// 全プラットフォーム共通: 5000px をベースとする
// ノードが端に近づいたら自動拡張するが、最大でもベースの 3 倍まで (15000px)
double get kCanvasBaseSize {
  return 5000.0;
}

/// ノードが端に近い場合にキャンバスを拡張する
double computeCanvasSize(Map<String, MindMapNode> nodes) {
  final base = kCanvasBaseSize;
  final maxAllowed = base * 3; // ベースの3倍が上限
  double maxExtent = base;
  for (final node in nodes.values) {
    // 端から800pxの余裕を持たせる
    final right = node.position.dx + node.width + 800;
    final bottom = node.position.dy + node.visualHeight + 800;
    if (right > maxExtent) maxExtent = right;
    if (bottom > maxExtent) maxExtent = bottom;
  }
  // 1000刻みで切り上げ（最大 base*3 まで）
  return ((maxExtent / 1000).ceil() * 1000).toDouble().clamp(base, maxAllowed);
}

/// アンカーへのスナップ判定距離
const double _kAnchorSnapDist = 28.0;

/// URL から「リスト全体の埋め込みを提案できる」再生リスト ID を返す。
/// Mix (RD…) / ウォッチリスト (WL) / 高評価 (LL) は /playlist ページが無く
/// 一覧を取得できないため null (= 単一動画として扱う)。
/// 埋め込みの選択ダイアログ (マップ側 / Windows ブラウズ側) で共用する。
String? _embeddablePlaylistIdOf(String url) {
  final m = RegExp(r'[?&]list=([a-zA-Z0-9_-]+)').firstMatch(url);
  final id = m?.group(1);
  if (id == null || id.startsWith('RD') || id == 'WL' || id == 'LL') {
    return null;
  }
  return id;
}

/// URL の再生リストが Mix (RD…) / ウォッチリスト (WL) / 高評価 (LL) の
/// 「/playlist ページが無く一覧を取得できない」 リストならその ID を返す。
/// この場合は「視聴中の動画のみ埋め込むか」 を確認するダイアログを出す
/// (= ユーザー要望: ミックスリストは取得できない旨を案内する)。
String? _unfetchableListIdOf(String url) {
  final m = RegExp(r'[?&]list=([a-zA-Z0-9_-]+)').firstMatch(url);
  final id = m?.group(1);
  if (id == null) return null;
  if (id.startsWith('RD') || id == 'WL' || id == 'LL') return id;
  return null;
}

/// watch URL から list= を除いた「単一動画 URL」 を作る。 再生位置
/// (t=/start=) は維持する。 動画 ID が取れなければ元の URL を返す。
String _stripListParamKeepTime(String url) {
  final id = NodeWidget.extractVideoId(url);
  if (id == null) return url;
  final t = RegExp(r'[?&](?:t|start)=([0-9hms]+)').firstMatch(url)?.group(1);
  return 'https://www.youtube.com/watch?v=$id${t != null ? '&t=$t' : ''}';
}

/// QR コード画像のバイト列から文字列をデコードする (= ユーザー要望: QR リーダー)。
/// 純 Dart 実装 (image + zxing2) なので Windows / Android 双方で動く。 画像デコード
/// と二値化は重いので、 呼び出し側は compute() で別 isolate 実行する。 QR が
/// 見つからなければ null を返す。
String? decodeQrFromImageBytes(Uint8List bytes) {
  try {
    final image = img.decodeImage(bytes);
    if (image == null) return null;
    final rgba = image.convert(numChannels: 4);
    final source = zx.RGBLuminanceSource(
      image.width,
      image.height,
      rgba.getBytes(order: img.ChannelOrder.abgr).buffer.asInt32List(),
    );
    final bitmap = zx.BinaryBitmap(zx.HybridBinarizer(source));
    final result = zx.QRCodeReader().decode(bitmap);
    final text = result.text;
    return (text.trim().isEmpty) ? null : text;
  } catch (_) {
    // NotFoundException / FormatException 等 = QR 未検出。
    return null;
  }
}

/// WebView 内の AI サイトへ、選択画像を個別の File として注入するための
/// 転送データを作る。重いファイル読み込みと base64 化は [compute] で行う。
List<Map<String, String>> _readAiImagePayloads(List<String> paths) {
  const mimeByExt = <String, String>{
    'png': 'image/png',
    'jpg': 'image/jpeg',
    'jpeg': 'image/jpeg',
    'gif': 'image/gif',
    'webp': 'image/webp',
    'bmp': 'image/bmp',
    'heic': 'image/heic',
    'heif': 'image/heif',
  };
  final result = <Map<String, String>>[];
  for (final path in paths) {
    try {
      final file = File(path);
      if (!file.existsSync()) continue;
      final dot = path.lastIndexOf('.');
      final ext = dot >= 0 ? path.substring(dot + 1).toLowerCase() : '';
      final mime = mimeByExt[ext];
      if (mime == null) continue;
      final bytes = file.readAsBytesSync();
      if (bytes.isEmpty) continue;
      result.add(<String, String>{
        'name': path.split(RegExp(r'[/\\]')).last,
        'mime': mime,
        'base64': base64Encode(bytes),
      });
    } catch (_) {}
  }
  return result;
}

