/// ページ種別ごとの色 (利用者が選んだアイコンにもこの色を使う)。
Color _pageIconColorOf(String? pageType) {
  switch (pageType) {
    case 'bookshelf':
      return const Color(0xFFFF7043);
    case 'paint':
      return const Color(0xFFEC407A);
    case 'document':
      return const Color(0xFF4FC3F7);
    case 'markdown':
      return const Color(0xFF5FD3B2);
    case 'videoEditor':
      return const Color(0xFFFF7043);
    default:
      return const Color(0xFF8B84FF);
  }
}

/// ページ種別ごとの既定アイコン (= ページ一覧と同じ絵)。
IconData pageTypeDefaultIcon(String? pageType, {bool active = false}) {
  switch (pageType) {
    case 'bookshelf':
      return Icons.shelves;
    case 'paint':
      return Icons.brush_rounded;
    case 'document':
      return Icons.article_rounded;
    case 'markdown':
      return Icons.polyline_rounded;
    case 'videoEditor':
      return Icons.movie_creation_rounded;
    default:
      return active ? Icons.map : Icons.map_outlined;
  }
}

/// ページ一覧と同じ見た目のアイコン (= ユーザー要望: 「別ページに送る」 でも
/// 種類ごとの絵と色に揃える)。 個別に選んだアイコンがあればそれを使う。
Widget pageListIcon(MindMapProvider provider, MindMapPage p,
    {double size = 18, bool active = false}) {
  final color = _pageIconColorOf(p.pageType);
  return Icon(
    pageIconFor(provider, p, pageTypeDefaultIcon(p.pageType, active: active)),
    size: size,
    color: active ? color : color.withValues(alpha: 0.75),
  );
}

/// このページに出すアイコン。 個別指定 → 種類の指定 → 元からの既定 の順。
IconData pageIconFor(MindMapProvider provider, MindMapPage p, IconData fallback) {
  final i = provider.pageIconIndexFor(p.id, p.pageType);
  if (i != null && i >= 0 && i < kPageIconChoices.length) {
    return kPageIconChoices[i];
  }
  return fallback;
}

class MindMapScreen extends StatefulWidget {
  const MindMapScreen({super.key});
  @override
  State<MindMapScreen> createState() => _MindMapScreenState();
}

/// 画面分割パネルの位置 (4 方向)。
/// - right: 画面右側に縦長パネル (= 既定、 PDF は縦スクロール)
/// - left:  画面左側に縦長パネル (= PDF は縦スクロール)
/// - top:   画面上側に横長パネル (= PDF は横スクロール / ページめくり)
/// - bottom: 画面下側に横長パネル (= PDF は横スクロール / ページめくり)
enum _SplitPosition { right, left, top, bottom }

enum _SplitIconFill { left, right, top, bottom }

Widget _splitPanelIcon(_SplitIconFill fill,
    {Color color = Colors.white, double size = 22}) {
  return SizedBox(
    width: size,
    height: size,
    child: CustomPaint(painter: _SplitPanelIconPainter(fill, color)),
  );
}

class _SplitPanelIconPainter extends CustomPainter {
  final _SplitIconFill fill;
  final Color color;
  const _SplitPanelIconPainter(this.fill, this.color);

  @override
  void paint(Canvas canvas, Size size) {
    final stroke = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = (size.shortestSide * 0.09).clamp(1.4, 2.2).toDouble()
      ..strokeCap = StrokeCap.round
      ..color = color;
    final fillPaint = Paint()
      ..style = PaintingStyle.fill
      ..color = color.withValues(alpha: 0.48);
    final rect = Offset.zero & size;
    final rrect = RRect.fromRectAndRadius(
      rect.deflate(stroke.strokeWidth),
      Radius.circular(size.shortestSide * 0.18),
    );

    canvas.save();
    canvas.clipRRect(rrect);
    final Rect active;
    switch (fill) {
      case _SplitIconFill.left:
        active = Rect.fromLTWH(0, 0, size.width / 2, size.height);
        break;
      case _SplitIconFill.right:
        active = Rect.fromLTWH(size.width / 2, 0, size.width / 2, size.height);
        break;
      case _SplitIconFill.top:
        active = Rect.fromLTWH(0, 0, size.width, size.height / 2);
        break;
      case _SplitIconFill.bottom:
        active = Rect.fromLTWH(0, size.height / 2, size.width, size.height / 2);
        break;
    }
    canvas.drawRect(active, fillPaint);
    canvas.restore();

    canvas.drawRRect(rrect, stroke);
    final inset = stroke.strokeWidth / 2;
    if (fill == _SplitIconFill.left || fill == _SplitIconFill.right) {
      canvas.drawLine(Offset(size.width / 2, inset),
          Offset(size.width / 2, size.height - inset), stroke);
    } else {
      canvas.drawLine(Offset(inset, size.height / 2),
          Offset(size.width - inset, size.height / 2), stroke);
    }
  }

  @override
  bool shouldRepaint(covariant _SplitPanelIconPainter oldDelegate) =>
      oldDelegate.fill != fill || oldDelegate.color != color;
}

/// 分割ボタンのツールチップ文言 (ユーザー要望)。
/// - モバイル: 左右ではなく「上分割 / 下分割」 と表示し、 Windows の
///   ショートカット (Ctrl+^ / Ctrl+\) は出さない。
/// - デスクトップ: 「左画面分割 / 右画面分割」。 既定のキー割り当ては
///   外したので、 キーは併記しない (= ユーザー要望)。
String _splitBtnTooltip(BuildContext context, bool left) {
  final desktop =
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
  final provider = context.read<MindMapProvider>();
  if (!desktop) return provider.t(left ? 've.splitUp' : 've.splitDown');
  // 既定のキー割り当ては左右とも外したので、 案内も出さない
  // (= ユーザー要望。 欲しい人はショートカット一覧で自分で決められる)。
  return provider.t(left ? 'tooltip.splitLeft' : 'tooltip.splitRight');
}

/// リッチテキストのツールバーを「白アイコン・白文字」 でラップする
/// (= ユーザー要望: ノード/メモ編集のフォントファミリー等のツールバー項目が
///  黒文字で全く読めない → 全て白字/白アイコンに)。
/// 仕組み:
///  - 通常ボタン (太字/取消線/色 等) の Icon 色 → config の base.iconTheme で白に。
///  - フォント名/サイズのドロップダウンのラベル文字は色指定が無く周囲の
///    DefaultTextStyle を継承するため、 DefaultTextStyle.merge で白に。
///  - ドロップダウンの「▾」 矢印 Icon は IconTheme.merge で白に。
///  - 展開されるポップアップメニュー (フォント一覧) は別ルートに描画されるため
///    この白指定は伝播せず、 明るい背景に黒文字のまま (読める) で問題なし。
Widget _whiteQuillSimpleToolbar(QuillController controller, {Key? key}) {
  // ★ ライトテーマ対策 ★ M3 の IconButton/ドロップダウンは前景色を
  //   colorScheme.onSurface(Variant) から解決するため、 アプリがライトテーマだと
  //   暗背景のツールバー上でも項目が黒く見えてしまう (= ユーザー報告: 文書の
  //   リッチテキスト項目が黒くて見えない)。 ツールバー専用に配色を白へ上書き
  //   して、 config の iconTheme・DefaultTextStyle・IconTheme と合わせて確実に
  //   白文字/白アイコンにする。
  return Builder(builder: (ctx) {
    final base = Theme.of(ctx);
    final provider = ctx.read<MindMapProvider>();
    return Theme(
      // ★ 背景も暗く固定 ★ QuillSimpleToolbar の背景は既定で Theme.canvasColor
      //   を使う (= simple_toolbar.dart)。 アプリがライトテーマだと canvasColor が
      //   白になり、 白アイコン/白文字が「白背景に白」 で全く見えなくなる
      //   (= ユーザー報告)。 canvasColor / surface を暗色に上書きし、 さらに config
      //   側でも color を明示してツールバー背景を確実に暗くする。
      data: base.copyWith(
        canvasColor: const Color(0xFF1E1E32),
        colorScheme: base.colorScheme.copyWith(
          onSurface: Colors.white,
          onSurfaceVariant: Colors.white,
          onPrimary: Colors.white,
          surface: const Color(0xFF1E1E32),
          // ── ドロップダウン (フォント/サイズ/「通常」 等) のメニュー背景も暗色に ──
          // = ユーザー報告: フォント・フォントサイズ・通常 の項目を押すと「白背景に
          //   白文字」 で全く見えない。 これらは MenuAnchor を使い、 M3 では既定で
          //   surfaceContainer を背景にするため、 surfaceContainer 系を暗色へ。
          surfaceContainer: const Color(0xFF1E1E32),
          surfaceContainerHigh: const Color(0xFF252535),
          surfaceContainerHighest: const Color(0xFF2A2A3E),
          surfaceContainerLow: const Color(0xFF1A1A2E),
          surfaceContainerLowest: const Color(0xFF141422),
        ),
        // MenuAnchor (フォント/サイズ/行高 ドロップダウン) の背景を暗色固定。
        menuTheme: const MenuThemeData(
          style: MenuStyle(
            backgroundColor: WidgetStatePropertyAll(Color(0xFF1E1E32)),
            surfaceTintColor: WidgetStatePropertyAll(Colors.transparent),
          ),
        ),
        // PopupMenu (見出しスタイル「通常」 等) の背景も暗色固定。
        popupMenuTheme: const PopupMenuThemeData(
          color: Color(0xFF1E1E32),
          surfaceTintColor: Colors.transparent,
          textStyle: TextStyle(color: Colors.white),
        ),
        iconTheme: const IconThemeData(color: Colors.white),
        textTheme: base.textTheme
            .apply(bodyColor: Colors.white, displayColor: Colors.white),
      ),
      child: DefaultTextStyle.merge(
        style: const TextStyle(color: Colors.white),
        child: IconTheme.merge(
          data: const IconThemeData(color: Colors.white),
          child: QuillSimpleToolbar(
            key: key,
            controller: controller,
            config: QuillSimpleToolbarConfig(
              // ── ツールバー背景を暗色に固定 (= ユーザー報告: 白背景に白アイコン/
              //    白文字で全く読めない) ──。 未指定だと Theme.canvasColor (ライト
              //    テーマで白) が使われるため、 ここで明示する。
              color: Color(0xFF1E1E32),
              // ── 左詰めでコンパクトに (= ユーザー要望: 項目をもっと詰めて) ──
              //   単一行モード (multiRowsDisplay:false) は内部で Row(spaceEvenly)
              //   を使うため、 幅に収まると項目が均等に散らばってしまい、
              //   どれだけ隙間設定を詰めても効かない。 Wrap で左詰めする
              //   複数行モードにし、 隙間ゼロ + 小さいアイコンで密に並べる。
              //   デスクトップの広い幅では 1 行に左詰め、 スマホでは詰まった
              //   まま最小限の段数で折り返す。
              multiRowsDisplay: true,
              // 区切り線も省いて更にコンパクトに。
              showDividers: false,
              // ── 左右の矢印ボタン (元に戻す/やり直し/インデント) を非表示に
              //    (= ユーザー要望: リッチテキストの左右の矢印が目障りなので消す)。
              //    ボタンが減って横幅も縮むため、 オーバーフロー時の左右スクロール
              //    矢印も出にくくなる。 ──
              showUndo: false,
              showRedo: false,
              showIndent: false,
              // ── 左揃え / 中央揃え / 右揃え を出す (= ユーザー要望) ──
              //   flutter_quill は既定でこの 3 つを出さないので明示する。
              //   両端揃えも一緒に付いてくる。
              showAlignmentButtons: true,
              showJustifyAlignment: false,
              // ── 項目の間隔を詰める (= ユーザー要望: リッチテキストの項目の
              //    隙間が広すぎる) ──
              //    既定はボタン間・セクション間ともに余裕を取っているので、
              //    最小限にして密に並べる。
              toolbarIconAlignment: WrapAlignment.start,
              toolbarSectionSpacing: 0,
              toolbarRunSpacing: 0,
              buttonOptions: QuillSimpleToolbarButtonOptions(
                base: QuillToolbarBaseButtonOptions(
                  // ── アイコンとタップ領域を小さくして詰める (= ユーザー要望:
                  //    リッチテキスト項目をもっとコンパクトに) ──
                  iconSize: 16,
                  iconButtonFactor: 1.35,
                  iconTheme: QuillIconTheme(
                    iconButtonUnselectedData: IconButtonData(
                      color: Colors.white,
                      visualDensity: VisualDensity.compact,
                      padding: EdgeInsets.zero,
                      constraints:
                          BoxConstraints(minWidth: 26, minHeight: 30),
                    ),
                    iconButtonSelectedData: IconButtonData(
                      color: Colors.white,
                      visualDensity: VisualDensity.compact,
                      padding: EdgeInsets.zero,
                      constraints:
                          BoxConstraints(minWidth: 26, minHeight: 30),
                    ),
                  ),
                ),
                // ── フォントサイズを「数値」 で選べるようにする (= ユーザー要望:
                //    既定の「小/大/特大 (でっかい)」 ラベルは分かりにくいので、
                //    具体的な数値 (pt) のプルダウンにする)。 値 '0' は size 属性を
                //    クリア (既定サイズに戻す)。 ──
                fontSize: QuillToolbarFontSizeButtonOptions(
                  items: <String, String>{
                    provider.t('richText.defaultSize'): '0',
                    '10': '10',
                    '12': '12',
                    '14': '14',
                    '16': '16',
                    '18': '18',
                    '20': '20',
                    '24': '24',
                    '28': '28',
                    '32': '32',
                    '40': '40',
                    '48': '48',
                    '64': '64',
                  },
                ),
              ),
            ),
          ),
        ),
      ),
    );
  });
}

/// webview の Web ページをホイール量だけスクロールさせる JS を返す。
/// 多くのサイトは document をスクロールすれば良いが、 ChatGPT / Gemini /
/// Claude / DeepSeek 等は本文を内側の overflow コンテナでスクロールするため
/// `window.scrollBy` では動かない (= ユーザー報告: AIチャット欄がマウスホイールで
/// スクロールできない)。 document が伸びない場合は、 ページ内で最も背の高い
/// スクロール可能要素を探して直接スクロールする。 見つけた要素は
/// `window.__mmScrollEl` にキャッシュして毎フレームの全走査を避ける。
/// トップレベル関数: _MindMapScreenState と _InAppViewerDialogState の両方から
/// 呼べるようにするため (= ビルドエラー対策)。
String _webWheelScrollJs(int dx, int dy) {
  return '''
(function(dx,dy){
  function tall(el){
    if(!el||el.nodeType!==1) return false;
    var o=window.getComputedStyle(el).overflowY;
    return (o==='auto'||o==='scroll'||o==='overlay') && el.scrollHeight>el.clientHeight+2;
  }
  var doc=document.scrollingElement||document.documentElement||document.body;
  if(doc && doc.scrollHeight>doc.clientHeight+2){ doc.scrollTop+=dy; doc.scrollLeft+=dx; return; }
  var t=window.__mmScrollEl;
  if(!t || !t.isConnected || !tall(t)){
    var best=null,bestH=0,all=document.querySelectorAll('body *');
    for(var i=0;i<all.length;i++){
      var el=all[i];
      if(tall(el)){ var h=el.scrollHeight-el.clientHeight; if(h>bestH){ bestH=h; best=el; } }
    }
    t=best; window.__mmScrollEl=t;
  }
  if(t){ t.scrollTop+=dy; t.scrollLeft+=dx; }
})($dx,$dy);
''';
}

bool _webJsTruthy(dynamic value) {
  if (value == true) return true;
  if (value is num) return value != 0;
  if (value is String) {
    final v = value.trim().toLowerCase();
    return v == 'true' || v == '"true"' || v == '1' || v == '"1"';
  }
  return false;
}

bool _isAiChatUrl(String url) {
  final lower = url.toLowerCase();
  return lower.contains('gemini.google.com') ||
      lower.contains('chatgpt.com') ||
      lower.contains('chat.openai.com') ||
      lower.contains('claude.ai') ||
      lower.contains('deepseek.com') ||
      lower.contains('grok.x.ai') ||
      lower.contains('grok.com') ||
      lower.contains('perplexity.ai') ||
      lower.contains('copilot.microsoft.com');
}

bool _isLikelyEmbeddedVideoUrl(String url) {
  final lower = url.toLowerCase();
  if (_isAiChatUrl(lower)) return false;
  return lower.contains('youtube.com') ||
      lower.contains('youtu.be') ||
      lower.contains('youtube-nocookie.com') ||
      lower.contains('vimeo.com') ||
      lower.contains('player.vimeo.com') ||
      lower.contains('nicovideo.jp') ||
      lower.contains('twitter.com') ||
      lower.contains('x.com/') ||
      lower.contains('bilibili.com') ||
      lower.contains('dailymotion.com') ||
      lower.contains('twitch.tv') ||
      lower.contains('tiktok.com') ||
      lower.contains('facebook.com') ||
      lower.contains('reddit.com') ||
      lower.endsWith('.mp4') ||
      lower.endsWith('.webm') ||
      lower.contains('.mp4?') ||
      lower.contains('.webm?');
}

String _webVideoPresenceJs() => r'''
(function(){
  function looksVideo(el){
    var s = '';
    try {
      s = ((el && (el.src || el.getAttribute('src') || el.title || el.name)) || '').toLowerCase();
    } catch(e) {}
    return s.indexOf('youtube.com') >= 0 ||
      s.indexOf('youtu.be') >= 0 ||
      s.indexOf('youtube-nocookie.com') >= 0 ||
      s.indexOf('vimeo.com') >= 0 ||
      s.indexOf('nicovideo.jp') >= 0 ||
      s.indexOf('bilibili.com') >= 0 ||
      s.indexOf('dailymotion.com') >= 0 ||
      s.indexOf('twitch.tv') >= 0 ||
      s.indexOf('tiktok.com') >= 0 ||
      s.indexOf('facebook.com') >= 0 ||
      s.indexOf('reddit.com') >= 0 ||
      s.indexOf('.mp4') >= 0 ||
      s.indexOf('.webm') >= 0;
  }
  function hasDoc(doc, depth){
    if(!doc || depth > 3) return false;
    try {
      if(doc.querySelector && doc.querySelector('video')) return true;
      var frames = doc.querySelectorAll ? doc.querySelectorAll('iframe,embed,object') : [];
      for(var i=0;i<frames.length;i++){
        var f = frames[i];
        if(looksVideo(f)) return true;
        try {
          var sub = f.contentDocument || (f.contentWindow && f.contentWindow.document);
          if(sub && hasDoc(sub, depth + 1)) return true;
        } catch(e) {}
      }
    } catch(e) {}
    return false;
  }
  return hasDoc(document, 0);
})();
''';

/// 画面分割パネルの動画を「パネルいっぱい」まで縦に伸ばす / 元に戻す JS。
///
/// = ユーザー要望: 「PC 版の YouTube 画面を分割すると上下の領域が余って
///   もったいないから縦に伸ばして欲しい」。
/// 分割パネルは細長い (幅は半分・高さは全画面) ため、 YouTube の通常
/// レイアウトだと 16:9 のプレーヤーが上の方に小さく乗り、 下にコメント欄が
/// 続くだけで縦が余る。 ON にすると、
///   ・マストヘッド / サイドバー / コメント / 概要欄などページ側の要素を隠し、
///   ・プレーヤーとその親をビューポート (100vw × 100vh) いっぱいに広げ、
///   ・`<video>` を object-fit: fill にして縦にも引き伸ばす
/// ことで、 パネル全面が動画になる。 OFF にすると注入した style を外して
/// 元の YouTube レイアウトに戻る (リロード不要)。
String _splitVideoFillJs(bool on) {
  if (!on) {
    return r'''
(function(){
  try {
    var s = document.getElementById('__MM_SPLIT_FILL__');
    if (s && s.parentNode) s.parentNode.removeChild(s);
    window.__MM_SPLIT_FILL_ON__ = false;
    if (window.__MM_SPLIT_FILL_TIMER__) {
      clearInterval(window.__MM_SPLIT_FILL_TIMER__);
      window.__MM_SPLIT_FILL_TIMER__ = null;
    }
    var vs = document.querySelectorAll('video');
    for (var i = 0; i < vs.length; i++) {
      try { vs[i].style.removeProperty('object-fit'); } catch(e){}
    }
  } catch(e){}
})();
''';
  }
  return r'''
(function(){
  var CSS = [
    'ytd-masthead, #masthead, #masthead-container, ytd-mini-guide-renderer,',
    'ytd-guide-renderer, #guide, tp-yt-app-drawer, #secondary, #secondary-inner,',
    '#related, ytd-watch-next-secondary-results-renderer, #comments,',
    'ytd-watch-metadata, #above-the-fold, #below, ytd-merch-shelf-renderer,',
    'footer, ytd-mealbar-promo-renderer { display: none !important; }',
    'html, body { overflow: hidden !important; background: #000 !important;',
    '  margin: 0 !important; padding: 0 !important;',
    '  height: 100% !important; width: 100% !important; }',
    '#page-manager { margin-top: 0 !important; padding-top: 0 !important; }',
    '#primary, #primary-inner, #player, #player-container-outer {',
    '  max-width: 100% !important; margin: 0 !important; padding: 0 !important; }',
    'ytd-player, #movie_player, #player-container, #player-container-inner,',
    '.html5-video-container {',
    '  width: 100vw !important; height: 100vh !important;',
    '  max-width: 100vw !important; max-height: 100vh !important;',
    '  position: fixed !important; top: 0 !important; left: 0 !important;',
    '  overflow: hidden !important; }',
    'video, .html5-main-video {',
    '  width: 100vw !important; height: 100vh !important;',
    '  max-width: 100vw !important; max-height: 100vh !important;',
    '  object-fit: fill !important;',
    '  position: fixed !important; top: 0 !important; left: 0 !important;',
    '  margin: 0 !important; transform: none !important; }',
    '.ytp-chrome-bottom, .ytp-chrome-controls, .ytp-gradient-bottom {',
    '  opacity: 1 !important; pointer-events: auto !important;',
    '  z-index: 2147483646 !important; }'
  ].join('\n');
  function apply(){
    try {
      var s = document.getElementById('__MM_SPLIT_FILL__');
      if (!s) {
        s = document.createElement('style');
        s.id = '__MM_SPLIT_FILL__';
        (document.head || document.documentElement).appendChild(s);
      }
      if (s.textContent !== CSS) s.textContent = CSS;
      // YouTube はインラインスタイルで video のサイズを書き戻すので上書きし続ける。
      var vs = document.querySelectorAll('video');
      for (var i = 0; i < vs.length; i++) {
        vs[i].style.setProperty('object-fit', 'fill', 'important');
        vs[i].style.setProperty('width', '100vw', 'important');
        vs[i].style.setProperty('height', '100vh', 'important');
      }
    } catch(e){}
  }
  window.__MM_SPLIT_FILL_ON__ = true;
  apply();
  if (!window.__MM_SPLIT_FILL_TIMER__) {
    window.__MM_SPLIT_FILL_TIMER__ = setInterval(function(){
      if (window.__MM_SPLIT_FILL_ON__) apply();
    }, 600);
  }
})();
''';
}

/// 音楽サイト (SoundCloud / Spotify 等) を裏に回っても止めない JS
/// (= ユーザー要望: バックグラウンド再生)。
///
/// 仕組み: ページは `visibilitychange` / `blur` を見て自分で一時停止する
/// ことがあるので、
///   1) document.hidden / visibilityState を常に「表示中」 と答えさせる
///   2) それらのイベントを握りつぶす
///   3) 念のため、 勝手に止まった `<audio>/<video>` を鳴らし直す
/// の 3 つを行う。 ユーザーが自分で押した一時停止は尊重する
/// (= 直前に再生中だった要素だけを鳴らし直す)。
const String _kWebAudioKeepAliveJs = r'''
(function(){
  if (window.__mmAudioKeepAlive) return;
  window.__mmAudioKeepAlive = true;
  try {
    // 1) 「隠れていない」 ことにする
    Object.defineProperty(document, 'hidden',
        {configurable: true, get: function(){ return false; }});
    Object.defineProperty(document, 'visibilityState',
        {configurable: true, get: function(){ return 'visible'; }});
    Object.defineProperty(document, 'webkitHidden',
        {configurable: true, get: function(){ return false; }});
  } catch(e) {}
  // 2) 停止のきっかけになるイベントを止める
  ['visibilitychange','webkitvisibilitychange','blur','pagehide','freeze']
      .forEach(function(t){
    window.addEventListener(t, function(ev){
      ev.stopImmediatePropagation();
    }, true);
    document.addEventListener(t, function(ev){
      ev.stopImmediatePropagation();
    }, true);
  });
  // 3) 勝手に止まったら鳴らし直す (利用者の一時停止は尊重)
  function media(){
    try {
      return [].slice.call(document.querySelectorAll('audio,video'));
    } catch(e) { return []; }
  }
  media().forEach(function(m){
    if (m.__mmHooked) return;
    m.__mmHooked = true;
    m.addEventListener('play', function(){ m.__mmWanted = true; });
    m.addEventListener('pause', function(){
      // 利用者操作なら __mmUserPause が直前に立つ
      if (!m.__mmUserPause) {
        setTimeout(function(){
          try { if (m.__mmWanted && m.paused) m.play(); } catch(e){}
        }, 200);
      }
      m.__mmUserPause = false;
    });
  });
  document.addEventListener('click', function(){
    media().forEach(function(m){ m.__mmUserPause = true; });
  }, true);
  document.addEventListener('keydown', function(){
    media().forEach(function(m){ m.__mmUserPause = true; });
  }, true);
  if (window.__mmAudioTimer) clearInterval(window.__mmAudioTimer);
  window.__mmAudioTimer = setInterval(function(){
    media().forEach(function(m){
      if (m.__mmHooked) return;
      m.__mmHooked = true;
      m.addEventListener('play', function(){ m.__mmWanted = true; });
      m.addEventListener('pause', function(){
        if (!m.__mmUserPause) {
          setTimeout(function(){
            try { if (m.__mmWanted && m.paused) m.play(); } catch(e){}
          }, 200);
        }
        m.__mmUserPause = false;
      });
    });
  }, 2000);
})();
''';

/// 「今選んでいるモデルで、 あとどれだけ使えるか」 の表示文。
///
/// = ユーザー要望「Dev モードは 200 ドルではなく、 実際にそのモデルの残り
///   使用可能なトークン量や金額を表示して欲しい」。 枠の上限は使う側に
///   とって意味が薄いので出さず、 単価がモデルごとに違うことが分かるよう
///   モデル名と入力 / 出力それぞれの残りトークン、 残額を出す。
/// AI チャットと AI 編集の両方から使う (表示を揃えるため 1 か所にまとめた)。
String aiRemainText(MindMapProvider provider) {
  double inRate = 0, outRate = 0;
  for (final m in provider.relayModels) {
    if (m is Map && '${m['id']}' == provider.relayModel) {
      inRate = (m['billedInputPerMTok'] as num?)?.toDouble() ?? 0;
      outRate = (m['billedOutputPerMTok'] as num?)?.toDouble() ?? 0;
    }
  }
  String tokAt(double usd, double perM) {
    if (perM <= 0) return '-';
    final t = usd / perM * 1e6;
    if (t >= 1e6) return '${(t / 1e6).toStringAsFixed(1)}M';
    if (t >= 1e3) return '${(t / 1e3).toStringAsFixed(0)}k';
    return t.toStringAsFixed(0);
  }

  // モデル名は同じ行の左側 (モデル選択ボタン) に出ているので、 ここでは
  // 繰り返さない (= ユーザー要望: 右に書く必要は無いので消して、 残り
  // トークン数が切れずに収まるように)。
  if (provider.isDevPlan) {
    final left = provider.devRemainingUsd;
    final usd = '\$${left.toStringAsFixed(2)}';
    if (inRate <= 0 && outRate <= 0) {
      // モデルの単価がまだ届いていない → 金額だけ。
      return provider.t('credit.devRemainUsd').replaceFirst('{usd}', usd);
    }
    return provider
        .t('credit.devRemainIo')
        .replaceFirst('{in}', tokAt(left, inRate))
        .replaceFirst('{out}', tokAt(left, outRate))
        .replaceFirst('{usd}', usd);
  }
  final bal = provider.creditBalanceUsd;
  if (bal <= 0) return provider.t('credit.insufficient');
  if (outRate <= 0) return ''; // まだモデル一覧が届いていない等
  return provider.t('mcp.remain').replaceFirst('{out}', tokAt(bal, outRate));
}


/// 選んでいるタブの中身の高さに合わせて縮む TabBarView
/// (= ユーザー要望: 余白があるなら伸ばして全部入れ、 短い側では間延びさせない)。
///
/// 素の TabBarView は必ず親いっぱいに広がるので、 短いタブでも下に大きな
/// 余白が出てしまう。 選択中の子だけを高さの基準にし、 他は畳んでおく。
class _AutoHeightTabBarView extends StatefulWidget {
  final List<Widget> children;
  const _AutoHeightTabBarView({required this.children});
  @override
  State<_AutoHeightTabBarView> createState() => _AutoHeightTabBarViewState();
}

class _AutoHeightTabBarViewState extends State<_AutoHeightTabBarView> {
  TabController? _ctrl;

  void _onTab() {
    if (mounted) setState(() {});
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final c = DefaultTabController.of(context);
    if (identical(c, _ctrl)) return;
    _ctrl?.removeListener(_onTab);
    _ctrl = c..addListener(_onTab);
  }

  @override
  void dispose() {
    _ctrl?.removeListener(_onTab);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final i = _ctrl?.index ?? 0;
    return Stack(children: [
      for (var k = 0; k < widget.children.length; k++)
        // 選んでいる物だけが高さを決める。 他は畳む (状態は保つ)。
        Offstage(
          offstage: k != i,
          child: TickerMode(
            enabled: k == i,
            child: k == i
                ? widget.children[k]
                : const SizedBox(width: double.infinity),
          ),
        ),
    ]);
  }
}

