/// 「今選んでいるモデル」 の小さなボタン。 押すと上の画面が出る。

/// AI の返事に紛れ込んだ「ツール実行結果: …」 の写しを取り除く。
///
/// = ユーザー要望「ツール実行結果のごちゃごちゃした物は応答として返さない
///   ようにして欲しい」。 会話の履歴は
///   `ツール実行結果: read_page → {…}` という形で AI へ渡しているので、
///   モデルがその書き方を真似て、 最後の返事の頭に戻り値の JSON をそのまま
///   貼り付けてくることがある。 人には読めない上に長いだけなので、 画面へ
///   出す前に落とす。
String stripToolEchoFromReply(String reply) {
  final marker = RegExp(
      r'^\s*(?:ツール実行結果|ツールの実行結果|ツール結果|実行結果'
      r'|Tool\s*result|tool_result|Result)\s*[:：]',
      caseSensitive: false);
  // 直前の行の続き (JSON の折り返しや `名前 → {…}` の形) かどうか。
  final continued = RegExp(r'^\s*(?:[\[\]{}",]|[\w.-]+\s*(?:→|->)\s*[\[{])');
  // 説明が一切無く、 JSON の塊だけを返してきた行。
  final wholeJson = RegExp(r'^\s*[\[{].*[\]}]\s*$');
  // 履歴の見出し (「アシスタント:」) も返事には要らない。
  final speaker = RegExp(r'^\s*(?:アシスタント|Assistant)\s*[:：]\s*');
  final out = <String>[];
  var skipping = false;
  for (final line in reply.split('\n')) {
    if (marker.hasMatch(line)) {
      skipping = true;
      continue;
    }
    if (skipping) {
      if (line.trim().isEmpty) {
        skipping = false;
        continue;
      }
      if (continued.hasMatch(line)) continue;
      skipping = false;
    }
    out.add(line.replaceFirst(speaker, ''));
  }
  final lines = out.join('\n').trim().split('\n');
  // 本文が残る時だけ、 頭に居座った生 JSON の行も落とす。
  while (lines.length > 1 &&
      (lines.first.trim().isEmpty || wholeJson.hasMatch(lines.first))) {
    lines.removeAt(0);
  }
  final cleaned = lines.join('\n').trim();
  return cleaned.isEmpty ? reply.trim() : cleaned;
}

/// アプリが自動インストールした ffmpeg/ffprobe を置くフォルダー。
Future<Directory> ffmpegInstallDir() async {
  final base = await getApplicationSupportDirectory();
  final dir = Directory('${base.path}${Platform.pathSeparator}ffmpeg_bin');
  if (!await dir.exists()) await dir.create(recursive: true);
  return dir;
}

/// ffmpeg の実体を探す (アプリ専用フォルダー → PATH → 定番の場所)。
///
/// ビデオエディターだけでなく、 ヘッダーの画面録画ボタンからも使うので
/// 画面の外に置いてある。
Future<String?> findFfmpegExe() async {
  if (Platform.isWindows) {
    try {
      final dir = await ffmpegInstallDir();
      final p = '${dir.path}${Platform.pathSeparator}ffmpeg.exe';
      if (await File(p).exists()) return p;
    } catch (_) {}
  }
  for (final c in ['ffmpeg', 'ffmpeg.exe']) {
    try {
      final r = await Process.run(c, ['-version']);
      if (r.exitCode == 0) return c;
    } catch (_) {}
  }
  if (Platform.isWindows) {
    for (final p in [
      r'C:\ffmpeg\bin\ffmpeg.exe',
      r'C:\Program Files\ffmpeg\bin\ffmpeg.exe',
    ]) {
      try {
        if (await File(p).exists()) return p;
      } catch (_) {}
    }
  }
  return null;
}

/// 動画の再生速度を WebView 内へ流し込む JS。
/// 外の窓 (main.dart の `_FloatingWebWindowApp`) からも使うので公開。
String webVideoRateJs(double rawRate) {
  final rate = rawRate.clamp(0.25, 16.0).toDouble().toStringAsFixed(3);
  return '''
(function(rate){
  try {
    window.__mmVideoRate = rate;
    function currentRate(){
      return Number(window.__mmVideoRate || rate) || rate;
    }
    function setVideo(v){
      try {
        var r = currentRate();
        v.playbackRate = r;
        if ('defaultPlaybackRate' in v) v.defaultPlaybackRate = r;
        if (!v.__mmRateHooked) {
          v.__mmRateHooked = true;
          v.addEventListener('ratechange', function(){
            var rr = currentRate();
            if (Math.abs((v.playbackRate || 1) - rr) > 0.02) {
              setTimeout(function(){ try { v.playbackRate = rr; } catch(e) {} }, 0);
            }
          }, true);
        }
      } catch(e) {}
    }
    function postToFrame(f){
      try {
        if (!f || !f.contentWindow) return;
        var src = ((f.src || f.getAttribute('src') || '') + '').toLowerCase();
        var r = currentRate();
        if (src.indexOf('youtube.com') >= 0 ||
            src.indexOf('youtu.be') >= 0 ||
            src.indexOf('youtube-nocookie.com') >= 0) {
          f.contentWindow.postMessage(JSON.stringify({
            event: 'command',
            func: 'setPlaybackRate',
            args: [r]
          }), '*');
        }
        if (src.indexOf('vimeo.com') >= 0 || src.indexOf('player.vimeo.com') >= 0) {
          f.contentWindow.postMessage(JSON.stringify({
            method: 'setPlaybackRate',
            value: r
          }), '*');
          f.contentWindow.postMessage({method: 'setPlaybackRate', value: r}, '*');
        }
      } catch(e) {}
    }
    function applyDoc(doc, depth){
      if (!doc || depth > 3) return;
      try {
        var videos = doc.querySelectorAll ? doc.querySelectorAll('video') : [];
        for (var i = 0; i < videos.length; i++) setVideo(videos[i]);
        var frames = doc.querySelectorAll ? doc.querySelectorAll('iframe') : [];
        for (var j = 0; j < frames.length; j++) {
          var f = frames[j];
          postToFrame(f);
          try {
            var sub = f.contentDocument || (f.contentWindow && f.contentWindow.document);
            if (sub) applyDoc(sub, depth + 1);
          } catch(e) {}
        }
      } catch(e) {}
    }
    function apply(){ applyDoc(document, 0); }
    apply();
    if (window.__mmVideoRateTimer) clearInterval(window.__mmVideoRateTimer);
    window.__mmVideoRateTimer = setInterval(apply, 1000);
  } catch(e) {}
})($rate);
''';
}

/// 画面分割パネルのリサイズハンドル widget。
/// 視覚的に「掴める」 ように hover で色が変わり、 中央に「⋮ / ⋯」 の
/// しるしを表示する。 hit test 領域は太め (12px) で確実に掴める。
class _ResizeHandle extends StatefulWidget {
  final _SplitPosition splitPosition;
  final ValueChanged<DragUpdateDetails> onHorizontalDrag;
  final ValueChanged<DragUpdateDetails> onVerticalDrag;
  const _ResizeHandle({
    required this.splitPosition,
    required this.onHorizontalDrag,
    required this.onVerticalDrag,
  });
  @override
  State<_ResizeHandle> createState() => _ResizeHandleState();
}

class _ResizeHandleState extends State<_ResizeHandle> {
  bool _hovering = false;
  bool _dragging = false;

  @override
  Widget build(BuildContext context) {
    final pos = widget.splitPosition;
    final isVertical =
        pos == _SplitPosition.top || pos == _SplitPosition.bottom;
    // active 時は紫色で「掴んでいる」 ことを示す。
    final isActive = _hovering || _dragging;
    // ── Positioned の設定 ──
    // 縦バー (右/左分割) は parent の高さいっぱい (top:0, bottom:0)、 幅 12
    // 横バー (上/下分割) は parent の幅いっぱい (left:0, right:0)、 高さ 12
    return Positioned(
      left: isVertical ? 0 : (pos == _SplitPosition.right ? 0 : null),
      right: isVertical ? 0 : (pos == _SplitPosition.left ? 0 : null),
      top: isVertical ? (pos == _SplitPosition.bottom ? 0 : null) : 0,
      bottom: isVertical ? (pos == _SplitPosition.top ? 0 : null) : 0,
      width: isVertical ? null : 12,
      height: isVertical ? 12 : null,
      child: MouseRegion(
        cursor: isVertical
            ? SystemMouseCursors.resizeUpDown
            : SystemMouseCursors.resizeLeftRight,
        onEnter: (_) => setState(() => _hovering = true),
        onExit: (_) => setState(() => _hovering = false),
        child: GestureDetector(
          behavior: HitTestBehavior.translucent,
          onHorizontalDragStart:
              isVertical ? null : (_) => setState(() => _dragging = true),
          onHorizontalDragEnd:
              isVertical ? null : (_) => setState(() => _dragging = false),
          onHorizontalDragUpdate: isVertical ? null : widget.onHorizontalDrag,
          onVerticalDragStart:
              isVertical ? (_) => setState(() => _dragging = true) : null,
          onVerticalDragEnd:
              isVertical ? (_) => setState(() => _dragging = false) : null,
          onVerticalDragUpdate: isVertical ? widget.onVerticalDrag : null,
          child: Stack(
            children: [
              // 背景 (= 領域全体)
              Positioned.fill(
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 120),
                  color: isActive
                      ? const Color(0xFF6C63FF).withValues(alpha: 0.35)
                      : Colors.white.withValues(alpha: 0.04),
                ),
              ),
              // 中央の「掴むしるし」 (= バーの中央に縦/横の細い線)
              Center(
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 120),
                  width: isVertical ? 40 : 3,
                  height: isVertical ? 3 : 40,
                  decoration: BoxDecoration(
                    color: isActive
                        ? const Color(0xFF6C63FF)
                        : Colors.white.withValues(alpha: 0.35),
                    borderRadius: BorderRadius.circular(2),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

/// 動的に作られるブックマークボタン (= Google 検索の ★ ボタンで作成)。
/// 旧 customPage1〜5 の事前定義スロットに代わる仕組み。
///
/// ID 形式は 'bookmark:<32 文字 hex>' (= 既存の customPage* と衝突しない)。
/// SharedPreferences の 'mokumoku_bookmark_buttons_v1' に List<JSON> 形式で
/// 永続化される。 ヘッダー / 下部バーへの配置は既存の customHeaderButtons /
/// customBottomButtons の文字列 ID リストに直接 'bookmark:xxx' を入れる。
class _BookmarkButton {
  final String id;
  final String url;
  final String label;
  final int iconCodePoint;
  final int colorValue;
  final int createdAt;

  const _BookmarkButton({
    required this.id,
    required this.url,
    required this.label,
    required this.iconCodePoint,
    required this.colorValue,
    required this.createdAt,
  });

  /// 動的 IconData の生成は Flutter の tree-shake-icons (= release ビルド
  /// 時の未使用アイコン除去) と相性が悪く、 build apk で
  /// "Avoid non-constant invocations of IconData" エラーが出る。
  /// そこで、 ピッカーで使う静的リスト `_MindMapScreenState
  /// ._availableBookmarkIcons` から codePoint 一致のものを引いて返す。
  /// 一致しない (= 旧データなど) 場合はデフォルトの bookmark を返す。
  IconData get icon {
    for (final c in _MindMapScreenState._availableBookmarkIcons) {
      if (c.codePoint == iconCodePoint) return c;
    }
    return Icons.bookmark_rounded;
  }

  Color get color => Color(colorValue);

  Map<String, dynamic> toJson() => {
        'id': id,
        'url': url,
        'label': label,
        'icon': iconCodePoint,
        'color': colorValue,
        'createdAt': createdAt,
      };

  static _BookmarkButton? fromJson(Object? raw) {
    if (raw is! Map) return null;
    final id = raw['id'];
    final url = raw['url'];
    final label = raw['label'];
    final icon = raw['icon'];
    final color = raw['color'];
    final createdAt = raw['createdAt'];
    if (id is! String ||
        url is! String ||
        label is! String ||
        icon is! int ||
        color is! int) {
      return null;
    }
    return _BookmarkButton(
      id: id,
      url: url,
      label: label,
      iconCodePoint: icon,
      colorValue: color,
      createdAt:
          createdAt is int ? createdAt : DateTime.now().millisecondsSinceEpoch,
    );
  }

  _BookmarkButton copyWith({
    String? label,
    int? iconCodePoint,
    int? colorValue,
    String? url,
  }) =>
      _BookmarkButton(
        id: id,
        url: url ?? this.url,
        label: label ?? this.label,
        iconCodePoint: iconCodePoint ?? this.iconCodePoint,
        colorValue: colorValue ?? this.colorValue,
        createdAt: createdAt,
      );
}

/// URL の「# から後ろ」 を落として比べる (= DeepL のように打つたびに
/// # が変わるサイトで、 画面を作り直さないため)。
String _urlWithoutFragment(String u) {
  final i = u.indexOf('#');
  return i < 0 ? u : u.substring(0, i);
}

class _MindMapScreenState extends State<MindMapScreen>
    with WidgetsBindingObserver {
  final Map<String, TransformationController> _controllers = {};
  // タイムラインで予定の通知を仕掛けた済みの ID 集合 (= 重複防止)。
  //   key = 'cal_${event.id}_$dateKey'。
  final Set<String> _scheduledNotifications = <String>{};
  // キーボードショートカット用フォーカスノード
  final FocusNode _keyboardFocusNode = FocusNode();
  // Scaffold を外部から操作するためのキー（ドロワー開閉など）
  final GlobalKey<ScaffoldState> _scaffoldKey = GlobalKey<ScaffoldState>();
  // InteractiveViewer 自体ではなく、その内側の Stack に付ける
  final GlobalKey _canvasKey = GlobalKey();
  // Scaffold body 直下の Stack に付けるキー。 図形選択ツールバーを「図形の
  // 真上」 に重ねる際、 キャンバス座標 → グローバル座標 → この Stack の
  // ローカル座標へ変換するために使う (ユーザー要望)。
  final GlobalKey _bodyStackKey = GlobalKey();
  // 分割表示を除いた、実際のマップ表示領域。ホイール移動とスクロールバーの
  // クランプ計算を全画面サイズではなく現在のビューポートに合わせるために使う。
  final GlobalKey _mapViewportKey = GlobalKey();

  /// ミニマップ (右上の縮図) を出すか (= ユーザー要望: マップ上のどこに
  /// いるのか分かりにくいので、 全体と現在位置を縮図で見たい)。
  bool _miniMapOpen = true;
  static const String _kMiniMapPrefsKey = 'miniMapOpen';

  Future<void> _loadMiniMapPref() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final v = prefs.getBool(_kMiniMapPrefsKey);
      if (v != null && mounted) setState(() => _miniMapOpen = v);
    } catch (_) {}
  }

  Future<void> _toggleMiniMap() async {
    setState(() => _miniMapOpen = !_miniMapOpen);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool(_kMiniMapPrefsKey, _miniMapOpen);
    } catch (_) {}
  }

  // moveMode（長押し後の移動モード）
  String? _moveModeNodeId;
  Offset? _movingPos;
  Offset? _moveDragAnchor;
  int? _movingPointerId;

  // ギャラリーでドラッグ中、 入れ替わる先としてハイライトする要素 id
  //   (= ユーザー要望: どこと入れ替わるか枠で分かるように)。
  String? _shelfSwapTargetId;

  // スナップ情報
  SnapTarget? _currentSnap;

  // アクションOverlay
  String? _actionNodeId;
  OverlayEntry? _overlayEntry;

  /// 現在出ているオーバーレイが「複数選択の一括操作バー」 かどうか。
  /// = ユーザー要望: 要素を削除しても範囲選択のボタンが他の箇所を押すまで
  ///   残り続けるので、 選択が空になったら同時に消すための判定に使う。
  bool _overlayIsMultiSelect = false;

  // Bookshelf inline text editor for newly added text tiles.
  String? _inlineShelfEditNodeId;
  bool _inlineShelfDeleteWhenEmpty = false;
  final TextEditingController _inlineShelfEditCtrl = TextEditingController();
  final FocusNode _inlineShelfEditFocus =
      FocusNode(debugLabel: 'bookshelfInlineText');
  String? _inlineNodeEditNodeId;
  bool _inlineNodeDeleteWhenEmpty = false;
  bool _inlineNodeAllowDelimiterExpansion = false;
  final TextEditingController _inlineNodeEditCtrl = TextEditingController();
  final FocusNode _inlineNodeEditFocus =
      FocusNode(debugLabel: 'nodeInlineText');

  /// 表ノードなど、[NodeWidget] 内部で直接編集しているノード。
  /// 通常/ギャラリーのインライン編集 ID と合わせて、モバイルのキーボード表示時に
  /// 編集対象を自動で見える位置へ移動するために使う。
  String? _nestedInlineEditNodeId;
  Timer? _inlineEditorRevealTimer;
  bool _applyingInlineEditorRevealTransform = false;

  // ─── 装飾図形 (= 直線/矢印/長方形/楕円) の挿入・選択 State ─────────────
  //
  // ユーザー要望「直線や矢印線、 長方形等の図形を挿入できるようにして」 への
  // 対応で導入。
  //
  // - _drawingDecorationKind: 図形挿入モード中の挿入種別 (null = 通常モード)
  //   ヘッダーの「図形を挿入」 ボタン → モーダルで種類を選ぶ → ここにセット。
  //   ユーザーがマップをドラッグすると start/end が更新され、 ドラッグ終了で
  //   provider に追加して終了 (kind を null に戻す)。
  // - _drawingDecorationStart / End: ドラッグ中の始点・終点 (マップ座標)
  // - _selectedDecorationId: タップで選択された装飾の ID (= 削除候補)
  MapDecorationKind? _drawingDecorationKindRaw;

  /// 今描こうとしている図形の種類。 null なら図形の挿入モードではない。
  ///
  /// ★ 図形の挿入と範囲選択は同時に使えない (= ユーザー要望: どちらか
  ///   しかできないように)。 代入をここで受けて、 図形モードに入ったら
  ///   範囲選択を必ず抜ける。 代入箇所が散らばっているので、 素の変数では
  ///   なく setter で一元的に面倒を見る。
  MapDecorationKind? get _drawingDecorationKind => _drawingDecorationKindRaw;
  set _drawingDecorationKind(MapDecorationKind? v) {
    _drawingDecorationKindRaw = v;
    if (v != null && _rangeSelectModeRaw) {
      _rangeSelectModeRaw = false;
      _rangeSelectedIds.clear();
      _rangeSelectedDecorationIds.clear();
      _rangeStart = null;
      _rangeEnd = null;
      // 一括操作バーは次のフレームで _dismissMultiSelectOverlayIfEmpty が
      // 閉じる。 ここで _removeOverlay() を呼ぶと setState の入れ子になる。
    }
