  Offset? _pendingTapCanvasPos;
  // 挿入する図形の色 (RGB 24bit) と線の太さ。 挿入モードのツールバーで変更でき、
  // 新規図形に適用される。 既存図形を選択中はその図形の編集にも使う。
  int _shapeColorRgb = 0xF44336; // 既定: 赤 (暗いマップ上でも視認しやすい)
  double _shapeStrokeWidth = 3.0;
  // 図形の挿入用パレット (色)。
  static const List<int> _shapePalette = [
    0xF44336, // 赤
    0xE91E63, // ピンク
    0xFF9800, // オレンジ
    // 黄 (0xFFEB3B) / 黄緑 (0xCDDC39) は外した (= ユーザー要望: 黄色は
    // 背景色にすると読みにくいので出さない)。
    0x4CAF50, // 緑
    0x009688, // 青緑
    0x00BCD4, // シアン
    0x2196F3, // 青
    0x3F51B5, // 藍
    0x9C27B0, // 紫
    0x795548, // 茶
    0x9E9E9E, // 灰
    0x000000, // 黒
    0xFFFFFF, // 白
  ];

  // ─── サブマップ埋め込みナビゲーション履歴 ─────────────────────────────────
  //
  // ノードに埋め込まれたサブマップを開くと、 現在のページ ID を `_navHistory`
