  /// SnackBar が閉じるか別の操作が来るとクリア。
  List<({String nodeId, String suggestedTitle})>? _pendingAutofillSuggestions;

  /// 連番オートフィル SnackBar の表示開始時刻。 タイトル保存時の Enter が
  /// 続けて Snackbar の Enter として誤発火するのを防ぐため、 表示直後 300ms
  /// 以内の Enter は無視する。
  DateTime? _pendingAutofillShownAt;

  // ── ノード検索
  bool _searchVisible = false;
  bool _searchReplaceExpanded = false;
  String _searchQuery = '';
  List<String> _searchResultIds = [];
  int _searchResultIndex = 0;
  final TextEditingController _searchCtrl = TextEditingController();
  final TextEditingController _replaceCtrl = TextEditingController();
  final FocusNode _searchFocusNode = FocusNode();
  final FocusNode _replaceFocusNode = FocusNode();

  // 選択中の接続（複数選択対応）
  final Set<NodeConnection> _selectedConnections = {};
  NodeConnection? _draggingConnectionBend;
  int? _draggingConnectionBendIndex;
  final Set<({String fromId, String toId, int index})>
      _selectedConnectionBends = {};
  bool _connectionBendPointerActive = false;
  Offset? _connectionBendDragStart;
  Map<NodeConnection, List<Offset>> _connectionBendDragInitialPoints = {};
  bool _connectionBendDragHistoryRecorded = false;
  bool _connectionBendDragMoved = false;
  ({String fromId, String toId, int index})? _pendingConnectionBendToggleOff;
  NodeConnection? _draggingConnectionLabel;
  bool _suppressConnectionTapAfterBendDrag = false;

  // ── フローティングツール (計算機 / ストップウォッチ) ──
  /// それぞれ 1 つだけ表示。二度目の Ctrl+M は無視（既に開いていれば前面に）
  OverlayEntry? _calculatorOverlay;
  OverlayEntry? _stopwatchOverlay;

  /// 高度な関数電卓 (Ctrl+Shift+M)
  OverlayEntry? _sciCalcOverlay;

  /// ポモドーロタイマー (Ctrl+P)
  OverlayEntry? _pomodoroOverlay;

  /// 天気予報 (カスタム項目から起動)
  OverlayEntry? _weatherOverlay;

  /// 集中ロック (Android のみ。設定した時間だけ全画面ロック)
  OverlayEntry? _focusLockOverlay;

  // LAN 共有 (_lanShareServer / _lastLanShareImportUrlKey) は廃止
  //   (= ユーザー要望: リアルタイム共同編集があるので不要)。

  /// アプリ外脱出ロック (Android のみ。タイマー無しのトグル式)。
  /// カスタムボタン 'appLock' で ON/OFF する。ON の間は OS の画面固定
  ///   (startLockTask) で他アプリ/ホームへ抜けられないようにし、復帰時に
  ///   再ロックする (= ユーザー要望)。
  bool _appExitLocked = false;

  /// アプリ外脱出ロックの自動解除タイマー (null = 無制限)。
  Timer? _appExitLockTimer;

  /// アプリ外脱出ロックの自動解除予定時刻 (null = 無制限/未設定)。
  /// UI に「残り時間」 を表示するために使う。
  DateTime? _appExitLockEndAt;

  /// 予定から自動開始したアプリ外脱出ロックか。
  bool _appExitLockByEvent = false;

  /// 今の予定枠で一度ユーザーが解除したら、同じ枠では再固定しない。
  bool _appExitLockEventDismissed = false;

  /// 現在のロックがスケジュール (時刻指定) 起動か。
  bool _focusLockBySchedule = false;

  /// 今の時間枠で一度ユーザーが解除したら、 同じ枠では再ロックしない。
  bool _focusLockScheduleDismissed = false;

  /// スケジュール判定用の定期タイマー。
  Timer? _focusLockScheduleTimer;

  // ── ジオフェンス画面ロック (= 確定地点から半径 N km の出入りでロック) ──
  /// 位置を定期チェックするタイマー。
  Timer? _geofenceTimer;

  /// 直近の「半径内にいたか」 (= エッジ検出用、 初回 null)。
  bool? _geofenceWasInside;

  /// 位置取得中フラグ (= GPS 取得の多重起動を防ぐ)。
  bool _geofenceChecking = false;

  // ── フローティングツールを一時的に裏に隠すための状態 ───────────────────
  // 計算機/ストップウォッチ/関数電卓/ポモドーロ/天気の OverlayEntry は
  // ルート Overlay に挿入されており、本来 Drawer や PopupMenu、カレンダー
  // モードよりも上に描画される。ユーザーから「これらの UI が見えるようにして」
  // 要望があったので、対応する UI が表に出ている間は Offstage で **裏に
  // 隠して非インタラクティブ** にする。Offstage は widget tree から外さない
  // ので、Tick の State (タイマー残時間・ストップウォッチ計測) は完全に
  // 維持される — カレンダー/ドロワーから戻ってきたら裏で進んだ続きから見える。
  bool _drawerOpen = false;
  bool _popupMenuOpen = false;

  /// 計算機等のフローティングツールを今、裏に隠すべきかどうか。
  /// - drawer (左メニュー) が開いている時
  /// - 右上 ⋮ ポップアップメニューが開いている時
  /// - カレンダーモード中 (画面が大きく切り替わっているのでツールは邪魔)
  bool get _shouldHideFloatingTools =>
      _drawerOpen || _popupMenuOpen || _calendarMode;

  /// 上記いずれかの状態が変化した時に呼び、5 つの OverlayEntry に
  /// rebuild を要求する。各 OverlayEntry の builder は
  /// `_shouldHideFloatingTools` を毎回読み直すので Offstage の値が
  /// 自動的に更新される。
  void _refreshFloatingOverlays() {
    _calculatorOverlay?.markNeedsBuild();
    _stopwatchOverlay?.markNeedsBuild();
    _sciCalcOverlay?.markNeedsBuild();
    _pomodoroOverlay?.markNeedsBuild();
    _weatherOverlay?.markNeedsBuild();
  }

  /// ── ドロワーのマップ複数選択モード ──
  /// drawer が開いているとき、Shift/Ctrl + クリックや長押しで複数のマップを
  /// 選択 → Ctrl+G で新規フォルダーにまとめて格納。
  /// 選択中の page id を保持。空なら通常モード。
  Set<String> _drawerSelectedPageIds = {};

  /// drawer 内のフォルダー複数選択 (ページとは別管理)
  /// フォルダーを選択した状態で「・・・」メニュー → 一括削除等が可能
  Set<String> _drawerSelectedFolderIds = {};

  /// Shift + クリックでの範囲選択用に、最後に単独選択したアンカーの
  /// drawer 上のフラットインデックス (0 始まり) を保持。
  /// drawer の表示順 (フォルダー → そのページ群 → ルートページ群) で連番。
  int? _drawerLastAnchorIndex;

  /// ページとフォルダー、どちらかが選択されていれば複数選択モード扱い
  bool get _drawerMultiSelectActive =>
      _drawerSelectedPageIds.isNotEmpty || _drawerSelectedFolderIds.isNotEmpty;

  /// drawer のページ一覧用スクロールコントローラー。
  /// マップが大量に増えた時に RawScrollbar を白系で常時表示するために使う。
  final ScrollController _drawerListScrollCtrl = ScrollController();

  /// drawer の表示モード (= ユーザー要望: マップ一覧と同じ位置に同じ大きさで
  /// 今日のタイムラインを表示)。 'maps' = マップ一覧、 'timeline' = タイムライン。
  /// Ctrl+Shift+T ショートカットで 'timeline' にセットしてドロワーを開く。
  String _drawerView = 'maps';

  /// タイムラインで表示している日の「今日からの日数オフセット」。
  /// 0 = 今日、 -1 = 前日、 +1 = 翌日 (= ユーザー要望: 矢印で前後の日に切替)。
  int _timelineDayOffset = 0;

  // ── 睡眠時間 (= ユーザー要望: タイムラインで睡眠時間帯をコンパクト表示) ──
  /// 睡眠の開始 / 終了 (分・0〜1439)。 -1 = 未設定 (= 圧縮しない)。
  /// 例: 23:00〜7:00 → start=1380, end=420 (日跨ぎ可)。
  int _sleepStartMin = -1;
  int _sleepEndMin = -1;

  /// 睡眠中の 1 時間あたりの圧縮表示高さ (px)。 通常時は 60px。
  static const double _kSleepHourPx = 7.0;
  bool get _sleepEnabled =>
      _sleepStartMin >= 0 &&
      _sleepEndMin >= 0 &&
      _sleepStartMin != _sleepEndMin;

  /// 時刻 h (0〜23) が睡眠ゾーンに入るか (日跨ぎ対応)。 圧縮表示の判定に使う。
  bool _isSleepHour(int h) {
    if (!_sleepEnabled) return false;
    final m = h * 60; // その時間の開始分で判定
    if (_sleepStartMin < _sleepEndMin) {
      return m >= _sleepStartMin && m < _sleepEndMin;
    }
    return m >= _sleepStartMin || m < _sleepEndMin; // 日跨ぎ
  }

  /// 各時刻境界 (0:00〜24:00) の y 座標 (= 圧縮込み)。 hourY[h] = h:00 の y。
  /// 睡眠時間は _kSleepHourPx に圧縮、 それ以外は 60px。 未設定時は h*60 (恒等)。
  List<double> _tlHourY() {
    const double hourHeight = 60.0;
    final List<double> y = [0.0];
    for (int h = 0; h < 24; h++) {
      y.add(y.last + (_isSleepHour(h) ? _kSleepHourPx : hourHeight));
    }
    return y;
  }

  /// 分 (0〜1440) → タイムライン描画 y。 睡眠未設定時は minute と等しい (恒等)。
  double _tlYForMin(int minute) {
    final hy = _tlHourY();
    final m = minute.clamp(0, 24 * 60);
    final h = (m ~/ 60).clamp(0, 23);
    final frac = (m - h * 60) / 60.0;
    return hy[h] + frac * (hy[h + 1] - hy[h]);
  }

  /// 描画 y → 分 (_tlYForMin の逆)。 睡眠未設定時は y と等しい (恒等)。
  int _tlMinForY(double y) {
    final hy = _tlHourY();
    for (int h = 0; h < 24; h++) {
      if (y < hy[h + 1] || h == 23) {
        final span = hy[h + 1] - hy[h];
        final frac = span <= 0 ? 0.0 : ((y - hy[h]) / span).clamp(0.0, 1.0);
        return (h * 60 + frac * 60).round().clamp(0, 24 * 60);
      }
    }
    return 24 * 60;
  }

  /// 圧縮込みのタイムライン全体高さ。 未設定時は 1440。
  double get _tlTotalHeight => _tlHourY().last;

  Future<void> _loadSleepTime() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final s = prefs.getInt('timelineSleepStartMin') ?? -1;
      final e = prefs.getInt('timelineSleepEndMin') ?? -1;
      if (!mounted) return;
      setState(() {
        _sleepStartMin = s;
        _sleepEndMin = e;
      });
    } catch (_) {}
  }

  Future<void> _persistSleepTime() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setInt('timelineSleepStartMin', _sleepStartMin);
      await prefs.setInt('timelineSleepEndMin', _sleepEndMin);
    } catch (_) {}
  }

  Widget _sleepTimeRow(String label, String value, VoidCallback onTap) {
    return Row(children: [
      SizedBox(
          width: 48,
          child: Text(label,
              style: const TextStyle(color: Colors.white70, fontSize: 13))),
      const SizedBox(width: 8),
      Expanded(
        child: OutlinedButton(
          style: OutlinedButton.styleFrom(
              foregroundColor: Colors.white,
              side: const BorderSide(color: Colors.white24)),
          onPressed: onTap,
          child: Text(value, style: const TextStyle(fontSize: 15)),
        ),
      ),
    ]);
  }

  /// 睡眠時間 (タイムラインの圧縮表示) を設定するダイアログ (= ユーザー要望)。
  Future<void> _showSleepTimeDialog(BuildContext ctx) async {
    TimeOfDay start = _sleepStartMin >= 0
        ? TimeOfDay(hour: _sleepStartMin ~/ 60, minute: _sleepStartMin % 60)
        : const TimeOfDay(hour: 23, minute: 0);
    TimeOfDay end = _sleepEndMin >= 0
        ? TimeOfDay(hour: _sleepEndMin ~/ 60, minute: _sleepEndMin % 60)
        : const TimeOfDay(hour: 7, minute: 0);
    String fmt(TimeOfDay t) =>
        '${t.hour.toString().padLeft(2, '0')}:${t.minute.toString().padLeft(2, '0')}';
    await showDialog<void>(
      context: ctx,
      builder: (dctx) => StatefulBuilder(
        builder: (dctx, setD) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            Text('💤', style: TextStyle(fontSize: 18)),
            SizedBox(width: 8),
            Text(context.read<MindMapProvider>().t('sleep.title'),
                style: const TextStyle(color: Colors.white, fontSize: 16)),
          ]),
          content: Column(mainAxisSize: MainAxisSize.min, children: [
            Text(context.read<MindMapProvider>().t('sleep.desc'),
                style: TextStyle(color: Colors.white54, fontSize: 12)),
            const SizedBox(height: 14),
            _sleepTimeRow(
                context.read<MindMapProvider>().t('sleep.bedtime'),
                fmt(start), () async {
              final t = await showTimePicker(context: dctx, initialTime: start);
              if (t != null) setD(() => start = t);
            }),
            const SizedBox(height: 8),
            _sleepTimeRow(
                context.read<MindMapProvider>().t('sleep.wakeup'),
                fmt(end), () async {
              final t = await showTimePicker(context: dctx, initialTime: end);
              if (t != null) setD(() => end = t);
            }),
          ]),
          actions: [
            if (_sleepEnabled)
              TextButton(
                onPressed: () {
                  setState(() {
                    _sleepStartMin = -1;
                    _sleepEndMin = -1;
                  });
                  _persistSleepTime();
                  Navigator.pop(dctx);
                },
                child: Text(context.read<MindMapProvider>().t('sleep.disable'),
                    style: TextStyle(color: Color(0xFFE57373))),
              ),
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6C63FF),
                  foregroundColor: Colors.white),
              onPressed: () {
                setState(() {
                  _sleepStartMin = start.hour * 60 + start.minute;
                  _sleepEndMin = end.hour * 60 + end.minute;
                });
                _persistSleepTime();
                Navigator.pop(dctx);
              },
              child: Text(context.read<MindMapProvider>().t('btn.settings')),
            ),
          ],
        ),
      ),
    );
  }

