  //
  // ・[_splitOpen]       : 開閉状態
  // ・[_splitPanelWidth] : パネル幅 (左端のグリップでドラッグリサイズ)
  // ・[_splitUrlCtrl]    : URL 入力欄の TextEditingController
  // ・[_splitCurrentUrl] : 現在ロード中の URL
  // ・[_splitMode]       : 'web' | 'pdf' (URL の拡張子から自動判定)
  //
  // Platform 別の描画切替:
  //   Windows → wv_win.Webview
  //   その他   → iaw.InAppWebView
  //   PDF      → sf_pdf.SfPdfViewer (全プラットフォーム共通)
  bool _splitOpen = false;

  /// _splitOpen の代入と同時に provider.setSplitMode を呼ぶヘルパー。
  /// _customBottomTopButtons (2x6) と _customBottomTopButtonsSplit (2x2)
  /// の自動切り替えのため。 setState ブロック内で呼ぶ。
  ///
  /// ユーザー要望: 「画面分割が 2 つ出ている状態で画面分割のカスタムボタンを
  /// 押すと 2 つ目だけ ON/OFF が切り替わるだけで 1 枚目が閉じないから閉じる
  /// ようにして」。
  /// → 閉じるとき (v == false) は左パネルも同時に閉じる。
  ///   開くとき (v == true) は左パネルには触れない (= 既存挙動維持)。
  void _setSplitOpen(bool v) {
    // ── Pro ゲート: 画面分割の新規オープンは無料 2 回まで ──
    // 閉じている状態 (_splitOpen == false) から開く (v == true) ときだけ
    //   カウント対象。既に開いている状態での再オープン (パネル切替・入れ替え・
    //   履歴移動・復元) はカウントしない。3 回目以降は Pro ペイウォールを出し、
    //   分割は開かない。Pro/Max/クーポン/開発者モードは無制限。
    if (v && !_splitOpen) {
      final pv = context.read<MindMapProvider>();
      if (!pv.isProUnlocked && !pv.canUseSplitView) {
        // setState 内から呼ばれることがあるため showDialog は次フレームに回す。
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) {
            _showPaywallDialog(pv,
                bodyOverride: pv.t('paywall.proRequiredSplit'));
          }
        });
        return; // _splitOpen は false のまま (開かない)
      }
      if (!pv.isProUnlocked) {
        pv.recordSplitViewUse(); // 無料枠を 1 消費
      }
    }
    _splitOpen = v;
    // 画面分割を「閉じる」 操作時に左パネルも閉じる (= 同時に両方クリア)
    if (!v && _splitLeftOpen) {
      _splitLeftOpen = false;
      _splitLeftLocalPdfPath = null;
      _splitLeftHasVideo = false;
    }
    // ── 閉じる時のフォーカス・Office パスクリア ──
    // ユーザー要望: 「画面分割が閉じられた時に画面が固まってスクロール
    //   不可になることがあるからそれも修正して」 への対応。
    //   原因は WebView 内の TextField や PDF Viewer が Focus を握ったまま
    //   widget が dispose されると、 メインの InteractiveViewer が
    //   pointer event を受け取れなくなること。 unfocus で確実に解放する。
    // また、 Office モード時のパスもクリアしないと、 再度開いた時に
    // 前のファイルが残って混乱するので、 ここで一緒にクリアする。
    if (!v) {
      _splitLocalOfficePath = null;
      _splitOfficeFileName = '';
      _splitLocalPdfPath = null;
      _splitCurrentUrl = '';
      _splitHasVideo = false;
      try {
        FocusManager.instance.primaryFocus?.unfocus();
      } catch (_) {/* context が無効でも続行 */}
    }
    try {
      if (mounted) {
        // ── モバイル対応 (= ユーザー要望「2×2 ボタン配置も辞めにして」) ──
        // モバイルでは split モード時の 2x2 ボタン配置 (= _customBottomTopButtonsSplit)
        // を使わず、 通常の 2x6 (= _customBottomTopButtons) を維持する。
        // そのため provider に true を伝えない (常に false 扱いで通常配置を使う)。
        // 閉じる時 (v == false) はデスクトップ/モバイル共通で false を伝えて
        // 確実に通常配置に戻す。
        final shouldUseSplitButtons = _isDesktop && v;
        context.read<MindMapProvider>().setSplitMode(shouldUseSplitButtons);
      }
    } catch (e) {
      debugPrint('setSplitMode 失敗 (context 無効?): $e');
    }
  }

  double _splitPanelWidth = 480.0;
  final TextEditingController _splitUrlCtrl = TextEditingController();
  String _splitCurrentUrl = '';
  String _splitMode = 'web'; // 'web' | 'pdf'

  /// 画面分割の URL 入力バーの表示状態。 デフォルトは閉じた状態
  /// (= ユーザー要望「URL を常に表示しない」)。 ヘッダーの検索アイコンを
  /// 押すとトグルで開く。
  bool _splitUrlBarOpen = false;

  /// 画面分割の動画再生速度 (0.25 〜 2.0)。 動画サイトを開いた時に
  /// 下部にオーバーレイで表示される Slider で操作。 デフォルト 1.0x。
  double _splitVideoPlaybackRate = 1.0;

  /// 動画再生速度バーの展開/折りたたみ状態。
  /// ユーザー要望「再生速度バーは折りたたんで目立たない形にできるように
  ///   して」 への対応。 false なら小さな速度アイコン 1 つだけ表示、
  ///   true なら従来の通常バー (スライダー + プリセット) を展開表示。
  bool _splitVideoBarExpanded = false;
  bool _splitHasVideo = false;
  bool _splitLeftHasVideo = false;

  /// 分割パネルの動画をパネルいっぱいに縦へ引き伸ばすモード
  /// (= ユーザー要望: 分割すると上下の領域が余ってもったいない)。
  /// 速度バーのアイコンでトグルし、 ページ遷移後も再適用する。
  /// prefs `splitVideoFillMode` に保存。
  bool _splitVideoFillMode = false;
  wv_win.WebviewController? _splitWinController;
  bool _splitWinInitialized = false;
  iaw.InAppWebViewController? _splitIawController;
  String? _splitLocalPdfPath;

  /// 画面分割パネル PDF 用の SfPdfViewer コントローラ。
  /// マウスがパネル側にあるとき、 メインの KeyboardListener から
  /// ↑↓ や PageUp/Down で `jumpTo` / `nextPage` / `previousPage` を呼んで
  /// プログラマブルにスクロールするため。 SfPdfViewer 自身の Focus に
  /// 頼ると「止まってしまう場所」 が出るので、 こちらで完全制御する。
  final sf_pdf.PdfViewerController _splitPdfController =
      sf_pdf.PdfViewerController();

  /// 右パネルヘッダーの「ページ番号入力欄」 用 Controller。
  /// 左パネルと同じヘッダー構造に揃えるため新規追加 (= ユーザー要望
  /// 「右画面分割の上は左画面分割の上に揃えろ」)。
  final TextEditingController _splitJumpPageCtrl = TextEditingController();

  // ─── 画面分割パネルで Office ファイル (pptx/docx) を表示するための状態 ──
  // ユーザー要望: 「word もパワポも画面分割に対応させて」 への対応。
  // _splitMode に 'pptx', 'docx' を追加し、 該当モードの時は右パネル
  // 内に _PptxViewerDialog / _DocxViewerDialog を Widget として埋め込む
  // (= これらは既に普通の Widget として実装されているので、 Dialog
  // ラッパーを外して画面分割パネル内に直接配置できる)。
  //
  /// 右パネルの Office ファイルパス (pptx / docx)。 mode が 'pptx' / 'docx'
  /// の時のみ有効。 PDF 用の _splitLocalPdfPath と同じ位置付け。
  String? _splitLocalOfficePath;
  String _splitOfficeFileName = '';

  /// 左パネルの Office ファイルパス。 mode が 'pptx' / 'docx' の時のみ有効。
  String? _splitLeftLocalOfficePath;
  String _splitLeftOfficeFileName = '';

  // ─── 画面分割「左パネル」 (= PDF 専用、 並列表示用) ────────────────
  // ユーザー要望: 「PDF を画面分割した状態で、 他の PDF を開いたら、
  // 左右で半分半分異なる PDF が開かれた状態になるようにして」。
  //
  // 既存の `_splitOpen` (= 右パネル) を維持しつつ、 新規に左パネルを追加。
  // 右パネルが何かを表示中に新 PDF を開こうとした場合、 既存を右に残して
  // 新 PDF を左パネルに展開する。 これでマップを潰さずに左右に 2 つの PDF
  // を並べられる (= ただし狭くなるので必要に応じてマップは隠す)。
  bool _splitLeftOpen = false;
  String? _splitLeftLocalPdfPath;
  int _splitLeftCurrentPage = 1;
  int _splitLeftTotalPages = 0;

  /// 左パネル PDF のコントローラ (= 右パネルとは完全独立)
  final sf_pdf.PdfViewerController _splitLeftPdfController =
      sf_pdf.PdfViewerController();

  /// 左パネルの幅 (= 右パネルと別管理)
  double _splitLeftPanelWidth = 480.0;

  /// 左パネル PDF のページ入力 controller
  final TextEditingController _splitLeftPageInputCtrl =
      TextEditingController(text: '1');

  /// 左パネル領域にマウスが乗っているか (= Esc キーで閉じる判定に使う)
  bool _splitLeftPanelHover = false;

  // ─── 左パネル WebView/URL 対応 (= PDF 限定解除) ──────────────────────
  // ユーザー要望: 「左画面分割は PDF に限定する必要ない」 「PDF 以外も左画面に
  // 割り当てられるようにしろ」。
  /// 左パネル現在の URL (= PDF 以外の Web ページや YouTube 等)
  String _splitLeftCurrentUrl = '';

  /// 左パネルのモード ('pdf' | 'web')
  String _splitLeftMode = 'pdf';

  /// 左パネル URL 入力欄
  final TextEditingController _splitLeftUrlCtrl = TextEditingController();

  /// 左パネル WebView コントローラ (= Mobile + その他プラットフォーム用)
  iaw.InAppWebViewController? _splitLeftIawController;

  /// 左パネル用の Windows webview_windows コントローラ。
  /// ユーザー要望: 「左側に移そうとすると真っ白な全画面になってフリーズ
  ///   する」 の根本原因は、 左パネルが常に `flutter_inappwebview` を使って
  ///   いたが、 これは Windows でのサポートが不安定で、 Windows 環境では
  ///   ハングアップしてしまうこと。 右パネルと同じく `webview_windows` を
  ///   左でも使うことで解決する。
  wv_win.WebviewController? _splitLeftWinController;
  bool _splitLeftWinInitialized = false;

  /// 左パネル URL 入力欄の表示状態
  bool _splitLeftUrlBarOpen = false;

  /// 左パネルに URL を読み込む (= PDF 以外の Web ページ等)。
  /// PDF なら `_splitLoadLeftPdf` 経由、 それ以外は WebView で開く。
  void _splitLoadLeftUrl(String raw) {
    var url = raw.trim();
    if (url.isEmpty) return;
    // ── モバイル: 左パネルは使わず「上分割」 (= メインパネルを上に配置) ──
    // ユーザー要望: スマホでは左右分割ではなく上下分割の 2 ボタンにしたい。
    //   左ボタン → 上分割。 メインパネルを開いて位置を top に上書きする。
    if (!_isDesktop) {
      setState(() {
        _setSplitOpen(true);
      });
      _splitLoadUrl(url);
      setState(() {
        _splitPosition = _SplitPosition.top;
      });
      return;
    }
    // Windows ローカルパス検出
    final isWinLocal = RegExp(r'^[a-zA-Z]:[\\/]').hasMatch(url);
    // スキーマ補完
    if (!url.startsWith('http://') &&
        !url.startsWith('https://') &&
        !url.startsWith('file://') &&
        !url.startsWith('/') &&
        !isWinLocal) {
      url = 'https://$url';
    }
    final isPdf = url.toLowerCase().endsWith('.pdf');
    final isLocalFile =
        isWinLocal || url.startsWith('file://') || url.startsWith('/');
    if (isPdf && isLocalFile) {
      // PDF ローカル → 既存の左 PDF 表示処理に振る
      _splitLoadLeftPdf(url);
      return;
    }
    // ── OAuth ポップアップが動かないサイトは外部ブラウザへ ──
    // (= 詳細は _isOAuthBlockedUrl のコメント参照)
    if (!isPdf && !isLocalFile && _isOAuthBlockedUrl(url)) {
      final uri = Uri.tryParse(url);
      if (uri != null) {
        try {
          launchUrl(uri, mode: LaunchMode.externalApplication);
          if (mounted) {
            _appSnack(
              context,
              SnackBar(
                content: Text(
                    context.read<MindMapProvider>().t('split.openedExternal')),
                backgroundColor: Color(0xFF6C63FF),
                duration: Duration(seconds: 3),
              ),
            );
          }
          return;
        } catch (_) {}
      }
    }
    setState(() {
      _splitLeftOpen = true;
      _splitLeftCurrentUrl = url;
      _splitLeftMode = isPdf ? 'pdf' : 'web';
      _splitLeftLocalPdfPath = (isPdf && isLocalFile) ? url : null;
      _splitLeftUrlCtrl.text = url;
      _splitLeftHasVideo = !isPdf && _isLikelyVideoUrl(url);
    });
    // WebView がすでにある場合は loadUrl
    // Windows は webview_windows、 それ以外は flutter_inappwebview を更新。
    if (!isPdf) {
      if (Platform.isWindows) {
        _splitLeftWinController?.loadUrl(url);
      } else {
        _splitLeftIawController?.loadUrl(
            urlRequest: iaw.URLRequest(url: iaw.WebUri(url)));
      }
      _scheduleSplitVideoProbe(leftPanel: true);
    }
    // ── ロード直後にメインへフォーカスを戻す ──
    // ユーザー要望: 「左画面分割をすると画面が固まってスクロールできなく
    //   なる問題」 への対応。 WebView 内の Platform View が暗黙的に
    //   フォーカスを握ると、 メインの InteractiveViewer がマウスホイール
    //   等のポインタイベントを受け取れなくなる。 unfocus で明示的に解放。
    try {
      FocusManager.instance.primaryFocus?.unfocus();
    } catch (_) {}
  }

  /// PDF パネルの隣 (= 左パネル) に、選んだ生成 AI のサイトを開く。
  /// ユーザー要望:「Windows 版で PDF を表示している左側に、カスタムボタンで
  ///   設定できる 5 種類の生成 AI から選んで AI 会話ボックスを開けるように」。
  /// URL はカスタムボタン (openChatGPT 等) と同一にして挙動を揃える。
  /// デスクトップ専用 (左パネルはデスクトップのみ)。
  void _openAiInLeftPanel(String aiId) {
    const urls = <String, String>{
      'chatgpt': 'https://chatgpt.com/',
      'gemini': 'https://gemini.google.com/app',
      'claude': 'https://claude.ai/',
      'deepseek': 'https://chat.deepseek.com/',
      'grok': 'https://grok.com/',
    };
    final url = urls[aiId];
    if (url == null) return;
    _splitLoadLeftUrl(url);
  }

  /// 左パネルに PDF をロード。 右パネルとは独立に動作。
  void _splitLoadLeftPdf(String path) {
    if (path.isEmpty) return;
    // モバイル: 左パネルではなく「上分割」 (メインパネルを上に配置)。
    if (!_isDesktop) {
      setState(() {
        _setSplitOpen(true);
      });
      _splitLoadUrl(path);
      setState(() {
        _splitPosition = _SplitPosition.top;
      });
      return;
    }
    setState(() {
      _splitLeftOpen = true;
      _splitLeftLocalPdfPath = path;
      _splitLeftMode = 'pdf';
      _splitLeftCurrentPage = 1;
      _splitLeftTotalPages = 0;
      _splitLeftHasVideo = false;
    });
    // ロード直後のフォーカス解放 (= スクロール不可問題対策)
    try {
      FocusManager.instance.primaryFocus?.unfocus();
    } catch (_) {}
    // 最終ページ復元は onDocumentLoaded のなかで実行
  }

  /// 左パネルを閉じる (= PDF/Web どちらも)
  /// 右パネル**だけ**を閉じる (= 左パネルには触れない)。
  ///
  /// ユーザー要望「ChatGPT と Claude を画面分割で同時に開いた状態で Claude
  ///   ボタンを押すと ChatGPT の画面まで閉じてしまう問題があるから選択した
  ///   項目だけの ON/OFF が切り替わるようにして」 への対応で導入。
  ///
  /// 画面分割のペインに置く Office / テキストのビューア本体。
  ///
  /// 左右どちらのペインからも同じ物を使う。 呼び出し側は
  /// [_SplitCellEmbeddedPanel] で包むこと (ビューアが自分を閉じる時の
  /// `Navigator.pop()` でアプリ本体の画面が消えてしまうのを防ぐため)。
  Widget _buildSplitOfficeViewer(
    BuildContext ctx, {
    required String mode,
    required String path,
    required String fileName,
  }) {
    final isDark = ctx.watch<MindMapProvider>().isDarkMode;
    switch (mode) {
      case 'pptx':
        return _PptxViewerDialog(
          filePath: path,
          fileName: fileName,
          isDarkMode: isDark,
        );
      case 'docx':
        return _DocxViewerDialog(
          filePath: path,
          fileName: fileName,
          isDarkMode: isDark,
        );
      case 'txt':
        // ── テキスト系ファイル (= ユーザー要望: txt も画面分割上で
        //    開けるように)。 ペインは狭いのでメモ / AI パネルは自動で
        //    開かない。 ──
        return _TextEditorDialog(
          filePath: path,
          fileName: fileName,
          isDarkMode: isDark,
          compactHost: true,
        );
      default:
        return _SpreadsheetEditorDialog(
          filePath: path,
          fileName: fileName,
          isDarkMode: isDark,
        );
    }
  }

  /// 既存の `_setSplitOpen(false)` は「画面分割全体を閉じる」 操作で、
  /// 左パネルも同時に閉じる仕様 (= 別の過去要望「画面分割が 2 つ出ている
  /// 状態で画面分割のカスタムボタンを押すと 2 つ目だけ ON/OFF が切り替わる
  /// だけで 1 枚目が閉じないから閉じる」)。 この一斉閉じが「Claude を閉じる
  /// だけのつもりが ChatGPT も消える」 問題の原因。
  ///
  /// 新関数 `_closeSplitRightPanelOnly` は右パネルだけを閉じ、 左パネルは
  /// 残す。 `_setSplitOpen(false)` から左パネル close 部分だけを除いた版。
  void _closeSplitRightPanelOnly() {
    setState(() {
      _splitOpen = false;
      _splitLocalOfficePath = null;
      _splitOfficeFileName = '';
      _splitLocalPdfPath = null;
      _splitCurrentUrl = '';
      _splitHasVideo = false;
      // 左パネルが残ってる場合は split モードの provider 状態を保持
      // (= 左がある間は customBottomTopButtonsSplit 設定を活かす)
      final shouldUseSplitButtons = _isDesktop && _splitLeftOpen;
      try {
        if (mounted) {
          context.read<MindMapProvider>().setSplitMode(shouldUseSplitButtons);
        }
      } catch (e) {
        debugPrint('setSplitMode 失敗 (context 無効?): $e');
      }
      try {
        FocusManager.instance.primaryFocus?.unfocus();
      } catch (_) {/* context 無効でも続行 */}
    });
  }

  void _closeSplitLeftPanel() {
    setState(() {
      _splitLeftOpen = false;
      _splitLeftLocalPdfPath = null;
      _splitLeftCurrentUrl = '';
      _splitLeftMode = 'pdf';
      _splitLeftHasVideo = false;
      // ── Office モードのパスもクリア ──
      // ユーザー要望: 「画面分割が閉じられた時に画面が固まってスクロール
      //   不可になることがある」 への対応の一部。 残骸が残ると次回開いた
      //   時に表示分岐が混乱するため、 明示的にクリア。
      _splitLeftLocalOfficePath = null;
      _splitLeftOfficeFileName = '';
      // Windows webview_windows のコントローラ参照もクリア
      // (= widget が破棄される時に State 側で dispose が走るので、
      //  ここでは参照だけ外す)
      _splitLeftWinController = null;
      _splitLeftWinInitialized = false;
      // 元ノード ID もリセット (全画面へ戻す時は先に取り出してから閉じる)。
      _splitLeftOriginNodeId = null;
    });
    // ── フォーカスをメインに戻す ──
    // WebView 内の TextField や PDF Viewer が Focus を握ったまま
    // widget が dispose されると、 メインの InteractiveViewer が
    // pointer event (= スクロール) を受け取れなくなる。
    try {
      FocusManager.instance.primaryFocus?.unfocus();
    } catch (_) {/* context 無効でも続行 */}
  }

  /// 左右の画面分割パネルの中身を入れ替える。
  ///
  /// 改修ポイント (= ユーザー要望「左右に画面分割がおいてある状態で右の
  ///   画面分割から左右の入れ替えボタンを押すと右の画面は左に来るけど、
  ///   左のやつが右に移らずに消えてしまうバグ」 への対応):
  ///   * 旧仕様: PDF (path) と Web (URL) しか考慮していなかったため、
  ///     Office モード (pptx/docx/xlsx) のパネルは `_splitLoadUrl` /
  ///     `_splitLoadLeftUrl` で復元できず消えていた。
  ///   * 新仕様: Office パス (`_splitLocalOfficePath`) もスナップショット
  ///     して、 mode に応じて適切な復元処理を呼ぶ。
  void _swapSplitPanels() {
    final leftOpen = _splitLeftOpen;
    final rightOpen = _splitOpen;
    final leftMode = _splitLeftMode;
    final leftUrl = _splitLeftCurrentUrl;
    final leftPdfPath = _splitLeftLocalPdfPath;
    final leftOfficePath = _splitLeftLocalOfficePath;
    final leftOfficeName = _splitLeftOfficeFileName;
    final rightMode = _splitMode;
    final rightUrl = _splitCurrentUrl;
    final rightPdfPath = _splitLocalPdfPath;
    final rightOfficePath = _splitLocalOfficePath;
    final rightOfficeName = _splitOfficeFileName;

    if (!leftOpen && !rightOpen) {
      _appSnack(context, SnackBar(
        content: Text(context.read<MindMapProvider>().t('split.noPanelToSwap')),
        duration: Duration(seconds: 2),
        backgroundColor: Color(0xFFFFA726),
      ));
      return;
    }

    bool _isOffice(String m) =>
        m == 'pptx' || m == 'docx' || m == 'xlsx' || m == 'txt';

    // ── 一度両方を閉じてから、 build 完了 + 500ms 待ってから再ロード ──
    setState(() {
      _setSplitOpen(false);
    });
    _closeSplitLeftPanel();

    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      Future.delayed(const Duration(milliseconds: 500), () {
        if (!mounted) return;
        // 元の左 → 右パネルへ
        if (leftOpen) {
          if (_isOffice(leftMode) && leftOfficePath != null) {
            // Office (pptx/docx/xlsx) を右パネルにロード
            _openOfficeInSplitPanel(leftOfficePath, leftOfficeName,
                mode: leftMode, isLeftPanel: false);
          } else if (leftMode == 'pdf' && leftPdfPath != null) {
            _splitLoadUrl(leftPdfPath);
          } else if (leftUrl.isNotEmpty) {
            _splitLoadUrl(leftUrl);
          }
        }
        // 元の右 → 左パネルへ (= さらに 300ms 後)
        Future.delayed(const Duration(milliseconds: 300), () {
          if (!mounted) return;
          if (rightOpen) {
            if (_isOffice(rightMode) && rightOfficePath != null) {
              // Office (pptx/docx/xlsx) を左パネルにロード
              _openOfficeInSplitPanel(rightOfficePath, rightOfficeName,
                  mode: rightMode, isLeftPanel: true);
            } else if (rightMode == 'pdf' && rightPdfPath != null) {
              _splitLoadLeftPdf(rightPdfPath);
            } else if (rightUrl.isNotEmpty) {
              _splitLoadLeftUrl(rightUrl);
            }
          }
        });
      });
    });
  }

  /// 「スマート左右移動」 ボタンの動作。
  ///
  /// ユーザー要望: 「右においてあったら左矢印で左側に移動、 左において
  ///   あったら右矢印で右に移動でいいやん、 で、 既に移動先に分割画面が
  ///   あればそれと交代で入れ替えでいいやん」。
  ///
  /// 引数 [fromLeft] = `true` ならこのボタンは左パネル側 (= 左→右へ移動)、
  ///                 `false` なら右パネル側 (= 右→左へ移動) という意味。
  ///
  /// 動作:
  ///   * 移動先 (反対側) が空 → 自分の内容を反対側にロードして、 自分を閉じる
  ///   * 移動先に何かある    → スワップ (_swapSplitPanels に委譲)
  ///
  /// ユーザー要望: 「生成 AI 系を画面の左に移そうとするとフリーズする」
  ///   への再対応。 Windows の webview_windows は dispose() が同期的に
  ///   返るがネイティブ側 (WebView2 + COM) の破棄は非同期で完了するため、
  ///   250ms 程度では足りずに左パネルの flutter_inappwebview 生成中に
  ///   競合してフリーズする。 解決策:
  ///   1. `addPostFrameCallback` で「右パネルを閉じる setState の build」
  ///      が完了するまで待つ
  ///   2. その後 500ms 待つ (= ネイティブ webview の破棄完了を待つ)
  ///   3. 反対側にロード
  void _smartMovePanel({required bool fromLeft}) {
    final fromSrcOpen = fromLeft ? _splitLeftOpen : _splitOpen;
    final fromDstOpen = fromLeft ? _splitOpen : _splitLeftOpen;
    if (!fromSrcOpen) return;
    if (fromDstOpen) {
      _swapSplitPanels();
      return;
    }
    bool _isOffice(String m) =>
        m == 'pptx' || m == 'docx' || m == 'xlsx' || m == 'txt';
    if (fromLeft) {
      // 左 → 右へ移動
      final mode = _splitLeftMode;
      final url = _splitLeftCurrentUrl;
      final pdfPath = _splitLeftLocalPdfPath;
      final officePath = _splitLeftLocalOfficePath;
      final officeName = _splitLeftOfficeFileName;
      _closeSplitLeftPanel();
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        Future.delayed(const Duration(milliseconds: 500), () {
          if (!mounted) return;
          if (_isOffice(mode) && officePath != null) {
            _openOfficeInSplitPanel(officePath, officeName,
                mode: mode, isLeftPanel: false);
          } else if (mode == 'pdf' && pdfPath != null) {
            _splitLoadUrl(pdfPath);
          } else if (url.isNotEmpty) {
            _splitLoadUrl(url);
          }
        });
      });
    } else {
      // 右 → 左へ移動
      final mode = _splitMode;
      final url = _splitCurrentUrl;
      final pdfPath = _splitLocalPdfPath;
      final officePath = _splitLocalOfficePath;
      final officeName = _splitOfficeFileName;
      setState(() => _setSplitOpen(false));
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        Future.delayed(const Duration(milliseconds: 500), () {
          if (!mounted) return;
          if (_isOffice(mode) && officePath != null) {
            _openOfficeInSplitPanel(officePath, officeName,
                mode: mode, isLeftPanel: true);
          } else if (mode == 'pdf' && pdfPath != null) {
            _splitLoadLeftPdf(pdfPath);
          } else if (url.isNotEmpty) {
            _splitLoadLeftUrl(url);
          }
        });
      });
    }
  }

  /// スマート左右移動ボタン用のアイコンを決める。
  /// 反対側が空 → 移動アイコン (左パネルなら →、 右パネルなら ←)
  /// 反対側に何かある → スワップアイコン (⇆)
  IconData _smartMoveIcon({required bool fromLeft}) {
    final fromDstOpen = fromLeft ? _splitOpen : _splitLeftOpen;
    if (fromDstOpen) return Icons.swap_horiz_rounded;
    return fromLeft ? Icons.arrow_forward_rounded : Icons.arrow_back_rounded;
  }

  /// スマート左右移動ボタン用のツールチップ文言を決める。
  String _smartMoveTooltip({required bool fromLeft}) {
    final fromDstOpen = fromLeft ? _splitOpen : _splitLeftOpen;
    final p = context.read<MindMapProvider>();
    if (fromDstOpen) return p.t('split.swapLR');
    return fromLeft ? p.t('split.moveRight') : p.t('split.moveLeft');
  }

  /// 左パネルの現在の内容 (PDF / Web) を全画面ビューアで開き直す。
  /// ユーザー要望: 「画面分割画面の上に全画面表示にするボタン」 (左パネル版)。
  Future<void> _openSplitLeftAsFullscreen() async {
    if (!_splitLeftOpen) return;
    final pdfPath = _splitLeftLocalPdfPath;
    final url = _splitLeftCurrentUrl;
    final mode = _splitLeftMode;
    // 元ノード ID を引き継いでメモ欄を出せるようにする (= ユーザー要望:
    // 左分割から全画面に戻すとメモ欄が出せなくなる問題の修正)。
    final originNodeId = _splitLeftOriginNodeId;
    // 左パネルを閉じる
    _closeSplitLeftPanel();
    // フルスクリーン アプリ内ビューアで開く (PDF / Web 自動判別)
    if (mode == 'pdf' && pdfPath != null) {
      await _showInAppViewer(context, pdfPath,
          isLocalFile: true, nodeId: originNodeId);
    } else if (url.isNotEmpty) {
      await _showInAppViewer(context, url,
          isLocalFile: false, nodeId: originNodeId);
    }
  }

  /// 指定 URL を画面分割パネルで開くヘルパー。
  /// モバイル版 (InAppWebView) のクリップボード貼り付け polyfill を仕込む。
  ///
  /// ユーザー要望: 「このアプリでの貼り付けをサポートしていませんって
  ///   出て画像やらをモバイル版で生成AIに渡せられないから渡せるように
  ///   して」 への対応。
  ///
  /// 問題:
  ///   Android/iOS の WebView は標準で `navigator.clipboard.read` /
  ///   `readText` を実装していない (= secure context や user gesture の
  ///   制約で失敗する) ため、 ChatGPT / Claude / Gemini 等が「貼り付け」
  ///   機能を呼ぶと「貼り付けをサポートしていません」 と表示してしまう。
  ///
  /// 解決:
  ///   Flutter 標準の Clipboard API でテキストを取得し、 JS の
  ///   `navigator.clipboard.read[Text]` を polyfill。 既存 API が動く
  ///   場合はそちらを優先し、 失敗時のみ fallback として Flutter から
  ///   取得したテキストを返す。 これで text の貼り付けは確実に動く。
  ///
  /// 画像クリップボード:
  ///   Flutter 標準 API では画像を取得できない (= super_clipboard 等の
  ///   追加パッケージが必要)。 画像を貼りたい場合は、 ChatGPT 等の
  ///   「+ (添付) ボタン」 から画像を選択する。 InAppWebView の
  ///   onShowFileChooser は標準で動作するので、 ファイル選択は問題なし。
  void _installClipboardPolyfill(iaw.InAppWebViewController ctrl) {
    if (_isDesktop) return; // モバイルのみ対象
    try {
      // 既に同じ handler が登録されていてもエラーにはならないが、
      // 念のため try-catch で囲む。
      ctrl.addJavaScriptHandler(
        handlerName: 'mokumoku_clipboard_readText',
        callback: (args) async {
          try {
            final data = await Clipboard.getData(Clipboard.kTextPlain);
            return data?.text ?? '';
          } catch (e) {
            debugPrint('clipboard polyfill text read 失敗: $e');
            return '';
          }
        },
      );
    } catch (e) {
      debugPrint('clipboard polyfill handler 登録失敗: $e');
    }
  }

  /// onLoadStop 後に `navigator.clipboard.read[Text]` の polyfill JS を
  /// 注入。 ナビゲーション毎に window コンテキストが再生成されるため、
  /// onLoadStop の度に呼ぶ必要がある。
  /// `__mokumoku_clipboard_polyfill__` フラグで二重注入をガード。
  Future<void> _injectClipboardPolyfillJs(
      iaw.InAppWebViewController ctrl) async {
    if (_isDesktop) return;
    try {
      await ctrl.evaluateJavascript(source: r'''
        (function() {
          if (window.__mokumoku_clipboard_polyfill__) return;
          window.__mokumoku_clipboard_polyfill__ = true;
          if (!navigator.clipboard) navigator.clipboard = {};
          var origRead = navigator.clipboard.read
              ? navigator.clipboard.read.bind(navigator.clipboard) : null;
          var origReadText = navigator.clipboard.readText
              ? navigator.clipboard.readText.bind(navigator.clipboard) : null;
          async function fetchFromFlutter() {
            try {
              var t = await window.flutter_inappwebview.callHandler(
                  'mokumoku_clipboard_readText');
              return typeof t === 'string' ? t : '';
            } catch (e) { return ''; }
          }
          navigator.clipboard.readText = async function() {
            try {
              if (origReadText) {
                var t = await origReadText();
                if (typeof t === 'string' && t.length > 0) return t;
              }
            } catch (e) {/* fall through to Flutter */}
            return await fetchFromFlutter();
          };
          navigator.clipboard.read = async function() {
            try {
              if (origRead) {
                var items = await origRead();
                if (items && items.length > 0) return items;
              }
            } catch (e) {/* fall through to Flutter */}
            var text = await fetchFromFlutter();
            if (!text) return [];
            try {
              return [new ClipboardItem({
                'text/plain': new Blob([text], { type: 'text/plain' })
              })];
            } catch (e) { return []; }
          };
        })();
      ''');
    } catch (e) {
      debugPrint('clipboard polyfill JS 注入失敗: $e');
    }
  }

  /// ChatGPT / Gemini / Claude / DeepSeek / Grok 等の AI カスタムボタンが
  /// 押された時のトグル動作。
  /// ユーザー要望:
  ///   「chatgpt や gemini, claude のカスタムボタンを再度押すことで画面分割
  ///    を閉じたり、 開いたりきりかえられるようにして」
  ///
  /// 動作仕様:
  /// 1. 右パネルで同じドメイン (= 同じ AI サービス) を web モードで開いている
  ///    → 右パネルを閉じる (= 同じボタンを再度押すと閉じる)
  /// 2. 左パネルで同じドメインを web モードで開いている
  ///    → 左パネルを閉じる
  /// 3. それ以外 (= まだ開いていない、 別のサービスが開いている、 PDF/Office
  ///    モードで開いている) → 通常の `_openUrlInSplitPanel` を呼んで開く
  ///
  /// URL の一致判定は host (= ドメイン) ベース。 これにより、 ログイン後の
  /// `https://chatgpt.com/c/xxxxxx-xxxx` のようなサブパスに遷移していても
  /// 「同じ ChatGPT パネル」 と認識でき、 ボタン再押下で閉じられる。
  void _toggleUrlInSplitPanel(String url, {bool? isLeftPanel}) {
    // ヘッダーの AI/Web ボタンでパネルを開閉するときは、 予約済みのノード AI
    //   注入をキャンセルする (= ユーザー要望: AI ボタンで ChatGPT を開くと最後に
    //   開いた単語が勝手にプロンプト欄へ入力されるバグの修正)。 ノードの AI ボタン
    //   経由は _splitLoadUrl → injectInto で改めて seq を進めるので影響しない。
    _splitAiInjectSeq++;
    bool sameHost(String current) {
      if (current.isEmpty) return false;
      try {
        final cur = Uri.parse(current);
        final tgt = Uri.parse(url);
        if (cur.host.isEmpty || tgt.host.isEmpty) return false;
        return cur.host == tgt.host;
      } catch (_) {
        return false;
      }
    }

    // ── 右パネルで同じサービスを開いている → 右だけ閉じる ──
    // ユーザー要望「ChatGPT と Claude を画面分割で同時に開いた状態で Claude
    //   ボタンを押すと ChatGPT の画面まで閉じてしまう問題があるから選択した
    //   項目だけの ON/OFF が切り替わるようにして」 への対応で、 `_setSplitOpen
    //   (false)` (= 全閉) ではなく `_closeSplitRightPanelOnly()` (= 右のみ) を
    //   使う。 これで左パネルに別サービス (= ChatGPT 等) が入っていても、
    //   それは残したまま右の対象サービスだけが OFF になる。
    if (_splitOpen && _splitMode == 'web' && sameHost(_splitCurrentUrl)) {
      _closeSplitRightPanelOnly();
      return;
    }
    // ── 左パネルで同じサービスを開いている → 閉じる ──
    if (_splitLeftOpen &&
        _splitLeftMode == 'web' &&
        sameHost(_splitLeftCurrentUrl)) {
      _closeSplitLeftPanel();
      return;
    }
    // ── モバイル版は最初 50% の高さで開く (= ユーザー要望) ──
    // モバイルでは _splitPosition は bottom に強制マップされる (= 上下分割)
    //   ので、 `_splitPanelWidth` は実質的にパネルの「高さ」 として扱われる。
    //   画面高さの 50% に設定し、 上下がほぼ半分ずつ見える状態で開く。
    //   もっと広げたい / 狭めたいときはドラッグハンドルで調整する。
    if (!_isDesktop) {
      try {
        final mq = MediaQuery.of(context).size;
        _splitPanelWidth = mq.height * 0.5;
      } catch (_) {/* context 無効時は既存値を維持 */}
    }
    // ── どちらにも該当しなければ通常通り開く ──
    _openUrlInSplitPanel(url, isLeftPanel: isLeftPanel);
  }

  /// ヘッダーの ChatGPT / Gemini / Claude / DeepSeek / Grok ボタン等から
  /// 呼ばれる。
  ///
  /// [isLeftPanel]:
  /// - `true`  → 強制的に左パネルに開く
  /// - `false` → 強制的に右パネルに開く
  /// - `null`  → 自動振り分け。
  ///
  /// 自動振り分けのルール (= ユーザー要望「画面分割していない側に配置
  /// されるようにして、 両方配置されていたら右側に配置されるようにして」):
  ///   * 左パネルだけが空 (= 右だけ開いている)  → **左**に開く
  ///   * それ以外 (両方空、 左だけ開いている、 両方開いている) → **右**に開く
  ///
  /// 反対側のパネルが開いていてもそのまま残す (= 左右同時表示可能)。
  void _openUrlInSplitPanel(String url, {bool? isLeftPanel}) {
    final bool useLeft;
    if (isLeftPanel != null) {
      useLeft = isLeftPanel;
    } else {
      // 空いてる側に開く。 両方埋まってる場合は右を上書き。
      useLeft = _splitOpen && !_splitLeftOpen;
    }
    if (useLeft) {
      _splitLoadLeftUrl(url);
    } else {
      setState(() {
        _setSplitOpen(true);
      });
      _splitLoadUrl(url);
    }
  }

  /// Office ファイル (pptx / docx) を画面分割パネルで開くヘルパー。
  /// ユーザー要望: 「word もパワポも画面分割に対応させて」 への対応。
  ///
  /// [mode] は 'pptx' または 'docx' を想定。
  /// [isLeftPanel] が null の場合は自動振り分け (= 右が空 ? 左 : 右)。
  void _openOfficeInSplitPanel(String filePath, String fileName,
      {required String mode, bool? isLeftPanel}) {
    final bool useLeft;
    if (isLeftPanel != null) {
      useLeft = isLeftPanel;
    } else {
      useLeft = _splitOpen && !_splitLeftOpen;
    }
    if (useLeft) {
      setState(() {
        _splitLeftOpen = true;
        _splitLeftMode = mode;
        _splitLeftLocalOfficePath = filePath;
        _splitLeftOfficeFileName = fileName;
        // Office モード時は PDF/Web 用フィールドはクリア
        _splitLeftLocalPdfPath = null;
        _splitLeftCurrentUrl = '';
      });
    } else {
      setState(() {
        _setSplitOpen(true);
        _splitMode = mode;
        _splitLocalOfficePath = filePath;
        _splitOfficeFileName = fileName;
        _splitLocalPdfPath = null;
        _splitCurrentUrl = '';
      });
    }
    // ── ロード直後にメインへフォーカスを戻す (スクロール不可問題対策) ──
    // 開いた瞬間に Office Viewer 内の TextField や Listener にフォーカスが
    // 移り、 メインの InteractiveViewer が pointer event を受け取れなく
    // なる現象への対応。
    try {
      FocusManager.instance.primaryFocus?.unfocus();
    } catch (_) {}
  }

  /// 左画面分割ボタンの onTap ハンドラ。
  /// - 開いてなければ PDF 選択 or URL 入力で開く (= 選択肢ダイアログ)
  /// - 開いていれば閉じる
  /// ユーザー要望: 「左画面分割は PDF に限定する必要ない」。
  Future<void> _toggleSplitLeftPanel() async {
    if (_splitLeftOpen) {
      _closeSplitLeftPanel();
      return;
    }
    // 開く: 「PDF 選択」 か「URL 入力」 を選んでもらう
    if (!mounted) return;
    final choice = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E2E),
        title: Text(
            _isDesktop
                ? context.read<MindMapProvider>().t('split.leftTitle')
                : context.read<MindMapProvider>().t('split.topTitle'),
            style: const TextStyle(color: Colors.white)),
        content: Text(
          context.read<MindMapProvider>().t('split.pdfOrUrl'),
          style: const TextStyle(color: Colors.white70),
        ),
        actions: [
          TextButton.icon(
            icon: const Icon(Icons.file_open_rounded,
                color: Color(0xFFFF6B6B)),
            label: Text(context.read<MindMapProvider>().t('split.chooseFile'),
                style: TextStyle(color: Color(0xFFFF6B6B))),
            onPressed: () => Navigator.of(ctx).pop('file'),
          ),
          TextButton.icon(
            icon: const Icon(Icons.link_rounded, color: Color(0xFF6C63FF)),
            label: Text(context.read<MindMapProvider>().t('split.enterUrl'),
                style: TextStyle(color: Color(0xFF6C63FF))),
            onPressed: () => Navigator.of(ctx).pop('url'),
          ),
          TextButton(
            child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
            onPressed: () => Navigator.of(ctx).pop(null),
          ),
        ],
      ),
    );
    if (choice == 'file') {
      // PDF に加えて Excel / Word / PowerPoint も選べる (= ユーザー要望:
      // 左に PDF、 右に Excel のように別々のファイルを並べたい)。
      await _splitOpenLocalFile(leftPanel: true);
    } else if (choice == 'url') {
      if (!mounted) return;
      // URL 入力ダイアログ
      final urlCtrl = TextEditingController();
      final url = await showDialog<String>(
        context: context,
        builder: (ctx) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E2E),
          title: Text(context.read<MindMapProvider>().t('split.enterUrl'),
              style: const TextStyle(color: Colors.white)),
          content: TextField(
            controller: urlCtrl,
            autofocus: true,
            style: const TextStyle(color: Colors.white),
            decoration: const InputDecoration(
              hintText: 'https://example.com',
              hintStyle: TextStyle(color: Colors.white30),
            ),
            onSubmitted: (v) => Navigator.of(ctx).pop(v),
          ),
          actions: [
            TextButton(
              child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
              onPressed: () => Navigator.of(ctx).pop(null),
            ),
            TextButton(
              child: Text(context.read<MindMapProvider>().t('btn.open'),
                  style: const TextStyle(color: Color(0xFF6C63FF))),
              onPressed: () => Navigator.of(ctx).pop(urlCtrl.text),
            ),
          ],
        ),
      );
      if (url != null && url.trim().isNotEmpty) {
        _splitLoadLeftUrl(url);
      }
    }
  }

  // ─── PDF への書き込み (= ユーザー要望: テキストとチェック) ────────────
  /// 'none' | 'text' | 'check'。 モードが入っている間、 PDF をタップした
  /// 場所に書き込む。 左ペインとメインペインで別々に持つ。
  String _splitPdfAnnotMode = 'none';
  String _splitLeftPdfAnnotMode = 'none';
  bool _pdfWriteBusy = false;

  /// チェック (✓) の大きさ (= ユーザー要望: 既定は 10)。
  ///
  /// 旧版は「倍率」 (既定 1.0 / prefs 'pdfCheckScale') だったが、 描き込み
  /// パレット側の数字と揃えるため「大きさ」 に改めた (10 = 旧 4 倍相当)。
  /// 単位が変わったので prefs の鍵も変える (古い倍率をそのまま読むと
  /// 極端に小さくなってしまうため)。
  double _pdfCheckSize = 10.0;

  Future<void> _loadPdfCheckScale() async {
    try {
      final sp = await SharedPreferences.getInstance();
      final v = sp.getDouble('pdfCheckSize');
      if (v != null && mounted) {
        setState(() => _pdfCheckSize = v.clamp(1.0, 20.0));
      }
    } catch (_) {}
  }

  Future<void> _setPdfCheckScale(double v) async {
    setState(() => _pdfCheckSize = v.clamp(1.0, 20.0));
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setDouble('pdfCheckSize', _pdfCheckSize);
    } catch (_) {}
  }

  /// チェックの大きさを選ぶ小さなメニュー (= ユーザー要望)。
  Future<void> _showPdfCheckSizeMenu(Offset globalPos) async {
    final box = Overlay.of(context).context.findRenderObject() as RenderBox?;
    if (box == null) return;
    final sel = await showMenu<double>(
      context: context,
      color: const Color(0xFF1E1E2E),
      position: RelativeRect.fromRect(
          globalPos & const Size(1, 1), Offset.zero & box.size),
      items: [
        // 数字はパレットのスライダーと同じ「大きさ」 (既定 10)。
        for (final (v, label) in const [
          (2.5, '小さめ'),
          (5.0, 'ふつう'),
          (10.0, '大きめ (既定)'),
          (14.0, 'とても大きい'),
          (20.0, '特大'),
        ])
          PopupMenuItem<double>(
            value: v,
            height: 34,
            child: Row(children: [
              Icon(Icons.check_rounded,
                  size: (10 + v * 1.1).clamp(10.0, 28.0).toDouble(),
                  color: const Color(0xFFE57373)),
              const SizedBox(width: 10),
              Text('$label  (${v.toStringAsFixed(0)})',
                  style: TextStyle(
                      color: (_pdfCheckSize - v).abs() < 0.01
                          ? const Color(0xFF6C63FF)
                          : Colors.white,
                      fontSize: 12.5)),
            ]),
          ),
      ],
    );
    if (sel != null) await _setPdfCheckScale(sel);
  }

  /// PDF 図形・線 描き込みモード (= ユーザー要望)。 ペインごとに独立。
  bool _splitPdfDrawActive = false;
  bool _splitLeftPdfDrawActive = false;

  /// 書き込み後にビューアを読み直すための鍵 (ファイルが変わったため)。
  int _splitPdfReloadTick = 0;
  int _splitLeftPdfReloadTick = 0;

  Future<void> _handleSplitPdfTap(sf_pdf.PdfGestureDetails d,
      {required bool left}) async {
    final mode = left ? _splitLeftPdfAnnotMode : _splitPdfAnnotMode;
    if (mode == 'none' || _pdfWriteBusy) return;
    final path = left ? _splitLeftLocalPdfPath : _splitLocalPdfPath;
    final pageNo = d.pageNumber;
    final Offset pos = d.pagePosition;
    if (path == null || pageNo < 1) return;
    final provider = context.read<MindMapProvider>();
    String? text;
    if (mode == 'text') {
      text = await _promptPdfWriteText(provider);
      if (text == null || text.trim().isEmpty) return;
    }
    _pdfWriteBusy = true;
    bool ok;
    if (mode == 'text') {
      ok = await _PdfInkWriter.writeText(path, pageNo, pos, text!.trim());
    } else {
      ok = await _PdfInkWriter.writeCheck(path, pageNo, pos,
          size: _pdfCheckSize);
    }
    _pdfWriteBusy = false;
    if (!mounted) return;
    if (ok) {
      // ファイルが変わったので読み直す (ページは最終ページ記録で戻る)。
      setState(() {
        if (left) {
          _splitLeftPdfReloadTick++;
        } else {
          _splitPdfReloadTick++;
        }
      });
    } else {
      _appSnack(
        context,
        SnackBar(
            content: Text(provider.t('pdf.writeFailed')),
            backgroundColor: const Color(0xFFE57373)),
      );
    }
  }

  /// 分割ペインの PDF で最後に押した所 (画面座標)。 文字の箱をここへ出す。
  Offset? _splitPdfDownGlobal;

  /// 押した所にそのまま書き込める文字の箱を出す (= ユーザー要望: 「文字を
  /// 置く」 という項目や入力窓を出すのではなく、 パワーポイントと同じように
  /// クリックした場所へテキストボックスが現れて、 そのまま書けるように)。
  ///
  /// 箱の外を押すと確定、 Esc で取り消し。 戻り値は書いた文字 (取り消し /
  /// 空なら null)。 全画面ビューア側の PdfDrawLayer と同じ操作感に揃えてある。
  Future<String?> _promptPdfWriteText(MindMapProvider provider) {
    final completer = Completer<String?>();
    final ctrl = TextEditingController();
    final focus = FocusNode();
    final overlay = Overlay.of(context, rootOverlay: true);
    final scr = MediaQuery.sizeOf(context);
    final at = _splitPdfDownGlobal ??
        Offset(scr.width / 2 - 110, scr.height / 2 - 20);
    // 画面からはみ出さない位置へ寄せる。
    final left =
        at.dx.clamp(0.0, math.max(0.0, scr.width - 260.0)).toDouble();
    final top =
        at.dy.clamp(0.0, math.max(0.0, scr.height - 64.0)).toDouble();
    late final OverlayEntry entry;
    var done = false;
    void finish(String? v) {
      if (done) return;
      done = true;
      entry.remove();
      // 取り外した直後の dispose はビルド中に当たることがあるので 1 枚待つ。
      WidgetsBinding.instance.addPostFrameCallback((_) {
        ctrl.dispose();
        focus.dispose();
      });
      completer.complete((v == null || v.trim().isEmpty) ? null : v);
    }

    entry = OverlayEntry(
      builder: (_) => Stack(children: [
        // 箱の外を押したら確定する (中身が空なら取り消し扱い)。
        // opaque にして、 その押下が下の PDF まで抜けないようにする
        // (抜けると同じ操作で次の箱が開いてしまう)。
        Positioned.fill(
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () => finish(ctrl.text),
          ),
        ),
        Positioned(
          left: left,
          top: top,
          child: Material(
            color: Colors.transparent,
            child: ConstrainedBox(
              constraints: const BoxConstraints(minWidth: 150, maxWidth: 420),
              child: Container(
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.92),
                  border:
                      Border.all(color: const Color(0xFFE57373), width: 1.4),
                  borderRadius: BorderRadius.circular(3),
                ),
                padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                child: IntrinsicWidth(
                  child: Focus(
                    canRequestFocus: false,
                    skipTraversal: true,
                    onKeyEvent: (node, e) {
                      if (e is! KeyDownEvent) return KeyEventResult.ignored;
                      if (e.logicalKey == LogicalKeyboardKey.escape) {
                        finish(null);
                        return KeyEventResult.handled;
                      }
                      return KeyEventResult.ignored;
                    },
                    child: TextField(
                      controller: ctrl,
                      focusNode: focus,
                      autofocus: true,
                      style: const TextStyle(
                          color: Color(0xFFC81414),
                          // 焼き込む大きさ (25pt) に近い見た目にする
                          // (= ユーザー要望: 既定 25)。
                          fontSize: 22,
                          height: 1.2),
                      cursorColor: const Color(0xFFE57373),
                      decoration: InputDecoration(
                        isDense: true,
                        border: InputBorder.none,
                        hintText: provider.t('pdf.writeTextHint'),
                        hintStyle:
                            const TextStyle(color: Colors.black26, fontSize: 13),
                      ),
                      onSubmitted: finish,
                    ),
                  ),
                ),
              ),
            ),
          ),
        ),
      ]),
    );
    overlay.insert(entry);
    WidgetsBinding.instance.addPostFrameCallback((_) => focus.requestFocus());
    return completer.future;
  }

  /// 書き込みモードの切替ボタン (ペインごとのページ操作列に置く)。
  Widget _pdfWriteModeButtons({required bool left}) {
    final provider = context.read<MindMapProvider>();
    final mode = left ? _splitLeftPdfAnnotMode : _splitPdfAnnotMode;
    void toggle(String m) {
      setState(() {
        final cur = left ? _splitLeftPdfAnnotMode : _splitPdfAnnotMode;
        final next = cur == m ? 'none' : m;
        if (left) {
          _splitLeftPdfAnnotMode = next;
        } else {
          _splitPdfAnnotMode = next;
        }
        if (next != 'none') {
          _appSnack(
            context,
            SnackBar(
                content: Text(provider.t('pdf.writeHint')),
                duration: const Duration(seconds: 3)),
          );
        }
      });
    }

    Widget b(String m, IconData ic, String tip) => IconButton(
          tooltip: tip,
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
          icon: Icon(ic,
              size: 16,
              color: mode == m ? const Color(0xFFE57373) : Colors.white54),
          onPressed: () => toggle(m),
        );

    // ── 図形・線 描き込みモード (= ユーザー要望) ──
    // ON にするとペインの PDF 上に透明オーバーレイが出て、 ドラッグで
    // ペン / 直線 / 矢印 / 四角 / 楕円 を描ける (PdfDrawLayer)。
    final drawOn = left ? _splitLeftPdfDrawActive : _splitPdfDrawActive;
    final drawBtn = IconButton(
      tooltip: provider.t('pdf.drawShapes'),
      padding: EdgeInsets.zero,
      constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
      icon: Icon(Icons.draw_rounded,
          size: 16,
          color: drawOn ? const Color(0xFF5FD3B2) : Colors.white54),
      onPressed: () {
        setState(() {
          if (left) {
            _splitLeftPdfDrawActive = !_splitLeftPdfDrawActive;
            if (_splitLeftPdfDrawActive) _splitLeftPdfAnnotMode = 'none';
          } else {
            _splitPdfDrawActive = !_splitPdfDrawActive;
            if (_splitPdfDrawActive) _splitPdfAnnotMode = 'none';
          }
        });
        final on = left ? _splitLeftPdfDrawActive : _splitPdfDrawActive;
        if (on) {
          _appSnack(
            context,
            SnackBar(
                content: Text(provider.t('pdfdraw.hint')),
                duration: const Duration(seconds: 3)),
          );
        }
      },
    );

    return Row(mainAxisSize: MainAxisSize.min, children: [
      b('text', Icons.text_fields_rounded, provider.t('pdf.writeText')),
      // 右クリック / 長押しで大きさを選べる (= ユーザー要望)。
      GestureDetector(
        onSecondaryTapDown: (d) =>
            unawaited(_showPdfCheckSizeMenu(d.globalPosition)),
        onLongPressStart: (d) =>
            unawaited(_showPdfCheckSizeMenu(d.globalPosition)),
        child: b(
            'check',
            Icons.check_rounded,
            '${provider.t('pdf.writeCheck')} '
                '(大きさ: ${_pdfCheckSize.toStringAsFixed(0)} / '
                '右クリックで変更)'),
      ),
      drawBtn,
    ]);
  }

  /// 左パネル PDF 用のホイールイベント蓄積。
  /// 右パネルの `_wheelAccum` と同じ役割 (= デルタを溜めてしきい値超で動かす)
  /// だが、 こっちは「左パネル専用」 なので右と独立した状態を持つ。
  double _splitLeftWheelAccum = 0.0;

  /// 左パネル PDF のマウスホイール処理。
  /// 内部 syncfusion のスクロールも動くため、 ここでは「ページ送り」 を
  /// 追加で叩いて感度を底上げするだけ。 デルタ 80 で 1 ページ進む。
  /// アクティブパネル判定は不要 (= Listener が左パネル内に置かれている
  /// ので、 左パネル上のマウスイベントのみ届く)。
  void _onSplitLeftPdfWheel(PointerSignalEvent event) {
    if (event is! PointerScrollEvent) return;
    if (_splitLeftLocalPdfPath == null) return;
    _splitLeftWheelAccum += event.scrollDelta.dy;
    if (_splitLeftWheelAccum >= 80) {
      _splitLeftWheelAccum = 0;
      try {
        _splitLeftPdfController.nextPage();
      } catch (_) {}
    } else if (_splitLeftWheelAccum <= -80) {
      _splitLeftWheelAccum = 0;
      try {
        _splitLeftPdfController.previousPage();
      } catch (_) {}
    }
  }

  /// 分割パネルの Web ページを矢印/PageUp/Down キーでスクロールするための JS
  /// (= ユーザー要望: 分割した Web ページが上下キー/ホイールで動かない問題)。
  /// 対応しないキーは null。
  String? _webArrowScrollJs(LogicalKeyboardKey key) {
    if (key == LogicalKeyboardKey.arrowDown) return 'window.scrollBy(0,120);';
    if (key == LogicalKeyboardKey.arrowUp) return 'window.scrollBy(0,-120);';
    if (key == LogicalKeyboardKey.arrowLeft) return 'window.scrollBy(-120,0);';
    if (key == LogicalKeyboardKey.arrowRight) return 'window.scrollBy(120,0);';
    if (key == LogicalKeyboardKey.pageDown) {
      return 'window.scrollBy(0,Math.round(window.innerHeight*0.9));';
    }
    if (key == LogicalKeyboardKey.pageUp) {
      return 'window.scrollBy(0,-Math.round(window.innerHeight*0.9));';
    }
    return null;
  }

  /// 分割パネル (右/左) の Web ページにスクロール JS を流す。
  void _scrollSplitWeb(LogicalKeyboardKey key, {required bool left}) {
    final js = _webArrowScrollJs(key);
    if (js == null) return;
    try {
      if (!kIsWeb && Platform.isWindows) {
        if (left) {
          if (_splitLeftWinInitialized)
            _splitLeftWinController?.executeScript(js);
        } else {
          if (_splitWinInitialized) _splitWinController?.executeScript(js);
        }
      } else {
        (left ? _splitLeftIawController : _splitIawController)
            ?.evaluateJavascript(source: js);
      }
    } catch (_) {}
  }

  /// 分割パネルの Web ページをマウスホイールでスクロールする (= ユーザー要望)。
  /// webview_windows はホイールを内部スクロールに転送しないことがあるため、
  /// ホイール量を JS に渡して直接スクロールさせる (内部コンテナ対応は
  /// [_webWheelScrollJs] 参照)。
  void _scrollSplitWebByWheel(PointerSignalEvent event, {required bool left}) {
    if (event is! PointerScrollEvent) return;
    final dx = event.scrollDelta.dx.round();
    final dy = event.scrollDelta.dy.round();
    if (dx == 0 && dy == 0) return;
    final js = _webWheelScrollJs(dx, dy);
    try {
      if (!kIsWeb && Platform.isWindows) {
        if (left) {
          if (_splitLeftWinInitialized) {
            _splitLeftWinController?.executeScript(js);
          }
        } else {
          if (_splitWinInitialized) _splitWinController?.executeScript(js);
        }
      } else {
        (left ? _splitLeftIawController : _splitIawController)
            ?.evaluateJavascript(source: js);
      }
    } catch (_) {}
  }

  /// 画面分割パネルの位置 (右 / 左 / 上 / 下)。 上部ツールバーで切替。
  /// vertical (top/bottom) の時は PDF を横スクロール (= ページめくり) で表示。
  ///
  /// ── モバイル対応 (= ユーザー要望「モバイル版は左右の画面分割を辞めて
  ///   上下の分割にして」) ──
  /// 内部状態は `_splitPositionRaw` で保持し、 アクセスはこの getter/setter
  /// 経由に統一。 モバイルは縦長なので左右分割はせず、 上分割 / 下分割の
  /// 2 つを採用する (ユーザー要望)。 left→top / right→bottom にマップ。
  /// デスクトップは従来通り 4 方向。
  _SplitPosition _splitPositionRaw = _SplitPosition.right;
  _SplitPosition get _splitPosition {
    if (!_isDesktop) {
      // モバイル: 左右は使わず、 上 / 下 に振り分ける。
      if (_splitPositionRaw == _SplitPosition.left) {
        return _SplitPosition.top;
      }
      if (_splitPositionRaw == _SplitPosition.right) {
        return _SplitPosition.bottom;
      }
      // top / bottom はそのまま採用 (= 上分割・下分割の 2 択)
    }
    return _splitPositionRaw;
  }

  set _splitPosition(_SplitPosition v) {
    if (!_isDesktop) {
      if (v == _SplitPosition.left) {
        _splitPositionRaw = _SplitPosition.top;
        return;
      }
      if (v == _SplitPosition.right) {
        _splitPositionRaw = _SplitPosition.bottom;
        return;
      }
    }
    _splitPositionRaw = v;
  }

  /// マップ一覧 (Drawer) からマップタイルをドラッグ中かどうか。
  /// Draggable の onDragStarted/onDragEnd で更新。 グローバル pointer route
  /// で drop を検出するときに、 通常の click と区別するためのガード。
  bool _draggingMapPage = false;

  /// ドラッグ中のページデータ (= drop 先で使う)。
  _DrawerPageDragData? _currentDrawerDragData;

  /// ドラッグ中のグローバルポインタ位置 (= drop 位置の追跡用)。
  Offset _draggingPointerPos = Offset.zero;

  /// 画面分割パネルで開いた PDF/URL の履歴スタック (戻るボタン用)。
  /// 新規 URL を開くたびに push、 戻るボタンで pop。 最大 30 件保持。
  /// 各要素は (url, isLocalPdfPath, splitMode) の 3 つ組。
  final List<({String url, bool isLocal, String mode})> _splitHistory = [];

  /// 画面分割パネルの「進む」 用履歴。
  /// ユーザー要望「画面分割が上書きされたら開くのめんどくさいから
  ///   alt+←→ で以前画面分割で開いていた画面に戻って切り替えられるよう
  ///   にして欲しい」 への対応。
  /// Alt+← で 戻る (= history → forward へ移動)、 Alt+→ で 進む
  /// (= forward → history へ移動)。 新規 URL を開くと forward は
  /// クリアされる (= 一般的なブラウザの戻る/進む挙動)。
  final List<({String url, bool isLocal, String mode})> _splitForwardHistory =
      [];

  /// Alt+← で画面分割パネルを一つ前の URL/PDF に戻す。
  void _splitNavigateBack() {
    if (_splitHistory.isEmpty) {
      _showLockToast(
          context.read<MindMapProvider>().t('split.noBackHistory'));
      return;
    }
    // 現在のページを forward に push (= 進める履歴)
    if (_splitCurrentUrl.isNotEmpty) {
      _splitForwardHistory.add((
        url: _splitCurrentUrl,
        isLocal: _splitLocalPdfPath != null,
        mode: _splitMode,
      ));
      if (_splitForwardHistory.length > 30) {
        _splitForwardHistory.removeAt(0);
      }
    }
    // history から pop して開く
    final prev = _splitHistory.removeLast();
    _splitLoadUrlPreserveForward(prev.url);
  }

  /// Alt+→ で画面分割パネルを一つ進めた URL/PDF に戻す。
  void _splitNavigateForward() {
    if (_splitForwardHistory.isEmpty) {
      _showLockToast(
          context.read<MindMapProvider>().t('split.noForwardHistory'));
      return;
    }
    if (_splitCurrentUrl.isNotEmpty) {
      _splitHistory.add((
        url: _splitCurrentUrl,
        isLocal: _splitLocalPdfPath != null,
        mode: _splitMode,
      ));
      if (_splitHistory.length > 30) _splitHistory.removeAt(0);
    }
    final next = _splitForwardHistory.removeLast();
    _splitLoadUrlPreserveForward(next.url);
  }

  /// `_splitLoadUrl` のラッパー: ロード時に forward history を消さない。
  /// (= back/forward ナビゲーション中は forward を消さずに維持する)
  void _splitLoadUrlPreserveForward(String url) {
    _suppressForwardClear = true;
    try {
      _splitLoadUrl(url);
    } finally {
      _suppressForwardClear = false;
    }
  }

  /// forward history をクリアしないフラグ (back/forward ナビ中のみ true)。
  bool _suppressForwardClear = false;

  /// ユーザーが無効化したショートカットの ID 集合。
  /// `_commandForKeyCombo` 内で skip するために参照する。
  final Set<String> _disabledShortcuts = {};

  /// 画面分割パネルを開いた時の元ノード ID。
  /// `_showInAppViewer` の「画面分割で開く」 ボタン経由で開かれた時に、
  /// nodeId が分かっていればここに保存。 「全画面表示に戻る」 ボタンで
  /// `_showInAppViewer` を再度呼ぶときに、 この nodeId を渡してメモ
  /// パネルが表示されるようにする。
  /// 画面分割を閉じる時に null にリセット。
  String? _splitOriginNodeId;

  /// 左パネル版の元ノード ID (= ユーザー要望: PDF を左分割で開いた後に
  /// 全画面へ戻すとメモ欄が出せなくなる問題の修正)。 左パネルから
  /// 「全画面で開き直す」 時にこの nodeId を渡してメモパネルを復活させる。
  String? _splitLeftOriginNodeId;

  // ─── 画面分割パネル PDF: ページ移動オーバーレイ ───────────────────
  /// 画面分割パネルで開いている PDF の現在ページ番号。
  /// onPageChanged で更新。 ヘッダ等で表示するために保持する。
  int _splitPdfCurrentPage = 0;

  /// 画面分割パネルで開いている PDF の総ページ数。
  /// onDocumentLoaded で取得して保持。
  int _splitPdfTotalPages = 0;

  /// 「N / M ページ」 をオーバーレイ表示中かどうか。
  /// 3 秒経ったら自動で false に戻る。
  bool _splitPdfPageOverlayVisible = false;

  /// オーバーレイ自動消去用タイマー。
  Timer? _splitPdfPageOverlayTimer;

  /// ページ変更時にオーバーレイを 3 秒間表示する。
  void _showSplitPdfPageOverlay() {
    _splitPdfPageOverlayTimer?.cancel();
    if (!mounted) return;
    setState(() => _splitPdfPageOverlayVisible = true);
    _splitPdfPageOverlayTimer = Timer(const Duration(seconds: 3), () {
      if (!mounted) return;
      setState(() => _splitPdfPageOverlayVisible = false);
    });
  }

  /// 画面分割パネルを開く/閉じる。
  /// 画面分割を閉じた時の PDF 最終ページ番号 (= 開き直し時の復元用)。
  /// null なら未保存。
  int? _splitLastPdfPage;

  /// モバイル: 上分割 / 下分割 ボタン用。 指定位置で開く / 同じ位置なら閉じる。
  /// (ユーザー要望: モバイルは左右分割ではなく上下分割の 2 ボタン)。
  void _mobileOpenSplitAt(bool top) {
    final pos = top ? _SplitPosition.top : _SplitPosition.bottom;
    if (_splitOpen && _splitPosition == pos) {
      _toggleSplitPanel(); // 同じ位置で開いていればトグルで閉じる
      return;
    }
    setState(() => _splitPosition = pos);
    if (!_splitOpen) _toggleSplitPanel(); // 閉じていれば開く
  }

  void _toggleSplitPanel() {
    final willOpen = !_splitOpen;
    if (!willOpen) {
      // ── 閉じる前に PDF の現在ページを保存 ──
      // 次回開いた時に同じページから再開できるように。
      try {
        if (_splitMode == 'pdf' && _splitCurrentUrl.isNotEmpty) {
          _splitLastPdfPage = _splitPdfController.pageNumber;
        }
      } catch (_) {/* PDF 未ロードの時は例外を握りつぶす */}
    }
    setState(() {
      _splitOpen = willOpen;
      // ★ 閉じる時に hover フラグもクリア ★
      // 旧不具合: PDF パネル側にマウスがある状態で画面分割を閉じると、
      //          _splitPanelHover=true のまま残り、 _pauseViewer が true で
      //          panEnabled/scaleEnabled が false → マップがスクロールできない
      //          状態に陥る。 閉じた瞬間に false に戻して復活させる。
      if (!willOpen) {
        _splitPanelHover = false;
        // 他の「ビューアを止める」 系フラグも安全側に倒す
        // (= ドラッグ/範囲選択/長押し が画面分割パネルの上で中断された場合、
        //   そのまま残ってマップ操作が無効になることを防ぐ)
        _canvasLongPressActive = false;
        _rangeDragging = false;
        _rangeStart = null;
        _rangeEnd = null;
        // 元ノード ID もリセット (= 「全画面表示に戻る」 で消費済み or
        // ユーザーが × で閉じた = もうリンクなし)
        _splitOriginNodeId = null;
      }
    });
    // 閉じた直後の次フレームで、 マップ側のキー入力 Focus を要求し直す
    // (= 画面分割側のフォーカスが残ったままだと、 矢印キー等が
    //   マップに届かない問題を回避)
    if (!willOpen) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          try {
            FocusScope.of(context).requestFocus(FocusNode());
            FocusManager.instance.primaryFocus?.unfocus();
          } catch (_) {}
        }
      });
    }
    if (willOpen && _splitCurrentUrl.isEmpty) {
      _splitLoadUrl('https://www.google.com');
    } else if (willOpen && _splitMode == 'web') {
      // ── Web モード復元 ──
      // 起動時に _loadSplitPanelLastUrl で _splitCurrentUrl はセットされる
      // が、 WebView はその時まだ build されていないので URL がロード
      // されていない。 画面分割を開いた瞬間に明示的に loadUrl する必要が
      // ある。 次フレームで WebView が build された後に実行。
      final restoreUrl = _splitCurrentUrl;
      WidgetsBinding.instance.addPostFrameCallback((_) async {
        // コントローラの生成を待つ (= 最大 2 秒)
        for (int i = 0; i < 20; i++) {
          await Future<void>.delayed(const Duration(milliseconds: 100));
          if (!mounted || !_splitOpen) return;
          try {
            if (_isDesktop && Platform.isWindows && _splitWinInitialized) {
              await _splitWinController?.loadUrl(restoreUrl);
              return;
            }
            if (_splitIawController != null) {
              await _splitIawController!.loadUrl(
                  urlRequest: iaw.URLRequest(url: iaw.WebUri(restoreUrl)));
              return;
            }
          } catch (_) {/* まだ初期化中。 リトライ */}
        }
      });
    } else if (willOpen && _splitMode == 'pdf' && _splitLastPdfPage != null) {
      // ── 開いた直後に最後のページに復元 ──
      // SfPdfViewer のロード完了後に jumpToPage する必要があるので、
      // postFrameCallback で次フレーム以降に実行。
      final targetPage = _splitLastPdfPage!;
      WidgetsBinding.instance.addPostFrameCallback((_) async {
        // ローダーが完了するまで複数回試す (= 最大 2 秒間 リトライ)
        for (int i = 0; i < 20; i++) {
          await Future<void>.delayed(const Duration(milliseconds: 100));
          if (!mounted || !_splitOpen) return;
          try {
            _splitPdfController.jumpToPage(targetPage);
            return;
          } catch (_) {/* まだロード中。 リトライ */}
        }
      });
    }
  }

  /// 永続化された最後の画面分割 URL を SharedPreferences から復元する。
  Future<void> _loadSplitPanelLastUrl() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final saved = prefs.getString('split_panel_last_url');
      if (!mounted) return;
      if (saved == null || saved.isEmpty) return;
      // ── PDF/Web の判定 + ローカルファイルパス検出 ──
      // 旧不具合: PDF モードで復元する時、 ローカルパス (C:\... 等) を
      //          `_splitLocalPdfPath` にセットしていなかったため、
      //          SfPdfViewer.network() に C:\ パスを渡してしまい、
      //          ファイルが開けず「何も表示されない」 状態になっていた。
      final isPdf = saved.toLowerCase().endsWith('.pdf');
      final isWinLocal = RegExp(r'^[a-zA-Z]:[\\/]').hasMatch(saved);
      final isLocalFile =
          isWinLocal || saved.startsWith('file://') || saved.startsWith('/');
      setState(() {
        _splitCurrentUrl = saved;
        _splitUrlCtrl.text = saved;
        _splitMode = isPdf ? 'pdf' : 'web';
        _splitHasVideo = !isPdf && _isLikelyVideoUrl(saved);
        // ローカル PDF なら _splitLocalPdfPath にセットしておく
        // → 画面分割を開いた瞬間、 `_buildSplitContent` の PDF 分岐で
        //   `SfPdfViewer.file(File(_splitLocalPdfPath!))` が機能する。
        _splitLocalPdfPath = (isPdf && isLocalFile) ? saved : null;
      });
    } catch (_) {}
  }

  /// ユーザーが無効化したショートカットを復元。
  Future<void> _loadDisabledShortcuts() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final list = prefs.getStringList('disabled_shortcuts');
      if (!mounted) return;
      if (list != null && list.isNotEmpty) {
        setState(() {
          _disabledShortcuts
            ..clear()
            ..addAll(list);
        });
      }
    } catch (_) {}
  }

  /// 無効化リストを SharedPreferences に保存。
  Future<void> _persistDisabledShortcuts() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setStringList(
          'disabled_shortcuts', _disabledShortcuts.toList());
    } catch (_) {}
  }

  /// カスタムキーバインドを SharedPreferences から読み込む (= ユーザー要望:
  ///   割り当てたショートカットが再起動後も残るように。 旧実装はセッション限り
  ///   でメモリ上にしか保持していなかった)。
  Future<void> _loadCustomKeyBindings() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString('custom_key_bindings');
      if (raw == null || raw.isEmpty) return;
      final decoded = jsonDecode(raw);
      if (decoded is! Map) return;
      final sanitized = _sanitizeCustomKeyBindings(decoded);
      if (!mounted) return;
      setState(() {
        _customKeyBindings
          ..clear()
          ..addAll(sanitized);
      });
      // 旧版で保存できていた固定キーとの衝突や重複を、そのまま次回へ
      // 持ち越さない。値が同じ場合の上書きは SharedPreferences の no-op。
      await prefs.setString('custom_key_bindings', jsonEncode(sanitized));
    } catch (_) {}
  }

  /// カスタムキーバインドを SharedPreferences に保存。
  Future<void> _persistCustomKeyBindings() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(
          'custom_key_bindings', jsonEncode(_customKeyBindings));
    } catch (_) {}
  }

  /// 保存済みのカスタム割り当てを、現在のコマンド定義に合わせて安全化する。
  ///
  /// - 存在しない / 固定コマンドの ID は無視
  /// - 固定・予約キーとの衝突は無視
  /// - 同じ実効キーが複数コマンドに割り当てられた場合、デフォルト所有者を
  ///   優先し、それ以外はデフォルトへ戻す
  Map<String, String> _sanitizeCustomKeyBindings(Map<dynamic, dynamic> raw) {
    final definitionsById = <String, Map<String, dynamic>>{
      for (final cmd in _assignableCommandDefs) (cmd['id']! as String): cmd,
    };
    final sanitized = <String, String>{};

    raw.forEach((key, value) {
      if (key is! String || value is! String) return;
      final cmd = definitionsById[key];
      if (cmd == null || _fixedCommands.contains(key)) return;
      final trimmed = value.trim();
      final normalized = _normalizeShortcutCombo(trimmed);
      if (normalized.isEmpty ||
          _nonAssignableShortcutCombos.contains(normalized)) {
        return;
      }
      final defaultKey = cmd['defaultKey']! as String;
      if (normalized == _normalizeShortcutCombo(defaultKey)) return;
      sanitized[key] = trimmed;
    });

    // 衝突を 1 件解消すると、そのコマンドがデフォルトへ戻った結果として
    // 別の衝突が現れる場合があるため、安定するまで繰り返す。
    var changed = true;
    while (changed) {
      changed = false;
      final ownersByKey = <String, List<String>>{};
      for (final cmd in _assignableCommandDefs) {
        final id = cmd['id']! as String;
        if (_fixedCommands.contains(id)) continue;
        final effective = _normalizeShortcutCombo(
            sanitized[id] ?? (cmd['defaultKey']! as String));
        if (effective.isEmpty) continue;
        ownersByKey.putIfAbsent(effective, () => <String>[]).add(id);
      }
      for (final entry in ownersByKey.entries) {
        final owners = entry.value;
        if (owners.length < 2) continue;
        String keep = owners.first;
        for (final id in owners) {
          final cmd = definitionsById[id]!;
          if (_normalizeShortcutCombo(cmd['defaultKey']! as String) ==
              entry.key) {
            keep = id;
            break;
          }
        }
        for (final id in owners) {
          if (id != keep && sanitized.remove(id) != null) changed = true;
        }
      }
    }
    return sanitized;
  }

  /// 現在有効なパネル幅 (画面幅の 25〜85% にクランプ)。
  double _splitPanelEffectiveWidth(BuildContext context) {
    if (!_splitOpen) return 0;
    final w = MediaQuery.of(context).size.width;
    // 最大 90% (= ドラッグ時の clamp と一致。 常にマップ側が見える)。
    return _splitPanelWidth.clamp(w * 0.25, w * 0.90).toDouble();
  }

  /// 現在のパネル位置に応じた有効サイズ。
  /// 左右分割 → 幅 (画面幅基準)、 上下分割 → 高さ (画面高さ基準)。
  /// 上下分割のクランプ範囲は 25〜85% (= 左右と同じ感覚)。
  double _splitPanelEffectiveSize(BuildContext context) {
    if (!_splitOpen) return 0;
    final size = MediaQuery.of(context).size;
    // ── Office モード (pptx/docx/xlsx) の最小幅補正 ──
    // ユーザー要望「pptx ファイルを画面分割して、 表示領域の大きさを一定
    //   以上小さくすると項目が画面分割画面からはみ出して押せなくなって
    //   しまうから、 項目がはみ出る大きさまで表示領域を小さくできないように
    //   して」 への対応。 計算上の min が 480/360 を下回らないようにする。
    final isOfficeMode =
        _splitMode == 'pptx' || _splitMode == 'docx' || _splitMode == 'xlsx';
    if (_splitPosition == _SplitPosition.top ||
        _splitPosition == _SplitPosition.bottom) {
      final dynamicMin = size.height * 0.25;
      final floor = isOfficeMode ? math.max(360.0, dynamicMin) : dynamicMin;
      // 上分割はヘッダーの下から始まるので、 その分だけ上限を下げる
      // (= ヘッダーを避けた結果、 下側がはみ出すのを防ぐ)。
      final headerBottom = _splitPosition == _SplitPosition.top
          ? MediaQuery.of(context).padding.top + kToolbarHeight
          : 0.0;
      final ceil = math.max(floor, size.height * 0.95 - headerBottom);
      return _splitPanelWidth.clamp(floor, ceil).toDouble();
    }
    final dynamicMin = size.width * 0.25;
    final floor = isOfficeMode ? math.max(580.0, dynamicMin) : dynamicMin;
    return _splitPanelWidth.clamp(floor, size.width * 0.90).toDouble();
  }

  /// URL 入力欄から「開く」 が押された時の処理。
  void _splitLoadUrl(String raw) {
    var url = raw.trim();
    if (url.isEmpty) return;
    // ── ① Windows ローカルパス検出 ──
    // 例: `C:\Users\foo\doc.pdf` / `D:/data/x.pdf` のような
    // ドライブ文字 + コロン + スラッシュ で始まるもの。
    // これに `https://` を付けてしまうと『https://C:\...』 という壊れた
    // URL になり、 ローカル PDF が開けなくなる。
    final isWinLocal = RegExp(r'^[a-zA-Z]:[\\/]').hasMatch(url);
    // ── _splitLoadUrl は「右パネルに表示」 のみ ──
    // ユーザー要望: 「ctrl+\を押したら今見ているPDFが画面の右側に、
    // ctrl+^を押したら画面の左側に表示」。
    // 自動振り分け (= 既存 PDF があれば左にずらす) は削除。
    // 左パネルへのロードは `_splitLoadLeftPdf` / `_splitLoadLeftUrl` を
    // 直接呼ぶことで行う (= ショートカット側で振り分け制御)。
    // スキーマ補完 (= http/https/file/絶対パス/Windows ドライブ パス
    // のどれでもない場合のみ https を付ける)
    if (!url.startsWith('http://') &&
        !url.startsWith('https://') &&
        !url.startsWith('file://') &&
        !url.startsWith('/') &&
        !isWinLocal) {
      url = 'https://$url';
    }
    // YouTube → そのまま watch URL で開く。 embed への変換は廃止。
    // 理由: Android の WebView で `youtube.com/embed/...` を開くと、
    //       「動画を YouTube アプリで開く」 系のリダイレクトや
    //       X-Frame-Options 制約で表示エラーになりがちなため。
    // watch URL なら YouTube 側がモバイル UI を返してそのまま再生できる。
    // (旧: ytId != null なら url = 'https://www.youtube.com/embed/$ytId';)
    // PDF 判定 (拡張子)
    final isPdf = url.toLowerCase().endsWith('.pdf');
    // ローカルファイル判定: Windows ドライブパス / file:// / Unix 絶対パス
    final isLocalFile =
        isWinLocal || url.startsWith('file://') || url.startsWith('/');
    // ── OAuth ポップアップが動かないサイトは外部ブラウザへ ──
    // ユーザー報告「Claude に Google 垢からログインしようとすると暗転して
    //   しまって先に進めない」 への対応。 claude.ai 等は子ウィンドウ
    //   ポップアップを要求するが webview_windows は対応しないため、
    //   そのサイトだけアプリ内ビューアではなく外部ブラウザで開く。
    //   PDF は除外 (= 外部 PDF 直リンクは普通にアプリ内で見せたい)。
    if (!isPdf && !isLocalFile && _isOAuthBlockedUrl(url)) {
      final uri = Uri.tryParse(url);
      if (uri != null) {
        try {
          launchUrl(uri, mode: LaunchMode.externalApplication);
          if (mounted) {
            _appSnack(
              context,
              SnackBar(
                content: Text(
                    context.read<MindMapProvider>().t('split.openedExternal')),
                backgroundColor: Color(0xFF6C63FF),
                duration: Duration(seconds: 3),
              ),
            );
          }
          return;
        } catch (_) {}
      }
    }
    setState(() {
      // ── 右パネルを開く ──
      // ユーザー要望「両画面分割の状態から ⇄ を押すと左側の画面が消えて
      //   右の画面が左に来るだけになってしまっている」 への修正:
      //   旧コードでは _splitOpen を別経路 (= _setSplitOpen(true)) でしか
      //   セットしていなかったため、 スワップ復元時にこのメソッドだけ
      //   呼ぶと右パネルが開かなかった。 ここで明示的に立てる。
      _setSplitOpen(true);
      // ── 新しい URL を開く前に、 現在のページを履歴に push ──
      // (空でないとき。 初回ロードは履歴を作らない)。
      if (_splitCurrentUrl.isNotEmpty && _splitCurrentUrl != url) {
        _splitHistory.add((
          url: _splitCurrentUrl,
          isLocal: _splitLocalPdfPath != null,
          mode: _splitMode,
        ));
        if (_splitHistory.length > 30) {
          _splitHistory.removeAt(0);
        }
        // ── 新規操作で進む履歴をクリア (= ブラウザの戻る/進む同様) ──
        // ただし Alt+← / Alt+→ ナビゲーション中は維持する。
        if (!_suppressForwardClear) {
          _splitForwardHistory.clear();
        }
      }
      _splitCurrentUrl = url;
      // ローカル PDF なら _splitLocalPdfPath にパスを入れる → SfPdfViewer
      // がローカルファイルとして読み込めるようになる。 リモート PDF (= URL)
      // は null のまま。
      _splitLocalPdfPath = (isPdf && isLocalFile) ? url : null;
      _splitMode = isPdf ? 'pdf' : 'web';
      _splitHasVideo = !isPdf && _isLikelyVideoUrl(url);
      _splitUrlCtrl.text = url;
    });
    // Platform 別の WebView コントローラに loadUrl (PDF 以外の時)
    if (!isPdf) {
      if (_isDesktop && Platform.isWindows && _splitWinInitialized) {
        _splitWinController?.loadUrl(url);
      }
      _splitIawController?.loadUrl(
          urlRequest: iaw.URLRequest(url: iaw.WebUri(url)));
      _scheduleSplitVideoProbe(leftPanel: false);
    }
    _persistSplitPanelLastUrl(url);
  }

  /// 最後に開いた URL を SharedPreferences に保存。
  Future<void> _persistSplitPanelLastUrl(String url) async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('split_panel_last_url', url);
    } catch (_) {}
  }

  /// ローカル PDF ファイル選択。
  /// 分割ペインへ任意のファイルを開く (= ユーザー要望: 左に PDF、 右に
  /// Excel のように別々のファイルを並べたい)。 PDF / Excel / CSV / Word /
  /// PowerPoint に対応。
  Future<void> _splitOpenLocalFile({required bool leftPanel}) async {
    final provider = context.read<MindMapProvider>();
    try {
      final result = await FilePicker.platform.pickFiles(
        dialogTitle: provider.t('split.chooseFile'),
        type: FileType.custom,
        allowedExtensions: ['pdf', 'xlsx', 'xls', 'csv', 'tsv', 'docx', 'pptx', 'txt'],
      );
      final path = result?.files.single.path;
      if (path == null || !mounted) return;
      final name = path.replaceAll('\\', '/').split('/').last;
      final ext =
          name.contains('.') ? name.split('.').last.toLowerCase() : '';
      if (ext == 'pdf') {
        if (leftPanel) {
          _splitLoadLeftPdf(path);
        } else {
          setState(() {
            _setSplitOpen(true);
            _splitLocalPdfPath = path;
            _splitCurrentUrl = path;
            _splitMode = 'pdf';
            _splitLocalOfficePath = null;
            _splitHasVideo = false;
            _splitUrlCtrl.text = path;
          });
        }
        return;
      }
      final mode = ext == 'docx'
          ? 'docx'
          : ext == 'pptx'
              ? 'pptx'
              : ext == 'txt'
                  ? 'txt' // テキストエディタ (= ユーザー要望)
                  : 'xlsx'; // xlsx / csv は表計算ビューア
      _openOfficeInSplitPanel(path, name, mode: mode, isLeftPanel: leftPanel);
    } catch (e) {
      debugPrint('分割ペインのファイル選択失敗: $e');
    }
  }

  @override
  void initState() {
    super.initState();
    _bottomToolbarExpandedNotifier.value = _bottomBarOpen;
    WidgetsBinding.instance.addObserver(this);
    // ── PDF への描き込みが焼き込まれたらサムネイルを作り直す ──
    //    (= ユーザー報告: PDF の上に手書きしてもサムネイルに反映されない)。
    //    ビューアを閉じた時の自動保存でも飛んでくるので、 画面側で受ける。
    pdfDrawBurnedNotifier.addListener(_onPdfDrawBurned);
    // SnackBar をドロワーより手前に出すために共有する (= ユーザー要望)。
    appMainScaffoldKey = _scaffoldKey;
    // ── 本体が起きていない間にフローティングメモから頼まれた「マップに
    //    追加」 を取り込む (= ユーザー要望)。 読み込みが済んでから。 ──
    WidgetsBinding.instance.addPostFrameCallback((_) {
      // ignore: discarded_futures
      _drainPendingFloatingMemos();
    });
    // ── トークン切れの時に、 文言だけでなくチャージの画面まで案内する
    //    (= ユーザー要望)。 短い間に何度も断られても 1 回だけ出す。 ──
    context.read<MindMapProvider>().onCreditShort = _onCreditShort;
    // ignore: discarded_futures
    _loadMiniMapPref();
    // ── 「プログラムから開く」 で渡されたファイルを処理する (= ユーザー要望)。
    //    最初のフレームが出てから聞く (起動直後だとダイアログを出せない)。
    if (pendingOpenFilePaths.isNotEmpty) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        // ignore: discarded_futures
        _handlePendingOpenFiles();
      });
    }
    // ── 起動中に 2 個目の「アプリで開く」 から引き渡されたファイルを開く ──
    // (= ユーザー要望: 新規でアプリを立ち上げず、 既に開いている画面の上で
    //  表示する)。 main() の待ち受けが pendingOpenFilePaths に足して
    //  この tick を増やす。
    if (_isDesktop) {
      openWithFilesTick.addListener(_onOpenWithFilesArrived);
      // ── フローティング AI 窓 (別プロセス) からの「AI アシスタントを
      //    開いて」 を受ける (= ユーザー要望) ──
      assistantRequestFromFloating.addListener(_onAssistantRequested);
      // ── ショートカットからの「このボタンを実行して」 を受ける
      //    (= ユーザー要望: ボタンを一発で呼び出すショートカット) ──
      commandRequestFromShortcut.addListener(_onShortcutCommandRequested);
      // DM 未読の変化を受けてバッジを描き直す (= ユーザー要望)。
      serviceBadgeTick.addListener(_onServiceBadgeChanged);
      // ── 外の窓 (別プロセス) を分割ペインの上に置いて放した時の受け口
      //    (= ユーザー要望: 外に出した YouTube を分割画面の上に置いたら
      //     そのペインに埋め込まれる) ──
      floatingWindowDropProbe = _handleFloatingWindowDrop;
      // ── 別プロセスのメモ窓 (ショートカット起動) からの頼みごと ──
      //    (= ユーザー報告: マップに追加しようとすると「追加できるページが
      //     ありません」 と出る)。
      floatingMemoBridge = _handleFloatingMemoBridge;
    }
    // ── ショートカットから起動された時、 そのボタンを実行する ──
    //    Windows は起動引数、 Android は intent の extra から拾う。
    //    画面が組み上がってから実行したいので次のフレームで。
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      if (!mounted) return;
      final id = await HomeShortcutService.initialCommandId();
      if (!mounted || id == null || id.isEmpty) return;
      _runShortcutCommand(id);
    });
    // 既に起動中にホーム画面のショートカットが押された時 (Android)。
    HomeShortcutService.setOpenCommandHandler(_runShortcutCommand);
    // ── デスクトップの購入状態をサーバーと同期 ──
    // Stripe の決済は外部ブラウザで完結するので、 起動時に Cloudflare Worker
    // の権利 API を読んで最新のプランを取り込む。
    if (_isDesktop) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        // ignore: discarded_futures
        context.read<MindMapProvider>().syncEntitlementFromServer();
      });
      // フローティングメモ / AI (サブウィンドウ) からの呼び出しを受ける
      // (= ユーザー要望: メモを AI に渡す / マップに追加 / フォーカス返却)。
      try {
        DesktopMultiWindow.setMethodHandler(_onSubWindowCall);
      } catch (_) {}
    }
    // ── 有料プラン誘導モーダルの共通入口を登録 (= ユーザー要望: 有料プラン
    //    が必要な機能に触れた時は誘導モーダルを出す)。 別ウィジェット
    //    (Google 検索の自動操作など) からもここ経由で同じモーダルが開く。 ──
    paywallPresenter = (ctx, message) {
      if (!mounted) return;
      _showPaywallDialog(context.read<MindMapProvider>(),
          bodyOverride: message);
    };
    _inlineShelfEditFocus.addListener(_handleShelfInlineFocusChanged);
    _inlineNodeEditFocus.addListener(_handleNodeInlineFocusChanged);
    _loadReferencePositions();
    // 「次のN件を表示」ノードのタップ情報を SharedPreferences から復元する。
    // この情報はメモリ常駐の Map (= _playlistLoadMoreInfo) に格納されるが、
    // アプリ再起動や別マップに移動した State 再構築では失われるため、
    // 永続化しないと再起動後にロードモアノードを押しても無反応になる。
    _loadLoadMoreInfo();
    // 画面分割パネルで「最後に開いた URL」 を SharedPreferences から復元。
    // 復元できれば次に分割を開いた瞬間にその URL がロードされる。
    _loadSplitPanelLastUrl();
    // 分割パネルの「動画を縦いっぱいに伸ばす」 設定も復元 (= ユーザー要望)。
    _loadSplitVideoFillMode();
    // ユーザーが無効化したショートカットの一覧も復元。
    _loadDisabledShortcuts();
    // チェック (✓) の大きさを読む (= ユーザー要望)。
    unawaited(_loadPdfCheckScale());
    _loadMapSplitPrefs();
    // カスタムキーバインド (割り当て変更) も復元。
    _loadCustomKeyBindings();
    // フラッシュカード生成設定 (問題形式・枚数) を復元。
    _loadFlashcardGenSettings();
    // アラームを復元して再スケジュール (= 再起動後も鳴るように)。
    _loadAlarms();
    // 手動登録したサブスクリプションと支払日前通知を復元。
    _loadManagedSubscriptions();
    // タイムラインの睡眠時間 (圧縮表示) 設定を復元。
    _loadSleepTime();
    // ── モバイルは画面分割の既定を「上分割」 にする (= ユーザー要望) ──
    // _splitPositionRaw は left→top にマップされるので、 モバイルでは left を
    //   既定にして上分割で開く (デスクトップは従来通り右分割)。
    if (!_isDesktop) {
      _splitPositionRaw = _SplitPosition.left;
    }
    // ヘッダー/フッターの「お気に入り 1〜5」 ボタンの表示情報
    // (ラベル + アイコン) を読み込む。 Google 検索で編集された内容を
    // 反映するために、 開く/戻る タイミングでも再読み込みする。
    _refreshCustomPagesCache();
    // 動的に作られたブックマークボタン (= 'bookmark:<hex>') の表示情報を読み込む。
    _loadBookmarkButtons();
    // ユーザーが右クリックで変更したカスタム項目のアイコンを読み込む。
    _loadCustomIconOverrides();
    // アップロードされた独自アイコン画像を読み込む (= ユーザー要望)。
    _loadCustomIconImages();
    // ボタンごとの開き方 (全画面 / 画面分割) を読み込む (= ユーザー要望)。
    unawaited(_commandOpenStylesReady);
    // ── ホーム画面ショートカットからの起動 (アプリ既に起動中) ──
    // ショートカットがタップされたら、 そのマップ(ページ)へ切り替える。
    HomeShortcutService.setOpenPageHandler((pageId) {
      if (!mounted) return;
      context.read<MindMapProvider>().openPageById(pageId);
    });
    WidgetsBinding.instance.addPostFrameCallback((_) => _centerOnRoot());
    // ── 集中ロックのスケジュール監視 (Android のみ) ──
    // 30 秒ごとに現在時刻が設定した時間枠に入ったかを確認し、 入っていれば
    // 全画面ロックを起動する。 起動直後にも一度チェックする。
    if (!kIsWeb && Platform.isAndroid) {
      _focusLockScheduleTimer = Timer.periodic(
          const Duration(seconds: 30), (_) => _checkFocusLockSchedule());
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _checkFocusLockSchedule();
      });
    }
    // ── ジオフェンス画面ロックの監視 (モバイル専用) ──
    // 確定地点から半径 N km の出入りで集中ロックを起動する。 機能が無効なら
    // _checkGeofence は即 return する (= GPS は有効時のみ取得)。
    // 画面ロック / 集中ロックはモバイル専用 (= ユーザー要望: Windows では無効)。
    if (!kIsWeb && Platform.isAndroid) {
      _geofenceTimer =
          Timer.periodic(const Duration(seconds: 30), (_) => _checkGeofence());
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _checkGeofence();
      });
    }
    // ページ切替時に自動で基準位置を中央に
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final provider = context.read<MindMapProvider>();
      // アプリ機能と文書ファイル作成を MCP へ預ける (= アシスタントを
      //   開かなくても外部の MCP から使えるように)。
      _registerMcpHandlers(provider);
      // 録画の保存先 (= ユーザー要望) を読み込む。
      // ignore: discarded_futures
      _loadRecSaveDir();
      _lastPageIndexForCenter = provider.currentPageIndex;
      provider.addListener(_onProviderChangedForPageSwitch);
      // カレンダーイベントのロード
      provider.loadCalendarEvents();
      provider.loadGoogleCalendarSettings();
      // イベント時刻通知タイマー (30秒間隔で発火チェック)
      _eventNotifyTimer = Timer.periodic(
          const Duration(seconds: 30), (_) => _checkEventNotifications());
      // 初回起動フロー判定:
      //   provider のコンストラクタ内で `_loadGeminiApiKey` が非同期で走る。
      //   その中で `_isFirstLaunch` が初めて確定 (= SharedPreferences から
      //   `langPickerShown` を読んで決定) するため、ロード完了を待たないと
      //   この判定で false (= デフォルト値) のまま処理してしまい、本当は
      //   初回なのに言語ピッカーが出ずユーザー名ダイアログだけが出る、と
      //   いう不具合になる。
      //   → `provider.initialLoadDone` を await して、確実にフラグが
      //     確定してから判定する。
      Future<void>.microtask(() async {
        await provider.initialLoadDone;
        // ★ モバイルで初回設定画面 (言語/タイムゾーン/ユーザー名) が出ない不具合の
        //   修正 ★ initialLoadDone は軽量の _loadEssentialUiState 完了で先に解決する
        //   が、 その時点ではまだ pages が空 = build() がローディング Scaffold
        //   (CircularProgressIndicator) を返している瞬間で、 そこに出した showDialog
        //   はモバイルでは失われていた。 → pages が生成され実 UI になるまで待って
        //   (最大 8 秒のフォールバック)、 さらに 1 フレーム後に表示する。
        int waited = 0;
        while (mounted && provider.pages.isEmpty && waited < 8000) {
          await Future<void>.delayed(const Duration(milliseconds: 100));
          waited += 100;
        }
        if (!mounted || _onboardingShown) return;
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted || _onboardingShown) return;
          _onboardingShown = true;
          if (provider.isFirstLaunch) {
            _showInitialLanguagePicker(provider);
          }
          // 名前は Google アカウントから受け取るので、 起動時に
          //   ユーザー名を尋ねる画面は出さない (= ユーザー要望)。
        });
      });
    });
    // ── 矢印キー長押しリピート用のグローバルハンドラ ──
    HardwareKeyboard.instance.addHandler(_handleMainGlobalArrowKey);
    // ── ドラッグ&ドロップ用のグローバル pointer route ──
    // Drawer からマップタイルをドラッグ → マップキャンバスでドロップ
    // を、 DragTarget の hit test に依存せず確実に検出するため、
    // pointerRouter で全 PointerEvent を監視する (= hit test 経由ではない)。
    WidgetsBinding.instance.pointerRouter
        .addGlobalRoute(_globalPointerForMapDrop);
  }

  /// ドラッグ中のグローバルポインタ追跡 + drop 検出。
  /// `_draggingMapPage == true` の間、 各 PointerMoveEvent でポインタ位置を
  /// 更新し、 PointerUpEvent で drop 処理を実行する。
  void _globalPointerForMapDrop(PointerEvent event) {
    // ── マウスの現在位置を控えておく (= Ctrl+Shift+N をカーソル付近に
    //    作るため)。 hover / move / down のどれでも更新する。 タッチでは
    //    hover が来ないので、 最後に触った場所が残る。 ──
    if (event is PointerHoverEvent ||
        event is PointerMoveEvent ||
        event is PointerDownEvent) {
      _lastGlobalPointerPos = event.position;
    }
    // Draggable が再構築で先に破棄されても、ポインタ終了の次フレームには
    // 空バーの配置候補を必ず解除する。即時解除すると accept 前に消え得る。
    if ((event is PointerUpEvent || event is PointerCancelEvent) &&
        _activeDesktopHeaderDrag != null) {
      final finishingDrag = _activeDesktopHeaderDrag;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && identical(_activeDesktopHeaderDrag, finishingDrag)) {
          _endDesktopHeaderDrag();
        }
      });
    }
    if (!_draggingMapPage) return;
    if (event is PointerMoveEvent || event is PointerHoverEvent) {
      _draggingPointerPos = event.position;
      // setState せずに位置だけ更新 (= 頻繁な再 build を避ける)。
      // visual feedback は別の hover state で出している。
    } else if (event is PointerUpEvent || event is PointerCancelEvent) {
      _draggingPointerPos = event.position;
      _handleMapPageDrop(event.position);
      // drop 後に state クリア (onDragEnd が呼ばれなくても安全)
      if (mounted) {
        setState(() {
          _draggingMapPage = false;
          _currentDrawerDragData = null;
        });
      }
    }
  }

  /// ダイアログを「クリックした場所」 の近くに出す (= ユーザー要望:
  /// 「ファイルを作成」 「ページを追加」 は画面中央ではなく押した場所に)。
  /// `_lastGlobalPointerPos` (hover / down で常時更新) を基準に置き、
  /// 画面からはみ出す分は内側へ寄せる。 位置が取れない時は従来どおり中央。
  Future<T?> _showNearDialogMain<T>(
      {required WidgetBuilder builder,
      double width = 480,
      double height = 400}) {
    final at = _lastGlobalPointerPos;
    return showDialog<T>(
      context: context,
      builder: (dctx) {
        if (at == null) return builder(dctx);
        final screen = MediaQuery.of(dctx).size;
        final left = (at.dx - width / 2)
            .clamp(12.0, math.max(12.0, screen.width - width - 12))
            .toDouble();
        var top = at.dy + 14;
        if (top + height > screen.height - 12) {
          top = math.max(12.0, at.dy - height - 14);
        }
        return Stack(children: [
          Positioned(
            left: left,
            top: top,
            width: width,
            child: Material(
              type: MaterialType.transparency,
              child: Builder(builder: builder),
            ),
          ),
        ]);
      },
    );
  }

  /// マップキャンバス上の drop 処理。 ポインタの global position から
  /// キャンバス座標に変換し、 その位置に「📒 マップ名」 サブマップノードを生成。
  void _handleMapPageDrop(Offset globalPos) {
    final data = _currentDrawerDragData;
    if (data == null || data.pageIds.isEmpty) return;
    final provider = context.read<MindMapProvider>();
    // ── ドロワー内へのドロップはサブマップ化しない (= 並び替え/フォルダー移動) ──
    // ユーザー要望: ドラッグでマップ一覧の並び替えができるように。 ドロワーが開いて
    //   いて、 ドロップ位置がドロワー幅 (左側) に収まっていれば、 ドロワー内の
    //   DragTarget (並び替え/フォルダー) が処理するので、 ここでは何もしない。
    // ※ Scaffold.maybeOf(context) は State の context (Scaffold の親) からは
    //   自身の Scaffold を見つけられず常に null になるため使えない。 State が
    //   管理する `_drawerOpen` フラグを使う (= サブマップ化バグの修正)。
    final drawerOpen = _drawerOpen;
    if (drawerOpen) {
      final screenW = MediaQuery.of(context).size.width;
      // Flutter の Drawer 既定幅は 304 (狭い画面では画面幅に収める)。
      final drawerW = screenW < 320 ? screenW - 8 : 304.0;
      if (globalPos.dx < drawerW) return;
    }
    // マップ領域外 (= 上部 AppBar) なら無視。
    if (globalPos.dy < 60) return;
    // ── サブマップノード化は廃止 (= ユーザー要望)。 ドロップされたページを
    //    分割ビューで開く。 2 件以上なら自動で 4 分割にする。 ──
    final dropped = <MindMapPage>[];
    for (final pageId in data.pageIds) {
      if (pageId == provider.currentPage.id) continue;
      for (final p in provider.pages) {
        if (p.id == pageId) {
          if (_splitEligiblePage(p)) dropped.add(p);
          break;
        }
      }
    }
    if (dropped.isEmpty) return;
    setState(() {
      _mapSplitOpen = true;
      if (dropped.length >= 2 && _isDesktop) _mapSplitQuad = true;
      var di = 0;
      for (final slotIdx in _visibleSplitSlots()) {
        if (slotIdx == _mapSplitEditorSlot) continue;
        if (di >= dropped.length) break;
        _mapSplitCells[slotIdx] = dropped[di++].id;
      }
    });
    _appSnack(
      context,
      SnackBar(
        content: Text(
            context
                .read<MindMapProvider>()
                .t('map.splitDropOpened')
                .replaceFirst('{n}', '${dropped.length}'),
            style: const TextStyle(fontSize: 12)),
        backgroundColor: const Color(0xFF6C63FF),
        duration: const Duration(seconds: 2),
      ),
    );
    // 分割で開いたらドロワーを閉じてペインを見せる。
    if (drawerOpen) {
      try {
        _scaffoldKey.currentState?.closeDrawer();
      } catch (_) {}
    }
  }

  // ── 矢印キー長押しリピート（メインキャンバス用）──
  /// 現在押下中の矢印キー
  final Set<LogicalKeyboardKey> _mainHeldArrows = {};

  /// リピート用 Timer（initial delay）
  Timer? _mainArrowRepeatDelayTimer;

  /// リピート用 Timer（periodic）
  Timer? _mainArrowRepeatTimer;

  /// メインキャンバスのキーハンドラ。矢印キーの連続リピートだけ担当。
  /// Esc や他のショートカットは既存の KeyboardListener（Focus ベース）が担当する。
  bool _handleMainGlobalArrowKey(KeyEvent event) {
    if (!mounted) return false;
    // ── Esc: クラウド同期 (アップロード/ダウンロード) 中なら中断する
    //    (= ユーザー要望: Esc で転送をキャンセル) ──
    if (event is KeyDownEvent &&
        event.logicalKey == LogicalKeyboardKey.escape) {
      // ── ヘッダーのマップ名インライン編集中なら Esc で抜ける ──
      // (= ユーザー要望: ヘッダーの名前編集から抜けられない。 Esc で編集を
      //   キャンセルして通常表示へ戻す。 変更は破棄)。
      if (_editingMapName) {
        _endInlineMapNameEdit();
        return true;
      }
      final provider = context.read<MindMapProvider>();
      if (provider.isSyncing) {
        provider.cancelSync();
        return true;
      }
      // 動画ダウンロード中なら Esc で中止する (= ユーザー要望)。
      if (_activeVideoDlCancelToken != null) {
        _activeVideoDlCancelToken!.value = true;
        return true;
      }
      // ── ギャラリーの行/列 掴み選択モードを Esc で解除する
      //    (= ユーザー要望: 行や列の掴みの選択モードから抜けられないので、
      //    Esc で選択を解除して通常状態に戻せるように) ──
      if (_shelfSelRows.isNotEmpty ||
          _shelfSelCols.isNotEmpty ||
          _shelfRowDragFrom != null ||
          _shelfColDragFrom != null) {
        setState(() {
          _shelfSelRows.clear();
          _shelfSelCols.clear();
          _shelfRowAnchor = null;
          _shelfColAnchor = null;
          _shelfRowDragFrom = null;
          _shelfColDragFrom = null;
        });
        return true;
      }
    }
    // ── Tab: 親 → 一番上の子 → 兄弟を順に (= ユーザー要望) ──
    // 文字入力中でも効かせたいので、 インライン編集中は確定してから移る。
    if (_isDesktop &&
        event is KeyDownEvent &&
        event.logicalKey == LogicalKeyboardKey.tab &&
        !HardwareKeyboard.instance.isControlPressed &&
        !HardwareKeyboard.instance.isMetaPressed &&
        !HardwareKeyboard.instance.isAltPressed) {
      final route = ModalRoute.of(context);
      if (_focusLockOverlay == null &&
          !_splitPanelHover &&
          !_splitLeftPanelHover &&
          !_searchVisible &&
          !_editingMapName &&
          route != null &&
          route.isCurrent &&
          // ノードのインライン編集中は対象。 それ以外の入力欄では
          // 通常の Tab (フォーカス移動) に任せる。
          (_inlineNodeEditNodeId != null || !_isPrimaryEditableTextFocused())) {
        if (_moveNodeSelectionByTab(
            backwards: HardwareKeyboard.instance.isShiftPressed)) {
          return true;
        }
      }
    }
    // ── Ctrl+Shift+N: 新しい要素を作って、 そのまま名前を打ち始める ──
    //    (= ユーザー要望: 文字入力中でも押したら新しい要素が作られて、
    //     新しく作られた側の入力がアクティブになる)。
    //    インライン編集中は、 まず今の入力を確定してから作る。
    if (_isDesktop &&
        event is KeyDownEvent &&
        event.logicalKey == LogicalKeyboardKey.keyN &&
        (HardwareKeyboard.instance.isControlPressed ||
            HardwareKeyboard.instance.isMetaPressed) &&
        HardwareKeyboard.instance.isShiftPressed &&
        !HardwareKeyboard.instance.isAltPressed) {
      final route = ModalRoute.of(context);
      final provider = context.read<MindMapProvider>();
      if (_focusLockOverlay == null &&
          !_splitPanelHover &&
          !_splitLeftPanelHover &&
          !_editingMapName &&
          route != null &&
          route.isCurrent &&
          provider.currentPage.pageType == 'normal' &&
          // 編集中のノード以外の入力欄 (検索欄など) では邪魔しない。
          (_inlineNodeEditNodeId != null || !_isPrimaryEditableTextFocused())) {
        _createNodeAndStartEditing(provider);
        return true;
      }
    }
    // ── F3: 要素の上に説明書きを書く (= ユーザー要望) ──
    if (_isDesktop &&
        event is KeyDownEvent &&
        event.logicalKey == LogicalKeyboardKey.f3 &&
        !HardwareKeyboard.instance.isControlPressed &&
        !HardwareKeyboard.instance.isMetaPressed &&
        !HardwareKeyboard.instance.isShiftPressed &&
        !HardwareKeyboard.instance.isAltPressed) {
      final route = ModalRoute.of(context);
      if (_focusLockOverlay == null &&
          !_splitPanelHover &&
          !_splitLeftPanelHover &&
          !_editingMapName &&
          route != null &&
          route.isCurrent &&
          !_isPrimaryEditableTextFocused()) {
        final provider = context.read<MindMapProvider>();
        final id = _nodeIdForDirectEdit(provider);
        if (id != null && provider.nodes.containsKey(id)) {
          // 要素の上に直接書き込む (= ユーザー要望: ダイアログではなく)。
          _startCaptionEdit(id);
          return true;
        }
      }
    }
    // F2はFocusベースのKeyboardListenerだけに任せると、アクションバーや
    // 添付ビューアーがFocusを奪った後に届かない。マップが最前面で、
    // テキスト入力中でない時はグローバルハンドラから直接編集を開始する。
    if (_isDesktop &&
        event is KeyDownEvent &&
        event.logicalKey == LogicalKeyboardKey.f2 &&
        _shortcutCommandMatches('editTitle', 'F2') &&
        !HardwareKeyboard.instance.isControlPressed &&
        !HardwareKeyboard.instance.isMetaPressed &&
        !HardwareKeyboard.instance.isShiftPressed &&
        !HardwareKeyboard.instance.isAltPressed) {
      final route = ModalRoute.of(context);
      if (_focusLockOverlay != null ||
          _splitPanelHover ||
          _splitLeftPanelHover ||
          route == null ||
          !route.isCurrent ||
          _primaryFocusOwnsEmbeddedF2() ||
          _isPrimaryEditableTextFocused()) {
        return false;
      }
      final provider = context.read<MindMapProvider>();
      final id = _nodeIdForDirectEdit(provider);
      final node = id == null ? null : provider.nodes[id];
      if (node == null) return false;
      _startInlineTitleEdit(context, node);
      return true;
    }
    // ── Space: 設定シートを開く (= ユーザー報告: Space から設定が開かない
    //    ことがある) ──
    // KeyboardListener はフォーカスを失うとキーを受け取れないため、 分割
    // パネルやダイアログ、 WebView を触った後に効かなくなっていた。 フォー
    // カスに依存しないグローバルハンドラからも開けるようにする。
    // 閉じる方はシート自身の Focus が担当するので、 ここでは開くだけ
    // (マップが最前面 = route.isCurrent の時に限る)。
    //
    // ★ KeyDown が一時的な状態 (閉じかけのダイアログ / 消えかけのフォー
    //   カス等) に阻まれた時は、 同じ押下の KeyUp でもう一度判定する
    //   (= ユーザー報告: 選択解除した直後などに Space で設定が開かない
    //   ことがある。 押した瞬間だけ条件が崩れていても、 離す頃には状態が
    //   落ち着いているので開ける)。
    if (_isDesktop &&
        (event is KeyDownEvent || event is KeyUpEvent) &&
        event.logicalKey == LogicalKeyboardKey.space &&
        !_settingsSheetOpen &&
        !HardwareKeyboard.instance.isControlPressed &&
        !HardwareKeyboard.instance.isMetaPressed &&
        !HardwareKeyboard.instance.isShiftPressed &&
        !HardwareKeyboard.instance.isAltPressed &&
        _shortcutCommandMatches('openSettings', 'Space')) {
      if (_spaceSettingsGuardsPass()) {
        if (event is KeyDownEvent) {
          _pendingSpaceSettingsRetry = false;
          _toggleSettingsSheetFromShortcut(context.read<MindMapProvider>());
          return true;
        }
        // KeyUp: KeyDown 側が阻まれていた時だけ開き直す (通常の押下で
        // 二重に開かないよう、 KeyDown が開けた時はフラグが下りている)。
        if (_pendingSpaceSettingsRetry) {
          _pendingSpaceSettingsRetry = false;
          _toggleSettingsSheetFromShortcut(context.read<MindMapProvider>());
          return true;
        }
      } else if (event is KeyDownEvent) {
        _pendingSpaceSettingsRetry = true;
      }
    }
    // ── F6 (変更可能): 分割パネル(左右)の中身を入れ替え (= ユーザー要望) ──
    // マップが最前面の時だけ処理する。PDF ビューア等が前面にあるときは
    // false を返して消費せず、そちら側の F6 ハンドラに委ねる。
    // ★ 割り当ての変更・無効化を尊重する (= ユーザー要望: 変更不可を
    //   変更できるように)。 押されたコンボが swapSplitPanels の現在の
    //   割り当てと一致した時だけ動く。
    if (event is KeyDownEvent &&
        _shortcutCommandMatches(
            'swapSplitPanels', _getPressedKeyCombo(event))) {
      final r = ModalRoute.of(context);
      final fp = FocusManager.instance.primaryFocus;
      final editing = fp != null && fp.context?.widget is EditableText;
      if (!editing && r != null && r.isCurrent) {
        _swapSplitPanels();
        return true;
      }
      return false;
    }
    // ★ マウスが分割パネル側にあるときはマップの矢印キー操作を無効化 ★
    // (PDF / WebView 側に矢印キーを譲る = ページめくり等で使う)。
    // マウスがマップ側にあれば通常通りマップを矢印キーで pan できる。
    // 左パネル (`_splitLeftPanelHover`) も同様に skip 対象にする。
    if (_splitPanelHover || _splitLeftPanelHover) {
      if (_mainHeldArrows.isNotEmpty) {
        _mainHeldArrows.clear();
        _mainArrowRepeatDelayTimer?.cancel();
        _mainArrowRepeatDelayTimer = null;
        _mainArrowRepeatTimer?.cancel();
        _mainArrowRepeatTimer = null;
      }
      return false;
    }
    // メインキャンバスが最前面でない（ダイアログやタイムラインなどが上にある）なら
    // 手を出さない
    final route = ModalRoute.of(context);
    if (route == null || !route.isCurrent) {
      // 最前面でなくなった時点でリピート状態をクリア
      if (_mainHeldArrows.isNotEmpty) {
        _mainHeldArrows.clear();
        _mainArrowRepeatDelayTimer?.cancel();
        _mainArrowRepeatDelayTimer = null;
        _mainArrowRepeatTimer?.cancel();
        _mainArrowRepeatTimer = null;
      }
      return false;
    }
    // テキスト編集中は干渉しない（TextField のカーソル移動を邪魔しない）
    if (_isPrimaryEditableTextFocused()) {
      return false;
    }
    final k = event.logicalKey;
    if (k != LogicalKeyboardKey.arrowLeft &&
        k != LogicalKeyboardKey.arrowRight &&
        k != LogicalKeyboardKey.arrowUp &&
        k != LogicalKeyboardKey.arrowDown) {
      return false;
    }
    if (event is KeyDownEvent) {
      if (!_mainHeldArrows.contains(k)) {
        _mainHeldArrows.add(k);
        // 初回は KeyboardListener に任せる（既存の動作と同一）
        // リピートのみ Timer で担当
        _scheduleMainArrowRepeat();
      }
      return false; // KeyboardListener も処理を継続
    }
    if (event is KeyUpEvent) {
      _mainHeldArrows.remove(k);
      if (_mainHeldArrows.isEmpty) {
        _mainArrowRepeatDelayTimer?.cancel();
        _mainArrowRepeatDelayTimer = null;
        _mainArrowRepeatTimer?.cancel();
        _mainArrowRepeatTimer = null;
      }
      return false;
    }
    return false;
  }

  // True while a TextField or the gallery inline editor owns keyboard focus.
  bool _isPrimaryEditableTextFocused() {
    if (_inlineShelfEditFocus.hasFocus) return true;
    if (_inlineNodeEditFocus.hasFocus) return true;
    final focused = FocusManager.instance.primaryFocus;
    if (focused == null) return false;
    if (focused == _inlineShelfEditFocus) return true;
    if (focused == _inlineNodeEditFocus) return true;
    final ctx = focused.context;
    if (ctx == null) return false;
    final widget = ctx.widget;
    if (widget is EditableText) return true;
    return ctx.findAncestorWidgetOfExactType<EditableText>() != null;
  }

  bool _primaryFocusOwnsEmbeddedF2() {
    final focusContext = FocusManager.instance.primaryFocus?.context;
    if (focusContext == null) return false;
    return focusContext
                .findAncestorStateOfType<_SpreadsheetEditorDialogState>() !=
            null ||
        focusContext.findAncestorStateOfType<_DocxViewerDialogState>() != null ||
        focusContext.findAncestorStateOfType<_PptxViewerDialogState>() != null ||
        focusContext.findAncestorStateOfType<_PdfMemoPanelState>() != null;
  }

  /// 説明書きをその場編集しているノード (= ユーザー要望: F3 の入力欄を
  /// 要素の上に直接書き込める形に / 書いたメモをクリックして編集)。
  String? _editingCaptionNodeId;
  final TextEditingController _captionCtrl = TextEditingController();
  final FocusNode _captionFocus = FocusNode(debugLabel: 'node_caption');

  /// 説明書きの帯の横幅 (描画と場所空けで同じ値を使う)。
  double _captionWidthFor(MindMapNode n) => math.max(120.0, n.width + 60);

  /// 説明書きの編集を始める。 まだ無ければ空で作る。
  void _startCaptionEdit(String nodeId) {
    final provider = context.read<MindMapProvider>();
    final node = provider.nodes[nodeId];
    if (node == null) return;
    _removeOverlay();
    _captionCtrl.text = node.caption ?? '';
    _captionCtrl.selection =
        TextSelection.collapsed(offset: _captionCtrl.text.length);
    // Enter で確定 / Shift+Enter で改行 (複数行 TextField は Enter が改行に
    // なってしまい onSubmitted が飛ばないため、 キーを直接見る)。
    _captionFocus.onKeyEvent = (nodeF, event) {
      if (event is! KeyDownEvent) return KeyEventResult.ignored;
      final isEnter = event.logicalKey == LogicalKeyboardKey.enter ||
          event.logicalKey == LogicalKeyboardKey.numpadEnter;
      if (isEnter && !HardwareKeyboard.instance.isShiftPressed) {
        if (_captionCtrl.value.composing.isValid) {
          return KeyEventResult.ignored; // IME 変換確定は奪わない
        }
        _commitCaptionEdit();
        return KeyEventResult.handled;
      }
      if (event.logicalKey == LogicalKeyboardKey.escape) {
        setState(() => _editingCaptionNodeId = null);
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    };
    setState(() => _editingCaptionNodeId = nodeId);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted && _editingCaptionNodeId == nodeId) {
        _captionFocus.requestFocus();
      }
    });
  }

  /// 説明書きの編集を確定する。
  void _commitCaptionEdit() {
    final id = _editingCaptionNodeId;
    if (id == null) return;
    final text = _captionCtrl.text;
    setState(() => _editingCaptionNodeId = null);
    final provider = context.read<MindMapProvider>();
    provider.updateNodeCaption(id, text);
    // 説明書きのぶん、 上にある要素をどかして被らないようにする。
    provider.makeRoomForCaption(id);
  }

  /// 要素の上に浮かべる説明書き (表示 + その場編集)。
  List<Widget> _buildNodeCaptions(MindMapProvider provider,
      Map<String, MindMapNode> nodes, double canvasSize) {
    const gap = 8.0;
    final out = <Widget>[];
    for (final n in nodes.values) {
      if (n.hiddenInContainer != null) continue;
      final editing = _editingCaptionNodeId == n.id;
      final text = (n.caption ?? '').trim();
      if (!editing && text.isEmpty) continue;
      final w = _captionWidthFor(n);
      out.add(Positioned(
        left: n.position.dx + n.width / 2 - w / 2,
        // 下端をノードのすぐ上に固定して、 中身の高さぶん上へ伸ばす。
        bottom: canvasSize - (n.position.dy - gap),
        width: w,
        child: _captionBubble(provider, n, editing),
      ));
    }
    return out;
  }

  Widget _captionBubble(
      MindMapProvider provider, MindMapNode n, bool editing) {
    const fill = Color(0xFFFFF3C4);
    const line = Color(0xFFE0B34A);
    final body = Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),
      decoration: BoxDecoration(
        color: fill,
        borderRadius: BorderRadius.circular(7),
        border: Border.all(color: line, width: 1.2),
        boxShadow: const [
          BoxShadow(color: Color(0x33000000), blurRadius: 4, offset: Offset(0, 2)),
        ],
      ),
      child: editing
          ? TextField(
              controller: _captionCtrl,
              focusNode: _captionFocus,
              maxLines: 4,
              minLines: 1,
              textAlign: TextAlign.center,
              style: const TextStyle(
                  color: Color(0xFF10202C),
                  fontSize: 12,
                  height: 1.35,
                  fontWeight: FontWeight.w600),
              decoration: InputDecoration(
                isDense: true,
                border: InputBorder.none,
                contentPadding: EdgeInsets.zero,
                hintText: provider.t('caption.hint'),
                hintStyle: const TextStyle(
                    color: Color(0x7710202C), fontSize: 11.5),
              ),
              onSubmitted: (_) => _commitCaptionEdit(),
              onTapOutside: (_) => _commitCaptionEdit(),
            )
          : Text(
              (n.caption ?? '').trim(),
              textAlign: TextAlign.center,
              maxLines: 4,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                  color: Color(0xFF10202C),
                  fontSize: 12,
                  height: 1.35,
                  fontWeight: FontWeight.w600),
            ),
    );
    return Column(mainAxisSize: MainAxisSize.min, children: [
      // クリックで編集 (= ユーザー要望: 書いたメモをクリックして編集)。
      MouseRegion(
        cursor: SystemMouseCursors.click,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: editing ? null : () => _startCaptionEdit(n.id),
          child: body,
        ),
      ),
      // ノードを指す小さな三角
      CustomPaint(size: const Size(12, 6), painter: _CaptionTailPainter()),
    ]);
  }

  /// Tab で選択を移す (= ユーザー要望: 親を選んでいる時は一番上の子へ、
  /// そこからは兄弟を上から順に切り替える)。 移動できたら true。
  ///
  /// [backwards] (Shift+Tab) は逆順に回る。
  bool _moveNodeSelectionByTab({bool backwards = false}) {
    final provider = context.read<MindMapProvider>();
    if (provider.currentPage.pageType != 'normal') return false;
    // 文字入力中なら、 まず今の内容を確定させる。
    final editingId = _inlineNodeEditNodeId;
    if (editingId != null) _commitNodeInlineTextEdit();
    final current = editingId ?? _nodeIdForDirectEdit(provider);
    if (current == null || !provider.nodes.containsKey(current)) return false;

    String? target;
    final children = provider.orderedChildIdsOf(current);
    if (children.isNotEmpty) {
      // 親を選んでいる → 一番上の子へ。
      target = backwards ? children.last : children.first;
    } else {
      // 子が無い → 同じ親の兄弟を順に。
      final siblings = provider.orderedSiblingIdsOf(current);
      if (siblings.length <= 1) return false;
      final i = siblings.indexOf(current);
      if (i < 0) return false;
      final next = backwards
          ? (i - 1 + siblings.length) % siblings.length
          : (i + 1) % siblings.length;
      target = siblings[next];
    }
    if (target == null || target == current) return false;
    _selectNodeForKeyboardNav(target);
    // 文字入力中に Tab を押した時は、 移った先も入力モードにする
    // (= ユーザー要望: 他のノードに移りつつ入力モードに)。
    if (editingId != null) {
      final moved = target;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        final n = context.read<MindMapProvider>().nodes[moved];
        if (n != null) _startInlineTitleEdit(context, n);
      });
    }
    return true;
  }

  /// キーボード移動で選んだ要素を選択状態にして、 画面内に入れる。
  void _selectNodeForKeyboardNav(String nodeId) {
    final provider = context.read<MindMapProvider>();
    final node = provider.nodes[nodeId];
    if (node == null) return;
    _removeOverlay();
    provider.selectNode(nodeId);
    setState(() {
      _rangeSelectedIds.clear();
      _selectedConnections.clear();
      _actionNodeId = nodeId;
    });
    // 画面外なら中央へ寄せる。
    final ctrl = _ctrlFor(provider.currentPage.id);
    final view = _editorViewportSize();
    final m = Matrix4.copy(ctrl.value);
    final sc = m.getMaxScaleOnAxis();
    final tl = ctrl.toScene(Offset.zero);
    final br = ctrl.toScene(Offset(view.width, view.height));
    final visible = Rect.fromPoints(tl, br).deflate(40);
    final center =
        Offset(node.position.dx + node.width / 2, node.position.dy + node.visualHeight / 2);
    if (!visible.contains(center)) {
      m.setTranslationRaw(
        view.width / 2 - center.dx * sc,
        view.height / 2 - center.dy * sc,
        0,
      );
      ctrl.value = m;
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _showActionButtons(nodeId, ctrl);
    });
  }

  String? _nodeIdForDirectEdit(MindMapProvider provider) {
    if (_selectedConnections.isNotEmpty ||
        _selectedDecorationId != null ||
        _rangeSelectedDecorationIds.isNotEmpty) {
      return null;
    }
    final actionId = _actionNodeId;
    if (actionId != null && provider.nodes.containsKey(actionId)) {
      return actionId;
    }
    if (_rangeSelectedIds.isNotEmpty) {
      if (_rangeSelectedIds.length != 1) return null;
      final rangeId = _rangeSelectedIds.first;
      if (provider.nodes.containsKey(rangeId)) return rangeId;
      return null;
    }
    final selectedId = provider.selectedNodeId;
    if (selectedId != null && provider.nodes.containsKey(selectedId)) {
      return selectedId;
    }
    return null;
  }

  /// Repeats held arrow-key movement after the initial delay.
  void _scheduleMainArrowRepeat() {
    _mainArrowRepeatDelayTimer?.cancel();
    _mainArrowRepeatTimer?.cancel();
    _mainArrowRepeatDelayTimer = Timer(
      const Duration(milliseconds: 350),
      () {
        if (!mounted || _mainHeldArrows.isEmpty) return;
        _mainArrowRepeatTimer = Timer.periodic(
          const Duration(milliseconds: 50),
          (_) {
            if (!mounted) {
              _mainArrowRepeatTimer?.cancel();
              _mainArrowRepeatTimer = null;
              return;
            }
            _mainHeldArrows.removeWhere(
                (k) => !HardwareKeyboard.instance.isLogicalKeyPressed(k));
            if (_mainHeldArrows.isEmpty) {
              _mainArrowRepeatTimer?.cancel();
              _mainArrowRepeatTimer = null;
              return;
            }
            for (final k in _mainHeldArrows.toList()) {
              _executeMainArrow(k);
            }
          },
        );
      },
    );
  }

  /// 矢印キーに対応する実アクション（メインキャンバス用）
  /// - カレンダーモード中: 選択日を前日/翌日/前週/翌週に移動
  /// - 通常: キャンバスをスクロール
  void _executeMainArrow(LogicalKeyboardKey k) {
    if (!mounted) return;
    if (_calendarMode) {
      setState(() {
        if (k == LogicalKeyboardKey.arrowLeft) {
          _selectedCalendarDay =
              _selectedCalendarDay.subtract(const Duration(days: 1));
        } else if (k == LogicalKeyboardKey.arrowRight) {
          _selectedCalendarDay =
              _selectedCalendarDay.add(const Duration(days: 1));
        } else if (k == LogicalKeyboardKey.arrowUp) {
          _selectedCalendarDay =
              _selectedCalendarDay.subtract(const Duration(days: 7));
        } else if (k == LogicalKeyboardKey.arrowDown) {
          _selectedCalendarDay =
              _selectedCalendarDay.add(const Duration(days: 7));
        }
        if (_selectedCalendarDay.year != _calendarMonth.year ||
            _selectedCalendarDay.month != _calendarMonth.month) {
          _calendarMonth =
              DateTime(_selectedCalendarDay.year, _selectedCalendarDay.month);
        }
      });
    } else {
      final provider = context.read<MindMapProvider>();
      final pageId = provider.currentPage.id;
      final ctrl = _ctrlFor(pageId);
      _handleArrowKey(k, ctrl);
    }
  }

  /// displayName が空なら初回起動用のユーザー名入力ダイアログを表示する。
  /// すでに名前が設定済みの場合は何もしない。
  ///
  /// 初回起動でも「スキップ」可能 (= 名前未設定で進める)。ただしメッセージ
  /// 送信機能を使う時には別途ダイアログを出して設定を促す。
  ///
  /// 一度スキップしたユーザーには、起動するたびに再表示しない (ユーザー要望)。
  /// `provider.displayNameSkipped` が true の場合は早期リターン。設定シートから
  /// 手動で「ユーザー名」を開くか、メッセージ送信などで必須シーンに当たった
  /// ときのみ表示される。

  /// アバター (絵文字) 選択ダイアログ (= ユーザー要望: ユーザーのアイコンを
  /// ユーザーが指定できるように)。
  /// ユーザーアイコンの見た目を組み立てる共通ウィジェット。
  /// 設定ヘッダーとユーザー名ダイアログで共用する。
  /// 優先順位: カスタム画像 > 絵文字テンプレート > 表示名イニシャル >
  ///   既定の可愛い絵文字 (_kDefaultAvatarEmoji)。
  Widget _userAvatarVisual(MindMapProvider provider, {double size = 48}) {
    final imgPath = provider.userAvatarImagePath;
    final hasImage =
        imgPath != null && imgPath.isNotEmpty && File(imgPath).existsSync();
    final emoji = provider.userAvatar;
    Widget inner;
    if (hasImage) {
      inner = Image.file(
        File(imgPath),
        width: size,
        height: size,
        fit: BoxFit.cover,
        gaplessPlayback: true,
        errorBuilder: (_, __, ___) => Text(
          _kDefaultAvatarEmoji,
          style: TextStyle(fontSize: size * 0.5),
        ),
      );
    } else {
      final txt = (emoji != null && emoji.isNotEmpty)
          ? emoji
          : (provider.displayName.isNotEmpty
              ? provider.displayName.characters.first.toUpperCase()
              : _kDefaultAvatarEmoji);
      inner = Text(txt, style: TextStyle(fontSize: size * 0.5));
    }
    return Container(
      width: size,
      height: size,
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        // ── 外枠は控えめに (= ユーザー要望: 枠が派手すぎるので地味に) ──
        // 旧: オレンジ太枠 → 新: ごく薄いニュートラルな縁取り。
        color: Colors.white.withValues(alpha: 0.05),
        border:
            Border.all(color: Colors.white.withValues(alpha: 0.15), width: 1),
      ),
      alignment: Alignment.center,
      child: inner,
    );
  }

  void _showAvatarPickerDialog(BuildContext ctx, MindMapProvider provider) {
    // ── アバター候補の絵文字 (= ユーザー要望: デフォルトテンプレートの中から
    //    選べるように)。 怖い '👤' は外し、 可愛くて控えめな顔・小動物を先頭に
    //    並べる。 「クリア」 で既定アイコンに戻る。
    const avatarCandidates = <String>[
