  /// カスタム画像をアバターに設定する。 画像を選んで attachments/ に安定的に
  /// コピーし、 そのパスを userAvatarImage として保存する (= ユーザー要望:
  /// アイコンを独自に設定できるように)。
  Future<void> _pickCustomAvatarImage(
      BuildContext dctx, MindMapProvider provider) async {
    try {
      final result = await FilePicker.platform.pickFiles(
        dialogTitle: provider.t('pick.avatarImage'),
        type: FileType.image,
        withData: false,
      );
      if (result == null || result.files.isEmpty) return;
      final srcPath = result.files.single.path;
      if (srcPath == null || srcPath.isEmpty) return;
      // attachments/ にコピーして、 元ファイルが移動・削除されても残るように。
      final appDir = await getApplicationDocumentsDirectory();
      final attachDir = Directory('${appDir.path}/attachments');
      if (!await attachDir.exists()) {
        await attachDir.create(recursive: true);
      }
      final ext = srcPath.contains('.')
          ? srcPath.substring(srcPath.lastIndexOf('.') + 1)
          : 'png';
      final destName = 'avatar_${DateTime.now().millisecondsSinceEpoch}.$ext';
      final destPath = '${attachDir.path}/$destName';
      await File(srcPath).copy(destPath);
      await provider.setUserAvatarImage(destPath);
      if (dctx.mounted) Navigator.pop(dctx);
    } catch (e) {
      debugPrint('カスタムアバター画像の設定に失敗: $e');
      if (mounted) {
        _appSnack(
            context,
            SnackBar(
                content:
                    Text(context.read<MindMapProvider>().t('icon.setFailed'))));
      }
    }
  }


  /// 最後に通知した「日付:イベントID」の集合。
  /// 同じイベントを当日中に何度も通知しないように記憶する。
  final Set<String> _notifiedKeys = {};
  Timer? _eventNotifyTimer;

  /// タイムライン予定の通知を「1 度だけ」に集約するための共有ガード。
  /// ポーラー (_checkEventNotifications) とリードタイム予約
  /// (_schedulePendingEventNotifications) の両方がここを通すので、
  /// 同じ予定が複数経路から二重・三重に通知されるのを防ぐ
  /// (= ユーザー要望: 通知が 3 回くらい出てうざい → 1 度だけ)。
  final Set<String> _timelineNotifiedKeys = <String>{};

  /// 30秒ごとに呼ばれる: 現在時刻の1分以内に開始する予定があれば通知を出す
  void _checkEventNotifications() {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final now = DateTime.now();
    final todayKey = _dateKey(now);
    final events = provider.eventsOn(todayKey);
    for (final ev in events) {
      if (ev.startTime == null) continue;
      final parts = ev.startTime!.split(':');
      if (parts.length != 2) continue;
      final evHour = int.tryParse(parts[0]);
      final evMin = int.tryParse(parts[1]);
      if (evHour == null || evMin == null) continue;
      final eventDateTime =
          DateTime(now.year, now.month, now.day, evHour, evMin);
      // 開始時刻の直前（30秒〜0秒前）に 1 回だけ通知
      final diffSec = eventDateTime.difference(now).inSeconds;
      if (diffSec < 0 || diffSec > 60) continue;
      final k = '$todayKey:${ev.id}';
      if (_notifiedKeys.contains(k)) continue;
      _notifiedKeys.add(k);
      _notifyTimelineEventOnce(ev);
    }
    // メッセージ機能は廃止したので新着メッセージチェックは行わない。
    // (ユーザー要望「メッセージ機能を無くして」)
  }

  /// タイムライン予定の通知を「1 度だけ」 システム通知で出す
  /// (= ユーザー要望: 通知が 3 回くらい出てうざい → 1 度だけ・システム通知で)。
  /// ポーラーとリードタイム予約の両経路から呼ばれるが、_timelineNotifiedKeys
  /// で重複を抑止する。Windows は OS トースト、 それ以外はアプリ内オーバーレイ
  /// (Android は zonedSchedule の OS 通知が本命で、これは前面時の補助)。
  void _notifyTimelineEventOnce(CalendarEvent ev) {
    if (!mounted) return;
    final now = DateTime.now();
    String two(int n) => n.toString().padLeft(2, '0');
    final todayKey = '${now.year}-${two(now.month)}-${two(now.day)}';
    final key = 'tl_${ev.id}_$todayKey';
    if (_timelineNotifiedKeys.contains(key)) return; // 既に通知済み → 1度だけ
    _timelineNotifiedKeys.add(key);
    final tlP = context.read<MindMapProvider>();
    final title = ev.title.isEmpty ? tlP.t('tlNotif.timeNow') : ev.title;
    final body = (ev.startTime != null && ev.startTime!.isNotEmpty)
        ? tlP.t('tlNotif.startAt').replaceFirst('{time}', ev.startTime!)
        : tlP.t('tlNotif.reached');
    if (!kIsWeb && Platform.isWindows) {
      _showWindowsOsNotification(null, title, body);
    } else {
      _showNodeNotificationOverlay('', title, body);
    }
  }

  /// 予定が変更 (時刻変更含む) されたら、 その予定の「通知済み」 ガードを
  /// 全てクリアして、 通知が改めて 1 回出るようにする
  /// (= ユーザー要望: 通知は 1 回だが、 予定を変更したら回数がリセットされる)。
  void _resetEventNotifyGuards(String eventId) {
    _notifiedKeys.removeWhere((k) => k.endsWith(':$eventId'));
    _timelineNotifiedKeys.removeWhere((k) => k.startsWith('tl_${eventId}_'));
    // OS 予約通知の重複ガードも消して、 新しい時刻で貼り直せるようにする。
    _scheduledNotifications.removeWhere((k) => k.startsWith('cal_${eventId}_'));
  }

  // ── メッセージ受信通知は廃止 ──
  // ユーザー要望「メッセージ機能を無くして」 に伴い、 新着メッセージの
  //   ポーリング (_checkIncomingMessages) と SnackBar 通知
  //   (_showIncomingMessageNotification) を削除した。 開発者とのやり取りは
  //   「お問い合わせ」 (バグ報告 / 機能依頼 + 返信) に集約。

  /// 画面上に予定開始通知を表示（SnackBar + 音/バイブ代替は将来実装）
  void _showEventNotification(CalendarEvent ev) {
    if (!mounted) return;
    final color = Color(ev.colorArgb ?? 0xFFBA68C8);
    _appSnack(
      context,
      SnackBar(
        content: Row(children: [
          Icon(Icons.notifications_active, color: color),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  '⏰ ${ev.startTime ?? ''}',
                  style: TextStyle(
                      color: color, fontSize: 12, fontWeight: FontWeight.w700),
                ),
                Text(
                  ev.title,
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 14,
                      fontWeight: FontWeight.w600),
                ),
              ],
            ),
          ),
        ]),
        backgroundColor: const Color(0xFF2A2A3E),
        behavior: SnackBarBehavior.floating,
        duration: const Duration(seconds: 10),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(10),
          side: BorderSide(color: color, width: 1.5),
        ),
      ),
    );
  }

  /// 初回起動時の言語選択ダイアログ（キャンセル不可）
  void _showInitialLanguagePicker(MindMapProvider provider) {
    // ── スクロール + キーボード操作用の controller / state ──
    // ユーザー要望「スクロールバーは白くて視認しやすい色にして / 上下キー
    //   で言語選択を移動できて、 Enter で確定みたいな作りにして」 への対応。
    final scrollCtrl = ScrollController();
    final focusNode = FocusNode();
    final langs = MindMapProvider.supportedLanguages.toList();
    int selectedIdx = langs.indexOf(provider.appLanguage);
    if (selectedIdx < 0) selectedIdx = 0;
    const itemHeight = 48.0; // 1 アイテムの実測縦サイズ目安

    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (dctx) => StatefulBuilder(
        builder: (sctx, setD) {
          // 選択肢が画面外なら自動スクロール (上下キーで移動した時)
          void ensureVisible() {
            if (!scrollCtrl.hasClients) return;
            final target = (selectedIdx * itemHeight)
                .clamp(0.0, scrollCtrl.position.maxScrollExtent);
            final viewport = scrollCtrl.position.viewportDimension;
            final offset = scrollCtrl.offset;
            // 選択中アイテムが見える範囲外なら自動でスクロール
            if (target < offset) {
              scrollCtrl.animateTo(target,
                  duration: const Duration(milliseconds: 150),
                  curve: Curves.easeOut);
            } else if (target > offset + viewport - itemHeight) {
              scrollCtrl.animateTo(target - viewport + itemHeight,
                  duration: const Duration(milliseconds: 150),
                  curve: Curves.easeOut);
            }
          }

          // ★ 先に閉じてから後処理する (= ユーザー報告: 言語切替で暗転して
          //   操作できなくなる)。 この画面は barrierDismissible:false +
          //   PopScope(canPop:false) なので、 後処理が失敗して pop に到達しない
          //   と二度と閉じられない。 閉じてから保存すれば詰まらない。
          void confirmAndClose() {
            Navigator.pop(dctx);
            unawaited(() async {
              try {
                await provider.completeFirstLaunch();
              } catch (e) {
                debugPrint('初回設定の保存に失敗: $e');
              }
            }());
            // 言語選択の後にタイムゾーン選択 (メルカトル地図) を表示し、
            // その後にユーザー名ダイアログへ進む (ユーザー要望)。
            if (mounted) _showTimezonePicker(provider);
          }

          return PopScope(
            canPop: false,
            child: Focus(
              focusNode: focusNode,
              autofocus: true,
              onKeyEvent: (node, event) {
                if (event is! KeyDownEvent) return KeyEventResult.ignored;
                if (event.logicalKey == LogicalKeyboardKey.arrowDown) {
                  setD(() {
                    selectedIdx = (selectedIdx + 1) % langs.length;
                  });
                  provider.applyAppLanguageLight(langs[selectedIdx]);
                  WidgetsBinding.instance
                      .addPostFrameCallback((_) => ensureVisible());
                  return KeyEventResult.handled;
                }
                if (event.logicalKey == LogicalKeyboardKey.arrowUp) {
                  setD(() {
                    selectedIdx =
                        (selectedIdx - 1 + langs.length) % langs.length;
                  });
                  provider.applyAppLanguageLight(langs[selectedIdx]);
                  WidgetsBinding.instance
                      .addPostFrameCallback((_) => ensureVisible());
                  return KeyEventResult.handled;
                }
                if (event.logicalKey == LogicalKeyboardKey.enter ||
                    event.logicalKey == LogicalKeyboardKey.numpadEnter) {
                  confirmAndClose();
                  return KeyEventResult.handled;
                }
                return KeyEventResult.ignored;
              },
              child: AlertDialog(
                backgroundColor: const Color(0xFF2A2A3E),
                shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16)),
                title: Row(children: [
                  const Icon(Icons.language_rounded,
                      color: Color(0xFF4FC3F7), size: 24),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(provider.t('firstRun.title'),
                        style: const TextStyle(
                            color: Colors.white,
                            fontSize: 16,
                            fontWeight: FontWeight.w700)),
                  ),
                ]),
                content: SizedBox(
                  width: 320,
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Text(
                        provider.t('firstRun.welcome'),
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                            color: Colors.white70, fontSize: 13),
                      ),
                      const SizedBox(height: 8),
                      Text(
                        provider.t('firstRun.keyHint'),
                        textAlign: TextAlign.center,
                        style: TextStyle(
                            color: Colors.white.withValues(alpha: 0.5),
                            fontSize: 11),
                      ),
                      const SizedBox(height: 12),
                      Container(
                        constraints: const BoxConstraints(maxHeight: 320),
                        decoration: BoxDecoration(
                          color: Colors.white.withValues(alpha: 0.04),
                          borderRadius: BorderRadius.circular(10),
                        ),
                        // ── スクロールバーを常時表示 + 白で視認性UP ──
                        child: Theme(
                          data: Theme.of(context).copyWith(
                            scrollbarTheme: ScrollbarThemeData(
                              thumbVisibility:
                                  const WidgetStatePropertyAll(true),
                              trackVisibility:
                                  const WidgetStatePropertyAll(true),
                              thickness: const WidgetStatePropertyAll(10.0),
                              thumbColor: WidgetStatePropertyAll(
                                  Colors.white.withValues(alpha: 0.85)),
                              trackColor: WidgetStatePropertyAll(
                                  Colors.white.withValues(alpha: 0.15)),
                              trackBorderColor: WidgetStatePropertyAll(
                                  Colors.white.withValues(alpha: 0.25)),
                              radius: const Radius.circular(8),
                            ),
                          ),
                          child: Scrollbar(
                            controller: scrollCtrl,
                            thumbVisibility: true,
                            trackVisibility: true,
                            child: SingleChildScrollView(
                              controller: scrollCtrl,
                              padding: const EdgeInsets.only(right: 14),
                              child: Column(
                                children: List.generate(langs.length, (i) {
                                  final code = langs[i];
                                  final isSelected = i == selectedIdx;
                                  return InkWell(
                                    onTap: () async {
                                      setD(() {
                                        selectedIdx = i;
                                      });
                                      // 1 タップごとに全文書を保存すると
                                      //   固まるので軽量適用 (= 既存の言語
                                      //   ダイアログと同じ方針)。
                                      await provider
                                          .applyAppLanguageLight(code);
                                    },
                                    borderRadius: BorderRadius.circular(8),
                                    child: Container(
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 14, vertical: 12),
                                      decoration: BoxDecoration(
                                        color: isSelected
                                            ? const Color(0xFF4FC3F7)
                                                .withValues(alpha: 0.2)
                                            : Colors.transparent,
                                        border: Border(
                                          left: BorderSide(
                                            color: isSelected
                                                ? const Color(0xFF4FC3F7)
                                                : Colors.transparent,
                                            width: 3,
                                          ),
                                        ),
                                      ),
                                      child: Row(children: [
                                        Icon(
                                          isSelected
                                              ? Icons.check_circle_rounded
                                              : Icons.circle_outlined,
                                          color: isSelected
                                              ? const Color(0xFF4FC3F7)
                                              : Colors.white38,
                                          size: 20,
                                        ),
                                        const SizedBox(width: 12),
                                        Expanded(
                                          child: Text(
                                            MindMapProvider.languageDisplayName(
                                                code),
                                            style: TextStyle(
                                              color: isSelected
                                                  ? Colors.white
                                                  : Colors.white70,
                                              fontSize: 15,
                                              fontWeight: isSelected
                                                  ? FontWeight.w700
                                                  : FontWeight.w500,
                                            ),
                                          ),
                                        ),
                                        // 翻訳が完成していない言語に「BETA」バッジ。
                                        // ユーザーが選ぶ前に「これはまだ英語UIだよ」を
                                        // 視覚的に伝えるためのプレウォーニング。
                                        if (!MindMapProvider.isFullyTranslated(
                                            code)) ...[
                                          Container(
                                            padding: const EdgeInsets.symmetric(
                                                horizontal: 6, vertical: 2),
                                            decoration: BoxDecoration(
                                              color: const Color(0xFFFFB347)
                                                  .withValues(alpha: 0.18),
                                              borderRadius:
                                                  BorderRadius.circular(6),
                                              border: Border.all(
                                                  color: const Color(0xFFFFB347)
                                                      .withValues(alpha: 0.6),
                                                  width: 1),
                                            ),
                                            child: const Text(
                                              'BETA',
                                              style: TextStyle(
                                                color: Color(0xFFFFB347),
                                                fontSize: 9,
                                                fontWeight: FontWeight.w800,
                                                letterSpacing: 0.5,
                                              ),
                                            ),
                                          ),
                                          const SizedBox(width: 6),
                                        ],
                                        Text(
                                          code.toUpperCase(),
                                          style: const TextStyle(
                                              color: Colors.white38,
                                              fontSize: 11,
                                              fontFamily: 'monospace'),
                                        ),
                                      ]),
                                    ),
                                  );
                                }),
                              ),
                            ),
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
                actions: [
                  ElevatedButton(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: const Color(0xFF4FC3F7),
                      foregroundColor: Color(0xFF10241F),
                      padding: const EdgeInsets.symmetric(
                          horizontal: 20, vertical: 10),
                    ),
                    onPressed: confirmAndClose,
                    child: Text(provider.t('btn.continue'),
                        style: const TextStyle(
                            color: Colors.white, fontWeight: FontWeight.w700)),
                  ),
                ],
              ),
            ),
          );
        },
      ),
    );
  }

  /// 初回起動: 言語選択の後に出す「タイムゾーン選択」 ダイアログ。
  /// メルカトル風の世界地図をタップ (= 経度から UTC オフセットを推定) または
  /// 1 時間単位の −/+ で UTC オフセットを選び、 時計の時差として保存する。
  /// 選択後はユーザー名ダイアログへ進む。
  void _showTimezonePicker(MindMapProvider provider) {
    // 端末ローカルの UTC オフセット (分) を初期選択に。
    final deviceUtcMin = DateTime.now().timeZoneOffset.inMinutes;
    // 言語デフォルトがあればそれを優先 (= 端末と言語が食い違う場合に自然)。
    int utcMin = deviceUtcMin;
    // 時 (整数) にスナップ。
    utcMin = (utcMin / 60).round() * 60;
    // 設定言語/初期タイムゾーンの経度を地図の中央に置く (= 自国が中央に来る)。
    final double tzCenterLon = (utcMin / 60.0) * 15.0;

    String fmtUtc(int m) {
      final sign = m < 0 ? '-' : '+';
      final am = m.abs();
      final mm = (am % 60).toString().padLeft(2, '0');
      return 'UTC$sign${am ~/ 60}:$mm';
    }

    void finish() {
      // 時差 = 選択 UTC − 端末ローカル UTC。 ユーザー設定として保存。
      // ignore: discarded_futures
      provider.setClockOffsetMinutes(utcMin - deviceUtcMin);
    }

    showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (dctx) => StatefulBuilder(
        builder: (sctx, setD) {
          // 地図サイズ (画面幅に合わせて調整)
          final mqW = MediaQuery.of(sctx).size.width;
          final mapW = (mqW - 80).clamp(220.0, 360.0);
          final mapH = mapW * 0.52;
          return PopScope(
            canPop: false,
            child: AlertDialog(
              backgroundColor: const Color(0xFF2A2A3E),
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(16)),
              title: Row(children: [
                const Icon(Icons.public_rounded,
                    color: Color(0xFF4FC3F7), size: 22),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(provider.t('tz.title'),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 16,
                          fontWeight: FontWeight.w700)),
                ),
              ]),
              content: SizedBox(
                width: mapW,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(provider.t('tz.hint'),
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                            color: Colors.white60, fontSize: 12)),
                    const SizedBox(height: 10),
                    // ── メルカトル風 世界地図 (タップで経度→UTC を選択) ──
                    ClipRRect(
                      borderRadius: BorderRadius.circular(10),
                      child: GestureDetector(
                        onTapDown: (d) {
                          final dx = d.localPosition.dx.clamp(0.0, mapW);
                          // 画面中央 = tzCenterLon。相対経度 → 絶対経度 → UTC 時。
                          // 中央オフセットにより端のゾーン (UTC+13/+14 等) にも届く。
                          final rel = (dx / mapW) * 360.0 - 180.0;
                          final lon = tzCenterLon + rel;
                          final h = (lon / 15.0).round().clamp(-12, 14);
                          setD(() => utcMin = h * 60);
                        },
                        child: CustomPaint(
                          size: Size(mapW, mapH),
                          painter: _TimezoneMapPainter(
                              selectedUtcMinutes: utcMin,
                              centerLon: tzCenterLon),
                        ),
                      ),
                    ),
                    const SizedBox(height: 12),
                    // ── 1 時間単位の −/+ 微調整 ──
                    Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        IconButton(
                          icon: const Icon(Icons.remove_circle_outline_rounded,
                              color: Color(0xFF4FC3F7)),
                          onPressed: utcMin <= -720
                              ? null
                              : () => setD(() =>
                                  utcMin = ((utcMin / 60).round() - 1) * 60),
                        ),
                        Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 18, vertical: 8),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.06),
                            borderRadius: BorderRadius.circular(8),
                          ),
                          child: Text(fmtUtc(utcMin),
                              style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 18,
                                  fontWeight: FontWeight.w700,
                                  fontFeatures: [
                                    FontFeature.tabularFigures()
                                  ])),
                        ),
                        IconButton(
                          icon: const Icon(Icons.add_circle_outline_rounded,
                              color: Color(0xFF4FC3F7)),
                          onPressed: utcMin >= 840
                              ? null
                              : () => setD(() =>
                                  utcMin = ((utcMin / 60).round() + 1) * 60),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
              actions: [
                ElevatedButton(
                  style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF4FC3F7),
                    foregroundColor: Color(0xFF10241F),
                    padding: const EdgeInsets.symmetric(
                        horizontal: 20, vertical: 10),
                  ),
                  onPressed: () {
                    finish();
                    if (dctx.mounted) Navigator.pop(dctx);
                  },
                  child: Text(provider.t('btn.continue'),
                      style: const TextStyle(
                          color: Colors.white, fontWeight: FontWeight.w700)),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  int _lastPageIndexForCenter = 0;

  /// 初回起動の設定フロー (言語/タイムゾーン/ユーザー名) を 1 度だけ出すためのガード。
  bool _onboardingShown = false;
  void _onProviderChangedForPageSwitch() {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    // ページが増減している事もあるので、 毎回そろえ直す。
    _syncReferencesToProvider(provider);
    if (provider.currentPageIndex != _lastPageIndexForCenter) {
      _lastPageIndexForCenter = provider.currentPageIndex;
      // ── 分割表示中のアクティブ切替では基準位置へ戻さない ──
      // (= ユーザー要望: 基準位置で開かれるのは初回だけにして、 分割で
      //    再度アクティブにしても位置が飛ばないように)。 ペインの表示位置は
      //    アクティブ化時に ctrl 行列ごと引き継いでいるのでそのまま使う。
      if (_mapSplitOpen) return;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _centerOnRoot();
      });
    }
  }

  Future<void> _loadReferencePositions() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final str = prefs.getString('pageReferencePositions');
      if (str == null) return;
      final map = jsonDecode(str) as Map<String, dynamic>;
      _pageReferencePositions.clear();
      for (final e in map.entries) {
        final v = e.value as List<dynamic>;
        _pageReferencePositions[e.key] =
            Offset((v[0] as num).toDouble(), (v[1] as num).toDouble());
      }
      if (mounted) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          _centerOnRoot();
          _syncReferencesToProvider(context.read<MindMapProvider>());
        });
      }
    } catch (_) {}
  }

  Future<void> _saveReferencePositions() async {
    if (mounted) _syncReferencesToProvider(context.read<MindMapProvider>());
    try {
      final prefs = await SharedPreferences.getInstance();
      final map = <String, List<double>>{};
      for (final e in _pageReferencePositions.entries) {
        map[e.key] = [e.value.dx, e.value.dy];
      }
      await prefs.setString('pageReferencePositions', jsonEncode(map));
    } catch (_) {}
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    pdfDrawBurnedNotifier.removeListener(_onPdfDrawBurned);
    if (_isDesktop) {
      try {
        openWithFilesTick.removeListener(_onOpenWithFilesArrived);
        assistantRequestFromFloating.removeListener(_onAssistantRequested);
        commandRequestFromShortcut
            .removeListener(_onShortcutCommandRequested);
        serviceBadgeTick.removeListener(_onServiceBadgeChanged);
        floatingWindowDropProbe = null;
        floatingMemoBridge = null;
      } catch (_) {}
    }
    _pdfPageUiTimer?.cancel();
    _pdfPageUiTimer = null;
    _captionCtrl.dispose();
    _captionFocus.dispose();
    _subAiCtrl.dispose();
    if (_isDesktop) {
      try {
        DesktopMultiWindow.setMethodHandler(null);
      } catch (_) {}
    }
    _edgeScrollTimer?.cancel();
    _mapScrollbarHideTimer?.cancel();
    // 全体図の自動非表示タイマー (= ユーザー要望: 動いている時だけ出す)。
    _miniMapHideTimer?.cancel();
    _lockToastTimer?.cancel();
    _cutFadeTimer?.cancel();
    _eventNotifyTimer?.cancel();
    // アプリ外脱出ロックの自動解除タイマーをキャンセル。
    _appExitLockTimer?.cancel();
    // キー長押しリピート用 Timer を停止
    _mainArrowRepeatDelayTimer?.cancel();
    _mainArrowRepeatTimer?.cancel();
    // 「後で通知」 で予約されたすべての Timer をキャンセル
    for (final t in _pendingNotificationTimers.values) {
      t.cancel();
    }
    _pendingNotificationTimers.clear();
    // フローティング動画窓の残骸を除去 (= 画面破棄後に Overlay に残らない)。
    for (final e in _floatingVideoEntries) {
      try {
        e.remove();
      } catch (_) {}
    }
    _floatingVideoEntries.clear();
    // 画面分割パネル PDF オーバーレイの Timer もキャンセル
    _splitPdfPageOverlayTimer?.cancel();
    HardwareKeyboard.instance.removeHandler(_handleMainGlobalArrowKey);
    WidgetsBinding.instance.pointerRouter
        .removeGlobalRoute(_globalPointerForMapDrop);
    _overlayEntry?.remove();
    // マップ名インライン編集の TextEditingController を破棄
    _mapNameEditCtrl?.dispose();
    // フローティングツールのオーバーレイも片付ける
    _calculatorOverlay?.remove();
    _calculatorOverlay = null;
    _stopwatchOverlay?.remove();
    _stopwatchOverlay = null;
    _sciCalcOverlay?.remove();
    _sciCalcOverlay = null;
    _pomodoroOverlay?.remove();
    _pomodoroOverlay = null;
    _weatherOverlay?.remove();
    _weatherOverlay = null;
    _focusLockOverlay?.remove();
    _focusLockOverlay = null;
    _focusLockScheduleTimer?.cancel();
    _focusLockScheduleTimer = null;
    _geofenceTimer?.cancel();
    _geofenceTimer = null;
    try {
      context
          .read<MindMapProvider>()
          .removeListener(_onProviderChangedForPageSwitch);
    } catch (_) {}
    _keyboardFocusNode.dispose();
    _inlineShelfEditFocus.removeListener(_handleShelfInlineFocusChanged);
    _inlineShelfEditFocus.dispose();
    _inlineShelfEditCtrl.dispose();
    _inlineNodeEditFocus.removeListener(_handleNodeInlineFocusChanged);
    _inlineNodeEditFocus.dispose();
    _inlineNodeEditCtrl.dispose();
    _inlineEditorRevealTimer?.cancel();
    _searchCtrl.dispose();
    _replaceCtrl.dispose();
    _searchFocusNode.dispose();
    _replaceFocusNode.dispose();
    // 画面分割パネル関連の dispose
    _splitUrlCtrl.dispose();
    _splitJumpPageCtrl.dispose();
    _splitWinController?.dispose();
    // 左パネル用 Windows webview_windows のコントローラも dispose
    _splitLeftWinController?.dispose();
    _drawerListScrollCtrl.dispose();
    _timelineDrawerScrollCtrl?.dispose();
    _timelineDragAutoScrollTimer?.cancel();
    _todoInputCtrl.dispose();
    for (final c in _controllers.values) {
      c.dispose();
    }
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    super.didChangeAppLifecycleState(state);
    // ── 本体を最小化してもフローティングは画面に残す (= ユーザー要望:
    //    大元のアプリを非表示にすると一緒に非表示になってしまう) ──
    //    アプリ内の重ね描きは本体の窓と一心同体で消えるしかないので、
    //    最小化された瞬間に「アプリの外の本物の窓」 へ姿を変えて生き残る。
    //    外に出せない窓 (電卓など) はそのまま (= 本体と一緒に隠れる)。
    if (state == AppLifecycleState.hidden && _isDesktop) {
      for (final h in _floatingPopOutHandlers.toList()) {
        unawaited(h());
      }
    }
    // アプリ切替・ウィンドウ非アクティブ化では pointer-up/cancel が届かない
    // 場合がある。パンを停止するドラッグ状態をここで必ず破棄しておく。
    if (state != AppLifecycleState.resumed) {
      _cancelInterruptedCanvasGesture();
      // 保存はまとめて遅延実行しているので (= フリーズ対策)、 前面から外れる
      //   時に待機中のぶんを確実に書き出す。
      try {
        unawaited(context.read<MindMapProvider>().flushSaveToStorage());
      } catch (_) {}
    }
    // ウィンドウが非アクティブになった時点でドラッグは成立しないため、
    // 配置候補だけが残らないよう確実に終了扱いにする。
    if (state != AppLifecycleState.resumed &&
        _activeDesktopHeaderDrag != null) {
      _endDesktopHeaderDrag();
    }
    // ブラウザでの決済から戻ってきた時に、 購入状態を取り込む
    // (= Stripe Webhook → Cloudflare Worker → ここ)。
    if (state == AppLifecycleState.resumed && _isDesktop && mounted) {
      // ignore: discarded_futures
      context.read<MindMapProvider>().syncEntitlementFromServer();
    }
    // 別ウィンドウ／Web タブで保存された変更を、アプリへ戻った時点で
    // ページ単位に調停する。ローカル未編集ページは最新内容へ更新し、
    // 同じページの同時編集は Provider 側で競合コピーとして保護する。
    if (state == AppLifecycleState.resumed) {
      try {
        unawaited(
          context.read<MindMapProvider>().reconcilePageStorageFromOtherTabs(),
        );
      } catch (_) {}
      // フローティングメモの「ページに追加」 を取り込む (= ユーザー要望)。
      unawaited(_consumePendingFloatingMemoAdds());
    }
    // ── アプリ外脱出ロック (トグル式) の離脱対策 ──
    // ロック中にホーム / 他アプリへ飛ぼうとしても、前面に戻った
    //   (resumed) ら OS の画面固定 (lock task) と没入モードを再要求して
    //   抜けられないようにする (= ユーザー要望)。集中ロックの
    //   オーバーレイとは独立に動くので、ここで先に処理する。
    if (_appExitLocked && state == AppLifecycleState.resumed) {
      _osLockStart(); // 既に固定中なら no-op
      try {
        SystemChrome.setEnabledSystemUIMode(SystemUiMode.immersiveSticky);
      } catch (_) {}
    }
    // ── 集中ロック中の離脱対策 (ユーザー要望) ──
    // ロック中にホーム / 他アプリへ飛ぼうとした場合の保険。 アプリが
    //   前面に戻った (resumed) ら OS の画面固定 (lock task) を再要求し、
    //   ロックオーバーレイが残っていることを保証する。
    //   ※ ホーム/他アプリへの遷移自体を完全に塞ぐには、 ネイティブ側
    //     (MainActivity.kt) の startLockTask() による画面固定が必須。
    if (_focusLockOverlay == null) return;
    if (state == AppLifecycleState.resumed) {
      _osLockStart(); // 画面固定を再要求 (既に固定中なら no-op)
      // 設定画面 (WiFi 等) → ホーム → アプリ復帰の経路でロックを抜けられる
      //   問題への対策。オーバーレイが残っていても最前面とは限らないため、
      //   一度 remove して再 insert し、確実にロック画面を最前面へ戻す。
      final entry = _focusLockOverlay!;
      try {
        if (entry.mounted) entry.remove();
        Overlay.of(context, rootOverlay: true).insert(entry);
      } catch (_) {}
      // ロックより前に開いていた動画・AI・Google検索も、この再挿入で
      // 背面へ戻さない。次フレームで同じ OverlayEntry を積み直すため、
      // WebView の状態や入力中のプロンプトをリセットせず最前面を保てる。
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || _focusLockOverlay == null) return;
        GoogleSearchDialog.bringFloatingSingletonsWithPrefixToFront(
            context, 'focus_lock_');
      });
    }
  }

  /// デフォルトの拡大率
  /// PC: 100% = scale 0.75 / モバイル: 100% = scale 0.50
  static double get _baseScale => _isDesktop ? 0.9375 : 0.50;
  static double get _kDefaultScale => _baseScale; // 100%

  /// %表示値 → 実際のスケール値
  double _percentToScale(int percent) => percent / 100.0 * _baseScale;

  /// 実際のスケール値 → %表示値
  int _scaleToPercent(double scale) => (scale / _baseScale * 100).round();

  TransformationController _ctrlFor(String pageId) {
    if (!_controllers.containsKey(pageId)) {
      final c = TransformationController();
      _controllers[pageId] = c;
      c.value = _matrixFor(const Offset(900, 900), _kDefaultScale);
      // ── 分割ペイン用 ('split_...') のコントローラには編集側の変換
      //    リスナーを付けない (= ユーザー要望: 他の分割画面を動かした時に
      //    左上の画面のスクロールバーまで連動して出る問題の修正)。
      //    _onTransformChanged は _lastMatrix / ロック補正 / バー表示など
      //    「編集キャンバス専用」 の処理のため、 ペインの変換で発火すると
      //    誤作動する。 ──
      if (!pageId.startsWith('split_')) {
        c.addListener(() => _onTransformChanged(c));
      }
    }
    return _controllers[pageId]!;
  }

  Matrix4? _lastMatrix;

  /// クランプ中の再入を防ぐフラグ (ctrl.value 変更がリスナーを再発火するため)。
  bool _clampingShelf = false;

  /// ギャラリー (本棚) のパンを内容範囲に制限する (= ユーザー要望: +ボックスの
  /// 無い空白へスワイプして出て行けないように)。 ノード + フロンティアの +ボックス
  /// のバウンディングボックスが常にビューポート内に留まるよう translation を
  /// クランプする。 `_onTransformChanged` (パン/フリック中に連続発火) から呼ぶ。
  /// ギャラリー (本棚) の内容 (ノード + +ボックス) のキャンバス座標
  /// バウンディング。 パンのクランプとスクロールバーの可動域の両方で使う
  /// (= ユーザー要望: 移動が制限される位置でスクロールバーが端まで来るように、
  /// 2 つの範囲を一致させる)。 内容が無ければ null。
  Rect? _bookshelfContentBounds(MindMapProvider provider) {
    double minX = double.infinity,
        minY = double.infinity,
        maxX = -double.infinity,
        maxY = -double.infinity;
    void acc(double l, double t, double r, double b) {
      if (l < minX) minX = l;
      if (t < minY) minY = t;
      if (r > maxX) maxX = r;
      if (b > maxY) maxY = b;
    }

    for (final n in provider.currentPage.nodes.values) {
      acc(n.position.dx, n.position.dy, n.position.dx + n.width,
          n.position.dy + n.visualHeight);
    }
    for (final r in provider.bookshelfFrontierRects()) {
      acc(r.left, r.top, r.right, r.bottom);
    }
    if (!minX.isFinite) return null;
    return Rect.fromLTRB(minX, minY, maxX, maxY);
  }

  void _clampBookshelfPan(TransformationController ctrl) {
    if (_clampingShelf) return;
    final provider = context.read<MindMapProvider>();
    if (provider.currentPage.pageType != 'bookshelf') return;
    // 内容 (ノード + +ボックス) のキャンバス座標バウンディング。
    final bounds = _bookshelfContentBounds(provider);
    if (bounds == null) return;
    final minX = bounds.left,
        minY = bounds.top,
        maxX = bounds.right,
        maxY = bounds.bottom;

    final m = ctrl.value;
    final scale = m.getMaxScaleOnAxis();
    final t = m.getTranslation();
    // ── ビューポートはマップが実際に見えている領域 (= ユーザー要望) ──
    // AI チャット欄 / PDF 等の画面分割パネルを開くと Flex(Row/Column) でマップ
    //   領域がその分だけ狭くなる。 旧実装は全画面幅 (MediaQuery) でクランプして
    //   いたため、 列数が多い (例: 7 列) ギャラリーでパネルを出すと、 右端の列が
    //   パネルの裏に固定されて手前に引き出せず閲覧できなかった。
    //   左右/下分割は Flex の別チャイルドなので、 マップ側の local 原点は隠れず
    //   「幅/高さを縮める」 だけで正しくクランプできる。 上分割だけはオーバーレイ
    //   (Flex 外) で local の上端が隠れるため、 縦を縮めると逆にパネル裏へ寄せて
    //   しまうので従来どおり全高で扱う。
    // 分割中は編集セルの大きさで判定する (= ユーザー報告: 表示されていない
    // 領域分まで考慮されて端までスクロールできない)。
    final size = _mapSplitOpen
        ? _splitCellGlobalRect(_mapSplitEditorSlot).size
        : MediaQuery.sizeOf(context);
    const double splitterW = 8.0;
    double viewW = size.width;
    double viewH = size.height;
    if (_splitOpen) {
      final eff = _splitPanelEffectiveSize(context);
      switch (_splitPosition) {
        case _SplitPosition.right:
        case _SplitPosition.left:
          viewW = (size.width - eff - splitterW).clamp(50.0, size.width);
          break;
        case _SplitPosition.bottom:
          viewH = (size.height - eff - splitterW).clamp(50.0, size.height);
          break;
        case _SplitPosition.top:
          break; // オーバーレイのため縦は縮めない
      }
    }
    if (_splitLeftOpen) {
      final leftEff = _splitLeftPanelWidth
          .clamp(size.width * 0.20, size.width * 0.90)
          .toDouble();
      viewW = (viewW - leftEff - splitterW).clamp(50.0, size.width);
    }
    // 端にわずかな余白は許す。 キャンバス座標 120px ぶん (スクロールバーの
    // 可動域計算 _canvasBoundaryMarginForScrollbars と同じ値にして、 バーが
    // ちょうど端に来る位置でパンも止まるようにする = ユーザー要望)。
    final buffer = 120.0 * scale;

    // 画面座標: screen = scale * canvas + translation。
    // 内容が常にビューポートを覆う/収まるよう translation を制限。
    double clampAxis(double tv, double cMin, double cMax, double viewLen) {
      final contentLen = scale * (cMax - cMin);
      double lo, hi;
      if (contentLen >= viewLen) {
        // 内容が画面より大きい → 端を越えて空白を出せない。
        lo = viewLen - scale * cMax - buffer; // 内容右端を画面右に寄せる下限
        hi = -scale * cMin + buffer; // 内容左端を画面左に寄せる上限
      } else {
        // 内容が画面より小さい → 画面からはみ出さない範囲に収める。
        lo = -scale * cMin - buffer;
        hi = viewLen - scale * cMax + buffer;
      }
      if (lo > hi) return (lo + hi) / 2;
      return tv.clamp(lo, hi);
    }

    final ntx = clampAxis(t.x, minX, maxX, viewW);
    final nty = clampAxis(t.y, minY, maxY, viewH);
    if ((ntx - t.x).abs() > 0.5 || (nty - t.y).abs() > 0.5) {
      _clampingShelf = true;
      final fixed = Matrix4.copy(m)..setTranslationRaw(ntx, nty, 0);
      ctrl.value = fixed;
      _lastMatrix = fixed.clone();
      _clampingShelf = false;
    }
  }

  /// 今表示している範囲の中心 (キャンバス座標) を provider に伝える。
  /// MCP / AI が作ったノードを「見ている所」 に置くために使う
  /// (= ユーザー要望: 右下に作られると探すのが面倒)。
  void _reportViewCenter(TransformationController ctrl) {
    try {
      final m = ctrl.value;
      final sc = m.getMaxScaleOnAxis();
      if (sc <= 0) return;
      final t = m.getTranslation();
      final sz =
          View.of(context).physicalSize / View.of(context).devicePixelRatio;
      // 画面中央のスクリーン座標 → キャンバス座標。 ノードの左上が中央に
      // 来るよう、 ノードの見かけの中心分だけ戻す。
      final cx = (sz.width / 2 - t.x) / sc - 80;
      final cy = (sz.height / 2 - t.y) / sc - 28;
      context.read<MindMapProvider>().setMcpViewCenter(Offset(cx, cy));
    } catch (_) {}
  }

  /// MCP が書き込んだ後、 そのページへ切り替えて内容が見える位置に寄せる。
  int _lastHandledMcpFocusSeq = 0;
  void _handleMcpFocus(MindMapProvider provider) {
    final seq = provider.mcpFocusSeq;
    if (seq == _lastHandledMcpFocusSeq) return;
    _lastHandledMcpFocusSeq = seq;
    final pid = provider.mcpFocusPageId;
    if (pid == null) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final idx = provider.pages.indexWhere((p) => p.id == pid);
      if (idx < 0) return;
      if (provider.currentPageIndex != idx) provider.switchPage(idx);
      // 置かれたノードの中心へ寄せる (何も無ければ何もしない)。
      final page = provider.pages[idx];
      if (page.nodes.isEmpty) return;
      var minX = double.infinity, minY = double.infinity;
      var maxX = -double.infinity, maxY = -double.infinity;
      for (final n in page.nodes.values) {
        minX = math.min(minX, n.position.dx);
        minY = math.min(minY, n.position.dy);
        maxX = math.max(maxX, n.position.dx + n.width);
        maxY = math.max(maxY, n.position.dy + n.visualHeight);
      }
      if (!minX.isFinite || !minY.isFinite) return;
      final center = Offset((minX + maxX) / 2 - 80, (minY + maxY) / 2 - 28);
      try {
        _ctrlFor(page.id).value =
            _matrixFor(center, _percentToScale(_scalePercent));
      } catch (_) {}
    });
  }

  void _onTransformChanged(TransformationController ctrl) {
    if (_applyingInlineEditorRevealTransform) {
      _lastMatrix = ctrl.value.clone();
      return;
    }
    if (_lastMatrix == null) {
      _lastMatrix = ctrl.value.clone();
      return;
    }
    final previousTranslation = _lastMatrix!.getTranslation();
    final currentTranslation = ctrl.value.getTranslation();
    if ((previousTranslation.x - currentTranslation.x).abs() > 0.1 ||
        (previousTranslation.y - currentTranslation.y).abs() > 0.1) {
      _markMapScrollActivity();
    }

    // 全体図は動いている間だけ出す (= ユーザー要望)。 拡大縮小も含めて
    //   ここを通るので、 まとめてここで合図する。
    _markMiniMapActivity();
    // ギャラリー (本棚) のパンを内容範囲に制限 (= ユーザー要望)。
    _clampBookshelfPan(ctrl);
    // 今見ている場所を控える (MCP/AI の生成物をここに置くため)。
    _reportViewCenter(ctrl);
    if (!_lockH && !_lockV && !_lockScale) {
      _lastMatrix = ctrl.value.clone();
      // ジェスチャーでスケールが変わったら表示値も更新
      final s = ctrl.value.getMaxScaleOnAxis();
      final percent = _scaleToPercent(s).clamp(50, 150);
      if (percent != _scalePercent) {
        _scalePercent = percent;
        // setStateはリスナー内で直接呼べないのでpostFrameCallbackで。
        // 拡大率は常時ツールバーに出さず、操作した時だけ数秒表示する。
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) _showLockToast('\u{1F50D} $_scalePercent%');
        });
      }
      return;
    }
    final cur = ctrl.value;
    final prev = _lastMatrix!;
    final curTx = cur.getTranslation();
    final prevTx = prev.getTranslation();
    bool needFix = false;
    double tx = curTx.x, ty = curTx.y;

    // ↔ON → 横方向固定 → xを元に戻す
    if (_lockH && curTx.x != prevTx.x) {
      tx = prevTx.x;
      needFix = true;
    }
    // ↕ON → 縦方向固定 → yを元に戻す
    if (_lockV && curTx.y != prevTx.y) {
      ty = prevTx.y;
      needFix = true;
    }

    // 拡大率固定: scaleが変わったら元に戻す
    if (_effectiveLockScale) {
      final curScale = cur.getMaxScaleOnAxis();
      final prevScale = prev.getMaxScaleOnAxis();
      if ((curScale - prevScale).abs() > 0.001) {
        ctrl.value = prev;
        _lastMatrix = prev.clone();
        return;
      }
    } else {
      // スケールフリー時は表示値を更新
      final s = cur.getMaxScaleOnAxis();
      final percent = _scaleToPercent(s).clamp(50, 150);
      if (percent != _scalePercent) {
        _scalePercent = percent;
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) _showLockToast('\u{1F50D} $_scalePercent%');
        });
      }
    }

    if (needFix) {
      final fixed = Matrix4.copy(cur);
      fixed.setTranslationRaw(tx, ty, 0);
      ctrl.value = fixed;
    }
    _lastMatrix = ctrl.value.clone();
  }

  Matrix4 _matrixFor(Offset p, [double? scale]) {
    final sc = scale ?? _kDefaultScale;
    final sz =
        View.of(context).physicalSize / View.of(context).devicePixelRatio;
    final tx = sz.width / 2 - (p.dx + 80) * sc;
    final ty = sz.height / 2 - (p.dy + 28) * sc;
    return Matrix4.identity()
      ..translate(tx, ty)
      ..scale(sc);
  }

  void _centerOnRoot() {
    final provider = context.read<MindMapProvider>();
    if (provider.pages.isEmpty) return;
    final scale = _percentToScale(_scalePercent);
    final pageId = provider.currentPage.id;
    // ページごとの基準位置があればそれを使う
    final refPos = _pageReferencePositions[pageId] ?? _referencePos;
    _ctrlFor(pageId).value = _matrixFor(refPos, scale);
  }

  /// 知っている基準位置を provider へ渡す (= ユーザー要望: 位置の指定が
  /// 無い時は基準位置の付近に作る)。 基準位置は画面側が持っているので、
  /// MCP / AI が使えるように控えてもらう。 ページ数ぶんの代入だけなので
  /// 切り替えのたびに呼んでも軽い。
  void _syncReferencesToProvider(MindMapProvider provider) {
    for (final p in provider.pages) {
      provider.setMcpPageReference(
          p.id, _pageReferencePositions[p.id] ?? _referencePos);
    }
  }

  /// 現在ページの基準位置（自動整列などで中心座標として使用）
  Offset _currentRefPos() {
    final provider = context.read<MindMapProvider>();
    if (provider.pages.isEmpty) return _referencePos;
    final pageId = provider.currentPage.id;
    return _pageReferencePositions[pageId] ?? _referencePos;
  }

