  /// 格納ノードをタップした時に表示される「展開」ポップアップ。
  /// ノードの上部に小さな吹き出しメニューとして表示し、
  /// 「展開」ボタンを押すと provider.unpackContainer が呼ばれて元の状態に戻る。
  void _showContainerExpandPopup(String nodeId, TransformationController ctrl) {
    _removeOverlay();
    final provider = context.read<MindMapProvider>();
    final node = provider.nodes[nodeId];
    if (node == null || !node.isContainer) return;

    setState(() => _actionNodeId = nodeId);
    // ノードの右上あたりに表示するためのスクリーン座標を計算
    final canvasPos = Offset(
      node.position.dx + node.width / 2,
      node.position.dy,
    );
    final matrix = ctrl.value;
    final scale = matrix.getMaxScaleOnAxis();
    final translation = matrix.getTranslation();
    // ノード上部のスクリーン座標（中央寄せで表示）
    final screenX = canvasPos.dx * scale + translation.x;
    final screenY = canvasPos.dy * scale + translation.y;

    _overlayEntry = OverlayEntry(
      builder: (overlayCtx) {
        return Positioned(
          left: screenX - 70,
          top: screenY - 56,
          child: Material(
            color: Colors.transparent,
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              Container(
                padding: const EdgeInsets.all(6),
                decoration: BoxDecoration(
                  color: const Color(0xFF2A2A3E),
                  borderRadius: BorderRadius.circular(24),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black.withValues(alpha: 0.5),
                      blurRadius: 10,
                    ),
                  ],
                  border: Border.all(
                      color: const Color(0xFFFFA726).withValues(alpha: 0.6),
                      width: 1.2),
                ),
                child: InkWell(
                  onTap: () {
                    _removeOverlay();
                    provider.unpackContainer(nodeId);
                    setState(() => _actionNodeId = null);
                  },
                  borderRadius: BorderRadius.circular(18),
                  child: Padding(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      const Icon(Icons.unarchive_rounded,
                          color: Color(0xFFFFA726), size: 18),
                      const SizedBox(width: 6),
                      Text(provider.t('ctx.unpackContainer'),
                          style: const TextStyle(
                              color: Colors.white,
                              fontSize: 13,
                              fontWeight: FontWeight.w600)),
                    ]),
                  ),
                ),
              ),
            ]),
          ),
        );
      },
    );
    Overlay.of(context, rootOverlay: true).insert(_overlayEntry!);
  }

  /// 描画用の接続線を計算する。
  ///
  /// - 両端が格納ノード内 → 非表示
  /// - 片端だけが格納ノード内 → 隠れている側を「格納先コンテナ」に置換
  ///   （コンテナが外部と接続されているように見せる）
  /// - 同じ (外部, コンテナ) のペアが複数回出てきても 1 本だけ残す
  List<NodeConnection> _effectiveConnections(
      Map<String, MindMapNode> nodes, List<NodeConnection> conns) {
    final result = <NodeConnection>[];
    // 重複削除用: "from|to" 形式のキー
    final seen = <String>{};
    for (final c in conns) {
      final from = nodes[c.fromId];
      final to = nodes[c.toId];
      if (from == null || to == null) {
        result.add(c);
        continue;
      }
      final fromHidden = from.hiddenInContainer;
      final toHidden = to.hiddenInContainer;
      if (fromHidden != null && toHidden != null) {
        // 両端ともコンテナ内: 描画しない
        continue;
      }
      if (fromHidden == null && toHidden == null) {
        // 両端とも可視: そのまま
        result.add(c);
        continue;
      }
      // 片方だけが隠れている → 隠れている側を containerId に置換
      String newFromId = c.fromId;
      String newToId = c.toId;
      if (fromHidden != null) {
        newFromId = fromHidden;
      }
      if (toHidden != null) {
        newToId = toHidden;
      }
      // 同じノード同士になったらスキップ（同一コンテナ内のノード同士）
      if (newFromId == newToId) continue;
      // 置換後のコンテナノードが存在し、かつ可視であること
      final nf = nodes[newFromId];
      final nt = nodes[newToId];
      if (nf == null || nt == null) continue;
      if (nf.hiddenInContainer != null || nt.hiddenInContainer != null) {
        continue;
      }
      // 無向重複を弾く
      final k1 = '$newFromId|$newToId';
      final k2 = '$newToId|$newFromId';
      if (seen.contains(k1) || seen.contains(k2)) continue;
      seen.add(k1);
      result.add(NodeConnection(
        fromId: newFromId,
        fromAnchor: c.fromAnchor,
        toId: newToId,
        toAnchor: c.toAnchor,
        strokeWidth: c.strokeWidth,
        showArrow: c.showArrow,
        arrowHeadScale: c.arrowHeadScale,
        bidirectional: c.bidirectional,
        label: c.label,
        labelPosition: c.labelPosition,
        lineColorValue: c.lineColorValue,
        relationshipType: c.relationshipType,
        lineStyle: c.lineStyle,
        elbowSplitRatio: c.elbowSplitRatio,
        elbowPointCount: c.elbowPointCount,
        elbowBendPoints: c.elbowBendPoints,
      ));
    }
    return result;
  }

  // ─── 裁断モード ───────────────────────────────────────────────────────
  /// 裁断モード中のクリックを処理する。
  /// 1 回目のクリック: [_cutStartPoint] を記録
  /// 2 回目のクリック: 始点 → 終点の線分で、交差する接続を切断し、
  ///                  交差する名前付きグループを左右に分割する。
  ///                  その後、両点をクリアして次の裁断に備える。
  void _handleCutClick(Offset canvasPos) {
    if (_cutStartPoint == null) {
      // 1 回目のクリック: 始点を記録
      setState(() {
        _cutStartPoint = canvasPos;
        _cutPreviewEnd = canvasPos;
      });
      return;
    }
    // 2 回目のクリック: 裁断実行
    final provider = context.read<MindMapProvider>();
    final a = _cutStartPoint!;
    final b = canvasPos;

    // ── 接続線との交差判定 → 切断 ──
    final toRemove = <NodeConnection>[];
    for (final c in List<NodeConnection>.from(provider.connections)) {
      final from = provider.nodes[c.fromId];
      final to = provider.nodes[c.toId];
      if (from == null || to == null) continue;
      if (from.hiddenInContainer != null || to.hiddenInContainer != null)
        continue;
      final p1 = from.anchorPoint(c.fromAnchor);
      final p2 = to.anchorPoint(c.toAnchor);
      if (_segmentsIntersect(a, b, p1, p2)) {
        toRemove.add(c);
      }
    }
    // ── 裁断で切れる接続/グループを 1 回の undo でまとめて戻せるように、
    //    一連のミューテーションを undo バッチで囲む (= ユーザー要望:
    //    複数リンクを一度に切った時戻るで 1 個ずつ戻るのを解消) ──
    final cutBatched = toRemove.isNotEmpty;
    if (cutBatched) provider.beginUndoBatch();
    for (final c in toRemove) {
      provider.severConnection(fromId: c.fromId, toId: c.toId);
    }

    // ── 名前付きグループ矩形との交差判定 → 分割 or 解除 ──
    // 【仕様】
    //   - メンバ 2 つ以上: 貫通すると左/右に分割
    //   - メンバ 1 つ:     貫通すると「グループ解除」(付箋枠を消す)
    //   - 始点と終点が両方とも矩形の外側にあり、かつ線分が矩形を横切る場合のみ
    //   - 終点が矩形内に入っていたら何もしない（「抜ける動作」が完了していないため）
    final namedGroups = provider.namedGroups;
    for (final entry in namedGroups.entries.toList()) {
      final groupName = entry.key;
      final memberIds =
          entry.value.where((id) => provider.nodes.containsKey(id)).toList();
      if (memberIds.isEmpty) continue;

      // グループの外接矩形（付箋パディング込み）
      double minX = double.infinity, minY = double.infinity;
      double maxX = -double.infinity, maxY = -double.infinity;
      for (final id in memberIds) {
        final n = provider.nodes[id]!;
        if (n.position.dx < minX) minX = n.position.dx;
        if (n.position.dy < minY) minY = n.position.dy;
        final r = n.position.dx + n.width;
        final bo = n.position.dy + n.visualHeight;
        if (r > maxX) maxX = r;
        if (bo > maxY) maxY = bo;
      }
      if (minX == double.infinity) continue;
      const pad = 28.0;
      const labelH = 28.0;
      final rect = Rect.fromLTRB(
          minX - pad, minY - pad - labelH, maxX + pad, maxY + pad);

      // 始点/終点どちらかが矩形内にある → 分割しない
      // （「外 → 内 → 外」の貫通でなければグループは切らない）
      if (rect.contains(a) || rect.contains(b)) continue;

      // 両端が外側 かつ 線分が辺と交差 → 貫通したと判定
      final tl = rect.topLeft;
      final tr = rect.topRight;
      final bl = rect.bottomLeft;
      final br = rect.bottomRight;
      final crosses = _segmentsIntersect(a, b, tl, tr) ||
          _segmentsIntersect(a, b, tr, br) ||
          _segmentsIntersect(a, b, br, bl) ||
          _segmentsIntersect(a, b, bl, tl);
      if (!crosses) continue;

      // ── メンバ 1 つのグループ: 貫通したらグループ解除 ──
      // 付箋枠だけを消したい (ノードは残る)。
      if (memberIds.length == 1) {
        provider.removeNamedGroup(groupName);
        continue;
      }

      // カット線に対してノードの中心がどちら側かで振り分け
      final leftIds = <String>{};
      final rightIds = <String>{};
      for (final id in memberIds) {
        final n = provider.nodes[id]!;
        final cx = n.position.dx + n.width / 2;
        final cy = n.position.dy + n.visualHeight / 2;
        // 外積符号: (b-a) × (c-a) > 0 なら左側
        final cross = (b.dx - a.dx) * (cy - a.dy) - (b.dy - a.dy) * (cx - a.dx);
        if (cross >= 0) {
          leftIds.add(id);
        } else {
          rightIds.add(id);
        }
      }
      if (leftIds.isNotEmpty && rightIds.isNotEmpty) {
        provider.splitNamedGroup(
          groupName: groupName,
          leftIds: leftIds,
          rightIds: rightIds,
          cutStart: a,
          cutEnd: b,
        );
      }
    }
    if (cutBatched) provider.endUndoBatch();

    // 裁断完了 → 実行された裁断線を一瞬だけ残してから消す（視覚フィードバック）
    _cutFadeTimer?.cancel();
    setState(() {
      _cutStartPoint = null;
      _cutPreviewEnd = null;
      _cutFadingLine = [a, b];
    });
    _cutFadeTimer = Timer(const Duration(milliseconds: 450), () {
      if (!mounted) return;
      setState(() => _cutFadingLine = null);
    });
  }

  /// 裁断モードを終了 or リセット時に呼ぶ
  void _resetCutStroke() {
    _cutStartPoint = null;
    _cutPreviewEnd = null;
    _cutFadingLine = null;
    _cutFadeTimer?.cancel();
  }

  /// 2 線分 [p1→p2] と [p3→p4] が交差するかを返す（端点での接触も true）
  bool _segmentsIntersect(Offset p1, Offset p2, Offset p3, Offset p4) {
    double cross(Offset o, Offset a, Offset b) {
      return (a.dx - o.dx) * (b.dy - o.dy) - (a.dy - o.dy) * (b.dx - o.dx);
    }

    final d1 = cross(p3, p4, p1);
    final d2 = cross(p3, p4, p2);
    final d3 = cross(p1, p2, p3);
    final d4 = cross(p1, p2, p4);
    if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) &&
        ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) {
      return true;
    }
    return false;
  }

  /// PC版：拡大率をパーセントで変更（現在の表示中心を維持）
  /// ユーザーが明示的に呼び出す操作 (拡大率入力ダイアログ / カスタムボタンの
  /// zoomIn5・zoomOut5) なので、_lockScale が ON でも適用する。
  /// lockScale ガードは _onTransformChanged 側で「直前 _lastMatrix と
  /// 現在 ctrl.value のスケール差」を見て巻き戻すため、ここで先に
  /// _lastMatrix を新しい行列に同期させてから ctrl.value を更新する。
  /// キーボードショートカット等の基準となる「編集キャンバスの中心」。
  /// 分割表示中はアクティブ (編集) 側ペインの中心を返す (= ユーザー要望:
  /// 分割中の Ctrl+± やノード追加がアクティブ側で動くように)。
  /// [global] = true なら画面全体座標、 false なら編集ビューポート内の
  /// ローカル座標 (ctrl の translation と組で使う)。
  //
  // ★ 編集セルの矩形は `_splitCellGlobalRect(_mapSplitEditorSlot)` に一本化。
  //   以前は 0.5 決め打ちの割合矩形 (_editorCellFrac) を別に持っていたため、
  //   境界線をドラッグして分割比を変えるとズーム / ノード追加 / 全画面
  //   ダイアログの基準点がセルの中心からずれ、 操作のたびに表示が変な方向へ
  //   動いていた (= ユーザー報告)。
  Offset _editorViewportCenter(MindMapProvider provider,
      {bool global = false}) {
    final s = View.of(context).physicalSize / View.of(context).devicePixelRatio;
    final t = provider.currentPage.pageType;
    final split = _mapSplitOpen &&
        t != 'paint' &&
        t != 'document' &&
        t != 'videoEditor';
    if (!split) return Offset(s.width / 2, s.height / 2);
    // ★ セルの矩形は _splitCellGlobalRect と同じ計算で求める (AppBar の
    //   高さを引いた body 基準 + 境界線の比率)。 画面全体の割合で計算して
    //   いた頃は、 ズームやノード追加の基準点がセルの中心から常にずれて
    //   いた (= ユーザー報告: 切り替えや操作で変な方向に動く)。
    final r = _splitCellGlobalRect(_mapSplitEditorSlot);
    // ペイン内ローカル座標 (ctrl の translation と組で使う) / 画面全体座標。
    return global ? r.center : Offset(r.width / 2, r.height / 2);
  }

  void _applyScale(int percent) {
    final scale = _percentToScale(percent);
    _scalePercent = percent;
    _showLockToast('\u{1F50D} $percent%');
    final provider = context.read<MindMapProvider>();
    if (provider.pages.isEmpty) return;
    final ctrl = _ctrlFor(provider.currentPage.id);
    // 分割中はアクティブ側ペインの中心を基準にズームする (= ユーザー要望)。
    final c = _editorViewportCenter(provider);
    // 現在の画面中央のキャンバス座標を保持したままスケール変更
    final currentMatrix = ctrl.value;
    final prevScale = currentMatrix.getMaxScaleOnAxis();
    final tx = currentMatrix.getTranslation().x;
    final ty = currentMatrix.getTranslation().y;
    // 画面中央のキャンバス座標
    final cx = (c.dx - tx) / prevScale;
    final cy = (c.dy - ty) / prevScale;
    // 新しいtranslation
    final newTx = c.dx - cx * scale;
    final newTy = c.dy - cy * scale;
    final newMatrix = Matrix4.identity()
      ..translate(newTx, newTy)
      ..scale(scale);
    // ── ctrl.value を更新する前に _lastMatrix を新しい行列へ同期 ──
    // これにより _onTransformChanged が走った瞬間 (curScale - prevScale)
    // がほぼ 0 となり、lockScale ON でも巻き戻されない。
    _lastMatrix = newMatrix.clone();
    ctrl.value = newMatrix;
  }

  /// PC版：拡大率入力ダイアログ
  void _showScaleInputDialog() {
    final ctrl = TextEditingController(text: _scalePercent.toString());
    showDialog(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(context.read<MindMapProvider>().t('zoom.specify'),
            style: TextStyle(color: Colors.white, fontSize: 14)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          keyboardType: TextInputType.number,
          style: const TextStyle(color: Colors.white, fontSize: 16),
          decoration: InputDecoration(
            filled: true,
            fillColor: Colors.white.withValues(alpha: 0.07),
            suffixText: '%',
            suffixStyle: const TextStyle(color: Colors.white54),
            hintText: context.read<MindMapProvider>().t('zoom.hint100'),
            hintStyle: const TextStyle(color: Colors.white38),
            border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(10),
                borderSide: BorderSide.none),
            contentPadding:
                const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
          ),
          onSubmitted: (v) {
            final val = int.tryParse(v.trim());
            if (val != null && val > 0) {
              Navigator.pop(dctx);
              _applyScale(val);
            }
          },
        ),
        actions: [
          // プリセットボタン
          Wrap(
            spacing: 6,
            children: [50, 75, 100, 120, 150]
                .map((p) => GestureDetector(
                      onTap: () {
                        Navigator.pop(dctx);
                        _applyScale(p);
                      },
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 10, vertical: 5),
                        decoration: BoxDecoration(
                          color:
                              const Color(0xFF6C63FF).withValues(alpha: 0.25),
                          borderRadius: BorderRadius.circular(8),
                        ),
                        child: Text('$p%',
                            style: const TextStyle(
                                color: Colors.white70, fontSize: 12)),
                      ),
                    ))
                .toList(),
          ),
          const SizedBox(height: 4),
          Row(mainAxisAlignment: MainAxisAlignment.end, children: [
            TextButton(
                onPressed: () => Navigator.pop(dctx),
                child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                    style: TextStyle(color: Colors.white54))),
            ElevatedButton(
              onPressed: () {
                final val = int.tryParse(ctrl.text.trim());
                if (val != null && val > 0) {
                  Navigator.pop(dctx);
                  _applyScale(val);
                }
              },
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6C63FF),
                  foregroundColor: Colors.white,),
              child: Text(context.read<MindMapProvider>().t('btn.apply')),
            ),
          ]),
        ],
      ),
    );
  }

  // ─── 座標変換 ────────────────────────────────────────────────────────────

  /// 分割中に、 その画面座標が「編集しているペイン」 の中かどうか。
  /// 分割していない時は常に true。
  ///
  /// 範囲選択 (Shift+ドラッグ) の開始判定に使う。 これが無いと、 他のペイン
  /// (別のマップやギャラリー) の上でドラッグしても編集ペインの範囲選択が
  /// 始まってしまい、 両方が同時に動いているように見える
  /// (= ユーザー報告: 分割中に Shift ドラッグすると他のマップも range 選択)。
  bool _pointerInEditorCell(Offset globalPos) {
    if (!_mapSplitOpen) return true;
    try {
      final r = _splitCellGlobalRect(_mapSplitEditorSlot);
      if (r.width <= 0 || r.height <= 0) return true;
      return r.contains(globalPos);
    } catch (_) {
      return true;
    }
  }

  // ── PDF のページ送りで画面全体を作り直さない (= ユーザー報告: PDF を
  //    高速でスクロールすると固まる) ──
  //   onPageChanged はスクロール中に何度も飛んでくる。 そのたびに
  //   setState するとこの巨大な画面が丸ごと再構築され、 描画が追いつかない。
  //   値の更新は即座に行い、 再描画だけを一定間隔にまとめる。
  Timer? _pdfPageUiTimer;

  void _applyPdfPageChange(VoidCallback apply) {
    apply(); // 値は遅らせない (ページ番号の記録や入力欄の同期はすぐ反映)
    if (_pdfPageUiTimer != null) return; // すでに再描画を予約済み
    _pdfPageUiTimer = Timer(const Duration(milliseconds: 160), () {
      _pdfPageUiTimer = null;
      if (mounted) setState(() {});
    });
  }

  Offset _globalToCanvas(Offset globalPos, TransformationController ctrl) {
    // canvasKey は InteractiveViewer 内の Stack に付いているためキャンバス座標系と一致
    final box = _canvasKey.currentContext?.findRenderObject() as RenderBox?;
    if (box != null) {
      return box.globalToLocal(globalPos);
    }
    // フォールバック
    return MatrixUtils.transformPoint(Matrix4.inverted(ctrl.value), globalPos);
  }

  Offset _canvasToGlobal(Offset canvasPos, TransformationController ctrl) {
    final box = _canvasKey.currentContext?.findRenderObject() as RenderBox?;
    if (box != null) {
      return box.localToGlobal(canvasPos);
    }
    return MatrixUtils.transformPoint(ctrl.value, canvasPos);
  }

  // ─── 長押しドラッグハンドラ（長押しと同時にそのままドラッグ） ─────────────

  /// 長押し開始：ムーブモード突入＋ドラッグアンカー設定
  /// 他の参加者が編集中 (ロック中) なら知らせて操作を止める (= ユーザー要望:
  /// 競合を防ぐため、 編集中の要素は他のユーザーからロックが掛かるように)。
  /// 触ってよければ false。
  bool _blockedByLiveLock(String nodeId) {
    final provider = context.read<MindMapProvider>();
    // 閲覧のみの権限で参加している時は編集させない (= ユーザー要望: 権限)。
    if (provider.liveActive && !provider.liveCanEdit) {
      _showLockToast(provider.t('live.viewOnlyNotice'));
      return true;
    }
    final owner = provider.liveLockOwnerOf(nodeId);
    if (owner == null) return false;
    _showLockToast(provider
        .t('live.lockedBy')
        .replaceFirst('{name}', owner.name.isEmpty ? '...' : owner.name));
    return true;
  }

  /// 付箋グループのお仲間を一緒に動かすための一時集合 (= ユーザー要望:
  /// グループ化された項目はまとめて動かせるように)。 掴んだノード自身は
  /// 含めない。 ドラッグ開始で作り、 終了で空にする。
  final Set<String> _groupDragIds = <String>{};

  /// 掴んだ位置 (= 差分を出す基準)。
  Offset? _groupDragStartPos;

  /// [nodeId] が入っている付箋グループのお仲間 (自分は除く) を集める。
  Set<String> _groupMatesOf(MindMapProvider provider, String nodeId) {
    final mates = <String>{};
    for (final members in provider.namedGroups.values) {
      if (!members.contains(nodeId)) continue;
      for (final m in members) {
        if (m == nodeId) continue;
        // 格納で隠れている / 既に無いノードは動かさない。
        final n = provider.nodes[m];
        if (n == null || n.hiddenInContainer != null) continue;
        mates.add(m);
      }
    }
    return mates;
  }

  void _onLongPressNodeStart(
      String nodeId, Offset globalPos, TransformationController ctrl) {
    if (_blockedByLiveLock(nodeId)) return;
    _removeOverlay();
    final provider = context.read<MindMapProvider>();
    final node = provider.nodes[nodeId];
    if (node == null) return;
    final canvasPos = _globalToCanvas(globalPos, ctrl);
    // ── 付箋グループのお仲間を一緒に動かす (= ユーザー要望) ──
    //    範囲選択でまとめて掴んでいる時は、 そちらの動きに任せる。
    final mates = _rangeSelectedIds.isEmpty
        ? _groupMatesOf(provider, nodeId)
        : <String>{};
    setState(() {
      _moveModeNodeId = nodeId;
      _selectedConnections.clear();
      _clearConnectionBendDragFields(clearSelection: true);
      _moveDragAnchor = canvasPos - node.position;
      _movingPos = node.position;
      _groupDragStartPos = node.position;
      _groupDragIds
        ..clear()
        ..addAll(mates);
    });
    // エッジスクロールタイマー開始
    _lastDragGlobalPos = globalPos;
    _edgeScrollCtrl = ctrl;
    _startEdgeScrollTimer();
  }

  /// 長押しドラッグ中：位置とスナップ更新
  void _onLongPressNodeMove(Offset globalPos, TransformationController ctrl) {
    if (_moveModeNodeId == null || _moveDragAnchor == null) return;
    final canvasPos = _globalToCanvas(globalPos, ctrl);
    final newPos = canvasPos - _moveDragAnchor!;
    final clampedPos = Offset(
      newPos.dx.clamp(0.0, 20000.0),
      newPos.dy.clamp(0.0, 20000.0),
    );
    final provider = context.read<MindMapProvider>();
    // ギャラリーはブロックを繋げないので、 接続/兄弟スナップのガイドは出さない。
    final bool isShelf = provider.currentPage.pageType == 'bookshelf';
    final snap = isShelf
        ? null
        : _detectAnchorSnap(clampedPos, _moveModeNodeId!, provider);

    // 兄弟スナップ検出（アンカースナップがない場合のみ）
    String? sibParent;
    Offset? sibPos;
    if (snap == null && !isShelf) {
      final sibResult =
          _detectSiblingSnap(clampedPos, _moveModeNodeId!, provider);
      sibParent = sibResult?.$1;
      sibPos = sibResult?.$2;
    }

    // ギャラリー: 現在の位置で入れ替わる先の要素を求めて枠を強調する
    //   (= ユーザー要望)。 ドロップ時 (snapNodeToShelfCell) と同じ座標
    //   (= ノード左上 = clampedPos) を渡し、 ハイライト先と実際の入れ替え先を
    //   一致させる。
    final String? swapTarget = isShelf
        ? provider.shelfSwapTargetAt(_moveModeNodeId!, clampedPos)
        : null;

    setState(() {
      _movingPos = sibPos ?? clampedPos;
      _currentSnap = snap;
      _siblingGuideParentId = sibParent;
      _siblingGuidePos = sibPos;
      _shelfSwapTargetId = swapTarget;
    });

    // 画面端に近づいたらビューポートを自動スクロール
    _autoScrollIfNeeded(globalPos, ctrl);
  }

  /// カーソル位置を更新（onPanUpdateから呼ばれる）
  void _autoScrollIfNeeded(Offset globalPos, TransformationController ctrl) {
    _lastDragGlobalPos = globalPos;
    _edgeScrollCtrl = ctrl;
    _startEdgeScrollTimer();
  }

  /// オートスクロール時の「マップが実際に見えている画面領域」 を返す。
  ///
  /// ユーザー要望「表示領域外に出た時に画面を追跡する機能が備わっているが、
  ///   画面分割をした際には画面分割で表示されていないマップ領域は画面外と
  ///   見なして追跡するようにして欲しい」 への対応で導入。
  ///
  /// 計算ロジック:
  ///   - 画面全体 (= `MediaQuery.size`) から始めて、
  ///   - **右パネル** (`_splitOpen` + `_splitPosition.right`) があれば右端を縮める
  ///   - **左パネル** (`_splitOpen` + `_splitPosition.left`) があれば左端を縮める
  ///   - **上パネル** (`_splitPosition.top`) があれば上端を縮める
  ///   - **下パネル** (`_splitPosition.bottom`) があれば下端を縮める
  ///   - **左サイドパネル** (`_splitLeftOpen`、 これは右パネルと独立な追加分割) も左端を縮める
  ///
  /// 戻り値はピクセル単位の矩形 (= MediaQuery 座標系)。 `_performEdgeScroll`
  /// 内で `pos.dx < visible.left + margin` 等の判定に使う。
  Rect _visibleMapRectForAutoScroll(BuildContext context) {
    final size = MediaQuery.of(context).size;
    double left = 0;
    double right = size.width;
    double top = 0;
    double bottom = size.height;
    // splitter (= リサイズハンドル) の幅。 厳密に取得するのは複雑なので、
    // 経験的に 8px 程度を確保。 これより小さく見積もると、 ノードが
    // ハンドルの裏に隠れる時にスクロールが発火しない。
    const double splitterWidth = 8.0;
    // ── 右パネル / 左パネル / 上パネル / 下パネル (_splitPosition で 1 方向) ──
    if (_splitOpen) {
      final eff = _splitPanelEffectiveSize(context);
      switch (_splitPosition) {
        case _SplitPosition.right:
          right = (size.width - eff - splitterWidth).clamp(0.0, size.width);
          break;
        case _SplitPosition.left:
          left = (eff + splitterWidth).clamp(0.0, size.width);
          break;
        case _SplitPosition.top:
          top = (eff + splitterWidth).clamp(0.0, size.height);
          break;
        case _SplitPosition.bottom:
          bottom = (size.height - eff - splitterWidth).clamp(0.0, size.height);
          break;
      }
    }
    // ── 左サイドパネル (= _splitLeftOpen、 上のメインパネルとは独立) ──
    // 左に追加で固定パネルが開いている場合は、 さらにマップ領域の左端が縮む。
    if (_splitLeftOpen) {
      final leftEff = _splitLeftPanelWidth
          .clamp(size.width * 0.20, size.width * 0.90)
          .toDouble();
      final newLeft = (leftEff + splitterWidth).clamp(0.0, size.width);
      if (newLeft > left) left = newLeft;
    }
    // ── マップの画面分割 (2/4 分割) 中は、 編集キャンバスが入っている
    //    セルの矩形まで狭める (= ユーザー要望: 分割画面の境界の段階で
    //    画面追跡されるように。 旧: 画面全体の端まで持って行かないと
    //    追跡が始まらなかった)。 ──
    final providerForSplit = context.read<MindMapProvider>();
    if (_mapSplitOpen && _splitEligiblePage(providerForSplit.currentPage)) {
      final cell = _splitCellGlobalRect(_mapSplitEditorSlot);
      left = math.max(left, cell.left);
      top = math.max(top, cell.top);
      right = math.min(right, cell.right);
      bottom = math.min(bottom, cell.bottom);
    }
    // ── 安全クランプ: left < right、 top < bottom を保証 ──
    // 万一パネル幅の合計が画面を超えるような異常な状態でも、 矩形が反転して
    // 妙な挙動になるのを防ぐ (= 最低 50px 確保)。
    if (right - left < 50) right = (left + 50).clamp(0.0, size.width);
    if (bottom - top < 50) bottom = (top + 50).clamp(0.0, size.height);
    return Rect.fromLTRB(left, top, right, bottom);
  }

  /// エッジスクロールタイマーを開始
  void _startEdgeScrollTimer() {
    if (_edgeScrollTimer != null && _edgeScrollTimer!.isActive) return;
    _edgeScrollTimer = Timer.periodic(
      const Duration(milliseconds: 16),
      (_) => _performEdgeScroll(),
    );
  }

  /// タイマーで呼ばれる：カーソル位置に基づいてスクロール
  void _performEdgeScroll() {
    final pos = _lastDragGlobalPos;
    final ctrl = _edgeScrollCtrl;
    if (pos == null || ctrl == null) {
      _stopEdgeScroll();
      return;
    }
    // ドラッグが終了していたら停止。範囲選択を「描いている」途中も追尾対象とする
    // (= 矩形ラバーバンドが画面端に達したらキャンバスをスクロールしてさらに広げられる)。
    //
    // 範囲選択には 2 経路があり、 どちらも追尾対象にする:
    //   (a) PC 長押しドラッグ経路: `_canvasLongPressActive` = true
    //   (b) カスタムボタン経路 (= isRangeMode を ON にしてから GestureDetector
    //       で onPanStart → onPanUpdate): `_canvasLongPressActive` は false
    // 旧実装は (a) しか想定していなかったため、 カスタムボタンから入った
    // 範囲選択でカーソルが画面端に達してもキャンバスがスクロールせず、
    // それ以上矩形が伸ばせない問題があった。
    // → `_canvasLongPressActive` を外して `_rangeSelectMode + _rangeStart`
    //   が立っていれば両経路を同等に扱う。
    final isDrawingRangeSelect =
        _rangeSelectMode && _rangeStart != null && !_rangeDragging;
    if (!_rangeDragging &&
        _moveModeNodeId == null &&
        !isDrawingRangeSelect &&
        !_shelfHandleDragging &&
        // 図形の移動ドラッグ中も追尾対象 (= ユーザー要望)。
        !_draggingDecoration) {
      _stopEdgeScroll();
      return;
    }

    // ── 画面分割を考慮した「マップが実際に見えている領域」 を計算 ──
    // ユーザー要望「表示領域外に出た時に画面を追跡する機能が備わっているが、
    //   画面分割をした際には画面分割で表示されていないマップ領域は画面外と
    //   見なして追跡するようにして欲しい」 への対応。
    //
    // 旧仕様: 画面全体 (MediaQuery.size) の端を判定基準にしていたので、
    //   分割パネル (= 右に Web/PDF、 左に Web/PDF、 上下分割) の裏に
    //   ノードがドラッグされても「画面外」 とは判定されず、 オートスクロール
    //   が走らなかった。 結果としてユーザーが見えない位置でノードが
    //   止まってしまう。
    // 新仕様: 分割パネルの幅 (= `_splitPanelEffectiveSize` / 左パネル相当)
    //   を引いた「実際にマップが見えている矩形」 を計算し、 その矩形の端を
    //   margin の判定に使う。 これでパネルの裏に行こうとした瞬間にスクロール
    //   が発火し、 ノードが常に視野内に留まる。
    final mq = MediaQuery.of(context);
    final screenW = mq.size.width;
    final screenH = mq.size.height;
    final visible = _visibleMapRectForAutoScroll(context);
    // モバイルは指でエッジが見えにくいのでマージン・速度を拡大
    final double margin = _isDesktop ? 50.0 : 80.0;
    final double speed = _isDesktop ? 10.0 : 16.0;

    // ── 判定に使う端の座標 (= ユーザー要望) ──
    // ノード移動中は「カーソル位置」 ではなく「動かしているノードの外接矩形の
    //   端 (先端)」 が画面外に出ようとした時点で追跡する。 範囲選択など、 対象
    //   ノードが無い場合は従来通りカーソル位置を使う。
    double leftEdge = pos.dx;
    double rightEdge = pos.dx;
    double topEdge = pos.dy;
    double bottomEdge = pos.dy;
    if (_moveModeNodeId != null && _movingPos != null) {
      final node = context.read<MindMapProvider>().nodes[_moveModeNodeId!];
      if (node != null) {
        final scale = ctrl.value.getMaxScaleOnAxis();
        final tl = _canvasToGlobal(_movingPos!, ctrl);
        final w = node.width * scale;
        final h = node.visualHeight * scale;
        // ── 巨大ノード対策 (= ユーザー要望: 縦が極端に長くて画面外に出る大きさの
        //    ノードが、 ドラッグしていないのに勝手に画面外へ追跡されるバグ修正) ──
        // ノードがビューポートより大きい軸では、 外接矩形の端が常に画面外に
        //   あるため「端で判定」 だと auto-scroll が止まらず暴走 (タイマー駆動の
        //   ため指が止まっていても延々スクロール) する。 その軸だけはノード端で
        //   なくカーソル位置で判定する (= 端が視野に収まる軸のみノード端で追跡)。
        if (w <= visible.width - 2 * margin) {
          leftEdge = tl.dx;
          rightEdge = tl.dx + w;
        }
        if (h <= visible.height - 2 * margin) {
          topEdge = tl.dy;
          bottomEdge = tl.dy + h;
        }
      }
    }

    double dx = 0;
    double dy = 0;

    // 左端: ノード(またはカーソル)の左端が visible.left に近づいたら
    if (leftEdge < visible.left + margin) {
      dx = speed * ((visible.left + margin - leftEdge) / margin);
    } else if (rightEdge > visible.right - margin) {
      // 右端: ノードの右端が visible.right に近づいたら
      dx = -speed * ((rightEdge - (visible.right - margin)) / margin);
    }
    // 上端 / 下端も同様にノードの上端 / 下端で判定
    if (topEdge < visible.top + margin) {
      dy = speed * ((visible.top + margin - topEdge) / margin);
    } else if (bottomEdge > visible.bottom - margin) {
      dy = -speed * ((bottomEdge - (visible.bottom - margin)) / margin);
    }
    // 旧仕様の保険: ポインタが完全に画面外 (= screen の物理端の外側) に
    // 出ても visible.right < pos.dx などで dx は既に負方向に効くので追加処理
    // は不要。 ただし screen 幅 / 高さは未使用警告を避けるため変数として使う。
    // (= 静的解析が「未使用」 と警告しないよう、 ここで参照を残す)
    assert(screenW > 0 && screenH > 0);

    // ── ギャラリーの行/列ハンドルのドラッグは掴んだ軸方向だけ追従 ──
    // 行=縦のみ / 列=横のみ。 そうしないと、 左端の行ハンドル付近にカーソルが
    //   あるだけで横スクロールが暴発する (= 行は左端の縦帯を縦にドラッグする)。
    if (_shelfRowDragFrom != null) dx = 0;
    if (_shelfColDragFrom != null) dy = 0;

    if (dx == 0 && dy == 0) return;

    final current = ctrl.value.clone();
    current.translate(dx, dy);
    ctrl.value = current;
    _lastMatrix = ctrl.value.clone();

    // 範囲ドラッグ中はdeltaも更新（ビューがスクロールした分ノードも追従）
    if (_rangeDragging && _rangeDragAnchor != null) {
      final scale = ctrl.value.getMaxScaleOnAxis();
      setState(() {
        _rangeDragDelta = Offset(
          _rangeDragDelta.dx - dx / scale,
          _rangeDragDelta.dy - dy / scale,
        );
      });
    } else if (_moveModeNodeId != null && _movingPos != null) {
      final scale = ctrl.value.getMaxScaleOnAxis();
      setState(() {
        _movingPos = Offset(
          _movingPos!.dx - dx / scale,
          _movingPos!.dy - dy / scale,
        );
      });
    } else if (isDrawingRangeSelect) {
      // 範囲選択を描画中: カーソルが画面端で止まっていても矩形が伸び続けるよう、
      // canvas 上の対応点を再計算して _rangeEnd を更新する。
      // (onPointerMove が来ない=指/カーソルが動かない状態でも、
      //  キャンバスがスクロールすれば「カーソルの canvas 座標」は動いている)
      setState(() {
        _rangeEnd = _globalToCanvas(pos, ctrl);
      });
    } else if (_shelfRowDragFrom != null || _shelfColDragFrom != null) {
      // ギャラリーの行/列ハンドルのドラッグ中にビューがスクロールしたら、
      //   静止しているカーソルのキャンバス座標を取り直す (= ドロップ先
      //   ハイライトがカーソルに追従し続ける)。 実位置ベースなので旧実装の
      //   ような累積補正 (二重計上の温床) は不要。
      setState(() {
        _shelfHandlePointerCanvas = _globalToCanvas(pos, ctrl);
      });
    } else if (_draggingDecoration &&
        _decoDragFollowsScroll &&
        _selectedDecorationId != null) {
      // 図形の移動ドラッグ中: ビューがスクロールした分だけ図形も動かして、
      // カーソルの下に図形が残り続けるようにする (= ノードと同じ挙動)。
      final scale = ctrl.value.getMaxScaleOnAxis();
      if (scale > 0) {
        final d = Offset(-dx / scale, -dy / scale);
        context.read<MindMapProvider>().dragDecorationBy(
            _selectedDecorationId!,
            startDelta: d,
            endDelta: d);
      }
    }
  }

  /// 自動スクロールタイマー停止
  void _stopEdgeScroll() {
    _edgeScrollTimer?.cancel();
    _edgeScrollTimer = null;
    _lastDragGlobalPos = null;
    _edgeScrollCtrl = null;
  }

  /// ノードドロップ位置 [pos] (= ノードの左上座標) に重なる PDF/URL 系
  /// ノードの ID を返す。 メモ追加用のドロップ判定に使う。
  ///
  /// - PDF系: attachmentPath が `.pdf` で終わるノード
  /// - URL系: linkUrl が空でないノード
  /// 子持ちの PDF/URL ノードにノードがドロップされた時に、 ユーザーに
  /// 「格納 (= メモにする) するか、 子として接続するか、 キャンセルか」 を
  /// 確認する (= ユーザー要望: 子要素を格納した状態の親ノードと接続する時は、
  /// 格納先に含めるか確認が出てくるように)。
  void _confirmDropOnPopulatedParent(
      MindMapProvider provider, String targetNodeId, String sourceNodeId) {
    final target = provider.nodes[targetNodeId];
    final source = provider.nodes[sourceNodeId];
    if (target == null || source == null) return;
    final untitled = provider.t('common.untitledParen');
    final targetTitle = target.title.isEmpty ? untitled : target.title;
    final sourceTitle = source.title.isEmpty ? untitled : source.title;
    showDialog<int>(
      context: context,
      builder: (dctx) {
        final node = FocusNode(debugLabel: 'ConfirmDropOnPopulatedParent');
        WidgetsBinding.instance.addPostFrameCallback((_) {
          node.requestFocus();
        });
        return Focus(
          focusNode: node,
          onKeyEvent: (_, event) {
            if (event is! KeyDownEvent) return KeyEventResult.ignored;
            if (event.logicalKey == LogicalKeyboardKey.enter ||
                event.logicalKey == LogicalKeyboardKey.numpadEnter) {
              Navigator.pop(dctx, 1); // デフォルト=格納
              return KeyEventResult.handled;
            }
            if (event.logicalKey == LogicalKeyboardKey.escape) {
              Navigator.pop(dctx, 0);
              return KeyEventResult.handled;
            }
            return KeyEventResult.ignored;
          },
          child: AlertDialog(
            backgroundColor: const Color(0xFF1E1E32),
            title: Text(
                context
                    .read<MindMapProvider>()
                    .t('container.storeConfirm')
                    .replaceFirst('{title}', targetTitle),
                style: const TextStyle(color: Colors.white)),
            content: Text(
                provider
                    .t('store.dropChoices')
                    .replaceAll('{src}', sourceTitle)
                    .replaceAll('{tgt}', targetTitle),
                style: const TextStyle(color: Colors.white70, fontSize: 13)),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dctx, 0),
                child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                    style: TextStyle(color: Colors.white60)),
              ),
              TextButton(
                onPressed: () => Navigator.pop(dctx, 2),
                child: Text(
                    context.read<MindMapProvider>().t('container.connectChild'),
                    style: TextStyle(color: Color(0xFF6C63FF))),
              ),
              ElevatedButton(
                autofocus: true,
                style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF43B97F),
                    foregroundColor: Colors.white,),
                onPressed: () => Navigator.pop(dctx, 1),
                child: Text(
                    context.read<MindMapProvider>().t('container.store'),
                    style: TextStyle(color: Colors.white)),
              ),
            ],
          ),
        );
      },
    ).then((choice) {
      if (!mounted) return;
      if (choice == 1) {
        // 格納 (= メモ化 + 元ノード削除)
        final memo = provider.addPdfMemoFromDroppedNode(
          targetNodeId: targetNodeId,
          sourceNodeId: sourceNodeId,
        );
        if (memo != null) {
          provider.deleteNode(sourceNodeId);
          if (mounted) {
            _appSnack(
                context,
                SnackBar(
                  content: Text(provider.t('pdfMemo.droppedFromNode')),
                  duration: const Duration(seconds: 1),
                  backgroundColor: const Color(0xFF2A2A3E),
                ));
          }
        }
      } else if (choice == 2) {
        // 子として接続 (= 兄弟ノードとして親-子接続を追加)
        provider.connectNodes(targetNodeId, sourceNodeId, AnchorDirection.east,
            AnchorDirection.west);
      }
      // choice == 0 (キャンセル) は何もしない
    });
  }

  /// - 自分自身は除外
  ///
  /// 重なり判定は「ドラッグ中ノードの中心 × 候補ノードの矩形に内包」 で行う。
  /// (= ノードの大部分がドロップ先に乗っていれば成立)
  String? _findDropTargetForMemo(
      Offset pos, String sourceId, MindMapProvider provider) {
    final source = provider.nodes[sourceId];
    if (source == null) return null;
    // ドラッグ中ノードの中心座標
    final center = pos + Offset(source.width / 2, source.height / 2);
    for (final entry in provider.nodes.entries) {
      final id = entry.key;
      if (id == sourceId) continue;
      final n = entry.value;
      final isPdf = (n.attachmentPath ?? '').toLowerCase().endsWith('.pdf');
      final isUrl = (n.linkUrl ?? '').isNotEmpty;
      if (!isPdf && !isUrl) continue;
      final rect =
          Rect.fromLTWH(n.position.dx, n.position.dy, n.width, n.height);
      if (rect.contains(center)) {
        return id;
      }
    }
    return null;
  }

  /// 長押しドラッグ終了：ノード位置確定・接続処理
  void _onLongPressNodeEnd() {
    _stopEdgeScroll();
    final nodeId = _moveModeNodeId;
    final pos = _movingPos;
    final snap = _currentSnap;
    final sibParent = _siblingGuideParentId;
    final sibPos = _siblingGuidePos;
    // 付箋グループのお仲間 (= ユーザー要望: まとめて動かす) と移動量。
    final mates = Set<String>.of(_groupDragIds);
    final groupStart = _groupDragStartPos;
    setState(() {
      _moveModeNodeId = null;
      _movingPos = null;
      _currentSnap = null;
      _moveDragAnchor = null;
      _movingPointerId = null;
      _siblingGuideParentId = null;
      _siblingGuidePos = null;
      _shelfSwapTargetId = null;
      _groupDragIds.clear();
      _groupDragStartPos = null;
    });
    if (nodeId == null) return;
    final provider = context.read<MindMapProvider>();
    // ── お仲間を同じ量だけ動かす (掴んだノード自身は、 この後の
    //    通常処理 (吸着 / 押しのけ) でそのまま置かれる) ──
    if (mates.isNotEmpty && pos != null && groupStart != null) {
      final d = pos - groupStart;
      if (d.dx.abs() > 0.5 || d.dy.abs() > 0.5) {
        provider.moveNodes(mates, d);
      }
    }

    // ── ギャラリー: ブロック同士は繋げず、 ドロップ位置を最寄りのグリッドセルへ
    //    スナップする (= ユーザー要望: リンク不可 / 配置は候補区画のみ) ──
    if (provider.currentPage.pageType == 'bookshelf') {
      if (pos != null) provider.snapNodeToShelfCell(nodeId, pos);
      return;
    }

    // ── ドロップ先が PDF/URL ノードならメモとして追加 + ソース削除 ──
    // (= ユーザー要望: 「ノードを PDF/URL ノードにドラッグ&ドロップで
    //  メモが追加される」)
    // スナップ中・兄弟ガイド中・付箋エリア中はそちらの操作を優先する。
    if (snap == null && sibParent == null && pos != null) {
      final dropTargetId = _findDropTargetForMemo(pos, nodeId, provider);
      if (dropTargetId != null) {
        final targetHasChildren =
            provider.connections.any((c) => c.fromId == dropTargetId);
        if (!targetHasChildren) {
          // 子なしの PDF/URL ノードへのドロップは従来通り即メモ化。
          final memo = provider.addPdfMemoFromDroppedNode(
            targetNodeId: dropTargetId,
            sourceNodeId: nodeId,
          );
          if (memo != null) {
            provider.deleteNode(nodeId);
            if (mounted) {
              _appSnack(
                  context,
                  SnackBar(
                    content: Text(provider.t('pdfMemo.droppedFromNode')),
                    duration: const Duration(seconds: 1),
                    backgroundColor: const Color(0xFF2A2A3E),
                  ));
            }
          }
          return;
        }
        // ── 子持ち親ノードへのドロップは確認ダイアログを出す (= ユーザー要望:
        //    子要素を格納した状態の親ノードと接続する時は、 格納先に含めるか
        //    確認が出てくるように) ──
        // 「格納 (= メモにする)」 「子として接続」 「キャンセル」 の 3 択。
        _confirmDropOnPopulatedParent(provider, dropTargetId, nodeId);
        return;
      }
    }

    if (snap != null) {
      // 既存ノード（snap.nodeId）= 親, ドラッグノード = 子
      provider.connectNodes(
          snap.nodeId, nodeId, snap.toAnchor, snap.fromAnchor);
      if (pos != null) {
        final adjusted =
            _ensureSpacing(nodeId, snap.nodeId, snap.fromAnchor, pos, provider);
        provider.updateNodePosition(nodeId, adjusted);
        provider.pushSurroundingNodes(nodeId);
      }
    } else if (sibParent != null && sibPos != null) {
      // 兄弟スナップ：親ノードに子として接続
      final parent = provider.nodes[sibParent];
      if (parent != null) {
        provider.connectNodes(
            sibParent, nodeId, AnchorDirection.east, AnchorDirection.west);
        provider.updateNodePosition(nodeId, sibPos);
        provider.pushSurroundingNodes(nodeId);
      }
    } else if (pos != null) {
      provider.updateNodePosition(nodeId, pos);
      provider.pushSurroundingNodes(nodeId);
    }

    // ── ドロップ後、付箋エリアに入ったかチェック ──
    if (pos != null && provider.namedGroups.isNotEmpty) {
      final dropNode = provider.nodes[nodeId];
      if (dropNode != null) {
        _checkDropIntoGroup(nodeId, dropNode, provider);
        _checkDraggedOutOfGroup(nodeId, dropNode, provider);
      }
    }
  }

  /// ノードが所属グループの外にドロップされた時解除確認を表示
  void _checkDraggedOutOfGroup(
      String nodeId, MindMapNode droppedNode, MindMapProvider provider) {
    const pad = 14.0;
    const labelH = 26.0;
    final bounds = _GroupBackgroundPainter.computeBounds(
        provider.namedGroups,
        provider.nodes,
        _groupColorOverrides(provider),
        _groupFontSizeOverrides(provider),
        _groupFontFamilyOverrides(provider),
        _groupPaddingOverrides(provider));

    for (final b in bounds) {
      // このグループのメンバーでない場合はスキップ
      if (!b.nodeIds.contains(nodeId)) continue;

      final groupRect = Rect.fromLTRB(
        b.minX - pad,
        b.minY - pad - labelH,
        b.maxX + pad,
        b.maxY + pad,
      );
      final nodeCenterX = droppedNode.position.dx + droppedNode.width / 2;
      final nodeCenterY =
          droppedNode.position.dy + droppedNode.visualHeight / 2;

      // グループ外にドロップされた場合
      if (!groupRect.contains(Offset(nodeCenterX, nodeCenterY))) {
        final groupName = b.name;
        final displayName =
            groupName.isEmpty ? provider.t('groupList.unnamed') : groupName;

        showDialog(
          context: context,
          barrierColor: Colors.black38,
          builder: (dctx) => AlertDialog(
            backgroundColor: const Color(0xFF2A2A3E),
            shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(16),
                side:
                    BorderSide(color: Colors.redAccent.withValues(alpha: 0.4))),
            title: Row(children: [
              const Icon(Icons.label_off_rounded,
                  color: Colors.redAccent, size: 20),
              const SizedBox(width: 8),
              Expanded(
                child: Text(provider.t('groupDrop.outTitle'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 15,
                        fontWeight: FontWeight.bold)),
              ),
            ]),
            content: Text(
              provider.t('groupDrop.outBody').replaceAll('{name}', displayName),
              style: const TextStyle(color: Colors.white70, fontSize: 13),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dctx),
                child: Text(provider.t('node.cancel'),
                    style: const TextStyle(color: Colors.white54)),
              ),
              ElevatedButton.icon(
                onPressed: () {
                  Navigator.pop(dctx);
                  final updatedIds = Set<String>.of(b.nodeIds)..remove(nodeId);
                  if (updatedIds.isEmpty) {
                    provider.removeNamedGroup(groupName);
                  } else {
                    provider.setNamedGroup(groupName, updatedIds);
                  }
                },
                icon: const Icon(Icons.label_off_rounded, size: 16),
                label: Text(provider.t('groupDrop.outConfirm')),
                style:
                    ElevatedButton.styleFrom(
                      backgroundColor: Colors.redAccent,
                      // 暗いテーマだと既定の文字色が濃くて読めない
                      // (= ユーザー報告: 「全て削除」 の文字が読めない)。,
                      foregroundColor: Colors.white),
              ),
            ],
          ),
        );
        break; // 最初に見つかったグループのみ
      }
    }
  }

  /// ノードが付箋エリア内にドロップされた場合に参加確認を表示
  void _checkDropIntoGroup(
      String nodeId, MindMapNode droppedNode, MindMapProvider provider) {
    const pad = 14.0;
    const labelH = 26.0;
    final bounds = _GroupBackgroundPainter.computeBounds(
        provider.namedGroups,
        provider.nodes,
        _groupColorOverrides(provider),
        _groupFontSizeOverrides(provider),
        _groupFontFamilyOverrides(provider),
        _groupPaddingOverrides(provider));

    for (final b in bounds) {
      // すでにそのグループのメンバーなら何もしない
      if (b.nodeIds.contains(nodeId)) continue;

      final groupRect = Rect.fromLTRB(
        b.minX - pad,
        b.minY - pad - labelH,
        b.maxX + pad,
        b.maxY + pad,
      );
      final nodeCenterX = droppedNode.position.dx + droppedNode.width / 2;
      final nodeCenterY =
          droppedNode.position.dy + droppedNode.visualHeight / 2;

      if (groupRect.contains(Offset(nodeCenterX, nodeCenterY))) {
        final groupName = b.name;
        final displayName =
            groupName.isEmpty ? provider.t('groupList.unnamed') : groupName;

        showDialog(
          context: context,
          barrierColor: Colors.black38,
          builder: (dctx) => AlertDialog(
            backgroundColor: const Color(0xFF2A2A3E),
            shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(16),
                side: BorderSide(
                    color: const Color(0xFFFFB347).withValues(alpha: 0.5))),
            title: Row(children: [
              const Icon(Icons.label_rounded,
                  color: Color(0xFFFFB347), size: 20),
              const SizedBox(width: 8),
              Expanded(
                child: Text(provider.t('groupDrop.inTitle'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 15,
                        fontWeight: FontWeight.bold)),
              ),
            ]),
            content: Text(
              provider.t('groupDrop.inBody').replaceAll('{name}', displayName),
              style: const TextStyle(color: Colors.white70, fontSize: 13),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dctx),
                child: Text(provider.t('node.cancel'),
                    style: const TextStyle(color: Colors.white54)),
              ),
              ElevatedButton.icon(
                onPressed: () {
                  Navigator.pop(dctx);
                  final updatedIds = Set<String>.of(b.nodeIds)..add(nodeId);
                  provider.setNamedGroup(groupName, updatedIds);
                },
                icon: const Icon(Icons.add_rounded, size: 16),
                label: Text(provider.t('groupDrop.inConfirm')),
                style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFFFFB347),
                    foregroundColor: Color(0xFF10241F),),
              ),
            ],
          ),
        );
        break; // 最初に見つかったグループのみ
      }
    }
  }

  // ─── moveMode 専用ポインターハンドラ（外部タップによるキャンセル用） ────────

  void _onMoveModePointerDown(PointerDownEvent e, TransformationController ctrl,
      MindMapProvider provider) {
    // ムーブモード中に別の指でタップされたらリセット
    if (_moveModeNodeId != null &&
        _movingPointerId != null &&
        _movingPointerId != e.pointer) {
      _resetInteractionState();
    }
  }

  void _onMoveModePointerMove(
      PointerMoveEvent e, TransformationController ctrl) {
    // onLongPressMoveUpdate で処理するため不要
  }

  void _onMoveModePointerUp(PointerUpEvent e) {
    // onLongPressEnd で処理するため不要
  }

  void _onMoveModePointerCancel(PointerCancelEvent e) {
    // onLongPressEnd で処理するため不要
  }

  // ─── 4方向アンカーのスナップ判定 ────────────────────────────────────────

  SnapTarget? _detectAnchorSnap(
      Offset draggedPos, String draggedId, MindMapProvider provider) {
    final nodes = provider.nodes;
    final me = nodes[draggedId];
    if (me == null) return null;
    // 折りたたみ (collapsed) で隠れている子孫ノードはスナップ候補に出さない。
    // (= 「配置候補に置くとノードが消えてしまう」 バグの修正: 非表示ノードへ
    //   接続すると、 繋いだノードも折りたたみ配下に入って画面から消えるため)。
    final hidden = provider.hiddenNodeIds;

    // ドラッグ中のノードの仮アンカー位置を計算
    final myNode = me.copyWith(position: draggedPos);

    SnapTarget? best;
    double bestDist = _kAnchorSnapDist;

    for (final other in nodes.values) {
      if (other.id == draggedId) continue;
      // 格納ノードに隠されているメンバーはスナップ候補に出さない。
      // (= 格納したはずの子ノード由来の配置候補が残り、 そこへドロップすると
      //   コンテナの中に吸い込まれてしまう問題への対策 / ユーザー要望)。
      if (other.hiddenInContainer != null) continue;
      if (hidden.contains(other.id)) continue;

      // ノードのanchorModeで許可された方向のみチェック
      final myDirs = anchorsForMode(myNode.anchorMode);
      for (final myDir in myDirs) {
        final myAnchor = myNode.anchorPoint(myDir);
        final otherDirs = anchorsForMode(other.anchorMode);
        for (final otherDir in otherDirs) {
          final otherAnchor = other.anchorPoint(otherDir);
          final dist = (myAnchor - otherAnchor).distance;
          if (dist < _kAnchorSnapDist && dist < bestDist) {
            bestDist = dist;
            best = SnapTarget(
              nodeId: other.id,
              fromAnchor: myDir,
              toAnchor: otherDir,
            );
          }
        }
      }
    }
    return best;
  }

  /// 範囲（複数選択）ドラッグ中のスナップ検出。
  ///
  /// 選択中のノード群 (= [selectedIds]) を [delta] だけ平行移動した仮想位置
  /// で、選択範囲外のノードに対して最も近いアンカーペアを返す。
  /// 戻り値の [SnapTarget.sourceNodeId] には「最も近接した選択ノード ID」が
  /// 入り、[nodeId] には「ターゲット (選択範囲外) のノード ID」が入る。
  ///
  /// 範囲ドラッグ完了時はこの結果に基づいて
  /// `provider.moveAndConnectToTarget(...)` を呼び、選択ノードすべてを
  /// ターゲットの「子」として一括接続する。
  SnapTarget? _detectAnchorSnapForRange(
      Set<String> selectedIds, Offset delta, MindMapProvider provider) {
    if (selectedIds.isEmpty) return null;
    final nodes = provider.nodes;
    // 折りたたみで隠れている子孫はスナップ候補に出さない (= 消失バグ対策)。
    final hidden = provider.hiddenNodeIds;

    SnapTarget? best;
    double bestDist = _kAnchorSnapDist;

    for (final srcId in selectedIds) {
      final src = nodes[srcId];
      if (src == null) continue;
      // 仮想位置 (delta 適用後) のノード
      final srcMoved = src.copyWith(
        position: Offset(
          src.position.dx + delta.dx,
          src.position.dy + delta.dy,
        ),
      );
      final myDirs = anchorsForMode(srcMoved.anchorMode);

      for (final other in nodes.values) {
        if (selectedIds.contains(other.id)) continue; // 範囲内同士は除外
        // 格納ノードに隠されているメンバーはスナップ候補に出さない。
        if (other.hiddenInContainer != null) continue;
        if (hidden.contains(other.id)) continue;
        final otherDirs = anchorsForMode(other.anchorMode);
        for (final myDir in myDirs) {
          final myAnchor = srcMoved.anchorPoint(myDir);
          for (final otherDir in otherDirs) {
            final otherAnchor = other.anchorPoint(otherDir);
            final dist = (myAnchor - otherAnchor).distance;
            if (dist < _kAnchorSnapDist && dist < bestDist) {
              bestDist = dist;
              best = SnapTarget(
                nodeId: other.id,
                fromAnchor: myDir,
                toAnchor: otherDir,
                sourceNodeId: srcId,
              );
            }
          }
        }
      }
    }
    return best;
  }

  // ─── 兄弟スナップ検出 ──────────────────────────────────────────────────────
  /// 既存の子ノードと平行に並んだ場合に、同じ親の子ノードとしてスナップ
  /// 戻り値: (parentId, snapPosition) or null
  (String, Offset)? _detectSiblingSnap(
      Offset draggedPos, String draggedId, MindMapProvider provider) {
    // 配置候補（スナップ）が無効ならスナップしない
    if (!provider.snapEnabled) return null;

    final nodes = provider.nodes;
    final conns = provider.connections;
    final me = nodes[draggedId];
    if (me == null) return null;
    // 折りたたみで隠れている親子はスナップ候補に出さない (= 消失バグ対策)。
    final hidden = provider.hiddenNodeIds;

    const double alignThreshold = 30.0; // 平行判定の許容範囲(px)
    const double siblingGap = 20.0; // 兄弟ノード間のギャップ

    // 全接続を走査し、既存の子ノードと平行かチェック
    for (final conn in conns) {
      final child = nodes[conn.toId];
      final parent = nodes[conn.fromId];
      if (child == null || parent == null) continue;
      if (child.id == draggedId || parent.id == draggedId) continue;
      // 格納ノードに隠されている親子はスナップ候補に出さない。
      if (child.hiddenInContainer != null || parent.hiddenInContainer != null) {
        continue;
      }
      if (hidden.contains(child.id) || hidden.contains(parent.id)) continue;

      // 子ノードのX座標と近いか（縦方向で平行に並んでいるか）
      final dx = (draggedPos.dx - child.position.dx).abs();
      if (dx < alignThreshold) {
        // 近い → 子ノードの上か下にスナップ位置を提案
        // 当たり判定はタイトル本体 (height) で行う。 visualHeight を使うと
        // 動画/画像で伸びた分だけ離され、 大きいノード同士が近づけない
        // (= ユーザー報告のバグ)。 _avoidOverlap 等と同じく height に統一。
        final myCenter = draggedPos.dy + me.height / 2;
        final childCenter = child.position.dy + child.height / 2;

        Offset snapPos;
        if (myCenter < childCenter) {
          // 上にスナップ（ドラッグノードの height 分上に）
          snapPos = Offset(
              child.position.dx, child.position.dy - me.height - siblingGap);
        } else {
          // 下にスナップ（子ノードの height 分下に）
          snapPos = Offset(
              child.position.dx, child.position.dy + child.height + siblingGap);
        }

        // 距離が近ければスナップ
        final dist = (draggedPos - snapPos).distance;
        if (dist < 60.0) {
          return (conn.fromId, snapPos);
        }
      }

      // 子ノードのY座標と近いか（横方向で平行に並んでいるか）
      final dy = (draggedPos.dy - child.position.dy).abs();
      if (dy < alignThreshold) {
        final myCenter = draggedPos.dx + me.width / 2;
        final childCenter = child.position.dx + child.width / 2;

        Offset snapPos;
        if (myCenter < childCenter) {
          snapPos = Offset(
              child.position.dx - me.width - siblingGap, child.position.dy);
        } else {
          snapPos = Offset(
              child.position.dx + child.width + siblingGap, child.position.dy);
        }

        final dist = (draggedPos - snapPos).distance;
        if (dist < 60.0) {
          return (conn.fromId, snapPos);
        }
      }
    }
    return null;
  }

  // ─── 接続時にノード間の距離確保 ──────────────────────────────────────────

  Offset _ensureSpacing(
      String draggedId,
      String targetId,
      AnchorDirection draggedAnchor,
      Offset currentPos,
      MindMapProvider provider) {
    final target = provider.nodes[targetId];
    final dragged = provider.nodes[draggedId];
    if (target == null || dragged == null) return currentPos;

    const double minGap = 60.0;
    // 当たり判定はタイトル本体 (height) で行う。 visualHeight を使うと動画/画像
    // で伸びた分だけ離され、 大きいノード同士が近づけない (= ユーザー報告の
    // バグ)。 _avoidOverlap と同じく height に統一する。
    final targetH = target.height;
    final draggedH = dragged.height;
    Offset adjusted = currentPos;

    switch (draggedAnchor) {
      case AnchorDirection.west:
        final need = target.position.dx + target.width + minGap;
        if (currentPos.dx < need) {
          adjusted = Offset(need, currentPos.dy);
        }
        break;
      case AnchorDirection.east:
        final need = target.position.dx - dragged.width - minGap;
        if (currentPos.dx > need) {
          adjusted = Offset(need, currentPos.dy);
        }
        break;
      case AnchorDirection.north:
        final need = target.position.dy + targetH + minGap;
        if (currentPos.dy < need) {
          adjusted = Offset(currentPos.dx, need);
        }
        break;
      case AnchorDirection.south:
        final need = target.position.dy - draggedH - minGap;
        if (currentPos.dy > need) {
          adjusted = Offset(currentPos.dx, need);
        }
        break;
      case AnchorDirection.northEast:
      case AnchorDirection.southEast:
        final needX = target.position.dx - dragged.width - minGap;
        if (currentPos.dx > needX) {
          adjusted = Offset(needX, currentPos.dy);
        }
        break;
      case AnchorDirection.northWest:
      case AnchorDirection.southWest:
        final needX = target.position.dx + target.width + minGap;
        if (currentPos.dx < needX) {
          adjusted = Offset(needX, currentPos.dy);
        }
        break;
    }

    // 他ノードとの重なりチェック＆回避。
    // 当たり判定はタイトル本体のみで行う (= 画像/動画/メモの視覚的延長は
    // 当たり判定の対象外。 ユーザー要望「画像/動画ノードの当たり判定が
    // 大きすぎる」 対応)。
    adjusted = _avoidOverlap(
        nodeId: draggedId,
        pos: adjusted,
        w: dragged.width,
        vh: dragged.height,
        provider: provider);

    return Offset(
      adjusted.dx.clamp(0.0, 20000.0),
      adjusted.dy.clamp(0.0, 20000.0),
    );
  }

  /// 他ノードとの重なりを回避する
  Offset _avoidOverlap({
    required String nodeId,
    required Offset pos,
    required double w,
    required double vh,
    required MindMapProvider provider,
  }) {
    // ── 当たり判定はノード本体 (タイトル領域) ベース ──
    // 画像 / 動画サムネイル / 長いメモは「視覚的拡張」 であり、 当たり判定
    // にはタイトル領域 (node.height) のみを使う。 visualHeight をそのまま
    // 使うと「画像を埋めた途端に当たり判定が縦に長くなり、 全然近づいて
    // いないのに他のノードが避ける」 という UX 問題が出る (ユーザー報告)。
    //
    // pad もユーザー要望を反映して 16 → 6 に減らし、 微妙に重なる距離なら
    // 干渉しないようにする。 結果として画像領域は他ノードと重なり得るが、
    // タイトル本体は確実に重ならない。
    const double pad = 6.0; // ノード間の最小余白 (was 16)
    Offset adjusted = pos;
    for (int attempt = 0; attempt < 20; attempt++) {
      bool overlapped = false;
      for (final other in provider.nodes.values) {
        if (other.id == nodeId) continue;
        // 格納ノードに隠されているメンバーは描画されないので重なり回避の対象外。
        if (other.hiddenInContainer != null) continue;
        // 当たり判定用には node.height のみ参照 (= タイトル本体のみ)。
        // 視覚的延長 (画像/動画/メモ) は当たり判定の対象外。
        final ovh = other.height;
        // 矩形の重なり判定（pad分の余白込み）
        if (adjusted.dx < other.position.dx + other.width + pad &&
            adjusted.dx + w + pad > other.position.dx &&
            adjusted.dy < other.position.dy + ovh + pad &&
            adjusted.dy + vh + pad > other.position.dy) {
          // 下にずらす（相手ノードのタイトル下端 + 余白）
          adjusted = Offset(adjusted.dx, other.position.dy + ovh + pad);
          overlapped = true;
          break;
        }
      }
      if (!overlapped) break;
    }
    return adjusted;
  }

  // ─── Overlay（アクションボタン） ─────────────────────────────────────────

  // ─── PC版：WebViewダイアログ（YouTube/検索） ────────────────────────────

  /// Google検索 + メモダイアログを起動。
  ///
  /// ── 引数 ──
  /// - `initialQuery`: 検索欄の初期キーワード (空なら Google トップから)
  /// - `initialMemo`: メモ入力欄の初期テキスト (空ならドラフトが復元される)
  /// - `customTitle`: タイトルバー表示用の追加文字列 (省略可)
  ///
  /// ── 動作 ──
  /// 「お気に入り 1〜5」 ボタンに表示するアイコン/ラベルのキャッシュ。
  /// Google 検索でユーザーが編集した内容を SharedPreferences から取り込んで
  /// 保持。 build() からは同期的にこの Map を参照する。
  /// key: slot index (0〜4), value: (icon, label, isEmpty)
  final List<({IconData icon, String label, bool isEmpty})> _customPagesCache =
      List.generate(
    5,
    (_) => (
      icon: Icons.bookmark_rounded,
      label: '',
      isEmpty: true,
    ),
  );

  // ─── 動的ブックマークボタン ────────────────────────────────────────
  /// ブックマーク ID (= 'bookmark:<hex>') → _BookmarkButton のキャッシュ。
  /// アプリ起動時に _loadBookmarkButtons() で SharedPreferences から復元。
  /// 編集時は _saveBookmarkButtons() で永続化。
  final Map<String, _BookmarkButton> _bookmarkButtonsCache = {};

  /// 32 文字の hex 形式でランダムな ID を生成。
  /// 'bookmark:' プレフィックスを付けて返す。
  String _generateBookmarkId() {
    final r = math.Random();
    final bytes = List<int>.generate(16, (_) => r.nextInt(256));
    final hex = bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join();
    return 'bookmark:$hex';
  }

  /// SharedPreferences からブックマークボタン一覧を読み込んでキャッシュ更新。
  /// 起動時と、 動的ブックマーク変更後 (他画面からの編集等) に呼ぶ。
  Future<void> _loadBookmarkButtons() async {
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString('mokumoku_bookmark_buttons_v1');
      _bookmarkButtonsCache.clear();
      if (raw == null || raw.isEmpty) return;
      final list = jsonDecode(raw);
      if (list is! List) return;
      for (final item in list) {
        final b = _BookmarkButton.fromJson(item);
        if (b != null) _bookmarkButtonsCache[b.id] = b;
      }
      if (mounted) setState(() {});
    } catch (e, st) {
      debugPrint('_loadBookmarkButtons 失敗: $e\n$st');
    }
  }

  /// 現在のキャッシュ内容を SharedPreferences に書き戻す。
  Future<void> _saveBookmarkButtons() async {
    try {
      final sp = await SharedPreferences.getInstance();
      final list = _bookmarkButtonsCache.values.map((b) => b.toJson()).toList();
      await sp.setString('mokumoku_bookmark_buttons_v1', jsonEncode(list));
    } catch (e, st) {
      debugPrint('_saveBookmarkButtons 失敗: $e\n$st');
    }
  }

  // ─── カスタム項目のアイコン override ───────────────────────────────
  //
  // ユーザー要望: 「カスタム項目それぞれ右クリックでアイコンの形状自体を
  //   別のものに変更したりできるようにして」 への対応。
  //
  // ヘッダー / フッターに配置できるカスタム項目 (= openChatGPT, openGemini,
  // openClaude, openDeepSeek, openGrok, openYoutube, openSpotify,
  // openSoundCloud, openQiita, calculator, stopwatch, pomodoro, weather,
  // calendar, messaging, addPage, shortcuts 等) のアイコンを、 ユーザーが
  // 右クリック / 長押しメニューから自由に変更できる仕組み。
  //
  // 永続化: SharedPreferences の `mokumoku_custom_icon_overrides_v1` に
  // `{commandId: codePoint}` 形式の JSON で保存。 アイコンの IconData は
  // codePoint (= 整数) で識別できれば再構築可能。
  //
  // Key 種別: bookmark:<hex> や customPage1〜5 のような動的 ID も対象にできる
  // が、 これらは別途専用の編集 UI (`_showBookmarkButtonContextMenu` /
  // `_showCustomPageContextMenu`) があるためそちらに任せる (= ここでは
  // 通常コマンド ID のみ扱う)。

  /// commandId → IconData の codePoint。 SharedPreferences で永続化される。
  Map<String, int> _customIconOverrides = {};

  /// SharedPreferences からアイコン override を読み込む (起動時)。
  Future<void> _loadCustomIconOverrides() async {
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString('mokumoku_custom_icon_overrides_v1') ?? '{}';
      final map = jsonDecode(raw);
      if (map is! Map) return;
      if (!mounted) return;
      setState(() {
        _customIconOverrides =
            map.map((k, v) => MapEntry(k.toString(), (v as num).toInt()));
      });
    } catch (e) {
      debugPrint('_loadCustomIconOverrides 失敗: $e');
    }
  }

  /// アイコン override を保存。 [codePoint] が null ならデフォルトに戻す。
  Future<void> _saveCustomIconOverride(String commandId, int? codePoint) async {
    setState(() {
      if (codePoint == null) {
        _customIconOverrides.remove(commandId);
      } else {
        _customIconOverrides[commandId] = codePoint;
      }
    });
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString('mokumoku_custom_icon_overrides_v1',
          jsonEncode(_customIconOverrides));
    } catch (e) {
      debugPrint('_saveCustomIconOverride 失敗: $e');
    }
  }

  /// カスタムアイコン機能のプリセット候補。 static const で列挙することで
  /// Flutter の icon tree shaker が「この IconData は使われている」 と
  /// 判定でき、 ビルド時に `--no-tree-shake-icons` フラグ無しでビルドできる
  /// ようになる。 動的な `IconData(cp, fontFamily: 'MaterialIcons')` 構築は
  /// tree shaker が見抜けず、 APK ビルドが
  ///   "Avoid non-constant invocations of IconData"
  /// で失敗するため、 codePoint から IconData への変換はこの静的マップで行う。
  static const List<IconData> _kCustomIconCandidates = <IconData>[
    Icons.star_rounded,
    Icons.favorite_rounded,
    Icons.bookmark_rounded,
    Icons.label_rounded,
    Icons.flag_rounded,
    Icons.lightbulb_rounded,
    Icons.bolt_rounded,
    Icons.local_fire_department_rounded,
    Icons.psychology_rounded,
    Icons.auto_awesome_rounded,
    Icons.assistant_rounded,
    Icons.hub_rounded,
    Icons.smart_toy_rounded,
    Icons.chat_rounded,
    Icons.forum_rounded,
    Icons.send_rounded,
    Icons.home_rounded,
