  /// codePoint → IconData の lookup マップ。 [_kCustomIconCandidates] と
  /// 自動で同期するので、 候補リストを更新すれば自動的に反映される。
  /// `_kCustomIconCandidates` に IconData を 1 つでも追加すれば、 そのアイコン
  /// が ビルド成果物にも自動的に含まれる。
  static final Map<int, IconData> _kCustomIconByCodePoint = {
    for (final ic in _kCustomIconCandidates) ic.codePoint: ic,
  };

  /// commandId のアイコンを取得 (override があれば優先)。
  /// 描画箇所からはこれを呼ぶことでカスタマイズが反映される。
  IconData _resolveCustomIcon(String commandId, IconData defaultIcon) {
    final cp = _customIconOverrides[commandId];
    if (cp == null) return defaultIcon;
    // tree shaking 対応:
    //   旧実装は `IconData(cp, fontFamily: 'MaterialIcons')` で動的に
    //   構築していたが、 Flutter のビルドツールが「このアイコンが使われる」
    //   ことを静的解析できず、 APK release build で
    //     "Avoid non-constant invocations of IconData"
    //   というエラーで落ちていた。
    //   現在は事前列挙された候補から codePoint で lookup する形にして、
    //   tree shaker が確実に動作するようにしてある。 候補に含まれない
    //   codePoint (= 旧バージョンで保存されたカスタムアイコン等) は
    //   defaultIcon にフォールバック。
    return _kCustomIconByCodePoint[cp] ?? defaultIcon;
  }

  /// カスタムボタンのアイコン Widget を返す。 通常は `Icon` だが、 一部の
  /// コマンドは IconData では表現できないので専用描画に差し替える。
  ///   - openDeepSeek: DeepSeek 公式ロゴのクジラ (= ユーザー要望)。
  /// ユーザーがアイコン形状を上書きしている場合は上書きを尊重して通常 `Icon`。
  /// ユーザーがアップロードした独自アイコン画像 (commandId → ファイルパス)。
  /// (= ユーザー要望: アイコンの画像を自分でアップロードしてカスタマイズ)
  final Map<String, String> _customIconImages = {};
  static const String _kCustomIconImagesKey = 'customIconImages_v1';

  Future<void> _loadCustomIconImages() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kCustomIconImagesKey);
      if (raw == null || raw.isEmpty) return;
      final m = jsonDecode(raw);
      if (m is! Map || !mounted) return;
      setState(() {
        _customIconImages.clear();
        m.forEach((k, v) {
          if (k is String && v is String && v.isNotEmpty) {
            _customIconImages[k] = v;
          }
        });
      });
    } catch (_) {}
  }

  Future<void> _setCustomIconImage(String commandId, String? path) async {
    setState(() {
      if (path == null || path.isEmpty) {
        _customIconImages.remove(commandId);
      } else {
        _customIconImages[commandId] = path;
      }
    });
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(
          _kCustomIconImagesKey, jsonEncode(_customIconImages));
    } catch (_) {}
  }

  /// 画像を選んで丸く切り抜き、 このボタンのアイコンにする (= ユーザー要望)。
  Future<void> _pickAndCropIconImage(String commandId) async {
    try {
      final res = await FilePicker.platform.pickFiles(type: FileType.image);
      final path = res?.files.single.path;
      if (path == null || path.isEmpty || !mounted) return;
      final saved = await showDialog<String>(
        context: context,
        barrierColor: Colors.black87,
        builder: (_) =>
            _CircleCropDialog(imagePath: path, saveName: commandId),
      );
      if (saved != null && saved.isNotEmpty) {
        await _setCustomIconImage(commandId, saved);
      }
    } catch (_) {}
  }

  Widget _cmdIconWidget(String commandId, IconData icon,
      {required Color color, required double size}) {
    // アップロードされた画像が最優先 (= ユーザー要望)。
    final imgPath = _customIconImages[commandId];
    if (imgPath != null && imgPath.isNotEmpty) {
      final f = File(imgPath);
      if (f.existsSync()) {
        // 形 (丸 / 四角) は切り抜き時の PNG 自体が持っている (透明部分)。
        return Image.file(f,
            width: size + 4, height: size + 4, fit: BoxFit.contain);
      }
    }
    if (commandId == 'openDeepSeek' &&
        !_customIconOverrides.containsKey(commandId)) {
      return _WhaleIcon(color: color, size: size);
    }
    // X (旧 Twitter) は Material に本物のロゴが無く、 旧アイコン (@ 字) は
    //   Threads に見えてしまうので、 文字の「X」 を描く (= ユーザー要望)。
    if (commandId == 'openX' && !_customIconOverrides.containsKey(commandId)) {
      return _letterXIcon(color, size);
    }
    return Icon(icon, color: color, size: size);
  }

  /// 文字「X」 をアイコンとして描く (= ユーザー要望: X のアイコンを文字の X に)。
  Widget _letterXIcon(Color color, double size) {
    return SizedBox(
      width: size,
      height: size,
      child: Center(
        child: Text('X',
            style: TextStyle(
                color: color,
                fontSize: size,
                fontWeight: FontWeight.w900,
                height: 1.0)),
      ),
    );
  }

  /// `_ToolBarBtn` の `iconWidget` 用。 DeepSeek なら白クジラ Widget、
  /// そうでなければ null (= `_ToolBarBtn` が通常の `Icon` を描く)。
  /// _ToolBarBtn はアイコンを常に白で colored 背景の上に描くので白固定。
  Widget? _toolbarWhaleIcon(String commandId, {double size = 17}) {
    if (commandId == 'openDeepSeek' &&
        !_customIconOverrides.containsKey(commandId)) {
      return _WhaleIcon(color: Colors.white, size: size);
    }
    // X (旧 Twitter): 文字の「X」 を白で描く (colored 背景の上)。
    if (commandId == 'openX' && !_customIconOverrides.containsKey(commandId)) {
      return _letterXIcon(Colors.white, size);
    }
    return null;
  }

  /// アイコン選択ダイアログ。 ユーザーが「アイコン変更」 を選んだ時に表示。
  /// プリセットから選ぶ + 「デフォルトに戻す」 ボタン。
  /// 候補リストは [_kCustomIconCandidates] (= static const) を参照する。
  Future<void> _showIconPickerDialog(String commandId) async {
    final provider = context.read<MindMapProvider>();
    // 押したボタンの近くに出す (= ユーザー要望: カスタムボタンの設定で
    // 開かれる画面は全てボタンの近くに)。
    final anchor = _customButtonAnchor();
    final picked = await showDialog<IconData>(
      context: context,
      barrierColor:
          Colors.black.withValues(alpha: anchor == null ? 0.5 : 0.25),
      builder: (ctx) => _positionNearAnchor(
        ctx,
        anchor,
        AlertDialog(
        backgroundColor: const Color(0xFF1E1E2E),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        title: Text(provider.t('icon.select'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        content: SizedBox(
          width: 380,
          height: 384,
          child: Column(children: [
            // ── 自分の画像をアイコンにする (= ユーザー要望: アップロードして
            //    独自にカスタマイズ。 丸く切り抜く編集画面つき) ──
            Row(children: [
              Expanded(
                child: OutlinedButton.icon(
                  icon: const Icon(Icons.add_photo_alternate_rounded,
                      size: 16, color: Color(0xFF4FC3F7)),
                  label: Text(provider.t('icon.uploadImage'),
                      style: const TextStyle(
                          color: Color(0xFF4FC3F7), fontSize: 12)),
                  style: OutlinedButton.styleFrom(
                      side: const BorderSide(color: Colors.white24)),
                  onPressed: () {
                    Navigator.of(ctx).pop();
                    unawaited(_pickAndCropIconImage(commandId));
                  },
                ),
              ),
              if (_customIconImages.containsKey(commandId)) ...[
                const SizedBox(width: 8),
                OutlinedButton(
                  style: OutlinedButton.styleFrom(
                      side: const BorderSide(color: Colors.white24)),
                  onPressed: () {
                    Navigator.of(ctx).pop();
                    unawaited(_setCustomIconImage(commandId, null));
                  },
                  child: Text(provider.t('icon.removeImage'),
                      style: const TextStyle(
                          color: Color(0xFFFF8A80), fontSize: 12)),
                ),
              ],
            ]),
            const SizedBox(height: 8),
            Expanded(
              child: GridView.count(
                crossAxisCount: 8,
                mainAxisSpacing: 4,
                crossAxisSpacing: 4,
                children: [
                  for (final ic in _kCustomIconCandidates)
                    InkWell(
                      onTap: () => Navigator.of(ctx).pop(ic),
                      borderRadius: BorderRadius.circular(8),
                      child: Container(
                        decoration: BoxDecoration(
                          color: _customIconOverrides[commandId] ==
                                  ic.codePoint
                              ? const Color(0xFF6C63FF)
                                  .withValues(alpha: 0.3)
                              : Colors.transparent,
                          borderRadius: BorderRadius.circular(8),
                        ),
                        child: Icon(ic, color: Colors.white, size: 22),
                      ),
                    ),
                ],
              ),
            ),
          ]),
        ),
        actions: [
          if (_customIconOverrides.containsKey(commandId))
            TextButton(
              onPressed: () {
                Navigator.of(ctx).pop();
                _saveCustomIconOverride(commandId, null);
              },
              child: Text(provider.t('shortcuts.resetTooltip'),
                  style: const TextStyle(color: Color(0xFFFF6B6B))),
            ),
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white70)),
          ),
        ],
      ),
        const Size(420, 480),
      ),
    );

    if (picked != null) {
      await _saveCustomIconOverride(commandId, picked.codePoint);
    }
  }

  /// カスタム項目用の右クリック / 長押しメニュー。 アイコン変更 + 色変更
  /// + 削除を提供。
  ///
  /// ★ 押したボタンのすぐ近くに出す (= ユーザー要望: 設定項目は押しやすい
  ///   ようにボタンの近くに出現するように)。 [ctx] は押されたボタン自身の
  ///   BuildContext で、 その画面上の位置に合わせてメニューを置く。
  ///   位置が取れない時だけ、 従来どおり中央に出す。
  /// 直近に押されたカスタムボタンの画面座標 (= ユーザー報告: 左右のバーに
  /// 置いたボタンの設定がヘッダーの所に出てしまう)。 長押し / 右クリックの
  /// コールバックには位置が来ないものがあるので、 Listener で拾って控える。
  Offset? _lastCustomButtonPointerPos;

  // ─── ボタンの「開き方」 (全画面 / 画面分割) ───────────────────────────
  //
  // ユーザー要望: 「google 検索は全画面で立ち上がるのに、 Gmail は分割画面で
  //   立ち上がるとか変。 右クリック (モバイルは長押し) で全画面か画面分割かを
  //   選べるように」。 既定は今までの動きのままで、 変えた時だけ効く。

  /// Web を開く系ボタンの URL と表示名。 開き方を切り替える時に使う。
  static const Map<String, List<String>> _webCommandTargets = {
    'openChatGPT': ['https://chatgpt.com/', 'ChatGPT'],
    'openGemini': ['https://gemini.google.com/app', 'Gemini'],
    'openClaude': ['https://claude.ai/', 'Claude'],
    'openDeepSeek': ['https://chat.deepseek.com/', 'DeepSeek'],
    'openGrok': ['https://grok.com/', 'Grok'],
    'openGmail': ['https://mail.google.com/', 'Gmail'],
    'openReddit': ['https://www.reddit.com/', 'Reddit'],
    'openX': ['https://x.com/', 'X'],
    'openYoutubeMusic': ['https://music.youtube.com/', 'YouTube Music'],
    'openDeepL': ['https://www.deepl.com/translator', 'DeepL'],
    'openGoogleCalendar': ['https://calendar.google.com/', 'Google Calendar'],
    'openGoogleDrive': ['https://drive.google.com/', 'Google Drive'],
    'openGoogleMaps': ['https://www.google.com/maps', 'Google Maps'],
    'openGoogleEarth': ['https://earth.google.com/web/', 'Google Earth'],
    // ビデオ会議 (Meet / Zoom) は _webCommandTargets に入れない。
    //   埋め込み WebView では通話が始まらないので、 全画面 / 分割 /
    //   フローティングのどれを選んでも意味が無く、 外のブラウザで開く
    //   (= ユーザー報告への対応)。
    'openKindle': ['https://read.amazon.co.jp/', 'Kindle'],
    'openSlack': ['https://app.slack.com/', 'Slack'],
    'openDiscord': ['https://discord.com/channels/@me', 'Discord'],
    // URL は設定で変わるので _webCommandUrl で作り直す (= 開く画面の選択)。
    'openInstagram': ['https://www.instagram.com/', 'Instagram'],
    // YouTube も画面分割 / フローティングで開けるように (= ユーザー要望)。
    'openYoutube': ['https://m.youtube.com/', 'YouTube'],
    'openSpotify': ['https://open.spotify.com/', 'Spotify'],
    'openSoundCloud': ['https://soundcloud.com/', 'SoundCloud'],
    'openAmazon': ['https://www.amazon.co.jp/', 'Amazon'],
    'openQiita': ['https://qiita.com/', 'Qiita'],
    'openLINE': ['https://line.me/ja/', 'LINE'],
    // 統合 AI ボタン。 URL は選択中の AI に合わせて _webCommandUrl が作る。
    'openAi': ['', 'AI'],
  };

  /// 何も設定していない時の開き方 (= 今までの動き)。 ここに入っているものは
  /// 画面分割 (右)、 それ以外は全画面。
  static const Set<String> _splitByDefaultCommands = {
    'openChatGPT',
    'openGemini',
    'openClaude',
    'openDeepSeek',
    'openGrok',
    'openGmail',
  };

  /// 選べる開き方。 順番はそのまま UI の並び順。
  static const List<String> _openStyles = [
    'full', // 全画面
    'splitLeft', // 左に分割
    'splitRight', // 右に分割
    'floating', // フローティング
  ];

  /// ユーザーが決めた開き方 (id → _openStyles のどれか)。 prefs に残す。
  final Map<String, String> _commandOpenStyle = {};
  static const String _kCommandOpenStyleKey = 'commandOpenStyle_v1';

  /// このボタンの開き方。 設定が無ければ今までの動き。
  String _openStyleOf(String commandId) {
    final v = _commandOpenStyle[commandId];
    if (v != null && _openStyles.contains(v)) return v;
    // 旧版の 'split' は「右に分割」 として読む (= 設定を引き継ぐ)。
    if (v == 'split') return 'splitRight';
    // ショートカット一覧の既定は今までどおり全画面のダイアログ
    //   (フローティング / 分割は選んだ人だけ = ユーザー要望)。
    if (commandId == 'shortcuts') return 'full';
    // AI アシスタントの既定も今までどおり全画面のダイアログ。
    //   (分割 / フローティングは選んだ人だけ = ユーザー要望)
    if (commandId == 'aiAssistant') return 'full';
    // 道具ボタン (フラッシュカード等) の既定は浮遊窓 (= 今までの動き)。
    if (_floatableToolCommands.contains(commandId)) return 'floating';
    return _splitByDefaultCommands.contains(commandId) ? 'splitRight' : 'full';
  }

  /// 開き方の表示名。
  String _openStyleLabel(MindMapProvider provider, String style) {
    switch (style) {
      case 'splitLeft':
        return provider.t('openStyle.splitLeft');
      case 'splitRight':
        return provider.t('openStyle.splitRight');
      case 'floating':
        return provider.t('openStyle.floating');
      default:
        return provider.t('openStyle.full');
    }
  }

  /// URL は開かないが「全画面 / フローティング」 を選べる道具ボタン。
  ///
  /// = ユーザー要望「フラッシュカードもフローティングモード等で開けるように
  ///   して欲しい」。 左右分割は中身が Web ページではないので出さない。
  static const Set<String> _floatableToolCommands = {
    'flashcards',
    // ショートカット一覧 (= ユーザー要望: 一覧もフローティングモードや
    //   画面分割で開けるように)。 分割は「ペインの中に全画面」 で入る。
    'shortcuts',
    // メモ (= ユーザー要望: マップメモとフローティングメモの統合)。
    //   全画面 = マップのメモ画面、 フローティング = 浮かぶメモ窓。
    'mapMemo',
    // AI アシスタント (= ユーザー要望: 画面自体を左右分割やフローティングで
    //   出せるように)。 分割は「ペインの中に全画面」 で入る。
    'aiAssistant',
  };

  /// 開き方を選べるボタンか (= URL を開くボタン + 上の道具ボタン)。
  bool _canChooseOpenStyle(String commandId) =>
      _webCommandTargets.containsKey(commandId) ||
      _floatableToolCommands.contains(commandId) ||
      // = ユーザー要望: Google 検索と自動化も左右分割 / フローティングで
      //   開けるように。
      commandId == 'googleSearch' ||
      commandId == 'webAutomation';

  /// そのボタンで選べる開き方の一覧。 道具ボタンは全画面とフローティングだけ。
  List<String> _openStylesFor(String commandId) {
    // ショートカット一覧は分割ペインの中にも入れられる (= ユーザー要望)。
    if (commandId == 'shortcuts' ||
        commandId == 'aiAssistant' ||
        commandId == 'googleSearch' ||
        // メモも左右分割で開ける (= ユーザー要望)。
        commandId == 'mapMemo') {
      return const ['full', 'floating', 'splitLeft', 'splitRight'];
    }
    // 自動化は手順の窓なので、 全画面か浮遊窓のどちらか (= 分割ペインに
    // 入れると操作するブラウザと重なって使えない)。
    if (commandId == 'webAutomation') {
      return const ['full', 'floating'];
    }
    return _floatableToolCommands.contains(commandId)
        ? const ['full', 'floating']
        : _openStyles;
  }

  /// 開き方の読み込みが済んだ合図 (= ショートカット実行が読み込みより先に
  /// 走って既定の右分割になってしまうのを防ぐ)。
  late final Future<void> _commandOpenStylesReady = _loadCommandOpenStyles();

  Future<void> _loadCommandOpenStyles() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kCommandOpenStyleKey);
      if (raw == null || raw.isEmpty) return;
      final m = jsonDecode(raw);
      if (m is! Map) return;
      if (!mounted) return;
      setState(() {
        _commandOpenStyle.clear();
        m.forEach((k, v) {
          // ★ 'full' / 'split' しか読んでいなかったため、 保存した
          //   「左に分割 / 右に分割 / フローティング」 が再起動で消えていた
          //   (= 設定したのに次に開くと既定に戻る)。 今ある開き方は全部読む。
          //   'split' は旧版の値なので、 そのまま入れて _openStyleOf が
          //   「右に分割」 として解釈する。
          if (k is String &&
              v is String &&
              (_openStyles.contains(v) || v == 'split')) {
            _commandOpenStyle[k] = v;
          }
        });
      });
    } catch (_) {}
  }

  Future<void> _setCommandOpenStyle(String commandId, String style) async {
    setState(() => _commandOpenStyle[commandId] = style);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(
          _kCommandOpenStyleKey, jsonEncode(_commandOpenStyle));
    } catch (_) {}
  }

  /// このボタンが開く URL。 Instagram のように設定で変わるものはここで作る。
  String? _webCommandUrl(String commandId) {
    if (commandId == 'openInstagram') return _instagramUrl();
    if (commandId == 'openAi') {
      // 選択中のブラウザ AI のチャット画面 (クエリ無し)。
      final t = context.read<MindMapProvider>().browserAiTargetDef;
      return (t['url'] ?? '').replaceAll('{q}', '');
    }
    final t = _webCommandTargets[commandId];
    return t == null ? null : t[0];
  }

  /// 設定された開き方で Web を開く。 まだ何も設定していない時は false を
  /// 返して、 従来の処理にそのまま任せる (= 特別扱いの多いボタンを壊さない)。
  bool _openWebCommandStyled(String commandId) {
    // ユーザーが一度も選んでいなければ、 今までどおりの動き。
    if (!_commandOpenStyle.containsKey(commandId)) return false;
    final target = _webCommandTargets[commandId];
    if (target == null) return false;
    final url = _webCommandUrl(commandId) ?? target[0];
    if (url.isEmpty) return false;
    final provider = context.read<MindMapProvider>();
    switch (_openStyleOf(commandId)) {
      // ── 分割で開く設定のボタンは「もう一度押すと閉じて全画面に戻る」 ──
      //    (= ユーザー報告: 分割で開いた後にボタンを押し直しても全画面に
      //    戻らない)。 既定経路と同じトグル (_toggleUrlInSplitPanel) を通す。
      case 'splitLeft':
        _toggleUrlInSplitPanel(url, isLeftPanel: true);
        break;
      case 'splitRight':
        _toggleUrlInSplitPanel(url, isLeftPanel: false);
        break;
      case 'floating':
        // ── YouTube はアプリの中の浮遊窓で開く (= ユーザー報告: YouTube が
        //    フローティングモードでアプリの中から立ち上がらない) ──
        //    こちらの窓は再生速度バーやセルへの埋め込みに対応している。
        //    中の WebView を作れなかった時は外の窓へ自動で逃げる。
        if (commandId == 'openYoutube' ||
            url.contains('youtube.com') ||
            url.contains('youtu.be')) {
          _showFloatingVideoWindow(url, external: false);
          break;
        }
        // それ以外は外の本物の窓で開く (= ユーザー要望: 統合)。
        _openFloatingWebUnified(url);
        break;
      default:
        // ── YouTube は Google 検索の画面ではなく、 アプリの YouTube 画面で
        //    開く (= ユーザー報告: PC のカスタムボタンから開くと Google 検索
        //    の YouTube で開いてしまう)。 こちらはサムネイル付きの埋め込みや
        //    再生速度に対応している。 ──
        if (commandId == 'openYoutube') {
          _openYoutubeBrowser(context, provider, forceHome: true);
          break;
        }
        _openGoogleSearchDialog(context, provider,
            initialUrl: url, customTitle: target[1]);
    }
    return true;
  }

  /// 直近に押されたカスタムボタンが載っているバー全体の画面座標
  /// (= ユーザー要望: 近くに出す時はバーと被らないように)。
  /// 押した瞬間に控えておき、 ダイアログをこの帯の外へ逃がすのに使う。
  Rect? _lastCustomButtonBarRect;

  /// BuildContext が指す widget の画面上の矩形。 取れなければ null。
  Rect? _rectOfContext(BuildContext? ctx) {
    if (ctx == null) return null;
    try {
      final box = ctx.findRenderObject() as RenderBox?;
      if (box != null && box.hasSize && box.attached) {
        return box.localToGlobal(Offset.zero) & box.size;
      }
    } catch (_) {}
    return null;
  }

  /// ボタンの矩形から、 それが載っているバー (画面の端に沿った帯) を推定する。
  ///
  /// バーは必ず画面のどれかの端に張り付いているので、 ボタンから一番近い端を
  /// 探し、 その端からボタンの向こう側までを「バーの帯」 とみなす。
  /// バー自体の widget を辿らずに済むので、 ヘッダー・左右バー・下バーの
  /// どれでも同じ理屈で効く。
  Rect _inferBarRect(Rect btn, Size screen) {
    final toLeft = btn.left;
    final toRight = screen.width - btn.right;
    final toTop = btn.top;
    final toBottom = screen.height - btn.bottom;
    final nearest = [toLeft, toRight, toTop, toBottom]
        .reduce((a, b) => a < b ? a : b);
    if (nearest == toLeft) {
      return Rect.fromLTRB(0, 0, btn.right, screen.height);
    }
    if (nearest == toRight) {
      return Rect.fromLTRB(btn.left, 0, screen.width, screen.height);
    }
    if (nearest == toTop) {
      return Rect.fromLTRB(0, 0, screen.width, btn.bottom);
    }
    return Rect.fromLTRB(0, btn.top, screen.width, screen.height);
  }

  /// ボタンが載っているバー (帯) を、 先祖を辿って実際に測る。
  ///
  /// ★ 端からの距離で推定する `_inferBarRect` は、 下バーの一番左 (右) の
  ///   ボタンのように「角に近いボタン」 で横バーを縦バーと取り違える
  ///   (左端まで 16px / 下端まで 50px なら「左バー」 と判定されてしまう)。
  ///   すると設定メニューがバーの真横 = 画面の上の方へ飛ばされ、 ヘッダーの
  ///   辺りに出てしまっていた (= ユーザー報告: 下部ボタンを長押しした時の
  ///   設定項目がヘッダーの所に出る)。 実物を測れば取り違えない。
  Rect? _barRectOfButton(BuildContext? ctx, Rect btn, Size screen) {
    if (ctx == null) return null;
    Rect? found;
    try {
      ctx.visitAncestorElements((el) {
        final ro = el.renderObject;
        if (ro is RenderBox && ro.hasSize && ro.attached) {
          final Rect r;
          try {
            r = ro.localToGlobal(Offset.zero) & ro.size;
          } catch (_) {
            return true;
          }
          // 画面まるごと (= 背景や Stack) まで来たら打ち切る。
          if (r.width >= screen.width * 0.95 &&
              r.height >= screen.height * 0.9) {
            return false;
          }
          final bool wide = r.width >= screen.width * 0.55 &&
              r.height <= screen.height * 0.45;
          final bool tall = r.height >= screen.height * 0.45 &&
              r.width <= screen.width * 0.4;
          if ((wide || tall) && r.contains(btn.center)) {
            found = r;
            return false;
          }
        }
        return true;
      });
    } catch (_) {}
    return found;
  }

  /// 押されたカスタムボタンの位置と、 そのバーの帯を控える。
  /// [btnCtx] はボタン自身の BuildContext (取れなければ押下点で代用)。
  void _rememberCustomButtonPress(Offset pos, BuildContext? btnCtx) {
    _lastCustomButtonPointerPos = pos;
    final screen = MediaQuery.sizeOf(btnCtx ?? context);
    final btn = _rectOfContext(btnCtx) ??
        Rect.fromCenter(center: pos, width: 44, height: 44);
    // 先祖から実測 → 取れない時だけ端からの距離で推定する。
    _lastCustomButtonBarRect =
        _barRectOfButton(btnCtx, btn, screen) ?? _inferBarRect(btn, screen);
  }

  /// カスタムボタンの設定系ダイアログを、 押したボタンの近くに出すための
  /// 「錨」。 [at] が無ければ直近の押下位置を使う。
  Rect? _customButtonAnchor([Offset? at]) {
    final p = at ?? _lastCustomButtonPointerPos;
    if (p == null) return null;
    return Rect.fromCenter(center: p, width: 1, height: 1);
  }

  /// 錨の近くにダイアログを置く (画面外へはみ出さないよう寄せる)。
  /// [anchor] が null の時は中央 (= 従来どおり)。
  ///
  /// [avoid] (既定は直近に押されたバーの矩形) と重なる時は、 その帯の外へ
  /// 逃がす (= ユーザー要望: 近くに出す時はバーと被らないように)。
  /// 横長のバー (ヘッダー/下バー) なら上下へ、 縦長のバー (左右バー) なら
  /// 左右へ逃がす。
  Widget _positionNearAnchor(
      BuildContext ctx, Rect? anchor, Widget child, Size size,
      {Rect? avoid, bool useLastBar = true}) {
    if (anchor == null) return Center(child: child);
    final screen = MediaQuery.sizeOf(ctx);
    final bar = avoid ?? (useLastBar ? _lastCustomButtonBarRect : null);
    final bool sideBar = bar != null && !bar.isEmpty && bar.height > bar.width;
    // ── バーの外に置ける高さまで縮める (= ユーザー要望: 押したボタンの
    //    周囲に出す)。 縮めないと画面に入りきらず、 clamp で画面の上端 =
    //    ヘッダーの辺りまで飛ばされてしまう。 中身は縦にスクロールできる。 ──
    double boxH = size.height;
    if (bar != null && !bar.isEmpty && !sideBar) {
      final double above = bar.top - 16;
      final double below = screen.height - bar.bottom - 16;
      final double room = above > below ? above : below;
      if (room > 160 && boxH > room) boxH = room;
    }
    if (boxH > screen.height - 16) boxH = screen.height - 16;
    size = Size(size.width, boxH);
    child = ConstrainedBox(
        constraints: BoxConstraints(maxHeight: boxH), child: child);
    final double maxLeft = (screen.width - size.width - 8.0).clamp(8.0, 1e5);
    final double maxTop = (screen.height - size.height - 8.0).clamp(8.0, 1e5);

    double left;
    double top;
    if (sideBar) {
      // ── 左右のバー: ボタンの「真横」 に、 高さの中央を合わせて置く
      //    (= ユーザー要望: 少し下にずれるのではなく、 上下に余裕があるなら
      //    ボタンの高さに中央が来るよう真横に)。 画面からはみ出す時だけ
      //    clamp で寄せる (= 上下に余裕が無い時)。 ──
      left = (bar.center.dx < screen.width / 2)
          ? bar.right + 8
          : bar.left - size.width - 8;
      top = anchor.center.dy - size.height / 2;
    } else {
      // ── ヘッダー / 下バー / 不明: 従来どおりボタンの下 (入らなければ上) ──
      left = anchor.center.dx - size.width / 2;
      top = anchor.bottom + 8;
      if (top + size.height > screen.height - 8) {
        top = anchor.top - size.height - 8;
      }
    }
    left = left.clamp(8.0, maxLeft);
    top = top.clamp(8.0, maxTop);

    // ── それでもバーと重なるなら逃がす (横長バーは上下へ、 縦長バーは左右へ) ──
    if (bar != null && !bar.isEmpty) {
      var rect = Rect.fromLTWH(left, top, size.width, size.height);
      if (rect.overlaps(bar)) {
        if (bar.width >= bar.height) {
          final below = bar.bottom + 8;
          final above = bar.top - size.height - 8;
          top = (above >= 8 && (bar.top > screen.height - bar.bottom))
              ? above
              : below;
          top = top.clamp(8.0, maxTop);
        } else {
          left = (bar.center.dx < screen.width / 2)
              ? (bar.right + 8).clamp(8.0, maxLeft)
              : (bar.left - size.width - 8).clamp(8.0, maxLeft);
        }
        // まだ重なる (バーが大きすぎる) 時は、 もう一方の軸でも逃がす。
        rect = Rect.fromLTWH(left, top, size.width, size.height);
        if (rect.overlaps(bar)) {
          if (bar.width >= bar.height) {
            left = (bar.center.dx < screen.width / 2)
                ? (bar.right + 8).clamp(8.0, maxLeft)
                : (bar.left - size.width - 8).clamp(8.0, maxLeft);
          } else {
            top = (bar.center.dy < screen.height / 2)
                ? (bar.bottom + 8).clamp(8.0, maxTop)
                : (bar.top - size.height - 8).clamp(8.0, maxTop);
          }
        }
      }
    }
    return Stack(children: [
      Positioned(left: left, top: top, width: size.width, child: child),
    ]);
  }

  Future<void> _showCustomItemContextMenu(BuildContext ctx, String commandId,
      {Offset? at}) async {
    final provider = ctx.read<MindMapProvider>();
    // 押されたボタンの位置と大きさ (画面座標)。
    //
    // ★ [at] (= 実際に押された画面上の点) が渡されていればそれを最優先で
    //   使う (= ユーザー報告: 左右のバーに置いたカスタムボタンの設定が
    //   ヘッダーの所に出てしまう)。 [ctx] はボタンを組み立てている
    //   メソッドの context で、 ボタン自身ではなく囲みのバー全体を指して
    //   いることがあり、 それだと位置がずれる。
    Rect? anchor = _customButtonAnchor(at);
    if (anchor == null) {
      try {
        final box = ctx.findRenderObject() as RenderBox?;
        if (box != null && box.hasSize) {
          final topLeft = box.localToGlobal(Offset.zero);
          anchor = topLeft & box.size;
        }
      } catch (_) {}
    }
    await showDialog<void>(
      context: ctx,
      // 背景は薄く (近くに出るので画面全体を暗くしすぎない)。
      barrierColor: Colors.black.withValues(alpha: anchor == null ? 0.5 : 0.2),
      builder: (sctx) {
        // ── 画面に収まる大きさにする (= ユーザー報告: モバイルで下部ボタンを
        //    長押しすると設定が画面の上の方に出てしまう)。 実際の高さが
        //    見積もりより大きいと、 置き場所の計算がずれて遠くへ飛ぶので、
        //    ここで上限を決めて中を縦スクロールにする。 ──
        final scr = MediaQuery.sizeOf(sctx);
        final menuW = math.min(380.0, scr.width - 24.0);
        // パソコンは画面が広いので、 縦は目一杯まで使って最後の項目まで
        // 出し切る (= ユーザー要望: PC は下まで表示し切って欲しい)。
        // 触る端末は今までどおり画面の半分までにして、 中を縦スクロール。
        final menuH = _isDesktop
            ? math.max(320.0, scr.height - 96.0)
            : math.min(360.0, math.max(200.0, scr.height * 0.5));
        final menu = Material(
        color: const Color(0xFF1E1E2E),
        elevation: 12,
        borderRadius: BorderRadius.circular(14),
        child: ConstrainedBox(
          constraints: BoxConstraints(maxWidth: menuW, maxHeight: menuH),
          child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const SizedBox(height: 8),
              // ── 説明 (= ユーザー要望: 「裁断モード」 等が何のことか
              //    分からないので、 各ボタンに説明の項目を) ──
              //    ここで全文が読めるので、 押しても何も起きない
              //    (= ユーザー要望: この時点で見えるから押せないように)。
              ListTile(
                leading: const Icon(Icons.help_outline_rounded,
                    color: Color(0xFF4FC3F7)),
                title: Text(provider.t('cmd.description'),
                    style: const TextStyle(color: Colors.white)),
                subtitle: Text(
                  _commandDescription(provider, commandId),
                  style:
                      const TextStyle(color: Colors.white54, fontSize: 11),
                ),
              ),
              // ── 開き方 (全画面 / 左右分割 / フローティング) ──
              //    URL を開くだけのボタンにだけ出す (= ユーザー要望)。
              //    ★ 見出しと選択肢を同じ行に並べて縦を詰める (= ユーザー要望:
              //      横に持ってきたらコンパクトに収まるのでは)。
              if (_canChooseOpenStyle(commandId)) ...[
                const Divider(color: Colors.white12, height: 1),
                StatefulBuilder(
                  builder: (rowCtx, setRow) => Padding(
                    padding: const EdgeInsets.fromLTRB(16, 8, 12, 8),
                    child: Row(children: [
                      const Icon(Icons.open_in_new_rounded,
                          color: Color(0xFF26C6DA), size: 18),
                      const SizedBox(width: 10),
                      Text(provider.t('openStyle.title'),
                          style: const TextStyle(
                              color: Colors.white, fontSize: 13)),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Wrap(
                          alignment: WrapAlignment.end,
                          spacing: 4,
                          runSpacing: 4,
                          children: [
                            for (final s in _openStylesFor(commandId))
                              _openStyleChip(commandId, s,
                                  _openStyleLabel(provider, s), setRow),
                          ],
                        ),
                      ),
                    ]),
                  ),
                ),
                // ── AI を選ぶ (= 統合 AI ボタンだけ)。 その場のチップで
                //    切り替えられる (= ユーザー要望: アイコンや開き方の設定と
                //    同じメニューにまとめる)。 ──
                if (commandId == 'openAi') ...[
                  StatefulBuilder(
                    builder: (aiCtx, setAiSel) => Padding(
                      padding: const EdgeInsets.fromLTRB(16, 4, 12, 4),
                      child: Row(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            const Padding(
                              padding: EdgeInsets.only(top: 6),
                              child: Icon(Icons.auto_awesome_rounded,
                                  color: Color(0xFFBA68C8), size: 18),
                            ),
                            const SizedBox(width: 10),
                            Padding(
                              padding: const EdgeInsets.only(top: 8),
                              child: Text(provider.t('ai.selectAi'),
                                  style: const TextStyle(
                                      color: Colors.white, fontSize: 13)),
                            ),
                            const SizedBox(width: 10),
                            Expanded(
                              child: Wrap(
                                alignment: WrapAlignment.end,
                                spacing: 4,
                                runSpacing: 4,
                                children: [
                                  for (final t
                                      in MindMapProvider.browserAiTargets)
                                    InkWell(
                                      borderRadius: BorderRadius.circular(20),
                                      onTap: () {
                                        unawaited(provider.setBrowserAiTarget(
                                            t['id'] ?? ''));
                                        setAiSel(() {});
                                      },
                                      child: Container(
                                        padding: const EdgeInsets.symmetric(
                                            horizontal: 10, vertical: 6),
                                        decoration: BoxDecoration(
                                          color: t['id'] ==
                                                  provider.browserAiTarget
                                              ? const Color(0xFFBA68C8)
                                                  .withValues(alpha: 0.25)
                                              : Colors.white
                                                  .withValues(alpha: 0.06),
                                          borderRadius:
                                              BorderRadius.circular(20),
                                          border: Border.all(
                                              color: t['id'] ==
                                                      provider.browserAiTarget
                                                  ? const Color(0xFFBA68C8)
                                                  : Colors.white.withValues(
                                                      alpha: 0.12)),
                                        ),
                                        child: Text(t['label'] ?? '',
                                            style: TextStyle(
                                                color: t['id'] ==
                                                        provider
                                                            .browserAiTarget
                                                    ? Colors.white
                                                    : Colors.white60,
                                                fontSize: 11)),
                                      ),
                                    ),
                                ],
                              ),
                            ),
                          ]),
                    ),
                  ),
                  // 前提条件の設定 (= 旧 AI 切替メニューから引き継ぎ)。
                  ListTile(
                    dense: true,
                    leading: const Icon(Icons.tune_rounded,
                        color: Color(0xFFBA68C8), size: 18),
                    title: Text(provider.t('ai.prefixTitle'),
                        style: const TextStyle(
                            color: Colors.white, fontSize: 13)),
                    trailing: const Icon(Icons.chevron_right_rounded,
                        color: Colors.white38, size: 18),
                    onTap: () {
                      Navigator.pop(sctx);
                      unawaited(_showBrowserAiPrefixDialog());
                    },
                  ),
                ],
                // Instagram だけは「開く画面」 (ホーム / DM / プロフィール) を
                //   その場のチップで選べるようにする (= ユーザー要望: 押して
                //   別画面を出すまでもない。 ここで一度に選べるように)。
                if (commandId == 'openInstagram')
                  StatefulBuilder(
                    builder: (igCtx, setIg) => Padding(
                      padding: const EdgeInsets.fromLTRB(16, 4, 12, 8),
                      child: Row(children: [
                        const Icon(Icons.camera_alt_rounded,
                            color: Color(0xFFE1306C), size: 18),
                        const SizedBox(width: 10),
                        Text(provider.t('insta.landingTitle'),
                            style: const TextStyle(
                                color: Colors.white, fontSize: 13)),
                        const SizedBox(width: 10),
                        Expanded(
                          // 横一列に並べる (= ユーザー要望: 折り返すと
                          // 見栄えが悪い)。
                          child: Row(
                            mainAxisAlignment: MainAxisAlignment.end,
                            children: [
                              for (final e in const [
                                ('home', 'insta.home'),
                                ('dm', 'insta.dm'),
                                ('profile', 'insta.profile'),
                              ])
