  /// Google 検索 ★ クリック時に表示するダイアログ。
  /// 名前 / アイコン / 色 / URL を選択して [作成] で動的ボタンを作る。
  /// 戻り値: 作成した _BookmarkButton (キャンセル時は null)。
  Future<_BookmarkButton?> _showCreateBookmarkButtonDialog({
    required String initialUrl,
    required String initialLabel,
  }) async {
    final provider = context.read<MindMapProvider>();
    final labelCtrl = TextEditingController(text: initialLabel);
    final urlCtrl = TextEditingController(text: initialUrl);
    IconData selectedIcon = _availableBookmarkIcons.first;
    Color selectedColor = _availableBookmarkColors.first;

    final result = await showDialog<_BookmarkButton>(
      context: context,
      barrierDismissible: true,
      builder: (dctx) {
        return StatefulBuilder(builder: (sctx, setS) {
          return AlertDialog(
            backgroundColor: const Color(0xFF22222E),
            shape:
                RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
            title: Row(children: [
              Container(
                width: 36,
                height: 36,
                decoration: BoxDecoration(
                  color: selectedColor.withValues(alpha: 0.2),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: selectedColor),
                ),
                child: Icon(selectedIcon, color: selectedColor, size: 22),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Text(provider.t('fav.addTitle'),
                    style: const TextStyle(
                        color: Colors.white,
