  /// ブックマークボタンの URL を内蔵 WebView (Google 検索ダイアログ) で開く。
  void _openBookmarkUrl(BuildContext ctx, MindMapProvider provider, String id) {
    final b = _bookmarkButtonsCache[id];
    if (b == null) {
      if (!mounted) return;
      _appSnack(ctx, SnackBar(
        backgroundColor: const Color(0xFFE57373),
        duration: const Duration(seconds: 2),
        content: Text(provider.t('fav.notFound')),
      ));
      return;
    }
    _openGoogleSearchDialog(
      ctx,
      provider,
      initialUrl: b.url,
      customTitle: b.label,
    );
  }

