  /// カスタムページボタン (customPage1〜5) の右クリック / 長押しメニュー。
  /// 「名前を変更」 「アイコンを変更」 「ページを削除」
  /// 「このボタンを配置から外す」 の最大 4 項目。
  /// ボトムシートとして表示 (= モバイル / デスクトップ共通)。
  Future<void> _showCustomPageContextMenu(
      BuildContext ctx, MindMapProvider provider, String commandId) async {
    final slotIdx = int.tryParse(commandId.substring('customPage'.length)) ?? 0;
    if (slotIdx < 1 || slotIdx > 5) return;
    final idx = slotIdx - 1;
    final cache = _customPagesCache[idx];
    final isEmpty = cache.isEmpty;
    // 押したボタンの近くに出す (= ユーザー要望: カスタムボタンの設定で
    // 開かれる画面は全てボタンの近くに)。 下から出るシートはやめた。
    final anchor = _customButtonAnchor();
    await showDialog<void>(
      context: ctx,
      barrierColor:
          Colors.black.withValues(alpha: anchor == null ? 0.5 : 0.25),
      builder: (sheetCtx) {
        return _positionNearAnchor(
          sheetCtx,
          anchor,
          Material(
          color: const Color(0xFF1E1E32),
          elevation: 12,
          borderRadius: BorderRadius.circular(14),
          clipBehavior: Clip.antiAlias,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Padding(
                padding: const EdgeInsets.only(
                    left: 16, right: 16, top: 12, bottom: 4),
                child: Row(children: [
                  Container(
                    width: 28,
                    height: 28,
                    decoration: BoxDecoration(
                      color: const Color(0xFFFFB347).withValues(alpha: 0.2),
                      borderRadius: BorderRadius.circular(6),
                      border: Border.all(color: const Color(0xFFFFB347)),
                    ),
                    child: Center(
                      child: Text(
                        '$slotIdx',
                        style: const TextStyle(
                            color: Color(0xFFFFB347),
                            fontSize: 13,
                            fontWeight: FontWeight.w700),
                      ),
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(provider.t('fav.pageSectionTitle'),
                            style: const TextStyle(
                                color: Colors.white54, fontSize: 11)),
                        Text(
                          isEmpty
                              ? provider.t('fav.unregistered')
                              : cache.label,
                          style: const TextStyle(
                              color: Colors.white,
                              fontSize: 15,
                              fontWeight: FontWeight.w700),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                        ),
                      ],
                    ),
                  ),
                ]),
              ),
              const Divider(color: Colors.white12, height: 8),
              if (isEmpty) ...[
                // 未登録: 案内文 + 「ボタンを配置から外す」
                Padding(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
                  child: Text(
                    provider.t('fav.pageEmptyHint'),
                    style: const TextStyle(color: Colors.white54, fontSize: 12),
                  ),
                ),
                ListTile(
                  leading: const Icon(Icons.remove_circle_outline_rounded,
                      color: Color(0xFFE57373)),
                  title: Text(provider.t('fav.removeFromLayout'),
                      style: const TextStyle(
                          color: Color(0xFFE57373),
                          fontSize: 14,
                          fontWeight: FontWeight.w600)),
                  subtitle: Text(
                    provider.t('fav.removeFromLayoutSub'),
                    style: const TextStyle(color: Colors.white38, fontSize: 11),
                  ),
                  onTap: () async {
                    Navigator.of(sheetCtx).pop();
                    await _removeCustomPageSlot(idx);
                  },
                ),
              ] else ...[
                ListTile(
                  leading:
                      const Icon(Icons.edit_rounded, color: Color(0xFF4FC3F7)),
                  title: Text(provider.t('drawer.rename'),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 14,
                          fontWeight: FontWeight.w600)),
                  onTap: () async {
                    Navigator.of(sheetCtx).pop();
                    await _renameCustomPage(idx, cache.label);
                  },
                ),
                ListTile(
                  leading: const Icon(Icons.palette_rounded,
                      color: Color(0xFF43B97F)),
                  title: Text(provider.t('icon.change'),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 14,
                          fontWeight: FontWeight.w600)),
                  onTap: () async {
                    Navigator.of(sheetCtx).pop();
                    await _pickCustomPageIcon(idx, cache.icon);
                  },
                ),
                ListTile(
                  leading: const Icon(Icons.delete_outline_rounded,
                      color: Color(0xFFE57373)),
                  title: Text(provider.t('page.deleteTitle'),
                      style: const TextStyle(
                          color: Color(0xFFE57373),
                          fontSize: 14,
                          fontWeight: FontWeight.w600)),
                  subtitle: Text(
                    provider.t('fav.pageDeleteSub'),
                    style: const TextStyle(color: Colors.white38, fontSize: 11),
                  ),
                  onTap: () async {
                    Navigator.of(sheetCtx).pop();
                    await _deleteCustomPage(idx);
                  },
                ),
                ListTile(
                  leading: const Icon(Icons.remove_circle_outline_rounded,
                      color: Color(0xFFFF9800)),
                  title: Text(provider.t('fav.removeFromLayout'),
                      style: const TextStyle(
                          color: Color(0xFFFF9800),
                          fontSize: 14,
                          fontWeight: FontWeight.w600)),
                  subtitle: Text(
                    provider.t('fav.removeSlotSub'),
                    style: const TextStyle(color: Colors.white38, fontSize: 11),
                  ),
                  onTap: () async {
                    Navigator.of(sheetCtx).pop();
                    await _removeCustomPageSlot(idx);
                  },
                ),
              ],
