  /// Stripe の決済ページを開く (デスクトップ)。 決済は外部ブラウザで行い、
  /// 完了後は Webhook を受けたサーバー側で権利を付ける設計。 サーバー未構築の
  /// 間は、 戻ってきたユーザーに状況を伝えるだけにする (勝手にプランを
  /// 上げると、 未決済でも Pro になってしまうため)。
  Future<void> _startStripeCheckout(
      MindMapProvider provider, String plan, bool yearly) async {
    final uid = provider.currentUid ?? '';
    final ok = await provider.billing.openStripeCheckout(
      planName: plan,
      yearly: yearly,
      appUserId: uid,
    );
    if (!mounted) return;
    if (ok) {
      // 決済完了までの猶予を見て何度か権利を取りに行く (Webhook 反映待ち)。
      for (final sec in const [8, 20, 40, 70, 120]) {
        Future.delayed(Duration(seconds: sec), () {
          if (!mounted) return;
          // ignore: discarded_futures
          provider.syncEntitlementFromServer();
        });
      }
    }
    _appSnack(
      context,
      SnackBar(
        content: Text(provider.t(
            ok ? 'paywall.stripeOpened' : 'paywall.stripeOpenFailed')),
        backgroundColor:
            ok ? const Color(0xFF43B97F) : const Color(0xFFE57373),
        duration: const Duration(seconds: 5),
      ),
    );
  }

  void _showPaywallDialog(MindMapProvider provider, {String? bodyOverride}) {
    showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E1E),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        title: Row(children: [
          const Icon(Icons.workspace_premium_rounded,
              color: Color(0xFFFFB347), size: 22),
          const SizedBox(width: 8),
          Expanded(
            child: Text(provider.t('paywall.title'),
                style: const TextStyle(
                    color: Colors.white,
                    fontSize: 16,
                    fontWeight: FontWeight.w700)),
          ),
        ]),
        content: SizedBox(
          width: 380,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(bodyOverride ?? provider.t('paywall.body'),
                  style: const TextStyle(
                      color: Colors.white70, fontSize: 13, height: 1.5)),
              const SizedBox(height: 12),
              // ── 有料プランで解禁される機能を Pro/Max で纏めて表示 (= ユーザー要望) ──
              _buildPlanFeatureSummary(provider),
              const SizedBox(height: 14),
              // ─── デスクトップの購入ボタン (Stripe 決済リンク) ───
              // Windows / Linux は RevenueCat SDK 非対応なので、 Stripe の
              // 決済ページをブラウザで開く。 client_reference_id に Firebase
              // UID を渡して購入者を特定する。
              if (_isDesktop && provider.billing.hasStripeLinks) ...[
                _buildStripePlanCards(provider,
                    onTapBefore: () => Navigator.of(ctx).pop()),
                const SizedBox(height: 10),
              ],
              // ─── クーポン入力ボタン ───
              // Pro 加入を求める画面で「コードを持っている → そっちで認証
              // したい」というユーザーフローに対応。タップで入力ダイアログ。
              Container(
                decoration: BoxDecoration(
                  color: const Color(0xFF4FC3F7).withValues(alpha: 0.08),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                      color: const Color(0xFF4FC3F7).withValues(alpha: 0.3)),
                ),
                child: InkWell(
                  borderRadius: BorderRadius.circular(8),
                  onTap: () {
                    Navigator.of(ctx).pop();
                    _showCouponEntryDialog(provider);
                  },
                  child: Padding(
                    padding: const EdgeInsets.all(10),
                    child: Row(children: [
                      const Icon(Icons.local_offer_rounded,
                          color: Color(0xFF4FC3F7), size: 16),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          provider.t('paywall.haveCoupon'),
                          style: const TextStyle(
                              color: Color(0xFF4FC3F7),
                              fontSize: 12,
                              fontWeight: FontWeight.w700),
                        ),
                      ),
                      const Icon(Icons.chevron_right_rounded,
                          color: Color(0xFF4FC3F7), size: 18),
                    ]),
                  ),
                ),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white60)),
          ),
          // 上に購入カードを出している時は重複するので隠す。
          if (!(_isDesktop && provider.billing.hasStripeLinks))
            ElevatedButton.icon(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFFFB347),
                  foregroundColor: Colors.black),
              onPressed: () {
                // ペイウォールを閉じて購入シートを開く
                Navigator.of(ctx).pop();
                _showPurchaseSheet(provider);
