  /// 購入シート内の 1 プラン行 (Pro/Max × 月額/年額)。
  Widget _buildPlanTile(
    MindMapProvider provider,
    BillingPackage pkg, {
    required bool disabled,
    required VoidCallback onTap,
  }) {
    final isMax = pkg.planName == BillingPlanName.max;
    final accent = isMax ? const Color(0xFFFFB347) : const Color(0xFF4FC3F7);
    final planLabel = isMax ? 'Max' : 'Pro';
    final periodLabel = pkg.isYearly
        ? provider.t('paywall.yearly')
        : provider.t('paywall.monthly');
    return Material(
      color: accent.withValues(alpha: 0.12),
      borderRadius: BorderRadius.circular(10),
      child: InkWell(
        borderRadius: BorderRadius.circular(10),
        onTap: disabled ? null : onTap,
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
          child: Row(children: [
            Icon(Icons.workspace_premium_rounded, color: accent, size: 20),
            const SizedBox(width: 10),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('$planLabel ・ $periodLabel',
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 14,
                          fontWeight: FontWeight.w700)),
                  const SizedBox(height: 2),
                  Text(pkg.priceString,
                      style: TextStyle(
                          color: accent,
                          fontSize: 13,
                          fontWeight: FontWeight.w600)),
                ],
              ),
            ),
            Icon(Icons.chevron_right_rounded,
                color: Colors.white.withValues(alpha: 0.5)),
          ]),
        ),
      ),
    );
  }

  /// クーポンコード入力ダイアログ。
  /// ユーザーがコードを入れて「適用」を押すと、Firestore 上のドキュメントを
  /// 検証して有効なら永続適用、無効ならエラーを表示する。
  void _showCouponEntryDialog(MindMapProvider provider) {
    final ctrl = TextEditingController();
    String? errorMsg;
    bool busy = false;

    showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setStateDialog) {
          // ── クーポンは Google ログインが前提 (= ユーザー要望) ──
          //    ログインしていなければ、 まずブラウザで認証してもらう。
          //    認証情報が入っていないビルドではこの入口は出さない。
          final needsGoogle =
              provider.canUseGoogleSignIn && !provider.googleSignedIn;

          Future<void> doSignIn() async {
            if (busy) return;
            setStateDialog(() {
              busy = true;
              errorMsg = provider.t('account.openingBrowser');
            });
            try {
              final who = await provider.signInWithGoogle();
              if (!ctx.mounted) return;
              setStateDialog(() {
                busy = false;
                errorMsg = who == null ? provider.t('account.cancelled') : null;
              });
            } catch (e) {
              if (!ctx.mounted) return;
              setStateDialog(() {
                busy = false;
                errorMsg = '$e';
              });
            }
          }

          Future<void> doApply() async {
            if (busy) return;
            // ログインしていなければ、 適用の前にログインを済ませる。
            if (provider.canUseGoogleSignIn && !provider.googleSignedIn) {
              await doSignIn();
              if (!ctx.mounted || !provider.googleSignedIn) return;
            }
            setStateDialog(() {
              busy = true;
              errorMsg = null;
            });
            final err = await provider.applyCoupon(ctrl.text);
            if (!ctx.mounted) return;
            if (err == null) {
              // 成功 → ダイアログを閉じて SnackBar 通知
              Navigator.of(ctx).pop();
              if (mounted) {
                _appSnack(
                  context,
                  SnackBar(
                    content: Text(provider.t('coupon.applied')),
                    backgroundColor: const Color(0xFF43B97F),
                  ),
                );
              }
            } else {
              setStateDialog(() {
                busy = false;
                errorMsg = err;
              });
            }
          }

          return AlertDialog(
            backgroundColor: const Color(0xFF1E1E1E),
            shape:
                RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
            title: Row(children: [
              const Icon(Icons.local_offer_rounded,
                  color: Color(0xFF4FC3F7), size: 20),
              const SizedBox(width: 8),
              Text(provider.t('coupon.title'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 15,
                      fontWeight: FontWeight.w700)),
            ]),
            content: SizedBox(
              width: 360,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(provider.t('coupon.hint'),
                      style:
                          const TextStyle(color: Colors.white54, fontSize: 11)),
                  // ── ログイン状態の案内 (= ユーザー要望: クーポン適用時は
                  //    Google アカウントへのログインを求める) ──
                  if (provider.canUseGoogleSignIn) ...[
                    const SizedBox(height: 12),
                    Container(
                      padding: const EdgeInsets.all(10),
                      decoration: BoxDecoration(
                        color: const Color(0xFF15151F),
                        borderRadius: BorderRadius.circular(8),
                        border: Border.all(
                            color: needsGoogle
                                ? const Color(0xFFFFB74D)
                                : const Color(0xFF9CCC65),
                            width: 1),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(children: [
                            Icon(
                                needsGoogle
                                    ? Icons.lock_person_rounded
                                    : Icons.verified_user_rounded,
                                size: 16,
                                color: needsGoogle
                                    ? const Color(0xFFFFB74D)
                                    : const Color(0xFF9CCC65)),
                            const SizedBox(width: 8),
                            Expanded(
                              child: Text(
                                needsGoogle
                                    ? provider.t('coupon.errNeedGoogle')
                                    : (provider.googleEmail.isEmpty
                                        ? provider.t('account.signedIn')
                                        : provider.googleEmail),
                                style: TextStyle(
                                    color: needsGoogle
                                        ? const Color(0xFFFFB74D)
                                        : Colors.white,
                                    fontSize: 12),
                              ),
                            ),
                          ]),
                          if (needsGoogle) ...[
                            const SizedBox(height: 6),
                            Text(provider.t('coupon.googleWhy'),
                                style: const TextStyle(
                                    color: Colors.white54,
                                    fontSize: 11,
                                    height: 1.5)),
                            const SizedBox(height: 8),
                            SizedBox(
                              width: double.infinity,
                              child: ElevatedButton.icon(
                                style: ElevatedButton.styleFrom(
                                    backgroundColor: const Color(0xFF1A2030),
                                    foregroundColor: Colors.white,
                                    side: const BorderSide(
                                        color: Color(0xFF4FC3F7), width: 1)),
                                icon: const Icon(Icons.account_circle_rounded,
                                    size: 16, color: Color(0xFF4FC3F7)),
                                label: Text(provider.t('coupon.signInButton'),
                                    style: const TextStyle(
                                        color: Color(0xFF4FC3F7),
                                        fontSize: 12)),
                                onPressed: busy ? null : doSignIn,
                              ),
                            ),
                          ],
                        ],
                      ),
                    ),
                  ],
                  const SizedBox(height: 12),
                  TextField(
                    controller: ctrl,
                    autofocus: true,
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 16,
                        letterSpacing: 2,
                        fontWeight: FontWeight.w600),
                    textCapitalization: TextCapitalization.characters,
                    textInputAction: TextInputAction.go,
                    onSubmitted: (_) => doApply(),
                    decoration: InputDecoration(
                      labelText: provider.t('coupon.label'),
                      labelStyle:
                          const TextStyle(color: Colors.white54, fontSize: 12),
                      filled: true,
                      fillColor: Colors.white.withValues(alpha: 0.05),
                      border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(8),
                          borderSide: BorderSide.none),
                    ),
                  ),
                  if (errorMsg != null) ...[
                    const SizedBox(height: 10),
                    Text(errorMsg!,
                        style: const TextStyle(
                            color: Color(0xFFFF6B6B), fontSize: 12)),
                  ],
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: busy ? null : () => Navigator.of(ctx).pop(),
                child: Text(provider.t('btn.cancel'),
                    style: const TextStyle(color: Colors.white60)),
              ),
              ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF4FC3F7),
                    foregroundColor: Colors.black),
                onPressed: busy ? null : doApply,
                icon: busy
                    ? const SizedBox(
                        width: 14,
                        height: 14,
                        child: CircularProgressIndicator(
                            strokeWidth: 2, color: Colors.black))
                    : const Icon(Icons.check_rounded, size: 16),
                label: Text(provider.t('coupon.apply')),
              ),
            ],
          );
        },
      ),
    );
  }

  /// 開発者モード専用: クーポン管理画面 (生成 + 一覧 + 削除)
  ///
  /// 開発者がクーポンを発行する流れ:
  /// 1. 「新規クーポンを生成」をタップ
  /// 2. 割引率 (0-100%)、有効期限、最大使用回数、メモを入力
  /// 3. 生成 → ランダム 8 文字コードが Firestore に保存され画面に表示
  /// 4. ユーザーに配布
  ///
  /// 既存クーポンは下に一覧表示され、コードコピー / 削除ができる。
  /// まとめて消す前の確認。
  Future<bool?> _confirmCouponBulkDelete(BuildContext ctx, int n) {
    return showDialog<bool>(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: const Text('選んだコードを消しますか？',
            style: TextStyle(color: Colors.white, fontSize: 15)),
        content: Text('$n 件を消します。 元には戻せません。',
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, false),
            child:
                const Text('やめる', style: TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFE57373),
                foregroundColor: Colors.white),
            onPressed: () => Navigator.pop(dctx, true),
            child: const Text('消す'),
          ),
        ],
      ),
    );
  }

  /// まとめる前の確認。
  Future<bool?> _confirmCouponMerge(BuildContext ctx, int n) {
    return showDialog<bool>(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: const Text('1 つにまとめますか？',
            style: TextStyle(color: Colors.white, fontSize: 15)),
        content: Text(
            '$n 件の残り人数を足した新しいコードを作り、 元のコードは消します。\n'
            '期限とプランは、 選んだ中で一番長い / 強い物に合わせます。',
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, false),
            child:
                const Text('やめる', style: TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF4FC3F7),
                foregroundColor: Colors.black),
            onPressed: () => Navigator.pop(dctx, true),
            child: const Text('まとめる'),
          ),
        ],
      ),
    );
  }

  void _showCouponManagerDialog(BuildContext ctx, MindMapProvider provider) {
    // ── 状態は StatefulBuilder の builder の「外側」で保持する ──
    // 旧実装では builder 内のローカル変数に置いていたため、setD() で
    // 再ビルドされるたびに変数がリセットされ、毎フレーム listCoupons() が
    // 再発火 → 永遠にローディング状態のままになるバグがあった (2026-05)。
    List<Map<String, dynamic>>? coupons;
    bool loading = true;
    bool _firstLoadKicked = false;
    // ── まとめて選ぶ (= ユーザー要望: Ctrl / Shift で複数選択) ──
    final selected = <String>{};
    int? lastTapIndex;
    // ── 絞り込み (= ユーザー要望: アカウント名で検索、 種類ごとのタブ) ──
    final searchCtrl = TextEditingController();
    var searchText = '';
    var planTab = 'all'; // all | dev | max | pro

    // ── クーポン (Firestore) と Dev コード (代行サーバー) をまとめて読む ──
    //   置き場所は違うが、 使う側から見ればどちらも「配る引き換えコード」
    //   なので、 1 つの一覧に並べる (= ユーザー要望: 同じ画面で発行する)。
    Future<List<Map<String, dynamic>>> loadAllCodes() async {
      // 3 つを同時に取りに行く (= ユーザー要望: 一覧が出るまでが遅い)。
      // 順番に待つと 3 往復分かかっていた。
      final results = await Future.wait<dynamic>([
        provider.listCoupons(),
        provider.listDevCodes(),
        provider.listAllUsers(),
      ]);
      final list = results[0] as List<Map<String, dynamic>>;
      final devs = results[1] as List<Map<String, dynamic>>;
      final users = results[2] as List<Map<String, dynamic>>;
      // コード → 使っている人の名前 (= ユーザー要望: どのアカウントが
      // そのライセンスを使っているか知りたい)。
      final byCode = <String, List<String>>{};
      for (final u in users) {
        final code = '${u['couponCode'] ?? ''}'.trim().toUpperCase();
        if (code.isEmpty) continue;
        final name = '${u['displayName'] ?? ''}'.trim();
        final uid = '${u['uid'] ?? ''}';
        byCode
            .putIfAbsent(code, () => <String>[])
            .add(name.isEmpty ? '(名前なし) $uid' : name);
      }
      final merged = <Map<String, dynamic>>[
        for (final d in devs)
          {
            'code': '${d['code'] ?? ''}',
            'discountPercent': 100,
            'maxUses': (d['maxUses'] as num?)?.toInt() ?? 0,
            'currentUses': (d['currentUses'] as num?)?.toInt() ?? 0,
            'expiresAt': ((d['expiresAt'] as num?)?.toInt() ?? 0) > 0
                ? DateTime.fromMillisecondsSinceEpoch(
                        ((d['expiresAt'] as num).toInt()) * 1000,
                        isUtc: true)
                    .toIso8601String()
                : '',
            'validMonthsAfterUse': (d['months'] as num?)?.toInt() ?? 0,
            'note': '${d['note'] ?? ''}',
            'plan': 'dev',
            'isDev': true,
            'users': byCode['${d['code'] ?? ''}'.toUpperCase()] ??
                const <String>[],
          },
        for (final c in list)
          {
            ...c,
            'users':
                byCode['${c['code'] ?? ''}'.toUpperCase()] ?? const <String>[],
          },
      ];
      return merged;
    }

    showDialog<void>(
      context: ctx,
      builder: (dctx) => StatefulBuilder(
        builder: (sctx, setD) {
          // 初回のみリストを読み込む。再ビルド時には絶対に再発火しない。
          if (!_firstLoadKicked) {
            _firstLoadKicked = true;
            loadAllCodes().then((list) {
              if (sctx.mounted) {
                setD(() {
                  coupons = list;
                  loading = false;
                });
              }
            }).catchError((e) {
              debugPrint('listCoupons UI error: $e');
              if (sctx.mounted) {
                setD(() {
                  coupons = [];
                  loading = false;
                });
              }
            });
          }

          Future<void> openCreateForm() async {
            final discountCtrl = TextEditingController(text: '100');
            final maxUsesCtrl = TextEditingController(text: '0');
            final validMonthsCtrl = TextEditingController(text: '0');
            final noteCtrl = TextEditingController();
            DateTime? expiry;
            bool busy = false;
            // クーポンが解放するプラン (Pro / Max) の選択。 既定は Pro。
            // Max を選ぶと月 25GB up / 100GB dl の上位プランを解放する。
            SubscriptionPlan planChoice = SubscriptionPlan.pro;

            await showDialog<void>(
              context: sctx,
              builder: (cctx) => StatefulBuilder(
                builder: (cctx, setCD) {
                  Future<void> doGenerate() async {
                    if (busy) return;
                    final discount =
                        _parseIntLoose(discountCtrl.text) ?? 100;
                    final maxUses = _parseIntLoose(maxUsesCtrl.text) ?? 0;
                    final validMonths =
                        _parseIntLoose(validMonthsCtrl.text) ?? 0;
                    setCD(() => busy = true);
                    String? code;
                    String? errorDetail;
                    try {
                      // Dev は代行サーバー (Worker) が正本。 Firestore の
                      //   クーポンに書いてもサーバーが知らず、 AI を呼ぶ時に
                      //   残高不足で断られてしまうため、 発行先を分ける。
                      code = planChoice == SubscriptionPlan.dev
                          ? await provider.createDevCode(
                              months: validMonths.clamp(0, 120),
                              maxUses: maxUses,
                              expiresAt: expiry,
                              note: noteCtrl.text.trim(),
                            )
                          : await provider.createCoupon(
                              discountPercent: discount.clamp(0, 100),
                              expiresAt: expiry,
                              validMonthsAfterUse: validMonths.clamp(0, 120),
                              maxUses: maxUses,
                              note: noteCtrl.text.trim(),
                              plan: planChoice,
                            );
                    } catch (e) {
                      errorDetail =
                          e.toString().replaceFirst('Exception: ', '');
                    }
                    if (!cctx.mounted) return;
                    Navigator.of(cctx).pop();
                    if (code != null) {
                      // 一覧を再読み込み
                      final list = await loadAllCodes();
                      if (sctx.mounted) {
                        setD(() {
                          coupons = list;
                        });
                      }
                      if (mounted) {
                        _appSnack(
                          context,
                          SnackBar(
                            content: Text(
                                '${provider.t('dev.coupon.created')}$code'),
                            backgroundColor: const Color(0xFF43B97F),
                            duration: const Duration(seconds: 4),
                          ),
                        );
                      }
                    } else {
                      // 失敗: 詳細メッセージを長めのSnackBarで通知
                      // (Firestore ルール / 権限 / 認証期限切れ等)
                      if (mounted) {
                        final msg =
                            errorDetail ?? 'クーポン生成に失敗しました。Firebase接続を確認してください。';
                        _appSnack(
                          context,
                          SnackBar(
                            content: Text(
                                context
                                    .read<MindMapProvider>()
                                    .t('coupon.genFailed')
                                    .replaceFirst('{err}', msg),
                                style: const TextStyle(fontSize: 12)),
                            backgroundColor: const Color(0xFFFF6B6B),
                            duration: const Duration(seconds: 8),
                            action: SnackBarAction(
                              label:
                                  context.read<MindMapProvider>().t('btn.copy'),
                              textColor: Colors.white,
                              onPressed: () {
                                Clipboard.setData(ClipboardData(text: msg));
                              },
                            ),
                          ),
                        );
                      }
                    }
                  }

                  return AlertDialog(
                    backgroundColor: const Color(0xFF1E1E1E),
                    shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(14)),
                    title: Text(provider.t('dev.coupon.create'),
                        style: const TextStyle(
                            color: Colors.white,
                            fontSize: 15,
                            fontWeight: FontWeight.w700)),
                    content: SizedBox(
