  /// 入力 URL を判定してギャラリーへ動画を取り込む。 プレイリスト / チャンネル
  /// URL が見つかればスクレイプ取得、 それ以外は動画リンク (複数可) として
  /// まとめて追加する。
  /// バッチで取り込む要素がギャラリーの枠 (横×縦, 既定 5×5=25) を超える時に
  /// 「拡張して追加するか」 を確認する (= ユーザー要望: 25 要素を超えるものが
  /// 一度に入ろうとしたら確認を出す)。 戻り値 true=追加可 (必要なら段数を拡張
  /// 済み)、 false=中止。 表紙にまとまる取り込みは表示上 1 件なので発火しない。
  void _showGalleryPlaceLimitSnack(MindMapProvider provider) {
    if (!mounted) return;
    _appSnack(
      context,
      SnackBar(
        content: Text(provider.t('shelf.placeLimitExceeded')),
        backgroundColor: Colors.redAccent,
        duration: const Duration(seconds: 3),
      ),
    );
  }

  Future<bool> _confirmGalleryExpand(
      BuildContext context, MindMapProvider provider, int incomingCount) async {
    if (provider.currentPage.pageType != 'bookshelf') return true;
    if (incomingCount <= 0) return true;
    if (!provider.canPlaceShelfItems(incomingCount)) {
      _showGalleryPlaceLimitSnack(provider);
      return false;
    }
    final cols = provider.shelfGridCols
        .clamp(1, MindMapProvider.kShelfMaxGridCols)
        .toInt();
    final cap = provider.shelfGridCapacity();
    final existing = provider.shelfVisibleCount();
    if (existing + incomingCount <= cap) return true;
    if (!mounted) return true;
    final total = existing + incomingCount;
    var nextCols = cols;
    var needRows = (total / nextCols).ceil();
    if (needRows > MindMapProvider.kShelfMaxGridRows) {
      nextCols = (total / MindMapProvider.kShelfMaxGridRows)
          .ceil()
          .clamp(cols, MindMapProvider.kShelfMaxGridCols)
          .toInt();
      needRows = (total / nextCols).ceil();
    }
    if (needRows > MindMapProvider.kShelfMaxGridRows ||
        nextCols > MindMapProvider.kShelfMaxGridCols) {
      _showGalleryPlaceLimitSnack(provider);
      return false;
    }
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Row(children: [
          Icon(Icons.grid_view_rounded, color: Color(0xFFFFB347), size: 20),
          SizedBox(width: 10),
          Text(context.read<MindMapProvider>().t('grid.expandConfirm'),
              style: TextStyle(color: Colors.white, fontSize: 16)),
        ]),
        content: Text(
          '$incomingCount 件は現在の枠 ($cap マス) を超えます。\n'
          'グリッドを拡張して追加しますか？',
          style: const TextStyle(color: Colors.white70, fontSize: 13),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, false),
            child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFFFB347),
                foregroundColor: Color(0xFF10241F),),
            onPressed: () => Navigator.pop(dctx, true),
            child: Text(context.read<MindMapProvider>().t('grid.expandAdd'),
                style: const TextStyle(color: Colors.black)),
          ),
        ],
      ),
    );
    if (ok == true) {
      provider.setShelfGrid(
          cols: nextCols == cols ? null : nextCols, rows: needRows);
      return true;
    }
    return false;
  }

  /// ギャラリーの表紙 (複数動画をまとめた格納コンテナ) タップ時のメニュー。
  /// いきなり展開/格納せず「編集 / 展開・格納 / 削除」 を選ばせる
  /// (= ユーザー要望: 表紙を押すといきなりは開かず項目が出るように)。
  void _showBookshelfCoverMenu(MindMapNode node) {
    final provider = context.read<MindMapProvider>();
    final nodeMap = provider.currentPage.nodes;
    final memberIds = (node.containedNodeIds ?? const <String>[])
        .where((id) => nodeMap.containsKey(id))
        .toList();
    // メンバーが 1 つでも表示されていれば「展開中」。
    final expanded =
        memberIds.any((id) => nodeMap[id]?.hiddenInContainer == null);

    Widget item({
      required IconData icon,
      required Color color,
      required String label,
      required VoidCallback onTap,
    }) {
      return ListTile(
        dense: true,
        leading: Icon(icon, color: color, size: 22),
        title: Text(label,
            style: const TextStyle(color: Colors.white, fontSize: 14)),
        onTap: onTap,
      );
    }

    showDialog<void>(
      context: context,
      builder: (dctx) => Dialog(
        backgroundColor: const Color(0xFF1E1E32),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 320),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 14, 16, 6),
                child: Row(children: [
                  const Icon(Icons.video_library_rounded,
                      color: Color(0xFFFFB347), size: 20),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      node.title.isEmpty ? '📺' : node.title,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 14,
                          fontWeight: FontWeight.w700),
                    ),
                  ),
                ]),
              ),
              const Divider(color: Colors.white12, height: 1),
              item(
                icon: Icons.edit_rounded,
                color: const Color(0xFF4FC3F7),
                label: provider.t('cover.edit'),
                onTap: () {
                  Navigator.pop(dctx);
                  _startInlineTitleEdit(context, node);
                },
              ),
              item(
                icon: expanded
                    ? Icons.unfold_less_rounded
                    : Icons.unfold_more_rounded,
                color: const Color(0xFF43B97F),
                label: provider
                    .t(expanded ? 'cover.collapse' : 'cover.expand')
                    .replaceFirst('{n}', '${memberIds.length}'),
                onTap: () {
                  Navigator.pop(dctx);
                  provider.toggleBookshelfCover(node.id);
                },
              ),
              item(
                icon: Icons.delete_outline_rounded,
                color: const Color(0xFFEF5350),
                label: provider.t('cover.delete'),
                onTap: () async {
                  Navigator.pop(dctx);
                  final ok = await showDialog<bool>(
                    context: context,
                    builder: (cctx) => AlertDialog(
                      backgroundColor: const Color(0xFF1E1E32),
                      title: Text(provider.t('cover.delete'),
                          style: const TextStyle(
                              color: Colors.white, fontSize: 15)),
                      content: Text(
                        provider
                            .t('cover.deleteConfirm')
                            .replaceFirst('{n}', '${memberIds.length}'),
                        style: const TextStyle(
                            color: Colors.white70, fontSize: 13),
                      ),
                      actions: [
                        TextButton(
                          onPressed: () => Navigator.pop(cctx, false),
                          child: Text(provider.t('btn.cancel'),
                              style: const TextStyle(color: Colors.white54)),
                        ),
                        ElevatedButton(
                          style: ElevatedButton.styleFrom(
                              backgroundColor: const Color(0xFFEF5350),
                              foregroundColor: Colors.white),
                          onPressed: () => Navigator.pop(cctx, true),
                          child: Text(provider.t('cover.delete')),
                        ),
                      ],
                    ),
                  );
                  if (ok == true && mounted) {
                    // deleteNodes はコンテナのメンバーも一緒に削除する。
                    provider.deleteNodes({node.id});
                  }
                },
              ),
              const SizedBox(height: 6),
            ],
          ),
        ),
      ),
    );
  }

