  Future<void> _runBookshelfImport(
      BuildContext context, MindMapProvider provider, String raw,
      {List<int>? cell}) async {
    var tokens = raw.split(RegExp(r'\s+')).where((s) => s.isNotEmpty).toList();
    if (tokens.isEmpty) return;
    // プレイリスト / チャンネル URL が含まれていれば、 最初の 1 件を取得。
    for (final url in tokens) {
      final playlistId = _extractPlaylistId(url);
      if (playlistId != null) {
        final videoId = NodeWidget.extractVideoId(url);
        // ── Mix (RD…) / ウォッチリスト (WL) / 高評価 (LL) ──
        // /playlist ページが無く一覧を取得できない → 「視聴中の動画のみ
        // 埋め込むか」 を確認する (= ユーザー要望: ミックスリストは取得
        // できない旨が分かるように)。
        if (_unfetchableListIdOf(url) != null) {
          if (videoId == null) {
            _appSnack(
                context,
                SnackBar(
                  content: Text(provider.t('embed.mixNoVideo')),
                  backgroundColor: Colors.redAccent,
                  duration: const Duration(seconds: 3),
                ));
            return;
          }
          final ok = await _confirmMixListSingleEmbed(provider);
          if (ok != true || !mounted) return;
          // 視聴中の動画のみを単一動画として取り込む (下の動画リンク処理へ)。
          tokens = [_stripListParamKeepTime(url)];
          break;
        }
        // ── 通常の再生リスト視聴中 (watch?v=…&list=…) ──
        // 「視聴中の動画のみ / リスト全体」 の選択を出す (= ユーザー要望:
        // プレイリスト視聴中に埋め込みボタンを押したら選択画面が出るように)。
        if (videoId != null) {
          final choice = await _askEmbedThisOrWholeList(provider);
          if (choice == null || !mounted) return;
          if (choice == 'one') {
            tokens = [_stripListParamKeepTime(url)];
            break;
          }
        }
        _loadBookshelfVideos(provider, playlistId: playlistId, cell: cell);
        return;
      }
      final channelInfo = _extractChannelInfo(url);
      if (channelInfo != null) {
        _pickChannelMode().then((mode) {
          if (mode == null || !mounted) return;
          provider.setChannelMode(mode);
          _loadBookshelfVideos(provider,
              playlistId: channelInfo.$1,
              customUrl: channelInfo.$2,
              isChannel: true,
              channelMode: mode,
              cell: cell);
        });
        return;
      }
    }
    // 残りは「動画リンク」 扱い: YouTube は ID を集めて一括追加、
    //   それ以外のリンクは 1 タイルずつ追加する。
    if (!await _confirmGalleryExpand(context, provider, tokens.length)) return;
    final ids = <String>[];
    final titles = <String>[];
    int linkK = 0;
    for (final url in tokens) {
      final vid = NodeWidget.extractVideoId(url);
      if (vid != null && vid.isNotEmpty) {
        ids.add(vid);
        titles.add('');
      } else {
        provider.addVideoToBookshelf(url,
            cell: cell == null ? null : [cell[0] + linkK, cell[1]]);
        linkK++;
      }
    }
    if (ids.isNotEmpty) {
      final linkOffset = linkK;
      () async {
        final before = provider.currentPage.nodes.keys.toSet();
        final added = provider.addVideosToBookshelf(ids, titles,
            cell: cell == null ? null : [cell[0] + linkOffset, cell[1]]);
        // 空白区切りで複数動画 URL を取り込んだ場合も、プレイリスト/
        // チャンネル取り込みと同じく 1 つの表紙ブロックへまとめる。
        final newIds = provider.currentPage.nodes.keys
            .where((id) => !before.contains(id))
            .toList(growable: false);
        if (newIds.length > 1) {
          provider.createBookshelfCover(
            newIds,
            '',
            cell: cell == null ? null : [cell[0] + linkOffset, cell[1]],
          );
        }
        if (mounted) {
          _appSnack(
            context,
            SnackBar(
              content: Text(provider
                  .t('bookshelf.added')
                  .replaceAll('{n}', added.toString())),
              backgroundColor: const Color(0xFF43B97F),
              duration: const Duration(seconds: 2),
            ),
          );
        }
        // 動画タイトルを oEmbed で補完 (= ユーザー要望: 埋め込んだ動画は
        // 動画タイトルが入るように)。
        _backfillMissingTitlesViaOEmbed(provider);
      }();
    } else if (linkK > 0) {
      // リンクだけ追加した場合も、 YouTube リンクならタイトルを補完する。
      _backfillMissingTitlesViaOEmbed(provider);
    }
  }

  /// ギャラリー用にチャンネル / プレイリストの動画を DOM スクレイプで取得して、
  /// 親ノードや接続線を作らずフラットにギャラリーへ追加する
  /// (_loadPlaylistVideos のギャラリー版)。
  void _loadBookshelfVideos(MindMapProvider provider,
      {required String playlistId,
      String? customUrl,
      bool isChannel = false,
      String? channelMode,
      List<int>? cell}) {
    final List<String> urls = [];
    if (customUrl != null) {
      final base = customUrl.replaceAll(RegExp(r'/videos$'), '');
      final mode = channelMode ?? 'videos';
      if (isChannel) {
        if (mode == 'videos' || mode == 'both') urls.add('$base/videos');
        if (mode == 'shorts' || mode == 'both') urls.add('$base/shorts');
      } else {
        urls.add(customUrl);
      }
    } else {
      urls.add('https://m.youtube.com/playlist?list=$playlistId');
    }
    if (urls.isEmpty) return;

    void onResults(List<String> videoIds, List<String> titles,
        String? pageTitle, List<int> viewCounts) {
      List<String> ids = videoIds;
      List<String> tts = titles;
      if (isChannel) {
        final filtered = provider.filterChannelVideos(videoIds, titles,
            viewCounts: viewCounts.isNotEmpty ? viewCounts : null);
        ids = filtered.$1;
        tts = filtered.$2;
      }
      () async {
        if (!await _confirmGalleryExpand(context, provider, ids.length)) return;
        final before = provider.currentPage.nodes.keys.toSet();
        final added = provider.addVideosToBookshelf(ids, tts, cell: cell);
        // = ユーザー要望: プレイリスト/チャンネルから取り込んだ動画は 1 つの
        //   「表紙ブロック」 にまとめ、 クリックで格納/展開できるようにする。
        final newIds = provider.currentPage.nodes.keys
            .where((k) => !before.contains(k))
            .toList();
        if (newIds.length > 1) {
          provider.createBookshelfCover(newIds, pageTitle ?? '', cell: cell);
        }
        if (mounted) {
          _appSnack(
            context,
            SnackBar(
              content: Text(provider
                  .t('bookshelf.added')
                  .replaceAll('{n}', added.toString())),
              backgroundColor: const Color(0xFF43B97F),
              duration: const Duration(seconds: 2),
            ),
          );
        }
        _backfillMissingTitlesViaOEmbed(provider);
      }();
    }

    if (_isDesktop) {
      showDialog(
        context: context,
        barrierColor: Colors.black.withValues(alpha: 0.75),
        builder: (_) => Dialog(
          backgroundColor: Colors.transparent,
          insetPadding:
              const EdgeInsets.symmetric(horizontal: 60, vertical: 40),
          child: ClipRRect(
            borderRadius: BorderRadius.circular(16),
            child: SizedBox(
              width: 800,
              height: 550,
              child: _WindowsPlaylistExtractSheet(
                urls: urls,
                playlistId: playlistId,
                extractPageTitle: isChannel,
                onResults: onResults,
              ),
            ),
          ),
        ),
      );
    } else {
      showModalBottomSheet(
        context: context,
        isScrollControlled: true,
        backgroundColor: Colors.black,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
        ),
        builder: (_) => _PlaylistExtractSheet(
          urls: urls,
          playlistId: playlistId,
          extractPageTitle: isChannel,
          onResults: onResults,
        ),
      );
    }
  }

  void _loadPlaylistVideos(
      String playlistId, MindMapNode parentNode, MindMapProvider provider,
      {String? customUrl,
      bool isChannel = false,
      String? channelMode,
      String? originalUrl}) {
    // ── 親ノードに元のハイパーリンクを付与 (= ユーザー要望: YouTube の
    //    チャンネルやリストの動画を取得する場合、 親ノードに元のリンクを
    //    含める) ──
    // originalUrl (= ユーザーが開いていた / 入力した URL) を最優先で使い、
    //   無ければ customUrl (チャンネル) / playlist URL から復元する。
    final linkForParent = (originalUrl != null && originalUrl.isNotEmpty)
        ? originalUrl
        : (customUrl != null
            ? customUrl.replaceAll(RegExp(r'/videos$'), '')
            : 'https://www.youtube.com/playlist?list=$playlistId');
    if (linkForParent.isNotEmpty) {
      provider.updateNodeLink(parentNode.id, linkForParent);
    }
    // 読み込むURLリストを作る
    // - プレイリスト: 1つだけ
    // - チャンネル: channelMode に応じて /videos と /shorts を組み立て
    final List<String> urls = [];
    if (customUrl != null) {
      // /videos で終わっていなければ追加
      final base = customUrl.replaceAll(RegExp(r'/videos$'), '');
      final mode = channelMode ?? 'videos';
      if (isChannel) {
        if (mode == 'videos' || mode == 'both') urls.add('$base/videos');
        if (mode == 'shorts' || mode == 'both') urls.add('$base/shorts');
      } else {
        urls.add(customUrl);
      }
    } else {
      urls.add('https://m.youtube.com/playlist?list=$playlistId');
    }
    if (urls.isEmpty) return;

    void onResults(List<String> videoIds, List<String> titles,
        String? pageTitle, List<int> viewCounts) {
      // チャンネル名が取得できて、親ノードのタイトルが空ならチャンネル名をセット
      if (isChannel && pageTitle != null && pageTitle.isNotEmpty) {
        final current = provider.nodes[parentNode.id];
        if (current != null && current.title.trim().isEmpty) {
          provider.updateNodeTitle(parentNode.id, pageTitle);
        }
      }

      // フィルターを適用
      List<String> filteredIds = videoIds;
      List<String> filteredTitles = titles;
      if (isChannel) {
        final filtered = provider.filterChannelVideos(videoIds, titles,
            viewCounts: viewCounts.isNotEmpty ? viewCounts : null);
        filteredIds = filtered.$1;
        filteredTitles = filtered.$2;
      }

      // チャンネル動画キューを登録（自動補充用）
      if (isChannel) {
        provider.registerChannelQueue(
            parentNode.id, filteredIds, filteredTitles);
      }

      // 自動削除モードONなら最初のN件だけ表示
      int batchSize = 5;
      if (isChannel && provider.autoDeleteWatched) {
        batchSize = provider.unwatchedLimit;
      }

      // 親ノード (チャンネルノード / プレイリスト親) の右側に動画を展開する。
      // モバイルの動画サムネイルは大きめに描画される (16:9 比率) ため、
      // 親ノードと子動画サムネイルを十分離して重ならないようにする。
      // 親ノードの幅に関わらず、最低 250px の水平距離を確保する。
      final parentW = parentNode.width;
      final basePos = Offset(
          parentNode.position.dx + parentW + 250, parentNode.position.dy);
      final result = provider.addPlaylistNodes(
        playlistId,
        filteredIds,
        filteredTitles,
        basePos,
        parentNodeId: parentNode.id,
        startIndex: 0,
        batchSize: batchSize,
      );
      final pId = result.$1;
      final remaining = result.$2;
      final loadMoreId = result.$3;
      final nextStart = result.$4;
      if (remaining > 0 && loadMoreId != null) {
        _playlistLoadMoreInfo[loadMoreId] = _PlaylistLoadMoreData(
          playlistId: playlistId,
          videoIds: filteredIds,
          titles: filteredTitles,
          basePos: basePos,
          nextStart: nextStart,
          parentId: pId,
        );
        // 再起動後も「次のN件を表示」が機能するように永続化。
        _saveLoadMoreInfo();
      }

      // 抽出時にタイトルが取れなかった動画について oEmbed で補完
      // （DOMからの取得は非ログイン状態だと失敗することがある）
      _backfillMissingTitlesViaOEmbed(provider);
    }

    final sheet = _PlaylistExtractSheet(
      urls: urls,
      playlistId: playlistId,
      extractPageTitle: isChannel,
      onResults: onResults,
    );

    if (_isDesktop) {
      showDialog(
        context: context,
        barrierColor: Colors.black.withValues(alpha: 0.75),
        builder: (_) => Dialog(
          backgroundColor: Colors.transparent,
          insetPadding:
              const EdgeInsets.symmetric(horizontal: 60, vertical: 40),
          child: ClipRRect(
            borderRadius: BorderRadius.circular(16),
            child: SizedBox(
              width: 800,
              height: 550,
              child: _WindowsPlaylistExtractSheet(
                urls: urls,
                playlistId: playlistId,
                extractPageTitle: isChannel,
                onResults: onResults,
              ),
            ),
          ),
        ),
      );
    } else {
      showModalBottomSheet(
        context: context,
        isScrollControlled: true,
        backgroundColor: Colors.black,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
        ),
        builder: (_) => sheet,
      );
    }
  }

  /// `_playlistLoadMoreInfo` を SharedPreferences に保存する。
  ///
  /// プレイリスト / チャンネルから抽出した動画リストを 5 件ずつ展開する際に
  /// 残り情報 (videoIds / titles / nextStart / 親ノード ID …) を保持して
  /// いるが、これはメモリ上の Map のみで、アプリ再起動や別マップ往復で
  /// State が破棄されると失われ、「次の N 件を表示」ノードを押しても無
  /// 反応 (= `data == null` で即 return) になる。本メソッドで永続化する。
  Future<void> _saveLoadMoreInfo() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      if (_playlistLoadMoreInfo.isEmpty) {
        await prefs.remove('playlistLoadMoreInfo');
        return;
      }
      final m = <String, dynamic>{};
      for (final e in _playlistLoadMoreInfo.entries) {
        m[e.key] = {
          'playlistId': e.value.playlistId,
          'videoIds': e.value.videoIds,
          'titles': e.value.titles,
          'bx': e.value.basePos.dx,
          'by': e.value.basePos.dy,
          'nextStart': e.value.nextStart,
          'parentId': e.value.parentId,
        };
      }
      await prefs.setString('playlistLoadMoreInfo', jsonEncode(m));
    } catch (e) {
      debugPrint('saveLoadMoreInfo failed: $e');
    }
  }

  /// `_playlistLoadMoreInfo` を SharedPreferences から復元する。
  /// `_saveLoadMoreInfo` の対。失敗時は黙って空のまま続行する。
  Future<void> _loadLoadMoreInfo() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString('playlistLoadMoreInfo');
      if (raw == null || raw.isEmpty) return;
      final j = jsonDecode(raw);
      if (j is! Map) return;
      j.forEach((k, v) {
        if (k is! String || v is! Map) return;
        try {
          _playlistLoadMoreInfo[k] = _PlaylistLoadMoreData(
            playlistId: v['playlistId'] as String,
            videoIds: List<String>.from(v['videoIds'] as List),
            titles: List<String>.from(v['titles'] as List),
            basePos: Offset(
              (v['bx'] as num).toDouble(),
              (v['by'] as num).toDouble(),
            ),
            nextStart: (v['nextStart'] as num).toInt(),
            parentId: v['parentId'] as String,
          );
        } catch (_) {
          // 1 エントリの破損は他のエントリに波及させない
        }
      });
    } catch (e) {
      debugPrint('loadLoadMoreInfo failed: $e');
    }
  }

  /// 「続きを出す」ノードがタップされた時の処理
  void _handleLoadMoreNodeTap(String nodeId, MindMapProvider provider) {
    final data = _playlistLoadMoreInfo[nodeId];
    if (data == null) return;

    provider.deleteNode(nodeId);
    _playlistLoadMoreInfo.remove(nodeId);

    final result = provider.addPlaylistNodes(
      data.playlistId,
      data.videoIds,
      data.titles,
      data.basePos,
      parentNodeId: data.parentId,
      startIndex: data.nextStart,
      batchSize: 5,
    );
    final newParentId = result.$1;
    final newRemaining = result.$2;
    final newLoadMoreId = result.$3;
    final newNextStart = result.$4;

    if (newRemaining > 0 && newLoadMoreId != null) {
      _playlistLoadMoreInfo[newLoadMoreId] = _PlaylistLoadMoreData(
        playlistId: data.playlistId,
        videoIds: data.videoIds,
        titles: data.titles,
        basePos: data.basePos,
        nextStart: newNextStart,
        parentId: newParentId,
      );
    }
    // ノードを削除/追加した結果の最新状態を SharedPreferences に永続化。
    // 失敗しても fire-and-forget (await しない)。
    _saveLoadMoreInfo();
  }

  void _resetInteractionState() {
    _stopEdgeScroll();
    _commitShelfInlineTextEdit();
    _removeOverlay();
    // 触るのをやめたらロックも外す (= 他の人が編集できるように)。
    try {
      context.read<MindMapProvider>().liveSetEditingNode(null);
    } catch (_) {}
    _movingPointerId = null;
    _moveDragAnchor = null;
    if (mounted) {
      setState(() {
        _moveModeNodeId = null;
        _movingPos = null;
        _currentSnap = null;
        _selectedConnections.clear();
        _clearConnectionBendDragFields(clearSelection: true);
        _draggingConnectionLabel = null;
        _suppressConnectionTapAfterBendDrag = false;
        _rangeStart = null;
        _rangeEnd = null;
        _rangeDragging = false;
        _rangeDragAnchor = null;
        _rangeDragDelta = Offset.zero;
        _siblingGuideParentId = null;
        _siblingGuidePos = null;
        _canvasLongPressActive = false;
        _canvasLongPressStart = null;
      });
    }
  }

  /// OS・Platform View・ジェスチャーアリーナにポインター終了を奪われた場合でも、
  /// InteractiveViewer を停止する一時フラグを残さない。
  ///
  /// 選択内容や範囲選択「モード」自体は維持し、進行中だったドラッグだけを破棄する。
  /// これにより次の空白左ドラッグで直ちにパン操作へ戻れる。
  void _cancelInterruptedCanvasGesture() {
    _stopEdgeScroll();
    final hasTransientState = _moveModeNodeId != null ||
        _movingPos != null ||
        _rangeStart != null ||
        _rangeEnd != null ||
        _rangeDragging ||
        _canvasLongPressActive ||
        _shelfHandleDragging ||
        _shelfHandleHovering ||
        _draggingDecoration ||
        _drawingDecorationStart != null ||
        _drawingDecorationEnd != null ||
        _draggingConnectionLabel != null ||
        _connectionBendPointerActive ||
        _activeMapScrollbarAxis != null;
    if (!hasTransientState || !mounted) return;
    setState(() {
      _moveModeNodeId = null;
      _movingPos = null;
      _moveDragAnchor = null;
      _movingPointerId = null;
      _currentSnap = null;
      _siblingGuideParentId = null;
      _siblingGuidePos = null;
      _shelfSwapTargetId = null;
      _rangeStart = null;
      _rangeEnd = null;
      _rangeDragging = false;
      _rangeDragAnchor = null;
      _rangeDragDelta = Offset.zero;
      _canvasLongPressActive = false;
      _canvasLongPressStart = null;
      _shelfRowDragFrom = null;
      _shelfColDragFrom = null;
      _shelfHandlePointerCanvas = null;
      _shelfHandleHovering = false;
      _draggingDecoration = false;
      _decoBodyDragMoved = false;
      _drawingDecorationStart = null;
      _drawingDecorationEnd = null;
      _draggingConnectionLabel = null;
      _suppressConnectionTapAfterBendDrag = false;
      _activeMapScrollbarAxis = null;
      _clearConnectionBendDragFields();
    });
  }

  /// 新しい主ボタン操作がマップに届いた時、前回操作の取りこぼしだけを回収する。
  /// マップ領域に実際にイベントが届いているため、分割パネルの hover 残留も解除可能。
  void _recoverCanvasInputBeforePointerDown(PointerDownEvent event) {
    final isPrimary = event.kind != PointerDeviceKind.mouse ||
        event.buttons == kPrimaryMouseButton;
    if (!isPrimary) return;
    if (_splitPanelHover || _splitLeftPanelHover) {
      setState(() {
        _splitPanelHover = false;
        _splitLeftPanelHover = false;
      });
    }
    if (_moveModeNodeId != null ||
        _rangeStart != null ||
        _rangeEnd != null ||
        _rangeDragging ||
        _canvasLongPressActive ||
        _shelfHandleDragging ||
        _shelfHandleHovering ||
        _draggingDecoration ||
        _draggingConnectionLabel != null ||
        _connectionBendPointerActive) {
      _cancelInterruptedCanvasGesture();
    }
  }

  // ─── リンクを開く ──────────────────────────────────────────────────────────

  /// `<video>` タグでアプリ内再生できるローカル動画拡張子を判定。
  /// `NodeWidget.isMp4Url` が拾わない `.webm` 系を補完するための判定。
  /// YouTube ダウンロードで保存された動画は muxed の container により
  /// `.webm` になることがあり、これを当アプリ内プレイヤーで開くために必要。
  /// `_FullscreenVideoPageState._isLocalPlayableVideo` と同等のロジック。
  bool _isLocalVideoFile(String url) {
    final lower = url.toLowerCase();
    var path = lower;
    final qi = path.indexOf('?');
    if (qi >= 0) path = path.substring(0, qi);
    final hi = path.indexOf('#');
    if (hi >= 0) path = path.substring(0, hi);
    return path.endsWith('.webm') ||
        path.endsWith('.ogv') ||
        path.endsWith('.ogg') ||
        path.endsWith('.3gp');
  }

  /// メモノードに表示されているタイムスタンプをタップした時に呼ばれる。
  /// このメモノードに繋がった親動画ノードを探し、 そこに記録された動画を
  /// 指定秒数からシークして再生開始する。
  ///
  /// 親動画ノードの判定:
  /// - `connections` のうち `toId == memo.id` のものを「親」 とみなし、
  ///   `fromId` のノードに `youtubeUrl` (= 動画 URL) があれば動画ノード扱い
  /// - YouTube 動画なら `https://www.youtube.com/watch?v=ID&t=Xs` 形式の URL に変換
  ///   (動画自体が `&t=` でシーク開始してくれる)
  /// - ローカル mp4 なら `_FullscreenVideoPage(initialPosition: seconds)` で
  ///   ネイティブプレイヤー側でシーク開始
  ///
  /// 親動画ノードが見つからない場合は SnackBar で通知して何もしない
  /// (= ユーザーがメモを別のノードに繋ぎ変えたケースの保険)。
  void _jumpFromMemoTimestamp(MindMapNode memoNode, double seconds) {
    final provider = context.read<MindMapProvider>();
    // 親接続をたどって動画 URL を持つノードを探す
    String? videoUrl;
    String? parentNodeId;
    for (final c in provider.connections) {
      if (c.toId != memoNode.id) continue;
      final parent = provider.nodes[c.fromId];
      if (parent == null) continue;
      final url = parent.youtubeUrl ?? '';
      if (url.isEmpty) continue;
      videoUrl = url;
      parentNodeId = parent.id;
      break;
    }
    if (videoUrl == null) {
      _appSnack(
        context,
        SnackBar(
          content:
              Text(context.read<MindMapProvider>().t('node.linkVideoNotFound')),
          duration: Duration(seconds: 2),
        ),
      );
      return;
    }

    final videoId = NodeWidget.extractVideoId(videoUrl);
    final secInt = seconds.floor();

    if (videoId != null) {
      // YouTube: ?t=Xs 付き URL を直接ロードすればシークしてくれる。
      // 元の URL にもクエリが付いている可能性があるので、 video ID から
      // 標準形式に組み立て直す方が確実。
      final urlWithStart =
          'https://www.youtube.com/watch?v=$videoId&t=${secInt}s';
      if (_isDesktop) {
        _showWebDialog(context, urlWithStart);
      } else {
        _openFullscreenVideo(
          context,
          url: urlWithStart,
          // モバイル版は YouTube 動画ページでも `initialPosition` で
          // <video>.currentTime のシークを試みるので両方渡す (どちらかが
          // 効けば OK)。
          initialPosition: seconds,
        );
      }
      return;
    }

    // ローカル mp4 / 直リンク mp4: initialPosition でシーク
    final isMp4 = NodeWidget.isMp4Url(videoUrl) || _isLocalVideoFile(videoUrl);
    if (isMp4) {
      final headerTitle = parentNodeId != null
          ? (provider.nodes[parentNodeId]?.title ?? '')
          : '';
      if (_isDesktop) {
        // Windows 版は initialPosition 未対応のため、 一旦 SnackBar で通知。
        // 将来 _WindowsWebViewSheet にも seek を実装したらここを差し替える。
        _showWebDialog(
          context,
          videoUrl,
          initialTitle: headerTitle.isNotEmpty ? headerTitle : null,
        );
        _appSnack(
          context,
          SnackBar(
            content: Text(
                '動画を開きました。 ${_formatJumpSec(seconds)} までシークしてください (デスクトップは自動シーク未対応)'),
            duration: const Duration(seconds: 4),
          ),
        );
      } else {
        _openFullscreenVideo(
          context,
          url: videoUrl,
          initialPosition: seconds,
          initialTitle: headerTitle.isNotEmpty ? headerTitle : null,
        );
      }
      return;
    }

    // それ以外 (= 動画として扱えない URL) はそのまま開く
    _openFullscreenVideo(context, url: videoUrl, initialPosition: seconds);
  }

  /// `_jumpFromMemoTimestamp` の SnackBar 用に `mm:ss` / `h:mm:ss` 形式に整形。
  String _formatJumpSec(double sec) {
    final s = sec.floor();
    final h = s ~/ 3600;
    final m = (s % 3600) ~/ 60;
    final ss = s % 60;
    if (h > 0) {
      return '$h:${m.toString().padLeft(2, '0')}:${ss.toString().padLeft(2, '0')}';
    }
    return '${m.toString().padLeft(2, '0')}:${ss.toString().padLeft(2, '0')}';
  }

  void _openNodeLink(MindMapNode node) {
    final url = _nodeGetLink(node);
    // ── Ctrl(⌘)+クリック: アプリ内の別ペイン (画面分割パネル) で開く ──
    // ユーザー要望「YouTube 動画等、 Ctrl+クリックでアプリ内で違うタブ
    //   (= 別ペイン) が開かれるように」 への対応。
    //   ・デスクトップのみ (モバイルには画面分割パネルが無いため通常動作)。
    //   ・対象は YouTube と http(s) の Web ページのみ。 ローカルの mp4/webm
    //     等はそのままアプリ内プレイヤーで開く (= 従来動作へフォールバック)。
    //   ・通常クリックは従来通りフルスクリーンプレイヤー / ビューアで開く。
    //   _openUrlInSplitPanel は空いている側のペインに自動で開き、 両方
    //   埋まっていれば右ペインを差し替える (= ブラウザの新規タブに近い挙動)。
    final bool ctrlPressed = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    if (_isDesktop && ctrlPressed && url.isNotEmpty) {
      final vid = NodeWidget.extractVideoId(url);
      if (vid != null) {
        _openUrlInSplitPanel('https://www.youtube.com/watch?v=$vid');
        return;
      }
      if (url.startsWith('http://') || url.startsWith('https://')) {
        _openUrlInSplitPanel(url);
        return;
      }
      // ローカルファイル等は通常動作へフォールバック (下へ続行)。
    }
    final videoId = NodeWidget.extractVideoId(url);
    // mp4 直リンク + ローカル webm/ogv/3gp も全て「アプリ内動画プレイヤー
    // (= _FullscreenVideoPage / _showWebDialog) で開くべきファイル」と判定する。
    // YouTube ダウンロードで保存される動画は muxed の container 形式により
    // .webm になることがあり、isMp4Url だけだと拾えず _launchUrl 経由で
    // 外部アプリが開いてしまう (= うちの再生バー / 速度スライダーが効かない)。
    final isMp4 =
        videoId == null && (NodeWidget.isMp4Url(url) || _isLocalVideoFile(url));
    if (videoId != null) {
      // 同じ親の兄弟YouTube動画をプレイリストとして構築
      final provider = context.read<MindMapProvider>();
      final conns = provider.connections;
      // この node の親を探す
      String? parentId;
      for (final c in conns) {
        if (c.toId == node.id) {
          parentId = c.fromId;
          break;
        }
      }
      final playlist = <String>[];
      int startIdx = 0;
      if (parentId != null) {
        // 親の子ノードでYouTube URLを持つものを順番に
        for (final c in conns) {
          if (c.fromId == parentId) {
            final child = provider.nodes[c.toId];
            if (child != null && (child.youtubeUrl ?? '').isNotEmpty) {
              final vid = NodeWidget.extractVideoId(child.youtubeUrl!);
              if (vid != null) {
                playlist.add('https://www.youtube.com/watch?v=$vid');
              }
            }
          }
        }
        // このノードのインデックスを探す
        final thisUrl = 'https://www.youtube.com/watch?v=$videoId';
        startIdx = playlist.indexOf(thisUrl).clamp(0, playlist.length - 1);
      }
      // ── ギャラリー + 自動遷移ON: 親子ではなくギャラリーの動画をセル順で playlist に
      //    する (= ユーザー要望: 動画が終わったらギャラリーの次の動画へ) ──
      if (provider.currentPage.pageType == 'bookshelf' &&
          provider.bookshelfAutoPlayNext) {
        final r =
            _bookshelfVideoPlaylist('https://www.youtube.com/watch?v=$videoId');
        if (r.$1.length > 1) {
          playlist
            ..clear()
            ..addAll(r.$1);
          startIdx = r.$2;
        }
      }
      if (playlist.isEmpty) {
        playlist.add('https://www.youtube.com/watch?v=$videoId');
      }

      // 最後に見た動画を記録
      provider.saveVideoPosition(videoId, provider.getVideoPosition(videoId));

      // 自動削除モードON → プレーヤーを閉じた後に視聴完了ノードを削除して補充
      final parentIdForDelete = parentId;
      final shouldAutoDelete = provider.autoDeleteWatched;

      if (_isDesktop) {
        _showWebDialog(context, playlist[startIdx],
            playlist: playlist, startIndex: startIdx,
            // ── ノード経由で開いた場合の DL 完了時の動作 (モバイル版と同じ) ──
            // 既存ノードの YouTube URL をローカルパスに置換してオフライン化する。
            // これを指定しないと `_showWebDialog` のデフォルト
            // `_defaultEmbedDownloadedVideo` が走って新規ノードがマップ中央に
            // 作られてしまう (= 元のノードが残ったまま重複が出る)。
            onDownloadComplete: (record) {
          _replaceNodeUrlWithLocal(node.id, record);
        }).then((_) {
          if (shouldAutoDelete) {
            provider.processWatchedAndRefill(parentIdForDelete);
          }
          // ギャラリーなら見終わった動画を削除 (設定ON時のみ。 内部でガード)。
          provider.cleanupWatchedBookshelfVideos();
        });
      } else {
        _openFullscreenVideo(context,
            url: playlist[startIdx], playlist: playlist, startIndex: startIdx,
            // ── ノード経由で開いた場合の DL 完了時の動作 ──
            // 既存ノードの YouTube URL をローカルパスに置換してオフライン化
            // する。新規ノードを作るのではなく、ユーザーがいま見ている動画
            // ノード自体をオフライン化することで「見つからない」問題を回避。
            onDownloadComplete: (record) {
          _replaceNodeUrlWithLocal(node.id, record);
        }).then((_) {
          if (shouldAutoDelete) {
            provider.processWatchedAndRefill(parentIdForDelete);
          }
          // ギャラリーなら見終わった動画を削除 (設定ON時のみ。 内部でガード)。
          provider.cleanupWatchedBookshelfVideos();
        });
      }
    } else if (isMp4) {
      // ノード経由でローカル mp4 (オフライン化された YouTube 動画 etc) を
      // 開く場合、ヘッダーには元の動画タイトル (= ノードのタイトル) を出す。
      // 指定しないと WebView がファイル名を表示するので
      // "3915_2026_2_yR6fHAe9WFw_1.mp4" みたいな見た目になる。
      final headerTitle = node.title.isNotEmpty ? node.title : null;
      if (_isDesktop) {
        _showWebDialog(context, url, initialTitle: headerTitle);
      } else {
        _openFullscreenVideo(context, url: url, initialTitle: headerTitle);
      }
    } else {
      // ノード経由なので、 アプリ内ビューア内でこのノードに紐づくメモを
      // 残せるように nodeId を伝搬する (URL メモ機能)。
      _launchUrl(url, nodeId: node.id);
    }
  }

  /// ノード経由で開いた YouTube 動画が DL 完了した時に、そのノード自体の
  /// `youtubeUrl` をローカルパス (オフライン再生用) に書き換える。
  /// 新規ノードを作る代わりにこれを呼ぶことで、ユーザーが見ていた動画ノード
  /// がそのままオフライン化される (キャンバス上の見た目は変わらない)。
  ///
  /// 動作:
  ///   - `youtubeUrl` をローカルパスに置換 → サムネ右下にオフラインバッジが
  ///     自動で表示される (NodeWidget の isOffline 判定経由)。
  ///   - サムネイル: record['thumbPath'] (CDN sd/hq) があれば即セット、
  ///     なければ動画ファイルからフレーム抽出。
  ///   - SnackBar で「ノードをオフライン化しました」通知。
  void _replaceNodeUrlWithLocal(String nodeId, Map<String, dynamic> record) {
    if (!mounted) return;
    final path = record['path']?.toString() ?? '';
    final thumbPath = record['thumbPath']?.toString();
    final title = record['title']?.toString() ?? '';
    debugPrint(
        '[ReplaceNode] nodeId=$nodeId path=$path thumb=$thumbPath title=$title');
    if (path.isEmpty) {
      debugPrint('[ReplaceNode] path is empty, abort');
      return;
    }
    final provider = context.read<MindMapProvider>();
    // ファイル実体の存在も確認 (ダウンロードが途中で止まっていないか)
    if (!File(path).existsSync()) {
      debugPrint('[ReplaceNode] file does not exist at $path');
      _appSnack(
          context,
          SnackBar(
            content: Text('${provider.t('video.fileNotFound')}: $path',
                style: const TextStyle(fontSize: 12)),
            backgroundColor: const Color(0xFFE53935),
          ));
      return;
    }
    // ノードがまだ存在するかチェック (ユーザーが DL 中に削除した可能性)
    if (provider.nodes[nodeId] == null) {
      debugPrint('[ReplaceNode] node $nodeId not found in provider');
      // ノードが消えていたら、新しくキャンバス中央に作成する
      // (= デフォルトの動作にフォールバック)
      _embedLocalVideoAsNode(path, title, thumbPath: thumbPath);
      return;
    }
    debugPrint(
        '[ReplaceNode] node found, current youtubeUrl=${provider.nodes[nodeId]?.youtubeUrl}');
    // ノードの動画 URL をローカルパスに置換
    provider.updateNodeYoutube(nodeId, path);
    debugPrint('[ReplaceNode] updated youtubeUrl to local path. After: '
        '${provider.nodes[nodeId]?.youtubeUrl}');
    // サムネイル: CDN サムネがあれば即セット、なければ動画から生成
    if (thumbPath != null &&
        thumbPath.isNotEmpty &&
        File(thumbPath).existsSync()) {
      provider.setVideoThumbnailPath(nodeId, thumbPath);
      debugPrint('[ReplaceNode] thumb set: $thumbPath');
    } else {
      provider.generateVideoThumbnail(nodeId);
      debugPrint('[ReplaceNode] thumb gen requested');
    }
    // UI 強制再描画 (provider.notifyListeners は updateNodeYoutube 内で
    // 呼ばれているはずだが、念のため当 State でも setState して
    // キャンバス上のノード描画を確実に更新する)
    if (mounted) setState(() {});
    // SnackBar で通知
    _appSnack(
        context,
        SnackBar(
          content: Text(provider.t('video.nodeOfflined'),
              style: const TextStyle(fontSize: 12)),
          backgroundColor: const Color(0xFF43B97F),
          duration: const Duration(seconds: 3),
        ));
  }

  /// ギャラリーの動画ノードをセル順 (行→列) に並べた再生リストと、 [currentUrl] の
  /// 位置を返す (= ユーザー要望: 動画が終わったらギャラリーの次の動画へ)。
  /// ギャラリー以外、 または動画が 2 本未満なら空リスト。
  (List<String>, int) _bookshelfVideoPlaylist(String currentUrl) {
    final provider = context.read<MindMapProvider>();
    if (provider.currentPage.pageType != 'bookshelf') {
      return (const <String>[], 0);
    }
    final vids = provider.currentPage.nodes.values.where((n) {
      final u = n.youtubeUrl ?? '';
      return u.isNotEmpty && NodeWidget.extractVideoId(u) != null;
    }).toList();
    if (vids.length < 2) return (const <String>[], 0);
    // = ユーザー要望: 進行方向 (左→右 / 右→左) を設定で切り替え。 列順を反転。
    final reverse = provider.bookshelfReverseOrder;
    vids.sort((a, b) {
      final ca = provider.shelfCellOf(a.id) ?? const [0, 0];
      final cb = provider.shelfCellOf(b.id) ?? const [0, 0];
      if (ca[1] != cb[1]) return ca[1] - cb[1];
      return reverse ? cb[0] - ca[0] : ca[0] - cb[0];
    });
    final urls = vids.map((n) => n.youtubeUrl!).toList();
    final curId = NodeWidget.extractVideoId(currentUrl);
    int idx = 0;
    for (int i = 0; i < urls.length; i++) {
      if (NodeWidget.extractVideoId(urls[i]) == curId) {
        idx = i;
        break;
      }
    }
    return (urls, idx);
  }

  Future<void> _openLink(String url) async {
    final videoId = NodeWidget.extractVideoId(url);
    // mp4 直リンク + ローカル webm/ogv/3gp も全部アプリ内プレイヤーで開く。
    // (`_openNodeLink` と同じ理由)
    final isMp4 =
        videoId == null && (NodeWidget.isMp4Url(url) || _isLocalVideoFile(url));
    if (videoId != null) {
      final ytUrl = 'https://www.youtube.com/watch?v=$videoId';
      // ギャラリー + 自動遷移ON の時は、 ギャラリーの動画をセル順で playlist にして渡す。
      final provider = context.read<MindMapProvider>();
      List<String> pl = const [];
      int startIdx = 0;
      if (provider.currentPage.pageType == 'bookshelf' &&
          provider.bookshelfAutoPlayNext) {
        final r = _bookshelfVideoPlaylist(ytUrl);
        pl = r.$1;
        startIdx = r.$2;
      }
      if (_isDesktop) {
        if (pl.length > 1) {
          await _showWebDialog(context, ytUrl,
              playlist: pl, startIndex: startIdx);
        } else {
          await _showWebDialog(context, ytUrl);
        }
      } else {
        if (pl.length > 1) {
          await _openFullscreenVideo(context,
              url: ytUrl, playlist: pl, startIndex: startIdx);
        } else {
          await _openFullscreenVideo(context, url: ytUrl);
        }
      }
      // プレイヤーを閉じた後、 見終わった動画を削除する設定なら掃除する。
      if (mounted) provider.cleanupWatchedBookshelfVideos();
    } else if (isMp4) {
      if (_isDesktop) {
        _showWebDialog(context, url);
      } else {
        _openFullscreenVideo(context, url: url);
      }
    } else {
      _launchUrl(url);
    }
  }

  /// モバイル：動画/Webを全画面で開く
  /// 動画を開いた時に「表示のなめらかさ (リフレッシュレート) を動画に
  /// 合わせるか」 を確認する (= ユーザー要望: 動画を上げる時にリフレッシュ
  /// レートを合わせるかの確認が出るようにして欲しい)。
  ///
  /// ・Android のみ。 Windows は OS がモニターのレートで描画するので不要。
  /// ・「今後聞かない」 を選ぶと以後は保存した選択を黙って適用する。
  /// ・切り替えに失敗しても再生自体には影響しない。
  // 現在は未使用 (= ユーザー要望で確認ダイアログを廃止)。 設定画面から
  // 手動で高リフレッシュレートを選ぶ導線は残っているので、 将来また
  // 動画連動に戻せるよう関数自体は残置する。
  // ignore: unused_element
  Future<void> _maybeAskMatchRefreshRate(BuildContext ctx) async {
    if (kIsWeb || !Platform.isAndroid) return;
    final provider = ctx.read<MindMapProvider>();
    if (!provider.askRefreshOnVideo) {
      // 確認済み: 保存された選択をそのまま適用する。
      await applyPreferredDisplayMode(
          high: provider.matchRefreshOnVideo && provider.highRefreshRate);
      return;
    }
    if (!mounted) return;
    bool dontAsk = false;
    final res = await showDialog<bool>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Text(provider.t('refresh.askTitle'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
          content: Column(mainAxisSize: MainAxisSize.min, children: [
            Text(provider.t('refresh.askBody'),
                style: const TextStyle(color: Colors.white70, fontSize: 13)),
            const SizedBox(height: 8),
            InkWell(
              onTap: () => setD(() => dontAsk = !dontAsk),
              child: Row(children: [
                Icon(
                    dontAsk
                        ? Icons.check_box_rounded
                        : Icons.check_box_outline_blank_rounded,
                    size: 18,
                    color: Colors.white70),
                const SizedBox(width: 6),
                Flexible(
                  child: Text(provider.t('refresh.dontAsk'),
                      style: const TextStyle(
                          color: Colors.white70, fontSize: 12)),
                ),
              ]),
            ),
          ]),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(dctx, false),
                child: Text(provider.t('refresh.keep'),
                    style: const TextStyle(color: Colors.white54))),
            ElevatedButton(
                onPressed: () => Navigator.pop(dctx, true),
                child: Text(provider.t('refresh.match'))),
          ],
        );
      }),
    );
    if (res == null) return; // 閉じただけなら何もしない
    await provider.setMatchRefreshOnVideo(res);
    if (dontAsk) await provider.setAskRefreshOnVideo(false);
    await applyPreferredDisplayMode(high: res && provider.highRefreshRate);
  }

  Future<void> _openFullscreenVideo(
    BuildContext ctx, {
    required String url,
    List<String> playlist = const [],
    int startIndex = 0,
    double? initialRate,

    /// 動画開始位置 (秒)。 メモのハイパーリンクから飛んできた時に、
    /// その時刻からシークして再生開始するために使う。 0 なら先頭から。
    double initialPosition = 0.0,
    void Function(String currentUrl)? onEmbedUrl,
    bool focusMode = true,
    void Function(Map<String, dynamic> record)? onDownloadComplete,
    // モバイル版では現状参照していないが、`_showWebDialog` がデスクトップ /
    // モバイル両方で同じシグネチャを使うために受け取れるようにしておく。
    // 将来 _FullscreenVideoPage にもタイトル表示を入れる場合はそのまま流せる。
    String? initialTitle,
  }) {
    // 初期倍率: 呼び出し側未指定なら Provider の直近倍率を採用
    // (= 動画を開くたびに 1.0x にリセットされない)。
    final double effectiveRate =
        initialRate ?? ctx.read<MindMapProvider>().lastVideoPlaybackRate;
    // ── 「表示を動画に合わせますか?」 の確認は廃止 (= ユーザー要望:
    //    項目は出さなくてよい / 動画視聴のリフレッシュレートは変えない) ──
    //    表示モードは OS 任せにする。
    // ダウンロード完了コールバックが指定されていなければ、デフォルトとして
    // 「マップに自動埋め込み」する関数を割り当てる。これでノード経由 / ブラウズ
    // 経由を問わず、ダウンロード完了 → 自動的にマップにノード化される。
    final dlCallback = onDownloadComplete ?? _defaultEmbedDownloadedVideo;
    return Navigator.of(ctx).push(MaterialPageRoute(
      fullscreenDialog: true,
      builder: (_) => _FullscreenVideoPage(
        url: url,
        playlist: playlist,
        startIndex: startIndex,
        initialRate: effectiveRate,
        initialPosition: initialPosition,
        onEmbedUrl: onEmbedUrl,
        focusMode: focusMode,
        onDownloadComplete: dlCallback,
        // 現在の URL を画面分割パネルに引き継ぎつつ閉じる
        onMoveToSplitPanel: (currentUrl, {bool isLeftPanel = false}) {
          // ユーザー要望: 「右分割と左分割を同時に表示できる」
          //   ようにするため、 反対側パネルは触らない。
          final isPdf = currentUrl.toLowerCase().endsWith('.pdf');
          if (isLeftPanel) {
            if (isPdf) {
              _splitLoadLeftPdf(currentUrl);
            } else {
              _splitLoadLeftUrl(currentUrl);
            }
          } else {
            setState(() => _setSplitOpen(true));
            _splitLoadUrl(currentUrl);
          }
        },
      ),
    ));
  }

  // ─── ダウンロード済み動画のマップ埋め込み + 一覧 ───────────────────────────

  /// ダウンロード完了時に既定で呼ばれる「マップに自動埋め込み」関数。
  /// `_FullscreenVideoPage.onDownloadComplete` のデフォルト値として使う。
  /// 現在のキャンバス中央に動画ノードを生成し、ローカルファイルパスを
  /// `youtubeUrl` フィールドに保存 (既存の mp4 添付パターン踏襲)。
  /// サムネイルもバックグラウンドで生成する。
  void _defaultEmbedDownloadedVideo(Map<String, dynamic> record) {
    if (!mounted) return;
    final path = record['path']?.toString() ?? '';
    final title = record['title']?.toString() ?? '';
    final thumbPath = record['thumbPath']?.toString();
    if (path.isEmpty) return;
    _embedLocalVideoAsNode(path, title, thumbPath: thumbPath);
  }

  /// 指定パスのローカル動画ファイルを、現在のキャンバス中央に動画ノード
  /// として配置する。
  /// - 配置位置: 現在のビューポート中心 (TransformationController の状態
  ///   から逆算)。
  /// - ノードへの紐付け: `updateNodeYoutube` に絶対パスを渡す
  ///   (mp4 添付の既存パターンを踏襲)。
  /// - サムネイル: `thumbPath` が指定されていれば優先的にノードに当て、
  ///   無ければ `generateVideoThumbnail` で動画ファイルから生成。
  void _embedLocalVideoAsNode(String localPath, String title,
      {String? thumbPath}) {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final pageId = provider.currentPage.id;
    final ctrl = _ctrlFor(pageId);
    final s = View.of(context).physicalSize / View.of(context).devicePixelRatio;
    final mat = ctrl.value;
    final scale = mat.getMaxScaleOnAxis();
    final tx = mat.getTranslation().x;
    final ty = mat.getTranslation().y;
    final cx = (s.width / 2 - tx) / scale;
    final cy = (s.height / 2 - ty) / scale;
    final pos = Offset(cx - 80, cy - 21);

    // 容量上限チェックは provider 側で対応 (例外時はここで握りつぶさず
    // SnackBar で通知)。
    try {
      final newNode = provider.addNodeAtCenterReturning(pos);
      provider.updateNodeYoutube(newNode.id, localPath);
      provider.updateNodeLink(newNode.id, '');
      // タイトルを設定 (空文字なら Provider のデフォルトのまま)
      if (title.isNotEmpty) {
        provider.updateNodeTitle(newNode.id, title);
      }
      // サムネイル: CDN から取得済みなら即セット、なければ動画ファイル
      // からフレーム抽出 (非同期)。
      if (thumbPath != null &&
          thumbPath.isNotEmpty &&
          File(thumbPath).existsSync()) {
        provider.setVideoThumbnailPath(newNode.id, thumbPath);
      } else {
        provider.generateVideoThumbnail(newNode.id);
      }

      _appSnack(
          context,
          SnackBar(
            content: Text(
                '${provider.t('video.embeddedToMap')}: '
                '${title.isEmpty ? localPath.split(Platform.pathSeparator).last : title}',
                style: const TextStyle(fontSize: 12)),
            backgroundColor: const Color(0xFF43B97F),
            duration: const Duration(seconds: 3),
          ));
    } catch (e) {
      _appSnack(
          context,
          SnackBar(
            content: Text('${provider.t('video.embedFailed')}: $e',
                style: const TextStyle(fontSize: 12)),
            backgroundColor: const Color(0xFFE53935),
          ));
    }
  }

  /// バックグラウンド再生を有効にするダイアログ。
  ///
  /// 動作:
  ///   1. 現在のバッテリー最適化除外状態を `Permission.ignoreBatteryOptimizations`
  ///      で確認し、状態を表示
  ///   2. 「設定画面を開く」ボタン → Android のバッテリー最適化除外画面
  ///      (REQUEST_IGNORE_BATTERY_OPTIMIZATIONS Intent) にジャンプ
  ///   3. ユーザーがそこで「制限なし」を選んで戻ってくる
  ///   4. 必要なら「アプリ情報を開く」も用意 (端末メーカー独自の電池
  ///      最適化が強い場合のフォールバック)
  ///
  /// デスクトップ (Windows / macOS / Linux) ではこの機能は不要なので
  /// 「Android 端末専用」と表示して何もしない。
  Future<void> _showBackgroundPlaybackDialog(BuildContext ctx) async {
    final provider = ctx.read<MindMapProvider>();
    // Android 以外では機能しないので、簡単な案内だけ。
    if (!Platform.isAndroid) {
      await showDialog<void>(
        context: ctx,
        builder: (dctx) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            const Icon(Icons.info_outline_rounded,
                color: Color(0xFF4FC3F7), size: 20),
            const SizedBox(width: 8),
            Text(provider.t('bg.title'),
                style: const TextStyle(color: Colors.white, fontSize: 14)),
          ]),
          content: Text(
            provider.t('bg.androidOnly'),
            style: const TextStyle(color: Colors.white70, fontSize: 12),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: const Text('OK', style: TextStyle(color: Colors.white70)),
            ),
          ],
        ),
      );
      return;
    }

    if (!ctx.mounted) return;
    await showDialog<void>(
      context: ctx,
      builder: (dctx) => StatefulBuilder(
        builder: (sctx, setD) {
          // ダイアログを開いている間にユーザーが端末設定を変えて戻って
          // きたケースに備えて、毎回再描画時に最新状態を取得する。
          // Future ベースで非同期取得して setState で反映。
          Future<bool> getBatteryOptStatus() async {
            try {
              return await Permission.ignoreBatteryOptimizations.isGranted;
            } catch (_) {
              return false;
            }
          }

          return AlertDialog(
            backgroundColor: const Color(0xFF1E1E32),
            title: Row(children: [
              const Icon(Icons.battery_charging_full_rounded,
                  color: Color(0xFF4FC3F7), size: 20),
              const SizedBox(width: 8),
              Expanded(
                child: Text(provider.t('bg.title'),
                    style: const TextStyle(color: Colors.white, fontSize: 14)),
              ),
            ]),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // ── ON/OFF スイッチ ──
                  // メインの設定。これが ON の時だけ動画再生時に高頻度
                  // play() 強制呼び出し + wakelock + MediaSession が効く。
                  Container(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 12, vertical: 10),
                    decoration: BoxDecoration(
                      color: provider.backgroundPlaybackEnabled
                          ? const Color(0xFF43B97F).withValues(alpha: 0.18)
                          : Colors.white.withValues(alpha: 0.06),
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(
                        color: provider.backgroundPlaybackEnabled
                            ? const Color(0xFF43B97F)
                            : Colors.white24,
                        width: 1.2,
                      ),
                    ),
                    child: Row(children: [
                      Icon(
                        provider.backgroundPlaybackEnabled
                            ? Icons.play_circle_rounded
                            : Icons.pause_circle_outline_rounded,
                        color: provider.backgroundPlaybackEnabled
                            ? const Color(0xFF43B97F)
                            : Colors.white54,
                        size: 24,
                      ),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Text(
                              provider.backgroundPlaybackEnabled
                                  ? provider.t('bg.statusOn')
                                  : provider.t('bg.statusOff'),
                              style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 13,
                                  fontWeight: FontWeight.w700),
                            ),
                            const SizedBox(height: 2),
                            Text(
                              provider.backgroundPlaybackEnabled
                                  ? provider.t('bg.statusOnDesc')
                                  : provider.t('bg.statusOffDesc'),
                              style: TextStyle(
                                  color: Colors.white.withValues(alpha: 0.6),
                                  fontSize: 10),
                            ),
                          ],
                        ),
                      ),
                      // カスタム Switch
                      GestureDetector(
                        onTap: () async {
                          final next = !provider.backgroundPlaybackEnabled;
                          await provider.setBackgroundPlaybackEnabled(next);
                          setD(() {});
                          // ON にしたら即座にバッテリー最適化除外もチェック。
                          // 未許可なら自動で除外申請ダイアログを出す。
                          if (next) {
                            try {
                              if (!await Permission
                                  .ignoreBatteryOptimizations.isGranted) {
                                await Permission.ignoreBatteryOptimizations
                                    .request();
                                setD(() {});
                              }
                            } catch (_) {}
                          }
                          // ── 設定画面から切り替えた時も常駐サービスを
                          //    即座に合わせる (= ユーザー報告: ON なのに
                          //    再生されない回がある。 動画を開いた後に ON に
                          //    しても Service が起動していなかった) ──
                          try {
                            if (!kIsWeb && Platform.isAndroid) {
                              if (next) {
                                await _BgPlaybackController.start();
                              } else {
                                await _BgPlaybackController.forceStop();
                              }
                            }
                          } catch (_) {}
                        },
                        child: Container(
                          width: 44,
                          height: 24,
                          decoration: BoxDecoration(
                            color: provider.backgroundPlaybackEnabled
                                ? const Color(0xFF43B97F)
                                : Colors.white24,
                            borderRadius: BorderRadius.circular(14),
                          ),
                          child: AnimatedAlign(
                            duration: const Duration(milliseconds: 150),
                            alignment: provider.backgroundPlaybackEnabled
                                ? Alignment.centerRight
                                : Alignment.centerLeft,
                            child: Container(
                              margin: const EdgeInsets.all(2),
                              width: 20,
                              height: 20,
                              decoration: const BoxDecoration(
                                color: Colors.white,
                                shape: BoxShape.circle,
                              ),
                            ),
                          ),
                        ),
                      ),
                    ]),
                  ),
                  const SizedBox(height: 12),
                  // ── バッテリー最適化除外の状態 ──
                  FutureBuilder<bool>(
                    future: getBatteryOptStatus(),
                    builder: (_, snap) {
                      final isExcluded = snap.data ?? false;
                      return Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 10, vertical: 8),
                        decoration: BoxDecoration(
                          color: isExcluded
                              ? const Color(0xFF43B97F).withValues(alpha: 0.10)
                              : Colors.white.withValues(alpha: 0.04),
                          borderRadius: BorderRadius.circular(6),
                          border: Border.all(
                            color: isExcluded
                                ? const Color(0xFF43B97F).withValues(alpha: 0.5)
                                : Colors.white12,
                          ),
                        ),
                        child: Row(children: [
                          Icon(
                            isExcluded
                                ? Icons.check_circle_rounded
                                : Icons.warning_amber_rounded,
                            color: isExcluded
                                ? const Color(0xFF43B97F)
                                : const Color(0xFFFFB347),
                            size: 16,
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: Text(
                              isExcluded
                                  ? provider.t('bg.batteryExcluded')
                                  : provider.t('bg.batteryRestricted'),
                              style: const TextStyle(
                                  color: Colors.white, fontSize: 11),
                            ),
                          ),
                          if (!isExcluded)
                            TextButton(
                              style: TextButton.styleFrom(
                                padding:
                                    const EdgeInsets.symmetric(horizontal: 8),
                                minimumSize: const Size(0, 28),
                                tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                              ),
                              onPressed: () async {
                                try {
                                  await Permission.ignoreBatteryOptimizations
                                      .request();
                                  setD(() {});
                                } catch (_) {}
                              },
                              child: Text(provider.t('bg.unrestrict'),
                                  style: const TextStyle(
                                      color: Color(0xFF4FC3F7),
                                      fontSize: 11,
                                      fontWeight: FontWeight.w700)),
                            ),
                        ]),
                      );
                    },
                  ),
                  const SizedBox(height: 12),
                  // 動作説明
                  Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: Colors.white.withValues(alpha: 0.04),
                      borderRadius: BorderRadius.circular(4),
                    ),
                    child: Text(
                      provider.t('bg.actionsOn'),
                      style: const TextStyle(
                          color: Colors.white60, fontSize: 10, height: 1.6),
                    ),
                  ),
                ],
              ),
            ),
            actionsPadding: const EdgeInsets.fromLTRB(8, 0, 8, 8),
            actions: [
              TextButton(
                onPressed: () async {
                  try {
                    await openAppSettings();
                  } catch (e) {
                    debugPrint('openAppSettings failed: $e');
                  }
                },
                child: Text(context.read<MindMapProvider>().t('app.info'),
                    style: TextStyle(color: Colors.white70)),
              ),
              ElevatedButton(
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6C63FF),
                  foregroundColor: Colors.white,
                ),
                onPressed: () => Navigator.pop(dctx),
                child: Text(context.read<MindMapProvider>().t('btn.close'),
                    style:
                        TextStyle(fontSize: 12, fontWeight: FontWeight.w700)),
              ),
            ],
          );
        },
      ),
    );
  }

  /// ダウンロード済み動画一覧ダイアログ。
  /// 右クリックメニュー (PC) や 3 点メニュー (PC/モバイル共通) から開く。
  ///
  /// 操作:
  ///   - タップ: アプリ内プレイヤーで再生
  ///   - 長押し: 選択モードに入る (モバイル向け)
  ///   - Ctrl+クリック: 選択トグル (デスクトップ向け、選択モードに入る)
  ///   - Shift+クリック: アンカーから範囲選択 (デスクトップ向け)
  ///   - 「埋」アイコン: マップに再度埋め込む
  ///   - 「✕」アイコン: 1 件だけ削除
  ///   - 選択モード時: トップに [全て選択] [{n} 件削除] が出る
  void _showDownloadedVideosDialog(BuildContext ctx) {
    final provider = ctx.read<MindMapProvider>();
    // ── 選択状態 (ダイアログのスコープに保持) ──
    // path をキーにする (videoId は無いケースもあるので path が一意)。
    final selectedPaths = <String>{};
    // Shift+クリック範囲選択用のアンカー (現在表示中リスト内のインデックス)
    int? lastAnchorIndex;
    // FutureBuilder の最新スナップショットを保持する。リスト全選択や範囲選択
    // から参照するために、外側変数で持つ。
    List<Map<String, dynamic>> currentList = const [];
    // 選択モード自体のフラグ (selectedPaths とは独立)。
    // ・[選択] ボタンで明示的に true にできる (チェックボックス表示)
    // ・[×] ボタンで false に戻る (選択もクリア)
    // ・Ctrl/Shift+クリック / 長押しで自動的に true になる
    bool selectMode = false;

    showDialog(
      context: ctx,
      builder: (dctx) => StatefulBuilder(builder: (sctx, setD) {
        // selectedPaths が空でも、ユーザーが明示的に選択モード入りした
        // (= [選択] ボタン) ならチェックボックスを表示。
        final inSelectMode = selectMode || selectedPaths.isNotEmpty;
        final totalSelectable = currentList.length;

        // Ctrl+A / Cmd+A で全選択。リストが空 or 既に全選択済みなら何もしない。
        // CallbackShortcuts は Focus を必要とするので autofocus した Focus で
        // ダイアログ全体を包む。 Mac は meta:true、Windows/Linux は control:true。
        void selectAllInList() {
          if (currentList.isEmpty) return;
          setD(() {
            selectMode = true;
            for (final r in currentList) {
              final path = r['path']?.toString() ?? '';
              if (path.isNotEmpty) selectedPaths.add(path);
            }
          });
        }

        return CallbackShortcuts(
          bindings: <ShortcutActivator, VoidCallback>{
            const SingleActivator(LogicalKeyboardKey.keyA, control: true):
                selectAllInList,
            const SingleActivator(LogicalKeyboardKey.keyA, meta: true):
                selectAllInList,
          },
          child: Focus(
            autofocus: true,
            child: AlertDialog(
              backgroundColor: const Color(0xFF1E1E32),
              // ── タイトル: 通常 / 選択モードで切替 ──
              title: inSelectMode
                  ? Row(children: [
                      // [×] 選択解除 (バッジ風アイコンとして使う)
                      IconButton(
                        padding: EdgeInsets.zero,
                        constraints:
                            const BoxConstraints(minWidth: 28, minHeight: 28),
                        iconSize: 18,
                        tooltip: provider.t('btn.deselectAll'),
                        icon: const Icon(Icons.close, color: Colors.white70),
                        onPressed: () {
                          setD(() {
                            selectedPaths.clear();
                            lastAnchorIndex = null;
                            // [×] は選択 + 選択モード自体を解除する
                            selectMode = false;
                          });
                        },
                      ),
                      const SizedBox(width: 6),
                      Expanded(
                        child: Text(
                          provider.t('dl.selectedCount').replaceAll(
                              '{n}', selectedPaths.length.toString()),
                          style: const TextStyle(
                              color: Colors.white, fontSize: 14),
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                    ])
                  : Row(children: [
                      const Icon(Icons.download_done_rounded,
                          color: Color(0xFFFFB347), size: 20),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(provider.t('video.downloadList'),
                            style: const TextStyle(
                                color: Colors.white, fontSize: 15),
                            overflow: TextOverflow.ellipsis),
                      ),
                      // ── [選択] ボタン ──
                      // モバイル/デスクトップ共通で、選択モードに入る入口。
                      // デスクトップは Ctrl/Shift+クリックでも入れるが、
                      // 「ボタンが見当たらない」要望に応えてタイトル右に配置。
                      // 一覧が空の時は不要なので非表示。
                      if (totalSelectable > 0)
                        TextButton.icon(
                          style: TextButton.styleFrom(
                            padding: const EdgeInsets.symmetric(
                                horizontal: 8, vertical: 4),
                            minimumSize: const Size(0, 28),
                            tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                          ),
                          icon: const Icon(Icons.checklist_rounded,
                              color: Color(0xFFFFB347), size: 16),
                          label: Text(provider.t('btn.select'),
                              style: const TextStyle(
                                  color: Color(0xFFFFB347),
                                  fontSize: 12,
                                  fontWeight: FontWeight.w600)),
                          onPressed: () {
                            setD(() {
                              // 選択モード突入。selectedPaths は空のまま。
                              // ユーザーがその後、各行のタップ / 全て選択 で
                              // 選択を進める。
                              selectMode = true;
                            });
                          },
                        ),
                    ]),
              contentPadding:
                  const EdgeInsets.symmetric(horizontal: 8, vertical: 8),
              content: SizedBox(
                width: 380,
                height: 480,
                child: FutureBuilder<List<Map<String, dynamic>>>(
                  future: _DownloadedVideosStore.load(),
                  builder: (fctx, snap) {
                    if (snap.connectionState != ConnectionState.done) {
                      return const Center(
                        child: CircularProgressIndicator(
                          color: Color(0xFFFFB347),
                          strokeWidth: 2,
                        ),
                      );
                    }
                    final list = snap.data ?? const [];
                    // タイトルバー (アクション側) で参照するため、外側変数に
                    // 反映する。FutureBuilder が再構築するたびに同期される。
                    // ── 重要 ──
                    // builder の呼び出し中に setD() を直接呼ぶと
                    // setState during build 例外になるため、
                    // postFrame で「currentList の長さが変わった時だけ」
                    // 1 度 setD を呼んでタイトルを再ビルドさせる。
                    // これがないと初回ロード時に [選択] ボタンが
                    // 出ないままになる (FutureBuilder と StatefulBuilder の
                    // 状態が分離していて、currentList の代入だけでは
                    // 親 (タイトル) は更新されないため)。
                    if (currentList.length != list.length) {
                      final prevLen = currentList.length;
                      currentList = list;
                      WidgetsBinding.instance.addPostFrameCallback((_) {
                        // 二重 setD を避ける: 既に新しい長さに揃っていれば skip
                        if (prevLen != list.length) {
                          try {
                            setD(() {});
                          } catch (_) {}
                        }
                      });
                    }
                    if (list.isEmpty) {
                      return Center(
                        child: Text(
                          provider.t('video.noDownloads'),
                          style: const TextStyle(
                              color: Colors.white54, fontSize: 13),
                        ),
                      );
                    }
                    return ListView.separated(
                      itemCount: list.length,
                      separatorBuilder: (_, __) =>
                          const Divider(color: Colors.white12, height: 1),
                      itemBuilder: (lctx, i) {
                        final r = list[i];
                        final path = r['path']?.toString() ?? '';
                        final title = r['title']?.toString() ?? '';
                        final size = (r['sizeBytes'] as num?)?.toInt() ?? 0;
                        final ts = (r['downloadedAt'] as num?)?.toInt() ?? 0;
                        final filename =
                            path.split(Platform.pathSeparator).last;
                        final dispTitle = title.isEmpty ? filename : title;
                        final isSel = selectedPaths.contains(path);

                        // ── タップハンドラ ──
                        // モディファイアキー (Ctrl/Shift) の状態で挙動を切り替える。
                        // ユーザー要望: 通常タップは「動画を再生」のみ。選択モード
                        // への入り口は明示的な [選択] ボタン (タイトル右) と
                        // Ctrl/Shift+クリック (デスクトップ) のみ。
                        // 長押しでの選択モード起動は廃止 (誤操作で選択モードに
                        // 入り、次タップが再生にならない問題があったため)。
                        void handleTap() {
                          final isCtrl =
                              HardwareKeyboard.instance.isControlPressed ||
                                  HardwareKeyboard.instance.isMetaPressed;
                          final isShift =
                              HardwareKeyboard.instance.isShiftPressed;
                          if (isShift && lastAnchorIndex != null) {
                            // Shift+クリック: アンカーから現在位置までを選択
                            final start =
                                lastAnchorIndex! < i ? lastAnchorIndex! : i;
                            final end =
                                lastAnchorIndex! < i ? i : lastAnchorIndex!;
                            setD(() {
                              for (var k = start; k <= end; k++) {
                                final p = list[k]['path']?.toString() ?? '';
                                if (p.isNotEmpty) selectedPaths.add(p);
                              }
                            });
                            return;
                          }
                          if (isCtrl) {
                            // Ctrl+クリック: 単体トグル (選択モード入り含む)
                            setD(() {
                              if (isSel) {
                                selectedPaths.remove(path);
                              } else {
                                selectedPaths.add(path);
                              }
                              lastAnchorIndex = i;
                            });
                            return;
                          }
                          if (inSelectMode) {
                            // 選択モード中の通常タップ: トグル
                            setD(() {
                              if (isSel) {
                                selectedPaths.remove(path);
                              } else {
                                selectedPaths.add(path);
                              }
                              lastAnchorIndex = i;
                            });
                            return;
                          }
                          // 通常タップ: 動画を再生
                          Navigator.pop(dctx);
                          final headerTitle = title.isNotEmpty ? title : null;
                          if (_isDesktop) {
                            _showWebDialog(context, path,
                                initialTitle: headerTitle);
                          } else {
                            _openFullscreenVideo(context,
                                url: path, initialTitle: headerTitle);
                          }
                        }

                        return Container(
                          // 選択中のハイライト (薄いオレンジ系)
                          color: isSel
                              ? const Color(0xFFFFB347).withValues(alpha: 0.12)
                              : null,
                          child: ListTile(
                            dense: true,
                            contentPadding: const EdgeInsets.symmetric(
                                horizontal: 12, vertical: 4),
                            // 選択モード中はチェックボックス、通常時はムービーアイコン
                            leading: inSelectMode
                                ? Checkbox(
                                    value: isSel,
                                    onChanged: (_) => handleTap(),
                                    activeColor: const Color(0xFFFFB347),
                                    checkColor: Colors.black,
                                    visualDensity: VisualDensity.compact,
                                    materialTapTargetSize:
                                        MaterialTapTargetSize.shrinkWrap,
                                  )
                                : const Icon(Icons.movie_rounded,
                                    color: Color(0xFF4FC3F7), size: 28),
                            title: Text(
                              dispTitle,
                              style: const TextStyle(
                                  color: Colors.white, fontSize: 13),
                              overflow: TextOverflow.ellipsis,
                              maxLines: 2,
                            ),
                            subtitle: Text(
                              '${_humanReadableBytes(size)}'
                              '${ts > 0 ? "  •  ${_relativeTime(ts)}" : ""}',
                              style: const TextStyle(
                                  color: Colors.white38, fontSize: 11),
                            ),
                            onTap: handleTap,
                            trailing: inSelectMode
                                // 選択モード中は trailing アクションを隠す
                                // (チェックボックスでの操作に集中させる)
                                ? null
                                : Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                        IconButton(
                                          tooltip:
                                              provider.t('dl.tooltipEmbed'),
                                          padding: EdgeInsets.zero,
                                          constraints: const BoxConstraints(
                                              minWidth: 32, minHeight: 32),
                                          icon: const Icon(
                                              Icons.add_to_photos_rounded,
                                              color: Color(0xFF43B97F),
                                              size: 20),
                                          onPressed: () {
                                            Navigator.pop(dctx);
                                            final tp =
                                                r['thumbPath']?.toString();
                                            _embedLocalVideoAsNode(
                                                path, dispTitle,
                                                thumbPath: tp);
                                          },
                                        ),
                                        IconButton(
                                          tooltip:
                                              provider.t('dl.tooltipDelete'),
                                          padding: EdgeInsets.zero,
                                          constraints: const BoxConstraints(
                                              minWidth: 32, minHeight: 32),
                                          icon: const Icon(Icons.close_rounded,
                                              color: Colors.redAccent,
                                              size: 20),
                                          onPressed: () async {
                                            // 単体削除確認 → 1 件だけ削除
                                            final ok = await showDialog<bool>(
                                              context: dctx,
                                              builder: (cctx) => AlertDialog(
                                                backgroundColor:
                                                    const Color(0xFF1E1E32),
                                                title: Text(
                                                    provider
                                                        .t('dl.deleteOneTitle'),
                                                    style: const TextStyle(
                                                        color: Colors.white,
                                                        fontSize: 14)),
                                                content: Text(
                                                  provider
                                                      .t('dl.deleteOneBody')
                                                      .replaceAll(
                                                          '{title}', dispTitle),
                                                  style: const TextStyle(
                                                      color: Colors.white70,
                                                      fontSize: 12),
                                                ),
                                                actions: [
                                                  TextButton(
                                                    onPressed: () =>
                                                        Navigator.pop(
                                                            cctx, false),
                                                    child: Text(
                                                        provider
                                                            .t('btn.cancel'),
                                                        style: const TextStyle(
                                                            color: Colors
                                                                .white70)),
                                                  ),
                                                  TextButton(
                                                    onPressed: () =>
                                                        Navigator.pop(
                                                            cctx, true),
                                                    child: Text(
                                                        provider
                                                            .t('btn.delete'),
                                                        style: const TextStyle(
                                                            color: Colors
                                                                .redAccent)),
                                                  ),
                                                ],
                                              ),
                                            );
                                            if (ok != true) return;
                                            // 削除前に sourceUrl を抜き取る
                                            final src =
                                                r['sourceUrl']?.toString() ??
                                                    '';
                                            try {
                                              final f = File(path);
                                              if (await f.exists())
                                                await f.delete();
                                            } catch (_) {}
                                            await _DownloadedVideosStore
                                                .removeByPath(path);
                                            // ノードの URL を元の YouTube URL に
                                            // 戻す (該当ノードがあれば)。
                                            if (src.isNotEmpty) {
                                              provider
                                                  .restoreNodesFromLocalVideos(
                                                      {path: src});
                                            }
                                            setD(() {
                                              selectedPaths.remove(path);
                                            });
                                          },
                                        ),
                                      ]),
                          ),
                        );
                      },
                    );
                  },
                ),
              ),
              actions: inSelectMode
                  ? [
                      // [全て選択] (現リスト全件をまとめて選択状態に)
                      TextButton.icon(
                        icon: const Icon(Icons.select_all_rounded,
                            color: Colors.white70, size: 18),
                        label: Text(provider.t('btn.selectAll'),
                            style: const TextStyle(color: Colors.white70)),
                        onPressed: () {
                          setD(() {
                            for (final r in currentList) {
                              final p = r['path']?.toString() ?? '';
                              if (p.isNotEmpty) selectedPaths.add(p);
                            }
                          });
                        },
                      ),
                      // [{n} 件削除] (赤色強調)
                      ElevatedButton.icon(
                        style: ElevatedButton.styleFrom(
                            backgroundColor: Colors.redAccent,
                            foregroundColor: Colors.white,),
                        icon: const Icon(Icons.delete_outline,
                            size: 18, color: Colors.white),
                        label: Text(
                          '${provider.t('btn.delete')} (${selectedPaths.length})',
                          style: const TextStyle(color: Colors.white),
                        ),
                        onPressed: () async {
                          // 確認ダイアログ
                          final n = selectedPaths.length;
                          final confirmed = await showDialog<bool>(
                            context: dctx,
                            builder: (cctx) => AlertDialog(
                              backgroundColor: const Color(0xFF1E1E32),
                              title: Text(
                                  provider
                                      .t('dl.bulkDeleteConfirmTitle')
                                      .replaceAll('{n}', n.toString()),
                                  style: const TextStyle(
                                      color: Colors.white, fontSize: 14)),
                              content: Text(
                                  provider.t('dl.bulkDeleteConfirmBody'),
                                  style: const TextStyle(
                                      color: Colors.white70, fontSize: 12)),
                              actions: [
                                TextButton(
                                  onPressed: () => Navigator.pop(cctx, false),
                                  child: Text(provider.t('btn.cancel'),
                                      style: const TextStyle(
                                          color: Colors.white70)),
                                ),
                                ElevatedButton.icon(
                                  autofocus: true, // Enter で即削除に進む
                                  style: ElevatedButton.styleFrom(
                                      backgroundColor: Colors.redAccent,
                                      foregroundColor: Colors.white,),
                                  icon: const Icon(Icons.delete_outline,
                                      size: 16, color: Colors.white),
                                  label: Text(provider.t('btn.delete'),
                                      style:
                                          const TextStyle(color: Colors.white)),
                                  onPressed: () => Navigator.pop(cctx, true),
                                ),
                              ],
                            ),
                          );
                          if (confirmed != true) return;
                          // ファイル実体を削除する **前** に、各 path に紐づく
                          // 元 URL (sourceUrl) を取得しておく。
                          // 削除後にノードのローカルパスを元 URL に書き戻すため、
                          // ファイル削除より先に sourceUrl を抜き取る順序が重要。
                          final paths = selectedPaths.toList();
                          final allRecords =
                              await _DownloadedVideosStore.load();
                          final restorations = <String, String>{};
                          for (final r in allRecords) {
                            final p = r['path']?.toString() ?? '';
                            final src = r['sourceUrl']?.toString() ?? '';
                            if (paths.contains(p) && src.isNotEmpty) {
                              restorations[p] = src;
                            }
                          }
                          // ファイル実体を削除 (失敗しても続行)
                          for (final p in paths) {
                            try {
                              final f = File(p);
                              if (await f.exists()) await f.delete();
                            } catch (_) {}
                          }
                          // ストアからもまとめて除去
                          await _DownloadedVideosStore.removeByPaths(paths);
                          // ノードの youtubeUrl を元の YouTube URL に戻す。
                          // これで「オフライン」バッジが消え、CDN サムネが復活。
                          // 全ページ走査するので、別マップに置かれているノード
                          // でも復元される。
                          provider.restoreNodesFromLocalVideos(restorations);
                          // ダイアログをリビルド + 選択解除 + 選択モードも解除
                          // (削除後は通常表示に戻る)
                          setD(() {
                            selectedPaths.clear();
                            lastAnchorIndex = null;
                            selectMode = false;
                          });
                          // SnackBar で完了通知
                          if (!ctx.mounted) return;
                          _appSnack(
                              ctx,
                              SnackBar(
                                content: Text(
                                    provider
                                        .t('dl.bulkDeletedDone')
                                        .replaceAll('{n}', n.toString()),
                                    style: const TextStyle(fontSize: 12)),
                                backgroundColor: const Color(0xFF43B97F),
                                duration: const Duration(seconds: 3),
                              ));
                        },
                      ),
                    ]
                  : [
                      TextButton(
                        onPressed: () => Navigator.pop(dctx),
                        child: Text(provider.t('btn.close'),
                            style: const TextStyle(color: Colors.white70)),
                      ),
                    ],
            ),
          ),
        );
      }),
    );
  }

  /// バイト数を人間に読みやすい文字列にする (1.2 MB / 345 KB 等)。
  /// `_FullscreenVideoPageState._humanBytes` と同等。両クラスで使うので
  /// MindMapScreenState 側にも持つ。
  String _humanReadableBytes(int bytes) {
    if (bytes < 1024) return '$bytes B';
    if (bytes < 1024 * 1024) {
      return '${(bytes / 1024).toStringAsFixed(1)} KB';
    }
    if (bytes < 1024 * 1024 * 1024) {
      return '${(bytes / 1024 / 1024).toStringAsFixed(1)} MB';
    }
    return '${(bytes / 1024 / 1024 / 1024).toStringAsFixed(2)} GB';
  }

  /// UNIX ミリ秒タイムスタンプを「3 分前 / 2 時間前 / 1 日前」のような
  /// 相対表現に変換する。1 週間以上は yyyy/MM/dd 表記。
  String _relativeTime(int unixMs) {
    final now = DateTime.now().millisecondsSinceEpoch;
    final diff = now - unixMs;
    if (diff < 60 * 1000) return 'たった今';
    if (diff < 60 * 60 * 1000) {
      return '${(diff / 60 / 1000).floor()}分前';
    }
    if (diff < 24 * 60 * 60 * 1000) {
      return '${(diff / 60 / 60 / 1000).floor()}時間前';
    }
    if (diff < 7 * 24 * 60 * 60 * 1000) {
      return '${(diff / 24 / 60 / 60 / 1000).floor()}日前';
    }
    final dt = DateTime.fromMillisecondsSinceEpoch(unixMs);
    return '${dt.year}/${dt.month.toString().padLeft(2, "0")}/'
        '${dt.day.toString().padLeft(2, "0")}';
  }

  // ─── 範囲選択ノードの YouTube 一括ダウンロード ────────────────────────────

  /// 範囲選択中のノードに、まだローカル化されていない YouTube 動画 URL が
  /// 1 つ以上あるか判定する。範囲選択メニュー / 一括 DL ボタンの表示条件。
  bool _selectedNodesHaveYoutubeVideos(MindMapProvider provider) {
    // リリース前コンプライアンス対応:
    // YouTube 動画の端末保存は YouTube 規約上リスクが高いため、表示条件を常に false にする。
    return false;
  }

  /// ファイル名 sanitize (一括 DL 用)。
  ///
  /// 重要: 半角の禁止文字 (`<>:"/\|?*` 等) だけでなく、**ASCII 範囲外の
  /// 文字すべて (CJK / 全角記号 / 絵文字 / 全角 ！？「」 等) も `_` に
  /// 置換する**。これは Android の `video_player_android` プラグインが、
  /// `VideoPlayerController.file(File(path))` 内で path → file URI に
  /// 変換するときに non-ASCII を正しくエスケープできず初期化失敗する
  /// ケースがあるため。タイトル中の日本語等はファイル名から落ちるが、
  /// ノードのタイトル表示や DL 一覧は `record['title']` (= 元の生タイトル)
  /// から引くので体感には影響しない。
  String _bulkSanitizeFilename(String name) {
    var s = name
        // 半角の Windows 禁止文字 + 制御文字
        .replaceAll(RegExp(r'[<>:"/\\|?*\x00-\x1F]'), '_')
        // ASCII 範囲外を全部 `_` に
        .replaceAll(RegExp(r'[^\x20-\x7E]'), '_')
        .trim()
        .replaceAll(RegExp(r'\s+'), '_')
        // 連続 `_` を 1 つに圧縮
        .replaceAll(RegExp(r'_+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
    if (s.length > 60) s = s.substring(0, 60);
    if (s.isEmpty) s = 'video';
    return s;
  }

  /// 同名ファイルが既に存在する場合は `_1`, `_2` のサフィックスを付ける。
  String _bulkEnsureUniquePath(String path) {
    if (!File(path).existsSync()) return path;
    final dot = path.lastIndexOf('.');
    final stem = dot >= 0 ? path.substring(0, dot) : path;
    final ext = dot >= 0 ? path.substring(dot) : '';
    for (var i = 1; i < 1000; i++) {
      final candidate = '${stem}_$i$ext';
      if (!File(candidate).existsSync()) return candidate;
    }
    return path;
  }

  /// 範囲選択中のノードのうち YouTube 動画 URL を持つものを一括で
  /// ダウンロードして、各ノードの `youtubeUrl` を保存先のローカルパスに
  /// 置換する (= オフラインで視聴できるようにする)。
  ///
  /// 動作:
  ///   1. 対象 (videoId が抽出できる YouTube URL を持つノード) を収集
  ///   2. 確認ダイアログ「N 件をダウンロードします」
  ///   3. 進捗ダイアログ (キャンセル不可) を出して 1 件ずつ DL
  ///   4. 各 DL 完了で:
  ///      - `_DownloadedVideosStore` にレコード追加
  ///      - `provider.updateNodeYoutube(nodeId, localPath)` で URL 置換
  ///      - `provider.generateVideoThumbnail(nodeId)` でサムネ生成
  ///   5. 全件処理後、進捗ダイアログを閉じて結果 SnackBar を表示
  ///
  /// 失敗したノードは元の YouTube URL のまま残るので、再試行可能。
  /// `_DownloadedVideosStore.sourceUrl` に元 URL が残るので後から復元可能。
  /// YouTube の hqdefault.jpg / maxresdefault.jpg をダウンロードして
  /// 端末のキャッシュ領域に保存する。成功したらローカルパスを、失敗
  /// したら `null` を返す。
  ///
  /// 動画 DL と一緒に呼んで `videoThumbnailPath` にセットする用。
  /// (= ノードの再生サムネを即座に表示できる)
  ///
  /// 試す URL:
  ///   1. https://i.ytimg.com/vi/{id}/hqdefault.jpg     (16:9 480x360)
  ///   2. https://i.ytimg.com/vi/{id}/sddefault.jpg     (16:9 640x480, 高画質)
  /// 1 が失敗した場合は 2 にフォールバック。
  Future<String?> _downloadYoutubeThumbnail(
      String videoId, Directory baseDir) async {
    final urls = [
      'https://i.ytimg.com/vi/$videoId/sddefault.jpg',
      'https://i.ytimg.com/vi/$videoId/hqdefault.jpg',
    ];
    final thumbDir =
        Directory('${baseDir.path}${Platform.pathSeparator}video_thumbs');
    try {
      if (!await thumbDir.exists()) {
        await thumbDir.create(recursive: true);
      }
    } catch (_) {
      return null;
    }
    final outPath = '${thumbDir.path}${Platform.pathSeparator}yt_$videoId.jpg';
    for (final url in urls) {
      try {
        final resp =
            await http.get(Uri.parse(url)).timeout(const Duration(seconds: 15));
        if (resp.statusCode == 200 && resp.bodyBytes.isNotEmpty) {
          // hqdefault は存在しないとき 404 ではなく 120x90 のグレー画像を
          // 返してくる場合がある。ボディサイズが極端に小さければスキップ。
          if (resp.bodyBytes.length < 1024) continue;
          await File(outPath).writeAsBytes(resp.bodyBytes);
          return outPath;
        }
      } catch (e) {
        debugPrint('Thumbnail fetch failed ($url): $e');
      }
    }
    return null;
  }

  /// ドラッグ&ドロップでメモを追加するターゲットになるノードを検出する。
  /// 引数 [dropPoint] は canvas 座標系のドロップ位置 (カーソル位置)。
  ///
  /// 検出ルール:
  ///   - 現在の選択 (`_rangeSelectedIds`) に含まれるノードは対象外
  ///   - 格納ノードに隠されているノードも対象外
  ///   - 添付ファイルが .pdf で終わる、 または `linkUrl` が空でない
  ///     (= PDF / ハイパーリンクノード) のみ対象
  ///   - ノードの矩形が [dropPoint] を含むこと
  MindMapNode? _detectMemoDropTarget(
      MindMapProvider provider, Offset dropPoint) {
    for (final node in provider.nodes.values) {
      if (node.hiddenInContainer != null) continue;
      if (_rangeSelectedIds.contains(node.id)) continue;
      final att = (node.attachmentPath ?? '').toLowerCase();
      final isPdf = att.endsWith('.pdf');
      final isLink = (node.linkUrl ?? '').isNotEmpty;
      if (!isPdf && !isLink) continue;
      final rect = Rect.fromLTWH(
        node.position.dx,
        node.position.dy,
        node.width,
        node.visualHeight,
      );
      if (rect.contains(dropPoint)) return node;
    }
    return null;
  }

  /// ドロップで検出された PDF/リンクターゲットノード [target] に対し、
  /// 選択中の複数ノード [sourceIds] をメモとして変換 (= 追加 + 元削除)。
  /// 確認ダイアログを挟み、 ユーザーが承認した時だけ反映する。
  Future<void> _confirmAddNodesAsMemos(
    BuildContext ctx,
    MindMapProvider provider,
    MindMapNode target,
    Set<String> sourceIds,
  ) async {
    final isPdf = (target.attachmentPath ?? '').toLowerCase().endsWith('.pdf');
    final targetKind = isPdf ? 'PDF' : 'リンク';
    final ok = await showDialog<bool>(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E1E),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        title: Row(children: [
          Icon(
            isPdf ? Icons.picture_as_pdf_rounded : Icons.link_rounded,
            color: const Color(0xFF4FC3F7),
            size: 20,
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              '$targetKindにメモとして変換',
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 15,
                  fontWeight: FontWeight.w700),
            ),
          ),
        ]),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              '${sourceIds.length}個のノードを '
              '「${target.title.isEmpty ? '(無題)' : target.title}」'
              'のメモに変換しますか？',
              style: const TextStyle(color: Colors.white70, fontSize: 12.5),
            ),
            const SizedBox(height: 8),
            const Text(
              '※ 元のノードはマップから削除されます',
              style: TextStyle(color: Color(0xFFE57373), fontSize: 11.5),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, false),
            child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                style: const TextStyle(color: Colors.white60)),
          ),
          ElevatedButton.icon(
            autofocus: true,
            style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFF43B97F),
              foregroundColor: Colors.black,
            ),
            onPressed: () => Navigator.pop(dctx, true),
            icon: const Icon(Icons.swap_horiz_rounded, size: 16),
            label: Text(context.read<MindMapProvider>().t('btn.convert')),
          ),
        ],
      ),
    );
    if (ok != true) return;
    if (!mounted) return;

    // 成功したソース ID を集めて、 後でまとめて削除する。
    final addedSourceIds = <String>{};
    for (final sid in sourceIds) {
      final memo = provider.addPdfMemoFromDroppedNode(
        targetNodeId: target.id,
        sourceNodeId: sid,
      );
      if (memo != null) addedSourceIds.add(sid);
    }
    if (addedSourceIds.isNotEmpty) {
      provider.deleteNodes(addedSourceIds);
    }
    setState(() {
      _rangeSelectedIds.removeAll(addedSourceIds);
      if (_rangeSelectedIds.isEmpty) {
        _rangeSelectMode = false;
      }
    });
    if (!mounted) return;
    _appSnack(
        context,
        SnackBar(
          content: Text(
            '${addedSourceIds.length}個のノードを '
            '「${target.title.isEmpty ? '(無題)' : target.title}」 '
            'のメモに変換しました',
            style: const TextStyle(fontSize: 12),
          ),
          backgroundColor: const Color(0xFF43B97F),
          duration: const Duration(seconds: 3),
        ));
  }

  /// 画面の端 (右下) に出すダウンロード進捗インジケータ。
  /// (= ユーザー要望: 中央のダイアログではなく端に割合を表示し、 そこを
  ///  タップするとダウンロードを中止できるように)。
  ///   * [overall] 0.0〜1.0 の全体進捗 (円グラフ + %)。
  ///   * [label]   現在処理中の項目名など (2 行まで)。
  ///   * [onCancel] インジケータをタップした時の中止処理。
  /// 戻り値の OverlayEntry を完了時に remove() すること。
  OverlayEntry _insertDownloadCornerIndicator({
    required ValueListenable<double> overall,
    required ValueListenable<String> label,
    required VoidCallback onCancel,
  }) {
    final entry = OverlayEntry(builder: (octx) {
      final mq = MediaQuery.of(octx);
      return Positioned(
        right: 14,
        bottom: 14 + mq.padding.bottom,
        child: Material(
          color: Colors.transparent,
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: onCancel,
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
              decoration: BoxDecoration(
                color: const Color(0xFF1E1E32).withOpacity(0.96),
                borderRadius: BorderRadius.circular(14),
                border: Border.all(color: const Color(0xFF43B97F), width: 1),
                boxShadow: const [
                  BoxShadow(color: Colors.black54, blurRadius: 8)
                ],
              ),
              child: Row(mainAxisSize: MainAxisSize.min, children: [
                ValueListenableBuilder<double>(
                  valueListenable: overall,
                  builder: (_, v, __) => SizedBox(
                    width: 38,
                    height: 38,
                    child: Stack(alignment: Alignment.center, children: [
                      CircularProgressIndicator(
                        value: (v <= 0 || v > 1) ? null : v,
                        strokeWidth: 3.5,
                        color: const Color(0xFF43B97F),
                        backgroundColor: Colors.white12,
                      ),
                      Text('${(v.clamp(0.0, 1.0) * 100).round()}%',
                          style: const TextStyle(
                              color: Colors.white,
                              fontSize: 9,
                              fontWeight: FontWeight.bold)),
                    ]),
                  ),
                ),
                const SizedBox(width: 10),
                ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 190),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      ValueListenableBuilder<String>(
                        valueListenable: label,
                        builder: (_, t, __) => Text(t,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: Colors.white, fontSize: 11)),
                      ),
                      const SizedBox(height: 2),
                      Row(mainAxisSize: MainAxisSize.min, children: [
                        Icon(Icons.stop_circle_rounded,
                            color: Color(0xFFE57373), size: 13),
                        SizedBox(width: 3),
                        Text(
                            context
                                .read<MindMapProvider>()
                                .t('common.tapToCancel'),
                            style: TextStyle(
                                color: Color(0xFFE57373), fontSize: 10)),
                      ]),
                    ],
                  ),
                ),
              ]),
            ),
          ),
        ),
      );
    });
    final overlay = Overlay.of(context, rootOverlay: true);
    overlay.insert(entry);
    return entry;
  }

  Future<void> _bulkDownloadSelectedYoutubeVideos(
      BuildContext ctx, MindMapProvider provider) async {
    if (!ctx.mounted) return;
    _appSnack(
        ctx,
        SnackBar(
          content: Text(ctx.read<MindMapProvider>().t('dl.disabledRelease')),
          backgroundColor: const Color(0xFF2A2A3E),
        ));
  }

  /// 範囲選択中に画像/添付とYouTube動画の両方が含まれている時に
  /// 1ボタンで両方を一括ダウンロードするための統合メソッド。
  ///
  /// - 画像/添付ファイル → `_bulkDownloadSelectedAttachments`
  /// - YouTube動画       → `_bulkDownloadSelectedYoutubeVideos`
  ///
  /// それぞれの選択肢が存在する場合のみ順次実行する。
  /// 添付ファイルの方がデスクトップで保存先ディレクトリ選択ダイアログを
  /// 出すため、それを先に走らせる (キャンセルでも YouTube 側は続行)。
  Future<void> _bulkDownloadSelectedMixed(
      BuildContext ctx, MindMapProvider provider) async {
    final hasAttachments = _selectedNodesHaveAttachments(provider);
    final hasYoutube = _selectedNodesHaveYoutubeVideos(provider);
    if (hasAttachments) {
      await _bulkDownloadSelectedAttachments(ctx, provider);
    }
    if (!mounted) return;
    if (hasYoutube) {
      await _bulkDownloadSelectedYoutubeVideos(ctx, provider);
    }
  }

  /// アプリ内 WebView では OAuth ポップアップが動かないサイトかどうか。
  ///
  /// Google などはセキュリティ上、埋め込みブラウザでのログインを拒否する。
  /// URL の部分一致は偽装ホストも拾うため、共有ヘルパーで host を厳密比較する。
  bool _isOAuthBlockedUrl(String url) {
    return isBlockedEmbeddedOAuthUrl(url);
  }

  Future<void> _launchUrl(String url, {String? nodeId}) async {
    final uri = Uri.tryParse(url);
    if (uri == null) return;
    // ── OAuth がブロックされるサイトは強制外部ブラウザ ──
    // claude.ai 等で Google ログインを試みると暗転するため、 ここで
    // アプリ内ビューアをスキップする。
    if (_isOAuthBlockedUrl(url)) {
      try {
        await launchUrl(uri, mode: LaunchMode.externalApplication);
        if (mounted) {
          _appSnack(
            context,
            SnackBar(
              content: Text(
                  context.read<MindMapProvider>().t('split.openedExternal')),
              backgroundColor: Color(0xFF6C63FF),
              duration: Duration(seconds: 3),
            ),
          );
        }
        return;
      } catch (e) {
        debugPrint('外部ブラウザ起動失敗: $e');
        // フォールスルー: 通常処理にフォールバック
      }
    }
    // ── YouTube の URL は専用 YouTube ビューアで開く ──
    // ユーザー要望: 「URL から YouTube を開く時に上部に表示されるボタンも
    //   YouTube のカスタムボタンから開いた時に表示されるボタンと揃えて」。
    // /watch 以外 (チャンネル / 検索 / youtu.be 等) は呼び出し元で動画判定
    //   されず汎用ビューアに来てしまい、 上部ボタンの構成が変わっていた。
    //   ここで YouTube ドメインを拾い、 カスタムボタンと同じ
    //   `_showWebDialog` / `_openFullscreenVideo` (= 同じ上部ボタン) へ回す。
    final lowerUrl = url.toLowerCase();
    final isYoutubeUrl =
        lowerUrl.contains('youtube.com') || lowerUrl.contains('youtu.be');
    if (mounted &&
        isYoutubeUrl &&
        context.read<MindMapProvider>().openLinksInApp) {
      if (_isDesktop) {
        _showWebDialog(context, url);
      } else {
        _openFullscreenVideo(context, url: url);
      }
      return;
    }
    // ── アプリ内ビューア優先 ──
    // ユーザー設定 `openLinksInApp` (デフォルト true) が true なら、
    // 外部ブラウザではなく WebView ベースのアプリ内ビューアで開く。
    // 動画系 (YouTube / mp4) は呼び出し元の `_openLink` 側で先に
    // 専用プレイヤーへ振り分けられるので、 ここに来るのは「動画ではない
    // 通常 URL」 のみ。
    // [nodeId] が渡されると、 ビューア内でその URL に紐づくメモを
    // 残せる (= サイトを見ながらメモを書く機能)。
    if (mounted && context.read<MindMapProvider>().openLinksInApp) {
      try {
        await _showInAppViewer(context, url, nodeId: nodeId);
        return;
      } catch (e) {
        // フォールバック: 何らかの理由でアプリ内表示に失敗 → 外部ブラウザ
        debugPrint('In-app viewer failed, falling back to external: $e');
      }
    }
    try {
      await launchUrl(uri, mode: LaunchMode.externalApplication);
    } catch (_) {
      if (mounted) {
        _appSnack(
          context,
          SnackBar(
              content: Text(context
                  .read<MindMapProvider>()
                  .t('common.cannotOpenUrl')
                  .replaceFirst('{url}', url))),
        );
      }
    }
  }

  /// アプリ内ビューア (汎用 URL / PDF) を開く。
  ///
  /// パラメータ:
  ///   - [urlOrPath]: HTTP URL もしくはローカルファイルパス
  ///   - [isLocalFile]: true の場合 `urlOrPath` をローカルファイルとみなして
  ///     `file://` URI に変換する
  ///   - [nodeId]: PDF の場合に渡すと、 ビューア内で PDFメモの追加・編集が
  ///     できるようになる (= ノードに `pdfMemos` を紐づけるため)
  ///
  /// プラットフォーム分岐:
  ///   - デスクトップ (Win/macOS/Linux): `_InAppViewerDialog` を Dialog で
  ///     表示。 中身は webview_windows (Windows) もしくは flutter_inappwebview
  ///     (macOS/Linux) で WebView を埋め込む。
  ///   - モバイル: `_InAppViewerPage` をフルスクリーン Navigator.push で開く。
  ///
  /// 戻り値: ダイアログ / ページの dismiss を待つ Future。
  /// 「プログラムから開く」 でこのアプリに渡されたファイルを処理する
  /// (= ユーザー要望: 確認を取らずにいきなり開く)。
  ///
  /// マップへの追加はビューア内の「ページに追加」 ボタン、 またはメモ /
  /// AI を使った時点で行われる (= 開いただけではマップを汚さない)。
  /// 起動済みの本体へ「アプリで開く」 のファイルが引き渡された時 (= main()
  /// の待ち受けが受信した時) に呼ばれる。 既に開いている画面の上で開く。
  void _onOpenWithFilesArrived() {
    if (!mounted) return;
    // ignore: discarded_futures
    _handlePendingOpenFiles();
  }

  Future<void> _handlePendingOpenFiles() async {
    if (pendingOpenFilePaths.isEmpty || !mounted) return;
    final paths = List<String>.from(pendingOpenFilePaths);
    pendingOpenFilePaths.clear();
    // ── 動画などの画面を表示中なら、 どう開くかを先に選ぶ ──
    // (= ユーザー報告: YouTube を開いている時に PDF を上に開いたら、 下の
    //  YouTube 画面に戻した時にフリーズした。 重ねて開かず、 今の画面を
    //  閉じて開くか、 新しいアプリを立ち上げて開くかを選べるように)。
    final nav = Navigator.of(context, rootNavigator: true);
    if (_isDesktop && nav.canPop()) {
      final provider = context.read<MindMapProvider>();
      final choice = await showDialog<String>(
        context: context,
        useRootNavigator: true,
        builder: (dctx) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            const Icon(Icons.layers_rounded,
                color: Color(0xFFFFB347), size: 20),
            const SizedBox(width: 8),
            Expanded(
              child: Text(provider.t('openWith.busyTitle'),
                  style: const TextStyle(color: Colors.white, fontSize: 15)),
            ),
          ]),
          content: Text(provider.t('openWith.busyMsg'),
              style: const TextStyle(
                  color: Colors.white70, fontSize: 13, height: 1.5)),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            TextButton(
              onPressed: () => Navigator.pop(dctx, 'newWindow'),
              child: Text(provider.t('openWith.busyNewWindow'),
                  style: const TextStyle(color: Color(0xFF4FC3F7))),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6C63FF),
                  foregroundColor: Colors.white),
              onPressed: () => Navigator.pop(dctx, 'overwrite'),
              child: Text(provider.t('openWith.busyOverwrite')),
            ),
          ],
        ),
      );
      if (!mounted || choice == null) return; // キャンセル = 何もしない
      if (choice == 'newWindow') {
        // 別プロセスで開く。 --new-window を付けると 2 個目側は起動済みの
        // 本体へ引き渡さず、 そのまま新しいウィンドウとして立ち上がる。
        try {
          await Process.start(
              Platform.resolvedExecutable, ['--new-window', ...paths],
              mode: ProcessStartMode.detached);
        } catch (_) {}
        return;
      }
      // 上書き: 開いている画面 (動画 / ビューア等) を全部閉じてから開く。
      // WebView の後始末が終わる前に次のビューアを重ねるとフリーズの原因に
      // なるため、 少しだけ待つ。
      nav.popUntil((r) => r.isFirst);
      await Future.delayed(const Duration(milliseconds: 400));
      if (!mounted) return;
    }
    // ── 保存データの読み込みは待たずに、 すぐビューアを開く ──
    // (= ユーザー要望: 「アプリから開く」 で立ち上がるまでが遅い)。
    // 以前はここで読み込み完了を待っていたが、 それは「マップに追加」 した
    // ノードが読み込み完了時に差し替えられて消えるのを防ぐためだった。
    // 待ち合わせは追加する瞬間 (onEnsureNode) に移したので、 表示だけなら
    // 読み込みを待つ必要がない。
    if (!mounted) return;
    for (final path in paths) {
      if (!mounted) return;
      await _openExternalFileByKind(path);
    }
  }

  /// 「プログラムから開く」 で渡されたファイルを種類ごとに開く
  /// (= ユーザー要望: 動画ビューワー / エディター、 ペイントアプリとしても
  ///  既定のアプリにできるように)。
  Future<void> _openExternalFileByKind(String path) async {
    final lower = path.toLowerCase();
    bool hasExt(List<String> exts) => exts.any(lower.endsWith);

    // ── 動画: 全画面プレイヤーで開く ──
    if (hasExt(const ['.mp4', '.mkv', '.webm', '.mov', '.avi', '.m4v'])) {
      final url = Uri.file(path, windows: Platform.isWindows).toString();
      await _openFullscreenVideo(context, url: url, initialTitle: _baseName(path));
      return;
    }
    // ── 画像: 画像エディタ (ペイント) で開く ──
    if (hasExt(const ['.png', '.jpg', '.jpeg', '.gif', '.bmp', '.webp'])) {
      if (!mounted) return;
      _gViewerOpenSw = Stopwatch()..start();
      _viewerMark('image tap');
      // 分割中は分割セルの中で開く (= ユーザー要望: 他のファイルと同じに)。
      if (_canEmbedIntoMapSplit()) {
        _embedViewerIntoMapSplitCell((_) => ColoredBox(
              color: const Color(0xFF1A1A24),
              child: _ImageEditorDialog(
                filePath: path,
                fileName: _baseName(path),
                useRootNavigator: false,
              ),
            ));
        return;
      }
      await showDialog<void>(
        context: context,
        useRootNavigator: true,
        barrierColor: Colors.black.withValues(alpha: 0.92),
        builder: (_) => _ImageEditorDialog(
          filePath: path,
          fileName: _baseName(path),
        ),
      );
      return;
    }
    // ── テキスト / Markdown 等はアプリ内テキストエディタで開く ──
    // (= ユーザー要望: マークダウン形式を開いた時にプレビュー機能が無い。
    //  ビューアの素のテキスト表示ではなく、 添付ファイルと同じテキスト
    //  エディタで開く。 .md はエディタの Markdown / Mermaid プレビューが
    //  使える)。
    {
      final dot = lower.lastIndexOf('.');
      final ext = dot >= 0 ? lower.substring(dot + 1) : '';
      if (_kTextEditorExts.contains(ext)) {
        final ex = await _findEmbeddedAttachmentFor(path);
        if (!mounted) return;
        await _openAttachment(ex?.path ?? path, nodeId: ex?.nodeId);
        return;
      }
    }
    // ── 既に同じファイルをマップへ埋め込み済みなら、 そのノードで開く ──
    // (= ユーザー要望: アプリで開くを選んだ時、 既に挿入されている所で
    //  開かれるように)。 そのページへ切り替えてノードを見せた上で、
    //  ノード紐付きのビューア (メモ / AI がそのまま使える) を開く。
    final existing = await _findEmbeddedAttachmentFor(path);
    if (existing != null && mounted) {
      final provider = context.read<MindMapProvider>();
      final idx = provider.pages.indexWhere((p) => p.id == existing.pageId);
      if (idx >= 0) {
        if (provider.currentPage.id != existing.pageId) {
          provider.switchPage(idx);
        }
        provider.selectNode(existing.nodeId);
        final n = provider.nodes[existing.nodeId];
        if (n != null) {
          try {
            _ctrlFor(existing.pageId).value =
                _matrixFor(n.position, _percentToScale(_scalePercent));
          } catch (_) {}
        }
        _appSnack(
          context,
          SnackBar(
            content: Text(provider.t('openWith.openedExisting')),
            backgroundColor: const Color(0xFF43B97F),
            duration: const Duration(seconds: 2),
          ),
        );
        await _showInAppViewer(context, existing.path,
            isLocalFile: true, nodeId: existing.nodeId);
        return;
      }
    }
    if (!mounted) return;
    // それ以外 (PDF / 文書 など) は従来どおりビューアで開く。
    await _showInAppViewer(context, path, isLocalFile: true);
  }

  /// [path] と同じファイルを添付しているノードを全ページから探す
  /// (= ユーザー要望: 既に埋め込んだ PDF を「アプリで開く」 したら、 既に
  ///  挿入されている所で開く)。
  ///
  /// ドロップで埋め込んだファイルは attachments フォルダへコピーされて
  /// パスが変わっているので、 パス一致に加えて 「ファイル名 + サイズが同じ」
  /// も同一とみなす。 見つからなければ null。
  Future<({String pageId, String nodeId, String path})?>
      _findEmbeddedAttachmentFor(String path) async {
    final provider = context.read<MindMapProvider>();
    // 起動直後はまだページが読み込まれていないので少しだけ待つ
    // (読み込みが遅くても最大 ~3 秒で諦めて普通に開く)。
    try {
      await provider.initialLoadDone.timeout(const Duration(seconds: 2));
    } catch (_) {}
    for (var i = 0; i < 10 && provider.pages.isEmpty; i++) {
      await Future.delayed(const Duration(milliseconds: 100));
    }
    final base = _baseName(path).toLowerCase();
    int size = -1;
    try {
      size = File(path).lengthSync();
    } catch (_) {}
    for (final p in provider.pages) {
      for (final n in p.nodes.values) {
        final ap = n.attachmentPath;
        if (ap == null || ap.isEmpty) continue;
        if (ap == path) return (pageId: p.id, nodeId: n.id, path: ap);
        if (_baseName(ap).toLowerCase() != base) continue;
        try {
          final f = File(ap);
          if (!f.existsSync()) continue;
          if (size >= 0 && f.lengthSync() == size) {
            return (pageId: p.id, nodeId: n.id, path: ap);
          }
        } catch (_) {}
      }
    }
    return null;
  }

  String _baseName(String path) => path.split(RegExp(r'[/\\]')).last;

  /// ページ種別 → マップ一覧 (Drawer) と同じアイコンと色
  /// (= ユーザー要望: 別ページに送る等の選択肢のアイコンをマップ一覧と
  ///  揃える)。 `_DrawerTile` の leading と同じ対応表。
  /// ページ一覧などに出すアイコンと色。 利用者の指定があればそれを使う。
  static (IconData, Color) _pageKindIconOfWith(
      MindMapProvider provider, MindMapPage p) {
    final (icon, color) = _pageKindIconOf(p);
    return (pageIconFor(provider, p, icon), color);
  }

  static (IconData, Color) _pageKindIconOf(MindMapPage p) {
    switch (p.pageType) {
      case 'bookshelf':
        return (Icons.shelves, const Color(0xFFFF7043));
      case 'paint':
        return (Icons.brush_rounded, const Color(0xFFEC407A));
      case 'document':
        return (Icons.article_rounded, const Color(0xFF4FC3F7));
      // Markdown / 図 (Mermaid) ページ専用のアイコン (= ユーザー要望)。
      case 'markdown':
        return (Icons.polyline_rounded, const Color(0xFF5FD3B2));
      case 'videoEditor':
        return (Icons.movie_creation_rounded, const Color(0xFFFF7043));
      default:
        return (Icons.map, const Color(0xFF8B84FF));
    }
  }

  /// 開いている添付ノードを別のページへ移す (= ユーザー要望: 開いている
  /// PDF をページに埋め込んだり移動したりできるように)。
  Future<void> _moveAttachmentNodeToPage(String nodeId) async {
    final provider = context.read<MindMapProvider>();
    final curId = provider.currentPage.id;
    final targets = provider.pages
        .where((p) => p.id != curId && p.pageType != 'videoEditor')
        .toList();
    if (targets.isEmpty) {
      _appSnack(context,
          SnackBar(content: Text(provider.t('move.noTarget'))));
      return;
    }
    final targetId = await showDialog<String>(
      context: context,
      builder: (dctx) => SimpleDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('pdf.moveToOtherPage'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        children: [
          for (final p in targets)
            SimpleDialogOption(
              onPressed: () => Navigator.pop(dctx, p.id),
              child: Row(children: [
                // ページ種別ごとのアイコン (= マップ一覧と同じ見た目)。
                Icon(_pageKindIconOfWith(provider, p).$1,
                    color: _pageKindIconOfWith(provider, p).$2, size: 18),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(p.name,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(color: Colors.white)),
                ),
              ]),
            ),
        ],
      ),
    );
    if (targetId == null || !mounted) return;
    final idx = provider.pages.indexWhere((p) => p.id == targetId);
    if (idx < 0) return;
    provider.moveNodesToPage({nodeId}, idx);
    if (!mounted) return;
    final name = provider.pages[idx].name;
    _appSnack(
      context,
      SnackBar(
        content:
            Text(provider.t('pdf.movedToPage').replaceFirst('{name}', name)),
        backgroundColor: const Color(0xFF43B97F),
      ),
    );
  }

  /// ファイルを添付したノードを画面中央に作る (= ユーザー要望: マップに
  /// テキストや PDF を埋め込めるように)。
  String? _embedFileAsNode(
      MindMapProvider provider, String path, String fileName,
      {String? pageId}) {
    // ページがまだ無い (= 読み込み中) 間は追加しない。 追加してもロード完了時に
    // 差し替えられて消えるため (= ユーザー報告のバグ)。
    if (provider.pages.isEmpty) {
      _appSnack(
        context,
        SnackBar(
            content: Text(provider.t('openWith.notReady')),
            backgroundColor: const Color(0xFFE57373)),
      );
      return null;
    }
    // 追加先ページが指定されていて、 それが今開いているページでなければ
    // そのページへ直接作る (= ユーザー要望: 追加先を選べるように)。
    if (pageId != null && pageId != provider.currentPage.id) {
      final idx = provider.pages.indexWhere((p) => p.id == pageId);
      if (idx >= 0) {
        final id =
            provider.addAttachmentNodeToPage(idx, path, fileName);
        if (id != null) {
          // 1 枚目のサムネイルも付ける (= ユーザー報告: アプリから開くで
          // 埋め込むとサムネイルが表示されない)。
          _generateEmbedAttachmentThumb(provider, id, path);
          _appSnack(
            context,
            SnackBar(
              content: Text(provider
                  .t('openWith.embeddedInPage')
                  .replaceFirst('{name}', fileName)
                  .replaceFirst('{page}', provider.pages[idx].name)),
              backgroundColor: const Color(0xFF43B97F),
              duration: const Duration(seconds: 3),
            ),
          );
        }
        return id;
      }
    }
    final ctrl = _ctrlFor(provider.currentPage.id);
    final size =
        View.of(context).physicalSize / View.of(context).devicePixelRatio;
    final mat = ctrl.value;
    final scale = mat.getMaxScaleOnAxis();
    final t = mat.getTranslation();
    final pos = Offset(
      (size.width / 2 - t.x) / scale - 80,
      (size.height / 2 - t.y) / scale - 21,
    );
    final node = provider.addNodeAtCenterReturning(pos);
    provider.updateNodeTitle(node.id, fileName);
    provider.updateNodeAttachment(node.id, path, fileName);
    // 1 枚目のサムネイルも付ける (= ユーザー報告: ドロップと違って
    // アプリから開くで埋め込むとサムネイルが表示されない)。
    _generateEmbedAttachmentThumb(provider, node.id, path);
    _appSnack(
      context,
      SnackBar(
        content: Text(
            provider.t('openWith.embedded').replaceFirst('{name}', fileName)),
        backgroundColor: const Color(0xFF43B97F),
        duration: const Duration(seconds: 3),
      ),
    );
    return node.id;
  }

  /// 「アプリから開く」 などで添付したノードに 1 枚目のサムネイルを付ける
  /// (= ユーザー報告: ドロップした時と違ってサムネイルが表示されない)。
  /// ドロップ経路 (_generateAttachmentThumbnail) と同じ生成処理を非同期で
  /// 走らせ、 完了したらノードへ反映する。
  void _generateEmbedAttachmentThumb(
      MindMapProvider provider, String nodeId, String path) {
    final ext = path.split('.').last.toLowerCase();
    if (!const ['pdf', 'pptx', 'docx', 'xlsx'].contains(ext)) return;
    // 巨大 PDF はラスタライズしない (ビューア側と同じ安全上限)。
    if (ext == 'pdf' && !_isPdfRasterSourceSafe(path)) return;
    // ignore: discarded_futures
    () async {
      try {
        // ── ビューアで開いている PDF は触らない (= ユーザー報告: 手書きを
        //    保存した直後に落ちる)。 ネイティブ側が同じファイルを読んで
        //    いる最中にラスタライズすると巻き添えで落ちるため、 閉じるまで
        //    待ってから作る。 待ちきれない時は諦める (次に開いた時に作る)。 ──
        if (ext == 'pdf') {
          // 読みながら何度も描き込む事があるので、 閉じるまで気長に待つ
          // (= ユーザー報告: 手書きがサムネイルに出ない。 旧実装は 30 秒で
          //  諦めていたため、 保存後もしばらく開いたままだと作られなかった)。
          for (var i = 0; i < 900 && isPdfOpenNow(path); i++) {
            await Future<void>.delayed(const Duration(seconds: 1));
          }
          if (isPdfOpenNow(path)) return;
          if (!mounted) return;
          // 書き込み直後はファイルがまだ落ち着いていないことがある。
          await Future<void>.delayed(const Duration(milliseconds: 400));
        }
        final appDir = await getApplicationDocumentsDirectory();
        final thumbDir = Directory('${appDir.path}/attachments');
        if (!thumbDir.existsSync()) thumbDir.createSync(recursive: true);
        final thumb =
            await _generateAttachmentThumbnail(path, ext, thumbDir.path);
        if (thumb != null && mounted) {
          provider.setAttachmentThumb(nodeId, thumb.path, thumb.aspect);
        }
      } catch (_) {}
    }();
  }

  Future<void> _showInAppViewer(BuildContext ctx, String urlOrPath,
      {bool isLocalFile = false,
      String? nodeId,
      double initialRate = 1.0,
      bool? useRootNavigator,
      // どの分割セルへ入れるか (= ユーザー要望: ビューアの左分割 / 右分割で
      // 押した側のセルへ、 アプリのビューアのまま移す)。 null なら従来通り
      // 編集セル。
      int? embedSlot}) async {
    _gViewerOpenSw = Stopwatch()..start();
    _viewerMark('tap');
    // 表示用 URL を組み立てる。 ローカルパスは file:// に変換。
    String displayUrl = urlOrPath;
    if (isLocalFile) {
      try {
        // Windows のバックスラッシュを正規化
        displayUrl =
            Uri.file(urlOrPath, windows: Platform.isWindows).toString();
      } catch (_) {
        displayUrl = 'file://$urlOrPath';
      }
    }
    // 拡張子で PDF かどうか判定 (URL クエリ・フラグメントを除いて見る)
    String stripped = displayUrl.toLowerCase();
    final qIdx = stripped.indexOf('?');
    if (qIdx >= 0) stripped = stripped.substring(0, qIdx);
    final hIdx = stripped.indexOf('#');
    if (hIdx >= 0) stripped = stripped.substring(0, hIdx);
    final isPdf = stripped.endsWith('.pdf');

    // ── PDF を開く前の安全チェック (= ユーザー要望: PDF を開くと落ちがち) ──
    // 1) ローカルファイルが存在しない/空のまま syncfusion に渡すと、 ネイティブ
    //    側でクラッシュ (= アプリ強制終了) することがあるので事前に弾く。
    // 2) 非常に大きい PDF はネイティブ描画が OOM でアプリごと落ちやすい。 開く
    //    前に確認し、 「外部アプリで開く」 を選べるようにして強制終了を避ける。
    if (isPdf && isLocalFile) {
      try {
        final f = File(urlOrPath);
        if (!await f.exists()) {
          if (ctx.mounted) {
            _appSnack(
                ctx,
                SnackBar(
                    content: Text(context
                        .read<MindMapProvider>()
                        .t('pdf.fileNotFound'))));
          }
          return;
        }
        final len = await f.length();
        if (len <= 0) {
          if (ctx.mounted) {
            _appSnack(
                ctx,
                SnackBar(
                    content: Text(
                        context.read<MindMapProvider>().t('pdf.fileEmpty'))));
          }
          return;
        }
        // ビューアはストリーム描画 + 巨大時はサムネ生成もスキップするため、
        // 数百 MB の PDF も開ける (= ユーザー要望: 数 GB の PDF でも読めるように)。
        // 確認は本当に巨大な 1.5GB 超だけに出す (それ未満は黙って開く)。
        const kHugePdfBytes = 1536 * 1024 * 1024;
        if (len > kHugePdfBytes && ctx.mounted) {
          final mb = (len / 1024 / 1024).toStringAsFixed(0);
          final choice = await showDialog<String>(
            context: ctx,
            useRootNavigator: useRootNavigator ?? true,
            builder: (dctx) => AlertDialog(
              backgroundColor: const Color(0xFF1E1E32),
              title: Text(context.read<MindMapProvider>().t('pdf.largeTitle'),
                  style: TextStyle(color: Colors.white, fontSize: 15)),
              content: Text(
                  'この PDF は $mb MB あります。 アプリ内ビューアで開くと、 端末に'
                  'よっては動作が重くなったり強制終了することがあります。\n'
                  'どうしますか？',
                  style: const TextStyle(color: Colors.white70, fontSize: 13)),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(dctx, 'cancel'),
                  child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                      style: TextStyle(color: Colors.white54)),
                ),
                TextButton(
                  onPressed: () => Navigator.pop(dctx, 'external'),
                  child: Text(
                      context.read<MindMapProvider>().t('pptx.openExternal')),
                ),
                ElevatedButton(
                  style: ElevatedButton.styleFrom(
                      backgroundColor: const Color(0xFF6C63FF),
                      foregroundColor: Colors.white),
                  onPressed: () => Navigator.pop(dctx, 'inapp'),
                  child:
                      Text(context.read<MindMapProvider>().t('pdf.openAnyway')),
                ),
              ],
            ),
          );
          if (choice == 'external') {
            try {
              await OpenFilex.open(urlOrPath);
            } catch (_) {}
            return;
          }
          if (choice != 'inapp') return; // キャンセル
        }
      } catch (e) {
        debugPrint('PDF 事前チェック失敗 (続行): $e');
      }
    }

    _viewerMark('pre-checks done');
    if (_isDesktop) {
      // ビューア本体 (全画面 Dialog / フローティング窓 で共用)。
      final viewerContent = _InAppViewerDialog(
              // マップ分割中は分割セルを覆う窓で開く (下記) ので、 メモ /
              // AI パネルは自動で開かない (= ユーザー要望: 表示領域が狭い)。
              compactHost: _canEmbedIntoMapSplit(),
              url: displayUrl,
              isPdf: isPdf,
              nodeId: nodeId,
              initialRate: initialRate,
              // ── まだマップに載っていないローカルファイルを開いた時
              //    (= 「プログラムから開く」)、 メモ / AI を使ったタイミングや
              //    「ページに追加」 ボタンでマップへ追加する (= ユーザー要望)。 ──
              onEnsureNode: (nodeId == null && isLocalFile)
                  ? ({String? pageId}) async {
                      if (!mounted) return null;
                      final p = context.read<MindMapProvider>();
                      // 追加する時だけ保存データの読み込みを待つ
                      // (表示は待たない = 起動を速くするため)。 読み込み前に
                      // 作ったノードは完了時に差し替えられて消えてしまう。
                      try {
                        await p.initialLoadDone;
                      } catch (_) {}
                      if (!mounted) return null;
                      final name = urlOrPath.split(RegExp(r'[/\\]')).last;
                      return _embedFileAsNode(p, urlOrPath, name,
                          pageId: pageId);
                    }
                  : null,
              // 開いているファイルのノードを別のページへ移す (= ユーザー要望)。
              onMoveNodeToPage: _moveAttachmentNodeToPage,
              // 画面分割パネルへ引き継ぎ (= ビューア閉じて MindMapScreen
              // の右側パネルで開く)
              onMoveToSplitPanel: (currentUrl, {bool isLeftPanel = false}) {
                // 拡張子はクエリ (?) と位置指定 (#page=3) を外して見る。
                var probe = currentUrl.toLowerCase();
                final qi = probe.indexOf('?');
                if (qi >= 0) probe = probe.substring(0, qi);
                final hi = probe.indexOf('#');
                if (hi >= 0) probe = probe.substring(0, hi);
                final isPdf = probe.endsWith('.pdf');
                // マップ分割中は分割セルへ埋め込む (= ユーザー要望)。
                if (_canEmbedIntoMapSplit()) {
                  // ★ PDF をそのまま _embedUrlIntoSplitSide へ渡すと Web セル
                  //   (= ブラウザ内蔵の PDF 表示) になり、 描き込みも文字入れも
                  //   できなくなっていた (= ユーザー報告: 「再度画面分割を行うと
                  //   ブラウザ版で開かれてしまう」)。 アプリのビューアのまま、
                  //   押した側のセルへ入れ直す。
                  if (isPdf) {
                    // ignore: discarded_futures
                    _showInAppViewer(
                      context,
                      currentUrl,
                      isLocalFile: !currentUrl.startsWith('http://') &&
                          !currentUrl.startsWith('https://'),
                      nodeId: nodeId,
                      embedSlot: _mapSplitSideSlot(left: isLeftPanel),
                    );
                    return;
                  }
                  _embedUrlIntoSplitSide(currentUrl, left: isLeftPanel);
                  return;
                }
                // ユーザー要望: 「右分割と左分割を同時に表示できる」
                //   ようにするため、 反対側パネルは触らない。
                if (isLeftPanel) {
                  // 全画面へ戻す時にメモ欄を復活させるため元ノードを保持
                  // (= ユーザー要望)。
                  _splitLeftOriginNodeId = nodeId;
                  if (isPdf) {
                    _splitLoadLeftPdf(currentUrl);
                  } else {
                    _splitLoadLeftUrl(currentUrl);
                  }
                } else {
                  setState(() {
                    _setSplitOpen(true);
                    _splitOriginNodeId = nodeId;
                  });
                  _splitLoadUrl(currentUrl);
                }
              },
              // AI 一問一答クイズ生成 (PDF 限定)
              onGenerateQuiz: isPdf
                  ? (pdfPath) {
                      _showQuizGenerationDialog(context, pdfPath,
                          nodeId: nodeId);
                    }
                  : null,
              // メモを AI に質問 → 回答をマップ/メモへ (= ユーザー要望)。
              onAskAiMemo: (memo) {
                final (_, body) = _parseMemoImage(memo.text);
                _askAiQuestionAndPlace(
                    question: body, memo: memo, memoNodeId: nodeId);
              },
              // 手書きを焼き込んだらサムネイルを作り直す (= ユーザー報告)。
              onSavedToFile: () => _notifyAttachmentEdited(nodeId),
      );
      // ── マップ分割中はフローティング窓で開く (= ユーザー要望: 全画面では
      //    なく分割した画面の上で開き、 他の領域はそのまま操作できるように。
      //    動画 / 画像編集と同じ方式で非モーダル)。 ──
      if (_canEmbedIntoMapSplit()) {
        // 分割セルの中にそのまま組み込む (= ユーザー要望: PDF などが
        //   その画面に埋め込まれた状態で開くように。 浮遊窓のヘッダーと
        //   ビューアのヘッダーが二重に並ぶのも無くなる)。
        _embedViewerIntoMapSplitCell(
            (_) => ColoredBox(
                color: const Color(0xFF1A1A24), child: viewerContent),
            slot: embedSlot);
        return;
      }
      await showDialog<void>(
        context: ctx,
        useRootNavigator: useRootNavigator ?? true,
        barrierColor: Colors.black.withValues(alpha: 0.92),
        // ── フルスクリーン Dialog ──
        // 通常の Dialog は IntrinsicWidth/SafeArea でラップされて中央に
        // 余白付きで表示される。 ユーザーが「表示領域もっと広く」 を希望
        // したので、 Dialog.fullscreen でメインウィンドウ全面に展開する。
        // 角丸・余白なしでビューアがウィンドウいっぱいになる。
        builder: (dctx) {
          // 分割中はアクティブ側ペインの領域内での「全画面」 にする
          // (= ユーザー要望: 分割した画面上での全画面)。
          // ★ PDF だけは分割中でも本当の全画面で開く (= ユーザー報告:
          //   分割した画面上で PDF を開くとフリーズしてしまう。 ペインの
          //   狭い領域に Syncfusion ビューアを押し込むのをやめる)。
          return Padding(
            padding: isPdf ? EdgeInsets.zero : _activePaneDialogInsets(),
            child: Dialog.fullscreen(
              backgroundColor: const Color(0xFF1A1A24),
              child: viewerContent,
            ),
          );
        },
      );
    } else {
      // ビューア本体 (全画面ページ / フローティング窓 で共用)。
      final pageContent = _InAppViewerPage(
          url: displayUrl,
          isPdf: isPdf,
          nodeId: nodeId,
          initialRate: initialRate,
          onMoveToSplitPanel: (currentUrl, {bool isLeftPanel = false}) {
            // ユーザー要望: 「右分割と左分割を同時に表示できる」
            //   ようにするため、 反対側パネルは触らない。
            final isPdf = currentUrl.toLowerCase().endsWith('.pdf');
            if (isLeftPanel) {
              // 全画面へ戻す時にメモ欄を復活させるため元ノードを保持
              // (= ユーザー要望)。
              _splitLeftOriginNodeId = nodeId;
              if (isPdf) {
                _splitLoadLeftPdf(currentUrl);
              } else {
                _splitLoadLeftUrl(currentUrl);
              }
            } else {
              setState(() {
                _setSplitOpen(true);
                _splitOriginNodeId = nodeId;
              });
              _splitLoadUrl(currentUrl);
            }
          },
          onGenerateQuiz: isPdf
              ? (pdfPath) {
                  _showQuizGenerationDialog(context, pdfPath, nodeId: nodeId);
                }
              : null,
          // メモを AI に質問 (= ユーザー要望: モバイルのメモにも AI ボタン)。
          onAskAiMemo: (memo) {
            final (_, body) = _parseMemoImage(memo.text);
            _askAiQuestionAndPlace(
                question: body, memo: memo, memoNodeId: nodeId);
          },
          // 手書きを焼き込んだらサムネイルを作り直す (= ユーザー報告)。
          onSavedToFile: () => _notifyAttachmentEdited(nodeId),
      );
      // ── マップ分割中はフローティング窓で開く (非モーダル =
      //    他の領域はそのまま操作できる) ──
      if (_canEmbedIntoMapSplit()) {
        // 分割セルの中に埋め込む (= ユーザー要望)。
        _embedViewerIntoMapSplitCell((_) => pageContent);
        return;
      }
      await Navigator.of(ctx, rootNavigator: useRootNavigator ?? false)
          .push<void>(MaterialPageRoute<void>(
        fullscreenDialog: true,
        builder: (_) => pageContent,
      ));
    }
  }

  /// 「マップの外」 にメモ一覧を出すフローティングパネルを開く。
  /// 設定シート / コマンドメニュー / ヘッダーボタンから呼ばれる想定。
  /// 各メモをタップすると、 そのメモが紐づくノードの PDF / URL を
  /// アプリ内ビューアで該当ページ + 位置から開く。
  void _showPdfMemoListPanel(BuildContext ctx) {
    // メモを開くときの共通処理。
    // - urlOverride 非 null: URL メモ → そのままアプリ内ビューアへ
    // - urlOverride null + page 非 null: PDF メモ → #page=N 付きで PDF を開く
    // - 両方 null: その他 (ノードのリンクを開くだけ)
    void openMemo(
        String nodeId, String pathOrUrl, int? page, String? urlOverride) {
      Navigator.of(ctx).maybePop();
      // サイトメモ (web_page_memos) のように紐づくノードが無い場合は
      //   空文字で渡ってくる → nodeId は null として扱う。
      final String? nid = nodeId.isEmpty ? null : nodeId;
      if (urlOverride != null) {
        // URL メモ: ローカルファイルではない
        _showInAppViewer(ctx, urlOverride, isLocalFile: false, nodeId: nid);
        return;
      }
      String openPath = pathOrUrl;
      if (page != null && !pathOrUrl.contains('#page=')) {
        openPath = '$pathOrUrl#page=$page';
      }
      _showInAppViewer(ctx, openPath,
          isLocalFile: !pathOrUrl.startsWith('http'), nodeId: nid);
    }

    // 「その他」タブのノードメモをタップ → そのノードへ画面を移動。
    void focusNode(String nodeId) {
      Navigator.of(ctx).maybePop();
      if (!mounted) return;
      final provider = context.read<MindMapProvider>();
      final node = provider.nodes[nodeId];
      if (node == null) return;
      final pageId = provider.currentPage.id;
      final scale = _percentToScale(_scalePercent);
      _ctrlFor(pageId).value = _matrixFor(node.position, scale);
      setState(() {
        _selectedConnections.clear();
        _clearConnectionBendDragFields(clearSelection: true);
      });
    }

    if (_isDesktop) {
      // デスクトップ: 右側にスライドインする SideSheet 風 Dialog
      showGeneralDialog<void>(
        context: ctx,
        barrierColor: Colors.black54,
        barrierDismissible: true,
        barrierLabel: context.read<MindMapProvider>().t('menu.memoList'),
        transitionDuration: const Duration(milliseconds: 220),
        pageBuilder: (_, __, ___) {
          return Align(
            alignment: Alignment.centerRight,
            child: SizedBox(
              width: 360,
              height: double.infinity,
              child: _MapPdfMemoListPanel(
                  onOpenMemo: openMemo, onFocusNode: focusNode),
            ),
          );
        },
        transitionBuilder: (_, anim, __, child) {
          return SlideTransition(
            position: Tween<Offset>(
              begin: const Offset(1, 0),
              end: Offset.zero,
            ).animate(
                CurvedAnimation(parent: anim, curve: Curves.easeOutCubic)),
            child: child,
          );
        },
      );
    } else {
      // モバイル: 全画面シート
      showModalBottomSheet<void>(
        context: ctx,
        isScrollControlled: true,
        backgroundColor: Colors.transparent,
        builder: (_) => SizedBox(
          height: MediaQuery.of(ctx).size.height * 0.85,
          child: ClipRRect(
            borderRadius: const BorderRadius.vertical(top: Radius.circular(18)),
            child: _MapPdfMemoListPanel(
                onOpenMemo: openMemo, onFocusNode: focusNode),
          ),
        ),
      );
    }
  }

  // ─── 接続線タップ ────────────────────────────────────────────────────────

  // ??? ???????????? ?????????????????????????????????????????????

  NodeConnection? _latestConnection(
      NodeConnection conn, MindMapProvider provider) {
    for (final c in provider.connections) {
      if (c.fromId == conn.fromId && c.toId == conn.toId) return c;
    }
    return null;
  }

  List<Offset> _bendPointsForConnection(
      NodeConnection conn, MindMapProvider provider) {
    final latest = _latestConnection(conn, provider) ?? conn;
    if (latest.elbowBendPoints.isNotEmpty) {
      return List<Offset>.from(latest.elbowBendPoints);
    }
    final from = provider.nodes[latest.fromId];
    final to = provider.nodes[latest.toId];
    if (from == null || to == null) return const <Offset>[];
    final pts = ConnectionPainter.elbowPointsFor(latest, from, to);
    if (pts.length <= 2) return const <Offset>[];
    return pts.sublist(1, pts.length - 1);
  }

  ({String fromId, String toId, int index}) _connectionBendKey(
          NodeConnection connection, int index) =>
      (fromId: connection.fromId, toId: connection.toId, index: index);

  Map<NodeConnection, Set<int>> _selectedBendIndicesFor(
      Iterable<NodeConnection> connections) {
    final result = <NodeConnection, Set<int>>{};
    for (final connection in connections) {
      final indices = _selectedConnectionBends
          .where((key) =>
              key.fromId == connection.fromId && key.toId == connection.toId)
          .map((key) => key.index)
          .toSet();
      if (indices.isNotEmpty) result[connection] = indices;
    }
    return result;
  }

  void _clearConnectionBendDragFields({bool clearSelection = false}) {
    _draggingConnectionBend = null;
    _draggingConnectionBendIndex = null;
    _connectionBendPointerActive = false;
    _connectionBendDragStart = null;
    _connectionBendDragInitialPoints = {};
    _connectionBendDragHistoryRecorded = false;
    _connectionBendDragMoved = false;
    _pendingConnectionBendToggleOff = null;
    if (clearSelection) _selectedConnectionBends.clear();
  }

  void _syncSelectedConnectionsToBends(
    MindMapProvider provider, {
    NodeConnection? fallback,
  }) {
    _selectedConnections
      ..clear()
      ..addAll(provider.connections.where((connection) =>
          _selectedConnectionBends.any((selected) =>
              selected.fromId == connection.fromId &&
              selected.toId == connection.toId)));
    if (_selectedConnections.isEmpty && fallback != null) {
      _selectedConnections
          .add(_latestConnection(fallback, provider) ?? fallback);
    }
  }

  void _beginConnectionBendInteraction(
    ({NodeConnection connection, int index}) hit,
    Offset canvasPos,
    MindMapProvider provider,
  ) {
    final key = _connectionBendKey(hit.connection, hit.index);
    final additive = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    final wasSelected = _selectedConnectionBends.contains(key);

    setState(() {
      _connectionBendPointerActive = true;
      _suppressConnectionTapAfterBendDrag = true;
      if (additive && wasSelected) {
        // Ctrl/Meta の単独クリックなら pointer-up で選択解除する。一方、
        // そのままドラッグした場合は選択を維持して全節点を一括移動する。
        _pendingConnectionBendToggleOff = key;
      } else {
        if (!additive && !wasSelected) {
          _selectedConnectionBends.clear();
        }
        _selectedConnectionBends.add(key);
      }
      _draggingConnectionBend = hit.connection;
      _draggingConnectionBendIndex = hit.index;

      // 節点を選んだリンクだけを強調表示する。Ctrl/Meta なら別リンクの
      // 節点も残るため、複数リンクをまたいだ一括移動にも対応できる。
      _syncSelectedConnectionsToBends(provider, fallback: hit.connection);
    });

    _connectionBendDragStart = canvasPos;
    _connectionBendDragHistoryRecorded = false;
    _connectionBendDragMoved = false;
    _connectionBendDragInitialPoints = {};

    final selectedByConnection = _selectedBendIndicesFor(provider.connections);
    for (final entry in selectedByConnection.entries) {
      final points = _bendPointsForConnection(entry.key, provider);
      if (entry.value.any((index) => index >= 0 && index < points.length)) {
        _connectionBendDragInitialPoints[entry.key] = points;
      }
    }
  }

  void _updateSelectedConnectionBends(
      Offset canvasPos, MindMapProvider provider, double scale) {
    final dragStart = _connectionBendDragStart;
    if (dragStart == null || _connectionBendDragInitialPoints.isEmpty) return;
    final delta = canvasPos - dragStart;
    // 画面上3px未満の揺れはクリックとして扱い、不要な保存・Undoを防ぐ。
    if (!_connectionBendDragMoved &&
        delta.distance * math.max(scale, 0.1) < 3.0) {
      return;
    }
    _connectionBendDragMoved = true;
    _pendingConnectionBendToggleOff = null;

    final updates = <NodeConnection, List<Offset>>{};
    for (final entry in _connectionBendDragInitialPoints.entries) {
      final points = List<Offset>.from(entry.value);
      var changed = false;
      for (final selected in _selectedConnectionBends) {
        if (selected.fromId != entry.key.fromId ||
            selected.toId != entry.key.toId ||
            selected.index < 0 ||
            selected.index >= points.length) {
          continue;
        }
        points[selected.index] = entry.value[selected.index] + delta;
        changed = true;
      }
      if (changed) updates[entry.key] = points;
    }
    if (updates.isEmpty) return;
    final recordHistory = !_connectionBendDragHistoryRecorded;
    _connectionBendDragHistoryRecorded = true;
    provider.updateConnectionBendPointsBatch(
      updates,
      recordHistory: recordHistory,
    );
  }

  void _finishConnectionBendInteraction(
    MindMapProvider provider, {
    bool cancelled = false,
  }) {
    if (!mounted) return;
    final toggleOff = !cancelled && !_connectionBendDragMoved
        ? _pendingConnectionBendToggleOff
        : null;
    final fallback = _draggingConnectionBend;
    setState(() {
      if (toggleOff != null) {
        _selectedConnectionBends.remove(toggleOff);
        _syncSelectedConnectionsToBends(provider, fallback: fallback);
      }
      _clearConnectionBendDragFields();
      if (cancelled) _suppressConnectionTapAfterBendDrag = false;
    });
    if (!cancelled) {
      Future.delayed(const Duration(milliseconds: 80), () {
        if (mounted) _suppressConnectionTapAfterBendDrag = false;
      });
    }
  }

  ({NodeConnection connection, int index})? _hitConnectionBendPoint(
      Offset canvasPos, MindMapProvider provider, double scale) {
    if (provider.currentPage.pageType == 'bookshelf') return null;
    final radius = math.max(8.0, 14.0 / math.max(scale, 0.1));
    // ぶら下がる先が 1 つだけの線は直線で描くので、 節点のつまみも出さない
    // (= ユーザー要望: 表が 1 つの時に節点が付くのはおかしい)。
    final singles =
        ConnectionPainter.singleChildSourceIds(provider.connections);
    for (final conn in provider.connections.reversed) {
      if (ConnectionPainter.resolveStyle(
              conn, provider.connectionLineStyle, singles) !=
          'elbow') {
        continue;
      }
      final from = provider.nodes[conn.fromId];
      final to = provider.nodes[conn.toId];
      if (from == null || to == null) continue;
      final pts = ConnectionPainter.elbowPointsFor(conn, from, to);
      for (int i = 1; i < pts.length - 1; i++) {
        if ((pts[i] - canvasPos).distance <= radius) {
          return (connection: conn, index: i - 1);
        }
      }
    }
    return null;
  }

  NodeConnection? _hitConnectionLabel(
      Offset canvasPos, MindMapProvider provider, double scale) {
    if (provider.currentPage.pageType == 'bookshelf') return null;
    final radius = math.max(12.0, 24.0 / math.max(scale, 0.1));
    for (final conn in provider.connections.reversed) {
      if (conn.label == null || conn.label!.isEmpty) continue;
      final from = provider.nodes[conn.fromId];
      final to = provider.nodes[conn.toId];
      if (from == null || to == null) continue;
      final point = ConnectionPainter.pointOnConnection(conn, from, to,
          fallbackLineStyle: provider.connectionLineStyle,
          singleChildSources:
              ConnectionPainter.singleChildSourceIds(provider.connections));
      if ((point - canvasPos).distance <= radius) return conn;
    }
    return null;
  }

  void _onConnectionTap(Offset globalPos, TransformationController ctrl,
      MindMapProvider provider) {
    final canvasPos = _globalToCanvas(globalPos, ctrl);
    final painter = ConnectionPainter(
      nodes: provider.nodes,
      connections: provider.connections,
      lineStyle: provider.connectionLineStyle,
    );
    final hit = painter.findConnection(canvasPos);
    if (hit == null) {
      // 接続なし → 接続が選択されていれば解除する
      if (_selectedConnections.isNotEmpty) {
        _resetInteractionState();
      }
      return;
    }
    final clearBendSelection =
        _selectedConnectionBends.isNotEmpty || _connectionBendPointerActive;
    final isCtrl = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    if (isCtrl) {
      // Ctrl+クリック: トグル追加/削除（オーバーレイは出さず、Ctrlリリース時に表示）
      setState(() {
        if (clearBendSelection) {
          _clearConnectionBendDragFields(clearSelection: true);
        }
        if (_selectedConnections.contains(hit)) {
          _selectedConnections.remove(hit);
        } else {
          _selectedConnections.add(hit);
        }
        _lastCtrlConnectionTapPos = globalPos;
        _connOverlayPendingOnCtrlUp = _selectedConnections.isNotEmpty;
      });
    } else if (_selectedConnections.length > 1 &&
        _selectedConnections.contains(hit)) {
      // 複数選択中で、選択中の接続をクリック → 選択を維持してメニュー表示
      if (clearBendSelection) {
        setState(() => _clearConnectionBendDragFields(clearSelection: true));
      }
      _showConnectionDeleteOverlay(hit, globalPos, provider);
    } else {
      // 通常クリック: 単一選択 + メニュー表示
      setState(() {
        if (clearBendSelection) {
          _clearConnectionBendDragFields(clearSelection: true);
        }
        _selectedConnections.clear();
        _selectedConnections.add(hit);
        _lastCtrlConnectionTapPos = null;
        _connOverlayPendingOnCtrlUp = false;
      });
      _showConnectionDeleteOverlay(hit, globalPos, provider);
    }
  }

  /// 選択中の接続に対してメニューを表示（右クリック or 再タップ用）
  void _showConnectionMenu(Offset globalPos, MindMapProvider provider) {
    if (_selectedConnections.isEmpty) return;
    _showConnectionDeleteOverlay(
        _selectedConnections.first, globalPos, provider);
  }

  /// 選択中の親子リンクについて、接続元ノードへ「親」、接続先ノードへ
  /// 「子」のピルを浮かせる。設定画面で関係種別を変えた直後にも追従するよう、
  /// 選択時の古いインスタンスではなく provider の最新接続を参照する。
  List<Widget> _buildSelectedConnectionRoleBadges(
      MindMapProvider provider, Map<String, MindMapNode> nodes) {
    if (_selectedConnections.isEmpty ||
        provider.currentPage.pageType == 'bookshelf') {
      return const <Widget>[];
    }
    final rolesByNode = <String, Set<String>>{};
    final selectedKeys = _selectedConnections
        .map((connection) => '${connection.fromId}\u{0}${connection.toId}')
        .toSet();
    // 選択キー作成と全接続の1回走査に分け、複数選択でも二重ループにしない。
    for (final connection in provider.connections) {
      final key = '${connection.fromId}\u{0}${connection.toId}';
      if (!selectedKeys.contains(key) || !connection.isParentChild) continue;
      rolesByNode
          .putIfAbsent(connection.fromId, () => <String>{})
          .add('parent');
      rolesByNode.putIfAbsent(connection.toId, () => <String>{}).add('child');
    }
    if (rolesByNode.isEmpty) return const <Widget>[];

    final parentLabel = provider.t('conn.roleParent');
    final childLabel = provider.t('conn.roleChild');
    return rolesByNode.entries.map((entry) {
      final node = nodes[entry.key];
      if (node == null || node.hiddenInContainer != null) {
        return const SizedBox.shrink();
      }
      final isParent = entry.value.contains('parent');
      final isChild = entry.value.contains('child');
      final label = isParent && isChild
          ? '$parentLabel・$childLabel'
          : (isParent ? parentLabel : childLabel);
      final color = isParent && isChild
          ? const Color(0xFF7E57C2)
          : (isParent ? const Color(0xFF26A69A) : const Color(0xFF42A5F5));
      return Positioned(
        left: node.position.dx + node.width / 2,
        top: math.max(0.0, node.position.dy - 32.0),
        child: FractionalTranslation(
          translation: const Offset(-0.5, 0),
          child: IgnorePointer(
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
              decoration: BoxDecoration(
                color: color.withValues(alpha: 0.96),
                borderRadius: BorderRadius.circular(14),
                border: Border.all(color: Colors.white70, width: 1.2),
              ),
              child: Text(
                label,
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 11,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ),
          ),
        ),
      );
    }).toList(growable: false);
  }

  // ─── PC版：キャンバス右クリックメニュー ─────────────────────────────────

  void _showCanvasContextMenu(Offset globalPos, TransformationController ctrl,
      MindMapProvider provider) {
    _removeOverlay();
    final mq = MediaQuery.of(context);
    final sw = mq.size.width;
    final sh = mq.size.height;

    // メニュー項目を構築
    // モバイル版では、ノード追加 / リンク挿入 / ファイル添付 / 範囲選択 の
    // 4 つは画面下部のボタンバーに既にデフォルト搭載されているため、
    // この空き領域メニューに同じ項目を出すと冗長 + ボタン領域が狭くなる。
    // → モバイル時はこの 4 項目をスキップする (デスクトップでは従来通り表示)。
    // 「マップを分割表示」 を押した時に、 その下へ割り方 (上下 / 左右 /
    // 4 分割) を差し込むか (= ユーザー要望: 右クリックではなく左クリックで、
    // 元の項目を出したまま 2〜4 分割の設定が出てくるように)。
    bool splitExpanded = false;
    // 割り方を「右に」 出すため、 項目そのものの位置を測る鍵 (= ユーザー要望)。
    final GlobalKey splitItemKey = GlobalKey();
    List<Widget> buildItems(bool splitExpanded, VoidCallback toggleSplit) => [
      // ── ギャラリー: 背景画像の設定 (= ユーザー要望: ギャラリー背景を
      //    右クリックすることで背景画像の設定項目が出るように) ──
      if (provider.currentPage.pageType == 'bookshelf')
        _CtxMenuItem(
          icon: Icons.wallpaper_rounded,
          label: provider.t('cmd.mapBackground'),
          color: const Color(0xFF6C63FF),
          onTap: () {
            _removeOverlay();
            _showMapBackgroundDialog(context, provider);
          },
        ),
      if (_isDesktop)
        _CtxMenuItem(
          icon: Icons.select_all_rounded,
          label: provider.t('ctx.rangeSelect'),
          color: const Color(0xFF4FC3F7),
          onTap: () {
            _removeOverlay();
            setState(() {
              _rangeSelectMode = true;
              _rangeSelectedIds.clear();
              _rangeSelectedDecorationIds.clear();
            });
          },
        ),
      if (_isDesktop)
        _CtxMenuItem(
          icon: Icons.add_circle_rounded,
          label: provider.t('ctx.addNode'),
          color: const Color(0xFF6C63FF),
          onTap: () {
            _removeOverlay();
            final canvasPos = _globalToCanvas(globalPos, ctrl);
            _createNodeWithOptionalInlineTitleEdit(
                provider, canvasPos - const Offset(80, 21));
          },
        ),
      // マップの背景画像設定 (= ユーザー要望: マップの背景画像を自由に
      //   カスタマイズ)。 画像選択 / 解除 / 不透明度・表示モード調整を
      //   ダイアログで行う。 一番下ではなく 3 番目に置く (= ユーザー要望:
      //   よく使うので上の方に)。 ギャラリーは先頭に専用項目があるので出さない。
      if (provider.currentPage.pageType != 'bookshelf')
        _CtxMenuItem(
          icon: Icons.wallpaper_rounded,
          label: (provider.currentPage.backgroundImagePath ?? '').isEmpty
              ? provider.t('bg.configure')
              : provider.t('bg.change'),
          color: const Color(0xFF6C63FF),
          onTap: () {
            _removeOverlay();
            _showMapBackgroundDialog(context, provider);
          },
        ),
      // ── 画面分割 (= ユーザー要望) ──
      //    分割していない時: 押すと右側に割り方 (上下 / 左右 / 4 分割) が出る。
      //    分割している時  : 押すと分割を解除するだけ (割り方は出さない)。
      _CtxMenuItem(
        key: splitItemKey,
        icon: _mapSplitOpen
            ? Icons.close_fullscreen_rounded
            : Icons.splitscreen_rounded,
        label: provider.t(_mapSplitOpen ? 'cmd.closeSplit' : 'hdr.mapSplit'),
        color: const Color(0xFF4FC3F7),
        expanded: _mapSplitOpen ? null : splitExpanded,
        expandRight: true,
        onTap: _mapSplitOpen
            ? () {
                _removeOverlay();
                // 右クリックした場所のペインのページを残して解除する
                // (= ユーザー要望: 左上のページに移ってしまうのを直す)。
                _closeMapSplitKeeping(_splitSlotAtGlobal(globalPos));
              }
            : toggleSplit,
      ),
      _CtxMenuItem(
        icon: Icons.content_cut_rounded,
        label: provider.t('hdr.cutMode'),
        color: const Color(0xFFFF6B6B),
        onTap: () {
          _removeOverlay();
          setState(() {
            _cutMode = !_cutMode;
            _cutStartPoint = null;
            _cutPreviewEnd = null;
          });
          _showLockToast(_cutMode
              ? provider.t('toast.cutModeOn')
              : provider.t('toast.cutModeOff'));
        },
      ),
      // ── 図形を挿入 (= 直線/矢印/波線/長方形/円 など) ──
      // ユーザー要望「右クリックの項目に図形の挿入項目を追加して」。
      _CtxMenuItem(
        icon: Icons.draw_rounded,
        label: provider.t('hdr.insertMapShape'),
        color: const Color(0xFF43B97F),
        onTap: () {
          _removeOverlay();
          _showMapShapePicker();
        },
      ),
      _CtxMenuItem(
        icon: Icons.account_tree_outlined,
        // 多言語対応 (= ユーザー指摘: 端子の文字が日本語のままだった)
        label: provider.t('flow.terminal'),
        color: const Color(0xFF4DB6AC),
        onTap: () {
          _removeOverlay();
          _showTerminalBlockPicker(provider, _globalToCanvas(globalPos, ctrl));
        },
      ),
      // ── メモ一覧 (= ユーザー要望: 他のマップ / PDF ビューワーで書いたメモを
      //    参照・編集。 メモの場所 (マップ) 毎にグループ化して表示) ──
      _CtxMenuItem(
        icon: Icons.sticky_note_2_rounded,
        label: provider.t('ctx.memoList'),
        color: const Color(0xFFFFC107),
        onTap: () {
          _removeOverlay();
          _showPdfMemoListPanel(context);
        },
      ),
      // 「リンクを挿入 (リンクノードを追加)」 は廃止 (= ユーザー要望:
      // URL は直接貼り付ければノードになるので専用機能は不要)。
      if (_isDesktop)
        _CtxMenuItem(
          icon: Icons.attach_file_rounded,
          label: provider.t('ctx.attachFile'),
          color: const Color(0xFFFF6B6B),
          onTap: () {
            _removeOverlay();
            _pickAndAttachFile(context, provider, ctrl);
          },
        ),
      // ── 新規ファイルを生成 (txt / md / docx / xlsx / pptx / csv) して
      //    その場にノード化 (= ユーザー要望: 右クリックからファイルを
      //    生成できるように。 マインドマップ / ギャラリーの両方) ──
      if (_isDesktop)
        _CtxMenuItem(
          icon: Icons.note_add_rounded,
          label: provider.t('file.create'),
          color: const Color(0xFF4FC3F7),
          onTap: () {
            _removeOverlay();
            final canvasPos = _globalToCanvas(globalPos, ctrl);
            // ignore: discarded_futures
            _createFileNodeAt(provider, canvasPos);
          },
        ),
      if (_rangeSelectedIds.isNotEmpty) ...[
        _CtxMenuItem(
          icon: Icons.content_copy_rounded,
          label: provider.t(_isDesktop ? 'ctx.copyShortcut' : 'ctx.copy'),
          color: const Color(0xFF4FC3F7),
          onTap: () {
            _removeOverlay();
            _handleCopy(provider);
          },
        ),
        // ── 選択中ノードの添付ファイル一括ダウンロード ──
        // 画像 / PDF / 動画など、attachmentPath が設定されたノードを
        // 全部走査して、指定したディレクトリにそのままコピーする。
        // 添付がないノードはスキップ。1 件もなければメニュー項目を非表示。
        // ヘッダーと同じく、画像/添付 と YouTube 動画の両方が混在するときは
        // 1 つの「画像と動画を一括DL」項目に統合する (= ユーザー要望)。
        if (_selectedNodesHaveAttachments(provider) &&
            _selectedNodesHaveYoutubeVideos(provider))
          _CtxMenuItem(
            icon: Icons.download_rounded,
            label: provider.t('ctx.bulkDownloadMedia'),
            color: const Color(0xFF43B97F),
            onTap: () {
              _removeOverlay();
              _bulkDownloadSelectedMixed(context, provider);
            },
          )
        else if (_selectedNodesHaveAttachments(provider))
          _CtxMenuItem(
            icon: Icons.download_for_offline_rounded,
            label: provider.t('ctx.bulkDownloadAttachments'),
            color: const Color(0xFF43B97F),
            onTap: () {
              _removeOverlay();
              _bulkDownloadSelectedAttachments(context, provider);
            },
          )
        else if (_selectedNodesHaveYoutubeVideos(provider))
          // リリース版では YouTube 動画の端末保存は無効化しているため、
          // 通常はここに到達しない。保険として無効化メッセージのみ表示する。
          _CtxMenuItem(
            icon: Icons.cloud_download_rounded,
            label: provider.t('ctx.bulkDownloadYoutube'),
            color: const Color(0xFFFFB347),
            onTap: () {
              _removeOverlay();
              _bulkDownloadSelectedYoutubeVideos(context, provider);
            },
          ),
        // ── ギャラリーに整列 (= 選択ノードを等間隔・同寸タイルで並べ直す) ──
        _CtxMenuItem(
          icon: Icons.view_module_rounded,
          label: provider.t('ctx.bookshelf'),
          color: const Color(0xFFFF7043),
          onTap: () {
            final ids = Set.of(_rangeSelectedIds);
            _removeOverlay();
            provider.arrangeAsBookshelf(onlyIds: ids);
          },
        ),
        _CtxMenuItem(
          icon: Icons.delete_rounded,
          label: provider.t(_isDesktop
              ? 'ctx.deleteSelectedShortcut'
              : 'tooltip.deleteSelectedMobile'),
          color: Colors.redAccent,
          onTap: () {
            _removeOverlay();
            _confirmDeleteSelected(context, provider);
          },
        ),
      ],
      if (provider.namedGroups.isNotEmpty)
        _CtxMenuItem(
          icon: Icons.bookmarks_rounded,
          label: provider.t('ctx.groupList'),
          color: const Color(0xFFFFB347),
          onTap: () {
            _removeOverlay();
            _showGroupListDialog(context, provider);
          },
        ),
      // ── 基準位置の「設定」 と「移動」 を 1 項目に統合 (= ユーザー要望) ──
      // クリックで 2 択ダイアログ (基準位置を設定 / 基準位置へ移動) を出す。
      // ※ 上下の区切り線は「変な線が入る」 との指摘で撤去 (= ユーザー要望)。
      _CtxMenuItem(
        icon: Icons.gps_fixed_rounded,
        label: provider.t('ctx.basePosition'),
        color: const Color(0xFF43B97F),
        onTap: () {
          _removeOverlay();
          _showRefChooser(globalPos);
        },
      ),
      _CtxMenuItem(
        icon: Icons.text_fields_rounded,
        label: provider.t('ctx.fontSizeSettings'),
        color: const Color(0xFFFFB347),
        onTap: () {
          _removeOverlay();
          _showGlobalFontSizeDialog(context, provider);
        },
      ),
    ];

    // 高さの見積りは「割り方を開いた状態」 で取る (= 開いても入りきるように)。
    final items = buildItems(true, () {});

    // 各項目の推定高さ (MenuItem=46, Toggle=44, Divider=1)
    double estH = 0;
    for (final w in items) {
      if (w is Divider) {
        estH += 1;
      } else if (w is _CtxMenuToggle) {
        estH += 44;
      } else {
        estH += 46;
      }
    }
    final maxAvail = sh - mq.padding.top - mq.padding.bottom - 32;
    final useTwoCol = estH > maxAvail;

    final double menuW = useTwoCol ? 420.0 : 210.0;
    double left = globalPos.dx.clamp(8.0, sw - menuW - 8.0);
    // ── ノード生成ボタンをカーソルと同じ高さに合わせる ──
    // デスクトップでは並びが 1番上=範囲選択 / 2番目=ノード生成 なので、
    // メニュー上端を「範囲選択 1 項目分 + ノード生成の半分」だけ上にずらして、
    // ノード生成ボタンの中央がカーソル位置に来るようにする。 2 カラム表示でも
    // ノード生成は左カラム 2 行目に来るため、 同じオフセットで成立する。
    // モバイルはこの 2 項目を出さない (下部バーに常設) ため補正しない。
    const double kCtxItemH = 46.0;
    final double nodeGenAnchorOffset = _isDesktop ? kCtxItemH * 1.5 : 0.0;
    double top = (globalPos.dy - nodeGenAnchorOffset).clamp(mq.padding.top + 8,
        sh - (useTwoCol ? estH / 2 + 16 : estH + 16).clamp(100.0, maxAvail));

    _overlayEntry = OverlayEntry(
      builder: (_) => StatefulBuilder(builder: (_, setMenuState) {
        final list = buildItems(splitExpanded,
            () => setMenuState(() => splitExpanded = !splitExpanded));
        return Stack(children: [
          Positioned.fill(
            child: GestureDetector(
              onTap: _removeOverlay,
              onSecondaryTap: _removeOverlay,
              behavior: HitTestBehavior.translucent,
              child: const SizedBox.expand(),
            ),
          ),
          Positioned(
            left: left,
            top: top,
            child: Material(
              color: Colors.transparent,
              child: Container(
                width: menuW,
                constraints: BoxConstraints(maxHeight: maxAvail),
                decoration: BoxDecoration(
                  color: const Color(0xFF1E1E32),
                  borderRadius: BorderRadius.circular(12),
                  border:
                      Border.all(color: Colors.white.withValues(alpha: 0.12)),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black.withValues(alpha: 0.6),
                      blurRadius: 20,
                      offset: const Offset(0, 6),
                    ),
                  ],
                ),
                child: useTwoCol
                    ? SingleChildScrollView(child: _buildTwoColMenu(list))
                    : SingleChildScrollView(
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: list,
                        ),
                      ),
              ),
            ),
          ),
          // ── 割り方は「右に」 出す (= ユーザー要望) ──
          //    項目そのものの位置を測って、 その右隣に並べる。
          if (splitExpanded && !_mapSplitOpen)
            _buildSplitLayoutFlyout(provider, splitItemKey, sw, sh),
        ]);
      }),
    );
    Overlay.of(context, rootOverlay: true).insert(_overlayEntry!);
  }

  /// 右クリックメニューの「マップを分割表示」 の右隣に出す、 割り方の板
  /// (= ユーザー要望: 開くと右に項目が出るように)。
  /// [itemKey] は分割項目そのもの。 その画面座標を測って隣に並べる。
  Widget _buildSplitLayoutFlyout(
      MindMapProvider provider, GlobalKey itemKey, double sw, double sh) {
    final box = itemKey.currentContext?.findRenderObject() as RenderBox?;
    if (box == null || !box.hasSize) return const SizedBox.shrink();
    final Offset at;
    try {
      at = box.localToGlobal(Offset.zero);
    } catch (_) {
      return const SizedBox.shrink();
    }
    const double w = 190.0;
    final rows = <Widget>[
      _CtxSplitOption(
        icon: Icons.horizontal_split_rounded,
        label: provider.t('map.splitModeTopBottom'),
        checked: _mapSplitOpen && !_mapSplitQuad && _mapSplitStacked,
        onTap: () {
          _removeOverlay();
          // ignore: discarded_futures
          _applyMapSplitMode(panes: 2, stacked: true);
        },
      ),
      _CtxSplitOption(
        icon: Icons.vertical_split_rounded,
        label: provider.t('map.splitModeLeftRight'),
        checked: _mapSplitOpen && !_mapSplitQuad && !_mapSplitStacked,
        onTap: () {
          _removeOverlay();
          // ignore: discarded_futures
          _applyMapSplitMode(panes: 2, stacked: false);
        },
      ),
      // モバイルは画面が小さいので 4 分割は出さない
      // (= _buildMapSplitModeButtons と同じ扱い)。
      if (_isDesktop)
        _CtxSplitOption(
          icon: Icons.grid_view_rounded,
          label: provider.t('map.splitQuad'),
          checked: _mapSplitOpen && _mapSplitQuad,
          onTap: () {
            _removeOverlay();
            // ignore: discarded_futures
            _applyMapSplitMode(panes: 4, stacked: false);
          },
        ),
    ];
    final double h = rows.length * 36.0 + 10;
    // 右に置けなければ左へ回す (= 画面の端でも見えるように)。
    double left = at.dx + box.size.width + 6;
    if (left + w > sw - 8) left = at.dx - w - 6;
    left = left.clamp(8.0, (sw - w - 8).clamp(8.0, sw));
    final double top = (at.dy - 4).clamp(8.0, (sh - h - 8).clamp(8.0, sh));
    return Positioned(
      left: left,
      top: top,
      child: Material(
        color: Colors.transparent,
        child: Container(
          width: w,
          padding: const EdgeInsets.symmetric(vertical: 5, horizontal: 4),
          decoration: BoxDecoration(
            color: const Color(0xFF23233A),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(color: Colors.white.withValues(alpha: 0.16)),
            boxShadow: [
              BoxShadow(
                color: Colors.black.withValues(alpha: 0.6),
                blurRadius: 18,
                offset: const Offset(0, 5),
              ),
            ],
          ),
          child: Column(mainAxisSize: MainAxisSize.min, children: rows),
        ),
      ),
    );
  }

  /// ─── マップの背景画像設定ダイアログ ─────────────────────────────────
  /// ユーザー要望「マップの背景画像をユーザーが自由にカスタマイズ」 への
  /// 対応。画像の選択 / 解除 / 不透明度 (0〜100) / 表示モード
  /// (cover / contain / tile) をまとめて編集できる。
  /// マップ毎のメモを編集するダイアログ (= ユーザー要望: ヘッダーのメモ
  /// ボタンでマップ毎にメモを保存できるように)。 現在のマップ (ページ) ごとに
  /// 1 つのメモを SharedPreferences に保存する。
  /// 保存文字列 (Quill Delta JSON / 旧 Markdown・プレーン) から QuillController を作る。
  /// 旧形式 (Markdown/プレーン) は平文として読み込む (= 後方互換)。
  /// 保存済みのメモ本文 (旧 Quill Delta JSON もしくは素のテキスト) から
  /// 素のテキストだけを取り出す (= ユーザー要望: マップメモは単純な
  /// テキスト入力にする)。 旧データからの移行にも使う。
  String _mapMemoPlainFromStored(String stored) {
    final t = stored.trim();
    if (t.isEmpty) return '';
    // Delta JSON なら insert を連結して素のテキストにする。
    if (t.startsWith('[')) {
      try {
        final decoded = jsonDecode(t);
        if (decoded is List) {
          final sb = StringBuffer();
          for (final op in decoded) {
            if (op is Map && op['insert'] is String) {
              sb.write(op['insert']);
            }
          }
          return sb.toString().replaceAll(RegExp(r'\n$'), '');
        }
      } catch (_) {}
    }
    return stored;
  }

  QuillController _mapMemoQuillFromStored(String stored) {
    final s = stored.trim();
    Document doc;
    if (s.isEmpty) {
      doc = Document();
    } else {
      try {
        final decoded = jsonDecode(s);
        if (decoded is List) {
          doc = Document.fromJson(decoded);
        } else {
          doc = Document.fromJson([
            {'insert': '$s\n'}
          ]);
        }
      } catch (_) {
        doc = Document.fromJson([
          {'insert': '$s\n'}
        ]);
      }
    }
    return QuillController(
      document: doc,
      selection: const TextSelection.collapsed(offset: 0),
    );
  }

  /// flutter_quill のデフォルト文字色を白に強制する DefaultStyles
  /// (= ユーザー要望: ノード編集・マップメモのリッチテキストが暗背景に黒文字で
  ///  見えない)。 段落・見出し・リスト・引用など全ブロック種を白で上書きし、
  ///  プレースホルダは下線なしの淡い白にする。 flutter_quill はプレーン行を
  ///  `defaultStyles.paragraph.style` で描くので、 これを白にすれば本文が白になる。
  DefaultStyles _whiteQuillStyles(BuildContext ctx) {
    DefaultTextBlockStyle? blk(DefaultTextBlockStyle? b) => b == null
        ? null
        : DefaultTextBlockStyle(
            b.style.copyWith(color: Colors.white),
            b.horizontalSpacing,
            b.verticalSpacing,
            b.lineSpacing,
            b.decoration);
    final base = DefaultStyles.getInstance(ctx);
    final ph = base.placeHolder;
    return base.merge(DefaultStyles(
      paragraph: blk(base.paragraph),
      h1: blk(base.h1),
      h2: blk(base.h2),
      h3: blk(base.h3),
      h4: blk(base.h4),
      h5: blk(base.h5),
      h6: blk(base.h6),
      // lists は DefaultListBlockStyle 型なので copyWith で白にする
      //   (blk は DefaultTextBlockStyle を返すため型が合わない)。
      lists: base.lists == null
          ? null
          : base.lists!
              .copyWith(style: base.lists!.style.copyWith(color: Colors.white)),
      quote: blk(base.quote),
      // プレースホルダ (ヒント) は下線なしの淡い白 (= ユーザー要望: 黄色い
      //   下線が邪魔)。 spacing は既存値を流用。
      placeHolder: ph == null
          ? null
          : DefaultTextBlockStyle(
              const TextStyle(
                  color: Color(0x80FFFFFF),
                  fontSize: 16,
                  fontWeight: FontWeight.w400,
                  decoration: TextDecoration.none),
              ph.horizontalSpacing,
              ph.verticalSpacing,
              ph.lineSpacing,
              null),
    ));
  }

  /// [inPane] が true の時は、 渡された [ctx] の Navigator (= 分割ペインの
  /// 中の入れ物) に出す (= ユーザー要望: メモも左右分割で開けるように)。
  Future<void> _showMapMemoDialog(BuildContext ctx, MindMapProvider provider,
      {bool inPane = false}) async {
    final pageId = provider.currentPage.id;
    final pageTitle = provider.currentPage.name;
    String defaultItemName(int number) =>
        provider.t('memo.defaultItemName').replaceFirst('{n}', '$number');
    bool global = await _MapMemoStore.loadScope(pageId);
    // ── 複数メモ項目 (= ユーザー要望: 項目を複数登録して切り替え) ──
    var data = await _MapMemoStore.loadItems(pageId, global,
        defaultItemName: defaultItemName(1));
    List<_MapMemoItem> items = data.items;
    int selected = data.selected;
    if (!mounted) return;
    // 作成した QuillController を保持して最後に dispose (項目/スコープ切替で
    //   作り直しても use-after-dispose にならないように)。
    // 素のテキスト入力 1 本 (= ユーザー要望: リッチテキスト廃止)。
    final textCtrl = TextEditingController(
        text: _mapMemoPlainFromStored(items[selected].body));
    // 「キャンセル」 を明示的に押した時だけ true。 それ以外の閉じ方
    //   (バリアタップ / 戻るジェスチャー / 「保存」) では編集内容を保存する
    //   (= ユーザー要望: キャンセルを押さずに閉じたら保存)。
    bool cancelled = false;

    // 現在の編集内容を選択中の項目に書き戻す (保存・切替の前に必ず呼ぶ)。
    void syncCurrentToItem() {
      if (selected >= 0 && selected < items.length) {
        items[selected].body = textCtrl.text;
      }
    }

    Future<void> persist() async {
      syncCurrentToItem();
      await _MapMemoStore.saveItems(pageId, global, items, selected);
      await _MapMemoStore.saveScope(pageId, global);
    }

    await showDialog<void>(
      context: ctx,
      // ペインの中に出す時は、 そのペインの入れ物に出す (= 画面全体を
      // 覆わないように)。
      useRootNavigator: !inPane,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        // ── 項目操作 (切替/追加/名前変更/削除) ──
        void selectItem(int i) {
          if (i == selected || i < 0 || i >= items.length) return;
          syncCurrentToItem();
          selected = i;
          textCtrl.text = _mapMemoPlainFromStored(items[selected].body);
          setD(() {});
        }

        void addItem() {
          syncCurrentToItem();
          items.add(_MapMemoItem(defaultItemName(items.length + 1), ''));
          selected = items.length - 1;
          textCtrl.text = '';
          setD(() {});
        }

        void deleteItem() {
          if (items.length <= 1) {
            // 最後の 1 件は消さず空にする。
            items[selected] = _MapMemoItem(defaultItemName(1), '');
          } else {
            items.removeAt(selected);
            if (selected >= items.length) selected = items.length - 1;
          }
          textCtrl.text = _mapMemoPlainFromStored(items[selected].body);
          setD(() {});
        }

        Future<void> renameItem() async {
          final rc = TextEditingController(text: items[selected].name);
          final name = await showDialog<String>(
            context: dctx,
            builder: (rctx) => AlertDialog(
              backgroundColor: const Color(0xFF2A2A3E),
              title: Text(provider.t('memo.itemName'),
                  style: const TextStyle(color: Colors.white, fontSize: 15)),
              content: TextField(
                controller: rc,
                autofocus: true,
                style: const TextStyle(color: Colors.white),
                decoration: const InputDecoration(
                  hintStyle: TextStyle(color: Colors.white38),
                  enabledBorder: UnderlineInputBorder(
                      borderSide: BorderSide(color: Colors.white24)),
                  focusedBorder: UnderlineInputBorder(
                      borderSide: BorderSide(color: Color(0xFFFFB347))),
                ),
                onSubmitted: (v) => Navigator.pop(rctx, v),
              ),
              actions: [
                TextButton(
                    onPressed: () => Navigator.pop(rctx),
                    child: Text(provider.t('btn.cancel'),
                        style: const TextStyle(color: Colors.white54))),
                ElevatedButton(
                    style: ElevatedButton.styleFrom(
                        backgroundColor: const Color(0xFFFFB347),
                        foregroundColor: Colors.black),
                    onPressed: () => Navigator.pop(rctx, rc.text),
                    child: const Text('OK')),
              ],
            ),
          );
          if (name != null && name.trim().isNotEmpty) {
            items[selected].name = name.trim();
            setD(() {});
          }
        }

        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            const Icon(Icons.sticky_note_2_rounded,
                color: Color(0xFFFFB347), size: 20),
            const SizedBox(width: 10),
            Expanded(
              child: Text(
                  global
                      ? provider.t('memo.titleGlobal')
                      : provider
                          .t('memo.titlePage')
                          .replaceFirst('{title}', pageTitle),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(color: Colors.white, fontSize: 15)),
            ),
            // ── フローティングに切り替え (= ユーザー要望) ──
            //   今の内容を保存してから、 アプリの外／浮遊のメモ窓を開く。
            IconButton(
              tooltip: provider.t('split.toFloating'),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints(minWidth: 30, minHeight: 30),
              icon: const Icon(Icons.picture_in_picture_alt_rounded,
                  color: Color(0xFF80CBC4), size: 18),
              onPressed: () async {
                await persist();
                // メモ本文を浮遊メモへ引き継ぐ。
                try {
                  final sp = await SharedPreferences.getInstance();
                  await sp.setString('floating_memo_text_v1', textCtrl.text);
                } catch (_) {}
                if (!dctx.mounted) return;
                Navigator.pop(dctx);
                unawaited(_openPopOutWindow(provider, kind: 'memo'));
              },
            ),
          ]),
          content: SizedBox(
            width: 440,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // ── スコープ選択 (ここ限定 / 全体) (= ユーザー要望: 表記変更) ──
                SegmentedButton<bool>(
                  segments: [
                    ButtonSegment(
                        value: false,
                        label: Text(provider.t('memo.scopeHere')),
                        icon: const Icon(Icons.description_outlined, size: 16)),
                    ButtonSegment(
                        value: true,
                        label: Text(provider.t('memo.scopeGlobal')),
                        icon: const Icon(Icons.public_rounded, size: 16)),
                  ],
                  selected: {global},
                  showSelectedIcon: false,
                  // 選択中タブの文字が黒くて見えない問題を修正 (= ユーザー要望:
                  //   見やすい色に)。 選択中は紫背景＋白文字、 非選択は白系。
                  style: SegmentedButton.styleFrom(
                    visualDensity: VisualDensity.compact,
                    foregroundColor: Colors.white70,
                    selectedForegroundColor: Colors.white,
                    selectedBackgroundColor:
                        const Color(0xFF6C63FF).withValues(alpha: 0.55),
                  ),
                  onSelectionChanged: (s) async {
                    final g = s.first;
                    // 切替前に今のスコープへ保存してから、 新スコープを読込。
                    syncCurrentToItem();
                    await _MapMemoStore.saveItems(
                        pageId, global, items, selected);
                    final d = await _MapMemoStore.loadItems(pageId, g,
                        defaultItemName: defaultItemName(1));
                    items = d.items;
                    selected = d.selected;
                    textCtrl.text =
                        _mapMemoPlainFromStored(items[selected].body);
                    global = g;
                    setD(() {});
                  },
                ),
                const SizedBox(height: 8),
                // ── メモ項目タブ + 追加/名前変更/削除 (= ユーザー要望: 複数登録
                //    して切り替え) ──
                Row(children: [
                  Expanded(
                    child: SingleChildScrollView(
                      scrollDirection: Axis.horizontal,
                      child: Row(children: [
                        for (int i = 0; i < items.length; i++)
                          Padding(
                            padding: const EdgeInsets.only(right: 6),
                            child: GestureDetector(
                              onTap: () => selectItem(i),
                              // ダブルクリックでそのタブ (メモ) の名前を変更
                              //   (= ユーザー要望: マップメモ名はダブルクリックで
                              //    名前変更できるように)。 先にそのタブを選択して
                              //    から rename する。
                              onDoubleTap: () {
                                if (i != selected) selectItem(i);
                                renameItem();
                              },
                              child: Container(
                                padding: const EdgeInsets.symmetric(
                                    horizontal: 12, vertical: 6),
                                decoration: BoxDecoration(
                                  color: i == selected
                                      ? const Color(0xFFFFB347)
                                          .withValues(alpha: 0.25)
                                      : Colors.white10,
                                  borderRadius: BorderRadius.circular(16),
                                  border: Border.all(
                                      color: i == selected
                                          ? const Color(0xFFFFB347)
                                          : Colors.white24),
                                ),
                                child: Text(items[i].name,
                                    style: TextStyle(
                                        color: i == selected
                                            ? Colors.white
                                            : Colors.white70,
                                        fontSize: 12,
                                        fontWeight: i == selected
                                            ? FontWeight.w700
                                            : FontWeight.w500)),
                              ),
                            ),
                          ),
                      ]),
                    ),
                  ),
                  IconButton(
                    tooltip: provider.t('memo.addItem'),
                    visualDensity: VisualDensity.compact,
                    icon: const Icon(Icons.add_circle_outline_rounded,
                        color: Color(0xFFFFB347), size: 20),
                    onPressed: addItem,
                  ),
                  IconButton(
                    tooltip: provider.t('drawer.rename'),
                    visualDensity: VisualDensity.compact,
                    icon: const Icon(Icons.edit_outlined,
                        color: Colors.white54, size: 18),
                    onPressed: renameItem,
                  ),
                  IconButton(
                    tooltip: provider.t('btn.delete'),
                    visualDensity: VisualDensity.compact,
                    icon: const Icon(Icons.delete_outline_rounded,
                        color: Color(0xFFE57373), size: 18),
                    onPressed: deleteItem,
                  ),
                ]),
                const SizedBox(height: 8),
                // ── 貼り付けた画像 (= ユーザー要望: マップメモに画像を
                //    貼れるように) ──
                //    クリップボードから (Ctrl+V と同じ内容) か、 ファイルを
                //    選んで足す。 画像はアプリの中へコピーして持つ。
                Builder(builder: (imgCtx) {
                  final imgs = items[selected].images;
                  Future<void> addFromClipboard() async {
                    final path = await _importMemoImageFromClipboard();
                    if (path == null) {
                      if (dctx.mounted) {
                        _appSnack(
                            dctx,
                            SnackBar(
                                content: Text(provider.t('memo.noImage')),
                                duration: const Duration(seconds: 2)));
                      }
                      return;
                    }
                    setD(() => imgs.add(path));
                    await persist();
                  }

                  Future<void> addFromFile() async {
                    final res = await FilePicker.platform.pickFiles(
                        dialogTitle: provider.t('pick.image'),
                        type: FileType.image);
                    final p = res?.files.single.path;
                    if (p == null) return;
                    final path = await _importMemoImage(srcPath: p);
                    if (path == null) return;
                    setD(() => imgs.add(path));
                    await persist();
                  }

                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(children: [
                        TextButton.icon(
                          style: TextButton.styleFrom(
                              visualDensity: VisualDensity.compact,
                              foregroundColor: const Color(0xFFFFB347)),
                          icon: const Icon(Icons.content_paste_rounded,
                              size: 15),
                          label: Text(provider.t('memo.pasteImage'),
                              style: const TextStyle(fontSize: 11.5)),
                          onPressed: addFromClipboard,
                        ),
                        TextButton.icon(
                          style: TextButton.styleFrom(
                              visualDensity: VisualDensity.compact,
                              foregroundColor: Colors.white54),
                          icon: const Icon(Icons.image_outlined, size: 15),
                          label: Text(provider.t('memo.addImageFile'),
                              style: const TextStyle(fontSize: 11.5)),
                          onPressed: addFromFile,
                        ),
                      ]),
                      if (imgs.isNotEmpty)
                        SizedBox(
                          height: 86,
                          child: ListView.separated(
                            scrollDirection: Axis.horizontal,
                            itemCount: imgs.length,
                            separatorBuilder: (_, __) =>
                                const SizedBox(width: 6),
                            itemBuilder: (_, i) => Stack(children: [
                              ClipRRect(
                                borderRadius: BorderRadius.circular(6),
                                child: Image.file(File(imgs[i]),
                                    width: 110,
                                    height: 82,
                                    fit: BoxFit.cover,
                                    errorBuilder: (_, __, ___) => Container(
                                          width: 110,
                                          height: 82,
                                          color: Colors.white10,
                                          child: const Icon(
                                              Icons.broken_image_outlined,
                                              color: Colors.white24),
                                        )),
                              ),
                              Positioned(
                                right: 0,
                                top: 0,
                                child: InkWell(
                                  onTap: () async {
                                    setD(() => imgs.removeAt(i));
                                    await persist();
                                  },
                                  child: Container(
                                    decoration: BoxDecoration(
                                      color:
                                          Colors.black.withValues(alpha: 0.6),
                                      borderRadius: const BorderRadius.only(
                                          bottomLeft: Radius.circular(6)),
                                    ),
                                    padding: const EdgeInsets.all(2),
                                    child: const Icon(Icons.close_rounded,
                                        size: 14, color: Colors.white70),
                                  ),
                                ),
                              ),
                            ]),
                          ),
                        ),
                      const SizedBox(height: 8),
                    ],
                  );
                }),
                // ── 単純なテキスト入力 (= ユーザー要望: リッチテキストは
                //    要らない。 テキストを打てるだけのメモに) ──
                Container(
                  height: 300,
                  width: double.infinity,
                  padding: const EdgeInsets.all(10),
                  decoration: BoxDecoration(
                    color: const Color(0xFF121212),
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(color: Colors.white24),
                  ),
                  child: TextField(
                    controller: textCtrl,
                    maxLines: null,
                    expands: true,
                    textAlignVertical: TextAlignVertical.top,
                    keyboardType: TextInputType.multiline,
                    style: const TextStyle(color: Colors.white, fontSize: 14),
                    cursorColor: const Color(0xFFFFB347),
                    decoration: InputDecoration(
                      isDense: true,
                      border: InputBorder.none,
                      hintText: provider.t(global
                          ? 'memo.placeholderGlobal'
                          : 'memo.placeholderPage'),
                      hintStyle:
                          const TextStyle(color: Colors.white38, fontSize: 13),
                    ),
                  ),
                ),
              ],
            ),
          ),
          actions: [
            // ── ファイルを読み込む (= ユーザー要望: 書き出しはできるのに
            //    読み込みができない)。 今のメモに差し替え / 末尾に足す。 ──
            TextButton.icon(
              style: TextButton.styleFrom(foregroundColor: Colors.white70),
              icon: const Icon(Icons.file_open_outlined, size: 16),
              label: const Text('読み込む', style: TextStyle(fontSize: 12)),
              onPressed: () async {
                final loaded = await _pickTextFileForMemo(dctx);
                if (loaded == null || !dctx.mounted) return;
                final cur = textCtrl.text;
                setD(() {
                  textCtrl.text = loaded.mode == 'append' && cur.isNotEmpty
                      ? '$cur\n\n${loaded.text}'
                      : loaded.text;
                  textCtrl.selection = TextSelection.collapsed(
                      offset: textCtrl.text.length);
                });
                syncCurrentToItem();
              },
            ),
            // ── テキストで保存 (= ユーザー要望: メモを .txt に書き出す) ──
            //    右クリック / 長押しで保存場所の設定 (= ユーザー要望)。
            Builder(builder: (btnCtx) {
              return GestureDetector(
                onSecondaryTap: () {
                  // ignore: discarded_futures
                  _showMemoSaveDirMenu(btnCtx);
                },
                onLongPress: () {
                  // ignore: discarded_futures
                  _showMemoSaveDirMenu(btnCtx);
                },
                child: Tooltip(
                  message: '${provider.t('memo.saveAsText')}\n'
                      '${provider.t('memo.saveDirHint')}',
                  triggerMode: TooltipTriggerMode.manual,
                  child: TextButton.icon(
                    style:
                        TextButton.styleFrom(foregroundColor: Colors.white70),
                    icon: const Icon(Icons.save_alt_rounded, size: 16),
                    label: Text(provider.t('memo.saveAsText'),
                        style: const TextStyle(fontSize: 12)),
                    onPressed: () async {
                      syncCurrentToItem();
                      final it = items[selected];
                      final buf = StringBuffer()
                        ..writeln(it.name)
                        ..writeln('')
                        ..writeln(it.body);
                      if (it.images.isNotEmpty) {
                        buf
                          ..writeln('')
                          ..writeln('--- 画像 ---');
                        for (final p in it.images) {
                          buf.writeln(p);
                        }
                      }
                      await _saveTextFile(
                          suggestedName: '${it.name}.txt',
                          content: buf.toString());
                    },
                  ),
                ),
              );
            }),
            // ── メモをページに埋め込む (= ユーザー要望: 「ブロックとして
            //    配置」 から表記変更 + 埋め込むページも選べるように)。
            //    ギャラリーならブロック、 マップならメモ要素として置く。 ──
            TextButton.icon(
              onPressed: () async {
                final text = textCtrl.text.trim();
                if (text.isEmpty) return;
                // 追加先を選ぶ (ノードを置ける種類だけ)。
                final targets = <int>[
                  for (int i = 0; i < provider.pages.length; i++)
                    if (provider.pages[i].pageType == 'normal' ||
                        provider.pages[i].pageType == 'bookshelf')
                      i
                ];
                if (targets.isEmpty) return;
                final picked = await showDialog<int>(
                  context: dctx,
                  builder: (pctx) => AlertDialog(
                    backgroundColor: const Color(0xFF1E1E32),
                    title: Text(provider.t('md.pickTargetPage'),
                        style: const TextStyle(
                            color: Colors.white, fontSize: 15)),
                    content: SizedBox(
                      width: 320,
                      height: math.min(380.0,
                          20.0 + 44.0 * math.max(2, targets.length)),
                      child: ListView.builder(
                        itemCount: targets.length,
                        itemBuilder: (_, k) {
                          final i = targets[k];
                          final pg = provider.pages[i];
                          final isCur = pg.id == provider.currentPage.id;
                          return ListTile(
                            dense: true,
                            leading: Icon(
                                pg.pageType == 'bookshelf'
                                    ? Icons.shelves
                                    : Icons.map_rounded,
                                size: 17,
                                color: pg.pageType == 'bookshelf'
                                    ? const Color(0xFFFF7043)
                                    : const Color(0xFF8B84FF)),
                            title: Text(
                                isCur
                                    ? '${pg.name}${provider.t('copyTo.currentSuffix')}'
                                    : pg.name,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                    color: Colors.white, fontSize: 13)),
                            onTap: () => Navigator.pop(pctx, i),
                          );
                        },
                      ),
                    ),
                    actions: [
                      TextButton(
                        onPressed: () => Navigator.pop(pctx),
                        child: Text(provider.t('btn.cancel'),
                            style:
                                const TextStyle(color: Colors.white54)),
                      ),
                    ],
                  ),
                );
                if (picked == null) return;
                final pg = provider.pages[picked];
                if (pg.pageType == 'bookshelf' &&
                    pg.id == provider.currentPage.id &&
                    !await _confirmGalleryExpand(context, provider, 1)) {
                  return;
                }
                provider.addTextNoteToBookshelf(text, pageIndex: picked);
                if (dctx.mounted) Navigator.pop(dctx);
                _appSnack(
                    context,
                    SnackBar(
                      content: Text(provider.t('shelf.memoPlaced')),
                      backgroundColor: const Color(0xFF1A1A2E),
                      duration: const Duration(seconds: 2),
                    ));
              },
              icon: const Icon(Icons.view_module_rounded,
                  color: Color(0xFF26C6DA), size: 18),
              label: Text(provider.t('memo.placeAsBlock'),
                  style: const TextStyle(color: Color(0xFF26C6DA))),
            ),
            TextButton(
              onPressed: () {
                cancelled = true;
                Navigator.pop(dctx);
              },
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFFFB347),
                  foregroundColor: Colors.black),
              onPressed: () async {
                await persist();
                if (dctx.mounted) Navigator.pop(dctx);
              },
              child: Text(provider.t('btn.save')),
            ),
          ],
        );
      }),
    );
    // キャンセルを押さずに閉じた場合は編集内容を保存 (= ユーザー要望)。
    //   バリアタップ・戻るジェスチャーで閉じても保存される。 「保存」 ボタン
    //   経由の場合は既に保存済みだが、 もう一度書いても同内容で冪等。
    if (!cancelled) {
      try {
        await persist();
      } catch (_) {}
    }
    // ダイアログを閉じたらテキストコントローラを破棄。
    try {
      textCtrl.dispose();
    } catch (_) {}
  }

  /// マップメモ用の簡易 Markdown レンダラ (旧形式の表示用に残置・現在は未使用)。
  // ignore: unused_element
  List<Widget> _buildMapMemoMarkdown(String src) {
    final widgets = <Widget>[];
    for (final raw in src.split('\n')) {
      final t = raw.trim();
      if (t.isEmpty) {
        widgets.add(const SizedBox(height: 6));
        continue;
      }
      final img = RegExp(r'^!\[[^\]]*\]\(([^)]+)\)$').firstMatch(t);
      if (img != null) {
        widgets.add(_mapMemoImageWidget(img.group(1)!.trim()));
        continue;
      }
      if (t == '---' || t == '***') {
        widgets.add(const Divider(color: Colors.white24, height: 16));
        continue;
      }
      if (t.startsWith('### ')) {
        widgets.add(Padding(
          padding: const EdgeInsets.only(top: 4, bottom: 2),
          child: Text(t.substring(4),
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 14,
                  fontWeight: FontWeight.w700)),
        ));
        continue;
      }
      if (t.startsWith('## ')) {
        widgets.add(Padding(
          padding: const EdgeInsets.only(top: 6, bottom: 2),
          child: Text(t.substring(3),
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 16,
                  fontWeight: FontWeight.w700)),
        ));
        continue;
      }
      if (t.startsWith('# ')) {
        widgets.add(Padding(
          padding: const EdgeInsets.only(top: 6, bottom: 2),
          child: Text(t.substring(2),
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 18,
                  fontWeight: FontWeight.w800)),
        ));
        continue;
      }
      if (t.startsWith('- ') || t.startsWith('* ')) {
        widgets.add(Padding(
          padding: const EdgeInsets.only(left: 4, top: 1, bottom: 1),
          child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('•  ',
                style: TextStyle(color: Colors.white70, fontSize: 13)),
            Expanded(
              child: RichText(
                  text:
                      TextSpan(children: _mapMemoInlineSpans(t.substring(2)))),
            ),
          ]),
        ));
        continue;
      }
      widgets.add(Padding(
        padding: const EdgeInsets.symmetric(vertical: 1),
        child: RichText(
            text: TextSpan(children: _mapMemoInlineSpans(raw.trimRight()))),
      ));
    }
    return widgets;
  }

  /// インライン Markdown (**太字** / [テキスト](url)) を TextSpan に変換。
  List<InlineSpan> _mapMemoInlineSpans(String text) {
    const base = TextStyle(color: Colors.white, fontSize: 13, height: 1.4);
    final spans = <InlineSpan>[];
    final re = RegExp(r'\*\*(.+?)\*\*|\[([^\]]+)\]\(([^)]+)\)');
    int idx = 0;
    for (final m in re.allMatches(text)) {
      if (m.start > idx) {
        spans.add(TextSpan(text: text.substring(idx, m.start), style: base));
      }
      if (m.group(1) != null) {
        spans.add(TextSpan(
            text: m.group(1),
            style: base.copyWith(fontWeight: FontWeight.w700)));
      } else {
        final label = m.group(2)!;
        final url = m.group(3)!;
        spans.add(TextSpan(
          text: label,
          style: base.copyWith(
              color: const Color(0xFF6BB7E8),
              decoration: TextDecoration.underline),
          recognizer: TapGestureRecognizer()
            ..onTap = () => _openMapMemoLink(url),
        ));
      }
      idx = m.end;
    }
    if (idx < text.length) {
      spans.add(TextSpan(text: text.substring(idx), style: base));
    }
    if (spans.isEmpty) spans.add(TextSpan(text: text, style: base));
    return spans;
  }

  Widget _mapMemoImageWidget(String pathOrUrl) {
    Widget inner;
    if (pathOrUrl.startsWith('http')) {
      inner = Image.network(pathOrUrl,
          fit: BoxFit.contain,
          errorBuilder: (_, __, ___) => _mapMemoImgError());
    } else {
      final f = File(pathOrUrl);
      inner = f.existsSync()
          ? Image.file(f,
              fit: BoxFit.contain,
              errorBuilder: (_, __, ___) => _mapMemoImgError())
          : _mapMemoImgError();
    }
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 6),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(8),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxHeight: 260),
          child: inner,
        ),
      ),
    );
  }

  Widget _mapMemoImgError() => Container(
        height: 56,
        alignment: Alignment.center,
        color: Colors.white10,
        child: Text(context.read<MindMapProvider>().t('img.cannotDisplay'),
            style: TextStyle(color: Colors.white38, fontSize: 12)),
      );

  void _openMapMemoLink(String url) {
    try {
      _showWebDialog(context, url, initialTitle: url);
    } catch (_) {}
  }

  /// マップメモ用に画像を選んで attachments/ にコピーし、 そのパスを返す
  /// (旧 Markdown 用・現在は未使用。 リッチテキスト化に伴い保留)。
  // ignore: unused_element
  Future<String?> _pickMapMemoImagePath() async {
    try {
      final result = await FilePicker.platform.pickFiles(
        dialogTitle: context.read<MindMapProvider>().t('pick.image'),
        type: FileType.image,
        withData: false,
      );
      if (result == null || result.files.isEmpty) return null;
      final srcPath = result.files.single.path;
      if (srcPath == null || srcPath.isEmpty) return null;
      final appDir = await getApplicationDocumentsDirectory();
      final attachDir = Directory('${appDir.path}/attachments');
      if (!await attachDir.exists()) {
        await attachDir.create(recursive: true);
      }
      final ext = srcPath.contains('.')
          ? srcPath.substring(srcPath.lastIndexOf('.') + 1)
          : 'png';
      final destName = 'memo_${DateTime.now().millisecondsSinceEpoch}.$ext';
      final destPath = '${attachDir.path}/$destName';
      await File(srcPath).copy(destPath);
      return destPath;
    } catch (e) {
      debugPrint('マップメモ画像の挿入に失敗: $e');
      return null;
    }
  }

  /// フラッシュカード管理 (= ユーザー要望: フラッシュカードを単品で作成・編集
  /// できるように)。 マップ毎にカード (表/裏) を保存し、 一覧から学習を始める。
  Future<void> _showFlashcardMode(BuildContext ctx, MindMapProvider provider,
      {
      // フローティング窓 (= アプリ内のドラッグできる小窓) で開くか。
      //   = ユーザー要望「フラッシュカードもフローティングモード等で開ける
      //   ように」。 ボタンの右クリック →「開き方」 で選ぶ。
      //   null = 今までの動き (パソコンは浮遊窓、 スマホはダイアログ)。
      bool? floating}) async {
    final pageId = provider.currentPage.id;
    // まとめ操作 (削除・フォルダー移動) から使うので控えておく。
    pageIdOfFc = pageId;
    _fcSelected.clear();
    _fcAnchor = null;
    var cards = await _FlashcardStore.load(pageId);
    if (!mounted) return;
    // ── 一覧の欄を差し替えて出すパネル (= ユーザー要望: プロンプトから生成 /
    //    AI修正 / 生成設定 は新しいモーダルを重ねず、 後ろの欄が切り替わる) ──
    var fcPane = 'list'; // list / prompt / fix / settings
    final promptCtrl = TextEditingController();
    final fixCtrl = TextEditingController();
    // AI生成パネルに添付した資料 (= ユーザー要望: 資料から生成と
    // プロンプトから生成を 1 つにまとめて、 資料もプロンプトも渡せるように)。
    String? attachPath;
    var attachName = '';
    // Ctrl+V で貼った画像 (= ユーザー要望: チャット欄に画像を貼れるように)。
    final genImgs = <AiInputImage>[];
    // AI修正の欄も同じ入力欄にする (= ユーザー要望)。 画像と資料を別に持つ。
    final fixImgs = <AiInputImage>[];
    String? fixAttachPath;
    var fixAttachName = '';
    // 生成設定パネルの下書き (開くたびに現在値から作り直す)。
    TextEditingController? sCount;
    TextEditingController? sPdfStart;
    TextEditingController? sPdfEnd;
    TextEditingController? sLineStart;
    TextEditingController? sLineCount;
    TextEditingController? sPrompt;
    var sFolder = '';
    var sFolderNames = <String>{};
    var sFormats = <String>{};
    var sRelated = false;
    var sAvoid = false;
    Widget dlg(BuildContext _) => StatefulBuilder(builder: (dctx, setD) {
        Future<void> reload() async {
          cards = await _FlashcardStore.load(pageId);
          if (dctx.mounted) setD(() {});
        }

        // パネルを閉じて一覧へ戻る。
        void backToList() => setD(() => fcPane = 'list');

        // ── AIで生成のパネル (資料の添付 + プロンプト。 = ユーザー要望:
        //    資料から生成とプロンプトから生成を 1 つに統合) ──
        Future<void> runPromptGen() async {
          final topic = promptCtrl.text.trim();
          final path = attachPath;
          final photos = List<AiInputImage>.of(genImgs);
          if (path == null && topic.isEmpty && photos.isEmpty) return;
          backToList();
          if (path != null) {
            // 資料あり: プロンプトは抽出の指示として渡す (空でもよい)。
            await _runFlashcardDocGen(pageId, provider,
                path: path, fileName: attachName, prompt: topic);
          } else {
            await _runFlashcardKeywordGen(pageId, provider, topic,
                images: photos.isEmpty ? null : photos);
          }
          promptCtrl.clear();
          attachPath = null;
          attachName = '';
          genImgs.clear();
          await reload();
        }

        Future<String?> pickFlashcardFile() async {
          final picked = await FilePicker.platform.pickFiles(
              dialogTitle: provider.t('pick.flashcardFile'),
              type: FileType.custom,
              allowedExtensions: ['pdf', 'docx', 'pptx', 'txt', 'md']);
          return picked?.files.single.path;
        }

        Future<void> pickAttach() async {
          final picked = await FilePicker.platform.pickFiles(
              dialogTitle: provider.t('pick.flashcardFile'),
              type: FileType.custom,
              allowedExtensions: ['pdf', 'docx', 'pptx', 'txt', 'md']);
          final p = picked?.files.single.path;
          if (p == null) return;
          setD(() {
            attachPath = p;
            attachName = picked!.files.single.name;
          });
        }

        /// クリップボードの画像を取り込む (= ユーザー要望: Ctrl+V で貼れる)。
        /// 画像でなければ何もしない (文字はそのまま入力欄へ入る)。
        Future<void> pasteImageInto(List<AiInputImage> into) async {
          try {
            final bytes = await readClipboardImageBytes();
            if (bytes == null || bytes.isEmpty || !dctx.mounted) return;
            setD(() => into.add(AiInputImage(
                  mime: 'image/png',
                  base64: base64Encode(bytes),
                  name: 'clipboard.png',
                )));
          } catch (_) {}
        }

        /// 生成と修正で共通の入力欄 (= ユーザー要望: 修正の所も同じ形にして、
        /// Ctrl+V の画像貼り付けと資料の添付ができるように)。
        Widget chatInputBox({
          required TextEditingController ctrl,
          required Color accent,
          required String hint,
          required List<AiInputImage> imgs,
          required VoidCallback onSend,
          required VoidCallback onPickFile,
          required String attachTooltip,
          required String attachLabel,
          required bool hasAttach,
          required VoidCallback onClearAttach,
        }) =>
            Container(
              decoration: BoxDecoration(
                color: Colors.white.withValues(alpha: 0.06),
                borderRadius: BorderRadius.circular(16),
                border: Border.all(color: accent.withValues(alpha: 0.45)),
              ),
              padding: const EdgeInsets.fromLTRB(14, 10, 8, 8),
              child: Column(children: [
                // Enter で送信 / Shift+Enter で改行 / Ctrl+V で画像貼り付け。
                Focus(
                  onKeyEvent: (n, event) {
                    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
                      return KeyEventResult.ignored;
                    }
                    final isCtrl =
                        HardwareKeyboard.instance.isControlPressed ||
                            HardwareKeyboard.instance.isMetaPressed;
                    if (isCtrl &&
                        event.logicalKey == LogicalKeyboardKey.keyV) {
                      unawaited(pasteImageInto(imgs));
                      // 文字の貼り付けは邪魔しない。
                      return KeyEventResult.ignored;
                    }
                    if (event.logicalKey != LogicalKeyboardKey.enter &&
                        event.logicalKey != LogicalKeyboardKey.numpadEnter) {
                      return KeyEventResult.ignored;
                    }
                    if (HardwareKeyboard.instance.isShiftPressed) {
                      final sel = ctrl.selection;
                      final text = ctrl.text;
                      final start = sel.start >= 0 ? sel.start : text.length;
                      final end = sel.end >= 0 ? sel.end : text.length;
                      ctrl.value = TextEditingValue(
                        text: text.replaceRange(start, end, '\n'),
                        selection:
                            TextSelection.collapsed(offset: start + 1),
                      );
                      return KeyEventResult.handled;
                    }
                    onSend();
                    return KeyEventResult.handled;
                  },
                  child: TextField(
                    controller: ctrl,
                    autofocus: true,
                    minLines: 2,
                    maxLines: 8,
                    textInputAction: TextInputAction.newline,
                    style: const TextStyle(
                        color: Colors.white, fontSize: 13, height: 1.5),
                    decoration: InputDecoration(
                      isDense: true,
                      contentPadding: EdgeInsets.zero,
                      border: InputBorder.none,
                      hintText: hint,
                      hintStyle:
                          const TextStyle(color: Colors.white30, fontSize: 13),
                    ),
                  ),
                ),
                // 貼った画像の見出し。
                if (imgs.isNotEmpty)
                  Padding(
                    padding: const EdgeInsets.only(top: 6),
                    child: Align(
                      alignment: Alignment.centerLeft,
                      child: Wrap(spacing: 6, runSpacing: 6, children: [
                        for (var i = 0; i < imgs.length; i++)
                          Stack(children: [
                            ClipRRect(
                              borderRadius: BorderRadius.circular(6),
                              child: Image.memory(base64Decode(imgs[i].base64),
                                  width: 54,
                                  height: 54,
                                  fit: BoxFit.cover,
                                  gaplessPlayback: true),
                            ),
                            Positioned(
                              right: 0,
                              top: 0,
                              child: InkWell(
                                onTap: () => setD(() => imgs.removeAt(i)),
                                child: Container(
                                  decoration: const BoxDecoration(
                                      color: Colors.black54,
                                      shape: BoxShape.circle),
                                  child: const Icon(Icons.close_rounded,
                                      size: 13, color: Colors.white),
                                ),
                              ),
                            ),
                          ]),
                      ]),
                    ),
                  ),
                Row(children: [
                  // 資料の添付 (PDF / docx / pptx / txt / md)。
                  IconButton(
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 30, minHeight: 30),
                    tooltip: attachTooltip,
                    icon: Icon(Icons.attach_file_rounded,
                        size: 17,
                        color: hasAttach
                            ? const Color(0xFF7FD8A0)
                            : Colors.white54),
                    onPressed: onPickFile,
                  ),
                  Expanded(
                    child: Text(attachLabel,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                            color: hasAttach
                                ? const Color(0xFF7FD8A0)
                                : Colors.white30,
                            fontSize: 11)),
                  ),
                  if (hasAttach)
                    IconButton(
                      padding: EdgeInsets.zero,
                      constraints:
                          const BoxConstraints(minWidth: 26, minHeight: 26),
                      icon: const Icon(Icons.close_rounded,
                          size: 15, color: Colors.white38),
                      onPressed: onClearAttach,
                    ),
                  // 送信 (= アシスタントの ↑ ボタンと同じ)。
                  Material(
                    color: accent,
                    shape: const CircleBorder(),
                    child: InkWell(
                      customBorder: const CircleBorder(),
                      onTap: onSend,
                      child: const Padding(
                        padding: EdgeInsets.all(6),
                        child: Icon(Icons.arrow_upward_rounded,
                            size: 16, color: Colors.black),
                      ),
                    ),
                  ),
                ]),
              ]),
            );

        Widget promptPane() => Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(children: [
                  const Icon(Icons.auto_awesome_rounded,
                      color: Color(0xFF26C6DA), size: 18),
                  const SizedBox(width: 8),
                  Text(provider.t('flash.aiGen'),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 14,
                          fontWeight: FontWeight.w700)),
                  // 枚数・形式の注記は見出しの右に置く (= ユーザー要望)。
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(provider.t('flash.genCountNote'),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 11)),
                  ),
                ]),
                const SizedBox(height: 10),
                chatInputBox(
                  ctrl: promptCtrl,
                  accent: const Color(0xFF26C6DA),
                  hint: provider.t('flash.orderHint'),
                  imgs: genImgs,
                  onSend: () => unawaited(runPromptGen()),
                  onPickFile: () => unawaited(pickAttach()),
                  attachTooltip: provider.t('flash.attachDoc'),
                  attachLabel: attachPath == null
                      ? provider.t('md.fromFileNone')
                      : attachName,
                  hasAttach: attachPath != null,
                  onClearAttach: () => setD(() {
                    attachPath = null;
                    attachName = '';
                  }),
                ),
                const SizedBox(height: 6),
                Align(
                  alignment: Alignment.centerRight,
                  child: TextButton(
                      onPressed: backToList,
                      child: Text(provider.t('btn.cancel'),
                          style: const TextStyle(color: Colors.white54))),
                ),
              ],
            );

        // ── AI でカードを直すパネル (= ユーザー要望: 生成と同じ入力欄に
        //    して、 Ctrl+V の画像貼り付けと資料の添付ができるように) ──
        Future<void> runAiFix() async {
          final order = fixCtrl.text.trim();
          if (order.isEmpty) return;
          final photos = List<AiInputImage>.of(fixImgs);
          final path = fixAttachPath;
          backToList();
          // 添付された資料は文字にしてから渡す (画像はそのまま見せる)。
          var sourceText = '';
          if (path != null) {
            final dot = path.lastIndexOf('.');
            final ext = dot >= 0 ? path.substring(dot + 1).toLowerCase() : '';
            sourceText = await _extractAttachmentTextForAi(path, ext) ?? '';
          }
          await _runFlashcardAiFix(pageId, provider, order,
              images: photos.isEmpty ? null : photos, sourceText: sourceText);
          fixCtrl.clear();
          fixImgs.clear();
          fixAttachPath = null;
          fixAttachName = '';
          await reload();
        }

        Widget fixPane() {
          final visible = _fcVisible(cards);
          final picked = [
            for (final i in _fcSelected)
              if (i >= 0 && i < visible.length) i
          ];
          final n = picked.isEmpty ? cards.length : picked.length;
          return Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(children: [
                const Icon(Icons.auto_fix_high_rounded,
                    color: Color(0xFFBA68C8), size: 18),
                const SizedBox(width: 8),
                Text(provider.t('flash.aiFixTitle'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 14,
                        fontWeight: FontWeight.w700)),
                const Spacer(),
                Text(
                    provider
                        .t('flash.aiFixTarget')
                        .replaceFirst('{n}', '$n')
                        .replaceFirst(
                            '{scope}',
                            provider.t(picked.isEmpty
                                ? 'flash.aiFixAll'
                                : 'flash.aiFixSelected')),
                    style: const TextStyle(
                        color: Colors.white54, fontSize: 11.5)),
              ]),
              const SizedBox(height: 10),
              chatInputBox(
                ctrl: fixCtrl,
                accent: const Color(0xFFBA68C8),
                hint: provider.t('flash.aiFixHint'),
                imgs: fixImgs,
                onSend: () => unawaited(runAiFix()),
                onPickFile: () => unawaited(() async {
                  final p = await pickFlashcardFile();
                  if (p == null || !dctx.mounted) return;
                  setD(() {
                    fixAttachPath = p;
                    fixAttachName = p.split(RegExp(r'[\\/]')).last;
                  });
                }()),
                attachTooltip: provider.t('flash.attachDoc'),
                attachLabel: fixAttachPath == null
                    ? provider.t('md.fromFileNone')
                    : fixAttachName,
                hasAttach: fixAttachPath != null,
                onClearAttach: () => setD(() {
                  fixAttachPath = null;
                  fixAttachName = '';
                }),
              ),
              const SizedBox(height: 6),
              Align(
                alignment: Alignment.centerRight,
                child: TextButton(
                    onPressed: backToList,
                    child: Text(provider.t('btn.cancel'),
                        style: const TextStyle(color: Colors.white54))),
              ),
            ],
          );
        }

        // ── 生成設定のパネル ──
        void openSettingsPane() {
          sCount?.dispose();
          sPdfStart?.dispose();
          sPdfEnd?.dispose();
          sLineStart?.dispose();
          sLineCount?.dispose();
          sPrompt?.dispose();
          sCount =
              TextEditingController(text: _flashcardGenCount.toString());
          sPdfStart = TextEditingController(
              text: _fcPdfStart > 0 ? '$_fcPdfStart' : '');
          sPdfEnd = TextEditingController(
              text: _fcPdfEnd > 0 ? '$_fcPdfEnd' : '');
          sLineStart = TextEditingController(
              text: _fcTxtStartLine > 0 ? '$_fcTxtStartLine' : '');
          sLineCount = TextEditingController(
              text: _fcTxtLineCount > 0 ? '$_fcTxtLineCount' : '');
          sPrompt = TextEditingController(text: _fcPrompt);
          sFolder = _fcFolder.trim();
          sFolderNames = {
            for (final c in cards)
              if (c.group.trim().isNotEmpty) c.group.trim(),
            if (sFolder.isNotEmpty) sFolder,
          };
          sFormats = _fcFormat
              .split(',')
              .map((s) => s.trim())
              .where((s) => s.isNotEmpty)
              .toSet();
          if (sFormats.isEmpty) sFormats.add('auto');
          sRelated = _fcIncludeRelated;
          sAvoid = _fcAvoidExisting;
          setD(() => fcPane = 'settings');
        }

        void saveSettingsPane() {
          _flashcardGenCount =
              (int.tryParse(sCount?.text.trim() ?? '') ?? 15).clamp(1, 60);
          _fcPdfStart = int.tryParse(sPdfStart?.text.trim() ?? '') ?? 0;
          _fcPdfEnd = int.tryParse(sPdfEnd?.text.trim() ?? '') ?? 0;
          _fcTxtStartLine = (int.tryParse(sLineStart?.text.trim() ?? '') ?? 0)
              .clamp(0, 1 << 30);
          _fcTxtLineCount = int.tryParse(sLineCount?.text.trim() ?? '') ?? 0;
          _fcFormat = sFormats.isEmpty ? 'auto' : sFormats.join(',');
          _fcPrompt = sPrompt?.text.trim() ?? '';
          _fcFolder = sFolder.trim();
          _fcIncludeRelated = sRelated;
          _fcAvoidExisting = sAvoid;
          _persistFlashcardGenSettings();
          backToList();
        }

        Widget settingsPane() {
          Widget numField(String label, TextEditingController? c) =>
              TextField(
                controller: c,
                keyboardType: TextInputType.number,
                style: const TextStyle(color: Colors.white, fontSize: 13),
                decoration: _fcInputDeco(label),
              );
          final fmts = [
            ('auto', provider.t('fmt.auto')),
            ('term', provider.t('fmt.term')),
            ('qa', provider.t('quiz.qa')),
            ('cloze', provider.t('quiz.fillblank')),
            ('choice', provider.t('fmt.choice')),
            ('calc', provider.t('fmt.calc')),
            ('diagram', provider.t('fmt.diagram')),
            ('coding', provider.t('fmt.coding')),
          ];
          return Column(children: [
            Row(children: [
              const Icon(Icons.tune_rounded,
                  color: Color(0xFF26C6DA), size: 18),
              const SizedBox(width: 8),
              Text(provider.t('flash.genSettings'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 14,
                      fontWeight: FontWeight.w700)),
            ]),
            const SizedBox(height: 8),
            Expanded(
              child: SingleChildScrollView(
                child: Column(mainAxisSize: MainAxisSize.min, children: [
                  // ── 生成先フォルダー ──
                  Row(children: [
                    const Icon(Icons.folder_rounded,
                        color: Color(0xFF26C6DA), size: 18),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Container(
                        decoration: BoxDecoration(
                          color: Colors.white.withValues(alpha: 0.06),
                          borderRadius: BorderRadius.circular(8),
                        ),
                        padding:
                            const EdgeInsets.symmetric(horizontal: 12),
                        child: DropdownButtonHideUnderline(
                          child: DropdownButton<String>(
                            isExpanded: true,
                            value: sFolder.trim(),
                            dropdownColor: const Color(0xFF2A2A3E),
                            style: const TextStyle(
                                color: Colors.white, fontSize: 13),
                            items: [
                              DropdownMenuItem(
                                  value: '',
                                  child: Text(provider.t('flash.noFolder'),
                                      style: const TextStyle(
                                          color: Colors.white54,
                                          fontSize: 13))),
                              for (final g in sFolderNames.toList()..sort())
                                DropdownMenuItem(
                                    value: g,
                                    child: Text('📁 $g',
                                        style: const TextStyle(
                                            fontSize: 13))),
                            ],
                            onChanged: (v) =>
                                setD(() => sFolder = v ?? ''),
                          ),
                        ),
                      ),
                    ),
                    IconButton(
                      tooltip: provider.t('flash.newFolder'),
                      icon: const Icon(Icons.create_new_folder_rounded,
                          color: Color(0xFF26C6DA), size: 20),
                      onPressed: () async {
                        final name = await _askNewFlashcardFolder(dctx);
                        if (name == null || name.trim().isEmpty) return;
                        setD(() {
                          sFolderNames.add(name.trim());
                          sFolder = name.trim();
                        });
                      },
                    ),
                  ]),
                  const SizedBox(height: 12),
                  Row(children: [
                    Text(provider.t('flash.model'),
                        style: const TextStyle(
                            color: Colors.white54, fontSize: 12)),
                    const SizedBox(width: 8),
                    _AiModelPicker(provider: provider),
                  ]),
                  const SizedBox(height: 12),
                  numField(provider.t('flash.countHint'), sCount),
                  const SizedBox(height: 12),
                  Align(
                      alignment: Alignment.centerLeft,
                      child: Text(provider.t('flash.problemFormat'),
                          style: const TextStyle(
                              color: Colors.white54, fontSize: 12))),
                  const SizedBox(height: 4),
                  Wrap(spacing: 6, runSpacing: 6, children: [
                    for (final f in fmts)
                      FilterChip(
                        label: Text(f.$2),
                        selected: sFormats.contains(f.$1),
                        backgroundColor: const Color(0xFF2A2A3E),
                        selectedColor: const Color(0xFF26C6DA),
                        checkmarkColor: Colors.black,
                        labelStyle: TextStyle(
                            color: sFormats.contains(f.$1)
                                ? Colors.black
                                : Colors.white,
                            fontSize: 12),
                        onSelected: (sel) => setD(() {
                          if (f.$1 == 'auto') {
                            sFormats
                              ..clear()
                              ..add('auto');
                            return;
                          }
                          if (sel) {
                            sFormats
                              ..remove('auto')
                              ..add(f.$1);
                          } else if (sFormats.length > 1) {
                            sFormats.remove(f.$1);
                          } else {
                            sFormats
                              ..clear()
                              ..add('auto');
                          }
                        }),
                      ),
                  ]),
                  if (sFormats.contains('auto'))
                    Padding(
                      padding: const EdgeInsets.only(top: 6),
                      child: Text(provider.t('fmt.autoSub'),
                          style: const TextStyle(
                              color: Colors.white38,
                              fontSize: 11,
                              height: 1.4)),
                    ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: sPrompt,
                    minLines: 2,
                    maxLines: 4,
                    style:
                        const TextStyle(color: Colors.white, fontSize: 13),
                    decoration:
                        _fcInputDeco(provider.t('flash.promptLabel'))
                            .copyWith(
                      hintText: provider.t('flash.promptHint'),
                      hintStyle: const TextStyle(
                          color: Colors.white24, fontSize: 11),
                    ),
                  ),
                  SwitchListTile(
                    contentPadding: EdgeInsets.zero,
                    dense: true,
                    activeColor: const Color(0xFF26C6DA),
                    title: Text(provider.t('flash.relatedToggle'),
                        style: const TextStyle(
                            color: Colors.white, fontSize: 13)),
                    subtitle: Text(provider.t('flash.relatedSub'),
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 11)),
                    value: sRelated,
                    onChanged: (v) => setD(() => sRelated = v),
                  ),
                  SwitchListTile(
                    contentPadding: EdgeInsets.zero,
                    dense: true,
                    activeColor: const Color(0xFF26C6DA),
                    title: Text(provider.t('flash.noDupToggle'),
                        style: const TextStyle(
                            color: Colors.white, fontSize: 13)),
                    subtitle: Text(provider.t('flash.noDupSub'),
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 11)),
                    value: sAvoid,
                    onChanged: (v) => setD(() => sAvoid = v),
                  ),
                  const Divider(color: Colors.white12, height: 16),
                  Align(
                      alignment: Alignment.centerLeft,
                      child: Text(provider.t('flash.pdfPageRange'),
                          style: const TextStyle(
                              color: Colors.white54, fontSize: 12))),
                  const SizedBox(height: 4),
                  Row(children: [
                    Expanded(
                        child: numField(
                            provider.t('quiz.startPage'), sPdfStart)),
                    const SizedBox(width: 8),
                    Expanded(
                        child:
