  /// Windows の OS 通知 (local_notifier トースト) を表示する。
  /// ユーザー要望「windows 版の通知方法を OS 通知に」 への対応。
  /// クリックすると、 ウィンドウを前面に出して該当ノードを選択する
  /// (= 旧オーバーレイの「ノードへ」 と同じ挙動)。
  void _showWindowsOsNotification(String? nodeId, String title, String body) {
    try {
      final notification = LocalNotification(
        title: title.isNotEmpty ? title : 'マインドマップ通知',
        body: body,
      );
      notification.onClick = () {
        // ウィンドウを前面化してから該当ノードを選択。
        () async {
          try {
            await windowManager.show();
            await windowManager.focus();
          } catch (_) {}
        }();
        if (nodeId != null && nodeId.isNotEmpty && mounted) {
          try {
            final provider = context.read<MindMapProvider>();
            if (provider.nodes.containsKey(nodeId)) {
              provider.selectNode(nodeId);
            }
          } catch (_) {}
        }
      };
      notification.show();
      // ── 自動で閉じる (= ユーザー報告: 通知が閉じれずにずっと残り続ける) ──
      // local_notifier の Windows トーストは明示的に close しないと
      //   通知センターに残り続けるため、一定時間後に自動で閉じる。
      Timer(const Duration(seconds: 15), () {
        try {
          notification.close();
        } catch (_) {}
      });
    } catch (e) {
      debugPrint('Windows OS 通知の表示に失敗: $e');
      // 失敗時はアプリ内オーバーレイにフォールバック
      if (mounted) _showNodeNotificationOverlay(nodeId ?? '', title, body);
    }
  }

  /// 通知発火時にアプリ全面にオーバーレイ表示。
  /// ユーザーが「閉じる」 か 「該当ノードへジャンプ」 をタップするまで残る。
  void _showNodeNotificationOverlay(
      String nodeId, String title, String content) {
    if (!mounted) return;
    final overlay = Overlay.maybeOf(context, rootOverlay: true);
    if (overlay == null) return;
    final provider = context.read<MindMapProvider>();
    OverlayEntry? entry;
    void close() {
      try {
        entry?.remove();
      } catch (_) {}
    }

    entry = OverlayEntry(builder: (_) {
      return Positioned(
        top: 24,
        right: 24,
        child: Material(
          color: Colors.transparent,
          child: Container(
            constraints: const BoxConstraints(maxWidth: 360, minWidth: 280),
            decoration: BoxDecoration(
              color: const Color(0xFF22222E),
              borderRadius: BorderRadius.circular(12),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withValues(alpha: 0.5),
                  blurRadius: 16,
                  offset: const Offset(0, 6),
                ),
              ],
              border: Border.all(
                  color: const Color(0xFFFFA726).withValues(alpha: 0.4),
                  width: 1.5),
            ),
            padding: const EdgeInsets.all(14),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(children: [
                  const Icon(Icons.notifications_active_rounded,
                      color: Color(0xFFFFA726), size: 20),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(provider.t('notif.title'),
                        style: const TextStyle(
                            color: Color(0xFFFFA726),
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                            letterSpacing: 0.6)),
                  ),
                  IconButton(
                    icon: const Icon(Icons.close_rounded,
                        color: Colors.white54, size: 18),
                    padding: EdgeInsets.zero,
                    constraints: const BoxConstraints(),
                    onPressed: close,
                  ),
                ]),
                const SizedBox(height: 8),
                Text(title,
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 15,
                        fontWeight: FontWeight.w600),
                    maxLines: 3,
                    overflow: TextOverflow.ellipsis),
                if (content.isNotEmpty && content != title) ...[
                  const SizedBox(height: 6),
                  Text(content,
                      style:
                          const TextStyle(color: Colors.white70, fontSize: 13),
                      maxLines: 4,
                      overflow: TextOverflow.ellipsis),
                ],
                const SizedBox(height: 10),
                Row(
                  mainAxisAlignment: MainAxisAlignment.end,
                  children: [
                    TextButton.icon(
                      icon: const Icon(Icons.center_focus_strong_rounded,
                          color: Color(0xFFFFA726), size: 16),
                      label: Text(provider.t('notif.toNode'),
                          style: const TextStyle(color: Color(0xFFFFA726))),
                      onPressed: () {
                        close();
                        // ノードを選択状態にしてフォーカス。
                        // (centerOn 系のメソッドがあれば併用可)
                        try {
                          final provider = context.read<MindMapProvider>();
                          if (provider.nodes.containsKey(nodeId)) {
                            provider.selectNode(nodeId);
                          }
                        } catch (_) {}
                      },
                    ),
                  ],
                ),
              ],
            ),
          ),
        ),
      );
    });
    overlay.insert(entry);
    // ── 自動消去 (10 秒) ──
    Timer(const Duration(seconds: 10), close);
    // 同時にシステム音 (= ポモドーロタイマーの完了音と同じ仕組み)
    try {
      _AudioAlarm.playAlarm('node_notification');
    } catch (_) {}
  }

  /// 通知予約中の Timer 一覧 (nodeId → Timer)。
  /// 二重予約を防ぐため、 既存のものはキャンセルしてから登録。
  final Map<String, Timer> _pendingNotificationTimers = {};

  // ─── ファイルを作成 ────────────────────────────────────────────────
  //
  // ノード右クリックメニューから「ファイルを作成」 を選んだ時のフロー:
  // 1. ダイアログで形式 (txt / docx / pptx / xlsx / csv) + ファイル名を指定
  // 2. アプリの documents/attachments/ に空のテンプレートファイルを生成
  // 3. 子ノードは作らず、 押されたノード自身のタイトル = ファイル名、
  //    attachment = 生成したファイルとする (= ユーザー要望: そのノードがファイル化)
  // 4. ユーザーはそのノードをタップして、 内蔵エディタで開いて編集可能
  Future<void> _showCreateFileDialog(
      BuildContext ctx, MindMapProvider provider, String parentNodeId) async {
    final result = await _promptCreateFileTypeName(ctx, provider);
    if (result == null) return;
    await _createAndAttachFile(
        provider, parentNodeId, result['type']!, result['name']!);
  }

  /// 右クリック位置に新規ファイル (txt / md / docx 等) のノードを作る
  /// (= ユーザー要望: 右クリックからファイルを生成できるように。
  /// ギャラリーでは棚のセルへ自動配置)。
  Future<void> _createFileNodeAt(
      MindMapProvider provider, Offset canvasPos) async {
    final result = await _promptCreateFileTypeName(context, provider);
    if (result == null || !mounted) return;
    final page = provider.currentPage;
    final String? id = page.pageType == 'bookshelf'
        ? provider.mcpAddGalleryItem(page.id, text: result['name'])
        : provider.mcpAddNode(page.id,
            title: '', x: canvasPos.dx, y: canvasPos.dy);
    if (id == null) return;
    await _createAndAttachFile(
        provider, id, result['type']!, result['name']!);
  }

  /// ファイルの種類と名前を聞くダイアログ (種類パレット付き)。
  /// 生成先が違う複数の入口 (ノード右クリック / キャンバス右クリック) で共用。
  Future<Map<String, String>?> _promptCreateFileTypeName(
      BuildContext ctx, MindMapProvider provider) async {
    String selectedType = 'docx'; // デフォルト
    final nameCtrl =
        TextEditingController(text: provider.t('file.defaultName'));
    // クリックした場所の近くに出す (= ユーザー要望: 画面中央ではなく)。
    final result = await _showNearDialogMain<Map<String, String>>(
      width: 480,
      height: 430,
      builder: (dctx) {
        return StatefulBuilder(builder: (sctx, setS) {
          return AlertDialog(
            backgroundColor: const Color(0xFF22222E),
            title: Row(children: [
              const Icon(Icons.note_add_rounded,
                  color: Color(0xFF4FC3F7), size: 22),
              const SizedBox(width: 8),
              Text(provider.t('file.create'),
                  style: const TextStyle(color: Colors.white)),
            ]),
            // 窓 (480) から枠と余白を引いた幅に収める。 以前は 420 を
            // そのまま指定していて右がはみ出し、 中身が左に寄って見えた
            // (= ユーザー要望: バランスよく)。
            content: SizedBox(
              width: 340,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text(provider.t('file.format'),
                      style: const TextStyle(
                          color: Colors.white70,
                          fontSize: 12,
                          fontWeight: FontWeight.w600)),
                  const SizedBox(height: 8),
                  // ── 形式選択 (= ユーザー要望: 左に寄り過ぎないよう、
                  //    2 列で幅いっぱいに揃える) ──
                  Builder(builder: (bctx) {
                    final types = <(String, IconData, String, Color)>[
                      (
                        'txt',
                        Icons.text_snippet_outlined,
                        provider.t('file.txtType'),
                        const Color(0xFF9E9E9E)
                      ),
                      (
                        'md',
                        Icons.article_outlined,
                        'Markdown',
                        const Color(0xFF6C63FF)
                      ),
                      // HTML & CSS は一覧から外した (= ユーザー要望:
                      //   見栄えのため)。 作る仕組み自体は残してあるので、
                      //   .html のファイルを開けば今まで通り編集できる。
                      (
                        'docx',
                        Icons.description_outlined,
                        provider.t('file.wordDoc'),
                        const Color(0xFF2196F3)
                      ),
                      (
                        'pptx',
                        Icons.slideshow_outlined,
                        'PowerPoint',
                        const Color(0xFFE65100)
                      ),
                      (
                        'xlsx',
                        Icons.table_chart_outlined,
                        'Excel',
                        const Color(0xFF2E7D32)
                      ),
                      (
                        'csv',
                        Icons.view_list_outlined,
                        'CSV',
                        const Color(0xFF7B1FA2)
                      ),
                    ];
                    Widget tile((String, IconData, String, Color) t) {
                      final on = selectedType == t.$1;
                      return InkWell(
                        onTap: () => setS(() => selectedType = t.$1),
                        borderRadius: BorderRadius.circular(8),
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 10, vertical: 10),
                          decoration: BoxDecoration(
                            color: on
                                ? t.$4.withValues(alpha: 0.18)
                                : const Color(0xFF1A1A24),
                            borderRadius: BorderRadius.circular(8),
                            border: Border.all(
                              color: on ? t.$4 : Colors.white24,
                              width: on ? 2 : 1,
                            ),
                          ),
                          child: Row(
                            children: [
                              Icon(t.$2, color: t.$4, size: 20),
                              const SizedBox(width: 8),
                              Expanded(
                                child: Column(
                                  crossAxisAlignment:
                                      CrossAxisAlignment.start,
                                  children: [
                                    Text('.${t.$1}',
                                        style: TextStyle(
                                            color: t.$4,
                                            fontSize: 11,
                                            fontWeight: FontWeight.w700)),
                                    Text(t.$3,
                                        maxLines: 1,
                                        overflow: TextOverflow.ellipsis,
                                        style: const TextStyle(
                                            color: Colors.white,
                                            fontSize: 11)),
                                  ],
                                ),
                              ),
                            ],
                          ),
                        ),
                      );
                    }

                    return Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        for (var i = 0; i < types.length; i += 2)
                          Padding(
                            padding: EdgeInsets.only(
                                bottom: i + 2 < types.length ? 8 : 0),
                            child: Row(children: [
                              Expanded(child: tile(types[i])),
                              const SizedBox(width: 8),
                              if (i + 1 < types.length)
                                Expanded(child: tile(types[i + 1]))
                              else
                                const Expanded(child: SizedBox.shrink()),
                            ]),
                          ),
                      ],
                    );
                  }),
                  const SizedBox(height: 16),
                  Text(provider.t('file.name'),
                      style: const TextStyle(
                          color: Colors.white70,
                          fontSize: 12,
                          fontWeight: FontWeight.w600)),
                  const SizedBox(height: 6),
                  TextField(
                    controller: nameCtrl,
                    autofocus: true,
                    style: const TextStyle(color: Colors.white, fontSize: 14),
                    decoration: InputDecoration(
                      filled: true,
                      fillColor: const Color(0xFF1A1A24),
                      hintText: provider.t('file.nameHint'),
                      hintStyle: const TextStyle(color: Colors.white30),
                      suffixText: '.$selectedType',
                      suffixStyle: const TextStyle(
                          color: Color(0xFF4FC3F7),
                          fontWeight: FontWeight.w600),
                      contentPadding: const EdgeInsets.symmetric(
                          horizontal: 12, vertical: 10),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(6),
                      ),
                      enabledBorder: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(6),
                        borderSide: const BorderSide(color: Colors.white24),
                      ),
                      focusedBorder: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(6),
                        borderSide: const BorderSide(
                            color: Color(0xFF4FC3F7), width: 2),
                      ),
                    ),
                    onChanged: (_) => setS(() {}),
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dctx).pop(),
                child: Text(provider.t('btn.cancel'),
                    style: const TextStyle(color: Colors.white54)),
              ),
              FilledButton.icon(
                onPressed: nameCtrl.text.trim().isEmpty
                    ? null
                    : () => Navigator.of(dctx).pop({
                          'type': selectedType,
                          'name': nameCtrl.text.trim(),
                        }),
                icon: const Icon(Icons.check_rounded, size: 16),
                label: Text(provider.t('btn.create')),
                style: FilledButton.styleFrom(
                  backgroundColor: const Color(0xFF4FC3F7),
                  foregroundColor: Colors.black,
                ),
              ),
            ],
          );
        });
      },
    );
    nameCtrl.dispose();
    return result;
  }

  /// 実際にファイルを生成して、 押されたノード自身に添付する (= ファイル化)。
  Future<void> _createAndAttachFile(MindMapProvider provider, String nodeId,
      String type, String baseName) async {
    try {
      // ── ファイル名の正規化 + 衝突回避 ──
      final safeBase = baseName
          .replaceAll(RegExp(r'[\\/:*?"<>|]'), '_')
          .replaceAll('.', '_');
      final appDir = await getApplicationDocumentsDirectory();
      final attachDir = Directory('${appDir.path}/attachments');
      if (!await attachDir.exists()) {
        await attachDir.create(recursive: true);
      }
      String fileName = '$safeBase.$type';
      String destPath = '${attachDir.path}/$fileName';
      // 同名ファイルがあれば番号付与
      int counter = 1;
      while (await File(destPath).exists()) {
        fileName = '${safeBase}_$counter.$type';
        destPath = '${attachDir.path}/$fileName';
        counter++;
      }
      // ── 形式別にテンプレートを書き出し ──
      final bytes = _OfficeFileTemplate.buildEmpty(type);
      await File(destPath).writeAsBytes(bytes, flush: true);
      // ── HTML は同じ名前の CSS も置く (= ユーザー要望: css は html と
      //    一緒に使うので「HTML & CSS」 として作る)。 html 側から
      //    <link> で読んでいるので、 css を編集すれば見た目が変わる。 ──
      if (type == 'html') {
        try {
          final cssName =
              '${fileName.substring(0, fileName.lastIndexOf('.'))}.css';
          final cssPath = '${attachDir.path}/$cssName';
          // html 側の <link> を実際の css 名に直す。
          final htmlFile = File(destPath);
          final htmlText = await htmlFile.readAsString();
          await htmlFile.writeAsString(
              htmlText.replaceFirst('href="style.css"',
                  'href="${Uri.encodeComponent(cssName)}"'),
              flush: true);
          if (!await File(cssPath).exists()) {
            await File(cssPath).writeAsString(
                '/* $cssName — このファイルで見た目を整えます */\n'
                'body {\n'
                '  font-family: sans-serif;\n'
                '  margin: 24px;\n'
                '  line-height: 1.7;\n'
                '}\n'
                'h1 {\n'
                '  color: #2b579a;\n'
                '}\n',
                flush: true);
          }
        } catch (_) {}
      }

      // ── 子ノードは作らず、 押されたノード自身をファイル化する ──
      //   (= ユーザー要望: 「子要素でなく、 そのノードがファイル化するように」)。
      //   タイトルを生成ファイル名に、 attachment を生成ファイルにする。
      provider.updateNodeTitle(nodeId, fileName);
      provider.updateNodeAttachment(nodeId, destPath, fileName);

      if (mounted) {
        _appSnack(context, SnackBar(
          backgroundColor: const Color(0xFF1A1A2E),
          content: Row(children: [
            const Icon(Icons.check_circle_rounded,
                color: Color(0xFF4FC3F7), size: 18),
            const SizedBox(width: 8),
            Expanded(
              child: Text(
                  provider.t('file.created').replaceFirst('{name}', fileName),
                  style: const TextStyle(color: Colors.white)),
            ),
          ]),
          duration: const Duration(seconds: 3),
        ));
      }
    } catch (e, st) {
      debugPrint('ファイル作成エラー: $e\n$st');
      if (mounted) {
        _appSnack(context, SnackBar(
          backgroundColor: Colors.redAccent,
          content:
              Text(provider.t('file.createFailed').replaceFirst('{err}', '$e')),
        ));
      }
    }
  }

  /// メニュー項目を2列に分割して表示
  Widget _buildTwoColMenu(List<Widget> items) {
    // Divider以外の実項目を抽出。先頭のセクションは先頭に残し、
    // 通常アクションだけを2列化する。
    final actionItems = <Widget>[];
    final leadingFullWidthItems = <Widget>[];
    final trailingFullWidthItems =
        <Widget>[]; // Divider, Padding(カラー行), _CtxFontSizeRow等
    var seenAction = false;
    for (final w in items) {
      final isFullWidth = w is Divider ||
          w is _CtxFontSizeRow ||
          w is _CtxButtonSection ||
          (w is Padding && w.child is Row);
      if (isFullWidth) {
        if (seenAction) {
          trailingFullWidthItems.add(w);
        } else {
          leadingFullWidthItems.add(w);
        }
      } else {
        seenAction = true;
        actionItems.add(w);
      }
    }
    // 半分に分割
    final mid = (actionItems.length / 2).ceil();
    final leftCol = actionItems.sublist(0, mid);
    final rightCol = actionItems.sublist(mid);
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        ...leadingFullWidthItems,
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Expanded(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: leftCol,
              ),
            ),
            Container(width: 1, color: Colors.white10, height: mid * 46.0),
            Expanded(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: rightCol,
              ),
            ),
          ],
        ),
        ...trailingFullWidthItems,
      ],
    );
  }

  void _showConnectionDeleteOverlay(
      NodeConnection conn, Offset globalPos, MindMapProvider provider,
      {bool forceMulti = false}) {
    _removeOverlay();
    final allSelected = List.of(_selectedConnections);
    final targets = allSelected.isEmpty ? <NodeConnection>[conn] : allSelected;
    final displayCount = targets.length;
    _overlayEntry = OverlayEntry(
      builder: (_) => _ConnectionActionOverlay(
        screenPos: globalPos,
        connection: conn,
        selectedCount: displayCount,
        onClose: () {
          _removeOverlay();
        },
        onDelete: () {
          _resetInteractionState();
          for (final c in targets) {
            provider.disconnectNodes(c.fromId, c.toId);
          }
          _selectedConnections.clear();
        },
        onStrokeWidthChanged: (w) {
          provider.updateConnections(targets, strokeWidth: w);
        },
        onShowArrowChanged: (v) {
          provider.updateConnections(targets, showArrow: v);
        },
        onArrowHeadScaleChanged: (s) {
          provider.updateConnections(targets, arrowHeadScale: s);
        },
        onLineStyleChanged: (style) {
          if (style != 'elbow' && _selectedConnectionBends.isNotEmpty) {
            setState(
                () => _clearConnectionBendDragFields(clearSelection: true));
          }
          provider.updateConnections(targets, lineStyle: style);
        },
        onElbowSplitRatioChanged: (ratio) {
          if (_selectedConnectionBends.isNotEmpty) {
            setState(
                () => _clearConnectionBendDragFields(clearSelection: true));
          }
          provider.updateConnections(targets,
              elbowSplitRatio: ratio, clearElbowBendPoints: true);
        },
        onElbowPointCountChanged: (count) {
          if (_selectedConnectionBends.isNotEmpty) {
            setState(
                () => _clearConnectionBendDragFields(clearSelection: true));
          }
          provider.updateConnections(targets,
              elbowPointCount: count, clearElbowBendPoints: true);
        },
        onClearElbowBendPoints: () {
          if (_selectedConnectionBends.isNotEmpty) {
            setState(
                () => _clearConnectionBendDragFields(clearSelection: true));
          }
          provider.updateConnections(targets, clearElbowBendPoints: true);
        },
        onSaveDefaults: (snapshot) {
          provider.saveConnectionDefaultsFrom(snapshot);
          // 保存できたことを知らせる (= ユーザー報告: 押しても何も出ない)。
          _appSnack(
            context,
            SnackBar(
              content: Text(provider.t('conn.defaultsSaved'),
                  style: const TextStyle(fontSize: 12)),
              backgroundColor: const Color(0xFF43B97F),
              duration: const Duration(seconds: 2),
            ),
          );
        },
        onBidirectionalChanged: (v) {
          provider.updateConnections(targets, bidirectional: v);
        },
        onLabelChanged: (text) {
          if (text.isEmpty) {
            // 空文字なら明示的にラベルを削除
            provider.updateConnections(targets, clearLabel: true);
          } else {
            provider.updateConnections(targets, label: text);
          }
        },
        onLabelPositionChanged: (position) {
          provider.updateConnections(targets, labelPosition: position);
        },
        onLineColorChanged: (value) {
          provider.updateConnections(targets, lineColorValue: value);
        },
        onRelationshipTypeChanged: (type) {
          provider.updateConnections(targets, relationshipType: type);
        },
        onReverse: () {
          _resetInteractionState();
          for (final c in targets) {
            provider.reverseConnection(c.fromId, c.toId);
          }
        },
      ),
    );
    Overlay.of(context, rootOverlay: true).insert(_overlayEntry!);
  }

  // ─── インラインタイトル編集 ───────────────────────────────────────────

  void _startInlineTitleEdit(BuildContext ctx, MindMapNode node,
      {bool deleteWhenEmpty = false, bool allowDelimiterExpansion = false}) {
    _removeOverlay();
    final provider = ctx.read<MindMapProvider>();
    // ギャラリーでは通常ノード用のインラインエディターを描画しないため、
    // memo だけでなく画像・PDF・動画・リンク等も専用エディターで編集する。
    // ここを F2 / 編集ボタン / ダブルクリック共通の振り分け地点にする。
    final isShelfElement = provider.currentPage.pageType == 'bookshelf' &&
        provider.shelfCellOf(node.id) != null;
    if (isShelfElement) {
      _beginShelfInlineTextEdit(provider, node.id,
          deleteWhenEmpty: deleteWhenEmpty);
      return;
    }
    _beginNodeInlineTextEdit(provider, node.id,
        deleteWhenEmpty: deleteWhenEmpty,
        allowDelimiterExpansion: allowDelimiterExpansion);
  }

  // ─── AIダイアログ ──────────────────────────────────────────────────────────

  /// ノードのAIボタン: API キーを叩かず、 ノードタイトルの用語をブラウザの
  /// 現在のブラウザAIターゲットのチャット画面 (クエリ無しのベース URL)。
  /// 統合 AI ボタン (openAi) とギャラリーヘッダーの AI ボタンが共有する。
  Future<void> _showPlainNodeTextInput(BuildContext ctx, String nodeId,
      {bool allowDelimiterExpansion = false}) async {
    final provider = ctx.read<MindMapProvider>();
    final node = provider.nodes[nodeId];
    if (node == null) return;
    final initial = [node.title, node.memoText ?? '']
        .where((s) => s.trim().isNotEmpty)
        .join('\n');
    final ctrl = TextEditingController(text: initial);

    void save(BuildContext dctx) {
      final normalized =
          ctrl.text.replaceAll('\r\n', '\n').replaceAll('\r', '\n');
      final raw = normalized.trim();
      if (allowDelimiterExpansion && raw.isNotEmpty) {
        final parts = _splitNodeBatchParts(provider, raw);
        if (parts.length > 1) {
          _expandDelimitedNodeText(provider, nodeId, parts);
          Navigator.pop(dctx);
          return;
        }
      }
      final lines = normalized.split('\n');
      final title = lines.isNotEmpty ? lines.first.trim() : '';
      final memo = lines.length > 1 ? lines.skip(1).join('\n').trim() : '';
      provider.updateNodeRichText(
        nodeId,
        richText: '',
        title: title,
        memo: memo,
      );
      provider.resolveNodeOverlaps(nodeId);
      if (title.isNotEmpty) _offerBulkAutofillSuggestions(nodeId);
      Navigator.pop(dctx);
    }

    await showDialog<void>(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('inlineEdit.header'),
            style: const TextStyle(color: Colors.white)),
        content: SizedBox(
          width: 520,
          child: TextField(
            controller: ctrl,
            autofocus: true,
            minLines: 5,
            maxLines: 10,
            keyboardType: TextInputType.multiline,
            textInputAction: TextInputAction.newline,
            style: const TextStyle(color: Colors.white, fontSize: 16),
            decoration: InputDecoration(
              hintText: provider.t('node.enterHint'),
              hintStyle: const TextStyle(color: Colors.white38),
              filled: true,
              fillColor: const Color(0xFF10101B),
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(8),
                borderSide: BorderSide.none,
              ),
            ),
            onSubmitted: (_) {},
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            onPressed: () => save(dctx),
            style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFF4FC3F7),
              foregroundColor: const Color(0xFF101426),
            ),
            child: Text(provider.t('btn.save')),
          ),
        ],
      ),
    );
    ctrl.dispose();
  }

  String _browserAiBaseUrl(MindMapProvider provider) {
    switch (provider.browserAiTarget) {
      case 'gemini':
        return 'https://gemini.google.com/app';
      case 'perplexity':
        return 'https://www.perplexity.ai/';
      case 'claude':
        return 'https://claude.ai/';
      case 'grok':
        return 'https://grok.com/';
      case 'deepseek':
        return 'https://chat.deepseek.com/';
      case 'google':
        return 'https://www.google.com/';
      case 'chatgpt':
      default:
        return 'https://chatgpt.com/';
    }
  }

  /// 現在選択中のブラウザAI をアプリ内分割パネルで開く (= 統合 AI ボタン /
  /// ギャラリーヘッダーの AI ボタン用)。 同じものが開いていれば再押下で
  /// 閉じる (トグル)。 API キーは使わず、 ブラウザ (WebView) で開くだけ。
  void _openBrowserAiPanel() {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    _toggleUrlInSplitPanel(_browserAiBaseUrl(provider));
  }

  /// 統合 AI ボタンの右クリック / 長押しで出す「AI 切替」メニュー
  /// (= ユーザー要望: ノードの AI ボタンの様に 1 つにまとめ、 右クリック/
  /// 長押しでモデルを切り替える)。 選んだ AI を即座に分割パネルで開く。
  void _showBrowserAiSwitchMenu({Offset? at}) {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    // 押したボタンの近くに出す (= ユーザー要望)。 位置が分からない時だけ中央。
    final anchor = _customButtonAnchor(at);
    showDialog<void>(
      context: context,
      barrierColor: Colors.black.withValues(alpha: anchor == null ? 0.54 : 0.25),
      builder: (dctx) => _positionNearAnchor(
        dctx,
        anchor,
        Material(
          color: Colors.transparent,
          child: Container(
            width: 300,
            padding: const EdgeInsets.fromLTRB(18, 16, 18, 18),
            decoration: BoxDecoration(
