  /// ブラウザ AI に渡す「前提条件」 の編集ダイアログ (= ユーザー要望)。
  Future<void> _showBrowserAiPrefixDialog() async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final ctrl = TextEditingController(text: provider.browserAiPrefix);
    // 呼び元 (AI 切替メニュー) と同じくボタンの近くに出す (= ユーザー要望)。
    final anchor = _customButtonAnchor();
    final saved = await showDialog<String>(
      context: context,
      barrierColor: Colors.black.withValues(alpha: anchor == null ? 0.54 : 0.25),
      builder: (dctx) => _positionNearAnchor(
        dctx,
        anchor,
        AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        insetPadding: anchor == null
            ? const EdgeInsets.symmetric(horizontal: 40, vertical: 24)
            : EdgeInsets.zero,
        title: Text(provider.t('ai.prefixTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: SizedBox(
          width: 360,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Align(
              alignment: Alignment.centerLeft,
              child: Text(provider.t('ai.prefixDesc'),
                  style: const TextStyle(color: Colors.white54, fontSize: 12)),
            ),
            const SizedBox(height: 10),
            TextField(
              controller: ctrl,
              autofocus: true,
              minLines: 2,
              maxLines: 5,
              style: const TextStyle(color: Colors.white, fontSize: 13),
              decoration: InputDecoration(
                hintText: provider.t('ai.prefixHint'),
                hintStyle: const TextStyle(color: Colors.white24, fontSize: 12),
                filled: true,
                fillColor: Colors.white.withValues(alpha: 0.06),
                border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(8),
                    borderSide: BorderSide.none),
              ),
            ),
          ]),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, '__cancel__'),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          TextButton(
            onPressed: () => Navigator.pop(dctx, ''),
            child: Text(provider.t('btn.clear'),
                style: const TextStyle(color: Color(0xFFFF8A80))),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFBA68C8),
                foregroundColor: Colors.white),
            onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
            child: Text(provider.t('btn.save')),
          ),
        ],
        ),
        const Size(420, 320),
      ),
    );
    ctrl.dispose();
    if (saved == null || saved == '__cancel__') return;
    await provider.setBrowserAiPrefix(saved);
    if (mounted) {
      _appSnack(
          context,
          SnackBar(
              content: Text(saved.isEmpty ? '前提条件をクリアしました' : '前提条件を保存しました'),
              backgroundColor: const Color(0xFFBA68C8),
              duration: const Duration(seconds: 2)));
    }
  }

  Widget _browserAiSwitchChip(
      MindMapProvider provider, BuildContext dctx, Map<String, String> t) {
    final selected = t['id'] == provider.browserAiTarget;
    return GestureDetector(
      onTap: () async {
        Navigator.pop(dctx);
        await provider.setBrowserAiTarget(t['id']!);
        _openBrowserAiPanel();
      },
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 9),
        decoration: BoxDecoration(
          color: selected
              ? const Color(0xFFBA68C8).withValues(alpha: 0.28)
              : Colors.white10,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
              color: selected ? const Color(0xFFBA68C8) : Colors.white24),
        ),
        child: Text(t['label'] ?? t['id']!,
            style: TextStyle(
                color: selected ? Colors.white : Colors.white70,
                fontSize: 13,
                fontWeight: selected ? FontWeight.w700 : FontWeight.w500)),
      ),
    );
  }

  /// AI (ChatGPT / Gemini / Perplexity 等) にクエリとして渡し、 アプリ内の
  /// 分割パネルで開く。 どの AI を使うかは AIボタンの右クリック / 長押しで
  /// 切り替える (provider.browserAiTarget)。 プレフィル非対応サイトでも使える
  /// ように、 用語をクリップボードにもコピーしておく。
  /// ノードを検索/ブラウザに渡すときの「実テキスト」 を返す。 通常ノードは
  /// title を優先して既存挙動を維持し、 title が空のギャラリーのテキストノートは
  /// memoText、 それも空なら richText のプレーンテキストを使う (= ユーザー要望:
  /// ギャラリーで入力したテキストが YouTube/Google 検索に渡らない不具合の修正)。
  String _nodeEffectiveText(MindMapNode n) {
    final title = n.title.trim();
    if (title.isNotEmpty) return title;
    final memo = (n.memoText ?? '').trim();
    if (memo.isNotEmpty) return memo;
    final rt = n.richText;
    if (rt != null && rt.trim().isNotEmpty) {
      return MindMapNode.richDeltaToPlainText(rt).trim();
    }
    return '';
  }

  /// ノードのローカル添付 (Web URL でない実ファイルパス) を返す。 無ければ null。
  /// (= 画像/ファイルノードの AI 送信判定に使う。 サムネではなく本体添付を見る)
  String? _localMediaPathOfNode(MindMapNode n) {
    final ap = (n.attachmentPath ?? '').trim();
    if (ap.isEmpty) return null;
    if (ap.startsWith('http://') || ap.startsWith('https://')) return null;
    final uri = Uri.tryParse(ap);
    if (uri?.scheme.toLowerCase() == 'file') {
      try {
        return uri!.toFilePath();
      } catch (_) {
        return null;
      }
    }
    return ap;
  }

  /// AI に画像として渡せる拡張子か。
  bool _isAiImageExt(String ext) => const {
        'jpg',
        'jpeg',
        'png',
        'gif',
        'webp',
        'heic',
        'heif',
        'bmp',
      }.contains(ext);

  /// ローカルでそのまま UTF-8 テキストとして読める添付拡張子か。
  bool _isTextLikeAttachmentExt(String ext) => const {
        'txt',
        'md',
        'markdown',
        'csv',
        'tsv',
        'json',
        'log',
        'dart',
        'py',
        'js',
        'ts',
        'java',
        'kt',
        'cpp',
        'c',
        'h',
        'hpp',
        'cs',
        'go',
        'rb',
        'rs',
        'swift',
        'sh',
        'yml',
        'yaml',
        'xml',
        'html',
        'htm',
        'css',
      }.contains(ext);

  /// ノードに添付されたファイルからローカルで本文テキストを抽出する
  /// (= ユーザー要望: API キーが無くても、 貼りついたファイルの中身をブラウザ版
  /// AI に渡せるように)。 抽出できない/未対応の形式は null を返す。
  Future<String?> _extractAttachmentTextForAi(String path, String ext) async {
    const int kMaxChars = 12000;
    String clip(String s) => s.length > kMaxChars
        ? '${s.substring(0, kMaxChars)}\n... [truncated]'
        : s;
    try {
      final file = File(path);
      if (!await file.exists()) return null;
      // ── プレーンテキスト系 ──
      if (_isTextLikeAttachmentExt(ext)) {
        String text;
        try {
          text = await file.readAsString();
        } catch (_) {
          // UTF-8 で読めない (Shift-JIS 等) → バイト列から復元。
          text = String.fromCharCodes(await file.readAsBytes());
        }
        return clip(text.trim());
      }
      final bytes = await file.readAsBytes();
      // ── PDF ──
      if (ext == 'pdf') {
        final doc = sfpdf.PdfDocument(inputBytes: bytes);
        try {
          return clip(sfpdf.PdfTextExtractor(doc).extractText().trim());
        } finally {
          doc.dispose();
        }
      }
      // ── docx (Word) ──
      if (ext == 'docx') {
        return clip(_extractOoxmlText(bytes, 'word/document.xml'));
      }
      // ── pptx (PowerPoint): 全スライドのテキストを結合 ──
      if (ext == 'pptx') {
        final archive = ZipDecoder().decodeBytes(bytes);
        final slides = archive.files
            .where((f) =>
                f.isFile &&
                RegExp(r'ppt/slides/slide\d+\.xml$').hasMatch(f.name))
            .toList()
          ..sort((a, b) => a.name.compareTo(b.name));
        final buf = StringBuffer();
        for (final f in slides) {
          buf.writeln(_stripXmlTags(
              utf8.decode(f.content as List<int>, allowMalformed: true)));
        }
        return clip(buf.toString().trim());
      }
      // ── xlsx (Excel): 各シートのセルをタブ区切りで結合 ──
      if (ext == 'xlsx') {
        final excel = xls.Excel.decodeBytes(bytes);
        final buf = StringBuffer();
        for (final entry in excel.tables.entries) {
          buf.writeln('[${entry.key}]');
          for (final row in entry.value.rows) {
            final cells = row.map((c) => _xlsxCellToPlain(c?.value)).toList();
            if (cells.any((c) => c.trim().isNotEmpty)) {
              buf.writeln(cells.join('\t'));
            }
          }
        }
        return clip(buf.toString().trim());
      }
    } catch (e) {
      debugPrint('添付テキスト抽出失敗: $e');
    }
    return null;
  }

  /// xlsx セル値をプレーン文字列へ変換する (AI 添付抽出用の簡易版)。
  String _xlsxCellToPlain(xls.CellValue? v) {
    if (v == null) return '';
    if (v is xls.TextCellValue) {
      // excel 4.x の TextCellValue.value は独自 TextSpan 型 → dynamic で走査。
      final buf = StringBuffer();
      void walk(dynamic span) {
        if (span == null) return;
        try {
          final t = span.text;
          if (t is String) buf.write(t);
        } catch (_) {}
        try {
          final children = span.children;
          if (children is Iterable) {
            for (final c in children) {
              walk(c);
            }
          }
        } catch (_) {}
      }

      walk(v.value);
      final r = buf.toString();
      return r.isEmpty ? v.value.toString() : r;
    }
    if (v is xls.IntCellValue) return v.value.toString();
    if (v is xls.DoubleCellValue) {
      final d = v.value;
      return d == d.truncateToDouble() ? d.toInt().toString() : d.toString();
    }
    if (v is xls.BoolCellValue) return v.value ? 'TRUE' : 'FALSE';
    if (v is xls.DateCellValue) {
      return '${v.year.toString().padLeft(4, '0')}-'
          '${v.month.toString().padLeft(2, '0')}-'
          '${v.day.toString().padLeft(2, '0')}';
    }
    if (v is xls.DateTimeCellValue) {
      return '${v.year.toString().padLeft(4, '0')}-'
          '${v.month.toString().padLeft(2, '0')}-'
          '${v.day.toString().padLeft(2, '0')} '
          '${v.hour.toString().padLeft(2, '0')}:'
          '${v.minute.toString().padLeft(2, '0')}';
    }
    if (v is xls.TimeCellValue) {
      return '${v.hour.toString().padLeft(2, '0')}:'
          '${v.minute.toString().padLeft(2, '0')}';
    }
    if (v is xls.FormulaCellValue) return '=${v.formula}';
    return v.toString();
  }

  /// OOXML (docx) の指定 XML パートを取り出してプレーンテキスト化する。
  String _extractOoxmlText(List<int> bytes, String partPath) {
    try {
      final archive = ZipDecoder().decodeBytes(bytes);
      for (final f in archive.files) {
        if (f.isFile && f.name == partPath) {
          return _stripXmlTags(
              utf8.decode(f.content as List<int>, allowMalformed: true));
        }
      }
    } catch (_) {}
    return '';
  }

  /// XML タグを除去して段落/改行を保ったプレーンテキストにする (docx/pptx 用)。
  String _stripXmlTags(String xml) {
    var s = xml;
    // 段落・改行・タブを明示的な区切りへ。
    s = s.replaceAll(RegExp(r'</w:p>|</a:p>'), '\n');
    s = s.replaceAll(RegExp(r'<w:br\s*/?>|<a:br\s*/?>'), '\n');
    s = s.replaceAll(RegExp(r'<w:tab\s*/?>|<a:tab\s*/?>'), '\t');
    // 残りのタグを除去。
    s = s.replaceAll(RegExp(r'<[^>]+>'), '');
    // XML エンティティを復元。
    s = s
        .replaceAll('&amp;', '&')
        .replaceAll('&lt;', '<')
        .replaceAll('&gt;', '>')
        .replaceAll('&quot;', '"')
        .replaceAll('&apos;', "'");
    // 連続する空行を圧縮。
    s = s.replaceAll(RegExp(r'\n{3,}'), '\n\n');
    return s.trim();
  }

  /// ローカル画像をシステムのクリップボードへ書き込む (= ユーザー要望: API キーが
  /// 無い時はブラウザ版 AI に貼り付けられるよう画像をコピーする)。 成功で true。
  Future<bool> _copyImageFileToClipboard(String path) async {
    try {
      final clipboard = SystemClipboard.instance;
      if (clipboard == null) return false; // 非対応プラットフォーム
      final bytes = await File(path).readAsBytes();
      final dot = path.lastIndexOf('.');
      final ext = dot >= 0 ? path.substring(dot + 1).toLowerCase() : '';
      final item = DataWriterItem();
      switch (ext) {
        case 'png':
          item.add(Formats.png(bytes));
          break;
        case 'jpg':
        case 'jpeg':
          item.add(Formats.jpeg(bytes));
          break;
        case 'gif':
          item.add(Formats.gif(bytes));
          break;
        case 'webp':
          item.add(Formats.webp(bytes));
          break;
        case 'bmp':
          item.add(Formats.bmp(bytes));
          break;
        default:
          // heic/heif 等はクリップボード画像として貼り付けられないので非対応。
          return false;
      }
      await clipboard.write([item]);
      return true;
    } catch (e) {
      debugPrint('画像クリップボードコピー失敗: $e');
      return false;
    }
  }

  Future<int> _copyImageFilesToClipboard(
    Iterable<String> paths, {
    String? fallbackText,
  }) async {
    try {
      final clipboard = SystemClipboard.instance;
      if (clipboard == null) return 0;
      final seen = <String>{};
      final validPaths = <String>[];
      for (final rawPath in paths) {
        final file = File(rawPath).absolute;
        final path = file.path;
        if (!seen.add(path) || !await file.exists()) continue;
        final dot = path.lastIndexOf('.');
        final ext = dot >= 0 ? path.substring(dot + 1).toLowerCase() : '';
        if (!_isAiImageExt(ext)) continue;
        validPaths.add(path);
      }
      if (validPaths.isEmpty) return 0;

      // Windowsでは標準画像表現が先頭providerから採用されるため、PNG/JPEG
      // 等を先頭へ置く。各画像は別DataWriterItemのまま保持し、結合しない。
      const bitmapExts = <String>{'png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp'};
      validPaths.sort((a, b) {
        String extOf(String value) {
          final dot = value.lastIndexOf('.');
          return dot >= 0 ? value.substring(dot + 1).toLowerCase() : '';
        }

        final aBitmap = bitmapExts.contains(extOf(a));
        final bBitmap = bitmapExts.contains(extOf(b));
        if (aBitmap == bBitmap) return 0;
        return aBitmap ? -1 : 1;
      });

      final items = <DataWriterItem>[];
      for (final path in validPaths) {
        final file = File(path);
        final dot = path.lastIndexOf('.');
        final ext = dot >= 0 ? path.substring(dot + 1).toLowerCase() : '';
        final item = DataWriterItem(
          suggestedName: path.split(RegExp(r'[/\\]')).last,
        );
        // 受け側が画像貼り付けを扱える場合の表現。全画像に個別に付ける。
        if (bitmapExts.contains(ext)) {
          final bytes = await file.readAsBytes();
          switch (ext) {
            case 'png':
              item.add(Formats.png(bytes));
              break;
            case 'jpg':
            case 'jpeg':
              item.add(Formats.jpeg(bytes));
              break;
            case 'gif':
              item.add(Formats.gif(bytes));
              break;
            case 'webp':
              item.add(Formats.webp(bytes));
              break;
            case 'bmp':
              item.add(Formats.bmp(bytes));
              break;
          }
        }
        // 複数ファイルとして扱うAIサイト向けの表現。
        item.add(Formats.fileUri(Uri.file(path)));
        if (items.isEmpty &&
            fallbackText != null &&
            fallbackText.trim().isNotEmpty) {
          item.add(Formats.plainText(fallbackText));
        }
        items.add(item);
      }
      await clipboard.write(items);
      return items.length;
    } catch (e) {
      debugPrint('複数画像クリップボードコピー失敗: $e');
      return 0;
    }
  }

  Future<void> _openBrowserAiForNode(String nodeId) async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final node = provider.nodes[nodeId];
    if (node == null) return;
    // ── ノードの本文全体を AI に渡す (= ユーザー要望: リッチテキストで編集した
    //   要素も、 AI ボタンを押すとブラウザ版 AI にその内容を渡せるように) ──
    //   richText があればその全文 (タイトル+メモ統合)、 無ければ タイトル+メモ。
    String content;
    final rt = node.richText;
    if (rt != null && rt.trim().isNotEmpty) {
      content = MindMapNode.richDeltaToPlainText(rt).trim();
    } else {
      final memo = (node.memoText ?? '').trim();
      final title = node.title.trim();
      content = memo.isEmpty ? title : '$title\n$memo';
    }
    // ── ローカル添付 (画像/PDF/docx/pptx) を AI に渡す (= ユーザー要望: 画像/
    //    ファイルノードは文字が空でも中身を AI に渡す。 両対応: API キーがあれば
    //    Gemini 等で画像/ファイルを直接解析、 無ければ画像をクリップボードへ
    //    コピーしてブラウザ版 AI に貼り付けられるようにする) ──
    final mediaPath = _localMediaPathOfNode(node);
    if (mediaPath != null) {
      final dot = mediaPath.lastIndexOf('.');
      final ext = dot >= 0 ? mediaPath.substring(dot + 1).toLowerCase() : '';
      final bool isImage = _isAiImageExt(ext);
      // API がバイナリのまま受け取れる形式 (Gemini/Claude ネイティブ対応)。
      final bool isApiDoc = const {'pdf', 'docx', 'pptx'}.contains(ext);
      // ローカルで本文テキストを抽出できる形式 (= キーが無くてもブラウザ AI に
      //   中身を渡せる)。
      final bool isTextExtractable =
          isApiDoc || _isTextLikeAttachmentExt(ext) || ext == 'xlsx';
      if (isImage || isTextExtractable) {
        // ── 既定はブラウザ版 AI に送る (= ユーザー要望: 明示的に API キーを使う
        //    ボタンを押さない限り基本的にブラウザ版へ)。 API キーで添付そのものを
        //    直接解析させたい時は、 AI ボタンを右クリック/長押し →「AI に質問して
        //    回答を取得」 (API) を使う。 ──
        // (1) 画像 → 元画像をFileとしてブラウザAIへ自動添付する。
        // クリップボードにも個別画像のまま残し、サイト側DOM変更時の保険にする。
        if (isImage) {
          final imagePayloads =
              await compute(_readAiImagePayloads, <String>[mediaPath]);
          if (!mounted) return;
          _sendQueryToBrowserAi(
            content.isEmpty ? '貼り付けた画像について教えてください。' : content,
            copyTextToClipboard: false,
            imagePayloads: imagePayloads,
          );
          _copyImageFileToClipboard(mediaPath).then((copied) {
            if (!mounted) return;
            _appSnack(
              context,
              SnackBar(
                content: Text(copied
                    ? '画像を個別ファイルのまま AI へ添付しています。'
                        '反映されない場合は入力欄へ貼り付けてください。'
                    : '画像をコピーできませんでした。AI ボタン右クリックの「AI に質問して回答を取得」で API に直接渡せます。'),
                backgroundColor:
                    copied ? const Color(0xFF43B97F) : const Color(0xFFE57373),
                duration: const Duration(seconds: 4),
              ),
            );
          });
          return;
        }
        // (2) ドキュメント/テキスト → ローカルで本文を抽出してブラウザ AI に同梱
        //     (= ユーザー要望: ノードに貼りついたファイルも AI に渡す。 ただし
        //     既定はブラウザ版)。
        final extracted = await _extractAttachmentTextForAi(mediaPath, ext);
        if (!mounted) return;
        final name =
            node.attachmentName ?? mediaPath.split(RegExp(r'[/\\]')).last;
        if (extracted != null && extracted.trim().isNotEmpty) {
          final combined = content.isEmpty
              ? '【添付ファイル「$name」の内容】\n$extracted'
              : '$content\n\n【添付ファイル「$name」の内容】\n$extracted';
          _sendQueryToBrowserAi(combined);
          return;
        }
        // (3) 抽出できなかった場合 → 案内 + 本文のみブラウザへ送信。
        _appSnack(
          context,
          SnackBar(
            content: Text(content.isEmpty
                ? 'このファイルの内容を読み取れませんでした。AI ボタン右クリックの「AI に質問して回答を取得」で API に直接渡せます。'
                : 'ファイルの内容を読み取れませんでした。本文のみ AI に送ります。'),
            backgroundColor: const Color(0xFFE57373),
            duration: const Duration(seconds: 3),
          ),
        );
        if (content.isNotEmpty) _sendQueryToBrowserAi(content);
        return;
      }
    }
    // ── 埋め込み URL を AI に渡す (= ユーザー要望: YouTube・画像・ホームページ
    //   の URL を埋め込んだノードは AI ボタンでその URL も渡す。 ただしローカル
    //   ファイル (file:// やローカルパス) は Web 版 AI から参照できないので渡さない) ──
    bool isWebUrl(String u) =>
        u.startsWith('http://') || u.startsWith('https://');
    final yt = (node.youtubeUrl ?? '').trim();
    final link = (node.linkUrl ?? '').trim();
    // 画像/動画の添付 (= ユーザー要望: 画像や YouTube を選択して AI ボタンを
    //   押したら、 その画像・動画のリンクも AI に送られるように)。 Web URL の
    //   添付 (例: Google 検索や YouTube サムネ由来の画像) のみ対象。
    final att = (node.attachmentPath ?? '').trim();
    for (final u in [yt, link, att]) {
      if (isWebUrl(u) && !content.contains(u)) {
        content = content.isEmpty ? u : '$content\n$u';
      }
    }
    if (content.isEmpty) {
      _appSnack(
        context,
        SnackBar(
          content: Text(provider.t('ai.nodeEmpty')),
          backgroundColor: Color(0xFFE53935),
          duration: Duration(seconds: 2),
        ),
      );
      return;
    }
    _sendQueryToBrowserAi(content);
  }

  /// 任意のテキスト [content] をブラウザ版 AI のチャット欄へ送る (= ノードの AI
  /// ボタン / 範囲選択の一括 AI で共用)。 前提条件を先頭に付け、 開いている AI
  /// パネルへ inject、 無ければ設定中の AI を右パネルに開いて inject する。
  void _sendQueryToBrowserAi(
    String content, {
    bool copyTextToClipboard = true,
    List<Map<String, String>> imagePayloads = const <Map<String, String>>[],
  }) {
    if (content.trim().isEmpty || !mounted) return;
    final provider = context.read<MindMapProvider>();
    // 前提条件 (= ユーザー要望: 「日本語で答えて」 等) を先頭に付ける。
    final query = provider.browserAiApplyPrefix(content);
    // 用語をクリップボードにもコピー (プレフィル非対応サイトの貼り付け用)。
    if (copyTextToClipboard) {
      unawaited(Clipboard.setData(ClipboardData(text: query)));
    }
    final url = provider.browserAiUrlForQuery(query);

    // ── モバイル: 要素/一括の AI は全画面で開く (= ユーザー要望: ロック画面
    //    から AI を立ち上げた時と同じく、 既定で全画面表示にする)。
    //    GoogleSearchDialog.show は不透明な全画面ルートなので、 背後の
    //    WebView プラットフォームビューにタッチを奪われる既知問題も無い。
    //    画像添付は分割パネル側の注入経路 (_injectImagesToSplitAi) が必要な
    //    ため、 従来どおり分割パネルで開く。 ──
    final bool isMobileAi =
        !kIsWeb && (Platform.isAndroid || Platform.isIOS);
    if (isMobileAi && imagePayloads.isEmpty) {
      _openFullscreenBrowserAiMobile(query, url);
      return;
    }

    void injectInto({required bool left, required bool reuse}) {
      final token = ++_splitAiInjectSeq;
      // = ユーザー要望: 「最初に AI ボタンを押した時は用語が入力されない」。
      //   新規にパネルを開く初回は WebView 生成 + AI ページのロード + (場合に
      //   よっては) ログイン処理に時間がかかり、 旧 5.5 秒では入力欄が
      //   まだ無く注入が空振りしていた。 注入は冪等 (成功後はトークンで
      //   dup 判定して二重入力しない) なので、 リトライ回数と最大待ち時間を
      //   伸ばして初回の取りこぼしを無くす。
      final delays = reuse
          ? const [150, 600, 1500, 3000, 6000, 10000, 16000, 24000, 36000]
          : const [
              1200, 2400, 3800, 5500, 7500, 9500, 12000, 15000, 20000,
              28000, 38000, 48000
            ];
      for (final ms in delays) {
        Future.delayed(Duration(milliseconds: ms), () {
          _injectTitleToSplitAi(query, token, left: left);
          if (imagePayloads.isNotEmpty) {
            _injectImagesToSplitAi(imagePayloads, token, left: left);
          }
        });
      }
    }

    final rightAiId = (_splitOpen && _splitMode == 'web')
        ? _panelAiId(provider, _splitCurrentUrl)
        : null;
    final leftAiId = (_splitLeftOpen && _splitLeftMode == 'web')
        ? _panelAiId(provider, _splitLeftCurrentUrl)
        : null;

    if (rightAiId != null && leftAiId != null) {
      final useLeft = _lastNodeAiSide != 'left';
      _lastNodeAiSide = useLeft ? 'left' : 'right';
      injectInto(left: useLeft, reuse: true);
      return;
    }
    if (rightAiId != null || leftAiId != null) {
      final useLeft = leftAiId != null;
      _lastNodeAiSide = useLeft ? 'left' : 'right';
      injectInto(left: useLeft, reuse: true);
      return;
    }
    _splitLoadUrl(url);
    _lastNodeAiSide = 'right';
    injectInto(left: false, reuse: false);
  }

  /// モバイル: ブラウザ版 AI を全画面ルートで開く (= ユーザー要望: 要素から
  /// AI を立ち上げた時、 ロック画面の AI と同じく既定で全画面になるように)。
  /// プロンプトは GoogleSearchDialog 側の initialAiPrompt 注入に任せる。
  /// メモ → ノード追加や「画面分割で開く」 も通常の検索ダイアログと同じく使える。
  void _openFullscreenBrowserAiMobile(String query, String url) {
    final provider = context.read<MindMapProvider>();
    void handleAddNode(String title, String memo, String? linkUrl) {
      if (!mounted) return;
      final pageId = provider.currentPage.id;
      final pCtrl = _ctrlFor(pageId);
      final s =
          View.of(context).physicalSize / View.of(context).devicePixelRatio;
      final mat = pCtrl.value;
      final scale = mat.getMaxScaleOnAxis();
      final tx = mat.getTranslation().x;
      final ty = mat.getTranslation().y;
      final pos = Offset(
          (s.width / 2 - tx) / scale - 80, (s.height / 2 - ty) / scale - 21);
      final newNode = provider.addNodeAtCenterReturning(pos);
      if (title.isNotEmpty) provider.updateNodeTitle(newNode.id, title);
      if (memo.isNotEmpty) provider.updateNodeMemo(newNode.id, memo);
      if (linkUrl != null && linkUrl.isNotEmpty) {
        provider.updateNodeLink(newNode.id, linkUrl);
      }
      _appSnack(
        context,
        SnackBar(
          content: Text(provider.t('googleSearch.nodeAdded')),
          backgroundColor: const Color(0xFF43B97F),
          duration: const Duration(seconds: 2),
        ),
      );
    }

    unawaited(GoogleSearchDialog.show(
      context,
      initialUrl: url,
      initialAiPrompt: query,
      customTitle: provider.browserAiTargetLabel,
      onAddNode: handleAddNode,
      onMoveToSplitPanel: (currentUrl, {bool isLeftPanel = false}) {
        // マップ分割中は分割セルへ埋め込む (= ユーザー要望)。
        if (_canEmbedIntoMapSplit()) {
          _embedUrlIntoSplitCell(currentUrl);
          return;
        }
        final isPdf = currentUrl.toLowerCase().endsWith('.pdf');
        if (isLeftPanel) {
          if (isPdf) {
            _splitLoadLeftPdf(currentUrl);
          } else {
            _splitLoadLeftUrl(currentUrl);
          }
        } else {
          setState(() => _setSplitOpen(true));
          _splitLoadUrl(currentUrl);
        }
      },
    ));
  }

  /// 範囲選択した複数要素の本文を、 要素ごとに改行で区切ってブラウザ版 AI へ
  /// まとめて送る (= ユーザー要望: AI 一括でそのままブラウザ AI に渡す)。
  Future<void> _sendBulkNodesToBrowserAi() async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final parts = <String>[];
    final localImages = <String>[];
    var imageNumber = 0;
    for (final id in _rangeSelectedIds) {
      final n = provider.nodes[id];
      if (n == null) continue;
      final rt = n.richText;
      String t;
      if (rt != null && rt.trim().isNotEmpty) {
        t = MindMapNode.richDeltaToPlainText(rt).trim();
      } else {
        final memo = (n.memoText ?? '').trim();
        final title = n.title.trim();
        t = memo.isEmpty ? title : '$title\n$memo';
      }

      final mediaPath = _localMediaPathOfNode(n);
      String? imageName;
      if (mediaPath != null) {
        final dot = mediaPath.lastIndexOf('.');
        final ext =
            dot >= 0 ? mediaPath.substring(dot + 1).toLowerCase() : '';
        if (_isAiImageExt(ext)) {
          localImages.add(mediaPath);
          imageNumber++;
          imageName = (n.attachmentName ?? '').trim();
          if (imageName.isEmpty) {
            imageName = mediaPath.split(RegExp(r'[/\\]')).last;
          }
        }
      }

      final urls = <String>[];
      for (final value in [
        (n.youtubeUrl ?? '').trim(),
        (n.linkUrl ?? '').trim(),
        (n.attachmentPath ?? '').trim(),
      ]) {
        if ((value.startsWith('http://') || value.startsWith('https://')) &&
            !urls.contains(value) &&
            !t.contains(value)) {
          urls.add(value);
        }
      }
      final section = <String>[];
      if (t.isNotEmpty) section.add(t);
      if (imageName != null) {
        section.add(provider
            .t('aiImg.attachedLabel')
            .replaceFirst('{i}', '$imageNumber')
            .replaceFirst('{name}', imageName));
      }
      section.addAll(urls);
      if (section.isNotEmpty) {
        // = ユーザー要望: 「要素 N」 の見出しは付けず、 各要素の本文をそのまま
        //   改行区切りで送る。
        parts.add(section.join('\n'));
      }
    }
    if (parts.isEmpty && localImages.isEmpty) {
      _appSnack(
          context,
          SnackBar(
              content: Text(provider.t('ai.nodeEmpty')),
              backgroundColor: const Color(0xFFE53935),
              duration: const Duration(seconds: 2)));
      return;
    }
    final content = parts.isEmpty
        ? '貼り付けた選択画像を、要素の順番に沿ってまとめて分析してください。'
        : parts.join('\n\n');
    final imagePayloads = localImages.isEmpty
        ? const <Map<String, String>>[]
        : await compute(_readAiImagePayloads, localImages);
    if (!mounted) return;
    // 本文と、元画像を1枚ずつ独立したFileとして同じAIパネルへ渡す。
    _sendQueryToBrowserAi(
      content,
      copyTextToClipboard: localImages.isEmpty,
      imagePayloads: imagePayloads,
    );
    if (localImages.isEmpty) return;

    final copied = await _copyImageFilesToClipboard(
      localImages,
      fallbackText: provider.browserAiApplyPrefix(content),
    );
    if (!mounted) return;
    final attached = imagePayloads.length;
    // 文言は多言語対応 (= ユーザー指摘: メッセージが日本語のまま)。
    final message = attached > 0
        ? provider
                .t('aiImg.attached')
                .replaceFirst('{n}', '$attached') +
            (copied > 0 ? provider.t('aiImg.alsoClipboard') : '')
        : copied > 0
            ? provider.t('aiImg.copiedOnly').replaceFirst('{n}', '$copied')
            : provider.t('aiImg.failed');
    _appSnack(
      context,
      SnackBar(
        content: Text(message),
        backgroundColor: attached > 0 || copied > 0
            ? const Color(0xFF43B97F)
            : const Color(0xFFE57373),
        duration: const Duration(seconds: 4),
      ),
    );
  }

  /// 範囲選択の一括 AI ボタン右クリック/長押し → モデル切替 / 前提条件 / 子要素
  /// 生成モードを選ぶダイアログ (= ユーザー要望)。
  void _showBulkAiModeMenu() {
    if (!mounted || _rangeSelectedIds.isEmpty) return;
    final provider = context.read<MindMapProvider>();
    showDialog<String>(
      context: context,
      barrierColor: Colors.black54,
      builder: (dctx) => Center(
        child: Material(
          color: Colors.transparent,
          child: Container(
            width: 300,
            padding: const EdgeInsets.fromLTRB(18, 16, 18, 18),
            decoration: BoxDecoration(
              color: const Color(0xFF2A2A3E),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                  color: const Color(0xFFFFB347).withValues(alpha: 0.5)),
              boxShadow: [
                BoxShadow(
                    color: Colors.black.withValues(alpha: 0.6),
                    blurRadius: 28,
                    offset: const Offset(0, 10)),
              ],
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(children: [
                  const Icon(Icons.auto_awesome_rounded,
                      color: Color(0xFFFFB347), size: 18),
                  const SizedBox(width: 8),
                  Text('AI (${_rangeSelectedIds.length})',
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 15,
                          fontWeight: FontWeight.w700)),
                ]),
                const SizedBox(height: 14),
                Text(provider.t('ai.questionMode'),
                    style: const TextStyle(
                        color: Colors.white54,
                        fontSize: 11,
                        fontWeight: FontWeight.w700)),
                const SizedBox(height: 10),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: [
                    for (final t in MindMapProvider.browserAiTargets)
                      _aiModeChip(provider, dctx, t),
                  ],
                ),
                const SizedBox(height: 8),
                // ── 前提条件の設定 ──
                InkWell(
                  onTap: () => Navigator.pop(dctx, 'prefix'),
                  borderRadius: BorderRadius.circular(8),
                  child: Padding(
                    padding:
                        const EdgeInsets.symmetric(vertical: 8, horizontal: 4),
                    child: Row(children: [
                      const Icon(Icons.tune_rounded,
                          color: Color(0xFF4FC3F7), size: 18),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(provider.t('ai.setPrefix'),
                                style: const TextStyle(
                                    color: Colors.white,
                                    fontSize: 13,
                                    fontWeight: FontWeight.w600)),
                            Text(
                                provider.browserAiPrefix.trim().isEmpty
                                    ? provider.t('ai.prefixPlaceholder')
                                    : provider.browserAiPrefix.trim(),
                                maxLines: 2,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                    color: Colors.white38, fontSize: 11)),
                          ],
                        ),
                      ),
                      const Icon(Icons.chevron_right_rounded,
                          color: Colors.white38, size: 18),
                    ]),
                  ),
                ),
                const SizedBox(height: 8),
                const Divider(color: Colors.white12, height: 1),
                const SizedBox(height: 14),
                // ── 子要素生成モード (選択した全要素に子要素を生成) ──
                InkWell(
                  onTap: () => Navigator.pop(dctx, 'gen'),
                  borderRadius: BorderRadius.circular(10),
                  child: Container(
                    width: double.infinity,
                    padding: const EdgeInsets.symmetric(
                        horizontal: 12, vertical: 12),
                    decoration: BoxDecoration(
                      color: const Color(0xFF43B97F).withValues(alpha: 0.15),
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(
                          color:
                              const Color(0xFF43B97F).withValues(alpha: 0.55)),
                    ),
                    child: Row(children: [
                      const Icon(Icons.account_tree_rounded,
                          color: Color(0xFF43B97F), size: 18),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(provider.t('ai.genChildrenApi'),
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 13,
                                fontWeight: FontWeight.w600)),
                      ),
                    ]),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    ).then((result) async {
      if (result == null || !mounted) return;
      if (result == 'prefix') {
        await _showBrowserAiPrefixDialog();
      } else if (result == 'gen') {
        await _generateChildrenForSelectedNodes();
      } else if (result.startsWith('q:')) {
        // モデル切替を保存してから、 そのままブラウザ AI へ一括送信。
        await context
            .read<MindMapProvider>()
            .setBrowserAiTarget(result.substring(2));
        _sendBulkNodesToBrowserAi();
      }
    });
  }

  /// 範囲選択した全要素に対して子要素を AI 生成する (= 一括 AI の子要素生成
  /// モード)。 キー未設定なら 1 度だけ入力を促し、 以降は順番に生成する。
  Future<void> _generateChildrenForSelectedNodes() async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final ids =
        _rangeSelectedIds.where((id) => provider.nodes[id] != null).toList();
    if (ids.isEmpty) return;
    if (!provider.hasActiveAiKey) {
      _showGeminiKeyDialog(
          context, provider, () => _generateChildrenForSelectedNodes(),
          anyProvider: true);
      return;
    }
    _appSnack(
        context,
        SnackBar(
            content: Text(context.read<MindMapProvider>()
                .t('bulk.generatingChildren')
                .replaceFirst('{n}', '${ids.length}')),
            duration: const Duration(seconds: 2)));
    for (final id in ids) {
      if (!mounted) return;
      try {
        await provider.aiGenerateChildren(id);
      } catch (_) {
        // 個別失敗は無視して次へ (= 一括処理を止めない)。
      }
    }
  }

  /// 分割パネルに、 現在選択中の ブラウザAI と同じサイト (ホスト) が既に
  /// 開いているか。 開いていれば再読込せず入力欄への挿入だけで済ませる。
  // ignore: unused_element
  bool _splitShowingSameAiHost(MindMapProvider provider) {
    if (!_splitOpen || _splitMode != 'web') return false;
    final tmpl = provider.browserAiTargetDef['url'] ?? '';
    final th = Uri.tryParse(tmpl.replaceAll('{q}', ''))?.host ?? '';
    final ch = Uri.tryParse(_splitCurrentUrl)?.host ?? '';
    if (th.isEmpty || ch.isEmpty) return false;
    return th == ch;
  }

  /// パネルに開いている [url] が AI チャットサービスなら、 その id を返す
  /// (chatgpt / gemini / claude / deepseek / grok / perplexity)。 違えば null。
  /// browserAiTargets のホストと突き合わせて判定する (Google 検索は除外)。
  String? _panelAiId(MindMapProvider provider, String url) {
    if (url.isEmpty) return null;
    final h = Uri.tryParse(url)?.host ?? '';
    if (h.isEmpty) return null;
    for (final t in MindMapProvider.browserAiTargets) {
      final id = t['id'];
      if (id == null || id == 'google') continue;
      final th =
          Uri.tryParse((t['url'] ?? '').replaceAll('{q}', ''))?.host ?? '';
      if (th.isNotEmpty && th == h) return id;
    }
    return null;
  }

  /// ノードの AI ボタンで両側に AI チャットが開いているときの、 最後に文章を
  /// 渡した側 ('left' / 'right')。 次回は反対側へ渡して左右交互にする
  /// (= ユーザー要望)。
  String _lastNodeAiSide = 'right';

  /// 開いている AI チャット欄のヘッダーを右クリックした時、 同じ AI モデルを
  /// 反対側のパネルにももう一つ開く (= ユーザー要望)。 そのパネルが AI チャット
  /// でない (PDF 等) 場合は何もしない。 複製先には、 直近のクエリ付き URL では
  /// なく AI のホーム URL を開いて「新しいチャット」 として出す。
  void _duplicateSplitAiToOpposite({required bool fromLeft}) {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final srcUrl = fromLeft ? _splitLeftCurrentUrl : _splitCurrentUrl;
    final srcMode = fromLeft ? _splitLeftMode : _splitMode;
    if (srcMode != 'web') return;
    final aiId = _panelAiId(provider, srcUrl);
    if (aiId == null) return; // AI チャット以外は対象外
    final tmpl = MindMapProvider.browserAiTargets.firstWhere(
          (t) => t['id'] == aiId,
          orElse: () => const <String, String>{},
        )['url'] ??
        '';
    var openUrl = tmpl.replaceAll('{q}', '');
    // 末尾の ?q= / &q= を取り除いてホーム URL にする。
    openUrl = openUrl.replaceAll(RegExp(r'[?&]q=$'), '');
    if (openUrl.isEmpty) openUrl = srcUrl;
    // 反対側のパネルに開く。
    _openUrlInSplitPanel(openUrl, isLeftPanel: !fromLeft);
  }

  /// 送信ごとの通し番号 (= 分割パネル AI への二重挿入防止トークン)。
  int _splitAiInjectSeq = 0;

  /// 分割パネルで開いた AI のチャット入力欄に [text] を挿入する。
  /// 既に同じ文字列が入っている (= ?q= で入った / 挿入済み) 場合はスキップ。
  /// [left] = true で左パネル、 false で右パネルの WebView に挿入する。
  /// AI ページを開いている WebView (分割セル / 浮遊窓 / ドックなど) 全部に
  /// JS を流す (= ユーザー報告: 添付画像が AI に渡らない)。
  void _execOnOpenAiWebViews(String js) {
    const hosts = [
      'chatgpt.com',
      'chat.openai.com',
      'gemini.google.com',
      'claude.ai',
      'perplexity.ai',
      'grok.com',
      'chat.deepseek.com',
    ];
    for (final v in _WinGoogleSearchViewState.liveViews.toList()) {
      final u = v.currentUrl.toLowerCase();
      if (hosts.any(u.contains)) {
        // ignore: discarded_futures
        v.execJs(js);
      }
    }
  }

  void _injectImagesToSplitAi(
    List<Map<String, String>> images,
    int token, {
    bool left = false,
  }) {
    if (!mounted || images.isEmpty || token != _splitAiInjectSeq) return;
    final provider = context.read<MindMapProvider>();
    final targetUrl = left ? _splitLeftCurrentUrl : _splitCurrentUrl;
    // 遅延注入中に別サイトへ移動した場合、ローカル画像を誤送信しない。
    // ただし旧来の左右分割パネル以外 (マップ分割セル / 浮遊窓) で AI を
    // 開いているケースもあるので、 その場合は下の共通経路で流す。
    final hasLegacyPanel = _panelAiId(provider, targetUrl) != null;
    final payload = jsonEncode(images);
    final js = '''
(function() {
  try {
    if (window.__mmNodeAiImagesToken === $token) return 'dup';
    var specs = $payload;
    if (!Array.isArray(specs) || !specs.length) return 'empty';
    var files = [];
    for (var i = 0; i < specs.length; i++) {
      var spec = specs[i] || {};
      var binary = atob(spec.base64 || '');
      var bytes = new Uint8Array(binary.length);
      for (var j = 0; j < binary.length; j++) {
        bytes[j] = binary.charCodeAt(j);
      }
      files.push(new File(
        [bytes],
        spec.name || ('kamispec-image-' + (i + 1) + '.png'),
        { type: spec.mime || 'image/png', lastModified: Date.now() }
      ));
    }
    if (!files.length) return 'empty';

    function transferFor(list) {
      var transfer = new DataTransfer();
      for (var i = 0; i < list.length; i++) {
        transfer.items.add(list[i]);
      }
      return transfer;
    }

    function collectRoots() {
      var roots = [document];
      for (var i = 0; i < roots.length; i++) {
        var elements = roots[i].querySelectorAll('*');
        for (var j = 0; j < elements.length; j++) {
          if (elements[j].shadowRoot &&
              roots.indexOf(elements[j].shadowRoot) < 0) {
            roots.push(elements[j].shadowRoot);
          }
        }
      }
      return roots;
    }

    function accepts(input, file) {
      var accept = String(input.accept || '').trim().toLowerCase();
      if (!accept) return true;
      var values = accept.split(',');
      var mime = String(file.type || '').toLowerCase();
      var name = String(file.name || '').toLowerCase();
      for (var i = 0; i < values.length; i++) {
        var value = values[i].trim();
        if (value === mime) return true;
        if (value.slice(-2) === '/*' &&
            mime.indexOf(value.slice(0, -1)) === 0) return true;
        if (value.charAt(0) === '.' &&
            name.slice(-value.length) === value) return true;
      }
      return false;
    }

    var roots = collectRoots();
    var selectors = [
      'form[data-type="unified-composer"] input[type="file"]',
      'input[data-testid="file-upload-input"]',
      'input[data-testid="upload-file-input"]',
      'images-files-uploader input[type="file"]',
      'input[type="file"][accept*="image"]',
      'input[type="file"][multiple]',
      'input[type="file"]'
    ];
    var candidates = [];
    for (var r = 0; r < roots.length; r++) {
      for (var s = 0; s < selectors.length; s++) {
        var found = roots[r].querySelectorAll(selectors[s]);
        for (var f = 0; f < found.length; f++) {
          if (candidates.indexOf(found[f]) < 0) candidates.push(found[f]);
        }
      }
    }
    var scored = [];
    for (var c = 0; c < candidates.length; c++) {
      var candidate = candidates[c];
      if (candidate.disabled) continue;
      if (files.length > 1 && !candidate.multiple) continue;
      var allAccepted = true;
      for (var a = 0; a < files.length; a++) {
        if (!accepts(candidate, files[a])) { allAccepted = false; break; }
      }
      if (!allAccepted) continue;
      var meta = [
        candidate.id,
        candidate.name,
        candidate.getAttribute('aria-label'),
        candidate.getAttribute('data-testid')
      ].join(' ');
      var score = candidate.multiple ? 30 : 0;
      if (/upload|file|attach/i.test(meta)) score += 40;
      if (/avatar|profile|icon|logo/i.test(meta)) score -= 180;
      var form = candidate.closest('form');
      if (form && form.querySelector(
          '#prompt-textarea,textarea,[contenteditable="true"]')) score += 80;
      if (candidate.closest(
          '[data-type="unified-composer"],[class*="composer" i],' +
          '[class*="prompt" i]')) score += 50;
      if (candidate.closest(
          '[class*="avatar" i],[class*="profile" i]')) score -= 180;
      scored.push({ input: candidate, score: score });
    }
    scored.sort(function(a, b) { return b.score - a.score; });

    if (scored.length) {
      var input = scored[0].input;
      var transfer = transferFor(files);
      var descriptor = Object.getOwnPropertyDescriptor(
        window.HTMLInputElement.prototype,
        'files'
      );
      if (descriptor && descriptor.set) {
        descriptor.set.call(input, transfer.files);
      } else {
        input.files = transfer.files;
      }
      var staged = input.files ? input.files.length : 0;
      if (!staged) return 'file-input-empty';
      input.dispatchEvent(new Event(
        'input', { bubbles: true, composed: true }
      ));
      input.dispatchEvent(new Event(
        'change', { bubbles: true, composed: true }
      ));
      window.__mmNodeAiImagesToken = $token;
      return 'file-input:' + staged;
    }

    // file input がDOMに出ていないサイト向けに、composerへ一度だけdropを試す。
    // 画像は合成せず、同じDataTransfer内の個別Fileとして渡す。
    var promptSelectors = [
      '#prompt-textarea',
      'div.ProseMirror[contenteditable="true"]',
      'rich-textarea [contenteditable="true"]',
      'div.ql-editor[contenteditable="true"]',
      '[data-lexical-editor="true"][contenteditable="true"]',
      'textarea',
      '[role="textbox"][contenteditable="true"]',
      '[contenteditable="true"]'
    ];
    var target = null;
    for (var rr = 0; rr < roots.length && !target; rr++) {
      for (var ps = 0; ps < promptSelectors.length && !target; ps++) {
        var prompts = roots[rr].querySelectorAll(promptSelectors[ps]);
        for (var pi = prompts.length - 1; pi >= 0; pi--) {
          var rect = prompts[pi].getBoundingClientRect();
          if (rect.width > 20 && rect.height > 10) {
            target = prompts[pi];
            break;
          }
        }
      }
    }
    if (!target) return 'not-found';
    var transfer = transferFor(files);
    target.focus();
    var dropHandled = false;
    try {
      target.dispatchEvent(new DragEvent('dragenter', {
        bubbles: true, cancelable: true, composed: true,
        dataTransfer: transfer
      }));
      target.dispatchEvent(new DragEvent('dragover', {
        bubbles: true, cancelable: true, composed: true,
        dataTransfer: transfer
      }));
      var drop = new DragEvent('drop', {
        bubbles: true, cancelable: true, composed: true,
        dataTransfer: transfer
      });
      dropHandled = !target.dispatchEvent(drop);
    } catch (_) {}
    if (dropHandled) {
      window.__mmNodeAiImagesToken = $token;
      return 'drop:' + files.length;
    }

    // dropを受け付けないサイトだけpasteへフォールバックする。
    var paste = new Event(
      'paste', { bubbles: true, cancelable: true, composed: true }
    );
    Object.defineProperty(paste, 'clipboardData', { value: transfer });
    if (!target.dispatchEvent(paste)) {
      window.__mmNodeAiImagesToken = $token;
      return 'paste:' + files.length;
    }
    return 'not-handled';
  } catch (e) {
    return 'error: ' + e;
  }
})();
''';
    try {
      if (hasLegacyPanel) {
        if (!kIsWeb && Platform.isWindows) {
          final controller =
              left ? _splitLeftWinController : _splitWinController;
          final ready = left ? _splitLeftWinInitialized : _splitWinInitialized;
          if (ready) controller?.executeScript(js);
        } else {
          (left ? _splitLeftIawController : _splitIawController)
              ?.evaluateJavascript(source: js);
        }
      }
      // マップ分割セル / 浮遊窓 / ドックで開いている AI にも流す
      // (= ユーザー報告: 添付画像が AI に渡らない)。
      _execOnOpenAiWebViews(js);
    } catch (_) {}
  }

  void _injectTitleToSplitAi(String text, int token, {bool left = false}) {
    if (!mounted) return;
    // 古い (キャンセル済み) 注入バッチは実行しない (= ユーザー要望: AI ボタンで
    //   ChatGPT 等を開くと、 最後に開いた単語が勝手にプロンプト欄へ入力される
    //   バグの修正)。 パネルに別 URL を開く等で _splitAiInjectSeq が進むと、
    //   予約済みの遅延注入 (最大 5.5 秒) はここで無効化される。
    if (token != _splitAiInjectSeq) return;
    final escaped = jsonEncode(text);
    final js = '''
(function() {
  try {
    var text = $escaped;
    var t = (text || '').trim();
    if (!t) return 'empty';
    var lp = ((location.host || '') + ' ' + (location.pathname || ''))
        .toLowerCase();
    if (/accounts\.google|appleid|signin|sign-in|sign_in|login|log-in|auth\./
        .test(lp)) return 'login-page';
    function isLoginField(el) {
      if (!el || el.tagName !== 'INPUT') return false;
      var ty = (el.type || '').toLowerCase();
      if (ty !== 'text' && ty !== 'search' && ty !== '') return true;
      var meta = ((el.name || '') + ' ' + (el.id || '') + ' ' +
          (el.autocomplete || '') + ' ' +
          (el.getAttribute('aria-label') || '')).toLowerCase();
      if (/email|identifier|passw|user|phone|tel|otp|code/.test(meta)) {
        return true;
      }
      var f = el.closest('form');
      if (f && f.querySelector(
          'input[type="password"],input[type="email"]')) return true;
      return false;
    }
    var selectors = [
      'div.ProseMirror[contenteditable="true"]',
      '#prompt-textarea',
      'div[contenteditable="true"].ql-editor',
      'textarea',
      'input[type="text"]',
      'div[contenteditable="true"]',
    ];
    function visibleArea(el) {
      var r = el.getBoundingClientRect();
      if (r.width < 80 || r.height < 16) return 0;
      if (r.bottom < 0 || r.top > window.innerHeight) return 0;
      return r.width * r.height;
    }
    var best = null, bestArea = 0;
    for (var i = 0; i < selectors.length; i++) {
      var nodes = document.querySelectorAll(selectors[i]);
      for (var j = 0; j < nodes.length; j++) {
        if (isLoginField(nodes[j])) continue;
        var a = visibleArea(nodes[j]);
        if (a > bestArea) { bestArea = a; best = nodes[j]; }
      }
      if (best) break;
    }
    if (!best) return 'not-found';
    var tag = best.tagName;
    var isField = tag === 'TEXTAREA' || tag === 'INPUT';
    var existing = isField ? (best.value || '')
                           : (best.innerText || best.textContent || '');
    if (window.__mmNodeAiToken === $token &&
        existing.indexOf(t) !== -1) return 'dup';
    if (existing.indexOf(t) !== -1) { window.__mmNodeAiToken = $token; return 'already'; }
    best.focus();
    if (isField) {
      var proto = tag === 'TEXTAREA'
        ? window.HTMLTextAreaElement.prototype
        : window.HTMLInputElement.prototype;
      var setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
      setter.call(best, text);
      best.dispatchEvent(new Event('input', { bubbles: true }));
      try { best.selectionStart = best.selectionEnd = text.length; } catch (e) {}
    } else {
      try {
        var range = document.createRange();
        range.selectNodeContents(best);
        var sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
        document.execCommand('insertText', false, text);
      } catch (e) {
        best.innerText = text;
        best.dispatchEvent(new InputEvent('input', { bubbles: true, data: text }));
      }
    }
    window.__mmNodeAiToken = $token;
    return 'ok';
  } catch (e) { return 'error: ' + e; }
})();
''';
    try {
      if (!kIsWeb && Platform.isWindows) {
        if (left) {
          if (_splitLeftWinInitialized) {
            _splitLeftWinController?.executeScript(js);
          }
        } else {
          if (_splitWinInitialized) _splitWinController?.executeScript(js);
        }
      } else {
        (left ? _splitLeftIawController : _splitIawController)
            ?.evaluateJavascript(source: js);
      }
      // マップ分割セル / 浮遊窓で開いている AI にも入力する。
      _execOnOpenAiWebViews(js);
    } catch (_) {}
  }

  /// 子要素生成モード (AI ボタン右クリック/長押し → 子要素を生成)。
  /// 設定済みの API キーで、 親ノードの内容に合わせた子ノードを AI が生成する。
  /// (provider.aiGenerateChildren は現在の AI プロバイダ/キーを使う。)
  void _generateChildrenForNode(String nodeId) {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    if (provider.nodes[nodeId] == null) return;
    // 子ノード生成は現在の AI プロバイダ (Gemini/OpenAI/Claude/Grok/DeepSeek)
    //   を使うので、 Gemini 限定ではなく「いずれかのキーがあるか」 で判定する
    //   (= ユーザー報告: OpenAI 等だと API キー画面から先に進めないバグの修正)。
    if (!provider.hasActiveAiKey) {
      _showGeminiKeyDialog(
          context, provider, () => _generateChildrenForNode(nodeId),
          anyProvider: true);
      return;
    }
    // 進捗スナックバー (停止ボタン付き) + 完了/エラー通知は _runAiTask が担当。
    _runAiTask(context, nodeId, 'children');
  }

  /// PDF ビューアのメモ / ノードから AI に質問を投げ、 その回答を
  /// 「マップ (新規ノード)」 または「メモに追記」 で書き戻す (= ユーザー要望)。
  /// 設定済み API キーで回答を取得し、 回答ダイアログから配置先を選べる。
  Future<void> _askAiQuestionAndPlace({
    required String question,
    String? sourceNodeId, // 答えをノード化する時、 近くに配置する元ノード
    PdfMemo? memo, // 答えを追記する対象 (PDF メモ)
    String? memoNodeId, // memo が属するノード
    // ── 添付 (画像/PDF/docx/pptx) を見た上で答えさせる対象ノード ──
    //   (= ユーザー要望: 画像/ファイルノードの AI ボタンで、 文字が空でも
    //   中の画像/ファイルを API の AI に渡す)。 指定時は askAiAboutNodeMedia を使う。
    MindMapNode? mediaNode,
  }) async {
    if (!mounted) return;
    var q = question.trim();
    if (q.isEmpty) {
      // 添付ノードがある時は文字が空でも OK (添付物そのものを解析させる)。
      if (mediaNode != null) {
        q = 'この添付物 (画像/ファイル) の内容を読み取ってください。'
            '問題・課題・質問が書かれていれば直接解いて答えを、'
            'そうでなければ要点を日本語で説明してください。';
      } else {
        _showSimpleInfoDialog('質問内容が空のため AI に送れません');
        return;
      }
    }
    final provider = context.read<MindMapProvider>();
    if (!provider.hasActiveAiKey) {
      _showGeminiKeyDialog(
          context,
          provider,
          () => _askAiQuestionAndPlace(
              question: question,
              sourceNodeId: sourceNodeId,
              memo: memo,
              memoNodeId: memoNodeId),
          anyProvider: true);
      return;
    }
    // ローディング (キャンセル不可の小ダイアログ)
    showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (_) => const Center(
        child: SizedBox(
          width: 54,
          height: 54,
          child: CircularProgressIndicator(color: Color(0xFFBA68C8)),
        ),
      ),
    );
    String answer = '';
    try {
      // 添付ノード指定時は画像/ファイルを直接 AI に渡して解析させる。
      answer = (mediaNode != null
              ? await provider.askAiAboutNodeMedia(mediaNode, q)
              : await provider.askAi(q))
          .trim();
    } catch (e) {
      if (mounted) Navigator.of(context, rootNavigator: true).pop();
      if (mounted) _showSimpleInfoDialog('AI エラー: $e');
      return;
    }
    if (mounted) Navigator.of(context, rootNavigator: true).pop(); // ローディング閉じ
    if (!mounted) return;
    if (answer.isEmpty) {
      _showSimpleInfoDialog('AI から回答が得られませんでした');
      return;
    }
    await showDialog<void>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
            side: const BorderSide(color: Color(0xFFBA68C8), width: 1)),
        title: Row(children: [
          const Icon(Icons.auto_awesome_rounded,
              color: Color(0xFFBA68C8), size: 20),
          const SizedBox(width: 8),
          Expanded(
            child: Text(provider.t('ai.answer'),
                style: const TextStyle(color: Colors.white, fontSize: 16)),
          ),
        ]),
        content: SizedBox(
          width: 480,
          child: SingleChildScrollView(
            child: SelectableText(answer,
                style: const TextStyle(color: Colors.white70, fontSize: 13)),
          ),
        ),
        actionsOverflowButtonSpacing: 6,
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.close'),
                style: const TextStyle(color: Colors.white54)),
          ),
          if (memo != null && memoNodeId != null)
            ElevatedButton.icon(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF4FC3F7),
                  foregroundColor: Color(0xFF10241F),),
              icon: const Icon(Icons.note_add_rounded, size: 16),
              label: Text(provider.t('ai.appendToMemo')),
              onPressed: () {
                provider.updatePdfMemo(memoNodeId, memo.id,
                    text: '${memo.text}\n\n【AI】 $answer');
                Navigator.pop(dctx);
                _appSnack(
                  context,
                  SnackBar(
                    content: Text(provider.t('ai.appendedToMemo')),
                    backgroundColor: const Color(0xFF4FC3F7),
                    duration: const Duration(seconds: 2),
                  ),
                );
              },
            ),
          ElevatedButton.icon(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF43B97F),
                foregroundColor: Colors.white,),
            icon: const Icon(Icons.account_tree_rounded, size: 16),
            label: Text(provider.t('ai.addToMap')),
            onPressed: () {
              _placeAiAnswerAsNode(q, answer, sourceNodeId);
              Navigator.pop(dctx);
              _appSnack(
                context,
                SnackBar(
                  content: Text(provider.t('ai.addedToMap')),
                  backgroundColor: const Color(0xFF43B97F),
                  duration: const Duration(seconds: 2),
                ),
              );
            },
          ),
        ],
      ),
    );
  }

  /// AI の回答を新しいノードとしてマップに追加する。 質問元ノードがあれば
  /// その右隣に、 無ければ基準位置付近に置く。
  void _placeAiAnswerAsNode(
      String question, String answer, String? sourceNodeId) {
    final provider = context.read<MindMapProvider>();
    final src = sourceNodeId != null ? provider.nodes[sourceNodeId] : null;
    final Offset pos;
    if (src != null) {
      pos = Offset(src.position.dx + src.width + 80, src.position.dy);
    } else {
      final ref = _currentRefPos();
      pos = Offset(ref.dx, ref.dy + 80);
    }
    final node = provider.addNodeAtCenterReturning(pos);
    final title =
        question.length > 40 ? '${question.substring(0, 40)}…' : question;
    provider.updateNodeTitle(node.id, 'Q: $title');
    provider.updateNodeMemo(node.id, answer);
  }

  /// 中央に出る簡易お知らせダイアログ (ビューアの上にも表示される)。
  void _showSimpleInfoDialog(String msg) {
    if (!mounted) return;
    showDialog<void>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        content: Text(msg,
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: const Text('OK', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
  }

  /// ギャラリーのタイルに入り切らなかった文字を全部読むための窓
  /// (= ユーザー要望: 入り切らない文字を表示する)。
  ///
  /// タイルの大きさは固定なので、 長い文章は途中で切れる。 切れているタイル
  /// だけに出る「…」 ボタンからここへ来る。 書式付き (リッチテキスト) の
  /// 要素は見た目のまま、 それ以外は素の文字として出す。 どちらも選んで
  /// 写せるようにし、 その場で書き直しにも進めるようにしている。
  ///
  /// [pageId] は分割ペインなど、 いま編集しているページ以外の要素を開く時に
  /// 渡す。 省略すると現在のページから探す。
  Future<void> _showGalleryFullTextDialog(String nodeId,
      {String? pageId}) async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    // 編集は「今のページの要素」 に限る (別ページの要素は編集経路が別のため)。
    final bool onCurrentPage =
        pageId == null || pageId == provider.currentPage.id;
    MindMapNode? node;
    if (onCurrentPage) {
      node = provider.nodes[nodeId];
    } else {
      for (final p in provider.pages) {
        if (p.id == pageId) {
          node = p.nodes[nodeId];
          break;
        }
      }
    }
    if (node == null) return;
    final rich = node.richText;
    final bool hasRich = rich != null && rich.isNotEmpty;
    final String plain = hasRich
        ? MindMapNode.buildRichSpan(rich, const TextStyle())
            .toPlainText()
            .trim()
        : [
            node.title.trim(),
            (node.memoText ?? '').trim(),
          ].where((s) => s.isNotEmpty).join('\n');
    if (plain.isEmpty) return;
    // 書式付きはタイルと同じ見た目で読めるようにする。
    final InlineSpan? richSpan = hasRich
        ? MindMapNode.buildRichSpan(
            rich,
            const TextStyle(color: Colors.white, fontSize: 14, height: 1.6),
          )
        : null;
    final edited = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        shape:
            RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        title: Row(children: [
          const Icon(Icons.notes_rounded, color: Color(0xFF4FC3F7), size: 19),
          const SizedBox(width: 8),
          Expanded(
            child: Text(provider.t('gallery.fullText'),
                style: const TextStyle(
                    color: Colors.white,
                    fontSize: 15,
                    fontWeight: FontWeight.w700)),
          ),
        ]),
        content: SizedBox(
          width: 460,
          // 画面が小さい端末でも収まるよう、 高さは画面の半分までにして
          //   中でスクロールさせる。
          height: (MediaQuery.of(dctx).size.height * 0.5).clamp(160.0, 420.0),
          child: SingleChildScrollView(
            child: richSpan is TextSpan
                ? SelectableText.rich(richSpan)
                : SelectableText(
                    plain,
                    style: const TextStyle(
                        color: Colors.white, fontSize: 14, height: 1.6),
                  ),
          ),
        ),
        actions: [
          TextButton.icon(
            onPressed: () async {
              await Clipboard.setData(ClipboardData(text: plain));
              if (!dctx.mounted) return;
              Navigator.pop(dctx);
              if (!mounted) return;
              _appSnack(
                context,
                SnackBar(content: Text(provider.t('gallery.fullTextCopied'))),
              );
            },
            icon: const Icon(Icons.copy_rounded,
                size: 15, color: Colors.white70),
            label: Text(provider.t('btn.copy'),
                style: const TextStyle(color: Colors.white70)),
          ),
          if (onCurrentPage)
            TextButton.icon(
              onPressed: () => Navigator.pop(dctx, true),
              icon: const Icon(Icons.edit_rounded,
                  size: 15, color: Color(0xFF4FC3F7)),
              label: Text(provider.t('btn.edit'),
                  style: const TextStyle(color: Color(0xFF4FC3F7))),
            ),
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.close'),
                style: const TextStyle(color: Colors.white54)),
          ),
        ],
      ),
    );
    if (edited == true && mounted) {
      await _showNodeRichEditDialog(context, nodeId);
    }
  }

  /// ノードの AI ボタン右クリック/長押し → 「質問モード(AI 切替) / 子要素生成
  /// モード」 の選択ダイアログ。 ノードが中央にあるとアクションバーと重なる
  /// 問題 (= ユーザー要望) を避けるため、 まずアクションバーを閉じてから、
  /// 画面の安定した context で中央モーダルとして表示する。
  void _showNodeAiModeMenu(String nodeId) {
    if (!mounted) return;
    _removeOverlay(); // アクションバー (色パレット/スライダー含む) を閉じる
    final provider = context.read<MindMapProvider>();
    if (provider.nodes[nodeId] == null) return;
    showDialog<String>(
      context: context,
      barrierColor: Colors.black54,
      builder: (dctx) => Center(
        child: Material(
          color: Colors.transparent,
          child: Container(
            width: 290,
            padding: const EdgeInsets.fromLTRB(18, 16, 18, 18),
            decoration: BoxDecoration(
              color: const Color(0xFF2A2A3E),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                  color: const Color(0xFFBA68C8).withValues(alpha: 0.45)),
              boxShadow: [
                BoxShadow(
                    color: Colors.black.withValues(alpha: 0.6),
                    blurRadius: 28,
                    offset: const Offset(0, 10)),
              ],
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(children: const [
                  Icon(Icons.auto_awesome_rounded,
                      color: Color(0xFFBA68C8), size: 18),
                  SizedBox(width: 8),
                  Text('AI',
                      style: TextStyle(
                          color: Colors.white,
                          fontSize: 15,
                          fontWeight: FontWeight.w700)),
                ]),
                const SizedBox(height: 14),
                Text(provider.t('ai.questionMode'),
                    style: const TextStyle(
                        color: Colors.white54,
                        fontSize: 11,
                        fontWeight: FontWeight.w700)),
                const SizedBox(height: 10),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: [
                    for (final t in MindMapProvider.browserAiTargets)
                      _aiModeChip(provider, dctx, t),
                  ],
                ),
                const SizedBox(height: 16),
                const Divider(color: Colors.white12, height: 1),
                const SizedBox(height: 14),
                InkWell(
                  onTap: () => Navigator.pop(dctx, 'gen'),
                  borderRadius: BorderRadius.circular(10),
                  child: Container(
                    width: double.infinity,
                    padding: const EdgeInsets.symmetric(
                        horizontal: 12, vertical: 12),
                    decoration: BoxDecoration(
                      color: const Color(0xFF43B97F).withValues(alpha: 0.15),
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(
                          color:
                              const Color(0xFF43B97F).withValues(alpha: 0.55)),
                    ),
                    child: Row(children: [
                      const Icon(Icons.account_tree_rounded,
                          color: Color(0xFF43B97F), size: 18),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(provider.t('ai.genChildrenApi'),
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 13,
                                fontWeight: FontWeight.w600)),
                      ),
                    ]),
                  ),
                ),
                const SizedBox(height: 8),
                // ── AI に質問して回答を取得 (= ユーザー要望: 答えをマップ/メモへ) ──
                InkWell(
                  onTap: () => Navigator.pop(dctx, 'ask'),
                  borderRadius: BorderRadius.circular(10),
                  child: Container(
                    width: double.infinity,
                    padding: const EdgeInsets.symmetric(
                        horizontal: 12, vertical: 12),
                    decoration: BoxDecoration(
                      color: const Color(0xFF4FC3F7).withValues(alpha: 0.15),
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(
                          color:
                              const Color(0xFF4FC3F7).withValues(alpha: 0.55)),
                    ),
                    child: Row(children: [
                      const Icon(Icons.quiz_rounded,
                          color: Color(0xFF4FC3F7), size: 18),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(provider.t('ai.askGetAnswer'),
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 13,
                                fontWeight: FontWeight.w600)),
                      ),
                    ]),
                  ),
                ),
                const SizedBox(height: 8),
                // ── AI に渡す前提条件の設定 (= ユーザー要望: 要素の AI ボタンを
                //    右クリックした時に前提条件プロンプトを設定できる項目) ──
                InkWell(
                  onTap: () => Navigator.pop(dctx, 'prereq'),
                  borderRadius: BorderRadius.circular(10),
                  child: Container(
                    width: double.infinity,
                    padding: const EdgeInsets.symmetric(
                        horizontal: 12, vertical: 12),
                    decoration: BoxDecoration(
                      color: const Color(0xFFFFB347).withValues(alpha: 0.12),
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(
                          color:
                              const Color(0xFFFFB347).withValues(alpha: 0.5)),
                    ),
                    child: Row(children: [
                      const Icon(Icons.rule_rounded,
                          color: Color(0xFFFFB347), size: 18),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(provider.t('ai.prereqTitle'),
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 13,
                                fontWeight: FontWeight.w600)),
                      ),
                    ]),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    ).then((result) async {
      if (result == null || !mounted) return;
      if (result == 'prereq') {
        // 前提条件 (= ブラウザ AI に渡す文章の先頭に付く指示) の編集。
        _showBrowserAiPrefixDialog();
      } else if (result == 'gen') {
        _generateChildrenForNode(nodeId);
      } else if (result == 'ask') {
        // 明示的な API 送信 (= ユーザー要望: この「AI に質問して回答を取得」 が
        //   API キーを使う明示ボタン)。 添付 (画像/PDF/docx/pptx) があれば、
        //   それも API に直接渡して解析させる。
        final n = context.read<MindMapProvider>().nodes[nodeId];
        if (n != null) {
          final hasLocalMedia = _localMediaPathOfNode(n) != null;
          _askAiQuestionAndPlace(
            question: n.title,
            sourceNodeId: nodeId,
            mediaNode: hasLocalMedia ? n : null,
          );
        }
      } else if (result.startsWith('q:')) {
        // 質問モード: モデルを保存 (= 次回も同じモデル) してから開く。
        await context
            .read<MindMapProvider>()
            .setBrowserAiTarget(result.substring(2));
        _openBrowserAiForNode(nodeId);
      }
    });
  }

  /// 質問モードの AI 選択チップ。 選択中は強調表示。
  Widget _aiModeChip(
      MindMapProvider provider, BuildContext dctx, Map<String, String> t) {
    final selected = t['id'] == provider.browserAiTarget;
    return InkWell(
      onTap: () => Navigator.pop(dctx, 'q:${t['id']}'),
      borderRadius: BorderRadius.circular(20),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
        decoration: BoxDecoration(
          color: selected
              ? const Color(0xFFBA68C8).withValues(alpha: 0.30)
              : Colors.white.withValues(alpha: 0.06),
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
              color: selected ? const Color(0xFFBA68C8) : Colors.white24,
              width: selected ? 1.5 : 1),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          if (selected)
            const Padding(
              padding: EdgeInsets.only(right: 4),
              child:
                  Icon(Icons.check_rounded, size: 14, color: Color(0xFFBA68C8)),
            ),
          Text(t['label'] ?? '',
              style: TextStyle(
                  color: selected ? Colors.white : Colors.white70,
                  fontSize: 13,
                  fontWeight: selected ? FontWeight.w700 : FontWeight.w500)),
        ]),
      ),
    );
  }

