        backgroundColor: const Color(0xFF2A2A3E),
        title: Row(children: [
          Container(
            width: 24,
            height: 24,
            decoration: const BoxDecoration(
                color: Color(0xFFBA68C8), shape: BoxShape.circle),
            child:
                const Icon(Icons.chat_rounded, color: Colors.white, size: 14),
          ),
          const SizedBox(width: 8),
          Text(provider.t('ai.customQuestion'),
              style: const TextStyle(color: Colors.white, fontSize: 14)),
        ]),
        content: TextField(
          controller: promptCtrl,
          autofocus: true,
          maxLines: 4,
          minLines: 2,
          style: const TextStyle(color: Colors.white, fontSize: 13),
          decoration: InputDecoration(
            filled: true,
            fillColor: Colors.white.withValues(alpha: 0.07),
            hintText: provider.t('ai.enterQuestion'),
            hintStyle: const TextStyle(color: Colors.white30, fontSize: 12),
            border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
                borderSide: BorderSide.none),
            contentPadding: const EdgeInsets.all(12),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFBA68C8),
                foregroundColor: Colors.white,),
            onPressed: () {
              final prompt = promptCtrl.text.trim();
              if (prompt.isEmpty) return;
              Navigator.pop(dctx);
              _runAiTask(ctx, nodeId, 'custom', customPrompt: prompt);
            },
            child: Text(provider.t('btn.send')),
          ),
        ],
      ),
    );
  }

  void _runAiTask(BuildContext ctx, String nodeId, String type,
      {String? customPrompt}) {
    final provider = ctx.read<MindMapProvider>();
    final modelLabel = provider.aiModelTier == 'pro' ? 'Pro' : 'Flash';

    // ローディングスナックバー表示（停止ボタン付き）
    // 注: AI はバックグラウンドで動作するため、別の作業を並行して行える。
    //     Ctrl+Z は「AI開始後の別作業」を先に取り消し、それが無くなってから
    //     AI 自体をキャンセルする。
    final messenger = ScaffoldMessenger.of(ctx);
    _appSnackM(
        messenger,
        SnackBar(
          content: Row(children: [
            const SizedBox(
                width: 18,
                height: 18,
                child: CircularProgressIndicator(
                    strokeWidth: 2, color: Colors.white)),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text('$modelLabel ${provider.t('ai.thinking')}',
                      style: const TextStyle(fontSize: 13)),
                  Text(provider.t(_isDesktop ? 'ai.bgHint' : 'ai.bgHintMobile'),
                      style:
                          const TextStyle(fontSize: 10, color: Colors.white54)),
                ],
              ),
            ),
          ]),
          duration: const Duration(seconds: 120),
          backgroundColor: const Color(0xFF2A2A3E),
          // 停止ボタン: タップで進行中の AI 生成をキャンセル（結果は反映されない）
          action: SnackBarAction(
            label: provider.t('ai.stop'),
            textColor: const Color(0xFFFF6B6B),
            onPressed: () {
              provider.cancelAi();
              messenger.hideCurrentSnackBar();
              _appSnackM(
                  messenger,
                  SnackBar(
                    content: Text(provider.t('ai.cancelled')),
                    duration: const Duration(seconds: 2),
                    backgroundColor: const Color(0xFF9E9E9E),
                  ));
            },
          ),
        ));

    Future<void> task;
    switch (type) {
      case 'explain':
        task = provider.aiExplainNode(nodeId);
        break;
      case 'children':
        task = provider.aiGenerateChildren(nodeId);
        break;
      case 'custom':
        task = provider.aiCustomPrompt(nodeId, customPrompt ?? '');
        break;
      default:
        return;
    }

    task.then((_) {
      messenger.hideCurrentSnackBar();
      // キャンセル済みの場合は「生成完了」トーストを出さない
      // （「停止」ボタン側で既に停止通知を表示済み）
      if (provider.aiCancelled) return;
      _appSnackM(
          messenger,
          SnackBar(
            content: Row(children: [
              const Icon(Icons.check_circle_rounded,
                  color: Colors.white, size: 18),
              const SizedBox(width: 8),
              Text(provider.t('ai.genDone').replaceFirst('{model}', modelLabel),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 13,
                      fontWeight: FontWeight.w700)),
            ]),
            backgroundColor: const Color(0xFF43B97F),
            duration: const Duration(seconds: 3),
          ));
    }).catchError((e) {
      messenger.hideCurrentSnackBar();
      if (provider.aiCancelled) return;
      _appSnackM(
          messenger,
          SnackBar(
            content: Text(provider.t('ai.error').replaceFirst('{err}', '$e')),
            backgroundColor: Colors.redAccent,
            duration: const Duration(seconds: 4),
          ));
    });
  }

  /// トークン数を読みやすく整形
  static String _compactTokens(int n) {
    if (n < 1000) return '$n';
    if (n < 10000) return '${(n / 1000).toStringAsFixed(1)}K';
    return '${(n / 1000).round()}K';
  }

  /// 設定メニュー（中央ダイアログ）
  /// 言語 / AI / ショートカット / ヘッダーカスタマイズ 等のメタ設定を集約
  ///
  /// [expandBehavior]: true なら「動作設定」 ExpansionTile を最初から展開
  /// した状態で開く (Ctrl+J ショートカットから呼ばれた時用)。
  void _showSettingsSheet(BuildContext ctx, MindMapProvider provider,
      {bool expandBehavior = false}) {
    // ダイアログ寿命に紐づくスクロールコントローラ（1ダイアログ1つ）
    final scrollCtrl = ScrollController();
    // Space キーでトグル開閉するためのフラグ管理。
    // showDialog は Future を返すので、dismissed されたタイミングで flag を
    // 戻す。以降の Space 押下でまた開くように。
    _settingsSheetOpen = true;
    showDialog(
      context: ctx,
      barrierColor: Colors.black54,
      builder: (sctx) => StatefulBuilder(
        builder: (sctx2, setS) {
          // 外 (Space ショートカット) からこのシートだけを確実に閉じる
          // ための関数を登録する (= ユーザー報告: Space から設定が開かない
          // ことがある → 「開いている」 フラグだけ残る事故を防ぐ)。
          _closeSettingsSheet = () {
            final nav = Navigator.of(sctx2);
            if (nav.canPop()) nav.pop();
          };
          // 画面サイズに応じて最大サイズを適応的に決定
          // 以前は 480x640 固定 → 広めに
          final screen = MediaQuery.of(sctx).size;
          final maxW = screen.width.clamp(320.0, 640.0);
          final maxH = (screen.height * 0.90).clamp(420.0, 900.0);
          final baseColor = provider.headerColor;
          final panelColor = Color.alphaBlend(
              baseColor.withValues(
                  alpha: provider.hasCustomHeaderColor ? 0.42 : 0.0),
              const Color(0xFF1E1E32));
          final accentColor = provider.hasCustomHeaderColor
              ? _themeReadableAccent(baseColor)
              : const Color(0xFFBA68C8);
          return Dialog(
            backgroundColor: panelColor,
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(18),
            ),
            insetPadding:
                const EdgeInsets.symmetric(horizontal: 16, vertical: 24),
            // Space キーで設定シートを閉じるためのフォーカス。
            // ダイアログ表示中はメインキャンバスのキーハンドラまで Space が
            // 届かないので、ダイアログ内部でキャッチして自分で閉じる必要がある。
            // テキスト入力中 (TextField にフォーカス) の時はスペースを
            // 「文字入力」として優先したいため、focused=false の時だけ処理。
            child: Focus(
              autofocus: true,
              onKeyEvent: (node, event) {
                if (event is! KeyDownEvent && event is! KeyRepeatEvent)
                  return KeyEventResult.ignored;
                if (event.logicalKey != LogicalKeyboardKey.space) {
                  return KeyEventResult.ignored;
                }
                // 何らかの子 TextField がフォーカスを持っていたら
                // 普通に空白文字として使わせる
                final primary = FocusManager.instance.primaryFocus;
                if (primary != null && primary.context != null) {
                  final ctxW = primary.context!.widget;
                  if (ctxW is EditableText ||
                      primary.context!
                              .findAncestorWidgetOfExactType<EditableText>() !=
                          null) {
                    return KeyEventResult.ignored;
                  }
                }
                // Space でダイアログ閉じる
                Navigator.of(sctx2).pop();
                return KeyEventResult.handled;
              },
              child: ConstrainedBox(
                constraints: BoxConstraints(maxWidth: maxW, maxHeight: maxH),
