    showDialog(
      context: ctx,
      builder: (dctx) => StatefulBuilder(
        builder: (dctx2, setD) => Dialog(
          backgroundColor: const Color(0xFF1E1E32),
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
          insetPadding:
              const EdgeInsets.symmetric(horizontal: 24, vertical: 40),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 420),
            child: Padding(
              padding: const EdgeInsets.fromLTRB(18, 16, 18, 12),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(children: [
                    const Icon(Icons.palette_rounded,
                        color: Color(0xFFFF6B6B), size: 20),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(provider.t('colorCfg.title'),
                          style: const TextStyle(
                              color: Colors.white,
                              fontSize: 15,
                              fontWeight: FontWeight.w700)),
                    ),
                    IconButton(
                      icon: const Icon(Icons.close_rounded,
                          color: Colors.white54, size: 18),
                      onPressed: () => Navigator.pop(dctx),
                    ),
                  ]),
                  const SizedBox(height: 10),
                  // モード選択
                  RadioListTile<String>(
                    value: 'cycle',
                    groupValue: provider.colorMode,
                    onChanged: (v) async {
                      if (v == null) return;
                      await provider.setColorMode(v);
                      setD(() {});
                    },
                    activeColor: const Color(0xFF6C63FF),
                    title: Text(provider.t('colorCfg.cycleMode'),
                        style:
                            const TextStyle(color: Colors.white, fontSize: 13)),
                    dense: true,
                    contentPadding: EdgeInsets.zero,
                  ),
                  RadioListTile<String>(
                    value: 'fixed',
                    groupValue: provider.colorMode,
                    onChanged: (v) async {
                      if (v == null) return;
                      await provider.setColorMode(v);
                      setD(() {});
                    },
                    activeColor: const Color(0xFF6C63FF),
                    title: Text(provider.t('colorCfg.fixedMode'),
                        style:
                            const TextStyle(color: Colors.white, fontSize: 13)),
                    dense: true,
                    contentPadding: EdgeInsets.zero,
                  ),
                  const SizedBox(height: 8),
                  // 固定色 or パレット表示
                  Text(
                    provider.colorMode == 'fixed'
                        ? provider.t('colorCfg.pickFixed')
                        : provider.t('colorCfg.palette'),
                    style: const TextStyle(
                        color: Colors.white60,
                        fontSize: 11,
                        fontWeight: FontWeight.w600),
                  ),
                  const SizedBox(height: 10),
                  // 10色グリッド
                  Wrap(
                    spacing: 10,
                    runSpacing: 10,
                    children: List.generate(
                      MindMapProvider.nodePalette.length,
                      (i) {
                        final c = MindMapProvider.nodePalette[i];
                        final isSelected = provider.colorMode == 'fixed' &&
                            provider.fixedColorIndex == i;
                        return GestureDetector(
                          onTap: provider.colorMode == 'fixed'
                              ? () async {
                                  await provider.setFixedColorIndex(i);
                                  setD(() {});
                                }
                              : null,
                          child: Container(
                            width: 34,
                            height: 34,
                            decoration: BoxDecoration(
                              color: c,
                              shape: BoxShape.circle,
                              border: isSelected
                                  ? Border.all(color: Colors.white, width: 3)
                                  : Border.all(color: Colors.white24, width: 1),
                              boxShadow: isSelected
                                  ? [
                                      BoxShadow(
                                        color: c.withValues(alpha: 0.6),
                                        blurRadius: 8,
                                        spreadRadius: 1,
                                      )
                                    ]
                                  : null,
                            ),
                          ),
                        );
                      },
                    ),
                  ),
                  const SizedBox(height: 14),
                  Align(
                    alignment: Alignment.centerRight,
                    child: TextButton(
                      onPressed: () => Navigator.pop(dctx),
                      child: Text(provider.t('btn.close'),
                          style: const TextStyle(color: Colors.white70)),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }

  Color _themeReadableAccent(Color baseColor) {
    final hsl = HSLColor.fromColor(baseColor);
    final saturation = math.max(0.45, hsl.saturation);
    final lightness = baseColor.computeLuminance() < 0.35 ? 0.72 : 0.34;
    return hsl.withSaturation(saturation).withLightness(lightness).toColor();
  }

  bool _canShowIcCardBalance(MindMapProvider provider) =>
      !kIsWeb && Platform.isAndroid && provider.appLanguage == 'ja';

  bool _hideCommandForCurrentLocale(String? id, MindMapProvider provider) {
    if (id == 'icCardBalance' && !_canShowIcCardBalance(provider)) return true;
    // キーボード前提の一覧はモバイルの表示・追加候補から除外する。
    return id == 'shortcuts' && !_isDesktop;
  }

  Widget _settingsTile({
    required IconData icon,
    required Color color,
    required String title,
    String? subtitle,
    required VoidCallback onTap,
  }) {
    final provider = context.read<MindMapProvider>();
    final baseColor = provider.headerColor;
    final itemColor = color;
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(10),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 12),
        margin: const EdgeInsets.symmetric(vertical: 2),
        decoration: BoxDecoration(
          color: Color.alphaBlend(baseColor.withValues(alpha: 0.22),
              Colors.white.withValues(alpha: 0.04)),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: baseColor.withValues(alpha: 0.28)),
        ),
        child: Row(children: [
          Icon(icon, color: itemColor, size: 20),
          const SizedBox(width: 12),
          Expanded(
            child: Text(title,
                style: const TextStyle(color: Colors.white, fontSize: 14)),
          ),
          if (subtitle != null && subtitle.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(right: 4),
              child: Text(subtitle,
                  style: TextStyle(
                      color: itemColor,
                      fontSize: 12,
                      fontWeight: FontWeight.w600)),
            ),
          const Icon(Icons.chevron_right_rounded,
              color: Colors.white38, size: 18),
        ]),
      ),
    );
  }

  /// 設定シートのプラン・使用状況タイル右側に出す短いラベル。
  /// 例: 'Free 1/2', 'Pro', 'Developer', 'Coupon 100%'
  String _planShortLabel(MindMapProvider provider) {
    final plan = provider.currentPlan;
    // 開発者モード中は「今どのプランを装っているか」が知りたい。 一律 DEV だと
    // Free を試している時も DEV と出て紛らわしかった (= ユーザー要望:
    // 「Free(Dev)」 のように装っているプランを添えて欲しい)。
    if (provider.developerMode) {
      if (plan == SubscriptionPlan.dev) return 'Dev';
      final base = plan == SubscriptionPlan.max
          ? 'Max'
          : (plan == SubscriptionPlan.pro ? 'Pro' : 'Free');
      return '$base (Dev)';
    }
    // Dev プラン (= 決済を通さずに AI が使える枠)。 開発者モードとは別。
    if (plan == SubscriptionPlan.dev) return 'Dev';
    if (plan == SubscriptionPlan.max) return 'Max';
    if (plan == SubscriptionPlan.pro) {
      if (!provider.proSubscribed && provider.hasActiveCoupon) {
        return 'Coupon ${provider.couponDiscountPercent}%';
      }
      return 'Pro';
    }
    if (provider.hasActiveCoupon) {
      return 'Coupon ${provider.couponDiscountPercent}%';
    }
    return 'Free';
  }

  /// プラン・使用状況ダイアログ。
  /// - 現在のプラン (Developer / Pro / Coupon / Free) を大きく表示
  /// - ページ作成枠の使用率 (LinearProgressIndicator)
  /// - お問い合わせ送信枠の今日の使用率
  /// - クーポン適用中なら適用コード + 有効期限
  void _showUsageDialog(BuildContext ctx, MindMapProvider provider) {
    showDialog<void>(
      context: ctx,
      builder: (dctx) => StatefulBuilder(
        builder: (sctx, setD) {
          int? remainingInquiries;
          bool _firstLoad = false;
          // 残り回数を非同期取得 (1 回だけ)
          if (!_firstLoad) {
            _firstLoad = true;
            provider.remainingInquirySendCount().then((n) {
              if (sctx.mounted) {
                setD(() => remainingInquiries = n);
              }
            });
          }

          // ── プラン情報を組み立て ──
          // 開発者モード時は `_devImpersonatePlan` が `currentPlan` に
          // 反映されるので、currentPlan ベースでラベル / 色 / アイコンを決める。
          // ただしクーポン・実 Pro と区別するため isDev フラグも参照。
          final isDev = provider.developerMode;
          final isPro = provider.proSubscribed;
          final isCoupon = provider.hasActiveCoupon;
          final unlimited = provider.hasUnlimitedPages;
          final plan = provider.currentPlan;

          String planLabel;
          Color planColor;
          IconData planIcon;
          if (plan == SubscriptionPlan.dev) {
            // Dev 枠 (引き換えコードで付与)。 Max の全機能 + 決済なしの AI。
            planLabel = 'Dev';
            planColor = const Color(0xFFFFB74D);
            planIcon = Icons.construction_rounded;
          } else if (plan == SubscriptionPlan.max) {
            // 開発者モードで MAX を演じている (実課金は未対応)
            planLabel = provider.t('usage.planMax');
            planColor = const Color(0xFFE91E63);
            planIcon = Icons.diamond_rounded;
          } else if (plan == SubscriptionPlan.pro) {
            // 実 Pro / クーポン / 開発者モードで Pro 演じ → "Pro" 系で表示
            // 実クーポン適用中だけ "クーポン適用中" 表示にする (開発者モード時は除外)
            if (!isDev && isCoupon && !isPro) {
              planLabel = provider.t('usage.planCoupon');
              planColor = const Color(0xFF4FC3F7);
              planIcon = Icons.local_offer_rounded;
            } else {
              planLabel = provider.t('usage.planPro');
              planColor = const Color(0xFFFFB347);
              planIcon = Icons.workspace_premium_rounded;
            }
          } else {
            // free (実無料 / 開発者モードで Free 演じ)
            planLabel = provider.t('usage.planFree');
            planColor = const Color(0xFF9CCC65);
            planIcon = Icons.eco_rounded;
          }
          // 開発者モードで別プランを装っている間は、 装っているプラン名に
          // (Dev) を添える (= ユーザー要望: Free を試している時に Dev とだけ
          // 出るのは分かりにくい)。
          if (isDev && plan != SubscriptionPlan.dev) {
            planLabel = '$planLabel (Dev)';
          }

          // ── アップグレード先 (= ユーザー要望: プランの所に Max への
          //    誘導も出して欲しい)。 無料なら Pro と Max の両方、
          //    Pro なら Max だけを案内する。 ──
          final upgradeTargets = <String>[
            if (plan == SubscriptionPlan.free) 'pro',
            // Dev は既に全機能が開いているので案内しない。
            if (plan != SubscriptionPlan.max && plan != SubscriptionPlan.dev)
              'max',
          ];
          final canUpgrade = upgradeTargets.isNotEmpty;
          final upgradeToMax = plan == SubscriptionPlan.pro;
          final upgradeColor =
              upgradeToMax ? const Color(0xFFBA68C8) : const Color(0xFFFFB347);
          final upgradePrompt = upgradeToMax
              ? provider.t('paywall.maxRequiredGeneric')
              : provider.t('usage.upgradePrompt');

          // ★ 画面に余白があるなら使い切る (= ユーザー要望: Max プランや
          //   クーポン入力まで見えるように)。 題名・タブ・余白の分だけ引く。
          final tabBodyHeight =
              (MediaQuery.of(dctx).size.height - 240).clamp(360.0, 780.0);

          final pagesUsed = provider.pages.length;
          final pageTypesUsed = provider.freePageTypesUsed;
          final pageLimit = MindMapProvider.kFreePageLimit;
          final pagePercent = 0.0;

          final inquiryUsed = remainingInquiries == null
              ? null
              : (remainingInquiries! < 0
                  ? null
                  : MindMapProvider.kInquiryDailyLimit - remainingInquiries!);
          final inquiryLimit = MindMapProvider.kInquiryDailyLimit;
          // ★ 「開発者モードだから無制限」 ではなく、 プロバイダが返した
          //   残量 (-1 = 無制限) をそのまま信じる。 Free を装っている時は
          //   ちゃんと有限で出る (= ユーザー報告)。
          final inquiryUnlimited =
              remainingInquiries != null && remainingInquiries! < 0;
          final inquiryPercent = (inquiryUnlimited || inquiryUsed == null)
              ? 0.0
              : (inquiryUsed / inquiryLimit).clamp(0.0, 1.0);

          // Max / Dev はこれ以上のプランが無いので、 変更タブを出さない
          // (= ユーザー要望)。
          final showPlanTab = !provider.isMaxUnlocked;

          return AlertDialog(
            backgroundColor: const Color(0xFF1E1E1E),
            shape:
                RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
            title: Row(children: [
              const Icon(Icons.donut_small_rounded,
                  color: Color(0xFF9CCC65), size: 22),
              const SizedBox(width: 8),
              Expanded(
                child: Text(provider.t('menu.usage'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 16,
                        fontWeight: FontWeight.w700)),
              ),
              IconButton(
                icon: const Icon(Icons.close, color: Colors.white54, size: 20),
                onPressed: () => Navigator.of(dctx).pop(),
              ),
            ]),
            content: SizedBox(
              // 値段つきのカードを収めるため少し広げる (= ユーザー要望)。
              width: 460,
              // ★ 1 枚に全部積むと「どこを見ればいいか分からない」 ので、
              //   「今の状況」 と「プランを変える」 の 2 つに分ける
              //   (= ユーザー要望)。
              child: DefaultTabController(
                // ── Max / Dev の人には「プランを変える」 を出さない
                //    (= ユーザー要望)。 これ以上のプランが無いので、
                //    出しても行き先が無い。 ──
                length: showPlanTab ? 2 : 1,
                child: Column(mainAxisSize: MainAxisSize.min, children: [
                  if (showPlanTab)
                  Container(
                    decoration: BoxDecoration(
                      color: Colors.white.withValues(alpha: 0.04),
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: TabBar(
                      indicator: BoxDecoration(
                        color: planColor.withValues(alpha: 0.22),
                        borderRadius: BorderRadius.circular(10),
                      ),
                      indicatorSize: TabBarIndicatorSize.tab,
                      dividerColor: Colors.transparent,
                      labelColor: Colors.white,
                      unselectedLabelColor: Colors.white54,
                      labelStyle: const TextStyle(
                          fontSize: 12.5, fontWeight: FontWeight.w700),
                      unselectedLabelStyle: const TextStyle(fontSize: 12.5),
                      tabs: [
                        Tab(height: 38, text: provider.t('usage.tabStatus')),
                        Tab(height: 38, text: provider.t('usage.tabPlans')),
                      ],
                    ),
                  ),
                  if (showPlanTab) const SizedBox(height: 12),
                  // 中身の高さに合わせて縮む (= ユーザー要望: 余白があるなら
                  //   伸ばして全部入れる / 逆に短い側で間延びさせない)。
                  ConstrainedBox(
                    constraints: BoxConstraints(maxHeight: tabBodyHeight),
                    child: _AutoHeightTabBarView(children: [
                      // ── ① 今の状況 ──
                      SingleChildScrollView(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          mainAxisSize: MainAxisSize.min,
                          children: [
                    // ─── 現在のプラン ───
                    Container(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 14, vertical: 14),
                      decoration: BoxDecoration(
                        color: planColor.withValues(alpha: 0.1),
                        borderRadius: BorderRadius.circular(10),
                        border: Border.all(
                            color: planColor.withValues(alpha: 0.5),
                            width: 1.5),
                      ),
                      child: Row(children: [
                        Icon(planIcon, color: planColor, size: 28),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(provider.t('usage.currentPlan'),
                                    style: const TextStyle(
                                        color: Colors.white54, fontSize: 11)),
                                const SizedBox(height: 2),
                                Text(planLabel,
                                    style: TextStyle(
                                        color: planColor,
                                        fontSize: 18,
                                        fontWeight: FontWeight.w700)),
                              ]),
                        ),
                      ]),
                    ),

                    // ─── クーポン詳細 (適用中の時) ───
                    if (isCoupon && !isDev) ...[
                      const SizedBox(height: 10),
                      Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 12, vertical: 10),
                        decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.03),
                            borderRadius: BorderRadius.circular(8)),
                        child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                provider
                                    .t('usage.couponInfo')
                                    .replaceAll('{code}',
                                        provider.appliedCouponCode ?? '-')
                                    .replaceAll('{percent}',
                                        '${provider.couponDiscountPercent}'),
                                style: const TextStyle(
                                    color: Color(0xFF4FC3F7),
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600),
                              ),
                              if (provider.couponExpiry != null) ...[
                                const SizedBox(height: 4),
                                Text(
                                  provider.t('usage.couponExpiry').replaceAll(
                                      '{date}',
                                      provider.couponExpiry!
                                          .toIso8601String()
                                          .substring(0, 10)),
                                  style: const TextStyle(
                                      color: Colors.white54, fontSize: 11),
                                ),
                              ],
                            ]),
                      ),
                    ],

                    // ─── 契約中のサブスク (= ユーザー要望: Google アカウント
                    //     から契約中のサブスクを表示して、 アプリから解約) ───
                    // Google ログイン中の uid で課金サーバーに照会し、 状態と
                    // 次回請求日を出して、 その場で解約 / 取り消しができる。
                    const SizedBox(height: 10),
                    _SubscriptionPanel(provider: provider),

                    // ─── サブスクリプションの管理・解約 (ストアのページ) ───
                    // 支払い方法の変更・返金の相談・Play の購入はストア側で。
                    // Android: Play の購入は端末の Google アカウントに必ず
                    //   紐づくので、 Play ストアの「定期購入」 からいつでも
                    //   解約できる (RevenueCat managementURL で直行)。
                    // Windows: Stripe のカスタマーポータル (購入時のメール
                    //   アドレスでログイン) で解約・カード変更ができる。
                    const SizedBox(height: 10),
                    Container(
                      decoration: BoxDecoration(
                        color: const Color(0xFF80CBC4).withValues(alpha: 0.07),
                        borderRadius: BorderRadius.circular(8),
                        border: Border.all(
                            color:
                                const Color(0xFF80CBC4).withValues(alpha: 0.3)),
                      ),
                      child: InkWell(
                        borderRadius: BorderRadius.circular(8),
                        onTap: () async {
                          final ok =
                              await provider.billing.openManagementPage();
                          if (!ok && sctx.mounted) {
                            showDialog<void>(
                              context: sctx,
                              builder: (mctx) => AlertDialog(
                                backgroundColor: const Color(0xFF1E1E1E),
                                title: Text(provider.t('usage.manageSub'),
                                    style: const TextStyle(
                                        color: Colors.white, fontSize: 15)),
                                content: Text(
                                    provider.t('usage.manageSubFailed'),
                                    style: const TextStyle(
                                        color: Colors.white70,
                                        fontSize: 13,
                                        height: 1.5)),
                                actions: [
                                  TextButton(
                                    onPressed: () => Navigator.of(mctx).pop(),
                                    child: Text(provider.t('btn.close'),
                                        style: const TextStyle(
                                            color: Colors.white60)),
                                  ),
                                ],
                              ),
                            );
                          }
                        },
                        child: Padding(
                          padding: const EdgeInsets.all(10),
                          child: Row(children: [
                            const Icon(Icons.manage_accounts_rounded,
                                color: Color(0xFF80CBC4), size: 18),
                            const SizedBox(width: 8),
                            Expanded(
                              child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(provider.t('usage.manageSub'),
                                        style: const TextStyle(
                                            color: Color(0xFF80CBC4),
                                            fontSize: 12,
                                            fontWeight: FontWeight.w700)),
                                    const SizedBox(height: 2),
                                    Text(provider.t('usage.manageSubDesc'),
                                        style: const TextStyle(
                                            color: Colors.white54,
                                            fontSize: 10.5,
                                            height: 1.4)),
                                  ]),
                            ),
                            const Icon(Icons.open_in_new_rounded,
                                color: Color(0xFF80CBC4), size: 16),
                          ]),
                        ),
                      ),
                    ),

                    const SizedBox(height: 18),

                    // ─── ページ作成枠 ───
                    _usageRow(
                      label: provider.t('usage.pages'),
                      detail: unlimited
                          ? provider
                              .t('usage.pagesUnlimited')
                              .replaceAll('{used}', '$pagesUsed')
                          : provider
                              .t('usage.pagesUsed')
                              .replaceAll('{used}', '$pageTypesUsed')
                              .replaceAll('{limit}', '$pageLimit'),
                      percent: pagePercent,
                      unlimited: unlimited,
                      barColor: const Color(0xFF9CCC65),
                    ),

                    const SizedBox(height: 14),

                    // ─── お問い合わせ送信枠 ───
                    _usageRow(
                      label: provider.t('usage.inquiries'),
                      detail: inquiryUnlimited
                          ? provider.t('usage.inquiriesUnlimited')
                          : (remainingInquiries == null)
                              ? '...'
                              : provider
                                  .t('usage.inquiriesUsed')
                                  .replaceAll('{used}', '${inquiryUsed ?? 0}')
                                  .replaceAll('{limit}', '$inquiryLimit'),
                      percent: inquiryPercent,
                      unlimited: inquiryUnlimited,
                      barColor: (remainingInquiries ?? 1) == 0
                          ? Colors.redAccent
                          : const Color(0xFF4FC3F7),
                    ),

                    const SizedBox(height: 14),
                    // ─── クラウド同期は Max 限定 ───
                    // Free / Pro では同期そのものが使えないので、 使用量の帯を
                    //   出すと「少しは使える」 と誤解させる。 案内 1 行に置き換える
                    //   (= ユーザー指摘: Free/Pro はアップロードできないはず)。
                    if (!provider.isMaxUnlocked && !provider.isStorageUnlimited)
                      Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 12, vertical: 10),
                        decoration: BoxDecoration(
                          color: const Color(0xFFBA68C8).withValues(alpha: 0.12),
                          borderRadius: BorderRadius.circular(8),
                          border: Border.all(
                              color: const Color(0xFFBA68C8)
                                  .withValues(alpha: 0.4)),
                        ),
                        child: Row(children: [
                          const Icon(Icons.cloud_off_rounded,
                              size: 16, color: Color(0xFFBA68C8)),
                          const SizedBox(width: 8),
                          Expanded(
                            child: Text(provider.t('cloud.maxOnly'),
                                style: const TextStyle(
                                    color: Colors.white70,
                                    fontSize: 11.5,
                                    height: 1.4)),
                          ),
                        ]),
                      ),
                    // ─── クラウド アップロード (今月) (= ユーザー要望: 使用量表示) ───
                    if (provider.isMaxUnlocked || provider.isStorageUnlimited)
                    _usageRow(
                      label: provider.t('cloud.uploadMonth'),
                      detail: provider.isStorageUnlimited
                          ? '${_formatBytes(provider.monthlyUploadBytes)} / 無制限'
                          : '${_formatBytes(provider.monthlyUploadBytes)} / ${_formatBytes(provider.monthlyUploadLimit)}',
                      percent: provider.isStorageUnlimited ||
                              provider.monthlyUploadLimit <= 0
                          ? 0.0
                          : (provider.monthlyUploadBytes /
                                  provider.monthlyUploadLimit)
                              .clamp(0.0, 1.0),
                      unlimited: provider.isStorageUnlimited,
                      barColor: provider.monthlyUploadRemaining <= 0 &&
                              !provider.isStorageUnlimited
                          ? Colors.redAccent
                          : const Color(0xFF66BB6A),
                    ),
                    if (provider.isMaxUnlocked || provider.isStorageUnlimited)
                      const SizedBox(height: 14),
                    // ─── クラウド ダウンロード (今月) ───
                    if (provider.isMaxUnlocked || provider.isStorageUnlimited)
                    _usageRow(
                      label: provider.t('cloud.downloadMonth'),
                      detail: provider.isStorageUnlimited
                          ? '${_formatBytes(provider.monthlyDownloadBytes)} / 無制限'
                          : '${_formatBytes(provider.monthlyDownloadBytes)} / ${_formatBytes(provider.monthlyDownloadLimit)}',
                      percent: provider.isStorageUnlimited ||
                              provider.monthlyDownloadLimit <= 0
                          ? 0.0
                          : (provider.monthlyDownloadBytes /
                                  provider.monthlyDownloadLimit)
                              .clamp(0.0, 1.0),
                      unlimited: provider.isStorageUnlimited,
                      barColor: provider.monthlyDownloadRemaining <= 0 &&
                              !provider.isStorageUnlimited
                          ? Colors.redAccent
                          : const Color(0xFF4FC3F7),
                    ),
                    if (provider.isMaxUnlocked || provider.isStorageUnlimited)
                      const SizedBox(height: 14),
                    // ─── クラウド保存容量 (累積) ───
                    if (provider.isMaxUnlocked || provider.isStorageUnlimited)
                    _usageRow(
                      label: provider.t('cloud.storage'),
                      detail: provider.isStorageUnlimited
                          ? '${_formatBytes(provider.totalStorageBytes)} / 無制限'
                          : '${_formatBytes(provider.totalStorageBytes)} / ${_formatBytes(provider.totalStorageLimit)}',
                      percent: provider.isStorageUnlimited ||
                              provider.totalStorageLimit <= 0
                          ? 0.0
                          : (provider.totalStorageBytes /
                                  provider.totalStorageLimit)
                              .clamp(0.0, 1.0),
                      unlimited: provider.isStorageUnlimited,
                      barColor: provider.totalStorageRemaining <= 0 &&
                              !provider.isStorageUnlimited
                          ? Colors.redAccent
                          : const Color(0xFFBA68C8),
                    ),

                          ],
                        ),
                      ),
                      // ── ② プランを変える (Max / Dev では出さない) ──
                      if (showPlanTab)
                      SingleChildScrollView(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          mainAxisSize: MainAxisSize.min,
                          children: [
                    // ─── アップグレード案内 ───
                    if (canUpgrade) ...[
                      const SizedBox(height: 18),
                      Container(
                        padding: const EdgeInsets.all(10),
                        decoration: BoxDecoration(
                            color: upgradeColor.withValues(alpha: 0.08),
                            borderRadius: BorderRadius.circular(8),
                            border: Border.all(
                                color: upgradeColor.withValues(alpha: 0.3))),
                        child: Row(children: [
                          Icon(Icons.info_outline_rounded,
                              color: upgradeColor, size: 14),
                          const SizedBox(width: 6),
                          Expanded(
                            child: Text(upgradePrompt,
                                style: TextStyle(
                                    color: upgradeColor,
                                    fontSize: 11,
                                    height: 1.4)),
                          ),
                        ]),
                      ),
                      const SizedBox(height: 12),
                      // ─── 何が解放されるか (= ユーザー要望: ちゃんと
                      //     説明書きが欲しい) ───
                      _buildPlanFeatureSummary(provider),
                      const SizedBox(height: 12),
                      // ─── 値段つきの購入カード (= ユーザー要望: ここでも
                      //     月額・年額を出す) ───
                      //     デスクトップは Stripe のカードをそのまま出し、
                      //     決済リンクが無い環境 (モバイル等) は今までの
                      //     ボタンで購入シートを開く。
                      if (_isDesktop && provider.billing.hasStripeLinks)
                        _buildStripePlanCards(
                          provider,
                          plans: upgradeTargets,
                          onTapBefore: () => Navigator.of(dctx).pop(),
                        )
                      else
                        for (int i = 0; i < upgradeTargets.length; i++)
                          Padding(
                            padding: EdgeInsets.only(
                                bottom: i == upgradeTargets.length - 1 ? 0 : 8),
                            child: _buildUpgradeCta(
                              provider,
                              upgradeTargets[i],
                              onTap: () {
                                Navigator.of(dctx).pop();
                                _showPurchaseSheet(provider,
                                    focusPlan: upgradeTargets[i]);
                              },
                            ),
                          ),
                    ],

                    // ─── クーポン入力ボタン ───
                    // 無料プラン / クーポン適用中ユーザーの両方に対して、
                    // 「コードを入力 / 別のコードに切り替え」のアクセス手段を
                    // 設定 (= 親の設定シート) を経由せず提供する。実 Pro / 開発者
                    // モードの時も残しておく (将来別タイプのクーポンが
                    // 追加された時の汎用エントリ)。
                    const SizedBox(height: 14),
                    Container(
                      decoration: BoxDecoration(
                        color: const Color(0xFF4FC3F7).withValues(alpha: 0.08),
                        borderRadius: BorderRadius.circular(8),
                        border: Border.all(
                            color:
                                const Color(0xFF4FC3F7).withValues(alpha: 0.3)),
                      ),
                      child: InkWell(
                        borderRadius: BorderRadius.circular(8),
                        onTap: () {
                          Navigator.of(dctx).pop();
                          _showCouponEntryDialog(provider);
                        },
                        child: Padding(
                          padding: const EdgeInsets.all(10),
                          child: Row(children: [
                            const Icon(Icons.local_offer_rounded,
                                color: Color(0xFF4FC3F7), size: 16),
                            const SizedBox(width: 8),
                            Expanded(
                              child: Text(
                                isCoupon
                                    ? provider.t('usage.changeCoupon')
                                    : provider.t('usage.enterCoupon'),
                                style: const TextStyle(
                                    color: Color(0xFF4FC3F7),
                                    fontSize: 12,
                                    fontWeight: FontWeight.w700),
                              ),
                            ),
                            const Icon(Icons.chevron_right_rounded,
                                color: Color(0xFF4FC3F7), size: 18),
                          ]),
                        ),
                      ),
                    ),
                          ],
                        ),
                      ),
                    ]),
                  ),
                ]),
              ),
            ),
          );
        },
      ),
    );
  }

  /// 使用状況の 1 行 (タイトル + 進捗バー + 詳細テキスト)
  /// バイト数を MB / GB で読みやすく整形する (= ユーザー要望: 使用量表示)。
  String _formatBytes(int b) {
    if (b >= 1024 * 1024 * 1024) {
      return '${(b / 1024 / 1024 / 1024).toStringAsFixed(2)} GB';
    }
    if (b >= 1024 * 1024) {
      return '${(b / 1024 / 1024).toStringAsFixed(1)} MB';
    }
    if (b >= 1024) return '${(b / 1024).toStringAsFixed(0)} KB';
    return '$b B';
  }

  Widget _usageRow({
    required String label,
    required String detail,
    required double percent,
    required bool unlimited,
    required Color barColor,
  }) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Row(children: [
          Expanded(
            child: Text(label,
                style: const TextStyle(
                    color: Colors.white,
                    fontSize: 13,
                    fontWeight: FontWeight.w600)),
          ),
          Text(detail,
              style: TextStyle(
                  color: barColor, fontSize: 11, fontWeight: FontWeight.w600)),
        ]),
        const SizedBox(height: 6),
        ClipRRect(
          borderRadius: BorderRadius.circular(4),
          child: LinearProgressIndicator(
            // unlimited 時に value を null にすると LinearProgressIndicator が
            // インディターミネート (永久ループ) アニメに切り替わってしまう。
            // Pro/Max ユーザーには「枠が既に開放済み」を伝えたいので、
            // 1.0 を渡してフルバーで静止させる。これによりページ無制限・
            // バグ報告無制限の行で読み込みバーが回り続けるのを防ぐ。
            value: unlimited ? 1.0 : percent,
            minHeight: 6,
            backgroundColor: Colors.white.withValues(alpha: 0.06),
            valueColor: AlwaysStoppedAnimation<Color>(barColor),
          ),
        ),
      ],
    );
  }

  /// 設定シート用トグル行（配置候補・視聴済み自動削除など）
  /// 設定項目の説明を出すダイアログ (= ユーザー要望: 「連番タイトル
  /// オートフィル」 「配置候補」 「関連動画を隠す」 等がどこの話なのか
  /// 分からないので、 隣に説明を開くボタンを付ける)。
  /// [anchor] を渡すと、 画面の真ん中ではなく押したボタンのすぐ近くに出す
  /// (= ユーザー要望: 説明文は見やすいようにボタンの近くに)。
  void _showSettingHelp(String title, String bodyKey, {Rect? anchor}) {
    final provider = context.read<MindMapProvider>();
    const size = Size(360, 260);
    showDialog<void>(
      context: context,
      barrierColor: Colors.black.withValues(alpha: anchor == null ? 0.5 : 0.25),
      builder: (dctx) => _positionNearAnchor(
        dctx,
        anchor,
        Material(
          color: const Color(0xFF1E1E32),
          elevation: 14,
          borderRadius: BorderRadius.circular(14),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 360, maxHeight: 420),
            child: Padding(
              padding: const EdgeInsets.fromLTRB(16, 14, 12, 8),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(children: [
                    const Icon(Icons.help_outline_rounded,
                        color: Color(0xFF4FC3F7), size: 19),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(title,
                          style: const TextStyle(
                              color: Colors.white,
                              fontSize: 14.5,
                              fontWeight: FontWeight.w700)),
                    ),
                  ]),
                  const SizedBox(height: 8),
                  Flexible(
                    child: SingleChildScrollView(
                      child: Text(provider.t(bodyKey),
                          style: const TextStyle(
                              color: Colors.white70,
                              fontSize: 12.5,
                              height: 1.55)),
                    ),
                  ),
                  Align(
                    alignment: Alignment.centerRight,
                    child: TextButton(
                      onPressed: () => Navigator.pop(dctx),
                      child: Text(provider.t('btn.close'),
                          style: const TextStyle(color: Color(0xFF4FC3F7))),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
        size,
        // 設定シートの中から開くので、 バーを避ける仕組みは使わない。
        useLastBar: false,
      ),
    );
  }

  /// 説明ボタン (ⓘ)。 [helpKey] が null なら何も出さない。
  Widget _settingHelpButton(String title, String? helpKey) {
    if (helpKey == null) return const SizedBox.shrink();
    // 押したボタンの位置を測って、 説明をその近くに出す (= ユーザー要望)。
    final key = GlobalKey();
    return IconButton(
      key: key,
      padding: EdgeInsets.zero,
      visualDensity: VisualDensity.compact,
      constraints: const BoxConstraints(minWidth: 26, minHeight: 26),
      icon: const Icon(Icons.help_outline_rounded,
          color: Colors.white38, size: 16),
      tooltip: context.read<MindMapProvider>().t('settings.whatIsThis'),
      onPressed: () =>
          _showSettingHelp(title, helpKey, anchor: _rectOfContext(key.currentContext)),
    );
  }

  Widget _settingsToggleTile({
    required IconData icon,
    required Color color,
    required String title,
    required bool value,
    required ValueChanged<bool> onChanged,
    // 隣に「説明を開く」 ボタンを出す翻訳キー (= ユーザー要望)。
    String? helpKey,
  }) {
    final provider = context.read<MindMapProvider>();
    final baseColor = provider.headerColor;
    final itemColor = color;
    return InkWell(
      onTap: () => onChanged(!value),
      borderRadius: BorderRadius.circular(10),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
        margin: const EdgeInsets.symmetric(vertical: 2),
        decoration: BoxDecoration(
          color: Color.alphaBlend(baseColor.withValues(alpha: 0.22),
              Colors.white.withValues(alpha: 0.04)),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: baseColor.withValues(alpha: 0.28)),
        ),
        child: Row(children: [
          Icon(icon, color: itemColor, size: 20),
          const SizedBox(width: 12),
          Expanded(
            child: Text(title,
                style: const TextStyle(color: Colors.white, fontSize: 14)),
