  /// ヘッダーカスタマイズ（ドラッグしてヘッダーに配置できるボタン一覧）
  /// ヘッダー (AppBar) の背景色を選ぶ (= ユーザー要望: ヘッダーの色を変えたり
  /// カスタマイズできる機能)。 ヘッダータイトルを長押しで開く。
  void _showHeaderColorPicker(MindMapProvider provider) {
    const palette = <Color>[
      Color(0xFF1A1A2E), // デフォルト (濃紺)
      Color(0xFF12121C), // ほぼ黒
      Color(0xFF263238), // ブルーグレー
      Color(0xFF1B3A2E), // 深緑
      Color(0xFF1B2A4A), // 紺青
      Color(0xFF311B4A), // 紫
      Color(0xFF4A1B2B), // ワイン
      Color(0xFF4A2B1B), // 茶
      Color(0xFF0F2A2A), // ティール
      Color(0xFF3A1B2E), // 赤紫
      Color(0xFF2E2A1B), // カーキ
      Color(0xFF333333), // グレー
    ];
    showDialog<void>(
      context: context,
      builder: (dctx) {
        final panelColor = Color.alphaBlend(
            provider.headerColor
                .withValues(alpha: provider.hasCustomHeaderColor ? 0.42 : 0.0),
            const Color(0xFF1E1E32));
        final accentColor = provider.hasCustomHeaderColor
            ? _themeReadableAccent(provider.headerColor)
            : const Color(0xFF4FC3F7);
        return AlertDialog(
          backgroundColor: panelColor,
          title: Text(provider.t('hdr.color'),
              style: const TextStyle(color: Colors.white, fontSize: 16)),
          content: SizedBox(
            width: 320,
            child: Wrap(
              spacing: 10,
              runSpacing: 10,
              children: [
                for (final c in palette)
                  GestureDetector(
                    onTap: () {
                      provider.setHeaderColor(c.toARGB32());
                      Navigator.pop(dctx);
                    },
                    child: Container(
                      width: 44,
                      height: 44,
                      decoration: BoxDecoration(
                        color: c,
                        borderRadius: BorderRadius.circular(8),
                        border: Border.all(
                          color: provider.headerColor.toARGB32() == c.toARGB32()
                              ? const Color(0xFF4FC3F7)
                              : Colors.white24,
                          width: provider.headerColor.toARGB32() == c.toARGB32()
                              ? 2.5
                              : 1,
                        ),
                      ),
                    ),
                  ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.close'),
                  style: TextStyle(color: accentColor)),
            ),
          ],
        );
      },
    );
