  Future<void> _showDesktopHeaderBarCollisionModePicker(
      BuildContext ctx, MindMapProvider provider) async {
    final current = provider.desktopHeaderBarCollisionMode;
    final selected = await showDialog<String>(
      context: ctx,
      barrierColor: Colors.black54,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: Text(
          provider.t('header.barCollisionBehavior'),
          style: const TextStyle(color: Colors.white, fontSize: 16),
        ),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            for (final mode in const ['ask', 'merge', 'swap'])
              ListTile(
                contentPadding: EdgeInsets.zero,
                leading: Icon(
                  mode == current
                      ? Icons.radio_button_checked_rounded
                      : Icons.radio_button_off_rounded,
                  color: mode == current
                      ? const Color(0xFF8D86FF)
                      : Colors.white38,
                ),
                title: Text(
                  provider.t('header.barCollisionMode.$mode'),
                  style: const TextStyle(color: Colors.white, fontSize: 13),
                ),
                subtitle: Text(
                  provider.t('header.barCollisionMode.${mode}Hint'),
                  style: const TextStyle(color: Colors.white54, fontSize: 11),
                ),
                onTap: () => Navigator.pop(dialogContext, mode),
              ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: Text(provider.t('focusLock.cancel')),
          ),
        ],
      ),
    );
    if (selected != null) {
      await provider.setDesktopHeaderBarCollisionMode(selected);
    }
  }

  void _showHeaderCustomizeSheet(BuildContext ctx, MindMapProvider provider) {
    // ── 全ページ種別で同じヘッダーボタン構成を使う ──
    // 旧仕様はギャラリー等 (normal 以外) を専用リスト (galleryHeaderButtons)
    //   で独立管理していたが、「マインドマップとフリーノートやギャラリーで
    //   ヘッダーのボタンを揃えて欲しい」 (= ユーザー要望 2026-07) に従い、
    //   どのページから開いても共通の customHeaderButtons を編集する。
    List<String> hcbList() => provider.customHeaderButtons;
    // 追加時に「これから追加するボタンの配置先」 を適用する (= ユーザー要望)。
    Future<void> hcbAdd(String id) async {
      await provider.addHeaderButton(id);
      if (_isDesktop) {
        await provider.setDesktopHeaderButtonPlacementFor(
            id, _hcbTargetPlacement);
        // ── 配置先のバーは自動で出す (= ユーザー要望: 「バーを表示する端」
        //    という別項目があると混乱するので消し、 配置先を選ぶだけで
        //    そこにバーが出るようにした) ──
        await provider.setDesktopHeaderDockEnabled(_hcbTargetPlacement, true);
      }
    }

    Future<void> hcbRemove(String id) => provider.removeHeaderButton(id);
    Future<void> hcbReorder(int o, int n) =>
        provider.reorderHeaderButtons(o, n);
    // ダイアログ寿命に合わせて 1 つの ScrollController を作る。
    // 「ヘッダーに表示中」 リストの RawScrollbar とその子 SingleChildScrollView
    // で共有することで、 サムが常時表示される。
    final ScrollController hcsScrollCtrl = ScrollController();
    // ── 配置済みリストの高さ (画面高に対する割合)。 境界のドラッグで変更
    //    できる (= ユーザー要望)。 前回の値を prefs から読み込む。 ──
    if (_hcbPlacedFrac <= 0) {
      // ignore: discarded_futures
      SharedPreferences.getInstance().then((sp) {
        final v = sp.getDouble('hdrCustPlacedFrac');
        if (v != null && v > 0) {
          _hcbPlacedFrac = v.clamp(0.12, 0.68).toDouble();
        }
      });
    }
    // ── Ctrl / Shift でまとめて選択して追加する状態 (= ユーザー要望) ──
    //   候補チップを Ctrl(個別トグル)/Shift(範囲) で複数選択し、「まとめて追加」で
    //   一度にバーへ送れるようにする。 StatefulBuilder の setS をまたいで保持
    //   したいのでダイアログ寿命のローカル変数に置く。
    final Set<String> multiSelIds = <String>{};
    String? multiSelAnchor;
    showDialog(
      context: ctx,
      barrierColor: Colors.black54,
      builder: (sctx) => StatefulBuilder(
        builder: (sctx2, setS) {
          // 画面サイズに応じてダイアログの上限を決める（縦長モバイル対応）
          final screen = MediaQuery.of(sctx).size;
          final maxW = screen.width.clamp(320.0, 560.0);
          // 高さは固定にする (下の ConstrainedBox 参照) ので、 極端に低い
          // ウィンドウでもはみ出さないよう insetPadding (上下 24) を引いた
          // 実利用可能高さで必ず頭打ちにする。
          final maxH = math.min(
            (screen.height * 0.90).clamp(480.0, 900.0).toDouble(),
            math.max(240.0, screen.height - 48),
          );
          final baseColor = provider.headerColor;
          final panelColor = Color.alphaBlend(
              baseColor.withValues(
                  alpha: provider.hasCustomHeaderColor ? 0.42 : 0.0),
              const Color(0xFF1E1E32));
          final accentColor = provider.hasCustomHeaderColor
              ? _themeReadableAccent(baseColor)
              : const Color(0xFFFFB347);
          return Focus(
            autofocus: true,
            // ── Esc は「まとめ選択中」 のときは選択解除だけ (= ユーザー要望:
            //    Esc で項目自体が閉じてしまうのを、 選択モードの解除だけに) ──
            //    選択が無ければ既定どおりダイアログを閉じる。
            onKeyEvent: (node, event) {
              if (event is KeyDownEvent &&
                  event.logicalKey == LogicalKeyboardKey.escape &&
                  multiSelIds.isNotEmpty) {
                setS(() {
                  multiSelIds.clear();
                  multiSelAnchor = null;
                });
                return KeyEventResult.handled;
              }
              return KeyEventResult.ignored;
            },
            child: Dialog(
            backgroundColor: panelColor,
            shape:
                RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),
            insetPadding:
                const EdgeInsets.symmetric(horizontal: 16, vertical: 24),
            child: ConstrainedBox(
              // 高さを固定 (min == max) にする (= ユーザー要望: ボタンを 1 個
              // 削除するたびにダイアログ自体が縮んで中央寄せし直され、 全体が
              // ずれて同じ位置を連打できなかった)。 高さが変わらなければ
              // 削除ボタンの座標も動かない。
              constraints: BoxConstraints(
                maxWidth: maxW,
                minHeight: maxH,
                maxHeight: maxH,
              ),
              child: Padding(
                padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
                child: Builder(builder: (innerCtx) {
                  // ── 追加可能なボタン候補を先に算出 ──
                  // 「ヘッダーに既に追加済み」「モバイル不要 (shortcuts)」を
                  // 除外したリスト。候補数で UI の出し分け / 領域サイズを
                  // 決めるため、Wrap の手前で計算しておく。
                  final availableCmds = _headerCustomizableCommands
                      .where((c) => !hcbList().contains(c['id']))
                      .where(
                          (c) => !_isRetiredCustomCommand(c['id'] as String?))
                      // 統合済みの旧ボタン ('legacy') は新規追加候補に出さない
                      // (= ユーザー要望: メンバー予定表は予定表に合体)。
                      .where((c) => c['legacy'] != true)
                      // IC カード残高は FeliCa/NFC を使うため Android 版のみ
                      //   かつ日本語設定時だけ表示する。
                      .where((c) => !_hideCommandForCurrentLocale(
                          c['id'] as String?, provider))
                      // ── ユーザー要望: 同じボタンを上下バーに重複配置
                      //    できないように、 下部バー (customBottomButtons) に
                      //    既にあるコマンドもヘッダー候補から除外 ──
                      // ただしデスクトップではモバイル下部バーを使わないので、
                      //   下部バーの既定 (openYoutube/cutMode/calendar/sync/addPage)
                      //   が原因でヘッダー候補から消えてしまう不具合があった。
                      //   デスクトップではこの除外を行わない (= YouTube 等が
                      //   ヘッダーのカスタマイズ候補に戻る)。
                      .where((c) =>
                          _isDesktop ||
                          !provider.customBottomButtons.contains(c['id']))
                      .where((c) => _isDesktop || c['id'] != 'shortcuts')
                      // 開発者モード限定項目 (`devOnly: true`) は、
                      // 開発者モード ON の時だけ追加候補に出す。
                      // OFF のユーザーには項目自体を見せない。
                      .where(
                          (c) => c['devOnly'] != true || provider.developerMode)
                      // 画面ロック / 集中ロック / 下部ボタン格納 /
                      //   フローティングメモはモバイル専用
                      //   (= ユーザー要望: Windows のカスタマイズ候補から外す)。
                      .where((c) =>
                          !_isDesktop ||
                          (c['id'] != 'appLock' &&
                              c['id'] != 'focusLock' &&
                              c['id'] != 'toggleBottomBar' &&
                              // フローティングメモはデスクトップでも
                              // 使えるようになったので除外しない
                              // (= ユーザー要望)。
                              true))
                      .toList();
                  // ── 追加候補を「表示順」で平坦化 (Ctrl/Shift の範囲選択 &
                  //    まとめ追加用)。 下のカテゴリ別セクションと同じ並び順で
                  //    id を集める。 ──
                  final flatAvailableIds = <String>[];
                  {
                    final byIdFlat = <String, Map<String, dynamic>>{
                      for (final c in availableCmds) c['id'] as String: c
                    };
                    final categorizedFlat = <String>{};
                    for (final cat in _headerButtonCategories) {
                      categorizedFlat
                          .addAll(cat['commandIds'] as List<String>);
                    }
                    for (final cat in _headerButtonCategories) {
                      final base = List<String>.from(
                          cat['commandIds'] as List<String>);
                      if (cat['id'] == 'other') {
                        for (final c in availableCmds) {
                          final id = c['id'] as String;
                          if (!categorizedFlat.contains(id) &&
                              !base.contains(id)) {
                            base.add(id);
                          }
                        }
                      }
                      for (final id in base) {
                        if (byIdFlat.containsKey(id)) {
                          flatAvailableIds.add(id);
                        }
                      }
                    }
                  }
                  // 候補チップのタップ処理。 Ctrl(個別トグル)/Shift(範囲) 押下時は
                  //   まとめ選択に入れ、 修飾キー無しは従来通り 1 個だけ即追加。
                  void handleCandidateTap(String id) {
                    final keys = HardwareKeyboard.instance.logicalKeysPressed;
                    final bool ctrlHeld = keys.contains(
                            LogicalKeyboardKey.controlLeft) ||
                        keys.contains(LogicalKeyboardKey.controlRight) ||
                        keys.contains(LogicalKeyboardKey.metaLeft) ||
                        keys.contains(LogicalKeyboardKey.metaRight);
                    final bool shiftHeld =
                        keys.contains(LogicalKeyboardKey.shiftLeft) ||
                            keys.contains(LogicalKeyboardKey.shiftRight);
                    if (ctrlHeld || shiftHeld) {
                      if (shiftHeld && multiSelAnchor != null) {
                        final a = flatAvailableIds.indexOf(multiSelAnchor!);
                        final b = flatAvailableIds.indexOf(id);
                        if (a >= 0 && b >= 0) {
                          final lo = a < b ? a : b;
                          final hi = a < b ? b : a;
                          for (int k = lo; k <= hi; k++) {
                            multiSelIds.add(flatAvailableIds[k]);
                          }
                        } else {
                          multiSelIds.add(id);
                        }
                      } else {
                        // Ctrl: 個別トグル
                        if (!multiSelIds.remove(id)) multiSelIds.add(id);
                      }
                      multiSelAnchor = id;
                      setS(() {});
                      return;
                    }
                    // 修飾キー無し = 従来通り 1 個だけ即追加。
                    multiSelIds.remove(id);
                    hcbAdd(id).then((_) {
                      if (mounted) setS(() {});
                    });
                  }

                  return Column(
                    // ダイアログ高さは固定になったので、 Column も高さいっぱいを
                    // 使い、 余りは「追加できるボタン」エリア (Expanded) が
                    // 吸収する。 これで項目の増減があってもレイアウトが動かない。
                    mainAxisSize: MainAxisSize.max,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Row(children: [
                        Icon(Icons.dashboard_customize_rounded,
                            color: accentColor, size: 22),
                        const SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            provider.t('header.customizeTitle'),
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 15,
                                fontWeight: FontWeight.w700),
                          ),
                        ),
                      ]),
                      const SizedBox(height: 4),
                      Text(provider.t('header.emptyHint'),
                          style: const TextStyle(
                              color: Colors.white54, fontSize: 11)),
                      const SizedBox(height: 14),

                      Text(provider.t('hdr.color'),
                          style: const TextStyle(
                              color: Colors.white70,
                              fontSize: 12,
                              fontWeight: FontWeight.w600)),
                      const SizedBox(height: 8),
                      Container(
                        padding: const EdgeInsets.all(10),
                        decoration: BoxDecoration(
                          color: Colors.white.withValues(alpha: 0.04),
                          borderRadius: BorderRadius.circular(10),
                        ),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Wrap(
                              spacing: 8,
                              runSpacing: 8,
                              children: [
                                for (final c in const <Color>[
                                  Color(0xFF1A1A2E),
                                  Color(0xFF12121C),
                                  Color(0xFF263238),
                                  Color(0xFF1B3A2E),
                                  Color(0xFF1B2A4A),
                                  Color(0xFF311B4A),
                                  Color(0xFF4A1B2B),
                                  Color(0xFF4A2B1B),
                                  Color(0xFF0F2A2A),
                                  Color(0xFF3A1B2E),
                                  Color(0xFF2E2A1B),
                                  Color(0xFF333333),
                                ])
                                  GestureDetector(
                                    onTap: () async {
                                      await provider
                                          .setHeaderColor(c.toARGB32());
                                      setS(() {});
                                    },
                                    child: Container(
                                      width: 34,
                                      height: 34,
                                      decoration: BoxDecoration(
                                        color: c,
                                        borderRadius: BorderRadius.circular(9),
                                        border: Border.all(
                                          color:
                                              provider.headerColor.toARGB32() ==
                                                      c.toARGB32()
                                                  ? const Color(0xFF4FC3F7)
                                                  : Colors.white24,
                                          width:
                                              provider.headerColor.toARGB32() ==
                                                      c.toARGB32()
                                                  ? 2.5
                                                  : 1,
                                        ),
                                      ),
                                    ),
                                  ),
                              ],
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(height: 16),

                      if (_isDesktop) ...[
                        // ── 「バーを表示する端」 の項目は削除 (= ユーザー要望:
                        //    「新しく追加するボタンの配置先」 と 2 つあると
                        //    混乱するため)。 配置先を選んでボタンを足すと、
                        //    その端のバーは hcbAdd の中で自動的に出る。
                        // ── 新しく追加するボタンの配置先 (= ユーザー要望:
                        //    上下左右のボタンが「今から配置するボタン」 に
                        //    適用されるように。 ここで選んだ端に、 下の候補から
                        //    追加したボタンがそのまま入る)。 ──
                        Text(provider.t('header.newButtonTarget'),
                            style: const TextStyle(
                                color: Colors.white70,
                                fontSize: 12,
                                fontWeight: FontWeight.w600)),
                        const SizedBox(height: 8),
                        Wrap(
                          spacing: 8,
                          runSpacing: 8,
                          children: [
                            for (final placement in [
                              (
                                'top',
                                Icons.vertical_align_top_rounded,
                                'header.placementTop'
                              ),
                              (
                                'bottom',
                                Icons.vertical_align_bottom_rounded,
                                'header.placementBottom'
                              ),
                              (
                                'left',
                                Icons.align_horizontal_left_rounded,
                                'header.placementLeft'
                              ),
                              (
                                'right',
                                Icons.align_horizontal_right_rounded,
                                'header.placementRight'
                              ),
                            ])
                              Builder(builder: (_) {
                                final selected =
                                    _hcbTargetPlacement == placement.$1;
                                return Material(
                                  color: Colors.transparent,
                                  child: InkWell(
                                    borderRadius: BorderRadius.circular(9),
                                    onTap: () => setS(() =>
                                        _hcbTargetPlacement = placement.$1),
                                    child: AnimatedContainer(
                                      duration:
                                          const Duration(milliseconds: 140),
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 12, vertical: 7),
                                      decoration: BoxDecoration(
                                        color: selected
                                            ? Color.alphaBlend(
                                                accentColor.withValues(
                                                    alpha: 0.28),
                                                const Color(0xFF2A2A42),
                                              )
                                            : const Color(0xFF29293B),
                                        borderRadius:
                                            BorderRadius.circular(9),
                                        border: Border.all(
                                          color: selected
                                              ? accentColor
                                              : Colors.white24,
                                          width: selected ? 1.5 : 1,
                                        ),
                                      ),
                                      child: Row(
                                        mainAxisSize: MainAxisSize.min,
                                        children: [
                                          Icon(placement.$2,
                                              size: 14,
                                              color: selected
                                                  ? Colors.white
                                                  : Colors.white60),
                                          const SizedBox(width: 5),
                                          Text(
                                            provider.t(placement.$3),
                                            style: TextStyle(
                                              color: selected
                                                  ? Colors.white
                                                  : Colors.white70,
                                              fontSize: 11,
                                              fontWeight: selected
                                                  ? FontWeight.w700
                                                  : FontWeight.w500,
                                            ),
                                          ),
                                        ],
                                      ),
                                    ),
                                  ),
                                );
                              }),
                          ],
                        ),
                        const SizedBox(height: 16),
                      ],

                      // ヘッダーに追加済み
                      Text(provider.t('header.addedButtons'),
                          style: const TextStyle(
                              color: Colors.white70,
                              fontSize: 12,
                              fontWeight: FontWeight.w600)),
                      const SizedBox(height: 6),
                      // 追加済みリスト: 高さを「常に固定」にする
                      // (= ユーザー要望: 1 個削除するたびに枠が縮んで下の要素が
                      //   ずり上がり、 同じ位置を連打して削除できなかった)。
                      // 削除で候補側に戻る分のスペースは最初から確保してあるので、
                      // 追加/削除しても枠のサイズも下の「追加できるボタン」の
                      // 位置も動かない。 中身が溢れる場合は内側でスクロールする。
                      SizedBox(
                        // 境界のドラッグで高さを変えられる (= ユーザー要望)。
                        height: maxH *
                            (_hcbPlacedFrac > 0
                                ? _hcbPlacedFrac
                                : (_isDesktop ? 0.26 : 0.32)),
                        child: Container(
                          padding: const EdgeInsets.all(8),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.04),
                            borderRadius: BorderRadius.circular(10),
                          ),
                          child: hcbList().isEmpty
                              ? Padding(
                                  padding:
                                      const EdgeInsets.symmetric(vertical: 12),
                                  child: Center(
                                    child: Text(provider.t('hdr.emptyPlaced'),
                                        style: const TextStyle(
                                            color: Colors.white30,
                                            fontSize: 11)),
                                  ),
                                )
                              : RawScrollbar(
                                  controller: hcsScrollCtrl,
                                  thumbColor:
                                      Colors.white.withValues(alpha: 0.55),
                                  thickness: 8,
                                  radius: const Radius.circular(4),
                                  thumbVisibility: true,
                                  padding: const EdgeInsets.only(
                                      right: 2, top: 4, bottom: 4),
                                  child: SingleChildScrollView(
                                    controller: hcsScrollCtrl,
                                    padding: const EdgeInsets.only(right: 12),
                                    child: Column(
                                      mainAxisSize: MainAxisSize.min,
                                      children: [
                                        for (int i = 0;
                                            i < hcbList().length;
                                            i++)
                                          // モバイル版では 'shortcuts' をカスタム項目から隠す
                                          // (クラウド同期で desktop 設定が入っていた場合の保護)
                                          if ((_isDesktop ||
                                                  hcbList()[i] !=
                                                      'shortcuts') &&
                                              !_hideCommandForCurrentLocale(
                                                  hcbList()[i], provider))
                                            _headerCustomizeRow(
                                              id: hcbList()[i],
                                              index: i,
                                              total: hcbList().length,
                                              provider: provider,
                                              placement: _isDesktop
                                                  ? provider
                                                      .desktopHeaderButtonPlacementFor(
                                                          hcbList()[i])
                                                  : null,
                                              onPlacementChanged: _isDesktop
                                                  ? (placement) async {
                                                      await provider
                                                          .setDesktopHeaderButtonPlacementFor(
                                                              hcbList()[i],
                                                              placement);
                                                      setS(() {});
                                                    }
                                                  : null,
                                              onRemove: () async {
                                                await hcbRemove(hcbList()[i]);
                                                setS(() {});
                                              },
                                              onMoveUp: () async {
                                                if (i > 0) {
                                                  await hcbReorder(i, i - 1);
                                                  setS(() {});
                                                }
                                              },
                                              onMoveDown: () async {
                                                if (i < hcbList().length - 1) {
                                                  await hcbReorder(i, i + 2);
                                                  setS(() {});
                                                }
                                              },
                                            ),
                                      ],
                                    ),
                                  ),
                                ),
                        ),
                      ),
                      // ── 境界のドラッグバー (= ユーザー要望: 配置済みと
                      //    追加できるボタンの間の境界を動かして表示領域を
                      //    変えられるように)。 変更した高さは次回も引き継ぐ。 ──
                      MouseRegion(
                        cursor: SystemMouseCursors.resizeUpDown,
                        child: GestureDetector(
                          behavior: HitTestBehavior.opaque,
                          onVerticalDragUpdate: (d) {
                            setS(() {
                              final cur = _hcbPlacedFrac > 0
                                  ? _hcbPlacedFrac
                                  : (_isDesktop ? 0.26 : 0.32);
                              _hcbPlacedFrac = (cur + d.delta.dy / maxH)
                                  .clamp(0.12, 0.68)
                                  .toDouble();
                            });
                          },
                          onVerticalDragEnd: (_) {
                            // ignore: discarded_futures
                            SharedPreferences.getInstance().then((sp) => sp
                                .setDouble(
                                    'hdrCustPlacedFrac', _hcbPlacedFrac));
                          },
                          child: SizedBox(
                            height: 14,
                            child: Center(
                              child: Container(
                                width: 64,
                                height: 4,
                                decoration: BoxDecoration(
                                  color: Colors.white24,
                                  borderRadius: BorderRadius.circular(2),
                                ),
                              ),
                            ),
                          ),
                        ),
                      ),

                      // 追加可能なボタン一覧。
                      // 候補ゼロでもセクションごと消さずに枠だけ残す
                      // (= ユーザー要望: 削除でここに項目が戻ってきた瞬間に
                      //   セクションが生えてレイアウトが飛ぶのを防ぐ)。
                      ...[
                        Row(children: [
                          Expanded(
                            child: Text(provider.t('header.availableButtons'),
                                style: const TextStyle(
                                    color: Colors.white70,
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600)),
                          ),
                          // モバイル版では 3/3 などの枠数を表示
                          if (!_isDesktop)
                            Text(
                              '${hcbList().length}/∞',
                              style: TextStyle(
                                  color: Colors.white38,
                                  fontSize: 11,
                                  fontWeight: FontWeight.w600),
                            ),
                        ]),
                        // ── Ctrl / Shift でまとめて選択して追加できるヒント ──
                        //   (= ユーザー要望)。 デスクトップのみ (修飾キーが要る)。
                        if (_isDesktop) ...[
                          const SizedBox(height: 2),
                          Text(provider.t('header.multiSelectHint'),
                              style: const TextStyle(
                                  color: Colors.white38, fontSize: 10.5)),
                        ],
                        // ── まとめ選択中のアクション行 (まとめて追加 / 選択解除) ──
                        if (multiSelIds.isNotEmpty) ...[
                          const SizedBox(height: 8),
                          Row(children: [
                            Expanded(
                              child: ElevatedButton.icon(
                                style: ElevatedButton.styleFrom(
                                    backgroundColor: const Color(0xFFFFB347),
                                    foregroundColor: Colors.black,
                                    padding: const EdgeInsets.symmetric(
                                        vertical: 8),
                                    minimumSize: const Size(0, 34)),
                                icon: const Icon(Icons.playlist_add_rounded,
                                    size: 16),
                                label: Text(
                                    '${provider.t('header.addSelected')} (${multiSelIds.length})',
                                    style: const TextStyle(
                                        fontSize: 12,
                                        fontWeight: FontWeight.w700)),
                                onPressed: () async {
                                  // 表示順 (flatAvailableIds) に追加する。
                                  for (final aid in flatAvailableIds) {
                                    if (multiSelIds.contains(aid)) {
                                      await hcbAdd(aid);
                                    }
                                  }
                                  multiSelIds.clear();
                                  multiSelAnchor = null;
                                  if (mounted) setS(() {});
                                },
                              ),
                            ),
                            const SizedBox(width: 8),
                            TextButton(
                              onPressed: () {
                                multiSelIds.clear();
                                multiSelAnchor = null;
                                setS(() {});
                              },
                              child: Text(provider.t('header.clearSelection'),
                                  style: const TextStyle(
                                      color: Colors.white54, fontSize: 12)),
                            ),
                          ]),
                        ],
                        const SizedBox(height: 6),
                        // 候補数で高さが伸び縮みするコンテナ。Expanded だと
                        // 候補が無い・少ないときも巨大に開いてしまうため、
                        // 「中身の自然サイズ + maxHeight でキャップ」の形に変えた。
                        // Wrap が長くて maxHeight を超えるときは内側で
                        // SingleChildScrollView がスクロールする。
                        Expanded(
                          child: SizedBox(
                            width: double.infinity,
                            child: Container(
                              padding: const EdgeInsets.all(8),
                              decoration: BoxDecoration(
                                color: Colors.white.withValues(alpha: 0.02),
                                borderRadius: BorderRadius.circular(10),
                              ),
                              child: SingleChildScrollView(
                                child: Builder(builder: (_) {
                                  // ── 役割ごとに区分けして表示 ──
                                  // ユーザー要望「追加できるボタン、 役割毎に
                                  //   区分けしてボタンを探しやすくして」 への対応。
                                  // 旧仕様: 全候補をフラット Wrap で表示 → 30+
                                  //   個並ぶと探しにくい。
                                  // 新仕様: `_headerButtonCategories` の順で
                                  //   セクションを並べ、 各セクション内で Wrap
                                  //   表示する。
                                  //
                                  // モバイル版でのスロット上限制御 (= 既に上限
                                  // なら全候補を disabled で表示) は従来通り。
                                  final atLimit = false;
                                  // ── カテゴリ → 該当候補の Map を組み立て ──
                                  // availableCmds の id を引いて、 カテゴリ
                                  // commandIds の順に並べる。 該当無しのカテゴリ
                                  // は描画スキップ。
                                  final byId = <String, Map<String, dynamic>>{
                                    for (final c in availableCmds) c['id']!: c
                                  };
                                  // ── どのカテゴリにも属さないコマンドを
                                  //     「その他」 にフォールバック ──
                                  // 新しいコマンドが _headerCustomizableCommands
                                  // に追加されたが _headerButtonCategories に
                                  // 入っていない場合の防御。
                                  final categorized = <String>{};
                                  for (final cat in _headerButtonCategories) {
                                    final ids =
                                        cat['commandIds'] as List<String>;
                                    categorized.addAll(ids);
                                  }
                                  final uncategorizedAvailable = availableCmds
                                      .where(
                                          (c) => !categorized.contains(c['id']))
                                      .toList();
                                  // 「その他」 カテゴリに動的フォールバック分を
                                  // 追加 (= 既存の 'shortcuts' に未分類 ID を
                                  // 末尾に append)。
                                  List<String> commandIdsFor(
                                      Map<String, dynamic> cat) {
                                    final base = List<String>.from(
                                        cat['commandIds'] as List<String>);
                                    if (cat['id'] == 'other') {
                                      for (final c in uncategorizedAvailable) {
                                        final id = c['id'] as String;
                                        if (!base.contains(id)) base.add(id);
                                      }
                                    }
                                    return base;
                                  }

                                  // ── セクション描画 ──
                                  final sections = <Widget>[];
                                  for (int ci = 0;
                                      ci < _headerButtonCategories.length;
                                      ci++) {
                                    final cat = _headerButtonCategories[ci];
                                    final ids = commandIdsFor(cat);
                                    // この カテゴリで「追加可能」 として残って
                                    // いる候補だけを順序通り集める。
                                    final chipsForCat = <Widget>[];
                                    for (final id in ids) {
                                      final cmd = byId[id];
                                      if (cmd == null) continue;
                                      chipsForCat.add(_headerCustomizeChip(
                                        id: id,
                                        isAdded: false,
                                        enabled: !atLimit,
                                        selected: multiSelIds.contains(id),
                                        onTap: atLimit
                                            ? null
                                            : () => handleCandidateTap(id),
                                      ));
                                    }
                                    if (chipsForCat.isEmpty) continue;
                                    // ── 見出し ──
                                    // 小さめのラベル + 区切り線で「カテゴリ感」
                                    // を出す。 セクション間には少し間隔を空ける。
                                    if (sections.isNotEmpty) {
                                      sections.add(const SizedBox(height: 10));
                                    }
                                    sections.add(Padding(
                                      padding: const EdgeInsets.only(bottom: 6),
                                      child: Row(children: [
                                        Icon(cat['icon'] as IconData,
                                            size: 14, color: Colors.white54),
                                        const SizedBox(width: 6),
                                        Text(
                                          provider.t(cat['labelKey'] as String),
                                          style: const TextStyle(
                                              color: Colors.white60,
                                              fontSize: 11,
                                              fontWeight: FontWeight.w700,
                                              letterSpacing: 0.3),
                                        ),
                                        const SizedBox(width: 8),
                                        Expanded(
                                          child: Container(
                                            height: 1,
                                            color: Colors.white
                                                .withValues(alpha: 0.06),
                                          ),
                                        ),
                                      ]),
                                    ));
                                    sections.add(Wrap(
                                      spacing: 6,
                                      runSpacing: 6,
                                      children: chipsForCat,
                                    ));
                                  }
                                  // 候補ゼロでも枠は残す (= レイアウトを
                                  // 動かさないため)。 案内文だけ表示する。
                                  if (sections.isEmpty) {
                                    return Padding(
                                      padding: const EdgeInsets.symmetric(
                                          vertical: 16),
                                      child: Center(
                                        child: Text(
                                          provider.t('hdr.emptyAvailable'),
                                          textAlign: TextAlign.center,
                                          style: const TextStyle(
                                              color: Colors.white30,
                                              fontSize: 11),
                                        ),
                                      ),
                                    );
                                  }
                                  return Column(
                                    mainAxisSize: MainAxisSize.min,
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: sections,
                                  );
                                }),
                              ),
                            ),
                          ),
                        ),
                      ],
                    ],
                  );
                }),
              ),
            ),
          ),
          );
        },
      ),
    );
  }

  /// 追加済みヘッダーボタンの並び替え/削除可能な行
  /// 上下矢印ボタンで並び替え（ドラッグ不要）、右端のゴミ箱で削除。
  Widget _headerCustomizeRow({
    required String id,
    required int index,
    required int total,
    required MindMapProvider provider,
    required VoidCallback onRemove,
    required VoidCallback onMoveUp,
    required VoidCallback onMoveDown,
    String? placement,
    ValueChanged<String>? onPlacementChanged,
  }) {
    final cmd = _headerCustomizableCommands.firstWhere((c) => c['id'] == id,
        orElse: () => <String, dynamic>{});
    final labelKey = cmd['labelKey'] as String?;
    var label = labelKey != null ? provider.t(labelKey) : id;
    // ── 「フラッシュカード」 は狭いボタン一覧で「フラッシュカー / ド」 と不自然に
    //   折り返して見栄えが悪い (= ユーザー要望)。 「フラッシュ / カード」 で
    //   折り返すよう、 フラッシュの後に明示的な改行を入れる。 ──
    if (label == 'フラッシュカード') label = 'フラッシュ\nカード';
    final icon = cmd['icon'] as IconData?;
    final color = (cmd['color'] as Color?) ?? const Color(0xFF4FC3F7);
    return Container(
      // ── 1 番上のタイルの y 座標を常に同じにする ──
      // 旧: `margin: vertical 2` だとリストの先頭にも上 2px のマージンが
      //     入り、 タイル削除→詰まり時に位置がわずかに動いて感じられる。
      // 新: bottom only にして、 タイル間の間隔だけ確保。 リスト先頭の
      //     タイルは常に y=0 から始まるので、 削除を連続しても 1 番上の
      //     削除ボタンの位置はピクセル単位で同じ場所に来る。
      margin: const EdgeInsets.only(bottom: 4),
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.12),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: color.withValues(alpha: 0.5), width: 1.0),
      ),
      child: Row(children: [
        // 上へ
        IconButton(
          icon: const Icon(Icons.arrow_upward_rounded, size: 16),
          color: index > 0 ? Colors.white70 : Colors.white24,
          tooltip: provider.t('header.moveUp'),
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
          onPressed: index > 0 ? onMoveUp : null,
        ),
        // 下へ
        IconButton(
          icon: const Icon(Icons.arrow_downward_rounded, size: 16),
          color: index < total - 1 ? Colors.white70 : Colors.white24,
          tooltip: provider.t('header.moveDown'),
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
          onPressed: index < total - 1 ? onMoveDown : null,
        ),
        const SizedBox(width: 8),
        if (icon != null) _cmdIconWidget(id, icon, color: color, size: 16),
        if (icon != null) const SizedBox(width: 6),
        Expanded(
          child: Text(label,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 12,
                  fontWeight: FontWeight.w600)),
        ),
        const SizedBox(width: 8),
        if (placement != null && onPlacementChanged != null)
          PopupMenuButton<String>(
            initialValue: placement,
            tooltip: provider.t('header.buttonPlacement'),
            color: const Color(0xFF242438),
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 32, minHeight: 28),
            icon: Icon(
              switch (placement) {
                'bottom' => Icons.vertical_align_bottom_rounded,
                'left' => Icons.align_horizontal_left_rounded,
                'right' => Icons.align_horizontal_right_rounded,
                _ => Icons.vertical_align_top_rounded,
              },
              size: 17,
              color: const Color(0xFFFFB347),
            ),
            onSelected: onPlacementChanged,
            itemBuilder: (_) => [
              for (final item in const [
                (
                  'top',
                  Icons.vertical_align_top_rounded,
                  'header.placementTop'
                ),
                (
                  'bottom',
                  Icons.vertical_align_bottom_rounded,
                  'header.placementBottom'
                ),
                (
                  'left',
                  Icons.align_horizontal_left_rounded,
                  'header.placementLeft'
                ),
                (
                  'right',
                  Icons.align_horizontal_right_rounded,
                  'header.placementRight'
                ),
              ])
                PopupMenuItem<String>(
                  value: item.$1,
                  child: Row(children: [
                    Icon(item.$2, size: 17, color: Colors.white70),
                    const SizedBox(width: 8),
                    Text(provider.t(item.$3),
                        style: const TextStyle(color: Colors.white)),
                  ]),
                ),
            ],
          ),
        IconButton(
          icon: const Icon(Icons.delete_outline_rounded, size: 16),
          color: Colors.redAccent,
          tooltip: provider.t('header.removeButton'),
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
          onPressed: onRemove,
        ),
      ]),
    );
  }

  Widget _headerCustomizeChip({
    required String id,
    required bool isAdded,
    required VoidCallback? onTap,
    bool enabled = true,
    // ── Ctrl/Shift でまとめて選択中の候補チップ (= ユーザー要望) ──
    //   選択中は枠を強調してチェックアイコンを出す。
    bool selected = false,
  }) {
    final provider = context.read<MindMapProvider>();
    final cmd = _headerCustomizableCommands.firstWhere((c) => c['id'] == id,
        orElse: () => <String, dynamic>{});
    final labelKey = cmd['labelKey'] as String?;
    var label = labelKey != null ? provider.t(labelKey) : id;
    // ── 「フラッシュカード」 は狭いボタン一覧で「フラッシュカー / ド」 と不自然に
    //   折り返して見栄えが悪い (= ユーザー要望)。 「フラッシュ / カード」 で
    //   折り返すよう、 フラッシュの後に明示的な改行を入れる。 ──
    if (label == 'フラッシュカード') label = 'フラッシュ\nカード';
    final icon = cmd['icon'] as IconData?;
    var color = (cmd['color'] as Color?) ?? const Color(0xFF4FC3F7);
    // 暗すぎる既定色 (黒系) はダーク背景の選択画面で見えないので明るくする
    //   (= ユーザー要望: 選択画面で黒いボタンが見えない)。
    if (color.computeLuminance() < 0.12) color = const Color(0xFFEFEFEF);
    const selColor = Color(0xFFFFB347);
    return InkWell(
      onTap: enabled ? onTap : null,
      borderRadius: BorderRadius.circular(8),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
        decoration: BoxDecoration(
          color: selected
              ? selColor.withValues(alpha: 0.22)
              : (isAdded
                  ? color.withValues(alpha: 0.2)
                  : Colors.white.withValues(alpha: enabled ? 0.04 : 0.015)),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(
              color: selected
                  ? selColor
                  : (isAdded
                      ? color
                      : (enabled ? Colors.white12 : Colors.white10)),
              width: selected ? 1.8 : 1.3),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          if (icon != null)
            _cmdIconWidget(id, icon,
                color: enabled ? color : color.withValues(alpha: 0.3),
                size: 16),
          if (icon != null) const SizedBox(width: 6),
          Text(label,
              style: TextStyle(
                  color: isAdded || selected
                      ? Colors.white
                      : (enabled ? Colors.white70 : Colors.white24),
                  fontSize: 12,
                  fontWeight: FontWeight.w600)),
          const SizedBox(width: 6),
          Icon(
            selected
                ? Icons.check_circle_rounded
                : (isAdded
                    ? Icons.remove_circle_outline_rounded
                    : Icons.add_circle_outline_rounded),
            size: 14,
            color: selected
                ? selColor
                : (isAdded
                    ? Colors.redAccent
                    : (enabled ? color : Colors.white24)),
          ),
        ]),
      ),
    );
  }

  /// ヘッダーに追加できるコマンドの定義
  /// アイコンは `IconData` の定数参照、ラベルは翻訳キー
  static const Set<String> _retiredCustomCommandIds = {
    // 操作ボタンのカスタマイズは「バーの何もない所をクリック」 に統合
    // (= ユーザー要望: ボタン自体は消す)。
    'customizeHeader',
    'openX',
    'openQiita',
    'moveLockMenu',
    // TikTok は在アプリ WebView でアクセス不可のため廃止 (= ユーザー報告)。
    // 既に配置済みのボタンもここで非表示になる。
    'openTikTok',
    'wrapWithParent',
    'searchSoundCloud',
    'searchSpotify',
    // LINE は Web 版のチャットが存在せず、 サイトを開いても何もできない
    //   (= ユーザー要望: ブラウザ版で開けないならボタンを消す)。
    'openLINE',
    // ── フローティング AI / フローティングメモは「AI」「メモ」 に統合
    //    (= ユーザー要望)。 配置済みのものもここで消える。 ──
    'popOutAi',
    'floatingMemo',
    // ── AI の個別ボタンは「ブラウザ版AI」 (openAi) に統一 (= ユーザー要望) ──
    // 配置済みのものもここで消える。 どの AI を開くかは openAi の
    // 右クリック / 長押しメニューで選ぶ。
    'openChatGPT',
    'openGemini',
    'openClaude',
    'openDeepSeek',
    'openGrok',
  };

  static bool _isRetiredCustomCommand(String? id) =>
      id != null && _retiredCustomCommandIds.contains(id);

