  /// 図形ピッカーの 1 個分のアイテム (= アイコン + ラベル)。
  Widget _buildShapeChoice(BuildContext pickerContext, MapDecorationKind kind,
      IconData icon, String label) {
    return InkWell(
      onTap: () {
        Navigator.of(pickerContext).pop();
        setState(() {
          _drawingDecorationKind = kind;
          _lastShapeKind = kind;
          _drawingDecorationStart = null;
          _drawingDecorationEnd = null;
          _selectedDecorationId = null;
          // 折れ線の作りかけは持ち越さない。
          _polylinePoints.clear();
          _polylineCursor = null;
        });
        // ヒントを SnackBar で出す (モードは × / Esc まで継続)。
        final provider = context.read<MindMapProvider>();
        // 折れ線はドラッグではなくクリックで作るので、 別の案内を出す。
        final hint = kind == MapDecorationKind.polyline
            ? provider.t('shape.polylineHint')
            : provider.t('shape.dragHint');
        _appSnack(
          context,
          SnackBar(
            content: Text('$label: $hint'),
            duration: Duration(seconds: kind == MapDecorationKind.polyline
                ? 4
                : 2),
            behavior: SnackBarBehavior.floating,
          ),
        );
      },
      // ラベルの長さで幅がバラバラにならないよう固定幅にする
      // (= ユーザー指摘: 英語版の図形の並びが悪い)。 2 行まで折り返し、
      // それ以上は省略。 高さも揃うので格子状にきれいに並ぶ。
      child: SizedBox(
        width: 96,
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 10),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Container(
                width: 52,
                height: 52,
                decoration: BoxDecoration(
                  color: const Color(0xFF43B97F).withValues(alpha: 0.15),
                  borderRadius: BorderRadius.circular(10),
                  border: Border.all(
                      color: const Color(0xFF43B97F).withValues(alpha: 0.4)),
                ),
                child: Icon(icon, color: const Color(0xFF43B97F), size: 28),
              ),
              const SizedBox(height: 6),
              SizedBox(
                height: 32,
                child: Text(label,
                    textAlign: TextAlign.center,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: Colors.white, fontSize: 12, height: 1.25)),
