    );
  }

  /// マップ上で装飾図形ドラッグを開始 (= 始点を記録)。
  /// 既存の InteractiveViewer の onPanStart 等から呼ばれる。
  bool _decorationCanAttachToNode(MapDecorationKind kind) =>
      kind == MapDecorationKind.line || kind == MapDecorationKind.arrow;

  ({String nodeId, AnchorDirection anchor, Offset point})?
      _nearestDecorationNodeAnchor(Offset point, {double maxDistance = 34}) {
    final provider = context.read<MindMapProvider>();
    final hidden = provider.hiddenNodeIds;
    ({String nodeId, AnchorDirection anchor, Offset point})? best;
    var bestDistance = maxDistance;
    for (final node in provider.nodes.values) {
      if (hidden.contains(node.id)) continue;
      for (final anchor in anchorsForMode(node.anchorMode)) {
        final anchorPoint = node.anchorPoint(anchor);
        final distance = (anchorPoint - point).distance;
        if (distance <= bestDistance) {
          bestDistance = distance;
          best = (nodeId: node.id, anchor: anchor, point: anchorPoint);
        }
      }
    }
    return best;
  }

  MapDecoration _resolvedDecoration(
      MapDecoration decoration, MindMapProvider provider) {
    var start = decoration.start;
    var end = decoration.end;
    final startNode = decoration.startNodeId == null
        ? null
        : provider.nodes[decoration.startNodeId!];
    final endNode = decoration.endNodeId == null
        ? null
        : provider.nodes[decoration.endNodeId!];
    if (startNode != null && decoration.startNodeAnchor != null) {
      start = startNode.anchorPoint(decoration.startNodeAnchor!);
    }
    if (endNode != null && decoration.endNodeAnchor != null) {
      end = endNode.anchorPoint(decoration.endNodeAnchor!);
    }
    return decoration.copyWith(start: start, end: end);
  }

  List<MapDecoration> _resolvedDecorations(MindMapProvider provider) =>
      provider.decorations
          .map((decoration) => _resolvedDecoration(decoration, provider))
          .toList(growable: false);

  // ── 折れ線 (polyline) の作成中の状態 (= ユーザー要望: 節点の沢山ついた
  //    折れ曲がった直線)。 クリックで節点を足していき、 最後の点をもう一度
  //    押す / Enter / ダブルクリック で確定する。 ──
  final List<Offset> _polylinePoints = <Offset>[];

  /// 次の節点の候補 (マウスが今いる場所)。 プレビューの最後の 1 本に使う。
  Offset? _polylineCursor;

  bool get _polylineMode =>
      _drawingDecorationKind == MapDecorationKind.polyline;

  /// 折れ線に節点を足す。 最後の点のすぐ近くを押したら確定にする。
  void _polylineAddPoint(Offset p) {
    if (_polylinePoints.isNotEmpty) {
      final last = _polylinePoints.last;
      if ((p - last).distance < 12) {
        _polylineCommit();
        return;
      }
    }
    setState(() {
      _polylinePoints.add(p);
      _polylineCursor = p;
    });
  }

  /// 今の節点で折れ線を確定する (2 点未満なら捨てる)。
  void _polylineCommit() {
    if (_polylinePoints.length < 2) {
      setState(() {
        _polylinePoints.clear();
        _polylineCursor = null;
      });
      return;
    }
    final pts = List<Offset>.of(_polylinePoints);
    final deco = MapDecoration(
      id: 'deco_${DateTime.now().microsecondsSinceEpoch}',
      kind: MapDecorationKind.polyline,
      // start / end は外接矩形や移動処理が使うので、 端の点を入れておく。
      start: pts.first,
      end: pts.last,
      colorRgb: _shapeColorRgb,
      strokeWidth: _shapeStrokeWidth,
      layer: context.read<MindMapProvider>().activeLayer,
      points: pts,
    );
    context.read<MindMapProvider>().addMapDecoration(deco);
    setState(() {
      _polylinePoints.clear();
      _polylineCursor = null;
    });
  }

  /// 作りかけの折れ線を捨てる (Esc / モード解除)。
  void _polylineCancel() {
    if (_polylinePoints.isEmpty && _polylineCursor == null) return;
    setState(() {
      _polylinePoints.clear();
      _polylineCursor = null;
    });
  }

  /// 押した所へ、 決めた大きさ・縦横比で図形を 1 個置く (= ユーザー要望)。
  ///
  /// 線・矢印・波線は横一直線、 それ以外は正方形の枠に収める (= 縦横比は
  /// 固定)。 ドラッグした時は今までどおり好きな形に描ける。
  void _placeFixedSizeDecoration(Offset center) {
    final kind = _drawingDecorationKind;
    if (kind == null || kind == MapDecorationKind.polyline) return;
    final half = _shapeInsertSize / 2;
    final bool lineLike = kind == MapDecorationKind.line ||
        kind == MapDecorationKind.arrow ||
        kind == MapDecorationKind.wavyLine;
    final Offset start = lineLike
        ? Offset(center.dx - half, center.dy)
        : Offset(center.dx - half, center.dy - half);
    final Offset end = lineLike
        ? Offset(center.dx + half, center.dy)
        : Offset(center.dx + half, center.dy + half);
    final deco = MapDecoration(
      id: 'deco_${DateTime.now().microsecondsSinceEpoch}',
      kind: kind,
      start: start,
      end: end,
      colorRgb: _shapeColorRgb,
      strokeWidth: _shapeStrokeWidth,
      // 中を塗るか (= ユーザー要望: 中空にできる札で切り替える)。
      filled: !_shapeHollow,
      layer: context.read<MindMapProvider>().activeLayer,
    );
    context.read<MindMapProvider>().addMapDecoration(deco);
    // 続けて置けるよう、 挿入モードは解除しない (ドラッグ描きと同じ)。
    setState(() {
      _drawingDecorationStart = null;
      _drawingDecorationEnd = null;
    });
  }

  void _handleDecorationPanStart(Offset canvasPoint) {
    final kind = _drawingDecorationKind;
    if (kind == null) return;
    // 折れ線はドラッグではなくクリックで節点を足していく。
    if (kind == MapDecorationKind.polyline) return;
    final snap = _decorationCanAttachToNode(kind)
        ? _nearestDecorationNodeAnchor(canvasPoint)
        : null;
    setState(() {
      _drawingDecorationStart = snap?.point ?? canvasPoint;
      _drawingDecorationEnd = snap?.point ?? canvasPoint;
    });
  }

  void _handleDecorationPanUpdate(Offset canvasPoint) {
    final kind = _drawingDecorationKind;
    if (kind == null) return;
    if (kind == MapDecorationKind.polyline) return;
    final snap = _decorationCanAttachToNode(kind)
        ? _nearestDecorationNodeAnchor(canvasPoint)
        : null;
    setState(() {
      _drawingDecorationEnd = snap?.point ?? canvasPoint;
    });
  }

  void _handleDecorationPanEnd() {
    if (_drawingDecorationKind == null) return;
    if (_drawingDecorationKind == MapDecorationKind.polyline) return;
    final start = _drawingDecorationStart;
    final end = _drawingDecorationEnd;
    if (start != null && end != null && (end - start).distance >= 6) {
      final canAttach = _decorationCanAttachToNode(_drawingDecorationKind!);
      final startSnap = canAttach ? _nearestDecorationNodeAnchor(start) : null;
      final endSnap = canAttach ? _nearestDecorationNodeAnchor(end) : null;
      // 6px 以上動いてれば確定 (= タップだけだと小さすぎるので破棄)
      final deco = MapDecoration(
        id: 'deco_${DateTime.now().microsecondsSinceEpoch}',
        kind: _drawingDecorationKind!,
        start: startSnap?.point ?? start,
        end: endSnap?.point ?? end,
        startNodeId: startSnap?.nodeId,
        startNodeAnchor: startSnap?.anchor,
        endNodeId: endSnap?.nodeId,
        endNodeAnchor: endSnap?.anchor,
        colorRgb: _shapeColorRgb,
        strokeWidth: _shapeStrokeWidth,
        // 中を塗るか (= ユーザー要望)。
        filled: !_shapeHollow,
        // ── 今いるレイヤーに置く (= ユーザー要望: ページ毎にレイヤーを
        //    移動して、 そのレイヤーに対してオブジェクトを配置する) ──
        layer: context.read<MindMapProvider>().activeLayer,
      );
      context.read<MindMapProvider>().addMapDecoration(deco);
    }
    // ── 挿入モードは解除しない (= ユーザー要望) ──
    // 図形を 1 個描いてもモードは継続し、 連続して図形を描ける。
    // 解除は Esc キー or ツールバーの × ボタンのみ。
    setState(() {
      _drawingDecorationStart = null;
      _drawingDecorationEnd = null;
    });
  }

  /// 図形挿入モードを終了する (Esc / × ボタン)。
  ///
  /// 折れ線を引いている最中の Esc は「確定」 にする (= ユーザー要望: Esc で
  /// 取り消されるのは使い辛い。 むしろ確定して欲しい)。 モードは残すので、
  /// 続けて次の折れ線を引ける。 引き終えた後にもう一度押すとモードを抜ける。
  void _exitShapeInsertMode() {
    if (_polylinePoints.isNotEmpty) {
      _polylineCommit();
      return;
    }
    if (!_shapePaletteOpen &&
        _drawingDecorationKind == null &&
        _drawingDecorationStart == null &&
        _drawingDecorationEnd == null) {
      return;
    }
    setState(() {
      // × / Esc の時だけパレットごと閉じる (= ユーザー要望)。
      _shapePaletteOpen = false;
      _drawingDecorationKind = null;
      _drawingDecorationStart = null;
      _drawingDecorationEnd = null;
      _polylineCursor = null;
    });
  }

  /// 図形のヒットテスト: 指定キャンバス座標に最も手前で重なる装飾の ID。
  /// 線/矢印/波線は線分との距離、 それ以外は外接矩形 (拡張) 内かで判定。
  String? _decorationHitTest(Offset p, double scale) {
    // 画面上で約 14px を当たり判定にする (= キャンバス座標では 14/scale)。
    // ズームアウト時でもタップしやすいよう scale で割る。
    final s = scale <= 0 ? 1.0 : scale;
    final t = (14.0 / s).clamp(6.0, 90.0);
    final provider = context.read<MindMapProvider>();
    // 手前 (レイヤー番号が大きい方、 同じ層では後から描いた方) から
    // 当てる (= 5 段階レイヤー対応: 重なっている時は上の層を選ぶ)。
    final indexed = _resolvedDecorations(provider).asMap().entries.toList()
      ..sort((a, b) {
        final byLayer = a.value.layer.compareTo(b.value.layer);
        return byLayer != 0 ? byLayer : a.key.compareTo(b.key);
      });
    final decos = [for (final e in indexed) e.value];
    for (final d in decos.reversed) {
      switch (d.kind) {
        case MapDecorationKind.polyline:
          final pts = d.points;
          for (var i = 0; i + 1 < pts.length; i++) {
            if (_distToSegment(p, pts[i], pts[i + 1]) <= t + d.strokeWidth) {
              return d.id;
            }
          }
          break;
        case MapDecorationKind.line:
        case MapDecorationKind.arrow:
        case MapDecorationKind.wavyLine:
          if (_distToSegment(p, d.start, d.end) <= t + d.strokeWidth) {
            return d.id;
          }
          break;
        default:
          final r = Rect.fromPoints(d.start, d.end).inflate(t);
          if (r.contains(p)) return d.id;
      }
    }
    return null;
  }

  /// 点 p から線分 a-b への最短距離。
  double _distToSegment(Offset p, Offset a, Offset b) {
    final ab = b - a;
    final lenSq = ab.dx * ab.dx + ab.dy * ab.dy;
    if (lenSq < 1e-6) return (p - a).distance;
    var t = ((p.dx - a.dx) * ab.dx + (p.dy - a.dy) * ab.dy) / lenSq;
    t = t.clamp(0.0, 1.0);
    final proj = Offset(a.dx + ab.dx * t, a.dy + ab.dy * t);
    return (p - proj).distance;
  }

  /// キャンバスタップ時の装飾選択処理。 装飾に当たれば選択、 外れたら
  /// 選択解除 + 通常のリセット。
  void _handleCanvasTapForDecoration(Offset canvasPos, double scale) {
    final hit = _decorationHitTest(canvasPos, scale);
    if (hit != null) {
      setState(() => _selectedDecorationId = hit);
      return;
    }
    if (_selectedDecorationId != null) {
      setState(() => _selectedDecorationId = null);
    }
    _resetInteractionState();
  }

  /// 範囲選択の矩形 [rect] (キャンバス座標) に重なる図形を
  /// `_rangeSelectedDecorationIds` に追加する。
  void _addDecorationsInRect(Rect rect) {
    final provider = context.read<MindMapProvider>();
    final decos = _resolvedDecorations(provider);
    for (final d in decos) {
      final r = Rect.fromPoints(d.start, d.end).inflate(1.0);
      if (rect.overlaps(r)) {
        _rangeSelectedDecorationIds.add(d.id);
      }
    }
  }

  /// 選択中の装飾を削除。
  void _deleteSelectedDecoration() {
    final id = _selectedDecorationId;
    if (id == null) return;
    context.read<MindMapProvider>().removeMapDecoration(id);
    setState(() {
      _selectedDecorationId = null;
      // 消した後に選ぶ物が残っていなければ、 選択モードも終わりにする
      // (= ユーザー要望: 削除したら選択モード自体も解除)。
      if (_rangeSelectedIds.isEmpty && _rangeSelectedDecorationIds.isEmpty) {
        _rangeSelectMode = false;
        _rangeStart = null;
        _rangeEnd = null;
      }
    });
  }

  void _detachDecorationEndpoint(
      MindMapProvider provider, MapDecoration decoration, bool isStart) {
    final resolved = _resolvedDecoration(decoration, provider);
    provider.setDecorationEndpointAttachment(
      decoration.id,
      isStart: isStart,
      point: isStart ? resolved.start : resolved.end,
    );
  }

  void _snapDecorationEndpoint(
      MindMapProvider provider, String decorationId, bool isStart) {
    MapDecoration? decoration;
    for (final candidate in provider.decorations) {
      if (candidate.id == decorationId) {
        decoration = candidate;
        break;
      }
    }
    if (decoration == null || !_decorationCanAttachToNode(decoration.kind)) {
      return;
    }
    final point = isStart ? decoration.start : decoration.end;
    final snap = _nearestDecorationNodeAnchor(point);
    provider.setDecorationEndpointAttachment(
      decorationId,
      isStart: isStart,
      nodeId: snap?.nodeId,
      anchor: snap?.anchor,
      point: snap?.point ?? point,
    );
  }

  /// 選択中の図形に移動 / リサイズ用ハンドルを重ねる (キャンバス座標)。
  /// ・中央ハンドル: 図形全体を移動 (start/end を同じだけ平行移動)
  /// ・始点 / 終点ハンドル: その点だけを動かしてサイズ・形を変える
  /// ドラッグ中は _draggingDecoration=true でマップのパン/ズームを止める。
  /// Listener (ポインタイベント) を使うことで InteractiveViewer のパンと
  /// 競合せずに確実にハンドル操作を拾える。
  List<Widget> _buildDecorationHandles(
      MindMapProvider provider, TransformationController ctrl) {
    final id = _selectedDecorationId;
    if (id == null || _drawingDecorationKind != null) return const [];
    MapDecoration? deco;
    for (final d in provider.decorations) {
      if (d.id == id) {
        deco = d;
        break;
      }
    }
    if (deco == null) return const [];
    final sourceDecoration = deco;
    deco = _resolvedDecoration(sourceDecoration, provider);
    final rawScale = ctrl.value.getMaxScaleOnAxis();
    final scale = rawScale <= 0 ? 1.0 : rawScale;
    final hs = 26.0 / scale; // 画面上で約 26px になるキャンバスサイズ
    final half = hs / 2;
    final border = 2.0 / scale;
    final decoId = deco.id;

    // ★ Listener → GestureDetector に変更 (= ユーザー報告: 図形を掴んで
    //   移動させようとすると画面の方が動いてしまう)。 Listener はジェスチャ
    //   アリーナに参加しないため、 InteractiveViewer のパンにポインタを
    //   奪われることがあった。 GestureDetector のドラッグはアリーナで勝つので
    //   マップは動かない。 delta はドラッグレコグナイザが localDelta 基準で
    //   計算するため、 従来どおりキャンバス座標のまま使える。
    Widget handle(Offset canvasPos, Color color, IconData? icon,
        void Function(Offset canvasDelta) onDrag,
        {VoidCallback? onStart,
        VoidCallback? onEnd,
        bool followScroll = false}) {
      void finish() {
        _stopEdgeScroll();
        _decoDragFollowsScroll = false;
        onEnd?.call();
        provider.endDecorationDrag();
        if (mounted) setState(() => _draggingDecoration = false);
      }

      return Positioned(
        left: canvasPos.dx - half,
        top: canvasPos.dy - half,
        width: hs,
        height: hs,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onPanDown: (_) {
            setState(() {
              _draggingDecoration = true;
              _decoDragFollowsScroll = followScroll;
            });
            provider.beginDecorationDrag();
            onStart?.call();
          },
          onPanUpdate: (d) {
            onDrag(d.delta);
            // 画面の端に来たらビューを追跡させる (= ユーザー要望:
            // 選択中は画面固定、 画面外に出ようとした時だけ追跡)。
            if (followScroll) _autoScrollIfNeeded(d.globalPosition, ctrl);
          },
          onPanEnd: (_) => finish(),
          onPanCancel: finish,
          child: Container(
            decoration: BoxDecoration(
              color: color,
              shape: BoxShape.circle,
              border: Border.all(color: Colors.white, width: border),
              boxShadow: const [
                BoxShadow(color: Colors.black45, blurRadius: 2),
              ],
            ),
            child: icon != null
                ? Icon(icon, size: hs * 0.55, color: Colors.white)
                : null,
          ),
        ),
      );
    }

    final center = Rect.fromPoints(deco.start, deco.end).center;
    // ── 本体ドラッグで移動 ──
    // ユーザー要望「ドラッグして別の場所に移動」。 選択中の図形の外接矩形を
    //   覆う透明 Listener を置き、 ドラッグで start/end をまとめて平行移動する。
    //   リサイズ/移動ハンドルより下 (リストの先頭) に置くので、 ハンドル位置
    //   ではハンドルが優先される。 細い線でも掴めるよう少し外側に広げる。
    final bbox = Rect.fromPoints(deco.start, deco.end).inflate(10.0 / scale);
    // 本体ドラッグも GestureDetector (アリーナで勝つ = マップが動かない)。
    void bodyFinish() {
      _stopEdgeScroll();
      _decoDragFollowsScroll = false;
      if (_decoBodyDragMoved) {
        _snapDecorationEndpoint(provider, decoId, true);
        _snapDecorationEndpoint(provider, decoId, false);
        provider.endDecorationDrag();
      }
      _decoBodyDragMoved = false;
      if (mounted) setState(() => _draggingDecoration = false);
    }

    Widget bodyMove() => Positioned(
          left: bbox.left,
          top: bbox.top,
          width: bbox.width,
          height: bbox.height,
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            // ポインタDOWNで即ビューアを止める (マップの同時パンを防ぐ)。
            // undo はタップでは積まず、 最初の移動で積む。
            onPanDown: (_) {
              _decoBodyDragMoved = false;
              _decoDragFollowsScroll = true;
              if (!_draggingDecoration) {
                setState(() => _draggingDecoration = true);
              }
            },
            onPanUpdate: (d) {
              if (!_decoBodyDragMoved) {
                _decoBodyDragMoved = true;
                provider.beginDecorationDrag();
                _detachDecorationEndpoint(provider, sourceDecoration, true);
                _detachDecorationEndpoint(provider, sourceDecoration, false);
              }
              provider.dragDecorationBy(decoId,
                  startDelta: d.delta, endDelta: d.delta);
              // 画面の端に来たらビューを追跡 (= ユーザー要望)。
              _autoScrollIfNeeded(d.globalPosition, ctrl);
            },
            onPanEnd: (_) => bodyFinish(),
            onPanCancel: bodyFinish,
            child: const SizedBox.expand(),
          ),
        );

    // ── 図形内テキストの自由移動ハンドル ──
    // テキストがある場合のみ表示。 アンバーの「T」ハンドルをドラッグすると
    //   textAnchorX/Y が更新され、 文字が外接矩形内を自由に動く (ユーザー要望)。
    //   中央移動ハンドルと重ならないよう、 アンカー点の少し上に浮かせる。
    Widget? textHandle;
    if (deco.text.isNotEmpty) {
      // クロージャ内では nullable の昇格が効かないため、 非 null の
      //   ローカル参照を捕捉する (同一オブジェクトなので最新値を読める)。
      final MapDecoration dd = deco;
      final tb = Rect.fromPoints(dd.start, dd.end);
      final tx = tb.left + tb.width * dd.textAnchorX;
      final ty = tb.top + tb.height * dd.textAnchorY - hs * 1.3;
      void textFinish() {
        provider.endDecorationDrag();
        if (mounted) setState(() => _draggingDecoration = false);
      }

      textHandle = Positioned(
        left: tx - half,
        top: ty - half,
        width: hs,
        height: hs,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onPanDown: (_) {
            setState(() => _draggingDecoration = true);
            provider.beginDecorationDrag();
          },
          onPanUpdate: (d) {
            // delta はキャンバス座標。 外接矩形サイズで正規化して
            //   アンカーを増分更新する (= 同オブジェクト参照なので最新値を読む)。
            final w = (dd.end.dx - dd.start.dx).abs();
            final h = (dd.end.dy - dd.start.dy).abs();
            if (w < 1 || h < 1) return;
            final nx = (dd.textAnchorX + d.delta.dx / w).clamp(0.0, 1.0);
            final ny = (dd.textAnchorY + d.delta.dy / h).clamp(0.0, 1.0);
            provider.dragDecorationTextAnchor(decoId, nx, ny);
          },
          onPanEnd: (_) => textFinish(),
          onPanCancel: textFinish,
          child: Container(
            decoration: BoxDecoration(
              color: const Color(0xFFFFB300),
              shape: BoxShape.circle,
              border: Border.all(color: Colors.white, width: border),
              boxShadow: const [
                BoxShadow(color: Colors.black45, blurRadius: 2),
              ],
            ),
            child: Icon(Icons.text_fields_rounded,
                size: hs * 0.55, color: Colors.white),
          ),
        ),
      );
    }

    return [
      // 本体ドラッグ移動領域 (ハンドルより下)
      bodyMove(),
      // 始点ハンドル (リサイズ)
      handle(deco.start, const Color(0xFF43B97F), null,
          (cd) => provider.dragDecorationBy(decoId, startDelta: cd),
          onStart: () =>
              _detachDecorationEndpoint(provider, sourceDecoration, true),
          onEnd: () => _snapDecorationEndpoint(provider, decoId, true)),
      // 終点ハンドル (リサイズ)
      handle(deco.end, const Color(0xFF43B97F), null,
          (cd) => provider.dragDecorationBy(decoId, endDelta: cd),
          onStart: () =>
              _detachDecorationEndpoint(provider, sourceDecoration, false),
          onEnd: () => _snapDecorationEndpoint(provider, decoId, false)),
      // 移動ハンドル (中央) — start/end を同じだけ動かす。
      // 画面端でのビュー追跡あり (= ユーザー要望)。
      handle(
          center,
          const Color(0xFF4FC3F7),
          Icons.open_with_rounded,
          (cd) =>
              provider.dragDecorationBy(decoId, startDelta: cd, endDelta: cd),
          followScroll: true,
          onStart: () {
        _detachDecorationEndpoint(provider, sourceDecoration, true);
        _detachDecorationEndpoint(provider, sourceDecoration, false);
      }, onEnd: () {
        _snapDecorationEndpoint(provider, decoId, true);
        _snapDecorationEndpoint(provider, decoId, false);
      }),
      // 文字移動ハンドル (アンバー) — 一番上に置いて掴みやすく
      if (textHandle != null) textHandle,
    ];
  }

  /// 図形の種類の並び (ピッカー / ツールバー共通)。
  /// 図形の並び (= ユーザー要望: 同じ形が塗り / 中空で 2 つ並んでいたのを
  /// 1 つにまとめ、 中空にするかは「中空」 の札で切り替える。 見分けの
  /// つかない楕円のボタンは外した)。
  static const List<MapDecorationKind> _shapeKindsOrder = [
    MapDecorationKind.line,
    // 折れ線 (= ユーザー要望: 節点の沢山ついた折れ曲がった直線)。
    MapDecorationKind.polyline,
    MapDecorationKind.arrow,
    MapDecorationKind.wavyLine,
    MapDecorationKind.rectangle,
    MapDecorationKind.hollowCircle,
    MapDecorationKind.hollowTriangle,
    MapDecorationKind.hollowDiamond,
    // ── 追加図形 (= ユーザー要望: 星マークなど挿入できる図形を増やす) ──
    MapDecorationKind.star,
    MapDecorationKind.pentagon,
    MapDecorationKind.hexagon,
    MapDecorationKind.heart,
    MapDecorationKind.cross,
  ];

  /// 次に置く図形の中を空けるか (= ユーザー要望: 中空にできるボタン)。
  /// 既定は「塗る」。
  bool _shapeHollow = false;

  IconData _shapeKindIcon(MapDecorationKind k) {
    switch (k) {
      case MapDecorationKind.polyline:
        return Icons.timeline_rounded;
      case MapDecorationKind.line:
        return Icons.remove_rounded;
      case MapDecorationKind.arrow:
        return Icons.arrow_forward_rounded;
      case MapDecorationKind.wavyLine:
        return Icons.waves_rounded;
      case MapDecorationKind.rectangle:
      case MapDecorationKind.filledRectangle:
        return Icons.square_rounded;
      case MapDecorationKind.ellipse:
        return Icons.egg_alt_rounded;
      case MapDecorationKind.hollowCircle:
      case MapDecorationKind.circle:
        return Icons.circle_rounded;
      case MapDecorationKind.hollowTriangle:
        return Icons.change_history_rounded;
      case MapDecorationKind.hollowDiamond:
        return Icons.diamond_rounded;
      case MapDecorationKind.star:
        return Icons.star_rounded;
      case MapDecorationKind.pentagon:
        return Icons.pentagon_rounded;
      case MapDecorationKind.hexagon:
        return Icons.hexagon_rounded;
      case MapDecorationKind.heart:
        return Icons.favorite_rounded;
      case MapDecorationKind.cross:
        return Icons.add_rounded;
    }
  }

  String _shapeKindLabel(MindMapProvider p, MapDecorationKind k) {
    switch (k) {
      case MapDecorationKind.polyline:
        return p.t('shape.polyline');
      case MapDecorationKind.line:
        return p.t('shape.line');
      case MapDecorationKind.arrow:
        return p.t('shape.arrow');
      case MapDecorationKind.wavyLine:
        return p.t('shape.wavyLine');
      case MapDecorationKind.rectangle:
        return p.t('shape.hollowRect');
      case MapDecorationKind.filledRectangle:
        return p.t('shape.rect');
      case MapDecorationKind.ellipse:
        return p.t('shape.ellipse');
      case MapDecorationKind.hollowCircle:
        return p.t('shape.hollowCircle');
      case MapDecorationKind.hollowTriangle:
        return p.t('shape.hollowTriangle');
      case MapDecorationKind.hollowDiamond:
        return p.t('shape.hollowDiamond');
      case MapDecorationKind.circle:
        return p.t('shape.circle');
      case MapDecorationKind.star:
        return p.t('shape.star');
      case MapDecorationKind.pentagon:
        return p.t('shape.pentagon');
      case MapDecorationKind.hexagon:
        return p.t('shape.hexagon');
      case MapDecorationKind.heart:
        return p.t('shape.heart');
      case MapDecorationKind.cross:
        return p.t('shape.cross');
    }
  }

  /// 色スウォッチ 1 個 (タップで onTap)。
  Widget _shapeColorSwatch(int rgb, bool selected, VoidCallback onTap) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        width: 22,
        height: 22,
        margin: const EdgeInsets.symmetric(horizontal: 3),
        decoration: BoxDecoration(
          color: Color(0xFF000000 | rgb),
          shape: BoxShape.circle,
          border: Border.all(
            color: selected ? const Color(0xFF4FC3F7) : Colors.white24,
            width: selected ? 2.5 : 1,
          ),
        ),
      ),
    );
  }

