            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                // 1 段目: 種類アイコン (横スクロール) + × 終了
                Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Flexible(
                      child: SingleChildScrollView(
                        scrollDirection: Axis.horizontal,
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            for (final k in _shapeKindsOrder)
                              Padding(
                                padding:
                                    const EdgeInsets.symmetric(horizontal: 2),
                                child: InkWell(
                                  onTap: () => setState(() {
                                    _drawingDecorationKind = k;
                                    // 次にボタンを押した時はこの種類で始める。
                                    _lastShapeKind = k;
                                    // 種類を変えたら作りかけの折れ線は捨てる。
                                    _polylinePoints.clear();
                                    _polylineCursor = null;
                                  }),
                                  borderRadius: BorderRadius.circular(8),
                                  child: Container(
                                    width: 36,
                                    height: 36,
                                    decoration: BoxDecoration(
                                      color: _drawingDecorationKind == k
                                          ? const Color(0xFF43B97F)
                                              .withValues(alpha: 0.3)
                                          : Colors.white
                                              .withValues(alpha: 0.05),
                                      borderRadius: BorderRadius.circular(8),
                                      border: Border.all(
                                          color: _drawingDecorationKind == k
                                              ? const Color(0xFF43B97F)
                                              : Colors.white12),
                                    ),
                                    child: Icon(_shapeKindIcon(k),
                                        size: 20,
                                        color: _drawingDecorationKind == k
                                            ? const Color(0xFF7BE0AE)
                                            : Colors.white70),
                                  ),
                                ),
                              ),
                          ],
                        ),
                      ),
                    ),
                    const SizedBox(width: 6),
                    // ── 中空にする札 (= ユーザー要望: 図形は 1 つにまとめ、
                    //    中空にできるボタンを付ける)。 線の仲間には効かない。 ──
                    Tooltip(
                      message: provider.t('shape.hollow'),
                      child: InkWell(
                        onTap: () =>
                            setState(() => _shapeHollow = !_shapeHollow),
                        borderRadius: BorderRadius.circular(8),
                        child: Container(
                          height: 36,
                          padding: const EdgeInsets.symmetric(horizontal: 8),
                          decoration: BoxDecoration(
                            color: _shapeHollow
                                ? const Color(0xFF43B97F).withValues(alpha: 0.3)
                                : Colors.white.withValues(alpha: 0.05),
                            borderRadius: BorderRadius.circular(8),
                            border: Border.all(
                                color: _shapeHollow
                                    ? const Color(0xFF43B97F)
                                    : Colors.white12),
                          ),
                          child: Row(mainAxisSize: MainAxisSize.min, children: [
                            Icon(
                                _shapeHollow
                                    ? Icons.circle_outlined
                                    : Icons.circle_rounded,
                                size: 18,
                                color: _shapeHollow
                                    ? const Color(0xFF7BE0AE)
                                    : Colors.white70),
                            const SizedBox(width: 4),
                            Text(provider.t('shape.hollow'),
                                style: TextStyle(
                                    fontSize: 11,
                                    fontWeight: FontWeight.w700,
                                    color: _shapeHollow
                                        ? const Color(0xFF7BE0AE)
                                        : Colors.white54)),
