    final anchor = _customButtonAnchor(at);
    await showDialog<void>(
      context: context,
      barrierColor: Colors.black.withValues(alpha: anchor == null ? 0.54 : 0.25),
      builder: (dctx) => _positionNearAnchor(
        dctx,
        anchor,
        StatefulBuilder(
        builder: (dctx, setS) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E2E),
          // 近くに出す時は Positioned の幅いっぱいに広げる (既定の余白を消す)。
          insetPadding: anchor == null
              ? const EdgeInsets.symmetric(horizontal: 40, vertical: 24)
              : EdgeInsets.zero,
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
          title: Row(children: [
            const Icon(Icons.camera_alt_rounded,
                color: Color(0xFFE1306C), size: 20),
            const SizedBox(width: 8),
            Expanded(
              child: Text(provider.t('insta.landingTitle'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 15,
                      fontWeight: FontWeight.w700)),
            ),
          ]),
          content: SizedBox(
            width: 320,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              for (final e in const [
                ('home', 'insta.home', Icons.home_rounded),
                ('dm', 'insta.dm', Icons.send_rounded),
                ('profile', 'insta.profile', Icons.person_rounded),
              ])
                RadioListTile<String>(
                  value: e.$1,
                  groupValue: sel,
                  onChanged: (v) => setS(() => sel = v ?? 'home'),
                  dense: true,
                  activeColor: const Color(0xFFE1306C),
                  title: Row(children: [
                    Icon(e.$3, size: 16, color: Colors.white70),
                    const SizedBox(width: 8),
                    Text(provider.t(e.$2),
                        style: const TextStyle(
                            color: Colors.white, fontSize: 13)),
                  ]),
                ),
              // プロフィールは URL にユーザー名が要るので、 選んだ時だけ
              // 入力欄を出す。
              if (sel == 'profile')
                Padding(
                  padding: const EdgeInsets.only(top: 4, left: 8, right: 8),
                  child: TextField(
                    controller: nameCtrl,
                    autofocus: true,
                    style: const TextStyle(color: Colors.white, fontSize: 13),
                    decoration: InputDecoration(
                      prefixText: '@ ',
                      prefixStyle: const TextStyle(
                          color: Colors.white38, fontSize: 13),
                      hintText: provider.t('insta.usernameHint'),
                      hintStyle: const TextStyle(
                          color: Colors.white24, fontSize: 12),
                      enabledBorder: const UnderlineInputBorder(
                          borderSide: BorderSide(color: Colors.white24)),
                      focusedBorder: const UnderlineInputBorder(
                          borderSide: BorderSide(color: Color(0xFFE1306C))),
                    ),
                  ),
                ),
            ]),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            TextButton(
              onPressed: () {
                // 先頭の @ と URL 形式の貼り付けを許容して整える。
                var name = nameCtrl.text.trim();
                if (name.startsWith('@')) name = name.substring(1);
                if (name.contains('/')) {
                  name = name
                      .split('/')
                      .where((s) => s.isNotEmpty)
                      .last
                      .split('?')
                      .first;
                }
                setState(() {
                  _instagramLanding = sel;
                  _instagramUsername = name;
                });
                _persistInstagramLanding();
                Navigator.of(dctx).pop();
              },
              child: Text(provider.t('btn.save'),
                  style: const TextStyle(color: Color(0xFFE1306C))),
            ),
          ],
        ),
        ),
        const Size(380, 330),
      ),
    );
    nameCtrl.dispose();
  }

