  void _openSoundCloudSearch(BuildContext ctx, MindMapProvider provider) async {
    final artistCtrl = TextEditingController();
    final trackCtrl = TextEditingController();
    final composerCtrl = TextEditingController();

    await showDialog<void>(
      context: ctx,
      builder: (dctx) {
        // openMode: 'full' = 通常のフルスクリーン WebView、'pip' = ミニ PiP
        // ユーザーが「作業しながら音だけ聞きたい」場合は 'pip' を選ぶ。
        Future<void> doSearch({String openMode = 'full'}) async {
          final artist = artistCtrl.text.trim();
          final track = trackCtrl.text.trim();
          final producer = composerCtrl.text.trim();
          // ── 検索クエリ構築 ──
          // プロデューサー名は "prod. <name>" の形でクエリに含める。
          // ヒップホップ / 電子音楽の SoundCloud では曲名末尾に
          // 「(prod. ProducerName)」と書く慣習が広く浸透しており、
          // 「prod. xxx」をフルテキスト検索すると、その人がプロデュース
          // した曲だけを高精度で絞り込める。
          final parts = <String>[];
          if (artist.isNotEmpty) parts.add(artist);
          if (track.isNotEmpty) parts.add(track);
          if (producer.isNotEmpty) parts.add('prod. $producer');
          final query = parts.join(' ');
          // SoundCloud は URL パラメータでの言語指定をサポートしないが、
          // 将来対応する場合に備えて localizeSoundcloudUrl を経由させる。
          final url = provider.localizeSoundcloudUrl(query.isEmpty
              ? 'https://soundcloud.com/'
              : 'https://soundcloud.com/search/sounds?q=${Uri.encodeQueryComponent(query)}');
          if (dctx.mounted) Navigator.of(dctx).pop();
          if (!mounted) return;
          if (openMode == 'pip') {
            // ミニ PiP で開く: 画面隅に小さく浮かべて作業しながら音楽を流せる。
            // 畳むと音だけ流れる "音楽コントロール" 状態に。
            final title = query.isEmpty ? 'SoundCloud' : 'SoundCloud: $query';
            _openInPiP(url, title: title);
          } else {
            // 通常のフルスクリーン WebView で開く
            _showWebDialog(context, url);
          }
        }

        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E1E),
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
          title: Row(children: [
            const Icon(Icons.headphones_rounded,
                color: Color(0xFFFFB347), size: 20),
            const SizedBox(width: 8),
            Text(provider.t('soundcloud.title'),
                style: const TextStyle(
                    color: Colors.white,
                    fontSize: 15,
                    fontWeight: FontWeight.w700)),
          ]),
          content: SizedBox(
            width: 360,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(provider.t('soundcloud.hint'),
                    style:
                        const TextStyle(color: Colors.white54, fontSize: 11)),
                const SizedBox(height: 12),
                _scTextField(provider.t('soundcloud.artist'),
                    Icons.person_rounded, artistCtrl),
                const SizedBox(height: 8),
                _scTextField(provider.t('soundcloud.track'),
                    Icons.music_note_rounded, trackCtrl),
                const SizedBox(height: 8),
                _scTextField(provider.t('soundcloud.composer'),
                    Icons.edit_note_rounded, composerCtrl,
                    autofocusOnEnter: true, onSubmit: () => doSearch()),
                const SizedBox(height: 6),
                // 作曲家入力欄の補足: SoundCloud には作曲家の専用フィールドが
                // 無いので、入力された作曲家名はクエリに連結されてフルテキスト
                // 検索される (説明文・タイトル等にマッチすればヒット) こと
                // を明示する。
                Text(provider.t('soundcloud.composerNote'),
                    style:
                        const TextStyle(color: Colors.white38, fontSize: 10)),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white70)),
            ),
            // PiP で開く: 画面隅に小さく浮かべて作業しながら音だけ流したい時用
            OutlinedButton.icon(
              style: OutlinedButton.styleFrom(
                  side: const BorderSide(color: Color(0xFFFFB347)),
                  foregroundColor: const Color(0xFFFFB347)),
              onPressed: () => doSearch(openMode: 'pip'),
              icon: const Icon(Icons.picture_in_picture_alt_rounded, size: 16),
              label: Text(provider.t('btn.openInPiP')),
            ),
            ElevatedButton.icon(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFFFB347),
                  foregroundColor: Colors.black),
              onPressed: () => doSearch(),
              icon: const Icon(Icons.search_rounded, size: 16),
              label: Text(provider.t('soundcloud.search')),
            ),
          ],
        );
      },
    );
  }

  /// SoundCloud / Spotify 検索ダイアログ用の入力欄ヘルパ
  Widget _scTextField(String label, IconData icon, TextEditingController ctrl,
      {bool autofocusOnEnter = false,
      Future<void> Function()? onSubmit,
      Color color = const Color(0xFFFFB347)}) {
    return TextField(
      controller: ctrl,
      style: const TextStyle(color: Colors.white, fontSize: 13),
      textInputAction:
          autofocusOnEnter ? TextInputAction.search : TextInputAction.next,
      onSubmitted: onSubmit == null ? null : (_) => onSubmit(),
      decoration: InputDecoration(
        prefixIcon: Icon(icon, color: color, size: 18),
        labelText: label,
        labelStyle: const TextStyle(color: Colors.white54, fontSize: 12),
        filled: true,
        fillColor: Colors.white.withValues(alpha: 0.05),
        border: OutlineInputBorder(
            borderRadius: BorderRadius.circular(8),
            borderSide: BorderSide.none),
        contentPadding:
            const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
      ),
    );
  }

