  /// ─── Spotify 検索ダイアログ ─────────────────────────────────────────────
  /// Spotify Web Player の検索 URL は
  /// `https://open.spotify.com/search/<keyword>` 形式。
  /// SoundCloud と同じく 3 つの入力欄 (歌手 / 作品 / プロデューサー) を
  /// 用意し、入力された値をスペース連結したクエリで検索する。
  /// プロデューサー欄は SoundCloud と異なり "prod." ヘルパは付けない:
  /// Spotify は商業楽曲が中心で、トラック名に `(prod. xxx)` の慣習が
  /// 浸透していないため、生のキーワードでアーティスト / アルバム検索した
  /// ほうがヒット率が高い。
  void _openSpotifySearch(BuildContext ctx, MindMapProvider provider) async {
    final artistCtrl = TextEditingController();
    final trackCtrl = TextEditingController();
    final producerCtrl = TextEditingController();
    const spotifyGreen = Color(0xFF1DB954);

    await showDialog<void>(
      context: ctx,
      builder: (dctx) {
        Future<void> doSearch({String openMode = 'full'}) async {
          final artist = artistCtrl.text.trim();
          final track = trackCtrl.text.trim();
          final producer = producerCtrl.text.trim();
          // ── 検索クエリ ──
          // Spotify Web の検索 URL は path セグメントにクエリを乗せる:
          //   https://open.spotify.com/search/<encoded keyword>
          // 全部空ならトップページ (https://open.spotify.com/) に飛ばす。
          final parts = <String>[];
          if (artist.isNotEmpty) parts.add(artist);
          if (track.isNotEmpty) parts.add(track);
          // Spotify では "prod. xxx" 慣習がほぼ無いため、プロデューサー名は
          // 単純なキーワードとして連結する。Spotify の検索はアーティスト名・
          // アルバム名・作家クレジットも検索対象なので、この単純連結で
          // 大抵ヒットする。
          if (producer.isNotEmpty) parts.add(producer);
          final query = parts.join(' ');
          // Spotify の国際化URL `intl-<lang>/` プレフィックスを挿入。
          // 例: https://open.spotify.com/intl-en/search/<query>
          // これでユーザーがアプリで選択した言語の Spotify Web UI で開ける
          // (Spotify が対応していない言語の場合は intl- 無しのデフォルト URL)。
          final url = provider.localizeSpotifyUrl(query.isEmpty
              ? 'https://open.spotify.com/'
              : 'https://open.spotify.com/search/${Uri.encodeComponent(query)}');
          if (dctx.mounted) Navigator.of(dctx).pop();
          if (!mounted) return;
          if (openMode == 'pip') {
            final title = query.isEmpty ? 'Spotify' : 'Spotify: $query';
            _openInPiP(url, title: title);
          } else {
            _showWebDialog(context, url);
          }
        }

        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E1E),
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
          title: Row(children: [
            const Icon(Icons.music_note_rounded, color: spotifyGreen, size: 20),
            const SizedBox(width: 8),
            Text(provider.t('spotify.title'),
                style: const TextStyle(
                    color: Colors.white,
                    fontSize: 15,
                    fontWeight: FontWeight.w700)),
          ]),
          content: SizedBox(
            width: 360,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(provider.t('spotify.hint'),
                    style:
                        const TextStyle(color: Colors.white54, fontSize: 11)),
                const SizedBox(height: 12),
                _scTextField(provider.t('spotify.artist'), Icons.person_rounded,
                    artistCtrl,
                    color: spotifyGreen),
                const SizedBox(height: 8),
                _scTextField(
                    provider.t('spotify.track'), Icons.album_rounded, trackCtrl,
                    color: spotifyGreen),
                const SizedBox(height: 8),
                _scTextField(provider.t('spotify.producer'),
                    Icons.edit_note_rounded, producerCtrl,
                    color: spotifyGreen,
                    autofocusOnEnter: true,
                    onSubmit: () => doSearch()),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white70)),
            ),
            // PiP で開く: 画面隅に小さく浮かべて作業しながら音だけ流したい時用
            OutlinedButton.icon(
              style: OutlinedButton.styleFrom(
                  side: const BorderSide(color: spotifyGreen),
                  foregroundColor: spotifyGreen),
              onPressed: () => doSearch(openMode: 'pip'),
              icon: const Icon(Icons.picture_in_picture_alt_rounded, size: 16),
              label: Text(provider.t('btn.openInPiP')),
            ),
            ElevatedButton.icon(
              style: ElevatedButton.styleFrom(
                  backgroundColor: spotifyGreen, foregroundColor: Colors.black),
              onPressed: () => doSearch(),
              icon: const Icon(Icons.search_rounded, size: 16),
              label: Text(provider.t('soundcloud.search')),
            ),
          ],
        );
      },
    );
  }

  /// ─── 計算機（フローティング）(Ctrl+M) ────────────────────────────────────────
  /// Overlay 上に浮かぶ非モーダル・ドラッグ移動可能なパネル。
  /// ダイアログと違って他画面の操作をブロックしない。
  /// 物理キーボード入力: 0-9, ., + - * /, Enter(=), Backspace, Esc(クリア)
  void _showCalculatorDialog(BuildContext ctx, MindMapProvider provider) {
    // ── 計算機は関数電卓に統一 (= ユーザー要望: フローティングモードと
    //    普通に開く時とで UI が異なって困惑する) ──
    _showScientificCalculatorDialog(ctx, provider);
