  // 旧・基本計算機 (現在は未使用。 関数電卓に統一)。
  // ignore: unused_element
  void _showBasicCalculatorDialogLegacy(
      BuildContext ctx, MindMapProvider provider) {
    if (_calculatorOverlay != null) return; // 既に開いていれば無視
    final screen = MediaQuery.of(ctx).size;
    // 画面右寄り、上端から 80px の位置に初期配置（邪魔になりにくい）
    final initialOffset = Offset(
      (screen.width - 320).clamp(20.0, screen.width - 20.0),
      80.0,
    );
    _calculatorOverlay = OverlayEntry(
      builder: (_) => _FloatingCalculator(
        hidden: _shouldHideFloatingTools,
        provider: provider,
        initialOffset: initialOffset,
        onClose: () {
          _calculatorOverlay?.remove();
          _calculatorOverlay = null;
          // メインキャンバスにフォーカスを戻してショートカットキーを復活させる
          if (mounted) _keyboardFocusNode.requestFocus();
        },
      ),
    );
    Overlay.of(ctx, rootOverlay: true).insert(_calculatorOverlay!);
  }

  /// ─── ストップウォッチ（フローティング）(Ctrl+T) ─────────────────────────────
  /// Overlay 上に浮かぶ非モーダル・ドラッグ移動可能なパネル。
  /// スタート/ストップ/リセット/ラップ機能付き。Timer.periodic で 50ms ごとに更新。
  void _showStopwatchDialog(BuildContext ctx, MindMapProvider provider) {
    if (_stopwatchOverlay != null) return; // 既に開いていれば無視
    final screen = MediaQuery.of(ctx).size;
    // 画面右寄り、上から 90px（計算機と重ならないようオフセット）
    final initialOffset = Offset(
      (screen.width - 360).clamp(20.0, screen.width - 20.0),
      110.0,
    );
    _stopwatchOverlay = OverlayEntry(
      builder: (_) => _FloatingStopwatch(
        hidden: _shouldHideFloatingTools,
        provider: provider,
        initialOffset: initialOffset,
        onClose: () {
          _stopwatchOverlay?.remove();
          _stopwatchOverlay = null;
          // メインキャンバスにフォーカスを戻してショートカットキーを復活させる
          if (mounted) _keyboardFocusNode.requestFocus();
        },
      ),
    );
    Overlay.of(ctx, rootOverlay: true).insert(_stopwatchOverlay!);
  }

  /// ─── 音声入力 (Speech-to-Text) ─────────────────────────────────────────
  /// マイクで話した内容を認識し、 区切り語で分割して複数ノードを生成する。
  /// 認識言語はアプリの表示言語 (`provider.speechLocaleId`) に追従する。
  void _showVoiceInputDialog(BuildContext ctx, MindMapProvider provider) {
    showDialog<void>(
      context: ctx,
      barrierDismissible: true,
      builder: (dctx) => _VoiceInputDialog(
        provider: provider,
        onCreate: (titles) {
          Navigator.pop(dctx);
          if (!mounted || titles.isEmpty) return;
          if (provider.currentPage.pageType == 'bookshelf') {
            () async {
              final texts = titles
                  .map((t) => t.trim())
                  .where((t) => t.isNotEmpty)
                  .toList();
              if (!await _confirmGalleryExpand(
                  context, provider, texts.length)) {
                return;
              }
              var added = 0;
              for (final text in texts) {
                provider.addTextNoteToBookshelf(text);
                added++;
              }
              if (added > 0) {
                _appSnack(
                    context,
                    SnackBar(
                      backgroundColor: const Color(0xFF43B97F),
                      content: Text(
                        provider
                            .t('bookshelf.added')
                            .replaceAll('{n}', '$added'),
                        style: const TextStyle(color: Colors.white),
                      ),
                      duration: const Duration(seconds: 2),
                    ));
              }
            }();
            return;
          }
          // 画面中央 (canvas 座標) を求めてノードを縦に積む
          final sz =
              View.of(context).physicalSize / View.of(context).devicePixelRatio;
          final center = _globalToCanvas(Offset(sz.width / 2, sz.height / 2),
              _ctrlFor(provider.currentPage.id));
          final ids =
              provider.addNodesFromVoice(titles, center - const Offset(80, 21));
          if (ids.isNotEmpty) {
            _appSnack(
                context,
                SnackBar(
                  backgroundColor: const Color(0xFF43B97F),
                  content: Text(
                    provider
                        .t('voice.created')
                        .replaceAll('{count}', '${ids.length}'),
                    style: const TextStyle(color: Colors.white),
                  ),
                  duration: const Duration(seconds: 2),
                ));
          }
        },
      ),
    );
  }

  /// ─── 集中ロック (Android のみ) ─────────────────────────────────────────
  /// 設定した時間だけ全画面をロックして集中するためのダイアログ。
  ///
  /// プリセット (5/15/25/45/60 分) ＋ カスタム (1〜180 分スライダー) から
  /// 時間を選んで「開始」 すると、 全画面の `_FocusLockOverlay` を表示する。
  ///
  /// 注意: 通常の Flutter アプリは OS 全体をロックできない (= ホームボタンや
  ///   ナビゲーションを完全に塞ぐには Device Admin / キオスクモードが必要)。
  ///   ここで実装するのは「アプリ内の全画面ロック」 で、 戻る (back) は
  ///   PopScope で無効化し、 システムバーも没入モードで隠す。 緊急時は
  ///   長押しで早期解除できる。
  /// ジオフェンスの定期チェック: 現在地と基準点の距離を測り、 設定した契機
  /// (半径内に入った / 半径外に出た) のエッジで集中ロックを起動する。
  /// 機能が無効・基準点未設定・位置取得失敗の時は何もしない。
  Future<void> _checkGeofence() async {
    if (!mounted || _geofenceChecking) return;
    final p = context.read<MindMapProvider>();
    if (!p.geofenceLockEnabled || !p.geofenceHasPoint) {
      _geofenceWasInside = null;
    }
  }

  Future<void> _setGeofenceToCurrentLocation(MindMapProvider provider) async {
    if (!mounted) return;
    _appSnack(
        context,
        SnackBar(
            content: Text(provider.t('geo.serviceDisabled')),
            duration: const Duration(seconds: 2)));
  }

  Future<void> _pickGeofenceOnMap(MindMapProvider provider) async {
    final initLat = provider.geofenceLat ?? 35.681236; // 既定: 東京駅
    final initLon = provider.geofenceLon ?? 139.767125;
    await showDialog<void>(
      context: context,
      useRootNavigator: false,
      builder: (dctx) => Dialog(
        backgroundColor: const Color(0xFF1E1E32),
        insetPadding: const EdgeInsets.all(16),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        child: SizedBox(
          width: 600,
          height: 520,
          child: _MapPickerDialog(
            initialLat: initLat,
            initialLon: initLon,
            provider: provider,
            onPick: (lat, lon) async {
              Navigator.of(dctx).pop();
              await provider.setGeofencePoint(lat, lon);
            },
          ),
        ),
      ),
    );
  }

  Future<int?> _pickClockMinuteDial(BuildContext ctx, int initialMin,
      {String? helpText}) async {
    final safe = initialMin.clamp(0, 1439).toInt();
    final picked = await showTimePicker(
      context: ctx,
      initialTime: TimeOfDay(hour: safe ~/ 60, minute: safe % 60),
      initialEntryMode: TimePickerEntryMode.dial,
      helpText: helpText,
    );
    if (picked == null) return null;
    return picked.hour * 60 + picked.minute;
  }

  void _showFocusLockDialog(BuildContext ctx, MindMapProvider provider) {
    if (_focusLockOverlay != null) return; // 既にロック中
    // プリセット分数 (ユーザー要望: 5 / 15 / 30 / 60 分)。
    const presets = <int>[5, 15, 60];
    // プリセットは「選択」ではなく加算ボタンとして扱う。0分から始めることで
    // +5 → +5 → +15 のように、押した回数どおりの合計時間になる。
    int selectedMin = 0;
    // 数値入力用 (ユーザー要望: カスタムを押さなくても直接分数を指定できる)。
    final minCtrl = TextEditingController(text: '$selectedMin');
    final taskCtrl = TextEditingController();

    showDialog<void>(
      context: ctx,
      barrierColor: Colors.black54,
      builder: (dctx) => StatefulBuilder(
        builder: (dctx2, setS) {
          // ── 集中ロックのチップ ──
          // Material 3 の ChoiceChip は backgroundColor (M2 プロパティ) を
          // 無視して白系のサーフェス色になり、 未選択チップが「白背景に白文字」
          // で見えなくなる問題があった (ユーザー報告)。 配色を完全に制御する
          // 自前チップに置き換えて、 選択/未選択どちらも文字がはっきり見える
          // ようにする。
          Widget chip({
            required String label,
            required bool selected,
            required VoidCallback onTap,
            IconData? icon,
          }) {
            return InkWell(
              onTap: onTap,
              borderRadius: BorderRadius.circular(10),
              child: Container(
                padding: EdgeInsets.symmetric(
                    horizontal: icon == null ? 14 : 6, vertical: 8),
                decoration: BoxDecoration(
                  color: selected
                      ? const Color(0xFFEF5350)
                      : const Color(0xFF2A2A3E),
                  borderRadius: BorderRadius.circular(10),
                  border: Border.all(
                    color: selected ? const Color(0xFFEF5350) : Colors.white24,
                  ),
                ),
                child: icon != null
                    ? Icon(icon, color: Colors.white, size: 18)
                    : Text(
                        label,
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                          color: Colors.white,
                          fontWeight: FontWeight.w600,
                          fontSize: 13,
                        ),
                      ),
              ),
            );
          }

          Widget presetChip(int m) => chip(
                label: '+$m${provider.t('focusLock.minutesSuffix')}',
                selected: false,
                onTap: () => setS(() {
                  selectedMin = (selectedMin + m).clamp(0, 600).toInt();
                  minCtrl.text = '$selectedMin';
                  minCtrl.selection =
                      TextSelection.collapsed(offset: minCtrl.text.length);
                }),
              );

          return Dialog(
            backgroundColor: const Color(0xFF1E1E32),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(18),
            ),
            insetPadding:
                const EdgeInsets.symmetric(horizontal: 24, vertical: 24),
            child: ConstrainedBox(
              constraints: BoxConstraints(
                maxWidth: 420,
                maxHeight: MediaQuery.of(dctx2).size.height * 0.88,
              ),
              child: SingleChildScrollView(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(20, 18, 20, 14),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Row(children: [
                        const Icon(Icons.lock_clock_rounded,
                            color: Color(0xFFEF5350), size: 22),
                        const SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            provider.t('focusLock.dialogTitle'),
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 16,
                                fontWeight: FontWeight.w700),
                          ),
                        ),
                        IconButton(
                          icon: const Icon(Icons.close_rounded,
                              color: Colors.white54, size: 20),
                          onPressed: () => Navigator.pop(dctx),
                        ),
                      ]),
                      const SizedBox(height: 8),
                      Text(
                        provider.t('focusLock.description'),
                        style: const TextStyle(
                            color: Colors.white70, fontSize: 12, height: 1.4),
                      ),
                      const SizedBox(height: 12),
                      // ToDo (タスク) を主役にする (= ユーザー要望: 時刻指定
                      // ではなくタスクベースをメインに)。 並びも先頭に。
                      Row(children: [
                        Expanded(
                          child: chip(
                            label: provider.t('focusLock.modeTasks'),
                            icon: Icons.task_alt_rounded,
                            selected: provider.focusLockMode == 'tasks',
                            onTap: () {
                              provider.setFocusLockMode('tasks');
                              setS(() {});
                            },
                          ),
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: chip(
                            label: provider.t('focusLock.modeTimer'),
                            icon: Icons.timer_rounded,
                            selected: provider.focusLockMode == 'timer',
                            onTap: () {
                              provider.setFocusLockMode('timer');
                              setS(() {});
                            },
                          ),
                        ),
                      ]),
                      const SizedBox(height: 14),
                      if (provider.focusLockMode == 'timer') ...[
                        Row(
                          children: [
                            for (final m in presets) ...[
                              Expanded(child: presetChip(m)),
                              const SizedBox(width: 5),
                            ],
                            Tooltip(
                              message: provider.t('focusLock.reset'),
                              child: SizedBox(
                                width: 38,
                                child: chip(
                                  label: '',
                                  icon: Icons.restart_alt_rounded,
                                  selected: selectedMin == 0,
                                  onTap: () => setS(() {
                                    selectedMin = 0;
                                    minCtrl.text = '0';
                                    minCtrl.selection =
                                        const TextSelection.collapsed(
                                            offset: 1);
                                  }),
                                ),
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 12),
                        // ── 分数の直接指定 (スライダー + 数値入力) ──
                        // ユーザー要望: カスタムを押さなくてもバー / 数値で分数を
                        //   指定できるように、 常時表示にする。
                        Row(
                          children: [
                            Expanded(
                              child: SliderTheme(
                                data: SliderTheme.of(dctx2).copyWith(
                                  activeTrackColor: const Color(0xFFEF5350),
                                  thumbColor: const Color(0xFFEF5350),
                                  inactiveTrackColor:
                                      Colors.white.withValues(alpha: 0.15),
                                ),
                                child: Slider(
                                  min: 0,
                                  max: 600,
                                  value: selectedMin.clamp(0, 600).toDouble(),
                                  onChanged: (v) => setS(() {
                                    selectedMin = v.round();
                                    minCtrl.text = '$selectedMin';
                                    minCtrl.selection = TextSelection.collapsed(
                                        offset: minCtrl.text.length);
                                  }),
                                ),
                              ),
                            ),
                            const SizedBox(width: 8),
                            SizedBox(
                              width: 64,
                              child: TextField(
                                controller: minCtrl,
                                keyboardType: TextInputType.number,
                                textAlign: TextAlign.center,
                                style: const TextStyle(
                                    color: Colors.white,
                                    fontSize: 15,
                                    fontWeight: FontWeight.w700),
                                decoration: InputDecoration(
                                  isDense: true,
                                  contentPadding: const EdgeInsets.symmetric(
                                      vertical: 8, horizontal: 4),
                                  filled: true,
                                  fillColor:
                                      Colors.white.withValues(alpha: 0.07),
                                  border: OutlineInputBorder(
                                    borderRadius: BorderRadius.circular(8),
                                    borderSide: BorderSide.none,
                                  ),
                                ),
                                onChanged: (t) {
                                  final v = int.tryParse(t);
                                  if (v != null) {
                                    setS(() =>
                                        selectedMin = v.clamp(0, 600).toInt());
                                  }
                                },
                              ),
                            ),
                            const SizedBox(width: 4),
                            Text(provider.t('focusLock.minutesSuffix'),
                                style: const TextStyle(
                                    color: Colors.white70, fontSize: 13)),
                          ],
                        ),
                      ] else ...[
                        _buildFocusLockTaskEditor(provider, taskCtrl, setS),
                      ],
                      const SizedBox(height: 14),
                      const Divider(color: Colors.white12, height: 1),
                      const SizedBox(height: 10),
                      // ── 秒表示設定 ──
                      // キー名は hideSeconds だが、現行UI文言に合わせて
                      // true = 秒を表示する、として扱う。
                      // カウントダウンが無いタスク制では意味がないので、
                      // タイマー制の時だけ出す (= ユーザー指摘)。
