  /// 現在保存されている天気の地点名 (なければ null)。
  Future<String?> _currentWeatherCity() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getString('weather_cityName');
  }

  /// 都市名から手早く地点を設定する (ジオコーディング → 予報取得 → 保存)。
  /// 天気パネルと同じ SharedPreferences キーに保存するので、 メニューの
  /// サマリーにも天気パネルにも反映される。
  Future<void> _quickSetWeatherCity(BuildContext sctx, MindMapProvider provider,
      String query, void Function(VoidCallback) setD) async {
    final q = query.trim();
    if (q.isEmpty) return;
    final messenger = ScaffoldMessenger.maybeOf(context);
    _appSnackM(
        messenger,
        SnackBar(
          content: Text(provider.t('clock.searching')),
          duration: const Duration(seconds: 30),
        ));
    try {
      final lang = provider.appLanguage;
      final geoUrl =
          'https://geocoding-api.open-meteo.com/v1/search?name=${Uri.encodeQueryComponent(q)}&count=1&language=$lang&format=json';
      final geoRes = await http.get(Uri.parse(geoUrl));
      if (geoRes.statusCode != 200)
        throw Exception('HTTP ${geoRes.statusCode}');
      final geoData = jsonDecode(geoRes.body) as Map<String, dynamic>;
      final results = geoData['results'] as List<dynamic>?;
      if (results == null || results.isEmpty) {
        messenger?.hideCurrentSnackBar();
        _appSnackM(
            messenger,
            SnackBar(
              backgroundColor: const Color(0xFFE57373),
              content: Text(provider.t('weather.cityNotFound')),
              duration: const Duration(seconds: 3),
            ));
        return;
      }
      final r = (results.first as Map).cast<String, dynamic>();
      final lat = (r['latitude'] as num).toDouble();
      final lon = (r['longitude'] as num).toDouble();
      final name = r['name'] as String? ?? q;
      final admin1 = r['admin1'] as String? ?? '';
      final country = r['country'] as String? ?? '';
      final parts = <String>[name];
      if (admin1.isNotEmpty && admin1 != name) parts.add(admin1);
      if (country.isNotEmpty) parts.add(country);
      final displayName = parts.join(', ');

      // 予報取得 (天気パネルと同一のパラメータ → 同じキャッシュ形式)
      final fcUrl = 'https://api.open-meteo.com/v1/forecast'
          '?latitude=$lat&longitude=$lon'
          '&current_weather=true'
          '&hourly=temperature_2m,precipitation_probability,weather_code'
          '&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max'
          '&timezone=auto'
          '&forecast_days=5';
      final fcRes = await http.get(Uri.parse(fcUrl));
      if (fcRes.statusCode != 200) throw Exception('HTTP ${fcRes.statusCode}');

      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('weather_cityName', displayName);
      await prefs.setDouble('weather_lat', lat);
      await prefs.setDouble('weather_lon', lon);
      await prefs.setString('weather_cache_json_v2', fcRes.body);
      await prefs.setInt(
          'weather_cache_at_ms_v2', DateTime.now().millisecondsSinceEpoch);

      messenger?.hideCurrentSnackBar();
      _appSnackM(
          messenger,
          SnackBar(
            backgroundColor: const Color(0xFF43B97F),
            content: Text('${provider.t('clock.citySet')}: $displayName'),
            duration: const Duration(seconds: 2),
          ));
      // 天気フローティングパネルが開いていれば最新地点で再描画させる
      _weatherOverlay?.markNeedsBuild();
      setD(() {});
    } catch (e) {
      messenger?.hideCurrentSnackBar();
      _appSnackM(
          messenger,
          SnackBar(
            backgroundColor: const Color(0xFFE57373),
            content: Text('${provider.t('weather.fetchFail')}: $e'),
            duration: const Duration(seconds: 3),
          ));
    }
  }

  /// ─── 高度な関数電卓（フローティング）(Ctrl+Shift+M) ─────────────────────
  /// sin/cos/tan, log, ln, exp, sqrt, x², 括弧, π, e などに対応
  void _showScientificCalculatorDialog(
      BuildContext ctx, MindMapProvider provider) {
    if (_sciCalcOverlay != null) return;
    final screen = MediaQuery.of(ctx).size;
    final initialOffset = Offset(
      (screen.width - 360).clamp(20.0, screen.width - 20.0),
      60.0,
    );
    _sciCalcOverlay = OverlayEntry(
      builder: (_) => _FloatingScientificCalculator(
        hidden: _shouldHideFloatingTools,
        provider: provider,
        initialOffset: initialOffset,
        onClose: () {
          _sciCalcOverlay?.remove();
          _sciCalcOverlay = null;
          // メインキャンバスにフォーカスを戻してショートカットキーを復活させる
          if (mounted) _keyboardFocusNode.requestFocus();
        },
        // アプリの外 (別ウィンドウ) に出す (= ユーザー要望)。 WebView を
        // 使わない純 Flutter UI なのでサブウィンドウでも動く。
        onPopOut: !_isDesktop
            ? null
            : () {
                _sciCalcOverlay?.remove();
                _sciCalcOverlay = null;
                unawaited(_openPopOutWindow(provider, kind: 'calc'));
              },
      ),
    );
    Overlay.of(ctx, rootOverlay: true).insert(_sciCalcOverlay!);
  }

  /// URL（YouTube動画 or チャンネル）を新規ノードとして現在のマップに追加
  /// - 動画 → 単一ノードを作成して youtubeUrl をセット、タイトル自動取得
  /// - チャンネル → モード選択ダイアログ（動画/ショート/両方）→ _loadPlaylistVideos
  /// 既存ノードと重ならない埋め込み位置を返す (= ユーザー要望: 独立した動画を
  /// 複数埋め込む時、 同じ場所に重なって埋め込まれず、 隣のブロックへ並ぶように)。
  /// [desired] を起点に右→下へ走査し、 最初に空いている位置を返す。
  Offset _nonOverlappingEmbedPos(MindMapProvider provider, Offset desired,
      {double w = 168, double h = 132}) {
    final nodes = provider.currentPage.nodes.values.toList();
    if (nodes.isEmpty) return desired;
    bool overlaps(Offset p) {
      final r = Rect.fromLTWH(p.dx, p.dy, w, h);
      for (final n in nodes) {
        final nr = Rect.fromLTWH(
            n.position.dx, n.position.dy, n.width, n.visualHeight);
        // わずかに縮めて、 ぴったり隣接は「重なり」 とみなさない。
        if (r.overlaps(nr.deflate(2))) return true;
      }
      return false;
    }

    if (!overlaps(desired)) return desired;
    const stepX = 188.0; // 1 列ぶん (幅 + 余白)
    const stepY = 156.0; // 1 行ぶん (高さ + 余白)
    for (int row = 0; row < 60; row++) {
      for (int col = 0; col < 60; col++) {
        if (row == 0 && col == 0) continue; // desired は埋まっているので除く
        final cand = Offset((desired.dx + col * stepX).clamp(0.0, 20000.0),
            (desired.dy + row * stepY).clamp(0.0, 20000.0));
        if (!overlaps(cand)) return cand;
      }
    }
    return desired;
  }

  Future<void> _embedYoutubeUrlAsNode(
      String url, MindMapProvider provider) async {
    if (!mounted) return;
    // Windows の「この動画以降をすべて」 は改行区切りの 1 バッチで渡す。
    // ギャラリー側は同じ形式をまとめて表紙化し、通常マップ側はここで順番に
    // 展開する。個別 callback の同時実行による重複配置・表紙欠落を防ぐ。
    final batchUrls = url
        .split(RegExp(r'\s+'))
        .map((value) => value.trim())
        .where((value) => value.isNotEmpty)
        .toList(growable: false);
    if (batchUrls.length > 1) {
      for (final batchUrl in batchUrls) {
        if (!mounted) return;
        await _embedYoutubeUrlAsNode(batchUrl, provider);
      }
      return;
    }
    if (batchUrls.length == 1) url = batchUrls.single;
    // 新規ノードの配置位置：現在の画面中央のキャンバス座標
    final pageId = provider.currentPage.id;
    final ctrl = _ctrlFor(pageId);
    final s = View.of(context).physicalSize / View.of(context).devicePixelRatio;
    final mat = ctrl.value;
    final scale = mat.getMaxScaleOnAxis();
    final tx = mat.getTranslation().x;
    final ty = mat.getTranslation().y;
    final cx = (s.width / 2 - tx) / scale;
    final cy = (s.height / 2 - ty) / scale;
    // 画面中央を起点に、 既存ノードと重ならない位置を探す (= 複数埋め込みで
    //   同じ場所に重なるのを防ぐ)。
    final pos = _nonOverlappingEmbedPos(provider, Offset(cx - 80, cy - 21));

    // まず動画URLか判定
    final videoId = NodeWidget.extractVideoId(url);
    if (videoId != null) {
      // ── 再生リスト視聴中の動画 (watch?v=…&list=…) ──
      // 「この動画だけ埋め込むか、 リスト内の動画をすべて埋め込むか」 を
      // 選択できるようにする (= ユーザー要望)。 Mix (RD…) やウォッチリスト
      // (WL/LL) は /playlist ページから一覧を取得できないため、 代わりに
      // 「視聴中の動画のみ埋め込むか」 の確認を出す (= ユーザー要望)。
      final embedListId = _embeddablePlaylistIdOf(url);
      if (embedListId != null) {
        final choice = await _askEmbedThisOrWholeList(provider);
        if (!mounted || choice == null) return;
        if (choice == 'list') {
          // リスト全体 → 親ノード + 子動画ノード群として一括取り込み。
          final parent = provider.addNodeAtCenterReturning(pos);
          _loadPlaylistVideos(embedListId, parent, provider,
              originalUrl:
                  'https://www.youtube.com/playlist?list=$embedListId');
          return;
        }
        // 'one' → 下の単一動画埋め込みへフォールスルー。
        // list= を落とした単一動画 URL に正規化する (残したままだと
        // ノードからの再生時にリスト全体が自動再生されてしまう)。
        // 再生位置 (t=/start=) は維持する。
        url = _stripListParamKeepTime(url);
      } else if (_unfetchableListIdOf(url) != null) {
        // ── Mix (RD…) / WL / LL 視聴中 ──
        // 一覧を取得できないため、 視聴中の動画のみ埋め込むかを確認する。
        final ok = await _confirmMixListSingleEmbed(provider);
        if (ok != true || !mounted) return;
        url = _stripListParamKeepTime(url);
      }
      // 動画 → 単一ノードを作成
      final newNode = provider.addNodeAtCenterReturning(pos);
      provider.updateNodeYoutube(newNode.id, url);
      _fetchYoutubeTitle(videoId, newNode.id, provider, force: true);
      _appSnack(
          context,
          SnackBar(
            content: Text(provider.t('embed.videoAdded')),
            backgroundColor: const Color(0xFF43B97F),
            duration: const Duration(seconds: 2),
          ));
      return;
    }

    // ── プレイリスト判定 ──
    // YouTube のプレイリストページ (/playlist?list=PLxxx 等) を WebView で
    // 開いている時に + ボタンを押すと、プレイリスト内の動画を一括取得して
    // 親ノード + 子動画ノード群を生成する。チャンネルと同じ仕組み。
    final playlistId = _extractPlaylistId(url);
    if (playlistId != null) {
      final parent = provider.addNodeAtCenterReturning(pos);
      _loadPlaylistVideos(playlistId, parent, provider, originalUrl: url);
      return;
    }

    // チャンネル判定
    final channelInfo = _extractChannelInfo(url);
    if (channelInfo != null) {
      final mode = await _pickChannelMode();
      if (mode == null || !mounted) return;
      provider.setChannelMode(mode);
      // チャンネル親ノードを作成
      final parent = provider.addNodeAtCenterReturning(pos);
      _loadPlaylistVideos(channelInfo.$1, parent, provider,
          customUrl: channelInfo.$2,
          isChannel: true,
          channelMode: mode,
          originalUrl: url);
      return;
    }

    // どちらでもなければ SnackBar で通知
    if (mounted) {
      _appSnack(
          context,
          SnackBar(
            content: Text(provider.t('embed.notSupported')),
            backgroundColor: Colors.redAccent,
            duration: const Duration(seconds: 2),
          ));
    }
  }

  /// 言語設定ダイアログ（UI表示とAI出力の言語を指定）
  ///
  /// ユーザー要望:
  ///   - 上部にスライドバーを置き、 30 言語の中をドラッグで素早く選べる
  ///   - 配色を白基調にして見やすく
  ///   - Enter キーで確定して閉じられるようにする
  void _showLanguageDialog(BuildContext ctx, MindMapProvider provider) {
    final scrollCtrl = ScrollController();
    final focusNode = FocusNode();
    final langs = MindMapProvider.supportedLanguages;
    // ── 言語適用は「閉じる時に 1 回だけ」 (= ユーザー報告: Android で言語切替が
    //   超遅い)。 原因はタップ毎に setAppLanguage が走り、 全文書ツリーの jsonEncode
    //   (保存) + 画面全体 (Consumer) の再ビルドが毎回発生していたこと。
    // ── 2026-06 改善 ── 「直ぐに反映されない」 という要望を受け、 選択毎に軽量適用
    //   (applyAppLanguageLight: 言語切替 + prefs 書き込み + 再ビルドのみ、 ページ名
    //   リネームや _saveToStorage は行わない) して即座に反映する。 重いリネーム/
    //   保存は閉じる時に finalizeAppLanguage で 1 回だけ。 軽量適用が prefs を書く
    //   ので、 選んだ直後にアプリを落としても英語に戻らない。
    final String origLang = provider.appLanguage;
    String pendingLang = provider.appLanguage;
    // 二重に閉じようとしないための印 (閉じる経路が複数あるため)。
    bool closing = false;
    Future<void> applyPendingLang() async {
      // 軽量適用で最終値を確定 (= prefs 書き込み完了 → 永続化保証)。
      await provider.applyAppLanguageLight(pendingLang);
      // 言語が変わったら、 閉じる時に 1 回だけ重い後処理 (ページ名/保存)。
      if (pendingLang != origLang) {
        await provider.finalizeAppLanguage();
      }
    }

    // ── 項目の色は常にヘッダーの色に合わせる (= ユーザー要望: 言語設定の
    //    項目の色はヘッダーに設定したカラーになるように)。 以前はカスタム色を
    //    設定した時だけで、 既定のままだと青 (0xFF1976D2) 固定だった。 ──
    final baseColor = provider.headerColor;
    // 白背景のダイアログで見えるよう、 明るすぎる色だけ少し濃くする。
    final langPrimary = baseColor.computeLuminance() > 0.82
        ? HSLColor.fromColor(baseColor).withLightness(0.5).toColor()
        : baseColor;
    final langOnPrimary = langPrimary.computeLuminance() > 0.45
        ? const Color(0xFF101322)
        : Colors.white;
    final langRouteBg = Color.alphaBlend(
        baseColor.withValues(alpha: 0.34), const Color(0xFF12121E));
    final langDialogBg =
        Color.alphaBlend(baseColor.withValues(alpha: 0.08), Colors.white);
    final langPanelBg = Color.alphaBlend(
        baseColor.withValues(alpha: 0.05), const Color(0xFFF5F7FA));

    // ★ 全画面ルート化 (= ユーザー報告: Android で言語ダイアログのスライダー/
    //   チップ/一覧が一切反応しない問題の修正)。 原因はダイアログ背後にある
    //   WebView の Android プラットフォームビューが、 そのまま重なって配置され
    //   Flutter のダイアログ上のタッチを横取りすること (Windows は webview_windows
    //   で合成方式が違うため発生しない=報告の OS 差と一致)。 不透明な全画面ルート
    //   にすれば背後ルート(=WebView)がオフステージになり、 タッチ横取りが起きず
    //   確実に操作できる。 縦スクロールも保証される。
    Navigator.of(ctx, rootNavigator: true).push(MaterialPageRoute<void>(
      fullscreenDialog: true,
      builder: (dctx) => Scaffold(
        backgroundColor: langRouteBg,
        body: PopScope(
          // canPop:false で全クローズ経路 (システムバック / 閉じる / Enter →
          //   いずれも Navigator.maybePop) をここに集約し、 言語を await で永続化
          //   してから自前で pop する (= 閉じる前に確実に prefs へ書き込む)。
          canPop: false,
          // ★ 先に閉じてから保存する (= ユーザー報告: 言語を切り替えると暗転して
          //   アプリが動作しなくなる) ★
          //   旧実装は `await applyPendingLang()` の**後**に pop していた。
          //   この後処理は全文書ツリーの jsonEncode (保存) を含むので、 ページが
          //   多いと数秒かかり、 その間この暗い全画面ルート (langRouteBg) が
          //   canPop:false のまま残って何も押せなくなる。 保存が例外を投げた
          //   場合は pop に到達せず、 暗転したまま**永久に**戻れなくなっていた。
          //   言語自体は選んだ時点で applyAppLanguageLight が適用・保存済みなので、
          //   先に閉じても失われるものは無い。
          onPopInvokedWithResult: (didPop, _) {
            if (didPop || closing) return;
            closing = true;
            Navigator.of(dctx).pop();
            // 残りの後処理は閉じた後に。 失敗しても画面は既に戻っている。
            unawaited(() async {
              try {
                await applyPendingLang();
              } catch (e) {
                debugPrint('言語の後処理に失敗: $e');
              }
            }());
          },
          child: StatefulBuilder(
            builder: (sctx, setD) {
              int idx = langs.indexOf(pendingLang);
              if (idx < 0) idx = 0;
              final currentCode = langs[idx];

              void scrollToCurrent() {
                if (!scrollCtrl.hasClients) return;
                const rowHeight = 44.0;
                final target = (idx * rowHeight)
                    .clamp(0.0, scrollCtrl.position.maxScrollExtent);
                scrollCtrl.animateTo(
                  target,
                  duration: const Duration(milliseconds: 220),
                  curve: Curves.easeOutCubic,
                );
              }

              return Focus(
                autofocus: true,
                focusNode: focusNode,
                onKeyEvent: (n, ev) {
                  if (ev is KeyDownEvent &&
                      (ev.logicalKey == LogicalKeyboardKey.enter ||
                          ev.logicalKey == LogicalKeyboardKey.numpadEnter)) {
                    // maybePop → PopScope(canPop:false) が言語を永続化してから閉じる。
                    Navigator.maybePop(dctx);
                    return KeyEventResult.handled;
                  }
                  return KeyEventResult.ignored;
                },
                child: AlertDialog(
                  // 内容がはみ出しても必ずスクロールできるように (= 旧 AlertDialog は
                  //   非スクロールで下端が見切れていた)。
                  scrollable: true,
                  backgroundColor: langDialogBg,
                  shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(16)),
                  title: Row(children: [
                    Icon(Icons.language_rounded, color: langPrimary, size: 22),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(provider.t('lang.dialogTitle'),
                          style: const TextStyle(
                              color: Color(0xFF1A1A2E),
                              fontSize: 15,
                              fontWeight: FontWeight.w700)),
                    ),
                  ]),
                  content: SizedBox(
                    width: 320,
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        Text(
                          provider.t('lang.description'),
                          style: const TextStyle(
                              color: Color(0xFF555770), fontSize: 11),
                        ),
                        const SizedBox(height: 10),
                        // ── よく使う言語のクイック選択 (= ユーザー要望: 30 言語の
                        //    スライダーは細かくて狙いにくいので、 日本語など主要言語は
                        //    1 タップで即切替できるチップを上部に置く) ──
                        Wrap(
                          spacing: 6,
                          runSpacing: 6,
                          children: [
                            for (final code in MindMapProvider
                                .supportedLanguages
                                .where(MindMapProvider.isFullyTranslated))
                              Builder(builder: (_) {
                                final selected = pendingLang == code;
                                return InkWell(
                                  borderRadius: BorderRadius.circular(20),
                                  // 選んだら即時に反映 (= ユーザー要望)。
                                  onTap: () {
                                    setD(() => pendingLang = code);
                                    provider.applyAppLanguageLight(code);
                                  },
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(
                                        horizontal: 12, vertical: 7),
                                    decoration: BoxDecoration(
                                      color: selected
                                          ? langPrimary
                                          : const Color(0xFFEEF1F6),
                                      borderRadius: BorderRadius.circular(20),
                                      border: Border.all(
                                          color: selected
                                              ? langPrimary
                                              : const Color(0xFFD0D4E0)),
                                    ),
                                    child: Text(
                                      MindMapProvider.languageDisplayName(code),
                                      style: TextStyle(
                                        fontSize: 12.5,
                                        fontWeight: FontWeight.w700,
                                        color: selected
                                            ? langOnPrimary
                                            : const Color(0xFF1A1A2E),
                                      ),
                                    ),
                                  ),
                                );
                              }),
                          ],
                        ),
                        const SizedBox(height: 12),
                        // ── スライドバー部 (30 言語をドラッグで一気に移動) ──
                        Container(
                          padding: const EdgeInsets.fromLTRB(10, 8, 10, 4),
                          decoration: BoxDecoration(
                            color: langPanelBg,
                            borderRadius: BorderRadius.circular(10),
                            border: Border.all(
                                color: langPrimary.withValues(alpha: 0.18),
                                width: 1),
                          ),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(
                                crossAxisAlignment: CrossAxisAlignment.end,
                                children: [
                                  Expanded(
                                    child: Text(
                                      MindMapProvider.languageDisplayName(
                                          currentCode),
                                      style: const TextStyle(
                                        color: Color(0xFF1A1A2E),
                                        fontSize: 18,
                                        fontWeight: FontWeight.w800,
                                      ),
                                    ),
                                  ),
                                  Text(
                                    '${idx + 1} / ${langs.length}',
                                    style: const TextStyle(
                                      color: Color(0xFF888AA0),
                                      fontSize: 11,
                                      fontFamily: 'monospace',
                                      fontWeight: FontWeight.w600,
                                    ),
                                  ),
                                ],
                              ),
                              SliderTheme(
                                data: SliderTheme.of(sctx).copyWith(
                                  activeTrackColor: langPrimary,
                                  inactiveTrackColor:
                                      langPrimary.withValues(alpha: 0.18),
                                  thumbColor: langPrimary,
                                  overlayColor:
                                      langPrimary.withValues(alpha: 0.18),
                                  valueIndicatorColor: const Color(0xFF1A1A2E),
                                  valueIndicatorTextStyle: const TextStyle(
                                      color: Colors.white,
                                      fontSize: 12,
                                      fontWeight: FontWeight.w700),
                                  showValueIndicator: ShowValueIndicator.always,
                                  trackHeight: 4,
                                ),
                                child: Slider(
                                  min: 0,
                                  max: (langs.length - 1).toDouble(),
                                  divisions: langs.length - 1,
                                  value: idx.toDouble(),
                                  label: MindMapProvider.languageDisplayName(
                                      currentCode),
                                  onChanged: (v) {
                                    final newIdx = v.round();
                                    if (newIdx < 0 || newIdx >= langs.length) {
                                      return;
                                    }
                                    final code = langs[newIdx];
                                    final moved = (newIdx - idx).abs() >= 1;
                                    setD(() => pendingLang = code);
                                    if (moved) scrollToCurrent();
                                  },
                                  // ドラッグ中は per-tap で重くならないよう、 指を離した
                                  //   時に確定言語を即時反映する (= ユーザー要望)。
                                  onChangeEnd: (v) {
                                    final newIdx = v.round();
                                    if (newIdx < 0 || newIdx >= langs.length) {
                                      return;
                                    }
                                    provider
                                        .applyAppLanguageLight(langs[newIdx]);
                                  },
                                ),
                              ),
                            ],
                          ),
                        ),
                        const SizedBox(height: 10),
                        // ── 言語リスト (タップでも選択可) ─────────────
                        Container(
                          constraints: const BoxConstraints(maxHeight: 280),
                          decoration: BoxDecoration(
                            color: langPanelBg,
                            borderRadius: BorderRadius.circular(10),
                            border: Border.all(
                                color: const Color(0xFFD0D4E0), width: 1),
                          ),
                          child: Scrollbar(
                            controller: scrollCtrl,
                            thumbVisibility: true,
                            child: SingleChildScrollView(
                              controller: scrollCtrl,
                              child: Column(
                                children: langs.map((code) {
                                  final isSelected = pendingLang == code;
                                  return InkWell(
                                    // 選んだら即時に反映 (= ユーザー要望)。
                                    onTap: () {
                                      setD(() => pendingLang = code);
                                      provider.applyAppLanguageLight(code);
                                    },
                                    borderRadius: BorderRadius.circular(8),
                                    child: Container(
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 12, vertical: 10),
                                      decoration: BoxDecoration(
                                        color: isSelected
                                            ? langPrimary.withValues(
                                                alpha: 0.10)
                                            : Colors.transparent,
                                        border: Border(
                                          left: BorderSide(
                                            color: isSelected
                                                ? langPrimary
                                                : Colors.transparent,
                                            width: 3,
                                          ),
                                        ),
                                      ),
                                      child: Row(children: [
                                        Icon(
                                          isSelected
                                              ? Icons.check_circle_rounded
                                              : Icons.circle_outlined,
                                          color: isSelected
                                              ? langPrimary
                                              : const Color(0xFFB0B3C7),
                                          size: 18,
                                        ),
                                        const SizedBox(width: 10),
                                        Expanded(
                                          child: Text(
                                            MindMapProvider.languageDisplayName(
                                                code),
                                            style: TextStyle(
                                              color: isSelected
                                                  ? const Color(0xFF1A1A2E)
                                                  : const Color(0xFF333448),
                                              fontSize: 14,
                                              fontWeight: isSelected
                                                  ? FontWeight.w700
                                                  : FontWeight.w500,
                                            ),
                                          ),
                                        ),
                                        if (!MindMapProvider.isFullyTranslated(
                                            code)) ...[
                                          Container(
                                            padding: const EdgeInsets.symmetric(
                                                horizontal: 6, vertical: 2),
                                            decoration: BoxDecoration(
                                              color: const Color(0xFFFF9800)
                                                  .withValues(alpha: 0.15),
                                              borderRadius:
                                                  BorderRadius.circular(6),
                                              border: Border.all(
                                                  color: const Color(0xFFFF9800)
                                                      .withValues(alpha: 0.6),
                                                  width: 1),
                                            ),
                                            child: const Text(
                                              'BETA',
                                              style: TextStyle(
                                                color: Color(0xFFE65100),
                                                fontSize: 9,
                                                fontWeight: FontWeight.w800,
                                                letterSpacing: 0.5,
                                              ),
                                            ),
                                          ),
                                          const SizedBox(width: 6),
                                        ],
                                        Text(
                                          code,
                                          style: const TextStyle(
                                              color: Color(0xFF888AA0),
                                              fontSize: 11,
                                              fontFamily: 'monospace'),
                                        ),
                                      ]),
                                    ),
                                  );
                                }).toList(),
                              ),
                            ),
                          ),
                        ),
                        const SizedBox(height: 8),
                        Text(
                          provider.t('lang.note'),
                          style: const TextStyle(
                              color: Color(0xFF888AA0), fontSize: 10),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          provider.t('lang.enterToClose'),
                          style: TextStyle(
                              color: langPrimary,
                              fontSize: 11,
                              fontWeight: FontWeight.w600),
                        ),
                      ],
                    ),
                  ),
                  actions: [
                    TextButton(
                      // maybePop → PopScope(canPop:false) が言語を永続化してから閉じる。
                      onPressed: () => Navigator.maybePop(dctx),
                      child: Text(provider.t('btn.close'),
                          style: TextStyle(
                              color: langPrimary, fontWeight: FontWeight.w700)),
                    ),
                  ],
                ),
              );
            },
          ),
        ),
      ),
    ));
  }

  /// 「Gemini APIキー未設定」 を知らせ、 ワンタップで設定ダイアログを開ける
  /// SnackBar (= ユーザー要望: 設定への導線を統一)。
  void _showAiKeyMissingSnack(BuildContext ctx, MindMapProvider provider) {
    _appSnack(
      ctx,
      SnackBar(
        content: Text(provider.t('ai.geminiKeyNotSet')),
        backgroundColor: Colors.redAccent,
        duration: const Duration(seconds: 5),
        action: SnackBarAction(
          label: provider.t('btn.settings'),
          textColor: Colors.white,
          onPressed: () =>
              _showGeminiKeyDialog(ctx, provider, null, anyProvider: true),
        ),
      ),
    );
  }

  /// トークンが尽きて AI が断られた時に呼ばれる (provider から)。
  /// 何が起きたかを伝えてから、 チャージの画面をそのまま開く
  /// (= ユーザー要望: 文言と一緒に誘導画面も出す)。
  /// 一続きの処理で何度も断られることがあるので、 短い間は 1 回だけ出す。
  DateTime? _creditShortShownAt;
  bool _creditShortDialogOpen = false;
  void _onCreditShort() {
    if (!mounted || _creditShortDialogOpen) return;
    // ── 開発者 / Dev 枠は決済画面へ飛ばさない (= ユーザー要望: 開発者モード
    //    なのに決済画面に遷移してしまう)。 ここへ来たという事は Worker が
    //    本人を Dev と認めなかった時なので、 何が起きたかだけ伝える。 ──
    final devProvider = context.read<MindMapProvider>();
    if (devProvider.developerMode || devProvider.isDevPlan) {
      final now = DateTime.now();
      final last = _creditShortShownAt;
      if (last != null && now.difference(last) < const Duration(seconds: 20)) {
        return;
      }
      _creditShortShownAt = now;
      _appSnack(
        context,
        SnackBar(
          content: Text(devProvider.t('credit.devNotRecognized')),
          backgroundColor: const Color(0xFFE57373),
          duration: const Duration(seconds: 6),
        ),
      );
      return;
    }
    final now = DateTime.now();
    final last = _creditShortShownAt;
    if (last != null && now.difference(last) < const Duration(seconds: 20)) {
      return;
    }
    _creditShortShownAt = now;
    final provider = context.read<MindMapProvider>();
    _appSnack(
      context,
      SnackBar(
        content: Text(provider.t('credit.insufficient')),
        backgroundColor: const Color(0xFFE57373),
        duration: const Duration(seconds: 4),
      ),
    );
    _creditShortDialogOpen = true;
    // ignore: discarded_futures
    _showAiCreditDialog(context, provider).whenComplete(() {
      _creditShortDialogOpen = false;
    });
  }

  /// 前払いクレジットの画面 (= ユーザー要望: 最初に 10 ドル、 足りなくなったら
  /// 都度チャージ。 使った分だけ原価 + 1 割で引かれる)。
  ///
  /// 決済は外部ブラウザの Stripe Checkout で行う。 アプリはカード情報に
  /// 一切触れない。 支払いが済むと Stripe → Worker の webhook 経由で残高が
  /// 増えるので、 戻ってきたら「残高を更新」 を押してもらう。
  Future<void> _showAiCreditDialog(BuildContext ctx, MindMapProvider provider,
      {bool inPlace = false}) async {
    // 開いた時点の残高・使用量を取り直す。
    unawaited(provider.refreshCreditBalance());
    unawaited(provider.refreshRelayModels());
    unawaited(provider.refreshRelayUsage());
    var packs = 1;
    var busy = false;
    // 渡された ctx が閉じた画面のものでも開けるようにする (= ユーザー報告:
    // 押しても先の画面が出ないことがある)。
    final BuildContext base = ctx.mounted ? ctx : context;
    await showDialog<void>(
      context: base,
      // [inPlace] = フローティングの浮遊窓の中の Navigator に出す
      // (= 決済までの画面もフローティングで見えるように)。
      useRootNavigator: !inPlace,
      builder: (dctx) => StatefulBuilder(
        builder: (sctx, setD) {
          final bal = provider.creditBalanceUsd;
          final pack = provider.creditPackUsd;
          final models = provider.relayModels;
          String yen(double usd) =>
              '約¥${MindMapProvider.usdToJpy(usd).toStringAsFixed(0)}';
          return AlertDialog(
            backgroundColor: const Color(0xFF2A2A3E),
            shape:
                RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
            title: Row(children: [
              // ★ プラン画面のバッジと同じ作りに揃えた (= ユーザー要望:
              //   決済画面のアイコンを新しく)。 緑の財布はこの画面だけ浮いて
              //   いて、 サブスク画面と別のアプリのように見えていた。
              Container(
                padding: const EdgeInsets.all(6),
                decoration: const BoxDecoration(
                  shape: BoxShape.circle,
                  gradient: LinearGradient(
                      colors: [Color(0xFF6C63FF), Color(0xFF4FC3F7)]),
                ),
                child:
                    const Icon(Icons.bolt_rounded, color: Colors.white, size: 15),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(provider.t('credit.title'),
                    style:
                        const TextStyle(color: Colors.white, fontSize: 15)),
              ),
            ]),
            content: SizedBox(
              width: 400,
              child: SingleChildScrollView(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    // ── 残高 ──
                    Container(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 14, vertical: 12),
                      decoration: BoxDecoration(
                        color: bal <= 0
                            ? const Color(0xFF3A2020)
                            : (provider.creditLow
                                ? const Color(0xFF332B1A)
                                : const Color(0xFF1E2E22)),
                        borderRadius: BorderRadius.circular(10),
                        border: Border.all(
                            color: bal <= 0
                                ? const Color(0xFFE57373)
                                : (provider.creditLow
                                    ? const Color(0xFFFFB347)
                                    : const Color(0xFF66BB6A))),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(provider.t('credit.balance'),
                              style: const TextStyle(
                                  color: Colors.white60, fontSize: 11)),
                          const SizedBox(height: 4),
                          Row(
                            crossAxisAlignment: CrossAxisAlignment.baseline,
                            textBaseline: TextBaseline.alphabetic,
                            children: [
                              Text('\$${bal.toStringAsFixed(2)}',
                                  style: const TextStyle(
                                      color: Colors.white,
                                      fontSize: 24,
                                      fontWeight: FontWeight.w800)),
                              const SizedBox(width: 8),
                              Text(yen(bal),
                                  style: const TextStyle(
                                      color: Colors.white54, fontSize: 12)),
                              const Spacer(),
                              IconButton(
                                tooltip: provider.t('credit.refresh'),
                                icon: const Icon(Icons.refresh_rounded,
                                    color: Colors.white54, size: 18),
                                onPressed: () async {
                                  await provider.refreshCreditBalance();
                                  setD(() {});
                                },
                              ),
                            ],
                          ),
                          if (bal <= 0)
                            Text(provider.t('credit.emptyHint'),
                                style: const TextStyle(
                                    color: Color(0xFFEF9A9A),
                                    fontSize: 11,
                                    height: 1.4))
                          else if (provider.creditLow)
                            Text(provider.t('credit.lowHint'),
                                style: const TextStyle(
                                    color: Color(0xFFFFB347),
                                    fontSize: 11,
                                    height: 1.4)),
                        ],
                      ),
                    ),
                    const SizedBox(height: 8),
                    // ── 残りトークン目安 + 使用トークン量 (= ユーザー要望:
                    //    チャージ後に残りと使った分が見えるように) ──
                    Builder(builder: (_) {
                      // 選択中モデルの請求単価 (USD / 100万トークン)。
                      double inRate = 0.33, outRate = 2.75;
                      for (final m in models) {
                        if (m is Map && '${m['id']}' == provider.relayModel) {
                          inRate =
                              (m['billedInputPerMTok'] as num?)?.toDouble() ??
                                  inRate;
                          outRate =
                              (m['billedOutputPerMTok'] as num?)?.toDouble() ??
                                  outRate;
                        }
                      }
                      String tok(num t) {
                        final v = t.toDouble();
                        if (v >= 1e6) {
                          return '${(v / 1e6).toStringAsFixed(1)}M';
                        }
                        if (v >= 1e3) {
                          return '${(v / 1e3).toStringAsFixed(0)}k';
                        }
                        return v.toStringAsFixed(0);
                      }

                      String leftTok(double perM) =>
                          perM <= 0 ? '-' : tok(bal / perM * 1e6);
                      final u = provider.relayUsage;
                      final inTok = (u?['inputTokens'] as num?)?.toInt() ?? 0;
                      final outTok =
                          (u?['outputTokens'] as num?)?.toInt() ?? 0;
                      final billed =
                          (u?['billedUsd'] as num?)?.toDouble() ?? 0.0;
                      return Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 12, vertical: 10),
                        decoration: BoxDecoration(
                          color: Colors.white.withValues(alpha: 0.04),
                          borderRadius: BorderRadius.circular(8),
                        ),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              provider
                                  .t('credit.tokensLeft')
                                  .replaceFirst('{in}', leftTok(inRate))
                                  .replaceFirst('{out}', leftTok(outRate)),
                              style: const TextStyle(
                                  color: Color(0xFF9CCC65),
                                  fontSize: 11.5,
                                  fontWeight: FontWeight.w600,
                                  height: 1.4),
                            ),
                            const SizedBox(height: 4),
                            Text(
                              provider
                                  .t('credit.usedTokens')
                                  .replaceFirst('{in}', tok(inTok))
                                  .replaceFirst('{out}', tok(outTok))
                                  .replaceFirst(
                                      '{usd}', billed.toStringAsFixed(2)),
                              style: const TextStyle(
                                  color: Colors.white60,
                                  fontSize: 11,
                                  height: 1.4),
                            ),
                            const SizedBox(height: 2),
                            Text(
                              provider
                                  .t('credit.totals')
                                  .replaceFirst(
                                      '{c}',
                                      provider.creditTotalChargedUsd
                                          .toStringAsFixed(2))
                                  .replaceFirst(
                                      '{s}',
                                      provider.creditTotalSpentUsd
                                          .toStringAsFixed(2)),
                              style: const TextStyle(
                                  color: Colors.white38,
                                  fontSize: 10.5,
                                  height: 1.4),
                            ),
                          ],
                        ),
                      );
                    }),
                    const SizedBox(height: 14),
                    // ── 仕組みの説明文は出さない (= ユーザー要望: 使う度に
                    //    実費 + 〜 が引かれる、 という説明は要らない) ──

                    // ── チャージ額 ──
                    Row(children: [
                      Text(provider.t('credit.amount'),
                          style: const TextStyle(
                              color: Colors.white, fontSize: 13)),
                      const Spacer(),
                      IconButton(
                        icon: Icon(Icons.remove_circle_rounded,
                            color: packs > 1
                                ? const Color(0xFF6C63FF)
                                : Colors.white24,
                            size: 22),
                        onPressed:
                            packs <= 1 ? null : () => setD(() => packs--),
                      ),
                      Text('\$${(pack * packs).toStringAsFixed(0)}',
                          style: const TextStyle(
                              color: Colors.white,
                              fontSize: 17,
                              fontWeight: FontWeight.w700)),
                      IconButton(
                        icon: Icon(Icons.add_circle_rounded,
                            color: packs < 20
                                ? const Color(0xFF6C63FF)
                                : Colors.white24,
                            size: 22),
                        onPressed:
                            packs >= 20 ? null : () => setD(() => packs++),
                      ),
                    ]),
                    Text(yen(pack * packs),
                        textAlign: TextAlign.right,
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 11)),
                    const SizedBox(height: 12),
                    SizedBox(
                      height: 42,
                      child: ElevatedButton.icon(
                        style: ElevatedButton.styleFrom(
                          backgroundColor: const Color(0xFF6C63FF),
                          foregroundColor: Colors.white,
                          elevation: 3,
                          shadowColor:
                              const Color(0xFF6C63FF).withValues(alpha: 0.4),
                        ),
                        icon: busy
                            ? const SizedBox(
                                width: 16,
                                height: 16,
                                child: CircularProgressIndicator(
                                    strokeWidth: 2, color: Colors.white))
                            : const Icon(Icons.credit_card_rounded, size: 18),
                        label: Text(provider.t('credit.charge')),
                        onPressed: busy
                            ? null
                            : () async {
                                setD(() => busy = true);
                                try {
                                  final url = await provider
                                      .createCreditCheckoutUrl(packs: packs);
                                  if (url == null || url.isEmpty) {
                                    throw Exception('no url');
                                  }
                                  await launchUrl(Uri.parse(url),
                                      mode: LaunchMode.externalApplication);
                                } catch (e) {
                                  if (sctx.mounted) {
                                    _appSnack(
                                      sctx,
                                      SnackBar(
                                        content: Text(
                                            '${provider.t('credit.chargeFailed')}: $e'),
                                        backgroundColor:
                                            const Color(0xFFE57373),
                                      ),
                                    );
                                  }
                                } finally {
                                  if (sctx.mounted) setD(() => busy = false);
                                }
                              },
                      ),
                    ),
                    const SizedBox(height: 6),
                    Text(provider.t('credit.chargeNote'),
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 10.5, height: 1.4)),
                    // ── 「使うモデル」 の一覧はここでは出さない
                    //    (= ユーザー要望: チャット欄で切り替えられるので不要) ──
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dctx),
                child: Text(provider.t('btn.close'),
                    style: const TextStyle(color: Colors.white54)),
              ),
            ],
          );
        },
      ),
    );
  }

  void _showGeminiKeyDialog(
      BuildContext ctx, MindMapProvider provider, VoidCallback? onDone,
      {bool anyProvider = false}) {
    // ★ 中間画面 (「キーを用意せずに使う」 の入口) は廃止 (= ユーザー要望:
    //   開いたらその先の AI クレジットの画面がそのまま出るように)。
    //   キーはサーバーだけが持つので、 アプリ側で設定する物はもう無い。
    //   [anyProvider] は旧 API との互換のために残している (使わない)。
    final BuildContext base = ctx.mounted ? ctx : context;
    // ignore: discarded_futures
    // フローティングのアシスタントから来た時は、 その浮遊窓の中に出す
    // (= ユーザー要望: 決済画面に飛ぶまでの画面もフローティングで)。
    _showAiCreditDialog(base, provider, inPlace: _assistantOpenedFloating)
        .then((_) {
      if (!mounted) return;
      // 元の AI 操作の再実行 (チャージ等で使える状態になった時だけ)。
      if (onDone != null && provider.hasActiveAiKey) onDone();
    });
  }

  /// AIプロバイダごとのモデル選択ドロップダウン
  /// - Gemini: Flash / Pro の tier 切替
  /// - OpenAI: openaiAvailableModels からドロップダウン
  /// - Claude: claudeAvailableModels からドロップダウン
  Widget _buildAiModelSelector(MindMapProvider provider, StateSetter setD) {
    // Grok / DeepSeek はモデル名を編集可能テキスト (_buildOpenAiCompatModelField)
    // で扱うため、 ここでは何も描画しない (= Claude のドロップダウンが誤って
    // 出ないようにする)。
    if (provider.aiProvider == 'grok' ||
        provider.aiProvider == 'deepseek' ||
        provider.aiProvider == 'openrouter') {
      return const SizedBox.shrink();
    }
    // Gemini: Flash / Pro のセグメントボタン
    if (provider.aiProvider == 'gemini') {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          const SizedBox(height: 8),
          // ── ラベル + 「最新に更新」ボタン ──
          // OpenAI / Claude セクションと同じ仕組み。Gemini は tier 切替
          // (Flash / Pro) なのでドロップダウンは無いが、リフレッシュ自体は
          // 全プロバイダー一括で叩くので Gemini の選択肢にも反映される。
          Row(
            children: [
              Expanded(
                child: Text(provider.t('aiDlg.modelSelectLabel'),
                    style: const TextStyle(
                        color: Colors.white54,
                        fontSize: 11,
                        fontWeight: FontWeight.w600)),
              ),
              Tooltip(
                message: provider.t('aiDlg.refreshModels'),
                child: InkWell(
                  borderRadius: BorderRadius.circular(6),
                  onTap: () async {
                    final scaffold = ScaffoldMessenger.maybeOf(context);
                    _appSnackM(
                        scaffold,
                        SnackBar(
                          content: Text(provider.t('aiDlg.refreshingModels')),
                          duration: const Duration(seconds: 2),
                        ));
                    await provider.forceRefreshAllAvailableModels();
                    setD(() {});
                    _appSnackM(
                        scaffold,
                        SnackBar(
                          content: Text(provider.t('aiDlg.refreshDone')),
                          backgroundColor: const Color(0xFF43B97F),
                          duration: const Duration(seconds: 2),
                        ));
                  },
                  child: const Padding(
                    padding: EdgeInsets.all(4),
                    child: Icon(Icons.refresh_rounded,
                        color: Color(0xFF4FC3F7), size: 16),
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 4),
          Row(children: [
            Expanded(
              child: _geminiTierChip(
                label: provider.t('aiDlg.modelTierFlash'),
                selected: provider.aiModelTier == 'flash',
                color: const Color(0xFF4FC3F7),
                onTap: () async {
                  provider.aiModelTier = 'flash';
                  await provider.saveAiSettings();
                  setD(() {});
                },
              ),
            ),
            const SizedBox(width: 6),
            Expanded(
              child: _geminiTierChip(
                label: provider.t('aiDlg.modelTierPro'),
                selected: provider.aiModelTier == 'pro',
                color: const Color(0xFFFFB347),
                onTap: () async {
                  provider.aiModelTier = 'pro';
                  await provider.saveAiSettings();
                  setD(() {});
                },
              ),
            ),
          ]),
        ],
      );
    }

    // OpenAI / Claude: ドロップダウン
    // 注: 旧来は `MindMapProvider.openaiAvailableModels` のように
    // クラス側の static const 一覧を参照していたが、AI のモデル一覧を
    // 動的取得 (各社の API から最新モデルを 24h ごとに取り直し) するよう
    // 変更したため、provider インスタンスのゲッターを使う形に変えている。
    // これで新モデルがリリースされるたびにユーザーがコード更新を待たずに
    // 選択肢が増えるようになる。
    final isOpenAi = provider.aiProvider == 'openai';
    final models = isOpenAi
        ? provider.openaiAvailableModels
        : provider.claudeAvailableModels;
    final currentId = isOpenAi ? provider.openaiModel : provider.anthropicModel;
    final accent = isOpenAi ? const Color(0xFF43B97F) : const Color(0xFFFFB347);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        const SizedBox(height: 8),
        // ── ラベル + 「最新に更新」ボタン ──
        // ボタン押下で各社の models API を叩いてモデル一覧を再取得する
        // (24h 制限を無視して即時実行)。新モデルがリリースされても
        // ユーザーがコード更新を待たずに選択肢に出てくるための仕組み。
        Row(
          children: [
            Expanded(
              child: Text(provider.t('aiDlg.modelSelectLabel'),
                  style: const TextStyle(
                      color: Colors.white54,
                      fontSize: 11,
                      fontWeight: FontWeight.w600)),
            ),
            Tooltip(
              message: provider.t('aiDlg.refreshModels'),
              child: InkWell(
                borderRadius: BorderRadius.circular(6),
                onTap: () async {
                  // 押下中の視覚フィードバック (アイコンを少し透明に)
                  // SnackBar で結果通知も出す。
                  final scaffold = ScaffoldMessenger.maybeOf(context);
                  _appSnackM(
                      scaffold,
                      SnackBar(
                        content: Text(provider.t('aiDlg.refreshingModels')),
                        duration: const Duration(seconds: 2),
                      ));
                  await provider.forceRefreshAllAvailableModels();
                  setD(() {});
                  _appSnackM(
                      scaffold,
                      SnackBar(
                        content: Text(provider.t('aiDlg.refreshDone')),
                        backgroundColor: const Color(0xFF43B97F),
                        duration: const Duration(seconds: 2),
                      ));
                },
                child: Padding(
                  padding: const EdgeInsets.all(4),
                  child: Icon(Icons.refresh_rounded, color: accent, size: 16),
                ),
              ),
            ),
          ],
        ),
        const SizedBox(height: 4),
        Container(
          decoration: BoxDecoration(
            color: Colors.white.withValues(alpha: 0.05),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: accent.withValues(alpha: 0.35)),
          ),
          child: DropdownButtonHideUnderline(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 12),
              child: DropdownButton<String>(
                isExpanded: true,
                dropdownColor: const Color(0xFF2A2A3E),
                value: models.any((m) => m['id'] == currentId)
                    ? currentId
                    : models.first['id'],
                items: models
                    .map((m) => DropdownMenuItem<String>(
                          value: m['id'],
                          child: Text(
                            m['label'] ?? m['id']!,
                            style: const TextStyle(
                                color: Colors.white, fontSize: 12),
                            overflow: TextOverflow.ellipsis,
                          ),
                        ))
                    .toList(),
                onChanged: (v) async {
                  if (v == null) return;
                  if (isOpenAi) {
                    await provider.setOpenaiModel(v);
                  } else {
                    await provider.setAnthropicModel(v);
                  }
                  setD(() {});
                },
              ),
            ),
          ),
        ),
      ],
    );
  }

  /// Gemini Flash/Pro tier 切替チップ
  Widget _geminiTierChip({
    required String label,
    required bool selected,
    required Color color,
    required VoidCallback onTap,
  }) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(8),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 7),
        decoration: BoxDecoration(
          color: selected
              ? color.withValues(alpha: 0.22)
              : Colors.white.withValues(alpha: 0.04),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(
            color: selected ? color : Colors.white12,
            width: selected ? 1.5 : 1,
          ),
        ),
        child: Center(
          child: Text(label,
              style: TextStyle(
                  color: selected ? Colors.white : Colors.white60,
                  fontSize: 11,
                  fontWeight: FontWeight.w600),
              overflow: TextOverflow.ellipsis),
        ),
      ),
    );
  }

  /// AIプロバイダ選択チップ

  /// Grok / DeepSeek 用のモデル名入力欄 (編集可能テキスト)。
  /// モデル名は変わりやすいので固定リストにせず、 ユーザーが直接編集できる。
  /// OpenRouter のモデルを一覧から選ぶ (= ユーザー要望: モデルごとに API
  /// キーを設定するのではなく、 OpenRouter でまとめて選択して使えるように)。
  /// 検索できるので数百件でも目的のモデルにすぐ辿り着ける。
  Future<void> _showOpenrouterModelPicker(
      MindMapProvider provider, void Function(VoidCallback) setD) async {
    // ignore: discarded_futures
    provider.refreshOpenrouterModels();
    final searchCtrl = TextEditingController();
    await showDialog<void>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx2, setP) {
        final q = searchCtrl.text.trim().toLowerCase();
        final all = provider.openrouterModels;
        final items = q.isEmpty
            ? all
            : all
                .where((m) =>
                    (m['id'] ?? '').toLowerCase().contains(q) ||
                    (m['label'] ?? '').toLowerCase().contains(q))
                .toList();
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
          title: Row(children: [
            const Icon(Icons.hub_rounded, color: Color(0xFF26A69A), size: 20),
            const SizedBox(width: 8),
            Expanded(
              child: Text(provider.t('ai.openrouterPickModel'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 15,
                      fontWeight: FontWeight.w700)),
            ),
            IconButton(
              tooltip: provider.t('ai.openrouterRefresh'),
              icon: const Icon(Icons.refresh_rounded,
                  color: Colors.white54, size: 18),
              onPressed: () async {
                await provider.refreshOpenrouterModels(force: true);
                setP(() {});
              },
            ),
          ]),
          content: SizedBox(
            width: 460,
            height: 460,
            child: Column(children: [
              TextField(
                controller: searchCtrl,
                autofocus: true,
                style: const TextStyle(color: Colors.white, fontSize: 13),
                onChanged: (_) => setP(() {}),
                decoration: InputDecoration(
                  isDense: true,
                  prefixIcon: const Icon(Icons.search_rounded,
                      color: Colors.white38, size: 18),
                  hintText: provider.t('ai.openrouterSearchHint'),
                  hintStyle:
                      const TextStyle(color: Colors.white30, fontSize: 12),
                  filled: true,
                  fillColor: Colors.white.withValues(alpha: 0.06),
                  border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(8),
                      borderSide: BorderSide.none),
                ),
              ),
              const SizedBox(height: 8),
              Expanded(
                child: provider.openrouterModelsLoading && all.isEmpty
                    ? const Center(child: CircularProgressIndicator())
                    : items.isEmpty
                        ? Center(
                            child: Text(provider.t('ai.openrouterNoModels'),
                                textAlign: TextAlign.center,
                                style: const TextStyle(
                                    color: Colors.white38, fontSize: 12)),
                          )
                        : ListView.builder(
                            itemCount: items.length,
                            itemBuilder: (c, i) {
                              final m = items[i];
                              final id = m['id'] ?? '';
                              final selected = id == provider.openrouterModel;
                              final price = m['price'] ?? '';
                              return ListTile(
                                dense: true,
                                selected: selected,
                                selectedTileColor: const Color(0xFF26A69A)
                                    .withValues(alpha: 0.16),
                                title: Text(m['label'] ?? id,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                        color: selected
                                            ? const Color(0xFF4DD0C4)
                                            : Colors.white,
                                        fontSize: 13,
                                        fontWeight: selected
                                            ? FontWeight.w700
                                            : FontWeight.w500)),
                                subtitle: Text(
                                    price.isEmpty ? id : id + '  ·  ' + price,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(
                                        color: Colors.white38, fontSize: 10.5)),
                                trailing: selected
                                    ? const Icon(Icons.check_rounded,
                                        color: Color(0xFF4DD0C4), size: 18)
                                    : null,
                                onTap: () async {
                                  await provider.setOpenrouterModel(id);
                                  if (dctx2.mounted) Navigator.of(dctx2).pop();
                                  setD(() {});
                                },
                              );
                            },
                          ),
              ),
            ]),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx2).pop(),
              child: Text(provider.t('btn.close'),
                  style: const TextStyle(color: Colors.white60)),
            ),
          ],
        );
      }),
    );
  }

  Widget _buildOpenAiCompatModelField(
      MindMapProvider provider, void Function(VoidCallback) setD) {
    final isGrok = provider.aiProvider == 'grok';
    final isOpenrouter = provider.aiProvider == 'openrouter';
    final ctrl = TextEditingController(
        text: isOpenrouter
            ? provider.openrouterModel
            : isGrok
                ? provider.grokModel
                : provider.deepseekModel);
    final accent = isOpenrouter
        ? const Color(0xFF26A69A)
        : isGrok
            ? const Color(0xFF607D8B)
            : const Color(0xFF5C6BC0);
    final hint = isOpenrouter
        ? 'openai/gpt-4o-mini / anthropic/claude-sonnet-4.5 ...'
        : isGrok
            ? 'grok-3 / grok-4 ...'
            : 'deepseek-chat / deepseek-reasoner';
    Future<void> save(String v) async {
      if (isOpenrouter) {
        await provider.setOpenrouterModel(v);
      } else if (isGrok) {
        await provider.setGrokModel(v);
      } else {
        await provider.setDeepseekModel(v);
      }
    }
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Align(
          alignment: Alignment.centerLeft,
          child: Text(provider.t('aiDlg.modelSelectLabel'),
              style: const TextStyle(
                  color: Colors.white54,
                  fontSize: 11,
                  fontWeight: FontWeight.w600)),
        ),
        const SizedBox(height: 4),
        // ── OpenRouter は対応モデルが数百あるので一覧から選べるようにする
        //    (= ユーザー要望: まとめて選択して使えるように)。 手入力も残す。 ──
        if (isOpenrouter) ...[
          SizedBox(
            width: double.infinity,
            child: OutlinedButton.icon(
              style: OutlinedButton.styleFrom(
                foregroundColor: accent,
                side: BorderSide(color: accent.withValues(alpha: 0.7)),
                padding: const EdgeInsets.symmetric(vertical: 10),
              ),
              onPressed: () => _showOpenrouterModelPicker(provider, setD),
              icon: const Icon(Icons.list_alt_rounded, size: 16),
              label: Text(
                provider.t('ai.openrouterPickModel') +
                    '  (' +
                    provider.openrouterModel +
                    ')',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(fontSize: 12),
              ),
            ),
          ),
          const SizedBox(height: 6),
        ],
        TextField(
          controller: ctrl,
          style: const TextStyle(color: Colors.white, fontSize: 13),
          onSubmitted: (v) async {
            await save(v);
            setD(() {});
          },
          onChanged: (v) async {
            // 入力のたびに保存 (送信時に確実に最新値を使うため)
            await save(v);
          },
          decoration: InputDecoration(
            isDense: true,
            filled: true,
            fillColor: Colors.white.withValues(alpha: 0.05),
            hintText: hint,
            hintStyle: const TextStyle(color: Colors.white24, fontSize: 12),
            contentPadding:
                const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: BorderSide(color: accent.withValues(alpha: 0.35)),
            ),
            enabledBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: BorderSide(color: accent.withValues(alpha: 0.35)),
            ),
            focusedBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: BorderSide(color: accent),
            ),
          ),
        ),
      ],
    );
  }

  Widget _aiProviderChip({
    required String label,
    required bool selected,
    required bool hasKey,
    required Color color,
    required VoidCallback onTap,
  }) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(8),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 8),
        decoration: BoxDecoration(
          color: selected
              ? color.withValues(alpha: 0.25)
              : Colors.white.withValues(alpha: 0.04),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(
              color: selected ? color : Colors.white12,
              width: selected ? 2 : 1),
        ),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Text(label,
              style: TextStyle(
                  color: selected ? Colors.white : Colors.white70,
                  fontSize: 12,
                  fontWeight: FontWeight.w700)),
          const SizedBox(height: 2),
          Icon(
            hasKey ? Icons.check_circle_rounded : Icons.circle_outlined,
            size: 12,
            color: hasKey ? color : Colors.white24,
          ),
        ]),
      ),
    );
  }

  /// APIキー入力セクション（ラベル＋入力欄＋保存ボタン）
  /// 選択中 AI サービスの「API キー取得ページ」 URL (= ユーザー要望:
  /// OpenAI を選んでいるのに Google の案内が出るのは変)。
  String _aiKeyPageUrl(String aiProvider) {
    switch (aiProvider) {
      case 'openai':
        return 'https://platform.openai.com/api-keys';
      case 'anthropic':
        return 'https://console.anthropic.com/settings/keys';
      case 'grok':
        return 'https://console.x.ai';
      case 'deepseek':
        return 'https://platform.deepseek.com/api_keys';
      case 'openrouter':
        return 'https://openrouter.ai/keys';
      default:
        return 'https://aistudio.google.com/apikey';
    }
  }

  /// 上記リンクの表示文言。
  String _aiKeyPageLabel(MindMapProvider provider, String aiProvider) {
    switch (aiProvider) {
      case 'openai':
        return provider.t('aiDlg.helpOpenai');
      case 'anthropic':
        return provider.t('aiDlg.helpClaude');
      case 'grok':
        return 'console.x.ai';
      case 'deepseek':
        return 'platform.deepseek.com';
      case 'openrouter':
        return provider.t('ai.openrouterHelp');
      default:
        return provider.t('ai.getFreeKey');
    }
  }

  Widget _apiKeySection({
    required MindMapProvider provider,
    required String label,
    required String hintText,
    required TextEditingController controller,
    required String helpUrl,
    required String helpText,
    required bool isSet,
    required Color accentColor,
    required Future<void> Function() onSave,
  }) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // ラベルと取得リンクは、 どちらも枠からはみ出さないよう可変幅に
        // する (= ユーザー要望: OpenRouter などが枠に入り切っていない)。
        Row(children: [
          Flexible(
            child: Text(label,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                    color: Colors.white70,
                    fontSize: 12,
                    fontWeight: FontWeight.w600)),
          ),
          const SizedBox(width: 6),
          if (isSet)
            Icon(Icons.check_circle_rounded, size: 12, color: accentColor),
          const SizedBox(width: 6),
          Flexible(
            child: Align(
              alignment: Alignment.centerRight,
              child: InkWell(
                onTap: () => _launchUrl(helpUrl),
                borderRadius: BorderRadius.circular(4),
                child: Padding(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 4, vertical: 2),
                  child: Row(mainAxisSize: MainAxisSize.min, children: [
                    Icon(Icons.open_in_new_rounded,
                        size: 11, color: accentColor.withValues(alpha: 0.9)),
                    const SizedBox(width: 3),
                    Flexible(
                      child: Text(helpText,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                              color: accentColor.withValues(alpha: 0.9),
                              fontSize: 10,
                              decoration: TextDecoration.underline,
                              decorationColor:
                                  accentColor.withValues(alpha: 0.9))),
                    ),
                  ]),
                ),
              ),
            ),
          ),
        ]),
        const SizedBox(height: 4),
        Row(children: [
          Expanded(
            child: TextField(
              controller: controller,
              style: const TextStyle(
                  color: Colors.white, fontSize: 12, fontFamily: 'monospace'),
              obscureText: false,
              decoration: InputDecoration(
                filled: true,
                fillColor: Colors.white.withValues(alpha: 0.05),
                hintText: hintText,
                hintStyle: const TextStyle(color: Colors.white24, fontSize: 11),
                border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(8),
                    borderSide: BorderSide.none),
                contentPadding:
                    const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
              ),
              onSubmitted: (_) async => await onSave(),
            ),
          ),
          const SizedBox(width: 6),
          // 保存ボタンの文字は背景の明るさに応じて黒/白に切り替える
          // (= ユーザー要望: 文字が見にくいのではっきり読めるように)。
          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: accentColor,
              foregroundColor: accentColor.computeLuminance() > 0.45
                  ? const Color(0xFF1A1A24)
                  : Colors.white,
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
            ),
            onPressed: () async => await onSave(),
            child: Text(provider.t('msg.saveBtn'),
                style: const TextStyle(
