  // ─── リンク編集 ──────────────────────────────────────────────────────────

  void _editLink(BuildContext ctx, MindMapNode node) {
    // 既存のURL（youtubeUrl or linkUrl）を初期値に
    final existingUrl = (node.linkUrl ?? '').isNotEmpty
        ? node.linkUrl!
        : (node.youtubeUrl ?? '');
    final ctrl = TextEditingController(text: existingUrl);
    void doSave(BuildContext dctx) {
      final url = ctrl.text.trim();
      final prov = ctx.read<MindMapProvider>();
      // プレイリストURL検出
      final playlistId = _extractPlaylistId(url);
      if (playlistId != null) {
        Navigator.pop(dctx);
        _loadPlaylistVideos(playlistId, node, prov, originalUrl: url);
        return;
      }
      // チャンネルURL検出
      final channelInfo = _extractChannelInfo(url);
      if (channelInfo != null) {
        Navigator.pop(dctx);
        _pickChannelMode().then((mode) {
          if (mode == null) return;
          prov.setChannelMode(mode);
          _loadPlaylistVideos(channelInfo.$1, node, prov,
              customUrl: channelInfo.$2,
              isChannel: true,
              channelMode: mode,
              originalUrl: url);
        });
        return;
      }
      // YouTube URLかどうか判定
      final videoId = NodeWidget.extractVideoId(url);
      if (videoId != null) {
        prov.updateNodeYoutube(node.id, url);
        prov.updateNodeLink(node.id, '');
        Navigator.pop(dctx);
        _fetchYoutubeTitle(videoId, node.id, prov, force: true);
      } else if (NodeWidget.isMp4Url(url)) {
        prov.updateNodeYoutube(node.id, url);
        prov.updateNodeLink(node.id, '');
        Navigator.pop(dctx);
        prov.generateVideoThumbnail(node.id);
      } else {
        prov.updateNodeLink(node.id, url);
        prov.updateNodeYoutube(node.id, '');
        Navigator.pop(dctx);
      }
      // 保存できたことを知らせる (= ユーザー要望: 保存を押したら
      // 「保存しました」 と出るように)。
      if (mounted) {
        _appSnack(
          context,
          SnackBar(
            content: Text(
                url.isEmpty ? prov.t('link.cleared') : prov.t('link.saved'),
                style: const TextStyle(fontSize: 12)),
            backgroundColor: const Color(0xFF43B97F),
            duration: const Duration(seconds: 2),
          ),
        );
      }
    }

    showDialog(
      context: ctx,
      builder: (dctx) {
        final prov = ctx.read<MindMapProvider>();
        return AlertDialog(
          backgroundColor: const Color(0xFF2A2A3E),
          title: Row(children: [
            Container(
                width: 28,
                height: 28,
                decoration: const BoxDecoration(
                    color: Color(0xFF4FC3F7), shape: BoxShape.circle),
                child: const Icon(Icons.link_rounded,
                    color: Colors.white, size: 18)),
            const SizedBox(width: 10),
            Text(prov.t('linkEdit.title'),
                style: const TextStyle(color: Colors.white, fontSize: 16)),
          ]),
          content: TextField(
            controller: ctrl,
            autofocus: true,
            style: const TextStyle(color: Colors.white, fontSize: 14),
            keyboardType: TextInputType.url,
            decoration: InputDecoration(
              filled: true,
              fillColor: Colors.white.withValues(alpha: 0.07),
              hintText: 'https://...',
              hintStyle: const TextStyle(color: Colors.white38, fontSize: 13),
              border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                  borderSide: BorderSide.none),
              prefixIcon: const Icon(Icons.link_rounded,
                  color: Colors.white38, size: 18),
              contentPadding:
                  const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
            ),
            onSubmitted: (_) => doSave(dctx),
          ),
          actions: [
            if (existingUrl.isNotEmpty)
              TextButton(
                  onPressed: () {
                    final prov = ctx.read<MindMapProvider>();
                    prov.updateNodeLink(node.id, '');
                    prov.updateNodeYoutube(node.id, '');
                    Navigator.pop(dctx);
                  },
                  child: Text(prov.t('linkEdit.remove'),
                      style: const TextStyle(color: Colors.redAccent))),
            TextButton(
                onPressed: () => Navigator.pop(dctx),
                child: Text(prov.t('node.cancel'),
                    style: const TextStyle(color: Colors.white54))),
            ElevatedButton(
              onPressed: () => doSave(dctx),
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF4FC3F7),
                  foregroundColor: Color(0xFF10241F),),
              child: Text(prov.t('node.save')),
            ),
          ],
        );
      },
    );
  }

  // ─── ノード統合リッチテキスト編集 ───────────────────────────────────────────

  List<String> _splitNodeBatchParts(MindMapProvider provider, String raw) {
    final delimiter = provider.voiceDelimiter.trim();
    final normalized = raw.replaceAll('\r\n', '\n').trim();
    if (delimiter.isEmpty || normalized.isEmpty) return const <String>[];
    final parts = normalized
        .split(delimiter)
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toList(growable: false);
    return parts.length > 1 ? parts : const <String>[];
  }

  (String, String) _titleMemoFromPlainText(String raw) {
    final lines = raw.replaceAll('\r\n', '\n').trim().split('\n');
    var title = '';
    var titleLine = -1;
    for (var i = 0; i < lines.length; i++) {
      final line = lines[i].trim();
      if (line.isNotEmpty) {
        title = line;
        titleLine = i;
        break;
      }
    }
    if (titleLine < 0) return ('', '');
    final memo = titleLine + 1 < lines.length
        ? lines.skip(titleLine + 1).join('\n').trim()
        : '';
    return (title, memo);
  }

  String _plainTextRichJson(String raw) {
    final text = raw.trim();
    return jsonEncode([
      {'insert': text.endsWith('\n') ? text : '$text\n'}
    ]);
  }

  void _savePlainNodeText(MindMapProvider provider, String nodeId, String raw) {
    final text = raw.trim();
    final titleMemo = _titleMemoFromPlainText(text);
    provider.updateNodeRichText(
      nodeId,
      richText: _plainTextRichJson(text),
      title: titleMemo.$1,
      memo: titleMemo.$2,
    );
  }

  void _expandDelimitedNodeText(
      MindMapProvider provider, String firstNodeId, List<String> parts) {
    final base = provider.nodes[firstNodeId];
    if (base == null || parts.isEmpty) return;
    final isBookshelf = provider.currentPage.pageType == 'bookshelf';

    _savePlainNodeText(provider, firstNodeId, parts.first);
    for (var index = 1; index < parts.length; index++) {
      final id = isBookshelf
          ? provider.addEmptyTextNoteToBookshelf()
          : provider
              .addNodeAtCenterReturning(
                  base.position + Offset(190.0 * index, 0))
              .id;
      if (id.isEmpty) break;
      _savePlainNodeText(provider, id, parts[index]);
      if (!isBookshelf) provider.resolveNodeOverlaps(id);
    }
    if (!isBookshelf) provider.resolveNodeOverlaps(firstNodeId);
  }

  Future<void> _showNodeBatchDelimiterDialog(
      BuildContext ctx, MindMapProvider provider) async {
    final ctrl = TextEditingController(text: provider.voiceDelimiter);
    final result = await showDialog<String>(
