        backgroundColor: const Color(0xFF1E1E32),
        title: Text(context.read<MindMapProvider>().t('delim.title'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(context.read<MindMapProvider>().t('delim.desc'),
                style: const TextStyle(color: Colors.white70, fontSize: 12)),
            const SizedBox(height: 10),
            TextField(
              controller: ctrl,
              autofocus: true,
              style: const TextStyle(color: Colors.white),
              decoration: InputDecoration(
                hintText: context.read<MindMapProvider>().t('delim.hint'),
                hintStyle: const TextStyle(color: Colors.white38),
                filled: true,
                fillColor: Colors.white.withValues(alpha: 0.07),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(8),
                  borderSide: BorderSide.none,
                ),
              ),
              onSubmitted: (v) => Navigator.pop(dctx, v),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF4FC3F7),
                foregroundColor: Colors.black),
            onPressed: () => Navigator.pop(dctx, ctrl.text),
            child: Text(provider.t('btn.save')),
          ),
        ],
      ),
    );
    if (result != null) {
      await provider.setVoiceDelimiter(result.trim());
    }
    ctrl.dispose();
  }

  /// ノードの統合リッチテキスト編集ダイアログ (= ユーザー要望: タイトルとメモを
  /// 分けず、 編集ボタンを押したらまとめてリッチテキストで書ける)。
  /// 保存時に Quill Delta(JSON) を richText に保存し、 平文の 1 行目を title、
  /// 残りを memo として派生保存する (検索・サイズ計算・後方互換のため)。
  Future<void> _showNodeRichEditDialog(BuildContext ctx, String nodeId,
      {bool allowDelimiterExpansion = false}) async {
    final provider = ctx.read<MindMapProvider>();
    final node = provider.nodes[nodeId];
    if (node == null) return;
    // 初期ドキュメント: richText があればそれを、 無ければ title+memo から構築
    //   (title 行は見出しにして従来の「タイトル大・メモ小」 の見た目に近づける)。
    Document doc;
    final rt = node.richText;
    if (rt != null && rt.trim().isNotEmpty) {
      try {
        final decoded = jsonDecode(rt);
        doc = decoded is List
            ? Document.fromJson(decoded)
            : Document.fromJson([
                {'insert': '${MindMapNode.richDeltaToPlainText(rt)}\n'}
              ]);
      } catch (_) {
        doc = Document.fromJson([
          {'insert': '\n'}
        ]);
      }
    } else {
      final ops = <Map<String, dynamic>>[];
      final title = node.title;
      final memo = node.memoText ?? '';
      if (title.isNotEmpty) {
        ops.add({'insert': title});
        ops.add({
          'insert': '\n',
          'attributes': {'header': 2}
        });
      }
      if (memo.isNotEmpty) {
        ops.add({'insert': memo.endsWith('\n') ? memo : '$memo\n'});
      }
      if (ops.isEmpty) {
        ops.add({'insert': '\n'});
      }
      doc = Document.fromJson(ops);
    }
    final controller = QuillController(
      document: doc,
      selection: const TextSelection.collapsed(offset: 0),
    );

    void doSave(BuildContext dctx) {
      final richJson = jsonEncode(controller.document.toDelta().toJson());
      final plain = controller.document.toPlainText();
      final batchParts = allowDelimiterExpansion
          ? _splitNodeBatchParts(provider, plain)
          : const <String>[];
      if (batchParts.length > 1) {
        _expandDelimitedNodeText(provider, nodeId, batchParts);
        Navigator.pop(dctx);
        if (batchParts.first.trim().isNotEmpty) {
          _offerBulkAutofillSuggestions(nodeId);
        }
        return;
      }
      final lines = plain.split('\n');
      String title = '';
      int i = 0;
      for (; i < lines.length; i++) {
        if (lines[i].trim().isNotEmpty) {
          title = lines[i].trim();
          break;
        }
      }
      final memo =
          i + 1 < lines.length ? lines.skip(i + 1).join('\n').trim() : '';
      provider.updateNodeRichText(nodeId,
          richText: richJson, title: title, memo: memo);
      // ── 旧インライン編集と同じ後処理を統合リッチ編集にも持たせる ──
      //   テキストが伸びて周囲のノードと重なるのを解消し、 タイトルが
      //   入っていれば連番一括サジェスト (オートフィル) を試みる。
      provider.resolveNodeOverlaps(nodeId);
      Navigator.pop(dctx);
      if (title.trim().isNotEmpty) {
        _offerBulkAutofillSuggestions(nodeId);
      }
    }

    final isMobile = MediaQuery.of(ctx).size.width < 600;
    await showDialog<void>(
      context: ctx,
      builder: (dctx) {
        // ★ flutter_quill のデフォルト文字色を白に強制 (= ユーザー要望: ノード
        //   編集のリッチテキストが暗背景に黒文字で見えない)。 全ブロック種を白に
        //   する共通ヘルパを使う (マップメモと同一の処理)。
        final whiteStyles = _whiteQuillStyles(dctx);
        Widget batchDelimiterBar() {
          if (!allowDelimiterExpansion) return const SizedBox.shrink();
          return StatefulBuilder(
            builder: (barCtx, setBarState) {
              final current = provider.voiceDelimiter.trim();
              return Align(
                alignment: Alignment.centerRight,
                child: TextButton.icon(
                  style: TextButton.styleFrom(
                    foregroundColor: Colors.white54,
                    padding:
                        const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                    textStyle: const TextStyle(fontSize: 11),
                    minimumSize: Size.zero,
                    tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  ),
                  onPressed: () async {
                    await _showNodeBatchDelimiterDialog(barCtx, provider);
                    if (mounted) setBarState(() {});
                  },
                  icon: const Icon(Icons.call_split_rounded, size: 13),
                  label: Text(current.isEmpty ? '一括分割設定' : '分割: $current'),
                ),
              );
            },
          );
        }

        // 共通のリッチテキストエディタ本体 (高さは親が決める)。
        // ── 本文を確実に白にする (= ユーザー要望: 黒文字で全く読めない) ──
        //   flutter_quill は内部で Theme の textTheme から既定色を作るため、
        //   customStyles だけでは反映されないことがある。 Theme の textTheme を
        //   白に上書きした上で、 customStyles と DefaultTextStyle も白で渡す。
        final editor = Theme(
            data: Theme.of(dctx).copyWith(
              textTheme: Theme.of(dctx)
                  .textTheme
                  .apply(bodyColor: Colors.white, displayColor: Colors.white),
            ),
            child: Container(
              width: double.infinity,
              padding: const EdgeInsets.all(8),
              decoration: BoxDecoration(
                // ── 背景を不透明の黒に固定 (= ユーザー要望: モバイルで白地に
                //   白文字になって全く見えない)。 旧 white@0.06 は明るいサーフェス
                //   に重なると白っぽく飛んで読めなくなっていた。 マップメモ
                //   エディタと同じ不透明 0xFF121212 に統一する。
                color: const Color(0xFF121212),
                borderRadius: BorderRadius.circular(8),
              ),
              child: DefaultTextStyle(
                style: const TextStyle(color: Colors.white),
                child: QuillEditor.basic(
                  controller: controller,
                  config: QuillEditorConfig(
                    customStyles: whiteStyles,
                    placeholder: 'タイトルや内容をまとめて入力…',
                    padding: EdgeInsets.zero,
                    // ── Enter で保存 / Shift+Enter で改行 (デスクトップのみ) ──
                    // onKeyPressed は Quill の改行処理より前に呼ばれ、 handled を
                    // 返すと改行が挿入されない。 モバイルは Enter = 改行に固定し、
                    //   保存は「保存」ボタンで行う (= ユーザー要望: モバイルは
                    //   Enter で改行、 保存ボタンを直接押す)。 物理キーボード接続時
                    //   の誤保存も防ぐため、 Enter 保存はデスクトップ限定にする。
                    onKeyPressed: (event, qnode) {
                      if (isMobile) return null;
                      if (event is KeyDownEvent &&
                          (event.logicalKey == LogicalKeyboardKey.enter ||
                              event.logicalKey ==
                                  LogicalKeyboardKey.numpadEnter) &&
                          !HardwareKeyboard.instance.isShiftPressed) {
                        doSave(dctx);
                        return KeyEventResult.handled;
                      }
                      return null;
                    },
                  ),
                ),
              ),
            ));
        if (isMobile) {
          // ── モバイルは全画面 (= ユーザー要望: モバイルのノード編集リッチ
          //    テキストが崩れる問題の修正)。 エディタを Expanded にして、
          //    キーボード表示時もオーバーフローしないようにする。 ──
          return Dialog.fullscreen(
            backgroundColor: const Color(0xFF1E1E32),
            child: SafeArea(
              child: Column(children: [
                Row(children: [
                  IconButton(
                    icon: const Icon(Icons.close, color: Colors.white70),
                    onPressed: () => Navigator.pop(dctx),
                  ),
                  Expanded(
                    child: Text(provider.t('node.editTitle'),
                        style:
                            const TextStyle(color: Colors.white, fontSize: 15)),
                  ),
                  TextButton(
                    onPressed: () => doSave(dctx),
                    child: Text(provider.t('btn.save'),
                        style: const TextStyle(
                            color: Color(0xFF4FC3F7),
                            fontWeight: FontWeight.w700)),
                  ),
                ]),
                // ── 入力パレットを本文の直上に配置。
                //    モバイルでは最下部に置くと入力位置と離れやすいため、
                //    編集対象のすぐ近くへ寄せる。 ──
                Padding(
                  padding: const EdgeInsets.fromLTRB(8, 2, 8, 4),
                  child: _whiteQuillSimpleToolbar(controller),
                ),
                if (allowDelimiterExpansion)
                  Padding(
                    padding: const EdgeInsets.fromLTRB(8, 0, 8, 6),
                    child: batchDelimiterBar(),
                  ),
                Padding(
                  padding: const EdgeInsets.fromLTRB(8, 2, 8, 4),
                  child: SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      style: ElevatedButton.styleFrom(
                        backgroundColor: const Color(0xFF4FC3F7),
                        foregroundColor: Colors.black,
                        padding: const EdgeInsets.symmetric(vertical: 10),
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(10),
                        ),
                      ),
                      icon: const Icon(Icons.check_rounded, size: 18),
                      label: Text(context.read<MindMapProvider>().t('paint.confirm'),
                          style:
                              const TextStyle(fontWeight: FontWeight.w700)),
                      onPressed: () => doSave(dctx),
                    ),
                  ),
                ),
                Expanded(
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(8, 4, 8, 8),
                    child: editor,
                  ),
                ),
              ]),
            ),
          );
        }
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            const Icon(Icons.edit_note_rounded,
                color: Color(0xFF4FC3F7), size: 20),
            const SizedBox(width: 10),
            Expanded(
              child: Text(provider.t('node.editTitle'),
                  style: const TextStyle(color: Colors.white, fontSize: 15)),
            ),
          ]),
          content: SizedBox(
            width: 460,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                _whiteQuillSimpleToolbar(controller),
                if (allowDelimiterExpansion) ...[
                  const SizedBox(height: 6),
                  batchDelimiterBar(),
                ],
                const SizedBox(height: 6),
                SizedBox(height: 280, child: editor),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF4FC3F7),
                  foregroundColor: Colors.black),
              onPressed: () => doSave(dctx),
              child: Text(provider.t('btn.save')),
            ),
          ],
        );
      },
    );
    controller.dispose();
  }

  /// 画面分割パネル本体。 親 Row の子として固定幅で配置される。
  /// 開いていないときは SizedBox.shrink を返す (= ゼロ幅で消える)。
  ///
  /// ★ 旧実装は Stack の上に `Positioned(right: 0, width: panelWidth)` で
  ///   オーバーレイしていたが、 マウスホイール等のポインタイベントが
  ///   背後のマップキャンバスに漏れる問題があったため、 完全に独立した
  ///   Row レイアウトに変更 (= マップとパネルが領域を共有しない構造)。
  /// SfPdfViewer のドキュメントロード完了時に呼ばれる。
  /// 非表示ページに該当するページから始まると、 ユーザーは「スクロールバーが
  /// 非表示ページ分まで考慮されてない」 と感じるので、 最初の表示可能ページに
  /// 自動でジャンプして UX を整える。
  /// 例: 1 ページ目が非表示 → 自動で 2 ページ目を初期表示。
  void _handleSplitPdfLoaded(sf_pdf.PdfDocumentLoadedDetails details) {
    // 総ページ数と初期ページ番号をセット (オーバーレイ表示で使用)
    final pageCount = details.document.pages.count;
    if (mounted) {
      setState(() {
        _splitPdfTotalPages = pageCount;
        _splitPdfCurrentPage = 1;
      });
      // ヘッダー入力欄も同期 (= ユーザー要望「上のページ番号が振られて
      // いない」 への対応)。
      _splitJumpPageCtrl.text = '1';
    }
    final pdfKey = _splitLocalPdfPath ?? _splitCurrentUrl;
    if (pdfKey.isEmpty) return;
    final provider = context.read<MindMapProvider>();
    // ── 最終ページ復元 (= ユーザー要望: 全画面 ⇔ 画面分割でページが戻らない) ──
    // 全画面ビューア / 左パネルと同じく provider.lastPdfPageFor を共有して、
    //   読んでいたページから再開する。 非表示ページの first-jump より後 (200ms)
    //   に実行して上書きする。
    try {
      final lastPage = provider.lastPdfPageFor(pdfKey);
      if (lastPage != null && lastPage >= 1 && lastPage <= pageCount) {
        Future.delayed(const Duration(milliseconds: 200), () {
          if (!mounted || !_splitOpen) return;
          try {
            _splitPdfController.jumpToPage(lastPage);
            setState(() {
              _splitPdfCurrentPage = lastPage;
              _splitJumpPageCtrl.text = '$lastPage';
            });
          } catch (_) {}
        });
      }
    } catch (_) {}
    final hidden = provider.hiddenPdfPagesFor(pdfKey);
    if (hidden.isEmpty) return;
    // 最初の表示可能ページを探す
    int firstVisible = 1;
    while (firstVisible <= pageCount && hidden.contains(firstVisible)) {
      firstVisible++;
    }
    if (firstVisible > pageCount) return; // 全ページ非表示
    if (firstVisible == 1) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_splitOpen) return;
      try {
        _splitPdfController.jumpToPage(firstVisible);
      } catch (_) {}
    });
  }

  /// SfPdfViewer の onPageChanged フック。 非表示ページに遷移した場合、
  /// 進行方向に応じて次の表示可能ページに自動でジャンプする。
  /// 例: 2 ページ目が非表示で、 1 → 2 へ進もうとすると 3 ページ目へ。
  void _handleSplitPdfPageChanged(sf_pdf.PdfPageChangedDetails details) {
    // ── ページ移動を検知してオーバーレイ表示 ──
    // 「現在ページ / 全ページ」 を 3 秒間表示する。 初回ロード時 (新==旧)
    // は表示しない。 自動ジャンプ (非表示ページスキップ) でもページが
    // 動くので、 表示する。
    if (mounted) {
      _applyPdfPageChange(() {
        _splitPdfCurrentPage = details.newPageNumber;
        if (_splitPdfTotalPages == 0) {
          try {
            _splitPdfTotalPages = _splitPdfController.pageCount;
          } catch (_) {}
        }
      });
      // ── ヘッダーのページ番号入力欄を現在ページに同期 ──
      // ユーザー要望: 「上のページ番号が振られていない」 への対応。
      // PDF ビューアの実ページが変わるたびに入力欄テキストを更新して
      // 「現在 N ページ目」 が見えるようにする。
      _splitJumpPageCtrl.text = '${details.newPageNumber}';
      // 旧仕様のオーバーレイ (= 右上の「N / M」 バッジ) は廃止 (ユーザー
      // 要望「今の右上にちょっとだけ出るページ番号表記は要らない」)。
      // _showSplitPdfPageOverlay() は呼び出さない。
    }

    final pdfKey = _splitLocalPdfPath ?? _splitCurrentUrl;
    if (pdfKey.isEmpty) return;
    final provider = context.read<MindMapProvider>();
    // 最終ページを永続化 (= ユーザー要望: 全画面 ⇔ 画面分割を切り替えても
    //   ページが最初に戻らないように。 全画面ビューア / 左パネルと同じく
    //   provider.lastPdfPageFor を共有して引き継ぐ)。
    try {
      provider.setLastPdfPage(pdfKey, details.newPageNumber);
    } catch (_) {}
    final hidden = provider.hiddenPdfPagesFor(pdfKey);
    if (hidden.isEmpty) return;
    if (!hidden.contains(details.newPageNumber)) return;
    // 進む方向 (新 > 旧) か戻る方向 (新 < 旧) かを判別
    // 同値 (= 初回ロード) は前進扱い
    final isForward = details.newPageNumber >= details.oldPageNumber;
    final maxPage = _splitPdfController.pageCount;
    if (maxPage <= 0) return;
    int target = details.newPageNumber;
    // 最大 maxPage 回まで探す (= 全ページ非表示等の暴走防止)
    for (int i = 0; i < maxPage; i++) {
      if (isForward) {
        target++;
        if (target > maxPage) {
          // 末尾を超えたら戻り方向にやり直す
          target = details.newPageNumber - 1;
          if (target < 1) return;
          // 戻り方向に切替えて続行
          for (int j = 0; j < maxPage; j++) {
            if (!hidden.contains(target)) break;
            target--;
            if (target < 1) return;
          }
          break;
        }
      } else {
        target--;
        if (target < 1) {
          // 先頭を下回ったら前進方向にやり直す
          target = details.newPageNumber + 1;
          if (target > maxPage) return;
          for (int j = 0; j < maxPage; j++) {
            if (!hidden.contains(target)) break;
            target++;
            if (target > maxPage) return;
          }
          break;
        }
      }
      if (!hidden.contains(target)) break;
    }
    if (target == details.newPageNumber) return;
    // onPageChanged 中の jumpToPage は不安定なので、 次フレームで実行
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_splitOpen) return;
      try {
        _splitPdfController.jumpToPage(target);
      } catch (_) {}
    });
  }

  // 注: 分割 PDF の右クリックメニューは廃止 (= ユーザー要望: 「ページを
  //     非表示」 等の項目は要らない)。
  /// 画面分割「左パネル」 (= PDF 専用、 並列表示用) の描画。
  /// 右パネル (`_buildSplitPanel`) のシンプル PDF 専用版。
  Widget _buildSplitLeftPanel(MindMapProvider provider) {
    if (!_splitLeftOpen) return const SizedBox.shrink();
    final mq = MediaQuery.of(context);
    final w = mq.size.width;
    // ユーザー要望: 「左右の境界線をドラッグしたら表示領域の大きさを
    // 変えられるようにして」。 右パネルと同じ範囲 (= 画面幅の 20%〜90%) で
    // クランプ。 上限を 50% から 90% に拡大することで「ほぼ全画面の PDF」
    // としても使える。
    final width = _splitLeftPanelWidth.clamp(w * 0.20, w * 0.90).toDouble();
    final pdfPath = _splitLeftLocalPdfPath;
    return SizedBox(
      width: width,
      // ── MouseRegion でホバー検知 ──
      // Esc キーで「アクティブなパネル」 を閉じるための判定に使う。
      // 右パネルの `_splitPanelHover` と同じ概念。
      child: MouseRegion(
        onEnter: (_) {
          // 排他化: 左パネルに来たら右パネル hover を強制的に false にする
          // (= WebView 等の Platform View が onExit を取りこぼす問題への対策)
          if (!_splitLeftPanelHover || _splitPanelHover) {
            setState(() {
              _splitLeftPanelHover = true;
              _splitPanelHover = false;
            });
          }
        },
        onExit: (_) {
          if (_splitLeftPanelHover) {
            setState(() => _splitLeftPanelHover = false);
          }
        },
        child: Material(
          color: const Color(0xFF13132A),
          elevation: 8,
          // ── Stack で本体 + リサイズハンドル ──
          // 右パネルと同じ作りで、 右端にドラッグハンドルを配置。
          child: Stack(children: [
            Column(
              children: [
                // ── 上部バー ──
                // mode に応じてアイコン・タイトル表示が変わる。
                // 右クリックや「URL 入力」 ボタンで mode 切替可能。
                Container(
                  height: 40,
                  padding: const EdgeInsets.symmetric(horizontal: 6),
                  decoration: const BoxDecoration(
                    color: Color(0xFF1A1A30),
                    border: Border(
                      bottom: BorderSide(color: Colors.white12, width: 1),
                    ),
                  ),
                  child: GestureDetector(
                      // ── ヘッダー右クリックで同じ AI を反対側にも複製 (= ユーザー要望) ──
                      behavior: HitTestBehavior.translucent,
                      onSecondaryTap: () =>
                          _duplicateSplitAiToOpposite(fromLeft: true),
                      child: Row(children: [
                        Icon(
                          _splitLeftMode == 'web'
                              ? Icons.public_rounded
                              : Icons.picture_as_pdf_rounded,
                          size: 18,
                          color: _splitLeftMode == 'web'
                              ? const Color(0xFF6C63FF)
                              : const Color(0xFFFF6B6B),
                        ),
                        const SizedBox(width: 6),
                        // ユーザー要望: 「左右の画面分割の上の項目を左側に揃えて」。
                        // Expanded → Flexible にしてタイトルが必要な幅だけ取り、
                        // 後続のアイコン群が左に詰まるように。
                        Flexible(
                          child: Text(
                            _splitLeftMode == 'web' &&
                                    _splitLeftCurrentUrl.isNotEmpty
                                ? _splitLeftCurrentUrl
                                : (pdfPath != null
                                    ? pdfPath.split(RegExp(r'[/\\]')).last
                                    : '(未選択)'),
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: Colors.white70, fontSize: 12),
                          ),
                        ),
                        const SizedBox(width: 6),
                        // ── URL 入力ボタン (= mode 切替) ──
                        IconButton(
                          icon: const Icon(Icons.link_rounded,
                              color: Colors.white60, size: 16),
                          tooltip: provider.t('split.openUrl'),
                          padding: EdgeInsets.zero,
                          constraints:
                              const BoxConstraints(minWidth: 28, minHeight: 28),
                          onPressed: () async {
                            final urlCtrl = TextEditingController(
                                text: _splitLeftCurrentUrl);
                            final url = await showDialog<String>(
                              context: context,
                              builder: (ctx) => AlertDialog(
                                backgroundColor: const Color(0xFF1E1E2E),
                                title: Text(provider.t('split.enterUrl'),
                                    style:
                                        const TextStyle(color: Colors.white)),
                                content: TextField(
                                  controller: urlCtrl,
                                  autofocus: true,
                                  style: const TextStyle(color: Colors.white),
                                  decoration: const InputDecoration(
                                    hintText: 'https://example.com',
                                    hintStyle: TextStyle(color: Colors.white30),
                                  ),
                                  onSubmitted: (v) => Navigator.of(ctx).pop(v),
                                ),
                                actions: [
                                  TextButton(
                                    child: Text(provider.t('btn.cancel'),
                                        style: const TextStyle(
                                            color: Colors.white54)),
                                    onPressed: () =>
                                        Navigator.of(ctx).pop(null),
                                  ),
                                  TextButton(
                                    child: Text(provider.t('btn.open'),
                                        style: const TextStyle(
                                            color: Color(0xFF6C63FF))),
                                    onPressed: () =>
                                        Navigator.of(ctx).pop(urlCtrl.text),
                                  ),
                                ],
                              ),
                            );
                            if (url != null && url.trim().isNotEmpty) {
                              _splitLoadLeftUrl(url);
                            }
                          },
                        ),
                        // ページ番号入力
                        if (pdfPath != null && _splitLeftTotalPages > 0)
                          SizedBox(
                            width: 56,
                            child: TextField(
                              controller: _splitLeftPageInputCtrl,
                              style: const TextStyle(
                                  color: Colors.white, fontSize: 11),
                              textAlign: TextAlign.center,
                              keyboardType: TextInputType.number,
                              inputFormatters: const [
                                _FullWidthDigitToHalfFormatter()
                              ],
                              decoration: const InputDecoration(
                                isDense: true,
                                contentPadding:
                                    EdgeInsets.symmetric(vertical: 4),
                                border: OutlineInputBorder(
                                  borderSide: BorderSide(color: Colors.white24),
                                ),
                              ),
                              onSubmitted: (v) {
                                final p = int.tryParse(v);
                                if (p != null &&
                                    p >= 1 &&
                                    p <= _splitLeftTotalPages) {
                                  try {
                                    _splitLeftPdfController.jumpToPage(p);
                                  } catch (_) {}
                                }
                              },
                            ),
                          ),
                        if (pdfPath != null && _splitLeftTotalPages > 0)
                          Padding(
                            padding: const EdgeInsets.symmetric(horizontal: 4),
                            child: Text(
                              '/ $_splitLeftTotalPages',
                              style: const TextStyle(
                                  color: Colors.white54, fontSize: 11),
                            ),
                          ),
                        // ── PDF への書き込み (= ユーザー要望: テキスト /
                        //    チェック) ──
                        if (pdfPath != null)
                          _pdfWriteModeButtons(left: true),
                        // ── スマート左右移動ボタン (= 統合) ──
                        // ユーザー要望: 「図の 3 つの記号 1 つに纏めて、 右において
                        //   あったら左矢印で左側に移動、 左においてあったら右矢印で
                        //   右に移動でいいやん、 で、 既に移動先に分割画面があれば
                        //   それと交代で入れ替えでいいやん」。
                        // 旧仕様の「前ページ (<)」 「次ページ (>)」 「左右入れ替え
                        // (⇆)」 の 3 つを廃止して、 1 つのスマートボタンに統合。
                        // ページ移動は左の「ページ番号入力欄」 や PDF 上のスクロール
                        // で行う。
                        IconButton(
                          icon: Icon(_smartMoveIcon(fromLeft: true),
                              color: Colors.white70, size: 18),
                          tooltip: _smartMoveTooltip(fromLeft: true),
                          padding: EdgeInsets.zero,
                          constraints:
                              const BoxConstraints(minWidth: 28, minHeight: 28),
                          onPressed: () => _smartMovePanel(fromLeft: true),
                        ),
                        // ── 全画面表示ボタン (新規) ──
                        // ユーザー要望: 「左の画面分割画面の上に全画面表示にする
                        // ボタンを付けて」。 左パネルを閉じて、 内容をフルスクリーン
                        // アプリ内ビューアで開き直す。
                        // ── WebView 表示中のみ: 再読込 / ログアウト (= ユーザー要望) ──
                        if (_splitLeftWinController != null ||
                            _splitLeftIawController != null) ...[
                          IconButton(
                            icon: const Icon(Icons.refresh_rounded,
                                color: Colors.white70, size: 18),
                            tooltip: provider.t('split.reload'),
                            padding: EdgeInsets.zero,
                            constraints: const BoxConstraints(
                                minWidth: 28, minHeight: 28),
                            onPressed: () => _reloadSplitPanel(isLeft: true),
                          ),
                          IconButton(
                            icon: const Icon(Icons.logout_rounded,
                                color: Colors.white70, size: 18),
                            tooltip: provider.t('split.relogin'),
                            padding: EdgeInsets.zero,
                            constraints: const BoxConstraints(
                                minWidth: 28, minHeight: 28),
                            onPressed: () =>
                                _confirmClearSplitLogin(isLeft: true),
                          ),
                        ],
                        // ── フローティングに切り替え (= ユーザー要望: 普通に
                        //    開くチャット欄のヘッダーからフローティングへ) ──
                        //    今のページをドラッグできる浮遊パネルとして開き、
                        //    この分割パネルは閉じる。 Web 表示の時だけ出す。
                        if (_splitLeftMode == 'web')
                          IconButton(
                            icon: const Icon(Icons.picture_in_picture_alt_rounded,
                                color: Colors.white70, size: 18),
                            tooltip: provider.t('split.toFloating'),
                            padding: EdgeInsets.zero,
                            constraints: const BoxConstraints(
                                minWidth: 28, minHeight: 28),
                            onPressed: () {
                              final url = _splitLeftUrlCtrl.text.trim();
                              _closeSplitLeftPanel();
                              // 最初から外の本物の窓で開く (= ユーザー要望: 統合)。
                              _openFloatingWebUnified(url);
                            },
                          ),
                        IconButton(
                          icon: const Icon(Icons.fullscreen_rounded,
                              color: Colors.white70, size: 18),
                          tooltip: provider.t('split.backToFull'),
                          padding: EdgeInsets.zero,
                          constraints:
                              const BoxConstraints(minWidth: 28, minHeight: 28),
                          onPressed: _openSplitLeftAsFullscreen,
                        ),
                        IconButton(
                          icon: const Icon(Icons.close_rounded,
                              color: Colors.white60, size: 18),
                          tooltip: provider.t('split.closeLeft'),
                          padding: EdgeInsets.zero,
                          constraints:
                              const BoxConstraints(minWidth: 28, minHeight: 28),
                          onPressed: _closeSplitLeftPanel,
                        ),
                      ])),
                ),
                // ── PDF / Web の本体 ──
                // ・mode == 'web' なら Windows では _SplitWindowsWebView
                //                       それ以外は flutter_inappwebview
                // ・mode == 'pdf' なら SfPdfViewer (= 既存)
                // ・どちらも無ければ「未選択」 placeholder
                //
                // ユーザー要望: 「左側に移そうとすると真っ白な全画面になって
                //   フリーズする」 への対応で、 Windows では右パネルと同じく
                //   webview_windows を使う (= flutter_inappwebview は Windows
                //   サポートが不安定なのでハング回避)。
                Expanded(
                  // ── Office モード (pptx / docx / xlsx) を最優先で判定 ──
                  // ユーザー要望「word もパワポも画面分割に対応させて」 +
                  //   「word や excel が左画面分割に対応していないから対応
                  //   するようにして」。
                  // 左パネルでは webview/PDF の右端スクロールバーがリサイズハンドル
                  //   (右端 12px) と重なるので、 本体を右に 12px 余白を入れてずらす
                  //   (= ユーザー要望: 左に AI チャット欄を出すと境界とスクロール
                  //    バーが同じ位置に来る不具合の修正)。
                  child: Padding(
                    padding: const EdgeInsets.only(right: 12),
                    child: (_splitLeftMode == 'pptx' ||
                                _splitLeftMode == 'docx' ||
                                _splitLeftMode == 'xlsx' ||
                                _splitLeftMode == 'txt') &&
                            _splitLeftLocalOfficePath != null
                        // ── 右ペインと同じく、 閉じる時の pop がアプリ
                        //    本体の画面を巻き添えにしないよう専用の
                        //    Navigator を挟む ──
                        ? _SplitCellEmbeddedPanel(
                            key: ValueKey('splitLeftOffice:'
                                '$_splitLeftMode:$_splitLeftLocalOfficePath'),
                            onClose: _closeSplitLeftPanel,
                            builder: (ctx) => _buildSplitOfficeViewer(
                              ctx,
                              mode: _splitLeftMode,
                              path: _splitLeftLocalOfficePath!,
                              fileName: _splitLeftOfficeFileName,
                            ),
                          )
                        : _splitLeftMode == 'web' &&
                                _splitLeftCurrentUrl.isNotEmpty
                            ? Stack(
                                children: [
                                  Positioned.fill(
                                    child: Listener(
                                      // マウスホイールで Web をスクロール (= ユーザー要望)
                                      onPointerSignal: (e) =>
                                          _scrollSplitWebByWheel(e, left: true),
                                      child: Platform.isWindows
                                          ? _SplitWindowsWebView(
                                              key: _splitWebKeyLeft,
                                              url: _splitLeftCurrentUrl,
                                              onControllerReady: (c) {
                                                _splitLeftWinController = c;
                                                _scheduleSplitVideoProbe(
                                                    leftPanel: true);
                                              },
                                              onInitialized: () {
                                                setState(() =>
                                                    _splitLeftWinInitialized =
                                                        true);
                                                _scheduleSplitVideoProbe(
                                                    leftPanel: true);
                                              },
                                              // ── 現在 URL を追跡 (左パネル版) ──
                                              // 全画面切り替えでセッション保持。
                                              onUrlChanged: (u) {
                                                if (u != _splitLeftCurrentUrl &&
                                                    mounted) {
                                                  // # から後ろだけの変化では
                                                  // 画面を作り直さない
                                                  // (= ユーザー報告: DeepL)。
                                                  if (_urlWithoutFragment(u) ==
                                                      _urlWithoutFragment(
                                                          _splitLeftCurrentUrl)) {
                                                    _splitLeftCurrentUrl = u;
                                                    return;
                                                  }
                                                  setState(() =>
                                                      _splitLeftCurrentUrl = u);
                                                  _scheduleSplitVideoProbe(
                                                      leftPanel: true);
                                                }
                                              },
                                            )
                                          : iaw.InAppWebView(
                                              initialUrlRequest: iaw.URLRequest(
                                                  url: iaw.WebUri(
                                                      _splitLeftCurrentUrl)),
                                              onWebViewCreated: (ctrl) {
                                                _splitLeftIawController = ctrl;
                                                // モバイル版: クリップボード polyfill
                                                _installClipboardPolyfill(ctrl);
                                              },
                                              onLoadStop: (c, url) async {
                                                // クリップボード polyfill JS を再注入
                                                await _injectClipboardPolyfillJs(
                                                    c);
                                                // 遷移後に速度を再適用 (左パネル)
                                                await _applySplitVideoPlaybackRate(
                                                    _splitVideoPlaybackRate,
                                                    leftPanel: true);
                                                _scheduleSplitVideoProbe(
                                                    leftPanel: true);
                                              },
                                            ),
                                    ),
                                  ),
                                  // ── 動画サイトなら速度バーを上部にオーバーレイ ──
                                  // ユーザー要望「右画面分割した時だけ再生速度調整
                                  //   バーが出てくるの変だから、 左分割の際にも再生
                                  //   速度調整バーが出るようにして」 への対応。
                                  // 右パネルと同じ判定 (_isLikelyVideoUrl) を使い、
                                  // Google 検索や SNS など動画埋め込みが入りうるサイト
                                  // でもバーが出る。
                                  if (_isLikelyVideoUrl(_splitLeftCurrentUrl) ||
                                      _splitLeftHasVideo)
                                    Positioned(
                                      left: 8,
                                      right: 8,
                                      top: 8,
                                      child: _buildSplitVideoSpeedBar(),
                                    ),
                                ],
                              )
                            : pdfPath != null
                                // ── 図形・線 描き込みレイヤー
                                //    (= ユーザー要望) ──
                                ? PdfDrawLayer(
                                    active: _splitLeftPdfDrawActive,
                                    filePath: pdfPath,
                                    controller: _splitLeftPdfController,
                                    tr: provider.t,
                                    onExit: () {
                                      if (mounted) {
                                        setState(() =>
                                            _splitLeftPdfDrawActive = false);
                                      }
                                    },
                                    onSaved: () {
                                      if (mounted) {
                                        setState(
                                            () => _splitLeftPdfReloadTick++);
                                      }
                                    },
                                    child: Container(
                                    color: Colors.white,
                                    child: Listener(
                                      behavior: HitTestBehavior.translucent,
                                      // 押した所を覚えておく (= 文字の箱を
                                      // そこへ出すため)。
                                      onPointerDown: (e) =>
                                          _splitPdfDownGlobal = e.position,
                                      onPointerSignal: _onSplitLeftPdfWheel,
                                      child: ExcludeFocus(
                                        child: sf_pdf.SfPdfViewer.file(
                                          File(pdfPath),
                                          // 書き込み後に読み直すための鍵。
                                          key: ValueKey(
                                              'splpdfL_${pdfPath}_$_splitLeftPdfReloadTick'),
                                          controller: _splitLeftPdfController,
                                          // ── タップした場所へ書き込む
                                          //    (= ユーザー要望: テキスト /
                                          //    チェック) ──
                                          onTap: (d) => unawaited(
                                              _handleSplitPdfTap(d,
                                                  left: true)),
                                          pageLayoutMode: sf_pdf
                                              .PdfPageLayoutMode.continuous,
                                          scrollDirection: sf_pdf
                                              .PdfScrollDirection.vertical,
                                          enableDoubleTapZooming: true,
                                          maxZoomLevel: 8.0,
                                          onPageChanged: (details) {
                                            if (!mounted) return;
                                            _applyPdfPageChange(() {
                                              _splitLeftCurrentPage =
                                                  details.newPageNumber;
                                              if (_splitLeftPageInputCtrl
                                                      .text !=
                                                  '${details.newPageNumber}') {
                                                _splitLeftPageInputCtrl.text =
                                                    '${details.newPageNumber}';
                                              }
                                            });
                                            // 最終ページ記録
                                            try {
                                              provider.setLastPdfPage(pdfPath,
                                                  details.newPageNumber);
                                            } catch (_) {}
                                          },
                                          onDocumentLoaded: (details) {
                                            if (!mounted) return;
                                            setState(() {
                                              _splitLeftTotalPages =
                                                  details.document.pages.count;
                                              _splitLeftPageInputCtrl.text =
                                                  '$_splitLeftCurrentPage';
                                            });
                                            // 書き込み後の読み直しで元の
                                            // ページへ戻る。
                                            if (_splitLeftCurrentPage > 1 &&
                                                _splitLeftCurrentPage <=
                                                    details.document.pages
                                                        .count) {
                                              Future.delayed(
                                                  const Duration(
                                                      milliseconds: 150), () {
                                                if (!mounted) return;
                                                try {
                                                  _splitLeftPdfController
                                                      .jumpToPage(
                                                          _splitLeftCurrentPage);
                                                } catch (_) {}
                                              });
                                            }
                                            // 最終ページ復元
                                            try {
                                              final lastPage = provider
                                                  .lastPdfPageFor(pdfPath);
                                              if (lastPage != null &&
                                                  lastPage >= 1 &&
                                                  lastPage <=
                                                      _splitLeftTotalPages) {
                                                Future.delayed(
                                                    const Duration(
                                                        milliseconds: 200), () {
                                                  if (!mounted) return;
                                                  try {
                                                    _splitLeftPdfController
                                                        .jumpToPage(lastPage);
                                                    setState(() {
                                                      _splitLeftCurrentPage =
                                                          lastPage;
                                                      _splitLeftPageInputCtrl
                                                          .text = '$lastPage';
                                                    });
                                                  } catch (_) {}
                                                });
                                              }
                                            } catch (_) {}
                                          },
                                        ), // SfPdfViewer 閉じ
                                      ), // ExcludeFocus 閉じ
                                    ), // Listener 閉じ
                                  ), // Container 閉じ
                                  ) // PdfDrawLayer 閉じ
                                : Container(
                                    color: const Color(0xFF13132A),
                                    alignment: Alignment.center,
                                    child: Text(provider.t('split.noPdf'),
                                        style:
                                            TextStyle(color: Colors.white38)),
                                  ),
                  ),
                ),
                // ── PDF 横スクロールバー ──
                // ユーザー要望: 「画面を拡大した際、 表示領域内を左右に動かせる
                // バーを PDF の下に付けて欲しい」。
                // zoomLevel > 1.0 (= PDF が拡大されてはみ出している) ときだけ
                // 表示。 Slider を動かすと scrollOffset.dx が変わる。
                // _splitLeftPdfHorizontalScroll: 0.0〜1.0 で現在位置を保持。
                if (pdfPath != null)
                  _SplitPdfHorizontalScrollBar(
                    controller: _splitLeftPdfController,
                    panelWidth: width,
                    accent: const Color(0xFFFF6B6B),
                  ),
              ],
            ),
            // ── 左パネルのリサイズハンドル ──
            // 右端 (= マップ側との境界) に縦バー。 ドラッグで _splitLeftPanelWidth
            // を更新。 `_SplitPosition.left` を渡すと右端にハンドルが配置される。
            _ResizeHandle(
              splitPosition: _SplitPosition.left,
              onHorizontalDrag: (d) {
                setState(() {
                  // _SplitPosition.left の sign は 1 (= 右にドラッグすると広がる)
                  _splitLeftPanelWidth = (_splitLeftPanelWidth + d.delta.dx)
                      .clamp(240.0, mq.size.width * 0.9);
                });
              },
              onVerticalDrag: (d) {/* 縦方向は使わない */},
            ),
          ]), // Stack 閉じ
        ), // Material 閉じ
      ), // MouseRegion 閉じ
    );
  }

  /// 上分割パネルを「ヘッダーのすぐ下」 に被せるオーバーレイ。
  ///
  /// Flex に入れず Scaffold の上の Stack に重ねる形は従来どおり
  /// (旧実装の Flex 縦 + WebView はフリーズしたため)。 ただし以前は
  /// `top: 0` でヘッダーごと覆っていて、 **ヘッダーのボタンが一切押せなく
  /// なっていた** (= ユーザー報告: モバイルで上分割にするとヘッダー項目が
  /// 開けない)。 Stack は後の子が当たり判定を取るうえ、 パネルの中身
  /// (WebView / PDF) が不透明なのでタップを全部吸っていた。
  /// AppBar のぶんだけ下げて重ならないようにする。
  double _headerBottomInset(MindMapProvider provider) {
    final showMobileHeaderTray =
        !_isDesktop && provider.currentPage.pageType != 'markdown';
    return MediaQuery.of(context).padding.top +
        kToolbarHeight +
        (showMobileHeaderTray && _mobileHeaderCustomOpen
            ? _kHeaderCustomBarHeight
            : 0.0);
  }

  Widget _buildTopSplitOverlay(MindMapProvider provider) {
    return Positioned(
      top: _headerBottomInset(provider),
      left: 0,
      right: 0,
      // height は指定せず、 中身 (高さ panelSize の SizedBox) に任せる。
      // ★ SafeArea は外した。 上端の余白は _headerBottomInset で足して
      //   いるので、 残すと二重に下がる。
      child: Material(
        elevation: 12,
        color: const Color(0xFF13132A),
        child: _buildSplitPanel(provider),
      ),
    );
  }

  /// 画面分割パネルの URL 入力ダイアログ (インライン/メニュー共通)。
  Future<void> _splitOpenUrlDialog() async {
    final provider = context.read<MindMapProvider>();
    final urlCtrl = TextEditingController(text: _splitCurrentUrl);
    final url = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E2E),
        title: Text(provider.t('split.enterUrl'),
            style: const TextStyle(color: Colors.white)),
        content: TextField(
          controller: urlCtrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          decoration: const InputDecoration(
            hintText: 'https://example.com',
            hintStyle: TextStyle(color: Colors.white30),
          ),
          onSubmitted: (v) => Navigator.of(ctx).pop(v),
        ),
        actions: [
          TextButton(
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
            onPressed: () => Navigator.of(ctx).pop(null),
          ),
          TextButton(
            child: Text(provider.t('btn.open'),
                style: const TextStyle(color: Color(0xFF6C63FF))),
            onPressed: () => Navigator.of(ctx).pop(urlCtrl.text),
          ),
        ],
      ),
    );
    if (url != null && url.trim().isNotEmpty) {
      _splitLoadUrl(url);
    }
  }

  /// 画面分割を閉じて、 同じ内容を全画面ビューアで開き直す (インライン/メニュー共通)。
  Future<void> _splitReturnToFullscreen() async {
    if (_splitCurrentUrl.isEmpty) return;
    final url = _splitCurrentUrl;
    final isLocal = _splitLocalPdfPath != null;
    final originNodeId = _splitOriginNodeId;
    // 画面分割で設定していた再生速度を全画面に引き継ぐ (ユーザー要望)。
    final rate = _splitVideoPlaybackRate;
    setState(() {
      _setSplitOpen(false);
    });
    // ── 動画 (YouTube / mp4 / ローカル動画) は専用のフルスクリーン動画
    //    プレイヤーで開き直す (= ユーザー報告: 画面分割から全画面に戻すと、
    //    分割パネルのままの Web ビューア UI で戻ってしまい、 動画プレイヤーの
    //    操作ボタン群 (埋め込み/PiP/メモ/AI/分割/速度) が揃わない) ──
    // _openFullscreenVideo は内部で onMoveToSplitPanel も配線するので、
    // そのまま再び分割へ戻す動線も維持される。
    final isVideo = !isLocal &&
        (NodeWidget.extractVideoId(url) != null ||
            NodeWidget.isMp4Url(url) ||
            _isLocalVideoFile(url));
    if (isVideo) {
      await _openFullscreenVideo(context, url: url, initialRate: rate);
      return;
    }
    await _showInAppViewer(
      context,
      isLocal ? _splitLocalPdfPath! : url,
      isLocalFile: isLocal,
      nodeId: originNodeId,
      initialRate: rate,
    );
  }

  /// モバイル: 画面分割パネルの操作ボタンを 1 つに集約したメニュー (ユーザー要望)。
  /// 上分割 / 下分割 / 全画面 / URL / スマート移動 / 速度バー / 閉じる をまとめる。
  void _showMobileSplitMenu(MindMapProvider provider) {
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: const Color(0xFF1A1A30),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(16)),
      ),
      builder: (sheetCtx) {
        Widget item(Object icon, String label, VoidCallback onTap,
            {Color? color, bool selected = false}) {
          final iconColor = color ?? Colors.white70;
          return ListTile(
            dense: true,
            leading: icon is IconData
                ? Icon(icon, color: iconColor, size: 20)
                : SizedBox(
                    width: 20,
                    height: 20,
                    child: Center(child: icon as Widget)),
            title: Text(label,
                style: TextStyle(
                    color: selected ? const Color(0xFF6C63FF) : Colors.white,
                    fontSize: 14,
                    fontWeight: selected ? FontWeight.w700 : FontWeight.w500)),
            trailing: selected
                ? const Icon(Icons.check_rounded,
                    color: Color(0xFF6C63FF), size: 18)
                : null,
            onTap: onTap,
          );
        }

        final isWeb = _splitMode == 'web';
        return SafeArea(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const SizedBox(height: 8),
              Container(
                width: 40,
                height: 4,
                decoration: BoxDecoration(
                    color: Colors.white24,
                    borderRadius: BorderRadius.circular(2)),
              ),
              const SizedBox(height: 8),
              // ① 上分割
              item(
                  _splitPanelIcon(_SplitIconFill.top,
                      color: const Color(0xFFFF6B6B), size: 20),
                  provider.t('ve.splitUp'), () {
                Navigator.of(sheetCtx).pop();
                setState(() => _splitPosition = _SplitPosition.top);
              }, selected: _splitPosition == _SplitPosition.top),
              // ② 下分割
              item(
                  _splitPanelIcon(_SplitIconFill.bottom,
                      color: const Color(0xFF2196F3), size: 20),
                  provider.t('ve.splitDown'), () {
                Navigator.of(sheetCtx).pop();
                setState(() => _splitPosition = _SplitPosition.bottom);
              }, selected: _splitPosition == _SplitPosition.bottom),
              const Divider(color: Colors.white12, height: 1),
              // 再生速度バー (動画サイト時のみ)
              if (isWeb)
                item(Icons.speed_rounded,
                    _splitVideoBarExpanded ? '速度バーを隠す' : '速度バーを表示', () {
                  Navigator.of(sheetCtx).pop();
                  setState(
                      () => _splitVideoBarExpanded = !_splitVideoBarExpanded);
                }),
              // ── ページ再読込 / ログアウト (= ユーザー要望: AI チャット欄の
              //    フリーズ対策 + Google アカウント切替) ──
              if (isWeb)
                item(Icons.refresh_rounded, 'ページを再読込', () {
                  Navigator.of(sheetCtx).pop();
                  _reloadSplitPanel(isLeft: false);
                }),
              if (isWeb)
                item(
                    Icons.logout_rounded,
                    context
                        .read<MindMapProvider>()
                        .t('menu.logoutSwitchAccount'), () {
                  Navigator.of(sheetCtx).pop();
                  _confirmClearSplitLogin(isLeft: false);
                }),
              // URL を開く
              item(Icons.link_rounded, 'URL を開く', () {
                Navigator.of(sheetCtx).pop();
                _splitOpenUrlDialog();
              }),
              // 全画面表示に戻る
              item(Icons.fullscreen_rounded, '全画面表示に戻る', () {
                Navigator.of(sheetCtx).pop();
                _splitReturnToFullscreen();
              }),
              const Divider(color: Colors.white12, height: 1),
              // 閉じる
              item(Icons.close_rounded, provider.t('split.close'), () {
                Navigator.of(sheetCtx).pop();
                _toggleSplitPanel();
              }, color: const Color(0xFFFF6B6B)),
              const SizedBox(height: 8),
            ],
          ),
        );
      },
    );
  }

  /// 画面分割パネルの WebView を再読込する (= ユーザー要望: ChatGPT/Claude
  /// 等の AI チャット欄がフリーズした時更新できるように)。
  Future<void> _reloadSplitPanel({bool isLeft = false}) async {
    try {
      if (Platform.isWindows) {
        await (isLeft ? _splitLeftWinController : _splitWinController)
            ?.reload();
      } else {
        await (isLeft ? _splitLeftIawController : _splitIawController)
            ?.reload();
      }
    } catch (_) {}
  }

  /// 画面分割パネルの WebView の Cookie/キャッシュをクリアしてログアウトする
  /// (= ユーザー要望: ログアウトしても前回のアカウントで開かれるバグの対策 +
  ///  サイトにログインする Google アカウントの切替)。
  /// 注: WebView の Cookie ストアはプラットフォーム制約でアプリ全体で共有の
  ///   ため、 これで全サイトのログインが切れる。 ログインし直すと別アカウントを
  ///   選べる (= 個別プロファイルの同時保持はプラットフォーム上不可)。
  Future<void> _clearSplitLoginSession({bool isLeft = false}) async {
    final provider = context.read<MindMapProvider>();
    try {
      if (Platform.isWindows) {
        final c = isLeft ? _splitLeftWinController : _splitWinController;
        await c?.clearCookies();
        await c?.clearCache();
        await c?.reload();
      } else {
        await iaw.CookieManager.instance().deleteAllCookies();
        final c = isLeft ? _splitLeftIawController : _splitIawController;
        await c?.evaluateJavascript(
            source:
                'try{localStorage.clear();sessionStorage.clear();}catch(e){}');
        await c?.reload();
      }
      if (mounted) {
        _appSnack(
          context,
          SnackBar(
            content: Text(provider.t('split.cookieCleared')),
            backgroundColor: const Color(0xFF6C63FF),
            duration: const Duration(seconds: 4),
          ),
        );
      }
    } catch (_) {}
  }

  /// ログアウト (Cookie クリア) の確認ダイアログ。
  Future<void> _confirmClearSplitLogin({bool isLeft = false}) async {
    final provider = context.read<MindMapProvider>();
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('split.logoutTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        content: Text(provider.t('split.logoutBody'),
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, false),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF6C63FF),
                foregroundColor: Colors.white,),
            onPressed: () => Navigator.pop(dctx, true),
            child: Text(provider.t('btn.logout'),
                style: const TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
    if (ok == true) {
      await _clearSplitLoginSession(isLeft: isLeft);
    }
  }

  /// 設定メニューから呼ぶ「Google アカウントのログイン記憶を抹消」 (= ユーザー
  /// 要望: ログアウトしてもアカウント情報が残り続けるので消したい)。
  /// 分割パネルが開いていなくても動くよう、 Windows では一時コントローラを
  /// 作って Cookie/キャッシュを消す (= WebView2 のプロファイルはプロセスで
  /// 共有なので、 全 WebView のログインが消える)。
  Future<void> _confirmClearAllWebLogin() async {
    final provider = context.read<MindMapProvider>();
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('split.clearLoginTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        content: Text(provider.t('split.clearLoginBody'),
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, false),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFE53935),
                foregroundColor: Colors.white,),
            onPressed: () => Navigator.pop(dctx, true),
            child: Text(provider.t('btn.erase'),
                style: const TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
    if (ok != true) return;
    bool success = false;
    try {
      if (!kIsWeb && Platform.isWindows) {
        // 一時コントローラを初期化 → Cookie/キャッシュ消去 → 破棄。
        final c = wv_win.WebviewController();
        await c.initialize();
        await c.clearCookies();
        await c.clearCache();
        await c.dispose();
        success = true;
      } else if (!kIsWeb) {
        await iaw.CookieManager.instance().deleteAllCookies();
        success = true;
      }
    } catch (e) {
      debugPrint('Web ログイン消去に失敗: $e');
    }
    if (!mounted) return;
    _appSnack(
      context,
      SnackBar(
        content: Text(success
            ? 'ログイン情報 (Cookie) を消去しました。 次回は再ログインが必要です。'
            : 'ログイン情報の消去に失敗しました。'),
        backgroundColor:
            success ? const Color(0xFF6C63FF) : const Color(0xFFE57373),
        duration: const Duration(seconds: 4),
      ),
    );
  }

  Widget _buildSplitPanel(MindMapProvider provider) {
    if (!_splitOpen) return const SizedBox.shrink();
    final mq = MediaQuery.of(context);
    final isVertical = _splitPosition == _SplitPosition.top ||
        _splitPosition == _SplitPosition.bottom;
    final panelSize = _splitPanelEffectiveSize(context);
    return SizedBox(
      // 左右分割なら幅で指定、 上下分割なら高さで指定。
      width: isVertical ? null : panelSize,
      height: isVertical ? panelSize : null,
      // ── マウス hover 検知 (= 念のための保険) ──
      // Row 分離で原則ホイールイベントは漏れないが、 ノードのドラッグ
      // (= グローバルポインタ追跡) などの稀なケースに備えて、 パネル
      // 領域ホバー中はメインキャンバスの InteractiveViewer の pan/scale を
      // 一時停止する仕組みも維持。
      child: MouseRegion(
        onEnter: (_) {
          // ── 排他化 (= ユーザー要望「左分割した画面が他のマップや
          //   右分割した画面にカーソルを載せた状態でもずっとアクティブに
          //   なっていて、 マップ等とスクロールが連動してしまう問題」) ──
          // WebView や Pdf Viewer の Platform View が onExit を発火し
          // 損ねるケースがあるため、 反対側の hover に入った時にこちら
          // 側で強制的に左パネル hover を false にして「片方しか
          // アクティブにならない」 状態を保証する。
          if (!_splitPanelHover || _splitLeftPanelHover) {
            setState(() {
              _splitPanelHover = true;
              _splitLeftPanelHover = false;
            });
          }
        },
        onExit: (_) {
          if (_splitPanelHover) {
            setState(() => _splitPanelHover = false);
          }
        },
        child: Material(
          color: const Color(0xFF13132A),
          elevation: 8,
          child: Stack(
            children: [
              Column(
                children: [
                  // ── 上部バー (= 左パネルヘッダーと同じ構造) ──
                  // ユーザー要望: 「右画面分割の上は左画面分割の上に揃えろ」。
                  // 左パネルと同一のレイアウト (mode アイコン → タイトル →
                  // URL入力 → ページ番号 → 前/次 → 入れ替え → 全画面 → 閉じる)
                  // で並べる。 高さ・padding・アイコンサイズも左パネルに合わせ
                  // て 40 / 6 / 16〜20 に統一。
                  //
                  // 旧仕様で右パネルだけ持っていた「位置切替 / 再読込 / URL バー
                  // 展開 / 検索アイコン / PDF 開く」 は、 統一性を優先して
                  // ヘッダーから外した (= 機能自体は他経路で代替できる)。
                  Container(
                    height: 40,
                    padding: const EdgeInsets.symmetric(horizontal: 6),
                    decoration: const BoxDecoration(
                      color: Color(0xFF1A1A30),
                      border: Border(
                        bottom: BorderSide(color: Colors.white12, width: 1),
                      ),
                    ),
                    child: GestureDetector(
                        // ── ヘッダー右クリックで同じ AI を反対側にも複製 (= ユーザー要望) ──
                        behavior: HitTestBehavior.translucent,
                        onSecondaryTap: () =>
                            _duplicateSplitAiToOpposite(fromLeft: false),
                        child: Row(children: [
                          Icon(
                            _splitMode == 'web'
                                ? Icons.public_rounded
                                : Icons.picture_as_pdf_rounded,
                            size: 18,
                            color: _splitMode == 'web'
                                ? const Color(0xFF6C63FF)
                                : const Color(0xFFFF6B6B),
                          ),
                          const SizedBox(width: 6),
                          Flexible(
                            child: Text(
                              _splitMode == 'web' && _splitCurrentUrl.isNotEmpty
                                  ? _splitCurrentUrl
                                  : (_splitLocalPdfPath != null
                                      ? _splitLocalPdfPath!
                                          .split(RegExp(r'[/\\]'))
                                          .last
                                      : '(未選択)'),
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: Colors.white70, fontSize: 12),
                            ),
                          ),
                          const SizedBox(width: 6),
                          // ── ページ番号入力 (PDF 時のみ表示) ──
                          if (_splitMode == 'pdf' && _splitPdfTotalPages > 0)
                            SizedBox(
                              width: 56,
                              child: TextField(
                                controller: _splitJumpPageCtrl,
                                style: const TextStyle(
                                    color: Colors.white, fontSize: 11),
                                textAlign: TextAlign.center,
                                keyboardType: TextInputType.number,
                                inputFormatters: const [
                                  _FullWidthDigitToHalfFormatter()
                                ],
                                decoration: const InputDecoration(
                                  isDense: true,
                                  contentPadding:
                                      EdgeInsets.symmetric(vertical: 4),
                                  border: OutlineInputBorder(
                                    borderSide:
                                        BorderSide(color: Colors.white24),
                                  ),
                                ),
                                onSubmitted: (v) {
                                  final p = int.tryParse(v);
                                  if (p != null &&
                                      p >= 1 &&
                                      p <= _splitPdfTotalPages) {
                                    try {
                                      _splitPdfController.jumpToPage(p);
                                    } catch (_) {}
                                  }
                                },
                              ),
                            ),
                          if (_splitMode == 'pdf' && _splitPdfTotalPages > 0)
                            Padding(
                              padding:
                                  const EdgeInsets.symmetric(horizontal: 4),
                              child: Text(
                                '/ $_splitPdfTotalPages',
                                style: const TextStyle(
                                    color: Colors.white54, fontSize: 11),
                              ),
                            ),
                          // ── PDF への書き込み (= ユーザー要望: テキスト /
                          //    チェック)。 ローカルファイルの時だけ。 ──
                          if (_splitMode == 'pdf' &&
                              _splitLocalPdfPath != null)
                            _pdfWriteModeButtons(left: false),
                          // ── 操作ボタン ──
                          // モバイルは全ボタンを 1 つの ⋮ メニューに集約 (ユーザー要望)。
                          //   上分割/下分割もメニュー内に含める。 デスクトップは
                          //   従来通りインライン表示。
                          if (_isDesktop) ...[
                            // URL 入力ボタン
                            IconButton(
                              icon: const Icon(Icons.link_rounded,
                                  color: Colors.white60, size: 16),
                              tooltip: provider.t('split.openUrl'),
                              padding: EdgeInsets.zero,
                              constraints: const BoxConstraints(
                                  minWidth: 28, minHeight: 28),
                              onPressed: _splitOpenUrlDialog,
                            ),
                            // ── PDF の隣 (左) に生成 AI を開くボタン (新規) ──
                            // ユーザー要望:「PDF を表示している左側に、5 種類の
                            //   生成 AI から選んで AI 会話ボックスを開けるように」。
                            //   PDF 表示中のみ表示し、選んだ AI を左パネルに開く。
                            if (_splitMode == 'pdf')
                              PopupMenuButton<String>(
                                tooltip: provider.t('split.openAiLeft'),
                                // 色は隣のボタンと揃える (= ユーザー要望:
                                // AI アイコンだけ色が付いていて目立つ)。
                                icon: const Icon(Icons.smart_toy_rounded,
                                    color: Colors.white60, size: 18),
                                padding: EdgeInsets.zero,
                                color: const Color(0xFF1E1E32),
                                onSelected: _openAiInLeftPanel,
                                itemBuilder: (_) => const [
                                  PopupMenuItem(
                                      value: 'chatgpt',
                                      child: Text('ChatGPT',
                                          style:
                                              TextStyle(color: Colors.white))),
                                  PopupMenuItem(
                                      value: 'gemini',
                                      child: Text('Gemini',
                                          style:
                                              TextStyle(color: Colors.white))),
                                  PopupMenuItem(
                                      value: 'claude',
                                      child: Text('Claude',
                                          style:
                                              TextStyle(color: Colors.white))),
                                  PopupMenuItem(
                                      value: 'deepseek',
                                      child: Text('DeepSeek',
                                          style:
                                              TextStyle(color: Colors.white))),
                                  PopupMenuItem(
                                      value: 'grok',
                                      child: Text('Grok',
                                          style:
                                              TextStyle(color: Colors.white))),
                                ],
                              ),
                            // スマート左右移動ボタン (前/次/入れ替え統合)
                            IconButton(
                              icon: Icon(_smartMoveIcon(fromLeft: false),
                                  color: Colors.white70, size: 18),
                              tooltip: _smartMoveTooltip(fromLeft: false),
                              padding: EdgeInsets.zero,
                              constraints: const BoxConstraints(
                                  minWidth: 28, minHeight: 28),
                              onPressed: () => _smartMovePanel(fromLeft: false),
                            ),
                            // ── WebView 表示中のみ: 再読込 / ログアウト (= ユーザー要望) ──
                            if (_splitWinController != null ||
                                _splitIawController != null) ...[
                              // ページ再読込 (AI チャット欄のフリーズ対策)
                              IconButton(
                                icon: const Icon(Icons.refresh_rounded,
                                    color: Colors.white70, size: 18),
                                tooltip: provider.t('split.reload'),
                                padding: EdgeInsets.zero,
                                constraints: const BoxConstraints(
                                    minWidth: 28, minHeight: 28),
                                onPressed: () =>
                                    _reloadSplitPanel(isLeft: false),
                              ),
                              // ログアウト / 別アカウントでログイン (Cookie クリア)
                              IconButton(
                                icon: const Icon(Icons.logout_rounded,
                                    color: Colors.white70, size: 18),
                                tooltip: provider.t('split.relogin'),
                                padding: EdgeInsets.zero,
                                constraints: const BoxConstraints(
                                    minWidth: 28, minHeight: 28),
                                onPressed: () =>
                                    _confirmClearSplitLogin(isLeft: false),
                              ),
                            ],
                            // ── フローティングに切り替え (= ユーザー要望:
                            //    AI ボタンから開くチャット欄のヘッダーにも) ──
                            //    今のページを浮遊パネルに移して、 この分割
                            //    パネルは閉じる。 Web 表示の時だけ出す。
                            if (_splitMode == 'web')
                              IconButton(
                                icon: const Icon(
                                    Icons.picture_in_picture_alt_rounded,
                                    color: Colors.white70,
                                    size: 18),
                                tooltip: provider.t('split.toFloating'),
                                padding: EdgeInsets.zero,
                                constraints: const BoxConstraints(
                                    minWidth: 28, minHeight: 28),
                                onPressed: () {
                                  final url = _splitUrlCtrl.text.trim();
                                  _toggleSplitPanel();
                                  // 最初から外の本物の窓で開く (= 統合)。
                                  _openFloatingWebUnified(url);
                                },
                              ),
                            // 全画面表示に戻る
                            IconButton(
                              icon: const Icon(Icons.fullscreen_rounded,
                                  color: Colors.white70, size: 18),
                              tooltip: provider.t('split.backToFull'),
                              padding: EdgeInsets.zero,
                              constraints: const BoxConstraints(
                                  minWidth: 28, minHeight: 28),
                              onPressed: _splitReturnToFullscreen,
                            ),
                            // 閉じる
                            IconButton(
                              icon: const Icon(Icons.close_rounded,
                                  color: Colors.white60, size: 18),
                              tooltip: provider.t('split.close'),
                              padding: EdgeInsets.zero,
                              constraints: const BoxConstraints(
                                  minWidth: 28, minHeight: 28),
                              onPressed: _toggleSplitPanel,
                            ),
                          ] else
                            // モバイル: 1 つのメニューボタンに集約
                            IconButton(
                              icon: const Icon(Icons.more_vert_rounded,
                                  color: Colors.white70, size: 20),
                              tooltip: provider.t('common.menu'),
                              padding: EdgeInsets.zero,
                              constraints: const BoxConstraints(
                                  minWidth: 32, minHeight: 32),
                              onPressed: () => _showMobileSplitMenu(provider),
                            ),
                        ])),
                  ),
                  // ── コンテンツ本体 ──
                  Expanded(child: _buildSplitContent(provider)),
                  // ── PDF 横スクロールバー (右パネル) ──
                  // ユーザー要望: 「画面を拡大した際、 表示領域内を左右に動かせる
                  // バーを PDF の下に付けて欲しい」。
                  // PDF モード時のみ表示、 zoom > 1.0 の時だけ active。
                  if (_splitMode == 'pdf' && _splitCurrentUrl.isNotEmpty)
                    _SplitPdfHorizontalScrollBar(
                      controller: _splitPdfController,
                      panelWidth: panelSize,
                      accent: const Color(0xFF6C63FF),
                    ),
                ],
              ),
              // ── リサイズハンドル ──
              // パネル位置に応じて端を変える:
              //  - right:  左端 (= マップ境界) 縦バー、 onHorizontalDragUpdate
              //  - left:   右端 縦バー、 onHorizontalDragUpdate (反転)
              //  - top:    下端 横バー、 onVerticalDragUpdate
              //  - bottom: 上端 横バー、 onVerticalDragUpdate (反転)
              // 視認性向上のため:
              //  - hit test 領域は太め (12px) で確実に掴める
              //  - hover 時に紫色のハイライト + 中央に「掴むしるし」 を表示
              //  - 通常時はほぼ透明で UI を邪魔しない
              _ResizeHandle(
                splitPosition: _splitPosition,
                onHorizontalDrag: (d) {
                  setState(() {
                    final sign =
                        _splitPosition == _SplitPosition.left ? 1.0 : -1.0;
                    // ── Office モード (pptx/docx/xlsx) は最小幅を引き上げ ──
                    // ユーザー要望「pptx ファイルを画面分割して、 表示領域の
                    //   大きさを一定以上小さくすると項目が画面分割画面から
                    //   はみ出して押せなくなってしまうから、 項目がはみ出る
                    //   大きさまで表示領域を小さくできないようにして」 への
                    //   対応。 PPTX ビューアのヘッダーには「再生 / N枚目 /
                    //   ← / → / 保存 / DL / 外部 / 閉じる」 等のボタンが
                    //   並んでおり、 600px くらい必要。
                    //   旧 480px だと 9 ボタン全部は収まらず一部がはみ出る
                    //   問題があったので 580px へ引き上げ。
                    //   その他のモード (web / pdf 等) は従来通り 240px。
                    final isOfficeMode = _splitMode == 'pptx' ||
                        _splitMode == 'docx' ||
                        _splitMode == 'xlsx';
                    final minWidth = isOfficeMode ? 580.0 : 240.0;
                    _splitPanelWidth = (_splitPanelWidth + sign * d.delta.dx)
                        .clamp(minWidth, mq.size.width * 0.90);
                  });
                  // 端まで広げても勝手に全画面化しない (= ユーザー要望: 端に持って
                  //   行きすぎると少し動かすだけで全画面になって使いにくい)。 縦分割
                  //   と同様、 全画面にしたい時はビューアの全画面ボタンを使う。 上の
                  //   clamp で最大 90% に抑え、 常にマップ側が見える状態を保つ。
                },
                onVerticalDrag: (d) {
                  setState(() {
                    final sign =
                        _splitPosition == _SplitPosition.top ? 1.0 : -1.0;
                    // 縦分割でも Office モードでは高さ最小を引き上げ
                    // (= 縦に潰れすぎるとヘッダーとサムネ列が重なって
                    //   操作不能になるため)。
                    final isOfficeMode = _splitMode == 'pptx' ||
                        _splitMode == 'docx' ||
                        _splitMode == 'xlsx';
                    final minHeight = isOfficeMode ? 360.0 : 180.0;
                    _splitPanelWidth = (_splitPanelWidth + sign * d.delta.dy)
                        .clamp(minHeight, mq.size.height * 0.95);
                  });
                  // 縦分割（モバイル）では、境界まで広げても勝手に全画面化しない
                  //   (= ユーザー要望: 境界に触れると勝手に全画面になるのをやめる)。
                  //   全画面にしたいときはビューア側の全画面ボタンを使う。
                },
              ),
            ],
          ),
        ),
      ), // MouseRegion 閉じ
    );
  }

  /// コンテンツ本体 (URL に応じて WebView または PDF Viewer)。
  Widget _buildSplitContent(MindMapProvider provider) {
    // 「何も開いていない」 判定:
    //   URL が空 かつ Office ファイルパスも未設定。
    // ユーザー要望「pptx や docx ファイルが画面分割に対応していないのか
    //   画面分割ボタンを押しても出てこない」 への修正:
    //   旧仕様では `_splitCurrentUrl.isEmpty` だけで早期 return していた
    //   ため、 Office モード (mode == pptx/docx + _splitLocalOfficePath
    //   設定済み) でもヒント画面が出て、 Office 表示の分岐に到達できな
    //   かった。 _splitLocalOfficePath == null も AND して、 Office ファ
    //   イルが開かれている時はヒントをスキップする。
    if (_splitCurrentUrl.isEmpty && _splitLocalOfficePath == null) {
      // 何も開いていないときの初期状態 (使い方のヒント)
      return Container(
        color: const Color(0xFF0F0F1A),
        child: Center(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(Icons.public_rounded, color: Colors.white24, size: 56),
              const SizedBox(height: 14),
              Text(
                provider.t('split.urlHint'),
                style: const TextStyle(color: Colors.white54, fontSize: 13),
                textAlign: TextAlign.center,
              ),
              const SizedBox(height: 18),
              ElevatedButton.icon(
                onPressed: () =>
                    unawaited(_splitOpenLocalFile(leftPanel: false)),
                icon: const Icon(Icons.file_open_rounded,
                    size: 18, color: Colors.white),
                label: Text(provider.t('split.chooseFile'),
                    style: const TextStyle(color: Colors.white)),
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFFF6B6B),
                  foregroundColor: Colors.white,
                  shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(8)),
                ),
              ),
            ],
          ),
        ),
      );
    }
    // ── Office モード (pptx / docx / xlsx) ──
    // ユーザー要望: 「word もパワポも画面分割に対応させて」 +
    //   「word や excel が左画面分割に対応していないから対応するように
    //   して」 への対応。
    // _PptxViewerDialog / _DocxViewerDialog / _SpreadsheetEditorDialog
    // は元々 Container を返す通常の Widget なので、 画面分割パネル内に
    // 直接埋め込んで使える。
    if ((_splitMode == 'pptx' ||
            _splitMode == 'docx' ||
            _splitMode == 'xlsx' ||
            _splitMode == 'txt') &&
        _splitLocalOfficePath != null) {
      // ── ビューアは自分を閉じる時に `Navigator.of(context).pop()` を
      //    呼ぶ。 ペインへ直に置くと、 その pop がアプリ本体の画面を
      //    巻き添えにして真っ黒な画面が残ってしまう。 そこで分割セルと
      //    同じく専用の Navigator を挟み、 閉じたらペインを畳む。 ──
      return _SplitCellEmbeddedPanel(
        key: ValueKey('splitOffice:$_splitMode:$_splitLocalOfficePath'),
        onClose: _closeSplitRightPanelOnly,
        builder: (ctx) => _buildSplitOfficeViewer(
          ctx,
          mode: _splitMode,
          path: _splitLocalOfficePath!,
          fileName: _splitOfficeFileName,
        ),
      );
    }
    // ── PDF モード ──
    if (_splitMode == 'pdf') {
      // ローカルファイル or ネットワーク URL を判別
      // ★ 画面分割の SfPdfViewer 設定 ★
      // - controller を持って ↑↓ や PageUp/Down で自前スクロール
      // - enableTextSelection: false で OCR/テキスト選択 を無効化
      // - ExcludeFocus で囲んで、 SfPdfViewer 内部の Focus → 内蔵キー
      //   ハンドラが反応してしまうのを抑止 (= 左右キーで 2 ページ送られる
      //   不具合の解消)。 私の KeyboardListener が単独でキー処理を担う。
      // - scrollDirection: 上下分割の時は横スクロール (= ページめくり風)、
      //   左右分割の時は縦スクロール (= 既定)。
      final isVerticalSplit = _splitPosition == _SplitPosition.top ||
          _splitPosition == _SplitPosition.bottom;
      final scrollDir = isVerticalSplit
          ? sf_pdf.PdfScrollDirection.horizontal
          : sf_pdf.PdfScrollDirection.vertical;
      final pdfViewer = _splitLocalPdfPath != null
          ? sf_pdf.SfPdfViewer.file(
              File(_splitLocalPdfPath!),
              // 書き込み後に読み直すための鍵。
              key: ValueKey(
                  'splpdfR_${_splitLocalPdfPath}_$_splitPdfReloadTick'),
              controller: _splitPdfController,
              // ── タップした場所へ書き込む (= ユーザー要望) ──
              onTap: (d) => unawaited(_handleSplitPdfTap(d, left: false)),
              enableTextSelection: false,
              canShowScrollHead: false,
              canShowPaginationDialog: true,
              scrollDirection: scrollDir,
              // ★ single モードに変更 ★
              // デフォルトの continuous は連続スクロールで複数ページが一度に
              // 見えるため、 「ページ非表示」 機能で jumpToPage しても直前の
              // 非表示ページが画面に残る問題があった。 single モードでは
              // 1 ページずつ表示なので、 jumpToPage 後は確実にそのページ
              // だけが画面に映る (= 非表示ページが完全にスキップされる)。
              pageLayoutMode: sf_pdf.PdfPageLayoutMode.continuous,
              onPageChanged: _handleSplitPdfPageChanged,
              onDocumentLoaded: _handleSplitPdfLoaded,
            )
          : sf_pdf.SfPdfViewer.network(
              _splitCurrentUrl,
              controller: _splitPdfController,
              enableTextSelection: false,
              canShowScrollHead: false,
              canShowPaginationDialog: true,
              scrollDirection: scrollDir,
              pageLayoutMode: sf_pdf.PdfPageLayoutMode.continuous,
              onPageChanged: _handleSplitPdfPageChanged,
              onDocumentLoaded: _handleSplitPdfLoaded,
            );
      // ── 右クリック検出 ──
      // PDF ビューア上で右クリック (= 副ボタン) されたら、 ノードと同じ
      // ページ操作メニューを表示する。 SfPdfViewer 自身は内部 GestureDetector
      // で副ボタンを処理しない (= テキスト選択メニューは別経路) ため、
      // Listener.onPointerDown で kSecondaryMouseButton を直接捕まえる。
      // behavior: translucent で SfPdfViewer 自身のパン/スクロールも生かす。
      // ── 図形・線 描き込みレイヤー (= ユーザー要望)。 ローカル PDF のみ。 ──
      return PdfDrawLayer(
        active: _splitPdfDrawActive && _splitLocalPdfPath != null,
        filePath: _splitLocalPdfPath,
        controller: _splitPdfController,
        tr: provider.t,
        onExit: () {
          if (mounted) setState(() => _splitPdfDrawActive = false);
        },
        onSaved: () {
          if (mounted) setState(() => _splitPdfReloadTick++);
        },
        child: Listener(
          behavior: HitTestBehavior.translucent,
          // ── 右クリックメニューは廃止 (= ユーザー要望: 「ページを非表示」 等
          //    の項目は要らない)。 右クリックは PDF 側の既定動作に任せる。 ──
          //    押した所は覚えておく (= 文字の箱をそこへ出すため)。
          onPointerDown: (event) => _splitPdfDownGlobal = event.position,
          // ── ページ移動時のオーバーレイは廃止 ──
          // ユーザー要望: 「今の右上にちょっとだけ出るページ番号表記は
          //   要らない」。 代わりに上部ヘッダーの入力欄に現在ページを
          //   常時表示するようにした (_splitJumpPageCtrl)。
          child: ExcludeFocus(child: pdfViewer),
        ),
      );
    }
    // ── Web モード ──
    // Windows は webview_windows (アプリ全体のパターンに合わせる)、
    // それ以外は flutter_inappwebview。
    // ── 動画サイト判定 (= 右パネル) ──
    // 動画タグが入りうるサイト全般で速度バーを出す。
    // (= 詳細は `_isLikelyVideoUrl` のコメント参照)
    final isVideoSite = _isLikelyVideoUrl(_splitCurrentUrl) || _splitHasVideo;
    Widget webViewWidget;
    if (Platform.isWindows) {
      webViewWidget = _SplitWindowsWebView(
        key: _splitWebKeyRight,
        url: _splitCurrentUrl,
        onControllerReady: (c) {
          _splitWinController = c;
          _scheduleSplitVideoProbe(leftPanel: false);
        },
        onInitialized: () {
          setState(() => _splitWinInitialized = true);
          _scheduleSplitVideoProbe(leftPanel: false);
        },
        // ── 現在 URL を追跡 (= 全画面切り替えでセッション保持) ──
        onUrlChanged: (u) {
          if (u != _splitCurrentUrl && mounted) {
            // # から後ろだけの変化 (= DeepL の入力等) では画面を作り直さない
            // (= ユーザー報告: 何度も初期化中に戻る)。 控えだけ更新する。
            if (_urlWithoutFragment(u) ==
                _urlWithoutFragment(_splitCurrentUrl)) {
              _splitCurrentUrl = u;
              _persistSplitPanelLastUrl(u);
              return;
            }
            setState(() => _splitCurrentUrl = u);
            _persistSplitPanelLastUrl(u);
            _scheduleSplitVideoProbe(leftPanel: false);
          }
        },
      );
    } else {
      webViewWidget = iaw.InAppWebView(
        initialUrlRequest: iaw.URLRequest(url: iaw.WebUri(_splitCurrentUrl)),
        initialSettings: iaw.InAppWebViewSettings(
          javaScriptEnabled: true,
          domStorageEnabled: true,
          useHybridComposition: true,
          mediaPlaybackRequiresUserGesture: false,
          allowsInlineMediaPlayback: true,
          transparentBackground: false,
          allowFileAccess: true,
          mixedContentMode:
              iaw.MixedContentMode.MIXED_CONTENT_COMPATIBILITY_MODE,
        ),
        onWebViewCreated: (c) {
          _splitIawController = c;
          // モバイル版のクリップボード貼り付け polyfill (= ユーザー要望:
          //   「このアプリでの貼り付けをサポートしていませんって出て画像
          //   やらをモバイル版で生成AIに渡せられないから渡せるようにして」)
          _installClipboardPolyfill(c);
        },
        // ── URL 変更を追跡 ──
        // ユーザーが YouTube のホームから動画ページに遷移した時等、
        // _splitCurrentUrl を最新の URL に更新する。
        // → 動画サイト判定 (= 速度バー表示) もリアルタイムに反映。
        onLoadStop: (c, url) async {
          if (url != null) {
            final s = url.toString();
            if (s != _splitCurrentUrl && mounted) {
              setState(() => _splitCurrentUrl = s);
              _persistSplitPanelLastUrl(s);
            }
          }
          // クリップボード polyfill JS を再注入 (= ナビゲーション後の
          // 新しい window コンテキストに当て直す)
          await _injectClipboardPolyfillJs(c);
          // 動画ページ遷移後、 既存の再生速度を再適用
          await _applySplitVideoPlaybackRate(_splitVideoPlaybackRate);
          _scheduleSplitVideoProbe(leftPanel: false);
        },
        onUpdateVisitedHistory: (c, url, _) {
          // SPA (YouTube 等) は onLoadStop が走らないので history で追跡
          if (url != null) {
            final s = url.toString();
            if (s != _splitCurrentUrl && mounted) {
              setState(() => _splitCurrentUrl = s);
              _persistSplitPanelLastUrl(s);
              _scheduleSplitVideoProbe(leftPanel: false);
            }
          }
        },
      );
    }
    // ── マウスホイールで Web ページをスクロール (= ユーザー要望) ──
    //   webview_windows がホイールを内部スクロールに転送しないことがあるため、
    //   ホイール量を JS の scrollBy に渡す。
    webViewWidget = Listener(
      onPointerSignal: (e) => _scrollSplitWebByWheel(e, left: false),
      child: webViewWidget,
    );
    if (!isVideoSite) return webViewWidget;
    // 動画サイト: WebView の上部に再生速度コントロールバーをオーバーレイ
    // (= ユーザー要望「上に出るようにして」)
    return Stack(
      children: [
        Positioned.fill(child: webViewWidget),
        Positioned(
          left: 8,
          right: 8,
          top: 8,
          child: _buildSplitVideoSpeedBar(),
        ),
      ],
    );
  }

  /// 画面分割で動画サイトを開いている時のオーバーレイ再生速度バー。
  /// Slider (1.0〜videoMaxRate) + 動的プリセットボタン。
  /// `<video>` タグの playbackRate を JS で直接書き換える。
  ///
  /// ユーザー要望: 「画面分割した時に再生速度が 2 倍までしか出せない」
  /// → 通常画面と同じ `provider.videoMaxRate` (1.5 〜 16.0、 デフォルト 5.0)
  /// まで対応。 最小値も 1.0 (= 0.5 倍等は不要) に変更。
  Widget _buildSplitVideoSpeedBar() {
    // 通常画面と共通の最大値を使う (= 設定で変更可能)
    final maxRate =
        context.watch<MindMapProvider>().videoMaxRate.clamp(1.5, 16.0);
    // ── プリセット ──
    // ユーザー要望「再生速度を設定する倍率ボタンが 3.8 倍とかイマイチ
    //   3.8 を 3、 5.5 を 4 にして」 への対応。 旧コードは
    //     (maxRate + 2.0) / 2 という補間値 (例: max=5.5 → 3.75 → 3.8x)
    //   になっていたため、 整数ベースのプリセットに変更:
    //     - max <= 2      → [1, 1.5, 2]
    //     - max <= 4      → [1, 1.5, 2, 3, max]   ← デフォルト
    //     - max <= 8      → [1, 2, 4, max]
    //     - max <= 16     → [1, 2, 4, 8, max]
    //   末尾の max が既存値と重複する場合は重複除去。
    final List<double> presets;
    if (maxRate <= 2.0 + 0.01) {
      presets = [1.0, 1.5, 2.0];
    } else if (maxRate <= 4.0 + 0.01) {
      presets = [1.0, 1.5, 2.0, 3.0, maxRate];
    } else if (maxRate <= 8.0 + 0.01) {
      presets = [1.0, 2.0, 4.0, maxRate];
    } else {
      presets = [1.0, 2.0, 4.0, 8.0, maxRate];
    }
    // 重複除去 + ソート
    final uniquePresetsSet = <double>{};
    for (final p in presets) {
      uniquePresetsSet.add(double.parse(p.toStringAsFixed(1)));
    }
    final sortedPresets = uniquePresetsSet.toList()..sort();
    // ── 折りたたみモード: 速度アイコン 1 つだけ ──
    // ユーザー要望「再生速度バーは折りたたんで目立たない形にできるように
    //   して」 への対応。 デフォルトは折りたたみ (= 邪魔にならない小さな
    //   アイコン)、 タップで通常バーを展開。
    if (!_splitVideoBarExpanded) {
      return Align(
        alignment: Alignment.topRight,
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          // 折りたたみ時も「縦いっぱい」 トグルは出しておく (= ユーザー要望の
          // 主目的なので、 バーを開かずに 1 タップで切り替えられるように)。
          _splitVideoFillToggle(),
          const SizedBox(width: 6),
          Material(
            color: Colors.transparent,
            child: InkWell(
              borderRadius: BorderRadius.circular(20),
              onTap: () => setState(() => _splitVideoBarExpanded = true),
              child: Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                decoration: BoxDecoration(
                  color: Colors.black.withValues(alpha: 0.55),
                  borderRadius: BorderRadius.circular(20),
                  border:
                      Border.all(color: Colors.white.withValues(alpha: 0.15)),
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Icon(Icons.speed_rounded,
                        color: Color(0xFF6C63FF), size: 16),
                    const SizedBox(width: 4),
                    Text(
                      '${_splitVideoPlaybackRate.toStringAsFixed(1)}x',
                      style: const TextStyle(
                        color: Colors.white,
                        fontSize: 11,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ]),
      );
    }
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: Colors.black.withValues(alpha: 0.75),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: Colors.white12),
      ),
      child: Row(
        children: [
          // ── 左端: 最大倍率設定メニュー ──
          // ユーザー要望「左端のアイコンをクリックすることで再生速度の
          //   最大倍率を設定できるようにして、 デフォルトでは 4 倍まで
          //   にしておいて」 への対応。 PopupMenuButton 化することで、
          //   アイコンクリック → 倍率プリセット選択 → 即反映。
          PopupMenuButton<double>(
            tooltip: context.read<MindMapProvider>().t('video.maxRate'),
            padding: EdgeInsets.zero,
            color: const Color(0xFF1A1A2E),
            icon: const Icon(Icons.speed_rounded,
                color: Color(0xFF6C63FF), size: 18),
            onSelected: (v) async {
              await context.read<MindMapProvider>().setVideoMaxRate(v);
              // 現在の速度値が新最大を超えていたら丸める
              if (_splitVideoPlaybackRate > v) {
                setState(() => _splitVideoPlaybackRate = v);
                await _applySplitVideoPlaybackRate(v);
              }
            },
            itemBuilder: (_) {
              final current = context.read<MindMapProvider>().videoMaxRate;
              PopupMenuEntry<double> item(double v, String label) {
                final sel = (current - v).abs() < 0.01;
                return PopupMenuItem<double>(
                  value: v,
                  child: Row(children: [
                    Icon(
                        sel
                            ? Icons.check_circle_rounded
                            : Icons.circle_outlined,
                        size: 14,
                        color: sel ? const Color(0xFF6C63FF) : Colors.white38),
                    const SizedBox(width: 8),
                    Text(label,
                        style:
                            const TextStyle(color: Colors.white, fontSize: 13)),
                  ]),
                );
              }

              return [
                item(2.0, '最大 2x'),
                item(4.0, '最大 4x  (デフォルト)'),
                item(8.0, '最大 8x'),
                item(16.0, '最大 16x'),
              ];
            },
          ),
          const SizedBox(width: 4),
          Text(
            '${_splitVideoPlaybackRate.toStringAsFixed(2)}x',
            style: const TextStyle(
              color: Colors.white,
              fontSize: 12,
              fontWeight: FontWeight.w700,
              fontFeatures: [FontFeature.tabularFigures()],
            ),
          ),
          const SizedBox(width: 4),
          Expanded(
            child: SliderTheme(
              data: SliderTheme.of(context).copyWith(
                trackHeight: 3,
                thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 7),
                overlayShape: const RoundSliderOverlayShape(overlayRadius: 14),
                activeTrackColor: const Color(0xFF6C63FF),
                inactiveTrackColor: Colors.white24,
                thumbColor: const Color(0xFF6C63FF),
                overlayColor: const Color(0xFF6C63FF).withValues(alpha: 0.3),
              ),
              child: Slider(
                value: _splitVideoPlaybackRate.clamp(1.0, maxRate),
                min: 1.0,
                max: maxRate,
                // 0.1 刻みで divisions を計算 (= 1.0〜maxRate を 0.1 単位)
                divisions: ((maxRate - 1.0) * 10).round().clamp(10, 200),
                onChanged: (v) {
                  setState(() => _splitVideoPlaybackRate = v);
                  // 両パネル (= 右 + 左) に同じ速度を適用する。
                  // 片方しか開いていなくても safe (= null チェックされる)。
                  _applySplitVideoPlaybackRate(v);
                },
              ),
            ),
          ),
          // プリセット (= maxRate に応じて動的)
          for (final preset in sortedPresets)
            Padding(
              padding: const EdgeInsets.only(left: 4),
              child: InkWell(
                borderRadius: BorderRadius.circular(4),
                onTap: () {
                  setState(() => _splitVideoPlaybackRate = preset);
                  _applySplitVideoPlaybackRate(preset);
                },
                child: Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
                  decoration: BoxDecoration(
                    color: (_splitVideoPlaybackRate - preset).abs() < 0.01
                        ? const Color(0xFF6C63FF).withValues(alpha: 0.25)
                        : Colors.transparent,
                    borderRadius: BorderRadius.circular(4),
                    border: Border.all(
                      color: (_splitVideoPlaybackRate - preset).abs() < 0.01
                          ? const Color(0xFF6C63FF)
                          : Colors.white24,
                      width: 0.5,
                    ),
                  ),
                  child: Text(
                    '${preset.toStringAsFixed(preset == preset.truncateToDouble() ? 0 : 1)}x',
                    style: TextStyle(
                      color: (_splitVideoPlaybackRate - preset).abs() < 0.01
                          ? const Color(0xFF6C63FF)
                          : Colors.white70,
                      fontSize: 11,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
              ),
            ),
          // ── 動画を縦いっぱいに伸ばすトグル (= ユーザー要望) ──
          const SizedBox(width: 4),
          _splitVideoFillToggle(),
          // ── 折りたたみボタン (= バーを最小化) ──
          // ユーザー要望「再生速度バーは折りたたんで目立たない形にできる
          //   ようにして」 への対応。 タップで _splitVideoBarExpanded を
          //   false に戻して、 小さなアイコン表示に。
          const SizedBox(width: 4),
          InkWell(
            borderRadius: BorderRadius.circular(4),
            onTap: () => setState(() => _splitVideoBarExpanded = false),
            child: Container(
              padding: const EdgeInsets.all(3),
              child: const Icon(Icons.close_rounded,
                  color: Colors.white54, size: 16),
            ),
          ),
        ],
      ),
    );
  }

  /// JavaScript で <video> タグの再生速度を設定。
  /// 画面分割の WebView (Windows / iaw) 両方に対応。
  /// 指定 URL が「動画が含まれる可能性が高いページ」 かどうかを判定。
  /// 速度バー表示の条件として使用。
  ///
  /// ユーザー要望「Google検索閲覧するページに動画が含まれる時には再生
  ///   速度調整バーが出るようにして欲しい」 への対応で、 google.com /
  ///   twitter / x.com / 動画埋め込みが多い SNS も含める。 ヒットしても
  ///   ページに video タグがなければ速度バーの操作は空振り (= 害なし)、
  ///   ヒット漏れだとバーが出ないので、 広めに拾う方針。
  bool _isLikelyVideoUrl(String url) {
    return _isLikelyEmbeddedVideoUrl(url);
  }

  Future<void> _applySplitVideoPlaybackRate(double rate,
      {bool? leftPanel}) async {
    final js = webVideoRateJs(rate);
    try {
      // leftPanel == null → 両パネルへ、 true → 左のみ、 false → 右のみ
      // ユーザー要望「右画面分割した時だけ再生速度調整バーが出てくるの
      //   変だから、 左分割の際にも再生速度調整バーが出るようにして」
      //   に対応するため、 左パネルへも同じ JS を流すルートを追加。
      if (leftPanel == true || leftPanel == null) {
        if (Platform.isWindows && _splitLeftWinInitialized) {
          await _splitLeftWinController?.executeScript(js);
        } else if (_splitLeftIawController != null) {
          await _splitLeftIawController!.evaluateJavascript(source: js);
        }
      }
      if (leftPanel == false || leftPanel == null) {
        if (Platform.isWindows && _splitWinInitialized) {
          await _splitWinController?.executeScript(js);
        } else if (_splitIawController != null) {
          await _splitIawController!.evaluateJavascript(source: js);
        }
      }
    } catch (_) {}
  }

  /// 速度バー内の「動画を縦いっぱいに伸ばす」 トグルボタン (= ユーザー要望:
  /// 分割すると上下の領域が余ってもったいないので縦に伸ばして欲しい)。
  Widget _splitVideoFillToggle() {
    final on = _splitVideoFillMode;
    return Material(
      color: Colors.transparent,
      child: Tooltip(
        message: context.read<MindMapProvider>().t(
            on ? 'split.videoFillOff' : 'split.videoFillOn'),
        child: InkWell(
          borderRadius: BorderRadius.circular(20),
          onTap: _toggleSplitVideoFill,
          child: Container(
            padding: const EdgeInsets.all(5),
            decoration: BoxDecoration(
              color: on
                  ? const Color(0xFF6C63FF).withValues(alpha: 0.85)
                  : Colors.black.withValues(alpha: 0.55),
              borderRadius: BorderRadius.circular(20),
              border: Border.all(
                  color: on
                      ? const Color(0xFF6C63FF)
                      : Colors.white.withValues(alpha: 0.15)),
            ),
            child: Icon(
              on
                  ? Icons.close_fullscreen_rounded
                  : Icons.height_rounded,
              color: on ? Colors.white : Colors.white70,
              size: 16,
            ),
          ),
        ),
      ),
    );
  }

  /// 分割パネルの「動画を縦いっぱいに伸ばす」 モードを両パネルへ適用する
  /// (= ユーザー要望)。 [leftPanel] を渡すとその側だけに適用。
  Future<void> _applySplitVideoFill(bool on, {bool? leftPanel}) async {
    final js = _splitVideoFillJs(on);
    try {
      if (leftPanel == true || leftPanel == null) {
        if (Platform.isWindows && _splitLeftWinInitialized) {
          await _splitLeftWinController?.executeScript(js);
        } else if (_splitLeftIawController != null) {
          await _splitLeftIawController!.evaluateJavascript(source: js);
        }
      }
      if (leftPanel == false || leftPanel == null) {
        if (Platform.isWindows && _splitWinInitialized) {
          await _splitWinController?.executeScript(js);
        } else if (_splitIawController != null) {
          await _splitIawController!.evaluateJavascript(source: js);
        }
      }
    } catch (_) {}
  }

  /// 「縦いっぱい」 モードを起動時に復元する。
  Future<void> _loadSplitVideoFillMode() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final on = prefs.getBool('splitVideoFillMode') ?? false;
      if (on && mounted) setState(() => _splitVideoFillMode = true);
    } catch (_) {}
  }

  /// 「縦いっぱい」 モードのトグル + 永続化。
  Future<void> _toggleSplitVideoFill() async {
    final next = !_splitVideoFillMode;
    setState(() => _splitVideoFillMode = next);
    await _applySplitVideoFill(next);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool('splitVideoFillMode', next);
    } catch (_) {}
  }

  Future<void> _probeSplitVideoPresence({required bool leftPanel}) async {
    if (!mounted) return;
    if (leftPanel) {
      if (_splitLeftMode != 'web' || _splitLeftCurrentUrl.isEmpty) return;
    } else {
      if (_splitMode != 'web' || _splitCurrentUrl.isEmpty) return;
    }
    dynamic result;
    try {
      if (Platform.isWindows) {
        final ready =
            leftPanel ? _splitLeftWinInitialized : _splitWinInitialized;
        final ctrl = leftPanel ? _splitLeftWinController : _splitWinController;
        if (!ready || ctrl == null) return;
        result = await ctrl.executeScript(_webVideoPresenceJs());
      } else {
        final ctrl = leftPanel ? _splitLeftIawController : _splitIawController;
        if (ctrl == null) return;
        result = await ctrl.evaluateJavascript(source: _webVideoPresenceJs());
      }
    } catch (_) {
      return;
    }
    final hasVideo = _webJsTruthy(result);
    if (!mounted) return;
    setState(() {
      if (leftPanel) {
        _splitLeftHasVideo = hasVideo;
      } else {
        _splitHasVideo = hasVideo;
      }
    });
    // ページ遷移で注入済み CSS が消えるので、 動画を見つけたら再適用する
    // (= ユーザー要望の「縦いっぱい」 モードを維持)。
    if (hasVideo && _splitVideoFillMode) {
      unawaited(_applySplitVideoFill(true, leftPanel: leftPanel));
    }
  }

  void _scheduleSplitVideoProbe({required bool leftPanel}) {
    for (final ms in const [250, 1200, 3000]) {
      Future.delayed(Duration(milliseconds: ms), () {
        if (mounted) {
          _probeSplitVideoPresence(leftPanel: leftPanel);
        }
      });
    }
  }

  // ─── Build ───────────────────────────────────────────────────────────────

  @override
  Widget build(BuildContext context) {
    return Consumer<MindMapProvider>(builder: (context, provider, _) {
      // MCP / AI が作った物のあるページへ寄せる (= ユーザー要望)。
      _handleMcpFocus(provider);
      if (provider.pages.isEmpty) {
        return const Scaffold(
          backgroundColor: Color(0xFF0F0F1A),
          body: Center(child: CircularProgressIndicator()),
        );
      }
      final pageId = provider.currentPage.id;
      final ctrl = _ctrlFor(pageId);
      // 選択が空になったのに一括操作バーが残っていたら閉じる
      // (= ユーザー要望: 要素を削除したら範囲選択のボタンも同時に消える)。
      _dismissMultiSelectOverlayIfEmpty(provider);
      // ── 名前の編集中にページが切り替わったら、 編集を打ち切る
      //    (= ユーザー報告: 確定していない名前のまま別のページへ移ると、
      //     その名前が付いて回る)。 名前は始めたページへ書き戻す。 ──
      if (_editingMapName &&
          _mapNameEditPageId != null &&
          _mapNameEditPageId != pageId) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) _commitInlineMapNameEdit();
        });
      }

      return KeyboardListener(
        focusNode: _keyboardFocusNode,
        autofocus: true,
        onKeyEvent: (event) {
          if (!_isDesktop) return;
          if (_isPrimaryEditableTextFocused()) return;
          // Ctrl/Meta リリース検知: 複数選択された接続線のメニューを表示
          if (event is KeyUpEvent &&
              (event.logicalKey == LogicalKeyboardKey.controlLeft ||
                  event.logicalKey == LogicalKeyboardKey.controlRight ||
                  event.logicalKey == LogicalKeyboardKey.metaLeft ||
                  event.logicalKey == LogicalKeyboardKey.metaRight)) {
            // 他のCtrl/Metaがまだ押されていないか確認
            final stillPressed = HardwareKeyboard.instance.isControlPressed ||
                HardwareKeyboard.instance.isMetaPressed;
            if (!stillPressed) {
              // ── ノード複数選択 → 単品と同スタイルのフローティングオーバーレイ ──
              // (右上ボタン列廃止に伴い 1 個からこのメニューを出す)
              if (_rangeSelectedIds.isNotEmpty &&
                  _selectedConnections.isEmpty) {
                _showMultiNodeActionOverlay(context, provider, ctrl);
                return;
              }
              // ── 接続線複数選択 → 接続設定オーバーレイ ──
              if (_connOverlayPendingOnCtrlUp &&
                  _selectedConnections.isNotEmpty &&
                  _lastCtrlConnectionTapPos != null) {
                _connOverlayPendingOnCtrlUp = false;
                final isMulti = _connOverlayIsMulti;
                _connOverlayIsMulti = false;
                final pos = _lastCtrlConnectionTapPos!;
                if (isMulti) {
                  _showConnectionDeleteOverlay(
                      _selectedConnections.first, pos, provider,
                      forceMulti: true);
                } else {
                  _showConnectionDeleteOverlay(
                      _selectedConnections.first, pos, provider);
                }
              }
            }
            return;
          }
          if (event is KeyUpEvent) return;
          // 長押し対応: Repeatイベントも受理するが、リピートさせたい
          // キーだけ通す（ダイアログ開きなどはリピートさせない）
          if (event is KeyRepeatEvent) {
            final k = event.logicalKey;
            final repeatable = k == LogicalKeyboardKey.arrowLeft ||
                k == LogicalKeyboardKey.arrowRight ||
                k == LogicalKeyboardKey.arrowUp ||
                k == LogicalKeyboardKey.arrowDown ||
                k == LogicalKeyboardKey.backspace ||
                k == LogicalKeyboardKey.delete ||
                k == LogicalKeyboardKey.keyZ || // Undo連打
                k == LogicalKeyboardKey.keyY || // Redo連打（カスタムでYに設定した場合）
                k == LogicalKeyboardKey.equal ||
                k == LogicalKeyboardKey.minus ||
                k == LogicalKeyboardKey.numpadAdd ||
                k == LogicalKeyboardKey.numpadSubtract;
            if (!repeatable) return;
          }
          final isCtrl = HardwareKeyboard.instance.isControlPressed ||
              HardwareKeyboard.instance.isMetaPressed;
          final isShift = HardwareKeyboard.instance.isShiftPressed;
          final isAlt = HardwareKeyboard.instance.isAltPressed;

          if (isCtrl &&
              !isShift &&
              !isAlt &&
              event.logicalKey == LogicalKeyboardKey.keyV &&
              _shortcutCommandMatches('paste', 'Ctrl+V')) {
            _handlePaste(provider);
            return;
          }

          // ── Alt+← / Alt+→: 履歴ナビゲーション ──
          // 変更可能化 (= ユーザー要望) に伴い、 コマンド解決経由の
          // historyBack / historyForward へ移動した (この下の
          // _commandForKeyCombo → ディスパッチ)。

          // ── Enter: 連番オートフィル一括適用 ──
          // 「兄弟ノードに連番を一括適用しますか」 SnackBar が表示中の
          // 状態で Enter キーを押すと、 ボタン押下と同じ処理が走る。
          // 表示直後 300ms 以内の Enter は無視する (= タイトル保存時の
          // Enter が連鎖してきた誤発火を防ぐ)。
          if (event.logicalKey == LogicalKeyboardKey.enter &&
              !isCtrl &&
              !isShift &&
              !isAlt &&
              _pendingAutofillSuggestions != null &&
              _pendingAutofillSuggestions!.isNotEmpty) {
            final shownAt = _pendingAutofillShownAt;
            if (shownAt != null &&
                DateTime.now().difference(shownAt).inMilliseconds < 300) {
              return;
            }
            _applyPendingAutofill();
            return;
          }

          // Ctrl + "+"（または「=」キー） → 拡大
          // ユーザー要望: 「PDFビューワー上で Ctrl+/- を押してもマップの方の
          // 拡大率が変わってしまう、 ちゃんと PDF 側の拡大率が変わるように」。
          // ★ PDF パネルがアクティブなら PDF のズームレベルを変える ★
          // 左パネル → 右パネル → マップ拡大 の優先順位。
          if (isCtrl &&
              (event.logicalKey == LogicalKeyboardKey.equal ||
                  event.logicalKey == LogicalKeyboardKey.numpadAdd ||
                  event.logicalKey == LogicalKeyboardKey.add)) {
            // 左パネル PDF アクティブ?
            if (_splitLeftPanelHover && _splitLeftLocalPdfPath != null) {
              try {
                final cur = _splitLeftPdfController.zoomLevel;
                _splitLeftPdfController.zoomLevel = (cur + 0.05).clamp(1.0, 8.0);
              } catch (e) {
                debugPrint('左パネル PDF ズーム失敗: $e');
              }
              return;
            }
            // 右パネル PDF アクティブ?
            if (_splitPanelHover && _splitMode == 'pdf') {
              try {
                final cur = _splitPdfController.zoomLevel;
                _splitPdfController.zoomLevel = (cur + 0.05).clamp(1.0, 8.0);
              } catch (e) {
                debugPrint('右パネル PDF ズーム失敗: $e');
              }
              return;
            }
            // どちらでもなければマップ拡大
            _applyScale((_scalePercent + 10).clamp(50, 200));
            return;
          }
          // Ctrl + "-" → 縮小
          if (isCtrl &&
              (event.logicalKey == LogicalKeyboardKey.minus ||
                  event.logicalKey == LogicalKeyboardKey.numpadSubtract)) {
            // 左パネル PDF アクティブ?
            if (_splitLeftPanelHover && _splitLeftLocalPdfPath != null) {
              try {
                final cur = _splitLeftPdfController.zoomLevel;
                _splitLeftPdfController.zoomLevel = (cur - 0.05).clamp(1.0, 8.0);
              } catch (e) {
                debugPrint('左パネル PDF ズーム失敗: $e');
              }
              return;
            }
            // 右パネル PDF アクティブ?
            if (_splitPanelHover && _splitMode == 'pdf') {
              try {
                final cur = _splitPdfController.zoomLevel;
                _splitPdfController.zoomLevel = (cur - 0.05).clamp(1.0, 8.0);
              } catch (e) {
                debugPrint('右パネル PDF ズーム失敗: $e');
              }
              return;
            }
            // どちらでもなければマップ縮小
            _applyScale((_scalePercent - 10).clamp(50, 200));
            return;
          }
          // Ctrl + 0 → 100%にリセット
          if (isCtrl &&
              !isShift &&
              (event.logicalKey == LogicalKeyboardKey.digit0 ||
                  event.logicalKey == LogicalKeyboardKey.numpad0)) {
            _applyScale(100);
            return;
          }

          // ── Ctrl+E: 図形の挿入 (= ユーザー要望) ──
          // 以前は予定登録だったが「図形の挿入と被る」 ため、Ctrl+E は
          //   図形挿入に割り当てる。
          // 注: 予定登録は以前ここで Ctrl+Shift+E に割り当てていたが、
          //   Ctrl+Shift+E は「マップ一覧 (ドロワー) を開く」 コマンド
          //   (openDrawer) のデフォルトキーと衝突するため割り当てを撤去した
          //   (= ユーザー要望)。予定登録はメニュー / ボタンから開ける。
          if (isCtrl &&
              !isShift &&
              !isAlt &&
              event.logicalKey == LogicalKeyboardKey.keyE &&
              _shortcutCommandMatches('insertMapShape', 'Ctrl+E')) {
            _showMapShapePicker();
            return;
          }

          // ── Ctrl+Shift+\\ / Ctrl+Shift+^: 画面分割 → 全画面表示 ──
          // ユーザー要望: 「画面分割したものを全画面表示にするショートカット
          // キーを付けて欲しい」。
          // - Ctrl+Shift+\\ → 右画面分割パネルを全画面表示に
          // - Ctrl+Shift+^ → 左画面分割パネルを全画面表示に
          // 元のパネルは閉じる (= 全画面に切替)。
          // ★ 変更可能化 (= ユーザー要望): 既定キーのままの時だけこの直接
          //   ハンドラで拾う (JIS の ^ はキーコードが揺れるため、 既定キー
          //   ではコンボ解決に頼らずここで確実に判定する)。 付け替えた時は
          //   下のコマンド解決 (splitRight/LeftFullscreen) が動く。
          if (isCtrl && isShift) {
            final isBackslash =
                event.logicalKey == LogicalKeyboardKey.backslash;
            final isShiftCaret = event.logicalKey == LogicalKeyboardKey.caret ||
                event.physicalKey == PhysicalKeyboardKey.equal ||
                (event.character ?? '') == '^';
            // Ctrl+Shift+\\ → 右パネルを全画面化
            if (isBackslash &&
                _shortcutCommandMatches(
                    'splitRightFullscreen', 'Ctrl+Shift+\\') &&
                _splitOpen &&
                _splitCurrentUrl.isNotEmpty) {
              final url = _splitCurrentUrl;
              final nodeId = _splitOriginNodeId;
              _setSplitOpen(false);
              _showInAppViewer(context, url, nodeId: nodeId);
              return;
            }
            // Ctrl+Shift+^ → 左パネルを全画面化
            if (isShiftCaret &&
                _shortcutCommandMatches(
                    'splitLeftFullscreen', 'Ctrl+Shift+^') &&
                _splitLeftOpen &&
                (_splitLeftLocalPdfPath != null ||
                    _splitLeftCurrentUrl.isNotEmpty)) {
              final url = _splitLeftLocalPdfPath ?? _splitLeftCurrentUrl;
              _closeSplitLeftPanel();
              _showInAppViewer(context, url);
              return;
            }
          }

          // ── Ctrl+^ で左画面分割トグル ──
          // ユーザー要望: 「ctrl+^ で左画面分割が呼び出されるようにしろ」。
          //
          // 日本語キーボードの `^` キーは色々なキーコードで来る可能性が
          // あるため、 複数判定で確実に拾う:
          //   - LogicalKeyboardKey.caret (= ASCII 0x5e の `^`)
          //   - PhysicalKeyboardKey.equal (= 米国配列の `=` の位置 = 日本語の `^`)
          //   - event.character == '^' (= 文字としての `^`)
          //   - 英語配列の Ctrl + Shift + 6 (= ^ の入力)
          if (isCtrl) {
            final logicalCaret = event.logicalKey == LogicalKeyboardKey.caret;
            final physicalCaret =
                event.physicalKey == PhysicalKeyboardKey.equal;
            final charCaret = (event.character ?? '') == '^';
            final isShift6 = isShift &&
                (event.logicalKey == LogicalKeyboardKey.digit6 ||
                    event.logicalKey == LogicalKeyboardKey.numpad6);
            if ((logicalCaret || physicalCaret || charCaret || isShift6) &&
                _shortcutCommandMatches('toggleSplitLeftScreen', 'Ctrl+^')) {
              _toggleSplitLeftPanel();
              return;
            }
            // バックスラッシュもダブルチェック (= commandId 経由が
            // 動かないケースの保険)
            if (event.logicalKey == LogicalKeyboardKey.backslash &&
                !isShift &&
                _shortcutCommandMatches('toggleSplitScreen', 'Ctrl+\\')) {
              _toggleSplitPanel();
              return;
            }
          }

          // Escape: 検索パネルが開いていれば先に閉じる
          if (event.logicalKey == LogicalKeyboardKey.escape && _searchVisible) {
            setState(() {
              _searchVisible = false;
              _searchResultIds = [];
            });
            _keyboardFocusNode.requestFocus();
            return;
          }

          // ── Escape: 画面分割パネル (PDF/WebView) を閉じる ──
          // ユーザー要望: 「画面分割の PDF ビューワーがアクティブになっている
          // 状態で Esc キーを入れたらビューワーが閉じる」。
          //
          // 優先順位:
          // 1. 左パネルにマウスが乗っている → 左パネルを閉じる
          // 2. 右パネルにマウスが乗っている → 右パネルを閉じる
          // 3. (両方開いてる場合) どちらにもホバーしてないなら何もしない
          //    (= マップ操作中の Esc は通常の選択解除に使うため)
          if (event.logicalKey == LogicalKeyboardKey.escape) {
            if (_splitLeftOpen && _splitLeftPanelHover) {
              _closeSplitLeftPanel();
              _keyboardFocusNode.requestFocus();
              return;
            }
            if (_splitOpen && _splitPanelHover) {
              setState(() {
                _setSplitOpen(false);
              });
              _keyboardFocusNode.requestFocus();
              return;
            }
          }

          // Escape: 選択・モードを解除
          if (event.logicalKey == LogicalKeyboardKey.escape) {
            // ── 切り取り (Ctrl+X) 待ちを最優先で解除 (= Windows と同じく Esc で
            //    切り取りをキャンセル) ──
            if (_cutNodeIds.isNotEmpty) {
              setState(() {
                _cutNodeIds.clear();
                _cutSourcePageIndex = null;
              });
              return;
            }
            // ── 図形挿入モード / 図形選択中なら最優先で解除 ──
            // ユーザー要望「挿入モードを Esc で抜けられるように」。 この Esc
            //   ブロックは最後に return するため、 ここで図形モードを処理しないと
            //   cancelMode (コマンド側) まで到達せず Esc が効かなかった。
            if (_drawingDecorationKind != null) {
              _exitShapeInsertMode();
              return;
            }
            if (_selectedDecorationId != null) {
              setState(() => _selectedDecorationId = null);
              return;
            }
            // ヘッダー並び替えモード中なら最優先で解除
            if (_reorderHeaderMode) {
              _exitHeaderReorderMode();
              return;
            }
            // カレンダーモード中なら最優先でマップに戻る
            if (_calendarMode) {
              setState(() => _calendarMode = false);
              _refreshFloatingOverlays();
              return;
            }
            // 裁断モード中なら裁断モードを終了
            if (_cutMode) {
              setState(() {
                _cutMode = false;
                _cutStartPoint = null;
                _cutPreviewEnd = null;
                _cutFadingLine = null;
              });
              _cutFadeTimer?.cancel();
              _showLockToast(provider.t('toast.cutModeOff'));
              return;
            }
            if (_settingRefMode) {
              setState(() => _settingRefMode = false);
              return;
            }
            if (_rangeSelectMode) {
              setState(() {
                _rangeSelectMode = false;
                _rangeSelectedIds.clear();
                _rangeSelectedDecorationIds.clear();
                _rangeStart = null;
                _rangeEnd = null;
              });
            } else if (_moveModeNodeId != null ||
                _actionNodeId != null ||
                _selectedConnections.isNotEmpty) {
              _resetInteractionState();
            }
            // 何も選択されていない状態では何もしない
            return;
          }

          // Ctrl+F: 検索パネルを開く (変更可能化 = 既定キーのままの時だけ
          // ここで拾う。 付け替えた時はコマンド解決 'search' が動く)。
          if (isCtrl &&
              !isShift &&
              !isAlt &&
              event.logicalKey == LogicalKeyboardKey.keyF &&
              _shortcutCommandMatches('search', 'Ctrl+F')) {
            setState(() {
              _searchVisible = true;
              _searchReplaceExpanded = false;
              _searchQuery = '';
              _searchCtrl.clear();
              _replaceCtrl.clear();
              _searchResultIds = [];
              _searchResultIndex = 0;
            });
            WidgetsBinding.instance
                .addPostFrameCallback((_) => _searchFocusNode.requestFocus());
            return;
          }

          // 検索パネル表示中はキャンバスショートカットを無効化
          if (_searchVisible) return;

          // Ctrl キー単独押し → ノード選択中なら範囲選択モードへ切り替え
          if ((event.logicalKey == LogicalKeyboardKey.controlLeft ||
                  event.logicalKey == LogicalKeyboardKey.controlRight) &&
              !isShift &&
              _actionNodeId != null &&
              !_rangeSelectMode) {
            final selId = _actionNodeId!;
            _removeOverlay();
            setState(() {
              _rangeSelectMode = true;
              _rangeSelectedIds.clear();
              _rangeSelectedDecorationIds.clear();
              _rangeSelectedIds.add(selId);
            });
            return;
          }

          // ── カスタムキーバインドを含めてコマンドを解決 ──────────────────────
          final keyCombo = _getPressedKeyCombo(event);
          final commandId = _commandForKeyCombo(keyCombo);

          // ────────────────────────────────────────────────────────────────────
          // コマンド実行
          // ────────────────────────────────────────────────────────────────────
          if (commandId == 'undo') {
            // カレンダー表示中はカレンダー用のUndoを優先
            if (_calendarMode && provider.canUndoCalendar) {
              provider.undoCalendarEvents();
            } else if (provider.canUndoDeletedPage) {
              // ページ削除直後は、AIキャンセルやページ内Undoより復元を優先。
              _undoDeletedPageIfAvailable(provider);
            } else if (provider.aiInProgress &&
                !provider.hasUserActionsAfterAiStart) {
              // AI動作中で、AI開始後にユーザー操作がない場合のみ AI をキャンセル。
              // ユーザー操作がある場合はそれらを先に undo() で取り消すため、
              // 下の else 分岐に流す（AI はバックグラウンドで動作継続）。
              provider.cancelAi();
              final m = ScaffoldMessenger.of(context);
              m.hideCurrentSnackBar();
              _appSnackM(
                  m,
                  SnackBar(
                    content: Text(provider.t('ai.cancelled')),
                    duration: const Duration(seconds: 2),
                    backgroundColor: const Color(0xFF9E9E9E),
                  ));
            } else {
              provider.undo();
            }
          } else if (commandId == 'redo') {
            // 旧 redoAlternate (Ctrl+Shift+Z) は廃止 (= ユーザー要望:
            // Ctrl+Y に同じ機能があるなら要らない)。
            provider.redo();
          } else if (commandId == 'historyBack') {
            // 変更可能化 (= ユーザー要望)。 分割パネルの履歴を優先するのは
            // 旧固定キー (Alt+←) と同じ。
            if (_splitOpen && _splitHistory.isNotEmpty) {
              _splitNavigateBack();
            } else {
              _navigateBack();
            }
          } else if (commandId == 'historyForward') {
            if (_splitOpen && _splitForwardHistory.isNotEmpty) {
              _splitNavigateForward();
            } else {
              _navigateForward();
            }
          } else if (commandId == 'swapSplitPanels') {
            _swapSplitPanels();
          } else if (commandId == 'splitRightFullscreen') {
            // 右分割パネルを全画面表示に (元パネルは閉じる)。
            if (_splitOpen && _splitCurrentUrl.isNotEmpty) {
              final url = _splitCurrentUrl;
              final nodeId = _splitOriginNodeId;
              _setSplitOpen(false);
              _showInAppViewer(context, url, nodeId: nodeId);
            }
          } else if (commandId == 'splitLeftFullscreen') {
            if (_splitLeftOpen &&
                (_splitLeftLocalPdfPath != null ||
                    _splitLeftCurrentUrl.isNotEmpty)) {
              final url = _splitLeftLocalPdfPath ?? _splitLeftCurrentUrl;
              _closeSplitLeftPanel();
              _showInAppViewer(context, url);
            }
          } else if (commandId == 'search') {
            setState(() {
              _searchVisible = true;
              _searchReplaceExpanded = false;
              _searchQuery = '';
              _searchCtrl.clear();
              _replaceCtrl.clear();
              _searchResultIds = [];
              _searchResultIndex = 0;
            });
            WidgetsBinding.instance
                .addPostFrameCallback((_) => _searchFocusNode.requestFocus());
          } else if (commandId == 'syncDialog') {
            _showSyncDialog(context, provider);
          } else if (commandId == 'autoSyncPage') {
            _autoSyncCurrentPage(context, provider);
          } else if (commandId == 'newPage') {
            _addPageDialog(context, provider);
          } else if (commandId == 'deletePage') {
            _confirmDeletePage(context, provider);
          } else if (commandId == 'lockH') {
            final newLockH = !_lockH;
            setState(() => _lockH = newLockH);
            _showLockToast(
                provider.t(newLockH ? 'toast.lockHOn' : 'toast.lockHOff'));
          } else if (commandId == 'lockV') {
            final newLockV = !_lockV;
            setState(() => _lockV = newLockV);
            _showLockToast(
                provider.t(newLockV ? 'toast.lockVOn' : 'toast.lockVOff'));
          } else if (commandId == 'copy') {
            if (_rangeSelectedIds.isNotEmpty) {
              _handleCopy(provider);
            } else if (_actionNodeId != null) {
              _handleSingleNodeCopy(_actionNodeId!, provider);
            }
          } else if (commandId == 'cut') {
            _handleCut(provider);
          } else if (commandId == 'paste') {
            _handlePaste(provider);
          } else if (commandId == 'newNode') {
            // Ctrl+Shift+N: 新規ノードを作ってそのまま名前を打ち始める。
            //
            // ★ 全体キー処理 (`_handleMainGlobalArrowKey`) と同じ関数を呼ぶ
            //   (= ユーザー報告: 初回だけ 2 個別々の場所に生成される)。
            //   以前はこちらだけ「画面中央」 に作っていたため、 2 経路が
            //   両方走った初回だけ離れた場所に 2 個できていた。 関数側に
            //   二重処理よけがあるので、 どちらが先に来ても 1 個で済む。
            _createNodeAndStartEditing(provider);
          } else if (commandId == 'group') {
            // グループ化/グループ解除トグル
            if (_rangeSelectedIds.isNotEmpty) {
              String? matchedGroup;
              for (final e in provider.namedGroups.entries) {
                final validIds = e.value
                    .where((id) => provider.nodes.containsKey(id))
                    .toSet();
                if (validIds.isNotEmpty &&
                    validIds.length == _rangeSelectedIds.length &&
                    validIds.every((id) => _rangeSelectedIds.contains(id))) {
                  matchedGroup = e.key;
                  break;
                }
              }
              if (matchedGroup != null) {
                provider.removeNamedGroup(matchedGroup);
                if (mounted) {
                  final name = matchedGroup.isEmpty
                      ? provider.t('groupList.unnamed')
                      : matchedGroup;
                  final msg = provider
                      .t('groupCreate.removed')
                      .replaceAll('{name}', name);
                  _appSnack(
                      context,
                      SnackBar(
                        content: Text(msg),
                        backgroundColor: Colors.redAccent,
                        duration: const Duration(seconds: 2),
                      ));
                }
              } else {
                _showNameGroupDialog(context, provider);
              }
            }
          } else if (commandId == 'makeShortcut') {
            // ボタンを一発で呼び出すショートカットを作る (= ユーザー要望)。
            _showMakeShortcutDialog();
          } else if (commandId == 'selectAll') {
            _removeOverlay();
            _selectAllMapElements(provider);
          } else if (commandId == 'openDrawer') {
            if (_scaffoldKey.currentState?.isDrawerOpen == true) {
              _scaffoldKey.currentState?.closeDrawer();
            } else {
              setState(() => _drawerView = 'maps');
              _scaffoldKey.currentState?.openDrawer();
            }
          } else if (commandId == 'openTimeline') {
            // ── ToDo ドロワーを開く (タイムラインは廃止 = ユーザー要望) ──
            setState(() {
              _drawerView = 'todo';
            });
            if (_scaffoldKey.currentState?.isDrawerOpen != true) {
              _scaffoldKey.currentState?.openDrawer();
            }
          } else if (commandId == 'newFolder') {
            _addFolderDialog(context, provider);
          } else if (commandId == 'cloudUpload') {
            // ── 連打ガード: 同期中 (アップロード/ダウンロード中) は無視 ──
            // (= ユーザー要望: Ctrl+S 連打で最初の処理が終わるまで無視)
            if (provider.isUploading || provider.isDownloading) {
              _appSnack(
                  context,
                  SnackBar(
                      content: Text(provider.t('sync.inProgress')),
                      duration: Duration(seconds: 1)));
            } else if (_calendarMode) {
              // カレンダーモード中: カレンダーイベントを Firebase (+Google) に保存
              _uploadCalendarToCloud(provider);
            } else {
              // = ユーザー要望: 名前が未設定 (既定名) なら、 上げる前に名前を求める。
              _ensurePageNamed(context, provider, () {
                // オフライン動画 (= 端末 DL 済みでまだクラウドに上げていない)
                // を含むなら、URL のみ / 動画データも含めて上げるをユーザーに
                // 選ばせる。動画ファイルは MB 単位で重く、無料枠の Firebase
                // Storage を使い切る恐れもあるため、明示的な選択肢を提示。
                final hasOfflineVideo =
                    provider.currentPage.nodes.values.any((n) {
                  final url = (n.youtubeUrl ?? '').trim();
                  if (url.isEmpty) return false;
                  if (url.startsWith('http://') || url.startsWith('https://')) {
                    return false;
                  }
                  return (n.videoStorageUrl ?? '').isEmpty;
                });
                if (hasOfflineVideo) {
                  _askVideoUploadModeAndSync(context, provider);
                } else {
                  // = ユーザー要望: 差分だけアップロード (変更が無ければスキップ)
                  _diffUploadCurrentPage(provider);
                }
              });
            }
          } else if (commandId == 'cloudDownload') {
            // ── 連打ガード: 同期中 (アップロード/ダウンロード中) は無視 ──
            // (= ユーザー要望: Ctrl+D 連打で最初の処理が終わるまで無視)
            if (provider.isDownloading) {
              _showCloudDownloadDetailsDialog(context, provider);
            } else if (provider.isUploading) {
              _appSnack(
                  context,
                  SnackBar(
                      content: Text(provider.t('sync.inProgress')),
                      duration: Duration(seconds: 1)));
            } else if (_calendarMode) {
              // カレンダーモード中: Firebase (+Google) からカレンダーイベント取得
              _downloadCalendarFromCloud(provider);
            } else if (_rangeSelectedIds.isNotEmpty) {
              // リリース版では YouTube 動画の端末保存を無効化しているため、
              // Ctrl+D は常にクラウドからのマップダウンロードとして扱う。
              _showCloudDownloadDialog(context, provider);
            } else {
              // = ユーザー要望: 差分だけダウンロード (クラウドが新しい時だけ取得)
              _diffDownloadCurrentPage(provider);
            }
          } else if (commandId == 'delete') {
            if (_rangeSelectedDecorationIds.isNotEmpty) {
              // 範囲選択で捕捉した図形を一括削除 (ノードも併せて削除)
              for (final id in _rangeSelectedDecorationIds.toList()) {
                provider.removeMapDecoration(id);
              }
              setState(() => _rangeSelectedDecorationIds.clear());
              if (_rangeSelectedIds.isNotEmpty) {
                // ノードの削除は確認の後、 そちらで選択モードも終わりにする。
                _handleDeleteKey(context, provider);
              } else {
                // ★ 図形だけを消した時も選択モードを終わりにする
                //   (= ユーザー要望: 削除したら範囲選択モードも解除)。
                //   以前はここだけモードが残り、 ヘッダーが「範囲を選択」 の
                //   ままになっていた。
                _removeOverlay();
                setState(() {
                  _rangeSelectMode = false;
                  _rangeStart = null;
                  _rangeEnd = null;
                });
              }
            } else if (_selectedDecorationId != null) {
              _deleteSelectedDecoration();
            } else {
              _handleDeleteKey(context, provider);
            }
          } else if (commandId == 'cancelMode') {
            // 図形挿入モード中 / 図形選択中なら最優先で解除
            if (_drawingDecorationKind != null) {
              _exitShapeInsertMode();
            } else if (_selectedDecorationId != null) {
              setState(() => _selectedDecorationId = null);
            }
            // カレンダーモード中なら最優先でカレンダーを抜けてマップに戻る
            else if (_calendarMode) {
              setState(() => _calendarMode = false);
              _refreshFloatingOverlays();
            }
            // 裁断モード中なら裁断モードを終了
            else if (_cutMode) {
              setState(() {
                _cutMode = false;
                _cutStartPoint = null;
                _cutPreviewEnd = null;
                _cutFadingLine = null;
              });
              _cutFadeTimer?.cancel();
              _showLockToast(provider.t('toast.cutModeOff'));
            } else if (_settingRefMode) {
              setState(() => _settingRefMode = false);
            } else if (_rangeSelectMode) {
              setState(() {
                _rangeSelectMode = false;
                _rangeSelectedIds.clear();
                _rangeSelectedDecorationIds.clear();
                _rangeStart = null;
                _rangeEnd = null;
              });
            } else if (_moveModeNodeId != null ||
                _actionNodeId != null ||
                _selectedConnections.isNotEmpty) {
              _resetInteractionState();
            }
          } else if (commandId == 'editTitle') {
            final selId = _nodeIdForDirectEdit(provider);
            if (selId != null) {
              final node = provider.nodes[selId];
              if (node != null) {
                _startInlineTitleEdit(context, node);
              }
            }
          } else if (commandId == 'quickFlashcard') {
            // 素早く文字を入力してフラッシュカード登録 (= ユーザー要望)。
            //   ノードを選択中 (= 押しながら) なら、 そのタイトルを表面に入れた
            //   状態で開く (= ユーザー要望)。
            final fcId = _actionNodeId ?? provider.selectedNodeId;
            final fcTitle =
                fcId != null ? (provider.nodes[fcId]?.title.trim() ?? '') : '';
            _showQuickFlashcardDialog(initialFront: fcTitle);
          } else if (commandId == 'snapToggle') {
            // 配置候補 (スナップ) のON/OFF。
            // 旧来 Ctrl+J に直接バインドしていたが、 ユーザー要望により
            // Ctrl+J は「動作設定」 を開くショートカットに変更した。
            // 本ケースは「カスタムキー割り当て」 でユーザーが snapToggle
            // に別キーを再割当した時のためだけに残してある。
            provider.setSnapEnabled(!provider.snapEnabled);
            _showLockToast(provider
                .t(provider.snapEnabled ? 'toast.snapOn' : 'toast.snapOff'));
          } else if (commandId == 'openBehaviorSettings') {
            // Ctrl+J: 動作設定セクションを開いた状態で設定シートを表示。
            _openBehaviorSettings();
          } else if (commandId == 'setRef') {
            // Ctrl+B: 基準位置の設定モードに入る
            setState(() => _settingRefMode = true);
            _showLockToast(provider.t('toast.refSet'));
          } else if (commandId == 'goRef') {
            // Ctrl+Shift+B: 基準位置に移動（未設定ならルートに移動）
            _centerOnRoot();
            _showLockToast(provider.t('toast.refGo'));
          } else if (commandId == 'customizeHeader') {
            // Ctrl+H: ヘッダーカスタマイズ画面を開く
            _showHeaderCustomizeSheet(context, provider);
          } else if (commandId == 'autoLayout') {
            // Ctrl+Shift+A: 基準位置を中心に自動整列
            provider.autoLayoutTree(referencePos: _currentRefPos());
            _centerOnRoot();
          } else if (commandId == 'openSettings') {
            // Space: 設定画面をトグル開閉する (共通処理へ委譲)。
            _toggleSettingsSheetFromShortcut(provider);
          } else if (commandId == 'toggleCalendar') {
            // Ctrl+Shift+C: カレンダー表示の切替
            setState(() => _calendarMode = !_calendarMode);
            _refreshFloatingOverlays();
          } else if (commandId == 'newEvent') {
            // Ctrl+Alt+N: 今日のイベント新規作成（カレンダーモード中のみ）
            if (_calendarMode) {
              final today = DateTime.now();
              final key = _dateKey(today);
              final now = TimeOfDay.now();
              final startStr =
                  '${now.hour.toString().padLeft(2, '0')}:${(now.minute ~/ 15 * 15).toString().padLeft(2, '0')}';
              final endHour = (now.hour + 1).clamp(0, 23);
              final endStr =
                  '${endHour.toString().padLeft(2, '0')}:${(now.minute ~/ 15 * 15).toString().padLeft(2, '0')}';
              _editCalendarEventDialog(
                  context,
                  provider,
                  key,
                  CalendarEvent(
                    id: '',
                    title: '',
                    startTime: startStr,
                    endTime: endStr,
                  ));
            }
          } else if (commandId == 'toggleTheme') {
            // Ctrl+Shift+L: ダーク/ライトモードの切替
            provider.setDarkMode(!provider.isDarkMode);
          } else if (commandId == 'openYoutube') {
            // Ctrl+U: YouTube ブラウザを「ホーム画面」 で開く。
            // ユーザー要望「Ctrl+U で開くと最後に見た埋め込み動画に飛んで
            //   しまい新しい動画が見られない。 ちゃんと YouTube のホームに
            //   飛ぶようにして」 への対応。 forceHome:true で保存済み URL を
            //   無視 (+ クリア) してホームへ直行する。
            _openYoutubeBrowser(context, provider, forceHome: true);
          } else if (commandId == 'openSoundCloud') {
            // ボタンと同じく「サイト直行」 に統一 (= ユーザー要望)。
            _openSoundCloudSite(context, provider);
          } else if (commandId == 'openSpotify') {
            _openSpotifySite(context, provider);
          } else if (commandId == 'insertMapShape') {
            // 図形挿入ピッカーを開く (ユーザー割り当てキー)。
            _showMapShapePicker();
          } else if (commandId == 'googleSearch') {
            // Ctrl+Shift+F: Google 検索 + メモダイアログを開く。
            // ユーザー要望: 「ノードから検索を押して立ち上がる google 検索は
            // 全画面ではなく、 小さいダイアログ」 → compactMode: true で開く。
            _openGoogleSearchDialog(context, provider, compactMode: true);
          } else if (commandId == 'customPage1' ||
              commandId == 'customPage2' ||
              commandId == 'customPage3' ||
              commandId == 'customPage4' ||
              commandId == 'customPage5') {
            // お気に入りページ スロット 1〜5。 SharedPreferences の
            // ブックマーク一覧 (上から N 番目) に対応する URL を WebView で開く。
            // 未登録 (= まだそのスロットに何も保存されていない) なら、
            // 「Google 検索でブックマークを追加してください」 を促す。
            // commandId は分岐条件 (== 'customPage1' 等) を通過した時点で
            // 確実に non-null だが、 Dart の型推論で String? のままなので
            // null assertion (!) で確実に String に narrow する。
            final slotIdx =
                int.parse(commandId!.substring('customPage'.length)) - 1;
            _openCustomPageSlot(context, provider, slotIdx);
          } else if (commandId != null && commandId.startsWith('bookmark:')) {
            // 動的ブックマークボタン: 保存された URL を内蔵 WebView で開く。
            _openBookmarkUrl(context, provider, commandId);
          } else if (commandId == 'openShortcuts') {
            // Ctrl+I: ショートカット一覧ダイアログ
            _openShortcutsList(context);
          } else if (commandId == 'openCalculator') {
            // Ctrl+M: 計算機は関数電卓に統一 (= ユーザー要望: UI が 2 種類
            // あって困惑する)。 既に開いていればトグルで閉じる。
            if (_calculatorOverlay != null) {
              _calculatorOverlay?.remove();
              _calculatorOverlay = null;
            } else if (_sciCalcOverlay != null) {
              _sciCalcOverlay?.remove();
              _sciCalcOverlay = null;
              if (mounted) _keyboardFocusNode.requestFocus();
            } else {
              _showScientificCalculatorDialog(context, provider);
            }
          } else if (commandId == 'openScientificCalc') {
            // Ctrl+Shift+M: 高度な関数電卓を開閉トグル
            if (_sciCalcOverlay != null) {
              _sciCalcOverlay?.remove();
              _sciCalcOverlay = null;
            } else {
              _showScientificCalculatorDialog(context, provider);
            }
          } else if (commandId == 'openStopwatch') {
            // Ctrl+T: ストップウォッチフローティングパネルをトグル（開閉）
            if (_stopwatchOverlay != null) {
              _stopwatchOverlay?.remove();
              _stopwatchOverlay = null;
            } else {
              _showStopwatchDialog(context, provider);
            }
          } else if (commandId == 'openPomodoro') {
            // Ctrl+P: ポモドーロタイマーフローティングパネルをトグル（開閉）
            if (_pomodoroOverlay != null) {
              _pomodoroOverlay?.remove();
              _pomodoroOverlay = null;
            } else {
              _showPomodoroDialog(context, provider);
            }
          } else if (commandId == 'openWeather') {
            // ── マインドマップ以外のページでは Ctrl+W は「天気」 ではなく、
            //    開いている画面分割パネル/ビューアを閉じる動作に充てる
            //    (= ユーザー要望: ブラウザのタブを閉じる感覚) ──
            if (provider.currentPage.pageType != 'normal') {
              if (_splitOpen || _splitLeftOpen) {
                _setSplitOpen(false);
              }
              // パネルが開いていなければ何もしない (天気は開かない)。
            } else if (_weatherOverlay != null) {
              // Ctrl+W: 天気予報フローティングパネルをトグル（開閉）
              _weatherOverlay?.remove();
              _weatherOverlay = null;
            } else {
              _showWeatherDialog(context, provider);
            }
          } else if (commandId == 'createTable') {
            // Ctrl+Shift+R: PowerPoint 風グリッドで行列数を選んで表ノードを生成
            _showCreateTableDialog(context, provider);
          } else if (commandId == 'createFromFolder') {
            // OS のフォルダ選択ダイアログ → 中身を階層化してマインドマップ化
            _createMapFromFolder(context, provider);
          } else if (commandId == 'toggleSplitScreen') {
            // Ctrl+\\: 画面分割パネル (右) の開閉
            _toggleSplitPanel();
          } else if (commandId == 'toggleSplitLeftScreen') {
            // Ctrl+^: 画面分割パネル (左) の開閉
            // ユーザー要望: 「ctrl+\\で右画面分割、 ctrl+^で左画面分割」。
            _toggleSplitLeftPanel();
          } else if (commandId == 'containerize') {
            // Ctrl+G: 文脈に応じて 2 つの動作:
            //   1) drawer が開いていて複数マップ選択中
            //      → 選択マップを新規サブフォルダーに格納 (従来どおり)
            //   2) それ以外 (通常)
            //      → 複数ファイルを選んで 1 つの zip フォルダーにまとめる
            //        (ユーザー要望で「ノードを格納」 から差し替え。 ノードの
            //         グループ化は Ctrl+Shift+G の `group` で従来どおり可能)
            if (_drawerMultiSelectActive) {
              _groupSelectedDrawerPagesIntoFolder(context, provider);
            } else {
              _createZipFolderFromFiles(context, provider);
            }
          } else if (commandId == 'addChildren') {
            // Ctrl+Shift+A: 即時で固定数の子ノードを生成 (ダイアログ無し)。
            //
            // 個数は `provider.quickAddChildrenCount` (既定 5、設定画面で変更可)。
            // 生成対象:
            //   - 範囲選択中なら 全ての選択ノードに対してそれぞれ count 個生成
            //     (= 一気に並列構造を作れる)
            //   - 単一ノード選択中ならそのノードに対して count 個
            //   - 何も選択していなければ案内トースト
            //
            // 個別の個数指定が欲しいときは引き続き右クリックメニュー
            // 「子要素を複数追加」(`_showAddChildrenDialog`) を使える。
            final parentIds = <String>[];
            if (_rangeSelectedIds.isNotEmpty) {
              parentIds.addAll(_rangeSelectedIds);
            } else if (_actionNodeId != null) {
              parentIds.add(_actionNodeId!);
            }
            if (parentIds.isEmpty) {
              _showLockToast(provider.t('toast.needNodeSelection'));
            } else {
              final count = provider.quickAddChildrenCount;
              final newIds = parentIds.length == 1
                  // 単一: skipUndo なしでそのまま (Undo 1 回ぶん積まれる)
                  ? provider.addChildrenWithCount(parentIds.first, count)
                  // 複数: 一括メソッドで Undo を 1 回にまとめる
                  : provider.addChildrenToMultipleParents(parentIds, count);
              if (newIds.isNotEmpty) {
                // 生成された子が操作バーで隠れないよう、 親の選択は外す
                //   (= ユーザー報告: 追加直後に操作バーが子ノードに重なる)。
                //   最初の子を選び直すので、 続けて編集する流れは変わらない。
                setState(() {
                  _rangeSelectedIds.clear();
                  _actionNodeId = null;
                });
                // 最初に生成された子を選択 (連続編集の起点に)
                provider.selectNode(newIds.first);
              }
            }
          } else if (commandId == 'collapseChildren') {
            // Ctrl+Q: 子ノードを折りたたむ (= 格納する) / 展開する。
            // - 単一ノード選択中: そのノードを toggle
            // - 範囲選択中: 選択された各ノードのうち子孫を持つもののみ
            //   一括で同じ状態 (折りたたみ or 展開) に揃える
            //     先頭ノードの現在状態を反転した状態を目標にする。
            //   1 つでも子孫を持つノードがあれば適用、無ければ案内。
            // 既に collapsed / 子孫無しの状態でも安全に no-op になるように
            // provider.toggleNodeCollapsed が内部で判定する設計に依拠。
            final ids = <String>[];
            if (_rangeSelectedIds.isNotEmpty) {
              ids.addAll(_rangeSelectedIds);
            } else if (_actionNodeId != null) {
              ids.add(_actionNodeId!);
            }
            if (ids.isEmpty) {
              _showLockToast(provider.t('toast.needNodeSelection'));
            } else {
              // 子孫を持つノードだけを対象にする (葉ノードは無視)
              final targets = ids
                  .where((id) => provider.getDescendants(id).isNotEmpty)
                  .toList();
              if (targets.isEmpty) {
                _showLockToast(provider.t('toast.collapseNoChildren'));
              } else if (targets.length == 1) {
                // 単一: そのまま toggle (collapsed フラグが反転)
                provider.toggleNodeCollapsed(targets.first);
              } else {
                // 複数: 先頭ノードの「次の状態」に他のノードも揃える
                // (混在状態だと挙動が直感に反するため)
                final firstNode = provider.nodes[targets.first];
                if (firstNode == null) return;
                final targetCollapsed = !firstNode.collapsed;
                for (final id in targets) {
                  final n = provider.nodes[id];
                  if (n == null) continue;
                  if (n.collapsed != targetCollapsed) {
                    provider.toggleNodeCollapsed(id);
                  }
                }
              }
            }
          } else if (commandId == 'cutMode') {
            // Ctrl+Shift+V: 裁断モードの切替
            setState(() {
              _cutMode = !_cutMode;
              _cutStartPoint = null;
              _cutPreviewEnd = null;
            });
            _showLockToast(_cutMode
                ? provider.t('toast.cutModeOn')
                : provider.t('toast.cutModeOff'));
          } else if (commandId != null &&
              (_headerExecutedShortcutCommandIds.contains(commandId) ||
                  // 既定キーを持たないボタンに割り当てた時 (= ユーザー要望:
                  //   全てのボタンにキーを割り当てられるように)。
                  _headerCustomizableCommands
                      .any((c) => c['id'] == commandId))) {
            _executeHeaderCommand(commandId, provider);
          } else {
            // ── コマンドに対応しない固定ショートカット ──────────────────────
            if (isCtrl && _getDigitIndex(event.logicalKey) != null) {
              // Ctrl+1〜9: マップを切り替え（変更不可）
              // ── ショートカット基準フォルダーを尊重 ──
              // _shortcutFolderId が設定されていれば、そのフォルダー内の
              // ページの上から N 番目を開く。null なら従来動作 (全ページ
              // の絶対インデックス)。
              final idx = _getDigitIndex(event.logicalKey)!;
              final target = provider.pageForShortcutSlot(idx);
              if (target != null) {
                final realIdx = provider.pages.indexOf(target);
                if (realIdx >= 0) {
                  provider.switchPage(realIdx);
                  WidgetsBinding.instance
                      .addPostFrameCallback((_) => _centerOnRoot());
                }
              }
            // Ctrl+R / Ctrl+Shift+P / Ctrl+Shift+D / Ctrl+Shift+S /
            // Ctrl+K / Ctrl+L の直接ハンドラは廃止 (= 変更可能化。
            // コマンド解決経由の autoSyncPage / newPage / deletePage /
            // syncDialog / lockH / lockV ディスパッチが担当する)。
            } else if (event.logicalKey == LogicalKeyboardKey.backspace) {
              // Backspace: 削除（Delete と同じ挙動 — 図形/範囲図形にも対応）
              if (_rangeSelectedDecorationIds.isNotEmpty) {
                for (final id in _rangeSelectedDecorationIds.toList()) {
                  provider.removeMapDecoration(id);
                }
                setState(() => _rangeSelectedDecorationIds.clear());
                if (_rangeSelectedIds.isNotEmpty) {
                  _handleDeleteKey(context, provider);
                } else {
                  // 図形だけ消した時も選択モードを終わりにする
                  // (= ユーザー要望: 消したら選択モード自体も解除)。
                  _removeOverlay();
                  setState(() {
                    _rangeSelectMode = false;
                    _rangeStart = null;
                    _rangeEnd = null;
                  });
                }
              } else if (_selectedDecorationId != null) {
                _deleteSelectedDecoration();
              } else {
                _handleDeleteKey(context, provider);
              }
            } else if (event.logicalKey == LogicalKeyboardKey.arrowLeft ||
                event.logicalKey == LogicalKeyboardKey.arrowRight ||
                event.logicalKey == LogicalKeyboardKey.arrowUp ||
                event.logicalKey == LogicalKeyboardKey.arrowDown ||
                event.logicalKey == LogicalKeyboardKey.pageUp ||
                event.logicalKey == LogicalKeyboardKey.pageDown) {
              // ★ 左パネル PDF のスクロール (= 右と同じ実装) ★
              // ユーザー要望: 「右のスクロール速度と同じ速度でスクロール」。
              // ExcludeFocus で内部キー処理を止めているので、 ここで自前で
              // 動かす。 右パネルと同じ 200px ステップで完全に統一。
              // アクティブパネル判定は `_splitLeftPanelHover` のみ参照する
              // ため、 「右の動きに合わせて左も」 のような連動は発生しない。
              if (_splitLeftPanelHover &&
                  _splitLeftLocalPdfPath != null &&
                  !_calendarMode) {
                try {
                  const scrollStep = 200.0;
                  final cur = _splitLeftPdfController.scrollOffset;
                  if (event.logicalKey == LogicalKeyboardKey.arrowDown) {
                    _splitLeftPdfController.jumpTo(
                        xOffset: cur.dx, yOffset: cur.dy + scrollStep);
                  } else if (event.logicalKey == LogicalKeyboardKey.arrowUp) {
                    _splitLeftPdfController.jumpTo(
                        xOffset: cur.dx,
                        yOffset:
                            (cur.dy - scrollStep).clamp(0, double.infinity));
                  } else if (event.logicalKey == LogicalKeyboardKey.pageDown) {
                    _splitLeftPdfController.nextPage();
                  } else if (event.logicalKey == LogicalKeyboardKey.pageUp) {
                    _splitLeftPdfController.previousPage();
                  } else if (event.logicalKey ==
                      LogicalKeyboardKey.arrowRight) {
                    _splitLeftPdfController.nextPage();
                  } else if (event.logicalKey == LogicalKeyboardKey.arrowLeft) {
                    _splitLeftPdfController.previousPage();
                  }
                } catch (_) {}
                return;
              }
              // 左パネルが Web の時: 矢印キーで Web ページをスクロール
              //   (= ユーザー要望: 分割した Web ページが上下キーで動かない)。
              if (_splitLeftPanelHover &&
                  _splitLeftMode == 'web' &&
                  !_calendarMode) {
                _scrollSplitWeb(event.logicalKey, left: true);
                return;
              }
              // ★ マウスが分割パネル側にあるとき: PDF を自前スクロール ★
              // SfPdfViewer 内蔵のキー処理に任せると「止まってしまう場所」 が
              // 出るので、 PdfViewerController を使って直接制御する。
              // ・上下キー: 200px ずつ垂直スクロール (= スピード優先)
              // ・PageUp/Down: ページ送り
              // ・左右キー: PDF の場合はページ送り (= 横スクロール無し前提)
              // マップ側 (=! _splitPanelHover) の時は従来通りマップ pan。
              if (_splitPanelHover && _splitMode == 'pdf' && !_calendarMode) {
                try {
                  const scrollStep = 200.0;
                  final cur = _splitPdfController.scrollOffset;
                  // 上下分割 (= scrollDirection: horizontal) の時は
                  // ↑↓ もページめくりにする (= 横スクロール表示なので
                  // 上下キーは縦スクロールしても意味がない)。
                  final isVerticalSplit =
                      _splitPosition == _SplitPosition.top ||
                          _splitPosition == _SplitPosition.bottom;
                  if (event.logicalKey == LogicalKeyboardKey.arrowDown) {
                    if (isVerticalSplit) {
                      _splitPdfController.nextPage();
                    } else {
                      _splitPdfController.jumpTo(
                          xOffset: cur.dx, yOffset: cur.dy + scrollStep);
                    }
                  } else if (event.logicalKey == LogicalKeyboardKey.arrowUp) {
                    if (isVerticalSplit) {
                      _splitPdfController.previousPage();
                    } else {
                      _splitPdfController.jumpTo(
                          xOffset: cur.dx,
                          yOffset:
                              (cur.dy - scrollStep).clamp(0, double.infinity));
                    }
                  } else if (event.logicalKey == LogicalKeyboardKey.pageDown) {
                    _splitPdfController.nextPage();
                  } else if (event.logicalKey == LogicalKeyboardKey.pageUp) {
                    _splitPdfController.previousPage();
                  } else if (event.logicalKey ==
                          LogicalKeyboardKey.arrowRight ||
                      event.logicalKey == LogicalKeyboardKey.arrowLeft) {
                    // PDF は通常横スクロールしないので、 左右キーはページ送り
                    if (event.logicalKey == LogicalKeyboardKey.arrowRight) {
                      _splitPdfController.nextPage();
                    } else {
                      _splitPdfController.previousPage();
                    }
                  }
                } catch (_) {/* PDF 未ロード等は無視 */}
                return;
              }
              // 右パネルが Web の時: 矢印キーで Web ページをスクロール
              //   (= ユーザー要望: 分割した Web ページが上下キーで動かない)。
              if (_splitPanelHover && _splitMode == 'web' && !_calendarMode) {
                _scrollSplitWeb(event.logicalKey, left: false);
                return;
              }
              // マウスがパネル側 (= 非 PDF or 非分割) の時はマップ pan 抑止だけ
              if (_splitPanelHover && !_calendarMode) {
                return;
              }
              // ── フリーノート / 文書ページ: 矢印キーはタブ列ホバー中の
              //    ページ切替だけに使う (= ユーザー報告: 上下カーソルで
              //    ページが遷移してしまう)。 ノート側が消費したらマップの
              //    パンはしない。 ──
              if (!_calendarMode &&
                  _paintArrowKeyHandler != null &&
                  (provider.currentPage.pageType == 'paint' ||
                      provider.currentPage.pageType == 'document')) {
                if (event is KeyDownEvent &&
                    _paintArrowKeyHandler!(event.logicalKey)) {
                  return;
                }
                if (event is! KeyDownEvent) return;
              }
              // カレンダーモード中は矢印キーで「選択中の日」を移動
              if (_calendarMode) {
                setState(() {
                  if (event.logicalKey == LogicalKeyboardKey.arrowLeft) {
                    _selectedCalendarDay =
                        _selectedCalendarDay.subtract(const Duration(days: 1));
                  } else if (event.logicalKey ==
                      LogicalKeyboardKey.arrowRight) {
                    _selectedCalendarDay =
                        _selectedCalendarDay.add(const Duration(days: 1));
                  } else if (event.logicalKey == LogicalKeyboardKey.arrowUp) {
                    _selectedCalendarDay =
                        _selectedCalendarDay.subtract(const Duration(days: 7));
                  } else if (event.logicalKey == LogicalKeyboardKey.arrowDown) {
                    _selectedCalendarDay =
                        _selectedCalendarDay.add(const Duration(days: 7));
                  }
                  // 表示中の月と違ったら月も自動で切り替える
                  if (_selectedCalendarDay.year != _calendarMonth.year ||
                      _selectedCalendarDay.month != _calendarMonth.month) {
                    _calendarMonth = DateTime(
                        _selectedCalendarDay.year, _selectedCalendarDay.month);
                  }
                });
              } else {
                // 通常: キャンバスをスクロール
                _handleArrowKey(event.logicalKey, ctrl);
              }
            } else if (event.logicalKey == LogicalKeyboardKey.enter) {
              // カレンダーモード中: 選択中の日のタイムラインを開く
              if (_calendarMode) {
                _showEventsForDay(context, provider, _selectedCalendarDay);
              }
            }
          }
        },
        child: DropTarget(
          onDragEntered: (_) => setState(() => _isDroppingFile = true),
          onDragExited: (_) => setState(() => _isDroppingFile = false),
          onDragDone: (details) async {
            setState(() => _isDroppingFile = false);
            if (details.files.isEmpty) return;
            // ── 画面分割パネル (web モード) 領域へのドロップ判定 ──
            // ユーザー要望「ファイルをアップロードしようとするとマップが反応
            //   してしまって生成 AI にドラッグ＆ドロップでファイルを渡すこと
            //   ができないからドラッグ＆ドロップで生成 AI にアプリ内からちゃ
            //   んとファイルが渡せるようにして」 への対応:
            //   ドロップ位置がパネル領域内なら、 マップに新規ノードを作るのを
            //   止めて、 WebView 側に paste 相当でファイルを送り込む。
            final hit = _splitPanelHitForDrop(details.localPosition);
            if (hit != null) {
              final isLeft = hit == 'left';
              int ok = 0;
              for (final xf in details.files) {
                final r = await _injectFileToWebView(xf, isLeftPanel: isLeft);
                if (r) ok++;
              }
              if (mounted) {
                _appSnack(
                  context,
                  SnackBar(
                    content: Text(provider
                        .t('ai.sentFiles')
                        .replaceFirst('{n}', '$ok')
                        .replaceFirst(
                            '{panel}',
                            isLeft
                                ? provider.t('split.leftPanelLabel')
                                : provider.t('split.rightPanelLabel'))),
                    backgroundColor: const Color(0xFF6C63FF),
                    duration: const Duration(seconds: 2),
                  ),
                );
              }
              return;
            }
            // ── ビデオエディターページなら、 ドロップをエディターへ委譲 ──
            //   (= ユーザー要望: 動画を D&D でレイヤーに追加)。 マップへの
            //   ノード生成は行わない。
            if (provider.currentPage.pageType == 'videoEditor' &&
                _veDropHandler != null) {
              _veDropHandler!(details.files.map((f) => f.path).toList());
              return;
            }
            // ── フリーノート (paint) ページなら、 ドロップをノートへ委譲 ──
            //   (= ユーザー要望: 画像を D&D で直接入れる / 画像置き場へ格納)。
            if (provider.currentPage.pageType == 'paint' &&
                _paintDropHandler != null) {
              _paintDropHandler!(details.files.map((f) => f.path).toList(),
                  details.globalPosition);
              return;
            }
            // ── 分割中は、 落とした場所のペインを先にアクティブにする
            //    (= ユーザー報告: 左に落としたのに右のマップへ入る)。
            //    ノードは「今編集しているページ」 に作られるため。 ──
            if (_mapSplitOpen) {
              for (final k in _visibleSplitSlots()) {
                if (!_splitCellGlobalRect(k)
                    .contains(details.globalPosition)) {
                  continue;
                }
                if (k == _mapSplitEditorSlot) break; // 既にそこが編集側
                final pid = _mapSplitCells[k];
                if (pid == null) break;
                _mapSplitActivate(provider, pid, slot: k);
                // 切り替え直後のレイアウト反映を待ってから置く。
                await Future<void>.delayed(const Duration(milliseconds: 60));
                break;
              }
            }
            if (!mounted) return;
            await _handleDroppedFiles(details.files, provider, ctrl,
                dropLocalPosition: details.localPosition);
          },
          child: Stack(fit: StackFit.expand, children: [
            Scaffold(
              key: _scaffoldKey,
              // ライトモード時は銀色背景、ダーク時は従来の濃紺
              backgroundColor: provider.isDarkMode
                  ? const Color(0xFF0F0F1A)
                  : const Color(0xFFD8D8D4),
              drawer: _buildDrawer(context, provider),
              // drawer が閉じられた時に複数選択状態をクリアして次回開いた時に
              // 混乱しないようにする (選択モードのまま放置されるのを防ぐ)
              // また、_drawerOpen を更新してフローティングツール (計算機等) を
              // drawer が開いている間は Offstage で裏に隠す。タイマーは裏で動き続ける。
              onDrawerChanged: (open) {
                setState(() => _drawerOpen = open);
                _refreshFloatingOverlays();
                if (!open && _drawerMultiSelectActive) {
                  setState(() {
                    _drawerSelectedPageIds.clear();
                    _drawerSelectedFolderIds.clear();
                    _drawerLastAnchorIndex = null;
                  });
                }
              },
              appBar: _buildAppBar(context, provider),
              body: Padding(
                // 端へ固定したボタンバーはページを覆わず、専用の余白へ収める。
                // 自由配置へ切り替えたバーだけは従来どおりページ上へ重ねる。
                padding: _desktopAnchoredDockInsets(provider),
                child: Stack(
                  key: _bodyStackKey,
                children: [
                  // ── メインレイアウト: Row で完全分離 ──
                  // 旧実装: メインキャンバスを Padding(right: panelWidth) で縮めて、
                  //   その上に Positioned で画面分割パネルをオーバーレイしていたが、
                  //   マウスホイール等のイベントが背後のマップに漏れる問題が出た。
                  // 新実装: Flex で左/右/上/下にパネルを配置できる。 領域が完全に
                  //   独立しているのでイベントが交わらない。
                  //   `_splitOpen == false` の時は _buildSplitPanel が SizedBox.shrink
                  //   を返すため、 Flex のパネル側は実質ゼロ幅 (= 通常のマップ全画面表示)。
                  // ★ パネル位置切替 ★
                  //   - right:  Row, textDirection: ltr → [マップ, パネル]
                  //   - left:   Row, textDirection: rtl → [パネル, マップ]
                  //   - bottom: Column, verticalDirection: down → [マップ, パネル]
                  //   - top:    Flex には入れず、 Scaffold の上に被せるオーバーレイ
                  //             として描画する (ユーザー要望「ヘッダーの上に被さって
                  //             分割」 + 上分割時のフリーズ回避)。
                  Flex(
                    direction: (_splitPosition == _SplitPosition.bottom)
                        ? Axis.vertical
                        : Axis.horizontal,
                    textDirection: _splitPosition == _SplitPosition.left
                        ? TextDirection.rtl
                        : TextDirection.ltr,
                    verticalDirection: VerticalDirection.down,
                    children: [
                      // ── 画面分割「左パネル」 (= 並列 PDF 表示用、 画面の最左に配置) ──
                      // ユーザー要望: 「PDF を画面分割した状態で、 他の PDF を開いたら、
                      // 左右で半分半分異なる PDF が開かれた状態」。
                      // _splitPosition との競合を避けるため、 必ず ltr の Directionality
                      // でラップして「画面の左側」 に固定する。
                      if (_splitLeftOpen)
                        Directionality(
                          textDirection: TextDirection.ltr,
                          child: _buildSplitLeftPanel(provider),
                        ),
                      Expanded(
                        child: Directionality(
                          textDirection: TextDirection.ltr,
                          child: Stack(
                            key: _mapViewportKey,
                            children: [
                              Listener(
                                behavior: HitTestBehavior.translucent,
                                // ── マップ上にマウスが来たら両パネル hover を OFF ──
                                // ユーザー要望「左分割した画面が他のマップや右分割した画面に
                                //   カーソルを載せた状態でもずっとアクティブになっていて、
                                //   マップ等とスクロールが連動してしまう問題」 への対応。
                                // WebView/PdfViewer の Platform View が onExit を取りこぼす
                                // ため、 「マップ上にマウスがいる」 という事実から逆算して
                                // 強制的に左右パネルの hover を false にする。 これで
                                // マップ上ではマップだけがスクロール対象になる。
                                onPointerHover: (_) {
                                  if (_splitPanelHover ||
                                      _splitLeftPanelHover) {
                                    setState(() {
                                      _splitPanelHover = false;
                                      _splitLeftPanelHover = false;
                                    });
                                    // ── Office (Word/Excel/PowerPoint) 等のフォーカス解除 ──
                                    // ユーザー要望「word ファイルを左側で編集した状態で
                                    //   真ん中にカーソルを持ってきてスクロールするとマップ
                                    //   と word が連動して動いてしまう」 への対応。
                                    // 編集中の TextField 等が primaryFocus を握ったままだと
                                    // マウスホイール event がそちらに流れて、 マップに来た
                                    // つもりが Word も一緒にスクロールしてしまう。
                                    // panel → マップへの境界遷移時に明示的に unfocus する
                                    // ことで、 マウスホイールがマップだけに渡るようにする。
                                    try {
                                      FocusManager.instance.primaryFocus
                                          ?.unfocus();
                                      // マップ keyboard focus に戻して Ctrl+Z 等も復活させる
                                      if (_isDesktop &&
                                          !_keyboardFocusNode.hasFocus) {
                                        _keyboardFocusNode.requestFocus();
                                      }
                                    } catch (_) {}
                                  }
                                },
                                onPointerSignal: (event) =>
                                    _handleCanvasWheelScroll(event, ctrl),
                                onPointerDown: (e) {
                                  _recoverCanvasInputBeforePointerDown(e);
                                  // ── ショートカットキー復活処理 ──
                                  // ダイアログを開いて閉じる / メモパネル等を操作するとフォーカスが
                                  // 別の widget に移ってしまい、 ショートカット (Ctrl+Z 等) が
                                  // 効かなくなる症状が出ていた。 キャンバスに pointer event が
                                  // 来た瞬間に keyboard focus を要求し直すことで復旧させる。
                                  // 既にフォーカス済みなら何もしない (= no-op)。
                                  if (_isDesktop &&
                                      !_keyboardFocusNode.hasFocus) {
                                    _keyboardFocusNode.requestFocus();
                                  }
                                  // 裁断モード: クリックで始点/終点を設定
                                  if (_cutMode) {
                                    final canvasPos =
                                        _globalToCanvas(e.position, ctrl);
                                    _handleCutClick(canvasPos);
                                    return;
                                  }
                                  if ((e.kind != PointerDeviceKind.mouse ||
                                          e.buttons == kPrimaryMouseButton) &&
                                      !_rangeSelectMode &&
                                      _moveModeNodeId == null &&
                                      _drawingDecorationKind == null) {
                                    final canvasPos =
                                        _globalToCanvas(e.position, ctrl);
                                    final labelHit = _hitConnectionLabel(
                                        canvasPos,
                                        provider,
                                        ctrl.value.getMaxScaleOnAxis());
                                    if (labelHit != null) {
                                      _removeOverlay();
                                      setState(() {
                                        _clearConnectionBendDragFields(
                                            clearSelection: true);
                                        _draggingConnectionLabel = labelHit;
                                        _suppressConnectionTapAfterBendDrag =
                                            true;
                                        _selectedConnections.clear();
                                        _selectedConnections.add(labelHit);
                                      });
                                      return;
                                    }
                                    final hit = _hitConnectionBendPoint(
                                        canvasPos,
                                        provider,
                                        ctrl.value.getMaxScaleOnAxis());
                                    if (hit != null) {
                                      _removeOverlay();
                                      _beginConnectionBendInteraction(
                                          hit, canvasPos, provider);
                                      return;
                                    }
                                  }
                                  if (_moveModeNodeId != null) {
                                    _onMoveModePointerDown(e, ctrl, provider);
                                  }
                                  // PC: Shift+ドラッグで即範囲選択を開始
                                  if (_isDesktop &&
                                      HardwareKeyboard
                                          .instance.isShiftPressed &&
                                      !_rangeSelectMode &&
                                      _moveModeNodeId == null) {
                                    final canvasPos =
                                        _globalToCanvas(e.position, ctrl);
                                    // 分割中は「編集しているペイン」 の中で
                                    //   始めた時だけ範囲選択にする
                                    //   (= ユーザー報告: 他のマップまで
                                    //   一緒に範囲選択されてしまう)。
                                    if (!_pointerInEditorCell(e.position)) {
                                      return;
                                    }
                                    // ノード上ならスキップ
                                    bool onNode = false;
                                    for (final n in provider.nodes.values) {
                                      final r = Rect.fromLTWH(
                                          n.position.dx,
                                          n.position.dy,
                                          n.width,
                                          n.visualHeight);
                                      if (r.contains(canvasPos)) {
                                        onNode = true;
                                        break;
                                      }
                                    }
                                    if (!onNode) {
                                      setState(() {
                                        _rangeSelectMode = true;
                                        _rangeSelectedIds.clear();
                                        _rangeSelectedDecorationIds.clear();
                                        _rangeStart = canvasPos;
                                        _rangeEnd = canvasPos;
                                        _canvasLongPressActive = true;
                                        _canvasLongPressStart = canvasPos;
                                      });
                                    }
                                  }
                                  // 範囲選択モードでドラッグ開始判定
                                  if (_rangeSelectMode &&
                                      !_rangeDragging &&
                                      (_rangeSelectedIds.isNotEmpty ||
                                          _rangeSelectedDecorationIds
                                              .isNotEmpty)) {
                                    final canvasPos =
                                        _globalToCanvas(e.position, ctrl);
                                    bool hitSelected = false;
                                    for (final id in _rangeSelectedIds) {
                                      final n = provider.nodes[id];
                                      if (n == null) continue;
                                      final r = Rect.fromLTWH(
                                          n.position.dx,
                                          n.position.dy,
                                          n.width,
                                          n.visualHeight);
                                      if (r.contains(canvasPos)) {
                                        hitSelected = true;
                                        break;
                                      }
                                    }
                                    // 選択中の図形の上でドラッグ開始した場合も一括移動を始める
                                    if (!hitSelected &&
                                        _rangeSelectedDecorationIds
                                            .isNotEmpty) {
                                      for (final d in provider.decorations) {
                                        if (!_rangeSelectedDecorationIds
                                            .contains(d.id)) continue;
                                        final resolved =
                                            _resolvedDecoration(d, provider);
                                        if (Rect.fromPoints(
                                                resolved.start, resolved.end)
                                            .inflate(10)
                                            .contains(canvasPos)) {
                                          hitSelected = true;
                                          break;
                                        }
                                      }
                                    }
                                    if (hitSelected) {
                                      // 選択範囲の直上にある操作列がドラッグを覆わない
                                      // よう、移動開始と同時に閉じる。
                                      _removeOverlay();
                                      setState(() {
                                        _rangeDragging = true;
                                        _rangeDragAnchor = canvasPos;
                                        _rangeDragDelta = Offset.zero;
                                      });
                                      _lastDragGlobalPos = e.position;
                                      _edgeScrollCtrl = ctrl;
                                      _startEdgeScrollTimer();
                                    }
                                  }
                                  // ギャラリーではキャンバス枠の外からでも範囲選択
                                  // の起点を置けるようにする。枠外は内側の
                                  // GestureDetector がヒットしないため、外側
                                  // Listener で開始だけ拾う。
                                  if (provider.currentPage.pageType ==
                                          'bookshelf' &&
                                      _rangeSelectMode &&
                                      !_rangeDragging &&
                                      !_canvasLongPressActive &&
                                      _moveModeNodeId == null) {
                                    final box = _canvasKey.currentContext
                                        ?.findRenderObject() as RenderBox?;
                                    if (box != null) {
                                      final local =
                                          box.globalToLocal(e.position);
                                      final outside = local.dx < 0 ||
                                          local.dy < 0 ||
                                          local.dx > box.size.width ||
                                          local.dy > box.size.height;
                                      if (outside) {
                                        setState(() {
                                          _rangeSelectedIds.clear();
                                          _rangeSelectedDecorationIds.clear();
                                          _rangeStart = local;
                                          _rangeEnd = local;
                                          _canvasLongPressActive = true;
                                          _canvasLongPressStart = local;
                                        });
                                        _lastDragGlobalPos = e.position;
                                        _edgeScrollCtrl = ctrl;
                                        _startEdgeScrollTimer();
                                      }
                                    }
                                  }
                                },
                                onPointerMove: (e) {
                                  if (_draggingConnectionLabel != null) {
                                    final original = _draggingConnectionLabel!;
                                    final conn =
                                        _latestConnection(original, provider) ??
                                            original;
                                    final from = provider.nodes[conn.fromId];
                                    final to = provider.nodes[conn.toId];
                                    if (from != null && to != null) {
                                      final canvasPos =
                                          _globalToCanvas(e.position, ctrl);
                                      final position = ConnectionPainter
                                          .closestPositionOnConnection(
                                        canvasPos,
                                        conn,
                                        from,
                                        to,
                                        fallbackLineStyle:
                                            provider.connectionLineStyle,
                                      );
                                      provider.updateConnectionLabelPosition(
                                          conn, position);
                                    }
                                    return;
                                  }
                                  if (_draggingConnectionBend != null &&
                                      _draggingConnectionBendIndex != null) {
                                    final canvasPos =
                                        _globalToCanvas(e.position, ctrl);
                                    _updateSelectedConnectionBends(
                                        canvasPos,
                                        provider,
                                        ctrl.value.getMaxScaleOnAxis());
                                    return;
                                  }
                                  // ── 折れ線: 最後の節点からカーソルまでの
                                  //    1 本をプレビューする (= ユーザー要望) ──
                                  if (_polylineMode &&
                                      _polylinePoints.isNotEmpty) {
                                    final canvasPos =
                                        _globalToCanvas(e.position, ctrl);
                                    setState(() => _polylineCursor = canvasPos);
                                    return;
                                  }
                                  // 裁断モード: 始点が設定済みなら、プレビュー終点を更新
                                  if (_cutMode) {
                                    if (_cutStartPoint != null) {
                                      final canvasPos =
                                          _globalToCanvas(e.position, ctrl);
                                      setState(
                                          () => _cutPreviewEnd = canvasPos);
                                    }
                                    return; // 裁断モード中は他のポインタ処理をスキップ
                                  }
                                  if (_moveModeNodeId != null) {
                                    _onMoveModePointerMove(e, ctrl);
                                  }
                                  // Shift+ドラッグ中: 矩形を拡張
                                  if (_canvasLongPressActive &&
                                      _rangeSelectMode &&
                                      _rangeStart != null &&
                                      !_rangeDragging) {
                                    final canvasPos =
                                        _globalToCanvas(e.position, ctrl);
                                    setState(() {
                                      _rangeEnd = canvasPos;
                                    });
                                  }
                                  // 範囲ドラッグ中: Listenerでノード移動を直接処理
                                  if (_rangeDragging &&
                                      _rangeDragAnchor != null) {
                                    final canvasPos =
                                        _globalToCanvas(e.position, ctrl);
                                    final newDelta =
                                        canvasPos - _rangeDragAnchor!;
                                    // 選択ノード群のいずれかが範囲外ノードのアンカーに近づいたら
                                    // 接続候補としてハイライト。 既存の _currentSnap 表示
                                    // (= ターゲットアンカー上のオレンジハイライト) を流用する。
                                    final snap = _detectAnchorSnapForRange(
                                        _rangeSelectedIds, newDelta, provider);
                                    setState(() {
                                      _rangeDragDelta = newDelta;
                                      _currentSnap = snap;
                                    });
                                  }
                                  // ドラッグ中はカーソル位置を常時更新 + タイマー確保。
                                  // 範囲選択を「描いている」最中も含めて、画面端追尾が効くようにする
                                  // (描画中にカーソルが画面外へ向かうと、キャンバスが自動で
                                  //  そちらへスクロールして矩形を伸ばし続けられる)。
                                  // 長押し経路 / カスタムボタン経路の両方で動くよう、
                                  // `_canvasLongPressActive` を要求しない。
                                  final isDrawingRangeSelect =
                                      _rangeSelectMode &&
                                          _rangeStart != null &&
                                          !_rangeDragging;
                                  if (_rangeDragging ||
                                      _moveModeNodeId != null ||
                                      isDrawingRangeSelect) {
                                    _lastDragGlobalPos = e.position;
                                    _edgeScrollCtrl = ctrl;
                                    _startEdgeScrollTimer();
                                  }
                                },
                                onPointerUp: (e) {
                                  if (_draggingConnectionLabel != null) {
                                    setState(
                                        () => _draggingConnectionLabel = null);
                                    Future.delayed(
                                        const Duration(milliseconds: 80), () {
                                      if (mounted) {
                                        _suppressConnectionTapAfterBendDrag =
                                            false;
                                      }
                                    });
                                    return;
                                  }
                                  if (_connectionBendPointerActive) {
                                    _finishConnectionBendInteraction(provider);
                                    return;
                                  }
                                  // 裁断モードではポインタアップで何もしない（タップイベントで処理）
                                  if (_cutMode) {
                                    return;
                                  }
                                  if (_moveModeNodeId != null) {
                                    _onMoveModePointerUp(e);
                                  }
                                  // Shift+ドラッグ選択の確定
                                  if (_canvasLongPressActive &&
                                      _rangeSelectMode &&
                                      _rangeStart != null &&
                                      _rangeEnd != null &&
                                      !_rangeDragging) {
                                    final rect = Rect.fromPoints(
                                        _rangeStart!, _rangeEnd!);
                                    // ── 親に格納 (折りたたみ) されている子ノードは範囲選択から
                                    //    除外 (= ユーザー要望: 親ノードに子ノードを格納した後に、
                                    //    その子ノードがあった位置に範囲選択するとその子ノードまで
                                    //    選択されてしまいグループ化に含まれるバグの修正) ──
                                    final hidden = provider.hiddenNodeIds;
                                    for (final node in provider.nodes.values) {
                                      if (hidden.contains(node.id)) continue;
                                      final nodeRect = Rect.fromLTWH(
                                          node.position.dx,
                                          node.position.dy,
                                          node.width,
                                          node.visualHeight);
                                      if (rect.overlaps(nodeRect)) {
                                        _rangeSelectedIds.add(node.id);
                                      }
                                    }
                                    _addDecorationsInRect(rect);
                                    final emptySelection =
                                        _rangeSelectedIds.isEmpty &&
                                            _rangeSelectedDecorationIds.isEmpty;
                                    setState(() {
                                      _canvasLongPressActive = false;
                                      _canvasLongPressStart = null;
                                      _rangeStart = null;
                                      _rangeEnd = null;
                                      // 何も選択されなければ即モード解除
                                      if (emptySelection) {
                                        _rangeSelectMode = false;
                                      }
                                    });
                                    // ── 範囲選択が確定したら複数選択メニューを出す ──
                                    // (= ユーザー要望: 単に範囲選択した時も Ctrl+A と
                                    //   同じ項目 (一括編集/AI/カード化等) が出るように)。
                                    // 右上ボタン列廃止に伴い 1 個から出す。
                                    if (!emptySelection &&
                                        _rangeSelectedIds.isNotEmpty &&
                                        _selectedConnections.isEmpty) {
                                      _showMultiNodeActionOverlay(
                                          context, provider, ctrl);
                                    }
                                  }
                                  // 範囲ドラッグ終了
                                  if (_rangeDragging) {
                                    _stopEdgeScroll();
                                    final snap = _currentSnap;
                                    if (snap != null) {
                                      // 範囲ドラッグ中に他のノードのアンカーへスナップしていた:
                                      // 移動 + ターゲットノードを「親」、選択中の各ノードを「子」と
                                      // して一括接続する。Undo は 1 回でまとめて戻る。
                                      //
                                      // ── スペーシング補正 ──
                                      // ソースノード (= スナップ起点) が target から rangeMinGap
                                      // 以上離れる位置になるよう delta 全体を押し出す。同じ delta
                                      // を選択ノード全員に適用するので選択内のレイアウト
                                      // (= 縦並び/横並び等) は崩れない。
                                      // _ensureSpacing は単一ノード前提で、_avoidOverlap が範囲内
                                      // 他ノードと干渉してレイアウトが崩れるため、ここでは流用せず
                                      // アンカー方向ごとに必要な軸オフセットだけを計算する。
                                      const double rangeMinGap = 100.0;
                                      Offset adjustedDelta = _rangeDragDelta;
                                      final src =
                                          provider.nodes[snap.sourceNodeId];
                                      final tgt = provider.nodes[snap.nodeId];
                                      if (src != null && tgt != null) {
                                        final ip = src.position +
                                            _rangeDragDelta; // intended src pos
                                        Offset push = Offset.zero;
                                        switch (snap.fromAnchor) {
                                          case AnchorDirection.west:
                                            final need = tgt.position.dx +
                                                tgt.width +
                                                rangeMinGap;
                                            if (ip.dx < need)
                                              push = Offset(need - ip.dx, 0);
                                            break;
                                          case AnchorDirection.east:
                                            final need = tgt.position.dx -
                                                src.width -
                                                rangeMinGap;
                                            if (ip.dx > need)
                                              push = Offset(need - ip.dx, 0);
                                            break;
                                          case AnchorDirection.north:
                                            // 当たり判定はタイトル本体 (height)。 visualHeight だと
                                            // 大きいノードが離されて近づけない (= ユーザー報告)。
                                            final need = tgt.position.dy +
                                                tgt.height +
                                                rangeMinGap;
                                            if (ip.dy < need)
                                              push = Offset(0, need - ip.dy);
                                            break;
                                          case AnchorDirection.south:
                                            final need = tgt.position.dy -
                                                src.height -
                                                rangeMinGap;
                                            if (ip.dy > need)
                                              push = Offset(0, need - ip.dy);
                                            break;
                                          case AnchorDirection.northEast:
                                          case AnchorDirection.southEast:
                                            // ターゲットの左側に配置 (X 軸のみ)
                                            final need = tgt.position.dx -
                                                src.width -
                                                rangeMinGap;
                                            if (ip.dx > need)
                                              push = Offset(need - ip.dx, 0);
                                            break;
                                          case AnchorDirection.northWest:
                                          case AnchorDirection.southWest:
                                            // ターゲットの右側に配置 (X 軸のみ)
                                            final need = tgt.position.dx +
                                                tgt.width +
                                                rangeMinGap;
                                            if (ip.dx < need)
                                              push = Offset(need - ip.dx, 0);
                                            break;
                                        }
                                        adjustedDelta = _rangeDragDelta + push;
                                      }
                                      // ── 「子ノードと並べる = 兄弟として親に接続」判定 ──
                                      // ユーザー要望: 複数選択を既存の子ノードと並べた時、
                                      // 子の子ではなく **兄弟** として親に接続したい。
                                      // target ノードが親接続を持っていて、 かつスナップが
                                      // target の北/南方向 (= 上下に並ぶ位置) で発生した場合、
                                      // 接続先を target → target の親に切り替えて、 選択ノード群を
                                      // 既存の兄弟と同じ向きで接続する。これにより、 縦並びの
                                      // 兄弟ノード列に追加するように見える UX になる。
                                      String connectTargetId = snap.nodeId;
                                      AnchorDirection connectTargetAnchor =
                                          snap.toAnchor;
                                      AnchorDirection connectSourceAnchor =
                                          snap.fromAnchor;
                                      final isVerticalSiblingSnap =
                                          snap.toAnchor ==
                                                  AnchorDirection.north ||
                                              snap.toAnchor ==
                                                  AnchorDirection.south;
                                      if (isVerticalSiblingSnap) {
                                        for (final c in provider.connections) {
                                          if (c.toId == snap.nodeId) {
                                            // target に親があった → 親へ接続 (兄弟になる)
                                            connectTargetId = c.fromId;
                                            connectTargetAnchor = c.fromAnchor;
                                            // 既存の子と同じ向きで親に繋ぐ
                                            connectSourceAnchor = c.toAnchor;
                                            break;
                                          }
                                        }
                                      }

                                      provider.moveAndConnectToTarget(
                                        Set.of(_rangeSelectedIds),
                                        adjustedDelta,
                                        connectTargetId,
                                        sourceAnchor: connectSourceAnchor,
                                        targetAnchor: connectTargetAnchor,
                                      );
                                    } else {
                                      // ── ドラッグ&ドロップで PDF/リンクノードへメモ変換 ──
                                      // 範囲選択した複数ノードを PDF (添付が .pdf) または
                                      // ハイパーリンク (linkUrl 設定済み) のノード上にドロップ
                                      // すると確認ダイアログ → 承認で元ノードを削除しつつ
                                      // メモとして登録する。
                                      final dropPoint =
                                          (_rangeDragAnchor ?? Offset.zero) +
                                              _rangeDragDelta;
                                      final memoTarget = _detectMemoDropTarget(
                                          provider, dropPoint);
                                      if (memoTarget != null &&
                                          _rangeSelectedIds.isNotEmpty) {
                                        final selectedIds =
                                            Set<String>.from(_rangeSelectedIds);
                                        setState(() {
                                          _rangeDragging = false;
                                          _rangeDragAnchor = null;
                                          _rangeDragDelta = Offset.zero;
                                          _currentSnap = null;
                                        });
                                        _confirmAddNodesAsMemos(context,
                                            provider, memoTarget, selectedIds);
                                        return;
                                      }
                                      // 通常の範囲移動 (接続なし)
                                      if (_rangeSelectedIds.isNotEmpty) {
                                        provider.moveNodes(
                                            Set.of(_rangeSelectedIds),
                                            _rangeDragDelta);
                                        // ギャラリーは位置ではなくセル単位でまとめて
                                        //   移動する (= ユーザー要望)。 でないと整列で
                                        //   元のセル位置に戻ってしまう。
                                        if (provider.currentPage.pageType ==
                                            'bookshelf') {
                                          provider.moveShelfCellsByDelta(
                                              Set.of(_rangeSelectedIds),
                                              _rangeDragDelta);
                                        }
                                      }
                                      // 範囲選択した図形も同じ delta で一括移動 (ユーザー要望)
                                      if (_rangeSelectedDecorationIds
                                          .isNotEmpty) {
                                        provider.moveDecorations(
                                            Set.of(_rangeSelectedDecorationIds),
                                            _rangeDragDelta);
                                      }
                                    }
                                    setState(() {
                                      _rangeDragging = false;
                                      _rangeDragAnchor = null;
                                      _rangeDragDelta = Offset.zero;
                                      _currentSnap = null;
                                    });
                                    _restoreMultiNodeActionOverlayAfterRangeDrag(
                                        provider, ctrl);
                                  }
                                },
                                onPointerCancel: (e) {
                                  if (_draggingConnectionLabel != null) {
                                    setState(() {
                                      _draggingConnectionLabel = null;
                                      _suppressConnectionTapAfterBendDrag =
                                          false;
                                    });
                                  }
                                  if (_connectionBendPointerActive) {
                                    _finishConnectionBendInteraction(provider,
                                        cancelled: true);
                                  }
                                  if (_moveModeNodeId != null) {
                                    _onMoveModePointerCancel(e);
                                  }
                                  _cancelInterruptedCanvasGesture();
                                },
                                // = ユーザー要望: お絵かき/ビデオエディターは専用ビューを表示。
                                //   (ガント/予定表はページではなくカスタムボタンのツールへ移行)。
                                // ── マップの画面分割は最優先 (= ユーザー要望:
                                //    フリーノートもマップ / ギャラリーと同時に
                                //    開けるように、 paint が編集側でも分割を維持)。 ──
                                child: _mapSplitOpen &&
                                        _splitEligiblePage(
                                            provider.currentPage)
                                    ? _buildMapSplitLayout(
                                        context, provider, ctrl)
                                    : provider.currentPage.pageType ==
                                            'markdown'
                                        ? _MarkdownPageView(
                                            key: ValueKey(
                                                'md_${provider.currentPage.id}'),
                                            provider: provider,
                                            pageId: provider.currentPage.id,
                                            extractText:
                                                _extractAttachmentTextForAi,
                                            onEmbedToPage:
                                                (path, name, {pageId}) =>
                                                    _embedFileAsNode(
                                                        provider, path, name,
                                                        pageId: pageId),
                                            onOpenBrowserAi: _isDesktop
                                                ? () => _openDesktopFloatingAi(
                                                    provider)
                                                : null)
                                        : (provider.currentPage.pageType ==
                                                    'document' ||
                                                provider.currentPage.pageType ==
                                                    'paint')
                                        ? _PaintPageView(
                                            key: ValueKey(
                                                'paint_note_${provider.currentPage.id}_${provider.mcpContentTick}'),
                                            provider: provider,
                                            pageId: provider.currentPage.id)
                                        : provider.currentPage.pageType ==
                                                'videoEditor'
                                            ? _VideoEditorPageView(
                                                key: ValueKey(
                                                    'veditor_${provider.currentPage.id}_${provider.mcpContentTick}'),
                                                provider: provider,
                                                pageId: provider.currentPage.id)
                                            : _buildCanvas(
                                                context, provider, ctrl),
                              ),
                              // ── アップロード進捗インジケーター (= ユーザー要望) ──
                              // バックグラウンドのファイルアップロードが進行中か分かるよう、 画面の
                              //   右上端に小さく % を表示する。 アップロードが無い時は出さない。
                              if (provider.isAnyUploading)
                                Positioned(
                                  top: 8,
                                  right: 8,
                                  child: SafeArea(
                                    child: IgnorePointer(
                                      child: Container(
                                        padding: const EdgeInsets.symmetric(
                                            horizontal: 10, vertical: 6),
                                        decoration: BoxDecoration(
                                          color: const Color(0xFF1E1E32)
                                              .withValues(alpha: 0.92),
                                          borderRadius:
                                              BorderRadius.circular(20),
                                          border: Border.all(
                                              color: const Color(0xFF4FC3F7)
                                                  .withValues(alpha: 0.5)),
                                          boxShadow: [
                                            BoxShadow(
                                                color: Colors.black
                                                    .withValues(alpha: 0.4),
                                                blurRadius: 8),
                                          ],
                                        ),
                                        child: Row(
                                            mainAxisSize: MainAxisSize.min,
                                            children: [
                                              SizedBox(
                                                width: 14,
                                                height: 14,
                                                child:
                                                    CircularProgressIndicator(
                                                  strokeWidth: 2,
                                                  value: provider
                                                              .overallUploadProgress >
                                                          0
                                                      ? provider
                                                          .overallUploadProgress
                                                      : null,
                                                  valueColor:
                                                      const AlwaysStoppedAnimation<
                                                              Color>(
                                                          Color(0xFF4FC3F7)),
                                                  backgroundColor:
                                                      Colors.white24,
                                                ),
                                              ),
                                              const SizedBox(width: 8),
                                              Text(
                                                '⬆ ${(provider.overallUploadProgress * 100).round()}%'
                                                '${provider.uploadingCount > 1 ? ' (${provider.uploadingCount})' : ''}',
                                                style: const TextStyle(
                                                    color: Colors.white,
                                                    fontSize: 11,
                                                    fontWeight:
                                                        FontWeight.w600),
                                              ),
                                            ]),
                                      ),
                                    ),
                                  ),
                                ),
                              // 下部ツールバー
                              // ── ギャラリー(bookshelf)でも下部バーを表示 ──
                              //   (= ユーザー要望: モバイルのギャラリーページでも
                              //   下部のボタンを使えるように)。中身は通常ページと
                              //   同じ customBottomButtons / customBottomTopButtons を
                              //   共有し、スロット長押しや⋮メニューの「下部バーを
                              //   カスタマイズ」から設定できる。
                              //   paint / document / videoEditor / markdown は
                              //   専用ツールバーで画面全体を使うため非表示
                              //   (markdown は = ユーザー要望: モバイルの
                              //   マークダウンページでは下部ボタンを出さない)。
                              if (_moveModeNodeId == null &&
                                  !_isDesktop &&
                                  !_isCanvasTextEditing &&
                                  MediaQuery.viewInsetsOf(context).bottom < 1 &&
                                  provider.currentPage.pageType != 'paint' &&
                                  provider.currentPage.pageType != 'document' &&
                                  provider.currentPage.pageType != 'markdown' &&
                                  provider.currentPage.pageType !=
                                      'videoEditor')
                                _buildBottomToolBar(context, provider, ctrl),
                              // ── 図形挿入モードのツールバー ──
                              // 種類切替 + 色 + 太さ + × (終了) を上部中央に固定表示。
                              // モードは図形を描いても解除されず、 × か Esc で終了する。
                              if (_shapePaletteOpen)
                                _buildShapeInsertToolbar(provider),
                              // ── 図形選択時のツールバー ──
                              // 作成済み図形を選択中: 色 / 太さ / 種類の編集 + 削除。
                              // パレットを出している間は重ねない。
                              if (!_shapePaletteOpen &&
                                  _selectedDecorationId != null)
                                _buildShapeSelectionToolbar(provider),
                              // 基準位置設定モード中のバナー
                              if (_settingRefMode)
                                Positioned(
                                  top: 0,
                                  left: 0,
                                  right: 0,
                                  child: SafeArea(
                                    child: Center(
                                      child: Container(
                                        margin: const EdgeInsets.only(top: 8),
                                        padding: const EdgeInsets.symmetric(
                                            horizontal: 20, vertical: 10),
                                        decoration: BoxDecoration(
                                          color: const Color(0xFF43B97F)
                                              .withValues(alpha: 0.9),
                                          borderRadius:
                                              BorderRadius.circular(12),
                                          boxShadow: [
                                            BoxShadow(
                                              color: Colors.black
                                                  .withValues(alpha: 0.4),
                                              blurRadius: 12,
                                            ),
                                          ],
                                        ),
                                        child: Row(
                                            mainAxisSize: MainAxisSize.min,
                                            children: [
                                              const Icon(
                                                  Icons.touch_app_rounded,
                                                  color: Colors.white,
                                                  size: 18),
                                              const SizedBox(width: 8),
                                              Text(
                                                  provider
                                                      .t('banner.tapToSetRef'),
                                                  style: const TextStyle(
                                                      color: Colors.white,
                                                      fontSize: 13,
                                                      fontWeight:
                                                          FontWeight.w600)),
                                              const SizedBox(width: 12),
                                              GestureDetector(
                                                onTap: () => setState(() =>
                                                    _settingRefMode = false),
                                                child: Container(
                                                  padding:
                                                      const EdgeInsets.all(4),
                                                  decoration: BoxDecoration(
                                                    color: Colors.white
                                                        .withValues(alpha: 0.2),
                                                    shape: BoxShape.circle,
                                                  ),
                                                  child: const Icon(Icons.close,
                                                      color: Colors.white,
                                                      size: 14),
                                                ),
                                              ),
                                            ]),
                                      ),
                                    ),
                                  ),
                                ),
                              // 裁断モード中のバナー + 画面外周の赤いボーダー
                              if (_cutMode) ...[
                                Positioned.fill(
                                  child: IgnorePointer(
                                    child: Container(
                                      decoration: BoxDecoration(
                                        border: Border.all(
                                          color: const Color(0xFFFF6B6B)
                                              .withValues(alpha: 0.75),
                                          width: 3,
                                        ),
                                      ),
                                    ),
                                  ),
                                ),
                                Positioned(
                                  top: 0,
                                  left: 0,
                                  right: 0,
                                  child: SafeArea(
                                    child: Center(
                                      child: Container(
                                        margin: const EdgeInsets.only(top: 8),
                                        padding: const EdgeInsets.symmetric(
                                            horizontal: 20, vertical: 10),
                                        decoration: BoxDecoration(
                                          color: const Color(0xFFFF6B6B)
                                              .withValues(alpha: 0.92),
                                          borderRadius:
                                              BorderRadius.circular(12),
                                          boxShadow: [
                                            BoxShadow(
                                              color: Colors.black
                                                  .withValues(alpha: 0.4),
                                              blurRadius: 12,
                                            ),
                                          ],
                                        ),
                                        child: Row(
                                            mainAxisSize: MainAxisSize.min,
                                            children: [
                                              const Icon(
                                                  Icons.content_cut_rounded,
                                                  color: Colors.white,
                                                  size: 18),
                                              const SizedBox(width: 8),
                                              Text(
                                                  provider.t(_cutStartPoint ==
                                                          null
                                                      ? 'banner.cutPickStart'
                                                      : 'banner.cutPickEnd'),
                                                  style: const TextStyle(
                                                      color: Colors.white,
                                                      fontSize: 13,
                                                      fontWeight:
                                                          FontWeight.w600)),
                                              const SizedBox(width: 12),
                                              GestureDetector(
                                                onTap: () {
                                                  setState(
                                                      () => _cutMode = false);
                                                  _resetCutStroke();
                                                },
                                                child: Container(
                                                  padding:
                                                      const EdgeInsets.all(4),
                                                  decoration: BoxDecoration(
                                                    color: Colors.white
                                                        .withValues(alpha: 0.2),
                                                    shape: BoxShape.circle,
                                                  ),
                                                  child: const Icon(Icons.close,
                                                      color: Colors.white,
                                                      size: 14),
                                                ),
                                              ),
                                            ]),
                                      ),
                                    ),
                                  ),
                                ),
                              ],
                              // 検索パネル
                              if (_searchVisible) _buildSearchPanel(provider),
                              // ドロップ中のオーバーレイ表示
                              if (_isDroppingFile)
                                Positioned.fill(
                                  child: IgnorePointer(
                                    child: Container(
                                      color: const Color(0xFF6C63FF)
                                          .withValues(alpha: 0.15),
                                      child: Center(
                                        child: Container(
                                          padding: const EdgeInsets.symmetric(
                                              horizontal: 32, vertical: 20),
                                          decoration: BoxDecoration(
                                            color: const Color(0xFF1E1E32)
                                                .withValues(alpha: 0.95),
                                            borderRadius:
                                                BorderRadius.circular(16),
                                            border: Border.all(
                                                color: const Color(0xFF6C63FF),
                                                width: 2),
                                          ),
                                          child: Row(
                                              mainAxisSize: MainAxisSize.min,
                                              children: [
                                                const Icon(
                                                    Icons.file_upload_rounded,
                                                    color: Color(0xFF6C63FF),
                                                    size: 28),
                                                const SizedBox(width: 12),
                                                Text(provider.t('drop.here'),
                                                    style: const TextStyle(
                                                        color: Colors.white,
                                                        fontSize: 16,
                                                        fontWeight:
                                                            FontWeight.w600)),
                                              ]),
                                        ),
                                      ),
                                    ),
                                  ),
                                ),
                              // ロックトースト（画面中央上部）
                              // モバイルではコンパクトに、デスクトップでは従来通り大きめに表示。
                              if (_lockToastMessage != null)
                                Positioned(
                                  top: 80,
                                  left: 0,
                                  right: 0,
                                  child: IgnorePointer(
                                    child: Center(
                                      child: AnimatedOpacity(
                                        opacity: 1.0,
                                        duration:
                                            const Duration(milliseconds: 200),
                                        child: Container(
                                          padding: _isDesktop
                                              ? const EdgeInsets.symmetric(
                                                  horizontal: 28, vertical: 16)
                                              : const EdgeInsets.symmetric(
                                                  horizontal: 16, vertical: 8),
                                          decoration: BoxDecoration(
                                            color: const Color(0xFF1E1E32),
                                            borderRadius: BorderRadius.circular(
                                                _isDesktop ? 14 : 10),
                                            border: Border.all(
                                                color: const Color(0xFFFFB347),
                                                width: _isDesktop ? 2 : 1.2),
                                            boxShadow: [
                                              BoxShadow(
                                                color: Colors.black
                                                    .withValues(alpha: 0.5),
                                                blurRadius:
                                                    _isDesktop ? 20 : 12,
                                                offset: const Offset(0, 4),
                                              ),
                                            ],
                                          ),
                                          child: Text(
                                            _lockToastMessage!,
                                            style: TextStyle(
                                              color: Colors.white,
                                              fontSize: _isDesktop ? 18 : 12,
                                              fontWeight: FontWeight.w700,
                                              letterSpacing: 0.3,
                                            ),
                                          ),
                                        ),
                                      ),
                                    ),
                                  ),
                                ),
                            ],
                          ),
                        ), // Directionality 閉じ
                      ),
                      // ── 画面分割パネル ──
                      // Flex の中で、 マップキャンバスの隣 (右/左) または下 (bottom)
                      // に並ぶ。 top の場合は Flex に入れず、 Scaffold の上に被せる
                      // オーバーレイとして描画する (下記 _buildTopSplitOverlay)。
                      if (_splitPosition != _SplitPosition.top)
                        _buildSplitPanel(provider),
                    ],
                  ), // Row 閉じ
                  // ── ここから下のフローティング要素 (= 全画面オーバーレイ) ──
                  // 旧実装で `_buildSplitPanel(provider)` を Stack の末尾に置いて
                  // いたが、 上の Row 内に移したのでここでは不要。 通知バナー等の
                  // 全画面オーバーレイは引き続き Stack 直下に残す。
                  //
                  // ── マウス位置で _splitPanelHover を直接判定 (Stack 最前面) ──
                  // MouseRegion(onHover) は hit test を消費しないので、 下の
                  // マップやノードのクリックには影響しない。 マウスポインタが
                  // 画面のどこにあろうとも onHover が呼ばれるので、 パネル境界
                  // との比較で確実に hover フラグを更新できる。 ノードドラッグ
                  // 中など hit test 固定シーンでもこの判定は機能する。
                  if (_splitOpen || _splitLeftOpen)
                    Positioned.fill(
                      child: MouseRegion(
                        opaque: false,
                        // hit test は透過する (= 下のマップ・ノードのクリックは
                        // 通常通り受け取れる)。 MouseRegion 自身は GestureRecognizer
                        // を持たないので pointer event をブロックしない。
                        onHover: (event) {
                          final mq = MediaQuery.of(context).size;
                          // ── 右パネル hover 判定 (既存) ──
                          if (_splitOpen) {
                            final panelSize = _splitPanelEffectiveSize(context);
                            bool overPanel;
                            switch (_splitPosition) {
                              case _SplitPosition.right:
                                overPanel =
                                    event.position.dx >= mq.width - panelSize;
                                break;
                              case _SplitPosition.left:
                                overPanel = event.position.dx < panelSize;
                                break;
                              case _SplitPosition.top:
                                overPanel = event.position.dy < panelSize;
                                break;
                              case _SplitPosition.bottom:
                                overPanel =
                                    event.position.dy >= mq.height - panelSize;
                                break;
                            }
                            if (overPanel != _splitPanelHover) {
                              setState(() => _splitPanelHover = overPanel);
                            }
                          }
                          // ── 左パネル hover 判定 (新規) ──
                          // 画面の最左から _splitLeftPanelWidth ピクセル以内なら
                          // 左パネル上と判定。 ユーザー要望「アクティブになって
                          // いない時は連動してスクロールされない」 のための
                          // 正確なアクティブ判定。
                          if (_splitLeftOpen) {
                            final leftSize = _splitLeftPanelWidth
                                .clamp(0.0, mq.width)
                                .toDouble();
                            final overLeft = event.position.dx < leftSize;
                            if (overLeft != _splitLeftPanelHover) {
                              setState(() => _splitLeftPanelHover = overLeft);
                            }
                          }
                        },
                      ),
                    ),
                  // ── 並び替えモード: 何もない所をタップして解除 ──
                  // (= ユーザー報告: モバイルで並び替えモードを解除できない)。
                  // translucent なので、 ボタンのドラッグ (Draggable) は下の
                  // ボタンへそのまま通り、 タップ (移動なし) だけをここで拾って
                  // 解除する。 ヘッダーの並び替えトレイは AppBar 側 (この body の
                  // 外) にあるので、 この全面レイヤーには覆われない。
                  if (_reorderHeaderMode)
                    Positioned.fill(
                      child: GestureDetector(
                        behavior: HitTestBehavior.translucent,
                        onTap: _exitHeaderReorderMode,
                      ),
                    ),
                ],
                ),
              ),
            ),
            _buildDesktopHeaderButtonsDock(provider),
            // ── 上分割パネルをヘッダーの上に被せる ──
            // ユーザー要望: 上分割はヘッダーに被さるオーバーレイにする
            //   (+ Flex に入れていた時の上分割フリーズも回避)。
            if (_splitOpen && _splitPosition == _SplitPosition.top)
              _buildTopSplitOverlay(provider),
            // ── AI アシスタントを閉じている間の小さな知らせ ──
            // = ユーザー要望「処理中に画面を閉じたら、 処理中と止めるボタンを
            //   小さく表示しておいて欲しい」。 押すとアシスタントを開き直す。
            _buildAiBusyChip(provider),
            // ── 部分録画中は、 録っていない所を暗くする (= ユーザー要望) ──
            _buildRecDimOverlay(),
            // ── 画面録画の操作パネル (= ユーザー要望) ──
            _buildScreenRecBar(provider),
            // ── ヘッドレス YouTube 再生中のフローティング停止ボタン ──
            // ユーザー要望: 「YouTubeをヘッドレスで再生するボタンを作って、
            //   押したらヘッドレス再生を止めるボタンが出てきてプレイヤーが
            //   閉じてバックグラウンド再生されるように」 の停止 UI 側。
            // ヘッドレス再生中 (_headlessYoutubeUrlNotifier が非 null) の
            //   間だけ表示。 タップで `stopHeadlessYoutube()` を呼んで終了。
            ValueListenableBuilder<String?>(
              valueListenable: _headlessYoutubeUrlNotifier,
              builder: (_, url, __) {
                if (url == null || url.isEmpty) {
                  return const SizedBox.shrink();
                }
                return Positioned(
                  left: 12,
                  bottom: 96,
                  child: Material(
                    color: Colors.transparent,
                    child: GestureDetector(
                      onTap: () async {
                        await stopHeadlessYoutube();
                        if (!mounted) return;
                        _appSnack(
                          context,
                          SnackBar(
                            content: Text(provider.t('headless.stopped')),
                            backgroundColor: const Color(0xFF2A2A3E),
                            duration: const Duration(seconds: 1),
                          ),
                        );
                      },
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 14, vertical: 10),
                        decoration: BoxDecoration(
                          color: const Color(0xFFE53935),
                          borderRadius: BorderRadius.circular(22),
                          boxShadow: const [
                            BoxShadow(
                              color: Colors.black54,
                              blurRadius: 8,
                              offset: Offset(0, 2),
                            ),
                          ],
                        ),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            const Icon(Icons.stop_circle_rounded,
                                color: Colors.white, size: 20),
                            const SizedBox(width: 6),
                            Text(provider.t('headless.stop'),
                                style: const TextStyle(
                                    color: Colors.white,
                                    fontSize: 13,
                                    fontWeight: FontWeight.w600)),
                          ],
                        ),
                      ),
                    ),
                  ),
                );
              },
            ),
          ]),
        ),
      );
    });
  }

  // YouTube FABを左下に表示するためのボディ内Stack — 廃止: _buildBottomToolBar に統合

  // ─── 下部ツールバー（横並び） ───────────────────────────────────────────────

  Widget _buildBottomToolBar(BuildContext context, MindMapProvider provider,
      TransformationController ctrl) {
    // SnackBar (AI 処理中等) と被らないよう、`provider.bottomBarLifted` が
    // true の時はツールバーを 96px 持ち上げる。アニメーションで滑らかに移動。
    // 状態は `_appSnack` ヘルパが SnackBar 表示開始時に true、 closed で
    // false に戻す。グローバル管理なのでどの画面の SnackBar でも動く。
    // 持ち上げ量 (96px) は、 SnackBar を下マージン 12px で画面下端に出した
    // ときに 1〜2 行の SnackBar がカスタムボタンの「下」 に完全に収まる高さ。
    return AnimatedPositioned(
      duration: const Duration(milliseconds: 240),
      curve: Curves.easeOutCubic,
      right: 0,
      left: 0,
      bottom: provider.bottomBarLifted ? 96.0 : 0.0,
      child: SafeArea(
        child: Padding(
          padding: const EdgeInsets.only(bottom: 6),
          child: (_bottomBarOpen && !_bottomBarCollapsed)
              ? Row(
                  children: [
                    Expanded(
                      child: Container(
                        margin: const EdgeInsets.only(left: 12, right: 4),
                        padding: const EdgeInsets.symmetric(
                            horizontal: 4, vertical: 5),
                        // ── バー本体は黒背景 (= ユーザー要望: 左右バーと同じく
                        //    ボタン同士の間にも黒い背景が敷かれたバーにする)。
                        //    バーの「後ろ」はページがそのまま見える (バーは
                        //    ページ上に浮くオーバーレイ)。 メッセージは
                        //    bottomBarLifted + 通知余白計算で退避済み。 ──
                        decoration: BoxDecoration(
                          color: provider.headerColor.withValues(alpha: 0.96),
                          borderRadius: BorderRadius.circular(16),
                          boxShadow: [
                            BoxShadow(
                              color: Colors.black.withValues(alpha: 0.22),
                              blurRadius: 10,
                              offset: const Offset(0, 2),
                            ),
                          ],
                        ),
                        // ── 2×6 レイアウト ────────────────────────────────
                        // 1行目: [リンク][添付][範囲選択][＋ノード]|[戻る][進む]
                        // 2行目: [拡大率]|[custom0][custom1][custom2][custom3][custom4]
                        // 固定ボタンは従来通り; 2行目の 2〜6 列目は
                        // provider.customBottomButtons で管理するカスタム項目。
                        // カスタム項目が未登録のスロットは「＋」プレースホルダーが
                        // 表示され、タップで選択シートを開く。
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            // === 1行目 ===
                            // provider.customBottomTopButtons (6 スロット) を
                            // ベースに動的描画。デフォルトは
                            //   [link][file][rangeSelect][addNode][undo][redo]
                            // ユーザーは長押しで他のボタンに差し替えたり、
                            // 並び替えモードで順序を入れ替えられる。
                            //
                            // 画面分割中 (Android で半幅) はボタンが潰れて
                            // 使えなくなるため、 1 行あたりのスロット数を 2
                            // に絞り、 結果として「2×2 = 上位 4 ボタン」 の
                            // グリッド表示にする。
                            Builder(builder: (_) {
                              // 上下分割はマップ(と下部バー)が全幅のまま縦に
                              //   縮むだけなので 2×6 を維持する。 左右分割
                              //   (= 半幅) の時だけ 2×2 に絞る。
                              final isHorizontalSplit =
                                  _splitPosition == _SplitPosition.left ||
                                      _splitPosition == _SplitPosition.right;
                              final isMobileSplitView = _splitOpen &&
                                  isHorizontalSplit &&
                                  MediaQuery.of(context).size.width < 700;
                              final slotsTop = isMobileSplitView
                                  ? 2
                                  : MindMapProvider.mobileBottomTopCustomSlots;
                              // ★ 描画時フォールバック (= ユーザー報告の再発防止:
                              //   下部ボタンが空になる不具合)。 provider 側が空でも
                              //   描画時に既定ボタンを出す。
                              final topButtons =
                                  provider.customBottomTopButtons.isEmpty
                                      ? MindMapProvider.defaultBottomTopButtons
                                      : provider.customBottomTopButtons;
                              return Row(
                                children: [
                                  for (int i = 0; i < slotsTop; i++)
                                    Expanded(
                                      child: Builder(builder: (_) {
                                        // スロット数が足りない場合は空スロット
                                        final id = i < topButtons.length
                                            ? topButtons[i]
                                            : '';
                                        if (id.isEmpty) {
                                          return _ToolBarBtn(
                                            onPressRecord: _rememberCustomButtonPress,
                                            icon: Icons
                                                .add_circle_outline_rounded,
                                            label:
                                                provider.t('bottomBar.empty'),
                                            color: Colors.white
                                                .withValues(alpha: 0.2),
                                            onTap: () =>
                                                _showBottomTopBarCustomizeSheet(
                                                    context, provider, i),
                                          );
                                        }
                                        final btn = _buildBottomTopCustomButton(
                                            id, i, provider, ctrl);
                                        // 並び替えモード中はドラッグ可能に
                                        if (_reorderHeaderMode) {
                                          return _ReorderableHeaderIcon(
                                            index: i,
                                            id: id,
                                            onDropped: (fromIndex) {
                                              if (fromIndex != i) {
                                                final int adjustedNew =
                                                    i > fromIndex ? i + 1 : i;
                                                provider
                                                    .reorderBottomTopButtons(
                                                        fromIndex, adjustedNew);
                                              }
                                            },
                                            child: btn,
                                          );
                                        }
                                        return btn;
                                      }),
                                    ),
                                ],
                              );
                            }),
                            const SizedBox(height: 4),
                            // 行間の薄いセパレーター（任意）
                            Container(
                              height: 1,
                              margin: const EdgeInsets.symmetric(horizontal: 6),
                              color: Colors.white.withValues(alpha: 0.05),
                            ),
                            const SizedBox(height: 4),
                            // === 2行目 ===
                            // 6 スロット構成:
                            //   - lockScale (拡大率ロック) は provider.lockScaleBottomSlot
                            //     で指定された位置 (0..5) に表示
                            //   - 残り 5 スロットは customBottomButtons から順に詰める
                            // 並び替えモード中は lockScale も含めてドラッグ可能。
                            Builder(builder: (_) {
                              final lockSlot =
                                  provider.lockScaleBottomSlot.clamp(0, 5);
                              // ★ 描画時フォールバック (= ユーザー報告の再発防止:
                              //   Android 初回/アップグレードで下部ボタンが
                              //   「集中ロック」 だけになる不具合)。 provider 側が
                              //   何らかの理由で空でも、 描画時に既定ボタンを出して
                              //   必ず操作可能にする。
                              final customs = provider
                                      .customBottomButtons.isEmpty
                                  ? MindMapProvider.defaultBottomBottomButtons
                                  : provider.customBottomButtons;
                              // 画面分割中 (Android で半幅) はスロット数を
                              // 2 に絞って下部バーを 2×2 グリッドにする。
                              // 上下分割は全幅のままなので 2×6 を維持。
                              //   左右分割 (半幅) の時だけ 2×2 に絞る。
                              final isHorizontalSplit =
                                  _splitPosition == _SplitPosition.left ||
                                      _splitPosition == _SplitPosition.right;
                              final isMobileSplitView = _splitOpen &&
                                  isHorizontalSplit &&
                                  MediaQuery.of(context).size.width < 700;
                              final slotsBottom = isMobileSplitView ? 2 : 6;
                              return Row(
                                children: [
                                  for (int visIdx = 0;
                                      visIdx < slotsBottom;
                                      visIdx++)
                                    Expanded(
                                      child: Builder(builder: (_) {
                                        // 画面ロック (集中ロック) スロット
                                        // ── ユーザー要望: 拡大率ロックを初期
                                        //    項目から外し、 代わりに画面ロック
                                        //    ボタンを既定で置く。 色は黄色。 ──
                                        // スロット位置の管理 (lockScaleBottomSlot)
                                        //   と並び替えの仕組みはそのまま流用する。
                                        if (visIdx == lockSlot) {
                                          final lockBtn = _ToolBarBtn(
                                            onPressRecord: _rememberCustomButtonPress,
                                            icon: Icons.lock_clock_rounded,
                                            label: provider
                                                .t('focusLock.menuTitle'),
                                            color: const Color(0xFFE53935),
                                            onTap: () {
                                              _showFocusLockDialog(
                                                  context, provider);
                                            },
                                            // モバイル長押しで並び替えモードや
                                            // 他ボタンとの差し替えメニューを開けるようにする。
                                            // ※ メニューに渡す commandId は 'focusLock'
                                            //   にする。 スロット管理用の 'lockScale' を
                                            //   渡すと拡大率ロックの編集メニューが誤って
                                            //   開いてしまうため (= ユーザー報告のバグ修正)。
                                            onLongPress: !_isDesktop
                                                ? () =>
                                                    _showButtonLongPressMenu(
                                                        context,
                                                        provider,
                                                        'focusLock',
                                                        isFooter: true)
                                                : null,
                                          );
                                          // 並び替えモード時はドラッグ可能 +
                                          // ドロップ受け側でも lockScale との交換を扱う
                                          if (_reorderHeaderMode) {
                                            return _ReorderableHeaderIcon(
                                              index: visIdx,
                                              id: 'lockScale',
                                              onDropped: (fromIndex) {
                                                // fromIndex から lockScale 位置 (visIdx) に
                                                // ドロップされた → スロット入れ替え
                                                if (fromIndex == visIdx) return;
                                                // ① lockScale を fromIndex に移す
                                                //   (元 fromIndex にあった custom は同じ
                                                //    customs[] 配列のままなので、
                                                //    新 lockSlot=fromIndex の場合
                                                //    visIdx<fromIndex の custom は
                                                //    customs[visIdx]、
                                                //    visIdx>fromIndex の custom は
                                                //    customs[visIdx-1] に対応する)
                                                // → 単純に lockSlot を fromIndex に変える
                                                //    だけだと、ドラッグ元 (fromIndex) の
                                                //    custom が画面上で「lockScale が来た
                                                //    旧位置」に押し出される形になる。
                                                //    ユーザーから見ると「位置が入れ替
                                                //    わった」ので OK。
                                                provider
                                                    .swapLockScaleWithVisibleSlot(
                                                        fromIndex);
                                              },
                                              child: lockBtn,
                                            );
                                          }
                                          return lockBtn;
                                        }
                                        // それ以外 = customBottomButtons の順番
                                        // インデックスを計算: visIdx が lockSlot より
                                        // 後なら -1、前ならそのまま
                                        final customIdx = visIdx > lockSlot
                                            ? visIdx - 1
                                            : visIdx;
                                        if (customIdx < customs.length) {
                                          final id = customs[customIdx];
                                          final btn = _buildBottomCustomButton(
                                              id, provider, ctrl);
                                          if (_reorderHeaderMode) {
                                            return _ReorderableHeaderIcon(
                                              index: visIdx,
                                              id: id,
                                              onDropped: (fromIndex) {
                                                if (fromIndex == visIdx) return;
                                                // ドロップ元が lockScale なら、
                                                // lockScale をここに移動
                                                if (fromIndex == lockSlot) {
                                                  provider
                                                      .swapLockScaleWithVisibleSlot(
                                                          visIdx);
                                                  return;
                                                }
                                                // 通常のカスタム間並び替え
                                                final fromCustomIdx =
                                                    fromIndex > lockSlot
                                                        ? fromIndex - 1
                                                        : fromIndex;
                                                final toCustomIdx = customIdx;
                                                if (fromCustomIdx <
                                                        customs.length &&
                                                    toCustomIdx <
                                                        customs.length) {
                                                  // ReorderableListView 仕様に
                                                  // 合わせて adjusted を計算
                                                  final adj = toCustomIdx >
                                                          fromCustomIdx
                                                      ? toCustomIdx + 1
                                                      : toCustomIdx;
                                                  provider.reorderBottomButtons(
                                                      fromCustomIdx, adj);
                                                }
                                              },
                                              child: btn,
                                            );
                                          }
                                          return btn;
                                        }
                                        // 空スロット: ＋プレースホルダー
                                        // ── ユーザー要望: 下段の差し替え候補を
                                        //    上段と統一する ──
                                        // 上段 (1行目) の空スロットは
                                        //   _showBottomTopBarCustomizeSheet
                                        //   (全コマンド一覧) を開くので、 下段も
                                        //   同じ「スロット差し替え」 シート
                                        //   (_showBottomBottomBarCustomizeSheet)
                                        //   を開いて候補を揃える。 旧実装は
                                        //   フィルタ付きの追加シートを開いていて
                                        //   上段と項目が違っていた。
                                        return _ToolBarBtn(
                                          onPressRecord: _rememberCustomButtonPress,
                                          icon:
                                              Icons.add_circle_outline_rounded,
                                          label: provider.t('bottomBar.empty'),
                                          color: Colors.white
                                              .withValues(alpha: 0.2),
                                          onTap: () =>
                                              _showBottomBottomBarCustomizeSheet(
                                                  context, provider, customIdx),
                                        );
                                      }),
                                    ),
                                ],
                              );
                            }),
                            // === 3行目 (= ユーザー要望: Max プランのみ 3 段目) ===
                            // bottomThirdRowEnabled かつ Max かつ 左右分割でない時のみ。
                            if (provider.bottomThirdRowEnabled &&
                                provider.isMaxUnlocked &&
                                !(_splitOpen &&
                                    (_splitPosition == _SplitPosition.left ||
                                        _splitPosition ==
                                            _SplitPosition.right) &&
                                    MediaQuery.of(context).size.width <
                                        700)) ...[
                              const SizedBox(height: 4),
                              Container(
                                height: 1,
                                margin:
                                    const EdgeInsets.symmetric(horizontal: 6),
                                color: Colors.white.withValues(alpha: 0.05),
                              ),
                              const SizedBox(height: 4),
                              Row(
                                children: [
                                  for (int i = 0;
                                      i <
                                          MindMapProvider
                                              .mobileBottomThirdCustomSlots;
                                      i++)
                                    Expanded(
                                      child: Builder(builder: (_) {
                                        final id = i <
                                                provider
                                                    .customBottomThirdButtons
                                                    .length
                                            ? provider
                                                .customBottomThirdButtons[i]
                                            : '';
                                        final btn =
                                            _buildBottomThirdCustomButton(
                                                id, i, provider, ctrl);
                                        if (_reorderHeaderMode &&
                                            id.isNotEmpty) {
                                          return _ReorderableHeaderIcon(
                                            index: i,
                                            id: id,
                                            onDropped: (fromIndex) {
                                              if (fromIndex == i) return;
                                              final adjustedNew =
                                                  i > fromIndex ? i + 1 : i;
                                              provider
                                                  .reorderBottomThirdButtons(
                                                      fromIndex, adjustedNew);
                                            },
                                            child: btn,
                                          );
                                        }
                                        return btn;
                                      }),
                                    ),
                                ],
                              ),
                            ],
                            if (provider.bottomFourthRowEnabled &&
                                provider.isMaxUnlocked &&
                                !(_splitOpen &&
                                    (_splitPosition == _SplitPosition.left ||
                                        _splitPosition ==
                                            _SplitPosition.right) &&
                                    MediaQuery.of(context).size.width <
                                        700)) ...[
                              const SizedBox(height: 4),
                              Container(
                                height: 1,
                                margin:
                                    const EdgeInsets.symmetric(horizontal: 6),
                                color: Colors.white.withValues(alpha: 0.05),
                              ),
                              const SizedBox(height: 4),
                              Row(
                                children: [
                                  for (int i = 0;
                                      i <
                                          MindMapProvider
                                              .mobileBottomFourthCustomSlots;
                                      i++)
                                    Expanded(
                                      child: Builder(builder: (_) {
                                        final id = i <
                                                provider
                                                    .customBottomFourthButtons
                                                    .length
                                            ? provider
                                                .customBottomFourthButtons[i]
                                            : '';
                                        final btn =
                                            _buildBottomThirdCustomButton(
                                                id, i, provider, ctrl,
                                                fourthRow: true);
                                        if (_reorderHeaderMode &&
                                            id.isNotEmpty) {
                                          return _ReorderableHeaderIcon(
                                            index: i,
                                            id: id,
                                            onDropped: (fromIndex) {
                                              if (fromIndex == i) return;
                                              final adjustedNew =
                                                  i > fromIndex ? i + 1 : i;
                                              provider
                                                  .reorderBottomFourthButtons(
                                                      fromIndex, adjustedNew);
                                            },
                                            child: btn,
                                          );
                                        }
                                        return btn;
                                      }),
                                    ),
                                ],
                              ),
                            ],
                          ],
                        ),
                      ),
                    ),
                    GestureDetector(
                      // ── バーの横のボタンは「収納 (畳む)」 (= ユーザー要望:
                      //    非表示ではなく収納にして、 もう一度押したら開く)。
                      //    完全に消すのはヘッダーの非表示ボタン
                      //    (toggleBottomBar) の役目。 ──
                      onTap: () {
                        setState(() {
                          _bottomBarCollapsed = true;
                          _bottomToolbarExpandedNotifier.value = false;
                        });
                      },
                      child: Container(
                        width: 22,
                        height: 22,
                        margin: const EdgeInsets.only(right: 6),
                        decoration: BoxDecoration(
                          color: const Color(0xFF1A1A2E).withValues(alpha: 0.9),
                          borderRadius: BorderRadius.circular(6),
                          border: Border.all(
                              color: Colors.white.withValues(alpha: 0.1)),
                        ),
                        child: const Icon(Icons.chevron_right_rounded,
                            color: Colors.white30, size: 14),
                      ),
                    ),
                  ],
                )
              // ── 畳んだ状態のつまみ ──
              //    押すとバーが開き直す (= ユーザー要望: 収納した後に
              //    もう一度押すと開かれるように)。 完全に消えている
              //    (_bottomBarOpen == false) 時は画面下端の帯で戻す。
              : (_bottomBarOpen && _bottomBarCollapsed)
                  ? Align(
                      alignment: Alignment.bottomRight,
                      child: Padding(
                        padding: const EdgeInsets.only(right: 12),
                        child: GestureDetector(
                          onTap: () {
                            setState(() {
                              _bottomBarCollapsed = false;
                              _bottomToolbarExpandedNotifier.value = true;
                            });
                          },
                          // 上スワイプでも開く (= 片手で戻しやすいように)。
                          onVerticalDragEnd: (d) {
                            if ((d.primaryVelocity ?? 0) < -80) {
                              setState(() {
                                _bottomBarCollapsed = false;
                                _bottomToolbarExpandedNotifier.value = true;
                              });
                            }
                          },
                          child: Container(
                            width: 42,
                            height: 24,
                            decoration: BoxDecoration(
                              color: const Color(0xFF1A1A2E)
                                  .withValues(alpha: 0.9),
                              borderRadius: BorderRadius.circular(8),
                              border: Border.all(
                                  color: Colors.white.withValues(alpha: 0.12)),
                            ),
                            child: const Icon(Icons.chevron_left_rounded,
                                color: Colors.white70, size: 17),
                          ),
                        ),
                      ),
                    )
                  : !_isDesktop
                  ? Align(
                      alignment: Alignment.bottomCenter,
                      child: GestureDetector(
                        behavior: HitTestBehavior.translucent,
                        onTap: () {
                          setState(() {
                            _bottomBarOpen = true;
                            _bottomBarCollapsed = false;
                            _bottomToolbarExpandedNotifier.value = true;
                          });
                        },
                        onVerticalDragEnd: (d) {
                          if ((d.primaryVelocity ?? 0) < -80) {
                            setState(() {
                              _bottomBarOpen = true;
                              _bottomToolbarExpandedNotifier.value = true;
                            });
                          }
                        },
                        child: const SizedBox(
                            width: double.infinity, height: 22),
                      ),
                    )
                  : Align(
                  alignment: Alignment.centerRight,
                  child: Padding(
                    padding: const EdgeInsets.only(right: 16),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        GestureDetector(
                          onTap: () {
                            setState(() {
                              _bottomBarOpen = true;
                              _bottomToolbarExpandedNotifier.value = true;
                            });
                          },
                          child: Container(
                            width: 40,
                            height: 40,
                            decoration: BoxDecoration(
                              color: const Color(0xFF1A1A2E)
                                  .withValues(alpha: 0.9),
                              borderRadius: BorderRadius.circular(12),
                              border: Border.all(
                                  color: Colors.white.withValues(alpha: 0.1)),
                              boxShadow: [
                                BoxShadow(
                                  color: Colors.black.withValues(alpha: 0.3),
                                  blurRadius: 8,
                                ),
                              ],
                            ),
                            child: const Icon(Icons.keyboard_arrow_up_rounded,
                                color: Colors.white54, size: 22),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
        ),
      ),
    );
  }

  /// 画面端へ固定したデスクトップ用ボタンバーの専用レイアウト領域。
  ///
  /// ドック自体は Scaffold の外側にある overlay へ描画されるため、以前は
  /// カレンダーやキャンバスの上へ重なっていた。固定中だけ body を内側へ
  /// 押し込み、自由配置中は余白を戻すことで両方の操作感を保つ。
  EdgeInsets _desktopAnchoredDockInsets(MindMapProvider provider) {
    if (!_isDesktop) return EdgeInsets.zero;
    bool hasAnchoredSide(String placement) {
      return _visibleDesktopHeaderButtonsAt(provider, placement).isNotEmpty &&
          !provider.desktopSideDockFloatingAt(placement);
    }

    // ── 4 辺とも余白を取らない (= ユーザー要望) ──
    // 下部バー: 「後ろは専用の背景ではなく元のページ背景がそのまま見えるように」
    //   → 旧 `hasBottom ? 88 : 0` の帯が Scaffold 背景として露出し
    //   「白い背景」に見えていたので 0 にした。
    // 左右バー: 同じ理由で 80px の帯をやめる (= ユーザー要望:「左右バーの背景が
    //   真っ白なものになっている、 背景を後ろの画面と同じものにして違和感を
    //   なくして」)。 ライトテーマだと Scaffold 背景が白いため、 確保した帯が
    //   そのまま白い柱に見えていた。 帯を無くしてバーをページの上に浮かせれば、
    //   バーの後ろには元のページ (キャンバス) がそのまま続く。
    // hasAnchoredSide は現在は未使用だが、 端固定判定として残しておく。
    if (hasAnchoredSide('left') || hasAnchoredSide('right')) {
      // 判定だけ行い、 余白は取らない。
    }
    return EdgeInsets.zero;
  }

  List<String> _visibleDesktopHeaderButtonsAt(
      MindMapProvider provider, String placement) {
    return provider
        .desktopHeaderButtonsForPlacement(placement)
        .where((id) =>
            !_isRetiredCustomCommand(id) &&
            !_hideCommandForCurrentLocale(id, provider))
        .toList();
  }

  /// 画面の左右端に固定 (= 埋め込み / 端固定) されている縦バーが占める幅。
  ///
  /// = ユーザー要望「スクロールバーがサイドバーと重なるのが気になる。 右端に
  ///   サイドバーを埋め込んだ時は、 全体図とサイドバーの間にスクロールバーが
  ///   来るようにして欲しい」。 ページのスクロールバーと全体図 (ミニマップ) を
  ///   この幅だけ内側へ寄せると、 外側からバー → スクロールバー → 全体図 の
  ///   順に並ぶ。
  ///
  /// 自由配置中のバーは位置が読めないので 0 (= 避けない)。
  double _anchoredSideDockWidth(MindMapProvider provider, String placement) {
    if (!_isDesktop) return 0.0;
    if (_visibleDesktopHeaderButtonsAt(provider, placement).isEmpty) return 0.0;
    if (provider.desktopSideDockFloatingAt(placement)) return 0.0;
    // バー本体の幅 (_buildDesktopSideHeaderDock の dockWidth) は 60 固定。
    // 埋め込んでいない時は端との余白 (edgeMargin 10) ぶんも外側に要る。
    const dockWidth = 60.0;
    return dockWidth +
        (provider.desktopSideDockEmbeddedAt(placement) ? 0.0 : 12.0);
  }

  void _reorderDesktopHeaderButtonsAt(MindMapProvider provider,
      String placement, int oldIndex, int targetIndex) {
    final ids = _visibleDesktopHeaderButtonsAt(provider, placement);
    if (oldIndex < 0 ||
        targetIndex < 0 ||
        oldIndex >= ids.length ||
        targetIndex >= ids.length ||
        oldIndex == targetIndex) return;
    provider.reorderHeaderButtonsById(ids[oldIndex], ids[targetIndex]);
  }

  void _beginDesktopHeaderDrag(_DesktopHeaderDragData data) {
    if (!mounted) return;
    setState(() => _activeDesktopHeaderDrag = data);
  }

  void _endDesktopHeaderDrag() {
    if (!mounted || _activeDesktopHeaderDrag == null) return;
    setState(() => _activeDesktopHeaderDrag = null);
  }

  void _exitHeaderReorderMode() {
    if (!mounted || (!_reorderHeaderMode && _activeDesktopHeaderDrag == null)) {
      return;
    }
    setState(() {
      _reorderHeaderMode = false;
      _activeDesktopHeaderDrag = null;
    });
  }

  bool _isDesktopHeaderDropAtScreenEdge(
      Offset globalPosition, String targetPlacement) {
    final size = MediaQuery.sizeOf(context);
    if (size.width <= 0 || size.height <= 0) return false;
    const sideEdge = 84.0;
    const verticalEdge = 88.0;
    return switch (targetPlacement) {
      'left' => globalPosition.dx <= sideEdge,
      'right' => globalPosition.dx >= size.width - sideEdge,
      'top' => globalPosition.dy <= verticalEdge,
      'bottom' => globalPosition.dy >= size.height - verticalEdge,
      _ => false,
    };
  }

  bool _canAcceptDesktopHeaderDrag(_DesktopHeaderDragData data,
      String targetPlacement, Offset globalPosition) {
    final sourcePlacement = switch (data) {
      _DesktopHeaderBarDragData() => data.sourcePlacement,
      _DesktopHeaderButtonDragData() => data.sourcePlacement,
      _ => '',
    };
    // 別バーへ移す場合はポインタが実際にその画面端へ到達した時だけ受理する。
    // 浮動バーや広い祖先 DragTarget を横切っただけで別辺へ飛ぶ誤操作を防ぐ。
    if (sourcePlacement != targetPlacement &&
        !_isDesktopHeaderDropAtScreenEdge(globalPosition, targetPlacement)) {
      return false;
    }
    if (data is _DesktopHeaderBarDragData) {
      return data.sourcePlacement != targetPlacement;
    }
    if (data is _DesktopHeaderButtonDragData) {
      // 同一バー内はボタン間の専用挿入スロットだけで受理する。外側の広い
      // DragTarget が同一バーのドロップを末尾移動として奪うのを防ぎ、狙った
      // 隙間へ正確に挿入する。別バーへの移動は上の実画面端ガードを通す。
      return data.commandId.isNotEmpty &&
          data.sourcePlacement != targetPlacement;
    }
    return false;
  }

  Future<String?> _askDesktopHeaderBarCollisionMode(
      MindMapProvider provider) async {
    if (!mounted) return null;
    return showDialog<String>(
      context: context,
      barrierColor: Colors.black54,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: Text(
          provider.t('header.barCollisionPromptTitle'),
          style: const TextStyle(color: Colors.white, fontSize: 16),
        ),
        content: Text(
          provider.t('header.barCollisionPromptBody'),
          style: const TextStyle(color: Colors.white70, fontSize: 13),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: Text(provider.t('focusLock.cancel')),
          ),
          OutlinedButton.icon(
            onPressed: () => Navigator.pop(dialogContext, 'merge'),
            icon: const Icon(Icons.call_merge_rounded, size: 17),
            label: Text(provider.t('header.barCollisionMode.merge')),
          ),
          ElevatedButton.icon(
            onPressed: () => Navigator.pop(dialogContext, 'swap'),
            icon: const Icon(Icons.swap_horiz_rounded, size: 17),
            label: Text(provider.t('header.barCollisionMode.swap')),
          ),
        ],
      ),
    );
  }

  Future<void> _acceptDesktopHeaderBarDrag(
    MindMapProvider provider,
    _DesktopHeaderBarDragData data,
    String targetPlacement,
  ) async {
    // 空バーは常設しないため、衝突確認の対象も実際に要素があるバーだけにする。
    final targetHasBar =
        provider.desktopHeaderButtonsForPlacement(targetPlacement).isNotEmpty;
    var mode = targetHasBar ? provider.desktopHeaderBarCollisionMode : 'merge';
    if (mode == 'ask') {
      mode = await _askDesktopHeaderBarCollisionMode(provider) ?? '';
    }
    if (mode == 'merge') {
      await provider.mergeDesktopHeaderButtonBars(
          data.sourcePlacement, targetPlacement);
    } else if (mode == 'swap') {
      await provider.swapDesktopHeaderButtonBars(
          data.sourcePlacement, targetPlacement);
    } else {
      return;
    }
    if (targetPlacement == 'bottom') {
      await provider.setDesktopBottomDockPosition(floating: false);
    }
  }

  void _acceptDesktopHeaderDrag(MindMapProvider provider,
      _DesktopHeaderDragData data, String targetPlacement) {
    if (data is _DesktopHeaderBarDragData) {
      unawaited(_acceptDesktopHeaderBarDrag(provider, data, targetPlacement));
    } else if (data is _DesktopHeaderButtonDragData) {
      unawaited(provider.moveDesktopHeaderButtonToPlacement(
          data.commandId, targetPlacement));
    }
  }

  /// 上下左右バー共通のドロップ受け口。実バーだけでなくドラッグ中に出す
  /// 空辺プレースホルダーにも使い、ボタン単位の移動とバー同士の交換を
  /// 同じ経路へ集約する。
  Widget _buildDesktopHeaderDockTarget(
    MindMapProvider provider,
    String placement,
    Widget child, {
    bool placeholder = false,
  }) {
    return DragTarget<_DesktopHeaderDragData>(
      onWillAcceptWithDetails: (details) =>
          _canAcceptDesktopHeaderDrag(details.data, placement, details.offset),
      onAcceptWithDetails: (details) {
        // 移動元が先にツリーから消えて onDragEnd が欠ける経路でも、
        // 空の配置候補が残らないよう受け入れ側で必ず解除する。
        _endDesktopHeaderDrag();
        _acceptDesktopHeaderDrag(provider, details.data, placement);
      },
      builder: (context, candidates, rejected) {
        final hovered = candidates.isNotEmpty;
        final showPlaceholder = placeholder && _activeDesktopHeaderDrag != null;
        return AnimatedContainer(
          duration: const Duration(milliseconds: 140),
          curve: Curves.easeOut,
          decoration: showPlaceholder
              ? BoxDecoration(
                  color: const Color(0xFF6C63FF)
                      .withValues(alpha: hovered ? 0.28 : 0.10),
                  borderRadius: BorderRadius.circular(16),
                )
              : null,
          foregroundDecoration: (hovered || showPlaceholder)
              ? BoxDecoration(
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(
                    color: const Color(0xFF8D86FF)
                        .withValues(alpha: hovered ? 0.95 : 0.45),
                    width: hovered ? 2.0 : 1.0,
                  ),
                )
              : null,
          child: child,
        );
      },
    );
  }

  /// バー (サイドバー / 下部バー) の「何もない所」 をクリックしたら、
  /// ヘッダーの余白と同じくボタン配置設定を開けるようにする。
  ///
  /// = ユーザー要望「サイドバーや下部バーの何もないところをクリックすると
  ///   ヘッダーと同じようにカスタムボタンの配置設定が出るようにして」。
  ///
  /// 仕組み: バー全体を包む GestureDetector を 1 枚被せるだけ。 ボタン /
  /// 移動グリップ / リサイズハンドルは自分でジェスチャを取り、 ジェスチャ
  /// アリーナでは「より深い側」 が先に勝つので、 この onTap まで届くのは
  /// 余白・仕切り線・ボタンの無い空きスペースだけになる (= ヘッダーで
  /// flexibleSpace に敷いているのと同じ考え方)。
  Widget _wrapBarEmptyAreaCustomizeTap(MindMapProvider provider, Widget bar) {
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: () => _showHeaderCustomizeSheet(context, provider),
      onSecondaryTap: () => _showHeaderCustomizeSheet(context, provider),
      child: bar,
    );
  }

  /// バー全体を別の辺へ移す専用グリップ。下部バーの自由配置用 pan
  /// ハンドルとは別に置くため、既存のフローティング移動も維持される。
  Widget _buildDesktopHeaderDockMoveGrip(
    MindMapProvider provider,
    String placement, {
    double width = 34,
    double height = 30,
    ValueChanged<Offset>? onFreeDrop,
    VoidCallback? onDoubleTap,
  }) {
    final data = _DesktopHeaderBarDragData(placement);
    Offset? lastGlobalPosition;
    final grip = Tooltip(
      message: provider
          .t(onFreeDrop == null ? 'header.redockBar' : 'header.dragDock'),
      child: MouseRegion(
        cursor: SystemMouseCursors.grab,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onDoubleTap: onDoubleTap,
          child: SizedBox(
            width: width,
            height: height,
            child: const Icon(Icons.open_with_rounded,
                size: 17, color: Colors.white54),
          ),
        ),
      ),
    );
    return Draggable<_DesktopHeaderDragData>(
      data: data,
      dragAnchorStrategy: pointerDragAnchorStrategy,
      onDragStarted: () => _beginDesktopHeaderDrag(data),
      onDragUpdate: (details) => lastGlobalPosition = details.globalPosition,
      onDragEnd: (details) {
        if (!details.wasAccepted && onFreeDrop != null) {
          onFreeDrop(
              lastGlobalPosition ?? details.offset + const Offset(23, 23));
        }
        _endDesktopHeaderDrag();
      },
      onDragCompleted: _endDesktopHeaderDrag,
      onDraggableCanceled: (_, __) => _endDesktopHeaderDrag(),
      feedback: Material(
        color: Colors.transparent,
        child: Container(
          width: 46,
          height: 46,
          decoration: BoxDecoration(
            color: const Color(0xFF25253B).withValues(alpha: 0.96),
            borderRadius: BorderRadius.circular(14),
            border: Border.all(color: const Color(0xFF8D86FF), width: 1.5),
            boxShadow: const [
              BoxShadow(color: Colors.black45, blurRadius: 12),
            ],
          ),
          child: const Icon(Icons.open_with_rounded,
              size: 20, color: Colors.white),
        ),
      ),
      childWhenDragging: Opacity(opacity: 0.25, child: grip),
      child: grip,
    );
  }

  Widget _buildDesktopSideHeaderDock(
    MindMapProvider provider,
    String placement,
    Color panelColor,
    Color borderColor,
    List<BoxShadow> shadow,
  ) {
    final screen = MediaQuery.sizeOf(context);
    if (screen.width < 120 || screen.height < 140) {
      return const SizedBox.shrink();
    }
    final collapsed = provider.desktopHeaderDockCollapsedAt(placement);
    final floating = provider.desktopSideDockFloatingAt(placement);
    // ── 画面端への「埋め込み」 (= ユーザー要望: 下部バーの端にある埋め込み
    //    ボタンを左右バーにも) ──。 自由配置中は埋め込みより配置を優先する。
    final embedded =
        provider.desktopSideDockEmbeddedAt(placement) && !floating;
    const dockWidth = 60.0;
    final double edgeMargin = embedded ? 0.0 : 10.0;
    final mediaPadding = MediaQuery.paddingOf(context);
    // ── バーの上限 (= ユーザー要望: 左端のバーが上に飛び出て、 ページ名や
    //    マップ一覧を開くボタンと重なるので、 その高さまで上がれないように) ──
    // ヘッダー (AppBar) の下端 + 余白。 固定配置でも自由配置でもこの線より
    // 上へは行かせない。
    final anchoredTop =
        math.max(kToolbarHeight + 12.0, mediaPadding.top + 8.0).toDouble();
    final anchoredBottom = math.max(12.0, mediaPadding.bottom + 8.0).toDouble();
    final anchoredAvailableHeight =
        math.max(96.0, screen.height - anchoredTop - anchoredBottom).toDouble();
    final absoluteMaxHeight = math.max(96.0, screen.height - 16.0).toDouble();
    final maxHeight = floating
        ? absoluteMaxHeight
        : math.min(absoluteMaxHeight, anchoredAvailableHeight).toDouble();
    final minHeight = math.min(176.0, maxHeight).toDouble();
    final dockHeight = (_desktopSideDockLiveHeights[placement] ??
            provider.desktopSideDockHeightAt(placement))
        .clamp(minHeight, maxHeight)
        .toDouble();
    final actualHeight = collapsed ? 78.0 : dockHeight;
    final anchoredCenter = Offset(
      placement == 'left'
          ? edgeMargin + dockWidth / 2
          : screen.width - edgeMargin - dockWidth / 2,
      collapsed
          ? anchoredTop + actualHeight / 2
          : anchoredTop + anchoredAvailableHeight / 2,
    );
    final requestedCenter = floating
        ? Offset(
            provider.desktopSideDockXAt(placement) * screen.width,
            provider.desktopSideDockYAt(placement) * screen.height,
          )
        : anchoredCenter;
    // ── 上端の制限 (= ユーザー要望: ヘッダーのページ名 / マップ一覧ボタンと
    //    重ならない高さまでしか上がれないように) ──
    // バー上端が anchoredTop より上に行かないよう中心 y の下限を決める。
    // 画面が低くて下限が上限を超える場合は下限を優先しない (clamp が壊れる)。
    final double minCenterY = anchoredTop + actualHeight / 2;
    final double maxCenterY = screen.height - actualHeight / 2 - 8;
    // バーが画面より高くて両立できない時は「上端をヘッダー直下に合わせる」 を
    // 優先する (= ヘッダーのボタンには絶対に被らせない、 というのが要望)。
    double clampCenterY(double y) => minCenterY <= maxCenterY
        ? y.clamp(minCenterY, maxCenterY).toDouble()
        : minCenterY;
    final center = Offset(
      requestedCenter.dx
          .clamp(dockWidth / 2 + (embedded ? 0.0 : 8.0),
              screen.width - dockWidth / 2 - (embedded ? 0.0 : 8.0))
          .toDouble(),
      clampCenterY(requestedCenter.dy),
    );

    final ids = <String>[];
    final rawIds = provider.customHeaderButtons;
    for (int i = 0; i < rawIds.length; i++) {
      final id = rawIds[i];
      if (provider.desktopHeaderButtonPlacementFor(id) != placement ||
          _isRetiredCustomCommand(id) ||
          _hideCommandForCurrentLocale(id, provider)) continue;
      ids.add(id);
    }

    final activeButtonDrag =
        _activeDesktopHeaderDrag is _DesktopHeaderButtonDragData
            ? _activeDesktopHeaderDrag as _DesktopHeaderButtonDragData
            : null;
    final showInsertionGaps = activeButtonDrag?.sourcePlacement == placement;

    Widget insertionGap(String? beforeCommandId) {
      return _DesktopHeaderInsertionGap(
        barAxis: Axis.vertical,
        placement: placement,
        beforeCommandId: beforeCommandId,
        active:
            showInsertionGaps && activeButtonDrag?.commandId != beforeCommandId,
        onDragEnded: _endDesktopHeaderDrag,
        onDropped: (data) {
          unawaited(provider.moveDesktopHeaderButtonToPlacement(
            data.commandId,
            placement,
            beforeCommandId: beforeCommandId,
          ));
        },
      );
    }

    Widget sideButton(int index) {
      final id = ids[index];
      final button = _buildCustomHeaderButton(id, provider);
      if (button == null) return const SizedBox.shrink();
      final slot = SizedBox(
        width: _kHeaderCustomButtonExtent,
        height: _kHeaderCustomButtonExtent,
        child: Center(child: button),
      );
      if (!_reorderHeaderMode) {
        final data = _DesktopHeaderButtonDragData(id, placement);
        return _DesktopDraggableHeaderIcon(
          data: data,
          onDragStarted: () => _beginDesktopHeaderDrag(data),
          onDragEnded: _endDesktopHeaderDrag,
          child: slot,
        );
      }
      return _ReorderableHeaderIcon(
        index: index,
        id: id,
        desktopSourcePlacement: placement,
        child: slot,
        onDragStartedGlobal: (data) => _beginDesktopHeaderDrag(data),
        onDragEndGlobal: _endDesktopHeaderDrag,
        onDropped: (fromIndex) {
          if (fromIndex == index || fromIndex < 0 || fromIndex >= ids.length)
            return;
          _reorderDesktopHeaderButtonsAt(provider, placement, fromIndex, index);
        },
      );
    }

    void freeDropSideBar(Offset globalPosition) {
      final renderBox = context.findRenderObject() as RenderBox?;
      final localPosition =
          renderBox?.globalToLocal(globalPosition) ?? globalPosition;
      final next = Offset(
        localPosition.dx
            .clamp(dockWidth / 2 + 8, screen.width - dockWidth / 2 - 8)
            .toDouble(),
        // ドロップ位置も上端制限に従わせる (= ユーザー要望: ヘッダーの
        // ページ名 / マップ一覧ボタンに被る高さへは置けないように)。
        clampCenterY(localPosition.dy),
      );
      // 端に固定していた時の暗黙の全高を、自由配置へ切り替えた瞬間の
      // 実寸へ確定する。移動後にバーが急に伸びるのを防ぐ。
      unawaited(provider.setDesktopSideDockHeight(placement, dockHeight));
      unawaited(provider.setDesktopSideDockPosition(
        placement,
        floating: true,
        x: next.dx / screen.width,
        y: next.dy / screen.height,
      ));
      setState(() => _desktopSideDockLiveHeights.remove(placement));
    }

    void resetSideBarDock() {
      setState(() => _desktopSideDockLiveHeights.remove(placement));
      unawaited(provider.setDesktopSideDockPosition(
        placement,
        floating: false,
      ));
    }

    void commitSideBarHeight() {
      final next = _desktopSideDockLiveHeights[placement] ?? dockHeight;
      unawaited(provider.setDesktopSideDockHeight(placement, next));
      setState(() => _desktopSideDockLiveHeights.remove(placement));
    }

    Widget resizeHandle(bool top) => Tooltip(
          message: provider.t('header.resizeDock'),
          child: MouseRegion(
            cursor: SystemMouseCursors.resizeUpDown,
            child: GestureDetector(
              behavior: HitTestBehavior.opaque,
              onVerticalDragUpdate: (details) {
                final current =
                    _desktopSideDockLiveHeights[placement] ?? dockHeight;
                final delta = (top ? -details.delta.dy : details.delta.dy) * 2;
                setState(() {
                  _desktopSideDockLiveHeights[placement] =
                      (current + delta).clamp(minHeight, maxHeight).toDouble();
                });
              },
              onVerticalDragEnd: (_) => commitSideBarHeight(),
              onVerticalDragCancel: commitSideBarHeight,
              child: SizedBox(
                width: 46,
                height: 9,
                child: Center(
                  child: Container(
                    width: 24,
                    height: 3,
                    decoration: BoxDecoration(
                      color: Colors.white.withValues(alpha: 0.24),
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                ),
              ),
            ),
          ),
        );

    final sideMenu = Material(
      color: Colors.transparent,
      child: Container(
        width: dockWidth,
        height: actualHeight,
        padding: collapsed
            ? const EdgeInsets.symmetric(horizontal: 5, vertical: 6)
            : const EdgeInsets.symmetric(horizontal: 5),
        decoration: BoxDecoration(
          color: panelColor,
          // 埋め込み中は画面端側の角を直角にして端と一体化させる
          // (= ユーザー要望: 下部バーと同じ埋め込みを左右バーにも)。
          borderRadius: embedded
              ? BorderRadius.only(
                  topLeft: Radius.circular(placement == 'left' ? 0 : 16),
                  bottomLeft: Radius.circular(placement == 'left' ? 0 : 16),
                  topRight: Radius.circular(placement == 'left' ? 16 : 0),
                  bottomRight: Radius.circular(placement == 'left' ? 16 : 0),
                )
              : BorderRadius.circular(16),
          border: Border.all(color: borderColor),
          boxShadow: shadow,
        ),
        child: collapsed
            ? Column(mainAxisSize: MainAxisSize.min, children: [
                _buildDesktopHeaderDockMoveGrip(
                  provider,
                  placement,
                  width: 46,
                  height: 30,
                  onFreeDrop: freeDropSideBar,
                  onDoubleTap: resetSideBarDock,
                ),
                IconButton(
                  tooltip: provider.t('header.expandDock'),
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints.tightFor(width: 46, height: 36),
                  icon: Icon(
                    placement == 'left'
                        ? Icons.chevron_right_rounded
                        : Icons.chevron_left_rounded,
                    color: Colors.white70,
                    size: 21,
                  ),
                  onPressed: () =>
                      provider.setDesktopHeaderDockCollapsed(placement, false),
                ),
              ])
            : Column(children: [
                resizeHandle(true),
                _buildDesktopHeaderDockMoveGrip(
                  provider,
                  placement,
                  width: 46,
                  height: 24,
                  onFreeDrop: freeDropSideBar,
                  onDoubleTap: resetSideBarDock,
                ),
                Divider(height: 1, color: borderColor),
                Expanded(
                  // アプリ全体の ScrollbarTheme は常時表示だが、左右のドックだけは
                  // スクロール操作中に現れ、停止するとフェードアウトさせる。
                  child: ScrollbarTheme(
                    data: ScrollbarTheme.of(context).copyWith(
                      thumbVisibility: const WidgetStatePropertyAll(false),
                      trackVisibility: const WidgetStatePropertyAll(false),
                    ),
                    child: SingleChildScrollView(
                      key: PageStorageKey<String>(
                          'desktop_header_buttons_$placement'),
                      physics: const ClampingScrollPhysics(),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          if (ids.isNotEmpty) insertionGap(ids.first),
                          for (int i = 0; i < ids.length; i++) ...[
                            sideButton(i),
                            insertionGap(
                                i + 1 < ids.length ? ids[i + 1] : null),
                          ],
                        ],
                      ),
                    ),
                  ),
                ),
                Divider(height: 1, color: borderColor),
                SizedBox(
                  width: _kHeaderCustomButtonExtent,
                  height: _kHeaderCustomButtonExtent,
                  child: const SizedBox.shrink(),
                ),
                // ── 画面端へ埋め込む / 浮かせるへ戻す (= ユーザー要望:
                //    下部バーの端にある埋め込みボタンを左右バーにも) ──
                IconButton(
                  tooltip: provider.t(embedded
                      ? 'header.floatSideDock'
                      : 'header.embedSideDock'),
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints.tightFor(width: 46, height: 32),
                  icon: Icon(
                    embedded
                        ? Icons.horizontal_distribute_rounded
                        : (placement == 'left'
                            ? Icons.align_horizontal_left_rounded
                            : Icons.align_horizontal_right_rounded),
                    color: Colors.white54,
                    size: 18,
                  ),
                  onPressed: () {
                    if (!provider.desktopSideDockEmbeddedAt(placement)) {
                      // 自由配置中に埋め込みを押したら端固定へ戻して埋め込む。
                      if (provider.desktopSideDockFloatingAt(placement)) {
                        unawaited(provider.setDesktopSideDockPosition(placement,
                            floating: false));
                      }
                      setState(
                          () => _desktopSideDockLiveHeights.remove(placement));
                      unawaited(
                          provider.setDesktopSideDockEmbedded(placement, true));
                    } else {
                      unawaited(
                          provider.setDesktopSideDockEmbedded(placement, false));
                    }
                  },
                ),
                IconButton(
                  tooltip: provider.t('header.collapseDock'),
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints.tightFor(width: 46, height: 32),
                  icon: Icon(
                    placement == 'left'
                        ? Icons.chevron_left_rounded
                        : Icons.chevron_right_rounded,
                    color: Colors.white54,
                    size: 19,
                  ),
                  onPressed: () =>
                      provider.setDesktopHeaderDockCollapsed(placement, true),
                ),
                resizeHandle(false),
              ]),
      ),
    );
    return Positioned(
      left: center.dx - dockWidth / 2,
      top: center.dy - actualHeight / 2,
      child: _buildDesktopHeaderDockTarget(
        provider,
        placement,
        _wrapBarEmptyAreaCustomizeTap(provider, sideMenu),
      ),
    );
  }

  Widget _buildDesktopBottomHeaderDock(
    MindMapProvider provider,
    List<String> ids,
    Color panelColor,
    Color borderColor,
    List<BoxShadow> shadow,
  ) {
    final screen = MediaQuery.sizeOf(context);
    // 起動直後やウィンドウ最小化中は Stack の実寸が一時的に極小になる。
    // この間に clamp の下限が上限を超えないよう、寸法確定まで描画しない。
    if (screen.width < 120 || screen.height < 96) {
      return const SizedBox.shrink();
    }
    final maxWidth = math.max(96.0, screen.width - 24.0).toDouble();
    final minWidth = math.min(180.0, maxWidth).toDouble();
    final dockWidth =
        (_desktopBottomDockLiveWidth ?? provider.desktopBottomDockWidth)
            .clamp(minWidth, maxWidth)
            .toDouble();
    final collapsed = provider.desktopHeaderDockCollapsedAt('bottom');
    final actualWidth =
        (collapsed ? math.min(104.0, maxWidth) : dockWidth).toDouble();
    final dockHeight = collapsed ? 46.0 : 66.0;
    // ── 下端への「埋め込み」 (= ユーザー要望: 浮かせるだけでなく画面下端に
    //    ぴったり密着するモードも選べる)。 自由配置中は埋め込みより優先。
    final embedded =
        provider.desktopBottomDockEmbedded && !provider.desktopBottomDockFloating;

    Offset anchoredCenter() => Offset(screen.width / 2,
        screen.height - dockHeight / 2 - (embedded ? 0 : 12));
    final unshiftedCenter = _desktopBottomDockLiveCenter ??
        (provider.desktopBottomDockFloating
            ? Offset(provider.desktopBottomDockX * screen.width,
                provider.desktopBottomDockY * screen.height)
            : anchoredCenter());
    // ── 通知が出てもバーは動かさない (= ユーザー要望: 「メッセージ自体が
    //    バーより上に出るようにして欲しい」) ──
    // 旧: 通知中はドックを 104px 上へ逃がしていたため、 メッセージのたびに
    //     バーが飛び跳ねて位置が定まらなかった。 今は逆に、 メッセージ側が
    //     バーの実位置を見て上へ回り込む (`_snackBarFloatingMargin` 参照)。
    final requestedCenter = unshiftedCenter;
    final center = Offset(
      requestedCenter.dx
          .clamp(actualWidth / 2 + 8, screen.width - actualWidth / 2 - 8)
          .toDouble(),
      requestedCenter.dy
          .clamp(dockHeight / 2 + 8,
              screen.height - dockHeight / 2 - (embedded ? 0 : 8))
          .toDouble(),
    );

    void freeDropBottomBar(Offset globalPosition) {
      final renderBox = context.findRenderObject() as RenderBox?;
      final localPosition =
          renderBox?.globalToLocal(globalPosition) ?? globalPosition;
      final next = Offset(
        localPosition.dx
            .clamp(actualWidth / 2 + 8, screen.width - actualWidth / 2 - 8)
            .toDouble(),
        localPosition.dy
            .clamp(dockHeight / 2 + 8, screen.height - dockHeight / 2 - 8)
            .toDouble(),
      );
      provider.setDesktopBottomDockPosition(
        floating: true,
        x: screen.width <= 0 ? 0.5 : next.dx / screen.width,
        y: screen.height <= 0 ? 0.88 : next.dy / screen.height,
      );
      setState(() => _desktopBottomDockLiveCenter = null);
    }

    void resetBottomBarDock() {
      setState(() => _desktopBottomDockLiveCenter = null);
      provider.setDesktopBottomDockPosition(floating: false);
    }

    Widget resizeHandle(bool left) => Tooltip(
          message: provider.t('header.resizeDock'),
          child: MouseRegion(
            cursor: SystemMouseCursors.resizeLeftRight,
            child: GestureDetector(
              behavior: HitTestBehavior.opaque,
              onHorizontalDragUpdate: (details) {
                final current = _desktopBottomDockLiveWidth ?? dockWidth;
                final delta = (left ? -details.delta.dx : details.delta.dx) * 2;
                setState(() {
                  _desktopBottomDockLiveWidth =
                      (current + delta).clamp(minWidth, maxWidth).toDouble();
                });
              },
              onHorizontalDragEnd: (_) {
                final next = _desktopBottomDockLiveWidth ?? dockWidth;
                provider.setDesktopBottomDockWidth(next);
                setState(() => _desktopBottomDockLiveWidth = null);
              },
              onHorizontalDragCancel: () {
                final next = _desktopBottomDockLiveWidth ?? dockWidth;
                provider.setDesktopBottomDockWidth(next);
                setState(() => _desktopBottomDockLiveWidth = null);
              },
              child: Container(
                width: 9,
                margin: const EdgeInsets.symmetric(vertical: 8),
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.08),
                  borderRadius: BorderRadius.circular(5),
                ),
              ),
            ),
          ),
        );

    final content = Material(
      color: Colors.transparent,
      child: Container(
        width: actualWidth,
        height: dockHeight,
        // = ユーザー要望: バー本体は左右バーと同じ黒背景 (panelColor) を持ち、
        //   その「後ろ」に元のページ背景が見える (専用余白 88px は廃止済み →
        //   _desktopAnchoredDockInsets 参照)。 下端埋め込み中は下側の角を
        //   直角にして画面下端と一体化させる。
        decoration: BoxDecoration(
          color: panelColor,
          borderRadius: embedded
              ? BorderRadius.vertical(
                  top: Radius.circular(collapsed ? 14 : 16))
              : BorderRadius.circular(collapsed ? 14 : 16),
          border: Border.all(color: borderColor),
          boxShadow: shadow,
        ),
        child: collapsed
            ? Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                _buildDesktopHeaderDockMoveGrip(provider, 'bottom',
                    width: 62,
                    height: dockHeight,
                    // 埋め込み中は自由配置させない (= ユーザー要望: 下端に
                    // 配置した時は位置が自由に動かないように)。 他の端
                    // (左/右/上) へのドラッグ移動は従来どおりできる。
                    onFreeDrop: embedded ? null : freeDropBottomBar,
                    onDoubleTap: resetBottomBarDock),
                IconButton(
                  tooltip: provider.t('header.expandDock'),
                  visualDensity: VisualDensity.compact,
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints.tightFor(width: 30, height: 40),
                  icon: const Icon(Icons.unfold_more_rounded,
                      color: Colors.white70, size: 19),
                  onPressed: () =>
                      provider.setDesktopHeaderDockCollapsed('bottom', false),
                ),
              ])
            : Column(children: [
                SizedBox(
                  height: 16,
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      _buildDesktopHeaderDockMoveGrip(provider, 'bottom',
                          width: 98,
                          height: 16,
                          // 埋め込み中は位置固定 (= ユーザー要望)。
                          onFreeDrop: embedded ? null : freeDropBottomBar,
                          onDoubleTap: resetBottomBarDock),
                    ],
                  ),
                ),
                Expanded(
                  child: Row(children: [
                    resizeHandle(true),
                    Expanded(
                      child: _HeaderCustomButtonsBar(
                        provider: provider,
                        buildButton: _buildCustomHeaderButton,
                        buttonIds: ids,
                        storageKey: 'desktop_header_buttons_bottom',
                        reorderMode: _reorderHeaderMode,
                        desktopPlacement: 'bottom',
                        onDesktopButtonDragStarted: _beginDesktopHeaderDrag,
                        onDesktopButtonDragEnded: _endDesktopHeaderDrag,
                        activeDesktopButtonDrag: _activeDesktopHeaderDrag
                                is _DesktopHeaderButtonDragData
                            ? _activeDesktopHeaderDrag
                                as _DesktopHeaderButtonDragData
                            : null,
                        fullWidth: true,
                        maxWidth: math.max(0.0, dockWidth - 50).toDouble(),
                        trailing: const SizedBox.shrink(),
                        onReorder: _reorderHeaderMode
                            ? (oldIndex, newIndex) =>
                                _reorderDesktopHeaderButtonsAt(
                                    provider, 'bottom', oldIndex, newIndex)
                            : null,
                      ),
                    ),
                    // ── 下端へ埋め込む / 浮かせるへ戻す (= ユーザー要望) ──
                    IconButton(
                      tooltip: provider.t(embedded
                          ? 'header.floatBottomDock'
                          : 'header.embedBottomDock'),
                      visualDensity: VisualDensity.compact,
                      constraints:
                          const BoxConstraints.tightFor(width: 32, height: 40),
                      icon: Icon(
                          embedded
                              ? Icons.vertical_align_center_rounded
                              : Icons.vertical_align_bottom_rounded,
                          color: Colors.white54,
                          size: 18),
                      onPressed: () {
                        if (!provider.desktopBottomDockEmbedded) {
                          // 自由配置中に埋め込みを押したら固定へ戻して埋め込む。
                          if (provider.desktopBottomDockFloating) {
                            provider.setDesktopBottomDockPosition(
                                floating: false);
                          }
                          setState(() => _desktopBottomDockLiveCenter = null);
                          provider.setDesktopBottomDockEmbedded(true);
                        } else {
                          provider.setDesktopBottomDockEmbedded(false);
                        }
                      },
                    ),
                    IconButton(
                      tooltip: provider.t('header.collapseDock'),
                      visualDensity: VisualDensity.compact,
                      constraints:
                          const BoxConstraints.tightFor(width: 32, height: 40),
                      icon: const Icon(Icons.unfold_less_rounded,
                          color: Colors.white54, size: 18),
                      onPressed: () => provider.setDesktopHeaderDockCollapsed(
                          'bottom', true),
                    ),
                    resizeHandle(false),
                  ]),
                ),
              ]),
      ),
    );

    return Positioned(
      left: center.dx - actualWidth / 2,
      top: center.dy - dockHeight / 2,
      child: _buildDesktopHeaderDockTarget(
          provider, 'bottom', _wrapBarEmptyAreaCustomizeTap(provider, content)),
    );
  }

  Widget _buildDesktopHeaderButtonsDock(MindMapProvider provider) {
    if (!_isDesktop ||
        // Scaffold の Drawer よりこのドック用 Stack の方が後に描画されるため、
        // 開いたマップ一覧の上へボタンバーが重ならないようにする。
        _drawerOpen ||
        _moveModeNodeId != null ||
        _rangeSelectMode ||
        _editingMapName) return const SizedBox.shrink();

    final panelColor = Color.alphaBlend(
      provider.headerColor.withValues(alpha: 0.88),
      const Color(0xFF151522),
    );
    final borderColor = Colors.white.withValues(alpha: 0.12);
    final shadow = <BoxShadow>[
      BoxShadow(
        color: Colors.black.withValues(alpha: 0.34),
        blurRadius: 14,
        offset: const Offset(0, 4),
      ),
    ];
    final bottomIds = _visibleDesktopHeaderButtonsAt(provider, 'bottom');
    final leftIds = _visibleDesktopHeaderButtonsAt(provider, 'left');
    final rightIds = _visibleDesktopHeaderButtonsAt(provider, 'right');
    // 要素が無いバーは常設しない。辺全体の DragTarget はカスタムボタンまたは
    // バーをドラッグしている間だけ下の placeholder として表示する。
    final bottomEnabled = bottomIds.isNotEmpty;
    final leftEnabled = leftIds.isNotEmpty;
    final rightEnabled = rightIds.isNotEmpty;
    final showEmptyTargets = _activeDesktopHeaderDrag != null;
    if (!bottomEnabled && !leftEnabled && !rightEnabled && !showEmptyTargets) {
      return const SizedBox.shrink();
    }

    Widget emptySideTarget(String placement) => Positioned(
          top: kToolbarHeight + 12,
          bottom: 12,
          left: placement == 'left' ? 10 : null,
          right: placement == 'right' ? 10 : null,
          child: SafeArea(
            top: false,
            child: _buildDesktopHeaderDockTarget(
              provider,
              placement,
              const SizedBox(
                width: 60,
                child: Center(
                  child: Icon(Icons.vertical_align_center_rounded,
                      color: Colors.white38, size: 22),
                ),
              ),
              placeholder: true,
            ),
          ),
        );

    Widget emptyBottomTarget() => Positioned(
          left: 80,
          right: 80,
          bottom: 12,
          child: SafeArea(
            top: false,
            child: _buildDesktopHeaderDockTarget(
              provider,
              'bottom',
              const SizedBox(
                width: double.infinity,
                height: 64,
                child: Center(
                  child: Icon(Icons.horizontal_rule_rounded,
                      color: Colors.white38, size: 28),
                ),
              ),
              placeholder: true,
            ),
          ),
        );

    return Positioned.fill(
      child: Stack(clipBehavior: Clip.none, children: [
        if (bottomEnabled)
          _buildDesktopBottomHeaderDock(
              provider, bottomIds, panelColor, borderColor, shadow),
        if (showEmptyTargets && !bottomEnabled) emptyBottomTarget(),
        if (leftEnabled)
          _buildDesktopSideHeaderDock(
              provider, 'left', panelColor, borderColor, shadow),
        if (showEmptyTargets && !leftEnabled) emptySideTarget('left'),
        if (rightEnabled)
          _buildDesktopSideHeaderDock(
              provider, 'right', panelColor, borderColor, shadow),
        if (showEmptyTargets && !rightEnabled) emptySideTarget('right'),
      ]),
    );
  }

  Widget _buildHeaderMiddleCustomButtons(MindMapProvider provider,
      {double? maxWidth}) {
    if (!_isDesktop) return const SizedBox.shrink();
    // ── 全ページ種別で共通の customHeaderButtons を表示する ──
    // (= ユーザー要望 2026-07: マインドマップとフリーノート/ギャラリーで
    //  ヘッダーのボタン構成を揃える。 旧: normal 以外は galleryHeaderButtons)。
    final ids = _visibleDesktopHeaderButtonsAt(provider, 'top');
    // 空の上部バーも常設せず、ドラッグ中だけ配置先を表示する。
    final enabled = ids.isNotEmpty;
    final showEmptyTarget = !enabled && _activeDesktopHeaderDrag != null;
    if (!enabled && !showEmptyTarget) {
      // ── カスタムボタンが 1 つも無い時は誘導を出す (= ユーザー要望:
      //    カスタマイズボタンを消した代わりに、 ここをクリックの文面) ──
      final noneAnywhere = !provider.customHeaderButtons.any((id) =>
          !_isRetiredCustomCommand(id) &&
          !_hideCommandForCurrentLocale(id, provider));
      if (noneAnywhere) {
        // ★ 文言は出さず + ボタンだけにする (= ユーザー要望: シンプルな
        //   作りに)。 何のボタンかは載せた時に分かるので、 案内は不要。
        return Tooltip(
          message: provider.t('header.emptyBarHint'),
          child: InkWell(
            borderRadius: BorderRadius.circular(18),
            onTap: () => _showHeaderCustomizeSheet(context, provider),
            child: Container(
              width: 36,
              height: 36,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: Colors.white.withValues(alpha: 0.06),
                shape: BoxShape.circle,
                border: Border.all(color: Colors.white24),
              ),
              child: const Icon(Icons.add_rounded,
                  color: Colors.white54, size: 20),
            ),
          ),
        );
      }
      return const SizedBox.shrink();
    }

    if (showEmptyTarget) {
      return _buildDesktopHeaderDockTarget(
        provider,
        'top',
        const SizedBox(
          width: 176,
          height: 42,
          child: Center(
            child: Icon(Icons.horizontal_rule_rounded,
                color: Colors.white38, size: 28),
          ),
        ),
        placeholder: true,
      );
    }

    final collapsed = provider.desktopHeaderDockCollapsedAt('top');
    final moveGrip =
        _buildDesktopHeaderDockMoveGrip(provider, 'top', width: 32, height: 40);
    final Widget content;
    if (collapsed) {
      content = Material(
        color: Colors.transparent,
        child: Container(
          height: 42,
          padding: const EdgeInsets.symmetric(horizontal: 3),
          decoration: BoxDecoration(
            color: Colors.black.withValues(alpha: 0.12),
            borderRadius: BorderRadius.circular(14),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            moveGrip,
            IconButton(
              tooltip: provider.t('header.expandDock'),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints.tightFor(width: 34, height: 38),
              icon: const Icon(Icons.unfold_more_rounded,
                  color: Colors.white70, size: 19),
              onPressed: () =>
                  provider.setDesktopHeaderDockCollapsed('top', false),
            ),
          ]),
        ),
      );
    } else {
      final barMaxWidth =
          maxWidth == null ? null : math.max(0.0, maxWidth - 66.0).toDouble();
      Widget expanded = Material(
        color: Colors.transparent,
        child: Container(
          height: _kHeaderCustomBarHeight,
          decoration: BoxDecoration(
            color: Colors.black.withValues(alpha: 0.08),
            borderRadius: BorderRadius.circular(15),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            moveGrip,
            _HeaderCustomButtonsBar(
              provider: provider,
              buildButton: _buildCustomHeaderButton,
              buttonIds: ids,
              storageKey: 'desktop_header_buttons_top',
              reorderMode: _reorderHeaderMode,
              desktopPlacement: 'top',
              onDesktopButtonDragStarted: _beginDesktopHeaderDrag,
              onDesktopButtonDragEnded: _endDesktopHeaderDrag,
              activeDesktopButtonDrag:
                  _activeDesktopHeaderDrag is _DesktopHeaderButtonDragData
                      ? _activeDesktopHeaderDrag as _DesktopHeaderButtonDragData
                      : null,
              maxWidth: barMaxWidth,
              onReorder: _reorderHeaderMode
                  ? (oldIndex, newIndex) => _reorderDesktopHeaderButtonsAt(
                      provider, 'top', oldIndex, newIndex)
                  : null,
            ),
            IconButton(
              tooltip: provider.t('header.collapseDock'),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints.tightFor(width: 34, height: 40),
              icon: const Icon(Icons.unfold_less_rounded,
                  color: Colors.white54, size: 18),
              onPressed: () =>
                  provider.setDesktopHeaderDockCollapsed('top', true),
            ),
          ]),
        ),
      );
      if (maxWidth != null) {
        expanded = ConstrainedBox(
          constraints: BoxConstraints(maxWidth: maxWidth),
          child: expanded,
        );
      }
      content = expanded;
    }

    return _buildDesktopHeaderDockTarget(
      provider,
      'top',
      content,
    );
  }

  /// AI チャット (MCP) を開く。 必要なら先にサーバー機構を起動する。
  /// ヘッダーの常設ボタンと ⋮ メニューの両方から呼ばれる。
  /// フローティング AI 窓から「AI アシスタントを開いて」 と頼まれた時
  /// (= ユーザー要望)。 本体で MCP チャットを開く。
  void _onAssistantRequested() {
    final v = assistantRequestFromFloating.value;
    if (v == null || !mounted) return;
    // 同じ値で 2 回走らないように、 受け取ったら消しておく。
    assistantRequestFromFloating.value = null;
    final provider = context.read<MindMapProvider>();
    // ★ 浮遊窓では開かない (= ユーザー要望: AI アシスタントはアプリの中で
    //   しか使わないのでフローティングは要らない)。 普通に開く。
    // ignore: discarded_futures
    _openMcpChat(provider);
  }

  /// 直前に知らせた未読数 (増えた時だけ OS 通知を出すため)。
  final Map<String, int> _serviceUnreadShown = {};

  /// DM 未読が変わった (= 外部フローティング窓がタイトルから拾って知らせて
  /// きた)。 バッジを描き直し、 増えていたら OS 通知も出す (= ユーザー要望:
  /// Instagram / Slack / Discord などの DM 通知を表示)。
  void _onServiceBadgeChanged() {
    if (!mounted) return;
    serviceUnreadCounts.forEach((host, count) {
      final prev = _serviceUnreadShown[host] ?? 0;
      if (count > prev && _isDesktop) {
        final label = _serviceLabelForHost(host) ?? host;
        _showWindowsOsNotification(
            null,
            label,
            context
                .read<MindMapProvider>()
                .t('notif.newDm')
                .replaceFirst('{n}', '$count'));
      }
      _serviceUnreadShown[host] = count;
    });
    setState(() {});
  }

  String? _serviceLabelForHost(String host) {
    for (final e in _webCommandTargets.entries) {
      try {
        if (Uri.parse(e.value[0]).host == host) return e.value[1];
      } catch (_) {}
    }
    return null;
  }

  /// このボタンのサービスの未読数 (バッジ表示用)。 0 なら出さない。
  int _unreadForCommand(String commandId) {
    try {
      final url = _webCommandUrl(commandId) ?? '';
      final h = Uri.parse(url).host;
      if (h.isEmpty) return 0;
      return serviceUnreadCounts[h] ?? 0;
    } catch (_) {
      return 0;
    }
  }

  /// デスクトップのショートカットから「このボタンを実行して」 と届いた時。
  void _onShortcutCommandRequested() {
    final id = commandRequestFromShortcut.value;
    if (id == null || id.isEmpty || !mounted) return;
    // 同じ値で 2 回走らないように、 受け取ったら消しておく。
    commandRequestFromShortcut.value = null;
    _runShortcutCommand(id);
  }

  /// ショートカットから頼まれたボタンの動作を実行する
  /// (= ユーザー要望: ショートカットを押すと他のカスタムボタンを一発で呼ぶ)。
  ///
  /// 起動直後は各種の読み込みが終わっていないことがあるので、 少し待ってから
  /// 実行する。 ショートカットを作るボタン自身は (無限に入れ子になるので)
  /// 実行しない。
  void _runShortcutCommand(String commandId) {
    if (!mounted || commandId.isEmpty) return;
    if (commandId == 'makeShortcut') return;
    unawaited(() async {
      // ★ 開き方の設定を読み終わる前に実行すると、 フローティング設定でも
      //   既定の右分割で開いてしまう (= ユーザー報告)。 読み込みを待つ。
      try {
        await _commandOpenStylesReady;
      } catch (_) {}
      await Future<void>.delayed(const Duration(milliseconds: 300));
      if (!mounted) return;
      try {
        _executeHeaderCommand(commandId, context.read<MindMapProvider>());
      } catch (_) {/* 未知の ID などは黙って無視 */}
    }());
  }

  /// AI アシスタントを「浮かせた」 状態で開く (= ユーザー要望:
  /// フローティング AI から呼ぶと、 アシスタントや決済の画面も前面に出る)。
  /// 開いている間だけ本体の窓を常に手前にし、 閉じたら元へ戻す。
  /// フローティング経由でアシスタントを開いている間 true
  /// (= 決済までの画面も同じ浮遊窓の中に出すための印)。
  bool _assistantOpenedFloating = false;

  Future<void> _openMcpChatFloating(MindMapProvider provider) async {
    var pinned = false;
    if (_isDesktop) {
      try {
        await windowManager.setAlwaysOnTop(true);
        pinned = true;
      } catch (_) {}
    }
    // 開いている間、 Windows は他アプリのクリックで TOPMOST が外れるので
    // 3 秒ごとに確かめる。 ★ フラグが立ったままなら触らない (= ユーザー報告:
    // 無条件に持ち上げ直すと、 操作のたびに消えたり出たりして邪魔)。
    Timer? keep;
    if (pinned) {
      keep = Timer.periodic(const Duration(seconds: 3), (_) async {
        try {
          if (await windowManager.isAlwaysOnTop()) return;
          await windowManager.setAlwaysOnTop(true);
        } catch (_) {}
      });
    }
    _assistantOpenedFloating = true;
    try {
      // 小さな浮遊窓で開く (= ユーザー要望: アシスタントもフローティングで)。
      await _openMcpChat(provider, floatingPanel: true);
    } finally {
      _assistantOpenedFloating = false;
      keep?.cancel();
      if (pinned) {
        try {
          await windowManager.setAlwaysOnTop(false);
        } catch (_) {}
      }
    }
  }

  /// AI アシスタント (MCP チャット) を開く。
  /// [initialTask] を渡すと、 その仕事の前提を AGENTS.md と同じ扱いで
  /// 添えて開く (= ユーザー要望: + ボタンから「AI で新規ページ作成」)。
  // ─── 画面録画 (= ユーザー要望: ビデオエディターの外からも使えるように /
  //     録る範囲を指定できるように) ──────────────────────────────────
  /// 前に選んだ範囲 (次からは選び直さなくてよいように覚えておく)。
  ScreenRecRegion? _lastRecRegion;

  /// 録る範囲を選んでもらう。 返り値が null なら取り消し。
  /// 中の region が null なら画面全体。
  Future<({ScreenRecRegion? region, bool ok})?> _askRecRegion() async {
    final provider = context.read<MindMapProvider>();
    final v = scap.virtualScreenRect();
    if (v == null) return (region: null, ok: true); // 取れない環境は全画面
    final shot = scap.captureScreenRectPng(v.x, v.y, v.width, v.height);
    if (shot == null || !mounted) return (region: null, ok: true);
    return showDialog<({ScreenRecRegion? region, bool ok})>(
      context: context,
      builder: (_) => _ScreenRecRegionDialog(
        provider: provider,
        shot: shot,
        vx: v.x,
        vy: v.y,
        vw: v.width,
        vh: v.height,
        initial: _lastRecRegion,
      ),
    );
  }

  /// 画面録画の開始 / 停止。 [onSaved] に録れたファイルのパスを渡す。
  ///
  /// 録画そのものは画面の外 (ScreenRecorder) が持っているので、
  /// ビデオエディターを閉じても録り続けられる。
  Future<void> toggleScreenRecording(
      {void Function(String path)? onSaved}) async {
    final provider = context.read<MindMapProvider>();
    final rec = ScreenRecorder.instance;
    if (rec.recording) {
      unawaited(_disarmRecStopHotkey());
      try {
        final path = await rec.stop();
        if (!mounted) return;
        _recLastSaved = path;
        _recActiveRegion = null;
        _pushScreenRecState();
        if (onSaved != null) {
          onSaved(path);
          await _showRecWinAgain();
        } else if (_recPreviewAfter && _recWinId != null) {
          // ── プレビューも外の録画窓の中で出す (= ユーザー要望) ──
          if (!await _sendPreviewToRecWin(path)) {
            await _closeAutoRecWin();
            unawaited(_showScreenRecPreview(path, provider));
          }
        } else if (_recPreviewAfter) {
          await _showRecWinAgain();
          // ── 撮り終わったらプレビューを出す (= ユーザー要望) ──
          unawaited(_showScreenRecPreview(path, provider));
        } else {
          _screenRecFinishedNotice(path, provider);
          await _showRecWinAgain();
        }
      } catch (e) {
        if (!mounted) return;
        // ★ 失敗したら、 中身の無いファイルを渡さずに理由を出す
        //   (= ユーザー報告「画面録画が表示されない」 の原因はこれだった)。
        _recActiveRegion = null;
        _pushScreenRecState();
        await _showRecWinAgain();
        _screenRecSnack('${provider.t('ve.screenRecFailed')}: $e',
            const Color(0xFFE57373));
      }
      if (mounted) setState(() {});
      return;
    }
    // ── Android は OS の MediaProjection で録る (= ユーザー要望: モバイル
    //    版でも画面録画に対応)。 範囲指定はできないので画面全体。 ──
    if (Platform.isAndroid) {
      try {
        await rec.startAndroid();
        _startRecBridge();
        if (!mounted) return;
        _screenRecSnack(
            provider.t('ve.screenRecStarted'), const Color(0xFF43B97F));
        _pushScreenRecState();
      } catch (e) {
        if (mounted) _screenRecSnack('$e', const Color(0xFFE57373));
      }
      if (mounted) setState(() {});
      return;
    }
    if (!Platform.isWindows) {
      _screenRecSnack(provider.t('ve.screenRecDesktopOnly'),
          const Color(0xFFFFB347));
      return;
    }
    final ff = await findFfmpegExe();
    if (!mounted) return;
    if (ff == null) {
      await _showFfmpegMissingSimple(provider);
      return;
    }
    final chosen = await _askRecRegion();
    if (chosen == null || !mounted) return; // 取り消し
    _lastRecRegion = chosen.region;
    try {
      await rec.start(ff, region: chosen.region);
      if (!mounted) return;
      _screenRecSnack(
          chosen.region == null
              ? provider.t('ve.screenRecStarted')
              : '${provider.t('ve.screenRecStarted')} (${chosen.region})',
          const Color(0xFF43B97F));
      _pushScreenRecState();
      // 停止のグローバルホットキーを構える (= ユーザー要望)。
      await _armRecStopHotkey();
    } catch (e) {
      if (!mounted) return;
      _screenRecSnack('$e', const Color(0xFFE57373));
    }
    if (mounted) setState(() {});
  }

  // ─── モバイル: 録画を外の窓 (オーバーレイ) で操れるようにする橋 ───
  //     (= ユーザー要望: モバイル版の録画ボタンを外に出せない)
  //     オーバーレイは別エンジンなので直接は触れない。 1 秒ごとに
  //     prefs へ「録画中か / 何秒たったか」 を書き、 向こうが置いた
  //     「止めて」 の合図を拾う。
  static const String _kRecStateBridgeKey = 'floating_rec_state_v1';
  static const String _kRecStopBridgeKey = 'floating_rec_stop_v1';
  Timer? _recBridgeTimer;

  void _startRecBridge() {
    if (_isDesktop) return;
    _recBridgeTimer?.cancel();
    _recBridgeTimer =
        Timer.periodic(const Duration(seconds: 1), (_) async {
      final rec = ScreenRecorder.instance;
      try {
        final sp = await SharedPreferences.getInstance();
        await sp.setString(
            _kRecStateBridgeKey, '${rec.recording ? 1 : 0}|${rec.seconds}');
        await sp.reload();
        if (sp.getBool(_kRecStopBridgeKey) == true) {
          await sp.setBool(_kRecStopBridgeKey, false);
          if (rec.recording && mounted) {
            await _recBarStop(context.read<MindMapProvider>());
          }
        }
      } catch (_) {}
      if (!rec.recording) _stopRecBridge();
    });
  }

  void _stopRecBridge() {
    _recBridgeTimer?.cancel();
    _recBridgeTimer = null;
    unawaited(() async {
      try {
        final sp = await SharedPreferences.getInstance();
        await sp.setString(_kRecStateBridgeKey, '0|0');
      } catch (_) {}
    }());
  }

  /// 録画の操作をアプリの外の窓へ出す (Android)。
  Future<void> _popOutRecToOverlay(MindMapProvider provider) async {
    if (kIsWeb || !Platform.isAndroid) {
      _screenRecSnack(provider.t('popOut.desktopOnly'),
          const Color(0xFFFFB347));
      return;
    }
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString('floating_overlay_mode_v1', 'rec');
    } catch (_) {}
    await _toggleFloatingMemoOverlay(provider, forceOpen: true);
    _startRecBridge();
    if (mounted) setState(() => _recBarOpen = false);
  }

  void _screenRecSnack(String msg, Color color) {
    if (!mounted) return;
    ScaffoldMessenger.maybeOf(context)?.showSnackBar(SnackBar(
      content: Text(msg, style: const TextStyle(fontSize: 12.5)),
      backgroundColor: color,
      duration: const Duration(seconds: 4),
    ));
  }

  /// ffmpeg が無い時の案内 (ヘッダーの画面録画から押した場合)。
  /// 自動インストールはビデオエディター側が持っているので、 そちらへ促す。
  Future<void> _showFfmpegMissingSimple(MindMapProvider provider) async {
    if (!mounted) return;
    await showDialog<void>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('video.ffmpegNotFound'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Text(
            '${provider.t('video.ffmpegNotFoundBody')}\n\n'
            '${provider.t('ve.ffmpegFromEditor')}',
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
            onPressed: () {
              Navigator.pop(dctx);
              try {
                launchUrl(Uri.parse('https://ffmpeg.org/download.html'),
                    mode: LaunchMode.externalApplication);
              } catch (_) {}
            },
            child: Text(provider.t('video.howToGet')),
          ),
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.close'),
                style: const TextStyle(color: Colors.white54)),
          ),
        ],
      ),
    );
  }

  /// ビデオエディターの外で録り終えた時の知らせ。 そのまま貼れるようにする。
  void _screenRecFinishedNotice(String path, MindMapProvider provider) {
    final messenger = ScaffoldMessenger.maybeOf(context);
    messenger?.showSnackBar(SnackBar(
      content: Text('${provider.t('ve.screenRecSaved')}\n$path',
          style: const TextStyle(fontSize: 12)),
      duration: const Duration(seconds: 8),
      action: SnackBarAction(
        label: provider.t('ve.screenRecOpenFolder'),
        onPressed: () {
          try {
            Process.run('explorer', ['/select,', path.replaceAll('/', '\\')]);
          } catch (_) {}
        },
      ),
    ));
  }

  // ─── 画面録画の操作パネル (= ユーザー要望: Windows+G を押した時のような
  //     録画画面が出てほしい) ─────────────────────────────────────────
  /// パネルを出しているか。
  bool _recBarOpen = false;

  /// パネルの位置 (ドラッグで動かせる)。 null なら既定の位置 (上・中央寄り)。
  Offset? _recBarPos;

  /// 録る対象。 'screen' = 画面全体 / 'region' = 範囲を選ぶ。
  String _recTarget = 'screen';

  /// 保存先 (= ユーザー要望: 指定できるように)。 空なら既定の場所。
  String _recSaveDir = '';
  static const String _kRecDirKey = 'screenRecSaveDir';

  /// 撮り終わったらプレビューを出すか (= ユーザー要望: 出すか選べるように)。
  bool _recPreviewAfter = true;
  static const String _kRecPreviewKey = 'screenRecPreviewAfter';

  Future<void> _loadRecSaveDir() async {
    try {
      final sp = await SharedPreferences.getInstance();
      _recSaveDir = sp.getString(_kRecDirKey) ?? '';
      ScreenRecorder.customDir = _recSaveDir;
      _recPreviewAfter = sp.getBool(_kRecPreviewKey) ?? true;
      _recStopHotkey = sp.getString(_kRecHotkeyKey) ?? 'ctrl+alt+r';
    } catch (_) {}
  }

  Future<void> _setRecPreviewAfter(bool v) async {
    if (mounted) setState(() => _recPreviewAfter = v);
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setBool(_kRecPreviewKey, v);
    } catch (_) {}
    _pushScreenRecState();
    // ── 何が変わったか出す (= ユーザー報告: 押しても反応しないように
    //    見える)。 実際は「撮り終わった後にプレビューを出すか」 の
    //    切り替えで、 その場では何も起きないため分かりにくかった。 ──
    _screenRecSnack(
        v ? '撮り終わったらプレビューを出します' : '撮り終わってもプレビューは出しません',
        v ? const Color(0xFF43B97F) : const Color(0xFF616184));
  }

  /// 保存先フォルダーを選ぶ。
  Future<void> _pickRecSaveDir(MindMapProvider provider) async {
    try {
      final dir = await FilePicker.platform.getDirectoryPath(
          dialogTitle: provider.t('ve.recSaveDirPick'));
      if (dir == null || !mounted) return;
      setState(() => _recSaveDir = dir);
      ScreenRecorder.customDir = dir;
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_kRecDirKey, dir);
      if (!mounted) return;
      _screenRecSnack('${provider.t('ve.recSaveDirSet')}: $dir',
          const Color(0xFF43B97F));
    } catch (e) {
      if (mounted) _screenRecSnack('$e', const Color(0xFFE57373));
    }
  }

  /// 直前に録れたファイル (パネルに「開く」 を出すため)。
  String? _recLastSaved;

  Widget _buildScreenRecBar(MindMapProvider provider) {
    if (!_recBarOpen) return const SizedBox.shrink();
    final rec = ScreenRecorder.instance;
    final media = MediaQuery.sizeOf(context);
    // ── バーが画面からはみ出さないようにする (= ユーザー報告: モバイルで
    //    画面録画のバーを消せない。 幅が画面より広く、 右端の × が画面外に
    //    出ていたのが原因)。 中の道具は横スクロールに逃がし、 × は常に
    //    バーの右端に見えるようにする。 ──
    final barMaxW = math.max(200.0, media.width - 16);
    final pos = _recBarPos ??
        Offset(math.max(0.0, (media.width - 360) / 2), 74);
    return Positioned(
      left: pos.dx.clamp(0.0, math.max(0.0, media.width - barMaxW)),
      top: pos.dy.clamp(0.0, math.max(0.0, media.height - 80)),
      child: AnimatedBuilder(
        animation: rec,
        builder: (_, __) => Material(
          color: Colors.transparent,
          child: GestureDetector(
            // どこを掴んでも動かせる (= 録画したい場所から避けられるように)。
            onPanUpdate: (d) => setState(() {
              _recBarPos = (_recBarPos ?? pos) + d.delta;
            }),
            child: Container(
              padding: const EdgeInsets.fromLTRB(12, 8, 8, 8),
              constraints: BoxConstraints(maxWidth: barMaxW),
              decoration: BoxDecoration(
                color: const Color(0xF21B1B2C),
                borderRadius: BorderRadius.circular(14),
                border: Border.all(
                    color: rec.recording
                        ? const Color(0xFFE53935)
                        : Colors.white24),
                boxShadow: const [
                  BoxShadow(
                      color: Colors.black87,
                      blurRadius: 16,
                      offset: Offset(0, 4)),
                ],
              ),
              child: Row(mainAxisSize: MainAxisSize.min, children: [
                // ── 道具の列は入り切らなければ横スクロール。 × は列の外
                //    (右端) に固定するので、 いつでも押して閉じられる。 ──
                Flexible(
                  child: SingleChildScrollView(
                    scrollDirection: Axis.horizontal,
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                Icon(Icons.screenshot_monitor_rounded,
                    size: 17,
                    color: rec.recording
                        ? const Color(0xFFE53935)
                        : const Color(0xFF9575CD)),
                const SizedBox(width: 8),
                if (rec.recording) ...[
                  // ── 録画中: 赤い点 + 経過時間 + 停止 ──
                  _RecBlinkDot(),
                  const SizedBox(width: 7),
                  Text(rec.label,
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 14,
                          fontFeatures: [FontFeature.tabularFigures()],
                          fontWeight: FontWeight.w700)),
                  const SizedBox(width: 10),
                  _recBarButton(
                    icon: Icons.stop_rounded,
                    label: provider.t('ve.screenRecStop'),
                    color: const Color(0xFFE53935),
                    onTap: () => unawaited(_recBarStop(provider)),
                  ),
                  // キーボードのショートカットはモバイルでは押せないので
                  // 出さない (= ユーザー要望)。
                  // 録画中も外へ出せるようにする (= ユーザー要望)。
                  const SizedBox(width: 4),
                  IconButton(
                    tooltip: provider.t('ve.recPopOut'),
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 30, minHeight: 30),
                    icon: const Icon(Icons.open_in_new_rounded,
                        size: 16, color: Color(0xFF9575CD)),
                    onPressed: () => unawaited(_isDesktop
                        ? openScreenRecWindow()
                        : _popOutRecToOverlay(provider)),
                  ),
                  if (_isDesktop && _recStopHotkey.isNotEmpty) ...[
                    const SizedBox(width: 6),
                    Text(_recStopHotkey.toUpperCase(),
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 10)),
                  ],
                ] else ...[
                  // ── 待機中: 対象を選んで開始 ──
                  //    範囲指定は Windows だけ (Android の MediaProjection は
                  //    画面全体しか撮れない)。
                  if (_isDesktop) ...[
                    _recTargetChip(
                        provider,
                        'screen',
                        Icons.desktop_windows_rounded,
                        provider.t('ve.recTargetScreen')),
                    const SizedBox(width: 4),
                    _recTargetChip(provider, 'region', Icons.crop_rounded,
                        provider.t('ve.recTargetRegion')),
                    const SizedBox(width: 10),
                  ],
                  _recBarButton(
                    icon: Icons.fiber_manual_record_rounded,
                    label: provider.t('ve.recStart'),
                    color: const Color(0xFF9575CD),
                    onTap: () => unawaited(_recBarStart(provider)),
                  ),
                  // ── アプリの外へ出す ──
                  //    デスクトップは別ウィンドウ、 Android は他のアプリの
                  //    上に出せるオーバーレイ (= ユーザー要望: モバイルでも
                  //    録画ボタンを外に出せるように)。
                  const SizedBox(width: 2),
                  IconButton(
                    tooltip: provider.t('ve.recPopOut'),
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 30, minHeight: 30),
                    icon: const Icon(Icons.open_in_new_rounded,
                        size: 16, color: Color(0xFF9575CD)),
                    onPressed: () => unawaited(_isDesktop
                        ? openScreenRecWindow()
                        : _popOutRecToOverlay(provider)),
                  ),
                  // ── 保存先を選ぶのはデスクトップだけ (Android はアプリ
                  //    専用フォルダー固定)。 ──
                  if (_isDesktop) ...[
                    const SizedBox(width: 2),
                    IconButton(
                      tooltip: _recSaveDir.isEmpty
                          ? provider.t('ve.recSaveDirPick')
                          : '${provider.t('ve.recSaveDirPick')}\n$_recSaveDir',
                      padding: EdgeInsets.zero,
                      constraints:
                          const BoxConstraints(minWidth: 30, minHeight: 30),
                      icon: Icon(Icons.drive_file_move_outline,
                          size: 17,
                          color: _recSaveDir.isEmpty
                              ? Colors.white38
                              : const Color(0xFF9CCC65)),
                      onPressed: () => unawaited(_pickRecSaveDir(provider)),
                    ),
                  ],
                  const SizedBox(width: 2),
                  // ── 撮影後にプレビューを出すか (= ユーザー要望) ──
                  IconButton(
                    tooltip: provider.t('ve.recPreviewAfter'),
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 30, minHeight: 30),
                    icon: Icon(Icons.slideshow_rounded,
                        size: 17,
                        color: _recPreviewAfter
                            ? const Color(0xFF9CCC65)
                            : Colors.white38),
                    onPressed: () =>
                        unawaited(_setRecPreviewAfter(!_recPreviewAfter)),
                  ),
                  // ── 停止ショートカット / 保存先を開く: キーボードと
                  //    エクスプローラーが前提なのでデスクトップだけ。 ──
                  if (_isDesktop) ...[
                    const SizedBox(width: 2),
                    IconButton(
                      tooltip: _recStopHotkey.isEmpty
                          ? provider.t('ve.recHotkeyTitle')
                          : '${provider.t('ve.recHotkeyTitle')}\n'
                              '${_recStopHotkey.toUpperCase()}',
                      padding: EdgeInsets.zero,
                      constraints:
                          const BoxConstraints(minWidth: 30, minHeight: 30),
                      icon: Icon(Icons.keyboard_rounded,
                          size: 17,
                          color: _recStopHotkey.isEmpty
                              ? Colors.white38
                              : const Color(0xFF9575CD)),
                      onPressed: () =>
                          unawaited(_editRecStopHotkey(provider)),
                    ),
                    if (_recLastSaved != null) ...[
                      const SizedBox(width: 2),
                      IconButton(
                        tooltip: provider.t('ve.screenRecOpenFolder'),
                        padding: EdgeInsets.zero,
                        constraints:
                            const BoxConstraints(minWidth: 30, minHeight: 30),
                        icon: const Icon(Icons.folder_open_rounded,
                            size: 17, color: Color(0xFF9CCC65)),
                        onPressed: () {
                          try {
                            Process.run('explorer', [
                              '/select,',
                              _recLastSaved!.replaceAll('/', '\\')
                            ]);
                          } catch (_) {}
                        },
                      ),
                    ],
                  ],
                ],
                    ]),
                  ),
                ),
                const SizedBox(width: 2),
                IconButton(
                  tooltip: provider.t('btn.close'),
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints(minWidth: 28, minHeight: 28),
                  icon: const Icon(Icons.close_rounded,
                      size: 16, color: Colors.white38),
                  onPressed: () => setState(() => _recBarOpen = false),
                ),
              ]),
            ),
          ),
        ),
      ),
    );
  }

  Widget _recTargetChip(
      MindMapProvider provider, String id, IconData icon, String label) {
    final on = _recTarget == id;
    return InkWell(
      borderRadius: BorderRadius.circular(10),
      onTap: () => setState(() => _recTarget = id),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
        decoration: BoxDecoration(
          color: on ? const Color(0xFF39395C) : Colors.transparent,
          borderRadius: BorderRadius.circular(10),
          border: Border.all(
              color: on ? const Color(0xFF9575CD) : Colors.white24),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          Icon(icon, size: 13, color: on ? Colors.white : Colors.white54),
          const SizedBox(width: 5),
          Text(label,
              style: TextStyle(
                  color: on ? Colors.white : Colors.white54, fontSize: 11.5)),
        ]),
      ),
    );
  }

  Widget _recBarButton({
    required IconData icon,
    required String label,
    required Color color,
    required VoidCallback onTap,
  }) =>
      Material(
        color: color,
        borderRadius: BorderRadius.circular(11),
        child: InkWell(
          borderRadius: BorderRadius.circular(11),
          onTap: onTap,
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 11, vertical: 6),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              Icon(icon, size: 15, color: Colors.white),
              const SizedBox(width: 5),
              Text(label,
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 12,
                      fontWeight: FontWeight.w600)),
            ]),
          ),
        ),
      );

  /// [presetGiven] が true の時は範囲選びを行わず [preset] をそのまま使う
  /// (= 別窓の録画パネルが自分の窓の中で範囲を選んで渡してくる。
  ///  ユーザー要望: 範囲選びもプレビューも全部 1 つの窓の中で)。
  Future<void> _recBarStart(MindMapProvider provider,
      {ScreenRecRegion? preset, bool presetGiven = false}) async {
    // ── Android は OS の MediaProjection で画面全体を録る
    //    (= ユーザー要望: モバイル版でも画面録画に対応)。 ──
    if (Platform.isAndroid) {
      try {
        await ScreenRecorder.instance.startAndroid();
        // 外の窓へ状態を流し始める (= ユーザー要望: 外に出した窓で止める)。
        _startRecBridge();
        if (mounted) setState(() => _recLastSaved = null);
      } catch (e) {
        if (mounted) _screenRecSnack('$e', const Color(0xFFE57373));
      }
      return;
    }
    if (!Platform.isWindows) {
      _screenRecSnack(provider.t('ve.screenRecDesktopOnly'),
          const Color(0xFFFFB347));
      return;
    }
    final ff = await findFfmpegExe();
    if (!mounted) return;
    if (ff == null) {
      await _showFfmpegMissingSimple(provider);
      return;
    }
    ScreenRecRegion? region;
    if (presetGiven) {
      region = preset;
      if (region != null) _lastRecRegion = region;
    } else if (_recTarget == 'region') {
      final chosen = await _askRecRegion();
      if (chosen == null || !mounted) return; // 取り消し
      region = chosen.region;
      _lastRecRegion = region;
    }
    // ★ アプリ内のパネルから始める時は、 先に「録画に写らない別窓」 へ
    //   操作を移してから録り始める (= ユーザー報告: アプリの中から録ると
    //   停止ボタンが録画に写り込む)。 別窓は SetWindowDisplayAffinity で
    //   キャプチャから除外されている。
    if (_recWinId == null && _recBarOpen) {
      await openScreenRecWindow(autoOpened: true);
      if (!mounted) return;
    }
    try {
      await ScreenRecorder.instance.start(ff, region: region);
      if (mounted) {
        setState(() {
          _recLastSaved = null;
          _recActiveRegion = region; // 暗転に使う
        });
      }
      _pushScreenRecState();
      // ── 停止のグローバルホットキーを構える (= ユーザー要望: アプリの
      //    外にいても止められるように)。 窓は隠さず停止ボタンを出したまま
      //    (= ユーザー報告: ボタンが無いと止めにくい)。 ──
      await _armRecStopHotkey();
    } catch (e) {
      // 録れなかった時は、 出した別窓を片付けて操作を元の場所に戻す。
      await _closeAutoRecWin();
      if (mounted) _screenRecSnack('$e', const Color(0xFFE57373));
      _pushScreenRecState();
    }
  }

  /// 録画停止のショートカット (空 = 無効)。 prefs `screenRecStopHotkey`。
  String _recStopHotkey = 'ctrl+alt+r';
  static const String _kRecHotkeyKey = 'screenRecStopHotkey';

  /// 'ctrl+alt+r' のような文字列を (修飾キー, 仮想キーコード) にする。
  (int, int)? _parseRecHotkey(String s) {
    var mods = 0;
    int? vk;
    for (final raw in s.toLowerCase().split('+')) {
      final p = raw.trim();
      switch (p) {
        case '':
          break;
        case 'ctrl':
          mods |= 2; // MOD_CONTROL
          break;
        case 'alt':
          mods |= 1; // MOD_ALT
          break;
        case 'shift':
          mods |= 4; // MOD_SHIFT
          break;
        case 'win':
          mods |= 8; // MOD_WIN
          break;
        default:
          if (p.length == 1) {
            final c = p.toUpperCase().codeUnitAt(0);
            if ((c >= 0x30 && c <= 0x39) || (c >= 0x41 && c <= 0x5A)) {
              vk = c; // 数字と英字は文字コード = 仮想キーコード
            }
          } else if (p.startsWith('f')) {
            final n = int.tryParse(p.substring(1));
            if (n != null && n >= 1 && n <= 12) vk = 0x6F + n; // VK_F1=0x70
          }
      }
    }
    if (vk == null) return null;
    return (mods, vk);
  }

  /// 録画中だけホットキーを登録する (使っていない間は他のアプリの邪魔を
  /// しない)。
  Future<void> _armRecStopHotkey() async {
    if (!Platform.isWindows) return;
    final parsed = _parseRecHotkey(_recStopHotkey);
    if (parsed == null) {
      await RecStopHotkey.instance.stop();
      return;
    }
    RecStopHotkey.instance.onPressed = () {
      if (!mounted || !ScreenRecorder.instance.recording) return;
      unawaited(_recBarStop(context.read<MindMapProvider>()));
    };
    await RecStopHotkey.instance.start(parsed.$1, parsed.$2);
  }

  Future<void> _disarmRecStopHotkey() => RecStopHotkey.instance.stop();

  /// 停止ショートカットを設定する (= ユーザー要望: 設定できるように)。
  /// 使いたいキーをそのまま押してもらって覚える。
  Future<void> _editRecStopHotkey(MindMapProvider provider) async {
    var combo = _recStopHotkey;
    String? keyName(LogicalKeyboardKey k) {
      final label = k.keyLabel;
      if (label.length == 1 &&
          RegExp(r'[A-Za-z0-9]').hasMatch(label)) {
        return label.toLowerCase();
      }
      for (var i = 1; i <= 12; i++) {
        if (k == LogicalKeyboardKey(LogicalKeyboardKey.f1.keyId + i - 1)) {
          return 'f$i';
        }
      }
      return null;
    }

    final saved = await showDialog<String>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Text(provider.t('ve.recHotkeyTitle'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
          content: Focus(
            autofocus: true,
            onKeyEvent: (n, event) {
              if (event is! KeyDownEvent) return KeyEventResult.handled;
              final name = keyName(event.logicalKey);
              if (name == null) return KeyEventResult.handled;
              final mods = <String>[
                if (HardwareKeyboard.instance.isControlPressed) 'ctrl',
                if (HardwareKeyboard.instance.isAltPressed) 'alt',
                if (HardwareKeyboard.instance.isShiftPressed) 'shift',
              ];
              setD(() => combo = [...mods, name].join('+'));
              return KeyEventResult.handled;
            },
            child: SizedBox(
              width: 320,
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                Text(provider.t('ve.recHotkeyHint'),
                    style: const TextStyle(
                        color: Colors.white54, fontSize: 12)),
                const SizedBox(height: 12),
                Container(
                  width: double.infinity,
                  padding: const EdgeInsets.symmetric(vertical: 12),
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: Colors.white.withValues(alpha: 0.06),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(color: const Color(0xFF9575CD)),
                  ),
                  child: Text(
                      combo.isEmpty
                          ? provider.t('ve.recHotkeyNone')
                          : combo.toUpperCase(),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 16,
                          fontWeight: FontWeight.w700)),
                ),
              ]),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx, ''),
              child: Text(provider.t('ve.recHotkeyClear'),
                  style: const TextStyle(color: Color(0xFFE57373))),
            ),
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF9575CD),
                  foregroundColor: Colors.white),
              onPressed: () => Navigator.pop(dctx, combo),
              child: Text(provider.t('btn.save')),
            ),
          ],
        );
      }),
    );
    if (saved == null) return;
    setState(() => _recStopHotkey = saved);
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_kRecHotkeyKey, saved);
    } catch (_) {}
    _pushScreenRecState();
    // 録画中なら新しいキーで掛け直す。
    if (ScreenRecorder.instance.recording) await _armRecStopHotkey();
  }

  /// 録画が終わった後に録画窓を出し直す。 自動で出した窓なら片付けて
  /// 操作を元の場所 (アプリ内パネル) に戻す。
  Future<void> _showRecWinAgain() async {
    final id = _recWinId;
    if (id == null) return;
    if (_recWinAutoOpened) {
      await _closeAutoRecWin();
      return;
    }
    _recWinHidden = false;
    try {
      await WindowController.fromWindowId(id).show();
    } catch (_) {}
    _pushScreenRecState();
  }

  Future<void> _recBarStop(MindMapProvider provider) async {
    unawaited(_disarmRecStopHotkey());
    try {
      final path = await ScreenRecorder.instance.stop();
      if (!mounted) return;
      setState(() {
        _recLastSaved = path;
        _recActiveRegion = null;
      });
      _pushScreenRecState();
      // ビデオエディターを開いていれば、 そのままタイムラインへ載せる。
      final add = _veAddRecording;
      if (add != null) {
        add(path);
        _screenRecSnack(provider.t('ve.screenRecAdded'),
            const Color(0xFF43B97F));
        await _showRecWinAgain();
      } else if (_recPreviewAfter && _recWinId != null) {
        // ── プレビューも外の録画窓の中で出す (= ユーザー要望: 範囲選びも
        //    プレビューも全部 1 つの窓の中で完結させる) ──
        if (!await _sendPreviewToRecWin(path)) {
          await _closeAutoRecWin();
          unawaited(_showScreenRecPreview(path, provider));
        }
      } else if (_recPreviewAfter) {
        await _showRecWinAgain();
        // ── 撮り終わったらプレビューを出す (= ユーザー要望) ──
        unawaited(_showScreenRecPreview(path, provider));
      } else {
        _screenRecSnack('${provider.t('ve.screenRecSaved')}: $path',
            const Color(0xFF43B97F));
        await _showRecWinAgain();
      }
    } catch (e) {
      if (!mounted) return;
      setState(() => _recActiveRegion = null);
      await _showRecWinAgain();
      _screenRecSnack('${provider.t('ve.screenRecFailed')}: $e',
          const Color(0xFFE57373));
      _pushScreenRecState();
    }
  }

  /// 撮れた動画のプレビューを外の録画窓の中で出してもらう。
  /// 窓が閉じているなどで届かなければ false (呼び手が本体側で出す)。
  Future<bool> _sendPreviewToRecWin(String path) async {
    final id = _recWinId;
    if (id == null) return false;
    try {
      if (_recWinHidden) {
        // 隠してあった窓を出してそこで見せる (録画中の自動隠しを含む)。
        await WindowController.fromWindowId(id).show();
        _recWinHidden = false;
      }
      await DesktopMultiWindow.invokeMethod(id, 'recPreview', {'path': path});
      return true;
    } catch (_) {
      return false;
    }
  }

  /// 録画開始と同時に自動で出した別窓なら、 片付けて操作を元の場所へ戻す。
  ///
  /// ★ 窓は破棄せず隠すだけにする。 サブ窓のエンジン破棄 (close) は
  ///   動画再生 (fvp) を積んだ後だと本体の描画スレッドごと固まる事がある
  ///   (= ユーザー報告: プレビューを閉じて本体に戻るとフリーズ)。
  ///   次に使う時はそのまま出し直す (作り直しも不要になる)。
  Future<void> _closeAutoRecWin() async {
    final id = _recWinId;
    if (id == null || !_recWinAutoOpened) return;
    _recWinAutoOpened = false;
    _recWinHidden = true;
    try {
      await WindowController.fromWindowId(id).hide();
    } catch (_) {}
    if (mounted) setState(() => _recBarOpen = true);
  }

  /// 撮り終わった録画をその場で見せる (= ユーザー要望: プレビューを出すか
  /// 選べるように)。 別窓から止めた時に本体が後ろに居ると見えないので、
  /// 先に本体を前へ出す。
  Future<void> _showScreenRecPreview(
      String path, MindMapProvider provider) async {
    if (!mounted) return;
    try {
      await windowManager.show();
      await windowManager.focus();
    } catch (_) {}
    if (!mounted) return;
    await showDialog<void>(
      context: context,
      builder: (_) => _ScreenRecPreviewDialog(provider: provider, path: path),
    );
  }

  /// 今録っている範囲 (暗転に使う)。 null = 画面全体 or 録っていない。
  ScreenRecRegion? _recActiveRegion;

  /// 録っていない所を暗くする膜 (= ユーザー要望: 部分録画中は外を暗く)。
  ///
  /// アプリの窓の中だけを暗くする。 窓の外まで覆うには、 常に最前面の
  /// 透過ウィンドウを別に作る必要があるため、 ここでは窓の中に留めている
  /// (録画そのものは窓の外も含めて画面全体から切り取っている)。
  Widget _buildRecDimOverlay() {
    final r = _recActiveRegion;
    if (r == null || !ScreenRecorder.instance.recording) {
      return const SizedBox.shrink();
    }
    // 画面 (物理ピクセル) → このアプリの論理座標へ。
    final view = View.of(context);
    final dpr = view.devicePixelRatio;
    // 窓の左上が画面のどこにあるか。 Flutter からは直接取れないので、
    // 窓いっぱい = 画面いっぱいとみなして重ねる (最大化での利用が主)。
    final rect = Rect.fromLTWH(r.x / dpr, r.y / dpr, r.width / dpr,
        r.height / dpr);
    return Positioned.fill(
      child: IgnorePointer(
        child: CustomPaint(painter: _RecDimPainter(rect)),
      ),
    );
  }

  /// ビデオエディターが開いている間だけ入る「録れた動画の受け取り係」。
  void Function(String path)? _veAddRecording;

  /// クリップボードにある画像をバイト列で返す (無ければ null)。
  ///
  /// = ユーザー要望「Ctrl+V でプロンプト欄に画像を貼り付けたい」。
  ///   フラッシュカードの貼り付けと同じ super_clipboard の読み方を、
  ///   他からも使えるようにまとめたもの。
  Future<Uint8List?> readClipboardImageBytes() async {
    try {
      final clipboard = SystemClipboard.instance;
      if (clipboard == null) return null;
      final reader = await clipboard.read();
      const candidates = <FileFormat>[
        Formats.png,
        Formats.jpeg,
        Formats.gif,
        Formats.webp,
        Formats.bmp,
      ];
      for (final fmt in candidates) {
        if (!reader.canProvide(fmt)) continue;
        final bytes = await _readClipboardFileBytes(reader, fmt);
        if (bytes != null && bytes.isNotEmpty) return bytes;
      }
    } catch (_) {}
    return null;
  }

  /// 画面録画の操作パネルを出す (ビデオエディターのボタンからも呼ぶ)。
  void openScreenRecBar() {
    if (!mounted) return;
    setState(() => _recBarOpen = true);
  }

  /// 録画窓へ渡す今の様子。
  Map<String, dynamic> _screenRecStateMap() {
    final rec = ScreenRecorder.instance;
    return <String, dynamic>{
      'recording': rec.recording,
      'label': rec.label,
      'target': _recTarget,
      'saveDir': _recSaveDir,
      'lastSaved': _recLastSaved ?? '',
      'preview': _recPreviewAfter,
      'stopKey': _recStopHotkey,
    };
  }

  /// 開いている録画窓の id (null = 出していない)。
  int? _recWinId;

  /// 録画開始と同時に自動で出した窓か (止めたら片付けて元に戻すため)。
  bool _recWinAutoOpened = false;

  /// 録画窓を隠しているか (★破棄はしない — サブ窓のエンジン破棄が
  /// 本体ごと固まる事があるため、 隠して使い回す。
  /// = ユーザー報告: プレビューを閉じて戻るとフリーズ)。
  bool _recWinHidden = false;

  /// 今の様子を録画窓へ押し出す (窓から何度も聞きに来させない)。
  void _pushScreenRecState() {
    final id = _recWinId;
    if (id == null) return;
    try {
      unawaited(
          DesktopMultiWindow.invokeMethod(id, 'recState', _screenRecStateMap()));
    } catch (_) {}
  }

  /// 録画窓からの注文を処理する (受け口とは切り離して走らせる)。
  Future<void> _handleScreenRecCmd(String cmd, String value) async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    try {
      switch (cmd) {
        case 'target':
          if (mounted) {
            setState(() => _recTarget = value.isEmpty ? 'screen' : value);
          }
          break;
        case 'start':
          {
            // 別窓は範囲を自分の窓の中で選んで JSON で渡してくる
            // (= ユーザー要望: 範囲選びも 1 つの窓の中で)。
            ScreenRecRegion? preset;
            var presetGiven = false;
            if (value.trim().isNotEmpty) {
              try {
                final m = jsonDecode(value);
                if (m is Map) {
                  presetGiven = true;
                  preset = ScreenRecRegion.fromJson(
                      (m['region'] is Map) ? (m['region'] as Map) : null);
                }
              } catch (_) {}
            }
            await _recBarStart(provider,
                preset: preset, presetGiven: presetGiven);
          }
          break;
        case 'stop':
          await _recBarStop(provider);
          break;
        case 'previewClosed':
          // 窓の中のプレビューが閉じられた。 自動で出した窓なら片付ける。
          await _closeAutoRecWin();
          break;
        case 'pickDir':
          await _pickRecSaveDir(provider);
          break;
        case 'preview':
          await _setRecPreviewAfter(value == '1');
          break;
        case 'openFolder':
          final p = _recLastSaved;
          if (p != null) {
            try {
              Process.run('explorer', ['/select,', p.replaceAll('/', '\\')]);
            } catch (_) {}
          }
          break;
      }
    } catch (_) {}
    _pushScreenRecState();
  }

  /// 録画の操作を「アプリの外の小さな窓」 として出す (= ユーザー要望)。
  ///
  /// ★ この窓は録画に写り込まない。 Windows の
  ///   SetWindowDisplayAffinity(WDA_EXCLUDEFROMCAPTURE) を窓側で掛けており、
  ///   画面を取り込む側 (gdigrab) からは存在しないものとして扱われる。
  Future<void> openScreenRecWindow({bool autoOpened = false}) async {
    if (!_isDesktop) return;
    // アプリ内のパネルの近くに出す (= 目で追える位置に現れるように)。
    Future<Rect> barFrame() async {
      var frame = const Offset(120, 90) & const Size(440, 158);
      try {
        final b = await windowManager.getBounds();
        final p = _recBarPos ??
            (mounted
                ? Offset((MediaQuery.sizeOf(context).width - 360) / 2, 74)
                : const Offset(120, 90));
        frame = Offset(b.left + p.dx, b.top + p.dy) & const Size(440, 158);
      } catch (_) {}
      return frame;
    }

    // ── 前に作った窓が残っていれば使い回す (破棄すると本体ごと固まる
    //    事があるため、 隠してあるだけ) ──
    final existing = _recWinId;
    if (existing != null) {
      try {
        final win = WindowController.fromWindowId(existing);
        await win.setFrame(await barFrame());
        await win.show();
        _recWinHidden = false;
        _recWinAutoOpened = autoOpened;
        if (mounted) setState(() => _recBarOpen = false);
        _pushScreenRecState();
        return;
      } catch (_) {
        // 使い回せない (本当に閉じられていた) → 作り直す。
        _recWinId = null;
        _recWinHidden = false;
      }
    }
    try {
      final win = await DesktopMultiWindow.createWindow(
          jsonEncode({'kind': 'screenrec'}));
      _recWinId = win.windowId;
      _recWinAutoOpened = autoOpened;
      _recWinHidden = false;
      await win.setFrame(await barFrame());
      await win.setTitle('HisatorNotebook Rec');
      await win.show();
      if (mounted) setState(() => _recBarOpen = false);
      // 開いた直後の様子を 1 回渡す (以後は変化のたびに押し出す)。
      Future<void>.delayed(const Duration(milliseconds: 500),
          _pushScreenRecState);
    } catch (e) {
      _recWinId = null;
      _recWinAutoOpened = false;
      if (mounted) _screenRecSnack('$e', const Color(0xFFE57373));
    }
  }


  /// アプリの機能ボタンと文書ファイル作成を MCP へ預ける。
  ///
  /// 実行はどちらも画面側でしかできないので、 画面から渡す必要がある。
  /// ★ 以前は AI アシスタントを開いた時だけ登録していたため、 一度も
  ///   開かずに MCP を呼ぶと list_app_commands が空、 create_document_file が
  ///   「作れません」 になっていた (= 動作確認で判明)。 起動時にも登録する。
  void _registerMcpHandlers(MindMapProvider provider) {
    provider.registerMcpCommands(
      [
        for (final c in _headerCustomizableCommands)
          {
            'id': '${c['id']}',
            'label': provider.t('${c['labelKey']}'),
          }
      ],
      (id) => _executeHeaderCommand(id, provider),
    );
    provider.registerMcpFileBuilder(_buildMcpFile);
    // 画面の中の会話だけでなく、 prefs の控えも消す (= 動作確認で判明:
    //   控えが残っていたので、 開き直すと消したはずの会話が戻っていた)。
    //   今頼まれている用件は残す仕様なので、 残った分を控えにも書き戻す。
    provider.registerMcpChatClearer(() {
      final s = _McpChatSession.instance;
      s.clearHistory();
      unawaited(provider.clearMcpChatHistory(keep: [
        for (final m in s.msgs)
          if (m.role == 'user' || m.role == 'ai')
            {
              'role': m.role,
              'text': m.text,
              'at': DateTime.now().millisecondsSinceEpoch,
            }
      ]));
    });
  }

  /// AI アシスタントを閉じている間だけ出す、 小さな「処理中 / 停止」 の札。
  ///
  /// = ユーザー要望「処理中に画面を閉じたら、 処理中と止めるボタンを小さく
  ///   表示しておいて欲しい」。 会話は画面の外 (_McpChatSession) が持って
  ///   いるので、 閉じていても進み具合が分かる。 札を押すと開き直す。
  Widget _buildAiBusyChip(MindMapProvider provider) {
    final session = _McpChatSession.instance;
    return AnimatedBuilder(
      animation: session,
      builder: (_, __) {
        // 開いている間はチャット欄の中に出ているので、 札は出さない。
        if (!session.busy || _mcpChatVisible) return const SizedBox.shrink();
        return Positioned(
          right: 12,
          bottom: 96,
          child: Material(
            color: Colors.transparent,
            child: Container(
              padding: const EdgeInsets.fromLTRB(10, 6, 6, 6),
              decoration: BoxDecoration(
                color: const Color(0xFF23233C),
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: const Color(0xFF43B97F), width: 1),
                boxShadow: const [
                  BoxShadow(
                      color: Colors.black54,
                      blurRadius: 8,
                      offset: Offset(0, 2)),
                ],
              ),
              child: Row(mainAxisSize: MainAxisSize.min, children: [
                InkWell(
                  borderRadius: BorderRadius.circular(14),
                  // 押すとアシスタントを開き直す (= 続きが見える)。
                  onTap: () => unawaited(_openMcpChat(provider)),
                  child: Padding(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 4, vertical: 2),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      const SizedBox(
                          width: 13,
                          height: 13,
                          child: CircularProgressIndicator(
                              strokeWidth: 2, color: Color(0xFF43B97F))),
                      const SizedBox(width: 7),
                      Text(
                          '${provider.t('mcp.busyChip')}'
                          '${session.step > 0 ? ' ${session.step}' : ''}',
                          style: const TextStyle(
                              color: Colors.white70, fontSize: 11.5)),
                    ]),
                  ),
                ),
                const SizedBox(width: 4),
                InkWell(
                  borderRadius: BorderRadius.circular(14),
                  onTap: session.canceling ? null : session.stop,
                  child: Padding(
                    padding: const EdgeInsets.all(3),
                    child: Icon(Icons.stop_circle_outlined,
                        size: 18,
                        color: session.canceling
                            ? Colors.white24
                            : const Color(0xFFE57373)),
                  ),
                ),
              ]),
            ),
          ),
        );
      },
    );
  }

  /// AI アシスタントの画面を今出しているか (札を二重に出さないため)。
  bool _mcpChatVisible = false;

  Future<void> _openMcpChat(MindMapProvider provider,
      {String? initialTask, bool floatingPanel = false}) async {
    if (!provider.mcpServerEnabled) {
      await provider.setMcpServerEnabled(true);
    }
    _registerMcpHandlers(provider);
    if (!mounted) return;
    // ── 「開き方」 が分割なら、 ペインの中に出す (= ユーザー要望: AI
    //    アシスタントの画面自体を左右分割で出せるように) ──
    // お題つき (新規ページ作成など) はダイアログのまま。 ペインは常設の
    //   作業場所として使う想定なので、 その場限りの用件と混ぜない。
    if (_isDesktop && !floatingPanel && initialTask == null) {
      try {
        await _commandOpenStylesReady;
      } catch (_) {}
      if (!mounted) return;
      final style = _openStyleOf('aiAssistant');
      if (style == 'splitLeft' || style == 'splitRight') {
        if (!_mapSplitOpen) {
          await _applyMapSplitMode(panes: 2, stacked: false);
          if (!mounted) return;
        }
        if (_mapSplitOpen) {
          final slot = style == 'splitLeft' ? 0 : _primaryViewerSlot();
          if (_mapSplitCellTool[slot] == 'aiAssistant') {
            setState(() {
              _mapSplitCellTool.remove(slot);
              _syncNarrowPaneRatio();
            });
          } else {
            _embedToolIntoSlot(slot, 'aiAssistant');
          }
          return;
        }
      } else if (style == 'floating') {
        // ignore: discarded_futures
        _openMcpChat(provider, floatingPanel: true);
        return;
      }
    }
    Widget chat(BuildContext _) => _McpChatDialog(
          provider: provider,
          onOpenAiSettings: () =>
              _showGeminiKeyDialog(context, provider, null, anyProvider: true),
          extractFileText: _extractAttachmentTextForAi,
          initialTask: initialTask,
          floatingPanel: floatingPanel,
          // ブラウザ版 AI を呼ぶ (= ユーザー要望: 右上のアシスタントからも)。
          //   「AI」 ボタンと同じ開き方の設定に従う。
          onOpenBrowserAi: (url) {
            if (_openStyleOf('openAi') == 'floating' && _isDesktop) {
              openExternalWebWindow(url, embeddable: true);
              return;
            }
            _openUrlInSplitPanel(url);
          },
          // 浮かせ直す口は廃止 (= ユーザー要望: アプリの中だけで使う)。
        );
    // ── フローティング経由なら、 全画面ではなく小さな浮遊窓で開く
    //    (= ユーザー要望: AI アシスタントもフローティング画面で) ──
    if (floatingPanel && _isDesktop) {
      final done = Completer<void>();
      _showFloatingPanelWindow(
        chat,
        width: 520,
        height: 700,
        memoryKey: 'assistant',
        // アプリの外へ出す (= ユーザー要望)。 アシスタントは Web ページでは
        //   ないので、 別プロセスの Web 窓ではなくサブ窓に会話だけを映す。
        //   考える所 (_McpChatSession) は本体に残したまま動かす。
        popOutCustom: (frame, pinned) =>
            openAssistantWindow(provider, frame: frame, pinned: pinned),
        onClosed: () {
          if (!done.isCompleted) done.complete();
        },
      );
      // 開いている間は小さな札を出さない (= 二重表示を避ける)。
      if (mounted) setState(() => _mcpChatVisible = true);
      await done.future;
      if (mounted) setState(() => _mcpChatVisible = false);
      return;
    }
    if (mounted) setState(() => _mcpChatVisible = true);
    await showDialog<void>(context: context, builder: chat);
    if (mounted) setState(() => _mcpChatVisible = false);
  }

  // ─────────── AI アシスタントをアプリの外の窓へ出す (= ユーザー要望) ───────────
  //
  // アシスタントは Web ページではないので、 別プロセスの Web 窓には載せられない。
  // かわりに desktop_multi_window のサブ窓に**会話の画面だけ**を出し、
  // 考える所 (_McpChatSession) は本体に残す。 サブ窓は
  //   ・入力 → 本体へ 'assistCmd' で送る
  //   ・本体 → 変化のたびに 'assistState' を押し出す
  // というやり取りだけを持つ。 こうすればページの書き換えは今まで通り本体が行う。

  /// 開いているアシスタント窓の id (null = 出していない)。
  int? _assistWinId;

  /// 会話の変化を窓へ流すための購読 (窓を閉じたら外す)。
  VoidCallback? _assistListener;

  /// 今の会話の様子を JSON にする (窓へ渡す形)。
  Map<String, String> _assistantStateMap(MindMapProvider provider) {
    final s = _McpChatSession.instance;
    return {
      'json': jsonEncode({
        'msgs': [
          for (final m in s.msgs)
            {'role': m.role, 'text': m.text},
        ],
        'busy': s.busy,
        'canceling': s.canceling,
        'step': s.step,
        'maxRounds': _McpChatSession.maxRounds,
        'model': provider.relayModel,
        'balance': aiRemainText(provider),
      }),
    };
  }

  void _pushAssistantState() {
    final id = _assistWinId;
    if (id == null || !mounted) return;
    try {
      unawaited(DesktopMultiWindow.invokeMethod(
          id, 'assistState', _assistantStateMap(context.read<MindMapProvider>())));
    } catch (_) {}
  }

  /// アシスタント窓からの注文 (送信 / 停止)。
  Future<void> _handleAssistantCmd(String cmd, String value) async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final session = _McpChatSession.instance;
    session.bind(provider);
    try {
      switch (cmd) {
        case 'send':
          final text = value.trim();
          if (text.isEmpty || session.busy) break;
          _registerMcpHandlers(provider);
          await session.run(shown: text, raw: text);
          break;
        case 'stop':
          session.stop();
          break;
      }
    } catch (_) {}
    _pushAssistantState();
  }

  /// アシスタントを「アプリの外の窓」 として出す。
  Future<bool> openAssistantWindow(MindMapProvider provider,
      {Rect? frame, bool pinned = false}) async {
    if (!_isDesktop) return false;
    final session = _McpChatSession.instance;
    session.bind(provider);
    _registerMcpHandlers(provider);
    // 既に出ているなら、 その窓を前に出すだけ。
    final existing = _assistWinId;
    if (existing != null) {
      try {
        final win = WindowController.fromWindowId(existing);
        if (frame != null) await win.setFrame(frame);
        await win.show();
        _pushAssistantState();
        return true;
      } catch (_) {
        _assistWinId = null;
      }
    }
    try {
      final win = await DesktopMultiWindow.createWindow(
          jsonEncode({'kind': 'assistant', 'pinned': pinned}));
      _assistWinId = win.windowId;
      await win.setFrame(frame ?? const Rect.fromLTWH(120, 90, 520, 700));
      await win.setTitle('HisatorNotebook AI');
      await win.show();
      // 会話が動いたら押し出す (窓から何度も聞きに来させない)。
      _assistListener?.call();
      void listener() => _pushAssistantState();
      session.addListener(listener);
      _assistListener = () => session.removeListener(listener);
      Future<void>.delayed(
          const Duration(milliseconds: 400), _pushAssistantState);
      return true;
    } catch (e) {
      _assistWinId = null;
      debugPrint('アシスタント窓を開けませんでした: $e');
      return false;
    }
  }

  /// AI (MCP) から頼まれた文書ファイルを作って保存し、 ページに貼る。
  /// 出来たファイルのパスを返す。 失敗したら null。
  Future<String?> _buildMcpFile(Map<String, dynamic> spec) async {
    try {
      final provider = context.read<MindMapProvider>();
      final kind = '${spec['kind'] ?? ''}'.toLowerCase();
      const known = {'xlsx', 'csv', 'docx', 'pptx', 'pdf', 'txt', 'md'};
      if (!known.contains(kind)) return null;

      final rows = <List<String>>[
        for (final r in (spec['rows'] as List? ?? const []))
          [for (final c in (r as List? ?? const [])) '$c']
      ];
      final paragraphs = <String>[
        for (final p in (spec['paragraphs'] as List? ?? const [])) '$p'
      ];
      final slides = <({String title, List<String> bullets})>[
        for (final sl in (spec['slides'] as List? ?? const []))
          if (sl is Map)
            (
              title: '${sl['title'] ?? ''}',
              bullets: <String>[
                for (final b in (sl['bullets'] as List? ?? const [])) '$b'
              ],
            )
      ];
      final title = '${spec['title'] ?? ''}';

      final bytes = await _OfficeFileTemplate.buildWithContent(
        kind,
        rows: rows.isEmpty ? null : rows,
        paragraphs: paragraphs.isEmpty ? null : paragraphs,
        slides: slides.isEmpty ? null : slides,
        title: title.isEmpty ? null : title,
      );

      // 保存先はアプリの書類フォルダ。 名前が無ければ見出しか日時から作る。
      var name = '${spec['fileName'] ?? ''}'.trim();
      if (name.isEmpty) {
        final base = title.isNotEmpty
            ? title
            : '${provider.t('mcp.fileDefaultName')}'
                '_${DateTime.now().millisecondsSinceEpoch}';
        name = base;
      }
      name = name.replaceAll(RegExp(r'[\\/:*?"<>|]'), '_');
      if (!name.toLowerCase().endsWith('.$kind')) name = '$name.$kind';

      final docs = await getApplicationDocumentsDirectory();
      final dir = Directory('${docs.path}/mcp_files');
      await dir.create(recursive: true);
      final file = File('${dir.path}/$name');
      await file.writeAsBytes(bytes, flush: true);

      // 作ったファイルはページに貼って、 そのまま開けるようにする。
      final pageId = '${spec['pageId'] ?? ''}';
      provider.mcpAddFileNode(pageId, file.path,
          title: title.isEmpty ? null : title);
      return file.path;
    } catch (e, st) {
      // 握りつぶすと「作れませんでした」 としか出ず原因が追えないので、
      //   理由をそのまま上へ返す (チャットに理由が出る)。
      debugPrint('MCP からのファイル作成に失敗: $e\n$st');
      rethrow;
    }
  }

  Widget _buildHeaderCustomizeIcon(MindMapProvider provider) {
    return IconButton(
      // 格子アイコンは 4 分割ボタンと紛らわしかったので、 元のつまみアイコンに
      //   戻す (= ユーザー要望)。 紛らわしかった「動作設定」 の常設ボタンは
      //   隣から外したので、 これで混同しない。
      icon: const Icon(Icons.tune_rounded, color: Colors.white70, size: 20),
      tooltip: provider.t('menu.customizeHeader'),
      padding: EdgeInsets.zero,
      constraints: const BoxConstraints.tightFor(
        width: _kHeaderCustomButtonExtent,
        height: _kHeaderCustomButtonExtent,
      ),
      onPressed: () => _showHeaderCustomizeSheet(context, provider),
    );
  }

  int _bottomBarRowCount(MindMapProvider provider) =>
      provider.bottomFourthRowEnabled
          ? 4
          : provider.bottomThirdRowEnabled
              ? 3
              : 2;

  String _bottomBarRowLabel(MindMapProvider provider, int rows) {
    switch (rows) {
      case 4:
        return provider.t('settings.bottomRows4');
      case 3:
        return provider.t('settings.bottomRows3');
      default:
        return provider.t('settings.bottomRows2');
    }
  }

  Future<void> _setBottomBarRows(MindMapProvider provider, int rows) async {
    final next = rows.clamp(2, 4).toInt();
    await provider.setBottomThirdRowEnabled(next >= 3);
    await provider.setBottomFourthRowEnabled(next >= 4);
  }

  Future<void> _showBottomRowsPicker(MindMapProvider provider) async {
    final current = _bottomBarRowCount(provider);
    final selected = await showModalBottomSheet<int>(
      context: context,
      backgroundColor: const Color(0xFF1E1E32),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetCtx) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(20, 16, 12, 8),
              child: Row(children: [
                const Icon(Icons.view_agenda_rounded,
                    color: Color(0xFFBA68C8), size: 20),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(
                    provider.t('settings.bottomRowsTitle'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 16,
                        fontWeight: FontWeight.w700),
                  ),
                ),
                IconButton(
                  icon: const Icon(Icons.close_rounded, color: Colors.white54),
                  onPressed: () => Navigator.of(sheetCtx).pop(),
                ),
              ]),
            ),
            for (final rows in const [2, 3, 4])
              ListTile(
                leading: Icon(
                  rows == current
                      ? Icons.radio_button_checked_rounded
                      : Icons.radio_button_unchecked_rounded,
                  color: rows == current
                      ? const Color(0xFFBA68C8)
                      : Colors.white38,
                ),
                title: Text(
                  _bottomBarRowLabel(provider, rows),
                  style: const TextStyle(color: Colors.white),
                ),
                onTap: () => Navigator.of(sheetCtx).pop(rows),
              ),
            const SizedBox(height: 8),
          ],
        ),
      ),
    );
    if (selected == null || selected == current) return;
    await _setBottomBarRows(provider, selected);
  }

  // ─── AppBar ──────────────────────────────────────────────────────────────

  PreferredSizeWidget _buildAppBar(
      BuildContext context, MindMapProvider provider) {
    final isRangeMode = _rangeSelectMode;
    // 図形 (折れ線・四角など) だけを選んでいる時も「〜個選択中」 と出す
    // (= ユーザー報告: 全選択で図形をまとめて削除できない)。
    final hasRangeSelection =
        _rangeSelectedIds.isNotEmpty || _rangeSelectedDecorationIds.isNotEmpty;
    // ── モバイルでマークダウンを開いている間は、 ヘッダーのボタン列を
    //    出さない (= ユーザー要望: 表示領域が限られているので、 その場所は
    //    マークダウン側の AI アシスタント等の道具に譲る)。 ──
    final showMobileHeaderTray =
        !_isDesktop && provider.currentPage.pageType != 'markdown';

    return AppBar(
      backgroundColor: provider.headerColor,
      elevation: 0,
      bottom: showMobileHeaderTray && _mobileHeaderCustomOpen
          ? PreferredSize(
              preferredSize: const Size.fromHeight(_kHeaderCustomBarHeight),
              child: Container(
                height: _kHeaderCustomBarHeight,
                width: double.infinity,
                decoration: BoxDecoration(
                  color: Color.alphaBlend(
                    provider.headerColor.withValues(
                        alpha: provider.hasCustomHeaderColor ? 0.82 : 0.0),
                    const Color(0xFF151522),
                  ),
                  border: Border(
                    top:
                        BorderSide(color: Colors.white.withValues(alpha: 0.08)),
                  ),
                ),
                child: _HeaderCustomButtonsBar(
                  provider: provider,
                  buildButton: _buildCustomHeaderButton,
                  // カスタマイズ画面が編集する共通リストを全ページで表示する。
                  // 旧実装はギャラリーだけ別リストを読んでいたため、追加した
                  // 「戻る/進む」等が通常マップにだけ現れていた。
                  buttonIds: null,
                  reorderMode: _reorderHeaderMode,
                  fullWidth: true,
                  trailing: const SizedBox.shrink(),
                  onReorder: _reorderHeaderMode
                      ? (oldIndex, newIndex) {
                          final int adjustedNew =
                              newIndex > oldIndex ? newIndex + 1 : newIndex;
                          provider.reorderHeaderButtons(oldIndex, adjustedNew);
                        }
                      : null,
                ),
              ),
            )
          : null,
      // ── ヘッダーの空き領域 (ページ名・ボタン以外) をクリックでカスタマイズ ──
      // ユーザー要望: 「ページ名の所をクリックしたらページ名 (変更)、 それ以外の
      //   何もないヘッダーの箇所をクリックしたらカスタムボタン変更画面」。
      //   flexibleSpace はツールバー背面全体を占めるので、 タイトル (ページ名) や
      //   ボタンの無い余白をタップ/右クリックすると反応する。 ページ名・ボタンは
      //   前面の opaque な GestureDetector / IconButton が消費するのでここには
      //   届かない (= 役割が綺麗に分かれる)。 左クリックでもカスタマイズを開ける
      //   ようにして、 副ボタンの無いモバイルでも操作できるようにする。
      flexibleSpace: Stack(
        fit: StackFit.expand,
        children: [
          Positioned.fill(
            child: GestureDetector(
              behavior: HitTestBehavior.translucent,
              onTap: () => _showHeaderCustomizeSheet(context, provider),
              onSecondaryTap: () =>
                  _showHeaderCustomizeSheet(context, provider),
              child: const SizedBox.expand(),
            ),
          ),
          // AppBar.title の幅は右側アクション数で変わるため、そこを基準に
          // 中央配置するとギャラリー固有ボタンの有無で列全体が左右へ動く。
          // flexibleSpace の画面幅を基準にし、全ページで同じ中心・高さを使う。
          if (_isDesktop &&
              _moveModeNodeId == null &&
              !isRangeMode &&
              !_editingMapName)
            Align(
              alignment: Alignment.bottomCenter,
              child: SizedBox(
                // AppBar の標準 toolbarHeight (56) の中央に48pxバーを置く。
                // bottomへ48pxを直置きすると他のAppBarアイコンより4px下がる。
                height: kToolbarHeight,
                child: LayoutBuilder(builder: (barContext, constraints) {
                  final width = constraints.maxWidth;
                  final maxBarWidth = width < 96.0
                      ? width
                      : math.max(
                          96.0,
                          width - _kDesktopHeaderSideReserve * 2,
                        );
                  return Center(
                    child: _buildHeaderMiddleCustomButtons(
                      provider,
                      maxWidth: maxBarWidth,
                    ),
                  );
                }),
              ),
            ),
        ],
      ),
      automaticallyImplyLeading: _moveModeNodeId == null && !isRangeMode,
      leading: _moveModeNodeId != null
          ? null
          : isRangeMode
              ? IconButton(
                  icon: const Icon(Icons.close, color: Colors.white70),
                  onPressed: () {
                    setState(() {
                      _rangeSelectMode = false;
                      _rangeSelectedIds.clear();
                      _rangeSelectedDecorationIds.clear();
                      _rangeStart = null;
                      _rangeEnd = null;
                    });
                  },
                )
              : Builder(
                  builder: (ctx) => IconButton(
                    icon: const Icon(Icons.menu, color: Colors.white70),
                    onPressed: () => Scaffold.of(ctx).openDrawer(),
                  ),
                ),
      title: GestureDetector(
        // ── ヘッダーの何もない所 (ページ名の領域) を右クリック ──
        // ユーザー要望: 「カスタムボタンの入れ替えはヘッダーの何もない所を
        //   右クリックすると出てくるようにして」。 デスクトップのみ反応
        //   (モバイルには副ボタンが無いので onSecondaryTap は発火しない)。
        behavior: HitTestBehavior.deferToChild,
        // ── ヘッダーのページ名をタップ → その場 (ヘッダー上) で直接編集 (= ユーザー
        //    要望:「マップ名が記載されている所をクリックしたらそのまま名前を編集
        //    できるように」。 以前は改名ダイアログを開いていたが、 インラインの
        //    TextField に置き換えた)。 何もないヘッダーの箇所 (右クリック) は
        //    カスタムボタン変更画面。 範囲選択中・移動中・編集中はタイトルが
        //    別表示なので無効。 ──
        onTap: null,
        onSecondaryTap: null,
        // ── 長押しでヘッダーの色を変更 (= ユーザー要望: ヘッダーの色を
        //   カスタマイズできる機能。 デスクトップ/モバイル両方で反応) ──
        onLongPress: null,
        child: _moveModeNodeId != null
            ? Row(children: [
                const Icon(Icons.open_with_rounded,
                    color: Colors.orangeAccent, size: 18),
                const SizedBox(width: 8),
                Text(provider.t('shape.dragMoveConnect'),
                    style: const TextStyle(
                        color: Colors.orangeAccent,
                        fontSize: 15,
                        fontWeight: FontWeight.w600)),
              ])
            : isRangeMode
                ? Text(
                    hasRangeSelection
                        ? provider.t('range.countSelected').replaceAll(
                            '{n}',
                            '${_rangeSelectedIds.length + _rangeSelectedDecorationIds.length}')
                        : provider.t('range.selectNodes'),
                    style: const TextStyle(
                        color: Color(0xFF4FC3F7),
                        fontSize: 15,
                        fontWeight: FontWeight.w600))
                // ページ名はページ種別を問わずタイトル (= ヘッダー左端) に出す
                //   (= ユーザー要望: ページ名が右端なのを左端へ)。 GestureDetector
                //   の子をテキスト幅ぴったりに保つため ConstrainedBox で上限を
                //   設ける (空きヘッダー部分のタップは背面 flexibleSpace に流れて
                //   カスタムボタン変更画面が開く)。
                : _editingMapName
                    // ── インライン編集中: その場で名前を打ち替えられる TextField。
                    //    Enter / 他をタップで確定 (= ユーザー要望: そのまま編集)。 ──
                    ? ConstrainedBox(
                        constraints: const BoxConstraints(maxWidth: 260),
                        child: SizedBox(
                          height: 40,
                          child: TextField(
                            controller: _mapNameEditCtrl,
                            autofocus: true,
                            maxLines: 1,
                            textInputAction: TextInputAction.done,
                            cursorColor: const Color(0xFF6C63FF),
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 17,
                                fontWeight: FontWeight.bold),
                            decoration: const InputDecoration(
                              isDense: true,
                              contentPadding: EdgeInsets.symmetric(vertical: 8),
                              enabledBorder: UnderlineInputBorder(
                                  borderSide:
                                      BorderSide(color: Colors.white24)),
                              focusedBorder: UnderlineInputBorder(
                                  borderSide:
                                      BorderSide(color: Color(0xFF6C63FF))),
                            ),
                            onSubmitted: (_) => _commitInlineMapNameEdit(),
                            onTapOutside: (_) => _commitInlineMapNameEdit(),
                          ),
                        ),
                      )
                    : LayoutBuilder(
                        builder: (titleCtx, constraints) => SizedBox(
                          width: constraints.maxWidth,
                          height: _kHeaderCustomBarHeight,
                          child: Stack(
                            alignment: Alignment.center,
                            children: [
                              Align(
                                alignment: Alignment.centerLeft,
                                child: Row(
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    Flexible(
                                      child: ConstrainedBox(
                                        constraints:
                                            const BoxConstraints(maxWidth: 260),
                                        child: GestureDetector(
                                          behavior:
                                              HitTestBehavior.deferToChild,
                                          onTap: (_moveModeNodeId != null ||
                                                  isRangeMode ||
                                                  _editingMapName)
                                              ? null
                                              : _beginInlineMapNameEdit,
                                          onSecondaryTap: _editingMapName
                                              ? null
                                              : () =>
                                                  _showHeaderCustomizeSheet(
                                                      context, provider),
                                          onLongPress: _editingMapName
                                              ? null
                                              : () => _showHeaderColorPicker(
                                                  provider),
                                          child: Text(
                                              provider.currentPage.name,
                                              maxLines: 1,
                                              overflow: TextOverflow.ellipsis,
                                              style: const TextStyle(
                                                  color: Colors.white,
                                                  fontSize: 17,
                                                  fontWeight:
                                                      FontWeight.bold)),
                                        ),
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                              Align(
                                alignment: Alignment.centerRight,
                                child: Row(
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    // ── 共同編集の参加者 (= ユーザー要望:
                                    //    どのユーザーが操作しているか) ──
                                    // 共有している当のページを開いている時
                                    // だけ出す (= ユーザー要望: 共有して
                                    // いないページでは表示しない)。
                                    if (provider.liveActive &&
                                        provider.livePageId ==
                                            provider.currentPage.id)
                                      _buildLivePeerChips(provider),
                                    // ── 分割モードのボタン ──
                                    // デスクトップは常設 (= ユーザー要望:
                                    // 4 画面 / 左右 / 上下 の 3 つを並べる)。
                                    // モバイルはヘッダーが狭いので常駐させず、
                                    // カスタムボタンとして置いてもらう
                                    // (= ユーザー要望)。
                                    if (_isDesktop &&
                                        _splitEligiblePage(
                                            provider.currentPage))
                                      _buildMapSplitModeButtons(provider),
                                    // ── 動作設定は常設しない (= ユーザー要望) ──
                                    //   カスタムボタン (ヘッダーのボタン一覧
                                    //   から配置) と Ctrl+J で開けるので、
                                    //   右上に固定で置く必要はない。
                                    if (_isDesktop)
                                      const SizedBox.shrink(),
                                  ],
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
      ),
      actions: [
        // 注: 下部ボタンの格納はカスタムボタン (toggleBottomBar) として
        //   配置できるので、 ヘッダーには常設しない (= ユーザー要望)。
        if (showMobileHeaderTray)
          IconButton(
            icon: Icon(
              _mobileHeaderCustomOpen
                  ? Icons.keyboard_arrow_up_rounded
                  : Icons.apps_rounded,
              color: Colors.white70,
              size: 21,
            ),
            tooltip: provider.t('menu.customizeHeader'),
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 36, minHeight: 36),
            onPressed: () => setState(
                () => _mobileHeaderCustomOpen = !_mobileHeaderCustomOpen),
          ),
        // ── 横スクロール可能なツールバー ──
        // ボタン数が画面幅を超えた時、 横スワイプで隠れたボタンが流れて
        // 出てくるようにする (ユーザー要望「ヘッダーが入り切らなくなったら
        // スワイプしたら流れて出てくるようにして」)。
        SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          physics: const ClampingScrollPhysics(),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              // ── サブマップ履歴: 戻る / 進む ──
              // ノードに埋め込まれたサブマップを開くと _navHistory に push
              // され、 ここに戻る/進むボタンが現れる。 通常マップ (= 一度も
              // サブマップに飛んでいない状態) では両ボタンとも非表示。
              if (_navActiveForCurrent(provider) && _navIndex > 0)
                IconButton(
                  icon: const Icon(Icons.arrow_back_ios_new_rounded,
                      color: Colors.white70, size: 18),
                  tooltip: provider.t('split.back'),
                  padding: _isDesktop ? null : EdgeInsets.zero,
                  constraints: _isDesktop
                      ? null
                      : const BoxConstraints(minWidth: 36, minHeight: 36),
                  onPressed: _navigateBack,
                ),
              if (_navActiveForCurrent(provider) &&
                  _navIndex < _navHistory.length - 1)
                IconButton(
                  icon: const Icon(Icons.arrow_forward_ios_rounded,
                      color: Colors.white70, size: 18),
                  tooltip: provider.t('split.forward'),
                  padding: _isDesktop ? null : EdgeInsets.zero,
                  constraints: _isDesktop
                      ? null
                      : const BoxConstraints(minWidth: 36, minHeight: 36),
                  onPressed: _navigateForward,
                ),
              // ── 画面分割ボタンはヘッダーから削除 ──
              // ユーザー要望: 「左画面分割、 右画面分割はカスタムボタンとして
              // 割り当てるのではなく、 マップ上から PDF を開いた際にショートカット
              // キーやボタンを押した時だけ機能するようにして欲しい」。
              // → ヘッダーには出さず、 フルスクリーン PDF 内のボタンと
              //   Ctrl+\ / Ctrl+^ ショートカットからのみアクセス可能。

              if (_moveModeNodeId != null)
                TextButton(
                  onPressed: _resetInteractionState,
                  child: Text(provider.t('common.done'),
                      style: const TextStyle(
                          color: Colors.orangeAccent,
                          fontSize: 15,
                          fontWeight: FontWeight.w600)),
                )
              else if (isRangeMode) ...[
                // ── 範囲選択中の一括操作ボタン列 (右上) は削除しました (2026-07)。
                //    (= ユーザー要望: 選択範囲の上に出るメニューと項目が重複して
                //    いるので、 選択範囲上部のメニューだけに統一する)。
                //    複製 / 一括DL も _MultiNodeActionOverlay 側へ移設済み。
                // 範囲選択モードの「完了」ボタンは削除しました (2026-05)。
                // モバイルでヘッダーがオーバーフローしていたため、空エリアタップ /
                // Esc キー / 戻るジェスチャーで抜ける運用に変更しています。
              ] else ...[
                // ── ギャラリー(と同じ)ヘッダーボタン ──
                // ユーザー要望: マインドマップ (normal) 以外のページ
                //   (ギャラリー/お絵かき/ビデオエディター/AIスタジオ) は、
                //   ヘッダーボタンをギャラリーと完全に同じものに揃える。
                if (provider.currentPage.pageType != 'normal') ...[
                  // ── ページ名ラベルはヘッダー左端 (AppBar の title) に移設した
                  //    (= ユーザー要望: ページ名が右端なのを左端へ)。 ここ (actions)
                  //    には出さない。 ──
                  // ── ギャラリー等 (normal 以外) のヘッダーも自由に配置できる
                  //    カスタムバー (= ユーザー要望)。 デフォルトは従来どおり
                  //    マップメモ/範囲選択/AI/フラッシュカード (provider 側
                  //    defaultGalleryHeaderButtons でシード)。 通常ページの
                  //    customHeaderButtons とは独立 (galleryHeaderButtons)。 ──
                  if (false)
                    _HeaderCustomButtonsBar(
                      provider: provider,
                      buildButton: _buildCustomHeaderButton,
                      buttonIds: provider.galleryHeaderButtons,
                      reorderMode: _reorderHeaderMode,
                      onReorder: _reorderHeaderMode
                          ? (oldIndex, newIndex) {
                              final int adjustedNew =
                                  newIndex > oldIndex ? newIndex + 1 : newIndex;
                              provider.reorderGalleryHeaderButtons(
                                  oldIndex, adjustedNew);
                            }
                          : null,
                    ),
                  // ── YouTube 埋め込み / リンク埋め込み / 動画の再生設定 (見終わ
                  //    ったら次へ 等) / グリッドサイズ は「ギャラリー固有」 の操作
                  //    なので、 ギャラリー (bookshelf) 以外 (お絵かき/ビデオエディター
                  //    等) では出さない (= ユーザー要望: ペイント等にも出てきて
                  //    しまうのを修正)。 ──
                  if (provider.currentPage.pageType == 'bookshelf')
                    PopupMenuButton<String>(
                      tooltip: provider.t('shelf.galleryOps'),
                      icon: const Icon(Icons.add_box_outlined,
                          color: Colors.white70),
                      color: const Color(0xFF1E1E32),
                      onSelected: (v) {
                        switch (v) {
                          case 'youtube':
                            // = ユーザー要望: YouTube はホーム画面から開く。
                            _openYoutubeBrowser(context, provider,
                                forceHome: true,
                                onEmbed: (url) => _runBookshelfImport(
                                    context, provider, url));
                            break;
                          case 'link':
                            _showBookshelfImportDialog(context, provider);
                            break;
                          case 'autoNext':
                            provider.setBookshelfAutoPlayNext(
                                !provider.bookshelfAutoPlayNext);
                            break;
                          case 'deleteWatched':
                            provider.setAutoDeleteWatched(
                                !provider.autoDeleteWatched);
                            break;
                          case 'reverseOrder':
                            // = ユーザー要望: 進行方向 左→右 / 右→左 を切り替え。
                            provider.setBookshelfReverseOrder(
                                !provider.bookshelfReverseOrder);
                            break;
                          case 'addRow':
                            provider.setShelfGrid(
                                rows: provider.bookshelfRowCount() + 1);
                            break;
                          case 'addColumn':
                            provider.setShelfGrid(
                                cols: provider.bookshelfColCount() + 1);
                            break;
                        }
                      },
                      itemBuilder: (_) => [
                        PopupMenuItem<String>(
                          value: 'youtube',
                          child: Row(children: [
                            const Icon(Icons.smart_display_rounded,
                                color: Color(0xFFFF0000), size: 18),
                            const SizedBox(width: 10),
                            Text(provider.t('bookshelf.openYoutube'),
                                style: const TextStyle(color: Colors.white)),
                          ]),
                        ),
                        PopupMenuItem<String>(
                          value: 'link',
                          child: Row(children: [
                            const Icon(Icons.link_rounded,
                                color: Color(0xFF4FC3F7), size: 18),
                            const SizedBox(width: 10),
                            Text(provider.t('bookshelf.embedLink'),
                                style: const TextStyle(color: Colors.white)),
                          ]),
                        ),
                        const PopupMenuDivider(),
                        // ── チェック付き項目は CheckedPopupMenuItem の既定チェック
                        //    マークが地味で分かりにくい (= ユーザー報告) ので、 水色
                        //    (0xFF4FC3F7) の明るいチェックボックスアイコンに置き換える。
                        _shelfCheckItem(
                            'autoNext',
                            provider.t('shelf.autoPlayNext'),
                            provider.bookshelfAutoPlayNext),
                        _shelfCheckItem(
                            'deleteWatched',
                            provider.t('shelf.deleteWatched'),
                            provider.autoDeleteWatched),
                        // = ユーザー要望: 動画の進行方向 (左→右 / 右→左)。
                        _shelfCheckItem(
                            'reverseOrder',
                            provider.t('shelf.rtlProgress'),
                            provider.bookshelfReverseOrder),
                        const PopupMenuDivider(),
                        PopupMenuItem<String>(
                          value: 'addRow',
                          child: Row(children: [
                            const Icon(Icons.table_rows_rounded,
                                color: Color(0xFFFFB347), size: 18),
                            const SizedBox(width: 10),
                            Text(provider.t('table.addRow'),
                                style: const TextStyle(color: Colors.white)),
                          ]),
                        ),
                        PopupMenuItem<String>(
                          value: 'addColumn',
                          child: Row(children: [
                            const Icon(Icons.view_column_rounded,
                                color: Color(0xFFFFB347), size: 18),
                            const SizedBox(width: 10),
                            Text(provider.t('table.addColumn'),
                                style: const TextStyle(color: Colors.white)),
                          ]),
                        ),
                      ],
                    ),
                ],
                // モバイル版ではヘッダーの「ページ追加」アイコンを非表示にする。
                // サイドドロワーの + ボタン、および右上 ⋮ メニュー内から追加できるため重複していた。
                // ── ユーザーがカスタマイズしたヘッダーボタン（ドラッグで並び替え可能）──
                // ── ユーザーがカスタマイズしたヘッダーボタンはマインドマップ
                //    (normal) ページでのみ表示。 それ以外のページは上の
                //    ギャラリー共通ボタンに統一する (= ユーザー要望) ──
                if (false &&
                    provider.currentPage.pageType == 'normal' &&
                    provider.customHeaderButtons.isNotEmpty)
                  _HeaderCustomButtonsBar(
                    provider: provider,
                    buildButton: _buildCustomHeaderButton,
                    reorderMode: _reorderHeaderMode,
                    onReorder: _reorderHeaderMode
                        ? (oldIndex, newIndex) {
                            // provider.reorderHeaderButtons は
                            // ReorderableListView と同じ仕様で
                            // (newIndex > oldIndex) の場合に -1 される実装。
                            // しかしここの Draggable は「drop 先のスロット番号」
                            // をそのまま渡しているので、前方移動 (左→右) の時に
                            // 1 つずれる問題が発生していた。
                            // → 前方移動時だけ newIndex を +1 して渡す。
                            final int adjustedNew =
                                newIndex > oldIndex ? newIndex + 1 : newIndex;
                            provider.reorderHeaderButtons(
                                oldIndex, adjustedNew);
                          }
                        : null,
                  ),
                // ── AI チャット (MCP) ── (= ユーザー要望: 右上の画面分割の
                //   隣に置く)。 メニューを開かずに 1 タップで出せる。
                if (_isDesktop)
                  // 右クリック (長押し) で開き方を選べる (= ユーザー要望:
                  //   右分割 / 左分割 / フローティング / 全画面)。
                  GestureDetector(
                    onSecondaryTapDown: (d) => unawaited(
                        _showAiAssistantOpenStyleMenu(d.globalPosition)),
                    onLongPressStart: (d) => unawaited(
                        _showAiAssistantOpenStyleMenu(d.globalPosition)),
                    child: IconButton(
                      // 「AI に任せる」 が伝わるアイコンに (= ユーザー要望)。
                      icon: Icon(Icons.auto_awesome_rounded,
                          color: provider.mcpServerEnabled
                              ? const Color(0xFF80CBC4)
                              : Colors.white70,
                          size: 20),
                      tooltip:
                          '${provider.t('mcp.chatTitle')} '
                          '${provider.t('tip.rightClickOpenStyle')}',
                      padding: EdgeInsets.zero,
                      constraints:
                          const BoxConstraints(minWidth: 36, minHeight: 36),
                      onPressed: () => _openMcpChat(provider),
                    ),
                  ),
                PopupMenuButton<String>(
                  icon: const Icon(Icons.more_vert, color: Colors.white70),
                  tooltip: provider.t('tooltip.openMenu'),
                  color: Color.alphaBlend(
                    provider.headerColor.withValues(
                        alpha: provider.hasCustomHeaderColor ? 0.48 : 0.0),
                    const Color(0xFF2A2A3E),
                  ),
                  // ── フローティングツール (計算機等) を裏に隠す制御 ──
                  // PopupMenuButton はそのままだと計算機等の OverlayEntry より
                  // 下のレイヤに描画されてしまい、ツールに重なって読めない。
                  // 開いた瞬間に _popupMenuOpen=true にして 5 つのツールを
                  // Offstage に隠す → 選択 / キャンセルで戻す。Offstage なので
                  // タイマー State は維持されメニュー操作中も裏で進む。
                  onOpened: () {
                    setState(() => _popupMenuOpen = true);
                    _refreshFloatingOverlays();
                  },
                  onCanceled: () {
                    setState(() => _popupMenuOpen = false);
                    _refreshFloatingOverlays();
                  },
                  onSelected: (v) {
                    setState(() => _popupMenuOpen = false);
                    _refreshFloatingOverlays();
                    if (v == 'clear') _confirmClear(context, provider);
                    if (v == 'rename') {
                      _renamePageDialog(
                          context, provider, provider.currentPageIndex);
                    }
                    if (v == 'delete') _confirmDeletePage(context, provider);
                    if (v == 'trash') {
                      // ignore: discarded_futures
                      _showPageTrashDialog(context, provider);
                    }
                    if (v == 'addPage') _addPageDialog(context, provider);
                    if (v == 'openWeatherFromMenu') {
                      // 日付+時刻+天気 サマリー項目をタップ → 時差 / 天気の地点を
                      // 設定するダイアログを開く (要望対応)。 そこから詳しい天気
                      // パネルも開ける。
                      _showWeatherClockConfigDialog(context, provider);
                    }
                    if (v == 'lockH') setState(() => _lockH = !_lockH);
                    if (v == 'lockV') setState(() => _lockV = !_lockV);
                    if (v == 'sync') _showSyncDialog(context, provider);
                    if (v == 'mcpServer') {
                      _openMcpChat(provider);
                      return;
                    }
                    if (v == 'inquiry') _showInquiryDialog(context, provider);
                    // 'messaging' (メッセージ機能) は廃止 (ユーザー要望)。
                    if (v == 'autoLayout') {
                      provider.autoLayoutTree(referencePos: _currentRefPos());
                      _centerOnRoot();
                    }
                    if (v == 'zoomIn')
                      _applyScale((_scalePercent + 10).clamp(50, 150));
                    if (v == 'zoomOut')
                      _applyScale((_scalePercent - 10).clamp(50, 150));
                    if (v == 'goRef') _centerOnRoot();
                    if (v == 'setRef') {
                      setState(() => _settingRefMode = true);
                    }
                    if (v == 'snapToggle') {
                      provider.setSnapEnabled(!provider.snapEnabled);
                    }
                    if (v == 'autoDeleteToggle') {
                      provider
                          .setAutoDeleteWatched(!provider.autoDeleteWatched);
                    }
                    if (v == 'shortcuts') {
                      _openShortcutsList(context);
                    }
                    if (v == 'language') {
                      _showLanguageDialog(context, provider);
                    }
                    if (v == 'aiSettings') {
                      _showGeminiKeyDialog(context, provider, null);
                    }
                    if (v == 'settings') {
                      _showSettingsSheet(context, provider);
                    }
                    if (v == 'customizeHeader') {
                      _showHeaderCustomizeSheet(context, provider);
                    }
                    if (v == 'customizeBottomBar') {
                      _showBottomBarCustomizeSheet(context, provider);
                    }
                    if (v == 'cycleBottomRows') {
                      // ignore: discarded_futures
                      _showBottomRowsPicker(provider);
                    }
                    if (v == 'reorderHeader') {
                      // 並び替えモード開始。ヘッダーアイコンが LongPress でドラッグ可能に。
                      // Esc キー (または画面タップ) で解除。
                      setState(() => _reorderHeaderMode = true);
                      // 下部 SnackBar はモバイルだとボタンを隠してしまうため
                      // _showLockToast で上部中央に表示する。
                      _showLockToast(provider.t('reorderHeader.hint'));
                    }
                  },
                  itemBuilder: (_) => [
                    // ── 日付 + 時刻 + 天気サマリー (タップで時差/地点 設定) ──
                    // 時差 (provider.clockOffsetMinutes) を適用した日付・時刻を
                    // 毎秒更新で表示し、 下段に天気サマリー (地名・降水確率・
                    // 最高/最低) を出す。 都市未設定時は「天気を設定」表示。
                    PopupMenuItem(
                      value: 'openWeatherFromMenu',
                      padding: const EdgeInsets.symmetric(horizontal: 12),
                      child: _MenuClockWeather(provider: provider),
                    ),
                    const PopupMenuDivider(height: 6),
                    PopupMenuItem(
                        value: 'addPage',
                        child: Row(children: [
                          const Icon(Icons.add_box_outlined,
                              color: Colors.white54, size: 18),
                          const SizedBox(width: 8),
                          Text(provider.t('menu.addPage'),
                              style: const TextStyle(color: Colors.white)),
                        ])),
                    PopupMenuItem(
                        value: 'rename',
                        child: Row(children: [
                          const Icon(Icons.drive_file_rename_outline_rounded,
                              color: Colors.white54, size: 18),
                          const SizedBox(width: 8),
                          Text(provider.t('menu.rename'),
                              style: const TextStyle(color: Colors.white)),
                        ])),
                    // ── ページをリセット ('clear') は削除 (= ユーザー要望) ──
                    // 誤操作でマップ全体が消える事故が起きやすいため、メニューから
                    //   外す。本体ロジック (_confirmClear / clearCurrentPage) は
                    //   後方互換のため残しているが、 メニューからは到達不能になる。
                    PopupMenuItem(
                        value: 'delete',
                        child: Row(children: [
                          const Icon(Icons.delete_outline_rounded,
                              color: Colors.redAccent, size: 18),
                          const SizedBox(width: 8),
                          Text(provider.t('menu.delete'),
                              style: const TextStyle(color: Colors.redAccent)),
                        ])),
                    // ── ごみ箱 (= ユーザー要望) ──
                    // ページを消した時の控え (page_backups) を見て、 待たずに
                    //   完全に削除できる。 1 か月を過ぎた分は自動で消える。
                    // (バックアップ復元の窓口は以前ユーザー要望で外したので、
                    //   ここでも出していない)
                    PopupMenuItem(
                        value: 'trash',
                        child: Row(children: [
                          const Icon(Icons.delete_sweep_rounded,
                              color: Colors.white54, size: 18),
                          const SizedBox(width: 8),
                          Text(provider.t('trash.menu'),
                              style: const TextStyle(color: Colors.white)),
                        ])),
                    // AI チャット (MCP) はヘッダー右上 (画面分割の隣) に
                    //   常設したので、 メニューからは外した (= ユーザー要望)。
                    if (!_isDesktop) ...[
                      const PopupMenuDivider(),
                      PopupMenuItem(
                          value: 'goRef',
                          child: Row(children: [
                            const Icon(Icons.my_location_rounded,
                                color: Colors.white54, size: 18),
                            const SizedBox(width: 8),
                            Text(provider.t('menu.goRef'),
                                style: const TextStyle(color: Colors.white)),
                          ])),
                      PopupMenuItem(
                          value: 'setRef',
                          child: Row(children: [
                            const Icon(Icons.add_location_alt_rounded,
                                color: Color(0xFF43B97F), size: 18),
                            const SizedBox(width: 8),
                            Text(provider.t('menu.setRef'),
                                style: const TextStyle(color: Colors.white)),
                          ])),
                    ],
                    // ボタンの配置設定はヘッダー右上に常設しているので、
                    //   メニューからは外した (= ユーザー要望)。 併せて、
                    //   項目が無くなって二重になっていた区切り線も 1 本に。
                    // PC では下のふたつが両方消えるため、 この区切り線だけが
                    //   残って 「削除」 と 「設定」 の間に線が出ていた
                    //   (= ユーザー要望で消したはずが残っていた)。
                    if (!_isDesktop) const PopupMenuDivider(),
                    if (!_isDesktop)
                      PopupMenuItem(
                        value: 'customizeBottomBar',
                        child: Row(children: [
                          const Icon(Icons.view_agenda_outlined,
                              color: Color(0xFFFFB347), size: 18),
                          const SizedBox(width: 8),
                          Text(provider.t('menu.customizeBottomBar'),
                              style: const TextStyle(color: Colors.white)),
                        ]),
                      ),
                    if (!_isDesktop && provider.isMaxUnlocked)
                      PopupMenuItem(
                        value: 'cycleBottomRows',
                        child: Row(children: [
                          const Icon(Icons.view_agenda_rounded,
                              color: Color(0xFFBA68C8), size: 18),
                          const SizedBox(width: 8),
                          Text(provider.t('settings.bottomRowsTitle'),
                              style: const TextStyle(color: Colors.white)),
                          const SizedBox(width: 6),
                          Text(
                            '(${_bottomBarRowLabel(
                              provider,
                              _bottomBarRowCount(provider),
                            )})',
                            style: const TextStyle(
                                color: Colors.white38, fontSize: 11),
                          ),
                        ]),
                      ),
                    // ── 設定（配置候補/視聴済み自動削除/ショートカット/クラウド同期/
                    //    AI/メッセージ/お問い合わせ はすべて設定内に集約）──
                    //    区切り線は入れない (= ユーザー要望)。
                    PopupMenuItem(
                      value: 'settings',
                      child: Row(children: [
                        const Icon(Icons.settings_rounded,
                            color: Color(0xFFBA68C8), size: 18),
                        const SizedBox(width: 8),
                        Text(provider.t('menu.settings'),
                            style: const TextStyle(color: Colors.white)),
                      ]),
                    ),
                  ],
                ),
              ],
            ],
          ),
        ),
      ],
    );
  }

  // ─── Drawer ──────────────────────────────────────────────────────────────

  /// マップ一覧 ↔ タイムライン切替タブ (両方のドロワーで使う共通 UI)。
  Widget _buildDrawerViewSwitcher() {
    final provider = context.watch<MindMapProvider>();
    final baseColor = provider.headerColor;
    Widget chip(String label, IconData icon, String mode) {
      final selected = _drawerView == mode;
      return Expanded(
        child: InkWell(
          onTap: () => setState(() => _drawerView = mode),
          borderRadius: BorderRadius.circular(6),
          child: Container(
            padding: const EdgeInsets.symmetric(vertical: 8),
            decoration: BoxDecoration(
              color: selected
                  ? baseColor.withValues(alpha: 0.58)
                  : baseColor.withValues(alpha: 0.16),
              borderRadius: BorderRadius.circular(6),
              border: Border.all(
                  color: selected
                      ? Colors.white.withValues(alpha: 0.32)
                      : baseColor.withValues(alpha: 0.34),
                  width: 1),
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Icon(icon,
                    color: selected ? Colors.white : Colors.white54, size: 14),
                const SizedBox(width: 6),
                Text(label,
                    style: TextStyle(
                        color: selected ? Colors.white : Colors.white54,
                        fontSize: 12,
                        fontWeight: FontWeight.w600)),
              ],
            ),
          ),
        ),
      );
    }

    return Padding(
      padding: const EdgeInsets.fromLTRB(10, 10, 10, 4),
      child: Row(children: [
        chip(provider.t('drawer.maps'), Icons.map_rounded, 'maps'),
        const SizedBox(width: 6),
        // タイムラインは廃止し、 ToDo のチェックリストに置き換えた
        // (= ユーザー要望)。
        chip(provider.t('drawer.todo'), Icons.checklist_rounded, 'todo'),
      ]),
    );
  }

  /// タイムラインドロワー: 今日 (= 端末ローカル 0:00 以降) に作成/更新された
  /// PDF メモを時刻降順で一覧表示する (= ユーザー要望)。
  /// タイムライン Drawer 用の永続 ScrollController。
  /// 毎ビルドで作り直すと、予定をタップ追加したりドラッグするたびに
  /// スクロールが現在時刻へ飛んでしまうため、State に保持して使い回す。
  ScrollController? _timelineDrawerScrollCtrl;

  /// 最後に初期スクロールを行った _timelineDayOffset。
  /// 「初回」と「表示日が変わった時」だけ現在時刻(他日は朝8時)へジャンプし、
  /// それ以外の再ビルド(タップ追加/ドラッグ)ではスクロールを動かさない。
  int? _timelineDrawerScrolledOffset;

  /// 端到達で前日/翌日へ連続スクロールするための制御フラグ。
  bool _timelineHandlingBoundary = false;

  /// 日付めくり直後にジャンプしたいスクロール位置（端の反対側）。
  /// 0.0 = 先頭(0:00) / double.infinity = 末尾(24:00) / null = 通常の初期スクロール。
  double? _timelinePendingBoundaryOffset;

  /// ドラッグ開始時の表示日オフセット / 日付キー / 元のアイテム。
  /// ドラッグ中に日付をめくっても、 予定の描画位置 (= 表示日との差分で補正) と
  /// 確定先 (= 元の日付キー基準) を正しく計算するために保持する。
  int _timelineDragStartDayOffset = 0;
  String? _timelineDragStartDateKey;
  Map<String, dynamic>? _timelineDraggingItem;

  /// タイムライン Drawer のスクロールが上端/下端に達したら前日/翌日へ切り替え、
  /// 反対側の端から続けて読み込めるようにする
  /// (= ユーザー要望: 0時/24時を超えて前後の日の時間までスクロールできるように)。
  /// _DayTimelinePage._onScroll と同方式。
  void _onTimelineDrawerScroll() {
    final c = _timelineDrawerScrollCtrl;
    if (c == null || !c.hasClients || _timelineHandlingBoundary) return;
    // イベントのドラッグ中は日付めくりしない（誤操作防止）。
    if (_timelineDraggingId != null) return;
    final pos = c.position;
    if (pos.pixels >= pos.maxScrollExtent - 1 &&
        pos.userScrollDirection == ScrollDirection.reverse) {
      // 下端で下方向に続ける → 翌日へ、先頭(0:00)から
      _timelineHandlingBoundary = true;
      _timelinePendingBoundaryOffset = 0.0;
      setState(() => _timelineDayOffset += 1);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _timelineHandlingBoundary = false;
      });
    } else if (pos.pixels <= 0 &&
        pos.userScrollDirection == ScrollDirection.forward) {
      // 上端で上方向に続ける → 前日へ、最下部(24:00)から
      _timelineHandlingBoundary = true;
      _timelinePendingBoundaryOffset = double.infinity;
      setState(() => _timelineDayOffset -= 1);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _timelineHandlingBoundary = false;
      });
    }
  }

  // ── 予定ドラッグ中のエッジ自動スクロール (= ユーザー要望: ドラッグで
  //    画面外へ出るときは追跡してスクロールする) ──
  final GlobalKey _timelineDrawerViewportKey = GlobalKey();
  Offset? _timelineDragLastGlobalPos;
  Timer? _timelineDragAutoScrollTimer;

  void _startTimelineDragAutoScroll() {
    _timelineDragAutoScrollTimer?.cancel();
    _timelineDragAutoScrollTimer = Timer.periodic(
        const Duration(milliseconds: 16), (_) => _timelineDragEdgeTick());
  }

  void _stopTimelineDragAutoScroll() {
    _timelineDragAutoScrollTimer?.cancel();
    _timelineDragAutoScrollTimer = null;
  }

  /// ドラッグ中の予定の上端を、 掴んだカーソルに追従させた「表示日上の content
  /// 位置 (分=px)」 として算出する。 カーソルのスクリーン Y・ビューポート上端・
  /// スクロール量から計算するので、 日付めくり/スクロールに関係なく常にカーソル
  /// にぴったり張り付く (= ユーザー要望: 24時付近の乖離を解消)。 算出できなければ
  /// null。
  double? _timelineDragEventTopContent() {
    final pos = _timelineDragLastGlobalPos;
    final c = _timelineDrawerScrollCtrl;
    final rb = _timelineDrawerViewportKey.currentContext?.findRenderObject()
        as RenderBox?;
    if (pos == null || c == null || !c.hasClients || rb == null) return null;
    final vpTop = rb.localToGlobal(Offset.zero).dy;
    // スクリーン Y = vpTop + content - scroll  ⇔  content = (Y - vpTop) + scroll
    return (pos.dy - _timelineDragGrabOffset - vpTop) + c.position.pixels;
  }

  /// 予定ドラッグ中、ポインタがビューポート上下端に近いとタイムラインを
  /// スクロールする (予定の位置はカーソルから算出するので追従は自動)。
  /// 端に到達してもまだ押していれば前日/翌日へめくる。
  void _timelineDragEdgeTick() {
    if (_timelineDraggingId == null) {
      _stopTimelineDragAutoScroll();
      return;
    }
    if (_timelineDragLastGlobalPos == null) return;
    final c = _timelineDrawerScrollCtrl;
    if (c == null || !c.hasClients) return;
    final rb = _timelineDrawerViewportKey.currentContext?.findRenderObject()
        as RenderBox?;
    if (rb == null) return;
    final vpTop = rb.localToGlobal(Offset.zero).dy;
    final vpBottom = vpTop + rb.size.height;
    final y = _timelineDragLastGlobalPos!.dy;
    const edge = 56.0; // エッジ感知ゾーン(px)
    const maxStep = 12.0; // 1tick あたりの最大スクロール量(px)
    double step = 0;
    if (y < vpTop + edge) {
      final depth = ((vpTop + edge) - y).clamp(0.0, edge);
      step = -maxStep * (depth / edge);
    } else if (y > vpBottom - edge) {
      final depth = (y - (vpBottom - edge)).clamp(0.0, edge);
      step = maxStep * (depth / edge);
    }
    if (step == 0) return;
    final cur = c.position.pixels;
    final maxExt = c.position.maxScrollExtent;
    final next = (cur + step).clamp(0.0, maxExt);
    final actual = next - cur;
    if (actual != 0) {
      c.jumpTo(next);
      // スクロールが変わったので、 カーソル基準で予定位置を再計算するため再ビルド。
      setState(() {});
      return;
    }
    // ── 端に到達してもまだ端方向へ押している → 前日/翌日へめくって
    //    シームレスにドラッグを継続する (= ユーザー要望: 0時/24時を跨いで
    //    次の日・前日へそのまま送れるように) ──
    if (_timelineHandlingBoundary) return;
    if (step > 0 && cur >= maxExt - 0.5) {
      // 下端で下方向 → 翌日へ。 反対側 (0:00) からめくる。
      _timelineHandlingBoundary = true;
      _timelinePendingBoundaryOffset = 0.0;
      setState(() => _timelineDayOffset += 1);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _timelineHandlingBoundary = false;
      });
    } else if (step < 0 && cur <= 0.5) {
      // 上端で上方向 → 前日へ。 反対側 (24:00) からめくる。
      _timelineHandlingBoundary = true;
      _timelinePendingBoundaryOffset = double.infinity;
      setState(() => _timelineDayOffset -= 1);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _timelineHandlingBoundary = false;
      });
    }
  }

  /// マップ一覧と同じ Drawer ウィジェットを返すので、 位置とサイズは同一。
  /// 今日のタイムライン (= ユーザー要望: カレンダー風時刻軸、 現在時刻付近を
  /// 一番上に来るように)。 24 時間の時刻軸を縦に並べ、 各時間ブロックに
  /// その時刻に該当する予定 / 活動を配置する。
  // ─── ToDo チェックリスト (= ユーザー要望: タイムラインの代わりに) ───────
  //
  // サイドメニューの 2 つ目のタブ。 やることを書き足して、 チェックで
  // 済みにし、 ゴミ箱で消す。 prefs `drawer_todos_v1` に JSON で保存。
  final List<Map<String, dynamic>> _drawerTodos = [];
  bool _drawerTodosLoaded = false;
  final TextEditingController _todoInputCtrl = TextEditingController();

  Future<void> _loadDrawerTodos() async {
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString('drawer_todos_v1');
      if (raw == null || raw.isEmpty) return;
      final arr = jsonDecode(raw);
      if (arr is! List) return;
      _drawerTodos
        ..clear()
        ..addAll([
          for (final e in arr)
            if (e is Map) {'t': '${e['t'] ?? ''}', 'd': e['d'] == true}
        ]);
      if (mounted) setState(() {});
    } catch (_) {}
  }

  Future<void> _saveDrawerTodos() async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString('drawer_todos_v1', jsonEncode(_drawerTodos));
    } catch (_) {}
  }

  void _addDrawerTodo() {
    final t = _todoInputCtrl.text.trim();
    if (t.isEmpty) return;
    setState(() {
      _drawerTodos.add({'t': t, 'd': false});
      _todoInputCtrl.clear();
    });
    // ignore: discarded_futures
    _saveDrawerTodos();
  }

  Widget _buildTodoDrawer(BuildContext ctx, MindMapProvider provider) {
    if (!_drawerTodosLoaded) {
      _drawerTodosLoaded = true;
      // ignore: discarded_futures
      _loadDrawerTodos();
    }
    final bg = Color.alphaBlend(
        provider.headerColor.withValues(alpha: 0.62), const Color(0xFF13132A));
    final hasDone = _drawerTodos.any((e) => e['d'] == true);
    return Drawer(
      backgroundColor: bg,
      child: SafeArea(
        child: Column(children: [
          _buildDrawerViewSwitcher(),
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 10, 8, 0),
            child: Row(children: [
              const Icon(Icons.checklist_rounded,
                  color: Color(0xFF7FD8A0), size: 18),
              const SizedBox(width: 8),
              Expanded(
                child: Text(provider.t('drawer.todo'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 14,
                        fontWeight: FontWeight.w700)),
              ),
              // 済みの項目をまとめて消す。
              if (hasDone)
                TextButton(
                  style: TextButton.styleFrom(
                    visualDensity: VisualDensity.compact,
                    padding: const EdgeInsets.symmetric(horizontal: 8),
                  ),
                  onPressed: () {
                    setState(() =>
                        _drawerTodos.removeWhere((e) => e['d'] == true));
                    // ignore: discarded_futures
                    _saveDrawerTodos();
                  },
                  child: Text(provider.t('todo.clearDone'),
                      style: const TextStyle(
                          color: Colors.white54, fontSize: 11)),
                ),
            ]),
          ),
          // ── 追加欄 ──
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 8, 14, 4),
            child: Row(children: [
              Expanded(
                child: TextField(
                  controller: _todoInputCtrl,
                  style: const TextStyle(color: Colors.white, fontSize: 13),
                  decoration: InputDecoration(
                    isDense: true,
                    contentPadding: const EdgeInsets.symmetric(
                        horizontal: 12, vertical: 10),
                    hintText: provider.t('todo.addHint'),
                    hintStyle:
                        const TextStyle(color: Colors.white38, fontSize: 12),
                    filled: true,
                    fillColor: Colors.white.withValues(alpha: 0.06),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                      borderSide: BorderSide.none,
                    ),
                  ),
                  onSubmitted: (_) => _addDrawerTodo(),
                ),
              ),
              const SizedBox(width: 8),
              InkWell(
                borderRadius: BorderRadius.circular(10),
                onTap: _addDrawerTodo,
                child: Container(
                  width: 38,
                  height: 38,
                  decoration: BoxDecoration(
                    color: const Color(0xFF7FD8A0).withValues(alpha: 0.18),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(
                        color:
                            const Color(0xFF7FD8A0).withValues(alpha: 0.6)),
                  ),
                  child: const Icon(Icons.add_rounded,
                      color: Color(0xFF7FD8A0), size: 20),
                ),
              ),
            ]),
          ),
          // ── 一覧 ──
          Expanded(
            child: _drawerTodos.isEmpty
                ? Center(
                    child: Padding(
                      padding: const EdgeInsets.all(20),
                      child: Text(provider.t('todo.empty'),
                          textAlign: TextAlign.center,
                          style: const TextStyle(
                              color: Colors.white38,
                              fontSize: 12,
                              height: 1.6)),
                    ),
                  )
                : ListView.builder(
                    padding: const EdgeInsets.fromLTRB(8, 4, 8, 12),
                    itemCount: _drawerTodos.length,
                    itemBuilder: (_, i) {
                      final item = _drawerTodos[i];
                      final done = item['d'] == true;
                      return Container(
                        margin: const EdgeInsets.symmetric(vertical: 2),
                        decoration: BoxDecoration(
                          color: Colors.white.withValues(alpha: 0.05),
                          borderRadius: BorderRadius.circular(10),
                        ),
                        child: Row(children: [
                          // チェック (押すと済み ↔ 未了)。
                          InkWell(
                            borderRadius: BorderRadius.circular(10),
                            onTap: () {
                              setState(() => item['d'] = !done);
                              // ignore: discarded_futures
                              _saveDrawerTodos();
                            },
                            child: Padding(
                              padding: const EdgeInsets.all(10),
                              child: Icon(
                                  done
                                      ? Icons.check_box_rounded
                                      : Icons
                                          .check_box_outline_blank_rounded,
                                  size: 20,
                                  color: done
                                      ? const Color(0xFF7FD8A0)
                                      : Colors.white54),
                            ),
                          ),
                          Expanded(
                            child: Text(
                              '${item['t']}',
                              style: TextStyle(
                                color:
                                    done ? Colors.white38 : Colors.white,
                                fontSize: 13,
                                height: 1.4,
                                decoration: done
                                    ? TextDecoration.lineThrough
                                    : null,
                                decorationColor: Colors.white38,
                              ),
                            ),
                          ),
                          IconButton(
                            visualDensity: VisualDensity.compact,
                            icon: const Icon(Icons.close_rounded,
                                size: 16, color: Colors.white38),
                            onPressed: () {
                              setState(() => _drawerTodos.removeAt(i));
                              // ignore: discarded_futures
                              _saveDrawerTodos();
                            },
                          ),
                        ]),
                      );
                    },
                  ),
          ),
        ]),
      ),
    );
  }

  Widget _buildTimelineDrawer(BuildContext ctx, MindMapProvider provider) {
    final realNow = DateTime.now();
    // ── 表示する日 (= ユーザー要望: 矢印で前日/翌日に切替) ──
    // _timelineDayOffset==0 が今日。 events/ラベルは「表示日」基準で出す。
    final isToday = _timelineDayOffset == 0;
    final now = DateTime(realNow.year, realNow.month, realNow.day)
        .add(Duration(days: _timelineDayOffset));
    final startOfDay =
        DateTime(now.year, now.month, now.day).millisecondsSinceEpoch;
    String two(int n) => n.toString().padLeft(2, '0');
    final todayKey = '${now.year}-${two(now.month)}-${two(now.day)}';
    final dow = [
      'Mon',
      'Tue',
      'Wed',
      'Thu',
      'Fri',
      'Sat',
      'Sun'
    ][(now.weekday - 1).clamp(0, 6)];
    final dateLabel = '${two(now.month)}/${two(now.day)} ($dow)';

    // ── 今日のタイムライン項目を時刻別に集約 ──
    // 各項目: {kind, startMin, endMin, title, subtitle, color, nodeId?}
    final items = <Map<String, dynamic>>[];
    // カレンダー予定
    final events = provider.eventsOn(todayKey);
    for (final ev in events) {
      int parseMin(String? hhmm) {
        if (hhmm == null || !hhmm.contains(':')) return -1;
        final parts = hhmm.split(':');
        final h = int.tryParse(parts[0]) ?? 0;
        final m = int.tryParse(parts.length > 1 ? parts[1] : '0') ?? 0;
        return h * 60 + m;
      }

      final s = parseMin(ev.startTime);
      final e = parseMin(ev.endTime);
      items.add({
        'kind': 'event',
        'startMin': s,
        'endMin': e < 0 ? s + 60 : e,
        'title': ev.title.isEmpty ? provider.t('tl.untitledEvent') : ev.title,
        'subtitle': ev.memo ?? '',
        'color': ev.colorArgb != null
            ? Color(ev.colorArgb!)
            : const Color(0xFF4FC3F7),
        // 削除に必要な情報 (= ユーザー要望: タイムラインから予定を削除可能に)。
        'eventId': ev.id,
        // 他人 (グループ共有) のイベントは削除できないので区別する。
        'isOthers': ev.isOthersEvent(provider.currentUid),
      });
    }
    // ── 活動 (PdfMemo) は表示しない (= ユーザー要望: 活動履歴は要らない、
    //    予定だけでいい) ──

    // ── ドラッグ中に日付をめくった場合、 ドラッグ中の予定は表示日の
    //    events に含まれず消えてしまう → ジェスチャも中断される。 元の
    //    アイテムを注入してウィジェット (とドラッグ) を生かし続ける。 ──
    if (_timelineDraggingId != null &&
        _timelineDraggingItem != null &&
        !items.any((it) => it['eventId'] == _timelineDraggingId)) {
      items.add(_timelineDraggingItem!);
    }

    // 時刻軸の表示: 各時間 = 60px の縦ブロック (= 1 分 = 1px)
    // ── 睡眠時間の圧縮表示用 座標マップ (= ユーザー要望) ──
    // hourY[h] = 時刻 h:00 の y 座標。 tlY(分)=描画 y、 tlMinForY(y)=分。
    // 実体は state メソッド (_commitTimelineDrag など build 外からも使うため)。
    // 睡眠未設定時は恒等変換 (= 既存挙動と完全一致。 安全)。
    final List<double> hourY = _tlHourY();
    final double totalHeight = _tlTotalHeight; // 圧縮込みの全体高さ
    double tlY(int minute) => _tlYForMin(minute);
    int tlMinForY(double y) => _tlMinForY(y);

    // ── 重なる予定を横並び (列分け) するための列割り当て ──
    // (= ユーザー要望: 予定が被る時はブロックが重ならず横に配置)。
    // 開始時刻順に貪欲に空き列へ割り当て、 同じ重なりクラスタ内の列数を数えて、
    // 各予定を「列番号 / 列数」 で横位置を決める (Align + FractionallySizedBox)。
    int durMin(Map<String, dynamic> it) {
      final d = ((it['endMin'] as int) - (it['startMin'] as int)).abs();
      return d < 44 ? 44 : d; // 描画上の最小高さに合わせて重なり判定
    }

    final timed = items.where((it) => (it['startMin'] as int) >= 0).toList()
      ..sort((a, b) {
        final c = (a['startMin'] as int).compareTo(b['startMin'] as int);
        return c != 0 ? c : durMin(b).compareTo(durMin(a));
      });
    final laneOf = <String, int>{};
    final colsOf = <String, int>{};
    int li = 0;
    while (li < timed.length) {
      int lj = li;
      int clusterEnd = (timed[li]['startMin'] as int) + durMin(timed[li]);
      final lanesEnd = <int>[];
      final clusterKeys = <String>[];
      while (lj < timed.length && (timed[lj]['startMin'] as int) < clusterEnd) {
        final s = timed[lj]['startMin'] as int;
        final e2 = s + durMin(timed[lj]);
        int lane = -1;
        for (int l = 0; l < lanesEnd.length; l++) {
          if (lanesEnd[l] <= s) {
            lane = l;
            break;
          }
        }
        if (lane == -1) {
          lane = lanesEnd.length;
          lanesEnd.add(e2);
        } else {
          lanesEnd[lane] = e2;
        }
        final k = 'tlitem_${timed[lj]['eventId'] ?? timed[lj]['nodeId'] ?? s}';
        laneOf[k] = lane;
        clusterKeys.add(k);
        if (e2 > clusterEnd) clusterEnd = e2;
        lj++;
      }
      final cols = lanesEnd.length;
      for (final k in clusterKeys) {
        colsOf[k] = cols;
      }
      li = lj;
    }

    final eventCount = events.length;
    // ── 終日の予定 (= startTime 無し) ──
    // 時刻グリッドだとスクロールで消えてしまうので、 上部に固定で常に表示する
    //   (= ユーザー要望: その日の終日予定を常に表示)。
    final allDayEvents = events
        .where((e) => e.startTime == null || e.startTime!.trim().isEmpty)
        .toList();
    final timelineBase = provider.headerColor;
    final timelineDrawerBg = Color.alphaBlend(
      timelineBase.withValues(
          alpha: provider.hasCustomHeaderColor ? 0.30 : 0.0),
      const Color(0xFF13132A),
    );
    final timelineDrawerPanel = Color.alphaBlend(
      timelineBase.withValues(
          alpha: provider.hasCustomHeaderColor ? 0.22 : 0.0),
      const Color(0xFF161622),
    );
    final timelineSleepPanel = Color.alphaBlend(
      timelineBase.withValues(
          alpha: provider.hasCustomHeaderColor ? 0.26 : 0.0),
      const Color(0xFF1B2440),
    );
    final timelineDrawerLine = timelineBase.withValues(
        alpha: provider.hasCustomHeaderColor ? 0.28 : 0.10);

    // 現在時刻付近にスクロールするためのコントローラ。 ListView では位置
    //   制御が複雑なので、 SingleChildScrollView + ScrollController を使う。
    // State に保持して使い回す（毎ビルドで作り直すとスクロールが飛ぶ）。
    if (_timelineDrawerScrollCtrl == null) {
      _timelineDrawerScrollCtrl = ScrollController();
      // 端での前日/翌日連続スクロール用のリスナーを 1 度だけ登録。
      _timelineDrawerScrollCtrl!.addListener(_onTimelineDrawerScroll);
    }
    final controller = _timelineDrawerScrollCtrl!;
    // 今日は現在時刻付近、 それ以外の日は朝 8 時付近にスクロールする。
    final nowMin = isToday ? (realNow.hour * 60 + realNow.minute) : (8 * 60);
    // 現在時刻が画面の少し上 (= 60px = 1 時間分) に来るようオフセット。
    final initialOffset = (tlY(nowMin) - 60).clamp(0.0, totalHeight).toDouble();
    // 初期スクロールは「初回」と「表示日が変わった時」だけ。毎ビルドで
    //   jumpTo すると、予定をタップ追加/ドラッグするたびにスクロールが
    //   現在時刻へ飛んでしまう (= ユーザー要望: 追加のためにクリックしても
    //   その場で動かないように)。
    final needInitialScroll =
        _timelineDrawerScrolledOffset != _timelineDayOffset;
    _timelineDrawerScrolledOffset = _timelineDayOffset;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (controller.hasClients) {
        // 端到達による日付めくり直後は、反対側の端へジャンプして連続表示。
        // それ以外（初回・矢印での日付切替）は現在時刻/朝8時へジャンプ。
        if (_timelinePendingBoundaryOffset != null) {
          final maxExt = controller.position.maxScrollExtent;
          final target = _timelinePendingBoundaryOffset == double.infinity
              ? maxExt
              : _timelinePendingBoundaryOffset!.clamp(0.0, maxExt);
          controller.jumpTo(target);
          _timelinePendingBoundaryOffset = null;
          // 日付めくり後にスクロール位置が変わったので、 ドラッグ中なら
          //   予定をカーソル基準で再配置するため再ビルドする。
          if (_timelineDraggingId != null && mounted) setState(() {});
        } else if (needInitialScroll) {
          controller.jumpTo(initialOffset);
        }
      }
      // タイムラインを開いたタイミングで、 今日の予定の通知を仕掛ける
      //   (= ユーザー要望: 予定は通知される)。 重複は _scheduledNotifications で抑止。
      _schedulePendingEventNotifications(provider);
    });

    return Drawer(
      backgroundColor: timelineDrawerBg,
      child: SafeArea(
        child: Focus(
          autofocus: true,
          // ── 予定を選択中に Backspace/Del で削除 (= ユーザー要望:
          //    × ボタンを廃止しキー操作で削除できるように) ──
          onKeyEvent: (node, event) {
            if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
              return KeyEventResult.ignored;
            }
            // 入力欄にフォーカスがあるときは介入しない (テキスト編集を壊さない)
            final primary = FocusManager.instance.primaryFocus;
            if (primary != null && primary != node) {
              final w = primary.context?.widget;
              if (w is EditableText) return KeyEventResult.ignored;
            }
            if (event.logicalKey == LogicalKeyboardKey.delete ||
                event.logicalKey == LogicalKeyboardKey.backspace) {
              final id = _selectedTimelineEventId;
              if (id == null) return KeyEventResult.ignored;
              CalendarEvent? ev;
              for (final e in provider.eventsOn(todayKey)) {
                if (e.id == id) {
                  ev = e;
                  break;
                }
              }
              if (ev == null || ev.isOthersEvent(provider.currentUid)) {
                return KeyEventResult.ignored;
              }
              _confirmDeleteTimelineEvent(
                  ctx, provider, todayKey, id, ev.title);
              return KeyEventResult.handled;
            }
            return KeyEventResult.ignored;
          },
          child: Column(children: [
            _buildDrawerViewSwitcher(),
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 8, 16, 8),
              child: Row(children: [
                // ── カレンダー (月表示) を開く / 閉じるトグルボタン ──
                // ユーザー要望: タイムラインから開いたカレンダーを、 同じボタンを
                //   もう一度押すことで閉じられるように (= トグル化)。 カレンダー
                //   表示中はボタンを強調 (背景ハイライト) して「押すと閉じる」を示す。
                // ユーザー要望: トグルしてもサイドメニュー (ドロワー) は閉じない
                //   ようにするため、 maybePop() は呼ばない。
                Tooltip(
                  message: _calendarMode
                      ? provider.t('tl.closeCalendar')
                      : provider.t('tl.openCalendar'),
                  child: InkWell(
                    onTap: () {
                      setState(() => _calendarMode = !_calendarMode);
                      _refreshFloatingOverlays();
                    },
                    borderRadius: BorderRadius.circular(8),
                    child: Container(
                      padding: const EdgeInsets.all(4),
                      decoration: _calendarMode
                          ? BoxDecoration(
                              color: const Color(0xFF6C63FF)
                                  .withValues(alpha: 0.22),
                              borderRadius: BorderRadius.circular(8),
                            )
                          : null,
                      child: const Icon(Icons.calendar_month_rounded,
                          color: Color(0xFF6C63FF), size: 20),
                    ),
                  ),
                ),
                // ── 睡眠時間ボタン (= ユーザー要望: タイムラインから睡眠時間を設定) ──
                // タップで就寝/起床を設定。 設定済みは強調表示。 設定した時間帯は
                //   タイムライン上でコンパクトに折りたたまれる。
                Tooltip(
                  message: _sleepEnabled
                      ? provider.t('tl.changeSleep')
                      : provider.t('tl.setSleep'),
                  child: InkWell(
                    onTap: () => _showSleepTimeDialog(ctx),
                    borderRadius: BorderRadius.circular(8),
                    child: Container(
                      padding: const EdgeInsets.all(4),
                      decoration: _sleepEnabled
                          ? BoxDecoration(
                              color: const Color(0xFF8AA0EB)
                                  .withValues(alpha: 0.22),
                              borderRadius: BorderRadius.circular(8),
                            )
                          : null,
                      child: Icon(Icons.bedtime_rounded,
                          color: _sleepEnabled
                              ? const Color(0xFF8AA0EB)
                              : Colors.white38,
                          size: 18),
                    ),
                  ),
                ),
                const SizedBox(width: 6),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(children: [
                        Text(dateLabel,
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 13,
                                fontWeight: FontWeight.w700)),
                        const SizedBox(width: 6),
                        // ── 前日 / 翌日 切替の矢印 (= ユーザー要望) ──
                        InkWell(
                          onTap: () => setState(() => _timelineDayOffset -= 1),
                          borderRadius: BorderRadius.circular(12),
                          child: const Padding(
                            padding: EdgeInsets.all(2),
                            child: Icon(Icons.chevron_left_rounded,
                                color: Colors.white70, size: 20),
                          ),
                        ),
                        InkWell(
                          onTap: () => setState(() => _timelineDayOffset += 1),
                          borderRadius: BorderRadius.circular(12),
                          child: const Padding(
                            padding: EdgeInsets.all(2),
                            child: Icon(Icons.chevron_right_rounded,
                                color: Colors.white70, size: 20),
                          ),
                        ),
                        const SizedBox(width: 4),
                        // 今日の時は「今日」 バッジ、 それ以外は相対日
                        //   (明日 / 昨日 / ○日後 / ○日前) を表示。 タップで今日へ。
                        if (isToday)
                          Container(
                            padding: const EdgeInsets.symmetric(
                                horizontal: 6, vertical: 2),
                            decoration: BoxDecoration(
                              color: const Color(0xFF6C63FF)
                                  .withValues(alpha: 0.25),
                              borderRadius: BorderRadius.circular(4),
                            ),
                            child: Text(provider.t('cal.today'),
                                style: const TextStyle(
                                    color: Color(0xFFC4B5FD),
                                    fontSize: 10,
                                    fontWeight: FontWeight.w600)),
                          )
                        else
                          Tooltip(
                            message: context
                                .read<MindMapProvider>()
                                .t('cal.backToToday'),
                            child: InkWell(
                              onTap: () =>
                                  setState(() => _timelineDayOffset = 0),
                              borderRadius: BorderRadius.circular(4),
                              child: Container(
                                padding: const EdgeInsets.symmetric(
                                    horizontal: 6, vertical: 2),
                                decoration: BoxDecoration(
                                  color: Colors.white.withValues(alpha: 0.12),
                                  borderRadius: BorderRadius.circular(4),
                                ),
                                child: Text(
                                  _timelineDayOffset == 1
                                      ? provider.t('tl.tomorrow')
                                      : _timelineDayOffset == -1
                                          ? provider.t('tl.yesterday')
                                          : _timelineDayOffset > 1
                                              ? provider
                                                  .t('tl.daysLater')
                                                  .replaceFirst('{n}',
                                                      '$_timelineDayOffset')
                                              : provider
                                                  .t('tl.daysAgo')
                                                  .replaceFirst('{n}',
                                                      '${-_timelineDayOffset}'),
                                  style: const TextStyle(
                                      color: Colors.white70,
                                      fontSize: 10,
                                      fontWeight: FontWeight.w600),
                                ),
                              ),
                            ),
                          ),
                      ]),
                      // 絵文字 📅 はフォントによって「17」 等の固定日付付きで
                      //   描画される (= ユーザー指摘) ため、 日付を持たない
                      //   Material アイコンに置き換える。
                      Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          const Icon(Icons.event_note_rounded,
                              color: Colors.white54, size: 12),
                          const SizedBox(width: 4),
                          Text(
                            provider
                                .t('tl.eventCount')
                                .replaceFirst('{n}', '$eventCount'),
                            style: const TextStyle(
                                color: Colors.white54, fontSize: 11),
                          ),
                        ],
                      ),
                      // ── 予定通知のリード時間 (= 開始の何分前に通知するか) ──
                      //    タップで分数を入力。 デフォルト 15 分前 (= ユーザー要望)。
                      const SizedBox(height: 2),
                      InkWell(
                        onTap: () async {
                          final v = await _showIntInputDialog(
                            title: provider.t('tl.notifyLeadTitle'),
                            initial: provider.eventNotifyLeadMinutes,
                            min: 0,
                            max: 1440,
                          );
                          if (v != null) {
                            await provider.setEventNotifyLeadMinutes(v);
                            if (mounted) setState(() {});
                          }
                        },
                        borderRadius: BorderRadius.circular(4),
                        child: Padding(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 2, vertical: 1),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              const Icon(Icons.notifications_active_rounded,
                                  color: Colors.white38, size: 11),
                              const SizedBox(width: 3),
                              Text(
                                provider.eventNotifyLeadMinutes > 0
                                    ? provider.t('tl.notifyLead').replaceFirst(
                                        '{n}',
                                        '${provider.eventNotifyLeadMinutes}')
                                    : provider.t('tl.notifyAtStart'),
                                style: const TextStyle(
                                    color: Colors.white38, fontSize: 10),
                              ),
                              const SizedBox(width: 2),
                              const Icon(Icons.edit,
                                  color: Colors.white24, size: 10),
                            ],
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
                if (_isDesktop)
                  Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                    decoration: BoxDecoration(
                      color: Colors.white.withValues(alpha: 0.07),
                      borderRadius: BorderRadius.circular(4),
                      border: Border.all(color: Colors.white12),
                    ),
                    child: const Text('Ctrl+Shift+T',
                        style: TextStyle(
                            color: Colors.white38,
                            fontSize: 9,
                            fontWeight: FontWeight.w600)),
                  ),
              ]),
            ),
            const Divider(color: Colors.white12, height: 1),
            Padding(
              padding: const EdgeInsets.fromLTRB(10, 7, 10, 7),
              child: SizedBox(
                width: double.infinity,
                height: 34,
                child: OutlinedButton.icon(
                  style: OutlinedButton.styleFrom(
                    foregroundColor: const Color(0xFFC4B5FD),
                    side: const BorderSide(color: Color(0x667C6CFF)),
                    visualDensity: VisualDensity.compact,
                  ),
                  onPressed: () => _showAddCalendarEventDialog(
                    ctx,
                    provider,
                    todayKey,
                    '',
                    '',
                    initialAllDay: true,
                  ),
                  icon: const Icon(Icons.playlist_add_check_rounded, size: 18),
                  label: Text(
                    provider.t('tl.registerTodo'),
                    style: const TextStyle(
                        fontSize: 12, fontWeight: FontWeight.w700),
                  ),
                ),
              ),
            ),
            const Divider(color: Colors.white12, height: 1),
            // ── 終日の予定 (= ユーザー要望: その日の終日予定を常に上部に表示) ──
            if (allDayEvents.isNotEmpty)
              Container(
                width: double.infinity,
                padding: const EdgeInsets.fromLTRB(8, 4, 8, 5),
                color: timelineDrawerPanel,
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Padding(
                      padding: const EdgeInsets.only(right: 6, top: 4),
                      child: Text(provider.t('cal.allDay'),
                          style: const TextStyle(
                              color: Colors.white38, fontSize: 10)),
                    ),
                    Expanded(
                      child: Wrap(
                        spacing: 6,
                        runSpacing: 4,
                        children: [
                          for (final e in allDayEvents)
                            GestureDetector(
                              onTap: () => _showAddCalendarEventDialog(
                                  ctx, provider, todayKey, '', '',
                                  editEvent: e),
                              child: Container(
                                padding: const EdgeInsets.symmetric(
                                    horizontal: 8, vertical: 3),
                                decoration: BoxDecoration(
                                  color: (e.colorArgb != null
                                          ? Color(e.colorArgb!)
                                          : const Color(0xFF4FC3F7))
                                      .withValues(alpha: 0.85),
                                  borderRadius: BorderRadius.circular(6),
                                ),
                                child: Text(
                                  e.title.isEmpty
                                      ? provider.t('tl.untitledEvent')
                                      : e.title,
                                  style: const TextStyle(
                                      color: Colors.white,
                                      fontSize: 11,
                                      fontWeight: FontWeight.w600),
                                ),
                              ),
                            ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            if (allDayEvents.isNotEmpty)
              const Divider(color: Colors.white12, height: 1),
            // ── 24 時間時刻軸 ──
            // NotificationListener<ScrollNotification> で onNotification を
            //   true (= 消費) にし、 タイムライン内のスクロールが背後のキャン
            //   バスへ漏れるのを防ぐ (= ユーザー要望)。
            Expanded(
              child: NotificationListener<ScrollNotification>(
                onNotification: (_) => true,
                child: SingleChildScrollView(
                  key: _timelineDrawerViewportKey,
                  controller: controller,
                  child: GestureDetector(
                    // ── タイムラインの空白部分をタップ → 予定追加ダイアログ
                    //    (= ユーザー要望: タイムラインに自由に予定を追加できる
                    //    ように) ──
                    // タップ位置の Y 座標から時刻 (分) を逆算し、 予定作成ダイアログ
                    //   を開く。 子の項目 (= 既存予定/活動 Container) は
                    //   GestureDetector.onTap が伝播しないので、 空白タップだけ
                    //   ここに来る。
                    behavior: HitTestBehavior.translucent,
                    onTapUp: (d) {
                      final dy = d.localPosition.dy;
                      // 睡眠圧縮を考慮して y → 分 に変換 (= ユーザー要望)。
                      final mins = tlMinForY(dy);
                      final h = (mins ~/ 60).clamp(0, 23);
                      final mRound = ((mins % 60) ~/ 15) * 15;
                      final startStr = '${two(h)}:${two(mRound)}';
                      final endH = (h + 1).clamp(0, 23);
                      final endStr = '${two(endH)}:${two(mRound)}';
                      _showAddCalendarEventDialog(
                          ctx, provider, todayKey, startStr, endStr);
                    },
                    child: SizedBox(
                      height: totalHeight,
                      child: Stack(
                        children: [
                          // ── 各時間の罫線とラベル (起きている時間のみ) ──
                          // 睡眠時間は個別の行を出さず、 下の「睡眠コンパクト帯」 に
                          //   まとめて表示する (= ユーザー要望: 睡眠ゾーンを削除した
                          //   ようなコンパクト表示)。 top/height は圧縮込みの hourY を使う。
                          for (int h = 0; h < 24; h++)
                            if (!_isSleepHour(h))
                              Positioned(
                                left: 0,
                                right: 0,
                                top: hourY[h],
                                height: hourY[h + 1] - hourY[h],
                                child: Container(
                                  decoration: BoxDecoration(
                                    border: Border(
                                      top: BorderSide(
                                          color: timelineDrawerLine,
                                          width: 0.5),
                                    ),
                                  ),
                                  child: Padding(
                                    padding:
                                        const EdgeInsets.only(left: 6, top: 2),
                                    child: Text('${two(h)}:00',
                                        style: const TextStyle(
                                            color: Colors.white38,
                                            fontSize: 10)),
                                  ),
                                ),
                              ),
                          // ── 睡眠ゾーンのコンパクト帯 (= ユーザー要望) ──
                          // 連続する睡眠時間を 1 本の帯にまとめ、 💤 と時刻範囲を表示。
                          for (int h = 0; h < 24; h++)
                            if (_isSleepHour(h) &&
                                (h == 0 || !_isSleepHour(h - 1)))
                              Builder(builder: (_) {
                                int endH = h;
                                while (endH < 24 && _isSleepHour(endH)) {
                                  endH++;
                                }
                                final endLabel =
                                    endH >= 24 ? '24:00' : '${two(endH)}:00';
                                return Positioned(
                                  left: 0,
                                  right: 0,
                                  top: hourY[h],
                                  height: hourY[endH] - hourY[h],
                                  child: Container(
                                    decoration: BoxDecoration(
                                      color: timelineSleepPanel,
                                      border: Border(
                                        top: BorderSide(
                                            color: timelineDrawerLine,
                                            width: 0.5),
                                        bottom: BorderSide(
                                            color: timelineDrawerLine,
                                            width: 0.5),
                                      ),
                                    ),
                                    alignment: Alignment.centerLeft,
                                    padding: const EdgeInsets.only(left: 8),
                                    child: Text(
                                      '💤 ${two(h)}:00〜$endLabel',
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                      style: const TextStyle(
                                          color: Color(0xFF8AA0EB),
                                          fontSize: 9,
                                          fontWeight: FontWeight.w700),
                                    ),
                                  ),
                                );
                              }),
                          // 現在時刻ライン (= 赤い水平線、 今日のみ表示)。
                          // ラベルは realNow（実際の現在時刻）を使う。以前は now
                          // （表示日の 0:00）を使っていたため常に "00:00" になっていた
                          // （= ユーザー報告のバグ）。
                          if (isToday)
                            Positioned(
                              left: 48,
                              right: 8,
                              top: tlY(nowMin) - 1,
                              height: 2,
                              child: Container(
                                decoration: BoxDecoration(
                                  color: const Color(0xFFE57373),
                                  boxShadow: [
                                    BoxShadow(
                                        color: const Color(0xFFE57373)
                                            .withValues(alpha: 0.5),
                                        blurRadius: 4),
                                  ],
                                ),
                              ),
                            ),
                          if (isToday)
                            Positioned(
                              left: 4,
                              top: tlY(nowMin) - 7,
                              child: Container(
                                padding: const EdgeInsets.symmetric(
                                    horizontal: 4, vertical: 1),
                                decoration: BoxDecoration(
                                  color: const Color(0xFFE57373),
                                  borderRadius: BorderRadius.circular(2),
                                ),
                                child: Text(
                                  '${two(realNow.hour)}:${two(realNow.minute)}',
                                  style: const TextStyle(
                                      color: Colors.white,
                                      fontSize: 9,
                                      fontWeight: FontWeight.w700),
                                ),
                              ),
                            ),
                          // 各項目を絶対配置 (終日 = startMin<0 は上部固定セクション
                          //   に出すのでグリッドからは除外)。
                          for (final it in items
                              .where((it) => (it['startMin'] as int) >= 0))
                            (() {
                              final isEvent = it['kind'] == 'event';
                              final eventId = it['eventId'] as String?;
                              final isOwn = isEvent &&
                                  it['isOthers'] != true &&
                                  eventId != null;
                              final dragging = eventId != null &&
                                  eventId == _timelineDraggingId;
                              final selected = isEvent &&
                                  eventId != null &&
                                  eventId == _selectedTimelineEventId;
                              final baseMin = (it['startMin'] as int) < 0
                                  ? 0
                                  : (it['startMin'] as int);
                              final color = it['color'] as Color;
                              // ドラッグ中の予定は「掴んだカーソル位置」 に追従させる
                              //   (= ユーザー要望: 24時を跨いでもカーソルと予定が
                              //   大きく乖離しないように)。 算出できなければ baseMin。
                              final bool resizingThis = eventId != null &&
                                  eventId == _timelineResizingId;
                              // 睡眠圧縮を考慮した y 座標。 ドラッグ中はカーソル基準の
                              //   content-Y をそのまま使い、 それ以外は分→y 変換 (tlY)。
                              final double topPx = resizingThis
                                  ? tlY(_timelineResizeStartMin ?? baseMin)
                                  : dragging
                                      ? (_timelineDragEventTopContent() ??
                                          tlY(baseMin))
                                      : tlY(baseMin);
                              // 重なり用の列番号 / 列数 (= 横並び配置)。
                              final lkey =
                                  'tlitem_${eventId ?? it['nodeId'] ?? baseMin}';
                              final lane = laneOf[lkey] ?? 0;
                              final cols = colsOf[lkey] ?? 1;
                              // FractionallySizedBox(widthFactor:1/cols) を列スロットに
                              // 正しく寄せる Alignment 値。 旧 `(2l+1)/cols-1` は
                              // 重なる不具合があった (= ユーザー報告) ので正しい式に修正。
                              final alignX = cols <= 1
                                  ? 0.0
                                  : (2 * lane + 1 - cols) / (cols - 1);
                              return Positioned(
                                key: ValueKey(lkey),
                                left: 50,
                                right: 8,
                                top: topPx.clamp(0.0, totalHeight).toDouble(),
                                height: (() {
                                  // リサイズ中はドラッグ中の開始/終了分で高さを出す
                                  // (= ユーザー要望: 上も下も境界ドラッグで長さ変更)。
                                  final resizing = eventId != null &&
                                      eventId == _timelineResizingId;
                                  final s = resizing
                                      ? (_timelineResizeStartMin ??
                                          (it['startMin'] as int))
                                      : (it['startMin'] as int);
                                  final e = resizing
                                      ? (_timelineResizeEndMin ??
                                          (it['endMin'] as int))
                                      : (it['endMin'] as int);
                                  // 圧縮込みの表示高さ (tlY 差分)。 最小 44px。 上限なし。
                                  final spanPx = (tlY(e) - tlY(s)).abs();
                                  return spanPx < 44 ? 44.0 : spanPx;
                                })(),
                                child: Align(
                                  alignment: Alignment(alignX, 0),
                                  child: FractionallySizedBox(
                                    widthFactor: 1.0 / cols,
                                    child: Stack(children: [
                                      Positioned.fill(
                                        child: GestureDetector(
                                          // タップ: メモはノード選択、 予定は選択 (= Del 対象)。
                                          onTap: it['kind'] == 'memo'
                                              ? () {
                                                  Navigator.pop(ctx);
                                                  provider.selectNode(
                                                      it['nodeId'] as String);
                                                }
                                              : (isEvent && eventId != null
                                                  ? () {
                                                      setState(() =>
                                                          _selectedTimelineEventId =
                                                              eventId);
                                                      // 自分の予定はタップで編集ダイアログ
                                                      //   （削除ボタン付き）を開く。
                                                      if (!isOwn) return;
                                                      CalendarEvent? ev;
                                                      for (final e in events) {
                                                        if (e.id == eventId) {
                                                          ev = e;
                                                          break;
                                                        }
                                                      }
                                                      if (ev != null) {
                                                        _showAddCalendarEventDialog(
                                                            ctx,
                                                            provider,
                                                            todayKey,
                                                            ev.startTime ?? '',
                                                            ev.endTime ?? '',
                                                            editEvent: ev);
                                                      }
                                                    }
                                                  : null),
                                          // ── ドラッグで時間を移動 (自分の予定のみ) ──
                                          onVerticalDragStart: isOwn
                                              ? (d) {
                                                  // ドラッグ開始時の表示日 / 日付キー / アイテムを
                                                  //   記録 (日跨ぎの確定先計算に使う)。
                                                  _timelineDragStartDayOffset =
                                                      _timelineDayOffset;
                                                  _timelineDragStartDateKey =
                                                      todayKey;
                                                  _timelineDraggingItem = it;
                                                  // 掴んだカーソルと予定上端のズレを記録し、
                                                  //   ドラッグ中はそのズレを保ってカーソルに
                                                  //   追従させる。
                                                  final c =
                                                      _timelineDrawerScrollCtrl;
                                                  final rb =
                                                      _timelineDrawerViewportKey
                                                              .currentContext
                                                              ?.findRenderObject()
                                                          as RenderBox?;
                                                  if (c != null &&
                                                      c.hasClients &&
                                                      rb != null) {
                                                    final vpTop = rb
                                                        .localToGlobal(
                                                            Offset.zero)
                                                        .dy;
                                                    final eventTopScreen =
                                                        vpTop +
                                                            baseMin -
                                                            c.position.pixels;
                                                    _timelineDragGrabOffset =
                                                        d.globalPosition.dy -
                                                            eventTopScreen;
                                                  } else {
                                                    _timelineDragGrabOffset = 0;
                                                  }
                                                  _timelineDragLastGlobalPos =
                                                      d.globalPosition;
                                                  setState(() {
                                                    _timelineDraggingId =
                                                        eventId;
                                                    _selectedTimelineEventId =
                                                        eventId;
                                                  });
                                                  _startTimelineDragAutoScroll();
                                                }
                                              : null,
                                          onVerticalDragUpdate: isOwn
                                              ? (d) {
                                                  _timelineDragLastGlobalPos =
                                                      d.globalPosition;
                                                  // 位置はカーソルから算出するので再ビルドで反映。
                                                  setState(() {});
                                                }
                                              : null,
                                          onVerticalDragEnd: isOwn
                                              ? (_) => _commitTimelineDrag(
                                                  provider, todayKey, it)
                                              : null,
                                          onVerticalDragCancel: isOwn
                                              ? () {
                                                  _stopTimelineDragAutoScroll();
                                                  setState(() {
                                                    _timelineDraggingId = null;
                                                    _timelineDragLastGlobalPos =
                                                        null;
                                                    _timelineDraggingItem =
                                                        null;
                                                    _timelineDragStartDateKey =
                                                        null;
                                                  });
                                                }
                                              : null,
                                          child: Container(
                                            // 横並び時は左右に隙間を空けて隣の予定とくっつか
                                            // ないようにする (= ユーザー要望: 被らないように)。
                                            margin: EdgeInsets.only(
                                                bottom: 1,
                                                top: 1,
                                                left: cols > 1 ? 2 : 0,
                                                right: cols > 1 ? 2 : 0),
                                            padding: const EdgeInsets.symmetric(
                                                horizontal: 8, vertical: 4),
                                            decoration: BoxDecoration(
                                              color: color.withValues(
                                                  alpha:
                                                      selected ? 0.38 : 0.22),
                                              borderRadius:
                                                  BorderRadius.circular(6),
                                              border: Border.all(
                                                  color: color.withValues(
                                                      alpha:
                                                          selected ? 1.0 : 0.6),
                                                  width: selected ? 2 : 1),
                                            ),
                                            child: Row(
                                              crossAxisAlignment:
                                                  CrossAxisAlignment.start,
                                              children: [
                                                Icon(
                                                  it['kind'] == 'event'
                                                      ? Icons.event_note_rounded
                                                      : Icons.smart_toy_rounded,
                                                  color: color,
                                                  size: 12,
                                                ),
                                                const SizedBox(width: 4),
                                                Expanded(
                                                  child: Column(
                                                    crossAxisAlignment:
                                                        CrossAxisAlignment
                                                            .start,
                                                    children: [
                                                      Text(
                                                        it['title'] as String,
                                                        style: const TextStyle(
                                                            color: Colors.white,
                                                            fontSize: 11,
                                                            fontWeight:
                                                                FontWeight
                                                                    .w600),
                                                        maxLines: 1,
                                                        overflow: TextOverflow
                                                            .ellipsis,
                                                      ),
                                                      if ((it['subtitle']
                                                              as String)
                                                          .isNotEmpty)
                                                        Text(
                                                          it['subtitle']
                                                              as String,
                                                          style:
                                                              const TextStyle(
                                                                  color: Colors
                                                                      .white54,
                                                                  fontSize: 9),
                                                          maxLines: 1,
                                                          overflow: TextOverflow
                                                              .ellipsis,
                                                        ),
                                                    ],
                                                  ),
                                                ),
                                              ],
                                            ),
                                          ),
                                        ),
                                      ),
                                      // ── 上端/下端のリサイズハンドル (= ユーザー要望:
                                      //    見えるマークは消し、 上も下も境界ドラッグで
                                      //    長さ変更) ── どちらも透明な当たり判定のみ。
                                      if (isOwn) ...[
                                        // 上端: 開始時刻を変更
                                        Positioned(
                                          left: 0,
                                          right: 0,
                                          top: 0,
                                          height: 10,
                                          child: MouseRegion(
                                            cursor:
                                                SystemMouseCursors.resizeUpDown,
                                            child: GestureDetector(
                                              behavior: HitTestBehavior.opaque,
                                              onVerticalDragStart: (d) {
                                                _timelineResizeGrabY =
                                                    d.globalPosition.dy;
                                                _timelineResizeOrigStart =
                                                    it['startMin'] as int;
                                                _timelineResizeStartEnd =
                                                    it['endMin'] as int;
                                                setState(() {
                                                  _timelineResizingId = eventId;
                                                  _timelineResizeStartMin =
                                                      it['startMin'] as int;
                                                  _timelineResizeEndMin =
                                                      it['endMin'] as int;
                                                });
                                              },
                                              onVerticalDragUpdate: (d) {
                                                final e =
                                                    _timelineResizeStartEnd ??
                                                        (it['endMin'] as int);
                                                final delta = d
                                                        .globalPosition.dy -
                                                    (_timelineResizeGrabY ??
                                                        d.globalPosition.dy);
                                                int ns =
                                                    ((_timelineResizeOrigStart ??
                                                                (it['startMin']
                                                                    as int)) +
                                                            delta)
                                                        .round();
                                                ns = (ns / 5).round() * 5;
                                                if (ns < 0) ns = 0;
                                                if (ns > e - 15) ns = e - 15;
                                                setState(() =>
                                                    _timelineResizeStartMin =
                                                        ns);
                                              },
                                              onVerticalDragEnd: (_) =>
                                                  _commitTimelineResize(
                                                      provider, todayKey, it),
                                            ),
                                          ),
                                        ),
                                        // 下端: 終了時刻を変更
                                        Positioned(
                                          left: 0,
                                          right: 0,
                                          bottom: 0,
                                          height: 10,
                                          child: MouseRegion(
                                            cursor:
                                                SystemMouseCursors.resizeUpDown,
                                            child: GestureDetector(
                                              behavior: HitTestBehavior.opaque,
                                              onVerticalDragStart: (d) {
                                                _timelineResizeGrabY =
                                                    d.globalPosition.dy;
                                                _timelineResizeOrigStart =
                                                    it['startMin'] as int;
                                                _timelineResizeStartEnd =
                                                    it['endMin'] as int;
                                                setState(() {
                                                  _timelineResizingId = eventId;
                                                  _timelineResizeStartMin =
                                                      it['startMin'] as int;
                                                  _timelineResizeEndMin =
                                                      it['endMin'] as int;
                                                });
                                              },
                                              onVerticalDragUpdate: (d) {
                                                final s =
                                                    _timelineResizeStartMin ??
                                                        (it['startMin'] as int);
                                                final delta = d
                                                        .globalPosition.dy -
                                                    (_timelineResizeGrabY ??
                                                        d.globalPosition.dy);
                                                int ne =
                                                    ((_timelineResizeStartEnd ??
                                                                (it['endMin']
                                                                    as int)) +
                                                            delta)
                                                        .round();
                                                ne = (ne / 5).round() * 5;
                                                if (ne < s + 15) ne = s + 15;
                                                if (ne > 24 * 60) ne = 24 * 60;
                                                setState(() =>
                                                    _timelineResizeEndMin = ne);
                                              },
                                              onVerticalDragEnd: (_) =>
                                                  _commitTimelineResize(
                                                      provider, todayKey, it),
                                            ),
                                          ),
                                        ),
                                      ],
                                    ]),
                                  ),
                                ),
                              );
                            })(),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ]),
        ),
      ),
    );
  }

  /// 予定追加ダイアログ (= ユーザー要望: タイムラインに自由に予定を
  /// 追加できるように)。 タイムラインの空白部分をタップした位置の時刻を
  /// 初期値として、 タイトル + 開始/終了時刻を入力させる。
  Future<void> _showAddCalendarEventDialog(BuildContext ctx,
      MindMapProvider provider, String dateKey, String start, String end,
      {CalendarEvent? editEvent, bool initialAllDay = false}) async {
    final isEdit = editEvent != null;
    final titleCtrl = TextEditingController(text: editEvent?.title ?? '');
    final startCtrl =
        TextEditingController(text: editEvent?.startTime ?? start);
    final endCtrl = TextEditingController(text: editEvent?.endTime ?? end);
    // 終日フラグ (= ユーザー要望: 予定を終日登録できるように)。 開始時刻が
    //   空の既存予定 (= 既に終日扱い) を開いた時は ON で開く。
    bool allDay = isEdit
        ? (editEvent.startTime == null || editEvent.startTime!.trim().isEmpty)
        : initialAllDay;
    bool lockDuringEvent = editEvent?.lockDuringEvent ?? false;
    bool appLockDuringEvent = editEvent?.appLockDuringEvent ?? false;
    // 戻り値: 'save' = 追加/保存, 'delete' = 削除, null = キャンセル
    final result = await showDialog<String>(
      context: ctx,
      builder: (dctx) => StatefulBuilder(
        builder: (dctx, setSt) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            Icon(
                isEdit
                    ? Icons.edit_calendar_rounded
                    : Icons.event_available_rounded,
                color: const Color(0xFF6C63FF),
                size: 20),
            const SizedBox(width: 10),
            Text(
                isEdit
                    ? '${provider.t('tl.editEvent')} ($dateKey)'
                    : '${provider.t('tl.addEvent')} ($dateKey)',
                style: const TextStyle(color: Colors.white, fontSize: 14)),
          ]),
          content: SizedBox(
            width: 320,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: titleCtrl,
                  autofocus: true,
                  style: const TextStyle(color: Colors.white),
                  // Enter でそのまま追加/保存（= ユーザー要望）
                  onSubmitted: (_) => Navigator.pop(dctx, 'save'),
                  decoration: InputDecoration(
                    hintText: provider.t('tl.eventTitle'),
                    hintStyle: const TextStyle(color: Colors.white38),
                    filled: true,
                    fillColor: Colors.white.withValues(alpha: 0.07),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(8),
                      borderSide: BorderSide.none,
                    ),
                  ),
                ),
                const SizedBox(height: 10),
                if (!allDay)
                  Row(children: [
                    Expanded(
                      child: TextField(
                        controller: startCtrl,
                        style: const TextStyle(color: Colors.white),
                        onSubmitted: (_) => Navigator.pop(dctx, 'save'),
                        decoration: InputDecoration(
                          labelText: provider.t('tl.startHHmm'),
                          labelStyle: const TextStyle(color: Colors.white54),
                          filled: true,
                          fillColor: Colors.white.withValues(alpha: 0.07),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(8),
                            borderSide: BorderSide.none,
                          ),
                        ),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: TextField(
                        controller: endCtrl,
                        style: const TextStyle(color: Colors.white),
                        onSubmitted: (_) => Navigator.pop(dctx, 'save'),
                        decoration: InputDecoration(
                          labelText: provider.t('tl.endHHmm'),
                          labelStyle: const TextStyle(color: Colors.white54),
                          filled: true,
                          fillColor: Colors.white.withValues(alpha: 0.07),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(8),
                            borderSide: BorderSide.none,
                          ),
                        ),
                      ),
                    ),
                  ]),
                // ── 終日トグル (= ユーザー要望: 時刻の下に配置) ──
                // ON の時は時刻行を隠し、 保存時に開始/終了を null (= 終日扱い)。
                SwitchListTile(
                  contentPadding: EdgeInsets.zero,
                  dense: true,
                  title: Text(provider.t('cal.allDay'),
                      style:
                          const TextStyle(color: Colors.white, fontSize: 14)),
                  value: allDay,
                  activeColor: const Color(0xFF6C63FF),
                  onChanged: (v) => setSt(() {
                    allDay = v;
                    if (v) {
                      lockDuringEvent = false;
                      appLockDuringEvent = false;
                    }
                  }),
                ),
                // 予定に紐づくロックは Android でしか発動しないので、
                //   PC では出さない (= ユーザー要望: PC 版には付けない)。
                if (!allDay && !_isDesktop)
                  Column(
                    children: [
                      SwitchListTile(
                        contentPadding: EdgeInsets.zero,
                        dense: true,
                        // 多言語対応 (= ユーザー要望: 中の項目も日本語だった)。
                        title: Text(provider.t('cal.lockDuringEvent'),
                            style: const TextStyle(
                                color: Colors.white, fontSize: 14)),
                        subtitle: Text(provider.t('cal.lockDuringEventDesc'),
                            style: const TextStyle(
                                color: Colors.white54, fontSize: 11)),
                        value: lockDuringEvent,
                        activeColor: const Color(0xFF4FC3F7),
                        onChanged: (v) => setSt(() => lockDuringEvent = v),
                      ),
                      SwitchListTile(
                        contentPadding: EdgeInsets.zero,
                        dense: true,
                        title: Text(provider.t('cal.appLockDuringEvent'),
                            style: const TextStyle(
                                color: Colors.white, fontSize: 14)),
                        subtitle: Text(provider.t('cal.appLockDuringEventDesc'),
                            style: const TextStyle(
                                color: Colors.white54, fontSize: 11)),
                        value: appLockDuringEvent,
                        activeColor: const Color(0xFFEF5350),
                        onChanged: (v) => setSt(() => appLockDuringEvent = v),
                      ),
                    ],
                  ),
              ],
            ),
          ),
          actions: [
            // 編集時のみ: キャンセルの左に削除ボタン（= ユーザー要望）
            if (isEdit)
              TextButton.icon(
                onPressed: () => Navigator.pop(dctx, 'delete'),
                icon: const Icon(Icons.delete_outline_rounded,
                    color: Color(0xFFE57373), size: 18),
                label: Text(provider.t('btn.delete'),
                    style: const TextStyle(color: Color(0xFFE57373))),
              ),
            TextButton(
              onPressed: () => Navigator.pop(dctx, null),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              // foregroundColor を白に指定しないとボタン文字が見えない
              // （= ユーザー報告: 追加ボタンの文字が見えない）
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6C63FF),
                  foregroundColor: Colors.white),
              onPressed: () => Navigator.pop(dctx, 'save'),
              child:
                  Text(isEdit ? provider.t('btn.save') : provider.t('btn.add')),
            ),
          ],
        ),
      ),
    );
    if (result == 'delete' && editEvent != null) {
      await provider.removeCalendarEvent(dateKey, editEvent.id);
      return;
    }
    if (result != 'save') return;
    final title = titleCtrl.text.trim();
    if (title.isEmpty) return;
    // 終日の時は時刻を持たせない (= startTime/endTime を null に)。
    final st = allDay
        ? null
        : (startCtrl.text.trim().isEmpty ? null : startCtrl.text.trim());
    final et = allDay
        ? null
        : (endCtrl.text.trim().isEmpty ? null : endCtrl.text.trim());
    final shouldLockDuringEvent =
        lockDuringEvent && !allDay && st != null && et != null;
    final shouldAppLockDuringEvent =
        appLockDuringEvent && !allDay && st != null && et != null;
    if (editEvent != null) {
      await provider.updateCalendarEvent(
        dateKey,
        editEvent.id,
        title,
        memo: editEvent.memo,
        startTime: st,
        endTime: et,
        colorArgb: editEvent.colorArgb ?? 0xFF6C63FF,
        lockDuringEvent: shouldLockDuringEvent,
        appLockDuringEvent: shouldAppLockDuringEvent,
      );
      // 予定が変更されたら「通知済み」 をリセットして再通知できるように。
      _resetEventNotifyGuards(editEvent.id);
    } else {
      await provider.addCalendarEvent(
        dateKey,
        title,
        startTime: st,
        endTime: et,
        colorArgb: 0xFF6C63FF,
        lockDuringEvent: shouldLockDuringEvent,
        appLockDuringEvent: shouldAppLockDuringEvent,
      );
    }
    // 追加/編集直後の通知スケジュール (= ユーザー要望: 予定は通知される)。
    _schedulePendingEventNotifications(provider);
    _checkFocusLockSchedule();
  }

  /// 今日の未通過予定の startTime を Timer で監視し、 該当時刻に到達したら
  /// SnackBar / バナーで通知する (= ユーザー要望: 予定は通知されるように)。
  void _schedulePendingEventNotifications(MindMapProvider provider) {
    final now = DateTime.now();
    String two(int n) => n.toString().padLeft(2, '0');
    final todayKey = '${now.year}-${two(now.month)}-${two(now.day)}';
    // ── 通知リード時間 (= 開始時刻の何分前に通知するか。 デフォルト 15 分前) ──
    final lead = provider.eventNotifyLeadMinutes;
    final events = provider.eventsOn(todayKey);
    for (final ev in events) {
      if (ev.startTime == null || !ev.startTime!.contains(':')) continue;
      final parts = ev.startTime!.split(':');
      final h = int.tryParse(parts[0]) ?? 0;
      final m = int.tryParse(parts.length > 1 ? parts[1] : '0') ?? 0;
      final evDt = DateTime(now.year, now.month, now.day, h, m);
      final delta = evDt.difference(now);
      if (delta.isNegative) continue; // 既に開始時刻を過ぎている
      if (delta.inMinutes > 24 * 60) continue; // 24h 以上先は無視
      // 通知を出す時刻 = 開始時刻 - lead 分。 既にその時刻を過ぎていれば即時通知。
      var fireDelta = delta - Duration(minutes: lead);
      if (fireDelta.isNegative) fireDelta = Duration.zero;
      // 既に登録済みの場合の重複防止用 ID
      final key = 'cal_${ev.id}_$todayKey';
      if (_scheduledNotifications.contains(key)) continue;
      _scheduledNotifications.add(key);
      // リードタイム到達で 1 度だけシステム通知 (= ユーザー要望)。
      // キーは残したまま (_scheduledNotifications.remove しない) なので、
      // タイムラインを開き直しても再スケジュール・再通知されない。
      // 実際の重複抑止は _notifyTimelineEventOnce の共有ガードが担う。
      Timer(fireDelta, () {
        if (!mounted) return;
        _notifyTimelineEventOnce(ev);
      });
    }
  }

  /// タイムラインの予定をドラッグ移動した結果を確定する (= ユーザー要望:
  /// 予定をドラッグで自由に時間移動できるように)。 開始時刻を 5 分刻みに
  /// スナップし、 終了時刻があれば同じ量だけずらす。 タイトル/メモ/色は維持。
  void _commitTimelineDrag(
      MindMapProvider provider, String dateKey, Map<String, dynamic> it) {
    _stopTimelineDragAutoScroll();
    // ドラッグ中に日付をめくっている場合、 予定が今も存在するのは「ドラッグ
    //   開始日」 なので、 確定の基準日キーはそちらを使う (= 表示中の日では
    //   予定が見つからず更新されない不具合を防ぐ)。
    final dk = _timelineDragStartDateKey ?? dateKey;
    // 確定時刻 = 掴んだカーソルの最終位置 (= 表示日上の content 分) +
    //   ドラッグ中にめくった日数。 これでカーソルを離した位置に確定する。
    final dayDeltaCommit = _timelineDayOffset - _timelineDragStartDayOffset;
    final eventTopOnDay = _timelineDragEventTopContent();
    final eventId = it['eventId'] as String?;
    final origStart = it['startMin'] as int;
    int committedDayShift = 0; // 0時/24時を跨いだ日数 (確定後の表示日に使う)
    // 予定を更新 (開始時刻なし / 他人の予定 / 変化なし はスキップ)。
    // ドラッグ状態のリセットより先に更新して、 リビルドで即 新位置に描画する。
    if (eventId != null && origStart >= 0) {
      CalendarEvent? ev;
      for (final e in provider.eventsOn(dk)) {
        if (e.id == eventId) {
          ev = e;
          break;
        }
      }
      if (ev != null && !ev.isOthersEvent(provider.currentUid)) {
        String two(int n) => n.toString().padLeft(2, '0');
        String hhmm(int m) => '${two(m ~/ 60)}:${two(m % 60)}';
        // 絶対位置(分) → 5 分スナップ → 0時/24時を跨いだら前日/翌日へ
        //   (= ユーザー要望: 境界をシームレスに行き来)。
        // eventTopOnDay は圧縮込みの content-Y なので、 _tlMinForY で分に戻す
        //   (= 睡眠圧縮時もドロップ位置の時刻が正しくなるように)。
        int total = eventTopOnDay != null
            ? (_tlMinForY(eventTopOnDay) + dayDeltaCommit * 24 * 60)
            : origStart;
        total = (total / 5).round() * 5;
        int dayShift = 0;
        while (total < 0) {
          total += 24 * 60;
          dayShift -= 1;
        }
        while (total >= 24 * 60) {
          total -= 24 * 60;
          dayShift += 1;
        }
        committedDayShift = dayShift;
        final newStart = total; // 0〜1435
        final deltaMin = (newStart + dayShift * 24 * 60) - origStart;
        if (deltaMin != 0) {
          // 終了時刻があれば同じ量シフト（時刻部分のみ）、 無ければ維持
          String? newEnd;
          final endStr = ev.endTime;
          if (endStr != null && endStr.contains(':')) {
            final ep = endStr.split(':');
            final eMin = (int.tryParse(ep[0]) ?? 0) * 60 +
                (int.tryParse(ep.length > 1 ? ep[1] : '0') ?? 0);
            newEnd =
                hhmm(((eMin + deltaMin) % (24 * 60) + 24 * 60) % (24 * 60));
          }
          if (dayShift == 0) {
            // 同じ日内で時刻のみ更新
            // ignore: discarded_futures
            provider.updateCalendarEvent(dk, eventId, ev.title,
                memo: ev.memo,
                startTime: hhmm(newStart),
                endTime: newEnd,
                colorArgb: ev.colorArgb);
          } else {
            // 0時/24時を跨いで前日/翌日へ移動
            final base = DateTime.tryParse(dk);
            if (base != null) {
              final target = base.add(Duration(days: dayShift));
              final targetKey =
                  '${target.year}-${two(target.month)}-${two(target.day)}';
              // ignore: discarded_futures
              provider.moveCalendarEvent(dk, eventId, targetKey,
                  newStartTime: hhmm(newStart), newEndTime: newEnd);
            }
          }
        }
      }
    }
    setState(() {
      _timelineDraggingId = null;
      _timelineDragLastGlobalPos = null;
      _timelineDraggingItem = null;
      _timelineDragStartDateKey = null;
    });
    // 確定後は「移動先の日 (開始日 + 跨いだ日数)」 を表示して、 移動結果が
    //   その場で見えるようにする。
    final endOffset = _timelineDragStartDayOffset + committedDayShift;
    if (_timelineDayOffset != endOffset) {
      setState(() => _timelineDayOffset = endOffset);
    }
    // 移動 (= 時刻変更) したので通知ガードをリセットして再スケジュール
    // (= ユーザー要望: 予定を変更したら通知回数がリセット)。
    final movedId = it['eventId'] as String?;
    if (movedId != null) {
      _resetEventNotifyGuards(movedId);
      _schedulePendingEventNotifications(provider);
    }
  }

  /// 下端ドラッグでの予定の長さ変更を確定する (= ユーザー要望)。
  void _commitTimelineResize(
      MindMapProvider provider, String dateKey, Map<String, dynamic> it) {
    final eventId = it['eventId'] as String?;
    final ns = _timelineResizeStartMin;
    final ne = _timelineResizeEndMin;
    setState(() {
      _timelineResizingId = null;
      _timelineResizeStartMin = null;
      _timelineResizeEndMin = null;
    });
    if (eventId == null || ne == null) return;
    CalendarEvent? ev;
    for (final e in provider.eventsOn(dateKey)) {
      if (e.id == eventId) {
        ev = e;
        break;
      }
    }
    if (ev == null || ev.isOthersEvent(provider.currentUid)) return;
    String two(int n) => n.toString().padLeft(2, '0');
    // 上端ドラッグなら開始時刻も更新 (= ユーザー要望: 上も下も長さ変更)。
    final startStr =
        ns != null ? '${two(ns ~/ 60)}:${two(ns % 60)}' : ev.startTime;
    final endStr = '${two(ne ~/ 60)}:${two(ne % 60)}';
    // ignore: discarded_futures
    provider.updateCalendarEvent(dateKey, eventId, ev.title,
        memo: ev.memo,
        startTime: startStr,
        endTime: endStr,
        colorArgb: ev.colorArgb);
    _resetEventNotifyGuards(eventId);
    _schedulePendingEventNotifications(provider);
  }

  /// タイムラインの予定を削除する確認ダイアログ (= ユーザー要望:
  /// サイドメニューのタイムラインから予定を削除できるように)。
  Future<void> _confirmDeleteTimelineEvent(
      BuildContext ctx,
      MindMapProvider provider,
      String dateKey,
      String eventId,
      String title) async {
    final ok = await showDialog<bool>(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('tl.deleteEvent'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        content: Text(
            provider.t('tl.deleteEventConfirm').replaceFirst('{title}',
                title.isEmpty ? provider.t('tl.untitledEvent') : title),
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, false),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFE57373),
                foregroundColor: Colors.white,),
            onPressed: () => Navigator.pop(dctx, true),
            child: Text(provider.t('btn.delete'),
                style: const TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
    if (ok == true) {
      await provider.removeCalendarEvent(dateKey, eventId);
      if (_selectedTimelineEventId == eventId) {
        _selectedTimelineEventId = null;
      }
      if (mounted) setState(() {});
    }
  }

  Widget _buildDrawer(BuildContext context, MindMapProvider provider) {
    // ── ToDo モードへの分岐 (= ユーザー要望: タイムラインを廃止して
    //    ToDo のチェックリストに)。 昔の保存値 'timeline' も ToDo へ流す。 ──
    if (_drawerView == 'todo' || _drawerView == 'timeline') {
      return _buildTodoDrawer(context, provider);
    }
    return Drawer(
      backgroundColor: Color.alphaBlend(
          provider.headerColor.withValues(alpha: 0.62),
          const Color(0xFF13132A)),
      child: SafeArea(
        // Drawer は独自の FocusScope を持つため、外側 KeyboardListener には
        // Del/Backspace が届かない。drawer 内で複数選択中に「Del で一括削除」を
        // 行えるよう、ここに dedicated な Focus + onKeyEvent を仕込む。
        child: Focus(
          autofocus: true,
          // タップ・テキスト入力で奪われ得る通常のフォーカスではなく、
          // バックグラウンドで KeyEvent を黙って観察する用途。
          // 子の入力フィールドには干渉せず、Del/Backspace のみ消費する。
          onKeyEvent: (focusNode, event) {
            if (event is! KeyDownEvent && event is! KeyRepeatEvent)
              return KeyEventResult.ignored;
            // 入力欄にフォーカスがあるときは介入しない (テキスト編集を壊さない)
            final primary = FocusManager.instance.primaryFocus;
            if (primary != null && primary != focusNode) {
              final ctxW = primary.context?.widget;
              if (ctxW is EditableText) return KeyEventResult.ignored;
            }
            // ── Esc: 複数選択中はまず選択解除だけ行い、 サイドバーは閉じない
            //    (= ユーザー要望)。 選択が無ければ ignored を返して通常どおり
            //    Drawer を閉じる。 handled を返すとフレームワークの
            //    Drawer 自動クローズ (DismissIntent) まで届かず消費される。
            if (event.logicalKey == LogicalKeyboardKey.escape) {
              if (_drawerMultiSelectActive) {
                setState(() {
                  _drawerSelectedPageIds.clear();
                  _drawerSelectedFolderIds.clear();
                  _drawerLastAnchorIndex = null;
                });
                return KeyEventResult.handled;
              }
              return KeyEventResult.ignored;
            }
            if (!_drawerMultiSelectActive) return KeyEventResult.ignored;
            if (event.logicalKey == LogicalKeyboardKey.delete ||
                event.logicalKey == LogicalKeyboardKey.backspace) {
              _confirmDeleteSelectedDrawerItems(context, provider);
              return KeyEventResult.handled;
            }
            return KeyEventResult.ignored;
          },
          child: Column(children: [
            // ── マップ一覧 / タイムライン切替タブ (= ユーザー要望) ──
            _buildDrawerViewSwitcher(),
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 16, 8, 8),
              child: Row(children: [
                const Icon(Icons.map_outlined, color: Colors.white54, size: 18),
                const SizedBox(width: 10),
                Expanded(
                    child: Text(provider.t('drawer.title'),
                        style: const TextStyle(
                            color: Colors.white70,
                            fontSize: 13,
                            fontWeight: FontWeight.w600))),
                if (_isDesktop)
                  Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                    decoration: BoxDecoration(
                      color: Colors.white.withValues(alpha: 0.07),
                      borderRadius: BorderRadius.circular(4),
                      border: Border.all(color: Colors.white12),
                    ),
                    child: const Text('Ctrl+Shift+E',
                        style: TextStyle(
                            color: Colors.white38,
                            fontSize: 9,
                            fontWeight: FontWeight.w600)),
                  ),
                if (_isDesktop) const SizedBox(width: 4),
                // ── ルート (フォルダー外のページ) を Ctrl+1〜9 基準にするトグル ──
                // モバイル版では物理キーボードがないため Ctrl+1〜9 ショートカット
                // 自体が使えない → このトグルボタンも隠す。デスクトップ版では
                // 従来通り表示する。
                // 現在 shortcutFolderId が「ROOT 特殊値」と一致するなら有効状態
                // (薄紫の塗り) を表示。タップで ON/OFF。
                if (_isDesktop)
                  Builder(builder: (btnCtx) {
                    // ── いま Ctrl+1〜9 がどこを見ているか ──
                    //
                    // = ユーザー指摘「この盤面でボタンの ON/OFF を切り替えても
                    //   意味がないのでは」。 そのとおりで、 基準が未設定 (null)
                    //   でもルート指定 (sentinel) でも `pageForShortcutSlot` は
                    //   同じ「一覧のページ」 を返す。 つまり ON/OFF は同じ動き
                    //   だった。 そこで、
                    //     ・一覧が対象の時 … 点灯したままにして、 押しても
                    //       状態は変えず「いまこうなっています」 と伝えるだけ
                    //     ・フォルダーが対象の時 … 押すと一覧に戻す (意味あり)
                    //   にする。
                    final baseId = provider.shortcutFolderId;
                    final folder = (baseId != null &&
                            baseId != MindMapProvider.shortcutRootSentinel)
                        ? provider.folders
                            .where((f) => f.id == baseId)
                            .firstOrNull
                        : null;
                    // フォルダーが指定されていない = この一覧が対象。
                    final isRootShortcut = folder == null;
                    return IconButton(
                      tooltip: isRootShortcut
                          ? provider.t('root.shortcutAlready')
                          : '${provider.t('root.setShortcut')}\n'
                              '${provider.t('root.shortcutFolderNow').replaceFirst('{name}', folder.name)}',
                      padding: EdgeInsets.zero,
                      iconSize: 18,
                      constraints:
                          const BoxConstraints(minWidth: 32, minHeight: 32),
                      icon: Stack(clipBehavior: Clip.none, children: [
                        Icon(Icons.keyboard_command_key,
                            color: isRootShortcut
                                ? const Color(0xFF6C63FF)
                                : Colors.white38,
                            size: 16),
                        if (isRootShortcut)
                          Positioned(
                            right: -2,
                            top: -2,
                            child: Container(
                              width: 6,
                              height: 6,
                              decoration: const BoxDecoration(
                                color: Color(0xFF6C63FF),
                                shape: BoxShape.circle,
                              ),
                            ),
                          ),
                      ]),
                      onPressed: () async {
                        // 既に一覧が対象なら、 状態は変えずに知らせるだけ
                        // (押しても何も変わらないのに切り替わったように
                        //  見えるのを止める = ユーザー指摘)。
                        if (isRootShortcut) {
                          _appSnack(
                              context,
                              SnackBar(
                                backgroundColor: const Color(0xFF3A3A55),
                                duration: const Duration(seconds: 3),
                                content: Text(
                                    provider.t('root.shortcutAlready'),
                                    style:
                                        const TextStyle(color: Colors.white)),
                              ));
                          return;
                        }
                        await provider.setShortcutFolder(null);
                        if (!mounted) return;
                        _appSnack(
                            context,
                            SnackBar(
                              backgroundColor: const Color(0xFF6C63FF),
                              duration: const Duration(seconds: 2),
                              content: Text(provider.t('root.shortcutSet'),
                                  style: const TextStyle(color: Colors.white)),
                            ));
                      },
                    );
                  }),
                // 「+」メニュー: 新規ページ / 新規フォルダー / JSON 読み込み / フォルダー一括読み込み
                // Builder の btnCtx を anchor として渡し、ボタンの右下に
                // ポップオーバー表示する。
                Builder(builder: (btnCtx) {
                  return IconButton(
                    icon: const Icon(Icons.add, color: Colors.white54),
                    tooltip: provider.t('drawer.addMenu'),
                    onPressed: () =>
                        _showDrawerAddMenu(context, provider, btnCtx),
                  );
                }),
              ]),
            ),
            const Divider(color: Colors.white10, height: 1),
            Expanded(child: _buildDrawerBody(context, provider)),
            const SizedBox(height: 8),
          ]),
        ), // Focus
      ),
    );
  }

  /// Drawer の本体: フォルダー → そのページ → ルートページの順で表示
  Widget _buildDrawerBody(BuildContext context, MindMapProvider provider) {
    final folders = provider.folders;
    // 非表示ページをフィルタリング (= 「このページを非表示」 の項目で hidePage
    // されたページは Drawer 一覧に表示しない)。
    final rootPages = provider
        .pagesInFolder(null)
        .where((p) => !provider.isPageHidden(p.id))
        .toList();
    return Column(children: [
      // ── 複数選択中のツールバー (選択がある時のみ表示) ──
      // 選択中ページを 1 つの新規フォルダーに格納するボタン (Ctrl+G 相当)、
      // 選択解除ボタンを並べる。
      if (_drawerMultiSelectActive)
        _buildDrawerMultiSelectBar(context, provider),
      Expanded(
        // マップが多くなった時に「どこを見ているか」が分かりにくかったので、
        // 暗い drawer 上でもはっきり見える白系のスクロールバーを常時表示する。
        // RawScrollbar はカスタム配色がそのまま反映される (Theme に依存しない)。
        child: RawScrollbar(
          controller: _drawerListScrollCtrl,
          thumbColor: Colors.white.withValues(alpha: 0.85),
          // ホバー時は更に明るく強調
          thumbVisibility: true,
          trackVisibility: true,
          trackColor: Colors.white.withValues(alpha: 0.12),
          trackBorderColor: Colors.white.withValues(alpha: 0.18),
          thickness: 9,
          radius: const Radius.circular(5),
          // ノブと中身が被らないよう、コンテンツに右側パディングを入れる。
          padding: const EdgeInsets.only(right: 2, top: 4, bottom: 4),
          interactive: true,
          child: ListView(
            controller: _drawerListScrollCtrl,
            padding: const EdgeInsets.fromLTRB(0, 6, 12, 6),
            children: [
              // フォルダー(展開可能)
              for (final folder in folders) ...[
                _buildFolderHeader(context, provider, folder),
                if (folder.expanded)
                  ...provider
                      .pagesInFolder(folder.id)
                      .where((p) => !provider.isPageHidden(p.id))
                      .map((p) =>
                          _buildPageTile(context, provider, p, indent: 18)),
              ],
              // フォルダー内のページを上位階層（現在の1階層モデルではルート）へ
              // 戻すドロップ先。ルートページがまだ1件も無い場合でも表示する。
              if (folders.isNotEmpty)
                _buildDrawerRootDropTarget(context, provider),
              if (folders.isNotEmpty && rootPages.isNotEmpty)
                const Divider(color: Colors.white10, height: 8),
              // ルート(フォルダー外)のページ
              ...rootPages.map((p) => _buildPageTile(context, provider, p)),
            ],
          ),
        ),
      ),
    ]);
  }

  /// フォルダー内ページを上位階層へ戻すドロップ先。
  ///
  /// フォルダーモデルは永続化互換性のため従来どおり1階層のままなので、上位階層は
  /// `folderId == null` のルートを意味する。移動には既存の一括APIを使い、`_pages`
  /// の順序（Drawer内の並び順）を崩さない。
  Widget _buildDrawerRootDropTarget(
      BuildContext context, MindMapProvider provider) {
    return DragTarget<_DrawerPageDragData>(
      onWillAcceptWithDetails: (details) {
        final ids = details.data.pageIds.toSet();
        return provider.pages
            .any((page) => ids.contains(page.id) && page.folderId != null);
      },
      onAcceptWithDetails: (details) {
        provider.movePagesToFolder(details.data.pageIds, null);
        setState(() {
          _drawerSelectedPageIds.clear();
          _drawerSelectedFolderIds.clear();
          _drawerLastAnchorIndex = null;
        });
      },
      builder: (context, candidates, rejected) {
        final hovering = candidates.isNotEmpty;
        final accent = hovering ? const Color(0xFF43B97F) : Colors.white38;
        return AnimatedContainer(
          duration: const Duration(milliseconds: 120),
          margin: const EdgeInsets.fromLTRB(8, 6, 8, 2),
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 9),
          decoration: BoxDecoration(
            color: hovering
                ? const Color(0xFF43B97F).withValues(alpha: 0.18)
                : Colors.white.withValues(alpha: 0.035),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
              color: hovering
                  ? const Color(0xFF43B97F)
                  : Colors.white.withValues(alpha: 0.14),
              width: hovering ? 1.5 : 1,
            ),
          ),
          child: Row(children: [
            Icon(Icons.drive_file_move_rounded, color: accent, size: 18),
            const SizedBox(width: 8),
            Expanded(
              child: Text(
                provider.t('page.moveToRoot'),
                style: TextStyle(
                  color: hovering ? const Color(0xFF8CE9B9) : Colors.white60,
                  fontSize: 12,
                  fontWeight: hovering ? FontWeight.w700 : FontWeight.w500,
                ),
              ),
            ),
            Icon(Icons.keyboard_arrow_up_rounded, color: accent, size: 18),
          ]),
        );
      },
    );
  }

  /// drawer 複数選択時のツールバー。
  /// - 選択数のバッジ
  /// - 「サブフォルダーに格納」ボタン (Ctrl+G で発火する処理と同じ)
  /// - 選択解除ボタン
  Widget _buildDrawerMultiSelectBar(
      BuildContext context, MindMapProvider provider) {
    final pageCount = _drawerSelectedPageIds.length;
    final folderCount = _drawerSelectedFolderIds.length;
    final mergeablePageCount = provider.pages
        .where((p) =>
            _drawerSelectedPageIds.contains(p.id) &&
            MindMapProvider.isMergeablePageType(p.pageType))
        .length;
    // 表示テキスト: ページとフォルダーの数をどちらも考慮
    String label;
    if (pageCount > 0 && folderCount > 0) {
      label =
          '$pageCount ${provider.t('drawer.selectedSuffix')} + $folderCount${provider.t('drawer.foldersSelected')}';
    } else if (folderCount > 0) {
      label = '$folderCount${provider.t('drawer.foldersSelected')}';
    } else {
      label = '$pageCount ${provider.t('drawer.selectedSuffix')}';
    }
    // フォルダーが選択されている場合、サブフォルダー化ボタンは無効化する
    // (フォルダーをフォルダー内に入れる仕組みは未対応のため)
    final canGroup = folderCount == 0 && pageCount > 0;
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
      color: const Color(0xFF263238),
      child: Row(children: [
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
          decoration: BoxDecoration(
            color: const Color(0xFF00E5FF).withValues(alpha: 0.18),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(
                color: const Color(0xFF00E5FF).withValues(alpha: 0.5)),
          ),
          child: Text(
            label,
            style: const TextStyle(
                color: Color(0xFF00E5FF),
                fontSize: 11,
                fontWeight: FontWeight.w700),
          ),
        ),
        const SizedBox(width: 6),
        // ── ボタン列は幅が足りなければ左右に流せるようにする
        //    (= ユーザー報告: 「選択を解除」 がはみ出す)。 reverse で右端
        //    (選択解除) を最初から見えるようにし、 収まる時は右寄せになる。 ──
        Expanded(
          child: SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            reverse: true,
            child: Row(mainAxisSize: MainAxisSize.min, children: [
        // 「サブフォルダーへ格納」 (Ctrl+G と同じ動作) — ページのみの場合
        Tooltip(
          message: '${provider.t('drawer.tip.groupIntoFolder')} (Ctrl+G)',
          child: IconButton(
            icon: Icon(Icons.create_new_folder_rounded,
                color: canGroup ? const Color(0xFF43B97F) : Colors.white24,
                size: 22),
            tooltip: provider.t('drawer.tip.groupIntoFolder'),
            onPressed: canGroup
                ? () => _groupSelectedDrawerPagesIntoFolder(context, provider)
                : null,
          ),
        ),
        // 「選択ページを 1 つに統合」 (= ユーザー要望: 複数のマインドマップ/
        //   ギャラリーを中の要素までまとめて統合)。 2 ページ以上で有効。
        Tooltip(
          message: context.read<MindMapProvider>().t('merge.tooltip'),
          child: IconButton(
            icon: Icon(Icons.merge_type_rounded,
                color: mergeablePageCount >= 2
                    ? const Color(0xFFFFB347)
                    : Colors.white24,
                size: 22),
            onPressed: mergeablePageCount >= 2
                ? () => _mergeSelectedDrawerPages(context, provider)
                : null,
          ),
        ),
        // 選択ページをまとめて共有して共同編集 (= ユーザー要望)。
        Tooltip(
          message: provider.t('drawer.bulkShare'),
          child: IconButton(
            icon: Icon(Icons.public_rounded,
                color: pageCount > 0 ? const Color(0xFF43B97F) : Colors.white24,
                size: 22),
            onPressed: pageCount > 0
                ? () => _bulkShareSelectedPages(context, provider)
                : null,
          ),
        ),
        // 選択ページを 1 つの .hnmap に書き出す (= ユーザー要望: まとめて
        //   選択してページファイルとして書き出せるように)。
        Tooltip(
          message: provider.t('drawer.bulkExport'),
          child: IconButton(
            icon: Icon(Icons.archive_rounded,
                color: pageCount > 0 ? const Color(0xFF4FC3F7) : Colors.white24,
                size: 22),
            onPressed: pageCount > 0
                ? () {
                    final selected = provider.pages
                        .where((p) => _drawerSelectedPageIds.contains(p.id))
                        .toList();
                    _exportPagesBundle(context, provider, selected);
                  }
                : null,
          ),
        ),
        // 一括削除ボタン (フォルダー含めて削除可能)
        Tooltip(
          message: provider.t('drawer.bulkDelete'),
          child: IconButton(
            icon: const Icon(Icons.delete_sweep_rounded,
                color: Color(0xFFFF6B6B), size: 22),
            tooltip: provider.t('drawer.bulkDelete'),
            onPressed: () => _confirmBulkDelete(context, provider,
                folderIds: _drawerSelectedFolderIds.toList(),
                pageIds: _drawerSelectedPageIds.toList()),
          ),
        ),
        // 選択解除
        Tooltip(
          message: provider.t('drawer.tip.clearSelection'),
          child: IconButton(
            icon: const Icon(Icons.close, color: Colors.white54, size: 18),
            onPressed: () => setState(() {
              _drawerSelectedPageIds.clear();
              _drawerSelectedFolderIds.clear();
              _drawerLastAnchorIndex = null;
            }),
          ),
        ),
            ]),
          ),
        ),
      ]),
    );
  }

  /// 複数選択中の操作: 選択ページの中身を 1 つの新規ページに統合する
  /// (= ユーザー要望)。 元のページは残す。 統合後はそのページへ切替。
  Future<void> _mergeSelectedDrawerPages(
      BuildContext ctx, MindMapProvider provider) async {
    final selectedPages = provider.pages
        .where((p) => _drawerSelectedPageIds.contains(p.id))
        .toList();
    final mergeablePages = selectedPages
        .where((p) => MindMapProvider.isMergeablePageType(p.pageType))
        .toList();
    final ids = mergeablePages.map((p) => p.id).toList();
    if (ids.length < 2) {
      _appSnack(
        ctx,
        SnackBar(
          backgroundColor: const Color(0xFFFFB347),
          duration: const Duration(seconds: 3),
          content: Text(provider.t('drawer.mergeFailed'),
              style: const TextStyle(color: Colors.black)),
        ),
      );
      return;
    }
    // ── 種類の違うページ同士は統合できない (= ユーザー報告: 統合できて
    //    しまうが中身が混ざらず、 空のページができる)。 フリーノートや
    //    マークダウンの本文はページの JSON ではなく prefs にあり、 種類を
    //    跨いだ統合ではどこにも取り込めないため。 ──
    final types = mergeablePages.map((p) => p.pageType).toSet();
    if (types.length > 1) {
      _appSnack(
        ctx,
        SnackBar(
          backgroundColor: const Color(0xFFFFB347),
          duration: const Duration(seconds: 4),
          content: Text(provider.t('drawer.mergeTypeMismatch'),
              style: const TextStyle(color: Colors.black)),
        ),
      );
      return;
    }
    final mergedType = types.first;
    final ctrl =
        TextEditingController(text: provider.t('drawer.mergedMapDefault'));
    final ok = await showDialog<bool>(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('drawer.mergePages'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          Text(
              provider
                  .t('drawer.mergeDesc')
                  .replaceFirst('{count}', '${ids.length}'),
              style: const TextStyle(color: Colors.white60, fontSize: 12)),
          const SizedBox(height: 12),
          TextField(
            controller: ctrl,
            autofocus: true,
            style: const TextStyle(color: Colors.white),
            decoration: InputDecoration(
                labelText: provider.t('drawer.mergedPageName'),
                labelStyle: const TextStyle(color: Colors.white54),
                isDense: true),
          ),
        ]),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx, false),
              child: Text(provider.t('btn.cancel'))),
          ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFFFB347),
                  foregroundColor: Color(0xFF10241F),),
              onPressed: () => Navigator.pop(dctx, true),
              child: Text(provider.t('drawer.merge'))),
        ],
      ),
    );
    if (ok != true || !ctx.mounted) return;

    final paintBundles = <({String pageName, List<_PaintNote> notes})>[];
    for (final page in mergeablePages.where((p) => p.pageType == 'paint')) {
      final loaded = await _PaintStore.load(
        page.id,
        defaultNoteName:
            provider.t('paint.defaultNoteName').replaceFirst('{n}', '1'),
        defaultPageName:
            provider.t('paint.defaultPageName').replaceFirst('{n}', '1'),
      );
      if (!ctx.mounted) return;
      paintBundles.add((pageName: page.name, notes: loaded.notes));
    }
    // マークダウンの本文 (prefs) も一緒に統合する (= ユーザー要望:
    // 同じ種類同士なら元の種類のまま、 中身も含めて 1 つになるように)。
    final mdBundles = <({String pageName, List<_MdTab> tabs})>[];
    if (mergedType == 'markdown') {
      final sp = await SharedPreferences.getInstance();
      if (!ctx.mounted) return;
      for (final page in mergeablePages) {
        final doc = decodeMarkdownDoc(sp.getString('markdown_${page.id}'));
        mdBundles.add((pageName: page.name, tabs: doc.tabs));
      }
    }

    final nm = ctrl.text.trim();
    final idx = provider.mergePages(ids, name: nm.isEmpty ? null : nm);
    if (idx >= 0) {
      if (paintBundles.isNotEmpty && idx < provider.pages.length) {
        final mergedPage = provider.pages[idx];
        final mergedNotes = <_PaintNote>[];
        for (final bundle in paintBundles) {
          for (final note in bundle.notes) {
            final clone = _PaintNote.fromJson(
                Map<String, dynamic>.from(note.toJson()),
                defaultName: provider
                    .t('paint.defaultNoteName')
                    .replaceFirst('{n}', '1'),
                defaultPageName: provider
                    .t('paint.defaultPageName')
                    .replaceFirst('{n}', '1'));
            final pageName = bundle.pageName.trim();
            if (pageName.isNotEmpty) clone.name = '$pageName - ${clone.name}';
            mergedNotes.add(clone);
          }
        }
        if (mergedNotes.isNotEmpty) {
          await _PaintStore.save(mergedPage.id, mergedNotes, 0);
        }
      }
      // ── マークダウン同士: タブを全部つないで新ページの本文にする ──
      if (mdBundles.isNotEmpty && idx < provider.pages.length) {
        final mergedPage = provider.pages[idx];
        final tabs = <_MdTab>[];
        for (final b in mdBundles) {
          for (final t in b.tabs) {
            final base = b.pageName.trim();
            tabs.add(_MdTab(
              id: 'md${DateTime.now().microsecondsSinceEpoch}_${tabs.length}',
              name: base.isEmpty ? t.name : '$base-${t.name}',
              text: t.text,
            ));
          }
        }
        if (tabs.isNotEmpty) {
          final sp = await SharedPreferences.getInstance();
          await sp.setString(
              'markdown_${mergedPage.id}', encodeMarkdownDoc(tabs, 0));
          // 統合先で書き方例を上書きしないように (中身は既にある)。
          await sp.setBool('md_sample_seeded_${mergedPage.id}', true);
        }
      }
      if (!mounted) return;
      setState(() {
        _drawerSelectedPageIds.clear();
        _drawerSelectedFolderIds.clear();
        _drawerLastAnchorIndex = null;
      });
      _scaffoldKey.currentState?.closeDrawer();
    } else {
      _appSnack(
          ctx,
          SnackBar(
              backgroundColor: Colors.redAccent,
              content: Text(provider.t('drawer.mergeFailed'))));
    }
  }

  Future<void> _groupSelectedDrawerPagesIntoFolder(
      BuildContext ctx, MindMapProvider provider) async {
    if (_drawerSelectedPageIds.isEmpty) return;
    // フォルダー名をユーザーに尋ねる(キャンセル可)
    final ctrl = TextEditingController(
        text:
            '${provider.t('drawer.newFolderDefault')} (${_drawerSelectedPageIds.length})');
    final name = await showDialog<String>(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('drawer.newFolderTitle'),
            style: const TextStyle(color: Colors.white)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          decoration: InputDecoration(
            hintText: provider.t('drawer.subfolderHint'),
            hintStyle: const TextStyle(color: Colors.white38),
            enabledBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: const BorderSide(color: Colors.white24),
            ),
            focusedBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: const BorderSide(color: Color(0xFF43B97F)),
            ),
          ),
          onSubmitted: (v) => Navigator.pop(dctx, v.trim()),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.cancel'))),
          ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF43B97F),
                  foregroundColor: Colors.white,),
              onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
              child: Text(provider.t('btn.ok'))),
        ],
      ),
    );
    if (name == null || name.isEmpty) return;
    final newFolderId = provider.addFolder(name: name);
    final ids = _drawerSelectedPageIds.toList();
    provider.movePagesToFolder(ids, newFolderId);
    if (!ctx.mounted) return;
    setState(() => _drawerSelectedPageIds.clear());
    _appSnack(
        ctx,
        SnackBar(
          backgroundColor: const Color(0xFF43B97F),
          duration: const Duration(seconds: 3),
          content: Text(
              provider
                  .t('drawer.movedToFolder')
                  .replaceAll('{count}', '${ids.length}')
                  .replaceAll('{name}', name),
              style: const TextStyle(color: Colors.white)),
        ));
  }

  /// drawer タイルがタップされた時に、Shift/Ctrl 修飾キーで複数選択モードに
  /// 切替できるか判定。true ならタイル本来の onTap (ページ切替) は行わない。
  bool _toggleDrawerSelectionIfModifier(String pageId) {
    final keys = HardwareKeyboard.instance.logicalKeysPressed;
    final hasShift = keys.contains(LogicalKeyboardKey.shiftLeft) ||
        keys.contains(LogicalKeyboardKey.shiftRight);
    final hasCtrl = keys.contains(LogicalKeyboardKey.controlLeft) ||
        keys.contains(LogicalKeyboardKey.controlRight) ||
        keys.contains(LogicalKeyboardKey.metaLeft) ||
        keys.contains(LogicalKeyboardKey.metaRight);
    final hasModifier = hasShift || hasCtrl;
    // 既に複数選択モードに入っているなら、修飾なしのタップでもトグルする
    final inSelectMode = _drawerMultiSelectActive;
    if (!hasModifier && !inSelectMode) return false;
    // ── 最初に普通に押していたページも選択に入れる (= ユーザー報告:
    //    Ctrl/Shift を押して 2 つ目を選ぶと、 1 つ目が選ばれないまま
    //    新しく押した方だけが選択された状態になる) ──
    //    修飾なしのクリックは「ページを開く」 だけで選択集合には入らない
    //    ため、 何も選ばれていない状態から修飾クリックされた時に、
    //    起点 (直前に押していたページ) を先に入れておく。
    if (hasModifier && !inSelectMode) {
      final provider = context.read<MindMapProvider>();
      String? seed;
      final anchor = _drawerLastAnchorIndex;
      if (anchor != null) {
        final flat = _drawerFlatItems(provider);
        if (anchor >= 0 && anchor < flat.length) {
          final it = flat[anchor];
          if (it.kind == _DrawerFlatItemKind.page) seed = it.id;
        }
      }
      // ★ 起点が分からない時は「今開いているページ」 を起点にする
      //   (= ユーザー報告: 開いているページから Ctrl で 2 つ目を選ぶと、
      //   開いていた方が選ばれないまま始まる)。 一覧で押していなくても、
      //   利用者から見れば「今選んでいるページ」 はそれなので。
      seed ??= provider.currentPage.id;
      if (seed != pageId) _drawerSelectedPageIds.add(seed);
    }
    // ── Shift クリック: 範囲選択 ──
    // 直前のアンカー位置から今回タップしたタイルまでの範囲を全て選択する。
    // これにより上から下まで Shift で纏めて選択できる。
    if (hasShift && _drawerLastAnchorIndex != null) {
      final flat = _drawerFlatItems(context.read<MindMapProvider>());
      final tappedIdx = flat.indexWhere(
          (it) => it.kind == _DrawerFlatItemKind.page && it.id == pageId);
      if (tappedIdx >= 0) {
        final lo = tappedIdx < _drawerLastAnchorIndex!
            ? tappedIdx
            : _drawerLastAnchorIndex!;
        final hi = tappedIdx > _drawerLastAnchorIndex!
            ? tappedIdx
            : _drawerLastAnchorIndex!;
        setState(() {
          for (int i = lo; i <= hi; i++) {
            final it = flat[i];
            if (it.kind == _DrawerFlatItemKind.page) {
              _drawerSelectedPageIds.add(it.id);
            } else {
              _drawerSelectedFolderIds.add(it.id);
            }
          }
        });
        return true;
      }
    }
    // 通常のトグル (Ctrl クリック or 既に選択モード内のタップ)
    setState(() {
      if (_drawerSelectedPageIds.contains(pageId)) {
        _drawerSelectedPageIds.remove(pageId);
      } else {
        _drawerSelectedPageIds.add(pageId);
      }
      // この単独選択操作を新しいアンカーとして記録 (Shift の起点)
      final flat = _drawerFlatItems(context.read<MindMapProvider>());
      final idx = flat.indexWhere(
          (it) => it.kind == _DrawerFlatItemKind.page && it.id == pageId);
      if (idx >= 0) _drawerLastAnchorIndex = idx;
    });
    return true;
  }

  void _recordDrawerAnchor(
      MindMapProvider provider, _DrawerFlatItemKind kind, String id) {
    final flat = _drawerFlatItems(provider);
    final idx = flat.indexWhere((it) => it.kind == kind && it.id == id);
    if (idx >= 0) _drawerLastAnchorIndex = idx;
  }

  /// drawer のフラットなアイテムリストを構築する (範囲選択用)。
  /// 表示順: 各フォルダーヘッダー → そのフォルダー内のページ (展開時) →
  ///          最後にルートのページ群。
  /// このインデックスを使うと「上のマップを選択 → Shift で下のマップ」で
  /// 物理的に挟まれているマップを全て一発選択できる。
  List<_DrawerFlatItem> _drawerFlatItems(MindMapProvider provider) {
    final items = <_DrawerFlatItem>[];
    for (final folder in provider.folders) {
      items.add(
          _DrawerFlatItem(kind: _DrawerFlatItemKind.folder, id: folder.id));
      if (folder.expanded) {
        for (final p in provider.pagesInFolder(folder.id)) {
          items.add(_DrawerFlatItem(kind: _DrawerFlatItemKind.page, id: p.id));
        }
      }
    }
    for (final p in provider.pagesInFolder(null)) {
      items.add(_DrawerFlatItem(kind: _DrawerFlatItemKind.page, id: p.id));
    }
    return items;
  }

  /// フォルダーヘッダー部分のクリック時に複数選択モードに入るかを判定。
  /// 修飾キー or 既に選択中なら true を返してフォルダーの展開/折りたたみを
  /// 抑止し、選択トグルだけを行う。
  bool _toggleDrawerFolderSelectionIfModifier(String folderId) {
    final keys = HardwareKeyboard.instance.logicalKeysPressed;
    final hasShift = keys.contains(LogicalKeyboardKey.shiftLeft) ||
        keys.contains(LogicalKeyboardKey.shiftRight);
    final hasCtrl = keys.contains(LogicalKeyboardKey.controlLeft) ||
        keys.contains(LogicalKeyboardKey.controlRight) ||
        keys.contains(LogicalKeyboardKey.metaLeft) ||
        keys.contains(LogicalKeyboardKey.metaRight);
    final hasModifier = hasShift || hasCtrl;
    final inSelectMode = _drawerMultiSelectActive;
    if (!hasModifier && !inSelectMode) return false;
    // Shift 範囲選択
    if (hasShift && _drawerLastAnchorIndex != null) {
      final flat = _drawerFlatItems(context.read<MindMapProvider>());
      final tappedIdx = flat.indexWhere(
          (it) => it.kind == _DrawerFlatItemKind.folder && it.id == folderId);
      if (tappedIdx >= 0) {
        final lo = tappedIdx < _drawerLastAnchorIndex!
            ? tappedIdx
            : _drawerLastAnchorIndex!;
        final hi = tappedIdx > _drawerLastAnchorIndex!
            ? tappedIdx
            : _drawerLastAnchorIndex!;
        setState(() {
          for (int i = lo; i <= hi; i++) {
            final it = flat[i];
            if (it.kind == _DrawerFlatItemKind.page) {
              _drawerSelectedPageIds.add(it.id);
            } else {
              _drawerSelectedFolderIds.add(it.id);
            }
          }
        });
        return true;
      }
    }
    setState(() {
      if (_drawerSelectedFolderIds.contains(folderId)) {
        _drawerSelectedFolderIds.remove(folderId);
      } else {
        _drawerSelectedFolderIds.add(folderId);
      }
      final flat = _drawerFlatItems(context.read<MindMapProvider>());
      final idx = flat.indexWhere(
          (it) => it.kind == _DrawerFlatItemKind.folder && it.id == folderId);
      if (idx >= 0) _drawerLastAnchorIndex = idx;
    });
    return true;
  }

  /// フォルダーヘッダー（展開トグル + 長押しメニュー）
  Widget _buildFolderHeader(
      BuildContext context, MindMapProvider provider, MindMapFolder folder) {
    // ── DragTarget でラップ ──
    // ドラッグされた _DrawerPageDragData を受け取り、対象フォルダーへ移動。
    // ホバー中は緑色枠で「ここに入る」と視覚フィードバック。
    return DragTarget<_DrawerPageDragData>(
      onWillAcceptWithDetails: (details) {
        // 既にこのフォルダーにあるページしか含まれていなければ受け取らない
        // (見た目が変わるだけで意味がないため)
        final pages = provider.pages;
        for (final id in details.data.pageIds) {
          final p =
              pages.firstWhere((e) => e.id == id, orElse: () => pages.first);
          if (p.folderId != folder.id) return true;
        }
        return false;
      },
      onAcceptWithDetails: (details) {
        provider.movePagesToFolder(details.data.pageIds, folder.id);
        // 移動先フォルダーは展開しておく (ユーザーが結果を確認しやすい)
        if (!folder.expanded) {
          provider.toggleFolderExpanded(folder.id);
        }
        setState(() => _drawerSelectedPageIds.clear());
      },
      builder: (ctx, candidate, rejected) {
        final hovering = candidate.isNotEmpty;
        // フォルダーが複数選択中ならシアンで強調 (D&D ホバー中は緑が優先)
        final isSelected = _drawerSelectedFolderIds.contains(folder.id);
        // 「・・・」ボタンの位置でメニューをポップオーバーするための GlobalKey
        final moreBtnKey = GlobalKey();
        return InkWell(
          onTap: () {
            // Shift/Ctrl 押下中、または選択モード中なら選択トグルのみ
            if (_toggleDrawerFolderSelectionIfModifier(folder.id)) return;
            provider.toggleFolderExpanded(folder.id);
          },
          onLongPress: () =>
              _showFolderContextMenu(context, provider, folder, moreBtnKey),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
            decoration: BoxDecoration(
              color: hovering
                  ? const Color(0xFF43B97F).withValues(alpha: 0.18)
                  : (isSelected
                      ? const Color(0xFF00E5FF).withValues(alpha: 0.16)
                      : provider.headerColor.withValues(alpha: 0.14)),
              border: hovering
                  ? Border.all(color: const Color(0xFF43B97F), width: 1.5)
                  : (isSelected
                      ? Border.all(
                          color: const Color(0xFF00E5FF).withValues(alpha: 0.6),
                          width: 1.2)
                      : Border.all(
                          color: provider.headerColor.withValues(alpha: 0.22),
                          width: 0.8)),
              borderRadius: BorderRadius.circular(8),
            ),
            child: Row(children: [
              Icon(
                folder.expanded
                    ? Icons.keyboard_arrow_down_rounded
                    : Icons.chevron_right_rounded,
                color: Colors.white54,
                size: 18,
              ),
              const SizedBox(width: 4),
              Icon(
                folder.expanded
                    ? Icons.folder_open_rounded
                    : Icons.folder_rounded,
                color: const Color(0xFFFFB347),
                size: 16,
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(folder.name,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 13,
                        fontWeight: FontWeight.w600)),
              ),
              // ── ディスク連動フォルダーのバッジ ──
              // linkedDirPath が設定されているフォルダーは、所属するページが
              // 自動的にそのディレクトリへ JSON として保存される。
              // ユーザーが視覚的に区別できるよう、緑色の💾アイコンバッジを表示。
              if (folder.linkedDirPath != null) ...[
                Tooltip(
                  message: provider
                      .t('folder.tip.linkedDir')
                      .replaceAll('{path}', folder.linkedDirPath ?? ''),
                  child: Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                    decoration: BoxDecoration(
                      color: const Color(0xFF43B97F).withValues(alpha: 0.25),
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(
                          color:
                              const Color(0xFF43B97F).withValues(alpha: 0.6)),
                    ),
                    child: const Icon(Icons.folder_zip_rounded,
                        color: Color(0xFF43B97F), size: 10),
                  ),
                ),
                const SizedBox(width: 4),
              ],
              // ── Ctrl+1〜9 基準フォルダー表示バッジ ──
              // _shortcutFolderId が現在のフォルダー ID と一致するときだけ表示。
              // ユーザーがどのフォルダーが基準か一目でわかるようにする。
              if (_isDesktop && provider.shortcutFolderId == folder.id) ...[
                Tooltip(
                  message: provider.t('folder.tip.shortcutBase'),
                  child: Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                    decoration: BoxDecoration(
                      color: const Color(0xFF6C63FF).withValues(alpha: 0.25),
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(
                          color:
                              const Color(0xFF6C63FF).withValues(alpha: 0.6)),
                    ),
                    child: const Row(mainAxisSize: MainAxisSize.min, children: [
                      Icon(Icons.keyboard_command_key,
                          color: Color(0xFF6C63FF), size: 10),
                      SizedBox(width: 3),
                      Text('Ctrl+1-9',
                          style: TextStyle(
                              color: Color(0xFF6C63FF),
                              fontSize: 9,
                              fontWeight: FontWeight.w700)),
                    ]),
                  ),
                ),
                const SizedBox(width: 4),
              ],
              // ページ数バッジ
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.08),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Text('${provider.pagesInFolder(folder.id).length}',
                    style:
                        const TextStyle(color: Colors.white54, fontSize: 10)),
              ),
              const SizedBox(width: 4),
              IconButton(
                key: moreBtnKey,
                icon: const Icon(Icons.more_vert, color: Colors.white38),
                iconSize: 16,
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
                onPressed: () => _showFolderContextMenu(
                    context, provider, folder, moreBtnKey),
              ),
            ]),
          ),
        );
      },
    );
  }

  /// ページタイル（フォルダー内 / ルート両用）
  Widget _buildPageTile(
      BuildContext context, MindMapProvider provider, MindMapPage page,
      {double indent = 0}) {
    final i = provider.pages.indexOf(page);
    if (i < 0) return const SizedBox.shrink();
    // 現在開いているページかどうか。ただし複数選択モード中は意図的に「非アクティブ」
    // 扱いにする (= 紫色のハイライトを付けない)。
    // 複数選択しているときに「現在開いているマップだけが紫」だと、選択中のマップ
    // (シアン枠) と混在して "今選択しているのはどれだっけ?" と混乱しやすい
    // ためのユーザー要望対応。
    final isActuallyActive = i == provider.currentPageIndex;
    final isActive = isActuallyActive && !_drawerMultiSelectActive;
    final sizeBytes = provider.calculatePageSizeBytes(page);
    // ── Ctrl+N ラベルの計算 ──
    // 既定 (基準フォルダー未設定) はルート (フォルダー外のページ) のみ
    // を対象に Ctrl+1〜9 を割り当てる。フォルダー内のマップには
    // ラベルを付けない（ユーザーが意図せずフォルダー中身に Ctrl+2〜9 が
    // 振られる事故を防ぐ）。フォルダー右クリックから「Ctrl+1〜9 の基準にする」
    // を選んだ時だけ、そのフォルダー内のページにラベルを付ける。
    // 判定ロジックは provider.pageForShortcutSlot と完全に同じスコープにする。
    String? shortcutLabel;
    if (_isDesktop) {
      final shortcutFolderId = provider.shortcutFolderId;
      // ★ pageForShortcutSlot と完全に同じ並び (pagesInFolder = ピン留め先頭)
      //   を使う。 こうしないとドロワー表示順とラベルがずれる (= ユーザー報告:
      //   一番上のマップに Ctrl+2 が付く)。
      final List<MindMapPage> scope;
      if (shortcutFolderId != null &&
          shortcutFolderId != MindMapProvider.shortcutRootSentinel) {
        // 指定フォルダーが基準
        scope = provider.pagesInFolder(shortcutFolderId);
      } else {
        // null / sentinel → ルート (フォルダー外) のページのみが基準
        scope = provider.pagesInFolder(null);
      }
      final localIdx = scope.indexOf(page);
      if (localIdx >= 0 && localIdx < 9) {
        shortcutLabel = 'Ctrl+${localIdx + 1}';
      }
    }
    // ── 複数選択モード対応 ──
    // 選択中なら左端にチェックマークの背景色 (薄シアン) を出す。
    final isMultiSelected = _drawerSelectedPageIds.contains(page.id);
    // 「・・・」メニューを位置指定で開くための GlobalKey。
    // _DrawerTile 内の PopupMenuButton "more" 選択時、ここで保持した
    // anchor 位置にメニューが出る。
    final anchorKey = GlobalKey();
    Widget tile = _DrawerTile(
      key: ValueKey(page.id),
      index: i,
      page: page,
      isActive: isActive,
      isAutoSync: provider.isPageAutoSync(page.id),
      sizeText: MindMapProvider.formatBytes(sizeBytes),
      shortcutLabel: shortcutLabel,
      onToggleAutoSync: provider.isSyncEnabled
          ? () => provider.setPageAutoSync(
              page.id, !provider.isPageAutoSync(page.id))
          : null,
      onTap: () {
        // Shift/Ctrl 押下中、または既に複数選択モードならトグルのみ。
        // それ以外は通常の「ページ切替」動作。
        if (!provider.isDownloading &&
            _toggleDrawerSelectionIfModifier(page.id)) return;
        if (provider.isDownloading && _drawerMultiSelectActive) {
          setState(() {
            _drawerSelectedPageIds.clear();
            _drawerSelectedFolderIds.clear();
            _drawerLastAnchorIndex = null;
          });
        }
        _recordDrawerAnchor(provider, _DrawerFlatItemKind.page, page.id);
        _scaffoldKey.currentState?.closeDrawer();
        provider.switchPage(i);
        WidgetsBinding.instance.addPostFrameCallback((_) => _centerOnRoot());
      },
      // 複数選択開始は **デスクトップ専用**。
      // モバイル版では「2 つ選択できてしまう」混乱を避けるため、長押しで
      // 選択モードに入る動作を無効化する。
      // (Ctrl+G でフォルダー化等のキーボードショートカットも無いため、
      //  モバイルで複数選択を導入してもメリットが乏しい)
      onLongPress: _isDesktop
          ? () {
              setState(() {
                _recordDrawerAnchor(
                    provider, _DrawerFlatItemKind.page, page.id);
                if (_drawerSelectedPageIds.contains(page.id)) {
                  _drawerSelectedPageIds.remove(page.id);
                } else {
                  _drawerSelectedPageIds.add(page.id);
                }
              });
            }
          : null,
      isMultiSelected: isMultiSelected,
      onRename: () {
        Navigator.pop(context);
        _renamePageDialog(context, provider, i);
      },
      onDelete: provider.pages.length > 1
          ? () {
              Navigator.pop(context);
              _confirmDeletePageAt(context, provider, i);
            }
          : null,
      // 追加機能: 長押し / 「・・・」メニュー
      // btnCtx を受け取り、その RenderBox 位置に showMenu でポップオーバー。
      // 長押しフォールバック (btnCtx が null) の時は anchorKey を使う。
      onMore: (btnCtx) =>
          _showPageContextMenu(context, provider, page, btnCtx, anchorKey),
    );
    // ── ドラッグ&ドロップ対応 ──
    // ページタイルを Draggable でラップし、フォルダーヘッダーや
    // ルート領域 (DragTarget) にドロップして移動できるようにする。
    // 複数選択中の場合は選択ページ全部をまとめて運ぶ。
    final dragData = _DrawerPageDragData(
      pageIds: _drawerSelectedPageIds.contains(page.id)
          ? _drawerSelectedPageIds.toList()
          : [page.id],
      primaryTitle: page.name,
    );
    return KeyedSubtree(
      key: anchorKey,
      child: Padding(
        padding: EdgeInsets.only(left: indent),
        // ── ページ並び替えのための DragTarget ──
        // 別ページタイルからドロップされた時、このタイルの直前 or 直後に
        // 並び替える。ホバー位置 (上半分 / 下半分) で挿入位置を決定する。
        // フォルダーヘッダーやルートドロップ領域への移動は既存の DragTarget
        // で別途処理 (フォルダー間移動)。
        child: _ReorderDropZone(
          targetPageId: page.id,
          provider: provider,
          // 並び替え後に選択をクリアして UI を整える
          onReordered: () {
            setState(() {
              _drawerSelectedPageIds.clear();
              _drawerSelectedFolderIds.clear();
              _drawerLastAnchorIndex = null;
            });
          },
          // ── ドラッグ判定領域の制御 ──
          // タイル全体を LongPressDraggable でラップすると、右側の
          // 自動同期ボタンや「・・・」ボタンを長押ししただけで
          // ドラッグが起動してメニューが開けなくなる。
          // そこで Stack 構造にして:
          //   1. 通常の tile (= _DrawerTile, ボタン群を含む) を底に置き
          //   2. 左側 (右マージン 64px) だけに透明な LongPressDraggable
          //      レイヤーを被せ、長押しでドラッグ開始する
          // hitTestBehavior: translucent により、タップは下の
          // _DrawerTile に通り、長押しのみドラッグへ流れる。
          // ── ドラッグハンドル方式 ──
          // ユーザーフィードバック: タイル全体の左半分がドラッグ領域だと、
          // タイトルをタップしようとしても誤ってドラッグが起動する。
          // 解決策: 左端 24px の「掴みハンドル」だけをドラッグ可能領域とし、
          // タイル本体 (タップ・長押し) は通常の InkWell として動作させる。
          // ハンドルには Icons.drag_indicator を表示して視覚的にも明示する。
          child: Stack(
            children: [
              // 元のタイル全体 (左にハンドル分のパディングを追加して重なりを回避)
              // モバイルは掴みやすいようハンドルを広く取る (= ユーザー要望:
              //   モバイルでマップ一覧の並び替えができない問題の修正)。
              Padding(
                padding: EdgeInsets.only(left: _isDesktop ? 22 : 42),
                child: tile,
              ),
              // 左端の掴みハンドル (デスクトップ 24px / モバイル 42px、 視覚アイコン付き)
              Positioned(
                left: 0,
                top: 0,
                bottom: 0,
                width: _isDesktop ? 24 : 42,
                child: LongPressDraggable<_DrawerPageDragData>(
                  data: dragData,
                  delay: _isDesktop
                      ? const Duration(milliseconds: 80)
                      : const Duration(milliseconds: 250),
                  // ── ドラッグ開始時に Drawer を自動で閉じる ──
                  // Scaffold.drawer はモーダル overlay (= 右側に半透明
                  // barrier が出る) なので、 Drawer を閉じないと
                  // キャンバスの DragTarget まで pointer event が
                  // 届かず drop が成立しない。 ドラッグ開始した瞬間に
                  // Drawer を閉じて、 feedback widget はそのまま追従。
                  // この時 root Navigator ではなく Scaffold が管理する
                  // drawer を閉じる必要があるので `Scaffold.maybeOf` を使う。
                  onDragStarted: () {
                    // ── ドロワーは閉じない (= ユーザー要望: ドラッグでマップ一覧の
                    //   並び替えができるように) ──
                    // 以前はここで closeDrawer していたが、 それだと並び替え用の
                    //   ドロップゾーン (= 他のページタイル) が消えてしまい、 並び替えが
                    //   できなくなっていた。 キャンバスへのドロップ (サブマップ化) は
                    //   下のグローバル pointer route で位置検出するため、 ドロワーを
                    //   閉じる必要はない (ドロワー内 = 並び替え、 ドロワー外 = サブマップ)。
                    if (mounted) {
                      setState(() {
                        _draggingMapPage = true;
                        _currentDrawerDragData = dragData;
                      });
                    }
                  },
                  onDragEnd: (_) {
                    // ドラッグが終了 (= 成功・失敗どちらでも) state クリア。
                    // 既に _globalPointerForMapDrop で処理されている場合は
                    // すでに false になっているので no-op。
                    if (mounted && _draggingMapPage) {
                      setState(() {
                        _draggingMapPage = false;
                        _currentDrawerDragData = null;
                      });
                    }
                  },
                  feedback: Material(
                    color: Colors.transparent,
                    child: Container(
                      constraints: const BoxConstraints(maxWidth: 240),
                      padding: const EdgeInsets.symmetric(
                          horizontal: 12, vertical: 8),
                      decoration: BoxDecoration(
                        color: const Color(0xFF6C63FF).withValues(alpha: 0.95),
                        borderRadius: BorderRadius.circular(10),
                        boxShadow: [
                          BoxShadow(
                              color: Colors.black.withValues(alpha: 0.4),
                              blurRadius: 12,
                              offset: const Offset(0, 4)),
                        ],
                      ),
                      child: Row(mainAxisSize: MainAxisSize.min, children: [
                        const Icon(Icons.drag_indicator,
                            color: Colors.white, size: 18),
                        const SizedBox(width: 6),
                        Flexible(
                          child: Text(
                              dragData.pageIds.length > 1
                                  ? '${dragData.primaryTitle} (+${dragData.pageIds.length - 1})'
                                  : dragData.primaryTitle,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 13,
                                  fontWeight: FontWeight.w700)),
                        ),
                      ]),
                    ),
                  ),
                  child: MouseRegion(
                    cursor: SystemMouseCursors.grab,
                    child: Center(
                      // モバイルは掴みやすいよう大きく・はっきり表示する
                      //   (= ユーザー要望: モバイルで並び替えできない問題)。
                      child: Icon(
                        Icons.drag_indicator,
                        color: _isDesktop ? Colors.white24 : Colors.white54,
                        size: _isDesktop ? 14 : 22,
                      ),
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  /// 「+」ボタンのメニュー: 新規ページ / 新規フォルダー / JSON 読み込み / フォルダーを開く
  /// 「+」ボタンのメニュー: 新規ページ / 新規フォルダー / JSON 読み込み / フォルダーを開く
  /// 旧: showModalBottomSheet (画面下から出てくる) → drawer を閉じる必要があり UX が悪い
  /// 新: showMenu で「+」ボタンの右隣にポップオーバー表示。drawer を閉じずに済む。
  /// `anchorCtx` は IconButton の Builder 内で渡された BuildContext で、その
  /// RenderBox 位置がメニューのアンカーになる。
  void _showDrawerAddMenu(BuildContext context, MindMapProvider provider,
      [BuildContext? anchorCtx]) {
    if (!mounted) return;
    final ctx = this.context;

    // 表示位置の計算
    RelativeRect position;
    final overlay = Overlay.of(ctx).context.findRenderObject() as RenderBox;
    if (anchorCtx != null) {
      final ro = anchorCtx.findRenderObject();
      if (ro is RenderBox && ro.attached) {
        final topLeft = ro.localToGlobal(Offset.zero, ancestor: overlay);
        final bottomRight = ro.localToGlobal(ro.size.bottomRight(Offset.zero),
            ancestor: overlay);
        position = RelativeRect.fromRect(
          Rect.fromPoints(topLeft, bottomRight),
          Offset.zero & overlay.size,
        );
      } else {
        position = const RelativeRect.fromLTRB(80, 80, 0, 0);
      }
    } else {
      position = const RelativeRect.fromLTRB(80, 80, 0, 0);
    }

    showMenu<_AddMenuAction>(
      context: ctx,
      position: position,
      color: const Color(0xFF1E1E32),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(10),
        side: BorderSide(color: Colors.white.withValues(alpha: 0.12)),
      ),
      items: <PopupMenuEntry<_AddMenuAction>>[
        // ── 「追加メニュー」 ヘッダーはタップ不可で不要のため削除 (= ユーザー要望) ──
        _menuItem<_AddMenuAction>(
            value: _AddMenuAction.newPage,
            icon: Icons.add_box_outlined,
            iconColor: const Color(0xFF6C63FF),
            label: provider.t('drawer.newPage'),
            shortcut: _getCommandShortcut('newPage')),
        // ── Markdown / 図 (Mermaid) ページ (= ユーザー要望: ページ機能として
        //    「新規マークダウン」 を出す) ──
        _menuItem<_AddMenuAction>(
            value: _AddMenuAction.newMarkdownPage,
            icon: Icons.polyline_rounded,
            iconColor: const Color(0xFF5FD3B2),
            label: provider.t('drawer.newMarkdownPage'),
            shortcut: _getCommandShortcut('newMarkdownPage')),
        // ── ギャラリーページ (= PDF/画像/動画を同寸タイルで自動整列する専用ページ) ──
        _menuItem<_AddMenuAction>(
            value: _AddMenuAction.newBookshelfPage,
            icon: Icons.shelves,
            iconColor: const Color(0xFFFF7043),
            label: provider.t('drawer.newBookshelfPage'),
            shortcut: _getCommandShortcut('newBookshelfPage')),
        // ── お絵かき (ペイント) ページ (= ユーザー要望) ──
        _menuItem<_AddMenuAction>(
            value: _AddMenuAction.newPaintPage,
            icon: Icons.brush_rounded,
            iconColor: const Color(0xFFEC407A),
            label: provider.t('drawer.newPaintPage'),
            shortcut: _getCommandShortcut('newPaintPage')),
        // ── 文章作成 (ドキュメント) ページ (= ユーザー要望: 罫線付きで Word の
        //    ような文章が書ける) ──
        _menuItem<_AddMenuAction>(
            value: _AddMenuAction.newVideoEditorPage,
            icon: Icons.movie_creation_rounded,
            iconColor: const Color(0xFFFF7043),
            label: provider.t('drawer.newVideoEditorPage'),
            shortcut: _getCommandShortcut('newVideoEditorPage')),
        _menuItem<_AddMenuAction>(
            value: _AddMenuAction.newFolder,
            icon: Icons.create_new_folder_outlined,
            iconColor: const Color(0xFFFFB347),
            label: provider.t('drawer.newFolder'),
            shortcut: _getCommandShortcut('newFolder')),
        const PopupMenuDivider(),
        _menuItem<_AddMenuAction>(
            value: _AddMenuAction.importBundle,
            icon: Icons.inventory_2_outlined,
            iconColor: const Color(0xFFBA68C8),
            // ★ 読み込みは 1 項目に統合した (= ユーザー要望: json / html と
            //   分かれていて違いが分からない)。 中で拡張子ごとに振り分ける。
            label: provider.t('export.bundleImport'),
            formatHint: '.hnmap / .json / .html'),
        _menuItem<_AddMenuAction>(
            value: _AddMenuAction.joinLive,
            icon: Icons.groups_rounded,
            iconColor: const Color(0xFF6C63FF),
            label: provider.t('live.joinTitle')),
        // (「マップだけ読み込む」 は上の 1 項目に統合した = ユーザー要望。
        //  .json / .html も同じ入口から読める)
        _menuItem<_AddMenuAction>(
            value: _AddMenuAction.openFolder,
            icon: Icons.folder_open_rounded,
            iconColor: const Color(0xFF4FC3F7),
            label: provider.t('drawer.openFolder'),
            formatHint: provider.t('drawer.openFolderFormats')),
        const PopupMenuDivider(),
        // ── AI で新規ページを作る (= ユーザー要望: + ボタンから AI に
        //    ページを作ってもらえるように)。 呼ぶのは AI アシスタント
        //    (MCP チャット) で、 「新しいページを作る」 という前提を
        //    添えて開く。 ──
        _menuItem<_AddMenuAction>(
            value: _AddMenuAction.aiNewPage,
            icon: Icons.auto_awesome_rounded,
            iconColor: const Color(0xFFBA68C8),
            label: provider.t('drawer.aiNewPage'),
            formatHint: provider.t('drawer.aiNewPageHint')),
        // ── 「AIでファイルを要約」「AIで用語・概念を解説」 はユーザー要望で
        //    削除 (= AI アシスタントのボタンから同じことが呼べるため)。
        //    機能本体 (_summarizeFileToNewPage / _aiExplainConcept) と
        //    _AddMenuAction の値は、 ショートカット・AI アシスタント経由の
        //    呼び出しで今も使うので残してある。
        // ── 「資料に追加質問する」項目もユーザー要望で削除済み ──
        // 旧: 要約済みページに対する Q&A ダイアログを起動するメニュー項目。
        // 削除理由: 機能としては残っているが、メニュー項目として置く価値が
        // 薄いと判断 (ノードの AI 機能から同じ Q&A ができる)。
      ],
    ).then((action) {
      if (action == null || !mounted) return;
      switch (action) {
        case _AddMenuAction.newPage:
          // ここは種類がもう選ばれている (+ メニューに全部並んでいる) ので、
          // 種類を聞き直さずそのままマインドマップを作る。
          _createNormalPage(provider);
          break;
        case _AddMenuAction.newBookshelfPage:
          _addBookshelfPageDialog(ctx, provider);
          break;
        case _AddMenuAction.newPaintPage:
          _addPaintPageDialog(ctx, provider);
          break;
        case _AddMenuAction.newDocumentPage:
          _addDocumentPageDialog(ctx, provider);
          break;
        case _AddMenuAction.newMarkdownPage:
          _addMarkdownPageDialog(ctx, provider);
          break;
        case _AddMenuAction.newVideoEditorPage:
          _addVideoEditorPageDialog(ctx, provider);
          break;
        case _AddMenuAction.newFolder:
          _addFolderDialog(ctx, provider);
          break;
        case _AddMenuAction.importBundle:
          // .json / .html を選ばれた時の案内に使うので context を渡す。
          _importPageBundle(provider, hostContext: ctx);
          break;
        case _AddMenuAction.joinLive:
          _showJoinLiveDialog(provider);
          break;
        case _AddMenuAction.importJson:
          _importJsonFile(ctx, provider);
          break;
        case _AddMenuAction.openFolder:
          _importJsonFromDirectory(ctx, provider);
          break;
        case _AddMenuAction.aiNewPage:
          // AI アシスタントを「新しいページを作る」 前提で開く (= ユーザー要望)。
          // ignore: discarded_futures
          _openMcpChat(provider, initialTask: 'newPage');
          break;
        case _AddMenuAction.aiSummarize:
          _aiSummarizeFromFile(ctx, provider);
          break;
        case _AddMenuAction.aiExplain:
          _aiExplainConcept(ctx, provider);
          break;
        case _AddMenuAction.aiFollowUp:
          // メニュー項目は削除済だが、enum 値は他から参照される可能性があるため
          // ハンドラだけ残しておく (無視する no-op)。
          break;
      }
    });
  }

  /// フォルダー新規作成ダイアログ
  void _addFolderDialog(BuildContext context, MindMapProvider provider) {
    final ctrl = TextEditingController();
    void doCreate(BuildContext ctx) {
      final name = ctrl.text.trim();
      Navigator.pop(ctx);
      provider.addFolder(name: name.isEmpty ? null : name);
    }

    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('folder.newTitle'),
            style: const TextStyle(color: Colors.white)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          decoration: InputDecoration(
            hintText: provider.t('folder.nameHint'),
            hintStyle: const TextStyle(color: Colors.white38),
            enabledBorder: const UnderlineInputBorder(
                borderSide: BorderSide(color: Colors.white24)),
            focusedBorder: const UnderlineInputBorder(
                borderSide: BorderSide(color: Color(0xFFFFB347))),
          ),
          onSubmitted: (_) => doCreate(ctx),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
            onPressed: () => doCreate(ctx),
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFFFB347),
                foregroundColor: Color(0xFF10241F),),
            child: Text(provider.t('folder.create')),
          ),
        ],
      ),
    );
  }

  /// フォルダー長押しメニュー
  /// フォルダーの「・・・」メニュー。
  /// `anchorKey` で指定したウィジェットの位置の隣にポップオーバー表示する。
  /// 複数のフォルダーが選択中なら「N 個まとめて削除」等の一括操作を提供。
  void _showFolderContextMenu(
      BuildContext context, MindMapProvider provider, MindMapFolder folder,
      [GlobalKey? anchorKey]) {
    // ── 安全な context 取得 ──
    if (!mounted) return;
    final ctx = this.context;
    // 複数選択中の場合は一括操作メニュー、そうでなければ通常メニュー
    final folderIds = _drawerSelectedFolderIds.contains(folder.id)
        ? _drawerSelectedFolderIds.toList()
        : [folder.id];
    final pageIds = _drawerSelectedPageIds.toList();
    final isBulk =
        folderIds.length > 1 || (folderIds.length == 1 && pageIds.isNotEmpty);

    // ── 表示位置の計算 ──
    // anchorKey があればそのウィジェットの右下、なければ画面中央付近
    RelativeRect position;
    final overlay = Overlay.of(ctx).context.findRenderObject() as RenderBox;
    if (anchorKey != null && anchorKey.currentContext != null) {
      final box = anchorKey.currentContext!.findRenderObject() as RenderBox;
      final topLeft = box.localToGlobal(Offset.zero, ancestor: overlay);
      final bottomRight = box.localToGlobal(box.size.bottomRight(Offset.zero),
          ancestor: overlay);
      position = RelativeRect.fromRect(
        Rect.fromPoints(topLeft, bottomRight),
        Offset.zero & overlay.size,
      );
    } else {
      // フォールバック: 画面左上付近
      position = const RelativeRect.fromLTRB(80, 120, 0, 0);
    }

    final items = <PopupMenuEntry<_FolderAction>>[
      // ヘッダー (タップ不可のラベル)
      PopupMenuItem<_FolderAction>(
        enabled: false,
        height: 32,
        child: Row(children: [
          const Icon(Icons.folder_rounded, color: Color(0xFFFFB347), size: 16),
          const SizedBox(width: 8),
          Flexible(
            child: Text(
                isBulk
                    ? '${folderIds.length}${provider.t('drawer.foldersSelected')}'
                        '${pageIds.isNotEmpty ? " + ${pageIds.length}${provider.t('drawer.selectedSuffix')}" : ""}'
                    : folder.name,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                    color: Colors.white,
                    fontSize: 12,
                    fontWeight: FontWeight.w700)),
          ),
        ]),
      ),
      const PopupMenuDivider(),
    ];

    if (!isBulk) {
      // ── 単一フォルダー操作 ──
      // Ctrl+1〜9 の基準フォルダーとして使うかのトグル項目を追加
      final isShortcut = provider.shortcutFolderId == folder.id;
      items.addAll([
        _menuItem<_FolderAction>(
            value: _FolderAction.rename,
            icon: Icons.edit_outlined,
            iconColor: const Color(0xFF4FC3F7),
            label: provider.t('folder.rename')),
        if (_isDesktop)
          _menuItem<_FolderAction>(
              value: _FolderAction.toggleShortcut,
              icon: isShortcut
                  ? Icons.keyboard_command_key
                  : Icons.keyboard_outlined,
              iconColor: isShortcut
                  ? const Color(0xFFFFB347)
                  : const Color(0xFF6C63FF),
              label: isShortcut
                  ? provider.t('folder.unsetShortcut')
                  : provider.t('folder.setShortcut')),
        _menuItem<_FolderAction>(
            value: _FolderAction.export,
            icon: Icons.file_upload_outlined,
            iconColor: const Color(0xFF43B97F),
            label: provider.t('folder.export')),
        // ── マップごとに個別ファイルで書き出し (旧称: ディレクトリとして書き出し) ──
        // 1 つの巨大 JSON にまとめるのではなく、選んだフォルダー直下に
        // フォルダー内の各マップを個別の .json ファイルとして保存する。
        // エクスプローラーでそのまま閲覧でき、後で再度フォルダーごと
        // 読み込みも可能。
        _menuItem<_FolderAction>(
            value: _FolderAction.exportAsDirectory,
            icon: Icons.folder_zip_rounded,
            iconColor: const Color(0xFF43B97F),
            label: provider.t('folder.exportAsDir')),
        _menuItem<_FolderAction>(
            value: _FolderAction.delete,
            icon: Icons.delete_outline_rounded,
            iconColor: const Color(0xFFFF6B6B),
            label: provider.t('folder.delete')),
      ]);
    } else {
      // ── 一括操作 (複数選択中) ──
      items.add(_menuItem<_FolderAction>(
          value: _FolderAction.bulkDelete,
          icon: Icons.delete_sweep_rounded,
          iconColor: const Color(0xFFFF6B6B),
          label: provider.t('drawer.bulkDelete')));
      items.add(_menuItem<_FolderAction>(
          value: _FolderAction.clearSelection,
          icon: Icons.deselect_rounded,
          iconColor: Colors.white54,
          label: provider.t('drawer.tip.clearSelection')));
    }

    showMenu<_FolderAction>(
      context: ctx,
      position: position,
      color: const Color(0xFF1E1E32),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(10),
        side: BorderSide(color: Colors.white.withValues(alpha: 0.12)),
      ),
      items: items,
    ).then((action) {
      if (action == null || !mounted) return;
      switch (action) {
        case _FolderAction.rename:
          _renameFolderDialog(ctx, provider, folder);
          break;
        case _FolderAction.export:
          _exportFolderToJson(ctx, provider, folder);
          break;
        case _FolderAction.exportAsDirectory:
          _exportFolderAsDirectory(ctx, provider, folder);
          break;
        case _FolderAction.delete:
          _confirmDeleteFolder(ctx, provider, folder);
          break;
        case _FolderAction.bulkDelete:
          _confirmBulkDelete(ctx, provider,
              folderIds: folderIds, pageIds: pageIds);
          break;
        case _FolderAction.clearSelection:
          setState(() {
            _drawerSelectedFolderIds.clear();
            _drawerSelectedPageIds.clear();
            _drawerLastAnchorIndex = null;
          });
          break;
        case _FolderAction.toggleShortcut:
          // 既に基準なら null に、未設定 or 別フォルダーなら今のフォルダーに
          final wasShortcut = provider.shortcutFolderId == folder.id;
          provider.setShortcutFolder(wasShortcut ? null : folder.id);
          _appSnack(
              ctx,
              SnackBar(
                backgroundColor: const Color(0xFF6C63FF),
                duration: const Duration(seconds: 2),
                content: Text(
                    wasShortcut
                        ? provider.t('folder.shortcutCleared')
                        : provider
                            .t('folder.shortcutSet')
                            .replaceAll('{name}', folder.name),
                    style: const TextStyle(color: Colors.white)),
              ));
          break;
      }
    });
  }

  /// showMenu 内で再利用する装飾済みメニュー項目ヘルパー
  PopupMenuItem<T> _menuItem<T>(
      {required T value,
      required IconData icon,
      required Color iconColor,
      required String label,
      String? shortcut,
      String? formatHint}) {
    final hasFormatHint = formatHint != null && formatHint.isNotEmpty;
    final hasShortcut = shortcut != null && shortcut.isNotEmpty;
    return PopupMenuItem<T>(
      value: value,
      height: hasFormatHint ? 48 : 38,
      child: Row(children: [
        Icon(icon, color: iconColor, size: 18),
        const SizedBox(width: 12),
        Expanded(
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(label,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(color: Colors.white, fontSize: 13)),
              if (hasFormatHint)
                Text(formatHint!,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style:
                        const TextStyle(color: Colors.white38, fontSize: 10)),
            ],
          ),
        ),
        if (hasShortcut) ...[
          const SizedBox(width: 12),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
            decoration: BoxDecoration(
              color: Colors.white.withValues(alpha: 0.07),
              borderRadius: BorderRadius.circular(5),
              border: Border.all(color: Colors.white12),
            ),
            child: Text(shortcut!,
                style: const TextStyle(
                    color: Colors.white54,
                    fontSize: 10,
                    fontWeight: FontWeight.w700)),
          ),
        ],
      ]),
    );
  }

  /// 複数のフォルダー & ページをまとめて削除する確認ダイアログ。
  /// フォルダー削除時はその中のページも一緒に消すかをユーザーが選択 (デフォルト)
  Future<void> _confirmBulkDelete(
      BuildContext context, MindMapProvider provider,
      {required List<String> folderIds, required List<String> pageIds}) async {
    // フォルダー内のページを集計 (削除対象に追加するか別フォルダーへ移すか)
    final pagesInFolders = <String>[];
    for (final fid in folderIds) {
      pagesInFolders.addAll(provider.pagesInFolder(fid).map((p) => p.id));
    }
    final totalPagesAffected = {...pageIds, ...pagesInFolders}.length;
    // 全ページ削除すると 0 になる場合は中止 (ProvidedRule: pages.length > 1)
    final remaining =
        provider.pages.length - {...pageIds, ...pagesInFolders}.length;
    final allPagesWillBeDeleted = remaining < 1;

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Row(children: [
          const Icon(Icons.warning_amber_rounded,
              color: Color(0xFFFF6B6B), size: 22),
          const SizedBox(width: 10),
          Text(provider.t('drawer.bulkDelete'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
        ]),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
                provider
                    .t('drawer.bulkDeleteBody')
                    .replaceAll('{folders}', folderIds.length.toString())
                    .replaceAll('{pages}', totalPagesAffected.toString()),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
            if (allPagesWillBeDeleted) ...[
              const SizedBox(height: 8),
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: const Color(0xFFFF6B6B).withValues(alpha: 0.15),
                  borderRadius: BorderRadius.circular(6),
                  border: Border.all(
                      color: const Color(0xFFFF6B6B).withValues(alpha: 0.5)),
                ),
                child: Text(provider.t('drawer.bulkDeleteWarning'),
                    style: const TextStyle(
                        color: Color(0xFFFF6B6B), fontSize: 11)),
              ),
            ],
          ],
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx, false),
              child: Text(provider.t('btn.cancel'))),
          ElevatedButton.icon(
            style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFFFF6B6B),
              foregroundColor: Colors.white,
              disabledBackgroundColor: const Color(0xFF6E404A),
              disabledForegroundColor: Colors.white60,
            ),
            onPressed:
                allPagesWillBeDeleted ? null : () => Navigator.pop(dctx, true),
            icon: const Icon(Icons.delete_forever_rounded, size: 16),
            label: Text(provider.t('btn.delete')),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    // 実際の削除: provider に bulkDelete メソッドを追加
    provider.bulkDeletePagesAndFolders(folderIds: folderIds, pageIds: pageIds);
    if (!context.mounted) return;
    setState(() {
      _drawerSelectedFolderIds.clear();
      _drawerSelectedPageIds.clear();
      _drawerLastAnchorIndex = null;
    });
    _appSnack(
        context,
        SnackBar(
          backgroundColor: const Color(0xFF43B97F),
          duration: const Duration(seconds: 3),
          content: Text(provider.t('drawer.bulkDeleted'),
              style: const TextStyle(color: Colors.white)),
        ));
  }

  /// フォルダー名変更ダイアログ
  void _renameFolderDialog(
      BuildContext context, MindMapProvider provider, MindMapFolder folder) {
    final ctrl = TextEditingController(text: folder.name);
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('folder.rename'),
            style: const TextStyle(color: Colors.white)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          decoration: InputDecoration(
            hintText: provider.t('folder.nameHint'),
            hintStyle: const TextStyle(color: Colors.white38),
          ),
          onSubmitted: (_) {
            final name = ctrl.text.trim();
            if (name.isNotEmpty) provider.renameFolder(folder.id, name);
            Navigator.pop(ctx);
          },
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
            onPressed: () {
              final name = ctrl.text.trim();
              if (name.isNotEmpty) provider.renameFolder(folder.id, name);
              Navigator.pop(ctx);
            },
            child: Text(provider.t('btn.ok')),
          ),
        ],
      ),
    );
  }

  /// フォルダー削除確認
  void _confirmDeleteFolder(
      BuildContext context, MindMapProvider provider, MindMapFolder folder) {
    final pageCount = provider.pagesInFolder(folder.id).length;
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('folder.deleteTitle'),
            style: const TextStyle(color: Colors.white)),
        content: Text(
          pageCount == 0
              ? provider.t('folder.deleteConfirmEmpty')
              : provider
                  .t('folder.deleteConfirm')
                  .replaceAll('{name}', folder.name)
                  .replaceAll('{count}', '$pageCount'),
          style: const TextStyle(color: Colors.white70, fontSize: 13),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          if (pageCount > 0)
            TextButton(
              onPressed: () {
                provider.deleteFolder(folder.id, deletePages: false);
                Navigator.pop(ctx);
              },
              child: Text(provider.t('folder.deleteKeepPages'),
                  style: const TextStyle(color: Color(0xFF4FC3F7))),
            ),
          ElevatedButton(
            onPressed: () {
              provider.deleteFolder(folder.id, deletePages: pageCount > 0);
              Navigator.pop(ctx);
            },
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFFF6B6B),
                foregroundColor: Colors.white),
            child: Text(provider.t('btn.delete'),
                style: const TextStyle(
                    color: Colors.white, fontWeight: FontWeight.w700)),
          ),
        ],
      ),
    );
  }

  /// ページのアイコンを選ぶ (= ユーザー要望: ページ一覧のアイコンを個別に
  /// 設定したり、 種別でまとめて設定したりできるように)。
  Future<void> _showPageIconPicker(
      BuildContext ctx, MindMapProvider provider, MindMapPage page) async {
    // 'one' = このページだけ / 'type' = 同じ種類すべて
    var scope = 'one';
    final type = page.pageType ?? 'normal';
    final color = _pageIconColorOf(page.pageType);
    await showDialog<void>(
      context: ctx,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        final cur = provider.pageIconIndexFor(page.id, page.pageType);
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
          title: Row(children: [
            Icon(Icons.emoji_symbols_rounded, color: color, size: 20),
            const SizedBox(width: 8),
            Expanded(
              child: Text(provider.t('page.changeIcon'),
                  style:
                      const TextStyle(color: Colors.white, fontSize: 15)),
            ),
          ]),
          content: SizedBox(
            width: 420,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              // 適用する範囲。
              Row(children: [
                for (final e in [
                  ('one', provider.t('page.iconScopeOne')),
                  ('type', provider.t('page.iconScopeType')),
                ])
                  Padding(
                    padding: const EdgeInsets.only(right: 8),
                    child: InkWell(
                      borderRadius: BorderRadius.circular(999),
                      onTap: () => setD(() => scope = e.$1),
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 12, vertical: 7),
                        decoration: BoxDecoration(
                          color: scope == e.$1
                              ? color.withValues(alpha: 0.22)
                              : Colors.white.withValues(alpha: 0.06),
                          borderRadius: BorderRadius.circular(999),
                          border: Border.all(
                              color: scope == e.$1 ? color : Colors.white24),
                        ),
                        child: Text(e.$2,
                            style: TextStyle(
                                color: scope == e.$1
                                    ? Colors.white
                                    : Colors.white70,
                                fontSize: 12,
                                fontWeight: FontWeight.w700)),
                      ),
                    ),
                  ),
              ]),
              const SizedBox(height: 10),
              SizedBox(
                height: 260,
                child: GridView.builder(
                  gridDelegate:
                      const SliverGridDelegateWithFixedCrossAxisCount(
                    crossAxisCount: 7,
                    mainAxisSpacing: 6,
                    crossAxisSpacing: 6,
                  ),
                  itemCount: kPageIconChoices.length,
                  itemBuilder: (_, i) {
                    final selected = cur == i;
                    return InkWell(
                      borderRadius: BorderRadius.circular(10),
                      onTap: () async {
                        if (scope == 'type') {
                          await provider.setPageTypeIcon(type, i);
                        } else {
                          await provider.setPageIcon(page.id, i);
                        }
                        setD(() {});
                      },
                      child: Container(
                        decoration: BoxDecoration(
                          color: selected
                              ? color.withValues(alpha: 0.22)
                              : Colors.white.withValues(alpha: 0.05),
                          borderRadius: BorderRadius.circular(10),
                          border: Border.all(
                              color: selected ? color : Colors.white12),
                        ),
                        child: Icon(kPageIconChoices[i],
                            size: 20,
                            color: selected ? color : Colors.white70),
                      ),
                    );
                  },
                ),
              ),
            ]),
          ),
          actions: [
            TextButton(
              onPressed: () async {
                // 元のアイコンに戻す。
                if (scope == 'type') {
                  await provider.setPageTypeIcon(type, null);
                } else {
                  await provider.setPageIcon(page.id, null);
                }
                setD(() {});
              },
              child: Text(provider.t('page.iconReset'),
                  style: const TextStyle(color: Color(0xFFE57373))),
            ),
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.close'),
                  style: const TextStyle(color: Colors.white54)),
            ),
          ],
        );
      }),
    );
  }

  /// ページ長押しメニュー(JSON エクスポート / フォルダーへ移動 / 名前変更 / 削除)
  /// ページの「・・・」メニュー。
  /// `anchorKey` で指定したウィジェットの位置の隣にポップオーバー表示する。
  /// 複数選択中なら一括削除メニューを提供する。
  void _showPageContextMenu(
      BuildContext context, MindMapProvider provider, MindMapPage page,
      [BuildContext? anchorCtx, GlobalKey? fallbackKey]) {
    // ── 安全な context 取得 ──
    // 呼び出し元が PopupMenuButton 経由で次フレームに遅延した場合、
    // 当初の context は無効化されている可能性がある。State の
    // context を優先して使う (mounted チェック付き)。
    if (!mounted) return;
    final ctx = this.context;
    final pageIds = _drawerSelectedPageIds.contains(page.id)
        ? _drawerSelectedPageIds.toList()
        : [page.id];
    final folderIds = _drawerSelectedFolderIds.toList();
    final isBulk = pageIds.length > 1 || folderIds.isNotEmpty;

    // ── 表示位置の計算 ──
    // 優先: anchorCtx (「・・・」ボタンの BuildContext) → その RenderBox の右下
    // 次点: fallbackKey (タイル全体の KeyedSubtree GlobalKey)
    // 最終: 画面左上付近
    RelativeRect position;
    final overlay = Overlay.of(ctx).context.findRenderObject() as RenderBox;
    RenderBox? anchorBox;
    if (anchorCtx != null) {
      final ro = anchorCtx.findRenderObject();
      if (ro is RenderBox && ro.attached) anchorBox = ro;
    }
    if (anchorBox == null && fallbackKey?.currentContext != null) {
      final ro = fallbackKey!.currentContext!.findRenderObject();
      if (ro is RenderBox && ro.attached) anchorBox = ro;
    }
    if (anchorBox != null) {
      final topLeft = anchorBox.localToGlobal(Offset.zero, ancestor: overlay);
      final bottomRight = anchorBox.localToGlobal(
          anchorBox.size.bottomRight(Offset.zero),
          ancestor: overlay);
      position = RelativeRect.fromRect(
        Rect.fromPoints(topLeft, bottomRight),
        Offset.zero & overlay.size,
      );
    } else {
      position = const RelativeRect.fromLTRB(80, 120, 0, 0);
    }
    // 移動先メニューを同じ位置に出すため覚えておく (= ユーザー要望)。
    _lastPageMenuPos = position;

    final items = <PopupMenuEntry<_PageAction>>[];
    // ── ヘッダー (選択件数) は複数選択時のみ表示 ──
    // ユーザー要望: 単一ページのメニューでは「どのページか分かっているので
    //   一番上のページ名ヘッダーは不要。 ページ名を変更から始めて」。
    //   複数選択時は件数表示が有用なので残す。
    if (isBulk) {
      items.add(PopupMenuItem<_PageAction>(
        enabled: false,
        height: 32,
        child: Row(children: [
          const Icon(Icons.description_outlined,
              color: Color(0xFF6C63FF), size: 16),
          const SizedBox(width: 8),
          Flexible(
            child: Text(
                '${pageIds.length}${provider.t('drawer.selectedSuffix')}'
                '${folderIds.isNotEmpty ? " + ${folderIds.length}${provider.t('drawer.foldersSelected')}" : ""}',
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                    color: Colors.white,
                    fontSize: 12,
                    fontWeight: FontWeight.w700)),
          ),
        ]),
      ));
      items.add(const PopupMenuDivider());
    }

    if (!isBulk) {
      items.addAll([
        _menuItem<_PageAction>(
            value: _PageAction.rename,
            icon: Icons.edit_outlined,
            iconColor: const Color(0xFF4FC3F7),
            label: provider.t('page.rename')),
        _menuItem<_PageAction>(
            value: _PageAction.moveToFolder,
            icon: Icons.drive_file_move_outlined,
            iconColor: const Color(0xFFFFB347),
            label: provider.t('page.moveToFolder')),
        // ── アイコンを変える (= ユーザー要望: ページごと / 種類ごとに) ──
        _menuItem<_PageAction>(
            value: _PageAction.changeIcon,
            icon: Icons.emoji_symbols_rounded,
            iconColor: const Color(0xFF5FD3B2),
            label: provider.t('page.changeIcon')),
        // 注: 「プレビュー用ファイルとして書き出し」 (HTML) は削除
        //     (= ユーザー要望: 読み込めないので意味が無い)。 持ち出しは
        //     下の .hnmap (画像・動画ごと) を使う。
        // ── 画像 / 動画ごと持ち出せる書き出し (= ユーザー要望) ──
        _menuItem<_PageAction>(
            value: _PageAction.exportBundle,
            icon: Icons.inventory_2_outlined,
            iconColor: const Color(0xFFBA68C8),
            label: provider.t('export.bundle')),
        // ── Web に公開 (= ユーザー要望: サーバーに公開して皆で見られるように) ──
        _menuItem<_PageAction>(
            value: _PageAction.publish,
            // ★ 共有済みかは publishedCodeFor で見る。 publishedUrlFor は
            //   url が空でない時だけ返すが、 共同編集の登録は url を空で
            //   書くので常に null になり、 共有中でも「未共有」 の見た目に
            //   なっていた (= 検証で判明)。
            icon: provider.publishedCodeFor(page.id) != null
                ? Icons.public_rounded
                : Icons.public_off_rounded,
            iconColor: provider.publishedCodeFor(page.id) != null
                ? const Color(0xFF43B97F)
                : const Color(0xFF4FC3F7),
            label: provider.t(provider.publishedCodeFor(page.id) != null
                ? 'publish.menuPublished'
                : 'publish.menu')),
        // ── マークダウンで編集 (= ユーザー要望: JSON でなく Markdown で書ける/
        //   模式図でプレビュー)。 通常マップのみ。 ──
        if (page.pageType == 'normal')
          _menuItem<_PageAction>(
              value: _PageAction.markdown,
              icon: Icons.notes_rounded,
              iconColor: const Color(0xFF26C6DA),
              label: provider.t('page.markdownEdit')),
        // ── Markdown 書き出し (= ユーザー要望) ──
        if (page.pageType == 'normal')
          _menuItem<_PageAction>(
              value: _PageAction.markdownExport,
              icon: Icons.description_outlined,
              iconColor: const Color(0xFF26C6DA),
              label: provider.t('page.markdownExport')),
        // ── 別マップへ全要素を移動してこのマップを削除 (= ユーザー要望) ──
        if (provider.pages.length > 1 &&
            MindMapProvider.isMergeablePageType(page.pageType))
          _menuItem<_PageAction>(
              value: _PageAction.moveAllToMap,
              icon: Icons.drive_file_move_rounded,
              iconColor: const Color(0xFFFFB347),
              label: provider.t('page.moveAllToMap')),
        if (provider.pages.length > 1)
          _menuItem<_PageAction>(
              value: _PageAction.delete,
              icon: Icons.delete_outline_rounded,
              iconColor: const Color(0xFFFF6B6B),
              label: provider.t('page.delete')),
        // ── 区切り ──
        const PopupMenuDivider(),
        // ── お気に入り (現在開いているページに対して) ──
        _menuItem<_PageAction>(
            value: _PageAction.toggleFavorite,
            icon: provider.isPageFavorite(page.id)
                ? Icons.star_rounded
                : Icons.star_outline_rounded,
            iconColor: const Color(0xFFFFC107),
            label: provider.isPageFavorite(page.id)
                ? provider.t('page.unpin')
                : provider.t('page.pin')),
        // ── ホーム画面/デスクトップにこのマップのショートカットを作成 ──
        // (= ユーザー要望: マップごとにアプリ風のショートカットを置いて、
        //   そのマップを直接開けるように)。
        if (HomeShortcutService.isSupported)
          _menuItem<_PageAction>(
              value: _PageAction.createShortcut,
              icon: Icons.add_to_home_screen_rounded,
              iconColor: const Color(0xFF66BB6A),
              label: (!kIsWeb && Platform.isWindows)
                  ? 'デスクトップにショートカット作成'
                  : 'ホーム画面にショートカット作成'),
        // ── ユーザー要望により「このページを非表示」「マップ順をシャッフル」
        //   (および各リセット/復元) は menu から削除。 機能本体
        //   (provider.hidePage / shufflePages 等) は他からの参照互換のため
        //   残置している。
      ]);
    } else {
      items.add(_menuItem<_PageAction>(
          value: _PageAction.bulkDelete,
          icon: Icons.delete_sweep_rounded,
          iconColor: const Color(0xFFFF6B6B),
          label: provider.t('drawer.bulkDelete')));
      items.add(_menuItem<_PageAction>(
          value: _PageAction.clearSelection,
          icon: Icons.deselect_rounded,
          iconColor: Colors.white54,
          label: provider.t('drawer.tip.clearSelection')));
    }

    showMenu<_PageAction>(
      context: ctx,
      position: position,
      color: const Color(0xFF1E1E32),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(10),
        side: BorderSide(color: Colors.white.withValues(alpha: 0.12)),
      ),
      items: items,
    ).then((action) {
      if (action == null || !mounted) return;
      switch (action) {
        case _PageAction.rename:
          final i = provider.pages.indexOf(page);
          if (i >= 0) _renamePageDialog(ctx, provider, i);
          break;
        case _PageAction.moveToFolder:
          _showMoveToFolderSheet(ctx, provider, page);
          break;
        case _PageAction.changeIcon:
          // ignore: discarded_futures
          _showPageIconPicker(ctx, provider, page);
          break;
        case _PageAction.export:
          _exportPageToJson(ctx, provider, page);
          break;
        case _PageAction.exportBundle:
          _exportPageBundle(ctx, provider, page);
          break;
        case _PageAction.publish:
          _showPublishPageDialog(ctx, provider, page);
          break;
        case _PageAction.markdown:
          _showMarkdownMindMapDialog(ctx, provider, page);
          break;
        case _PageAction.markdownExport:
          _exportPageToMarkdown(ctx, provider, page);
          break;
        case _PageAction.moveAllToMap:
          if (!MindMapProvider.isMergeablePageType(page.pageType)) break;
          _moveAllElementsToMap(ctx, provider, page);
          break;
        case _PageAction.delete:
          final i = provider.pages.indexOf(page);
          if (i >= 0) _confirmDeletePageAt(ctx, provider, i);
          break;
        case _PageAction.bulkDelete:
          _confirmBulkDelete(ctx, provider,
              folderIds: folderIds, pageIds: pageIds);
          break;
        case _PageAction.clearSelection:
          setState(() {
            _drawerSelectedFolderIds.clear();
            _drawerSelectedPageIds.clear();
            _drawerLastAnchorIndex = null;
          });
          break;
        case _PageAction.hide:
          provider.hidePage(page.id);
          _appSnack(
            ctx,
            SnackBar(
              content: Text(
                  provider.t('page.hidden').replaceFirst('{name}', page.name),
                  style: const TextStyle(fontSize: 12)),
              backgroundColor: const Color(0xFF9E9E9E),
              action: SnackBarAction(
                label: provider.t('btn.undo'),
                textColor: Colors.white,
                onPressed: () => provider.unhidePage(page.id),
              ),
              duration: const Duration(seconds: 4),
            ),
          );
          break;
        case _PageAction.resetHidden:
          provider.resetHiddenPages();
          _appSnack(
            ctx,
            SnackBar(
              content: Text(provider.t('page.allShown'),
                  style: const TextStyle(fontSize: 12)),
              backgroundColor: const Color(0xFF4FC3F7),
              duration: const Duration(seconds: 2),
            ),
          );
          break;
        case _PageAction.shuffle:
          provider.shufflePages();
          _appSnack(
            ctx,
            SnackBar(
              content: Text(provider.t('page.shuffled'),
                  style: const TextStyle(fontSize: 12)),
              backgroundColor: const Color(0xFFAB47BC),
              duration: const Duration(seconds: 3),
            ),
          );
          break;
        case _PageAction.restoreOrder:
          provider.restorePageOrder();
          _appSnack(
            ctx,
            SnackBar(
              content: Text(provider.t('page.orderRestored'),
                  style: const TextStyle(fontSize: 12)),
              backgroundColor: const Color(0xFF66BB6A),
              duration: const Duration(seconds: 2),
            ),
          );
          break;
        case _PageAction.toggleFavorite:
          final wasFav = provider.isPageFavorite(page.id);
          provider.toggleFavoritePage(page.id);
          _appSnack(
            ctx,
            SnackBar(
              content: Text(
                  wasFav
                      ? provider
                          .t('page.unpinnedSnack')
                          .replaceAll('{name}', page.name)
                      : provider
                          .t('page.pinnedSnack')
                          .replaceAll('{name}', page.name),
                  style: const TextStyle(fontSize: 12)),
              backgroundColor: const Color(0xFFFFC107),
              duration: const Duration(seconds: 2),
            ),
          );
          break;
        case _PageAction.createShortcut:
          () async {
            // ページのショートカットも同じ作成先を使う (= ユーザー要望)。
            await _loadShortcutDestDir();
            final ok = await HomeShortcutService.pinMapShortcut(
                pageId: page.id,
                label: page.name,
                destDir: _shortcutDestDir);
            if (!mounted) return;
            final isWin = !kIsWeb && Platform.isWindows;
            _appSnack(
              ctx,
              SnackBar(
                content: Text(
                    ok
                        ? (isWin
                            ? '「${page.name}」 のショートカットをデスクトップに作成しました'
                            : '「${page.name}」 のショートカットをホーム画面に追加しました')
                        : 'ショートカットを作成できませんでした',
                    style: const TextStyle(fontSize: 12)),
                backgroundColor:
                    ok ? const Color(0xFF66BB6A) : const Color(0xFFE57373),
                duration: const Duration(seconds: 3),
              ),
            );
          }();
          break;
      }
    });
  }

  /// 「フォルダーへ移動」シート: 既存フォルダーから選択 or 新規作成 or ルートに戻す
  /// 直前に開いたページメニューの位置 (= ユーザー要望: 移動先の一覧は
  /// 画面下からではなく、 押したボタンの近くに出す)。
  RelativeRect? _lastPageMenuPos;

  void _showMoveToFolderSheet(
      BuildContext context, MindMapProvider provider, MindMapPage page) {
    // ── 押したボタンの近くにメニューとして出す (= ユーザー要望) ──
    final anchor = _lastPageMenuPos;
    if (anchor != null) {
      // ignore: discarded_futures
      showMenu<String>(
        context: context,
        position: anchor,
        color: const Color(0xFF1E1E32),
        items: [
          PopupMenuItem<String>(
            value: '',
            child: Row(children: [
              const Icon(Icons.eject_outlined,
                  color: Color(0xFF4FC3F7), size: 18),
              const SizedBox(width: 10),
              Expanded(
                child: Text(provider.t('page.moveToRoot'),
                    style:
                        const TextStyle(color: Colors.white, fontSize: 13.5)),
              ),
              if (page.folderId == null)
                const Icon(Icons.check_rounded,
                    color: Color(0xFF43B97F), size: 16),
            ]),
          ),
          for (final f in provider.folders)
            PopupMenuItem<String>(
              value: f.id,
              child: Row(children: [
                const Icon(Icons.folder_rounded,
                    color: Color(0xFFFFB347), size: 18),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(f.name,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style:
                          const TextStyle(color: Colors.white, fontSize: 13.5)),
                ),
                if (page.folderId == f.id)
                  const Icon(Icons.check_rounded,
                      color: Color(0xFF43B97F), size: 16),
              ]),
            ),
          const PopupMenuDivider(),
          PopupMenuItem<String>(
            value: '__new__',
            child: Row(children: [
              const Icon(Icons.create_new_folder_outlined,
                  color: Color(0xFFFFB347), size: 18),
              const SizedBox(width: 10),
              Expanded(
                child: Text(provider.t('folder.createAndMove'),
                    style:
                        const TextStyle(color: Colors.white, fontSize: 13.5)),
              ),
            ]),
          ),
        ],
      ).then((sel) {
        if (sel == null || !mounted) return;
        if (sel == '__new__') {
          _addFolderAndMoveDialog(this.context, provider, page);
          return;
        }
        provider.movePageToFolder(page.id, sel.isEmpty ? null : sel);
      });
      return;
    }
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: const Color(0xFF1E1E32),
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(20))),
      builder: (sheetCtx) {
        return SafeArea(
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 14, 16, 8),
              child: Text(provider.t('page.moveToFolder'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 14,
                      fontWeight: FontWeight.w700)),
            ),
            const Divider(color: Colors.white12, height: 1),
            // ルート(フォルダー外)
            ListTile(
              leading:
                  const Icon(Icons.eject_outlined, color: Color(0xFF4FC3F7)),
              title: Text(provider.t('page.moveToRoot'),
                  style: const TextStyle(color: Colors.white, fontSize: 14)),
              trailing: page.folderId == null
                  ? const Icon(Icons.check_rounded, color: Color(0xFF43B97F))
                  : null,
              onTap: () {
                provider.movePageToFolder(page.id, null);
                Navigator.pop(sheetCtx);
              },
            ),
            const Divider(color: Colors.white12, height: 1),
            // 既存フォルダー
            for (final f in provider.folders)
              ListTile(
                leading:
                    const Icon(Icons.folder_rounded, color: Color(0xFFFFB347)),
                title: Text(f.name,
                    style: const TextStyle(color: Colors.white, fontSize: 14)),
                trailing: page.folderId == f.id
                    ? const Icon(Icons.check_rounded, color: Color(0xFF43B97F))
                    : null,
                onTap: () {
                  provider.movePageToFolder(page.id, f.id);
                  Navigator.pop(sheetCtx);
                },
              ),
            // 新規フォルダー作成
            ListTile(
              leading: const Icon(Icons.create_new_folder_outlined,
                  color: Color(0xFFFFB347)),
              title: Text(provider.t('folder.createAndMove'),
                  style: const TextStyle(color: Colors.white, fontSize: 14)),
              onTap: () {
                Navigator.pop(sheetCtx);
                _addFolderAndMoveDialog(context, provider, page);
              },
            ),
            const SizedBox(height: 8),
          ]),
        );
      },
    );
  }

  /// 新規フォルダー作成 + ページをそのフォルダーに移動
  void _addFolderAndMoveDialog(
      BuildContext context, MindMapProvider provider, MindMapPage page) {
    final ctrl = TextEditingController();
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('folder.newTitle'),
            style: const TextStyle(color: Colors.white)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          decoration: InputDecoration(
            hintText: provider.t('folder.nameHint'),
            hintStyle: const TextStyle(color: Colors.white38),
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
            onPressed: () {
              final name = ctrl.text.trim();
              final id = provider.addFolder(name: name.isEmpty ? null : name);
              provider.movePageToFolder(page.id, id);
              Navigator.pop(ctx);
            },
            child: Text(provider.t('folder.create')),
          ),
        ],
      ),
    );
  }

  // ─── 移動中ノードの仮位置マップ（接続線アニメーション用） ──────────────────
  Map<String, MindMapNode> _movingNodes(Map<String, MindMapNode> base) {
    // ドラッグしていない時は元の Map を「同じ参照のまま」返す。 毎回コピーを
    //   作ると ConnectionPainter.shouldRepaint が常に true になり、 ホバーや
    //   無関係な setState でも全接続線を描き直してしまう (= 重さの一因)。
    //   ドラッグ中だけ仮位置を反映したコピーを作る。
    final bool dragging = (_moveModeNodeId != null && _movingPos != null) ||
        (_rangeDragging && _rangeDragDelta != Offset.zero);
    if (!dragging) return base;
    final copy = Map<String, MindMapNode>.of(base);
    // 単体ドラッグ
    if (_moveModeNodeId != null && _movingPos != null) {
      final node = copy[_moveModeNodeId];
      if (node != null) {
        copy[_moveModeNodeId!] = node.copyWith(position: _movingPos);
      }
    }
    // 範囲ドラッグ
    if (_rangeDragging && _rangeDragDelta != Offset.zero) {
      for (final id in _rangeSelectedIds) {
        final node = copy[id];
        if (node != null) {
          copy[id] = node.copyWith(
            position: Offset(
              (node.position.dx + _rangeDragDelta.dx).clamp(0.0, 20000.0),
              (node.position.dy + _rangeDragDelta.dy).clamp(0.0, 20000.0),
            ),
          );
        }
      }
    }
    return copy;
  }

  // ─── キャンバス ───────────────────────────────────────────────────────────

  /// ページ背景を「表示領域いっぱい」に敷き詰める (= ユーザー要望: キャンバスの
  /// 外に出られない枠から先にも背景が続くように)。InteractiveViewer の外側
  /// (スクリーン座標) に固定配置するので、パン/ズームしても常に画面全体を覆う
  /// 壁紙になる。cover=全面を覆う / tile=画像を敷き詰める / contain=画像全体を中央に。
  Widget _buildInfinitePageBackground(
      MindMapProvider provider, TransformationController ctrl,
      {MindMapPage? pageOverride}) {
    // 分割ペインでは表示中の別ページの背景を使う (= ユーザー要望: 分割の
    // 右側で背景が反映されない問題の修正)。
    final page = pageOverride ?? provider.currentPage;

    final path = (page.backgroundImagePath ?? '').trim();
    if (path.isEmpty) return const SizedBox.shrink();
    final templateId = _mapBackgroundTemplateId(path);
    final opacity = (page.backgroundOpacityPercent.clamp(0, 100)) / 100.0;
    Widget bg;
    if (templateId != null) {
      bg = AnimatedBuilder(
        animation: ctrl,
        builder: (_, __) => _MapBackgroundTemplateView(
          templateId: templateId,
          scrollOffset: ctrl.toScene(Offset.zero),
          hueDegrees: page.backgroundHueDegrees,
          saturationPercent: page.backgroundSaturationPercent,
          brightnessPercent: page.backgroundBrightnessPercent,
        ),
      );
    } else {
      final file = File(path);
      if (!file.existsSync()) return const SizedBox.shrink();
      BoxFit fit;
      ImageRepeat repeat = ImageRepeat.noRepeat;
      switch (page.backgroundFit) {
        case 'contain':
          fit = BoxFit.contain;
          break;
        case 'tile':
          fit = BoxFit.none;
          repeat = ImageRepeat.repeat;
          break;
        case 'cover':
        default:
          fit = BoxFit.cover;
      }
      bg = Image.file(
        file,
        fit: fit,
        repeat: repeat,
        errorBuilder: (_, __, ___) => const SizedBox.shrink(),
        gaplessPlayback: true,
      );
    }
    return Positioned.fill(
      child: IgnorePointer(
        child: Opacity(opacity: opacity, child: bg),
      ),
    );
  }

  Size _canvasDimensionForScrollbars(MindMapProvider provider,
      {MindMapPage? pageOverride}) {
    // ── 分割ペイン用: 指定ページのノード範囲から算出する ──
    if (pageOverride != null) {
      if (pageOverride.pageType == 'bookshelf') {
        // +ボックス格子まで含めた実寸 (= 編集側と同じ) を使う。
        final s = provider.bookshelfCanvasSize(pageOverride: pageOverride);
        return Size(math.max(1.0, s.width), math.max(1.0, s.height));
      }
      // 編集側と同じく、 折りたたみで隠れているノードは除外する
      // (= ペインの InteractiveViewer の実境界と食い違わせない)。
      final paneHidden = provider.hiddenNodeIdsOnPage(pageOverride);
      final paneVisible = paneHidden.isEmpty
          ? pageOverride.nodes
          : Map<String, MindMapNode>.fromEntries(pageOverride.nodes.entries
              .where((e) => !paneHidden.contains(e.key)));
      if (paneVisible.isEmpty) return const Size(2000, 2000);
      final extent = computeCanvasSize(paneVisible);
      return Size(extent, extent);
    }
    if (provider.currentPage.pageType == 'bookshelf') {
      // ── スクロールバーの可動域をパンのクランプ範囲と一致させる ──
      // (= ユーザー要望: 移動が制限される位置でスクロールバーが端まで
      //    来るように)。 旧実装は固定キャンバス寸 + 2000px 余白だったため、
      //    バーを端まで持って行けなかった。 内容バウンディングを使う。
      final bounds = _bookshelfContentBounds(provider);
      if (bounds != null) {
        // 原点 0 から内容右端/下端まで。 左/上のはみ出し分は margin 側で扱う。
        return Size(math.max(1.0, bounds.right), math.max(1.0, bounds.bottom));
      }
      return provider.bookshelfCanvasSize();
    }
    // 実キャンバスと同じく、折りたたみで非表示の子孫は extent から除外する。
    // 全ノードで計算すると、遠方の非表示ノードぶんだけ scrollbar が空白域へ
    // 動けてしまい InteractiveViewer の実境界と食い違う。
    final hidden = provider.hiddenNodeIds;
    final visibleNodes = Map<String, MindMapNode>.fromEntries(
      provider.nodes.entries.where((entry) => !hidden.contains(entry.key)),
    );
    final extent = computeCanvasSize(visibleNodes);
    return Size(extent, extent);
  }

  EdgeInsets _canvasBoundaryMarginForScrollbars(
      MindMapProvider provider, BuildContext context,
      {MindMapPage? pageOverride}) {
    // ── 分割ペイン用: 指定ページのノード範囲に余白を足す ──
    if (pageOverride != null) {
      if (pageOverride.pageType != 'bookshelf') return EdgeInsets.zero;
      double minX = double.infinity, minY = double.infinity;
      for (final n in pageOverride.nodes.values) {
        minX = math.min(minX, n.position.dx);
        minY = math.min(minY, n.position.dy);
      }
      if (!minX.isFinite) return const EdgeInsets.all(2000);
      const pad = 120.0;
      return EdgeInsets.fromLTRB(-minX + pad, -minY + pad, pad, pad);
    }
    if (provider.currentPage.pageType != 'bookshelf') {
      return EdgeInsets.zero;
    }
    // ── パンのクランプ (_clampBookshelfPan) と同じ範囲にする ──
    // (= ユーザー要望: バーが端に来る位置とパンの止まる位置を一致させる)。
    // クランプ側の余白 (キャンバス座標 120px) をそのまま margin に使う。
    final bounds = _bookshelfContentBounds(provider);
    if (bounds != null) {
      const pad = 120.0;
      return EdgeInsets.fromLTRB(
          -bounds.left + pad, -bounds.top + pad, pad, pad);
    }
    return const EdgeInsets.all(2000);
  }

  /// スクロールバーを表示する「操作中のペイン」 (= ユーザー要望: バーを
  /// 動かした時に他の画面のバーまで出ないように)。 'editor' = 編集セル、
  /// int = 分割ペインのセル番号。
  Object _mapScrollbarOwner = 'editor';

  // ─── 全体図 (ミニマップ) は「動いている間だけ」 出す (= ユーザー要望:
  //     画面が動いた時だけ表示、 止まっている時は出さない) ───────────────
  /// 今、 全体図を出しているか。
  bool _miniMapActive = false;

  /// カーソルが全体図の上にあるか (乗せている間は消さない)。
  bool _miniMapHover = false;
  Timer? _miniMapHideTimer;
  bool _miniMapShowPending = false;

  /// 画面が動いた合図。 出してから少し経つと自動で消える。
  void _markMiniMapActivity() {
    if (!mounted) return;
    _miniMapHideTimer?.cancel();
    if (!_miniMapActive && !_miniMapShowPending) {
      _miniMapShowPending = true;
      // リスナーの中から直接 setState は呼べないので次のフレームで。
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _miniMapShowPending = false;
        if (!mounted || _miniMapActive) return;
        setState(() => _miniMapActive = true);
      });
    }
    _miniMapHideTimer = Timer(const Duration(milliseconds: 1400), () {
      if (!mounted || !_miniMapActive) return;
      // カーソルを乗せている間は消さない (押して移動できるように)。
      if (_miniMapHover) {
        _markMiniMapActivity();
        return;
      }
      setState(() => _miniMapActive = false);
    });
  }

  void _markMapScrollActivity({Object owner = 'editor'}) {
    if (!mounted || !_isDesktop) return;
    _mapScrollbarHideTimer?.cancel();
    if (_mapScrollbarOwner != owner) {
      setState(() => _mapScrollbarOwner = owner);
    }
    if (!_mapScrollbarsVisible && !_mapScrollbarShowPending) {
      _mapScrollbarShowPending = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _mapScrollbarShowPending = false;
        if (!mounted || _mapScrollbarsVisible) return;
        setState(() => _mapScrollbarsVisible = true);
      });
    }
    _mapScrollbarHideTimer = Timer(const Duration(milliseconds: 900), () {
      if (!mounted) return;
      if (_mapScrollbarsVisible || _activeMapScrollbarAxis != null) {
        setState(() {
          _mapScrollbarsVisible = false;
          _activeMapScrollbarAxis = null;
        });
      }
    });
  }

  void _setActiveMapScrollbarAxis(Axis? axis, {Object owner = 'editor'}) {
    if (!mounted || _activeMapScrollbarAxis == axis) return;
    if (axis != null) _markMapScrollActivity(owner: owner);
    setState(() => _activeMapScrollbarAxis = axis);
  }

  void _setMapScrollbarProgress({
    required MindMapProvider provider,
    required TransformationController ctrl,
    required Axis axis,
    required double progress,
    required Size viewportSize,
    MindMapPage? pageOverride,
    Object owner = 'editor',
  }) {
    if ((axis == Axis.horizontal && _lockH) ||
        (axis == Axis.vertical && _lockV)) {
      return;
    }
    _markMapScrollActivity(owner: owner);
    final canvasDim =
        _canvasDimensionForScrollbars(provider, pageOverride: pageOverride);
    final margin = _canvasBoundaryMarginForScrollbars(provider, context,
        pageOverride: pageOverride);
    final matrix = Matrix4.copy(ctrl.value);
    final scale = matrix.getMaxScaleOnAxis();
    final translation = matrix.getTranslation();
    final normalized = progress.clamp(0.0, 1.0).toDouble();
    var tx = translation.x;
    var ty = translation.y;

    if (axis == Axis.horizontal) {
      final maxX = margin.left * scale;
      final minX =
          viewportSize.width - (canvasDim.width + margin.right) * scale;
      final range = math.max(0.0, maxX - minX);
      tx = range <= 0 ? (minX + maxX) / 2 : maxX - range * normalized;
    } else {
      final maxY = margin.top * scale;
      final minY =
          viewportSize.height - (canvasDim.height + margin.bottom) * scale;
      final range = math.max(0.0, maxY - minY);
      ty = range <= 0 ? (minY + maxY) / 2 : maxY - range * normalized;
    }

    matrix.setTranslationRaw(tx, ty, 0);
    // TransformationController の listener は同期発火するため、直前行列を先に
    // 合わせてロック補正が古いページ位置を参照しないようにする。
    _lastMatrix = matrix.clone();
    ctrl.value = matrix;
  }

  /// InteractiveViewer は Scrollable ではないため、変換行列と同期する縦横 2 本の
  /// スクロールバーを重ねる。トラックのクリックとつまみのドラッグの両方に対応。
  Widget _buildMapViewportScrollbars(
      MindMapProvider provider, TransformationController ctrl,
      {MindMapPage? pageOverride, Object owner = 'editor'}) {
    return Positioned.fill(
      child: LayoutBuilder(
        builder: (context, constraints) {
          final viewport = constraints.biggest;
          if (!viewport.width.isFinite ||
              !viewport.height.isFinite ||
              viewport.width < 80 ||
              viewport.height < 80) {
            return const SizedBox.shrink();
          }
          final canvasDim = _canvasDimensionForScrollbars(provider,
              pageOverride: pageOverride);
          final margin = _canvasBoundaryMarginForScrollbars(provider, context,
              pageOverride: pageOverride);

          return AnimatedBuilder(
            animation: ctrl,
            builder: (context, _) {
              final matrix = ctrl.value;
              final scale = matrix.getMaxScaleOnAxis();
              final translation = matrix.getTranslation();
              final horizontalRange = math.max(
                0.0,
                (canvasDim.width + margin.horizontal) * scale - viewport.width,
              );
              final verticalRange = math.max(
                0.0,
                (canvasDim.height + margin.vertical) * scale - viewport.height,
              );
              final horizontalMax = margin.left * scale;
              final verticalMax = margin.top * scale;
              final horizontalProgress = horizontalRange <= 0
                  ? 0.0
                  : ((horizontalMax - translation.x) / horizontalRange)
                      .clamp(0.0, 1.0)
                      .toDouble();
              final verticalProgress = verticalRange <= 0
                  ? 0.0
                  : ((verticalMax - translation.y) / verticalRange)
                      .clamp(0.0, 1.0)
                      .toDouble();

              const edgeInset = 6.0;
              const oppositeBarSpace = 24.0;
              const hitThickness = 18.0;
              const innerInset = 2.0;
              final horizontalTrackLength =
                  math.max(1.0, viewport.width - edgeInset - oppositeBarSpace);
              final verticalTrackLength =
                  math.max(1.0, viewport.height - edgeInset - oppositeBarSpace);
              final horizontalInnerLength =
                  math.max(1.0, horizontalTrackLength - innerInset * 2);
              final verticalInnerLength =
                  math.max(1.0, verticalTrackLength - innerInset * 2);
              // ── つまみの長さは「実際に動かせる量」 から決める
              //    (= ユーザー報告: ギャラリーで明らかに横へスライドできるのに
              //    つまみがほぼ全長を占めておかしい)。 内容の実寸から出すと、
              //    パンのクランプ範囲とズレて「動かせるのにつまみは満杯」 に
              //    なり得る。 可動域 (range) と揃えれば必ず一致する。 ──
              final horizontalVisibleFraction =
                  (viewport.width / (viewport.width + horizontalRange))
                      .clamp(0.0, 1.0)
                      .toDouble();
              final verticalVisibleFraction =
                  (viewport.height / (viewport.height + verticalRange))
                      .clamp(0.0, 1.0)
                      .toDouble();
              final horizontalThumbLength = math.min(
                horizontalInnerLength,
                math.max(
                    44.0, horizontalInnerLength * horizontalVisibleFraction),
              );
              final verticalThumbLength = math.min(
                verticalInnerLength,
                math.max(44.0, verticalInnerLength * verticalVisibleFraction),
              );
              final horizontalTravel =
                  math.max(0.0, horizontalInnerLength - horizontalThumbLength);
              final verticalTravel =
                  math.max(0.0, verticalInnerLength - verticalThumbLength);
              final horizontalThumbOffset =
                  innerInset + horizontalTravel * horizontalProgress;
              final verticalThumbOffset =
                  innerInset + verticalTravel * verticalProgress;
              final trackColor = provider.isDarkMode
                  ? Colors.black.withValues(alpha: 0.44)
                  : Colors.white.withValues(alpha: 0.72);
              final idleThumbColor = provider.isDarkMode
                  ? Colors.white.withValues(alpha: 0.62)
                  : const Color(0xFF4E5268).withValues(alpha: 0.68);
              const activeThumbColor = Color(0xFF6C63FF);

              Widget horizontalBar() {
                final active = _activeMapScrollbarAxis == Axis.horizontal;
                final disabled = _lockH || horizontalRange <= 0;
                return MouseRegion(
                  cursor: disabled
                      ? SystemMouseCursors.basic
                      : SystemMouseCursors.resizeLeftRight,
                  onEnter: (_) => _setActiveMapScrollbarAxis(Axis.horizontal,
                      owner: owner),
                  onExit: (_) {
                    if (_activeMapScrollbarAxis == Axis.horizontal) {
                      _setActiveMapScrollbarAxis(null, owner: owner);
                    }
                  },
                  child: Semantics(
                    label: '横スクロールバー',
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onHorizontalDragStart: disabled
                          ? null
                          : (_) => _setActiveMapScrollbarAxis(Axis.horizontal,
                              owner: owner),
                      onHorizontalDragUpdate: disabled || horizontalTravel <= 0
                          ? null
                          : (details) => _setMapScrollbarProgress(
                                provider: provider,
                                ctrl: ctrl,
                                pageOverride: pageOverride,
                                owner: owner,
                                axis: Axis.horizontal,
                                progress: horizontalProgress +
                                    details.delta.dx / horizontalTravel,
                                viewportSize: viewport,
                              ),
                      onTapUp: disabled || horizontalTravel <= 0
                          ? null
                          : (details) => _setMapScrollbarProgress(
                                provider: provider,
                                ctrl: ctrl,
                                pageOverride: pageOverride,
                                owner: owner,
                                axis: Axis.horizontal,
                                progress: (details.localPosition.dx -
                                        innerInset -
                                        horizontalThumbLength / 2) /
                                    horizontalTravel,
                                viewportSize: viewport,
                              ),
                      child: Container(
                        decoration: BoxDecoration(
                          color: trackColor,
                          borderRadius: BorderRadius.circular(9),
                          border: Border.all(color: Colors.white24),
                        ),
                        child: Stack(
                          children: [
                            Positioned(
                              left: horizontalThumbOffset,
                              top: 3,
                              width: horizontalThumbLength,
                              bottom: 3,
                              child: DecoratedBox(
                                decoration: BoxDecoration(
                                  color: disabled
                                      ? idleThumbColor.withValues(alpha: 0.32)
                                      : (active
                                          ? activeThumbColor
                                          : idleThumbColor),
                                  borderRadius: BorderRadius.circular(7),
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                );
              }

              Widget verticalBar() {
                final active = _activeMapScrollbarAxis == Axis.vertical;
                final disabled = _lockV || verticalRange <= 0;
                return MouseRegion(
                  cursor: disabled
                      ? SystemMouseCursors.basic
                      : SystemMouseCursors.resizeUpDown,
                  onEnter: (_) =>
                      _setActiveMapScrollbarAxis(Axis.vertical, owner: owner),
                  onExit: (_) {
                    if (_activeMapScrollbarAxis == Axis.vertical) {
                      _setActiveMapScrollbarAxis(null, owner: owner);
                    }
                  },
                  child: Semantics(
                    label: '縦スクロールバー',
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onVerticalDragStart: disabled
                          ? null
                          : (_) => _setActiveMapScrollbarAxis(Axis.vertical,
                              owner: owner),
                      onVerticalDragUpdate: disabled || verticalTravel <= 0
                          ? null
                          : (details) => _setMapScrollbarProgress(
                                provider: provider,
                                ctrl: ctrl,
                                pageOverride: pageOverride,
                                owner: owner,
                                axis: Axis.vertical,
                                progress: verticalProgress +
                                    details.delta.dy / verticalTravel,
                                viewportSize: viewport,
                              ),
                      onTapUp: disabled || verticalTravel <= 0
                          ? null
                          : (details) => _setMapScrollbarProgress(
                                provider: provider,
                                ctrl: ctrl,
                                pageOverride: pageOverride,
                                owner: owner,
                                axis: Axis.vertical,
                                progress: (details.localPosition.dy -
                                        innerInset -
                                        verticalThumbLength / 2) /
                                    verticalTravel,
                                viewportSize: viewport,
                              ),
                      child: Container(
                        decoration: BoxDecoration(
                          color: trackColor,
                          borderRadius: BorderRadius.circular(9),
                          border: Border.all(color: Colors.white24),
                        ),
                        child: Stack(
                          children: [
                            Positioned(
                              top: verticalThumbOffset,
                              left: 3,
                              height: verticalThumbLength,
                              right: 3,
                              child: DecoratedBox(
                                decoration: BoxDecoration(
                                  color: disabled
                                      ? idleThumbColor.withValues(alpha: 0.32)
                                      : (active
                                          ? activeThumbColor
                                          : idleThumbColor),
                                  borderRadius: BorderRadius.circular(7),
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                );
              }

              // ── 下端に置いた下部バーの上へ退避する (= ユーザー要望:
              //    下端にバーを配置した時、 ページ自体の左右移動バー
              //    (横スクロールバー) が下部バーの上に来るように) ──
              // 埋め込み中だけでなく「自由配置していない = 下端に固定」 の
              // 状態すべてが対象。 埋め込みでない時はバー下の余白 12px も足す。
              // ── このバーが画面の下端に接しているか ──
              // 分割中の上段ペインの下には下部バーが無いので、 バーを
              // 持ち上げると宙に浮いた変な位置に出てしまう
              // (= ユーザー報告)。 下端に接するペインだけ退避させる。
              final int? slotOfBar =
                  owner is int ? owner : (_mapSplitOpen ? _mapSplitEditorSlot : null);
              final bool barTouchesScreenBottom = !_mapSplitOpen ||
                  slotOfBar == null ||
                  (_mapSplitQuad
                      ? slotOfBar >= 2
                      : (!_mapSplitStacked || slotOfBar == 1));
              final bool bottomDockAtEdge = barTouchesScreenBottom &&
                  !provider.desktopBottomDockFloating &&
                      _visibleDesktopHeaderButtonsAt(provider, 'bottom')
                          .isNotEmpty;
              final double bottomDockInset = bottomDockAtEdge
                  ? (provider.desktopHeaderDockCollapsedAt('bottom')
                          ? 46.0
                          : 66.0) +
                      (provider.desktopBottomDockEmbedded ? 0.0 : 12.0)
                  : 0.0;
              // ── 左右端の縦バーの内側へ退避する (= ユーザー要望: 右端に
              //    サイドバーを埋め込んだ時、 全体図とサイドバーの間に
              //    スクロールバーが来るように) ──
              // 下部バーと同じく、 その辺に接しているペインだけ避ける。
              final bool paneTouchesScreenRight = !_mapSplitOpen ||
                  slotOfBar == null ||
                  (_mapSplitQuad
                      ? slotOfBar.isOdd
                      : (_mapSplitStacked || slotOfBar == 1));
              final bool paneTouchesScreenLeft = !_mapSplitOpen ||
                  slotOfBar == null ||
                  (_mapSplitQuad
                      ? slotOfBar.isEven
                      : (_mapSplitStacked || slotOfBar == 0));
              final double rightDockInset = paneTouchesScreenRight
                  ? _anchoredSideDockWidth(provider, 'right')
                  : 0.0;
              final double leftDockInset = paneTouchesScreenLeft
                  ? _anchoredSideDockWidth(provider, 'left')
                  : 0.0;
              return Stack(
                children: [
                  Positioned(
                    left: edgeInset + leftDockInset,
                    right: oppositeBarSpace + rightDockInset,
                    bottom: edgeInset + bottomDockInset,
                    height: hitThickness,
                    child: horizontalBar(),
                  ),
                  Positioned(
                    top: edgeInset,
                    right: edgeInset + rightDockInset,
                    bottom: oppositeBarSpace + bottomDockInset,
                    width: hitThickness,
                    child: verticalBar(),
                  ),
                ],
              );
            },
          );
        },
      ),
    );
  }

  // ── マップの画面分割 (= ユーザー要望: マインドマップ / ギャラリーページも
  //    PC は左右、 モバイルは上下で別々のマップを開けるように) ──────────────
  /// 分割表示 ON/OFF (ヘッダーの「マップを分割表示」 コマンドで切替)。
  bool _mapSplitOpen = false;

  /// 分割セルに表示するページ id (最大 4 セル)。 セル番号は
  /// 2 分割: 0=左(上) 1=右(下)、 4 分割: 0=左上 1=右上 2=左下 3=右下。
  /// 編集セル (_mapSplitEditorSlot) は常に currentPage を表示するので、
  /// ここの値は「非編集セルに何を出すか」 の記憶。
  final List<String?> _mapSplitCells = [null, null, null, null];

  /// 編集キャンバスが入っているセル番号。 ペインをタップするとその場で
  /// 編集側が移る (= ユーザー要望) ため可変。
  int _mapSplitEditorSlot = 0;

  /// 分割ペインの Web ビューを作り直させないための固定の鍵
  /// (= ユーザー報告: 何度も「初期化中」 に戻る)。
  final GlobalKey _splitWebKeyRight = GlobalKey();
  final GlobalKey _splitWebKeyLeft = GlobalKey();

  /// 分割ペインをアクティブ化した時刻 (epoch ms)。
  ///
  /// ペインの Listener(onPointerUp) はタップ認識より先に走るので、 同じ
  /// クリックから続けて届くノードの onTap では既に切替が終わっており、
  /// 「アクティブ化のためのクリックか」 を切替有無では判定できない。
  /// この時刻からの経過で見分ける。
  int _splitActivatedAtMs = 0;

  /// アクティブ化したのと同じクリックか (= 開閉や表示位置の自動調整を
  /// 抑えたい操作か)。
  bool get _justActivatedSplitPane =>
      DateTime.now().millisecondsSinceEpoch - _splitActivatedAtMs < 600;

  /// 4 分割モード (= ユーザー要望: 画面 4 分割とかできるように)。
  bool _mapSplitQuad = false;

  /// 最後に使った分割レイアウトの記憶 (= ユーザー要望: 最後が 4 分割なら
  /// 次回も 4 分割で開く)。 prefs 'mapSplitQuad'。
  bool _mapSplitQuadPref = false;

  /// 分割の境界位置 (= ユーザー要望: 境界線をドラッグで自由に動かせるように)。
  /// 左右方向 (左ペインの幅の割合) と上下方向 (上ペインの高さの割合)。
  /// 4 分割では列 / 行の境界として同じ値を使う。
  double _mapSplitRatioX = 0.5;
  double _mapSplitRatioY = 0.5;

  /// 2 分割の向き (= ユーザー要望: 上下分割にするか左右分割にするか設定
  /// できるように)。 true = 上下 (縦に積む) / false = 左右。 デスクトップの
  /// 既定は左右、 モバイルの既定は上下。 prefs 'mapSplitStacked'。
  bool _mapSplitStacked = false;

  /// ペインごとのコピー済みヘッダーボタン (= ユーザー要望: 全体ヘッダーの
  /// ボタンをドラッグして分割画面のヘッダーへ持ってこれるように)。
  /// キー = セル番号。 prefs `paneHeaderButtons_v1` に保存。
  final Map<int, List<String>> _paneHeaderButtons = {};

  Future<void> _persistPaneHeaderButtons() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('paneHeaderButtons_v1',
          jsonEncode(_paneHeaderButtons.map((k, v) => MapEntry('$k', v))));
    } catch (_) {}
  }

  Future<void> _loadMapSplitPrefs() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      _mapSplitQuadPref = prefs.getBool('mapSplitQuad') ?? false;
      _mapSplitRatioX =
          (prefs.getDouble('mapSplitRatioX') ?? 0.5).clamp(0.15, 0.85);
      _mapSplitRatioY =
          (prefs.getDouble('mapSplitRatioY') ?? 0.5).clamp(0.15, 0.85);
      _mapSplitStacked = prefs.getBool('mapSplitStacked') ?? !_isDesktop;
      // Instagram を開く画面の設定 (= ユーザー要望)。
      _instagramLanding = prefs.getString('instagramLanding') ?? 'home';
      _instagramUsername = prefs.getString('instagramUsername') ?? '';
      final ph = prefs.getString('paneHeaderButtons_v1');
      if (ph != null) {
        final m = jsonDecode(ph) as Map<String, dynamic>;
        _paneHeaderButtons.clear();
        m.forEach((k, v) {
          final slot = int.tryParse(k);
          if (slot != null && v is List) {
            _paneHeaderButtons[slot] = List<String>.from(v);
          }
        });
      }
    } catch (_) {}
  }

  /// ペインのミニヘッダーボタン 1 個。 押すとそのペインをアクティブ化して
  /// からコマンドを実行する (= ユーザー要望: 押したボタン機能は分割画面内
  /// で起動)。 長押しで削除。
  Widget _paneHeaderBtn(MindMapProvider provider, int slot, String id) {
    final cmd = _headerCustomizableCommands.firstWhere(
        (c) => c['id'] == id,
        orElse: () => <String, dynamic>{});
    final icon = (cmd['icon'] as IconData?) ?? Icons.bolt_rounded;
    final color = (cmd['color'] as Color?) ?? const Color(0xFF4FC3F7);
    final labelKey = cmd['labelKey'] as String? ?? '';
    // ── ドラッグで移動 / 削除 (= ユーザー要望: ペインボタンのところから
    //    そのままドラッグで戻したり消したりできるように) ──
    //    ・別のペインへドロップ → そのペインへ移動
    //    ・ペインの外 (ヘッダー / キャンバス) へドロップ → 削除 (= 戻す)
    final btn = Tooltip(
      triggerMode: TooltipTriggerMode.manual,
      message: labelKey.isNotEmpty ? provider.t(labelKey) : id,
      child: IconButton(
        padding: EdgeInsets.zero,
        constraints: const BoxConstraints(minWidth: 26, minHeight: 26),
        icon: Icon(icon, size: 15, color: color),
        onPressed: () => _runPaneHeaderCommand(provider, slot, id),
      ),
    );
    return Draggable<String>(
      data: 'panebtn:$slot:$id',
      dragAnchorStrategy: pointerDragAnchorStrategy,
      feedback: Material(
        color: Colors.transparent,
        child: Opacity(
          opacity: 0.9,
          child: Container(
            padding: const EdgeInsets.all(5),
            decoration: BoxDecoration(
              color: Colors.black.withValues(alpha: 0.6),
              shape: BoxShape.circle,
            ),
            child: Icon(icon, size: 17, color: color),
          ),
        ),
      ),
      childWhenDragging: Opacity(opacity: 0.3, child: btn),
      onDragEnd: (details) {
        // どのペインにも入っていなければ削除する。
        if (details.wasAccepted) return;
        final inPane = _visibleSplitSlots()
            .any((k) => _splitCellGlobalRect(k).contains(details.offset));
        if (inPane) return;
        setState(() => _paneHeaderButtons[slot]?.remove(id));
        _persistPaneHeaderButtons();
        _showLockToast(provider.t('map.paneBtnRemoved'));
      },
      child: btn,
    );
  }

  /// ヘッダーボタンのうち「サイトを開くだけ」 のコマンドの URL。
  /// ペインに置いたボタンから押された時は、 全画面ではなくそのペインの中に
  /// 埋め込んで開く (= ユーザー要望: Google マップや Earth 等が全画面で
  /// 開いてしまうので分割画面内で開くように)。
  String? _paneEmbeddableUrlFor(MindMapProvider provider, String id) {
    switch (id) {
      case 'openGoogleMaps':
        return 'https://www.google.com/maps';
      case 'openGoogleEarth':
        return 'https://earth.google.com/web/';
      case 'openGoogleCalendar':
        return 'https://calendar.google.com/';
      case 'openGoogleDrive':
        return 'https://drive.google.com/';
      case 'openDeepL':
        return 'https://www.deepl.com/translator';
      case 'openQiita':
        return 'https://qiita.com/';
      case 'openReddit':
        return 'https://www.reddit.com/';
      case 'openX':
        return 'https://x.com/';
      case 'openInstagram':
        // 開く画面の設定 (ホーム / DM / プロフィール) に従う。
        return _instagramUrl();
      case 'openYoutubeMusic':
        return 'https://music.youtube.com/';
      case 'openSlack':
        return 'https://app.slack.com/';
      case 'openDiscord':
        return 'https://discord.com/channels/@me';
      // Meet / Zoom はペインに埋め込んでも通話できないので候補に出さない。
      case 'openPaiza':
        return 'https://paiza.jp/';
      case 'openProgate':
        return 'https://prog-8.com/';
      case 'openAtCoder':
        return 'https://atcoder.jp/';
      case 'openAmazon':
        return _amazonBaseUrl(provider);
      case 'openKindle':
        return 'https://read.amazon.co.jp/';
      case 'openYoutube':
        return provider.localizeYoutubeUrl('https://www.youtube.com/');
      case 'googleSearch':
        return 'https://www.google.com/';
      case 'openAi':
      case 'openChatGPT':
        return 'https://chatgpt.com/';
      case 'openGemini':
        return 'https://gemini.google.com/app';
      case 'openClaude':
        return 'https://claude.ai/new';
      default:
        return null;
    }
  }

  void _runPaneHeaderCommand(MindMapProvider provider, int slot, String id) {
    // サイト系ボタンはそのペインの中に埋め込んで開く (= ユーザー要望)。
    final siteUrl = _paneEmbeddableUrlFor(provider, id);
    if (siteUrl != null && _isDesktop) {
      // 既に同じサイトが開いているボタンをもう一度押した時の動き。
      if (_mapSplitCellWeb[slot] == siteUrl) {
        // ── YouTube / Instagram は行き先を選べるようにする (= ユーザー要望:
        //    お気に入りのチャンネルや動画へ飛べるように / DM かホームか
        //    更新かを選べるように)。 それ以外のサイトは従来どおり更新。 ──
        if (id == 'openYoutube' || id == 'openInstagram') {
          // ignore: discarded_futures
          _showPaneSiteMenu(provider, slot, id, siteUrl);
        } else {
          _reloadSplitCellWeb(slot);
        }
      } else {
        _embedUrlIntoSlot(slot, siteUrl);
      }
      return;
    }
    // ── 計算機などのツールは、 浮かせずにそのペイン内で全画面で開く
    //    (= ユーザー要望)。 既に開いているボタンをもう一度押したら閉じる。 ──
    if (_isPaneEmbeddableTool(id)) {
      if (_mapSplitCellTool[slot] == id) {
        setState(() {
          _mapSplitCellTool.remove(slot);
          _syncNarrowPaneRatio();
        });
      } else {
        _embedToolIntoSlot(slot, id);
      }
      return;
    }
    final pageId = _mapSplitCells[slot];
    if (pageId == null) return;
    // ペインをアクティブ化してから次フレームでコマンドを実行する。
    _mapSplitActivate(provider, pageId, slot: slot);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _executeHeaderCommand(id, context.read<MindMapProvider>());
    });
  }

  /// ペインに埋め込み済みのサイトボタンをもう一度押した時に出す行き先メニュー
  /// (= ユーザー要望: YouTube はお気に入りのチャンネルや動画へ飛べるように、
  /// Instagram は DM / ホーム / 更新 を選べるように)。
  ///
  /// お気に入りは、 YouTube のブラウズ画面でタブを「お気に入り (保持)」 に
  /// したものをそのまま使う (prefs `mokumoku_win_pinned_tabs_v1`)。
  Future<void> _showPaneSiteMenu(
      MindMapProvider provider, int slot, String id, String homeUrl) async {
    final isYoutube = id == 'openYoutube';
    // お気に入りタブ (URL + 表示名) を読む。 YouTube ボタンの時だけ使う。
    final favorites = <({String url, String title})>[];
    if (isYoutube) {
      try {
        final prefs = await SharedPreferences.getInstance();
        final raw = prefs.getString('mokumoku_win_pinned_tabs_v1');
        if (raw != null && raw.isNotEmpty) {
          final list = jsonDecode(raw);
          if (list is List) {
            for (final e in list) {
              if (e is! Map) continue;
              final u = '${e['url'] ?? ''}'.trim();
              if (u.isEmpty) continue;
              final t = '${e['title'] ?? ''}'.trim();
              favorites.add((url: u, title: t.isEmpty ? u : t));
            }
          }
        }
      } catch (_) {/* 読めなくてもメニューは出す */}
    }
    if (!mounted) return;
    // ペインの左上あたりに出す (押したボタンのすぐ近く)。
    final cell = _splitCellGlobalRect(slot);
    final pos = Offset(cell.left + 12, cell.top + 44);
    final selected = await showMenu<String>(
      context: context,
      color: const Color(0xFF22222E),
      position: RelativeRect.fromLTRB(pos.dx, pos.dy, pos.dx, pos.dy),
      items: [
        // 今見ている画面をそのまま読み直す (= ユーザー要望: 更新でホームに
        //   戻らないように)。
        PopupMenuItem<String>(
          value: 'reload',
          child: Row(children: [
            const Icon(Icons.refresh_rounded,
                color: Color(0xFF4FC3F7), size: 18),
            const SizedBox(width: 8),
            Text(provider.t('pane.reloadCurrent'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        PopupMenuItem<String>(
          value: 'home',
          child: Row(children: [
            const Icon(Icons.home_rounded,
                color: Color(0xFF9CCC65), size: 18),
            const SizedBox(width: 8),
            Text(provider.t('pane.openHome'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        // ── 今見ているページをお気に入りに入れる (= ユーザー要望: 分割の
        //    中にはタブが無いので、 ここから登録できるように) ──
        PopupMenuItem<String>(
          value: 'addFav',
          child: Row(children: [
            const Icon(Icons.star_rounded,
                color: Color(0xFFFFB347), size: 18),
            const SizedBox(width: 8),
            Text(provider.t('pane.addFavorite'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        if (!isYoutube)
          PopupMenuItem<String>(
            value: 'dm',
            child: Row(children: [
              const Icon(Icons.mail_rounded,
                  color: Color(0xFFE1306C), size: 18),
              const SizedBox(width: 8),
              Text(provider.t('insta.dm'),
                  style: const TextStyle(color: Colors.white, fontSize: 13)),
            ]),
          ),
        if (isYoutube) ...[
          const PopupMenuDivider(),
          if (favorites.isEmpty)
            PopupMenuItem<String>(
              enabled: false,
              child: Text(provider.t('pane.noFavorites'),
                  style: const TextStyle(color: Colors.white38, fontSize: 11)),
            ),
          for (var i = 0; i < favorites.length && i < 15; i++)
            PopupMenuItem<String>(
              value: 'fav:$i',
              child: Row(children: [
                const Icon(Icons.star_rounded,
                    color: Color(0xFFFFB347), size: 16),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(favorites[i].title,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style:
                          const TextStyle(color: Colors.white, fontSize: 12.5)),
                ),
              ]),
            ),
        ],
      ],
    );
    if (selected == null || !mounted) return;
    if (selected == 'reload') {
      _reloadSplitCellWeb(slot);
      return;
    }
    if (selected == 'addFav') {
      await _addPaneUrlToFavorites(provider, slot);
      return;
    }
    // 行き先を変えて開き直す。 「今見ている画面」 の記憶を消し、 更新回数も
    //   進める (同じ URL を選び直した時もちゃんと開き直すため)。
    void openInPane(String url) {
      _mapSplitCellWebCur.remove(slot);
      setState(() {
        _mapSplitCellWebTick[slot] = (_mapSplitCellWebTick[slot] ?? 0) + 1;
      });
      _embedUrlIntoSlot(slot, url);
    }

    if (selected == 'home') {
      openInPane(homeUrl);
      return;
    }
    if (selected == 'dm') {
      openInPane('https://www.instagram.com/direct/inbox/');
      return;
    }
    if (selected.startsWith('fav:')) {
      final i = int.tryParse(selected.substring(4)) ?? -1;
      if (i < 0 || i >= favorites.length) return;
      openInPane(favorites[i].url);
    }
  }

  /// 分割セルで今見ているページをお気に入りに登録する (= ユーザー要望:
  /// 分割の中にはタブが出ないので、 ボタンから登録できるように)。
  ///
  /// 置き場所は YouTube ブラウズ画面の「お気に入り (保持) タブ」 と同じ
  /// (prefs `mokumoku_win_pinned_tabs_v1`) なので、 どちらから登録しても
  /// 両方に出てくる。
  Future<void> _addPaneUrlToFavorites(
      MindMapProvider provider, int slot) async {
    final url = (_mapSplitCellWebCur[slot] ?? _mapSplitCellWeb[slot] ?? '')
        .trim();
    if (url.isEmpty) return;
    // 名前は YouTube の動画なら本当の題名を取りに行く。 取れなければ
    //   アドレスの分かりやすい部分を使う。
    String title = '';
    try {
      final vid = NodeWidget.extractVideoId(url);
      if (vid != null) {
        final resp = await http
            .get(Uri.parse('https://www.youtube.com/oembed'
                '?url=https://www.youtube.com/watch?v=$vid&format=json'))
            .timeout(const Duration(seconds: 6));
        if (resp.statusCode == 200) {
          final data = jsonDecode(resp.body);
          if (data is Map) title = '${data['title'] ?? ''}'.trim();
        }
      }
    } catch (_) {/* 題名が取れなくても登録はする */}
    if (title.isEmpty) {
      final u = Uri.tryParse(url);
      title = u == null
          ? url
          : (u.path.length > 1 ? '${u.host}${u.path}' : u.host);
    }
    var added = false;
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString('mokumoku_win_pinned_tabs_v1');
      final list = <Map<String, dynamic>>[];
      if (raw != null && raw.isNotEmpty) {
        final decoded = jsonDecode(raw);
        if (decoded is List) {
          for (final e in decoded) {
            if (e is Map) list.add(Map<String, dynamic>.from(e));
          }
        }
      }
      // 同じアドレスが既にあれば二重に足さない。
      final dup = list.any((e) => '${e['url'] ?? ''}'.trim() == url);
      if (!dup) {
        list.add({'url': url, 'title': title});
        // 増え続けないよう上限を設ける (古い方から捨てる)。
        while (list.length > 30) {
          list.removeAt(0);
        }
        await prefs.setString(
            'mokumoku_win_pinned_tabs_v1', jsonEncode(list));
        added = true;
      }
    } catch (e) {
      debugPrint('お気に入りの保存に失敗: $e');
    }
    if (!mounted) return;
    _showLockToast(added
        ? '${provider.t('pane.favoriteAdded')}: $title'
        : provider.t('pane.favoriteExists'));
  }

  /// 分割の境界位置を保存する。
  Future<void> _persistMapSplitRatios() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setDouble('mapSplitRatioX', _mapSplitRatioX);
      await prefs.setDouble('mapSplitRatioY', _mapSplitRatioY);
    } catch (_) {}
  }

  /// 分割レイアウトが占める領域 (AppBar より下) のサイズ。
  Size _mapSplitBodySize() {
    final s = View.of(context).physicalSize / View.of(context).devicePixelRatio;
    return Size(s.width, math.max(1.0, s.height - kToolbarHeight));
  }

  /// ドラッグで動かせる分割の境界線 (= ユーザー要望)。 ダブルクリックで
  /// 半分に戻す。
  Widget _mapSplitDivider({required bool vertical}) {
    return MouseRegion(
      cursor: vertical
          ? SystemMouseCursors.resizeLeftRight
          : SystemMouseCursors.resizeUpDown,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onPanUpdate: (d) {
          final body = _mapSplitBodySize();
          setState(() {
            if (vertical) {
              _mapSplitRatioX = (_mapSplitRatioX + d.delta.dx / body.width)
                  .clamp(0.15, 0.85);
            } else {
              _mapSplitRatioY = (_mapSplitRatioY + d.delta.dy / body.height)
                  .clamp(0.15, 0.85);
            }
          });
        },
        onPanEnd: (_) => _persistMapSplitRatios(),
        onDoubleTap: () {
          setState(() {
            if (vertical) {
              _mapSplitRatioX = 0.5;
            } else {
              _mapSplitRatioY = 0.5;
            }
          });
          _persistMapSplitRatios();
        },
        child: Container(
          // 掴みやすいよう当たり判定は 8px 取り、 見た目は 1px の線にする。
          width: vertical ? 8 : null,
          height: vertical ? null : 8,
          color: Colors.transparent,
          alignment: Alignment.center,
          child: Container(
            width: vertical ? 1 : null,
            height: vertical ? null : 1,
            color: Colors.white24,
          ),
        ),
      ),
    );
  }

  Future<void> _persistMapSplitQuad() async {
    _mapSplitQuadPref = _mapSplitQuad;
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool('mapSplitQuad', _mapSplitQuad);
    } catch (_) {}
  }

  /// ヘッダー常設ボタンからの分割トグル (= ユーザー要望: デフォルトで
  /// 右上に搭載)。 開く時は前回のレイアウト (2/4 分割) を復元する。
  void _toggleMapSplitFromHeader() {
    setState(() {
      _mapSplitOpen = !_mapSplitOpen;
      _mapSplitEditorSlot = 0;
      // モバイルは 4 分割にしない (= ユーザー要望: 画面が小さいので不要)。
      _mapSplitQuad = _mapSplitOpen && _mapSplitQuadPref && _isDesktop;
    });
  }

  /// [globalPos] が入っている分割セルの番号。 どのセルでもなければ null。
  /// (= ユーザー要望: 右クリックしたウィンドウのページを残して解除したい)
  int? _splitSlotAtGlobal(Offset globalPos) {
    if (!_mapSplitOpen) return null;
    for (final k in _visibleSplitSlots()) {
      if (_splitCellGlobalRect(k).contains(globalPos)) return k;
    }
    return null;
  }

  /// 分割を解除する時に、 そのセルに出ていたページへ切り替えてから閉じる。
  /// (= ユーザー要望: 解除すると左上のページに移ってしまうが、 右クリック
  ///  したウィンドウのページに移ってほしい)
  void _closeMapSplitKeeping(int? slot) {
    if (!_mapSplitOpen) return;
    if (slot != null && slot != _mapSplitEditorSlot) {
      // 編集セル以外を指していたら、 そのセルに出ているページへ移る。
      final pid = _mapSplitCells[slot];
      if (pid != null && pid.isNotEmpty) {
        final provider = context.read<MindMapProvider>();
        final idx = provider.pages.indexWhere((p) => p.id == pid);
        if (idx >= 0) provider.switchPage(idx);
      }
    }
    _closeMapSplit();
  }

  /// 画面分割を解除して 1 画面に戻す。 埋め込んでいた Web / ツールも一緒に
  /// 片付けて、 編集していたページだけの表示に戻す。 分割していなければ
  /// 何もしない。 ヘッダーの closeSplit コマンドと、 ページ名バッジの
  /// メニュー (= ユーザー要望: 分割画面を閉じる項目) から共用。
  void _closeMapSplit() {
    // 分割が畳まれたら「道具のために開いた」 印も消す。
    _toolOpenedSplit.clear();
    if (!_mapSplitOpen) return;
    setState(() {
      _mapSplitOpen = false;
      _mapSplitQuad = false;
      _mapSplitEditorSlot = 0;
      _mapSplitCellWeb.clear();
      _mapSplitCellWebCur.clear();
      _mapSplitCellTool.clear();
      _syncNarrowPaneRatio();
      _mapSplitCellFile.clear();
    });
  }

  /// 分割セルに埋め込んだ Web (Google 検索 / YouTube 等) の URL。
  /// (= ユーザー要望: 要素から立ち上げた検索や動画を分割画面に埋め込み、
  ///    動画を再生しながら別のページを編集できるように)。 キー = セル番号。
  final Map<int, String> _mapSplitCellWeb = {};

  /// 埋め込んだ Web セルの再読み込み回数。 セルの Widget キーに混ぜてあり、
  /// 増やすと webview が作り直される = 更新される (= ユーザー要望: ペインに
  /// 置いたボタンをもう一度押したら画面を更新し直せるように)。
  final Map<int, int> _mapSplitCellWebTick = {};

  /// 埋め込んだ Web セルが**今表示している** URL (= ユーザー要望: 更新すると
  /// ホーム画面に戻ってしまうので、 今見ている画面を読み直すように)。
  /// セルの中で動画やページを辿ると、 その都度ここが更新される。
  /// Widget のキーには混ぜない (混ぜるとページを開く度に作り直されてしまう)。
  final Map<int, String> _mapSplitCellWebCur = {};

  /// 分割セルに埋め込んだファイルビューア (PDF / Office / テキスト等)。
  /// キー = セル番号、 値 = ビューアを組み立てる builder。
  /// (= ユーザー要望: 分割画面でファイルを開いた時、 浮遊窓ではなく
  ///    その画面に埋め込まれた状態で開くように。 浮遊窓のヘッダーと
  ///    ビューアのヘッダーが二重に重なる問題もこれで解消する)。
  final Map<int, WidgetBuilder> _mapSplitCellFile = {};

  /// ファイルビューアを分割セルへ埋め込む。 開くセルは既定で編集セル
  /// (= 今まで浮遊窓が覆っていた場所と同じ)。
  void _embedViewerIntoMapSplitCell(WidgetBuilder builder, {int? slot}) {
    final k = (slot ?? _mapSplitEditorSlot).clamp(0, 3);
    setState(() {
      _mapSplitCellFile[k] = builder;
      // 同じセルに Web / ツールが残っていると、 編集セルが移った時に
      // 古いブラウザ表示が蘇ってしまう (= ユーザー報告の再発経路)。
      _mapSplitCellWeb.remove(k);
      _mapSplitCellWebCur.remove(k);
      _mapSplitCellTool.remove(k);
      _syncNarrowPaneRatio();
    });
  }

  /// 埋め込んだファイルビューアを閉じる (ビューアの × / 戻るで呼ばれる)。
  void _closeMapSplitCellFile(int slot, WidgetBuilder opened) {
    // 別のファイルに差し替わった後で古い窓の後始末が届くことがあるので、
    // 開いていた本人と同じ時だけ片付ける。
    if (!mounted || !identical(_mapSplitCellFile[slot], opened)) return;
    setState(() => _mapSplitCellFile.remove(slot));
  }

  /// 分割セルに埋め込んだツール (計算機など) のコマンド id。 キー = セル番号。
  /// (= ユーザー要望: ペインに置いたボタンから開いたら、 フローティングでは
  ///    なくそのペイン内の全画面で開く)。
  final Map<int, String> _mapSplitCellTool = {};

  /// ペイン内に全画面で開けるツールか。
  /// その道具を出すために画面分割を作ったか (道具の id → true)。
  ///
  /// = ユーザー要望「元々が全画面であったのなら全画面に戻して欲しい」。
  /// 分割していない所から道具を開くと 2 分割にするので、 その道具を閉じた
  /// 時は分割ごと畳んで元の全画面に戻す。 もともと分割していた時は、
  /// 道具だけ外して分割はそのまま残す。
  final Map<String, bool> _toolOpenedSplit = {};

  /// 道具 (メモ / ショートカット一覧など) を左右分割のペインに入れる。
  /// まだ分割していなければ 2 分割にしてから入れる。
  Future<void> _openToolInSplitPane(String id, bool left) async {
    final wasSplit = _mapSplitOpen;
    if (!_mapSplitOpen) {
      await _applyMapSplitMode(panes: 2, stacked: false);
      if (!mounted) return;
    }
    if (!_mapSplitOpen) return;
    final slot = left ? 0 : _primaryViewerSlot();
    if (_mapSplitCellTool[slot] == id) {
      // もう一度押した = 閉じる。
      final openedByUs = _toolOpenedSplit.remove(id) ?? false;
      setState(() {
        _mapSplitCellTool.remove(slot);
        _syncNarrowPaneRatio();
      });
      // この道具のために分割したのなら、 全画面に戻す (= ユーザー要望)。
      if (openedByUs) _closeMapSplit();
    } else {
      if (!wasSplit) _toolOpenedSplit[id] = true;
      _embedToolIntoSlot(slot, id);
    }
  }

  bool _isPaneEmbeddableTool(String id) =>
      id == 'calculator' ||
      // ショートカット一覧 (= ユーザー要望: 画面分割でも開けるように)。
      id == 'shortcuts' ||
      // このページのメモ (= ユーザー要望: メモも左右分割で開けるように)。
      id == 'mapMemo' ||
      // AI アシスタント (= ユーザー要望: 画面自体を左右分割で出せるように)。
      id == 'aiAssistant';

  /// 半分では広すぎる「細い」 ツール (= ユーザー要望: ショートカット一覧は
  /// 半分だと大きすぎる)。 開いた時だけ境界を寄せて、 閉じたら元の幅に戻す。
  static bool _isNarrowPaneTool(String? id) => id == 'shortcuts';

  /// 細いツールを開く前の境界位置 (閉じた時に戻すため)。
  double? _splitRatioBeforeNarrowTool;

  /// 細いツールを入れたペインの幅の割合。
  static const double _kNarrowPaneRatio = 0.22;

  /// 細いツールの有無に合わせて境界を寄せる / 戻す。
  ///
  /// 共有の `_mapSplitRatioX` を書き換える形にしてあるので、 開いている間に
  /// 境界をドラッグすればそのまま動かせる (派生値で上書きすると、 ドラッグ
  /// しても何も起きない画面になってしまう)。
  void _syncNarrowPaneRatio() {
    if (_mapSplitQuad || _mapSplitStacked) return;
    int? narrowSlot;
    for (final k in const [0, 1]) {
      if (_isNarrowPaneTool(_mapSplitCellTool[k])) {
        narrowSlot = k;
        break;
      }
    }
    if (narrowSlot != null) {
      _splitRatioBeforeNarrowTool ??= _mapSplitRatioX;
      _mapSplitRatioX =
          narrowSlot == 0 ? _kNarrowPaneRatio : 1 - _kNarrowPaneRatio;
    } else if (_splitRatioBeforeNarrowTool != null) {
      _mapSplitRatioX = _splitRatioBeforeNarrowTool!;
      _splitRatioBeforeNarrowTool = null;
    }
  }

  /// ツールをペインに埋め込む。 Web セルと同じ扱いで、 編集セルが指定された
  /// 場合は編集ペインを空いているセルへ退避する。
  void _embedToolIntoSlot(int slot, String id) {
    setState(() {
      if (slot == _mapSplitEditorSlot) {
        int other = _primaryViewerSlot();
        for (final s in _visibleSplitSlots()) {
          if (s != slot &&
              _mapSplitCellWeb[s] == null &&
              _mapSplitCellTool[s] == null) {
            other = s;
            break;
          }
        }
        _mapSplitEditorSlot = other;
        _mapSplitCellWeb.remove(other);
        _mapSplitCellTool.remove(other);
      }
      _mapSplitCellWeb.remove(slot);
      _mapSplitCellTool[slot] = id;
      _syncNarrowPaneRatio();
    });
  }

  /// 埋め込んだツールの Widget。 閉じるとセルは元 (ページ表示) に戻る。
  Widget _buildEmbeddedPaneTool(
      MindMapProvider provider, int slot, String id) {
    void close() {
      setState(() {
        _mapSplitCellTool.remove(slot);
        _syncNarrowPaneRatio();
      });
    }

    switch (id) {
      case 'calculator':
        return _FloatingCalculator(
          key: ValueKey('pane_tool_${slot}_$id'),
          provider: provider,
          initialOffset: Offset.zero,
          onClose: close,
          embedded: true,
        );
      // ショートカット一覧 (= ユーザー要望: 画面分割でも開けるように)。
      case 'shortcuts':
        return _buildShortcutsPanel(provider, onClose: close);
      // このページのメモ (= ユーザー要望: メモも左右分割で開けるように)。
      //   メモの画面はダイアログとして組んであるので、 ペインの中に専用の
      //   入れ物 (Navigator) を立てて、 その中に出す。
      case 'mapMemo':
        return _PaneDialogHost(
          key: ValueKey('pane_tool_${slot}_$id'),
          onClose: close,
          open: (hostCtx) =>
              _showMapMemoDialog(hostCtx, provider, inPane: true),
        );
      // AI アシスタント (= ユーザー要望: 画面自体を左右分割で出せるように)。
      // 会話とループは画面の外 (_McpChatSession) が持っているので、
      // ペインに出し入れしても処理は途切れない。
      case 'aiAssistant':
        _registerMcpHandlers(provider);
        return _McpChatDialog(
          provider: provider,
          paneMode: true,
          onClosePane: close,
          onOpenAiSettings: () =>
              _showGeminiKeyDialog(context, provider, null, anyProvider: true),
          extractFileText: _extractAttachmentTextForAi,
          onOpenBrowserAi: (url) {
            if (_openStyleOf('openAi') == 'floating' && _isDesktop) {
              openExternalWebWindow(url, embeddable: true);
              return;
            }
            _openUrlInSplitPanel(url);
          },
        );
      default:
        return const SizedBox.shrink();
    }
  }

  /// 埋め込んだ Web セルを再読み込みする。
  void _reloadSplitCellWeb(int slot) {
    if (_mapSplitCellWeb[slot] == null) return;
    setState(() {
      _mapSplitCellWebTick[slot] = (_mapSplitCellWebTick[slot] ?? 0) + 1;
    });
    final p = context.read<MindMapProvider>();
    _showLockToast('${_paneLabel(p, slot)}: ${p.t('map.paneReloaded')}');
  }

  /// ビューア (YouTube / Web / PDF) の「分割で開く」を、 マップ分割が
  /// 開いている時は分割セルへの埋め込みに切り替えるか。
  /// 分割セルの中に開けるか。
  ///
  /// 以前はデスクトップ限定だったが、 モバイルでも分割自体は
  /// カスタムボタン (mapSplitLR / mapSplitTB) から使えるので、
  /// 分割中は中に開けるようにした
  /// (= ユーザー要望: モバイルでも分割画面内で開けるように)。
  bool _canEmbedIntoMapSplit() {
    if (!_mapSplitOpen) return false;
    final provider = context.read<MindMapProvider>();
    return _splitEligiblePage(provider.currentPage);
  }

  /// 編集キャンバスが実際に見えている領域の大きさ。
  ///
  /// `_mapViewportKey` は分割ペインをまとめて包む Stack に付いているので、
  /// 分割中にそのまま使うと「見えていない他ペインの分」 まで足された広い
  /// ビューポートになり、 端までスクロールできなくなる
  /// (= ユーザー報告: 表示されていない領域分が考慮されてスクロールバーの
  ///  端までスクロールできていない)。 分割中は編集セルの矩形を使う。
  Size _editorViewportSize() {
    if (_mapSplitOpen) {
      return _splitCellGlobalRect(_mapSplitEditorSlot).size;
    }
    final box =
        _mapViewportKey.currentContext?.findRenderObject() as RenderBox?;
    // ★ 最初のフレームではまだ配置が済んでおらず、 size を読むと
    //   「RenderBox was not laid out」 で落ちる (= 起動のたびに例外が出て
    //   全体図の初回描画が失敗していた)。 済んでいない間は画面全体の
    //   大きさで代用する。
    if (box == null || !box.hasSize) return MediaQuery.sizeOf(context);
    return box.size;
  }

  /// メモ / AI をアプリの外の小窓として開く (= ユーザー要望: PC でもアプリ
  /// の外にフローティング表示したい)。 デスクトップ専用。
  ///
  /// desktop_multi_window で別ウィンドウを立ち上げる。 メモは本体と同じ
  /// SharedPreferences を読み書きするので、 どちらで書いても内容は同じ。
  /// フローティングメモ / AI (サブウィンドウ) からの呼び出しを受ける
  /// (= ユーザー要望: メモの内容を AI に渡したりマップに埋め込んだり)。
  /// 別プロセスで開いたメモ窓 (ショートカット起動) からの頼みごとを
  /// サブウィンドウと同じ口へ流す (= ユーザー報告: マップに追加しようと
  /// すると「追加できるページがありません」 と出る)。 単体で開いた窓は
  /// desktop_multi_window では本体に届かないので 127.0.0.1 越しに来る。
  Future<String> _handleFloatingMemoBridge(String method, dynamic args) async {
    try {
      final r = await _onSubWindowCall(MethodCall(method, args), -1);
      return r == null ? '' : '$r';
    } catch (_) {
      return '';
    }
  }

  Future<dynamic> _onSubWindowCall(MethodCall call, int fromWindowId) async {
    switch (call.method) {
      // ── 別窓の録画パネルから (= ユーザー要望: 録画ボタンをアプリの外へ) ──
      case 'screenRecState':
        return _screenRecStateMap();
      case 'screenRecClosed':
        // 窓が本当に閉じられた (× ボタン) → 押し出しをやめる。
        _recWinId = null;
        _recWinAutoOpened = false;
        _recWinHidden = false;
        break;
      case 'screenRecCmd':
        {
          final m = (call.arguments is Map)
              ? (call.arguments as Map).cast<String, dynamic>()
              : const <String, dynamic>{};
          // ★ ここで await してはいけない。 範囲選びのモーダルを開いたまま
          //   待つと応答が返らず、 窓と本体の両方が固まる (= ユーザー報告)。
          //   受け付けたことだけ即返し、 実際の処理は後ろで走らせる。
          unawaited(_handleScreenRecCmd('${m['cmd'] ?? ''}',
              '${m['value'] ?? ''}'));
          return _screenRecStateMap();
        }
      // ── アプリの外へ出した AI アシスタントの窓から (= ユーザー要望) ──
      case 'assistState':
        return _assistantStateMap(context.read<MindMapProvider>());
      case 'assistCmd':
        {
          final m = (call.arguments is Map)
              ? (call.arguments as Map).cast<String, dynamic>()
              : const <String, dynamic>{};
          // ★ ここで待たない。 AI の応答は分単位で掛かることがあり、
          //   待つと窓と本体の両方が固まる (録画窓で同じ失敗をしている)。
          unawaited(
              _handleAssistantCmd('${m['cmd'] ?? ''}', '${m['value'] ?? ''}'));
          return _assistantStateMap(context.read<MindMapProvider>());
        }
      case 'assistClosed':
        // 窓が閉じられた → 押し出しをやめる。
        _assistListener?.call();
        _assistListener = null;
        _assistWinId = null;
        break;
      case 'floatingMemoToNode':
        final text = '${call.arguments ?? ''}'.trim();
        if (text.isEmpty) break;
        final provider = context.read<MindMapProvider>();
        provider.addMemoNodeToCurrentPage(text);
        break;
      case 'floatingMemoToAi':
        final text = '${call.arguments ?? ''}'.trim();
        if (text.isEmpty) break;
        // ignore: discarded_futures
        _openPopOutWindow(context.read<MindMapProvider>(),
            kind: 'ai', query: text);
        break;
      case 'focusMain':
        // サブウィンドウを閉じた後、 フォーカスを本体へ戻す (= ユーザー
        // 報告: 閉じると本体の動作がおかしくなる、 の対策)。
        try {
          await windowManager.show();
          await windowManager.focus();
        } catch (_) {}
        break;
      case 'floatingMemoAskAi':
        // フローティングメモの中の AI 画面から (= ユーザー要望: 別窓を出さず
        //   メモの所が AI に切り替わる)。 メモ窓は鍵もトークンも持たないので、
        //   本体が代行サーバーへ投げて、 答えの文だけを返す。
        {
          final q = '${call.arguments ?? ''}'.trim();
          if (q.isEmpty) return '';
          try {
            return await context.read<MindMapProvider>().askAi(q);
          } catch (e) {
            // 先頭の ⚠ を目印にして、 メモ窓側で赤字にする。
            return '⚠$e';
          }
        }
      case 'floatingMemoAiModels':
        // メモ窓の「AI モデルを変更」 メニュー用 (= ユーザー要望: AI ボタンの
        //   長押し / 右クリックでモデルを変更)。 一覧と現在値を返す。
        {
          final provider = context.read<MindMapProvider>();
          if (provider.relayModels.isEmpty) {
            try {
              await provider.refreshRelayModels();
            } catch (_) {}
          }
          String label(String id) => id.replaceAll(RegExp(r'-\d{8}$'), '');
          final models = <Map<String, String>>[
            for (final e in provider.relayModels)
              if (e is Map &&
                  e['available'] == true &&
                  '${e['id'] ?? ''}'.isNotEmpty)
                {'id': '${e['id']}', 'label': label('${e['id']}')},
          ];
          // 一覧が取れない時でも、 今のモデルだけは出す。
          if (models.isEmpty && provider.relayModel.isNotEmpty) {
            models.add({
              'id': provider.relayModel,
              'label': label(provider.relayModel),
            });
          }
          return jsonEncode(
              {'current': provider.relayModel, 'models': models});
        }
      case 'floatingMemoSetAiModel':
        // メモ窓で選んだモデルを本体の設定 (relayModel) に反映する。
        {
          final id = '${call.arguments ?? ''}'.trim();
          if (id.isNotEmpty) {
            await context.read<MindMapProvider>().setRelayModel(id);
          }
          return 'ok';
        }
      case 'openFloatingMemo':
        // フローティング AI のヘッダーから (= ユーザー要望)。
        // ignore: discarded_futures
        _openPopOutWindow(context.read<MindMapProvider>(), kind: 'memo');
        break;
      case 'openFloatingAi':
        // メモ窓 (サブウィンドウ) では WebView2 が動かないため、 本体に
        // 頼んで開いてもらう (= ユーザー報告: AI チャット欄を開くと
        // webview 関連のエラー)。 今は本体もパネルではなく「アプリの外の
        // 窓」 を起動するので、 本体を前面に出す必要はない。
        final aiQuery = '${call.arguments ?? ''}'.trim();
        _openDesktopFloatingAi(context.read<MindMapProvider>(),
            query: aiQuery.isEmpty ? null : aiQuery);
        break;
      case 'openFloatingWeb':
        // メモ窓の Google 検索も同じ理由で本体側の浮遊パネルで開く。
        final webUrl = '${call.arguments ?? ''}'.trim();
        if (webUrl.isEmpty) break;
        try {
          await windowManager.show();
        } catch (_) {}
        _showFloatingPanelWindow(
          (_) => _WinGoogleSearchView(
            key: ValueKey('floating_web_$webUrl'),
            url: webUrl,
          ),
          width: 760,
          height: 620,
          memoryKey: 'web',
          popOutUrl: webUrl,
        );
        break;
      case 'floatingMemoPages':
        // メモの「マップに追加」 のページ一覧 (= ユーザー要望: 追加先の
        // ページを指定できるように)。
        final provider = context.read<MindMapProvider>();
        final cur = provider.currentPage.id;
        return jsonEncode([
          for (final p in provider.pages)
            if (p.pageType == 'normal' || p.pageType == 'bookshelf')
              {'id': p.id, 'name': p.name, 'current': p.id == cur},
        ]);
      case 'floatingMemoToNodePage':
        try {
          final m = jsonDecode('${call.arguments}') as Map<String, dynamic>;
          final text = '${m['text'] ?? ''}'.trim();
          final pid = '${m['pageId'] ?? ''}';
          if (text.isEmpty) break;
          final provider = context.read<MindMapProvider>();
          final idx = provider.pages.indexWhere((p) => p.id == pid);
          if (idx < 0) break;
          provider.addMemoNodeToPage(idx, text);
          // 別プロセスのメモ窓は戻り値で成否を見る (= ユーザー報告対応)。
          return 'ok';
        } catch (_) {}
        break;
    }
    return null;
  }

  /// 本体が起きていない間にフローティングメモが控えた「マップに追加」 を
  /// 取り込む (= ユーザー要望: 本体が起動していなくても追加できるように)。
  /// メモ窓が prefs `pending_memo_to_map_v1` に積んだ分を、 読み込み完了後に
  /// 現在のページへメモ要素として足す。
  Future<void> _drainPendingFloatingMemos() async {
    try {
      final provider = context.read<MindMapProvider>();
      await provider.initialLoadDone;
      if (!mounted) return;
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString('pending_memo_to_map_v1');
      if (raw == null || raw.isEmpty) return;
      List<dynamic> queue;
      try {
        queue = jsonDecode(raw) as List<dynamic>;
      } catch (_) {
        await sp.remove('pending_memo_to_map_v1');
        return;
      }
      var added = 0;
      for (final e in queue) {
        if (e is! Map) continue;
        final text = '${e['text'] ?? ''}'.trim();
        if (text.isEmpty) continue;
        provider.addMemoNodeToPage(provider.currentPageIndex, text);
        added++;
      }
      await sp.remove('pending_memo_to_map_v1');
      if (added > 0 && mounted) {
        _appSnack(
          context,
          SnackBar(
            content: Text(provider
                .t('memo.pendingAdded')
                .replaceFirst('{n}', '$added')),
            backgroundColor: const Color(0xFF1A2A14),
          ),
        );
      }
    } catch (e) {
      debugPrint('保留メモの取り込みに失敗: $e');
    }
  }

  /// 開いたポップアウト窓の ID (二重起動防止用)。
  /// 種類ごとの外部ツール窓の windowId (二重起動よけ)。
  final Map<String, int> _popOutToolWinIds = {};

  Future<void> _openPopOutWindow(MindMapProvider provider,
      {required String kind,
      String? query,
      Map<String, String>? extraArgs,
      // 「開いて」 と頼まれた時 (= トグルではない呼び出し)。 既に開いて
      //   いれば閉じずに前へ出す (= ユーザー報告: フローティング画面から
      //   フローティングメモを立ち上げられない。 見えない所に開きっぱなしの
      //   窓があると、 押すたびにトグルで閉じていた)。
      bool forceOpen = false}) async {
    if (!_isDesktop) {
      // ── モバイル (= ユーザー要望: フローティング AI をモバイルでも) ──
      //   デスクトップのような別ウィンドウは作れないので、 アプリ内の
      //   ドラッグできる浮遊パネルとして開く。 マップを見ながら AI を
      //   使えるという目的は同じ。
      if (kind == 'ai') {
        // アプリの外に出す (= ユーザー要望: アプリ内の小窓ではなく、 他の
        //   アプリの上に出せるように)。 オーバーレイを AI モードで開く。
        //   Android 以外はアプリ内の浮遊パネルにフォールバック。
        if (!kIsWeb && Platform.isAndroid) {
          try {
            final sp = await SharedPreferences.getInstance();
            await sp.setString('floating_overlay_mode_v1', 'ai');
          } catch (_) {}
          await _toggleFloatingMemoOverlay(provider, forceOpen: true);
          return;
        }
        _openMobileFloatingAi(provider, query: query);
        return;
      }
      _showLockToast(provider.t('popOut.desktopOnly'));
      return;
    }
    // ── デスクトップの AI は別ウィンドウにしない (= ユーザー報告: AI
    //    ウィンドウを開けませんでした) ──
    //   別ウィンドウでは WebView2 が動かないため、 アプリ内の浮遊パネルで
    //   開く。 マップを見ながら AI を使えるという目的は同じ。
    if (kind == 'ai') {
      _openDesktopFloatingAi(provider, query: query);
      return;
    }
    // ── 同じ種類の窓が既に開いていたら閉じる (= ユーザー要望: ボタンを
    //    もう一度押すと閉じるトグル) ──
    //    ただし forceOpen で頼まれた時は閉じずに前へ出す。
    final existingId = _popOutToolWinIds[kind];
    if (existingId != null) {
      var alive = false;
      try {
        final ids = await DesktopMultiWindow.getAllSubWindowIds();
        alive = ids.contains(existingId);
      } catch (_) {}
      if (alive) {
        if (forceOpen) {
          try {
            await WindowController.fromWindowId(existingId).show();
          } catch (_) {}
          return;
        }
        _popOutToolWinIds.remove(kind);
        try {
          await WindowController.fromWindowId(existingId).close();
        } catch (_) {}
        return;
      }
      // 既に閉じられている窓の id が残っていただけ → 作り直しへ。
      _popOutToolWinIds.remove(kind);
    }
    try {
      final args = <String, dynamic>{'kind': kind, ...?extraArgs};
      if (kind == 'ai') {
        // 選択中の AI サイトのトップを開く ({q} は空にする)。
        final tmpl =
            provider.browserAiTargetDef['url'] ?? 'https://chatgpt.com/';
        args['url'] = tmpl.replaceAll('{q}', '');
        if (query != null && query.trim().isNotEmpty) {
          args['q'] = query.trim();
        }
      }
      final win = await DesktopMultiWindow.createWindow(jsonEncode(args));
      _popOutToolWinIds[kind] = win.windowId;
      // メモは履歴が無ければ小さく始まり、 中身に合わせて自動で伸びる
      // (= ユーザー要望: 余計なスペースを確保しない)。
      final size = kind == 'memo'
          ? const Size(460, 200)
          : kind == 'calc'
              // 高さは開いた後に中身へぴったり合わせ直す (= 下の空き対策)。
              ? const Size(400, 640)
              : kind == 'timer'
                  ? const Size(360, 460)
                  : const Size(520, 720);
      // ── 押したボタンの近くに出す (= ユーザー要望: 左上固定ではなく) ──
      var origin = const Offset(160, 120);
      try {
        final b = await windowManager.getBounds();
        final p = _lastCustomButtonPointerPos;
        if (p != null) {
          origin = Offset(
            (b.left + p.dx + 16).clamp(b.left + 8,
                math.max(b.left + 8, b.right - size.width - 8)),
            (b.top + p.dy + 16).clamp(b.top + 8,
                math.max(b.top + 8, b.bottom - size.height - 8)),
          );
        }
      } catch (_) {}
      win
        ..setFrame(origin & size)
        ..setTitle(kind == 'memo'
            ? provider.t('hdr.mapMemo')
            : kind == 'calc'
                ? provider.t('hdr.calculator')
                : kind == 'timer'
                    ? provider.t('hdr.stopwatch')
                    : provider.t('hdr.popOutAi'))
        ..show();
    } catch (e) {
      if (!mounted) return;
      _appSnack(
        context,
        SnackBar(
          content: Text('${provider.t('popOut.failed')}: $e'),
          backgroundColor: const Color(0xFFE57373),
        ),
      );
    }
  }

  /// 分割ペインのホイール操作 (= ユーザー報告: Ctrl を押していないのに
  /// 拡大縮小してしまう)。 Ctrl 併用時だけズーム、 それ以外はスクロール。
  void _handlePaneWheel(PointerSignalEvent event,
      TransformationController ctrl, MindMapPage page) {
    if (event is! PointerScrollEvent) return;
    final ctrlKey = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    final m = Matrix4.copy(ctrl.value);
    if (ctrlKey) {
      // Ctrl + ホイール: ポインタ位置を中心にズーム。
      final cur = m.getMaxScaleOnAxis();
      final next =
          (cur * (1 - event.scrollDelta.dy / 900.0)).clamp(0.15, 3.0);
      if ((next - cur).abs() < 0.0005) return;
      final t = m.getTranslation();
      // 画面上のポインタ位置が動かないように平行移動を補正する。
      final box = context.findRenderObject() as RenderBox?;
      final local = box == null
          ? event.position
          : box.globalToLocal(event.position);
      final cx = (local.dx - t.x) / cur;
      final cy = (local.dy - t.y) / cur;
      m.setEntry(0, 0, next);
      m.setEntry(1, 1, next);
      m.setTranslationRaw(local.dx - cx * next, local.dy - cy * next, 0);
      ctrl.value = m;
      return;
    }
    // 通常のホイール: 上下 (Shift 併用で左右) にスクロール。
    final shift = HardwareKeyboard.instance.isShiftPressed;
    final dx = shift ? -event.scrollDelta.dy : -event.scrollDelta.dx;
    final dy = shift ? 0.0 : -event.scrollDelta.dy;
    if (dx == 0 && dy == 0) return;
    final t = m.getTranslation();
    final scale = m.getMaxScaleOnAxis();
    final canvasDim =
        _canvasDimensionForScrollbars(context.read<MindMapProvider>(),
            pageOverride: page);
    final margin = _canvasBoundaryMarginForScrollbars(
        context.read<MindMapProvider>(), context,
        pageOverride: page);
    final view = _splitCellGlobalRect(_mapSplitEditorSlot).size;
    final minX = view.width - (canvasDim.width + margin.right) * scale;
    final maxX = margin.left * scale;
    final minY = view.height - (canvasDim.height + margin.bottom) * scale;
    final maxY = margin.top * scale;
    m.setTranslationRaw(
      _clampCanvasTranslation(t.x + dx, minX, maxX),
      _clampCanvasTranslation(t.y + dy, minY, maxY),
      0,
    );
    ctrl.value = m;
  }

  /// ポインタ位置が編集セル以外の分割セル (別ページの閲覧ペイン / Web を
  /// 埋め込んだセル) の上にあるか (= ユーザー要望: 埋め込んだ先だけが
  /// スクロールするように)。
  bool _isPointerOverNonEditorSplitCell(Offset globalPos) {
    if (!_mapSplitOpen) return false;
    for (final k in _visibleSplitSlots()) {
      if (k == _mapSplitEditorSlot) continue;
      if (_splitCellGlobalRect(k).contains(globalPos)) return true;
    }
    return false;
  }

  /// セル [k] の画面上の矩形 (AppBar 下の body 領域基準)。
  Rect _splitCellGlobalRect(int k) {
    final s = View.of(context).physicalSize / View.of(context).devicePixelRatio;
    const top = kToolbarHeight;
    final body = Rect.fromLTWH(0, top, s.width, s.height - top);
    // 境界線をドラッグで動かせるので、 比率から矩形を計算する。
    final rx = _mapSplitRatioX;
    final ry = _mapSplitRatioY;
    Rect frac;
    if (!_mapSplitQuad) {
      frac = _mapSplitStacked
          ? (k == 0
              ? Rect.fromLTRB(0, 0, 1, ry)
              : Rect.fromLTRB(0, ry, 1, 1))
          : (k == 0
              ? Rect.fromLTRB(0, 0, rx, 1)
              : Rect.fromLTRB(rx, 0, 1, 1));
    } else {
      final l = (k % 2) == 0 ? 0.0 : rx;
      final r = (k % 2) == 0 ? rx : 1.0;
      final tp = (k ~/ 2) == 0 ? 0.0 : ry;
      final bt = (k ~/ 2) == 0 ? ry : 1.0;
      frac = Rect.fromLTRB(l, tp, r, bt);
    }
    return Rect.fromLTRB(
      body.left + body.width * frac.left,
      body.top + body.height * frac.top,
      body.left + body.width * frac.right,
      body.top + body.height * frac.bottom,
    );
  }

  /// フローティング検索ウィンドウ等をドラッグして分割セルの上で離したら、
  /// その URL をそのセルへ埋め込む (= ユーザー要望)。 埋め込めたら true。
  bool _tryEmbedDropOnSplitCell(Offset globalPos, String url) {
    if (!_canEmbedIntoMapSplit()) return false;
    for (final k in _visibleSplitSlots()) {
      if (_splitCellGlobalRect(k).contains(globalPos)) {
        // 編集セルへのドロップも許可 (= ユーザー要望: 自分の画面に埋め込む
        // こともドラッグで選べるように)。 その場合は編集ペインが隣へ移る。
        _embedUrlIntoSlot(k, url);
        return true;
      }
    }
    return false;
  }

  /// 外の窓 (= 別プロセスのフローティング Web 窓) を動かし終えた時の受け口。
  ///
  /// = ユーザー要望「外部に出した YouTube を、 画面分割で他の分割画面の上に
  ///   置いたら埋め込まれるようにして」。
  ///
  /// [frameOnScreen] は外の窓の画面座標での枠。 その中心が分割セルの上なら
  /// そのセルへ [url] を埋め込んで true を返す (= 外の窓は自分を閉じる)。
  /// 分割していない / ペインの上ではない時は false (窓はそのまま残る)。
  Future<bool> _handleFloatingWindowDrop(
      Rect frameOnScreen, String url) async {
    if (!mounted || !_isDesktop) return false;
    if (!_canEmbedIntoMapSplit()) return false;
    var origin = Offset.zero;
    try {
      final b = await windowManager.getBounds();
      if (b.left > -8000 && b.top > -8000) origin = b.topLeft;
    } catch (_) {}
    if (!mounted) return false;
    // 分割セルの矩形はアプリ内 (Flutter ビュー) 座標なので、 本体の窓の
    // 左上ぶんを引いて合わせる。
    return _tryEmbedDropOnSplitCell(frameOnScreen.center - origin, url);
  }

  /// URL を指定スロットへ埋め込む。 編集セルが指定された場合は編集ペインを
  /// 空いているセルへ退避してから埋め込む (= ユーザー要望: 自分の画面に
  /// 埋め込むこともできるように)。
  void _embedUrlIntoSlot(int slot, String url) {
    setState(() {
      if (slot == _mapSplitEditorSlot) {
        int other = _primaryViewerSlot();
        for (final s in _visibleSplitSlots()) {
          if (s != slot && _mapSplitCellWeb[s] == null) {
            other = s;
            break;
          }
        }
        _mapSplitEditorSlot = other;
        _mapSplitCellWeb.remove(other);
      }
      // 同じセルにツールが入っていたら、 Web に置き換える (取り残し防止)。
      _mapSplitCellTool.remove(slot);
      _mapSplitCellWeb[slot] = url;
      _syncNarrowPaneRatio();
    });
    // どのペインに入ったか分かるようにペイン名も出す (= ユーザー報告:
    // 変な位置に入る、 の切り分けにもなる)。
    final p = context.read<MindMapProvider>();
    _showLockToast('${_paneLabel(p, slot)}: ${p.t('map.webEmbedded')}');
  }

  /// 分割ペインの位置ラベル (左/右 or 左上/右上/左下/右下)。
  String _paneLabel(MindMapProvider provider, int k) {
    if (!_mapSplitQuad) {
      return provider.t(k == 0 ? 'map.paneLeft' : 'map.paneRight');
    }
    switch (k) {
      case 0:
        return provider.t('map.paneTL');
      case 1:
        return provider.t('map.paneTR');
      case 2:
        return provider.t('map.paneBL');
      default:
        return provider.t('map.paneBR');
    }
  }

  /// フローティング窓の「ペインへ送る」 メニュー (= ユーザー要望: 別の
  /// ペインへ送る / 自分のペインへ埋め込むを選べるように)。
  void _showFloatingSendMenu(
      String url, Offset globalPos, VoidCallback closeWin) {
    if (!_mapSplitOpen || !mounted) return;
    final provider = context.read<MindMapProvider>();
    final items = <PopupMenuEntry<int>>[];
    for (final k in _visibleSplitSlots()) {
      final isEd = k == _mapSplitEditorSlot;
      items.add(PopupMenuItem<int>(
        value: k,
        height: 38,
        child: Text(
          isEd
              ? provider.t('map.embedOwnPane')
              : provider
                  .t('map.sendToPane')
                  .replaceFirst('{p}', _paneLabel(provider, k)),
          style: const TextStyle(color: Colors.white, fontSize: 12.5),
        ),
      ));
    }
    showMenu<int>(
      context: context,
      color: const Color(0xFF1E1E32),
      position: RelativeRect.fromLTRB(
          globalPos.dx, globalPos.dy, globalPos.dx + 1, globalPos.dy + 1),
      items: items,
    ).then((slot) {
      if (slot == null || !mounted) return;
      _embedUrlIntoSlot(slot, url);
      closeWin();
    });
  }

  /// フローティング動画 / Web ウィンドウ (= ユーザー要望: 要素タップで
  /// 立ち上がる YouTube も Google 検索と同様にドラッグして分割セルへ
  /// 埋め込めるように)。 Overlay 上の非モーダル窓。
  final List<OverlayEntry> _floatingVideoEntries = [];

  /// 任意の画面 (画像編集など) をフローティング窓で開く (= ユーザー要望:
  /// 分割中は分割を覆わない窓で開き、 他の領域で別の作業ができるように)。
  /// モバイル用のフローティング AI (= ユーザー要望)。
  /// アプリ内のドラッグ / リサイズできる小窓で AI サイトを開く。
  /// [query] があればプロンプト欄へ事前入力する。
  void _openMobileFloatingAi(MindMapProvider provider, {String? query}) {
    final tmpl = provider.browserAiTargetDef['url'] ?? 'https://chatgpt.com/';
    final q = (query ?? '').trim();
    final url = q.isEmpty
        ? tmpl.replaceAll('{q}', '')
        : tmpl.replaceAll('{q}', Uri.encodeComponent(q));
    // 画面に収まる大きさで開く (小さい端末でも操作部が隠れないように)。
    final size = MediaQuery.of(context).size;
    final w = math.min(size.width * 0.94, 520.0);
    final h = math.min(size.height * 0.72, 720.0);
    _showFloatingPanelWindow(
      (_) => _MobileBrowserAiPage(
        url: url,
        injectText: q,
        embedded: true,
      ),
      width: w,
      height: h,
      memoryKey: 'ai',
    );
  }

  /// デスクトップ: AI を「アプリの外の窓」 として開く (= ユーザー要望:
  /// フローティング AI はアプリの外に出て、 ディアクティブでも前面に出る
  /// ピン機能が欲しい)。
  ///
  /// ★ サブ窓 (DesktopMultiWindow) では WebView2 が初期化できないので、
  ///   同じ実行ファイルをもう 1 プロセス起動する (= OS から見て普通の窓)。
  ///   これならアプリの枠の外へ自由に動かせて、 常に手前 (TOPMOST) にも
  ///   できる。 WebView の保存先は共有なので、 ログイン状態もそのまま。
  ///   起動時からピン ON で開く。
  void _openDesktopFloatingAi(MindMapProvider provider, {String? query}) {
    final def = provider.browserAiTargetDef;
    final tmpl = (def['url'] as String?) ?? 'https://chatgpt.com/';
    final q = (query ?? '').trim();
    final url = tmpl.replaceAll('{q}', Uri.encodeComponent(q));
    final label = (def['label'] as String?) ?? 'AI';
    final ok = openExternalWebWindow(url, pinned: true, title: label);
    if (ok) return;
    // 外の窓を開けない環境 (= モバイル等) では、 従来どおりアプリ内の
    //   浮遊パネルで開く。
    _showFloatingPanelWindow(
      (_) => _FloatingAiSwitcherPanel(query: q),
      width: 560,
      height: 720,
      memoryKey: 'ai',
    );
  }

  /// サイト (Instagram / Slack / Discord / YouTube 等) をアプリ内の
  /// ドラッグできる浮遊パネルで開く (= ユーザー要望: 各サイトボタンに
  /// フローティング機能を付ける)。 別ウィンドウでは WebView2 が動かない
  /// ため、 フローティング AI と同じ本体内パネルで開く。
  void _floatSiteUrl(String url) {
    final u = url.trim();
    if (u.isEmpty || !_isDesktop) return;
    _showFloatingPanelWindow(
      (_) => _WinGoogleSearchView(
        key: ValueKey(
            'float_site_${u}_${DateTime.now().millisecondsSinceEpoch}'),
        url: u,
      ),
      width: 760,
      height: 620,
      memoryKey: 'site',
      popOutUrl: u,
    );
  }

  /// 開いているフローティング窓 (合言葉 -> 実体)。 同じ合言葉の窓は
  /// 1 つだけにして、 2 回目からは前面に出し直す (= ユーザー要望: タップの
  /// たびに窓が増える)。 「複数開けるようにする」 を入れている時は増やす。
  final Map<String, OverlayEntry> _floatingPanelSingletons = {};

  void _showFloatingPanelWindow(WidgetBuilder builder,
      {double width = 760,
      double height = 560,
      String? memoryKey,
      String? singletonKey,
      String? popOutUrl,
      ValueGetter<String>? popOutUrlBuilder,
      bool aiSwitchable = false,
      // Web ページでない画面を外へ出すための差し替え口 (= ユーザー要望:
      //   AI アシスタントもアプリの外に出せるように)。
      Future<bool> Function(Rect frame, bool pinned)? popOutCustom,
      // 最初に出す位置と大きさ (= マップ分割中は分割セルを覆う形で開く)。
      Rect? initialRect,
      VoidCallback? onClosed}) {
    // ★ 同じ窓が既に開いていれば、 増やさずに前面へ出し直す。
    //
    // = ユーザー要望「フローティングの窓が後ろに隠れた後、 その項目を
    //   もう一度押したら既に開いている窓が前面に出てくるように」。
    //   合言葉を渡していない呼び出しが多かったので、 覚えている置き場所
    //   (memoryKey) を合言葉の代わりに使う。 どちらも無い窓だけ今までどおり
    //   増える。
    singletonKey ??= memoryKey;
    final allowMulti =
        context.read<MindMapProvider>().allowMultipleFloatingWindows;
    if (singletonKey != null && !allowMulti) {
      final open = _floatingPanelSingletons[singletonKey];
      if (open != null) {
        if (_floatingVideoEntries.contains(open)) {
          // 一度外して入れ直すと一番上に来る (中身と位置はそのまま)。
          try {
            open.remove();
            Overlay.of(context, rootOverlay: true).insert(open);
          } catch (_) {}
          return;
        }
        _floatingPanelSingletons.remove(singletonKey);
      }
    }
    late OverlayEntry entry;
    void closeSelf() {
      if (_floatingVideoEntries.contains(entry)) {
        entry.remove();
        _floatingVideoEntries.remove(entry);
        if (singletonKey != null &&
            identical(_floatingPanelSingletons[singletonKey], entry)) {
          _floatingPanelSingletons.remove(singletonKey);
        }
        onClosed?.call();
      }
    }

    entry = OverlayEntry(
      builder: (_) => _FloatingPanelWindow(
        builder: builder,
        initialWidth: width,
        initialHeight: height,
        // 最後に開いた大きさ・位置で開く (= ユーザー要望)。
        memoryKey: memoryKey,
        // アプリの外へ出せるようにする (= ユーザー要望)。 スマホ版でも
        // ボタン自体は出して、 押したら「パソコン版だけ」 と知らせる
        // (= 出せない理由が分かるように)。
        popOutUrl: popOutUrl,
        popOutUrlBuilder: popOutUrlBuilder,
        // AI を表示している窓なら、 ヘッダーからモデルを切り替えられる
        // (= ユーザー要望: フローティングに切り替えた後も切り替えたい)。
        onSwitchAi: aiSwitchable
            ? () => _switchFloatingAi(closeSelf, width, height, memoryKey)
            : null,
        popOutCustom: popOutCustom,
        initialRect: initialRect,
        onClose: closeSelf,
      ),
    );
    _floatingVideoEntries.add(entry);
    if (singletonKey != null) _floatingPanelSingletons[singletonKey] = entry;
    Overlay.of(context, rootOverlay: true).insert(entry);
  }

  /// 「フローティングで開く」 の入口 (= ユーザー要望: フローティングモードと
  /// 外部モードを統合)。 デスクトップは最初から**アプリの外の本物の窓**として
  /// 開く。 本体を消しても残り、 ピン留めも窓のヘッダーからできる。
  /// 別の窓を作れないモバイルだけ、 アプリ内の浮遊パネルで開く。
  /// 外部 Web 窓のプロセス (URL のホスト → pid)。 再押しで閉じるために覚える。
  final Map<String, int> _externalWebPids = {};

  void _openFloatingWebUnified(String url) {
    final u = url.trim();
    if (u.isEmpty) return;
    if (_isDesktop) {
      // ── もう一度押した時 ──
      //   後ろに隠れているなら前面に出し直す (= ユーザー要望)。
      //   既に一番手前にあるなら、 今までどおり閉じる (トグル)。
      final key = Uri.tryParse(u)?.host ?? u;
      final openPid = _externalWebPids[key];
      if (openPid != null) {
        final wasFront = bringExternalWindowToFront(openPid);
        if (!wasFront) return; // 前面に出したので、ここで終わり
        _externalWebPids.remove(key);
        var closed = false;
        try {
          closed = Process.killPid(openPid);
        } catch (_) {}
        if (closed) return;
      }
      unawaited(() async {
        // 押したボタンの近くに出す (= ユーザー要望: 左上固定ではなく)。
        Offset? pos;
        try {
          final b = await windowManager.getBounds();
          final p = _lastCustomButtonPointerPos;
          if (p != null) {
            pos = Offset(b.left + p.dx + 16, b.top + p.dy + 16);
          }
        } catch (_) {}
        // ここは「もう一度押したら閉じる」 トグルなので、 共通の
        //   1 つだけ制御は通さない (閉じた直後に開き直せなくなるため)。
        final pid =
            await openExternalWebWindowPid(u, position: pos, single: false);
        if (pid != null && mounted) _externalWebPids[key] = pid;
      }());
      return;
    }
    _showFloatingPanelWindow(
      (_) =>
          _WinGoogleSearchView(key: ValueKey('floating_web_$u'), url: u),
      width: 560,
      height: 720,
      memoryKey: 'web',
      popOutUrl: u,
      aiSwitchable: _isBrowserAiUrl(u),
    );
  }

  /// この URL が AI チャットのものか (= フローティングにした時にヘッダーへ
  /// モデル切り替えを出してよいか)。
  bool _isBrowserAiUrl(String url) {
    if (url.isEmpty) return false;
    String host;
    try {
      host = Uri.parse(url).host.toLowerCase();
    } catch (_) {
      return false;
    }
    if (host.isEmpty) return false;
    for (final t in MindMapProvider.browserAiTargets) {
      try {
        final h = Uri.parse(t['url'] ?? '').host.toLowerCase();
        if (h.isNotEmpty && h == host) return true;
      } catch (_) {}
    }
    return false;
  }

  /// フローティングで開いている AI を別のモデルへ切り替える
  /// (= ユーザー要望: フローティングに切り替えた後もヘッダーから切り替えたい)。
  ///
  /// 中身を差し替えるのではなく、 今の窓を閉じて選んだ AI で開き直す。
  /// 大きさと位置は memoryKey で覚えているので、 同じ場所に出てくる。
  Future<void> _switchFloatingAi(VoidCallback closeCurrent, double width,
      double height, String? memoryKey) async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final anchor = _customButtonAnchor();
    final picked = await showDialog<String>(
      context: context,
      barrierColor: Colors.black.withValues(alpha: 0.3),
      builder: (dctx) => _positionNearAnchor(
        dctx,
        anchor,
        Material(
          color: const Color(0xFF2A2A3E),
          elevation: 12,
          borderRadius: BorderRadius.circular(16),
          child: Padding(
            padding: const EdgeInsets.fromLTRB(18, 16, 18, 14),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(children: [
                  const Icon(Icons.auto_awesome_rounded,
                      color: Color(0xFFBA68C8), size: 18),
                  const SizedBox(width: 8),
                  Text(provider.t('ai.selectAi'),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 15,
                          fontWeight: FontWeight.w700)),
                ]),
                const SizedBox(height: 12),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: [
                    for (final t in MindMapProvider.browserAiTargets)
                      InkWell(
                        borderRadius: BorderRadius.circular(20),
                        onTap: () => Navigator.pop(dctx, t['id']),
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 14, vertical: 8),
                          decoration: BoxDecoration(
                            color: t['id'] == provider.browserAiTarget
                                ? const Color(0xFFBA68C8)
                                    .withValues(alpha: 0.3)
                                : Colors.white.withValues(alpha: 0.07),
                            borderRadius: BorderRadius.circular(20),
                            border: Border.all(
                                color: t['id'] == provider.browserAiTarget
                                    ? const Color(0xFFBA68C8)
                                    : Colors.white24),
                          ),
                          child: Text(t['label'] ?? '',
                              style: const TextStyle(
                                  color: Colors.white, fontSize: 13)),
                        ),
                      ),
                  ],
                ),
              ],
            ),
          ),
        ),
        const Size(320, 220),
      ),
    );
    if (!mounted || picked == null || picked.isEmpty) return;
    await provider.setBrowserAiTarget(picked);
    if (!mounted) return;
    final def = MindMapProvider.browserAiTargets.firstWhere(
        (t) => t['id'] == picked,
        orElse: () => MindMapProvider.browserAiTargets.first);
    // クエリを入れない素のチャット画面を開く。
    final url = (def['url'] ?? '').replaceFirst('?q={q}', '').replaceFirst(
        '{q}', '');
    closeCurrent();
    _showFloatingPanelWindow(
      (_) => _WinGoogleSearchView(key: ValueKey('floating_web_$url'), url: url),
      width: width,
      height: height,
      memoryKey: memoryKey,
      popOutUrl: url,
      aiSwitchable: true,
    );
  }

  /// [globalPos] を含む分割セル番号。 どのセルにも入らなければ編集セル。
  int _slotAtGlobal(Offset? globalPos) {
    if (globalPos != null) {
      for (final k in _visibleSplitSlots()) {
        if (_splitCellGlobalRect(k).contains(globalPos)) return k;
      }
    }
    return _mapSplitEditorSlot;
  }

  /// フローティング窓を開く。 [nearScreenPos] (= 発生元のノードの画面座標)
  /// があればそのノードがいるセルの中央に、 無ければ [slot] / 編集セルの
  /// 中央に出す (= ユーザー要望: 立ち上げた分割ブロックの上に出す)。
  void _showFloatingVideoWindow(String url,
      {Offset? nearScreenPos,
      int? slot,
      // 外の本物の窓で開くか。 null = 既定 (パソコンなら外の窓)。
      // 動作設定で「アプリ内の浮遊窓」 を選んだ時に false が来る。
      bool? external}) {
    Offset? pos;
    double w = 560;
    double h = 380;
    if (_mapSplitOpen) {
      final k = slot ?? _slotAtGlobal(nearScreenPos);
      final cell = _splitCellGlobalRect(k);
      // セルからはみ出さないサイズに収め、 そのセルの中央に置く。
      w = math.min(w, math.max(320.0, cell.width - 24));
      h = math.min(h, math.max(220.0, cell.height - 24));
      pos = Offset(
        cell.left + (cell.width - w) / 2,
        cell.top + (cell.height - h) / 2,
      );
    }
    // ── デスクトップは「アプリの外の本物の窓」 で開く ──
    // = ユーザー要望「そもそも要素から YouTube を立ち上げる時は、 いきなり
    //   外部に出すモードで立ち上がるようにして。 それを画面分割で他の分割
    //   画面の上に置いたら埋め込まれる仕様に」。
    // アプリ内の重ね描き窓は WebView2 の初期化に失敗することがあり
    //   (= ユーザー報告: 分割中に要素から YouTube を開くと「WebView を
    //   初期化できませんでした」)、 別プロセスの窓なら確実に表示できる。
    // 窓を分割ペインの上へ置いて放すと、 そのペインへ埋め込まれる
    //   (--floating-embed → main.dart の /embed → _handleFloatingWindowDrop)。
    if ((external ?? true) &&
        _isDesktop &&
        (url.startsWith('http://') || url.startsWith('https://'))) {
      // ignore: discarded_futures
      _openExternalFloatingVideoWindow(url, localPos: pos, width: w, height: h);
      return;
    }
    _showInAppFloatingVideoWindow(url, pos: pos, width: w, height: h);
  }

  /// 要素から開いた動画 / Web を「アプリの外の窓」 として立ち上げる。
  /// [localPos] はアプリ内 (Flutter ビュー) の座標。 画面座標へ直してから
  /// 開くので、 分割ペインの上にそのまま重なって出る。
  Future<void> _openExternalFloatingVideoWindow(String url,
      {Offset? localPos, required double width, required double height}) async {
    var origin = Offset.zero;
    try {
      final b = await windowManager.getBounds();
      // 最小化中は座標があり得ない値になるので使わない。
      if (b.left > -8000 && b.top > -8000) origin = b.topLeft;
    } catch (_) {}
    final ok = openExternalWebWindow(
      url,
      embeddable: true,
      frame: localPos == null
          ? null
          : Rect.fromLTWH(
              (origin.dx + localPos.dx).clamp(0.0, 8000.0),
              (origin.dy + localPos.dy).clamp(0.0, 8000.0),
              width,
              height,
            ),
    );
    if (ok || !mounted) return;
    // 外の窓を開けない環境では従来どおりアプリ内の浮遊窓で開く。
    _showInAppFloatingVideoWindow(url,
        pos: localPos, width: width, height: height);
  }

  /// アプリ内の浮遊窓 (重ね描き) で開く従来の経路。 モバイルや、 外の窓を
  /// 開けなかった時のフォールバック。
  void _showInAppFloatingVideoWindow(String url,
      {Offset? pos, required double width, required double height}) {
    final w = width;
    final h = height;
    late OverlayEntry entry;
    entry = OverlayEntry(
      builder: (_) => _FloatingWebWindow(
        url: url,
        initialPos: pos,
        initialWidth: w,
        initialHeight: h,
        onDragDrop: _tryEmbedDropOnSplitCell,
        onSendTo: _showFloatingSendMenu,
        onClose: () {
          if (_floatingVideoEntries.contains(entry)) {
            entry.remove();
            _floatingVideoEntries.remove(entry);
          }
        },
      ),
    );
    _floatingVideoEntries.add(entry);
    Overlay.of(context, rootOverlay: true).insert(entry);
  }

  /// 「左に分割 / 右に分割」 をマップ分割と統合する (= ユーザー要望:
  /// 分割表示中に左分割を押したら、 分割の左側の領域がその画面になる)。
  /// 左右 (モバイルの上下分割では上下) のどちら側かでセルを選ぶ。
  void _embedUrlIntoSplitSide(String url, {required bool left}) {
    // まだ分割していなければ、 このボタンで分割表示を開いてから入れる
    // (= ユーザー要望: 従来の左右分割ボタンと分割表示を統合)。
    if (_isDesktop && !_mapSplitOpen) {
      final provider = context.read<MindMapProvider>();
      if (_splitEligiblePage(provider.currentPage)) {
        _toggleMapSplitFromHeader();
      }
    }
    if (!_canEmbedIntoMapSplit()) return;
    _embedUrlIntoSlot(_mapSplitSideSlot(left: left), url);
  }

  /// 左分割 / 右分割で入れる先のセル番号。 セルの位置 (画面座標) から
  /// 左右 (縦積みなら上下) を判定する。 分割を開く働きは持たない
  /// (= ユーザー要望: PDF もこの選び方に合わせて同じ側へ入れたい)。
  int _mapSplitSideSlot({required bool left}) {
    if (!_mapSplitQuad) {
      if (_mapSplitStacked) return left ? 0 : 1; // 上 / 下
      return left ? 0 : 1; // 左 / 右
    }
    // 4 分割: 左列 = 0,2 / 右列 = 1,3 (= ユーザー報告: 変な位置に
    // 入ることがある)。 選び方を明確に:
    //   1) 指定した列の「空いている」 非編集セル
    //   2) 指定した列の非編集セル (上書き)
    final col = left ? const [0, 2] : const [1, 3];
    for (final k in col) {
      if (k != _mapSplitEditorSlot && _mapSplitCellWeb[k] == null) return k;
    }
    for (final k in col) {
      if (k != _mapSplitEditorSlot) return k;
    }
    return col.first;
  }

  /// URL を空いている分割セル (編集セル以外) へ埋め込む。
  void _embedUrlIntoSplitCell(String url) {
    setState(() {
      int? target;
      for (final s in _visibleSplitSlots()) {
        if (s == _mapSplitEditorSlot) continue;
        if (_mapSplitCellWeb[s] == null) {
          target = s;
          break;
        }
      }
      target ??= _primaryViewerSlot();
      _mapSplitCellWeb[target] = url;
    });
    _showLockToast(
        context.read<MindMapProvider>().t('map.webEmbedded'));
  }

  /// 互換: 編集セルが 1 番目 (左/上) か。
  bool get _mapSplitEditorOnFirst => _mapSplitEditorSlot == 0;

  /// 分割ペインに表示できるページか。 文書 / ビデオエディターのみ除外
  /// (フリーノートも開ける = ユーザー要望: フリーノートとマップ /
  /// ギャラリーを同時に開けるように)。
  bool _splitEligiblePage(MindMapPage p) =>
      p.pageType != 'document' && p.pageType != 'videoEditor';

  /// 表示中のセル番号一覧 (2 分割は 0,1 / 4 分割は 0..3)。
  List<int> _visibleSplitSlots() =>
      _mapSplitQuad ? const [0, 1, 2, 3] : const [0, 1];

  /// ヘッダーコントロールが対象にする「主ペイン」 (編集セル以外の最初の
  /// 表示セル)。
  int _primaryViewerSlot() {
    for (final i in _visibleSplitSlots()) {
      if (i != _mapSplitEditorSlot) return i;
    }
    return _mapSplitEditorSlot == 0 ? 1 : 0;
  }

  // ── ページ背景 (壁紙 / テンプレート) の明暗判定 ──
  // = ユーザー要望: 背景を黒系にしたのに接続線の色が白にならない →
  //   背景の明暗に合わせて線の色が自動で見やすくなるように。
  /// 暗い系の組み込みテンプレート id。
  static const Set<String> _kDarkMapBgTemplates = {
    'wood', 'chalkboard', 'ocean', 'aurora', 'nightSky', 'galaxy',
    'rain', 'blueprint', 'midnight',
    // 花火 / 城 も夜空ベースで暗い (= 接続線を白系にする)。
    'fireworks', 'castle',
  };

  /// カスタム背景画像の明暗判定キャッシュ (path → 暗いか)。
  final Map<String, bool> _bgImageDarkCache = {};

  /// ページの背景が暗いか。 背景なしはテーマに従う。 カスタム画像は
  /// 初回のみ縮小デコードして平均輝度を計算 (完了までテーマ準拠)。
  bool _pageBackgroundIsDark(MindMapProvider provider, MindMapPage page) {
    final path = page.backgroundImagePath;
    if (path == null || path.isEmpty) return provider.isDarkMode;
    final tpl = _mapBackgroundTemplateId(path);
    if (tpl != null) return _kDarkMapBgTemplates.contains(tpl);
    final cached = _bgImageDarkCache[path];
    if (cached != null) return cached;
    _computeBgImageDark(path);
    return provider.isDarkMode;
  }

  Future<void> _computeBgImageDark(String path) async {
    if (_bgImageDarkCache.containsKey(path)) return;
    _bgImageDarkCache[path] = false; // 再入防止の仮値 (完了後に上書き)
    try {
      final f = File(path);
      if (!await f.exists()) return;
      final bytes = await f.readAsBytes();
      final codec = await ui.instantiateImageCodec(bytes,
          targetWidth: 24, targetHeight: 24);
      final frame = await codec.getNextFrame();
      final data =
          await frame.image.toByteData(format: ui.ImageByteFormat.rawRgba);
      frame.image.dispose();
      if (data == null) return;
      var sum = 0.0;
      final n = data.lengthInBytes ~/ 4;
      for (var i = 0; i < n; i++) {
        sum += 0.299 * data.getUint8(i * 4) +
            0.587 * data.getUint8(i * 4 + 1) +
            0.114 * data.getUint8(i * 4 + 2);
      }
      final dark = n > 0 && (sum / n) < 110;
      _bgImageDarkCache[path] = dark;
      if (mounted && dark) setState(() {});
    } catch (_) {}
  }

  /// セル [k] (非編集セル) に表示するページを解決する。 他のセルと重複
  /// しないページを選ぶ。 開けるページが無ければ null。
  MindMapPage? _resolveSplitCellPage(MindMapProvider provider, int k) {
    final used = <String>{provider.currentPage.id};
    for (final i in _visibleSplitSlots()) {
      if (i == k || i == _mapSplitEditorSlot) continue;
      final id = _mapSplitCells[i];
      if (id != null) used.add(id);
    }
    final pages = provider.pages.where(_splitEligiblePage).toList();
    final storedId = _mapSplitCells[k];
    for (final p in pages) {
      if (p.id == storedId && !used.contains(p.id)) return p;
    }
    for (final p in pages) {
      if (!used.contains(p.id)) return p;
    }
    return null;
  }

  /// 分割レイアウト: 編集セル + 閲覧セル (2 分割 or 4 分割 = ユーザー要望)。
  /// 編集セルはタップされたセルへその場で移る (セルのページ配置は不変)。
  Widget _buildMapSplitLayout(BuildContext context, MindMapProvider provider,
      TransformationController ctrl) {
    // 境界線はドラッグで動かせる (= ユーザー要望)。 使い回すと GestureDetector
    // の状態が共有されるので、 置く場所ごとに生成する。
    Widget divV() => _mapSplitDivider(vertical: true);
    Widget divH() => _mapSplitDivider(vertical: false);
    // 比率は整数 flex に落として反映する (1000 分率)。
    final flexA = (_mapSplitRatioX * 1000).round().clamp(150, 850);
    final flexB = 1000 - flexA;
    final flexTop = (_mapSplitRatioY * 1000).round().clamp(150, 850);
    final flexBottom = 1000 - flexTop;
    Widget cell(int k, {int flex = 1000}) {
      final isEditor = k == _mapSplitEditorSlot;
      final String? webUrl = isEditor ? null : _mapSplitCellWeb[k];
      final String? toolId = isEditor ? null : _mapSplitCellTool[k];
      Widget inner;
      String label;
      if (isEditor) {
        final cur = provider.currentPage;
        label = _splitPageLabel(cur);
        // ClipRect: 壁紙などの描画が隣のペインへはみ出さないようにする。
        // フリーノートが編集側の時は専用ビューをそのまま埋める
        // (= ユーザー要望: フリーノートとマップ等を同時に開ける)。
        inner = ClipRect(
          child: cur.pageType == 'paint'
              ? _PaintPageView(
                  key: ValueKey('paint_note_${cur.id}_${provider.paintReloadTick}'),
                  provider: provider,
                  pageId: cur.id)
              // Markdown ページも分割の中でそのまま開く (= ユーザー報告:
              //   ページ名は Markdown なのに中身が出ない)。
              : cur.pageType == 'markdown'
                  ? _MarkdownPageView(
                      key: ValueKey('md_split_editor_${cur.id}'),
                      provider: provider,
                      pageId: cur.id,
                      extractText: _extractAttachmentTextForAi,
                      onEmbedToPage: (path, name, {pageId}) =>
                          _embedFileAsNode(provider, path, name,
                              pageId: pageId),
                      onOpenBrowserAi: _isDesktop
                          ? () => _openDesktopFloatingAi(provider)
                          : null)
                  : _buildCanvas(context, provider, ctrl),
        );
      } else if (webUrl != null) {
        // ── Web 埋め込みセル (= ユーザー要望: Google 検索 / YouTube を
        //    分割画面に埋め込み、 再生しながら別ページを編集)。 webview は
        //    独立したセルとして生き続けるので、 他セルの編集中も再生が
        //    止まらない。 サイト名は常時表示せずボタンだけにする
        //    (= ユーザー要望: ずっと左上に表示されたら鬱陶しい)。 ──
        label = '';
        // tick を混ぜているので、 同じ URL でも tick が増えると作り直される
        //   = 更新される (= ユーザー要望)。
        final webKey = ValueKey('map_split_web_${k}_${webUrl}_'
            '${_mapSplitCellWebTick[k] ?? 0}');
        inner = ClipRect(
          // ★ モバイルも埋め込めるようにした (= ユーザー報告: 分割画面で
          //   要素から YouTube を押すと WebView が出せなかった)。 中で
          //   デスクトップ = webview_windows / モバイル = inappwebview に
          //   切り替わる。
          child: _WinGoogleSearchView(
            key: webKey,
            // 更新した時に「今見ている画面」 を読み直せるよう、 辿った先の
            //   URL があればそれを開く (= ユーザー要望: ホームに戻らない)。
            url: _mapSplitCellWebCur[k] ?? webUrl,
            onUrlChanged: (u) => _mapSplitCellWebCur[k] = u,
          ),
        );
      } else if (toolId != null) {
        // ── ツール埋め込みセル (計算機など。 = ユーザー要望: ペインに置いた
        //    ボタンから開いたらそのペイン内の全画面で開く) ──
        label = '';
        inner = ClipRect(
          child: Container(
            color: const Color(0xFF12121F),
            child: _buildEmbeddedPaneTool(provider, k, toolId),
          ),
        );
      } else {
        final page = _resolveSplitCellPage(provider, k);
        label = page == null
            ? provider.t('map.splitNoOtherPage')
            : _splitPageLabel(page);
        inner = _buildMapSplitPane(provider, slot: k);
      }
      // ── どのセルにどのページが開いているかのバッジ (= ユーザー要望:
      //    4 分割でどこがどこか分かりにくい)。 アクティブ側の色変え / 枠は
      //    廃止 (= ユーザー要望: 一々色を変えなくてよい)。 編集セルは
      //    小さな ✎ アイコンだけで示す。 バッジをタップすると別のページ
      //    に入れ替えられる (= ユーザー要望)。 ──
      final paneBtns = _paneHeaderButtons[k] ?? const <String>[];
      // このセルに埋め込まれているファイルビューア (無ければ null)。
      final WidgetBuilder? embedded = _mapSplitCellFile[k];
      Widget cellStack = Stack(fit: StackFit.expand, children: [
          inner,
          // ── ペインのミニヘッダー (コピーされた全体ヘッダーボタン。
          //    押すとこのペインで起動 / 長押しで削除 = ユーザー要望) ──
          if (paneBtns.isNotEmpty)
            Positioned(
              left: 6,
              top: 32,
              child: Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 4, vertical: 1),
                decoration: BoxDecoration(
                  color: Colors.black.withValues(alpha: 0.40),
                  borderRadius: BorderRadius.circular(999),
                ),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  for (final id in paneBtns)
                    _paneHeaderBtn(provider, k, id),
                ]),
              ),
            ),
          Positioned(
            left: 6,
            top: 6,
            child: GestureDetector(
              onTapDown: (d) => _showSplitCellPageMenu(
                  provider, k, isEditor, d.globalPosition),
              child: Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                decoration: BoxDecoration(
                  color: Colors.black.withValues(alpha: 0.45),
                  borderRadius: BorderRadius.circular(999),
                ),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  if (isEditor) ...[
                    const Icon(Icons.edit_rounded,
                        size: 11, color: Colors.white70),
                    const SizedBox(width: 4),
                  ],
                  // Web 埋め込みセルはサイト名を出さず 🌐 ボタンだけにする
                  // (= ユーザー要望)。 押すとメニューで詳細操作。
                  if (label.isEmpty)
                    const Icon(Icons.public_rounded,
                        size: 12, color: Colors.white70)
                  else
                    ConstrainedBox(
                      constraints: const BoxConstraints(maxWidth: 160),
                      child: Text(label,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                              color: Colors.white,
                              fontSize: 11,
                              fontWeight: FontWeight.w600)),
                    ),
                  const SizedBox(width: 3),
                  const Icon(Icons.expand_more_rounded,
                      size: 12, color: Colors.white54),
                ]),
              ),
            ),
          ),
          // ── 埋め込んだファイルビューア (= ユーザー要望: 分割画面で
          //    開いたファイルはその画面に埋め込まれた状態で開く)。
          //    ペインのバッジより前面に置き、 ビューアのヘッダーに
          //    重ならないようにする。 ──
          if (embedded != null)
            Positioned.fill(
              child: _SplitCellEmbeddedPanel(
                key: ObjectKey(embedded),
                builder: embedded,
                onClose: () => _closeMapSplitCellFile(k, embedded),
              ),
            ),
        ]);
      // ── ドロップ受け口: 全体ヘッダーのボタンをドラッグして、 この
      //    ペインのミニヘッダーへコピーする (= ユーザー要望)。 ──
      //
      // 以前は編集ペイン (isEditor) を除いていたため、 「左上以外に置けない
      // 時がある」 状態だった (= ユーザー報告)。 編集ペインはタップした所へ
      // 移るので、 直前に触ったペイン = 置きたいペインが弾かれていた。
      // どのペインでも受けるようにする。
      {
        final inner0 = cellStack;
        cellStack = DragTarget<String>(
          // 全体ヘッダーからのコピー ('hdrbtn:') と、 他ペインのボタンの
          // 移動 ('panebtn:<slot>:<id>') を受ける (= ユーザー要望)。
          onWillAcceptWithDetails: (d) =>
              d.data.startsWith('hdrbtn:') || d.data.startsWith('panebtn:'),
          onAcceptWithDetails: (d) {
            String id;
            int? from;
            if (d.data.startsWith('panebtn:')) {
              final parts = d.data.split(':');
              from = int.tryParse(parts[1]);
              id = parts.sublist(2).join(':');
              if (from == k) return; // 同じペイン内は何もしない
            } else {
              id = d.data.substring(7);
            }
            setState(() {
              if (from != null) _paneHeaderButtons[from]?.remove(id);
              final list =
                  _paneHeaderButtons.putIfAbsent(k, () => <String>[]);
              if (!list.contains(id)) list.add(id);
            });
            _persistPaneHeaderButtons();
          },
          builder: (c, cand, _) =>
              Stack(fit: StackFit.expand, children: [
            inner0,
            if (cand.isNotEmpty)
              IgnorePointer(
                  child: Container(
                      color: const Color(0xFF6C63FF)
                          .withValues(alpha: 0.12))),
          ]),
        );
      }
      return Expanded(flex: flex, child: cellStack);
    }

    if (!_mapSplitQuad) {
      // 向きはユーザー設定に従う (= ユーザー要望: 上下 / 左右を選べるように)。
      final a = _mapSplitStacked ? flexTop : flexA;
      final b = _mapSplitStacked ? flexBottom : flexB;
      final panes = <Widget>[
        cell(0, flex: a),
        _mapSplitStacked ? divH() : divV(),
        cell(1, flex: b),
      ];
      return _mapSplitStacked
          ? Column(
              crossAxisAlignment: CrossAxisAlignment.stretch, children: panes)
          : Row(crossAxisAlignment: CrossAxisAlignment.stretch, children: panes);
    }
    // ── 4 分割: 2x2 (0=左上 1=右上 2=左下 3=右下) ──
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Expanded(
        flex: flexTop,
        child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [cell(0, flex: flexA), divV(), cell(1, flex: flexB)]),
      ),
      divH(),
      Expanded(
        flex: flexBottom,
        child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [cell(2, flex: flexA), divV(), cell(3, flex: flexB)]),
      ),
    ]);
  }

  /// 共同編集の参加者バッジ (= ユーザー要望: 誰が操作しているか表示)。
  /// 自分は塗り、 他の参加者はその人の色で並べる。 タップで一覧を出す。
  Widget _buildLivePeerChips(MindMapProvider provider) {
    final peers = provider.livePeers
        .where((p) => p.clientId != provider.liveClientId)
        .toList();
    Widget dot(Color c, String name, {bool me = false}) => Tooltip(
          message: me ? '$name (${provider.t('live.on')})' : name,
          child: Container(
            margin: const EdgeInsets.only(right: 3),
            width: 18,
            height: 18,
            decoration: BoxDecoration(
              color: c,
              shape: BoxShape.circle,
              border: me
                  ? Border.all(color: Colors.white, width: 1.4)
                  : Border.all(color: Colors.white24),
            ),
            alignment: Alignment.center,
            child: Text(
              name.isEmpty ? '?' : name.characters.first.toUpperCase(),
              style: const TextStyle(
                  color: Colors.white, fontSize: 9, fontWeight: FontWeight.w800),
            ),
          ),
        );
    final myName = provider.displayName.isEmpty
        ? provider.t('live.anonymous')
        : provider.displayName;
    // タップでプロフィールと参加者の一覧を出す (= ユーザー要望)。
    return InkWell(
      borderRadius: BorderRadius.circular(999),
      onTap: () => _showLiveProfileDialog(provider),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          Container(
            margin: const EdgeInsets.only(right: 5),
            width: 7,
            height: 7,
            decoration: const BoxDecoration(
                color: Color(0xFF43B97F), shape: BoxShape.circle),
          ),
          dot(Color(provider.liveMyColorRgb), myName, me: true),
          for (final p in peers.take(4)) dot(Color(p.colorRgb), p.name),
          if (peers.length > 4)
            Text('+${peers.length - 4}',
                style: const TextStyle(color: Colors.white54, fontSize: 10)),
        ]),
      ),
    );
  }

  /// 参加者バッジをタップした時のプロフィール画面 (= ユーザー要望)。
  /// 自分の名前とアイコンをその場で直せて、 参加している相手も一覧できる。
  /// 名前は 3 秒ごとの在席送信で相手にも反映される。
  void _showLiveProfileDialog(MindMapProvider provider) {
    final nameCtrl = TextEditingController(text: provider.displayName);
    showDialog<void>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx2, setD) {
        final peers = provider.livePeers
            .where((p) => p.clientId != provider.liveClientId)
            .toList();
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          scrollable: true,
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
          title: Row(children: [
            const Icon(Icons.badge_rounded, color: Color(0xFF9C93FF), size: 20),
            const SizedBox(width: 8),
            Expanded(
              child: Text(provider.t('live.profileTitle'),
                  style: const TextStyle(color: Colors.white, fontSize: 15)),
            ),
          ]),
          content: SizedBox(
            width: 340,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // ── 自分のプロフィール ──
                Row(children: [
                  // アイコンをタップで既存のアバター選択を開く。
                  InkWell(
                    borderRadius: BorderRadius.circular(999),
                    onTap: () async {
                      _showAvatarPickerDialog(dctx2, provider);
                    },
                    child: Stack(clipBehavior: Clip.none, children: [
                      _userAvatarVisual(provider, size: 52),
                      Positioned(
                        right: -2,
                        bottom: -2,
                        child: Container(
                          padding: const EdgeInsets.all(3),
                          decoration: const BoxDecoration(
                              color: Color(0xFF2B2B3D),
                              shape: BoxShape.circle),
                          child: const Icon(Icons.edit_rounded,
                              size: 11, color: Colors.white70),
                        ),
                      ),
                    ]),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: TextField(
                      controller: nameCtrl,
                      maxLength: 24,
                      style:
                          const TextStyle(color: Colors.white, fontSize: 13.5),
                      decoration: InputDecoration(
                        labelText: provider.t('live.profileName'),
                        labelStyle: const TextStyle(
                            color: Colors.white54, fontSize: 12),
                        counterText: '',
                        isDense: true,
                        enabledBorder: const UnderlineInputBorder(
                            borderSide: BorderSide(color: Colors.white24)),
                        focusedBorder: const UnderlineInputBorder(
                            borderSide: BorderSide(color: Color(0xFF9C93FF))),
                      ),
                    ),
                  ),
                ]),
                const SizedBox(height: 6),
                Text(provider.t('live.profileHint'),
                    style: const TextStyle(
                        color: Colors.white38, fontSize: 10.5, height: 1.4)),
                // ── 参加者一覧 (セッション中のみ) ──
                if (provider.liveActive) ...[
                  const SizedBox(height: 12),
                  const Divider(color: Colors.white12, height: 1),
                  const SizedBox(height: 10),
                  Text(provider.t('live.participants'),
                      style: const TextStyle(
                          color: Colors.white54,
                          fontSize: 11,
                          fontWeight: FontWeight.w700)),
                  const SizedBox(height: 6),
                  if (peers.isEmpty)
                    Text(provider.t('live.onlyYou'),
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 11.5))
                  else
                    for (final p in peers)
                      Padding(
                        padding: const EdgeInsets.symmetric(vertical: 3),
                        child: Row(children: [
                          Container(
                            width: 16,
                            height: 16,
                            decoration: BoxDecoration(
                              color: Color(p.colorRgb),
                              shape: BoxShape.circle,
                              border: Border.all(color: Colors.white24),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: Text(
                                p.name.isEmpty
                                    ? provider.t('live.anonymous')
                                    : p.name,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                    color: Colors.white, fontSize: 12.5)),
                          ),
                          if ((p.lockNodeId ?? '').isNotEmpty)
                            Text(provider.t('live.editingNow'),
                                style: const TextStyle(
                                    color: Color(0xFF9CCC65), fontSize: 10.5)),
                        ]),
                      ),
                ],
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx2).pop(),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6C63FF),
                  foregroundColor: Colors.white),
              onPressed: () async {
                final name = nameCtrl.text.trim();
                if (name.isNotEmpty && name != provider.displayName) {
                  await provider.setDisplayName(name);
                }
                if (dctx2.mounted) Navigator.of(dctx2).pop();
              },
              child: Text(provider.t('btn.save')),
            ),
          ],
        );
      }),
    ).then((_) => nameCtrl.dispose());
  }

  /// 「動作設定」 の項目一覧。 設定シート (モバイル) とヘッダーのボタンから
  /// 開くダイアログ (デスクトップ) の両方で使う。
  /// [ctx] は画面側の context (別のダイアログを開く用)、 [sheetCtx] は自分を
  /// 包んでいるシート/ダイアログの context (閉じる用)。
  /// 動作設定の中の小見出し (= ユーザー要望: ボタン式の項目とそうでない
  /// 項目を分けてまとめる)。
  Widget _behaviorSectionLabel(String text) => Padding(
        padding: const EdgeInsets.fromLTRB(4, 14, 4, 6),
        child: Row(children: [
          Text(text,
              style: const TextStyle(
                  color: Colors.white38,
                  fontSize: 11,
                  fontWeight: FontWeight.w700,
                  letterSpacing: 0.6)),
          const SizedBox(width: 8),
          const Expanded(child: Divider(color: Colors.white12, height: 1)),
        ]),
      );

  List<Widget> _behaviorSettingsChildren({
    required MindMapProvider provider,
    required BuildContext ctx,
    required BuildContext sheetCtx,
    required void Function(VoidCallback) setS,
  }) {
    return [
            // ── 切り替え (ON/OFF) の項目 ── (= ユーザー要望: ボタン式と分ける)
            _behaviorSectionLabel(provider.t('settings.groupToggles')),

            // ── トグル: 配置候補 ──
            _settingsToggleTile(
              icon: provider.snapEnabled
                  ? Icons.grid_on_rounded
                  : Icons.grid_off_rounded,
              color: provider.snapEnabled
                  ? const Color(0xFF4FC3F7)
                  : Colors.white54,
              title: provider.t('menu.snap'),
              helpKey: 'help.snap',
              value: provider.snapEnabled,
              onChanged: (v) {
                provider.setSnapEnabled(v);
                setS(() {});
              },
            ),

            // ── トグル: Esc キーで閲覧画面を閉じる (= ユーザー要望: Excel /
            //    Word / YouTube などが Esc で閉じてしまうのを止められるように) ──
            _settingsToggleTile(
              icon: provider.closeViewerWithEsc
                  ? Icons.keyboard_return_rounded
                  : Icons.keyboard_hide_rounded,
              color: provider.closeViewerWithEsc
                  ? const Color(0xFFFFB347)
                  : Colors.white54,
              title: provider.t('menu.escClose'),
              helpKey: 'help.escClose',
              value: provider.closeViewerWithEsc,
              onChanged: (v) {
                provider.setCloseViewerWithEsc(v);
                setS(() {});
              },
            ),

            // ── 音楽サイトのバックグラウンド再生のトグルはここから削除
            //    (= ユーザー要望: 動作設定ではなく、 開いた項目のヘッダーで
            //    切り替える)。 実体は _DockedGoogleSearchPane のヘッダーに
            //    移した (音楽サイトを開いている時だけ出る)。 ──

            // ── トグル: 埋め込み動画で関連動画等を隠す ──
            // ON (既定): YouTube 視聴時に関連動画・コメント・
            //   ヘッダー等を CSS で隠す視聴専用モード。
            // OFF: 通常の YouTube UI のまま (関連動画も表示)。
            // (= ユーザー要望: 非表示にするかの設定項目)
            // ON = 関連動画を表示する (= ユーザー要望: 言い回しを
            //   「〜する」 で統一)。 中の設定は「隠すか」 なので反転する。
            _settingsToggleTile(
              icon: provider.hideEmbedRelated
                  ? Icons.visibility_off_rounded
                  : Icons.visibility_rounded,
              color: provider.hideEmbedRelated
                  ? Colors.white54
                  : const Color(0xFFBA68C8),
              title:
                  provider.t('menu.hideEmbedRelated'),
              helpKey: 'help.hideEmbedRelated',
              value: !provider.hideEmbedRelated,
              onChanged: (v) {
                provider.setHideEmbedRelated(!v);
                setS(() {});
              },
            ),

            // ── トグル: フローティングを複数開けるようにする ──
            //   既定は 1 つだけ (= ユーザー要望: タップのたびに窓が増える)。
            _settingsToggleTile(
              icon: provider.allowMultipleFloatingWindows
                  ? Icons.filter_none_rounded
                  : Icons.crop_square_rounded,
              color: provider.allowMultipleFloatingWindows
                  ? const Color(0xFF4FC3F7)
                  : Colors.white54,
              title: provider.t('menu.allowMultiFloat'),
              helpKey: 'help.allowMultiFloat',
              value: provider.allowMultipleFloatingWindows,
              onChanged: (v) {
                provider.setAllowMultipleFloatingWindows(v);
                setS(() {});
              },
            ),

            // ── トグル: 連番オートフィル ──
            // 「第一章」 入力 → 同じ親の空兄弟ノードに「第二章」
            // 「第三章」 を一括サジェスト。
            _settingsToggleTile(
              icon: provider.autofillSequenceEnabled
                  ? Icons.format_list_numbered_rounded
                  : Icons
                      .format_list_bulleted_rounded,
              color: provider.autofillSequenceEnabled
                  ? const Color(0xFFFFB347)
                  : Colors.white54,
              title:
                  provider.t('menu.autofillSequence'),
              helpKey: 'help.autofillSequence',
              value: provider.autofillSequenceEnabled,
              onChanged: (v) {
                provider
                    .setAutofillSequenceEnabled(v);
                setS(() {});
              },
            ),

            // ── トグル: リンク・PDFをアプリ内で開く ──
            // true: WebView ベースのアプリ内ビューア
            //   (デスクトップは webview_windows / モバイルと
            //    macOS は flutter_inappwebview)
            // false: 既存挙動どおり OS の規定アプリで開く
            // PDF は Android 標準 WebView では描画できないため、
            // Android では true でも OS のビューアにフォールバック。
            _settingsToggleTile(
              icon: provider.openLinksInApp
                  ? Icons.open_in_browser_rounded
                  : Icons.open_in_new_rounded,
              color: provider.openLinksInApp
                  ? const Color(0xFF4FC3F7)
                  : Colors.white54,
              title: provider.t('set.openInApp'),
              helpKey: 'help.openInApp',
              value: provider.openLinksInApp,
              onChanged: (v) {
                provider.setOpenLinksInApp(v);
                setS(() {});
              },
            ),


            // ── トグル: 高リフレッシュレート (= ユーザー要望:
            //    120Hz / 144Hz 等にも対応) ──
            // Android のみ効く (Windows は OS 側が
            //   モニターのレートで描画するため不要)。
            if (!kIsWeb && Platform.isAndroid)
              _settingsToggleTile(
                icon: provider.highRefreshRate
                    ? Icons.speed_rounded
                    : Icons.speed_outlined,
                color: provider.highRefreshRate
                    ? const Color(0xFF7FD8A0)
                    : Colors.white54,
                title: provider.t('refresh.setting'),
                helpKey: 'help.highRefreshRate',
                value: provider.highRefreshRate,
                onChanged: (v) async {
                  await provider
                      .setHighRefreshRate(v);
                  await applyPreferredDisplayMode(
                      high: v);
                  setS(() {});
                },
              ),


            // ── トグル: 全体図 (ミニマップ) を出さない (= ユーザー要望) ──
            // ON = 全体図を表示する (= ユーザー要望: 「〜する」 で統一)。
            //   中の設定は「出さないか」 なので反転する。
            _settingsToggleTile(
              icon: provider.hideMiniMap
                  ? Icons.map_outlined
                  : Icons.map_rounded,
              color: provider.hideMiniMap
                  ? Colors.white54
                  : const Color(0xFF9FB6C4),
              title: provider.t('settings.hideMiniMap'),
              helpKey: 'help.hideMiniMap',
              value: !provider.hideMiniMap,
              onChanged: (v) {
                provider.setHideMiniMap(!v);
                setS(() {});
              },
            ),

            // ── トグル: 動画のメモ / AI 欄を横に並べる (= ユーザー要望:
            //    PDF のように横に配置するモードを設定で選べるように) ──
            _settingsToggleTile(
              icon: provider.videoPanelSideBySide
                  ? Icons.vertical_split_rounded
                  : Icons.picture_in_picture_alt_rounded,
              color: provider.videoPanelSideBySide
                  ? const Color(0xFF80CBC4)
                  : Colors.white54,
              title: provider.t('settings.videoPanelSide'),
              helpKey: 'help.videoPanelSide',
              value: provider.videoPanelSideBySide,
              onChanged: (v) {
                provider.setVideoPanelSideBySide(v);
                setS(() {});
              },
            ),

            // ── トグル: ノード生成直後にノード内で直接入力 ──
            _settingsToggleTile(
              icon:
                  provider.promptForTitleOnNodeCreate
                      ? Icons.edit_note_rounded
                      : Icons.edit_off_rounded,
              color:
                  provider.promptForTitleOnNodeCreate
                      ? const Color(0xFFFFC107)
                      : Colors.white54,
              title: provider.t(
                  'settings.promptForTitleOnNodeCreate'),
              helpKey: 'help.promptForTitleOnNodeCreate',
              value:
                  provider.promptForTitleOnNodeCreate,
              onChanged: (v) {
                provider
                    .setPromptForTitleOnNodeCreate(v);
                setS(() {});
              },
            ),

            // ── ここから下は「はじめは切ってある」 もの ──
            //    (= ユーザー要望: 見栄えのため、 既定で入っているものと
            //     切ってあるものをまとめて並べる)。
            // ── トグル: 「アプリで開く」 を別ウィンドウで開くか (Windows のみ。
            //    = ユーザー要望: 既に起動しているならその画面で開き、 別アプリを
            //    立ち上げるかは設定で選べるように) ──
            if (!kIsWeb && Platform.isWindows)
              _settingsToggleTile(
                icon: provider.openWithNewInstance
                    ? Icons.open_in_new_rounded
                    : Icons.tab_rounded,
                color: provider.openWithNewInstance
                    ? const Color(0xFF4FC3F7)
                    : Colors.white54,
                title: provider.t('menu.openWithNewInstance'),
                helpKey: 'help.openWithNewInstance',
                value: provider.openWithNewInstance,
                onChanged: (v) {
                  provider.setOpenWithNewInstance(v);
                  setS(() {});
                },
              ),

            // ── トグル: 視聴済み自動削除 ──
            _settingsToggleTile(
              icon: provider.autoDeleteWatched
                  ? Icons.auto_delete_rounded
                  : Icons.auto_delete_outlined,
              color: provider.autoDeleteWatched
                  ? const Color(0xFF43B97F)
                  : Colors.white54,
              title: provider.t('menu.autoDelete'),
              helpKey: 'help.autoDelete',
              value: provider.autoDeleteWatched,
              onChanged: (v) {
                provider.setAutoDeleteWatched(v);
                setS(() {});
              },
            ),

            // ── トグル: メモ欄を閉じる は廃止 ──
            // ユーザー要望により削除。 メモ表示は常にデフォルト
            // (= 折りたたまない) で運用する。 関連の provider 値
            // (memoCollapsedGlobal) は内部 state として残置するが、
            // UI からの切替手段は無くした。


            // ── 押して設定するボタン式の項目 ── (= ユーザー要望)
            _behaviorSectionLabel(provider.t('settings.groupDialogs')),
            // ── どこで開くか (= ユーザー要望: 今の画面で開くか、 新しく
            //    アプリを立ち上げて開くかを選べるように) ──
            //    デスクトップ専用 (モバイルは常に今の画面)。
            if (_isDesktop)
              _settingsTile(
                icon: Icons.open_in_new_rounded,
                color: const Color(0xFF8D86FF),
                title: provider.t('openTarget.title'),
                subtitle: provider.t(provider.openTarget == 'window'
                    ? 'openTarget.window'
                    : 'openTarget.same'),
                onTap: () async {
                  final v = await showDialog<String>(
                    context: ctx,
                    builder: (dctx) => SimpleDialog(
                      backgroundColor: const Color(0xFF1E1E32),
                      shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(14)),
                      title: Text(provider.t('openTarget.title'),
                          style: const TextStyle(
                              color: Colors.white, fontSize: 15)),
                      children: [
                        for (final e in const [
                          ('same', Icons.open_in_full_rounded),
                          ('window', Icons.launch_rounded),
                        ])
                          ListTile(
                            leading: Icon(e.$2,
                                color: provider.openTarget == e.$1
                                    ? const Color(0xFF8D86FF)
                                    : Colors.white54,
                                size: 20),
                            title: Text(provider.t('openTarget.${e.$1}'),
                                style: const TextStyle(
                                    color: Colors.white, fontSize: 13)),
                            subtitle: Text(
                                provider.t('openTarget.${e.$1}Desc'),
                                style: const TextStyle(
                                    color: Colors.white54, fontSize: 11)),
                            onTap: () => Navigator.pop(dctx, e.$1),
                          ),
                      ],
                    ),
                  );
                  if (v != null) await provider.setOpenTarget(v);
                  setS(() {});
                },
              ),

            // ── 要素から検索を立ち上げた時の開き方 (= ユーザー要望: 要素から
            //    google 検索や youtube 検索を立ち上げた時の挙動を設定できる
            //    ように)。 Google 検索と YouTube 検索の両方に効く。 ──
            _settingsTile(
              icon: Icons.travel_explore_rounded,
              color: const Color(0xFF4FC3F7),
              title: provider.t('nodeSearchOpen.title'),
              subtitle: provider
                  .t('nodeSearchOpen.${_nodeSearchMode(provider)}'),
              onTap: () async {
                final v = await showDialog<String>(
                  context: ctx,
                  builder: (dctx) => SimpleDialog(
                    backgroundColor: const Color(0xFF1E1E32),
                    shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(14)),
                    title: Text(provider.t('nodeSearchOpen.title'),
                        style: const TextStyle(
                            color: Colors.white, fontSize: 15)),
                    children: [
                      for (final e in const [
                        ('external', Icons.launch_rounded),
                        ('floating', Icons.picture_in_picture_alt_rounded),
                        ('full', Icons.open_in_full_rounded),
                      ])
                        // スマホは外の窓を作れないので出さない。
                        if (_isDesktop || e.$1 != 'external')
                          ListTile(
                            leading: Icon(e.$2,
                                color: provider.nodeSearchOpenMode == e.$1
                                    ? const Color(0xFF4FC3F7)
                                    : Colors.white54,
                                size: 20),
                            title: Text(provider.t('nodeSearchOpen.${e.$1}'),
                                style: const TextStyle(
                                    color: Colors.white, fontSize: 13)),
                            subtitle: Text(
                                provider.t('nodeSearchOpen.${e.$1}Desc'),
                                style: const TextStyle(
                                    color: Colors.white54, fontSize: 11)),
                            onTap: () => Navigator.pop(dctx, e.$1),
                          ),
                    ],
                  ),
                );
                if (v != null) await provider.setNodeSearchOpenMode(v);
                setS(() {});
              },
            ),

            if (_isDesktop)
              _settingsTile(
                icon: Icons.call_merge_rounded,
                color: const Color(0xFF8D86FF),
                title: provider
                    .t('header.barCollisionBehavior'),
                subtitle: provider.t(
                    'header.barCollisionMode.${provider.desktopHeaderBarCollisionMode}'),
                onTap: () async {
                  await _showDesktopHeaderBarCollisionModePicker(
                      ctx, provider);
                  setS(() {});
                },
              ),

            // ── タイル: 画像貼り付けスケール (%) ──
            // 0 = OFF、 1〜100 = 画像サイズ × (% / 100)。
            // タップで 0〜100% スライダーダイアログを開く。
            _settingsTile(
              icon:
                  provider.pasteImageScalePercent > 0
                      ? Icons.image_rounded
                      : Icons.image_outlined,
              color:
                  provider.pasteImageScalePercent > 0
                      ? const Color(0xFF7FD8A0)
                      : Colors.white54,
              title: provider
                  .t('settings.pasteImageScale'),
              subtitle: provider
                          .pasteImageScalePercent >
                      0
                  ? '${provider.pasteImageScalePercent}%'
                  : provider.t('settings.off'),
              onTap: () async {
                final picked =
                    await _showImageScalePicker(
                        provider);
                if (picked != null) {
                  await provider
                      .setPasteImageScalePercent(
                          picked);
                  setS(() {});
                }
              },
            ),

            // ── クイック子要素生成数 ──
            // タップで小さなダイアログを開いて 1〜30 の数値入力。
            // ラベルはデスクトップでは "(Ctrl+Shift+A)" 付きで
            // ショートカットを案内するが、モバイルでは
            // ショートカットが押せないので付けない。
            _settingsTile(
              icon: Icons.account_tree_rounded,
              color: const Color(0xFF43B97F),
              title: provider.t(_isDesktop
                  ? 'menu.quickAddChildrenCount'
                  : 'menu.quickAddChildrenCountMobile'),
              subtitle: provider
                  .t('quickAdd.subtitle')
                  .replaceAll(
                      '{n}',
                      provider.quickAddChildrenCount
                          .toString()),
              onTap: () async {
                await _showQuickAddChildrenCountDialog(
                    ctx, provider);
                setS(() {});
              },
            ),
    ];
  }

  /// 「動作設定」 を開く (= ユーザー要望: 設定項目の中ではなくヘッダー右上の
  /// 画面分割ボタンの所から開く)。 デスクトップは専用ダイアログ、 モバイルは
  /// 従来どおり設定シートの該当セクションを展開して表示する。 Ctrl+J も同じ。
  void _openBehaviorSettings() {
    if (!mounted) return;
    if (!_isDesktop) {
      if (_settingsSheetOpen) {
        Navigator.of(context, rootNavigator: true).maybePop();
        _settingsSheetOpen = false;
        return;
      }
      _settingsSheetOpen = false;
      _showSettingsSheet(context, context.read<MindMapProvider>(),
          expandBehavior: true);
      return;
    }
    // 開いている時にもう一度押したら閉じる (トグル)。
    if (_behaviorDialogOpen) {
      Navigator.of(context, rootNavigator: true).maybePop();
      return;
    }
    final provider = context.read<MindMapProvider>();
    final screenCtx = context;
    _behaviorDialogOpen = true;
    showDialog<void>(
      context: context,
      barrierColor: Colors.black45,
      builder: (dctx) => StatefulBuilder(
        builder: (bctx, setS) => Dialog(
          backgroundColor: const Color(0xFF1E1E32),
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
          child: ConstrainedBox(
            constraints: BoxConstraints(
              maxWidth: 520,
              maxHeight: MediaQuery.of(bctx).size.height * 0.8,
            ),
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 14, 8, 10),
                child: Row(children: [
                  const Icon(Icons.settings_suggest_rounded,
                      color: Color(0xFF7FD8A0), size: 20),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(provider.t('menu.behaviorSettings'),
                        style: const TextStyle(
                            color: Colors.white,
                            fontSize: 15,
                            fontWeight: FontWeight.w700)),
                  ),
                  IconButton(
                    tooltip: provider.t('btn.close'),
                    icon: const Icon(Icons.close_rounded,
                        color: Colors.white54, size: 18),
                    onPressed: () => Navigator.pop(dctx),
                  ),
                ]),
              ),
              const Divider(color: Colors.white12, height: 1),
              Flexible(
                child: SingleChildScrollView(
                  padding: const EdgeInsets.symmetric(vertical: 6),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: _behaviorSettingsChildren(
                      provider: provider,
                      ctx: screenCtx,
                      sheetCtx: dctx,
                      setS: setS,
                    ),
                  ),
                ),
              ),
            ]),
          ),
        ),
      ),
    ).whenComplete(() {
      _behaviorDialogOpen = false;
    });
  }

  /// 動作設定ダイアログ (デスクトップ) が開いているか。 同じボタンをもう一度
  /// 押した時に閉じる (トグル) ために持つ。
  bool _behaviorDialogOpen = false;

  /// マップ分割のモード切替ボタン (4 分割 / 左右 2 分割 / 上下 2 分割)。
  ///
  /// 分割していない時から 3 つとも並べる (= ユーザー要望: 最初のマップの
  /// 時点で 3 つ配置されている状態に)。 4 分割中も 2 分割のボタンは残す。
  /// 今のモードをもう一度押すと分割を閉じる。
  Widget _buildMapSplitModeButtons(MindMapProvider provider) {
    bool isActive(int panes, bool stacked) {
      if (!_mapSplitOpen) return false;
      if (panes == 4) return _mapSplitQuad;
      return !_mapSplitQuad && _mapSplitStacked == stacked;
    }

    Widget btn(int panes, bool stacked, String tooltipKey) {
      final active = isActive(panes, stacked);
      return IconButton(
        padding: EdgeInsets.zero,
        constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
        tooltip: provider.t(tooltipKey),
        icon: _SplitLayoutIcon(
          panes: panes,
          stacked: stacked,
          size: 16,
          color: active ? const Color(0xFF4FC3F7) : Colors.white70,
        ),
        onPressed: () => _applyMapSplitMode(panes: panes, stacked: stacked),
      );
    }

    return Row(mainAxisSize: MainAxisSize.min, children: [
      // モバイルは画面が小さく 4 分割は実用的でないので出さない
      // (= ユーザー要望)。
      if (_isDesktop) btn(4, false, 'map.splitQuad'),
      btn(2, false, 'map.splitModeLeftRight'),
      btn(2, true, 'map.splitModeTopBottom'),
    ]);
  }

  /// 分割レイアウトを [panes] / [stacked] のモードに切り替える。 既にその
  /// モードなら分割を閉じる (= トグル)。
  Future<void> _applyMapSplitMode({
    required int panes,
    required bool stacked,
  }) async {
    final quad = panes == 4 && _isDesktop;
    final already = _mapSplitOpen &&
        (quad
            ? _mapSplitQuad
            : (!_mapSplitQuad && _mapSplitStacked == stacked));
    if (already) {
      _toggleMapSplitFromHeader(); // 同じボタンをもう一度 → 閉じる
      return;
    }
    setState(() {
      _mapSplitQuad = quad;
      if (!quad) {
        _mapSplitStacked = stacked;
        // 4→2 に戻した時、 編集セルが下段なら上段へ寄せる。
        if (_mapSplitEditorSlot > 1) _mapSplitEditorSlot = 0;
      }
    });
    // 次回開く時のために記憶する。
    await _persistMapSplitQuad();
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool('mapSplitStacked', _mapSplitStacked);
    } catch (_) {}
    if (!mounted) return;
    if (!_mapSplitOpen) {
      // _toggleMapSplitFromHeader は _mapSplitQuadPref から quad を復元する
      // ので、 上で記憶した後に呼ぶ必要がある。
      _toggleMapSplitFromHeader();
    }
  }

  /// 分割用のページ表示名 (種類の絵文字付き)。 マインドマップにも
  /// アイコンを付ける (= ユーザー要望: ギャラリーだけアイコンがあって
  /// マップに無いのが気になる)。
  String _splitPageLabel(MindMapPage p) => p.pageType == 'bookshelf'
      ? '📚 ${p.name}'
      : p.pageType == 'paint'
          ? '🖌 ${p.name}'
          : '🗺 ${p.name}';

  /// セル左上のページ名バッジをタップ → そのセルに表示するページを選ぶ
  /// (= ユーザー要望: ページ名をクリックしたら別のページと入れ替えられる)。
  Future<void> _showSplitCellPageMenu(MindMapProvider provider, int slot,
      bool isEditor, Offset globalPos) async {
    final overlayBox =
        Overlay.of(context).context.findRenderObject() as RenderBox?;
    final size = overlayBox?.size ?? MediaQuery.of(context).size;
    final currentId =
        isEditor ? provider.currentPage.id : _mapSplitCells[slot];
    final hasWeb = !isEditor && _mapSplitCellWeb[slot] != null;
    final sel = await showMenu<String>(
      context: context,
      color: const Color(0xFF1E1E32),
      position: RelativeRect.fromLTRB(globalPos.dx, globalPos.dy,
          size.width - globalPos.dx, size.height - globalPos.dy),
      items: [
        // ── 何かを埋め込んでいる時は「窓に戻す / 閉じる」 だけにする
        //    (= ユーザー要望: 選択肢が多いと紛らわしい) ──
        //    ページの一覧や追加/削除はここでは出さない。 まず埋め込みを
        //    閉じれば、 いつもどおりの一覧が出る。
        if (hasWeb) ...[
          PopupMenuItem(
            value: '__floatWeb__',
            child: Text('↗ ${provider.t('map.floatEmbed')}',
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ),
          PopupMenuItem(
            value: '__closeWeb__',
            child: Text('❌ ${provider.t('map.closeEmbed')}',
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ),
        ] else ...[
          for (final p in provider.pages)
            if (_splitEligiblePage(p))
              PopupMenuItem(
                value: p.id,
                enabled: p.id != currentId,
                child: Text(_splitPageLabel(p),
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                        color: p.id == currentId
                            ? Colors.white38
                            : Colors.white,
                        fontSize: 13)),
              ),
          // ── ペインのボタン操作メニューは廃止 (= ユーザー要望: ボタンを
          //    そのままドラッグで戻したり消したりできるように)。 ボタンは
          //    Draggable なので、 他のペインへドロップで移動、 ペインの外
          //    (ヘッダーやキャンバス) へドロップで削除される。 ──
          // ── ページ追加 / 削除 (ヘッダーのメニューを廃止した分をここへ
          //    集約 = ユーザー要望) ──
          PopupMenuItem(
            value: '__addPage__',
            child: Text('＋ ${provider.t('menu.addPage')}',
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(color: Color(0xFF8C7CFF), fontSize: 13)),
          ),
          PopupMenuItem(
            value: '__deletePage__',
            child: Text('🗑 ${provider.t('map.deletePagePick')}',
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(color: Colors.redAccent, fontSize: 13)),
          ),
        ],
        // ── 分割そのものを閉じる (= ユーザー要望: ページ名をクリックした
        //    時に分割画面を閉じる項目も出るように)。 どのセルからでも
        //    選べるよう、 埋め込みの有無に関わらず常に出す。 ──
        PopupMenuItem(
          value: '__closeSplit__',
          child: Text('✕ ${provider.t('cmd.closeSplit')}',
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(color: Color(0xFFFFB74D), fontSize: 13)),
        ),
      ],
    );
    if (sel == null || !mounted) return;
    if (sel == '__closeSplit__') {
      _closeMapSplit();
      return;
    }
    if (sel == '__addPage__') {
      // 「＋新規追加」 を押したセル自身に新ページを出す (= ユーザー報告:
      //   4 分割で追加すると左上のページが切り替わってしまう)。
      //   以前は編集セルから押すと _primaryViewerSlot() (= 左上) に入れて
      //   いたので、 押したセルではなく左上が切り替わっていた。
      _addPageIntoSplitPane(provider, slot, intoEditor: isEditor);
      return;
    }
    if (sel == '__deletePage__') {
      _showDeleteSplitPagePicker(provider);
      return;
    }
    if (sel == '__closeWeb__') {
      setState(() => _mapSplitCellWeb.remove(slot));
      return;
    }
    if (sel == '__floatWeb__') {
      // 埋め込みをフローティング窓に戻す (= ユーザー要望: 再度欄を
      // 浮かび上がらせられる項目)。 窓は埋め込んでいたセルの上から始める
      // (= ユーザー要望: 左上スタートではなく)。
      //
      // ★ 見ていたページをそのまま浮かせる (= 最初に開いた URL ではなく)。
      // ★ 古い WebView を捨てたその場で新しい WebView を作ると初期化に
      //   失敗することがある (= ユーザー報告: 窓を浮かび上がらせると
      //   「WebView を初期化できませんでした」)。 片付けが終わるのを待って
      //   から開く。
      final url = _mapSplitCellWebCur[slot] ?? _mapSplitCellWeb[slot];
      setState(() {
        _mapSplitCellWeb.remove(slot);
        _mapSplitCellWebCur.remove(slot);
      });
      if (url != null) {
        Future.delayed(const Duration(milliseconds: 300), () {
          if (mounted) _showFloatingVideoWindow(url, slot: slot);
        });
      }
      return;
    }
    // ── そのセルに被さっている物を先にどける (= ユーザー報告: 分割で
    //    ショートカット一覧などを開いた後に別のマップを選んでも、 一覧が
    //    前面に残ったままで画面が切り替わらない)。 ──
    setState(() {
      _mapSplitCellTool.remove(slot);
      _mapSplitCellFile.remove(slot);
      _mapSplitCellWeb.remove(slot);
      _mapSplitCellWebCur.remove(slot);
      _syncNarrowPaneRatio();
    });
    if (isEditor) {
      final idx = provider.pages.indexWhere((p) => p.id == sel);
      if (idx >= 0) provider.switchPage(idx);
    } else {
      setState(() {
        _mapSplitCells[slot] = sel;
      });
    }
  }

  /// ペインに表示中のページを確認付きで削除する (= ユーザー要望)。
  Future<void> _confirmDeleteSplitPage(
      MindMapProvider provider, MindMapPage page) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('menu.delete'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Text(
            provider
                .t('page.deleteConfirm')
                .replaceFirst('{name}', page.name),
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dctx).pop(false),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          TextButton(
            onPressed: () => Navigator.of(dctx).pop(true),
            child: Text(provider.t('menu.delete'),
                style: const TextStyle(color: Colors.redAccent)),
          ),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    final idx = provider.pages.indexWhere((p) => p.id == page.id);
    if (idx < 0) return;
    provider.deletePage(idx);
    setState(() {
      for (var i = 0; i < _mapSplitCells.length; i++) {
        if (_mapSplitCells[i] == page.id) _mapSplitCells[i] = null;
      }
    });
  }

  /// 「ページを選択して削除」 (= ユーザー要望: 削除も一覧の中の項目に)。
  /// 全ページから選んで確認付きで削除する。
  Future<void> _showDeleteSplitPagePicker(MindMapProvider provider) async {
    final sel = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('map.deletePagePick'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: SizedBox(
          width: 300,
          height: 340,
          child: ListView(shrinkWrap: true, children: [
            for (final p in provider.pages)
              ListTile(
                dense: true,
                title: Text(_splitPageLabel(p),
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: Colors.white, fontSize: 13)),
                trailing: const Icon(Icons.delete_outline_rounded,
                    size: 16, color: Colors.redAccent),
                onTap: () => Navigator.of(dctx).pop(p.id),
              ),
          ]),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dctx).pop(),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
        ],
      ),
    );
    if (sel == null || !mounted) return;
    final idx = provider.pages.indexWhere((p) => p.id == sel);
    if (idx < 0) return;
    await _confirmDeleteSplitPage(provider, provider.pages[idx]);
  }

  /// 新規ページを作成して分割ペイン (セル [slot]) で開く (= ユーザー要望)。
  /// ページの種類 (マインドマップ / ギャラリー / フリーノート) を選べる
  /// (= ユーザー要望: 種類の選択ができるように)。 編集側のページは変えない。
  /// [slot] に新しいページを作って表示する。
  /// [intoEditor] true の時は編集セル自身への追加。 新ページをそのまま
  /// 編集対象 (currentPage) にして、 その編集セルに出す。
  /// false の時は非編集セルへの追加。 編集側は元のページへ戻し、
  /// 新ページはそのセルにだけ表示する。
  Future<void> _addPageIntoSplitPane(MindMapProvider provider, int slot,
      {bool intoEditor = false}) async {
    // ── 種類の選択 ──
    // クリックした場所の近くに出す (= ユーザー要望: 画面中央ではなく)。
    final kind = await _showNearDialogMain<String>(
      width: 300,
      height: 260,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('menu.addPage'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          for (final e in [
            ('normal', Icons.account_tree_rounded, 'pageKind.map',
                const Color(0xFF6C63FF)),
            ('bookshelf', Icons.shelves, 'pageKind.gallery',
                const Color(0xFFFF7043)),
            ('paint', Icons.brush_rounded, 'pageKind.paint',
                const Color(0xFFEC407A)),
            // Markdown / 図 (Mermaid) ページ (= ユーザー要望)。
            ('markdown', Icons.polyline_rounded, 'drawer.newMarkdownPage',
                const Color(0xFF5FD3B2)),
          ])
            ListTile(
              dense: true,
              leading: Icon(e.$2, color: e.$4, size: 20),
              title: Text(provider.t(e.$3),
                  style: const TextStyle(color: Colors.white, fontSize: 13)),
              onTap: () => Navigator.of(dctx).pop(e.$1),
            ),
        ]),
      ),
    );
    if (kind == null || !mounted) return;
    if (!provider.canCreatePageType(kind)) {
      _showPaywallDialog(provider,
          bodyOverride: kind == 'paint'
              ? provider.t('paywall.proRequiredNote')
              : null);
      return;
    }
    final keepIdx = provider.currentPageIndex;
    final folderId = _targetFolderForNewPage(provider);
    switch (kind) {
      case 'bookshelf':
        provider.addBookshelfPage(name: null, folderId: folderId);
        break;
      case 'paint':
        provider.addPaintPage(name: null, folderId: folderId);
        break;
      // Markdown / 図 (Mermaid) ページ (= ユーザー要望)。
      case 'markdown':
        provider.addMarkdownPage(name: null, folderId: folderId);
        break;
      default:
        provider.addPage(name: null, folderId: folderId);
    }
    final newId = provider.pages.last.id;
    if (intoEditor) {
      // 編集セルへの追加: 新ページを編集対象のまま、 押したセル (= 編集
      //   セル) に出す。 addPage が既に currentPage を新ページにしている。
      setState(() {
        _mapSplitEditorSlot = slot;
        _mapSplitCells[slot] = newId;
      });
    } else {
      // 非編集セルへの追加: 編集側を元のページへ戻し、 新ページはその
      //   セルにだけ表示する。
      provider.switchPage(keepIdx);
      setState(() => _mapSplitCells[slot] = newId);
    }
  }

  // ── 分割ペイン (非アクティブ側) のギャラリー行/列ドラッグ ──
  // = ユーザー要望: アクティブでも非アクティブでも掴みの挙動を変えない。
  // 掴んでいる間はこのペインの中だけで完結させ (ページを切り替えると
  // ウィジェットが作り直されてドラッグが途切れるため)、 指を離した時に
  // 「そのページを編集側にしてから移動」 を実行する。
  int? _paneShelfRowDragFrom;
  int? _paneShelfColDragFrom;
  Offset? _paneShelfDragPos;

  /// [rects] (行/列の帯) のうち [v] に最も近い番号。
  int _nearestPaneLine(List<Rect> rects, double v, {required bool vertical}) {
    var best = 0;
    var bestD = double.infinity;
    for (var i = 0; i < rects.length; i++) {
      final c = vertical ? rects[i].center.dy : rects[i].center.dx;
      final d = (c - v).abs();
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    return best;
  }

  /// 分割ペインのギャラリー行/列グリップ。
  /// 編集側の掴み (_shelfHandleVisual) と見た目・掴み心地をそろえる
  /// (= ユーザー要望: 非アクティブ時に表示や挙動が変わるのはおかしい)。
  Widget _paneShelfHandleChip(
    MindMapProvider provider,
    MindMapPage page,
    int slot,
    int index, {
    required bool vertical,
    required List<Rect> lineRects,
  }) {
    final dragging = vertical
        ? _paneShelfRowDragFrom == index
        : _paneShelfColDragFrom == index;
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onPanStart: (d) {
        setState(() {
          if (vertical) {
            _paneShelfRowDragFrom = index;
          } else {
            _paneShelfColDragFrom = index;
          }
          _paneShelfDragPos = lineRects[index].center;
        });
      },
      onPanUpdate: (d) {
        // ペイン内のキャンバス座標へ (ドラッグ量をそのまま足す)。
        final cur = _paneShelfDragPos;
        if (cur == null) return;
        setState(() => _paneShelfDragPos = cur + d.delta);
      },
      onPanCancel: () => setState(() {
        _paneShelfRowDragFrom = null;
        _paneShelfColDragFrom = null;
        _paneShelfDragPos = null;
      }),
      onPanEnd: (_) {
        final from = vertical ? _paneShelfRowDragFrom : _paneShelfColDragFrom;
        final pos = _paneShelfDragPos;
        setState(() {
          _paneShelfRowDragFrom = null;
          _paneShelfColDragFrom = null;
          _paneShelfDragPos = null;
        });
        if (from == null || pos == null) return;
        final target = _nearestPaneLine(
            lineRects, vertical ? pos.dy : pos.dx,
            vertical: vertical);
        if (target == from) {
          // 動かさなかった時は「押しただけ」 と同じ扱いで編集側にする。
          _mapSplitActivate(provider, page.id, slot: slot);
          return;
        }
        // 並べ替えは「そのページを編集側にしてから」 実行する
        // (provider の並べ替えは現在ページに対して働くため)。
        _mapSplitActivate(provider, page.id, slot: slot);
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          if (provider.currentPage.id != page.id) return;
          if (vertical) {
            provider.moveShelfRow(from, target);
          } else {
            provider.moveShelfColumn(from, target);
          }
        });
      },
      child: _shelfHandleVisual(dragging, vertical: vertical),
    );
  }

  /// 分割ペイン (非編集セル [slot]): 別ページのライブ表示。
  /// マップ / ギャラリーはパン / ズーム可の閲覧 (タップでその場で編集側に)、
  /// フリーノートは専用エディタをそのまま埋め込み (= ユーザー要望:
  /// フリーノートとマップ / ギャラリーを同時に開けるように)。
  Widget _buildMapSplitPane(MindMapProvider provider, {required int slot}) {
    final page = _resolveSplitCellPage(provider, slot);
    if (page == null) {
      return Container(
        // 編集側 (Scaffold) と同じ背景色にそろえる (= ユーザー要望:
        // アクティブになると背景の色が変わって困惑する問題の解消)。
        color: provider.isDarkMode
            ? const Color(0xFF0F0F1A)
            : const Color(0xFFD8D8D4),
        child: Center(
          child: Text(provider.t('map.splitNoOtherPage'),
              style: const TextStyle(color: Colors.white38, fontSize: 12)),
        ),
      );
    }
    // 解決結果を記憶 (ページ増減で表示が入れ替わりにくくする)。
    _mapSplitCells[slot] = page.id;
    // ── フリーノートは読み取り専用ではなく、 専用エディタごと埋め込んで
    //    その場で描けるようにする (自前の保存 / 状態を持つため独立動作)。 ──
    if (page.pageType == 'paint') {
      return ClipRect(
        child: _PaintPageView(
          key: ValueKey('paint_split_${page.id}_${provider.paintReloadTick}'),
          provider: provider,
          pageId: page.id,
        ),
      );
    }
    // ── Markdown ページも中身ごと埋め込む (= ユーザー報告: 分割にすると
    //    ページ名は Markdown なのに Markdown が開いていない) ──
    if (page.pageType == 'markdown') {
      return ClipRect(
        child: _MarkdownPageView(
          key: ValueKey('md_split_${page.id}'),
          provider: provider,
          pageId: page.id,
          extractText: _extractAttachmentTextForAi,
          onEmbedToPage: (path, name, {pageId}) =>
              _embedFileAsNode(provider, path, name, pageId: pageId),
          onOpenBrowserAi:
              _isDesktop ? () => _openDesktopFloatingAi(provider) : null,
        ),
      );
    }
    final paneCtrl = _ctrlFor('split_${page.id}');
    final bool paneShelf = page.pageType == 'bookshelf';
    // ── 折りたたみ (collapsed) をペインにも反映する ──
    // ★ 以前は page.nodes をそのまま描いていたので、 ペイン側だけ折りたたみが
    //   無視されて子ノードが全部見えていた。 アクティブ / 非アクティブを
    //   切り替えるたびに子が展開 / 収納されるように見える原因
    //   (= ユーザー報告: 4 分割で切り替えると子要素が勝手に展開/収納される)。
    //   キャンバスの大きさも編集側と同じ「見えているノード」 基準にしないと、
    //   引き継いだ表示位置が境界クランプでずれる。
    final Set<String> paneHidden =
        paneShelf ? const <String>{} : provider.hiddenNodeIdsOnPage(page);
    final Map<String, MindMapNode> paneNodes = paneHidden.isEmpty
        ? page.nodes
        : Map<String, MindMapNode>.fromEntries(
            page.nodes.entries.where((e) => !paneHidden.contains(e.key)));
    final List<NodeConnection> paneConnections = paneShelf
        ? const <NodeConnection>[]
        : (paneHidden.isEmpty
            ? page.connections
            : page.connections
                .where((c) =>
                    !paneHidden.contains(c.fromId) &&
                    !paneHidden.contains(c.toId))
                .toList());
    // ギャラリーは編集側と同じ実寸キャンバス + 実際の +ボックス格子を使う
    // (= ユーザー要望: 分割の右側でもギャラリーが正しく表示されるように)。
    final Size paneCanvas = paneShelf
        ? provider.bookshelfCanvasSize(pageOverride: page)
        : Size.square(computeCanvasSize(paneNodes));
    final List<Rect> paneFrontierRects = paneShelf
        ? provider.bookshelfFrontierRects(pageOverride: page)
        : const <Rect>[];
    final List<List<int>> paneFrontierCells = paneShelf
        ? provider.bookshelfFrontierCells(pageOverride: page)
        : const <List<int>>[];
    // 行/列の掴みチップ (= ユーザー要望: 分割で開いた時に行や列の掴みが
    // 表示されない時がある → ペインにも表示する)。 掴みはグリッドの外側
    // (負座標) にあるため、 初期表示を少し右下へ寄せて見えるようにする。
    final List<Rect> paneRowHandles = paneShelf
        ? provider.bookshelfRowHandleRects(pageOverride: page)
        : const <Rect>[];
    final List<Rect> paneColHandles = paneShelf
        ? provider.bookshelfColHandleRects(pageOverride: page)
        : const <Rect>[];
    if (paneShelf && paneCtrl.value.isIdentity()) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        if (paneCtrl.value.isIdentity()) {
          paneCtrl.value = Matrix4.identity()..translate(44.0, 44.0);
        }
      });
    }
    return Container(
      // 編集側 (Scaffold) と同じ背景色にそろえる (= ユーザー要望:
      // アクティブになると背景の色が変わって困惑する問題の解消)。
      color: provider.isDarkMode
          ? const Color(0xFF0F0F1A)
          : const Color(0xFFD8D8D4),
      child: ClipRect(
        // ── パン / ズーム / ホイールなどどんな操作でも、 指を離した時点で
        //    このペインを編集側 (アクティブ) にする (= ユーザー要望:
        //    Ctrl+± や Ctrl+A が操作した側で動くように)。 pointer-up で
        //    切り替えるのでドラッグ中のジェスチャは途切れない。 ──
        // ホイール (onPointerSignal) では切り替えない: ペインのズームだけ
        // で編集権まで移ると「勝手に別ページが開いた」 ように感じるため
        // (= ユーザー要望: 動作が不安定 → 安定化)。
        child: Listener(
          behavior: HitTestBehavior.translucent,
          // ペイン内の操作でもスクロールバーを出す (編集側と同じ 900ms で
          // 自動フェード)。
          onPointerDown: (_) => _markMapScrollActivity(owner: slot),
          onPointerMove: (_) => _markMapScrollActivity(owner: slot),
          onPointerSignal: (e) {
            _markMapScrollActivity(owner: slot);
            // ホイールはこのペインのスクロールとして扱う (= ユーザー報告:
            // Ctrl 無しで拡大縮小してしまう問題)。 Ctrl 併用の時だけズーム。
            _handlePaneWheel(e, paneCtrl, page);
          },
          onPointerUp: (_) =>
              _mapSplitActivate(provider, page.id, slot: slot),
          child: Stack(children: [
            // ── ページ背景 (壁紙) をペインにも反映 (= ユーザー要望:
            //    右側の背景が上手く反映されていない) ──
            _buildInfinitePageBackground(provider, paneCtrl,
                pageOverride: page),
          InteractiveViewer(
            transformationController: paneCtrl,
            // 編集キャンバス側と同じズーム範囲 / 余白にそろえる。 ずれて
            // いると、 アクティブ化した瞬間に編集側の制約でクランプされて
            // 表示位置が飛ぶ (= ユーザー要望: アクティブになったタイミング
            // で変な位置に動く問題の修正)。
            //
            // ── ホイールでの拡大縮小は切る (= ユーザー報告: 画面分割時に
            //    Ctrl を押していないのに拡大縮小してしまう) ──
            // InteractiveViewer は既定でホイール = ズームなので、 ここを
            // 切って、 下の Listener でホイールをスクロールとして扱う。
            // ピンチ (トラックパッド / タッチ) でのズームは
            // scaleEnabled=false でも PanZoom 経由で効く。
            scaleEnabled: false,
            minScale: 0.15,
            maxScale: 3.0,
            constrained: false,
            boundaryMargin: paneShelf
                ? const EdgeInsets.all(2000)
                : EdgeInsets.zero,
            child: SizedBox(
              width: paneCanvas.width,
              height: paneCanvas.height,
              child: GestureDetector(
                // 空き領域のタップでもこのページを編集側にする
                // (= ユーザー要望: 右側も左と同じように操作)。
                behavior: HitTestBehavior.translucent,
                // タップのキャンバス座標も渡す (= ユーザー要望: 基準位置の
                // 設定などが 1 クリック目でそのまま効くように)。
                onTapUp: (d) => _mapSplitActivate(provider, page.id,
                    slot: slot, tapCanvasPos: d.localPosition),
                child: Stack(clipBehavior: Clip.none, children: [
                    // ── 背景 (通常 = グリッド / ギャラリー = 木目 + 棚板)
                    //    (= ユーザー要望: ギャラリーの見た目も揃える) ──
                    // ★ 実寸 (paneCanvas) で描く。 Positioned.fill だと親
                    //   Stack の大きさで描かれ、 棚板がキャンバスの端まで
                    //   届かずに隙間が見えていた (= ユーザー報告: 非アクティブ
                    //   だとギャラリーの隙間が見えてしまう)。 編集側は
                    //   CustomPaint(size: ...) で実寸を渡している。
                    Positioned(
                      left: 0,
                      top: 0,
                      width: paneCanvas.width,
                      height: paneCanvas.height,
                      child: IgnorePointer(
                        child: CustomPaint(
                          size: paneCanvas,
                          painter: paneShelf
                              ? _BookshelfBackgroundPainter(
                                  tileRects: [
                                    for (final n in paneNodes.values)
                                      if (n.hiddenInContainer == null)
                                        Rect.fromLTWH(
                                            n.position.dx,
                                            n.position.dy,
                                            n.width,
                                            n.visualHeight),
                                  ],
                                  isDark: provider.isDarkMode,
                                )
                              : _mapBgHidesGrid(page.backgroundImagePath)
                                  ? null
                                  : _GridPainter(
                                      isDesktop: _isDesktop,
                                      isDark: provider.isDarkMode,
                                    ),
                        ),
                      ),
                    ),
                    // ── ギャラリー: タイル群の背後に敷板を敷く ──
                    // ★ 編集側と同じ層をペインにも敷く (= ユーザー報告:
                    //   分割で非アクティブになると + ボックスの隙間の背景が
                    //   変わってしまう)。 これが無いと隙間から壁紙が透けて、
                    //   アクティブ時と見た目が変わっていた。
                    if (paneShelf)
                      Positioned(
                        left: 0,
                        top: 0,
                        width: paneCanvas.width,
                        height: paneCanvas.height,
                        child: IgnorePointer(
                          child: CustomPaint(
                            size: paneCanvas,
                            painter: _ShelfBackdropPainter(
                              nodes: paneNodes,
                              isDark: provider.isDarkMode,
                              addRects: paneFrontierRects,
                            ),
                          ),
                        ),
                      ),
                    // 接続線
                    Positioned.fill(
                      child: IgnorePointer(
                        child: CustomPaint(
                          painter: ConnectionPainter(
                            nodes: paneNodes,
                            connections: paneConnections,
                            isDarkMode: provider.isDarkMode,
                            darkBackground:
                                _pageBackgroundIsDark(provider, page),
                          ),
                        ),
                      ),
                    ),
                    // 装飾図形 (レイヤー 1〜3 = ノードの後ろ)
                    Positioned.fill(
                      child: IgnorePointer(
                        child: CustomPaint(
                          painter: _DecorationPainter(
                            decorations: page.decorations,
                            layers: const {1, 2, 3},
                          ),
                        ),
                      ),
                    ),
                    // ギャラリーの行/列の掴みチップ (表示用レプリカ。 操作は
                    //   タップでこのページを編集側にしてから = ユーザー要望)。
                    if (paneShelf) ...[
                      // ★ 編集側 (_buildShelfLineHandles) と同じ寸法・置き方に
                      //   そろえる (= ユーザー報告: 非アクティブだと掴みの
                      //   見た目が変わってしまう)。 太さはモバイル 56 / PC 34。
                      //   行チップは編集側と同じく「rect の右端」 に右揃え、
                      //   列チップは「rect の下端」 に下揃えで置く。 左上揃えの
                      //   ままだと最小太さぶんズレて、 アクティブ側と位置が
                      //   合わなかった (= ユーザー報告)。
                      //   編集側は行/列が 2 つ以上ある時だけ掴みを出すので、
                      //   ここも同じ条件にする。
                      if (paneRowHandles.length > 1)
                        for (var i = 0; i < paneRowHandles.length; i++)
                          Positioned(
                            left: paneRowHandles[i].right -
                                math.max(
                                    paneRowHandles[i].width, _shelfHandleThick),
                            top: paneRowHandles[i].top,
                            width: math.max(
                                paneRowHandles[i].width, _shelfHandleThick),
                            height: paneRowHandles[i].height,
                            child: _paneShelfHandleChip(
                                provider, page, slot, i,
                                vertical: true,
                                lineRects: paneRowHandles),
                          ),
                      if (paneColHandles.length > 1)
                        for (var i = 0; i < paneColHandles.length; i++)
                          Positioned(
                            left: paneColHandles[i].left,
                            top: paneColHandles[i].bottom -
                                math.max(paneColHandles[i].height,
                                    _shelfHandleThick),
                            width: paneColHandles[i].width,
                            height: math.max(
                                paneColHandles[i].height, _shelfHandleThick),
                            child: _paneShelfHandleChip(
                                provider, page, slot, i,
                                vertical: false,
                                lineRects: paneColHandles),
                          ),
                      // ── 行/列の番号バッジ (= ユーザー要望: アクティブか
                      //    どうかに関わらず常に表示)。 編集側と同じ見た目。 ──
                      for (var i = 0; i < paneRowHandles.length; i++)
                        Positioned(
                          left: paneRowHandles[i].right -
                              math.max(paneRowHandles[i].width,
                                      _shelfHandleThick) *
                                  0.5 -
                              _shelfBadgeW * 0.5,
                          top: paneRowHandles[i].center.dy - _shelfBadgeH * 0.5,
                          width: _shelfBadgeW,
                          height: _shelfBadgeH,
                          child: IgnorePointer(
                              child: _shelfIndexBadge('${i + 1}')),
                        ),
                      for (var i = 0; i < paneColHandles.length; i++)
                        Positioned(
                          left: paneColHandles[i].center.dx - _shelfBadgeW * 0.5,
                          top: paneColHandles[i].bottom -
                              math.max(paneColHandles[i].height,
                                      _shelfHandleThick) *
                                  0.5 -
                              _shelfBadgeH * 0.5,
                          width: _shelfBadgeW,
                          height: _shelfBadgeH,
                          child: IgnorePointer(
                              child: _shelfIndexBadge('${i + 1}')),
                        ),
                    ],
                    // ギャラリーの「+ボックス」 (= 編集側と同じ格子の空セル。
                    //   タップでこのページが編集側になる = ユーザー要望:
                    //   分割でもギャラリーを正しく表示 + 普段通りの操作)。
                    // * 編集側 (_buildShelfAddBox) と同一の見た目にする
                    //   (= ユーザー要望: 非アクティブでも + ボックスの隙間が
                    //   白で埋まっているアクティブ時と同じ状態に)。 白い箱は
                    //   セル全体の中央に置き、 枠色・影・+ の大きさも同じ。
                    if (paneShelf)
                      for (var fi = 0;
                          fi < paneFrontierRects.length &&
                              fi < paneFrontierCells.length;
                          fi++)
                        Builder(builder: (_) {
                          final cellRect = provider.bookshelfCellRect(
                              paneFrontierCells[fi][0],
                              paneFrontierCells[fi][1],
                              pageOverride: page);
                          final box = paneFrontierRects[fi];
                          final hit = cellRect ?? box;
                          return Positioned(
                            left: hit.left,
                            top: hit.top,
                            width: hit.width,
                            height: hit.height,
                            child: Center(
                              child: SizedBox(
                                width: box.width,
                                height: box.height,
                                child: Container(
                                  decoration: BoxDecoration(
                                    color: Colors.white,
                                    borderRadius: BorderRadius.circular(10),
                                    border: Border.all(
                                        color: const Color(0xFFE0E0E0)),
                                    boxShadow: [
                                      BoxShadow(
                                        color: Colors.black
                                            .withValues(alpha: 0.18),
                                        blurRadius: 8,
                                        offset: const Offset(0, 3),
                                      ),
                                    ],
                                  ),
                                  child: const Center(
                                    child: Icon(Icons.add_rounded,
                                        color: Color(0xFFBDBDBD), size: 48),
                                  ),
                                ),
                              ),
                            ),
                          );
                        }),
                    // ノード (タップでこのページがその場で編集側になり、
                    //   そのノードが選択されてアクションボタンが出る
                    //   = ユーザー要望: 左側と同様の機能が使えるように)
                    for (final n in paneNodes.values)
                      if (n.hiddenInContainer == null)
                        Positioned(
                          left: n.position.dx,
                          top: n.position.dy,
                          child: NodeWidget(
                            // (レイヤー 4〜5 の図形はこの後に重ねる)
                            key: ValueKey('map_split_${page.id}_${n.id}'),
                            node: n,
                            isSelected: false,
                            isShelf: paneShelf,
                            isDarkMode: provider.isDarkMode,
                            // 分割ペインのギャラリーでも全文を読めるように。
                            onShowFullText: paneShelf
                                ? () => _showGalleryFullTextDialog(n.id,
                                    pageId: page.id)
                                : null,
                            onTap: () => _mapSplitActivate(
                                provider, page.id,
                                nodeId: n.id, slot: slot),
                          ),
                        ),
                    // 図形レイヤー 4〜5 (= ノードより手前。 編集側と同じ)。
                    Positioned.fill(
                      child: IgnorePointer(
                        child: CustomPaint(
                          painter: _DecorationPainter(
                            decorations: page.decorations,
                            layers: const {4, 5},
                          ),
                        ),
                      ),
                    ),
                  ]),
                ),
              ),
            ),
            // ── スクロールバー (= ユーザー要望: 右側にも表示し、 この
            //    ペインのスクロールだけを動かす)。 操作したペイン (owner)
            //    のバーだけを表示し、 他の画面のバーは出さない
            //    (= ユーザー要望)。 900ms で自動フェード。 ──
            if (_isDesktop &&
                _mapScrollbarsVisible &&
                _mapScrollbarOwner == slot)
              _buildMapViewportScrollbars(provider, paneCtrl,
                  pageOverride: page, owner: slot),
          ]),
        ),
      ),
    );
  }

  /// 分割ペインのページを 「その場で」 編集側へ切り替える。
  /// ペインの位置は入れ替えず (編集キャンバスがタップした側へ移る)、
  /// 表示位置も引き継ぐので画面の見た目は変わらない。 [nodeId] を渡すと
  /// 切替後にそのノードを選択してアクションボタンを出す。
  void _mapSplitActivate(MindMapProvider provider, String pageId,
      {String? nodeId, int? slot, Offset? tapCanvasPos}) {
    // ── 1 クリック目でモード操作をそのまま実行 (= ユーザー要望: 基準位置の
    //    設定などで「アクティブにするための 1 クリック」 を余計にしない)。
    //    現状は基準位置設定モードを転送対象にする。 ──
    final forwardSetRef = _settingRefMode && tapCanvasPos != null;
    final oldId = provider.currentPage.id;
    // 既にアクティブなら何もしない (パン終了とタップの両方から呼ばれても
    // 二重に切り替わらないように冪等にする)。 nodeId の選択処理だけは行う。
    final switched = oldId != pageId;
    if (switched) {
      final idx = provider.pages.indexWhere((p) => p.id == pageId);
      if (idx < 0) return;
      // ペインで見えていた位置をそのまま編集用コントローラへ、 逆に旧編集
      // ページの位置をペイン用コントローラへ引き継ぐ (見た目が飛ばない)。
      //
      // ★ 引き渡しは「同じフレームのうちに」 同期で行う。
      //   ・postFrameCallback にすると、 切替後の最初の 1 フレームだけ
      //     編集キャンバスが古い行列 (一度も編集していないページなら単位
      //     行列) で描かれ、 次のフレームで正しい位置へ跳ねる =
      //     「アクティブにすると要素が変な方向に動く」 の正体 (= ユーザー報告)。
      //   ・かといって素のまま代入するとギャラリーのパン制限
      //     (_clampBookshelfPan) が旧ページ基準で働いて切り詰められるので、
      //     引き渡しの間だけ制限を止める。
      final paneMatrix = _ctrlFor('split_$pageId').value.clone();
      final editorMatrix = _ctrlFor(oldId).value.clone();
      _clampingShelf = true;
      // ★ 代入より先に _lastMatrix を新しい行列へそろえる。 軸ロック
      //   (Ctrl+K / Ctrl+L) 中は _onTransformChanged が「直前の行列」 へ
      //   巻き戻すので、 旧ページの行列が残っていると引き継いだ位置が
      //   そこへ引きずられてしまう (_applyScale と同じ手当て)。
      _lastMatrix = paneMatrix.clone();
      _ctrlFor(pageId).value = paneMatrix;
      _ctrlFor('split_$oldId').value = editorMatrix;
      _clampingShelf = false;
      // ギャラリーは初回表示時の自動センタリングが走ると位置が飛ぶので、
      // アクティブ化時は「センタリング済み」 扱いにして抑止する
      // (= ユーザー要望: アクティブになった時に変な位置へ動く問題の修正)。
      _shelfCenteredPages.add(pageId);
      // このクリックでアクティブ化したことを控える。 Listener(onPointerUp) は
      // タップ認識より先に走るため、 続いて届くノードの onTap の時点では既に
      // 切替済みで「切替と同時のクリックか」 が判別できない。 時刻で見分ける
      // (= ユーザー報告: 分割の別画面を触っただけで子ノードが展開/収納される)。
      _splitActivatedAtMs = DateTime.now().millisecondsSinceEpoch;
      provider.switchPage(idx);
      setState(() {
        // タップされたセルへ編集側が移り、 旧編集セルには旧ページが残る
        // (= セルのページ配置は動かさず、 編集権だけが移動する)。
        final oldSlot = _mapSplitEditorSlot;
        final tappedSlot = slot ??
            _visibleSplitSlots().firstWhere(
                (i) => i != oldSlot && _mapSplitCells[i] == pageId,
                orElse: _primaryViewerSlot);
        _mapSplitCells[oldSlot] = oldId;
        _mapSplitCells[tappedSlot] = pageId;
        _mapSplitEditorSlot = tappedSlot;
      });
    }
    // ── 基準位置設定モードなら、 アクティブ化と同時にそのタップ位置を
    //    基準位置として適用する (= ユーザー要望: 1 クリック目でいきなり
    //    別の分割画面の基準位置を設定できるように)。 ──
    if (forwardSetRef) {
      final canvasPos = tapCanvasPos!;
      setState(() {
        _referencePos = canvasPos;
        _pageReferencePositions[pageId] = canvasPos;
        _showRefMarker = true;
        _settingRefMode = false;
      });
      _saveReferencePositions();
      Future.delayed(const Duration(seconds: 3), () {
        if (mounted) setState(() => _showRefMarker = false);
      });
      return;
    }
    if (nodeId != null) {
      // アクティブ化のためのクリックだったか (= このクリックで切り替わった、
      // または直前に Listener 側が切り替えたばかりか)。 判定したら控えは
      // 使い切る: そうしないと 600ms 以内の 2 回目のクリックまで無視されて
      // 「格納ノードが開けない」 になってしまう。
      final activating = switched || _justActivatedSplitPane;
      _splitActivatedAtMs = 0;
      // 切替後のフレームで、 タップされたノードを選択してアクション
      // ボタンを表示する (= 左側と同じタップ体験)。
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || provider.currentPage.id != pageId) return;
        final n = provider.nodes[nodeId];
        if (n == null) return;
        provider.selectNode(nodeId);
        final ctrl = _ctrlFor(pageId);
        if (n.isContainer) {
          // ★ アクティブ化のためのクリックでは、 格納ノードを開いたり
          //   閉じたりしない (= ユーザー報告: 分割の別画面を触っただけで
          //   格納していた子ノードが展開/収納される)。 選ぶだけにして、
          //   開閉はアクティブになった後のもう 1 回のクリックで行う。
          //   ペインの Listener(onPointerUp) が先に切替を済ませてしまうので、
          //   switched だけでは判定できない (時刻でも見る)。
          if (activating) return;
          if (provider.currentPage.pageType == 'bookshelf') {
            _showBookshelfCoverMenu(n);
          } else {
            _showContainerExpandPopup(nodeId, ctrl);
          }
          return;
        }
        setState(() {
          _selectedConnections.clear();
          _clearConnectionBendDragFields(clearSelection: true);
        });
        // アクティブ化と同時のクリックでは、 操作バーの場所を作るための
        // 自動スクロールをしない (= ユーザー報告: 切り替えた瞬間に表示が
        // 変な方向へ動く)。 引き継いだ表示位置をそのまま保つ。
        _showActionButtons(nodeId, ctrl, ensureRoom: !activating);
      });
    }
  }

  /// 右上に出す全体の縮図 (= ユーザー要望: マップ上のどこにいるのか、
  /// 他の要素がどこにあるのかを縮図で見たい)。
  ///
  /// ・全ノードを小さな四角で描き、 今見えている範囲を枠で示す。
  /// ・縮図をタップ / ドラッグするとその位置へ移動する。
  /// ・畳んでおける (設定は次回も引き継ぐ)。
  Widget _buildMiniMap(
      MindMapProvider provider,
      TransformationController ctrl,
      Map<String, MindMapNode> nodes,
      List<NodeConnection> connections) {
    // ギャラリー等では出さない (= ユーザー要望: 全体図はマインドマップだけ)。
    if (provider.currentPage.pageType != 'normal') {
      return const SizedBox.shrink();
    }
    // 動作設定で消している時は出さない (= ユーザー要望)。
    if (provider.hideMiniMap) return const SizedBox.shrink();
    // 中身が無いページでは出しても意味がないので隠す。
    if (nodes.isEmpty) return const SizedBox.shrink();
    final double box = _isDesktop ? 168.0 : 112.0;
    final double w = box;
    final double h = box;

    // ── 右のカスタムバーと重ならないように横へ避ける (= ユーザー要望) ──
    //    バー幅 + 端の余白ぶん左へ寄せる。 自由配置中のバーは位置が
    //    読めないので避けない。
    //    さらにページのスクロールバー (幅 18 + 余白) ぶんも空ける
    //    (= ユーザー要望: 全体図とサイドバーの間にスクロールバーが来るように)。
    double rightOff = 8;
    final double sideDockWidth = _anchoredSideDockWidth(provider, 'right');
    if (sideDockWidth > 0) {
      rightOff += sideDockWidth + 24;
    }

    if (!_miniMapOpen) {
      return Positioned(
        top: 8,
        right: rightOff,
        child: _miniMapChrome(
          child: IconButton(
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints.tightFor(width: 30, height: 30),
            tooltip: provider.t('minimap.show'),
            icon: const Icon(Icons.map_outlined,
                size: 17, color: Color(0xFF9FB6C4)),
            onPressed: _toggleMiniMap,
          ),
        ),
      );
    }

    return Positioned(
      top: 8,
      right: rightOff,
      // ── 動いている間だけ見せる (= ユーザー要望: 止まっている時は出さない)。
      //    カーソルを乗せている間は消さないので、 押して移動もできる。 ──
      child: MouseRegion(
        onEnter: (_) {
          _miniMapHover = true;
          _markMiniMapActivity();
        },
        onExit: (_) {
          _miniMapHover = false;
          _markMiniMapActivity();
        },
        child: IgnorePointer(
          ignoring: !(_miniMapActive || _miniMapHover),
          child: AnimatedOpacity(
            opacity: (_miniMapActive || _miniMapHover) ? 1 : 0,
            duration: const Duration(milliseconds: 220),
            child: _miniMapChrome(
        child: SizedBox(
          width: w,
          height: h + 22,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            // 見出し + 畳むボタン
            SizedBox(
              height: 22,
              child: Row(children: [
                const SizedBox(width: 8),
                const Icon(Icons.map_rounded,
                    size: 12, color: Color(0xFF6FC3E8)),
                const SizedBox(width: 5),
                Expanded(
                  child: Text(provider.t('minimap.title'),
                      style: const TextStyle(
                          color: Color(0xFFB9CBD6),
                          fontSize: 10,
                          fontWeight: FontWeight.w700)),
                ),
                IconButton(
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints.tightFor(width: 22, height: 22),
                  tooltip: provider.t('minimap.hide'),
                  icon: const Icon(Icons.close_rounded,
                      size: 13, color: Color(0xFF8FA6B4)),
                  onPressed: _toggleMiniMap,
                ),
              ]),
            ),
            // 縮図本体
            Expanded(
              child: AnimatedBuilder(
                animation: ctrl,
                builder: (_, __) {
                  final view = _editorViewportSize();
                  // 今見えている範囲 (キャンバス座標)。
                  final viewport = Rect.fromPoints(
                      ctrl.toScene(Offset.zero),
                      ctrl.toScene(Offset(view.width, view.height)));
                  // ── 映す範囲 ──
                  // キャンバスは 2 万 px 四方の固定で、 大半は空白。 全体を
                  // 映すと現在位置が点にしか見えないので、 「要素の広がり」 と
                  // 「今の表示範囲」 を合わせた矩形を映す (= ユーザー要望:
                  // 全体のどこにいて、 他の要素がどこにあるか)。
                  var minX = double.infinity, minY = double.infinity;
                  var maxX = -double.infinity, maxY = -double.infinity;
                  for (final n in nodes.values) {
                    minX = math.min(minX, n.position.dx);
                    minY = math.min(minY, n.position.dy);
                    maxX = math.max(maxX, n.position.dx + n.width);
                    maxY = math.max(maxY, n.position.dy + n.visualHeight);
                  }
                  var world = Rect.fromLTRB(minX, minY, maxX, maxY)
                      .expandToInclude(viewport);
                  // 余白を少し足して、 端の要素が縁に貼り付かないようにする。
                  final pad = math.max(world.width, world.height) * 0.06 + 40;
                  world = Rect.fromLTRB(world.left - pad, world.top - pad,
                      world.right + pad, world.bottom + pad);

                  return LayoutBuilder(builder: (_, cons) {
                    final paintSize = Size(cons.maxWidth, cons.maxHeight);
                    // 歪ませないよう縦横同じ倍率で収める。
                    final scale = math.min(paintSize.width / world.width,
                        paintSize.height / world.height);
                    final dx =
                        (paintSize.width - world.width * scale) / 2;
                    final dy =
                        (paintSize.height - world.height * scale) / 2;

                    void jumpTo(Offset local) {
                      // 縮図上の点をキャンバス座標へ戻して、 そこを画面中央へ。
                      final target = Offset(
                        (local.dx - dx) / scale + world.left,
                        (local.dy - dy) / scale + world.top,
                      );
                      final m = Matrix4.copy(ctrl.value);
                      final sc = m.getMaxScaleOnAxis();
                      m.setTranslationRaw(
                        view.width / 2 - target.dx * sc,
                        view.height / 2 - target.dy * sc,
                        0,
                      );
                      ctrl.value = m;
                    }

                    return GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTapDown: (d) => jumpTo(d.localPosition),
                      onPanUpdate: (d) => jumpTo(d.localPosition),
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(6),
                        child: CustomPaint(
                          size: paintSize,
                          painter: _MiniMapPainter(
                            nodes: nodes,
                            connections: connections,
                            world: world,
                            viewport: viewport,
                            scale: scale,
                            offset: Offset(dx, dy),
                          ),
                        ),
                      ),
                    );
                  });
                },
              ),
            ),
          ]),
        ),
      ),
          ),
        ),
      ),
    );
  }

  /// ミニマップの外枠 (半透明のガラス板)。
  Widget _miniMapChrome({required Widget child}) => Material(
        color: Colors.transparent,
        child: Container(
          padding: const EdgeInsets.all(3),
          decoration: BoxDecoration(
            color: const Color(0xFF101A24).withValues(alpha: 0.82),
            borderRadius: BorderRadius.circular(9),
            border: Border.all(
                color: const Color(0xFF6FC3E8).withValues(alpha: 0.35)),
            boxShadow: const [
              BoxShadow(
                  color: Color(0x55000000), blurRadius: 10, offset: Offset(0, 3))
            ],
          ),
          child: child,
        ),
      );

  Widget _buildCanvas(BuildContext context, MindMapProvider provider,
      TransformationController ctrl) {
    // カレンダーモード時はマインドマップ描画を置き換え
    if (_calendarMode) {
      return _buildCalendarView(context, provider);
    }
    final allNodes = provider.nodes;
    final allConnections = provider.connections;
    final isMoveMode = _moveModeNodeId != null;
    final isRangeMode = _rangeSelectMode;

    // 折りたたみで非表示にするノード
    final hidden = provider.hiddenNodeIds;
    final nodes = Map<String, MindMapNode>.fromEntries(
        allNodes.entries.where((e) => !hidden.contains(e.key)));
    final connections = allConnections
        .where((c) => !hidden.contains(c.fromId) && !hidden.contains(c.toId))
        .toList();

    // ── ドラッグ&ドロップでサブマップ化 ──────────────────────────────
    // マップ一覧 (Drawer) でページをロングプレスドラッグしてキャンバス上に
    // ドロップすると、 そのドロップ位置に「📒 マップ名」 ノードが作成され、
    // linkedPageId が設定される (= タップでそのページに遷移できるサブマップ
    // 参照ノード)。 既存の `_DrawerPageDragData` を Drawer 側で発火して
    // いるので、 こちらは DragTarget として受けるだけで OK。
    return DragTarget<_DrawerPageDragData>(
      // ★ hit test を確実にするため opaque に設定 ★
      // 旧設定 (= translucent デフォルト) では子の InteractiveViewer に
      // hit test を取られて DragTarget が反応しないケースがあった。
      hitTestBehavior: HitTestBehavior.opaque,
      onWillAcceptWithDetails: (d) {
        // 現在のページ自身は drop しても無意味なので拒否
        final pid = d.data.pageIds.isEmpty ? null : d.data.pageIds.first;
        return pid != null && pid != provider.currentPage.id;
      },
      onAcceptWithDetails: (details) {
        // ── マップ一覧からの D&D は「分割で開く」 に変更 (= ユーザー要望:
        //    サブマップ化機能は消して、 落としたら分割で開かれるように)。
        //    既存の linkedPageId ノードの動作 (タップで遷移) はそのまま。 ──
        final dropped = details.data.pageIds
            .where((id) => id != provider.currentPage.id)
            .map((id) {
              for (final p in provider.pages) {
                if (p.id == id) return p;
              }
              return null;
            })
            .whereType<MindMapPage>()
            .where(_splitEligiblePage)
            .toList();
        if (dropped.isEmpty) return;
        setState(() {
          _mapSplitOpen = true;
          // 2 枚以上落としたら 4 分割にして順に割り当てる。
          if (dropped.length >= 2 && _isDesktop) _mapSplitQuad = true;
          var di = 0;
          for (final slotIdx in _visibleSplitSlots()) {
            if (slotIdx == _mapSplitEditorSlot) continue;
            if (di >= dropped.length) break;
            _mapSplitCells[slotIdx] = dropped[di++].id;
          }
        });
        _appSnack(
          context,
          SnackBar(
            content: Text(
                context
                    .read<MindMapProvider>()
                    .t('map.splitDropOpened')
                    .replaceFirst('{n}', '${dropped.length}'),
                style: const TextStyle(fontSize: 12)),
            backgroundColor: const Color(0xFF6C63FF),
            duration: const Duration(seconds: 2),
          ),
        );
      },
      builder: (ctx, candidate, rejected) {
        // ドロップ中はキャンバス全体に紫の半透明オーバーレイを出して、
        // どこに drop できるか視覚的に示す。
        // ★ Stack を `fit: StackFit.expand` で親いっぱいに広げないと
        //   DragTarget の hit test 領域が子の自然サイズだけになり、
        //   InteractiveViewer の中央以外で drop が反応しなくなる。
        return Stack(fit: StackFit.expand, children: [
          // ── 表示領域いっぱいの背景 (壁紙) ──
          // InteractiveViewer の外側に固定配置し、キャンバスの枠を越えて
          // パン/ズームしても常に画面全体が背景で覆われるようにする。
          _buildInfinitePageBackground(provider, ctrl),
          Positioned.fill(
            child: _buildCanvasInner(context, provider, ctrl, nodes,
                connections, isMoveMode, isRangeMode),
          ),
          // ── 右上のミニマップ (= ユーザー要望) ──
          _buildMiniMap(provider, ctrl, nodes, connections),
          if (candidate.isNotEmpty)
            Positioned.fill(
              child: IgnorePointer(
                child: Container(
                  decoration: BoxDecoration(
                    color: const Color(0xFF6C63FF).withValues(alpha: 0.10),
                    border:
                        Border.all(color: const Color(0xFF6C63FF), width: 3),
                  ),
                  alignment: Alignment.topCenter,
                  padding: const EdgeInsets.only(top: 24),
                  child: Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
                    decoration: BoxDecoration(
                      color: const Color(0xFF6C63FF),
                      borderRadius: BorderRadius.circular(20),
                    ),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      const Icon(Icons.add_to_drive_rounded,
                          color: Colors.white, size: 16),
                      const SizedBox(width: 6),
                      Text(provider.t('submap.dropToEmbed'),
                          style: const TextStyle(
                              color: Colors.white,
                              fontSize: 12,
                              fontWeight: FontWeight.w700)),
                    ]),
                  ),
                ),
              ),
            ),
          // マウスホイールを横移動へ切り替えるデスクトップ向け UI。
          // モバイルでは下部ツールバーと操作領域が重なるため表示せず、
          // 従来どおり空白ドラッグでパンする。
          // 操作したペイン (owner=editor) の時だけ表示 (= ユーザー要望:
          // バーを動かした時に他の画面のバーまで出ないように)。
          if (_isDesktop &&
              _mapScrollbarsVisible &&
              _mapScrollbarOwner == 'editor')
            _buildMapViewportScrollbars(provider, ctrl),
        ]);
      },
    );
  }

  /// 元の `_buildCanvas` の中身。 DragTarget で wrap したことで分離した。
  /// 引数は元の関数で計算済みの状態を渡してもらう。
  /// 既に「中央スタート」 のために中央寄せ済みのギャラリーページ ID。
  final Set<String> _shelfCenteredPages = {};

  /// ギャラリーページの中身をビューの中央に表示する (= ユーザー要望: 中央スタート)。
  /// _matrixFor が指定キャンバス座標を画面中央に置く仕組みを再利用する。
  void _centerBookshelfView(String pid, TransformationController ctrl) {
    final provider = context.read<MindMapProvider>();
    if (provider.currentPage.id != pid) return;
    double minX = double.infinity, minY = double.infinity, maxX = 0, maxY = 0;
    void acc(double l, double t, double r, double b) {
      if (l < minX) minX = l;
      if (t < minY) minY = t;
      if (r > maxX) maxX = r;
      if (b > maxY) maxY = b;
    }

    for (final n in provider.currentPage.nodes.values) {
      acc(n.position.dx, n.position.dy, n.position.dx + n.width,
          n.position.dy + n.visualHeight);
    }
    for (final r in provider.bookshelfFrontierRects()) {
      acc(r.left, r.top, r.right, r.bottom);
    }
    if (!minX.isFinite) return;
    final center = Offset((minX + maxX) / 2, (minY + maxY) / 2);
    // _matrixFor は (p.dx+80, p.dy+28) を画面中央に置くので、 中心を補正。
    ctrl.value = _matrixFor(center - const Offset(80, 28), _kDefaultScale);
  }

  /// この数を超えたら「見えている範囲だけ描く」 に切り替える
  /// (= ユーザー報告: 大量のファイルを読み込むとカクついて動かなくなる)。
  /// 少ないうちは全部描いた方が単純で速いので、 通常のマップの挙動は変えない。
  static const int _kCullNodeThreshold = 250;

  /// 画面外でも作っておく余白 (キャンバス座標)。 スクロールした瞬間に
  /// 空白が見えないよう、 表示範囲より一回り広く作る。
  static const double _kCullMargin = 800.0;

  /// InteractiveViewer が渡す [viewport] (シーン座標の四角形) から、
  /// 描画対象にする矩形を作る。
  Rect _cullRectFromViewport(Quad viewport) {
    final xs = [
      viewport.point0.x,
      viewport.point1.x,
      viewport.point2.x,
      viewport.point3.x
    ];
    final ys = [
      viewport.point0.y,
      viewport.point1.y,
      viewport.point2.y,
      viewport.point3.y
    ];
    var l = xs.first, r = xs.first, t = ys.first, b = ys.first;
    for (final v in xs) {
      if (v < l) l = v;
      if (v > r) r = v;
    }
    for (final v in ys) {
      if (v < t) t = v;
      if (v > b) b = v;
    }
    if (!l.isFinite || !r.isFinite || !t.isFinite || !b.isFinite) {
      return Rect.largest;
    }
    return Rect.fromLTRB(l, t, r, b).inflate(_kCullMargin);
  }

  /// 接続線を表示範囲で間引く。 両端のノードがどちらも範囲外なら描かない。
  /// [cullRect] が null なら間引かない (= ノードが少ない時)。
  List<NodeConnection> _cullConnections(
    List<NodeConnection> connections,
    Map<String, MindMapNode> nodes,
    Rect? cullRect,
  ) {
    if (cullRect == null) return connections;
    return connections.where((c) {
      final a = nodes[c.fromId];
      final b = nodes[c.toId];
      if (a == null || b == null) return true; // 判断できない物は残す
      // 線は 2 点の間を通るので、 その外接矩形が範囲に掛かるかで見る。
      final rect = Rect.fromLTRB(
        math.min(a.position.dx, b.position.dx),
        math.min(a.position.dy, b.position.dy),
        math.max(a.position.dx + a.width, b.position.dx + b.width),
        math.max(a.position.dy + a.visualHeight,
            b.position.dy + b.visualHeight),
      );
      return rect.overlaps(cullRect);
    }).toList();
  }

  /// ノードが描画対象の矩形に掛かっているか。
  bool _nodeIntersects(MindMapNode n, Rect r) =>
      n.position.dx <= r.right &&
      n.position.dx + n.width >= r.left &&
      n.position.dy <= r.bottom &&
      n.position.dy + n.visualHeight >= r.top;

  /// 画面外でも必ず描くノード (操作中のもの)。 位置がずれている最中や
  /// 操作バーが出ているものを消すと、 掴んでいる対象が消えてしまう。
  bool _mustRenderNode(String id) =>
      id == _moveModeNodeId ||
      id == _actionNodeId ||
      id == _editingCaptionNodeId ||
      id == _inlineShelfEditNodeId ||
      (_rangeDragging && _rangeSelectedIds.contains(id));

  Widget _buildCanvasInner(
      BuildContext context,
      MindMapProvider provider,
      TransformationController ctrl,
      Map<String, MindMapNode> nodes,
      List<NodeConnection> connections,
      bool isMoveMode,
      bool isRangeMode) {
    // ── ギャラリーページ: 開いた直後に整列し直して中央へ寄せる (= 中央スタート) ──
    final curPage = provider.currentPage;
    if (curPage.pageType == 'bookshelf' &&
        !_shelfCenteredPages.contains(curPage.id)) {
      final pid = curPage.id;
      _shelfCenteredPages.add(pid);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || provider.currentPage.id != pid) return;
        provider.reflowBookshelf();
        _centerBookshelfView(pid, ctrl);
      });
    }
    final isMobileShelf = !_isDesktop && curPage.pageType == 'bookshelf';
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      // InteractiveViewer の child より外に見える余白も viewport の
      // 「何もない所」として扱う。child 内のノード/図形は手前の
      // tap recognizer が受け取るため、ここは外側余白だけで発火する。
      onTap: isMobileShelf
          ? () {
              if (_inlineShelfEditNodeId != null) {
                _commitShelfInlineTextEdit(clearSelection: true);
                return;
              }
              _clearShelfElementSelection(provider);
            }
          : null,
      // ギャラリーは boundaryMargin が広く、 キャンバス (棚グリッド) の外側の
      // 余白を右クリックすると子の onSecondaryTapUp に当たらず何も出なかった
      // (= ユーザー要望: 何もない所の右クリックで背景設定が出ないことがある)。
      // viewport 全体で受けるフォールバック。 キャンバス内は子の recognizer が
      // 勝つので二重には出ない。
      onSecondaryTapUp: _isDesktop && !isRangeMode
          ? (details) =>
              _showCanvasContextMenu(details.globalPosition, ctrl, provider)
          : null,
      child: InteractiveViewer.builder(
        transformationController: ctrl,
        // 通常マップはキャンバス外へはスクロールできないよう margin をゼロに。
        // ギャラリーは中身を画面中央に寄せたい (= ユーザー要望: +ブロックを中央に)
        //   ので余白を確保し、 _centerBookshelfView の中央寄せが端で詰まって
        //   左上に張り付かないようにする。
        boundaryMargin: provider.currentPage.pageType == 'bookshelf'
            // 右に分割パネル (AI チャット等) を出すと最終列がパネルの下に隠れて
            //   見えなくなる。 パネル幅ぶん右マージンを増やし、 中身を左へ余分に
            //   スクロールして最終列をパネルの外まで送り出せるようにする
            //   (= ユーザー要望: AI チャット欄を出しても全要素を見られるように)。
            ? EdgeInsets.fromLTRB(
                2000,
                2000,
                2000 +
                    (_splitOpen
                        ? _splitPanelEffectiveSize(context) + 240.0
                        : 0.0),
                2000)
            : EdgeInsets.zero,
        minScale: 0.15,
        maxScale: 3.0,
        // ★ マウスカーソル位置でアクティブ側を切替 ★
        // 画面分割中: カーソルがパネル側 → マップ静止 (PDF/WebView に譲る)
        //             カーソルがマップ側 → マップ通常動作
        // _splitPanelHover は MouseRegion.onEnter/onExit で自動更新される。
        panEnabled: !_pauseViewer &&
            !isRangeMode &&
            !(_lockH && _lockV) &&
            !_splitPanelHover &&
            !_shelfHandleHovering &&
            !_shelfHandleDragging &&
            !_connectionBendPointerActive,
        panAxis: _lockH && !_lockV
            ? PanAxis.vertical
            : (_lockV && !_lockH ? PanAxis.horizontal : PanAxis.free),
        scaleEnabled: !_pauseViewer &&
            !isRangeMode &&
            !_effectiveLockScale &&
            !_splitPanelHover &&
            !_shelfHandleHovering,
        builder: (BuildContext context, Quad viewport) {
          // ── 1 フレームに 1 回だけ「描く範囲」 を求める ──
          //   ノードが多い時だけ間引く (= ユーザー報告: 大量のファイルを
          //   読み込むとカクついて動かなくなる)。 少ない時は null にして
          //   従来どおり全部描く。
          final Rect? cullRect = nodes.length > _kCullNodeThreshold
              ? _cullRectFromViewport(viewport)
              : null;
          return GestureDetector(
            behavior: (isRangeMode ||
                    _canvasLongPressActive ||
                    _polylineMode ||
                    _drawingDecorationKind != null)
                ? HitTestBehavior.opaque
                : HitTestBehavior.translucent,
            // ── 折れ線モード: クリックで節点を足していく (= ユーザー要望:
            //    節点の沢山ついた折れ曲がった直線)。 最後の点をもう一度
            //    押すか、 ダブルクリックで確定。 ──
            onTapDown: _polylineMode
                ? (details) {
                    _polylineAddPoint(
                        _globalToCanvas(details.globalPosition, ctrl));
                  }
                : null,
            // ── 図形を選んでいる時は、 押しただけで決めた大きさの図形を
            //    置く (= ユーザー要望: PDF の所と同じく瞬時に出せる)。
            //    ★ onTapDown だとドラッグの始まりでも走ってしまい、 引いた
            //      図形と重ねて 2 個できる。 タップが成立した時だけ呼ぶ。 ──
            onTapUp: (_drawingDecorationKind != null && !_polylineMode)
                ? (details) {
                    _placeFixedSizeDecoration(
                        _globalToCanvas(details.globalPosition, ctrl));
                  }
                : null,
            // 範囲選択中: 空エリアの 1 タップで選択を解除し、 選択モードも
            //   一緒に抜ける (= ユーザー報告: 「〜個選択」 の状態でどこかを
            //   押すと選択は解除されるのに選択モードだけ残るのが気になる)。
            onTap: provider.currentPage.pageType == 'bookshelf' &&
                    _inlineShelfEditNodeId != null
                ? () => _commitShelfInlineTextEdit(clearSelection: !_isDesktop)
                : (isRangeMode && !_rangeDragging && !_canvasLongPressActive
                    ? () {
                        if (_suppressNextRangeDeselect) {
                          setState(() => _suppressNextRangeDeselect = false);
                          return;
                        }
                        _removeOverlay();
                        setState(() {
                          _rangeSelectMode = false;
                          _rangeSelectedIds.clear();
                          _rangeSelectedDecorationIds.clear();
                          _rangeStart = null;
                          _rangeEnd = null;
                        });
                      }
                    : null),
            // 折れ線の確定は Esc / 最後の点をもう一度押す の 2 通り
            // (= ユーザー要望: ダブルクリックでの確定は要らない)。
            onDoubleTap: _polylineMode
                ? null
                : isRangeMode &&
                    !_rangeDragging &&
                    !_canvasLongPressActive
                ? () {
                    _removeOverlay();
                    setState(() {
                      _rangeSelectMode = false;
                      _rangeSelectedIds.clear();
                      _rangeSelectedDecorationIds.clear();
                      _rangeStart = null;
                      _rangeEnd = null;
                    });
                  }
                // ── 通常モード: 何もない場所をダブルクリックで選択解除 ──
                // = ユーザー要望。 ノードはそれ自身が onDoubleTap を消費するため
                //   (ジェスチャアリーナで手前のノードが勝つ)、 この空エリアの
                //   ダブルタップはノード上では発火しない。
                : (_drawingDecorationKind == null && !isMoveMode)
                    ? () {
                        _removeOverlay();
                        provider.selectNode(null);
                        setState(() {
                          _selectedDecorationId = null;
                          _selectedConnections.clear();
                          _clearConnectionBendDragFields(clearSelection: true);
                          _rangeSelectedIds.clear();
                          _rangeSelectedDecorationIds.clear();
                        });
                      }
                    : null,
            // ── 何もない場所を長押し ──────────────────
            // PC: 範囲選択ドラッグを開始 (既存仕様)。
            // モバイル (Android 等): クリップボードの画像をその位置に貼り付け
            //   (ユーザー要望「Android版でマップを長押ししたらクリップボードに
            //   保存した画像を出せる機能」)。
            // モバイルの範囲選択モード中は、 アプリ内クリップボード/切り取りが
            //   空なら反応しない (= 範囲選択操作中の長押しで OS クリップボード
            //   から意図しないノードが作られるのを防ぐ。 従来ガードの維持)。
            // ── インライン編集中はキャンバスの長押しを完全に無効化する ──
            // (= ユーザー要望: モバイルで要素の中のテキストを範囲選択しづらい)。
            // 原因: TextField の「長押しで単語選択」 と、 キャンバス側の
            //   「長押しで貼り付け」 が同じ長押しジェスチャーを取り合い、
            //   キャンバス側が勝つと選択が始まらなかった。 編集中は
            //   キャンバス側の長押し認識自体を外して TextField に譲る。
            onLongPressStart: (!isMoveMode &&
                    _inlineNodeEditNodeId == null &&
                    _inlineShelfEditNodeId == null &&
                    _nestedInlineEditNodeId == null &&
                    (_isDesktop
                        ? !isRangeMode
                        : (!isRangeMode ||
                            _clipboard.isNotEmpty ||
                            _cutNodeIds.isNotEmpty)))
                ? (details) {
                    final canvasPos =
                        _globalToCanvas(details.globalPosition, ctrl);
                    // ノードの上ではない場合のみ反応 (= 空エリア限定)
                    bool onNode = false;
                    for (final n in nodes.values) {
                      final r = Rect.fromLTWH(n.position.dx, n.position.dy,
                          n.width, n.visualHeight);
                      if (r.contains(canvasPos)) {
                        onNode = true;
                        break;
                      }
                    }
                    if (onNode) return;
                    if (_isDesktop) {
                      // PC: 範囲選択開始 (既存仕様)
                      setState(() {
                        _canvasLongPressActive = true;
                        _canvasLongPressStart = canvasPos;
                        _rangeSelectMode = true;
                        _rangeSelectedIds.clear();
                        _rangeSelectedDecorationIds.clear();
                        _rangeStart = canvasPos;
                        _rangeEnd = canvasPos;
                      });
                    } else {
                      // モバイル: 直近のコピーが「画像」 なら画像を優先して
                      // 貼り付ける (= ユーザー要望: 貼り付けボタンでは画像が
                      // 貼れるのに、 長押しだと古いアプリ内ノードが優先されて
                      // 画像が貼れなかった)。 画像でなければ従来どおり
                      // アプリ内コピー済みノード → OS 画像 の順。
                      // ── 直近の OS クリップボードの種類で貼り分ける
                      //    (= ユーザー要望: テキストならそのテキスト、 画像なら
                      //    その画像が貼り付けられるように) ──
                      //  1. 画像 → 画像ノード (読めない端末はピッカー保険)
                      //  2. テキスト → その文字のノード
                      //  3. どちらも無ければアプリ内コピー済みノード
                      //  4. それも無ければ画像扱いで試す (ピッカーが開く)
                      unawaited(() async {
                        if (await _osClipboardHasImage()) {
                          await _pasteClipboardImageAt(canvasPos,
                              imageOnly: true);
                          return;
                        }
                        String clipText = '';
                        try {
                          clipText = (await Clipboard.getData(
                                      Clipboard.kTextPlain))
                                  ?.text
                                  ?.trim() ??
                              '';
                        } catch (_) {}
                        if (!mounted) return;
                        if (clipText.isNotEmpty) {
                          final n =
                              provider.addNodeAtCenterReturning(canvasPos);
                          provider.updateNodeTitle(n.id, clipText);
                          return;
                        }
                        if (!_pasteAppClipboardAt(provider, canvasPos)) {
                          await _pasteClipboardImageAt(canvasPos,
                              imageOnly: true);
                        }
                      }());
                    }
                  }
                : null,
            onLongPressMoveUpdate: _isDesktop && _canvasLongPressActive
                ? (details) {
                    final canvasPos =
                        _globalToCanvas(details.globalPosition, ctrl);
                    setState(() {
                      _rangeEnd = canvasPos;
                    });
                  }
                : null,
            onLongPressEnd: _isDesktop && _canvasLongPressActive
                ? (_) {
                    // 範囲選択確定
                    if (_rangeStart != null && _rangeEnd != null) {
                      final rect = Rect.fromPoints(_rangeStart!, _rangeEnd!);
                      // 親に格納された (折りたたみ) 子ノードは除外。
                      final hiddenIds = provider.hiddenNodeIds;
                      for (final node in nodes.values) {
                        if (hiddenIds.contains(node.id)) continue;
                        final nodeRect = Rect.fromLTWH(node.position.dx,
                            node.position.dy, node.width, node.visualHeight);
                        if (rect.overlaps(nodeRect)) {
                          _rangeSelectedIds.add(node.id);
                        }
                      }
                      _addDecorationsInRect(rect);
                    }
                    final emptySelection = _rangeSelectedIds.isEmpty &&
                        _rangeSelectedDecorationIds.isEmpty;
                    setState(() {
                      _canvasLongPressActive = false;
                      _canvasLongPressStart = null;
                      _rangeStart = null;
                      _rangeEnd = null;
                      if (emptySelection) _rangeSelectMode = false;
                    });
                  }
                : null,
            onLongPressCancel: _isDesktop
                ? () {
                    if (_canvasLongPressActive || _rangeStart != null) {
                      _cancelInterruptedCanvasGesture();
                    }
                  }
                : null,
            onPanStart: _drawingDecorationKind != null
                ? (details) {
                    // ユーザー要望「直線や矢印線、 長方形等の図形を挿入できる
                    //   ようにして」 への対応。 挿入モード中はドラッグで装飾の
                    //   start/end を記録する。
                    final canvasPos =
                        _globalToCanvas(details.globalPosition, ctrl);
                    _handleDecorationPanStart(canvasPos);
                  }
                : (isRangeMode && !_rangeDragging && !_canvasLongPressActive
                    ? (details) {
                        final canvasPos =
                            _globalToCanvas(details.globalPosition, ctrl);
                        // 選択済みノード上なら何もしない（Listenerがドラッグ処理する）
                        if (_rangeSelectedIds.isNotEmpty) {
                          for (final id in _rangeSelectedIds) {
                            final n = nodes[id];
                            if (n == null) continue;
                            final r = Rect.fromLTWH(n.position.dx,
                                n.position.dy, n.width, n.visualHeight);
                            if (r.contains(canvasPos)) return;
                          }
                        }
                        // それ以外→範囲選択矩形
                        setState(() {
                          _rangeStart = canvasPos;
                          _rangeEnd = canvasPos;
                        });
                      }
                    : null),
            onPanUpdate: _drawingDecorationKind != null
                ? (details) {
                    final canvasPos =
                        _globalToCanvas(details.globalPosition, ctrl);
                    _handleDecorationPanUpdate(canvasPos);
                  }
                : (isRangeMode && !_rangeDragging
                    ? (details) {
                        final canvasPos =
                            _globalToCanvas(details.globalPosition, ctrl);
                        if (_rangeStart != null) {
                          setState(() {
                            _rangeEnd = canvasPos;
                          });
                        }
                        // ── 画面端に近づいたら自動スクロール ──
                        _autoScrollIfNeeded(details.globalPosition, ctrl);
                      }
                    : null),
            onPanEnd: _drawingDecorationKind != null
                ? (_) {
                    _handleDecorationPanEnd();
                  }
                : (isRangeMode && !_rangeDragging
                    ? (_) {
                        // ── 自動スクロールタイマーを必ず停止 ──
                        _stopEdgeScroll();
                        // 範囲選択確定
                        if (_rangeStart != null && _rangeEnd != null) {
                          final rect =
                              Rect.fromPoints(_rangeStart!, _rangeEnd!);
                          // 親に格納された (折りたたみ) 子ノードは除外。
                          final hiddenIds = provider.hiddenNodeIds;
                          for (final node in nodes.values) {
                            if (hiddenIds.contains(node.id)) continue;
                            final nodeRect = Rect.fromLTWH(
                                node.position.dx,
                                node.position.dy,
                                node.width,
                                node.visualHeight);
                            if (rect.overlaps(nodeRect)) {
                              _rangeSelectedIds.add(node.id);
                            }
                          }
                          _addDecorationsInRect(rect);
                        }
                        final emptySelection = _rangeSelectedIds.isEmpty &&
                            _rangeSelectedDecorationIds.isEmpty;
                        setState(() {
                          _rangeStart = null;
                          _rangeEnd = null;
                          if (emptySelection) _rangeSelectMode = false;
                        });
                        // ── 範囲選択が確定したら複数選択メニューを出す ──
                        // モバイルの範囲選択はこの onPanEnd 経路で確定する
                        // (長押し経路は貼り付け用で _canvasLongPressActive が
                        // 立たない)。 右上ボタン列廃止後、 ここでメニューを
                        // 出さないとモバイルでは一括AI/削除等の入口が無くなる
                        // (= ユーザー報告: 複数選択時の削除ボタン等が消えた)。
                        if (!emptySelection &&
                            _rangeSelectedIds.isNotEmpty &&
                            _selectedConnections.isEmpty) {
                          _showMultiNodeActionOverlay(context, provider, ctrl);
                        }
                      }
                    : null),
            onPanCancel: (_drawingDecorationKind != null || isRangeMode)
                ? _cancelInterruptedCanvasGesture
                : null,
            child: Builder(
              builder: (context) {
                final canvasSize = computeCanvasSize(nodes);
                // ── ギャラリーページ: キャンバスを中身 (+ボックス含む) ぴったりにして
                //    範囲外へはパンできないようにする (= ユーザー要望) ──
                final bool isShelf =
                    provider.currentPage.pageType == 'bookshelf';
                final canvasDim = isShelf
                    ? provider.bookshelfCanvasSize()
                    : Size(canvasSize, canvasSize);
                final double canvasW = canvasDim.width;
                final double canvasH = canvasDim.height;
                // 常設の +ボックス群 (= 埋めたセルの右と下のフロンティア)。
                final List<List<int>> frontierCells =
                    isShelf ? provider.bookshelfFrontierCells() : const [];
                final List<Rect> frontierRects =
                    isShelf ? provider.bookshelfFrontierRects() : const [];
                // ── ノード 1 個分のウィジェットを組む (= レイヤーごとに 2 回
                //    使うので関数に切り出した。 中身は従来と同一) ──
                Widget buildNodeWidget(MindMapNode node) {
                              final isMove = _moveModeNodeId == node.id;
                              final isRangeSelected =
                                  _rangeSelectedIds.contains(node.id);
                              AnchorDirection? highlight;
                              if (_currentSnap != null &&
                                  _currentSnap!.nodeId == node.id) {
                                highlight = _currentSnap!.toAnchor;
                              }
                              // 範囲ドラッグ時のポジション
                              Offset? posOverride;
                              bool dragging = false;
                              if (isMove && _movingPos != null) {
                                posOverride = _movingPos;
                                dragging = true;
                              } else if (_rangeDragging && isRangeSelected) {
                                posOverride = Offset(
                                  (node.position.dx + _rangeDragDelta.dx)
                                      .clamp(0.0, 20000.0),
                                  (node.position.dy + _rangeDragDelta.dy)
                                      .clamp(0.0, 20000.0),
                                );
                                dragging = true;
                              } else if (_groupDragIds.contains(node.id) &&
                                  _movingPos != null &&
                                  _groupDragStartPos != null) {
                                // ── 付箋グループのお仲間も一緒に動かす
                                //    (= ユーザー要望)。 掴んだノードの移動量を
                                //    そのまま乗せる。 ──
                                final d = _movingPos! - _groupDragStartPos!;
                                posOverride = Offset(
                                  (node.position.dx + d.dx).clamp(0.0, 20000.0),
                                  (node.position.dy + d.dy).clamp(0.0, 20000.0),
                                );
                                dragging = true;
                              }
                              return NodeWidget(
                                key: ValueKey(node.id),
                                node: node,
                                isCut: _cutNodeIds.contains(node.id),
                                isShelf: isShelf,
                                // ギャラリーで入れ替わる先の要素を枠で強調 (= ユーザー要望)
                                isSwapTarget: _shelfSwapTargetId == node.id,
                                // タイルに入り切らなかった文字を読めるようにする
                                //   (= ユーザー要望)。 切れている時だけボタンが出る。
                                onShowFullText: isShelf
                                    ? () => _showGalleryFullTextDialog(node.id)
                                    : null,
                                isSelected: _actionNodeId == node.id ||
                                    isMove ||
                                    isRangeSelected,
                                // モバイルの範囲選択モードで、複数選択中のノード上は
                                // 通常のパン (指でスライド) で即ドラッグ開始できるようにする。
                                // 長押しが要らなくなるので「選択 → 動かせない」感が解消。
                                enablePanDrag: !_isDesktop &&
                                    isRangeMode &&
                                    isRangeSelected &&
                                    _rangeSelectedIds.length > 1,
                                isSearchHit: _searchResultIds.contains(node.id),
                                isCurrentSearchResult: _searchResultIds.isNotEmpty &&
                                    _searchResultIndex < _searchResultIds.length &&
                                    _searchResultIds[_searchResultIndex] == node.id,
                                // ライトモード時は黄色ハイライトが見えづらいので濃い色を使うため
                                // テーマ情報を NodeWidget に渡す
                                isDarkMode: provider.isDarkMode,
                                positionOverride: posOverride,
                                forceDragging: dragging,
                                highlightAnchors: highlight == null
                                    ? const <AnchorDirection>{}
                                    : <AnchorDirection>{highlight},
                                // 接続ラベル「接続」の出し分け:
                                //   - 単一ドラッグ: ドラッグ中ノード自身に出す
                                //   - 範囲ドラッグ: 最も近接した「ソース選択ノード」に出す
                                //     (= _currentSnap.sourceNodeId が一致するノード)
                                currentSnap: (isMove ||
                                        (_rangeDragging &&
                                            _currentSnap?.sourceNodeId == node.id))
                                    ? _currentSnap
                                    : null,
                                onTap: isRangeMode
                                    ? () {
                                        setState(() {
                                          if (isRangeSelected) {
                                            _rangeSelectedIds.remove(node.id);
                                          } else {
                                            _rangeSelectedIds.add(node.id);
                                          }
                                        });
                                      }
                                    : isMoveMode
                                        ? () => _resetInteractionState()
                                        : () {
                                            // Ctrl+クリックで複数選択
                                            if (_isDesktop &&
                                                (HardwareKeyboard
                                                        .instance.isControlPressed ||
                                                    HardwareKeyboard
                                                        .instance.isMetaPressed)) {
                                              setState(() {
                                                _rangeSelectMode = true;
                                                if (_rangeSelectedIds
                                                    .contains(node.id)) {
                                                  _rangeSelectedIds.remove(node.id);
                                                  if (_rangeSelectedIds.isEmpty) {
                                                    _rangeSelectMode = false;
                                                  }
                                                } else {
                                                  _rangeSelectedIds.add(node.id);
                                                }
                                              });
                                              _removeOverlay();
                                              return;
                                            }
                                            if (_playlistLoadMoreInfo
                                                .containsKey(node.id)) {
                                              _handleLoadMoreNodeTap(
                                                  node.id, provider);
                                              return;
                                            }
                                            provider.selectNode(node.id);
                                            // 格納ノードなら展開ポップアップを表示。
                                            // ギャラリーの表紙は、 いきなり展開/格納せず
                                            //   「編集 / 削除 / 展開・格納」 のメニューを
                                            //   出す (= ユーザー要望: 表紙を押すといきなり
                                            //   開かず項目が出るように)。
                                            if (node.isContainer) {
                                              if (provider.currentPage.pageType ==
                                                  'bookshelf') {
                                                _showBookshelfCoverMenu(node);
                                              } else {
                                                _showContainerExpandPopup(
                                                    node.id, ctrl);
                                              }
                                              return;
                                            }
                                            setState(() {
                                              _selectedConnections.clear();
                                              _clearConnectionBendDragFields(
                                                  clearSelection: true);
                                            });
                                            _showActionButtons(node.id, ctrl);
                                          },
                                onDoubleTap: (isMoveMode || isRangeMode)
                                    ? null
                                    : () => _startInlineTitleEdit(context, node),
                                onLongPressStart: (isMoveMode && !isMove)
                                    ? null
                                    : isRangeMode
                                        ? (isRangeSelected &&
                                                _rangeSelectedIds.length > 1
                                            ? (globalPos) {
                                                // 範囲選択のグループドラッグ開始
                                                final canvasPos =
                                                    _globalToCanvas(globalPos, ctrl);
                                                _removeOverlay();
                                                HapticFeedback.mediumImpact();
                                                setState(() {
                                                  _rangeDragging = true;
                                                  _rangeDragAnchor = canvasPos;
                                                  _rangeDragDelta = Offset.zero;
                                                });
                                                // エッジスクロール開始
                                                _lastDragGlobalPos = globalPos;
                                                _edgeScrollCtrl = ctrl;
                                                _startEdgeScrollTimer();
                                              }
                                            : null)
                                        : (globalPos) {
                                            // PC/モバイル共通: ドラッグでノード移動。
                                            //   デスクトップでは NodeWidget の onPanStart
                                            //   (マウスドラッグ) がこの同じ
                                            //   onLongPressStart コールバックを呼ぶため、
                                            //   ここを「削除確認」にしてしまうとドラッグ
                                            //   移動が削除ダイアログに化けて移動できなく
                                            //   なる。削除は右クリックメニュー / アクション
                                            //   バーの削除ボタンから行う。
                                            _onLongPressNodeStart(
                                                node.id, globalPos, ctrl);
                                          },
                                onLongPressMoveUpdate: isRangeMode
                                    ? (_rangeDragging
                                        ? (globalPos) {
                                            final canvasPos =
                                                _globalToCanvas(globalPos, ctrl);
                                            if (_rangeDragAnchor != null) {
                                              setState(() {
                                                _rangeDragDelta =
                                                    canvasPos - _rangeDragAnchor!;
                                              });
                                            }
                                            // エッジスクロール更新
                                            _autoScrollIfNeeded(globalPos, ctrl);
                                          }
                                        : null)
                                    : (globalPos) {
                                        // PC/モバイル共通: ドラッグ中はノードを移動。
                                        _onLongPressNodeMove(globalPos, ctrl);
                                      },
                                onLongPressEnd: isRangeMode
                                    ? (_rangeDragging
                                        ? () {
                                            // グループドラッグ確定
                                            _stopEdgeScroll();
                                            provider.moveNodes(
                                                Set.of(_rangeSelectedIds),
                                                _rangeDragDelta);
                                            setState(() {
                                              _rangeDragging = false;
                                              _rangeDragAnchor = null;
                                              _rangeDragDelta = Offset.zero;
                                            });
                                            _restoreMultiNodeActionOverlayAfterRangeDrag(
                                                provider, ctrl);
                                          }
                                        : null)
                                    : () {
                                        // PC/モバイル共通: ドラッグ確定でノード移動を確定。
                                        _onLongPressNodeEnd();
                                      },
                                onThumbnailTap: _nodeHasLink(node)
                                    ? () {
                                        provider.selectNode(node.id);
                                        _openNodeLink(node);
                                      }
                                    : null,
                                onAttachmentTap:
                                    (node.attachmentPath ?? '').isNotEmpty
                                        ? () {
                                            provider.selectNode(node.id);
                                            _openAttachment(node.attachmentPath!,
                                                nodeId: node.id);
                                          }
                                        : null,
                                // サブマップ埋め込みピル → 履歴に積んで遷移
                                onLinkedMapTap: (node.linkedPageId ?? '').isNotEmpty
                                    ? () => _navigateToPage(node.linkedPageId!)
                                    : null,
                                // ── メモノードのタイムスタンプタップ ──
                                // 動画メモ (= NodeContentType.memo + memoText が `[mm:ss]`
                                //   形式) で発火。 親動画ノードを辿って、 その動画を
                                //   タップされた秒数からシーク再生開始する。
                                onMemoTimestampTap:
                                    node.contentType == NodeContentType.memo
                                        ? (sec) => _jumpFromMemoTimestamp(node, sec)
                                        : null,
                                onRightClick: _isDesktop
                                    ? (globalPos) {
                                        provider.selectNode(node.id);
                                        _showNodeContextMenu(
                                            node.id, globalPos, ctrl);
                                      }
                                    : null,
                                onInlineEditingStarted: !_isDesktop
                                    ? () {
                                        if (!mounted) return;
                                        setState(
                                            () => _nestedInlineEditNodeId = node.id);
                                        _scheduleInlineEditorReveal(node.id);
                                      }
                                    : null,
                                onInlineEditingEnded: !_isDesktop
                                    ? () {
                                        if (!mounted ||
                                            _nestedInlineEditNodeId != node.id) {
                                          return;
                                        }
                                        setState(
                                            () => _nestedInlineEditNodeId = null);
                                      }
                                    : null,
                                onRequestScreenFocus: _isDesktop
                                    ? () {
                                        if (mounted)
                                          _keyboardFocusNode.requestFocus();
                                      }
                                    : null,
                                defaultTitleFontSize: provider.defaultTitleFontSize,
                                defaultMemoFontSize: provider.defaultMemoFontSize,
                                uploadProgress: provider.getUploadProgress(node.id),
                                showResizeHandles: _actionNodeId == node.id,
                                onSizeChanged: (w, h, dx, dy) {
                                  provider.updateNodeSize(node.id, w, h);
                                  if (dx != 0 || dy != 0) {
                                    final cur = provider.nodes[node.id];
                                    if (cur != null) {
                                      provider.updateNodePosition(
                                          node.id,
                                          Offset(
                                            (cur.position.dx + dx)
                                                .clamp(0.0, 20000.0),
                                            (cur.position.dy + dy)
                                                .clamp(0.0, 20000.0),
                                          ));
                                    }
                                  }
                                },
                              );
                }
                // 背景パネルはブロック (ノード) の後ろにだけ描く (= +ボックスや
                // 空きの後ろには描かない = ユーザー要望)。
                final List<Rect> shelfRects = isShelf
                    ? nodes.values
                        .map((n) => Rect.fromLTWH(n.position.dx, n.position.dy,
                            n.width, n.visualHeight))
                        .toList()
                    : const <Rect>[];
                return Container(
                  width: canvasW,
                  height: canvasH,
                  // ── スクロール可能範囲の外枠は描かない (= ユーザー要望:
                  //    新規マップで左端に線が出るのが気になる)。
                  //    範囲はスクロールバーで分かるので枠は不要。 ──
                  decoration: null,
                  child: Stack(
                    key: _canvasKey,
                    clipBehavior: Clip.none,
                    children: [
                      Positioned.fill(
                        child: GestureDetector(
                          behavior: HitTestBehavior.opaque,
                          // ── タップ位置を onTapDown で記録 ──
                          // onTap は位置を持たないので、 図形ヒットテスト用に
                          // ここでキャンバス座標を控えておく。 挿入モード中も記録する
                          // (タップ = ドラッグではない ので既存図形の選択に使える)。
                          onTapDown: isRangeMode
                              ? null
                              : (details) {
                                  _pendingTapCanvasPos = _globalToCanvas(
                                      details.globalPosition, ctrl);
                                },
                          // ── タップ確定: 範囲選択解除 or 図形の選択/解除 ──
                          // onTapUp ではなく onTap を使うことで確実に発火させる。
                          onTap: () {
                            if (isShelf && _inlineShelfEditNodeId != null) {
                              _commitShelfInlineTextEdit(
                                  clearSelection: !_isDesktop);
                              return;
                            }
                            if (isRangeMode) {
                              // 直前のオーバーレイ閉じクリックはカウントしない
                              if (_suppressNextRangeDeselect) {
                                setState(
                                    () => _suppressNextRangeDeselect = false);
                                return;
                              }
                              setState(() {
                                _rangeSelectMode = false;
                                _rangeSelectedIds.clear();
                                _rangeSelectedDecorationIds.clear();
                                _rangeStart = null;
                                _rangeEnd = null;
                              });
                              return;
                            }
                            final p = _pendingTapCanvasPos;
                            if (p == null) return;
                            if (_clearShelfLineSelectionIfOutside(
                                provider, p)) {
                              if (isShelf && !_isDesktop) {
                                _clearShelfElementSelection(provider);
                              }
                              return;
                            }
                            final scale = ctrl.value.getMaxScaleOnAxis();
                            // ── 挿入モード中のタップ ──
                            // 描画はドラッグ (onPan) で行うので、 タップ (= ドラッグ
                            //   ではない) は既存図形の選択に使える。 図形に当たれば
                            //   挿入モードを抜けて選択 (ハンドルが出る)、 外れたら
                            //   挿入モードを維持して続けて描けるようにする。
                            if (_drawingDecorationKind != null) {
                              final hit = _decorationHitTest(p, scale);
                              if (hit != null) {
                                _exitShapeInsertMode();
                                setState(() => _selectedDecorationId = hit);
                              }
                              return;
                            }
                            final decorationHit = _decorationHitTest(p, scale);
                            _handleCanvasTapForDecoration(p, scale);
                            if (isShelf && decorationHit == null) {
                              // 編集中でない通常選択でも、ギャラリーの空白タップは
                              // provider 側の選択を含めて完全に解除する。
                              _clearShelfElementSelection(provider);
                            }
                          },
                          onSecondaryTapUp: _isDesktop && !isRangeMode
                              ? (details) => _showCanvasContextMenu(
                                  details.globalPosition, ctrl, provider)
                              : null,
                          child: const SizedBox.expand(),
                        ),
                      ),

                      // ── カスタム背景画像は表示領域いっぱいの壁紙として
                      //   InteractiveViewer の外側 (_buildInfinitePageBackground)
                      //   に移動した (= ユーザー要望: 枠の外まで背景を続ける)。
                      //   ここではキャンバス内には描かない。

                      RepaintBoundary(
                        child: CustomPaint(
                          size: isShelf
                              ? Size(canvasW, canvasH)
                              : Size(canvasSize, canvasSize),
                          // ギャラリーページは網目グリッドではなく、 木目調 + 棚板の
                          // 背景にする (= ユーザー要望: 後ろの網目を別のものに)。
                          painter: isShelf
                              ? _BookshelfBackgroundPainter(
                                  tileRects: shelfRects,
                                  isDark: provider.isDarkMode,
                                )
                              // 木目テンプレートでは方眼を描かない
                              // (= ユーザー要望)。
                              : _mapBgHidesGrid(
                                      provider.currentPage.backgroundImagePath)
                                  ? null
                                  : _GridPainter(
                                      isDesktop: !kIsWeb &&
                                          (Platform.isWindows ||
                                              Platform.isMacOS ||
                                              Platform.isLinux),
                                      isDark: provider.isDarkMode,
                                    ),
                        ),
                      ),
                      // ── ギャラリー: タイル群の背後に敷板を敷く ──
                      //   (= ユーザー要望: 背景は設定できるようにしつつ、
                      //    ブロックの隙間から模様が点在して見えると気が散る)。
                      //   タイル全体を囲む矩形を少し広げて単色で塗るので、
                      //   隙間だけが同じ色で埋まり、 板の外は壁紙が見える。
                      if (isShelf)
                        CustomPaint(
                          size: Size(canvasSize, canvasSize),
                          painter: _ShelfBackdropPainter(
                            nodes: nodes,
                            isDark: provider.isDarkMode,
                            // ＋ブロックの矩形も敷板に含める (= ユーザー要望:
                            //   ＋ブロックが出ている隙間まで塞ぐ)。
                            addRects: frontierRects,
                          ),
                        ),
                      // ── グループ背景（付箋風にノードの後ろに表示）──
                      if (provider.namedGroups.isNotEmpty) ...[
                        Builder(builder: (_) {
                          final co = _groupColorOverrides(provider);
                          final fs = _groupFontSizeOverrides(provider);
                          final ff = _groupFontFamilyOverrides(provider);
                          final pd = _groupPaddingOverrides(provider);
                          return CustomPaint(
                            size: Size(canvasSize, canvasSize),
                            painter: _GroupBackgroundPainter(
                              groups: provider.namedGroups,
                              nodes: nodes,
                              colorOverrides: co,
                              fontSizeOverrides: fs,
                              fontFamilyOverrides: ff,
                              paddingOverrides: pd,
                              isDark: provider.isDarkMode,
                            ),
                          );
                        }),
                        // ── グループラベルのタップ領域 ──
                        ..._buildGroupLabelTaps(provider, nodes, ctrl),
                        // ── グループ枠の拡張ハンドル ──
                        ..._buildGroupResizeHandles(provider, nodes, ctrl),
                      ],
                      // ── 装飾図形の描画 (= 直線/矢印/長方形/楕円) ──
                      // ユーザー要望「直線や矢印線、 長方形等の図形を挿入できる
                      //   ようにして」 への対応。 provider.decorations を読み取って、
                      //   CustomPaint で描画する。 ノードと同じキャンバス座標系で
                      //   描かれるので、 マップのパン/ズームに追従する。
                      //
                      //   選択中の装飾 (= _selectedDecorationId) は強調表示。
                      // ── 図形レイヤー (タップで直接選択できるようにする) ──
                      // _DecorationPainter.hitTest が図形上で true を返すので、
                      //   deferToChild により「図形の上のタップ」 だけをここで拾える。
                      //   図形以外のタップは透過して下の fill (= 選択解除) に届く。
                      //   これで下層 fill のヒットテストに依存せず確実に選択できる。
                      GestureDetector(
                        behavior: HitTestBehavior.deferToChild,
                        onTapDown: (d) => _pendingTapCanvasPos =
                            _globalToCanvas(d.globalPosition, ctrl),
                        onTap: () {
                          final p = _pendingTapCanvasPos;
                          if (p == null) return;
                          final scale = ctrl.value.getMaxScaleOnAxis();
                          final hit = _decorationHitTest(p, scale);
                          if (hit != null) {
                            if (_drawingDecorationKind != null) {
                              _exitShapeInsertMode();
                            }
                            setState(() => _selectedDecorationId = hit);
                          }
                        },
                        child: CustomPaint(
                          size: Size(canvasSize, canvasSize),
                          painter: _DecorationPainter(
                            decorations: _resolvedDecorations(provider),
                            selectedId: _selectedDecorationId,
                            rangeSelectedIds: _rangeSelectedDecorationIds,
                            rangeDragDelta:
                                _rangeDragging ? _rangeDragDelta : Offset.zero,
                            hitScale: ctrl.value.getMaxScaleOnAxis(),
                            // レイヤー 4〜5 はノードより手前の別ペインターで
                            // 描く (= 5 段階レイヤー)。 ここは 1〜3 だけ。
                            layers: const {1, 2, 3},
                          ),
                        ),
                      ),
                      // ── 接続線はノードと同じ層 (レイヤー3相当) に描く ──
                      // (= ユーザー報告: 接続線が図形のレイヤー1より下に
                      //  来てしまう)。 図形レイヤー1〜3 の後、 ノードの直前。
                      RepaintBoundary(
                        child: CustomPaint(
                        size: Size(canvasSize, canvasSize),
                        painter: ConnectionPainter(
                            // 設定した線の形を既存の接続にも反映する
                            // (= これまで渡しておらず既定のままだった)。
                            lineStyle: provider.connectionLineStyle,
                            nodes: _movingNodes(nodes),
                            // 格納ノード処理:
                            //   両端が隠れているノード → 非表示
                            //   片方だけが隠れている → 見えている側と「その隠れたノードの
                            //   格納先コンテナ」の接続に置換し、コンテナが外部と接続しているように見せる
                            // ギャラリー(本棚)では要素同士を繋ぐリンクは出さない
                            //   (= ユーザー要望)。
                            connections: provider.currentPage.pageType ==
                                    'bookshelf'
                                ? const <NodeConnection>[]
                                // レイヤー順に描く (= ユーザー要望: レイヤーは
                                // リンクにも適用される)。 大きい層ほど手前。
                                : (_cullConnections(
                                    _effectiveConnections(nodes, connections),
                                    nodes,
                                    cullRect)
                                  ..sort((a, b) =>
                                      a.layer.compareTo(b.layer))),
                            selectedConnections: _selectedConnections,
                            selectedBendIndices:
                                _selectedBendIndicesFor(connections),
                            // ライトモード時に pale な黄色の接続線を濃く補正するため
                            isDarkMode: provider.isDarkMode,
                            // 背景 (壁紙) の明暗に合わせて線色を自動調整
                            // (= ユーザー要望)。
                            darkBackground: _pageBackgroundIsDark(
                                provider, provider.currentPage)),
                        ),
                      ),
                      // ── 選択中の図形のハンドル (移動 / リサイズ) ──
                      // ユーザー要望「挿入した図形を選択して移動・大きさや形状を
                      //   変えられるように」 への対応。 中央=移動、 始点/終点=リサイズ。
                      ..._buildDecorationHandles(provider, ctrl),
                      // ── 折れ線の作りかけプレビュー (= ユーザー要望) ──
                      //    今までに置いた節点 + マウス位置までの 1 本。
                      if (_polylineMode && _polylinePoints.isNotEmpty)
                        IgnorePointer(
                          child: CustomPaint(
                            size: Size(canvasSize, canvasSize),
                            painter: _DecorationPainter(
                              decorations: [
                                MapDecoration(
                                  id: '__preview_poly__',
                                  kind: MapDecorationKind.polyline,
                                  start: _polylinePoints.first,
                                  end: _polylineCursor ?? _polylinePoints.last,
                                  colorRgb: _shapeColorRgb,
                                  strokeWidth: _shapeStrokeWidth,
                                  points: [
                                    ..._polylinePoints,
                                    if (_polylineCursor != null &&
                                        _polylineCursor != _polylinePoints.last)
                                      _polylineCursor!,
                                  ],
                                ),
                              ],
                              selectedId: null,
                            ),
                          ),
                        ),
                      // 描画中プレビュー (= 装飾挿入モードでドラッグ中)
                      if (_drawingDecorationKind != null &&
                          _drawingDecorationStart != null &&
                          _drawingDecorationEnd != null)
                        IgnorePointer(
                          child: CustomPaint(
                            size: Size(canvasSize, canvasSize),
                            painter: _DecorationPainter(
                              decorations: [
                                MapDecoration(
                                  id: '__preview__',
                                  kind: _drawingDecorationKind!,
                                  start: _drawingDecorationStart!,
                                  end: _drawingDecorationEnd!,
                                  colorRgb: _shapeColorRgb,
                                  strokeWidth: _shapeStrokeWidth,
                                ),
                              ],
                              selectedId: null,
                            ),
                          ),
                        ),
                      // 裁断線のプレビュー描画（始点が設定済みの時）
                      if (_cutMode && _cutStartPoint != null)
                        IgnorePointer(
                          child: CustomPaint(
                            size: Size(canvasSize, canvasSize),
                            painter: _CutPreviewPainter(
                              start: _cutStartPoint!,
                              end: _cutPreviewEnd ?? _cutStartPoint!,
                            ),
                          ),
                        ),
                      // 裁断直後の「実行済み線」を一瞬表示（フェードアウト）
                      if (_cutFadingLine != null && _cutFadingLine!.length == 2)
                        IgnorePointer(
                          child: CustomPaint(
                            size: Size(canvasSize, canvasSize),
                            painter: _CutPreviewPainter(
                              start: _cutFadingLine![0],
                              end: _cutFadingLine![1],
                              solid: true,
                            ),
                          ),
                        ),

                      // 接続線のタップ判定レイヤー（ノードの下）
                      if (!isMoveMode && !isRangeMode)
                        Positioned.fill(
                          child: GestureDetector(
                            behavior: HitTestBehavior.translucent,
                            onTapUp: (details) {
                              if (_suppressConnectionTapAfterBendDrag) {
                                _suppressConnectionTapAfterBendDrag = false;
                                return;
                              }
                              // 並び替えモード中の解除挙動:
                              //   モバイル → シングルタップで解除 (ダブルタップは指で狙いにくいため)
                              //   デスクトップ → ダブルクリック (誤解除防止)
                              // モバイル版で接続線タップ等と競合する懸念があるが、
                              // 並び替えモード中は誤操作防止の方が優先度が高い。
                              if (_reorderHeaderMode && !_isDesktop) {
                                _exitHeaderReorderMode();
                                return;
                              }
                              // 基準位置設定モード
                              if (_settingRefMode) {
                                final canvasPos = _globalToCanvas(
                                    details.globalPosition, ctrl);
                                final pageId = provider.currentPage.id;
                                setState(() {
                                  _referencePos = canvasPos;
                                  _pageReferencePositions[pageId] = canvasPos;
                                  _showRefMarker = true;
                                  _settingRefMode = false;
                                });
                                _saveReferencePositions();
                                Future.delayed(const Duration(seconds: 3), () {
                                  if (mounted)
                                    setState(() => _showRefMarker = false);
                                });
                                return;
                              }
                              // ── 図形 (装飾) の選択を最優先で判定 ──
                              // この接続線タップ判定レイヤーは装飾レイヤーより上に
                              //   重なっており、 タップを先取りしてしまうため、 図形の
                              //   選択がここまで到達していなかった (= 図形をタップしても
                              //   反応しない原因)。 ここで図形のヒットテストを行い、
                              //   当たれば選択して終了する。
                              final canvasPos =
                                  _globalToCanvas(details.globalPosition, ctrl);
                              final scale = ctrl.value.getMaxScaleOnAxis();
                              if (_hitConnectionBendPoint(
                                      canvasPos, provider, scale) !=
                                  null) {
                                return;
                              }
                              final decoHit =
                                  _decorationHitTest(canvasPos, scale);
                              if (decoHit != null) {
                                if (_drawingDecorationKind != null) {
                                  _exitShapeInsertMode();
                                }
                                setState(() => _selectedDecorationId = decoHit);
                                return;
                              }
                              // 図形に当たらなかった場合、 選択中の図形があれば解除
                              if (_selectedDecorationId != null) {
                                setState(() => _selectedDecorationId = null);
                              }
                              _onConnectionTap(
                                  details.globalPosition, ctrl, provider);
                            },
                            // デスクトップ: ダブルクリック解除 (誤解除防止)
                            onDoubleTap: _reorderHeaderMode && _isDesktop
                                ? _exitHeaderReorderMode
                                : null,
                            onSecondaryTapUp: _isDesktop
                                ? (details) => _showCanvasContextMenu(
                                    details.globalPosition, ctrl, provider)
                                : null,
                          ),
                        ),

                      // ── グループ領域のダブルタップ領域（ノードより下に配置）──
                      if (provider.namedGroups.isNotEmpty)
                        ..._buildGroupAreaTaps(provider, nodes, ctrl),

                      // ── ギャラリーの「+ボックス」 群 (= 埋めたセルの右と下に出る白い箱。
                      //    ここに PDF/画像/動画/テキストを入れていく = ユーザー要望) ──
                      // タップ範囲はセル全体にする (= ユーザー報告: モバイルで
                      // 1 行目の右端の空スロットを埋められない)。 見た目の白い
                      // 箱は中央に同じ大きさで描き、 当たり判定だけ広げる。
                      if (isShelf)
                        for (int fi = 0;
                            fi < frontierRects.length &&
                                fi < frontierCells.length;
                            fi++)
                          Builder(builder: (_) {
                            final cellRect = provider.bookshelfCellRect(
                                frontierCells[fi][0], frontierCells[fi][1]);
                            final box = frontierRects[fi];
                            final hit = cellRect ?? box;
                            return Positioned(
                              left: hit.left,
                              top: hit.top,
                              width: hit.width,
                              height: hit.height,
                              child: Center(
                                child: SizedBox(
                                  width: box.width,
                                  height: box.height,
                                  child: _buildShelfAddBox(provider, ctrl,
                                      cell: frontierCells[fi]),
                                ),
                              ),
                            );
                          }),

                      // ── レイヤー順に描く (= ユーザー要望: レイヤーはノードにも
                      //    適用される)。 小さい層が奥、 大きい層が手前。
                      //    レイヤー 4〜5 のノードは、 この後の「図形レイヤー
                      //    4〜5」 より更に手前に置きたいので、 ここでは 1〜3 だけ
                      //    描き、 4〜5 は下でまとめて描く。 ──
                      // ── レイヤー順に描く (= ユーザー要望: レイヤーはノードや
                      //    リンクにも適用される)。 小さい層が奥、 大きい層が手前。
                      //    レイヤー 4〜5 のノードは「図形レイヤー 4〜5」 より
                      //    更に手前に置きたいので、 ここでは 1〜3 だけ描き、
                      //    4〜5 は図形の後 (下の方) でまとめて描く。 ──
                      ...(nodes.values.toList()
                            ..sort((a, b) => a.layer.compareTo(b.layer)))
                          .where((n) => n.layer <= 3)
                          // 格納ノード内に隠されているノードは画面に描画しない
                          .where((n) => n.hiddenInContainer == null)
                          // ── 表示範囲の外は作らない (= ユーザー報告: 大量の
                          //    ファイルを読み込むとカクついて動かなくなる) ──
                          //    ノードが多い時だけ間引く。 操作中のノードは
                          //    画面外でも必ず作る。 矩形は 1 フレームに 1 回
                          //    だけ計算する (cullRect)。
                          .where((n) =>
                              cullRect == null ||
                              _mustRenderNode(n.id) ||
                              _nodeIntersects(n, cullRect))
                          .map(buildNodeWidget),

                      // ── 図形レイヤー 4〜5 (= ユーザー要望: 5 段階レイヤー)。
                      //    ノードより手前に描く。 タップは下 (接続線タップ層の
                      //    図形ヒットテスト) が拾うので表示専用。 ──
                      IgnorePointer(
                        child: CustomPaint(
                          size: Size(canvasSize, canvasSize),
                          painter: _DecorationPainter(
                            decorations: _resolvedDecorations(provider),
                            selectedId: _selectedDecorationId,
                            rangeSelectedIds: _rangeSelectedDecorationIds,
                            rangeDragDelta:
                                _rangeDragging ? _rangeDragDelta : Offset.zero,
                            hitScale: ctrl.value.getMaxScaleOnAxis(),
                            layers: const {4, 5},
                          ),
                        ),
                      ),

                      // ── 手前のレイヤー (4〜5) のノード (= ユーザー要望:
                      //    レイヤーはノードにも適用される)。 図形の 4〜5 より
                      //    更に手前に描く。 ──
                      ...(nodes.values.toList()
                            ..sort((a, b) => a.layer.compareTo(b.layer)))
                          .where((n) => n.layer >= 4)
                          // 格納ノード内に隠されているノードは画面に描画しない
                          .where((n) => n.hiddenInContainer == null)
                          // ── 表示範囲の外は作らない (= ユーザー報告: 大量の
                          //    ファイルを読み込むとカクついて動かなくなる) ──
                          //    ノードが多い時だけ間引く。 操作中のノードは
                          //    画面外でも必ず作る。 矩形は 1 フレームに 1 回
                          //    だけ計算する (cullRect)。
                          .where((n) =>
                              cullRect == null ||
                              _mustRenderNode(n.id) ||
                              _nodeIntersects(n, cullRect))
                          .map(buildNodeWidget),

                      // ── 共同編集: 他の参加者が編集中の要素に枠と名前を
                      //    重ねる (= ユーザー要望: どのユーザーが操作して
                      //    いるか表示されるように)。 表示だけなので
                      //    IgnorePointer でタップは下へ通す。
                      //    共有中のページを開いている時だけ。 ──
                      if (provider.liveActive &&
                          provider.livePageId == provider.currentPage.id)
                        for (final n in nodes.values
                            .where((n) => n.hiddenInContainer == null))
                          if (provider.liveLockOwnerOf(n.id) != null)
                            Positioned(
                              left: n.position.dx,
                              top: n.position.dy,
                              width: n.width,
                              height: n.visualHeight,
                              child: IgnorePointer(
                                child: _LiveLockBadge(
                                  color: Color(
                                      provider.liveLockOwnerOf(n.id)!.colorRgb),
                                  name: provider.liveLockOwnerOf(n.id)!.name,
                                ),
                              ),
                            ),

                      ..._buildSelectedConnectionRoleBadges(
                          provider, _movingNodes(nodes)),

                      if (!isShelf && _inlineNodeEditNodeId != null)
                        _buildNodeInlineTextEditor(provider),

                      // ── ギャラリーの行/列 掴みハンドル (= ユーザー要望: 行単位/
                      //    列単位でドラッグして並べ替え)。 ノードの上に重ねて掴める。 ──
                      if (isShelf && !isRangeMode)
                        ..._buildShelfReorderHandles(provider, ctrl),

                      if (isShelf && _inlineShelfEditNodeId != null)
                        _buildShelfInlineTextEditor(provider),

                      // ── 要素の説明書き (= ユーザー要望: F3 で要素の上に
                      //    書ける注釈)。 ノードの外側に浮かせて置くので、
                      //    ノードの寸法や当たり判定には影響しない。
                      //    クリックでその場編集できる。 ──
                      ..._buildNodeCaptions(provider, nodes, canvasSize),

                      // ── グループ非メンバー表示（ノードの上に描画）──
                      if (provider.namedGroups.isNotEmpty)
                        IgnorePointer(
                          child: Builder(builder: (_) {
                            final co = _groupColorOverrides(provider);
                            return CustomPaint(
                              size: Size(canvasSize, canvasSize),
                              painter: _GroupForegroundPainter(
                                groups: provider.namedGroups,
                                nodes: nodes,
                                colorOverrides: co,
                              ),
                            );
                          }),
                        ),

                      // 範囲選択矩形の描画
                      if (_rangeStart != null && _rangeEnd != null)
                        Positioned.fill(
                          child: IgnorePointer(
                            child: CustomPaint(
                              painter: _RangeSelectionPainter(
                                start: _rangeStart!,
                                end: _rangeEnd!,
                              ),
                            ),
                          ),
                        ),

                      // 兄弟スナップガイド
                      if (_siblingGuidePos != null && _moveModeNodeId != null)
                        Positioned(
                          left: _siblingGuidePos!.dx - 2,
                          top: _siblingGuidePos!.dy - 2,
                          child: IgnorePointer(
                            child: Container(
                              width: 144,
                              height: 60,
                              decoration: BoxDecoration(
                                border: Border.all(
                                    color: const Color(0xFF4FC3F7)
                                        .withValues(alpha: 0.7),
                                    width: 2),
                                borderRadius: BorderRadius.circular(18),
                                color: const Color(0xFF4FC3F7)
                                    .withValues(alpha: 0.08),
                              ),
                              child: Center(
                                child: Text(
                                    context
                                        .read<MindMapProvider>()
                                        .t('sibling.placeHere'),
                                    style: const TextStyle(
                                        color: Color(0xFF4FC3F7),
                                        fontSize: 11,
                                        fontWeight: FontWeight.w600)),
                              ),
                            ),
                          ),
                        ),

                      // 基準位置マーカー（設定直後の一時表示）
                      if (_showRefMarker)
                        Builder(builder: (_) {
                          final pid = provider.currentPage.id;
                          final pos =
                              _pageReferencePositions[pid] ?? _referencePos;
                          return Positioned(
                            left: pos.dx - 18,
                            top: pos.dy - 18,
                            child: IgnorePointer(
                              child: AnimatedOpacity(
                                opacity: 1.0,
                                duration: const Duration(milliseconds: 300),
                                child: Container(
                                  width: 36,
                                  height: 36,
                                  decoration: BoxDecoration(
                                    shape: BoxShape.circle,
                                    color: const Color(0xFF43B97F)
                                        .withValues(alpha: 0.2),
                                    border: Border.all(
                                        color: const Color(0xFF43B97F),
                                        width: 2.5),
                                    boxShadow: [
                                      BoxShadow(
                                        color: const Color(0xFF43B97F)
                                            .withValues(alpha: 0.4),
                                        blurRadius: 16,
                                        spreadRadius: 4,
                                      ),
                                    ],
                                  ),
                                  child: const Icon(Icons.close_rounded,
                                      color: Color(0xFF43B97F), size: 22),
                                ),
                              ),
                            ),
                          );
                        }),
                    ],
                  ),
                );
              },
            ),
          );
        },
      ),
    );
  }

  // ─── カレンダー表示 ──────────────────────────────────────────────────
  /// カレンダーモードで表示する月間カレンダー。
  /// 上部に月ナビゲーション、グリッドで日付セルを表示し、
  /// セル内にその日のイベントを簡易表示。セルタップで追加/編集ダイアログ。
  Widget _buildCalendarView(BuildContext context, MindMapProvider provider) {
    final year = _calendarMonth.year;
    final month = _calendarMonth.month;
    final firstDay = DateTime(year, month, 1);
    final lastDay = DateTime(year, month + 1, 0);
    // 月の最初の週の開始（日曜始まり）: firstDay の weekday (月=1..日=7) から計算
    // DateTime.weekday は Mon=1..Sun=7。日曜始まりなら Sun=0 に変換
    final startOffset = firstDay.weekday % 7; // Sun=0..Sat=6
    final daysInMonth = lastDay.day;
    final totalCells = ((startOffset + daysInMonth) / 7).ceil() * 7;

    // 「今日」の判定は provider のカレンダー時刻 (タイムゾーン考慮) を使う。
    // 言語/国に応じて異なる時差で「今日」が決まる。
    final todayKey = _dateKey(provider.calendarNow());

    // モバイル下部には 2×6 グリッドのツールバー (開いた状態で高さ ~96px)
    // がカレンダーの上に重なって描画されるため、最終週が隠れないよう
    // 下方向にパディングを確保する。
    // 閉じていても開いていても大体同じ余白を取る (トグル時のガタつき防止)。
    // デスクトップ版はツールバー自体が非表示なので詰める。
    final double bottomReserve = _isDesktop ? 12.0 : 110.0;

    return Container(
      color: provider.isDarkMode
          ? const Color(0xFF0B0B1E)
          : const Color(0xFFD8D8D4),
      // 全方向 12px から、上と左右は 12px, 下だけ可変 (ツールバー分確保)
      padding:
          EdgeInsets.only(left: 12, right: 12, top: 6, bottom: bottomReserve),
      child: Column(
        children: [
          // ── カレンダーを閉じる ──
          // ×アイコンのみのコンパクトなボタン (テキストは省略 — × は普遍的に閉じる意)
          Row(children: [
            IconButton(
              tooltip: provider.t('cal.close'),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints(minWidth: 36, minHeight: 36),
              icon: Icon(Icons.close_rounded,
                  color: provider.isDarkMode ? Colors.white70 : Colors.black87,
                  size: 22),
              onPressed: () {
                setState(() => _calendarMode = false);
                _refreshFloatingOverlays();
              },
            ),
            // ── タイムゾーン設定 ──
            // 言語に応じた標準時を選択するダイアログ。
            // 現在のラベルがあればバッジで表示。
            IconButton(
              tooltip: provider.t('cal.tz.title'),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints(minWidth: 36, minHeight: 36),
              icon: Stack(clipBehavior: Clip.none, children: [
                Icon(Icons.public_rounded,
                    color:
                        provider.isDarkMode ? Colors.white54 : Colors.black54,
                    size: 20),
                if (provider.calendarTzOffsetMinutes != null)
                  Positioned(
                    right: -2,
                    top: -2,
                    child: Container(
                      width: 8,
                      height: 8,
                      decoration: const BoxDecoration(
                        color: Color(0xFFFFB347),
                        shape: BoxShape.circle,
                      ),
                    ),
                  ),
              ]),
              onPressed: () => _showCalendarTimezoneDialog(context, provider),
            ),
            // ── 右端: グループ閲覧ユーザー切替 (Maxプラン限定) ──
            const Spacer(),
            _buildCalendarViewerSwitcher(provider),
          ]),
          // 月ナビゲーション (高さを詰める)
          Row(children: [
            IconButton(
              icon: Icon(Icons.chevron_left,
                  color: provider.isDarkMode ? Colors.white70 : Colors.black87),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints(minWidth: 32, minHeight: 32),
              onPressed: () => setState(() {
                _calendarMonth = DateTime(year, month - 1);
              }),
            ),
            Expanded(
              child: Center(
                child: Text(
                  '$year / ${month.toString().padLeft(2, '0')}',
                  style: TextStyle(
                      color:
                          provider.isDarkMode ? Colors.white : Colors.black87,
                      fontSize: 18,
                      fontWeight: FontWeight.w700),
                ),
              ),
            ),
            IconButton(
              icon: Icon(Icons.chevron_right,
                  color: provider.isDarkMode ? Colors.white70 : Colors.black87),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints(minWidth: 32, minHeight: 32),
              onPressed: () => setState(() {
                _calendarMonth = DateTime(year, month + 1);
              }),
            ),
            TextButton(
              style: TextButton.styleFrom(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                minimumSize: Size.zero,
                tapTargetSize: MaterialTapTargetSize.shrinkWrap,
              ),
              onPressed: () => setState(() {
                final now = DateTime.now();
                _calendarMonth = DateTime(now.year, now.month);
              }),
              child: Text(provider.t('cal.today'),
                  style: const TextStyle(color: Color(0xFFBA68C8))),
            ),
            // (旧) Google Calendar 設定ボタンはここにあったが、Google Calendar
            // 連携は廃止 (Firebase 経由の同期グループのみ) のため削除済み。
          ]),
          const SizedBox(height: 4),
          // 曜日ヘッダー (縦パディングを詰める) — 言語に合わせた表記 + 土日色分け
          Builder(builder: (_) {
            // 言語別の曜日略称 (日曜始まり)
            const weekdayLabels = <String, List<String>>{
              'ja': ['日', '月', '火', '水', '木', '金', '土'],
              'en': ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'],
              'zh': ['日', '一', '二', '三', '四', '五', '六'],
              'ko': ['일', '월', '화', '수', '목', '금', '토'],
              'es': ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'],
              'fr': ['Dim', 'Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam'],
              'de': ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa'],
              'pt': ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'],
              'ru': ['Вс', 'Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб'],
            };
            final labels =
                weekdayLabels[provider.appLanguage] ?? weekdayLabels['en']!;
            return Row(
              children: List.generate(7, (idx) {
                final isSun = idx == 0;
                final isSat = idx == 6;
                return Expanded(
                  child: Center(
                    child: Padding(
                      padding: const EdgeInsets.symmetric(vertical: 2),
                      child: Text(labels[idx],
                          style: TextStyle(
                              color: isSun
                                  ? const Color(0xFFE53935)
                                  : isSat
                                      ? const Color(0xFF1976D2)
                                      : (provider.isDarkMode
                                          ? Colors.white54
                                          : Colors.black54),
                              fontSize: 11,
                              fontWeight: FontWeight.w700)),
                    ),
                  ),
                );
              }),
            );
          }),
          Divider(
              color: provider.isDarkMode ? Colors.white12 : Colors.black26,
              height: 1),
          // 日付グリッド — GridView の代わりに Column+Row+Expanded を使い
          // スクロールなしで常に全セルが画面に収まるようにする
          Expanded(
            child: Column(
              children: List.generate(totalCells ~/ 7, (rowIdx) {
                return Expanded(
                  child: Padding(
                    padding: const EdgeInsets.only(bottom: 2),
                    child: Row(
                      children: List.generate(7, (colIdx) {
                        final i = rowIdx * 7 + colIdx;
                        return Expanded(
                          child: Padding(
                            padding: const EdgeInsets.only(right: 2),
                            child: _buildCalendarCell(i, startOffset,
                                daysInMonth, year, month, todayKey, provider),
                          ),
                        );
                      }),
                    ),
                  ),
                );
              }),
            ),
          ),
        ],
      ),
    );
  }

  /// カレンダー用のタイムゾーン選択ダイアログ。
  /// 言語に応じたプリセット (例: 米国/ロシアは複数) を一覧表示し、
  /// ユーザーが選択するとそのオフセットが provider に保存される。
  /// 「端末ローカルに戻す」項目もある。
  Future<void> _showCalendarTimezoneDialog(
      BuildContext context, MindMapProvider provider) async {
    final presets = provider.presetTimezonesFor(provider.appLanguage);
    final currentOffset = provider.calendarTzOffsetMinutes;
    await showDialog<void>(
      context: context,
      builder: (dctx) {
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            const Icon(Icons.public_rounded,
                color: Color(0xFFFFB347), size: 20),
            const SizedBox(width: 8),
            Expanded(
              child: Text(provider.t('cal.tz.title'),
                  style: const TextStyle(color: Colors.white, fontSize: 15)),
            ),
          ]),
          content: SizedBox(
            width: 360,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(provider.t('cal.tz.body'),
                    style:
                        const TextStyle(color: Colors.white70, fontSize: 12)),
                const SizedBox(height: 12),
                // 「端末ローカル」オプション
                _tzOption(
                  label: provider.t('cal.tz.systemDefault'),
                  sublabel: provider.t('cal.tz.systemSub'),
                  selected: currentOffset == null,
                  onTap: () async {
                    await provider.setCalendarTimezone(null);
                    if (dctx.mounted) Navigator.pop(dctx);
                  },
                ),
                const Divider(color: Colors.white12, height: 16),
                // プリセット一覧 (スクロール可能)
                if (presets.isEmpty)
                  Padding(
                    padding: const EdgeInsets.all(8),
                    child: Text(provider.t('cal.tz.noPreset'),
                        style: const TextStyle(
                            color: Colors.white54, fontSize: 12)),
                  ),
                if (presets.isNotEmpty)
                  ConstrainedBox(
                    constraints: const BoxConstraints(maxHeight: 280),
                    child: SingleChildScrollView(
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: presets.map((p) {
                          final label = p[0] as String;
                          final off = p[1] as int;
                          final selected = currentOffset == off &&
                              provider.calendarTzLabel == label;
                          return _tzOption(
                            label: label,
                            sublabel: _formatOffsetLabel(off),
                            selected: selected,
                            onTap: () async {
                              await provider.setCalendarTimezone(off,
                                  label: label);
                              if (dctx.mounted) Navigator.pop(dctx);
                            },
                          );
                        }).toList(),
                      ),
                    ),
                  ),
                const Divider(color: Colors.white12, height: 16),
                // カスタムオフセット (時単位、-12〜+14)
                _customOffsetRow(context, provider, dctx),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.cancel')),
            ),
          ],
        );
      },
    );
  }

  /// タイムゾーン選択肢の 1 行 (ListTile 風)
  Widget _tzOption({
    required String label,
    required String sublabel,
    required bool selected,
    required VoidCallback onTap,
  }) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(6),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 8),
        margin: const EdgeInsets.only(bottom: 2),
        decoration: BoxDecoration(
          color: selected
              ? const Color(0xFFFFB347).withValues(alpha: 0.15)
              : Colors.transparent,
          borderRadius: BorderRadius.circular(6),
          border: selected
              ? Border.all(
                  color: const Color(0xFFFFB347).withValues(alpha: 0.5))
              : null,
        ),
        child: Row(children: [
          Icon(
            selected
                ? Icons.radio_button_checked
                : Icons.radio_button_unchecked,
            color: selected ? const Color(0xFFFFB347) : Colors.white38,
            size: 16,
          ),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(label,
                    style: TextStyle(
                        color: Colors.white,
                        fontSize: 13,
                        fontWeight:
                            selected ? FontWeight.w700 : FontWeight.w500)),
                Text(sublabel,
                    style:
                        const TextStyle(color: Colors.white54, fontSize: 11)),
              ],
            ),
          ),
        ]),
      ),
    );
  }

  /// カスタムオフセット入力行 (-12 〜 +14 の整数時)。
  Widget _customOffsetRow(
      BuildContext outer, MindMapProvider provider, BuildContext dctx) {
    final ctrl = TextEditingController(
        text: provider.calendarTzOffsetMinutes != null
            ? (provider.calendarTzOffsetMinutes! / 60).toStringAsFixed(1)
            : '');
    return Row(children: [
      Expanded(
        child: Text(provider.t('cal.tz.custom'),
            style: const TextStyle(color: Colors.white70, fontSize: 12)),
      ),
      const SizedBox(width: 8),
      SizedBox(
        width: 70,
        child: TextField(
          controller: ctrl,
          keyboardType: const TextInputType.numberWithOptions(
              signed: true, decimal: true),
          style: const TextStyle(color: Colors.white, fontSize: 13),
          decoration: const InputDecoration(
            isDense: true,
            hintText: '+9',
            hintStyle: TextStyle(color: Colors.white38),
            contentPadding: EdgeInsets.symmetric(horizontal: 6, vertical: 6),
            enabledBorder: OutlineInputBorder(
              borderSide: BorderSide(color: Colors.white24),
            ),
            focusedBorder: OutlineInputBorder(
              borderSide: BorderSide(color: Color(0xFFFFB347)),
            ),
          ),
        ),
      ),
      const SizedBox(width: 6),
      const Text('h', style: TextStyle(color: Colors.white54, fontSize: 12)),
      const SizedBox(width: 6),
      ElevatedButton(
        style: ElevatedButton.styleFrom(
            backgroundColor: const Color(0xFFFFB347),
            foregroundColor: Colors.black,
            padding: const EdgeInsets.symmetric(horizontal: 10),
            minimumSize: const Size(0, 32)),
        onPressed: () async {
          final h = double.tryParse(ctrl.text.trim());
          if (h == null) return;
          final mins = (h * 60).round().clamp(-12 * 60, 14 * 60);
          await provider.setCalendarTimezone(mins,
              label: 'UTC${h >= 0 ? "+" : ""}${h.toStringAsFixed(1)}');
          if (dctx.mounted) Navigator.pop(dctx);
        },
        child: Text(provider.t('btn.ok'),
            style: const TextStyle(
                color: Colors.black,
                fontWeight: FontWeight.w700,
                fontSize: 12)),
      ),
    ]);
  }

  /// オフセット (分) を 'UTC+9:00' 形式の文字列に整形。
  String _formatOffsetLabel(int minutes) {
    final sign = minutes >= 0 ? '+' : '-';
    final abs = minutes.abs();
    final h = abs ~/ 60;
    final m = abs % 60;
    if (m == 0) return 'UTC$sign$h:00';
    return 'UTC$sign$h:${m.toString().padLeft(2, '0')}';
  }

  /// グループ内のユーザー切替セレクタ（Pro 以上で解禁）。
  ///
  /// - Free プラン → 何も表示しない（自分のカレンダーしか見られない）
  /// - 同期グループ未参加 → 何も表示しない
  /// - Pro / Max プラン + 同期参加中 → 現在の閲覧対象を表示するピル + タップでピッカー
  ///
  /// 仕様：
  ///   * 「自分」「全員」「(メンバーごと)」の中から最大100名まで選択できる
  ///   * Pro 以上 + allowCalendarSharing=ON のメンバーのみ表示
  Widget _buildCalendarViewerSwitcher(MindMapProvider provider) {
    // カレンダーのグループ閲覧は Pro 以上で解禁 (旧仕様は Max 限定)。
    if (!provider.isMaxUnlocked) {
      return const SizedBox.shrink();
    }
    // グループ未参加なら無意味なので非表示
    if (!provider.isSyncEnabled) {
      return const SizedBox.shrink();
    }
    final dark = provider.isDarkMode;

    // 現在の閲覧対象ラベル
    String label;
    IconData icon;
    if (provider.isCalendarViewingSelf) {
      label = provider.t('cal.viewing.self');
      icon = Icons.person_rounded;
    } else if (provider.isCalendarViewingAll) {
      label = provider.t('cal.viewing.all');
      icon = Icons.groups_rounded;
    } else {
      final m =
          provider.memberInfoForUid(provider.calendarViewingSpecificUid ?? '');
      label = m?.displayName ?? provider.t('cal.viewing.unknown');
      icon = Icons.account_circle_rounded;
    }

    return Material(
      color: Colors.transparent,
      child: InkWell(
        borderRadius: BorderRadius.circular(20),
        onTap: () => _showCalendarViewerPicker(provider),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
          decoration: BoxDecoration(
            color: (dark ? Colors.white : Colors.black).withValues(alpha: 0.08),
            borderRadius: BorderRadius.circular(20),
            border: Border.all(
              color: const Color(0xFFBA68C8).withValues(alpha: 0.45),
              width: 1,
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(icon, size: 16, color: const Color(0xFFBA68C8)),
              const SizedBox(width: 6),
              ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 140),
                child: Text(
                  label,
                  overflow: TextOverflow.ellipsis,
                  maxLines: 1,
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w600,
                    color: dark ? Colors.white : Colors.black87,
                  ),
                ),
              ),
              const SizedBox(width: 4),
              Icon(Icons.expand_more_rounded,
                  size: 16, color: dark ? Colors.white54 : Colors.black54),
            ],
          ),
        ),
      ),
    );
  }

  /// グループ閲覧ユーザー選択ボトムシート。
  /// 「自分」「全員」 + 閲覧可能なメンバー一覧 (最大100件) を表示。
  Future<void> _showCalendarViewerPicker(MindMapProvider provider) async {
    final members = provider.viewableCalendarMembers;
    final dark = provider.isDarkMode;
    await showModalBottomSheet<void>(
      context: context,
      backgroundColor: dark ? const Color(0xFF1B1B2A) : Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(16)),
      ),
      builder: (sctx) {
        return SafeArea(
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 8),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 4, 16, 8),
                  child: Row(
                    children: [
                      const Icon(Icons.groups_rounded,
                          color: Color(0xFFBA68C8), size: 18),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          provider.t('cal.viewing.title'),
                          style: TextStyle(
                            fontSize: 14,
                            fontWeight: FontWeight.w700,
                            color: dark ? Colors.white : Colors.black87,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
                Divider(
                    height: 1, color: dark ? Colors.white12 : Colors.black12),
                Flexible(
                  child: ListView(
                    shrinkWrap: true,
                    children: [
                      _viewerPickerTile(
                        provider: provider,
                        icon: Icons.person_rounded,
                        title: provider.t('cal.viewing.self'),
                        subtitle: provider.displayName.isEmpty
                            ? null
                            : provider.displayName,
                        selected: provider.isCalendarViewingSelf,
                        onTap: () async {
                          await provider.setCalendarViewingUid(
                              MindMapProvider.kCalendarViewSelf);
                          if (sctx.mounted) Navigator.pop(sctx);
                        },
                      ),
                      _viewerPickerTile(
                        provider: provider,
                        icon: Icons.groups_rounded,
                        title: provider.t('cal.viewing.all'),
                        subtitle: provider.t('cal.viewing.allSubtitle'),
                        selected: provider.isCalendarViewingAll,
                        onTap: () async {
                          await provider.setCalendarViewingUid(
                              MindMapProvider.kCalendarViewAll);
                          if (sctx.mounted) Navigator.pop(sctx);
                        },
                      ),
                      if (members.isNotEmpty)
                        Divider(
                            height: 1,
                            color: dark ? Colors.white12 : Colors.black12),
                      if (members.isEmpty)
                        Padding(
                          padding: const EdgeInsets.fromLTRB(16, 16, 16, 12),
                          child: Text(
                            provider.t('cal.viewing.noMembers'),
                            style: TextStyle(
                              fontSize: 12,
                              color: dark ? Colors.white54 : Colors.black54,
                            ),
                          ),
                        )
                      else
                        ...members.map((m) => _viewerPickerTile(
                              provider: provider,
                              icon: Icons.account_circle_rounded,
                              title: m.displayName,
                              selected: provider.calendarViewingUid == m.uid,
                              onTap: () async {
                                await provider.setCalendarViewingUid(m.uid);
                                if (sctx.mounted) Navigator.pop(sctx);
                              },
                            )),
                    ],
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
    // 切替後に画面再描画
    if (mounted) setState(() {});
  }

  Widget _viewerPickerTile({
    required MindMapProvider provider,
    required IconData icon,
    required String title,
    String? subtitle,
    required bool selected,
    required VoidCallback onTap,
  }) {
    final dark = provider.isDarkMode;
    return ListTile(
      dense: true,
      leading: Icon(icon,
          size: 22,
          color: selected
              ? const Color(0xFFBA68C8)
              : (dark ? Colors.white70 : Colors.black54)),
      title: Text(title,
          style: TextStyle(
            fontSize: 13,
            fontWeight: selected ? FontWeight.w700 : FontWeight.w500,
            color: dark ? Colors.white : Colors.black87,
          )),
      subtitle: subtitle == null
          ? null
          : Text(subtitle,
              style: TextStyle(
                fontSize: 11,
                color: dark ? Colors.white54 : Colors.black54,
              )),
      trailing: selected
          ? const Icon(Icons.check_rounded, color: Color(0xFFBA68C8), size: 20)
          : null,
      onTap: onTap,
    );
  }

  /// カレンダーセル 1 つ分のウィジェット
  /// ── 機能 ──
  /// * セルタップ  : その日を選択
  /// * セルダブルタップ : タイムライン表示
  /// * イベントチップタップ : 編集ダイアログ（削除ボタン付き）
  /// * イベントチップ長押し : 他の日へドラッグ (Ctrl+ドラッグでコピー)
  /// * イベントチップ右クリック : ポップアップメニュー（編集/コピー/削除）
  /// * セルに対してイベントをドロップ : 移動 / Ctrl+ドロップでコピー
  Widget _buildCalendarCell(int i, int startOffset, int daysInMonth, int year,
      int month, String todayKey, MindMapProvider provider) {
    final dayNum = i - startOffset + 1;
    if (dayNum < 1 || dayNum > daysInMonth) {
      return Container(
          color: provider.isDarkMode
              ? Colors.white.withValues(alpha: 0.02)
              : Colors.black.withValues(alpha: 0.04));
    }
    final date = DateTime(year, month, dayNum);
    final key = _dateKey(date);
    final events = provider.eventsOn(key);
    final isToday = key == todayKey;
    final isSelected = date.year == _selectedCalendarDay.year &&
        date.month == _selectedCalendarDay.month &&
        date.day == _selectedCalendarDay.day;
    final isSunday = date.weekday == DateTime.sunday;
    final isSaturday = date.weekday == DateTime.saturday;
    // ── 祝日判定 ──
    // appLanguage に応じた国の祝日を取得。祝日なら日付テキストを赤くし、
    // 祝日名を小さなチップとしてセル上部に表示する。
    final holidayName = provider.holidayNameOn(key);
    final isHoliday = holidayName != null;

    return DragTarget<_CalendarDragPayload>(
      // Google イベントは別日にも拒否（書き換え不可）
      onWillAcceptWithDetails: (details) =>
          details.data.fromDateKey != key || // 別日ならOK
          // 同じ日でも Ctrl/Cmd が押されていれば複製として受け入れ
          HardwareKeyboard.instance.isControlPressed ||
          HardwareKeyboard.instance.isMetaPressed,
      onAcceptWithDetails: (details) async {
        final d = details.data;
        final isCopy = HardwareKeyboard.instance.isControlPressed ||
            HardwareKeyboard.instance.isMetaPressed;
        if (d.fromDateKey == key && !isCopy) return;
        if (isCopy) {
          await provider.copyCalendarEvent(d.fromDateKey, d.eventId, key);
          if (mounted) {
            _appSnack(
                context,
                SnackBar(
                  content: Text(provider.t('cal.copySuccess')),
                  duration: const Duration(seconds: 1),
                ));
          }
        } else {
          await provider.moveCalendarEvent(d.fromDateKey, d.eventId, key);
          if (mounted) {
            _appSnack(
                context,
                SnackBar(
                  content: Text(provider.t('cal.moveSuccess')),
                  duration: const Duration(seconds: 1),
                ));
          }
        }
      },
      builder: (dtCtx, candidate, rejected) {
        // ドラッグ中のホバー視覚フィードバック
        final isDragHover = candidate.isNotEmpty;
        final isCopyMode = isDragHover &&
            (HardwareKeyboard.instance.isControlPressed ||
                HardwareKeyboard.instance.isMetaPressed);
        return InkWell(
          onTap: () {
            // 1クリック: 選択のみ
            setState(() => _selectedCalendarDay = date);
          },
          onDoubleTap: () => _showEventsForDay(context, provider, date),
          child: Container(
            decoration: BoxDecoration(
              color: isDragHover
                  ? (isCopyMode
                      ? const Color(0xFF00E5FF).withValues(alpha: 0.30)
                      : const Color(0xFF4FC3F7).withValues(alpha: 0.30))
                  : (isToday
                      ? const Color(0xFFBA68C8).withValues(alpha: 0.15)
                      : (provider.isDarkMode
                          ? Colors.white.withValues(alpha: 0.04)
                          : Colors.white.withValues(alpha: 0.35))),
              borderRadius: BorderRadius.circular(6),
              border: isDragHover
                  ? Border.all(
                      color: isCopyMode
                          ? const Color(0xFF00E5FF)
                          : const Color(0xFF4FC3F7),
                      width: 2.5)
                  : (isSelected
                      ? Border.all(color: const Color(0xFF4FC3F7), width: 2.0)
                      : (isToday
                          ? Border.all(
                              color: const Color(0xFFBA68C8), width: 1.5)
                          : Border.all(
                              color: provider.isDarkMode
                                  ? Colors.white12
                                  : Colors.black26,
                              width: 0.5))),
            ),
            padding: const EdgeInsets.all(4),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(children: [
                  Text(
                    '$dayNum',
                    style: TextStyle(
                      // 祝日は赤色 (土曜の青よりも優先)
                      color: (isHoliday || isSunday)
                          ? const Color(0xFFE53935)
                          : isSaturday
                              ? const Color(0xFF1976D2)
                              : (provider.isDarkMode
                                  ? Colors.white70
                                  : Colors.black87),
                      fontSize: 13,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  // 祝日マーク (小さい赤丸 + 名前は別行で)
                  if (isHoliday) ...[
                    const SizedBox(width: 4),
                    Container(
                      width: 6,
                      height: 6,
                      decoration: const BoxDecoration(
                        color: Color(0xFFE53935),
                        shape: BoxShape.circle,
                      ),
                    ),
                  ],
                ]),
                // 祝日名 (小さいチップ風表示)
                if (isHoliday)
                  Tooltip(
                    message: holidayName,
                    child: Container(
                      margin: const EdgeInsets.only(top: 2),
                      padding: const EdgeInsets.symmetric(
                          horizontal: 4, vertical: 1),
                      decoration: BoxDecoration(
                        color: const Color(0xFFE53935).withValues(alpha: 0.15),
                        borderRadius: BorderRadius.circular(3),
                        border: Border.all(
                            color:
                                const Color(0xFFE53935).withValues(alpha: 0.4),
                            width: 0.5),
                      ),
                      child: Text(
                        holidayName,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: Color(0xFFE53935),
                          fontSize: 9,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ),
                  ),
                const SizedBox(height: 2),
                // イベント一覧（セル高さに応じて表示数を制限）
                Expanded(
                  child: ClipRect(
                    child: ListView(
                      physics: const NeverScrollableScrollPhysics(),
                      padding: EdgeInsets.zero,
                      children: events
                          .map((e) => Padding(
                                padding: const EdgeInsets.only(bottom: 1),
                                child: _buildMonthEventChip(e, key, provider),
                              ))
                          .toList(),
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  /// 月表示セル内の小さなイベント行
  /// * タップ → 編集ダイアログ
  /// * 長押し → 他のセルへドラッグ（LongPressDraggable）
  /// * 右クリック（デスクトップ）→ ポップアップメニュー
  Widget _buildMonthEventChip(
      CalendarEvent e, String key, MindMapProvider provider) {
    final chip = Container(
      padding: const EdgeInsets.symmetric(horizontal: 3, vertical: 1),
      decoration: BoxDecoration(
        color: Color(e.colorArgb ?? 0xFFBA68C8),
        borderRadius: BorderRadius.circular(3),
      ),
      child: Row(children: [
        if (e.startTime != null) ...[
          Text(e.startTime!,
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 8,
                  fontWeight: FontWeight.w700)),
          const SizedBox(width: 2),
        ],
        Expanded(
          child: Text(
            e.title,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(color: Colors.white, fontSize: 9),
          ),
        ),
      ]),
    );

    // 半透明の「ドラッグ中の元位置」用チップ
    final chipGhost = Opacity(opacity: 0.35, child: chip);

    // ドラッグのフィードバック（追従して表示されるミニ版）
    final chipFeedback = Material(
      color: Colors.transparent,
      child: Container(
        constraints: const BoxConstraints(maxWidth: 140),
        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
        decoration: BoxDecoration(
          color: Color(e.colorArgb ?? 0xFFBA68C8),
          borderRadius: BorderRadius.circular(4),
          boxShadow: [
            BoxShadow(
                color: Colors.black.withValues(alpha: 0.35),
                blurRadius: 6,
                offset: const Offset(0, 2)),
          ],
          border: Border.all(color: Colors.white, width: 1.2),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (e.startTime != null) ...[
              Text(e.startTime!,
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 10,
                      fontWeight: FontWeight.w700)),
              const SizedBox(width: 4),
            ],
            Flexible(
              child: Text(
                e.title.isEmpty ? '(no title)' : e.title,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(color: Colors.white, fontSize: 11),
              ),
            ),
          ],
        ),
      ),
    );

    final interactive = GestureDetector(
      // タップ: 編集ダイアログ（モバイルでも削除ができるように）
      onTap: () => _editCalendarEventDialog(context, provider, key, e),
      // 右クリック: アクションメニュー
      onSecondaryTapUp: (details) =>
          _showMonthEventActionMenu(details.globalPosition, key, e, provider),
      child: chip,
    );

    // Google イベントはドラッグ不可（maxSimultaneousDrags: 0）
    return LongPressDraggable<_CalendarDragPayload>(
      data: _CalendarDragPayload(fromDateKey: key, eventId: e.id),
      maxSimultaneousDrags:
          (e.isGoogleEvent || e.isOthersEvent(provider.currentUid)) ? 0 : 1,
      // フィードバック (chipFeedback) は子チップとサイズが異なるため、 既定の
      //   childDragAnchorStrategy だとカーソルから大きくずれる (= ユーザー報告:
      //   PC でドラッグするとカーソルと予定がずれる)。 pointerDragAnchorStrategy
      //   でフィードバックの左上をポインタ位置に合わせ、 ずれを解消する。
      dragAnchorStrategy: pointerDragAnchorStrategy,
      feedback: chipFeedback,
      childWhenDragging: chipGhost,
      // 予定の長押し操作時の振動を無効化 (= ユーザー要望: タイムラインで
      //   予定を扱うときに変な風に振動して気分が悪いので振動させない)。
      hapticFeedbackOnStart: false,
      child: interactive,
    );
  }

  /// 月表示のイベントチップに対するアクションメニュー
  Future<void> _showMonthEventActionMenu(Offset globalPos, String dateKey,
      CalendarEvent e, MindMapProvider provider) async {
    final isOthers = e.isOthersEvent(provider.currentUid);
    // 注: Google Calendar 同期済みでも「自分のイベント」は編集・削除可能
    // （isGoogleEvent は read-only 判定に使わない）
    final isReadOnly = isOthers;
    final selected = await showMenu<String>(
      context: context,
      position: RelativeRect.fromLTRB(
          globalPos.dx, globalPos.dy, globalPos.dx + 1, globalPos.dy + 1),
      color: const Color(0xFF2A2A3E),
      items: [
        PopupMenuItem<String>(
          value: 'edit',
          child: Row(children: [
            Icon(isReadOnly ? Icons.visibility : Icons.edit,
                color: const Color(0xFF4FC3F7), size: 16),
            const SizedBox(width: 8),
            Text(provider.t('ctx.edit'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        PopupMenuItem<String>(
          value: 'copy',
          child: Row(children: [
            const Icon(Icons.content_copy, color: Color(0xFFBA68C8), size: 16),
            const SizedBox(width: 8),
            Text(provider.t('ctx.copy'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        if (!isReadOnly)
          PopupMenuItem<String>(
            value: 'copyRange',
            child: Row(children: [
              const Icon(Icons.date_range_rounded,
                  color: Color(0xFF00E5FF), size: 16),
              const SizedBox(width: 8),
              Text(provider.t('cal.copyRange'),
                  style: const TextStyle(color: Colors.white, fontSize: 13)),
            ]),
          ),
        if (!isReadOnly)
          PopupMenuItem<String>(
            value: 'routine',
            child: Row(children: [
              const Icon(Icons.event_repeat_rounded,
                  color: Color(0xFF66BB6A), size: 16),
              const SizedBox(width: 8),
              Text(provider.t('cal.registerRoutine'),
                  style: const TextStyle(color: Colors.white, fontSize: 13)),
            ]),
          ),
        if (!isReadOnly)
          PopupMenuItem<String>(
            value: 'delete',
            child: Row(children: [
              const Icon(Icons.delete, color: Color(0xFFFF6B6B), size: 16),
              const SizedBox(width: 8),
              Text(provider.t('ctx.delete'),
                  style: const TextStyle(color: Colors.white, fontSize: 13)),
            ]),
          ),
      ],
    );
    if (!mounted) return;
    if (selected == 'edit') {
      await _editCalendarEventDialog(context, provider, dateKey, e);
    } else if (selected == 'copy') {
      // 同じ日に複製（時刻はそのまま）
      await provider.copyCalendarEvent(dateKey, e.id, dateKey);
      if (mounted) {
        _appSnack(
            context,
            SnackBar(
              content: Text(provider.t('cal.copySuccess')),
              duration: const Duration(seconds: 1),
            ));
      }
    } else if (selected == 'copyRange') {
      if (mounted) {
        await _showRoutineCopyDialog(
          context,
          provider: provider,
          event: e,
          fromDateKey: dateKey,
          asRoutine: false,
        );
      }
    } else if (selected == 'routine') {
      if (mounted) {
        await _showRoutineCopyDialog(
          context,
          provider: provider,
          event: e,
          fromDateKey: dateKey,
          asRoutine: true,
        );
      }
    } else if (selected == 'delete') {
      await provider.removeCalendarEvent(dateKey, e.id);
      if (mounted) {
        _appSnack(
            context,
            SnackBar(
              content: Text(provider.t('cal.deleteSuccess')),
              duration: const Duration(seconds: 1),
            ));
      }
    }
  }

  String _dateKey(DateTime d) =>
      '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';

  /// 日付セルをタップした時のタイムライン画面。
  /// Google カレンダーのような 1 日のタイムライン (0-24 時) を表示し、
  /// 各時間スロットの空き領域をタップして予定を追加/ドラッグでブロック作成。
  void _showEventsForDay(
      BuildContext ctx, MindMapProvider provider, DateTime day) {
    final key = _dateKey(day);
    Navigator.of(ctx).push(MaterialPageRoute(
      builder: (pageCtx) => _DayTimelinePage(
        day: day,
        dateKey: key,
        provider: provider,
        // pageCtx（タイムライン画面のcontext）を渡すことで、
        // ダイアログがタイムラインの上に表示されるようにする
        onEditEvent: (dialogCtx, dateKey, ev) =>
            _editCalendarEventDialog(dialogCtx, provider, dateKey, ev),
      ),
    ));
  }

  /// イベントの追加・編集ダイアログ
  /// 右クリックメニュー: ノードのタイトル/メモを指定言語に翻訳する。
  /// - APIキー未設定なら警告を出して終了
  /// 右クリックメニュー: 関連動画を取得して子ノードとして追加。
  ///
  /// クエリは:
  ///   - ノードに YouTube URL があり、タイトルが取得済み: タイトル
  ///   - YouTube URL なし: ノードのテキスト (title) 自体
  /// で検索 → 上位 5 件 (重複/既存ノードは除外) を子ノードとして追加。
  Future<void> _fetchAndAddRelatedVideos(
      BuildContext ctx, MindMapProvider provider, String nodeId) async {
    final node = provider.nodes[nodeId];
    if (node == null) return;
    // クエリ決定
    String query = node.title.trim();
    if (query.isEmpty) {
      _appSnack(
          ctx,
          SnackBar(
            content: Text(provider.t('related.queryEmpty')),
            backgroundColor: const Color(0xFFE53935),
            duration: const Duration(seconds: 3),
          ));
      return;
    }
    // 進行中表示 (5秒では足りない可能性あり: processing: true)
    final progressController = _appSnack(
        ctx,
        SnackBar(
          content: Row(children: [
            const SizedBox(
                width: 18,
                height: 18,
                child: CircularProgressIndicator(
                    strokeWidth: 2, color: Colors.white)),
            const SizedBox(width: 12),
            Expanded(
              child: Text(
                '${provider.t('related.fetching')}: $query',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(fontSize: 13),
              ),
            ),
          ]),
          duration: const Duration(seconds: 60),
          backgroundColor: const Color(0xFF1E1E32),
        ),
        processing: true);

    final videos = await _fetchRelatedVideos(query,
        limit: 12, // 重複除外後に 5 件残るよう多めに取得
        youtubeRegionQuery: provider.youtubeRegionQuery());
    progressController?.close();

    if (!ctx.mounted) return;
    if (videos.isEmpty) {
      _appSnack(
          ctx,
          SnackBar(
            content: Text(provider.t('related.notFound')),
            backgroundColor: const Color(0xFFE53935),
            duration: const Duration(seconds: 3),
          ));
      return;
    }
    // ── マップ内既存の YouTube 動画 ID を収集 ──
    // ノードの youtubeUrl から v=xxx の xxx を抽出して、 関連動画リストから
    // 親/子/その他全ノードと同じ動画を最初から除外する。
    // (= ユーザー要望: 「子ノードや親ノードと同じ動画が出ないように」)
    final existingVideoIds = <String>{};
    final videoIdRegex =
        RegExp(r'(?:[?&]v=|/watch/|/embed/|youtu\.be/)([A-Za-z0-9_-]{6,})');
    for (final n in provider.currentPage.nodes.values) {
      final url = n.youtubeUrl ?? n.linkUrl ?? '';
      if (url.isEmpty) continue;
      final m = videoIdRegex.firstMatch(url);
      if (m != null) existingVideoIds.add(m.group(1)!);
    }
    // 既存と重複する videoId を除外
    final filtered = videos
        .where((v) {
          final vid = (v['videoId'] ?? '').trim();
          return vid.isNotEmpty && !existingVideoIds.contains(vid);
        })
        .take(5)
        .toList();
    if (filtered.isEmpty) {
      _appSnack(
          ctx,
          SnackBar(
            content: Text(provider.t('related.allDuplicates')),
            backgroundColor: const Color(0xFFFFB347),
            duration: const Duration(seconds: 3),
          ));
      return;
    }
    final added = provider.addRelatedVideoChildrenForNode(nodeId, filtered);
    if (added == 0) {
      _appSnack(
          ctx,
          SnackBar(
            content: Text(provider.t('related.allDuplicates')),
            backgroundColor: const Color(0xFFFFB347),
            duration: const Duration(seconds: 3),
          ));
      return;
    }
    _appSnack(
        ctx,
        SnackBar(
          content: Text('${provider.t('related.addedPrefix')} $added '
              '${provider.t('related.addedSuffix')}'),
          backgroundColor: const Color(0xFF43B97F),
          duration: const Duration(seconds: 3),
        ));
    // サムネイル取得 (各ノードの YouTube CDN サムネを取りに行く)
    // 親ノードの直近の子ノードに対して generateVideoThumbnail を呼ぶ
    for (final node in provider.nodes.values) {
      final url = node.youtubeUrl ?? '';
      if (url.isEmpty) continue;
      // videos に含まれる videoId のノードのみ
      for (final v in videos) {
        final vid = v['videoId'] ?? '';
        if (vid.isNotEmpty && url.contains(vid)) {
          provider.generateVideoThumbnail(node.id);
          break;
        }
      }
    }
  }

  /// 既存: 翻訳機能エントリポイント。
  /// - 言語選択ダイアログを出して、選んだ言語で AI 翻訳
  /// - 結果はノードのタイトル(短)とメモ(長)に書き戻す
  Future<void> _translateNode(
      BuildContext ctx, MindMapProvider provider, String nodeId) async {
    if (!provider.hasActiveAiKey) {
      _showAiKeyMissingSnack(ctx, provider);
      return;
    }
    final node = provider.nodes[nodeId];
    if (node == null) return;
    final original =
        '${node.title}${node.memoText != null && node.memoText!.isNotEmpty ? "\n\n${node.memoText}" : ""}'
            .trim();
    if (original.isEmpty) return;

    // 翻訳先の言語選択
    final langs = <Map<String, String>>[
      {'code': 'ja', 'label': '日本語'},
      {'code': 'en', 'label': 'English'},
      {'code': 'zh', 'label': '中文'},
      {'code': 'ko', 'label': '한국어'},
      {'code': 'es', 'label': 'Español'},
      {'code': 'fr', 'label': 'Français'},
      {'code': 'de', 'label': 'Deutsch'},
      {'code': 'pt', 'label': 'Português'},
      {'code': 'ru', 'label': 'Русский'},
    ];
    final selected = await showDialog<String>(
      context: ctx,
      builder: (dctx) => SimpleDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('translate.chooseLang'),
            style: const TextStyle(color: Colors.white, fontSize: 14)),
        children: langs.map((l) {
          return SimpleDialogOption(
            onPressed: () => Navigator.pop(dctx, l['code']),
            child: Text(l['label']!,
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          );
        }).toList(),
      ),
    );
    if (selected == null || !mounted) return;

    // AI 翻訳実行
    provider.lastUploadError = null;
    final messenger = ScaffoldMessenger.of(ctx);
    _appSnackM(
        messenger,
        SnackBar(
            content: Text(provider.t('deepl.translating')),
            duration: const Duration(seconds: 30)));
    try {
      final langName = langs.firstWhere((l) => l['code'] == selected)['label']!;
      final prompt = '次のテキストを $langName に翻訳してください。'
          '出力は翻訳結果のみ。前後に説明や引用符は付けないこと。\n\n'
          '---\n$original\n---';
      final result = (await provider.askGemini(prompt)).trim();
      if (!mounted) return;
      messenger.hideCurrentSnackBar();
      if (result.isEmpty) {
        _appSnackM(
            messenger,
            SnackBar(
                content: Text(provider.t('deepl.emptyResult')),
                backgroundColor: Colors.redAccent));
        return;
      }
      // 結果を 1 行目=タイトル, 残り=メモ に分割
      final lines = result.split('\n');
      final newTitle = lines.first.trim();
      final newMemo =
          lines.length > 1 ? lines.sublist(1).join('\n').trim() : '';
      provider.updateNodeTitle(nodeId, newTitle);
      if (newMemo.isNotEmpty) {
        provider.updateNodeMemo(nodeId, newMemo);
      }
    } catch (e) {
      if (!mounted) return;
      messenger.hideCurrentSnackBar();
      _appSnackM(
          messenger,
          SnackBar(
              content:
                  Text(provider.t('deepl.failed').replaceFirst('{err}', '$e')),
              backgroundColor: Colors.redAccent));
    }
  }

  /// 右クリックメニュー: ノードのタイトル/メモを AI で要約してメモ欄に書き込む。
  /// 元のタイトルは保持する (要約はあくまで補助情報のため)。
  Future<void> _summarizeNode(
      BuildContext ctx, MindMapProvider provider, String nodeId) async {
    if (!provider.hasActiveAiKey) {
      _showAiKeyMissingSnack(ctx, provider);
      return;
    }
    final node = provider.nodes[nodeId];
    if (node == null) return;
    final original =
        '${node.title}${node.memoText != null && node.memoText!.isNotEmpty ? "\n\n${node.memoText}" : ""}'
            .trim();
    if (original.isEmpty) return;

    final messenger = ScaffoldMessenger.of(ctx);
    _appSnackM(
        messenger,
        SnackBar(
            content: Text(provider.t('summary.summarizing')),
            duration: const Duration(seconds: 30)));
    try {
      final prompt = '次のテキストを要点だけにまとめて簡潔に要約してください。'
          'タイトルと本文のセクションは作らず、本文だけ 2〜4 行で出力。\n\n'
          '---\n$original\n---';
      final summary = (await provider.askGemini(prompt)).trim();
      if (!mounted) return;
      messenger.hideCurrentSnackBar();
      if (summary.isEmpty) {
        _appSnackM(
            messenger,
            SnackBar(
                content: Text(provider.t('summary.emptyResult')),
                backgroundColor: Colors.redAccent));
        return;
      }
      // メモ欄に書き込む (既存メモは要約で上書き)
      provider.updateNodeMemo(nodeId, summary);
    } catch (e) {
      if (!mounted) return;
      messenger.hideCurrentSnackBar();
      _appSnackM(
          messenger,
          SnackBar(
              content: Text(
                  provider.t('summary.failed').replaceFirst('{err}', '$e')),
              backgroundColor: Colors.redAccent));
    }
  }

  /// 設定画面の「クイック子要素生成数」タイルから開く小ダイアログ。
  /// 画像貼り付けスケール (%) を選ぶダイアログを開く。
  /// 戻り値: 選択された % (0〜100)、 キャンセル時は null。
  /// UI: 0〜100 の Slider + 値表示。 0 を選ぶと OFF (= 通常ノード)。
  Future<int?> _showImageScalePicker(MindMapProvider provider) async {
    int current = provider.pasteImageScalePercent;
    return showDialog<int?>(
      context: context,
      builder: (dctx) {
        return StatefulBuilder(
          builder: (sctx, setS) => AlertDialog(
            backgroundColor: const Color(0xFF1E1E2E),
            title: Row(
              children: [
                const Icon(Icons.image_rounded,
                    color: Color(0xFF7FD8A0), size: 20),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    provider.t('settings.pasteImageScale'),
                    style: const TextStyle(color: Colors.white),
                  ),
                ),
              ],
            ),
            content: SizedBox(
              width: 380,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    crossAxisAlignment: CrossAxisAlignment.baseline,
                    textBaseline: TextBaseline.alphabetic,
                    children: [
                      Text(
                        current == 0 ? 'OFF' : '$current',
                        style: const TextStyle(
                          color: Color(0xFF7FD8A0),
                          fontSize: 36,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      if (current > 0)
                        const Padding(
                          padding: EdgeInsets.only(left: 4),
                          child: Text('%',
                              style: TextStyle(
                                  color: Color(0xFF7FD8A0),
                                  fontSize: 18,
                                  fontWeight: FontWeight.w600)),
                        ),
                    ],
                  ),
                  const SizedBox(height: 8),
                  SliderTheme(
                    data: const SliderThemeData(
                      activeTrackColor: Color(0xFF7FD8A0),
                      inactiveTrackColor: Colors.white24,
                      thumbColor: Color(0xFF7FD8A0),
                      overlayColor: Color(0x337FD8A0),
                    ),
                    child: Slider(
                      min: 0,
                      max: 100,
                      divisions: 20, // 5% 刻み
                      value: current.toDouble(),
                      label: current == 0 ? 'OFF' : '$current%',
                      onChanged: (v) {
                        setS(() => current = v.round());
                      },
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 4),
                    child: Text(
                      current == 0
                          ? provider.t('settings.pasteImageScaleHintOff')
                          : provider
                              .t('settings.pasteImageScaleHintOn')
                              .replaceAll('{n}', '$current'),
                      style:
                          const TextStyle(color: Colors.white60, fontSize: 12),
                    ),
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dctx).pop(),
                child: Text(provider.t('btn.cancel'),
                    style: const TextStyle(color: Colors.white60)),
              ),
              ElevatedButton(
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF7FD8A0),
                  foregroundColor: Colors.black87,
                ),
                onPressed: () => Navigator.of(dctx).pop(current),
                child: const Text('OK'),
              ),
            ],
          ),
        );
      },
    );
  }

  /// Ctrl+Shift+A 押下時に 1 度に作る子ノード数を 1〜30 の範囲で入力する。
  /// 入力値は provider.setQuickAddChildrenCount で永続化される。
  Future<void> _showQuickAddChildrenCountDialog(
      BuildContext ctx, MindMapProvider provider) async {
    final ctrl =
        TextEditingController(text: provider.quickAddChildrenCount.toString());
    void doSave(BuildContext dctx) {
      final n = int.tryParse(ctrl.text.trim()) ?? 0;
      if (n <= 0) {
        Navigator.pop(dctx);
        return;
      }
      provider.setQuickAddChildrenCount(n);
      Navigator.pop(dctx);
    }

    await showDialog(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('quickAdd.dialogTitle'),
            style: const TextStyle(color: Colors.white)),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
                provider.t(_isDesktop
                    ? 'quickAdd.dialogHint'
                    : 'quickAdd.dialogHintMobile'),
                style: const TextStyle(color: Colors.white54, fontSize: 12)),
            const SizedBox(height: 12),
            TextField(
              controller: ctrl,
              autofocus: true,
              keyboardType: TextInputType.number,
              style: const TextStyle(color: Colors.white, fontSize: 16),
              decoration: InputDecoration(
                labelText: provider.t('addChildren.countLabel'),
                labelStyle: const TextStyle(color: Colors.white38),
                hintText: provider.t('common.range1to30'),
                hintStyle: const TextStyle(color: Colors.white24),
                enabledBorder: const UnderlineInputBorder(
                    borderSide: BorderSide(color: Colors.white24)),
                focusedBorder: const UnderlineInputBorder(
                    borderSide: BorderSide(color: Color(0xFF43B97F))),
              ),
              inputFormatters: [
                FilteringTextInputFormatter.digitsOnly,
              ],
              onSubmitted: (_) => doSave(dctx),
            ),
            const SizedBox(height: 8),
            // クイック選択チップ (1〜10 + 既定の 5 強調)
            Wrap(
              spacing: 4,
              runSpacing: 4,
              children: [
                for (final n in [1, 2, 3, 4, 5, 6, 8, 10]) n
              ]
                  .map((n) => InkWell(
                        onTap: () {
                          ctrl.text = '$n';
                        },
                        borderRadius: BorderRadius.circular(6),
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 10, vertical: 6),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.06),
                            borderRadius: BorderRadius.circular(6),
                            border: Border.all(color: Colors.white24),
                          ),
                          child: Text('$n',
                              style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 12,
                                  fontWeight: FontWeight.w600)),
                        ),
                      ))
                  .toList(),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            onPressed: () => doSave(dctx),
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF43B97F),
                foregroundColor: Colors.white,),
            child: Text(provider.t('btn.save')),
          ),
        ],
      ),
    );
  }

  /// 右クリックメニュー: 「子ノードを追加」のダイアログ。
  /// 個数を指定すると provider.addChildrenWithCount を呼び、
  /// 空の子ノードを作って親ノードに接続する。
  /// ユーザー要望により、生成直後のインライン編集起動は行わない。
  /// (一番上の子だけ名前入力を求められる挙動を回避するため)
  void _showAddChildrenDialog(
      BuildContext context, MindMapProvider provider, String parentId) {
    final ctrl = TextEditingController(text: '3');
    void doCreate(BuildContext dctx) {
      final raw = ctrl.text.trim();
      final n = int.tryParse(raw) ?? 0;
      if (n <= 0) {
        Navigator.pop(dctx);
        return;
      }
      // 上限を 30 に制限（手入力で大量作成して UI を壊すのを防ぐ）
      final count = n.clamp(1, 30);
      Navigator.pop(dctx);
      final newIds = provider.addChildrenWithCount(parentId, count);
      if (newIds.isEmpty) return;
      // 最初の子ノードを選択するだけにとどめる。
      // インライン編集の自動起動はユーザー要望により無効化済み。
      provider.selectNode(newIds.first);
    }

    showDialog(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('ctx.addChildren'),
            style: const TextStyle(color: Colors.white)),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(provider.t('addChildren.hint'),
                style: const TextStyle(color: Colors.white54, fontSize: 12)),
            const SizedBox(height: 12),
            TextField(
              controller: ctrl,
              autofocus: true,
              keyboardType: TextInputType.number,
              style: const TextStyle(color: Colors.white, fontSize: 16),
              decoration: InputDecoration(
                labelText: provider.t('addChildren.countLabel'),
                labelStyle: const TextStyle(color: Colors.white38),
                hintText: provider.t('common.range1to30'),
                hintStyle: const TextStyle(color: Colors.white24),
                enabledBorder: const UnderlineInputBorder(
                    borderSide: BorderSide(color: Colors.white24)),
                focusedBorder: const UnderlineInputBorder(
                    borderSide: BorderSide(color: Color(0xFF43B97F))),
              ),
              inputFormatters: [
                FilteringTextInputFormatter.digitsOnly,
              ],
              onSubmitted: (_) => doCreate(dctx),
            ),
            const SizedBox(height: 8),
            // 1〜10 のクイック選択チップ
            Wrap(
              spacing: 4,
              runSpacing: 4,
              children: [
                for (final n in [1, 2, 3, 4, 5, 6, 8, 10]) n
              ]
                  .map((n) => InkWell(
                        onTap: () {
                          ctrl.text = '$n';
                        },
                        borderRadius: BorderRadius.circular(6),
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 10, vertical: 6),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.06),
                            borderRadius: BorderRadius.circular(6),
                            border: Border.all(color: Colors.white24),
                          ),
                          child: Text('$n',
                              style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 12,
                                  fontWeight: FontWeight.w600)),
                        ),
                      ))
                  .toList(),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            onPressed: () => doCreate(dctx),
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF43B97F),
                foregroundColor: Colors.white,),
            child: Text(provider.t('addChildren.create')),
          ),
        ],
      ),
    );
  }

  /// ショートカット (Ctrl+E) から予定登録ダイアログを開く。
  /// 選択中ノードがあればそのノードの予定として、 無ければ空の新規予定として
  /// 開く。 ユーザー要望「予定登録の画面を表示させるショートカットキー」。
  // 現在キー割り当てなし (Ctrl+Shift+E はマップ一覧ドロワーに譲った)。
  // 別キーに割り当て直せるようメソッド自体は残しておく。
  // ignore: unused_element
  void _openScheduleDialogShortcut(MindMapProvider provider) {
    final selId = provider.selectedNodeId;
    if (selId != null && provider.nodes.containsKey(selId)) {
      _addNodeToCalendar(context, provider, selId);
      return;
    }
    // 選択ノードが無ければ空の新規予定 (= 終日の白紙テンプレ) を開く。
    final today = DateTime.now();
    final dateKey =
        '${today.year.toString().padLeft(4, '0')}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}';
    _editCalendarEventDialog(
      context,
      provider,
      dateKey,
      CalendarEvent(
        id: '', // 空 ID = 新規作成テンプレ
        title: '',
        memo: null,
        startTime: null,
        endTime: null,
        colorArgb: 0xFFBA68C8,
      ),
    );
  }

  /// ノードのタイトル/メモをコピーした予定編集ダイアログを開く。
  /// 「保存」を押した時点で実際にカレンダーに登録される。
  /// 日付は今日、時刻は未指定 (終日扱い)、色はノードと同じものを初期値にする。
  Future<void> _addNodeToCalendar(
      BuildContext ctx, MindMapProvider provider, String nodeId) async {
    final node = provider.nodes[nodeId];
    if (node == null) return;
    final today = DateTime.now();
    final dateKey =
        '${today.year.toString().padLeft(4, '0')}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}';
    // 「新規作成のテンプレ」 (id='') を渡す → ダイアログ内で
    // addCalendarEvent が呼ばれる。
    final template = CalendarEvent(
      id: '', // ← 空 ID = 新規作成テンプレ
      title: node.title.trim().isEmpty ? '無題' : node.title.trim(),
      memo: (node.memoText?.trim().isEmpty ?? true) ? null : node.memoText,
      // 時刻はユーザーが必要に応じて設定する
      startTime: null,
      endTime: null,
      // ノードの色を初期値にする
      colorArgb: node.color.value,
    );
    await _editCalendarEventDialog(ctx, provider, dateKey, template);
  }

  Future<void> _editCalendarEventDialog(BuildContext ctx,
      MindMapProvider provider, String dateKey, CalendarEvent? existing) async {
    // id が空文字列の場合はタイムラインから作成された「新規作成のテンプレ」扱い
    // （時刻プリフィルのみ使って、保存時は addCalendarEvent を呼ぶ）
    final isNewTemplate = existing != null && existing.id.isEmpty;
    final effectiveExisting = isNewTemplate ? null : existing;
    final titleCtrl = TextEditingController(text: existing?.title ?? '');
    final memoCtrl = TextEditingController(text: existing?.memo ?? '');
    String? startTime = existing?.startTime;
    String? endTime = existing?.endTime;
    int colorArgb = existing?.colorArgb ?? 0xFFBA68C8;
    final isGoogle = effectiveExisting?.isGoogleEvent ?? false;
    // 他メンバー所有のイベントも読み取り専用扱い（Google と同じ UI 挙動）
    final isOthers =
        effectiveExisting?.isOthersEvent(provider.currentUid) ?? false;
    // Google または 他人所有 → 読み取り専用
    // (既存コードは `isGoogle` を条件にしているので、そちらに他人イベントを含める)
    // ただし表示用に別名も保持しておく
    // Google Calendar 同期済みでも自分のイベントは編集可能。
    // 他メンバー所有のイベントのみ読み取り専用。
    final bool isReadOnlyDialog = isOthers;
    // 日付も編集可能に: 初期値は渡された dateKey
    DateTime currentDate = DateTime.parse(dateKey);
    String currentDateKey = dateKey;

    // ── 通知設定 (= 「後で通知」 を 予定登録 に統合) ──
    // ユーザー要望「後で通知を予定登録と纏めて欲しい」 への対応。
    //   旧: 「後で通知」(相対時間で通知) と 「予定登録」(カレンダー登録) が
    //       別々のメニュー項目だった。
    //   新: 予定登録ダイアログに「通知する」 トグル + 何分前 を追加し、
    //       開始時刻を持つイベントは保存時に OS 通知も予約できるようにした。
    //       これにより「後で通知」 は予定登録に吸収され、 メニュー項目を 1 本化。
    // notifyEnabled: 通知を予約するか。 新規作成時はデフォルト ON にして
    //   「予定 = 通知付き」 を自然な既定に (開始時刻が無ければ無効)。
    bool notifyEnabled = effectiveExisting == null;
    // 何分前に通知するか (0 = 開始時刻ちょうど)。
    int notifyLeadMinutes = 0;

    // ── 終日フラグ (ユーザー要望「終日をスケジュールに設定可能に」) ──
    // 当アプリは startTime == null を「終日」 として扱うため、 ON の時は
    // 開始/終了時刻をクリアし、 時刻選択 UI を隠す。 既定は false にして
    // 従来どおり時刻行を表示する (新規でいきなり終日になるのを避ける)。
    bool allDay = false;
    bool lockDuringEvent = existing?.lockDuringEvent ?? false;
    bool appLockDuringEvent = existing?.appLockDuringEvent ?? false;

    // 色パレット
    const palette = <int>[
      0xFFBA68C8, // 紫
      0xFF4FC3F7, // 水色
      0xFF43B97F, // 緑
      0xFFFF6B6B, // 赤
      0xFFFFB347, // オレンジ
      0xFF263238, // ブラック (旧 黄: 視認性が低かったため廃止)
      0xFFF06292, // ピンク
      0xFF4DB6AC, // ティール
      0xFF9E9E9E, // グレー
    ];

    Future<void> pickTime(bool isStart, StateSetter setD) async {
      // ── 数値で時刻指定 ──
      // ユーザー要望「予定登録の select time の所は UI ではなく、 数値で
      //   時間指定するようにして」 への対応。 時計ダイヤル (showTimePicker)
      //   ではなく、 時 (0-23) と 分 (0-59) を数値入力するダイアログにする。
      final current = isStart ? startTime : endTime;
      // ── デフォルト値: 現在時刻 + 1 時間、 分は切り捨て (= 00 分) ──
      // ユーザー要望「時刻入力を押したらデフォルトで現在時刻+1時間・分は
      //   切り捨てされた値から始める」 への対応。 例: 8:37 → 9:00。
      //   23 時台は +1 で 0 時に回り込む。
      final nowForDefault = DateTime.now();
      int h = (nowForDefault.hour + 1) % 24;
      int m = 0;
      if (current != null && current.contains(':')) {
        final parts = current.split(':');
        h = int.tryParse(parts[0]) ?? h;
        m = int.tryParse(parts[1]) ?? 0;
      }
      final hCtrl = TextEditingController(text: h.toString());
      final mCtrl = TextEditingController(text: m.toString().padLeft(2, '0'));
      final picked = await showDialog<String?>(
        context: ctx,
        builder: (dctx) => StatefulBuilder(
          builder: (sctx, setS) {
            String? compose() {
              final hh = int.tryParse(hCtrl.text.trim());
              final mm = int.tryParse(mCtrl.text.trim());
              if (hh == null || mm == null) return null;
              if (hh < 0 || hh > 23 || mm < 0 || mm > 59) return null;
              return '${hh.toString().padLeft(2, '0')}:'
                  '${mm.toString().padLeft(2, '0')}';
            }

            Widget numField(TextEditingController c, String label, int max,
                bool autofocusField) {
              return Expanded(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(label,
                        style: const TextStyle(
                            color: Colors.white54, fontSize: 11)),
                    const SizedBox(height: 4),
                    TextField(
                      controller: c,
                      autofocus: autofocusField,
                      keyboardType: TextInputType.number,
                      textAlign: TextAlign.center,
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 26,
                          fontWeight: FontWeight.w700),
                      decoration: InputDecoration(
                        filled: true,
                        fillColor: const Color(0xFF1A1A24),
                        contentPadding: const EdgeInsets.symmetric(
                            horizontal: 8, vertical: 10),
                        border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(8)),
                        hintText: provider
                            .t('common.range0toMax')
                            .replaceFirst('{max}', '$max'),
                        hintStyle: const TextStyle(
                            color: Colors.white24, fontSize: 13),
                      ),
                      onChanged: (_) => setS(() {}),
                      onSubmitted: (_) {
                        final v = compose();
                        if (v != null) Navigator.of(dctx).pop(v);
                      },
                    ),
                  ],
                ),
              );
            }

            final valid = compose() != null;
            return AlertDialog(
              backgroundColor: const Color(0xFF22222E),
              title: Text(
                  isStart
                      ? provider.t('cal.enterStartTime')
                      : provider.t('cal.enterEndTime'),
                  style: const TextStyle(color: Colors.white, fontSize: 15)),
              content: SizedBox(
                width: 240,
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.end,
                  children: [
                    numField(hCtrl, provider.t('cal.hour'), 23, true),
                    const Padding(
                      padding: EdgeInsets.symmetric(horizontal: 6),
                      child: Text(':',
                          style: TextStyle(
                              color: Colors.white,
                              fontSize: 26,
                              fontWeight: FontWeight.w700)),
                    ),
                    numField(mCtrl, provider.t('cal.minute'), 59, false),
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.of(dctx).pop(),
                  child: Text(provider.t('btn.cancel'),
                      style: const TextStyle(color: Colors.white54)),
                ),
                FilledButton(
                  onPressed:
                      valid ? () => Navigator.of(dctx).pop(compose()) : null,
                  child: const Text('OK'),
                ),
              ],
            );
          },
        ),
      );
      if (picked != null) {
        setD(() {
          if (isStart) {
            startTime = picked;
          } else {
            endTime = picked;
          }
        });
      }
    }

    await showDialog(
      context: ctx,
      builder: (dctx) => StatefulBuilder(
        builder: (sctx, setD) => AlertDialog(
          backgroundColor: const Color(0xFF2A2A3E),
          title: Row(children: [
            Icon(Icons.event_note_rounded, color: Color(colorArgb), size: 20),
            const SizedBox(width: 8),
            Text(provider.t('cal.eventTitle'),
                style: const TextStyle(color: Colors.white, fontSize: 14)),
            if (isGoogle) ...[
              const SizedBox(width: 8),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                decoration: BoxDecoration(
                  color: const Color(0xFF4285F4),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: const Text('G',
                    style: TextStyle(
                        color: Colors.white,
                        fontSize: 10,
                        fontWeight: FontWeight.w700)),
              ),
            ],
          ]),
          content: SizedBox(
            width: 380,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  // 日付ピッカー（タップで変更可能）
                  OutlinedButton.icon(
                    icon: const Icon(Icons.calendar_today, size: 16),
                    label: Text(
                        '${currentDate.year}/${currentDate.month}/${currentDate.day}'),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: Colors.white,
                      side: const BorderSide(color: Colors.white24),
                      padding: const EdgeInsets.symmetric(
                          vertical: 10, horizontal: 12),
                    ),
                    onPressed: isReadOnlyDialog
                        ? null
                        : () async {
                            final picked = await showDatePicker(
                              context: ctx,
                              initialDate: currentDate,
                              firstDate: DateTime(2000),
                              lastDate: DateTime(2100),
                            );
                            if (picked != null) {
                              setD(() {
                                currentDate = picked;
                                currentDateKey = _dateKey(picked);
                              });
                            }
                          },
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: titleCtrl,
                    autofocus: true,
                    readOnly: isReadOnlyDialog,
                    // Enter キーでダイアログを Save として閉じる
                    textInputAction: TextInputAction.done,
                    onSubmitted: isReadOnlyDialog
                        ? null
                        : (_) async {
                            await _saveCalendarEventFromDialog(
                                dctx,
                                provider,
                                dateKey,
                                currentDateKey,
                                effectiveExisting,
                                titleCtrl.text.trim(),
                                memoCtrl.text.trim(),
                                startTime,
                                endTime,
                                colorArgb,
                                notify: notifyEnabled && startTime != null,
                                notifyLeadMinutes: notifyLeadMinutes,
                                lockDuringEvent: lockDuringEvent &&
                                    !allDay &&
                                    startTime != null &&
                                    endTime != null,
                                appLockDuringEvent: appLockDuringEvent &&
                                    !allDay &&
                                    startTime != null &&
                                    endTime != null);
                          },
                    style: const TextStyle(color: Colors.white, fontSize: 13),
                    decoration: InputDecoration(
                      hintText: provider.t('cal.eventTitle'),
                      hintStyle: const TextStyle(color: Colors.white30),
                      filled: true,
                      fillColor: Colors.white10,
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(8),
                        borderSide: BorderSide.none,
                      ),
                    ),
                  ),
                  const SizedBox(height: 10),
                  // ── 終日トグル (ユーザー要望) ──
                  // ON にすると開始/終了時刻をクリアし、 下の時刻行を隠す。
                  // 保存時は時刻なし (= startTime/endTime が null) として
                  // 終日イベント扱いになる。
                  Row(children: [
                    const Icon(Icons.event_available_rounded,
                        size: 16, color: Colors.white54),
                    const SizedBox(width: 6),
                    Text(provider.t('cal.allDay'),
                        style: const TextStyle(
                            color: Colors.white70, fontSize: 13)),
                    const Spacer(),
                    Switch(
                      value: allDay,
                      onChanged: isReadOnlyDialog
                          ? null
                          : (v) => setD(() {
                                allDay = v;
                                if (v) {
                                  startTime = null;
                                  endTime = null;
                                  lockDuringEvent = false;
                                  appLockDuringEvent = false;
                                }
                              }),
                    ),
                  ]),
                  // 時刻
                  // OutlinedButton.icon だと icon + gap + label で横幅を食い、
                  // 狭いモバイル画面で "23:00" のようなテキストが 2 行に
                  // 折り返してしまう。アイコンを取り除いたシンプルな
                  // OutlinedButton にして label の横幅を最大化し、
                  // さらに FittedBox で仕上げに縮小する二重対策。
                  if (!allDay)
                    Row(children: [
                      Expanded(
                        child: OutlinedButton(
                          style: OutlinedButton.styleFrom(
                            foregroundColor: Colors.white,
                            side: const BorderSide(color: Colors.white24),
                            padding: const EdgeInsets.symmetric(horizontal: 8),
                          ),
                          onPressed: isReadOnlyDialog
                              ? null
                              : () => pickTime(true, setD),
                          child: FittedBox(
                            fit: BoxFit.scaleDown,
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                const Icon(Icons.schedule,
                                    size: 14, color: Colors.white70),
                                const SizedBox(width: 4),
                                Text(startTime ?? '--:--',
                                    maxLines: 1,
                                    overflow: TextOverflow.visible,
                                    softWrap: false),
                              ],
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      const Text('→', style: TextStyle(color: Colors.white54)),
                      const SizedBox(width: 8),
                      Expanded(
                        child: OutlinedButton(
                          style: OutlinedButton.styleFrom(
                            foregroundColor: Colors.white,
                            side: const BorderSide(color: Colors.white24),
                            padding: const EdgeInsets.symmetric(horizontal: 8),
                          ),
                          onPressed: isReadOnlyDialog
                              ? null
                              : () => pickTime(false, setD),
                          child: FittedBox(
                            fit: BoxFit.scaleDown,
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                const Icon(Icons.schedule,
                                    size: 14, color: Colors.white70),
                                const SizedBox(width: 4),
                                Text(endTime ?? '--:--',
                                    maxLines: 1,
                                    overflow: TextOverflow.visible,
                                    softWrap: false),
                              ],
                            ),
                          ),
                        ),
                      ),
                      if (startTime != null || endTime != null) ...[
                        const SizedBox(width: 4),
                        IconButton(
                          icon: const Icon(Icons.close,
                              color: Colors.white54, size: 16),
                          tooltip: 'clear',
                          onPressed: isReadOnlyDialog
                              ? null
                              : () => setD(() {
                                    startTime = null;
                                    endTime = null;
                                  }),
                        ),
                      ],
                    ]),
                  // 予定に紐づくロックは Android 専用 (= ユーザー要望)。
                  if (!isReadOnlyDialog && !allDay && !_isDesktop) ...[
                    const SizedBox(height: 8),
                    Row(children: [
                      const Icon(Icons.lock_clock_rounded,
                          size: 15, color: Color(0xFF4FC3F7)),
                      const SizedBox(width: 6),
                      Expanded(
                        child: Text(provider.t('cal.lockDuringEvent'),
                            style: const TextStyle(
                                color: Colors.white70, fontSize: 12)),
                      ),
                      Switch(
                        value: lockDuringEvent,
                        activeColor: const Color(0xFF4FC3F7),
                        onChanged: (v) => setD(() => lockDuringEvent = v),
                      ),
                    ]),
                    Padding(
                      padding: const EdgeInsets.only(left: 21, bottom: 2),
                      child: Text(provider.t('cal.lockDuringEventDesc'),
                          style: const TextStyle(
                              color: Colors.white54, fontSize: 10)),
                    ),
                    Row(children: [
                      const Icon(Icons.phonelink_lock_rounded,
                          size: 15, color: Color(0xFFEF5350)),
                      const SizedBox(width: 6),
                      Expanded(
                        child: Text(provider.t('cal.appLockDuringEvent'),
                            style: const TextStyle(
                                color: Colors.white70, fontSize: 12)),
                      ),
                      Switch(
                        value: appLockDuringEvent,
                        activeColor: const Color(0xFFEF5350),
                        onChanged: (v) => setD(() => appLockDuringEvent = v),
                      ),
                    ]),
                    Padding(
                      padding: const EdgeInsets.only(left: 21, bottom: 2),
                      child: Text(provider.t('cal.appLockDuringEventDesc'),
                          style: const TextStyle(
                              color: Colors.white54, fontSize: 10)),
                    ),
                  ],
                  const SizedBox(height: 10),
                  // ── 今から○分後に通知 (相対指定) ──
                  // ユーザー要望「時刻指定の他に、 何分後に通知するって項目を
                  //   作って、 現在時刻から 10 分後に通知したりできるように
                  //   して」 への対応。 タップすると現在時刻 + N 分を開始時刻に
                  //   セットし、 通知を ON にする (= 何分前 = 0 にしてちょうど
                  //   その時刻に通知)。 日付を跨ぐ場合に備えて currentDate も
                  //   再計算する。
                  // 終日 (allDay) の時は時刻を持たないので相対通知は隠す。
                  if (!isReadOnlyDialog && !allDay) ...[
                    Align(
                      alignment: Alignment.centerLeft,
                      child: Text(provider.t('cal.notifyFromNow'),
                          style: const TextStyle(
                              color: Colors.white60, fontSize: 11)),
                    ),
                    const SizedBox(height: 4),
                    Wrap(
                      spacing: 6,
                      runSpacing: 6,
                      children: [
                        for (final mins in const [10, 30, 60])
                          ActionChip(
                            label: Text(mins >= 60
                                ? provider
                                    .t('cal.hoursLater')
                                    .replaceAll('{n}', '${mins ~/ 60}')
                                : provider
                                    .t('cal.minutesLater')
                                    .replaceAll('{n}', '$mins')),
                            backgroundColor: const Color(0xFF3A3A4A),
                            labelStyle: const TextStyle(
                                color: Colors.white, fontSize: 11),
                            side: const BorderSide(color: Colors.white24),
                            onPressed: () {
                              final target =
                                  DateTime.now().add(Duration(minutes: mins));
                              setD(() {
                                currentDate = DateTime(
                                    target.year, target.month, target.day);
                                currentDateKey = _dateKey(currentDate);
                                startTime =
                                    '${target.hour.toString().padLeft(2, '0')}:'
                                    '${target.minute.toString().padLeft(2, '0')}';
                                notifyEnabled = true;
                                notifyLeadMinutes = 0;
                              });
                            },
                          ),
                        // その他 (~日~時~分後を数値入力)
                        ActionChip(
                          label: Text(provider.t('cal.other')),
                          backgroundColor: const Color(0xFF3A3A4A),
                          labelStyle: const TextStyle(
                              color: Colors.white, fontSize: 11),
                          side: const BorderSide(color: Colors.white24),
                          onPressed: () async {
                            final v = await _showRelativeNotifyDialog(provider);
                            if (v != null && v > 0) {
                              final target =
                                  DateTime.now().add(Duration(minutes: v));
                              setD(() {
                                currentDate = DateTime(
                                    target.year, target.month, target.day);
                                currentDateKey = _dateKey(currentDate);
                                startTime =
                                    '${target.hour.toString().padLeft(2, '0')}:'
                                    '${target.minute.toString().padLeft(2, '0')}';
                                notifyEnabled = true;
                                notifyLeadMinutes = 0;
                              });
                            }
                          },
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                  ],
                  // ── 通知する トグル ──
                  // ユーザー要望「時刻入力しないとトグルをオンにできないなら、
                  //   時刻入力するまで隠しておいて」 への対応。 開始時刻が無い
                  //   ときは通知トグルそのものを表示しない (= startTime != null
                  //   が条件)。 「今から通知」 ボタン or 開始時刻の指定で
                  //   startTime がセットされると、 このトグルが現れる。
                  if (!isReadOnlyDialog && !allDay && startTime != null) ...[
                    Row(children: [
                      const Icon(Icons.notifications_active_outlined,
                          size: 15, color: Color(0xFFFFA726)),
                      const SizedBox(width: 6),
                      Text(provider.t('cal.notify'),
                          style: const TextStyle(
                              color: Colors.white70, fontSize: 12)),
                      const Spacer(),
                      Switch(
                        value: notifyEnabled,
                        activeColor: const Color(0xFFFFA726),
                        onChanged: (v) => setD(() => notifyEnabled = v),
                      ),
                    ]),
                    // 何分前に通知するか (通知 ON の時だけ)
                    if (notifyEnabled)
                      Padding(
                        padding:
                            const EdgeInsets.only(left: 21, top: 2, bottom: 2),
                        child: Wrap(
                          spacing: 6,
                          runSpacing: 6,
                          children: [
                            for (final lead in const [
                              (0, '開始時刻'),
                              (5, '5分前'),
                              (10, '10分前'),
                              (30, '30分前'),
                              (60, '1時間前'),
                            ])
                              () {
                                final sel = notifyLeadMinutes == lead.$1;
                                return ChoiceChip(
                                  label: Text(lead.$2),
                                  selected: sel,
                                  onSelected: (_) =>
                                      setD(() => notifyLeadMinutes = lead.$1),
                                  selectedColor: const Color(0xFFFFA726),
                                  backgroundColor: const Color(0xFF3A3A4A),
                                  showCheckmark: false,
                                  labelStyle: TextStyle(
                                    color: sel ? Colors.black : Colors.white,
                                    fontSize: 11,
                                    fontWeight:
                                        sel ? FontWeight.w700 : FontWeight.w500,
                                  ),
                                  side: BorderSide(
                                    color: sel
                                        ? const Color(0xFFFFA726)
                                        : Colors.white24,
                                    width: 1,
                                  ),
                                );
                              }(),
                            // ── その他 (数値で何分前か直接指定) ──
                            // ユーザー要望「予定時刻の何分前に通知するかを
                            //   設定できるようにして」 を、 プリセット以外の
                            //   任意の分数でも指定できるよう数値入力を用意。
                            () {
                              const presets = {0, 5, 10, 30, 60};
                              final isCustom =
                                  !presets.contains(notifyLeadMinutes);
                              final label =
                                  isCustom
                                      ? provider
                                          .t('cal.minutesBefore')
                                          .replaceFirst(
                                              '{n}', '$notifyLeadMinutes')
                                      : provider.t('cal.other');
                              return ChoiceChip(
                                label: Text(label),
                                selected: isCustom,
                                onSelected: (_) async {
                                  final v = await _showIntInputDialog(
                                    title: provider.t('tl.notifyLeadTitle'),
                                    initial: notifyLeadMinutes,
                                    min: 0,
                                    max: 1440,
                                  );
                                  if (v != null) {
                                    setD(() => notifyLeadMinutes = v);
                                  }
                                },
                                selectedColor: const Color(0xFFFFA726),
                                backgroundColor: const Color(0xFF3A3A4A),
                                showCheckmark: false,
                                labelStyle: TextStyle(
                                  color: isCustom ? Colors.black : Colors.white,
                                  fontSize: 11,
                                  fontWeight: isCustom
                                      ? FontWeight.w700
                                      : FontWeight.w500,
                                ),
                                side: BorderSide(
                                  color: isCustom
                                      ? const Color(0xFFFFA726)
                                      : Colors.white24,
                                  width: 1,
                                ),
                              );
                            }(),
                          ],
                        ),
                      ),
                    const SizedBox(height: 8),
                  ],
                  // 色パレット
                  Text(provider.t('cal.color'),
                      style:
                          const TextStyle(color: Colors.white60, fontSize: 11)),
                  const SizedBox(height: 4),
                  Wrap(
                    spacing: 6,
                    runSpacing: 6,
                    children: palette.map((c) {
                      final selected = c == colorArgb;
                      return GestureDetector(
                        onTap: isReadOnlyDialog
                            ? null
                            : () => setD(() => colorArgb = c),
                        child: Container(
                          width: 26,
                          height: 26,
                          decoration: BoxDecoration(
                            color: Color(c),
                            shape: BoxShape.circle,
                            border: Border.all(
                              color: selected ? Colors.white : Colors.white30,
                              width: selected ? 2 : 1,
                            ),
                          ),
                          child: selected
                              ? const Icon(Icons.check,
                                  size: 14, color: Colors.white)
                              : null,
                        ),
                      );
                    }).toList(),
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: memoCtrl,
                    maxLines: 3,
                    readOnly: isReadOnlyDialog,
                    style: const TextStyle(color: Colors.white, fontSize: 12),
                    decoration: InputDecoration(
                      hintText: provider.t('cal.memo'),
                      hintStyle: const TextStyle(color: Colors.white30),
                      filled: true,
                      fillColor: Colors.white10,
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(8),
                        borderSide: BorderSide.none,
                      ),
                    ),
                  ),
                  if (isGoogle)
                    Padding(
                      padding: const EdgeInsets.only(top: 8),
                      child: Text(
                        provider.t('cal.googleReadOnly'),
                        style: TextStyle(
                            color: Colors.white38,
                            fontSize: 10,
                            fontStyle: FontStyle.italic),
                      ),
                    ),
                ],
              ),
            ),
          ),
          actions: [
            // 削除ボタン: 既存ローカルイベントの時だけ表示
            if (effectiveExisting != null && !isReadOnlyDialog)
              TextButton.icon(
                icon: const Icon(Icons.delete,
                    color: Color(0xFFFF6B6B), size: 18),
                label: Text(provider.t('ctx.delete'),
                    style: const TextStyle(color: Color(0xFFFF6B6B))),
                onPressed: () async {
                  // 確認ダイアログなしで即削除（Undo で復元可能）
                  await provider.removeCalendarEvent(
                      dateKey, effectiveExisting.id);
                  if (dctx.mounted) Navigator.pop(dctx);
                  if (mounted) {
                    _appSnack(
                        context,
                        SnackBar(
                          content: Text(provider.t('cal.deleteSuccess')),
                          duration: const Duration(seconds: 1),
                        ));
                  }
                },
              ),
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white60)),
            ),
            if (!isReadOnlyDialog)
              ElevatedButton(
                style:
                    ElevatedButton.styleFrom(backgroundColor: Color(colorArgb)),
                onPressed: () async {
                  final title = titleCtrl.text.trim();
                  if (title.isEmpty) {
                    Navigator.pop(dctx);
                    return;
                  }
                  await _saveCalendarEventFromDialog(
                      dctx,
                      provider,
                      dateKey,
                      currentDateKey,
                      effectiveExisting,
                      title,
                      memoCtrl.text.trim(),
                      startTime,
                      endTime,
                      colorArgb,
                      // ── 通知予約 (= 後で通知 統合) ──
                      notify: notifyEnabled && startTime != null,
                      notifyLeadMinutes: notifyLeadMinutes,
                      lockDuringEvent: lockDuringEvent &&
                          !allDay &&
                          startTime != null &&
                          endTime != null,
                      appLockDuringEvent: appLockDuringEvent &&
                          !allDay &&
                          startTime != null &&
                          endTime != null);
                },
                child: Text(provider.t('btn.save'),
                    style: const TextStyle(color: Colors.white)),
              ),
          ],
        ),
      ),
    );
  }

  /// 「~日~時~分後に通知」 を数値入力するダイアログ。 合計分数を返す
  /// (キャンセル時 / 0 の時は呼び出し側で通知しない)。 デフォルトは 0/0/0。
  /// ユーザー要望: 「何分後だと 3 日後とか設定しにくいから ~日~時~分後で
  ///   設定できるように。 デフォルトは 0」。
  Future<int?> _showRelativeNotifyDialog(MindMapProvider provider) async {
    final dCtrl = TextEditingController(text: '0');
    final hCtrl = TextEditingController(text: '0');
    final mCtrl = TextEditingController(text: '0');
    return showDialog<int>(
      context: context,
      builder: (dctx) => StatefulBuilder(
        builder: (sctx, setS) {
          int parse(TextEditingController c) =>
              int.tryParse(c.text.trim()) ?? 0;
          final total = parse(dCtrl) * 1440 + parse(hCtrl) * 60 + parse(mCtrl);
          Widget field(TextEditingController c, String label) => Expanded(
                child: Column(mainAxisSize: MainAxisSize.min, children: [
                  Text(label,
                      style:
                          const TextStyle(color: Colors.white54, fontSize: 11)),
                  const SizedBox(height: 4),
                  TextField(
                    controller: c,
                    keyboardType: TextInputType.number,
                    textAlign: TextAlign.center,
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 22,
                        fontWeight: FontWeight.w700),
                    decoration: InputDecoration(
                      filled: true,
                      fillColor: const Color(0xFF1A1A24),
                      contentPadding: const EdgeInsets.symmetric(
                          horizontal: 8, vertical: 10),
                      border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(8)),
                      hintText: '0',
                      hintStyle: const TextStyle(color: Colors.white24),
                    ),
                    onChanged: (_) => setS(() {}),
                  ),
                ]),
              );
          return AlertDialog(
            backgroundColor: const Color(0xFF22222E),
            title: Text(provider.t('cal.relativeNotifyTitle'),
                style: const TextStyle(color: Colors.white, fontSize: 15)),
            content: SizedBox(
              width: 300,
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                Row(crossAxisAlignment: CrossAxisAlignment.end, children: [
                  field(dCtrl, provider.t('cal.days')),
                  const SizedBox(width: 6),
                  field(hCtrl, provider.t('cal.hour')),
                  const SizedBox(width: 6),
                  field(mCtrl, provider.t('cal.minute')),
                ]),
                const SizedBox(height: 8),
                Align(
                  alignment: Alignment.centerLeft,
                  child: Text(provider.t('cal.relativeNotifyHint'),
                      style:
                          const TextStyle(color: Colors.white38, fontSize: 11)),
                ),
              ]),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dctx),
                child: Text(provider.t('btn.cancel'),
                    style: const TextStyle(color: Colors.white54)),
              ),
              ElevatedButton(
                style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFFFFA726),
                    foregroundColor: Color(0xFF10241F),),
                onPressed: total <= 0 ? null : () => Navigator.pop(dctx, total),
                child: Text(provider.t('coupon.apply')),
              ),
            ],
          );
        },
      ),
    );
  }

  /// ダイアログからのイベント保存処理（日付変更対応）
  Future<void> _saveCalendarEventFromDialog(
      BuildContext dctx,
      MindMapProvider provider,
      String originalDateKey,
      String newDateKey,
      CalendarEvent? existing,
      String title,
      String memo,
      String? startTime,
      String? endTime,
      int colorArgb,
      {bool notify = false,
      int notifyLeadMinutes = 0,
      bool lockDuringEvent = false,
      bool appLockDuringEvent = false}) async {
    if (title.isEmpty) {
      if (dctx.mounted) Navigator.pop(dctx);
      return;
    }
    final memoOpt = memo.isEmpty ? null : memo;
    if (existing == null) {
      // 新規作成: 指定された日付キーに追加
      await provider.addCalendarEvent(newDateKey, title,
          memo: memoOpt,
          startTime: startTime,
          endTime: endTime,
          colorArgb: colorArgb,
          lockDuringEvent: lockDuringEvent,
          appLockDuringEvent: appLockDuringEvent);
    } else if (newDateKey != originalDateKey) {
      // 日付が変わった: 旧日付から削除 → 新日付に追加
      await provider.removeCalendarEvent(originalDateKey, existing.id);
      await provider.addCalendarEvent(newDateKey, title,
          memo: memoOpt,
          startTime: startTime,
          endTime: endTime,
          colorArgb: colorArgb,
          lockDuringEvent: lockDuringEvent,
          appLockDuringEvent: appLockDuringEvent);
    } else {
      // 通常の更新
      await provider.updateCalendarEvent(originalDateKey, existing.id, title,
          memo: memoOpt,
          startTime: startTime,
          endTime: endTime,
          colorArgb: colorArgb,
          lockDuringEvent: lockDuringEvent,
          appLockDuringEvent: appLockDuringEvent);
    }

    // ── 通知予約 (= 「後で通知」 を予定登録に統合) ──
    // ユーザー要望「後で通知を予定登録と纏めて欲しい」 への対応。
    // notify=true かつ 開始時刻あり の時、 イベント開始時刻 (- 何分前)
    // に OS 通知 + アプリ内オーバーレイを予約する。 カレンダー登録は上で
    // 済んでいるので、 ここでは _scheduleAbsoluteNotification (= 通知のみ、
    // カレンダー二重登録しない) を使う。
    if (notify && startTime != null) {
      try {
        final parts = startTime.split(':');
        if (parts.length == 2) {
          final h = int.tryParse(parts[0]) ?? 0;
          final m = int.tryParse(parts[1]) ?? 0;
          final d = DateTime.parse(newDateKey);
          final fireAt = DateTime(d.year, d.month, d.day, h, m)
              .subtract(Duration(minutes: notifyLeadMinutes));
          // 通知 ID: 日付 + 時刻 + タイトル のハッシュ (32bit)。
          final notifId = ('$newDateKey$startTime$title').hashCode & 0x7FFFFFFF;
          _scheduleAbsoluteNotification(
            notifId: notifId,
            title: title,
            body: memo,
            fireAt: fireAt,
          );
        }
      } catch (e) {
        debugPrint('予定登録からの通知予約に失敗: $e');
      }
    }

    _checkFocusLockSchedule();
    if (dctx.mounted) Navigator.pop(dctx);
  }

  // (旧) Google Calendar 設定ダイアログ / モバイルサインインダイアログは
  // Google Calendar 連携の廃止に伴い削除。Firebase 経由の同期グループのみで
  // 動作するため、これらを呼ぶ UI もまとめて取り除き済み。

  /// ノードがリンク (link_url / youtube_url / video_storage_url のいずれか)
  /// を持っているかどうか。
  bool _nodeHasLink(MindMapNode node) {
    return (node.youtubeUrl ?? '').isNotEmpty ||
        (node.linkUrl ?? '').isNotEmpty ||
        (node.videoStorageUrl ?? '').isNotEmpty;
  }

  /// ノードに紐づく URL を 1 つ返す。優先順は link_url > video_storage_url
  /// > youtube_url。何も無ければ空文字。
  String _nodeGetLink(MindMapNode node) {
    if ((node.linkUrl ?? '').isNotEmpty) return node.linkUrl!;
    // ローカル動画ファイルの場合、Storage URLがあればそちらを優先
    if ((node.videoStorageUrl ?? '').isNotEmpty) {
      return node.videoStorageUrl!;
    }
    return node.youtubeUrl ?? '';
  }

  // ─── リンクノード追加（キャンバス右クリック・下部ツールバー共通） ─────────────

  void _addLinkNodeFromCanvas(BuildContext ctx, MindMapProvider provider,
      TransformationController ctrl, Offset globalPos) {
    final urlCtrl = TextEditingController();
    void doAdd(BuildContext dctx) {
      final url = urlCtrl.text.trim();
      if (url.isEmpty) return;
      Navigator.pop(dctx);
      final canvasPos = _globalToCanvas(globalPos, ctrl);
      provider.addNodeAtCenter(canvasPos - const Offset(80, 21));
      final nodeId = provider.selectedNodeId;
      if (nodeId != null) {
        final playlistId = _extractPlaylistId(url);
        if (playlistId != null) {
          final node = provider.nodes[nodeId];
          if (node != null) {
            _loadPlaylistVideos(playlistId, node, provider, originalUrl: url);
          }
          return;
        }
        final channelInfo = _extractChannelInfo(url);
        if (channelInfo != null) {
          final node = provider.nodes[nodeId];
          if (node != null) {
            _pickChannelMode().then((mode) {
              if (mode == null) return;
              provider.setChannelMode(mode);
              _loadPlaylistVideos(channelInfo.$1, node, provider,
                  customUrl: channelInfo.$2,
                  isChannel: true,
                  channelMode: mode,
                  originalUrl: url);
            });
          }
          return;
        }
        final videoId = NodeWidget.extractVideoId(url);
        if (videoId != null) {
          provider.updateNodeYoutube(nodeId, url);
          provider.updateNodeLink(nodeId, '');
          _fetchYoutubeTitle(videoId, nodeId, provider, force: true);
        } else if (NodeWidget.isMp4Url(url)) {
          provider.updateNodeYoutube(nodeId, url);
          provider.updateNodeLink(nodeId, '');
          provider.generateVideoThumbnail(nodeId);
        } else {
          provider.updateNodeLink(nodeId, url);
          provider.updateNodeYoutube(nodeId, '');
        }
      }
    }

    showDialog(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Row(children: [
          Container(
              width: 28,
              height: 28,
              decoration: const BoxDecoration(
                  color: Color(0xFF4FC3F7), shape: BoxShape.circle),
              child: const Icon(Icons.link_rounded,
                  color: Colors.white, size: 18)),
          const SizedBox(width: 10),
          Text(provider.t('link.addTitle'),
              style: const TextStyle(color: Colors.white, fontSize: 14)),
        ]),
        content: TextField(
          controller: urlCtrl,
          autofocus: true,
          keyboardType: TextInputType.url,
          style: const TextStyle(color: Colors.white, fontSize: 14),
          decoration: InputDecoration(
            filled: true,
            fillColor: Colors.white.withValues(alpha: 0.07),
            hintText: 'https://...',
            hintStyle: const TextStyle(color: Colors.white38, fontSize: 13),
            border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
                borderSide: BorderSide.none),
            prefixIcon:
                const Icon(Icons.link_rounded, color: Colors.white38, size: 18),
            contentPadding:
                const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
          ),
          onSubmitted: (_) => doAdd(dctx),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('node.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
            onPressed: () => doAdd(dctx),
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF4FC3F7),
                foregroundColor: Color(0xFF10241F),),
            child: Text(provider.t('link.addButton')),
          ),
        ],
      ),
    );
  }

