  // ─── ドラッグ＆ドロップでファイル添付 ────────────────────────────────────────

  /// 拡張子から MIME type を推定 (= WebView に File オブジェクトを渡すとき
  /// type を正しくセットしないと AI 側が「対応外」 と弾くため必要)。
  String _mimeFromFileName(String name) {
    final l = name.toLowerCase();
    if (l.endsWith('.png')) return 'image/png';
    if (l.endsWith('.jpg') || l.endsWith('.jpeg')) return 'image/jpeg';
    if (l.endsWith('.gif')) return 'image/gif';
    if (l.endsWith('.webp')) return 'image/webp';
    if (l.endsWith('.bmp')) return 'image/bmp';
    if (l.endsWith('.svg')) return 'image/svg+xml';
    if (l.endsWith('.pdf')) return 'application/pdf';
    if (l.endsWith('.txt')) return 'text/plain';
    if (l.endsWith('.md')) return 'text/markdown';
    if (l.endsWith('.json')) return 'application/json';
    if (l.endsWith('.ipynb')) return 'application/json';
    if (l.endsWith('.csv')) return 'text/csv';
    if (l.endsWith('.html') || l.endsWith('.htm')) return 'text/html';
    if (l.endsWith('.docx')) {
      return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
    }
    if (l.endsWith('.xlsx')) {
      return 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
    }
    if (l.endsWith('.pptx')) {
      return 'application/vnd.openxmlformats-officedocument.presentationml.presentation';
    }
    if (l.endsWith('.doc')) return 'application/msword';
    if (l.endsWith('.mp4')) return 'video/mp4';
    if (l.endsWith('.webm')) return 'video/webm';
    if (l.endsWith('.mp3')) return 'audio/mpeg';
    if (l.endsWith('.wav')) return 'audio/wav';
    if (l.endsWith('.zip')) return 'application/zip';
    return 'application/octet-stream';
  }

  /// 生成 AI の WebView にファイルを「paste 相当」 で送り込む。
  ///
  /// ユーザー要望「ファイルをアップロードしようとするとマップが反応して
  ///   しまって生成 AI にドラッグ＆ドロップでファイルを渡すことができない
  ///   からドラッグ＆ドロップで生成 AI にアプリ内からちゃんとファイルが
  ///   渡せるようにして」 への対応。
  ///
  /// 戦略:
  ///   1. ファイルを base64 で読み取り、 WebView 側で File オブジェクトに再構築
  ///   2. ページ内の `input[type="file"]` があればそれに files をセットして
  ///      change イベント発火 (= 通常のファイル選択と同じ扱い)
  ///   3. それでも反応しない/見つからない場合は、 contenteditable / textarea
  ///      に対して ClipboardEvent('paste') を file 付きでディスパッチ
  ///      (= Claude / Gemini / ChatGPT すべて貼り付けでアップロードに対応)
  ///
  /// パフォーマンス: 1 ファイルあたり 20 MB を上限。 それ以上は SnackBar 警告。
  Future<bool> _injectFileToWebView(dynamic xfile,
      {required bool isLeftPanel}) async {
    final provider = context.read<MindMapProvider>();
    try {
      final path = xfile.path as String;
      final name = path.split(Platform.pathSeparator).last;
      final file = File(path);
      if (!await file.exists()) return false;
      final size = await file.length();
      const maxBytes = 20 * 1024 * 1024;
      if (size > maxBytes) {
        if (mounted) {
          _appSnack(
              context,
              SnackBar(
                content: Text(provider
                    .t('webview.over20mb')
                    .replaceFirst('{name}', name)),
                backgroundColor: Colors.redAccent,
                duration: const Duration(seconds: 3),
              ));
        }
        return false;
      }
      final bytes = await file.readAsBytes();
      final b64 = base64Encode(bytes);
      final mime = _mimeFromFileName(name);
      // JS 文字列に直接埋め込むため、 シングルクォートをエスケープ
      final safeName = name.replaceAll('\\', '\\\\').replaceAll("'", "\\'");
      final js = '''
        (async function() {
          try {
            // base64 → Uint8Array
            const b64 = '$b64';
            const bin = atob(b64);
            const arr = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
            const blob = new Blob([arr], { type: '$mime' });
            const file = new File([blob], '$safeName',
                { type: '$mime', lastModified: Date.now() });
            // 戦略 1: input[type="file"] にセット
            const inputs = document.querySelectorAll('input[type="file"]');
            if (inputs.length > 0) {
              const dt = new DataTransfer();
              dt.items.add(file);
              const inp = inputs[0];
              inp.files = dt.files;
              inp.dispatchEvent(new Event('input', { bubbles: true }));
              inp.dispatchEvent(new Event('change', { bubbles: true }));
              return 'input';
            }
            // 戦略 2: contenteditable / textarea に paste
            const cands = document.querySelectorAll(
                'div[contenteditable="true"],textarea,'
                + 'div[role="textbox"],p[contenteditable="true"]');
            if (cands.length === 0) return 'no-target';
            const target = cands[cands.length - 1];
            target.focus();
            const dt2 = new DataTransfer();
            dt2.items.add(file);
            const ev = new ClipboardEvent('paste', {
              clipboardData: dt2,
              bubbles: true,
              cancelable: true,
            });
            target.dispatchEvent(ev);
            return 'paste';
          } catch (e) {
            return 'error: ' + e.message;
          }
        })();
      ''';
      if (Platform.isWindows) {
        final ctrl =
            isLeftPanel ? _splitLeftWinController : _splitWinController;
        await ctrl?.executeScript(js);
      } else {
        final ctrl =
            isLeftPanel ? _splitLeftIawController : _splitIawController;
        await ctrl?.evaluateJavascript(source: js);
      }
      return true;
    } catch (e) {
      debugPrint('_injectFileToWebView 失敗: $e');
      return false;
    }
  }

  /// ドロップ位置が「画面分割パネルの web モード領域」 内か判定。
  /// 真なら WebView に inject、 偽ならマップ処理に流す。
  /// 戻り値: 'right' / 'left' / null (= マップに流す)
  ///
  /// ── 修正履歴 ──
  /// 旧実装は raw な `_splitPanelWidth` (= 保存された未クランプの値) と
  /// 比較していたため、 画面サイズに応じて自動クランプされた実際の表示
  /// パネルサイズ (= `_splitPanelEffectiveSize`) とズレが生じ、 ユーザー
  /// から見た「パネルの上」にドロップしても null が返ってマップに流れる
  /// 問題があった。 さらに top / bottom 分割の場合に「幅の値」を「高さ」
  /// と比較していたため、 縦分割ではほぼ確実にミスヒットしていた。
  /// → クランプ後のサイズを使い、 上下/左右で正しい軸を見るように修正。
  /// 同時に境界の取りこぼし防止のため 4px のヒットマージンを設けた。
  String? _splitPanelHitForDrop(Offset localPos) {
    if (!mounted) return null;
    final mq = MediaQuery.of(context);
    final w = mq.size.width;
    final h = mq.size.height;
    const hitMargin = 4.0; // 境界ちょうどでも拾えるよう余裕を持たせる

    // ── 右パネル (= 通常の split panel) ──
    if (_splitOpen && _splitMode == 'web' && _splitCurrentUrl.isNotEmpty) {
      // 表示中の実サイズ (= 画面サイズに対するクランプ後)
      final eff = _splitPanelEffectiveSize(context);
      switch (_splitPosition) {
        case _SplitPosition.right:
          if (localPos.dx >= w - eff - hitMargin) return 'right';
          break;
        case _SplitPosition.left:
          if (localPos.dx < eff + hitMargin) return 'right';
          break;
        case _SplitPosition.top:
          if (localPos.dy < eff + hitMargin) return 'right';
          break;
        case _SplitPosition.bottom:
          if (localPos.dy >= h - eff - hitMargin) return 'right';
          break;
      }
    }
    // ── 左パネル (= 並列表示) ──
    // 左パネルも同様に画面幅でクランプされた実サイズで判定する。
    if (_splitLeftOpen &&
        _splitLeftMode == 'web' &&
        _splitLeftCurrentUrl.isNotEmpty) {
      final leftEff = _splitLeftPanelWidth.clamp(w * 0.20, w * 0.90).toDouble();
      if (localPos.dx < leftEff + hitMargin) return 'left';
    }
    return null;
  }

  Future<void> _handleDroppedFiles(List<dynamic> files,
      MindMapProvider provider, TransformationController ctrl,
      {Offset? dropLocalPosition, List<int>? shelfStartCell}) async {
    final appDir = await getApplicationDocumentsDirectory();
    final attachDir = Directory('${appDir.path}/attachments');
    if (!await attachDir.exists()) {
      await attachDir.create(recursive: true);
    }
    // ── ドロップ位置の解決 ──
    // dropLocalPosition (= viewer 上のローカル座標) が渡されればそれを
    // キャンバス座標に変換。 渡されない場合は画面中央をデフォルト。
    final s = View.of(context).physicalSize / View.of(context).devicePixelRatio;
    Offset baseCenter;
    if (dropLocalPosition != null) {
      baseCenter = _globalToCanvas(dropLocalPosition, ctrl);
    } else {
      baseCenter = _globalToCanvas(Offset(s.width / 2, s.height / 2), ctrl);
    }
    double offsetY = 0;

    // ── 升目の大きさ (= ユーザー要望: きれいに整列) ──
    //    サムネイル付きのノードが収まる大きさに合わせてある。
    const double kDropCellW = 300.0;
    const double kDropCellH = 360.0;
    int dropCols = 1;
    int dropPlaced = 0;

    // ── ギャラリー: ドロップ先のセルを決める (= ユーザー要望) ──
    // +ボックスに的確にドロップ (or +ボックスタップ → ファイル選択) ならその
    // セルから右へ連ねる。 フロンティア外への適当なドロップはセル未指定 =
    // 自動整列で「今出てる下の段の右」 へ並ぶ。
    final bool isShelf = provider.currentPage.pageType == 'bookshelf';
    List<int>? shelfCell = shelfStartCell;
    if (isShelf && shelfCell == null && dropLocalPosition != null) {
      shelfCell = provider.bookshelfFrontierCellAt(baseCenter);
    }
    int shelfK = 0;

    // ── ファイルとディレクトリを分けて処理 ──
    // 1. ディレクトリは「マップ上に階層化」 してマインドマップとして展開
    //    (ユーザー要望: フォルダーをマップ上にドラッグ&ドロップしたら
    //     ちゃんとそのマップ上にファイルが階層分けされて表示)
    // 2. 通常ファイルは従来通り個別ノードに添付
    final droppedDirs = <String>[];
    final droppedFiles = <dynamic>[];
    for (final xFile in files) {
      final path = xFile.path as String;
      try {
        final stat = FileStat.statSync(path);
        if (stat.type == FileSystemEntityType.directory) {
          droppedDirs.add(path);
        } else {
          droppedFiles.add(xFile);
        }
      } catch (_) {
        droppedFiles.add(xFile);
      }
    }
    if (isShelf &&
        droppedFiles.isNotEmpty &&
        !await _confirmGalleryExpand(context, provider, droppedFiles.length)) {
      return;
    }

    // ── 何個も落とした時の並べ方 (= ユーザー要望: 画面の中に見えるように
    //    置く。 入り切らない分は 2 列目・3 列目へ折り返す) ──
    //    見えている範囲をキャンバスの座標に直して、 その中に収まる位置から
    //    並べ始める。 下の方に落とした時は上へ引き上げる。
    {
      try {
        // ヘッダーや下のボタン列に隠れない範囲を見る (= ユーザー報告:
        // 一番上の実体部分が切れてしまう)。
        const chromeTop = 96.0; // 上のヘッダー
        const chromeBottom = 110.0; // 下のボタン列
        final visTopLeft =
            _globalToCanvas(const Offset(0, chromeTop), ctrl);
        final visBottomRight = _globalToCanvas(
            Offset(s.width, s.height - chromeBottom), ctrl);
        final visTop = visTopLeft.dy + 20;
        final visBottom = visBottomRight.dy - 20;
        final visLeft = visTopLeft.dx + 20;
        final visRight = visBottomRight.dx - 20;
        final availH = (visBottom - visTop);
        final availW = (visRight - visLeft);
        if (availH.isFinite && availH > 200 && availW.isFinite) {
          // 見えている幅に入る列数で升目を組む。
          final n = droppedFiles.length;
          dropCols = (availW / kDropCellW).floor().clamp(1, 8);
          if (dropCols > n) dropCols = n < 1 ? 1 : n;
          final rows = (n / dropCols).ceil();
          final blockW = dropCols * kDropCellW;
          final blockH = rows * kDropCellH;
          // 落とした場所を左上にしつつ、 画面からはみ出す時は引き戻す。
          final startY = baseCenter.dy
              .clamp(visTop, math.max(visTop, visBottom - blockH));
          final startX = baseCenter.dx
              .clamp(visLeft, math.max(visLeft, visRight - blockW));
          baseCenter = Offset(startX.toDouble(), startY.toDouble());
        }
      } catch (_) {}
    }

    // ── ここから先の追加は 1 回分の取り消しにまとめる (= ユーザー要望:
    //    まとめて埋め込んだ後の Ctrl+Z が 1 個ずつで面倒)。 ──
    provider.beginUndoBatch();
    try {

    // ── ディレクトリを順に処理 ──
    // 各ディレクトリを「ドロップ位置を起点に階層化」 する。
    // 複数フォルダ同時ドロップ時は、 Y 方向に少しずつずらして配置。
    for (int i = 0; i < droppedDirs.length; i++) {
      final dirPath = droppedDirs[i];
      final rootPos = Offset(
        baseCenter.dx - 80,
        baseCenter.dy - 21 + offsetY,
      );
      await _createMapFromFolderAt(
          context, provider, Directory(dirPath), rootPos);
      offsetY += 100; // 次のフォルダはやや下に
    }

    // ── 通常ファイルの処理 (従来ロジック) ──
    for (final xFile in droppedFiles) {
      final path = xFile.path as String;
      final name = path.split('/').last.split('\\').last;
      final ext = name.split('.').last.toLowerCase();

      final destPath = '${attachDir.path}/$name';
      try {
        await File(path).copy(destPath);
      } catch (_) {
        continue;
      }
      final isImage = ext == 'jpg' || ext == 'jpeg' || ext == 'png';
      final isVideo = ext == 'mp4' || ext == 'mov' || ext == 'm4v';

      // ── 縦に並べ、 画面からはみ出す分は次の列へ (= ユーザー要望) ──
      //    サムネイルが付く物は背が高いので、 種類ごとに送り幅を変えて
      //    重ならないようにする。
      // ── 升目にきれいに並べる (= ユーザー要望: 並びが汚い) ──
      //    種類で送り幅を変えると段がガタつくので、 1 個分の枠を同じ
      //    大きさにして左から右へ、 いっぱいになったら次の段へ置く。
      final col = dropPlaced % dropCols;
      final row = dropPlaced ~/ dropCols;
      dropPlaced++;
      final pos = baseCenter +
          Offset(-80 + col * kDropCellW, -21 + row * kDropCellH);
      provider.addNodeAtCenter(pos);
      final nodeId = provider.selectedNodeId;
      if (nodeId != null) {
        if (isVideo) {
          provider.updateNodeTitle(
              nodeId, name.replaceAll(RegExp(r'\.[^.]+$'), ''));
          provider.updateNodeYoutube(nodeId, destPath);
          provider.updateNodeLink(nodeId, '');
          provider.updateNodeSize(nodeId, 180, 42);
          provider.generateVideoThumbnail(nodeId);
        } else {
          if (!isImage) {
            provider.updateNodeTitle(nodeId, name);
          }
          provider.updateNodeAttachment(nodeId, destPath, name);
          if (isImage) {
            provider.updateNodeSize(nodeId, 180, 42);
          } else if (const ['pdf', 'pptx', 'docx', 'xlsx'].contains(ext)) {
            // ── 1 枚目をサムネイル化してノードに付ける (= ユーザー要望) ──
            // 非同期で生成し、 完了したらノードに反映 (ドロップ直後は従来の
            //   アイコン表示、 生成完了後にサムネイルへ差し替わる)。
            final thumbNodeId = nodeId;
            _generateAttachmentThumbnail(destPath, ext, attachDir.path)
                .then((thumb) {
              if (thumb != null && mounted) {
                provider.setAttachmentThumb(
                    thumbNodeId, thumb.path, thumb.aspect);
                provider.updateNodeSize(thumbNodeId, 180, 42);
              }
            });
          }
        }
      }
      // ギャラリー: このノードを指定セルから右へ連ねる (= 的確ドロップ/+ボックス)。
      if (isShelf && shelfCell != null && nodeId != null) {
        provider.setShelfCell(nodeId, shelfCell[0] + shelfK, shelfCell[1]);
        shelfK++;
      }
    }
    // 指定セルへ置いた場合は整列し直して位置を反映。
    if (isShelf && shelfCell != null) {
      provider.reflowBookshelf();
    }
    } finally {
      provider.endUndoBatch();
    }
  }

  /// 添付ファイルの 1 枚目をサムネイル画像にして保存する (= ユーザー要望:
  /// ドロップした PDF / pptx の表紙をサムネイル表示)。
  ///   - PDF: printing でラスタライズ (1 ページ目)。
  ///   - pptx / docx / xlsx: 内蔵の docProps/thumbnail.* を取り出す。
  /// 返り値はサムネイル画像のパスとアスペクト比 (= 幅/高さ)。 失敗時は null。
  Future<({String path, double aspect})?> _generateAttachmentThumbnail(
      String srcPath, String ext, String thumbDir) async {
    try {
      final lower = ext.toLowerCase();
      if (lower == 'pdf') {
        final bytes = await File(srcPath).readAsBytes();
        await for (final page
            in printing.Printing.raster(bytes, pages: [0], dpi: 96)) {
          final png = await page.toPng();
          // ★ 作り直す度に別の名前にする (= ユーザー報告: PDF に手書きしても
          //   サムネイルが変わらない)。 同じ名前だと、 画面に出ている
          //   Image.file が「同じ画像」 と見なして読み直さないため、 中身を
          //   書き換えても古い絵が出続ける (画像キャッシュを捨てても、 既に
          //   組み上がっている Image は解決済みのまま)。 古い方の絵は
          //   setAttachmentThumb 側で誰も使っていなければ消す。
          final stamp = DateTime.now().millisecondsSinceEpoch;
          final outPath =
              '$thumbDir/thumb_${srcPath.hashCode}_p1_$stamp.png';
          await File(outPath).writeAsBytes(png);
          final aspect = page.height > 0 ? page.width / page.height : 0.71;
          return (path: outPath, aspect: aspect);
        }
        return null;
      }
      if (lower == 'pptx' || lower == 'docx' || lower == 'xlsx') {
        // Office ファイル (zip) に埋め込まれた docProps/thumbnail.* を取り出す。
        final bytes = await File(srcPath).readAsBytes();
        final archive = ZipDecoder().decodeBytes(bytes);
        ArchiveFile? thumb;
        for (final f in archive.files) {
          final n = f.name.toLowerCase();
          if (n == 'docprops/thumbnail.jpeg' ||
              n == 'docprops/thumbnail.jpg' ||
              n == 'docprops/thumbnail.png') {
            thumb = f;
            break;
          }
        }
        if (thumb == null) return null;
        final content = Uint8List.fromList(thumb.content as List<int>);
        final tExt = thumb.name.split('.').last.toLowerCase();
        final outPath =
            '$thumbDir/thumb_${srcPath.hashCode}.${tExt == 'jpg' ? 'jpeg' : tExt}';
        await File(outPath).writeAsBytes(content);
        // 画像サイズからアスペクト比を求める (取れなければスライド既定 4:3)。
        double aspect = 1.3333;
        try {
          final completer = Completer<ui.Image>();
          ui.decodeImageFromList(content, completer.complete);
          final image = await completer.future;
          if (image.height > 0) aspect = image.width / image.height;
        } catch (_) {}
        return (path: outPath, aspect: aspect);
      }
    } catch (_) {}
    return null;
  }

  /// ドロップされたディレクトリパスから JSON を読み込み、新規フォルダーを作る。
  /// _importJsonFromDirectory のコア処理を path 引数で直接実行できる版。
  /// ディレクトリ選択ダイアログをスキップしてパス指定で処理を進める。
  Future<void> _importDirectoryFromPath(
      String dirPath, MindMapProvider provider) async {
    try {
      final dir = Directory(dirPath);
      if (!await dir.exists()) return;

      final jsonFiles = <File>[];
      await for (final entity
          in dir.list(recursive: false, followLinks: false)) {
        if (entity is File && entity.path.toLowerCase().endsWith('.json')) {
          jsonFiles.add(entity);
        }
      }

      // フォルダー作成 (常に linkedDirPath バインド)
      final folderName = dir.path.split(Platform.pathSeparator).last;
      final folderId =
          provider.addFolder(name: folderName, linkedDirPath: dirPath);

      if (jsonFiles.isEmpty) {
        // 空ディレクトリでもフォルダーは作成済 (linkedDirPath あり)
        if (!mounted) return;
        _appSnack(
            context,
            SnackBar(
              backgroundColor: const Color(0xFF4FC3F7),
              duration: const Duration(seconds: 4),
              content: Row(children: [
                const Icon(Icons.folder_open_rounded,
                    color: Colors.white, size: 18),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                      '${provider.t('import.emptyFolderLinked')}\n$dirPath',
                      style:
                          const TextStyle(color: Colors.white, fontSize: 12)),
                ),
              ]),
            ));
        return;
      }

      int totalPages = 0;
      String? firstPageId;
      for (final f in jsonFiles) {
        try {
          final txt = await f.readAsString();
          final res =
              provider.importFromJsonString(txt, targetFolderId: folderId);
          if (res['success'] == true) {
            totalPages += (res['addedPages'] as int? ?? 0);
            firstPageId ??= res['firstPageId'] as String?;
          }
        } catch (_) {}
      }

      if (!mounted) return;
      // 0 件読み込み成功ならフォルダー削除
      if (totalPages == 0) {
        provider.deleteFolder(folderId, deletePages: false);
        _appSnack(
            context,
            SnackBar(
              backgroundColor: const Color(0xFFFF6B6B),
              content: Text(provider.t('import.allFailed'),
                  style: const TextStyle(color: Colors.white)),
            ));
        return;
      }

      // 最初のページに切り替え
      if (firstPageId != null) {
        final idx = provider.pages.indexWhere((p) => p.id == firstPageId);
        if (idx >= 0) provider.switchPage(idx);
      }

      _appSnack(
          context,
          SnackBar(
            backgroundColor: const Color(0xFF43B97F),
            duration: const Duration(seconds: 3),
            content: Text(
              provider
                  .t('import.dirSuccess')
                  .replaceAll('{n}', '$totalPages')
                  .replaceAll('{name}', folderName),
              style: const TextStyle(color: Colors.white),
            ),
          ));
    } catch (e) {
      if (!mounted) return;
      _appSnack(
          context,
          SnackBar(
            backgroundColor: const Color(0xFFFF6B6B),
            content: Text('${provider.t('export.fail')}: $e',
                style: const TextStyle(color: Colors.white)),
          ));
    }
  }

  // ─── クリップボード画像の貼り付け (Android / モバイル) ───────────────────
  //
  // ユーザー要望「Android版でマップを長押ししたらクリップボードに保存した
  //   画像を出せる機能」 への対応。
  // マップの空エリアを長押しした位置 [canvasPos] に、 クリップボードの画像を
  //   画像ノードとして貼り付ける。 画像は attachments/ に保存して
  //   attachmentPath に設定する (= 既存のファイル添付と同じ仕組み)。

  /// クリップボードに画像があれば [canvasPos] に画像ノードを作成する。
  /// 無音カメラを開いて撮影し、 撮れた写真を現在のマップに画像ノードとして
  /// 追加する (= ユーザー要望)。 camera プラグインの takePicture は OS の
  /// シャッター音を鳴らさない (= 実質無音)。
  Future<void> _openSilentCamera() async {
    final provider = context.read<MindMapProvider>();
    if (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) {
      var status = await Permission.camera.status;
      if (!status.isGranted) {
        status = await Permission.camera.request();
      }
      if (!status.isGranted) {
        if (!mounted) return;
        _appSnack(
          context,
          SnackBar(
            content: Text(provider.t('cam.permissionDenied')),
            backgroundColor: const Color(0xFFE53935),
          ),
        );
        if (status.isPermanentlyDenied) {
          await openAppSettings();
        }
        return;
      }
    }
    final path = await Navigator.of(context).push<String>(
      MaterialPageRoute<String>(
        fullscreenDialog: true,
        builder: (_) => const _SilentCameraPage(),
      ),
    );
    if (path == null || !mounted) return;
    // ── ビデオを撮った時 (= ユーザー要望: 無音カメラでビデオも撮れるように) ──
    //    写真とは扱いが違うので、 動画ノードとして置く。
    final lowerPath = path.toLowerCase();
    if (lowerPath.endsWith('.mp4') ||
        lowerPath.endsWith('.mov') ||
        lowerPath.endsWith('.m4v') ||
        lowerPath.endsWith('.webm')) {
      await _addRecordedVideoNode(provider, path);
      return;
    }
    try {
      final appDir = await getApplicationDocumentsDirectory();
      final attachDir = Directory('${appDir.path}/attachments');
      if (!await attachDir.exists()) await attachDir.create(recursive: true);
      final name = 'camera_${DateTime.now().millisecondsSinceEpoch}.jpg';
      final dest = '${attachDir.path}/$name';
      await File(path).copy(dest);
      try {
        await File(path).delete(); // 一時ファイルを掃除
      } catch (_) {}
      // ── 左右反転させない (= ユーザー要望: 内カメラで撮ると左右が反転して
      //    いるので、 反転し直して見たままの向きで残す) ──
      //    ★ 反転し直すのは**内カメラで撮った時だけ**。 外カメラの写真は
      //      元から反転していないので、 掛け直すと鏡像になってしまう
      //      (= ユーザー報告: ON にすると左右反転して保存される)。
      if (provider.cameraUnmirror && _SilentCameraPage.lastShotFrontCamera) {
        await _flipImageHorizontally(dest);
      }
      if (!mounted) return;
      // ── 編集画面を飛ばす設定 (= ユーザー要望: シャッターを切ったら
      //    そのまま埋め込む) ──
      if (!provider.cameraSkipEdit) {
        await showDialog<void>(
          context: context,
          barrierColor: Colors.black.withValues(alpha: 0.92),
          builder: (_) => Dialog.fullscreen(
            backgroundColor: const Color(0xFF1A1A24),
            child: _ImageEditorDialog(
              filePath: dest,
              fileName: name,
            ),
          ),
        );
        if (!mounted) return;
      }
      // 現在のビュー中心に画像ノードを配置。
      final ctrl = _ctrlFor(provider.currentPage.id);
      final s =
          View.of(context).physicalSize / View.of(context).devicePixelRatio;
      final center = _globalToCanvas(Offset(s.width / 2, s.height / 2), ctrl);
      final newNode =
          provider.addNodeAtCenterReturning(center - const Offset(100, 75));
      provider.updateNodeAttachment(newNode.id, dest, name);
      // ── ノードの形 (= ユーザー報告: テキスト欄の所が変に大きくなって
      //    見栄えが悪い) ──
      //    visualHeight は「ノードの height + 写真の高さ」 で決まる。 旧実装は
      //    height に 150 を入れていたので、 文字が無いのに 150px の帯が
      //    写真の上に残っていた。 帯はタイトル用の最小限だけにして、 写真の
      //    高さは実物の縦横比から出させる。
      provider.updateNodeSize(newNode.id, 220, 40);
      unawaited(provider.applyImageAspectRatioFor(newNode.id, dest));
      provider.selectNode(newNode.id);
      _appSnack(context, SnackBar(content: Text(provider.t('photo.added'))));
    } catch (e) {
      if (mounted) {
        _appSnack(
            context,
            SnackBar(
                content: Text(
                    provider.t('photo.failed').replaceFirst('{err}', '$e'))));
      }
    }
  }

  /// 撮ったビデオをマップに動画ノードとして置く (= ユーザー要望: 無音カメラ
  /// にビデオを撮影できる機能)。 添付置き場へ移してから貼る。
  Future<void> _addRecordedVideoNode(
      MindMapProvider provider, String tmpPath) async {
    try {
      final appDir = await getApplicationDocumentsDirectory();
      final attachDir = Directory('${appDir.path}/attachments');
      if (!await attachDir.exists()) await attachDir.create(recursive: true);
      final dot = tmpPath.lastIndexOf('.');
      final ext = dot >= 0 ? tmpPath.substring(dot) : '.mp4';
      final name = 'camera_${DateTime.now().millisecondsSinceEpoch}$ext';
      final dest = '${attachDir.path}/$name';
      await File(tmpPath).copy(dest);
      try {
        await File(tmpPath).delete();
      } catch (_) {}
      if (!mounted) return;
      final ctrl = _ctrlFor(provider.currentPage.id);
      final s =
          View.of(context).physicalSize / View.of(context).devicePixelRatio;
      final center = _globalToCanvas(Offset(s.width / 2, s.height / 2), ctrl);
      final newNode =
          provider.addNodeAtCenterReturning(center - const Offset(100, 60));
      provider.updateNodeYoutube(newNode.id, dest);
      provider.updateNodeTitle(newNode.id, provider.t('cam.videoTitle'));
      provider.selectNode(newNode.id);
      if (!mounted) return;
      _appSnack(context, SnackBar(content: Text(provider.t('cam.videoAdded'))));
    } catch (e) {
      if (!mounted) return;
      _appSnack(
          context,
          SnackBar(
              content:
                  Text(provider.t('photo.failed').replaceFirst('{err}', '$e'))));
    }
  }

  /// 写真を左右反転して同じ場所に書き戻す (= ユーザー要望: 撮影時に左右が
  /// 反転するかの設定)。 失敗したら何もしない (元の写真がそのまま残る)。
  Future<void> _flipImageHorizontally(String path) async {
    try {
      final f = File(path);
      final bytes = await f.readAsBytes();
      final decoded = img.decodeImage(bytes);
      if (decoded == null) return;
      final flipped = img.flipHorizontal(decoded);
      await f.writeAsBytes(img.encodeJpg(flipped, quality: 92), flush: true);
    } catch (e) {
      debugPrint('写真の左右反転に失敗: $e');
    }
  }

  /// 画像 OCR 検索は APIキー必須のAI実装だったため廃止。
  Future<void> _openOcrImageSearch() async {
    if (!mounted) return;
    _appSnack(
      context,
      SnackBar(content: Text(context.read<MindMapProvider>().t('ocr.removed'))),
    );
  }

  /// QR 用に画像ファイルを選択 (= 全プラットフォーム共通)。
  Future<String?> _pickImageForQr() async {
    try {
      final res = await FilePicker.platform.pickFiles(
        dialogTitle: context.read<MindMapProvider>().t('pick.qrImage'),
        type: FileType.custom,
        allowedExtensions: const ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'],
      );
      return res?.files.single.path;
    } catch (_) {
      return null;
    }
  }

  /// QR コードリーダー (= ユーザー要望: QR コードリーダー機能とボタン)。
  /// モバイルはカメラ撮影 / 画像選択、 デスクトップはファイル選択した画像を
  /// 純 Dart (zxing2) でデコードし、 結果を開く/コピー/検索できるダイアログを出す。
  Future<void> _openQrReader() async {
    final provider = context.read<MindMapProvider>();
    String? path;
    if (_isDesktop) {
      path = await _pickImageForQr();
    } else {
      // モバイル: 撮影 / 画像からを画面中央の項目として選ばせる。
      // BottomSheet だと項目自体が下端に固定されるため、中央 Dialog を使う。
      final choice = await showDialog<String>(
        context: context,
        builder: (sctx) {
          Widget choice(IconData icon, String label, String value) {
            return SizedBox(
              width: double.infinity,
              child: OutlinedButton.icon(
                onPressed: () => Navigator.pop(sctx, value),
                style: OutlinedButton.styleFrom(
                  foregroundColor: Colors.white,
                  side: const BorderSide(color: Colors.white24),
                  padding: const EdgeInsets.symmetric(vertical: 14),
                ),
                icon: Icon(icon, color: const Color(0xFF4FC3F7)),
                label: Text(label, style: const TextStyle(fontSize: 15)),
              ),
            );
          }

          return AlertDialog(
            backgroundColor: const Color(0xFF1E1E32),
            title: Row(children: [
              const Icon(Icons.qr_code_scanner_rounded,
                  color: Color(0xFF4FC3F7), size: 22),
              const SizedBox(width: 10),
              Text(provider.t('qr.title'),
                  style: const TextStyle(color: Colors.white, fontSize: 16)),
            ]),
            content: SizedBox(
              width: 320,
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                choice(Icons.photo_camera_rounded,
                    provider.t('qr.scanWithCamera'), 'camera'),
                const SizedBox(height: 10),
                choice(Icons.image_rounded, provider.t('qr.scanFromImage'),
                    'gallery'),
              ]),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(sctx),
                child: Text(provider.t('btn.cancel'),
                    style: const TextStyle(color: Colors.white54)),
              ),
            ],
          );
        },
      );
      if (choice == 'camera') {
        path = await Navigator.of(context).push<String>(
          MaterialPageRoute<String>(
            fullscreenDialog: true,
            builder: (_) => const _SilentCameraPage(),
          ),
        );
      } else if (choice == 'gallery') {
        path = await _pickImageForQr();
      }
    }
    if (path == null || !mounted) return;
    Uint8List bytes;
    try {
      bytes = await File(path).readAsBytes();
    } catch (_) {
      return;
    }
    if (!mounted) return;
    showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (_) => const Center(
          child: CircularProgressIndicator(color: Color(0xFF4FC3F7))),
    );
    String? decoded;
    try {
      decoded = await compute(decodeQrFromImageBytes, bytes);
    } catch (_) {
      decoded = null;
    }
    if (mounted) Navigator.of(context, rootNavigator: true).pop();
    if (!mounted) return;
    if (decoded == null || decoded.trim().isEmpty) {
      _appSnack(
          context,
          SnackBar(
              content: Text(provider.t('qr.notFound')),
              backgroundColor: const Color(0xFFE53935)));
      return;
    }
    _showQrResultDialog(provider, decoded.trim());
  }

  void _showQrResultDialog(MindMapProvider provider, String content) {
    final isUrl =
        content.startsWith('http://') || content.startsWith('https://');
    showDialog<void>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Row(children: [
          const Icon(Icons.qr_code_scanner_rounded,
              color: Color(0xFF4FC3F7), size: 20),
          const SizedBox(width: 8),
          Expanded(
              child: Text(provider.t('qr.title'),
                  style: const TextStyle(color: Colors.white, fontSize: 16))),
        ]),
        content: SizedBox(
          width: 380,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Align(
              alignment: Alignment.centerLeft,
              child: Text(provider.t(isUrl ? 'qr.link' : 'qr.content'),
                  style: const TextStyle(color: Colors.white54, fontSize: 12)),
            ),
            const SizedBox(height: 6),
            SelectableText(content,
                style: TextStyle(
                    color: isUrl ? const Color(0xFF4FC3F7) : Colors.white,
