        content: SizedBox(
          width: 380,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Text(context.read<MindMapProvider>().t('ic.balance'),
                style:
                    const TextStyle(color: Colors.white54, fontSize: 12)),
            const SizedBox(height: 8),
            Text('¥$formatted',
                style: const TextStyle(
