  /// 単一の JSON / 自己完結 HTML ファイルを開いてページとして読み込み
  /// (= ユーザー要望: エクスポートした .html を取り込んでマップに戻せる)。
  Future<void> _importJsonFile(
      BuildContext context, MindMapProvider provider) async {
    try {
      final result = await FilePicker.platform.pickFiles(
        dialogTitle: provider.t('pick.importFile'),
        type: FileType.custom,
        allowedExtensions: ['json', 'html', 'htm'],
        allowMultiple: true,
      );
      if (result == null || result.files.isEmpty) return;

      int totalPages = 0;
      int totalFolders = 0;
      String? firstPageId;
      final errors = <String>[];

      for (final f in result.files) {
        if (f.path == null) continue;
        try {
          final txt = await File(f.path!).readAsString();
          final res = provider.importFromJsonString(txt);
          if (res['success'] == true) {
            totalPages += (res['addedPages'] as int? ?? 0);
            totalFolders += (res['addedFolders'] as int? ?? 0);
            firstPageId ??= res['firstPageId'] as String?;
          } else {
            errors.add('${f.name}: ${res['message'] ?? '?'}');
          }
        } catch (e) {
          errors.add('${f.name}: $e');
        }
      }

      if (!context.mounted) return;
      // インポートしたページに自動で切り替え
      if (firstPageId != null) {
        final idx = provider.pages.indexWhere((p) => p.id == firstPageId);
        if (idx >= 0) {
          provider.switchPage(idx);
          WidgetsBinding.instance.addPostFrameCallback((_) => _centerOnRoot());
        }
      }
      _appSnack(
          context,
          SnackBar(
            backgroundColor: errors.isEmpty
                ? const Color(0xFF43B97F)
                : const Color(0xFFFFB347),
            content: Text(
              provider
                  .t('import.summary')
                  .replaceAll('{pages}', '$totalPages')
                  .replaceAll('{folders}', '$totalFolders'),
              style: const TextStyle(color: Colors.white),
            ),
            duration: const Duration(seconds: 4),
          ));
      if (errors.isNotEmpty) {
        debugPrint('Import errors: $errors');
      }
    } catch (e) {
      if (!context.mounted) return;
      _appSnack(
          context,
          SnackBar(
            backgroundColor: const Color(0xFFFF6B6B),
            content: Text('${provider.t('import.fail')}: $e',
                style: const TextStyle(color: Colors.white)),
          ));
    }
  }

  /// 添付を持たない素のマップファイル (.json / .html) を 1 つ取り込む。
  ///
  /// 読み込みの入口を 1 つにまとめた時に、 拡張子で振り分けるために切り出した
  /// (= ユーザー要望: 読み込む項目が 2 つあって違いが分からない)。
  Future<void> _importPlainMapFile(
      BuildContext context, MindMapProvider provider, String path) async {
    try {
      final txt = await File(path).readAsString();
      final res = provider.importFromJsonString(txt);
      if (!context.mounted) return;
      if (res['success'] == true) {
        final firstPageId = res['firstPageId'] as String?;
        if (firstPageId != null) {
          final idx = provider.pages.indexWhere((p) => p.id == firstPageId);
          if (idx >= 0) {
            provider.switchPage(idx);
            WidgetsBinding.instance.addPostFrameCallback((_) => _centerOnRoot());
          }
        }
        _appSnack(
            context,
            SnackBar(
              backgroundColor: const Color(0xFF43B97F),
              content: Text(
                provider
                    .t('import.summary')
                    .replaceAll('{pages}', '${res['addedPages'] ?? 0}')
                    .replaceAll('{folders}', '${res['addedFolders'] ?? 0}'),
                style: const TextStyle(color: Colors.white),
              ),
              duration: const Duration(seconds: 4),
            ));
      } else {
        _appSnack(
            context,
            SnackBar(
              backgroundColor: const Color(0xFFFF6B6B),
              content: Text(
                  '${provider.t('import.fail')}: ${res['message'] ?? ''}',
                  style: const TextStyle(color: Colors.white)),
            ));
      }
    } catch (e) {
      if (!context.mounted) return;
      _appSnack(
          context,
          SnackBar(
            backgroundColor: const Color(0xFFFF6B6B),
            content: Text('${provider.t('import.fail')}: $e',
                style: const TextStyle(color: Colors.white)),
          ));
    }
  }

  /// フォルダーを開いて、中の .json ファイル全部をまとめてインポート (VSCode風)
  /// インポートしたファイルは新規フォルダー(フォルダー名=ディレクトリ名)に
  /// グルーピングされる。
  Future<void> _importJsonFromDirectory(
      BuildContext context, MindMapProvider provider) async {
    try {
      final dirPath = await FilePicker.platform.getDirectoryPath(
        dialogTitle: provider.t('import.dirDialogTitle'),
      );
      if (dirPath == null) return; // キャンセル
      final dir = Directory(dirPath);
      if (!await dir.exists()) return;

      // ディレクトリ内の .json を再帰的に列挙(深さ 1 まで)
      final jsonFiles = <File>[];
      await for (final entity
          in dir.list(recursive: false, followLinks: false)) {
        if (entity is File && entity.path.toLowerCase().endsWith('.json')) {
          jsonFiles.add(entity);
        }
      }

      // ── 空フォルダー対応 ──
      // JSON が無くてもフォルダーを作成して開く。新規ページ作成時、
      // フォルダーの linkedDirPath にバインドされていれば自動的に
      // そのディレクトリへ書き出される。
      // ディレクトリ名から新規フォルダー作成 (常に linkedDirPath を設定)
      final folderName = dir.path.split(Platform.pathSeparator).last;
      final folderId =
          provider.addFolder(name: folderName, linkedDirPath: dirPath);

      if (jsonFiles.isEmpty) {
        // 空のフォルダーを作っただけで終了。
        // 「新規ページを追加するとこのフォルダーに保存されます」と案内。
        if (!context.mounted) return;
        _appSnack(
            context,
            SnackBar(
              backgroundColor: const Color(0xFF4FC3F7),
              duration: const Duration(seconds: 4),
              content: Row(children: [
                const Icon(Icons.folder_open_rounded,
                    color: Colors.white, size: 18),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                      '${provider.t('import.emptyFolderLinked')}\n$dirPath',
                      style:
                          const TextStyle(color: Colors.white, fontSize: 12)),
                ),
              ]),
            ));
        return;
      }

      int totalPages = 0;
      String? firstPageId;
      final errors = <String>[];

      for (final f in jsonFiles) {
        try {
          final txt = await f.readAsString();
          final res =
              provider.importFromJsonString(txt, targetFolderId: folderId);
          if (res['success'] == true) {
            totalPages += (res['addedPages'] as int? ?? 0);
            firstPageId ??= res['firstPageId'] as String?;
          } else {
            errors.add('${f.uri.pathSegments.last}: ${res['message'] ?? '?'}');
          }
        } catch (e) {
          errors.add('${f.uri.pathSegments.last}: $e');
        }
      }

      if (!context.mounted) return;
      // インポート成功 0 件ならフォルダーを掃除 (空フォルダーは残さない)
      if (totalPages == 0) {
        provider.deleteFolder(folderId, deletePages: false);
        _appSnack(
            context,
            SnackBar(
              backgroundColor: const Color(0xFFFF6B6B),
              content: Text(provider.t('import.allFailed'),
                  style: const TextStyle(color: Colors.white)),
            ));
        return;
      }
      // 最初のページに切り替え
      if (firstPageId != null) {
        final idx = provider.pages.indexWhere((p) => p.id == firstPageId);
        if (idx >= 0) {
          provider.switchPage(idx);
          WidgetsBinding.instance.addPostFrameCallback((_) => _centerOnRoot());
        }
      }
      _appSnack(
          context,
          SnackBar(
            backgroundColor: errors.isEmpty
                ? const Color(0xFF43B97F)
                : const Color(0xFFFFB347),
            content: Text(
              provider
                  .t('import.dirSummary')
                  .replaceAll('{pages}', '$totalPages')
                  .replaceAll('{folder}', folderName),
              style: const TextStyle(color: Colors.white),
            ),
            duration: const Duration(seconds: 5),
          ));
      if (errors.isNotEmpty) {
        debugPrint('Folder import errors: $errors');
      }
    } catch (e) {
      if (!context.mounted) return;
      _appSnack(
          context,
          SnackBar(
            backgroundColor: const Color(0xFFFF6B6B),
            content: Text('${provider.t('import.fail')}: $e',
                style: const TextStyle(color: Colors.white)),
          ));
    }
  }

  /// ファイル名として安全な文字列に変換
  String _sanitizeFileName(String name) {
    final cleaned = name
        .replaceAll(RegExp(r'[\\/:*?"<>|]'), '_')
        .replaceAll(RegExp(r'\s+'), '_')
        .trim();
    return cleaned.isEmpty ? 'untitled' : cleaned;
  }

  /// 新規ページが連動フォルダーを継承すべきならそのフォルダー id を返す。
  String? _targetFolderForNewPage(MindMapProvider provider) {
    if (provider.currentPageIndex >= 0 &&
        provider.currentPageIndex < provider.pages.length) {
      final cur = provider.pages[provider.currentPageIndex];
      if (cur.folderId != null) {
        final matches =
            provider.folders.where((f) => f.id == cur.folderId).toList();
        if (matches.isNotEmpty && matches.first.linkedDirPath != null) {
          return cur.folderId;
        }
      }
    }
    return null;
  }

  /// アップロード前に、 ページ名が未設定 (空 or 既定の自動生成名) なら名前を
  /// 求める (= ユーザー要望: 作成時は聞かず、 Ctrl+S で上げる時に名前が無ければ
  /// 求める)。 既に名前があればそのまま [onNamed] を実行する。
  void _ensurePageNamed(
      BuildContext ctx, MindMapProvider provider, VoidCallback onNamed) {
    if (!provider.isDefaultPageName(provider.currentPage.name)) {
      onNamed();
      return;
    }
    final ctrl = TextEditingController();
    final idx = provider.currentPageIndex;
    void submit(BuildContext dctx) {
      final nm = ctrl.text.trim();
      Navigator.pop(dctx);
      if (nm.isNotEmpty && idx >= 0 && idx < provider.pages.length) {
        provider.renamePage(idx, nm);
      }
      onNamed();
    }

    showDialog(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('upload.nameTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          decoration: InputDecoration(
            hintText: provider.t('page.nameHint'),
            hintStyle: const TextStyle(color: Colors.white38),
            enabledBorder: const UnderlineInputBorder(
                borderSide: BorderSide(color: Colors.white24)),
            focusedBorder: const UnderlineInputBorder(
                borderSide: BorderSide(color: Color(0xFF6C63FF))),
          ),
          onSubmitted: (_) => submit(dctx),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx), // アップロードを中止
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF6C63FF),
                foregroundColor: Colors.white),
            onPressed: () => submit(dctx),
            child: Text(provider.t('upload.action')),
          ),
        ],
      ),
    );
  }

  // ── 新規ページ作成: 名前は最初に聞かず既定名で即作成する (= ユーザー要望)。
  //    名前はドロワーのリネーム、 または初回アップロード時 (Ctrl+S) に求める。
  /// 新規ページ。 どの種類を作るか選んでもらう (= ユーザー要望: 新規ページを
  /// 押した時に、 作られるページの種類を選べるように)。
  ///
  /// 押した所の近くに小さな一覧を出し、 選んだ種類の作成処理へ渡す。
  void _addPageDialog(BuildContext context, MindMapProvider provider) {
    unawaited(_showNewPageTypeMenu(provider));
  }

  /// 新規ページの種類を選ぶ小さな一覧。
  Future<void> _showNewPageTypeMenu(MindMapProvider provider) async {
    final items = <({
      String labelKey,
      IconData icon,
      Color color,
      void Function() create,
    })>[
      (
        labelKey: 'drawer.newPage',
        icon: Icons.account_tree_rounded,
        color: const Color(0xFF6C63FF),
        create: () => _createNormalPage(provider),
      ),
      (
        labelKey: 'drawer.newBookshelfPage',
        icon: Icons.shelves,
        color: const Color(0xFFFF7043),
        create: () => _addBookshelfPageDialog(context, provider),
      ),
      (
        labelKey: 'drawer.newPaintPage',
        icon: Icons.brush_rounded,
        color: const Color(0xFFEC407A),
        create: () => _addPaintPageDialog(context, provider),
      ),
      (
        labelKey: 'drawer.newDocumentPage',
        icon: Icons.description_outlined,
        color: const Color(0xFF4FC3F7),
        create: () => _addDocumentPageDialog(context, provider),
      ),
      (
        labelKey: 'drawer.newMarkdownPage',
        icon: Icons.polyline_rounded,
        color: const Color(0xFF5FD3B2),
        create: () => _addMarkdownPageDialog(context, provider),
      ),
      (
        labelKey: 'drawer.newVideoEditorPage',
        icon: Icons.movie_creation_rounded,
        color: const Color(0xFFFF7043),
        create: () => _addVideoEditorPageDialog(context, provider),
      ),
    ];
    final picked = await _showNearDialogMain<int>(
      width: 300,
      height: 56.0 * items.length + 56,
      builder: (dctx) => Container(
        decoration: BoxDecoration(
          color: const Color(0xFF1E1E32),
          borderRadius: BorderRadius.circular(12),
          border: Border.all(color: Colors.white.withValues(alpha: 0.12)),
        ),
        padding: const EdgeInsets.symmetric(vertical: 8),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(14, 4, 14, 8),
              child: Text(
                provider.t('newPage.pickType'),
                style: const TextStyle(
                    color: Colors.white54,
                    fontSize: 11,
                    fontWeight: FontWeight.w700),
              ),
            ),
            for (var i = 0; i < items.length; i++)
              InkWell(
                onTap: () => Navigator.pop(dctx, i),
                child: Padding(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
                  child: Row(children: [
                    Icon(items[i].icon, color: items[i].color, size: 18),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Text(
                        provider.t(items[i].labelKey),
                        style: const TextStyle(
                            color: Colors.white, fontSize: 13),
                      ),
                    ),
                  ]),
                ),
              ),
          ],
        ),
      ),
    );
    if (picked == null || !mounted) return;
    items[picked].create();
  }

  /// 普通のマインドマップページを作る (種類選択の 1 つ目)。
  void _createNormalPage(MindMapProvider provider) {
    if (!provider.canCreatePageType('normal')) {
      _showPaywallDialog(provider);
      return;
    }
    provider.addPage(name: null, folderId: _targetFolderForNewPage(provider));
    WidgetsBinding.instance.addPostFrameCallback((_) => _centerOnRoot());
  }

  /// お絵かき (ペイント) ページ新規作成ダイアログ (= ユーザー要望)。
  /// provider.addPaintPage を呼ぶ。
  void _addPaintPageDialog(BuildContext context, MindMapProvider provider) {
    // = ユーザー要望: 名前を聞かず既定名で即作成。
    if (!provider.canCreatePageType('paint')) {
      // ノートの新規作成は Pro 以上 (= ユーザー要望)。
      _showPaywallDialog(provider,
          bodyOverride: provider.t('paywall.proRequiredNote'));
      return;
    }
    provider.addPaintPage(
        name: null, folderId: _targetFolderForNewPage(provider));
  }

