  // ── ヘッダーのマップ名インライン編集 (= ユーザー要望:「マップ名が記載されて
  //    いる所をクリックしたらそのまま名前を編集できるように」)。 以前のように
  //    改名ダイアログを開かず、 ヘッダーのページ名を直接 TextField に変える。 ──
  bool _editingMapName = false;
  TextEditingController? _mapNameEditCtrl;

  /// 編集を始めた時のページ id。
  ///
  /// ★ 確定の時に「今開いているページ」 へ書くと、 編集中にページを
  ///   切り替えた場合に**別のページが改名されてしまう**
  ///   (= ユーザー報告: 名前が確定していない状態で切り替えると、 その名前の
  ///    まま別のページに切り替わる)。 始めた時のページを覚えておく。
  String? _mapNameEditPageId;

  /// マップ名タップ → ヘッダー上でインライン編集を開始する。
  void _beginInlineMapNameEdit() {
    if (_editingMapName || _moveModeNodeId != null || _rangeSelectMode) return;
    final page = context.read<MindMapProvider>().currentPage;
    final name = page.name;
    _mapNameEditCtrl?.dispose();
    _mapNameEditCtrl = TextEditingController(text: name)
      ..selection = TextSelection(baseOffset: 0, extentOffset: name.length);
    _mapNameEditPageId = page.id;
    setState(() => _editingMapName = true);
  }

  /// インライン編集中の名前を確定する (空欄や未変更ならキャンセル扱い)。
  void _commitInlineMapNameEdit() {
    if (!_editingMapName) return;
    final provider = context.read<MindMapProvider>();
    final name = (_mapNameEditCtrl?.text ?? '').trim();
    // 編集を始めたページへ書き戻す (今開いているページではない)。
    final id = _mapNameEditPageId;
    final i = id == null
        ? provider.pages.indexOf(provider.currentPage)
        : provider.pages.indexWhere((p) => p.id == id);
    if (i >= 0 && name.isNotEmpty && name != provider.pages[i].name) {
      provider.renamePage(i, name);
    }
    _endInlineMapNameEdit();
  }

  /// インライン編集を終了して TextField を片付ける。
  void _endInlineMapNameEdit() {
    if (!_editingMapName && _mapNameEditCtrl == null) return;
    final c = _mapNameEditCtrl;
    _mapNameEditCtrl = null;
    _mapNameEditPageId = null;
    if (mounted) {
      setState(() => _editingMapName = false);
    } else {
      _editingMapName = false;
    }
    // build 中の dispose を避けて次フレームで破棄する。
    WidgetsBinding.instance.addPostFrameCallback((_) => c?.dispose());
  }

  void _renamePageDialog(
      BuildContext context, MindMapProvider provider, int index) async {
    final ctrl = TextEditingController(text: provider.pages[index].name);
    void doRename(BuildContext ctx) {
      final name = ctrl.text.trim();
      if (name.isNotEmpty) provider.renamePage(index, name);
      Navigator.pop(ctx);
    }

    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: Text(provider.t('page.renameTitle'),
            style: const TextStyle(color: Colors.white)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          decoration: const InputDecoration(
            enabledBorder: UnderlineInputBorder(
                borderSide: BorderSide(color: Colors.white24)),
            focusedBorder: UnderlineInputBorder(
                borderSide: BorderSide(color: Color(0xFF6C63FF))),
          ),
          onSubmitted: (_) => doRename(ctx),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
            onPressed: () => doRename(ctx),
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF6C63FF),
                foregroundColor: Colors.white,),
            child: Text(provider.t('page.renameBtn')),
          ),
        ],
      ),
    );
  }

