    'zoomIn',
    'zoomOut',
    'zoomReset',
  };

  /// キーボード側で専用分岐を持たず、ヘッダー/フッターと同じ実処理へ
  /// 委譲するショートカットコマンド。
  static const Set<String> _headerExecutedShortcutCommandIds = {
    'bookshelf',
    'newBookshelfPage',
    'newPaintPage',
    'newDocumentPage',
    'newMarkdownPage',
    'newVideoEditorPage',
    'gantt',
    'memberSchedule',
    'mapMemo',
    'renamePage',
    'openGmail',
    // 「ブラウザ版AI」 (= 旧 ChatGPT/Gemini/… の個別項目を統合したもの)。
    'openAi',
  };

  /// ユーザーがカスタマイズしたキー割り当て（commandId → キー文字列）
  final Map<String, String> _customKeyBindings = {};

  /// ヘッダーに置ける全ボタンのうち、 まだショートカット定義が無いものを
  /// 「既定キー無し」 の定義として足した一覧
  /// (= ユーザー要望: 新規で割り当てなくてよいので、 全てのボタンに
  ///  ショートカットキーを割り当てられるようにはしておいて)。
  List<Map<String, dynamic>>? _assignableDefsCache;

  List<Map<String, dynamic>> get _assignableCommandDefs {
    final cached = _assignableDefsCache;
    if (cached != null) return cached;
    final out = <Map<String, dynamic>>[..._commandDefs];
    final known = <String>{
      for (final c in _commandDefs) c['id']! as String,
      // 同じ機能を別 id で既に持っているもの (_getCommandShortcut の対応表)。
      'calendar', 'themeMode', 'shortcuts',
    };
    for (final c in _headerCustomizableCommands) {
      final id = '${c['id'] ?? ''}';
      if (id.isEmpty || known.contains(id)) continue;
      if (_isRetiredCustomCommand(id)) continue;
      known.add(id);
      out.add(<String, dynamic>{
        'id': id,
        'labelKey': '${c['labelKey'] ?? id}',
        // 既定キーは持たない (= 割り当てたい人だけが後から決める)。
        'defaultKey': '',
      });
    }
    _assignableDefsCache = out;
    return out;
  }

  /// ショートカット表示順用のソートキー。
  /// 数値が小さいほど上に表示される。
  /// 1) Ctrl+A, B, C... Z の順（アルファベット）
  /// 2) Ctrl+Shift+A, B, C... Z の順
  /// 3) Ctrl+数字/特殊キー (Ctrl+1〜9, Ctrl++, Ctrl+-, Ctrl+0, Ctrl+Click)
  /// 4) Ctrl+Shift+特殊
  /// 5) Ctrl 単独
  /// 6) Plain: F2, F3, Delete, Esc, Space, Backspace, Enter
  /// 7) 矢印 (↑↓←→)
  int _shortcutSortKey(String keyStr) {
    final k = keyStr.toLowerCase();
    if (k.startsWith('ctrl+alt+')) {
      final rest = k.substring('ctrl+alt+'.length);
      if (rest.length == 1 && RegExp(r'[a-z]').hasMatch(rest)) {
        return 240 + rest.codeUnitAt(0);
      }
      return 260;
    }
    if (k.startsWith('ctrl+shift+')) {
      final rest = k.substring('ctrl+shift+'.length);
      if (rest.length == 1 && RegExp(r'[a-z]').hasMatch(rest)) {
        // 200 + 'a' = 297 → Ctrl+Shift+A = 297, Ctrl+Shift+Z = 322
        return 200 + rest.codeUnitAt(0);
      }
      return 299; // Ctrl+Shift+特殊
    }
    if (k.startsWith('ctrl+')) {
      final rest = k.substring('ctrl+'.length);
      if (rest.length == 1 && RegExp(r'[a-z]').hasMatch(rest)) {
        // 100 + 'a' = 197 → Ctrl+A = 197, Ctrl+Z = 222
        return 100 + rest.codeUnitAt(0);
      }
      return 199; // Ctrl+数字/特殊
    }
    if (k == 'ctrl') return 90;
    if (k.contains('↑') ||
        k.contains('→') ||
        k.contains('←') ||
        k.contains('↓')) {
      return 500; // 矢印キー
    }
    return 400; // Plain (F2, F3, Delete, Esc, Space, Backspace, Enter)
  }

  /// `_commandDefs` をソートしたコピーを返す。
  /// fixedSuffix=true は末尾グループ、false は先頭グループとし、
  /// それぞれの中でキー順に並べる。
  List<Map<String, dynamic>> _sortedCommandDefsForDisplay() {
    final modifiable = <Map<String, dynamic>>[];
    final fixed = <Map<String, dynamic>>[];
    for (final c in _assignableCommandDefs) {
      if (c['fixedSuffix'] == true) {
        fixed.add(c);
      } else {
        modifiable.add(c);
      }
    }
    int compare(Map<String, dynamic> a, Map<String, dynamic> b) {
      final aKey = _customKeyBindings[a['id']] ?? a['defaultKey']! as String;
      final bKey = _customKeyBindings[b['id']] ?? b['defaultKey']! as String;
      // キーが無いボタンは一覧のいちばん下へ (= 割り当てたい人が探す所)。
      final aSort = aKey.trim().isEmpty ? 9000 : _shortcutSortKey(aKey);
      final bSort = bKey.trim().isEmpty ? 9000 : _shortcutSortKey(bKey);
      if (aSort != bSort) return aSort.compareTo(bSort);
      // 同じカテゴリ内は文字列比較で安定化
      return aKey.toLowerCase().compareTo(bKey.toLowerCase());
    }

    modifiable.sort(compare);
    fixed.sort(compare);
    return [...modifiable, ...fixed];
  }

  /// 重要キーセクションで表示するショートカット定義。
  /// グローバルに捕捉する固定キーも含め、一覧本体と実際の入力処理を揃える。
  static const List<Map<String, String?>> _importantKeysOrder = [
    {'id': 'editTitle'}, // F2
    // 履歴を戻る / 進む (Alt+←/→) は重要キーから外した (= ユーザー要望)。
    //   機能もキーも今までどおりで、 一覧の下の方には出る。
    // 右画面分割 / 右分割を全画面表示 も既定キーを外したので下ろした。
    {'id': 'containerize'}, // Ctrl+G
    {'id': 'customizeHeader'}, // Ctrl+H
    {'id': 'cloudUpload'}, // Ctrl+S
    {'id': 'openYoutube'}, // Ctrl+U
    {
      'id': null,
      'labelKey': 'impKeys.shiftDragRangeSelect',
      'keyKey': 'shortcuts.shiftDragKey'
    },
    {'id': 'addChildren'}, // Ctrl+Shift+A
    {'id': 'group'}, // Ctrl+Shift+G
    {'id': 'newNode'}, // Ctrl+Shift+N
    {'id': 'syncDialog'}, // Ctrl+Shift+S
    // ── ページを作る系 (= ユーザー要望: 新規マークダウンページの作成などを
    //    重要キーとして載せて欲しい) ──
    {'id': 'newPage'}, // Ctrl+Shift+P (マインドマップ)
    {'id': 'newMarkdownPage'}, // Ctrl+Shift+M
    {'id': 'newBookshelfPage'}, // Ctrl+Shift+O
    {'id': 'newPaintPage'}, // Ctrl+Shift+X
    {'id': 'newVideoEditorPage'}, // Ctrl+Shift+K
    // 旧 redoAlternate (Ctrl+Shift+Z) は廃止 (= ユーザー要望)。
  ];

  /// 重要キーリストの各行を build する。
  List<Widget> _buildImportantKeyRows(MindMapProvider provider) {
    final rows = <Widget>[];
    for (final entry in _importantKeysOrder) {
      final id = entry['id'];
      String label;
      String key;
      if (id != null) {
        Map<String, dynamic>? cmd;
        for (final c in _commandDefs) {
          if (c['id'] == id) {
            cmd = c;
            break;
          }
        }
        if (cmd == null) continue;
        label = provider.t(cmd['labelKey']! as String);
        final baseKey = cmd['defaultKey']! as String;
        final fixedSuffix = cmd['fixedSuffix'] == true;
        final defaultKey = fixedSuffix
            ? '$baseKey${provider.t('shortcuts.fixedSuffix')}'
            : baseKey;
        key = _customKeyBindings[id] ?? defaultKey;
      } else {
        // 特殊エントリ: labelKey が指定されていれば翻訳経由で取得、
        // なければ label をそのまま使う (後方互換)。
        final lk = entry['labelKey'];
        if (lk != null && lk.isNotEmpty) {
          label = provider.t(lk);
        } else {
          label = entry['label'] ?? '';
        }
        // キー表示も同様に keyKey が指定されていれば翻訳経由で取得。
        // (= 「Shift+ドラッグ」 / 「Shift+Drag」 等の多言語表示)
        final kk = entry['keyKey'];
        if (kk != null && kk.isNotEmpty) {
          key = provider.t(kk);
        } else {
          key = entry['key'] ?? '';
        }
      }
      // ── モバイル: 画面分割は上下分割なので左右ラベルを上下に置換 (ユーザー要望) ──
      // さらに、 タップで実際に上分割 / 下分割できるボタンにする。
      final bool mobileSplitBtn = !_isDesktop &&
          (id == 'toggleSplitScreen' || id == 'toggleSplitLeftScreen');
      final bool isTopSplit = id == 'toggleSplitLeftScreen'; // 左→上
      final splitButtonColor =
          isTopSplit ? const Color(0xFFFF6B6B) : const Color(0xFF2196F3);
      if (!_isDesktop) {
        if (id == 'toggleSplitScreen') {
          label = provider.t('ve.splitDown');
        } else if (id == 'toggleSplitLeftScreen') {
          label = provider.t('ve.splitUp');
        }
      }
      final Widget rowInner = Row(
        children: [
          if (mobileSplitBtn) ...[
            _splitPanelIcon(
              isTopSplit ? _SplitIconFill.top : _SplitIconFill.bottom,
              color: splitButtonColor,
              size: 16,
            ),
            const SizedBox(width: 8),
          ],
          Expanded(
            child: Text(
              label,
              style: TextStyle(
                  color: mobileSplitBtn ? splitButtonColor : Colors.white,
                  fontSize: 12,
                  fontWeight:
                      mobileSplitBtn ? FontWeight.w700 : FontWeight.w500),
              overflow: TextOverflow.ellipsis,
              maxLines: 1,
            ),
          ),
          // ── ショートカットキー表示 (Windows のキーなのでモバイルでは隠す) ──
          if (_isDesktop) ...[
            const SizedBox(width: 12),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
              decoration: BoxDecoration(
                color: const Color(0xFFFFC107).withValues(alpha: 0.18),
                borderRadius: BorderRadius.circular(4),
                border: Border.all(
                  color: const Color(0xFFFFC107).withValues(alpha: 0.4),
                  width: 0.5,
                ),
              ),
              child: Text(
                key,
                style: const TextStyle(
                  color: Color(0xFFFFE082),
                  fontSize: 11,
                  fontWeight: FontWeight.bold,
                  fontFamily: 'monospace',
                  letterSpacing: 0.3,
                ),
              ),
            ),
          ],
        ],
      );
      rows.add(Padding(
        padding: const EdgeInsets.symmetric(vertical: 3),
        child: mobileSplitBtn
            ? InkWell(
                onTap: () => _mobileOpenSplitAt(isTopSplit),
                borderRadius: BorderRadius.circular(8),
                child: Padding(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 4, vertical: 2),
                  child: rowInner,
                ),
              )
            : rowInner,
      ));
    }
    return rows;
  }

  /// ショートカット一覧を「板」 として出す (浮遊窓 / 分割ペイン共通)。
  /// ダイアログと同じ中身に、 題と閉じるボタンを付けただけ。
  Widget _buildShortcutsPanel(MindMapProvider provider,
      {VoidCallback? onClose}) {
    return StatefulBuilder(builder: (bctx, setSt) {
      final scrollCtrl = ScrollController();
      return Container(
        color: const Color(0xFF1E1E32),
        child: Column(children: [
          Container(
            height: 38,
            padding: const EdgeInsets.only(left: 12, right: 4),
            color: const Color(0xFF23233A),
            child: Row(children: [
              const Icon(Icons.keyboard_rounded,
                  color: Color(0xFF4FC3F7), size: 16),
              const SizedBox(width: 8),
              Expanded(
                child: Text(provider.t('shortcuts.title'),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 13,
                        fontWeight: FontWeight.w700)),
              ),
              if (_customKeyBindings.isNotEmpty)
                TextButton(
                  onPressed: () {
                    setState(() => _customKeyBindings.clear());
                    _persistCustomKeyBindings();
                    setSt(() {});
                  },
                  child: Text(provider.t('shortcuts.resetAll'),
                      style: const TextStyle(
                          color: Colors.redAccent, fontSize: 11)),
                ),
              if (onClose != null)
                IconButton(
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints(minWidth: 30, minHeight: 30),
                  tooltip: provider.t('btn.close'),
                  icon: const Icon(Icons.close_rounded,
                      color: Colors.white54, size: 18),
                  onPressed: onClose,
                ),
            ]),
          ),
          Expanded(
            child: LayoutBuilder(builder: (lctx, cons) {
              return Padding(
                padding: const EdgeInsets.fromLTRB(12, 8, 6, 8),
                child: _buildShortcutsBody(
                  provider,
                  scrollCtrl,
                  () => setSt(() {}),
                  maxHeight: cons.maxHeight - 16,
                ),
              );
            }),
          ),
        ]),
      );
    });
  }

  /// ショートカット一覧の中身 (= ユーザー要望: 一覧もフローティングや
  /// 画面分割で開けるように)。 ダイアログ / 浮遊窓 / 分割ペインで同じ物を出す。
  Widget _buildShortcutsBody(
    MindMapProvider provider,
    ScrollController scrollCtrl,
    VoidCallback refresh, {
    required double maxHeight,
  }) {
    final sortedCmds = _sortedCommandDefsForDisplay();
    return ConstrainedBox(
                constraints: BoxConstraints(maxHeight: maxHeight),
                child: RawScrollbar(
                  controller: scrollCtrl,
                  thumbColor: Colors.white.withValues(alpha: 0.55),
                  thickness: 8,
                  radius: const Radius.circular(4),
                  thumbVisibility: true,
                  // スクロールバーの左右にパディングを設けて内容と被らないように
                  padding: const EdgeInsets.only(right: 2, top: 4, bottom: 4),
                  child: SingleChildScrollView(
                    controller: scrollCtrl,
                    padding: const EdgeInsets.only(right: 12),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        // ── ガイドサイトへのハイパーリンク ──
                        Padding(
                          padding: const EdgeInsets.only(bottom: 12),
                          child: InkWell(
                            borderRadius: BorderRadius.circular(4),
                            onTap: () {
                              launchUrl(
                                Uri.parse('https://kamispec.com/features.html'),
                                mode: LaunchMode.externalApplication,
                              );
                            },
                            child: Padding(
                              padding: const EdgeInsets.symmetric(
                                  horizontal: 4, vertical: 4),
                              child: Row(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  const Icon(Icons.open_in_new_rounded,
                                      color: Color(0xFF4FC3F7), size: 14),
                                  const SizedBox(width: 6),
                                  Text(
                                    provider.t('shortcuts.referenceLinkText'),
                                    style: TextStyle(
                                      color: const Color(0xFF4FC3F7),
                                      decoration: TextDecoration.underline,
                                      decorationColor: const Color(0xFF4FC3F7)
                                          .withValues(alpha: 0.6),
                                      fontSize: 12.5,
                                      fontWeight: FontWeight.w600,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ),
                        ),
                        // ── 重要キーセクション (黄色枠で強調) ──
                        Container(
                          margin: const EdgeInsets.only(bottom: 16),
                          padding: const EdgeInsets.fromLTRB(12, 10, 12, 10),
                          decoration: BoxDecoration(
                            color:
                                const Color(0xFFFFC107).withValues(alpha: 0.07),
                            border: Border.all(
                              color: const Color(0xFFFFC107)
                                  .withValues(alpha: 0.35),
                              width: 1,
                            ),
                            borderRadius: BorderRadius.circular(8),
                          ),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(children: [
                                const Icon(Icons.star_rounded,
                                    color: Color(0xFFFFC107), size: 16),
                                const SizedBox(width: 6),
                                Text(
                                  provider.t('shortcuts.importantSection'),
                                  style: const TextStyle(
                                    color: Color(0xFFFFC107),
                                    fontSize: 13,
                                    fontWeight: FontWeight.bold,
                                  ),
                                ),
                              ]),
                              const SizedBox(height: 8),
                              ..._buildImportantKeyRows(provider),
                            ],
                          ),
                        ),
                        // ヘッダー行
                        Padding(
                          padding: const EdgeInsets.only(bottom: 8),
                          child: Row(children: [
                            // チェックボックス列のスペース (= 各行の有効/無効
                            // トグルが入る位置)。 中央寄せの小さい説明アイコン。
                            SizedBox(
                              width: 28,
                              child: Tooltip(
                                message: provider.t('shortcuts.toggleEnabled'),
                                child: const Icon(Icons.check_box_outlined,
                                    color: Colors.white24, size: 14),
                              ),
                            ),
                            Expanded(
                                flex: 3,
                                child: Text(
                                    provider.t('shortcuts.column.command'),
                                    style: const TextStyle(
                                        color: Colors.white38,
                                        fontSize: 11,
                                        fontWeight: FontWeight.w600))),
                            if (_isDesktop) ...[
                              Expanded(
                                  flex: 2,
                                  child: Text(
                                      provider.t('shortcuts.column.key'),
                                      style: const TextStyle(
                                          color: Colors.white38,
                                          fontSize: 11,
                                          fontWeight: FontWeight.w600))),
                              const SizedBox(width: 32),
                            ],
                          ]),
                        ),
                        const Divider(color: Colors.white10),
                        ...sortedCmds.map((cmd) {
                          final id = cmd['id']! as String;
                          final labelKey = cmd['labelKey']! as String;
                          String label = provider.t(labelKey);
                          // モバイル: 画面分割は上下分割表記 (ユーザー要望)
                          if (!_isDesktop) {
                            if (id == 'toggleSplitScreen') {
                              label = provider.t('ve.splitDown');
                            } else if (id == 'toggleSplitLeftScreen') {
                              label = provider.t('ve.splitUp');
                            }
                          }
                          final baseKey = cmd['defaultKey']! as String;
                          final fixedSuffix = cmd['fixedSuffix'] == true;
                          final defaultKey = fixedSuffix
                              ? '$baseKey${provider.t('shortcuts.fixedSuffix')}'
                              : baseKey;
                          final currentKey =
                              _customKeyBindings[id] ?? defaultKey;
                          final isFixed = _fixedCommands.contains(id);
                          final isCustom = _customKeyBindings.containsKey(id);
                          // ── 無効化状態 ──
                          // _disabledShortcuts に含まれているとキー入力には反応
                          // しない。 固定キーは常に有効 (= 無効化不可)。
                          final isDisabled = _disabledShortcuts.contains(id);

                          return Padding(
                            padding: const EdgeInsets.symmetric(vertical: 3),
                            child: Row(children: [
                              // ── 有効/無効 トグル ──
                              // チェック = 有効 (キー入力でコマンドが発火)。
                              // チェック外し = 無効 (キー入力では発火しない)。
                              // 固定コマンドは常に有効、 ここではスペースだけ
                              // 取ってチェックボックスは描画しない。
                              SizedBox(
                                width: 28,
                                child: isFixed
                                    ? const SizedBox.shrink()
                                    : Transform.scale(
                                        scale: 0.85,
                                        child: Checkbox(
                                          value: !isDisabled,
                                          materialTapTargetSize:
                                              MaterialTapTargetSize.shrinkWrap,
                                          visualDensity: VisualDensity.compact,
                                          activeColor: const Color(0xFF4FC3F7),
                                          checkColor: Colors.white,
                                          side: const BorderSide(
                                              color: Colors.white38,
                                              width: 1.4),
                                          onChanged: (v) {
                                            setState(() {
                                              if (v == true) {
                                                _disabledShortcuts.remove(id);
                                              } else {
                                                _disabledShortcuts.add(id);
                                              }
                                            });
                                            _persistDisabledShortcuts();
                                            refresh();
                                          },
                                        ),
                                      ),
                              ),
                              Expanded(
                                flex: 3,
                                child: Text(label,
                                    style: TextStyle(
                                        color: isFixed
                                            ? Colors.white38
                                            : isDisabled
                                                ? Colors.white24
                                                : Colors.white70,
                                        fontSize: 12,
                                        decoration: isDisabled
                                            ? TextDecoration.lineThrough
                                            : null,
                                        decorationColor: Colors.white38)),
                              ),
                              // ── キー列 + 編集ボタン (Windows キーなのでモバイルでは隠す) ──
                              if (_isDesktop) ...[
                                Expanded(
                                  flex: 2,
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(
                                        horizontal: 8, vertical: 4),
                                    decoration: BoxDecoration(
                                      color: isDisabled
                                          ? Colors.white.withValues(alpha: 0.03)
                                          : isCustom
                                              ? const Color(0xFF6C63FF)
                                                  .withValues(alpha: 0.22)
                                              : Colors.white
                                                  .withValues(alpha: 0.07),
                                      borderRadius: BorderRadius.circular(6),
                                      border: Border.all(
                                        color: isDisabled
                                            ? Colors.white12
                                            : isCustom
                                                ? const Color(0xFF6C63FF)
                                                    .withValues(alpha: 0.5)
                                                : Colors.white12,
                                      ),
                                    ),
                                    child: Text(
                                        currentKey.isEmpty
                                            ? provider.t('shortcuts.unassigned')
                                            : currentKey,
                                        style: TextStyle(
                                            color: isFixed
                                                ? Colors.white24
                                                : isDisabled
                                                    ? Colors.white24
                                                    : isCustom
                                                        ? const Color(
                                                            0xFF4FC3F7)
                                                        : Colors.white70,
                                            fontSize: 11,
                                            fontWeight: FontWeight.w600,
                                            fontFamily: 'monospace',
                                            decoration: isDisabled
                                                ? TextDecoration.lineThrough
                                                : null,
                                            decorationColor: Colors.white38)),
                                  ),
                                ),
                                const SizedBox(width: 4),
                                // 編集/リセットボタン
                                SizedBox(
                                  width: 28,
                                  child: isFixed
                                      ? const SizedBox.shrink()
                                      : isCustom
                                          ? IconButton(
                                              padding: EdgeInsets.zero,
                                              iconSize: 16,
                                              icon: const Icon(
                                                  Icons.restart_alt_rounded,
                                                  color: Colors.redAccent),
                                              tooltip: provider
                                                  .t('shortcuts.resetTooltip'),
                                              onPressed: () {
                                                setState(() =>
                                                    _customKeyBindings
                                                        .remove(id));
                                                _persistCustomKeyBindings();
                                                refresh();
                                              },
                                            )
                                          : IconButton(
                                              padding: EdgeInsets.zero,
                                              iconSize: 16,
                                              icon: const Icon(
                                                  Icons.edit_rounded,
                                                  color: Colors.white30),
                                              tooltip: provider
                                                  .t('shortcuts.editTooltip'),
                                              onPressed: () {
                                                _showKeyBindingEditor(
                                                    context,
                                                    id,
                                                    label,
                                                    baseKey,
                                                    currentKey, (newKey) {
                                                  setState(() {
                                                    if (newKey.isEmpty ||
                                                        newKey == baseKey) {
                                                      _customKeyBindings
                                                          .remove(id);
                                                    } else {
                                                      _customKeyBindings[id] =
                                                          newKey;
                                                    }
                                                  });
                                                  _persistCustomKeyBindings();
                                                  refresh();
                                                });
                                              },
                                            ),
                                ),
                              ],
                            ]),
                          );
                        }),
                      ],
                    ),
                  ),
                ),
              );
  }

  /// ショートカット一覧を、 設定した開き方 (全画面 / フローティング /
  /// 分割ペイン) で開く (= ユーザー要望)。
  Future<void> _openShortcutsList(BuildContext ctx) async {
    if (!_isDesktop) {
      _showShortcutsDialog(ctx);
      return;
    }
    final provider = context.read<MindMapProvider>();
    // 開き方の設定は起動直後まだ読み込めていない事があるので待つ
    // (= 待たないと、 押すのが早いと既定の「全画面」 になってしまう)。
    try {
      await _commandOpenStylesReady;
    } catch (_) {}
    if (!mounted) return;
    final style = _openStyleOf('shortcuts');
    if (style == 'splitRight' || style == 'splitLeft') {
      // ★ まだ分割していなければ、 ここで分割してから入れる
      //   (= ユーザー報告: 右分割を選んでいるのに画面の真ん中に出る)。
      //   以前は「分割中なら」 という条件だったので、 分割していない時は
      //   黙って真ん中のダイアログに落ちていた。
      if (!_mapSplitOpen) {
        await _applyMapSplitMode(panes: 2, stacked: false);
        if (!mounted) return;
      }
      if (!_mapSplitOpen) {
        _showShortcutsDialog(ctx);
        return;
      }
      // 閉じた時に元の全画面へ戻す扱いも含めて、 共通の入口に任せる
      // (= ユーザー要望)。
      await _openToolInSplitPane('shortcuts', style == 'splitLeft');
      return;
    }
    if (style == 'floating') {
      _showFloatingPanelWindow(
        (_) => _buildShortcutsPanel(provider),
        width: 520,
        height: 640,
        memoryKey: 'shortcuts',
        // 押すたびに窓が増えないようにする (= ユーザー要望)。
        singletonKey: 'shortcuts',
      );
      return;
    }
    _showShortcutsDialog(ctx);
  }

  void _showShortcutsDialog(BuildContext ctx) {
    if (!_isDesktop) return;
    final provider = context.read<MindMapProvider>();
    // ダイアログ寿命に合わせて 1 つのScrollControllerを使う
    final scrollCtrl = ScrollController();
    // 上下キー / Page Up/Down / Home/End でスクロールするための Focus
    final keyFocus = FocusNode();
    showDialog(
      context: ctx,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setSt) {
        final hasCustom = _customKeyBindings.isNotEmpty;
        return Focus(
          focusNode: keyFocus,
          autofocus: true,
          // ── 上下キー / PgUp/PgDn / Home/End でスクロール ──
          // ユーザー要望「上下キーでショートカット一覧をスクロールできない」
          // 対応。 RawScrollbar 内の SingleChildScrollView をキー入力で操作。
          onKeyEvent: (node, event) {
            if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
              return KeyEventResult.ignored;
            }
            final k = event.logicalKey;
            if (!scrollCtrl.hasClients) return KeyEventResult.ignored;
            const lineStep = 56.0;
            const pageStep = 280.0;
            double newOffset = scrollCtrl.offset;
            if (k == LogicalKeyboardKey.arrowDown) {
              newOffset += lineStep;
            } else if (k == LogicalKeyboardKey.arrowUp) {
              newOffset -= lineStep;
            } else if (k == LogicalKeyboardKey.pageDown) {
              newOffset += pageStep;
            } else if (k == LogicalKeyboardKey.pageUp) {
              newOffset -= pageStep;
            } else if (k == LogicalKeyboardKey.home) {
              newOffset = 0;
            } else if (k == LogicalKeyboardKey.end) {
              newOffset = scrollCtrl.position.maxScrollExtent;
            } else {
              return KeyEventResult.ignored;
            }
            newOffset =
                newOffset.clamp(0.0, scrollCtrl.position.maxScrollExtent);
            scrollCtrl.animateTo(
              newOffset,
              duration: const Duration(milliseconds: 120),
              curve: Curves.easeOut,
            );
            return KeyEventResult.handled;
          },
          child: AlertDialog(
            backgroundColor: const Color(0xFF1E1E32),
            shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(18),
                side: const BorderSide(color: Color(0xFF4FC3F7), width: 1)),
            title: Row(children: [
              const Icon(Icons.info_outline_rounded,
                  color: Color(0xFF4FC3F7), size: 22),
              const SizedBox(width: 10),
              Expanded(
                child: Text(provider.t('shortcuts.title'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 16,
                        fontWeight: FontWeight.bold)),
              ),
              if (hasCustom)
                TextButton(
                  onPressed: () {
                    setState(() => _customKeyBindings.clear());
                    _persistCustomKeyBindings();
                    setSt(() {});
                  },
                  child: Text(provider.t('shortcuts.resetAll'),
                      style: const TextStyle(
                          color: Colors.redAccent, fontSize: 11)),
                ),
            ]),
            content: SizedBox(
              width: 460,
              child: _buildShortcutsBody(
                provider,
                scrollCtrl,
                () => setSt(() {}),
                maxHeight: MediaQuery.of(ctx).size.height * 0.78,
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dctx),
                child: Text(provider.t('btn.close'),
                    style: const TextStyle(color: Colors.white54)),
              ),
            ],
          ),
        );
      }),
    ).whenComplete(() {
      keyFocus.dispose();
    });
  }

  /// キー割り当て編集ダイアログ
  void _showKeyBindingEditor(
      BuildContext ctx,
      String commandId,
      String commandLabel,
      String defaultKey,
      String currentKey,
      ValueChanged<String> onSave) {
    final ctrl = TextEditingController(text: currentKey);
    // 物理キー入力をそのまま捕まえるためのフォーカス (= ユーザー要望: 文字で
    //   打つのではなく、 押したキーが欄に入る)。
    final captureFocus = FocusNode(debugLabel: 'keyBindingCapture');
    final provider = context.read<MindMapProvider>();
    showDialog(
      context: ctx,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setEd) {
        String? conflictMsg;

        /// 入力キーが他コマンドと重複していないかチェック
        /// 重複していればコマンド名（翻訳済み）を返す
        String? _checkConflict(String inputKey) {
          if (inputKey.isEmpty) return null;
          final normalized = _normalizeShortcutCombo(inputKey);
          if (_nonAssignableShortcutCombos.contains(normalized)) {
            return provider.t('shortcuts.fixedKeyLabel');
          }
          for (final cmd in _commandDefs) {
            final otherId = cmd['id']! as String;
            if (otherId == commandId) continue; // 自分自身はスキップ
            final otherKey = _normalizeShortcutCombo(
                (_customKeyBindings[otherId] ?? (cmd['defaultKey']! as String))
                    .trim());
            if (otherKey == normalized) {
              return provider.t(cmd['labelKey']! as String);
            }
          }
          return null;
        }

        void tryToSave() {
          final inputKey = ctrl.text.trim();
          if (inputKey.isEmpty) {
            onSave('');
            Navigator.pop(dctx);
            return;
          }
          final conflict = _checkConflict(inputKey);
          if (conflict != null) {
            setEd(() => conflictMsg = conflict);
            return;
          }
          onSave(inputKey);
          Navigator.pop(dctx);
        }

        return AlertDialog(
          backgroundColor: const Color(0xFF2A2A3E),
          title: Row(children: [
            const Icon(Icons.keyboard_alt_rounded,
                color: Color(0xFF4FC3F7), size: 18),
            const SizedBox(width: 8),
            Expanded(
              child: Text(commandLabel,
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 14,
                      fontWeight: FontWeight.bold)),
            ),
          ]),
          content: Column(mainAxisSize: MainAxisSize.min, children: [
            Text(provider.t('keyEdit.prompt'),
                style: const TextStyle(color: Colors.white54, fontSize: 12)),
            const SizedBox(height: 12),
            // ── キー捕捉フィールド (= ユーザー要望: ctrl 等を文字で打つのでは
            //    なく、 押したキーがそのまま欄に入る) ──
            //   物理キー押下を KeyboardListener で受け、 既存の
            //   `_getPressedKeyCombo` で「Ctrl+Shift+X」 形式に直して ctrl.text に
            //   入れる (= 保存/重複チェックは従来どおり ctrl.text を使う)。
            //   修飾キー単体 (Ctrl/Shift のみ) はキー本体が来るまで確定しない。
            KeyboardListener(
              focusNode: captureFocus,
              autofocus: true,
              onKeyEvent: (event) {
                if (event is! KeyDownEvent) return;
                final combo = _getPressedKeyCombo(event);
                if (combo.isEmpty) return; // 修飾キー単体は無視
                setEd(() {
                  ctrl.text = combo;
                  conflictMsg = null;
                });
              },
              child: GestureDetector(
                onTap: () => captureFocus.requestFocus(),
                child: Container(
                  width: double.infinity,
                  padding:
                      const EdgeInsets.symmetric(horizontal: 12, vertical: 16),
                  decoration: BoxDecoration(
                    color: conflictMsg != null
                        ? Colors.redAccent.withValues(alpha: 0.10)
                        : Colors.white.withValues(alpha: 0.07),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(
                      color: conflictMsg != null
                          ? Colors.redAccent.withValues(alpha: 0.7)
                          : (captureFocus.hasFocus
                              ? const Color(0xFF4FC3F7)
                              : const Color(0xFF4FC3F7).withValues(alpha: 0.4)),
                      width: 1.5,
                    ),
                  ),
                  alignment: Alignment.center,
                  child: Text(
                    ctrl.text.isEmpty
                        ? provider.t('keyEdit.pressKeys')
                        : ctrl.text,
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      color: ctrl.text.isEmpty ? Colors.white38 : Colors.white,
                      fontSize: 16,
                      fontWeight: FontWeight.w700,
                      letterSpacing: 1,
                    ),
                  ),
                ),
              ),
            ),
            // 重複エラーメッセージ
            AnimatedSwitcher(
              duration: const Duration(milliseconds: 180),
              child: conflictMsg != null
                  ? Padding(
                      key: const ValueKey('conflict'),
                      padding: const EdgeInsets.only(top: 8),
                      child: Row(children: [
                        const Icon(Icons.error_outline_rounded,
                            color: Colors.redAccent, size: 14),
                        const SizedBox(width: 6),
                        Expanded(
                          child: Text(
                            provider
                                .t('keyEdit.conflict')
                                .replaceAll('{name}', conflictMsg ?? ''),
                            style: const TextStyle(
                                color: Colors.redAccent, fontSize: 11),
                          ),
                        ),
                      ]),
                    )
                  : const SizedBox(key: ValueKey('empty'), height: 4),
            ),
            const SizedBox(height: 4),
            Text(
                provider
                    .t('keyEdit.defaultLabel')
                    .replaceAll('{key}', defaultKey),
                style: const TextStyle(color: Colors.white24, fontSize: 10)),
          ]),
          actions: [
            TextButton(
              onPressed: () {
                onSave('');
                Navigator.pop(dctx);
              },
              child: Text(provider.t('keyEdit.resetToDefault'),
                  style: const TextStyle(color: Colors.white38, fontSize: 12)),
            ),
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              onPressed: tryToSave,
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6C63FF),
                  foregroundColor: Colors.white,),
              child: Text(provider.t('btn.save')),
            ),
          ],
        );
      }),
    ).whenComplete(() {
      ctrl.dispose();
      captureFocus.dispose();
    });
  }
}

// ─── インラインタイトル編集ダイアログ ─────────────────────────────────────────

/// PDF パネル下に表示される水平スクロールバー widget。
/// SfPdfViewer の zoomLevel > 1.0 の時 (= PDF が拡大されてはみ出している)
/// 時のみ active になり、 ドラッグで横スクロール (= scrollOffset.dx) を更新。
///
/// ユーザー要望: 「画面を拡大した際、 表示領域内を左右に動かせるバーを PDF の
/// 下に付けて欲しい」。
class _SplitPdfHorizontalScrollBar extends StatefulWidget {
  final sf_pdf.PdfViewerController controller;

  /// パネルの可視幅 (= 横スクロール最大値の推定に使う)
  final double panelWidth;

  /// アクセントカラー (= Slider のつまみとアクティブトラックの色)
  final Color accent;
  const _SplitPdfHorizontalScrollBar({
    required this.controller,
    required this.panelWidth,
    required this.accent,
  });
  @override
  State<_SplitPdfHorizontalScrollBar> createState() =>
      _SplitPdfHorizontalScrollBarState();
}

class _SplitPdfHorizontalScrollBarState
    extends State<_SplitPdfHorizontalScrollBar> {
  /// 現在の横スクロール位置 (0.0〜1.0 の正規化)
  double _normalizedX = 0.0;

  /// 現在の zoomLevel (= 表示判定に使う)
  double _zoomLevel = 1.0;

  /// コントローラの状態を周期的にポーリング (= syncfusion は ChangeNotifier
  /// 風の API が不完全なので、 タイマで状態を取得する)
  Timer? _pollTimer;

  @override
  void initState() {
    super.initState();
    // 250ms 毎にコントローラの状態を取り直す。 ユーザー操作中のみ
    // pollingしてもいいが、 ライト実装で常時にする。
    _pollTimer = Timer.periodic(const Duration(milliseconds: 250), (_) {
      if (!mounted) return;
      _refreshState();
    });
  }

  @override
  void dispose() {
    _pollTimer?.cancel();
    super.dispose();
  }

  void _refreshState() {
    try {
      final z = widget.controller.zoomLevel;
      final offset = widget.controller.scrollOffset;
      // panelWidth * (zoomLevel - 1.0) ≒ はみ出した分の幅
      final maxX = widget.panelWidth * (z - 1.0).clamp(0.0, 10.0);
      final normalized = maxX > 0 ? (offset.dx / maxX).clamp(0.0, 1.0) : 0.0;
      if (z != _zoomLevel || (normalized - _normalizedX).abs() > 0.005) {
        setState(() {
          _zoomLevel = z;
          _normalizedX = normalized.toDouble();
        });
      }
    } catch (_) {}
  }

  @override
  Widget build(BuildContext context) {
    // zoom 1.0 以下 (= はみ出してない) ときはバー自体を表示しない
    if (_zoomLevel <= 1.01) {
      return const SizedBox.shrink();
    }
    final maxX = widget.panelWidth * (_zoomLevel - 1.0);
    return Container(
      height: 28,
      color: const Color(0xFF1A1A30),
      padding: const EdgeInsets.symmetric(horizontal: 8),
      child: Row(children: [
        Icon(Icons.swap_horiz_rounded, color: widget.accent, size: 16),
        const SizedBox(width: 6),
        Expanded(
          child: SliderTheme(
            data: SliderTheme.of(context).copyWith(
              trackHeight: 3,
              thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 6),
              overlayShape: const RoundSliderOverlayShape(overlayRadius: 12),
              activeTrackColor: widget.accent,
              inactiveTrackColor: Colors.white24,
              thumbColor: widget.accent,
              overlayColor: widget.accent.withValues(alpha: 0.3),
            ),
            child: Slider(
              value: _normalizedX.clamp(0.0, 1.0),
              min: 0.0,
              max: 1.0,
              onChanged: (v) {
                setState(() => _normalizedX = v);
                try {
                  final cur = widget.controller.scrollOffset;
                  widget.controller.jumpTo(
                    xOffset: v * maxX,
                    yOffset: cur.dy,
                  );
                } catch (_) {}
              },
            ),
          ),
        ),
        // 現在位置 / 拡大率の表示
        Text(
          '${(_zoomLevel * 100).toStringAsFixed(0)}%',
          style: TextStyle(
            color: widget.accent,
            fontSize: 10,
            fontWeight: FontWeight.w700,
            fontFeatures: const [FontFeature.tabularFigures()],
          ),
        ),
      ]),
    );
  }
}

class _InlineTitleDialog extends StatefulWidget {
  final MindMapNode node;
  final TextEditingController titleController;
  final TextEditingController memoController;
  final void Function(String title, String memo) onSave;

  /// ダイアログ表示のアンカー (= ノード下端の画面座標)。
  /// ダイアログはこの位置を起点にノードの真下に表示される。
  /// 画面の端で見切れないように clamp 処理。
  final Offset anchorScreenPos;

  /// URL ペースト時に呼ばれる: type = 'embed' (= 埋め込み動画) / 'link' (= ハイパーリンク)。
  /// ユーザー要望: 「ノードを編集のところに URL を貼り付けたら埋め込み動画や
  /// ハイパーリンクにするかの確認が出るようにして」 への対応。
  final void Function(String url, String type)? onUrlPasted;

  /// 「複数ノードに分割」 が押された時に呼ばれる (= ユーザー要望: ノード内に
  /// 区切り文字で複数の値を書いて一気に分割)。 引数は指定された区切り文字。
  final void Function(String delimiter)? onSplit;
  const _InlineTitleDialog({
    required this.node,
    required this.titleController,
    required this.memoController,
    required this.onSave,
    required this.anchorScreenPos,
    this.onUrlPasted,
    this.onSplit,
  });
  @override
  State<_InlineTitleDialog> createState() => _InlineTitleDialogState();
}

class _InlineTitleDialogState extends State<_InlineTitleDialog> {
  final FocusNode _escFocus = FocusNode();
  final FocusNode _titleFocus = FocusNode();

  // ── URL ペースト検出用 ──
  // ユーザー要望: 「ノードを編集のところに URL を貼り付けたら埋め込み動画や
  // ハイパーリンクにするかの確認が出るようにして」。
  // 直前のテキスト長を覚えておき、 急激な変化 (= ペースト) で URL が現れた
  // タイミングで 1 度だけダイアログを表示する。
  String _prevTitleText = '';
  String _prevMemoText = '';
  bool _urlDialogShown = false;

  /// 「複数ノードに分割」 モード (= ユーザー要望: ボタンは都度押すのではなく
  /// クリックの度に ON/OFF がトグル)。 ON のまま保存すると、 現在の区切り文字
  /// (provider.nodeSplitDelimiter) でテキストを分割して複数ノードを作る。
  /// 右クリックで区切り文字の設定ダイアログを開く。
  bool _splitOnSave = false;

  @override
  void initState() {
    super.initState();
    _prevTitleText = widget.titleController.text;
    _prevMemoText = widget.memoController.text;
    // Focus ウィジェットより先に、タイトル TextField に確実にフォーカスを渡す
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _titleFocus.requestFocus();
    });
  }

  /// キーボード (Gboard 等) から画像がコミットされた時の処理。
  ///
  /// ユーザー要望: 「モバイル版、直近のクリップボードに確かに画像が入って
  ///   いるのに、このアプリは、ここでの画像貼り付けをサポートしませんと出て
  ///   貼り付けることができない」 への対応。
  /// Android の IME はテキスト入力欄へ画像を挿入する際に richContent
  /// (commitContent) を使うが、 Flutter の TextField は
  /// contentInsertionConfiguration を指定しないと受け取れず、 OS 側が
  /// 「このアプリは画像の挿入をサポートしていません」 と表示してしまう。
  /// ここで受け取った画像は編集中ノードの添付画像として保存する。
  Future<void> _handleInsertedImage(KeyboardInsertedContent content) async {
    final bytes = content.data;
    if (bytes == null || bytes.isEmpty || !mounted) return;
    final provider = context.read<MindMapProvider>();
    try {
      final mime = content.mimeType.toLowerCase();
      var ext = 'png';
      if (mime.contains('jpeg') || mime.contains('jpg')) {
        ext = 'jpg';
      } else if (mime.contains('gif')) {
        ext = 'gif';
      } else if (mime.contains('webp')) {
        ext = 'webp';
      } else if (mime.contains('bmp')) {
        ext = 'bmp';
      }
      final appDir = await getApplicationDocumentsDirectory();
      final attachDir = Directory('${appDir.path}/attachments');
      if (!await attachDir.exists()) {
        await attachDir.create(recursive: true);
      }
      final name = 'kbimg_${DateTime.now().millisecondsSinceEpoch}.$ext';
      final destPath = '${attachDir.path}/$name';
      await File(destPath).writeAsBytes(bytes, flush: true);
      // 元画像の縦横比を記録 (NodeWidget の描画計算が使う)。
      try {
        final completer = Completer<ui.Image>();
        ui.decodeImageFromList(bytes, completer.complete);
        final im = await completer.future.timeout(const Duration(seconds: 3));
        if (im.height > 0) {
          provider.updateNodeAttachmentAspectRatio(
              widget.node.id, im.width / im.height);
        }
        im.dispose();
      } catch (_) {}
      provider.updateNodeAttachment(widget.node.id, destPath, name);
      if (mounted) {
        _appSnack(context, SnackBar(
          content: Text(provider.t('clip.imagePasted')),
          backgroundColor: const Color(0xFF43B97F),
          duration: const Duration(seconds: 2),
        ));
      }
    } catch (e) {
      debugPrint('キーボード画像挿入の保存に失敗: $e');
    }
  }

  /// テキストが急激に変化して URL を含むようになった時に呼ぶ。
  /// 1 度だけ「埋め込み / ハイパーリンク / そのまま」 の 3 択ダイアログを表示。
  void _handleTextChange(String newText, bool isTitle) {
    if (_urlDialogShown) {
      if (isTitle) {
        _prevTitleText = newText;
      } else {
        _prevMemoText = newText;
      }
      return;
    }
    final prev = isTitle ? _prevTitleText : _prevMemoText;
    final delta = newText.length - prev.length;
    // URL を含むか判定
    final urlMatch = RegExp(r'https?://[^\s]+').firstMatch(newText);
    if (urlMatch == null) {
      if (isTitle) {
        _prevTitleText = newText;
      } else {
        _prevMemoText = newText;
      }
      return;
    }
    // 急激な変化 (= 10 文字以上一気に追加) なら「ペースト」 と判定
    final isPaste = delta >= 10;
    if (!isPaste) {
      if (isTitle) {
        _prevTitleText = newText;
      } else {
        _prevMemoText = newText;
      }
      return;
    }
    // ペーストと判定 → ダイアログ表示
    _urlDialogShown = true;
    if (isTitle) {
      _prevTitleText = newText;
    } else {
      _prevMemoText = newText;
    }
    final url = urlMatch.group(0)!;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _showUrlPasteDialog(url, isTitle: isTitle);
    });
  }

  /// URL ペースト時の 3 択ダイアログ。
  Future<void> _showUrlPasteDialog(String url, {required bool isTitle}) async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final isYoutube = url.contains('youtube.com/') || url.contains('youtu.be/');
    final choice = await showDialog<String>(
      context: context,
      barrierColor: Colors.black.withValues(alpha: 0.5),
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E2E),
        title: Text(provider.t('urlPaste.pasted'),
            style: const TextStyle(color: Colors.white)),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(provider.t('urlPaste.howToHandle'),
                style: const TextStyle(color: Colors.white70)),
            const SizedBox(height: 8),
            Container(
              padding: const EdgeInsets.all(8),
              decoration: BoxDecoration(
                color: Colors.white.withValues(alpha: 0.05),
                borderRadius: BorderRadius.circular(6),
              ),
              child: Text(
                url.length > 80 ? '${url.substring(0, 80)}...' : url,
                style: const TextStyle(
                    color: Colors.white60,
                    fontSize: 11,
                    fontFamily: 'monospace'),
              ),
            ),
          ],
        ),
        actions: [
          if (isYoutube)
            TextButton.icon(
              icon: const Icon(Icons.smart_display_rounded,
                  color: Color(0xFFFF6B6B)),
              label: Text(provider.t('urlPaste.embedVideo'),
                  style: const TextStyle(color: Color(0xFFFF6B6B))),
              onPressed: () => Navigator.of(ctx).pop('embed'),
            ),
          TextButton.icon(
            icon: const Icon(Icons.link_rounded, color: Color(0xFF6C63FF)),
            label: Text(provider.t('urlPaste.hyperlink'),
                style: const TextStyle(color: Color(0xFF6C63FF))),
            onPressed: () => Navigator.of(ctx).pop('link'),
          ),
          TextButton(
            child: Text(provider.t('urlPaste.asIs'),
                style: const TextStyle(color: Colors.white54)),
            onPressed: () => Navigator.of(ctx).pop('plain'),
          ),
        ],
      ),
    );
    if (choice == null || choice == 'plain') return;
    if (choice == 'embed') {
      // 埋め込み動画 → URL をタイトル/メモから取り除く + onUrlPasted コール
      // バックで上位 widget に通知 → 親が `_embedYoutubeUrlAsNode` 等を呼ぶ。
      _removeUrlFromControllers(url);
      widget.onUrlPasted?.call(url, 'embed');
      if (mounted) {
        // ダイアログを閉じる (= 編集セッション終了、 タイトル/メモは保存される)
        widget.onSave(
          widget.titleController.text.trim(),
          widget.memoController.text.trim(),
        );
        Navigator.of(context).pop();
      }
    } else if (choice == 'link') {
      // ハイパーリンク → URL を linkUrl として保存。
      // タイトル/メモから URL を取り除き、 onUrlPasted で親に linkUrl を渡す
      // → 親が provider.updateNodeLink を呼ぶ。
      _removeUrlFromControllers(url);
      widget.onUrlPasted?.call(url, 'link');
      // ダイアログは閉じずに編集続行 (= タイトル/メモの調整可能)
    }
  }

  /// 確定した URL をタイトル / メモから取り除く
  void _removeUrlFromControllers(String url) {
    final t = widget.titleController.text;
    if (t.contains(url)) {
      widget.titleController.text = t.replaceAll(url, '').trim();
    }
    final m = widget.memoController.text;
    if (m.contains(url)) {
      widget.memoController.text = m.replaceAll(url, '').trim();
    }
    setState(() {});
  }

  @override
  void dispose() {
    _escFocus.dispose();
    _titleFocus.dispose();
    super.dispose();
  }

  void _submit() {
    widget.onSave(
      widget.titleController.text.trim(),
      widget.memoController.text.trim(),
    );
    // 分割モードが ON なら、 保存後に区切り文字で複数ノードへ分割する。
    if (_splitOnSave) {
      final delim = context.read<MindMapProvider>().nodeSplitDelimiter;
      widget.onSplit?.call(delim);
    }
    Navigator.of(context).pop();
  }

  /// 分割の区切り文字の設定ダイアログ (= ユーザー要望: 分割ボタンを右クリック
  /// すると設定が出る)。 区切り文字を選んで「設定」 すると provider に保存され、
  /// 分割モードが ON になる。 実際の分割は保存時 (_submit) に行われる。
  Future<void> _showSplitSettings() async {
    final provider = context.read<MindMapProvider>();
    final presets = <({String label, String value})>[
      (label: provider.t('voice.newline'), value: '\n'),
      (label: '、', value: '、'),
      (label: provider.t('voice.comma'), value: ','),
      (label: provider.t('voice.space'), value: ' '),
      (label: provider.t('voice.slash'), value: '/'),
    ];
    String sel = provider.nodeSplitDelimiter;
    final customCtrl = TextEditingController(
      text: presets.any((p) => p.value == sel) ? '' : (sel == '\n' ? '' : sel),
    );
    final chosen = await showDialog<String>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        final bool hasCustom = customCtrl.text.isNotEmpty;
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E2E),
          title: Text(provider.t('voice.delimiterTitle'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
          content: SizedBox(
            width: 300,
            child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(provider.t('voice.delimiterBody'),
                      style:
                          const TextStyle(color: Colors.white54, fontSize: 12)),
                  const SizedBox(height: 12),
                  Wrap(spacing: 8, runSpacing: 8, children: [
                    for (final p in presets)
                      ChoiceChip(
                        label: Text(p.label),
                        selected: !hasCustom && sel == p.value,
                        showCheckmark: false,
                        backgroundColor: const Color(0xFF2A2A3E),
                        selectedColor: const Color(0xFF6C63FF),
                        labelStyle: TextStyle(
                            color: (!hasCustom && sel == p.value)
                                ? Colors.white
                                : Colors.white60,
                            fontSize: 12),
                        onSelected: (_) => setD(() {
                          sel = p.value;
                          customCtrl.clear();
                        }),
                      ),
                  ]),
                  const SizedBox(height: 12),
                  TextField(
                    controller: customCtrl,
                    style: const TextStyle(color: Colors.white, fontSize: 13),
                    decoration: InputDecoration(
                      isDense: true,
                      hintText: provider.t('voice.otherHint'),
                      hintStyle:
                          const TextStyle(color: Colors.white24, fontSize: 12),
                      filled: true,
                      fillColor: Colors.white.withValues(alpha: 0.06),
                      border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(8),
                          borderSide: BorderSide.none),
                    ),
                    onChanged: (_) => setD(() {}),
                  ),
                ]),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6C63FF),
                  foregroundColor: Colors.white,),
              onPressed: () {
                final custom = customCtrl.text;
                Navigator.of(dctx).pop(custom.isNotEmpty ? custom : sel);
              },
              child: Text(provider.t('btn.settings')),
            ),
          ],
        );
      }),
    );
    customCtrl.dispose();
    if (chosen == null || chosen.isEmpty) return;
    // 区切り文字を保存し、 分割モードを ON にする (= 保存時に分割される)。
    await provider.setNodeSplitDelimiter(chosen);
    if (mounted) setState(() => _splitOnSave = true);
  }

  /// Enter単独 → 保存、Shift+Enter → 改行挿入 (デスクトップのみ)
  ///
  /// モバイル (Android/iOS) ではソフトキーボードの Enter キーは常に改行
  /// として扱う。Shift を押す手段が無く、キーボードを隠さないと保存ボタンが
  /// タップできない従来の挙動だと、「メモの中で改行が入れられない」と
  /// いう問題が出ていた。
  /// ignored を返すと TextField 側のデフォルト挙動 (multiline なので改行挿入)
  /// が動作する。保存は「保存」ボタンのタップで行う。
  KeyEventResult _handleEnterKey(
      KeyEvent event, TextEditingController controller) {
    if (event is! KeyDownEvent && event is! KeyRepeatEvent)
      return KeyEventResult.ignored;
    if (event.logicalKey != LogicalKeyboardKey.enter &&
        event.logicalKey != LogicalKeyboardKey.numpadEnter) {
      return KeyEventResult.ignored;
    }
    // モバイルでは Enter = 改行、保存は保存ボタンのみ。
    // kIsWeb は除外 (Web はデスクトップ扱い)
    final bool isMobile = !kIsWeb &&
        (defaultTargetPlatform == TargetPlatform.android ||
            defaultTargetPlatform == TargetPlatform.iOS);
    if (isMobile) {
      return KeyEventResult.ignored;
    }
    final isShift = HardwareKeyboard.instance.isShiftPressed;
    if (!isShift) {
      // Enter単独: 保存
      _submit();
      return KeyEventResult.handled;
    }
    // Shift+Enter: カーソル位置に改行を挿入
    final sel = controller.selection;
    final text = controller.text;
    final start = sel.start >= 0 ? sel.start : text.length;
    final end = sel.end >= 0 ? sel.end : text.length;
    final newText = text.replaceRange(start, end, '\n');
    controller.value = TextEditingValue(
      text: newText,
      selection: TextSelection.collapsed(offset: start + 1),
    );
    return KeyEventResult.handled;
  }

  @override
  Widget build(BuildContext context) {
    return Focus(
      autofocus: true,
      focusNode: _escFocus,
      onKeyEvent: (node, event) {
        if (event is KeyDownEvent &&
            event.logicalKey == LogicalKeyboardKey.escape) {
          // Escでも保存して閉じる（途中まで変更したものを破棄しない）
          _submit();
          return KeyEventResult.handled;
        }
        return KeyEventResult.ignored;
      },
      child: GestureDetector(
        onTap: _submit,
        child: Scaffold(
          backgroundColor: Colors.black.withValues(alpha: 0.5),
          body: LayoutBuilder(builder: (lctx, constraints) {
            // ── ノードの真下にダイアログを配置 ──
            // 画面端で見切れないように clamp する。
            const dialogWidth = 280.0;
            const estimatedDialogHeight = 220.0; // 概算
            final screenW = constraints.maxWidth;
            final screenH = constraints.maxHeight;
            // ── モバイルキーボード対応 ──
            // ソフトキーボードが出ると画面下部が viewInsets.bottom 分隠れる。
            // ダイアログがキーボードに重なって保存ボタンが押せなくなる問題への
            // 対策として、 「使える縦範囲」 を keyboard 上端までに制限する。
            final keyboardHeight = MediaQuery.of(lctx).viewInsets.bottom;
            // キーボード上端: ダイアログがこの線より下に行かないように
            final usableH = screenH - keyboardHeight;
            // ダイアログの左上座標を計算 (アンカーは中央 X / ノード下端 Y)
            var dx = widget.anchorScreenPos.dx - dialogWidth / 2;
            var dy = widget.anchorScreenPos.dy + 8; // ノード下に 8px の隙間
            // 画面下端 (or キーボード上端) を超えたらノードの上側に表示
            if (dy + estimatedDialogHeight > usableH - 8) {
              dy = widget.anchorScreenPos.dy -
                  estimatedDialogHeight -
                  widget.node.height -
                  8;
              // それでも上端から外れる場合は usable 範囲の中央寄りに置く
              if (dy < 8) {
                dy = ((usableH - estimatedDialogHeight) / 2)
                    .clamp(8.0, double.infinity);
              }
            }
            // 画面端で見切れないように clamp (= 縦は usableH を使う)
            dx = dx.clamp(
                8.0, (screenW - dialogWidth - 8.0).clamp(8.0, double.infinity));
            dy = dy.clamp(
                8.0,
                (usableH - estimatedDialogHeight - 8.0)
                    .clamp(8.0, double.infinity));
            return Stack(
              children: [
                Positioned(
                  left: dx,
                  top: dy,
                  child: GestureDetector(
                    onTap: () {}, // ダイアログ内タップで閉じない
                    child: Container(
                      width: 280,
                      padding: const EdgeInsets.symmetric(
                          horizontal: 16, vertical: 14),
                      decoration: BoxDecoration(
                        color: const Color(0xFF1E1E2E),
                        borderRadius: BorderRadius.circular(18),
                        border: Border.all(
                            color: widget.node.color.withValues(alpha: 0.7),
                            width: 2),
                        boxShadow: [
                          BoxShadow(
                              color: widget.node.color.withValues(alpha: 0.3),
                              blurRadius: 24,
                              spreadRadius: 2),
                          BoxShadow(
                              color: Colors.black.withValues(alpha: 0.5),
                              blurRadius: 16),
                        ],
                      ),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Row(children: [
                            Container(
                              width: 10,
                              height: 10,
                              decoration: BoxDecoration(
                                  color: widget.node.color,
                                  shape: BoxShape.circle),
                            ),
                            const SizedBox(width: 8),
                            Expanded(
                              child: Text(
                                  context
                                      .read<MindMapProvider>()
                                      .t('inlineEdit.header'),
                                  style: const TextStyle(
                                      color: Colors.white54,
                                      fontSize: 11,
                                      fontWeight: FontWeight.w500)),
                            ),
                            // ── 複数ノードに分割 (= ユーザー要望: クリックで
                            //    ON/OFF トグル、 右クリックで区切り文字の設定) ──
                            //    ON のまま保存すると区切り文字で複数ノードに分割。
                            InkWell(
                              onTap: () =>
                                  setState(() => _splitOnSave = !_splitOnSave),
                              onSecondaryTap: _showSplitSettings, // 右クリック=設定
                              onLongPress: _showSplitSettings, // モバイル長押し=設定
                              borderRadius: BorderRadius.circular(6),
                              child: Container(
                                padding: const EdgeInsets.symmetric(
                                    horizontal: 5, vertical: 2),
                                decoration: BoxDecoration(
                                  color: _splitOnSave
                                      ? const Color(0xFF6C63FF)
                                          .withValues(alpha: 0.24)
                                      : Colors.transparent,
                                  borderRadius: BorderRadius.circular(6),
                                ),
                                child: Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      Icon(Icons.call_split_rounded,
                                          color: _splitOnSave
                                              ? const Color(0xFFB3AEFF)
                                              : Colors.white38,
                                          size: 14),
                                      if (_splitOnSave) ...[
                                        const SizedBox(width: 3),
                                        Text(context.read<MindMapProvider>().t('inline.splitOn'),
                                            style: TextStyle(
                                                color: Color(0xFFB3AEFF),
                                                fontSize: 11,
                                                fontWeight: FontWeight.w700)),
                                      ],
                                    ]),
                              ),
                            ),
                          ]),
                          const SizedBox(height: 10),
                          // タイトル（Shift+Enterで改行 / Enterで保存）
                          Focus(
                            onKeyEvent: (n, event) =>
                                _handleEnterKey(event, widget.titleController),
                            child: TextField(
                              controller: widget.titleController,
                              focusNode: _titleFocus,
                              autofocus: false,
                              textAlign: TextAlign.center,
                              maxLines: null,
                              minLines: 1,
                              keyboardType: TextInputType.multiline,
                              textInputAction: TextInputAction.newline,
                              // IME からの画像挿入 (クリップボード画像の貼り
                              // 付け) を受け付ける (= ユーザー要望)。
                              contentInsertionConfiguration:
                                  ContentInsertionConfiguration(
                                onContentInserted: _handleInsertedImage,
                              ),
                              onChanged: (v) => _handleTextChange(v, true),
                              style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 16,
                                  fontWeight: FontWeight.w700),
                              decoration: InputDecoration(
                                filled: true,
                                fillColor: Colors.white.withValues(alpha: 0.06),
                                hintText: context
                                    .read<MindMapProvider>()
                                    .t('inlineEdit.titleHint'),
                                hintStyle: const TextStyle(
                                    color: Colors.white30, fontSize: 14),
                                border: OutlineInputBorder(
                                    borderRadius: BorderRadius.circular(12),
                                    borderSide: BorderSide.none),
                                contentPadding: const EdgeInsets.symmetric(
                                    horizontal: 12, vertical: 10),
                              ),
                            ),
                          ),
                          const SizedBox(height: 8),
                          // メモ（Shift+Enterで改行 / Enterで保存）
                          Focus(
                            onKeyEvent: (n, event) =>
                                _handleEnterKey(event, widget.memoController),
                            child: TextField(
                              controller: widget.memoController,
                              maxLines: 4,
                              minLines: 2,
                              keyboardType: TextInputType.multiline,
                              textInputAction: TextInputAction.newline,
                              // IME からの画像挿入も受け付ける (= ユーザー要望)。
                              contentInsertionConfiguration:
                                  ContentInsertionConfiguration(
                                onContentInserted: _handleInsertedImage,
                              ),
                              style: const TextStyle(
                                  color: Colors.white70, fontSize: 13),
                              decoration: InputDecoration(
                                filled: true,
                                fillColor: Colors.white.withValues(alpha: 0.04),
                                hintText: context
                                    .read<MindMapProvider>()
                                    .t('inlineEdit.memoHint'),
                                hintStyle: const TextStyle(
                                    color: Colors.white24, fontSize: 12),
                                border: OutlineInputBorder(
                                    borderRadius: BorderRadius.circular(12),
                                    borderSide: BorderSide.none),
                                contentPadding: const EdgeInsets.symmetric(
                                    horizontal: 12, vertical: 10),
                              ),
                            ),
                          ),
                          const SizedBox(height: 10),
                          Row(children: [
                            Expanded(
                              child: GestureDetector(
                                onTap: () => Navigator.of(context).pop(),
                                child: Container(
                                  padding:
                                      const EdgeInsets.symmetric(vertical: 9),
                                  decoration: BoxDecoration(
                                    color: Colors.white.withValues(alpha: 0.07),
                                    borderRadius: BorderRadius.circular(10),
                                  ),
                                  child: Center(
                                    child: Text(
                                        context
                                            .read<MindMapProvider>()
                                            .t('node.cancel'),
                                        style: const TextStyle(
                                            color: Colors.white54,
                                            fontSize: 13)),
                                  ),
                                ),
                              ),
                            ),
                            const SizedBox(width: 8),
                            Expanded(
                              child: GestureDetector(
                                onTap: _submit,
                                child: Container(
                                  padding:
                                      const EdgeInsets.symmetric(vertical: 9),
                                  decoration: BoxDecoration(
                                    color: widget.node.color,
                                    borderRadius: BorderRadius.circular(10),
                                  ),
                                  child: Center(
                                    child: Text(
                                        context
                                            .read<MindMapProvider>()
                                            .t('node.save'),
                                        style: const TextStyle(
                                            color: Colors.white,
                                            fontSize: 13,
                                            fontWeight: FontWeight.w700)),
                                  ),
                                ),
                              ),
                            ),
                          ]),
                        ],
                      ),
                    ),
                  ), // GestureDetector 閉じ (= ダイアログ本体)
                ), // Positioned 閉じ
              ], // Stack children 閉じ
            ); // Stack & return 閉じ
          }), // LayoutBuilder 閉じ
        ),
      ),
    );
  }
}

// ─── 接続削除オーバーレイ ──────────────────────────────────────────────────────

/// グループ編集ダイアログ内のグループ名入力欄。
/// StatefulBuilder が文字サイズスライダー等で頻繁に再ビルドされても、
/// TextEditingController の参照を確実に保持し、 入力中のテキストが
/// 消えないようにする (= ユーザー要望のバグ修正)。
class _GroupNameInputField extends StatefulWidget {
  final TextEditingController controller;
  final String labelText;
  final VoidCallback onSubmitted;
  const _GroupNameInputField({
    required this.controller,
    required this.labelText,
    required this.onSubmitted,
  });
  @override
  State<_GroupNameInputField> createState() => _GroupNameInputFieldState();
}

class _GroupNameInputFieldState extends State<_GroupNameInputField> {
  @override
  Widget build(BuildContext context) {
    return TextField(
      controller: widget.controller,
      style: const TextStyle(color: Colors.white, fontSize: 14),
      decoration: InputDecoration(
        filled: true,
        fillColor: Colors.white.withValues(alpha: 0.07),
        labelText: widget.labelText,
        labelStyle: const TextStyle(color: Colors.white38, fontSize: 12),
        border: OutlineInputBorder(
            borderRadius: BorderRadius.circular(10),
            borderSide: BorderSide.none),
        contentPadding:
            const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
      ),
      onSubmitted: (_) => widget.onSubmitted(),
    );
  }
}

class _ConnectionActionOverlay extends StatefulWidget {
  final Offset screenPos;
  final NodeConnection connection;
  final int selectedCount;
  final VoidCallback onClose;
  final VoidCallback onDelete;
  final VoidCallback onReverse;
  final ValueChanged<double> onStrokeWidthChanged;
  final ValueChanged<bool> onShowArrowChanged;
  final ValueChanged<double> onArrowHeadScaleChanged;
  final ValueChanged<String> onLineStyleChanged;
  final ValueChanged<double> onElbowSplitRatioChanged;
  final ValueChanged<int> onElbowPointCountChanged;
  final VoidCallback onClearElbowBendPoints;
  final ValueChanged<NodeConnection> onSaveDefaults;

  /// 両方向矢印トグル変更
  final ValueChanged<bool> onBidirectionalChanged;

  /// ラベル変更 (= 空文字なら削除扱い)
  final ValueChanged<String> onLabelChanged;
  final ValueChanged<double> onLabelPositionChanged;
  final ValueChanged<int?> onLineColorChanged;
  final ValueChanged<String> onRelationshipTypeChanged;
  const _ConnectionActionOverlay({
    required this.screenPos,
    required this.connection,
    this.selectedCount = 1,
    required this.onClose,
    required this.onDelete,
    required this.onReverse,
    required this.onStrokeWidthChanged,
    required this.onShowArrowChanged,
    required this.onArrowHeadScaleChanged,
    required this.onLineStyleChanged,
    required this.onElbowSplitRatioChanged,
    required this.onElbowPointCountChanged,
    required this.onClearElbowBendPoints,
    required this.onSaveDefaults,
    required this.onBidirectionalChanged,
    required this.onLabelChanged,
    required this.onLabelPositionChanged,
    required this.onLineColorChanged,
    required this.onRelationshipTypeChanged,
  });
  @override
  State<_ConnectionActionOverlay> createState() =>
      _ConnectionActionOverlayState();
}

class _ConnectionActionOverlayState extends State<_ConnectionActionOverlay>
    with SingleTickerProviderStateMixin {
  late AnimationController _anim;
  late Animation<double> _scale;
  late double _sw;
  late bool _arrow;
  late double _arrowScale;
  late String _lineStyle;
  late double _elbowSplitRatio;
  late int _elbowPointCount;
  late double _labelPosition;
  late int? _lineColorValue;
  late String _relationshipType;
  bool _collapsed = !kIsWeb && (Platform.isAndroid || Platform.isIOS);
  Offset? _panelPosition;
  Timer? _labelSaveDebounce;
  final ScrollController _lineColorScrollController = ScrollController();

  /// 色の並びにカーソルが乗っているか (= ユーザー要望: 左右のスクロール
  /// バーは、 乗っている時だけ出して常時は出さない)。
  bool _lineColorHovering = false;

  /// 両方向矢印トグル state
  late bool _bidirectional;

  /// ラベル入力 controller
  late TextEditingController _labelCtrl;

  @override
  void initState() {
    super.initState();
    _sw = widget.connection.strokeWidth;
    _arrow = widget.connection.showArrow;
    _arrowScale = widget.connection.arrowHeadScale;
    _lineStyle = widget.connection.lineStyle ?? 'curve';
    _elbowSplitRatio = widget.connection.elbowSplitRatio;
    _elbowPointCount = widget.connection.elbowPointCount;
    _labelPosition = widget.connection.labelPosition;
    _lineColorValue = widget.connection.lineColorValue;
    _relationshipType = widget.connection.relationshipType;
    _bidirectional = widget.connection.bidirectional;
    _labelCtrl = TextEditingController(text: widget.connection.label ?? '');
    _anim = AnimationController(
        vsync: this, duration: const Duration(milliseconds: 90));
    _scale = CurvedAnimation(parent: _anim, curve: Curves.easeOutCubic);
    _anim.forward();
  }

  @override
  void dispose() {
    _anim.dispose();
    _labelCtrl.dispose();
    _labelSaveDebounce?.cancel();
    _lineColorScrollController.dispose();
    super.dispose();
  }

  String _lineStyleLabel(String style) {
    final t = context.read<MindMapProvider>().t;
    switch (style) {
      case 'straight':
        return t('conn.styleStraight');
      case 'elbow':
        return t('conn.styleElbow');
      default:
        return t('conn.styleCurve');
    }
  }

  IconData _lineStyleIcon(String style) {
    switch (style) {
      case 'straight':
        return Icons.horizontal_rule_rounded;
      case 'elbow':
        return Icons.turn_right_rounded;
      default:
        return Icons.gesture_rounded;
    }
  }

  NodeConnection _snapshotConnection() => widget.connection.copyWith(
        strokeWidth: _sw,
        showArrow: _arrow,
        arrowHeadScale: _arrowScale,
        bidirectional: _bidirectional,
        lineStyle: _lineStyle,
        elbowSplitRatio: _elbowSplitRatio,
        elbowPointCount: _elbowPointCount,
        labelPosition: _labelPosition,
        lineColorValue: _lineColorValue,
        relationshipType: _relationshipType,
      );

  @override
  Widget build(BuildContext context) {
    final mq = MediaQuery.of(context);
    final double barW = math.min(380.0, math.max(0.0, mq.size.width - 24.0));
    const linkColors = <Color?>[
      null,
      Color(0xFFE53935),
      Color(0xFFFF7043),
      Color(0xFFFB8C00),
      Color(0xFFF9A825),
      Color(0xFF7CB342),
      Color(0xFF43A047),
      Color(0xFF00897B),
      Color(0xFF00ACC1),
      Color(0xFF1E88E5),
      Color(0xFF3949AB),
      Color(0xFF8E24AA),
      Color(0xFFD81B60),
      Color(0xFF6D4C41),
      Color(0xFF546E7A),
      Color(0xFF263238),
    ];
    final showLineColorScrollbar = <TargetPlatform>{
      TargetPlatform.windows,
      TargetPlatform.macOS,
      TargetPlatform.linux,
    }.contains(defaultTargetPlatform);
    double left = _panelPosition?.dx ?? widget.screenPos.dx - barW / 2;
    double top = _panelPosition?.dy ?? widget.screenPos.dy - 220;
    final topMin = mq.padding.top + 64.0;
    final estimatedHeight = _collapsed ? 64.0 : 360.0;
    final topMax = math.max(topMin, mq.size.height - estimatedHeight - 8.0);
    final leftMax = math.max(8.0, mq.size.width - barW - 8.0);
    left = left.clamp(8.0, leftMax);
    top = top.clamp(topMin, topMax);

    void movePanel(DragUpdateDetails details) {
      final next = Offset(left, top) + details.delta;
      setState(() {
        _panelPosition = Offset(
          next.dx.clamp(8.0, leftMax).toDouble(),
          next.dy.clamp(topMin, topMax).toDouble(),
        );
      });
    }

    return Stack(children: [
      Positioned.fill(
        child: GestureDetector(
          onTap: widget.onClose,
          behavior: HitTestBehavior.translucent,
          child: const SizedBox.expand(),
        ),
      ),
      Positioned(
        left: left,
        top: top,
        child: ScaleTransition(
          scale: _scale,
          alignment: Alignment.bottomCenter,
          child: Material(
            color: Colors.transparent,
            child: Container(
              width: barW,
              constraints: BoxConstraints(
                maxHeight: math.max(64.0, mq.size.height - top - 8.0),
              ),
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
              decoration: BoxDecoration(
                color: const Color(0xFF1A1A30),
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: Colors.white.withValues(alpha: 0.15)),
                boxShadow: [
                  BoxShadow(
                      color: Colors.black.withValues(alpha: 0.6),
                      blurRadius: 24,
                      offset: const Offset(0, 8))
                ],
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onPanUpdate: movePanel,
                    child: MouseRegion(
                      cursor: SystemMouseCursors.move,
                      child: Padding(
                        padding: const EdgeInsets.symmetric(vertical: 2),
                        child: Row(children: [
                          const Icon(Icons.drag_indicator_rounded,
                              color: Colors.white38, size: 17),
                          const SizedBox(width: 4),
                          Expanded(
                            child: Text(
                                widget.selectedCount > 1
                                    ? context
                                        .watch<MindMapProvider>()
                                        .t('conn.settingsMulti')
                                        .replaceAll(
                                            '{n}', '${widget.selectedCount}')
                                    : context
                                        .watch<MindMapProvider>()
                                        .t('conn.settings'),
                                style: const TextStyle(
                                    color: Colors.white70,
                                    fontSize: 11,
                                    fontWeight: FontWeight.w600)),
                          ),
                          IconButton(
                            tooltip: context.read<MindMapProvider>().t(
                                _collapsed
                                    ? 'conn.expandSettings'
                                    : 'conn.collapseSettings'),
                            visualDensity: VisualDensity.compact,
                            padding: EdgeInsets.zero,
                            constraints: const BoxConstraints(
                                minWidth: 30, minHeight: 30),
                            icon: Icon(
                              _collapsed
                                  ? Icons.expand_more_rounded
                                  : Icons.expand_less_rounded,
                              color: Colors.white54,
                              size: 20,
                            ),
                            onPressed: () =>
                                setState(() => _collapsed = !_collapsed),
                          ),
                        ]),
                      ),
                    ),
                  ),
                  if (!_collapsed)
                    Flexible(
                      child: SingleChildScrollView(
                        child: Column(children: [
                          const SizedBox(height: 10),
                          // ── 線種: 個別リンクごとに曲線 / 直線 / 直角を切り替える ──
                          Row(children: [
                            const Icon(Icons.account_tree_rounded,
                                color: Colors.white38, size: 14),
                            const SizedBox(width: 4),
                            Text(context.read<MindMapProvider>().t('conn.lineStyle'),
                                style: const TextStyle(
                                    color: Colors.white38, fontSize: 10)),
                            const Spacer(),
                            for (final style in const [
                              'curve',
                              'straight',
                              'elbow'
                            ])
                              Padding(
                                padding: const EdgeInsets.only(left: 4),
                                child: GestureDetector(
                                  onTap: () {
                                    setState(() => _lineStyle = style);
                                    widget.onLineStyleChanged(style);
                                  },
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(
                                        horizontal: 7, vertical: 5),
                                    decoration: BoxDecoration(
                                      color: _lineStyle == style
                                          ? const Color(0xFF4FC3F7)
                                              .withValues(alpha: 0.22)
                                          : Colors.white
                                              .withValues(alpha: 0.05),
                                      borderRadius: BorderRadius.circular(8),
                                      border: Border.all(
                                        color: _lineStyle == style
                                            ? const Color(0xFF4FC3F7)
                                            : Colors.white
                                                .withValues(alpha: 0.10),
                                      ),
                                    ),
                                    child: Row(
                                        mainAxisSize: MainAxisSize.min,
                                        children: [
                                          Icon(_lineStyleIcon(style),
                                              color: _lineStyle == style
                                                  ? const Color(0xFF4FC3F7)
                                                  : Colors.white54,
                                              size: 14),
                                          const SizedBox(width: 3),
                                          Text(_lineStyleLabel(style),
                                              style: TextStyle(
                                                  color: _lineStyle == style
                                                      ? const Color(0xFFB3E5FC)
                                                      : Colors.white54,
                                                  fontSize: 10,
                                                  fontWeight: FontWeight.w700)),
                                        ]),
                                  ),
                                ),
                              ),
                          ]),
                          const SizedBox(height: 8),
                          Row(children: [
                            const Icon(Icons.palette_outlined,
                                color: Colors.white38, size: 14),
                            const SizedBox(width: 4),
                            Text(context.read<MindMapProvider>().t('conn.linkColor'),
                                style: const TextStyle(
                                    color: Colors.white38, fontSize: 10)),
                            const SizedBox(width: 8),
                            Expanded(
                              // カーソルが乗っている間だけスクロールバーを
                              // 出す (= ユーザー要望: 常時表示にはしない)。
                              child: MouseRegion(
                                onEnter: (_) =>
                                    setState(() => _lineColorHovering = true),
                                onExit: (_) =>
                                    setState(() => _lineColorHovering = false),
                                child: SizedBox(
                                height: 40,
                                child: Scrollbar(
                                  controller: _lineColorScrollController,
                                  thumbVisibility: _lineColorHovering,
                                  trackVisibility:
                                      _lineColorHovering && showLineColorScrollbar,
                                  interactive: showLineColorScrollbar,
                                  scrollbarOrientation:
                                      ScrollbarOrientation.bottom,
                                  thickness: 5,
                                  radius: const Radius.circular(4),
                                  child: ListView.separated(
                                    controller: _lineColorScrollController,
                                    scrollDirection: Axis.horizontal,
                                    padding: const EdgeInsets.only(bottom: 9),
                                    itemCount: linkColors.length,
                                    separatorBuilder: (_, __) =>
                                        const SizedBox(width: 7),
                                    itemBuilder: (_, index) {
                                      final color = linkColors[index];
                                      final value = color?.toARGB32();
                                      final selected = _lineColorValue == value;
                                      return GestureDetector(
                                        behavior: HitTestBehavior.opaque,
                                        onTap: () {
                                          setState(
                                              () => _lineColorValue = value);
                                          widget.onLineColorChanged(value);
                                        },
                                        child: Container(
                                          width: 26,
                                          height: 26,
                                          margin: const EdgeInsets.symmetric(
                                              vertical: 2),
                                          decoration: BoxDecoration(
                                            shape: BoxShape.circle,
                                            color: color ?? Colors.transparent,
                                            border: Border.all(
                                              color: selected
                                                  ? const Color(0xFF80CBC4)
                                                  : Colors.white24,
                                              width: selected ? 2.5 : 1,
                                            ),
                                          ),
                                          child: color == null
                                              ? Icon(
                                                  Icons.auto_awesome_rounded,
                                                  color: selected
                                                      ? const Color(0xFF80CBC4)
                                                      : Colors.white70,
                                                  size: 15)
                                              : selected
                                                  ? const Icon(
                                                      Icons.check_rounded,
                                                      color: Colors.white,
                                                      size: 15)
                                                  : null,
                                        ),
                                      );
                                    },
                                  ),
                                ),
                              ),
                              ),
                            ),
                          ]),
                          if (_lineStyle == 'elbow') ...[
                            const SizedBox(height: 8),
                            Row(children: [
                              const Icon(Icons.call_split_rounded,
                                  color: Colors.white38, size: 14),
                              const SizedBox(width: 4),
                              Text(
                                  context
                                      .read<MindMapProvider>()
                                      .t('conn.bendPos')
                                      .replaceFirst('{a}',
                                          '${(_elbowSplitRatio * 10).round()}')
                                      .replaceFirst('{b}',
                                          '${(10 - _elbowSplitRatio * 10).round()}'),
                                  style: const TextStyle(
                                      color: Colors.white38, fontSize: 10)),
                              Expanded(
                                child: SliderTheme(
                                  data: SliderThemeData(
                                    trackHeight: 2,
                                    thumbShape: const RoundSliderThumbShape(
                                        enabledThumbRadius: 5),
                                    activeTrackColor: const Color(0xFF80CBC4),
                                    inactiveTrackColor:
                                        Colors.white.withValues(alpha: 0.1),
                                    thumbColor: Colors.white,
                                    overlayShape: const RoundSliderOverlayShape(
                                        overlayRadius: 10),
                                  ),
                                  child: Slider(
                                    value: _elbowSplitRatio.clamp(0.1, 0.9),
                                    min: 0.1,
                                    max: 0.9,
                                    divisions: 8,
                                    onChanged: (v) {
                                      setState(() => _elbowSplitRatio = v);
                                      widget.onElbowSplitRatioChanged(v);
                                    },
                                  ),
                                ),
                              ),
                            ]),
                            Row(children: [
                              const Icon(Icons.scatter_plot_rounded,
                                  color: Colors.white38, size: 14),
                              const SizedBox(width: 4),
                              Text(context.read<MindMapProvider>().t('conn.bendCount'),
                                  style: const TextStyle(
                                      color: Colors.white38, fontSize: 10)),
                              const Spacer(),
                              IconButton(
                                visualDensity: VisualDensity.compact,
                                padding: EdgeInsets.zero,
                                constraints: const BoxConstraints(
                                    minWidth: 28, minHeight: 28),
                                icon: const Icon(Icons.remove_rounded,
                                    color: Colors.white70, size: 16),
                                onPressed: _elbowPointCount <= 1
                                    ? null
                                    : () {
                                        final next = (_elbowPointCount - 1)
                                            .clamp(1, 8)
                                            .toInt();
                                        setState(() => _elbowPointCount = next);
                                        widget.onElbowPointCountChanged(next);
                                      },
                              ),
                              Text('$_elbowPointCount',
                                  style: const TextStyle(
                                      color: Color(0xFF80CBC4),
                                      fontSize: 12,
                                      fontWeight: FontWeight.w700)),
                              IconButton(
                                visualDensity: VisualDensity.compact,
                                padding: EdgeInsets.zero,
                                constraints: const BoxConstraints(
                                    minWidth: 28, minHeight: 28),
                                icon: const Icon(Icons.add_rounded,
                                    color: Colors.white70, size: 16),
                                onPressed: _elbowPointCount >= 8
                                    ? null
                                    : () {
                                        final next = (_elbowPointCount + 1)
                                            .clamp(1, 8)
                                            .toInt();
                                        setState(() => _elbowPointCount = next);
                                        widget.onElbowPointCountChanged(next);
                                      },
                              ),
                              TextButton(
                                onPressed: widget.onClearElbowBendPoints,
                                child: Text(context.read<MindMapProvider>().t('conn.bendReset'),
                                    style: const TextStyle(
                                        color: Colors.white54, fontSize: 10)),
                              ),
                            ]),
                          ],
                          const SizedBox(height: 10),
                          // ── 線の太さ ──
                          Row(children: [
                            const Icon(Icons.line_weight_rounded,
                                color: Colors.white38, size: 14),
                            const SizedBox(width: 4),
                            Text(
                                context
                                    .read<MindMapProvider>()
                                    .t('conn.thickness'),
                                style: const TextStyle(
                                    color: Colors.white38, fontSize: 10)),
                            Expanded(
                              child: SliderTheme(
                                data: SliderThemeData(
                                  trackHeight: 2,
                                  thumbShape: const RoundSliderThumbShape(
                                      enabledThumbRadius: 5),
                                  activeTrackColor: const Color(0xFF4FC3F7),
                                  inactiveTrackColor:
                                      Colors.white.withValues(alpha: 0.1),
                                  thumbColor: Colors.white,
                                  overlayShape: const RoundSliderOverlayShape(
                                      overlayRadius: 10),
                                ),
                                child: Slider(
                                  value: _sw,
                                  min: 1.0,
                                  max: 8.0,
                                  divisions: 7,
                                  onChanged: (v) {
                                    setState(() => _sw = v);
                                    widget.onStrokeWidthChanged(v);
                                  },
                                ),
                              ),
                            ),
                            Text('${_sw.round()}',
                                style: const TextStyle(
                                    color: Color(0xFF4FC3F7), fontSize: 10)),
                          ]),
                          // ── 矢印先端のサイズ ──
                          Row(children: [
                            const Icon(Icons.arrow_forward_rounded,
                                color: Colors.white38, size: 14),
                            const SizedBox(width: 4),
                            Text(
                                context.read<MindMapProvider>().t('conn.arrow'),
                                style: const TextStyle(
                                    color: Colors.white38, fontSize: 10)),
                            Expanded(
                              child: SliderTheme(
                                data: SliderThemeData(
                                  trackHeight: 2,
                                  thumbShape: const RoundSliderThumbShape(
                                      enabledThumbRadius: 5),
                                  activeTrackColor: const Color(0xFFBA68C8),
                                  inactiveTrackColor:
                                      Colors.white.withValues(alpha: 0.1),
                                  thumbColor: Colors.white,
                                  overlayShape: const RoundSliderOverlayShape(
                                      overlayRadius: 10),
                                ),
                                child: Slider(
                                  value: _arrowScale.clamp(0.5, 3.0),
                                  min: 0.5,
                                  max: 3.0,
                                  divisions: 25,
                                  onChanged: _arrow
                                      ? (v) {
                                          setState(() => _arrowScale = v);
                                          widget.onArrowHeadScaleChanged(v);
                                        }
                                      : null,
                                ),
                              ),
                            ),
                            Text('${(_arrowScale * 200).round()}%',
                                style: TextStyle(
                                    color: _arrow
                                        ? const Color(0xFFBA68C8)
                                        : Colors.white24,
                                    fontSize: 10)),
                          ]),
                          // ── 矢印 ON/OFF ──
                          GestureDetector(
                            onTap: () {
                              setState(() => _arrow = !_arrow);
                              widget.onShowArrowChanged(_arrow);
                            },
                            child: Container(
                              padding: const EdgeInsets.symmetric(
                                  horizontal: 10, vertical: 7),
                              decoration: BoxDecoration(
                                color: _arrow
                                    ? const Color(0xFF43B97F)
                                        .withValues(alpha: 0.15)
                                    : Colors.white.withValues(alpha: 0.05),
                                borderRadius: BorderRadius.circular(10),
                                border: Border.all(
                                  color: _arrow
                                      ? const Color(0xFF43B97F)
                                          .withValues(alpha: 0.4)
                                      : Colors.white.withValues(alpha: 0.1),
                                ),
                              ),
                              child: Row(children: [
                                Icon(
                                  _arrow
                                      ? Icons.arrow_forward_rounded
                                      : Icons.remove_rounded,
                                  color: _arrow
                                      ? const Color(0xFF43B97F)
                                      : Colors.white38,
                                  size: 16,
                                ),
                                const SizedBox(width: 8),
                                Text(
                                  _arrow
                                      ? context
                                          .read<MindMapProvider>()
                                          .t('conn.arrowOn')
                                      : context
                                          .read<MindMapProvider>()
                                          .t('conn.arrowOff'),
                                  style: TextStyle(
                                    color: _arrow
                                        ? const Color(0xFF43B97F)
                                        : Colors.white54,
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                                const Spacer(),
                                Icon(
                                  _arrow
                                      ? Icons.check_circle_rounded
                                      : Icons.circle_outlined,
                                  color: _arrow
                                      ? const Color(0xFF43B97F)
                                      : Colors.white24,
                                  size: 16,
                                ),
                              ]),
                            ),
                          ),
                          const SizedBox(height: 10),
                          // ── 両方向矢印トグル ──
                          // ON にすると from 側にも矢印を表示 (= A ↔ B)。
                          // 矢印 OFF 状態の時は選択不可 (= 矢印無しなら方向の概念がない)。
                          GestureDetector(
                            onTap: _arrow
                                ? () {
                                    setState(
                                        () => _bidirectional = !_bidirectional);
                                    widget
                                        .onBidirectionalChanged(_bidirectional);
                                  }
                                : null,
                            child: Container(
                              padding: const EdgeInsets.symmetric(
                                  horizontal: 10, vertical: 7),
                              decoration: BoxDecoration(
                                color: (_arrow && _bidirectional)
                                    ? const Color(0xFF6C63FF)
                                        .withValues(alpha: 0.15)
                                    : Colors.white.withValues(alpha: 0.05),
                                borderRadius: BorderRadius.circular(10),
                                border: Border.all(
                                  color: (_arrow && _bidirectional)
                                      ? const Color(0xFF6C63FF)
                                          .withValues(alpha: 0.4)
                                      : Colors.white.withValues(alpha: 0.1),
                                ),
                              ),
                              child: Row(children: [
                                Icon(
                                  _bidirectional
                                      ? Icons.compare_arrows_rounded
                                      : Icons.arrow_forward_rounded,
                                  color: !_arrow
                                      ? Colors.white24
                                      : (_bidirectional
                                          ? const Color(0xFF6C63FF)
                                          : Colors.white54),
                                  size: 16,
                                ),
                                const SizedBox(width: 8),
                                Text(
                                  context.read<MindMapProvider>().t(
                                      _bidirectional
                                          ? 'conn.bidirectional'
                                          : 'conn.oneWay'),
                                  style: TextStyle(
                                    color: !_arrow
                                        ? Colors.white24
                                        : (_bidirectional
                                            ? const Color(0xFF6C63FF)
                                            : Colors.white54),
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                                const Spacer(),
                                Icon(
                                  (_arrow && _bidirectional)
                                      ? Icons.check_circle_rounded
                                      : Icons.circle_outlined,
                                  color: !_arrow
                                      ? Colors.white24
                                      : (_bidirectional
                                          ? const Color(0xFF6C63FF)
                                          : Colors.white24),
                                  size: 16,
                                ),
                              ]),
                            ),
                          ),
                          const SizedBox(height: 10),
                          Row(children: [
                            Expanded(
                              child: GestureDetector(
                                onTap: () {
                                  setState(
                                      () => _relationshipType = 'parentChild');
                                  widget
                                      .onRelationshipTypeChanged('parentChild');
                                },
                                child: Container(
                                  padding:
                                      const EdgeInsets.symmetric(vertical: 7),
                                  decoration: BoxDecoration(
                                    color: _relationshipType == 'parentChild'
                                        ? const Color(0xFF26A69A)
                                            .withValues(alpha: 0.18)
                                        : Colors.white.withValues(alpha: 0.04),
                                    borderRadius: BorderRadius.circular(8),
                                    border: Border.all(
                                        color:
                                            _relationshipType == 'parentChild'
                                                ? const Color(0xFF26A69A)
                                                : Colors.white12),
                                  ),
                                  child: Row(
                                      mainAxisAlignment:
                                          MainAxisAlignment.center,
                                      children: [
                                        const Icon(Icons.account_tree_rounded,
                                            color: Color(0xFF80CBC4), size: 14),
                                        const SizedBox(width: 5),
                                        Text(context.read<MindMapProvider>().t('conn.parentChild'),
                                            style: const TextStyle(
                                                color: Colors.white70,
                                                fontSize: 11)),
                                      ]),
                                ),
                              ),
                            ),
                            const SizedBox(width: 6),
                            Expanded(
                              child: GestureDetector(
                                onTap: () {
                                  setState(
                                      () => _relationshipType = 'association');
                                  widget
                                      .onRelationshipTypeChanged('association');
                                },
                                child: Container(
                                  padding:
                                      const EdgeInsets.symmetric(vertical: 7),
                                  decoration: BoxDecoration(
                                    color: _relationshipType == 'association'
                                        ? const Color(0xFF7E57C2)
                                            .withValues(alpha: 0.18)
                                        : Colors.white.withValues(alpha: 0.04),
                                    borderRadius: BorderRadius.circular(8),
                                    border: Border.all(
                                        color:
                                            _relationshipType == 'association'
                                                ? const Color(0xFF7E57C2)
                                                : Colors.white12),
                                  ),
                                  child: Row(
                                      mainAxisAlignment:
                                          MainAxisAlignment.center,
                                      children: [
                                        const Icon(Icons.link_rounded,
                                            color: Color(0xFFB39DDB), size: 14),
                                        const SizedBox(width: 5),
                                        Text(context.read<MindMapProvider>().t('conn.related'),
                                            style: const TextStyle(
                                                color: Colors.white70,
                                                fontSize: 11)),
                                      ]),
                                ),
                              ),
                            ),
                          ]),
                          const SizedBox(height: 4),
                          Text(
                            context.read<MindMapProvider>().t(
                                _relationshipType == 'parentChild'
                                    ? 'conn.parentChildHint'
                                    : 'conn.relatedHint'),
                            style: const TextStyle(
                                color: Colors.white30, fontSize: 9),
                          ),
                          if (_relationshipType == 'parentChild') ...[
                            const SizedBox(height: 6),
                            SizedBox(
                              width: double.infinity,
                              height: 34,
                              child: OutlinedButton.icon(
                                style: OutlinedButton.styleFrom(
                                  foregroundColor: const Color(0xFF80CBC4),
                                  side: const BorderSide(
                                      color: Color(0x554DB6AC)),
                                  padding:
                                      const EdgeInsets.symmetric(horizontal: 8),
                                  visualDensity: VisualDensity.compact,
                                ),
                                onPressed: widget.onReverse,
                                icon: const Icon(Icons.swap_horiz_rounded,
                                    size: 16),
                                label: Text(
                                  context
                                      .watch<MindMapProvider>()
                                      .t('conn.reverseParentChild'),
                                  style: const TextStyle(
                                      fontSize: 10,
                                      fontWeight: FontWeight.w700),
                                ),
                              ),
                            ),
                          ],
                          const SizedBox(height: 10),
                          // ── ラベル入力欄 ──
                          // 接続線の中央に表示するテキスト。 空にすると非表示。
                          // フォーカスを失った時 (= onChanged で逐次反映ではなく) に
                          // provider に保存して、 typing 中の連続再描画を避ける。
                          Row(children: [
                            const Icon(Icons.label_outline_rounded,
                                color: Colors.white54, size: 16),
                            const SizedBox(width: 8),
                            Expanded(
                              child: TextField(
                                controller: _labelCtrl,
                                keyboardType: TextInputType.multiline,
                                textInputAction: TextInputAction.newline,
                                minLines: 1,
                                maxLines: 4,
                                style: const TextStyle(
                                    color: Colors.white, fontSize: 12),
                                decoration: InputDecoration(
                                  hintText: context
                                      .read<MindMapProvider>()
                                      .t('connection.labelHint'),
                                  hintStyle: const TextStyle(
                                      color: Colors.white38, fontSize: 11),
                                  filled: true,
                                  fillColor:
                                      Colors.white.withValues(alpha: 0.05),
                                  isDense: true,
                                  border: OutlineInputBorder(
                                      borderRadius: BorderRadius.circular(8),
                                      borderSide: BorderSide(
                                          color: Colors.white
                                              .withValues(alpha: 0.1))),
                                  enabledBorder: OutlineInputBorder(
                                      borderRadius: BorderRadius.circular(8),
                                      borderSide: BorderSide(
                                          color: Colors.white
                                              .withValues(alpha: 0.1))),
                                  focusedBorder: OutlineInputBorder(
                                      borderRadius: BorderRadius.circular(8),
                                      borderSide: const BorderSide(
                                          color: Color(0xFFBA68C8))),
                                  contentPadding: const EdgeInsets.symmetric(
                                      horizontal: 8, vertical: 6),
                                ),
                                onChanged: (v) {
                                  setState(() {});
                                  _labelSaveDebounce?.cancel();
                                  _labelSaveDebounce = Timer(
                                      const Duration(milliseconds: 350), () {
                                    widget.onLabelChanged(v.trim());
                                  });
                                },
                              ),
                            ),
                            if (_labelCtrl.text.isNotEmpty) ...[
                              const SizedBox(width: 4),
                              IconButton(
                                padding: EdgeInsets.zero,
                                constraints: const BoxConstraints(
                                    minWidth: 24, minHeight: 24),
                                icon: const Icon(Icons.close_rounded,
                                    color: Colors.white54, size: 14),
                                tooltip: context
                                    .read<MindMapProvider>()
                                    .t('connection.deleteLabel'),
                                onPressed: () {
                                  _labelCtrl.clear();
                                  widget.onLabelChanged('');
                                  setState(() {});
                                },
                              ),
                            ],
                          ]),
                          if (_labelCtrl.text.isNotEmpty) ...[
                            Row(children: [
                              const Icon(Icons.open_with_rounded,
                                  color: Colors.white38, size: 14),
                              const SizedBox(width: 4),
                              Text(context.read<MindMapProvider>().t('conn.tagPos'),
                                  style: const TextStyle(
                                      color: Colors.white38, fontSize: 10)),
                              Expanded(
                                child: Slider(
                                  value: _labelPosition.clamp(0.02, 0.98),
                                  min: 0.02,
                                  max: 0.98,
                                  onChanged: (v) {
                                    setState(() => _labelPosition = v);
                                    widget.onLabelPositionChanged(v);
                                  },
                                ),
                              ),
                            ]),
                            Text(context.read<MindMapProvider>().t('conn.tagDragHint'),
                                style: const TextStyle(
                                    color: Colors.white30, fontSize: 9)),
                          ],
                          const SizedBox(height: 10),
                          // ── 方向を反転 ──
                          Row(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                _Btn(
                                  icon: Icons.swap_horiz_rounded,
                                  label: context.watch<MindMapProvider>().t(
                                      _relationshipType == 'parentChild'
                                          ? 'conn.reverseParentChild'
                                          : 'conn.reverseDirection'),
                                  color: const Color(0xFF4FC3F7),
                                  size: 40.0,
                                  onTap: widget.onReverse,
                                ),
                                const SizedBox(width: 8),
                                _Btn(
                                  icon: Icons.save_rounded,
                                  label: context
                                      .read<MindMapProvider>()
                                      .t('conn.saveDefaults'),
                                  color: const Color(0xFF80CBC4),
                                  size: 40.0,
                                  onTap: () => widget
                                      .onSaveDefaults(_snapshotConnection()),
                                ),
                                const SizedBox(width: 8),
                                // ── 削除ボタン ──
                                _Btn(
                                  icon: Icons.link_off_rounded,
                                  label: context
                                      .read<MindMapProvider>()
                                      .t('conn.delete'),
                                  color: Colors.red.shade400,
                                  size: 40.0,
                                  onTap: widget.onDelete,
                                ),
                              ]),
                        ]),
                      ),
                    ),
                ],
              ),
            ),
          ),
        ),
      ),
    ]);
  }
}

// ─── Overlay: 上にボタン、下にカラー＋サイズ ─────────────────────────────────

class _ActionOverlay extends StatefulWidget {
  final Offset screenTopPos;
  final Offset screenBottomPos;
  final VoidCallback onClose,
      onEdit,
      onMemo,
      onLink,
      onDelete,
      onCollapse,
      onSearch,
      onCycleAnchor,
      onAttach,
      onAI;
  final VoidCallback? onDeleteGalleryRow;
  final VoidCallback? onDeleteGalleryColumn;
  final VoidCallback? onSwapGalleryDeleteActions;
  final bool galleryDeleteActionsSwapped;

  /// 「高度編集」 (= 書式付きの編集画面) を開く (= ユーザー要望: 編集ボタンを
  /// 高度編集に切り替えられるようにして、 文字の大きさや書体を変えられるように)。
  final VoidCallback onRichEdit;

  /// AI ボタンの右クリック/長押し。 親 (画面) 側でアクションバーを閉じてから
  /// 「質問モード(AI 切替) / 子要素生成モード」 の選択ダイアログを中央に出す
  /// (= ユーザー要望: ノードが中央にあるとメニューがアクションバーと重なる対策)。
  final VoidCallback onAIMode;

  /// 左クリックメニューに「カレンダーに登録」ボタンとして追加。
  /// (右クリックには方向 (anchorMode) ボタン他へリプレース)
  final VoidCallback onAddToCalendar;

  /// 「カレンダーに登録」 ボタンを右クリック/長押しした時の動作
  /// (= ユーザー要望: 予定登録を右クリックでフラッシュカード登録に切替、
  ///  書いてある文字を表面に登録)。
  final VoidCallback onAddToFlashcard;

  /// 「他」ボタン: 削除の右に表示し、押すと右クリックメニュー(_showNodeContextMenu)
  /// と同等のメニューを開く。タップ操作だけで右クリック専用機能(伸ばせる方向の
  /// 切替・翻訳・要約・子ノードを追加 等)にもアクセスできるようにするため。
  final VoidCallback onMore;
  final void Function(Color) onColor;
  final ValueChanged<String> onShapeChanged;
  final void Function(double w, double h) onSizeChanged;

  /// ノード個別フォントサイズ変更（null = デフォルトにリセット）
  final void Function(double? size) onTitleFontSizeChanged;
  final void Function(double? size) onMemoFontSizeChanged;
  final Color nodeColor;
  final double nodeWidth, nodeHeight;
  final bool showSizeControls;

  /// 現在のノード個別設定値（null = デフォルト使用中）
  final double? nodeTitleFontSize;
  final double? nodeMemoFontSize;

  /// グローバルデフォルト（スライダーの初期値に使用）
  final double defaultTitleFontSize;
  final double defaultMemoFontSize;
  final NodeAnchorMode anchorMode;
  final String nodeShape;
  final bool hasChildren, isCollapsed;
  const _ActionOverlay({
    required this.screenTopPos,
    required this.screenBottomPos,
    required this.onClose,
    required this.onEdit,
    required this.onRichEdit,
    required this.onMemo,
    required this.onLink,
    required this.onDelete,
    this.onDeleteGalleryRow,
    this.onDeleteGalleryColumn,
    this.onSwapGalleryDeleteActions,
    this.galleryDeleteActionsSwapped = false,
    required this.onColor,
    required this.onCollapse,
    required this.onSizeChanged,
    required this.onSearch,
    required this.onCycleAnchor,
    required this.onShapeChanged,
    required this.onAttach,
    required this.onAI,
    required this.onAIMode,
    required this.anchorMode,
    required this.nodeShape,
    required this.onAddToCalendar,
    required this.onAddToFlashcard,
    required this.onMore,
    required this.nodeColor,
    required this.nodeWidth,
    required this.nodeHeight,
    required this.showSizeControls,
    required this.hasChildren,
    required this.isCollapsed,
    required this.onTitleFontSizeChanged,
    required this.onMemoFontSizeChanged,
    required this.defaultTitleFontSize,
    required this.defaultMemoFontSize,
    this.nodeTitleFontSize,
    this.nodeMemoFontSize,
  });
  @override
  State<_ActionOverlay> createState() => _ActionOverlayState();
}

class _ActionOverlayState extends State<_ActionOverlay>
    with SingleTickerProviderStateMixin {
  late AnimationController _anim;
  late Animation<double> _scale;
  late double _w, _h;
  late double _titleFs, _memoFs;

  /// 10色パレット（provider.nodePaletteと同一順）
  static const _colors = [
    Color(0xFF6C63FF),
    Color(0xFF43B97F),
    Color(0xFFFF6B6B),
    Color(0xFFFFB347),
    Color(0xFF4FC3F7),
    Color(0xFFBA68C8),
    Color(0xFFE53935),
    Color(0xFF00897B),
    Color(0xFFF06292),
    Color(0xFF78909C),
  ];

  @override
  void initState() {
    super.initState();
    _w = widget.nodeWidth;
    _h = widget.nodeHeight;
    _titleFs = widget.nodeTitleFontSize ?? widget.defaultTitleFontSize;
    _memoFs = widget.nodeMemoFontSize ?? widget.defaultMemoFontSize;
    _anim = AnimationController(
        vsync: this, duration: const Duration(milliseconds: 180));
    _scale = CurvedAnimation(parent: _anim, curve: Curves.easeOutBack);
    _anim.forward();
  }

  @override
  void dispose() {
    _anim.dispose();
    super.dispose();
  }

  /// リンク / 添付 を 1 つのボタンに統合 (= ユーザー要望)。 ボタン直下に小さな
  /// 2 択メニュー (リンク編集 / ファイル添付) を出して切り替える。
  Future<void> _showLinkAttachMenu(BuildContext btnCtx) async {
    final provider = btnCtx.read<MindMapProvider>();
    final box = btnCtx.findRenderObject() as RenderBox?;
    final Offset pos = box != null
        ? box.localToGlobal(box.size.bottomCenter(Offset.zero))
        : const Offset(80, 80);
    final sel = await showMenu<String>(
      context: btnCtx,
      color: const Color(0xFF2A2A3E),
      position: RelativeRect.fromLTRB(pos.dx, pos.dy, pos.dx, pos.dy),
      items: [
        PopupMenuItem<String>(
          value: 'link',
          child: Row(children: [
            const Icon(Icons.link_rounded, color: Color(0xFFFFB347), size: 18),
            const SizedBox(width: 8),
            Text(provider.t('act.link'),
                style: const TextStyle(color: Colors.white)),
          ]),
        ),
        PopupMenuItem<String>(
          value: 'attach',
          child: Row(children: [
            const Icon(Icons.attach_file_rounded,
                color: Color(0xFFFF6B6B), size: 18),
            const SizedBox(width: 8),
            Text(provider.t('act.attach'),
                style: const TextStyle(color: Colors.white)),
          ]),
        ),
      ],
    );
    if (sel == 'link') {
      widget.onLink();
    } else if (sel == 'attach') {
      widget.onAttach();
    }
  }

  /// 方向アイコンは実際に使える本数ぶんの矢印を描く
  /// (= ユーザー要望: 8 方向のアイコンが実際と合っていない)。
  Widget _anchorModeGlyph(NodeAnchorMode mode, Color color) =>
      _AnchorModeGlyph(mode: mode, color: color, size: 18);

  String _anchorModeLabel(MindMapProvider provider, NodeAnchorMode mode) {
    switch (mode) {
      case NodeAnchorMode.twoWay:
        return provider.t('act.dir2way');
      case NodeAnchorMode.fourWay:
        return provider.t('act.dir4way');
      case NodeAnchorMode.fourWayDiagonal:
        return provider.t('act.dir4wayDiagonal');
      case NodeAnchorMode.eightWay:
        return provider.t('act.dir8way');
    }
  }

  /// 検索ボタン: 左クリック (onTap) で現在のエンジンで検索、
  /// 右クリック / 長押しで Google ⇄ YouTube を切り替える (ユーザー要望)。
  /// アイコン・色・ツールチップが現在のエンジンを示す。 build は
  /// context.watch しているので、 setNodeSearchUseYoutube の notifyListeners で
  /// このオーバーレイが再ビルドされアイコンが即座に切り替わる。
  IconData _nodeShapeIcon(String shape) {
    switch (shape) {
      case 'rect':
        return Icons.crop_square_rounded;
      case 'diamond':
        return Icons.diamond_outlined;
      case 'parallelogram':
        return Icons.transform_rounded;
      case 'hexagon':
        return Icons.hexagon_outlined;
      case 'document':
        return Icons.description_outlined;
      case 'cylinder':
        return Icons.storage_rounded;
      case 'trapezoid':
        return Icons.signal_cellular_4_bar_rounded;
      case 'chevron':
        return Icons.double_arrow_rounded;
      case 'circle':
        return Icons.circle_outlined;
      default:
        return Icons.rounded_corner_rounded;
    }
  }

  /// 形状ラベルは多言語対応する (= ユーザー要望: 日本語ベタ書きだった)。
  String _nodeShapeLabel(MindMapProvider provider, String shape) {
    switch (shape) {
      case 'rect':
        return provider.t('shape.flowProcess');
      case 'diamond':
        return provider.t('shape.flowDecision');
      case 'parallelogram':
        return provider.t('shape.flowIo');
      case 'hexagon':
        return provider.t('flow.shapePrepare');
      case 'document':
        return provider.t('flow.shapeDocument');
      case 'cylinder':
        return provider.t('flow.shapeDatabase');
      case 'trapezoid':
        return provider.t('flow.shapeManual');
      case 'chevron':
        return provider.t('flow.shapeStep');
      case 'circle':
        return provider.t('flow.shapeConnector');
      default:
        return provider.t('shape.flowRounded');
    }
  }

  /// 右クリック (モバイルは長押し) で役割が変わるボタンの説明文
  /// (= ユーザー要望: 切り替えられること自体に気付けるように)。
  /// 1 行目に「今の役割」、 2 行目に「どうすれば何に変わるか」 を出す。
  /// パソコンではカーソルを乗せるだけで出る。
  String _switchTooltip(
    MindMapProvider provider, {
    required bool isDesktop,
    required String current,
    required String target,
  }) {
    final hint = provider
        .t(isDesktop ? 'act.switchHintRight' : 'act.switchHintLong')
        .replaceFirst('{target}', target);
    return '$current\n$hint';
  }

  /// 「編集 / 高度編集」 ボタン (= ユーザー要望: 編集を高度編集に切り替えられる
  /// ようにして、 そこで文字の大きさや書体を変えられるように)。
  /// 左クリックで今のモードを実行、 右クリック (モバイルは長押し) で切替。
  Widget _editBtn(MindMapProvider provider, double btnSize, {double? width}) {
    final rich = provider.nodeEditUseRich;
    void toggle() => provider.setNodeEditUseRich(!rich);
    final isDesktop =
        !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
    return GestureDetector(
      onSecondaryTap: isDesktop ? toggle : null,
      onLongPress: isDesktop ? null : toggle,
      child: Tooltip(
        triggerMode: TooltipTriggerMode.manual,
        message: _switchTooltip(
          provider,
          isDesktop: isDesktop,
          current: provider.t(rich ? 'act.editRich' : 'act.edit'),
          target: provider.t(rich ? 'act.edit' : 'act.editRich'),
        ),
        child: _Btn(
          icon: rich ? Icons.text_format_rounded : Icons.edit_rounded,
          label: provider.t(rich ? 'act.editRich' : 'act.edit'),
          // 高度編集は色を変えて、 どちらの編集か一目で分かるようにする。
          color: rich ? const Color(0xFF9575CD) : const Color(0xFF4FC3F7),
          size: btnSize,
          width: width,
          badgeIcon:
              rich ? Icons.edit_rounded : Icons.text_format_rounded,
          badgeColor:
              rich ? const Color(0xFF4FC3F7) : const Color(0xFF9575CD),
          onTap: rich ? widget.onRichEdit : widget.onEdit,
        ),
      ),
    );
  }

  Widget _searchEngineBtn(MindMapProvider provider, double btnSize,
      {double? width}) {
    final yt = provider.nodeSearchUseYoutube;
    void toggle() => provider.setNodeSearchUseYoutube(!yt);
    final isDesktop =
        !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
    return GestureDetector(
      onSecondaryTap: toggle, // 右クリック (デスクトップ)
      // PC では切替を右クリックのみに限定（ユーザー要望）。モバイルは
      // 右クリックが無いので従来どおり長押しで切替できるようにする。
      onLongPress: isDesktop ? null : toggle,
      child: Tooltip(
        // モバイルでは Tooltip 既定の「長押しで表示」 が上の onLongPress と
        //   競合して切替が発火しないため、 手動表示にして長押しを解放する
        //   (= ユーザー要望: モバイルの長押しで検索エンジン切替)。
        triggerMode: TooltipTriggerMode.manual,
        message: _switchTooltip(
          provider,
          isDesktop: isDesktop,
          current: provider.t(yt ? 'act.searchYoutube' : 'act.searchGoogle'),
          target: provider.t(yt ? 'act.searchGoogle' : 'act.searchYoutube'),
        ),
        child: _Btn(
          icon: yt ? Icons.smart_display_rounded : Icons.search_rounded,
          // モバイルはボタン幅が狭くラベルが入り切らないため 'YT' に短縮
          // (= ユーザー要望)。 デスクトップは従来どおり 'YouTube'。
          label: yt ? (isDesktop ? 'YouTube' : 'YT') : provider.t('act.search'),
          color: yt ? const Color(0xFFFF5252) : const Color(0xFF90CAF9),
          size: btnSize,
          width: width,
          // 切替先 (今が YouTube なら Google の虫めがね) を印にする。
          badgeIcon: yt ? Icons.search_rounded : Icons.smart_display_rounded,
          badgeColor:
              yt ? const Color(0xFF90CAF9) : const Color(0xFFFF5252),
          onTap: widget.onSearch,
        ),
      ),
    );
  }

  /// 「予定登録 / カードに登録」 ボタン: 左クリックで現在のモードを実行、
  /// 右クリック (PC) / 長押し (モバイル) で 予定登録 ⇄ カードに登録 を切替
  /// (= ユーザー要望: YouTube/Google 検索ボタンと同じ操作感)。 build は
  /// context.watch しているので、 setNodeCalendarUseFlashcard の notifyListeners
  /// でアイコン・ラベルが即切り替わる。
  Widget _calendarBtn(MindMapProvider provider, double btnSize,
      {double? width}) {
    final useCard = provider.nodeCalendarUseFlashcard;
    void toggle() => provider.setNodeCalendarUseFlashcard(!useCard);
    final isDesktop =
        !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
    return GestureDetector(
      onSecondaryTap: isDesktop ? toggle : null,
      onLongPress: isDesktop ? null : toggle,
      child: Tooltip(
        triggerMode: TooltipTriggerMode.manual,
        message: _switchTooltip(
          provider,
          isDesktop: isDesktop,
          current: provider.t(useCard ? 'act.addToCard' : 'act.addToCalendar'),
          target: provider.t(useCard ? 'act.addToCalendar' : 'act.addToCard'),
        ),
        child: _Btn(
          icon: useCard ? Icons.style_rounded : Icons.event_available_rounded,
          label: useCard
              ? provider.t('act.addToCard')
              : provider.t('act.addToCalendar'),
          // ── どちらの役割かが色で分かるようにする (= ユーザー要望) ──
          //   カードに登録 = 青緑 / 予定登録 = 紫。
          color: useCard ? const Color(0xFF4DB6AC) : const Color(0xFFBA68C8),
          size: btnSize,
          width: width,
          badgeIcon: useCard
              ? Icons.event_available_rounded
              : Icons.style_rounded,
          badgeColor:
              useCard ? const Color(0xFFBA68C8) : const Color(0xFF4DB6AC),
          onTap: useCard ? widget.onAddToFlashcard : widget.onAddToCalendar,
        ),
      ),
    );
  }

  /// リンク / ファイル添付ボタン: 左クリック (onTap) で現在のモードを実行、
  /// 右クリック / 長押しで リンク ⇄ 添付 を切り替える (= ユーザー要望: YouTube/
  /// Google 検索ボタンと同じ操作感)。 アイコン・色・ラベルが現在のモードを示す。
  Widget _linkAttachBtn(MindMapProvider provider, double btnSize,
      {double? width}) {
    final useAttach = provider.nodeLinkUseAttach;
    void toggle() => provider.setNodeLinkUseAttach(!useAttach);
    final isDesktop =
        !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
    return GestureDetector(
      onSecondaryTap: isDesktop ? toggle : null,
      onLongPress: isDesktop ? null : toggle,
      child: Tooltip(
        triggerMode: TooltipTriggerMode.manual,
        message: _switchTooltip(
          provider,
          isDesktop: isDesktop,
          current: provider.t(useAttach ? 'act.attach' : 'act.link'),
          target: provider.t(useAttach ? 'act.link' : 'act.attach'),
        ),
        child: _Btn(
          icon: useAttach ? Icons.attach_file_rounded : Icons.link_rounded,
          label: useAttach ? provider.t('act.attach') : provider.t('act.link'),
          // ── どちらの役割かが色で分かるようにする (= ユーザー要望) ──
          //   添付 = 橙 / リンク = 青。
          color: useAttach ? const Color(0xFFFFB347) : const Color(0xFF64B5F6),
          size: btnSize,
          width: width,
          badgeIcon:
              useAttach ? Icons.link_rounded : Icons.attach_file_rounded,
          badgeColor:
              useAttach ? const Color(0xFF64B5F6) : const Color(0xFFFFB347),
          onTap: useAttach ? widget.onAttach : widget.onLink,
        ),
      ),
    );
  }

  /// AIボタン: 左クリック (onTap) でノードタイトルの用語をブラウザの AI
  /// (ChatGPT / Gemini 等) に渡してアプリ内分割パネルで開く。 右クリック /
  /// 長押しで使う AI サービスを切り替える。 build は context.watch している
  /// ので、 setBrowserAiTarget の notifyListeners でツールチップが即更新される。
  Widget _aiEngineBtn(MindMapProvider provider, double btnSize,
      {double? width}) {
    final isDesktop =
        !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
    final label = provider.browserAiTargetLabel;
    return GestureDetector(
      onSecondaryTapDown: isDesktop ? (_) => widget.onAIMode() : null,
      onLongPressStart: isDesktop ? null : (_) => widget.onAIMode(),
      child: Tooltip(
        // モバイルでは Tooltip 既定の長押し表示が上の onLongPressStart と
        //   競合するため手動表示にする (= ユーザー要望: モバイル長押しで AI 切替)。
        triggerMode: TooltipTriggerMode.manual,
        message: isDesktop
            ? '$label にノードの内容(埋め込み URL 含む)を渡して質問\n右クリックで AI 切替/子要素生成'
            : '$label にノードの内容(埋め込み URL 含む)を渡して質問\n長押しで AI 切替/子要素生成',
        child: _Btn(
          icon: Icons.auto_awesome_rounded,
          label: provider.t('act.ai'),
          color: const Color(0xFFBA68C8),
          size: btnSize,
          width: width,
          // ── 右上に歯車 (= ユーザー要望: AI も右クリックで設定画面が開く) ──
          //   他のボタンは切替先のアイコンを出すが、 ここは切替ではなく
          //   設定を開くので歯車にする。
          badgeIcon: Icons.settings_rounded,
          // 左タップ = 質問モード (= 最後に使った AI でタイトルを渡して開く)。
          onTap: widget.onAI,
        ),
      ),
    );
  }

  // AI モード選択 (質問モード / 子要素生成モード) のダイアログは、 アクション
  // バーと重ならないよう、 画面側 (_showNodeAiModeMenu) でアクションバーを閉じて
  // から中央モーダルとして表示する (= ユーザー要望)。 ここではトリガーするだけ。

  BoxDecoration _barDeco() => BoxDecoration(
        color: const Color(0xFF1A1A30),
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: Colors.white.withValues(alpha: 0.15)),
        boxShadow: [
          BoxShadow(
              color: Colors.black.withValues(alpha: 0.6),
              blurRadius: 24,
              offset: const Offset(0, 8))
        ],
      );

  @override
  Widget build(BuildContext context) {
    final provider = context.watch<MindMapProvider>();
    final mq = MediaQuery.of(context);
    final screenW = mq.size.width;
    final screenH = mq.size.height;
    // モバイルの狭い画面ではボタンサイズを小さくして delete などが
    // 画面外に溢れないようにする (Poco F6 Pro 等のアスペクト比でも収まるよう
    // 380px 以下で "compact" モードに切り替え)
    final bool compact = screenW < 400;
    final double btnSize = compact ? 30.0 : 36.0;
    final double btnGap = compact ? 3.0 : 4.0;
    final bool showGalleryDeleteActions = widget.onDeleteGalleryRow != null &&
        widget.onDeleteGalleryColumn != null;
    final bool showSizeControls = widget.showSizeControls;
    final bool showQuickBar = false;
    // 実際に表示されるボタン個数:
    // Edit, AI, Link, Search, Calendar (+ Collapse if hasChildren), Delete,
    // Gallery row/column delete (bookshelf only), More
    final int btnCount =
        (widget.hasChildren ? 9 : 8) + (showGalleryDeleteActions ? 2 : 0);
    // 左右 padding は compact でも詰めすぎず 16 (元 24) を確保
    final double topBarPadH = compact ? 8.0 : 12.0;
    // ── ボタン幅は「画面幅からの均等割り」 で決める (= ユーザー要望:
    //    複数行に跨ったり隙間が空きすぎたりせず、 1 行に詰めて収める) ──
    // 画面に収まる範囲で 1 個あたりの幅を最大化する。 下限はアイコン幅
    // (これ以上は縮められない)、 上限はアイコンの 1.5 倍 (広げすぎない)。
    final double btnBoxW =
        ((screenW - 16 - topBarPadH * 2 - btnGap * (btnCount - 1)) / btnCount)
            .clamp(btnSize, btnSize * 1.5)
            .toDouble();
    final double topBarW =
        btnBoxW * btnCount + btnGap * (btnCount - 1) + topBarPadH * 2;
    // 10色パレット: compact でも見えやすい色コイン大きさは維持 (20px)
    // 20*10 + margin(3)*9 + padding(16) = 243; 既定 280 より狭い
    final double colorCoin = compact ? 20.0 : 22.0;
    final double colorMargin = compact ? 1.0 : 1.5;
    final double bottomBarW =
        compact ? (colorCoin * 10 + colorMargin * 2 * 10 + 20) : 280.0;

    // 上バーの幅を画面幅に収める
    final double clampedTopBarW = topBarW.clamp(0.0, screenW - 16);

    // 下バー（色・スライダー）: ノード中心で水平センタリング
    // ── ノードの上と下に表示 + 表示位置を固定 ──
    // ユーザー要望「ノードをタップした時に出てくる項目はノードの上と下に
    //   表れるようにして、 スクロールしても一緒に動かないようにして」 への
    //   対応。
    //
    //   - 下バー (= 色 / サイズスライダー) はノードの下に表示
    //     ノードの下端の Y 座標 (widget.screenBottomPos.dy) を基準に下方向 12px
    //   - 上バー (= 編集 / AI / リンク等) はノードの上に表示
    //     ノードの上端の Y 座標 (widget.screenTopPos.dy) を基準に上方向
    //   - 位置は initState で固定された値 (_fixedTopPos / _fixedBottomPos)
    //     を使う → マップをスクロールしても overlay は動かない。
    double bL = (widget.screenBottomPos.dx - bottomBarW / 2)
        .clamp(8.0, (screenW - bottomBarW - 8).clamp(8.0, screenW));

    final bool overflowsTopBar = topBarW > screenW - 16;
    final double wrappedBarMaxW = (screenW - 16).clamp(0.0, screenW);
    // 上バーは ノードの上 に表示。
    // 1 行で収まる時 → 下バー (色/スライダー) と左端を揃える (= ユーザー要望:
    //   上の項目が左に寄り過ぎているので下の項目と左端を合わせる)。
    // 2 行 (Wrap) になる時 → ノード中心で水平センタリング。
    double tL = overflowsTopBar
        ? (widget.screenTopPos.dx - wrappedBarMaxW / 2)
            .clamp(8.0, (screenW - wrappedBarMaxW - 8).clamp(8.0, screenW))
        : bL.clamp(8.0, (screenW - clampedTopBarW - 8).clamp(8.0, screenW));

    // ── 縦位置: 上バー (ボタン) と 下バー (色/スライダー) が重ならないように ──
    // ユーザー報告: 「ウィンドウが小さい状態で下の方のノードをタップすると
    //   項目が重なって出て使いづらい」。
    // 原因: 旧実装は上バーをノード上端基準・下バーをノード下端基準で
    //   別々にクランプしていたため、 画面が低い & ノードが下端付近だと
    //   両バーが画面下部に寄って重なっていた。
    // 対応: ノードの上下の余白を見て、 下に十分入らなければ「両方ノードの上に
    //   積む」、 上に入らなければ「両方ノードの下に積む」、 どちらも十分なら
    //   従来どおり「ボタン上 / スライダー下」。 これで必ず重ならない。
    final double quickBarH = showQuickBar ? btnSize + 18 : 0.0;
    final double topBarH =
        (overflowsTopBar ? btnSize * 2 + 12 : btnSize) + quickBarH + 28;
    final double bottomBarH = showSizeControls
        ? (compact ? 156.0 : 176.0)
        : (compact ? 112.0 : 128.0);
    const double gap = 12.0;
    final double roomBelow = screenH - widget.screenBottomPos.dy;
    final double roomAbove = widget.screenTopPos.dy - mq.padding.top;
    double tT, bT;
    if (roomBelow < bottomBarH + 16 && roomAbove > topBarH + bottomBarH + 24) {
      // 下に余白なし → ノードの上に [ボタン][スライダー] の順で積む
      bT = widget.screenTopPos.dy - bottomBarH - gap;
      tT = bT - topBarH - gap;
    } else if (roomAbove < topBarH + 16 &&
        roomBelow > topBarH + bottomBarH + 24) {
      // 上に余白なし → ノードの下に [ボタン][スライダー] の順で積む
      tT = widget.screenBottomPos.dy + gap;
      bT = tT + topBarH + gap;
    } else {
      // 既定: ボタンはノード上、 スライダーはノード下
      tT = widget.screenTopPos.dy - topBarH - gap;
      bT = widget.screenBottomPos.dy + gap;
    }
    // 最終的に画面内へクランプ (両バーの高さを考慮)
    tT = tT.clamp(
        mq.padding.top + 8, (screenH - topBarH - 8).clamp(0.0, screenH));
    bT = bT.clamp(
        mq.padding.top + 8, (screenH - bottomBarH - 8).clamp(0.0, screenH));

    // ラベル幅は _Btn の既定 (アイコンの 1.6 倍) に任せる。 全ボタン同じ
    // 幅なので間隔が均等になり、 「行削除」「列削除」 も全文字見える
    // (= ユーザー要望: レイアウトを崩さず表示文字を増やす)。
    // ラベルはボタン幅に収まる短縮形 (act.delRow / act.delCol) を使う
    // (= ユーザー要望: 英語の "Delete this row" が "Delete t…" に切れる)。
    // ── 行削除 / 列削除 は 1 つのボタンにまとめる (= ユーザー要望) ──
    //   横に 2 つ並べるとバーが長くなるので、 今の役割だけを出し、
    //   右クリック (モバイルは長押し) でもう一方に切り替える。
    //   どちらを出すかは既存の `galleryDeleteActionsSwapped` をそのまま使う
    //   (true = 列削除)。
    final bool delColMode = widget.galleryDeleteActionsSwapped;
    final isDesktopPlatform =
        !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
    Widget galleryDeleteBtn() => GestureDetector(
          onSecondaryTap: isDesktopPlatform
              ? widget.onSwapGalleryDeleteActions
              : null,
          child: Tooltip(
            triggerMode: TooltipTriggerMode.manual,
            message: _switchTooltip(
              provider,
              isDesktop: isDesktopPlatform,
              current: provider.t(delColMode ? 'act.delCol' : 'act.delRow'),
              target: provider.t(delColMode ? 'act.delRow' : 'act.delCol'),
            ),
            child: _Btn(
              icon: delColMode
                  ? Icons.view_column_rounded
                  : Icons.table_rows_rounded,
              label: provider.t(delColMode ? 'act.delCol' : 'act.delRow'),
              color: delColMode
                  ? const Color(0xFFFFB74D)
                  : const Color(0xFFFF8A65),
              size: btnSize,
              width: btnBoxW,
              badgeIcon: delColMode
                  ? Icons.table_rows_rounded
                  : Icons.view_column_rounded,
              badgeColor: delColMode
                  ? const Color(0xFFFF8A65)
                  : const Color(0xFFFFB74D),
              onTap: delColMode
                  ? widget.onDeleteGalleryColumn!
                  : widget.onDeleteGalleryRow!,
              // モバイルは右クリックが無いので長押しで切り替える。
              onLongPress: isDesktopPlatform
                  ? null
                  : widget.onSwapGalleryDeleteActions,
            ),
          ),
        );
    final galleryDeleteButtons =
        showGalleryDeleteActions ? <Widget>[galleryDeleteBtn()] : const <Widget>[];

    final shapeButtons = <Widget>[];
    final selectedShape = widget.nodeShape == 'stadium'
        ? 'rounded'
        : widget.nodeShape.isEmpty
            ? 'rounded'
            : widget.nodeShape;
    // バーが横に伸びすぎないよう基本の 4 種のみ並べ、 それ以外の端子形状
    // (六角形 / 書類 / 円筒 …) が選ばれている時だけその形状も足す。
    final shapeList = <String>[
      'rounded',
      'rect',
      'diamond',
      'parallelogram',
      if (!const ['rounded', 'rect', 'diamond', 'parallelogram']
          .contains(selectedShape))
        selectedShape,
    ];
    for (final shape in shapeList) {
      if (shapeButtons.isNotEmpty) shapeButtons.add(SizedBox(width: btnGap));
      final selected = selectedShape == shape;
      shapeButtons.add(_Btn(
        icon: _nodeShapeIcon(shape),
        // 実際の形をそのまま描く (= ユーザー要望: 判断は ♦ みたいに)。
        iconBuilder: (c) =>
            _FlowShapeIcon(shape, color: c, size: const Size(22, 16)),
        label: _nodeShapeLabel(provider, shape),
        color: selected ? const Color(0xFF4DB6AC) : const Color(0xFF546E7A),
        size: btnSize,
        width: btnBoxW,
        onTap: () => widget.onShapeChanged(shape),
      ));
    }
    final quickBarContent = Row(mainAxisSize: MainAxisSize.min, children: [
      ...shapeButtons,
      SizedBox(width: btnGap),
      _Btn(
        icon: Icons.open_with_rounded,
        iconBuilder: (c) => _anchorModeGlyph(widget.anchorMode, c),
        label: _anchorModeLabel(provider, widget.anchorMode),
        color: const Color(0xFF78909C),
        size: btnSize,
        width: btnBoxW,
        onTap: widget.onCycleAnchor,
      ),
    ]);
    final topBarContent = Row(mainAxisSize: MainAxisSize.min, children: [
      _editBtn(provider, btnSize, width: btnBoxW),
      SizedBox(width: btnGap),
      _aiEngineBtn(provider, btnSize, width: btnBoxW),
      SizedBox(width: btnGap),
      // リンク / 添付 を 1 ボタンに統合 (= ユーザー要望: タップで 2 択切替)。
      _linkAttachBtn(provider, btnSize, width: btnBoxW),
      SizedBox(width: btnGap),
      _searchEngineBtn(provider, btnSize, width: btnBoxW),
      SizedBox(width: btnGap),
      // ── カレンダーに登録 (左クリック専用) ──
      // 旧 anchorMode (伸ばせる方向) ボタンの位置を流用。anchorMode は
      // 右クリックメニュー (_showNodeContextMenu) に移動した。
      _calendarBtn(provider, btnSize, width: btnBoxW),
      if (widget.hasChildren) ...[
        SizedBox(width: btnGap),
        _Btn(
            icon: widget.isCollapsed
                ? Icons.unfold_more_rounded
                : Icons.unfold_less_rounded,
            label: widget.isCollapsed
                ? provider.t('act.expand')
                : provider.t('act.collapse'),
            color: const Color(0xFF7E57C2),
            size: btnSize,
            width: btnBoxW,
            onTap: widget.onCollapse),
      ],
      for (final b in galleryDeleteButtons) ...[
        SizedBox(width: btnGap),
        b,
      ],
      // ── 削除は右から 2 番目に固定する (= ユーザー要望) ──
      //   一番右は「他」 (右クリックメニュー) なので、 その手前に置く。
      SizedBox(width: btnGap),
      _Btn(
          icon: Icons.delete_rounded,
          label: provider.t('act.delete'),
          color: Colors.red.shade400,
          size: btnSize,
          width: btnBoxW,
          onTap: widget.onDelete),
      SizedBox(width: btnGap),
      // ── 他 (More): 右クリックメニューを開く ──
      // タップ操作だけで右クリック専用機能 (伸ばせる方向の切替・翻訳・要約・
      // 子ノードを追加 等) にもアクセスできるようにするためのエントリポイント。
      _Btn(
          icon: Icons.more_horiz_rounded,
          label: provider.t('act.more'),
          color: const Color(0xFF78909C),
          size: btnSize,
          width: btnBoxW,
          onTap: widget.onMore),
    ]);

    // ── 画面が狭すぎて 1 行で収まらない時は 2 行にラップして全ボタンを表示する ──
    // 旧実装は SingleChildScrollView で横スクロールにフォールバックしていたが、
    // ユーザーから「上の "他" 項目が入り切れていない」と指摘があり、
    // スクロールに気付かないケースが多いことが分かった。
    // → Wrap に切り替え、必要に応じて 2 行目に折り返す。これで全ボタン
    //   (特に右端の "他" / Delete) がスクロールなしで常に見える。
    // 注: overflowsTopBar の判定はレイアウト計算用に上で定義済みなので
    // ここでは再定義しない。
    final List<Widget> wrappedChildren = [
      _editBtn(provider, btnSize, width: btnBoxW),
      _aiEngineBtn(provider, btnSize, width: btnBoxW),
      // リンク / 添付 を 1 ボタンに統合 (= ユーザー要望: タップで 2 択切替)。
      _linkAttachBtn(provider, btnSize, width: btnBoxW),
      _searchEngineBtn(provider, btnSize, width: btnBoxW),
      _calendarBtn(provider, btnSize, width: btnBoxW),
      if (widget.hasChildren)
        _Btn(
            icon: widget.isCollapsed
                ? Icons.unfold_more_rounded
                : Icons.unfold_less_rounded,
            label: widget.isCollapsed
                ? provider.t('act.expand')
                : provider.t('act.collapse'),
            color: const Color(0xFF7E57C2),
            size: btnSize,
            width: btnBoxW,
            onTap: widget.onCollapse),
      ...galleryDeleteButtons,
      // 削除は右から 2 番目 (= ユーザー要望)。
      _Btn(
          icon: Icons.delete_rounded,
          label: provider.t('act.delete'),
          color: Colors.red.shade400,
          size: btnSize,
          width: btnBoxW,
          onTap: widget.onDelete),
      _Btn(
          icon: Icons.more_horiz_rounded,
          label: provider.t('act.more'),
          color: const Color(0xFF78909C),
          size: btnSize,
          width: btnBoxW,
          onTap: widget.onMore),
    ];
    final wrappedTopBar = Wrap(
      spacing: btnGap,
      runSpacing: btnGap,
      alignment: WrapAlignment.center,
      children: wrappedChildren,
    );

    return Stack(children: [
      Positioned.fill(
          child: GestureDetector(
              onTap: widget.onClose,
              behavior: HitTestBehavior.translucent,
              child: const SizedBox.expand())),
      // ── 上: ボタン ──
      Positioned(
          left: tL,
          top: tT,
          child: ScaleTransition(
            scale: _scale,
            alignment: Alignment.bottomCenter,
            child: Material(
                color: Colors.transparent,
                child: Container(
                  // 1 行に収まる時は元の clampedTopBarW、収まらない時は画面幅の
                  // ほぼいっぱいまで使って Wrap で 2 行に折り返す。
                  constraints: BoxConstraints(
                      maxWidth: overflowsTopBar
                          ? (screenW - 16).clamp(0.0, screenW)
                          : clampedTopBarW),
                  padding: EdgeInsets.symmetric(
                      horizontal: topBarPadH, vertical: compact ? 7 : 10),
                  decoration: _barDeco(),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      if (showQuickBar) ...[
                        SingleChildScrollView(
                          scrollDirection: Axis.horizontal,
                          child: quickBarContent,
                        ),
                        SizedBox(height: compact ? 6 : 8),
                      ],
                      overflowsTopBar ? wrappedTopBar : topBarContent,
                    ],
                  ),
                )),
          )),
      // ── 下: カラー＋サイズ＋文字サイズ ──
      Positioned(
          left: bL,
          top: bT,
          child: ScaleTransition(
            scale: _scale,
            alignment: Alignment.topCenter,
            child: Material(
                color: Colors.transparent,
                child: Container(
                  width: bottomBarW,
                  padding: EdgeInsets.symmetric(
                      horizontal: compact ? 8 : 12, vertical: compact ? 7 : 10),
                  decoration: _barDeco(),
                  child: Column(mainAxisSize: MainAxisSize.min, children: [
                    // カラー
                    Row(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: _colors.map((c) {
                          final on = c.value == widget.nodeColor.value;
                          return GestureDetector(
                              onTap: () => widget.onColor(c),
                              child: Container(
                                width: colorCoin,
                                height: colorCoin,
                                margin: EdgeInsets.symmetric(
                                    horizontal: colorMargin),
                                decoration: BoxDecoration(
                                    color: c,
                                    shape: BoxShape.circle,
                                    border: on
                                        ? Border.all(
                                            color: Colors.white, width: 2.5)
                                        : Border.all(
                                            color: Colors.white
                                                .withValues(alpha: 0.2),
                                            width: 1),
                                    boxShadow: on
                                        ? [
                                            BoxShadow(
                                                color: c.withValues(alpha: 0.5),
                                                blurRadius: 6,
                                                spreadRadius: 1)
                                          ]
                                        : null),
                              ));
                        }).toList()),
                    const SizedBox(height: 6),
                    // ノードサイズ
                    if (showSizeControls) ...[
                      _sizeRow(
                          Icons.swap_horiz_rounded,
                          provider.t('overlay.widthLabel'),
                          _w,
                          80,
                          400,
                          const Color(0xFF4FC3F7), (v) {
                        setState(() => _w = v);
                        widget.onSizeChanged(_w, _h);
                      }),
                      _sizeRow(
                          Icons.height_rounded,
                          provider.t('overlay.heightLabel'),
                          _h,
                          36,
                          200,
                          const Color(0xFF43B97F), (v) {
                        setState(() => _h = v);
                        widget.onSizeChanged(_w, _h);
                      }),
                      const Divider(color: Colors.white10, height: 10),
                    ] else
                      const SizedBox(height: 6),
                    // ── 文字サイズ ──
                    // = ユーザー要望: 「タイトル」 という項目自体が無い (= 統合
                    //   リッチテキスト) ので、 旧「タイトルの大きさ」 行は削除し、
                    //   表示文字サイズを司る 1 つ (= メモ文字サイズ) だけ残す。
                    Row(children: [
                      const Icon(Icons.notes_rounded,
                          color: Colors.white38, size: 13),
                      const SizedBox(width: 2),
                      Text(provider.t('overlay.memoFontLabel'),
                          style: const TextStyle(
                              color: Colors.white38, fontSize: 10)),
                      Expanded(
                          child: SliderTheme(
                        data: SliderThemeData(
                            trackHeight: 2,
                            thumbShape: const RoundSliderThumbShape(
                                enabledThumbRadius: 5),
                            activeTrackColor: const Color(0xFF43B97F),
                            inactiveTrackColor:
                                Colors.white.withValues(alpha: 0.1),
                            thumbColor: Colors.white,
                            overlayShape: const RoundSliderOverlayShape(
                                overlayRadius: 10)),
                        child: Slider(
                            value: _memoFs,
                            min: 6,
                            max: 22,
                            onChanged: (v) {
                              setState(() {
                                _memoFs = v;
                              });
                              widget.onMemoFontSizeChanged(v);
                            }),
                      )),
                      Text('${_memoFs.round()}',
                          style: const TextStyle(
                              color: Color(0xFF43B97F), fontSize: 10)),
                    ]),
                  ]),
                )),
          )),
    ]);
  }

  Widget _sizeRow(IconData icon, String label, double val, double min,
      double max, Color color, ValueChanged<double> onChanged) {
    return Row(children: [
      Icon(icon, color: Colors.white38, size: 14),
      const SizedBox(width: 2),
      Text(label, style: const TextStyle(color: Colors.white38, fontSize: 10)),
      Expanded(
          child: SliderTheme(
        data: SliderThemeData(
            trackHeight: 2,
            thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 5),
            activeTrackColor: color,
            inactiveTrackColor: Colors.white.withValues(alpha: 0.1),
            thumbColor: Colors.white,
            overlayShape: const RoundSliderOverlayShape(overlayRadius: 10)),
        child: Slider(value: val, min: min, max: max, onChanged: onChanged),
      )),
      Text('${val.round()}',
          style: const TextStyle(color: Colors.white38, fontSize: 10)),
    ]);
  }
}

/// PC カスタムヘッダーのD&D payload。個別ボタンは index ではなく
/// commandId と移動元の辺を持つため、別バーへ落としても別リストの同じ index を
/// 誤って並び替えることがない。バー用 payload も同じ DragTarget で受ける。
abstract class _DesktopHeaderDragData {
  String get sourcePlacement;
  const _DesktopHeaderDragData();
}

class _DesktopHeaderButtonDragData extends _DesktopHeaderDragData {
  final String commandId;
  @override
  final String sourcePlacement;
  const _DesktopHeaderButtonDragData(this.commandId, this.sourcePlacement);
}

class _DesktopHeaderBarDragData extends _DesktopHeaderDragData {
  @override
  final String sourcePlacement;
  const _DesktopHeaderBarDragData(this.sourcePlacement);
}

/// 同一のPCカスタムバー内で、ボタンの「間」を明示する挿入先。
///
/// バー全体の DragTarget とは役割を分け、移動元と同じ辺のボタンだけを受理する。
/// これにより別辺へ移す操作は引き続き実画面端の判定を必ず通る。
class _DesktopHeaderInsertionGap extends StatelessWidget {
  final Axis barAxis;
  final String placement;
  final String? beforeCommandId;
  final bool active;
  final ValueChanged<_DesktopHeaderButtonDragData> onDropped;
  final VoidCallback onDragEnded;

  const _DesktopHeaderInsertionGap({
    required this.barAxis,
    required this.placement,
    required this.beforeCommandId,
    required this.active,
    required this.onDropped,
    required this.onDragEnded,
  });

  @override
  Widget build(BuildContext context) {
    final horizontal = barAxis == Axis.horizontal;
    return SizedBox(
      width: horizontal
          ? _kDesktopHeaderInsertionGapExtent
          : _kHeaderCustomButtonExtent,
      height: horizontal
          ? _kHeaderCustomButtonExtent
          : _kDesktopHeaderInsertionGapExtent,
      child: DragTarget<_DesktopHeaderDragData>(
        onWillAcceptWithDetails: (details) {
          final data = details.data;
          return active &&
              data is _DesktopHeaderButtonDragData &&
              data.sourcePlacement == placement &&
              data.commandId != beforeCommandId;
        },
        onAcceptWithDetails: (details) {
          final data = details.data;
          if (data is! _DesktopHeaderButtonDragData) return;
          onDragEnded();
          onDropped(data);
        },
        builder: (context, candidates, rejected) {
          final hovered = candidates.isNotEmpty;
          return AnimatedOpacity(
            opacity: active ? 1 : 0,
            duration: const Duration(milliseconds: 90),
            child: Center(
              child: AnimatedContainer(
                duration: const Duration(milliseconds: 90),
                width: horizontal ? (hovered ? 6 : 3) : (hovered ? 34 : 24),
                height: horizontal ? (hovered ? 34 : 24) : (hovered ? 6 : 3),
                decoration: BoxDecoration(
                  color: hovered
                      ? const Color(0xFFFFB347)
                      : const Color(0xFF8D86FF),
                  borderRadius: BorderRadius.circular(4),
                  boxShadow: hovered
                      ? const [
                          BoxShadow(
                            color: Color(0x99FFB347),
                            blurRadius: 8,
                          ),
                        ]
                      : null,
                ),
              ),
            ),
          );
        },
      ),
    );
  }
}

/// 通常表示中のPCカスタムボタンを、クリック可能なまま同一バー内で並べ替えたり
/// 別バーへ移したりできるラッパー。子をAbsorbPointerで無効化しない。
class _DesktopDraggableHeaderIcon extends StatelessWidget {
  final _DesktopHeaderButtonDragData data;
  final Widget child;
  final VoidCallback onDragStarted;
  final VoidCallback onDragEnded;
  final ValueChanged<Offset>? onDragUpdate;

  const _DesktopDraggableHeaderIcon({
    required this.data,
    required this.child,
    required this.onDragStarted,
    required this.onDragEnded,
    this.onDragUpdate,
  });

  @override
  Widget build(BuildContext context) {
    final draggable = Draggable<_DesktopHeaderDragData>(
      data: data,
      dragAnchorStrategy: pointerDragAnchorStrategy,
      onDragStarted: onDragStarted,
      onDragUpdate: (details) => onDragUpdate?.call(details.globalPosition),
      onDragEnd: (_) => onDragEnded(),
      onDragCompleted: onDragEnded,
      onDraggableCanceled: (_, __) => onDragEnded(),
      feedback: Material(
        color: Colors.transparent,
        child: IgnorePointer(
          child: Opacity(opacity: 0.88, child: child),
        ),
      ),
      childWhenDragging: Opacity(opacity: 0.22, child: child),
      child: child,
    );
    // アイコン本体はドロップ先にしない。並び替えは前後の細い挿入
    // ギャップだけが受理し、移動先アイコンへのハイライトも出さない。
    return draggable;
  }
}

/// カスタムヘッダーの共通寸法。
const double _kHeaderCustomBarHeight = 48.0;
const double _kHeaderCustomButtonExtent = 48.0;
const double _kDesktopHeaderInsertionGapExtent = 8.0;
const double _kDesktopHeaderSideReserve = 336.0;

/// AppBar 上でカスタムヘッダーボタンを横並び表示するウィジェット
///
/// PCでは通常時も別バーへドラッグでき、並び替えモード中は同じバー内の
/// 挿入位置まで指定できる。モバイルの従来並び替えはint indexのまま維持する。
class _HeaderCustomButtonsBar extends StatefulWidget {
  final MindMapProvider provider;
  final Widget? Function(String cmdId, MindMapProvider provider) buildButton;

  /// true にするとヘッダーアイコンがドラッグで並び替え可能になる。
  /// アイコン自体は振動するアニメ + 点線枠で「いま動かせるよ」感を出す。
  final bool reorderMode;

  /// 並び替え時に呼ばれる (oldIndex, newIndex)
  final void Function(int oldIndex, int newIndex)? onReorder;

  /// 表示するコマンドID一覧。 null なら provider.customHeaderButtons (通常ページ)。
  /// ギャラリー等では provider.galleryHeaderButtons を渡す (= ユーザー要望:
  /// ギャラリーのヘッダーも独立してカスタマイズ)。
  final List<String>? buttonIds;
  final String? storageKey;

  /// PC の上下ドックで使う辺。指定時は int index ではなく
  /// commandId + source placement の payload でドラッグし、別バーへの
  /// ドロップも provider の atomic move API で処理する。
  final String? desktopPlacement;
  final void Function(_DesktopHeaderButtonDragData data)?
      onDesktopButtonDragStarted;
  final VoidCallback? onDesktopButtonDragEnded;
  final _DesktopHeaderButtonDragData? activeDesktopButtonDrag;

  /// モバイルの展開段では右側アクション分の予約幅を取らず、横幅いっぱい使う。
  final bool fullWidth;
  final Widget? trailing;
  final double? maxWidth;
  const _HeaderCustomButtonsBar({
    required this.provider,
    required this.buildButton,
    this.reorderMode = false,
    this.onReorder,
    this.buttonIds,
    this.storageKey,
    this.desktopPlacement,
    this.onDesktopButtonDragStarted,
    this.onDesktopButtonDragEnded,
    this.activeDesktopButtonDrag,
    this.fullWidth = false,
    this.trailing,
    this.maxWidth,
  });

  @override
  State<_HeaderCustomButtonsBar> createState() =>
      _HeaderCustomButtonsBarState();
}

class _HeaderCustomButtonsBarState extends State<_HeaderCustomButtonsBar> {
  // 並び替え中のドラッグに追従して、 端に近づいたら横スクロールする
  // (= ユーザー要望: 要素が多いとスクロールして端に持っていけない)。
  final ScrollController _scrollCtrl = ScrollController();
  final GlobalKey _scrollAreaKey = GlobalKey();
  Timer? _autoScrollTimer;
  double _autoScrollDir = 0.0; // -1 = 左へ / +1 = 右へ / 0 = 停止

  @override
  void dispose() {
    _autoScrollTimer?.cancel();
    _scrollCtrl.dispose();
    super.dispose();
  }

  @override
  void didUpdateWidget(covariant _HeaderCustomButtonsBar oldWidget) {
    super.didUpdateWidget(oldWidget);
    // 通常マップとギャラリー系では保存元のボタン列が別。ページ切替時に前の
    // 横スクロール位置を持ち越すと、同じ中央基準でも列だけ横へずれて見える。
    if ((oldWidget.buttonIds == null) != (widget.buttonIds == null)) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && _scrollCtrl.hasClients) _scrollCtrl.jumpTo(0);
      });
    }
  }

  /// Draggable のドラッグ位置 (global) から、 スクロール領域の左右端に
  /// 近ければオートスクロールを開始/更新する。
  void _handleChildDragUpdate(Offset globalPos) {
    final box = _scrollAreaKey.currentContext?.findRenderObject() as RenderBox?;
    if (box == null || !_scrollCtrl.hasClients) {
      _autoScrollDir = 0.0;
      return;
    }
    final origin = box.localToGlobal(Offset.zero);
    final rect = origin & box.size;
    const edge = 48.0; // 端から 48px 以内でスクロール開始
    if (globalPos.dx < rect.left + edge) {
      _autoScrollDir = -1.0;
    } else if (globalPos.dx > rect.right - edge) {
      _autoScrollDir = 1.0;
    } else {
      _autoScrollDir = 0.0;
    }
    if (_autoScrollDir != 0.0) {
      _autoScrollTimer ??=
          Timer.periodic(const Duration(milliseconds: 16), (_) {
        if (!_scrollCtrl.hasClients || _autoScrollDir == 0.0) return;
        final next = (_scrollCtrl.offset + _autoScrollDir * 10.0)
            .clamp(0.0, _scrollCtrl.position.maxScrollExtent);
        _scrollCtrl.jumpTo(next);
      });
    } else {
      _stopAutoScroll();
    }
  }

  void _stopAutoScroll() {
    _autoScrollTimer?.cancel();
    _autoScrollTimer = null;
    _autoScrollDir = 0.0;
  }

  void _handlePointerSignal(PointerSignalEvent event) {
    if (event is! PointerScrollEvent || !_scrollCtrl.hasClients) return;
    final delta = event.scrollDelta.dx.abs() > event.scrollDelta.dy.abs()
        ? event.scrollDelta.dx
        : event.scrollDelta.dy;
    if (delta == 0) return;
    final next = (_scrollCtrl.offset + delta)
        .clamp(0.0, _scrollCtrl.position.maxScrollExtent)
        .toDouble();
    _scrollCtrl.jumpTo(next);
  }

  MindMapProvider get provider => widget.provider;
  List<String>? get buttonIds => widget.buttonIds;
  bool get reorderMode => widget.reorderMode;
  bool get fullWidth => widget.fullWidth;
  Widget? get trailing => widget.trailing;
  double? get maxWidth => widget.maxWidth;
  String? get desktopPlacement => widget.desktopPlacement;
  void Function(int, int)? get onReorder => widget.onReorder;

  @override
  Widget build(BuildContext context) {
    final rawButtons = buttonIds ?? provider.customHeaderButtons;
    final buttons = <String>[];
    final sourceIndices = <int>[];
    for (int i = 0; i < rawButtons.length; i++) {
      final id = rawButtons[i];
      if (_MindMapScreenState._isRetiredCustomCommand(id)) continue;
      // IC カード残高は Android 版かつ日本語 UI の時だけ表示。
      if (id == 'icCardBalance' &&
          (kIsWeb || !Platform.isAndroid || provider.appLanguage != 'ja')) {
        continue;
      }
      buttons.add(id);
      sourceIndices.add(i);
    }
    if (buttons.isEmpty && trailing == null) return const SizedBox.shrink();
    // AppBar 内で利用可能な残り幅を計算。
    // 右側のメニューボタン (⋮) や「隠れたアクション」の > 矢印が出る分を
    // 確保する必要がある。
    // - 通常モード: 約 180px
    // - 並び替えモード: 枠線とマージンが付いてアイコン自体が膨らむため、
    //   右側に一層余裕が必要。200px + 枠のぶん 20px ＝ 220px 引く
    final screenW = MediaQuery.of(context).size.width;
    final availableW = (maxWidth ?? screenW).clamp(0.0, screenW).toDouble();
    // ★ 起動ハング対策 ★
    // 初回レイアウト時は width が 0 になることがある (ログの "Width is zero")。
    //   その状態で下の clamp(96.0, screenW) をそのまま使うと、 下限(96)>上限(0)
    //   で ArgumentError が投げられ、 ヘッダーの build が毎フレーム失敗 →
    //   AppBar がサイズ確定できず幅0のまま再 build を繰り返して固まる
    //   (= 起動が「読み込み中」 のまま動かなくなる) 原因になっていた。
    //   幅が確定する (96px 以上になる) まではヘッダーボタンを描画しない。
    if (availableW < 96.0) return const SizedBox.shrink();
    final rightReserve =
        (fullWidth || maxWidth != null) ? 0.0 : (reorderMode ? 220.0 : 180.0);
    final double maxAvailable = fullWidth
        ? availableW
        : (availableW - rightReserve).clamp(96.0, availableW).toDouble();
    // 並び替えモード中は各アイコンに枠 (2px × 2 + margin 2px × 2 = 8px)
    // と振動アニメのための若干の余白が加わるため、1 アイコンあたりの幅を
    // 48 → 58 に上げる。これをしないとアイコン側が膨らんだぶん右側メニュー
    // ボタンが画面外に押し出されてしまう。
    final double perBtnW = reorderMode ? 58.0 : _kHeaderCustomButtonExtent;
    final desktopGapCount =
        desktopPlacement == null || buttons.isEmpty ? 0 : buttons.length + 1;
    final double rawButtonsW = buttons.length * perBtnW +
        desktopGapCount * _kDesktopHeaderInsertionGapExtent +
        (trailing == null ? 0.0 : perBtnW);
    final double endPadW = rawButtonsW > maxAvailable ? 56.0 : 0.0;
    final desiredW = rawButtonsW + endPadW;
    final double w =
        fullWidth ? maxAvailable : desiredW.clamp(0.0, maxAvailable).toDouble();

    // ★ すべてのボタンを同じ 48px 四方の枠に「はみ出させずに」 収める
    //   (= ユーザー報告: ボタンの配置が歪に見える)。 中身の自然サイズが
    //   44px だったり 48px だったりすると等間隔にならないので、
    //   FittedBox で枠に合わせてから中央に置く。
    Widget buttonSlot(Widget child) => SizedBox(
          width: _kHeaderCustomButtonExtent,
          height: _kHeaderCustomButtonExtent,
          child: Center(
            child: FittedBox(
              fit: BoxFit.scaleDown,
              child: child,
            ),
          ),
        );

    Widget insertionGap(String? beforeCommandId) {
      return _DesktopHeaderInsertionGap(
        barAxis: Axis.horizontal,
        placement: desktopPlacement!,
        beforeCommandId: beforeCommandId,
        active: widget.activeDesktopButtonDrag?.sourcePlacement ==
                desktopPlacement &&
            widget.activeDesktopButtonDrag?.commandId != beforeCommandId,
        onDragEnded: () {
          _stopAutoScroll();
          widget.onDesktopButtonDragEnded?.call();
        },
        onDropped: (data) {
          unawaited(provider.moveDesktopHeaderButtonToPlacement(
            data.commandId,
            desktopPlacement!,
            beforeCommandId: beforeCommandId,
          ));
        },
      );
    }

    final row = Row(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        if (desktopPlacement != null && buttons.isNotEmpty)
          insertionGap(buttons.first),
        for (int i = 0; i < buttons.length; i++) ...[
          Builder(builder: (_) {
            final id = buttons[i];
            final btn = widget.buildButton(id, provider);
            if (btn == null) return const SizedBox.shrink();
            // PCは通常表示中もボタン自体をドラッグできる。短いクリックは子の
            // IconButtonへそのまま届き、ドラッグが成立した時だけ別バー移動になる。
            if (!reorderMode) {
              final slot = buttonSlot(btn);
              if (desktopPlacement == null) return slot;
              final data = _DesktopHeaderButtonDragData(id, desktopPlacement!);
              return _DesktopDraggableHeaderIcon(
                data: data,
                onDragStarted: () =>
                    widget.onDesktopButtonDragStarted?.call(data),
                onDragUpdate: _handleChildDragUpdate,
                onDragEnded: () {
                  _stopAutoScroll();
                  widget.onDesktopButtonDragEnded?.call();
                },
                child: slot,
              );
            }
            // 並び替えモード: 振動アニメと点線枠で視覚フィードバック、
            // Draggable + DragTarget でドラッグ交換を実現。
            return _ReorderableHeaderIcon(
              index: i,
              id: id,
              desktopSourcePlacement: desktopPlacement,
              child: buttonSlot(btn),
              // ドラッグ位置を親へ通知して端でオートスクロールさせる
              // (= ユーザー要望: ドラッグに合わせて画面が追跡)。
              onDragUpdateGlobal: _handleChildDragUpdate,
              onDragEndGlobal: _stopAutoScroll,
              onDragStartedGlobal: (data) {
                if (data is _DesktopHeaderButtonDragData) {
                  widget.onDesktopButtonDragStarted?.call(data);
                }
              },
              onDesktopDragEnded: widget.onDesktopButtonDragEnded,
              onDropped: (fromIndex) {
                if (onReorder != null && fromIndex != i) {
                  final fromSource =
                      fromIndex >= 0 && fromIndex < sourceIndices.length
                          ? sourceIndices[fromIndex]
                          : fromIndex;
                  onReorder!(fromSource, sourceIndices[i]);
                }
              },
            );
          }),
          if (desktopPlacement != null)
            insertionGap(i + 1 < buttons.length ? buttons[i + 1] : null),
        ],
        if (trailing != null) buttonSlot(trailing!),
        if (endPadW > 0) SizedBox(width: endPadW),
      ],
    );

    return SizedBox(
      key: _scrollAreaKey,
      height: _kHeaderCustomBarHeight,
      width: w,
      child: ClipRect(
        child: Listener(
          onPointerSignal: _handlePointerSignal,
          child: desiredW <= w
              ? Align(alignment: Alignment.center, child: row)
              : Scrollbar(
                  controller: _scrollCtrl,
                  // ヘッダー移動中だけ浮かび、操作を止めるとフェードアウトする。
                  // アプリ全体の Theme は常時表示なので false を局所指定する。
                  thumbVisibility: false,
                  child: SingleChildScrollView(
                    key: PageStorageKey<String>(
                      widget.storageKey ??
                          (buttonIds == null
                              ? 'header_custom_buttons_bar_normal'
                              : 'header_custom_buttons_bar_gallery'),
                    ),
                    controller: _scrollCtrl,
                    scrollDirection: Axis.horizontal,
                    physics: const ClampingScrollPhysics(),
                    child: row,
                  ),
                ),
        ),
      ),
    );
  }
}

/// 並び替えモード中のヘッダーアイコン wrap。
/// - 左右に微妙に振動するアニメで「動かせる」と伝える
/// - 点線枠でドラッグターゲットであることを示す
/// - LongPress ではなく通常タップドラッグで動かせる
/// - 他のアイコンに重ねると _onDropped(fromIndex) がその slot のインデックスで呼ばれる
class _ReorderableHeaderIcon extends StatefulWidget {
  final int index;
  final String id;
  final Widget child;
  final void Function(int fromIndex) onDropped;
  final String? desktopSourcePlacement;
  final void Function(_DesktopHeaderButtonDragData data)? onDragStartedGlobal;
  final VoidCallback? onDesktopDragEnded;

  /// ドラッグ中の位置 (global) を親バーへ通知する (= 端でのオートスクロール用)。
  final void Function(Offset globalPos)? onDragUpdateGlobal;
  final VoidCallback? onDragEndGlobal;
  const _ReorderableHeaderIcon({
    required this.index,
    required this.id,
    required this.child,
    required this.onDropped,
    this.desktopSourcePlacement,
    this.onDragStartedGlobal,
    this.onDesktopDragEnded,
    this.onDragUpdateGlobal,
    this.onDragEndGlobal,
  });
  @override
  State<_ReorderableHeaderIcon> createState() => _ReorderableHeaderIconState();
}

class _ReorderableHeaderIconState extends State<_ReorderableHeaderIcon>
    with SingleTickerProviderStateMixin {
  late final AnimationController _wiggleCtrl;
  late final Animation<double> _wiggle;

  @override
  void initState() {
    super.initState();
    _wiggleCtrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 160),
    )..repeat(reverse: true);
    _wiggle = Tween(begin: -0.04, end: 0.04).animate(
      CurvedAnimation(parent: _wiggleCtrl, curve: Curves.easeInOut),
    );
  }

  @override
  void dispose() {
    _wiggleCtrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    // 内側の Widget (ヘッダーアイコン) のタップを一切無効化する。
    // これがないと、アイコンをクリック (長押しせず離した) だけで
    // 下の InkWell が反応してコマンドが実行されてしまう。
    // AbsorbPointer は Draggable の上位で動く gesture には影響しない
    // ため、ドラッグはそのまま効く。
    final absorbedChild = AbsorbPointer(
      absorbing: true,
      child: widget.child,
    );
    final desktopData = widget.desktopSourcePlacement == null
        ? null
        : _DesktopHeaderButtonDragData(
            widget.id, widget.desktopSourcePlacement!);
    final Object dragData = desktopData ?? widget.index;

    bool canAccept(Object data) {
      // PC の各ドックには専用の挿入ギャップがあるため、アイコン本体は
      // ドロップ候補にしない。従来のモバイル並び替えだけを維持する。
      if (desktopData != null) return false;
      return data is int && data != widget.index;
    }

    void finishDrag() {
      widget.onDragEndGlobal?.call();
      if (desktopData != null) widget.onDesktopDragEnded?.call();
    }

    void accept(Object data) {
      if (desktopData == null && data is int) widget.onDropped(data);
    }

    return DragTarget<Object>(
      onWillAcceptWithDetails: (d) => canAccept(d.data),
      onAcceptWithDetails: (d) => accept(d.data),
      builder: (ctx, candidateData, rejectedData) {
        final isHovered = candidateData.isNotEmpty;
        return Draggable<Object>(
          data: dragData,
          dragAnchorStrategy: pointerDragAnchorStrategy,
          onDragStarted: () {
            if (desktopData != null) {
              widget.onDragStartedGlobal?.call(desktopData);
            }
          },
          onDragUpdate: (d) =>
              widget.onDragUpdateGlobal?.call(d.globalPosition),
          onDragEnd: (_) => finishDrag(),
          onDragCompleted: finishDrag,
          onDraggableCanceled: (_, __) => finishDrag(),
          feedback: Material(
            color: Colors.transparent,
            child: Opacity(opacity: 0.85, child: absorbedChild),
          ),
          childWhenDragging: Opacity(opacity: 0.2, child: absorbedChild),
          child: AnimatedBuilder(
            animation: _wiggle,
            builder: (_, child) {
              return Transform.rotate(angle: _wiggle.value, child: child);
            },
            child: Container(
              margin: const EdgeInsets.symmetric(horizontal: 2),
              decoration: BoxDecoration(
                border: Border.all(
                  color: isHovered
                      ? const Color(0xFFFFB347)
                      : const Color(0xFFFFB347).withValues(alpha: 0.4),
                  width: isHovered ? 2.0 : 1.0,
                ),
                borderRadius: BorderRadius.circular(10),
              ),
              child: absorbedChild,
            ),
          ),
        );
      },
    );
  }
}

