class _AiCountSelector extends StatefulWidget {
  final int value;
  final int min;
  final int max;
  final ValueChanged<int> onChanged;
  const _AiCountSelector({
    required this.value,
    required this.min,
    required this.max,
    required this.onChanged,
  });
  @override
  State<_AiCountSelector> createState() => _AiCountSelectorState();
}

class _AiCountSelectorState extends State<_AiCountSelector> {
  late TextEditingController _ctrl;
  bool _editing = false;

  @override
  void initState() {
    super.initState();
    _ctrl = TextEditingController(text: '${widget.value}');
  }

  @override
  void didUpdateWidget(covariant _AiCountSelector old) {
    super.didUpdateWidget(old);
    if (!_editing && widget.value != old.value) {
      _ctrl.text = '${widget.value}';
    }
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  void _applyInput() {
    final parsed = int.tryParse(_ctrl.text.trim());
    int v = parsed ?? widget.value;
    if (v < widget.min) v = widget.min;
    if (v > widget.max) v = widget.max;
    _ctrl.text = '$v';
    _editing = false;
    if (v != widget.value) widget.onChanged(v);
  }

  @override
  Widget build(BuildContext context) {
    return Row(mainAxisSize: MainAxisSize.min, children: [
      GestureDetector(
        onTap: widget.value > widget.min
            ? () => widget.onChanged(widget.value - 1)
            : null,
        child: Container(
          width: 28,
          height: 28,
          decoration: BoxDecoration(
            color: widget.value > widget.min
                ? Colors.white.withValues(alpha: 0.1)
                : Colors.white.withValues(alpha: 0.03),
            borderRadius: BorderRadius.circular(6),
          ),
          child: Icon(Icons.remove,
              size: 16,
              color:
                  widget.value > widget.min ? Colors.white70 : Colors.white24),
        ),
      ),
      SizedBox(
        width: 44,
        height: 28,
        child: TextField(
          controller: _ctrl,
          keyboardType: TextInputType.number,
          textAlign: TextAlign.center,
          style: const TextStyle(
              color: Colors.white, fontSize: 14, fontWeight: FontWeight.bold),
          decoration: InputDecoration(
            isDense: true,
            contentPadding: const EdgeInsets.symmetric(vertical: 4),
            filled: true,
            fillColor: Colors.white.withValues(alpha: 0.05),
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(6),
              borderSide: BorderSide.none,
            ),
          ),
          onTap: () => _editing = true,
          onChanged: (_) => _editing = true,
          onEditingComplete: _applyInput,
          onSubmitted: (_) => _applyInput(),
          onTapOutside: (_) {
            if (_editing) _applyInput();
          },
        ),
      ),
      GestureDetector(
        onTap: widget.value < widget.max
            ? () => widget.onChanged(widget.value + 1)
            : null,
        child: Container(
          width: 28,
          height: 28,
          decoration: BoxDecoration(
            color: widget.value < widget.max
                ? Colors.white.withValues(alpha: 0.1)
                : Colors.white.withValues(alpha: 0.03),
            borderRadius: BorderRadius.circular(6),
          ),
          child: Icon(Icons.add,
              size: 16,
              color:
                  widget.value < widget.max ? Colors.white70 : Colors.white24),
        ),
      ),
    ]);
  }
}

