class _Btn extends StatelessWidget {
  final IconData icon;
  final String label;
  final Color color;
  final double size;
  final double? width;
  final VoidCallback onTap;
  final VoidCallback? onLongPress;

  /// アイコンの代わりに自前描画のグリフを使う場合に指定する
  /// (= ユーザー要望: 方向を実際の本数の矢印で描くため)。 引数は表示色。
  final Widget Function(Color color)? iconBuilder;

  /// 右上に出す小さな印 (= ユーザー要望: 右クリックするまで切り替えられること
  /// 自体に気付かない)。
  ///
  /// ★ 印には**切り替えた先のアイコン**をそのまま出す (= ユーザー要望: ←→ では
  ///   何に変わるか分からない)。 例えば「リンク」 の時は添付のクリップ、
  ///   「予定登録」 の時はカードの印が出る。 AI のように右クリックで設定画面が
  ///   開くボタンには歯車を渡す。 null なら印を出さない。
  final IconData? badgeIcon;

  /// 印の下地の色。 既定は暗い灰色。 切替先を色でも示したい時に使う。
  final Color? badgeColor;
  const _Btn(
      {required this.icon,
      required this.label,
      required this.color,
      required this.size,
      this.width,
      required this.onTap,
      this.onLongPress,
      this.iconBuilder,
      this.badgeIcon,
      this.badgeColor});
  @override
  Widget build(BuildContext context) {
    // ラベル幅は呼び出し側が width で指定する (アクションバーは画面幅から
    // 均等割りした幅を渡してくる)。 未指定はアイコン幅。 文字は小さめにして
    // 1 行に収まる文字数を稼ぐ (= ユーザー要望: 複数行に跨らず、 詰めて表示)。
    final boxWidth = width ?? size;
    final labelFontSize = boxWidth > size * 1.4 ? 10.0 : 9.0;
    return GestureDetector(
      onTap: onTap,
      onLongPress: onLongPress,
      child: SizedBox(
        // 各ボタンの幅を `size` (= btnSize) で固定する。
        // これにより英語等の長いラベル ("Add to cal."、"Collapse" 等) が
        // 横に広がってアクションバー全体が画面外に押し出されるのを防ぐ。
        // ラベルは ellipsis で切り詰め。アイコン自体 (= タップターゲット)
        // は常に円形で見えているので、ラベルが切れても用途は分かる。
        width: boxWidth,
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Stack(clipBehavior: Clip.none, children: [
            Container(
              width: size,
              height: size,
              decoration: BoxDecoration(
                color: color,
                shape: BoxShape.circle,
                border: Border.all(color: Colors.white, width: 2),
                boxShadow: [
                  BoxShadow(
                      color: color.withValues(alpha: 0.55),
                      blurRadius: 8,
                      offset: const Offset(0, 3))
                ],
              ),
              child: iconBuilder != null
                  ? Center(child: iconBuilder!(Colors.white))
                  : Icon(icon, color: Colors.white, size: size * 0.44),
            ),
            // ── 右上の小さな印 (= ユーザー要望) ──
            //   切り替えられるボタンは**切替先のアイコン**を出すので、 押す前に
            //   何に変わるか分かる。 AI のように設定画面が開くボタンは歯車。
            //   印そのものは押せない (下のボタンに操作を通す)。
            if (badgeIcon != null)
              Positioned(
                right: -2,
                top: -2,
                child: IgnorePointer(
                  child: Container(
                    width: size * 0.38,
                    height: size * 0.38,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color: badgeColor ?? const Color(0xFF263238),
                      shape: BoxShape.circle,
                      border: Border.all(color: Colors.white, width: 1.2),
                    ),
                    child: Icon(badgeIcon,
                        color: Colors.white, size: size * 0.24),
                  ),
                ),
              ),
          ]),
          const SizedBox(height: 4),
          Text(label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              textAlign: TextAlign.center,
              style: TextStyle(
                  color: Colors.white,
                  fontSize: labelFontSize,
                  fontWeight: FontWeight.w700,
                  shadows: const [
                    Shadow(
                      color: Colors.black87,
                      blurRadius: 3,
                      offset: Offset(0, 1),
                    ),
                  ])),
        ]),
      ),
    );
  }
}

