class _ToolBarBtn extends StatelessWidget {
  final IconData icon;

  /// 指定された場合は `icon` の代わりにこの Widget を描画する
  /// (例: DeepSeek のクジラ `_WhaleIcon`)。 IconData で表現できない
  /// 自前描画アイコン用。
  final Widget? iconWidget;
  final String label;
  final Color color;
  final VoidCallback onTap;

  /// モバイル版のフッターボタン長押しで「ボタンを差し替え/削除」メニューを
  /// 開くために使用 (省略可)。null なら長押しは無効。
  final VoidCallback? onLongPress;

  /// PC 版の右クリック (= マウス Secondary tap)。 カスタムページボタンの
  /// 編集メニュー等で使用。 null なら右クリック無効。
  final VoidCallback? onSecondaryTap;

  /// 押された瞬間に、 その画面座標とボタン自身の BuildContext を知らせる。
  /// 設定メニューを「押したボタンの近く」 に出すために使う (= ユーザー要望)。
  final void Function(Offset pos, BuildContext btnCtx)? onPressRecord;
  const _ToolBarBtn({
    required this.icon,
    this.iconWidget,
    required this.label,
    required this.color,
    required this.onTap,
    this.onLongPress,
    this.onSecondaryTap,
    this.onPressRecord,
  });
  @override
  Widget build(BuildContext context) {
    final provider = context.watch<MindMapProvider>();
    final baseBg = Color.alphaBlend(
      provider.headerColor
          .withValues(alpha: provider.hasCustomHeaderColor ? 0.88 : 0.78),
      const Color(0xFF1A1A2E),
    );
    return Listener(
      // gesture arena に参加しない Listener なので、 下の GestureDetector の
      // タップ / 長押し判定を邪魔しない。
      onPointerDown: onPressRecord == null
          ? null
          : (e) => onPressRecord!(e.position, context),
      child: GestureDetector(
      onTap: onTap,
      onLongPress: onLongPress,
      onSecondaryTap: onSecondaryTap,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Container(
            width: 34,
            height: 34,
            decoration: BoxDecoration(
              color: baseBg,
              borderRadius: BorderRadius.circular(10),
              border: Border.all(color: color.withValues(alpha: 0.55)),
              boxShadow: [
                BoxShadow(
                  color: baseBg.withValues(alpha: 0.35),
                  blurRadius: 6,
                  offset: const Offset(0, 2),
                ),
              ],
            ),
            child: iconWidget ?? Icon(icon, color: color, size: 17),
          ),
          const SizedBox(height: 2),
          // ラベルは横幅に収まるよう縮小して全文表示する (= ユーザー要望:
          //   「フラッシュカード」 等の長いラベルが切れて見栄えが悪い → 省略
          //   せずに縮めて全部見せる)。 短いラベルは fontSize 8 のまま。
          FittedBox(
            fit: BoxFit.scaleDown,
            alignment: Alignment.center,
            child: Text(label,
                maxLines: 1,
                softWrap: false,
                textAlign: TextAlign.center,
                style: TextStyle(
                    color: Colors.white.withValues(alpha: 0.5),
                    fontSize: 8,
                    fontWeight: FontWeight.w600)),
          ),
        ],
      ),
    ),
    );
  }
}

// ─── DeepSeek 用「クジラ」アイコン ───────────────────────────────────────────
// DeepSeek 公式ロゴはクジラ。 Material Icons にクジラが無いため自前で描画する。
// `Icon` と同様に正方形 [size] に収まり [color] 単色で塗られるので、 白背景の
// 丸ボタン (白クジラ) でもヘッダーの透明背景 (青クジラ) でも自然に馴染む。
class _WhaleIcon extends StatelessWidget {
  final Color color;
  final double size;
  const _WhaleIcon({required this.color, this.size = 20});
  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: size,
      height: size,
      child: CustomPaint(painter: _WhalePainter(color)),
    );
  }
}

class _WhalePainter extends CustomPainter {
  final Color color;
  const _WhalePainter(this.color);
  @override
  void paint(Canvas canvas, Size size) {
    // 24x24 の座標系で設計し、 実サイズへ等倍スケール。 頭が左・尾が右の横向き。
    final double s = size.width / 24.0;
    canvas.save();
    canvas.scale(s, s);

    final fill = Paint()
      ..color = color
      ..style = PaintingStyle.fill
      ..isAntiAlias = true;
    final stroke = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.4
      ..strokeCap = StrokeCap.round
      ..isAntiAlias = true;

    // ── 体 + 尾びれ ──
    final body = Path()
      ..moveTo(3.2, 13.4) // 口先 (左下)
      ..cubicTo(2.0, 9.6, 5.0, 7.3, 9.4, 7.3) // 顔 → 頭頂
      ..cubicTo(12.8, 7.3, 15.6, 8.2, 18.0, 9.5) // 背中 → 尾の付け根
      ..lineTo(21.8, 6.6) // 上の尾びれ先端
      ..quadraticBezierTo(19.8, 11.6, 22.0, 15.6) // 尾びれの切れ込み
      ..lineTo(17.6, 12.9) // 下の尾びれ付け根
      ..cubicTo(13.6, 16.4, 6.6, 16.8, 3.2, 13.4) // 腹 → 口先へ戻る
      ..close();
    canvas.drawPath(body, fill);

    // ── 潮吹き (頭頂の噴気孔から上へ V 字に) ──
    canvas.drawLine(const Offset(7.6, 6.9), const Offset(6.3, 3.4), stroke);
    canvas.drawLine(const Offset(8.6, 6.9), const Offset(9.2, 3.6), stroke);

    canvas.restore();
  }

  @override
  bool shouldRepaint(_WhalePainter old) => old.color != color;
}

// ─── PC版右クリックメニュー アイテム ─────────────────────────────────────────

class _CtxMenuItem extends StatefulWidget {
  final IconData icon;
  final String label;
  final Color color;
  final VoidCallback onTap;

  /// 押すと細かい設定が出る項目か。 null なら普通の項目。
  /// true = 開いている / false = 閉じている (= ユーザー要望: 「画面分割」 を
  /// 左クリックすると、 元の項目を出したまま割り方が出てくるように)。
  final bool? expanded;

  /// 設定を「右に」 出す項目か (= ユーザー要望)。 印を ＞ にする。
  final bool expandRight;
  const _CtxMenuItem({
    super.key,
    required this.icon,
    required this.label,
    required this.color,
    required this.onTap,
    this.expanded,
    this.expandRight = false,
  });
  @override
  State<_CtxMenuItem> createState() => _CtxMenuItemState();
}

class _CtxMenuItemState extends State<_CtxMenuItem> {
  bool _hovered = false;
  @override
  Widget build(BuildContext context) {
    return MouseRegion(
      onEnter: (_) => setState(() => _hovered = true),
      onExit: (_) => setState(() => _hovered = false),
      child: GestureDetector(
        onTap: widget.onTap,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 80),
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 9),
          decoration: BoxDecoration(
            color: _hovered
                ? widget.color.withValues(alpha: 0.15)
                : Colors.transparent,
            borderRadius: BorderRadius.circular(8),
          ),
          child: Row(children: [
            Container(
              width: 24,
              height: 24,
              decoration: BoxDecoration(
                color: widget.color.withValues(alpha: 0.2),
                shape: BoxShape.circle,
              ),
              child: Icon(widget.icon, color: widget.color, size: 14),
            ),
            const SizedBox(width: 6),
            Expanded(
              child: Text(widget.label,
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(color: Colors.white, fontSize: 11)),
            ),
            // 「押すと設定が出る」 印 (右に出す時は ＞)。
            if (widget.expanded != null)
              Icon(
                  widget.expandRight
                      ? Icons.chevron_right_rounded
                      : (widget.expanded!
                          ? Icons.expand_less_rounded
                          : Icons.expand_more_rounded),
                  size: 16,
                  color: widget.expanded!
                      ? const Color(0xFF4FC3F7)
                      : Colors.white.withValues(alpha: 0.5)),
          ]),
        ),
      ),
    );
  }
}

/// 右クリックメニューの「画面分割」 にぶら下がる割り方の行
/// (= ユーザー要望: 左クリックで元の項目を出したまま 2〜4 分割の設定が
/// 出てくるように)。 一段下げて出し、 今の割り方にはチェックを付ける。
