// ─── PC版右クリックメニュー トグル項目（チェックマーク付き） ───────────────

class _CtxMenuToggle extends StatefulWidget {
  final IconData icon;
  final String label;
  final Color color;
  final bool checked;
  final VoidCallback onTap;
  const _CtxMenuToggle({
    required this.icon,
    required this.label,
    required this.color,
    required this.checked,
    required this.onTap,
  });
  @override
  State<_CtxMenuToggle> createState() => _CtxMenuToggleState();
}

class _CtxMenuToggleState extends State<_CtxMenuToggle> {
  bool _hovered = false;
  @override
  Widget build(BuildContext context) {
    return MouseRegion(
      onEnter: (_) => setState(() => _hovered = true),
      onExit: (_) => setState(() => _hovered = false),
      child: GestureDetector(
        onTap: widget.onTap,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 80),
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 9),
          decoration: BoxDecoration(
            color: _hovered
                ? widget.color.withValues(alpha: 0.15)
                : Colors.transparent,
            borderRadius: BorderRadius.circular(8),
          ),
          child: Row(children: [
            Container(
              width: 24,
              height: 24,
              decoration: BoxDecoration(
                color: widget.checked
                    ? widget.color.withValues(alpha: 0.25)
                    : Colors.white.withValues(alpha: 0.06),
                shape: BoxShape.circle,
              ),
              child: Icon(widget.icon,
                  color: widget.checked ? widget.color : Colors.white38,
                  size: 14),
            ),
            const SizedBox(width: 6),
            Expanded(
              child: Text(widget.label,
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                      color: widget.checked ? Colors.white : Colors.white60,
                      fontSize: 11)),
            ),
            if (widget.checked)
              Icon(Icons.check_rounded, color: widget.color, size: 14),
          ]),
        ),
      ),
    );
  }
}

// ─── PC版右クリックメニュー：ノード個別文字サイズリアルタイム調整 ──────────────

class _CtxButtonSection extends StatelessWidget {
  final String title;
  final IconData icon;
  final Color color;
  final List<Widget> children;
  final bool compact;

  /// 2 グループモード (= ユーザー要望: 「形状」と「伸ばせる方向」の仕切りを、
  /// 下の 2 列メニューの中央仕切りと同じ位置に揃える)。
  /// 両方指定すると children の代わりに [左グループ | 中央仕切り | 右グループ]
  /// のレイアウトになり、 仕切りが常にセクション中央 (= メニュー中央) に来る。
  final List<Widget>? leftChildren;
  final List<Widget>? rightChildren;
  const _CtxButtonSection({
    required this.title,
    required this.icon,
    required this.color,
    this.children = const [],
    this.compact = false,
    this.leftChildren,
    this.rightChildren,
  });

  @override
  Widget build(BuildContext context) {
    final useSingleCompactRow =
        compact && MediaQuery.sizeOf(context).width < 600;
    final twoGroups = leftChildren != null && rightChildren != null;

    Widget groupWrap(List<Widget> items) => useSingleCompactRow
        ? Row(
            children: [
              for (final child in items)
                Expanded(child: SizedBox(height: 38, child: child)),
            ],
          )
        : Wrap(
            spacing: compact ? 5 : 6,
            runSpacing: compact ? 5 : 6,
            alignment: WrapAlignment.center,
            children: [
              for (final child in items)
                SizedBox(
                    width: compact ? 42 : 96,
                    height: compact ? 38 : null,
                    child: child),
            ],
          );

    return Padding(
      padding: const EdgeInsets.fromLTRB(8, 8, 8, 4),
      child: Container(
        decoration: BoxDecoration(
          color: Colors.white.withValues(alpha: 0.035),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: Colors.white.withValues(alpha: 0.08)),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Padding(
              padding: EdgeInsets.fromLTRB(12, compact ? 8 : 10, 12, 4),
              child: Row(children: [
                Icon(icon, color: color, size: 15),
                const SizedBox(width: 7),
                Text(title,
                    style: const TextStyle(
                        color: Colors.white70,
                        fontSize: 11,
                        fontWeight: FontWeight.w700)),
              ]),
            ),
            Padding(
              padding: EdgeInsets.fromLTRB(8, compact ? 2 : 4, 8, 8),
              child: twoGroups
                  // 左右 2 グループ + 中央仕切り。 Expanded 半々なので仕切りが
                  // 常にセクション中央 = 下の 2 列メニューの仕切りと同じ X に揃う。
                  ? Row(
                      crossAxisAlignment: CrossAxisAlignment.center,
                      children: [
                        Expanded(child: groupWrap(leftChildren!)),
                        Container(
                          width: 1,
                          height: 28,
                          margin: const EdgeInsets.symmetric(horizontal: 2),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.22),
                            borderRadius: BorderRadius.circular(1),
                          ),
                        ),
                        Expanded(child: groupWrap(rightChildren!)),
                      ],
                    )
                  : useSingleCompactRow
                      // モバイルでは形状4個＋区切り＋方向3個を均等に詰め、
                      // 「8方向」だけが二段目へ落ちないよう必ず一段で表示する。
                      ? Row(
                          children: [
                            for (final child in children)
                              Expanded(
                                child: SizedBox(height: 38, child: child),
                              ),
                          ],
                        )
                      : Wrap(
                          spacing: compact ? 5 : 6,
                          runSpacing: compact ? 5 : 6,
                          children: [
                            for (final child in children)
                              SizedBox(
                                  width: compact ? 42 : 96,
                                  height: compact ? 38 : null,
                                  child: child),
                          ],
                        ),
            ),
          ],
        ),
      ),
    );
  }
}

class _CtxIconToggleButton extends StatelessWidget {
  final IconData icon;
  final String label;
  final Color color;
  final bool checked;
  final VoidCallback onTap;

  /// アイコンの代わりに自前描画のグリフを使う場合に指定する
  /// (= ユーザー要望: 8 方向を実際に 8 本の矢印で描くため)。
  /// 引数は「その時の表示色」。
  final Widget Function(Color color)? iconBuilder;

  const _CtxIconToggleButton({
    required this.icon,
    required this.label,
    required this.color,
    required this.checked,
    required this.onTap,
    this.iconBuilder,
  });

  @override
  Widget build(BuildContext context) {
    return Tooltip(
      message: label,
      waitDuration: const Duration(milliseconds: 350),
      child: InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(9),
        child: Container(
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: checked
                ? color.withValues(alpha: 0.22)
                : Colors.white.withValues(alpha: 0.045),
            borderRadius: BorderRadius.circular(9),
            border: Border.all(
              color: checked ? color : Colors.white.withValues(alpha: 0.10),
              width: checked ? 1.4 : 1,
            ),
          ),
          child: iconBuilder != null
              ? iconBuilder!(checked ? color : Colors.white70)
              : Icon(icon,
                  color: checked ? color : Colors.white70, size: 19),
        ),
      ),
    );
  }
}

/// リンクの伸ばせる方向を「実際に使える本数ぶんの矢印」 で描くグリフ
/// (= ユーザー要望: 8 方向のアイコンが実際と合っていないので、 ちゃんと
/// 8 方向のアイコンにする)。 2 方向 / 4 方向 / 斜め 4 方向 / 8 方向を
/// [anchorsForMode] からそのまま描くので、 表示と挙動が必ず一致する。
class _AnchorModeGlyph extends StatelessWidget {
  final NodeAnchorMode mode;
  final Color color;
  final double size;
  const _AnchorModeGlyph({
    required this.mode,
    required this.color,
    this.size = 19,
  });

  @override
  Widget build(BuildContext context) => SizedBox(
        width: size,
        height: size,
        child: CustomPaint(
          painter: _AnchorModeGlyphPainter(
            dirs: anchorsForMode(mode),
            color: color,
          ),
        ),
      );
}

class _AnchorModeGlyphPainter extends CustomPainter {
  final List<AnchorDirection> dirs;
  final Color color;
  _AnchorModeGlyphPainter({required this.dirs, required this.color});

  /// 方向 → 単位ベクトル (画面座標系: y は下が正)。
  Offset _unit(AnchorDirection d) {
    const double s = 0.7071; // 1/sqrt(2)
    switch (d) {
      case AnchorDirection.north:
        return const Offset(0, -1);
      case AnchorDirection.south:
        return const Offset(0, 1);
      case AnchorDirection.east:
        return const Offset(1, 0);
      case AnchorDirection.west:
        return const Offset(-1, 0);
      case AnchorDirection.northEast:
        return const Offset(s, -s);
      case AnchorDirection.northWest:
        return const Offset(-s, -s);
      case AnchorDirection.southEast:
        return const Offset(s, s);
      case AnchorDirection.southWest:
        return const Offset(-s, s);
    }
  }

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);
    final double r = math.min(size.width, size.height) / 2 - 1.0;
    // 本数が多いほど線を細くして潰れないようにする。
    final double sw = dirs.length >= 8 ? 1.15 : 1.5;
    final line = Paint()
      ..color = color
      ..strokeWidth = sw
      ..strokeCap = StrokeCap.round
      ..isAntiAlias = true
      ..style = PaintingStyle.stroke;
    final fill = Paint()
      ..color = color
      ..isAntiAlias = true
      ..style = PaintingStyle.fill;
    // 中心の点 (= ノード)。
    canvas.drawCircle(center, dirs.length >= 8 ? 1.5 : 1.8, fill);
    final double head = dirs.length >= 8 ? 2.6 : 3.2;
    for (final d in dirs) {
      final u = _unit(d);
      final tip = center + Offset(u.dx * r, u.dy * r);
      final start = center + Offset(u.dx * 2.6, u.dy * 2.6);
      canvas.drawLine(start, tip, line);
      // 矢じり (先端から手前へ 2 本のヒゲ)。
      final px = -u.dy, py = u.dx; // 垂直方向
      final base = tip - Offset(u.dx * head, u.dy * head);
      canvas.drawLine(
          tip, base + Offset(px * head * 0.55, py * head * 0.55), line);
      canvas.drawLine(
          tip, base - Offset(px * head * 0.55, py * head * 0.55), line);
    }
  }

  @override
  bool shouldRepaint(covariant _AnchorModeGlyphPainter old) =>
      old.color != color || old.dirs.length != dirs.length;
}

class _CtxFontSizeRow extends StatefulWidget {
  final String nodeId;
  final MindMapNode node;
  final MindMapProvider provider;
  final double defaultTitleFontSize;
  final double defaultMemoFontSize;
  const _CtxFontSizeRow({
    required this.nodeId,
    required this.node,
    required this.provider,
    required this.defaultTitleFontSize,
    required this.defaultMemoFontSize,
  });
  @override
  State<_CtxFontSizeRow> createState() => _CtxFontSizeRowState();
}

class _CtxFontSizeRowState extends State<_CtxFontSizeRow> {
  late double _titleFs;
  late double _memoFs;

  @override
  void initState() {
    super.initState();
    _titleFs = widget.node.titleFontSize ?? widget.defaultTitleFontSize;
    _memoFs = widget.node.memoFontSize ?? widget.defaultMemoFontSize;
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(widget.provider.t('ctx.fontSize'),
              style: const TextStyle(
                  color: Colors.white38,
                  fontSize: 10,
                  fontWeight: FontWeight.w600)),
          const SizedBox(height: 4),
          // ── 「タイトル」 行は削除 (= ユーザー要望: タイトルという項目自体が
          //    存在しない統合リッチテキストのため)。 文字サイズはメモ側に一本化。 ──
          Row(children: [
            const Icon(Icons.notes_rounded, color: Colors.white38, size: 13),
            const SizedBox(width: 3),
            const Text('M',
                style: TextStyle(color: Colors.white38, fontSize: 10)),
            Expanded(
              child: SliderTheme(
                data: SliderThemeData(
                  trackHeight: 2,
                  thumbShape:
                      const RoundSliderThumbShape(enabledThumbRadius: 5),
                  activeTrackColor: const Color(0xFF43B97F),
                  inactiveTrackColor: Colors.white.withValues(alpha: 0.1),
                  thumbColor: Colors.white,
                  overlayShape:
                      const RoundSliderOverlayShape(overlayRadius: 10),
                ),
                child: Slider(
                  value: _memoFs.clamp(6.0, 22.0),
                  min: 6,
                  max: 22,
                  onChanged: (v) {
                    setState(() => _memoFs = v);
                    widget.provider.updateNodeMemoFontSize(widget.nodeId, v);
                  },
                ),
              ),
            ),
            SizedBox(
              width: 24,
              child: Text('${_memoFs.round()}',
                  style: const TextStyle(
                      color: Color(0xFF43B97F),
                      fontSize: 10,
                      fontWeight: FontWeight.bold)),
            ),
          ]),
        ],
      ),
    );
  }
}

// ─── モバイル用 WebView シート（webview_flutter 使用） ────────────────────────
//
// Windows 版とは別に用意する理由:
//   - webview_windows は Android/iOS で動かない (デスクトップ専用)
//   - Android は webview_flutter でシステム WebView を呼ぶ
//   - MIUI/HyperOS の WebView 不具合に対応するため、UA は敢えて設定しない
//     (既定 UA の末尾 "wv" で YouTube がモバイル Web 版を返してくれる)
//   - intent:// へのリダイレクトは遮断 (Chrome アプリ起動ループ防止)
//   - onProgress ≥ 70% でスピナーを消す (YouTube は SPA で onPageFinished が来ない場合あり)

// (_WebViewSheet / _MobileWebViewSheet — 旧 webview_flutter ベースの
//  未使用実装を削除。flutter_inappwebview 版 _FullscreenVideoPage に統一済み)

// ─── Windows専用 WebView シート（webview_windows使用） ──────────────────────

/// _WindowsWebViewSheet の 1 タブ分の状態（URL / ページ名 / お気に入り保持）。
class _WinTab {
  String url;
  String title;
  bool pinned;
  _WinTab({required this.url, this.title = '', this.pinned = false});
}

/// 共有 WebView に対して最後に開始したナビゲーション。
///
/// WebView2 の URL/title/loading ストリームには要求 ID が含まれない。複数要求を
/// キューで推測すると、キャンセル済み要求の redirect を次のタブへ誤帰属させる
/// ため、同時に追跡する所有者は常に最新の 1 件だけにする。
class _WinTabNavigation {
  final _WinTab tab;
  final String requestedUrl;
  final int generation;

  const _WinTabNavigation(this.tab, this.requestedUrl, this.generation);
}

/// webview_windows には shouldOverrideUrlLoading が無いので、 ドキュメント生成時
/// に注入してリンクの Ctrl/⌘+クリック・中クリックを捕まえ、 既定の遷移を止めて
/// `window.chrome.webview.postMessage` で URL を Flutter 側へ渡す。 受け取った側は
/// 新しいタブ (バックグラウンド) に開く (= ユーザー要望: 検索中に Ctrl+クリックで
/// 新しいタブ)。
///
/// さらに **別ウィンドウで開こうとする遷移** (`target="_blank"` リンク /
/// `window.open`) も横取りして新しいタブへ回す (= ユーザー要望: YouTube から
/// 広告を開いてしまうと戻れなくなるので、 新規画面へ飛ぶときは新しいタブで
/// 開いて元の画面に戻れるようにする)。 従来はこれらを WebView2 の popup policy
/// (`sameWindow`) に任せていたため、 広告ページが *同じ* WebView を乗っ取り、
/// 履歴を潰す広告だと元の動画へ戻れなくなっていた。
const String _kCtrlClickInterceptorJs = r'''
(function(){
  if (window.__mmCtrlClickHook) return;
  window.__mmCtrlClickHook = true;
  function send(href, activate){
    try {
      window.chrome.webview.postMessage(
        JSON.stringify({t:'ctrlclick', url: href, fg: activate ? 1 : 0}));
    } catch(e){}
  }
  function usable(href){
    if (!href) return false;
    var s = String(href);
    return s.indexOf('http://') === 0 || s.indexOf('https://') === 0;
  }
  function anchorFrom(e){
    var n = e.target;
    while (n && n !== document) {
      if (n.tagName && n.tagName.toLowerCase() === 'a' && n.href) return n;
      n = n.parentNode;
    }
    return null;
  }
  function handle(e, isAux){
    if (isAux && e.button !== 1) return;
    var a = anchorFrom(e);
    if (!a) return;
    var ctrlish = e.ctrlKey || e.metaKey;
    var mid = isAux && e.button === 1;
    var blank = false;
    try { blank = String(a.target || '').toLowerCase() === '_blank'; } catch(err){}
    if (!ctrlish && !mid && !blank) return;
    var href = a.href;
    if (!usable(href) || String(href).indexOf('javascript:') === 0) return;
    e.preventDefault(); e.stopPropagation();
    // Ctrl/中クリック = 背面タブ (従来通り)、 target=_blank = 前面タブ
    // (= 普通のブラウザと同じ挙動で、 戻るときはタブを切り替えれば良い)。
    send(href, blank && !ctrlish && !mid);
  }
  document.addEventListener('click', function(e){ handle(e, false); }, true);
  document.addEventListener('auxclick', function(e){ handle(e, true); }, true);
  // ── window.open を新しいタブへ振り替える ──
  // 呼び出し元が戻り値のウィンドウを触っても落ちないよう、 無害なスタブを返す。
  try {
    var nativeOpen = window.open;
    window.open = function(u, name, features){
      try {
        var href = u ? new URL(String(u), document.baseURI).href : '';
        if (usable(href)) {
          send(href, true);
          return {
            closed: false,
            close: function(){ this.closed = true; },
            focus: function(){}, blur: function(){},
            postMessage: function(){},
            document: { write: function(){}, writeln: function(){}, close: function(){} },
            location: { href: href, replace: function(){}, assign: function(){} }
          };
        }
      } catch(e){}
      try { return nativeOpen.apply(window, arguments); } catch(e){ return null; }
    };
  } catch(e){}
})();
''';

/// webview_windows の webMessageReceived から受け取ったメッセージが Ctrl+クリック
/// / 別ウィンドウ遷移 由来なら、 その URL と「前面タブで開くか」 を返す。
/// それ以外は null。
({String url, bool foreground})? _parseCtrlClickWebMessage(dynamic msg) {
  try {
    dynamic data = msg;
    if (data is String) {
      final s = data.trim();
      if (!s.startsWith('{')) return null;
      data = jsonDecode(s);
    }
    if (data is Map && data['t'] == 'ctrlclick') {
      final u = (data['url'] ?? '').toString();
      if (u.isEmpty) return null;
      final fg = data['fg'];
      return (
        url: u,
        foreground: fg == 1 || fg == true || fg == '1',
      );
    }
  } catch (_) {}
  return null;
}

class _WindowsWebViewSheet extends StatefulWidget {
  final String url;
  final List<String> playlist;
  final int startIndex;
  final double initialRate;

  /// 現在表示中のURLをマップに埋め込むコールバック（null なら埋め込みボタン非表示）
  final void Function(String currentUrl)? onEmbedUrl;

  /// 動画ダウンロード完了時に呼ばれる。`record` は
  /// `_DownloadedVideosStore.add` に渡すのと同じ Map (path/title/sourceUrl/
  /// videoId/sizeBytes/downloadedAt/thumbPath)。
  /// null の場合は DL 後の自動埋め込みは行わない (DL 自体は可能)。
  final void Function(Map<String, dynamic> record)? onDownloadComplete;

  /// ヘッダーに表示するタイトルの初期値。ローカル mp4 のように
  /// `<title>` を持たない動画を再生する際、ファイル名ではなく動画本来の
  /// タイトル (例: YouTube タイトル) を表示するためにノード側から渡す。
  /// 渡されない場合はページの `<title>` から取得 (= 従来挙動)。
  final String? initialTitle;

  /// 現在の URL を画面分割パネルに移して表示するコールバック。
  /// null なら「画面分割へ」 ボタンは出ない (= 旧挙動)。
  final void Function(String currentUrl, {bool isLeftPanel})?
      onMoveToSplitPanel;

  /// 現在の URL をアプリ内の浮遊パネル (フローティング) に移すコールバック。
  /// null ならフローティング化ボタン非表示 (= ユーザー要望: YouTube にも
  /// フローティング機能)。
  final void Function(String currentUrl)? onFloatRequest;

  /// true の時、 過去のナビ履歴 (= 最後に開いた動画 URL) の復元を行わず、
  /// 必ず widget.url (= YouTube ホーム) から開始する。
  /// Ctrl+U / 「YouTube を開く」 ショートカット経由で true になる。
  final bool forceHome;

  /// true (= デフォルト) の時、 動画ページでフォーカスモード CSS
  /// (関連動画 / コメント / ヘッダー / 検索ボックス等を隠す) を注入する。
  /// ノードからの埋め込み再生は true、 「YouTubeを開く」 等のブラウズ起動は
  /// false で渡され、 ブラウズ時は素の YouTube UI を保つ
  /// (= ユーザー要望: 埋め込み状態でないのに勝手に CSS が消えるバグの修正)。
  final bool focusMode;

  /// PiP からフルスクリーンに戻った時などに、 ロード完了後に <video> をこの
  /// 秒数へシークする (= ユーザー要望: PiP→全画面で先頭に戻るバグの修正)。
  /// 0 (デフォルト) なら何もしない。 1 回だけ適用する (手動シークを上書きしない)。
  final double initialPosition;

  /// 分割ペインの中に開いている時、 窓いっぱいに広げるかどうか
  /// (= ユーザー要望: 分割で開いた YouTube を全画面にするボタンが欲しい)。
  /// [onToggleFullWindow] が null ならボタンを出さない (分割していない時)。
  final bool isFullWindow;
  final VoidCallback? onToggleFullWindow;
  const _WindowsWebViewSheet({
    required this.url,
    this.playlist = const [],
    this.startIndex = 0,
    this.initialRate = 1.0,
    this.onEmbedUrl,
    this.onDownloadComplete,
    this.initialTitle,
    this.onMoveToSplitPanel,
    this.onFloatRequest,
    this.forceHome = false,
    this.focusMode = true,
    this.initialPosition = 0.0,
    this.isFullWindow = false,
    this.onToggleFullWindow,
  });
  @override
  State<_WindowsWebViewSheet> createState() => _WindowsWebViewSheetState();
}

