  ///   GlobalKey を付けておくと、 Flutter は作り直さずに「引っ越し」 させる
  ///   ので、 中の WebView はそのまま生き残る。
  final GlobalKey _videoMemoSubtreeKey = GlobalKey(debugLabel: 'videoMemoPane');
  final GlobalKey _videoAiSubtreeKey = GlobalKey(debugLabel: 'videoAiPane');

  /// 「横に並べる」 モードでのパネル側の幅 (= ユーザー要望: PDF のように
  /// 横に配置)。 仕切りを掴んで変えられる。 左右それぞれ持つ。
  double _videoSidePanelWidth = 420;
  double _videoSidePanelWidthLeft = 380;

  /// メモ / AI 欄をどちら側に置くか (= ユーザー要望: 左右に分けたり、
  /// 右や左にまとめたり、 掴んで置き換えたり)。 'left' / 'right'。
  /// 既定は両方とも右 (= 今までの並び)。 prefs `videoPanelSides` に覚える。
  final Map<String, String> _videoPanelSide = {'memo': 'right', 'ai': 'right'};

  /// 同じ側に 2 つある時の並び順 (上から)。 掴んで入れ替えられる。
  List<String> _videoPanelOrder = ['memo', 'ai'];

  static const String _kVideoPanelSidesKey = 'videoPanelSides';

  Future<void> _loadVideoPanelSides() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kVideoPanelSidesKey);
      if (raw == null || raw.isEmpty) return;
      final m = jsonDecode(raw);
      if (m is! Map) return;
      final sides = m['sides'];
      if (sides is Map) {
        for (final k in const ['memo', 'ai']) {
          final v = '${sides[k] ?? ''}';
          if (v == 'left' || v == 'right') _videoPanelSide[k] = v;
        }
      }
      final order = m['order'];
      if (order is List && order.length == 2) {
        final o = order.map((e) => '$e').toList();
        if (o.contains('memo') && o.contains('ai')) _videoPanelOrder = o;
      }
      if (mounted) setState(() {});
    } catch (_) {}
  }

  Future<void> _saveVideoPanelSides() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(
          _kVideoPanelSidesKey,
          jsonEncode({
            'sides': _videoPanelSide,
            'order': _videoPanelOrder,
          }));
    } catch (_) {}
  }

  /// パネルを掴んで別の場所へ落とした時 (= ユーザー要望: ドラッグ＆ドロップ
  /// で配置位置を替えられるように)。 [target] は 'left' / 'right'、
  /// [before] にもう一方の id を渡すとその上に入る。
  void _moveVideoPanel(String id, String target, {String? before}) {
    if (id != 'memo' && id != 'ai') return;
    // ★ 掴んでいた物を離した「その場」 で組み直すと、 ドラッグの後片付けと
    //   WebView の引っ越しが重なる。 次のフレームまで待ってから動かす
    //   (= ユーザー報告: 動かすと固まる、 の対策)。
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _applyVideoPanelMove(id, target, before: before);
    });
  }

  void _applyVideoPanelMove(String id, String target, {String? before}) {
    setState(() {
      _videoPanelSide[id] = target == 'left' ? 'left' : 'right';
      final other = id == 'memo' ? 'ai' : 'memo';
      if (before == other) {
        _videoPanelOrder = [id, other];
      } else if (before != null) {
        _videoPanelOrder = [other, id];
      }
    });
    // ignore: discarded_futures
    _saveVideoPanelSides();
  }

  // ── 動画メモ / AI パネルの自由配置・折り畳み (= ユーザー要望: ⇄ をやめて
