  final List<_VideoMemoEntry> _videoMemos = [];

  /// 入力中のメモに貼り付けた画像 (= ユーザー要望: 動画メモで画像を
  /// 貼り付けておけるように)。 メモを一覧へ足した時に一緒に持って行く。
  String? _videoMemoDraftImage;
  late final Future<void> _videoMemoLoadFuture;
  // 旧 `_videoMemoIncludeTimestamp` トグルは廃止 (タイムスタンプフィールドの
  // 値の有無で時刻添付が決まるシンプルなロジックに変更)。
  /// 二重サブミット防止。
  bool _videoMemoSubmitting = false;

  // ── プレビュー用の現在再生位置 (Windows 版) ──
  // モバイル版と同じ目的: パネル開時にトグル隣に「[03:24]」 をリアルタイム
  // 表示し、 「再生位置も保存」 が実際に動いていることを視覚で確認できる。
  double _videoMemoPreviewSec = 0.0;
  Timer? _videoMemoPreviewTimer;

  // ── ユーザー指定タイムスタンプ (Windows 版) ──
  // モバイル版と同じ仕様: 編集可能な mm:ss フィールドで指定時刻を入れる。
  final TextEditingController _videoMemoTsCtrl = TextEditingController();
  bool _videoMemoTsManualOverride = false;
  final FocusNode _videoMemoTsFocus = FocusNode();

  /// メモ入力欄の FocusNode。 編集中に Enter (Shift 無し) を押すと、
  /// マップへは出さず独立したメモ項目として追加する。Shift+Enter は改行のまま。
  late final FocusNode _videoMemoFocus = FocusNode(onKeyEvent: (node, event) {
    if (event is KeyDownEvent &&
        !HardwareKeyboard.instance.isShiftPressed &&
        (event.logicalKey == LogicalKeyboardKey.enter ||
            event.logicalKey == LogicalKeyboardKey.numpadEnter)) {
      _winSaveVideoMemoLocally();
      return KeyEventResult.handled;
    }
    // ── Ctrl+V: クリップボードに画像があればマップに画像メモとして貼り付け
    //    (= ユーザー要望) ──。 画像が無ければ ignored を返し、 通常どおり
    //    テキストが入力欄に貼り付けられる。
    if (event is KeyDownEvent &&
        HardwareKeyboard.instance.isControlPressed &&
        event.logicalKey == LogicalKeyboardKey.keyV) {
      _winPasteMemoImageIfAny();
      return KeyEventResult.ignored;
    }
    return KeyEventResult.ignored;
  });

  /// タイムスタンプフィールドを「表示するか」 のトグル状態。
  /// false (= 非表示) がデフォルト。 ユーザーがアイコンボタンで切替え。
  /// 非表示の間は _videoMemoTsCtrl が空のままなので、 保存時にタイムスタンプは
  /// 含まれない (= 「タイムスタンプを含める機能」 が任意になる)。
  bool _winVideoMemoShowTimestamp = false;

  void _startWinVideoMemoPreviewTimer() {
    _videoMemoPreviewTimer?.cancel();
    () async {
      if (!mounted) return;
      final t = await _winGetCurrentVideoTimeSec();
      if (!mounted) return;
      setState(() => _videoMemoPreviewSec = t);
      _winMaybeUpdateTsCtrl();
    }();
    _videoMemoPreviewTimer =
        Timer.periodic(const Duration(milliseconds: 800), (_) async {
      if (!mounted) {
        _videoMemoPreviewTimer?.cancel();
        return;
      }
      final t = await _winGetCurrentVideoTimeSec();
      if (!mounted) return;
      if ((t - _videoMemoPreviewSec).abs() >= 0.5) {
        setState(() => _videoMemoPreviewSec = t);
        _winMaybeUpdateTsCtrl();
      }
    });
  }

  /// 自動追従中だけ TsCtrl の中身を更新。
  void _winMaybeUpdateTsCtrl() {
    // ── タイムスタンプ自動追従を停止 ──
    // ユーザー要望: 「リアルタイム表示し続けると目障りだから、 再生位置を
    // 含めるボタンを押した時だけ表示するようにして」
    // → タイマーからの自動更新は完全に廃止し、 値のセットは
    //   トグル ON 時の `_winResetVideoMemoTsToNow()` (= ユーザーが
    //   ボタンを押した瞬間) のみに限定する。
    return;
  }

  void _stopWinVideoMemoPreviewTimer() {
    _videoMemoPreviewTimer?.cancel();
    _videoMemoPreviewTimer = null;
  }

  /// 「現在時刻に戻す」 ボタンの処理 (Windows)。
  void _winResetVideoMemoTsToNow() {
    setState(() {
      _videoMemoTsManualOverride = false;
      _videoMemoTsCtrl.text = _winFormatTimestamp(_videoMemoPreviewSec);
    });
  }

  /// mm:ss / h:mm:ss / 秒 を秒数に解釈 (Windows 版、 モバイル版と同じロジック)。
  double? _winParseUserTimestamp(String raw) {
    final s = raw.trim().replaceAll('：', ':').replaceAll(' ', '');
    if (s.isEmpty) return null;
    final parts = s.split(':');
    try {
      if (parts.length == 1) {
        final n = double.tryParse(parts[0]);
        return n != null && n >= 0 ? n : null;
      } else if (parts.length == 2) {
        final m = int.parse(parts[0]);
        final ss = int.parse(parts[1]);
        if (m < 0 || ss < 0 || ss >= 60) return null;
        return (m * 60 + ss).toDouble();
      } else if (parts.length == 3) {
        final h = int.parse(parts[0]);
        final m = int.parse(parts[1]);
        final ss = int.parse(parts[2]);
        if (h < 0 || m < 0 || m >= 60 || ss < 0 || ss >= 60) return null;
        return (h * 3600 + m * 60 + ss).toDouble();
      }
    } catch (_) {
      return null;
    }
    return null;
  }

  // ─── ダウンロード中の URL ロック ────────────────────────────────────────
  // ダウンロード開始時の動画 URL を覚えておき、 ダウンロード中に YouTube の
  // 自動再生で別動画に遷移してしまったら強制的に元の URL に戻す。
  /// ダウンロード中の元 URL (= ロックする URL)。 null ならロック無効。
  String? _downloadingLockUrl;

  /// ダウンロード中に「自動的に戻した」 警告を 1 回だけ出すためのフラグ。
  bool _downloadAutoNavBackWarned = false;

  @override
  void initState() {
    super.initState();
    _playbackRate = widget.initialRate;
    _currentUrl = widget.url;
    // メモ / AI 欄の置き場所を思い出す (= ユーザー要望: 左右の配置を覚える)。
    // ignore: discarded_futures
    _loadVideoPanelSides();
    if (isSafeExternalServiceUrl(widget.url)) {
      _oauthLastSafeServiceUrl = widget.url;
    }
    _playlist = widget.playlist.isNotEmpty ? widget.playlist : [widget.url];
    _winTabs = [_WinTab(url: widget.url)]; // 最初のタブ = 現在開いている URL
    _winActiveTab = 0;
    _winDisplayedTab = _winTabs[0];
    // ブラウズ用途 (focusMode=false) のシートだけを「アクティブなタブ置き場」
    //   として登録する。 Ctrl+U / 動画を開く 時に、 既に開いているこのシートへ
    //   新しいタブとして追加するために使う (= ユーザー要望)。
    if (!widget.focusMode) activeBrowseInstance = this;
    // 最初のタブのタイトルを取得 (動画なら oEmbed でタイトルをタブに付ける)。
    _fetchAndSetTabTitle(_winTabs[0], widget.url);
    // Ctrl+W = タブを閉じる / Ctrl+Shift+T = 閉じたタブを復元 (ユーザー要望)。
    // webview がフォーカスを奪うとアプリ側にキーが届かないことがあるが、
    // Flutter 側にフォーカスがある間はこのハンドラで処理する。
    HardwareKeyboard.instance.addHandler(_handleWinTabHotkey);
    // お気に入り(保持)タブは常に復元 → その後で「前回のタブを復元しますか？」
    // を確認 (= ユーザー要望: Edge のような復元確認 / お気に入りは常に開く)。
    _winRestorePinnedTabs().then((_) {
      if (mounted) _winMaybePromptRestoreLastTabs();
    });
    // タブをドラッグした瞬間に受け皿を出せるよう、 フォルダー名を先に読む。
    unawaited(_winRefreshFolderNames());
    _playlistIndex = widget.startIndex.clamp(0, _playlist.length - 1);
    // 動画タイトルの初期表示を呼び出し側 (ノードのタイトル等) からもらえる
    // 場合はそれを使う。HTML の <title> も埋めておき、ロード完了時の
    // DOM snapshot から同じ文字列を安全にタブへ確定する。
    if (widget.initialTitle != null && widget.initialTitle!.isNotEmpty) {
      _currentTitle = widget.initialTitle!;
    }
    // ── 動画メモ履歴を復元 ──
    // この動画 (URL or videoId 単位) で過去に「履歴に保存」 したメモを
    // 現セッションのメモ一覧として読み込む。 セッションを越えてメモが
    // 残るので、 後日同じ動画を開いた時に見返せる。
    _videoMemoLoadFuture = _winLoadVideoMemoHistory();
    // ── YouTube ナビ履歴の復元 ──
    // 前回このセッションで開いていた URL があれば、 widget.url の代わりに
    // それを初期 URL として使う (= 続きから始められる)。
    // 「YouTubeを開く」 起動 (= onEmbedUrl != null、 検索ページ等から開始)
    // の時のみ適用。 動画ページから直接起動された場合は元の URL を尊重。
    _initController();
    // forceHome (= Ctrl+U / 「YouTube を開く」 経由) の時は、 過去に開いた
    // 動画 URL を復元せず、 必ず widget.url (= ホーム) のままにする。
    // これをしないと「最後に開いた埋め込み動画に飛んで抜けられない」 状態に
    // なる (ユーザー報告)。
    if (widget.onEmbedUrl != null && !widget.forceHome) {
      _restoreYoutubeNavHistory();
    }
  }

  Future<void> _handoffSheetOAuthToExternalBrowser() async {
    final now = DateTime.now();
    final last = _lastOAuthHandoffAt;
    if (_oauthHandoffInProgress ||
        (last != null && now.difference(last) < const Duration(seconds: 30))) {
      return;
    }
    final fallback = isSafeExternalServiceUrl(_oauthLastSafeServiceUrl)
        ? _oauthLastSafeServiceUrl
        : (isSafeExternalServiceUrl(widget.url) ? widget.url : '');
    if (fallback.isEmpty) return;

    _oauthHandoffInProgress = true;
    _lastOAuthHandoffAt = now;
    try {
      final opened = await launchUrl(
        Uri.parse(fallback),
        mode: LaunchMode.externalApplication,
      );
      if (opened && mounted) {
        _appSnack(
          context,
          SnackBar(
            content: Text(context.read<MindMapProvider>().t('login.externalBrowser')),
            backgroundColor: const Color(0xFF6C63FF),
            duration: Duration(seconds: 3),
          ),
        );
      }
    } catch (e) {
      debugPrint('OAuth 外部ブラウザ起動失敗: $e');
    } finally {
      // 認証ページに留まって更新を繰り返さないよう、直前のサービスへ戻す。
      if (mounted &&
          _winActiveTab >= 0 &&
          _winActiveTab < _winTabs.length) {
        final tab = _winTabs[_winActiveTab];
        setState(() {
          tab.url = fallback;
          _winShowTabPreview(tab);
          _loading = true;
        });
        _winLoadForTab(tab, fallback);
      }
      Future<void>.delayed(const Duration(seconds: 2), () {
        if (mounted) _oauthHandoffInProgress = false;
      });
    }
  }

  /// 履歴の最新 URL があれば、 ロード後にそちらにナビゲートしなおす。
  Future<void> _restoreYoutubeNavHistory() async {
    final latest = await _YoutubeNavHistory.latest();
    if (latest == null || latest == widget.url || !mounted) return;
    if (!_isYoutubeUrl(latest)) return;
    // controller の初期化完了を少し待ってから loadUrl
    await Future.delayed(const Duration(milliseconds: 500));
    if (!mounted || !_initialized) return;
    if (_winActiveTab >= 0 && _winActiveTab < _winTabs.length) {
      final tab = _winTabs[_winActiveTab];
      setState(() {
        tab.url = latest;
        _winShowTabPreview(tab);
        _loading = true;
      });
      _winLoadForTab(tab, latest);
    }
  }

  /// URL が YouTube 関連か判定。 履歴に追加するか / 復元するかの判定用。
  bool _isYoutubeUrl(String u) {
    final lower = u.toLowerCase();
    return lower.contains('youtube.com') || lower.contains('youtu.be');
  }

  /// 保存済みの動画メモ項目を復元する。
  Future<void> _winLoadVideoMemoHistory() async {
    final loaded = await _VideoMemoHistoryStore.loadForUrl(_winHistoryKeyUrl());
    if (!mounted) return;
    setState(() {
      final merged = <_VideoMemoEntry>[..._videoMemos];
      final knownIds = merged.map((entry) => entry.id).toSet();
      for (final entry in loaded) {
        if (knownIds.add(entry.id)) {
          merged.add(entry);
        }
      }
      _videoMemos
        ..clear()
        ..addAll(merged.take(100));
    });
    // 読込み中に追加された項目は、待機中の persist が
    // この Future 完了後にマージ済みスナップショットを保存する。
  }

  /// このPC動画画面のメモ帳を識別する安定したキーを返す。
  ///
  /// WebView の現在 URL はタブ切替や YouTube の SPA 遷移で変わるため、保存先の
  /// キーには画面を開いた時の URL を使う。各メモが実際に紐づく動画は
  /// `_VideoMemoEntry.sourceUrl` に個別保存する。
  String _winHistoryKeyUrl() {
    final initial = widget.url.trim();
    return initial.isNotEmpty ? initial : 'youtube_video_memos';
  }

  /// 現在の動画メモ項目を SharedPreferences に保存する。
  Future<void> _winPersistVideoMemos() async {
    await _videoMemoLoadFuture;
    await _VideoMemoHistoryStore.saveForUrl(
      _winHistoryKeyUrl(),
      _videoMemos.take(100).toList(growable: false),
    );
  }

  /// メモ作成時点の動画 URL を正規化してスナップショットする。
  /// YouTube は余分な playlist / 時刻クエリを除いた watch URL、ローカル動画は
  /// playlist に入っている元パスを保存する。
  String _winCurrentMemoSourceUrl() {
    final current = _currentUrl.trim();
    final currentVideoId = _extractVideoIdFromWin(current);
    if (currentVideoId != null) {
      return 'https://www.youtube.com/watch?v=$currentVideoId';
    }

    if (_playlist.isNotEmpty && _playlistIndex < _playlist.length) {
      final playlistSource = _playlist[_playlistIndex].trim();
      if (playlistSource.isNotEmpty) {
        final playlistVideoId = _extractVideoIdFromWin(playlistSource);
        if (playlistVideoId != null) {
          return 'https://www.youtube.com/watch?v=$playlistVideoId';
        }
        // ローカル動画では WebView 側の URL が data: ラッパになることがあるため、
        // 元ファイルのパスを優先する。
        if (_isMp4UrlWin(playlistSource) || current.startsWith('data:')) {
          return playlistSource;
        }
      }
    }

    if (current.isNotEmpty) return current;
    return widget.url.trim();
  }

  /// メモ作成時点の動画タイトルをスナップショットする。
  String? _winCurrentMemoSourceTitle() {
    final title = _currentTitle.trim();
    if (title.isNotEmpty) return title;
    if (_winActiveTab >= 0 && _winActiveTab < _winTabs.length) {
      final tabTitle = _winTabs[_winActiveTab].title.trim();
      if (tabTitle.isNotEmpty) return tabTitle;
    }
    return null;
  }

  /// PC版WebViewで再生できるURLに変換する
  /// - YouTube動画: 通常の watch URL を直接ロード
  ///   （/embed/<id> や data: ラッパだと一部動画でエラー153が出るため）
  /// - mp4/動画ファイル: HTMLプレーヤーを生成
  String _toPlayableUrl(String url) {
    final videoId = _extractVideoIdFromWin(url);
    if (videoId != null) {
      // 通常の watch URL として開く。YouTubeの通常ページコンテキスト内で
      // 再生するため埋め込み制限の影響を受けにくい
      return 'https://www.youtube.com/watch?v=$videoId';
    }
    // mp4/動画ファイルの場合はHTMLプレーヤーを生成
    if (_isMp4UrlWin(url)) {
      return _buildMp4HtmlPlayer(url);
    }
    return url;
  }

  /// YouTubeをIFrame Player APIでラップしたHTMLを返す（data: URL）
  /// - raw iframeだとorigin=nullでエラー153が出るため、JS APIで動的に生成
  /// - host は www.youtube.com を使う（nocookie は 153 を返すケースが多い）
  /// - fs: 0 でフルスクリーンボタンを非表示にし、内部プレーヤーに留める
  String _buildYoutubeHtmlPlayer(String videoId) {
    final html = '''<!DOCTYPE html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>*{margin:0;padding:0;box-sizing:border-box;}
html,body{width:100%;height:100%;background:#000;overflow:hidden;}
#player{width:100%;height:100%;}
</style></head><body>
<div id="player"></div>
<script src="https://www.youtube.com/iframe_api"></script>
<script>
  var player;
  function onYouTubeIframeAPIReady() {
    player = new YT.Player('player', {
      height: '100%', width: '100%',
      videoId: '$videoId',
      host: 'https://www.youtube.com',
      playerVars: {
        autoplay: 1,
        playsinline: 1,
        rel: 0,
        modestbranding: 1,
        fs: 0,
        origin: 'https://www.youtube.com'
      },
      events: {
        onReady: function(e) { try { e.target.playVideo(); } catch(_) {} }
      }
    });
  }
</script>
</body></html>''';
    return Uri.dataFromString(html,
            mimeType: 'text/html', encoding: const Utf8Codec())
        .toString();
  }

  /// mp4をHTMLビデオプレーヤーでラップ（ローカルパス・リモートURL両対応）。
  ///
  /// 重要 (ローカルパスの場合):
  ///   `data:` URL に HTML を埋め込んで `<video src="file:///...">` で
  ///   再生しようとすると、`data:` スキームから `file://` リソースへの
  ///   アクセスが Chromium / WebView2 のセキュリティポリシーでブロック
  ///   されて、画面が真っ黒のまま再生されない。
  ///
  ///   そのため、ローカル mp4 の場合は HTML を **動画と同じディレクトリ** に
  ///   `.player.html` として書き出して、その HTML を `file://` URL で読み込む。
  ///   HTML 内の `<video src="ファイル名.mp4">` は相対パスなので、同一
  ///   ディレクトリの mp4 が解決されて再生できる。
  ///
  ///   (リモート URL `http(s)://` の場合は同一オリジン制約に当たらないので、
  ///    従来通り `data:` URL アプローチで OK)
  String _buildMp4HtmlPlayer(String url) {
    // ── タイトル埋め込み (ヘッダーに動画名を表示するため) ──
    // widget.initialTitle が指定されていればそれを HTML の <title> として埋める。
    // ロード完了時の DOM snapshot が <title> を拾うので、結果として
    // _currentTitle がファイル名ではなく動画本来のタイトルになる。
    final rawTitle = widget.initialTitle ?? '';
    final escapedTitle = const HtmlEscape().convert(rawTitle);

    // ── 左右キーのシーク (= ユーザー要望: 飛ぶ秒数を固定 + 設定可能に) ──
    // 標準 <video controls> の組み込みシークを上書きし、アプリ設定の秒数で
    // シークする。<video> に id="v" を付け、その直後でこのスクリプトを実行。
    // capture フェーズ + preventDefault でブラウザ既定シークを抑止。
    final seekStep = context.read<MindMapProvider>().videoSeekSeconds;
    final seekScript = '''
<script>
(function(){
  var v=document.getElementById('v')||document.querySelector('video');
  if(!v) return;
  window.__MM_SEEK__ = $seekStep;
  document.addEventListener('keydown', function(e){
    try {
      var t=e.target;
      // テキスト入力中だけスキップ。 ネイティブ <video> のシークバー
      // (input type=range) は除外しない (= ユーザー要望: シークバーにフォーカス
      // があると割合ベースの「変な秒数」 でシークしてしまうのを防ぐ)。
      if(t && ((t.tagName==='INPUT'&&t.type!=='range')||t.tagName==='TEXTAREA'||t.isContentEditable)) return;
      var step = window.__MM_SEEK__ || 5;
      if(e.key==='ArrowRight'||e.keyCode===39){ v.currentTime=Math.min((v.duration||1e9), v.currentTime+step); e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation(); }
      else if(e.key==='ArrowLeft'||e.keyCode===37){ v.currentTime=Math.max(0, v.currentTime-step); e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation(); }
    } catch(err){}
  }, true);
})();
</script>''';

    // ── リモート URL: data: URL で HTML をラップ (従来通り) ──
    if (url.startsWith('http') || url.startsWith('data:')) {
      final escaped = url.replaceAll('"', '&quot;');
      final html = '''<!DOCTYPE html><html><head><meta charset="utf-8">
<title>$escapedTitle</title>
<style>*{margin:0;padding:0;background:#000;}html,body{width:100%;height:100%;overflow:hidden;}
video{width:100%;height:100%;object-fit:contain;display:block;}
</style></head><body>
<video id="v" controls autoplay playsinline src="$escaped">
  <source src="$escaped" type="video/mp4">
</video>$seekScript</body></html>''';
      return Uri.dataFromString(html,
              mimeType: 'text/html', encoding: const Utf8Codec())
          .toString();
    }

    // ── ローカルパス: HTML を動画と同じディレクトリに書き出して file:// で読み込む ──
    String localPath = url;
    if (localPath.startsWith('file://')) {
      try {
        localPath = Uri.parse(localPath).toFilePath();
      } catch (_) {/* fall through */}
    }
    final norm = localPath.replaceAll(r'\', '/');
    final lastSlash = norm.lastIndexOf('/');
    if (lastSlash < 0) {
      // ディレクトリが取り出せない異常系: data: フォールバック (再生はできない可能性大)
      return Uri.dataFromString(
              '<!DOCTYPE html><body style="background:#000"></body>',
              mimeType: 'text/html',
              encoding: const Utf8Codec())
          .toString();
    }
    final dir = norm.substring(0, lastSlash);
    final filename = norm.substring(lastSlash + 1);
    // 相対 URL として参照するために HTML エスケープ + URI エンコード
    final encodedSrc = Uri.encodeComponent(filename);

    final html = '''<!DOCTYPE html><html><head><meta charset="utf-8">
<title>$escapedTitle</title>
<style>*{margin:0;padding:0;background:#000;}html,body{width:100%;height:100%;overflow:hidden;}
video{width:100%;height:100%;object-fit:contain;display:block;}
</style></head><body>
<video id="v" controls autoplay playsinline src="$encodedSrc">
  <source src="$encodedSrc" type="video/mp4">
</video>$seekScript</body></html>''';

    final htmlPath = '$dir/.mokumoku_player.html';
    try {
      // 同一 WebView 起動内で書き換えても OK (上書き)。
      // 別ディレクトリの動画を見るたびに別の .mokumoku_player.html を作る形になり、
      // ユーザーが Downloads フォルダを開いた時に小さい HTML が見える可能性は
      // あるが、隠しファイル風の名前 (.先頭) で付けて影響を最小化する。
      File(htmlPath).writeAsStringSync(html);
    } catch (e) {
      debugPrint('Failed to write player HTML: $e');
      // 書き込み失敗時は data: URL にフォールバック (再生不可だがクラッシュは防ぐ)
      return Uri.dataFromString(html,
              mimeType: 'text/html', encoding: const Utf8Codec())
          .toString();
    }

    // 書き出した HTML を file:// URL で参照する。
    // Windows パス (例: C:/Users/...) は file:/// で先頭にスラッシュが3つ必要。
    return htmlPath.startsWith('/') ? 'file://$htmlPath' : 'file:///$htmlPath';
  }

  bool _isMp4UrlWin(String url) {
    final lower = url.toLowerCase();
    return lower.endsWith('.mp4') ||
        lower.endsWith('.m4v') ||
        lower.endsWith('.mov') ||
        lower.contains('.mp4?') ||
        lower.contains('/mp4/');
  }

  String? _extractVideoIdFromWin(String url) {
    for (final p in [
      RegExp(r'youtu\.be/([a-zA-Z0-9_-]{11})'),
      RegExp(r'youtube\.com/watch\?.*v=([a-zA-Z0-9_-]{11})'),
      RegExp(r'youtube\.com/embed/([a-zA-Z0-9_-]{11})'),
      RegExp(r'youtube\.com/shorts/([a-zA-Z0-9_-]{11})'),
    ]) {
      final m = p.firstMatch(url);
      if (m != null) return m.group(1);
    }
    return null;
  }

  /// 現在URLが YouTube の動画 or チャンネルなら true
  /// ホーム画面や検索結果、ログインページでは false
  bool _isEmbeddableYoutubeUrl(String url) {
    if (url.isEmpty) return false;
    // 動画URL
    if (_extractVideoIdFromWin(url) != null) return true;
    // チャンネルURL
    if (RegExp(r'youtube\.com/@[A-Za-z0-9._-]+').hasMatch(url)) return true;
    if (RegExp(r'youtube\.com/channel/[A-Za-z0-9_-]+').hasMatch(url))
      return true;
    if (RegExp(r'youtube\.com/c/[A-Za-z0-9._-]+').hasMatch(url)) return true;
    if (RegExp(r'youtube\.com/user/[A-Za-z0-9._-]+').hasMatch(url)) return true;
    // プレイリストURL (?list=PLxxx / ?list=LLxxx / ?list=OLAKxxx 等)。
    // /playlist?list=... と /watch?v=...&list=... の両形式に対応する。
    // 後者は動画 URL 判定で先に true 返るので、ここでは前者を主にカバー。
    if (RegExp(r'youtube\.com/playlist\?').hasMatch(url) &&
        RegExp(r'[?&]list=[A-Za-z0-9_-]+').hasMatch(url)) {
      return true;
    }
    return false;
  }

  bool _winTabIsOpen(_WinTab tab) {
    return _winTabs.any((candidate) => identical(candidate, tab));
  }

  /// URL ストリームの値が、明示的に開始したタブ遷移と同じページかを判定する。
  /// YouTube は watch/embed 間で URL が正規化されるため videoId でも照合する。
  bool _winSameNavigationUrl(String actual, String requested) {
    if (actual == requested) return true;
    final actualVideoId = _extractVideoIdFromWin(actual);
    final requestedVideoId = _extractVideoIdFromWin(requested);
    if (actualVideoId != null && actualVideoId == requestedVideoId) return true;
    try {
      final a = Uri.parse(actual);
      final r = Uri.parse(requested);
      return a.scheme == r.scheme &&
          a.host.toLowerCase() == r.host.toLowerCase() &&
          a.path == r.path &&
          a.query == r.query;
    } catch (_) {
      return false;
    }
  }

  /// 共有 WebView のロードを、active index ではなくタブ実体へ紐付けて開始する。
  ///
  /// 共有コントローラでは古い loadUrl はキャンセルされ得るため、過去要求の
  /// キューは保持しない。以降の stream はこの最新 generation と一致する要求だけ
  /// が受け取る。
  void _winLoadForTab(_WinTab tab, String url) {
    if (!_winTabIsOpen(tab)) return;
    final playable = _toPlayableUrl(url);
    final generation = ++_winNavigationGeneration;
    _winActiveNavigation = _WinTabNavigation(tab, playable, generation);
    _winActiveNavigationMatched = false;
    try {
      _controller.loadUrl(playable);
    } catch (_) {
      if (_winActiveNavigation?.generation == generation) {
        _winActiveNavigation = null;
        _winActiveNavigationMatched = false;
      }
    }
  }

  /// 最新の明示ロードに対応する URL を観測したかだけを保守的に記録する。
  ///
  /// URL stream 自体では tab state を変更しない。要求 URL と一致した通知でも、
  /// 直後に旧ページの redirect が遅着し得るため、実 URL/title の確定は
  /// navigationCompleted 後の DOM snapshot だけで行う。
  void _winObserveUrlForActiveNavigation(String url) {
    final navigation = _winActiveNavigation;
    if (navigation != null &&
        _winTabIsOpen(navigation.tab) &&
        _winSameNavigationUrl(url, navigation.requestedUrl)) {
      _winActiveNavigationMatched = true;
    }
  }

  /// url stream の最新値でヘッダー表示用の [_currentUrl] をライブ更新する。
  /// navigationCompleted が発火しない YouTube 等の SPA 内遷移でも、動画メモ /
  /// AI / 埋め込みボタンの表示条件 (= _currentUrl に動画 ID があるか) が正しく
  /// 再評価されるようにする。 tab.url / title の確定 (DOM snapshot) には触れない。
  void _winSyncLiveUrl(String u) {
    // 表示中タブがアクティブな時だけ更新する (裏タブの redirect 混入を防ぐ)。
    final bool ownerIsActive = _winActiveTab >= 0 &&
        _winActiveTab < _winTabs.length &&
        identical(_winTabs[_winActiveTab], _winDisplayedTab);
    if (!ownerIsActive) return;
    // ローカル mp4 は data:/file: ラッパになり、元パス判定 (_playlist) を壊す
    //   ので _currentUrl を書き換えない (mp4 は _isMp4 フラグ側で処理)。
    if (u.startsWith('data:') || u.startsWith('file:')) return;
    if (u == _currentUrl) return;
    setState(() => _currentUrl = u);
  }

  /// navigationCompleted 時点の実 URL/title を、完了した最新 generation の
  /// 所有タブへ確定する。title stream はイベントに要求 ID が無く前後し得るため、
  /// タブ state の更新には使わず、ここで同じ DOM snapshot から取得する。
  Future<void> _winCommitCompletedNavigation() async {
    final navigation = _winActiveNavigation;
    final owner = navigation?.tab ?? _winDisplayedTab;
    final generation = navigation?.generation ?? _winNavigationGeneration;
    if (!_winTabIsOpen(owner)) return;

    String? actualUrl;
    String? actualTitle;
    try {
      final raw = await _controller.executeScript(r'''
        (function() {
          try {
            return JSON.stringify({
              url: String(window.location.href || ''),
              title: String(document.title || '')
            });
          } catch (e) {
            return '';
          }
        })()
      ''');
      dynamic decoded = raw;
      // webview_windows の戻り値は環境により JSON 文字列がもう一段
      // JSON-encode されるため、Map になるまで最大 2 回だけ展開する。
      for (int i = 0; i < 2 && decoded is String; i++) {
        final text = decoded.trim();
        if (text.isEmpty) break;
        try {
          decoded = jsonDecode(text);
        } catch (_) {
          break;
        }
      }
      if (decoded is Map) {
        actualUrl = (decoded['url'] ?? '').toString().trim();
        actualTitle = (decoded['title'] ?? '').toString().trim();
      }
    } catch (_) {}

    if (!mounted ||
        generation != _winNavigationGeneration ||
        !_winTabIsOpen(owner)) {
      return;
    }
    if (navigation != null) {
      if (!identical(_winActiveNavigation, navigation)) return;
      // 古い navigationCompleted が最新 loadUrl の直後に届く場合がある。
      // 要求 URL を一度も観測しておらず、DOM も要求先でないなら確定しない。
      if (!_winActiveNavigationMatched &&
          (actualUrl == null ||
              !_winSameNavigationUrl(actualUrl!, navigation.requestedUrl))) {
        return;
      }
      _winActiveNavigationMatched = true;
    }

    // ダウンロード対象を固定中に別動画へ自動遷移した場合は、誤った URL を
    // tab state へ確定する前に元ページへ戻す。
    final lock = _downloadingLockUrl;
    if (lock != null && actualUrl != null) {
      final lockVid = _extractVideoIdFromWin(lock);
      final actualVid = _extractVideoIdFromWin(actualUrl!);
      if (lockVid != null && actualVid != null && lockVid != actualVid) {
        _winLoadForTab(owner, lock);
        if (!_downloadAutoNavBackWarned) {
          _downloadAutoNavBackWarned = true;
          _appSnack(
            context,
            SnackBar(
              content:
                  Text(context.read<MindMapProvider>().t('video.autoReverted')),
              backgroundColor: const Color(0xFFFFB347),
              duration: const Duration(seconds: 3),
            ),
          );
        }
        return;
      }
    }

    final ownerIsActive = _winActiveTab >= 0 &&
        _winActiveTab < _winTabs.length &&
        identical(_winTabs[_winActiveTab], owner);
    setState(() {
      _winDisplayedTab = owner;
      if (actualUrl != null && actualUrl!.isNotEmpty) owner.url = actualUrl!;
      if (actualTitle != null && actualTitle!.isNotEmpty) {
        owner.title = _cleanTitle(actualTitle!);
      }
      if (ownerIsActive) {
        _currentUrl = owner.url;
        _currentTitle = owner.title;
        _loading = false;
      }
      if (navigation != null && identical(_winActiveNavigation, navigation)) {
        _winActiveNavigation = null;
        _winActiveNavigationMatched = false;
      }
    });
    if (ownerIsActive) {
      final committedUrl = owner.url;
      if (!_isVideoPageUrl(committedUrl)) {
        _removeFocusMode();
      }
      if (widget.onEmbedUrl != null) {
        try {
          context.read<MindMapProvider>().saveYoutubeBrowseUrl(committedUrl);
        } catch (_) {}
      }
      if (_isYoutubeUrl(committedUrl)) {
        _YoutubeNavHistory.recordVisit(committedUrl);
      }
      _onPageLoaded();
    }
  }

  /// ロード待ち中は WebView の遅延イベントよりも、選択したタブ自身の保存値を
  /// ヘッダーへ表示する。これにより A→B→C と素早く切替えても A の URL/title
  /// が B や C のプレビューへ混入しない。
  void _winShowTabPreview(_WinTab tab) {
    _currentUrl = tab.url;
    _currentTitle = tab.title;
  }

  Future<void> _initController() async {
    // Linux: webview_windows 非対応 → CEF (build 側の LinuxWebViewWidget) で
    //   表示する。 wv_win コントローラは初期化しない (= 呼ぶと例外)。
    if (Platform.isLinux) return;
    try {
      await _controller.initialize();
      // ── ユーザー要望: 広告から戻れるように ──
      // ポップアップ / 新規ウィンドウ (target=_blank / window.open) を別 OS
      // ウィンドウではなく現在の WebView 内で開く。 広告ページに飛んでも
      // 既存の「戻る」 ボタンで元の動画 / ページに戻れるようになる。
      try {
        await _controller
            .setPopupWindowPolicy(wv_win.WebviewPopupWindowPolicy.sameWindow);
      } catch (_) {}
      // ── Ctrl/中クリックで新しいタブを開く (= ユーザー要望) ──
      try {
        await _controller
            .addScriptToExecuteOnDocumentCreated(_kCtrlClickInterceptorJs);
      } catch (_) {}
      _controller.webMessage.listen((msg) {
        if (!mounted) return;
        final hit = _parseCtrlClickWebMessage(msg);
        if (hit != null) {
          // target=_blank / window.open → 前面タブ (= 普通のブラウザと同じ)。
          // Ctrl / 中クリック → 背面タブ (従来通り)。
          // どちらの場合も元のページはそのままタブに残るので、 広告に飛んでも
          // タブを切り替えれば元の動画へ戻れる (= ユーザー要望)。
          if (hit.foreground) {
            openUrlInNewTab(hit.url);
          } else {
            _openInNewWinTab(hit.url);
          }
          return;
        }
        // 動画終了 → playlist の次へ自動遷移 (= ユーザー要望: 動画が終わったら
        // 次の動画へ。 ギャラリーから playlist 付きで開いた時のみ働く)。
        if (_isEndedWebMessage(msg)) _handleWinPlaylistEnded();
      });
      // title stream は URL stream と到着順が保証されず、タブ/要求 ID も無い。
      // タブ state は navigationCompleted 後の DOM snapshot だけから更新する。
      // URL stream も同様に所有者推測へ使わず、最新要求との一致確認だけに使う。
      _controller.url.listen((u) {
        if (mounted && u.isNotEmpty) {
          if (isBlockedEmbeddedOAuthUrl(u)) {
            unawaited(_handoffSheetOAuthToExternalBrowser());
            return;
          }
          if (isSafeExternalServiceUrl(u)) {
            _oauthLastSafeServiceUrl = u;
          }
          _winObserveUrlForActiveNavigation(u);
          // ── SPA 遷移対応 (= ユーザー報告: PC で YouTube を開いても動画メモ /
          //    AI / 埋め込みボタンが出ない) ──。 YouTube は watch ページへ移っても
          //    ページ内 (history API) 遷移のため navigationCompleted が発火せず、
          //    ヘッダー用の _currentUrl が更新されずボタン表示条件を満たさない。
          //    url stream は SourceChanged (history API 含む) で発火するので、
          //    表示中タブの _currentUrl をライブ更新してボタンを出す。
          _winSyncLiveUrl(u);
        }
      });
      _controller.loadingState.listen((state) {
        if (mounted) {
          final navigationOwner = _winActiveNavigation?.tab ?? _winDisplayedTab;
          final ownerIsActive = _winActiveTab >= 0 &&
              _winActiveTab < _winTabs.length &&
              identical(_winTabs[_winActiveTab], navigationOwner);
          if (ownerIsActive && state == wv_win.LoadingState.loading) {
            setState(() => _loading = state == wv_win.LoadingState.loading);
          }
          if (state == wv_win.LoadingState.navigationCompleted) {
            unawaited(_winCommitCompletedNavigation());
          }
        }
      });
      if (_winActiveTab >= 0 && _winActiveTab < _winTabs.length) {
        final tab = _winTabs[_winActiveTab];
        final initialUrl = _playlist[_playlistIndex];
        tab.url = initialUrl;
        _winLoadForTab(tab, initialUrl);
      }
      if (mounted) setState(() => _initialized = true);
    } catch (e) {
      // 初期化失敗時はエラー表示
      if (mounted) setState(() => _initialized = false);
    }
  }

  /// 動画終了の web メッセージ ({t:'mmended'}) か判定する。
  bool _isEndedWebMessage(dynamic msg) {
    try {
      final s = msg is String ? msg : msg.toString();
      if (!s.contains('mmended')) return false;
      final m = jsonDecode(s);
      return m is Map && m['t'] == 'mmended';
    } catch (_) {
      return false;
    }
  }

  /// 動画が終わったら playlist の次へ自動遷移する (= ユーザー要望)。
  /// 終わった動画は視聴完了として記録し (見終わった動画の削除設定に使う)、
  /// 次があれば読み込む。 playlist が 1 本だけなら何もしない (= 従来通り停止)。
  void _handleWinPlaylistEnded() {
    // 単一動画 (playlist なし) は従来通り停止のまま (= 視聴完了記録も遷移も
    // しない)。 ギャラリーから playlist 付きで開いた時だけ働く。
    if (_playlist.length <= 1) return;
    final curVid = _extractVideoIdFromWin(_currentUrl);
    if (curVid != null) {
      try {
        context.read<MindMapProvider>().markVideoFullyWatched(curVid);
      } catch (_) {}
    }
    if (_playlistIndex < _playlist.length - 1) {
      if (_winActiveTab < 0 || _winActiveTab >= _winTabs.length) return;
      final tab = _winTabs[_winActiveTab];
      setState(() {
        _playlistIndex++;
        tab.url = _playlist[_playlistIndex];
        _winShowTabPreview(tab);
        _loading = true;
      });
      _winLoadForTab(tab, tab.url);
    }
  }

  void _onPageLoaded() {
    final originalUrl = _playlist[_playlistIndex];
    _isYoutube =
        originalUrl.contains('youtube.com') || originalUrl.contains('youtu.be');
    _isMp4 = !_isYoutube && _isMp4UrlWin(originalUrl);
    if (_isYoutube) {
      _injectFocusMode();
      _injectPlaybackRate();
      _injectInitialPositionSeek();
      Future.delayed(const Duration(milliseconds: 800), () {
        if (mounted) {
          _injectFocusMode();
          _injectPlaybackRate();
        }
      });
      Future.delayed(const Duration(milliseconds: 2000), () {
        if (mounted) {
          _injectFocusMode();
          _injectPlaybackRate();
        }
      });
      Future.delayed(const Duration(milliseconds: 4000), () {
        if (mounted) _injectFocusMode();
      });
    } else if (_isMp4) {
      _injectPlaybackRate();
      Future.delayed(const Duration(milliseconds: 500), () {
        if (mounted) _injectPlaybackRate();
      });
      if (mounted) setState(() {});
    }
  }

  /// PiP モードに移行する (Windows 専用)。
  ///
  /// リリース版では動画サイトからの端末保存を無効化する。
  Future<void> _downloadCurrentVideoWin() async {
    if (!mounted) return;
    _appSnack(
        context,
        SnackBar(
          content: Text(context.read<MindMapProvider>().t('dl.disabledReleaseSite')),
          backgroundColor: const Color(0xFF2A2A3E),
        ));
  }

  /// 現在再生中の YouTube 動画を取り出し、ルート Overlay 上にフローティング
  /// ミニプレイヤーを浮かべてからこのシートを閉じる。
  /// モバイル版 (`_FullscreenVideoPageState._enterPiP`) と同じ思想で
  /// 「再生位置をできる限り維持して引き継ぐ」ようにしている:
  ///   1. webview_windows の executeScript で `<video>.currentTime` を取得
  ///   2. 取れたらそれを start position として PiP に渡す
  ///   3. 取れなければ provider 側に保存している位置にフォールバック
  /// 再生中の YouTube 動画を、 アプリの外の独立したウィンドウで開く
  /// (= ユーザー判断: PiP を廃止してフローティングに一本化)。
  ///
  /// 別プロセスとして起動するので、 その窓を閉じても本体側の WebView には
  /// 影響しない (b88 で直した「サブ窓を閉じると WebView が全滅する」 の再発を
  /// 避けるため)。 見せるのは YouTube のページそのままで、 プレーヤーには
  /// 手を加えない。
  Future<void> _popOutVideoToOwnWindow() async {
    final videoId = _extractVideoIdFromWin(_currentUrl);
    if (videoId == null) return;
    // 今の再生位置を引き継ぐ (PiP と同じ方法で <video> から取る)。
    var seconds = 0;
    try {
      final result = await _controller.executeScript(
          "(function(){try{var v=document.querySelector('video');"
          "return v?v.currentTime:0;}catch(e){return 0;}})()");
      if (result != null) {
        seconds = (double.tryParse(result.toString()) ?? 0.0).floor();
      }
    } catch (_) {}
    final url = 'https://www.youtube.com/watch?v=$videoId'
        '${seconds > 3 ? '&t=${seconds}s' : ''}';
    // 別プロセスで開く。 同じプロセスのサブ窓で WebView を作ると、 その窓を
    //   閉じた時にプロセス全体で WebView が作れなくなる (b88 の不具合)。
    try {
      await Process.start(
        Platform.resolvedExecutable,
        ['--floating-web=${Uri.encodeComponent(url)}'],
        mode: ProcessStartMode.detached,
      );
    } catch (e) {
      debugPrint('動画をアプリの外へ出せませんでした: $e');
      return;
    }
    if (mounted) Navigator.of(context).maybePop();
  }

  Future<void> _enterWindowsPiP() async {
    final videoId = _extractVideoIdFromWin(_currentUrl);
    final title = _currentTitle;

    // ── ローカル mp4 (オフライン化された動画) の判定 ──
    // _isMp4 が true で、原本 URL (loadUrl 経由で書き換わる前の `widget.url`
    // = `_playlist[_playlistIndex]`) が http(s):// で始まらない場合は
    // ローカルファイルパスとみなす。
    // 注意: `_currentUrl` は WebView2 が listen に流す URL なので、ローカル
    // mp4 では `file:///.../mokumoku_player.html` に書き換わっている。
    // これを直接判定に使うと URL の正体を取り違えるので、`_playlist` を見る。
    final originalUrl = _playlist.isNotEmpty
        ? _playlist[_playlistIndex.clamp(0, _playlist.length - 1)]
        : _currentUrl;
    final bool isLocalMp4Pip = videoId == null &&
        _isMp4 &&
        !originalUrl.startsWith('http://') &&
        !originalUrl.startsWith('https://') &&
        !originalUrl.startsWith('about:');

    if (isLocalMp4Pip) {
      // ── ローカル mp4 PiP ──
      // <video> 要素の currentTime を JS で取得 (HTML プレイヤー側の id="v"
      // も加味するが、querySelector('video') で十分)。
      double position = 0.0;
      try {
        final result = await _controller.executeScript(
            "(function(){try{var v=document.querySelector('video');return v?v.currentTime:0;}catch(e){return 0;}})()");
        if (result != null) {
          position = double.tryParse(result.toString()) ?? 0.0;
        }
      } catch (_) {}
      final rate = _playbackRate;

      if (!mounted) return;
      final rootNavigator = Navigator.of(context, rootNavigator: true);
      final rootOverlay = rootNavigator.overlay;
      if (rootOverlay == null) return;

      // ── 原 mp4 のパス取得 ──
      // `_currentUrl` は loadUrl 後に WebView2 が listen に流す URL = HTML
      // プレイヤーへの file:// URL になっているので使えない。原本のローカル
      // パスは `_playlist[_playlistIndex]` (initState で渡された widget.url)
      // から取得する。
      String localPath = _playlist[_playlistIndex];
      if (localPath.startsWith('file://')) {
        try {
          localPath = Uri.parse(localPath).toFilePath();
        } catch (_) {/* fall through */}
      }

      _WindowsPiPManager.showLocalInOverlay(
        rootOverlay,
        localPath: localPath,
        position: position,
        rate: rate,
        title: title.isNotEmpty ? title : null,
        onRestore: (lp, pos, rt, tt) {
          // PiP の「拡大」ボタン: 元の動画ノードのフルシートを再オープン。
          // initialTitle にはタイトル (PiP に渡したものをそのまま) を渡して
          // ヘッダーがファイル名にフォールバックしないようにする。
          rootNavigator.push(MaterialPageRoute(
            fullscreenDialog: true,
            builder: (_) => Scaffold(
              backgroundColor: const Color(0xFF0F0F1A),
              body: SafeArea(
                child: _WindowsWebViewSheet(
                  onFloatRequest: widget.onFloatRequest,
                  url: lp,
                  initialRate: rt,
                  initialTitle: tt,
                ),
              ),
            ),
          ));
        },
      );
      // フルシートを閉じて PiP に "切り替える" 体験にする (両方残ると音が
      // 二重再生になる)
      if (rootNavigator.canPop()) rootNavigator.pop();
      return;
    }

    if (videoId == null) {
      // ── YouTube 以外 (SoundCloud / Spotify 等) の URL モード ──
      // 動画 ID は無いので位置の保存・拡大ボタンは無効。畳み機能は使える
      // ので、畳むと音声だけ流れ続けるミニ音楽コントロール状態になる。
      if (!mounted) return;
      final rootNavigator = Navigator.of(context, rootNavigator: true);
      final rootOverlay = rootNavigator.overlay;
      if (rootOverlay == null) return;
      _WindowsPiPManager.showUrlInOverlay(
        rootOverlay,
        url: _currentUrl,
        title: title.isNotEmpty ? title : null,
      );
      // フルシートを閉じて PiP に "切り替える" 体験にする (両方残ると音が
      // 二重再生になる)
      if (rootNavigator.canPop()) rootNavigator.pop();
      return;
    }
    final rate = _playbackRate;

    // ── 現在の再生位置を JS から取得 ──
    // webview_windows の executeScript は dynamic を返す。動画再生中で <video>
    // 要素があれば currentTime (秒) を返す。エラー時は 0 にフォールバック。
    double position = 0.0;
    try {
      final result = await _controller.executeScript(
          "(function(){try{var v=document.querySelector('video');return v?v.currentTime:0;}catch(e){return 0;}})()");
      if (result != null) {
        position = double.tryParse(result.toString()) ?? 0.0;
      }
    } catch (_) {}

    if (!mounted) return;
    final providerRef = context.read<MindMapProvider>();
    // フォールバック: provider 側に保存済みの位置 (動画ノードを開き直す時用に
    // 各動画の停止位置をキャッシュしている)
    if (position == 0.0) {
      position = providerRef.getVideoPosition(videoId);
    }
    final rootNavigator = Navigator.of(context, rootNavigator: true);
    final rootOverlay = rootNavigator.overlay;
    if (rootOverlay == null) return;

    // PiP 表示 → シートを閉じる順 (逆だと overlay 挿入時に context 無効になりうる)
    _WindowsPiPManager.showInOverlay(
      rootOverlay,
      videoId: videoId,
      position: position,
      rate: rate,
      title: title.isNotEmpty ? title : null,
      onRestore: (vid, pos, rt) {
        // PiP の「拡大」ボタン: 位置を保存してフルシートを再オープン。
        // ── URL に &t=Ns を付けて再生位置を引き継ぐ (= ユーザー要望: PiP→
        //    全画面で最初に戻ってしまうバグの修正)。 onPositionUpdate で更新
        //    された現在位置 pos を使う。
        providerRef.saveVideoPosition(vid, pos);
        final t = pos.toInt();
        rootNavigator.push(MaterialPageRoute(
          fullscreenDialog: true,
          builder: (_) => Scaffold(
            backgroundColor: const Color(0xFF0F0F1A),
            body: SafeArea(
              child: _WindowsWebViewSheet(
                  onFloatRequest: widget.onFloatRequest,
                url:
                    'https://www.youtube.com/watch?v=$vid${t > 0 ? '&t=${t}s' : ''}',
                initialRate: rt,
                initialPosition: pos,
              ),
            ),
          ),
        ));
      },
    );
    if (mounted) Navigator.of(context).pop();
  }

