  /// CSS注入: 動画ページ（/watch, /embed, /shorts）のみ UI を隠す
  /// ホーム画面 / 検索結果 / チャンネル一覧では検索ボックス等を残したまま
  bool _isVideoPageUrl(String url) {
    return url.contains('/watch') ||
        url.contains('/embed/') ||
        url.contains('/shorts/');
  }

  /// スプリットパネル用: 注入済みフォーカスモード CSS を撤去する。
  /// 動画ページから検索結果 / ホーム / 非 YouTube サイトへ SPA 遷移した
  /// 時に呼ぶ。 残ったままだと `_focusModeCSS` の汎用セレクタ (`header`
  /// `footer` / `html, body{...black...}`) が新ページに適用されて
  /// 「CSS が消える」 ように見える (= ユーザー報告)。
  void _removeFocusMode() {
    try {
      _controller.executeScript('''
        (function() {
          try {
            var s = document.getElementById("__MM_WIN_FOCUS__");
            if (s) s.parentNode && s.parentNode.removeChild(s);
          } catch (e) {}
        })();
      ''');
    } catch (_) {}
  }

  void _injectFocusMode() {
    // ── ブラウズ起動 (focusMode:false) では CSS を入れない (= ユーザー要望:
    //    YouTube 動画が埋め込み状態でないのに勝手に CSS が非表示になるバグ)。
    //    既に入っていれば撤去して素の YouTube UI (検索ボックス等) を保つ。
    if (!widget.focusMode) {
      _removeFocusMode();
      return;
    }
    // 動画以外のページ（ホーム・検索等）ではフォーカスモードCSSを入れない
    if (!_isVideoPageUrl(_currentUrl)) return;
    // ── ページ内コンテンツ(ノード)からの動画は常にフォーカス表示 ──
    // ここに到達している時点で focusMode==true (上の early-return でブラウズ
    // 起動は除外済み) なので、hideEmbedRelated 設定に関わらず必ず関連動画/
    // コメント等を隠して動画を中央に配置する (= ユーザー要望 2026-07)。
    // 再生速度/シークバー等のプレイヤー操作は _focusModeCSS 側で残している。
    final css = _focusModeCSS.replaceAll('\n', ' ').replaceAll("'", "\\'");
    _controller.executeScript('''
      (function() {
        var id = "__MM_WIN_FOCUS__";
        if (document.getElementById(id)) return;
        var s = document.createElement("style");
        s.id = id;
        s.textContent = '$css';
        (document.head || document.documentElement).appendChild(s);
      })();
    ''');
    // ── YouTube の autoplay (関連動画への自動遷移) を無効化 ──
    // 「動画が終わると勝手に次の動画が始まる」 「ダウンロード中に
    //   自動遷移してしまう」 等の問題への対策。
    // 戦略は 3 段階で重ねがけ:
    //   1. autoplay トグル (シャッフルアイコンの隣にある OFF/ON ボタン)
    //      の `aria-pressed` が `true` の時疑似クリックして OFF にする。
    //   2. 終了時の関連動画クリック promo card / 大きな次動画オーバーレイ
    //      (.ytp-ce-element / .ytp-endscreen-content) を CSS で隠して
    //      クリックできなくする。
    //   3. URL を `&autoplay=0` 付きに上書きする手段は SPA 上効きづらい
    //      ので、 video の `ended` イベントで強制 pause + URL 維持。
    // setInterval で何度も叩くのは YouTube SPA が後から DOM を差し替える
    // ため。 1 度の executeScript で済むよう、 セットアップ済みフラグ
    // (window.__MM_WIN_NOAUTOPLAY__) を見て二重起動しないようにする。
    _controller.executeScript('''
      (function() {
        if (window.__MM_WIN_NOAUTOPLAY__) return;
        window.__MM_WIN_NOAUTOPLAY__ = true;
        function disableAutoplayToggle() {
          try {
            // 新 UI: data-tooltip-target-id="ytp-autonav-toggle-button" or
            //        button.ytp-autonav-toggle-button
            // 旧 UI: .ytp-autonav-toggle-button
            var btns = document.querySelectorAll(
              '.ytp-autonav-toggle-button, button[aria-label*="自動再生"], button[aria-label*="Autoplay"]');
            for (var i = 0; i < btns.length; i++) {
              var b = btns[i];
              var pressed = (b.getAttribute('aria-checked') === 'true' ||
                             b.getAttribute('aria-pressed') === 'true');
              if (pressed) {
                try { b.click(); } catch(e) {}
              }
            }
          } catch(e) {}
        }
        function killEndscreen() {
          try {
            // エンドスクリーン (関連動画カード + 「次の動画」 大プレビュー)
            // を非表示。 自動でクリックされたり、 ユーザーの誤タップで
            // 別動画に飛ぶのを防ぐ。
            var sel = [
              '.ytp-ce-element', '.ytp-endscreen-content',
              '.ytp-cards-teaser', '.ytp-cards-button',
              '.ytp-autonav-endscreen-upnext-container',
              '.ytp-upnext'
            ].join(',');
            var els = document.querySelectorAll(sel);
            for (var i = 0; i < els.length; i++) {
              els[i].style.setProperty('display', 'none', 'important');
              els[i].style.setProperty('pointer-events', 'none', 'important');
            }
          } catch(e) {}
        }
        function blockEnded() {
          try {
            var vs = document.querySelectorAll('video');
            for (var i = 0; i < vs.length; i++) {
              var v = vs[i];
              if (v.__MM_NOAUTOPLAY__) continue;
              v.__MM_NOAUTOPLAY__ = true;
              v.addEventListener('ended', function(ev) {
                // 動画終了時、 next URL に navigate されるのを止める
                // (YouTube は内部で setTimeout を使って ended イベント
                //  からごく短時間で次動画を読み込むので、 ended イベント
                //  自体を消費して video を一時停止状態に保つ)。
                try { ev.stopImmediatePropagation(); } catch(_) {}
                try {
                  // 終了直後の自動遷移カウントダウンも消す
                  killEndscreen();
                } catch(_) {}
                try {
                  // Flutter 側へ終了を通知 → playlist の次へ自動遷移
                  // (= ユーザー要望)。 単一動画の時は Flutter 側で無視される。
                  window.chrome.webview.postMessage(JSON.stringify({t:'mmended'}));
                } catch(_) {}
              }, true /* capture */ );
            }
          } catch(e) {}
        }
        disableAutoplayToggle();
        killEndscreen();
        blockEnded();
        setInterval(function() {
          disableAutoplayToggle();
          killEndscreen();
          blockEnded();
        }, 800);
      })();
    ''');
    // ショート動画は YouTube 内部のインラインスタイルで
    // video 要素の width/height が強制されるため、JSで定期的に object-fit:contain
    // を上書きし、ビューポート中央に letterbox 表示させる
    // 100vw/100vh でプレーヤー親要素の高さに依存せず確実にフィット
    _controller.executeScript('''
      (function() {
        if (window.__MM_SHORTS_FIX__) return;
        window.__MM_SHORTS_FIX__ = true;
        function fix() {
          try {
            var vids = document.querySelectorAll('video');
            for (var i = 0; i < vids.length; i++) {
              var v = vids[i];
              v.style.setProperty('object-fit', 'contain', 'important');
              v.style.setProperty('width', '100vw', 'important');
              v.style.setProperty('height', '100vh', 'important');
              v.style.setProperty('max-width', '100vw', 'important');
              v.style.setProperty('max-height', '100vh', 'important');
              v.style.setProperty('position', 'fixed', 'important');
              v.style.setProperty('top', '0', 'important');
              v.style.setProperty('left', '0', 'important');
              v.style.setProperty('margin', 'auto', 'important');
              v.style.setProperty('transform', 'none', 'important');
              v.style.setProperty('z-index', '1', 'important');
            }
            // プレイヤーコンテナも viewport サイズに固定
            var containers = document.querySelectorAll(
              '#movie_player, ytd-player, .html5-video-container, #player-container, #player-container-inner');
            for (var j = 0; j < containers.length; j++) {
              var c = containers[j];
              c.style.setProperty('width', '100vw', 'important');
              c.style.setProperty('height', '100vh', 'important');
              c.style.setProperty('max-width', '100vw', 'important');
              c.style.setProperty('max-height', '100vh', 'important');
              c.style.setProperty('position', 'fixed', 'important');
              c.style.setProperty('top', '0', 'important');
              c.style.setProperty('left', '0', 'important');
              c.style.setProperty('overflow', 'hidden', 'important');
              c.style.setProperty('transform', 'none', 'important');
            }
          } catch(e) {}
        }
        fix();
        setInterval(fix, 400);
      })();
    ''');
  }

  void _injectPlaybackRate() {
    _controller.executeScript('''
      (function() {
        window.__MM_RATE__ = $_playbackRate;
        function applyAll() {
          try {
            var vs = document.querySelectorAll('video');
            for (var i = 0; i < vs.length; i++) {
              if (vs[i].playbackRate !== window.__MM_RATE__) {
                vs[i].playbackRate = window.__MM_RATE__;
              }
            }
          } catch(e) {}
        }
        applyAll();
        if (window.__MM_RATE_INSTALLED__) return;
        window.__MM_RATE_INSTALLED__ = true;
        setInterval(applyAll, 200);
        document.addEventListener('ratechange', function(e) {
          try {
            if (e.target && e.target.tagName === 'VIDEO' &&
                e.target.playbackRate !== window.__MM_RATE__) {
              e.target.playbackRate = window.__MM_RATE__;
            }
          } catch(err) {}
        }, true);
        document.addEventListener('loadeddata', applyAll, true);
        document.addEventListener('play', applyAll, true);
      })();
    ''');
  }

  /// PiP→全画面復帰時の続き再生用シーク (= ユーザー要望: 先頭に戻るバグ修正)。
  /// 1 回だけ適用し (= 手動シークを上書きしない)、 YouTube の autoplay が
  /// 0 秒へ戻すのに負けないよう数回試行する。
  bool _winInitialPosSeeked = false;
  void _injectInitialPositionSeek() {
    if (_winInitialPosSeeked) return;
    if (widget.initialPosition <= 0.5) return;
    _winInitialPosSeeked = true;
    final target = widget.initialPosition;
    for (final ms in [300, 800, 1500, 3000]) {
      Future.delayed(Duration(milliseconds: ms), () {
        if (!mounted) return;
        try {
          _controller.executeScript(
              "(function(){try{var v=document.querySelector('video');if(v&&Math.abs(v.currentTime-$target)>2){v.currentTime=$target;}}catch(e){}})()");
        } catch (_) {}
      });
    }
  }

  void _changeRate(double rate) {
    setState(() => _playbackRate = rate);
    // 「次に動画を開いた時も同じ倍率で開きたい」要望に応えて、
    // 最終倍率を Provider に保存。`_openFullscreenVideo` /
    // `_showWebDialog` 側でこれを次回の初期値として参照する。
    try {
      context.read<MindMapProvider>().setLastVideoPlaybackRate(rate);
    } catch (_) {}
    _injectPlaybackRate();
  }

  /// 動画再生速度の上限を変更するダイアログを表示する。
  /// HTML5 video の playbackRate は理論上 16.0 まで設定可能 (それ以上は
