                    child: Row(children: [
                      const Icon(Icons.warning_amber_rounded,
                          color: Color(0xFFFF6B6B), size: 14),
                      const SizedBox(width: 6),
                      Expanded(
                        child: Text(p.t('video.maxRate.warning'),
                            style: const TextStyle(
                                color: Color(0xFFFF6B6B), fontSize: 10)),
