  /// タイトルから不要なサフィックスを除去
  String _cleanTitle(String raw) {
    if (raw.isEmpty) return '';
    // data:URIの場合はファイル名を表示
    if (raw.startsWith('data:')) {
      final originalUrl = _playlist[_playlistIndex];
      final name = originalUrl.split('/').last.split('\\').last;
      return name.length > 60 ? '${name.substring(0, 57)}...' : name;
    }
    // YouTube系のサフィックスを削除
    var cleaned = raw
        .replaceAll(RegExp(r'\s*[-–—]\s*YouTube\s*$', caseSensitive: false), '')
        .replaceAll(
            RegExp(r'\s*[-–—]\s*m\.youtube\.com\s*$', caseSensitive: false), '')
        .trim();
    if (cleaned.length > 80) cleaned = '${cleaned.substring(0, 77)}...';
    return cleaned;
  }

  @override
  void dispose() {
    if (activeBrowseInstance == this) activeBrowseInstance = null;
    HardwareKeyboard.instance.removeHandler(_handleWinTabHotkey);
    // 動画メモ入力欄の controller を破棄
    _videoMemoController.dispose();
    _videoMemoTsCtrl.dispose();
    _videoMemoTsFocus.dispose();
    _videoMemoFocus.dispose();
    // AI チャットの controller も破棄
    _videoAiController.dispose();
    _videoAiScroll.dispose();
    // 動画メモプレビュー用タイマーも停止
    _videoMemoPreviewTimer?.cancel();
    _videoMemoPreviewTimer = null;
    // パネル内バナーのタイマーも停止 (setState-after-dispose 防止)
    _bannerTimer?.cancel();
    // 閉じる前に現在のタブ一覧を保存（次回起動時の「前のタブを復元」用）。
    // ただし動画再生用 (focusMode) の一時シートは保存しない。 これを保存すると、
    //   動画を閉じた直後の Ctrl+U で、 新しいホームタブに加えてその動画タブが
    //   復元され「YouTube タブが 2 つ開く」 不具合になる (= ユーザー報告)。
    if (!widget.focusMode) _winSaveLastTabs();
    // ── フリーズ対策 (ユーザー報告:「YouTube を全画面で開いた後に閉じると
    //   フリーズする時がある」) ──
    // 動画再生中の WebView2 を同期的に dispose すると、ネイティブ (WebView2)
    // の teardown がクローズのフレーム上で UI スレッドを一瞬ブロックし、
    // アプリが固まることがある。そこで:
    //   1. まず about:blank へ遷移して動画再生を確実に止める
    //   2. dispose 自体をダイアログのクローズ後 (次のイベントループ) に回す
    // これでクローズアニメーションが先に完了し、固まりが解消される。
    final ctrl = _controller;
    Future(() async {
      try {
        await ctrl.loadUrl('about:blank');
      } catch (_) {}
      try {
        await ctrl.dispose();
      } catch (_) {}
    });
    super.dispose();
  }

  // ─── 動画視聴中メモ (Windows 版) ────────────────────────────────────────
  // モバイル版 `_FullscreenVideoPageState` の同名メソッド群と完全に同じ
  // 思想・UI・ロジック。 共有の `MindMapProvider.addVideoMemoNode` を
  // 呼ぶので、 親動画ノード探索 / 子接続 / グループ参加の挙動も統一される。

  /// 現在の動画再生位置 (秒) を WebView2 の <video>.currentTime から取得。
  /// 取得失敗時は 0.0 を返す。
  Future<double> _winGetCurrentVideoTimeSec() async {
    if (!_initialized) return 0.0;
    try {
      final result = await _controller.executeScript(r'''
        (function() {
          try {
            var v = document.querySelector('video');
            return v ? v.currentTime : 0;
          } catch(e) { return 0; }
        })()
      ''');
      if (result == null) return 0.0;
      // executeScript は戻り値が JSON エンコードされる。 数値や数値文字列
      // どちらの可能性もあるため、 toString → tryParse で吸収。
      final s = result.toString().replaceAll('"', '').trim();
      return double.tryParse(s) ?? 0.0;
    } catch (_) {
      return 0.0;
    }
  }

  /// 秒数を `mm:ss` または `h:mm:ss` (1時間以上) にフォーマット。
  String _winFormatTimestamp(double sec) {
    final s = sec.floor();
    final h = s ~/ 3600;
    final m = (s % 3600) ~/ 60;
    final ss = s % 60;
    if (h > 0) {
      return '$h:${m.toString().padLeft(2, '0')}:${ss.toString().padLeft(2, '0')}';
    }
    return '${m.toString().padLeft(2, '0')}:${ss.toString().padLeft(2, '0')}';
  }

  /// メモパネル開閉トグル。
  /// = ユーザー要望: メモと AI は排他ではなく、 片方が開いていてももう片方を
  ///   反対側に開いて両方同時に使える。 メモは右、 AI は左に配置する。
  void _toggleWinVideoMemoPanel() {
    setState(() {
      _videoMemoPanelOpen = !_videoMemoPanelOpen;
      // 開くときは折り畳みと位置をリセットして、 全ボタンが見える展開状態かつ
      //   既定ドック位置 (画面内) で出す (= ユーザー要望: 起動時に全部見える)。
      if (_videoMemoPanelOpen) {
        _videoMemoCollapsed = false;
        _videoMemoPanelPos = null;
      }
    });
    if (_videoMemoPanelOpen) {
      _startWinVideoMemoPreviewTimer();
    } else {
      _stopWinVideoMemoPreviewTimer();
    }
  }

  /// AI パネルの開閉 (= ユーザー要望: Windows 版のみ、 YouTube 動画にブラウザ版
  /// AI 画面)。 メモとは排他にせず、 反対側 (左) に開いて両方使える。
  void _toggleWinVideoAiPanel() {
    setState(() {
      _videoAiPanelOpen = !_videoAiPanelOpen;
      // 開くときに、 設定中のブラウザ AI の URL をまだ持っていなければセット。
      if (_videoAiPanelOpen && _videoAiUrl.isEmpty) {
        final id = context.read<MindMapProvider>().browserAiTarget;
        _videoAiUrl = _winVideoAiUrlFor(id);
      }
      // 開くときは折り畳みと位置をリセット (= 起動時に全ボタンが見える展開状態
      //   かつ既定ドック位置 (画面内) で出す)。
      if (_videoAiPanelOpen) {
        _videoAiCollapsed = false;
        _videoAiPanelPos = null;
      }
    });
  }

  void _scrollWinVideoAiToBottom() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_videoAiScroll.hasClients) {
        _videoAiScroll.animateTo(
          _videoAiScroll.position.maxScrollExtent,
          duration: const Duration(milliseconds: 200),
          curve: Curves.easeOut,
        );
      }
    });
  }

  /// 入力された質問を AI に送り、 応答をチャットに追加する。
  Future<void> _winSendVideoAiMessage() async {
    final text = _videoAiController.text.trim();
    if (text.isEmpty || _videoAiBusy) return;
    final provider = context.read<MindMapProvider>();
    if (!provider.hasActiveAiKey) {
      _appSnack(
          context,
          SnackBar(
              content:
                  Text(context.read<MindMapProvider>().t('ai.apiKeyNotSet')),
              backgroundColor: const Color(0xFFE53935),
              duration: const Duration(seconds: 3)));
      return;
    }
    setState(() {
      _videoAiMessages.add((role: 'user', text: text));
      _videoAiController.clear();
      _videoAiBusy = true;
    });
    _scrollWinVideoAiToBottom();
    try {
      // これまでの会話を簡易に連結して文脈として渡す。
      final convo = _videoAiMessages
          .map((m) => '${m.role == 'user' ? 'ユーザー' : 'AI'}: ${m.text}')
          .join('\n');
      final prompt = '${provider.languageInstructionForAi()}\n\n'
          'あなたは動画を一緒に見ている学習アシスタントです。 以下の会話の'
          '最後のユーザーの発言に、 簡潔で分かりやすく答えてください。\n\n$convo';
      final reply = await provider.askAi(prompt);
      if (!mounted) return;
      setState(() => _videoAiMessages.add((role: 'ai', text: reply.trim())));
    } catch (e) {
      if (!mounted) return;
      setState(() => _videoAiMessages.add((role: 'ai', text: 'エラー: $e')));
    } finally {
      if (mounted) setState(() => _videoAiBusy = false);
      _scrollWinVideoAiToBottom();
    }
  }

  /// 動画 AI パネルで表示するブラウザ AI の URL (= ユーザー要望: API ではなく
  /// ブラウザ版の画面)。 空ならまだ開いていない。
  String _videoAiUrl = '';

  /// AI 欄の WebView の世代番号。 モデル切替と強制再読込の時だけ進める。
  /// 鍵にこれを使うことで、 普段の再描画で WebView が作り直されない
  /// (= ユーザー報告: 変なところで更新が入る、 の修正)。
  int _videoAiGen = 0;

  /// AI 欄で今見ているページ (表示用の控え。 鍵には使わない)。
  String _videoAiCurUrl = '';

  /// 動画 AI パネル (WebView2) のコントローラ。 マウスホイールを JS で
  ///   直接スクロールさせるために保持する (= ユーザー要望)。
  wv_win.WebviewController? _videoAiWinController;

  /// 動画 AI パネルのホイールスクロール。 このパネルはマップ (InteractiveViewer)
  /// の上に重なるオーバーレイなので、 ホイールがマップのズームに吸われて
  /// WebView2 に届かない。 そこで JS でチャット欄を直接スクロールする
  /// (= ユーザー要望: YouTube 内の AI のチャット欄をマウスホイールで動かせるように)。
  void _scrollVideoAiByWheel(PointerSignalEvent event) {
    if (event is! PointerScrollEvent) return;
    if (!Platform.isWindows) return; // モバイル (iaw) はネイティブスクロール
    final dx = event.scrollDelta.dx.round();
    final dy = event.scrollDelta.dy.round();
    if (dx == 0 && dy == 0) return;
    try {
      _videoAiWinController?.executeScript(_webWheelScrollJs(dx, dy));
    } catch (_) {}
  }

  /// 同一送信内の二重挿入を防ぐトークン。
  int _videoAiInjectSeq = 0;

  /// 動画メモ欄の本文を AI チャット欄に送る (= ユーザー要望: 動画メモから書いた
  /// 文章を AI に渡せるように)。 AI パネルが閉じていれば開き、 ロード完了の
  /// タイミングに合わせて数回 (= 1 回だけ成功扱い) 入力欄へ挿入する。
  void _sendVideoMemoToAi() {
    final text = _videoMemoController.text.trim();
    if (text.isEmpty) {
      _showInlineBanner(
          context.read<MindMapProvider>().t('vmemo.empty'),
          color: const Color(0xFFE57373));
      return;
    }
    _sendTextToVideoAi(text);
  }

  /// 「このセッションのメモ」 履歴をまとめて AI に送る (= ユーザー要望: 追加の履歴
  /// の所に AI ボタンを付けて、 書かれている内容を AI に送れるように)。
  String _videoHistoryText() {
    return _videoMemos.map((e) {
      final ts = e.timestampSec != null
          ? '[${_winFormatTimestamp(e.timestampSec!)}] '
          : '';
      return '$ts${e.text}';
    }).join('\n');
  }

  void _sendVideoHistoryToAi() {
    if (_videoMemos.isEmpty) {
      _showInlineBanner(
          context.read<MindMapProvider>().t('vmemo.noMemosToSend'),
          color: const Color(0xFFE57373));
      return;
    }
    final text = _videoHistoryText();
    _sendTextToVideoAi(text);
  }

  void _openVideoHistoryInGoogleSearch() {
    final provider = context.read<MindMapProvider>();
    if (_videoMemos.isEmpty) {
      _showInlineBanner(provider.t('vmemo.noMemosToSearch'),
          color: const Color(0xFFE57373));
      return;
    }
    final text = _videoHistoryText().trim();
    if (text.isEmpty) {
      _showInlineBanner(provider.t('vmemo.noMemosToSearch'),
          color: const Color(0xFFE57373));
      return;
    }
    final size = MediaQuery.of(context).size;
    // ── メモ欄の「隣」 に出す (= ユーザー要望: メモと同じ場所に重ねず、
    //    メモの隣に立ち上がるように) ──
    final memoRect = _winVideoMemoPanelRect();
    final rect = memoRect == null ? null : _winVideoMemoSearchRect(memoRect);
    GoogleSearchDialog.showFloating(
      context,
      initialQuery: text,
      initialMemo: text,
      customTitle: provider.t('vmemo.searchTitle'),
      anchorPos: rect?.topLeft ?? const Offset(16, 16),
      singletonKey: 'win_video_memo_google',
      initialWidth: rect?.width ??
          math.min(520.0, math.max(360.0, size.width * 0.42)),
      initialHeight: rect?.height ??
          math.min(500.0, math.max(320.0, size.height * 0.58)),
      onAddNode: (_, __, ___) {},
    );
  }

  /// 展開中の動画メモパネルの画面矩形 (グローバル座標)。 メモから開く
  /// Google 検索の位置決めに使う。 パネルが出ていない/畳んでいる時は null。
  Rect? _winVideoMemoPanelRect() {
    try {
      final ctx = _videoMemoPanelKey.currentContext;
      final rb = ctx?.findRenderObject() as RenderBox?;
      if (rb == null || !rb.hasSize) return null;
      return rb.localToGlobal(Offset.zero) & rb.size;
    } catch (_) {
      return null;
    }
  }

  /// メモ欄の「隣」 に出す Google 検索ウィンドウの矩形 (= ユーザー要望:
  /// メモと同じ場所に重ねるのではなく、 メモの隣に立ち上がるように)。
  /// メモの左側を優先し、 入らなければ右側。 画面内にクランプする。
  Rect _winVideoMemoSearchRect(Rect memo) {
    final screen = MediaQuery.of(context).size;
    final double w = math.min(520.0, math.max(360.0, screen.width * 0.36));
    final double h = memo.height.clamp(320.0, screen.height - 16.0);
    const gap = 12.0;
    double left = memo.left - w - gap; // まず左隣
    if (left < 8) left = memo.right + gap; // 入らなければ右隣
    left = left.clamp(8.0, math.max(8.0, screen.width - w - 8.0));
    final double top =
        memo.top.clamp(8.0, math.max(8.0, screen.height - h - 8.0));
    return Rect.fromLTWH(left, top, w, h);
  }

  /// 1件の動画メモ本文だけを Google 検索へ渡す。
  void _openVideoMemoInGoogleSearch(_VideoMemoEntry entry) {
    final text = entry.text.trim();
    final provider = context.read<MindMapProvider>();
    if (text.isEmpty) {
      _showInlineBanner(provider.t('vmemo.noMemosToSearch'),
          color: const Color(0xFFE57373));
      return;
    }
    final size = MediaQuery.of(context).size;
    final sourceTitle = (entry.sourceTitle ?? '').trim();
    // ── メモ欄の「隣」 に出す (= ユーザー要望) ──
    final memoRect = _winVideoMemoPanelRect();
    final rect = memoRect == null ? null : _winVideoMemoSearchRect(memoRect);
    GoogleSearchDialog.showFloating(
      context,
      initialQuery: text,
      initialMemo: text,
      customTitle: sourceTitle.isEmpty
          ? provider.t('vmemo.searchTitle')
          : provider
              .t('vmemo.searchSourceTitle')
              .replaceFirst('{title}', sourceTitle),
      anchorPos: rect?.topLeft ?? const Offset(16, 16),
      // 同じ検索画面を再利用しつつ、別項目を押した時は入力内容を更新する。
      singletonKey: 'win_video_memo_google',
      initialWidth: rect?.width ??
          math.min(520.0, math.max(360.0, size.width * 0.42)),
      initialHeight: rect?.height ??
          math.min(500.0, math.max(320.0, size.height * 0.58)),
      onAddNode: (_, __, ___) {},
    );
  }

  /// メモの内容で YouTube を検索し、 今見ている YouTube 画面をその検索
  /// 結果に切り替える (= ユーザー要望: Google 検索ボタンの隣に欲しい)。
  void _openVideoMemoInYoutubeSearch(_VideoMemoEntry entry) {
    final text = entry.text.trim();
    final provider = context.read<MindMapProvider>();
    if (text.isEmpty) {
      _showInlineBanner(provider.t('vmemo.noMemosToSearch'),
          color: const Color(0xFFE57373));
      return;
    }
    final url = 'https://www.youtube.com/results?search_query='
        '${Uri.encodeQueryComponent(text)}';
    // ── 新しいタブで開く (= ユーザー要望) ──
    //   以前は今のタブを検索結果に差し替えていたため、 見ていた動画が
    //   消えてしまい、 メモを取りながら調べるという使い方ができなかった。
    //   タブが上限に達している時は openUrlInNewTab が今のタブで開く。
    openUrlInNewTab(url);
  }

  /// [text] を AI チャット欄へ送る共通処理 (= 動画メモ / 履歴 で共用)。 前提条件を
  /// 先頭に付け、 AI パネルを開いてロード完了タイミングで数回挿入する。
  void _sendTextToVideoAi(String text) {
    if (text.trim().isEmpty) return;
    final provider = context.read<MindMapProvider>();
    // フォールバック手段としてクリップボードにもコピー。
    Clipboard.setData(ClipboardData(text: text));
    final wasOpen = _videoAiPanelOpen;
    if (!wasOpen) _toggleWinVideoAiPanel();
    if (_videoAiCollapsed) setState(() => _videoAiCollapsed = false);
    final sendText = provider.browserAiApplyPrefix(text);
    final token = ++_videoAiInjectSeq;
    final initialDelay = wasOpen
        ? const Duration(milliseconds: 300)
        : const Duration(milliseconds: 1500);
    Future.delayed(initialDelay, () => _injectTextToVideoAi(sendText, token));
    Future.delayed(initialDelay + const Duration(milliseconds: 1200),
        () => _injectTextToVideoAi(sendText, token));
    Future.delayed(initialDelay + const Duration(milliseconds: 2800),
        () => _injectTextToVideoAi(sendText, token));
  }

  /// AI サイトの入力欄に [text] を追加挿入する (contenteditable / textarea を
  /// 総当たりで探し、 一番大きい可視要素へ)。 [token] で 1 送信 1 回だけ挿入。
  void _injectTextToVideoAi(String text, int token) {
    if (!mounted) return;
    final escaped = jsonEncode(text);
    final js = '''
(function() {
  try {
    if (window.__mmVidAiToken === $token) return 'dup';
    var text = $escaped;
    var lp = ((location.host || '') + ' ' + (location.pathname || ''))
        .toLowerCase();
    if (/accounts\.google|appleid|signin|sign-in|sign_in|login|log-in|auth\./
        .test(lp)) return 'login-page';
    function isLoginField(el) {
      if (!el || el.tagName !== 'INPUT') return false;
      var ty = (el.type || '').toLowerCase();
      if (ty !== 'text' && ty !== 'search' && ty !== '') return true;
      var meta = ((el.name || '') + ' ' + (el.id || '') + ' ' +
          (el.autocomplete || '') + ' ' +
          (el.getAttribute('aria-label') || '')).toLowerCase();
      if (/email|identifier|passw|user|phone|tel|otp|code/.test(meta)) {
        return true;
      }
      var f = el.closest('form');
      if (f && f.querySelector(
          'input[type="password"],input[type="email"]')) return true;
      return false;
    }
    var ceSelectors = [
      'div.ProseMirror[contenteditable="true"]',
      '#prompt-textarea',
      'div[contenteditable="true"].ql-editor',
      'div[contenteditable="true"]',
    ];
    function visibleArea(el) {
      var r = el.getBoundingClientRect();
      if (r.width < 80 || r.height < 16) return 0;
      if (r.bottom < 0 || r.top > window.innerHeight) return 0;
      return r.width * r.height;
    }
    function moveCursorToEnd(el) {
      el.focus();
      try {
        var range = document.createRange();
        range.selectNodeContents(el);
        range.collapse(false);
        var sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
      } catch (e) {}
    }
    var best = null, bestArea = 0;
    for (var i = 0; i < ceSelectors.length; i++) {
      var nodes = document.querySelectorAll(ceSelectors[i]);
      for (var j = 0; j < nodes.length; j++) {
        var a = visibleArea(nodes[j]);
        if (a > bestArea) { bestArea = a; best = nodes[j]; }
      }
      if (best) break;
    }
    if (best) {
      var existing = (best.innerText || best.textContent || '').trim();
      moveCursorToEnd(best);
      var prefix = existing.length > 0 ? '\\n' : '';
      try {
        document.execCommand('insertText', false, prefix + text);
      } catch (e) {
        best.innerText = (existing + prefix + text);
        best.dispatchEvent(new InputEvent('input', { bubbles: true, data: text }));
      }
      window.__mmVidAiToken = $token;
      return 'ok-ce';
    }
    var taList = document.querySelectorAll('textarea, input[type="text"]');
    var bestTa = null, bestTaArea = 0;
    for (var k = 0; k < taList.length; k++) {
      if (isLoginField(taList[k])) continue;
      var ta = visibleArea(taList[k]);
      if (ta > bestTaArea) { bestTaArea = ta; bestTa = taList[k]; }
    }
    if (bestTa) {
      bestTa.focus();
      var existing = bestTa.value || '';
      var prefix = existing.length > 0 ? '\\n' : '';
      var newVal = existing + prefix + text;
      var proto = bestTa.tagName === 'TEXTAREA'
        ? window.HTMLTextAreaElement.prototype
        : window.HTMLInputElement.prototype;
      var setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
      setter.call(bestTa, newVal);
      bestTa.dispatchEvent(new Event('input', { bubbles: true }));
      try { bestTa.selectionStart = bestTa.selectionEnd = newVal.length; } catch (e) {}
      window.__mmVidAiToken = $token;
      return 'ok-ta';
    }
    return 'not-found';
  } catch (e) { return 'error: ' + e; }
})();
''';
    try {
      _videoAiWinController?.executeScript(js);
    } catch (_) {}
  }

  /// AI の id (chatgpt/gemini/…) から「ホーム画面」 の URL を返す。
  String _winVideoAiUrlFor(String id) {
    const urls = <String, String>{
      'chatgpt': 'https://chatgpt.com/',
      'gemini': 'https://gemini.google.com/app',
      'claude': 'https://claude.ai/',
      'deepseek': 'https://chat.deepseek.com/',
      'grok': 'https://grok.com/',
    };
    return urls[id] ?? 'https://chatgpt.com/';
  }

  /// 右クリック (or 切替ボタン) で表示する AI モデル切替メニュー。
  /// = ユーザー要望: 動画メモの AI ボタンを右クリックでモデル切替 + 前提条件設定。
  Future<void> _showWinVideoAiSwitchMenu(Offset? globalPos) async {
    final targets = MindMapProvider.browserAiTargets
        .where((t) => t['id'] != 'google')
        .toList();
    final pos = globalPos ?? const Offset(120, 120);
    final current = context.read<MindMapProvider>().browserAiTarget;
    final selected = await showMenu<String>(
      context: context,
      position: RelativeRect.fromLTRB(pos.dx, pos.dy, pos.dx, pos.dy),
      color: const Color(0xFF1E1E32),
      items: [
        for (final t in targets)
          PopupMenuItem<String>(
            value: t['id'],
            child: Row(children: [
              Icon(
                  t['id'] == current
                      ? Icons.radio_button_checked_rounded
                      : Icons.radio_button_unchecked_rounded,
                  color: t['id'] == current
                      ? const Color(0xFFBA68C8)
                      : Colors.white38,
                  size: 16),
              const SizedBox(width: 8),
              Text(t['label'] ?? t['id']!,
                  style: const TextStyle(color: Colors.white)),
            ]),
          ),
        const PopupMenuDivider(),
        PopupMenuItem<String>(
          value: '__prefix__',
          child: Row(children: [
            const Icon(Icons.tips_and_updates_outlined,
                color: Color(0xFFFFB347), size: 16),
            const SizedBox(width: 8),
            Text(context.read<MindMapProvider>().t('ai.setPrefix'),
                style: const TextStyle(color: Colors.white)),
          ]),
        ),
      ],
    );
    if (selected == null || !mounted) return;
    if (selected == '__prefix__') {
      // ── 前提条件 (= ブラウザ AI に渡す文章の先頭に付ける指示) を編集 ──
      final provider = context.read<MindMapProvider>();
      final ctrl = TextEditingController(text: provider.browserAiPrefix);
      final saved = await showDialog<String>(
        context: context,
        builder: (dctx) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Text(provider.t('ai.setPrefix'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
          content: SizedBox(
            width: 360,
            child: TextField(
              controller: ctrl,
              autofocus: true,
              minLines: 2,
              maxLines: 5,
              style: const TextStyle(color: Colors.white, fontSize: 13),
              decoration: InputDecoration(
                hintText: provider.t('ai.prefixHint'),
                hintStyle: const TextStyle(color: Colors.white38, fontSize: 12),
                filled: true,
                fillColor: Colors.white.withValues(alpha: 0.06),
                border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(8),
                    borderSide: BorderSide.none),
              ),
            ),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(dctx),
                child: Text(provider.t('btn.cancel'),
                    style: const TextStyle(color: Colors.white54))),
            ElevatedButton(
                onPressed: () => Navigator.pop(dctx, ctrl.text),
                child: Text(provider.t('btn.save'))),
          ],
        ),
      );
      if (saved != null) {
        await context.read<MindMapProvider>().setBrowserAiPrefix(saved.trim());
      }
      return;
    }
    await context.read<MindMapProvider>().setBrowserAiTarget(selected);
    if (mounted) {
      setState(() {
        _videoAiUrl = _winVideoAiUrlFor(selected);
        // モデルを切り替えた時は作り直して新しいサイトを開く。
        _videoAiGen++;
      });
    }
  }

  /// AI チャット欄を読み込み直す (= ユーザー要望: 更新ボタン)。
  /// 既に開いていれば WebView の再読み込み、 まだ出来ていなければ
  /// URL を入れ直して作り直す。
  void _reloadWinVideoAiPanel() {
    final c = _videoAiWinController;
    if (c != null) {
      try {
        // ignore: discarded_futures
        c.reload();
        return;
      } catch (_) {/* 下の作り直しに落ちる */}
    }
    // コントローラがまだ無い / 使えない時は、 世代番号を進めて WebView
    //   そのものを作り直す。
    if (_videoAiUrl.isEmpty) return;
    setState(() => _videoAiGen++);
  }

  /// AI パネル本体 (= ユーザー要望: API ではなくブラウザ版の AI 画面を表示し、
  /// 右クリックでモデル切替)。 メモ(右下)と同時に使えるよう左下にドックする。
  Widget _buildWinVideoAiPanel(BuildContext context, Size area) {
    final body = ClipRRect(
      borderRadius: const BorderRadius.vertical(bottom: Radius.circular(14)),
      child: _videoAiUrl.isEmpty
          ? const Center(
              child: CircularProgressIndicator(color: Color(0xFFBA68C8)))
          // ホイールでチャット欄をスクロール (= ユーザー要望)。 オーバーレイ
          //   なのでホイールがマップのズームに吸われる。 JS で直接スクロール。
          : Listener(
              onPointerSignal: _scrollVideoAiByWheel,
              child: _SplitWindowsWebView(
                // ★ 鍵は世代番号にする (= ユーザー報告: 変なところで
                //   WebView の更新が入る)。 以前は鍵に URL を使いながら、
                //   ページ遷移のたびにその URL を書き換えていたため、 次に
                //   画面が再描画された瞬間 (畳む / 動かす / メモ操作など) に
                //   「別物」 と判定されて WebView が作り直されていた。
                //   世代番号はモデル切替と強制再読込の時だけ進むので、
                //   普段の再描画では作り直されない。
                key: ValueKey('winVideoAi$_videoAiGen'),
                url: _videoAiUrl,
                onControllerReady: (c) => _videoAiWinController = c,
                onInitialized: () {},
                // 今見ているページは別の入れ物に控えるだけ (鍵に影響しない)。
                onUrlChanged: (u) => _videoAiCurUrl = u,
              ),
            ),
    );
    // ── 全画面表示 (= ユーザー要望: AI チャット欄を全画面にできるボタン) ──
    //   全画面時は表示エリアいっぱいに広げ、 位置も左上に固定する。
    const double margin = 8.0;
    final bool full = _videoAiFullscreen;
    // 境界ドラッグで決めたサイズを優先 (= ユーザー要望: 縦横をドラッグで調整)。
    final double panelW = full
        ? (area.width - margin * 2)
        : (_videoAiPanelSize?.width ?? 430);
    final double panelH = full
        ? (area.height - margin * 2)
        : (_videoAiPanelSize?.height ?? 560);
    return _winVideoDockPanel(
      context: context,
      sideMode: context.read<MindMapProvider>().videoPanelSideBySide,
      panelIdentityKey: const ValueKey('winVideoAiPanel'),
      area: area,
      pos: full ? const Offset(margin, margin) : _videoAiPanelPos,
      onMove: (o) => setState(() => _videoAiPanelPos = o),
      onResize:
          full ? null : (s) => setState(() => _videoAiPanelSize = s),
      alignRightDefault: false,
      width: panelW,
      expandedHeight: panelH,
      collapsed: _videoAiCollapsed,
      onToggleCollapse: () =>
          setState(() => _videoAiCollapsed = !_videoAiCollapsed),
      onClose: _toggleWinVideoAiPanel,
      // フローティング化: 入力中のプロンプトを引き継いで別窓の AI を開き、
      //   このパネルは閉じる (= ユーザー要望)。
      onPopOut: () => _popOutVideoPanel(ai: true),
      icon: Icons.auto_awesome_rounded,
      iconColor: const Color(0xFFBA68C8),
      title: 'AI',
      // 戻る (= ユーザー要望: AI チャット欄でリンクを踏んだ時に戻れるように)
      //   + 全画面表示トグル + AI モデル切替ボタン (= ⇄ 廃止後も残す)。
      headerExtra: [
        IconButton(
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
          icon: const Icon(Icons.arrow_back_rounded,
              color: Colors.white70, size: 18),
          tooltip: context.read<MindMapProvider>().t('btn.back'),
          onPressed: () {
            try {
              _videoAiWinController?.executeScript('window.history.back();');
            } catch (_) {}
          },
        ),
        // ── 画面を更新する (= ユーザー要望: AI チャット欄に更新ボタン) ──
        //   応答が止まった時や、 ログインし直した後に押す。 コントローラが
        //   まだ無い (初期化前) 時は URL を入れ直して作り直す。
        IconButton(
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
          icon: const Icon(Icons.refresh_rounded,
              color: Colors.white70, size: 18),
          tooltip: context.read<MindMapProvider>().t('common.reload'),
          onPressed: _reloadWinVideoAiPanel,
        ),
        // ── 全画面表示トグル (= ユーザー要望) ──
        IconButton(
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
          icon: Icon(
              full ? Icons.fullscreen_exit_rounded : Icons.fullscreen_rounded,
              color: Colors.white70,
              size: 19),
          tooltip: context
              .read<MindMapProvider>()
              .t(full ? 'common.exitFullscreen' : 'common.fullscreen'),
          onPressed: () =>
              setState(() => _videoAiFullscreen = !_videoAiFullscreen),
        ),
        // ── 押したボタンのすぐ下にメニューを出す (= ユーザー要望: 変な位置に
        //    項目が出る → ボタン位置付近に)。 Builder でボタン自身の
        //    RenderBox からグローバル座標を取る。 ──
        Builder(
          builder: (btnCtx) => IconButton(
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
            icon: const Icon(Icons.smart_toy_outlined,
                color: Color(0xFFBA68C8), size: 18),
            tooltip: context.read<MindMapProvider>().t('ai.switchModel'),
            onPressed: () =>
                _showWinVideoAiSwitchMenu(_buttonMenuPos(btnCtx)),
          ),
        ),
      ],
      body: body,
    );
  }

  /// ボタンの context からメニュー表示位置 (ボタン左下のグローバル座標) を
  /// 求める (= ユーザー要望: メニューは押したボタンの付近に出す)。
  Offset? _buttonMenuPos(BuildContext btnCtx) {
    try {
      final rb = btnCtx.findRenderObject() as RenderBox?;
      if (rb == null || !rb.attached) return null;
      return rb.localToGlobal(Offset(0, rb.size.height + 4));
    } catch (_) {
      return null;
    }
  }

  // ── ドック・ドラッグ (= カーソル 1:1 追従) ──
  // バグ: 旧実装は onPanUpdate で `onMove(Offset(left, top) + d.delta)` とし、
  //   ビルド時に確定した left/top (前フレームの値) に毎回 1 回分の delta を足して
  //   いた。 同一フレームに複数の pan イベントが来ると 2 個目以降の delta が
  //   脱落し、 パネルがカーソルから遅れて付いてくる ("置いて行かれる")。
  // 修正: ドラッグ中だけ使うライブ座標 [_dockDragPos] に delta を累積する。
  //   panStart で現在の left/top を基点に取り、 panUpdate で前回値 + delta を
  //   クランプして保存 + onMove。 これで全 delta が積算されカーソルに 1:1 で追従。
  void _dragDockStart(double left, double top) {
    _dockDragPos = Offset(left, top);
  }

  void _dragDockUpdate(DragUpdateDetails d, double left, double top,
      double maxLeft, double maxTop, ValueChanged<Offset> onMove) {
    final base = _dockDragPos ?? Offset(left, top);
    final next = base + d.delta;
    // パネル全体が画面内に残るよう、 呼び出し側が算出した上限でクランプする。
    final clamped = Offset(
      next.dx.clamp(0.0, maxLeft),
      next.dy.clamp(0.0, maxTop),
    );
    _dockDragPos = clamped;
    onMove(clamped);
  }

  void _dragDockEnd() {
    _dockDragPos = null;
  }

  // ── ドック・リサイズ (= ユーザー要望: 動画メモ / AI チャット欄の縦横の
  //    大きさを境界のドラッグで調整)。 移動ドラッグと同じ「ライブ値に delta を
  //    累積」 方式でカーソルに 1:1 追従させる。 ──
  void _dragDockResizeStart(double width, double height) {
    _dockResizeSize = Size(width, height);
  }

  void _dragDockResizeUpdate(DragUpdateDetails d, Size area,
      ValueChanged<Size> onResize,
      {bool horizontal = true, bool vertical = true}) {
    final base = _dockResizeSize;
    if (base == null) return;
    final next = Size(
      horizontal
          ? (base.width + d.delta.dx).clamp(260.0, area.width).toDouble()
          : base.width,
      vertical
          ? (base.height + d.delta.dy).clamp(180.0, area.height).toDouble()
          : base.height,
    );
    _dockResizeSize = next;
    onResize(next);
  }

  void _dragDockResizeEnd() {
    _dockResizeSize = null;
  }

  /// パネル内インラインバナーを表示する (= ユーザー要望: メモ追加等のメッセージを
  /// マップではなくメモ欄の上に出す)。 タイマで自動的に消える。
  void _showInlineBanner(String text,
      {Color color = const Color(0xFF43B97F),
      Duration duration = const Duration(seconds: 2)}) {
    _bannerTimer?.cancel();
    if (!mounted) return;
    setState(() {
      _bannerText = text;
      _bannerColor = color;
    });
    _bannerTimer = Timer(duration, () {
      if (!mounted) return;
      setState(() => _bannerText = null);
    });
  }

  /// メモパネルに重ねる通知バナー Widget (= PDF メモパネルと同じ見た目)。
  /// バナーが無いときは null を返す。
  Widget? _buildWinPanelBanner() {
    if (_bannerText == null) return null;
    return Positioned(
      left: 8,
      right: 8,
      top: 8,
      child: AnimatedOpacity(
        opacity: 1.0,
        duration: const Duration(milliseconds: 200),
        child: Material(
          color: Colors.transparent,
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            decoration: BoxDecoration(
              color: _bannerColor.withValues(alpha: 0.96),
              borderRadius: BorderRadius.circular(8),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withValues(alpha: 0.35),
                  blurRadius: 8,
                  offset: const Offset(0, 2),
                ),
              ],
            ),
            child: Row(children: [
              const Icon(Icons.check_circle_rounded,
                  color: Colors.white, size: 18),
              const SizedBox(width: 8),
              Expanded(
                child: Text(_bannerText ?? '',
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 12.5,
                        fontWeight: FontWeight.w600)),
              ),
            ]),
          ),
        ),
      ),
    );
  }

  /// 動画メモ / AI パネル共通の「自由配置 + 折り畳み」 ラッパ (= ユーザー要望:
  /// ⇄ をやめて自由に画面上へ配置 + ヘッダーのドラッグで移動 + 折り畳みボタン)。
  /// [pos] が null なら既定のドック位置 (下寄せ・左 or 右)。 ヘッダーをドラッグ
  /// すると [onMove] で座標を更新する。 [collapsed] の時は [body] を出さず
  /// ヘッダーだけの小さなバーになる。
  /// 動画メモ / AI チャット欄を別ウィンドウへ浮かせる (= ユーザー要望)。
  /// 書きかけの内容を引き継ぎ、 元のパネルは閉じる。
  Future<void> _popOutVideoPanel({required bool ai}) async {
    final provider = context.read<MindMapProvider>();
    final text = ai ? _videoAiController.text : _videoMemoController.text;
    // ── AI は「別ウィンドウ」 では開けない (= ユーザー報告: フローティング
    //    モードにすると MissingPluginException) ──
    //    desktop_multi_window のサブ窓には webview_windows を登録していない
    //    (登録すると、 サブ窓を閉じた後に本体でも WebView を作れなくなる。
    //    windows/runner/main.cpp のコメント参照)。 そのため AI 画面をサブ窓で
    //    作ろうとすると必ず失敗する。 ヘッダーの AI ボタンと同じく、 本体の
    //    浮遊パネルで開く。 そこから更に「外に出す」 ボタンで、 別プロセスの
    //    本物の窓へ移せる (ログインは保存先が同じなので引き継がれる)。
    if (ai) {
      // 選んでいる AI サイトを開く。 書きかけのプロンプトは URL の {q} に
      //   埋め込んで引き継ぐ (テンプレートに {q} が無ければそのまま開く)。
      final tmpl =
          provider.browserAiTargetDef['url'] ?? 'https://chatgpt.com/';
      final q = text.trim();
      final url = tmpl.replaceAll('{q}', Uri.encodeComponent(q));
      // ── 先にパネルを閉じ、 1 フレーム置いてから外の窓を立ち上げる
      //    (= ユーザー報告: AI 欄を左に置いてフローティングを押すと、
      //    右側に真っ白な板が一瞬出る)。 旧順序では外の窓の起動と同じ
      //    フレームでパネルの作り直しが走り、 描き途中の白いパネルが
      //    見えていた。 ──
      final wasOpen = _videoAiPanelOpen;
      if (wasOpen) _toggleWinVideoAiPanel();
      await Future<void>.delayed(const Duration(milliseconds: 60));
      if (!mounted) return;
      final opened = openExternalWebWindow(url);
      if (!mounted) return;
      if (!opened) {
        // 開けなかったらパネルを元に戻す (閉じっぱなしにしない)。
        if (wasOpen && !_videoAiPanelOpen) _toggleWinVideoAiPanel();
        _appSnack(
          context,
          SnackBar(
            content: Text(provider.t('popOut.desktopOnly')),
            backgroundColor: const Color(0xFFE57373),
            duration: const Duration(seconds: 2),
          ),
        );
        return;
      }
      return;
    }
    final ok = await openFloatingToolWindow(
      kind: 'memo',
      provider: provider,
      text: text,
    );
    if (!mounted) return;
    if (!ok) {
      _appSnack(
        context,
        SnackBar(
          content: Text(provider.t('popOut.desktopOnly')),
          backgroundColor: const Color(0xFFE57373),
          duration: const Duration(seconds: 2),
        ),
      );
      return;
    }
    // 浮かせたので、 動画の上に重なっていたパネルは閉じる。
    if (_videoMemoPanelOpen) _toggleWinVideoMemoPanel();
  }

  /// 動画メモ / AI 欄を「動画の横」 に並べた時の板 (= ユーザー要望: PDF の
  /// ように横に配置するモード)。 浮遊パネルと同じ中身を、 位置やリサイズの
  /// 仕掛け抜きで縦いっぱいに出す。
  Widget _winVideoSidePanelCard({
    required BuildContext context,
    required Key panelIdentityKey,
    required bool collapsed,
    required VoidCallback onToggleCollapse,
    required VoidCallback onClose,
    required IconData icon,
    required Color iconColor,
    required String title,
    required Widget body,
    List<Widget> headerExtra = const [],
    Widget? bannerOverlay,
    VoidCallback? onPopOut,
    // 掴んで置き場所を替えるための印 ('memo' / 'ai')。
    // (= ユーザー要望: ドラッグ＆ドロップで配置位置を替えられるように)
    String? dragId,
  }) {
    return Container(
      key: panelIdentityKey,
      decoration: const BoxDecoration(
        color: Color(0xFF1E1E32),
        border: Border(left: BorderSide(color: Color(0x33FFFFFF))),
      ),
      child: Material(
        color: Colors.transparent,
        child: Column(children: [
          _wrapPanelHeaderDraggable(
            dragId,
            icon,
            iconColor,
            title,
            Padding(
            padding: const EdgeInsets.fromLTRB(12, 6, 4, 6),
            child: Row(children: [
              if (dragId != null) ...[
                const Icon(Icons.drag_indicator_rounded,
                    color: Colors.white38, size: 16),
                const SizedBox(width: 4),
              ],
              Icon(icon, color: iconColor, size: 18),
              const SizedBox(width: 6),
              Expanded(
                child: Text(title,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 14,
                        fontWeight: FontWeight.w700)),
              ),
              ...headerExtra,
              // ── 左右を入れ替える (= ユーザー要望: メモと AI 欄の左右を
              //    ボタンで替えたい。 ドラッグでも替えられるが分かりにくい) ──
              if (dragId != null)
                IconButton(
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints(minWidth: 28, minHeight: 28),
                  icon: const Icon(Icons.swap_horiz_rounded,
                      color: Colors.white54, size: 16),
                  tooltip: context.read<MindMapProvider>().t('md.swapSides'),
                  onPressed: () {
                    final cur = _videoPanelSide[dragId] ?? 'right';
                    _applyVideoPanelMove(
                        dragId, cur == 'right' ? 'left' : 'right');
                  },
                ),
              if (onPopOut != null)
                IconButton(
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints(minWidth: 28, minHeight: 28),
                  icon: const Icon(Icons.open_in_new_rounded,
                      color: Color(0xFF80CBC4), size: 16),
                  tooltip: context
                      .read<MindMapProvider>()
                      .t('panel.popOutFloating'),
                  onPressed: onPopOut,
                ),
              IconButton(
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
                icon: Icon(
                    collapsed
                        ? Icons.open_in_full_rounded
                        : Icons.close_fullscreen_rounded,
                    color: Colors.white54,
                    size: 16),
                tooltip: context
                    .read<MindMapProvider>()
                    .t(collapsed ? 'ctx.expand' : 'ctx.collapse'),
                onPressed: onToggleCollapse,
              ),
              IconButton(
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
                icon: const Icon(Icons.close, color: Colors.white70, size: 18),
                tooltip: context.read<MindMapProvider>().t('btn.close'),
                onPressed: onClose,
              ),
            ]),
          ),
          ),
          if (!collapsed) ...[
            const Divider(height: 1, color: Color(0x22FFFFFF)),
            Expanded(
              child: bannerOverlay == null
                  ? body
                  : Stack(children: [
                      Positioned.fill(child: body),
                      bannerOverlay,
                    ]),
            ),
          ],
        ]),
      ),
    );
  }

  /// パネルのヘッダーを「掴んで動かせる」 ようにする (= ユーザー要望:
  /// ドラッグ＆ドロップで置き場所を替えられるように)。 [dragId] が null なら
  /// そのまま返す。
  Widget _wrapPanelHeaderDraggable(String? dragId, IconData icon,
      Color iconColor, String title, Widget header) {
    if (dragId == null) return header;
    return Draggable<String>(
      data: dragId,
      dragAnchorStrategy: pointerDragAnchorStrategy,
      feedback: Material(
        color: Colors.transparent,
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
          decoration: BoxDecoration(
            color: const Color(0xFF23233A),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: const Color(0xFF4FC3F7)),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            Icon(icon, color: iconColor, size: 16),
            const SizedBox(width: 6),
            Text(title,
                style: const TextStyle(
                    color: Colors.white,
                    fontSize: 12,
                    fontWeight: FontWeight.w700)),
          ]),
        ),
      ),
      childWhenDragging: Opacity(opacity: 0.4, child: header),
      child: MouseRegion(
        cursor: SystemMouseCursors.grab,
        child: header,
      ),
    );
  }

  Widget _winVideoDockPanel({
    required BuildContext context,
    // ── このパネルを見分ける鍵 (= ユーザー報告: メモ欄を開け閉めすると AI
    //    チャット欄まで読み込み直される) ──
    //    メモと AI は同じ Stack に並ぶ Positioned なので、 鍵が無いと
    //    Flutter は「並び順」 で対応付ける。 メモを閉じると AI が 1 番目に
    //    繰り上がり、 メモだった要素に AI が当てはめられて中の WebView が
    //    作り直されていた。 固定の鍵を付ければ、 並びが変わっても同じ
    //    パネルとして扱われ、 読み込み直しは起きない。
    required Key panelIdentityKey,
    // パネルが置かれる実際の表示エリア (= 親 Stack のサイズ)。 MediaQuery の
    //   全画面サイズだと、 動画ダイアログが画面より小さいときにパネルが
    //   ダイアログ外へ飛び出して右上の折り畳み/閉じるボタンが押せなくなる
    //   (= ユーザー報告)。 必ず LayoutBuilder で得た実寸を渡すこと。
    required Size area,
    required Offset? pos,
    required ValueChanged<Offset> onMove,
    required bool alignRightDefault,
    required double width,
    required double expandedHeight,
    required bool collapsed,
    required VoidCallback onToggleCollapse,
    required VoidCallback onClose,
    required IconData icon,
    required Color iconColor,
    required String title,
    List<Widget> headerExtra = const [],
    required Widget body,
    // パネル内に重ねる通知バナー (= ユーザー要望: 「メモを追加しました」 等の
    //   メッセージをマップではなくメモ欄の上に出す)。 null なら何も重ねない。
    Widget? bannerOverlay,
    // 展開時パネルの実矩形を外から参照するためのキー (= ユーザー要望: メモから
    //   開く Google 検索をメモ欄と同じ位置に出す)。 null なら付けない。
    GlobalKey? panelKey,
    // 右下角のドラッグでパネルの縦横サイズを変えられるようにする
    //   (= ユーザー要望: 動画メモや AI チャット欄の大きさを境界ドラッグで調整)。
    //   null ならリサイズ不可 (従来どおり)。
    ValueChanged<Size>? onResize,
    // ヘッダーの「フローティング化」 ボタン (= ユーザー要望: 動画メモや AI
    //   チャット欄をアプリの外に浮かせられるように)。 null なら出さない。
    VoidCallback? onPopOut,
    // 動画の横に並べるモードか (= ユーザー要望: 設定で切り替え)。
    bool sideMode = false,
  }) {
    // ── 横に並べるモードでは、 位置もリサイズも要らない板を返す ──
    if (sideMode) {
      return _winVideoSidePanelCard(
        context: context,
        panelIdentityKey: panelIdentityKey,
        // 掴んで置き場所を替えるための印 (= ユーザー要望)。
        dragId: panelIdentityKey == const ValueKey('winVideoMemoPanel')
            ? 'memo'
            : (panelIdentityKey == const ValueKey('winVideoAiPanel')
                ? 'ai'
                : null),
        collapsed: collapsed,
        onToggleCollapse: onToggleCollapse,
        onClose: onClose,
        icon: icon,
        iconColor: iconColor,
        title: title,
        headerExtra: headerExtra,
        bannerOverlay: bannerOverlay,
        onPopOut: onPopOut,
        body: body,
      );
    }
    final size = area;
    const double margin = 16.0;
    // 表示する高さ (折り畳み時はヘッダーのみ)。 エリアより大きいときは
    //   エリアに収める (= はみ出して下のボタンが隠れないように)。
    final double panelH =
        (collapsed ? 44.0 : expandedHeight).clamp(0.0, size.height);
    // パネル全体が収まる最大左上座標。 折り畳み時は小さなアイコン (44px) の幅で
    //   クランプする (= ユーザー報告: 畳んだ時にアイコンを動画の右端まで持って
    //   行けない。 原因は展開時の幅でクランプしていたこと)。
    final double effWidth = (collapsed ? 44.0 : width).clamp(0.0, size.width);
    final double maxLeft = (size.width - effWidth).clamp(0.0, size.width);
    final double maxTop = (size.height - panelH).clamp(0.0, size.height);
    final double defLeft =
        alignRightDefault ? (size.width - width - margin) : margin;
    final double defTop = size.height - panelH - margin;
    final base = pos ?? Offset(defLeft, defTop);
    // パネル全体 (幅・高さ) が表示エリア内に収まるようクランプ。 これで起動時も
    //   ドラッグ後も、 折り畳み/閉じるボタンが必ず画面内に見える。
    final double left = base.dx.clamp(0.0, maxLeft);
    final double top = base.dy.clamp(0.0, maxTop);
    if (collapsed) {
      // 折り畳み時は「ボタンだけの小さなもの」 にする (= ユーザー要望: 文字の
      //   ところに出さず、 アイコンだけの小さなボタンに)。 タップで展開、
      //   ドラッグで移動。
      return Positioned(
        key: panelIdentityKey,
        left: left,
        top: top,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onPanStart: (_) => _dragDockStart(left, top),
          onPanUpdate: (d) =>
              _dragDockUpdate(d, left, top, maxLeft, maxTop, onMove),
          onPanEnd: (_) => _dragDockEnd(),
          onTap: onToggleCollapse,
          child: Tooltip(
            message: context
                .read<MindMapProvider>()
                .t('common.tapToExpand')
                .replaceFirst('{title}', title),
            child: Container(
              width: 44,
              height: 44,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: const Color(0xFF1E1E32),
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: iconColor.withValues(alpha: 0.6)),
                boxShadow: const [
                  BoxShadow(
                      color: Colors.black54,
                      blurRadius: 12,
                      offset: Offset(0, 4)),
                ],
              ),
              child: Icon(icon, color: iconColor, size: 22),
            ),
          ),
        ),
      );
    }
    return Positioned(
      key: panelIdentityKey,
      left: left,
      top: top,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: () {},
        child: Container(
          key: panelKey,
          width: width,
          constraints: BoxConstraints(maxHeight: expandedHeight),
          decoration: BoxDecoration(
            color: const Color(0xFF1E1E32),
            borderRadius: BorderRadius.circular(14),
            boxShadow: const [
              BoxShadow(
                  color: Colors.black54, blurRadius: 16, offset: Offset(0, 8)),
            ],
          ),
          child: Material(
            color: Colors.transparent,
            child: Stack(children: [
              Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                // ── ヘッダー = ドラッグハンドル (= 自由配置) ──
                GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onPanStart: (_) => _dragDockStart(left, top),
                  onPanUpdate: (d) =>
                      _dragDockUpdate(d, left, top, maxLeft, maxTop, onMove),
                  onPanEnd: (_) => _dragDockEnd(),
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(12, 6, 4, 6),
                    child: Row(children: [
                      Icon(icon, color: iconColor, size: 18),
                      const SizedBox(width: 6),
                      Expanded(
                        child: Text(title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 14,
                                fontWeight: FontWeight.w700)),
                      ),
                      ...headerExtra,
                      // ── フローティング化 (= ユーザー要望: 動画メモ / AI
                      //    チャット欄を別ウィンドウとして浮かせる) ──
                      if (onPopOut != null)
                        IconButton(
                          padding: EdgeInsets.zero,
                          constraints:
                              const BoxConstraints(minWidth: 28, minHeight: 28),
                          icon: const Icon(Icons.open_in_new_rounded,
                              color: Color(0xFF80CBC4), size: 16),
                          tooltip: context
                              .read<MindMapProvider>()
                              .t('panel.popOutFloating'),
                          onPressed: onPopOut,
                        ),
                      // 折り畳み / 展開ボタン (= ユーザー要望)
                      IconButton(
                        padding: EdgeInsets.zero,
                        constraints:
                            const BoxConstraints(minWidth: 28, minHeight: 28),
                        icon: Icon(
                            collapsed
                                ? Icons.open_in_full_rounded
                                : Icons.close_fullscreen_rounded,
                            color: Colors.white54,
                            size: 16),
                        tooltip: context
                            .read<MindMapProvider>()
                            .t(collapsed ? 'ctx.expand' : 'ctx.collapse'),
                        onPressed: onToggleCollapse,
                      ),
                      IconButton(
                        padding: EdgeInsets.zero,
                        constraints:
                            const BoxConstraints(minWidth: 28, minHeight: 28),
                        icon: const Icon(Icons.close,
                            color: Colors.white70, size: 18),
                        tooltip: context.read<MindMapProvider>().t('btn.close'),
                        onPressed: onClose,
                      ),
                    ]),
                  ),
                ),
                if (!collapsed) ...[
                  const Divider(height: 1, color: Color(0x22FFFFFF)),
                  Expanded(
                    child: bannerOverlay == null
                        ? body
                        : Stack(
                            children: [
                              Positioned.fill(child: body),
                              bannerOverlay,
                            ],
                          ),
                  ),
                ],
              ],
              ),
              // ── 境界ドラッグでリサイズ (= ユーザー要望: 動画メモ / AI
              //    チャット欄の縦横の大きさを境界のドラッグで調整) ──
              //    右端 = 幅、 下端 = 高さ、 右下角 = 両方。
              if (onResize != null) ...[
                Positioned(
                  right: 0,
                  top: 44,
                  bottom: 14,
                  width: 8,
                  child: MouseRegion(
                    cursor: SystemMouseCursors.resizeLeftRight,
                    child: GestureDetector(
                      behavior: HitTestBehavior.translucent,
                      onPanStart: (_) =>
                          _dragDockResizeStart(width, expandedHeight),
                      onPanUpdate: (d) => _dragDockResizeUpdate(
                          d, size, onResize,
                          vertical: false),
                      onPanEnd: (_) => _dragDockResizeEnd(),
                    ),
                  ),
                ),
                Positioned(
                  left: 14,
                  right: 14,
                  bottom: 0,
                  height: 8,
                  child: MouseRegion(
                    cursor: SystemMouseCursors.resizeUpDown,
                    child: GestureDetector(
                      behavior: HitTestBehavior.translucent,
                      onPanStart: (_) =>
                          _dragDockResizeStart(width, expandedHeight),
                      onPanUpdate: (d) => _dragDockResizeUpdate(
                          d, size, onResize,
                          horizontal: false),
                      onPanEnd: (_) => _dragDockResizeEnd(),
                    ),
                  ),
                ),
                Positioned(
                  right: 0,
                  bottom: 0,
                  child: MouseRegion(
                    cursor: SystemMouseCursors.resizeDownRight,
                    child: GestureDetector(
                      behavior: HitTestBehavior.translucent,
                      onPanStart: (_) =>
                          _dragDockResizeStart(width, expandedHeight),
                      onPanUpdate: (d) =>
                          _dragDockResizeUpdate(d, size, onResize),
                      onPanEnd: (_) => _dragDockResizeEnd(),
                      child: const Padding(
                        padding: EdgeInsets.all(2),
                        child: Icon(Icons.south_east_rounded,
                            size: 13, color: Colors.white38),
                      ),
                    ),
                  ),
                ),
              ],
            ]),
          ),
        ),
      ),
    );
  }

  // 旧 `_winInsertVideoMemoTimestampAtCursor` メソッドは削除。
  // モバイル版と同じく「現在時刻を挿入」 ボタンを廃止して「再生位置も保存」
  // チェックの ON/OFF で自動添付する方式に統一した。

  /// メモ入力欄で Ctrl+V を押した時、 クリップボードに画像があれば、 それを
  /// 入力中のメモに貼り付けておく (= ユーザー要望: 動画メモで画像を貼り
  /// 付けておけるように)。 すぐマップへ送らず、 メモを一覧に足した時に
  /// 一緒に付いて行く。 画像が無ければ何もしない (= テキストは通常どおり
  /// 入力欄に貼り付けられる)。
  Future<void> _winPasteMemoImageIfAny() async {
    final saved = await grabImageForVideoMemo(allowPicker: false);
    if (saved == null || !mounted) return;
    setState(() => _videoMemoDraftImage = saved);
    _showInlineBanner(
        context.read<MindMapProvider>().t('vmemo.imageAttached'),
        color: const Color(0xFF43B97F));
  }

  /// 画像ボタン: クリップボードに画像があればそれを、 無ければファイルを
  /// 選んで入力中のメモに貼り付ける。
  Future<void> _winAttachMemoImage() async {
    final saved = await grabImageForVideoMemo();
    if (saved == null || !mounted) return;
    setState(() => _videoMemoDraftImage = saved);
    _showInlineBanner(
        context.read<MindMapProvider>().t('vmemo.imageAttached'),
        color: const Color(0xFF43B97F));
  }


  /// マップに追加する処理 (Windows 版)。
  Future<void> _winSubmitVideoMemoToMap(
      {_VideoMemoEntry? existingEntry}) async {
    if (_videoMemoSubmitting) return;
    final text = (existingEntry?.text ?? _videoMemoController.text).trim();
    // 画像だけのメモも送れる (= ユーザー要望: 画像を貼り付けておける)。
    if (text.isEmpty &&
        (existingEntry?.imagePath ?? _videoMemoDraftImage) == null) {
      _showInlineBanner(
          context.read<MindMapProvider>().t('vmemo.empty'),
          color: const Color(0xFFE57373));
      return;
    }
    setState(() => _videoMemoSubmitting = true);
    try {
      final provider = context.read<MindMapProvider>();
      // 一覧へ追加した後に別動画や別タブへ移動していても、作成時点の動画へ
      // 正しく接続する。旧JSONには sourceUrl が無いため現在動画へフォールバック。
      final snapshottedSource = (existingEntry?.sourceUrl ?? '').trim();
      final videoUrl = snapshottedSource.isNotEmpty
          ? snapshottedSource
          : _winCurrentMemoSourceUrl();

      // ── タイムスタンプ決定ロジック (Windows 版) ──
      // モバイル版と同じく「フィールドの値が全て」 方針。
      double? ts = existingEntry?.timestampSec;
      if (ts == null) {
        final tsText = _videoMemoTsCtrl.text.trim();
        if (tsText.isNotEmpty) {
          ts = _winParseUserTimestamp(tsText);
        }
      }
      final headerLabel = ts != null ? '[${_winFormatTimestamp(ts)}]' : '';

      // 貼り付けた画像もノードに付ける (= ユーザー要望)。
      final imgPath = existingEntry?.imagePath ?? _videoMemoDraftImage;
      final node = provider.addVideoMemoNode(
        memoText: text,
        videoUrl: videoUrl,
        memoTitleHeader: headerLabel.isEmpty ? null : headerLabel,
        fallbackPosition: const Offset(9000, 9000),
        attachmentPath: imgPath,
        attachmentName: imgPath == null
            ? null
            : imgPath.split(Platform.pathSeparator).last.split('/').last,
      );

      if (!mounted) return;
      if (node == null) {
        // ルート SnackBar はメモ欄の上に見えないので、 パネル内バナーで通知。
        _showInlineBanner(provider.t('vmemo.addFailed'),
            color: const Color(0xFFE57373));
        return;
      }

      setState(() {
        if (existingEntry != null) {
          existingEntry.addedToMap = true;
        } else {
          // 互換用の直接追加経路でも、一覧項目と同じ情報を保持する。
          _videoMemos.insert(
            0,
            _VideoMemoEntry(
              id: DateTime.now().microsecondsSinceEpoch.toString(),
              text: text,
              timestampSec: ts,
              imagePath: imgPath,
              addedToMap: true,
              sourceUrl: videoUrl.isEmpty ? null : videoUrl,
              sourceTitle: _winCurrentMemoSourceTitle(),
            ),
          );
          while (_videoMemos.length > 100) {
            _videoMemos.removeLast();
          }
          _videoMemoController.clear();
          _videoMemoDraftImage = null;
        }
      });
      // 永続化 (履歴一覧をセッション越しに保持)
      await _winPersistVideoMemos();

      // 「マップにメモを追加」 をメモ欄の上のバナーで通知 (= ユーザー要望)。
      _showInlineBanner(
          headerLabel.isNotEmpty
              ? provider
                  .t('vmemo.addedToMapAt')
                  .replaceFirst('{timestamp}', headerLabel)
              : provider.t('vmemo.addedToMap'),
          color: const Color(0xFF43B97F));
    } catch (e) {
      debugPrint('Win addVideoMemoNode failed: $e');
      if (mounted) {
        _showInlineBanner(
            context
                .read<MindMapProvider>()
                .t('vmemo.addFailedWithError')
                .replaceFirst('{error}', '$e'),
            color: const Color(0xFFE57373));
      }
    } finally {
      if (mounted) setState(() => _videoMemoSubmitting = false);
    }
  }

  /// まだマップに送っていないメモを、 まとめてマップへ追加する
  /// (= ユーザー要望: 動画メモを纏めてマップに追加できるように)。
  ///
  /// 1 件ずつの「マップに追加」 と同じ道を通す (同じ動画ノードの子として、
  /// タイムスタンプ付きで並ぶ)。 順番は**古い方から**にして、 マップ上の
  /// 並びが動画の時間の流れと同じになるようにする。 追加済みの物は飛ばす。
  Future<void> _winAddAllVideoMemosToMap() async {
    if (_videoMemoSubmitting) return;
    final provider = context.read<MindMapProvider>();
    // 一覧は新しい順なので、 逆から回して古い順に置く。
    final pending = _videoMemos
        .where((e) => !e.addedToMap && e.text.trim().isNotEmpty)
        .toList()
        .reversed
        .toList();
    if (pending.isEmpty) {
      _showInlineBanner(provider.t('vmemo.allAlreadyAdded'),
          color: const Color(0xFF4FC3F7));
      return;
    }
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('vmemo.addAllTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Text(
            provider
                .t('vmemo.addAllConfirm')
                .replaceFirst('{count}', '${pending.length}'),
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, false),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF43B97F),
                foregroundColor: Colors.white),
            onPressed: () => Navigator.pop(dctx, true),
            child: Text(provider.t('vmemo.addAllRun')),
          ),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    setState(() => _videoMemoSubmitting = true);
    var added = 0;
    var failed = 0;
    try {
      for (final entry in pending) {
        final snapshottedSource = (entry.sourceUrl ?? '').trim();
        final videoUrl = snapshottedSource.isNotEmpty
            ? snapshottedSource
            : _winCurrentMemoSourceUrl();
        final ts = entry.timestampSec;
        final headerLabel = ts != null ? '[${_winFormatTimestamp(ts)}]' : '';
        try {
          final img = entry.imagePath;
          final node = provider.addVideoMemoNode(
            memoText: entry.text.trim(),
            videoUrl: videoUrl,
            memoTitleHeader: headerLabel.isEmpty ? null : headerLabel,
            fallbackPosition: const Offset(9000, 9000),
            attachmentPath: img,
            attachmentName: img == null
                ? null
                : img.split(Platform.pathSeparator).last.split('/').last,
          );
          if (node == null) {
            failed++;
          } else {
            entry.addedToMap = true;
            added++;
          }
        } catch (e) {
          debugPrint('Win addVideoMemoNode (bulk) failed: $e');
          failed++;
        }
      }
      if (!mounted) return;
      setState(() {});
      await _winPersistVideoMemos();
      if (!mounted) return;
      _showInlineBanner(
        failed == 0
            ? provider
                .t('vmemo.addedAllToMap')
                .replaceFirst('{count}', '$added')
            : provider
                .t('vmemo.addedAllPartial')
                .replaceFirst('{count}', '$added')
                .replaceFirst('{failed}', '$failed'),
        color: failed == 0 ? const Color(0xFF43B97F) : const Color(0xFFFFB74D),
      );
    } finally {
      if (mounted) setState(() => _videoMemoSubmitting = false);
    }
  }

  /// 入力中の文章を独立した平文メモ項目として追加する。
  /// この時点ではマップへ送らず、一覧の各項目からマップ / AI / Google検索を選ぶ。
  void _winSaveVideoMemoLocally() {
    final text = _videoMemoController.text.trim();
    // 画像だけのメモも足せる (= ユーザー要望: 画像を貼り付けておける)。
    if (text.isEmpty && _videoMemoDraftImage == null) {
      _showInlineBanner(
          context.read<MindMapProvider>().t('vmemo.empty'),
          color: const Color(0xFFE57373));
      return;
    }
    // タイムスタンプフィールドから値を取得 (空なら時刻なし)
    double? ts;
    final tsText = _videoMemoTsCtrl.text.trim();
    if (tsText.isNotEmpty) {
      ts = _winParseUserTimestamp(tsText);
    }
    if (!mounted) return;
    final sourceUrl = _winCurrentMemoSourceUrl();
    final sourceTitle = _winCurrentMemoSourceTitle();
    setState(() {
      _videoMemos.insert(
        0,
        _VideoMemoEntry(
          id: DateTime.now().microsecondsSinceEpoch.toString(),
          text: text,
          timestampSec: ts,
          imagePath: _videoMemoDraftImage,
          addedToMap: false,
          sourceUrl: sourceUrl.isEmpty ? null : sourceUrl,
          sourceTitle: sourceTitle,
        ),
      );
      while (_videoMemos.length > 100) {
        _videoMemos.removeLast();
      }
      _videoMemoController.clear();
      _videoMemoDraftImage = null;
    });
    unawaited(_winPersistVideoMemos());
  }

  /// 履歴から削除。
  void _winDeleteVideoMemo(_VideoMemoEntry entry) {
    setState(() {
      _videoMemos.removeWhere((e) => e.id == entry.id);
    });
    // 永続化 (削除を反映)
    unawaited(_winPersistVideoMemos());
  }

  /// メモパネルウィジェット (Windows 版)。
  /// デスクトップでは画面が広いので、 右下のサイドカード (幅 380px) で
  /// 表示する。 動画は左側に大きく見えたまま。
  Widget _buildWinVideoMemoPanel(BuildContext context, Size area) {
    final provider = context.read<MindMapProvider>();
    // = ユーザー要望: AI(左下)と同時に使えるよう、 メモは右下にドックし
    //   フルスクリーンの暗幕は出さない (動画と AI パネルを操作できる)。
    return _winVideoDockPanel(
      context: context,
      sideMode: provider.videoPanelSideBySide,
      panelIdentityKey: const ValueKey('winVideoMemoPanel'),
      area: area,
      pos: _videoMemoPanelPos,
      onMove: (o) => setState(() => _videoMemoPanelPos = o),
      onResize: (s) => setState(() => _videoMemoPanelSize = s),
      panelKey: _videoMemoPanelKey,
      alignRightDefault: true,
      // 既定の幅 (= ユーザー要望: 下のボタンが全部入り切らないので広げる)。
      width: _videoMemoPanelSize?.width ?? 460,
      // = ユーザー要望: 旧仕様は動画エリアのほぼ全高 (area.height-24) にして
      //   いたが「縦が長すぎる」 ため、 AI チャット欄 (560) と同じくらいの
      //   コンパクトな高さにする。 中身は SingleChildScrollView なのではみ出し
      //   分はスクロールで見られる。 これで折り畳んで画面の端まで持って行ける。
      //   画面が小さい時は _winVideoDockPanel 側がエリア内にクランプする。
      //   境界ドラッグで決めたサイズがあればそれを優先 (= ユーザー要望)。
      expandedHeight: _videoMemoPanelSize?.height ?? 560,
      collapsed: _videoMemoCollapsed,
      onToggleCollapse: () {
        setState(() {
          final nextCollapsed = !_videoMemoCollapsed;
          _videoMemoCollapsed = nextCollapsed;
          if (nextCollapsed) {
            const collapsedSize = 44.0;
            const margin = 16.0;
            final defaultTop =
                (area.height - 560 - margin).clamp(0.0, area.height).toDouble();
            final current = _videoMemoPanelPos ??
                Offset(
                  (area.width - 460 - margin).clamp(0.0, area.width).toDouble(),
                  defaultTop,
                );
            final maxTop = (area.height - collapsedSize)
                .clamp(0.0, area.height)
                .toDouble();
            _videoMemoPanelPos = Offset(
              (area.width - collapsedSize).clamp(0.0, area.width).toDouble(),
              current.dy.clamp(0.0, maxTop).toDouble(),
            );
          }
        });
      },
      onClose: _toggleWinVideoMemoPanel,
      // フローティング化: 書きかけのメモを引き継いで別窓のメモを開き、
      //   このパネルは閉じる (= ユーザー要望)。
      onPopOut: () => _popOutVideoPanel(ai: false),
      icon: Icons.sticky_note_2_rounded,
      iconColor: const Color(0xFFFFB347),
      title: provider.t('vmemo.title'),
      // 「マップにメモを追加」 等の通知をメモ欄の上に重ねる (= ユーザー要望)。
      bannerOverlay: _buildWinPanelBanner(),
      // メモ本文を AI チャット欄に送る (= ユーザー要望: 動画メモから書いた
      //   文章を AI に渡せるように)。
      headerExtra: [
        // 左クリック=メモを AI に送る / 右クリック=AI モデル切替・前提条件設定
        //   (= ユーザー要望)。
        GestureDetector(
          onSecondaryTapUp: (d) => _showWinVideoAiSwitchMenu(d.globalPosition),
          child: IconButton(
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
            icon: const Icon(Icons.smart_toy_outlined,
                color: Color(0xFFBA68C8), size: 18),
            tooltip: '${provider.t('vmemo.sendToAi')} '
                '(${provider.t('tooltip.aiMenuPrereqSuffix')})',
            onPressed: _sendVideoMemoToAi,
          ),
        ),
      ],
      body: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(12, 8, 12, 12),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            const SizedBox(height: 4),
            TextField(
              controller: _videoMemoController,
              focusNode: _videoMemoFocus,
              style: const TextStyle(color: Colors.white, fontSize: 13),
              minLines: 3,
              maxLines: 8,
              keyboardType: TextInputType.multiline,
              textInputAction: TextInputAction.newline,
              decoration: InputDecoration(
                hintText: provider.t('vmemo.inputHint'),
                hintStyle: const TextStyle(color: Colors.white38, fontSize: 11),
                filled: true,
                fillColor: Colors.white.withValues(alpha: 0.08),
                isDense: true,
                contentPadding:
                    const EdgeInsets.symmetric(horizontal: 10, vertical: 10),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(8),
                  borderSide: BorderSide.none,
                ),
              ),
            ),
            // ── 貼り付けた画像 (= ユーザー要望: 動画メモで画像を貼り
            //    付けておけるように)。 × で外せる。 ──
