  /// 動画視聴中なら現在の再生位置を URL に付与して返す (= ユーザー要望:
  /// 画面分割にした時に画面が更新されて再生位置が最初に戻らないように)。
  /// YouTube は t= パラメータ、 mp4 はメディアフラグメント #t= で引き継ぐ。
  /// 動画でない / ほぼ先頭 / 取得失敗時は URL をそのまま返す。
  Future<String> _withVideoPosition(String url) async {
    double sec = 0;
    try {
      if (_initialized) {
        final result = await _controller.executeScript(
            "(function(){try{var v=document.querySelector('video');"
            "return v?v.currentTime:0;}catch(e){return 0;}})()");
        if (result != null) {
          sec = double.tryParse(
                  result.toString().replaceAll('"', '').trim()) ??
              0;
        }
      }
    } catch (_) {}
    if (sec < 3) return url; // ほぼ先頭なら付けない
    final t = sec.floor();
    if (_extractVideoIdFromWin(url) != null) {
      final uri = Uri.tryParse(url);
      if (uri == null) return url;
      final qp = Map<String, String>.from(uri.queryParameters);
      qp['t'] = '${t}s';
      return uri.replace(queryParameters: qp).toString();
    }
    if (_isMp4) {
      final base = url.split('#').first;
      return '$base#t=$t';
    }
    return url;
  }

  /// 再生リスト視聴中、ページ内のリストから「現在より後ろ」の動画 URL を
  /// 抽出する。取得できなければ空リスト（= 単独動画扱い）。
  Future<List<String>> _winFetchPlaylistAfterCurrent() async {
    try {
      final raw = await _controller.executeScript(r'''
        (function(){
          try{
            var rs = document.querySelectorAll('ytd-playlist-panel-video-renderer');
            var urls = [];
            var sel = -1;
            for (var i=0;i<rs.length;i++){
              var a = rs[i].querySelector('a#wc-endpoint, a[href*="watch?v="]');
              var href = a ? a.href : '';
              urls.push(href);
              if (rs[i].hasAttribute('selected')) sel = i;
            }
            if (sel < 0){
              var cur = (location.href.match(/[?&]v=([^&]+)/)||[])[1];
              if (cur){ for (var j=0;j<urls.length;j++){ if(urls[j].indexOf('v='+cur)>=0){ sel=j; break; } } }
            }
            var after = [];
            for (var k=sel+1;k<urls.length;k++){
              if (urls[k] && urls[k].indexOf('watch?v=')>=0) after.push(urls[k]);
            }
            return JSON.stringify(after);
          }catch(e){ return '[]'; }
        })();
      ''');
      dynamic decoded = raw;
      // executeScript は結果を JSON 文字列で返す（二重エンコードのこともある）
      for (var i = 0; i < 2 && decoded is String; i++) {
        try {
          decoded = jsonDecode(decoded as String);
        } catch (_) {
          break;
        }
      }
      if (decoded is List) {
        return decoded
            .map((e) => e.toString())
            .where((u) => u.isNotEmpty)
            .toList();
      }
    } catch (_) {}
    return [];
  }

  /// プレイヤーの上に「埋め込みました」トーストを 2 秒間表示する
  /// (= ユーザー要望: 埋め込んだことが分かるようにメッセージを出す)。
  /// 既存のマップ追加 SnackBar はフルスクリーンの WebView の背後に隠れて
  /// 見えないため、ルート Overlay にトーストを出して前面に見せる。
  void _showWinEmbedToast(String msg) {
    final overlay = Overlay.maybeOf(context, rootOverlay: true);
    if (overlay == null) return;
    OverlayEntry? e;
    e = OverlayEntry(
      builder: (_) => Positioned(
        top: 44,
        left: 0,
        right: 0,
        child: IgnorePointer(
          child: Center(
            child: Material(
              color: Colors.transparent,
              child: Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
                decoration: BoxDecoration(
                  color: const Color(0xFF43B97F),
                  borderRadius: BorderRadius.circular(22),
                  boxShadow: [
                    BoxShadow(
                        color: Colors.black.withValues(alpha: 0.4),
                        blurRadius: 14),
                  ],
                ),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  const Icon(Icons.check_circle_rounded,
                      color: Colors.white, size: 18),
                  const SizedBox(width: 8),
                  Text(msg,
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 14,
                          fontWeight: FontWeight.w700)),
                ]),
              ),
            ),
          ),
        ),
      ),
    );
    overlay.insert(e);
    Timer(const Duration(seconds: 2), () {
      try {
        e?.remove();
      } catch (_) {}
    });
  }

  /// 埋め込みボタンの処理。再生リスト視聴中は「この動画だけ / 後ろも全部」を
  /// 確認してから埋め込む (= ユーザー要望)。後続が無ければそのまま埋め込み。
  Future<void> _winEmbedWithConfirm() async {
    final provider = context.read<MindMapProvider>();
    final cb = widget.onEmbedUrl;
    if (cb == null) return;
    final url = _currentUrl;
    // ── ここで選択を完結させるため、 cb へ渡す URL からは list= を取り除く ──
    // 残したまま渡すと _embedYoutubeUrlAsNode 側の「この動画だけ / リスト
    // 全体」 ダイアログが重ねて表示されてしまう (= 二重確認の防止)。
    // 再生位置 (t=/start=) は維持する。
    String stripList(String u) {
      final id = NodeWidget.extractVideoId(u);
      if (id == null) return u;
      final t = RegExp(r'[?&](?:t|start)=([0-9hms]+)').firstMatch(u)?.group(1);
      return 'https://www.youtube.com/watch?v=$id${t != null ? '&t=$t' : ''}';
    }

    final after = await _winFetchPlaylistAfterCurrent();
    if (!mounted) return;
    if (after.isEmpty) {
      cb(url);
      // ── チャンネル / プレイリストは即トーストを出さない (= ユーザー報告) ──
      // チャンネル URL の場合、 cb (_embedYoutubeUrlAsNode) の中で「本編のみ /
      //   ショートのみ / 両方」 の選択ダイアログや一括取り込みが *非同期* で走る。
      //   ここで即「埋め込みました」 を出すと、 まだ選択画面の段階なのに完了
      //   メッセージが表示されてしまう。 単一動画の時だけ即トーストを出し、
      //   チャンネル / プレイリストは embed 側 (取り込み完了の SnackBar) に任せる。
      //   list= 付き (= embed 側で選択ダイアログが出る) の時も出さない。
      //   Mix (RD…) / WL / LL も embed 側で「視聴中の動画のみ埋め込むか」
      //   の確認ダイアログが出るようになったため、 ここでは出さない。
      final embedSideAsks = _embeddablePlaylistIdOf(url) != null ||
          _unfetchableListIdOf(url) != null;
      if (NodeWidget.extractVideoId(url) != null && !embedSideAsks) {
        _showWinEmbedToast(provider.t('embed.embedded'));
      }
      return;
    }
    // ── 「リスト全体」 も選べるようにする (= ユーザー要望: リスト内の動画を
    //   埋め込むのか、 見ている動画だけかを選択)。 途中の動画から視聴している
    //   場合、「後ろも全部」 では先頭側が入らないため。 Mix (RD…) 等は
    //   /playlist ページが無く取得できないので出さない。
    final String? wholeListId = _embeddablePlaylistIdOf(url);
    final choice = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('embed.title'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Text(
            provider.t('embed.body').replaceFirst('{n}', '${after.length + 1}'),
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actionsOverflowButtonSpacing: 6,
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, null),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          TextButton(
            onPressed: () => Navigator.pop(dctx, 'one'),
            child: Text(provider.t('embed.thisOnly'),
                style: const TextStyle(color: Color(0xFF90CAF9))),
          ),
          if (wholeListId != null)
            TextButton(
              onPressed: () => Navigator.pop(dctx, 'list'),
              child: Text(provider.t('embed.wholeList'),
                  style: const TextStyle(color: Color(0xFF80CBC4))),
            ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF43B97F),
                foregroundColor: Colors.white),
            onPressed: () => Navigator.pop(dctx, 'all'),
            child: Text(provider
                .t('embed.allAfter')
                .replaceFirst('{n}', '${after.length + 1}')),
          ),
        ],
      ),
    );
    if (!mounted || choice == null) return;
    if (choice == 'list' && wholeListId != null) {
      // 親ノード + 子動画ノード群としてリスト全体を一括取り込み。
      cb('https://www.youtube.com/playlist?list=$wholeListId');
      return;
    }
    if (choice == 'one') {
      cb(stripList(url));
      _showWinEmbedToast(provider.t('embed.embedded'));
    } else if (choice == 'all') {
      // callback は既存の String 型を保ったまま、改行区切りで 1 バッチとして
      // 渡す。ギャラリーでは `_runBookshelfImport` が元から空白区切り入力を
      // 解釈できるため全動画を 1 回で追加・表紙化でき、通常マップでは
      // `_embedYoutubeUrlAsNode` が順次展開する。
      final batch = <String>[
        stripList(url),
        for (final u in after) stripList(u),
      ];
      cb(batch.join('\n'));
      _showWinEmbedToast(provider
          .t('embed.embeddedN')
          .replaceFirst('{n}', '${after.length + 1}'));
    }
  }

  /// タブのラベル（アクティブなタブは現在のページタイトル、他は連番）。
  String _winTabLabel(int i) {
    if (i < 0 || i >= _winTabs.length) return '';
    final t = _winTabs[i].title;
    return t.isNotEmpty ? t : 'タブ ${i + 1}';
  }

  /// 別のタブへ切り替える。現在のタブの URL を保存してから読み込み直す。
  void _switchWinTab(int i) {
    if (i == _winActiveTab || i < 0 || i >= _winTabs.length) return;
    final target = _winTabs[i];
    setState(() {
      _winActiveTab = i;
      _winShowTabPreview(target);
      _loading = true;
    });
    _winLoadForTab(target, target.url);
  }

  /// 新しいタブ（YouTube ホーム）を開く。最大 _kMaxWinTabs まで。
  /// (+ ボタンはサイト選択メニューに統合したため現在は直接の呼び出し元は
  ///  無いが、 将来のショートカット用に残す。)
  // ignore: unused_element
  void _addWinTab() {
    if (_winTabs.length >= _kMaxWinTabs) return;
    final home = context
        .read<MindMapProvider>()
        .localizeYoutubeUrl('https://www.youtube.com/');
    late final _WinTab target;
    setState(() {
      target = _WinTab(url: home, title: 'YouTube');
      _winTabs.add(target);
      _winActiveTab = _winTabs.length - 1;
      _winShowTabPreview(target);
      _loading = true;
    });
    _winLoadForTab(target, home);
  }

  /// タブを閉じる。最後の 1 枚は閉じない。お気に入りタブを閉じたら保存も更新。
  void _closeWinTab(int i) {
    if (_winTabs.length <= 1 || i < 0 || i >= _winTabs.length) return;
    final wasActive = i == _winActiveTab;
    final wasPinned = _winTabs[i].pinned;
    // 閉じたタブを履歴に積む (Ctrl+Shift+T で復元できるように)。
    final closingUrl = wasActive && identical(_winTabs[i], _winDisplayedTab)
        ? _currentUrl
        : _winTabs[i].url;
    if (closingUrl.isNotEmpty) {
      _closedWinTabs.add(_WinTab(url: closingUrl, title: _winTabs[i].title));
      if (_closedWinTabs.length > 20) _closedWinTabs.removeAt(0);
    }
    setState(() {
      _winSelectedTabs.remove(_winTabs[i]);
      _winTabs.removeAt(i);
      if (_winActiveTab >= _winTabs.length) {
        _winActiveTab = _winTabs.length - 1;
      } else if (i < _winActiveTab) {
        _winActiveTab--;
      }
      if (wasActive) _loading = true;
    });
    if (wasPinned) _winSavePinnedTabs();
    if (wasActive) {
      final target = _winTabs[_winActiveTab];
      setState(() => _winShowTabPreview(target));
      _winLoadForTab(target, target.url);
    }
  }

  /// Ctrl/中クリックで受け取った URL をバックグラウンドの新タブに開く
  /// (= ブラウザの Ctrl+クリックと同じく、 アクティブタブは切り替えない)。
  void _openInNewWinTab(String url) {
    if (url.isEmpty || _winTabs.length >= _kMaxWinTabs) return;
    final tab = _WinTab(url: url, title: '');
    setState(() {
      _winTabs.add(tab);
    });
    _showWinEmbedToast('新しいタブで開きました');
    // タブに動画タイトルを付ける (= ユーザー要望: タブが「タブ4」 のままだと
    //   何のタブか分からない)。
    _fetchAndSetTabTitle(tab, url);
  }

  /// 外部 (Ctrl+U / 「YouTube を開く」 / 動画を開く 等) から、 既に開いている
  /// このブラウズ用シートへ新しいタブとして URL を開く (= ユーザー要望:
  /// 新しい動画や Ctrl+U は新しいタブで開く)。 動画ならタイトルをタブに付ける。
  void openUrlInNewTab(String url, {bool activate = true}) {
    if (url.isEmpty) return;
    if (_winTabs.length >= _kMaxWinTabs) {
      // 上限に達しているときは現在のタブで開く。
      final target = _winTabs[_winActiveTab];
      setState(() {
        target.url = url;
        _winShowTabPreview(target);
        _loading = true;
      });
      _winLoadForTab(target, url);
      return;
    }
    final tab = _WinTab(url: url, title: '');
    setState(() {
      _winTabs.add(tab);
      if (activate) {
        _winActiveTab = _winTabs.length - 1;
        _winShowTabPreview(tab);
        _loading = true;
      }
    });
    if (activate) _winLoadForTab(tab, url);
    _fetchAndSetTabTitle(tab, url);
  }

  /// タブの URL が YouTube 動画なら oEmbed でタイトルを取得し、 タブ名に設定する。
  /// タブ実体 (`_WinTab`) を直接更新するので、 並び替え/切替が起きても正しい
  /// タブにタイトルが付く。
  Future<void> _fetchAndSetTabTitle(_WinTab tab, String url) async {
    final vid = _extractVideoIdFromWin(url);
    if (vid == null) return;
    try {
      final resp = await http.get(Uri.parse(
          'https://www.youtube.com/oembed?url=https://www.youtube.com/watch?v=$vid&format=json'));
      if (resp.statusCode != 200) return;
      final data = jsonDecode(resp.body);
      final title =
          (data is Map ? (data['title'] ?? '') : '').toString().trim();
      if (title.isEmpty || !mounted || !_winTabs.contains(tab)) return;
      setState(() => tab.title = title);
    } catch (_) {}
  }

  /// 直近に閉じたタブを開き直す (Ctrl+Shift+T)。
  void _reopenClosedWinTab() {
    if (_closedWinTabs.isEmpty || _winTabs.length >= _kMaxWinTabs) return;
    final t = _closedWinTabs.removeLast();
    late final _WinTab target;
    setState(() {
      target = _WinTab(url: t.url, title: t.title);
      _winTabs.add(target);
      _winActiveTab = _winTabs.length - 1;
      _winShowTabPreview(target);
      _loading = true;
    });
    _winLoadForTab(target, t.url);
  }

  /// Ctrl+W = アクティブタブを閉じる (最後の 1 枚ならシート全体を閉じる)。
  /// Ctrl+Shift+T = 閉じたタブを復元。
  bool _handleWinTabHotkey(KeyEvent e) {
    if (e is! KeyDownEvent) return false;
    if (!mounted) return false;
    final ctrl = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    if (!ctrl) return false;
    final shift = HardwareKeyboard.instance.isShiftPressed;
    if (e.logicalKey == LogicalKeyboardKey.keyW && !shift) {
      if (_winTabs.length <= 1) {
        // 最後の 1 枚 → ブラウザのようにウィンドウ (シート) ごと閉じる。
        // 閉じる前に現在のタブを保存しておくと、 次回起動時に自動復元される。
        Navigator.of(context).maybePop();
      } else {
        _closeWinTab(_winActiveTab);
      }
      return true;
    }
    if (e.logicalKey == LogicalKeyboardKey.keyT && shift) {
      _reopenClosedWinTab();
      return true;
    }
    return false;
  }

  /// 指定タブに任意サイトを開く（タブ右クリックの「○○を開く」から）。
  void _openSiteInTab(int i, String url, String name) {
    if (i < 0 || i >= _winTabs.length) return;
    final target = _winTabs[i];
    setState(() {
      target.url = url;
      target.title = name;
      _winActiveTab = i;
      _winShowTabPreview(target);
      _loading = true;
    });
    _winLoadForTab(target, url);
    if (target.pinned) _winSavePinnedTabs();
  }

  /// 今見ているタブをお気に入り (保持) に登録 / 解除する
  /// (= ユーザー要望: タブの右クリックを知らなくても押すだけで登録できる
  /// ボタン)。 タブの右クリックメニューの「お気に入り」 と同じ保存先なので、
  /// どちらから登録しても同じ一覧に載る。
  void _toggleActiveTabFavorite() {
    if (_winActiveTab < 0 || _winActiveTab >= _winTabs.length) return;
    final tab = _winTabs[_winActiveTab];
    // 今実際に見ている URL で登録する (タブ作成時の URL のままだと、
    //   動画を辿った後に押した時に古いページが登録されてしまう)。
    if (_currentUrl.isNotEmpty && !tab.pinned) tab.url = _currentUrl;
    setState(() => tab.pinned = !tab.pinned);
    // ignore: discarded_futures
    _winSavePinnedTabs();
    final p = context.read<MindMapProvider>();
    _showWinEmbedToast(
        p.t(tab.pinned ? 'pane.favoriteAdded' : 'winTab.favRemoved'));
    // 題名がまだ無ければ取りに行く (お気に入り一覧で分かるように)。
    if (tab.pinned && tab.title.trim().isEmpty) {
      // ignore: discarded_futures
      _fetchAndSetTabTitle(tab, tab.url);
    }
  }

  /// タブ右クリックのメニュー: お気に入り(保持) 切替 + フォルダー + サイト。
  Future<void> _showWinTabMenu(Offset pos, int i) async {
    if (i < 0 || i >= _winTabs.length) return;
    final pinned = _winTabs[i].pinned;
    final tab = _winTabs[i];
    final isSelected = _winSelectedTabs.contains(tab);
    final selCount = _winSelectedTabs.length;
    final selected = await showMenu<String>(
      context: context,
      color: const Color(0xFF22222E),
      position: RelativeRect.fromLTRB(pos.dx, pos.dy, pos.dx, pos.dy),
      items: [
        PopupMenuItem<String>(
          value: 'pin',
          child: Row(children: [
            Icon(pinned ? Icons.star_rounded : Icons.star_border_rounded,
                color: const Color(0xFFFFB347), size: 18),
            const SizedBox(width: 8),
            Text(
                pinned
                    ? context.read<MindMapProvider>().t('winTab.favRemove')
                    : context.read<MindMapProvider>().t('winTab.favAddKeep'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        PopupMenuItem<String>(
          value: 'folder',
          child: Row(children: [
            const Icon(Icons.create_new_folder_rounded,
                color: Color(0xFFFFB347), size: 18),
            const SizedBox(width: 8),
            Text(context.read<MindMapProvider>().t('folder.saveTitle'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        // ── 複数選択 → まとめてフォルダーへ (= ユーザー要望) ──
        PopupMenuItem<String>(
          value: 'select',
          child: Row(children: [
            Icon(
                isSelected
                    ? Icons.check_box_rounded
                    : Icons.check_box_outline_blank_rounded,
                color: const Color(0xFF4FC3F7),
                size: 18),
            const SizedBox(width: 8),
            Text(
                context
                    .read<MindMapProvider>()
                    .t(isSelected ? 'winTab.unselect' : 'winTab.select'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        if (selCount > 0)
          PopupMenuItem<String>(
            value: 'saveSelected',
            child: Row(children: [
              const Icon(Icons.drive_file_move_rounded,
                  color: Color(0xFF43B97F), size: 18),
              const SizedBox(width: 8),
              Flexible(
                child: Text(
                    '${context.read<MindMapProvider>().t('winTab.saveSelected')}'
                    ' (${context.read<MindMapProvider>().t('winTab.selectedCount').replaceFirst('{n}', '$selCount')})',
                    style: const TextStyle(color: Colors.white, fontSize: 13)),
              ),
            ]),
          ),
        PopupMenuItem<String>(
          value: 'newFolder',
          child: Row(children: [
            const Icon(Icons.folder_special_rounded,
                color: Color(0xFFFFB347), size: 18),
            const SizedBox(width: 8),
            Text(context.read<MindMapProvider>().t('winTab.newFolder'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        const PopupMenuDivider(),
        ..._winSites.map((s) => PopupMenuItem<String>(
              value: 'site:${s.$1}',
              child: Text(
                  context
                      .read<MindMapProvider>()
                      .t('folder.openX')
                      .replaceFirst('{name}', s.$1),
                  style: const TextStyle(color: Colors.white, fontSize: 13)),
            )),
      ],
    );
    if (selected == null || !mounted) return;
    if (selected == 'pin') {
      setState(() {
        // アクティブタブは現在地を反映してからピン留め（正しい URL を保存）
        if (i == _winActiveTab && identical(_winTabs[i], _winDisplayedTab)) {
          _winTabs[i].url = _currentUrl;
          if (_currentTitle.isNotEmpty) _winTabs[i].title = _currentTitle;
        }
        _winTabs[i].pinned = !pinned;
      });
      _winSavePinnedTabs();
    } else if (selected == 'folder') {
      _winSaveTabToFolder(i);
    } else if (selected == 'select') {
      _toggleWinTabSelection(tab);
    } else if (selected == 'saveSelected') {
      _winSaveTabsToFolder(_winSelectedTabs.toList());
    } else if (selected == 'newFolder') {
      _winCreateFolder();
    } else if (selected.startsWith('site:')) {
      final name = selected.substring(5);
      final site = _winSites.firstWhere((s) => s.$1 == name,
          orElse: () => _winSites.first);
      _openSiteInTab(i, site.$2, site.$1);
    }
  }

  /// サイトボタン: 一覧から選んで「新しいタブ」で開く
  /// (= ユーザー要望: LINE 等のサイトを開くボタン)。
  Future<void> _showWinNewTabSiteMenu(Offset pos) async {
    final selected = await showMenu<String>(
      context: context,
      color: const Color(0xFF22222E),
      position: RelativeRect.fromLTRB(pos.dx, pos.dy, pos.dx, pos.dy),
      items: _winSites
          .map((s) => PopupMenuItem<String>(
                value: s.$1,
                child: Text(
                    context
                        .read<MindMapProvider>()
                        .t('folder.openXNewTab')
                        .replaceFirst('{name}', s.$1),
                    style: const TextStyle(color: Colors.white, fontSize: 13)),
              ))
          .toList(),
    );
    if (selected == null || !mounted) return;
    final site = _winSites.firstWhere((s) => s.$1 == selected,
        orElse: () => _winSites.first);
    if (_winTabs.length >= _kMaxWinTabs) {
      _openSiteInTab(_winActiveTab, site.$2, site.$1);
      return;
    }
    late final _WinTab target;
    setState(() {
      target = _WinTab(url: site.$2, title: site.$1);
      _winTabs.add(target);
      _winActiveTab = _winTabs.length - 1;
      _winShowTabPreview(target);
      _loading = true;
    });
    _winLoadForTab(target, site.$2);
  }

  /// お気に入り(保持)タブを SharedPreferences に保存。
  Future<void> _winSavePinnedTabs() async {
    try {
      final pinned = _winTabs
          .where((t) => t.pinned)
          .map((t) => {'url': t.url, 'title': t.title})
          .toList();
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_kPinnedTabsPrefKey, jsonEncode(pinned));
    } catch (_) {}
  }

  /// 起動時にお気に入り(保持)タブを復元する
  /// (= ユーザー要望: お気に入り登録したタブは開き直しても保持)。
  Future<void> _winRestorePinnedTabs() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kPinnedTabsPrefKey);
      if (raw == null || raw.isEmpty) return;
      final list = jsonDecode(raw);
      if (list is! List) return;
      final restored = <_WinTab>[];
      for (final e in list) {
        if (e is Map) {
          final u = (e['url'] ?? '').toString();
          if (u.isEmpty) continue;
          restored.add(_WinTab(
              url: u, title: (e['title'] ?? '').toString(), pinned: true));
        }
      }
      if (restored.isEmpty || !mounted) return;
      setState(() {
        // SharedPreferences 待ちの間にユーザーが開いたタブを消さないよう、
        // 復元一覧で置換せず既存 tab identity へマージする。
        final activeTab =
            (_winActiveTab >= 0 && _winActiveTab < _winTabs.length)
                ? _winTabs[_winActiveTab]
                : _winTabs.first;
        final tabs = List<_WinTab>.from(_winTabs);
        for (final saved in restored) {
          final existing = tabs.indexWhere((tab) => tab.url == saved.url);
          if (existing >= 0) {
            final tab = tabs[existing];
            tab.pinned = true;
            if (tab.title.isEmpty) tab.title = saved.title;
          } else if (tabs.length < _kMaxWinTabs) {
            tabs.add(saved);
          }
        }
        _winTabs = tabs;
        final activeIndex =
            _winTabs.indexWhere((tab) => identical(tab, activeTab));
        _winActiveTab = activeIndex >= 0 ? activeIndex : 0;
        if (!_winTabIsOpen(_winDisplayedTab)) {
          _winDisplayedTab = _winTabs[_winActiveTab];
        }
      });
    } catch (_) {}
  }

  /// 閉じるときに現在のタブ一覧を保存する（次回の「前のタブを復元」用）。
  Future<void> _winSaveLastTabs() async {
    try {
      final tabs = _winTabs
          .map((t) => {'url': t.url, 'title': t.title})
          .where((m) => (m['url'] ?? '').isNotEmpty)
          .toList();
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_kLastTabsPrefKey, jsonEncode(tabs));
    } catch (_) {}
  }

  /// 「前回のタブ自動復元」 を 1 アプリセッションにつき 1 回だけに制限する。
  /// これがないと、 タブを閉じて即 Ctrl+U 等で開き直すたびに前回タブが復元され、
  /// 同じ動画タブが 2 重に開いてしまう (= ユーザー報告)。 アプリ再起動 (= 別
  /// セッション) では false に戻るので、 起動後の継続性は保たれる。
  static bool _winLastTabsRestoredThisSession = false;

  /// 起動時、お気に入り復元の後に「前回開いていたタブ」を **確認ダイアログ
  /// なしで自動復元** する (= ユーザー要望: 「タブを復元しますか？」 は出さない)。
  /// お気に入りや現在開いているタブと重複する URL は除外する。
  /// アプリセッション中 2 回目以降の起動では復元しない (= 2 重タブ防止)。
  Future<void> _winMaybePromptRestoreLastTabs() async {
    if (_winLastTabsRestoredThisSession) return;
    _winLastTabsRestoredThisSession = true;
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kLastTabsPrefKey);
      if (raw == null || raw.isEmpty) return;
      final list = jsonDecode(raw);
      if (list is! List) return;
      final existing = _winTabs.map((t) => t.url).toSet();
      final candidates = <_WinTab>[];
      for (final e in list) {
        if (e is Map) {
          final u = (e['url'] ?? '').toString();
          if (u.isEmpty || existing.contains(u)) continue;
          if (candidates.any((c) => c.url == u)) continue; // 重複除外
          candidates.add(_WinTab(url: u, title: (e['title'] ?? '').toString()));
        }
      }
      if (candidates.isEmpty || !mounted) return;
      // 確認ダイアログは出さず、 そのまま自動で復元する。
      setState(() {
        for (final t in candidates) {
          if (_winTabs.length >= _kMaxWinTabs) break;
          _winTabs.add(t);
        }
      });
    } catch (_) {}
  }

  // ── タブのフォルダー（保存グループ・ブックマーク風） ──
  // (= ユーザー要望: フォルダーにタブを格納)。YouTube/Google 検索で共通の
  //   TabFolderStore に保存し、フォルダーを開くと中のタブをまとめて開く。

  /// タブ 1 枚を「URL + 題名」 の記録にする。 表示中のタブは、 タブ作成時の
  /// URL ではなく今見ているページを保存する。
  Map<String, String> _winTabRecord(_WinTab t) {
    final isDisplayed = identical(t, _winDisplayedTab);
    final url = (isDisplayed && _currentUrl.isNotEmpty) ? _currentUrl : t.url;
    final title = (isDisplayed && _currentTitle.isNotEmpty)
        ? _currentTitle
        : t.title;
    return {'url': url, 'title': title};
  }

  /// タブ i を任意のフォルダーに保存する。
  Future<void> _winSaveTabToFolder(int i) async {
    if (i < 0 || i >= _winTabs.length) return;
    await _winSaveTabsToFolder([_winTabs[i]]);
  }

  /// タブをまとめてフォルダーへ保存する (= ユーザー要望: 複数選択 +
  /// ドラッグ＆ドロップでまとめて保存)。 [folderName] を渡すとフォルダー
  /// 選択のダイアログを出さずにそこへ入れる。
  Future<void> _winSaveTabsToFolder(List<_WinTab> tabs,
      {String? folderName}) async {
    final records = tabs
        .map(_winTabRecord)
        .where((e) => (e['url'] ?? '').isNotEmpty)
        .toList();
    if (records.isEmpty) return;
    final folders = await TabFolderStore.load();
    if (!mounted) return;
    final name =
        folderName ?? await _winPickFolderName(folders.keys.toList());
    if (name == null || name.isEmpty || !mounted) return;
    final list = folders.putIfAbsent(name, () => []);
    var added = 0;
    for (final r in records) {
      if (!list.any((e) => e['url'] == r['url'])) {
        list.add(r);
        added++;
      }
    }
    await TabFolderStore.save(folders);
    if (!mounted) return;
    setState(() {
      _winSelectedTabs.clear();
      _winTabSelectMode = false;
      _winFolderNames = folders.keys.toList();
    });
    final p = context.read<MindMapProvider>();
    _showWinEmbedToast(records.length > 1
        ? p
            .t('folder.savedNTo')
            .replaceFirst('{n}', '${added == 0 ? records.length : added}')
            .replaceFirst('{name}', name)
        : p.t('folder.savedTo').replaceFirst('{name}', name));
  }

  /// 空のフォルダーを作る (= ユーザー要望: ヘッダーのタブからフォルダーを
  /// 作れるように)。 作った直後に、 選んでいるタブがあればそこへ入れる。
  Future<void> _winCreateFolder({List<_WinTab>? withTabs}) async {
    final provider = context.read<MindMapProvider>();
    final name = await _winAskFolderName(provider.t('winTab.newFolder'));
    if (name == null || name.trim().isEmpty || !mounted) return;
    final folderName = name.trim();
    final tabs = withTabs ?? _winSelectedTabs.toList();
    if (tabs.isNotEmpty) {
      await _winSaveTabsToFolder(tabs, folderName: folderName);
      return;
    }
    final folders = await TabFolderStore.load();
    folders.putIfAbsent(folderName, () => []);
    await TabFolderStore.save(folders);
    if (!mounted) return;
    setState(() => _winFolderNames = folders.keys.toList());
    _showWinEmbedToast(context
        .read<MindMapProvider>()
        .t('winTab.folderCreated')
        .replaceFirst('{name}', folderName));
  }

