      String folderName, List<Map<String, String>> tabs) async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final items = List<Map<String, String>>.from(tabs);
    await showDialog<void>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            const Icon(Icons.folder_open_rounded,
                color: Color(0xFFFFB347), size: 20),
            const SizedBox(width: 8),
            Expanded(
              child: Text(folderName,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(color: Colors.white, fontSize: 15)),
            ),
          ]),
          content: SizedBox(
            width: 360,
            child: ConstrainedBox(
              constraints: const BoxConstraints(maxHeight: 380),
              child: items.isEmpty
                  ? Text(provider.t('folder.empty'),
                      style: const TextStyle(color: Colors.white54))
                  : ListView(
                      shrinkWrap: true,
                      children: [
                        for (int i = 0; i < items.length; i++)
                          ListTile(
                            dense: true,
                            leading: const Icon(Icons.public_rounded,
                                color: Color(0xFF4FC3F7), size: 18),
                            title: Text(
                              (items[i]['title'] ?? '').isNotEmpty
                                  ? items[i]['title']!
                                  : (items[i]['url'] ?? ''),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: Colors.white, fontSize: 13),
                            ),
                            subtitle: Text(items[i]['url'] ?? '',
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                    color: Colors.white38, fontSize: 11)),
                            trailing: IconButton(
                              icon: const Icon(Icons.close_rounded,
                                  color: Color(0xFFE57373), size: 18),
                              onPressed: () async {
                                final url = items[i]['url'];
                                final folders = await TabFolderStore.load();
