  /// フォルダー内のタブをまとめて開く。
  void _winOpenFolder(List<Map<String, String>> tabs) {
    if (tabs.isEmpty) return;
    bool added = false;
    _WinTab? target;
    setState(() {
      for (final t in tabs) {
        if (_winTabs.length >= _kMaxWinTabs) break;
        final u = t['url'] ?? '';
        if (u.isEmpty) continue;
        target = _WinTab(url: u, title: t['title'] ?? '');
        _winTabs.add(target!);
        _winActiveTab = _winTabs.length - 1;
        added = true;
      }
      if (added && target != null) {
        _winShowTabPreview(target!);
        _loading = true;
      }
    });
    if (added && target != null) _winLoadForTab(target!, target!.url);
  }

  /// タブの選択を切り替える (選択モード / 長押し / Ctrl+クリック /
  /// 右クリックメニュー)。 1 つでも選んだら選択モードに入れて、 続けて
  /// クリックだけで選び足せるようにする。
  void _toggleWinTabSelection(_WinTab tab) {
    setState(() {
      if (!_winSelectedTabs.remove(tab)) {
        _winSelectedTabs.add(tab);
        _winTabSelectMode = true;
      }
      if (_winSelectedTabs.isEmpty) _winTabSelectMode = false;
    });
  }

  /// ドラッグ中に出すフォルダーの受け皿 (= ユーザー要望: タブをドラッグ＆
  /// ドロップでまとめて保存)。 既存フォルダーごとの受け皿 + 「新しい
  /// フォルダー」 を並べる。
  Widget _buildWinFolderDropZone() {
    final provider = context.read<MindMapProvider>();
    Widget chip({
      required IconData icon,
      required Color color,
      required String label,
      required bool highlighted,
    }) =>
        Container(
          margin: const EdgeInsets.symmetric(horizontal: 3),
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
          decoration: BoxDecoration(
            color: highlighted
                ? color.withValues(alpha: 0.25)
                : Colors.white.withValues(alpha: 0.05),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
                color: highlighted ? color : Colors.white24,
                width: highlighted ? 1.6 : 1),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            Icon(icon, size: 14, color: color),
            const SizedBox(width: 5),
            Text(label,
                style: TextStyle(
                    color: highlighted ? Colors.white : Colors.white70,
                    fontSize: 11.5,
                    fontWeight: FontWeight.w600)),
          ]),
        );

    return Container(
      height: 38,
      color: const Color(0xFF161628),
      padding: const EdgeInsets.symmetric(horizontal: 6),
      child: Row(children: [
        const Icon(Icons.drive_file_move_rounded,
            size: 15, color: Color(0xFFFFB347)),
        const SizedBox(width: 6),
        Expanded(
          child: ListView(
            scrollDirection: Axis.horizontal,
            children: [
              for (final name in _winFolderNames)
                DragTarget<List<_WinTab>>(
                  onWillAcceptWithDetails: (_) => true,
                  onAcceptWithDetails: (d) {
                    // ignore: discarded_futures
                    _winSaveTabsToFolder(d.data, folderName: name);
                  },
                  builder: (_, cand, __) => chip(
                    icon: Icons.folder_rounded,
                    color: const Color(0xFFFFB347),
                    label: name,
                    highlighted: cand.isNotEmpty,
                  ),
                ),
              DragTarget<List<_WinTab>>(
                onWillAcceptWithDetails: (_) => true,
                onAcceptWithDetails: (d) {
                  // ignore: discarded_futures
                  _winCreateFolder(withTabs: d.data);
                },
                builder: (_, cand, __) => chip(
                  icon: Icons.create_new_folder_rounded,
                  color: const Color(0xFF43B97F),
                  label: provider.t('winTab.newFolder'),
                  highlighted: cand.isNotEmpty,
                ),
              ),
            ],
          ),
        ),
      ]),
    );
  }

  /// 上部のタブバー（タブ一覧 + サイトボタン + 新規タブ「＋」）。
  Widget _buildWinTabBar() {
    final provider = context.read<MindMapProvider>();
    return Container(
      height: 34,
      color: const Color(0xFF0E0E1A),
      padding: const EdgeInsets.symmetric(horizontal: 4),
      child: Row(children: [
        Expanded(
          child: ListView.builder(
            scrollDirection: Axis.horizontal,
            itemCount: _winTabs.length,
            itemBuilder: (_, i) {
              final tab = _winTabs[i];
              final active = i == _winActiveTab;
              final pinned = tab.pinned;
              final selected = _winSelectedTabs.contains(tab);
              final tabBody = Container(
                constraints: const BoxConstraints(maxWidth: 190),
                margin: const EdgeInsets.symmetric(horizontal: 2, vertical: 5),
                padding: const EdgeInsets.only(left: 8, right: 4),
                decoration: BoxDecoration(
                  color: selected
                      ? const Color(0xFF4FC3F7).withValues(alpha: 0.18)
                      : (active
                          ? const Color(0xFF2A2A40)
                          : Colors.transparent),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                      color: selected
                          ? const Color(0xFF4FC3F7)
                          : (active
                              ? const Color(0xFF6C63FF)
                              : Colors.white12),
                      width: selected ? 1.6 : 1),
                ),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  if (selected) ...[
                    const Icon(Icons.check_circle_rounded,
                        size: 12, color: Color(0xFF4FC3F7)),
                    const SizedBox(width: 3),
                  ] else if (pinned) ...[
                    const Icon(Icons.star_rounded,
                        size: 12, color: Color(0xFFFFB347)),
                    const SizedBox(width: 3),
                  ],
                  Flexible(
                    child: Text(
                      _winTabLabel(i),
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                          color: active || selected
                              ? Colors.white
                              : Colors.white54,
                          fontSize: 12),
                    ),
                  ),
                  if (_winTabs.length > 1)
                    InkWell(
                      onTap: () => _closeWinTab(i),
                      borderRadius: BorderRadius.circular(10),
                      child: const Padding(
                        padding: EdgeInsets.all(3),
                        child: Icon(Icons.close_rounded,
                            size: 14, color: Colors.white38),
                      ),
                    ),
                ]),
              );
              // ドラッグで運ぶ中身: 選んでいるタブがあればまとめて、
              //   無ければこの 1 枚だけ (= ユーザー要望: 複数まとめて保存)。
              List<_WinTab> payload() =>
                  (selected && _winSelectedTabs.isNotEmpty)
                      ? _winSelectedTabs.toList()
                      : [tab];
              return Draggable<List<_WinTab>>(
                data: payload(),
                dragAnchorStrategy: pointerDragAnchorStrategy,
                onDragStarted: () {
                  // ignore: discarded_futures
                  _winRefreshFolderNames();
                  setState(() => _winTabDragging = true);
                },
                onDraggableCanceled: (_, __) =>
                    setState(() => _winTabDragging = false),
                onDragEnd: (_) => setState(() => _winTabDragging = false),
                feedback: Material(
                  color: Colors.transparent,
                  child: Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                    decoration: BoxDecoration(
                      color: const Color(0xFF2A2A40),
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(color: const Color(0xFF4FC3F7)),
                    ),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      const Icon(Icons.tab_rounded,
                          size: 14, color: Color(0xFF4FC3F7)),
                      const SizedBox(width: 6),
                      ConstrainedBox(
                        constraints: const BoxConstraints(maxWidth: 200),
                        child: Text(
                          payload().length > 1
                              ? provider
                                  .t('winTab.selectedCount')
                                  .replaceFirst('{n}', '${payload().length}')
                              : _winTabLabel(i),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                              color: Colors.white, fontSize: 12),
                        ),
                      ),
                    ]),
                  ),
                ),
                childWhenDragging: Opacity(opacity: 0.35, child: tabBody),
                child: GestureDetector(
                  onTap: () {
                    // 「タブを選ぶ」 モード中、 または Ctrl / ⌘ + クリックで
                    //   選択のオン・オフ (= ユーザー要望: タブを複数選択)。
                    //   ふつうのクリックは今まで通り切替。
                    if (_winTabSelectMode ||
                        HardwareKeyboard.instance.isControlPressed ||
                        HardwareKeyboard.instance.isMetaPressed) {
                      _toggleWinTabSelection(tab);
                      return;
                    }
                    _switchWinTab(i);
                  },
                  // 長押しでも選べる (= マウスだけで複数選択できるように)。
                  onLongPress: () => _toggleWinTabSelection(tab),
                  onSecondaryTapDown: (d) =>
                      _showWinTabMenu(d.globalPosition, i),
                  child: tabBody,
                ),
              );
            },
          ),
        ),
        // ── 画面更新はツールバー側 (上の段) に 1 つだけ置く ──
        //    タブ列にも足したところ、 同じボタンが 2 つ並んでしまったので
        //    こちらは外した (= ユーザー報告: 二重に付いている)。
        // ── 「タブを選ぶ」 ボタンは廃止 (= ユーザー要望: Ctrl / Shift +
        //    クリックでまとめて選んで、 ドラッグ&ドロップでフォルダーへ
        //    入れられるので要らない)。 モード自体の仕組み
        //    (`_winTabSelectMode`) は Ctrl+クリック経路で使うため残す。 ──
        // ── 選んでいるタブの件数 + まとめて保存 / 選択解除 ──
        if (_winSelectedTabs.isNotEmpty) ...[
          Tooltip(
            message: provider.t('winTab.saveSelected'),
            child: InkWell(
              onTap: () {
                // ignore: discarded_futures
                _winSaveTabsToFolder(_winSelectedTabs.toList());
              },
              borderRadius: BorderRadius.circular(8),
              child: Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                decoration: BoxDecoration(
                  color: const Color(0xFF4FC3F7).withValues(alpha: 0.15),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: const Color(0xFF4FC3F7)),
                ),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  const Icon(Icons.drive_file_move_rounded,
                      size: 14, color: Color(0xFF4FC3F7)),
                  const SizedBox(width: 4),
                  Text(
                      provider
                          .t('winTab.selectedCount')
                          .replaceFirst('{n}', '${_winSelectedTabs.length}'),
                      style: const TextStyle(
                          color: Color(0xFF4FC3F7),
                          fontSize: 11,
                          fontWeight: FontWeight.w700)),
                ]),
              ),
            ),
          ),
          IconButton(
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 26, minHeight: 26),
            tooltip: provider.t('winTab.clearSelection'),
            icon: const Icon(Icons.close_rounded,
                size: 15, color: Colors.white54),
            onPressed: () => setState(() {
              _winSelectedTabs.clear();
              _winTabSelectMode = false;
            }),
          ),
        ],
        // ── このページをお気に入り登録 (= ユーザー要望: タブの右クリック
        //    以外に、 押すだけのボタンが欲しい) ──
        //    今見ているタブを「お気に入り (保持)」 にする。 既に登録済みなら
        //    解除する。 星の塗りで今の状態が分かる。
        Builder(builder: (_) {
          final bool activeTabPinned = _winActiveTab >= 0 &&
              _winActiveTab < _winTabs.length &&
              _winTabs[_winActiveTab].pinned;
          return GestureDetector(
            onTap: _toggleActiveTabFavorite,
            behavior: HitTestBehavior.opaque,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 6),
              child: Tooltip(
                message: context.read<MindMapProvider>().t(
                    activeTabPinned ? 'winTab.favRemove' : 'winTab.favAddKeep'),
                child: Icon(
                  activeTabPinned
                      ? Icons.star_rounded
                      : Icons.star_border_rounded,
                  color: const Color(0xFFFFB347),
                  size: 19,
                ),
              ),
            ),
          );
        }),
        // フォルダーボタン（保存したタブのグループを開く / 管理 / 新規作成）。
        // ここへタブを落としてもフォルダーへ保存できる (= ユーザー要望:
        // ドラッグ＆ドロップでまとめて保存)。 長押し・右クリックで新規作成。
        DragTarget<List<_WinTab>>(
          onWillAcceptWithDetails: (_) => true,
          onAcceptWithDetails: (d) {
            // ignore: discarded_futures
            _winSaveTabsToFolder(d.data);
          },
          builder: (_, cand, __) => GestureDetector(
            onTap: _showWinFoldersMenu,
            onSecondaryTap: () {
              // ignore: discarded_futures
              _winCreateFolder();
            },
            onLongPress: () {
              // ignore: discarded_futures
              _winCreateFolder();
            },
            behavior: HitTestBehavior.opaque,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 6),
              child: Tooltip(
                message: '${provider.t('winTab.folderTip')}\n'
                    '${provider.t('winTab.dragToFolder')}',
                child: Icon(
                    cand.isNotEmpty
                        ? Icons.create_new_folder_rounded
                        : Icons.folder_rounded,
                    color: cand.isNotEmpty
                        ? const Color(0xFF43B97F)
                        : const Color(0xFFFFB347),
                    size: cand.isNotEmpty ? 21 : 18),
              ),
            ),
          ),
        ),
        // ── 「新しいタブ」 と「サイトを開く」 を + マークに統合 (= ユーザー要望:
        //    地球アイコンを + に統合)。 + を押すとサイト選択メニューが開き、
        //    選んだサイト (YouTube / Google / X 等) を新しいタブで開く。
        GestureDetector(
          onTapDown: (d) => _showWinNewTabSiteMenu(d.globalPosition),
          behavior: HitTestBehavior.opaque,
          child: Padding(
            padding: EdgeInsets.symmetric(horizontal: 6, vertical: 6),
            child: Tooltip(
              message: context.read<MindMapProvider>().t('winTab.newTabTip'),
              child: Icon(Icons.add_rounded, color: Colors.white70, size: 20),
            ),
          ),
        ),
      ]),
    );
  }

  @override
  Widget build(BuildContext context) {
    // ── 動画メモ / AI のショートカット (= ユーザー要望) ──
    // Ctrl+M でメモ、 Ctrl+Shift+A で AI をトグル。 WebView にフォーカスが
    // ある間はネイティブ側がキーを消費するため、 ツールバー/パネル側に
    // フォーカスがあるときに効く (ベストエフォート)。
    // _currentUrl から動画 ID が取れれば YouTube 動画ページと確定できるので、
    //   フラグ (_isYoutube) の確定を待たずにボタンを出す (= ユーザー報告対応)。
    return CallbackShortcuts(
      bindings: <ShortcutActivator, VoidCallback>{
        // ── メモ / AI は動画を開く前 (検索・一覧の画面) でも使える
        //    (= ユーザー要望: 動画を開く前の YouTube の画面でもメモ欄や
        //    AI チャット欄を開けるように)。 動画かどうかで出し分けない。 ──
        const SingleActivator(LogicalKeyboardKey.keyM, control: true):
            _toggleWinVideoMemoPanel,
        const SingleActivator(LogicalKeyboardKey.keyA,
            control: true, shift: true): _toggleWinVideoAiPanel,
        // ── Esc で閉じない設定 (= ユーザー要望: YouTube の画面が Esc で
        //    閉じるのを止めたい)。 何もしない割り当てで消費して、 既定の
        //    「ダイアログを閉じる」 まで届かせない。 ──
        if (!context.watch<MindMapProvider>().closeViewerWithEsc)
          const SingleActivator(LogicalKeyboardKey.escape): () {},
      },
      child: Focus(
        autofocus: true,
        child: Column(children: [
          // タブバー（上部・最大 5 タブ。+ で YouTube ホームを別タブで開く）
          _buildWinTabBar(),
          // タブをドラッグしている間だけ出るフォルダーの受け皿 (= ユーザー要望:
          //   タブを複数選んでドラッグ＆ドロップでまとめて保存)。
          if (_winTabDragging) _buildWinFolderDropZone(),
          // タイトルバー
          Container(
            color: const Color(0xFF1A1A2E),
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
            child: Row(children: [
              // ── 戻る / 進むボタン ──
              // Windows ではジェスチャー戻るが効かないため、明示的なボタンで
              // ページ遷移できるようにする (= 「ジェスチャーで戻ろうとしたら
              // アプリが閉じる」要望への対応)。
              // window.history.back() / forward() を JS で叩くのが最も汎用。
              // canGoBack / canGoForward の状態取得は WebView2 API では一手間
              // かかるため、今は常時タップ可能 (履歴が無ければ何も起きない)。
              IconButton(
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
                iconSize: 18,
                tooltip: context.read<MindMapProvider>().t('btn.back'),
                icon:
                    const Icon(Icons.arrow_back_rounded, color: Colors.white70),
                onPressed: () {
                  _controller
                      .executeScript('try{window.history.back();}catch(e){}');
                },
              ),
              IconButton(
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
                iconSize: 18,
                tooltip: context.read<MindMapProvider>().t('split.forward'),
                icon: const Icon(Icons.arrow_forward_rounded,
                    color: Colors.white70),
                onPressed: () {
                  _controller.executeScript(
                      'try{window.history.forward();}catch(e){}');
                },
              ),
              const SizedBox(width: 4),
              Container(
                width: 24,
                height: 24,
                decoration: BoxDecoration(
                    color: _isYoutube
                        ? const Color(0xFFE53935)
                        : const Color(0xFF4FC3F7),
                    shape: BoxShape.circle),
                child: Icon(
                    _isYoutube
                        ? Icons.play_arrow_rounded
                        : Icons.language_rounded,
                    color: Colors.white,
                    size: 16),
              ),
              const SizedBox(width: 8),
              Expanded(
                  child: Text(
                      _currentTitle.isNotEmpty
                          ? _currentTitle
                          : _isMp4
                              ? _playlist[_playlistIndex]
                                  .split('/')
                                  .last
                                  .split('\\')
                                  .last
                              : (Uri.tryParse(widget.url)?.host ?? widget.url),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 13,
                          fontWeight: FontWeight.bold),
                      overflow: TextOverflow.ellipsis)),
              // 再生速度（YouTube/mp4時）
              //   ★ 開いた時のフラグだけでなく「今見ている URL」 でも判定する
              //     (= ユーザー報告: 再生速度バーが出てこないモードで開く
              //      ことがある)。 動画サイトなら必ずバーを出す。
              if (_isYoutube || _isMp4 || _isLikelyEmbeddedVideoUrl(_currentUrl)) ...[
                // ── 再生速度の上限取得 ──
                // ユーザーが設定した最大値 (1.5〜16.0) を反映する。
                // 現在の _playbackRate が新しい上限を超えていたらクランプ。
                Builder(builder: (ctx) {
                  final maxRate = context.watch<MindMapProvider>().videoMaxRate;
                  if (_playbackRate > maxRate) {
                    // 次フレームで補正 (build 中に setState できないため)
                    WidgetsBinding.instance.addPostFrameCallback((_) {
                      if (mounted) _changeRate(maxRate);
                    });
                  }
                  // divisions: 0.25 刻みになるよう動的に算出
                  final divs = ((maxRate - 1.0) * 4).round().clamp(4, 60);
                  return Row(mainAxisSize: MainAxisSize.min, children: [
                    Text('${_playbackRate.toStringAsFixed(2)}x',
                        style: const TextStyle(
                            color: Colors.white54, fontSize: 11)),
                    SizedBox(
                      width: 120,
                      child: SliderTheme(
                        data: SliderThemeData(
                          trackHeight: 2,
                          thumbShape: const RoundSliderThumbShape(
                              enabledThumbRadius: 5),
                          activeTrackColor: Colors.white.withValues(alpha: 0.5),
                          inactiveTrackColor:
                              Colors.white.withValues(alpha: 0.1),
                          thumbColor: Colors.white,
                          overlayShape:
                              const RoundSliderOverlayShape(overlayRadius: 10),
                        ),
                        child: Slider(
                          value: _playbackRate.clamp(1.0, maxRate),
                          min: 1.0,
                          max: maxRate,
                          divisions: divs,
                          onChanged: _changeRate,
                        ),
                      ),
                    ),
                    // 倍率の上限を変更する設定アイコン
                    IconButton(
                      tooltip:
                          ctx.read<MindMapProvider>().t('video.tip.maxRate'),
                      padding: EdgeInsets.zero,
                      constraints:
                          const BoxConstraints(minWidth: 24, minHeight: 24),
                      iconSize: 14,
                      icon:
                          const Icon(Icons.tune_rounded, color: Colors.white54),
                      onPressed: () => _showMaxRateDialog(ctx),
                    ),
                    // オフライン (mp4) 動画の左右キーのシーク秒数を変更 (= ユーザー
                    //   要望: 飛ぶ時間が長すぎる→10秒既定 + 設定で変更可能に)。
                    if (_isMp4)
                      IconButton(
                        tooltip:
                            context.read<MindMapProvider>().t('seek.title'),
                        padding: EdgeInsets.zero,
                        constraints:
                            const BoxConstraints(minWidth: 24, minHeight: 24),
                        iconSize: 14,
                        icon: const Icon(Icons.fast_forward_rounded,
                            color: Colors.white54),
                        onPressed: () => _showSeekStepDialog(ctx),
                      ),
                  ]);
                }),
                // 再読み込みボタン: 現在の再生位置を保持したまま再ロード
                IconButton(
                  tooltip: context.read<MindMapProvider>().t('player.reload'),
                  icon: const Icon(Icons.refresh_rounded,
                      color: Colors.white70, size: 18),
                  onPressed: () {
                    if (_winActiveTab < 0 || _winActiveTab >= _winTabs.length) {
                      return;
                    }
                    final tab = _winTabs[_winActiveTab];
                    setState(() {
                      _loading = true;
                    });
                    _winLoadForTab(tab, tab.url);
                  },
                ),
                if (_isYoutube ||
                    _currentUrl.startsWith('http://') ||
                    _currentUrl.startsWith('https://'))
                  IconButton(
                    icon: const Icon(Icons.share_rounded,
                        color: Color(0xFF4FC3F7), size: 20),
                    tooltip:
                        context.read<MindMapProvider>().t('ctx.shareVideoUrl'),
                    onPressed: () {
                      final provider = context.read<MindMapProvider>();
                      final shareUrl = _currentUrl
                          .replaceFirst('https://m.youtube.com/',
                              'https://www.youtube.com/')
                          .replaceFirst('http://m.youtube.com/',
                              'https://www.youtube.com/');
                      Clipboard.setData(ClipboardData(text: shareUrl));
                      _showWinEmbedToast(provider.t('ctx.videoUrlCopied'));
                    },
                  ),
              ],
              // ── 動画に入る前の画面 (ホーム / 検索結果 / チャンネル等) でも
              //    画面更新できるように (= ユーザー要望) ──
              // 上の再読み込みは動画ページ限定 (再生位置を保持する版) だったため、
              // 一覧画面では更新手段が無かった。 動画ページ以外ではこちらを出す。
              if (!_isYoutube && !_isMp4)
                IconButton(
                  tooltip: context.read<MindMapProvider>().t('player.reload'),
                  icon: const Icon(Icons.refresh_rounded,
                      color: Colors.white70, size: 18),
                  onPressed: () {
                    if (_winActiveTab < 0 || _winActiveTab >= _winTabs.length) {
                      return;
                    }
                    final tab = _winTabs[_winActiveTab];
                    setState(() => _loading = true);
                    // 表示中の URL があればそれを、 無ければタブの URL を再読込。
                    _winLoadForTab(
                        tab, _currentUrl.isNotEmpty ? _currentUrl : tab.url);
                  },
                ),
              // プレイリストナビゲーション
              if (_playlist.length > 1) ...[
                IconButton(
                  icon: const Icon(Icons.skip_previous_rounded,
                      color: Colors.white54, size: 18),
                  onPressed: _playlistIndex > 0
                      ? () {
                          final tab = _winTabs[_winActiveTab];
                          setState(() {
                            _playlistIndex--;
                            tab.url = _playlist[_playlistIndex];
                            _winShowTabPreview(tab);
                            _loading = true;
                          });
                          _winLoadForTab(tab, tab.url);
                        }
                      : null,
                ),
                Text('${_playlistIndex + 1}/${_playlist.length}',
                    style:
                        const TextStyle(color: Colors.white38, fontSize: 11)),
                IconButton(
                  icon: const Icon(Icons.skip_next_rounded,
                      color: Colors.white54, size: 18),
                  onPressed: _playlistIndex < _playlist.length - 1
                      ? () {
                          final tab = _winTabs[_winActiveTab];
                          setState(() {
                            _playlistIndex++;
                            tab.url = _playlist[_playlistIndex];
                            _winShowTabPreview(tab);
                            _loading = true;
                          });
                          _winLoadForTab(tab, tab.url);
                        }
                      : null,
                ),
              ],
              // 現在の動画/チャンネルをマップに埋め込むボタン
              if (widget.onEmbedUrl != null &&
                  _isEmbeddableYoutubeUrl(_currentUrl))
                IconButton(
                  icon: const Icon(Icons.add_to_photos_rounded,
                      color: Color(0xFF43B97F), size: 20),
                  tooltip: context.read<MindMapProvider>().t('embed.tooltip'),
                  onPressed: () {
                    // ── ユーザー要望: 埋め込みボタンを押しても Player は閉じない ──
                    // 再生リスト視聴中は「この動画だけ / 後ろも全部」を確認して
                    // から埋め込み、 完了をプレイヤー上のトーストで知らせる。
                    _winEmbedWithConfirm();
                  },
                ),
              // ── URL 共有ボタン (= ユーザー要望: 動画の視聴画面内に動画の URL を
              //    共有するボタンが欲しい) ──。 web 動画 (YouTube / http(s)) の時
              //    だけ表示し、 クリップボードへコピーして他アプリへ貼り付け・共有
              //    できるようにする。 ローカルファイルのパスは共有しても無意味なので
              //    対象外。
              // リリース版では動画サイトからの端末保存ボタンは表示しない。
              // ── アプリの外に出す (フローティング) ボタン ──
              //
              // 以前はここが PiP (アプリ内の小窓に切り出す) だった。
              // YouTube の Developer Policies は
              //   「YouTube プレーヤーのいかなる部分・機能も、 改変・上書き・
              //    ブロックしてはならない」
              // と定めており、 プレーヤーを縮小して切り抜く PiP はこれに触れる
              // 恐れがある。 別ウィンドウで YouTube のページをそのまま出す方が
              // ブラウザで開くのと同じ形になり、 プレーヤーに手を加えない。
              // そこで PiP は廃止し、 こちらへ一本化した (= ユーザー判断)。
              if (_extractVideoIdFromWin(_currentUrl) != null)
                IconButton(
                  icon: const Icon(Icons.open_in_new_rounded,
                      color: Color(0xFF4FC3F7), size: 20),
                  tooltip:
                      context.read<MindMapProvider>().t('player.popOutWindow'),
                  onPressed: _popOutVideoToOwnWindow,
                ),
              // ── AI チャット (= ユーザー要望: YouTube だけでなくオフライン
              //    (ダウンロード済み mp4) 動画でも AI チャットを使えるように。
              //    AI ドック (_buildWinVideoAiPanel) は再生ソース非依存なので
              //    表示条件をメモボタンと揃えるだけで mp4 でも動く) ──
              // ── ボタン配置: パネルと同じく AI を左、 メモを右に並べる
              //    (= ユーザー要望: AI が左・メモが右に立ち上がるのでボタンも合わせる)。
              // ── 動画を開く前 (YouTube の検索/一覧の画面) でも出す
              //    (= ユーザー要望: 動画を開く前の画面の時点でメモ欄や AI
              //    チャット欄を開けるように)。 パネルはどちらも再生ソースに
              //    依存しないので、 表示条件から動画判定を外す。 ──
              // ── 右クリック/長押しで AI モデル切替 + 前提条件の画面 (= ユーザー
              //    要望: AI ボタンのモデルアイコンを右クリックで動画メモと同じ
              //    モデル選択 + 前提条件の画面を出す)。 左クリックは AI パネル開閉。 ──
              GestureDetector(
                onSecondaryTapUp: (d) =>
                    _showWinVideoAiSwitchMenu(d.globalPosition),
                // 長押しでも押した位置付近にメニューを出す (= ユーザー要望)。
                onLongPressStart: (d) =>
                    _showWinVideoAiSwitchMenu(d.globalPosition),
                child: IconButton(
                  icon: Icon(
                    Icons.auto_awesome_rounded,
                    color: _videoAiPanelOpen
                        ? const Color(0xFFBA68C8)
                        : Colors.white,
                    size: 20,
                  ),
                  tooltip:
                      '${context.read<MindMapProvider>().t('player.aiChat')} '
                      '(${context.read<MindMapProvider>().t('tooltip.aiMenuPrereqSuffix')})',
                  onPressed: _toggleWinVideoAiPanel,
                ),
              ),
              // ── メモボタン (動画視聴中にメモを取る) ──
              // モバイル版 _FullscreenVideoPage と同等。 タップで画面の上に
              // メモパネルが出る。 動画は止めずに視聴を続けながら入力でき、
              // 「マップに追加」 でメモノードとしてキャンバス上に配置できる。
              // 動画ページ以外 (検索結果・チャンネル一覧など) でも使える
              // (= ユーザー要望)。
              IconButton(
                icon: Icon(
                  _videoMemoPanelOpen
                      ? Icons.sticky_note_2_rounded
                      : Icons.sticky_note_2_outlined,
                  color: _videoMemoPanelOpen
                      ? const Color(0xFFFFB347)
                      : Colors.white,
                  size: 20,
                ),
                tooltip: context.read<MindMapProvider>().t('player.takeMemo'),
                onPressed: _toggleWinVideoMemoPanel,
              ),
              // ── 「画面分割パネルに移動」 ボタン ──
              // 現在再生中の動画/PDF URL を MindMapScreen の画面分割パネルへ
              // 引き継ぎつつ sheet を閉じる。 マップを編集しながら動画/PDF を
              // 見たい時の入口。 onMoveToSplitPanel が渡されていないときは
              // 非表示。
              // ── フローティング化 (= ユーザー要望: YouTube にも
              //    フローティング機能)。 再生位置を URL に載せて、 本体の
              //    浮遊パネルへ引き継ぐ。 ──
              if (widget.onFloatRequest != null)
                IconButton(
                  icon: const Icon(Icons.picture_in_picture_alt_rounded,
                      color: Color(0xFF80CBC4), size: 18),
                  tooltip:
                      context.read<MindMapProvider>().t('split.toFloating'),
                  onPressed: () async {
                    final urlToHandOff =
                        _currentUrl.isNotEmpty ? _currentUrl : widget.url;
                    final handoff = await _withVideoPosition(urlToHandOff);
                    if (!mounted) return;
                    widget.onFloatRequest!(handoff);
                    Navigator.pop(context);
                  },
                ),
              // ── 窓いっぱいに広げる / ペインに戻す (= ユーザー要望:
              //    分割で開いた YouTube を全画面にするボタンが欲しい) ──
              // 分割ペインの中に出ている時だけ。 WebView は作り直さないので
              // 再生は止まらない (= 分割へ移す時のように頭から再生し直しに
              // ならない)。
              if (widget.onToggleFullWindow != null)
                IconButton(
                  icon: Icon(
                      widget.isFullWindow
                          ? Icons.close_fullscreen_rounded
                          : Icons.open_in_full_rounded,
                      color: const Color(0xFF9CCC65),
                      size: 19),
                  tooltip: context.read<MindMapProvider>().t(
                      widget.isFullWindow
                          ? 'common.exitFullscreen'
                          : 'common.fullscreen'),
                  onPressed: widget.onToggleFullWindow,
                ),
              if (widget.onMoveToSplitPanel != null) ...[
                // ── 左画面分割 (= 画面の左に開く) ──
                // 動画視聴中は現在の再生位置を URL に載せて引き継ぐ
                // (= ユーザー要望: 分割にすると頭から再生し直しになる問題)。
                IconButton(
                  icon: _splitPanelIcon(_SplitIconFill.left,
                      color: const Color(0xFFFF6B6B), size: 20),
                  tooltip: _splitBtnTooltip(context, true),
                  onPressed: () async {
                    final urlToHandOff =
                        _currentUrl.isNotEmpty ? _currentUrl : widget.url;
                    final handoff = await _withVideoPosition(urlToHandOff);
                    if (!mounted) return;
                    widget.onMoveToSplitPanel!(handoff, isLeftPanel: true);
                    Navigator.pop(context);
                  },
                ),
                // ── 右画面分割 (= 画面の右に開く) ──
                IconButton(
                  icon: _splitPanelIcon(_SplitIconFill.right,
                      color: const Color(0xFF2196F3), size: 20),
                  tooltip: _splitBtnTooltip(context, false),
                  onPressed: () async {
                    final urlToHandOff =
                        _currentUrl.isNotEmpty ? _currentUrl : widget.url;
                    final handoff = await _withVideoPosition(urlToHandOff);
                    if (!mounted) return;
                    widget.onMoveToSplitPanel!(handoff, isLeftPanel: false);
                    Navigator.pop(context);
                  },
                ),
              ],
              IconButton(
                icon: const Icon(Icons.close, color: Colors.white54, size: 20),
                onPressed: () => Navigator.pop(context),
              ),
            ]),
          ),
          // WebView本体
          //   ★ 動画メモ / AI 欄を「横に並べる」 設定の時は、 動画とパネルを
          //     左右に分ける (= ユーザー要望: PDF のように横に配置するモード)。
          Expanded(
            child: Builder(builder: (lctx) {
              final sideOn =
                  lctx.watch<MindMapProvider>().videoPanelSideBySide;
              final anyPanel = _videoMemoPanelOpen || _videoAiPanelOpen;
              final videoArea = _buildWinVideoArea(context, side: sideOn);
              if (!sideOn || !anyPanel) return videoArea;
              return LayoutBuilder(builder: (bctx, cons) {
                final maxW = cons.maxWidth;
                // 開いているパネルを、 覚えている場所ごとに振り分ける。
                bool open(String id) =>
                    id == 'memo' ? _videoMemoPanelOpen : _videoAiPanelOpen;
                final left = <String>[
                  for (final id in _videoPanelOrder)
                    if (open(id) && _videoPanelSide[id] == 'left') id
                ];
                final right = <String>[
                  for (final id in _videoPanelOrder)
                    if (open(id) && _videoPanelSide[id] != 'left') id
                ];
                final maxSide = (maxW * 0.75).clamp(280.0, 1600.0);
                final wR = right.isEmpty
                    ? 0.0
                    : _videoSidePanelWidth.clamp(280.0, maxSide).toDouble();
                final wL = left.isEmpty
                    ? 0.0
                    : _videoSidePanelWidthLeft.clamp(280.0, maxSide).toDouble();

                // 動画の上に落とした位置を測るための鍵。
                final dropKey = _videoDropAreaKey;

                // ★ GlobalKey で包むことで、 置き場所を変えても作り直さずに
                //   引っ越しさせる (= 中の WebView が生き残り、 固まらない)。
                Widget panelFor(String id, double w) => KeyedSubtree(
                      key: id == 'memo'
                          ? _videoMemoSubtreeKey
                          : _videoAiSubtreeKey,
                      child: id == 'memo'
                          ? _buildWinVideoMemoPanel(
                              context, Size(w, cons.maxHeight))
                          : _buildWinVideoAiPanel(
                              context, Size(w, cons.maxHeight)),
                    );

                // 掴んで落とせる列 (= ユーザー要望: ドラッグ＆ドロップで配置替え)。
                Widget column(List<String> ids, String sideName, double w) {
                  return SizedBox(
                    width: w,
                    child: DragTarget<String>(
                      onWillAcceptWithDetails: (d) => true,
                      onAcceptWithDetails: (d) =>
                          _moveVideoPanel(d.data, sideName),
                      builder: (dctx, cand, rej) {
                        final hot = cand.isNotEmpty;
                        return Container(
                          decoration: BoxDecoration(
                            border: hot
                                ? Border.all(
                                    color: const Color(0xFF4FC3F7), width: 2)
                                : null,
                          ),
                          child: Column(children: [
                            for (var i = 0; i < ids.length; i++) ...[
                              if (i > 0)
                                const Divider(
                                    height: 1, color: Color(0x33FFFFFF)),
                              Expanded(
                                child: DragTarget<String>(
                                  onWillAcceptWithDetails: (d) =>
                                      d.data != ids[i],
                                  onAcceptWithDetails: (d) => _moveVideoPanel(
                                      d.data, sideName,
                                      before: ids[i]),
                                  builder: (_, c2, __) => Container(
                                    decoration: BoxDecoration(
                                      border: c2.isNotEmpty
                                          ? const Border(
                                              top: BorderSide(
                                                  color: Color(0xFF4FC3F7),
                                                  width: 2))
                                          : null,
                                    ),
                                    child: panelFor(ids[i], w),
                                  ),
                                ),
                              ),
                            ],
                          ]),
                        );
                      },
                    ),
                  );
                }

                // 仕切り (掴んで幅を変えられる)。 [rightSide] なら右列の幅。
                Widget divider({required bool rightSide}) => MouseRegion(
                      cursor: SystemMouseCursors.resizeLeftRight,
                      child: GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onHorizontalDragUpdate: (d) => setState(() {
                          if (rightSide) {
                            _videoSidePanelWidth =
                                (_videoSidePanelWidth - d.delta.dx)
                                    .clamp(280.0, maxSide)
                                    .toDouble();
                          } else {
                            _videoSidePanelWidthLeft =
                                (_videoSidePanelWidthLeft + d.delta.dx)
                                    .clamp(280.0, maxSide)
                                    .toDouble();
                          }
                        }),
                        child: Container(
                          width: 6,
                          color: const Color(0xFF23233A),
                          alignment: Alignment.center,
                          child: Container(
                            width: 2,
                            height: 36,
                            decoration: BoxDecoration(
                              color: Colors.white24,
                              borderRadius: BorderRadius.circular(1),
                            ),
                          ),
                        ),
                      ),
                    );

                return Row(children: [
                  if (left.isNotEmpty) ...[
                    column(left, 'left', wL),
                    divider(rightSide: false),
                  ],
                  // 動画の上に落とすと、 落とした側 (左半分 / 右半分) へ移す。
                  Expanded(
                    child: DragTarget<String>(
                      onWillAcceptWithDetails: (d) => true,
                      onAcceptWithDetails: (d) {
                        // 画面座標のままだと左列の分だけずれるので、 この
                        //   領域の中の位置に直してから左右を決める。
                        final box = dropKey.currentContext?.findRenderObject()
                            as RenderBox?;
                        final local = box?.globalToLocal(d.offset) ?? d.offset;
                        final half = (box?.size.width ?? maxW) / 2;
                        _moveVideoPanel(
                            d.data, local.dx < half ? 'left' : 'right');
                      },
                      builder: (_, cand, __) => Container(
                        key: dropKey,
                        foregroundDecoration: cand.isEmpty
                            ? null
                            : BoxDecoration(
                                color: const Color(0xFF4FC3F7)
                                    .withValues(alpha: 0.10)),
                        child: videoArea,
                      ),
                    ),
                  ),
                  if (right.isNotEmpty) ...[
                    divider(rightSide: true),
                    column(right, 'right', wR),
                  ],
                ]);
              });
            }),
          ),
        ]),
      ),
    );
  }

  /// 動画そのもの (WebView) の表示。 [side] が true の時は、 メモ / AI 欄は
  /// 横に並べるので上に重ねない (= ユーザー要望)。
  Widget _buildWinVideoArea(BuildContext context, {required bool side}) {
    return Stack(children: [
              if (Platform.isLinux)
                linux_wv.LinuxWebViewWidget(url: _currentUrl)
              else if (_initialized)
                wv_win.Webview(
                  _controller,
                  permissionRequested: (url, kind, isUserInitiated) =>
                      wv_win.WebviewPermissionDecision.allow,
                )
              else
                Center(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      CircularProgressIndicator(
                          valueColor:
                              AlwaysStoppedAnimation<Color>(Color(0xFFE53935))),
                      SizedBox(height: 12),
                      Text(
                          context
                              .read<MindMapProvider>()
                              .t('webview.initializing'),
                          style:
                              TextStyle(color: Colors.white54, fontSize: 12)),
                    ],
                  ),
                ),
              if (_loading && _initialized)
                const Positioned(
                  top: 0,
                  left: 0,
                  right: 0,
                  child: LinearProgressIndicator(
                      valueColor:
                          AlwaysStoppedAnimation<Color>(Color(0xFFE53935)),
                      backgroundColor: Colors.transparent),
                ),
              // ── 動画視聴中メモパネル ──
              // [_videoMemoPanelOpen] = true の時 WebView の上にオーバーレイ。
              // Stack の最後の子 = 最前面。 内部で Positioned.fill + 右下
              // Align のサイドカードを描画するため、 動画は左半分が見えたまま。
              // ── 動画メモ / AI パネルは実際の表示エリア (= この Stack のサイズ)
              //    を LayoutBuilder で取得して配置する。 MediaQuery の全画面サイズ
              //    だとダイアログより大きくなり、 パネルが枠外へ出て折り畳み/閉じる
              //    ボタンが押せなくなる (= ユーザー報告) ため。 ──
              // 横に並べるモードの時は、 ここには重ねない (親が横へ置く)。
              if (!side && (_videoMemoPanelOpen || _videoAiPanelOpen))
                Positioned.fill(
                  child: LayoutBuilder(builder: (lctx, constraints) {
                    final area =
                        Size(constraints.maxWidth, constraints.maxHeight);
                    return Stack(children: [
                      if (_videoMemoPanelOpen)
                        _buildWinVideoMemoPanel(context, area),
                      if (_videoAiPanelOpen)
                        _buildWinVideoAiPanel(context, area),
                    ]);
                  }),
                ),
    ]);
  }
}

// ─── ダウンロード済み動画の永続化 ──────────────────────────────────────────
//
// 動画ダウンロード機能で端末に保存した mp4/webm ファイルのメタ情報を
// SharedPreferences に保管する。右クリック (PC) または トップバーの
// 3 点メニュー (PC/モバイル共通) から「ダウンロードした動画一覧」を
// 開いて、過去ダウンロード済みの動画を再度マップに埋め込んだり、
// 端末の動画プレイヤーで開いたり、削除したりできる。
//
// データ構造: List<Map<String, dynamic>> を JSON 文字列にして保存。
// 各レコードのキー:
//   - path:        ローカルファイルパス (絶対パス)
//   - title:       表示用タイトル
//   - sourceUrl:   元の YouTube URL or mp4 URL (再ダウンロード用)
//   - videoId:     YouTube 動画 ID (任意、YouTube 由来の時だけ)
//   - sizeBytes:   ファイルサイズ (バイト)
//   - downloadedAt: ダウンロード完了時刻 (UNIX ms)
class _DownloadedVideosStore {
  static const String _key = 'downloaded_videos_v1';

  /// 保存済みリストを読む。ファイルが既に削除されているレコードは
  /// 自動で除外する (端末側でユーザーが手動削除した場合)。
  static Future<List<Map<String, dynamic>>> load() async {
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString(_key);
      if (raw == null || raw.isEmpty) return <Map<String, dynamic>>[];
      final List<dynamic> arr = jsonDecode(raw);
      final list = arr
          .whereType<Map>()
          .map((m) => m.map((k, v) => MapEntry(k.toString(), v)))
          .toList();
      // ファイル実体が残っているものだけに絞る
      final alive = <Map<String, dynamic>>[];
      var changed = false;
      for (final r in list) {
        final p = r['path']?.toString() ?? '';
        if (p.isNotEmpty && File(p).existsSync()) {
          alive.add(r);
        } else {
          changed = true;
        }
      }
      // ストアと実体が乖離していたら書き戻して同期する
      if (changed) {
        await sp.setString(_key, jsonEncode(alive));
      }
      // downloadedAt の降順 (新しい順)
      alive.sort((a, b) {
        final ai = (a['downloadedAt'] as num?)?.toInt() ?? 0;
        final bi = (b['downloadedAt'] as num?)?.toInt() ?? 0;
        return bi.compareTo(ai);
      });
      return alive;
    } catch (_) {
      return <Map<String, dynamic>>[];
    }
  }

  /// 1 件追加 (同 path が既に有れば置換)。
  static Future<void> add(Map<String, dynamic> record) async {
    try {
      final list = await load();
      // 同パスを除く
      list.removeWhere((r) => r['path'] == record['path']);
      list.insert(0, record);
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_key, jsonEncode(list));
    } catch (e) {
      debugPrint('_DownloadedVideosStore.add failed: $e');
    }
  }

  /// path に該当するレコードを除去 (ファイル実体は残す/消すは呼び出し側)。
  static Future<void> removeByPath(String path) async {
    try {
      final list = await load();
      list.removeWhere((r) => r['path'] == path);
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_key, jsonEncode(list));
    } catch (e) {
      debugPrint('_DownloadedVideosStore.removeByPath failed: $e');
    }
  }

  /// 複数 path のレコードをまとめてストアから除去する。
  /// ファイル実体の削除は呼び出し側 (UI 側) が File.delete() で行う。
  /// `removeByPath` を N 回呼ぶより高速 (load + save が 1 回ずつで済む)。
  static Future<void> removeByPaths(Iterable<String> paths) async {
    if (paths.isEmpty) return;
    try {
      final pathSet = paths.toSet();
      final list = await load();
      list.removeWhere((r) => pathSet.contains(r['path']));
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_key, jsonEncode(list));
    } catch (e) {
      debugPrint('_DownloadedVideosStore.removeByPaths failed: $e');
    }
  }
}

// ─── 全画面動画ページ（モバイル専用, flutter_inappwebview 版）────────────
// 元々 webview_flutter を使っていたが MIUI/HyperOS 上で
//   "Unable to establish connection on channel:
//    dev.flutter.pigeon.webview_flutter_android.WebView.loadUrl"
// という Pigeon 登録失敗で動かなかったため flutter_inappwebview に移行。
//
// Windows 版 (_WindowsWebViewSheet) と同等の機能:
//   - 再生速度スライダー (1.0x〜5.0x)
//   - 視聴位置の自動保存 (MindMapProvider.saveVideoPosition)
//   - フォーカスモード CSS (関連動画・コメント等を隠す)
//   - 現在の URL をマップに埋め込むボタン (onEmbedUrl)
//   - YouTube 動画 / mp4 / 一般 URL 全対応
//   - プレイリストによる連続再生
//   - 動画ダウンロード (_DownloadedVideosStore に登録 + onDownloadComplete
//     コールバックで MindMapScreen 側のキャンバスにノードを自動配置)

/// 動画視聴中に取ったメモを 1 件分表す軽量レコード。
/// 書いた動画メモを後から書き直すためのダイアログ (= ユーザー要望:
/// 文字の所をダブルクリックで編集できるように)。 直した本文を返す。
/// 取り消し / 変更なしなら null。
Future<String?> _showVideoMemoEditDialog(
    BuildContext context, String initial) async {
  final provider = context.read<MindMapProvider>();
  final ctrl = TextEditingController(text: initial);
  final result = await showDialog<String>(
    context: context,
    builder: (dctx) => AlertDialog(
      backgroundColor: const Color(0xFF1E1E32),
      title: Text(provider.t('vmemo.editTitle'),
          style: const TextStyle(color: Colors.white, fontSize: 15)),
      content: SizedBox(
        width: 420,
        child: TextField(
          controller: ctrl,
          autofocus: true,
          minLines: 3,
          maxLines: 12,
          keyboardType: TextInputType.multiline,
          style: const TextStyle(color: Colors.white, fontSize: 13),
          decoration: InputDecoration(
            filled: true,
            fillColor: Colors.white.withValues(alpha: 0.08),
            isDense: true,
            contentPadding:
                const EdgeInsets.symmetric(horizontal: 10, vertical: 10),
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: BorderSide.none,
            ),
          ),
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dctx),
          child: Text(provider.t('btn.cancel'),
              style: const TextStyle(color: Colors.white54)),
        ),
        ElevatedButton(
          style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFF4FC3F7),
              foregroundColor: Colors.black),
          onPressed: () => Navigator.pop(dctx, ctrl.text),
          child: Text(provider.t('btn.save')),
        ),
      ],
    ),
  );
  ctrl.dispose();
  if (result == null) return null;
  final t = result.trim();
  if (t.isEmpty || t == initial.trim()) return null;
  return t;
}

/// クリップボード / ファイル選択から画像を 1 枚取り込み、
/// `attachments/` に保存して置き場所を返す (= ユーザー要望: 動画メモで
/// 画像を貼り付けておけるように)。
///
/// まずクリップボードを見て、 画像が無ければファイル選択に回す
/// ([allowPicker] が false の時は諦めて null)。 取り込めなければ null。
Future<String?> grabImageForVideoMemo({bool allowPicker = true}) async {
  Uint8List? bytes;
  String ext = 'png';
  try {
    final clipboard = SystemClipboard.instance;
    if (clipboard != null) {
      final reader = await clipboard.read();
      const candidates = <(FileFormat, String)>[
        (Formats.png, 'png'),
        (Formats.jpeg, 'jpg'),
        (Formats.gif, 'gif'),
        (Formats.webp, 'webp'),
        (Formats.bmp, 'bmp'),
      ];
      for (final (fmt, e) in candidates) {
        if (!reader.canProvide(fmt)) continue;
        bytes = await _readClipboardImageBytesForMemo(reader, fmt);
        if (bytes != null && bytes.isNotEmpty) {
          ext = e;
          break;
        }
      }
    }
  } catch (e) {
    debugPrint('動画メモ: クリップボードの読み取りに失敗: $e');
  }
  try {
    final appDir = await getApplicationDocumentsDirectory();
    final attachDir = Directory('${appDir.path}/attachments');
    if (!await attachDir.exists()) await attachDir.create(recursive: true);
    final stamp = DateTime.now().millisecondsSinceEpoch;
    if (bytes != null && bytes.isNotEmpty) {
      final dest = '${attachDir.path}/videomemo_$stamp.$ext';
      await File(dest).writeAsBytes(bytes, flush: true);
      return dest;
    }
    if (!allowPicker) return null;
    // ── クリップボードに画像が無い時はファイルから選ぶ ──
    //    (Android は画面撮影の貼り付けが読めない端末があるため = 実績あり)
    final res = await FilePicker.platform.pickFiles(type: FileType.image);
    final src = res?.files.single.path;
    if (src == null || src.isEmpty) return null;
    final dot = src.lastIndexOf('.');
    final e2 = dot >= 0 ? src.substring(dot + 1) : 'png';
    final dest = '${attachDir.path}/videomemo_$stamp.$e2';
    await File(src).copy(dest);
    return dest;
  } catch (e) {
    debugPrint('動画メモ: 画像の取り込みに失敗: $e');
    return null;
  }
}

/// super_clipboard の getFile (コールバック式) を Future にする。
Future<Uint8List?> _readClipboardImageBytesForMemo(
    ClipboardReader reader, FileFormat format) async {
  final completer = Completer<Uint8List?>();
  try {
    reader.getFile(format, (file) async {
      try {
        final chunks = <int>[];
        await for (final chunk in file.getStream()) {
          chunks.addAll(chunk);
        }
        if (!completer.isCompleted) {
          completer.complete(Uint8List.fromList(chunks));
        }
      } catch (_) {
        if (!completer.isCompleted) completer.complete(null);
      }
    }, onError: (_) {
      if (!completer.isCompleted) completer.complete(null);
    });
  } catch (_) {
    if (!completer.isCompleted) completer.complete(null);
  }
  return completer.future;
}

/// 動画メモに貼った画像を大きく見る。
void showVideoMemoImage(BuildContext context, String path) {
  showDialog<void>(
    context: context,
    barrierColor: Colors.black87,
    builder: (dctx) => GestureDetector(
      onTap: () => Navigator.pop(dctx),
      child: Padding(
        padding: const EdgeInsets.all(24),
        child: InteractiveViewer(
          maxScale: 6,
          child: Center(child: Image.file(File(path), fit: BoxFit.contain)),
        ),
      ),
    ),
  );
}

/// 動画メモの一覧に出す画像の縮小表示。
Widget buildVideoMemoThumb(BuildContext context, String path,
    {double size = 34}) {
  return Padding(
    padding: const EdgeInsets.only(right: 6),
    child: GestureDetector(
      onTap: () => showVideoMemoImage(context, path),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(4),
        child: Image.file(
          File(path),
          width: size,
          height: size,
          fit: BoxFit.cover,
          errorBuilder: (_, __, ___) => Container(
            width: size,
            height: size,
            color: Colors.white10,
            child: const Icon(Icons.broken_image_outlined,
                size: 14, color: Colors.white38),
          ),
        ),
      ),
    ),
  );
}

/// PC / モバイル双方の `_videoMemos` に蓄えられ、
/// マップ追加済みフラグ (`addedToMap`) でリスト UI の「追加済み」 表示を
/// 切り替える。JSON 化して SharedPreferences にも保存できる。
class _VideoMemoEntry {
  /// メモ本文
  String text;

  /// メモ作成時の動画再生位置 (秒)。 null なら時刻未指定。
  double? timestampSec;

  /// このメモに貼り付けた画像の場所 (= ユーザー要望: 動画メモで画像を
  /// 貼り付けておけるように)。 貼っていなければ null。
  String? imagePath;

  /// マップに追加済みなら true。 重複追加防止 + UI バッジ用。
  bool addedToMap;

  /// このメモを作成した時点の動画 URL。YouTube URL は watch URL に正規化済み。
  /// 旧形式の保存データでは null のため、利用時は現在動画へフォールバックする。
  final String? sourceUrl;

  /// このメモを作成した時点の動画タイトル。項目の補助表示用。
  final String? sourceTitle;

  /// 一意 ID (リスト内の identity 比較用)
  final String id;

  /// 作成時刻 (UNIX ms)。 履歴永続化で並び順や古いものの整理に使う。
  final int savedAt;

  _VideoMemoEntry({
    required this.text,
    this.timestampSec,
    this.imagePath,
    this.addedToMap = false,
    this.sourceUrl,
    this.sourceTitle,
    required this.id,
    int? savedAt,
  }) : savedAt = savedAt ?? DateTime.now().millisecondsSinceEpoch;

  /// SharedPreferences 永続化用の JSON シリアライズ。
  Map<String, dynamic> toJson() => {
        'id': id,
        'text': text,
        'timestampSec': timestampSec,
        'imagePath': imagePath,
        'addedToMap': addedToMap,
        'sourceUrl': sourceUrl,
        'sourceTitle': sourceTitle,
        'savedAt': savedAt,
      };

  /// 永続化された Map から復元。 不正な形式の場合は null を返す。
  static _VideoMemoEntry? fromJson(Map<String, dynamic> j) {
    try {
      return _VideoMemoEntry(
        id: (j['id'] ?? DateTime.now().microsecondsSinceEpoch.toString())
            .toString(),
        text: (j['text'] ?? '').toString(),
        timestampSec: j['timestampSec'] is num
            ? (j['timestampSec'] as num).toDouble()
            : null,
        imagePath: (j['imagePath']?.toString().isNotEmpty ?? false)
            ? j['imagePath'].toString()
            : null,
        addedToMap: j['addedToMap'] == true,
        sourceUrl: j['sourceUrl']?.toString(),
        sourceTitle: j['sourceTitle']?.toString(),
        savedAt: j['savedAt'] is int ? j['savedAt'] as int : null,
      );
    } catch (_) {
      return null;
    }
  }
}

/// 動画メモ履歴の永続化ストア。
///
/// 一覧へ追加したメモをセッションを超えて保持するためのもの。
/// 動画 (videoId またはローカルパス) ごとに分けて SharedPreferences に保存し、
/// 同じ動画を後日再度開いた時に過去のメモを履歴一覧に復元できる。
///
/// データ構造:
///   key = "video_memo_history_<source-key>"
///   value = jsonEncode(List<Map<String, dynamic>>)
///
/// source-key の決定:
///   - YouTube 動画: videoId (e.g. "dQw4w9WgXcQ")
///   - mp4 直リンク / ローカル mp4: URL のハッシュ値
class _VideoMemoHistoryStore {
  static const _keyPrefix = 'video_memo_history_';

  /// 動画 URL (YouTube / mp4) から永続化用のキーを作る。
  static String _keyForUrl(String url) {
    final vid = NodeWidget.extractVideoId(url);
    if (vid != null) return '$_keyPrefix$vid';
    // YouTube 以外: URL の hashCode を使う (基本同じ URL なら同じキーになる)。
    return '$_keyPrefix\u0000url${url.hashCode}';
  }

  /// 指定動画のメモ履歴を読み込む。 未保存なら空リスト。
  static Future<List<_VideoMemoEntry>> loadForUrl(String url) async {
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString(_keyForUrl(url));
      if (raw == null || raw.isEmpty) return [];
      final List<dynamic> arr = jsonDecode(raw);
      final list = <_VideoMemoEntry>[];
      for (final item in arr) {
        if (item is Map<String, dynamic>) {
          final e = _VideoMemoEntry.fromJson(item);
          if (e != null) list.add(e);
        }
      }
      return list;
    } catch (_) {
      return [];
    }
  }

  /// 指定動画のメモ履歴を保存。 既存値を上書き。
  static Future<void> saveForUrl(
      String url, List<_VideoMemoEntry> entries) async {
    try {
      final sp = await SharedPreferences.getInstance();
      // 直近 100 件まで保持 (履歴が無限に増えないように上限を切る)
      final capped = entries.length > 100 ? entries.sublist(0, 100) : entries;
      final raw = jsonEncode(capped.map((e) => e.toJson()).toList());
      await sp.setString(_keyForUrl(url), raw);
    } catch (_) {
      // 保存失敗してもアプリ動作は続行する (履歴永続化は補助機能)
    }
  }
}

/// AI に投げた質問とその回答の 1 件 (= ユーザー要望: メモから AI に投げた
/// 質問の回答を履歴で保存)。
class _AiQaEntry {
  final String question;
  String answer;
  final int ts;
  _AiQaEntry({required this.question, this.answer = '', required this.ts});
  Map<String, dynamic> toJson() => {'q': question, 'a': answer, 'ts': ts};
  static _AiQaEntry fromJson(Map<String, dynamic> j) => _AiQaEntry(
        question: (j['q'] ?? '').toString(),
        answer: (j['a'] ?? '').toString(),
        ts: (j['ts'] as num?)?.toInt() ?? 0,
      );
}

/// AI Q&A 履歴の永続化ストア (prefs `ai_qa_history_v1`、 新しい順、 最大 200 件)。
class _AiQaHistoryStore {
  static const String _key = 'ai_qa_history_v1';

  static Future<List<_AiQaEntry>> load() async {
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString(_key);
      if (raw == null || raw.isEmpty) return [];
      final List<dynamic> arr = jsonDecode(raw);
      return arr
          .whereType<Map<String, dynamic>>()
          .map(_AiQaEntry.fromJson)
          .toList();
    } catch (_) {
      return [];
    }
  }

  static Future<void> save(List<_AiQaEntry> list) async {
    try {
      final sp = await SharedPreferences.getInstance();
      final capped = list.length > 200 ? list.sublist(0, 200) : list;
      await sp.setString(
          _key, jsonEncode(capped.map((e) => e.toJson()).toList()));
    } catch (_) {}
  }

  /// 新しい質問を先頭に追加する。 直近 (60 秒以内) と同一文言の質問は、
  /// メモ送信と手入力 Enter による二重記録を避けるためスキップする。
  static Future<void> addQuestion(String question, int ts) async {
    final q = question.trim();
    if (q.isEmpty) return;
    final list = await load();
    if (list.isNotEmpty &&
        list.first.question.trim() == q &&
        (ts - list.first.ts).abs() < 60000) {
      return;
    }
    list.insert(0, _AiQaEntry(question: q, ts: ts));
    await save(list);
  }

  /// 最新エントリ (先頭) の回答を更新する。
  static Future<void> setLatestAnswer(String answer) async {
    final list = await load();
    if (list.isEmpty) return;
    list.first.answer = answer;
    await save(list);
  }

  /// 回答を保存する。 最新エントリの回答が空ならそこへ、 そうでなければ
  /// 新規エントリとして追加する (= 質問を記録していなくても必ず保存される)。
  static Future<void> saveAnswer(String answer, int ts) async {
    final list = await load();
    if (list.isNotEmpty && list.first.answer.isEmpty) {
      list.first.answer = answer;
    } else {
      list.insert(0, _AiQaEntry(question: '', answer: answer, ts: ts));
    }
    await save(list);
  }

  static Future<void> removeAt(int i) async {
    final list = await load();
    if (i < 0 || i >= list.length) return;
    list.removeAt(i);
    await save(list);
  }
}

/// マップ (ページ) 毎のメモを保存するストア (= ユーザー要望)。
/// prefs キー `map_memo_<pageId>` に 1 ページ 1 メモを保持する。
/// マップメモ 1 項目 (= ユーザー要望: 複数登録して切り替え)。 [name] は
/// タブ名、 [body] は Quill Delta JSON 文字列 (旧形式のプレーン/Markdown も可)。
/// メモに貼る画像をアプリの中へコピーして、 その場所を返す。
/// クリップボードから (= Ctrl+V) と、 ファイル選択の両方で使う。
/// 取り込めなければ null。
Future<String?> _importMemoImage({Uint8List? bytes, String? srcPath}) async {
  try {
    final dir = await getApplicationDocumentsDirectory();
    final d = Directory('${dir.path}/memo_images');
    if (!await d.exists()) await d.create(recursive: true);
    final stamp = DateTime.now().millisecondsSinceEpoch;
    if (bytes != null && bytes.isNotEmpty) {
      final dest = '${d.path}/memo_$stamp.png';
      await File(dest).writeAsBytes(bytes, flush: true);
      return dest;
    }
    if (srcPath != null && srcPath.trim().isNotEmpty) {
      final src = File(srcPath);
      if (!await src.exists()) return null;
      final dot = srcPath.lastIndexOf('.');
      final ext = dot >= 0 ? srcPath.substring(dot) : '.png';
      final dest = '${d.path}/memo_$stamp$ext';
      await src.copy(dest);
      return dest;
    }
  } catch (e) {
    debugPrint('メモ画像の取り込みに失敗: $e');
  }
  return null;
}

/// クリップボードの画像を取り込む (= ユーザー要望: メモに画像を貼り付け)。
/// 画像が無ければ null。
Future<String?> _importMemoImageFromClipboard() async {
  try {
    final clipboard = SystemClipboard.instance;
    if (clipboard == null) return null;
    final reader = await clipboard.read();
    for (final fmt in const [
      Formats.png,
      Formats.jpeg,
      Formats.gif,
      Formats.webp,
      Formats.bmp,
    ]) {
      if (!reader.canProvide(fmt)) continue;
      final bytes = await _readClipboardBytes(reader, fmt);
      if (bytes != null && bytes.isNotEmpty) {
        return _importMemoImage(bytes: bytes);
      }
    }
  } catch (e) {
    debugPrint('クリップボードからの画像取り込みに失敗: $e');
  }
  return null;
}

/// クリップボードの 1 形式をバイト列で読む (画面側の同名処理と同じ方式)。
Future<Uint8List?> _readClipboardBytes(
    ClipboardReader reader, FileFormat format) async {
  final completer = Completer<Uint8List?>();
  try {
    reader.getFile(
      format,
      (file) async {
        try {
          final chunks = <int>[];
          await for (final chunk in file.getStream()) {
            chunks.addAll(chunk);
          }
          if (!completer.isCompleted) {
            completer.complete(Uint8List.fromList(chunks));
          }
        } catch (_) {
          if (!completer.isCompleted) completer.complete(null);
        }
      },
      onError: (_) {
        if (!completer.isCompleted) completer.complete(null);
      },
    );
  } catch (_) {
    if (!completer.isCompleted) completer.complete(null);
  }
  return completer.future
      .timeout(const Duration(seconds: 10), onTimeout: () => null);
}

class _MapMemoItem {
  String name;
  String body;

  /// 貼り付けた画像の置き場所 (= ユーザー要望: マップメモに画像を貼れるように)。
  /// アプリの `memo_images/` へコピーした絶対パスを並べて持つ。
  List<String> images;
  _MapMemoItem(this.name, this.body, {List<String>? images})
      : images = images ?? <String>[];
}

class _MapMemoStore {
  static String _key(String pageId) => 'map_memo_$pageId';
  // 全体共有メモ (= ユーザー要望: 違うマップからでも参照編集できる)。
  static const String _globalKey = 'map_memo_global';
  // 各ページが「個別 / 全体」 どちらのスコープを使うかの記憶。
  static String _scopeKey(String pageId) => 'map_memo_scope_$pageId';

  static Future<String> load(String pageId) async {
    try {
      final sp = await SharedPreferences.getInstance();
      return sp.getString(_key(pageId)) ?? '';
    } catch (_) {
      return '';
    }
  }

  static Future<void> save(String pageId, String text) async {
    try {
      final sp = await SharedPreferences.getInstance();
      if (text.trim().isEmpty) {
        await sp.remove(_key(pageId));
      } else {
        await sp.setString(_key(pageId), text);
      }
    } catch (_) {}
  }

  /// global=true なら全体共有メモ、 false ならページ毎メモを読み書きする。
  static Future<String> loadScoped(String pageId, bool global) async {
    try {
      final sp = await SharedPreferences.getInstance();
      return sp.getString(global ? _globalKey : _key(pageId)) ?? '';
    } catch (_) {
      return '';
    }
  }

  static Future<void> saveScoped(
      String pageId, bool global, String text) async {
    try {
      final sp = await SharedPreferences.getInstance();
      final k = global ? _globalKey : _key(pageId);
      if (text.trim().isEmpty) {
        await sp.remove(k);
      } else {
        await sp.setString(k, text);
      }
    } catch (_) {}
  }

  static Future<bool> loadScope(String pageId) async {
    try {
      final sp = await SharedPreferences.getInstance();
      return sp.getString(_scopeKey(pageId)) == 'global';
    } catch (_) {
      return false;
    }
  }

  static Future<void> saveScope(String pageId, bool global) async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_scopeKey(pageId), global ? 'global' : 'page');
    } catch (_) {}
  }

  // ── 複数メモ項目 (= ユーザー要望: 項目を複数登録して切り替え) ──
  // 新形式は `{"items":[{"n":name,"b":body},...],"sel":index}` を 1 つの
  // スコープキーに保存する。 旧形式 (単一 body = Quill Delta JSON / プレーン)
  // は既定名の 1 件として読み込む (= 後方互換)。

  /// 文字列 (旧/新どちらの形式でも) を項目リスト + 選択インデックスに変換。
  static ({List<_MapMemoItem> items, int selected}) _parseItems(
      String raw, String defaultItemName) {
    final s = raw.trim();
    if (s.isNotEmpty) {
      try {
        final decoded = jsonDecode(s);
        if (decoded is Map && decoded['items'] is List) {
          final list = <_MapMemoItem>[];
          for (final e in (decoded['items'] as List)) {
            if (e is Map) {
              list.add(_MapMemoItem(
                (e['n'] ?? defaultItemName).toString(),
                (e['b'] ?? '').toString(),
                images: [
                  for (final p in (e['img'] as List?) ?? const [])
                    if ('$p'.trim().isNotEmpty) '$p',
                ],
              ));
            }
          }
          if (list.isEmpty) list.add(_MapMemoItem(defaultItemName, ''));
          int sel = (decoded['sel'] as num?)?.toInt() ?? 0;
          if (sel < 0 || sel >= list.length) sel = 0;
          return (items: list, selected: sel);
        }
      } catch (_) {}
      // 旧形式 (単一 body): 1 件に移行。
      return (items: [_MapMemoItem(defaultItemName, s)], selected: 0);
    }
    return (items: [_MapMemoItem(defaultItemName, '')], selected: 0);
  }

  static Future<({List<_MapMemoItem> items, int selected})> loadItems(
      String pageId, bool global,
      {required String defaultItemName}) async {
    final raw = await loadScoped(pageId, global);
    return _parseItems(raw, defaultItemName);
  }

  /// Quill Delta JSON / プレーン文字列の本文が実質空かどうか。
  static bool _bodyBlank(String body) {
    final t = body.trim();
    if (t.isEmpty) return true;
    try {
      final d = jsonDecode(t);
      if (d is List) {
        final buf = StringBuffer();
        for (final op in d) {
          if (op is Map && op['insert'] is String) buf.write(op['insert']);
        }
        return buf.toString().trim().isEmpty;
      }
    } catch (_) {}
    return false;
  }

  static Future<void> saveItems(String pageId, bool global,
      List<_MapMemoItem> items, int selected) async {
    // 1 件だけかつ空なら、 旧挙動どおりキーごと削除 (空メモは保持しない)。
    if (items.length <= 1 &&
        (items.isEmpty ||
            (_bodyBlank(items.first.body) && items.first.images.isEmpty))) {
      await saveScoped(pageId, global, '');
      return;
    }
    int sel = (selected < 0 || selected >= items.length) ? 0 : selected;
    final json = jsonEncode({
      'items': items
          .map((it) => {
                'n': it.name,
                'b': it.body,
                if (it.images.isNotEmpty) 'img': it.images,
              })
          .toList(),
      'sel': sel,
    });
    await saveScoped(pageId, global, json);
  }
}

/// マップ (ページ) 毎のフラッシュカード (表/裏) を保存するストア (= ユーザー要望:
/// フラッシュカードを単品で作成・編集できるように)。 prefs `flashcards_<pageId>`。
/// フラッシュカード 1 枚 (= ユーザー要望: グループ化 + 「全体 / このマップ」
/// スコープ)。 [group] は所属グループ名 (空 = 未分類)、 [global]=true なら
/// 全マップから参照・編集できる「全体」 スコープ。
// image = カードに貼り付けた画像のローカルパス (= ユーザー要望。 空なら無し)。
typedef _FCard = ({
  String front,
  String back,
  String group,
  bool global,
  String image,
  // 画像をどちらの面に表示するか ('front' | 'back')。 = ユーザー要望: 指定した
  //   側だけに画像が出るように (両面に出るのは不具合)。 既定は 'front'。
  String imageSide
});

/// 面接練習用の「経歴」「保有資格」 レコードの永続ストア (= ユーザー要望:
/// レコードのように保存して使い回せるように)。 prefs に文字列リストで保存。
class _InterviewRecordStore {
  static const _kCareers = 'interview_careers_v1';
  static const _kQuals = 'interview_quals_v1';

  static Future<List<String>> _load(String key) async {
    final p = await SharedPreferences.getInstance();
    return p.getStringList(key) ?? <String>[];
  }

  static Future<void> _save(String key, List<String> v) async {
    final p = await SharedPreferences.getInstance();
    await p.setStringList(key, v);
  }

  static Future<List<String>> loadCareers() => _load(_kCareers);
  static Future<void> saveCareers(List<String> v) => _save(_kCareers, v);
  static Future<List<String>> loadQuals() => _load(_kQuals);
  static Future<void> saveQuals(List<String> v) => _save(_kQuals, v);
}

/// 経歴 / 保有資格レコードの管理ページ (= ユーザー要望: 別ページでレコード
/// みたいに保存)。 経歴・資格それぞれのリストを追加 / 編集 / 削除できる。
class _InterviewRecordsDialog extends StatefulWidget {
  const _InterviewRecordsDialog();
  @override
  State<_InterviewRecordsDialog> createState() =>
      _InterviewRecordsDialogState();
}

class _InterviewRecordsDialogState extends State<_InterviewRecordsDialog> {
  List<String> _careers = [];
  List<String> _quals = [];
  bool _loaded = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final c = await _InterviewRecordStore.loadCareers();
    final q = await _InterviewRecordStore.loadQuals();
    if (!mounted) return;
    setState(() {
      _careers = c;
      _quals = q;
      _loaded = true;
    });
  }

  Future<void> _editEntry(List<String> list, int? index, bool careers) async {
    final ctrl = TextEditingController(text: index != null ? list[index] : '');
    final result = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(
            index == null
                ? context.read<MindMapProvider>().t(
                    careers ? 'records.addCareer' : 'records.addQualification')
                : context.read<MindMapProvider>().t(careers
                    ? 'records.editCareer'
                    : 'records.editQualification'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          minLines: careers ? 2 : 1,
          maxLines: 5,
          style: const TextStyle(color: Colors.white),
          decoration: InputDecoration(
            hintText: careers
                ? context.read<MindMapProvider>().t('records.careerHint')
                : context
                    .read<MindMapProvider>()
                    .t('records.qualificationHint'),
            hintStyle: const TextStyle(color: Colors.white38, fontSize: 12),
            enabledBorder: const OutlineInputBorder(
                borderSide: BorderSide(color: Colors.white24)),
            focusedBorder: const OutlineInputBorder(
                borderSide: BorderSide(color: Color(0xFF4FC3F7))),
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF4FC3F7),
                foregroundColor: Color(0xFF10241F),),
            onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
            child: Text(context.read<MindMapProvider>().t('btn.save'),
                style: const TextStyle(color: Colors.black)),
          ),
        ],
      ),
    );
    if (result == null || result.isEmpty) return;
    setState(() {
      if (index != null) {
        list[index] = result;
      } else {
        list.add(result);
      }
    });
    if (careers) {
      await _InterviewRecordStore.saveCareers(_careers);
    } else {
      await _InterviewRecordStore.saveQuals(_quals);
    }
  }

  Widget _section(
      String title, IconData icon, List<String> list, bool careers) {
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Row(children: [
        Icon(icon, color: const Color(0xFF4FC3F7), size: 18),
        const SizedBox(width: 8),
        Text(title,
            style: const TextStyle(
                color: Colors.white,
                fontSize: 14,
                fontWeight: FontWeight.w700)),
        const Spacer(),
        TextButton.icon(
          icon: const Icon(Icons.add_rounded, size: 16),
          label: Text(context.read<MindMapProvider>().t('btn.add')),
          onPressed: () => _editEntry(list, null, careers),
        ),
      ]),
      if (list.isEmpty)
        Padding(
          padding: const EdgeInsets.symmetric(vertical: 8),
          child: Text(context.read<MindMapProvider>().t('records.empty'),
              style: const TextStyle(color: Colors.white38, fontSize: 12)),
        ),
      ...list.asMap().entries.map((e) => Card(
            color: const Color(0xFF2A2A3E),
            margin: const EdgeInsets.symmetric(vertical: 3),
            child: ListTile(
              dense: true,
              title: Text(e.value,
                  style: const TextStyle(color: Colors.white, fontSize: 13)),
              trailing: Row(mainAxisSize: MainAxisSize.min, children: [
                IconButton(
                  icon: const Icon(Icons.edit_rounded,
                      color: Colors.white54, size: 18),
                  onPressed: () => _editEntry(list, e.key, careers),
                ),
                IconButton(
                  icon: const Icon(Icons.delete_outline_rounded,
                      color: Colors.redAccent, size: 18),
                  onPressed: () async {
                    setState(() => list.removeAt(e.key));
                    if (careers) {
                      await _InterviewRecordStore.saveCareers(_careers);
                    } else {
                      await _InterviewRecordStore.saveQuals(_quals);
                    }
                  },
                ),
              ]),
            ),
          )),
      const SizedBox(height: 18),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    return Dialog(
      backgroundColor: const Color(0xFF1E1E32),
      child: SizedBox(
        width: 520,
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(18, 16, 18, 4),
            child: Row(children: [
              const Icon(Icons.badge_rounded,
                  color: Color(0xFF4FC3F7), size: 20),
              const SizedBox(width: 10),
              Text(context.read<MindMapProvider>().t('records.title'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 16,
                      fontWeight: FontWeight.w700)),
            ]),
          ),
          const Divider(height: 1, color: Colors.white12),
          Flexible(
            child: !_loaded
                ? const Padding(
                    padding: EdgeInsets.all(40),
                    child: Center(
                        child: CircularProgressIndicator(
                            color: Color(0xFF4FC3F7))))
                : SingleChildScrollView(
                    padding: const EdgeInsets.all(18),
                    child: Column(children: [
                      _section(
                          context.read<MindMapProvider>().t('records.career'),
                          Icons.work_history_rounded,
                          _careers,
                          true),
                      _section(
                          context.read<MindMapProvider>().t('records.quals'),
                          Icons.verified_rounded,
                          _quals,
                          false),
                    ]),
                  ),
          ),
          Padding(
            padding: const EdgeInsets.all(10),
            child: SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF4FC3F7),
                    foregroundColor: Color(0xFF10241F),),
                onPressed: () => Navigator.pop(context),
                child: Text(context.read<MindMapProvider>().t('btn.close'),
                    style: const TextStyle(color: Colors.black)),
              ),
            ),
          ),
        ]),
      ),
    );
  }
}

/// AI 面接練習 / 営業ロープレ練習の音声会話ダイアログ (= ユーザー要望)。
///  mode='interview': 会社名・新卒/中途・経歴・保有資格を設定 → AI が面接官
///    として音声会話 → フィードバック + 合否判定。
///  mode='roleplay' : 売りたい製品・商談相手の人物像・アプローチ方法を設定 →
///    AI がクライアント役で音声会話 → フィードバック。
/// 入力は音声 (STT) / テキスト両対応、 AI の発話は TTS で読み上げ (失敗時は
/// テキストのみで成立)。
/// 使うモデルを選ぶ小さなボタン (= ユーザー要望: 面接練習 / 営業ロープレでも
/// モデルを選びたい)。 AI アシスタントの選択画面と同じ中身を、 どの画面からでも
/// 出せるようにしたもの。 選択はアプリ全体で共有される。
class _AiModelPicker extends StatefulWidget {
  final MindMapProvider provider;
  const _AiModelPicker({required this.provider});
  @override
  State<_AiModelPicker> createState() => _AiModelPickerState();
}

class _AiModelPickerState extends State<_AiModelPicker> {
  /// 表示名。 末尾の日付 (…-20251001) は分かりにくいので落とす。
  String _label(String id) => id.replaceAll(RegExp(r'-\d{8}$'), '');

  @override
  Widget build(BuildContext context) {
    final provider = widget.provider;
    final models = [
      for (final m in provider.relayModels)
        if (m is Map && m['available'] == true) m
    ];
    if (models.isEmpty) return const SizedBox.shrink();
    const groups = [
      ('gemini', 'Gemini'),
      ('openai', 'ChatGPT'),
      ('anthropic', 'Claude'),
    ];
    return InkWell(
      borderRadius: BorderRadius.circular(6),
      onTap: () => showAiModelDialog(context, provider,
          onChanged: () { if (mounted) setState(() {}); }),
      child: Row(mainAxisSize: MainAxisSize.min, children: [
        const Icon(Icons.language_rounded, size: 13, color: Colors.white54),
        const SizedBox(width: 4),
        Text(_label(provider.relayModel),
            style: const TextStyle(color: Colors.white70, fontSize: 11)),
        const Icon(Icons.expand_more_rounded, size: 14, color: Colors.white38),
      ]),
    );
  }
}

class _AiTalkDialog extends StatefulWidget {
  final String mode; // 'interview' | 'roleplay' | 'pickup'
  const _AiTalkDialog({required this.mode});
  @override
  State<_AiTalkDialog> createState() => _AiTalkDialogState();
}

class _AiTalkDialogState extends State<_AiTalkDialog> {
  /// 今の練習の種類。 ★ 画面の中で切り替えられる (= ユーザー要望: 就活面接 /
  /// 営業ロールプレイ / 受験面接 / 資格面接を 1 つのボタンにまとめる)。
  /// 開いた時の種類は widget.mode で決まる。
  late String _mode = widget.mode;

  bool get _isInterview => _mode == 'interview';
  bool get _isPickup => _mode == 'pickup';

  /// 資格・免許の面接 (= ユーザー要望: 医師国家試験のような資格の面接)。
  bool get _isLicense => _mode == 'license';

  /// プレゼンテーションの練習 (= ユーザー要望: 原稿や動画を渡すと、 AI が
  /// 質疑を考えたり評価したりする)。
  bool get _isPresentation => _mode == 'presentation';

  /// 種類を選び直せる画面か (会話練習だけは別物なので出さない)。
  bool get _canSwitchMode => !_isPickup;

  /// 1 つのボタンにまとめた時に選べる種類 (= ユーザー要望)。
  static const List<({String mode, String labelKey, IconData icon})>
      _talkModes = [
    (
      mode: 'interview',
      labelKey: 'hdr.interviewPractice',
      icon: Icons.record_voice_over_rounded
    ),
    (
      mode: 'exam',
      labelKey: 'hdr.examInterview',
      icon: Icons.school_rounded
    ),
    (
      mode: 'license',
      labelKey: 'hdr.licenseInterview',
      icon: Icons.workspace_premium_rounded
    ),
    (
      mode: 'roleplay',
      labelKey: 'hdr.rolePlayPractice',
      icon: Icons.storefront_rounded
    ),
    (
      mode: 'presentation',
      labelKey: 'hdr.presentation',
      icon: Icons.co_present_rounded
    ),
  ];

  IconData get _modeIcon {
    for (final m in _talkModes) {
      if (m.mode == _mode) return m.icon;
    }
    return _isPickup ? Icons.woman_rounded : Icons.record_voice_over_rounded;
  }

  String get _modeLabelKey {
    for (final m in _talkModes) {
      if (m.mode == _mode) return m.labelKey;
    }
    return _isPickup ? 'hdr.pickupPractice' : 'hdr.rolePlayPractice';
  }

  /// 種類を切り替える。 会話は捨てて設定からやり直す (中身が別物のため)。
  void _switchMode(String next) {
    if (next == _mode) return;
    // ignore: discarded_futures
    _saveCurrentSettings();
    setState(() {
      _mode = next;
      _started = false;
      _verdict = null;
      _msgs.clear();
      // 下調べは種類ごとに分けて覚えているので読み直す。
      _refDigest = '';
      _refKey = '';
    });
    // ignore: discarded_futures
    _loadRefSettings();
    // ignore: discarded_futures
    _loadSettingsForMode();
  }

  /// 今の種類の設定を読み直す。
  Future<void> _loadSettingsForMode() async {
    if (_isPresentation) return _loadPresentSettings();
    if (_isExam) return _loadExamSettings();
    if (_isInterview) return _loadInterviewSetup();
    if (_isLicense) return _loadLicenseSettings();
    if (_isPickup) return _loadPickupSettings();
    return _loadRoleplaySettings();
  }

  /// 受験の面接練習か (= ユーザー要望: 受ける学校名と実績・成績を入れると、
  /// その学校に合わせた面接練習ができる)。
  bool get _isExam => _mode == 'exam';

  // ── 受験面接 ──
  /// 受ける学校の名前 (大学 / 高校 / 中学 / 小学校)。
  final TextEditingController _schoolCtrl = TextEditingController();

  /// 学部・学科・コースなど (任意)。
  final TextEditingController _schoolDeptCtrl = TextEditingController();

  /// 実績・成績・自己PR。
  final TextEditingController _achieveCtrl = TextEditingController();

  /// 校種。 grad | university | high | junior | elementary
  String _schoolKind = 'university';

  // ── 資格面接 (= ユーザー要望: 医師国家試験などの資格の面接) ──
  /// 面接の形式。 personal | group | oral
  String _licenseStyle = 'personal';

  // ── プレゼンテーション (= ユーザー要望: 原稿や動画を渡すと質疑を考えたり
  //    評価したりする) ──
  /// 発表の場。 academic (学会・研究発表) | business (社内・提案) | class (授業)
  String _presentScene = 'business';

  /// 渡された発表の動画 (任意)。 音声は書き起こせないので、 何コマか静止画を
  /// 抜いて「資料の見え方・構成」 を見てもらう。
  String _presentVideoPath = '';
  String _presentVideoName = '';

  /// 動画から抜いたコマ (最初のやり取りにだけ添える)。
  List<AiInputImage> _presentFrames = const [];
  bool _extractingFrames = false;

  // 設定
  final TextEditingController _topicCtrl = TextEditingController(); // 会社 / 製品
  final TextEditingController _careerCtrl = TextEditingController(); // 経歴(面接)
  String _careerType = 'newgrad'; // newgrad | midcareer
  bool _started = false;

  // ── 保存済みの経歴 / 保有資格レコード (= ユーザー要望: レコードのように
  //    保存して使い回す)。 別ページ (_InterviewRecordsDialog) で管理する。 ──
  List<String> _savedCareers = [];
  List<String> _savedQuals = [];
  String? _selectedCareer; // 選択中の経歴 (本文は _careerCtrl にも反映)
  final Set<String> _selectedQuals = {}; // 選択中の保有資格 (複数可)

  // ── 営業ロープレ: 商談相手の人物像 + アプローチ方法 (= ユーザー要望) ──
  final TextEditingController _counterpartCtrl = TextEditingController();
  final TextEditingController _pickupPlaceCtrl = TextEditingController();
  String _approach = 'inperson'; // inperson | phone | online
  bool _pickupRandomAi = false;
  int _pickupAgeMin = 20;
  int _pickupAgeMax = 35;

  // 会話
  final List<({String role, String text})> _msgs = [];
  final TextEditingController _input = TextEditingController();
  final ScrollController _scroll = ScrollController();
  bool _loading = false;

  // 音声入力 (STT)
  final stt.SpeechToText _speech = stt.SpeechToText();
  bool _speechInit = false;
  bool _listening = false;

  // 音声読み上げ (TTS)
  FlutterTts? _tts;
  bool _ttsOn = true;

  // 評価結果
  bool _evaluating = false;
  String? _verdict;

  // ── 下調べ (= ユーザー要望: AI の知識だけでなく Web と手元の資料を見る) ──
  /// 開始時に Web から相手 (学校 / 企業) の情報を取ってくるか。
  bool _useWebLookup = true;

  /// ユーザーが上げた資料 (「過去にこんな質問が来た」 等)。
  final List<({String path, String name, String text})> _refFiles = [];

  /// 下調べの結果をまとめた文章 (プロンプトへ渡す)。
  String _refDigest = '';

  /// 前回まとめた時の条件 (同じなら取り直さずに使い回す = 通信も課金も無駄が出る)。
  String _refKey = '';

  bool _gathering = false;
  String _gatherStatus = '';

  @override
  void initState() {
    super.initState();
    _initTts();
    _loadRefSettings();
    // ignore: discarded_futures
    _loadSettingsForMode();
  }

  Future<void> _loadInterviewSetup() async {
    await _loadRecords();
    await _loadInterviewSettings();
  }

  Future<void> _loadRecords() async {
    final c = await _InterviewRecordStore.loadCareers();
    final q = await _InterviewRecordStore.loadQuals();
    if (!mounted) return;
    setState(() {
      _savedCareers = c;
      _savedQuals = q;
    });
  }

  Future<void> _openRecordsManager() async {
    await showDialog<void>(
      context: context,
      builder: (_) => const _InterviewRecordsDialog(),
    );
    // 管理ページで増減した可能性があるので読み直す。 消えたレコードの選択は外す。
    await _loadRecords();
    if (!mounted) return;
    setState(() {
      if (_selectedCareer != null && !_savedCareers.contains(_selectedCareer)) {
        _selectedCareer = null;
      }
      _selectedQuals.removeWhere((q) => !_savedQuals.contains(q));
    });
  }

  /// 読み上げの速さ (1.0 = 等速)。
  ///
  /// ★ flutter_tts の setSpeechRate は環境で意味が違う。
  ///   Windows は SpeakingRate = 値 + 0.5、 Android は 値 × 2。
  ///   どちらも「0.5 = 等速」 なので、 欲しい倍率から逆算する。
  ///   前は 0.5 (= 等速) を渡していて、 面接の受け答えとしては間延びして
  ///   聞こえていた (= ユーザー報告: 遅い / 不自然)。
  static const double _kSpeakSpeed = 1.25;

  double _ttsRateValue(double speed) {
    if (!kIsWeb && Platform.isWindows) {
      return (speed - 0.5).clamp(0.0, 1.0);
    }
    return (speed / 2).clamp(0.0, 1.0);
  }

  Future<void> _initTts() async {
    try {
      final t = FlutterTts();
      try {
        final loc = context.read<MindMapProvider>().speechLocaleId;
        if (loc.isNotEmpty) await t.setLanguage(loc.replaceAll('_', '-'));
      } catch (_) {}
      try {
        await t.setSpeechRate(_ttsRateValue(_kSpeakSpeed));
      } catch (_) {}
      _tts = t;
      // 相手の性別に合う声を選ぶ (= ユーザー要望: 50 代主婦の設定なのに
      //   男性の声で読まれるのが気になる)。
      await _applyVoiceForPersona();
    } catch (_) {
      _tts = null;
    }
  }

  /// 設定した人物像から性別を推し量る。 'female' / 'male' / null (不明)。
  String? _personaGender() {
    // 面接官は相手の人物像を決めていないので、 指定しない (既定の声)。
    final src = _isInterview
        ? ''
        : '${_counterpartCtrl.text} ${_topicCtrl.text}';
    final s = src.toLowerCase();
    if (s.trim().isEmpty) return null;
    const female = [
      '女性', '女', '主婦', '母', 'ママ', '奥様', '奥さん', 'おばあ', '祖母',
      '娘', '姉', '妹', 'ol', 'woman', 'female', 'lady', 'she',
    ];
    const male = [
      '男性', '男', '主夫', '父', 'パパ', '旦那', 'ご主人', 'おじい', '祖父',
      '息子', '兄', '弟', 'man', 'male', 'he ',
    ];
    // 「女」 は「彼女」 等にも含まれるので、 先に女性語を見てから男性語。
    for (final k in female) {
      if (s.contains(k)) return 'female';
    }
    for (final k in male) {
      if (s.contains(k)) return 'male';
    }
    return null;
  }

  /// 人物像の性別に合う声へ切り替える。 見つからなければ何もしない。
  Future<void> _applyVoiceForPersona() async {
    final t = _tts;
    if (t == null) return;
    final want = _personaGender();
    if (want == null) return;
    try {
      final raw = await t.getVoices;
      if (raw is! List) return;
      final loc = context.mounted
          ? context.read<MindMapProvider>().speechLocaleId.replaceAll('_', '-')
          : '';
      final lang = loc.isEmpty ? 'ja' : loc.split('-').first.toLowerCase();
      Map? pick;
      for (final v in raw) {
        if (v is! Map) continue;
        final vloc = '${v['locale'] ?? ''}'.toLowerCase();
        if (!vloc.startsWith(lang)) continue;
        final g = '${v['gender'] ?? ''}'.toLowerCase();
        final name = '${v['name'] ?? ''}'.toLowerCase();
        // gender が取れる環境 (Windows など) はそれで、 取れなければ
        // よく入っている声の名前で見分ける。
        final isFemale = g == 'female' ||
            (g.isEmpty &&
                (name.contains('haruka') ||
                    name.contains('ayumi') ||
                    name.contains('sayaka') ||
                    name.contains('nanami') ||
                    name.contains('female')));
        final isMale = g == 'male' ||
            (g.isEmpty &&
                (name.contains('ichiro') ||
                    name.contains('keita') ||
                    name.contains('naoki') ||
                    name.contains('male')));
        if ((want == 'female' && isFemale) || (want == 'male' && isMale)) {
          pick = v;
          break;
        }
      }
      if (pick == null) return;
      await t.setVoice({
        'name': '${pick['name'] ?? ''}',
        'locale': '${pick['locale'] ?? ''}',
      });
    } catch (_) {
      // 声を選べない環境では既定のまま読み上げる。
    }
  }

  @override
  void dispose() {
    // 閉じる時にも設定を保存 (= ユーザー要望: 会話を始めずに閉じても復元)。
    // ignore: discarded_futures
    _saveCurrentSettings();
    try {
      _speech.cancel();
    } catch (_) {}
    try {
      _tts?.stop();
    } catch (_) {}
    _topicCtrl.dispose();
    _careerCtrl.dispose();
    _counterpartCtrl.dispose();
    _pickupPlaceCtrl.dispose();
    _schoolCtrl.dispose();
    _schoolDeptCtrl.dispose();
    _achieveCtrl.dispose();
    _input.dispose();
    _scroll.dispose();
    super.dispose();
  }

  Future<void> _speak(String text) async {
    if (!_ttsOn || _tts == null) return;
    try {
      await _tts!.stop();
      final clean = text.replaceAll(RegExp(r'[*_#`>|\-]'), ' ').trim();
      if (clean.isNotEmpty) await _tts!.speak(clean);
    } catch (_) {}
  }

  /// 校種の呼び名 (プロンプト用)。
  String get _schoolKindLabel {
    switch (_schoolKind) {
      case 'elementary':
        return '小学校';
      case 'junior':
        return '中学校';
      case 'high':
        return '高等学校';
      // 大学院は聞かれる内容がまるで違う (= ユーザー要望で追加)。
      case 'grad':
        return '大学院';
      default:
        return '大学';
    }
  }

  /// 大学院の面接だけに足す指示。
  ///
  /// 学部入試と違い、 志望動機より**研究計画・先行研究・指導教員との適合**が
  /// 中心になるので、 そこを尋ねさせる。
  String get _gradSchoolRule => _schoolKind != 'grad'
      ? ''
      : ' 大学院入試なので、 志望動機だけでなく**研究計画 (何を、 なぜ、 どう'
          '調べるか)・これまでの研究や卒業論文・先行研究の理解・希望する研究室'
          'や指導教員との適合・修了後の進路**を中心に掘り下げてください。'
          ' 答えが曖昧な時は、 研究者として詰めるべき点を 1 つだけ追加で'
          '尋ねてください。';

  String _systemPrompt() {
    final topic = _topicCtrl.text.trim();
    // ── プレゼンテーション (= ユーザー要望: 原稿や動画を渡すと、 AI が
    //    質疑を考えたり評価したりする) ──
    if (_isPresentation) {
      final script = _achieveCtrl.text.trim();
      final sceneLabel = _presentScene == 'academic'
          ? '学会・研究発表'
          : _presentScene == 'class'
              ? '授業・ゼミの発表'
              : '社内の報告・提案';
      return 'あなたは「$topic」というプレゼンテーションを聞いている'
          '$sceneLabelの聴衆です。 鋭くはあるが礼を欠かない質問者として'
          '振る舞ってください。'
          '${script.isNotEmpty ? '\n\n【発表の原稿・要旨】\n$script\n' : ''}'
          '${_presentFrames.isNotEmpty ? '\n渡された画像は発表の動画から抜き出した場面です。 スライドの見え方や進め方の参考にしてください。\n' : ''}'
          '\n進め方: まず一言だけ受け止めてから、 **質問を 1 つずつ**投げて'
          'ください。 質問は「聞いていて分からなかった所」「根拠が弱い所」'
          '「前提が抜けている所」「他の案と比べてどうか」「費用・期間・'
          '危険」 のような、 実際の質疑で出るものにしてください。'
          ' 発表者の答えが浅ければ、 その場で 1 つだけ追加で掘り下げます。'
          ' 音声会話なので 1 回の発話は短め (2〜3 文) に。'
          ' 原稿が渡されていない場合は、 まず何を発表するのかを尋ねてから'
          '質疑に入ってください。';
    }
    // ── 資格・免許の面接 (= ユーザー要望: 医師国家試験などの資格面接) ──
    if (_isLicense) {
      final name = topic;
      final achieve = _achieveCtrl.text.trim();
      final styleLabel = _licenseStyle == 'group'
          ? '集団面接'
          : _licenseStyle == 'oral'
              ? '口頭試問'
              : '個人面接';
      return 'あなたは「$name」の$styleLabelの試験官です。'
          '${achieve.isNotEmpty ? ' 受験者の学習状況・実務経験:「$achieve」。' : ''}'
          ' あなたが知っているこの資格の**役割・求められる適性・倫理・'
          '関係する法令や指針**をふまえて、 実際に問われそうなことを'
          '1 問ずつ尋ねてください。'
          '${_licenseStyle == 'oral' ? ' 口頭試問なので、 知識を確かめる具体的な問いを出し、 答えが浅ければその場で追加の問いを 1 つ重ねてください。' : ''}'
          '${_licenseStyle == 'group' ? ' 集団面接なので、 他の受験者にも同じ問いが向く前提で、 短く述べさせてください。' : ''}'
          ' 志望動機だけでなく、 **職業倫理 (守秘義務・利益相反・過誤への対応)**、'
          ' 資格取得後にどう働くか、 難しい場面での判断も尋ねてください。'
          ' 資格について確かな知識が無い場合は、 知ったかぶりをせず、'
          'その分野の専門職として一般に問われる内容にとどめてください。'
          ' 音声会話なので 1 回の発話は短め (2〜3 文) にし、 受験者の回答に'
          '簡単な相づち/掘り下げをしてから次へ進みます。 試験官として'
          '落ち着いた口調で振る舞ってください。';
    }
    // ── 受験面接 (= ユーザー要望) ──
    if (_isExam) {
      final school = _schoolCtrl.text.trim();
      final dept = _schoolDeptCtrl.text.trim();
      final achieve = _achieveCtrl.text.trim();
      return 'あなたは「$school」($_schoolKindLabel) の入学試験の面接官です。'
          '${dept.isNotEmpty ? ' 受験する学部・学科・コースは「$dept」です。' : ''}'
          '${achieve.isNotEmpty ? ' 受験生の実績・成績・自己PR:「$achieve」。' : ''}'
          ' あなたが知っているこの学校の**建学の精神・校風・教育方針・'
          'アドミッションポリシー・特色ある学び**をふまえて、 その学校で'
          '実際に出題されそうな面接質問を 1 問ずつ尋ねてください。'
          ' 学校について確かな知識が無い場合は、 知ったかぶりをせず、'
          '$_schoolKindLabel の面接で一般的に問われる内容 (志望動機・学校で'
          '学びたいこと・自己PR・長所短所・学校生活の抱負など) を尋ねて'
          'ください。'
          ' 受験生の実績や成績があれば、 それを踏まえた深掘り (その経験から'
          '何を学んだか、 入学後にどう活かすか) も交えてください。'
          '$_gradSchoolRule'
          ' $_schoolKindLabel の受験生に合った言葉づかいと難易度にしてください'
          '${_schoolKind == 'elementary' ? ' (小学校受験なので、 やさしい言葉で短く尋ねてください)' : ''}。'
          ' 音声会話なので 1 回の発話は短め (2〜3 文) にし、 受験生の回答に'
          '簡単な相づち/掘り下げをしてから次の質問へ進みます。 面接官として'
          '自然に振る舞ってください。';
    }
    if (_isInterview) {
      final type = _careerType == 'midcareer' ? '中途採用' : '新卒採用';
      final career = _careerCtrl.text.trim();
      final quals = _selectedQuals.toList();
      return 'あなたは「$topic」の採用面接官です。 これは$typeの面接です。'
          '${career.isNotEmpty ? ' 応募者の経歴:「$career」。' : ''}'
          '${quals.isNotEmpty ? ' 応募者の保有資格:「${quals.join(' / ')}」。' : ''}'
          ' あなたの知っている $topic の事業内容・特徴・業界をふまえ、 実際に'
          '出題されそうな面接質問を 1 問ずつ尋ねてください。 経歴や保有資格が'
          'あれば、 それを踏まえた質問 (資格の活かし方や経歴の深掘り) も交えて'
          'ください。 音声会話なので 1 回の発話は短め (2〜3 文) にし、 応募者の'
          '回答に簡単な相づち/掘り下げをしてから次の質問へ進みます。 面接官'
          'として自然に振る舞ってください。';
    }
    // 営業ロープレ: 商談相手の人物像 + アプローチ方法 (= ユーザー要望)。
    final counterpart = _counterpartCtrl.text.trim();
    if (_isPickup) {
      final ageRange = '$_pickupAgeMin〜$_pickupAgeMax歳';
      final place = _pickupPlaceCtrl.text.trim();
      final approachLabel = _approach == 'sns' ? 'SNS' : '対面';
      // ── 場面 + 人物像 は 1 つの任意項目 (_topicCtrl) に統合 (= ユーザー要望) ──
      final sceneAndPersona = _topicCtrl.text.trim();
      final randomRule = _pickupRandomAi
          ? ' 相手の人物像と具体的な場面は、あなたが自然で現実的にランダム設定してください。'
              ' 初回の返答では、会話として不自然にならない範囲で、どんな相手・場面かが伝わるようにしてください。'
          : (sceneAndPersona.isNotEmpty
              ? ' 練習したい場面・相手の人物像:「$sceneAndPersona」。 この設定に沿って、場面の空気と相手の人物像になりきってください。'
              : ' 具体的な場面と相手の人物像は、あなたが自然で現実的に決めてください。');
      return 'あなたはユーザーの会話練習の相手です。'
          '$randomRule'
          '${place.isNotEmpty ? ' 場所:「$place」。' : ''}'
          ' 相手は成人で、年齢範囲は「$ageRange」です。'
          ' これは「$approachLabel」 で自然に距離を縮める練習です。'
          '${_approach == 'sns' ? ' SNSの文面・返信間隔・既読後の温度感も自然に表現してください。' : ' 対面での距離感、表情、場の空気に合う反応をしてください。'}'
          ' 相手の立場を尊重し、嫌がる反応や断りも自然に出してください。'
          ' ユーザーが失礼・強引・不自然な言い方をしたら、会話相手として自然に引き、'
          ' 改善につながる余地を残してください。 音声会話なので 1 回の発話は短め (2〜3 文) に。';
    }
    final approachLabel = _approach == 'phone'
        ? '電話'
        : _approach == 'online'
            ? 'オンライン会議 (ビデオ通話)'
            : '対面';
    return 'あなたは見込み客 (クライアント) です。 営業担当者 (ユーザー) が'
        'あなたに「$topic」を売り込んできます。'
        '${counterpart.isNotEmpty ? ' あなた (クライアント) の人物像:「$counterpart」。 この人物になりきってください。' : ''}'
        ' これは「$approachLabel」 でのアプローチです。 $approachLabelならではの'
        '間合い・話し方 (例: 電話なら相手の顔が見えない前提でテンポよく、 対面'
        'なら表情や資料に言及、 オンラインなら画面共有を想定) で応じてください。'
        ' クライアントとして自然に、 時に懐疑的な質問や、 予算・競合・導入'
        'リスクへの懸念を投げかけ、 商談のように会話してください。 音声会話なので'
        '1 回の発話は短め (2〜3 文) に。 簡単には承諾せず、 リアルな反応を'
        'してください。';
  }

  String _buildPrompt(MindMapProvider provider, {String? userMsg}) {
    final s = StringBuffer();
    s.writeln(_systemPrompt());
    s.writeln(provider.languageInstructionForAi());
    // ── 下調べの結果 (= ユーザー要望: Web と手元の資料を見て面接させる) ──
    if (_refDigest.trim().isNotEmpty) {
      s.writeln('\n# 下調べ資料 (実際に調べた内容)');
      s.writeln(_refDigest.trim());
      s.writeln('この資料に書かれていることは事実として扱ってください。'
          ' 資料に無いことを推測で断定してはいけません。'
          ' 【過去に出た質問】 がある場合は、 そこにある質問を優先して'
          '尋ねてください (そのまま、 あるいは言い回しを少し変えて)。');
    }
    s.writeln('\n# 応答ルール');
    s.writeln(_isPickup
        ? '次の発話は会話相手として自然な 1〜2 文、80字以内にしてください。解説や長い助言は不要です。'
        : '次の発話は音声会話向けに短く、2〜3文以内にしてください。');
    s.writeln('\n# これまでの会話');
    if (_msgs.isEmpty) {
      s.writeln(_isInterview
          ? '(まだありません。 簡単に挨拶して、 最初の面接質問を 1 つしてください)'
          : _isPickup
              ? '(まだありません。 相手として自然に短く返答し、会話を始めてください)'
              : '(まだありません。 クライアントとして軽く挨拶し、 用件を尋ねてください)');
    }
    final recentMsgs =
        _msgs.length > 10 ? _msgs.sublist(_msgs.length - 10) : _msgs;
    if (recentMsgs.length < _msgs.length) {
      s.writeln('(古い会話は省略。直近 ${recentMsgs.length} 件だけを参考にしてください)');
    }
    for (final m in recentMsgs) {
      s.writeln('${m.role == 'user' ? 'ユーザー' : 'あなた'}: ${m.text}');
    }
    if (userMsg != null) s.writeln('ユーザー: $userMsg');
    s.writeln('\nあなたの次の発話:');
    return s.toString();
  }

  Future<void> _ask(String prompt) async {
    final provider = context.read<MindMapProvider>();
    setState(() => _loading = true);
    _scrollToEnd();
    try {
      // 発表の動画から抜いたコマは**最初の 1 往復にだけ**添える
      //   (毎回付けると同じ画像の分だけ何度も課金される)。
      final photos =
          (_isPresentation && _msgs.isEmpty && _presentFrames.isNotEmpty)
              ? _presentFrames
              : null;
      final r = (await provider.askAi(
        prompt,
        images: photos,
        maxTokensOverride: _isPickup ? 700 : 900,
        timeoutOverride: _isPickup
            ? const Duration(seconds: 90)
            : const Duration(seconds: 75),
      ))
          .trim();
      if (!mounted) return;
      setState(() {
        _msgs.add((role: 'ai', text: r));
        _loading = false;
      });
      _speak(r);
    } catch (e) {
      if (!mounted) return;
      final text = context
          .read<MindMapProvider>()
          .t('common.errorPrefix')
          .replaceFirst('{err}', '$e');
      setState(() {
        _msgs.add((role: 'ai', text: text));
        _loading = false;
      });
    }
    _scrollToEnd();
  }

  Future<void> _startConversation() async {
    final provider = context.read<MindMapProvider>();
    if (!provider.hasActiveAiKey) {
      _snack(provider.t('talk.apiKeyRequired'));
      return;
    }
    // 受験面接は学校名が要る (= その学校に合わせて聞くため)。
    if (_isExam) {
      if (_schoolCtrl.text.trim().isEmpty) {
        _snack(provider.t('talk.schoolRequired'));
        return;
      }
    } else if (_topicCtrl.text.trim().isEmpty && !_isPickup) {
      // ナンパ練習は「場面・人物像」 が任意項目なので、 空でも開始できる
      //   (= ユーザー要望: 1 つの任意項目としてまとめて最下部に置く)。
      _snack(provider.t(_isPresentation
          ? 'talk.presentRequired'
          : _isLicense
              ? 'talk.licenseRequired'
              : _isInterview
                  ? 'talk.companyRequired'
                  : 'talk.productRequired'));
      return;
    }
    // 設定を保存 (= ユーザー要望: 次回開いた時に前回の設定を復元)。
    // ignore: discarded_futures
    _saveCurrentSettings();
    // 人物像に合う声へ切り替えてから始める (= ユーザー要望)。
    // ignore: discarded_futures
    _applyVoiceForPersona();
    // 下調べ (Web + 手元の資料) を済ませてから会話に入る (= ユーザー要望)。
    await _gatherReference(provider);
    if (!mounted) return;
    setState(() => _started = true);
    await _ask(_buildPrompt(provider));
  }

  // ─────────── プレゼンテーション (= ユーザー要望) ───────────

  Future<void> _savePresentSettings() async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString('presentTopic', _topicCtrl.text.trim());
      await sp.setString('presentScript', _achieveCtrl.text.trim());
      await sp.setString('presentScene', _presentScene);
    } catch (_) {}
  }

  Future<void> _loadPresentSettings() async {
    try {
      final sp = await SharedPreferences.getInstance();
      if (!mounted) return;
      setState(() {
        _topicCtrl.text = sp.getString('presentTopic') ?? '';
        _achieveCtrl.text = sp.getString('presentScript') ?? '';
        final sc = sp.getString('presentScene');
        if (sc == 'academic' || sc == 'business' || sc == 'class') {
          _presentScene = sc!;
        }
      });
    } catch (_) {}
  }

  /// 発表の動画を選ぶ。 音声は書き起こせないので、 何コマか静止画にして
  /// 「資料の見え方・進め方」 を見てもらう (= ユーザー要望: 動画も渡したい)。
  Future<void> _pickPresentVideo() async {
    final provider = context.read<MindMapProvider>();
    try {
      final res = await FilePicker.platform.pickFiles(
        type: FileType.custom,
        allowedExtensions: ['mp4', 'mov', 'm4v', 'webm', 'mkv'],
      );
      final path = res?.files.single.path;
      if (path == null || !mounted) return;
      setState(() {
        _presentVideoPath = path;
        _presentVideoName = res!.files.single.name;
        _presentFrames = const [];
        _extractingFrames = true;
      });
      final frames = await _extractVideoFrames(path);
      if (!mounted) return;
      setState(() {
        _presentFrames = frames;
        _extractingFrames = false;
      });
      if (frames.isEmpty) _snack(provider.t('talk.presentVideoNoFrames'));
    } catch (_) {
      if (mounted) setState(() => _extractingFrames = false);
    }
  }

  /// 動画から等間隔で数コマ抜き出して画像にする。
  /// ffmpeg が見つからない環境では空を返す (動画なしとして続ける)。
  Future<List<AiInputImage>> _extractVideoFrames(String path,
      {int count = 6}) async {
    try {
      if (kIsWeb || !(Platform.isWindows || Platform.isMacOS || Platform.isLinux)) {
        return const [];
      }
      final exe = await findFfmpegExe();
      if (exe == null) return const [];
      final dir = await getTemporaryDirectory();
      final outDir = Directory(
          '${dir.path}${Platform.pathSeparator}present_${DateTime.now().millisecondsSinceEpoch}');
      await outDir.create(recursive: true);
      // 等間隔で count 枚。 横 960px に落として送る量を抑える。
      final pattern = '${outDir.path}${Platform.pathSeparator}f%02d.jpg';
      final r = await Process.run(exe, [
        '-hide_banner',
        '-loglevel', 'error',
        '-i', path,
        '-vf', "fps=1/10,scale=960:-1",
        '-frames:v', '$count',
        '-q:v', '4',
        pattern,
      ]).timeout(const Duration(minutes: 3));
      if (r.exitCode != 0) debugPrint('コマ抜き出しの警告: ${r.stderr}');
      final out = <AiInputImage>[];
      final files = outDir
          .listSync()
          .whereType<File>()
          .where((f) => f.path.toLowerCase().endsWith('.jpg'))
          .toList()
        ..sort((a, b) => a.path.compareTo(b.path));
      for (final f in files.take(count)) {
        out.add(AiInputImage(
          mime: 'image/jpeg',
          base64: base64Encode(await f.readAsBytes()),
          name: f.uri.pathSegments.last,
        ));
      }
      return out;
    } catch (e) {
      debugPrint('動画のコマ抜き出しに失敗: $e');
      return const [];
    }
  }

  /// 資格面接の設定を覚えておく。
  Future<void> _saveLicenseSettings() async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString('licenseName', _topicCtrl.text.trim());
      await sp.setString('licenseAchieve', _achieveCtrl.text.trim());
      await sp.setString('licenseStyle', _licenseStyle);
    } catch (_) {}
  }

  Future<void> _loadLicenseSettings() async {
    try {
      final sp = await SharedPreferences.getInstance();
      if (!mounted) return;
      setState(() {
        _topicCtrl.text = sp.getString('licenseName') ?? '';
        _achieveCtrl.text = sp.getString('licenseAchieve') ?? '';
        final st = sp.getString('licenseStyle');
        if (st == 'personal' || st == 'group' || st == 'oral') {
          _licenseStyle = st!;
        }
      });
    } catch (_) {}
  }

  Future<void> _saveCurrentSettings() async {
    // ignore: discarded_futures
    _saveRefSettings();
    if (_isPresentation) {
      await _savePresentSettings();
    } else if (_isLicense) {
      await _saveLicenseSettings();
    } else if (_isExam) {
      await _saveExamSettings();
    } else if (_isInterview) {
      await _saveInterviewSettings();
    } else if (_isPickup) {
      await _savePickupSettings();
    } else {
      await _saveRoleplaySettings();
    }
  }

  /// 受験面接の設定を覚えておく (= 次に開いた時にそのまま使えるように)。
  Future<void> _saveExamSettings() async {
    try {
