  // ─────────────── 下調べ (Web + 手元の資料) ───────────────

  /// 下調べに使う相手の名前 (学校名 / 会社名 / 製品名)。
  String _refTopic() {
    if (_isExam) {
      final s = _schoolCtrl.text.trim();
      final d = _schoolDeptCtrl.text.trim();
      return d.isEmpty ? s : '$s $d';
    }
    return _topicCtrl.text.trim();
  }

  /// Web の下調べを使えるモードか (会話練習は相手が実在しないので対象外)。
  bool get _canWebLookup => !_isPickup;

  Future<void> _loadRefSettings() async {
    try {
      final sp = await SharedPreferences.getInstance();
      final on = sp.getBool('aitalk_ref_web_$_mode');
      final paths =
          sp.getStringList('aitalk_ref_files_$_mode') ?? const [];
      final key = sp.getString('aitalk_ref_key_$_mode') ?? '';
      final digest = sp.getString('aitalk_ref_digest_$_mode') ?? '';
      if (!mounted) return;
      setState(() {
        _useWebLookup = on ?? _canWebLookup;
        _refFiles
          ..clear()
          ..addAll(paths.where((p) => p.trim().isNotEmpty).map((p) => (
                path: p,
                name: p.split(RegExp(r'[\\/]')).last,
                text: '',
              )));
        _refKey = key;
        _refDigest = digest;
      });
    } catch (_) {}
  }

  Future<void> _saveRefSettings() async {
    try {
      final on = _useWebLookup;
      final paths = _refFiles.map((f) => f.path).toList();
      final key = _refKey;
      final digest = _refDigest;
      final sp = await SharedPreferences.getInstance();
      await sp.setBool('aitalk_ref_web_$_mode', on);
      await sp.setStringList('aitalk_ref_files_$_mode', paths);
      await sp.setString('aitalk_ref_key_$_mode', key);
      await sp.setString('aitalk_ref_digest_$_mode', digest);
    } catch (_) {}
  }

  /// 資料ファイルを追加する (= ユーザー要望: 「事前にこんな質問が来た」 と
  /// いうテキストファイル等を上げて、 それを見ながら面接してほしい)。
  Future<void> _pickRefFiles() async {
    final p = context.read<MindMapProvider>();
    try {
      final res = await FilePicker.platform.pickFiles(
        allowMultiple: true,
        type: FileType.custom,
        allowedExtensions: TalkReference.allowedExtensions,
      );
      if (res == null) return;
      final added = <({String path, String name, String text})>[];
      for (final f in res.files) {
        final path = f.path;
        if (path == null || path.trim().isEmpty) continue;
        if (_refFiles.any((e) => e.path == path)) continue;
        added.add((path: path, name: f.name, text: ''));
      }
      if (added.isEmpty || !mounted) return;
      setState(() {
        _refFiles.addAll(added);
        // 資料が変わったので、 前回のまとめは使わずに作り直す。
        _refKey = '';
      });
      // ignore: discarded_futures
      _saveRefSettings();
    } catch (_) {
      if (mounted) _snack(p.t('talk.refFileError'));
    }
  }

  void _removeRefFile(String path) {
    setState(() {
      _refFiles.removeWhere((f) => f.path == path);
      _refKey = '';
    });
    // ignore: discarded_futures
    _saveRefSettings();
  }

  /// 開始前に下調べをして、 プロンプトに渡す資料 (_refDigest) を用意する。
  ///
  /// 条件が前回と同じなら作り直さない (通信も AI の料金も無駄になるため)。
  Future<void> _gatherReference(MindMapProvider provider) async {
    final topic = _refTopic();
    final useWeb = _useWebLookup && _canWebLookup && topic.isNotEmpty;
    final key = [
      _mode,
      useWeb ? 'web' : '-',
      topic,
      _refFiles.map((f) => f.path).join('|'),
    ].join('##');
    if (key == _refKey && _refDigest.trim().isNotEmpty) return;
    if (!useWeb && _refFiles.isEmpty) {
      if (mounted) {
        setState(() {
          _refDigest = '';
          _refKey = key;
        });
      }
      return;
    }
    setState(() {
      _gathering = true;
      _gatherStatus = provider.t('talk.refGathering');
    });
    final sources = <TalkRefSource>[];
    // ① 手元の資料 (過去の質問集など) を先に読む。
    if (_refFiles.isNotEmpty) {
      if (mounted) {
        setState(() => _gatherStatus = provider.t('talk.refGatherFile'));
      }
      for (var i = 0; i < _refFiles.length; i++) {
        final f = _refFiles[i];
        final text = f.text.isNotEmpty
            ? f.text
            : (await TalkReference.extractFileText(f.path) ?? '');
        if (text.trim().isEmpty) continue;
        _refFiles[i] = (path: f.path, name: f.name, text: text);
        sources.add(
            TalkRefSource('${provider.t('talk.refFileLabel')}: ${f.name}', text));
      }
    }
    // ② Web で相手を調べる。
    if (useWeb) {
      if (mounted) {
        setState(() => _gatherStatus = provider.t('talk.refGatherWeb'));
      }
      try {
        sources.addAll(await TalkReference.lookupWeb(topic,
            lang: provider.appLanguage));
      } catch (_) {}
    }
    if (sources.isEmpty) {
      if (mounted) {
        setState(() {
          _refDigest = '';
          _refKey = key;
          _gathering = false;
          _gatherStatus = '';
        });
        _snack(provider.t('talk.refNone'));
      }
      return;
    }
    final raw = StringBuffer();
    for (final s in sources) {
      raw.writeln('== ${s.label} ==');
      raw.writeln(s.text);
      raw.writeln();
    }
    var digest = raw.toString().trim();
    // 長いまま毎ターン送ると料金がかさむので、 一度だけまとめさせる。
    if (digest.length > 1800) {
      if (mounted) {
        setState(() => _gatherStatus = provider.t('talk.refGatherSummary'));
      }
      try {
        final sum = (await provider.askAi(
          _refSummaryPrompt(provider, digest),
          maxTokensOverride: 1600,
          timeoutOverride: const Duration(seconds: 90),
        ))
            .trim();
        if (sum.isNotEmpty) digest = sum;
      } catch (_) {
        digest = digest.substring(0, 1800);
      }
    }
    if (!mounted) return;
    setState(() {
      _refDigest = digest;
      _refKey = key;
      _gathering = false;
      _gatherStatus = '';
    });
    // ignore: discarded_futures
    _saveRefSettings();
    _snack(provider
        .t('talk.refReady')
        .replaceFirst('{n}', '${sources.length}'));
  }

  String _refSummaryPrompt(MindMapProvider provider, String raw) {
    final s = StringBuffer();
    s.writeln('次の資料は、 これから行う模擬面接 / 商談のための下調べです。');
    s.writeln('相手役を演じるのに要る事実だけを 800 字以内にまとめてください。');
    s.writeln(provider.languageInstructionForAi());
    s.writeln('\n決まり:');
    s.writeln('- 資料に書かれていないことを足さない。 推測で補わない。');
    s.writeln('- 【相手の特徴】 (建学の精神・校風・教育方針・求める人物像・'
        '事業内容・強みなど) と 【過去に出た質問】 の 2 つに分ける。');
    s.writeln('- 過去に出た質問が資料にある場合は、 言い回しを変えずに'
        'そのまま箇条書きで残す (最大 20 件)。');
    s.writeln('- 案内文・問い合わせ先・広告など、 面接や商談に関係ない部分は捨てる。');
    s.writeln('- 前置きや感想は書かず、 まとめだけを返す。');
    s.writeln('\n--- 資料ここから ---');
    s.writeln(raw.length > 24000 ? raw.substring(0, 24000) : raw);
    s.writeln('--- 資料ここまで ---');
    return s.toString();
  }

