  /// 保存済みのナンパ練習設定を復元する。
  Future<void> _loadPickupSettings() async {
    try {
      final sp = await SharedPreferences.getInstance();
      if (!mounted) return;
      setState(() {
        _topicCtrl.text = sp.getString('aitalk_pickup_combo') ?? '';
        _pickupPlaceCtrl.text = sp.getString('aitalk_pickup_place') ?? '';
        final ap = sp.getString('aitalk_pickup_approach');
        if (ap != null && (ap == 'inperson' || ap == 'sns')) {
          _approach = ap;
        }
        _pickupAgeMin =
            (sp.getInt('aitalk_pickup_age_min') ?? 20).clamp(18, 80).toInt();
        _pickupAgeMax =
            (sp.getInt('aitalk_pickup_age_max') ?? 35).clamp(18, 80).toInt();
        if (_pickupAgeMax < _pickupAgeMin) _pickupAgeMax = _pickupAgeMin;
        _pickupRandomAi = sp.getBool('aitalk_pickup_random') ?? false;
      });
    } catch (_) {}
  }

  Future<void> _send() async {
    final text = _input.text.trim();
    if (text.isEmpty || _loading) return;
    final provider = context.read<MindMapProvider>();
    if (!provider.hasActiveAiKey) return;
    final prompt = _buildPrompt(provider, userMsg: text);
    setState(() {
      _msgs.add((role: 'user', text: text));
      _input.clear();
    });
    await _ask(prompt);
  }

  Future<void> _evaluate() async {
    final provider = context.read<MindMapProvider>();
    if (!provider.hasActiveAiKey || _msgs.isEmpty || _evaluating) return;
    try {
      _tts?.stop();
    } catch (_) {}
    setState(() => _evaluating = true);
    final s = StringBuffer();
    // ★ 評価するのは**ユーザーの発言だけ**。 相手役 (AI) の受け答えを
    //   「良かった点」 に挙げてはいけない (= ユーザー報告: こちらが何も
    //   話していないのに、 クライアントの応対が褒められていた)。
    //   ユーザーの発言が無い時は、 その旨だけを短く返させる。
    final userTurns = _msgs.where((m) => m.role == 'user').length;
    s.writeln('【評価の決まり — 必ず守ること】');
    s.writeln('- 評価の対象は「ユーザー」 の発言だけです。 相手役 '
        '(面接官 / クライアント / 会話相手) の発言は**評価に含めないで'
        'ください**。 相手役の態度や言葉づかいを褒めたり直したりしては'
        'いけません。');
    s.writeln('- ユーザーの発言が 1 つも無い場合は、 良かった点や改善点を'
        '作文せず、「まだ話していないので評価できません」 とだけ伝えて'
        'ください。');
    if (userTurns == 0) {
      s.writeln('- 今回、 ユーザーの発言はありません。');
    }
    s.writeln();
    if (_isPresentation) {
      final sceneLabel = _presentScene == 'academic'
          ? '学会・研究発表'
          : _presentScene == 'class'
              ? '授業・ゼミの発表'
              : '社内の報告・提案';
      s.writeln('以下は「${_topicCtrl.text.trim()}」という$sceneLabelの'
          '質疑応答です。 聴衆の視点で、 発表者 (ユーザー) の受け答えを'
          '評価してください。 (1)良かった点 (2)改善点 (3)本番までに直すべき所 '
          'を簡潔にまとめ、 最後に**まだ聞かれていないが本番で聞かれそうな'
          '質問を 3 つ**挙げてください。');
    } else if (_isLicense) {
      final styleLabel = _licenseStyle == 'group'
          ? '集団面接'
          : _licenseStyle == 'oral'
              ? '口頭試問'
              : '個人面接';
      s.writeln('以下は「${_topicCtrl.text.trim()}」の$styleLabelの模擬試験です。 '
          '試験官の視点で、 受験者 (ユーザー) の受け答えを評価してください。 '
          '①良かった点 ②改善点 ③想定合否（合格 / 不合格）とその理由 を、 '
          '簡潔にまとめてください。 職業倫理や説明の分かりやすさも見てください。');
    } else if (_isExam) {
      final school = _schoolCtrl.text.trim();
      final dept = _schoolDeptCtrl.text.trim();
      s.writeln('以下は「$school」($_schoolKindLabel) の入学試験の模擬面接です。'
          '${dept.isNotEmpty ? ' 受験する学部・学科は「$dept」です。' : ''} '
          'その学校の面接官の視点で、 受験生 (ユーザー) の受け答えを評価して'
          'ください。 ①良かった点 ②改善点 ③想定合否（合格 / 不合格）と'
          'その理由 を、 簡潔にまとめてください。');
    } else if (_isInterview) {
      s.writeln('以下は「${_topicCtrl.text.trim()}」の'
          '${_careerType == 'midcareer' ? '中途' : '新卒'}採用面接の模擬会話です。 '
          '面接官の視点で、 応募者 (ユーザー) の受け答えを評価してください。 '
          '①良かった点 ②改善点 '
          '③想定合否（合格 / 不合格）とその理由 を、 簡潔にまとめてください。');
    } else if (_isPickup) {
      final place = _pickupPlaceCtrl.text.trim();
      final approachLabel = _approach == 'sns' ? 'SNS' : '対面';
      s.writeln('以下は「${_topicCtrl.text.trim()}」で自然に会話する練習です。 '
          '相手の年齢範囲は $_pickupAgeMin〜$_pickupAgeMax歳です。 '
          '声のかけ方は「$approachLabel」です。'
          '${place.isNotEmpty ? ' 場所は「$place」です。' : ''}'
          '${_pickupRandomAi ? ' 人物像や場面はAIがランダムに設定した条件です。' : ''}'
          '相手を尊重できていたか、会話が自然だったかの視点で評価してください。 '
          '①良かった点 ②改善点 ③次に試す一言 を、 簡潔にまとめてください。');
    } else {
      s.writeln('以下は「${_topicCtrl.text.trim()}」を売り込む営業ロールプレイの'
          '会話です。 クライアント視点で、 営業担当者 (ユーザー) の受け答えを'
          '評価してください。 ①良かった点 ②改善点 '
          '③成約可能性（高 / 中 / 低）とその理由 を、 簡潔にまとめてください。');
    }
    s.writeln(provider.languageInstructionForAi());
    s.writeln('\n# 会話');
    for (final m in _msgs) {
      final who = m.role == 'user'
          ? 'ユーザー'
          : ((_isInterview || _isExam)
              ? '面接官'
              : (_isPickup ? '相手' : 'クライアント'));
      s.writeln('$who: ${m.text}');
    }
    try {
      final r = (await provider.askAi(s.toString())).trim();
      if (!mounted) return;
      setState(() {
        _verdict = r;
        _evaluating = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _verdict = context
            .read<MindMapProvider>()
            .t('talk.evaluationFailed')
            .replaceFirst('{err}', '$e');
        _evaluating = false;
      });
    }
  }

  /// 設定画面に戻る (= ユーザー要望: 始めた後でも設定をやり直したい)。
  /// 会話と評価は捨てて、 入力した設定はそのまま残す。
  void _backToSetup() {
    try {
      _tts?.stop();
    } catch (_) {}
    try {
      if (_listening) _speech.stop();
    } catch (_) {}
    setState(() {
      _started = false;
      _listening = false;
      _msgs.clear();
      _verdict = null;
      _input.clear();
    });
  }

  void _snack(String m) {
    ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        SnackBar(content: Text(m), duration: const Duration(seconds: 2)));
  }

  void _scrollToEnd() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_scroll.hasClients) {
        _scroll.animateTo(_scroll.position.maxScrollExtent,
            duration: const Duration(milliseconds: 200), curve: Curves.easeOut);
      }
    });
  }

  Future<void> _toggleVoice() async {
    if (_listening) {
      try {
        await _speech.stop();
      } catch (_) {}
      if (mounted) setState(() => _listening = false);
      return;
    }
    if (!_speechInit) {
      try {
        if (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) {
          var mic = await Permission.microphone.status;
          if (!mic.isGranted) mic = await Permission.microphone.request();
          if (!mic.isGranted) return;
        }
        _speechInit = await _speech.initialize(onStatus: (st) {
          if (!mounted) return;
          if (st == 'done' || st == 'notListening') {
            setState(() => _listening = false);
          }
        });
      } catch (_) {
        _speechInit = false;
      }
    }
    if (!_speechInit || !mounted) return;
    final provider = context.read<MindMapProvider>();
    final base = _input.text.trim();
    setState(() => _listening = true);
    try {
      await _speech.listen(
        localeId: provider.speechLocaleId,
        onResult: (r) {
          if (!mounted) return;
          final w = r.recognizedWords;
          _input.text = base.isEmpty ? w : '$base $w';
          _input.selection =
              TextSelection.collapsed(offset: _input.text.length);
        },
      );
    } catch (_) {
      if (mounted) setState(() => _listening = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final isMobile = MediaQuery.of(context).size.width < 600;
    final accent = _isInterview
        ? const Color(0xFF4FC3F7)
        : _isPickup
            ? const Color(0xFFFF5C8A)
            : const Color(0xFF66BB6A);
    return Dialog(
      backgroundColor: const Color(0xFF1A1A2E),
      insetPadding: isMobile ? EdgeInsets.zero : const EdgeInsets.all(24),
      shape: isMobile
          ? const RoundedRectangleBorder(borderRadius: BorderRadius.zero)
          : RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: isMobile ? double.infinity : 580,
        // 設定の項目が増えて下が切れていたので、 画面に収まる範囲で
        // 縦を伸ばす (= ユーザー要望: もう少し下に広げれば全部入る)。
        height: isMobile
            ? double.infinity
            : math.min(920.0, MediaQuery.of(context).size.height - 80),
        child: SafeArea(
          child: Column(children: [
            // ── ヘッダー ──
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 12, 8, 8),
              child: Row(children: [
                Icon(_modeIcon, color: accent, size: 22),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(
                      context.read<MindMapProvider>().t(_modeLabelKey),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 16,
                          fontWeight: FontWeight.w700)),
                ),
                // ── 設定に戻る (= ユーザー要望: 始めた後でも設定を直したい) ──
                if (_started)
                  IconButton(
                    tooltip: context
                        .read<MindMapProvider>()
                        .t('talk.backToSetup'),
                    icon: const Icon(Icons.tune_rounded,
                        color: Colors.white70, size: 20),
                    onPressed: _backToSetup,
                  ),
                // 使うモデルを選べるように (= ユーザー要望: 面接練習と
                //   ロープレでも LLM を選びたい)。 選択はアプリ全体で共有。
                _AiModelPicker(provider: context.read<MindMapProvider>()),
                IconButton(
                  tooltip: context
                      .read<MindMapProvider>()
                      .t(_ttsOn ? 'talk.ttsOn' : 'talk.ttsOff'),
                  icon: Icon(
                      _ttsOn
                          ? Icons.volume_up_rounded
                          : Icons.volume_off_rounded,
                      color: _ttsOn ? accent : Colors.white38,
                      size: 20),
                  onPressed: () {
                    setState(() => _ttsOn = !_ttsOn);
                    if (!_ttsOn) {
                      try {
                        _tts?.stop();
                      } catch (_) {}
                    }
                  },
                ),
                IconButton(
                  icon: const Icon(Icons.close, color: Colors.white54),
                  onPressed: () => Navigator.pop(context),
                ),
              ]),
            ),
            // 残りのトークン量 (= ユーザー要望: 面接の所にも出してほしい)。
            //   AI アシスタントと同じ文言・同じ控えめな白で出す。
            Builder(builder: (ctx) {
              final remain = aiRemainText(ctx.read<MindMapProvider>());
              if (remain.trim().isEmpty) return const SizedBox.shrink();
              return Padding(
                padding: const EdgeInsets.fromLTRB(16, 0, 16, 6),
                child: Align(
                  alignment: Alignment.centerRight,
                  child: Text(remain,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                          color: Colors.white38, fontSize: 10.5)),
                ),
              );
            }),
            const Divider(height: 1, color: Colors.white12),
            Expanded(
                child:
                    _started ? _conversationView(accent) : _setupView(accent)),
          ]),
        ),
      ),
    );
  }

  Widget _setupView(Color accent) {
    final p = context.read<MindMapProvider>();
    return SingleChildScrollView(
      padding: const EdgeInsets.all(18),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        // ── 練習の種類 (= ユーザー要望: 4 つを 1 つのボタンにまとめる) ──
        if (_canSwitchMode) ...[
          Wrap(spacing: 6, runSpacing: 6, children: [
            for (final m in _talkModes)
              ChoiceChip(
                avatar: Icon(m.icon,
                    size: 14,
                    color: _mode == m.mode ? Colors.black : Colors.white54),
                label: Text(p.t(m.labelKey),
                    style: const TextStyle(fontSize: 12)),
                selected: _mode == m.mode,
                backgroundColor: const Color(0xFF2A2A44),
                selectedColor: accent,
                labelStyle: TextStyle(
                    color: _mode == m.mode ? Colors.black : Colors.white70),
                onSelected: (_) => _switchMode(m.mode),
              ),
          ]),
          const SizedBox(height: 14),
        ],
        Text(
            _isPresentation
                ? p.t('talk.presentDescription')
                : _isLicense
                    ? p.t('talk.licenseDescription')
                : _isExam
                    ? p.t('talk.examDescription')
                    : _isInterview
                        ? p.t('talk.interviewDescription')
                        : _isPickup
                            ? p.t('talk.pickupDescription')
                            : p.t('talk.salesDescription'),
            style: const TextStyle(color: Colors.white60, fontSize: 12.5)),
        // ── プレゼンテーションの設定 (= ユーザー要望: 原稿や動画を渡すと
        //    AI が質疑を考えたり評価したりする) ──
        if (_isPresentation) ...[
          const SizedBox(height: 16),
          Text(p.t('talk.presentTitle'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          TextField(
            controller: _topicCtrl,
            style: const TextStyle(color: Colors.white),
            decoration: _talkInputDeco(p.t('talk.presentTitleHint')),
          ),
          const SizedBox(height: 16),
          Text(p.t('talk.presentScene'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          Wrap(spacing: 6, runSpacing: 6, children: [
            for (final k in const [
              ('business', 'talk.presentBusiness'),
              ('academic', 'talk.presentAcademic'),
              ('class', 'talk.presentClass'),
            ])
              ChoiceChip(
                label: Text(p.t(k.$2), style: const TextStyle(fontSize: 12)),
                selected: _presentScene == k.$1,
                backgroundColor: const Color(0xFF2A2A44),
                selectedColor: accent,
                labelStyle: TextStyle(
                    color:
                        _presentScene == k.$1 ? Colors.black : Colors.white70),
                onSelected: (_) => setState(() => _presentScene = k.$1),
              ),
          ]),
          const SizedBox(height: 16),
          Text(p.t('talk.presentScript'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          TextField(
            controller: _achieveCtrl,
            minLines: 5,
            maxLines: 12,
            style: const TextStyle(color: Colors.white),
            decoration: _talkInputDeco(p.t('talk.presentScriptHint')),
          ),
          const SizedBox(height: 6),
          Text(p.t('talk.presentScriptNote'),
              style: const TextStyle(color: Colors.white38, fontSize: 11)),
          const SizedBox(height: 14),
          // ── 発表の動画 (任意) ──
          Container(
            padding: const EdgeInsets.fromLTRB(12, 10, 12, 10),
            decoration: BoxDecoration(
              color: Colors.white.withValues(alpha: 0.05),
              borderRadius: BorderRadius.circular(10),
              border: Border.all(color: Colors.white12),
            ),
            child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(children: [
                    Icon(Icons.movie_creation_outlined, color: accent, size: 18),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(p.t('talk.presentVideo'),
                                style: const TextStyle(
                                    color: Colors.white, fontSize: 12.5)),
                            Text(p.t('talk.presentVideoDesc'),
                                style: const TextStyle(
                                    color: Colors.white38, fontSize: 11)),
                          ]),
                    ),
                    const SizedBox(width: 8),
                    OutlinedButton.icon(
                      style: OutlinedButton.styleFrom(
                          foregroundColor: accent,
                          side: BorderSide(color: accent.withValues(alpha: 0.6)),
                          padding: const EdgeInsets.symmetric(horizontal: 10),
                          minimumSize: const Size(0, 32)),
                      icon: _extractingFrames
                          ? const SizedBox(
                              width: 13,
                              height: 13,
                              child: CircularProgressIndicator(strokeWidth: 2))
                          : const Icon(Icons.attach_file_rounded, size: 16),
                      label: Text(p.t('talk.refAttachBtn'),
                          style: const TextStyle(fontSize: 12)),
                      onPressed: _extractingFrames
                          ? null
                          : () => unawaited(_pickPresentVideo()),
                    ),
                  ]),
                  if (_presentVideoName.isNotEmpty) ...[
                    const SizedBox(height: 8),
                    Row(children: [
                      Icon(Icons.check_circle_rounded,
                          color: accent.withValues(alpha: 0.8), size: 14),
                      const SizedBox(width: 6),
                      Expanded(
                        child: Text(
                            _extractingFrames
                                ? _presentVideoName
                                : p
                                    .t('talk.presentFrames')
                                    .replaceFirst('{name}', _presentVideoName)
                                    .replaceFirst(
                                        '{n}', '${_presentFrames.length}'),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: Colors.white54, fontSize: 11)),
                      ),
                      IconButton(
                        padding: EdgeInsets.zero,
                        constraints:
                            const BoxConstraints(minWidth: 26, minHeight: 26),
                        icon: const Icon(Icons.close_rounded,
                            size: 15, color: Colors.white38),
                        onPressed: () => setState(() {
                          _presentVideoPath = '';
                          _presentVideoName = '';
                          _presentFrames = const [];
                        }),
                      ),
                    ]),
                  ],
                ]),
          ),
        ],
        // ── 資格面接の設定 (= ユーザー要望: 医師国家試験などの資格面接) ──
        if (_isLicense) ...[
          const SizedBox(height: 16),
          Text(p.t('talk.licenseName'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          TextField(
            controller: _topicCtrl,
            style: const TextStyle(color: Colors.white),
            decoration: _talkInputDeco(p.t('talk.licenseNameHint')),
          ),
          const SizedBox(height: 16),
          Text(p.t('talk.licenseStyle'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          Wrap(spacing: 6, runSpacing: 6, children: [
            for (final k in const [
              ('personal', 'talk.licensePersonal'),
              ('group', 'talk.licenseGroup'),
              ('oral', 'talk.licenseOral'),
            ])
              ChoiceChip(
                label: Text(p.t(k.$2), style: const TextStyle(fontSize: 12)),
                selected: _licenseStyle == k.$1,
                backgroundColor: const Color(0xFF2A2A44),
                selectedColor: accent,
                labelStyle: TextStyle(
                    color:
                        _licenseStyle == k.$1 ? Colors.black : Colors.white70),
                onSelected: (_) => setState(() => _licenseStyle = k.$1),
              ),
          ]),
          const SizedBox(height: 16),
          Text(p.t('talk.licenseBackground'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          TextField(
            controller: _achieveCtrl,
            minLines: 3,
            maxLines: 6,
            style: const TextStyle(color: Colors.white),
            decoration: _talkInputDeco(p.t('talk.licenseBackgroundHint')),
          ),
        ],
        // ── 受験面接の設定 (= ユーザー要望: 受ける学校と実績・成績) ──
        if (_isExam) ...[
          const SizedBox(height: 16),
          Text(p.t('talk.schoolKind'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          Wrap(spacing: 6, runSpacing: 6, children: [
            for (final k in const [
              // 大学院は聞かれる内容が学部と別物なので分けている
              // (= ユーザー要望)。
              ('grad', 'talk.schoolGrad'),
              ('university', 'talk.schoolUniv'),
              ('high', 'talk.schoolHigh'),
              ('junior', 'talk.schoolJunior'),
              ('elementary', 'talk.schoolElem'),
            ])
              ChoiceChip(
                label: Text(p.t(k.$2),
                    style: const TextStyle(fontSize: 12)),
                selected: _schoolKind == k.$1,
                backgroundColor: const Color(0xFF2A2A44),
                selectedColor: accent,
                labelStyle: TextStyle(
                    color: _schoolKind == k.$1
                        ? Colors.black
                        : Colors.white70),
                onSelected: (_) => setState(() => _schoolKind = k.$1),
              ),
          ]),
          const SizedBox(height: 16),
          Text(p.t('talk.schoolName'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          TextField(
            controller: _schoolCtrl,
            style: const TextStyle(color: Colors.white),
            decoration: _talkInputDeco(p.t('talk.schoolNameHint')),
          ),
          const SizedBox(height: 16),
          Text(p.t('talk.schoolDept'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          TextField(
            controller: _schoolDeptCtrl,
            style: const TextStyle(color: Colors.white),
            // 大学院は「研究科・専攻」 なので例を変える (= ユーザー要望で
            //   大学院を足したため)。
            decoration: _talkInputDeco(p.t(_schoolKind == 'grad'
                ? 'talk.schoolDeptHintGrad'
                : 'talk.schoolDeptHint')),
          ),
          const SizedBox(height: 16),
          Text(p.t('talk.achievements'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          TextField(
            controller: _achieveCtrl,
            minLines: 3,
            maxLines: 6,
            style: const TextStyle(color: Colors.white),
            decoration: _talkInputDeco(p.t('talk.achievementsHint')),
          ),
          const SizedBox(height: 8),
          Text(
              p.t(_useWebLookup
                  ? 'talk.examSchoolWebNote'
                  : 'talk.examSchoolNote'),
              style: const TextStyle(color: Colors.white38, fontSize: 11)),
        ],
        // ── 上部の主入力欄 (会社名 / 売りたい製品) ──
        // ナンパ練習では「場面＋人物像」 を 1 つの任意項目として最下部に
        //   まとめて置く (= ユーザー要望) ので、 ここでは出さない。
        // 資格面接は上に専用の欄を出しているので、 ここは出さない。
        if (!_isPickup && !_isExam && !_isLicense && !_isPresentation) ...[
          const SizedBox(height: 16),
          Text(
              context
                  .read<MindMapProvider>()
                  .t(_isInterview ? 'talk.companyName' : 'talk.productName'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          TextField(
            controller: _topicCtrl,
            style: const TextStyle(color: Colors.white),
            decoration: _talkInputDeco(context
                .read<MindMapProvider>()
                .t(_isInterview ? 'talk.companyHint' : 'talk.productHint')),
          ),
        ],
        if (_isPickup) ...[
          const SizedBox(height: 12),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
            decoration: BoxDecoration(
              color: Colors.white.withValues(alpha: 0.05),
              borderRadius: BorderRadius.circular(10),
              border: Border.all(color: Colors.white12),
            ),
            child: Row(children: [
              Icon(Icons.auto_awesome_rounded, color: accent, size: 18),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                    context
                        .read<MindMapProvider>()
                        .t('talk.pickupRandomProfile'),
                    style:
                        const TextStyle(color: Colors.white, fontSize: 12.5)),
              ),
              Switch(
                value: _pickupRandomAi,
                activeThumbColor: accent,
                onChanged: (v) => setState(() => _pickupRandomAi = v),
              ),
            ]),
          ),
          const SizedBox(height: 16),
          Text(context.read<MindMapProvider>().t('talk.pickupPlace'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          TextField(
            controller: _pickupPlaceCtrl,
            style: const TextStyle(color: Colors.white),
            decoration: _talkInputDeco(
                context.read<MindMapProvider>().t('talk.pickupPlaceHint')),
          ),
        ],
        if (_isInterview) ...[
          const SizedBox(height: 16),
          Text(context.read<MindMapProvider>().t('talk.applicationType'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          Row(children: [
            _segBtn(
                context.read<MindMapProvider>().t('talk.newgrad'),
                _careerType == 'newgrad',
                () => setState(() => _careerType = 'newgrad'),
                accent),
            const SizedBox(width: 8),
            _segBtn(
                context.read<MindMapProvider>().t('talk.midcareer'),
                _careerType == 'midcareer',
                () => setState(() => _careerType = 'midcareer'),
                accent),
          ]),
          const SizedBox(height: 16),
          // ── 経歴 (= ユーザー要望: 別ページでレコードのように保存・再利用) ──
          Row(children: [
            Text(context.read<MindMapProvider>().t('talk.yourCareer'),
                style: TextStyle(
                    color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
            const Spacer(),
            TextButton.icon(
              style: TextButton.styleFrom(
                  padding: const EdgeInsets.symmetric(horizontal: 8),
                  minimumSize: const Size(0, 28)),
              icon: Icon(Icons.folder_open_rounded, size: 15, color: accent),
              label: Text(
                  context.read<MindMapProvider>().t('talk.manageCareer'),
                  style: TextStyle(color: accent, fontSize: 11.5)),
              onPressed: _openRecordsManager,
            ),
          ]),
          if (_savedCareers.isNotEmpty) ...[
            const SizedBox(height: 2),
            Wrap(spacing: 6, runSpacing: 6, children: [
              for (final c in _savedCareers)
                _recordChip(c, _selectedCareer == c, accent, () {
                  setState(() {
                    if (_selectedCareer == c) {
                      _selectedCareer = null;
                    } else {
                      _selectedCareer = c;
                      _careerCtrl.text = c;
                    }
                  });
                }),
            ]),
          ],
          const SizedBox(height: 6),
          TextField(
            controller: _careerCtrl,
            style: const TextStyle(color: Colors.white),
            minLines: 2,
            maxLines: 5,
            decoration: _talkInputDeco(
                context.read<MindMapProvider>().t('talk.careerHint')),
          ),
          const SizedBox(height: 16),
          Text(context.read<MindMapProvider>().t('talk.qualifications'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          if (_savedQuals.isEmpty)
            Text(context.read<MindMapProvider>().t('talk.registerHint'),
                style: const TextStyle(color: Colors.white38, fontSize: 11.5))
          else
            Wrap(spacing: 6, runSpacing: 6, children: [
              for (final q in _savedQuals)
                _recordChip(q, _selectedQuals.contains(q), accent, () {
                  setState(() {
                    if (!_selectedQuals.add(q)) _selectedQuals.remove(q);
                  });
                }),
            ]),
        ]
        // ★ 受験面接をここへ落とさない (= ユーザー報告: 受験面接の設定に
        //   「商談相手はどんな人？」 と「アプローチ方法」 が出ていた)。
        //   以前は「面接 (就活) 以外」 = ロールプレイ扱いだったため、
        //   後から足した受験面接が営業用の欄を引き連れていた。
        else if (!_isExam && !_isLicense && !_isPresentation) ...[
          // ── 商談相手の人物像 (営業ロープレ専用) ──
          // ナンパ練習では「場面＋人物像」 を 1 つの任意項目として最下部に
          //   まとめて置く (= ユーザー要望) ため、 ここには出さない。
          if (!_isPickup) ...[
            const SizedBox(height: 16),
            Text(context.read<MindMapProvider>().t('talk.clientProfile'),
                style: TextStyle(
                    color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
            const SizedBox(height: 6),
            TextField(
              controller: _counterpartCtrl,
              style: const TextStyle(color: Colors.white),
              minLines: 2,
              maxLines: 4,
              decoration: _talkInputDeco(
                  context.read<MindMapProvider>().t('talk.counterpartHint')),
            ),
          ],
          if (_isPickup) ...[
            const SizedBox(height: 16),
            Text(context.read<MindMapProvider>().t('talk.pickupAgeRange'),
                style: TextStyle(
                    color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
            const SizedBox(height: 6),
            Container(
              padding: const EdgeInsets.fromLTRB(12, 10, 12, 6),
              decoration: BoxDecoration(
                color: Colors.white.withValues(alpha: 0.06),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: Colors.white12),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(children: [
                    Icon(Icons.woman_rounded, color: accent, size: 18),
                    const SizedBox(width: 8),
                    Text(
                        context
                            .read<MindMapProvider>()
                            .t('talk.pickupAgeRangeValue')
                            .replaceFirst('{min}', '$_pickupAgeMin')
                            .replaceFirst('{max}', '$_pickupAgeMax'),
                        style: const TextStyle(
                            color: Colors.white,
                            fontSize: 13,
                            fontWeight: FontWeight.w700)),
                    const Spacer(),
                    Text(
                        context
                            .read<MindMapProvider>()
                            .t('talk.pickupAdultOnly'),
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 11)),
                  ]),
                  RangeSlider(
                    min: 18,
                    max: 80,
                    divisions: 62,
                    values: RangeValues(
                        _pickupAgeMin.toDouble(), _pickupAgeMax.toDouble()),
                    labels: RangeLabels(
                        context
                            .read<MindMapProvider>()
                            .t('talk.ageValue')
                            .replaceFirst('{age}', '$_pickupAgeMin'),
                        context
                            .read<MindMapProvider>()
                            .t('talk.ageValue')
                            .replaceFirst('{age}', '$_pickupAgeMax')),
                    activeColor: accent,
                    inactiveColor: Colors.white24,
                    onChanged: (v) {
                      setState(() {
                        _pickupAgeMin = v.start.round();
                        _pickupAgeMax = v.end.round();
                      });
                    },
                  ),
                ],
              ),
            ),
          ],
          const SizedBox(height: 16),
          Text(
              _isPickup
                  ? context.read<MindMapProvider>().t('talk.pickupApproach')
                  : context.read<MindMapProvider>().t('talk.approach'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          Row(
              children: _isPickup
                  ? [
                      _segBtn(
                          context.read<MindMapProvider>().t('talk.inperson'),
                          _approach == 'inperson',
                          () => setState(() => _approach = 'inperson'),
                          accent),
                      const SizedBox(width: 8),
                      _segBtn('SNS', _approach == 'sns',
                          () => setState(() => _approach = 'sns'), accent),
                    ]
                  : [
                      _segBtn(
                          context.read<MindMapProvider>().t('talk.inperson'),
                          _approach == 'inperson',
                          () => setState(() => _approach = 'inperson'),
                          accent),
                      const SizedBox(width: 8),
                      _segBtn(
                          context.read<MindMapProvider>().t('talk.phone'),
                          _approach == 'phone',
                          () => setState(() => _approach = 'phone'),
                          accent),
                      const SizedBox(width: 8),
                      _segBtn(
                          context.read<MindMapProvider>().t('talk.online'),
                          _approach == 'online',
                          () => setState(() => _approach = 'online'),
                          accent),
                    ]),
          // ── 場面 + 人物像 を 1 つの任意項目として最下部に配置 (= ユーザー
          //    要望)。 AI ランダム設定 ON の時は不要なので隠す。 ──
          if (_isPickup && !_pickupRandomAi) ...[
            const SizedBox(height: 16),
            Text(context.read<MindMapProvider>().t('talk.pickupSceneProfile'),
                style: TextStyle(
                    color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
            const SizedBox(height: 6),
            TextField(
              controller: _topicCtrl,
              style: const TextStyle(color: Colors.white),
              minLines: 2,
              maxLines: 4,
              decoration: _talkInputDeco(
                  context.read<MindMapProvider>().t('talk.pickupSceneHint')),
            ),
          ],
        ],
        // ── 下調べ (= ユーザー要望: Web で調べて、 手元の資料も参照する) ──
        const SizedBox(height: 20),
        _refSection(accent),
        const SizedBox(height: 22),
        SizedBox(
          width: double.infinity,
          child: ElevatedButton.icon(
            style: ElevatedButton.styleFrom(
                backgroundColor: accent,
                foregroundColor: Colors.black,
                // 下調べ中は押せなくするが、 既定の無効色は暗い背景に溶けて
                // ボタンごと消えて見えるので、 色を明示する。
                disabledBackgroundColor: accent.withValues(alpha: 0.45),
                disabledForegroundColor: Colors.black87,
                padding: const EdgeInsets.symmetric(vertical: 12)),
            icon: _gathering
                ? const SizedBox(
                    width: 16,
                    height: 16,
                    child: CircularProgressIndicator(
                        strokeWidth: 2, color: Colors.black54))
                : const Icon(Icons.play_arrow_rounded),
            label: Text(
                _gathering
                    ? (_gatherStatus.isEmpty
                        ? p.t('talk.refGathering')
                        : _gatherStatus)
                    : _isPresentation
                        ? p.t('talk.startPresent')
                        : (_isExam || _isLicense)
                            ? p.t('talk.startExam')
                            : _isInterview
                                ? p.t('talk.startInterview')
                                : _isPickup
                                    ? p.t('talk.startPickup')
                                    : p.t('talk.startSales'),
                style: const TextStyle(fontWeight: FontWeight.w700)),
            onPressed: _gathering ? null : _startConversation,
          ),
        ),
      ]),
    );
  }

  /// 参考資料 (Web の下調べ + 手元のファイル) の設定欄。
  Widget _refSection(Color accent) {
    final p = context.read<MindMapProvider>();
    return Container(
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: Colors.white12),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Icon(Icons.travel_explore_rounded, color: accent, size: 18),
          const SizedBox(width: 8),
          Text(p.t('talk.refSection'),
              style: TextStyle(
                  color: accent, fontSize: 12, fontWeight: FontWeight.w700)),
        ]),
        if (_canWebLookup) ...[
          const SizedBox(height: 6),
          Row(children: [
            Expanded(
              child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(p.t('talk.refWeb'),
                        style: const TextStyle(
                            color: Colors.white, fontSize: 12.5)),
                    Text(p.t('talk.refWebDesc'),
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 11)),
                  ]),
            ),
            Switch(
              value: _useWebLookup,
              activeThumbColor: accent,
              onChanged: (v) {
                setState(() {
                  _useWebLookup = v;
                  _refKey = ''; // 条件が変わったので調べ直す
                });
                // ignore: discarded_futures
                _saveRefSettings();
              },
            ),
          ]),
        ],
        const SizedBox(height: 8),
        Row(children: [
          Expanded(
            child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(p.t('talk.refAttach'),
                      style:
                          const TextStyle(color: Colors.white, fontSize: 12.5)),
                  Text(p.t('talk.refAttachDesc'),
                      style:
                          const TextStyle(color: Colors.white38, fontSize: 11)),
                ]),
          ),
          const SizedBox(width: 8),
          OutlinedButton.icon(
            style: OutlinedButton.styleFrom(
                foregroundColor: accent,
                side: BorderSide(color: accent.withValues(alpha: 0.6)),
                padding: const EdgeInsets.symmetric(horizontal: 10),
                minimumSize: const Size(0, 32)),
            icon: const Icon(Icons.attach_file_rounded, size: 16),
            label: Text(p.t('talk.refAttachBtn'),
                style: const TextStyle(fontSize: 12)),
            onPressed: _pickRefFiles,
          ),
        ]),
        if (_refFiles.isNotEmpty) ...[
          const SizedBox(height: 8),
          Wrap(spacing: 6, runSpacing: 6, children: [
            for (final f in _refFiles)
              Chip(
                label: Text(f.name,
                    style: const TextStyle(color: Colors.white, fontSize: 11.5)),
