  Widget _conversationView(Color accent) {
    if (_verdict != null) {
      return Column(children: [
        Expanded(
          child: SingleChildScrollView(
            padding: const EdgeInsets.all(16),
            child:
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                Icon(Icons.assignment_turned_in_rounded,
                    color: accent, size: 20),
                const SizedBox(width: 8),
                Text(
                    _isInterview
                        ? context
                            .read<MindMapProvider>()
                            .t('talk.interviewFeedback')
                        : _isPickup
                            ? context
                                .read<MindMapProvider>()
                                .t('talk.pickupFeedback')
                            : context
                                .read<MindMapProvider>()
                                .t('talk.salesFeedback'),
                    style: TextStyle(
                        color: accent,
                        fontSize: 15,
                        fontWeight: FontWeight.w700)),
              ]),
              const SizedBox(height: 12),
              Text(_verdict!,
                  style: const TextStyle(
                      color: Colors.white, fontSize: 14, height: 1.5)),
            ]),
          ),
        ),
        const Divider(height: 1, color: Colors.white12),
        Padding(
          padding: const EdgeInsets.all(12),
          child: Row(children: [
            Expanded(
              child: OutlinedButton.icon(
                style: OutlinedButton.styleFrom(
                    foregroundColor: Colors.white70,
                    side: const BorderSide(color: Colors.white24)),
                icon: const Icon(Icons.replay_rounded, size: 18),
                label:
                    Text(context.read<MindMapProvider>().t('talk.backToConv')),
                onPressed: () => setState(() => _verdict = null),
              ),
            ),
            const SizedBox(width: 10),
            Expanded(
              child: ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                    backgroundColor: accent, foregroundColor: Colors.black),
                icon: const Icon(Icons.done_rounded, size: 18),
                label: Text(context.read<MindMapProvider>().t('talk.end')),
                onPressed: () => Navigator.pop(context),
              ),
            ),
          ]),
        ),
      ]);
    }
    return Column(children: [
      Expanded(
        child: ListView.builder(
          controller: _scroll,
          padding: const EdgeInsets.all(12),
          itemCount: _msgs.length + (_loading ? 1 : 0),
          itemBuilder: (c, i) {
            if (i >= _msgs.length) {
              return const Padding(
                padding: EdgeInsets.all(10),
                child: Align(
                  alignment: Alignment.centerLeft,
                  child: SizedBox(
                      width: 22,
                      height: 22,
                      child: CircularProgressIndicator(strokeWidth: 2)),
                ),
              );
            }
            final m = _msgs[i];
            final isUser = m.role == 'user';
            return Align(
              alignment: isUser ? Alignment.centerRight : Alignment.centerLeft,
              child: Container(
                margin: const EdgeInsets.symmetric(vertical: 4),
                padding:
                    const EdgeInsets.symmetric(horizontal: 12, vertical: 9),
                constraints: BoxConstraints(
                    maxWidth: MediaQuery.of(context).size.width * 0.72),
                decoration: BoxDecoration(
                  color: isUser
                      ? accent.withValues(alpha: 0.85)
                      : const Color(0xFF2A2A3E),
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Text(m.text,
                    style: TextStyle(
                        color: isUser ? Colors.black : Colors.white,
                        fontSize: 13.5,
                        height: 1.4)),
              ),
            );
          },
        ),
      ),
      const Divider(height: 1, color: Colors.white12),
      // ── 終了して評価 ──
      Padding(
        padding: const EdgeInsets.fromLTRB(12, 8, 12, 0),
        child: SizedBox(
          width: double.infinity,
          child: OutlinedButton.icon(
            style: OutlinedButton.styleFrom(
                foregroundColor: accent,
                side: BorderSide(color: accent.withValues(alpha: 0.6))),
            icon: _evaluating
                ? const SizedBox(
                    width: 14,
                    height: 14,
                    child: CircularProgressIndicator(strokeWidth: 2))
                : const Icon(Icons.fact_check_rounded, size: 18),
            label: Text(_isInterview
                ? context.read<MindMapProvider>().t('talk.endEvalInterview')
                : context.read<MindMapProvider>().t('talk.endEval')),
            onPressed: _evaluating || _msgs.isEmpty ? null : _evaluate,
          ),
        ),
      ),
      // ── 入力欄 (音声 / テキスト) ──
      Padding(
        padding: const EdgeInsets.fromLTRB(8, 6, 8, 8),
        child: Row(children: [
          IconButton(
            tooltip: context.read<MindMapProvider>().t('talk.voiceInput'),
            icon: Icon(_listening ? Icons.mic : Icons.mic_none_rounded,
                color: _listening ? const Color(0xFFFF5252) : Colors.white60),
            onPressed: _loading ? null : _toggleVoice,
          ),
          Expanded(
            child: TextField(
              controller: _input,
              style: const TextStyle(color: Colors.white, fontSize: 14),
              minLines: 1,
              maxLines: 4,
              textInputAction: TextInputAction.send,
              onSubmitted: (_) => _send(),
              decoration: _talkInputDeco(
                  context.read<MindMapProvider>().t('talk.replyHint')),
            ),
          ),
          const SizedBox(width: 4),
          IconButton(
            icon: Icon(Icons.send_rounded, color: accent),
            onPressed: _loading ? null : _send,
          ),
        ]),
      ),
    ]);
  }

  InputDecoration _talkInputDeco(String hint) => InputDecoration(
        hintText: hint,
        hintStyle: const TextStyle(color: Colors.white24, fontSize: 13),
        filled: true,
        fillColor: Colors.white.withValues(alpha: 0.06),
        contentPadding:
            const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
        border: OutlineInputBorder(
            borderRadius: BorderRadius.circular(8),
            borderSide: BorderSide.none),
      );

  Widget _segBtn(String label, bool sel, VoidCallback onTap, Color accent) {
    return Expanded(
      child: InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(8),
