          Flexible(
            child: Text(label,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(
                    color: selected ? Colors.white : Colors.white70,
                    fontSize: 12)),
          ),
        ]),
      ),
    );
  }
}

/// フラッシュカードの内容について会話しながら出題してくる AI チャット
/// (= ユーザー要望: 会話AIみたいにフラッシュカードを質問してくる)。
class _FlashcardChatDialog extends StatefulWidget {
  final List<({String front, String back, String image})> cards;
  const _FlashcardChatDialog({required this.cards});
  @override
  State<_FlashcardChatDialog> createState() => _FlashcardChatDialogState();
}

class _FlashcardChatDialogState extends State<_FlashcardChatDialog> {
  final List<({String role, String text})> _msgs = []; // role: user | ai
  final TextEditingController _input = TextEditingController();
  final ScrollController _scroll = ScrollController();
  bool _loading = false;
  final stt.SpeechToText _speech = stt.SpeechToText();
  bool _speechInit = false;
  bool _listening = false;

  @override
  void initState() {
    super.initState();
    _start();
  }

  @override
  void dispose() {
    try {
      _speech.cancel();
    } catch (_) {}
    _input.dispose();
    _scroll.dispose();
    super.dispose();
  }

  String _cardsBlock() {
    final b = StringBuffer();
    final n = widget.cards.length < 200 ? widget.cards.length : 200;
    for (int i = 0; i < n; i++) {
      final c = widget.cards[i];
      b.writeln('- ${c.front} = ${c.back}');
    }
    return b.toString();
  }

  String _buildPrompt(MindMapProvider provider, {String? userMsg}) {
    final s = StringBuffer();
    s.writeln('あなたはフレンドリーな学習チューターです。 下のフラッシュカード'
        '(語句=意味) の内容について、 ユーザーと会話しながら出題し理解度を確認'
        'してください。 一度に1問ずつ短く問いかけ、 ユーザーの回答には正誤と'
        '簡単な解説・励ましを返してから次の問題へ進みます。 雑談にも自然に'
        '応じつつ、 基本はカード内容のクイズを続けてください。 返答は簡潔に。');
    s.writeln(provider.languageInstructionForAi());
    s.writeln('\n# フラッシュカード一覧');
    s.write(_cardsBlock());
    s.writeln('\n# これまでの会話');
    if (_msgs.isEmpty) {
      s.writeln('(まだありません。 挨拶して最初の問題を出してください)');
    }
    for (final m in _msgs) {
      s.writeln('${m.role == 'user' ? 'ユーザー' : 'あなた'}: ${m.text}');
    }
    if (userMsg != null) s.writeln('ユーザー: $userMsg');
    s.writeln('\nあなたの次の返答:');
    return s.toString();
  }

  Future<void> _ask(String prompt) async {
    final provider = context.read<MindMapProvider>();
    setState(() => _loading = true);
    _scrollToEnd();
    try {
      final r = await provider.askAi(prompt);
      if (!mounted) return;
      setState(() {
        _msgs.add((role: 'ai', text: r.trim()));
        _loading = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _msgs.add((role: 'ai', text: 'エラーが発生しました: $e'));
        _loading = false;
      });
    }
    _scrollToEnd();
  }

  Future<void> _start() async {
    final provider = context.read<MindMapProvider>();
    if (!provider.hasActiveAiKey) {
      setState(
          () => _msgs.add((role: 'ai', text: 'AI を使うには設定で API キーを登録してください。')));
      return;
    }
    await _ask(_buildPrompt(provider));
  }

  Future<void> _send() async {
    final text = _input.text.trim();
    if (text.isEmpty || _loading) return;
    final provider = context.read<MindMapProvider>();
    if (!provider.hasActiveAiKey) return;
    final prompt = _buildPrompt(provider, userMsg: text);
    setState(() {
      _msgs.add((role: 'user', text: text));
      _input.clear();
    });
    await _ask(prompt);
  }

  void _scrollToEnd() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_scroll.hasClients) {
        _scroll.animateTo(_scroll.position.maxScrollExtent,
            duration: const Duration(milliseconds: 200), curve: Curves.easeOut);
      }
    });
  }

  Future<void> _toggleVoice() async {
    if (_listening) {
      try {
        await _speech.stop();
      } catch (_) {}
      if (mounted) setState(() => _listening = false);
      return;
    }
    if (!_speechInit) {
      try {
        if (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) {
          var mic = await Permission.microphone.status;
          if (!mic.isGranted) mic = await Permission.microphone.request();
          if (!mic.isGranted) return;
        }
        _speechInit = await _speech.initialize(onStatus: (st) {
          if (!mounted) return;
          if (st == 'done' || st == 'notListening') {
            setState(() => _listening = false);
          }
        });
      } catch (_) {
        _speechInit = false;
      }
    }
    if (!_speechInit || !mounted) return;
    final provider = context.read<MindMapProvider>();
    final base = _input.text.trim();
    setState(() => _listening = true);
    try {
      await _speech.listen(
        localeId: provider.speechLocaleId,
        onResult: (r) {
          if (!mounted) return;
          final w = r.recognizedWords;
          _input.text = base.isEmpty ? w : '$base $w';
          _input.selection =
              TextSelection.collapsed(offset: _input.text.length);
        },
      );
    } catch (_) {
      if (mounted) setState(() => _listening = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final isMobile = MediaQuery.of(context).size.width < 600;
    return Dialog(
      backgroundColor: const Color(0xFF1A1A2E),
      insetPadding: isMobile ? EdgeInsets.zero : const EdgeInsets.all(24),
      shape: isMobile
          ? const RoundedRectangleBorder(borderRadius: BorderRadius.zero)
          : RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: isMobile ? double.infinity : 560,
        height: isMobile ? double.infinity : 640,
        child: SafeArea(
          child: Column(children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 12, 8, 8),
              child: Row(children: [
                const Icon(Icons.forum_rounded,
                    color: Color(0xFFBA68C8), size: 22),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(context.read<MindMapProvider>().t('chat.aiQuiz'),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 16,
                          fontWeight: FontWeight.w700)),
                ),
                IconButton(
                  onPressed: () => Navigator.pop(context),
                  icon: const Icon(Icons.close, color: Colors.white70),
                ),
              ]),
            ),
            const Divider(color: Colors.white12, height: 1),
            Expanded(
              child: ListView.builder(
                controller: _scroll,
                padding: const EdgeInsets.all(12),
                itemCount: _msgs.length + (_loading ? 1 : 0),
                itemBuilder: (_, i) {
                  if (i >= _msgs.length) {
                    return const Align(
                      alignment: Alignment.centerLeft,
                      child: Padding(
                        padding: EdgeInsets.all(10),
                        child: SizedBox(
                            width: 18,
                            height: 18,
                            child: CircularProgressIndicator(
                                strokeWidth: 2, color: Color(0xFFBA68C8))),
                      ),
                    );
                  }
                  final m = _msgs[i];
                  final isUser = m.role == 'user';
                  return Align(
                    alignment:
                        isUser ? Alignment.centerRight : Alignment.centerLeft,
                    child: Container(
                      margin: const EdgeInsets.symmetric(vertical: 4),
                      padding: const EdgeInsets.symmetric(
                          horizontal: 12, vertical: 9),
                      constraints: const BoxConstraints(maxWidth: 420),
                      decoration: BoxDecoration(
                        color: isUser
                            ? const Color(0xFF26C6DA)
                            : const Color(0xFF2A2A46),
                        borderRadius: BorderRadius.circular(12),
                      ),
                      child: SelectableText(
                        m.text,
                        style: TextStyle(
                            color: isUser ? Colors.black87 : Colors.white,
                            fontSize: 14,
                            height: 1.35),
                      ),
                    ),
                  );
                },
              ),
            ),
            const Divider(color: Colors.white12, height: 1),
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 8, 12, 12),
              child: Row(children: [
                Expanded(
                  child: TextField(
                    controller: _input,
                    style: const TextStyle(color: Colors.white),
                    minLines: 1,
                    maxLines: 4,
                    textInputAction: TextInputAction.send,
                    onSubmitted: (_) => _send(),
                    decoration: InputDecoration(
                      hintText:
                          context.read<MindMapProvider>().t('chat.inputHint'),
                      hintStyle: const TextStyle(color: Colors.white38),
                      filled: true,
                      fillColor: const Color(0xFF1E1E32),
                      border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(10),
                          borderSide: BorderSide.none),
                      contentPadding: const EdgeInsets.symmetric(
                          horizontal: 14, vertical: 10),
                    ),
                  ),
                ),
                const SizedBox(width: 6),
                Material(
                  color: _listening ? const Color(0xFFEF5350) : Colors.white10,
                  shape: const CircleBorder(),
                  child: InkWell(
                    customBorder: const CircleBorder(),
                    onTap: _toggleVoice,
                    child: Padding(
                      padding: const EdgeInsets.all(11),
                      child: Icon(
                          _listening ? Icons.mic : Icons.mic_none_rounded,
                          color: Colors.white,
                          size: 20),
                    ),
                  ),
                ),
                const SizedBox(width: 6),
                Material(
                  color: const Color(0xFFBA68C8),
                  shape: const CircleBorder(),
                  child: InkWell(
                    customBorder: const CircleBorder(),
                    onTap: _loading ? null : _send,
                    child: const Padding(
                      padding: EdgeInsets.all(11),
                      child: Icon(Icons.send_rounded,
                          color: Colors.white, size: 20),
                    ),
                  ),
                ),
              ]),
            ),
          ]),
        ),
      ),
    );
  }
}

class _FlashcardStore {
  static String _key(String pageId) => 'flashcards_$pageId';
  // 「全体」 スコープのカードは全マップ共通のこのキーに保存する。
  static const String _globalKey = 'flashcards_global';

  static List<_FCard> _decode(String? raw, {required bool global}) {
    if (raw == null || raw.isEmpty) return [];
    try {
      final List<dynamic> arr = jsonDecode(raw);
      return arr.whereType<Map>().map((m) {
        return (
          front: (m['f'] ?? '').toString(),
          back: (m['b'] ?? '').toString(),
          group: (m['g'] ?? '').toString(),
          global: global,
          image: (m['img'] ?? '').toString(),
          imageSide: (m['imgs'] ?? 'front').toString(),
        );
      }).toList();
    } catch (_) {
      return [];
    }
  }

  /// このマップ固有 + 全体共有 のカードを結合して返す。
  static Future<List<_FCard>> load(String pageId) async {
    final sp = await SharedPreferences.getInstance();
    final pageCards = _decode(sp.getString(_key(pageId)), global: false);
    final globalCards = _decode(sp.getString(_globalKey), global: true);
    return [...pageCards, ...globalCards];
  }

  /// カードを「全体 / このマップ」 に振り分けて保存する。 渡される [cards] は
  /// load() で結合された全件 (= 全体カードも含む) である前提。
  static Future<void> saveList(String pageId, List<_FCard> cards) async {
    final sp = await SharedPreferences.getInstance();
    final page = cards.where((c) => !c.global).toList();
    final glob = cards.where((c) => c.global).toList();
    Map<String, String> enc(_FCard c) {
      final m = {'f': c.front, 'b': c.back, 'g': c.group};
      if (c.image.isNotEmpty) {
        m['img'] = c.image;
        m['imgs'] = c.imageSide.isEmpty ? 'front' : c.imageSide;
      }
      return m;
    }

    if (page.isEmpty) {
      await sp.remove(_key(pageId));
    } else {
      await sp.setString(_key(pageId), jsonEncode(page.map(enc).toList()));
    }
    if (glob.isEmpty) {
      await sp.remove(_globalKey);
    } else {
      await sp.setString(_globalKey, jsonEncode(glob.map(enc).toList()));
    }
  }

  static Future<void> add(String pageId, _FCard card) async {
    final list = await load(pageId);
    list.add(card);
    await saveList(pageId, list);
  }

  static Future<void> update(String pageId, int i, _FCard card) async {
    final list = await load(pageId);
    if (i < 0 || i >= list.length) return;
    list[i] = card;
    await saveList(pageId, list);
  }

  static Future<void> removeAt(String pageId, int i) async {
    final list = await load(pageId);
    if (i < 0 || i >= list.length) return;
    list.removeAt(i);
    await saveList(pageId, list);
  }

  /// 指定したカードをまとめて消す (= ユーザー要望: Ctrl / Shift で選んで削除)。
  /// 並び順ではなく中身で照合するので、 絞り込み表示中でも間違えない。
  static Future<void> removeCards(
      String pageId, List<_FCard> targets) async {
    if (targets.isEmpty) return;
    final list = await load(pageId);
    bool same(_FCard a, _FCard b) =>
        a.front == b.front && a.back == b.back && a.global == b.global;
    final kept = <_FCard>[];
    final pending = [...targets];
    for (final c in list) {
      final at = pending.indexWhere((t) => same(t, c));
      if (at >= 0) {
        pending.removeAt(at); // 同じ内容が複数あっても選んだ数だけ消す
        continue;
      }
      kept.add(c);
    }
    await saveList(pageId, kept);
  }

  /// 指定したカードのフォルダー (テーマ) をまとめて付け替える
  /// (= ユーザー要望: フォルダーに格納してテーマ毎にまとめる)。
  static Future<void> setGroupFor(
      String pageId, List<_FCard> targets, String group) async {
    if (targets.isEmpty) return;
    final list = await load(pageId);
    bool same(_FCard a, _FCard b) =>
        a.front == b.front && a.back == b.back && a.global == b.global;
    final pending = [...targets];
    final out = <_FCard>[];
    for (final c in list) {
      final at = pending.indexWhere((t) => same(t, c));
      if (at >= 0) {
        pending.removeAt(at);
        out.add((
          front: c.front,
          back: c.back,
          group: group,
          global: c.global,
          image: c.image,
          imageSide: c.imageSide,
        ));
        continue;
      }
      out.add(c);
    }
    await saveList(pageId, out);
  }
}

// ─── ガントチャート (= ユーザー要望: ガントチャートのページ) ───
// タスクはノードと独立に prefs (gantt_<pageId>) に保存する (モデル非依存)。
typedef _GanttTask = ({
  String id,
  String name,
  int startMs,
  int endMs,
  int color,
  // ── 担当者名 (= ユーザー要望: ガントにユーザー名を記載できるように) ──
  String assignee,
});

/// 1 枚のガントチャート (= ユーザー要望: チャート自体を複数作成できるように)。
/// 名前 + 表示単位 + 表示時間帯 + タスク群。
GanttBlockedInterval? _tryParseGanttBlockedInterval(Map value) {
  try {
    return GanttBlockedInterval.fromJson(value);
  } catch (_) {
    return null;
  }
}

class _GanttChart {
  String name;
  String kind; // 'gantt' | 'schedule' (= ユーザー要望: 人×日付の予定表)
  String unit; // 'day' | 'hour'
  int fromHour;
  int toHour;
  List<GanttBlockedInterval> blockedIntervals;
  List<_GanttTask> tasks;
  // ── schedule 用: 人(行) × 日付(列) の予定グリッド ──
  List<String> people;
  int schedStartMs; // 先頭日 (0:00)
  int schedDays; // 日数 (列数)
  Map<String, String> cells; // key 'r_c' → 予定テキスト
  _GanttChart({
    required this.name,
    this.kind = 'gantt',
    this.unit = 'day',
    this.fromHour = 6,
    this.toHour = 24,
    List<GanttBlockedInterval>? blockedIntervals,
    List<_GanttTask>? tasks,
    List<String>? people,
    this.schedStartMs = 0,
    this.schedDays = 7,
    Map<String, String>? cells,
  })  : blockedIntervals = blockedIntervals ?? [],
        tasks = tasks ?? [],
        people = people ?? ['自分'],
        cells = cells ?? {};

  Map<String, dynamic> toJson() => {
        'name': name,
        'kind': kind,
        'unit': unit,
        'from': fromHour,
        'to': toHour,
        'blocked': blockedIntervals.map((interval) => interval.toJson()).toList(),
        'tasks': tasks
            .map((t) => {
                  'id': t.id,
                  'n': t.name,
                  's': t.startMs,
                  'e': t.endMs,
                  'c': t.color,
                  'a': t.assignee,
                })
            .toList(),
        if (kind == 'schedule') ...{
          'people': people,
          'ss': schedStartMs,
          'sd': schedDays,
          'cells': cells,
        },
      };

  factory _GanttChart.fromJson(Map m) => _GanttChart(
        name: (m['name'] ?? '').toString(),
        kind: m['kind'] == 'schedule' ? 'schedule' : 'gantt',
        unit: m['unit'] == 'hour' ? 'hour' : 'day',
        fromHour: (m['from'] as num?)?.toInt() ?? 6,
        toHour: (m['to'] as num?)?.toInt() ?? 24,
        blockedIntervals: normalizeGanttBlockedIntervals(
          ((m['blocked'] as List?) ?? const [])
              .whereType<Map>()
              .map(_tryParseGanttBlockedInterval)
              .whereType<GanttBlockedInterval>(),
        ),
        tasks: ((m['tasks'] as List?) ?? const [])
            .whereType<Map>()
            .map((x) => (
                  id: (x['id'] ?? '').toString(),
                  name: (x['n'] ?? '').toString(),
                  startMs: (x['s'] as num?)?.toInt() ?? 0,
                  endMs: (x['e'] as num?)?.toInt() ?? 0,
                  color: (x['c'] as num?)?.toInt() ?? 0xFF4FC3F7,
                  assignee: (x['a'] ?? '').toString(),
                ))
            .toList(),
        people: ((m['people'] as List?) ?? const [])
            .map((e) => e.toString())
            .toList(),
        schedStartMs: (m['ss'] as num?)?.toInt() ?? 0,
        schedDays: (m['sd'] as num?)?.toInt() ?? 7,
        cells: ((m['cells'] as Map?) ?? const {})
            .map((k, v) => MapEntry(k.toString(), v.toString())),
      );
}

class _GanttStore {
  static String _key(String pageId) => 'gantt_$pageId';
  static String _unitKey(String pageId) => 'gantt_unit_$pageId';
  static String _chartsKey(String pageId) => 'gantt_charts_$pageId';

  /// 複数チャート対応の読み込み (= ユーザー要望)。 旧単一チャート形式は
  /// 1 チャートへ自動移行する。
  static Future<({List<_GanttChart> charts, int sel})> loadAll(String pageId,
      {required String defaultChartName}) async {
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString(_chartsKey(pageId));
      if (raw != null && raw.isNotEmpty) {
        final data = jsonDecode(raw);
        if (data is Map && data['charts'] is List) {
          final charts = (data['charts'] as List)
              .whereType<Map>()
              .map((m) => _GanttChart.fromJson(m))
              .toList();
          if (charts.isNotEmpty) {
            final sel = ((data['sel'] as num?)?.toInt() ?? 0)
                .clamp(0, charts.length - 1);
            return (charts: charts, sel: sel);
          }
        }
      }
    } catch (_) {}
    // 旧形式 (gantt_<id> + unit + hours) を 1 チャートへ移行。
    final tasks = await load(pageId);
    final unit = await loadUnit(pageId);
    final hrs = await loadHours(pageId);
    return (
      charts: [
        _GanttChart(
            name: defaultChartName,
            unit: unit,
            fromHour: hrs.$1,
            toHour: hrs.$2,
            tasks: tasks)
      ],
      sel: 0
    );
  }

  static Future<void> saveAll(
      String pageId, List<_GanttChart> charts, int sel) async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(
          _chartsKey(pageId),
          jsonEncode({
            'sel': sel,
            'charts': charts.map((c) => c.toJson()).toList(),
          }));
    } catch (_) {}
  }

  /// 表示単位 ('day' / 'hour') (= ユーザー要望: 時間単位のタスク表)。
  static Future<String> loadUnit(String pageId) async {
    try {
      final sp = await SharedPreferences.getInstance();
      return sp.getString(_unitKey(pageId)) == 'hour' ? 'hour' : 'day';
    } catch (_) {
      return 'day';
    }
  }

  static Future<void> saveUnit(String pageId, String unit) async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_unitKey(pageId), unit == 'hour' ? 'hour' : 'day');
    } catch (_) {}
  }

  static String _hoursKey(String pageId) => 'gantt_hours_$pageId';

  /// 時間モードで表示する時間帯 [from, to) (= ユーザー要望)。
  /// 既定は 6〜24 (= ユーザー要望: 0〜6時はデフォルト非表示)。
  static Future<(int, int)> loadHours(String pageId) async {
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString(_hoursKey(pageId));
      if (raw == null || !raw.contains(',')) return (6, 24);
      final parts = raw.split(',');
      final f = int.tryParse(parts[0]) ?? 6;
      final t = int.tryParse(parts[1]) ?? 24;
      if (f < 0 || t > 24 || f >= t) return (6, 24);
      return (f, t);
    } catch (_) {
      return (6, 24);
    }
  }

  static Future<void> saveHours(String pageId, int from, int to) async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_hoursKey(pageId), '$from,$to');
    } catch (_) {}
  }

  // ── 12時間 (AM/PM) 表記の ON/OFF (全ガント共通)。 既定 true (= ユーザー要望)。
  static const String _clock12hKey = 'gantt_clock12h';
  static Future<bool> load12h() async {
    try {
      final sp = await SharedPreferences.getInstance();
      return sp.getBool(_clock12hKey) ?? true;
    } catch (_) {
      return true;
    }
  }

  static Future<void> save12h(bool v) async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setBool(_clock12hKey, v);
    } catch (_) {}
  }

  static Future<List<_GanttTask>> load(String pageId) async {
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString(_key(pageId));
      if (raw == null || raw.isEmpty) return [];
      final List<dynamic> arr = jsonDecode(raw);
      return arr
          .whereType<Map>()
          .map((m) => (
                id: (m['id'] ?? '').toString(),
                name: (m['n'] ?? '').toString(),
                startMs: (m['s'] as num?)?.toInt() ?? 0,
                endMs: (m['e'] as num?)?.toInt() ?? 0,
                color: (m['c'] as num?)?.toInt() ?? 0xFF4FC3F7,
                assignee: (m['a'] ?? '').toString(),
              ))
          .toList();
    } catch (_) {
      return [];
    }
  }

  static Future<void> save(String pageId, List<_GanttTask> tasks) async {
    try {
      final sp = await SharedPreferences.getInstance();
      if (tasks.isEmpty) {
        await sp.remove(_key(pageId));
      } else {
        await sp.setString(
            _key(pageId),
            jsonEncode(tasks
                .map((t) => {
                      'id': t.id,
                      'n': t.name,
                      's': t.startMs,
                      'e': t.endMs,
                      'c': t.color,
                      'a': t.assignee,
                    })
                .toList()));
      }
    } catch (_) {}
  }
}

/// ガントチャート + メンバー予定表 を 1 つにまとめた「予定表」ツール
/// (= ユーザー要望: メンバー予定表とガントチャートは合体させて予定表みたいな
/// 名前のボタンにして)。 上部のタブでどちらを表示するか切り替える。
/// データは従来どおり別々の固定 ID ('global_gantt' / 'global_schedule') に
/// 保存されるので、 既存の内容はそのまま引き継がれる。
class _SchedulePlannerView extends StatefulWidget {
  final MindMapProvider provider;

  /// 初期表示タブ: 0=ガントチャート / 1=メンバー予定表。
  final int initialTab;
  const _SchedulePlannerView({required this.provider, this.initialTab = 0});
  @override
  State<_SchedulePlannerView> createState() => _SchedulePlannerViewState();
}

class _SchedulePlannerViewState extends State<_SchedulePlannerView> {
  late int _tab = widget.initialTab.clamp(0, 1);

  /// タブの並び順 (= ユーザー要望: どちらを左に置くかドラッグ&ドロップで
  /// 入れ替えられるように)。 prefs に残す。
  List<int> _order = [0, 1];
  static const String _kOrderKey = 'plannerTabOrder_v1';

  @override
  void initState() {
    super.initState();
    unawaited(_loadOrder());
  }

  Future<void> _loadOrder() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kOrderKey) ?? '';
      if (raw == '1,0' && mounted) setState(() => _order = [1, 0]);
    } catch (_) {}
  }

  Future<void> _swapOrder() async {
    setState(() => _order = [_order[1], _order[0]]);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_kOrderKey, _order.join(','));
    } catch (_) {}
  }

  /// 予定表の仕組み (同期のされ方) の説明 (= ユーザー要望)。
  Future<void> _showPlannerHelp() async {
    final provider = widget.provider;
    await showDialog<void>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('planner.helpTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: SizedBox(
          width: 440,
          child: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                for (final e in [
                  ('hdr.gantt', 'planner.helpGantt', const Color(0xFF4FC3F7)),
                  (
                    'hdr.memberSchedule',
                    'planner.helpMember',
                    const Color(0xFF66BB6A)
                  ),
                  ('planner.helpTabsTitle', 'planner.helpTabs',
                      const Color(0xFFFFB347)),
                ]) ...[
                  Text(provider.t(e.$1),
                      style: TextStyle(
                          color: e.$3,
                          fontSize: 13,
                          fontWeight: FontWeight.w700)),
                  const SizedBox(height: 4),
                  Text(provider.t(e.$2),
                      style: const TextStyle(
                          color: Colors.white70,
                          fontSize: 12,
                          height: 1.6)),
                  const SizedBox(height: 12),
                ],
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.close'),
                style: const TextStyle(color: Colors.white54)),
          ),
        ],
      ),
    );
  }

  Widget _tabBtn(int index, IconData icon, String label, Color color) {
    final on = _tab == index;
    // ドラッグで左右を入れ替えられるようにする (= ユーザー要望)。
    return Expanded(
      child: DragTarget<int>(
        onWillAcceptWithDetails: (d) => d.data != index,
        onAcceptWithDetails: (_) => unawaited(_swapOrder()),
        builder: (dctx, cand, _) => Draggable<int>(
          data: index,
          feedback: Material(
            color: Colors.transparent,
            child: SizedBox(
                width: 240, child: _tabInner(index, icon, label, color)),
          ),
          childWhenDragging:
              Opacity(opacity: 0.35, child: _tabInner(index, icon, label, color)),
          child: Container(
            decoration: cand.isNotEmpty
                ? BoxDecoration(
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(color: const Color(0xFFFFB347)),
                  )
                : null,
            child: _tabInner(index, icon, label, color),
          ),
        ),
      ),
    );
  }

  Widget _tabInner(int index, IconData icon, String label, Color color) {
    final on = _tab == index;
    return InkWell(
        onTap: () => setState(() => _tab = index),
        borderRadius: BorderRadius.circular(8),
        child: Container(
          padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 6),
          decoration: BoxDecoration(
            color: on ? color.withValues(alpha: 0.18) : Colors.transparent,
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
              color: on ? color : Colors.white24,
              width: on ? 1.4 : 1,
            ),
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(icon, size: 16, color: on ? color : Colors.white54),
              const SizedBox(width: 6),
              Flexible(
                child: Text(
                  label,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    color: on ? Colors.white : Colors.white60,
                    fontSize: 12,
                    fontWeight: on ? FontWeight.w700 : FontWeight.w500,
                  ),
                ),
              ),
            ],
          ),
        ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final provider = widget.provider;
    return Container(
      color: const Color(0xFF12121C),
      child: Column(children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(10, 8, 10, 6),
          child: Row(children: [
            // 並び順は _order に従う (= ドラッグで入れ替え可能)。
            for (int i = 0; i < _order.length; i++) ...[
              if (i > 0) const SizedBox(width: 8),
              if (_order[i] == 0)
                _tabBtn(0, Icons.view_timeline_rounded,
                    provider.t('hdr.gantt'), const Color(0xFF4FC3F7))
              else
                _tabBtn(1, Icons.groups_rounded,
                    provider.t('hdr.memberSchedule'),
                    const Color(0xFF66BB6A)),
            ],
            const SizedBox(width: 4),
            // ── 同期の仕組みの説明 (= ユーザー要望) ──
            IconButton(
              tooltip: provider.t('planner.helpTip'),
              padding: EdgeInsets.zero,
              constraints:
                  const BoxConstraints(minWidth: 32, minHeight: 32),
              icon: const Icon(Icons.help_outline_rounded,
                  color: Colors.white54, size: 18),
              onPressed: () => unawaited(_showPlannerHelp()),
            ),
          ]),
        ),
        const Divider(color: Colors.white12, height: 1),
        // タブ切替のたびに作り直す (= 隠れたガント側が autofocus を奪ったり、
        // 見えない側がキー入力を横取りするのを防ぐ)。 データは都度保存済み
        // なので作り直しても内容は失われない。
        Expanded(
          child: _tab == 0
              ? _GanttPageView(
                  key: const ValueKey('planner_gantt'),
                  provider: provider,
                  pageId: 'global_gantt')
              : _MemberSchedulePageView(
                  key: const ValueKey('planner_schedule'),
                  provider: provider,
                  pageId: 'global_schedule'),
        ),
      ]),
    );
  }
}

class _GanttPageView extends StatefulWidget {
  final MindMapProvider provider;
  final String pageId;
  const _GanttPageView(
      {super.key, required this.provider, required this.pageId});
  @override
  State<_GanttPageView> createState() => _GanttPageViewState();
}

class _GanttPageViewState extends State<_GanttPageView> {
  List<_GanttTask> _tasks = [];
  bool _loaded = false;
  // ── バーをドラッグして期間を自由設定するための状態 (= ユーザー要望) ──
  //   ドラッグ開始時の task / 元の開始終了 ms / 累積ピクセルを保持し、
  //   1 日 (_dayW px) 単位にスナップして開始・終了を動かす。
  String? _dragId;
  int _dragOrigStartMs = 0;
  int _dragOrigEndMs = 0;
  double _dragAccumPx = 0;
  int _dragActiveUnits = 1;
  // ── タスク名のインライン編集 (= ユーザー要望: クリックで名前変更) ──
  String? _editingNameId;
  final TextEditingController _nameEditCtrl = TextEditingController();
  // ── バー選択 + サイドメニュー + キーで分割 (= ユーザー要望) ──
  //   バーをタップで選択し、サイド編集メニューを開ける。選択中に S / Delete で
  //   分割 / 削除する (動画エディターのクリップ操作に近い操作感)。
  String? _selectedTaskId;
  bool _sidePanelOpen = false;
  final FocusNode _ganttFocus = FocusNode();
  // ── 表示単位 (= ユーザー要望: 日単位だけでなく時間単位のタスク表) ──
  //   'day' = 1 列 1 日、 'hour' = 1 列 1 時間。
  String _unit = 'day';
  // ── 時間モードで表示する時間帯 (= ユーザー要望: 表示しない時間帯を設定)。
  //   [_showFromHour, _showToHour) の時間だけ列に出す。 0〜24 で全表示。
  int _showFromHour = 0;
  int _showToHour = 24;
  List<GanttBlockedInterval> _blockedIntervals = [];
  bool _hourVisible(int h) =>
      (_showFromHour == 0 && _showToHour == 24) ||
      (h >= _showFromHour && h < _showToHour);
  bool _isBlockedColumn(DateTime column) =>
      _unit == 'hour' &&
      isGanttHourColumnBlocked(column, _blockedIntervals);

  ({DateTime start, DateTime end})? _normalizeTaskRange(
    DateTime start,
    DateTime end,
  ) {
    final flooredStart = _floorUnit(start);
    final flooredEnd = _floorUnit(end);
    if (_unit != 'hour' || _blockedIntervals.isEmpty) {
      return (
        start: flooredStart,
        end: flooredEnd.isBefore(flooredStart) ? flooredStart : flooredEnd,
      );
    }

    final active = ganttActiveHoursInRange(
      start: flooredStart,
      end: flooredEnd.isBefore(flooredStart) ? flooredStart : flooredEnd,
      blocked: _blockedIntervals,
    );
    if (active.isNotEmpty) {
      return (start: active.first, end: active.last);
    }

    final next = ganttSnapToActiveHour(
      value: flooredStart,
      blocked: _blockedIntervals,
    );
    return next == null ? null : (start: next, end: next);
  }

  DateTime? _defaultTaskEnd(DateTime start, {int activeUnits = 3}) {
    if (_unit != 'hour' || _blockedIntervals.isEmpty) {
      return _unit == 'hour'
          ? start.add(Duration(hours: activeUnits - 1))
          : start.add(Duration(days: activeUnits - 1));
    }
    return ganttShiftActiveHours(
      from: start,
      activeSteps: activeUnits - 1,
      blocked: _blockedIntervals,
    );
  }
  // ── 時刻表記 (= ユーザー要望: 13時 より 1時 + AM/PM 表記、 切替可) ──
  //   true = 午前/午後 (12h)、 false = 24h。 prefs `gantt_clock12h` (全体共通)。
  bool _use12h = true;
  // ── 複数チャート (= ユーザー要望: チャート自体を複数作成できるように) ──
  //   _tasks/_unit/_showFromHour/_showToHour は選択中チャートの作業状態。
  List<_GanttChart> _charts = [];
  int _selChart = 0;
  // ── 予定の通知 (= ユーザー要望: ガントの予定が通知される時刻を設定) ──
  //   有効時、 各タスクの開始日の指定時刻に OS 通知を出す。 prefs に永続化。
  bool _notifyEnabled = false;
  int _notifyHour = 9;
  int _notifyMinute = 0;
  // 日付クリックで「その日の時間表示」 に切り替える時の対象日 (= ユーザー要望)。
  //   null = 通常 (タスク範囲ベース)。
  DateTime? _focusDay;
  // = ユーザー要望: 表示領域をもう少し大きく。 列幅・行高を拡大。
  static const double _dayW = 52;
  static const double _hourW = 54;

  /// 画面幅いっぱいまで列を広げた時の列幅 (= ユーザー要望: ガントチャートが
  /// 明らかに小さい)。 build のたびに計算し、 既定より広い時だけ使う。
  double _fitColW = 0;
  double get _colW {
    final base = _unit == 'hour' ? _hourW : _dayW;
    return _fitColW > base ? _fitColW : base;
  }
  static const double _rowH = 46;
  static const double _nameW = 160;
  static const _palette = [
    Color(0xFF4FC3F7),
    Color(0xFF43B97F),
    Color(0xFFFFB347),
    Color(0xFFBA68C8),
    Color(0xFFFF6B6B),
    Color(0xFF26C6DA),
  ];

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _nameEditCtrl.dispose();
    _ganttFocus.dispose();
    // 閉じる時点の予定で通知を組み直す (= 編集/追加/削除を反映)。
    // 無効時は前回分のキャンセルのみ行われる。 fire-and-forget。
    _rescheduleGanttNotifications();
    super.dispose();
  }

  /// バー選択。タップで選択し、サイドメニュー/キー操作の対象にする。
  void _selectTask(String? id) {
    setState(() => _selectedTaskId = id);
    _ganttFocus.requestFocus();
  }

  /// 選択中タスクを「その位置(中央付近の単位境界)」で 2 つに分割する
  /// (= ユーザー要望: 選択して何かのキーでその位置で分割)。
  void _splitSelectedTask() {
    final id = _selectedTaskId;
    if (id == null) return;
    final i = _tasks.indexWhere((x) => x.id == id);
    if (i < 0) return;
    final t = _tasks[i];
    int firstEnd;
    int secondStart;
    if (_unit == 'hour' && _blockedIntervals.isNotEmpty) {
      // 非稼働時間は分割位置の計算にも含めない。例えば 21:00〜翌
      // 07:00（22:00〜06:00 が非稼働）は 21:00 / 06:00〜07:00
      // のように、実際に作業できる時間だけを二分する。
      final active = ganttActiveHoursInRange(
        start: _d(t.startMs),
        end: _d(t.endMs),
        blocked: _blockedIntervals,
      );
      if (active.length < 2) {
        _appSnack(
          context,
          SnackBar(
              content: Text(widget.provider.t('gantt.splitTooShort')),
              duration: const Duration(seconds: 2)),
        );
        return;
      }
      final firstCount = (active.length + 1) ~/ 2;
      firstEnd = active[firstCount - 1].millisecondsSinceEpoch;
      secondStart = active[firstCount].millisecondsSinceEpoch;
    } else {
      // 期間 (単位数)。 0 = 1 単位ぶんしかないので分割不可。
      final span = _unitIndex(_d(t.startMs), _d(t.endMs));
      if (span < 1) {
        _appSnack(
          context,
          SnackBar(
              content: Text(widget.provider.t('gantt.splitTooShort')),
              duration: const Duration(seconds: 2)),
        );
        return;
      }
      final half = span ~/ 2;
      firstEnd = _shiftUnits(t.startMs, half);
      secondStart = _shiftUnits(t.startMs, half + 1);
    }
    final first = (
      id: t.id,
      name: t.name,
      startMs: t.startMs,
      endMs: firstEnd,
      color: t.color,
      assignee: t.assignee,
    );
    final second = (
      id: 'g${DateTime.now().microsecondsSinceEpoch}',
      name: t.name,
      startMs: secondStart,
      endMs: t.endMs,
      color: t.color,
      assignee: t.assignee,
    );
    setState(() {
      _tasks[i] = first;
      _tasks.insert(i + 1, second);
      _selectedTaskId = second.id;
    });
    _saveCurrent();
  }

  void _deleteSelectedTask() {
    final id = _selectedTaskId;
    if (id == null) return;
    setState(() {
      _tasks.removeWhere((t) => t.id == id);
      _selectedTaskId = null;
    });
    _saveCurrent();
  }

  /// 指定タスクを「指定した列(単位)の頭」で 2 つに分割する
  /// (= ユーザー要望: 右クリックしたその位置で分割できるように)。
  /// [column] は 2 本目の先頭になる列。 バーの先頭列を指定した場合は
  /// 1 本目が空になるので分割不可。
  void _splitTaskAtColumn(_GanttTask t, DateTime column) {
    final i = _tasks.indexWhere((x) => x.id == t.id);
    if (i < 0) return;
    final secondStart = _floorUnit(column).millisecondsSinceEpoch;
    // 1 本目 = [start, secondStart - 1単位]、 2 本目 = [secondStart, end]。
    final firstEnd = _shiftUnits(secondStart, -1);
    if (secondStart <= t.startMs || secondStart > t.endMs) {
      _appSnack(
        context,
        SnackBar(
            content: Text(widget.provider.t('gantt.splitAtEdge')),
            duration: const Duration(seconds: 2)),
      );
      return;
    }
    final first = (
      id: t.id,
      name: t.name,
      startMs: t.startMs,
      endMs: firstEnd,
      color: t.color,
      assignee: t.assignee,
    );
    final second = (
      id: 'g${DateTime.now().microsecondsSinceEpoch}',
      name: t.name,
      startMs: secondStart,
      endMs: t.endMs,
      color: t.color,
      assignee: t.assignee,
    );
    setState(() {
      _tasks[i] = first;
      _tasks.insert(i + 1, second);
      _selectedTaskId = second.id;
    });
    _saveCurrent();
  }

  /// バーの右クリック (デスクトップ) / 長押し (モバイル) メニュー。
  /// 押した位置の列を 2 本目の先頭にして分割できる (= ユーザー要望)。
  Future<void> _showGanttBarMenu(
    _GanttTask t,
    Offset globalPos, {
    DateTime? splitColumn,
  }) async {
    _selectTask(t.id);
    final provider = widget.provider;
    final overlay =
        Overlay.of(context).context.findRenderObject() as RenderBox?;
    if (overlay == null) return;
    final result = await showMenu<String>(
      context: context,
      color: const Color(0xFF23233A),
      position: RelativeRect.fromRect(
        globalPos & const Size(1, 1),
        Offset.zero & overlay.size,
      ),
      items: [
        if (splitColumn != null)
          PopupMenuItem<String>(
            value: 'split',
            height: 40,
            child: Row(children: [
              const Icon(Icons.content_cut_rounded,
                  size: 16, color: Color(0xFFFFB347)),
              const SizedBox(width: 8),
              Text(provider.t('gantt.splitHere'),
                  style: const TextStyle(color: Colors.white, fontSize: 13)),
            ]),
          ),
        PopupMenuItem<String>(
          value: 'edit',
          height: 40,
          child: Row(children: [
            const Icon(Icons.edit_rounded, size: 16, color: Color(0xFF4FC3F7)),
            const SizedBox(width: 8),
            Text(provider.t('gantt.editTask'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        PopupMenuItem<String>(
          value: 'delete',
          height: 40,
          child: Row(children: [
            const Icon(Icons.delete_outline_rounded,
                size: 16, color: Color(0xFFE57373)),
            const SizedBox(width: 8),
            Text(provider.t('gantt.deleteTask'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
      ],
    );
    if (!mounted || result == null) return;
    switch (result) {
      case 'split':
        if (splitColumn != null) _splitTaskAtColumn(t, splitColumn);
        break;
      case 'edit':
        await _editTask(t);
        break;
      case 'delete':
        _selectedTaskId = t.id;
        _deleteSelectedTask();
        break;
    }
    if (mounted) _ganttFocus.requestFocus();
  }

  /// サイドメニュー/キー操作のキーハンドラ。S=分割 / Delete・Backspace=削除。
  KeyEventResult _onGanttKey(FocusNode node, KeyEvent event) {
    if (event is! KeyDownEvent) return KeyEventResult.ignored;
    // テキスト編集中 (タスク名インライン編集等) はキー操作を横取りしない。
    if (_editingNameId != null) return KeyEventResult.ignored;
    // ── テキスト入力欄にフォーカスがある間は横取りしない ──
    // (= Backspace で文字を消すつもりがタスクごと消えるのを防ぐ)。
    // バーをタップすると _selectTask() が _ganttFocus に primaryFocus を
    // 戻すので、 「バー選択中だけキーが効く」 状態になる。
    if (!_ganttFocus.hasPrimaryFocus) return KeyEventResult.ignored;
    final k = event.logicalKey;
    if (k == LogicalKeyboardKey.keyS) {
      _splitSelectedTask();
      return KeyEventResult.handled;
    }
    if (k == LogicalKeyboardKey.delete || k == LogicalKeyboardKey.backspace) {
      _deleteSelectedTask();
      return KeyEventResult.handled;
    }
    return KeyEventResult.ignored;
  }

  Future<void> _load() async {
    final data = await _GanttStore.loadAll(
      widget.pageId,
      defaultChartName:
          widget.provider.t('gantt.defaultChart').replaceFirst('{n}', '1'),
    );
    final c12 = await _GanttStore.load12h();
    final charts = data.charts;
    // = ユーザー要望: 各チャートは最初から 1 行分ある状態にする。
    for (var chartIndex = 0; chartIndex < charts.length; chartIndex++) {
      final c = charts[chartIndex];
      // ── 旧バージョンで日本語のまま保存された自動既定名「チャート{n}」 を、
      //    現在の表示言語の既定名へ移行する (= ユーザー要望: チャート名の多言語
      //    対応)。 数字で終わる自動生成名だけが対象で、 ユーザーが付けた独自名
      //    は書き換えない。 日本語表示時は同じ文字列なので無変更。 ──
      final autoMatch = RegExp(r'^チャート(\d+)$').firstMatch(c.name.trim());
      if (autoMatch != null) {
        c.name = widget.provider
            .t('gantt.defaultChart')
            .replaceFirst('{n}', autoMatch.group(1)!);
      }
      if (c.name.trim().isEmpty) {
        c.name = widget.provider
            .t('gantt.defaultChart')
            .replaceFirst('{n}', '${chartIndex + 1}');
      }
      if (c.tasks.isEmpty) {
        final now = DateTime.now();
        var start = c.unit == 'hour'
            ? DateTime(now.year, now.month, now.day, now.hour)
            : DateTime(now.year, now.month, now.day);
        DateTime end;
        if (c.unit == 'hour' && c.blockedIntervals.isNotEmpty) {
          final activeStart = ganttSnapToActiveHour(
            value: start,
            blocked: c.blockedIntervals,
          );
          // 全日を設定不可にしたチャートへ自動タスクを作らない。
          if (activeStart == null) continue;
          start = activeStart;
          end = ganttShiftActiveHours(
                from: start,
                activeSteps: 2,
                blocked: c.blockedIntervals,
              ) ??
              start;
        } else {
          end = c.unit == 'hour'
              ? start.add(const Duration(hours: 2))
              : start.add(const Duration(days: 2));
        }
        c.tasks.add((
          id: 'g${now.microsecondsSinceEpoch}',
          name: widget.provider.t('gantt.newTask'),
          startMs: start.millisecondsSinceEpoch,
          endMs: end.millisecondsSinceEpoch,
          color: _palette.first.toARGB32(),
          assignee: '',
        ));
      }
    }
    if (!mounted) return;
    setState(() {
      _charts = charts;
      _selChart = data.sel;
      final c = charts[data.sel];
      _tasks = c.tasks;
      _unit = c.unit;
      _showFromHour = c.fromHour;
      _showToHour = c.toHour;
      _blockedIntervals =
          List<GanttBlockedInterval>.from(c.blockedIntervals);
      _use12h = c12;
      _loaded = true;
    });
    // 通知設定を復元してから保存 (= ユーザー要望: 予定の通知時刻)。
    try {
      final prefs = await SharedPreferences.getInstance();
      _notifyEnabled = prefs.getBool('gantt_notify_enabled') ?? false;
      _notifyHour = (prefs.getInt('gantt_notify_hour') ?? 9).clamp(0, 23);
      _notifyMinute = (prefs.getInt('gantt_notify_min') ?? 0).clamp(0, 59);
      if (mounted) setState(() {});
    } catch (_) {}
    _saveCurrent();
    // 起動・再表示のたびに予定通知を組み直す (= 編集差分を反映)。
    _rescheduleGanttNotifications();
  }

  /// ガントの全タスクについて、 開始日の指定時刻に OS 通知を予約し直す
  /// (= ユーザー要望: 予定が通知される時刻を設定)。 無効時は全キャンセル。
  Future<void> _rescheduleGanttNotifications() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      // 前回予約分を全てキャンセル (削除/変更されたタスクの取りこぼし防止)。
      final oldIds = prefs.getStringList('gantt_notif_ids') ?? const [];
      for (final s in oldIds) {
        final id = int.tryParse(s);
        if (id != null) {
          try {
            await flutterLocalNotificationsPlugin.cancel(id);
          } catch (_) {}
        }
      }
      final newIds = <String>[];
      if (_notifyEnabled) {
        final now = DateTime.now();
        for (final c in _charts) {
          for (final t in c.tasks) {
            if (t.name.trim().isEmpty) continue;
            final start = DateTime.fromMillisecondsSinceEpoch(t.startMs);
            final fireAt = DateTime(
                start.year, start.month, start.day, _notifyHour, _notifyMinute);
            if (!fireAt.isAfter(now)) continue; // 過去は予約しない
            final notifId = 850000 + (t.id.hashCode.abs() % 60000);
            try {
              final scheduled = tz.TZDateTime.from(fireAt, tz.local);
              await flutterLocalNotificationsPlugin.zonedSchedule(
                notifId,
                widget.provider.t('gantt.title'),
                '${t.name.trim()} (${start.month}/${start.day})',
                scheduled,
                NotificationDetails(
                  android: AndroidNotificationDetails(
                    kNodeReminderChannelId,
                    kNodeReminderChannelName,
                    channelDescription: kNodeReminderChannelDescription,
                    importance: Importance.high,
                    priority: Priority.high,
                    enableVibration: true,
                    playSound: true,
                  ),
                ),
                androidScheduleMode: AndroidScheduleMode.exactAllowWhileIdle,
                uiLocalNotificationDateInterpretation:
                    UILocalNotificationDateInterpretation.absoluteTime,
              );
              newIds.add('$notifId');
            } catch (e) {
              debugPrint('ガント通知予約失敗: $e');
            }
          }
        }
      }
      await prefs.setStringList('gantt_notif_ids', newIds);
    } catch (e) {
      debugPrint('ガント通知の再スケジュール失敗: $e');
    }
  }

  /// 予定通知の設定ダイアログ (= ON/OFF + 通知時刻)。
  Future<void> _showGanttNotifySettings() async {
    bool enabled = _notifyEnabled;
    TimeOfDay time = TimeOfDay(hour: _notifyHour, minute: _notifyMinute);
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => StatefulBuilder(
        builder: (dctx, setD) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Text(context.read<MindMapProvider>().t('gantt.notifySettings'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
          content: Column(mainAxisSize: MainAxisSize.min, children: [
            SwitchListTile(
              contentPadding: EdgeInsets.zero,
              activeColor: const Color(0xFFFFB347),
              title: Text(
                  context.read<MindMapProvider>().t('gantt.notifyToggle'),
                  style: const TextStyle(color: Colors.white, fontSize: 14)),
              subtitle: Text(
                  context.read<MindMapProvider>().t('gantt.notifyDesc'),
                  style: const TextStyle(color: Colors.white38, fontSize: 11)),
              value: enabled,
              onChanged: (v) => setD(() => enabled = v),
            ),
            ListTile(
              contentPadding: EdgeInsets.zero,
              enabled: enabled,
              leading:
                  const Icon(Icons.schedule_rounded, color: Color(0xFFFFB347)),
              title: Text(context.read<MindMapProvider>().t('gantt.notifyTime'),
                  style: const TextStyle(color: Colors.white, fontSize: 14)),
              trailing: Text(
                  '${time.hour.toString().padLeft(2, '0')}:${time.minute.toString().padLeft(2, '0')}',
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 18,
                      fontWeight: FontWeight.w700)),
              onTap: !enabled
                  ? null
                  : () async {
                      final picked = await showTimePicker(
                          context: dctx, initialTime: time);
                      if (picked != null) setD(() => time = picked);
                    },
            ),
          ]),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx, false),
              child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFFFB347),
                  foregroundColor: Colors.black),
              onPressed: () => Navigator.pop(dctx, true),
              child: Text(context.read<MindMapProvider>().t('btn.save')),
            ),
          ],
        ),
      ),
    );
    if (ok != true) return;
    _notifyEnabled = enabled;
    _notifyHour = time.hour;
    _notifyMinute = time.minute;
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool('gantt_notify_enabled', _notifyEnabled);
      await prefs.setInt('gantt_notify_hour', _notifyHour);
      await prefs.setInt('gantt_notify_min', _notifyMinute);
    } catch (_) {}
    if (mounted) setState(() {});
    await _rescheduleGanttNotifications();
    if (mounted) {
      _appSnack(
          context,
          SnackBar(
            content: Text(_notifyEnabled
                ? widget.provider.t('gantt.notifyEnabledAt').replaceFirst(
                    '{time}',
                    '${_notifyHour.toString().padLeft(2, '0')}:${_notifyMinute.toString().padLeft(2, '0')}')
                : widget.provider.t('gantt.notifyDisabled')),
            backgroundColor: const Color(0xFFFFB347),
            duration: const Duration(seconds: 2),
          ));
    }
  }

  // ── 作業状態を選択中チャートへ書き戻して全チャートを保存する ──
  void _syncToChart() {
    if (_selChart < 0 || _selChart >= _charts.length) return;
    final c = _charts[_selChart];
    c.tasks = _tasks;
    c.unit = _unit;
    c.fromHour = _showFromHour;
    c.toHour = _showToHour;
    c.blockedIntervals =
        List<GanttBlockedInterval>.from(_blockedIntervals);
  }

  Future<void> _saveCurrent() async {
    _syncToChart();
    await _GanttStore.saveAll(widget.pageId, _charts, _selChart);
  }

  void _switchChart(int i) {
    if (i < 0 || i >= _charts.length || i == _selChart) return;
    _syncToChart();
    setState(() {
      _selChart = i;
      final c = _charts[i];
      _tasks = c.tasks;
      _unit = c.unit;
      _showFromHour = c.fromHour;
      _showToHour = c.toHour;
      _blockedIntervals =
          List<GanttBlockedInterval>.from(c.blockedIntervals);
      _editingNameId = null;
      _focusDay = null;
    });
    _saveCurrent();
  }

  void _addChart() {
    _syncToChart();
    final now = DateTime.now();
    final start = DateTime(now.year, now.month, now.day);
    final c = _GanttChart(
      name: widget.provider
          .t('gantt.defaultChart')
          .replaceFirst('{n}', '${_charts.length + 1}'),
      tasks: [
        (
          id: 'g${now.microsecondsSinceEpoch}',
          name: widget.provider.t('gantt.newTask'),
          startMs: start.millisecondsSinceEpoch,
          endMs: start.add(const Duration(days: 2)).millisecondsSinceEpoch,
          color: _palette.first.toARGB32(),
          assignee: '',
        )
      ],
    );
    setState(() {
      _charts.add(c);
      _selChart = _charts.length - 1;
      _tasks = c.tasks;
      _unit = c.unit;
      _showFromHour = c.fromHour;
      _showToHour = c.toHour;
      _blockedIntervals =
          List<GanttBlockedInterval>.from(c.blockedIntervals);
      _editingNameId = null;
      _focusDay = null;
    });
    _saveCurrent();
  }

  Future<void> _renameChart(int i) async {
    if (i < 0 || i >= _charts.length) return;
    final provider = context.read<MindMapProvider>();
    final ctrl = TextEditingController(text: _charts[i].name);
    final name = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('gantt.chartName'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: TextField(
            controller: ctrl,
            autofocus: true,
            style: const TextStyle(color: Colors.white)),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
              onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
              child: Text(provider.t('btn.save'))),
        ],
      ),
    );
    if (name == null || name.isEmpty) return;
    setState(() => _charts[i].name = name);
    _saveCurrent();
  }

  Future<void> _deleteChart(int i) async {
    if (_charts.length <= 1 || i < 0 || i >= _charts.length) return;
    final provider = context.read<MindMapProvider>();
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('gantt.chartDeleteTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Text(
            provider
                .t('gantt.chartDeleteConfirm')
                .replaceFirst('{name}', _charts[i].name),
            style: const TextStyle(color: Colors.white70)),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx, false),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFFF6B6B),
                  foregroundColor: Colors.white,),
              onPressed: () => Navigator.pop(dctx, true),
              child: Text(provider.t('btn.delete'))),
        ],
      ),
    );
    if (ok != true) return;
    setState(() {
      _charts.removeAt(i);
      if (_selChart >= _charts.length) _selChart = _charts.length - 1;
      final c = _charts[_selChart];
      _tasks = c.tasks;
      _unit = c.unit;
      _showFromHour = c.fromHour;
      _showToHour = c.toHour;
      _blockedIntervals =
          List<GanttBlockedInterval>.from(c.blockedIntervals);
    });
    _saveCurrent();
  }

  void _toggle12h() {
    setState(() => _use12h = !_use12h);
    _GanttStore.save12h(_use12h);
  }

  // ── タスク名インライン編集 (= ユーザー要望: ガントチャート上をクリックして
  //    タスク名を変更) ──
  void _beginNameEdit(_GanttTask t) {
    setState(() {
      _editingNameId = t.id;
      _nameEditCtrl.text = t.name;
      _nameEditCtrl.selection =
          TextSelection(baseOffset: 0, extentOffset: t.name.length);
    });
  }

  Future<void> _commitNameEdit(_GanttTask t) async {
    // onSubmitted と onTapOutside の二重発火を防ぐ。
    if (_editingNameId != t.id) return;
    final name = _nameEditCtrl.text.trim();
    final i = _tasks.indexWhere((x) => x.id == t.id);
    setState(() => _editingNameId = null);
    if (i < 0) return;
    if (name.isEmpty || name == t.name) return;
    setState(() {
      _tasks[i] = (
        id: t.id,
        name: name,
        startMs: t.startMs,
        endMs: t.endMs,
        color: t.color,
        assignee: t.assignee,
      );
    });
    await _saveCurrent();
  }

  /// 新しいタスク (= 行) を既定値で追加し、 すぐ名前のインライン編集に入る
  /// (= ユーザー要望: クリックで行・予定の追加)。
  Future<void> _addQuickTask() async {
    final now = DateTime.now();
    var start = _floorUnit(now);
    if (_unit == 'hour' && _blockedIntervals.isNotEmpty) {
      final activeStart = ganttSnapToActiveHour(
        value: start,
        blocked: _blockedIntervals,
      );
      if (activeStart == null) {
        _appSnack(
          context,
          SnackBar(
            content: Text(widget.provider.t('gantt.noAvailableHours')),
            duration: const Duration(seconds: 3),
          ),
        );
        return;
      }
      start = activeStart;
    }
    final end = _defaultTaskEnd(start);
    if (end == null) return;
    final t = (
      id: 'g${now.microsecondsSinceEpoch}',
      name: widget.provider.t('gantt.newTask'),
      startMs: start.millisecondsSinceEpoch,
      endMs: end.millisecondsSinceEpoch,
      color: _palette[_tasks.length % _palette.length].toARGB32(),
      assignee: '',
    );
    setState(() {
      _tasks.add(t);
      _editingNameId = t.id;
      _nameEditCtrl.text = t.name;
      _nameEditCtrl.selection =
          TextSelection(baseOffset: 0, extentOffset: t.name.length);
    });
    await _saveCurrent();
  }

  DateTime _d(int ms) => DateTime.fromMillisecondsSinceEpoch(ms);

  // ── 単位 (日/時間) を意識した座標・時刻ヘルパー (= ユーザー要望) ──
  /// 日モードはその日の 0:00、 時間モードはその時の 0 分に切り下げる。
  DateTime _floorUnit(DateTime d) => _unit == 'hour'
      ? DateTime(d.year, d.month, d.day, d.hour)
      : DateTime(d.year, d.month, d.day);

  /// [from]→[d] の単位数 (日数 or 時間数)。
  int _unitIndex(DateTime from, DateTime d) {
    final a = _floorUnit(from), b = _floorUnit(d);
    return _unit == 'hour' ? b.difference(a).inHours : b.difference(a).inDays;
  }

  /// [ms] を [n] 単位 (日 or 時間) ずらした切り下げ時刻の ms を返す。
  int _shiftUnits(int ms, int n) {
    final d = _floorUnit(_d(ms));
    final nd =
        _unit == 'hour' ? d.add(Duration(hours: n)) : d.add(Duration(days: n));
    return nd.millisecondsSinceEpoch;
  }

  /// 軸ラベル。 日モード=「M/D」、 時間モード=「H」。 日の変わり目の列は
  /// build 側で「M/D」 を出すのでここでは時刻だけ返す。
  String _axisLabel(DateTime d) {
    if (_unit == 'hour') return '${d.hour}';
    return '${d.month}/${d.day}';
  }

  /// 軸ラベル widget。 時間モード + 12h 設定なら AM/PM を上に小さく出す
  /// (= ユーザー要望: 13時 より 1時 + PM 表記)。
  Widget _axisLabelWidget(DateTime d, bool isBold, bool showAmPm) {
    if (!isBold && _unit == 'hour' && _use12h) {
      final h = d.hour;
      final pm = h >= 12;
      final h12 = (h % 12 == 0) ? 12 : h % 12;
      // AM/PM はブロック中央の列だけに表示 (= ユーザー要望)。 他の列は時刻のみ。
      if (!showAmPm) {
        return Text('$h12',
            style: const TextStyle(color: Colors.white60, fontSize: 11));
      }
      return Column(mainAxisAlignment: MainAxisAlignment.center, children: [
        Text(pm ? 'PM' : 'AM',
            style: TextStyle(
                color: pm ? const Color(0xFFFFB347) : const Color(0xFF4FC3F7),
                fontSize: 7,
                height: 1.0,
                fontWeight: FontWeight.w700)),
        Text('$h12',
            style: const TextStyle(
                color: Colors.white60, fontSize: 11, height: 1.1)),
      ]);
    }
    final txt = isBold ? '${d.month}/${d.day}' : _axisLabel(d);
    return Text(txt,
        style: const TextStyle(color: Colors.white38, fontSize: 9));
  }

  /// [cols] の中で [dt] に対応する列インデックス。 完全一致が無ければ直前の
  /// 列に寄せる (= 隠れた時間帯のタスクは手前の可視列に寄せる)。
  int _colIndex(List<DateTime> cols, DateTime dt) {
    final f = _floorUnit(dt);
    int best = 0;
    for (int i = 0; i < cols.length; i++) {
      if (cols[i] == f) return i;
      if (!cols[i].isAfter(f)) best = i;
    }
    return best;
  }

  /// 時間モードの表示範囲と、タスクを設定しない時間帯を編集する。
  /// 設定不可時間帯は列自体を消さず、重なったタスク部分だけ描画から除外する。
  Future<void> _showHoursDialog() async {
    int from = _showFromHour, to = _showToHour;
    var blocked = List<GanttBlockedInterval>.from(_blockedIntervals);

    String formatMinute(int minute) {
      if (minute == 24 * 60) return '24:00';
      final hour = (minute ~/ 60) % 24;
      final min = minute % 60;
      return '${hour.toString().padLeft(2, '0')}:'
          '${min.toString().padLeft(2, '0')}';
    }

    String intervalLabel(GanttBlockedInterval interval) {
      final overnight = interval.endMinute < interval.startMinute;
      final suffix = overnight
          ? widget.provider.t('gantt.nextDaySuffix')
          : '';
      return '${formatMinute(interval.startMinute)} 〜 '
          '${formatMinute(interval.endMinute)}$suffix';
    }

    Future<GanttBlockedInterval?> pickBlockedInterval(
        BuildContext parentContext) async {
      int startHour = 12;
      int endHour = 13;
      return showDialog<GanttBlockedInterval>(
        context: parentContext,
        builder: (pickCtx) => StatefulBuilder(
          builder: (pickCtx, setPick) {
            Widget dropdown(int value, ValueChanged<int?> onChanged) {
              return DropdownButton<int>(
                value: value,
                dropdownColor: const Color(0xFF2A2A3E),
                style: const TextStyle(color: Colors.white),
                items: [
                  for (int hour = 0; hour < 24; hour++)
                    DropdownMenuItem(
                      value: hour,
                      child: Text(
                          '${hour.toString().padLeft(2, '0')}:00'),
                    ),
                ],
                onChanged: onChanged,
              );
            }

            return AlertDialog(
              backgroundColor: const Color(0xFF1E1E32),
              title: Text(
                widget.provider.t('gantt.blockedRange'),
                style: const TextStyle(color: Colors.white, fontSize: 15),
              ),
              content: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      dropdown(startHour, (value) {
                        if (value != null) {
                          setPick(() => startHour = value);
                        }
                      }),
                      const Padding(
                        padding: EdgeInsets.symmetric(horizontal: 10),
                        child: Text('〜',
                            style: TextStyle(color: Colors.white70)),
                      ),
                      dropdown(endHour, (value) {
                        if (value != null) {
                          setPick(() => endHour = value);
                        }
                      }),
                    ],
                  ),
                  const SizedBox(height: 8),
                  Text(
                    startHour == endHour
                        ? widget.provider.t('gantt.blockedDifferentHours')
                        : endHour < startHour
                            ? widget.provider.t('gantt.blockedOvernightHint')
                            : widget.provider.t('gantt.blockedOverlapHint'),
                    style: TextStyle(
                      color: startHour == endHour
                          ? const Color(0xFFFF8A80)
                          : Colors.white54,
                      fontSize: 11,
                    ),
                  ),
                ],
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(pickCtx),
                  child: Text(
                    context.read<MindMapProvider>().t('btn.cancel'),
                    style: const TextStyle(color: Colors.white54),
                  ),
                ),
                ElevatedButton(
                  style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF4FC3F7),
                    foregroundColor: Colors.black,
                  ),
                  onPressed: startHour == endHour
                      ? null
                      : () => Navigator.pop(
                            pickCtx,
                            GanttBlockedInterval(
                              startMinute: startHour * 60,
                              endMinute: endHour * 60,
                            ),
                          ),
                  child: Text(context.read<MindMapProvider>().t('btn.add')),
                ),
              ],
            );
          },
        ),
      );
    }

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        Widget hourDropdown(int value, bool isFrom) {
          return DropdownButton<int>(
            value: value,
            dropdownColor: const Color(0xFF2A2A3E),
            style: const TextStyle(color: Colors.white),
            items: [
              for (int h = 0; h <= 24; h++)
                if (isFrom ? h <= 23 : h >= 1)
                  DropdownMenuItem(value: h, child: Text('$h:00')),
            ],
            onChanged: (v) {
              if (v == null) return;
              setD(() {
                if (isFrom) {
                  from = v;
                  if (to <= from) to = (from + 1).clamp(1, 24);
                } else {
                  to = v;
                  if (from >= to) from = (to - 1).clamp(0, 23);
                }
              });
            },
          );
        }

        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Text(
            widget.provider.t('gantt.timeAndBlockedTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 15),
          ),
          content: SizedBox(
            width: 420,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    widget.provider.t('gantt.visibleTimeRange'),
                    style: const TextStyle(color: Colors.white70, fontSize: 12),
                  ),
                  Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      hourDropdown(from, true),
                      const Padding(
                        padding: EdgeInsets.symmetric(horizontal: 10),
                        child: Text('〜',
                            style: TextStyle(color: Colors.white70)),
                      ),
                      hourDropdown(to, false),
                    ],
                  ),
                  const Divider(color: Colors.white12, height: 24),
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          widget.provider.t('gantt.blockedRange'),
                          style: const TextStyle(
                              color: Colors.white70, fontSize: 12),
                        ),
                      ),
                      if (blocked.isNotEmpty)
                        TextButton(
                          onPressed: () => setD(() => blocked = []),
                          child: Text(
                            widget.provider.t('gantt.blockedClearAll'),
                            style: const TextStyle(
                                color: Colors.white54, fontSize: 11),
                          ),
                        ),
                      IconButton(
                        tooltip: widget.provider
                            .t('gantt.blockedAddTooltip'),
                        visualDensity: VisualDensity.compact,
                        icon: const Icon(
                          Icons.add_circle_outline_rounded,
                          color: Color(0xFF4FC3F7),
                        ),
                        onPressed: () async {
                          final interval = await pickBlockedInterval(dctx);
                          if (interval == null) return;
                          setD(() {
                            blocked = normalizeGanttBlockedIntervals(
                              [...blocked, interval],
                            );
                          });
                        },
                      ),
                    ],
                  ),
                  if (blocked.isEmpty)
                    Padding(
                      padding: const EdgeInsets.symmetric(vertical: 8),
                      child: Text(
                        widget.provider.t('gantt.blockedEmpty'),
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 11),
                      ),
                    )
                  else
                    for (int i = 0; i < blocked.length; i++)
                      Container(
                        margin: const EdgeInsets.only(top: 6),
                        padding: const EdgeInsets.only(left: 12),
                        decoration: BoxDecoration(
                          color: const Color(0xFFFF6B6B)
                              .withValues(alpha: 0.12),
                          borderRadius: BorderRadius.circular(8),
                          border: Border.all(color: const Color(0x44FF6B6B)),
                        ),
                        child: Row(
                          children: [
                            const Icon(
                              Icons.block_rounded,
                              color: Color(0xFFFF8A80),
                              size: 16,
                            ),
                            const SizedBox(width: 8),
                            Expanded(
                              child: Text(
                                intervalLabel(blocked[i]),
                                style: const TextStyle(
                                    color: Colors.white70, fontSize: 12),
                              ),
                            ),
                            IconButton(
                              tooltip: widget.provider
                                  .t('gantt.blockedRemoveTooltip'),
                              visualDensity: VisualDensity.compact,
                              icon: const Icon(Icons.close_rounded,
                                  color: Colors.white54, size: 17),
                              onPressed: () =>
                                  setD(() => blocked.removeAt(i)),
                            ),
                          ],
                        ),
                      ),
                  const SizedBox(height: 4),
                  Text(
                    widget.provider.t('gantt.blockedDescription'),
                    style: const TextStyle(
                        color: Colors.white38, fontSize: 10),
                  ),
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () {
                setD(() {
                  from = 0;
                  to = 24;
                });
              },
              child: Text(context.read<MindMapProvider>().t('gantt.showAll'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            TextButton(
              onPressed: () => Navigator.pop(dctx, false),
              child: Text(
                context.read<MindMapProvider>().t('btn.cancel'),
                style: const TextStyle(color: Colors.white54),
              ),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF4FC3F7),
                  foregroundColor: Colors.black),
              onPressed: () => Navigator.pop(dctx, true),
              child: Text(context.read<MindMapProvider>().t('btn.ok')),
            ),
          ],
        );
      }),
    );
    if (confirmed != true) return;
    setState(() {
      _showFromHour = from;
      _showToHour = to;
      _blockedIntervals = blocked;
    });
    await _saveCurrent();
  }

  void _beginGanttDrag(_GanttTask t) {
    _dragId = t.id;
    _dragOrigStartMs = t.startMs;
    _dragOrigEndMs = t.endMs;
    _dragAccumPx = 0;
    if (_unit == 'hour' && _blockedIntervals.isNotEmpty) {
      _dragActiveUnits = ganttActiveHoursInRange(
        start: _d(t.startMs),
        end: _d(t.endMs),
        blocked: _blockedIntervals,
      ).length;
      if (_dragActiveUnits < 1) _dragActiveUnits = 1;
    } else {
      _dragActiveUnits = _unitIndex(_d(t.startMs), _d(t.endMs)) + 1;
    }
  }

  void _applyGanttTask(int startMs, int endMs) {
    final i = _tasks.indexWhere((x) => x.id == _dragId);
    if (i < 0) return;
    final t = _tasks[i];
    setState(() {
      _tasks[i] = (
        id: t.id,
        name: t.name,
        startMs: startMs,
        endMs: endMs,
        color: t.color,
        assignee: t.assignee,
      );
    });
  }

  /// バー本体をドラッグ → 開始・終了をまとめて移動 (1 単位 = _colW px)。
  void _ganttDragMove(double dx) {
    if (_dragId == null) return;
    _dragAccumPx += dx;
    final n = (_dragAccumPx / _colW).round();
    var startMs = _shiftUnits(_dragOrigStartMs, n);
    var endMs = _shiftUnits(_dragOrigEndMs, n);
    if (_unit == 'hour' && _blockedIntervals.isNotEmpty) {
      final activeStart = ganttSnapToActiveHour(
        value: _d(startMs),
        blocked: _blockedIntervals,
        forward: n >= 0,
      );
      if (activeStart == null) return;
      final activeEnd = ganttShiftActiveHours(
        from: activeStart,
        activeSteps: _dragActiveUnits - 1,
        blocked: _blockedIntervals,
      );
      if (activeEnd == null) return;
      startMs = activeStart.millisecondsSinceEpoch;
      endMs = activeEnd.millisecondsSinceEpoch;
    }
    _applyGanttTask(startMs, endMs);
  }

  /// 左端ハンドルをドラッグ → 開始のみ変更 (終了は固定、 終了は越えない)。
  void _ganttResizeStart(double dx) {
    if (_dragId == null) return;
    _dragAccumPx += dx;
    final n = (_dragAccumPx / _colW).round();
    var ns = _shiftUnits(_dragOrigStartMs, n);
    if (_unit == 'hour' && _blockedIntervals.isNotEmpty) {
      var activeStart = ganttSnapToActiveHour(
        value: _d(ns),
        blocked: _blockedIntervals,
        forward: n >= 0,
      );
      if (activeStart == null) return;
      if (activeStart.millisecondsSinceEpoch > _dragOrigEndMs) {
        activeStart = ganttSnapToActiveHour(
          value: _d(_dragOrigEndMs),
          blocked: _blockedIntervals,
          forward: false,
        );
        if (activeStart == null) return;
      }
      ns = activeStart.millisecondsSinceEpoch;
    }
    if (ns > _dragOrigEndMs) ns = _dragOrigEndMs;
    _applyGanttTask(ns, _dragOrigEndMs);
  }

  /// 右端ハンドルをドラッグ → 終了のみ変更 (開始は固定、 開始を下回らない)。
  void _ganttResizeEnd(double dx) {
    if (_dragId == null) return;
    _dragAccumPx += dx;
    final n = (_dragAccumPx / _colW).round();
    var ne = _shiftUnits(_dragOrigEndMs, n);
    if (_unit == 'hour' && _blockedIntervals.isNotEmpty) {
      var activeEnd = ganttSnapToActiveHour(
        value: _d(ne),
        blocked: _blockedIntervals,
        forward: n >= 0,
      );
      if (activeEnd == null) return;
      if (activeEnd.millisecondsSinceEpoch < _dragOrigStartMs) {
        activeEnd = ganttSnapToActiveHour(
          value: _d(_dragOrigStartMs),
          blocked: _blockedIntervals,
        );
        if (activeEnd == null) return;
      }
      ne = activeEnd.millisecondsSinceEpoch;
    }
    if (ne < _dragOrigStartMs) ne = _dragOrigStartMs;
    _applyGanttTask(_dragOrigStartMs, ne);
  }

  /// 表示単位を切り替える (= ユーザー要望)。
  Future<void> _setUnit(String u) async {
    if (u == _unit) return;
    // 手動切替時は日付フォーカスを解除し通常表示に戻す。
    setState(() {
      _unit = u;
      _focusDay = null;
    });
    await _saveCurrent();
  }

  /// 日付セルのクリックで時間/日表示をトグルする (= ユーザー要望)。
  ///   日表示 → その日の時間単位表示。 時間表示中に日付タップ → 日表示へ戻す。
  void _focusDayHourView(DateTime d) {
    setState(() {
      if (_unit == 'hour') {
        _unit = 'day';
        _focusDay = null;
      } else {
        _focusDay = DateTime(d.year, d.month, d.day);
        _unit = 'hour';
      }
    });
    _saveCurrent();
  }

  // ── チャート切替タブ (= ユーザー要望: チャート自体を複数作成) ──
  Widget _buildChartTabs() {
    return SizedBox(
      height: 36,
      child: Row(children: [
        Expanded(
          child: ListView.builder(
            scrollDirection: Axis.horizontal,
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
            itemCount: _charts.length,
            itemBuilder: (_, i) {
              final sel = i == _selChart;
              return Padding(
                padding: const EdgeInsets.only(right: 6),
                child: GestureDetector(
                  onTap: () => _switchChart(i),
                  onLongPress: () => _renameChart(i),
                  onSecondaryTap: () => _renameChart(i),
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 12),
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color: sel
                          ? const Color(0xFF4FC3F7).withValues(alpha: 0.25)
                          : const Color(0xFF1E1E32),
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(
                          color:
                              sel ? const Color(0xFF4FC3F7) : Colors.white12),
                    ),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      Text(_charts[i].name,
                          style: TextStyle(
                              color: sel ? Colors.white : Colors.white60,
                              fontSize: 12,
                              fontWeight:
                                  sel ? FontWeight.w700 : FontWeight.w400)),
                      if (sel && _charts.length > 1) ...[
                        const SizedBox(width: 6),
                        GestureDetector(
                          onTap: () => _deleteChart(i),
                          child: const Icon(Icons.close,
                              size: 13, color: Colors.white54),
                        ),
                      ],
                    ]),
                  ),
                ),
              );
            },
          ),
        ),
        IconButton(
          tooltip: context.read<MindMapProvider>().t('gantt.addChart'),
          visualDensity: VisualDensity.compact,
          icon: const Icon(Icons.add_box_rounded,
              color: Color(0xFF4FC3F7), size: 22),
          onPressed: _addChart,
        ),
      ]),
    );
  }

  Future<void> _endGanttDrag() async {
    if (_dragId == null) return;
    _dragId = null;
    await _saveCurrent();
  }

  int _activeTaskUnits(_GanttTask task) {
    if (_unit != 'hour' || _blockedIntervals.isEmpty) {
      return _unitIndex(_d(task.startMs), _d(task.endMs)) + 1;
    }
    final start = _floorUnit(_d(task.startMs));
    final end = _floorUnit(_d(task.endMs));
    final allTaskColumns = <DateTime>[];
    var cursor = start;
    int guard = 0;
    while (!cursor.isAfter(end) && guard++ < 50000) {
      allTaskColumns.add(cursor);
      cursor = cursor.add(const Duration(hours: 1));
    }
    return ganttActiveColumnCount(
      columns: allTaskColumns,
      start: _d(task.startMs),
      end: _d(task.endMs),
      blocked: _blockedIntervals,
    );
  }

  List<Widget> _ganttBarSegments(
      _GanttTask task, List<DateTime> columns) {
    if (_unit != 'hour') {
      final startIndex = _colIndex(columns, _d(task.startMs));
      final endIndex = _colIndex(columns, _d(task.endMs));
      return [
        Positioned(
          left: startIndex * _colW,
          top: 8,
          width: math.max(_colW, (endIndex - startIndex + 1) * _colW),
          height: _rowH - 16,
          child: _ganttBar(task,
              columns: columns, segStartIndex: startIndex),
        ),
      ];
    }

    final segments = ganttTaskSegments(
      columns: columns,
      start: _d(task.startMs),
      end: _d(task.endMs),
      blocked: _blockedIntervals,
    );
    if (segments.isEmpty) {
      if (_activeTaskUnits(task) > 0) return const [];
      return [
        Positioned(
          left: 6,
          top: 12,
          child: Tooltip(
            message:
                widget.provider.t('gantt.taskOnlyBlocked'),
            child: GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: () => _selectTask(task.id),
              onDoubleTap: () => _editTask(task),
              child: const Icon(
                Icons.warning_amber_rounded,
                color: Color(0xFFFF8A80),
                size: 20,
              ),
            ),
          ),
        ),
      ];
    }

    int labelSegment = 0;
    for (int i = 1; i < segments.length; i++) {
      if (segments[i].columnCount > segments[labelSegment].columnCount) {
        labelSegment = i;
      }
    }
    final activeUnits = _activeTaskUnits(task);
    return [
      for (int i = 0; i < segments.length; i++)
        Positioned(
          left: segments[i].startIndex * _colW,
          top: 8,
          width: segments[i].columnCount * _colW,
          height: _rowH - 16,
          child: _ganttBar(
            task,
            units: activeUnits,
            showLabel: i == labelSegment,
            showStartHandle: i == 0,
            showEndHandle: i == segments.length - 1,
            columns: columns,
            segStartIndex: segments[i].startIndex,
          ),
        ),
    ];
  }

  /// バー (本体 + 左右リサイズハンドル) を構築する。
  Widget _ganttBar(
    _GanttTask t, {
    int? units,
    bool showLabel = true,
    bool showStartHandle = true,
    bool showEndHandle = true,
    // ── 右クリック分割用: このバー(セグメント)が始まる列の絶対 index と
    //    列リスト (= ユーザー要望: 押した位置で分割) ──
    List<DateTime>? columns,
    int segStartIndex = 0,
  }) {
    const handleW = 14.0;
    // バー内ローカル X → その位置の列 (2 本目の先頭になる列)。
    DateTime? columnAt(double localDx) {
      if (columns == null || columns.isEmpty) return null;
      final ci = segStartIndex + (localDx / _colW).floor();
      if (ci < 0 || ci >= columns.length) return null;
      return columns[ci];
    }
    final visibleUnits =
        units ?? _unitIndex(_d(t.startMs), _d(t.endMs)) + 1;
    final selected = _selectedTaskId == t.id;
    final label = widget.provider
        .t(_unit == 'hour' ? 'gantt.durationHours' : 'gantt.durationDays')
        .replaceFirst('{n}', '$visibleUnits');
    final assignee = t.assignee.trim();
    return Stack(children: [
      // 本体: タップで選択 / ダブルタップで編集、 水平ドラッグで移動。
      Positioned.fill(
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () => _selectTask(t.id),
          onDoubleTap: () => _editTask(t),
          // ── 右クリック: 押した位置で分割 / 編集 / 削除メニュー ──
          onSecondaryTapDown: (d) => _showGanttBarMenu(
            t,
            d.globalPosition,
            splitColumn: columnAt(d.localPosition.dx),
          ),
          // モバイルには右クリックが無いので長押しで同じメニューを出す。
          onLongPressStart: (d) => _showGanttBarMenu(
            t,
            d.globalPosition,
            splitColumn: columnAt(d.localPosition.dx),
          ),
          onHorizontalDragStart: (_) {
            _selectTask(t.id);
            _beginGanttDrag(t);
          },
          onHorizontalDragUpdate: (d) => _ganttDragMove(d.delta.dx),
          onHorizontalDragEnd: (_) => _endGanttDrag(),
          child: Container(
            decoration: BoxDecoration(
              color: Color(t.color),
              borderRadius: BorderRadius.circular(6),
              border:
                  selected ? Border.all(color: Colors.white, width: 2) : null,
              boxShadow: selected
                  ? [
                      BoxShadow(
                          color: Colors.white.withValues(alpha: 0.5),
                          blurRadius: 6)
                    ]
                  : null,
            ),
            alignment: Alignment.center,
            padding: const EdgeInsets.symmetric(horizontal: handleW),
            child: showLabel
                ? Text(assignee.isEmpty ? label : '$label · $assignee',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: Colors.black87,
                        fontSize: 11,
                        fontWeight: FontWeight.w700))
                : null,
          ),
        ),
      ),
      // 左端ハンドル (開始日リサイズ)
      if (showStartHandle)
        Positioned(
          left: 0,
          top: 0,
          bottom: 0,
          width: handleW,
          child: _ganttHandle(t, true),
        ),
      // 右端ハンドル (終了日リサイズ)
      if (showEndHandle)
        Positioned(
          right: 0,
          top: 0,
          bottom: 0,
          width: handleW,
          child: _ganttHandle(t, false),
        ),
    ]);
  }

  Widget _ganttHandle(_GanttTask t, bool isStart) {
    return MouseRegion(
      cursor: SystemMouseCursors.resizeLeftRight,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onHorizontalDragStart: (_) => _beginGanttDrag(t),
        onHorizontalDragUpdate: (d) => isStart
            ? _ganttResizeStart(d.delta.dx)
            : _ganttResizeEnd(d.delta.dx),
        onHorizontalDragEnd: (_) => _endGanttDrag(),
        child: Align(
          alignment: isStart ? Alignment.centerLeft : Alignment.centerRight,
          child: Container(
            width: 4,
            height: double.infinity,
            margin: const EdgeInsets.symmetric(vertical: 4, horizontal: 3),
            decoration: BoxDecoration(
              color: Colors.white.withValues(alpha: 0.85),
              borderRadius: BorderRadius.circular(2),
            ),
          ),
        ),
      ),
    );
  }

  Future<void> _editTask(_GanttTask? task) async {
    final nameCtrl = TextEditingController(text: task?.name ?? '');
    final assigneeCtrl = TextEditingController(text: task?.assignee ?? '');
    final now = DateTime.now();
    DateTime start = task != null ? _d(task.startMs) : _floorUnit(now);
    if (task == null &&
        _unit == 'hour' &&
        _blockedIntervals.isNotEmpty) {
      final activeStart = ganttSnapToActiveHour(
        value: start,
        blocked: _blockedIntervals,
      );
      if (activeStart == null) {
        _appSnack(
          context,
          SnackBar(
            content: Text(widget.provider.t('gantt.noAvailableHours')),
            duration: const Duration(seconds: 3),
          ),
        );
        return;
      }
      start = activeStart;
    }
    DateTime end = task != null
        ? _d(task.endMs)
        : (_defaultTaskEnd(start) ?? start);
    final result = await showDialog<String>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        // 時間モードでは日付に加えて時刻も選ぶ (= ユーザー要望)。
        Future<void> pick(bool isStart) async {
          final base = isStart ? start : end;
          final pickedDate = await showDatePicker(
            context: dctx,
            initialDate: base,
            firstDate: DateTime(2000),
            lastDate: DateTime(2100),
          );
          if (pickedDate == null) return;
          int hour = base.hour;
          if (_unit == 'hour' && dctx.mounted) {
            final pickedTime = await showTimePicker(
              context: dctx,
              initialTime: TimeOfDay(hour: base.hour, minute: 0),
            );
            if (pickedTime != null) hour = pickedTime.hour;
          }
          final r = _unit == 'hour'
              ? DateTime(
                  pickedDate.year, pickedDate.month, pickedDate.day, hour)
              : DateTime(pickedDate.year, pickedDate.month, pickedDate.day);
          setD(() {
            if (isStart) {
              start = r;
              if (end.isBefore(start)) end = start;
            } else {
              end = r.isBefore(start) ? start : r;
            }
          });
        }

        String fmt(DateTime d) => _unit == 'hour'
            ? '${d.month}/${d.day} ${d.hour}:00'
            : '${d.year}/${d.month}/${d.day}';
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Text(
              widget.provider
                  .t(task == null ? 'gantt.addTask' : 'gantt.editTask'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
          content: SizedBox(
            width: 360,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              TextField(
                controller: nameCtrl,
                autofocus: true,
                style: const TextStyle(color: Colors.white),
                decoration: InputDecoration(
                  hintText: widget.provider.t('gantt.taskName'),
                  hintStyle: const TextStyle(color: Colors.white38),
                ),
              ),
              const SizedBox(height: 10),
              // ── 担当者 (= ユーザー要望: ガントにユーザー名を記載) ──
              TextField(
                controller: assigneeCtrl,
                style: const TextStyle(color: Colors.white),
                decoration: InputDecoration(
                  isDense: true,
                  prefixIcon: const Icon(Icons.person_outline_rounded,
                      size: 18, color: Color(0xFF43B97F)),
                  hintText: widget.provider.t('gantt.assigneeHint'),
                  hintStyle: const TextStyle(color: Colors.white38),
                ),
              ),
              const SizedBox(height: 16),
              Row(children: [
                Expanded(
                    child: OutlinedButton.icon(
                  onPressed: () => pick(true),
                  icon: const Icon(Icons.event,
                      size: 16, color: Color(0xFF4FC3F7)),
                  label: Text(
                      widget.provider
                          .t('gantt.startAt')
                          .replaceFirst('{t}', fmt(start)),
                      style: const TextStyle(color: Colors.white)),
                )),
                const SizedBox(width: 8),
                Expanded(
                    child: OutlinedButton.icon(
                  onPressed: () => pick(false),
                  icon: const Icon(Icons.event_available,
                      size: 16, color: Color(0xFF43B97F)),
                  label: Text(
                      widget.provider
                          .t('gantt.endAt')
                          .replaceFirst('{t}', fmt(end)),
                      style: const TextStyle(color: Colors.white)),
                )),
              ]),
              const SizedBox(height: 12),
              // ── タイムライン (カレンダー) と紐づけ (= ユーザー要望) ──
              //    タスクをカレンダー予定として登録し、 タイムラインに表示する。
              //    保存も同時に行う。 時間モードのタスクと相性が良い。
              SizedBox(
                width: double.infinity,
                child: OutlinedButton.icon(
                  style: OutlinedButton.styleFrom(
                      side: const BorderSide(color: Color(0x55FFB347))),
                  onPressed: () async {
                    final nm = nameCtrl.text.trim();
                    if (nm.isEmpty) return;
                    String two(int n) => n.toString().padLeft(2, '0');
                    final normalized = _normalizeTaskRange(start, end);
                    if (normalized == null) {
                      _appSnack(
                        context,
                        SnackBar(content: Text(
                            widget.provider.t('gantt.noAvailableHours'))),
                      );
                      return;
                    }
                    final s = normalized.start;
                    final e = normalized.end;
                    final dateKey = '${s.year}-${two(s.month)}-${two(s.day)}';
                    await widget.provider.addCalendarEvent(
                      dateKey,
                      nm,
                      startTime: '${two(s.hour)}:${two(s.minute)}',
                      endTime: '${two(e.hour)}:${two(e.minute)}',
                      colorArgb: task?.color ??
                          _palette[_tasks.length % _palette.length].toARGB32(),
                    );
                    if (dctx.mounted) Navigator.pop(dctx, 'save');
                  },
                  icon: const Icon(Icons.view_day_rounded,
                      size: 16, color: Color(0xFFFFB347)),
                  label: Text(widget.provider.t('gantt.addToTimeline'),
                      style: const TextStyle(color: Color(0xFFFFB347))),
                ),
              ),
            ]),
          ),
          actions: [
            if (task != null)
              TextButton(
                onPressed: () => Navigator.pop(dctx, 'delete'),
                child: Text(widget.provider.t('btn.delete'),
                    style: const TextStyle(color: Color(0xFFE57373))),
              ),
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(widget.provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF4FC3F7),
                  foregroundColor: Colors.black),
              onPressed: () {
                if (nameCtrl.text.trim().isEmpty) return;
                Navigator.pop(dctx, 'save');
              },
              child: Text(widget.provider.t('btn.save')),
            ),
          ],
        );
      }),
    );
    if (result == null) return;
    final normalized = result == 'save'
        ? _normalizeTaskRange(start, end)
        : null;
    if (result == 'save' && normalized == null) {
      if (mounted) {
        _appSnack(
          context,
          SnackBar(
            content: Text(widget.provider.t('gantt.noAvailableHours')),
            duration: const Duration(seconds: 3),
          ),
        );
      }
      return;
    }
    setState(() {
      if (result == 'delete' && task != null) {
        _tasks.removeWhere((t) => t.id == task.id);
      } else if (result == 'save') {
        final newTask = (
          id: task?.id ?? 'g${DateTime.now().microsecondsSinceEpoch}',
          name: nameCtrl.text.trim(),
          startMs: normalized!.start.millisecondsSinceEpoch,
          endMs: normalized.end.millisecondsSinceEpoch,
          color: task?.color ??
              _palette[_tasks.length % _palette.length].toARGB32(),
          assignee: assigneeCtrl.text.trim(),
        );
        if (task == null) {
          _tasks.add(newTask);
        } else {
          final i = _tasks.indexWhere((t) => t.id == task.id);
          if (i >= 0) _tasks[i] = newTask;
        }
      }
    });
    await _saveCurrent();
  }

  @override
  Widget build(BuildContext context) {
    if (!_loaded) {
      return const Center(
          child: CircularProgressIndicator(color: Color(0xFF4FC3F7)));
    }
    DateTime? minD, maxD;
    if (_unit == 'hour' && _focusDay != null) {
      // = ユーザー要望: 日付クリックでその日の時間単位表示。 その日 1 日分。
      minD = DateTime(_focusDay!.year, _focusDay!.month, _focusDay!.day);
      maxD = minD.add(const Duration(hours: 24));
    } else {
      for (final t in _tasks) {
        final s = _d(t.startMs), e = _d(t.endMs);
        if (minD == null || s.isBefore(minD)) minD = s;
        if (maxD == null || e.isAfter(maxD)) maxD = e;
      }
      final now = DateTime.now();
      minD ??= _floorUnit(now);
      // 既定表示幅を広めに (= ユーザー要望: 表示領域をもう少し大きく)。
      maxD ??= (_unit == 'hour'
          ? minD.add(const Duration(hours: 12))
          : minD.add(const Duration(days: 14)));
    }
    final start0 = _unit == 'hour'
        ? _floorUnit(minD).subtract(const Duration(hours: 1))
        : _floorUnit(minD).subtract(const Duration(days: 1));
    // ── 列の日時リスト (= ユーザー要望: 時間モードは表示しない時間帯を除外) ──
    final cols = <DateTime>[];
    final boldCols = <int>{}; // 日の変わり目の列インデックス (グリッド強調用)
    if (_unit == 'hour') {
      var d = start0;
      final lim = maxD.add(const Duration(hours: 3));
      int guard = 0;
      while (d.isBefore(lim) && guard++ < 50000) {
        if (_hourVisible(d.hour)) {
          if (cols.isEmpty || cols.last.day != d.day) boldCols.add(cols.length);
          cols.add(d);
        }
        d = d.add(const Duration(hours: 1));
      }
    } else {
      final n = _unitIndex(start0, maxD) + 3;
      for (int i = 0; i < n; i++) {
        cols.add(start0.add(Duration(days: i)));
      }
    }
    if (cols.isEmpty) cols.add(start0);
    final totalCols = cols.length;
    // 画面の幅いっぱいまで列を広げる (= ユーザー要望: 小さすぎる)。
    // 列が少ない時に間延びしすぎないよう上限も設ける。
    final availW = MediaQuery.sizeOf(context).width - _nameW - 48;
    _fitColW = totalCols > 0
        ? (availW / totalCols)
            .clamp(0.0, _unit == 'hour' ? 130.0 : 170.0)
            .toDouble()
        : 0;
    final timelineW = totalCols * _colW;
    final blockedCols = <int>{
      if (_unit == 'hour')
        for (int i = 0; i < cols.length; i++)
          if (_isBlockedColumn(cols[i])) i,
    };

    // ── AM/PM ラベルは各ブロックの中央 1 か所だけに出す (= ユーザー要望) ──
    final amPmCenters = <int>{};
    if (_unit == 'hour' && _use12h) {
      int runStart = -1;
      bool? runPm;
      void closeRun(int endExclusive) {
        if (runStart >= 0 && endExclusive > runStart) {
          amPmCenters.add((runStart + endExclusive - 1) ~/ 2);
        }
        runStart = -1;
        runPm = null;
      }

      for (int i = 0; i < cols.length; i++) {
        if (boldCols.contains(i)) {
          closeRun(i);
          continue;
        }
        final pm = cols[i].hour >= 12;
        if (runStart < 0) {
          runStart = i;
          runPm = pm;
        } else if (pm != runPm) {
          closeRun(i);
          runStart = i;
          runPm = pm;
        }
      }
      closeRun(cols.length);
    }

    // ── 現在時刻インジケーター (= ユーザー要望: 現在の時刻が分かるように) ──
    final nowT = DateTime.now();
    double? nowX;
    {
      final ci = _colIndex(cols, nowT);
      if (ci >= 0 && ci < cols.length) {
        final colTime = cols[ci];
        final unitMs = _unit == 'hour' ? 3600000 : 86400000;
        final diff =
            nowT.millisecondsSinceEpoch - colTime.millisecondsSinceEpoch;
        // 現在が可視列の範囲内 (= その列の単位内) の時だけ線を出す。
        if (diff >= 0 && diff < unitMs) {
          nowX = ci * _colW + (diff / unitMs) * _colW;
        }
      }
    }

    final isMobile = MediaQuery.of(context).size.width < 600;

    return Focus(
      focusNode: _ganttFocus,
      // 開いた直後からキー操作 (Delete / Backspace / S) が効くように
      // フォーカスを取っておく (= ユーザー要望: クリック → Delete で削除)。
      autofocus: true,
      onKeyEvent: _onGanttKey,
      child: Container(
        color: const Color(0xFF12121C),
        child: Row(children: [
          Expanded(
            child: Column(children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(12, 10, 12, 6),
                child: Row(children: [
                  if (!isMobile) ...[
                    const Icon(Icons.view_timeline_rounded,
                        color: Color(0xFF4FC3F7)),
                    const SizedBox(width: 8),
                    Flexible(
                      child: Text(widget.provider.t('gantt.title'),
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                              color: Colors.white,
                              fontSize: 16,
                              fontWeight: FontWeight.w700)),
                    ),
                    const SizedBox(width: 8),
                  ],
                  // ── 日 / 時間 の単位切替 (= ユーザー要望: 時間単位のタスク表) ──
                  SegmentedButton<String>(
                    segments: [
                      ButtonSegment(
                          value: 'day',
                          label: Text(widget.provider.t('gantt.day'))),
                      ButtonSegment(
                          value: 'hour',
                          label: Text(widget.provider.t('gantt.hour'))),
                    ],
                    selected: {_unit},
                    showSelectedIcon: false,
                    style: SegmentedButton.styleFrom(
                      visualDensity: VisualDensity.compact,
                      foregroundColor: Colors.white70,
                      selectedForegroundColor: Colors.white,
                      selectedBackgroundColor:
                          const Color(0xFF4FC3F7).withValues(alpha: 0.5),
                    ),
                    onSelectionChanged: (s) => _setUnit(s.first),
                  ),
                  // ── 表示する時間帯の設定 (時間モードのみ) (= ユーザー要望) ──
                  if (_unit == 'hour')
                    IconButton(
                      tooltip: context
                          .read<MindMapProvider>()
                          .t('gantt.timeAndBlockedTitle'),
                      visualDensity: VisualDensity.compact,
                      icon: const Icon(Icons.schedule_rounded,
