/// ガントチャートの背景グリッド (= ユーザー要望: 枠線が分かるように)。 縦線は
/// 列境界 (日/時間)、 横線は行境界。 名前列との境界と軸下を強調する。 時間モード
/// では 0 時の列 (= 日の変わり目) を強調する。
class _GanttGridPainter extends CustomPainter {
  final double nameW;
  final double colW;
  final double axisH;
  final double rowH;
  final int totalCols;
  final int rowCount;
  final Set<int> boldCols; // 日の変わり目の列インデックス (強調表示)。
  final Set<int> blockedCols; // タスクを設定しない時間帯。
  _GanttGridPainter({
    required this.nameW,
    required this.colW,
    required this.axisH,
    required this.rowH,
    required this.totalCols,
    required this.rowCount,
    required this.boldCols,
    required this.blockedCols,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final blockedFill = Paint()
      ..color = const Color(0x24FF5252)
      ..style = PaintingStyle.fill;
    final blockedStripe = Paint()
      ..color = const Color(0x40FF8A80)
      ..strokeWidth = 1;
    final thin = Paint()
      ..color = const Color(0x22FFFFFF)
      ..strokeWidth = 1;
    final bold = Paint()
      ..color = const Color(0x55FFFFFF)
      ..strokeWidth = 1;
    for (final i in blockedCols) {
      final rect = Rect.fromLTWH(nameW + i * colW, 0, colW, size.height);
      canvas.drawRect(rect, blockedFill);
      canvas.save();
      canvas.clipRect(rect);
      for (double x = rect.left - size.height;
          x < rect.right;
          x += 12) {
        canvas.drawLine(
          Offset(x, rect.bottom),
          Offset(x + size.height, rect.top),
          blockedStripe,
        );
      }
      canvas.restore();
    }
    // 縦線 (列境界)。 日の変わり目の列を強調。
    for (int i = 0; i <= totalCols; i++) {
      final x = nameW + i * colW;
      if (x > size.width + 0.5) break;
      canvas.drawLine(Offset(x, 0), Offset(x, size.height),
          boldCols.contains(i) ? bold : thin);
    }
    // 名前列との境界 + 軸下の境界。
    canvas.drawLine(Offset(nameW, 0), Offset(nameW, size.height), bold);
    canvas.drawLine(Offset(0, axisH), Offset(size.width, axisH), bold);
    // 横線 (行境界)。
    for (int r = 0; r <= rowCount; r++) {
      final y = axisH + r * rowH;
      if (y > size.height + 0.5) break;
      canvas.drawLine(Offset(0, y), Offset(size.width, y), thin);
    }
  }

  @override
  bool shouldRepaint(covariant _GanttGridPainter old) => true;
}

// ─── お絵かき (ペイント) ページ (= ユーザー要望: ペイントの様な自由に
//     お絵かきができるページ) ───
// ストロークはノードと独立に prefs (paint_<pageId>) に保存する (モデル非依存)。
// 1 ストローク = 色 + 太さ + 通過した点列。消しゴムは新しい線として保存せず、
// 既存の線・図形・テキストだけを削る。
class _PaintStroke {
  final int color;
  final double width;
  final List<Offset> points;

  /// 消しゴムのストロークか (= ユーザー要望: 図形/テキストも部分的に消せるように)。
  /// true のものは描画後に図形/テキストの上からもう一度描いて部分消去する。
  final bool erase;

  /// レイヤー順 (大きいほど手前) と グループ id (0 = 未所属)。
  /// (= ユーザー要望: 後から配置した要素が手前 + Ctrl+G グループ化)
  int z;
  int g;

  /// ペンの種類 (= ユーザー要望: チョーク / スクイグル 等)。
  /// '' = 通常 / 'chalk' / 'squiggle' / 'dotted' / 'dashed' / 'marker'。
  final String ps;

  /// 濃さ (不透明度 0.15〜1.0)。 1.0 = 従来どおり (= ユーザー要望: 詳細設定)。
  final double op;

  /// 間隔/スケール (0.4〜2.5)。 チョークの粒の間隔・スクイグルの波長・
  /// 点線/破線のピッチに掛かる倍率。 1.0 = 既定。
  final double iv;

  /// 輝き (グロー)。 true なら同色のぼかしハローを線の下に重ねて描く
  /// (= ユーザー要望: 文字や線に輝きを付けられるように)。
  final bool glow;

  /// どのレイヤーに属するか (0 = 一番下)。 消しゴムは**選んでいるレイヤーの
  /// 要素だけ**に効く (= ユーザー要望: 上に配置されたレイヤーに対してのみ
  /// 消しゴムを適用できるように)。 描く順 (前後関係) は従来どおり z が決める。
  int lyr;
  _PaintStroke(this.color, this.width, this.points,
      {this.erase = false,
      this.z = 0,
      this.g = 0,
      this.lyr = 0,
      this.ps = '',
      this.op = 1.0,
      this.iv = 1.0,
      this.glow = false});

  Map<String, dynamic> toJson() => {
        'c': color,
        'w': width,
        'p': points.map((o) => [o.dx, o.dy]).toList(),
        if (erase) 'e': true,
        if (z != 0) 'z': z,
        if (g != 0) 'g': g,
        if (lyr != 0) 'ly': lyr,
        if (ps.isNotEmpty) 'ps': ps,
        if (op != 1.0) 'o': op,
        if (iv != 1.0) 'iv': iv,
        if (glow) 'gw': true,
      };

  factory _PaintStroke.fromJson(Map m) => _PaintStroke(
        (m['c'] as num?)?.toInt() ?? 0xFF000000,
        (m['w'] as num?)?.toDouble() ?? 4.0,
        ((m['p'] as List?) ?? const [])
            .whereType<List>()
            .map((e) => Offset(
                  (e.isNotEmpty ? (e[0] as num) : 0).toDouble(),
                  (e.length > 1 ? (e[1] as num) : 0).toDouble(),
                ))
            .toList(),
        erase: m['e'] == true,
        z: (m['z'] as num?)?.toInt() ?? 0,
        g: (m['g'] as num?)?.toInt() ?? 0,
        lyr: (m['ly'] as num?)?.toInt() ?? 0,
        ps: (m['ps'] ?? '').toString(),
        op: ((m['o'] as num?)?.toDouble() ?? 1.0).clamp(0.1, 1.0),
        iv: ((m['iv'] as num?)?.toDouble() ?? 1.0).clamp(0.3, 3.0),
        glow: m['gw'] == true,
      );
}

/// お絵かきページのテキスト要素 (= ユーザー要望: テキストボックスでリッチに入力)。
/// 複数行 + 太字/斜体/サイズ/色の書式を持つ。
/// フリーノートで選べる文字の種類 (= ユーザー要望: 範囲選択して文字の種類を
/// 変えられるように)。 アプリはカスタムフォントを同梱していないので、
/// プラットフォームが解決できる総称ファミリー名を使う
/// (Windows/Android どちらでも Skia のフォントマネージャが解決し、
/// 未対応なら既定フォントへ無害にフォールバックする)。
/// 文字書式のプリセット (= ユーザー要望: 文字の種類や大きさ、 色の設定値を
/// 何項目か保存しておいて、 セットして使えるように)。
/// フリーノートのテキストツール / 選択中テキストへワンタップで適用できる。
/// SharedPreferences (`paintTextPresets_v1`) に JSON で保存する。
class _PaintTextPreset {
  String name;
  String font; // '' = 既定
  double size;
  int color;
  bool bold;
  bool italic;
  _PaintTextPreset({
    required this.name,
    required this.font,
    required this.size,
    required this.color,
    required this.bold,
    required this.italic,
  });

  Map<String, dynamic> toJson() => {
        'n': name,
        'ff': font,
        's': size,
        'c': color,
        if (bold) 'b': true,
        if (italic) 'i': true,
      };

  factory _PaintTextPreset.fromJson(Map m) => _PaintTextPreset(
        name: (m['n'] ?? '').toString(),
        font: (m['ff'] ?? '').toString(),
        size: ((m['s'] as num?)?.toDouble() ?? 28.0).clamp(10.0, 96.0),
        color: (m['c'] as num?)?.toInt() ?? 0xFF000000,
        bold: m['b'] == true,
        italic: m['i'] == true,
      );
}

/// フリーノートの図形テンプレート (= ユーザー要望: フリーノートで
/// テンプレート登録できるようにして、 登録した図を呼び出せるように)。
/// 選択中の要素 (線 / 図形 / テキスト / 画像) をひとかたまりで保存し、
/// 後からワンタップでページへ挿入できる。
/// 保存位置は左上を原点 (0,0) に正規化してあるので、 どのページに入れても
/// 同じ形で出てくる。 SharedPreferences (`paintTemplates_v1`) に JSON 保存。
class _PaintTemplate {
  String name;

  /// {'t': 'stroke'|'shape'|'text'|'image', 'd': <各クラスの toJson>}
  final List<Map<String, dynamic>> items;
  _PaintTemplate({required this.name, required this.items});

  Map<String, dynamic> toJson() => {'n': name, 'it': items};

  factory _PaintTemplate.fromJson(Map m) => _PaintTemplate(
        name: (m['n'] ?? '').toString(),
        items: ((m['it'] as List?) ?? const [])
            .whereType<Map>()
            .map((e) => Map<String, dynamic>.from(e))
            .toList(),
      );
}

class _PaintFontChoice {
  final String family; // '' = 既定
  final String labelKey;
  const _PaintFontChoice(this.family, this.labelKey);
}

const List<_PaintFontChoice> _kPaintFonts = [
  _PaintFontChoice('', 'paint.fontDefault'),
  _PaintFontChoice('sans-serif', 'paint.fontSans'),
  _PaintFontChoice('serif', 'paint.fontSerif'),
  _PaintFontChoice('monospace', 'paint.fontMono'),
  _PaintFontChoice('cursive', 'paint.fontCursive'),
];

/// 総称ファミリー名が実際にどのフォントで表示されるかは OS 依存で、
/// ラベルが「既定」 だけだと何の書体か分からない (= ユーザー要望: 既定だと
/// フォントの種類が分からないから、 ちゃんとフォント名を書いて欲しい)。
/// プラットフォームごとの実フォント名を返し、 ラベルの後ろに併記する。
String _paintFontRealName(String family) {
  final bool win = !kIsWeb && Platform.isWindows;
  final bool android = !kIsWeb && Platform.isAndroid;
  switch (family) {
    case '':
      // Flutter の既定はプラットフォームの UI フォント。
      if (win) return 'Yu Gothic UI';
      if (android) return 'Roboto / Noto Sans JP';
      return 'System';
    case 'sans-serif':
      if (win) return 'Segoe UI';
      if (android) return 'Roboto';
      return 'Sans';
    case 'serif':
      if (win) return 'Times New Roman';
      if (android) return 'Noto Serif';
      return 'Serif';
    case 'monospace':
      if (win) return 'Consolas';
      if (android) return 'Droid Sans Mono';
      return 'Mono';
    case 'cursive':
      if (win) return 'Segoe Script';
      if (android) return 'Cursive';
      return 'Cursive';
  }
  return family;
}

class _PaintText {
  Offset pos;
  String text;
  int color;
  double size;
  bool bold;
  bool italic;

  /// 文字の種類 (フォントファミリー)。 '' = 既定 (= ユーザー要望)。
  String font;

  /// 輝き (グロー)。 true なら同色のぼかしハローを文字の後ろに重ねる
  /// (= ユーザー要望: 文字や線に輝きを付けられるように)。
  bool glow;

  /// ハイパーリンク URL ('' = 無し)。 URL 貼り付けで自動設定されるほか、
  /// 選択バーの「リンク」 ボタンで任意の文字列に URL を紐付けられる
  /// (= ユーザー要望: URL 貼り付け後のハイパーリンク作成 + 文字とリンクの連携)。
  String link;

  /// 文字の曲げ強度 (= ユーザー要望: 文字を図の様に曲げる + 強度調整)。
  /// -1.0〜1.0。 0 = 直線、 正 = 上向きアーチ、 負 = 下向きアーチ。
  /// 1.0 で 180° の弧になる。
  double curve;

  /// Z 軸回転 (度、 時計回り) (= ユーザー要望: z 軸方向に文字を回転)。
  double rot;
  final List<_PaintStroke> erasers;

  /// レイヤー順 (大きいほど手前) と グループ id (0 = 未所属)。
  int z;
  int g;

  /// どのレイヤーに属するか (0 = 一番下)。 消しゴムは選んでいるレイヤーの
  /// 要素だけに効く (= ユーザー要望)。
  int lyr;
  _PaintText(this.pos, this.text, this.color, this.size,
      {this.lyr = 0,
      this.bold = false,
      this.italic = false,
      this.font = '',
      this.glow = false,
      this.link = '',
      this.curve = 0,
      this.rot = 0,
      this.z = 0,
      this.g = 0,
      List<_PaintStroke>? erasers})
      : erasers = erasers ?? [];

  Map<String, dynamic> toJson() => {
        'x': pos.dx,
        'y': pos.dy,
        't': text,
        'c': color,
        's': size,
        if (bold) 'b': true,
        if (italic) 'i': true,
        if (font.isNotEmpty) 'ff': font,
        if (glow) 'gw': true,
        if (link.isNotEmpty) 'lk': link,
        if (curve != 0) 'cv': curve,
        if (rot != 0) 'rt': rot,
        if (z != 0) 'z': z,
        if (g != 0) 'g': g,
        if (lyr != 0) 'ly': lyr,
        if (erasers.isNotEmpty)
          'er': erasers.map((stroke) => stroke.toJson()).toList(),
      };

  factory _PaintText.fromJson(Map m) => _PaintText(
        Offset((m['x'] as num?)?.toDouble() ?? 0,
            (m['y'] as num?)?.toDouble() ?? 0),
        (m['t'] ?? '').toString(),
        (m['c'] as num?)?.toInt() ?? 0xFF000000,
        (m['s'] as num?)?.toDouble() ?? 22.0,
        bold: m['b'] == true,
        italic: m['i'] == true,
        font: (m['ff'] ?? '').toString(),
        glow: m['gw'] == true,
        link: (m['lk'] ?? '').toString(),
        curve: ((m['cv'] as num?)?.toDouble() ?? 0).clamp(-1.0, 1.0),
        rot: (m['rt'] as num?)?.toDouble() ?? 0,
        z: (m['z'] as num?)?.toInt() ?? 0,
        g: (m['g'] as num?)?.toInt() ?? 0,
        lyr: (m['ly'] as num?)?.toInt() ?? 0,
        erasers: ((m['er'] as List?) ?? const [])
            .whereType<Map>()
            .map((stroke) => _PaintStroke.fromJson(stroke))
            .toList(),
      );
}

/// お絵かきページの現在ツール (= ユーザー要望: ペン/消しゴム/テキスト/図形/画像)。
enum _PaintTool { pen, eraser, text, shape, image, select, fill }

/// タップ位置ベースの領域塗り (= ユーザー要望: 図形の重なりのうち塗り潰す
/// 領域を個別で指定できるように)。 塗る領域は保存した点から毎描画時に
/// 「その点を含む図形の交差 − 含まない図形」 で再計算するので、 図形を
/// 動かすと塗りも追従する。
class _PaintFill {
  double x;
  double y;
  int color;
  double alpha;
  _PaintFill(this.x, this.y, this.color, this.alpha);

  Map<String, dynamic> toJson() => {
        'x': x,
        'y': y,
        'c': color,
        'a': alpha,
      };

  factory _PaintFill.fromJson(Map m) => _PaintFill(
        (m['x'] as num?)?.toDouble() ?? 0,
        (m['y'] as num?)?.toDouble() ?? 0,
        (m['c'] as num?)?.toInt() ?? 0xFF6C63FF,
        ((m['a'] as num?)?.toDouble() ?? 0.85).clamp(0.05, 1.0),
      );
}

/// 外接矩形に内接する正多角形の Path (= ユーザー要望: 図形の種類を増やす)。
/// [n] 頂点。 [rotation] は最初の頂点の角度 (既定 = 真上)。
/// (状態クラス内の _paintPolygonPath(_PaintShape) とは別物なので名前を分ける)
Path _paintRegularPolygonPath(Rect rect, int n,
    {double rotation = -math.pi / 2}) {
  final cx = rect.center.dx, cy = rect.center.dy;
  final rx = rect.width / 2, ry = rect.height / 2;
  final path = Path();
  for (int i = 0; i < n; i++) {
    final ang = rotation + i * 2 * math.pi / n;
    final p = Offset(cx + rx * math.cos(ang), cy + ry * math.sin(ang));
    if (i == 0) {
      path.moveTo(p.dx, p.dy);
    } else {
      path.lineTo(p.dx, p.dy);
    }
  }
  path.close();
  return path;
}

/// 外接矩形に内接する星形 (5 芒星) の Path (= ユーザー要望: 星マーク)。
Path _paintStarPath(Rect rect,
    {int points = 5, double innerRatio = 0.45}) {
  final cx = rect.center.dx, cy = rect.center.dy;
  final rx = rect.width / 2, ry = rect.height / 2;
  final path = Path();
  for (int i = 0; i < points * 2; i++) {
    final r = i.isEven ? 1.0 : innerRatio;
    final ang = -math.pi / 2 + i * math.pi / points;
    final p = Offset(cx + rx * r * math.cos(ang), cy + ry * r * math.sin(ang));
    if (i == 0) {
      path.moveTo(p.dx, p.dy);
    } else {
      path.lineTo(p.dx, p.dy);
    }
  }
  path.close();
  return path;
}

/// 外接矩形に内接するハートの Path (= ユーザー要望: 図形の種類を増やす)。
Path _paintHeartPath(Rect rect) {
  final w = rect.width, h = rect.height;
  final x = rect.left, y = rect.top;
  final path = Path()
    ..moveTo(x + w * 0.5, y + h * 0.28)
    // 左半分
    ..cubicTo(x + w * 0.42, y + h * 0.02, x + w * 0.02, y + h * 0.05,
        x + w * 0.03, y + h * 0.36)
    ..cubicTo(x + w * 0.04, y + h * 0.60, x + w * 0.28, y + h * 0.78,
        x + w * 0.5, y + h * 0.98)
    // 右半分
    ..cubicTo(x + w * 0.72, y + h * 0.78, x + w * 0.96, y + h * 0.60,
        x + w * 0.97, y + h * 0.36)
    ..cubicTo(x + w * 0.98, y + h * 0.05, x + w * 0.58, y + h * 0.02,
        x + w * 0.5, y + h * 0.28)
    ..close();
  return path;
}

/// 外接矩形に内接する十字 (プラス) の Path (= ユーザー要望)。
Path _paintCrossPath(Rect rect) {
  final t = 1.0 / 3.0; // 腕の太さ比
  final x1 = rect.left + rect.width * t;
  final x2 = rect.left + rect.width * (1 - t);
  final y1 = rect.top + rect.height * t;
  final y2 = rect.top + rect.height * (1 - t);
  return Path()
    ..moveTo(x1, rect.top)
    ..lineTo(x2, rect.top)
    ..lineTo(x2, y1)
    ..lineTo(rect.right, y1)
    ..lineTo(rect.right, y2)
    ..lineTo(x2, y2)
    ..lineTo(x2, rect.bottom)
    ..lineTo(x1, rect.bottom)
    ..lineTo(x1, y2)
    ..lineTo(rect.left, y2)
    ..lineTo(rect.left, y1)
    ..lineTo(x1, y1)
    ..close();
}

/// 図形の「面」 の Path (塗り領域計算・重なり塗りの共通ロジック)。
/// _PaintCanvasPainter._drawShape と同じ頂点計算にすること。
Path _paintShapeAreaPathOf(_PaintShape s) {
  final rect = Rect.fromPoints(s.a, s.b);
  switch (s.kind) {
    case 1:
      return Path()..addOval(rect);
    case 4:
      return Path()
        ..moveTo(rect.center.dx, rect.top)
        ..lineTo(rect.left, rect.bottom)
        ..lineTo(rect.right, rect.bottom)
        ..close();
    case 5:
      return Path()
        ..moveTo(rect.center.dx, rect.top)
        ..lineTo(rect.right, rect.center.dy)
        ..lineTo(rect.center.dx, rect.bottom)
        ..lineTo(rect.left, rect.center.dy)
        ..close();
    // ── 追加図形 (= ユーザー要望: 星マークなど挿入できる図形を増やす) ──
    case 6:
      return _paintStarPath(rect);
    case 7:
      return _paintRegularPolygonPath(rect, 5);
    case 8:
      return _paintRegularPolygonPath(rect, 6);
    case 9:
      return _paintHeartPath(rect);
    case 10:
      return _paintCrossPath(rect);
    default:
      return Path()..addRect(rect);
  }
}

/// 点 [p] が指す「領域」 の Path を返す (= タップ位置ベースの塗り)。
/// p を含む面図形の交差から、 含まない面図形を引いた形。 p がどの図形にも
/// 入っていなければ null。
Path? _paintRegionAt(List<_PaintShape> shapes, Offset p) {
  final containing = <_PaintShape>[];
  final others = <_PaintShape>[];
  for (final s in shapes) {
    if (s.kind == 2 || s.kind == 3) continue; // 線/矢印は面が無い
    if (_paintShapeAreaPathOf(s).contains(p)) {
      containing.add(s);
    } else {
      others.add(s);
    }
  }
  if (containing.isEmpty) return null;
  Path acc = _paintShapeAreaPathOf(containing.first);
  for (int i = 1; i < containing.length; i++) {
    acc = Path.combine(
        PathOperation.intersect, acc, _paintShapeAreaPathOf(containing[i]));
  }
  for (final s in others) {
    acc = Path.combine(
        PathOperation.difference, acc, _paintShapeAreaPathOf(s));
  }
  return acc;
}

/// 選択済み図形のリサイズ位置。線と矢印は start/end、それ以外は8方向。
enum _PaintShapeResizeHandle {
  topLeft,
  top,
  topRight,
  right,
  bottomRight,
  bottom,
  bottomLeft,
  left,
  start,
  end,
}

/// 図形要素 (= ユーザー要望: 図形挿入)。
/// kind: 0=四角,1=楕円,2=線,3=矢印,4=三角,5=ひし形。
class _PaintShape {
  int kind;
  Offset a, b;
  int color;
  double width;
  bool fill;

  /// 中塗りの不透明度 0.0〜1.0 (= ユーザー要望: 図形の中塗り箇所に透明度を
  /// 設定できるように)。 1.0 = 従来どおり不透明。 輪郭線はこの値の影響を
  /// 受けず、 中塗りだけが透ける。
  double fillAlpha;

  /// 中を塗る色 (= ユーザー要望: 枠線の色と中の塗り色を別々に指定できるように)。
  /// null なら従来どおり `color` (枠線と同じ色) で塗る。
  int? fillColor;
  final List<_PaintStroke> erasers;

  /// レイヤー順 (大きいほど手前) と グループ id (0 = 未所属)。
  int z;
  int g;

  /// 重なり塗りグループ id (0 = 無し)。 同じ id を持つ図形同士の
  /// 「重なる領域だけ」 を塗りつぶす (= ユーザー要望)。
  int fg;

  /// 輝き (グロー) (= ユーザー要望: 文字や線に輝きを付けられるように)。
  bool glow;

  /// Z 軸回転 (度、 時計回り、 外接矩形の中心まわり)
  /// (= ユーザー要望: z 軸方向に図形を回転)。
  double rot;

  /// どのレイヤーに属するか (0 = 一番下)。 消しゴムは選んでいるレイヤーの
  /// 要素だけに効く (= ユーザー要望)。
  int lyr;
  _PaintShape(this.kind, this.a, this.b, this.color, this.width, this.fill,
      {this.lyr = 0,
      this.fillAlpha = 1.0,
      this.fillColor,
      this.z = 0,
      this.g = 0,
      this.fg = 0,
      this.glow = false,
      this.rot = 0,
      List<_PaintStroke>? erasers})
      : erasers = erasers ?? [];

  Map<String, dynamic> toJson() => {
        'k': kind,
        'ax': a.dx,
        'ay': a.dy,
        'bx': b.dx,
        'by': b.dy,
        'c': color,
        'w': width,
        'f': fill,
        if (fillAlpha < 1.0) 'fa': fillAlpha,
        if (fillColor != null) 'fc': fillColor,
        if (z != 0) 'z': z,
        if (g != 0) 'g': g,
        if (lyr != 0) 'ly': lyr,
        if (fg != 0) 'fg': fg,
        if (glow) 'gw': true,
        if (rot != 0) 'rt': rot,
        if (erasers.isNotEmpty)
          'er': erasers.map((stroke) => stroke.toJson()).toList(),
      };

  factory _PaintShape.fromJson(Map m) => _PaintShape(
        (m['k'] as num?)?.toInt() ?? 0,
        Offset((m['ax'] as num?)?.toDouble() ?? 0,
            (m['ay'] as num?)?.toDouble() ?? 0),
        Offset((m['bx'] as num?)?.toDouble() ?? 0,
            (m['by'] as num?)?.toDouble() ?? 0),
        (m['c'] as num?)?.toInt() ?? 0xFF000000,
        (m['w'] as num?)?.toDouble() ?? 3.0,
        m['f'] == true,
        fillAlpha: ((m['fa'] as num?)?.toDouble() ?? 1.0).clamp(0.0, 1.0),
        fillColor: (m['fc'] as num?)?.toInt(),
        z: (m['z'] as num?)?.toInt() ?? 0,
        g: (m['g'] as num?)?.toInt() ?? 0,
        lyr: (m['ly'] as num?)?.toInt() ?? 0,
        fg: (m['fg'] as num?)?.toInt() ?? 0,
        glow: m['gw'] == true,
        rot: (m['rt'] as num?)?.toDouble() ?? 0,
        erasers: ((m['er'] as List?) ?? const [])
            .whereType<Map>()
            .map((stroke) => _PaintStroke.fromJson(stroke))
            .toList(),
      );
}

Rect? _paintStrokeBounds(_PaintStroke stroke, {double extra = 0}) {
  if (stroke.points.isEmpty) return null;
  var minX = stroke.points.first.dx;
  var minY = stroke.points.first.dy;
  var maxX = minX;
  var maxY = minY;
  for (int i = 1; i < stroke.points.length; i++) {
    final point = stroke.points[i];
    minX = math.min(minX, point.dx);
    minY = math.min(minY, point.dy);
    maxX = math.max(maxX, point.dx);
    maxY = math.max(maxY, point.dy);
  }
  return Rect.fromLTRB(minX, minY, maxX, maxY)
      .inflate(stroke.width / 2 + extra);
}

Map<_PaintShapeResizeHandle, Offset> _paintShapeResizeHandleCenters(
    _PaintShape shape) {
  if (shape.kind == 2 || shape.kind == 3) {
    return {
      _PaintShapeResizeHandle.start: shape.a,
      _PaintShapeResizeHandle.end: shape.b,
    };
  }
  final rect = Rect.fromPoints(shape.a, shape.b);
  return {
    _PaintShapeResizeHandle.topLeft: rect.topLeft,
    _PaintShapeResizeHandle.top: Offset(rect.center.dx, rect.top),
    _PaintShapeResizeHandle.topRight: rect.topRight,
    _PaintShapeResizeHandle.right: Offset(rect.right, rect.center.dy),
    _PaintShapeResizeHandle.bottomRight: rect.bottomRight,
    _PaintShapeResizeHandle.bottom: Offset(rect.center.dx, rect.bottom),
    _PaintShapeResizeHandle.bottomLeft: rect.bottomLeft,
    _PaintShapeResizeHandle.left: Offset(rect.left, rect.center.dy),
  };
}

/// 画像要素 (= ユーザー要望: 画像貼り付け)。 ローカルパス + 配置矩形。
class _PaintImageItem {
  String path;
  Rect rect;

  /// レイヤー順 (大きいほど手前) と グループ id (0 = 未所属)。
  int z;
  int g;

  /// どのレイヤーに属するか (0 = 一番下)。 消しゴムは**選んでいるレイヤーの
  /// 要素だけ**に効く (= ユーザー要望: 上に配置されたレイヤーに対してのみ
  /// 消しゴムを適用できるように)。 描く順 (前後関係) は従来どおり z が決める。
  int lyr;
  _PaintImageItem(this.path, this.rect,
      {this.z = 0, this.g = 0, this.lyr = 0});

  Map<String, dynamic> toJson() => {
        'p': path,
        'l': rect.left,
        't': rect.top,
        'w': rect.width,
        'h': rect.height,
        if (z != 0) 'z': z,
        if (g != 0) 'g': g,
        if (lyr != 0) 'ly': lyr,
      };

  factory _PaintImageItem.fromJson(Map m) => _PaintImageItem(
        (m['p'] ?? '').toString(),
        Rect.fromLTWH(
          (m['l'] as num?)?.toDouble() ?? 0,
          (m['t'] as num?)?.toDouble() ?? 0,
          (m['w'] as num?)?.toDouble() ?? 100,
          (m['h'] as num?)?.toDouble() ?? 100,
        ),
        z: (m['z'] as num?)?.toInt() ?? 0,
        g: (m['g'] as num?)?.toInt() ?? 0,
        lyr: (m['ly'] as num?)?.toInt() ?? 0,
      );
}

class _PaintEraseSnapshot {
  final List<_PaintStroke> strokes;
  final List<_PaintText> texts;
  final List<_PaintShape> shapes;
  final List<_PaintImageItem> images;
  _PaintEraseSnapshot({
    required this.strokes,
    required this.texts,
    required this.shapes,
    required this.images,
  });
}

class _PaintEraseEdit {
  final _PaintEraseSnapshot before;
  final _PaintEraseSnapshot after;
  _PaintEraseEdit({required this.before, required this.after});
}

/// 用紙サイズプリセット (= ユーザー要望: A4/B5 等)。 px は 96dpi 相当の論理サイズ。
