/// 1 ページ (= 1 枚のキャンバス)。 ストローク/テキスト/図形/画像 + 用紙サイズ。
class _PaintSheet {
  String name;
  String sizeId; // 'custom' の時は customW/customH を使う (= ユーザー要望)
  double customW;
  double customH;
  double ruleSpacing;
  final List<_PaintStroke> strokes;
  final List<_PaintText> texts;
  final List<_PaintShape> shapes;
  final List<_PaintImageItem> images;

  /// タップ位置ベースの領域塗り (= ユーザー要望: 塗る領域を個別指定)。
  final List<_PaintFill> fills;

  /// 用紙そのものの色 (= ユーザー要望: 何もない白紙を塗ったら紙の色が変わる)。
  /// null なら白。
  int? bgColor;

  /// 用紙そのものの背景画像 (= ユーザー要望: PDF を読み込んだ時に、 白い紙の
  /// 上に画像を重ねるのではなく画像自体が背景になるように)。
  /// 用紙いっぱいに敷かれ、 移動・選択・消しゴムの対象にならない。
  String? bgImage;
  final List<String> undo; // LIFO: 'stroke'|'text'|'shape'|'image'|'erase'
  // 消しゴムで消したテキスト/図形の退避 (= ユーザー要望: 文字/図形も消しゴムで
  //   消せる + 元に戻せる)。 undo に積んだ 'erase' と 1:1 で対応する LIFO。
  //   セッション内のみ (永続化しない)。 list='text'/'shape'、 index=元の位置。
  final List<({String list, int index, Object item})> eraseUndo = [];
  _PaintSheet({
    required this.name,
    required this.sizeId,
    this.customW = 1000,
    this.customH = 1000,
    this.ruleSpacing = 0,
    List<_PaintStroke>? strokes,
    List<_PaintText>? texts,
    List<_PaintShape>? shapes,
    List<_PaintImageItem>? images,
    List<_PaintFill>? fills,
  })  : strokes = strokes ?? [],
        texts = texts ?? [],
        shapes = shapes ?? [],
        images = images ?? [],
        fills = fills ?? [],
        undo = [];

  Map<String, dynamic> toJson() => {
        'n': name,
        'sz': sizeId,
        'cw': customW,
        'ch': customH,
        'rule': ruleSpacing,
        's': strokes.where((e) => !e.erase).map((e) => e.toJson()).toList(),
        't': texts.map((e) => e.toJson()).toList(),
        'sh': shapes.map((e) => e.toJson()).toList(),
        'im': images.map((e) => e.toJson()).toList(),
        if (fills.isNotEmpty) 'fl': fills.map((e) => e.toJson()).toList(),
        if (bgColor != null) 'bg': bgColor,
        if ((bgImage ?? '').isNotEmpty) 'bgi': bgImage,
      };

  factory _PaintSheet.fromJson(Map m, {String defaultName = 'Sheet'}) =>
      _PaintSheet(
        name: (m['n'] ?? defaultName).toString(),
        sizeId: (m['sz'] ?? 'a4p').toString(),
        customW: (m['cw'] as num?)?.toDouble() ?? 1000,
        customH: (m['ch'] as num?)?.toDouble() ?? 1000,
        ruleSpacing: (m['rule'] as num?)?.toDouble() ?? 0,
        strokes: ((m['s'] as List?) ?? const [])
            .whereType<Map>()
            .map((x) => _PaintStroke.fromJson(x))
            .toList(),
        texts: ((m['t'] as List?) ?? const [])
            .whereType<Map>()
            .map((x) => _PaintText.fromJson(x))
            .toList(),
        shapes: ((m['sh'] as List?) ?? const [])
            .whereType<Map>()
            .map((x) => _PaintShape.fromJson(x))
            .toList(),
        images: ((m['im'] as List?) ?? const [])
            .whereType<Map>()
            .map((x) => _PaintImageItem.fromJson(x))
            .toList(),
        fills: ((m['fl'] as List?) ?? const [])
            .whereType<Map>()
            .map((x) => _PaintFill.fromJson(x))
            .toList(),
      )
        ..bgColor = (m['bg'] as num?)?.toInt()
        ..bgImage = (m['bgi'] as String?);
}

/// フリーノート 1 冊。各ノートは複数のキャンバスページを持つ。
/// `pages` は旧 `sheets` と同じ要素形式なので、既存データの描画内容を
/// 変換せず保持できる。
class _PaintNote {
  String name;
  int selectedPage;
  final List<_PaintSheet> pages;

  _PaintNote({
    required this.name,
    required this.pages,
    this.selectedPage = 0,
  });

  Map<String, dynamic> toJson() => {
        'n': name,
        'sel': selectedPage,
        'pages': pages.map((page) => page.toJson()).toList(),
      };

  factory _PaintNote.fromJson(
    Map m, {
    required String defaultName,
    required String defaultPageName,
  }) {
    final pages = ((m['pages'] as List?) ?? const [])
        .whereType<Map>()
        .map((page) => _PaintSheet.fromJson(page, defaultName: defaultPageName))
        .toList();
    if (pages.isEmpty) {
      pages.add(_PaintSheet(name: defaultPageName, sizeId: 'a4p'));
    }
    var selectedPage = (m['sel'] as num?)?.toInt() ?? 0;
    if (selectedPage < 0 || selectedPage >= pages.length) selectedPage = 0;
    return _PaintNote(
      name: (m['n'] ?? defaultName).toString(),
      pages: pages,
      selectedPage: selectedPage,
    );
  }
}

class _PaintStore {
  static String _key(String pageId) => 'paint_$pageId';

  /// 旧形式 (ストロークのみ / {s,t} / {sheets,sel}) と新しい
  /// `{notes,noteSel}` の両対応。旧シートは内容を失わず「1 ページのノート」
  /// へ自動移行する。
  static Future<({List<_PaintNote> notes, int noteSel})> load(
    String pageId, {
    String defaultNoteName = 'Note 1',
    String defaultPageName = 'Page 1',
  }) async {
    List<_PaintNote> one(List<_PaintStroke> st, List<_PaintText> tx) => [
          _PaintNote(
            name: defaultNoteName,
            pages: [
              _PaintSheet(
                name: defaultPageName,
                sizeId: 'a4p',
                strokes: st,
                texts: tx,
              ),
            ],
          ),
        ];
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString(_key(pageId));
      if (raw == null || raw.isEmpty) return (notes: one([], []), noteSel: 0);
      final dec = jsonDecode(raw);
      if (dec is List) {
        final st =
            dec.whereType<Map>().map((m) => _PaintStroke.fromJson(m)).toList();
        return (notes: one(st, []), noteSel: 0);
      }
      if (dec is Map) {
        if (dec['notes'] is List) {
          final notes = (dec['notes'] as List)
              .whereType<Map>()
              .map((note) => _PaintNote.fromJson(note,
                  defaultName: defaultNoteName,
                  defaultPageName: defaultPageName))
              .toList();
          if (notes.isEmpty) notes.addAll(one([], []));
          var noteSel = (dec['noteSel'] as num?)?.toInt() ?? 0;
          if (noteSel < 0 || noteSel >= notes.length) noteSel = 0;
          return (notes: notes, noteSel: noteSel);
        }
        if (dec['sheets'] is List) {
          final sheets = (dec['sheets'] as List)
              .whereType<Map>()
              .map((m) => _PaintSheet.fromJson(m, defaultName: defaultPageName))
              .toList();
          if (sheets.isEmpty) return (notes: one([], []), noteSel: 0);
          // v2 の各シートを、同じ内容を持つ 1 ページのノートへ移行する。
          // 既存の名前はノート名として継承し、ページには新しい既定名を使う。
          final notes = <_PaintNote>[];
          for (int i = 0; i < sheets.length; i++) {
            final sheet = sheets[i];
            final oldName = sheet.name.trim();
            final isLegacyDefault =
                RegExp(r'^(?:Sheet|シート)\s*\d+$', caseSensitive: false)
                    .hasMatch(oldName);
            sheet.name = defaultPageName;
            notes.add(_PaintNote(
              name: isLegacyDefault
                  ? defaultNoteName.replaceFirst('1', '${i + 1}')
                  : (oldName.isEmpty ? defaultNoteName : oldName),
              pages: [sheet],
            ));
          }
          int sel = (dec['sel'] as num?)?.toInt() ?? 0;
          if (sel < 0 || sel >= notes.length) sel = 0;
          return (notes: notes, noteSel: sel);
        }
        final st = ((dec['s'] as List?) ?? const [])
            .whereType<Map>()
            .map((m) => _PaintStroke.fromJson(m))
            .toList();
        final tx = ((dec['t'] as List?) ?? const [])
            .whereType<Map>()
            .map((m) => _PaintText.fromJson(m))
            .toList();
        return (notes: one(st, tx), noteSel: 0);
      }
    } catch (_) {}
    return (notes: one([], []), noteSel: 0);
  }

  static Future<void> save(
      String pageId, List<_PaintNote> notes, int noteSel) async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(
          _key(pageId),
          jsonEncode({
            'v': 3,
            'notes': notes.map((note) => note.toJson()).toList(),
            'noteSel': noteSel,
          }));
    } catch (_) {}
  }
}

// ─── 文章作成 (ドキュメント) ページ (= ユーザー要望: 罫線がでてきて Word の
//     ような文章が作成できるモード) ──────────────────────────────────────────
// pageType=='document' のページで canvas の代わりに表示する全画面ビュー。
// flutter_quill のリッチテキストエディタを「白い用紙 + 罫線」 の上に載せる。
// 本文はノードと独立に prefs (document_<pageId>) へ Quill Delta JSON で保存。

/// 動画メモ / AI チャット欄などを、 アプリの外に浮かぶ別ウィンドウとして
/// 開く (= ユーザー要望: フローティングさせるボタンが欲しい)。
///
/// [kind] は 'memo' か 'ai'。 [text] を渡すと、 メモならその内容を引き継ぎ、
/// AI ならプロンプト欄に事前入力する。 デスクトップ専用。
///
/// ★ `kind: 'ai'` は**使わないこと**。 サブ窓のエンジンには webview_windows を
///   登録していないため (windows/runner/main.cpp のコメント参照)、 AI 画面を
///   作ろうとすると MissingPluginException で失敗する。 AI を外へ出したい時は
///   [openExternalWebWindow] (別プロセスの窓) を使う。
Future<bool> openFloatingToolWindow({
  required String kind,
  required MindMapProvider provider,
  String? text,
}) async {
  final isDesktop =
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
  if (!isDesktop) return false;
  try {
    final args = <String, dynamic>{'kind': kind};
    if (kind == 'ai') {
      final tmpl = provider.browserAiTargetDef['url'] ?? 'https://chatgpt.com/';
      args['url'] = tmpl.replaceAll('{q}', '');
      if (text != null && text.trim().isNotEmpty) args['q'] = text.trim();
    } else if (text != null && text.trim().isNotEmpty) {
      // メモ窓は起動時に保存済みテキストを読むので、 渡された内容を先に
      //   1 項目として積んでおくと、 そのまま続きが書ける。
      //   (上書きすると保存済みのメモが消えるので追記にする)
      await appendFloatingMemoItem(text);
    }
    final win = await DesktopMultiWindow.createWindow(jsonEncode(args));
    final size = kind == 'memo' ? const Size(460, 320) : const Size(520, 720);
    win
      ..setFrame(const Offset(160, 120) & size)
      // 題は統合後の名前に合わせる (= ユーザー要望: 外枠が
      //   「フローティングメモ」 のままなので「メモ」 に)。
      ..setTitle(provider.t(kind == 'memo' ? 'hdr.mapMemo' : 'hdr.popOutAi'))
      ..show();
    return true;
  } catch (e) {
    debugPrint('フローティング窓の起動に失敗: $e');
    return false;
  }
}

/// Web ページを「アプリの外に浮かぶ本物の窓」 として開く (= ユーザー要望:
/// フローティング AI を画面の外へ出したい)。
///
/// desktop_multi_window の「サブ窓」 は使えない。 サブ窓のエンジンには
/// webview_windows を登録していないため (登録するとサブ窓を閉じた後に本体でも
/// WebView を作れなくなる。 windows/runner/main.cpp のコメント参照)、 そこで
/// AI 画面を作ろうとすると MissingPluginException になる。
///
/// 代わりに**同じ実行ファイルをもう 1 プロセス起動**する。 OS から見て普通の
/// 窓なので画面のどこへでも動かせる。 WebView の保存先は実行ファイル基準で
/// 共有されるので、 本体でログイン済みならその状態のまま開く。
/// [pinned] = true なら、 開いた瞬間から「常に手前」 (= 他のアプリを
/// 触っていても前面に出たまま) にする (= ユーザー要望: フローティング AI は
/// ディアクティブでも前面に出るピン機能が欲しい)。
/// [title] を渡すと窓のタイトルに使う (URL の代わり)。
/// フローティング窓を「アプリの外」 へ出せない時の理由を返す (出せるなら null)。
///
/// = ユーザー要望: フローティングとアプリの外に出すを別のモードにしないで、
///   フローティングの時点で外に出せるように。 出せない時は理由を出す。
///
/// 出せるのは「パソコンで、 ふつうのウェブページ (http/https) を表示している窓」。
/// 電卓やストップウォッチのような画面、 端末内の動画ファイル、 スマホ版は
/// 別の窓を作れないので出せない。
String? popOutBlockedReason(MindMapProvider provider, String? url) {
  final isDesktop =
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
  if (!isDesktop) return provider.t('float.popOutDesktopOnly');
  final u = (url ?? '').trim();
  if (u.isEmpty) return provider.t('float.popOutNotWeb');
  if (!u.startsWith('http://') && !u.startsWith('https://')) {
    return provider.t('float.popOutLocalFile');
  }
  return null;
}

/// 今開いている「アプリ内フローティング窓」 を外の本物の窓へ変える処理の
/// 登録簿。 本体が最小化された時に全部呼んで、 フローティングだけ画面に残す
/// (= ユーザー要望)。 各フローティング窓が開く時に登録し、 閉じる時に外す。
final Set<Future<bool> Function()> _floatingPopOutHandlers = {};

bool openExternalWebWindow(String url,
    {bool pinned = false,
    String? title,
    // 掴んで外へ出した時に、 その場所・その大きさのまま出すための指定
    // (= ユーザー要望: フローティングをそのまま外へ出したい)。
    Rect? frame,
    // 本体の分割ペインの上に置いて放したら、 そのペインへ埋め込んで
    // 窓は閉じる (= ユーザー要望)。 要素から開いた動画の窓だけに付ける。
    bool embeddable = false}) {
  final isDesktop =
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
  final u = url.trim();
  if (!isDesktop || u.isEmpty) return false;
  unawaited(openExternalWebWindowPid(u,
      pinned: pinned, title: title, frame: frame, embeddable: embeddable));
  return true;
}

/// [openExternalWebWindow] の pid を返す版 (= 再押しで閉じるトグルのため)。
/// [position] は大きさは前回のまま、 場所だけ指定して開く
/// (= ユーザー要望: ボタンの近くに出す)。
/// 用途 (キー) ごとに開いている「外の窓」 のプロセス番号。
///
/// = ユーザー要望「押した度に window が立ち上がると一杯になってしまう」。
/// 同じ用途の窓が既に生きていれば、 新しく立ち上げずにそのままにする。
/// キーを省略した時は URL のホスト単位で 1 つ。
final Map<String, int> _externalWinPids = {};

/// その番号のプロセスがまだ生きているか。
///
/// ★ `Process.killPid` を存在確認に使ってはいけない。 Windows では
///   SIGTERM でも SIGKILL でも**本当に終了させてしまう**ので、 確認した
///   つもりで窓を閉じることになる。 外から覗く方法で調べる。
/// 前面に出したい窓を探す時の控え (EnumWindows の呼び出し先で使う)。
int _bringFrontTargetPid = 0;
int _bringFrontFoundHwnd = 0;

/// EnumWindows から 1 つずつ呼ばれる。 目的の PID の「表に出ている窓」 を
/// 見つけたら控えて打ち切る。
int _bringFrontEnumProc(int hwnd, int lParam) {
  try {
    final user32 = ffi.DynamicLibrary.open('user32.dll');
    final getPid = user32.lookupFunction<
        ffi.Int32 Function(ffi.IntPtr, ffi.Pointer<ffi.Uint32>),
        int Function(int, ffi.Pointer<ffi.Uint32>)>('GetWindowThreadProcessId');
    final isVisible = user32.lookupFunction<ffi.Int32 Function(ffi.IntPtr),
        int Function(int)>('IsWindowVisible');
    if (isVisible(hwnd) == 0) return 1;
    final buf = pkgffi.calloc<ffi.Uint32>();
    try {
      getPid(hwnd, buf);
      if (buf.value == _bringFrontTargetPid) {
        _bringFrontFoundHwnd = hwnd;
        return 0; // 見つかったので打ち切り
      }
    } finally {
      pkgffi.calloc.free(buf);
    }
  } catch (_) {}
  return 1;
}

/// 別プロセスで開いた窓 (フローティング) を前面に出す。
///
/// = ユーザー要望「フローティングの窓が後ろに隠れた後、 その項目を押したら
///   既に開いている窓が前面に出てくるように」。
/// 戻り値は「その窓が既に一番手前だったか」。 手前だった時は、 呼び出し元が
/// 今までどおり閉じる (トグル) 判断に使う。
bool bringExternalWindowToFront(int pid) {
  if (!Platform.isWindows) return false;
  try {
    final user32 = ffi.DynamicLibrary.open('user32.dll');
    final enumWindows = user32.lookupFunction<
        ffi.Int32 Function(
            ffi.Pointer<ffi.NativeFunction<ffi.Int32 Function(ffi.IntPtr, ffi.IntPtr)>>,
            ffi.IntPtr),
        int Function(
            ffi.Pointer<ffi.NativeFunction<ffi.Int32 Function(ffi.IntPtr, ffi.IntPtr)>>,
            int)>('EnumWindows');
    final showWindow = user32.lookupFunction<
        ffi.Int32 Function(ffi.IntPtr, ffi.Int32),
        int Function(int, int)>('ShowWindow');
    final setForeground = user32.lookupFunction<ffi.Int32 Function(ffi.IntPtr),
        int Function(int)>('SetForegroundWindow');
    final getForeground = user32.lookupFunction<ffi.IntPtr Function(),
        int Function()>('GetForegroundWindow');
    final isIconic = user32.lookupFunction<ffi.Int32 Function(ffi.IntPtr),
        int Function(int)>('IsIconic');

    _bringFrontTargetPid = pid;
    _bringFrontFoundHwnd = 0;
    final cb = ffi.Pointer.fromFunction<
        ffi.Int32 Function(ffi.IntPtr, ffi.IntPtr)>(_bringFrontEnumProc, 1);
    enumWindows(cb, 0);
    final hwnd = _bringFrontFoundHwnd;
    if (hwnd == 0) return false;
    final wasFront = getForeground() == hwnd && isIconic(hwnd) == 0;
    if (!wasFront) {
      if (isIconic(hwnd) != 0) showWindow(hwnd, 9); // SW_RESTORE
      setForeground(hwnd);
    }
    return wasFront;
  } catch (e) {
    debugPrint('窓を前面に出せませんでした: $e');
    return false;
  }
}

Future<bool> _externalWinAlive(int pid) async {
  try {
    if (Platform.isWindows) {
      final r = await Process.run('tasklist', ['/FI', 'PID eq $pid', '/NH']);
      return '${r.stdout}'.contains('$pid');
    }
    // POSIX の「シグナル 0」 = 届くかどうかだけ調べる。
    final r = await Process.run('kill', ['-0', '$pid']);
    return r.exitCode == 0;
  } catch (_) {
    return false;
  }
}

Future<int?> openExternalWebWindowPid(String url,
    {bool pinned = false,
    String? title,
    Rect? frame,
    Offset? position,
    bool embeddable = false,
    String? singleKey,
    bool single = true}) async {
  final isDesktop =
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
  final u = url.trim();
  if (!isDesktop || u.isEmpty) return null;
  // 同じ用途の窓が既に開いているなら、 もう 1 つ作らない。
  final key = singleKey ?? (Uri.tryParse(u)?.host ?? u);
  if (single) {
    final old = _externalWinPids[key];
    if (old != null) {
      if (await _externalWinAlive(old)) return old;
      _externalWinPids.remove(key);
    }
  }
  try {
    final proc = await Process.start(
      Platform.resolvedExecutable,
      [
        '--floating-web=${Uri.encodeComponent(u)}',
        if (pinned) '--floating-pin',
        if (embeddable) '--floating-embed',
        if (title != null && title.trim().isNotEmpty)
          '--floating-title=${Uri.encodeComponent(title.trim())}',
        if (frame != null) ...[
          '--floating-x=${frame.left.round()}',
          '--floating-y=${frame.top.round()}',
          '--floating-w=${frame.width.round()}',
          '--floating-h=${frame.height.round()}',
        ] else if (position != null) ...[
          '--floating-x=${position.dx.round()}',
          '--floating-y=${position.dy.round()}',
        ],
      ],
      mode: ProcessStartMode.detached,
    );
    if (single) _externalWinPids[key] = proc.pid;
    return proc.pid;
  } catch (e) {
    debugPrint('外の窓を開けませんでした: $e');
    return null;
  }
}

/// Markdown / Mermaid を書いて、 その場で描画を確認できるページ
/// (= ユーザー要望)。 pageType='markdown'。
///
/// 左に本文、 右に描画結果を並べる。 描画は WebView に
/// marked.js (Markdown) と mermaid.js (図) を読み込ませて行う。
/// 本文は prefs (markdown_<pageId>) に素のテキストで保存する。
/// Markdown 本文を埋め込んだプレビュー用 HTML。
/// marked (Markdown) と mermaid (図) を CDN から読み込む。
/// ネットに繋がらない時は、 素のテキストがそのまま出る。
/// Markdown ページと、 .md ファイルを開くテキストエディタの両方で使う
/// (= ユーザー要望: マークダウン形式を開いた時にもプレビュー機能)。
String _markdownPreviewHtml(String md, bool dark,
    {String markedSrc = 'https://cdn.jsdelivr.net/npm/marked/marked.min.js',
    String mermaidSrc =
        'https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js',
    String hljsSrc =
        'https://cdn.jsdelivr.net/gh/highlightjs/cdn-release@11/build/highlight.min.js',
    String? hljsCssSrc,
    String mathjaxSrc = 'https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-svg.js',
    String tocLabel = 'TOC',
    bool aiBridge = false,
    // = ユーザー要望: 文字の一部をリンクにして詳細へ飛べるように。
    //   押されたリンクを Flutter 側へ知らせる (図の道具ボタンとは別)。
    bool linkBridge = false,
    // 公開ページを「1 本の長い頁」 ではなくタブ切り替えにする
    // (= ユーザー要望: アプリの中と同じように分かれていてほしい)。
    List<({String name, String md})>? tabs,
    // 公開ページに「Markdown を保存」 を出すか (= ユーザー要望)。
    bool showDownload = false}) {
  final fg = dark ? '#E8EAF2' : '#16181D';
  final bg = dark ? '#14141F' : '#FFFFFF';
  final code = dark ? '#1E1E2E' : '#F3F4F8';
  final border = dark ? '#2E2E44' : '#DDE1EA';
  // 見出しや引用の飾りに使う色 (= ユーザー要望: もう少し飾りが欲しい)。
  final accent = dark ? '#BA68C8' : '#8E44AD';
  final strong = dark ? '#F3D9F8' : '#5B2C6F';
  final quote = dark ? '#B9C0D4' : '#4A5568';
  final thead = dark ? '#26263C' : '#EDEFF5';
  final theme = dark ? 'dark' : 'default';
  final hljsCss = hljsCssSrc ??
      (dark
          ? 'https://cdn.jsdelivr.net/gh/highlightjs/cdn-release@11/build/styles/github-dark.min.css'
          : 'https://cdn.jsdelivr.net/gh/highlightjs/cdn-release@11/build/styles/github.min.css');
  final src = jsonEncode(md);
  final toc = jsonEncode(tocLabel);
  final tabsJson = jsonEncode([
    for (final t in (tabs ?? const <({String name, String md})>[]))
      {'name': t.name, 'md': t.md}
  ]);
  // 公開ページだけに出す「Markdown を保存」 のボタン (= ユーザー要望)。
  //   同じ場所の ?dl=md を叩くとサーバーが .md を返す。 アプリ内の
  //   プレビューには出さない (file:// では意味が無いため)。
  final dlBtn = showDownload
      ? '<a id="mmdl" href="?dl=md" download>&#11015; Markdown</a>'
      : '';
  return '''<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<link rel="stylesheet" href="$hljsCss">
<style>
  body{margin:0;padding:18px 22px;background:$bg;color:$fg;
       font-family:"Yu Gothic UI","Meiryo","Segoe UI",sans-serif;
       font-size:14px;line-height:1.8;}
  /* ── 見出しを目立たせる (= ユーザー要望: 文字ばかりで味気ない) ── */
  h1{font-size:1.7em;margin:.6em 0 .5em;padding:0 0 8px;
     border-bottom:2px solid $accent;}
  /* 左の縦帯は読む邪魔になるので付けない (= ユーザー要望)。 */
  h2{font-size:1.32em;margin:1.4em 0 .5em;padding:0 0 6px;
     border-bottom:1px solid $border;}
  h3{font-size:1.12em;margin:1.2em 0 .4em;padding-bottom:4px;
     border-bottom:1px dashed $border;}
  h4{font-size:1em;margin:1em 0 .3em;color:$accent;}
  hr{border:none;border-top:1px solid $border;margin:22px 0;}
  strong{color:$strong;}
  ul,ol{padding-left:1.5em;}
  li{margin:.28em 0;}
  li::marker{color:$accent;}
  code{background:$code;padding:2px 5px;border-radius:4px;
       font-family:Consolas,monospace;font-size:12.5px;}
  pre{background:$code;padding:12px 14px;border-radius:8px;overflow-x:auto;
      border:1px solid $border;}
  pre code{background:none;padding:0;}
  table{border-collapse:collapse;margin:14px 0;width:auto;
        border-radius:8px;overflow:hidden;
        box-shadow:0 1px 3px rgba(0,0,0,.18);}
  th,td{border:1px solid $border;padding:8px 12px;}
  th{background:$thead;font-weight:700;}
  tbody tr:nth-child(even){background:$code;}
  blockquote{border-left:4px solid $accent;margin:14px 0;padding:8px 16px;
             background:$code;border-radius:0 8px 8px 0;color:$quote;}
  blockquote p{margin:.3em 0;}
  /* ── 図版 (= ユーザー要望: 必要に応じて画像も出す) ── */
  img{max-width:100%;border-radius:10px;display:block;margin:14px auto;
      box-shadow:0 2px 10px rgba(0,0,0,.28);}
  p>img:only-child{max-height:460px;object-fit:contain;}
  .mermaid{background:transparent;margin:14px 0;text-align:center;}
  /* ── Mermaid 図の拡大縮小 / 移動 (= ユーザー要望) ── */
  .mmwrap{position:relative;height:440px;border:1px solid $border;
          border-radius:10px;overflow:hidden;margin:14px 0;}
  .mmpane{position:absolute;left:0;top:0;transform-origin:0 0;cursor:grab;}
  .mmpane svg{display:block;max-width:none !important;}
  .mmctl{position:absolute;right:8px;top:8px;display:flex;gap:4px;z-index:5;}
  .mmctl button{min-width:28px;height:28px;border:1px solid $border;
          border-radius:6px;background:$code;color:$fg;font-size:13px;
          cursor:pointer;line-height:1;padding:0 6px;}
  .mmctl button:hover{filter:brightness(1.25);}
  /* 下端の境界をドラッグして表示領域を広げる (= ユーザー要望) */
  .mmresize{position:absolute;left:0;right:0;bottom:0;height:12px;
          cursor:ns-resize;z-index:6;display:flex;align-items:center;
          justify-content:center;}
  .mmresize::after{content:'';width:44px;height:4px;border-radius:2px;
          background:$border;opacity:.9;}
  .mmresize:hover::after{filter:brightness(1.4);}
  /* ── 目次 (= ユーザー要望: プレビューの発展) ── */
  #mmtoc{background:$code;border:1px solid $border;border-radius:10px;
         padding:10px 14px;margin:0 0 16px;}
  .mmtoc-title{font-weight:700;font-size:12px;margin-bottom:6px;
         color:#8890A6;}
  #mmtoc a{display:block;font-size:12.5px;color:$fg;opacity:.85;
         cursor:pointer;padding:2px 0;text-decoration:none;}
  #mmtoc a:hover{opacity:1;text-decoration:underline;}
  #mmtoc a.mmtoc-l2{padding-left:14px;}
  #mmtoc a.mmtoc-l3{padding-left:28px;}
  mjx-container svg{overflow:visible;}
  #err{color:#E57373;font-size:12px;white-space:pre-wrap;}
  /* 目次が長い時は中でスクロールさせる (= ユーザー報告: 目次が長すぎる) */
  #mmtoc{max-height:44vh;overflow:auto;}
  /* ── 公開ページのタブ (= ユーザー要望) ── */
  #mmtabs{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 16px;
          padding:0 0 10px;border-bottom:1px solid $border;}
  #mmtabs button{appearance:none;border:1px solid $border;background:$code;
          color:$fg;border-radius:999px;padding:6px 14px;font-size:13px;
          cursor:pointer;font-family:inherit;}
  #mmtabs button:hover{border-color:$accent;}
  #mmtabs button.on{background:$accent;border-color:$accent;color:#fff;
          font-weight:700;}
  /* ── Markdown を保存 (公開ページのみ) ── */
  #mmdl{position:fixed;right:14px;bottom:14px;z-index:40;
        display:inline-block;padding:8px 14px;border-radius:999px;
        background:$accent;color:#fff;text-decoration:none;font-size:12.5px;
        box-shadow:0 2px 10px rgba(0,0,0,.35);}
  #mmdl:hover{opacity:.9;}
  @media print{#mmdl{display:none;}}
</style></head><body>
$dlBtn
<div id="mmtabs" style="display:none"></div>
<div id="out"></div><div id="err"></div>
<script src="$markedSrc"></script>
<!-- ★ Mermaid は ESM (import) ではなく UMD 版を使う。
     loadStringContent / data: URI で開いたページはオリジンが特殊で、
     module の import が失敗して図が一切描画されないことがある。 -->
<script src="$mermaidSrc"></script>
<script src="$hljsSrc"></script>
<script>
window.MathJax = {
  tex: { inlineMath: [['\\\$', '\\\$'], ['\\\\(', '\\\\)']],
         displayMath: [['\\\$\\\$', '\\\$\\\$'], ['\\\\[', '\\\\]']] },
  svg: { fontCache: 'global' },
  options: { skipHtmlTags:
      ['script', 'noscript', 'style', 'textarea', 'pre', 'code'] },
  startup: { typeset: false }
};
</script>
<script src="$mathjaxSrc"></script>
<script>
(function () {
  var out = document.getElementById('out');
  var post = null;
  if (window.chrome && window.chrome.webview) {
    post = function (o) { window.chrome.webview.postMessage(o); };
  } else if (window.flutter_inappwebview) {
    post = function (o) {
      window.flutter_inappwebview.callHandler('mmbridge', JSON.stringify(o));
    };
  }
  // 図の道具ボタン (AI / 保存 / マップへ) を出すか。
  var bridge = ($aiBridge && post) ? { postMessage: post } : null;
  // リンクを押した時の通知を出すか (= ユーザー要望)。
  var linkPost = ($linkBridge && post) ? post : null;
  function esc(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
  }
  var mermaidInited = false;
  function ensureMermaid() {
    if (!window.mermaid || mermaidInited) return;
    mermaid.initialize({
      startOnLoad: false,
      theme: '$theme',
      securityLevel: 'loose'
    });
    mermaidInited = true;
  }
  // ── PNG 書き出し (svg → canvas)。 失敗時は null を返す ──
  function exportPng(svgText, w, h, cb) {
    try {
      var img = new Image();
      var blob = new Blob([svgText], { type: 'image/svg+xml;charset=utf-8' });
      var url = URL.createObjectURL(blob);
      img.onload = function () {
        try {
          var scale = 2;
          var c = document.createElement('canvas');
          c.width = Math.max(1, Math.round(w * scale));
          c.height = Math.max(1, Math.round(h * scale));
          var g = c.getContext('2d');
          g.fillStyle = '$bg';
          g.fillRect(0, 0, c.width, c.height);
          g.setTransform(scale, 0, 0, scale, 0, 0);
          g.drawImage(img, 0, 0, w, h);
          cb(c.toDataURL('image/png'));
        } catch (e) { cb(null); }
        URL.revokeObjectURL(url);
      };
      img.onerror = function () { URL.revokeObjectURL(url); cb(null); };
      img.src = url;
    } catch (e) { cb(null); }
  }
  // ── 図を「拡大縮小 + ドラッグ移動」 できる枠に入れる (= ユーザー要望) ──
  function makeInteractive(slot, svg, code) {
    slot.className = 'mermaid';
    slot.innerHTML =
      '<div class="mmwrap"><div class="mmpane">' + svg + '</div>' +
      '<div class="mmctl">' +
      (bridge
        ? '<button type="button" data-act="ai" title="AI">AI</button>' +
          '<button type="button" data-act="fix" title="AI fix">&#9998;</button>' +
          '<button type="button" data-act="copy" title="copy">&#10697;</button>' +
          '<button type="button" data-act="save" title="save PNG">&#8681;</button>' +
          '<button type="button" data-act="map" title="to map">&#9635;</button>'
        : '') +
      '<button type="button" data-act="in" title="zoom in">+</button>' +
      '<button type="button" data-act="out" title="zoom out">&#8722;</button>' +
      '<button type="button" data-act="reset" title="reset">&#8634;</button>' +
      '</div><div class="mmresize"></div></div>';
    var wrap = slot.querySelector('.mmwrap');
    var pane = slot.querySelector('.mmpane');
    var svgEl = pane.querySelector('svg');
    // ★ mermaid の svg は width:100% で親幅いっぱいに広がり、 縦長の図が
    //   巨大に描かれてしまう。 固有サイズ (max-width / viewBox) に固定して
    //   から拡大率を計算する。
    var intrinsic = 0;
    var mwStyle = svgEl.style && svgEl.style.maxWidth;
    if (mwStyle && mwStyle.indexOf('px') > 0) intrinsic = parseFloat(mwStyle);
    if (!intrinsic && svgEl.viewBox && svgEl.viewBox.baseVal) {
      intrinsic = svgEl.viewBox.baseVal.width;
    }
    if (intrinsic > 0) {
      svgEl.style.width = intrinsic + 'px';
      svgEl.style.maxWidth = 'none';
    }
    svgEl.style.height = 'auto';
    var s = 1, tx = 0, ty = 0;
    var userResized = false;
    function apply() {
      pane.style.transform =
          'translate(' + tx + 'px,' + ty + 'px) scale(' + s + ')';
    }
    function fit() {
      var w = wrap.clientWidth;
      var r = svgEl.getBoundingClientRect();
      var sw = r.width / s, sh = r.height / s;
      if (!sw || !sh) { s = 1; tx = 0; ty = 0; apply(); return; }
      // 幅に合わせてフィット。 最低 0.85 倍は保ち、 小さな図は 2 倍まで
      // 拡大 (= ユーザー要望: デフォルトの拡大率が小さすぎる)。
      s = Math.max(0.85, Math.min(2.0, (w - 24) / sw));
      if (!isFinite(s) || s <= 0) s = 1;
      if (!userResized) {
        wrap.style.height =
            Math.max(240, Math.min(620, sh * s + 30)) + 'px';
      }
      var h = wrap.clientHeight;
      tx = (w - sw * s) / 2;
      ty = (h >= sh * s) ? (h - sh * s) / 2 : 12;
      apply();
    }
    function zoomAt(px, py, factor) {
      var ns = Math.min(8, Math.max(0.15, s * factor));
      tx = px - (px - tx) * (ns / s);
      ty = py - (py - ty) * (ns / s);
      s = ns;
      apply();
    }
    apply();
    setTimeout(fit, 0);
    setTimeout(fit, 250);
    wrap.addEventListener('wheel', function (ev) {
      ev.preventDefault();
      var rect = wrap.getBoundingClientRect();
      zoomAt(ev.clientX - rect.left, ev.clientY - rect.top,
          ev.deltaY < 0 ? 1.15 : 1 / 1.15);
    }, { passive: false });
    var dragging = false, lx = 0, ly = 0;
    var resizing = false, rly = 0, rh = 0;
    wrap.addEventListener('mousedown', function (ev) {
      if (ev.target.closest('.mmctl')) return;
      if (ev.target.closest('.mmresize')) {
        resizing = true; userResized = true;
        rly = ev.clientY; rh = wrap.clientHeight;
        ev.preventDefault();
        return;
      }
      dragging = true; lx = ev.clientX; ly = ev.clientY;
      pane.style.cursor = 'grabbing';
      ev.preventDefault();
    });
    window.addEventListener('mousemove', function (ev) {
      if (resizing) {
        var nh = Math.max(160, Math.min(1400, rh + (ev.clientY - rly)));
        wrap.style.height = nh + 'px';
        return;
      }
      if (!dragging) return;
      tx += ev.clientX - lx; ty += ev.clientY - ly;
      lx = ev.clientX; ly = ev.clientY;
      apply();
    });
    window.addEventListener('mouseup', function () {
      resizing = false;
      dragging = false; pane.style.cursor = 'grab';
    });
    // ── 指の操作 (= ユーザー報告: スマホで図を左右に動かせない) ──
    //   1 本指でなぞると平行移動、 2 本指の開閉で拡大縮小。
    //   ブラウザの既定のスクロール/ズームに取られないよう、 図の上では
    //   touch-action を切って preventDefault する。
    wrap.style.touchAction = 'none';
    var tDrag = false, tlx = 0, tly = 0, pinch = 0;
    function tdist(t) {
      var dx = t[0].clientX - t[1].clientX;
      var dy = t[0].clientY - t[1].clientY;
      return Math.sqrt(dx * dx + dy * dy);
    }
    wrap.addEventListener('touchstart', function (ev) {
      if (ev.target.closest('.mmctl')) return;
      if (ev.target.closest('.mmresize')) {
        resizing = true; userResized = true;
        rly = ev.touches[0].clientY; rh = wrap.clientHeight;
        ev.preventDefault();
        return;
      }
      if (ev.touches.length === 1) {
        tDrag = true;
        tlx = ev.touches[0].clientX; tly = ev.touches[0].clientY;
        ev.preventDefault();
      } else if (ev.touches.length === 2) {
        tDrag = false;
        pinch = tdist(ev.touches);
        ev.preventDefault();
      }
    }, { passive: false });
    wrap.addEventListener('touchmove', function (ev) {
      if (resizing && ev.touches.length === 1) {
        var nh = Math.max(160,
            Math.min(1400, rh + (ev.touches[0].clientY - rly)));
        wrap.style.height = nh + 'px';
        ev.preventDefault();
        return;
      }
      if (ev.touches.length === 2) {
        var d = tdist(ev.touches);
        if (pinch > 0 && d > 0) {
          var rect = wrap.getBoundingClientRect();
          var cx = (ev.touches[0].clientX + ev.touches[1].clientX) / 2
              - rect.left;
          var cy = (ev.touches[0].clientY + ev.touches[1].clientY) / 2
              - rect.top;
          zoomAt(cx, cy, d / pinch);
        }
        pinch = d;
        ev.preventDefault();
        return;
      }
      if (!tDrag || ev.touches.length !== 1) return;
      tx += ev.touches[0].clientX - tlx;
      ty += ev.touches[0].clientY - tly;
      tlx = ev.touches[0].clientX; tly = ev.touches[0].clientY;
      apply();
      ev.preventDefault();
    }, { passive: false });
    wrap.addEventListener('touchend', function () {
      tDrag = false; pinch = 0; resizing = false;
    });
    wrap.addEventListener('touchcancel', function () {
      tDrag = false; pinch = 0; resizing = false;
    });
    wrap.querySelector('.mmctl').addEventListener('click', function (ev) {
      var b = ev.target.closest('button');
      if (!b) return;
      var act = b.getAttribute('data-act');
      var cw = wrap.clientWidth / 2, ch = wrap.clientHeight / 2;
      if (act === 'in') { zoomAt(cw, ch, 1.25); }
      else if (act === 'out') { zoomAt(cw, ch, 1 / 1.25); }
      else if (act === 'ai') {
        // 図の Mermaid ソースを Flutter (ブラウザ AI 欄) へ渡す。
        if (bridge) bridge.postMessage({ type: 'mermaidToAi', code: code });
      }
      else if (act === 'fix') {
        // AI 編集 (MCP) にこの図の修正を頼む (= ユーザー要望: 発展案)。
        if (bridge) bridge.postMessage({ type: 'mermaidFix', code: code });
      }
      else if (act === 'copy') {
        if (bridge) bridge.postMessage({ type: 'mermaidCopy', code: code });
      }
      else if (act === 'save' || act === 'map') {
        if (!bridge) return;
        var kind = (act === 'save') ? 'mermaidSave' : 'mermaidToMap';
        var rr = svgEl.getBoundingClientRect();
        var swN = Math.max(1, Math.round(rr.width / s));
        var shN = Math.max(1, Math.round(rr.height / s));
        var clone = svgEl.cloneNode(true);
        clone.setAttribute('width', swN);
        clone.setAttribute('height', shN);
        clone.style.maxWidth = ''; clone.style.width = '';
        clone.style.height = '';
        clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
        var svgText = new XMLSerializer().serializeToString(clone);
        exportPng(svgText, swN, shN, function (dataUrl) {
          if (dataUrl) {
            bridge.postMessage({ type: kind, png: dataUrl });
          } else {
            bridge.postMessage({ type: kind, svg: svgText });
          }
        });
      }
      else { userResized = false; fit(); }
    });
  }
  // ── 目次 (h1〜h3 から自動生成。 2 個未満なら出さない) ──
  // 見出しの頭に付いた絵文字や記号を目次では外す (= ユーザー要望:
  //   目次の先頭に変な絵文字が入る)。 本文の見出しはそのまま。
  function tocLabelOf(text) {
    var t = String(text || '');
    // 絵文字・記号・異体字セレクタ・囲み文字を頭から落とす。
    t = t.replace(
      /^(?:[\u2190-\u2BFF\u2600-\u27BF\uFE0E\uFE0F\u20E3\u3297\u3299]|\uD83C[\uDC00-\uDFFF]|\uD83D[\uDC00-\uDFFF]|\uD83E[\uDC00-\uDFFF]|\s)+/,
      '');
    return t.trim() || String(text || '').trim();
  }
  function buildToc() {
    var old = document.getElementById('mmtoc');
    if (old) old.remove();
    var hs = out.querySelectorAll('h1, h2, h3');
    if (hs.length < 2) return;
    // ★ 全部のタブを 1 頁にまとめると見出しが数十個になり、 目次だけで
    //   画面が埋まる (= ユーザー報告)。 多い時は浅い階層だけを出す。
    var deep = out.querySelectorAll('h1, h2, h3');
    var lim = 3;
    if (deep.length > 40) lim = 1;
    else if (deep.length > 18) lim = 2;
    var box = document.createElement('div');
    box.id = 'mmtoc';
    var html = '<div class="mmtoc-title">&#9776; ' + esc($toc) + '</div>';
    for (var i = 0; i < hs.length; i++) {
      var h = hs[i];
      h.id = 'mmh' + i;
      var lv = Number(h.tagName.substring(1));
      if (lv > lim) continue;
      html += '<a class="mmtoc-l' + lv + '" data-t="mmh' + i + '">' +
          esc(tocLabelOf(h.textContent)) + '</a>';
    }
    box.innerHTML = html;
    out.insertBefore(box, out.firstChild);
    box.addEventListener('click', function (ev) {
      var a = ev.target.closest('a');
      if (!a) return;
      var t = document.getElementById(a.getAttribute('data-t'));
      if (t) t.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  }
  function typesetMath() {
    if (window.MathJax && MathJax.typesetPromise) {
      try {
        if (MathJax.typesetClear) MathJax.typesetClear([out]);
        MathJax.typesetPromise([out]).catch(function () {});
      } catch (e) {}
    } else {
      // MathJax の起動が間に合っていない時のリトライ。
      setTimeout(function () {
        if (window.MathJax && MathJax.typesetPromise) {
          MathJax.typesetPromise([out]).catch(function () {});
        }
      }, 600);
    }
  }
  // ── 本体: マークダウン → HTML + mermaid + 目次 + ハイライト + 数式 ──
  // (window.__mmUpdate で分割プレビューからも再描画できる)
  function renderAll(src) {
    var blocks = [];
    function slotHtml(code) {
      blocks.push(String(code).trim());
      return '\\n\\n<div class="mermaid-slot" data-i="' +
          (blocks.length - 1) + '"></div>\\n\\n';
    }
    var kw = new RegExp('^\\\\s*(flowchart|graph|sequenceDiagram|' +
        'classDiagram|stateDiagram(?:-v2)?|erDiagram|gantt|pie\\\\b|' +
        'journey|mindmap|timeline|gitGraph|quadrantChart|' +
        'requirementDiagram|C4Context|sankey(?:-beta)?|' +
        'xychart(?:-beta)?|block-beta)\\\\b');
    var codeBlocks = [];
    var mathBlocks = [];
    // ① フェンス (``` / ~~~、 言語付き / なし) をすべて marked より先に
    //    取り出す。 mermaid (明示指定 or 図キーワードで始まる言語なし) は
    //    図スロットへ、 それ以外はコードスロットへ。 こうすると中身が
    //    marked の強調記法などに壊されない。
    var replaced = src.replace(
      /(`{3,}|~{3,})([^\\n]*)\\r?\\n([\\s\\S]*?)\\1/g,
      function (m, fence, lang, body) {
        var l = String(lang).trim().toLowerCase();
        if (l === 'mermaid' || (!l && kw.test(body))) return slotHtml(body);
        codeBlocks.push({ lang: l, text: body });
        return '\\n\\n<div class="code-slot" data-i="' +
            (codeBlocks.length - 1) + '"></div>\\n\\n';
      });
    // ② 数式 (\$\$…\$\$ / \$…\$) も marked より先に退避する
    //    (= 検証で発覚: \\int_0^x の _ が強調記法にされ Math input error)。
    replaced = replaced.replace(/\\\$\\\$([\\s\\S]+?)\\\$\\\$/g,
      function (m, body) {
        mathBlocks.push({ d: true, t: body });
        return '\\n\\n<div class="math-slot" data-i="' +
            (mathBlocks.length - 1) + '"></div>\\n\\n';
      });
    replaced = replaced.replace(/\\\$(\\S(?:[^\\\$\\n]*?\\S)?)\\\$/g,
      function (m, body, off, whole) {
        // \\\$ でエスケープされたものは数式にしない。
        if (off > 0 && whole.charAt(off - 1) === '\\\\') return m;
        mathBlocks.push({ d: false, t: body });
        return '<span class="math-slot" data-i="' +
            (mathBlocks.length - 1) + '"></span>';
      });
    out.innerHTML = (window.marked ? marked.parse(replaced) : replaced);
    // ③ コードブロックを戻す (エスケープ済みテキストとして挿入)。
    var cslots = out.querySelectorAll('.code-slot');
    for (var ci2 = 0; ci2 < cslots.length; ci2++) {
      var cs2 = cslots[ci2];
      var cb = codeBlocks[Number(cs2.getAttribute('data-i'))];
      if (!cb) continue;
      var pre = document.createElement('pre');
      var codeEl2 = document.createElement('code');
      if (cb.lang) codeEl2.className = 'language-' + cb.lang;
      codeEl2.textContent = String(cb.text).replace(/\\n\$/, '');
      pre.appendChild(codeEl2);
      cs2.parentNode.replaceChild(pre, cs2);
    }
    // ④ 数式を戻す (この後 MathJax が組版する)。
    var mslots = out.querySelectorAll('.math-slot');
    for (var mi = 0; mi < mslots.length; mi++) {
      var ms = mslots[mi];
      var mb = mathBlocks[Number(ms.getAttribute('data-i'))];
      if (!mb) continue;
      ms.textContent =
          mb.d ? ('\$\$' + mb.t + '\$\$') : ('\\\\(' + mb.t + '\\\\)');
    }
    // ── 目次 / シンタックスハイライト / 数式 (= ユーザー要望: 発展) ──
    buildToc();
    if (window.hljs) {
      var cs = out.querySelectorAll('pre > code');
      for (var ci = 0; ci < cs.length; ci++) {
        try { hljs.highlightElement(cs[ci]); } catch (e) {}
      }
    }
    typesetMath();
    var slots = out.querySelectorAll('.mermaid-slot');
    if (!slots.length) return;
    if (!window.mermaid) {
      for (var k = 0; k < slots.length; k++) {
        var bi = Number(slots[k].getAttribute('data-i'));
        slots[k].innerHTML = '<pre>' + esc(blocks[bi]) + '</pre>';
      }
      return;
    }
    ensureMermaid();
    // ── ラベルの中の括弧などで Parse error になるのを防ぐ ──
    //   例: B[営業管理 (Sales Cloud)] は mermaid が解釈できない。
    //   中身をそのまま二重引用符で包めば、 記号があっても通る。
    //   (= ユーザー報告: 生成した図が Parse error になる)
    // ★ この Dart 文字列は raw ではないので、 JS の正規表現の \\ は
    //   必ず 2 つ重ねる。 1 つだと Dart に食われて壊れた正規表現になり、
    //   スクリプト全体が構文エラーで死んでプレビューが真っ白になる
    //   (= ユーザー報告: プレビューが白いまま。 node --check で特定)。
    function fixMermaid(src) {
      try {
        var text = String(src);
        // 流れ図以外 (pie / sequence / gantt など) は [] の意味が違うので
        // 触らない。
        var head = text.replace(/^\\s+/, '').split(/\\s/)[0].toLowerCase();
        if (head !== 'graph' && head !== 'flowchart') return text;
        function quote(label) {
          return '"' + label.replace(/"/g, '″') + '"';
        }
        function risky(label) {
          if (/^\\s*"/.test(label)) return false;      // すでに包まれている
          if (/^\\s*[\\[\\(]/.test(label)) return false; // [[ ]] などの特殊な形
          return /[()（）:;,|<>#'"]/.test(label);
        }
        return text
          .replace(/([A-Za-z0-9_]+)\\[([^\\]\\n]*)\\]/g,
              function (m, id, label) {
            return risky(label) ? id + '[' + quote(label) + ']' : m;
          })
          .replace(/([A-Za-z0-9_]+)\\{([^}\\n]*)\\}/g,
              function (m, id, label) {
            return risky(label) ? id + '{' + quote(label) + '}' : m;
          });
      } catch (e) {
        return src;
      }
    }
    var idx = 0;
    function renderNext() {
      if (idx >= slots.length) return;
      var el = slots[idx];
      idx++;
      var i = Number(el.getAttribute('data-i'));
      try {
        mermaid.render('mm' + i + '_' + Date.now(), fixMermaid(blocks[i]))
          .then(function (r) {
            makeInteractive(el, r.svg, blocks[i]);
            renderNext();
          })
          .catch(function (e) {
            // 2 度目は元のまま試す (直しが裏目に出た時の保険)。
            try {
              mermaid.render('mmr' + i + '_' + Date.now(), blocks[i])
                .then(function (r2) {
                  makeInteractive(el, r2.svg, blocks[i]);
                  renderNext();
                })
                .catch(function (e2) {
                  el.innerHTML =
                      '<pre style="color:#E57373">' + esc(e2) + '</pre>' +
                      '<pre>' + esc(blocks[i]) + '</pre>';
                  renderNext();
                });
            } catch (e3) {
              el.innerHTML = '<pre style="color:#E57373">' + esc(e) + '</pre>' +
                  '<pre>' + esc(blocks[i]) + '</pre>';
              renderNext();
            }
          });
      } catch (e) {
        el.innerHTML = '<pre style="color:#E57373">' + esc(e) + '</pre>';
        renderNext();
      }
    }
    renderNext();
  }
  // ── リンク (= ユーザー要望: 文字の一部から詳細へ飛ぶ) ──
  //    `#見出し` は文書の中、 `tab:` は同じページの別タブ、 `page:` は
  //    アプリの別ページ、 http(s) は外のブラウザ。 いずれも既定の遷移
  //    (プレビューごと別のページへ飛んでしまう) は止める。
  document.addEventListener('click', function (ev) {
    var a = ev.target && ev.target.closest ? ev.target.closest('a') : null;
    if (!a) return;
    var href = a.getAttribute('href') || '';
    if (!href) return;
    if (href.charAt(0) === '#') {
      ev.preventDefault();
      var key = href.slice(1);
      try { key = decodeURIComponent(key); } catch (e) {}
      var hs = out.querySelectorAll('h1,h2,h3,h4,h5,h6');
      var want =
          String(key).trim().toLowerCase().replace(/[\\s\\u3000-]+/g, '');
      var hit = document.getElementById(href.slice(1));
      if (!hit) {
        for (var i = 0; i < hs.length; i++) {
          var t = String(hs[i].textContent).trim().toLowerCase()
              .replace(/[\\s\\u3000-]+/g, '');
          if (t === want || (want && t.indexOf(want) === 0)) {
            hit = hs[i];
            break;
          }
        }
      }
      if (hit) hit.scrollIntoView({ behavior: 'smooth', block: 'start' });
      return;
    }
    if (/^(tab|page|node):/i.test(href)) {
      ev.preventDefault();
      // 公開ページ (アプリの外) では、 tab: をその場の切り替えに使う。
      var mt = /^tab:(.*)\$/i.exec(href);
      if (mt && window.__mmShowTabByName &&
          window.__mmShowTabByName(mt[1])) {
        return;
      }
      if (linkPost) linkPost({ type: 'mdLink', href: href });
      return;
    }
    if (/^https?:/i.test(href)) {
      ev.preventDefault();
      if (linkPost) linkPost({ type: 'mdOpenUrl', href: href });
    }
  });
  // 分割プレビュー (編集しながら更新) 用の入口 (= ユーザー要望: 発展)。
  window.__mmUpdate = function (src) {
    try {
      renderAll(String(src));
    } catch (e) {
      document.getElementById('err').textContent = String(e);
    }
  };
  // ── タブ切り替え (= ユーザー要望: 公開ページもアプリの中と同じように
  //    ボタンで頁を切り替えたい)。 タブが 1 つ以下なら出さない。 ──
  var mmTabs = $tabsJson;
  var mmTabIdx = 0;
  function showTab(i) {
    if (!mmTabs || !mmTabs.length) return;
    if (i < 0 || i >= mmTabs.length) return;
    mmTabIdx = i;
    var bar = document.getElementById('mmtabs');
    var bs = bar.querySelectorAll('button');
    for (var k = 0; k < bs.length; k++) {
      if (k === i) bs[k].className = 'on';
      else bs[k].className = '';
    }
    try {
      renderAll(String(mmTabs[i].md));
    } catch (e) {
      document.getElementById('err').textContent = String(e);
    }
    window.scrollTo(0, 0);
  }
  window.__mmShowTabByName = function (name) {
    var want = String(name).trim();
    for (var i = 0; i < (mmTabs || []).length; i++) {
      if (String(mmTabs[i].name).trim() === want) { showTab(i); return true; }
    }
    return false;
  };
  if (mmTabs && mmTabs.length > 1) {
    var bar = document.getElementById('mmtabs');
    bar.style.display = 'flex';
    for (var ti = 0; ti < mmTabs.length; ti++) {
      (function (idx) {
        var b = document.createElement('button');
        b.textContent = String(mmTabs[idx].name || (idx + 1));
        b.addEventListener('click', function () { showTab(idx); });
        bar.appendChild(b);
      })(ti);
    }
  }
  try {
    if (mmTabs && mmTabs.length) showTab(0);
    else renderAll($src);
  } catch (e) {
    document.getElementById('err').textContent = String(e);
    out.textContent = $src;
  }
})();
</script></body></html>''';
}

/// マークダウンプレビューを file:// で開くための準備 (= ユーザー報告:
/// Mermaid の図が描画されない問題への対応)。
///
/// NavigateToString (loadStringContent) で開いたページは about:blank の
/// 特殊なオリジンになり、 環境によっては CDN の外部スクリプト読み込み自体が
/// 失敗して図が一切描画されない。 そこで:
///   1. 描画用 JS (marked / mermaid / highlight / MathJax) を同梱アセット
///      からアプリ内へ書き出し
///   2. プレビュー HTML を preview.html として書き出して
///   3. 通常のローカルファイル (file://) として開く。
/// ネットワークには依存せず、 オフラインでも描画できる。
/// marked / mermaid が用意できない時だけ null (= 呼び出し側が従来の
/// loadStringContent + CDN にフォールバックする)。
/// HTML プレビュー用に「明るい配色」 を明示した控えを作る。
///
/// WebView は暗いテーマを引き継ぐため、 背景色を指定していない HTML は
/// 真っ暗な地に白文字で表示されてしまう (= ユーザー報告)。 ブラウザで
/// 開いた時と同じ見た目になるよう `color-scheme: light` を差し込む。
/// 元のファイルには手を加えず、 プレビューの控えにだけ入れる。
/// 既に配色を指定している HTML はそのまま (書いた人の指定を尊重)。
String _htmlPreviewWithLightScheme(String src) {
  final lower = src.toLowerCase();
  if (lower.contains('color-scheme')) return src;
  const inject = '<meta name="color-scheme" content="light">'
      '<style>:root{color-scheme:light;}</style>';
  final headIdx = lower.indexOf('<head');
  if (headIdx >= 0) {
    final close = src.indexOf('>', headIdx);
    if (close > 0) {
      return '${src.substring(0, close + 1)}$inject${src.substring(close + 1)}';
    }
  }
  final htmlIdx = lower.indexOf('<html');
  if (htmlIdx >= 0) {
    final close = src.indexOf('>', htmlIdx);
    if (close > 0) {
      return '${src.substring(0, close + 1)}<head>$inject</head>'
          '${src.substring(close + 1)}';
    }
  }
  return '$inject$src';
}

Future<String?> _prepareMarkdownPreviewFile(String html,
    {String fileName = 'preview.html'}) async {
  try {
    final support = await getApplicationSupportDirectory();
    final sep = Platform.pathSeparator;
    final dir = Directory('${support.path}${sep}md_preview');
    await dir.create(recursive: true);

    // ── ① 同梱アセットから書き出す (= 確実。 ネットワーク不要) ──
    Future<bool> ensure(
        String name, String assetKey, String url, int minBytes) async {
      final f = File('${dir.path}$sep$name');
      try {
        if (await f.exists() && (await f.length()) > minBytes) return true;
      } catch (_) {}
      try {
        final data = await rootBundle.load(assetKey);
        if (data.lengthInBytes > minBytes) {
          await f.writeAsBytes(data.buffer.asUint8List(), flush: true);
          return true;
        }
      } catch (_) {}
      // ── ② 同梱に無い時だけネットワークから取る (保険) ──
      try {
        final res =
            await http.get(Uri.parse(url)).timeout(const Duration(seconds: 20));
        if (res.statusCode == 200 && res.bodyBytes.length > minBytes) {
          await f.writeAsBytes(res.bodyBytes, flush: true);
          return true;
        }
      } catch (_) {}
      try {
        return await f.exists() && (await f.length()) > minBytes;
      } catch (_) {
        return false;
      }
    }

    final okMarked = await ensure('marked.min.js', 'assets/js/marked.min.js',
        'https://cdn.jsdelivr.net/npm/marked/marked.min.js', 10000);
    final okMermaid = await ensure(
        'mermaid.min.js',
        'assets/js/mermaid.min.js',
        'https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js',
        100000);
    // ハイライト / 数式は無くてもページ側が自衛するので、 失敗は無視。
    await ensure('highlight.min.js', 'assets/js/highlight.min.js',
        'https://cdn.jsdelivr.net/gh/highlightjs/cdn-release@11/build/highlight.min.js',
        10000);
    await ensure('hljs-dark.css', 'assets/js/hljs-dark.css',
        'https://cdn.jsdelivr.net/gh/highlightjs/cdn-release@11/build/styles/github-dark.min.css',
        200);
    await ensure('hljs-light.css', 'assets/js/hljs-light.css',
        'https://cdn.jsdelivr.net/gh/highlightjs/cdn-release@11/build/styles/github.min.css',
        200);
    await ensure('tex-svg.js', 'assets/js/tex-svg.js',
        'https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-svg.js', 100000);
    if (!okMarked || !okMermaid) return null;
    final f = File('${dir.path}$sep$fileName');
    await f.writeAsString(html, flush: true);
    return Uri.file(f.path).toString();
  } catch (_) {
    return null;
  }
}

/// Markdown ページの中の 1 枚 (= ユーザー要望: 1 ページに何個もタブを
/// 作って色んな Markdown を書けるように)。
class _MdTab {
  String id;
  String name;
  String text;
  _MdTab({required this.id, required this.name, required this.text});

  Map<String, dynamic> toJson() => {'id': id, 'name': name, 'text': text};

  static _MdTab fromJson(Map<dynamic, dynamic> m) => _MdTab(
        id: '${m['id'] ?? ''}'.trim().isEmpty
            ? 'md${DateTime.now().microsecondsSinceEpoch}'
            : '${m['id']}',
        name: '${m['name'] ?? ''}',
        text: '${m['text'] ?? ''}',
      );
}

/// prefs (markdown_<pageId>) の中身を読む。
///
/// 旧い形は「素のテキスト 1 枚」 だったので、 JSON として読めない時は
/// そのまま 1 枚目のタブとして扱う (= 今までのページがそのまま開ける)。
({List<_MdTab> tabs, int sel}) decodeMarkdownDoc(String? raw) {
  if (raw == null || raw.isEmpty) return (tabs: <_MdTab>[], sel: 0);
  if (raw.trimLeft().startsWith('{')) {
    try {
      final j = jsonDecode(raw);
      if (j is Map && j['tabs'] is List) {
        final tabs = <_MdTab>[
          for (final e in (j['tabs'] as List))
            if (e is Map) _MdTab.fromJson(e)
        ];
        if (tabs.isNotEmpty) {
          final sel =
              ((j['sel'] as num?)?.toInt() ?? 0).clamp(0, tabs.length - 1);
          return (tabs: tabs, sel: sel);
        }
      }
    } catch (_) {
      // JSON に見えて違った → 本文として扱う。
    }
  }
  return (
    tabs: [
      _MdTab(
          id: 'md${DateTime.now().microsecondsSinceEpoch}',
          name: '1',
          text: raw)
    ],
    sel: 0
  );
}

String encodeMarkdownDoc(List<_MdTab> tabs, int sel) => jsonEncode({
      'v': 2,
      'sel': sel,
      'tabs': [for (final t in tabs) t.toJson()],
    });




/// 録っていない所を暗くする (= ユーザー要望: 部分録画中は外を暗く)。
class _RecDimPainter extends CustomPainter {
  final Rect hole;
  _RecDimPainter(this.hole);

  @override
  void paint(Canvas canvas, Size size) {
    final dim = Paint()..color = Colors.black.withValues(alpha: 0.45);
    canvas.save();
    canvas.clipRect(hole, clipOp: ui.ClipOp.difference);
    canvas.drawRect(Offset.zero & size, dim);
    canvas.restore();
    // 録っている範囲を赤い枠で示す。
    canvas.drawRect(
        hole,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 2
          ..color = const Color(0xFFE53935));
  }

  @override
  bool shouldRepaint(_RecDimPainter old) => old.hole != hole;
}

/// 語のまとまりの途中で改行されないようにする (= ユーザー要望:
/// 「要素」 が「要 / 素」、 「返す」 が「返 / す」 に割れて読みづらい)。
///
/// Flutter は日本語をどの文字の間でも折り返すので、 まとまりの内側へ
/// WORD JOINER (U+2060) を挟んで折れないようにする。
/// まとまりの見つけ方 (ざっくりで十分):
///   ・英数字の並び            → 1 かたまり
///   ・漢字の並び + 続く送り仮名 → 1 かたまり (「返す」「並べ替える」)
///   ・カタカナの並び          → 1 かたまり
///   ・記号・句読点            → そこで切れてよい
/// [maxRun] より長いまとまりは、 折れないと画面からはみ出すので対象外
/// (= ユーザー要望: 用語が長すぎる場合は例外)。
/// 数式・コード片が行の途中で割れないようにする (= ユーザー要望:
/// 「配列 a」 や |a[i] - M| のような並びの途中で折り返さない)。
///
/// ・記号を含む ASCII の連なりは、 間の空白ごと 1 かたまりにする
///   (空白を「折り返さない空白」 U+00A0 に置き換える)。 長すぎる連なりは
///   1 行に収まらないので対象外。
/// ・「配列 a」「先頭 N 個」 のように、 日本語の語のすぐ後ろに続く
///   短い ASCII も繋ぐ (語と記号・変数名の間で折れないように)。
String fcKeepFormulas(String text) {
  if (text.isEmpty) return text;
  // コードや表はそのまま (等幅で別に描いている)。
  if (text.contains('```') || text.contains('\n|')) return text;
  var s =
      text.replaceAllMapped(RegExp(r'[\x21-\x7E]+(?: [\x21-\x7E]+)+'), (m) {
    final run = m[0]!;
    if (run.length > 40 ||
        !RegExp(r'[\[\]\(\)\{\}|=+\-*/<>_^\\$]').hasMatch(run)) {
      return run;
    }
    return run.replaceAll(' ', ' ');
  });
  s = s.replaceAllMapped(
      RegExp(r'([぀-ヿ一-鿿]) ([\x21-\x7E ]{1,16})'),
      (m) => '${m[1]} ${m[2]}');
  return s;
}

/// 行頭・行末に来てはいけない文字で折り返さないようにする (禁則処理)。
///
/// ・閉じ括弧や句読点は行頭に置かない → 直前の文字と繋ぐ
/// ・開き括弧は行末に置かない → 直後の文字と繋ぐ
/// (= ユーザー報告: 「…において / ）」 のように変な位置で改行が入る)
String jpKinsoku(String text) {
  if (text.isEmpty) return text;
  if (text.contains('```') || text.contains('\n|')) return text;
  const joiner = '\u2060'; // WORD JOINER (見えない・折り返し禁止)
  // 行頭に来てほしくない文字。
  const notLineStart = '）)」』】〉》〕］]｝}、。，．・：；！？!?ー…';
  // 行末に来てほしくない文字。
  const notLineEnd = '（(「『【〈《〔［[｛{';
  final runes = text.runes.toList();
  final out = StringBuffer();
  for (var i = 0; i < runes.length; i++) {
    final ch = String.fromCharCode(runes[i]);
    if (i > 0 && notLineStart.contains(ch)) out.write(joiner);
    out.write(ch);
    if (i < runes.length - 1 && notLineEnd.contains(ch)) out.write(joiner);
  }
  return out.toString();
}

String jpKeepWords(String text, {int maxRun = 12}) {
  if (text.isEmpty) return text;
  // コードや表はそのまま (等幅で別に描いている)。
  if (text.contains('```') || text.contains('\n|')) return text;
  const joiner = '⁠';
  bool isKanji(int c) => c >= 0x4E00 && c <= 0x9FFF;
  bool isHira(int c) => c >= 0x3040 && c <= 0x309F;
  bool isKata(int c) => (c >= 0x30A0 && c <= 0x30FF) || c == 0x30FC;
  bool isAlnum(int c) =>
      (c >= 0x30 && c <= 0x39) ||
      (c >= 0x41 && c <= 0x5A) ||
      (c >= 0x61 && c <= 0x7A) ||
      c == 0x5F;
  // 助詞は語の一部ではないので、 ここで切れてよい (「配列の要素」 は
  // 「配列 / の要素」 のように折り返せる)。
  const particles = 'のをにはがへともやかでねよ';
  bool isParticle(int c) => particles.contains(String.fromCharCode(c));

  final runes = text.runes.toList();
  final out = StringBuffer();
  var i = 0;
  while (i < runes.length) {
    final c = runes[i];
    var end = i + 1;
    if (isAlnum(c)) {
      while (end < runes.length && isAlnum(runes[end])) {
        end++;
      }
    } else if (isKata(c)) {
      while (end < runes.length && isKata(runes[end])) {
        end++;
      }
    } else if (isHira(c) && !isParticle(c)) {
      // 短い平仮名の並びは 1 かたまり (= ユーザー報告: 「において」 の
      // 途中で改行される)。 長い並びは折れないと画面からはみ出すので、
      // 5 文字までに留める。 助詞から始まる並びはそこで切ってよい。
      var n = 1;
      while (end < runes.length && isHira(runes[end]) && n < 5) {
        end++;
        n++;
      }
    } else if (isKanji(c)) {
      // 漢字の並び + 送り仮名 を繰り返し繋ぐ (「並べ替える」「書き込む」)。
      while (end < runes.length) {
        while (end < runes.length && isKanji(runes[end])) {
          end++;
        }
        var okuri = 0;
        while (end < runes.length &&
            isHira(runes[end]) &&
            !isParticle(runes[end]) &&
            okuri < 2) {
          end++;
          okuri++;
        }
        // 次がまた漢字なら同じ語の続きとみなす。 そうでなければ終わり。
        if (end < runes.length && isKanji(runes[end]) && end - i < maxRun) {
          continue;
        }
        break;
      }
    }
    final len = end - i;
    for (var k = i; k < end; k++) {
      out.writeCharCode(runes[k]);
      // まとまりの内側にだけ挟む。 長すぎる時は挟まない (はみ出し防止)。
      if (len > 1 && len <= maxRun && k < end - 1) out.write(joiner);
    }
    i = end;
  }
  return out.toString();
}

/// 録画中を示す赤い点 (= ユーザー要望: 録画画面らしく)。
