/// 録る範囲を選ぶ画面 (= ユーザー要望: 録画する範囲を指定できるように)。
///
/// デスクトップを 1 枚撮って写し、 その上をドラッグしてもらう。
/// 返り値が null なら取り消し、 範囲が null の結果なら画面全体。
class _ScreenRecRegionDialog extends StatefulWidget {
  final MindMapProvider provider;
  final Uint8List shot;
  final int vx;
  final int vy;
  final int vw;
  final int vh;
  final ScreenRecRegion? initial;
  const _ScreenRecRegionDialog({
    required this.provider,
    required this.shot,
    required this.vx,
    required this.vy,
    required this.vw,
    required this.vh,
    this.initial,
  });

  @override
  State<_ScreenRecRegionDialog> createState() => _ScreenRecRegionDialogState();
}

class _ScreenRecRegionDialogState extends State<_ScreenRecRegionDialog> {
  Offset? _dragFrom;
  Offset? _dragTo;
  Size _viewSize = Size.zero;

  /// 表示上の矩形 → 画面の物理ピクセルの矩形。
  ScreenRecRegion? _toRegion() {
    final a = _dragFrom, b = _dragTo;
    if (a == null || b == null || _viewSize.width <= 0) return null;
    final sx = widget.vw / _viewSize.width;
    final sy = widget.vh / _viewSize.height;
    final l = math.min(a.dx, b.dx) * sx;
    final t = math.min(a.dy, b.dy) * sy;
    final r = math.max(a.dx, b.dx) * sx;
    final bo = math.max(a.dy, b.dy) * sy;
    final w = (r - l).round();
    final h = (bo - t).round();
    if (w < 16 || h < 16) return null;
    return ScreenRecRegion(
        widget.vx + l.round(), widget.vy + t.round(), w, h).evened();
  }

  @override
  Widget build(BuildContext context) {
    final p = widget.provider;
    final region = _toRegion();
    return Dialog(
      backgroundColor: const Color(0xFF1A1A2E),
      insetPadding: const EdgeInsets.all(24),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 900, maxHeight: 720),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 8, 6),
            child: Row(children: [
              const Icon(Icons.crop_rounded,
                  color: Color(0xFF9575CD), size: 19),
              const SizedBox(width: 8),
              Expanded(
                child: Text(p.t('ve.recRegionTitle'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 15,
                        fontWeight: FontWeight.w700)),
              ),
              IconButton(
                icon: const Icon(Icons.close_rounded,
                    color: Colors.white54, size: 20),
                onPressed: () => Navigator.pop(context),
              ),
            ]),
          ),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: Text(p.t('ve.recRegionHint'),
                style: const TextStyle(color: Colors.white54, fontSize: 12)),
          ),
          const SizedBox(height: 10),
          Flexible(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: AspectRatio(
                aspectRatio: widget.vw / widget.vh,
                child: LayoutBuilder(builder: (ctx, c) {
                  _viewSize = Size(c.maxWidth, c.maxHeight);
                  return GestureDetector(
                    onPanStart: (d) => setState(() {
                      _dragFrom = d.localPosition;
                      _dragTo = d.localPosition;
                    }),
                    onPanUpdate: (d) =>
                        setState(() => _dragTo = d.localPosition),
                    child: Stack(children: [
                      Positioned.fill(
                        child: Image.memory(widget.shot, fit: BoxFit.fill,
                            gaplessPlayback: true),
                      ),
                      // 選んでいない所を暗くして、 選んだ所だけ明るく残す。
                      if (_dragFrom != null && _dragTo != null)
                        Positioned.fill(
                          child: CustomPaint(
                            painter: _RecRegionPainter(_dragFrom!, _dragTo!),
                          ),
                        ),
                    ]),
                  );
                }),
              ),
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 10, 16, 12),
            child: Row(children: [
              Expanded(
                child: Text(
                    region == null
                        ? p.t('ve.recRegionWhole')
                        : '${region.width} x ${region.height}  '
                            '(+${region.x}, +${region.y})',
                    style: const TextStyle(
                        color: Color(0xFF9CCC65), fontSize: 12.5)),
              ),
              TextButton(
                onPressed: () => setState(() {
                  _dragFrom = null;
                  _dragTo = null;
                }),
                child: Text(p.t('ve.recRegionReset'),
                    style: const TextStyle(color: Colors.white54)),
              ),
              const SizedBox(width: 4),
              // 範囲を選んでいなければ画面全体で録る。
              ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF9575CD),
                    foregroundColor: Colors.white),
                icon: const Icon(Icons.fiber_manual_record_rounded, size: 16),
                label: Text(p.t('ve.recStart')),
                onPressed: () =>
                    Navigator.pop(context, (region: region, ok: true)),
              ),
            ]),
          ),
        ]),
      ),
    );
  }
}

class _RecRegionPainter extends CustomPainter {
  final Offset a;
  final Offset b;
  _RecRegionPainter(this.a, this.b);

  @override
  void paint(Canvas canvas, Size size) {
    final r = Rect.fromPoints(a, b);
    final dim = Paint()..color = Colors.black.withValues(alpha: 0.55);
    // 選んだ所以外を暗くする。
    canvas.save();
    canvas.clipRect(r, clipOp: ui.ClipOp.difference);
    canvas.drawRect(Offset.zero & size, dim);
    canvas.restore();
    canvas.drawRect(
        r,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 2
          ..color = const Color(0xFF9575CD));
  }

  @override
  bool shouldRepaint(_RecRegionPainter old) => old.a != a || old.b != b;
}

/// 撮り終わった画面録画をその場で確かめるプレビュー
/// (= ユーザー要望: 動画を撮り終わった後にプレビュー画面を出すか選べるように)。
///
/// 再生は video_player (デスクトップは fvp バックエンド)。 断片化 mp4 なので
/// 撮った直後でもそのまま再生できる。
class _ScreenRecPreviewDialog extends StatefulWidget {
  final MindMapProvider provider;
  final String path;
  const _ScreenRecPreviewDialog({required this.provider, required this.path});

  @override
  State<_ScreenRecPreviewDialog> createState() =>
      _ScreenRecPreviewDialogState();
}

class _ScreenRecPreviewDialogState extends State<_ScreenRecPreviewDialog> {
  VideoPlayerController? _vc;
  bool _failed = false;

  @override
  void initState() {
    super.initState();
    // ignore: discarded_futures
    _init();
  }

  Future<void> _init() async {
    try {
      final vc = VideoPlayerController.file(File(widget.path));
      await vc.initialize();
      if (!mounted) {
        await vc.dispose();
        return;
      }
      vc.addListener(_onTick);
      setState(() => _vc = vc);
      await vc.play();
    } catch (_) {
      if (mounted) setState(() => _failed = true);
    }
  }

  void _onTick() {
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
    _vc?.removeListener(_onTick);
    // ignore: discarded_futures
    _vc?.dispose();
    super.dispose();
  }

  String _fmt(Duration d) {
    final m = d.inMinutes.toString().padLeft(2, '0');
    final s = (d.inSeconds % 60).toString().padLeft(2, '0');
    return '$m:$s';
  }

  @override
  Widget build(BuildContext context) {
    final p = widget.provider;
    final vc = _vc;
    final ready = vc != null && vc.value.isInitialized;
    final dur = ready ? vc.value.duration : Duration.zero;
    final pos = ready ? vc.value.position : Duration.zero;
    final ratio = ready &&
            vc.value.aspectRatio.isFinite &&
            vc.value.aspectRatio > 0.1
        ? vc.value.aspectRatio
        : 16 / 9;
    return Dialog(
      backgroundColor: const Color(0xFF1A1A2E),
      insetPadding: const EdgeInsets.all(24),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 860, maxHeight: 680),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 8, 6),
            child: Row(children: [
              const Icon(Icons.movie_rounded,
                  color: Color(0xFF9575CD), size: 19),
              const SizedBox(width: 8),
              Expanded(
                child: Text(p.t('ve.recPreviewTitle'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 15,
                        fontWeight: FontWeight.w700)),
              ),
              IconButton(
                icon: const Icon(Icons.close_rounded,
                    color: Colors.white54, size: 20),
                onPressed: () => Navigator.pop(context),
              ),
            ]),
          ),
          Flexible(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: _failed
                  ? Padding(
                      padding: const EdgeInsets.all(24),
                      child: Text(
                          '${p.t('ve.screenRecSaved')}\n${widget.path}',
                          style: const TextStyle(
                              color: Colors.white70, fontSize: 12.5)),
                    )
                  : !ready
                      ? const Padding(
                          padding: EdgeInsets.all(48),
                          child: CircularProgressIndicator(
                              color: Color(0xFF9575CD)),
                        )
                      : AspectRatio(
                          aspectRatio: ratio,
                          child: ColoredBox(
                            color: Colors.black,
                            child: VideoPlayer(vc),
                          ),
                        ),
            ),
          ),
          if (ready)
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 4, 12, 0),
              child: Row(children: [
                IconButton(
                  icon: Icon(
                      vc.value.isPlaying
                          ? Icons.pause_rounded
                          : Icons.play_arrow_rounded,
                      color: Colors.white,
                      size: 26),
                  onPressed: () {
                    if (vc.value.isPlaying) {
                      // ignore: discarded_futures
                      vc.pause();
                    } else {
                      // ignore: discarded_futures
                      vc.play();
                    }
                  },
                ),
                Text(_fmt(pos),
                    style: const TextStyle(
                        color: Colors.white70,
                        fontSize: 11.5,
                        fontFeatures: [FontFeature.tabularFigures()])),
                Expanded(
                  child: Slider(
                    value: dur.inMilliseconds <= 0
                        ? 0
                        : pos.inMilliseconds
                            .clamp(0, dur.inMilliseconds)
                            .toDouble(),
                    max: math.max(1, dur.inMilliseconds).toDouble(),
                    activeColor: const Color(0xFF9575CD),
                    inactiveColor: Colors.white24,
                    onChanged: (v) {
                      // ignore: discarded_futures
                      vc.seekTo(Duration(milliseconds: v.round()));
                    },
                  ),
                ),
                Text(_fmt(dur),
                    style: const TextStyle(
                        color: Colors.white70,
                        fontSize: 11.5,
                        fontFeatures: [FontFeature.tabularFigures()])),
              ]),
            ),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),
            child: Row(children: [
              Expanded(
                child: Text(widget.path,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: Colors.white38, fontSize: 10.5)),
              ),
              TextButton.icon(
                icon: const Icon(Icons.folder_open_rounded,
                    size: 16, color: Color(0xFF9CCC65)),
                label: Text(p.t('ve.screenRecOpenFolder'),
                    style: const TextStyle(
                        color: Color(0xFF9CCC65), fontSize: 12)),
                onPressed: () {
                  try {
                    Process.run('explorer',
                        ['/select,', widget.path.replaceAll('/', '\\')]);
                  } catch (_) {}
                },
              ),
              const SizedBox(width: 4),
              TextButton(
                onPressed: () => Navigator.pop(context),
                child: Text(p.t('btn.close'),
                    style: const TextStyle(color: Colors.white54)),
              ),
            ]),
          ),
        ]),
      ),
    );
  }
}


/// 生成結果を見た目で確かめるための、 使い捨てのプレビュー。
/// (= ユーザー要望: 置き換える前にプレビューで確認する)
class _MarkdownConfirmPreview extends StatefulWidget {
  final String html;
  // 直した内容で描き直すため、 呼ぶ側が鍵を渡せるようにする。
  const _MarkdownConfirmPreview({super.key, required this.html});

  @override
  State<_MarkdownConfirmPreview> createState() =>
      _MarkdownConfirmPreviewState();
}

class _MarkdownConfirmPreviewState extends State<_MarkdownConfirmPreview> {
  wv_win.WebviewController? _win;
  bool _ready = false;
  bool _failed = false;

  bool get _isDesktop =>
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);

  @override
  void initState() {
    super.initState();
    if (_isDesktop) unawaited(_init());
  }

  Future<void> _init() async {
    try {
      final c = wv_win.WebviewController();
      await c.initialize().timeout(const Duration(seconds: 12));
      await c.setBackgroundColor(const Color(0xFF14141F));
      if (!mounted) {
        await c.dispose();
        return;
      }
      // 本文側のプレビューと同じファイルを奪い合わないよう名前を分ける。
      final url = await _prepareMarkdownPreviewFile(widget.html,
          fileName: 'preview_confirm.html');
      if (url != null) {
        await c.loadUrl(url);
      } else {
        await c.loadStringContent(widget.html);
      }
      if (!mounted) {
        await c.dispose();
        return;
      }
      setState(() {
        _win = c;
        _ready = true;
      });
    } catch (_) {
      if (mounted) setState(() => _failed = true);
    }
  }

  @override
  void dispose() {
    try {
      _win?.dispose();
    } catch (_) {}
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (_ready && _win != null) {
      return ColoredBox(
          color: const Color(0xFF14141F), child: wv_win.Webview(_win!));
    }
    if (_failed || !_isDesktop) {
      // WebView が使えない環境では書式のままでも確かめられる。
      return const ColoredBox(color: Color(0xFF14141F));
    }
    return const ColoredBox(
      color: Color(0xFF14141F),
      child: Center(
        child: SizedBox(
            width: 22,
            height: 22,
            child: CircularProgressIndicator(
                strokeWidth: 2, color: Color(0xFFBA68C8))),
      ),
    );
  }
}

/// Markdown の下書き置き場 (= ユーザー要望: 下書きはタブに埋め込まず、
/// 下書きのまま保存して後から呼び出し、 直してから反映できるように)。
/// prefs `markdown_drafts_<pageId>` に JSON で持つ。
class _MarkdownDraftStore {
  static String _key(String pageId) => 'markdown_drafts_$pageId';

  static Future<List<({String name, String text, String at})>> load(
      String pageId) async {
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString(_key(pageId));
      if (raw == null || raw.isEmpty) return [];
      final arr = jsonDecode(raw);
      if (arr is! List) return [];
      return [
        for (final e in arr)
          if (e is Map)
            (
              name: '${e['name'] ?? ''}',
              text: '${e['text'] ?? ''}',
              at: '${e['at'] ?? ''}',
            )
      ];
    } catch (_) {
      return [];
    }
  }

  static Future<void> _save(
      String pageId, List<({String name, String text, String at})> list) async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(
          _key(pageId),
          jsonEncode([
            for (final d in list)
              {'name': d.name, 'text': d.text, 'at': d.at}
          ]));
    } catch (_) {}
  }

  static Future<void> add(String pageId, String name, String text) async {
    final list = await load(pageId);
    list.insert(
        0,
        (
          name: name,
          text: text,
          at: DateTime.now().toIso8601String(),
        ));
    // 溜まりすぎないよう 50 件まで。
    await _save(pageId, list.length > 50 ? list.sublist(0, 50) : list);
  }

  /// 同じ名前の下書きを差し替える (無ければ足す)。
  static Future<void> replace(
      String pageId, String name, String text) async {
    final list = await load(pageId);
    final at = list.indexWhere((d) => d.name == name);
    final item =
        (name: name, text: text, at: DateTime.now().toIso8601String());
    if (at >= 0) {
      list[at] = item;
    } else {
      list.insert(0, item);
    }
    await _save(pageId, list);
  }

  static Future<void> removeAt(String pageId, int i) async {
    final list = await load(pageId);
    if (i < 0 || i >= list.length) return;
    list.removeAt(i);
    await _save(pageId, list);
  }
}

class _MarkdownPageView extends StatefulWidget {
  final MindMapProvider provider;
  final String pageId;

  /// ファイルから中身の文字を取り出す係 (= ユーザー要望: txt や PDF を
  /// 読み込ませて Markdown を作る)。 画面側の実装を借りる。
  final Future<String?> Function(String path, String ext)? extractText;

  /// 添付ファイル (.md) を開いている時のパス (= ユーザー要望: ギャラリーや
  /// マップに埋め込んだ Markdown も、 Markdown ページと同じ画面で開く)。
  /// null なら従来どおり prefs (markdown_<pageId>) に保存する。
  /// 指定時は本文をこのファイルへ読み書きし、 タブは 1 枚に固定する。
  final String? filePath;

  /// ファイルへ保存した時に呼ぶ (ノードのサムネイル更新など)。
  final VoidCallback? onSaved;

  /// 「他のページに追加」 で、 書き出した .md をノードとして埋め込む係
  /// (= ユーザー要望)。 画面側の _embedFileAsNode を借りる。
  final String? Function(String path, String fileName, {String? pageId})?
      onEmbedToPage;

  /// AI チャット欄からブラウザ AI (外の窓の ChatGPT など) を開く係
  /// (= ユーザー要望: API キー式だけでなくブラウザ版も開けるように)。
  final VoidCallback? onOpenBrowserAi;
  const _MarkdownPageView(
      {super.key,
      required this.provider,
      required this.pageId,
      this.extractText,
      this.filePath,
      this.onSaved,
      this.onEmbedToPage,
      this.onOpenBrowserAi});
  @override
  State<_MarkdownPageView> createState() => _MarkdownPageViewState();
}

class _MarkdownPageViewState extends State<_MarkdownPageView> {
  final TextEditingController _ctrl = TextEditingController();

  /// 添付ファイルを開いているか (= 保存先がファイル)。
  bool get _fileMode => widget.filePath != null;

  // ── 左右のパネル (= ユーザー要望: メモと AI チャット欄をこの画面にも) ──
  bool _memoOpen = false;
  bool _aiChatOpen = false;
  final TextEditingController _sideMemoCtrl = TextEditingController();
  Timer? _sideMemoDebounce;
  final List<({String role, String text})> _sideAiChat = [];
  final TextEditingController _sideAiInput = TextEditingController();
  final ScrollController _sideAiScroll = ScrollController();
  bool _sideAiBusy = false;
  String get _kMdSideMemoKey => 'md_sidememo_${widget.pageId}';

  // ── タブ (= ユーザー要望: 1 ページに何個もタブを作れるように) ──
  final List<_MdTab> _tabs = [];
  int _sel = 0;
  final ScrollController _tabScroll = ScrollController();

  /// タブの列にカーソルが乗っているか (= ユーザー要望: スクロールバーは
  /// ホバーした時だけ出す)。
  bool _tabStripHover = false;

  _MdTab? get _cur => (_sel >= 0 && _sel < _tabs.length) ? _tabs[_sel] : null;

  /// 入力欄の今の内容を、 開いているタブへ書き戻す。
  void _syncCurrentTab() {
    final c = _cur;
    if (c != null) c.text = _ctrl.text;
  }
  Timer? _saveDebounce;
  Timer? _renderDebounce;
  bool _loaded = false;
  bool _aiBusy = false;

  /// 表示の仕方 (= ユーザー要望: プレビューだけのモードも作る)。
  ///   'split'   … 本文とプレビューを並べる (既定)
  ///   'preview' … プレビューだけ
  ///   'editor'  … 本文だけ
  String _viewMode = 'split';
  static const String _kMdViewModeKey = 'markdownViewMode';

  /// 並べる時、 プレビューを左に置くか (= ユーザー要望: 左にプレビュー、
  /// 右に編集画面もできるように)。 既定は本文が左。
  bool _previewLeft = false;
  static const String _kMdPreviewLeftKey = 'markdownPreviewLeft';

  /// ヘッダー (ツールバー) を隠しているか (= ユーザー要望)。
  bool _headerHidden = false;

  // ── ネットへの公開 (= ユーザー要望: プレビュー画面をサーバーに公開) ──
  /// 公開中の URL (空 = 公開していない)。
  String _publishedUrl = '';

  /// 公開中の id (差し替え / 取り消しに使う)。
  String _publishedId = '';

  /// 失効時刻 (秒)。 0 = 不明。
  int _publishedExpiresAt = 0;

  /// 前に選んだ公開の長さ (時間)。 次もこれを既定にする。
  /// = ユーザー要望: 1 か月以内なら時間単位で細かく決めたい。
  int _publishHours = 24 * 7;

  /// 日数での言い方 (控えの持ち回りに使う)。
  int get _publishDays => (_publishHours / 24).ceil().clamp(1, 30);

  /// 閲覧のパスワード (空 = 誰でも読める)。
  String _publishPassword = '';

  /// 「7 日 3 時間」 のような言い方にする。
  String _publishSpanText(MindMapProvider provider, int hours) {
    final d = hours ~/ 24;
    final h = hours % 24;
    if (d > 0 && h > 0) {
      return provider
          .t('pub.spanDayHour')
          .replaceFirst('{d}', '$d')
          .replaceFirst('{h}', '$h');
    }
    if (d > 0) return provider.t('pub.days').replaceFirst('{n}', '$d');
    return provider.t('pub.hours').replaceFirst('{n}', '$h');
  }

  /// 公開の控えを置く prefs キー (ページごと)。
  String get _kMdPublishKey => 'md_published_${widget.pageId}';

  // ── 設定の窓は押した所の近くに出す (= ユーザー要望: 画面の真ん中だと
  //    押しにくい)。 ヘッダーのボタンを押した位置を控えておく。 ──
  Offset? _lastPointerPos;

  /// 押した所の近くに出すダイアログ。 位置が分からない時は中央のまま。
  Future<T?> _showNearDialog<T>(
      {required WidgetBuilder builder, Color? barrierColor}) {
    final at = _lastPointerPos;
    return showDialog<T>(
      context: context,
      barrierColor: barrierColor,
      builder: (dctx) {
        if (at == null) return builder(dctx);
        final screen = MediaQuery.of(dctx).size;
        // 画面より広いと右端が切れる (= ユーザー報告: モバイルで
        // 「ネットに公開する」 の右端が切れる) ので、 幅を縮める。
        final w = math.min(480.0, screen.width - 24.0);
        const h = 380.0;
        final left = (at.dx - w / 2)
            .clamp(12.0, math.max(12.0, screen.width - w - 12))
            .toDouble();
        var top = at.dy + 14;
        if (top + h > screen.height - 12) {
          top = math.max(12.0, at.dy - h - 14);
        }
        return Stack(children: [
          Positioned(
            left: left,
            top: top,
            width: w,
            child: Material(
              type: MaterialType.transparency,
              child: Builder(builder: builder),
            ),
          ),
        ]);
      },
    );
  }

  /// タブ列を出しているか (= ユーザー要望: 非表示ボタンで消せるように)。
  bool _tabBarVisible = true;
  static const String _kMdTabBarKey = 'markdownTabBarVisible';

  /// 隠している時、 上端にカーソルが乗っているか。
  bool _headerHover = false;
  static const String _kMdHeaderHiddenKey = 'markdownHeaderHidden';

  void _toggleSides() {
    setState(() => _previewLeft = !_previewLeft);
    // ignore: discarded_futures
    SharedPreferences.getInstance()
        .then((sp) => sp.setBool(_kMdPreviewLeftKey, _previewLeft));
  }

  /// プレビューを出すか (本文だけの時は出さない)。
  bool get _preview => _viewMode != 'editor';

  /// 画面が狭い時 (= モバイル) は「並べる」 を使わない
  /// (= ユーザー要望: 上下分割だと表示領域が狭まり過ぎる)。
  bool get _narrowScreen =>
      !_isDesktopPlatform || MediaQuery.sizeOf(context).width < 720;

  /// 表示の仕方を順に切り替える (並べる → プレビューだけ → 本文だけ)。
  /// 狭い画面では「プレビューだけ ⇄ 本文だけ」 の 2 つを行き来する。
  void _cycleViewMode() {
    setState(() {
      _viewMode = _narrowScreen
          ? (_viewMode == 'editor' ? 'preview' : 'editor')
          : (_viewMode == 'split'
              ? 'preview'
              : (_viewMode == 'preview' ? 'editor' : 'split'));
    });
    if (_preview) _render();
    // ignore: discarded_futures
    SharedPreferences.getInstance()
        .then((sp) => sp.setString(_kMdViewModeKey, _viewMode));
  }

  /// 表示の仕方ボタンは「押したら次に何になるか」 を出す (= ユーザー要望:
  /// 今の状態ではなく、 次のモードが分かるように)。
  /// 循環: 並べる → プレビューだけ → 本文だけ → 並べる。
  String get _nextViewMode => _narrowScreen
      ? (_viewMode == 'editor' ? 'preview' : 'editor')
      : (_viewMode == 'split'
          ? 'preview'
          : (_viewMode == 'preview' ? 'editor' : 'split'));

  IconData get _viewModeIcon => _nextViewMode == 'split'
      ? Icons.vertical_split_rounded
      : (_nextViewMode == 'preview'
          // プレビューは目のアイコンを使わない (= ユーザー要望)。
          ? Icons.wysiwyg_rounded
          : Icons.edit_note_rounded);

  String _viewModeLabel(MindMapProvider provider) => provider
      .t('md.viewNext')
      .replaceFirst(
          '{mode}',
          provider.t(_nextViewMode == 'split'
              ? 'md.viewSplit'
              : (_nextViewMode == 'preview'
                  ? 'md.viewPreview'
                  : 'md.viewEditor')));

  /// デスクトップの WebView。 モバイルは InAppWebView を使う。
  wv_win.WebviewController? _win;
  bool _winReady = false;
  iaw.InAppWebViewController? _iaw;

  String get _prefsKey => 'markdown_${widget.pageId}';

  bool get _isDesktopPlatform =>
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);

  @override
  void initState() {
    super.initState();
    _load();
    if (_isDesktopPlatform) _initWin();
  }

  @override
  void dispose() {
    _saveDebounce?.cancel();
    _renderDebounce?.cancel();
    _sideMemoDebounce?.cancel();
    // 閉じる直前の内容も確実に保存する。
    _syncCurrentTab();
    final blob = encodeMarkdownDoc(_tabs, _sel);
    // ignore: discarded_futures
    SharedPreferences.getInstance().then((sp) => sp.setString(_prefsKey, blob));
    if (_fileMode && _tabs.isNotEmpty) {
      // ファイル = 1 枚目のタブ、 という約束で書き戻す。
      // ignore: discarded_futures
      File(widget.filePath!).writeAsString(_tabs[0].text).then((_) {
        widget.onSaved?.call();
      }).catchError((_) {});
    }
    _mdMsgSub?.cancel();
    _tabScroll.dispose();
    _ctrl.dispose();
    _sideMemoCtrl.dispose();
    _sideAiInput.dispose();
    _sideAiScroll.dispose();
    try {
      _win?.dispose();
    } catch (_) {}
    super.dispose();
  }

  Future<void> _load() async {
    try {
      final sp = await SharedPreferences.getInstance();
      // メモ欄の中身 (パネルを開いた時のため先に読む)。
      _sideMemoCtrl.text = sp.getString(_kMdSideMemoKey) ?? '';
      // ── 添付ファイルモード: 本文はファイルから読む (= ユーザー要望) ──
      // タブも使える (= ユーザー要望: 複数タブとメモ / AI 欄のいいとこどり)。
      // タブ束は prefs (markdown_<疑似ページid>) に持ち、 ファイルには
      // 1 枚目のタブの本文を書き戻す (ファイル = 1 枚目、 という約束)。
      // 外でファイルが書き換えられた時に反映されるよう、 1 枚目の中身は
      // 毎回ファイルから読み直す。
      if (_fileMode) {
        String? fileText;
        try {
          fileText = await File(widget.filePath!).readAsString();
        } catch (_) {}
        final base = widget.filePath!
            .replaceAll('\\', '/')
            .split('/')
            .last
            .replaceAll(RegExp(r'\.(md|markdown)$', caseSensitive: false), '');
        final doc = decodeMarkdownDoc(sp.getString(_prefsKey));
        _tabs
          ..clear()
          ..addAll(doc.tabs);
        if (_tabs.isEmpty) {
          _tabs.add(_MdTab(
              id: 'md${DateTime.now().microsecondsSinceEpoch}',
              name: base.isEmpty ? '1' : base,
              text: fileText ?? ''));
        } else if (fileText != null) {
          _tabs[0].text = fileText;
        }
        _sel = doc.sel.clamp(0, _tabs.length - 1);
        _ctrl.text = _tabs[_sel].text;
        final m = sp.getString(_kMdViewModeKey) ?? '';
        if (m == 'split' || m == 'preview' || m == 'editor') _viewMode = m;
        _previewLeft = sp.getBool(_kMdPreviewLeftKey) ?? false;
        _headerHidden = sp.getBool(_kMdHeaderHiddenKey) ?? false;
        // 公開の控え (ファイルごとの pageId で持ち回る)。
        try {
          final raw = sp.getString(_kMdPublishKey);
          if (raw != null && raw.isNotEmpty) {
            final m2 = jsonDecode(raw);
            if (m2 is Map) {
              final exp = (m2['expiresAt'] as num?)?.toInt() ?? 0;
              if (exp * 1000 > DateTime.now().millisecondsSinceEpoch) {
                _publishedUrl = '${m2['url'] ?? ''}';
                _publishedId = '${m2['id'] ?? ''}';
                _publishedExpiresAt = exp;
                _publishHours = (m2['hours'] as num?)?.toInt() ??
                    (((m2['days'] as num?)?.toInt() ?? 7) * 24);
                _publishPassword = '${m2['pw'] ?? ''}';
              } else {
                await sp.remove(_kMdPublishKey);
              }
            }
          }
        } catch (_) {}
        if (!mounted) return;
        setState(() => _loaded = true);
        _scheduleRender();
        return;
      }
      final doc = decodeMarkdownDoc(sp.getString(_prefsKey));
      _tabs
        ..clear()
        ..addAll(doc.tabs);
      // 書き方例は「このページで一度も出していない」 時だけ差し込む
      // (= ユーザー要望: モバイルでも作成時に例が出るように)。 空の
      // タブ 1 枚だけの状態でも初回なら例を入れる。 逆に、 利用者が
      // 自分で空にした後に再起動で例が復活しないよう、 一度出したら
      // フラグを立てて二度と出さない。
      final seededKey = 'md_sample_seeded_${widget.pageId}';
      final seeded = sp.getBool(seededKey) ?? false;
      if (_tabs.isEmpty) {
        _tabs.add(_MdTab(
            id: 'md${DateTime.now().microsecondsSinceEpoch}',
            name: '1',
            text: _sample()));
        // ignore: discarded_futures
        sp.setBool(seededKey, true);
      } else if (!seeded &&
          _tabs.length == 1 &&
          _tabs[0].text.trim().isEmpty) {
        _tabs[0].text = _sample();
        // ignore: discarded_futures
        sp.setBool(seededKey, true);
      } else if (!seeded) {
        // 既に本文がある = 例は不要。 以後の判定を省くため立てておく。
        // ignore: discarded_futures
        sp.setBool(seededKey, true);
      }
      _sel = doc.sel.clamp(0, _tabs.length - 1);
      _ctrl.text = _tabs[_sel].text;
      // 前に選んだ表示の仕方を覚えている (= ユーザー要望)。
      final m = sp.getString(_kMdViewModeKey) ?? '';
      if (m == 'split' || m == 'preview' || m == 'editor') _viewMode = m;
      _previewLeft = sp.getBool(_kMdPreviewLeftKey) ?? false;
      _headerHidden = sp.getBool(_kMdHeaderHiddenKey) ?? false;
      // ★ タブ列は常に出す (= ユーザー報告: 複数タブの機能が消えている)。
      //   昔あった「タブ列の表示 / 非表示」 ボタンで false が保存されて
      //   いると、 ボタン自体を消した今は戻す手段が無く、 タブが永久に
      //   出なくなっていた。 古い保存値は読まない。
      _tabBarVisible = true;
      // 公開中かどうかを思い出す (= ユーザー要望: ネットへの公開)。
      //   期限が過ぎていれば控えを捨てる (サーバー側では既に消えている)。
      try {
        final raw = sp.getString(_kMdPublishKey);
        if (raw != null && raw.isNotEmpty) {
          final m = jsonDecode(raw);
          if (m is Map) {
            final exp = (m['expiresAt'] as num?)?.toInt() ?? 0;
            if (exp * 1000 > DateTime.now().millisecondsSinceEpoch) {
              _publishedUrl = '${m['url'] ?? ''}';
              _publishedId = '${m['id'] ?? ''}';
              _publishedExpiresAt = exp;
              _publishHours = (m['hours'] as num?)?.toInt() ??
                  (((m['days'] as num?)?.toInt() ?? 7) * 24);
              _publishPassword = '${m['pw'] ?? ''}';
            } else {
              await sp.remove(_kMdPublishKey);
            }
          }
        }
      } catch (_) {}
    } catch (_) {
      _tabs
        ..clear()
        ..add(_MdTab(
            id: 'md${DateTime.now().microsecondsSinceEpoch}',
            name: '1',
            text: _sample()));
      _sel = 0;
      _ctrl.text = _tabs[0].text;
    }
    if (!mounted) return;
    setState(() => _loaded = true);
    _scheduleRender();
  }

  String _sample() => '''# ${widget.provider.t('md.sampleTitle')}

${widget.provider.t('md.sampleBody')}

- ${widget.provider.t('md.sampleItem1')}
- ${widget.provider.t('md.sampleItem2')}

```mermaid
graph TD
  A[${widget.provider.t('md.sampleNodeA')}] --> B[${widget.provider.t('md.sampleNodeB')}]
  B --> C{${widget.provider.t('md.sampleNodeC')}}
  C -->|Yes| D[${widget.provider.t('md.sampleNodeD')}]
  C -->|No| A
```
''';

  /// プレビューの WebView が使えなかった (= WebView2 未対応環境など)。
  bool _winFailed = false;

  Future<void> _initWin() async {
    try {
      final c = wv_win.WebviewController();
      // 稀に initialize が返らないことがあるのでタイムアウトを付ける
      //   (= ユーザー報告: WebView の所でエラーが出る)。
      await c.initialize().timeout(const Duration(seconds: 12));
      // 透明背景 (alpha=0) はこのプラグインで未対応なので使わない。
      //   これが原因で初期化直後にエラーになる事があった。 不透明の暗色にする。
      await c.setBackgroundColor(const Color(0xFF14141F));
      if (!mounted) {
        await c.dispose();
        return;
      }
      // プレビューの中で押されたリンクを受け取る (= ユーザー要望)。
      _mdMsgSub?.cancel();
      _mdMsgSub = c.webMessage.listen(_onPreviewMessage);
      setState(() {
        _win = c;
        _winReady = true;
        _winFailed = false;
      });
      _scheduleRender();
    } catch (e) {
      debugPrint('markdown プレビューの初期化に失敗: $e');
      // 失敗しても本文の編集は続けられる。 プレビューだけ素のテキスト表示に
      //   フォールバックする (= ユーザー要望: エラーを出しっぱなしにしない)。
      if (mounted) {
        setState(() {
          _winReady = false;
          _winFailed = true;
        });
      }
    }
  }

  void _onChanged() {
    _syncCurrentTab();
    _saveDebounce?.cancel();
    _saveDebounce = Timer(const Duration(milliseconds: 400), _saveNow);
    _scheduleRender();
  }

  Future<void> _saveNow() async {
    try {
      _syncCurrentTab();
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_prefsKey, encodeMarkdownDoc(_tabs, _sel));
      // 添付ファイルモード: 1 枚目のタブをファイルへも書き戻す
      // (= ユーザー要望。 タブ束そのものは prefs が持つ)。
      if (_fileMode && _tabs.isNotEmpty) {
        await File(widget.filePath!).writeAsString(_tabs[0].text);
        widget.onSaved?.call();
      }
    } catch (_) {}
  }

  /// 打鍵のたびに描き直すと重いので、 少し待ってからまとめて描く。
  void _scheduleRender() {
    if (!_preview) return;
    _renderDebounce?.cancel();
    _renderDebounce = Timer(const Duration(milliseconds: 500), _render);
  }

  Future<void> _render() async {
    if (!mounted || !_preview) return;
    final html = _markdownPreviewHtml(_ctrl.text, widget.provider.isDarkMode,
        linkBridge: true);
    try {
      if (_isDesktopPlatform) {
        // ── file:// で開く (= Mermaid 描画対応。 about:blank だと CDN の
        //    スクリプトが読めない環境がある)。 準備できない時だけ従来の
        //    loadStringContent + CDN にフォールバック。 ──
        final localHtml = _markdownPreviewHtml(
            _ctrl.text, widget.provider.isDarkMode,
            linkBridge: true,
            markedSrc: 'marked.min.js',
            mermaidSrc: 'mermaid.min.js',
            hljsSrc: 'highlight.min.js',
            hljsCssSrc: widget.provider.isDarkMode
                ? 'hljs-dark.css'
                : 'hljs-light.css',
            mathjaxSrc: 'tex-svg.js',
            tocLabel: widget.provider.t('md.toc'));
        final fileUrl = await _prepareMarkdownPreviewFile(localHtml);
        if (!mounted || !_preview) return;
        if (fileUrl != null) {
          if (_winReady) await _win?.loadUrl(fileUrl);
          return;
        }
        // data: URI は長さ制限に当たる事があるので loadStringContent を使う
        //   (= ユーザー報告: WebView の所でエラー)。
        if (_winReady) await _win?.loadStringContent(html);
      } else {
        final uri = Uri.dataFromString(html,
                mimeType: 'text/html', encoding: utf8)
            .toString();
        await _iaw?.loadUrl(urlRequest: iaw.URLRequest(url: iaw.WebUri(uri)));
      }
    } catch (e) {
      debugPrint('markdown プレビューの描画に失敗: $e');
    }
  }

  // ─── ネットへの公開 (= ユーザー要望: プレビュー画面をサーバーに公開) ───
  //
  // 出来上がったプレビューの HTML をそのままサーバーへ預け、 リンクを知って
  // いる人なら誰でもブラウザで読める形にする。 **必ず期限が付く**。
  // 期限が来ればサーバー側で勝手に消えるので、 消し忘れが残らない。

  Future<void> _savePublishState() async {
    try {
      final sp = await SharedPreferences.getInstance();
      if (_publishedUrl.isEmpty) {
        await sp.remove(_kMdPublishKey);
      } else {
        await sp.setString(
            _kMdPublishKey,
            jsonEncode({
              'id': _publishedId,
              'url': _publishedUrl,
              'expiresAt': _publishedExpiresAt,
              'hours': _publishHours,
              'pw': _publishPassword,
            }));
      }
    } catch (_) {}
  }

  /// 公開する中身 (HTML) を作る。
  ///
  /// [allTabs] の時は 1 本の長い頁にせず、 **アプリの中と同じようにタブで
  /// 切り替える形**にする (= ユーザー要望)。
  String _publishHtml(bool allTabs) {
    _syncCurrentTab();
    final md = _ctrl.text;
    // 公開ページはふつうのブラウザで見るので、 CDN から読み込む既定のまま
    // でよい (アプリ内プレビューのようにローカルの控えを使う必要は無い)。
    return _markdownPreviewHtml(md, widget.provider.isDarkMode,
        tocLabel: widget.provider.t('md.toc'),
        // ★ 見る側にダウンロードボタンは出さない (= ユーザー要望: 邪魔だし、
        //   受け取っても普通は開く用意が無い)。
        showDownload: false,
        tabs: allTabs && _tabs.length > 1
            ? [for (final t in _tabs) (name: t.name, md: t.text)]
            : null);
  }

  String _publishExpiryText(MindMapProvider provider) {
    if (_publishedExpiresAt <= 0) return '';
    final at =
        DateTime.fromMillisecondsSinceEpoch(_publishedExpiresAt * 1000).toLocal();
    final left = at.difference(DateTime.now());
    final days = left.inDays;
    final hours = left.inHours;
    final when = '${at.year}/${at.month}/${at.day} '
        '${at.hour.toString().padLeft(2, '0')}:'
        '${at.minute.toString().padLeft(2, '0')}';
    final rest = days >= 1
        ? provider.t('pub.leftDays').replaceFirst('{n}', '$days')
        : provider
            .t('pub.leftHours')
            .replaceFirst('{n}', '${hours < 1 ? 1 : hours}');
    return provider
        .t('pub.expiresAt')
        .replaceFirst('{when}', when)
        .replaceFirst('{rest}', rest);
  }

  /// 公開ダイアログ用の選択ボタン。
  ///
  /// ★ M3 の ChoiceChip は**押せない時に背景の指定を無視して白くなる**ため
  ///   使わない (= ユーザー報告: 公開するを押すと選んでいないボタンが
  ///   白飛びして読めない)。 自前で描いて色を全部決める。
  Widget _pubChoiceChip({
    required String label,
    required bool selected,
    required bool enabled,
    required VoidCallback onTap,
  }) {
    const accent = Color(0xFF7FD8A0);
    final bg = selected ? accent : const Color(0xFF2A2A44);
    final fg = selected ? Colors.black : Colors.white70;
    return Opacity(
      opacity: enabled ? 1 : 0.55,
      child: Material(
        color: bg,
        borderRadius: BorderRadius.circular(999),
        child: InkWell(
          borderRadius: BorderRadius.circular(999),
          onTap: enabled ? onTap : null,
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 7),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              if (selected) ...[
                const Icon(Icons.check_rounded, size: 14, color: Colors.black),
                const SizedBox(width: 4),
              ],
              Text(label, style: TextStyle(color: fg, fontSize: 12)),
            ]),
          ),
        ),
      ),
    );
  }

  /// 期間を足し引きする小さなボタン。
  Widget _pubStepChip({
    required String label,
    required bool enabled,
    required VoidCallback onTap,
  }) {
    return Opacity(
      opacity: enabled ? 1 : 0.4,
      child: Material(
        color: const Color(0xFF2A2A44),
        borderRadius: BorderRadius.circular(999),
        child: InkWell(
          borderRadius: BorderRadius.circular(999),
          onTap: enabled ? onTap : null,
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 13, vertical: 7),
            child: Text(label,
                style: const TextStyle(color: Colors.white70, fontSize: 12)),
          ),
        ),
      ),
    );
  }

  /// 公開する markdown 本文 (読む人が .md として落とせるように渡す)。
  String _publishMarkdown(bool allTabs) {
    _syncCurrentTab();
    if (!allTabs || _tabs.length <= 1) return _ctrl.text;
    return _joinTabsAsDocument();
  }

  Future<void> _openPublishDialog() async {
    final provider = widget.provider;
    var allTabs = false;
    var hours = _publishHours;
    // 閲覧のパスワード (= ユーザー要望: 空なら誰でも読める)。
    final pwCtrl = TextEditingController(text: _publishPassword);
    var busy = false;
    String? error;
    await _showNearDialog<void>(
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        Future<void> run({required bool update}) async {
          setD(() {
            busy = true;
            error = null;
          });
          try {
            final r = await provider.publishHtmlPage(
              _publishHtml(allTabs),
              title: _cur?.name ?? '',
              hours: hours,
              // 読む人が .md を落とせるように本文も預ける (= ユーザー要望)。
              markdown: _publishMarkdown(allTabs),
              password: pwCtrl.text.trim(),
              updateId: update ? _publishedId : null,
            );
            if (!mounted) return;
            setState(() {
              _publishedUrl = r.url;
              _publishedId = r.id;
              _publishedExpiresAt = r.expiresAt;
              _publishHours = hours;
              _publishPassword = pwCtrl.text.trim();
            });
            await _savePublishState();
            setD(() => busy = false);
          } catch (e) {
            setD(() {
              busy = false;
              error = '$e'.replaceFirst('Exception: ', '');
            });
          }
        }

        Future<void> stop() async {
          setD(() => busy = true);
          final ok = await provider.unpublishHtmlPage(_publishedId);
          if (!mounted) return;
          if (ok) {
            setState(() {
              _publishedUrl = '';
              _publishedId = '';
              _publishedExpiresAt = 0;
            });
            await _savePublishState();
          }
          setD(() => busy = false);
        }

        final live = _publishedUrl.isNotEmpty;
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            const Icon(Icons.public_rounded,
