            width: 460,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              Align(
                alignment: Alignment.centerLeft,
                child: Text(provider.t('pub.desc'),
                    style: const TextStyle(
                        color: Colors.white54, fontSize: 11.5, height: 1.6)),
              ),
              const SizedBox(height: 14),
              // ── 公開する範囲 ──
              if (_tabs.length > 1) ...[
                Align(
                  alignment: Alignment.centerLeft,
                  child: Text(provider.t('pub.scope'),
                      style: const TextStyle(
                          color: Color(0xFF7FD8A0),
                          fontSize: 11.5,
                          fontWeight: FontWeight.w700)),
                ),
                const SizedBox(height: 6),
                Align(
                  alignment: Alignment.centerLeft,
                  child: Wrap(spacing: 8, children: [
                    _pubChoiceChip(
                      label: provider.t('pub.scopeTab'),
                      selected: !allTabs,
                      enabled: !busy,
                      onTap: () => setD(() => allTabs = false),
                    ),
                    _pubChoiceChip(
                      label: provider.t('pub.scopeAll'),
                      selected: allTabs,
                      enabled: !busy,
                      onTap: () => setD(() => allTabs = true),
                    ),
                  ]),
                ),
                const SizedBox(height: 14),
              ],
              // ── 公開の期限 ──
              Align(
                alignment: Alignment.centerLeft,
                child: Text(provider.t('pub.period'),
                    style: const TextStyle(
                        color: Color(0xFF7FD8A0),
