  // ─── タブの操作 (= ユーザー要望) ─────────────────────────────────
  /// 押されたタブへ移る。 今の内容は書き戻してから。
  void _selectTab(int i) {
    if (i < 0 || i >= _tabs.length || i == _sel) return;
    _syncCurrentTab();
    setState(() {
      _sel = i;
      _ctrl.text = _tabs[i].text;
    });
    unawaited(_saveNow());
    _scheduleRender();
  }

  /// 新しいタブを足す。 名前は「2」「3」… と重ならない番号にする。
  void _addTab() {
    _syncCurrentTab();
    var num = _tabs.length + 1;
    while (_tabs.any((t) => t.name == '$num')) {
      num++;
    }
    setState(() {
      _tabs.add(_MdTab(
          id: 'md${DateTime.now().microsecondsSinceEpoch}',
          name: '$num',
          text: ''));
      _sel = _tabs.length - 1;
      _ctrl.text = '';
    });
    unawaited(_saveNow());
    _scheduleRender();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_tabScroll.hasClients) {
        _tabScroll.jumpTo(_tabScroll.position.maxScrollExtent);
      }
    });
  }

  Future<void> _renameTab(int i) async {
    if (i < 0 || i >= _tabs.length) return;
    final provider = widget.provider;
    final ctrl = TextEditingController(text: _tabs[i].name);
    final name = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('md.tabRename'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          decoration: const InputDecoration(
            enabledBorder:
                UnderlineInputBorder(borderSide: BorderSide(color: Colors.white24)),
          ),
          onSubmitted: (v) => Navigator.pop(dctx, v),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          TextButton(
            onPressed: () => Navigator.pop(dctx, ctrl.text),
            child: Text(provider.t('btn.save'),
                style: const TextStyle(color: Color(0xFFBA68C8))),
          ),
        ],
      ),
    );
    ctrl.dispose();
    final v = (name ?? '').trim();
    if (v.isEmpty || !mounted) return;
    setState(() => _tabs[i].name = v);
    unawaited(_saveNow());
  }

  /// 消したタブの控え (Ctrl+Z で戻すため)。 = ユーザー要望:
  /// 確認は出さずに消して、 間違えたら取り消せるようにする。
  final List<({int index, _MdTab tab})> _deletedTabs = [];

  /// タブを消す。 ★確認は出さない (= ユーザー要望: 面倒)。
  /// 代わりに Ctrl+Z で戻せる。
  Future<void> _deleteTab(int i) async {
    if (i < 0 || i >= _tabs.length) return;
    final provider = widget.provider;
    if (_tabs.length <= 1) {
      _appSnackTop(context, provider.t('md.tabLastOne'),
          const Color(0xFFFFB347));
      return;
    }
    _syncCurrentTab();
    setState(() {
      _deletedTabs.add((index: i, tab: _tabs[i]));
      // 控えは増やし過ぎない。
      if (_deletedTabs.length > 20) _deletedTabs.removeAt(0);
      _tabs.removeAt(i);
      if (_sel >= _tabs.length) _sel = _tabs.length - 1;
      if (_sel < 0) _sel = 0;
      _ctrl.text = _tabs[_sel].text;
    });
    unawaited(_saveNow());
    _scheduleRender();
    if (!mounted) return;
    _appSnackTop(context, provider.t('md.tabDeletedUndo'),
        const Color(0xFF616184));
  }

  /// 消したタブを戻す (Ctrl+Z)。 戻せる物が無ければ何もしない。
  void _undoDeleteTab() {
    if (_deletedTabs.isEmpty) return;
    _syncCurrentTab();
    final last = _deletedTabs.removeLast();
    setState(() {
      final at = last.index.clamp(0, _tabs.length);
      _tabs.insert(at, last.tab);
      _sel = at;
      _ctrl.text = _tabs[_sel].text;
    });
    unawaited(_saveNow());
    _scheduleRender();
  }


  // ─── プレビューで押されたリンク (= ユーザー要望) ───────────────────
  StreamSubscription<dynamic>? _mdMsgSub;

  void _onPreviewMessage(dynamic msg) {
    try {
      dynamic m = msg;
      if (m is String) m = jsonDecode(m);
      if (m is! Map) return;
      final type = '${m['type'] ?? ''}';
      final href = '${m['href'] ?? ''}'.trim();
      if (href.isEmpty) return;
      if (type == 'mdOpenUrl') {
        final uri = Uri.tryParse(href);
        if (uri != null) {
          unawaited(launchUrl(uri, mode: LaunchMode.externalApplication));
        }
        return;
      }
      if (type != 'mdLink') return;
      final at = href.indexOf(':');
      final scheme = href.substring(0, at < 0 ? 0 : at).toLowerCase();
      var key = at < 0 ? '' : href.substring(at + 1).trim();
      try {
        key = Uri.decodeComponent(key);
      } catch (_) {}
      if (key.isEmpty) return;
      String norm(String x) =>
          x.trim().toLowerCase().replaceAll(RegExp(r'[\s　]+'), '');
      if (scheme == 'tab') {
        var i = _tabs.indexWhere((t) => t.name.trim() == key);
        if (i < 0) i = _tabs.indexWhere((t) => norm(t.name) == norm(key));
        if (i < 0) i = _tabs.indexWhere((t) => t.id == key);
        if (i >= 0) {
          _selectTab(i);
        } else if (mounted) {
          _appSnackTop(
              context,
              widget.provider.t('md.linkTabMissing').replaceFirst('{name}', key),
              const Color(0xFFFFB347));
        }
        return;
      }
      if (scheme == 'page') {
        final pages = widget.provider.pages;
        var i = pages.indexWhere((p) => p.name.trim() == key);
        if (i < 0) i = pages.indexWhere((p) => norm(p.name) == norm(key));
        if (i < 0) i = pages.indexWhere((p) => p.id == key);
        if (i >= 0) {
          widget.provider.switchPage(i);
        } else if (mounted) {
          _appSnackTop(
              context,
              widget.provider
                  .t('md.linkPageMissing')
                  .replaceFirst('{name}', key),
              const Color(0xFFFFB347));
        }
      }
    } catch (_) {}
  }

  /// AI に Markdown / Mermaid を書いてもらう (= ユーザー要望)。
  /// 資料として読み込むファイルを選んで、 中の文字を取り出す
  /// (= ユーザー要望: txt や PDF を読み込ませて Mermaid 入りの Markdown を作る)。
  /// 取れた文字と、 見せる用のファイル名を返す。 取り消し / 失敗なら null。
  Future<({String name, String text})?> _pickSourceFile() async {
    final provider = widget.provider;
    String? path;
    try {
      final res = await FilePicker.platform.pickFiles(
        dialogTitle: provider.t('md.fromFile'),
        type: FileType.custom,
        allowedExtensions: const [
          'txt', 'md', 'markdown', 'csv', 'log', 'json',
          'pdf', 'docx', 'pptx', 'xlsx', 'html', 'htm',
        ],
      );
      path = res?.files.single.path;
    } catch (e) {
      if (mounted) _appSnackTop(context, '$e', const Color(0xFFE57373));
      return null;
    }
    if (path == null || path.isEmpty) return null;
    final dot = path.lastIndexOf('.');
    final ext = dot >= 0 ? path.substring(dot + 1).toLowerCase() : '';
    final reader = widget.extractText;
    if (reader == null) return null;
    final text = await reader(path, ext);
    if (text == null || text.trim().isEmpty) {
      if (mounted) {
        _appSnackTop(context, provider.t('md.fromFileEmpty'),
            const Color(0xFFE57373));
      }
      return null;
    }
    // 長すぎる時は先頭だけ渡す (AI の入力上限に収める)。
    const maxChars = 24000;
    final body = text.length > maxChars ? text.substring(0, maxChars) : text;
    return (name: path.split(Platform.pathSeparator).last, text: body);
  }

  /// 使うモデルを選ぶ小さなボタン (= ユーザー要望: Markdown を書く LLM の
  /// モデル選択が無い)。 AI アシスタントと同じ設定 (relayModel) を使う。
  /// 使うモデルのボタン (= ユーザー要望: どこでも同じ選び方にする)。
  /// 押すとプロバイダーごとに横に並んだ共通の画面が開く。
  Widget _buildMdModelPicker(MindMapProvider provider, void Function() refresh) {
    String label(String id) => id.replaceAll(RegExp(r'-\d{8}$'), '');
    return InkWell(
      borderRadius: BorderRadius.circular(10),
      onTap: () => showAiModelDialog(context, provider, onChanged: refresh),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: Colors.white24),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          const Icon(Icons.memory_rounded, size: 13, color: Colors.white54),
          const SizedBox(width: 5),
          Text(label(provider.relayModel),
              style: const TextStyle(color: Colors.white70, fontSize: 11)),
          const Icon(Icons.expand_more_rounded,
              size: 14, color: Colors.white38),
        ]),
      ),
    );
  }

  Future<void> _askAiToWrite() async {
    if (_aiBusy) return;
    final provider = widget.provider;
    final reqCtrl = TextEditingController();
    // 資料として読ませるファイル (= ユーザー要望: ファイルからの作成も
    //   同じ「AI に書いてもらう」 の中で)。
    ({String name, String text})? source;
    // Ctrl+V で貼った画像 (= ユーザー要望)。 そのまま AI へ渡す。
    final pasted = <AiInputImage>[];
    // 複数タブに分けるか (= ユーザー要望: 数は指定せず、 AI が必要な分だけ
    //   分ける)。
    var splitTabs = false;
