          content: SizedBox(
            width: 460,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              // ── AI アシスタントと同じ形の入力欄 (= ユーザー要望) ──
              //    角の丸い枠に、 右下へ送信ボタンを内側に置く。
              //    Enter で送信 / Shift+Enter で改行。
              Container(
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.06),
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(
                      color: const Color(0xFFBA68C8).withValues(alpha: 0.45)),
                ),
                padding: const EdgeInsets.fromLTRB(14, 10, 8, 8),
                child: Column(children: [
                  // ★ Ctrl+V で画像も貼れるようにする (= ユーザー要望)。
                  //   画像はそのまま AI へ渡し、 文字は普通の貼り付けに任せる。
                  Focus(
                    onKeyEvent: (node, event) {
                      if (event is! KeyDownEvent) {
                        return KeyEventResult.ignored;
                      }
                      // ── Enter で送信 / Shift+Enter で改行 (= ユーザー報告:
                      //    Enter で改行になっていた) ──
                      if ((event.logicalKey == LogicalKeyboardKey.enter ||
                              event.logicalKey ==
                                  LogicalKeyboardKey.numpadEnter) &&
                          !HardwareKeyboard.instance.isShiftPressed) {
                        Navigator.pop(dctx, true);
                        return KeyEventResult.handled;
                      }
                      final ctrl = HardwareKeyboard.instance.isControlPressed ||
                          HardwareKeyboard.instance.isMetaPressed;
                      if (!ctrl ||
                          event.logicalKey != LogicalKeyboardKey.keyV) {
                        return KeyEventResult.ignored;
                      }
                      // ignore: discarded_futures
                      _pasteImageForAi().then((img) {
                        if (img != null) setD(() => pasted.add(img));
                      });
                      // 文字の貼り付けは邪魔しない。
                      return KeyEventResult.ignored;
                    },
                    child: TextField(
                    controller: reqCtrl,
                    autofocus: true,
                    maxLines: 6,
                    minLines: 2,
                    textInputAction: TextInputAction.newline,
                    style: const TextStyle(
                        color: Colors.white, fontSize: 13, height: 1.5),
                    decoration: InputDecoration(
                      isDense: true,
                      contentPadding: EdgeInsets.zero,
                      border: InputBorder.none,
                      hintText: provider.t('md.aiPlaceholder'),
