                      if (remain.isEmpty) return const SizedBox.shrink();
                      return Padding(
                        padding: const EdgeInsets.only(top: 3, left: 2),
                        child: Text(remain,
                            // 目立たない白にする (= ユーザー要望)。
                            style: const TextStyle(
                                color: Colors.white38, fontSize: 10)),
