    final req = reqCtrl.text.trim();
    reqCtrl.dispose();
    // 資料だけでも作れる (= ユーザー要望: ファイルを読ませて作る)。
    if (ask != true || (req.isEmpty && source == null) || !mounted) return;

    setState(() => _aiBusy = true);
    try {
      // 図が要る内容なら mermaid のコードブロックで書くよう明示する。
      final src = source;
      // ★ 複数タブに分けて書いてもらう時の決まり (= ユーザー要望:
      //   一度に何ページか作って、 本文から別ページへ飛べるように)。
      //   区切りと、 タブ名で飛べるリンクの書き方を教える。
      final multi = !splitTabs
          ? ''
          : '''

【複数ページに分けて書く】
- 内容の量とまとまりを見て、 **あなたが適切と考える数**のページに分けて
  ください (数はこちらでは決めません。 分ける必要が無ければ 1 本のままで
  構いません)。
- 各ページの先頭に「<<<PAGE: ページ名>>>」 という行を必ず置いてください
  (ページ名は短い日本語。 これが見出し兼タブ名になります)。
- 1 ページ目は目次・全体像とし、 他のページへは
  「[ページ名](tab:ページ名)」 の形でリンクを張ってください。
  詳しい説明は各ページ側に書き、 1 ページ目には概要だけ書きます。
- 各ページからも、 関係する他のページへ同じ形でリンクを張ってください。''';
      final prompt = '''${provider.languageInstructionForAi()}
あなたは Markdown の文書を書く道具です。 次の依頼に対して、
Markdown 本文だけを出力してください (前置き・説明・コードフェンスでの
全体の囲みは不要)。

$_kMdStyleRules

依頼: ${req.isEmpty ? '資料の内容を読みやすく整理してまとめてください。' : req}$multi${src == null ? '' : '''

--- 資料 (${src.name}) ---
${src.text}
--- 資料ここまで ---
資料に無いことは書かないでください。'''}''';
      final out = (await provider.askAi(prompt,
              images: pasted.isEmpty ? null : List<AiInputImage>.of(pasted)))
          .trim();
      if (!mounted) return;
      if (out.isEmpty) throw Exception(provider.t('md.aiEmpty'));
      // AI が全体を ``` で囲ってきた場合は剥がす。
      var body = out;
      final fence = RegExp(r'^```[a-zA-Z]*\s*\n([\s\S]*?)\n?```$');
      final m = fence.firstMatch(body.trim());
      if (m != null) body = m.group(1) ?? body;
      // 画像の指定 (image:キーワード) を実際の画像に差し替える (= ユーザー要望)。
      body = await _resolveMarkdownImages(body);
      if (!mounted) return;
      setState(() => _aiBusy = false);
      // ★ すぐには置き換えない (= ユーザー要望: プレビューで確認してから)。
      //   「置き換える」 / 「追加で修正を頼む」 / 「下書きとして保存」。
      //   修正はプレビューを開いたまま受け付け、 直った内容が返る。
      final r = await _confirmAiResult(body);
      if (!mounted || r == null) return;
      final current = r.body;
      if (r.action == 'draft') {
        // ★ 下書きは下書き置き場へ。 タブには足さない (= ユーザー報告:
        //   下書きに入れたはずなのにタブに追加されている)。
        //   反映する時に <<<PAGE>>> ごとにタブへ割り振られる。
        await _saveMarkdownDraft(current);
        return;
      }
      if (r.action != 'replace') return;
      // 複数ページに分けて書かれていたら、 タブに割り振る。
      final split = _splitMarkdownPages(current);
      if (split.length > 1) {
        await _applyMarkdownPages(split);
        return;
      }
      setState(() => _ctrl.text = current);
      // 内容に合わせてページ名も付け直す (= ユーザー要望)。
      _autoNamePageFromMarkdown(current);
      _onChanged();
      return;
    } catch (e) {
      if (!mounted) return;
      setState(() => _aiBusy = false);
      _appSnackTop(
          context, '$e'.replaceFirst('Exception: ', ''), const Color(0xFFE57373));
    }
  }

  /// AI に渡す「書き方」 の決まり (= ユーザー要望: 文字ばかりで味気ないので
  /// もう少し飾る / 必要に応じて画像も出す)。
  ///
  /// 生成と「ページ数を変える」 の両方で同じ決まりを使う。
  static const String _kMdStyleRules = '''
【書き方】
- 見出し (#, ##, ###) で階層を作り、 長い文章を並べず読みやすく区切る。
- 要点は箇条書き、 手順は番号付きにする。 大事な語は **太字** にする。
- 用語の対比・一覧・仕様などは Markdown の表にする。
- 補足や注意は引用 (> **メモ:** …) で添える。
- 見出しの先頭に、 内容に合う絵文字を 1 つだけ添えてよい (付けすぎない)。
- 区切りが要る所には --- を入れる。
- 図・フローチャート・シーケンス図・ガント・円グラフなどが有効な場合は、
  ```mermaid で始まるコードブロックとして Mermaid 記法で書く。
  ★Mermaid のラベルに ( ) や : , ; などの記号を入れる時は、 必ず二重引用符で
  包むこと (例: B["営業管理 (Sales Cloud)"])。 包まないと図が描けない。
- 写真・図版は **本当にその物が写っている 1 枚が要る時だけ** 入れる。
  形は `![説明](image:検索語)`、 多くても 1 ページに 1 枚。
  ★検索語は**固有名詞**にすること (実在する場所・建物・生き物・人物・
  製品の名前)。 「クラウド」「業務システム」「戦略」 のような**抽象的な語や
  一般語は絶対に指定しない**。 それらしい図が当たっても内容とは無関係で、
  読む人を混乱させるため。
  ★迷ったら**入れない**。 図で説明したい時は image: ではなく mermaid を使う。
  ★URL を自分で書いてはいけない。 必ず image: の形で書くこと。''';

  /// 画像を探しに行かない検索語 (= ユーザー報告: 全く関係の無い図が出る)。
  ///
  /// 抽象語で Commons を引くと「それっぽい概念図」 が必ず 1 件は当たるので、
  /// 中身と無関係な絵が入ってしまう。 その手の語は最初から諦める。
  static const List<String> _kVagueImageWords = [
    'クラウド', 'システム', 'サービス', '業務', '戦略', '概要', '構成', '仕組み',
    '技術', '事業', '会社', '企業', '導入', '支援', '開発', '運用', '管理',
    '製品', '情報', '課題', '効果', '流れ', '手順', '方法', 'イメージ', '図',
    'cloud', 'system', 'service', 'business', 'strategy', 'overview',
    'architecture', 'technology', 'company', 'enterprise', 'solution',
    'diagram', 'concept', 'process', 'workflow', 'management', 'data',
    'software', 'platform', 'network', 'digital', 'integration',
  ];

  /// その検索語で画像を探しに行ってよいか。
  bool _imageKeywordLooksConcrete(String keyword) {
    final k = keyword.trim();
    if (k.isEmpty || k.length < 2) return false;
    final low = k.toLowerCase();
    // 語がまるごと (または語の全部品が) 一般語なら諦める。
    final parts = low
        .split(RegExp(r'[\s　/・,、]+'))
        .where((e) => e.isNotEmpty)
        .toList();
    if (parts.isEmpty) return false;
    bool vague(String w) => _kVagueImageWords.any((v) => w == v.toLowerCase());
    if (parts.every(vague)) return false;
    // 「クラウドコンピューティング」 のように一般語だけで出来た複合語も外す。
    var rest = low;
    for (final v in _kVagueImageWords) {
      rest = rest.replaceAll(v.toLowerCase(), '');
    }
    rest = rest.replaceAll(RegExp(r'[\s　/・,、ーの]+'), '');
    return rest.isNotEmpty;
  }

  /// 本文の `image:検索語` を、 実際の画像 URL に差し替える。
  ///
  /// = ユーザー要望「画像も必要に応じて取ってきて表示するように」。
  /// 取得先は Wikimedia Commons の検索 API (鍵が要らず、 再配布可能な画像が
  /// 集まっている)。 見つからなかった指定は、 壊れた画像を出さないよう
  /// 行ごと取り除く。
  Future<String> _resolveMarkdownImages(String body) async {
    final re = RegExp(r'!\[([^\]]*)\]\(\s*image:\s*([^)]+?)\s*\)');
    final hits = re.allMatches(body).toList();
    if (hits.isEmpty) return body;
    final cache = <String, String?>{};
    // 取りに行き過ぎないよう上限を設ける (1 文書あたり 8 枚)。
    var budget = 8;
    final out = StringBuffer();
    var pos = 0;
    for (final m in hits) {
      out.write(body.substring(pos, m.start));
      pos = m.end;
      final alt = (m.group(1) ?? '').trim();
      final key = (m.group(2) ?? '').trim();
      String? url;
      // ★ 抽象的な語では探しに行かない (= ユーザー報告: 全く関係の無い図が
      //   出る)。 「クラウド」 のような語は Commons で必ず概念図が当たる。
      if (!_imageKeywordLooksConcrete(key)) {
        cache[key] = null;
      } else if (cache.containsKey(key)) {
        url = cache[key];
      } else if (budget > 0 && key.isNotEmpty) {
        budget--;
        url = await _searchCommonsImage(key);
        cache[key] = url;
      }
      if (url != null && url.isNotEmpty) {
        out.write('![${alt.isEmpty ? key : alt}]($url)');
      }
      // 見つからない時は何も書かない (壊れた画像を出さない)。
    }
    out.write(body.substring(pos));
    // 画像だけの行が空になった分の余分な空行を詰める。
    return out.toString().replaceAll(RegExp(r'\n{3,}'), '\n\n');
  }

  /// Wikimedia Commons から [keyword] に合う画像を 1 枚探して URL を返す。
  Future<String?> _searchCommonsImage(String keyword) async {
    try {
      final uri = Uri.https('commons.wikimedia.org', '/w/api.php', {
        'action': 'query',
        'format': 'json',
        'generator': 'search',
        'gsrsearch': '$keyword filetype:bitmap',
        'gsrnamespace': '6', // File:
        'gsrlimit': '1',
        'prop': 'imageinfo',
        'iiprop': 'url',
        'iiurlwidth': '900', // 原寸は巨大なことがあるので縮小版を使う
        'origin': '*',
      });
      final res = await http.get(uri).timeout(const Duration(seconds: 12));
      if (res.statusCode != 200) return null;
      final j = jsonDecode(utf8.decode(res.bodyBytes));
      final q = (j is Map) ? j['query'] : null;
      final pages = (q is Map) ? q['pages'] : null;
      if (pages is! Map) return null;
      for (final p in pages.values) {
        if (p is! Map) continue;
        final info = p['imageinfo'];
        if (info is! List || info.isEmpty) continue;
        final first = info.first;
        if (first is! Map) continue;
        final thumb = '${first['thumburl'] ?? ''}';
        final full = '${first['url'] ?? ''}';
        final url = thumb.isNotEmpty ? thumb : full;
        if (!url.startsWith('http')) continue;
        // ★ 当たったファイルの名前に検索語が入っていない物は使わない
        //   (= ユーザー報告: 関係の無い図が出る)。 Commons の全文検索は
        //   説明文にかすっただけの画像も返すため。
        final title = '${p['title'] ?? ''}'.toLowerCase();
        final name = Uri.decodeFull(url).toLowerCase();
        final words = keyword
            .toLowerCase()
            .split(RegExp(r'[\s　/・,、]+'))
            .where((w) => w.length >= 2)
            .toList();
        final hit = words.isEmpty ||
            words.any((w) => title.contains(w) || name.contains(w));
        if (!hit) continue;
        return url;
      }
    } catch (_) {}
    return null;
  }

  /// AI が書いた内容からページ名を付け直す (= ユーザー要望: Markdown の
  /// ページ名は、 利用者が独自に決めた物でない限り内容で上書きする)。
  ///
  /// 「マップ 1」「Markdown 3」 のような既定名か、 前に自動で付けた名前の
  /// 時だけ書き換える。 自分で付け直した名前には触らない。
  void _autoNamePageFromMarkdown(String body) {
    final provider = widget.provider;
    final i = provider.pages.indexWhere((p) => p.id == widget.pageId);
    if (i < 0) return;
    final page = provider.pages[i];
    if (!provider.isAutoGeneratedPageName(page.name) &&
        !provider.isPageNameAuto(page.id)) {
      return;
    }
    final title = _deriveMarkdownTitle(body);
    if (title.isEmpty || title == page.name) return;
    provider.renamePageAuto(i, title);
  }

  /// 本文の見出しからページ名を作る。 見つからなければ空。
  String _deriveMarkdownTitle(String body) {
    String clean(String s) {
      var t = s
          .replaceAll(RegExp(r'`+'), '')
          .replaceAll(RegExp(r'\*\*|__|~~'), '')
          // [文字](リンク) は文字だけ残す。
          .replaceAllMapped(
              RegExp(r'\[([^\]]*)\]\([^)]*\)'), (m) => m.group(1) ?? '')
          .trim();
      // 末尾の記号や句点は落とす。
      t = t.replaceFirst(RegExp(r'[\s:：。.、,]+$'), '');
      if (t.runes.length > 40) {
        t = String.fromCharCodes(t.runes.take(40));
      }
      return t.trim();
    }

    String? fallback;
    for (final raw in body.split('\n')) {
      final line = raw.trim();
      if (line.isEmpty) continue;
      // ページ区切り・水平線・コードフェンスは飛ばす。
      if (line.startsWith('<<<PAGE:') ||
          line.startsWith('---') ||
          line.startsWith('```')) {
        continue;
      }
      if (line.startsWith('#')) {
        final t = clean(line.replaceFirst(RegExp(r'^#+\s*'), ''));
        if (t.isNotEmpty) return t;
        continue;
      }
      fallback ??= clean(line);
    }
    return fallback ?? '';
  }

  /// 今あるタブを 1 本の文書 (<<<PAGE: 名前>>> 区切り) にまとめる。
  String _joinTabsAsDocument() {
    _syncCurrentTab();
    if (_tabs.length == 1) return _tabs.first.text;
    final b = StringBuffer();
    for (final t in _tabs) {
      b.writeln('<<<PAGE: ${t.name}>>>');
      b.writeln();
      b.writeln(t.text.trim());
      b.writeln();
    }
    return b.toString().trim();
  }

  /// タブ数を後から変える (= ユーザー要望「ページ数を指定しているけれど、
  /// 後から変えられるなら実装して」/「ヘッダーから指定できるように」)。
  ///
  /// [want] が 0 なら AI が必要なだけ分ける (= ユーザー要望: おまかせ)。
  /// 生成の時と同じで、 AI の出力は 1 本の文書として返り、 それを
  /// 「<<<PAGE: 名前>>>」 で区切ってタブへ割り振っている。 なので今ある
  /// 内容をまとめて渡し直し、 分け直してもらう。
  /// 内容そのものは足し引きせず、 まとめ方だけ変える。
  Future<void> _changeTabCount(int want) async {
    if (_aiBusy || !mounted) return;
    final provider = widget.provider;
    final doc = _joinTabsAsDocument();
    if (doc.trim().isEmpty) return;
    setState(() => _aiBusy = true);
    try {
      final pageRule = want == 1
          ? '- 区切りは入れず、 1 本の文書としてまとめてください。'
          : want <= 0
              ? '''
- 内容の量とまとまりを見て、 **あなたが適切と考える数**のページに
  分け直してください (無理に分けず、 1 本のままが良ければそれでも構いません)。
- 分ける場合は各ページの先頭に「<<<PAGE: ページ名>>>」 という行を必ず
  置いてください。
- 1 ページ目は目次・全体像とし、 他のページへは
  「[ページ名](tab:ページ名)」 の形でリンクを張ってください。'''
              : '''
- 内容を $want 個のページに分け直してください。
- 各ページの先頭に「<<<PAGE: ページ名>>>」 という行を必ず置いてください。
- 1 ページ目は目次・全体像とし、 他のページへは
  「[ページ名](tab:ページ名)」 の形でリンクを張ってください。''';
      final head = want <= 0
          ? '次の Markdown 文書を、 **内容を減らさずに** 読みやすい単位へ\n分け直してください。'
          : '次の Markdown 文書を、 **内容を減らさずに** $want ページへ分け直して\nください。';
      final prompt = '''${provider.languageInstructionForAi()}
$head Markdown 本文だけを出力してください (前置き・説明は不要)。

【分け方】
$pageRule
- 元の文章・表・図 (mermaid)・画像はできるだけそのまま残し、 割り振りと
  見出しの調整だけを行ってください。 新しい話題を足す必要はありません。

$_kMdStyleRules

【今の文書】
$doc''';
      final out = (await provider.askAi(prompt)).trim();
      if (!mounted) return;
      if (out.isEmpty) throw Exception(provider.t('md.aiEmpty'));
      var body = out;
      final fence = RegExp(r'^```[a-zA-Z]*\s*\n([\s\S]*?)\n?```$');
      final m = fence.firstMatch(body.trim());
      if (m != null) body = m.group(1) ?? body;
      body = await _resolveMarkdownImages(body);
      if (!mounted) return;
      setState(() => _aiBusy = false);
      // 見てから決めてもらう (生成の時と同じ流れ)。
      final r = await _confirmAiResult(body);
      if (!mounted || r == null) return;
      final result = r.body;
      if (r.action == 'draft') {
        await _saveMarkdownDraft(result);
        return;
      }
      if (r.action != 'replace') return;
      final split = _splitMarkdownPages(result);
      if (split.length > 1) {
        // 分け直しなので、 余ったタブは残さず作り直す。
        setState(() {
          _sel = 0;
          _tabs
            ..clear()
            ..add(_MdTab(
                id: 'md${DateTime.now().microsecondsSinceEpoch}',
                name: split.first.name.isEmpty ? '1' : split.first.name,
                text: split.first.text));
        });
        await _applyMarkdownPages(split);
      } else {
        setState(() {
          _sel = 0;
          _tabs
            ..clear()
            ..add(_MdTab(
                id: 'md${DateTime.now().microsecondsSinceEpoch}',
                name: widget.provider.currentPage.name,
                text: result));
          _ctrl.text = result;
        });
        _autoNamePageFromMarkdown(result);
        await _saveNow();
        _scheduleRender();
      }
    } catch (e) {
      if (!mounted) return;
      setState(() => _aiBusy = false);
      _appSnackTop(context, '$e'.replaceFirst('Exception: ', ''),
          const Color(0xFFE57373));
    }
  }

  /// 「<<<PAGE: 名前>>>」 で区切られた本文を、 (名前, 中身) に分ける。
  /// 区切りが無ければ 1 つだけ返す (= 今までどおり)。
  List<({String name, String text})> _splitMarkdownPages(String body) {
    final re = RegExp(r'^<<<PAGE:\s*(.+?)\s*>>>\s*$', multiLine: true);
    final hits = re.allMatches(body).toList();
    if (hits.isEmpty) {
      return [(name: '', text: body)];
    }
    final out = <({String name, String text})>[];
    for (var i = 0; i < hits.length; i++) {
      final m = hits[i];
      final end = i + 1 < hits.length ? hits[i + 1].start : body.length;
      final text = body.substring(m.end, end).trim();
      final name = (m.group(1) ?? '').trim();
      if (text.isEmpty) continue;
      out.add((name: name.isEmpty ? '${i + 1}' : name, text: text));
    }
    return out.isEmpty ? [(name: '', text: body)] : out;
  }

  /// 分けて書かれたページをタブへ割り振る (= ユーザー要望)。
  /// 1 枚目は今開いているタブに入れ、 残りは新しいタブへ。
  Future<void> _applyMarkdownPages(
      List<({String name, String text})> pages) async {
    _syncCurrentTab();
    setState(() {
      _tabs[_sel]
        ..name =
            pages.first.name.isEmpty ? _tabs[_sel].name : pages.first.name
        ..text = pages.first.text;
      _ctrl.text = pages.first.text;
      for (final p in pages.sublist(1)) {
        var name = p.name.isEmpty ? '${_tabs.length + 1}' : p.name;
        // 同じ名前が既にあれば番号を足す (リンクの行き先が迷子にならないように、
        //   なるべく元の名前を保つ)。
        var k = 2;
        while (_tabs.any((t) => t.name == name)) {
          name = '${p.name} ($k)';
          k++;
        }
        _tabs.add(_MdTab(
            id: 'md${DateTime.now().microsecondsSinceEpoch}_${_tabs.length}',
            name: name,
            text: p.text));
      }
    });
    // 内容に合わせてページ名も付け直す (= ユーザー要望)。
    _autoNamePageFromMarkdown(pages.first.text);
    await _saveNow();
    _scheduleRender();
    if (!mounted) return;
    _appSnackTop(
        context,
        widget.provider
            .t('md.pagesCreated')
            .replaceFirst('{n}', '${pages.length}'),
        const Color(0xFF43B97F));
  }

  /// クリップボードの画像を取り込む (= ユーザー要望: Ctrl+V で貼れるように)。
  /// 画像でなければ null (文字はそのまま入力欄へ入る)。
  Future<AiInputImage?> _pasteImageForAi() async {
    try {
      final host = context.findAncestorStateOfType<_MindMapScreenState>();
      final bytes = await host?.readClipboardImageBytes();
      if (bytes == null || bytes.isEmpty) return null;
      return AiInputImage(
        mime: 'image/png',
        base64: base64Encode(bytes),
        name: 'clipboard.png',
      );
    } catch (_) {
      return null;
    }
  }

  /// どこをどう直してほしいかを聞く (= ユーザー要望: 追加で修正依頼)。

  /// 今の内容に、 頼まれた直しを当てて書き直してもらう。
  Future<String> _reviseMarkdown(String body, String order) async {
    final provider = widget.provider;
    final prompt = '''${provider.languageInstructionForAi()}
次の Markdown 文書に、 指示された直しを反映して**全文を書き直して**ください。
直しに関係のない部分は変えないでください。
Markdown 本文だけを出力してください (前置き・説明・全体のコードフェンスは不要)。

【直してほしいこと】
$order

【今の文書】
$body''';
    final out = (await provider.askAi(prompt)).trim();
    if (out.isEmpty) throw Exception(provider.t('md.aiEmpty'));
    var fixed = out;
    final fence = RegExp(r'^```[a-zA-Z]*\s*\n([\s\S]*?)\n?```$');
    final m = fence.firstMatch(fixed.trim());
    if (m != null) fixed = m.group(1) ?? fixed;
    return fixed;
  }

  /// 下書きとして保存する (= ユーザー要望: タブに埋め込むのではなく、
  /// 下書きのまま残して後から呼び出し、 直してから反映できるように)。
  Future<void> _saveMarkdownDraft(String body) async {
    final provider = widget.provider;
    final ctrl = TextEditingController(
        text: '${provider.t('md.draftTabName')} '
            '${DateTime.now().toString().substring(5, 16)}');
    final name = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('md.aiDraftBtn'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: SizedBox(
          width: 360,
          child: TextField(
            controller: ctrl,
            autofocus: true,
            style: const TextStyle(color: Colors.white),
            decoration: InputDecoration(
              labelText: provider.t('md.draftName'),
              labelStyle:
                  const TextStyle(color: Colors.white38, fontSize: 12),
              enabledBorder: const UnderlineInputBorder(
                  borderSide: BorderSide(color: Colors.white24)),
            ),
            onSubmitted: (v) => Navigator.pop(dctx, v.trim()),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF7FD8A0),
                foregroundColor: Colors.black),
            onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
            child: Text(provider.t('btn.save')),
          ),
        ],
      ),
    );
    ctrl.dispose();
    if (name == null || !mounted) return;
    await _MarkdownDraftStore.add(
        widget.pageId, name.isEmpty ? provider.t('md.draftTabName') : name,
        body);
    if (!mounted) return;
    setState(() {});
    _appSnackTop(context, provider.t('md.draftSaved'),
        const Color(0xFF43B97F));
  }

  /// 保存した下書きの一覧 (= ユーザー要望: 後で呼び出して直してから反映)。
  Future<void> _openDraftList() async {
    final provider = widget.provider;
    var drafts = await _MarkdownDraftStore.load(widget.pageId);
    if (!mounted) return;
    await showDialog<void>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        Future<void> reload() async {
          drafts = await _MarkdownDraftStore.load(widget.pageId);
          if (dctx.mounted) setD(() {});
        }

        return AlertDialog(
          backgroundColor: const Color(0xFF1A1A2E),
          title: Row(children: [
            const Icon(Icons.drafts_outlined,
                color: Color(0xFF7FD8A0), size: 19),
            const SizedBox(width: 8),
            Text(provider.t('md.draftListTitle'),
                style: const TextStyle(color: Colors.white, fontSize: 15)),
          ]),
          content: SizedBox(
            width: math.min(MediaQuery.sizeOf(dctx).width - 120, 900.0),
            height: math.min(MediaQuery.sizeOf(dctx).height - 200, 620.0),
            child: drafts.isEmpty
                ? Center(
                    child: Text(provider.t('md.draftNone'),
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 12)),
                  )
                : ListView.separated(
                    itemCount: drafts.length,
                    separatorBuilder: (_, __) =>
                        const Divider(color: Colors.white10, height: 1),
                    itemBuilder: (_, i) {
                      final d = drafts[i];
                      return ListTile(
                        dense: true,
                        title: Text(d.name,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: Colors.white, fontSize: 13)),
                        subtitle: Text(
                            '${d.text.trim().runes.length} '
                            '${provider.t('drawer.charSuffix')}  ·  '
                            '${d.at.substring(0, 16)}',
                            style: const TextStyle(
                                color: Colors.white38, fontSize: 10.5)),
                        trailing:
                            Row(mainAxisSize: MainAxisSize.min, children: [
                          // 中身を見て、 直して、 反映する。
                          IconButton(
                            tooltip: provider.t('md.draftOpen'),
                            icon: const Icon(Icons.visibility_rounded,
                                color: Color(0xFF7FD8A0), size: 18),
                            onPressed: () async {
                              Navigator.pop(dctx);
                              await _reviewDraft(d);
                            },
                          ),
                          IconButton(
                            tooltip: provider.t('act.delete'),
                            icon: const Icon(Icons.delete_outline_rounded,
                                color: Color(0xFFE57373), size: 18),
                            onPressed: () async {
                              await _MarkdownDraftStore.removeAt(
                                  widget.pageId, i);
                              await reload();
                            },
                          ),
                        ]),
                      );
                    },
                  ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.close'),
                  style: const TextStyle(color: Colors.white54)),
            ),
          ],
        );
      }),
    );
  }

  /// 下書きをプレビューで見て、 直して、 反映する。
  ///
  /// 直す時もプレビューは開いたまま (= ユーザー報告)。 直った内容が返る。
  Future<void> _reviewDraft(({String name, String text, String at}) d) async {
    final r = await _confirmAiResult(d.text);
    if (!mounted || r == null) return;
    final current = r.body;
    if (r.action == 'draft') {
      // 直した内容を下書きとして上書き保存し直す。
      await _MarkdownDraftStore.replace(widget.pageId, d.name, current);
      if (!mounted) return;
      _appSnackTop(context, widget.provider.t('md.draftSaved'),
          const Color(0xFF43B97F));
      return;
    }
    if (r.action != 'replace') return;
    // 本文へ反映。 複数ページの下書きはタブへ割り振る
    // (= 下書き保存の時はタブに足さず、 反映の時に初めて分ける)。
    final split = _splitMarkdownPages(current);
    if (split.length > 1) {
      await _applyMarkdownPages(split);
      return;
    }
    setState(() => _ctrl.text = current);
    // 内容に合わせてページ名も付け直す (= ユーザー要望)。
    _autoNamePageFromMarkdown(current);
    _onChanged();
  }

  /// AI の結果を見せて、 どうするか決めてもらう。
  ///
  /// ★ 「追加で修正を頼む」 はこの画面を**閉じずに**その場で受け付ける
  ///   (= ユーザー報告: 直したいのはプレビューの中身なのに、 画面が閉じて
  ///    しまうと見ながら指示が出せない)。 直った内容はこの画面のまま
  ///    描き直し、 最後に選んだ操作と一緒に返す。
  Future<({String action, String body})?> _confirmAiResult(
      String body) async {
    final provider = widget.provider;
    final hasContent = _ctrl.text.trim().isNotEmpty;
    var current = body;
    var reviseOpen = false;
    var revising = false;
    final orderCtrl = TextEditingController();
    // 見た目でも確かめられるよう、 同じ描画で 1 枚出す。
    // ★ CDN 参照のままだと file:// では外部スクリプトが読めず真っ白になる
    //   (= ユーザー報告)。 本文のプレビューと同じく同梱の JS を指す。
    String htmlFor(String src) => _markdownPreviewHtml(
        src, provider.isDarkMode,
        markedSrc: 'marked.min.js',
        mermaidSrc: 'mermaid.min.js',
        hljsSrc: 'highlight.min.js',
        hljsCssSrc:
            provider.isDarkMode ? 'hljs-dark.css' : 'hljs-light.css',
        mathjaxSrc: 'tex-svg.js',
        tocLabel: provider.t('md.toc'));
    final act = await showDialog<String>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        // その場で直してもらう (画面は開いたまま)。
        Future<void> runRevise() async {
          final order = orderCtrl.text.trim();
          if (order.isEmpty || revising) return;
          setD(() => revising = true);
          try {
            final fixed = await _reviseMarkdown(current, order);
            if (fixed.trim().isNotEmpty) {
              final resolved = await _resolveMarkdownImages(fixed);
              current = resolved;
              orderCtrl.clear();
            }
          } catch (e) {
            if (mounted) {
              _appSnackTop(context, '$e'.replaceFirst('Exception: ', ''),
                  const Color(0xFFE57373));
            }
          }
          if (dctx.mounted) {
            setD(() {
              revising = false;
              reviseOpen = false;
            });
          }
        }

        return Dialog(
        backgroundColor: const Color(0xFF1A1A2E),
        // = ユーザー要望: 表示領域をもっと大きく。 画面いっぱいに近づける。
        insetPadding: const EdgeInsets.all(14),
        child: ConstrainedBox(
          constraints: BoxConstraints(
              maxWidth: MediaQuery.sizeOf(dctx).width - 28,
              maxHeight: MediaQuery.sizeOf(dctx).height - 28),
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 14, 8, 8),
              child: Row(children: [
                const Icon(Icons.fact_check_outlined,
                    color: Color(0xFFBA68C8), size: 19),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(provider.t('md.aiConfirmTitle'),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 15,
                          fontWeight: FontWeight.w700)),
                ),
                IconButton(
                  tooltip: provider.t('btn.close'),
                  icon: const Icon(Icons.close_rounded,
                      color: Colors.white54, size: 20),
                  onPressed: () => Navigator.pop(dctx),
                ),
              ]),
            ),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text(provider.t('md.aiConfirmHint'),
                    style:
                        const TextStyle(color: Colors.white54, fontSize: 12)),
              ),
            ),
            const SizedBox(height: 10),
            // 左に元の書式、 右に見た目。 どちらも読める形で確かめられる。
            Flexible(
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 16),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Expanded(
                      child: Container(
                        color: const Color(0xFF14141F),
                        padding: const EdgeInsets.all(10),
                        child: SingleChildScrollView(
                          child: SelectableText(current,
                              style: const TextStyle(
                                  color: Colors.white70,
                                  fontSize: 12,
                                  height: 1.5,
                                  fontFamily: 'Consolas')),
                        ),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      // 直ったら中身が変わるので、 鍵を変えて描き直す。
                      child: _MarkdownConfirmPreview(
                          key: ValueKey(current.hashCode),
                          html: htmlFor(current)),
                    ),
                  ],
                ),
              ),
            ),
            // ── その場で直してもらう欄 (= ユーザー要望: プレビューを
            //    閉じずに指示を出せるように) ──
            if (reviseOpen)
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 10, 16, 0),
                child: Row(children: [
                  Expanded(
                    child: TextField(
                      controller: orderCtrl,
                      autofocus: true,
                      enabled: !revising,
                      minLines: 1,
                      maxLines: 3,
                      style: const TextStyle(
                          color: Colors.white, fontSize: 13),
                      decoration: InputDecoration(
                        isDense: true,
                        filled: true,
                        fillColor: Colors.white.withValues(alpha: 0.06),
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(10),
                          borderSide: BorderSide.none,
                        ),
                        hintText: provider.t('md.aiReviseHint'),
                        hintStyle: const TextStyle(
                            color: Colors.white30, fontSize: 12),
                      ),
                      onSubmitted: (_) => unawaited(runRevise()),
                    ),
                  ),
                  const SizedBox(width: 8),
                  ElevatedButton.icon(
                    style: ElevatedButton.styleFrom(
                        backgroundColor: const Color(0xFFBA68C8),
                        foregroundColor: Colors.white),
                    icon: revising
                        ? const SizedBox(
                            width: 14,
                            height: 14,
                            child: CircularProgressIndicator(
                                strokeWidth: 2, color: Colors.white))
                        : const Icon(Icons.send_rounded, size: 16),
                    label: Text(provider.t('md.aiReviseRun')),
                    onPressed: revising ? null : () => unawaited(runRevise()),
                  ),
                ]),
              ),
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 12),
              child: Row(children: [
                const Spacer(),
                TextButton(
                  onPressed: () => Navigator.pop(dctx),
                  child: Text(provider.t('btn.cancel'),
                      style: const TextStyle(color: Colors.white54)),
                ),
                const SizedBox(width: 6),
                // ── 気になる所を直してもらう (= ユーザー要望: 続きに足すより
                //    追加で修正を頼めるほうが使う)。 画面は閉じずに、
                //    下に入力欄を出す (= ユーザー報告)。 ──
                OutlinedButton.icon(
                  style: OutlinedButton.styleFrom(
                      foregroundColor: const Color(0xFFBA68C8),
                      side: const BorderSide(color: Color(0xFFBA68C8))),
                  icon: const Icon(Icons.auto_fix_high_rounded, size: 17),
                  label: Text(provider.t('md.aiReviseBtn')),
                  onPressed: revising
                      ? null
                      : () => setD(() => reviseOpen = !reviseOpen),
                ),
                const SizedBox(width: 6),
                // ── 下書きとして残す (= ユーザー要望) ──
                OutlinedButton.icon(
                  style: OutlinedButton.styleFrom(
                      foregroundColor: const Color(0xFF7FD8A0),
                      side: const BorderSide(color: Color(0xFF7FD8A0))),
                  icon: const Icon(Icons.save_outlined, size: 17),
                  label: Text(provider.t('md.aiDraftBtn')),
                  onPressed: () => Navigator.pop(dctx, 'draft'),
                ),
                const SizedBox(width: 8),
                ElevatedButton.icon(
                  style: ElevatedButton.styleFrom(
                      backgroundColor: const Color(0xFFBA68C8),
                      foregroundColor: Colors.white),
                  icon: const Icon(Icons.check_rounded, size: 17),
                  label: Text(provider.t(
                      hasContent ? 'md.aiReplaceBtn' : 'md.aiUseBtn')),
                  onPressed: () => Navigator.pop(dctx, 'replace'),
                ),
              ]),
            ),
          ]),
        ),
      );
      }),
    );
    orderCtrl.dispose();
    if (act == null) return null;
    return (action: act, body: current);
  }

  void _appSnackTop(BuildContext ctx, String msg, Color color) {
    ScaffoldMessenger.maybeOf(ctx)?.showSnackBar(SnackBar(
      content: Text(msg),
      backgroundColor: color,
      duration: const Duration(seconds: 4),
    ));
  }

  Future<void> _copyAll() async {
    await Clipboard.setData(ClipboardData(text: _ctrl.text));
    if (!mounted) return;
    _appSnackTop(context, widget.provider.t('md.copied'),
        const Color(0xFF43B97F));
  }

  /// .md ファイルとして書き出す。
  Future<void> _exportMd() async {
    try {
      final baseName = _fileMode
          ? widget.filePath!.replaceAll('\\', '/').split('/').last
          : '${widget.provider.currentPage.name.replaceAll(RegExp(r'[\\/:*?"<>|]'), '_')}.md';
      // 既定の保存先は Download フォルダー (= ユーザー要望)。
      String? initialDir;
      try {
        initialDir = (await getDownloadsDirectory())?.path;
      } catch (_) {}
      final path = await FilePicker.platform.saveFile(
        dialogTitle: widget.provider.t('md.export'),
        fileName: baseName,
        initialDirectory: initialDir,
      );
      if (path == null) return;
      await File(path).writeAsString(_ctrl.text);
      if (!mounted) return;
      _appSnackTop(context, path, const Color(0xFF43B97F));
    } catch (e) {
      if (!mounted) return;
      _appSnackTop(context, '$e', const Color(0xFFE57373));
    }
  }

  /// 外のファイルを読み込む (= ユーザー要望: 書き出しはできるのに
  /// 読み込みができない)。 今のタブへ「差し替え」 か「末尾に足す」 かを聞く。
  Future<void> _importMd() async {
    try {
      final res = await FilePicker.platform.pickFiles(
        type: FileType.custom,
        allowedExtensions: const [
          'md', 'markdown', 'txt', 'text', 'log', 'csv'
        ],
        withData: true,
      );
      if (res == null || res.files.isEmpty || !mounted) return;
      final f = res.files.first;
      String text;
      if (f.bytes != null) {
        text = utf8.decode(f.bytes!, allowMalformed: true);
      } else if (f.path != null) {
        text = await File(f.path!).readAsString();
      } else {
        return;
      }
      if (!mounted) return;
      final mode = _ctrl.text.trim().isEmpty
          ? 'replace'
          : await showDialog<String>(
              context: context,
              builder: (dctx) => AlertDialog(
                backgroundColor: const Color(0xFF1E1E32),
                title: Text('${f.name} を読み込みます',
                    style:
                        const TextStyle(color: Colors.white, fontSize: 15)),
                content: const Text('今の内容をどうしますか？',
                    style: TextStyle(color: Colors.white70, fontSize: 13)),
                actions: [
                  TextButton(
                    onPressed: () => Navigator.pop(dctx),
                    child: const Text('やめる',
                        style: TextStyle(color: Colors.white54)),
                  ),
                  TextButton(
                    onPressed: () => Navigator.pop(dctx, 'append'),
                    child: const Text('末尾に足す'),
                  ),
                  ElevatedButton(
                    style: ElevatedButton.styleFrom(
                        backgroundColor: const Color(0xFF6C63FF),
                        foregroundColor: Colors.white),
                    onPressed: () => Navigator.pop(dctx, 'replace'),
                    child: const Text('差し替える'),
                  ),
                ],
              ),
            );
      if (mode == null || !mounted) return;
      setState(() {
        _ctrl.text = mode == 'append'
            ? '${_ctrl.text}\n\n$text'
            : text;
        _ctrl.selection =
            TextSelection.collapsed(offset: _ctrl.text.length);
      });
      _onChanged();
      if (!mounted) return;
      _appSnackTop(context, '${f.name} を読み込みました',
          const Color(0xFF43B97F));
    } catch (e) {
      if (!mounted) return;
      _appSnackTop(context, '$e', const Color(0xFFE57373));
    }
  }

  /// タブの列 (= ユーザー要望: 1 ページに何個もタブを作れるように)。
  /// タブ (ページ名) の並び。 ヘッダーの 1 段に収めるため、 帯の装飾は
  /// 付けない (= ユーザー要望: 2 段に分けない)。
  ///
  /// 操作 (= ユーザー要望):
  ///   ・ダブルクリック / 選んで F2 → 名前を変える
  ///   ・ドラッグ → 好きな位置へ並べ替え
  ///   ・右クリック (長押し) → 削除だけ
  ///   ・ホバー中のホイール → 左右にスクロール
  Widget _buildTabStrip(MindMapProvider provider) {
    Widget tabChip(int i, {bool dragging = false}) {
      final on = i == _sel;
      return Container(
        // ★ alignment を付けた Container は横幅いっぱい (maxWidth の 190px)
        //   まで広がってしまい、 タブが 1 つの時に馬鹿でかいピルになって
        //   いた (= ユーザー報告)。 Center(widthFactor: 1) で文字の幅に
        //   縮めつつ、 縦だけ中央に置く。
        margin: const EdgeInsets.symmetric(horizontal: 2, vertical: 3),
        padding: const EdgeInsets.symmetric(horizontal: 10),
        decoration: BoxDecoration(
          color: dragging
              ? const Color(0xFF3C3C6E)
              : on
                  ? const Color(0xFF32325A)
                  : Colors.transparent,
          borderRadius: BorderRadius.circular(8),
          border: Border.all(
              color: on ? const Color(0xFFBA68C8) : Colors.white24),
        ),
        child: Center(
          widthFactor: 1,
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 170),
            child: Text(
              _tabs[i].name.isEmpty ? '-' : _tabs[i].name,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                  color: on ? Colors.white : Colors.white60,
                  fontSize: 11.5,
                  fontWeight: on ? FontWeight.w700 : FontWeight.w400),
            ),
          ),
        ),
      );
    }

    return SizedBox(
      // スクロールバーのぶんだけ高さを取る (= ユーザー要望: 入り切らない時は
      //   左右にスクロールして見られるように)。
      height: 34,
      // ── スクロールバーはカーソルを乗せた時だけ出す (= ユーザー要望) ──
      child: MouseRegion(
        onEnter: (_) {
          if (!_tabStripHover) setState(() => _tabStripHover = true);
        },
        onExit: (_) {
          if (_tabStripHover) setState(() => _tabStripHover = false);
        },
        // ── 縦ホイールで左右に動かす (= ユーザー要望) ──
        child: Listener(
          onPointerSignal: (sig) {
            if (sig is! PointerScrollEvent) return;
            if (!_tabScroll.hasClients) return;
            final d = sig.scrollDelta;
            // 縦の回転量を横移動に読み替える (横ホイールがあればそちらを優先)。
            final delta = d.dx.abs() > d.dy.abs() ? d.dx : d.dy;
            if (delta == 0) return;
            final p = _tabScroll.position;
            _tabScroll.jumpTo(
                (p.pixels + delta).clamp(0.0, p.maxScrollExtent));
          },
          child: ScrollConfiguration(
        // マウスでもドラッグしてスクロールできるようにする。
        behavior: _AlwaysDraggableScrollBehavior(),
        child: Scrollbar(
          controller: _tabScroll,
          thumbVisibility: _tabStripHover,
          thickness: 4,
          radius: const Radius.circular(2),
          child: ListView.builder(
        controller: _tabScroll,
        scrollDirection: Axis.horizontal,
        // 末尾に「+」 を 1 つ足す (= ユーザー要望: タブの追加ボタンは
        // 一番右端のタブの右側に置く)。
        // 末尾に「×」 (今のタブを消す) と「+」 を並べる
        // (= ユーザー要望: × は + の左側に置く)。
        itemCount: _tabs.length + 2,
        itemBuilder: (_, i) {
          if (i == _tabs.length) {
            // ── 今のタブを消す (+ のすぐ左) ──
            final canDelete = _tabs.length > 1;
            return Tooltip(
              message: provider.t('md.tabDelete'),
              child: InkWell(
                borderRadius: BorderRadius.circular(8),
                onTap: canDelete ? () => unawaited(_deleteTab(_sel)) : null,
                child: Container(
                  margin:
                      const EdgeInsets.symmetric(horizontal: 2, vertical: 3),
                  padding: const EdgeInsets.symmetric(horizontal: 8),
                  alignment: Alignment.center,
                  child: Icon(Icons.close_rounded,
                      size: 16,
                      color: canDelete ? Colors.white54 : Colors.white24),
                ),
              ),
            );
          }
          if (i == _tabs.length + 1) {
            return Tooltip(
              message: provider.t('md.tabAdd'),
              child: InkWell(
                borderRadius: BorderRadius.circular(8),
                onTap: _addTab,
                child: Container(
                  margin:
                      const EdgeInsets.symmetric(horizontal: 2, vertical: 3),
                  padding: const EdgeInsets.symmetric(horizontal: 8),
                  alignment: Alignment.center,
                  child: const Icon(Icons.add_rounded,
                      size: 16, color: Colors.white54),
                ),
              ),
            );
          }
          // ドラッグで好きな位置へ動かせる (= ユーザー要望: 左へ / 右へ
          //   のメニューではなく、 掴んで並べ替える)。
          return DragTarget<int>(
            onWillAcceptWithDetails: (d) => d.data != i,
            onAcceptWithDetails: (d) => _reorderTab(d.data, i),
            builder: (_, cand, __) => Opacity(
              // 落とし先として狙われている間は薄く光らせる。
              opacity: cand.isEmpty ? 1 : 0.6,
              child: Draggable<int>(
                data: i,
                axis: Axis.horizontal,
                dragAnchorStrategy: pointerDragAnchorStrategy,
                feedback: Material(
                  color: Colors.transparent,
                  child: Opacity(
                      opacity: 0.9, child: tabChip(i, dragging: true)),
                ),
                childWhenDragging:
                    Opacity(opacity: 0.3, child: tabChip(i)),
                child: GestureDetector(
                  // 右クリック / 長押し → 削除だけ (= ユーザー要望)。
                  onSecondaryTapDown: (d) =>
                      _showTabMenu(i, d.globalPosition),
                  child: InkWell(
                    onTap: () => _selectTab(i),
                    onDoubleTap: () => unawaited(_renameTab(i)),
                    child: tabChip(i),
                  ),
                ),
              ),
            ),
          );
        },
          ),
        ),
        ),
        ),
      ),
    );
  }

  /// タブを [from] から [to] の位置へ動かす (ドラッグの並べ替え)。
  void _reorderTab(int from, int to) {
    if (from == to || from < 0 || from >= _tabs.length) return;
    if (to < 0 || to >= _tabs.length) return;
    _syncCurrentTab();
    setState(() {
      final moving = _tabs.removeAt(from);
      _tabs.insert(to, moving);
      // 選んでいたタブを追いかける。
      if (_sel == from) {
        _sel = to;
      } else if (from < _sel && to >= _sel) {
        _sel--;
      } else if (from > _sel && to <= _sel) {
        _sel++;
      }
    });
    // ignore: discarded_futures
    _saveNow();
  }

  /// タブのメニュー。 [at] は押された場所 (画面座標)。
  ///
  /// ★ 以前は画面の左上あたりに決め打ちで出していたので、 どのタブを
  ///   押しても同じ場所に出ていた (= ユーザー報告)。 押した場所に出す。
  Future<void> _showTabMenu(int i, [Offset? at]) async {
    final provider = widget.provider;
    final overlay =
        Overlay.of(context).context.findRenderObject() as RenderBox?;
    var origin = at;
    if (origin == null) {
      final box = context.findRenderObject() as RenderBox?;
      origin = box == null
          ? Offset.zero
          : box.localToGlobal(const Offset(60, 40));
    }
    final act = await showMenu<String>(
      context: context,
      color: const Color(0xFF1E1E32),
      position: RelativeRect.fromRect(
          origin & const Size(1, 1),
          Offset.zero & (overlay?.size ?? const Size(1920, 1080))),
      // ★ 出すのは削除だけ (= ユーザー要望)。 名前の変更はダブルクリック
      //   または F2、 並べ替えはドラッグで行う。
      items: [
        PopupMenuItem(
            value: 'del',
            child: Text(provider.t('act.delete'),
                style:
                    const TextStyle(color: Color(0xFFE57373), fontSize: 13))),
      ],
    );
    if (!mounted) return;
    if (act == 'del') await _deleteTab(i);
  }

  Widget _btn(IconData icon, String tip, VoidCallback? onTap,
          {Color? color}) =>
      IconButton(
        padding: EdgeInsets.zero,
        constraints: const BoxConstraints(minWidth: 34, minHeight: 34),
        tooltip: tip,
        icon: Icon(icon, size: 19, color: color ?? Colors.white70),
        onPressed: onTap,
      );

  @override
  Widget build(BuildContext context) {
    final provider = widget.provider;
    if (!_loaded) {
      return const Center(
          child: CircularProgressIndicator(color: Color(0xFFBA68C8)));
    }
    final narrow = MediaQuery.of(context).size.width < 720;
    final editorField = Container(
      color: const Color(0xFF14141F),
      child: TextField(
        controller: _ctrl,
        maxLines: null,
        expands: true,
        textAlignVertical: TextAlignVertical.top,
        style: const TextStyle(
            color: Colors.white,
            fontSize: 13,
            height: 1.6,
            fontFamily: 'Consolas'),
        cursorColor: const Color(0xFFBA68C8),
        decoration: InputDecoration(
          contentPadding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
          border: InputBorder.none,
          hintText: provider.t('mdPage.hint'),
          hintStyle: const TextStyle(color: Colors.white30, fontSize: 12.5),
        ),
        onChanged: (_) => _onChanged(),
      ),
    );
    // タブ列はヘッダー側 (全幅) へ移した (= ユーザー要望: 開いている
    //   ページをヘッダーに出す)。 ここは本文だけ。
    final editor = editorField;

    Widget preview;
    if (_isDesktopPlatform) {
      if (_winReady && _win != null) {
        preview = wv_win.Webview(_win!);
      } else if (_winFailed) {
        // WebView2 が使えない環境: 素のテキストをそのまま出して、 編集は
        //   続けられるようにする (= ユーザー要望: エラーを出しっぱなしにしない)。
        preview = Container(
          color: const Color(0xFF14141F),
          padding: const EdgeInsets.all(14),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(children: [
                const Icon(Icons.info_outline_rounded,
                    color: Color(0xFFFFB347), size: 15),
                const SizedBox(width: 6),
                Expanded(
                  child: Text(provider.t('md.previewUnavailable'),
                      style: const TextStyle(
                          color: Colors.white54, fontSize: 11)),
                ),
              ]),
              const SizedBox(height: 8),
              Expanded(
                child: SingleChildScrollView(
                  child: SelectableText(_ctrl.text,
                      style: const TextStyle(
                          color: Colors.white70,
                          fontSize: 12.5,
                          height: 1.5,
                          fontFamily: 'Consolas')),
                ),
              ),
            ],
          ),
        );
      } else {
        preview = const Center(
            child: SizedBox(
                width: 22,
                height: 22,
                child: CircularProgressIndicator(
                    strokeWidth: 2, color: Color(0xFFBA68C8))));
      }
    } else {
      preview = iaw.InAppWebView(
        initialSettings: iaw.InAppWebViewSettings(
          javaScriptEnabled: true,
          transparentBackground: true,
        ),
        onWebViewCreated: (c) {
          _iaw = c;
          // プレビューの中で押されたリンクを受け取る (= ユーザー要望)。
          c.addJavaScriptHandler(
              handlerName: 'mmbridge',
              callback: (args) {
                if (args.isNotEmpty) _onPreviewMessage(args.first);
                return null;
              });
          _render();
        },
      );
    }

    return CallbackShortcuts(
      // F2 で選んでいるタブの名前を変える (= ユーザー要望: ダブルクリック
      //   または選択して F2)。
      // Ctrl+Z は消したタブを戻す (= ユーザー要望: 確認を出さない代わり)。
      //   本文の取り消しは編集欄が自分で処理するので、 ここへは来ない。
      bindings: {
        const SingleActivator(LogicalKeyboardKey.f2): () {
          if (_sel >= 0 && _sel < _tabs.length) unawaited(_renameTab(_sel));
        },
        const SingleActivator(LogicalKeyboardKey.keyZ, control: true):
            _undoDeleteTab,
        const SingleActivator(LogicalKeyboardKey.keyZ, meta: true):
            _undoDeleteTab,
      },
      child: Listener(
        // 設定の窓を押した所の近くに出すため、 位置を控える (= ユーザー要望)。
        onPointerDown: (e) => _lastPointerPos = e.position,
        child: Container(
      color: const Color(0xFF10101A),
      child: Column(children: [
        // ── ツールバー (隠せる = ユーザー要望) ──
        if (_headerHidden)
          MouseRegion(
            onEnter: (_) => setState(() => _headerHover = true),
            onExit: (_) => setState(() => _headerHover = false),
            // ── 格納しても高さは変えない (= ユーザー要望: 細くなると
            //    カーソルを合わせづらい)。 ボタンだけ消した同じ高さの帯を
            //    残し、 ホバー (タップ) で「表示する」 ボタンを出す。 ──
            child: GestureDetector(
              onTap: () {
                setState(() => _headerHidden = false);
                // ignore: discarded_futures
                SharedPreferences.getInstance()
                    .then((sp) => sp.setBool(_kMdHeaderHiddenKey, false));
              },
              child: Container(
                height: narrow ? 78 : 42,
                width: double.infinity,
                decoration: const BoxDecoration(
                  color: Color(0xFF1A1A2E),
                  border: Border(
                      bottom: BorderSide(color: Colors.white12, width: 1)),
                ),
                alignment: Alignment.centerRight,
                child: _headerHover
                    ? _btn(Icons.keyboard_double_arrow_down_rounded,
                        provider.t('md.showHeader'), () {
                        setState(() => _headerHidden = false);
                        // ignore: discarded_futures
                        SharedPreferences.getInstance().then(
                            (sp) => sp.setBool(_kMdHeaderHiddenKey, false));
                      })
                    : const SizedBox.shrink(),
              ),
            ),
          )
        else
        Container(
          // モバイルは 2 段 (タブ + AI 中央 / 道具の列) なので高くする。
          height: narrow ? 78 : 42,
          padding: const EdgeInsets.symmetric(horizontal: 6),
          decoration: const BoxDecoration(
            color: Color(0xFF1A1A2E),
            border:
                Border(bottom: BorderSide(color: Colors.white12, width: 1)),
          ),
          child: _mdHeaderRow(provider, narrow),
        ),
        Expanded(
          // ── 左右のパネル (メモ / AI チャット) を本文の外側に置く
          //    (= ユーザー要望)。 デスクトップだけ。 ──
          child: Row(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            if (_isDesktopPlatform && _memoOpen)
              _buildSideMemoPanel(provider),
            Expanded(
              child: !_preview
              // 狭い画面は「並べる」 を使わない (= ユーザー要望: 上下分割
              // だと表示領域が狭まり過ぎる)。 前の設定が残っていても、
              // ここでプレビューだけに寄せる。
              ? editor
              : (_viewMode == 'preview' || narrow)
                  // プレビューだけ (= ユーザー要望)。
                  ? ColoredBox(
                      color: provider.isDarkMode
                          ? const Color(0xFF14141F)
                          : Colors.white,
                      child: preview)
                  : (narrow
                  // 狭い画面は上下に分ける。 既定はプレビューが上・編集が下
                  // (= ユーザー要望: モバイルでは編集画面が下に来るように)。
                  // 入れ替えボタンでどちらを上にするかは変えられる。
                  ? Column(children: [
                      if (_previewLeft) ...[
                        Expanded(child: editor),
                        const Divider(height: 1, color: Colors.white12),
                        Expanded(
                            child: ColoredBox(
                                color: provider.isDarkMode
                                    ? const Color(0xFF14141F)
                                    : Colors.white,
                                child: preview)),
                      ] else ...[
                        Expanded(
                            child: ColoredBox(
                                color: provider.isDarkMode
                                    ? const Color(0xFF14141F)
                                    : Colors.white,
                                child: preview)),
                        const Divider(height: 1, color: Colors.white12),
                        Expanded(child: editor),
                      ],
                    ])
                      : Row(children: [
                          // 左右の入れ替えに対応 (= ユーザー要望)。
                          if (_previewLeft) ...[
                            Expanded(
                                child: ColoredBox(
                                    color: provider.isDarkMode
                                        ? const Color(0xFF14141F)
                                        : Colors.white,
                                    child: preview)),
                            const VerticalDivider(
                                width: 1, color: Colors.white12),
                            Expanded(child: editor),
                          ] else ...[
                            Expanded(child: editor),
                            const VerticalDivider(
                                width: 1, color: Colors.white12),
                            Expanded(
                                child: ColoredBox(
                                    color: provider.isDarkMode
                                        ? const Color(0xFF14141F)
                                        : Colors.white,
                                    child: preview)),
                          ],
                        ])),
            ),
            if (_isDesktopPlatform && _aiChatOpen)
              _buildSideAiPanel(provider),
          ]),
        ),
      ]),
      ),
      ),
    );
  }

  /// マークダウンページのヘッダー 1 段。 [narrow] (= 狭い画面) の時は
  /// 左右に流せるようにし、 幅の伸び縮みに頼った部品を固定幅へ置き換える。
  // ─── 左右のパネル (= ユーザー要望: 埋め込みで開く画面と同じく、 メモと
  //     AI チャット欄をこの画面でも出せるように) ───────────────────────

  void _onSideMemoChanged() {
    _sideMemoDebounce?.cancel();
    _sideMemoDebounce = Timer(const Duration(milliseconds: 600), () async {
      try {
        final sp = await SharedPreferences.getInstance();
        await sp.setString(_kMdSideMemoKey, _sideMemoCtrl.text);
      } catch (_) {}
    });
  }

  /// AI の返事をカーソル位置へ差し込む。
  void _insertIntoBody(String text) {
    final t = _ctrl.text;
    final sel = _ctrl.selection;
    final pos = (sel.isValid ? sel.start : t.length).clamp(0, t.length);
    _ctrl.text = t.substring(0, pos) + text + t.substring(pos);
    _ctrl.selection = TextSelection.collapsed(offset: pos + text.length);
    _onChanged();
  }

  Future<void> _sendSideAiChat() async {
    final q = _sideAiInput.text.trim();
    if (q.isEmpty || _sideAiBusy) return;
    setState(() {
      _sideAiChat.add((role: 'user', text: q));
      _sideAiInput.clear();
      _sideAiBusy = true;
    });
    try {
      _syncCurrentTab();
      final body = _ctrl.text;
      final clipped =
          body.length > 12000 ? body.substring(0, 12000) : body;
      final prompt = '${widget.provider.languageInstructionForAi()}\n'
          '次の Markdown 文書を前提に、 質問に答えてください。 文書へ入れる'
          '文章を頼まれた時は、 前置きなしで Markdown だけを返してください。\n'
          '--- 文書 ---\n$clipped\n--- 質問 ---\n$q';
      final a = await widget.provider.askAi(prompt);
      if (mounted) setState(() => _sideAiChat.add((role: 'ai', text: a)));
    } catch (e) {
      if (mounted) {
        setState(() => _sideAiChat
            .add((role: 'ai', text: '$e'.replaceFirst('Exception: ', ''))));
      }
    } finally {
      if (mounted) setState(() => _sideAiBusy = false);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (_sideAiScroll.hasClients) {
          _sideAiScroll.jumpTo(_sideAiScroll.position.maxScrollExtent);
        }
      });
    }
  }

