  /// ファイルから開いている Markdown を、 アプリの新規ページとして取り込む
  /// (= ユーザー要望)。 タブ束ごと写す。 元のファイルはそのまま残る。
  Future<void> _addFileAsNewPage() async {
    final p = widget.provider;
    _syncCurrentTab();
    final base = widget.filePath!
        .replaceAll('\\', '/')
        .split('/')
        .last
        .replaceAll(RegExp(r'\.(md|markdown)$', caseSensitive: false), '');
    // 追加できたかはページ一覧の差分で確かめる (上限で断られることがある)。
    final before = p.pages.map((e) => e.id).toSet();
    p.addMarkdownPage(name: base.isEmpty ? 'Markdown' : base);
    final added = p.pages.where((e) => !before.contains(e.id)).toList();
    if (added.isEmpty) {
      if (mounted) {
        _appSnackTop(
            context, p.t('md.addAsPageFailed'), const Color(0xFFE57373));
      }
      return;
    }
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(
          'markdown_${added.first.id}', encodeMarkdownDoc(_tabs, _sel));
      await sp.setBool('md_sample_seeded_${added.first.id}', true);
    } catch (_) {}
    if (!mounted) return;
    _appSnackTop(context, p.t('md.addedAsPage'), const Color(0xFF43B97F));
  }

  /// 今のタブを .md に書き出して、 選んだページへノードとして埋め込む
  /// (= ユーザー要望: 新規で作った Markdown ページを他のページに追加)。
  Future<void> _addToOtherPage() async {
    final p = widget.provider;
    _syncCurrentTab();
    // 追加先はノードを置けるページ (マップ / ギャラリー) に限る。
    final targets = p.pages
        .where((pg) =>
            pg.id != widget.pageId &&
            (pg.pageType == 'normal' || pg.pageType == 'bookshelf'))
        .toList();
    if (targets.isEmpty) {
      _appSnackTop(
          context, p.t('md.noTargetPage'), const Color(0xFFFFB347));
      return;
    }
    final target = await showDialog<MindMapPage>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(p.t('md.pickTargetPage'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: SizedBox(
          width: 320,
          height: math.min(
              380.0, 20.0 + 44.0 * math.max(2, targets.length)),
          child: ListView.builder(
            itemCount: targets.length,
            itemBuilder: (_, i) => ListTile(
              dense: true,
              leading: Icon(
                  targets[i].pageType == 'bookshelf'
                      ? Icons.shelves
                      : Icons.map_rounded,
                  size: 17,
                  color: targets[i].pageType == 'bookshelf'
                      ? const Color(0xFFFF7043)
                      : const Color(0xFF8B84FF)),
              title: Text(targets[i].name,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(color: Colors.white, fontSize: 13)),
              onTap: () => Navigator.pop(dctx, targets[i]),
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(p.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
        ],
      ),
    );
    if (target == null || !mounted) return;
    try {
      final docs = await getApplicationDocumentsDirectory();
      final dir = Directory('${docs.path}/markdown_embeds');
      await dir.create(recursive: true);
      final safe = (_cur?.name ?? 'markdown')
          .replaceAll(RegExp(r'[\\/:*?"<>|]'), '_');
      final f = File(
          '${dir.path}/$safe-${DateTime.now().millisecondsSinceEpoch}.md');
      await f.writeAsString(_ctrl.text);
      // 埋め込み本体は画面側に任せる (成功のメッセージもそちらが出す)。
      widget.onEmbedToPage!(f.path, '$safe.md', pageId: target.id);
    } catch (e) {
      if (mounted) _appSnackTop(context, '$e', const Color(0xFFE57373));
    }
  }

  Widget _mdHeaderRow(MindMapProvider provider, bool narrow) {
    // ── AI ボタン。 モバイルは 「AI」 だけの短い表記にする
    //    (= ユーザー要望: 「AI に書いてもらう」 は長い)。 ──
    final aiBtn = SizedBox(
      height: 30,
      child: ElevatedButton.icon(
        style: ElevatedButton.styleFrom(
          backgroundColor: const Color(0xFFBA68C8),
          foregroundColor: Colors.white,
          padding: const EdgeInsets.symmetric(horizontal: 12),
          textStyle: const TextStyle(fontSize: 12.5),
        ),
        icon: _aiBusy
            ? const SizedBox(
                width: 14,
                height: 14,
                child: CircularProgressIndicator(
                    strokeWidth: 2, color: Colors.white))
            : const Icon(Icons.auto_awesome_rounded, size: 16),
        label: Text(narrow ? 'AI' : provider.t('md.aiWrite')),
        onPressed: _aiBusy ? null : _askAiToWrite,
      ),
    );
    // ヘッダーを隠すボタン (モバイルは上段の右端に置く)。
    final hideBtn = _btn(Icons.keyboard_double_arrow_up_rounded,
        provider.t('md.hideHeader'), () {
      setState(() => _headerHidden = true);
      // ignore: discarded_futures
      SharedPreferences.getInstance()
          .then((sp) => sp.setBool(_kMdHeaderHiddenKey, true));
    });
    // (タブ追加ボタンはタブ列の末尾に移した = ユーザー要望: 一番右端の
    //  タブの右側に置く)
    // タブ削除ボタン (= ユーザー要望: モバイルは右クリックが無いので、
    // 開いているタブをボタンから消せるように)。 消しても Ctrl+Z で戻せる。
    // (タブ削除の × はタブ列の中、 + の左に移した = ユーザー要望)
    final children = <Widget>[
            // (紫のノートのアイコンは削除 = ユーザー要望: 意味を成していない)
            // ── 開いているページ (タブ)。 添付ファイルでも使える
            //    (= ユーザー要望: 複数タブとメモ / AI 欄のいいとこどり) ──
            if (_tabBarVisible)
              Flexible(
                flex: 5,
                child: _buildTabStrip(provider),
              ),
            // (タブの追加 + と削除 × はタブ列の末尾に入れた = ユーザー要望:
            //  × は + の左側)
            const SizedBox(width: 6),
            aiBtn,
            const Spacer(),
            // ── ボタンの色は白で統一 (= ユーザー要望: 項目ごとに色が付いたり
            //    付かなかったりが気になる)。 色が出るのはメモ / AI の
            //    パネルが開いている時だけ。 ──
            // ── 入れ替えは並べている時だけ、 表示の仕方の「左」 に出す
            //    (= ユーザー要望: 出たり消えたりで他のボタンがずれない
            //    ように。 右寄せの列なので、 左端に足しても他は動かない)。 ──
            if (_viewMode == 'split')
              _btn(
                  narrow
                      ? Icons.swap_vert_rounded
                      : Icons.swap_horiz_rounded,
                  provider.t(narrow ? 'md.swapUpDown' : 'md.swapSides'),
                  _toggleSides),
            // 表示の仕方: 押したら次に何になるかを出す (= ユーザー要望)。
            _btn(_viewModeIcon, _viewModeLabel(provider), _cycleViewMode),
            // ── メモ / AI チャットのパネル (= ユーザー要望)。 画面が広い
            //    デスクトップだけ。 開いている時だけ色が付く。 ──
            if (_isDesktopPlatform) ...[
              _btn(Icons.sticky_note_2_outlined, provider.t('md.sideMemo'),
                  () => setState(() => _memoOpen = !_memoOpen),
                  color:
                      _memoOpen ? const Color(0xFFFFC857) : Colors.white70),
              // ── AI ボタンはブラウザ版 AI を開く (= ユーザー要望:
              //    「AI に書いてもらう」 ボタンがあるので、 こちらは
              //    ChatGPT / Gemini 等の外窓を開く)。 開く係が無い環境
              //    (モバイル等) では従来どおり内蔵チャット欄を出す。 ──
              _btn(Icons.smart_toy_outlined, provider.t('md.aiChat'), () {
                final open = widget.onOpenBrowserAi;
                if (open != null) {
                  open();
                } else {
                  setState(() => _aiChatOpen = !_aiChatOpen);
                }
              },
                  color:
                      _aiChatOpen ? const Color(0xFFBA68C8) : Colors.white70),
            ],
            // ── ページへの持ち出し / 取り込み (= ユーザー要望) ──
            //    ファイルから開いた時: 新規ページとして追加
            //    ページの時: 他のページに (ノードとして) 追加
            if (_fileMode)
              _btn(Icons.note_add_outlined, provider.t('md.addAsPage'),
                  () => unawaited(_addFileAsNewPage()))
            else if (widget.onEmbedToPage != null)
              _btn(Icons.library_add_outlined, provider.t('md.addToOtherPage'),
                  () => unawaited(_addToOtherPage())),
            // 再読み込みボタンは廃止 (= ユーザー要望: 書けばすぐ反映されるので
            //   押す意味が無い)。 描き直しは入力のたびに自動で走る。
            // (タブ列の表示 / 非表示ボタンは削除 = ユーザー要望: ヘッダー
            //  ごと隠せるので要らない)
            // ── タブ数を変える (= ユーザー要望: 中央に画面を出さず、
            //    ヘッダーからそのまま数を選べるように) ──
            //    押すと 1〜8 と「おまかせ」 が出て、 選んだ数へ分け直す。
            PopupMenuButton<int>(
              tooltip: provider.t('md.retabTitle'),
              color: const Color(0xFF1E1E32),
              padding: EdgeInsets.zero,
              enabled: !_aiBusy,
              onSelected: (n) => unawaited(_changeTabCount(n)),
              itemBuilder: (_) => [
                PopupMenuItem<int>(
                  enabled: false,
                  height: 30,
                  child: Text(provider.t('md.retabTitle'),
                      style: const TextStyle(
                          color: Colors.white38, fontSize: 11)),
                ),
                // 0 = AI が必要なだけ分ける (= ユーザー要望)。
                PopupMenuItem<int>(
                  value: 0,
                  child: Text(provider.t('md.retabAuto'),
                      style: const TextStyle(
                          color: Color(0xFFBA68C8), fontSize: 13)),
                ),
                for (final n in const [1, 2, 3, 4, 5, 6, 7, 8])
                  PopupMenuItem<int>(
                    value: n,
                    child: Text('$n',
                        style: const TextStyle(
                            color: Colors.white, fontSize: 13)),
                  ),
              ],
              child: SizedBox(
                width: 34,
                height: 34,
                child: Icon(Icons.auto_stories_rounded,
                    size: 19,
                    color: _aiBusy ? Colors.white24 : Colors.white70),
              ),
            ),
            // 保存した下書きを開く (= ユーザー要望)。
            _btn(Icons.drafts_outlined, provider.t('md.draftListTitle'),
                () => unawaited(_openDraftList())),
            // (リンクを挿入するボタンは削除 = ユーザー要望: AI に指示して
            //  直してもらえば済むため)
            _btn(Icons.copy_rounded, provider.t('md.copy'), _copyAll),
            // ネットに公開する (= ユーザー要望: プレビュー画面をサーバーへ)。
            //   公開中はアイコンの形 (塗り) だけで表す。 色は白で統一。
            if (provider.canPublishHtmlPage)
              _btn(
                  _publishedUrl.isEmpty
                      ? Icons.public_outlined
                      : Icons.public_rounded,
                  provider.t(_publishedUrl.isEmpty
                      ? 'pub.publish'
                      : 'pub.published'),
                  () => unawaited(_openPublishDialog())),
            if (_isDesktopPlatform) ...[
              // 外のファイルを読み込む (= ユーザー要望)。
              _btn(Icons.file_open_outlined, 'ファイルを読み込む',
                  () => unawaited(_importMd())),
              _btn(Icons.save_alt_rounded, provider.t('md.export'), _exportMd),
            ],
            // ヘッダーを隠す (= ユーザー要望)。 隠すと上端の細い帯だけになり、
            //   そこにカーソルを乗せた時だけ「表示」 ボタンが出る。
            hideBtn,
    ];
    if (!narrow) {
      // ── AI ボタンは編集 (黒) とプレビュー (白) の丁度中央に固定する
      //    (= ユーザー要望)。 タブ追加 (+) はその左に置く (= ユーザー要望)。
      //    他のボタン列の流れから外し、 Stack でヘッダー全幅の中央に重ねる。 ──
      final rowChildren =
          children.where((w) => !identical(w, aiBtn)).toList();
      return Stack(children: [
        Row(children: rowChildren),
        Center(child: aiBtn),
      ]);
    }
    // ── モバイルも 1 段に並べる (= ユーザー要望: ヘッダーの項目は 1 列に)。
    //    左: タブ + 追加 / 削除 → 中: 道具の列 (横スクロール) → 右: 隠す。
    //    タブ列と道具の列はどちらも横スクロールするが、 別々のウィジェット
    //    なので入れ子にはならない (= 指の動きが取り合いにならない)。
    final tabMaxW =
        math.max(80.0, MediaQuery.of(context).size.width / 2 - 90);
    // Spacer より後ろ = 道具の列。 末尾の「隠す」 は右端に固定するので除く。
    final tools = children.sublist(
        children.indexWhere((w) => w is Spacer) + 1, children.length - 1);
    return SizedBox(
      height: 40,
      child: Row(children: [
        if (_tabBarVisible)
          Flexible(
            child: ConstrainedBox(
              constraints: BoxConstraints(maxWidth: tabMaxW),
              child: _buildTabStrip(provider),
            ),
          ),
        Expanded(
          child: SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [aiBtn, const SizedBox(width: 4), ...tools],
            ),
          ),
        ),
        hideBtn,
      ]),
    );
  }
}

/// PDF への書き込み (= ユーザー要望: PDF にテキストの書き込みやチェックを
/// 付けられるように)。 syncfusion_flutter_pdf でファイル本体へ直接描き込む
/// ので、 他のアプリで開いても残る。 元に戻す仕組みは無い (上書き保存)。
class _PdfInkWriter {
  static Uint8List? _jpFontBytes;

  static Future<void> _ensureFont() async {
    if (_jpFontBytes != null) return;
    try {
      final d = await rootBundle.load('assets/fonts/NotoSansJP-Regular.ttf');
      _jpFontBytes = d.buffer.asUint8List();
    } catch (_) {
      // フォントが無くても英数字は標準フォントで書ける。
    }
  }

  /// [pagePos] はビューアの onTap が渡すページ座標 (pt、 左上原点)。
  static Future<bool> writeText(
      String path, int pageNumber, Offset pagePos, String text,
      {double fontSize = 25}) async {
    try {
      await _ensureFont();
      final bytes = await File(path).readAsBytes();
      final doc = sfpdf.PdfDocument(inputBytes: bytes);
      if (pageNumber < 1 || pageNumber > doc.pages.count) {
        doc.dispose();
        return false;
      }
      final page = doc.pages[pageNumber - 1];
      final sfpdf.PdfFont font = _jpFontBytes != null
          ? sfpdf.PdfTrueTypeFont(_jpFontBytes!, fontSize)
          : sfpdf.PdfStandardFont(sfpdf.PdfFontFamily.helvetica, fontSize);
      page.graphics.drawString(
        text,
        font,
        brush: sfpdf.PdfSolidBrush(sfpdf.PdfColor(200, 20, 20)),
        bounds: Rect.fromLTWH(
            pagePos.dx, (pagePos.dy - fontSize / 2).clamp(0, 1e5), 0, 0),
      );
      final out = await doc.save();
      doc.dispose();
      await File(path).writeAsBytes(out, flush: true);
      return true;
    } catch (e) {
      debugPrint('PDF テキスト書き込み失敗: $e');
      return false;
    }
  }

  /// タップした場所に赤いチェック (✓) を描く。 線 2 本で描くので、
  /// フォントにチェックの文字が無くても崩れない。
  static Future<bool> writeCheck(
      String path, int pageNumber, Offset pagePos,
      {double size = 10}) async {
    try {
      final bytes = await File(path).readAsBytes();
      final doc = sfpdf.PdfDocument(inputBytes: bytes);
      if (pageNumber < 1 || pageNumber > doc.pages.count) {
        doc.dispose();
        return false;
      }
      final page = doc.pages[pageNumber - 1];
      // 大きさで線の太さも一緒に変える (= ユーザー要望: 大きさを決められる)。
      // 描き込みパレットの ✓ と同じ形・同じ数字になるように合わせてある。
      final k = (size <= 0 ? 10.0 : size) / 2.5;
      // 線の太さは大きさと切り離して 2.5 固定 (= ユーザー要望: チェックの
      // 太さも 2.5)。 大きい ✓ でも線は細いままになる。
      final pen = sfpdf.PdfPen(sfpdf.PdfColor(200, 20, 20), width: 2.5);
      final x = pagePos.dx, y = pagePos.dy;
      page.graphics.drawLine(
          pen, Offset(x - 6 * k, y), Offset(x - 1.5 * k, y + 5.5 * k));
      page.graphics.drawLine(
          pen, Offset(x - 1.5 * k, y + 5.5 * k), Offset(x + 8 * k, y - 7 * k));
      final out = await doc.save();
      doc.dispose();
      await File(path).writeAsBytes(out, flush: true);
      return true;
    } catch (e) {
      debugPrint('PDF チェック書き込み失敗: $e');
      return false;
    }
  }
}

/// ギャラリーのタイル群の背後に敷く単色の板。
///
/// 壁紙を設定していても、 ブロック同士の隙間から模様が覗いて散らかって
/// 見えるという指摘への対応 (= ユーザー要望)。 タイル全体の外接矩形を
/// 少し広げて塗るので、 隙間は同じ色で埋まり、 板の外側では壁紙がそのまま
/// 見える。
class _ShelfBackdropPainter extends CustomPainter {
  final Map<String, MindMapNode> nodes;
  final bool isDark;

  /// 追加用の「＋」 ブロックの矩形 (フロンティアセル)。
  /// タイルだけでなく、 これらも敷板に含める (= ユーザー要望: ＋ブロックが
  /// 出ている隙間も塞ぐ)。
  final List<Rect> addRects;

  const _ShelfBackdropPainter({
    required this.nodes,
    required this.isDark,
    this.addRects = const [],
  });

  @override
  void paint(Canvas canvas, Size size) {
    // ── タイルと ＋ブロックの両方を囲む外接矩形を求める ──
    //   (= ユーザー要望: 埋まっている行だけでなく、 ＋ブロックが出ている
    //    全ての隙間を塞ぐ。 逆に ＋ブロックの外へは白を広げない)。
    double? l, t, r, b;
    void expand(double nl, double nt, double nr, double nb) {
      l = (l == null || nl < l!) ? nl : l;
      t = (t == null || nt < t!) ? nt : t;
      r = (r == null || nr > r!) ? nr : r;
      b = (b == null || nb > b!) ? nb : b;
    }

    for (final n in nodes.values) {
      if (n.hiddenInContainer != null) continue;
      expand(n.position.dx, n.position.dy, n.position.dx + n.width,
          n.position.dy + n.visualHeight);
    }
    for (final ar in addRects) {
      expand(ar.left, ar.top, ar.right, ar.bottom);
    }
    if (l == null || t == null || r == null || b == null) return;

    // タイル / ＋ブロックの外側に少しだけ余白 (縁が窮屈に見えないように)。
    // ＋ブロックの外へ大きく白がはみ出さないよう、 余白は控えめにする。
    const pad = 12.0;
    final rect = Rect.fromLTRB(l! - pad, t! - pad, r! + pad, b! + pad);
    final rr = RRect.fromRectAndRadius(rect, const Radius.circular(16));
    canvas.drawRRect(
        rr,
        Paint()
          ..color = isDark ? const Color(0xFF141A26) : const Color(0xFFE9ECF3));
    canvas.drawRRect(
        rr,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.2
          ..color = (isDark ? Colors.white : Colors.black)
              .withValues(alpha: 0.10));
  }

  @override
  bool shouldRepaint(covariant _ShelfBackdropPainter old) =>
      old.isDark != isDark ||
      old.nodes.length != nodes.length ||
      old.addRects.length != addRects.length ||
      (old.addRects.isNotEmpty &&
          addRects.isNotEmpty &&
          old.addRects.first != addRects.first);
}

