/// ドキュメント用紙に薄い罫線 (横線) を描く。
/// 左の赤いマージン線はユーザー要望で廃止した。
class _RuledLinePainter extends CustomPainter {
  final double lineHeight;
  final double topPad;
  final double leftPad;
  final double rightPad;

  /// 罫線を描くか (= ユーザー要望: Word のような真っ白な正式文書も書ける
  /// ように消せるようにする)。 左の赤いマージン線はユーザー要望で廃止した。
  final bool showLines;
  const _RuledLinePainter({
    this.lineHeight = 30,
    this.topPad = 48,
    this.leftPad = 64,
    this.rightPad = 56,
    this.showLines = true,
  });
  @override
  void paint(Canvas canvas, Size size) {
    if (showLines) {
      final line = Paint()
        ..color = const Color(0xFFCFE0F2) // 薄い青の罫線
        ..strokeWidth = 1;
      for (double y = topPad + lineHeight;
          y < size.height - 6;
          y += lineHeight) {
        canvas.drawLine(
            Offset(leftPad, y), Offset(size.width - rightPad, y), line);
      }
    }
    // 左の赤いマージン線はユーザー要望で廃止 (= 「要らないから消して」)。
  }

  @override
  bool shouldRepaint(covariant _RuledLinePainter old) =>
      old.lineHeight != lineHeight ||
      old.topPad != topPad ||
      old.leftPad != leftPad ||
      old.rightPad != rightPad ||
      old.showLines != showLines;
}

/// ノート (= ドキュメントページ) に貼り付けた画像を描画する埋め込みビルダー
/// (= ユーザー要望: ノートに画像を貼り付けられるように)。 embed type 'image' の
/// data (= ローカルファイルパス または http(s) URL) を Image で表示する。
class _DocImageEmbedBuilder extends EmbedBuilder {
  const _DocImageEmbedBuilder();

  @override
  String get key => 'image';

  @override
  Widget build(BuildContext context, EmbedContext embedContext) {
    final src = embedContext.node.value.data?.toString() ?? '';
    Widget broken() => Container(
          width: 140,
          height: 90,
          color: const Color(0xFFE0E0E0),
          alignment: Alignment.center,
          child: const Icon(Icons.broken_image_rounded, color: Colors.black38),
        );
    Widget img;
    if (src.startsWith('http://') || src.startsWith('https://')) {
      img = Image.network(src,
          fit: BoxFit.contain, errorBuilder: (_, __, ___) => broken());
    } else if (src.isNotEmpty) {
      img = Image.file(File(src),
          fit: BoxFit.contain, errorBuilder: (_, __, ___) => broken());
    } else {
      img = broken();
    }
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 6),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 560, maxHeight: 420),
        child: img,
      ),
    );
  }
}

