class _DocumentPageViewState extends State<_DocumentPageView> {
  /// 作られた時点の MCP 書き込み回数。 dispose 時に増えていたら、
  /// 「AI が書いたので作り直された」 ということなので保存しない。
  late final int _mcpTickAtInit = widget.provider.mcpContentTick;

  // ── 複数ページ対応 (= ユーザー要望: 文書は 2 ページ目以降も作れるように) ──
  // 1 文書 = 複数の「用紙ページ」。 各ページは独立した QuillController を持つ。
  // prefs には { v:2, horizontal:bool, pages:[delta,...] } で保存し、 旧形式
  //   (単一ページの delta = List) も読み込めるよう後方互換にしてある。
  final List<QuillController> _controllers = [];
  final List<FocusNode> _focusNodes = [];
  bool _loaded = false;
  Timer? _saveTimer;

  /// 縦開きの用紙スクロール。 余白を変える時に、 触っている側 (ヘッダー側 /
  /// フッター側) が画面に入るように動かすため (= ユーザー要望)。
  final ScrollController _paperScroll = ScrollController();

  /// 今表示している 1 ページ分の高さ (余白ダイアログのスクロール計算用)。
  double _paperPageHeight = 0;

  /// 表紙を出しているか (同上。 表紙の分だけページ位置がずれる)。
  bool _paperHasCover = false;

  /// 編集中 (= フォーカス中) のページ番号。 書式ツールバーはこのページの
  /// コントローラに紐づく (縦開きで複数ページが同時に見えている時に、 どの
  /// ページの書式を編集するかを決める)。
  int _activeIndex = 0;

  /// 横開き (= ユーザー要望: 縦開き / 横開きを入れ替えられるように)。
  /// false = 縦開き (ページを縦に積んで下へスクロール)、
  /// true  = 横開き (ページを左右にめくる PageView)。
  bool _horizontal = false;

  /// ノートの表紙指定。現在は `template:<id>` を保存する。
  /// 旧バージョンで保存された画像ファイルパスも表示だけ後方互換で扱う。
  /// null/空 で表紙なし。 縦開きの先頭にスクロールして消える表紙として表示する。
  String? _coverPath;
  String get _coverPrefsKey => 'document_cover_${widget.pageId}';

  /// 全ページに共通表示するヘッダー／フッター。編集モード中は用紙上で直接
  /// 入力し、通常モードでは固定テキストとして表示する。
  final TextEditingController _headerCtrl = TextEditingController();
  final TextEditingController _footerCtrl = TextEditingController();
  bool _headerFooterEditMode = false;
  String get _headerFooterPrefsKey => 'document_header_footer_${widget.pageId}';

  static const String _coverTemplatePrefix = 'template:';
  static const List<_DocCoverTemplate> _coverTemplates = [
    _DocCoverTemplate(
      id: 'executive',
      name: 'エグゼクティブ',
      subtitle: 'cover.tmplExecutive', // 表示時に t() で翻訳するキー
      eyebrow: 'REPORT',
      background: Color(0xFF10182F),
      accent: Color(0xFFFFC857),
      accent2: Color(0xFF2D9CDB),
      icon: Icons.business_center_rounded,
    ),
    _DocCoverTemplate(
      id: 'minimal',
      name: 'ミニマル',
      subtitle: 'cover.tmplMinimal',
      eyebrow: 'DOCUMENT',
      background: Color(0xFFF7F4EC),
      accent: Color(0xFF2F80ED),
      accent2: Color(0xFF111827),
      icon: Icons.article_outlined,
    ),
    _DocCoverTemplate(
      id: 'academic',
      name: 'アカデミック',
      subtitle: 'cover.tmplAcademic',
      eyebrow: 'STUDY NOTE',
      background: Color(0xFF12372A),
      accent: Color(0xFF7ED957),
      accent2: Color(0xFFE8F5E9),
      icon: Icons.school_rounded,
    ),
    _DocCoverTemplate(
      id: 'creative',
      name: 'クリエイティブ',
      subtitle: 'cover.tmplCreative',
      eyebrow: 'IDEA',
      background: Color(0xFF2A174A),
      accent: Color(0xFFFF5DA2),
      accent2: Color(0xFFFFB347),
      icon: Icons.auto_awesome_rounded,
    ),
  ];

  /// 横開き時のページめくり用コントローラ。
  final PageController _pageCtrl = PageController();

  static const double _lineH = 30;

  // ── 用紙の余白 (= ユーザー要望: ヘッダーやフッターの余白などをもっと自由に
  //    設定できるように) ──
  //    既定値は従来と同じ。 設定した値は prefs に覚えて次回も使う。
  //    上 = ヘッダー側、 下 = フッター側の余白。
  static const double _kDefaultPadTop = 48;
  static const double _kDefaultPadLeft = 64;
  static const double _kDefaultPadRight = 56;
  static const double _kDefaultPadBottom = 64;
  double _padTop = _kDefaultPadTop;
  double _padLeft = _kDefaultPadLeft;
  double _padRight = _kDefaultPadRight;
  double _padBottom = _kDefaultPadBottom;
  static const String _kDocMarginsKey = 'document_margins_v1';

  Future<void> _loadDocMargins() async {
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString(_kDocMarginsKey);
      if (raw == null || raw.isEmpty) return;
      final m = jsonDecode(raw);
      if (m is! Map) return;
      final t = (m['t'] as num?)?.toDouble();
      final l = (m['l'] as num?)?.toDouble();
      final r = (m['r'] as num?)?.toDouble();
      final b = (m['b'] as num?)?.toDouble();
      if (!mounted) return;
      setState(() {
        _padTop = (t ?? _padTop).clamp(0.0, 300.0).toDouble();
        _padLeft = (l ?? _padLeft).clamp(0.0, 300.0).toDouble();
        _padRight = (r ?? _padRight).clamp(0.0, 300.0).toDouble();
        _padBottom = (b ?? _padBottom).clamp(0.0, 300.0).toDouble();
      });
    } catch (_) {}
  }

  Future<void> _persistDocMargins() async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(
          _kDocMarginsKey,
          jsonEncode({
            't': _padTop,
            'l': _padLeft,
            'r': _padRight,
            'b': _padBottom,
          }));
    } catch (_) {}
  }

  /// 用紙の縦横比 (A4 縦 = 1:√2)。 ページの高さは幅 × これで固定し、
  /// 最終行からあふれた段落は次ページへ自動で送る (= ユーザー要望)。
  static const double _kPageAspect = 1.4142;

  /// 罫線の表示 (= ユーザー要望: Word のような正式な文書も書けるように)。
  /// 保存 JSON に含める。 左の赤いマージン線はユーザー要望で廃止した。
  bool _showRuledLines = true;

  /// 表紙の文字の上書き (= ユーザー要望: 表紙の中の文字を変えられるように)。
  /// null は既定 (タイトル = ページ名、 ラベルはテンプレート既定)。
  String? _coverTitle;
  String? _coverEyebrow;
  String? _coverSubtitle;
  String get _coverTextPrefsKey => 'document_cover_texts_${widget.pageId}';

  /// 各ページの本文の実高さを測るためのキー (あふれ検出用)。
  final List<GlobalKey> _contentKeys = [];

  /// 本文が入る最大高さ (= ページ高 - 上下パディング)。 build 時に更新。
  double _pageContentMaxH = 1000;
  Timer? _reflowTimer;
  int _reflowBurst = 0;

  /// 空の文書でも最低この行数ぶんの空行を用意して、 どの罫線にもすぐ書けるよう
  /// にする (= ユーザー要望: 自由な行に文字を書ける)。
  static const int _kDocMinLines = 30;

  String get _prefsKey => 'document_${widget.pageId}';

  @override
  void initState() {
    super.initState();
    _load();
    // 用紙の余白 (= ユーザー要望で設定できるようにした値) を読み直す。
    // ignore: discarded_futures
    _loadDocMargins();
  }

  /// 空の文書でも罫線いっぱいの「自由な行」 に書けるよう、 空行をあらかじめ
  /// 用意する (= ユーザー要望)。 罫線と本文は一緒にスクロールするので余分な
  /// 行があってもズレない。 最低 _kDocMinLines 行。
  void _seedMinLines(Document doc) {
    try {
      int lines = '\n'.allMatches(doc.toPlainText()).length;
      if (lines < 1) lines = 1;
      if (lines < _kDocMinLines) {
        final at = doc.length - 1;
        doc.insert(at < 0 ? 0 : at, '\n' * (_kDocMinLines - lines));
      }
    } catch (_) {}
  }

  /// Document からコントローラを生成し、 自動保存リスナとフォーカス追従を
  /// 配線して `_controllers` / `_focusNodes` に追加する。
  /// [seed] false なら空行の種まきをしない。 あふれ送りで作る中間ページに
  /// 空行を足すと、 その空行がまた次ページへあふれて無限にページが増える
  /// (= フリーズの原因) ため、 自動生成ページでは必ず false にする。
  void _attachController(Document doc, {bool seed = true}) {
    if (seed) _seedMinLines(doc);
    final ctrl = QuillController(
        document: doc, selection: const TextSelection.collapsed(offset: 0));
    ctrl.addListener(_scheduleSave);
    // 最終行からあふれたら次ページへ送るための検出 (= ユーザー要望)。
    ctrl.addListener(_scheduleReflow);
    // 文字数カウントの表示更新 (= ユーザー要望)。
    ctrl.addListener(_onDocCharsChanged);
    final fn = FocusNode();
    // フォーカスを得たページをアクティブ扱いにしてツールバーを紐づけ直す。
    //   削除でインデックスがずれ得るので、 その都度 indexOf で引き直す。
    fn.addListener(() {
      if (!mounted || !fn.hasFocus) return;
      final cur = _focusNodes.indexOf(fn);
      if (cur >= 0 && cur != _activeIndex) {
        setState(() => _activeIndex = cur);
      }
    });
    _controllers.add(ctrl);
    _focusNodes.add(fn);
    _contentKeys.add(GlobalKey());
  }

  // ─── 画像/URL の貼り付け (= ユーザー要望: ノートに画像を貼れる + URL はリンク) ───

  /// クリップボードからファイルのバイト列を読む (super_clipboard)。
  Future<Uint8List?> _readClipBytes(
      ClipboardReader reader, FileFormat format) async {
    final completer = Completer<Uint8List?>();
    try {
      reader.getFile(format, (file) async {
        try {
          final chunks = <int>[];
          await for (final chunk in file.getStream()) {
            chunks.addAll(chunk);
          }
          if (!completer.isCompleted) {
            completer.complete(Uint8List.fromList(chunks));
          }
        } catch (_) {
          if (!completer.isCompleted) completer.complete(null);
        }
      }, onError: (_) {
        if (!completer.isCompleted) completer.complete(null);
      });
    } catch (_) {
      if (!completer.isCompleted) completer.complete(null);
    }
    return completer.future
        .timeout(const Duration(seconds: 10), onTimeout: () => null);
  }

  /// 画像バイト列を端末内に保存して、 そのパスを返す。
  Future<String?> _saveImageBytes(Uint8List bytes, String ext) async {
    try {
      final dir = await getApplicationDocumentsDirectory();
      final d = Directory('${dir.path}/note_images');
      if (!await d.exists()) await d.create(recursive: true);
      final path =
          '${d.path}/note_${DateTime.now().millisecondsSinceEpoch}.$ext';
      await File(path).writeAsBytes(bytes);
      return path;
    } catch (_) {
      return null;
    }
  }

  /// 画像の埋め込みを [controller] の現在位置に挿入する。
  void _insertImagePath(QuillController controller, String path) {
    final index =
        controller.selection.baseOffset.clamp(0, controller.document.length);
    final len = controller.selection.isCollapsed
        ? 0
        : (controller.selection.extentOffset - controller.selection.baseOffset)
            .abs();
    // 画像の前後に改行を入れて単独行に置く (罫線と重なっても読める)。
    controller.replaceText(index, len, BlockEmbed.image(path), null);
    controller.replaceText(
        index + 1, 0, '\n', TextSelection.collapsed(offset: index + 2));
  }

  /// テキストを挿入。 全体が URL ならハイパーリンク (link 属性) として挿入する。
  void _insertTextSmart(QuillController controller, String text) {
    final index =
        controller.selection.baseOffset.clamp(0, controller.document.length);
    final len = controller.selection.isCollapsed
        ? 0
        : (controller.selection.extentOffset - controller.selection.baseOffset)
            .abs();
    final trimmed = text.trim();
    final isUrl = !trimmed.contains(RegExp(r'\s')) &&
        (trimmed.startsWith('http://') || trimmed.startsWith('https://'));
    if (isUrl) {
      controller.replaceText(index, len, trimmed,
          TextSelection.collapsed(offset: index + trimmed.length));
      controller.formatText(index, trimmed.length, LinkAttribute(trimmed));
      // リンク属性が後続入力に伝播しないよう、 末尾にリンク解除のプレーン空白。
    } else {
      controller.replaceText(index, len, text,
          TextSelection.collapsed(offset: index + text.length));
    }
  }

  /// Ctrl/Cmd+V や「貼り付け」 ボタンの本体。 画像 → テキスト(URL→リンク) の順。
  Future<void> _pasteIntoController(int i) async {
    if (i < 0 || i >= _controllers.length) return;
    final controller = _controllers[i];
    try {
      final clipboard = SystemClipboard.instance;
      if (clipboard == null) return;
      final reader = await clipboard.read();
      const imgCandidates = <(FileFormat, String)>[
        (Formats.png, 'png'),
        (Formats.jpeg, 'jpg'),
        (Formats.gif, 'gif'),
        (Formats.webp, 'webp'),
        (Formats.bmp, 'bmp'),
      ];
      for (final (fmt, ext) in imgCandidates) {
        if (reader.canProvide(fmt)) {
          final bytes = await _readClipBytes(reader, fmt);
          if (bytes != null && bytes.isNotEmpty) {
            final path = await _saveImageBytes(bytes, ext);
            if (path != null && mounted) {
              setState(() => _insertImagePath(controller, path));
              _scheduleSave();
            }
            return;
          }
        }
      }
      if (reader.canProvide(Formats.plainText)) {
        final text = await reader.readValue(Formats.plainText);
        if (text != null && text.isNotEmpty && mounted) {
          setState(() => _insertTextSmart(controller, text));
          _scheduleSave();
        }
      }
    } catch (_) {}
  }

  /// ファイルピッカーから画像を選んでノートに挿入 (= モバイルでも使える経路)。
  Future<void> _pickAndInsertImage() async {
    final idx = _activeIndex.clamp(0, _controllers.length - 1);
    try {
      final res = await FilePicker.platform.pickFiles(dialogTitle: context.read<MindMapProvider>().t('pick.image'), type: FileType.image);
      final p = res?.files.single.path;
      if (p == null || p.isEmpty || !mounted) return;
      setState(() => _insertImagePath(_controllers[idx], p));
      _scheduleSave();
    } catch (_) {}
  }

  Future<void> _load() async {
    List<Document> docs = [];
    try {
      final sp = await SharedPreferences.getInstance();
      // ── 旧キーからの引き継ぎ (= ユーザー要望: 通常のフリーノートと文書
      //    モードで中身が違うのを揃える) ──
      //    以前はシートごと ('document_paintdoc_<ページ>_<番号>') に分かれて
      //    いた。 ページ単位のキーがまだ空なら、 旧キーの中で最初に見つかった
      //    内容を引き継いで、 書いたものが消えたように見えないようにする。
      if ((sp.getString(_prefsKey) ?? '').isEmpty) {
        for (final k in sp.getKeys().where((k) =>
            k.startsWith('document_paintdoc_${widget.pageId}_'))) {
          final legacy = sp.getString(k) ?? '';
          if (legacy.isNotEmpty) {
            await sp.setString(_prefsKey, legacy);
            break;
          }
        }
      }
      final raw = sp.getString(_prefsKey);
      if (raw != null && raw.isNotEmpty) {
        final decoded = jsonDecode(raw);
        if (decoded is List) {
          // 旧形式 (単一ページの delta) → 1 ページとして読み込む。
          docs = [Document.fromJson(decoded)];
        } else if (decoded is Map) {
          _horizontal = decoded['horizontal'] == true;
          // 罫線の表示設定 (未保存なら既定 = 表示)。
          _showRuledLines = decoded['ruled'] != false;
          final pages = decoded['pages'];
          if (pages is List) {
            for (final p in pages) {
              try {
                docs.add(p is List ? Document.fromJson(p) : Document());
              } catch (_) {
                docs.add(Document());
              }
            }
          }
        }
      }
    } catch (_) {}
    if (docs.isEmpty) docs = [Document()];
    for (final d in docs) {
      _attachController(d);
    }
    // 表紙画像パスを復元 (= ユーザー要望: ノートに表紙)。
    try {
      final sp = await SharedPreferences.getInstance();
      final cp = sp.getString(_coverPrefsKey);
      if (cp != null && cp.isNotEmpty) {
        final isTemplate = _coverTemplateForValue(cp) != null;
        final isLegacyFile = !isTemplate && File(cp).existsSync();
        if (isTemplate || isLegacyFile) _coverPath = cp;
      }
      final headerFooter = sp.getString(_headerFooterPrefsKey);
      if (headerFooter != null && headerFooter.isNotEmpty) {
        final decoded = jsonDecode(headerFooter);
        if (decoded is Map) {
          _headerCtrl.text = decoded['header']?.toString() ?? '';
          _footerCtrl.text = decoded['footer']?.toString() ?? '';
        }
      }
      // 表紙の文字の上書きを復元 (= ユーザー要望: 表紙の文字を変えられる)。
      final ctRaw = sp.getString(_coverTextPrefsKey);
      if (ctRaw != null && ctRaw.isNotEmpty) {
        final ct = jsonDecode(ctRaw);
        if (ct is Map) {
          String? pick(String k) {
            final v = ct[k]?.toString().trim();
            return (v == null || v.isEmpty) ? null : v;
          }

          _coverTitle = pick('title');
          _coverEyebrow = pick('eyebrow');
          _coverSubtitle = pick('subtitle');
        }
      }
    } catch (_) {}
    if (!mounted) {
      for (final c in _controllers) {
        c.dispose();
      }
      for (final f in _focusNodes) {
        f.dispose();
      }
      return;
    }
    setState(() => _loaded = true);
    // 既存の長いページも固定ページ高へ流し込む (あふれた段落は次ページへ)。
    //   ただし開いた直後は描画を優先する (= ユーザー報告: 文書モードに
    //   切り替えると処理落ちする)。 保存済みの内容は前回時点で流し込み済み
    //   なので、 少し待ってから 1 回だけ確認すれば足りる。
    Timer(const Duration(milliseconds: 600), () {
      if (mounted) _scheduleReflow();
    });
  }

  String _coverValueForTemplate(String id) => '$_coverTemplatePrefix$id';

  _DocCoverTemplate? _coverTemplateForValue(String? value) {
    if (value == null || !value.startsWith(_coverTemplatePrefix)) return null;
    final id = value.substring(_coverTemplatePrefix.length);
    for (final template in _coverTemplates) {
      if (template.id == id) return template;
    }
    return null;
  }

  Future<String?> _pickCoverTemplate() async {
    final currentId = _coverTemplateForValue(_coverPath)?.id;
    return showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(widget.provider.t('cover.selectTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        content: SizedBox(
          width: 720,
          child: SingleChildScrollView(
            child: Wrap(
              spacing: 12,
              runSpacing: 12,
              children: [
                for (final template in _coverTemplates)
                  SizedBox(
                    width: 164,
                    child: InkWell(
                      borderRadius: BorderRadius.circular(12),
                      onTap: () => Navigator.pop(dctx, template.id),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          _buildCoverTemplatePreview(
                            template,
                            widget.provider.currentPage.name,
                            compact: true,
                            selected: template.id == currentId,
                          ),
                          const SizedBox(height: 7),
                          Text(template.name,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 12,
                                  fontWeight: FontWeight.w700)),
                          const SizedBox(height: 2),
                          Text(widget.provider.t(template.subtitle),
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: Colors.white54, fontSize: 10)),
                        ],
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
        ],
      ),
    );
  }

  /// 表紙テンプレートを選んで設定する。
  Future<void> _setCover() async {
    try {
      final id = await _pickCoverTemplate();
      if (id == null || id.isEmpty || !mounted) return;
      final value = _coverValueForTemplate(id);
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_coverPrefsKey, value);
      setState(() => _coverPath = value);
    } catch (_) {}
  }

  /// 表紙を外す。
  Future<void> _removeCover() async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.remove(_coverPrefsKey);
    } catch (_) {}
    if (mounted) setState(() => _coverPath = null);
  }

  /// 表紙ボタン押下: 未設定ならテンプレート選択、 設定済みなら変更/削除メニュー。
  /// メニューは画面中央のダイアログで出す (= ユーザー要望: 「表紙テンプレートを
  /// 変更」 等の項目は中央に表示)。
  Future<void> _onCoverButton() async {
    if (_coverPath == null || _coverPath!.isEmpty) {
      await _setCover();
      return;
    }
    final sel = await showDialog<String>(
      context: context,
      builder: (dctx) => SimpleDialog(
        backgroundColor: const Color(0xFF1E1E32),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        children: [
          ListTile(
            leading: const Icon(Icons.dashboard_customize_rounded,
                color: Color(0xFF66BB6A)),
            title: Text(widget.provider.t('cover.change'),
                style: const TextStyle(color: Colors.white)),
            onTap: () => Navigator.pop(dctx, 'change'),
          ),
          ListTile(
            leading:
                const Icon(Icons.edit_note_rounded, color: Color(0xFF4FC3F7)),
            title: Text(widget.provider.t('cover.editTexts'),
                style: const TextStyle(color: Colors.white)),
            onTap: () => Navigator.pop(dctx, 'texts'),
          ),
          ListTile(
            leading: const Icon(Icons.delete_outline_rounded,
                color: Color(0xFFE57373)),
            title: Text(widget.provider.t('cover.remove'),
                style: const TextStyle(color: Colors.white)),
            onTap: () => Navigator.pop(dctx, 'remove'),
          ),
        ],
      ),
    );
    if (sel == 'change') {
      await _setCover();
    } else if (sel == 'texts') {
      await _editCoverTexts();
    } else if (sel == 'remove') {
      await _removeCover();
    }
  }

  /// 表紙の文字 (上部ラベル / タイトル / サブタイトル) を編集する
  /// (= ユーザー要望: 表紙の中の文字なども変えられるように)。
  Future<void> _editCoverTexts() async {
    final provider = widget.provider;
    final template = _coverTemplateForValue(_coverPath);
    final eyebrowCtrl =
        TextEditingController(text: _coverEyebrow ?? template?.eyebrow ?? '');
    final titleCtrl = TextEditingController(
        text: (_coverTitle != null && _coverTitle!.isNotEmpty)
            ? _coverTitle!
            : provider.currentPage.name);
    final subtitleCtrl = TextEditingController(
        text: _coverSubtitle ??
            (template != null ? provider.t(template.subtitle) : ''));
    InputDecoration deco(String label) => InputDecoration(
          labelText: label,
          labelStyle: const TextStyle(color: Colors.white54, fontSize: 12),
          enabledBorder: const UnderlineInputBorder(
              borderSide: BorderSide(color: Colors.white24)),
          focusedBorder: const UnderlineInputBorder(
              borderSide: BorderSide(color: Color(0xFF4FC3F7))),
        );
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('cover.editTexts'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        content: SizedBox(
          width: 380,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            TextField(
                controller: eyebrowCtrl,
                style: const TextStyle(color: Colors.white),
                decoration: deco(provider.t('cover.eyebrowLabel'))),
            const SizedBox(height: 10),
            TextField(
                controller: titleCtrl,
                style: const TextStyle(color: Colors.white),
                decoration: deco(provider.t('cover.titleLabel'))),
            const SizedBox(height: 10),
            TextField(
                controller: subtitleCtrl,
                style: const TextStyle(color: Colors.white),
                decoration: deco(provider.t('cover.subtitleLabel'))),
          ]),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx, false),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          TextButton(
              onPressed: () => Navigator.pop(dctx, true),
              child: Text(provider.t('btn.save'),
                  style: const TextStyle(
                      color: Color(0xFF4FC3F7), fontWeight: FontWeight.w700))),
        ],
      ),
    );
    if (ok == true && mounted) {
      String? norm(TextEditingController c) {
        final v = c.text.trim();
        return v.isEmpty ? null : v;
      }

      setState(() {
        _coverEyebrow = norm(eyebrowCtrl);
        _coverTitle = norm(titleCtrl);
        _coverSubtitle = norm(subtitleCtrl);
      });
      try {
        final sp = await SharedPreferences.getInstance();
        await sp.setString(
            _coverTextPrefsKey,
            jsonEncode({
              'eyebrow': _coverEyebrow ?? '',
              'title': _coverTitle ?? '',
              'subtitle': _coverSubtitle ?? '',
            }));
      } catch (_) {}
    }
    eyebrowCtrl.dispose();
    titleCtrl.dispose();
    subtitleCtrl.dispose();
  }

  Widget _buildCoverTemplatePreview(_DocCoverTemplate template, String title,
      {bool compact = false,
      bool selected = false,
      bool fill = false,
      String? eyebrowOverride,
      String? subtitleOverride}) {
    final dark = ThemeData.estimateBrightnessForColor(template.background) ==
        Brightness.dark;
    final fg = dark ? Colors.white : const Color(0xFF111827);
    final muted = dark ? Colors.white70 : Colors.black54;
    final borderColor =
        selected ? template.accent : Colors.white.withValues(alpha: 0.12);
    final radius = BorderRadius.circular(compact ? 10 : 14);
    final body = Container(
        decoration: BoxDecoration(
          borderRadius: radius,
          border: Border.all(color: borderColor, width: selected ? 2 : 1),
          gradient: LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [
              template.background,
              Color.lerp(template.background, template.accent, 0.18) ??
                  template.background,
            ],
          ),
          boxShadow: compact
              ? null
              : [
                  BoxShadow(
                    color: Colors.black.withValues(alpha: 0.22),
                    blurRadius: 18,
                    offset: const Offset(0, 8),
                  ),
                ],
        ),
        clipBehavior: Clip.antiAlias,
        child: Stack(children: [
          Positioned(
            right: compact ? -20 : -34,
            top: compact ? -20 : -34,
            child: Container(
              width: compact ? 76 : 150,
              height: compact ? 76 : 150,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: template.accent.withValues(alpha: dark ? 0.22 : 0.18),
              ),
            ),
          ),
          Positioned(
            right: compact ? 18 : 42,
            bottom: compact ? 12 : 34,
            child: Icon(template.icon,
                color: template.accent2.withValues(alpha: dark ? 0.42 : 0.34),
                size: compact ? 34 : 82),
          ),
          Positioned(
            left: compact ? 14 : 40,
            top: compact ? 14 : 42,
            bottom: compact ? 14 : 34,
            child: Container(
              width: compact ? 3 : 5,
              decoration: BoxDecoration(
                color: template.accent,
                borderRadius: BorderRadius.circular(99),
              ),
            ),
          ),
          Padding(
            padding: EdgeInsets.fromLTRB(
                compact ? 24 : 58, compact ? 16 : 50, compact ? 12 : 40, 22),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(eyebrowOverride ?? template.eyebrow,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                        color: template.accent,
                        fontSize: compact ? 8 : 13,
                        fontWeight: FontWeight.w800,
                        letterSpacing: 1.4)),
                SizedBox(height: compact ? 8 : 18),
                Text(title.isEmpty ? template.name : title,
                    maxLines: compact ? 2 : 3,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                        color: fg,
                        fontSize: compact ? 14 : 34,
                        height: 1.05,
                        fontWeight: FontWeight.w900)),
                const Spacer(),
                Text(subtitleOverride ?? widget.provider.t(template.subtitle),
                    maxLines: compact ? 1 : 2,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                        color: muted,
                        fontSize: compact ? 8 : 13,
                        fontWeight: FontWeight.w500)),
              ],
            ),
          ),
        ]));
    if (fill) return body;
    // 一覧のプレビューも本体の用紙と同じ縦長比で出す (= ユーザー要望:
    //   表紙の大きさは本体のページサイズと合わせる)。
    return AspectRatio(aspectRatio: 1 / _kPageAspect, child: body);
  }

  /// 表紙ウィジェット (= 縦開きの先頭にスクロールして消える表紙)。
  /// 大きさは本体の用紙ページと同じにする (= ユーザー要望)。
  Widget _buildCover(double pageW, double pageH) {
    final path = _coverPath;
    if (path == null || path.isEmpty) return const SizedBox.shrink();
    final title = (_coverTitle != null && _coverTitle!.isNotEmpty)
        ? _coverTitle!
        : widget.provider.currentPage.name;
    final template = _coverTemplateForValue(path);
    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 6),
      child: Align(
        alignment: Alignment.topCenter,
        child: SizedBox(
          width: pageW,
          height: pageH,
          child: GestureDetector(
            onTap: _onCoverButton,
            child: template != null
                ? _buildCoverTemplatePreview(template, title,
                    fill: true,
                    eyebrowOverride: _coverEyebrow,
                    subtitleOverride: _coverSubtitle)
                : ClipRRect(
                    borderRadius: BorderRadius.circular(10),
                    child: Stack(fit: StackFit.expand, children: [
                      Image.file(File(path),
                          fit: BoxFit.cover,
                          errorBuilder: (_, __, ___) =>
                              Container(color: const Color(0xFF3A3A4E))),
                      Align(
                        alignment: Alignment.bottomLeft,
                        child: Container(
                          width: double.infinity,
                          padding: const EdgeInsets.fromLTRB(16, 30, 16, 14),
                          decoration: const BoxDecoration(
                            gradient: LinearGradient(
                              begin: Alignment.topCenter,
                              end: Alignment.bottomCenter,
                              colors: [Colors.transparent, Colors.black87],
                            ),
                          ),
                          child: Text(
                            title,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 22,
                                fontWeight: FontWeight.w800,
                                shadows: [
                                  Shadow(color: Colors.black, blurRadius: 6)
                                ]),
                          ),
                        ),
                      ),
                    ]),
                  ),
          ),
        ),
      ),
    );
  }

  void _scheduleSave() {
    _saveTimer?.cancel();
    _saveTimer = Timer(const Duration(milliseconds: 700), _save);
  }

  Future<void> _save() async {
    if (_controllers.isEmpty) return;
    // ── 中身は「await より前に」 同期で取り出す (= ユーザー報告: ×ボタンで
    //    閉じると内容が消える) ──
    //    dispose() は _save() を呼んだ直後に controller を破棄する。
    //    await をまたいでから document を読むと破棄済みのものを読むことに
    //    なり、 保存内容が空/不正になる。 先に JSON 化してしまえば安全。
    final String payload;
    try {
      payload = jsonEncode({
        'v': 2,
        'horizontal': _horizontal,
        'ruled': _showRuledLines,
        'pages':
            _controllers.map((c) => c.document.toDelta().toJson()).toList(),
      });
    } catch (_) {
      return; // 取り出せない時は既存の保存内容を壊さない
    }
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_prefsKey, payload);
    } catch (_) {}
  }

  // ─── 最終行からあふれたら次のページへ送る (= ユーザー要望) ───

  /// 打鍵が落ち着いてから 1 回だけあふれ検査を走らせる。
  void _scheduleReflow() {
    _reflowTimer?.cancel();
    _reflowTimer = Timer(const Duration(milliseconds: 220), () {
      _reflowBurst = 0;
      _reflowTick();
    });
  }

  /// 画面に出ているページの本文高さを測り、 用紙からあふれていたら最終段落を
  /// 次ページへ送る。 1 段落ごとに再レイアウト → 次フレームで測り直す。
  void _reflowTick() {
    if (!mounted) return;
    if (_reflowBurst++ > 60) return; // 保険 (異常時の無限ループ防止)
    final maxH = _pageContentMaxH;
    if (maxH <= _lineH * 2) return;
    for (var i = 0; i < _controllers.length; i++) {
      if (i >= _contentKeys.length) break;
      final ctx = _contentKeys[i].currentContext;
      if (ctx == null) continue; // 画面外のページは測れない (表示時に再検査)
      double h = 0;
      try {
        h = ctx.size?.height ?? 0;
      } catch (_) {
        continue;
      }
      // ── あふれの判定 ──
      //   1) 実際に描いた高さが用紙を超えた
      //   2) 行数が 1 ページに入る行数を超えた (= ユーザー要望: 一定の行数を
      //      超えたら次のページへ)。 画像などで高さが伸びない場合の保険。
      final maxLines = (maxH / _lineH).floor();
      var lines = 0;
      try {
        lines = '\n'.allMatches(_controllers[i].document.toPlainText()).length;
      } catch (_) {}
      final overflowed = h > maxH + 0.5 || (maxLines > 2 && lines > maxLines);
      if (!overflowed) continue;
      if (_carryLastParagraph(i)) {
        WidgetsBinding.instance.addPostFrameCallback((_) => _reflowTick());
        return;
      }
    }
  }

  /// ページ i の最終段落を次ページの先頭へ移す。 移せたら true。
  /// カーソルが移した段落の中にあった場合は次ページへフォーカスも移す
  /// (= 最終行で打ち続けるとそのまま次ページに進む)。
  /// 自動でページを増やす上限。 これ以上は送らずに諦める (暴走の保険)。
  static const int _kMaxDocPages = 200;

  bool _carryLastParagraph(int i) {
    if (i < 0 || i >= _controllers.length) return false;
    final ctrl = _controllers[i];
    final doc = ctrl.document;
    final plain = doc.toPlainText();
    if (plain.length <= 1) return false;
    // 最後の段落の先頭 (= 末尾の 1 つ前の改行の直後)。
    final cut = plain.lastIndexOf('\n', plain.length - 2) + 1;
    if (cut <= 0) return false; // 段落が 1 つしかない → 分けられない
    // ── 末尾が空行だけなら送らない ──
    //   「どの行にも書けるように」 用意した空行まで次ページへ流すと、
    //   送った先でも空行があふれて延々とページが増え続ける
    //   (= ユーザー報告: 操作中にフリーズする)。 空行は用紙からはみ出しても
    //   クリップされるだけでよい。
    if (plain.substring(cut).trim().isEmpty) return false;
    if (i + 1 >= _kMaxDocPages) return false;
    final len = doc.length;
    final tail = doc.toDelta().slice(cut, len);
    final head = doc.toDelta().slice(0, cut);
    // 送り先ページを用意する (自動生成ページには空行を足さない)。
    if (i + 1 >= _controllers.length) {
      setState(() => _attachController(Document(), seed: false));
    }
    final caret = ctrl.selection.baseOffset;
    final moveCaret = _focusNodes[i].hasFocus && caret >= cut;
    try {
      // 次ページの先頭へ挿入 (書式ごと移す)。
      _controllers[i + 1].document.compose(tail, ChangeSource.local);
      // 元ページからは段落ごと取り除く (先頭側は必ず改行で終わるので安全)。
      ctrl.document = Document.fromDelta(head);
    } catch (e) {
      // 分割に失敗したら何もしない (内容を壊さないことを優先)。
      debugPrint('ページ送りに失敗: $e');
      return false;
    }
    if (moveCaret) {
      final next = _controllers[i + 1];
      final off = (caret - cut).clamp(0, next.document.length - 1);
      next.updateSelection(
          TextSelection.collapsed(offset: off), ChangeSource.local);
      _focusNodes[i + 1].requestFocus();
      if (mounted) setState(() => _activeIndex = i + 1);
    } else if (caret < cut) {
      ctrl.updateSelection(
          TextSelection.collapsed(
              offset: caret.clamp(0, ctrl.document.length - 1)),
          ChangeSource.local);
    }
    _scheduleSave();
    return true;
  }

  /// 末尾に新しい空ページを追加する (= ユーザー要望: 2 ページ目以降を作る)。
  void _addPage() {
    setState(() => _attachController(Document()));
    _save();
    // 横開きなら追加したページへめくる。
    if (_horizontal) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || !_pageCtrl.hasClients) return;
        _pageCtrl.animateToPage(_controllers.length - 1,
            duration: const Duration(milliseconds: 300), curve: Curves.easeOut);
      });
    }
  }

  /// 指定ページを削除する (最低 1 ページは残す)。
  Future<void> _deletePage(int index) async {
    if (_controllers.length <= 1) return;
    if (index < 0 || index >= _controllers.length) return;
    final provider = context.read<MindMapProvider>();
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF252535),
        title: Text(provider.t('page.deleteTitle'),
            style: const TextStyle(color: Colors.white)),
        content: Text(
            provider
                .t('docPage.deleteConfirm')
                .replaceFirst('{n}', '${index + 1}'),
            style: const TextStyle(color: Colors.white70)),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx, false),
              child: Text(provider.t('btn.cancel'))),
          TextButton(
              onPressed: () => Navigator.pop(dctx, true),
              child: Text(provider.t('btn.delete'),
                  style: const TextStyle(
                      color: Colors.white, fontWeight: FontWeight.w700))),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    setState(() {
      final c = _controllers.removeAt(index);
      c.removeListener(_scheduleSave);
      c.removeListener(_scheduleReflow);
      c.dispose();
      _focusNodes.removeAt(index).dispose();
      if (index < _contentKeys.length) _contentKeys.removeAt(index);
      if (_activeIndex >= _controllers.length) {
        _activeIndex = _controllers.length - 1;
      }
    });
    _save();
  }

  /// 縦開き / 横開きを入れ替える (= ユーザー要望)。
  void _toggleLayout() {
    setState(() => _horizontal = !_horizontal);
    _save();
    if (_horizontal) {
      // 横開きへ切替時はアクティブページを表示する。
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || !_pageCtrl.hasClients) return;
        _pageCtrl.jumpToPage(_activeIndex.clamp(0, _controllers.length - 1));
      });
    }
  }

  Future<void> _saveHeaderFooter() async {
    final header = _headerCtrl.text;
    final footer = _footerCtrl.text;
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(
        _headerFooterPrefsKey,
        jsonEncode({
          'header': header,
          'footer': footer,
        }),
      );
    } catch (_) {}
  }

  void _toggleHeaderFooterEditMode() {
    if (_headerFooterEditMode) {
      // ignore: discarded_futures
      _saveHeaderFooter();
    }
    setState(() => _headerFooterEditMode = !_headerFooterEditMode);
  }

  @override
  void dispose() {
    _saveTimer?.cancel();
    _charCountTimer?.cancel();
    _reflowTimer?.cancel();
    // ★ AI (MCP) が中身を書き換えたせいで作り直された時は保存しない。
    //   ここで保存すると、 画面が持っている「書き換わる前」 の中身で
    //   上書きしてしまい、 AI が書いた文章が消える。
    if (widget.provider.mcpContentTick == _mcpTickAtInit) {
      _save(); // 離脱時に確実に保存
    }
    for (final c in _controllers) {
      c.removeListener(_scheduleSave);
      c.removeListener(_onDocCharsChanged);
      c.removeListener(_scheduleReflow);
      c.dispose();
    }
    for (final f in _focusNodes) {
      f.dispose();
    }
    _pageCtrl.dispose();
    _paperScroll.dispose();
    _saveHeaderFooter();
    _headerCtrl.dispose();
    _footerCtrl.dispose();
    super.dispose();
  }

  /// 用紙は白なので本文は黒で固定する (ダークテーマの DefaultTextStyle が白だと
  /// 白紙に白文字で見えないため、 customStyles で段落・見出しを黒に上書き)。
  DefaultStyles _blackStyles(BuildContext context) {
    DefaultTextBlockStyle blk(DefaultTextBlockStyle b, {bool fitLine = false}) {
      final fs = b.style.fontSize ?? 16.0;
      return DefaultTextBlockStyle(
          b.style.copyWith(
            color: Colors.black87,
            // 段落の 1 行の高さを罫線ピッチ (_lineH=30px) にぴったり合わせる
            //   (= ユーザー要望: 罫線と文字を入力できる位置が合っていない)。
            //   1 行 = fontSize × height なので height = 30 / fontSize。
            //   見出し (h1-h3) は大きい文字なので等倍のまま (30px に潰さない)。
            height: fitLine ? _lineH / fs : b.style.height,
            // ── 行内で文字を「中央」 ではなく「下 (= 罫線上)」 寄りに配置する ──
            // = ユーザー要望: 時々文字が罫線の中央に来てしまう → 罫線の上 (ベース
            //   ライン) に乗るように。 既定の even (= 上下均等 = 中央) だと背の高い
            //   行ボックス内で文字が中央に浮く。 proportional はフォントの上下比で
            //   余白を配分するため、 文字が下 (罫線側) に寄って線の上に乗る。
            leadingDistribution: TextLeadingDistribution.proportional,
          ),
          b.horizontalSpacing,
          b.verticalSpacing,
          b.lineSpacing,
          b.decoration);
    }

    final base = DefaultStyles.getInstance(context);
    return base.merge(DefaultStyles(
      paragraph:
          base.paragraph != null ? blk(base.paragraph!, fitLine: true) : null,
      h1: base.h1 != null ? blk(base.h1!) : null,
      h2: base.h2 != null ? blk(base.h2!) : null,
      h3: base.h3 != null ? blk(base.h3!) : null,
    ));
  }

  @override
  Widget build(BuildContext context) {
    if (!_loaded || _controllers.isEmpty) {
      return const Center(
          child: CircularProgressIndicator(color: Color(0xFF4FC3F7)));
    }
    final activeIdx = _activeIndex.clamp(0, _controllers.length - 1);
    final blackStyles = _blackStyles(context);
    return Container(
      color: const Color(0xFF2B2B3A), // 用紙のまわり (机の色)
      child: Column(children: [
        // ── 書式ツールバー (Word のリボン相当) ── アクティブページに紐づく。
        //   key を活性ページで変えてページ切替時に確実に貼り替える。
        Material(
          color: const Color(0xFF1E1E32),
          child: _whiteQuillSimpleToolbar(_controllers[activeIdx],
              key: ValueKey('doc_toolbar_$activeIdx')),
        ),
        // ── ページ操作バー (縦/横切替・ページめくり・追加・削除) ──
        _buildDocControlBar(activeIdx),
        // ── 用紙本体 ──
        Expanded(
          child: _horizontal
              ? _buildHorizontal(blackStyles)
              : _buildVertical(blackStyles),
        ),
      ]),
    );
  }

  /// 文字数カウント表示の更新 (= ユーザー要望: テキスト文字数をカウント
  /// できる機能)。 打鍵ごとの setState を避けるため 300ms デバウンス。
  Timer? _charCountTimer;
  void _onDocCharsChanged() {
    _charCountTimer?.cancel();
    _charCountTimer = Timer(const Duration(milliseconds: 300), () {
      if (mounted) setState(() {});
    });
  }

  /// 全用紙ページの合計文字数 (改行除く, 空白除く)。
  (int, int) _docCharCounts() {
    var total = 0, noSpace = 0;
    for (final c in _controllers) {
      final t = c.document.toPlainText().replaceAll('\n', '');
      total += t.length;
      noSpace += t.replaceAll(RegExp(r'\s'), '').length;
    }
    return (total, noSpace);
  }

  /// ページ操作バー: 縦/横の入れ替え、 横開き時のページめくり、 ページ追加/削除。
  /// 用紙の余白を決める画面 (= ユーザー要望: ヘッダーやフッターの余白などを
  /// もっと自由に設定できるように)。 上 = ヘッダー側、 下 = フッター側。
  /// 変えるとその場で紙に反映され、 次回も同じ余白で開く。
  /// 余白を触った側 (ヘッダー側 = 用紙の上端 / フッター側 = 下端) が
  /// 見えるところまで用紙を動かす (= ユーザー要望: フッターの余白を
  /// 動かす時は、 フッターの所に画面が移動して変化を確かめられるように)。
  /// 縦開きの時だけ効く (横開きは 1 ページが丸ごと見えているため)。
  void _scrollToPaperEdge({required bool footer}) {
    if (_horizontal || !_paperScroll.hasClients) return;
    if (_paperPageHeight <= 0) return;
    final pos = _paperScroll.position;
    final viewport = pos.viewportDimension;
    // 今見ているページ (表紙がある分だけ 1 つ後ろにずれる)。
    final slot = _activeIndex + (_paperHasCover ? 1 : 0);
    final top = slot * _paperPageHeight;
    final target = footer
        ? (top + _paperPageHeight - viewport) // 下端を画面の底に合わせる
        : top; // 上端を画面の頭に合わせる
    _paperScroll.animateTo(
      target.clamp(pos.minScrollExtent, pos.maxScrollExtent).toDouble(),
      duration: const Duration(milliseconds: 220),
      curve: Curves.easeOut,
    );
  }

  Future<void> _showDocMarginDialog() async {
    final provider = context.read<MindMapProvider>();
    await showDialog<void>(
      context: context,
      // ── 用紙を隠さないよう右端に寄せる (= ユーザー要望: 値を変えながら
      //    どう変わるか確認できるように)。 画面中央だと紙の上に重なる。 ──
      barrierColor: Colors.black26,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        Widget row(String label, double value, ValueChanged<double> onChanged,
            {bool? footerSide}) {
          return Row(children: [
            SizedBox(
              width: 92,
              child: Text(label,
                  style: const TextStyle(color: Colors.white70, fontSize: 12)),
            ),
            Expanded(
              child: Slider(
                value: value.clamp(0.0, 200.0),
                min: 0,
                max: 200,
                divisions: 40,
                label: '${value.round()}',
                // 触った瞬間に、 その余白がある側へ用紙を動かす。
                onChangeStart: footerSide == null
                    ? null
                    : (_) => _scrollToPaperEdge(footer: footerSide),
                onChanged: (v) {
                  onChanged(v);
                  setD(() {});
                  setState(() {});
                },
                onChangeEnd: (_) => _persistDocMargins(),
              ),
            ),
            SizedBox(
              width: 38,
              child: Text('${value.round()}',
                  textAlign: TextAlign.right,
                  style: const TextStyle(color: Colors.white, fontSize: 12)),
            ),
          ]);
        }

        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          // 用紙の上に重ならないよう右端に寄せる。
          alignment: Alignment.centerRight,
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
          title: Text(provider.t('doc.margins'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
          content: SizedBox(
            width: 380,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              row(provider.t('doc.marginTop'), _padTop, (v) => _padTop = v,
                  footerSide: false),
              row(provider.t('doc.marginBottom'), _padBottom,
                  (v) => _padBottom = v, footerSide: true),
              row(provider.t('doc.marginLeft'), _padLeft, (v) => _padLeft = v),
              row(provider.t('doc.marginRight'), _padRight,
                  (v) => _padRight = v),
              const SizedBox(height: 6),
              Text(provider.t('doc.marginHint'),
                  style: const TextStyle(
                      color: Colors.white38, fontSize: 10.5, height: 1.4)),
            ]),
          ),
          actions: [
            TextButton(
              onPressed: () {
                setState(() {
                  _padTop = _kDefaultPadTop;
                  _padBottom = _kDefaultPadBottom;
                  _padLeft = _kDefaultPadLeft;
                  _padRight = _kDefaultPadRight;
                });
                setD(() {});
                // ignore: discarded_futures
                _persistDocMargins();
              },
              child: Text(provider.t('btn.reset'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.close'),
                  style: const TextStyle(color: Color(0xFF4FC3F7))),
            ),
          ],
        );
      }),
    );
  }

  Widget _buildDocControlBar(int activeIdx) {
    final total = _controllers.length;
    final provider = context.read<MindMapProvider>();

    Widget buildPrimaryControls() => Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            // ── 文字数カウント (= ユーザー要望) ──
            Padding(
              padding: const EdgeInsets.only(left: 8, right: 4),
              child: Builder(builder: (_) {
                final (chars, noSpace) = _docCharCounts();
                return Text(
                  provider
                      .t('doc.charCount')
                      .replaceFirst('{n}', '$chars')
                      .replaceFirst('{m}', '$noSpace'),
                  style:
                      const TextStyle(color: Colors.white54, fontSize: 11),
                );
              }),
            ),
            TextButton.icon(
              onPressed: _toggleLayout,
              style: TextButton.styleFrom(
                  padding: const EdgeInsets.symmetric(horizontal: 8)),
              icon: Icon(
                  _horizontal
                      ? Icons.menu_book_rounded
                      : Icons.vertical_distribute_rounded,
                  color: const Color(0xFF4FC3F7),
                  size: 18),
              label: Text(_horizontal ? '横開き' : '縦開き',
                  style: const TextStyle(color: Colors.white, fontSize: 12)),
            ),
            // ── 余白の設定 (= ユーザー要望: ヘッダーやフッターの余白などを
            //    もっと自由に設定できるように) ──
            IconButton(
              tooltip: provider.t('doc.margins'),
              visualDensity: VisualDensity.compact,
              icon: const Icon(Icons.crop_free_rounded,
                  color: Color(0xFF9CCC65), size: 18),
              onPressed: _showDocMarginDialog,
            ),
            IconButton(
              tooltip: _coverPath == null ? '表紙テンプレートを選択' : '表紙を変更/外す',
              visualDensity: VisualDensity.compact,
              icon: Icon(
                  _coverPath == null
                      ? Icons.book_outlined
                      : Icons.auto_stories_rounded,
                  color: const Color(0xFFBA68C8),
                  size: 18),
              onPressed: _onCoverButton,
            ),
            IconButton(
              tooltip: widget.provider.t('docx.insertImage'),
              visualDensity: VisualDensity.compact,
              icon: const Icon(Icons.image_rounded,
                  color: Color(0xFF66BB6A), size: 18),
              onPressed: _pickAndInsertImage,
            ),
            IconButton(
              tooltip: widget.provider.t('doc.pasteClipboard'),
              visualDensity: VisualDensity.compact,
              icon: const Icon(Icons.content_paste_rounded,
                  color: Color(0xFF4FC3F7), size: 17),
              onPressed: () => _pasteIntoController(
                  _activeIndex.clamp(0, _controllers.length - 1)),
            ),
            IconButton(
              tooltip:
                  _headerFooterEditMode ? 'ヘッダー／フッター編集を終了' : 'ヘッダー／フッターを編集',
              visualDensity: VisualDensity.compact,
              icon: Icon(
                Icons.vertical_align_center_rounded,
                color: _headerFooterEditMode
                    ? const Color(0xFFFFC107)
                    : Colors.white70,
                size: 18,
              ),
              onPressed: _toggleHeaderFooterEditMode,
            ),
            // ── 用紙設定 (罫線) = ユーザー要望: Word のような
            //    真っ白な正式文書も書けるよう、 それぞれ消せるようにする ──
            PopupMenuButton<String>(
              tooltip: provider.t('doc.paperSettings'),
              icon: Icon(Icons.tune_rounded,
                  color: _showRuledLines
                      ? Colors.white70
                      : const Color(0xFFFFC107),
                  size: 18),
              color: const Color(0xFF252535),
              onSelected: (v) {
                setState(() {
                  if (v == 'ruled') _showRuledLines = !_showRuledLines;
                  if (v == 'word') _showRuledLines = false;
                  if (v == 'note') _showRuledLines = true;
                });
                _save();
              },
              itemBuilder: (_) {
                Widget check(bool on, String label) => Row(children: [
                      Icon(
                          on
                              ? Icons.check_box_rounded
                              : Icons.check_box_outline_blank_rounded,
                          color: const Color(0xFF80CBC4),
                          size: 18),
                      const SizedBox(width: 8),
                      Text(label,
                          style: const TextStyle(
                              color: Colors.white, fontSize: 13)),
                    ]);
                return [
                  PopupMenuItem(
                      value: 'ruled',
                      child:
                          check(_showRuledLines, provider.t('doc.showRuled'))),
                  const PopupMenuDivider(),
                  PopupMenuItem(
                      value: 'word',
                      child: Row(children: [
                        const Icon(Icons.description_rounded,
                            color: Color(0xFF4FC3F7), size: 18),
                        const SizedBox(width: 8),
                        Text(provider.t('doc.styleWord'),
                            style: const TextStyle(
                                color: Colors.white, fontSize: 13)),
                      ])),
                  PopupMenuItem(
                      value: 'note',
                      child: Row(children: [
                        const Icon(Icons.menu_book_rounded,
                            color: Color(0xFF80CBC4), size: 18),
                        const SizedBox(width: 8),
                        Text(provider.t('doc.styleNote'),
                            style: const TextStyle(
                                color: Colors.white, fontSize: 13)),
                      ])),
                ];
              },
            ),
          ],
        );

    Widget buildPageControls() => Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (_horizontal) ...[
              IconButton(
                tooltip: provider.t('docNav.prevPage'),
                visualDensity: VisualDensity.compact,
                icon: const Icon(Icons.chevron_left, color: Colors.white70),
                onPressed: activeIdx > 0
                    ? () => _pageCtrl.animateToPage(activeIdx - 1,
                        duration: const Duration(milliseconds: 250),
                        curve: Curves.easeOut)
                    : null,
              ),
              Text('${activeIdx + 1} / $total',
                  style: const TextStyle(color: Colors.white, fontSize: 12)),
              IconButton(
                tooltip: provider.t('docNav.nextPage'),
                visualDensity: VisualDensity.compact,
                icon: const Icon(Icons.chevron_right, color: Colors.white70),
                onPressed: activeIdx < total - 1
                    ? () => _pageCtrl.animateToPage(activeIdx + 1,
                        duration: const Duration(milliseconds: 250),
                        curve: Curves.easeOut)
                    : null,
              ),
            ] else
              Text(
                  provider.t('docNav.totalPages').replaceFirst('{n}', '$total'),
                  style: const TextStyle(color: Colors.white54, fontSize: 12)),
            const SizedBox(width: 4),
            if (total > 1)
              IconButton(
                tooltip: provider
                    .t('docNav.deletePageN')
                    .replaceFirst('{n}', '${activeIdx + 1}'),
                visualDensity: VisualDensity.compact,
                icon:
                    const Icon(Icons.delete_outline, color: Color(0xFFEF9A9A)),
                onPressed: () => _deletePage(activeIdx),
              ),
            // 文字付きのボタンにして見つけやすくする (= ユーザー要望:
            //   「ページを追加できない」 → ボタンの存在が分かるように)。
            TextButton.icon(
              onPressed: _addPage,
              style: TextButton.styleFrom(
                  padding: const EdgeInsets.symmetric(horizontal: 8)),
              icon: const Icon(Icons.note_add_outlined,
                  color: Color(0xFF80CBC4), size: 18),
              label: Text(provider.t('docNav.addPage'),
                  style: const TextStyle(color: Colors.white, fontSize: 12)),
            ),
          ],
        );

    return Container(
      height: 40,
      color: const Color(0xFF181826),
      padding: const EdgeInsets.symmetric(horizontal: 6),
      child: LayoutBuilder(builder: (barCtx, constraints) {
        if (constraints.maxWidth >= 720) {
          return Stack(children: [
            Center(child: buildPrimaryControls()),
            Align(
              alignment: Alignment.centerRight,
              child: buildPageControls(),
            ),
          ]);
        }
        return SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          child: Row(children: [
            buildPrimaryControls(),
            const SizedBox(width: 16),
            buildPageControls(),
          ]),
        );
      }),
    );
  }

  /// 縦開き: ページを縦に積んで 1 本のスクロールでめくる (= ユーザー要望)。
  /// ページの高さは幅 × A4 縦比で固定し、 あふれた段落は次ページへ送る。
  Widget _buildVertical(DefaultStyles blackStyles) {
    final bool hasCover = _coverPath != null && _coverPath!.isNotEmpty;
    return LayoutBuilder(builder: (lctx, constraints) {
      final pageW =
          math.min(820.0, math.max(320.0, constraints.maxWidth - 28));
      final pageH = pageW * _kPageAspect;
      _pageContentMaxH = pageH - _padTop - _padBottom;
      _paperPageHeight = pageH + 28; // 用紙の上下に付く余白 (Padding.all(14))
      _paperHasCover = hasCover;
      return ListView.builder(
        controller: _paperScroll,
        padding: EdgeInsets.zero,
        // 表紙がある場合は先頭 (index 0) に表紙を出し、 ページはその後ろへ
        //   (= ユーザー要望: ノートに表紙)。 表紙はスクロールで消える。
        itemCount: _controllers.length + (hasCover ? 1 : 0),
        itemBuilder: (ctx, idx) {
          if (hasCover && idx == 0) return _buildCover(pageW, pageH);
          final i = hasCover ? idx - 1 : idx;
          return _buildPaperPage(i, blackStyles,
              pageWidth: pageW, pageHeight: pageH, ownScroll: false);
        },
      );
    });
  }

  /// 横開き: ページを左右にめくる。 各ページは自前で縦スクロールする
  /// (= ユーザー要望)。
  Widget _buildHorizontal(DefaultStyles blackStyles) {
    return LayoutBuilder(builder: (lctx, constraints) {
      final pageW =
          math.min(820.0, math.max(320.0, constraints.maxWidth - 28));
      final pageH = pageW * _kPageAspect;
      _pageContentMaxH = pageH - _padTop - _padBottom;
      return PageView.builder(
        controller: _pageCtrl,
        itemCount: _controllers.length,
        onPageChanged: (i) {
          if (mounted) setState(() => _activeIndex = i);
        },
        itemBuilder: (ctx, i) => _buildPaperPage(i, blackStyles,
            pageWidth: pageW, pageHeight: pageH, ownScroll: true),
      );
    });
  }

  /// 1 ページ分の「白い用紙 + 罫線 + 本文エディタ」 を描く。
  /// [ownScroll] true (横開き) の時各ページが自前で縦スクロールし、
  /// false (縦開き) の時外側の ListView がまとめてスクロールする。
  /// ページ高は用紙サイズ (幅 × A4 縦比) で固定し (= Word と同じ)、 本文は
  /// OverflowBox で自然な高さにレイアウトして実高さを _contentKeys で測り、
  /// 用紙からあふれた段落は次ページへ送る (= ユーザー要望: 最終行から
  /// あふれたら次のページに進む)。 あふれの瞬間は ClipRect で隠す。
  Widget _buildPaperPage(int i, DefaultStyles blackStyles,
      {required double pageWidth,
      required double pageHeight,
      required bool ownScroll}) {
    // ビルドのたびに (次フレームで) あふれ検査を予約しておく。 スクロールして
    //   初めて画面に入ったページもここで測れる。 Timer でまとめられるので軽い。
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _scheduleReflow();
    });
    final paper = DecoratedBox(
      decoration: const BoxDecoration(
        color: Colors.white,
        boxShadow: [BoxShadow(color: Colors.black54, blurRadius: 14)],
      ),
      child: SizedBox(
        height: pageHeight,
        child: ClipRect(
          child: Stack(children: [
            // 罫線 (背景) — 用紙いっぱいに描く
            Positioned.fill(
              child: CustomPaint(
                painter: _RuledLinePainter(
                  lineHeight: _lineH,
                  topPad: _padTop,
                  leftPad: _padLeft,
                  rightPad: _padRight,
                  showLines: _showRuledLines,
                ),
              ),
            ),
            // ── ヘッダー / フッターは余白の帯の中に置く (= ユーザー要望:
            //    フッター側の余白を動かした時に、 フッターの位置がどう
            //    変わるか見えるように)。 本文のすぐ外側に寄せるので、
            //    余白を広げるとその分だけ紙の端から離れる。 ──
            Positioned(
              top: math.max(6.0, _padTop - 34),
              left: _padLeft,
              right: _padRight,
              child: _buildHeaderFooterField(
                controller: _headerCtrl,
                hint: 'ヘッダー',
                textAlign: TextAlign.left,
              ),
            ),
            Positioned(
              bottom: math.max(6.0, _padBottom - 34),
              left: _padLeft,
              right: _padRight,
              child: _buildHeaderFooterField(
                controller: _footerCtrl,
                hint: 'フッター',
                textAlign: TextAlign.center,
              ),
            ),
            // 本文エディタ。 OverflowBox で自然な高さにレイアウトし、 実高さを
            //   _contentKeys[i] で測る (あふれ → 次ページ送りの判定材料)。
            Positioned.fill(
              child: OverflowBox(
                alignment: Alignment.topLeft,
                minHeight: 0,
                maxHeight: double.infinity,
                child: Padding(
                  padding:
                      EdgeInsets.fromLTRB(_padLeft, _padTop, _padRight, 0),
                  child: Container(
                    key: i < _contentKeys.length ? _contentKeys[i] : null,
                    alignment: Alignment.topLeft,
                    child: DefaultTextStyle(
                      style: const TextStyle(color: Colors.black87),
                      child: QuillEditor.basic(
                        controller: _controllers[i],
                        focusNode: _focusNodes[i],
                        config: QuillEditorConfig(
                          customStyles: blackStyles,
                          placeholder: '文章を入力…',
                          padding: EdgeInsets.zero,
                          scrollable: false,
                          expands: false,
                          // 貼り付けた画像を描画 (= ユーザー要望: ノートに画像を貼れる)。
                          embedBuilders: const [_DocImageEmbedBuilder()],
                          // ── Ctrl/Cmd+V を横取りして画像/URL/テキストを賢く貼り付ける
                          //    (= ユーザー要望: 画像の貼り付け、 URL はハイパーリンクに)。
                          //    クリップボード読取は非同期なのでマイクロタスクで実行し、
                          //    既定の貼り付けは抑止する。
                          onKeyPressed: (event, qnode) {
                            if (event is KeyDownEvent &&
                                event.logicalKey == LogicalKeyboardKey.keyV &&
                                (HardwareKeyboard.instance.isControlPressed ||
                                    HardwareKeyboard
                                        .instance.isMetaPressed)) {
                              Future.microtask(() => _pasteIntoController(i));
                              return KeyEventResult.handled;
                            }
                            return null;
                          },
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ]),
        ),
      ),
    );

    // 用紙を中央寄せ + 余白。 幅は呼び出し側で計算した pageWidth で固定する。
    final framed = Padding(
      padding: const EdgeInsets.all(14),
      child: Align(
        alignment: Alignment.topCenter,
        heightFactor: 1.0,
        child: SizedBox(width: pageWidth, child: paper),
      ),
    );

    if (ownScroll) {
      return SingleChildScrollView(child: framed);
    }
    return framed;
  }

  Widget _buildHeaderFooterField({
    required TextEditingController controller,
    required String hint,
    required TextAlign textAlign,
  }) {
    if (_headerFooterEditMode) {
      return TextField(
        controller: controller,
        textAlign: textAlign,
        maxLines: 1,
        style: const TextStyle(color: Colors.black87, fontSize: 11),
        decoration: InputDecoration(
          isDense: true,
          hintText: hint,
          hintStyle: const TextStyle(color: Colors.black38, fontSize: 11),
          contentPadding:
              const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
          enabledBorder: const UnderlineInputBorder(
            borderSide: BorderSide(color: Color(0xFFFFC107)),
          ),
          focusedBorder: const UnderlineInputBorder(
            borderSide: BorderSide(color: Color(0xFFFF9800), width: 2),
          ),
        ),
        onChanged: (_) => _saveHeaderFooter(),
      );
    }
    if (controller.text.trim().isEmpty) return const SizedBox.shrink();
    return Text(
      controller.text,
      textAlign: textAlign,
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: const TextStyle(color: Colors.black54, fontSize: 11),
    );
  }
}

class _PaintPageView extends StatefulWidget {
  final MindMapProvider provider;
  final String pageId;
  const _PaintPageView(
      {super.key, required this.provider, required this.pageId});
  @override
  State<_PaintPageView> createState() => _PaintPageViewState();
}

class _PaintPageViewState extends State<_PaintPageView> {
  /// 作られた時点の MCP 書き込み回数 (dispose の上書き防止に使う)。
  late final int _mcpTickAtInit = widget.provider.mcpContentTick;

  // ── 設定の窓は「押した所の近く」 に出す (= ユーザー要望: 画面の真ん中だと
  //    押しにくい)。 道具の並びもキャンバスも同じ扱いにできるよう、 最後に
  //    指を置いた場所を覚えておいて、 そこを起点にする。 ──
  Offset? _lastPointerPos;

  /// 押した所の近くに出すダイアログ。 位置が分からない時は今までどおり中央。
  Future<T?> _showNearDialog<T>(
      {required WidgetBuilder builder, Color? barrierColor}) {
    final at = _lastPointerPos;
    return showDialog<T>(
      context: context,
      barrierColor: barrierColor,
      builder: (dctx) {
        if (at == null) return builder(dctx);
        final screen = MediaQuery.of(dctx).size;
        // 窓のおおよその大きさ。 画面からはみ出さないように寄せる。
        // 幅は画面に収まるところまで縮める (= モバイルで右端が切れないよう)。
        final w = math.min(420.0, screen.width - 24.0);
        const h = 360.0;
        final left = (at.dx - w / 2)
            .clamp(12.0, math.max(12.0, screen.width - w - 12))
            .toDouble();
        // 押した所のすぐ下に出す。 下が足りなければ上へ。
        var top = at.dy + 14;
        if (top + h > screen.height - 12) {
          top = math.max(12.0, at.dy - h - 14);
        }
        return Stack(children: [
          Positioned(
            left: left,
            top: top,
            width: w,
            child: Material(
              type: MaterialType.transparency,
              child: MediaQuery.removeViewInsets(
                context: dctx,
                removeTop: true,
                removeBottom: true,
                child: Builder(builder: builder),
              ),
            ),
          ),
        ]);
      },
    );
  }

  static bool get _isDesktop =>
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);

  List<_PaintSheet> _sheets = [];
  int _sel = 0;
  List<_PaintNote> _notes = [];
  int _noteSel = 0;
  _PaintNote get _note => _notes[_noteSel];
  bool _loaded = false;
  bool _dirty = false;
  QuillController? _noteController;
  final FocusNode _noteFocus = FocusNode();
  Timer? _noteSaveTimer;
  bool _noteLoaded = false;
  bool _noteHorizontal = false;
  List<dynamic> _noteTailPages = const <dynamic>[];
  String get _notePrefsKey => 'document_${widget.pageId}';

  _PaintStroke? _curStroke;
  _PaintShape? _curShape;
  // 「進める (やり直し)」 用スタック (= ユーザー要望)。 新規操作・シート切替・
  //   全消去でクリアする。 要素は undo で取り除いた実体を保持する。
  final List<({String kind, Object item})> _redo = [];
  // 選択中の画像 (= ユーザー要望: 配置画像を移動・拡大縮小)。 -1 で非選択。
  int _selImage = -1;
  // 画像ドラッグの状態。
  Rect? _imgDragOrig;
  Offset _imgDragStart = Offset.zero;
  bool _imgResizing = false;

  final Map<String, ui.Image> _imageCache = {};
  // Backspace/Del で選択画像を削除するためのフォーカス (= ユーザー要望)。
  final FocusNode _paintFocus = FocusNode();

  /// ページタブ列のスクロールコントローラ (= ユーザー要望: タブ下の
  /// スクロールバーを掴んで左右に動かせるように)。
  final ScrollController _pageTabScroll = ScrollController();

  /// ページタブ列にマウスが乗っているか。 矢印キーでのページ切替は
  /// この間だけ効かせる (= ユーザー報告: フリーノートで上下カーソルを
  /// 押すとページが遷移してしまう)。
  bool _pageTabsHovered = false;

  KeyEventResult _onPaintKey(FocusNode node, KeyEvent event) {
    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
      return KeyEventResult.ignored;
    }
    // インライン編集中はテキスト編集を優先 (削除キーは TextField に任せる)。
    if (_textEditPos != null) return KeyEventResult.ignored;
    final k = event.logicalKey;
    // ── Esc: 図形/描画モードから「選択・移動」 モードへ抜ける (= ユーザー要望)。
    //   既に選択ツールなら選択を解除する。
    if (k == LogicalKeyboardKey.escape) {
      if (_tool == _PaintTool.select) {
        if (_isAnySelSet()) setState(_clearSelSets);
      } else {
        _selectTool(_PaintTool.select);
      }
      return KeyEventResult.handled;
    }
    // ── Ctrl/Cmd+D: 文書モードの ON / OFF (= ユーザー要望: 切り替える
    //    ショートカットキーが欲しい) ──
    //    書いた内容はモードごとに別々に残るので、 何度切り替えても消えない。
    if (k == LogicalKeyboardKey.keyD &&
        (HardwareKeyboard.instance.isControlPressed ||
            HardwareKeyboard.instance.isMetaPressed)) {
      // ignore: discarded_futures
      _togglePaintDocMode();
      return KeyEventResult.handled;
    }
    // ── Ctrl/Cmd+G: 選択中のオブジェクトをグループ化 / 解除 (= ユーザー要望) ──
    if (k == LogicalKeyboardKey.keyG &&
        (HardwareKeyboard.instance.isControlPressed ||
            HardwareKeyboard.instance.isMetaPressed)) {
      if (_isAnySelSet()) {
        _togglePaintGroup();
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    }
    // ── F2: 選択中のテキストボックスの中身を編集する (= ユーザー要望) ──
    // 選択ツールで 1 個だけ選んでいる時 / テキストツールで選択中の時に効く。
    if (k == LogicalKeyboardKey.f2) {
      int idx = -1;
      if (_selTextSet.length == 1) {
        idx = _selTextSet.first;
      } else if (_selText >= 0) {
        idx = _selText;
      }
      if (idx >= 0 && idx < _sheet.texts.length) {
        _startTextEdit(_sheet.texts[idx].pos, existingIndex: idx);
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    }
    if (k == LogicalKeyboardKey.delete || k == LogicalKeyboardKey.backspace) {
      // 選択さえしていればどのツールでも消せるようにする
      //   (= ユーザー要望: 挿入した表を Backspace / Delete で削除したい)。
      //   表は罫線をまとめたグループなので、 罫線を掴めば全体が選択され、
      //   ここで一括削除される。
      if (_isAnySelSet()) {
        _deleteSelectedMulti();
      } else if (_selImage >= 0 && _selImage < _sheet.images.length) {
        _deleteSelImage();
      } else if (_selText >= 0 && _selText < _sheet.texts.length) {
        _deleteSelText();
      }
      // 背後のキャンバス (前ページで選択していたノード) の誤削除を防ぐため消費。
      return KeyEventResult.handled;
    }
    // ── Ctrl+C / Ctrl+V: 選択オブジェクトのコピー & 複製 (= ユーザー要望) ──
    //   選択ツールの複数選択のほか、 画像/テキストツールの単体選択にも対応。
    //   何も選択していない時は ignored にして背後 (マップ側) の処理へ流す。
    final bool ctrl = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    // ── Ctrl/Cmd+Z / Ctrl/Cmd+Y: フリーノート内の元に戻す / 進める ──
    // ここで必ず消費して、背後のマップ本体の undo/redo が誤って
    // 発火しないようにする。インラインテキスト編集中は上の早期 return で
    // TextField 側の文字履歴を優先する。
    if (ctrl && k == LogicalKeyboardKey.keyZ) {
      if (HardwareKeyboard.instance.isShiftPressed) {
        _redoAction();
      } else {
        _undo();
      }
      return KeyEventResult.handled;
    }
    if (ctrl && k == LogicalKeyboardKey.keyY) {
      _redoAction();
      return KeyEventResult.handled;
    }
    if (ctrl && k == LogicalKeyboardKey.keyC) {
      if (_copyPaintSelection()) return KeyEventResult.handled;
      return KeyEventResult.ignored;
    }
    if (ctrl && k == LogicalKeyboardKey.keyV) {
      if (_paintClipboard.isNotEmpty) {
        _pastePaintClipboard();
      }
      // 空でも消費する: 背後 (マップ側) の _handlePaste に流れると、 ペイント
      //   ページの裏に見えないノードが作られてしまうため。
      return KeyEventResult.handled;
    }
    // ── 矢印キー: ページタブ列にマウスが乗っている時だけページ切替 ──
    //   (= ユーザー報告: フリーノートで上下カーソルを押すとページが遷移して
    //   しまう)。 ホバーしていない時は消費だけして、 背後 (マップ側のパンや
    //   フォーカス移動によるスクロール) へ流さない。
    if (k == LogicalKeyboardKey.arrowUp ||
        k == LogicalKeyboardKey.arrowDown ||
        k == LogicalKeyboardKey.arrowLeft ||
        k == LogicalKeyboardKey.arrowRight) {
      if (ctrl || HardwareKeyboard.instance.isAltPressed) {
        return KeyEventResult.ignored;
      }
      // 分割パネル (PDF/Web) にマウスがある時はそちらのスクロールを優先。
      final host = _paintHost;
      if (host != null &&
          (host._splitPanelHover || host._splitLeftPanelHover)) {
        return KeyEventResult.ignored;
      }
      if (_pageTabsHovered && event is KeyDownEvent) {
        final next = (k == LogicalKeyboardKey.arrowDown ||
                k == LogicalKeyboardKey.arrowRight)
            ? _sel + 1
            : _sel - 1;
        if (next >= 0 && next < _sheets.length) _selectPage(next);
      }
      return KeyEventResult.handled;
    }
    return KeyEventResult.ignored;
  }

  /// マップ側のキー処理 (KeyboardListener) から呼ばれる矢印キーの受け口。
  /// フォーカスがノート側に無い時でも、 タブホバー中のページ切替と
  /// 「矢印キーを背後へ流さない」 を効かせる。 戻り値 true = 消費した。
  bool _hostArrowKey(LogicalKeyboardKey k) {
    if (_textEditPos != null) return false;
    final host = _paintHost;
    if (host != null &&
        (host._splitPanelHover || host._splitLeftPanelHover)) {
      return false;
    }
    if (_pageTabsHovered) {
      final next =
          (k == LogicalKeyboardKey.arrowDown || k == LogicalKeyboardKey.arrowRight)
              ? _sel + 1
              : _sel - 1;
      if (next >= 0 && next < _sheets.length) _selectPage(next);
    }
    return true;
  }

  // ── ペイント内クリップボード (= ユーザー要望: Ctrl+C / Ctrl+V で図形・
  //   テキスト・画像を複製)。 OS クリップボードとは独立したセッション内保持。
  //   要素は clone を保持し、 貼り付ける度に +18px ずつずらして重なりを防ぐ。
  final List<Object> _paintClipboard = [];
  static const Offset _kPaintPasteShift = Offset(18, 18);

  _PaintImageItem _cloneImage(_PaintImageItem it) =>
      _PaintImageItem(it.path, it.rect);

  /// 現在の選択内容をペイント内クリップボードへコピーする。
  /// コピーできた時 true (= キーイベントを消費する)。
  bool _copyPaintSelection() {
    final items = <Object>[];
    // 選択セットは選択ツールの複数選択だけでなく、テキストツール中に掴んだ
    // 図形にも使うため、現在ツールに依存せず優先してコピーする。
    if (_isAnySelSet()) {
      for (final i in _selStrokeSet) {
        if (i < _sheet.strokes.length) {
          final stroke = _sheet.strokes[i];
          if (!stroke.erase) items.add(_cloneStroke(stroke));
        }
      }
      for (final i in _selImgSet) {
        if (i < _sheet.images.length) items.add(_cloneImage(_sheet.images[i]));
      }
      for (final i in _selShapeSet) {
        if (i < _sheet.shapes.length) items.add(_cloneShape(_sheet.shapes[i]));
      }
      for (final i in _selTextSet) {
        if (i < _sheet.texts.length) items.add(_cloneText(_sheet.texts[i]));
      }
    } else if (_selImage >= 0 && _selImage < _sheet.images.length) {
      items.add(_cloneImage(_sheet.images[_selImage]));
    } else if (_selText >= 0 && _selText < _sheet.texts.length) {
      items.add(_cloneText(_sheet.texts[_selText]));
    }
    if (items.isEmpty) return false;
    _paintClipboard
      ..clear()
      ..addAll(items);
    return true;
  }

  /// クリップボードの内容を +18px ずらして貼り付け、 貼り付けた要素を
  /// 選択ツールで選択状態にする (= 連続 Ctrl+V でカスケード配置)。
  void _pastePaintClipboard() {
    if (_paintClipboard.isEmpty) return;
    const d = _kPaintPasteShift;
    final before = _makeEraseSnapshot();
    setState(() {
      _tool = _PaintTool.select;
      _clearSelSets();
      _selImage = -1;
      _selText = -1;
      _rangeRect = null;
      for (final it in _paintClipboard) {
        if (it is _PaintStroke) {
          final c = _cloneStroke(it);
          _shiftPaintStroke(c, d);
          _sheet.strokes.add(c..z = _nextPaintZ()..lyr = _activeLayer);
          _selStrokeSet.add(_sheet.strokes.length - 1);
        } else if (it is _PaintImageItem) {
          _sheet.images
              .add(_PaintImageItem(it.path, it.rect.shift(d))..z = _nextPaintZ()..lyr = _activeLayer);
          _selImgSet.add(_sheet.images.length - 1);
        } else if (it is _PaintShape) {
          final c = _cloneShape(it);
          c.a += d;
          c.b += d;
          _shiftPaintErasers(c.erasers, d);
          _sheet.shapes.add(c..z = _nextPaintZ()..lyr = _activeLayer);
          _selShapeSet.add(_sheet.shapes.length - 1);
        } else if (it is _PaintText) {
          final c = _cloneText(it);
          c.pos += d;
          _shiftPaintErasers(c.erasers, d);
          _sheet.texts.add(c..z = _nextPaintZ()..lyr = _activeLayer);
          _selTextSet.add(_sheet.texts.length - 1);
        }
      }
      // 次の貼り付けが今回の位置からさらにずれるよう、 保持内容も進める。
      for (final it in _paintClipboard) {
        if (it is _PaintStroke) {
          _shiftPaintStroke(it, d);
        } else if (it is _PaintImageItem) {
          it.rect = it.rect.shift(d);
        } else if (it is _PaintShape) {
          it.a += d;
          it.b += d;
          _shiftPaintErasers(it.erasers, d);
        } else if (it is _PaintText) {
          it.pos += d;
          _shiftPaintErasers(it.erasers, d);
        }
      }
      _pushPaintSnapshotEdit(before);
    });
    _persist();
  }

  /// 選択中オブジェクトをその場で複製する (= モバイル用の複製ボタン。
  /// Ctrl+C → Ctrl+V と同じ結果になる)。
  void _duplicatePaintSelection() {
    if (!_copyPaintSelection()) return;
    _pastePaintClipboard();
  }

  void _deleteSelImage() {
    if (_selImage < 0 || _selImage >= _sheet.images.length) return;
    setState(() {
      _sheet.images.removeAt(_selImage);
      // undo スタックから image を1つ取り除いて件数の整合を保つ。
      final i = _sheet.undo.lastIndexOf('image');
      if (i >= 0) _sheet.undo.removeAt(i);
      _selImage = -1;
      _redo.clear();
      _dirty = true;
    });
    _persist();
  }

  Color _color = const Color(0xFF000000);
  double _penWidth = 4;
  double _eraserWidth = 16;

  /// ペンの種類 ('' = 通常 / 'chalk' / 'squiggle' / 'dotted' / 'dashed' /
  /// 'marker') (= ユーザー要望: 種類を増やす)。
  String _penStyle = '';

  /// ペンの濃さ (不透明度) と 間隔/スケール (= ユーザー要望: 詳細設定)。
  double _penOpacity = 1.0;
  double _penInterval = 1.0;

  /// 輝き (グロー) トグル (= ユーザー要望: 文字や線に輝きを付けられるように)。
  /// ペン / 図形 / テキストの各ツールで個別に ON/OFF できる。
  bool _penGlow = false;
  bool _shapeGlow = false;
  bool _textGlow = false;

  /// 手振れ補正 (= ユーザー要望: 手振れ補正機能をフリーノートに搭載)。
  /// ON の間、 ペンの点列を指数移動平均で平滑化してガタつきを抑える。
  /// 強度 (0.15〜0.85) が大きいほど滑らか (追従は緩やか) になる。
  bool _penStabilize = false;
  double _penStabilizeStrength = 0.5;

  /// 新規テキストの文字色の濃さ (不透明度 0.2〜1.0)
  /// (= ユーザー要望: 文字色の濃さを調整できるように)。
  double _textAlpha = 1.0;

  /// キャンバスの回転角 (度)。 0 = 通常 (= ユーザー要望: ノート自体を
  /// 回転させながら文字などを書けるように)。 描画・入力とも Transform.rotate
  /// のヒットテスト逆変換で座標が合うので、 どの角度でもそのまま書ける。
  double _canvasRotationDeg = 0;

  /// 回転ボタンを 1 回押した時のステップ角と方向 (= ユーザー要望: 押す度に
  /// 既定 15° ずつ回転し、 長押しで角度と時計回り/反時計回りを指定できる)。
  double _canvasRotStep = 15;
  bool _canvasRotCw = true;

  // ── ページの画面分割 (= ユーザー要望: 別々のページを PC は左右、
  //    モバイルは上下に表示し、 どちらも編集でき、 要素を D&D で
  //    ページ間移動できるように) ──
  /// 分割表示 ON/OFF。
  bool _paintSplit = false;

  /// 非アクティブ側ペインのキャンバス実矩形 (ドロップ座標変換用)。
  final GlobalKey _splitPaneCanvasKey = GlobalKey();

  /// 分割ペインの表示倍率と、 実際に表示中のページ index (build で更新)。
  double _splitPaneFit = 1.0;
  int _splitPaneIndex = -1;

  /// 選択ドラッグ中のグローバル座標 (分割ペインへのドロップ判定に使う)。
  Offset? _selDragGlobal;

  /// 回転ボタンのタップ: ステップぶん回す (-180..180 に折り返し)。
  /// [cw] true = 時計回り、 false = 反時計回り
  /// (= ユーザー要望: 1 つのボタンにまとめず別々に並べる)。
  void _rotateCanvasBy(bool cw) {
    setState(() {
      var deg = _canvasRotationDeg + (cw ? _canvasRotStep : -_canvasRotStep);
      deg = ((deg + 540) % 360) - 180;
      _canvasRotationDeg = deg.roundToDouble();
      _canvasRotCw = cw; // 長押しダイアログの既定値を最後の向きに合わせる
    });
  }

  Future<void> _persistCanvasRotStep() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setDouble('paintRotStep', _canvasRotStep);
      await prefs.setBool('paintRotCw', _canvasRotCw);
    } catch (_) {}
  }

  /// 用紙の色を変える前の色を積むスタック (元に戻す用)。
  /// 値が -1 の時は「色未設定 (= 白)」 を表す。
  final List<int> _bgColorUndo = [];

  /// 塗りつぶしツールの不透明度 (= ユーザー要望: 領域を個別指定して塗る)。
  double _fillAlpha = 0.85;
  // 図形ツールの既定は直線 (kind 2) — 一番よく使うため (= ユーザー要望:
  // 図形の挿入を押した時は直線がデフォルトで選択されているように)。
  int _shapeKind = 2;

  /// 新規図形の中の塗り色。 null = 塗らない (中空)。
  /// (= ユーザー要望: 「塗る」 チェックと不透明度は廃止し、 塗り色を
  ///  選んだら塗る / 未選択なら中空、 という素直な形に)
  int? _shapeFillColor;
  _PaintTool _tool = _PaintTool.pen;
  double _lastPaintFit = 1.0;
  double? _lockedTextEditFit;
  // 既定ツールがペンなのに設定行が畳まれていて、 「ペンが選ばれているのに
  // 項目が出ていない」 という見え方になっていた (= ユーザー報告)。 開いた
  // 直後から太さ・色の行を出しておく。
  bool _optionsOpen = true;
  static const Color _canvasBg = Color(0xFFFFFFFF);

  // ── 消しゴムのカーソル枠 (= ユーザー要望: 白背景でも境界が分かるように) ──
  Offset? _eraserCursor; // キャンバス座標。 null で非表示。
  Offset? _eraserLastPoint;
  _PaintEraseSnapshot? _eraserBeforeSnapshot;
  bool _eraserChanged = false;
  final Set<_PaintText> _eraserTouchedTexts = <_PaintText>{};
  final Set<_PaintShape> _eraserTouchedShapes = <_PaintShape>{};
  // ── インラインテキスト編集 (= ユーザー要望: Word の様に挿入位置で直接入力) ──
  Offset? _textEditPos; // 編集中テキストの左上 (キャンバス座標)。 null で非編集。
  int _textEditIndex = -1; // 既存テキストを編集中なら index、 新規は -1。
  final TextEditingController _textEditCtrl = TextEditingController();
  final FocusNode _textEditFocus = FocusNode();
  double _textSize = 28;

  /// 新規テキストの文字の種類 (= ユーザー要望)。 '' = 既定フォント。
  String _textFont = '';

  /// 新規テキストの曲げ強度 (-1.0〜1.0、 0 = 直線)
  /// (= ユーザー要望: 文字を図の様に曲げる + 強度調整)。
  double _textCurve = 0;

  /// 表の既定 行数/列数 (= ユーザー要望: 表ボタンは押したら既定 5×5 を
  /// そのまま挿入し、 長押し (PC は右クリック) で既定値を設定できるように)。
  /// prefs 保存。
  int _tableRows = 5;
  int _tableCols = 5;

  /// 表の既定セル背景テンプレート id ('none' = 背景なし)
  /// (= ユーザー要望: 挿入の設定項目にデザインテンプレートを用意)。
  /// prefs `paintTableTheme` に保存。
  String _tableThemeId = 'none';

  // ── レイヤー (= ユーザー要望: レイヤーを設定できるようにして、 上に
  //    配置されたレイヤーに対してのみ消しゴムを適用できるように) ──
  //
  //    描く物 (線 / 文字 / 図形 / 画像) はそれぞれ「どのレイヤーに属するか」
  //    を持つ。 新しく描いた物は**選んでいるレイヤー**に入り、 消しゴムも
  //    そのレイヤーの物にしか効かない。 前後関係 (どれが手前に描かれるか)
  //    は従来どおり z が決めるので、 見た目は今までと変わらない。
  //
  //    レイヤーの数はページ (シート) ごとに覚える。
  int _activeLayer = 0;

  /// このページで使っているレイヤーの数 (最低 1)。 実際に使われている
  /// 一番大きい番号 + 1 と、 利用者が増やした数の大きい方。
  int _layerCountPref = 1;
  int get _layerCount {
    var maxUsed = 0;
    for (final e in _sheet.strokes) {
      if (e.lyr > maxUsed) maxUsed = e.lyr;
    }
    for (final e in _sheet.texts) {
      if (e.lyr > maxUsed) maxUsed = e.lyr;
    }
    for (final e in _sheet.shapes) {
      if (e.lyr > maxUsed) maxUsed = e.lyr;
    }
    for (final e in _sheet.images) {
      if (e.lyr > maxUsed) maxUsed = e.lyr;
    }
    final used = maxUsed + 1;
    return used > _layerCountPref ? used : _layerCountPref;
  }

  /// レイヤーを 1 枚増やして、 そこを選んだ状態にする。
  void _addPaintLayer() {
    setState(() {
      _layerCountPref = _layerCount + 1;
      _activeLayer = _layerCountPref - 1;
    });
    _snack(widget.provider
        .t('paint.layerAdded')
        .replaceFirst('{n}', '${_activeLayer + 1}'));
  }

  /// ヘッダー (ノート/ページ選択 + ツールバー) の表示 / 非表示
  /// (= ユーザー要望: フリーノートのヘッダー項目の表示/非表示を切り替える
  /// ボタンを作って欲しい)。 隠すとキャンバスを広く使える。
  /// prefs `paintHeaderHidden` に保存し、 次回も同じ状態で開く。
  static const String _kHeaderHiddenKey = 'paintHeaderHidden';
  bool _headerHidden = false;

  Future<void> _loadHeaderHidden() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final v = prefs.getBool(_kHeaderHiddenKey) ?? false;
      if (v && mounted) setState(() => _headerHidden = true);
    } catch (_) {}
  }

  Future<void> _toggleHeaderHidden() async {
    final next = !_headerHidden;
    setState(() => _headerHidden = next);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool(_kHeaderHiddenKey, next);
    } catch (_) {}
  }

  // ── カーソル / テキスト枠 (選択枠) の色カスタマイズ (= ユーザー要望:
  //    フリーノートページのカーソルやテキスト枠の色をカスタマイズできる
  //    設定項目を設けて) ────────────────────────────────────────────────
  static const String _kCursorColorKey = 'paintCursorColor';
  static const String _kFrameColorKey = 'paintFrameColor';
  static const Color _kDefaultUiPink = Color(0xFFEC407A);

  /// インライン入力のキャレット色。
  Color _cursorColor = _kDefaultUiPink;

  /// 選択枠 (テキスト枠 / 図形枠 / ラバーバンド / ハンドル) の色。
  Color _frameColor = _kDefaultUiPink;

  Future<void> _loadPaintUiColors() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final c = prefs.getInt(_kCursorColorKey);
      final f = prefs.getInt(_kFrameColorKey);
      // 手振れ補正の設定も一緒に復元する (= ユーザー要望: 手振れ補正)。
      final st = prefs.getBool('paintStabilize');
      final ss = prefs.getDouble('paintStabilizeStrength');
      // 回転ステップと方向 (= ユーザー要望)。
      final rs = prefs.getDouble('paintRotStep');
      final rc = prefs.getBool('paintRotCw');
      // 表の既定 行数/列数 (= ユーザー要望)。
      final tr = prefs.getInt('paintTableRows');
      final tc = prefs.getInt('paintTableCols');
      // 表の既定セル背景テンプレート (= ユーザー要望)。
      final tt = prefs.getString('paintTableTheme');
      // ページ削除時の番号詰め設定 (未設定なら null のまま = 初回に確認)。
      if (prefs.containsKey('paintRenumberOnDelete')) {
        _renumberOnDelete = prefs.getBool('paintRenumberOnDelete');
      }
      if (mounted &&
          (c != null ||
              f != null ||
              st != null ||
              ss != null ||
              rs != null ||
              rc != null ||
              tr != null ||
              tc != null ||
              tt != null)) {
        setState(() {
          if (c != null) _cursorColor = Color(c);
          if (f != null) _frameColor = Color(f);
          if (st != null) _penStabilize = st;
          if (ss != null) {
            _penStabilizeStrength = ss.clamp(0.15, 0.85).toDouble();
          }
          if (rs != null) _canvasRotStep = rs.clamp(1.0, 180.0).toDouble();
          if (rc != null) _canvasRotCw = rc;
          if (tr != null) _tableRows = tr.clamp(1, 50);
          if (tc != null) _tableCols = tc.clamp(1, 30);
          if (tt != null) _tableThemeId = tt;
        });
      }
    } catch (_) {}
  }

  /// 手振れ補正の ON/OFF と強度を保存する (次回起動時も同じ設定で使える)。
  Future<void> _persistPenStabilize() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool('paintStabilize', _penStabilize);
      await prefs.setDouble('paintStabilizeStrength', _penStabilizeStrength);
    } catch (_) {}
  }

  Future<void> _persistPaintUiColors() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setInt(_kCursorColorKey, _cursorColor.toARGB32());
      await prefs.setInt(_kFrameColorKey, _frameColor.toARGB32());
    } catch (_) {}
  }

  /// フリーノートの各項目の説明一覧 (= ユーザー要望: アイコンだけでは
  /// 分からないから項目の説明を付けて欲しい)。 ツールバーの ? から開く。
