    final p = widget.provider;
    // (アイコン, 名前キー, 説明キー) の一覧。 ツールバー / ツール群の順。
    final rows = <(IconData, String, String)>[
      (Icons.text_fields_rounded, 'paint.toolText', 'paint.help.text'),
      (Icons.edit_rounded, 'paint.toolPen', 'paint.help.pen'),
