      (Icons.category_rounded, 'paint.toolShape', 'paint.help.shape'),
      (Icons.format_color_fill_rounded, 'paint.toolFill', 'paint.help.fill'),
      (Icons.image_rounded, 'paint.toolImage', 'paint.help.image'),
      (Icons.photo_library_outlined, 'paint.imageStash', 'paint.help.stash'),
      (Icons.highlight_alt_rounded, 'paint.toolSelectMove',
          'paint.help.select'),
      (Icons.undo_rounded, 'btn.undo', 'paint.help.undo'),
      (Icons.delete_sweep_rounded, 'paint.clearAll', 'paint.help.clearAll'),
      (Icons.aspect_ratio_rounded, 'paint.paperSize', 'paint.help.paperSize'),
      (Icons.format_line_spacing_rounded, 'paint.ruledLines',
          'paint.help.ruled'),
      (Icons.grid_on_rounded, 'paint.insertTable', 'paint.help.table'),
      (Icons.rotate_90_degrees_ccw_rounded, 'paint.rotateCanvas',
          'paint.help.rotate'),
      (Icons.palette_outlined, 'paint.uiColors', 'paint.help.uiColors'),
      (Icons.vertical_split_rounded, 'paint.splitView', 'paint.help.split'),
      (Icons.download_rounded, 'paint.export', 'paint.help.export'),
      (Icons.description_outlined, 'paint.tabsPageHint', 'paint.help.tabs'),
    ];
    await _showNearDialog<void>(
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Row(children: [
          const Icon(Icons.help_outline_rounded,
              color: Color(0xFF4FC3F7), size: 20),
          const SizedBox(width: 8),
          Text(p.t('paint.help'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
        ]),
        content: SizedBox(
          width: 380,
          height: 440,
          child: ListView.separated(
            itemCount: rows.length,
            separatorBuilder: (_, __) =>
                const Divider(color: Colors.white12, height: 12),
            itemBuilder: (_, i) {
              final r = rows[i];
              return Row(crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Icon(r.$1, size: 18, color: const Color(0xFF4FC3F7)),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(p.t(r.$2),
                                style: const TextStyle(
                                    color: Colors.white,
                                    fontSize: 13,
                                    fontWeight: FontWeight.w700)),
                            const SizedBox(height: 2),
                            Text(p.t(r.$3),
                                style: const TextStyle(
                                    color: Colors.white60,
                                    fontSize: 12,
                                    height: 1.4)),
                          ]),
                    ),
                  ]);
            },
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dctx).pop(),
            child:
                const Text('OK', style: TextStyle(color: Color(0xFFEC407A))),
          ),
        ],
      ),
    );
  }

  /// カーソル / 枠色の設定ダイアログ。 プリセット色から選ぶ。
  Future<void> _showPaintUiColorSettings() async {
    const choices = <Color>[
      _kDefaultUiPink,
      Color(0xFF4FC3F7),
      Color(0xFF66BB6A),
      Color(0xFFFFB300),
      Color(0xFFFF7043),
      Color(0xFFBA68C8),
      Color(0xFF90A4AE),
      Color(0xFF212121),
      Color(0xFFFFFFFF),
    ];
    await _showNearDialog<void>(
      builder: (dctx) => StatefulBuilder(builder: (dctx, setDlg) {
        Widget row(String label, Color current, ValueChanged<Color> onPick) {
          return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(label,
                style: const TextStyle(color: Colors.white70, fontSize: 12)),
            const SizedBox(height: 6),
            Wrap(spacing: 6, runSpacing: 6, children: [
              for (final c in choices)
                GestureDetector(
                  onTap: () {
                    onPick(c);
                    setDlg(() {});
                  },
                  child: Container(
                    width: 26,
                    height: 26,
                    decoration: BoxDecoration(
                      color: c,
                      shape: BoxShape.circle,
                      border: Border.all(
                        color: current.toARGB32() == c.toARGB32()
                            ? Colors.white
                            : Colors.white24,
                        width: current.toARGB32() == c.toARGB32() ? 2.5 : 1,
                      ),
                    ),
                  ),
                ),
            ]),
          ]);
        }

        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Text(widget.provider.t('paint.uiColors'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
          content: Column(mainAxisSize: MainAxisSize.min, children: [
            row(widget.provider.t('paint.cursorColor'), _cursorColor, (c) {
              setState(() => _cursorColor = c);
              _persistPaintUiColors();
            }),
            const SizedBox(height: 14),
            row(widget.provider.t('paint.frameColor'), _frameColor, (c) {
              setState(() => _frameColor = c);
              _persistPaintUiColors();
            }),
          ]),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
              child: const Text('OK',
                  style: TextStyle(color: Color(0xFFEC407A))),
            ),
          ],
        );
      }),
    );
  }

  /// ヘッダーの表示 / 非表示トグルボタン。 隠している時も押せるよう、
  /// 常にツールオプション欄の右端 (= 常に見えている場所) に置く。
  Widget _buildHeaderToggleButton() {
    return Tooltip(
      message: widget.provider
          .t(_headerHidden ? 'paint.showHeader' : 'paint.hideHeader'),
      child: InkWell(
        borderRadius: BorderRadius.circular(6),
        onTap: _toggleHeaderHidden,
        child: Container(
          margin: const EdgeInsets.symmetric(horizontal: 4),
          padding: const EdgeInsets.all(5),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(6),
            border: Border.all(color: Colors.white24),
          ),
          child: Icon(
            _headerHidden
                ? Icons.keyboard_double_arrow_down_rounded
                : Icons.keyboard_double_arrow_up_rounded,
            size: 16,
            color: Colors.white70,
          ),
        ),
      ),
    );
  }

  /// 文字書式プリセット (= ユーザー要望: 文字の種類 / 大きさ / 色を
  /// 何項目か保存しておいてセットで使えるように)。
  static const String _kTextPresetsKey = 'paintTextPresets_v1';
  List<_PaintTextPreset> _textPresets = [];
  // ── 既定で太字 (= ユーザー要望: テキスト入力の文字が細すぎるので
  //   デフォルトは太字に)。 太字トグルで細字 (w500) にも戻せる。
  bool _textBold = true;
  bool _textItalic = false;
  // ── テキストの選択・移動 (= ユーザー要望: 挿入後のテキストを自由に移動) ──
  int _selText = -1;
  Offset? _textDragOrig;
  Offset _textDragStart = Offset.zero;
  // テキストツールのまま図形をドラッグしているか。
  // タップは従来どおり文字入力に使い、ドラッグが成立した時だけ図形を掴む。
  bool _textToolShapeMoving = false;
  // ── 選択ツール (= ユーザー要望: 図形/画像を掴んで移動・範囲選択で一括削除) ──
  final Set<int> _selStrokeSet = {};
  final Set<int> _selImgSet = {};
  final Set<int> _selShapeSet = {};
  final Set<int> _selTextSet = {};
  Rect? _rangeRect; // ラバーバンド矩形 (キャンバス座標)
  bool _selRanging = false;
  bool _selMoving = false;
  Offset _selRangeStart = Offset.zero;
  Offset _selLastP = Offset.zero;
  _PaintShapeResizeHandle? _shapeResizeHandle;
  int _shapeResizeIndex = -1;
  _PaintShape? _shapeResizeOrig;
  _PaintEraseSnapshot? _shapeResizeBeforeSnapshot;
  bool _shapeResizeChanged = false;
  _PaintEraseSnapshot? _selectionMoveBeforeSnapshot;
  bool _selectionMoveChanged = false;

  bool _isAnySelSet() =>
      _selStrokeSet.isNotEmpty ||
      _selImgSet.isNotEmpty ||
      _selShapeSet.isNotEmpty ||
      _selTextSet.isNotEmpty;
  void _clearSelSets() {
    _selStrokeSet.clear();
    _selImgSet.clear();
    _selShapeSet.clear();
    _selTextSet.clear();
  }

  /// シート内の要素 index を参照する選択・ドラッグ状態をまとめて解除する。
  /// シート切替後に同じ index の別要素が選択済みとして扱われることを防ぐ。
  void _resetPaintSelectionState() {
    _clearSelSets();
    _selImage = -1;
    _selText = -1;
    _rangeRect = null;
    // 部分コピーの対象矩形も破棄 (別シートの座標を切り出さないように)。
    _lastRangeRect = null;
    _selRanging = false;
    _selMoving = false;
    _selRotating = false;
    _selectionMoveBeforeSnapshot = null;
    _selectionMoveChanged = false;
    _shapeResizeHandle = null;
    _shapeResizeIndex = -1;
    _shapeResizeOrig = null;
    _shapeResizeBeforeSnapshot = null;
    _shapeResizeChanged = false;
    _imgDragOrig = null;
    _imgResizing = false;
    _textDragOrig = null;
    _textToolShapeMoving = false;
  }

  bool _paintStrokeHit(_PaintStroke stroke, Offset p, double fit) {
    if (stroke.erase || stroke.points.isEmpty) return false;
    // ── なげなわ塗りは「面」 の内側で掴めるようにする (= ユーザー要望) ──
    if (stroke.ps == 'lassoFill' && stroke.points.length >= 3) {
      final path = Path()
        ..moveTo(stroke.points.first.dx, stroke.points.first.dy);
      for (int i = 1; i < stroke.points.length; i++) {
        path.lineTo(stroke.points[i].dx, stroke.points[i].dy);
      }
      path.close();
      if (path.contains(p)) return true;
    }
    final screenTolerance = 8.0 / math.max(fit, 0.01);
    final tolerance = stroke.width / 2 + screenTolerance;
    final bounds = _paintStrokeBounds(stroke, extra: screenTolerance);
    if (bounds == null || !bounds.contains(p)) return false;
    if (stroke.points.length == 1) {
      return (p - stroke.points.first).distance <= tolerance;
    }
    for (int i = 1; i < stroke.points.length; i++) {
      if (_distToSegment(p, stroke.points[i - 1], stroke.points[i]) <=
          tolerance) {
        return true;
      }
    }
    return false;
  }

  bool _paintShapeHit(_PaintShape shape, Offset p, double fit) {
    // ── Z 軸回転した図形は、 点を逆回転してから判定する (= 見た目と一致)
    //    (= ユーザー要望: 図形の回転) ──
    if (shape.rot != 0) {
      final c = Rect.fromPoints(shape.a, shape.b).center;
      final rad = -shape.rot * math.pi / 180.0;
      final d = p - c;
      p = c +
          Offset(d.dx * math.cos(rad) - d.dy * math.sin(rad),
              d.dx * math.sin(rad) + d.dy * math.cos(rad));
    }
    final tolerance = shape.width / 2 + 8.0 / math.max(fit, 0.01);
    final rect = Rect.fromPoints(shape.a, shape.b);
    switch (shape.kind) {
      case 1:
        final rx = rect.width / 2;
        final ry = rect.height / 2;
        if (rx <= 0 || ry <= 0) return (p - rect.center).distance <= tolerance;
        bool inEllipse(double xRadius, double yRadius) {
          if (xRadius <= 0 || yRadius <= 0) return false;
          final dx = (p.dx - rect.center.dx) / xRadius;
          final dy = (p.dy - rect.center.dy) / yRadius;
          return dx * dx + dy * dy <= 1;
        }

        final inOuter = inEllipse(rx + tolerance, ry + tolerance);
        if (!inOuter || shape.fill) return inOuter;
        return !inEllipse(rx - tolerance, ry - tolerance);
      case 2:
        return _distToSegment(p, shape.a, shape.b) <= tolerance;
      case 3:
        if (_distToSegment(p, shape.a, shape.b) <= tolerance) return true;
        final direction = shape.b - shape.a;
        final length = direction.distance;
        if (length < 1) return (p - shape.b).distance <= tolerance;
        final unit = direction / length;
        final normal = Offset(-unit.dy, unit.dx);
        final head = (shape.width * 2.8).clamp(18.0, 90.0);
        final base = shape.b - unit * head;
        final halfBase = head * 0.62;
        final left = base + normal * halfBase;
        final right = base - normal * halfBase;
        final arrowHead = Path()
          ..moveTo(shape.b.dx, shape.b.dy)
          ..lineTo(left.dx, left.dy)
          ..lineTo(right.dx, right.dy)
          ..close();
        return arrowHead.contains(p) ||
            _distToSegment(p, shape.b, left) <= tolerance ||
            _distToSegment(p, left, right) <= tolerance ||
            _distToSegment(p, right, shape.b) <= tolerance;
      case 4:
      case 5:
        final path = _paintPolygonPath(shape);
        if (shape.fill) return path.contains(p);
        final points = _paintPolygonPoints(shape);
        for (int i = 0; i < points.length; i++) {
          if (_distToSegment(p, points[i], points[(i + 1) % points.length]) <=
              tolerance) {
            return true;
          }
        }
        return false;
      // ── 追加図形 (星/五角形/六角形/ハート/十字) は面 Path で判定する。
      //    枠のみでも面の内側タップで掴めるようにする (= 細い輪郭を正確に
      //    突く必要がなく、 モバイルでも掴みやすい)。 ──
      case 6:
      case 7:
      case 8:
      case 9:
      case 10:
        return _paintShapeAreaPathOf(shape).contains(p) ||
            (rect.inflate(tolerance).contains(p) &&
                !rect.deflate(tolerance * 2).contains(p));
      default:
        final outer = rect.inflate(tolerance);
        if (!outer.contains(p) || shape.fill) return outer.contains(p);
        if (rect.width <= tolerance * 2 || rect.height <= tolerance * 2) {
          return true;
        }
        return !rect.deflate(tolerance).contains(p);
    }
  }

  (String, int)? _selectHitTopmost(Offset p, double fit) {
    for (int i = _sheet.texts.length - 1; i >= 0; i--) {
      final t = _sheet.texts[i];
      final s = _measureText(t);
      final r = Rect.fromLTWH(t.pos.dx, t.pos.dy, s.width < 24 ? 24 : s.width,
          s.height < 18 ? 18 : s.height);
      if (r.contains(p)) return ('text', i);
    }
    for (int i = _sheet.shapes.length - 1; i >= 0; i--) {
      final sh = _sheet.shapes[i];
      if (_paintShapeHit(sh, p, fit)) return ('shape', i);
    }
    for (int i = _sheet.strokes.length - 1; i >= 0; i--) {
      if (_paintStrokeHit(_sheet.strokes[i], p, fit)) return ('stroke', i);
    }
    for (int i = _sheet.images.length - 1; i >= 0; i--) {
      if (_sheet.images[i].rect.contains(p)) return ('image', i);
    }
    return null;
  }

  bool _isSel((String, int) h) {
    switch (h.$1) {
      case 'stroke':
        return _selStrokeSet.contains(h.$2);
      case 'image':
        return _selImgSet.contains(h.$2);
      case 'shape':
        return _selShapeSet.contains(h.$2);
      default:
        return _selTextSet.contains(h.$2);
    }
  }

  /// 次のレイヤー番号 (今ある最大 z + 1 = 一番手前)。
  int _nextPaintZ() {
    var maxZ = 0;
    for (final s in _sheet.strokes) {
      maxZ = math.max(maxZ, s.z);
    }
    for (final s in _sheet.shapes) {
      maxZ = math.max(maxZ, s.z);
    }
    for (final t in _sheet.texts) {
      maxZ = math.max(maxZ, t.z);
    }
    for (final i in _sheet.images) {
      maxZ = math.max(maxZ, i.z);
    }
    return maxZ + 1;
  }

  /// 選択中の要素 (オブジェクト参照) を集める。
  List<Object> _selectedPaintObjects() {
    final items = <Object>[];
    for (final i in _selStrokeSet) {
      if (i < _sheet.strokes.length) items.add(_sheet.strokes[i]);
    }
    for (final i in _selShapeSet) {
      if (i < _sheet.shapes.length) items.add(_sheet.shapes[i]);
    }
    for (final i in _selTextSet) {
      if (i < _sheet.texts.length) items.add(_sheet.texts[i]);
    }
    for (final i in _selImgSet) {
      if (i < _sheet.images.length) items.add(_sheet.images[i]);
    }
    return items;
  }

  int _paintZOf(Object o) => o is _PaintStroke
      ? o.z
      : o is _PaintShape
          ? o.z
          : o is _PaintText
              ? o.z
              : (o as _PaintImageItem).z;

  void _setPaintZ(Object o, int z) {
    if (o is _PaintStroke) {
      o.z = z;
    } else if (o is _PaintShape) {
      o.z = z;
    } else if (o is _PaintText) {
      o.z = z;
    } else if (o is _PaintImageItem) {
      o.z = z;
    }
  }

  int _paintGOf(Object o) => o is _PaintStroke
      ? o.g
      : o is _PaintShape
          ? o.g
          : o is _PaintText
              ? o.g
              : (o as _PaintImageItem).g;

  void _setPaintG(Object o, int g) {
    if (o is _PaintStroke) {
      o.g = g;
    } else if (o is _PaintShape) {
      o.g = g;
    } else if (o is _PaintText) {
      o.g = g;
    } else if (o is _PaintImageItem) {
      o.g = g;
    }
  }

  /// 選択を前面へ (= ユーザー要望: 選択画面でレイヤーを変えられるように)。
  /// 選択内の相対順は保ったまま、 全体の最大 z より上へ積み直す。
  void _bringPaintSelectionToFront() {
    final items = _selectedPaintObjects();
    if (items.isEmpty) return;
    items.sort((a, b) => _paintZOf(a).compareTo(_paintZOf(b)));
    setState(() {
      var z = _nextPaintZ();
      for (final o in items) {
        _setPaintZ(o, z++);
      }
      _dirty = true;
    });
    _persist();
  }

  /// 選択を背面へ。 全体の最小 z より下へ (相対順は維持)。
  void _sendPaintSelectionToBack() {
    final items = _selectedPaintObjects();
    if (items.isEmpty) return;
    items.sort((a, b) => _paintZOf(a).compareTo(_paintZOf(b)));
    var minZ = 0;
    for (final s in _sheet.strokes) {
      minZ = math.min(minZ, s.z);
    }
    for (final s in _sheet.shapes) {
      minZ = math.min(minZ, s.z);
    }
    for (final t in _sheet.texts) {
      minZ = math.min(minZ, t.z);
    }
    for (final i in _sheet.images) {
      minZ = math.min(minZ, i.z);
    }
    setState(() {
      var z = minZ - items.length;
      for (final o in items) {
        _setPaintZ(o, z++);
      }
      _dirty = true;
    });
    _persist();
  }

  /// Ctrl+G: 選択中のオブジェクトをグループ化 / 解除 (= ユーザー要望)。
  /// 全員が同じグループに属していれば解除、 それ以外は新しいグループを付与。
  void _togglePaintGroup() {
    final items = _selectedPaintObjects();
    if (items.isEmpty) return;
    final firstG = _paintGOf(items.first);
    final allSame =
        firstG != 0 && items.every((o) => _paintGOf(o) == firstG);
    if (!allSame && items.length < 2) return; // 1 個だけではグループにしない
    setState(() {
      if (allSame) {
        for (final o in items) {
          _setPaintG(o, 0);
        }
      } else {
        var maxG = 0;
        for (final o in [
          ..._sheet.strokes,
          ..._sheet.shapes,
          ..._sheet.texts,
          ..._sheet.images
        ]) {
          maxG = math.max(maxG, _paintGOf(o));
        }
        final id = maxG + 1;
        for (final o in items) {
          _setPaintG(o, id);
        }
      }
      _dirty = true;
    });
    _persist();
    _snack(widget.provider.t(
        allSame ? 'paint.ungrouped' : 'paint.grouped'));
  }

  /// 選択にグループ所属の要素が含まれていたら、 同じグループの仲間を
  /// まとめて選択に加える (= グループ化した要素は一緒に動く)。
  void _expandPaintSelectionToGroups() {
    final gids = <int>{};
    for (final o in _selectedPaintObjects()) {
      final g = _paintGOf(o);
      if (g != 0) gids.add(g);
    }
    if (gids.isEmpty) return;
    for (int i = 0; i < _sheet.strokes.length; i++) {
      if (gids.contains(_sheet.strokes[i].g)) _selStrokeSet.add(i);
    }
    for (int i = 0; i < _sheet.shapes.length; i++) {
      if (gids.contains(_sheet.shapes[i].g)) _selShapeSet.add(i);
    }
    for (int i = 0; i < _sheet.texts.length; i++) {
      if (gids.contains(_sheet.texts[i].g)) _selTextSet.add(i);
    }
    for (int i = 0; i < _sheet.images.length; i++) {
      if (gids.contains(_sheet.images[i].g)) _selImgSet.add(i);
    }
  }

  /// 「重なりを塗る」 トグル (= ユーザー要望: 図形と図形の重なる領域のみを
  /// 塗りつぶす)。 選択中の面のある図形 2 個以上に共通の fg id を付与する。
  /// 既に全員同じ fg なら解除。
  void _togglePaintIntersectFill() {
    final shapes = _selShapeSet
        .where((i) => i < _sheet.shapes.length)
        .map((i) => _sheet.shapes[i])
        .where((s) => s.kind != 2 && s.kind != 3)
        .toList();
    if (shapes.length < 2) {
      _snack(widget.provider.t('paint.intersectNeeds2'));
      return;
    }
    final firstFg = shapes.first.fg;
    final allSame = firstFg != 0 && shapes.every((s) => s.fg == firstFg);
    setState(() {
      if (allSame) {
        for (final s in shapes) {
          s.fg = 0;
        }
      } else {
        var maxFg = 0;
        for (final s in _sheet.shapes) {
          maxFg = math.max(maxFg, s.fg);
        }
        final id = maxFg + 1;
        for (final s in shapes) {
          s.fg = id;
        }
      }
      _dirty = true;
    });
    _persist();
  }

  // ── 表の外枠リサイズドラッグ (= ユーザー要望: 表は外枠だけが選択状態に
  //    なり、 四隅を掴んで大きさを変えられるように) ──
  int? _tableResizeGid;
  Rect? _tableResizeStartRect;
  int _tableResizeCornerIdx = 0; // 0=左上 1=右上 2=左下 3=右下
  _PaintEraseSnapshot? _tableResizeSnapshot;
  bool _tableResizeChanged = false;

  /// 表の外枠リサイズ中のドラッグ更新。 ドラッグ開始時のスナップショット
  /// から毎回作り直すので誤差が累積しない。 罫線だけでなく同グループの
  /// 文字 / 手書き / 画像 / セル背景も一緒に拡縮する。
  void _updateTableResize(Offset p) {
    final gid = _tableResizeGid;
    final start = _tableResizeStartRect;
    final snap = _tableResizeSnapshot;
    if (gid == null || start == null || snap == null) return;
    // 固定点 = ドラッグしている角の対角。
    final fixed = switch (_tableResizeCornerIdx) {
      0 => start.bottomRight,
      1 => start.bottomLeft,
      2 => start.topRight,
      _ => start.topLeft,
    };
    final origCorner = switch (_tableResizeCornerIdx) {
      0 => start.topLeft,
      1 => start.topRight,
      2 => start.bottomLeft,
      _ => start.bottomRight,
    };
    final ov = origCorner - fixed;
    final cv = p - fixed;
    double fx = ov.dx.abs() < 1 ? 1 : cv.dx / ov.dx;
    double fy = ov.dy.abs() < 1 ? 1 : cv.dy / ov.dy;
    // 反転と極端な縮小 / 拡大を防ぐ (最小 幅40px / 高さ30px)。
    fx = fx
        .clamp(math.max(0.05, 40.0 / math.max(1.0, start.width)), 20.0)
        .toDouble();
    fy = fy
        .clamp(math.max(0.05, 30.0 / math.max(1.0, start.height)), 20.0)
        .toDouble();
    Offset tp(Offset o) => Offset(
        fixed.dx + (o.dx - fixed.dx) * fx, fixed.dy + (o.dy - fixed.dy) * fy);
    final fMin = math.min(fx, fy);
    setState(() {
      for (int i = 0;
          i < _sheet.shapes.length && i < snap.shapes.length;
          i++) {
        final live = _sheet.shapes[i];
        if (live.g != gid) continue;
        final orig = snap.shapes[i];
        live.a = tp(orig.a);
        live.b = tp(orig.b);
      }
      for (int i = 0; i < _sheet.texts.length && i < snap.texts.length; i++) {
        final live = _sheet.texts[i];
        if (live.g != gid) continue;
        final orig = snap.texts[i];
        live.pos = tp(orig.pos);
        live.size = (orig.size * fMin).clamp(6.0, 200.0).toDouble();
      }
      for (int i = 0;
          i < _sheet.images.length && i < snap.images.length;
          i++) {
        final live = _sheet.images[i];
        if (live.g != gid) continue;
        final orig = snap.images[i];
        live.rect = Rect.fromPoints(
            tp(orig.rect.topLeft), tp(orig.rect.bottomRight));
      }
      for (int i = 0;
          i < _sheet.strokes.length && i < snap.strokes.length;
          i++) {
        final live = _sheet.strokes[i];
        if (live.g != gid) continue;
        final orig = snap.strokes[i];
        for (int k = 0;
            k < live.points.length && k < orig.points.length;
            k++) {
          live.points[k] = tp(orig.points[k]);
        }
      }
      _tableResizeChanged = true;
      _dirty = true;
    });
  }

  /// 表グループ [gid] の罫線の外接矩形 (= 表の外枠)。
  Rect? _tableGroupRect(int gid) {
    double minX = double.infinity, minY = double.infinity;
    double maxX = -double.infinity, maxY = -double.infinity;
    var found = false;
    for (final s in _sheet.shapes) {
      if (s.g != gid || s.kind != 2) continue;
      found = true;
      minX = math.min(minX, math.min(s.a.dx, s.b.dx));
      minY = math.min(minY, math.min(s.a.dy, s.b.dy));
      maxX = math.max(maxX, math.max(s.a.dx, s.b.dx));
      maxY = math.max(maxY, math.max(s.a.dy, s.b.dy));
    }
    return found ? Rect.fromLTRB(minX, minY, maxX, maxY) : null;
  }

  /// 選択中の表グループの外枠 (表選択でなければ null)。
  Rect? _selectedTableFrameRect() {
    final gid = _selectedTableGroupId();
    if (gid == null) return null;
    return _tableGroupRect(gid);
  }

  /// [gid] が表グループ (横罫線 2 本以上 + 縦罫線 2 本以上) かどうか。
  bool _isTableGid(int gid) {
    if (gid == 0) return false;
    int h = 0, v = 0;
    for (final s in _sheet.shapes) {
      if (s.g != gid || s.kind != 2) continue;
      if ((s.a.dy - s.b.dy).abs() < 0.5) {
        h++;
      } else if ((s.a.dx - s.b.dx).abs() < 0.5) {
        v++;
      }
    }
    return h >= 2 && v >= 2;
  }

  void _addSel((String, int) h) {
    Object? obj;
    if (h.$1 == 'stroke') {
      _selStrokeSet.add(h.$2);
      if (h.$2 < _sheet.strokes.length) obj = _sheet.strokes[h.$2];
    } else if (h.$1 == 'image') {
      _selImgSet.add(h.$2);
      if (h.$2 < _sheet.images.length) obj = _sheet.images[h.$2];
    } else if (h.$1 == 'shape') {
      _selShapeSet.add(h.$2);
      if (h.$2 < _sheet.shapes.length) obj = _sheet.shapes[h.$2];
    } else {
      _selTextSet.add(h.$2);
      if (h.$2 < _sheet.texts.length) obj = _sheet.texts[h.$2];
    }
    // ── 表グループの「中身」 (セル文字など、 罫線以外) は単独で選択して
    //    動かせるようにする (= ユーザー要望: 表とグループ一体になって
    //    動かせない問題の解消)。 罫線を掴んだ時は従来どおり表全体
    //    (中身ごと) を選択する。 ──
    final g = obj == null ? 0 : _paintGOf(obj);
    if (h.$1 != 'shape' && g != 0 && _isTableGid(g)) return;
    // グループ所属なら仲間も一緒に選択 (= Ctrl+G グループ化の目的)。
    _expandPaintSelectionToGroups();
  }

  void _moveSelectedBy(Offset d) {
    for (final i in _selStrokeSet) {
      if (i < _sheet.strokes.length) {
        _shiftPaintStroke(_sheet.strokes[i], d);
      }
    }
    for (final i in _selImgSet) {
      if (i < _sheet.images.length) {
        _sheet.images[i].rect = _sheet.images[i].rect.shift(d);
      }
    }
    for (final i in _selShapeSet) {
      if (i < _sheet.shapes.length) {
        _sheet.shapes[i].a += d;
        _sheet.shapes[i].b += d;
        _shiftPaintErasers(_sheet.shapes[i].erasers, d);
      }
    }
    for (final i in _selTextSet) {
      if (i < _sheet.texts.length) {
        _sheet.texts[i].pos += d;
        _shiftPaintErasers(_sheet.texts[i].erasers, d);
      }
    }
  }

  void _selectInRect(Rect r) {
    _clearSelSets();
    for (int i = 0; i < _sheet.strokes.length; i++) {
      final stroke = _sheet.strokes[i];
      if (stroke.erase) continue;
      final bounds = _paintStrokeBounds(stroke);
      if (bounds != null && r.overlaps(bounds)) _selStrokeSet.add(i);
    }
    for (int i = 0; i < _sheet.images.length; i++) {
      if (r.overlaps(_sheet.images[i].rect)) _selImgSet.add(i);
    }
    for (int i = 0; i < _sheet.shapes.length; i++) {
      final sr = Rect.fromPoints(_sheet.shapes[i].a, _sheet.shapes[i].b)
          .inflate(_sheet.shapes[i].width.clamp(2.0, 30.0) + 1);
      if (r.overlaps(sr)) _selShapeSet.add(i);
    }
    for (int i = 0; i < _sheet.texts.length; i++) {
      final t = _sheet.texts[i];
      final s = _measureText(t);
      if (r.overlaps(Rect.fromLTWH(t.pos.dx, t.pos.dy,
          s.width < 8 ? 8 : s.width, s.height < 8 ? 8 : s.height))) {
        _selTextSet.add(i);
      }
    }
  }

  ({int index, _PaintShapeResizeHandle handle})? _shapeResizeHit(
      Offset p, double fit) {
    if (_selShapeSet.length != 1) return null;
    final index = _selShapeSet.first;
    if (index < 0 || index >= _sheet.shapes.length) return null;
    // 回転中の図形はハンドル位置が見た目とズレるためリサイズ対象外
    // (移動・回転スライダーでの調整は可能)。
    if (_sheet.shapes[index].rot != 0) return null;
    // Keep the hit target roughly the same size on screen even when a large
    // sheet is fitted at a very small scale.
    final radius = 13.0 / math.max(fit, 0.01);
    _PaintShapeResizeHandle? best;
    var bestDistance = double.infinity;
    for (final entry
        in _paintShapeResizeHandleCenters(_sheet.shapes[index]).entries) {
      final distance = (p - entry.value).distance;
      if (distance <= radius && distance < bestDistance) {
        best = entry.key;
        bestDistance = distance;
      }
    }
    return best == null ? null : (index: index, handle: best);
  }

  Rect _resizedPaintShapeRect(
      Rect original, _PaintShapeResizeHandle handle, Offset pointer) {
    const minSize = 12.0;
    var left = original.left;
    var top = original.top;
    var right = original.right;
    var bottom = original.bottom;
    switch (handle) {
      case _PaintShapeResizeHandle.topLeft:
        left = math.min(pointer.dx, right - minSize);
        top = math.min(pointer.dy, bottom - minSize);
        break;
      case _PaintShapeResizeHandle.top:
        top = math.min(pointer.dy, bottom - minSize);
        break;
      case _PaintShapeResizeHandle.topRight:
        right = math.max(pointer.dx, left + minSize);
        top = math.min(pointer.dy, bottom - minSize);
        break;
      case _PaintShapeResizeHandle.right:
        right = math.max(pointer.dx, left + minSize);
        break;
      case _PaintShapeResizeHandle.bottomRight:
        right = math.max(pointer.dx, left + minSize);
        bottom = math.max(pointer.dy, top + minSize);
        break;
      case _PaintShapeResizeHandle.bottom:
        bottom = math.max(pointer.dy, top + minSize);
        break;
      case _PaintShapeResizeHandle.bottomLeft:
        left = math.min(pointer.dx, right - minSize);
        bottom = math.max(pointer.dy, top + minSize);
        break;
      case _PaintShapeResizeHandle.left:
        left = math.min(pointer.dx, right - minSize);
        break;
      case _PaintShapeResizeHandle.start:
      case _PaintShapeResizeHandle.end:
        break;
    }
    return Rect.fromLTRB(left, top, right, bottom);
  }

  void _updateShapeResize(Offset p) {
    final handle = _shapeResizeHandle;
    final original = _shapeResizeOrig;
    final index = _shapeResizeIndex;
    if (handle == null ||
        original == null ||
        index < 0 ||
        index >= _sheet.shapes.length) {
      return;
    }
    setState(() {
      final target = _sheet.shapes[index];
      if (original.kind == 2 || original.kind == 3) {
        final nextA = handle == _PaintShapeResizeHandle.start ? p : original.a;
        final nextB = handle == _PaintShapeResizeHandle.end ? p : original.b;
        target.a = nextA;
        target.b = nextB;
        target.erasers
          ..clear()
          ..addAll(_transformLineErasers(
              original.erasers, original.a, original.b, nextA, nextB));
      } else {
        final oldRect = Rect.fromPoints(original.a, original.b);
        final nextRect = _resizedPaintShapeRect(oldRect, handle, p);
        target.a = nextRect.topLeft;
        target.b = nextRect.bottomRight;
        target.erasers
          ..clear()
          ..addAll(_transformPaintErasers(original.erasers, oldRect, nextRect));
      }
      _shapeResizeChanged = target.a != original.a || target.b != original.b;
      _dirty = _dirty || _shapeResizeChanged;
    });
  }

  void _finishShapeResize() {
    final before = _shapeResizeBeforeSnapshot;
    final changed = _shapeResizeChanged;
    setState(() {
      if (changed && before != null) {
        _pushPaintSnapshotEdit(before);
      }
      _shapeResizeHandle = null;
      _shapeResizeIndex = -1;
      _shapeResizeOrig = null;
      _shapeResizeBeforeSnapshot = null;
      _shapeResizeChanged = false;
    });
    if (changed) _persist();
  }

  // ── 回転ドラッグ (= ユーザー要望: 図形を掴んだ際に回転させられるように) ──
  /// 回転ハンドルをドラッグ中か。
  bool _selRotating = false;

  /// 単一選択図形の回転ハンドル位置 (キャンバス座標)。 painter と同じ式。
  Offset? _shapeRotateHandlePos(double fit) {
    if (_selShapeSet.length != 1) return null;
    final idx = _selShapeSet.first;
    if (idx < 0 || idx >= _sheet.shapes.length) return null;
    final s = _sheet.shapes[idx];
    final rect = Rect.fromPoints(s.a, s.b);
    final c = rect.center;
    final rad = s.rot * math.pi / 180.0;
    final dist = rect.height.abs() / 2 + 26 / math.max(fit, 0.01);
    return Offset(c.dx + dist * math.sin(rad), c.dy - dist * math.cos(rad));
  }

  /// 回転ドラッグ中: ポインタと中心の角度をそのまま回転角にする
  /// (ハンドルが指に付いてくる)。 Shift で 15° スナップ。
  void _updateRotateDrag(Offset p) {
    if (!_selRotating || _selShapeSet.length != 1) return;
    final idx = _selShapeSet.first;
    if (idx < 0 || idx >= _sheet.shapes.length) return;
    final s = _sheet.shapes[idx];
    final c = Rect.fromPoints(s.a, s.b).center;
    var deg = math.atan2(p.dx - c.dx, -(p.dy - c.dy)) * 180 / math.pi;
    if (HardwareKeyboard.instance.isShiftPressed) {
      deg = (deg / 15).round() * 15.0;
    }
    setState(() {
      s.rot = deg.roundToDouble();
      _dirty = true;
    });
  }

  void _onSelectPanStart(Offset p, double fit) {
    // 回転ハンドルはリサイズ/移動より優先で判定する。
    final rotPos = _shapeRotateHandlePos(fit);
    if (rotPos != null &&
        (p - rotPos).distance <= 14 / math.max(fit, 0.01)) {
      _selRotating = true;
      _selMoving = false;
      _selRanging = false;
      _selectionMoveBeforeSnapshot = _makeEraseSnapshot();
      return;
    }
    // ── 表の外枠リサイズハンドル (= ユーザー要望: 表は外枠だけが選択
    //    状態になり、 四隅を掴んで大きさを変えられるように) ──
    final tGid = _selectedTableGroupId();
    if (tGid != null) {
      final tr = _tableGroupRect(tGid);
      if (tr != null) {
        final tol = 16 / math.max(fit, 0.01);
        final corners = <Offset>[
          tr.topLeft,
          tr.topRight,
          tr.bottomLeft,
          tr.bottomRight,
        ];
        for (var ci = 0; ci < corners.length; ci++) {
          if ((p - corners[ci]).distance <= tol) {
            _tableResizeGid = tGid;
            _tableResizeStartRect = tr;
            _tableResizeCornerIdx = ci;
            _tableResizeSnapshot = _makeEraseSnapshot();
            _tableResizeChanged = false;
            _selectionMoveBeforeSnapshot = null;
            _selectionMoveChanged = false;
            _selMoving = false;
            _selRanging = false;
            return;
          }
        }
      }
    }
    final resizeHit = _shapeResizeHit(p, fit);
    if (resizeHit != null) {
      _shapeResizeHandle = resizeHit.handle;
      _shapeResizeIndex = resizeHit.index;
      _shapeResizeOrig = _cloneShape(_sheet.shapes[resizeHit.index]);
      _shapeResizeBeforeSnapshot = _makeEraseSnapshot();
      _shapeResizeChanged = false;
      _selectionMoveBeforeSnapshot = null;
      _selectionMoveChanged = false;
      _selMoving = false;
      _selRanging = false;
      return;
    }
    final hit = _selectHitTopmost(p, fit);
    if (hit != null) {
      if (!_isSel(hit))
        setState(() {
          _clearSelSets();
          _addSel(hit);
        });
      _selMoving = true;
      _selRanging = false;
      _selLastP = p;
      _selectionMoveBeforeSnapshot = _makeEraseSnapshot();
      _selectionMoveChanged = false;
    } else {
      setState(() {
        _clearSelSets();
        _selRanging = true;
        _selRangeStart = p;
        _rangeRect = Rect.fromPoints(p, p);
      });
      _selectionMoveBeforeSnapshot = null;
      _selectionMoveChanged = false;
      _selMoving = false;
    }
  }

  void _onSelectPanUpdate(Offset p) {
    if (_tableResizeGid != null) {
      // 表の外枠リサイズ (= ユーザー要望)。
      _updateTableResize(p);
    } else if (_selRotating) {
      // 回転ドラッグ (= ユーザー要望: 掴んで回転)。
      _updateRotateDrag(p);
    } else if (_shapeResizeHandle != null) {
      _updateShapeResize(p);
    } else if (_selRanging) {
      setState(() {
        _rangeRect = Rect.fromPoints(_selRangeStart, p);
        _selectInRect(_rangeRect!);
      });
    } else if (_selMoving) {
      final d = p - _selLastP;
      _selLastP = p;
      setState(() {
        _moveSelectedBy(d);
        if (d != Offset.zero) _selectionMoveChanged = true;
        _dirty = true;
      });
    }
  }

  void _onSelectPanEnd() {
    if (_tableResizeGid != null) {
      // 表の外枠リサイズを確定 (= ユーザー要望)。
      final before = _tableResizeSnapshot;
      final changed = _tableResizeChanged;
      setState(() {
        _tableResizeGid = null;
        _tableResizeStartRect = null;
        _tableResizeSnapshot = null;
        _tableResizeChanged = false;
        if (changed && before != null) _pushPaintSnapshotEdit(before);
      });
      if (changed) _persist();
      return;
    }
    if (_selRotating) {
      // 回転を確定して Undo スナップショットを積む (= ユーザー要望)。
      final before = _selectionMoveBeforeSnapshot;
      setState(() {
        _selRotating = false;
        if (before != null) _pushPaintSnapshotEdit(before);
        _selectionMoveBeforeSnapshot = null;
      });
      _persist();
    } else if (_shapeResizeHandle != null) {
      _finishShapeResize();
    } else if (_selRanging) {
      setState(() {
        _selRanging = false;
        // 部分コピー用に最後のラバーバンド矩形を保持する (= ユーザー要望:
        // 範囲を指定して画像や図形の一部を切り取ってコピー)。
        if (_rangeRect != null && !_rangeRect!.isEmpty) {
          _lastRangeRect = _rangeRect;
        }
        _rangeRect = null;
        // 範囲選択にグループの一部が入っていたら仲間ごと選択する。
        _expandPaintSelectionToGroups();
      });
    } else if (_selMoving) {
      // ── 分割ペインへドロップしたら選択要素をそのページへ移動 ──
      //    (= ユーザー要望: 画面分割した状態で要素を D&D で移動)。
      if (_paintSplit && _trySplitDropMove()) {
        setState(() {
          _selMoving = false;
          _selectionMoveBeforeSnapshot = null;
          _selectionMoveChanged = false;
        });
        return;
      }
      final before = _selectionMoveBeforeSnapshot;
      final changed = _selectionMoveChanged;
      setState(() {
        _selMoving = false;
        if (changed && before != null) _pushPaintSnapshotEdit(before);
        _selectionMoveBeforeSnapshot = null;
        _selectionMoveChanged = false;
      });
      if (changed) _persist();
    }
  }

  void _onSelectTap(Offset p, double fit) {
    final hit = _selectHitTopmost(p, fit);
    // ── 選択済みテキストを再タップしたら編集を開始 (= ユーザー要望: 選択モード
    //    でオブジェクトを指定しても編集できない → できるように) ──
    if (hit != null &&
        hit.$1 == 'text' &&
        _selTextSet.length == 1 &&
        _selTextSet.contains(hit.$2)) {
      final i = hit.$2;
      if (i >= 0 && i < _sheet.texts.length) {
        _startTextEdit(_sheet.texts[i].pos, existingIndex: i);
        return;
      }
    }
    // ── 表のセル (空き部分) をタップしたらそのまま書き込み開始
    //    (= ユーザー要望: セルをクリックしたら中に書き込めるように)。
    //    罫線などの要素に当たった時は従来どおり選択を優先する。 ──
    // セル背景 (テンプレートの塗り長方形) に当たった時も 「空きセルの
    //   タップ」 として書き込みを開始する (背景を敷いた表でもセルに
    //   書けるように)。
    final hitIsCellBg = hit != null &&
        hit.$1 == 'shape' &&
        hit.$2 < _sheet.shapes.length &&
        _isTableCellBg(_sheet.shapes[hit.$2]);
    if ((hit == null || hitIsCellBg) && _tableCellAt(p) != null) {
      setState(_clearSelSets);
      _startTextEdit(p);
      return;
    }
    setState(() {
      _clearSelSets();
      if (hit != null) _addSel(hit);
    });
  }

  /// 選択要素のドラッグが分割ペインの上で離されたら、 そのページへ移動する
  /// (= ユーザー要望: 画面分割した状態で要素を D&D で移動)。 成功で true。
  bool _trySplitDropMove() {
    final g = _selDragGlobal;
    if (g == null || !_isAnySelSet()) return false;
    final rb =
        _splitPaneCanvasKey.currentContext?.findRenderObject() as RenderBox?;
    if (rb == null || !rb.attached) return false;
    final local = rb.globalToLocal(g);
    if (local.dx < 0 ||
        local.dy < 0 ||
        local.dx > rb.size.width ||
        local.dy > rb.size.height) {
      return false;
    }
    final targetIdx = _splitPaneIndex;
    if (targetIdx < 0 || targetIdx >= _sheets.length || targetIdx == _sel) {
      return false;
    }
    final fit2 = _splitPaneFit <= 0 ? 1.0 : _splitPaneFit;
    _moveSelectionToSheet(targetIdx, local / fit2);
    return true;
  }

  /// 選択中の要素を [targetIdx] のページへ移動する。 [target] は移動先
  /// キャンバス座標 (選択全体の中心をここへ合わせる)。
  void _moveSelectionToSheet(int targetIdx, Offset target) {
    final dst = _sheets[targetIdx];
    // ── 選択実体の収集 + 全体バウンディング ──
    final strokes = <_PaintStroke>[];
    final shapes = <_PaintShape>[];
    final texts = <_PaintText>[];
    final images = <_PaintImageItem>[];
    double minX = double.infinity,
        minY = double.infinity,
        maxX = -double.infinity,
        maxY = -double.infinity;
    void acc(Rect r) {
      minX = math.min(minX, r.left);
      minY = math.min(minY, r.top);
      maxX = math.max(maxX, r.right);
      maxY = math.max(maxY, r.bottom);
    }

    for (final i in _selStrokeSet) {
      if (i < _sheet.strokes.length && !_sheet.strokes[i].erase) {
        strokes.add(_sheet.strokes[i]);
        final b = _paintStrokeBounds(_sheet.strokes[i]);
        if (b != null) acc(b);
      }
    }
    for (final i in _selShapeSet) {
      if (i < _sheet.shapes.length) {
        shapes.add(_sheet.shapes[i]);
        acc(Rect.fromPoints(_sheet.shapes[i].a, _sheet.shapes[i].b));
      }
    }
    for (final i in _selTextSet) {
      if (i < _sheet.texts.length) {
        final t = _sheet.texts[i];
        texts.add(t);
        final s = _measureText(t);
        acc(Rect.fromLTWH(t.pos.dx, t.pos.dy, s.width, s.height));
      }
    }
    for (final i in _selImgSet) {
      if (i < _sheet.images.length) {
        images.add(_sheet.images[i]);
        acc(_sheet.images[i].rect);
      }
    }
    if (!minX.isFinite) return;
    final center = Offset((minX + maxX) / 2, (minY + maxY) / 2);
    final d = target - center;
    // 移動先の最前面 z を起点に積む。
    var z = 0;
    for (final s in dst.strokes) {
      z = math.max(z, s.z);
    }
    for (final s in dst.shapes) {
      z = math.max(z, s.z);
    }
    for (final t in dst.texts) {
      z = math.max(z, t.z);
    }
    for (final im in dst.images) {
      z = math.max(z, im.z);
    }
    z += 1;
    final before = _makeEraseSnapshot(); // 元ページの Undo 用
    setState(() {
      _redo.clear();
      // ── 追加 (移動先) ── クローンをずらして入れ、 Undo 整合のため
      //    移動先の undo 履歴にも種類を積む。
      for (final s in strokes) {
        final c = _cloneStroke(s);
        _shiftPaintStroke(c, d);
        dst.strokes.add(c..z = z++);
        dst.undo.add('stroke');
      }
      for (final s in shapes) {
        final c = _cloneShape(s);
        c.a += d;
        c.b += d;
        _shiftPaintErasers(c.erasers, d);
        c.g = s.g;
        dst.shapes.add(c..z = z++);
        dst.undo.add('shape');
      }
      for (final t in texts) {
        final c = _cloneText(t);
        c.pos += d;
        _shiftPaintErasers(c.erasers, d);
        dst.texts.add(c..z = z++);
        dst.undo.add('text');
      }
      for (final im in images) {
        dst.images.add(_PaintImageItem(im.path, im.rect.shift(d),
            z: z++, g: im.g));
        dst.undo.add('image');
      }
      // ── 削除 (元ページ) ── index 降順で取り除く。
      final strokeIdx = _selStrokeSet.toList()..sort((a, b) => b.compareTo(a));
      for (final i in strokeIdx) {
        if (i < _sheet.strokes.length) _sheet.strokes.removeAt(i);
      }
      final shapeIdx = _selShapeSet.toList()..sort((a, b) => b.compareTo(a));
      for (final i in shapeIdx) {
        if (i < _sheet.shapes.length) _sheet.shapes.removeAt(i);
      }
      final textIdx = _selTextSet.toList()..sort((a, b) => b.compareTo(a));
      for (final i in textIdx) {
        if (i < _sheet.texts.length) _sheet.texts.removeAt(i);
      }
      final imgIdx = _selImgSet.toList()..sort((a, b) => b.compareTo(a));
      for (final i in imgIdx) {
        if (i < _sheet.images.length) _sheet.images.removeAt(i);
      }
      _pushPaintSnapshotEdit(before);
      _resetPaintSelectionState();
      _dirty = true;
    });
    _persist();
    _snack(widget.provider
        .t('paint.movedToPage')
        .replaceFirst('{name}', dst.name));
  }

  /// ペイントの丸い操作ハンドルボタン (移動 / 削除)。
  Widget _paintHandleBtn(IconData icon, Color color, String tooltip) => Tooltip(
        message: tooltip,
        child: Container(
          decoration: BoxDecoration(
            color: color,
            shape: BoxShape.circle,
            border: Border.all(color: Colors.white, width: 1.5),
            boxShadow: const [
              BoxShadow(
                  color: Colors.black45, blurRadius: 4, offset: Offset(0, 1)),
            ],
          ),
          child: Icon(icon, color: Colors.white, size: 15),
        ),
      );

  /// テキストの選択枠 (= ユーザー要望: フリーハンド選択と同じ「掴みの
  /// ついていない純粋な枠」 に統一)。 枠タップで編集、 枠ドラッグでそのまま
  /// 移動できる (旧: 枠の上の掴みバーでだけ移動できた)。
  List<Widget> _buildPaintTextHandles(double fit, int idx,
      {bool clearMultiSelection = false}) {
    if (idx < 0 || idx >= _sheet.texts.length) return const [];
    final t = _sheet.texts[idx];
    final s = _measureText(t);
    // 枠は文字にぴったり + 少しの余白 (フリーハンドの枠 = bounds.inflate と
    // 同じ見え方)。 最低サイズだけ確保して空テキストでも掴める。
    final double w = math.max(14.0, s.width) * fit;
    final double h = math.max(10.0, s.height) * fit;
    final double left = t.pos.dx * fit;
    final double top = t.pos.dy * fit;

    void beginEdit() {
      if (clearMultiSelection) _clearSelSets();
      _startTextEdit(t.pos, existingIndex: idx);
    }

    return [
      Positioned(
        left: left - 3,
        top: top - 3,
        width: w + 6,
        height: h + 6,
        child: MouseRegion(
          cursor: SystemMouseCursors.move,
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: beginEdit,
            onPanUpdate: (d) {
              if (idx >= _sheet.texts.length) return;
              setState(() {
                final text = _sheet.texts[idx];
                // 罫線シートでは移動中も罫線に吸着 (通常ドラッグと同じ)。
                final next = _snapTextPosToRule(text.pos + d.delta / fit);
                _shiftPaintErasers(text.erasers, next - text.pos);
                text.pos = next;
                _dirty = true;
              });
            },
            onPanEnd: (_) => _persist(),
            child: DecoratedBox(
              decoration: BoxDecoration(
                // テキスト枠の色はカスタマイズ可能 (= ユーザー要望)。
                border: Border.all(color: _frameColor, width: 1.5),
              ),
            ),
          ),
        ),
      ),
      // ── 回転ハンドル (= ユーザー要望: 文字を掴んだ際に回転させられる) ──
      // 枠の右上に丸ボタン。 ドラッグでポインタ方向へ回転が追従する。
      Positioned(
        left: left + w + 4,
        top: top - 30,
        child: MouseRegion(
          cursor: SystemMouseCursors.grab,
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onPanUpdate: (d) => _rotateTextByGlobalPoint(idx, d.globalPosition),
            onPanEnd: (_) => _persist(),
            child: _paintHandleBtn(Icons.rotate_right_rounded,
                const Color(0xFF8E24AA), widget.provider.t('paint.rotate')),
          ),
        ),
      ),
    ];
  }

  /// テキスト回転ドラッグ (= ユーザー要望)。 グローバル座標をキャンバス座標へ
  /// 変換し、 テキスト中心との角度をそのまま回転角にする。
  void _rotateTextByGlobalPoint(int idx, Offset globalPos) {
    if (idx < 0 || idx >= _sheet.texts.length) return;
    final box =
        _paintCanvasKey.currentContext?.findRenderObject() as RenderBox?;
    if (box == null || !box.attached) return;
    final fit = _lastPaintFit;
    if (fit <= 0) return;
    final p = box.globalToLocal(globalPos) / fit;
    final t = _sheet.texts[idx];
    final s = _measureText(t);
    final c = t.pos + Offset(s.width / 2, s.height / 2);
    var deg = math.atan2(p.dx - c.dx, -(p.dy - c.dy)) * 180 / math.pi;
    if (HardwareKeyboard.instance.isShiftPressed) {
      deg = (deg / 15).round() * 15.0;
    }
    setState(() {
      t.rot = deg.roundToDouble();
      _dirty = true;
    });
  }

  List<Widget> _buildPaintTextSelHandles(double fit) {
    if (_selTextSet.length != 1) return const [];
    return _buildPaintTextHandles(fit, _selTextSet.first,
        clearMultiSelection: true);
  }

  void _deleteSelectedMulti() {
    if (!_isAnySelSet()) return;
    final before = _makeEraseSnapshot();
    setState(() {
      final strokes = _selStrokeSet.toList()..sort((a, b) => b - a);
      for (final i in strokes) {
        if (i < _sheet.strokes.length) _sheet.strokes.removeAt(i);
      }
      final imgs = _selImgSet.toList()..sort((a, b) => b - a);
      for (final i in imgs) {
        if (i < _sheet.images.length) {
          _sheet.images.removeAt(i);
        }
      }
      final shapes = _selShapeSet.toList()..sort((a, b) => b - a);
      for (final i in shapes) {
        if (i < _sheet.shapes.length) {
          _sheet.shapes.removeAt(i);
        }
      }
      final texts = _selTextSet.toList()..sort((a, b) => b - a);
      for (final i in texts) {
        if (i < _sheet.texts.length) {
          _sheet.texts.removeAt(i);
        }
      }
      _clearSelSets();
      _selImage = -1;
      _selText = -1;
      _pushPaintSnapshotEdit(before);
    });
    _persist();
  }

  static const _palette = [
    Color(0xFF000000),
    Color(0xFFE53935),
    Color(0xFF1E88E5),
    Color(0xFF43A047),
    Color(0xFFFB8C00),
    Color(0xFF8E24AA),
    Color(0xFF00ACC1),
    Color(0xFFFFEB3B),
  ];
  static const _penWidths = [2.0, 4.0, 8.0, 16.0, 28.0];
  static const _eraserWidths = [
    8.0,
    16.0,
    28.0,
    44.0,
    64.0,
    96.0,
    128.0,
    192.0,
  ];

  _PaintSheet get _sheet => _sheets[_sel];
  _PaintCanvasSize get _csize => _sizeOf(_sheet);

  /// シートの用紙サイズを解決 (= ユーザー要望: 独自サイズ指定対応)。
  /// 'custom' の時は customW/customH を採用する。
  _PaintCanvasSize _sizeOf(_PaintSheet s) {
    if (s.sizeId == 'custom') {
      final w = s.customW > 0 ? s.customW : 1000.0;
      final h = s.customH > 0 ? s.customH : 1000.0;
      return _PaintCanvasSize('custom', w, h);
    }
    return _paintSizeById(s.sizeId);
  }

  @override
  void initState() {
    super.initState();
    _load();
    _loadTextPresets();
    _loadTemplates();
    _loadHeaderHidden();
    _loadPaintUiColors();
    _loadImageStash();
    // メインの DropTarget から画像ドロップを受け取れるよう自分を登録する
    // (= ユーザー要望: フリーノートへ画像を D&D で直接入れる)。
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _paintHost = context.findAncestorStateOfType<_MindMapScreenState>();
      _paintHost?._paintDropHandler = _onPaintDropFiles;
      _paintHost?._paintArrowKeyHandler = _hostArrowKey;
    });
  }

  // ── 画像のドラッグ&ドロップ + 画像置き場 (= ユーザー要望) ──────────────
  _MindMapScreenState? _paintHost; // ドロップ受け口を登録する親 State
  final GlobalKey _paintCanvasKey = GlobalKey();
  final GlobalKey _stashKey = GlobalKey();
  bool _stashOpen = false;
  List<String> _imageStash = [];

  Future<void> _loadImageStash() async {
    try {
      final sp = await SharedPreferences.getInstance();
      final list = sp.getStringList('paintImageStash_v1') ?? const [];
      if (!mounted) return;
      setState(() => _imageStash = List.of(list));
    } catch (_) {}
  }

  Future<void> _saveImageStash() async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setStringList('paintImageStash_v1', _imageStash);
    } catch (_) {}
  }

  bool _isPaintImagePath(String p) {
    final dot = p.lastIndexOf('.');
    final ext = dot >= 0 ? p.substring(dot + 1).toLowerCase() : '';
    return const {'jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'}.contains(ext);
  }

  /// 元ファイルをアプリ内ドキュメントへコピーして永続パスを返す
  /// (D&D 元や置き場の元ファイルが消えてもノートが壊れないように)。
  Future<String?> _copyImageToAppDir(String srcPath) async {
    try {
      if (!await File(srcPath).exists()) return null;
      final dir = await getApplicationDocumentsDirectory();
      if (!await dir.exists()) await dir.create(recursive: true);
      final dot = srcPath.lastIndexOf('.');
      final ext = dot >= 0 ? srcPath.substring(dot) : '.png';
      final dst =
          '${dir.path}/paint_img_${DateTime.now().microsecondsSinceEpoch}$ext';
      await File(srcPath).copy(dst);
      return dst;
    } catch (_) {
      return null;
    }
  }

  /// 画像ファイルをシートへ挿入する (D&D / 置き場タップ共用)。
  /// [centerCanvas] があればそこを中心に配置、 無ければ用紙中央。
  Future<void> _addImageFileToSheet(String srcPath,
      {Offset? centerCanvas}) async {
    final dst = await _copyImageToAppDir(srcPath);
    if (dst == null) {
      if (mounted) _snack(widget.provider.t('paint.imagePickFailed'));
      return;
    }
    final im = await _loadUiImage(dst);
    if (im == null || !mounted) return;
    _imageCache[dst] = im;
    final cs = _csize;
    double w = im.width.toDouble();
    double h = im.height.toDouble();
    final maxW = cs.w * 0.6;
    if (w > maxW) {
      h = h * maxW / w;
      w = maxW;
    }
    final c = centerCanvas ?? Offset(cs.w / 2, cs.h / 2);
    final rect = Rect.fromCenter(center: c, width: w, height: h);
    setState(() {
      _redo.clear();
      _sheet.images.add(_PaintImageItem(dst, rect)..z = _nextPaintZ()..lyr = _activeLayer);
      _sheet.undo.add('image');
      _selImage = _sheet.images.length - 1;
      _dirty = true;
    });
    _persist();
  }

  /// メイン DropTarget から委譲されるファイルドロップ (= ユーザー要望:
  /// フリーノートへ画像を D&D で直接入れる + 置き場へ D&D で格納)。
  Future<void> _onPaintDropFiles(List<String> paths, Offset globalPos) async {
    final images = paths.where(_isPaintImagePath).toList();
    if (images.isEmpty) return;
    // 置き場パネルの上へのドロップは「格納」。
    final stashBox =
        _stashKey.currentContext?.findRenderObject() as RenderBox?;
    if (stashBox != null && stashBox.attached) {
      final r = stashBox.localToGlobal(Offset.zero) & stashBox.size;
      if (r.contains(globalPos)) {
        var ok = 0;
        for (final p in images) {
          final dst = await _copyImageToAppDir(p);
          if (dst != null) {
            _imageStash.add(dst);
            ok++;
          }
        }
        if (ok > 0 && mounted) {
          setState(() {});
          _saveImageStash();
          _snack(widget.provider.t('paint.stashStored'));
        }
        return;
      }
    }
    // 用紙上へのドロップは「その位置へ挿入」。 用紙外なら中央。
    Offset? centerCanvas;
    final canvasBox =
        _paintCanvasKey.currentContext?.findRenderObject() as RenderBox?;
    if (canvasBox != null && canvasBox.attached) {
      final local = canvasBox.globalToLocal(globalPos);
      final fit = _lastPaintFit;
      if (fit > 0 &&
          local.dx >= 0 &&
          local.dy >= 0 &&
          local.dx <= canvasBox.size.width &&
          local.dy <= canvasBox.size.height) {
        centerCanvas = local / fit;
      }
    }
    for (final p in images) {
      await _addImageFileToSheet(p, centerCanvas: centerCanvas);
      // 複数枚は少しずつずらして重なりを避ける。
      if (centerCanvas != null) {
        centerCanvas = centerCanvas + const Offset(24, 24);
      }
    }
  }

  /// ピッカーから画像置き場へ追加 (D&D が使えないモバイルでも格納できる)。
  Future<void> _pickAndAddToStash() async {
    try {
      final picked = await FilePicker.platform.pickFiles(
        dialogTitle: widget.provider.t('pick.image'),
        type: FileType.image,
        allowMultiple: true,
        withData: !_isDesktop,
      );
      if (picked == null || picked.files.isEmpty) return;
      final dir = await getApplicationDocumentsDirectory();
      if (!await dir.exists()) await dir.create(recursive: true);
      var ok = 0;
      for (final f in picked.files) {
        String? dst;
        final srcPath = f.path;
        if (srcPath != null && srcPath.isNotEmpty) {
          dst = await _copyImageToAppDir(srcPath);
        } else if (f.bytes != null && f.bytes!.isNotEmpty) {
          final dot = f.name.lastIndexOf('.');
          final ext = dot >= 0 ? f.name.substring(dot) : '.png';
          dst =
              '${dir.path}/paint_img_${DateTime.now().microsecondsSinceEpoch}$ext';
          await File(dst).writeAsBytes(f.bytes!, flush: true);
        }
        if (dst != null) {
          _imageStash.add(dst);
          ok++;
        }
      }
      if (ok > 0 && mounted) {
        setState(() {});
        _saveImageStash();
      }
    } catch (_) {}
  }

  /// 画像置き場バー (= ユーザー要望: すぐ呼び出せるよう D&D で画像を格納
  /// しておける場所)。 サムネイルをタップで用紙中央へ挿入、 長押しで置き場
  /// から削除。 ＋ボタンでピッカーからも追加できる。 バー全体が D&D の受け口。
  Widget _buildImageStashBar() {
    final p = widget.provider;
    return Container(
      key: _stashKey,
      height: 64,
      width: double.infinity,
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
      decoration: const BoxDecoration(
        color: Color(0xFF171722),
        border: Border(bottom: BorderSide(color: Colors.white12)),
      ),
      child: Row(children: [
        Tooltip(
          message: p.t('paint.stashAdd'),
          child: InkWell(
            onTap: _pickAndAddToStash,
            borderRadius: BorderRadius.circular(8),
            child: Container(
              width: 48,
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(8),
                border: Border.all(color: Colors.white24),
              ),
              child: const Icon(Icons.add_photo_alternate_outlined,
                  color: Colors.white70, size: 20),
            ),
          ),
        ),
        const SizedBox(width: 8),
        Expanded(
          child: _imageStash.isEmpty
              ? Center(
                  child: Text(p.t('paint.stashDropHint'),
                      style: const TextStyle(
                          color: Colors.white38, fontSize: 12)))
              : ListView.separated(
                  scrollDirection: Axis.horizontal,
                  itemCount: _imageStash.length,
                  separatorBuilder: (_, __) => const SizedBox(width: 6),
                  itemBuilder: (_, i) {
                    final path = _imageStash[i];
                    return Tooltip(
                      message: p.t('paint.stashInsertHint'),
                      child: GestureDetector(
                        onTap: () => _addImageFileToSheet(path),
                        onLongPress: () {
                          setState(() => _imageStash.removeAt(i));
                          _saveImageStash();
                          _snack(p.t('paint.stashRemoved'));
                        },
                        child: ClipRRect(
                          borderRadius: BorderRadius.circular(6),
                          child: Image.file(
                            File(path),
                            width: 52,
                            height: 52,
                            fit: BoxFit.cover,
                            errorBuilder: (_, __, ___) => Container(
                                width: 52,
                                height: 52,
                                color: Colors.white10,
                                child: const Icon(Icons.broken_image_rounded,
                                    color: Colors.white38, size: 18)),
                          ),
                        ),
                      ),
                    );
                  },
                ),
        ),
      ]),
    );
  }

  // ── 文字書式プリセットの読み書き (= ユーザー要望) ──
  Future<void> _loadTextPresets() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kTextPresetsKey);
      if (raw == null || raw.isEmpty) return;
      final list = (jsonDecode(raw) as List)
          .whereType<Map>()
          .map(_PaintTextPreset.fromJson)
          .toList();
      if (mounted) setState(() => _textPresets = list);
    } catch (_) {}
  }

  Future<void> _saveTextPresets() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_kTextPresetsKey,
          jsonEncode(_textPresets.map((e) => e.toJson()).toList()));
    } catch (_) {}
  }

  /// 現在の書式 (テキストツールの設定、 またはテキスト選択中ならその書式) を
  /// 新しいプリセットとして保存する。 名前は入力させる。
  Future<void> _addTextPresetFromCurrent() async {
    String font = _textFont;
    double size = _textSize;
    int color = _color.toARGB32();
    bool bold = _textBold;
    bool italic = _textItalic;
    if (_selTextSet.length == 1 && _selTextSet.first < _sheet.texts.length) {
      final t = _sheet.texts[_selTextSet.first];
      font = t.font;
      size = t.size;
      color = t.color;
      bold = t.bold;
      italic = t.italic;
    }
    final ctrl = TextEditingController(
        text: _paintFontRealName(font) + ' ' + size.round().toString());
    final name = await _showNearDialog<String>(
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(widget.provider.t('paint.presetSave'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          onSubmitted: (v) => Navigator.pop(dctx, v.trim()),
          decoration: InputDecoration(
            hintText: widget.provider.t('paint.presetName'),
            hintStyle: const TextStyle(color: Colors.white38),
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(widget.provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
              onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
              child: Text(widget.provider.t('btn.save'))),
        ],
      ),
    );
    ctrl.dispose();
    if (name == null || name.isEmpty || !mounted) return;
    setState(() {
      _textPresets.add(_PaintTextPreset(
        name: name,
        font: font,
        size: size,
        color: color,
        bold: bold,
        italic: italic,
      ));
      if (_textPresets.length > 12) _textPresets.removeAt(0);
    });
    await _saveTextPresets();
  }

  /// プリセットを適用する。 テキストを選択中ならそのテキストへ、
  /// そうでなければこれから打つ文字の設定へ反映する。
  void _applyTextPreset(_PaintTextPreset preset) {
    setState(() {
      _textFont = preset.font;
      _textSize = preset.size;
      _color = Color(preset.color);
      _textBold = preset.bold;
      _textItalic = preset.italic;
    });
    if (_selTextSet.isNotEmpty) {
      _applyTextStyleToSelection(
        color: preset.color,
        font: preset.font,
        size: preset.size,
        bold: preset.bold,
        italic: preset.italic,
      );
    }
  }

  Future<void> _deleteTextPreset(int index) async {
    if (index < 0 || index >= _textPresets.length) return;
    setState(() => _textPresets.removeAt(index));
    await _saveTextPresets();
  }

  // ── 図形テンプレート (= ユーザー要望) ────────────────────────────────
  static const String _kTemplatesKey = 'paintTemplates_v1';
  List<_PaintTemplate> _templates = [];

  Future<void> _loadTemplates() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kTemplatesKey);
      if (raw == null || raw.isEmpty) return;
      final list = (jsonDecode(raw) as List)
          .whereType<Map>()
          .map(_PaintTemplate.fromJson)
          .toList();
      if (mounted) setState(() => _templates = list);
    } catch (_) {}
  }

  Future<void> _saveTemplates() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_kTemplatesKey,
          jsonEncode(_templates.map((e) => e.toJson()).toList()));
    } catch (_) {}
  }

  /// 選択中の要素をテンプレートとして登録する。 何も選択していない時は
  /// そのページの全要素を登録する (= 「今の図をまるごとテンプレートに」)。
  Future<void> _registerTemplateFromSelection() async {
    // 対象を集める (クローンしてから原点合わせするので元データは触らない)。
    final strokes = <_PaintStroke>[];
    final shapes = <_PaintShape>[];
    final texts = <_PaintText>[];
    final images = <_PaintImageItem>[];
    if (_isAnySelSet()) {
      for (final i in _selStrokeSet) {
        if (i < _sheet.strokes.length && !_sheet.strokes[i].erase) {
          strokes.add(_cloneStroke(_sheet.strokes[i]));
        }
      }
      for (final i in _selShapeSet) {
        if (i < _sheet.shapes.length) shapes.add(_cloneShape(_sheet.shapes[i]));
      }
      for (final i in _selTextSet) {
        if (i < _sheet.texts.length) texts.add(_cloneText(_sheet.texts[i]));
      }
      for (final i in _selImgSet) {
        if (i < _sheet.images.length) {
          images.add(_cloneImage(_sheet.images[i]));
        }
      }
    } else {
      for (final st in _sheet.strokes) {
        if (!st.erase) strokes.add(_cloneStroke(st));
      }
      for (final sh in _sheet.shapes) {
        shapes.add(_cloneShape(sh));
      }
      for (final t in _sheet.texts) {
        texts.add(_cloneText(t));
      }
      for (final im in _sheet.images) {
        images.add(_cloneImage(im));
      }
    }
    if (strokes.isEmpty &&
        shapes.isEmpty &&
        texts.isEmpty &&
        images.isEmpty) {
      if (mounted) _snack(widget.provider.t('paint.templateEmpty'));
      return;
    }

    // ── 左上を原点に正規化する ──
    double minX = double.infinity;
    double minY = double.infinity;
    void see(double x, double y) {
      if (x < minX) minX = x;
      if (y < minY) minY = y;
    }

    for (final st in strokes) {
      for (final pt in st.points) {
        see(pt.dx, pt.dy);
      }
    }
    for (final sh in shapes) {
      see(math.min(sh.a.dx, sh.b.dx), math.min(sh.a.dy, sh.b.dy));
    }
    for (final t in texts) {
      see(t.pos.dx, t.pos.dy);
    }
    for (final im in images) {
      see(im.rect.left, im.rect.top);
    }
    if (!minX.isFinite || !minY.isFinite) {
      minX = 0;
      minY = 0;
    }
    final d = Offset(-minX, -minY);
    for (final st in strokes) {
      _shiftPaintStroke(st, d);
    }
    for (final sh in shapes) {
      sh.a += d;
      sh.b += d;
      _shiftPaintErasers(sh.erasers, d);
    }
    for (final t in texts) {
      t.pos += d;
      _shiftPaintErasers(t.erasers, d);
    }
    for (int i = 0; i < images.length; i++) {
      images[i].rect = images[i].rect.shift(d);
    }

    final ctrl = TextEditingController(
        text: widget.provider
            .t('paint.templateDefaultName')
            .replaceFirst('{n}', (_templates.length + 1).toString()));
    final name = await _showNearDialog<String>(
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(widget.provider.t('paint.templateRegister'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          onSubmitted: (v) => Navigator.pop(dctx, v.trim()),
          decoration: InputDecoration(
            hintText: widget.provider.t('paint.templateName'),
            hintStyle: const TextStyle(color: Colors.white38),
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(widget.provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
              onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
              child: Text(widget.provider.t('btn.save'))),
        ],
      ),
    );
    ctrl.dispose();
    if (name == null || name.isEmpty || !mounted) return;

    final items = <Map<String, dynamic>>[
      for (final st in strokes) {'t': 'stroke', 'd': st.toJson()},
      for (final sh in shapes) {'t': 'shape', 'd': sh.toJson()},
      for (final t in texts) {'t': 'text', 'd': t.toJson()},
      for (final im in images) {'t': 'image', 'd': im.toJson()},
    ];
    setState(() {
      _templates.add(_PaintTemplate(name: name, items: items));
      if (_templates.length > 30) _templates.removeAt(0);
    });
    await _saveTemplates();
    if (mounted) _snack(widget.provider.t('paint.templateSaved'));
  }

  /// テンプレートを現在のページへ挿入する。 挿入した要素は選択状態にして
  /// そのままドラッグで動かせるようにする。
  void _insertTemplate(_PaintTemplate tpl) {
    if (tpl.items.isEmpty) return;
    // 毎回少しずらして重ならないようにする。
    final d = Offset(40.0 + (_templateInsertCount % 5) * 16.0,
        40.0 + (_templateInsertCount % 5) * 16.0);
    _templateInsertCount++;
    setState(() {
      _tool = _PaintTool.select;
      _clearSelSets();
      _selImage = -1;
      _selText = -1;
      _rangeRect = null;
      for (final raw in tpl.items) {
        final type = (raw['t'] ?? '').toString();
        final data = raw['d'];
        if (data is! Map) continue;
        switch (type) {
          case 'stroke':
            final st = _PaintStroke.fromJson(data);
            _shiftPaintStroke(st, d);
            _sheet.strokes.add(st..z = _nextPaintZ()..lyr = _activeLayer);
            _selStrokeSet.add(_sheet.strokes.length - 1);
            break;
          case 'shape':
            final sh = _PaintShape.fromJson(data);
            sh.a += d;
            sh.b += d;
            _shiftPaintErasers(sh.erasers, d);
            _sheet.shapes.add(sh..z = _nextPaintZ()..lyr = _activeLayer);
            _selShapeSet.add(_sheet.shapes.length - 1);
            break;
          case 'text':
            final t = _PaintText.fromJson(data);
            t.pos += d;
            _shiftPaintErasers(t.erasers, d);
            _sheet.texts.add(t..z = _nextPaintZ()..lyr = _activeLayer);
            _selTextSet.add(_sheet.texts.length - 1);
            break;
          case 'image':
            final im = _PaintImageItem.fromJson(data);
            im.rect = im.rect.shift(d);
            _sheet.images.add(im..z = _nextPaintZ()..lyr = _activeLayer);
            _selImgSet.add(_sheet.images.length - 1);
            break;
        }
      }
      _sheet.undo.add('template');
      _redo.clear();
      _dirty = true;
    });
    _persist();
  }

  int _templateInsertCount = 0;

  Future<void> _deleteTemplate(int index) async {
    if (index < 0 || index >= _templates.length) return;
    setState(() => _templates.removeAt(index));
    await _saveTemplates();
  }

