  Future<void> _load() async {
    final d = await _PaintStore.load(
      widget.pageId,
      defaultNoteName:
          widget.provider.t('paint.defaultNoteName').replaceFirst('{n}', '1'),
      defaultPageName:
          widget.provider.t('paint.defaultPageName').replaceFirst('{n}', '1'),
    );
    if (!mounted) return;
    setState(() {
      _notes = d.notes;
      _noteSel = d.noteSel;
      _sheets = _note.pages;
      _sel = _note.selectedPage;
      _loaded = true;
    });
    // 読み込んだ旧 {sheets,sel} をここで v3 のノート/ページ形式として
    // 保存し直す。以後の起動でも同じ二階層構造を使い、移行を遅延させない。
    await _persist();
    await _importDocumentTextIntoCanvasIfNeeded();
    await _preloadImages();
  }

  Future<void> _importDocumentTextIntoCanvasIfNeeded() async {
    if (_sheets.isEmpty) return;
    final first = _sheets.first;
    final canvasIsEmpty = first.strokes.isEmpty &&
        first.images.isEmpty &&
        first.shapes.isEmpty &&
        first.texts.isEmpty;
    if (!canvasIsEmpty) return;
    try {
      final sp = await SharedPreferences.getInstance();
      final doneKey = 'paint_document_imported_${widget.pageId}';
      if (sp.getBool(doneKey) == true) return;
      final raw = sp.getString(_notePrefsKey);
      if (raw == null || raw.isEmpty) return;
      Document doc = Document();
      final decoded = jsonDecode(raw);
      if (decoded is List) {
        doc = Document.fromJson(decoded);
      } else if (decoded is Map) {
        final pages = decoded['pages'];
        if (pages is List && pages.isNotEmpty && pages.first is List) {
          doc = Document.fromJson(pages.first as List);
        }
      }
      final plain = doc.toPlainText().trimRight();
      if (plain.trim().isEmpty) {
        await sp.setBool(doneKey, true);
        return;
      }
      if (!mounted) return;
      // ★ キャンバスの文字は折り返さないので、 本文をそのまま 1 つ置くと
      //   用紙の右端からはみ出して読めなくなる (= ユーザー報告)。
      //   用紙の幅に収まる位置で改行を入れてから置く。
      const double left = 72, fontSize = 28;
      final size = _sizeOf(first);
      final wrapped = _wrapForCanvas(
          plain, math.max(80.0, size.w - left * 2), fontSize);
      setState(() {
        first.texts.add(_PaintText(
          const Offset(left, 72),
          wrapped,
          0xFF000000,
          fontSize,
          bold: false,
        ));
        first.undo.add('text');
        _dirty = true;
      });
      _note.selectedPage = _sel;
      await _PaintStore.save(widget.pageId, _notes, _noteSel);
      await sp.setBool(doneKey, true);
    } catch (_) {}
  }

  /// キャンバスに置く文字を、 [maxWidth] に収まるところで改行して返す。
  /// キャンバスの文字は自動で折り返さないため、 あらかじめ改行を入れておく。
  /// 元からある改行はそのまま残す。
  static String _wrapForCanvas(String text, double maxWidth, double fontSize) {
    final style = TextStyle(fontSize: fontSize);
    final out = StringBuffer();
    var firstPara = true;
    for (final para in text.split('\n')) {
      if (!firstPara) out.write('\n');
      firstPara = false;
      if (para.isEmpty) continue;
      final tp = TextPainter(
        text: TextSpan(text: para, style: style),
        textDirection: TextDirection.ltr,
      )..layout(maxWidth: maxWidth);
      var offset = 0;
      var firstLine = true;
      while (offset < para.length) {
        final b = tp.getLineBoundary(TextPosition(offset: offset));
        var end = b.end;
        // 進まない時の保険 (無限ループ防止)。
        if (end <= offset) end = offset + 1;
        if (end > para.length) end = para.length;
        if (!firstLine) out.write('\n');
        firstLine = false;
        out.write(para.substring(offset, end));
        offset = end;
      }
    }
    return out.toString();
  }

  /// [p] に何も描かれていない (= 白紙) かを判定する。
  /// 用紙の色を塗り替えてよいかの判断に使う (= ユーザー要望)。
  /// 画像・図形・テキスト・線・領域塗りのどれにも当たらなければ白紙とみなす。
  bool _isBlankSpotForBgFill(Offset p) {
    const double tol = 12.0;
    final sh = _sheet;
    for (final im in sh.images) {
      if (im.rect.inflate(2).contains(p)) return false;
    }
    for (final t in sh.texts) {
      // 文字の外接矩形は概算 (1 文字 ≒ 文字サイズ、 高さ ≒ 1.3 倍)。
      final w = math.max(t.size, t.text.length * t.size * 0.6);
      final r = Rect.fromLTWH(t.pos.dx, t.pos.dy, w, t.size * 1.3);
      if (r.inflate(4).contains(p)) return false;
    }
    for (final shape in sh.shapes) {
      if (Rect.fromPoints(shape.a, shape.b).inflate(tol).contains(p)) {
        return false;
      }
    }
    for (final st in sh.strokes) {
      if (st.erase) continue;
      for (final q in st.points) {
        if ((q - p).distance <= tol + st.width / 2) return false;
      }
    }
    // 領域塗りは「塗った位置」 だけを持つので、 その近くなら白紙扱いしない。
    for (final f in sh.fills) {
      if ((Offset(f.x, f.y) - p).distance <= tol * 2) return false;
    }
    return true;
  }

  Future<void> _preloadImages() async {
    bool any = false;
    for (final sh in _sheets) {
      // 用紙の背景画像 (= PDF 取り込み) も先に読み込む。
      final bg = sh.bgImage;
      if (bg != null && bg.isNotEmpty && !_imageCache.containsKey(bg)) {
        final loaded = await _loadUiImage(bg);
        if (loaded != null) {
          _imageCache[bg] = loaded;
          any = true;
        }
      }
      for (final it in sh.images) {
        if (!_imageCache.containsKey(it.path)) {
          final loaded = await _loadUiImage(it.path);
          if (loaded != null) {
            _imageCache[it.path] = loaded;
            any = true;
          }
        }
      }
    }
    if (any && mounted) setState(() {});
  }

  Future<ui.Image?> _loadUiImage(String filePath) async {
    try {
      final bytes = await File(filePath).readAsBytes();
      final c = Completer<ui.Image>();
      ui.decodeImageFromList(bytes, c.complete);
      return await c.future;
    } catch (_) {
      return null;
    }
  }

  @override
  void dispose() {
    if (_paintHost?._paintDropHandler == _onPaintDropFiles) {
      _paintHost?._paintDropHandler = null;
    }
    if (_paintHost?._paintArrowKeyHandler == _hostArrowKey) {
      _paintHost?._paintArrowKeyHandler = null;
    }
    _noteSaveTimer?.cancel();
    final noteController = _noteController;
    if (noteController != null) {
      noteController.removeListener(_scheduleNoteSave);
      // ★ AI (MCP) の書き込みで作り直された時は保存しない (上書き防止)。
      if (widget.provider.mcpContentTick == _mcpTickAtInit) {
        unawaited(_saveNote());
      }
      noteController.dispose();
    }
    _noteFocus.dispose();
    _paintFocus.dispose();
    _textEditCtrl.dispose();
    _textEditFocus.dispose();
    _shapeWidthCtrl.dispose();
    _shapeWidthRepeat?.cancel();
    _pageTabScroll.dispose();
    if (_dirty) {
      _note.selectedPage = _sel;
      _PaintStore.save(widget.pageId, _notes, _noteSel);
    }
    // メモリ節約: デコード済み画像 (ui.Image) を破棄してネイティブメモリを
    //   解放する (= ユーザー要望: 全体のメモリ使用量を抑える)。
    for (final im in _imageCache.values) {
      try {
        im.dispose();
      } catch (_) {}
    }
    _imageCache.clear();
    super.dispose();
  }

  Future<void> _persist() async {
    _dirty = false;
    _note.selectedPage = _sel;
    await _PaintStore.save(widget.pageId, _notes, _noteSel);
  }

  List<Offset> _paintPolygonPoints(_PaintShape shape) {
    final rect = Rect.fromPoints(shape.a, shape.b);
    if (shape.kind == 4) {
      return [
        Offset(rect.center.dx, rect.top),
        rect.bottomLeft,
        rect.bottomRight,
      ];
    }
    return [
      Offset(rect.center.dx, rect.top),
      Offset(rect.right, rect.center.dy),
      Offset(rect.center.dx, rect.bottom),
      Offset(rect.left, rect.center.dy),
    ];
  }

  Path _paintPolygonPath(_PaintShape shape) {
    final points = _paintPolygonPoints(shape);
    return Path()
      ..moveTo(points.first.dx, points.first.dy)
      ..addPolygon(points, true);
  }

  void _selectTool(_PaintTool t) {
    // ツール切替時は編集中テキストを確定。
    if (_textEditPos != null && t != _PaintTool.text) _commitTextEdit();
    setState(() {
      if (_tool == t) {
        _optionsOpen = !_optionsOpen;
      } else {
        _tool = t;
        _optionsOpen = (t == _PaintTool.pen ||
            t == _PaintTool.eraser ||
            t == _PaintTool.shape);
      }
      // 画像ツール以外では画像の選択を解除 (選択枠を消す)。
      if (t != _PaintTool.image) _selImage = -1;
      if (t != _PaintTool.text) _selText = -1;
      if (t != _PaintTool.text) _textToolShapeMoving = false;
      if (t != _PaintTool.eraser) _eraserCursor = null;
      if (t != _PaintTool.select) {
        _clearSelSets();
        _rangeRect = null;
      }
    });
    // 画像ボタンを押した時点でピッカーを開く。従来は空白をもう一度タップ
    // しないと何も起きず、ボタンが無反応に見えていた。
    if (t == _PaintTool.image) unawaited(_pickAndAddImage());
  }

  void _onPanStart(Offset p) {
    if (_tool == _PaintTool.eraser) {
      setState(() {
        _eraserCursor = p;
        _eraserLastPoint = p;
        _eraserTouchedTexts.clear();
        _eraserTouchedShapes.clear();
        _eraserBeforeSnapshot = _makeEraseSnapshot();
        _curStroke = _PaintStroke(
          Colors.transparent.toARGB32(),
          _eraserWidth,
          [p],
          erase: true,
        );
        _eraserChanged = _eraseAlong(p, p);
      });
    } else if (_tool == _PaintTool.pen) {
      setState(() {
        _curStroke = _PaintStroke(
          _color.toARGB32(),
          _penWidth,
          [p],
          // ペンの種類 (通常/チョーク/波線/点線/破線/マーカー) と
          // 濃さ・間隔をストロークに持たせる (= ユーザー要望: 詳細設定)。
          ps: _penStyle,
          op: _penOpacity,
          iv: _penInterval,
          glow: _penGlow,
        );
      });
    } else if (_tool == _PaintTool.shape) {
      setState(() {
        _curShape = _PaintShape(_shapeKind, p, p, _color.toARGB32(), _penWidth,
            _shapeFillColor != null,
            fillColor: _shapeFillColor, glow: _shapeGlow);
      });
    } else if (_tool == _PaintTool.fill) {
      // ── フリーハンドで囲った領域を塗る (= ユーザー要望)。 ドラッグで
      //    輪郭をなぞり、 離すと閉じた形の塗りつぶしになる。 ──
      setState(() {
        _curStroke = _PaintStroke(
          _color.toARGB32(),
          2.0,
          [p],
          ps: 'lassoFill',
          op: _fillAlpha,
        );
      });
    }
  }

  void _onPanUpdate(Offset p) {
    if (_tool == _PaintTool.eraser) {
      setState(() {
        final from = _eraserLastPoint ?? p;
        _eraserCursor = p;
        _eraserLastPoint = p;
        _curStroke?.points.add(p);
        _eraserChanged = _eraseAlong(from, p) || _eraserChanged;
      });
    } else if (_curStroke != null) {
      setState(() {
        var q = p;
        // ── 手振れ補正 (= ユーザー要望): 前回点との指数移動平均で平滑化。
        //    強度が大きいほど新しい点の重みを下げてガタつきを吸収する。 ──
        if (_penStabilize &&
            _tool == _PaintTool.pen &&
            _curStroke!.points.isNotEmpty) {
          final prev = _curStroke!.points.last;
          final k =
              (1.0 - _penStabilizeStrength).clamp(0.15, 1.0).toDouble();
          q = Offset(
              prev.dx + (p.dx - prev.dx) * k, prev.dy + (p.dy - prev.dy) * k);
        }
        _curStroke!.points.add(q);
      });
    } else if (_curShape != null) {
      setState(() => _curShape!.b = _constrainShapeEnd(_curShape!.a, p));
    }
  }

  /// Shift を押しながら線 / 矢印を引いている間は、 終点を **水平 (0/180 度)
  /// または垂直 (90/270 度)** のうちドラッグ方向に近い側へスナップする
  /// (= ユーザー要望: 0/180 度に加えて 90/270 度方向にも引けるように)。
  /// 線 (kind 2) と矢印 (kind 3) 以外は従来どおり自由。
  Offset _constrainShapeEnd(Offset a, Offset p) {
    final kind = _curShape?.kind ?? _shapeKind;
    if (kind != 2 && kind != 3) return p;
    if (!HardwareKeyboard.instance.isShiftPressed) return p;
    final d = p - a;
    // 動きの大きい軸に沿わせる (横優勢 → 水平 / 縦優勢 → 垂直)。
    return d.dx.abs() >= d.dy.abs()
        ? Offset(p.dx, a.dy)
        : Offset(a.dx, p.dy);
  }

  void _onPanEnd() {
    if (_tool == _PaintTool.eraser) {
      final before = _eraserBeforeSnapshot;
      setState(() {
        if (_eraserChanged && before != null) {
          final mask = _curStroke;
          if (mask != null) {
            for (final text in _eraserTouchedTexts) {
              text.erasers.add(_cloneStroke(mask));
            }
            for (final shape in _eraserTouchedShapes) {
              shape.erasers.add(_cloneStroke(mask));
            }
          }
          _pushPaintSnapshotEdit(before);
        }
        _eraserBeforeSnapshot = null;
        _eraserLastPoint = null;
        _eraserChanged = false;
        _eraserTouchedTexts.clear();
        _eraserTouchedShapes.clear();
        _curStroke = null;
      });
      if (_dirty) _persist();
    } else if (_curStroke != null) {
      // ── なげなわ塗りで囲まずにタップしただけの時 ──
      //   何も無い所を押したのなら、 用紙そのものの色を変える
      //   (= ユーザー要望: 白紙を押したら白紙がその色になるように)。
      //   何かの上を押した時は誤操作なので、 これまでどおり何もしない。
      if (_curStroke!.ps == 'lassoFill' && _curStroke!.points.length < 3) {
        final tapped =
            _curStroke!.points.isNotEmpty ? _curStroke!.points.first : null;
        final color = _color.toARGB32();
        setState(() {
          _curStroke = null;
          if (tapped != null && _isBlankSpotForBgFill(tapped)) {
            _redo.clear();
            _bgColorUndo.add(_sheet.bgColor ?? -1);
            _sheet.bgColor = color;
            _sheet.undo.add('bg');
            _dirty = true;
          }
        });
        if (_dirty) _persist();
        return;
      }
      // ── 囲む線が交差していたら、 輪になっている部分だけを残す
      //    (= ユーザー要望: ○ で囲ったところだけが塗られるように)。
      //    書き始め / 書き終わりのはみ出しが塗りに含まれなくなる。 ──
      if (_curStroke!.ps == 'lassoFill') {
        final loop = _closedLoopOf(_curStroke!.points);
        if (loop != null && loop.length >= 4) {
          _curStroke!.points
            ..clear()
            ..addAll(loop);
        }
      }
      setState(() {
        _redo.clear();
        _sheet.strokes.add(_curStroke!..z = _nextPaintZ()..lyr = _activeLayer);
        _sheet.undo.add('stroke');
        _curStroke = null;
        _dirty = true;
      });
      _persist();
    } else if (_curShape != null) {
      setState(() {
        _redo.clear();
        _sheet.shapes.add(_curShape!..z = _nextPaintZ()..lyr = _activeLayer);
        _sheet.undo.add('shape');
        _curShape = null;
        _dirty = true;
        // ── 挿入した直後はその図形を選択状態にする (= ユーザー要望:
        //    挿入後すぐ塗りつぶし等を調整したい)。 選択ツールへ切り替え、
        //    選択バーから塗り / 透明度 / 回転などを変更できる。 ──
        _tool = _PaintTool.select;
        _resetPaintSelectionState();
        _selShapeSet.add(_sheet.shapes.length - 1);
      });
      _persist();
    }
  }

  // Image selection and transform.
  int _imageAt(Offset p) {
    for (int i = _sheet.images.length - 1; i >= 0; i--) {
      if (_sheet.images[i].rect.contains(p)) return i;
    }
    return -1;
  }

  void _onImageTap(Offset p) {
    final idx = _imageAt(p);
    if (idx >= 0) {
      setState(() => _selImage = idx);
    } else {
      // 空きをタップ → 新規画像を追加。
      _pickAndAddImage();
    }
  }

  void _onImagePanStart(Offset p, double fit) {
    final hr = 22 / fit; // 右下ハンドルの判定半径 (論理座標)
    if (_selImage >= 0 && _selImage < _sheet.images.length) {
      final r = _sheet.images[_selImage].rect;
      if ((p - r.bottomRight).distance <= hr) {
        _imgResizing = true;
        _imgDragOrig = r;
        _imgDragStart = p;
        return;
      }
      if (r.contains(p)) {
        _imgResizing = false;
        _imgDragOrig = r;
        _imgDragStart = p;
        return;
      }
    }
    final idx = _imageAt(p);
    if (idx >= 0) {
      setState(() => _selImage = idx);
      _imgResizing = false;
      _imgDragOrig = _sheet.images[idx].rect;
      _imgDragStart = p;
    } else {
      setState(() => _selImage = -1);
      _imgDragOrig = null;
    }
  }

  void _onImagePanUpdate(Offset p) {
    if (_selImage < 0 || _selImage >= _sheet.images.length) return;
    if (_imgDragOrig == null) return;
    final orig = _imgDragOrig!;
    final delta = p - _imgDragStart;
    setState(() {
      if (_imgResizing) {
        final ar = orig.width > 0 ? orig.height / orig.width : 1.0;
        final newW = (orig.width + delta.dx).clamp(24.0, 100000.0);
        _sheet.images[_selImage].rect =
            Rect.fromLTWH(orig.left, orig.top, newW, newW * ar);
      } else {
        _sheet.images[_selImage].rect = orig.shift(delta);
      }
      _dirty = true;
    });
  }

  void _onImagePanEnd() {
    if (_imgDragOrig != null) {
      _imgDragOrig = null;
      _persist();
    }
  }

  // ── 罫線シートでのテキスト行の高さ / 吸着 (= ユーザー要望: 罫線を入れた時は
  //    文字は罫線と罫線の間に 1 行ずつ重ならないようにしか配置できない) ──
  // 罫線あり (ruleSpacing > 0) の時は行ボックスの高さを罫線間隔ぴったりに
  // する (height = spacing / fontSize)。 これで複数行のテキストも 1 行ずつ
  // 罫線の間に収まる。 フォントが罫線間隔より大きい時は 1.0 が下限
  // (= その場合の重なりはサイズ側の問題なので位置では解決しない)。
  double _paintTextHeightFactor(double fontSize) {
    final sp = _sheet.ruleSpacing;
    if (sp > 0 && fontSize > 0) {
      return (sp / fontSize).clamp(1.0, 6.0).toDouble();
    }
    return 1.2;
  }

  /// 罫線ありの時、 テキスト上端を最寄りの罫線に吸着させる (行ボックスが
  /// 罫線間隔と同じ高さなので、 上端 = 罫線 なら行は罫線の間に収まる)。
  Offset _snapTextPosToRule(Offset pos) {
    final sp = _sheet.ruleSpacing;
    if (sp <= 0) return pos;
    double y = (pos.dy / sp).roundToDouble() * sp;
    if (y < 0) y = 0;
    return Offset(pos.dx, y);
  }

  // ── テキスト hit-test (上のものを優先) ──
  TextStyle _paintTextStyle({
    required double fontSize,
    required bool bold,
    required bool italic,
    Color? color,
    // 文字の種類 (= ユーザー要望)。 '' / null は既定フォント。
    String? family,
  }) =>
      TextStyle(
        color: color,
        fontSize: fontSize,
        fontWeight: bold ? FontWeight.bold : FontWeight.w500,
        fontStyle: italic ? FontStyle.italic : FontStyle.normal,
        fontFamily: (family == null || family.isEmpty) ? null : family,
        height: _paintTextHeightFactor(fontSize),
      );

  Size _measurePaintTextValue(String text, double size, bool bold, bool italic,
      [String family = '']) {
    final tp = TextPainter(
      text: TextSpan(
        text: text.isEmpty ? ' ' : text,
        style: _paintTextStyle(
            fontSize: size, bold: bold, italic: italic, family: family),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    return tp.size;
  }

  Size _measureText(_PaintText t) =>
      _measurePaintTextValue(t.text, t.size, t.bold, t.italic, t.font);

  int _textAt(Offset p) {
    for (int i = _sheet.texts.length - 1; i >= 0; i--) {
      final t = _sheet.texts[i];
      final s = _measureText(t);
      // 当たり判定も文字に沿わせる (= ユーザー要望: 枠が大き過ぎる)。
      // 空テキストでも掴めるだけの最低サイズは残す。
      final r = Rect.fromLTWH(t.pos.dx, t.pos.dy, s.width < 16 ? 16 : s.width,
          s.height < 12 ? 12 : s.height);
      if (r.contains(p)) return i;
    }
    return -1;
  }

  /// 点 [p] と線分 [a]-[b] の距離 (= 消しゴムの図形ヒット判定用)。
  double _distToSegment(Offset p, Offset a, Offset b) {
    final ab = b - a;
    final lenSq = ab.dx * ab.dx + ab.dy * ab.dy;
    if (lenSq <= 0.0) return (p - a).distance;
    var t = ((p.dx - a.dx) * ab.dx + (p.dy - a.dy) * ab.dy) / lenSq;
    t = t.clamp(0.0, 1.0);
    final proj = Offset(a.dx + ab.dx * t, a.dy + ab.dy * t);
    return (p - proj).distance;
  }

  bool _pointInEllipse(Offset p, Rect rect) {
    if (rect.width <= 0.001 || rect.height <= 0.001) return false;
    final dx = (p.dx - rect.center.dx) / (rect.width / 2);
    final dy = (p.dy - rect.center.dy) / (rect.height / 2);
    return dx * dx + dy * dy <= 1.0;
  }

  bool _arrowHeadHit(_PaintShape shape, Offset p, double radius) {
    final direction = shape.b - shape.a;
    final length = direction.distance;
    if (length < 1) return (p - shape.b).distance <= radius;
    final ux = direction.dx / length;
    final uy = direction.dy / length;
    final px = -uy;
    final py = ux;
    final head = (shape.width * 2.8).clamp(18.0, 90.0).toDouble();
    final halfBase = head * 0.62;
    final base = Offset(shape.b.dx - ux * head, shape.b.dy - uy * head);
    final left = Offset(base.dx + px * halfBase, base.dy + py * halfBase);
    final right = Offset(base.dx - px * halfBase, base.dy - py * halfBase);
    final headPath = Path()
      ..moveTo(shape.b.dx, shape.b.dy)
      ..lineTo(left.dx, left.dy)
      ..lineTo(right.dx, right.dy)
      ..close();
    return headPath.contains(p) ||
        _distToSegment(p, shape.b, left) <= radius ||
        _distToSegment(p, left, right) <= radius ||
        _distToSegment(p, right, shape.b) <= radius;
  }

  _PaintStroke _cloneStroke(_PaintStroke s) =>
      _PaintStroke(s.color, s.width, List<Offset>.from(s.points),
          erase: s.erase,
          z: s.z,
          g: s.g,
          ps: s.ps,
          op: s.op,
          iv: s.iv,
          glow: s.glow);

  _PaintText _cloneText(_PaintText t) =>
      _PaintText(t.pos, t.text, t.color, t.size,
          bold: t.bold,
          italic: t.italic,
          font: t.font,
          glow: t.glow,
          link: t.link,
          curve: t.curve,
          rot: t.rot,
          z: t.z,
          g: t.g,
          erasers: t.erasers.map(_cloneStroke).toList());

  _PaintShape _cloneShape(_PaintShape s) =>
      _PaintShape(s.kind, s.a, s.b, s.color, s.width, s.fill,
          fillAlpha: s.fillAlpha,
          glow: s.glow,
          rot: s.rot,
          erasers: s.erasers.map(_cloneStroke).toList());

  void _shiftPaintStroke(_PaintStroke stroke, Offset delta) {
    if (delta == Offset.zero) return;
    for (int i = 0; i < stroke.points.length; i++) {
      stroke.points[i] += delta;
    }
  }

  void _shiftPaintErasers(List<_PaintStroke> erasers, Offset delta) {
    if (delta == Offset.zero) return;
    for (final stroke in erasers) {
      for (int i = 0; i < stroke.points.length; i++) {
        stroke.points[i] += delta;
      }
    }
  }

  List<_PaintStroke> _transformPaintErasers(
      List<_PaintStroke> erasers, Rect from, Rect to) {
    const epsilon = 0.001;
    final hasWidth = from.width.abs() > epsilon;
    final hasHeight = from.height.abs() > epsilon;
    final sx = hasWidth ? to.width / from.width : 1.0;
    final sy = hasHeight ? to.height / from.height : 1.0;
    final strokeScale = hasWidth && hasHeight
        ? math.sqrt((sx.abs() * sy.abs()).clamp(0.01, 10000.0))
        : hasWidth
            ? sx.abs()
            : hasHeight
                ? sy.abs()
                : 1.0;
    Offset mapPoint(Offset p) => Offset(
          hasWidth
              ? to.left + (p.dx - from.left) * sx
              : p.dx + (to.center.dx - from.center.dx),
          hasHeight
              ? to.top + (p.dy - from.top) * sy
              : p.dy + (to.center.dy - from.center.dy),
        );
    return erasers
        .map((stroke) => _PaintStroke(
              stroke.color,
              (stroke.width * strokeScale).clamp(1.0, 100000.0).toDouble(),
              stroke.points.map(mapPoint).toList(),
              erase: true,
            ))
        .toList();
  }

  List<_PaintStroke> _transformLineErasers(List<_PaintStroke> erasers,
      Offset oldA, Offset oldB, Offset newA, Offset newB) {
    const epsilon = 0.001;
    final oldVector = oldB - oldA;
    final newVector = newB - newA;
    final oldLength = oldVector.distance;
    final newLength = newVector.distance;
    if (oldLength <= epsilon || newLength <= epsilon) {
      return _transformPaintErasers(
        erasers,
        Rect.fromPoints(oldA, oldB),
        Rect.fromPoints(newA, newB),
      );
    }
    final oldUnit = oldVector / oldLength;
    final newUnit = newVector / newLength;
    final oldNormal = Offset(-oldUnit.dy, oldUnit.dx);
    final newNormal = Offset(-newUnit.dy, newUnit.dx);
    final scale = newLength / oldLength;
    Offset mapPoint(Offset p) {
      final relative = p - oldA;
      final along = relative.dx * oldUnit.dx + relative.dy * oldUnit.dy;
      final across = relative.dx * oldNormal.dx + relative.dy * oldNormal.dy;
      return newA + newUnit * (along * scale) + newNormal * (across * scale);
    }

    return erasers
        .map((stroke) => _PaintStroke(
              stroke.color,
              (stroke.width * scale).clamp(1.0, 100000.0).toDouble(),
              stroke.points.map(mapPoint).toList(),
              erase: true,
            ))
        .toList();
  }

  _PaintEraseSnapshot _makeEraseSnapshot() => _PaintEraseSnapshot(
        strokes: _sheet.strokes.map(_cloneStroke).toList(),
        texts: _sheet.texts.map(_cloneText).toList(),
        shapes: _sheet.shapes.map(_cloneShape).toList(),
        images: _sheet.images.map(_cloneImage).toList(),
      );

  void _pushPaintSnapshotEdit(_PaintEraseSnapshot before) {
    _sheet.eraseUndo.add((
      list: 'edit',
      index: 0,
      item: _PaintEraseEdit(before: before, after: _makeEraseSnapshot()),
    ));
    _sheet.undo.add('erase');
    _redo.clear();
    _dirty = true;
    // 前後スナップショットは手書き点をすべて含むため、無制限に保持すると
    // 大きなノートの移動・消去を繰り返した際にメモリを圧迫する。
    const maxHistory = 100;
    while (_sheet.undo.length > maxHistory) {
      final removedKind = _sheet.undo.removeAt(0);
      if (removedKind == 'erase' && _sheet.eraseUndo.isNotEmpty) {
        _sheet.eraseUndo.removeAt(0);
      }
    }
    if (_redo.length > maxHistory) {
      _redo.removeRange(0, _redo.length - maxHistory);
    }
  }

  void _restoreEraseSnapshot(_PaintEraseSnapshot snapshot) {
    _sheet.strokes
      ..clear()
      ..addAll(snapshot.strokes.map(_cloneStroke));
    _sheet.texts
      ..clear()
      ..addAll(snapshot.texts.map(_cloneText));
    _sheet.shapes
      ..clear()
      ..addAll(snapshot.shapes.map(_cloneShape));
    _sheet.images
      ..clear()
      ..addAll(snapshot.images.map(_cloneImage));
  }

  bool _strokeSegmentNearEraser(
      Offset a, Offset b, Offset eraserA, Offset eraserB, double radius) {
    final mid = Offset((a.dx + b.dx) * 0.5, (a.dy + b.dy) * 0.5);
    return _distToSegment(a, eraserA, eraserB) <= radius ||
        _distToSegment(b, eraserA, eraserB) <= radius ||
        _distToSegment(mid, eraserA, eraserB) <= radius ||
        _distToSegment(eraserA, a, b) <= radius ||
        _distToSegment(eraserB, a, b) <= radius;
  }

  bool _appendStrokeAfterErase(
      _PaintStroke stroke, Offset from, Offset to, List<_PaintStroke> out) {
    if (stroke.erase) {
      out.add(stroke);
      return false;
    }
    if (stroke.points.isEmpty) return false;
    final radius = _eraserWidth / 2 + stroke.width / 2;
    if (stroke.points.length == 1) {
      if (_distToSegment(stroke.points.first, from, to) <= radius) {
        return true;
      }
      out.add(stroke);
      return false;
    }

    var changed = false;
    var chunk = <Offset>[];
    final chunks = <List<Offset>>[];
    void flushChunk() {
      if (chunk.isEmpty) return;
      chunks.add(chunk);
      chunk = <Offset>[];
    }

    for (int i = 0; i < stroke.points.length; i++) {
      final p = stroke.points[i];
      var hit = _distToSegment(p, from, to) <= radius;
      if (!hit && i > 0) {
        hit =
            _strokeSegmentNearEraser(stroke.points[i - 1], p, from, to, radius);
      }
      if (!hit && i + 1 < stroke.points.length) {
        hit =
            _strokeSegmentNearEraser(p, stroke.points[i + 1], from, to, radius);
      }
      if (hit) {
        changed = true;
        flushChunk();
      } else {
        chunk.add(p);
      }
    }
    flushChunk();
    if (!changed) {
      out.add(stroke);
      return false;
    }
    for (final points in chunks) {
      // ── 分割後もペンの種類/濃さ/間隔/レイヤー/グループを引き継ぐ ──
      // (= ユーザー報告: チョークやスクイグルに消しゴムが当たると、 当たって
      // いない箇所まで普通の線に戻ってしまう。 旧: 分割セグメントを色と太さ
      // だけの新規ストロークで作っていたため、 スタイル情報が落ちていた)。
      out.add(_PaintStroke(stroke.color, stroke.width, points,
          z: stroke.z,
          g: stroke.g,
          ps: stroke.ps,
          op: stroke.op,
          iv: stroke.iv));
    }
    return true;
  }

  bool _eraseStrokesAlong(Offset from, Offset to) {
    var changed = false;
    final next = <_PaintStroke>[];
    for (final stroke in _sheet.strokes) {
      // ── 選んでいるレイヤー以外は消さない (= ユーザー要望: 上に配置された
      //    レイヤーに対してのみ消しゴムを適用) ──
      if (stroke.lyr != _activeLayer) {
        next.add(stroke);
        continue;
      }
      changed = _appendStrokeAfterErase(stroke, from, to, next) || changed;
    }
    if (!changed) return false;
    _sheet.strokes
      ..clear()
      ..addAll(next);
    return true;
  }

  /// 消しゴムが [p] を通過した時、部分消去マスクの対象になる
  /// テキスト/図形を記録する。要素自体はリストから削除しない。
  bool _eraseObjectsAtPoint(Offset p) {
    final double r = _eraserWidth / 2;
    bool touched = false;
    // テキスト: 消しゴム円がテキスト矩形に重なれば、このジェスチャーの
    // マスク対象にする。実際に消えるのは文字の描画ピクセルだけ。
    for (int i = _sheet.texts.length - 1; i >= 0; i--) {
      final t = _sheet.texts[i];
      // 選んでいるレイヤー以外は対象にしない (= ユーザー要望)。
      if (t.lyr != _activeLayer) continue;
      final s = _measureText(t);
      final rect = Rect.fromLTWH(t.pos.dx, t.pos.dy,
          s.width < 24 ? 24 : s.width, s.height < 18 ? 18 : s.height);
      if (rect.inflate(r).contains(p)) {
        _eraserTouchedTexts.add(t);
        touched = true;
      }
    }
    // 図形: 描画形状そのものと消しゴム円の重なりで対象を記録する。
    for (int i = _sheet.shapes.length - 1; i >= 0; i--) {
      final sh = _sheet.shapes[i];
      // 選んでいるレイヤー以外は対象にしない (= ユーザー要望)。
      if (sh.lyr != _activeLayer) continue;
      final tol = r + sh.width;
      bool hit;
      if (sh.kind == 2) {
        hit = _distToSegment(p, sh.a, sh.b) <= tol;
      } else if (sh.kind == 3) {
        hit = _distToSegment(p, sh.a, sh.b) <= tol || _arrowHeadHit(sh, p, r);
      } else {
        final rect = Rect.fromPoints(sh.a, sh.b);
        if (sh.kind == 1) {
          final outer = rect.inflate(sh.fill ? r : tol);
          if (!_pointInEllipse(p, outer)) {
            hit = false;
          } else if (sh.fill) {
            hit = true;
          } else {
            final inner = rect.deflate(tol);
            hit = inner.width <= 0 ||
                inner.height <= 0 ||
                !_pointInEllipse(p, inner);
          }
        } else if (sh.fill) {
          hit = rect.inflate(r).contains(p);
        } else {
          hit = rect.inflate(tol).contains(p) && !rect.deflate(tol).contains(p);
        }
      }
      if (hit) {
        _eraserTouchedShapes.add(sh);
        touched = true;
      }
    }
    return touched;
  }

  bool _eraseAlong(Offset from, Offset to) {
    var changed = _eraseStrokesAlong(from, to);
    final distance = (to - from).distance;
    final steps =
        math.max(1, (distance / math.max(4.0, _eraserWidth / 2)).ceil());
    for (int i = 0; i <= steps; i++) {
      final t = steps == 0 ? 0.0 : i / steps;
      final p = Offset.lerp(from, to, t) ?? to;
      changed = _eraseObjectsAtPoint(p) || changed;
    }
    if (changed) {
      _dirty = true;
    }
    return changed;
  }

  /// 塗りつぶしツールのタップ (= ユーザー要望: 図形の重なりのうち塗る領域を
  /// 個別で指定できるように)。
  /// - タップ位置の領域 (= その点を含む面図形の交差 − 含まない図形) を塗る。
  /// - 既にその領域を塗った塗りが有れば削除 (トグル)。
  void _onFillTap(Offset p) {
    // 既存の塗りのトグル判定: 同じ領域 (= 既存の塗り点と同じ領域に p が入る)。
    for (int i = _sheet.fills.length - 1; i >= 0; i--) {
      final f = _sheet.fills[i];
      final region = _paintRegionAt(_sheet.shapes, Offset(f.x, f.y));
      if (region != null && region.contains(p)) {
        setState(() {
          _sheet.fills.removeAt(i);
          _dirty = true;
        });
        _persist();
        return;
      }
    }
    final region = _paintRegionAt(_sheet.shapes, p);
    if (region == null) {
      // ── フリーハンドで描いた閉領域もタップで塗れるように (= ユーザー
      //    要望)。 手書きストロークを閉じたパスとみなして内側判定する。 ──
      if (_fillFreehandRegionAt(p)) return;
      // ── 何も無い所を押したら用紙そのものの色を変える (= ユーザー要望) ──
      //   白紙でも塗れる状態なのに「面のある図形を選んでください」 と出るのは
      //   おかしいので、 案内を出さずにそのまま紙の色を変える。
      if (_isBlankSpotForBgFill(p)) {
        setState(() {
          _redo.clear();
          _bgColorUndo.add(_sheet.bgColor ?? -1);
          _sheet.bgColor = _color.toARGB32();
          _sheet.undo.add('bg');
          _dirty = true;
        });
        _persist();
        return;
      }
      // 図形やインクの上を押した時だけ、 塗れない理由を出す。
      _snack(widget.provider.t('paint.fillNoRegion'));
      return;
    }
    setState(() {
      _redo.clear();
      _sheet.fills.add(_PaintFill(p.dx, p.dy, _color.toARGB32(), _fillAlpha));
      _sheet.undo.add('fill');
      _dirty = true;
    });
    _persist();
  }

  /// 手書き線の自己交差を探し、 閉じた 「輪」 の輪郭点列を返す
  /// (= ユーザー要望: ○ で囲ったところだけが塗られるように)。
  ///
  /// 線が自分と交差していれば、 交点 → 交点 の区間がその輪。 輪から伸びた
  /// 尻尾は含まれないので、 始点と終点を単純に結んだ時のように塗りが
  /// 尾を引かない。 交差が無ければ null。
  ///
  /// [contains] を渡すとその点を含む輪のうち最小のものを返す (= 大きい輪の
  /// 内側の小さい輪を塗りたいはずなので)。 渡さない場合は面積最大の輪。
  List<Offset>? _closedLoopOf(List<Offset> src, {Offset? contains}) {
    if (src.length < 8) return null;
    // 点が多いと総当たりが重くなるので、 間引いた線で判定する
    // (塗り形状の差は目視では分からない程度)。
    final List<Offset> pts;
    if (src.length > 700) {
      final stride = (src.length / 700).ceil();
      pts = <Offset>[
        for (int i = 0; i < src.length; i += stride) src[i],
        src.last,
      ];
    } else {
      pts = src;
    }

    // 2 線分の交点 (無ければ null)。 端点の共有や平行は交差とみなさない。
    Offset? cross(Offset a1, Offset a2, Offset b1, Offset b2) {
      final r = a2 - a1;
      final sVec = b2 - b1;
      final denom = r.dx * sVec.dy - r.dy * sVec.dx;
      if (denom.abs() < 1e-9) return null;
      final qp = b1 - a1;
      final t = (qp.dx * sVec.dy - qp.dy * sVec.dx) / denom;
      final u = (qp.dx * r.dy - qp.dy * r.dx) / denom;
      if (t <= 0.0001 || t >= 0.9999 || u <= 0.0001 || u >= 0.9999) return null;
      return Offset(a1.dx + r.dx * t, a1.dy + r.dy * t);
    }

    List<Offset>? best;
    var bestArea = contains == null ? -1.0 : double.infinity;
    for (int i = 0; i + 1 < pts.length; i++) {
      final a1 = pts[i];
      final a2 = pts[i + 1];
      final aMinX = math.min(a1.dx, a2.dx);
      final aMaxX = math.max(a1.dx, a2.dx);
      final aMinY = math.min(a1.dy, a2.dy);
      final aMaxY = math.max(a1.dy, a2.dy);
      for (int j = i + 2; j + 1 < pts.length; j++) {
        final b1 = pts[j];
        final b2 = pts[j + 1];
        // 外接矩形が重ならない組は交差し得ないので早く弾く。
        if (math.max(b1.dx, b2.dx) < aMinX ||
            math.min(b1.dx, b2.dx) > aMaxX ||
            math.max(b1.dy, b2.dy) < aMinY ||
            math.min(b1.dy, b2.dy) > aMaxY) {
          continue;
        }
        final x = cross(a1, a2, b1, b2);
        if (x == null) continue;
        final loop = <Offset>[x, ...pts.sublist(i + 1, j + 1), x];
        if (loop.length < 4) continue;
        final path = Path()..fillType = PathFillType.evenOdd;
        path.moveTo(loop.first.dx, loop.first.dy);
        for (int k = 1; k < loop.length; k++) {
          path.lineTo(loop[k].dx, loop[k].dy);
        }
        path.close();
        if (contains != null && !path.contains(contains)) continue;
        final b = path.getBounds();
        final area = b.width * b.height;
        if (contains == null ? area > bestArea : area < bestArea) {
          best = loop;
          bestArea = area;
        }
      }
    }
    return best;
  }

  /// タップ位置 [p] を囲う手書きストローク (始点と終点を結んで閉領域と
  /// みなす) を前面から探し、 あればその輪郭のなげなわ塗りを追加する
  /// (= ユーザー要望: フリーハンドで描いた閉領域も塗りつぶせるように)。
  /// 自己交差した線 (輪の下で線が交差している等) も evenOdd 判定で
  /// 内側なら塗れる。 塗れたら true。
  bool _fillFreehandRegionAt(Offset p) {
    final candidates = <_PaintStroke>[
      for (final s in _sheet.strokes)
        if (!s.erase && s.ps != 'lassoFill' && s.points.length >= 8) s,
    ]..sort((a, b) => b.z.compareTo(a.z));
    for (final s in candidates) {
      final b = _paintStrokeBounds(s);
      if (b == null || b.width < 12 || b.height < 12) continue;
      if (!b.contains(p)) continue;
      // ── 実際に「輪」 になっている部分だけを塗る (= ユーザー要望: ○ で
      //    囲ったところだけが塗られてほしい) ──
      // 線が自分自身と交差していれば、 その交点から交点までが閉じた輪。
      // 交差が無い時だけ、 従来どおり始点と終点を結んで閉じる。
      final loop = _closedLoopOf(s.points, contains: p) ??
          List<Offset>.from(s.points);
      final path = Path()..fillType = PathFillType.evenOdd;
      path.moveTo(loop.first.dx, loop.first.dy);
      for (int i = 1; i < loop.length; i++) {
        path.lineTo(loop[i].dx, loop[i].dy);
      }
      path.close();
      if (!path.contains(p)) continue;
      setState(() {
        _redo.clear();
        _sheet.strokes.add(_PaintStroke(
          _color.toARGB32(),
          2.0,
          loop,
          ps: 'lassoFill',
          op: _fillAlpha,
        )..z = _nextPaintZ()..lyr = _activeLayer);
        _sheet.undo.add('stroke');
        _dirty = true;
      });
      _persist();
      return true;
    }
    return false;
  }

  // タップ: 既存テキストなら枠とボタンを表示、 空きなら新規をその位置でインライン入力
  //   (= ユーザー要望: Word の様に挿入位置で直接入力)。
  void _onTextTap(Offset p) {
    if (_textEditPos != null) {
      _commitTextEdit(selectAfterCommit: false);
      return;
    }
    final idx = _textAt(p);
    if (idx >= 0) {
      setState(() {
        _clearSelSets();
        _selText = idx;
      });
    } else {
      setState(() {
        _clearSelSets();
        _selText = -1;
      });
      _startTextEdit(p);
    }
  }

  /// セル内で開始した新規テキストの、 所属先の表グループ id (0 = 表外)。
  /// commit 時にテキストへ引き継がれ、 表と一緒に動くようになる。
  int _textEditTableGroup = 0;

  void _startTextEdit(Offset pos, {int existingIndex = -1}) {
    // 罫線シートでは最寄りの罫線に吸着 (= ユーザー要望: 罫線の間に 1 行ずつ)。
    pos = _snapTextPosToRule(pos);
    // ── 表のセル内をタップした新規テキストは、 セルの左上へ吸着させ、
    //    表のグループに参加させる (= ユーザー要望: セルに書き込めて、
    //    表とグループ化されて一緒に動くように)。 ──
    _textEditTableGroup = 0;
    if (existingIndex < 0) {
      final cell = _tableCellAt(pos);
      if (cell != null) {
        pos = cell.pos;
        _textEditTableGroup = cell.gid;
      }
    }
    setState(() {
      _selText = -1;
      _textEditIndex = existingIndex;
      _textEditPos = pos;
      _lockedTextEditFit = _lastPaintFit;
      if (existingIndex >= 0 && existingIndex < _sheet.texts.length) {
        final t = _sheet.texts[existingIndex];
        _textEditCtrl.text = t.text;
        _color = Color(t.color);
        _textSize = t.size;
        _textBold = t.bold;
        _textItalic = t.italic;
        _textFont = t.font;
        _textGlow = t.glow;
        _textCurve = t.curve;
        // 文字色の濃さ (= ユーザー要望) は色のアルファとして保持されている。
        _textAlpha = Color(t.color).a.clamp(0.2, 1.0).toDouble();
      } else {
        _textEditCtrl.text = '';
      }
    });
    _textEditCtrl.selection =
        TextSelection.collapsed(offset: _textEditCtrl.text.length);
    _textEditFocus.requestFocus();
  }

  /// 本文が URL (http/https で始まる 1 トークン) なら、 その URL を返す
  /// (= ユーザー要望: URL 貼り付け後のハイパーリンク作成)。 それ以外は null。
  String? _autoDetectPaintLink(String text) {
    final t = text.trim();
    if (t.isEmpty || t.contains('\n')) return null;
    if (!(t.startsWith('http://') || t.startsWith('https://'))) return null;
    if (t.contains(' ')) return null;
    return Uri.tryParse(t) == null ? null : t;
  }

  /// テキストのリンクをブラウザで開く (= ユーザー要望)。
  Future<void> _openPaintLink(String url) async {
    if (url.isEmpty) return;
    try {
      await launchUrl(Uri.parse(url), mode: LaunchMode.externalApplication);
    } catch (_) {}
  }

  /// 選択中テキスト (1 個) にリンク URL を設定 / 解除するダイアログ
  /// (= ユーザー要望: 文字をリンクと連携させる)。
  Future<void> _editPaintTextLink() async {
    if (_selTextSet.length != 1) return;
    final idx = _selTextSet.first;
    if (idx < 0 || idx >= _sheet.texts.length) return;
    final t = _sheet.texts[idx];
    final ctrl = TextEditingController(text: t.link);
    final provider = widget.provider;
    final result = await _showNearDialog<String>(
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('paint.linkTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white, fontSize: 13),
          decoration: InputDecoration(
            hintText: 'https://…',
            hintStyle: const TextStyle(color: Colors.white38),
            enabledBorder: const UnderlineInputBorder(
                borderSide: BorderSide(color: Colors.white24)),
            focusedBorder: const UnderlineInputBorder(
                borderSide: BorderSide(color: Color(0xFFEC407A))),
            helperText: provider.t('paint.linkHint'),
            helperStyle:
                const TextStyle(color: Colors.white38, fontSize: 11),
          ),
          onSubmitted: (v) => Navigator.of(ctx).pop(v),
        ),
        actions: [
          if (t.link.isNotEmpty)
            TextButton(
              onPressed: () => Navigator.of(ctx).pop(''),
              child: Text(provider.t('paint.linkRemove'),
                  style: const TextStyle(color: Color(0xFFE57373))),
            ),
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(null),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(ctrl.text),
            child: const Text('OK',
                style: TextStyle(color: Color(0xFFEC407A))),
          ),
        ],
      ),
    );
    if (result == null) return; // キャンセル
    setState(() {
      t.link = result.trim();
      _dirty = true;
    });
    _persist();
  }

  /// インライン入力を閉じた直後は、破棄予定の TextField が primary focus を
  /// 保持するフレームがある。次フレームでキャンバスへ戻し、確定直後に選択中の
  /// テキストボックスへ Ctrl/Cmd+C・V が確実に届くようにする。
  void _restorePaintFocusAfterTextEdit() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || _textEditPos != null) return;
      _paintFocus.requestFocus();
    });
  }

  void _commitTextEdit({bool selectAfterCommit = true}) {
    final rawPos = _textEditPos;
    if (rawPos == null) return;
    // 罫線シートでは確定位置も罫線に吸着 (掴みバーでの微調整後も揃える)。
    // (再代入せず新しい final に入れる = setState クロージャ内でも
    //  non-null promotion が効くように)
    final pos = _snapTextPosToRule(rawPos);
    final txt = _textEditCtrl.text;
    int nextSelText = -1;
    setState(() {
      if (_textEditIndex >= 0 && _textEditIndex < _sheet.texts.length) {
        final old = _sheet.texts[_textEditIndex];
        final shiftedErasers = old.erasers.map(_cloneStroke).toList();
        _shiftPaintErasers(shiftedErasers, pos - old.pos);
        _sheet.texts[_textEditIndex] = _PaintText(
            // 文字色の濃さ (= ユーザー要望) はアルファとして色に埋め込む。
            pos, txt, _color.withValues(alpha: _textAlpha).toARGB32(),
            _textSize,
            bold: _textBold,
            italic: _textItalic,
            font: _textFont,
            glow: _textGlow,
            curve: _textCurve,
            // 回転は編集前の値を引き継ぐ (回転は選択バーで変更する)。
            rot: old.rot,
            // レイヤー順とグループ所属も編集前の値を引き継ぐ
            // (旧実装は編集すると z/g が失われて表グループから外れていた)。
            z: old.z,
            g: old.g,
            // 既存のリンクは編集後も保持する。 本文が URL になった時は
            // リンクを追従させる (= ユーザー要望: 文字とリンクの連携)。
            link: _autoDetectPaintLink(txt) ?? old.link,
            erasers: shiftedErasers);
        nextSelText = _textEditIndex;
      } else if (txt.trim().isNotEmpty) {
        // 新規は本文がある時だけ要素を作る (= ユーザー要望: テキストが空の
        // 時はテキストボックスを作成しない。 旧: 空でも位置と書式を持つ
        // 空要素を作っていた)。
        _redo.clear();
        _sheet.texts.add(_PaintText(
            pos, txt, _color.withValues(alpha: _textAlpha).toARGB32(),
            _textSize,
            bold: _textBold,
            italic: _textItalic,
            font: _textFont,
            glow: _textGlow,
            curve: _textCurve,
            // セル内で書いた文字は表と同じグループに入れて一緒に動かす
            // (= ユーザー要望)。
            g: _textEditTableGroup,
            // URL を貼り付け / 入力したら自動でハイパーリンク化する
            // (= ユーザー要望: URL 貼り付け後のハイパーリンク作成)。
            link: _autoDetectPaintLink(txt) ?? '')
          ..z = _nextPaintZ()..lyr = _activeLayer);
        _sheet.undo.add('text');
        nextSelText = _sheet.texts.length - 1;
      }
      _textEditTableGroup = 0;
      _textEditPos = null;
      _textEditIndex = -1;
      _textEditCtrl.clear();
      _lockedTextEditFit = null;
      _selText = selectAfterCommit ? nextSelText : -1;
      if (!selectAfterCommit) _clearSelSets();
      _dirty = true;
    });
    _persist();
    _restorePaintFocusAfterTextEdit();
  }

  void _deleteTextEdit() {
    final hadExisting =
        _textEditIndex >= 0 && _textEditIndex < _sheet.texts.length;
    setState(() {
      if (hadExisting) {
        _sheet.texts.removeAt(_textEditIndex);
        final i = _sheet.undo.lastIndexOf('text');
        if (i >= 0) _sheet.undo.removeAt(i);
        _redo.clear();
        _dirty = true;
      }
      _textEditPos = null;
      _textEditIndex = -1;
      _textEditCtrl.clear();
      _lockedTextEditFit = null;
      _selText = -1;
      _textEditTableGroup = 0;
    });
    if (hadExisting) _persist();
    _restorePaintFocusAfterTextEdit();
  }

  // ドラッグ: 既存テキストをつかんで自由に移動 (= ユーザー要望)。
  // テキストに当たらなかった場合は図形を調べ、テキストツールのままでも
  // 既存図形を掴んで移動できるようにする。空き場所のタップは引き続き
  // _onTextTap が新規テキスト入力として扱う。
  void _onTextPanStart(Offset p, double fit) {
    if (_textEditPos != null) {
      // 入力欄の外でドラッグを始めた場合は、入力中の文字を失わず確定してから
      // 背後の既存要素を操作する。TextField 自身のドラッグはここへ届かない。
      _commitTextEdit(selectAfterCommit: false);
    }
    _textToolShapeMoving = false;

    // テキストモードでも、直前に掴んだ図形のリサイズハンドルを操作できる
    // ようにする。更新・Undo・消し跡の座標変換・保存は選択モードの既存経路へ
    // 委譲するので、四角/楕円の8方向と線/矢印の両端を同じ挙動で変形できる。
    final resizeHit = _shapeResizeHit(p, fit);
    if (resizeHit != null) {
      _textDragOrig = null;
      _textToolShapeMoving = true;
      _onSelectPanStart(p, fit);
      return;
    }

    final idx = _textAt(p);
    if (idx >= 0) {
      setState(() {
        _clearSelSets();
        _selText = idx;
      });
      _textDragOrig = _sheet.texts[idx].pos;
      _textDragStart = p;
      return;
    }

    // 上に重なった図形を優先する。塗りなし図形は線の近くだけがヒットするため、
    // 図形の内側へ文字を置く従来の操作も妨げない。
    int shapeIndex = -1;
    for (int i = _sheet.shapes.length - 1; i >= 0; i--) {
      if (_paintShapeHit(_sheet.shapes[i], p, fit)) {
        shapeIndex = i;
        break;
      }
    }
    if (shapeIndex >= 0) {
      setState(() {
        _selText = -1;
        _clearSelSets();
        _selShapeSet.add(shapeIndex);
      });
      _textDragOrig = null;
      _textToolShapeMoving = true;
      _selMoving = true;
      _selRanging = false;
      _selLastP = p;
      _selectionMoveBeforeSnapshot = _makeEraseSnapshot();
      _selectionMoveChanged = false;
      return;
    }

    setState(() {
      _selText = -1;
      _clearSelSets();
    });
    _textDragOrig = null;
  }

  void _onTextPanUpdate(Offset p) {
    if (_textToolShapeMoving) {
      _onSelectPanUpdate(p);
      return;
    }
    if (_selText < 0 || _selText >= _sheet.texts.length) return;
    if (_textDragOrig == null) return;
    setState(() {
      final text = _sheet.texts[_selText];
      // 罫線シートでは移動中も罫線に吸着 (= ユーザー要望: 罫線の間に
      // 1 行ずつしか配置できない)。 x は自由、 y だけ吸着する。
      final next =
          _snapTextPosToRule(_textDragOrig! + (p - _textDragStart));
      _shiftPaintErasers(text.erasers, next - text.pos);
      text.pos = next;
      _dirty = true;
    });
  }

  void _onTextPanEnd() {
    if (_textToolShapeMoving) {
      _onSelectPanEnd();
      _textToolShapeMoving = false;
      return;
    }
    if (_textDragOrig != null) {
      _textDragOrig = null;
      _persist();
    }
  }

  void _deleteSelText() {
    if (_selText < 0 || _selText >= _sheet.texts.length) return;
    setState(() {
      _sheet.texts.removeAt(_selText);
      final i = _sheet.undo.lastIndexOf('text');
      if (i >= 0) _sheet.undo.removeAt(i);
      _selText = -1;
      _redo.clear();
      _dirty = true;
    });
    _persist();
  }

  Future<void> _pickAndAddImage() async {
    try {
      final picked = await FilePicker.platform.pickFiles(
        dialogTitle: widget.provider.t('pick.image'),
        type: FileType.image,
        allowMultiple: false,
        withData: !_isDesktop,
      );
      if (picked == null || picked.files.isEmpty) {
        if (mounted) _snack(widget.provider.t('paint.imagePickCancelled'));
        return;
      }
      final selected = picked.files.first;
      final srcPath = selected.path;
      final bytes = selected.bytes;
      if ((srcPath == null || srcPath.isEmpty) &&
          (bytes == null || bytes.isEmpty)) {
        if (mounted) _snack(widget.provider.t('paint.imagePickFailed'));
        return;
      }
      final dir = await getApplicationDocumentsDirectory();
      if (!await dir.exists()) await dir.create(recursive: true);
      final sourceName =
          selected.name.isNotEmpty ? selected.name : (srcPath ?? '');
      final dot = sourceName.lastIndexOf('.');
      final ext = dot >= 0 ? sourceName.substring(dot) : '.png';
      final dst =
          '${dir.path}/paint_img_${DateTime.now().microsecondsSinceEpoch}$ext';
      if (srcPath != null &&
          srcPath.isNotEmpty &&
          await File(srcPath).exists()) {
        await File(srcPath).copy(dst);
      } else if (bytes != null && bytes.isNotEmpty) {
        await File(dst).writeAsBytes(bytes, flush: true);
      } else {
        if (mounted) _snack(widget.provider.t('paint.imagePickFailed'));
        return;
      }
      final im = await _loadUiImage(dst);
      if (im == null || !mounted) {
        if (mounted) _snack(widget.provider.t('paint.imagePickFailed'));
        return;
      }
      _imageCache[dst] = im;
      final cs = _csize;
      double w = im.width.toDouble();
      double h = im.height.toDouble();
      final maxW = cs.w * 0.6;
      if (w > maxW) {
        h = h * maxW / w;
        w = maxW;
      }
      final rect = Rect.fromLTWH((cs.w - w) / 2, (cs.h - h) / 2, w, h);
      setState(() {
        _redo.clear();
        _sheet.images.add(_PaintImageItem(dst, rect)..z = _nextPaintZ()..lyr = _activeLayer);
        _sheet.undo.add('image');
        _selImage = _sheet.images.length - 1; // 追加直後は選択状態に
        _dirty = true;
      });
      _persist();
    } catch (_) {
      if (mounted) _snack(widget.provider.t('paint.imagePickFailed'));
    }
  }

  /// テキストボックス + 書式 (太字/斜体/サイズ) で入力する (= ユーザー要望:
  /// テキストボックスが出てリッチに入力)。 複数行対応。 色は現在のパレット色。

  void _undo() {
    if (_sheet.undo.isEmpty) return;
    setState(() {
      final kind = _sheet.undo.removeLast();
      // 消しゴムで消したテキスト/図形を元の位置へ復元 (= ユーザー要望)。
      if (kind == 'erase') {
        if (_sheet.eraseUndo.isNotEmpty) {
          final e = _sheet.eraseUndo.removeLast();
          if (e.list == 'edit') {
            final edit = e.item as _PaintEraseEdit;
            _restoreEraseSnapshot(edit.before);
          } else if (e.list == 'text') {
            final idx = e.index.clamp(0, _sheet.texts.length);
            _sheet.texts.insert(idx, e.item as _PaintText);
          } else {
            final idx = e.index.clamp(0, _sheet.shapes.length);
            _sheet.shapes.insert(idx, e.item as _PaintShape);
          }
          _redo.add((kind: 'erase', item: e));
        }
        _clearSelSets();
        _selImage = -1;
        _selText = -1;
        _rangeRect = null;
        _dirty = true;
        return;
      }
      // 用紙の色を 1 つ前に戻す (= ユーザー要望の背景塗り)。
      //   switch の default は線を消すので、 必ずここで処理する。
      if (kind == 'bg') {
        final prev = _bgColorUndo.isNotEmpty ? _bgColorUndo.removeLast() : -1;
        _redo.add((kind: 'bg', item: _sheet.bgColor ?? -1));
        _sheet.bgColor = prev < 0 ? null : prev;
        _clearSelSets();
        _selImage = -1;
        _selText = -1;
        _rangeRect = null;
        _dirty = true;
        return;
      }
      Object? item;
      switch (kind) {
        case 'text':
          if (_sheet.texts.isNotEmpty) item = _sheet.texts.removeLast();
          break;
        case 'shape':
          if (_sheet.shapes.isNotEmpty) item = _sheet.shapes.removeLast();
          break;
        case 'image':
          if (_sheet.images.isNotEmpty) item = _sheet.images.removeLast();
          break;
        case 'fill':
          if (_sheet.fills.isNotEmpty) item = _sheet.fills.removeLast();
          break;
        default:
          if (_sheet.strokes.isNotEmpty) item = _sheet.strokes.removeLast();
      }
      if (item != null) _redo.add((kind: kind, item: item));
      _clearSelSets();
      _selImage = -1;
      _selText = -1;
      _rangeRect = null;
      _dirty = true;
    });
    _persist();
  }

  /// 進める (やり直し) (= ユーザー要望: 元に戻すの他に進めるボタン)。
  void _redoAction() {
    if (_redo.isEmpty) return;
    setState(() {
      final e = _redo.removeLast();
      // 消しゴムでの削除をやり直す (= 同じ実体を再びリストから除去)。
      if (e.kind == 'erase') {
        final rec = e.item as ({String list, int index, Object item});
        if (rec.list == 'edit') {
          final edit = rec.item as _PaintEraseEdit;
          _restoreEraseSnapshot(edit.after);
        } else if (rec.list == 'text') {
          _sheet.texts.remove(rec.item as _PaintText);
        } else {
          _sheet.shapes.remove(rec.item as _PaintShape);
        }
        _sheet.eraseUndo.add(rec);
        _sheet.undo.add('erase');
        _clearSelSets();
        _selImage = -1;
        _selText = -1;
        _rangeRect = null;
        _dirty = true;
        return;
      }
      if (e.kind == 'bg') {
        final next = e.item as int;
        _bgColorUndo.add(_sheet.bgColor ?? -1);
        _sheet.bgColor = next < 0 ? null : next;
        _sheet.undo.add('bg');
        _clearSelSets();
        _selImage = -1;
        _selText = -1;
        _rangeRect = null;
        _dirty = true;
        return;
      }
      switch (e.kind) {
        case 'text':
          _sheet.texts.add(e.item as _PaintText);
          break;
        case 'shape':
          _sheet.shapes.add(e.item as _PaintShape);
          break;
        case 'image':
          _sheet.images.add(e.item as _PaintImageItem);
          break;
        case 'fill':
          _sheet.fills.add(e.item as _PaintFill);
          break;
        default:
          _sheet.strokes.add(e.item as _PaintStroke);
      }
      _sheet.undo.add(e.kind);
      _clearSelSets();
      _selImage = -1;
      _selText = -1;
      _rangeRect = null;
      _dirty = true;
    });
    _persist();
  }

  Future<void> _clearAll() async {
    final sh = _sheet;
    if (sh.strokes.isEmpty &&
        sh.texts.isEmpty &&
        sh.shapes.isEmpty &&
        sh.images.isEmpty &&
        sh.fills.isEmpty) {
      return;
    }
    final ok = await _showNearDialog<bool>(
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(widget.provider.t('paint.clearAll'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Text(widget.provider.t('paint.clearConfirm'),
            style: const TextStyle(color: Colors.white70)),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx, false),
              child: Text(widget.provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFE57373),
                foregroundColor: Colors.black),
            onPressed: () => Navigator.pop(dctx, true),
            child: Text(widget.provider.t('btn.erase')),
          ),
        ],
      ),
    );
    if (ok != true) return;
    setState(() {
      sh.strokes.clear();
      sh.texts.clear();
      sh.shapes.clear();
      sh.images.clear();
      sh.fills.clear();
      sh.undo.clear();
      sh.eraseUndo.clear();
      _redo.clear();
      _resetPaintSelectionState();
      _curStroke = null;
      _curShape = null;
      _dirty = true;
    });
    _persist();
  }

  /// 既定名テンプレート ('ページ {n}' 等) の「次の名前」 を返す
  /// (= ユーザー要望: 途中のページを削除した後に追加しても同じ番号の
  /// ページが作られないように)。 既存名の最大番号 + 1 を使い、 それでも
  /// 衝突する場合は番号を進めて必ずユニークにする。
  String _uniqueDefaultName(String template, Iterable<String> existing) {
    final ex = existing.map((e) => e.trim()).toSet();
    final re = RegExp('^' +
        RegExp.escape(template)
            .replaceFirst(RegExp(r'\\\{n\\\}'), r'(\d+)') +
        r'$');
    var n = 0;
    for (final name in ex) {
      final m = re.firstMatch(name);
      if (m != null) {
        final v = int.tryParse(m.group(1) ?? '') ?? 0;
        if (v > n) n = v;
      }
    }
    n += 1;
    var cand = template.replaceFirst('{n}', '$n');
    while (ex.contains(cand)) {
      n++;
      cand = template.replaceFirst('{n}', '$n');
    }
    return cand;
  }

  void _addPage() {
    // 編集中の文字があれば先に確定 (新ページへ紛れ込むのを防ぐ)。
    if (_textEditPos != null) _commitTextEdit();
    setState(() {
      _sheets.add(_PaintSheet(
        // ページ名は数字の連番に戻した (= ユーザー要望 2026-07-31:
        // アルファベットではなくやはり数字に)。 最大番号 + 1 で重複しない。
        name: _uniqueDefaultName(widget.provider.t('paint.defaultPageName'),
            _sheets.map((s) => s.name)),
        sizeId: _sheet.sizeId,
      ));
      _sel = _sheets.length - 1;
      _resetPaintSelectionState();
      _dirty = true;
    });
    _persist();
  }

  /// ページタブの右クリックメニュー (= ユーザー要望: ページ名を右クリック
  /// して削除・新規ページ・新規ノートの追加ができるように)。
  Future<void> _showPageTabContextMenu(int index, Offset globalPos) async {
    final p = widget.provider;
    final overlay =
        Overlay.of(context).context.findRenderObject() as RenderBox?;
    if (overlay == null) return;
    final v = await showMenu<String>(
      context: context,
      color: const Color(0xFF1E1E32),
      position: RelativeRect.fromRect(
        globalPos & const Size(1, 1),
        Offset.zero & overlay.size,
      ),
      items: [
        PopupMenuItem(
          value: 'rename',
          height: 36,
          child: Row(children: [
            const Icon(Icons.edit_outlined, size: 15, color: Colors.white70),
            const SizedBox(width: 8),
            Text(p.t('paint.pageName'),
                style: const TextStyle(color: Colors.white, fontSize: 12.5)),
          ]),
        ),
        PopupMenuItem(
          value: 'addPage',
          height: 36,
          child: Row(children: [
            const Icon(Icons.add_box_outlined,
                size: 15, color: Color(0xFF7FD8A0)),
            const SizedBox(width: 8),
            Text(p.t('paint.addPage'),
                style: const TextStyle(color: Colors.white, fontSize: 12.5)),
          ]),
        ),
        PopupMenuItem(
          value: 'addNote',
          height: 36,
          child: Row(children: [
            const Icon(Icons.note_add_outlined,
                size: 15, color: Color(0xFF4FC3F7)),
            const SizedBox(width: 8),
            Text(p.t('paint.addNote'),
                style: const TextStyle(color: Colors.white, fontSize: 12.5)),
          ]),
        ),
        const PopupMenuDivider(),
        PopupMenuItem(
          value: 'delete',
          height: 36,
          enabled: _sheets.length > 1,
          child: Row(children: [
            Icon(Icons.delete_outline_rounded,
                size: 15,
                color: _sheets.length > 1
                    ? const Color(0xFFE57373)
                    : Colors.white24),
            const SizedBox(width: 8),
            Text(p.t('paint.deletePage'),
                style: TextStyle(
                    color: _sheets.length > 1
                        ? const Color(0xFFE57373)
                        : Colors.white24,
                    fontSize: 12.5)),
          ]),
        ),
      ],
    );
    if (!mounted || v == null) return;
    switch (v) {
      case 'rename':
        _selectPage(index);
        _renamePage();
        break;
      case 'addPage':
        _addPage();
        break;
      case 'addNote':
        _addNote();
        break;
      case 'delete':
        await _deletePageAt(index);
        break;
    }
  }

  // ── ホイール / トラックパッドのスクロールでページをめくる (= ユーザー要望:
  //    普通のノートのようにスクロールしたら次のページへ) ──
  double _pageScrollAccum = 0.0;
  DateTime _lastPageFlipAt = DateTime.fromMillisecondsSinceEpoch(0);

  void _onPaintCanvasScroll(PointerSignalEvent event) {
    if (event is! PointerScrollEvent) return;
    // 文字編集中は誤ってページが変わらないようにする。
    if (_textEditPos != null) return;
    if (_sheets.length <= 1) return;
    final now = DateTime.now();
    // 1 回のスクロールで一気にめくり過ぎないようクールダウンを挟む。
    if (now.difference(_lastPageFlipAt) < const Duration(milliseconds: 320)) {
      return;
    }
    _pageScrollAccum += event.scrollDelta.dy;
    const threshold = 80.0;
    if (_pageScrollAccum.abs() < threshold) return;
    final dir = _pageScrollAccum > 0 ? 1 : -1;
    _pageScrollAccum = 0.0;
    final next = _sel + dir;
    if (next < 0 || next >= _sheets.length) return;
    _lastPageFlipAt = now;
    _selectPage(next);
  }

  void _selectPage(int i) {
    if (i < 0 || i >= _sheets.length || i == _sel) return;
    // 切り替え先のページが文書モードかを読み直す (= ユーザー要望)。
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) unawaited(_loadDocModeForSheet());
    });
    // ── 編集中の文字は「元のページに」 確定してから切り替える ──
    // (= ユーザー要望: ページやノートを切り替えた時に書いた内容が
    //    切り替わらず重複してしまうことがある → 確定先がズレないように)。
    if (_textEditPos != null) _commitTextEdit(selectAfterCommit: false);
    setState(() {
      _sel = i;
      _note.selectedPage = i;
      _redo.clear();
      _resetPaintSelectionState();
      _curStroke = null;
      _curShape = null;
      // 描画途中の消しゴム状態も破棄 (前ページの内容へ影響しないように)。
      _eraserBeforeSnapshot = null;
      _eraserChanged = false;
      _eraserTouchedTexts.clear();
      _eraserTouchedShapes.clear();
    });
    _persist();
  }

  /// ページタブのドラッグ開始ラッパ (= ユーザー要望: ページの並べ替え)。
  /// デスクトップは掴んで即ドラッグ、 モバイルは長押しでドラッグ
  /// (即ドラッグだとタブ列の横スクロールと競合するため)。
  Widget _pageTabDragWrapper(
      {required Key key, required int index, required Widget child}) {
    if (_isDesktop) {
      return ReorderableDragStartListener(key: key, index: index, child: child);
    }
    return ReorderableDelayedDragStartListener(
        key: key, index: index, child: child);
  }

  /// ページの並べ替え (= ユーザー要望: ページの順番を自由に入れ替え)。
  /// `_sheets` は `_note.pages` と同一リストなので、 並べ替えは
  /// そのままノートへ反映・保存される。
  void _reorderPages(int oldIndex, int newIndex) {
    if (oldIndex < 0 || oldIndex >= _sheets.length) return;
    if (newIndex > oldIndex) newIndex--;
    newIndex = newIndex.clamp(0, _sheets.length - 1);
    if (oldIndex == newIndex) return;
    final selectedSheet =
        (_sel >= 0 && _sel < _sheets.length) ? _sheets[_sel] : null;
    setState(() {
      final moved = _sheets.removeAt(oldIndex);
      _sheets.insert(newIndex, moved);
      // 選択中ページを追従させる (実体で探し直す)。
      if (selectedSheet != null) {
        final idx = _sheets.indexOf(selectedSheet);
        if (idx >= 0) _sel = idx;
      }
      _note.selectedPage = _sel;
      _dirty = true;
    });
    _persist();
  }

  /// ページ一覧ダイアログ (= ユーザー要望: ページが多くなったら一覧を
  /// スワイプ (スクロール) して選べるように)。 タップで切替、 ドラッグで
  /// 並べ替え、 ゴミ箱で削除。 下部に番号詰め設定のトグル付き。
