                child: Text(widget.provider.t('paint.reorderNotesHint'),
                    style:
                        const TextStyle(color: Colors.white38, fontSize: 11)),
              ),
              const SizedBox(height: 6),
              Expanded(
                child: ReorderableListView(
                  buildDefaultDragHandles: true,
                  proxyDecorator: (child, index, animation) => Material(
                    color: Colors.transparent,
                    child: child,
                  ),
                  onReorder: (oldIndex, newIndex) {
                    _reorderPages(oldIndex, newIndex);
                    setDlg(() {});
                  },
                  children: [
                    for (int i = 0; i < _sheets.length; i++)
                      ListTile(
                        key: ObjectKey(_sheets[i]),
                        dense: true,
                        onTap: () {
                          _selectPage(i);
                          setDlg(() {});
                        },
                        leading: Icon(
                            i == _sel
                                ? Icons.check_rounded
                                : Icons.description_outlined,
                            size: 18,
                            color: i == _sel
                                ? const Color(0xFFEC407A)
                                : Colors.white54),
                        title: Text(_sheets[i].name,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: Colors.white, fontSize: 13)),
                        trailing: _sheets.length > 1
                            ? IconButton(
                                padding: EdgeInsets.zero,
                                constraints: const BoxConstraints(
                                    minWidth: 30, minHeight: 30),
                                tooltip:
                                    widget.provider.t('paint.deletePage'),
                                icon: const Icon(
                                    Icons.delete_outline_rounded,
                                    size: 17,
                                    color: Color(0xFFE57373)),
                                onPressed: () async {
                                  await _deletePageAt(i);
                                  setDlg(() {});
                                },
                              )
                            : null,
                      ),
                  ],
                ),
              ),
              const Divider(color: Colors.white12, height: 12),
              // ── 番号詰め設定 (= ユーザー要望: 2 回目以降は設定から選べる) ──
              Row(children: [
                Expanded(
                  child: Text(widget.provider.t('paint.renumberSetting'),
                      style: const TextStyle(
                          color: Colors.white70, fontSize: 12)),
                ),
                Switch(
                  value: _renumberOnDelete ?? false,
                  activeColor: const Color(0xFFEC407A),
                  onChanged: (v) {
                    setState(() => _renumberOnDelete = v);
                    _persistRenumberOnDelete();
                    setDlg(() {});
                  },
                ),
              ]),
            ]),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
