  void _showExportError(String stderrText) {
    if (!mounted) return;
    final tail = stderrText.length > 1500
        ? stderrText.substring(stderrText.length - 1500)
        : stderrText;
    showDialog<void>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(widget.provider.t('video.exportFailed'),
            style: TextStyle(color: Color(0xFFFF6B6B), fontSize: 15)),
        content: SizedBox(
          width: 460,
          child: SingleChildScrollView(
            child: SelectableText(tail.isEmpty ? '不明なエラー' : tail,
                style: const TextStyle(
                    color: Colors.white60, fontSize: 11, height: 1.3)),
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(widget.provider.t('btn.close'))),
        ],
      ),
    );
  }

