  Widget _dlgRow(String label, TextEditingController c) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 5),
      child: TextField(
        controller: c,
        style: const TextStyle(color: Colors.white),
        decoration: InputDecoration(
          labelText: label,
          labelStyle: const TextStyle(color: Colors.white54, fontSize: 12),
          isDense: true,
        ),
      ),
    );
  }

  static String _fmt(int ms) {
    if (ms < 0) ms = 0;
    final totalSec = ms ~/ 1000;
    final m = totalSec ~/ 60;
    final s = (totalSec % 60).toString().padLeft(2, '0');
    final cs = (ms % 1000) ~/ 100;
    return '$m:$s.$cs';
  }

  static int? _parseTime(String s) {
    s = s.trim();
    if (s.isEmpty) return null;
    try {
      final parts = s.split(':');
      double sec;
      if (parts.length == 1) {
        sec = double.parse(parts[0]);
      } else if (parts.length == 2) {
        sec = int.parse(parts[0]) * 60 + double.parse(parts[1]);
      } else {
        sec = int.parse(parts[0]) * 3600 +
            int.parse(parts[1]) * 60 +
            double.parse(parts[2]);
      }
      final ms = (sec * 1000).round();
      return ms < 0 ? 0 : ms;
    } catch (_) {
      return null;
    }
  }

