  @override
  Widget build(BuildContext context) {
    if (!_loaded) {
      return const Center(
          child: CircularProgressIndicator(color: Color(0xFFFF7043)));
    }
    // Focus: Backspace/Delete でアイテム削除。 Listener: 操作時にフォーカス確保。
    return Focus(
      focusNode: _focusNode,
      autofocus: true,
      onKeyEvent: _onKey,
      child: Listener(
        onPointerDown: (_) {
          if (!_focusNode.hasFocus) _focusNode.requestFocus();
        },
        child: Stack(fit: StackFit.expand, children: [
          Container(
            color: const Color(0xFF12121C),
            // ── モバイルで編集パネルを開いている間は、下部にパネル分の場所を
            //    空けてプレビュー/タイムラインを上へ寄せる (= ユーザー要望:
            //    編集項目で要素やプレビューが隠れないよう、 重ねず並べる)。 ──
            child: Padding(
              padding: EdgeInsets.only(
                  // パネル高 + キーボード高のぶん上へ詰める (= パネルを
                  // キーボードの上へ持ち上げても内容が隠れないように)。
                  bottom: (_veNarrow && _panelItemId != null)
                      ? _dockPanelHeight() +
                          MediaQuery.viewInsetsOf(context).bottom
                      : 0),
              child: Column(children: [
                // ── プレビューを最上部に置いて広く取る (= ユーザー要望: プレビュー
                //    画面が小さ過ぎる)。 上部の大きなタイトルバーは廃止。 ──
                _buildPreview(),
                _buildPreviewResizeHandle(),
                _buildTransport(),
                // ── 選択中要素の名前バーは廃止 (= ユーザー要望: 要素を選択
                //    した時に「Text」 等の項目名が 1 行出てタイムラインが
                //    動いてしまって邪魔) ──
                // ここにあった `_buildSelBar()` の機能は、
                //   分割 → ツールストリップ / 右クリックメニュー
                //   編集 → 要素クリックでサイドパネル
                //   削除 → 右クリックメニュー / Delete キー
                // にすべて存在するので、 行そのものを出さない。
                // ── 操作ボタンはプレビューとタイムラインの間の左端へ (= ユーザー要望) ──
                // モバイルで編集パネルを開いている間は隠して、 タイムラインの
                // 表示領域を広げる (= ユーザー要望: パネルで再生位置が隠れて
                // 見えない。 パネル中はメディア追加等のボタンは使わない)。
                if (!(_veNarrow && _panelItemId != null)) ...[
                  _buildToolStrip(),
                  const Divider(color: Colors.white12, height: 1),
                ],
                Expanded(child: _buildTimeline()),
              ]),
            ),
          ),
          // ── 要素編集パネル。 モバイルは下部ドッキング (重ねない)、
          //    デスクトップは右横オーバーレイ (= ユーザー要望)。 ──
          if (_panelItemId != null) _buildItemSidePanel(),
          // ── 処理中バナー (= ユーザー要望: 何％か表示) ──
          if (_processing)
            Positioned(
              top: 48,
              left: 0,
              right: 0,
              child: Center(
                child: Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
                  decoration: BoxDecoration(
                    color: const Color(0xFF24243A),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(color: const Color(0xFFFF7043)),
                  ),
                  child: Row(mainAxisSize: MainAxisSize.min, children: [
                    const SizedBox(
                      width: 16,
                      height: 16,
                      child: CircularProgressIndicator(
                          strokeWidth: 2, color: Color(0xFFFF7043)),
                    ),
                    const SizedBox(width: 10),
                    Text(_processMsg,
                        style:
                            const TextStyle(color: Colors.white, fontSize: 13)),
                  ]),
                ),
              ),
            ),
        ]),
      ),
    );
  }

  // ── プロジェクトファイルの保存 / 読み込み (= ユーザー要望: 動画の
