          );
        }

        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            const Icon(Icons.save_rounded, color: Color(0xFF66BB6A), size: 20),
            const SizedBox(width: 8),
            Text(p.t('ve.projectTitle'),
                style: const TextStyle(color: Colors.white, fontSize: 15)),
          ]),
          content: Column(mainAxisSize: MainAxisSize.min, children: [
            tile('embed', Icons.folder_zip_rounded, const Color(0xFF66BB6A),
                p.t('ve.projectSaveEmbed'), p.t('ve.projectSaveEmbedDesc')),
            const Divider(color: Colors.white12, height: 1),
            tile('ref', Icons.link_rounded, const Color(0xFF4FC3F7),
                p.t('ve.projectSaveRef'), p.t('ve.projectSaveRefDesc')),
            const Divider(color: Colors.white12, height: 1),
            tile('load', Icons.folder_open_rounded, const Color(0xFFFFB74D),
                p.t('ve.projectLoad'), p.t('ve.projectLoadDesc')),
          ]),
          actions: [
            TextButton(
