    }
  }

  /// プロジェクトを書き出す。 [embedMedia] = true なら動画/画像も同梱した
  /// ZIP、 false なら参照パスだけの JSON (= ユーザー要望: 選択できるように)。
  Future<void> _saveProjectFile({required bool embedMedia}) async {
    final p = widget.provider;
    if (_items.isEmpty) {
      _exportInfo(p.t('ve.projectEmpty'));
      return;
    }
    try {
      Directory? dir;
      try {
        dir = await getDownloadsDirectory();
      } catch (_) {}
      dir ??= await getApplicationDocumentsDirectory();
      final ts = DateTime.now().millisecondsSinceEpoch;
      String outPath;
      if (!embedMedia) {
        // ── 参照パスのみ (JSON)。 軽いが、 元ファイルを移動すると
        //    リンク切れになる (説明はダイアログに記載)。 ──
        outPath =
            '${dir.path}${Platform.pathSeparator}HisatorNotebook_project_$ts.json';
        final json = jsonEncode({
          'type': 'histornote_video_project',
          'v': 1,
          'media': 'reference',
          'items': _items.map((e) => e.toJson()).toList(),
        });
        await File(outPath).writeAsString(json, flush: true);
      } else {
        // ── メディア同梱 (ZIP)。 project.json + media/ に実ファイルを収め、
        //    items の path は ZIP 内の相対パスに置き換える。 ──
        setState(() {
          _processing = true;
          _processMsg = p.t('ve.projectSaving');
        });
        final archive = Archive();
        final mediaMap = <String, String>{}; // 元パス → ZIP 内相対パス
        int mi = 0;
        final itemsJson = <Map<String, dynamic>>[];
        for (final it in _items) {
          final j = it.toJson();
          if ((it.kind == _VeKind.video || it.kind == _VeKind.image) &&
              it.path.isNotEmpty) {
            var rel = mediaMap[it.path];
            if (rel == null) {
              final f = File(it.path);
              if (await f.exists()) {
                final base = it.path.replaceAll('\\', '/').split('/').last;
                rel = 'media/${mi}_$base';
                mi++;
                final bytes = await f.readAsBytes();
                archive.addFile(ArchiveFile(rel, bytes.length, bytes));
                mediaMap[it.path] = rel;
              }
            }
            if (rel != null) j['p'] = rel;
          }
          itemsJson.add(j);
        }
        final projBytes = utf8.encode(jsonEncode({
          'type': 'histornote_video_project',
          'v': 1,
          'media': 'embedded',
          'items': itemsJson,
        }));
        archive
            .addFile(ArchiveFile('project.json', projBytes.length, projBytes));
        final zipBytes = ZipEncoder().encode(archive);
        if (zipBytes == null) throw 'zip encode failed';
        outPath =
            '${dir.path}${Platform.pathSeparator}HisatorNotebook_project_$ts.zip';
        await File(outPath).writeAsBytes(zipBytes, flush: true);
      }
      if (!mounted) return;
      _exportInfo('${p.t('ve.projectSaved')}\n$outPath');
    } catch (e) {
      if (mounted) _exportInfo('${p.t('ve.projectSaveFailed')}: $e');
    } finally {
      if (mounted) {
        setState(() {
          _processing = false;
          _processMsg = '';
        });
      }
    }
  }

  /// プロジェクトファイル (.json / .zip) を読み込んで現在の内容を置き換える。
  Future<void> _loadProjectFile() async {
    final p = widget.provider;
    try {
      final res = await FilePicker.platform.pickFiles(
        dialogTitle: p.t('ve.projectLoad'),
        type: FileType.custom,
        allowedExtensions: ['json', 'zip'],
      );
      final path = res?.files.single.path;
      if (path == null) return;
      List<_VeItem>? items;
      if (path.toLowerCase().endsWith('.zip')) {
        setState(() {
          _processing = true;
          _processMsg = p.t('ve.projectLoading');
        });
        final bytes = await File(path).readAsBytes();
        final archive = ZipDecoder().decodeBytes(bytes);
        final appDir = await getApplicationDocumentsDirectory();
        final destRoot = Directory(
            '${appDir.path}/video_projects/${DateTime.now().millisecondsSinceEpoch}');
        await destRoot.create(recursive: true);
        String? projStr;
        final extracted = <String, String>{}; // ZIP 内相対パス → 展開先絶対パス
        for (final f in archive) {
          if (!f.isFile) continue;
          final name = f.name.replaceAll('\\', '/');
          // ZIP パストラバーサル対策 (= '..' を含むエントリは展開しない)。
          if (name.split('/').contains('..')) continue;
          if (name == 'project.json') {
            projStr = utf8.decode(f.content as List<int>);
          } else {
            final outFile = File('${destRoot.path}/$name');
            await outFile.create(recursive: true);
            await outFile.writeAsBytes(f.content as List<int>, flush: true);
            extracted[name] = outFile.path;
          }
        }
        if (projStr == null) throw 'project.json not found';
        final dec = jsonDecode(projStr);
        if (dec is! Map || dec['items'] is! List) throw 'invalid format';
        items = (dec['items'] as List)
            .whereType<Map>()
            .map((m) => _VeItem.fromJson(m))
            .toList();
        // 同梱メディアの相対パス → 展開先の絶対パスへ差し替え。
        for (final it in items) {
          final rel = it.path.replaceAll('\\', '/');
          if (rel.isNotEmpty && extracted.containsKey(rel)) {
            it.path = extracted[rel]!;
          }
        }
      } else {
        final dec = jsonDecode(await File(path).readAsString());
        if (dec is! Map || dec['items'] is! List) throw 'invalid format';
        items = (dec['items'] as List)
            .whereType<Map>()
            .map((m) => _VeItem.fromJson(m))
            .toList();
      }
      if (!mounted) return;
      _vePushUndo();
      setState(() {
        _items = items!;
        _selId = null;
        _panelItemId = null;
      });
      _persist();
      await _seekTo(0);
      if (mounted) _exportInfo(p.t('ve.projectLoaded'));
    } catch (e) {
      if (mounted) _exportInfo('${p.t('ve.projectLoadFailed')}: $e');
    } finally {
      if (mounted) {
        setState(() {
          _processing = false;
          _processMsg = '';
        });
      }
    }
  }

