  /// モバイル (狭い画面) 判定。 要素編集パネルを画面下部にドッキングするか、
  /// デスクトップのように右横オーバーレイにするかの分岐に使う。
  bool get _veNarrow => MediaQuery.sizeOf(context).shortestSide < 600;

  /// 下部ドッキング編集パネルの高さ (クランプ済み)。 上端グリップで可変。
  /// キーボードが出ている間は「キーボードを除いた高さ」 を基準にクランプする
  /// (= ユーザー要望: モバイルの編集項目が編集しづらい。 パネルごとキーボードの
  /// 上へ持ち上げるため、 持ち上げた状態で画面からあふれない高さにする)。
  double _dockPanelHeight() {
    final kb = MediaQuery.viewInsetsOf(context).bottom;
    final avail =
        (MediaQuery.sizeOf(context).height - kb).clamp(240.0, 100000.0);
    final maxH = avail * (kb > 0 ? 0.5 : 0.6);
    return _veDockPanelH.clamp(160.0, maxH.toDouble()).toDouble();
  }

  Widget _buildPreview() {
    // 画面が低いときにプレビューが伸び過ぎてタイムライン等を押し出さないよう、
    //   利用可能な高さ内にクランプする (= オーバーフロー防止)。
    // モバイルで編集パネルを開いている間は、その分だけ上限を下げてプレビューと
    //   タイムラインが下部パネルに隠れないようにする (= ユーザー要望)。
    final reserve =
        (_veNarrow && _panelItemId != null) ? _dockPanelHeight() : 0.0;
    final maxH = (MediaQuery.of(context).size.height - 240 - reserve)
        .clamp(120.0, 4000.0)
        .toDouble();
    final h = _previewHeight.clamp(120.0, maxH).toDouble();
    return Container(
      height: h,
      width: double.infinity,
      color: Colors.black,
      child: Center(
        child: AspectRatio(
          aspectRatio: _veAspect,
          child: LayoutBuilder(
              builder: (ctx, cns) => _buildStage(cns.maxWidth, cns.maxHeight)),
        ),
      ),
    );
  }

  /// プレビュー領域とタイムラインの境界。 縦ドラッグでプレビュー高さを変える
  /// (= ユーザー要望: ビュー領域を境界ドラッグでリサイズ)。
  Widget _buildPreviewResizeHandle() {
    return MouseRegion(
      cursor: SystemMouseCursors.resizeUpDown,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onVerticalDragUpdate: (d) {
          final maxH =
              (MediaQuery.of(context).size.height - 260).clamp(140.0, 2000.0);
          setState(() {
            _previewHeight = (_previewHeight + d.delta.dy).clamp(120.0, maxH);
          });
        },
        child: Container(
          height: 12,
          color: const Color(0xFF1A1A26),
          alignment: Alignment.center,
          child: Container(
            width: 44,
            height: 4,
            decoration: BoxDecoration(
              color: Colors.white30,
              borderRadius: BorderRadius.circular(2),
            ),
          ),
        ),
      ),
    );
  }

  // ── テキスト色のよく使う色 (= ユーザー要望: 色を変えやすく) ──
  static const List<int> _veTextPalette = [
    0xFFFFFFFF,
    0xFF000000,
    0xFFFF5252,
    0xFFFF7043,
    0xFFFFD54F,
    0xFF66BB6A,
    0xFF4FC3F7,
    0xFF42A5F5,
    0xFFBA68C8,
    0xFFEC407A,
    0xFF8D6E63,
    0xFF26A69A,
  ];

  void _pushRecentColor(int c) {
    _recentTextColors.remove(c);
    _recentTextColors.insert(0, c);
    while (_recentTextColors.length > 6) {
      _recentTextColors.removeLast();
    }
  }

  /// テキスト色のスウォッチ 1 個。 タップで [it] の色を即適用 (= 即プレビュー反映)。
  Widget _veColorSwatch(int c, _VeItem it) {
    final sel = (it.colorArgb & 0xFFFFFF) == (c & 0xFFFFFF);
    return GestureDetector(
      onTap: () {
        setState(() {
          it.colorArgb = c;
          _pushRecentColor(c);
        });
        _persist();
      },
      child: Container(
        width: 26,
        height: 26,
        decoration: BoxDecoration(
          color: Color(c),
          shape: BoxShape.circle,
          border: Border.all(
              color: sel ? const Color(0xFFFF7043) : Colors.white24,
              width: sel ? 2.5 : 1),
        ),
      ),
    );
  }

  /// R/G/B スライダーの自由色ピッカー (= ユーザー要望: 任意の色も選べるように)。
  /// 戻り値は ARGB int。 キャンセル時は null。
  Future<int?> _showVeColorPicker(int initialArgb) async {
    int r = (initialArgb >> 16) & 0xFF;
    int g = (initialArgb >> 8) & 0xFF;
    int b = initialArgb & 0xFF;
    return showDialog<int>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        final cur = 0xFF000000 | (r << 16) | (g << 8) | b;
        Widget chan(String name, int val, Color c, ValueChanged<double> on) =>
            Row(children: [
              SizedBox(
                  width: 18,
                  child: Text(name,
                      style: TextStyle(
                          color: c,
                          fontSize: 12,
                          fontWeight: FontWeight.bold))),
              Expanded(
                child: Slider(
                  value: val.toDouble(),
                  min: 0,
                  max: 255,
                  activeColor: c,
                  onChanged: on,
                ),
              ),
              SizedBox(
                  width: 30,
                  child: Text('$val',
                      style: const TextStyle(
                          color: Colors.white54, fontSize: 12))),
            ]);
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Text(widget.provider.t('ve.textColor'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
          content: SizedBox(
            width: 300,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              Container(
                height: 44,
                decoration: BoxDecoration(
                    color: Color(cur),
                    borderRadius: BorderRadius.circular(6),
                    border: Border.all(color: Colors.white24)),
              ),
              const SizedBox(height: 10),
              chan('R', r, const Color(0xFFFF5252),
                  (v) => setD(() => r = v.round())),
              chan('G', g, const Color(0xFF66BB6A),
                  (v) => setD(() => g = v.round())),
              chan('B', b, const Color(0xFF4FC3F7),
                  (v) => setD(() => b = v.round())),
            ]),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(dctx),
                child: Text(widget.provider.t('btn.cancel'),
                    style: const TextStyle(color: Colors.white54))),
            ElevatedButton(
                onPressed: () => Navigator.pop(dctx, cur),
                child: Text(widget.provider.t('btn.apply'))),
          ],
        );
      }),
    );
  }

  Widget _panelTimeField(
      String label, TextEditingController controller, _VeItem it) {
    return TextField(
      controller: controller,
      keyboardType: TextInputType.datetime,
      textInputAction: TextInputAction.done,
      onSubmitted: (_) => _commitPanelDetails(it),
      style: const TextStyle(color: Colors.white, fontSize: 12),
      decoration: InputDecoration(
        labelText: label,
        labelStyle: const TextStyle(color: Colors.white54, fontSize: 11),
        isDense: true,
        filled: true,
        fillColor: const Color(0xFF15151F),
        contentPadding: const EdgeInsets.symmetric(horizontal: 9, vertical: 10),
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(6),
          borderSide: BorderSide.none,
        ),
      ),
    );
  }

  /// 要素の設定を出す横サイドパネル (= ユーザー要望: 動画要素クリックで中央
  /// ダイアログではなく、すべての詳細プロパティを設定するメニュー)。
  Widget _buildItemSidePanel() {
    final idx = _items.indexWhere((e) => e.id == _panelItemId);
    if (idx < 0) return const SizedBox.shrink();
    final it = _items[idx];
    final isVideo = it.kind == _VeKind.video;
    final screenSize = MediaQuery.sizeOf(context);
    final useMobileSheet = screenSize.shortestSide < 600;

    Widget buildPanel(ScrollController? scrollController,
        {required bool compact}) {
      return Material(
        color: const Color(0xFF1E1E32),
        elevation: 16,
        child: SafeArea(
          top: !compact,
          child:
              Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            if (compact)
              Center(
                child: GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onVerticalDragUpdate: (details) {
                    // 上端グリップの縦ドラッグで下部ドッキングパネルの高さを
                    // 変える。 上へドラッグ (delta.dy<0) で高くする。 Column 側の
                    // 余白も同じ高さで連動するのでプレビュー/タイムラインと
                    // 重ならない (= ユーザー要望)。
                    final maxH = MediaQuery.sizeOf(context).height * 0.6;
                    setState(() {
                      _veDockPanelH = (_veDockPanelH - details.delta.dy)
                          .clamp(160.0, maxH)
                          .toDouble();
                    });
                  },
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(24, 7, 24, 5),
                    child: Container(
                      width: 42,
                      height: 4,
                      decoration: BoxDecoration(
                        color: Colors.white24,
                        borderRadius: BorderRadius.circular(4),
                      ),
                    ),
                  ),
                ),
              ),
            // ヘッダー
            Padding(
              padding: EdgeInsets.fromLTRB(
                  compact ? 10 : 14, compact ? 5 : 10, 4, 6),
              child: Row(children: [
                Icon(_kindIcon(it.kind), color: _layerColor(it.kind), size: 18),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                      isVideo
                          ? widget.provider.t('ve.videoClip')
