      widget.provider.t(id.isEmpty ? 've.fx.none' : 've.fx.$id');

  /// フェード時間 (ms) 用のスライダー行 (0〜3 秒) (= ユーザー要望:
  /// トランジション)。 0 = なし。
  Widget _panelMsSliderRow({
    required IconData icon,
    required String label,
    required int valueMs,
    required ValueChanged<int> onChanged,
    required VoidCallback onDone,
  }) {
    return Row(children: [
      Icon(icon, color: const Color(0xFFFF7043), size: 16),
      const SizedBox(width: 6),
      Text(label,
          style: const TextStyle(color: Colors.white54, fontSize: 12)),
      Expanded(
        child: Slider(
          value: valueMs.clamp(0, 3000).toDouble(),
          min: 0,
          max: 3000,
          divisions: 30,
          activeColor: const Color(0xFFFF7043),
          onChanged: (v) => onChanged(v.round()),
          onChangeEnd: (_) => onDone(),
        ),
      ),
      SizedBox(
        width: 38,
        child: Text(
            valueMs <= 0 ? '—' : '${(valueMs / 1000).toStringAsFixed(1)}s',
            textAlign: TextAlign.right,
            style: const TextStyle(color: Colors.white54, fontSize: 11)),
      ),
    ]);
  }

  // 選択できるフォント (= ユーザー要望)。 id は実フォント名 (主に Windows
  //   システムフォント)。 プレビューに反映。 書き出し時は対応するフォント
  //   ファイルが見つかればそれを drawtext に使う (_fontFileForFamily)。
  static const List<({String id, String label})> _veFonts = [
    (id: '', label: 'Default (Noto Sans JP / System)'),
    (id: 'Yu Gothic', label: '游ゴシック'),
    (id: 'Meiryo', label: 'メイリオ'),
    (id: 'MS PGothic', label: 'MS Pゴシック'),
    (id: 'Yu Mincho', label: '游明朝'),
    (id: 'MS PMincho', label: 'MS P明朝'),
  ];

  /// フォント名 → drawtext 用フォントファイルパス (見つからなければ null)。
  String? _fontFileForFamily(String family) {
    if (family.isEmpty) return null;
    if (!Platform.isWindows) return null;
    const map = {
      'Yu Gothic': r'C:\Windows\Fonts\YuGothM.ttc',
      'Meiryo': r'C:\Windows\Fonts\meiryo.ttc',
      'MS PGothic': r'C:\Windows\Fonts\msgothic.ttc',
      'Yu Mincho': r'C:\Windows\Fonts\YuMin.ttf',
      'MS PMincho': r'C:\Windows\Fonts\msmincho.ttc',
    };
    final p = map[family];
    if (p != null && File(p).existsSync()) return p;
    return null;
  }

  Widget _buildTransport() {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 2),
      child: Row(children: [
        IconButton(
          icon: Icon(_playing ? Icons.pause_rounded : Icons.play_arrow_rounded,
              color: Colors.white),
          onPressed: _togglePlay,
          visualDensity: VisualDensity.compact,
        ),
        Text(_fmt(_playheadMs),
            style: const TextStyle(color: Colors.white70, fontSize: 12)),
        Expanded(
          child: SliderTheme(
            data: SliderTheme.of(context).copyWith(
              trackHeight: 3,
              activeTrackColor: const Color(0xFFFF7043),
              thumbColor: const Color(0xFFFF7043),
              inactiveTrackColor: Colors.white24,
            ),
            child: Slider(
              value: _playheadMs
                  .clamp(0, math.max(_totalMs, _timelineVisualMaxMs))
                  .toDouble(),
              min: 0,
              max: math.max(_totalMs, _timelineVisualMaxMs).toDouble(),
              onChanged: (v) {
                _stop();
                _seekTo(v.toInt());
              },
            ),
          ),
        ),
        Text(_fmt(_totalMs),
            style: const TextStyle(color: Colors.white38, fontSize: 12)),
        // ── 再生倍率セレクタ (= ユーザー要望: 2倍速など) ──
        PopupMenuButton<double>(
          tooltip: widget.provider.t('ve.playbackRate'),
          color: const Color(0xFF252535),
          onSelected: _setRate,
          itemBuilder: (_) => [
            for (final r in _kRates)
              PopupMenuItem<double>(
                value: r,
                child: Row(children: [
                  Icon(
                      r == _playbackRate
                          ? Icons.check_rounded
                          : Icons.speed_rounded,
                      size: 16,
                      color: r == _playbackRate
                          ? const Color(0xFFFF7043)
                          : Colors.white54),
                  const SizedBox(width: 8),
                  Text(
                      widget.provider
                          .t('ve.rateX')
                          .replaceFirst('{r}', _rateLabel(r)),
                      style: const TextStyle(color: Colors.white)),
                ]),
              ),
          ],
          child: Container(
            margin: const EdgeInsets.symmetric(horizontal: 4),
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
            decoration: BoxDecoration(
              color: const Color(0xFF24243A),
              borderRadius: BorderRadius.circular(6),
              border: Border.all(color: const Color(0xFFFF7043)),
            ),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              const Icon(Icons.speed_rounded,
                  color: Color(0xFFFF7043), size: 15),
              const SizedBox(width: 3),
              Text('${_rateLabel(_playbackRate)}x',
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 12,
                      fontWeight: FontWeight.w600)),
            ]),
          ),
        ),
        // ── タイムラインの目盛り幅 (= ユーザー要望: 虫眼鏡アイコンだと
        //    「拡大率」 に見えて紛らわしいので、 時間軸の圧縮/伸長と分かる
        //    アイコン + ツールチップに変更)。 ついでにズーム時は再生ヘッドを
        //    基準にスクロール位置を補正し、 見た目上ヘッドが飛ばないようにする。
        IconButton(
          tooltip: widget.provider.t('ve.timelineZoomOut'),
          icon: const Icon(Icons.compress_rounded,
              color: Colors.white54, size: 20),
          onPressed: () => _zoomTimeline(1 / 1.4),
          visualDensity: VisualDensity.compact,
        ),
        IconButton(
          tooltip: widget.provider.t('ve.timelineZoomIn'),
          icon: const Icon(Icons.expand_rounded,
              color: Colors.white54, size: 20),
          onPressed: () => _zoomTimeline(1.4),
          visualDensity: VisualDensity.compact,
        ),
      ]),
    );
  }


  /// タイムラインの目盛り幅を変更する。 再生ヘッドの画面上の位置が
  /// 変わらないようスクロール位置も補正する (= ユーザー要望: ズームすると
  /// 再生位置が動いたように見えて紛らわしい問題の解消)。
  void _zoomTimeline(double factor) {
    final beforePx = _playheadMs / 1000.0 * _pxPerSec;
    setState(() => _pxPerSec = (_pxPerSec * factor).clamp(20.0, 400.0));
    final afterPx = _playheadMs / 1000.0 * _pxPerSec;
    if (_hScroll.hasClients) {
      final target = (_hScroll.offset + afterPx - beforePx)
          .clamp(0.0, _hScroll.position.maxScrollExtent);
      _hScroll.jumpTo(target);
    }
  }

  /// 選択した要素と再生ヘッドがタイムラインの見える位置に来るよう
  /// スクロールする (= ユーザー要望: 詳細パネルを開いた時にどの再生位置か
  /// 分かるように)。
  void _scrollTimelineToItem(_VeItem it) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_hScroll.hasClients) return;
      final itemPx = it.startMs / 1000.0 * _pxPerSec;
      final viewW = _hScroll.position.viewportDimension;
      // 要素の開始が画面の 1/4 の位置に来るように。
      final target = (itemPx - viewW / 4)
          .clamp(0.0, _hScroll.position.maxScrollExtent);
      _hScroll.animateTo(target,
          duration: const Duration(milliseconds: 200), curve: Curves.easeOut);
    });
  }

  // ── タイムラインの音声レベル表示 (= ユーザー要望: タイムライン上の動画の
  //    下にそれぞれの位置での音声の大きさが表示されるように) ──────────────
  // ffmpeg で音声を 8kHz/モノラル/8bit PCM に落とし、 100ms ごとの RMS を
  // 0..1 に正規化してキャッシュする。 デスクトップは外部 ffmpeg(.exe)、
  // モバイルは ffmpeg_kit を使う。 取得できない環境では単に表示しない。
  final Map<String, List<double>> _audioLevels = {};
  final Set<String> _audioLevelsPending = {};
  static const int _kAudioBucketMs = 100;

  void _requestAudioLevels(String path) {
    if (path.isEmpty || kIsWeb) return;
    if (_audioLevels.containsKey(path) || _audioLevelsPending.contains(path)) {
      return;
    }
    _audioLevelsPending.add(path);
    unawaited(_extractAudioLevels(path));
  }

  Future<void> _extractAudioLevels(String path) async {
    List<double> levels = const [];
    final tmp = '${Directory.systemTemp.path}${Platform.pathSeparator}'
        've_lvl_${DateTime.now().microsecondsSinceEpoch}.raw';
    try {
      final args = <String>[
        '-y',
        '-i',
        path,
        '-vn',
        '-ac',
        '1',
        '-ar',
        '8000',
        '-f',
        'u8',
        tmp,
      ];
      bool ok = false;
      final bool isMobile =
          !kIsWeb && (Platform.isAndroid || Platform.isIOS);
      if (isMobile) {
        final session = await FFmpegKit.executeWithArguments(args);
        ok = ReturnCode.isSuccess(await session.getReturnCode());
      } else {
        final ff = await _findFfmpeg();
        if (ff != null) {
          final r = await Process.run(ff, args,
              workingDirectory: Directory.systemTemp.path);
          ok = r.exitCode == 0;
        }
      }
      if (ok) {
        final f = File(tmp);
        if (await f.exists()) {
          final bytes = await f.readAsBytes();
          // RMS 計算は長尺動画で数千万サンプルになるため isolate へ逃がす。
          levels = await compute(_veComputeAudioLevels, bytes);
        }
      }
    } catch (e) {
      debugPrint('音声レベル抽出失敗: $e');
    } finally {
      try {
        File(tmp).deleteSync();
      } catch (_) {}
    }
    if (!mounted) return;
    setState(() => _audioLevels[path] = levels);
  }

  Widget _buildTimeline() {
    final totalW = (_totalMs / 1000.0 * _pxPerSec).clamp(200.0, 1000000.0);
    return SingleChildScrollView(
      scrollDirection: Axis.vertical,
      child: SizedBox(
        height: _rulerH + _kVeLayers * _rowH,
        child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          // 左ガター: レイヤーラベル (上が高レイヤー=前面)
          SizedBox(
            width: 34,
            child: Column(children: [
              const SizedBox(height: _rulerH),
              for (int l = _kVeLayers - 1; l >= 0; l--)
                Container(
                  height: _rowH,
                  alignment: Alignment.center,
                  decoration: const BoxDecoration(
                      border: Border(
                          bottom: BorderSide(color: Colors.white10, width: 1))),
                  child: Text('L$l',
                      style:
                          const TextStyle(color: Colors.white38, fontSize: 11)),
                ),
            ]),
          ),
          Expanded(
            // = ユーザー要望: 中身が無くてもタイムラインを右端まで表示する。
            //   ビューポート幅と内容幅の大きい方を使う (日付増で自動的に伸びる)。
            child: LayoutBuilder(builder: (ctx, cns) {
              final w = math.max(totalW.toDouble(), cns.maxWidth);
              _timelineVisualMaxMs =
                  math.max(_totalMs, (w / _pxPerSec * 1000).round());
              return SingleChildScrollView(
                controller: _hScroll,
                scrollDirection: Axis.horizontal,
                child: SizedBox(
                  width: w,
                  height: _rulerH + _kVeLayers * _rowH,
                  child: Stack(children: [
                    // タップでシーク + 右クリックで挿入メニュー (背面全域)
                    Positioned.fill(
                      child: GestureDetector(
                        behavior: HitTestBehavior.translucent,
                        onTapDown: (d) {
                          final ms =
                              (d.localPosition.dx / _pxPerSec * 1000).round();
                          _stop();
                          setState(() => _selId = null);
                          _seekTo(ms);
                        },
                        // = ユーザー要望: タイムライン右クリックでテキスト/画像を挿入。
                        onSecondaryTapDown: (d) {
                          final ms = (d.localPosition.dx / _pxPerSec * 1000)
                              .round()
                              .clamp(0, 1 << 30);
                          _showTimelineInsertMenu(d.globalPosition, ms);
                        },
                        onLongPressStart: (d) {
                          // モバイル向け: 長押しでも挿入メニュー。
                          final ms = (d.localPosition.dx / _pxPerSec * 1000)
                              .round()
                              .clamp(0, 1 << 30);
                          _showTimelineInsertMenu(d.globalPosition, ms);
                        },
                      ),
                    ),
                    // レイヤー行の背景 (装飾: ポインタ透過)
                    for (int row = 0; row < _kVeLayers; row++)
                      Positioned(
                        left: 0,
                        right: 0,
                        top: _rulerH + row * _rowH,
                        height: _rowH,
                        child: IgnorePointer(
                          child: Container(
                            decoration: BoxDecoration(
                              color: row.isEven
                                  ? const Color(0xFF15151F)
                                  : const Color(0xFF101019),
                              border: const Border(
                                  bottom: BorderSide(
                                      color: Colors.white10, width: 1)),
                            ),
                          ),
                        ),
                      ),
                    ..._buildRulerMarks(w),
                    for (final it in _items) _buildBlock(it),
                    // 再生ヘッド (装飾: ポインタ透過)
                    Positioned(
                      left: _playheadMs / 1000.0 * _pxPerSec,
                      top: 0,
                      bottom: 0,
                      width: 2,
                      child: IgnorePointer(
                        child: Container(color: const Color(0xFFFF7043)),
                      ),
                    ),
                  ]),
                ),
              );
            }),
          ),
        ]),
      ),
    );
  }

  List<Widget> _buildRulerMarks(double widthPx) {
    // = ユーザー要望: 何もオブジェクトが無い時は時間目盛を出さない。
    if (_items.isEmpty) return const [];
    final marks = <Widget>[];
    final stepSec = _pxPerSec < 40 ? 5 : 1;
    // = ユーザー要望: 目盛が途中(2秒)で切れないよう、 表示幅いっぱいまで引く。
    final totalSec = (widthPx / _pxPerSec).ceil() + 1;
    for (int s = 0; s <= totalSec; s += stepSec) {
      final x = s * _pxPerSec;
      marks.add(Positioned(
        left: x,
        top: 0,
        height: _rulerH,
        child: IgnorePointer(
          child: Row(children: [
            Container(width: 1, height: _rulerH, color: Colors.white24),
            const SizedBox(width: 2),
            Text('${s}s',
                style: const TextStyle(color: Colors.white38, fontSize: 9)),
          ]),
        ),
      ));
    }
    return marks;
  }

  /// タイムライン右クリック/長押しの挿入メニュー (= ユーザー要望)。
  /// 指定時刻 [atMs] にテキスト/画像を追加する。
  Future<void> _showTimelineInsertMenu(Offset globalPos, int atMs) async {
    final overlay = Overlay.of(context).context.findRenderObject() as RenderBox;
    final sel = await showMenu<String>(
      context: context,
      color: const Color(0xFF24243A),
      position: RelativeRect.fromRect(
        globalPos & const Size(40, 40),
        Offset.zero & overlay.size,
      ),
      items: [
        // ── 動画を挿入 (= ユーザー要望: 右クリック/長押しメニューに動画の
        //    挿入項目が無くて不便) ──
        PopupMenuItem(
          value: 'video',
          child: Row(children: [
            const Icon(Icons.movie_rounded, color: Color(0xFF4FC3F7), size: 18),
            const SizedBox(width: 10),
            Text(widget.provider.t('ve.addVideo'),
                style: const TextStyle(color: Colors.white)),
          ]),
        ),
        PopupMenuItem(
          value: 'text',
          child: Row(children: [
            const Icon(Icons.title_rounded, color: Color(0xFFFFB74D), size: 18),
            const SizedBox(width: 10),
            Text(widget.provider.t('ve.addText'),
                style: const TextStyle(color: Colors.white)),
          ]),
        ),
        PopupMenuItem(
          value: 'image',
          child: Row(children: [
            const Icon(Icons.image_rounded, color: Color(0xFF66BB6A), size: 18),
            const SizedBox(width: 10),
            Text(widget.provider.t('ve.addImage'),
                style: const TextStyle(color: Colors.white)),
          ]),
        ),
      ],
    );
    if (sel == 'video') {
      _addVideo(at: atMs);
    } else if (sel == 'text') {
      _addText(at: atMs);
    } else if (sel == 'image') {
      _addImage(at: atMs);
    }
  }

  Widget _buildBlock(_VeItem it) {
    final left = it.startMs / 1000.0 * _pxPerSec;
    final width = (it.durationMs / 1000.0 * _pxPerSec).clamp(8.0, 1000000.0);
    final row = _kVeLayers - 1 - it.layer; // L0 を最下段に表示
    final top = _rulerH + row * _rowH + 3;
    final selected = it.id == _selId;
    final color = _layerColor(it.kind);
    return Positioned(
      left: left,
      top: top,
      width: width.toDouble(),
      height: _rowH - 6,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        // クリックで選択 + 右の編集サイドメニューを開く (= ユーザー要望)。
        onTap: () => _openItemPanel(it),
        onDoubleTap: () => _openItemPanel(it),
        // ── 右クリックで「再生位置で分割」 メニュー (= ユーザー要望:
        //    要素を選択して右クリックで、 その再生位置で要素を分割) ──
        onSecondaryTapDown: (d) => _showVeItemMenu(it, d.globalPosition),
        onPanStart: (_) {
          _openItemPanel(it);
          setState(() {
            _selId = it.id;
            _panelItemId = it.id;
            _dragId = it.id;
            _dragStartMs = it.startMs;
            _dragLayer = it.layer;
            _dragDx = 0;
            _dragDy = 0;
            _resizing = false;
          });
        },
        onPanUpdate: (d) {
          if (_dragId != it.id || _resizing) return;
          _dragDx += d.delta.dx;
          _dragDy += d.delta.dy;
          setState(() {
            final dms = (_dragDx / _pxPerSec * 1000).round();
            it.startMs = (_dragStartMs + dms).clamp(0, 1 << 30);
            final dRows = (_dragDy / _rowH).round();
            it.layer = (_dragLayer - dRows).clamp(0, _kVeLayers - 1);
          });
        },
        onPanEnd: (_) {
          _dragId = null;
          if (_panelItemId == it.id) _syncPanelEditors(it);
          _persist();
          _seekTo(_playheadMs);
        },
        // ── 長押しで掴んで自由に移動 (= ユーザー要望: モバイルでタイムライン上の
        //    要素を長押しで動かせるように)。 即時パンはタイムラインの横スクロールと
        //    競合してしまうが、 長押し移動なら競合せず確実に掴んで動かせる。 ──
        onLongPressStart: (_) {
          _openItemPanel(it);
          setState(() {
            _selId = it.id;
            _panelItemId = it.id;
            _dragId = it.id;
            _dragStartMs = it.startMs;
            _dragLayer = it.layer;
            _resizing = false;
          });
        },
        onLongPressMoveUpdate: (d) {
          if (_dragId != it.id || _resizing) return;
          setState(() {
            final dms = (d.localOffsetFromOrigin.dx / _pxPerSec * 1000).round();
            it.startMs = (_dragStartMs + dms).clamp(0, 1 << 30);
            final dRows = (d.localOffsetFromOrigin.dy / _rowH).round();
            it.layer = (_dragLayer - dRows).clamp(0, _kVeLayers - 1);
          });
        },
        onLongPressEnd: (_) {
          _dragId = null;
          if (_panelItemId == it.id) _syncPanelEditors(it);
          _persist();
          _seekTo(_playheadMs);
        },
        child: Stack(children: [
          Container(
            decoration: BoxDecoration(
              color: color.withValues(alpha: selected ? 0.55 : 0.32),
              borderRadius: BorderRadius.circular(5),
              border: Border.all(
                  color: selected ? const Color(0xFFFF7043) : color,
                  width: selected ? 2 : 1),
            ),
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
            alignment: Alignment.centerLeft,
            child: Row(children: [
              Icon(_kindIcon(it.kind), color: Colors.white70, size: 12),
              const SizedBox(width: 4),
              Expanded(
                child: Text(it.displayName,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(color: Colors.white, fontSize: 11)),
              ),
            ]),
          ),
          // ── 音声レベル (= ユーザー要望: 動画の下にそれぞれの位置での
          //    音声の大きさを表示)。 ブロック下部に波形バーを重ねる。 ──
          if (it.kind == _VeKind.video)
            Builder(builder: (_) {
              _requestAudioLevels(it.path);
              final lv = _audioLevels[it.path];
              if (lv == null || lv.isEmpty) return const SizedBox.shrink();
              return Positioned(
                left: 2,
                right: 2,
                bottom: 1,
                height: math.min(14.0, (_rowH - 6) * 0.45),
                child: IgnorePointer(
                  child: CustomPaint(
                    painter: _VeAudioLevelPainter(
                      levels: lv,
                      srcInMs: it.srcInMs,
                      durationMs: it.durationMs,
                      bucketMs: _kAudioBucketMs,
                    ),
                  ),
                ),
              );
            }),
          // ── 左端リサイズハンドル (= ユーザー要望: 要素を左から右に小さく
          //    できるように)。 左端を右へドラッグすると、 開始位置を前進させ
          //    つつ尺を縮める。 動画はソース内トリム開始 (srcInMs) も同量
          //    ずらして、 表示内容が飛ばないようにする。 ──
          Positioned(
            left: 0,
            top: 0,
            bottom: 0,
            width: 16,
            child: GestureDetector(
              behavior: HitTestBehavior.opaque,
              onPanStart: (_) {
                _openItemPanel(it);
                _resizing = true;
                _resizeLeft = true;
                _dragId = it.id;
                _dragDx = 0;
                _dragStartMs = it.startMs;
                _dragStartDurMs = it.durationMs;
                _dragStartSrcInMs = it.srcInMs;
                setState(() => _selId = it.id);
              },
              onPanUpdate: (d) {
                if (!_resizing || !_resizeLeft || _dragId != it.id) return;
                _dragDx += d.delta.dx;
                setState(() {
                  int dms = (_dragDx / _pxPerSec * 1000).round();
                  // 右へ動かす上限: 残り尺 200ms を確保。
                  final int maxDms = _dragStartDurMs - 200;
                  // 左へ動かす下限: 開始位置が 0 未満にならない。 動画は
                  //   ソース内開始 (srcInMs) も 0 未満にならない範囲まで。
                  int minDms = -_dragStartMs;
                  if (it.kind == _VeKind.video) {
                    final int minBySrc = -_dragStartSrcInMs;
                    if (minBySrc > minDms) minDms = minBySrc;
                  }
                  dms = dms.clamp(minDms, maxDms);
                  it.startMs = _dragStartMs + dms;
                  it.durationMs = _dragStartDurMs - dms;
                  if (it.kind == _VeKind.video) {
                    it.srcInMs = _dragStartSrcInMs + dms;
                  }
                });
              },
              onPanEnd: (_) {
                _resizing = false;
                _resizeLeft = false;
                _dragId = null;
                _clampVideoItemToSource(it);
                if (_panelItemId == it.id) _syncPanelEditors(it);
                _persist();
                _seekTo(_playheadMs);
              },
              child: Align(
                alignment: Alignment.centerLeft,
                child: Container(
                  width: 3,
                  margin:
                      const EdgeInsets.symmetric(vertical: 6, horizontal: 4),
                  decoration: BoxDecoration(
                      color: Colors.white54,
                      borderRadius: BorderRadius.circular(2)),
                ),
              ),
            ),
          ),
          // 右端リサイズハンドル
          Positioned(
            right: 0,
            top: 0,
            bottom: 0,
            width: 16,
            child: GestureDetector(
              behavior: HitTestBehavior.opaque,
              onPanStart: (_) {
                _openItemPanel(it);
                _resizing = true;
                _resizeLeft = false;
                _dragId = it.id;
                _dragDx = 0;
                _dragStartMs = it.durationMs;
                setState(() => _selId = it.id);
              },
              onPanUpdate: (d) {
                if (!_resizing || _dragId != it.id) return;
                _dragDx += d.delta.dx;
                setState(() {
                  final dms = (_dragDx / _pxPerSec * 1000).round();
                  final desired = _dragStartMs + dms;
                  if (it.kind == _VeKind.video && it.srcDurationMs > 0) {
                    final remaining =
                        math.max(1, it.srcDurationMs - it.srcInMs);
                    final minDuration = math.min(200, remaining);
                    it.durationMs = desired.clamp(minDuration, remaining);
                  } else {
                    it.durationMs = desired.clamp(200, 1 << 30);
                  }
                });
              },
              onPanEnd: (_) {
                _resizing = false;
                _dragId = null;
                _clampVideoItemToSource(it);
                if (_panelItemId == it.id) _syncPanelEditors(it);
                _persist();
              },
              child: Align(
                alignment: Alignment.centerRight,
                child: Container(
                  width: 3,
                  margin:
                      const EdgeInsets.symmetric(vertical: 6, horizontal: 4),
                  decoration: BoxDecoration(
                      color: Colors.white54,
                      borderRadius: BorderRadius.circular(2)),
                ),
              ),
            ),
          ),
        ]),
      ),
    );
  }
}

/// モバイルの動画ビューアから「メモを AI に渡す / AI チャットを全画面で開く」 ための
/// 全画面ブラウザ AI ページ (= ユーザー要望: 動画メモを AI に送るボタン + AI
/// チャット欄を全画面表示するボタン)。 設定中のブラウザ AI を InAppWebView で開き、
/// 入力欄へメモ本文を JS 注入する (注入が空振りしてもクリップボードから貼り付け可能)。
/// 8bit(u8)/8kHz/モノラル PCM から 100ms ごとの RMS 音量 (0..1 正規化) を
/// 計算する (= ユーザー要望: タイムラインの動画の下に音声の大きさを表示)。
/// 長尺動画では数千万サンプルになるため compute() で isolate 実行する。
List<double> _veComputeAudioLevels(Uint8List bytes) {
  const samplesPerBucket = 8000 * 100 ~/ 1000; // 8kHz × 100ms = 800
  final n = bytes.length ~/ samplesPerBucket;
  if (n <= 0) return const [];
  final out = <double>[];
  double maxRms = 0.0;
  for (int b = 0; b < n; b++) {
    double sum = 0;
    final off = b * samplesPerBucket;
    for (int i = 0; i < samplesPerBucket; i++) {
      final v = (bytes[off + i] - 128) / 128.0;
      sum += v * v;
    }
    final rms = math.sqrt(sum / samplesPerBucket);
    if (rms > maxRms) maxRms = rms;
    out.add(rms);
  }
  // ピーク正規化 (最大音量 = バー最大)。 無音に近い時はそのまま。
  if (maxRms > 0.001) {
    for (int i = 0; i < out.length; i++) {
      out[i] = (out[i] / maxRms).clamp(0.0, 1.0);
    }
  }
  return out;
}

/// タイムラインの動画ブロック下部に音声レベルの縦棒列を描く painter
/// (= ユーザー要望)。 ブロックのトリム (srcInMs) と尺に追従する。
class _VeAudioLevelPainter extends CustomPainter {
  final List<double> levels;
  final int srcInMs;
  final int durationMs;
  final int bucketMs;
  _VeAudioLevelPainter({
    required this.levels,
    required this.srcInMs,
    required this.durationMs,
    required this.bucketMs,
  });

  @override
  void paint(Canvas canvas, Size size) {
    if (levels.isEmpty || durationMs <= 0 || size.width <= 0) return;
    final paint = Paint()
      ..color = const Color(0xCC4FC3F7)
      ..isAntiAlias = false;
    // 2px 間隔の縦棒で描く (幅の広いブロックでも軽い)。
    for (double x = 0; x < size.width; x += 2) {
      final ms = srcInMs + (x / size.width) * durationMs;
      final bi = ms ~/ bucketMs;
      if (bi < 0 || bi >= levels.length) continue;
      final h = (levels[bi] * size.height).clamp(0.6, size.height);
      canvas.drawRect(
          Rect.fromLTWH(x, size.height - h, 1.4, h.toDouble()), paint);
    }
  }

  @override
  bool shouldRepaint(covariant _VeAudioLevelPainter old) =>
      old.levels != levels ||
      old.srcInMs != srcInMs ||
      old.durationMs != durationMs ||
      old.bucketMs != bucketMs;
}

class _MobileBrowserAiPage extends StatefulWidget {
  final String url;
  final String injectText;
  final VoidCallback? onClose;
  final bool embedded;
  const _MobileBrowserAiPage({
    required this.url,
    required this.injectText,
    this.onClose,
    this.embedded = false,
  });
  @override
  State<_MobileBrowserAiPage> createState() => _MobileBrowserAiPageState();
}

class _MobileBrowserAiPageState extends State<_MobileBrowserAiPage> {
  iaw.InAppWebViewController? _ctrl;
  late final String _initialAiHost;

  @override
  void initState() {
    super.initState();
    _initialAiHost = Uri.tryParse(widget.url)?.host.toLowerCase() ?? '';
  }

  /// プロンプトを注入してよいのは、最初に開いた AI URL と同一 host のページだけ。
  /// ログイン・認証・外部リンクへの redirect 中に入力内容が漏れるのを防ぐ。
  bool _isInitialAiHost(Object? rawUrl) {
    final current = Uri.tryParse(rawUrl?.toString() ?? '');
    if (current == null || _initialAiHost.isEmpty) return false;
    return current.host.toLowerCase() == _initialAiHost;
  }

  /// AI ページの入力欄を探してメモ本文を流し込む (= ノード AI の注入と同等)。
  Future<void> _inject() async {
    final c = _ctrl;
    final t = widget.injectText.trim();
    if (c == null || t.isEmpty) return;
    // onLoadStop 後の遅延中にも redirect され得るため、注入する瞬間の URL を
    // controller から再取得して検証する (schedule 時の URL だけを信用しない)。
    try {
      final currentUrl = await c.getUrl();
      if (!mounted || !_isInitialAiHost(currentUrl)) return;
    } catch (_) {
      return;
    }
    final escaped = jsonEncode(widget.injectText);
    if (_initialAiHost.isEmpty) return;
    final escapedAllowedHost = jsonEncode(_initialAiHost);
    final js = '''
(function() {
  try {
    var allowedHost = $escapedAllowedHost;
    if ((window.location.hostname || '').toLowerCase() !== allowedHost) {
      return 'blocked-host';
    }
    var text = $escaped;
    var tt = (text || '').trim();
    if (!tt) return 'empty';
    var lp = ((location.host || '') + ' ' + (location.pathname || ''))
        .toLowerCase();
    if (/accounts\.google|appleid|signin|sign-in|sign_in|login|log-in|auth\./
        .test(lp)) return 'login-page';
    function isLoginField(el) {
      if (!el || el.tagName !== 'INPUT') return false;
      var ty = (el.type || '').toLowerCase();
      if (ty !== 'text' && ty !== 'search' && ty !== '') return true;
      var meta = ((el.name || '') + ' ' + (el.id || '') + ' ' +
          (el.autocomplete || '') + ' ' +
          (el.getAttribute('aria-label') || '')).toLowerCase();
      if (/email|identifier|passw|user|phone|tel|otp|code/.test(meta)) {
        return true;
      }
      var f = el.closest('form');
      if (f && f.querySelector(
          'input[type="password"],input[type="email"]')) return true;
      return false;
    }
    var selectors = [
      'div.ProseMirror[contenteditable="true"]',
      '#prompt-textarea',
      'div[contenteditable="true"].ql-editor',
      'textarea',
      'input[type="text"]',
      'div[contenteditable="true"]',
    ];
    function visibleArea(el){var r=el.getBoundingClientRect();if(r.width<80||r.height<16)return 0;if(r.bottom<0||r.top>window.innerHeight)return 0;return r.width*r.height;}
    var best=null,bestArea=0;
    for(var i=0;i<selectors.length;i++){var nodes=document.querySelectorAll(selectors[i]);for(var j=0;j<nodes.length;j++){if(isLoginField(nodes[j]))continue;var a=visibleArea(nodes[j]);if(a>bestArea){bestArea=a;best=nodes[j];}}if(best)break;}
    if(!best)return 'not-found';
    var tag=best.tagName;var isField=tag==='TEXTAREA'||tag==='INPUT';
    var existing=isField?(best.value||''):(best.innerText||best.textContent||'');
    if(existing.indexOf(tt)!==-1)return 'already';
    best.focus();
    if(isField){
      var proto=tag==='TEXTAREA'?window.HTMLTextAreaElement.prototype:window.HTMLInputElement.prototype;
      var setter=Object.getOwnPropertyDescriptor(proto,'value').set;
      setter.call(best,text);
      best.dispatchEvent(new Event('input',{bubbles:true}));
      try{best.selectionStart=best.selectionEnd=text.length;}catch(e){}
    }else{
      try{var range=document.createRange();range.selectNodeContents(best);var sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);document.execCommand('insertText',false,text);}
      catch(e){best.innerText=text;best.dispatchEvent(new InputEvent('input',{bubbles:true,data:text}));}
    }
    return 'ok';
  } catch(e){ return 'error:'+e; }
})();
''';
    try {
      await c.evaluateJavascript(source: js);
    } catch (_) {}
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF12121F),
      appBar: AppBar(
        backgroundColor: const Color(0xFF1A1A30),
        elevation: 0,
        leading: IconButton(
          icon: Icon(
              widget.embedded ? Icons.close_rounded : Icons.arrow_back_rounded,
              color: Colors.white),
          onPressed: widget.onClose ?? () => Navigator.of(context).maybePop(),
        ),
        title: Row(mainAxisSize: MainAxisSize.min, children: const [
          Icon(Icons.auto_awesome_rounded, color: Color(0xFFBA68C8), size: 18),
          SizedBox(width: 8),
          Text('AI', style: TextStyle(color: Colors.white, fontSize: 16)),
        ]),
        actions: [
          // ── リンクを踏んだ後に戻れるように (= ユーザー要望) ──
          IconButton(
            tooltip: context.read<MindMapProvider>().t('split.back'),
            icon: const Icon(Icons.arrow_back_ios_new_rounded,
                color: Colors.white70, size: 18),
            onPressed: () async {
              final c = _ctrl;
              if (c == null) return;
              if (await c.canGoBack()) {
                await c.goBack();
              } else {
                // 履歴が無ければ最初のページへ戻す。
                await c.loadUrl(
                    urlRequest: iaw.URLRequest(url: iaw.WebUri(widget.url)));
              }
            },
          ),
          IconButton(
            tooltip: context.read<MindMapProvider>().t('split.forward'),
            icon: const Icon(Icons.arrow_forward_ios_rounded,
                color: Colors.white70, size: 18),
            onPressed: () async {
              final c = _ctrl;
              if (c == null) return;
              if (await c.canGoForward()) await c.goForward();
            },
          ),
          IconButton(
            tooltip: context.read<MindMapProvider>().t('btn.reload'),
            icon: const Icon(Icons.refresh_rounded,
                color: Colors.white70, size: 19),
            onPressed: () async {
              final c = _ctrl;
              if (c == null) return;
              await c.reload();
            },
          ),
          if (widget.injectText.trim().isNotEmpty)
            IconButton(
              tooltip: context.read<MindMapProvider>().t('ai.pasteToInput'),
              icon: const Icon(Icons.content_paste_rounded,
                  color: Colors.white70),
              onPressed: _inject,
            ),
        ],
      ),
      body: iaw.InAppWebView(
        initialUrlRequest: iaw.URLRequest(url: iaw.WebUri(widget.url)),
        initialSettings: iaw.InAppWebViewSettings(
          javaScriptEnabled: true,
          domStorageEnabled: true,
          useHybridComposition: true,
          mediaPlaybackRequiresUserGesture: false,
          allowsInlineMediaPlayback: true,
          transparentBackground: false,
        ),
        onWebViewCreated: (c) => _ctrl = c,
        onLoadStop: (c, url) async {
          if (!_isInitialAiHost(url)) return;
          // AI ページの入力欄が生成されるのを待って数回注入する。
          for (final ms in const [900, 2000, 3500]) {
            Future.delayed(Duration(milliseconds: ms), () {
              if (mounted) _inject();
            });
          }
        },
      ),
    );
  }
}

/// バックグラウンド再生用のページ先回りパッチ (= ユーザー要望: ON なのに
/// 再生される時とされない時があるのを無くす)。
///
/// document start で流し込むことで、 YouTube が visibilitychange リスナーを
/// 登録する前に「常に表示中」 と思わせる。 背面に回ってから注入していた
/// 従来方式は、 登録順のレースで効いたり効かなかったりしていた。
const String _kBgPlaybackPatchJs = r"""
(function() {
  if (window.__MM_VISIBILITY_PATCHED__) return;
  try {
    Object.defineProperty(document, 'hidden',
      { configurable: true, get: function() { return false; } });
    Object.defineProperty(document, 'visibilityState',
      { configurable: true, get: function() { return 'visible'; } });
    Object.defineProperty(document, 'webkitHidden',
      { configurable: true, get: function() { return false; } });
    Object.defineProperty(document, 'webkitVisibilityState',
      { configurable: true, get: function() { return 'visible'; } });
    var origAdd = EventTarget.prototype.addEventListener;
    EventTarget.prototype.addEventListener = function(type, listener, opts) {
      if (type === 'visibilitychange' || type === 'webkitvisibilitychange') {
        return; // サイト側の「非表示になったら止める」 を登録させない
      }
      return origAdd.call(this, type, listener, opts);
    };
    window.__MM_VISIBILITY_PATCHED__ = true;
  } catch (e) {}
})();
""";

class _FullscreenVideoPage extends StatefulWidget {
  final String url;
  final List<String> playlist;
  final int startIndex;
  final double initialRate;

  /// 動画の開始位置 (秒)。PiP からフルスクリーンに復帰するときに使う。
  /// 0 ならシーク無し (= 動画の先頭から)。
  final double initialPosition;
  final void Function(String currentUrl)? onEmbedUrl;

  /// true の場合、関連動画・コメント・ヘッダー等を隠す CSS を注入する
  /// (ノード動画再生のような「視聴専用」用途向け)。
  /// false の場合は素の YouTube UI のまま (検索して動画を探す用途向け)。
  final bool focusMode;

  /// 動画ダウンロードが完了した時に呼ばれる。引数はダウンロードした
  /// メタ情報 (path / title / sourceUrl / videoId / sizeBytes / downloadedAt)。
  /// MindMapScreen 側でこのコールバックを設定して、現在のキャンバス中央に
  /// 動画ノードを自動生成する用途。null の場合は埋め込みを行わない。
  final void Function(Map<String, dynamic> record)? onDownloadComplete;

  /// 現在の URL を画面分割パネルに移して表示するコールバック。
  /// null なら「画面分割へ」 ボタンは出ない (= 旧挙動)。
  final void Function(String currentUrl, {bool isLeftPanel})?
      onMoveToSplitPanel;
  const _FullscreenVideoPage({
    required this.url,
    this.playlist = const [],
    this.startIndex = 0,
    this.initialRate = 1.0,
    this.initialPosition = 0.0,
    this.onEmbedUrl,
    this.focusMode = true,
    this.onDownloadComplete,
    this.onMoveToSplitPanel,
  });
  @override
  State<_FullscreenVideoPage> createState() => _FullscreenVideoPageState();
}

