  ///  閉じるだけでなくページ自体も戻ってしまう。 1 回目の戻るはパネルを
  ///  閉じるだけにして、 もう一度戻るとページ遷移するようにする)。
  /// パネルは history entry を作らないことがあるため、 goBack() だと
  /// パネルを飛び越えて前のページへ戻ってしまう。 そこで DOM から開いている
  /// engagement panel / bottom sheet を探して閉じるボタンを押し、
  /// 閉じたら 'closed' を返す (= その場合は goBack しない)。
  static const String _kCloseYtPanelJs = '''
(function(){
  function visible(el){
    try { return el && el.getClientRects().length > 0; } catch(e){ return false; }
  }
  try {
    var panels = document.querySelectorAll(
      'ytm-engagement-panel, [class*="engagement-panel"], ' +
      'ytm-bottom-sheet-renderer, .bottom-sheet-container');
    for (var i = 0; i < panels.length; i++) {
      var p = panels[i];
      if (!visible(p)) continue;
      var btns = p.querySelectorAll('button');
      for (var j = 0; j < btns.length; j++) {
        var al = (btns[j].getAttribute('aria-label') || '').toLowerCase();
        if (al.indexOf('close') >= 0 || al.indexOf('閉じる') >= 0 ||
            al.indexOf('cancel') >= 0 || al.indexOf('キャンセル') >= 0) {
          btns[j].click();
          return 'closed';
        }
      }
      var hb = p.querySelector(
          '.engagement-panel-header button, .bottom-sheet-header button');
      if (hb) { hb.click(); return 'closed'; }
    }
  } catch(e){}
  return 'none';
})();
''';
