  @override
  void initState() {
    super.initState();
    _playbackRate = widget.initialRate;
    _playlist = widget.playlist.isNotEmpty ? widget.playlist : [widget.url];
    _playlistIndex = widget.startIndex.clamp(0, _playlist.length - 1);
    _analyzeUrlSync(_playlist[_playlistIndex]);
    _initialLoadTarget = _computeLoadTargetUrl(_playlist[_playlistIndex]);
    _loadYoutubeUiLayout();
    // ── 動画メモ履歴を復元 ──
    // 過去にこの動画で「履歴に保存」 したメモを呼び戻す。 セッションを
    // 越えて保持されるので、 後日同じ動画を開けば履歴一覧に再表示される。
    _videoMemoLoadFuture = _loadVideoMemoHistory();
    // 画面ロック防止 ON: 動画再生中は画面が自動オフにならないようにする。
    // dispose で OFF に戻す。失敗しても致命的ではないので例外は無視。
    try {
      WakelockPlus.enable();
    } catch (_) {}
    // AppLifecycle 監視を開始。バックグラウンド遷移時に WebView の
    // <video> を play() し続けるため。
    WidgetsBinding.instance.addObserver(this);
    // ── Foreground Service の起動 (バックグラウンド再生 ON の時だけ) ──
    // 通知バーに常駐表示する代わりに、Activity が onStop に入らず
    // 完全停止しないため、画面オフでも WebView の音声再生が継続する。
    // 同期で initialize されないので postFrameCallback で実行。
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      if (!mounted) return;
      try {
        final provider = context.read<MindMapProvider>();
        if (provider.backgroundPlaybackEnabled && Platform.isAndroid) {
          await _initAndStartForegroundService();
        }
      } catch (e) {
        debugPrint('Foreground service init failed: $e');
      }
    });
    // mp4 / ローカル動画は WebView の `<video>` 経路で再生する。
    //
    // 経緯: 当初は VideoPlayer (ExoPlayer / AVPlayer) を使って native UI の
    // 2x 速度キャップを避けようとしたが、video_player_android が一部の
    // 動画ファイルで初期化失敗する問題があった。一方 WebView 経路は
    // コーデック対応範囲が広く、`controlslist="noplaybackrate"` で native
    // の速度セレクタを消した上で、`<video>.playbackRate` を JS 注入で
    // 自由に設定できる (Flutter 上部スライダーから 1.0x〜16.0x まで)。
    //
    // file:// URL でローカルファイルを読むのでオフラインでも動作。
    //
    // 実装: `_useWebViewFallback = true` を立てて build を WebView 経路に
    // 向かわせる。HTML 自体は onWebViewCreated 内で `_buildMp4PlayerRaw`
    // を呼んで loadData する (= controller が生成された後の確実な
    // タイミング)。ここで postFrameCallback で先行ロードしようとすると
    // `_c` がまだ null で何もロードされない競合が起きる。
    if (_isMp4) {
      _useWebViewFallback = true;
      // _fallbackHtmlLoaded はわざと false のまま。onWebViewCreated 側で
      // `!_fallbackHtmlLoaded` 条件が真になって HTML がロードされる。
    }
    // ── ブラウズ時の URL 追従ポーリング (= チャンネル埋め込みボタン対策) ──
    // onEmbedUrl != null (= 「YouTubeを開く」 ブラウズ起動) の時だけ起動。
    // ノードからの動画再生 (onEmbedUrl == null) では埋め込みボタンが無いので不要。
    // SPA 遷移イベントが発火しないチャンネルページでも実 URL を拾って
    //   `_currentUrl` を更新し、 埋め込みボタンを確実に表示する。
    if (widget.onEmbedUrl != null) {
      _browseUrlPollTimer =
          Timer.periodic(const Duration(milliseconds: 900), (_) async {
        if (!mounted) return;
        try {
          final u = await _c?.getUrl();
          final urlStr = u?.toString() ?? '';
          if (urlStr.isNotEmpty && urlStr != _currentUrl) {
            setState(() => _analyzeUrlSync(urlStr));
            _persistBrowseUrl();
          }
        } catch (_) {}
      });
    }
    // 安全策: 15 秒経ってもローディング中のままならば強制解除する。
    // SPA サイト (YouTube チャンネルページ等) では onLoadStop が
    // 発火しないケースがあるため。
    Future.delayed(const Duration(seconds: 15), () {
      if (mounted && _loading) {
        setState(() => _loading = false);
      }
    });
  }

  /// ローカル動画ファイル / HTTP 直リンク mp4 を VideoPlayerController で初期化。
  /// 成功後は 500ms 間隔の UI 更新タイマーを起動 (シークバー / 時間表示の
  /// 反映用)。失敗時は `_vpcErrorMessage` にエラー詳細を入れて、build 側で
  /// 表示する。
  Future<void> _initLocalVideoPlayer(String url) async {
    // 状態クリア
    if (mounted) {
      setState(() {
        _vpcErrorMessage = null;
      });
    }
    // ── ステップ 1: パス正規化とローカルファイル健全性チェック ──
    String? localPath;
    bool isHttp = false;
    if (url.startsWith('http://') || url.startsWith('https://')) {
      isHttp = true;
    } else {
      var p = url;
      if (p.startsWith('file://')) {
        p = p.replaceFirst(RegExp(r'^file:/+'), '/');
      }
      localPath = p;
      // ローカルファイルなら実体・サイズを確認 (ダウンロード途中で
      // 中断されていないか / 0 バイトじゃないか)
      try {
        final f = File(p);
        if (!await f.exists()) {
          if (mounted) {
            setState(() {
              _loading = false;
              _vpcErrorMessage = 'ファイルが見つかりません:\n$p';
            });
          }
          return;
        }
        final size = await f.length();
        if (size <= 0) {
          if (mounted) {
            setState(() {
              _loading = false;
              _vpcErrorMessage = 'ファイルが空です (0 バイト):\n$p\n'
                  'ダウンロードが途中で中断された可能性があります。';
            });
          }
          return;
        }
      } catch (e) {
        if (mounted) {
          setState(() {
            _loading = false;
            _vpcErrorMessage = 'ファイル確認エラー: $e\nパス: $p';
          });
        }
        return;
      }

      // ── non-ASCII path フォールバック ──
      // video_player_android プラグインは、`File(path)` 内に非 ASCII 文字
      // (CJK / 全角 / 絵文字 / 全角記号 ！？ 等) があると、内部の URI
      // 変換で失敗して MediaCodec エラーや「Source error」になることが
      // ある。今後 DL するファイルは sanitize で ASCII セーフになるが、
      // 過去にダウンロードして全角入りファイル名で保存されているファイル
      // を救うため、ここで tmp にコピーして path を ASCII セーフ化する。
      if (RegExp(r'[^\x20-\x7E]').hasMatch(localPath!)) {
        try {
          final tmpDir = Directory.systemTemp;
          // 拡張子は維持
          final dot = localPath.lastIndexOf('.');
          final ext = dot >= 0 ? localPath.substring(dot) : '.mp4';
          // パスのハッシュで安定的なファイル名を生成 (毎回コピーせず
          // 既にあれば再利用)
          final hash = localPath.hashCode.toUnsigned(32).toRadixString(16);
          final safePath =
              '${tmpDir.path}${Platform.pathSeparator}vp_$hash$ext';
          final safeFile = File(safePath);
          if (!await safeFile.exists()) {
            await File(localPath).copy(safePath);
          }
          debugPrint('VideoPlayer: non-ASCII path detected, '
              'using copy at $safePath (orig: $localPath)');
          localPath = safePath;
        } catch (e) {
          debugPrint('non-ASCII fallback copy failed: $e');
          // コピーに失敗しても元 path で試す (まだチャンスはある)
        }
      }
    }

    // ── ステップ 2: VideoPlayerController を構築して初期化 ──
    VideoPlayerController? vpc;
    try {
      if (isHttp) {
        vpc = VideoPlayerController.networkUrl(Uri.parse(url));
      } else {
        vpc = VideoPlayerController.file(File(localPath!));
      }
      // 動画の URL / ファイル形式によっては数秒かかるので 30 秒まで待つ。
      await vpc.initialize().timeout(const Duration(seconds: 30));
      // initialize() が return した直後でも内部 value がエラーになっている
      // ことがある (Android の MediaCodec が非対応コーデックを検知した
      // ケース等)。ここで明示的にチェックして、エラーなら通常の catch
      // 経路と同じようにメッセージ表示に倒す。
      if (vpc.value.hasError) {
        throw 'プレイヤー初期化エラー: '
            '${vpc.value.errorDescription ?? "不明"}';
      }
      if (!vpc.value.isInitialized) {
        throw 'プレイヤーが初期化未完了状態です '
            '(動画ファイルが読み込めていない可能性)';
      }
    } catch (e, st) {
      debugPrint('VideoPlayer init failed for $url: $e\n$st');
      // dispose を確実に
      try {
        await vpc?.dispose();
      } catch (_) {}
      if (mounted) {
        setState(() {
          _loading = false;
          _vpcErrorMessage = '動画プレイヤーの初期化に失敗しました\n\n'
              'エラー: $e\n\n'
              'パス: ${localPath ?? url}\n\n'
              'コンテナ形式が ExoPlayer / AVPlayer に対応していない '
              '可能性があります。ファイル長押しで端末標準アプリで開けます。';
        });
      }
      return;
    }
    if (!mounted) {
      try {
        await vpc.dispose();
      } catch (_) {}
      return;
    }

    // ── ステップ 3: ランタイムエラー監視 ──
    // initialize() 後に start した後で MediaCodec エラーが出ることがある。
    // VideoPlayerController.value.hasError を listener で拾って画面表示する。
    vpc.addListener(_onVpcValueChanged);

    // ファイル名タイトル
    final fname = url.split('/').last.split('\\').last;
    setState(() {
      _vpc = vpc;
      _loading = false;
      if (_currentTitle.isEmpty) _currentTitle = fname;
    });
    try {
      await vpc.setPlaybackSpeed(_playbackRate);
      // ── ハイパーリンクからのジャンプ / PiP 復帰時の続きシーク ──
      // `widget.initialPosition` が指定されている場合はその位置に飛ぶ。
      // 0.5 秒未満は実質ゼロとして無視 (= 動画頭から再生)。
      if (widget.initialPosition > 0.5) {
        try {
          await vpc.seekTo(
              Duration(milliseconds: (widget.initialPosition * 1000).round()));
          _initialPositionSeeked = true;
        } catch (e) {
          debugPrint('VideoPlayer seekTo(initialPosition) failed: $e');
        }
      }
      await vpc.play();
    } catch (e) {
      debugPrint('VideoPlayer play() failed: $e');
    }
    // UI 更新ポーリング (500ms): listener と二重だが、シークバーの
    // スムーズな再描画のために setState を間引いた頻度で呼ぶ。
    _vpcUiTimer = Timer.periodic(const Duration(milliseconds: 500), (_) {
      if (mounted) setState(() {});
    });
    _scheduleHideVpcControls();
  }

  /// VideoPlayerController.value 変更時のリスナー。ランタイムエラーを
  /// 拾って `_vpcErrorMessage` に書き込む。`hasError` だけ気にすればよい。
  void _onVpcValueChanged() {
    final vpc = _vpc;
    if (vpc == null) return;
    if (vpc.value.hasError && _vpcErrorMessage == null) {
      final msg = vpc.value.errorDescription ?? '不明なエラー';
      debugPrint('VideoPlayer runtime error: $msg');
      if (mounted) {
        setState(() {
          _vpcErrorMessage = '再生中にエラーが発生しました:\n$msg';
        });
      }
    }
  }

  /// 3 秒間操作がなければ動画上のコントロール (中央のプレイボタン /
  /// 下部のシークバー) を自動で非表示にするタイマー。再表示は動画タップで。
  void _scheduleHideVpcControls() {
    _vpcControlsHideTimer?.cancel();
    _vpcControlsHideTimer = Timer(const Duration(seconds: 3), () {
      if (mounted && _vpc?.value.isPlaying == true) {
        setState(() => _vpcShowControls = false);
      }
    });
  }

  @override
  void dispose() {
    // AppLifecycle 監視を解除
    WidgetsBinding.instance.removeObserver(this);
    // バックグラウンド再生継続 Timer も停止
    _bgPlayKeeper?.cancel();
    _bgPlayKeeper = null;
    // ブラウズ URL 追従ポーリングも停止
    _browseUrlPollTimer?.cancel();
    _browseUrlPollTimer = null;
    // YouTube 検索ボックスの controller を破棄
    _ytSearchController.dispose();
    // 動画メモ入力欄の controller を破棄
    _videoMemoController.dispose();
    _videoMemoTsCtrl.dispose();
    _videoMemoTsFocus.dispose();
    _videoMemoFocus.dispose();
    // 動画メモプレビュー用タイマーも停止
    _videoMemoPreviewTimer?.cancel();
    _videoMemoPreviewTimer = null;
    // パネル内バナーのタイマーも停止 (setState-after-dispose 防止)
    _bannerTimer?.cancel();
    // VideoPlayer 関連を確実に破棄。タイマーを止めてから controller を
    // dispose しないと、タイマー側の setState が走って破棄済み controller を
    // 触りに行く可能性がある。
    _vpcUiTimer?.cancel();
    _vpcUiTimer = null;
    _vpcControlsHideTimer?.cancel();
    _vpcControlsHideTimer = null;
    try {
      _vpc?.removeListener(_onVpcValueChanged);
    } catch (_) {}
    _vpc?.dispose();
    _vpc = null;
    // 画面ロック防止 OFF。ただし PiP モードに移行している場合は PiP 側で
    // 再度 enable しているので、ここでは無条件に disable してよい (PiP 側
    // が後で enable する)。
    try {
      WakelockPlus.disable();
    } catch (_) {}
    // Foreground Service 停止 (起動していなければ no-op)
    _stopForegroundService();
    super.dispose();
  }

  /// アプリ ライフサイクル変更時のハンドラ。
  /// 画面オフ・ホームボタン・別アプリ起動などで `paused` または `inactive`
  /// 状態に遷移した時、Android の WebView は `<video>` を内部的に pause
  /// する。これを上書きするため、ここで明示的に play() を呼び直す JS を
  /// 実行する。Android Manifest の `showWhenLocked` と組み合わせると、
  /// 画面オフでも音声再生が継続する。
  ///
  /// `resumed` (前面復帰) の時は Timer を停止。
  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    super.didChangeAppLifecycleState(state);
    if (state == AppLifecycleState.paused ||
        state == AppLifecycleState.inactive ||
        state == AppLifecycleState.hidden) {
      // バックグラウンド再生機能が無効なら何もしない。OFF でも止まる
      // ようにしているのは、ユーザーが意図しない wakelock や復帰処理で
      // バッテリーを消費させないため。
      if (!mounted) return;
      final provider = context.read<MindMapProvider>();
      if (!provider.backgroundPlaybackEnabled) return;
      // ── Foreground Service の生存確認・再起動 ──
      // 2回目以降の画面オフでバックグラウンド再生が止まる問題への対策。
      // OS や audio focus の都合で player が一時停止 → audio_service が
      // Service を止める、というシーケンスが起きうる。paused に入る
      // たびに Service が生きているか確認して、止まっていたら再起動する。
      // ensureRunning は refCount を変えずに生存確認だけ行う。
      _BgPlaybackController.ensureRunning().catchError((_) {});
      // バックグラウンド遷移を検出。WebView 側の <video> が継続的に
      // pause される (Android の WebView 仕様) ので、Timer を起動して
      // 短い間隔で play() を呼び続ける。
      // 注: 1回だけ play() を呼んでも 100-300ms 後に WebView が再度
      // pause させてくるため、200ms 間隔で呼び直す。
      _startBgPlayKeeper();
    } else if (state == AppLifecycleState.resumed) {
      _stopBgPlayKeeper();
    }
  }

  /// バックグラウンド時に <video> を play() に保つ Timer を起動する。
  /// 既に起動中なら何もしない。200ms 間隔で play() 強制呼び出し。
  /// ユーザーが明示的に pause した場合 (__MM_USER_PAUSED__ = true) は
  /// 何もしない (= ユーザーの意図を尊重)。
  void _startBgPlayKeeper() {
    if (_bgPlayKeeper != null) return;
    // 即座に1回呼んでから Timer 開始 (初回応答を早くする)
    _forceVideoPlay();
    // 200ms 間隔: Android WebView が pause を仕掛けてくる頻度より
    // 短くしないと、瞬間的に音が途切れる。バッテリー消費は paused
    // 中だけなので前面動作中の影響なし。
    _bgPlayKeeper = Timer.periodic(const Duration(milliseconds: 200), (_) {
      _forceVideoPlay();
    });
  }

  void _stopBgPlayKeeper() {
    _bgPlayKeeper?.cancel();
    _bgPlayKeeper = null;
  }

  /// YouTube 検索クエリ文字列を `m.youtube.com/results?search_query=...`
  /// にエンコードして遷移する。検索ボックス submit から呼ばれる。
  /// 空文字なら何もしない (フォーカスを外す程度)。
  void _runYoutubeSearch(String query) {
    final q = query.trim();
    if (q.isEmpty) return;
    // URL エンコード (日本語クエリも安全に渡せる)
    final encoded = Uri.encodeQueryComponent(q);
    // ユーザーがアプリで選んだ言語に合わせて hl=/gl= を付与する。
    final provider = context.read<MindMapProvider>();
    final url = provider.localizeYoutubeUrl(
        'https://m.youtube.com/results?search_query=$encoded');
    // 検索ページに遷移。playlist にも反映 (前後ボタン押下で履歴に戻れる)。
    setState(() {
      _playlist = [url];
      _playlistIndex = 0;
    });
    _navigateTo(url);
    // キーボードを閉じる
    FocusScope.of(context).unfocus();
  }

  /// WebView 内の <video> が paused かつユーザー意図でないなら play()。
  /// さらに WebView 自体も Android の onPause 状態から resume させる。
  /// (Activity onPause で InAppWebView 内部が WebView を pause する仕様への
  ///  対策。controller.android.resume() で再度動かす。)
  ///
  /// YouTube 動画の場合: YouTube プレーヤーは Page Visibility API を見て
  /// document.hidden が true になると自動で pause する仕様。これを防ぐため
  /// document.hidden / visibilityState を常に visible に偽装する JS を
  /// 毎回注入する (ページ遷移で偽装が消える可能性に備えて 200ms ごとに再注入)。
  void _forceVideoPlay() {
    final c = _c;
    if (c == null) return;
    // 1. WebView 自体を resume (Android 内部の WebView.onResume()) 。
    //    これがないと evaluateJavascript すら走らないことがある。
    try {
      c.android.resume().catchError((_) {});
    } catch (_) {
      // iOS / 古い API バージョンでは利用不可
    }
    // 2. Page Visibility API を偽装 + <video>.play() 強制 + YouTube 内部の
    //    プレーヤー API も叩く (HTML5 player の 'play' メソッドを直接呼ぶ)
    c.evaluateJavascript(source: r'''
      (function() {
        try {
          // ── (A) Page Visibility 偽装 ──
          // YouTube は document.hidden / visibilityState を監視して、
          // hidden になると自動で pause する。これを常に visible と
          // 思わせることで、バックグラウンド遷移時の自動 pause を防ぐ。
          // 既に偽装済みかチェック (二重定義は throw する) して未偽装なら適用。
          if (!window.__MM_VISIBILITY_PATCHED__) {
            try {
              Object.defineProperty(document, 'hidden', {
                configurable: true, get: function() { return false; }
              });
              Object.defineProperty(document, 'visibilityState', {
                configurable: true, get: function() { return 'visible'; }
              });
              Object.defineProperty(document, 'webkitHidden', {
                configurable: true, get: function() { return false; }
              });
              Object.defineProperty(document, 'webkitVisibilityState', {
                configurable: true, get: function() { return 'visible'; }
              });
              // visibilitychange イベントの dispatch を抑制 (これが発火
              // すると YouTube がリスナー内で pause を呼ぶため)
              var origAdd = EventTarget.prototype.addEventListener;
              EventTarget.prototype.addEventListener = function(type, listener, opts) {
                if (type === 'visibilitychange' || type === 'webkitvisibilitychange') {
                  // YouTube が登録するリスナーは無視 (= 視認状態変化を通知しない)
                  return;
                }
                return origAdd.call(this, type, listener, opts);
              };
              window.__MM_VISIBILITY_PATCHED__ = true;
            } catch(e) {}
          }
          // ── (B) <video> 要素を play() に戻す ──
          // 終了済み (ended) の動画は play() すると先頭から再生され、
          // 「勝手にループする回がある」 原因になっていた (= ユーザー報告)。
          // 再生位置が末尾に達しているものは触らない。
          var vs = document.querySelectorAll('video');
          for (var i = 0; i < vs.length; i++) {
            var v = vs[i];
            if (v.ended) continue;
            if (v.duration && isFinite(v.duration) &&
                v.currentTime >= v.duration - 0.35) {
              continue;
            }
            if (v.paused && !window.__MM_USER_PAUSED__) {
              v.play().catch(function(){});
            }
          }
        } catch(e) {}
      })();
    ''').catchError((_) {});
  }

  /// バックグラウンド再生用 Foreground Service を起動する。
  /// バックグラウンド再生 ON の時だけ動画再生開始時に呼ばれる。
  /// 通知バーに常駐通知を出す代わりに、Activity が onStop で完全停止
  /// しないため、画面オフでも WebView の音声再生が継続する。
  /// (audio_service ベースの新実装)
  Future<void> _initAndStartForegroundService() async {
    // 多言語対応の通知ラベルを設定してから Service 起動。
    // 既起動の場合は既存ハンドラーの mediaItem も自動更新される。
    if (mounted) {
      try {
        final provider = context.read<MindMapProvider>();
        _BgPlaybackController.setLabels(
          channelName: provider.t('bg.notificationChannelName'),
          channelDesc: provider.t('bg.notificationChannelDesc'),
          notifTitle: provider.t('bg.notificationTitle'),
          notifArtist: provider.t('bg.notificationArtist'),
        );
      } catch (_) {}
    }
    await _BgPlaybackController.start();
  }

  /// Foreground Service を停止する。動画ページを閉じるときに呼ぶ。
  Future<void> _stopForegroundService() async {
    await _BgPlaybackController.stop();
  }

  /// URL を解析して _isYoutube / _isMp4 / _currentVideoId を更新する（同期版）
  ///
  /// 【ユーザー報告 (2026-05) のバグ修正】
  /// mp4 はまず WebView を `about:blank` で起動 → `loadData(html)` で
  /// インラインプレイヤー HTML を流し込む方式。それまでに onLoadStart /
  /// onLoadStop / onUpdateVisitedHistory が `about:blank` や `data:...` の
  /// URL でこの関数を呼ぶ。素直に処理すると `_isMp4 = false` に上書きされ、
  /// build() の `isVideo = _isYoutube || _isMp4` が false になり：
  ///   1. 上部の再生バー (速度スライダー) が消える
  ///   2. onLoadStop の `else if (_isMp4)` ブランチに入らないため
  ///      `_injectPlaybackRate()` も呼ばれない
  /// 結果ユーザーは native の `<video controls>` UI でしか速度変更できず、
  /// それは最大 2x までだった。
  ///
  /// 修正: 過渡的 URL (`about:blank` / `data:...` / 空) では state を保持し、
  /// 実コンテンツ URL (initState の `widget.url` か、playlist 遷移後の URL)
  /// だけで `_isMp4` 等を更新する。
  void _analyzeUrlSync(String url) {
    // 過渡的 URL は無視 (上記コメント参照)。
    // 例外: `_currentUrl` はナビゲーション履歴のために最新 URL を反映したい
    // 場面もあるが、当 State では `_currentUrl` を主にローカル動画ファイル
    // パスや YouTube watch URL の判定に使うため、過渡的 URL を入れない方が
    // 整合性が取れる (= 既存値を維持する)。
    if (url.isEmpty || url == 'about:blank' || url.startsWith('data:')) {
      return;
    }
    // ── YouTube 内の広告 / トラッキング URL を無視 ──
    // YouTube動画再生中、広告セッションや計測スクリプトのために WebView
    // が一瞬これらのドメインに遷移することがあり、その瞬間に `_currentUrl`
    // が動画 URL から書き換わって埋め込みボタンが消える現象が起きる。
    // これらは動画ページの裏で動く中間 URL なので、ユーザーが意図した
    // ナビゲーションではない → `_currentUrl` を維持する (= 既存値そのまま)。
    if (url.contains('googleadservices.com') ||
        url.contains('googlesyndication.com') ||
        url.contains('doubleclick.net') ||
        url.contains('googletagservices.com') ||
        url.contains('googletagmanager.com') ||
        url.contains('google-analytics.com')) {
      return;
    }
    _currentUrl = url;
    _isYoutube = url.contains('youtube.com') || url.contains('youtu.be');
    // 「動画ページ」 を判定して _lastWatchedVideoUrl を更新する。
    // YouTube の動画ページは /watch?v=, youtu.be/ID, /shorts/ID のいずれか。
    // 検索結果 (/results?...) やトップページなどは含めない。 これにより
    // 「動画リロード」 ボタンを押した時に「直近視聴した動画」 へ戻れる
    // (広告で詰まった時の脱出経路)。
    if (_isYoutube) {
      final isVideoPage = url.contains('/watch?v=') ||
          url.contains('youtu.be/') ||
          url.contains('/shorts/');
      if (isVideoPage) {
        _lastWatchedVideoUrl = url;
      }
    } else {
      // 非 YouTube はそのまま記憶 (mp4 / 一般リンクなど)
      _lastWatchedVideoUrl = url;
    }
    // _isMp4 は「インラインの動画プレイヤー HTML で扱うべきローカル/HTTP の
    // 動画ファイル」を意味する。NodeWidget.isMp4Url は .mp4/.m4v/.mov のみを
    // 対象にしているが、YouTube ダウンロード経由で保存される動画は muxed
    // の container に応じて .webm になることもある。さらに、speed slider /
    // playbackRate スクリプト注入は `_isMp4` の経路でしか走らないため、
    // ここで .webm 等も含めて広めに判定して、ダウンロード済みノードでも
    // 1.0x〜5.0x (provider.videoMaxRate 上限) のスライダーが効くようにする。
    _isMp4 =
        !_isYoutube && (NodeWidget.isMp4Url(url) || _isLocalPlayableVideo(url));
    _currentVideoId = _extractVideoId(url);
  }

  /// `<video>` タグで再生できる代表的なローカル動画拡張子を判定する。
  /// `NodeWidget.isMp4Url` の補完として使う。
  /// 含めるもの: webm (YouTube ダウンロードの一部) / ogv / 3gp。
  /// mkv / avi / flv は WebView の `<video>` で再生できないため除外。
  bool _isLocalPlayableVideo(String url) {
    final lower = url.toLowerCase();
    // クエリ/フラグメントを除去
    var path = lower;
    final qi = path.indexOf('?');
    if (qi >= 0) path = path.substring(0, qi);
    final hi = path.indexOf('#');
    if (hi >= 0) path = path.substring(0, hi);
    return path.endsWith('.webm') ||
        path.endsWith('.ogv') ||
        path.endsWith('.ogg') ||
        path.endsWith('.3gp');
  }

  /// 指定 URL に対応するロードターゲット URL を返す。
  ///
  /// 【YouTube 動画の場合】
  /// 公式の `m.youtube.com/watch?v=VIDEO_ID` を直接ロードする。
  ///
  /// 以前は `youtube-nocookie.com/embed/VIDEO_ID` を使っていたが、
  /// 一部の動画 (埋め込み再生を制限しているチャンネル) でエラー153
  /// "このビデオをここで再生することはできません" 画面が表示されて
  /// しまい、ユーザーが追加で「YouTubeで視聴」ボタンを押す必要が
  /// あった。通常の watch URL なら元々 YouTube 上で再生する形なので
  /// 埋め込み制限の影響を受けない (Windows 版 _WindowsWebViewSheet
  /// も同じ理由で watch URL を使用している)。
  ///
  /// UI の「関連動画／コメント／ヘッダー」等は、動画再生ページ判定
  /// (onLoadStop 内) でフォーカスモード CSS を注入して隠しているため、
  /// 見た目は従来と変わらない。
  ///
  /// 視聴位置の復元は `&t=<秒>` クエリパラメータで指定。
  /// 加えて JS 側の _restorePosition でも seek を試みる二重体制。
  ///
  /// 【一般 URL の場合】
  /// そのまま返す。(mp4 はこの関数の守備範囲外。HTML 文字列で loadData する)
  String _computeLoadTargetUrl(String url) {
    if (_isYoutube && _currentVideoId != null) {
      // ── start 秒数の決定 (優先順位) ──
      // 1. widget.initialPosition (= メモのハイパーリンクからのジャンプ等で
      //    呼び出し側が明示指定した時刻) を最優先する。 これが指定されて
      //    いるとき、 savedSec で上書きすると「タイムスタンプをタップしたのに
      //    0 秒や前回視聴位置に飛ばされる」 という旧バグになる。
      // 2. 元 URL に `&t=Xs` が既に含まれていればそれを尊重 (呼び出し側が
      //    URL を組み立てて渡した場合への対応)。
      // 3. 上記いずれも無ければ Provider に保存された前回視聴位置。
      int startSec = 0;
      if (widget.initialPosition > 0.5) {
        startSec = widget.initialPosition.round();
      } else {
        // 元 URL に t= があるか抽出
        final m = RegExp(r'[?&]t=(\d+)').firstMatch(url);
        if (m != null) {
          startSec = int.tryParse(m.group(1)!) ?? 0;
        }
        if (startSec == 0) {
          final savedSec = context
              .read<MindMapProvider>()
              .getVideoPosition(_currentVideoId!)
              .round();
          if (savedSec > 5) startSec = savedSec;
        }
      }
      final buf = StringBuffer('https://m.youtube.com/watch?v=')
        ..write(_currentVideoId);
      if (startSec > 0) buf.write('&t=${startSec}s');
      return buf.toString();
    }
    return url;
  }

  /// メモの内容で YouTube を検索し、 今見ている画面を検索結果に切り替える
  /// (= ユーザー要望: Google 検索ボタンの隣に YouTube 検索も欲しい)。
  void _openVideoMemoInYoutubeSearch(_VideoMemoEntry entry) {
    final text = entry.text.trim();
    if (text.isEmpty) return;
    final url = 'https://m.youtube.com/results?search_query='
        '${Uri.encodeQueryComponent(text)}';
    // ignore: discarded_futures
    _navigateTo(url);
  }

  /// 指定 URL に遷移する（プレイリストの次・前・再読み込み用）
  Future<void> _navigateTo(String url) async {
    _analyzeUrlSync(url);
    if (mounted) {
      setState(() {
        _loading = true;
        _currentTitle = '';
      });
    }
    final c = _c;
    if (c == null) return;
    try {
      if (_isMp4) {
        // mp4 / ローカル動画は WebView の `<video>` 経路で再生する
        // (initState のコメント参照)。プレイリスト遷移時はここで HTML を
        // 再生成して loadData。
        final html = await _buildMp4PlayerRaw(url);
        await c.loadData(data: html, mimeType: 'text/html', encoding: 'utf-8');
      } else {
        final target = _computeLoadTargetUrl(url);
        await c.loadUrl(urlRequest: iaw.URLRequest(url: iaw.WebUri(target)));
      }
    } catch (e) {
      debugPrint('_navigateTo failed: $e');
    }
  }

  /// 動画再読み込みボタンの動作。
  ///
  /// 通常の WebView リロード (= `c.reload()`) だと、 検索結果ページなど
  /// 動画でないページにいる場合は「同じ動画を再読み込み」 ができない。
  /// このメソッドは:
  ///   - 直近で視聴していた動画 URL を `_lastWatchedVideoUrl` から取得
  ///   - そこに戻る (= cookie をクリアせずに動画自体を再ロード)
  ///   - `_lastWatchedVideoUrl` が無ければ通常の `reload()` にフォールバック
  ///
  /// これで「検索結果 → 動画再生中に広告で詰まる → 動画リロードで広告を
  /// スキップ」 という運用ができる。 検索結果ページに戻されない。
  Future<void> _reloadCurrentVideo() async {
    final c = _c;
    if (c == null) return;
    final lastVideo = _lastWatchedVideoUrl;
    if (lastVideo != null && lastVideo.isNotEmpty) {
      // 直近視聴動画に戻る (これにより広告ステートをリセット)
      await _navigateTo(lastVideo);
    } else {
      // 直近動画が無ければ普通の reload
      try {
        await c.reload();
      } catch (e) {
        debugPrint('reload failed: $e');
      }
    }
  }

  /// ホーム / 検索 / チャンネル等、動画ではない YouTube 画面をその場で更新。
  /// 動画用の「直近動画へ戻る」処理とは分け、現在の閲覧位置を維持する。
  Future<void> _reloadCurrentYoutubePage() async {
    final c = _c;
    if (c == null) return;
    try {
      if (mounted) setState(() => _loading = true);
      await c.reload();
    } catch (e) {
      debugPrint('YouTube page reload failed: $e');
    }
  }

  String? _extractVideoId(String url) {
    for (final p in [
      RegExp(r'youtu\.be/([a-zA-Z0-9_-]{11})'),
      RegExp(r'youtube\.com/watch\?.*v=([a-zA-Z0-9_-]{11})'),
      RegExp(r'youtube\.com/embed/([a-zA-Z0-9_-]{11})'),
      RegExp(r'youtube\.com/shorts/([a-zA-Z0-9_-]{11})'),
    ]) {
      final m = p.firstMatch(url);
      if (m != null) return m.group(1);
    }
    return null;
  }

  /// 現在URLが YouTube の動画 or チャンネルなら true
  bool _isEmbeddableYoutubeUrl(String url) {
    if (url.isEmpty) return false;
    if (_extractVideoId(url) != null) return true;
    if (RegExp(r'youtube\.com/@[A-Za-z0-9._-]+').hasMatch(url)) return true;
    if (RegExp(r'youtube\.com/channel/[A-Za-z0-9_-]+').hasMatch(url))
      return true;
    if (RegExp(r'youtube\.com/c/[A-Za-z0-9._-]+').hasMatch(url)) return true;
    if (RegExp(r'youtube\.com/user/[A-Za-z0-9._-]+').hasMatch(url)) return true;
    // プレイリスト URL (m.youtube.com / www.youtube.com 両対応)
    if (RegExp(r'youtube\.com/playlist\?').hasMatch(url) &&
        RegExp(r'[?&]list=[A-Za-z0-9_-]+').hasMatch(url)) {
      return true;
    }
    return false;
  }

  /// mp4 をインライン HTML プレイヤーでラップする。
  /// Android WebView が file:// をブロックした場合は JS から Base64 変換
  /// リクエスト (FlutterFallback handler) を送ってもらう仕組み。
  Future<String> _buildMp4PlayerRaw(String url) async {
    String videoSrc;
    if (!url.startsWith('http') &&
        !url.startsWith('data:') &&
        !url.startsWith('file://')) {
      final normalized = url.replaceAll(r'\', '/');
      videoSrc = normalized.startsWith('/')
          ? 'file://$normalized'
          : 'file:///$normalized';
    } else {
      videoSrc = url;
    }
    final escaped = videoSrc.replaceAll('"', '&quot;');
    // ── controlslist="noplaybackrate" について ──
    // 標準の `<video controls>` UI に含まれる「再生速度」セレクタは
    // 0.25/0.5/.../1.5/2.0 までしか選べない (= ユーザー報告「2倍速までしか
    // 見れない」の正体)。一方、当アプリは上部の Flutter スライダーから
    // 1.0x〜provider.videoMaxRate (既定5.0、最大16x) を直接 `playbackRate`
    // に当てる仕組み。両方残すとユーザーが native UI の 2x 制限を見て
    // 「これが上限」と勘違いするので、`noplaybackrate` で native の速度
    // セレクタを非表示にする。再生バー本体 (時間 / 一時停止 / 全画面など)
    // は残す。
    final initialRateJs = _playbackRate.toString();
    // 初期再生位置 (秒)。PiP からフルスクリーンに復帰した場合は
    // widget.initialPosition に最終再生位置が入っている。0 ならシーク無し。
    final initialPosJs = widget.initialPosition.toString();
    // 左右キーのシーク秒数 (= ユーザー設定。 既定 10 秒)。 ここまで await が
    // 無いので context.read は安全 (非同期ギャップ前)。
    final seekStepJs =
        context.read<MindMapProvider>().videoSeekSeconds.toString();
    final html = '''<!DOCTYPE html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>*{margin:0;padding:0;background:#000;}html,body{width:100%;height:100%;overflow:hidden;}
video{width:100%;height:100%;object-fit:contain;display:block;}
#loading{color:#888;font-size:14px;position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-family:sans-serif;}
</style></head><body>
<div id="loading">読み込み中...</div>
<video id="v" controls controlslist="nodownload noplaybackrate noremoteplayback" disablepictureinpicture autoplay playsinline src="$escaped">
  <source src="$escaped" type="video/mp4">
</video>
<script>
var v=document.getElementById('v');
var ld=document.getElementById('loading');
// 当 State から渡された初期速度を window 共有変数にも入れて、
// _injectPlaybackRate より早いタイミング (canplay) でも反映できるようにする
window.__MM_RATE__ = $initialRateJs;
// PiP→フルスクリーン復帰時の続き再生用。loadedmetadata で currentTime にセット。
window.__MM_INIT_POS__ = $initialPosJs;
var __mm_seeked = false;
function applyMyRate(){
  try { if (typeof window.__MM_RATE__==='number') v.playbackRate = window.__MM_RATE__; } catch(e){}
}
function applyInitialPos(){
  if (__mm_seeked) return;
  try {
    if (typeof window.__MM_INIT_POS__==='number' && window.__MM_INIT_POS__ > 0.5) {
      v.currentTime = window.__MM_INIT_POS__;
      __mm_seeked = true;
    }
  } catch(e){}
}
v.addEventListener('loadedmetadata', function(){
  applyInitialPos();
  applyMyRate();
});
v.addEventListener('canplay',function(){ld.style.display='none'; applyMyRate();});
v.addEventListener('play', applyMyRate);
// native UI が裏で速度を書き戻してきたら即座に当アプリ指定値へ復元
v.addEventListener('ratechange', function(){
  try {
    var r = window.__MM_RATE__;
    if (typeof r==='number' && Math.abs(v.playbackRate - r) > 0.001) {
      v.playbackRate = r;
    }
  } catch(e){}
});
// ── 左右キーでのシーク (= ユーザー要望: 飛ぶ秒数を固定 + 設定可能に) ──
// 標準 <video controls> の組み込みシーク (~5秒/まちまち) を上書きし、
// アプリ設定の秒数 (__MM_SEEK__) でシークする。capture フェーズ +
// preventDefault でブラウザ既定のシークを抑止。テキスト入力中は無効。
window.__MM_SEEK__ = $seekStepJs;
document.addEventListener('keydown', function(e){
  try {
    var t = e.target;
    // テキスト入力中だけスキップ。 ネイティブ <video> のシークバー
    // (input type=range) は除外しない (= ユーザー要望: シークバーにフォーカス
    // があると割合ベースの「変な秒数」 でシークしてしまうのを防ぎ、 常に固定
    // 秒数でシークさせる)。
    if (t && ((t.tagName==='INPUT' && t.type!=='range') || t.tagName==='TEXTAREA' || t.isContentEditable)) return;
    var step = window.__MM_SEEK__ || 5;
    if (e.key==='ArrowRight' || e.keyCode===39) {
      v.currentTime = Math.min((v.duration||1e9), v.currentTime + step);
      e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation();
    } else if (e.key==='ArrowLeft' || e.keyCode===37) {
      v.currentTime = Math.max(0, v.currentTime - step);
      e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation();
    }
  } catch(err){}
}, true);
v.addEventListener('error',function(){
  ld.textContent='再生準備中...';
  try {
    if (window.flutter_inappwebview) {
      window.flutter_inappwebview.callHandler('FlutterFallback','needBase64');
    }
  } catch(e) {}
});
setTimeout(function(){ld.style.display='none';},5000);

// ── MediaSession API ──
// Android の WebView でこの API を呼ぶと「メディアを再生中のアプリ」
// として OS に登録され、画面オフ後もバックグラウンド再生が許可されやすく
// なる。ロック画面に再生コントロール (play/pause/seek) も表示される。
// 対応: Chrome 73+ (WebView の根幹なので Android 7.0+ ならほぼ動く)。
if ('mediaSession' in navigator) {
  try {
    navigator.mediaSession.metadata = new MediaMetadata({
      title: 'Mindmap Video',
      artist: 'マインドマップアプリ',
    });
    navigator.mediaSession.setActionHandler('play', function() {
      try { v.play().catch(function(){}); } catch(e){}
    });
    navigator.mediaSession.setActionHandler('pause', function() {
      try { v.pause(); window.__MM_USER_PAUSED__ = true; } catch(e){}
    });
    navigator.mediaSession.setActionHandler('seekbackward', function() {
      try { v.currentTime = Math.max(0, v.currentTime - 10); } catch(e){}
    });
    navigator.mediaSession.setActionHandler('seekforward', function() {
      try { v.currentTime = v.currentTime + 10; } catch(e){}
    });
  } catch(e) {}
}
// ── バックグラウンド再生継続 ──
// Android の WebView は Activity が onStop に入ると `<video>` を自動で
// pause する仕様。これを上書きするため、pause / visibilitychange イベントで
// 「ユーザーが pause したかどうか」を判定して、ユーザーの意図でないなら
// 即座に play() を呼び直して再生を継続する。
//
// `__MM_USER_PAUSED__`: ユーザーが UI から pause したかのフラグ。
//   pause ボタンクリックで true、play ボタンクリックで false。
// `__MM_BG_RESUME__`: visibility が hidden の時の自動 resume 機能。
//   true = OS が pause したら自動で再開、false = 何もしない (ユーザー pause)。
window.__MM_USER_PAUSED__ = false;
window.__MM_BG_RESUME__ = true;
// ── ユーザー操作直後フラグ ──
// 「動画を手動で止めても画面オフでバックグラウンド再生が始まる」問題への対応。
// 旧実装は「2 秒以内に 2 回 pause が来たらユーザー意図」という曖昧判定で、
// 1 回だけ pause した直後に画面オフ → OS が再度 pause → 自動 play() の流れで
// 勝手に再生が再開してしまっていた。
//
// 新実装: pointerdown / mousedown / keydown / click を WINDOW LEVEL で
// listen しておき、最後にユーザー操作があった時刻を記録。pause イベントが
// 来た時、直前 1500ms 以内にユーザー操作があれば即座に「ユーザー pause」
// として確定する (= 1 回 pause しただけでフラグが立つ)。
window.__MM_LAST_USER_INTERACTION__ = 0;
(function() {
  function markInteraction() {
    window.__MM_LAST_USER_INTERACTION__ = Date.now();
  }
  // capture phase で拾う (各種 stopPropagation で潰されないように)
  var evts = ['pointerdown', 'mousedown', 'touchstart', 'keydown', 'click'];
  for (var i = 0; i < evts.length; i++) {
    try {
      window.addEventListener(evts[i], markInteraction, true);
    } catch (e) {}
  }
})();
v.addEventListener('pause', function() {
  // ── ユーザー意図判定 (新ロジック) ──
  // 直前 1500ms 以内にユーザー操作があった = ユーザーが pause ボタンを
  // 押した可能性が極めて高い。即座にフラグを立てて以降の自動 play を抑制。
  var sinceUI = Date.now() - (window.__MM_LAST_USER_INTERACTION__ || 0);
  if (sinceUI < 1500) {
    window.__MM_USER_PAUSED__ = true;
    return;  // 自動 play しない
  }
  // OS / Activity onStop による pause を検出: ユーザー操作と無関係なら
  // 即座に play() を呼んで継続再生。
  // 終了した動画は再開しない (= 勝手にループする回がある問題の修正)
  if (v.ended) return;
  if (window.__MM_BG_RESUME__ && !window.__MM_USER_PAUSED__) {
    setTimeout(function(){
      if (v.paused && !v.ended && !window.__MM_USER_PAUSED__) {
        try { v.play().catch(function(){}); } catch(e){}
      }
    }, 50);
  }
});
// visibility (タブ非表示 / ロック画面遷移) 変更でも継続再生
document.addEventListener('visibilitychange', function() {
  if (window.__MM_BG_RESUME__ && !window.__MM_USER_PAUSED__ &&
      v.paused && !v.ended) {
    try { v.play().catch(function(){}); } catch(e){}
  }
});
v.addEventListener('play', function() {
  // play されたらユーザー pause フラグ解除
  window.__MM_USER_PAUSED__ = false;
});
</script>
</body></html>''';
    return html;
  }

  /// フォーカスモード CSS を注入。
  /// [force] = true は UI 非表示ボタン経由 (= hideEmbedRelated 設定に
  /// 関わらず動画以外を隠す。 ユーザー要望 2026-07)。
  Future<void> _injectStyle({bool force = false}) async {
    // ── 関連動画等を隠す設定が OFF なら CSS を入れない (= ユーザー要望) ──
    // ただし UI 非表示ボタンで隠している間 (_uiHiddenCssApplied) は、
    // watch→watch の SPA 遷移で通常経路の _injectStyle() が走っても
    // 剥がさない (= 非表示のまま次の動画へ移っても隠れ続ける)。
    // ── ページ内コンテンツ(ノード)からの動画は常にフォーカス表示 ──
    // focusMode==true (= ノードの動画を開いた) 時は、hideEmbedRelated 設定に
    // 関わらず必ず関連動画/コメント等を隠して動画を中央に配置する
    // (= ユーザー要望 2026-07)。再生速度/シークバー等のプレイヤー操作は
    // _focusModeCSS 側で残している。ブラウズ起動 (focusMode:false) は素の
    // YouTube UI を保ちたいので、その場合のみ従来どおり設定を尊重する。
    try {
      if (!force &&
          !_uiHiddenCssApplied &&
          !widget.focusMode &&
          !context.read<MindMapProvider>().hideEmbedRelated) {
        await _removeStyle();
        return;
      }
    } catch (_) {}
    final css = _focusModeCSS.replaceAll('\n', ' ').replaceAll("'", "\\'");
    await _c?.evaluateJavascript(source: '''
      (function(){
        var id="__MM_FS_STYLE__";
        if(document.getElementById(id))return;
        var s=document.createElement("style");
        s.id=id;s.textContent='$css';
        (document.head||document.documentElement).appendChild(s);
      })();
    ''');
    await _syncHiddenYoutubeVideoAlignment();
  }

  /// アプリ側 UI を隠している間だけ、YouTube プレイヤーを画面上部へ寄せる。
  /// 横方向は既存の stretch / center を維持するため、通常動画も Shorts も
  /// 上部中央に収まり、UI を戻すと従来の垂直中央へ復帰する。
  Future<void> _syncHiddenYoutubeVideoAlignment() async {
    if (!_isYoutube) return;
    final alignment = _hideAllControls ? 'flex-start' : 'center';
    final scrollToTop = _hideAllControls ? 'window.scrollTo(0, 0);' : '';
    try {
      await _c?.evaluateJavascript(source: '''
        (function() {
          try {
            document.documentElement.style.setProperty(
              '--mm-video-y-align', '$alignment');
            $scrollToTop
          } catch (e) {}
        })();
      ''');
    } catch (_) {}
  }

  /// フォーカスモード CSS を撤去する。
  ///
  /// 【背景】
  /// YouTube は SPA で動くため、watch ページから検索結果やホーム、チャンネル
  /// ページに遷移しても document.head は維持される。`_injectStyle()` が貼った
  /// `<style id="__MM_FS_STYLE__">` がそのまま残ると、CSS が `#mobile-topbar`
  /// `header` `ytm-mobile-topbar-renderer` 等を `display:none` で隠している
  /// ため、移動先のページで検索ボックスやヘッダーが操作不能になる。
  ///
  /// 【ユーザー報告】
  /// 「YouTubeの動画を埋め込まずに視聴している状態で検索ボックスに触れて
  ///   しまうと何故かCSSが非表示になって操作できなくなる」
  /// → watch ページで貼った CSS が検索ページにも残って search box を隠して
  ///   いるため、タップしても入力できないし表示も崩れて見える、という現象。
  ///
  /// 【対応】watch 以外のページ (検索 / ホーム / チャンネル / 一般 URL) に
  /// 遷移したタイミングで `__MM_FS_STYLE__` を DOM から削除する。次に watch
  /// ページに戻った時には `_injectStyle()` が再度貼り直すので問題なし。
  Future<void> _removeStyle() async {
    try {
      await _c?.evaluateJavascript(source: '''
        (function(){
          try {
            var s=document.getElementById("__MM_FS_STYLE__");
            if(s) s.parentNode && s.parentNode.removeChild(s);
            document.documentElement.style.removeProperty('--mm-video-y-align');
          } catch(e) {}
        })();
      ''');
    } catch (_) {}
  }

  // ─── 動画ダウンロード ──────────────────────────────────────────────────
  //
  // 端末のドキュメントフォルダ配下 `Downloads/` に保存。
  // - mp4 直リンク: `http.get` で取得して書き出し (既存の添付ダウンロードと
  //   同じパターン)。
  // - YouTube: 著作権/規約リスクを避けるため、リリース版では端末保存しない。
  //
  // 進捗は受信バイト数を SnackBar 内 Text に流して可視化する。
  // 完了後は SnackBar の「開く」アクションから OpenFilex で開ける。

  /// ファイル名に使えない文字を `_` に置換し、長さも適度にトリム。
  /// 単発 DL 用の sanitize。一括版と同じ理由で ASCII 範囲のみ残す。
  String _sanitizeFilename(String name) {
    var s = name
        .replaceAll(RegExp(r'[<>:"/\\|?*\x00-\x1F]'), '_')
        // ASCII 範囲外 (CJK / 全角記号 / 絵文字) を `_` に
        .replaceAll(RegExp(r'[^\x20-\x7E]'), '_')
        .trim()
        .replaceAll(RegExp(r'\s+'), '_')
        .replaceAll(RegExp(r'_+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
    if (s.length > 60) s = s.substring(0, 60);
    if (s.isEmpty) s = 'video';
    return s;
  }

  /// 同名ファイルが既に存在する場合は `_1`, `_2` のサフィックスを付ける。
  String _ensureUniquePath(String path) {
    if (!File(path).existsSync()) return path;
    final dot = path.lastIndexOf('.');
    final stem = dot >= 0 ? path.substring(0, dot) : path;
    final ext = dot >= 0 ? path.substring(dot) : '';
    for (var i = 1; i < 1000; i++) {
      final candidate = '${stem}_$i$ext';
      if (!File(candidate).existsSync()) return candidate;
    }
    return path;
  }

  /// バイト数を人間に読みやすい文字列にする (1.2 MB / 345 KB 等)。
  String _humanBytes(int bytes) {
    if (bytes < 1024) return '$bytes B';
    if (bytes < 1024 * 1024) {
      return '${(bytes / 1024).toStringAsFixed(1)} KB';
    }
    if (bytes < 1024 * 1024 * 1024) {
      return '${(bytes / 1024 / 1024).toStringAsFixed(1)} MB';
    }
    return '${(bytes / 1024 / 1024 / 1024).toStringAsFixed(2)} GB';
  }

  /// YouTube の CDN サムネ (sd → hq) を取得してローカル保存する。
  /// MindMapScreenState の同名メソッドの State 版コピー (こちらは
  /// _FullscreenVideoPage の State から呼ばれる)。
  /// 成功で保存先パス、失敗で null。
  Future<String?> _downloadYoutubeThumbnailLocal(
      String videoId, Directory baseDir) async {
    final urls = [
      'https://i.ytimg.com/vi/$videoId/sddefault.jpg',
      'https://i.ytimg.com/vi/$videoId/hqdefault.jpg',
    ];
    final thumbDir =
        Directory('${baseDir.path}${Platform.pathSeparator}video_thumbs');
    try {
      if (!await thumbDir.exists()) {
        await thumbDir.create(recursive: true);
      }
    } catch (_) {
      return null;
    }
    final outPath = '${thumbDir.path}${Platform.pathSeparator}yt_$videoId.jpg';
    for (final url in urls) {
      try {
        final resp =
            await http.get(Uri.parse(url)).timeout(const Duration(seconds: 15));
        if (resp.statusCode == 200 && resp.bodyBytes.isNotEmpty) {
          if (resp.bodyBytes.length < 1024) continue;
          await File(outPath).writeAsBytes(resp.bodyBytes);
          return outPath;
        }
      } catch (_) {}
    }
    return null;
  }

  /// 「ダウンロード中」SnackBar を出して、進捗テキストを更新できる
  /// コールバックを返す。完了 / 失敗時は `done()` を呼ぶ側で消す。
  ({
    void Function(String) update,
    void Function(double) setFraction,
    void Function() done
  }) _showDownloadProgress(String initialText) {
    final scaffold = ScaffoldMessenger.of(context);
    scaffold.hideCurrentSnackBar();
    final notifier = ValueNotifier<String>(initialText);
    // (= ユーザー要望: ダウンロードの進行が分かるよう割合を表示。 円形ゲージを
    //  進捗値で塗りつぶし、 中央に % 数値を出す。)
    final fracNotifier = ValueNotifier<double>(0.0);
    _appSnackM(
        scaffold,
        SnackBar(
          content: Row(children: [
            ValueListenableBuilder<double>(
              valueListenable: fracNotifier,
              builder: (_, v, __) => SizedBox(
                width: 32,
                height: 32,
                child: Stack(alignment: Alignment.center, children: [
                  CircularProgressIndicator(
                    value: (v <= 0 || v > 1) ? null : v,
                    strokeWidth: 3,
                    color: Colors.white,
                    backgroundColor: Colors.white24,
                  ),
                  Text('${(v.clamp(0.0, 1.0) * 100).round()}',
                      style: const TextStyle(
                          fontSize: 9,
                          color: Colors.white,
                          fontWeight: FontWeight.bold)),
                ]),
              ),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: ValueListenableBuilder<String>(
                valueListenable: notifier,
                builder: (_, text, __) => Text(text,
                    overflow: TextOverflow.ellipsis,
                    maxLines: 2,
                    style: const TextStyle(fontSize: 12)),
              ),
            ),
          ]),
          // ダウンロード中はずっと出しておく (完了時に手動で消す)
          duration: const Duration(hours: 1),
          backgroundColor: const Color(0xFF1E1E32),
        ));
    return (
      update: (s) => notifier.value = s,
      setFraction: (f) => fracNotifier.value = f,
      done: () => scaffold.hideCurrentSnackBar(),
    );
  }

  /// 現在再生中の動画 (mp4 / YouTube) を端末にダウンロードする。
  Future<void> _downloadCurrentVideo() async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final url = _currentUrl;
    final isYouTube = _isYoutube && _currentVideoId != null;
    final isMp4Direct = _isMp4;
    if (isYouTube) {
      _appSnack(
          context,
          SnackBar(
            content: Text(context.read<MindMapProvider>().t('dl.disabledRelease')),
            backgroundColor: const Color(0xFF2A2A3E),
          ));
      return;
    }
    if (!isYouTube && !isMp4Direct) {
      _appSnack(
          context,
          SnackBar(
            content: Text(provider.t('video.downloadUnsupported')),
            backgroundColor: const Color(0xFFE53935),
          ));
      return;
    }

    // 保存先ディレクトリ (アプリのドキュメント配下 / Downloads)
    Directory dlDir;
    try {
      final docs = await getApplicationDocumentsDirectory();
      dlDir = Directory('${docs.path}${Platform.pathSeparator}Downloads');
      if (!await dlDir.exists()) {
        await dlDir.create(recursive: true);
      }
    } catch (e) {
      if (!mounted) return;
      _appSnack(
          context,
          SnackBar(
            content: Text(context
                .read<MindMapProvider>()
                .t('store.saveDestFailed')
                .replaceFirst('{err}', '$e')),
            backgroundColor: const Color(0xFFE53935),
          ));
      return;
    }

    final progress = _showDownloadProgress(isYouTube
        ? provider.t('dl.preparingYoutube')
        : provider.t('dl.downloadingVideo'));

    String? savedPath;
    String? errorMsg;
    // ダウンロード完了後に _DownloadedVideosStore に書き込むメタ情報。
    // 成功時のみ使用。
    String dlTitle = '';
    int dlSizeBytes = 0;
    // YouTube CDN から取得したサムネ画像のローカルパス (取れた時)。
    // 埋め込み時に setVideoThumbnailPath で当てる。
    String? dlThumbPath;

    try {
      if (isMp4Direct) {
        // ── mp4 直リンク ──
        // http.Client.send でストリーム取得して進捗を表示
        final filename = _sanitizeFilename(
            url.split('/').last.split('?').first.split('#').first);
        // 拡張子が無ければ .mp4 を補う
        final fname = filename.contains('.') ? filename : '$filename.mp4';
        savedPath =
            _ensureUniquePath('${dlDir.path}${Platform.pathSeparator}$fname');
        // メタ情報用: タイトルはタイトル取得経路がないのでファイル名を使う
        dlTitle = _currentTitle.isNotEmpty ? _currentTitle : fname;

        final client = http.Client();
        try {
          final req = http.Request('GET', Uri.parse(url));
          final resp = await client.send(req);
          if (resp.statusCode != 200) {
            throw 'HTTP ${resp.statusCode}';
          }
          final total = resp.contentLength ?? 0;
          var received = 0;
          final sink = File(savedPath).openWrite();
          await for (final chunk in resp.stream) {
            sink.add(chunk);
            received += chunk.length;
            if (total > 0) {
              final pct = (received * 100 / total).toStringAsFixed(1);
              progress.update(
                  '$pct% (${_humanBytes(received)} / ${_humanBytes(total)})');
              progress.setFraction(received / total);
            } else {
              progress.update(_humanBytes(received));
            }
          }
          await sink.flush();
          await sink.close();
          dlSizeBytes = received;
        } finally {
          client.close();
        }
      } else {
        // ── YouTube ──
        // リリース前コンプライアンス方針に合わせ、YouTube 本体の端末保存は無効化。
        // mp4 直リンクの保存経路は上の isMp4Direct 枝で引き続き利用できる。
        throw 'YouTube動画の端末保存は無効化されています';
      }
    } catch (e) {
      errorMsg = '$e';
      debugPrint('Download error: $e');
      // 失敗時、書きかけのファイルは消す (ゴミを残さない)
      if (savedPath != null) {
        try {
          final f = File(savedPath);
          if (await f.exists()) await f.delete();
        } catch (_) {}
        savedPath = null;
      }
    }

    progress.done();
    if (!mounted) return;

    final scaffold = ScaffoldMessenger.of(context);
    if (savedPath != null && errorMsg == null) {
      final filename = savedPath.split(Platform.pathSeparator).last;

      // ── 永続化: ダウンロード一覧 (SharedPreferences) に登録 ──
      // 一覧は MindMapScreen 側の右クリックメニュー / 3 点メニュー
      // から開くダイアログで参照される。
      final record = <String, dynamic>{
        'path': savedPath,
        'title': dlTitle,
        'sourceUrl': url,
        'videoId': _currentVideoId,
        'sizeBytes': dlSizeBytes,
        'downloadedAt': DateTime.now().millisecondsSinceEpoch,
        // CDN サムネが取れていれば一緒に保存。埋め込み側 (=
        // _defaultEmbedDownloadedVideo) で setVideoThumbnailPath に使う。
        if (dlThumbPath != null) 'thumbPath': dlThumbPath,
      };
      // await はあえて待たない (失敗してもダウンロード自体は成功扱い)。
      _DownloadedVideosStore.add(record);

      // ── マップ自動埋め込み ──
      // MindMapScreen から渡ってきた onDownloadComplete を呼ぶ。
      // 既定では `_defaultEmbedDownloadedVideo` (現在キャンバス中央に動画
      // ノード生成) が割り当てられているので、ユーザー操作なしで完了 →
      // 即マップに反映される。
      try {
        widget.onDownloadComplete?.call(record);
      } catch (e) {
        debugPrint('onDownloadComplete failed: $e');
      }

      _appSnackM(
          scaffold,
          SnackBar(
            content: Text('${provider.t('video.savedTo')}: $filename',
                style: const TextStyle(fontSize: 12)),
            backgroundColor: const Color(0xFF43B97F),
            duration: const Duration(seconds: 8),
            action: SnackBarAction(
              label: provider.t('video.open'),
              textColor: Colors.white,
              onPressed: () {
                // 端末標準アプリ (OpenFilex) ではなくアプリ内 _FullscreenVideoPage
                // で開く。これにより当アプリの再生バー / 速度スライダー
                // (1.0x〜provider.videoMaxRate) が利用できる。
                // 既に FullscreenVideoPage の中にいるので、新しいルートを
                // 上に push する形になる (戻るボタンで元の動画に戻れる)。
                if (savedPath == null) return;
                Navigator.of(context).push(MaterialPageRoute(
                  fullscreenDialog: true,
                  builder: (_) => _FullscreenVideoPage(
                    url: savedPath!,
                  ),
                ));
              },
            ),
          ));
    } else {
      _appSnackM(
          scaffold,
          SnackBar(
            content: Text(
                '${provider.t('video.downloadFailed')}: ${errorMsg ?? provider.t('video.unknownReason')}',
                style: const TextStyle(fontSize: 12)),
            backgroundColor: const Color(0xFFE53935),
          ));
    }
  }

  /// 再生倍率を注入（広告中・新 video 要素出現時にも追従するウォッチャー付き）
  Future<void> _injectPlaybackRate() async {
    await _c?.evaluateJavascript(source: '''
      (function(){
        window.__MM_RATE__ = $_playbackRate;
        function applyAll(){
          try {
            var vs = document.querySelectorAll('video');
            for (var i = 0; i < vs.length; i++) {
              if (vs[i].playbackRate !== window.__MM_RATE__) {
                vs[i].playbackRate = window.__MM_RATE__;
              }
            }
          } catch(e) {}
        }
        applyAll();
        if (window.__MM_RATE_INSTALLED__) return;
        window.__MM_RATE_INSTALLED__ = true;
        setInterval(applyAll, 200);
        document.addEventListener('ratechange', function(e){
          try {
            if (e.target && e.target.tagName === 'VIDEO' &&
                e.target.playbackRate !== window.__MM_RATE__) {
              e.target.playbackRate = window.__MM_RATE__;
            }
          } catch(err) {}
        }, true);
        document.addEventListener('loadeddata', applyAll, true);
        document.addEventListener('play', applyAll, true);
      })();
    ''');
  }

  /// 再生位置トラッカー: 3 秒ごとに currentTime を FlutterPosition ハンドラに送信
  Future<void> _injectPositionTracker() async {
    await _c?.evaluateJavascript(source: '''
      (function(){
        if(window.__MM_PT__)return;window.__MM_PT__=true;
        setInterval(function(){
          try{var v=document.querySelector("video");
            if(v&&v.currentTime>0){
              if (window.flutter_inappwebview) {
                window.flutter_inappwebview.callHandler('FlutterPosition', String(v.currentTime));
                if(v.ended) window.flutter_inappwebview.callHandler('FlutterEnded', 'ended');
              }
            }
          }catch(e){}
        },3000);
      })();
    ''');
  }

  /// 保存済みの再生位置があれば seek で復元
  /// 既にタイムスタンプジャンプを実行済みかのフラグ。
  /// `widget.initialPosition` 経由のシークは初回 onLoadStop で 1 回だけ
  /// 行いたい (= ユーザーが手動でシークし直した後に勝手に戻されないように)。
  bool _initialPositionSeeked = false;

  Future<void> _restorePosition() async {
    if (_currentVideoId == null) return;
    // ── 優先順位 ──
    // 1. widget.initialPosition (= メモのハイパーリンクからジャンプ等で
    //    呼び出し側が明示指定した時刻) — 最優先で飛ぶ。
    // 2. それ以外は前回視聴位置 (Provider 保存) を復元。
    double seekTo = -1;
    final hasInitialPos = widget.initialPosition > 0.5;
    if (hasInitialPos) {
      // 既にシーク済みなら何もしない (ユーザーの手動シークを上書きしない)
      if (_initialPositionSeeked) return;
      seekTo = widget.initialPosition;
    } else {
      if (_initialPositionSeeked) return;
      final saved =
          context.read<MindMapProvider>().getVideoPosition(_currentVideoId!);
      if (saved > 3) seekTo = saved;
    }
    if (seekTo < 0) return;
    // ── JS シーク戦略 (多段防御 + 成功検知) ──
    // YouTube は autoplay で動画を 0 秒から開始するため、 単発の
    // currentTime= 代入では autoplay の初期化に上書きされて 0 に戻る
    // ことがある。 そのため:
    //   1. 既存の <video> があれば即座にシーク
    //   2. <video>.loadedmetadata で再シーク (duration が確定した直後)
    //   3. <video>.canplay で再シーク (再生開始可能になった直後)
    //   4. MutationObserver で後から追加される <video> にもリスナー登録
    //   5. 念の為 0.3/0.8/1.5/3 秒後にも再試行
    // どれかが効いたら DONE フラグを立てて、 それ以降の試行をスキップ
    // (= 成功後にユーザーが手動でシークしたのを上書きしない)。
    await _c?.evaluateJavascript(source: '''
      (function(){
        if (window.__MM_SEEK_TARGET__ === $seekTo && window.__MM_SEEK_ACTIVE__) return;
        window.__MM_SEEK_TARGET__ = $seekTo;
        window.__MM_SEEK_ACTIVE__ = true;
        window.__MM_SEEK_DONE__ = false;
        var TARGET = $seekTo;
        var attached = new WeakSet();
        function applyOne(v){
          if (window.__MM_SEEK_DONE__) return;
          try {
            if (!v) return;
            v.currentTime = TARGET;
            // 0.3 秒後に成功確認: TARGET 付近にいれば DONE
            setTimeout(function(){
              try {
                if (v && Math.abs(v.currentTime - TARGET) < 2) {
                  window.__MM_SEEK_DONE__ = true;
                }
              } catch(e) {}
            }, 300);
          } catch(e) {}
        }
        function attach(v){
          if (!v || attached.has(v)) return;
          attached.add(v);
          v.addEventListener('loadedmetadata', function(){ applyOne(v); }, false);
          v.addEventListener('canplay', function(){ applyOne(v); }, false);
          applyOne(v);
        }
        function scanAll(){
          if (window.__MM_SEEK_DONE__) return;
          try {
            document.querySelectorAll('video').forEach(attach);
          } catch(e) {}
        }
        scanAll();
        try {
          new MutationObserver(scanAll).observe(document, {childList:true, subtree:true});
        } catch(e) {}
        setTimeout(scanAll, 300);
        setTimeout(scanAll, 800);
        setTimeout(scanAll, 1500);
        setTimeout(scanAll, 3000);
      })();
    ''');
    if (hasInitialPos) {
      _initialPositionSeeked = true;
    }
  }

  void _changeRate(double rate) {
    setState(() => _playbackRate = rate);
    // 次回動画を開いた時の初期倍率に使う (起動を跨いで引き継ぐ)。
    try {
      context.read<MindMapProvider>().setLastVideoPlaybackRate(rate);
    } catch (_) {}
    // ローカル動画は VideoPlayer (= _vpc) で再生中。WebView 経由の
    // playbackRate スクリプト注入は無関係なので skip。
    // _vpc?.setPlaybackSpeed は ExoPlayer / AVPlayer の native API を
    // 直接叩くので、native UI を介さず確実に rate が適用される。
    if (_vpc != null) {
      _vpc!.setPlaybackSpeed(rate);
      return;
    }
    _injectPlaybackRate();
  }

  /// `Duration` を `mm:ss` または `h:mm:ss` 形式の文字列に整形する。
  /// 動画プレイヤー下部の現在時間 / 総時間表示用。
  String _formatVpcDuration(Duration d) {
    if (d.inMicroseconds < 0) d = Duration.zero;
    final h = d.inHours;
    final m = d.inMinutes.remainder(60);
    final s = d.inSeconds.remainder(60);
    final mm = m.toString().padLeft(2, '0');
    final ss = s.toString().padLeft(2, '0');
    if (h > 0) return '$h:$mm:$ss';
    return '$mm:$ss';
  }

  // ─── 動画視聴中メモ: パネル開閉 + マップ追加 ────────────────────────────

  /// メモパネルの開閉トグル。 ヘッダーのメモボタンから呼ばれる。
  void _toggleVideoMemoPanel() {
    setState(() {
      _videoMemoPanelOpen = !_videoMemoPanelOpen;
    });
    // パネル開閉に合わせてプレビュータイマーを起動 / 停止
    if (_videoMemoPanelOpen) {
      _startVideoMemoPreviewTimer();
    } else {
      _stopVideoMemoPreviewTimer();
    }
  }

  // 旧 `_insertVideoMemoTimestampAtCursor` メソッドは削除した。
  // 「現在時刻を挿入」 ボタンを廃止し、 「再生位置も保存」 チェックの ON/OFF
  // で動画の現在再生位置を自動的にメモノードに添付する形に変更したため、
  // メモ本文への手動挿入は不要になった (= ボタン経路の出口を断った)。

  /// このモバイル動画画面のメモ一覧を識別する安定したキーを返す。
  ///
  /// プレイリスト移動後も一覧は同じ State で保持されるため、現在の
  /// `_playlistIndex` をキーにすると、別動画へ移動した後の追加済み更新や削除が
  /// 移動先動画の保存領域へ書かれてしまう。PC版と同じく画面を開いた時の URL を
  /// 一覧キーに固定し、各メモの実際の動画は `sourceUrl` で識別する。
  String _historyKeyUrl() {
    final initial = widget.url.trim();
    return initial.isNotEmpty ? initial : 'youtube_video_memos';
  }

  /// メモ項目を作った時点の動画 URL をスナップショットする。
  /// 項目を追加した後に別の動画へ移動してからマップへ送っても、
  /// 元の動画ノードに正しく接続できるようにする。
  String _currentVideoMemoSourceUrl() {
    if (_currentVideoId != null && _currentVideoId!.isNotEmpty) {
      return 'https://www.youtube.com/watch?v=$_currentVideoId';
    }

    if (_playlist.isNotEmpty && _playlistIndex < _playlist.length) {
      final source = _playlist[_playlistIndex].trim();
      if (source.isNotEmpty) {
        final videoId = NodeWidget.extractVideoId(source);
        if (videoId != null) {
          return 'https://www.youtube.com/watch?v=$videoId';
        }
        return source;
      }
    }

    final current = _currentUrl.trim();
    if (current.isNotEmpty) {
      final videoId = NodeWidget.extractVideoId(current);
      if (videoId != null) {
        return 'https://www.youtube.com/watch?v=$videoId';
      }
      return current;
    }
    return widget.url.trim();
  }

  /// メモ項目の補助表示と Google 検索タイトル用に、
  /// 作成時点の動画タイトルも保存する。
  String? _currentVideoMemoSourceTitle() {
    final title = _currentTitle.trim();
    return title.isEmpty ? null : title;
  }

  /// 永続化されたメモ履歴を読み込んで `_videoMemos` に反映。
  Future<void> _loadVideoMemoHistory() async {
    final loaded = await _VideoMemoHistoryStore.loadForUrl(_historyKeyUrl());
    if (!mounted) return;
    setState(() {
      final merged = <_VideoMemoEntry>[..._videoMemos];
      final knownIds = merged.map((entry) => entry.id).toSet();
      for (final entry in loaded) {
        if (knownIds.add(entry.id)) {
          merged.add(entry);
        }
      }
      _videoMemos
        ..clear()
        ..addAll(merged.take(100));
    });
    // 読込み中の追加/削除は persist 側でこの Future を待つため、
    // ここから再保存せずともマージ済み全件が次の書込みに入る。
  }

  /// 現在の `_videoMemos` を SharedPreferences に保存。
  Future<void> _persistVideoMemos() async {
    await _videoMemoLoadFuture;
    final snapshot = _videoMemos.take(100).toList(growable: false);
    await _VideoMemoHistoryStore.saveForUrl(_historyKeyUrl(), snapshot);
  }

  /// 「マップに追加」 を実行する内部処理。
  ///
  /// 入力欄から直接送信せず、一度リストへ追加したメモ項目の
  /// 「マップに追加」ボタンからのみ呼ぶ。
  Future<void> _submitVideoMemoToMap(
      {required _VideoMemoEntry existingEntry}) async {
    if (_videoMemoSubmitting) return;
    final text = existingEntry.text.trim();
    if (text.isEmpty) {
      _showInlineBanner(
          context.read<MindMapProvider>().t('vmemo.empty'),
          color: const Color(0xFFE57373));
      return;
    }
    setState(() => _videoMemoSubmitting = true);
    try {
      final provider = context.read<MindMapProvider>();
      // 別動画へ移動後でも、項目作成時の動画へ紐づける。
      // 旧形式の JSON には sourceUrl が無いため、その場合だけ現在動画へ
      // フォールバックして保存互換性を保つ。
      final snapshottedSource = (existingEntry.sourceUrl ?? '').trim();
      final videoUrl = snapshottedSource.isNotEmpty
          ? snapshottedSource
          : _currentVideoMemoSourceUrl();

      // ── タイムスタンプ決定ロジック ──
      // 旧実装にはトグル `_videoMemoIncludeTimestamp` があり、 何らかの
      // タイミングで OFF になると時刻が消えるバグの温床だった。
      // 新ロジックは「タイムスタンプフィールドの値が全て」 を採用:
      //   - フィールドが空 → 時刻なし (= ユーザーが意図的に消した)
      //   - フィールドに値あり → そのまま使う
      // 自動追従モードではフィールドに現在再生位置が常に流し込まれている
      // ので、 ユーザーが何も触らなければ必ず時刻が乗る。
      // 履歴経由 (existingEntry) のみ、 保存時の値を尊重する。
      final ts = existingEntry.timestampSec;
      // ts が null = タイムスタンプなしで保存 (ユーザーがフィールドを空にした)
      final headerLabel = ts != null ? '[${_formatTimestamp(ts)}]' : '';

      // ── ノード生成 ──
      // 親動画ノードが見つからないときの fallback 位置はキャンバス中央付近。
      // フルスクリーンページからは TransformationController が見えないので
      // 固定値で OK (provider 側で 20000×20000 にクランプされる)。
      // 貼り付けた画像もノードに付ける (= ユーザー要望)。
      final imgPath = existingEntry.imagePath;
      final node = provider.addVideoMemoNode(
        memoText: text,
        videoUrl: videoUrl,
        memoTitleHeader: headerLabel.isEmpty ? null : headerLabel,
        fallbackPosition: const Offset(9000, 9000),
        attachmentPath: imgPath,
        attachmentName: imgPath == null
            ? null
            : imgPath.split(Platform.pathSeparator).last.split('/').last,
      );

      if (!mounted) return;
      if (node == null) {
        // ルート SnackBar はメモ欄の上に見えにくいので、 パネル内バナーで通知。
        _showInlineBanner(provider.t('vmemo.addFailed'),
            color: const Color(0xFFE57373));
        return;
      }

      setState(() {
        existingEntry.addedToMap = true;
      });
      // 永続化 (履歴一覧をセッション越しに保持)
      await _persistVideoMemos();
      if (!mounted) return;

      // 「マップにメモを追加」 をメモ欄の上のバナーで通知 (= ユーザー要望)。
      _showInlineBanner(
          headerLabel.isNotEmpty
              ? provider
                  .t('vmemo.addedToMapAt')
                  .replaceFirst('{timestamp}', headerLabel)
              : provider.t('vmemo.addedToMap'),
          color: const Color(0xFF43B97F));
    } catch (e) {
      debugPrint('addVideoMemoNode failed: $e');
      if (mounted) {
        _showInlineBanner(
            context
                .read<MindMapProvider>()
                .t('vmemo.addFailedWithError')
                .replaceFirst('{error}', '$e'),
            color: const Color(0xFFE57373));
      }
    } finally {
      if (mounted) setState(() => _videoMemoSubmitting = false);
    }
  }

  /// まだマップに送っていないメモを、 まとめてマップへ追加する
  /// (= ユーザー要望: 動画メモを纏めてマップに追加できるように)。
  /// Windows 版の `_winAddAllVideoMemosToMap` と同じ動き。
  Future<void> _addAllVideoMemosToMap() async {
    if (_videoMemoSubmitting) return;
    final provider = context.read<MindMapProvider>();
    // 一覧は新しい順なので、 逆から回して古い順に置く。
    final pending = _videoMemos
        .where((e) => !e.addedToMap && e.text.trim().isNotEmpty)
        .toList()
        .reversed
        .toList();
    if (pending.isEmpty) {
      _showInlineBanner(provider.t('vmemo.allAlreadyAdded'),
          color: const Color(0xFF4FC3F7));
      return;
    }
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('vmemo.addAllTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Text(
            provider
                .t('vmemo.addAllConfirm')
                .replaceFirst('{count}', '${pending.length}'),
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, false),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF43B97F),
                foregroundColor: Colors.white),
            onPressed: () => Navigator.pop(dctx, true),
            child: Text(provider.t('vmemo.addAllRun')),
          ),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    setState(() => _videoMemoSubmitting = true);
    var added = 0;
    var failed = 0;
    try {
      for (final entry in pending) {
        final snapshottedSource = (entry.sourceUrl ?? '').trim();
        final videoUrl = snapshottedSource.isNotEmpty
            ? snapshottedSource
            : _currentVideoMemoSourceUrl();
        final ts = entry.timestampSec;
        final headerLabel = ts != null ? '[${_formatTimestamp(ts)}]' : '';
        try {
          final img = entry.imagePath;
          final node = provider.addVideoMemoNode(
            memoText: entry.text.trim(),
            videoUrl: videoUrl,
            memoTitleHeader: headerLabel.isEmpty ? null : headerLabel,
            fallbackPosition: const Offset(9000, 9000),
            attachmentPath: img,
            attachmentName: img == null
                ? null
                : img.split(Platform.pathSeparator).last.split('/').last,
          );
          if (node == null) {
            failed++;
          } else {
            entry.addedToMap = true;
            added++;
          }
        } catch (e) {
          debugPrint('addVideoMemoNode (bulk) failed: $e');
          failed++;
        }
      }
      if (!mounted) return;
      setState(() {});
      await _persistVideoMemos();
      if (!mounted) return;
      _showInlineBanner(
        failed == 0
            ? provider
                .t('vmemo.addedAllToMap')
                .replaceFirst('{count}', '$added')
            : provider
                .t('vmemo.addedAllPartial')
                .replaceFirst('{count}', '$added')
                .replaceFirst('{failed}', '$failed'),
        color: failed == 0 ? const Color(0xFF43B97F) : const Color(0xFFFFB74D),
      );
    } finally {
      if (mounted) setState(() => _videoMemoSubmitting = false);
    }
  }

  /// 画像ボタン: クリップボードに画像があればそれを、 無ければファイルを
  /// 選んで入力中のメモに貼り付ける (= ユーザー要望: 動画メモで画像を
  /// 貼り付けておけるように)。
  Future<void> _attachVideoMemoImage() async {
    final saved = await grabImageForVideoMemo();
    if (saved == null || !mounted) return;
    setState(() => _videoMemoDraftImage = saved);
    _showInlineBanner(
        context.read<MindMapProvider>().t('vmemo.imageAttached'),
        color: const Color(0xFF43B97F));
  }

  /// 入力中のテキストを独立したメモ項目として追加する。
  /// この時点ではマップへ送らず、各項目のボタンからマップ / AI /
  /// Google 検索を選ぶ。
  void _saveVideoMemoLocally() {
    final text = _videoMemoController.text.trim();
    // 画像だけのメモも足せる (= ユーザー要望)。
    if (text.isEmpty && _videoMemoDraftImage == null) {
      _showInlineBanner(
          context.read<MindMapProvider>().t('vmemo.empty'),
          color: const Color(0xFFE57373));
      return;
    }
    // タイムスタンプフィールドから値を取得 (空なら時刻なし)
    double? ts;
    final tsText = _videoMemoTsCtrl.text.trim();
    if (tsText.isNotEmpty) {
      ts = _parseUserTimestamp(tsText);
    }
    final sourceUrl = _currentVideoMemoSourceUrl();
    final sourceTitle = _currentVideoMemoSourceTitle();
    setState(() {
      _videoMemos.insert(
        0,
        _VideoMemoEntry(
          id: DateTime.now().microsecondsSinceEpoch.toString(),
          text: text,
          timestampSec: ts,
          imagePath: _videoMemoDraftImage,
          addedToMap: false,
          sourceUrl: sourceUrl.isEmpty ? null : sourceUrl,
          sourceTitle: sourceTitle,
        ),
      );
      while (_videoMemos.length > 100) {
        _videoMemos.removeLast();
      }
      _videoMemoController.clear();
      _videoMemoDraftImage = null;
    });
    // 永続化。旧 JSON は _VideoMemoEntry.fromJson で引き続き読める。
    unawaited(_persistVideoMemos());
  }

  /// メモ履歴行の削除。
  void _deleteVideoMemo(_VideoMemoEntry entry) {
    setState(() {
      _videoMemos.removeWhere((e) => e.id == entry.id);
    });
    // 永続化 (削除を反映)
    unawaited(_persistVideoMemos());
  }

  /// メモパネルウィジェット。 動画レイヤーの最前面に重ねて表示する。
  /// 動画タップ等を奪わないよう、 Positioned.fill ではなく
  /// Align(bottomCenter) で下半分にだけ存在する Material を返す。
  Widget _buildVideoMemoPanel(BuildContext context) {
    final provider = context.read<MindMapProvider>();
    final media = MediaQuery.of(context);
    final keyboard = media.viewInsets.bottom;
    final maxHeight = media.size.height * 0.55;
    return Positioned.fill(
      child: Stack(
        children: [
          // 背景タップで閉じる半透明レイヤー
          Positioned.fill(
            child: GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: _toggleVideoMemoPanel,
              child: Container(
                color: Colors.black.withValues(alpha: 0.35),
              ),
            ),
          ),
          // 下からのシート本体
          Align(
            alignment: Alignment.bottomCenter,
            child: GestureDetector(
              // シート内タップで閉じないように吸収
              behavior: HitTestBehavior.opaque,
              onTap: () {},
              child: AnimatedContainer(
                duration: const Duration(milliseconds: 180),
                curve: Curves.easeOut,
                constraints: BoxConstraints(maxHeight: maxHeight),
                margin: EdgeInsets.only(bottom: keyboard),
                decoration: const BoxDecoration(
                  color: Color(0xFF1E1E32),
                  borderRadius: BorderRadius.vertical(top: Radius.circular(16)),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black54,
                      blurRadius: 12,
                      offset: Offset(0, -4),
                    ),
                  ],
                ),
                child: Material(
                  color: Colors.transparent,
                  child: SafeArea(
                    top: false,
                    child: Padding(
                      padding: const EdgeInsets.fromLTRB(12, 8, 12, 8),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          // ── 通知バナー (= ユーザー要望: 「マップにメモを追加」 等の
                          //   メッセージをマップではなくメモ欄の上に出す) ──
                          if (_bannerText != null)
                            Container(
                              margin: const EdgeInsets.only(bottom: 8),
                              padding: const EdgeInsets.symmetric(
                                  horizontal: 12, vertical: 10),
                              decoration: BoxDecoration(
                                color: _bannerColor.withValues(alpha: 0.96),
                                borderRadius: BorderRadius.circular(8),
                              ),
                              child: Row(children: [
                                const Icon(Icons.check_circle_rounded,
                                    color: Colors.white, size: 18),
                                const SizedBox(width: 8),
                                Expanded(
                                  child: Text(_bannerText ?? '',
                                      style: const TextStyle(
                                          color: Colors.white,
                                          fontSize: 12.5,
                                          fontWeight: FontWeight.w600)),
                                ),
                              ]),
                            ),
                          // ── ヘッダー ──
                          Row(children: [
                            const Icon(Icons.sticky_note_2_rounded,
                                color: Color(0xFFFFB347), size: 18),
                            const SizedBox(width: 6),
                            Expanded(
                              child: Text(
                                provider.t('vmemo.title'),
                                style: const TextStyle(
                                    color: Colors.white,
                                    fontSize: 14,
                                    fontWeight: FontWeight.w700),
                              ),
                            ),
                            IconButton(
                              padding: EdgeInsets.zero,
                              constraints: const BoxConstraints(
                                  minWidth: 28, minHeight: 28),
                              icon: const Icon(Icons.close,
                                  color: Colors.white70, size: 18),
                              tooltip: context
                                  .read<MindMapProvider>()
                                  .t('btn.close'),
                              onPressed: _toggleVideoMemoPanel,
                            ),
                          ]),
                          const SizedBox(height: 4),
                          // ── 入力欄 ──
                          TextField(
                            controller: _videoMemoController,
                            focusNode: _videoMemoFocus,
                            style: const TextStyle(
                                color: Colors.white, fontSize: 14),
                            minLines: 2,
                            maxLines: 6,
                            keyboardType: TextInputType.multiline,
                            textInputAction: TextInputAction.newline,
                            decoration: InputDecoration(
                              hintText: provider.t('vmemo.inputHint'),
                              hintStyle: const TextStyle(
                                  color: Colors.white38, fontSize: 12),
                              filled: true,
                              fillColor: Colors.white.withValues(alpha: 0.08),
                              isDense: true,
                              contentPadding: const EdgeInsets.symmetric(
                                  horizontal: 10, vertical: 10),
                              border: OutlineInputBorder(
                                borderRadius: BorderRadius.circular(8),
                                borderSide: BorderSide.none,
                              ),
                            ),
                          ),
                          // ── 貼り付けた画像 (= ユーザー要望) ──
                          if (_videoMemoDraftImage != null) ...[
                            const SizedBox(height: 6),
                            Row(children: [
                              buildVideoMemoThumb(
                                  context, _videoMemoDraftImage!,
                                  size: 44),
                              Expanded(
                                child: Text(
                                  provider.t('vmemo.imageAttached'),
                                  style: const TextStyle(
                                      color: Colors.white70, fontSize: 11),
                                ),
                              ),
                              IconButton(
                                padding: EdgeInsets.zero,
                                constraints: const BoxConstraints(
                                    minWidth: 26, minHeight: 26),
                                icon: const Icon(Icons.close_rounded,
                                    color: Colors.white54, size: 15),
                                tooltip: provider.t('btn.delete'),
                                onPressed: () => setState(
                                    () => _videoMemoDraftImage = null),
                              ),
                            ]),
                          ],
                          const SizedBox(height: 8),
                          // ── 「再生位置を含める」 トグルボタン ──
                          // ユーザー要望: タイムスタンプはリアルタイム表示
                          // させず、 このボタンを押した時だけ表示 + その瞬間
                          // の動画時刻をスナップ保存。
                          Row(children: [
                            Material(
                              color: Colors.transparent,
                              child: InkWell(
                                borderRadius: BorderRadius.circular(6),
                                onTap: () {
                                  setState(() {
                                    _videoMemoShowTimestamp =
                                        !_videoMemoShowTimestamp;
                                  });
                                  if (_videoMemoShowTimestamp) {
                                    // ON: 現在の動画時刻を 1 回だけスナップ
                                    _resetVideoMemoTsToNow();
                                  } else {
                                    // OFF: フィールドをクリア (= 保存時に
                                    // タイムスタンプ無し)
                                    _videoMemoTsCtrl.clear();
                                    _videoMemoTsManualOverride = false;
                                  }
                                },
                                child: Container(
                                  padding: const EdgeInsets.symmetric(
                                      horizontal: 10, vertical: 6),
                                  decoration: BoxDecoration(
                                    color: _videoMemoShowTimestamp
                                        ? const Color(0xFF4FC3F7)
                                            .withValues(alpha: 0.18)
                                        : Colors.white.withValues(alpha: 0.04),
                                    borderRadius: BorderRadius.circular(6),
                                    border: Border.all(
                                      color: _videoMemoShowTimestamp
                                          ? const Color(0xFF4FC3F7)
                                          : Colors.white24,
                                    ),
                                  ),
                                  child: Row(
                                      mainAxisSize: MainAxisSize.min,
                                      children: [
                                        Icon(
                                          _videoMemoShowTimestamp
                                              ? Icons.play_circle_fill_rounded
                                              : Icons
                                                  .play_circle_outline_rounded,
                                          size: 14,
                                          color: _videoMemoShowTimestamp
                                              ? const Color(0xFF4FC3F7)
                                              : Colors.white70,
                                        ),
                                        const SizedBox(width: 4),
                                        Text(
                                          provider.t('vmemo.includePosition'),
                                          style: TextStyle(
                                            fontSize: 11,
                                            fontWeight: FontWeight.w600,
                                            color: _videoMemoShowTimestamp
                                                ? const Color(0xFF4FC3F7)
                                                : Colors.white70,
                                          ),
                                        ),
                                      ]),
                                ),
                              ),
                            ),
                          ]),
                          const SizedBox(height: 6),
                          // ── タイムスタンプ指定行 (= トグル ON 時のみ表示) ──
