  /// 動画メモ履歴をすべて削除する (= ユーザー要望: 一括で削除)。 確認つき。
  Future<void> _confirmClearVideoMemos() async {
    final provider = context.read<MindMapProvider>();
    if (_videoMemos.isEmpty) return;
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('vmemo.clearAllTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Text(
            provider
                .t('vmemo.clearAllConfirm')
                .replaceFirst('{count}', '${_videoMemos.length}'),
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx, false),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFE57373),
                foregroundColor: Colors.black),
            onPressed: () => Navigator.pop(dctx, true),
            child: Text(provider.t('btn.delete')),
          ),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    setState(() => _videoMemos.clear());
    await _persistVideoMemos();
    _showInlineBanner(provider.t('vmemo.clearedAll'));
  }

  /// 履歴 1 行。
  /// 現在再生中の動画 (mp4 でも YouTube でも OK) を指定秒へシークする。
  /// 履歴項目クリック → そのメモのタイムスタンプ位置に飛ぶ用途。
  /// VideoPlayerController があればそれを優先、 無ければ WebView の JS injection。
  Future<void> _seekVideoTo(double seconds) async {
    if (seconds < 0) seconds = 0;
    // VideoPlayer 経路 (ローカル mp4 / 直リンク)
    final vpc = _vpc;
    if (vpc != null && vpc.value.isInitialized) {
      try {
        await vpc.seekTo(Duration(milliseconds: (seconds * 1000).round()));
        if (!vpc.value.isPlaying) {
          await vpc.play();
        }
      } catch (e) {
        debugPrint('seekVideoTo (vpc) failed: $e');
      }
      return;
    }
    // WebView 経路 (YouTube / 動画 HTML)
    final c = _c;
    if (c == null) return;
    try {
      await c.evaluateJavascript(source: '''
        (function(){
          try {
            var v = document.querySelector('video');
            if (v) {
              v.currentTime = $seconds;
              if (v.paused) v.play();
            }
          } catch(e) {}
        })();
      ''');
    } catch (e) {
      debugPrint('seekVideoTo (webview) failed: $e');
    }
  }

  /// 「このセッションのメモ」 をまとめて AI に送る (= ユーザー要望: 一括で AI へ)。
  String _videoHistoryText() {
    return _videoMemos.map((e) {
      final ts = e.timestampSec != null
          ? '[${_formatTimestamp(e.timestampSec!)}] '
          : '';
      return '$ts${e.text}';
    }).join('\n');
  }

  void _sendVideoHistoryToAi() {
    if (_videoMemos.isEmpty) {
      _showInlineBanner(
          context.read<MindMapProvider>().t('vmemo.noMemosToSend'),
          color: const Color(0xFFE57373));
      return;
    }
    final text = _videoHistoryText();
    _openMemoTextInAi(text);
  }

  void _openVideoHistoryInGoogleSearch() {
    final provider = context.read<MindMapProvider>();
    if (_videoMemos.isEmpty) {
      _showInlineBanner(provider.t('vmemo.noMemosToSearch'),
          color: const Color(0xFFE57373));
      return;
    }
    final text = _videoHistoryText().trim();
    if (text.isEmpty) {
      _showInlineBanner(provider.t('vmemo.noMemosToSearch'),
          color: const Color(0xFFE57373));
      return;
    }
    // ── メモ欄の「隣」 (上側) に出す (= ユーザー要望: 同じ場所に重ねず、
    //    メモの隣に立ち上がるように。 メモは下寄せシートなので上に並べる) ──
    final rect = _videoMemoSearchRect(context);
    GoogleSearchDialog.showFloating(
      context,
      initialQuery: text,
      initialMemo: text,
      customTitle: provider.t('vmemo.searchTitle'),
      anchorPos: rect.topLeft,
      singletonKey: 'mobile_video_memo_google',
      initialWidth: rect.width,
      initialHeight: rect.height,
      onAddNode: (_, __, ___) {},
    );
  }

  /// 動画メモ欄 (下寄せシート) の画面矩形。 メモから開く Google 検索を
  /// メモと同じ位置・大きさで重ねるために使う (= ユーザー要望)。
  Rect _videoMemoPanelRect(BuildContext context) {
    final mq = MediaQuery.of(context);
    final size = mq.size;
    final w = size.width - 24.0;
    final h = size.height * 0.55;
    final left = 12.0;
    final top =
        (size.height - h - mq.padding.bottom - 8.0).clamp(8.0, size.height);
    return Rect.fromLTWH(left, top, w, h);
  }

  /// メモ欄の「隣」 (モバイルは上下配置なので上側) に出す Google 検索の矩形
  /// (= ユーザー要望: メモと同じ場所に重ねず、 隣に立ち上がるように)。
  Rect _videoMemoSearchRect(BuildContext context) {
    final memo = _videoMemoPanelRect(context);
    final size = MediaQuery.of(context).size;
    final double h =
        (memo.top - 16.0).clamp(240.0, size.height - 24.0).toDouble();
    return Rect.fromLTWH(12.0, 8.0, memo.width, h);
  }

  /// 1 件の動画メモ項目だけを Google 検索へ渡す。
  /// 作成時の動画タイトルが保存されていれば見出しに使うが、
  /// 旧データの sourceTitle == null でも従来通り開ける。
  void _openVideoMemoInGoogleSearch(_VideoMemoEntry entry) {
    final text = entry.text.trim();
    final provider = context.read<MindMapProvider>();
    if (text.isEmpty) {
      _showInlineBanner(provider.t('vmemo.noMemosToSearch'),
          color: const Color(0xFFE57373));
      return;
    }
    final rect = _videoMemoSearchRect(context);
    final sourceTitle = (entry.sourceTitle ?? '').trim();
    GoogleSearchDialog.showFloating(
      context,
      initialQuery: text,
      initialMemo: text,
      customTitle: sourceTitle.isEmpty
          ? provider.t('vmemo.searchTitle')
          : provider
              .t('vmemo.searchSourceTitle')
              .replaceFirst('{title}', sourceTitle),
      // ── メモ欄の「隣」 (上側) に出す (= ユーザー要望) ──
      anchorPos: rect.topLeft,
      // 同じ検索画面を再利用し、別項目を押した時は内容を更新する。
      singletonKey: 'mobile_video_memo_google',
      initialWidth: rect.width,
      initialHeight: rect.height,
      onAddNode: (_, __, ___) {},
    );
  }

  /// 表示中の YouTube 動画またはブラウズページを、ブラウザ AI の会話
  /// コンテキストとして渡す。動画では URL にタイトル・現在位置・説明も添え、
  /// ホーム / 検索では現在のページ URL とページ情報を渡す。WebView からの
  /// 説明取得に失敗しても URL とタイトルだけで開けるよう、JS 取得はベストエフォート。
  Future<void> _shareCurrentVideoWithBrowserAi() async {
    if (!mounted || _sharingVideoWithBrowserAi) return;
    // YouTube は SPA 遷移するため、非同期取得の途中で別動画へ移動し得る。
    // 共有開始時点の識別情報を固定し、各 await 後に videoId を照合する。
    final videoIdSnapshot = _currentVideoId;
    final titleSnapshot = _currentTitle.trim();
    final urlSnapshot = _currentUrl.isNotEmpty ? _currentUrl : widget.url;
    final provider = context.read<MindMapProvider>();
    bool isStillSameTarget() =>
        mounted &&
        _currentVideoId == videoIdSnapshot &&
        (videoIdSnapshot != null || _currentUrl == urlSnapshot);

    setState(() => _sharingVideoWithBrowserAi = true);
    try {
      var shareUrl = videoIdSnapshot == null
          ? urlSnapshot
          : 'https://www.youtube.com/watch?v=$videoIdSnapshot';
      shareUrl = shareUrl
          .replaceFirst('https://m.youtube.com/', 'https://www.youtube.com/')
          .replaceFirst('http://m.youtube.com/', 'https://www.youtube.com/');

      var description = '';
      Object? descriptionResult;
      try {
        descriptionResult = await _c?.evaluateJavascript(source: r'''
        (function() {
          try {
            var visible = document.querySelector(
              'ytm-expandable-video-description-body-renderer .description-text,' +
              'ytm-expandable-video-description-body-renderer,' +
              '#description-inline-expander #snippet-text,' +
              '#description'
            );
            var text = visible ? (visible.innerText || visible.textContent || '') : '';
            if (!text) {
              var meta = document.querySelector(
                'meta[name="description"], meta[itemprop="description"], meta[property="og:description"]'
              );
              text = meta ? (meta.getAttribute('content') || '') : '';
            }
            return text.trim();
          } catch (e) { return ''; }
        })();
      ''');
      } catch (_) {
        // URL とタイトルだけでも共有できるため、説明取得失敗は無視する。
      }
      if (!isStillSameTarget()) return;
      description = descriptionResult is String
          ? descriptionResult
          : (descriptionResult?.toString() ?? '');
      description = description.replaceAll(RegExp(r'\s+'), ' ').trim();
      if (description.length > 1200) {
        description = '${description.substring(0, 1200)}…';
      }

      final position = await _getCurrentVideoTimeSec();
      if (!isStillSameTarget()) return;

      final isVideoShare = videoIdSnapshot != null;
      final title = titleSnapshot.isNotEmpty
          ? titleSnapshot
          : (isVideoShare
              ? '${provider.t('fsv.videoAiUntitled')} ($videoIdSnapshot)'
              : shareUrl);
      final metadata = <String, Object>{
        'title': title,
        'url': shareUrl,
        if (position >= 1) 'currentPosition': _formatTimestamp(position),
        if (description.isNotEmpty) 'description': description,
      };

      final prompt = provider
          .t(isVideoShare ? 'fsv.videoAiPrompt' : 'fsv.pageAiPrompt')
          .replaceAll('{metadata}', jsonEncode(metadata));
      _openMemoTextInAi(
        prompt.trim(),
        copyToClipboard: false,
      );
    } finally {
      if (mounted) {
        setState(() => _sharingVideoWithBrowserAi = false);
      }
    }
  }

  /// メモ本文を持ってブラウザ版 AI を全画面ルートで開く (= ユーザー要望: モバイルの
  /// 動画ビューアから AI チャット欄を全画面で開く / メモを AI に渡す)。 設定中の
  /// ブラウザ AI ターゲットの URL にクエリを埋め込み、 ページ側 JS でも入力欄へ
  /// 注入する。 [text] が空なら空のまま AI を開く (= 全画面 AI チャットボタン用)。
  /// [copyToClipboard] は既存メモ送信のフォールバックを維持する一方、動画共有では
  /// 外部メタデータを端末クリップボードへ残さないため false にできる。
  void _openMemoTextInAi(
    String text, {
    bool copyToClipboard = true,
  }) {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final trimmed = text.trim();
    final query = trimmed.isEmpty ? '' : provider.browserAiApplyPrefix(trimmed);
    // 注入が空振りした時のために、 クリップボードにもコピーしておく。
    if (copyToClipboard && query.isNotEmpty) {
      Clipboard.setData(ClipboardData(text: query));
    }
    final url = query.isEmpty
        ? ((provider.browserAiTargetDef['url'] ??
                'https://www.google.com/search?q={q}')
            .replaceAll('{q}', ''))
        : provider.browserAiUrlForQuery(query);
    // ── 全画面で開く (= ユーザー要望: モバイルの AI は全画面に) ──
    //   以前は画面下半分のシートだったが、 入力欄が狭く使いづらかった。
    //   全画面ルートなら Android の WebView タッチ抜けも起きない。
    Navigator.of(context).push(
      MaterialPageRoute<void>(
        fullscreenDialog: true,
        builder: (_) => _MobileBrowserAiPage(
          url: url,
          injectText: query,
        ),
      ),
    );
  }

  /// YouTube 右端の AI / 動画共有ボタンを長押しした時に開く設定。
  /// ブラウザ AI の選択と前提条件を同じシートで編集し、既存の Provider 設定へ
  /// 保存する。通常タップの処理とは分離しているため、長押し後に AI を勝手に
  /// 開いたり動画共有を開始したりしない。
  Future<void> _showMobileVideoAiSettings() async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    var selectedTarget = provider.browserAiTarget;
    final prefixController =
        TextEditingController(text: provider.browserAiPrefix);
    try {
      final shouldSave = await showModalBottomSheet<bool>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: Colors.transparent,
        barrierColor: Colors.black54,
        builder: (sheetContext) {
          return StatefulBuilder(
            builder: (sheetContext, setSheetState) {
              final keyboardInset =
                  MediaQuery.of(sheetContext).viewInsets.bottom;
              return AnimatedPadding(
                duration: const Duration(milliseconds: 180),
                curve: Curves.easeOut,
                padding: EdgeInsets.only(bottom: keyboardInset),
                child: Container(
                  decoration: const BoxDecoration(
