      if (shouldSave != true || !mounted) return;
      await provider.setBrowserAiTarget(selectedTarget);
      await provider.setBrowserAiPrefix(prefixController.text.trim());
    } finally {
      prefixController.dispose();
    }
  }

  Future<void> _loadYoutubeUiLayout() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final layout = prefs.getString(_youtubeUiLayoutPrefKey);
      final inSide = layout == 'side';
      final atBottom = layout == 'bottom';
      final onLeft = prefs.getString(_youtubeUiSidePrefKey) == 'left';
      final storedOrder =
          prefs.getStringList(_youtubeSideActionOrderPrefKey) ?? const [];
      if (!mounted) return;
      setState(() {
        if (!_youtubeUiLayoutTouched) {
          _youtubeControlsInSideMenu = inSide;
          _youtubeControlsAtBottom = atBottom;
          _youtubeSideMenuOnLeft = onLeft;
        }
        if (!_youtubeSideActionOrderTouched) {
          _youtubeSideActionOrder =
              _normalizeYoutubeSideActionOrder(storedOrder);
        }
      });
    } catch (_) {}
  }

  List<String> _normalizeYoutubeSideActionOrder(Iterable<String> stored) {
    final known = _defaultYoutubeSideActionOrder.toSet();
    final seen = <String>{};
    final normalized = <String>[];
    // 未知 ID と重複 ID は無視する。条件によって現在表示されない既知 ID は
    // 削除せず保持するため、動画・ホーム・mp4 の切替後も順序が崩れない。
    for (final id in stored) {
      if (known.contains(id) && seen.add(id)) normalized.add(id);
    }
    for (final id in _defaultYoutubeSideActionOrder) {
      if (seen.add(id)) normalized.add(id);
    }
    // ── 移行 (2026-07-30): バックグラウンド再生ボタンを前方 (下部バーでは
    //    左の方) へ (= ユーザー要望: 結構使うから左の方に持ってきて)。
    // 旧既定は末尾だったため、 保存済みの並びでも「末尾のまま」 なら新既定
    // 位置へ移す。 ユーザーが自分で別の位置に並べ替えている場合は尊重する。
    if (normalized.length > 1 &&
        normalized.last == _ytSideBackgroundPlayback) {
      normalized.removeLast();
      final target = _defaultYoutubeSideActionOrder
          .indexOf(_ytSideBackgroundPlayback)
          .clamp(0, normalized.length);
      normalized.insert(target, _ytSideBackgroundPlayback);
    }
    return normalized;
  }

  Future<void> _saveYoutubeUiLayout() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(
          _youtubeUiLayoutPrefKey,
          _youtubeControlsInSideMenu
              ? 'side'
              : (_youtubeControlsAtBottom ? 'bottom' : 'header'));
      await prefs.setString(
          _youtubeUiSidePrefKey, _youtubeSideMenuOnLeft ? 'left' : 'right');
    } catch (_) {}
  }

  Future<void> _saveYoutubeSideActionOrder() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setStringList(
          _youtubeSideActionOrderPrefKey, _youtubeSideActionOrder);
    } catch (_) {}
  }

  void _moveYoutubeSideAction(String id, int offset) {
    final from = _youtubeSideActionOrder.indexOf(id);
    if (from < 0) return;
    final to = from + offset;
    if (to < 0 || to >= _youtubeSideActionOrder.length) return;
    setState(() {
      _youtubeSideActionOrderTouched = true;
      final moved = _youtubeSideActionOrder.removeAt(from);
      _youtubeSideActionOrder.insert(to, moved);
    });
    _saveYoutubeSideActionOrder();
  }

  void _resetYoutubeSideActionOrder() {
    setState(() {
      _youtubeSideActionOrderTouched = true;
      _youtubeSideActionOrder = List<String>.of(_defaultYoutubeSideActionOrder);
    });
    _saveYoutubeSideActionOrder();
  }

  String _youtubeSideActionLabel(String id) {
    switch (id) {
      case _ytSideHideUi:
        return 'UIを隠す';
      case _ytSideAiChat:
        return 'AIチャット';
      case _ytSideShareWithAi:
        return '動画をAIと共有';
      case _ytSideUiSettings:
        return 'UI配置設定';
      case _ytSideClose:
        return '動画画面を閉じる';
      case _ytSideHistoryBack:
        return '前のページ';
      case _ytSideHistoryForward:
        return '次のページ';
      case _ytSideSearch:
        return 'YouTube検索';
      case _ytSideEmbed:
        return 'マップに追加';
      case _ytSidePip:
        return 'ピクチャーインピクチャ';
      case _ytSideSplit:
        return '画面分割';
      case _ytSideMemo:
        return '動画メモ';
      case _ytSidePlaybackRate:
        return '再生速度';
      case _ytSideSeekStep:
        return '早送り秒数';
      case _ytSideReload:
        return '再読み込み';
      case _ytSideCopyUrl:
        return 'URLをコピー';
      case _ytSidePlaylistPosition:
        return 'プレイリスト位置';
      case _ytSidePlaylistPrevious:
        return '前の動画';
      case _ytSidePlaylistNext:
        return '次の動画';
      case _ytSideDownload:
        return '動画を保存';
      case _ytSideBackgroundPlayback:
        final provider = context.read<MindMapProvider>();
        return provider.backgroundPlaybackEnabled
            ? provider.t('bg.statusOn')
            : provider.t('bg.statusOff');
    }
    return id;
  }

