  bool _isYoutubeSideActionCurrentlyVisible(String id) {
    final isVideo = (_isYoutube && _currentVideoId != null) || _isMp4;
    final canEmbed = widget.onEmbedUrl != null &&
        (_isEmbeddableYoutubeUrl(_currentUrl) || _currentVideoId != null);
    final canShareUrl = _isYoutube ||
        _currentUrl.startsWith('http://') ||
        _currentUrl.startsWith('https://');
    switch (id) {
      case _ytSideHideUi:
      case _ytSideAiChat:
      case _ytSideUiSettings:
      case _ytSideClose:
      case _ytSideHistoryBack:
      case _ytSideHistoryForward:
      // ── メモは動画を開く前 (検索結果・チャンネル一覧など) でも出す
      //    (= ユーザー要望: 動画を開く前の YouTube の画面の時点でメモ欄や
      //    AI チャット欄を開けるように)。 AI と同じく常時表示。 ──
      case _ytSideMemo:
      // ── 画面更新も動画を開く前の画面で使えるように (= ユーザー要望:
      //    一覧や検索結果の画面にも更新ボタンが欲しい)。 ──
      case _ytSideReload:
        return true;
      case _ytSideShareWithAi:
        return _isYoutube;
      case _ytSideSearch:
        return _isYoutube && !_isMp4;
      case _ytSideEmbed:
        return canEmbed;
      case _ytSidePip:
      case _ytSidePlaybackRate:
      case _ytSideReload:
        return isVideo;
      case _ytSideSplit:
        return widget.onMoveToSplitPanel != null;
      case _ytSideSeekStep:
        return _isMp4;
      case _ytSideCopyUrl:
        return canShareUrl;
      case _ytSidePlaylistPosition:
      case _ytSidePlaylistPrevious:
      case _ytSidePlaylistNext:
        return _playlist.length > 1;
      case _ytSideDownload:
        return _isMp4 &&
            (_currentUrl.startsWith('http://') ||
                _currentUrl.startsWith('https://'));
      case _ytSideBackgroundPlayback:
        return !kIsWeb && Platform.isAndroid && isVideo;
    }
    return false;
  }

  void _setYoutubeUiLayout({bool? sideMenu, bool? sideOnLeft, bool? atBottom}) {
    if (!mounted) return;
    setState(() {
      _youtubeUiLayoutTouched = true;
      if (sideMenu != null) _youtubeControlsInSideMenu = sideMenu;
      if (sideOnLeft != null) _youtubeSideMenuOnLeft = sideOnLeft;
      if (atBottom != null) _youtubeControlsAtBottom = atBottom;
    });
    _saveYoutubeUiLayout();
  }

  void _showYoutubeUiSettings() {
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: const Color(0xFF1E1E32),
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setSheetState) {
          void update({bool? sideMenu, bool? sideOnLeft, bool? atBottom}) {
            _setYoutubeUiLayout(
                sideMenu: sideMenu, sideOnLeft: sideOnLeft, atBottom: atBottom);
            setSheetState(() {});
          }

          // 現在の配置を 'top' / 'bottom' / 'side' の 1 値で表す。
          final placement = _youtubeControlsInSideMenu
              ? 'side'
              : (_youtubeControlsAtBottom ? 'bottom' : 'top');

          void moveAction(String id, int offset) {
            _moveYoutubeSideAction(id, offset);
            setSheetState(() {});
          }

          return SafeArea(
            child: SizedBox(
              height: MediaQuery.sizeOf(sheetContext).height * 0.88,
              child: Padding(
                padding: const EdgeInsets.fromLTRB(16, 12, 16, 20),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(children: [
                      const Icon(Icons.tune_rounded,
                          color: Color(0xFF8C84FF), size: 21),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Text(context.read<MindMapProvider>().t('yt.uiPlacementTitle'),
                            style: TextStyle(
                                color: Colors.white,
                                fontSize: 16,
                                fontWeight: FontWeight.w700)),
                      ),
                      IconButton(
                        onPressed: () => Navigator.pop(sheetContext),
                        icon: const Icon(Icons.close_rounded,
                            color: Colors.white54),
                      ),
                    ]),
                    const SizedBox(height: 10),
                    Expanded(
                      child: ListView(
                        children: [
                          // ── UI の配置: 左 / 右 / 上 / 下 を横一列で選択 ──
                          //   (= ユーザー要望: 上/下/サイドの 3 項目 + サイドの
                          //   左右指定に分けず、 1 行の 4 択にまとめる)。
                          //   左/右 = サイドメニュー、 上 = ヘッダー、 下 = 下部バー。
                          Padding(
                            padding: const EdgeInsets.fromLTRB(16, 4, 16, 8),
                            child: Text(context.read<MindMapProvider>().t('yt.uiPlacement'),
                                style: const TextStyle(
                                    color: Colors.white54, fontSize: 12)),
                          ),
                          Row(children: [
                            for (final item in [
                              (
                                '左',
                                Icons.align_horizontal_left_rounded,
                                placement == 'side' && _youtubeSideMenuOnLeft,
                                () => update(sideMenu: true, sideOnLeft: true),
                              ),
                              (
                                '右',
                                Icons.align_horizontal_right_rounded,
                                placement == 'side' && !_youtubeSideMenuOnLeft,
                                () => update(sideMenu: true, sideOnLeft: false),
                              ),
                              (
                                '上',
                                Icons.vertical_align_top_rounded,
                                placement == 'top',
                                () => update(sideMenu: false, atBottom: false),
                              ),
                              (
                                '下',
                                Icons.vertical_align_bottom_rounded,
                                placement == 'bottom',
                                () => update(sideMenu: false, atBottom: true),
                              ),
                            ]) ...[
                              Expanded(
                                child: ChoiceChip(
                                  selected: item.$3,
                                  showCheckmark: false,
                                  selectedColor: const Color(0xFF8C84FF),
                                  avatar: Icon(item.$2, size: 18),
                                  label: Text(item.$1),
                                  onSelected: (_) => item.$4(),
                                ),
                              ),
                              if (item.$1 != '下') const SizedBox(width: 8),
                            ],
                          ]),
                          // ── ボタンの並び順 ──
                          // ヘッダー表示でも編集できるよう常に表示する
                          //   (= ユーザー要望 2026-07: 配置設定から UI ボタンを
                          //   入れ替えられるように)。 サイドメニューは全ボタン、
                          //   ヘッダーの右上ボタン列も (存在する 4 種の範囲で)
                          //   この順序に従う。
                          ...[
                            const Divider(color: Colors.white12, height: 28),
                            Row(children: [
                              Expanded(
                                child: Text(context.read<MindMapProvider>().t('yt.uiOrder'),
                                    style: TextStyle(
                                        color: Colors.white70,
                                        fontSize: 13,
                                        fontWeight: FontWeight.w700)),
                              ),
                              TextButton.icon(
                                onPressed: () {
                                  _resetYoutubeSideActionOrder();
                                  setSheetState(() {});
                                },
                                icon: const Icon(Icons.restart_alt_rounded,
                                    size: 17),
                                label: Text(context.read<MindMapProvider>().t('yt.uiOrderReset')),
                              ),
                            ]),
                            const SizedBox(height: 4),
                            for (var index = 0;
                                index < _youtubeSideActionOrder.length;
                                index++)
                              Builder(builder: (_) {
                                final id = _youtubeSideActionOrder[index];
                                final currentlyVisible =
                                    _isYoutubeSideActionCurrentlyVisible(id);
                                final color = currentlyVisible
                                    ? Colors.white70
                                    : Colors.white30;
                                return Container(
                                  key: ValueKey('youtube-side-order-$id'),
                                  margin: const EdgeInsets.only(bottom: 6),
                                  padding:
                                      const EdgeInsets.fromLTRB(10, 5, 4, 5),
                                  decoration: BoxDecoration(
                                    color:
                                        Colors.white.withValues(alpha: 0.035),
                                    borderRadius: BorderRadius.circular(9),
                                    border: Border.all(color: Colors.white10),
                                  ),
                                  child: Row(children: [
                                    Icon(_youtubeSideActionIcon(id),
                                        color: color, size: 20),
                                    const SizedBox(width: 10),
                                    Expanded(
                                      child: Column(
                                        crossAxisAlignment:
                                            CrossAxisAlignment.start,
                                        children: [
                                          Text(_youtubeSideActionLabel(id),
                                              style: TextStyle(
                                                  color: color, fontSize: 12)),
                                          if (!currentlyVisible)
                                            Text(
                                                context.read<MindMapProvider>()
                                                    .t('yt.hiddenInThisView'),
                                                style: TextStyle(
                                                    color: Colors.white24,
                                                    fontSize: 9)),
                                        ],
                                      ),
                                    ),
                                    IconButton(
                                      onPressed: index > 0
                                          ? () => moveAction(id, -1)
                                          : null,
                                      constraints: const BoxConstraints(
                                          minWidth: 34, minHeight: 34),
                                      padding: EdgeInsets.zero,
                                      icon: const Icon(
                                          Icons.keyboard_arrow_up_rounded,
                                          size: 22),
                                    ),
                                    IconButton(
                                      onPressed: index <
                                              _youtubeSideActionOrder.length - 1
                                          ? () => moveAction(id, 1)
                                          : null,
                                      constraints: const BoxConstraints(
                                          minWidth: 34, minHeight: 34),
                                      padding: EdgeInsets.zero,
                                      icon: const Icon(
                                          Icons.keyboard_arrow_down_rounded,
                                          size: 22),
                                    ),
                                  ]),
                                );
                              }),
                          ],
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            ),
          );
        },
      ),
    );
  }

