  void _showYoutubePlaybackRateSheet() {
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: const Color(0xFF1E1E32),
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setSheetState) {
          final maxRate = context.read<MindMapProvider>().videoMaxRate;
          final rate = _playbackRate.clamp(1.0, maxRate).toDouble();
          final divisions = ((maxRate - 1.0) * 4).round().clamp(4, 60);
          return SafeArea(
            child: Padding(
              padding: const EdgeInsets.fromLTRB(20, 16, 20, 24),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Row(children: [
                    const Icon(Icons.speed_rounded, color: Color(0xFF4FC3F7)),
                    const SizedBox(width: 10),
                    Text(context.read<MindMapProvider>().t('ve.playbackRate'),
                        style: TextStyle(
                            color: Colors.white,
                            fontSize: 16,
                            fontWeight: FontWeight.w700)),
                    const Spacer(),
                    Text('${rate.toStringAsFixed(2)}x',
                        style: const TextStyle(
                            color: Color(0xFF4FC3F7),
                            fontSize: 16,
                            fontWeight: FontWeight.w700)),
                  ]),
                  Slider(
                    value: rate,
                    min: 1.0,
                    max: maxRate,
                    divisions: divisions,
                    activeColor: const Color(0xFF4FC3F7),
                    onChanged: (value) {
                      _changeRate(value);
                      setSheetState(() {});
                    },
                  ),
                ],
              ),
            ),
          );
        },
      ),
    );
  }

  void _copyCurrentVideoUrl() {
    final provider = context.read<MindMapProvider>();
    final shareUrl = (_currentUrl.isNotEmpty ? _currentUrl : widget.url)
        .replaceFirst('https://m.youtube.com/', 'https://www.youtube.com/')
        .replaceFirst('http://m.youtube.com/', 'https://www.youtube.com/');
    Clipboard.setData(ClipboardData(text: shareUrl));
    _appSnack(
      context,
      SnackBar(
        content: Text(provider.t('ctx.videoUrlCopied')),
        duration: const Duration(seconds: 2),
        backgroundColor: const Color(0xFF2A2A3E),
      ),
    );
  }

  void _embedCurrentYoutubePage() {
    final callback = widget.onEmbedUrl;
    if (callback == null) return;
    var url = _currentUrl;
    if (!_isEmbeddableYoutubeUrl(url) && _currentVideoId != null) {
      url = 'https://m.youtube.com/watch?v=$_currentVideoId';
    }
    if (url.isNotEmpty) callback(url);
  }

  Future<void> _toggleVideoBackgroundPlayback() async {
    if (kIsWeb || !Platform.isAndroid || _backgroundPlaybackToggleBusy) return;
    final provider = context.read<MindMapProvider>();
    final next = !provider.backgroundPlaybackEnabled;
    setState(() => _backgroundPlaybackToggleBusy = true);
    try {
      await provider.setBackgroundPlaybackEnabled(next);
      if (next) {
        // Android の省電力制限対象なら、動画画面から直接除外を依頼する。
        // 拒否された場合も設定自体は保持し、次回この画面を開いた時に再度
        // Foreground Service を開始できるようにする。
        try {
          if (!await Permission.ignoreBatteryOptimizations.isGranted) {
            await Permission.ignoreBatteryOptimizations.request();
          }
        } catch (_) {}
        if (!mounted) return;
        await _initAndStartForegroundService();
      } else {
        // refCount を含めて完全停止し、常駐通知も即座に消す。
        await _BgPlaybackController.forceStop();
      }
      if (!mounted) return;
      _appSnack(
        context,
        SnackBar(
          content: Text(
            next ? provider.t('bg.statusOn') : provider.t('bg.stopped'),
          ),
          backgroundColor:
              next ? const Color(0xFF43B97F) : Colors.redAccent,
          duration: const Duration(seconds: 2),
        ),
      );
    } catch (e) {
      debugPrint('バックグラウンド再生の切り替えに失敗: $e');
      if (next) {
        await provider.setBackgroundPlaybackEnabled(false);
        await _BgPlaybackController.forceStop();
      }
    } finally {
      if (mounted) {
        setState(() => _backgroundPlaybackToggleBusy = false);
      }
    }
  }

  /// YouTube WebView の右端に重ねる共通サイズの丸ボタン。
  /// ヘルプ文や Tooltip は付けず、アイコンだけで構成する。
  /// [framed] = false でヘッダー配置モード用の「○枠なし」 表示
  /// (= ユーザー要望 2026-07: ヘッダーの他のボタンと見た目を揃えるため、
  ///  ヘッダー配置モードのボタンからは丸枠を外す)。
  Widget _buildMobileYoutubeRailButton({
    required Widget icon,
    required Color color,
    required VoidCallback? onTap,
    VoidCallback? onLongPress,
    bool framed = true,
  }) {
    if (!framed) {
      return Material(
        color: Colors.transparent,
        child: InkWell(
          customBorder: const CircleBorder(),
          onTap: onTap,
          onLongPress: onLongPress,
          child: SizedBox(
            width: 40,
            height: 40,
            child: Center(child: icon),
          ),
        ),
      );
    }
    return Material(
      color: Colors.black.withValues(alpha: 0.74),
      shape: CircleBorder(
        side: BorderSide(color: color.withValues(alpha: 0.72)),
      ),
      elevation: 3,
      child: InkWell(
        customBorder: const CircleBorder(),
        onTap: onTap,
        onLongPress: onLongPress,
        child: SizedBox(
          width: 40,
          height: 40,
          child: Center(child: icon),
        ),
      ),
    );
  }

  /// YouTube ホーム・検索・動画のヘッダーに共通4操作を表示する。
  /// ヘッダーの既存順は固定し、サイドの並べ替え設定からは独立させる。
  Widget _buildMobileYoutubeActionRail({Axis axis = Axis.vertical}) {
    final showYoutubeShare = _isYoutube;
    // ── ヘッダー配置モードは丸枠なし (framed:false) ──
    // (= ユーザー要望 2026-07: ヘッダーの他のボタンと種類が異なって見える
    //  ため、 ヘッダー配置モードのボタン UI からは○枠を外す)。
    final visibilityButton = _buildMobileYoutubeRailButton(
      color: const Color(0xFF6C63FF),
      icon: const Icon(Icons.visibility_off_rounded,
          color: Color(0xFF8C84FF), size: 21),
      onTap: _hideFullscreenControls,
      framed: false,
    );
    final aiButton = _buildMobileYoutubeRailButton(
      color: const Color(0xFFBA68C8),
      icon: const Icon(Icons.auto_awesome_rounded,
          color: Color(0xFFCE83D8), size: 21),
      onTap: () => _openMemoTextInAi(''),
      onLongPress: _showMobileVideoAiSettings,
      framed: false,
    );
    final shareButton = showYoutubeShare
        ? _buildMobileYoutubeRailButton(
            color: const Color(0xFF66BB6A),
            icon: _sharingVideoWithBrowserAi
                ? const SizedBox(
                    width: 17,
                    height: 17,
                    child: CircularProgressIndicator(
                      strokeWidth: 2,
                      color: Color(0xFF66BB6A),
                    ),
                  )
                : const Icon(Icons.screen_share_rounded,
                    color: Color(0xFF66BB6A), size: 21),
            onTap: _sharingVideoWithBrowserAi
                ? null
                : _shareCurrentVideoWithBrowserAi,
            onLongPress: _showMobileVideoAiSettings,
            framed: false,
          )
        : const SizedBox(width: 40, height: 40);
    final settingsButton = _buildMobileYoutubeRailButton(
      color: const Color(0xFFFFB347),
      icon: const Icon(Icons.tune_rounded, color: Color(0xFFFFB347), size: 21),
      onTap: _showYoutubeUiSettings,
      framed: false,
    );
    // ── 配置設定の並び順をヘッダーのボタン列にも適用する ──
    // (= ユーザー要望 2026-07: UI ボタンを配置設定から入れ替えられるように)。
    // ヘッダー列に存在する 4 種を _youtubeSideActionOrder の順で並べる。
    Widget buttonFor(String id) {
      switch (id) {
        case _ytSideHideUi:
          return visibilityButton;
        case _ytSideAiChat:
          return aiButton;
        case _ytSideShareWithAi:
          return shareButton;
        default:
          return settingsButton;
      }
    }

    final railIds = <String>[
      for (final id in _youtubeSideActionOrder)
        if (id == _ytSideHideUi ||
            id == _ytSideAiChat ||
            id == _ytSideShareWithAi ||
            id == _ytSideUiSettings)
          id,
    ];
    final buttons = axis == Axis.horizontal
        // 横並びでは非表示ボタンを右端に固定し、非表示後も同じ場所を
        // 透明な復帰領域として使えるようにする。
        ? <Widget>[
            for (final id in railIds)
              if (id != _ytSideHideUi) buttonFor(id),
            visibilityButton,
          ]
        : <Widget>[for (final id in railIds) buttonFor(id)];
    return Flex(
      direction: axis,
      mainAxisSize: MainAxisSize.min,
      children: [
        for (var i = 0; i < buttons.length; i++) ...[
          if (i > 0)
            SizedBox(
                width: axis == Axis.horizontal ? 8 : 0,
                height: axis == Axis.vertical ? 8 : 0),
          buttons[i],
        ],
      ],
    );
  }

  Widget? _buildMobileYoutubeSideAction(String id) {
    if (!_isYoutubeSideActionCurrentlyVisible(id)) return null;
    switch (id) {
      case _ytSideHideUi:
        return _buildMobileYoutubeRailButton(
          color: const Color(0xFF6C63FF),
          icon: const Icon(Icons.visibility_off_rounded,
              color: Color(0xFF8C84FF), size: 21),
          onTap: _hideFullscreenControls,
        );
      case _ytSideAiChat:
        return _buildMobileYoutubeRailButton(
          color: const Color(0xFFBA68C8),
          icon: const Icon(Icons.auto_awesome_rounded,
              color: Color(0xFFCE83D8), size: 21),
          onTap: () => _openMemoTextInAi(''),
          onLongPress: _showMobileVideoAiSettings,
        );
      case _ytSideShareWithAi:
        return _buildMobileYoutubeRailButton(
          // 緑が続くのを避けて青緑へ (= ユーザー要望: 順に色んな色を使う)。
          color: const Color(0xFF26C6DA),
          icon: _sharingVideoWithBrowserAi
              ? const SizedBox(
                  width: 17,
                  height: 17,
                  child: CircularProgressIndicator(
                      strokeWidth: 2, color: Color(0xFF66BB6A)),
                )
              : const Icon(Icons.screen_share_rounded,
                  color: Color(0xFF66BB6A), size: 21),
          onTap: _sharingVideoWithBrowserAi
              ? null
              : _shareCurrentVideoWithBrowserAi,
          onLongPress: _showMobileVideoAiSettings,
        );
      case _ytSideUiSettings:
        return _buildMobileYoutubeRailButton(
          color: const Color(0xFFFFB347),
          icon: const Icon(Icons.tune_rounded,
              color: Color(0xFFFFB347), size: 21),
          onTap: _showYoutubeUiSettings,
        );
      case _ytSideClose:
        return _buildMobileYoutubeRailButton(
          color: const Color(0xFFFF6B6B),
          icon: const Icon(Icons.close_rounded,
              color: Color(0xFFFF8A80), size: 21),
          onTap: () => Navigator.pop(context),
        );
      case _ytSideHistoryBack:
        return _buildMobileYoutubeRailButton(
          color: Colors.white54,
          icon: Icon(Icons.arrow_back_ios_new_rounded,
              color: _canGoBack ? Colors.white70 : Colors.white24, size: 18),
          onTap: _canGoBack
              ? () async {
                  try {
                    await _c?.goBack();
                  } catch (_) {}
                }
              : null,
        );
      case _ytSideHistoryForward:
        return _buildMobileYoutubeRailButton(
          color: Colors.white54,
          icon: Icon(Icons.arrow_forward_ios_rounded,
              color: _canGoForward ? Colors.white70 : Colors.white24, size: 18),
          onTap: _canGoForward
              ? () async {
                  try {
                    await _c?.goForward();
                  } catch (_) {}
                }
              : null,
        );
      case _ytSideSearch:
        return _buildMobileYoutubeRailButton(
          color: const Color(0xFF6C63FF),
          icon: const Icon(Icons.search_rounded,
              color: Color(0xFF8C84FF), size: 21),
          onTap: _showYoutubeSideSearchDialog,
        );
      case _ytSideEmbed:
        return _buildMobileYoutubeRailButton(
          color: const Color(0xFF43B97F),
          icon: const Icon(Icons.add_to_photos_rounded,
              color: Color(0xFF43B97F), size: 21),
          onTap: _embedCurrentYoutubePage,
        );
      case _ytSidePip:
        return _buildMobileYoutubeRailButton(
          color: const Color(0xFF4FC3F7),
          icon: const Icon(Icons.picture_in_picture_alt_rounded,
              color: Color(0xFF4FC3F7), size: 21),
          onTap: _enterPiP,
        );
      case _ytSideSplit:
        return _buildMobileYoutubeRailButton(
          color: _videoSplitDown
              ? const Color(0xFF2196F3)
              : const Color(0xFFFF6B6B),
          icon: _splitPanelIcon(
              _videoSplitDown ? _SplitIconFill.bottom : _SplitIconFill.top,
              color: _videoSplitDown
                  ? const Color(0xFF2196F3)
                  : const Color(0xFFFF6B6B),
              size: 21),
          onTap: () => _moveVideoToSplit(isLeftPanel: !_videoSplitDown),
          onLongPress: () => setState(() => _videoSplitDown = !_videoSplitDown),
        );
      case _ytSideMemo:
        return _buildMobileYoutubeRailButton(
          color: const Color(0xFFFFB347),
          icon: Icon(
            _videoMemoPanelOpen
                ? Icons.sticky_note_2_rounded
                : Icons.sticky_note_2_outlined,
            color: const Color(0xFFFFB347),
            size: 21,
          ),
          onTap: _toggleVideoMemoPanel,
        );
      case _ytSidePlaybackRate:
        return _buildMobileYoutubeRailButton(
          color: const Color(0xFF9CCC65),
          icon: Text('${_playbackRate.toStringAsFixed(1)}x',
              style: const TextStyle(
                  color: Color(0xFF4FC3F7),
                  fontSize: 10,
                  fontWeight: FontWeight.w800)),
          onTap: _showYoutubePlaybackRateSheet,
          onLongPress: () => _showMaxRateDialog(context),
        );
      case _ytSideSeekStep:
        return _buildMobileYoutubeRailButton(
          color: Colors.white54,
          icon: const Icon(Icons.fast_forward_rounded,
              color: Colors.white70, size: 21),
          onTap: () => _showSeekStepDialog(context),
        );
      case _ytSideReload:
        return _buildMobileYoutubeRailButton(
          color: Colors.white54,
          icon: const Icon(Icons.refresh_rounded,
              color: Colors.white70, size: 21),
          onTap: _currentVideoId == null
              ? _reloadCurrentYoutubePage
              : _reloadCurrentVideo,
        );
      case _ytSideCopyUrl:
        return _buildMobileYoutubeRailButton(
          color: const Color(0xFF9575CD),
          icon: const Icon(Icons.share_rounded,
              color: Color(0xFF4FC3F7), size: 21),
          onTap: _copyCurrentVideoUrl,
        );
      case _ytSidePlaylistPosition:
        return SizedBox(
          width: 40,
          height: 24,
          child: Center(
            child: Text('${_playlistIndex + 1}/${_playlist.length}',
                style: const TextStyle(
                    color: Colors.white54,
                    fontSize: 9,
                    fontWeight: FontWeight.w700)),
          ),
        );
      case _ytSidePlaylistPrevious:
        return _buildMobileYoutubeRailButton(
          color: Colors.white54,
          icon: const Icon(Icons.skip_previous_rounded,
              color: Colors.white70, size: 21),
          onTap: _playlistIndex > 0
              ? () {
                  _playlistIndex--;
                  _navigateTo(_playlist[_playlistIndex]);
                }
              : null,
        );
      case _ytSidePlaylistNext:
        return _buildMobileYoutubeRailButton(
          color: Colors.white54,
          icon: const Icon(Icons.skip_next_rounded,
              color: Colors.white70, size: 21),
          onTap: _playlistIndex < _playlist.length - 1
              ? () {
                  _playlistIndex++;
                  _navigateTo(_playlist[_playlistIndex]);
                }
              : null,
        );
      case _ytSideDownload:
        return _buildMobileYoutubeRailButton(
          color: const Color(0xFFFFB347),
          icon: const Icon(Icons.download_rounded,
              color: Color(0xFFFFB347), size: 21),
          onTap: _downloadCurrentVideo,
        );
      case _ytSideBackgroundPlayback:
        final provider = context.watch<MindMapProvider>();
        final enabled = provider.backgroundPlaybackEnabled;
        final statusLabel =
            provider.t(enabled ? 'bg.statusOn' : 'bg.statusOff');
        return Semantics(
          button: true,
          label: provider.t('bg.title'),
          value: statusLabel,
          child: Tooltip(
            message: statusLabel,
            child: _buildMobileYoutubeRailButton(
              color: enabled ? const Color(0xFFFF7AA2) : Colors.white54,
              icon: _backgroundPlaybackToggleBusy
                  ? SizedBox(
                      width: 17,
                      height: 17,
                      child: CircularProgressIndicator(
                        strokeWidth: 2,
                        color:
                            enabled ? const Color(0xFFFF7AA2) : Colors.white70,
                      ),
                    )
                  : Icon(
                      enabled
                          ? Icons.play_circle_fill_rounded
                          : Icons.play_circle_outline_rounded,
                      color:
                          enabled ? const Color(0xFFFF7AA2) : Colors.white70,
                      size: 21,
                    ),
              onTap: _backgroundPlaybackToggleBusy
                  ? null
                  : _toggleVideoBackgroundPlayback,
            ),
          ),
        );
    }
    // 新しいバージョンの設定値など未知 ID が来ても描画を止めない。
    return null;
  }

  Widget _buildMobileYoutubeSideMenu() {
    final controls = <Widget>[];
    for (final id in _youtubeSideActionOrder) {
      final control = _buildMobileYoutubeSideAction(id);
      if (control == null) continue;
      controls.add(KeyedSubtree(
        key: ValueKey('youtube-side-action-$id'),
        child: control,
      ));
    }
    return Container(
      width: 56,
      color: Colors.black,
      alignment: Alignment.topCenter,
      padding: const EdgeInsets.only(top: 8),
      child: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            for (var i = 0; i < controls.length; i++) ...[
              if (i > 0) const SizedBox(height: 8),
              controls[i],
            ],
            const SizedBox(height: 8),
          ],
        ),
      ),
    );
  }

  Widget _buildHiddenYoutubeControlsRestoreTarget() {
    final inSideMenu = _youtubeControlsInSideMenu;
    final onLeft = inSideMenu && _youtubeSideMenuOnLeft;
    // 下部配置時は復帰領域も画面下中央に置く (= ユーザー要望)。
    final atBottom = !inSideMenu && _youtubeControlsAtBottom;
    // サイドでは「UIを隠す」も並べ替え可能なため、非表示直前の位置がどこでも
    // 同じサイド領域を押せば復元できるよう、透明な復帰領域を縦全体に保つ。
    return Positioned(
      top: (inSideMenu || !atBottom) ? 0 : null,
      bottom: inSideMenu ? 0 : (atBottom ? 0 : null),
      // ヘッダー配置時は YouTube の検索欄と重なる右端を避け、上/下中央に置く。
      // サイド配置時だけ従来どおり左右端の復帰領域を維持する。
      left: inSideMenu
          ? (onLeft ? 0 : null)
          : (MediaQuery.sizeOf(context).width - 56) / 2,
      right: inSideMenu ? (onLeft ? null : 0) : null,
      width: 56,
      height: inSideMenu ? null : 56,
      child: Semantics(
        button: true,
        label: 'YouTube UIを再表示',
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: _restoreFullscreenControls,
          child: const SizedBox.expand(),
        ),
      ),
    );
  }

  /// モバイル YouTube のヘッダー配置。
  ///
  /// ブラウズ中は全操作を一段の横スクロール列へまとめる。動画視聴中は、
  /// 一段目を閉じる・履歴・更新・再生速度だけに固定し、残りを二段目へ送る。
  Widget _buildMobileYoutubeHeader(bool isVideo) {
    if (!isVideo) {
      const leadingIds = <String>[
        _ytSideClose,
        _ytSideHistoryBack,
        _ytSideHistoryForward,
        _ytSideReload,
        // 非表示ボタンを右端へ置かず、画面上中央付近へ来る順にする。
        _ytSideHideUi,
      ];
      final ids = <String>[
        ...leadingIds,
        for (final id in _youtubeSideActionOrder)
          if (!leadingIds.contains(id)) id,
      ];
      return Container(
        height: 52,
        color: Colors.black,
        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
        child: SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          physics: const ClampingScrollPhysics(),
          child: Row(
            children: [
              for (final id in ids)
                if (_buildMobileYoutubeSideAction(id) case final control?) ...[
                  control,
                  const SizedBox(width: 6),
                ],
            ],
          ),
        ),
      );
    }

    const primaryIds = <String>{
      _ytSideClose,
      _ytSideHistoryBack,
      _ytSideHistoryForward,
      _ytSideReload,
      _ytSidePlaybackRate,
    };
    final secondaryIds = <String>[
      for (final id in _youtubeSideActionOrder)
        if (!primaryIds.contains(id)) id,
    ];
    final provider = context.read<MindMapProvider>();
    final maxRate = context.watch<MindMapProvider>().videoMaxRate;
    final divisions = ((maxRate - 1.0) * 4).round().clamp(4, 60);

    return Container(
      color: Colors.black,
      padding: const EdgeInsets.fromLTRB(4, 3, 4, 4),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          // 一段目: 閉じる / 戻る / 進む / 更新 / 速度バー / 速度設定
          Row(
            children: [
              IconButton(
                tooltip: context.read<MindMapProvider>().t('btn.close'),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 36, minHeight: 36),
                icon: const Icon(Icons.close_rounded,
                    color: Color(0xFFFF8A80), size: 22),
                onPressed: () => Navigator.pop(context),
              ),
              IconButton(
                tooltip: provider.t('fsv.backHistory'),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 32, minHeight: 36),
                icon: Icon(Icons.arrow_back_ios_new_rounded,
                    color: _canGoBack ? Colors.white70 : Colors.white24,
                    size: 18),
                onPressed: _canGoBack
                    ? () async {
                        try {
                          await _c?.goBack();
                        } catch (_) {}
                      }
                    : null,
              ),
              IconButton(
                tooltip: provider.t('fsv.forwardHistory'),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 32, minHeight: 36),
                icon: Icon(Icons.arrow_forward_ios_rounded,
                    color: _canGoForward ? Colors.white70 : Colors.white24,
                    size: 18),
                onPressed: _canGoForward
                    ? () async {
                        try {
                          await _c?.goForward();
                        } catch (_) {}
                      }
                    : null,
              ),
              IconButton(
                tooltip: provider.t('fsv.reloadVideo'),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 34, minHeight: 36),
                icon: const Icon(Icons.refresh_rounded,
                    color: Colors.white70, size: 20),
                onPressed: _reloadCurrentVideo,
              ),
              Text('${_playbackRate.toStringAsFixed(2)}x',
                  style: const TextStyle(color: Colors.white54, fontSize: 10)),
              Expanded(
                child: SliderTheme(
                  data: SliderThemeData(
                    trackHeight: 2,
                    thumbShape:
                        const RoundSliderThumbShape(enabledThumbRadius: 5),
                    activeTrackColor: Colors.white.withValues(alpha: 0.5),
                    inactiveTrackColor: Colors.white.withValues(alpha: 0.15),
                    thumbColor: Colors.white,
                    overlayShape:
                        const RoundSliderOverlayShape(overlayRadius: 10),
                  ),
                  child: Slider(
                    value: _playbackRate.clamp(1.0, maxRate),
                    min: 1.0,
                    max: maxRate,
                    divisions: divisions,
                    onChanged: _changeRate,
                  ),
                ),
              ),
              IconButton(
                tooltip: provider.t('video.tip.maxRate'),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 32, minHeight: 36),
                icon: const Icon(Icons.tune_rounded,
                    color: Color(0xFFFFB347), size: 19),
                onPressed: () => _showMaxRateDialog(context),
              ),
            ],
          ),
          // 二段目: その他。収まり切らない操作は横スクロールで表示する。
          SizedBox(
            height: 48,
            child: SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              physics: const ClampingScrollPhysics(),
              child: Row(
                children: [
                  for (final id in secondaryIds)
                    if (_buildMobileYoutubeSideAction(id)
                        case final control?) ...[
                      control,
                      const SizedBox(width: 6),
                    ],
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  /// 書いたメモを後から書き直す (= ユーザー要望)。 モバイルは行の
  /// ダブルタップ / 鉛筆ボタンで開く。
  Future<void> _editVideoMemo(_VideoMemoEntry entry) async {
    final next = await _showVideoMemoEditDialog(context, entry.text);
    if (next == null || !mounted) return;
    setState(() => entry.text = next);
    await _persistVideoMemos();
  }

