  /// ローカル動画ファイル用の Flutter ネイティブ再生 UI を構築する。
  /// WebView を一切使わないので native の `<video controls>` UI による
  /// 速度キャップ (= Android の 2x 制限) が原理的に発生しない。
  ///
  /// レイアウト:
  ///   - 中央: VideoPlayer (アスペクト比保持)
  ///   - 中央オーバーレイ: 大きな再生 / 一時停止ボタン (タップでトグル)
  ///   - 下部: シークバー (VideoProgressIndicator) + 現在時間 / 総時間
  ///   - 動画タップ: コントロール表示 / 非表示トグル + 自動 hide タイマー
  ///
  /// `_vpc` がまだ null の時 (= 初期化中) はローディング、初期化に
  /// 失敗 (`_loading` が false かつ `_vpc` が null) の時はエラー表示。
  Widget _buildLocalVideoPlayer() {
    final vpc = _vpc;
    final hasRuntimeError = vpc != null && _vpcErrorMessage != null;
    if (vpc == null || !vpc.value.isInitialized || hasRuntimeError) {
      // 初期化中
      if (_loading && _vpcErrorMessage == null) {
        return const Center(
          child: CircularProgressIndicator(
              valueColor: AlwaysStoppedAnimation(Color(0xFF6C63FF))),
        );
      }
      // エラー画面: 詳細メッセージ + アクションボタン
      final detailMsg = _vpcErrorMessage ?? '動画を読み込めませんでした\n(初期化に失敗、詳細不明)';
      final currentUrl = _playlist[_playlistIndex];
      return SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const SizedBox(height: 40),
            Row(children: const [
              Icon(Icons.error_outline_rounded,
                  color: Color(0xFFFFB347), size: 32),
              SizedBox(width: 12),
              Text(
                '動画を読み込めませんでした',
                style: TextStyle(
                    color: Colors.white,
                    fontSize: 16,
                    fontWeight: FontWeight.w600),
              ),
            ]),
            const SizedBox(height: 16),
            // 詳細メッセージ (選択可能 = ユーザーがコピーして開発者に渡せる)
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: Colors.white.withValues(alpha: 0.06),
                borderRadius: BorderRadius.circular(8),
                border: Border.all(color: Colors.white.withValues(alpha: 0.15)),
              ),
              child: SelectableText(
                detailMsg,
                style: const TextStyle(
                    color: Colors.white70,
                    fontSize: 12,
                    fontFamily: 'monospace',
                    height: 1.5),
              ),
            ),
            const SizedBox(height: 16),
            // 再試行 / 外部アプリで開くボタン
            Wrap(spacing: 8, runSpacing: 8, children: [
              ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6C63FF),
                  foregroundColor: Colors.white,
                ),
                icon: const Icon(Icons.refresh_rounded, size: 16),
                label: Text(context.read<MindMapProvider>().t('fsv.retry'),
                    style: const TextStyle(fontSize: 12)),
                onPressed: () async {
                  // 古い controller を破棄してから initLocalVideoPlayer を
                  // やり直す
                  setState(() {
                    _vpcErrorMessage = null;
                    _loading = true;
                  });
                  _vpcUiTimer?.cancel();
                  _vpcUiTimer = null;
                  final old = _vpc;
                  _vpc = null;
                  try {
                    old?.removeListener(_onVpcValueChanged);
                  } catch (_) {}
                  try {
                    await old?.dispose();
                  } catch (_) {}
                  await _initLocalVideoPlayer(currentUrl);
                },
              ),
              // ── WebView 経路で再生 ──
              // VideoPlayer (ExoPlayer / AVPlayer) が初期化失敗する動画
              // でも、WebView の `<video>` 経路ならコーデック対応範囲が
              // 違うので再生できることがある。速度上限が native UI で
              // 2x になる代わり、最低限再生はできる救済手段。
              ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF43B97F),
                  foregroundColor: Colors.white,
                ),
                icon: const Icon(Icons.web_rounded, size: 16),
                label: Text(
                    context.read<MindMapProvider>().t('fsv.playInWebview'),
                    style: const TextStyle(fontSize: 12)),
                onPressed: () async {
                  // VideoPlayer を完全に破棄して、build を WebView 経路に
                  // 切り替える。
                  _vpcUiTimer?.cancel();
                  _vpcUiTimer = null;
                  _vpcControlsHideTimer?.cancel();
                  _vpcControlsHideTimer = null;
                  final old = _vpc;
                  _vpc = null;
                  try {
                    old?.removeListener(_onVpcValueChanged);
                  } catch (_) {}
                  try {
                    await old?.dispose();
                  } catch (_) {}
                  if (!mounted) return;
                  setState(() {
                    _useWebViewFallback = true;
                    _fallbackHtmlLoaded = false;
                    _vpcErrorMessage = null;
                    _loading = true;
                  });
                },
              ),
              OutlinedButton.icon(
                style: OutlinedButton.styleFrom(
                  foregroundColor: Colors.white70,
                  side: const BorderSide(color: Colors.white30),
                ),
                icon: const Icon(Icons.open_in_new_rounded, size: 16),
                label: Text(context.read<MindMapProvider>().t('fsv.openInApp'),
                    style: const TextStyle(fontSize: 12)),
                onPressed: () async {
                  try {
                    await OpenFilex.open(currentUrl);
                  } catch (e) {
                    debugPrint('OpenFilex failed: $e');
                  }
                },
              ),
            ]),
            const SizedBox(height: 12),
            Text(
              '考えられる原因:\n'
              '・ファイルが破損している (ダウンロードが途中で中断)\n'
              '・コンテナ形式が ExoPlayer / AVPlayer に未対応\n'
              '・コーデック不一致',
              style: TextStyle(
                  color: Colors.white.withValues(alpha: 0.45),
                  fontSize: 11,
                  height: 1.6),
            ),
          ],
        ),
      );
    }
    final v = vpc.value;
    final isPlaying = v.isPlaying;
    final pos = v.position;
    final dur = v.duration;
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: () {
        // タップでコントロール表示トグル。表示にしたら自動 hide を再スケジュール。
        setState(() => _vpcShowControls = !_vpcShowControls);
        if (_vpcShowControls) _scheduleHideVpcControls();
      },
      child: Container(
        color: Colors.black,
        child: Column(children: [
          // 動画本体
          Expanded(
            child: Stack(alignment: Alignment.center, children: [
              Center(
                child: AspectRatio(
                  aspectRatio: v.aspectRatio == 0 ? 16 / 9 : v.aspectRatio,
                  child: VideoPlayer(vpc),
                ),
              ),
              // 中央の大きな再生 / 一時停止ボタン
              if (_vpcShowControls)
                GestureDetector(
                  onTap: () {
                    setState(() {
                      if (isPlaying) {
                        vpc.pause();
                      } else {
                        vpc.play();
                        _scheduleHideVpcControls();
                      }
                    });
                  },
                  child: Container(
                    decoration: BoxDecoration(
                      color: Colors.black.withValues(alpha: 0.5),
                      shape: BoxShape.circle,
                    ),
                    padding: const EdgeInsets.all(18),
                    child: Icon(
                      isPlaying
                          ? Icons.pause_rounded
                          : Icons.play_arrow_rounded,
                      color: Colors.white,
                      size: 48,
                    ),
                  ),
                ),
            ]),
          ),
          // 下部のシークバー + 時間表示
          if (_vpcShowControls)
            Container(
              color: Colors.black.withValues(alpha: 0.7),
              padding: const EdgeInsets.fromLTRB(12, 6, 12, 8),
              child: Column(children: [
                // シークバー (タップ・ドラッグで現在位置を変更可能)
                VideoProgressIndicator(
                  vpc,
                  allowScrubbing: true,
                  colors: const VideoProgressColors(
                    playedColor: Color(0xFF6C63FF),
                    bufferedColor: Colors.white24,
                    backgroundColor: Colors.white10,
                  ),
                  padding: const EdgeInsets.symmetric(vertical: 6),
                ),
                const SizedBox(height: 4),
                // 現在 / 総時間
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      _formatVpcDuration(pos),
                      style: const TextStyle(
                          color: Colors.white70,
                          fontSize: 11,
                          fontFeatures: [FontFeature.tabularFigures()]),
                    ),
                    Text(
                      _formatVpcDuration(dur),
                      style: const TextStyle(
                          color: Colors.white54,
                          fontSize: 11,
                          fontFeatures: [FontFeature.tabularFigures()]),
                    ),
                  ],
                ),
              ]),
            ),
        ]),
      ),
    );
  }

  /// 動画再生速度の上限を変更するダイアログ (IAW 版)。
  /// Windows 版と同じ実装で _showMaxRateDialog としても機能を共有可能だが、
  /// State クラスごとに独立して動作させるため別メソッドで提供する。
  Future<void> _showMaxRateDialog(BuildContext ctx) async {
    final p = ctx.read<MindMapProvider>();
    double tmpMax = p.videoMaxRate;
    final result = await showDialog<double>(
      context: ctx,
      builder: (dctx) {
        return StatefulBuilder(builder: (sctx, ss) {
          final divs = ((16.0 - 1.5) * 2).round();
          return AlertDialog(
            backgroundColor: const Color(0xFF1E1E32),
            title: Row(children: [
              const Icon(Icons.speed_rounded,
                  color: Color(0xFFFFB347), size: 20),
              const SizedBox(width: 8),
              Text(p.t('video.maxRate.title'),
                  style: const TextStyle(color: Colors.white, fontSize: 15)),
            ]),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(p.t('video.maxRate.body'),
                    style:
                        const TextStyle(color: Colors.white70, fontSize: 12)),
                const SizedBox(height: 16),
                Center(
                  child: Text('${tmpMax.toStringAsFixed(1)}x',
                      style: const TextStyle(
                          color: Color(0xFFFFB347),
                          fontSize: 32,
                          fontWeight: FontWeight.w700)),
                ),
                Slider(
                  value: tmpMax,
                  min: 1.5,
                  max: 16.0,
                  divisions: divs,
                  activeColor: const Color(0xFFFFB347),
                  inactiveColor: Colors.white24,
                  label: '${tmpMax.toStringAsFixed(1)}x',
                  onChanged: (v) => ss(() => tmpMax = v),
                ),
                const SizedBox(height: 4),
                Wrap(
                  spacing: 6,
                  runSpacing: 6,
                  children: [2.0, 5.0, 8.0, 10.0, 16.0].map((preset) {
                    final selected = (tmpMax - preset).abs() < 0.01;
                    return ActionChip(
                      label: Text('${preset.toStringAsFixed(0)}x',
                          style: TextStyle(
                              color: selected ? Colors.black : Colors.white,
                              fontSize: 11,
                              fontWeight: FontWeight.w700)),
                      backgroundColor: selected
                          ? const Color(0xFFFFB347)
                          : const Color(0xFF2A2A3E),
                      onPressed: () => ss(() => tmpMax = preset),
                    );
                  }).toList(),
                ),
                const SizedBox(height: 8),
                if (tmpMax > 8.0)
                  Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: const Color(0xFFFF6B6B).withValues(alpha: 0.15),
                      borderRadius: BorderRadius.circular(6),
                      border: Border.all(
                          color:
                              const Color(0xFFFF6B6B).withValues(alpha: 0.5)),
                    ),
                    child: Row(children: [
                      const Icon(Icons.warning_amber_rounded,
                          color: Color(0xFFFF6B6B), size: 14),
                      const SizedBox(width: 6),
                      Expanded(
                        child: Text(p.t('video.maxRate.warning'),
                            style: const TextStyle(
                                color: Color(0xFFFF6B6B), fontSize: 10)),
                      ),
                    ]),
                  ),
              ],
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dctx, null),
                child: Text(p.t('btn.cancel')),
              ),
              ElevatedButton(
                style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFFFFB347),
                    foregroundColor: Colors.black),
                onPressed: () => Navigator.pop(dctx, tmpMax),
                child: Text(p.t('btn.ok'),
                    style: const TextStyle(
                        color: Colors.black, fontWeight: FontWeight.w700)),
              ),
            ],
          );
        });
      },
    );
    if (result != null) {
      await p.setVideoMaxRate(result);
    }
  }

