      },
    );
    if (result != null) {
      await p.setVideoSeekSeconds(result);
    }
  }

  /// タイトルから不要なサフィックスを除去
  String _cleanTitle(String raw) {
    if (raw.isEmpty) return '';
    if (raw.startsWith('data:')) {
      final originalUrl = _playlist[_playlistIndex];
      final name = originalUrl.split('/').last.split('\\').last;
      return name.length > 60 ? '${name.substring(0, 57)}...' : name;
    }
    var cleaned = raw
        .replaceAll(RegExp(r'\s*[-–—]\s*YouTube\s*$', caseSensitive: false), '')
        .replaceAll(
            RegExp(r'\s*[-–—]\s*m\.youtube\.com\s*$', caseSensitive: false), '')
        .trim();
    // "YouTube" / "youtube.com" だけのプレースホルダーは空扱いにする。
    // (SPA で動画タイトルが届く前の初期表示。表示すると味気ない上に
    //  実タイトルが取れたら上書きしたいので、空にして polling で取り直す)
    final lc = cleaned.toLowerCase();
    if (lc == 'youtube' || lc == 'youtube.com' || lc == 'm.youtube.com') {
      return '';
    }
    if (cleaned.length > 80) cleaned = '${cleaned.substring(0, 77)}...';
    return cleaned;
  }

  /// YouTube SPA はページロード完了後に少し遅れて動画タイトルが
  /// document.title に反映されるため、複数回ポーリングして取得する。
  /// 動画再生ページかつ現在タイトルが空 (またはプレースホルダー) の時のみ実行。
  void _pollVideoTitle() {
    if (!_isYoutube) return;
    if (!_currentUrl.contains('/watch') &&
        !_currentUrl.contains('/shorts/') &&
        !_currentUrl.contains('youtu.be/')) {
      return;
    }
    // 500ms / 1.5s / 3s / 5s / 8s でリトライ
    for (final delayMs in [500, 1500, 3000, 5000, 8000]) {
      Future.delayed(Duration(milliseconds: delayMs), () async {
        if (!mounted) return;
        if (_currentTitle.isNotEmpty) return; // すでに取れていれば終了
        try {
          // og:title メタタグを優先 (YouTube では document.title より早く確定する)
          final result = await _c?.evaluateJavascript(source: r'''
            (function() {
              try {
                var meta = document.querySelector('meta[property="og:title"]');
                var t = meta ? (meta.getAttribute('content') || '') : '';
                if (!t) {
                  t = document.title || '';
                  t = t.replace(/\s*-\s*YouTube\s*$/i, '').trim();
                }
                return t;
              } catch(e) { return ''; }
            })();
          ''');
          if (!mounted) return;
          if (result == null) return;
          final title = result.toString();
          if (title.isEmpty || title.toLowerCase() == 'youtube') return;
          setState(() => _currentTitle = _cleanTitle(title));
        } catch (_) {}
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    // YouTube ホーム / 検索 / チャンネルはブラウズ画面であり動画ではない。
    // videoId を取得できた watch/shorts ページだけ、速度等の動画専用行を出す。
    final isVideo = (_isYoutube && _currentVideoId != null) || _isMp4;
    final useManualSplitTooltip =
        defaultTargetPlatform == TargetPlatform.android ||
            defaultTargetPlatform == TargetPlatform.iOS ||
            defaultTargetPlatform == TargetPlatform.fuchsia;
    final hasYoutubeActionUi = _isYoutube || _isMp4;
    final useYoutubeSideMenu = hasYoutubeActionUi && _youtubeControlsInSideMenu;
    // = ユーザー要望: ヘッダー操作列を画面「下部」にも置けるように。
    final useYoutubeBottomBar = hasYoutubeActionUi &&
        !_youtubeControlsInSideMenu &&
        _youtubeControlsAtBottom;
    // ── 戻るボタン傍受: バックグラウンド再生 ON で動画再生中なら PiP に自動切替 ──
    // ユーザー要望: 「バックグラウンド再生状態から動画に戻ってきて画面を閉じる
    // とバックグラウンドが止まってしまう」 → 戻るボタンで素直に pop すると、
    // dispose で _stopForegroundService が呼ばれて Service が止まる。
    // PiP に切り替えてから閉じれば PiP 側で acquire を維持するので継続できる。
    //
    // 条件:
    //   - Android のみ (iOS / Web は PiP 経路と Service 経路がない)
    //   - バックグラウンド再生 ON
    //   - 動画ページ (YouTube / mp4) であること = isVideo
    // 上記すべてを満たす時、戻る → _enterPiP() で PiP に切り替えて閉じる。
    // それ以外は通常通り pop。
    return PopScope(
      // ── 戻るジェスチャー: PiP にせず「単に戻る」 (= ユーザー要望) ──
      // 常に横取りし、WebView の履歴を 1 つ戻るだけにする。履歴が無い
      // （YouTube ホーム等）ときは何もしない＝画面を閉じない。
      // 閉じたいときは左上の ← (Navigator.pop) ボタンを使う。
      canPop: false,
      onPopInvokedWithResult: (didPop, _) async {
        if (didPop) return;
        // ── コメント欄などのパネルが開いていたら、 1 回目の戻るは
        //    パネルを閉じるだけにする (= ユーザー要望)。 もう一度戻ると
        //    パネルが無いので通常どおりページが戻る。 ──
        try {
          final r = await _c?.evaluateJavascript(source: _kCloseYtPanelJs);
          if ('$r'.contains('closed')) return;
        } catch (_) {}
        if (_canGoBack) {
          try {
            await _c?.goBack();
          } catch (_) {}
        }
        // _canGoBack == false（ホーム等）→ 何もしない（閉じない）。
      },
      child: Scaffold(
        backgroundColor: Colors.black,
        body: SafeArea(
          bottom: false,
          child: Stack(
            children: [
              Row(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  if (!_hideAllControls &&
                      useYoutubeSideMenu &&
                      _youtubeSideMenuOnLeft)
                    _buildMobileYoutubeSideMenu(),
                  Expanded(
                    child: Column(children: [
                      // ── 上部バー (2 段構成) ──
                      // 1段目: [戻る] [タイトル] [マップに追加 / プレイリスト ナビ]
                      // 2段目: [WebView 戻る] [WebView 進む]  速度x [─ slider ─] [再読込]
                      // タイトルが長い時に再生速度バー達と争って省略されてしまう問題への対処。
                      // 動画ページ以外 (検索/チャンネル/一般 URL) では 2 段目は描画しない。
                      // UI を隠した後の復元操作も WebView 右端の固定レールが担当する。
                      // 下部配置 (useYoutubeBottomBar) の時は上には出さず、
                      // WebView の下 (Column 末尾) に同じヘッダーを描画する。
                      if (!_hideAllControls &&
                          !useYoutubeSideMenu &&
                          !useYoutubeBottomBar &&
                          hasYoutubeActionUi)
                        _buildMobileYoutubeHeader(isVideo),
                      // YouTube / mp4 は上の専用モバイルヘッダーを使う。一般 URL の
                      // ビューアだけは既存ヘッダーを維持する。
                      if (!_hideAllControls &&
                          !useYoutubeSideMenu &&
                          !hasYoutubeActionUi)
                        Container(
                          color: Colors.black,
                          padding: const EdgeInsets.symmetric(
                              horizontal: 8, vertical: 4),
                          child: Column(children: [
                            if (hasYoutubeActionUi && !useYoutubeSideMenu)
                              Align(
                                alignment: Alignment.centerRight,
                                child: _buildMobileYoutubeActionRail(
                                    axis: Axis.horizontal),
                              ),
                            // 1段目
                            Row(children: [
                              IconButton(
                                icon: const Icon(Icons.arrow_back,
                                    color: Colors.white, size: 22),
                                onPressed: () => Navigator.pop(context),
                              ),
                              // ── ブラウザ履歴の戻る / 進む ──
                              // 動画ページに限らず常時表示する (= Instagram などで
                              // 「ジェスチャー戻ろうとしてアプリ自体が閉じる」要望対応)。
                              // 動画ページの 2 段目にも別の戻る/進むがあるが、そちらは
                              // 動画コントロールに隣接しているのでこちらは独立。
                              IconButton(
                                tooltip: context
                                    .read<MindMapProvider>()
                                    .t('fsv.backHistory'),
                                padding: EdgeInsets.zero,
                                constraints: const BoxConstraints(
                                    minWidth: 32, minHeight: 32),
                                icon: Icon(Icons.arrow_back_ios_new_rounded,
                                    color: _canGoBack
                                        ? Colors.white70
                                        : Colors.white24,
                                    size: 18),
                                onPressed: _canGoBack
                                    ? () async {
                                        try {
                                          await _c?.goBack();
                                        } catch (_) {}
                                      }
                                    : null,
                              ),
                              IconButton(
                                tooltip: context
                                    .read<MindMapProvider>()
                                    .t('fsv.forwardHistory'),
                                padding: EdgeInsets.zero,
                                constraints: const BoxConstraints(
                                    minWidth: 32, minHeight: 32),
                                icon: Icon(Icons.arrow_forward_ios_rounded,
                                    color: _canGoForward
                                        ? Colors.white70
                                        : Colors.white24,
                                    size: 18),
                                onPressed: _canGoForward
                                    ? () async {
                                        try {
                                          await _c?.goForward();
                                        } catch (_) {}
                                      }
                                    : null,
                              ),
                              // ── 動画タイトルの表示は削除 (= ユーザー要望 2026-07:
                              //   「UI配置設定ボタンの下に動画タイトル等を表示しないで、
                              //   邪魔」)。 タイトルはタブや共有時のメタ情報としては
                              //   引き続き保持する (_currentTitle) が、 バーには出さない。
                              const Spacer(),
                              // ── マップに埋め込むボタン (YouTube 動画 / チャンネルのみ) ──
                              // 表示条件: `_isEmbeddableYoutubeUrl(_currentUrl)` でカバー
                              // できない瞬間 (SPA 遷移直後など) でも、`_currentVideoId` が
                              // セット済みなら動画ページとみなしてボタンを残す。これに
                              // より「動画再生中に埋め込みボタンが消える」現象を防ぐ。
                              if (widget.onEmbedUrl != null &&
                                  (_isEmbeddableYoutubeUrl(_currentUrl) ||
                                      _currentVideoId != null))
                                IconButton(
                                  tooltip: context
                                      .read<MindMapProvider>()
                                      .t('vmemo.addToMap'),
                                  padding: EdgeInsets.zero,
                                  constraints: const BoxConstraints(
                                      minWidth: 32, minHeight: 32),
                                  icon: const Icon(Icons.add_to_photos_rounded,
                                      color: Color(0xFF43B97F), size: 22),
                                  onPressed: () {
                                    // 埋め込み対象 URL は `_currentUrl` を優先するが、もし
                                    // 一時的に動画 URL から離れた状態 (広告等) なら、最後
                                    // に判定された動画 ID から watch URL を再構成する。
                                    String url = _currentUrl;
                                    if (!_isEmbeddableYoutubeUrl(url) &&
                                        _currentVideoId != null) {
                                      url =
                                          'https://m.youtube.com/watch?v=$_currentVideoId';
                                    }
                                    // ── ユーザー要望: 埋め込みボタンを押しても Player は閉じない ──
                                    // Navigator.pop を外し、 埋め込み後もそのまま視聴を続けられる
                                    // ようにする (= マップへの追加は onEmbedUrl 内で完結する)。
                                    widget.onEmbedUrl!(url);
                                  },
                                ),
                              // ── PiP (アプリ内ピクチャインピクチャ) ──
                              // 動画再生ページに限り表示。タップでミニプレイヤーに移行。
                              // フルスクリーンを閉じてもアプリ内に小さな WebView が残り
                              // 動画を続けて視聴できる。
                              // 表示条件:
                              //   (a) YouTube 動画 (videoId 取得済み)
                              //   (b) mp4 / ローカル動画 (= ダウンロード済みオフライン動画)
                              //   いずれも _enterPiP 側で適切なモード (YouTube / Local /
                              //   URL) に振り分けられる。
                              if ((_isYoutube && _currentVideoId != null) ||
                                  _isMp4)
                                IconButton(
                                  tooltip: context
                                      .read<MindMapProvider>()
                                      .t('fsv.pip'),
                                  padding: EdgeInsets.zero,
                                  constraints: const BoxConstraints(
                                      minWidth: 32, minHeight: 32),
                                  icon: const Icon(
                                      Icons.picture_in_picture_alt_rounded,
                                      color: Color(0xFF4FC3F7),
                                      size: 22),
                                  onPressed: _enterPiP,
                                ),
                              // ── 画面分割で開く ボタン ──
                              // 現在の URL を MindMapScreen の画面分割パネルへ引き継ぎつつ
                              // このフルスクリーンページを閉じる。 動画/PDF を見ながら
                              // マップを編集できる「真の画面分割」 状態に遷移する。
                              // onMoveToSplitPanel が渡されていない場合は非表示。
                              if (widget.onMoveToSplitPanel != null)
                                // ── 画面分割ボタン (1 つに統合 / 長押しで上・下を切替) ──
                                // ユーザー要望: 長押しで「上に分割 / 下に分割」 を切り替えて、
                                //   アイコンもその方向 (上/下) に切り変わるように。 タップは
                                //   現在の方向で分割する。
                                GestureDetector(
                                  behavior: HitTestBehavior.opaque,
                                  onTap: () => _moveVideoToSplit(
                                      isLeftPanel: !_videoSplitDown),
                                  onLongPressStart: (_) {
                                    setState(() =>
                                        _videoSplitDown = !_videoSplitDown);
                                    if (!useManualSplitTooltip) return;
                                    WidgetsBinding.instance
                                        .addPostFrameCallback((_) {
                                      if (!mounted) return;
                                      _videoSplitTooltipKey.currentState
                                          ?.ensureTooltipVisible();
                                    });
                                  },
                                  child: Padding(
                                    padding: EdgeInsets.all(6),
                                    child: Tooltip(
                                      key: _videoSplitTooltipKey,
                                      triggerMode: useManualSplitTooltip
                                          ? TooltipTriggerMode.manual
                                          : TooltipTriggerMode.longPress,
                                      message: context
                                          .read<MindMapProvider>()
                                          .t('split.openSplitTip'),
                                      child: _splitPanelIcon(
                                          _videoSplitDown
                                              ? _SplitIconFill.bottom
                                              : _SplitIconFill.top,
                                          color: _videoSplitDown
                                              ? const Color(0xFF2196F3)
                                              : const Color(0xFFFF6B6B),
                                          size: 22),
                                    ),
                                  ),
                                ),
                              // ── メモボタン (動画視聴中にメモを取る) ──
                              // タップで画面の上にメモパネルが下からせり上がる。
                              // 動画は止めずに視聴を続けながら入力でき、 「マップに追加」 で
                              // メモノードとしてキャンバス上に配置できる。
                              // ── 動画を開く前 (YouTube の検索/一覧の画面) でも
                              //    出す (= ユーザー要望: 動画を開く前の画面の
                              //    時点でメモ欄や AI チャット欄を開けるように)。
                              //    メモパネルは再生ソースに依存しない (再生位置を
                              //    含めるのは任意) ので、 動画判定を外す。 ──
                              IconButton(
                                tooltip: context
                                    .read<MindMapProvider>()
                                    .t('player.takeMemo'),
                                padding: EdgeInsets.zero,
                                constraints: const BoxConstraints(
                                    minWidth: 32, minHeight: 32),
                                icon: Icon(
                                  _videoMemoPanelOpen
                                      ? Icons.sticky_note_2_rounded
                                      : Icons.sticky_note_2_outlined,
                                  color: _videoMemoPanelOpen
                                      ? const Color(0xFFFFB347)
                                      : Colors.white,
                                  size: 22,
                                ),
                                onPressed: _toggleVideoMemoPanel,
                              ),
                              // ── ダウンロードボタン ──
                              // mp4 直リンクの時だけ表示。
                              // 端末のドキュメントフォルダ内 `Downloads/` に保存する。
                              // YouTube 本体の端末保存は著作権/規約リスクが高いため
                              // リリース版ではボタン自体を表示しない。
                              // ── ダウンロードボタン ──
                              // 表示条件:
                              //   HTTP/HTTPS で配信されている mp4 直リンク
                              if (_isMp4 &&
                                  (_currentUrl.startsWith('http://') ||
                                      _currentUrl.startsWith('https://')))
                                IconButton(
                                  tooltip: context
                                      .read<MindMapProvider>()
                                      .t('fsv.download'),
                                  padding: EdgeInsets.zero,
                                  constraints: const BoxConstraints(
                                      minWidth: 32, minHeight: 32),
                                  icon: const Icon(Icons.download_rounded,
                                      color: Color(0xFFFFB347), size: 22),
                                  onPressed: _downloadCurrentVideo,
                                ),
                              // プレイリストナビ (1段目右端)
                              if (_playlist.length > 1) ...[
                                IconButton(
                                  padding: EdgeInsets.zero,
                                  constraints: const BoxConstraints(
                                      minWidth: 32, minHeight: 32),
                                  icon: const Icon(Icons.skip_previous_rounded,
                                      color: Colors.white54, size: 20),
                                  onPressed: _playlistIndex > 0
                                      ? () {
                                          _playlistIndex--;
                                          _navigateTo(
                                              _playlist[_playlistIndex]);
                                        }
                                      : null,
                                ),
                                Text(
                                    '${_playlistIndex + 1}/${_playlist.length}',
                                    style: const TextStyle(
                                        color: Colors.white38, fontSize: 11)),
                                IconButton(
                                  padding: EdgeInsets.zero,
                                  constraints: const BoxConstraints(
                                      minWidth: 32, minHeight: 32),
                                  icon: const Icon(Icons.skip_next_rounded,
                                      color: Colors.white54, size: 20),
                                  onPressed:
                                      _playlistIndex < _playlist.length - 1
                                          ? () {
                                              _playlistIndex++;
                                              _navigateTo(
                                                  _playlist[_playlistIndex]);
                                            }
                                          : null,
                                ),
                              ],
                              // ── ヘッドレス再生 (紫のヘッドホン) ボタンは削除 ──
                              // ユーザー要望: 「モバイルの YouTube 動画上部の紫のヘッドホン
                              //   アイコンのボタンは意味を成していないので消して」。
                              //   ヘッドレス再生の仕組み自体 (startHeadlessYoutube /
                              //   フローティング停止ボタン) は残すが、 起動ボタンは出さない。
                            ]),
                            // 2段目 (動画ページかつ展開状態の時のみ表示)
                            // ── ブラウザ戻る/進むボタンは 1 段目 (= 上記の IconButton 群)
                            //    に同等のものがあるため、 重複削除。 ユーザー要望:
                            //    「Android版で YouTube を開いた時に戻る/進むボタンが 2 つ
                            //     あるから 1 つにして」。 旧実装は再生速度バーの左に
                            //    `_canGoBack` / `_canGoForward` 連動のボタンを 1 セット
                            //    重ねて出していた。 1 段目で十分のため撤去。
                            if (isVideo && _speedBarExpanded)
                              SingleChildScrollView(
                                scrollDirection: Axis.horizontal,
                                physics: const ClampingScrollPhysics(),
                                child: Row(children: [
                                  // ── IAW 版でも provider の videoMaxRate を反映 ──
                                  Builder(builder: (sctx) {
                                    final maxRate = context
                                        .watch<MindMapProvider>()
                                        .videoMaxRate;
                                    if (_playbackRate > maxRate) {
                                      WidgetsBinding.instance
                                          .addPostFrameCallback((_) {
                                        if (mounted) _changeRate(maxRate);
                                      });
                                    }
                                    final divs = ((maxRate - 1.0) * 4)
                                        .round()
                                        .clamp(4, 60);
                                    return Row(
                                        mainAxisSize: MainAxisSize.min,
                                        children: [
                                          Text(
                                              '${_playbackRate.toStringAsFixed(2)}x',
                                              style: const TextStyle(
                                                  color: Colors.white54,
                                                  fontSize: 11)),
                                          SizedBox(
                                            width: 110,
                                            child: SliderTheme(
                                              data: SliderThemeData(
                                                trackHeight: 2,
                                                thumbShape:
                                                    const RoundSliderThumbShape(
                                                        enabledThumbRadius: 5),
                                                activeTrackColor: Colors.white
                                                    .withValues(alpha: 0.5),
                                                inactiveTrackColor: Colors.white
                                                    .withValues(alpha: 0.15),
                                                thumbColor: Colors.white,
                                                overlayShape:
                                                    const RoundSliderOverlayShape(
                                                        overlayRadius: 10),
                                              ),
                                              child: Slider(
                                                value: _playbackRate.clamp(
                                                    1.0, maxRate),
                                                min: 1.0,
                                                max: maxRate,
                                                divisions: divs,
                                                onChanged: _changeRate,
                                              ),
                                            ),
                                          ),
                                          IconButton(
                                            tooltip: sctx
                                                .read<MindMapProvider>()
                                                .t('video.tip.maxRate'),
                                            padding: EdgeInsets.zero,
                                            constraints: const BoxConstraints(
                                                minWidth: 24, minHeight: 24),
                                            iconSize: 14,
                                            icon: const Icon(Icons.tune_rounded,
                                                color: Colors.white54),
                                            onPressed: () =>
                                                _showMaxRateDialog(sctx),
                                          ),
                                          // オフライン (mp4) 動画の左右キーのシーク秒数 (= ユーザー
                                          //   要望: 10秒既定 + 設定で変更可能に)。
                                          if (_isMp4)
                                            IconButton(
                                              tooltip: context
                                                  .read<MindMapProvider>()
                                                  .t('seek.title'),
                                              padding: EdgeInsets.zero,
                                              constraints: const BoxConstraints(
                                                  minWidth: 24, minHeight: 24),
                                              iconSize: 14,
                                              icon: const Icon(
                                                  Icons.fast_forward_rounded,
                                                  color: Colors.white54),
                                              onPressed: () =>
                                                  _showSeekStepDialog(sctx),
                                            ),
                                        ]);
                                  }),
                                  // 動画再読み込みボタン (広告対策)
                                  // 通常のリロードだと検索結果ページに戻されるが、 これは
                                  // 「直近視聴した動画」 にリロードするため、 広告で詰まっ
                                  // た時の脱出経路になる。
                                  IconButton(
                                    tooltip: context
                                        .read<MindMapProvider>()
                                        .t('fsv.reloadVideo'),
                                    padding: EdgeInsets.zero,
                                    constraints: const BoxConstraints(
                                        minWidth: 32, minHeight: 32),
                                    icon: const Icon(Icons.refresh_rounded,
                                        color: Colors.white70, size: 20),
                                    onPressed: _reloadCurrentVideo,
                                  ),
                                  if (_isYoutube ||
                                      _currentUrl.startsWith('http://') ||
                                      _currentUrl.startsWith('https://'))
                                    IconButton(
                                      tooltip: context
                                          .read<MindMapProvider>()
                                          .t('ctx.shareVideoUrl'),
                                      padding: EdgeInsets.zero,
                                      constraints: const BoxConstraints(
                                          minWidth: 32, minHeight: 32),
                                      icon: const Icon(Icons.share_rounded,
                                          color: Color(0xFF4FC3F7), size: 22),
                                      onPressed: () {
                                        final provider =
                                            context.read<MindMapProvider>();
                                        final shareUrl = _currentUrl
                                            .replaceFirst(
                                                'https://m.youtube.com/',
                                                'https://www.youtube.com/')
                                            .replaceFirst(
                                                'http://m.youtube.com/',
                                                'https://www.youtube.com/');
                                        Clipboard.setData(
                                            ClipboardData(text: shareUrl));
                                        _appSnack(
                                          context,
                                          SnackBar(
                                            content: Text(provider
                                                .t('ctx.videoUrlCopied')),
                                            duration:
                                                const Duration(seconds: 2),
                                            backgroundColor:
                                                const Color(0xFF2A2A3E),
                                          ),
                                        );
                                      },
                                    ),
                                ]),
                              ),
                            // ── 3 段目: YouTube 検索バー (常設、折りたたみ可能) ──
                            // YouTube モードの時だけ表示。 デフォルトは展開状態。
                            // 1 段目右端の検索アイコン (search_off) で折り畳める。
                            //
                            // 設置理由: YouTube が同じ動画の広告ステートを保持していて、
                            // 広告中に閉じる→開き直すと広告のまま動画にたどり着けない
                            // バグがある。 検索バーが常に見えていれば、 ここに別動画名を
                            // 入れて検索 → 別経路で開き直すという脱出手段が即取れる。
                            if (_ytSearchPanelOpen && _isYoutube && !_isMp4)
                              Padding(
                                padding: const EdgeInsets.fromLTRB(8, 0, 8, 6),
                                child: SizedBox(
                                  height: 32,
                                  child: TextField(
                                    controller: _ytSearchController,
                                    style: const TextStyle(
                                        color: Colors.white,
                                        fontSize: 13,
                                        fontWeight: FontWeight.w500,
                                        height: 1.1),
                                    textInputAction: TextInputAction.search,
                                    cursorColor: const Color(0xFF6C63FF),
                                    decoration: InputDecoration(
                                      hintText: context
                                          .read<MindMapProvider>()
                                          .t('fsv.ytSearch'),
                                      hintStyle: const TextStyle(
                                          color: Colors.white38, fontSize: 12),
                                      filled: true,
                                      fillColor:
                                          Colors.white.withValues(alpha: 0.12),
                                      isDense: true,
                                      contentPadding:
                                          const EdgeInsets.symmetric(
                                              horizontal: 4, vertical: 0),
                                      border: OutlineInputBorder(
                                        borderRadius: BorderRadius.circular(16),
                                        borderSide: BorderSide.none,
                                      ),
                                      focusedBorder: OutlineInputBorder(
                                        borderRadius: BorderRadius.circular(16),
                                        borderSide: const BorderSide(
                                            color: Color(0xFF6C63FF),
                                            width: 1.2),
                                      ),
                                      prefixIcon: const Icon(
                                          Icons.search_rounded,
                                          color: Color(0xFF6C63FF),
                                          size: 16),
                                      prefixIconConstraints:
                                          const BoxConstraints(
                                              minWidth: 28, minHeight: 28),
                                      suffixIcon: ValueListenableBuilder<
                                          TextEditingValue>(
                                        valueListenable: _ytSearchController,
                                        builder: (_, value, __) {
                                          if (value.text.isEmpty) {
                                            return const SizedBox.shrink();
                                          }
                                          return IconButton(
                                            padding: EdgeInsets.zero,
                                            constraints: const BoxConstraints(
                                                minWidth: 24, minHeight: 24),
                                            iconSize: 14,
                                            icon: const Icon(
                                                Icons.clear_rounded,
                                                color: Colors.white60),
                                            onPressed: () =>
                                                _ytSearchController.clear(),
                                          );
                                        },
                                      ),
                                      suffixIconConstraints:
                                          const BoxConstraints(
                                              minWidth: 28, minHeight: 28),
                                    ),
                                    onSubmitted: (q) {
                                      _runYoutubeSearch(q);
                                      // 連続検索可能なのでバーは閉じない、 フォーカスだけ外す
                                      FocusScope.of(context).unfocus();
                                    },
                                  ),
                                ),
                              ),
                          ]),
                        ),
                      // ── 動画プレイヤー本体 ──
                      // mp4 (= ローカル動画) は VideoPlayer (= ExoPlayer / AVPlayer)、
                      // YouTube / 一般 URL は InAppWebView を使う。
                      Expanded(
                        child: Stack(children: [
                          if (_isMp4 && !_useWebViewFallback)
                            _buildLocalVideoPlayer()
                          else
                            iaw.InAppWebView(
                              // 6.x API: WebUri を使う
                              initialUrlRequest: iaw.URLRequest(
                                url: iaw.WebUri((_isMp4 || _useWebViewFallback)
                                    ? 'about:blank'
                                    : _initialLoadTarget),
                              ),
                              // 6.x API: 統合された InAppWebViewSettings を使う
                              initialSettings: iaw.InAppWebViewSettings(
                                javaScriptEnabled: true,
                                domStorageEnabled: true,
                                useHybridComposition: true,
                                mediaPlaybackRequiresUserGesture: false,
                                allowsInlineMediaPlayback: true,
                                transparentBackground: false,
                                allowFileAccess: true,
                                mixedContentMode: iaw.MixedContentMode
                                    .MIXED_CONTENT_COMPATIBILITY_MODE,
                                // 縦ドラッグを親に渡さない (WebView 内で縦スクロール可能に)
                                useShouldOverrideUrlLoading: true,
                                // ── 新ウィンドウ / ポップアップを無効化 ──
                                // YouTube 動画再生中、広告のクリックなどで `target="_blank"`
                                // や `window.open(...)` 経由の新規ウィンドウが要求される
                                // ことがある。サポートしていないと WebView 内のリンクが
                                // 単純に「開かない」状態になり、ユーザーから見ると「タップ
                                // しても何も起きずに動画も止まったまま進行不能」 に見える。
                                // → supportMultipleWindows: false にすると新規ウィンドウ
                                //   要求が現在の WebView 内ナビゲーションにフォールバック
                                //   するので、shouldOverrideUrlLoading で URL を見て広告
                                //   ドメインなら CANCEL、通常リンクなら ALLOW、と一元的に
                                //   判定できるようになる。
                                supportMultipleWindows: false,
                                javaScriptCanOpenWindowsAutomatically: false,
                                // ── ユーザーエージェント上書き ──
                                // Android System WebView の既定 UA は最近のバージョンの
                                // YouTube に "未認証ブラウザ" と判定され、エラー 153
                                // ("動画プレーヤーの設定エラー" / "このビデオはここで再生
                                // できません") が出る動画が増えた。
                                // → Chrome モバイル相当の UA に偽装し、通常の m.youtube.com
                                //   と同じ扱いになるようにする。これで埋め込み制限が緩和されて
                                //   再生可能になるケースが多い。
                                userAgent:
                                    'Mozilla/5.0 (Linux; Android 14; Pixel 8) '
                                    'AppleWebKit/537.36 (KHTML, like Gecko) '
                                    'Chrome/126.0.0.0 Mobile Safari/537.36',
                                // ── サードパーティ Cookie を許可 ──
                                // YouTube は再生時にいくつかドメインをまたいで認証情報を
                                // やり取りする (accounts.google.com など)。Cookie が
                                // 許可されないと一部動画でエラー 153 になることがある。
                                thirdPartyCookiesEnabled: true,
                                // ハードウェアアクセラレーション (Android 9+ で動画再生
                                // 性能が向上する)
                                hardwareAcceleration: true,
                              ),
                              // ── バックグラウンド再生の安定化 (= ユーザー
                              //    要望: ON なのに再生される時とされない時が
                              //    ある) ──
                              // Page Visibility の偽装を「ページ読み込み前
                              // (document start)」 に入れる。 以前は背面に
                              // 回ってから注入していたため、 YouTube が先に
                              // visibilitychange リスナーを登録してしまい、
                              // 画面オフで pause される回とされない回が出て
                              // いた。 document start なら常に先回りできる。
                              initialUserScripts:
                                  UnmodifiableListView<iaw.UserScript>([
                                iaw.UserScript(
                                  source: _kBgPlaybackPatchJs,
                                  injectionTime: iaw
                                      .UserScriptInjectionTime.AT_DOCUMENT_START,
                                ),
                              ]),
                              onWebViewCreated: (controller) {
                                _c = controller;
                                controller.addJavaScriptHandler(
                                  handlerName: 'FlutterPosition',
                                  callback: (args) {
                                    if (args.isEmpty) return;
                                    final sec =
                                        double.tryParse(args[0].toString());
                                    if (sec != null &&
                                        _currentVideoId != null &&
                                        mounted) {
                                      context
                                          .read<MindMapProvider>()
                                          .saveVideoPosition(
                                              _currentVideoId!, sec);
                                    }
                                  },
                                );
                                controller.addJavaScriptHandler(
                                  handlerName: 'FlutterEnded',
                                  callback: (args) {
                                    if (_currentVideoId != null && mounted) {
                                      context
                                          .read<MindMapProvider>()
                                          .markVideoFullyWatched(
                                              _currentVideoId!);
                                    }
                                    if (_playlistIndex < _playlist.length - 1 &&
                                        mounted) {
                                      _playlistIndex++;
                                      _navigateTo(_playlist[_playlistIndex]);
                                    }
                                  },
                                );
                                controller.addJavaScriptHandler(
                                  handlerName: 'FlutterFallback',
                                  callback: (args) async {
                                    if (args.isEmpty) return;
                                    if (args[0].toString() == 'needBase64' &&
                                        _isMp4) {
                                      final currentUrl =
                                          _playlist[_playlistIndex];
                                      if (!currentUrl.startsWith('http') &&
                                          !currentUrl.startsWith('data:')) {
                                        try {
                                          final bytes = await File(currentUrl)
                                              .readAsBytes();
                                          final b64 = base64Encode(bytes);
                                          final src =
                                              'data:video/mp4;base64,$b64';
                                          _c?.evaluateJavascript(
                                              source:
                                                  'var v=document.getElementById("v");'
                                                  'if(v){v.src="$src";v.load();v.play();}');
                                        } catch (_) {}
                                      }
                                    }
                                  },
                                );
                                // mp4 の場合: initState で postFrameCallback に予約した
                                // _initialHtml がここで既に用意できているなら即ロード
                                if (_isMp4 && _initialHtml != null) {
                                  controller.loadData(
                                    data: _initialHtml!,
                                    mimeType: 'text/html',
                                    encoding: 'utf-8',
                                  );
                                }
                                // WebView フォールバックモード: VideoPlayer 初期化に失敗
                                // したケースで `_useWebViewFallback = true` & 再 build。
                                // この場合、mp4 用 HTML を即時生成して loadData する。
                                if (_useWebViewFallback &&
                                    _isMp4 &&
                                    !_fallbackHtmlLoaded) {
                                  _fallbackHtmlLoaded = true;
                                  () async {
                                    try {
                                      final html = await _buildMp4PlayerRaw(
                                          _playlist[_playlistIndex]);
                                      if (!mounted) return;
                                      await controller.loadData(
                                        data: html,
                                        mimeType: 'text/html',
                                        encoding: 'utf-8',
                                      );
                                    } catch (e) {
                                      debugPrint(
                                          'WebView fallback loadData failed: $e');
                                    }
                                  }();
                                }
                              },
                              onLoadStart: (controller, url) {
                                // ここでも URL を解析・更新する。
                                // チャンネルページなど onLoadStop が発火しない/遅いケースでも
                                // ナビゲーション開始時点で埋め込みボタンを出せるように。
                                final urlStr = url?.toString() ?? '';
                                if (mounted) {
                                  setState(() {
                                    _loading = true;
                                    if (urlStr.isNotEmpty)
                                      _analyzeUrlSync(urlStr);
                                    // ページ遷移したら以前のタイトルをクリアして再取得を促す
                                    _currentTitle = '';
                                  });
                                }
                                _updateNavState();
                                _persistBrowseUrl();
                              },
                              // YouTube のような SPA では画面遷移しても onLoadStop が
                              // 発火しない/遅れることがある。履歴の追加を検知して URL を
                              // 追従し、埋め込みボタンの表示を更新する。
                              onUpdateVisitedHistory:
                                  (controller, url, androidIsReload) {
                                final urlStr = url?.toString() ?? '';
                                if (mounted &&
                                    urlStr.isNotEmpty &&
                                    urlStr != _currentUrl) {
                                  setState(() {
                                    _analyzeUrlSync(urlStr);
                                    // SPA 遷移時もタイトルをクリアして再取得 (動画→動画 等)
                                    _currentTitle = '';
                                  });
                                  // 動画ページなら新タイトルを polling
                                  _pollVideoTitle();
                                  // ── SPA 遷移時のフォーカス CSS 切り替え ──
                                  // YouTube は m.youtube.com 内を SPA で動くため、
                                  // watch → 検索 や watch → ホーム の遷移で onLoadStop が
                                  // 発火しないことが多い。`__MM_FS_STYLE__` が watch ページ
                                  // で貼られたまま残ると、検索結果ページで #mobile-topbar
                                  // (= 検索ボックスを含むトップバー) が display:none のまま
                                  // になり、ユーザーが検索ボックスに触れても何もできない、
                                  // という現象が起こる。
                                  // → 履歴更新時に URL を判定して、watch 以外なら CSS を
                                  //    撤去、watch ならポストポンドで _injectStyle() を呼ぶ。
                                  final isWatch = urlStr.contains('/watch') ||
                                      urlStr.contains('/shorts/') ||
                                      urlStr.contains('/embed/') ||
                                      urlStr.contains('youtu.be/');
                                  if (_isYoutube && isWatch) {
                                    // ── 再生速度はフォーカスモードに関わらず維持する ──
                                    //   (= ユーザー報告: モバイルで別の動画へ移動すると
                                    //   4倍に設定したのに 1倍へ戻る)。 YouTube の SPA 遷移
                                    //   (動画→動画) では onLoadStop が発火せず、 JS 実行
                                    //   コンテキストが作り直されて __MM_RATE__ が失われる
                                    //   ことがあるため、 watch へ遷移する度に必ず再注入する。
                                    _injectPlaybackRate();
                                    // 動画埋め込み再生 (focusMode:true) の時だけ、 周辺 UI
                                    //   (関連動画/コメント/ヘッダー等) を隠す CSS + 位置復元
                                    //   を行う。 ブラウズ (focusMode:false) では素の YouTube
                                    //   UI と自由な遷移を保つ。
                                    if (widget.focusMode) {
                                      _injectStyle();
                                      _restorePosition();
                                    }
                                  } else {
                                    // ── watch 以外 (検索/ホーム/チャンネル/別サイト) では、
                                    //    過去に貼った フォーカス CSS を **focusMode に依らず必ず**
                                    //    撤去する。 = ユーザー報告「YouTube 動画を埋め込んで
                                    //    いないのに周りの CSS が非表示になる」 の対策。 CSS は
                                    //    header/footer/body 等の汎用セレクタを display:none に
                                    //    するため、 残ると遷移先のページが壊れる。 _removeStyle
                                    //    は未注入なら no-op (副作用なし) なので常に呼んで安全。──
                                    _removeStyle();
                                  }
                                }
                                _updateNavState();
                                _persistBrowseUrl();
                              },
                              onLoadStop: (controller, url) async {
                                // ── YouTube バックグラウンド再生対策 ──
                                // ページロード完了直後に Page Visibility API を偽装。
                                // YouTube の player は document.hidden を見て自動 pause
                                // するので、ここで早期に偽装することで「画面オフ → 自動
                                // pause」を阻止する。
                                // (force play timer でも 200ms ごとに再注入されるが、
                                //  YouTube が自身のリスナーを登録する前に仕込みたいので
                                //  ロード完了の最も早いタイミングで実行)
                                controller.evaluateJavascript(source: r'''
                    (function() {
                      if (window.__MM_VISIBILITY_PATCHED__) return;
                      try {
                        Object.defineProperty(document, 'hidden', {
                          configurable: true, get: function() { return false; }
                        });
                        Object.defineProperty(document, 'visibilityState', {
                          configurable: true, get: function() { return 'visible'; }
                        });
                        Object.defineProperty(document, 'webkitHidden', {
                          configurable: true, get: function() { return false; }
                        });
                        Object.defineProperty(document, 'webkitVisibilityState', {
                          configurable: true, get: function() { return 'visible'; }
                        });
                        var origAdd = EventTarget.prototype.addEventListener;
                        EventTarget.prototype.addEventListener = function(type, listener, opts) {
                          if (type === 'visibilitychange' || type === 'webkitvisibilitychange') return;
                          return origAdd.call(this, type, listener, opts);
                        };
                        window.__MM_VISIBILITY_PATCHED__ = true;
                      } catch(e) {}
                    })();
                  ''').catchError((_) {});
                                final urlStr = url?.toString() ?? _currentUrl;
                                if (mounted) {
                                  // ページ遷移ごとに URL を再解析する (検索→動画タップ→
                                  // 他動画へ、などで _isYoutube / _currentVideoId 等を追従)
                                  setState(() {
                                    _loading = false;
                                    _analyzeUrlSync(urlStr);
                                  });
                                }
                                _updateNavState();
                                _persistBrowseUrl();
                                // タイトル取得
                                try {
                                  final title = await controller.getTitle();
                                  if (mounted &&
                                      title != null &&
                                      title.isNotEmpty) {
                                    setState(() =>
                                        _currentTitle = _cleanTitle(title));
                                  }
                                } catch (_) {}
                                // 動画ページなら、SPA で遅れて反映されるタイトルを polling で取得
                                _pollVideoTitle();
                                // ── 動画固有の演出 (フォーカスモード CSS / 再生速度 /
                                //    位置保存 / 位置復元) は、実際に動画を再生している
                                //    ページに限って適用する。
                                // 検索結果 / チャンネル / 一般ブラウズページでは、
                                // ヘッダーや検索ボックスを隠してしまうと使い物にならないため、
                                // YouTube 本来の UI をそのまま残す。
                                final isVideoWatchPage =
                                    urlStr.contains('/watch') ||
                                        urlStr.contains('/shorts/') ||
                                        urlStr.contains('/embed/') ||
                                        urlStr.contains('youtu.be/');
                                if (_isYoutube && isVideoWatchPage) {
                                  // ── focusMode が true (= ノード動画埋め込み再生) の時だけ
                                  //    CSS を注入して関連動画 / コメント / ヘッダー / 検索
                                  //    ボックス を隠す。
                                  //    focusMode が false (= 「YouTubeを開く」ボタンから起動
                                  //    したブラウズモード) では、検索や別動画への遷移が必要
                                  //    なので素の YouTube UI を保つ。
                                  // ハイパーリンクからのジャンプは最優先で適用したい
                                  // (autoplay で 0 秒に戻される前に loadedmetadata 等の
                                  //  リスナーを仕掛けるため、 他の injection より先に呼ぶ)。
                                  await _restorePosition();
                                  if (widget.focusMode) {
                                    await _injectStyle();
                                  }
                                  await _injectPlaybackRate();
                                  await _injectPositionTracker();
                                } else if (_isMp4) {
                                  await _injectPlaybackRate();
                                } else {
                                  // ── watch / shorts / embed 以外 (検索結果・ホーム・
                                  //    チャンネル・一般 URL) では、以前 watch ページで貼った
                                  //    フォーカス CSS を撤去する。
                                  // 残したままだと #mobile-topbar / header / 検索ボックス
                                  //    が display:none のままになり、検索を含むトップバーが
                                  //    操作不能になる (ユーザー報告のバグ)。
                                  // ★ _isYoutube 依存を外す: YouTube watch → 非 YouTube
                                  //   サイト (Wikipedia 等) への遷移時に _isYoutube が
                                  //   false になって CSS が残り、新サイトの <header> /
                                  //   <footer> が display:none、 body 背景が黒に固定されて
                                  //   「YouTube動画を埋め込んでないのに CSS が消える」
                                  //   現象が起きていた (= ユーザー要望)。
                                  // ★ focusMode に依らず **必ず** 撤去する (残留防止)。
                                  //   focusMode:false で起動した場合は未注入なので no-op。
                                  await _removeStyle();
                                }
                                // それ以外 (YouTube 検索/チャンネル/一般ページ) は何も注入しない
                              },
                              onProgressChanged: (controller, p) {
                                // SPA サイト (YouTube) では onLoadStop が発火しない事が
                                // 多いので、進捗が 70% を超えたらローディングを外す。
                                // また 100% で常に解除。
                                if (mounted) {
                                  if (p >= 100 && _loading) {
                                    setState(() => _loading = false);
                                  } else if (p >= 70 && _loading) {
                                    setState(() => _loading = false);
                                  }
                                }
                              },
                              // 6.x API: onReceivedError(controller, request, error)
                              onReceivedError: (controller, request, error) {
                                debugPrint('InAppWebView error: '
                                    'type=${error.type} desc=${error.description} '
                                    'url=${request.url}');
                                if (mounted && _loading) {
                                  Future.delayed(const Duration(seconds: 3),
                                      () {
                                    if (mounted && _loading) {
                                      setState(() => _loading = false);
                                    }
                                  });
                                }
                              },
                              // 6.x API: onReceivedHttpError(controller, request, response)
                              onReceivedHttpError:
                                  (controller, request, response) {
                                debugPrint('InAppWebView HTTP error: '
                                    '${response.statusCode} url=${request.url}');
                              },
                              // intent:// 等のスキームを遮断し、http/https/data/about/blob のみ許可
                              shouldOverrideUrlLoading:
                                  (controller, navAction) async {
                                final u = navAction.request.url
                                        ?.toString()
                                        .toLowerCase() ??
                                    '';
                                // ── 非 http スキームの遮断 (intent://, market://, mailto: 等) ──
                                if (u.isEmpty)
                                  return iaw.NavigationActionPolicy.ALLOW;
                                final isHttpish = u.startsWith('http://') ||
                                    u.startsWith('https://') ||
                                    u.startsWith('data:') ||
                                    u.startsWith('about:') ||
                                    u.startsWith('blob:') ||
                                    u.startsWith('file://');
                                if (!isHttpish) {
                                  debugPrint(
                                      'InAppWebView blocked non-http scheme: $u');
                                  return iaw.NavigationActionPolicy.CANCEL;
                                }
                                // ── YouTube 動画視聴中の広告クリックで進行不能になるバグ対策 ──
                                // YouTube 動画再生中、広告のクリックスルーで以下の中継ドメインに
                                // フレームをまたいで遷移する → 戻れずに進行不能になる現象が起きる。
                                //   - googleadservices.com
                                //   - doubleclick.net  (g.doubleclick.net 含む)
                                //   - googlesyndication.com (pagead2.googlesyndication.com 等)
                                //   - googletagservices.com / googletagmanager.com
                                //   - adservice.google.* (国別ドメイン含む)
                                //   - syndication.google.com / pagead*.googleadservices.com
                                // これらは YouTube 内の動画再生では裏で動的に読み込まれる中間
                                // リソースなので、 `shouldOverrideUrlLoading` (= top-level
                                // フレームのナビゲーションのみ発火) で出てくる時はほぼ確実に
                                // 「広告クリックで遷移しようとした」 状況。 ここで CANCEL すれば、
                                // ユーザーは動画ページに留まったまま (= 広告クリックを単に
                                // 無視) になる。
                                // ノード動画再生 (focusMode = true) の時だけ有効化して、
                                // 「YouTubeを開く」 ブラウズモード (focusMode = false) では
                                // 広告ページも開けるようにしておく (ブラウザ的に使う想定)。
                                bool isAdNavigation(String url) {
                                  return url.contains('googleadservices.com') ||
                                      url.contains('doubleclick.net') ||
                                      url.contains('googlesyndication.com') ||
                                      url.contains('googletagservices.com') ||
                                      url.contains('googletagmanager.com') ||
                                      url.contains('google-analytics.com') ||
                                      // adservice.google.com / .co.jp / .de など国別ドメイン
                                      RegExp(r'adservice\.google\.[a-z.]+')
                                          .hasMatch(url) ||
                                      // pagead/aclk?* (Google AdSense クリック中継)
                                      url.contains('/pagead/aclk') ||
                                      url.contains('/pagead/adview') ||
                                      url.contains('/pagead/conversion');
                                }

                                if (widget.focusMode && isAdNavigation(u)) {
                                  debugPrint(
                                      'InAppWebView blocked YouTube ad navigation: $u');
                                  return iaw.NavigationActionPolicy.CANCEL;
                                }
                                // ── 動画ページから外部ドメインへの遷移を抑止 (focusMode のみ) ──
                                // 広告中継ドメインを抜けた後でも、最終的に広告主の URL に
                                // 飛ばされた瞬間 (= youtube.com 配下を抜けた直後の遷移) を
                                // 検知して CANCEL する。 これでクリック中継が新しい URL
                                // パターンに変わっても 1 段階の保険として動く。
                                // ただし焦点モード (= ノード再生) かつ「動画 watch ページから
                                // 別ドメインへ」 の時に限定。 検索結果やブラウズでは普通に
                                // 外部リンクを踏みたいケースもあるので影響しないようにする。
                                if (widget.focusMode &&
                                    _isYoutube &&
                                    _currentVideoId != null) {
                                  final isExternal = !u
                                          .contains('youtube.com') &&
                                      !u.contains('youtu.be') &&
                                      !u.contains('googlevideo.com') &&
                                      !u.contains('ytimg.com') &&
                                      !u.contains('googleusercontent.com') &&
                                      !u.contains('gstatic.com') &&
                                      !u.contains('google.com/recaptcha') &&
                                      !u.contains('accounts.google.com');
                                  // top-level (= main frame) のみブロック対象。
                                  // navAction.isForMainFrame が利用できれば使う。
                                  final bool isMainFrame =
                                      navAction.isForMainFrame ?? true;
                                  if (isExternal && isMainFrame) {
                                    debugPrint(
                                        'InAppWebView blocked external nav from video: $u');
                                    return iaw.NavigationActionPolicy.CANCEL;
                                  }
                                }
                                return iaw.NavigationActionPolicy.ALLOW;
                              },
                              // ── 新規ウィンドウ要求の遮断 ──
                              // supportMultipleWindows: false により基本的に新規ウィンドウは
                              // 現在の WebView 内ナビゲーションへフォールバックするが、
                              // 念のため onCreateWindow も cancel (= return false) にして
                              // 二重に防御する。 これで「広告タップ → 真っ白な新規タブが
                              // 裏で開かれて WebView がフリーズしたように見える」 現象を
                              // 完全に塞ぐ。
                              onCreateWindow:
                                  (controller, createWindowAction) async {
                                // ── 広告等のポップアップ (window.open) は OS ブラウザの別タブで
                                //    開く (= ユーザー要望: 広告が立ち上がる時は別タブで開く)。
                                //    動画はアプリ内でそのまま再生継続。 URL が取れない空ポップ
                                //    アップは従来通りブロック (白紙タブのフリーズ防止)。
                                final us = createWindowAction.request.url
                                        ?.toString() ??
                                    '';
                                if (us.startsWith('http://') ||
                                    us.startsWith('https://')) {
                                  final uri = Uri.tryParse(us);
                                  if (uri != null) {
                                    try {
                                      await launchUrl(uri,
                                          mode: LaunchMode.externalApplication);
                                    } catch (_) {}
                                  }
                                }
                                return false; // WebView 内には新規ウィンドウを作らない
                              },
                            ),
                          if (_loading)
                            const Center(
                              child: CircularProgressIndicator(
                                valueColor: AlwaysStoppedAnimation<Color>(
                                    Color(0xFFE53935)),
                              ),
                            ),
                          // ── YouTube 検索パネル (旧: オーバーレイ実装) ──
                          // 動画上にオーバーレイで降りてくる旧設計は削除。
                          // 検索バーはトップバーの 3 段目に常設に変更 (折りたたみ可能)。
                          // 詳細は `_ytSearchPanelOpen` の State 宣言コメント参照。
                          // ── 動画視聴中メモパネル ──
                          // [_videoMemoPanelOpen] = true の時だけ動画 / loading
                          // インジケータの上にオーバーレイ。 Stack の最後の子なので
                          // 自然に最前面に来る。 ヘッダーバーは別 Column 兄弟なので
                          // 隠れない (= ヘッダーのメモボタンでいつでもトグルできる)。
                          // 内部で Positioned.fill + Align(bottomCenter) のシート
                          // 構造を取るため、 Stack の領域全体をキャプチャしつつ、
                          // 表示は下半分のシートのみ。 残った上半分は dim フィルター
                          // 越しに動画が透けて見える。 シート外タップで閉じる UX。
                          if (_videoMemoPanelOpen)
                            _buildVideoMemoPanel(context),
                        ]),
                      ),
                      // ── 下部配置 (= ユーザー要望): ヘッダー操作列を WebView の
                      //    下に描画する。 上部 / サイドと同じ
                      //    _buildMobileYoutubeHeader をそのまま流用する。 ──
                      if (!_hideAllControls && useYoutubeBottomBar)
                        _buildMobileYoutubeHeader(isVideo),
                    ]),
                  ),
                  if (!_hideAllControls &&
                      useYoutubeSideMenu &&
                      !_youtubeSideMenuOnLeft)
                    _buildMobileYoutubeSideMenu(),
                ],
              ),
              if (_hideAllControls) _buildHiddenYoutubeControlsRestoreTarget(),
            ],
          ),
        ),
      ),
    );
  }
}

// (_WebViewSheet / _MobileWebViewSheet — 旧 webview_flutter ベースの
//  未使用実装を削除。flutter_inappwebview 版 _FullscreenVideoPage に統一済み)

// ─── YouTube検索結果シート ────────────────────────────────────────────────────

class _YoutubeSearchSheet extends StatefulWidget {
  final String keyword;
  final int count;
  final int minMinutes;
  final int maxMinutes;
  final String searchUrl;
  final void Function(List<String> videoIds, List<String> titles) onResults;
  const _YoutubeSearchSheet({
    required this.keyword,
    required this.count,
    this.minMinutes = 0,
    this.maxMinutes = 0,
    required this.searchUrl,
    required this.onResults,
  });
  @override
  State<_YoutubeSearchSheet> createState() => _YoutubeSearchSheetState();
}

class _YoutubeSearchSheetState extends State<_YoutubeSearchSheet> {
  // flutter_inappwebview ベースに移行。
  // _PlaylistExtractSheet と同じ理由で、webview_flutter では
  // MIUI/HyperOS 上で loadRequest が失敗するため iaw. を使う。
  iaw.InAppWebViewController? _c;
  bool _loading = true;
  bool _extracted = false;
  int _retryCount = 0;
  final List<String> _foundIds = [];
  final List<String> _foundTitles = [];
  final Set<String> _seenIds = {};
  // ── 同意 Cookie を仕込んでから WebView をロードする (= ユーザー報告: Android で
  //   YouTube 検索が結果を返さない)。 原因は m.youtube.com が同意
  //   インタースティシャル (consent.youtube.com) を返し、 動画カードの DOM が
  //   出ず 0 件スクレイプになること。 ログアウト (deleteAllCookies) 後も再発する。
  //   CONSENT/SOCS Cookie を先に書いておけば同意ウォールを回避できる。
  bool _cookiesReady = false;

  @override
  void initState() {
    super.initState();
    if (!kIsWeb && Platform.isAndroid) {
      // ★ タイムアウト保険: Cookie 書き込みが万一ハングしても、 1.5 秒で
      //   WebView を作る (= 永久スピナーにしない)。
      _seedConsentCookies()
          .timeout(const Duration(milliseconds: 1500), onTimeout: () {})
          .whenComplete(() {
        if (mounted) setState(() => _cookiesReady = true);
      });
    } else {
      _cookiesReady = true;
    }
  }

  Future<void> _seedConsentCookies() async {
    try {
      final cm = iaw.CookieManager.instance();
      Future<void> set(String url, String domain) async {
        final u = iaw.WebUri(url);
        await cm.setCookie(url: u, name: 'SOCS', value: 'CAI', domain: domain);
        await cm.setCookie(
            url: u,
            name: 'CONSENT',
            value: 'YES+cb.20210328-17-p0.en+FX+999',
            domain: domain);
      }

      await set('https://m.youtube.com', '.youtube.com');
      await set('https://www.youtube.com', '.youtube.com');
      await set('https://www.google.com', '.google.com');
    } catch (_) {}
  }

  void _onResults(List<dynamic> args) {
    if (_extracted) return;
    if (args.isEmpty) return;
    try {
      final msg = args[0]?.toString() ?? '';
      final parts = msg.split('|||');
      for (final p in parts) {
        final kv = p.split(':::');
        if (kv.length == 2 && kv[0].isNotEmpty && !_seenIds.contains(kv[0])) {
          _seenIds.add(kv[0]);
          _foundIds.add(kv[0]);
          _foundTitles.add(kv[1].isEmpty ? widget.keyword : kv[1]);
        }
      }
      // 指定件数に達したら即送信
      if (_foundIds.length >= widget.count) {
        _finalize();
      }
    } catch (_) {}
  }

  void _finalize() {
    if (_extracted) return;
    _extracted = true;
    if (_foundIds.isNotEmpty) {
      widget.onResults(
        _foundIds.take(widget.count).toList(),
        _foundTitles.take(widget.count).toList(),
      );
      if (mounted) Navigator.pop(context);
    }
  }

  void _tryExtract() {
    if (_extracted) return;
    _retryCount++;
    final max = widget.count;
    final minSec = widget.minMinutes * 60;
    final maxSec = widget.maxMinutes > 0 ? widget.maxMinutes * 60 : 999999;
    final alreadySeen = _seenIds.map((id) => '"$id"').join(',');
    _c?.evaluateJavascript(source: '''
      (function() {
        try {
          var minSec = $minSec;
          var maxSec = $maxSec;
          var already = new Set([$alreadySeen]);
          var need = $max - already.size;
          if (need <= 0) return;

          function parseDuration(text) {
            if (!text) return 0;
            text = text.trim();
            var parts = text.split(':').map(function(x){ return parseInt(x,10)||0; });
            if (parts.length === 3) return parts[0]*3600 + parts[1]*60 + parts[2];
            if (parts.length === 2) return parts[0]*60 + parts[1];
            return 0;
          }

          function getDuration(card) {
            if (!card) return 0;
            var selectors = [
              'ytm-thumbnail-overlay-time-status-renderer',
              'ytm-thumbnail-overlay-time-status-renderer span',
              '.badge-shape-wiz__text',
              'ytd-thumbnail-overlay-time-status-renderer span',
            ];
            for (var s = 0; s < selectors.length; s++) {
              try {
                var els = card.querySelectorAll(selectors[s]);
                for (var e = 0; e < els.length; e++) {
                  var t = (els[e].textContent || '').trim();
                  if (/^\\d+:\\d+/.test(t)) return parseDuration(t);
                }
              } catch(ex) {}
            }
            try {
              var al = card.querySelector('[aria-label*="minut"], [aria-label*="秒"], [aria-label*="分"]');
              if (al) {
                var label = al.getAttribute('aria-label') || '';
                var hm = label.match(/(\\d+)\\s*(?:hour|時間)/i);
                var mm = label.match(/(\\d+)\\s*(?:minut|分)/i);
                var sm = label.match(/(\\d+)\\s*(?:second|秒)/i);
                var sec = (hm ? parseInt(hm[1])*3600 : 0) + (mm ? parseInt(mm[1])*60 : 0) + (sm ? parseInt(sm[1]) : 0);
                if (sec > 0) return sec;
              }
            } catch(ex) {}
            return 0;
          }

          var cards = document.querySelectorAll(
            'ytm-video-with-context-renderer, ytm-compact-video-renderer, ytd-video-renderer, ytd-rich-item-renderer'
          );
          var results = [];
          for (var i = 0; i < cards.length && results.length < need; i++) {
            var card = cards[i];
            var link = card.querySelector('a[href*="/watch?v="]');
            if (!link) continue;
            var href = link.getAttribute('href') || '';
            var m = href.match(/[?&]v=([a-zA-Z0-9_-]{11})/);
            if (!m || already.has(m[1])) continue;

            var dur = getDuration(card);
            if (dur > 0 && (dur < minSec || dur > maxSec)) continue;

            already.add(m[1]);
            var title = '';
            try {
              var h3 = card.querySelector('h3, .title, [aria-label]');
              if (h3) title = (h3.textContent || h3.getAttribute('aria-label') || '').trim();
              if (!title) title = (link.getAttribute('aria-label') || link.textContent || '').trim();
            } catch(e) {}
            var durMin = dur > 0 ? Math.floor(dur/60) + ':' + ('0'+dur%60).slice(-2) : '';
            results.push(m[1] + ':::' + title.substring(0, 55) + (durMin ? ' ['+durMin+']' : ''));
          }
          if (results.length > 0 && window.flutter_inappwebview) {
            window.flutter_inappwebview.callHandler('FlutterResults', results.join('|||'));
          }
        } catch(e) {}
      })();
    ''');
    // まだ足りなければ2秒後にリトライ（最大3回）
    if (_retryCount < 3) {
      Future.delayed(const Duration(seconds: 2), () {
        if (!_extracted && _foundIds.length < widget.count && mounted) {
          // ページを少しスクロールしてもっとカードを読み込ませる
          _c?.evaluateJavascript(source: 'window.scrollBy(0, 800);');
          Future.delayed(const Duration(milliseconds: 800), _tryExtract);
        }
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final screenH = MediaQuery.of(context).size.height;
    return SizedBox(
      height: screenH * 0.7,
      child: Column(children: [
        Container(
          margin: const EdgeInsets.symmetric(vertical: 8),
          width: 40,
          height: 4,
          decoration: BoxDecoration(
              color: Colors.white24, borderRadius: BorderRadius.circular(2)),
        ),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
          child: Row(children: [
            Container(
              width: 24,
              height: 24,
              decoration: const BoxDecoration(
                  color: Color(0xFFE53935), shape: BoxShape.circle),
              child: const Icon(Icons.search, color: Colors.white, size: 14),
            ),
            const SizedBox(width: 8),
            Expanded(
                child: Text(
                    context
                        .read<MindMapProvider>()
                        .t('search.searching')
                        .replaceFirst('{kw}', widget.keyword)
                        .replaceFirst('{n}', '${widget.count}'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 13,
                        fontWeight: FontWeight.bold),
                    overflow: TextOverflow.ellipsis)),
            if (_loading)
              const SizedBox(
                  width: 16,
                  height: 16,
                  child: CircularProgressIndicator(
                      strokeWidth: 2,
                      valueColor:
                          AlwaysStoppedAnimation<Color>(Color(0xFFE53935)))),
            IconButton(
              icon: const Icon(Icons.close, color: Colors.white54, size: 20),
              onPressed: () => Navigator.pop(context),
            ),
          ]),
        ),
        Expanded(
          child: ClipRRect(
            borderRadius:
                const BorderRadius.vertical(bottom: Radius.circular(20)),
            // 同意 Cookie の準備が終わるまで WebView を作らない (= 初回ロードで
            //   Cookie が間に合わず同意ページに飛ぶのを防ぐ)。
            child: !_cookiesReady
                ? const Center(
                    child: CircularProgressIndicator(color: Color(0xFFE53935)))
                : iaw.InAppWebView(
                    initialUrlRequest: iaw.URLRequest(
                      url: iaw.WebUri(widget.searchUrl),
                    ),
                    initialSettings: iaw.InAppWebViewSettings(
                      javaScriptEnabled: true,
                      domStorageEnabled: true,
                      useHybridComposition: true,
                      mediaPlaybackRequiresUserGesture: false,
                      transparentBackground: false,
                      userAgent:
                          'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36',
                    ),
                    onWebViewCreated: (controller) {
                      _c = controller;
                      controller.addJavaScriptHandler(
                        handlerName: 'FlutterResults',
                        callback: _onResults,
                      );
                    },
                    onLoadStop: (controller, url) {
                      if (mounted) setState(() => _loading = false);
                      Future.delayed(const Duration(seconds: 2), _tryExtract);
                      // 7秒後に見つかった分だけで打ち切り
                      Future.delayed(const Duration(seconds: 7), () {
                        if (!_extracted && _foundIds.isNotEmpty && mounted) {
                          _finalize();
                        }
                      });
                    },
                    onProgressChanged: (controller, p) {
                      if (mounted && p >= 100 && _loading) {
                        setState(() => _loading = false);
                      }
                    },
                    onReceivedError: (controller, request, error) {
                      debugPrint('YoutubeSearch error: '
                          '${error.description} url=${request.url}');
                      if (mounted && _loading) {
                        setState(() => _loading = false);
                      }
                      // エラーでも抽出を試みる
                      Future.delayed(const Duration(seconds: 3), _tryExtract);
                    },
                  ),
          ),
        ),
      ]),
    );
  }
}

// ─── YouTubeプレイリスト展開シート ────────────────────────────────────────────

class _PlaylistExtractSheet extends StatefulWidget {
  final List<String> urls;
  final String playlistId;
  final bool extractPageTitle;
  final void Function(List<String> videoIds, List<String> titles,
      String? pageTitle, List<int> viewCounts) onResults;
  const _PlaylistExtractSheet({
    required this.urls,
    required this.playlistId,
    required this.extractPageTitle,
    required this.onResults,
  });
  @override
  State<_PlaylistExtractSheet> createState() => _PlaylistExtractSheetState();
}

class _PlaylistExtractSheetState extends State<_PlaylistExtractSheet> {
  // flutter_inappwebview ベースに移行。
  // webview_flutter は MIUI/HyperOS で Pigeon channel-error を起こして
  // loadRequest が失敗するため、_FullscreenVideoPage と同じ iaw. を使う。
  iaw.InAppWebViewController? _c;
  bool _loading = true;
  bool _finished = false;
  int _urlIndex = 0;
  // 全URLからの累積結果（順序保持・重複排除）
  final List<String> _allIds = [];
  final List<String> _allTitles = [];
  final List<int> _allViewCounts = [];
  final Set<String> _seenIds = {};
  String? _pageTitle;

  @override
  void initState() {
    super.initState();
  }

  void _onExtracted(List<dynamic> args) {
    if (_finished) return;
    if (args.isEmpty) {
      _advanceOrFinish();
      return;
    }
    try {
      final msg = args[0]?.toString() ?? '';
      final parts = msg.split('|||');
      for (final p in parts) {
        final kv = p.split(':::');
        if (kv.length >= 2 && kv[0].isNotEmpty) {
          if (_seenIds.add(kv[0])) {
            _allIds.add(kv[0]);
            _allTitles.add(kv[1].isEmpty ? 'Video' : kv[1]);
            _allViewCounts
                .add(kv.length >= 3 ? (int.tryParse(kv[2]) ?? -1) : -1);
          }
        }
      }
    } catch (_) {}
    _advanceOrFinish();
  }

  void _advanceOrFinish() {
    if (_finished) return;
    // 次のURLがあればロード、無ければ終了
    if (_urlIndex + 1 < widget.urls.length) {
      _urlIndex++;
      if (mounted) setState(() => _loading = true);
      _c?.loadUrl(
        urlRequest: iaw.URLRequest(url: iaw.WebUri(widget.urls[_urlIndex])),
      );
    } else {
      _finished = true;
      if (_allIds.isNotEmpty || _pageTitle != null) {
        widget.onResults(_allIds, _allTitles, _pageTitle, _allViewCounts);
      }
      if (mounted) Navigator.pop(context);
    }
  }

  void _extractAll() {
    if (_finished) return;
    _c?.evaluateJavascript(source: r'''
      (function() {
        if (window.__MM_EXTRACT_RUNNING__) return;
        window.__MM_EXTRACT_RUNNING__ = true;

        function countVideos() {
          var links = document.querySelectorAll('a[href*="/watch?v="], a[href*="/shorts/"]');
          var seen = {};
          var count = 0;
          for (var i = 0; i < links.length; i++) {
            var href = links[i].getAttribute('href') || '';
            if (href.indexOf('list=') !== -1 && href.indexOf('index=') === -1) continue;
            var vid = '';
            var m = href.match(/[?&]v=([a-zA-Z0-9_-]{11})/);
            if (m) vid = m[1];
            else {
              var ms = href.match(/\/shorts\/([a-zA-Z0-9_-]{11})/);
              if (ms) vid = ms[1];
            }
            if (!vid || seen[vid]) continue;
            seen[vid] = true;
            count++;
          }
          return count;
        }

        function scrollAll(cb) {
          var lastCount = 0;
          var stable = 0;
          var attempts = 0;
          var maxAttempts = 80;

          function step() {
            attempts++;
            // ページ最下部までスクロール
            try {
              var sh = Math.max(
                document.body.scrollHeight,
                document.documentElement.scrollHeight
              );
              window.scrollTo(0, sh);
              window.scrollBy(0, 3000);
            } catch(e) {}

            setTimeout(function() {
              var c = countVideos();
              if (c > lastCount) {
                lastCount = c;
                stable = 0;
              } else {
                stable++;
              }
              // 動画が増えなくなって5サイクル経過、または80回試行で終了
              if (stable >= 5 || attempts >= maxAttempts) {
                cb();
                return;
              }
              step();
            }, 700);
          }
          step();
        }

        function extractAll() {
          try {
            var links = document.querySelectorAll('a[href*="/watch?v="], a[href*="/shorts/"]');
            var seen = {};
            var results = [];
            for (var i = 0; i < links.length; i++) {
              var href = links[i].getAttribute('href') || '';
              if (href.indexOf('list=') !== -1 && href.indexOf('index=') === -1) continue;
              var vid = '';
              var m = href.match(/[?&]v=([a-zA-Z0-9_-]{11})/);
              if (m) vid = m[1];
              else {
                var ms = href.match(/\/shorts\/([a-zA-Z0-9_-]{11})/);
                if (ms) vid = ms[1];
              }
              if (!vid || seen[vid]) continue;
              seen[vid] = true;
              var title = '';
              var views = '-1';
              try {
                var p = links[i].closest('ytm-playlist-video-renderer, ytm-compact-video-renderer, ytm-video-with-context-renderer, ytm-rich-item-renderer, ytm-grid-video-renderer, ytm-reel-item-renderer, ytm-shorts-lockup-view-model, ytd-playlist-video-renderer');
                if (p) {
                  var h3 = p.querySelector('h3, .title, [aria-label], .video-title, .compact-media-item-headline');
                  if (h3) title = (h3.textContent || h3.getAttribute('aria-label') || '').trim();
                  // 再生数を抽出
                  var metaEls = p.querySelectorAll('.subtitle, .metadata, span, .ytm-badge-and-byline-renderer, .compact-media-item-metadata-content');
                  for (var j = 0; j < metaEls.length; j++) {
                    var txt = (metaEls[j].textContent || '').trim();
                    var vm = txt.match(/([\d,.]+)\s*(万|億|K|M|B)?\s*(回|views|view)/i);
                    if (vm) {
                      var num = parseFloat(vm[1].replace(/,/g, ''));
                      var unit = (vm[2] || '').toUpperCase();
                      if (unit === '万') num *= 10000;
                      else if (unit === '億') num *= 100000000;
                      else if (unit === 'K') num *= 1000;
                      else if (unit === 'M') num *= 1000000;
                      else if (unit === 'B') num *= 1000000000;
                      views = '' + Math.floor(num);
                      break;
                    }
                  }
                }
                if (!title) title = (links[i].getAttribute('aria-label') || links[i].textContent || '').trim();
              } catch(e) {}
              results.push(vid + ':::' + title.substring(0, 55) + ':::' + views);
            }
            // ── フォールバック (= ユーザー要望: ちゃんと取得してこれるように) ──
            // DOM のリンクから 1 件も取れない場合 (YouTube の DOM 変更や
            // ホーム画面のカルーセル等) は、 ページ内の初期データ JSON から
            // "videoId" を直接拾う。 タイトルは oEmbed 側で後追い補完される。
            if (results.length === 0) {
              try {
                var html = document.documentElement.innerHTML;
                var re = /"videoId"\s*:\s*"([a-zA-Z0-9_-]{11})"/g;
                var m2, seen2 = {};
                while ((m2 = re.exec(html)) !== null && results.length < 200) {
                  var v2 = m2[1];
                  if (seen2[v2] || seen[v2]) continue;
                  seen2[v2] = true;
                  results.push(v2 + ':::' + '' + ':::' + '-1');
                }
              } catch(e) {}
            }
            if (window.flutter_inappwebview) {
              window.flutter_inappwebview.callHandler('FlutterPlaylist', results.join('|||'));
            }
          } catch(e) {
            if (window.flutter_inappwebview) {
              window.flutter_inappwebview.callHandler('FlutterPlaylist', '');
            }
          } finally {
            window.__MM_EXTRACT_RUNNING__ = false;
          }
        }

        // ページタイトル抽出を最初に試みる
        try {
          var nameEl = document.querySelector('ytm-channel-header-info-renderer h1, ytm-c4-tabbed-header-renderer h1, [class*="channel-name"] [class*="title"], meta[property="og:title"]');
          var name = '';
          if (nameEl) {
            name = (nameEl.getAttribute('content') || nameEl.textContent || '').trim();
          }
          if (!name) {
            var t = document.title || '';
            name = t.replace(/\s*-\s*YouTube\s*$/, '').replace(/\s*-\s*Shorts\s*$/, '').trim();
          }
          if (name && window.flutter_inappwebview) {
            window.flutter_inappwebview.callHandler('FlutterPageTitle', name);
          }
        } catch(e) {}

        // スクロール完了後に抽出
        scrollAll(extractAll);
      })();
    ''');
  }

  @override
  Widget build(BuildContext context) {
    final screenH = MediaQuery.of(context).size.height;
    final progress = widget.urls.length > 1
        ? ' (${_urlIndex + 1}/${widget.urls.length})'
        : '';
    return SizedBox(
      height: screenH * 0.7,
      child: Column(children: [
        Container(
          margin: const EdgeInsets.symmetric(vertical: 8),
          width: 40,
          height: 4,
          decoration: BoxDecoration(
              color: Colors.white24, borderRadius: BorderRadius.circular(2)),
        ),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
          child: Row(children: [
            Container(
              width: 24,
              height: 24,
              decoration: const BoxDecoration(
                  color: Color(0xFFE53935), shape: BoxShape.circle),
              child: const Icon(Icons.playlist_play_rounded,
                  color: Colors.white, size: 16),
            ),
            const SizedBox(width: 8),
            Expanded(
                child: Text(
                    '${context.read<MindMapProvider>().t('playlist.fetching')}$progress',
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 13,
                        fontWeight: FontWeight.bold))),
            if (_loading)
              const SizedBox(
                  width: 16,
                  height: 16,
                  child: CircularProgressIndicator(
                      strokeWidth: 2,
                      valueColor:
                          AlwaysStoppedAnimation<Color>(Color(0xFFE53935)))),
            IconButton(
              icon: const Icon(Icons.close, color: Colors.white54, size: 20),
              onPressed: () {
                _finished = true;
                if (_allIds.isNotEmpty || _pageTitle != null) {
                  widget.onResults(
                      _allIds, _allTitles, _pageTitle, _allViewCounts);
                }
                Navigator.pop(context);
              },
            ),
          ]),
        ),
        Expanded(
          child: ClipRRect(
            borderRadius:
                const BorderRadius.vertical(bottom: Radius.circular(20)),
            child: iaw.InAppWebView(
              initialUrlRequest: iaw.URLRequest(
                url: iaw.WebUri(widget.urls[0]),
              ),
              initialSettings: iaw.InAppWebViewSettings(
                javaScriptEnabled: true,
                domStorageEnabled: true,
                useHybridComposition: true,
                mediaPlaybackRequiresUserGesture: false,
                transparentBackground: false,
                userAgent:
                    'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36',
              ),
              onWebViewCreated: (controller) {
                _c = controller;
                controller.addJavaScriptHandler(
                  handlerName: 'FlutterPlaylist',
                  callback: _onExtracted,
                );
                controller.addJavaScriptHandler(
                  handlerName: 'FlutterPageTitle',
                  callback: (args) {
                    if (args.isEmpty) return;
                    final t = args[0]?.toString().trim() ?? '';
                    if (t.isNotEmpty && _pageTitle == null) {
                      _pageTitle = t;
                    }
                  },
                );
              },
              onLoadStop: (controller, url) {
                if (mounted) setState(() => _loading = false);
                // 2秒待ってからJS側で全自動スクロール+抽出
                Future.delayed(const Duration(seconds: 2), _extractAll);
              },
              onReceivedError: (controller, request, error) {
                debugPrint('PlaylistExtract error: '
                    'type=${error.type} desc=${error.description} '
                    'url=${request.url}');
                // エラー時も次に進む
                if (mounted && _loading) {
                  setState(() => _loading = false);
                }
                // 抽出を試してから次へ (一部読み込まれているかもしれない)
                Future.delayed(const Duration(seconds: 3), _extractAll);
              },
              onProgressChanged: (controller, p) {
                if (mounted && p >= 100 && _loading) {
                  setState(() => _loading = false);
                }
              },
            ),
          ),
        ),
      ]),
    );
  }
}

