class _ChannelSettingsDialogState extends State<_ChannelSettingsDialog> {
  late bool _autoDelete;
  // ── 過去に生成した動画も再生成するスイッチ ──
  // Provider の `allowDuplicateVideoNodes` と連動。デフォルトは false で、
  // 一度ノード化した動画は addPlaylistNodes でスキップされる。true にすると
  // 同じチャンネル/プレイリストから再度ノード化できる。
  late bool _allowDuplicates;
  late int _limit;
  late int _minViews;
  late TextEditingController _includeCtrl;
  late TextEditingController _excludeCtrl;
  late TextEditingController _minViewsCtrl;
  late TextEditingController _limitCtrl;
  bool _showFilters = false;

  @override
  void initState() {
    super.initState();
    _autoDelete = widget.provider.autoDeleteWatched;
    _allowDuplicates = widget.provider.allowDuplicateVideoNodes;
    _limit = widget.provider.unwatchedLimit;
    _minViews = widget.provider.minViewCount;
    _includeCtrl = TextEditingController(text: widget.provider.includeKeywords);
    _excludeCtrl = TextEditingController(text: widget.provider.excludeKeywords);
    _minViewsCtrl =
        TextEditingController(text: _minViews > 0 ? '$_minViews' : '');
    _limitCtrl = TextEditingController(text: '$_limit');
  }

  @override
  void dispose() {
    _includeCtrl.dispose();
    _excludeCtrl.dispose();
    _minViewsCtrl.dispose();
    _limitCtrl.dispose();
    super.dispose();
  }

  void _saveAndPop(String mode) {
    // 設定を保存
    widget.provider.setAutoDeleteWatched(_autoDelete);
    widget.provider.setAllowDuplicateVideoNodes(_allowDuplicates);
    final lim = int.tryParse(_limitCtrl.text) ?? 5;
    widget.provider.setUnwatchedLimit(lim);
    final mv = int.tryParse(_minViewsCtrl.text) ?? 0;
    widget.provider.setMinViewCount(mv);
    widget.provider.setIncludeKeywords(_includeCtrl.text.trim());
    widget.provider.setExcludeKeywords(_excludeCtrl.text.trim());
    Navigator.pop(context, mode);
  }

