/// drawer の D&D で運ばれるデータ。
/// 単一ページ移動も複数ページ一括移動も、このペイロードで表現する。
/// drawer の D&D で運ばれるデータ。
/// 単一ページ移動も複数ページ一括移動も、このペイロードで表現する。
class _DrawerPageDragData {
  /// 移動対象ページ ID 一覧 (1 個以上)
  final List<String> pageIds;

  /// ドラッグ中フィードバックに表示する代表ページ名
  final String primaryTitle;
  const _DrawerPageDragData({
    required this.pageIds,
    required this.primaryTitle,
  });
}

/// drawer のフォルダーコンテキストメニュー (showMenu) の選択肢
enum _FolderAction {
  rename,

  /// 1 つの大きな .folder.json として書き出す (従来)
  export,

  /// ディレクトリを選び、各ページを個別の .json ファイルとして書き出す (新)
  exportAsDirectory,
  delete,
  bulkDelete,
  clearSelection,

  /// Ctrl+1〜9 の基準フォルダーとして設定 (or 解除)
  toggleShortcut,
}

/// drawer のページコンテキストメニュー (showMenu) の選択肢
// ════════════════════════════════════════════════════════════════════
//  マークダウン⇄マインドマップ (= ユーザー要望: JSON でなく Markdown で書ける /
//  出力を模式図でプレビュー)
// ════════════════════════════════════════════════════════════════════

/// ページのノード木を「インデント箇条書き」 の Markdown に変換する。
String _pageToMarkdown(MindMapPage page) {
  final incoming = <String>{};
  final childrenOf = <String, List<String>>{};
  for (final c in page.connections) {
    incoming.add(c.toId);
    childrenOf.putIfAbsent(c.fromId, () => []).add(c.toId);
  }
  final roots = page.nodes.keys.where((id) => !incoming.contains(id)).toList();
  final b = StringBuffer();
  final visited = <String>{};
  void walk(String id, int depth) {
    if (visited.contains(id)) return;
    visited.add(id);
    final node = page.nodes[id];
    if (node == null) return;
    final title = node.title.replaceAll('\n', ' ').trim();
    b.writeln('${'  ' * depth}- ${title.isEmpty ? '(無題)' : title}');
    for (final ch in (childrenOf[id] ?? const <String>[])) {
      walk(ch, depth + 1);
    }
  }

  for (final r in roots) {
    walk(r, 0);
  }
  for (final id in page.nodes.keys) {
    if (!visited.contains(id)) walk(id, 0);
  }
  if (b.isEmpty) return '- 中心テーマ\n  - 子要素1\n  - 子要素2\n';
  return b.toString();
}

/// Markdown (インデント/箇条書き/見出し) を (depth, text, parent index) の列へ。
List<({int depth, String text, int parent})> _parseMarkdownOutline(String md) {
  final res = <({int depth, String text, int parent})>[];
  final stack = <int>[]; // stack[k] = depth k のノードの res index
  for (final raw in md.split('\n')) {
    if (raw.trim().isEmpty) continue;
    int indent = 0;
    for (final cu in raw.codeUnits) {
      if (cu == 32) {
        indent++;
      } else if (cu == 9) {
        indent += 2;
      } else {
        break;
      }
    }
    var text = raw.trimLeft();
    text = text.replaceFirst(RegExp(r'^([-*+]\s+|#{1,6}\s+)'), '').trim();
    if (text.isEmpty) continue;
    var depth = indent ~/ 2;
    if (depth > stack.length) depth = stack.length; // 飛びを正規化
    while (stack.length > depth) {
      stack.removeLast();
    }
    final parent = stack.isEmpty ? -1 : stack.last;
    res.add((depth: depth, text: text, parent: parent));
    stack.add(res.length - 1);
  }
  return res;
}

/// 木をツリーレイアウト (depth=列、 葉を順に並べ親は子の中央) して座標を付ける。
List<({String text, int parentIndex, double x, double y})> _layoutMarkdownTree(
    List<({int depth, String text, int parent})> items) {
  final n = items.length;
  final children = List.generate(n, (_) => <int>[]);
  final roots = <int>[];
  for (int i = 0; i < n; i++) {
    final p = items[i].parent;
    if (p >= 0 && p < n) {
      children[p].add(i);
    } else {
      roots.add(i);
    }
  }
  final pos = List<Offset>.filled(n, Offset.zero);
  const colW = 210.0, rowH = 64.0;
  double nextLeafY = 0;
  double assign(int i) {
    final d = items[i].depth;
    double y;
    if (children[i].isEmpty) {
      y = nextLeafY;
      nextLeafY += rowH;
    } else {
      final ys = children[i].map(assign).toList();
      y = (ys.first + ys.last) / 2;
    }
    pos[i] = Offset(d * colW, y);
    return y;
  }

  for (final r in roots) {
    assign(r);
  }
  return [
    for (int i = 0; i < n; i++)
      (
        text: items[i].text,
        parentIndex: items[i].parent,
        x: pos[i].dx,
        y: pos[i].dy
      )
  ];
}

