class _MarkdownMindMapDialogState extends State<_MarkdownMindMapDialog> {
  late final TextEditingController _ctrl;
  List<({String text, int parentIndex, double x, double y})> _laid = [];

  @override
  void initState() {
    super.initState();
    _ctrl = TextEditingController(text: widget.initial);
    _reparse();
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  void _reparse() {
    _laid = _layoutMarkdownTree(_parseMarkdownOutline(_ctrl.text));
  }

  Widget _editor() => Container(
        color: const Color(0xFF14141F),
        padding: const EdgeInsets.all(8),
        child: TextField(
          controller: _ctrl,
          maxLines: null,
          expands: true,
          textAlignVertical: TextAlignVertical.top,
          onChanged: (_) => setState(_reparse),
          style: const TextStyle(
              color: Colors.white, fontSize: 13, fontFamily: 'monospace'),
          decoration: InputDecoration(
            border: InputBorder.none,
            isDense: true,
            hintText: context.read<MindMapProvider>().t('md.hint'),
            hintStyle: const TextStyle(color: Colors.white24),
          ),
        ),
      );

  Widget _preview() {
    const boxW = 180.0, boxH = 38.0;
    double maxX = 0, maxY = 0;
    for (final nd in _laid) {
      if (nd.x > maxX) maxX = nd.x;
      if (nd.y > maxY) maxY = nd.y;
    }
    final w = maxX + boxW + 60;
    final h = maxY + boxH + 60;
    return Container(
      color: const Color(0xFF0E0E16),
      child: _laid.isEmpty
          ? Center(
              child: Text(
                  context.read<MindMapProvider>().t('md.previewPlaceholder'),
                  style: const TextStyle(color: Colors.white38, fontSize: 12)))
          : InteractiveViewer(
              constrained: false,
              minScale: 0.2,
              maxScale: 3.0,
              boundaryMargin: const EdgeInsets.all(200),
              child: SizedBox(
                width: w < 200 ? 200 : w,
                height: h < 160 ? 160 : h,
                child: CustomPaint(painter: _MarkdownDiagramPainter(_laid)),
              ),
            ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final isMobile = MediaQuery.of(context).size.width < 700;
    return Dialog(
      backgroundColor: const Color(0xFF1A1A2E),
      insetPadding: const EdgeInsets.all(20),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
      child: SizedBox(
        width: isMobile ? double.infinity : 860,
        height: isMobile ? double.infinity : 620,
        child: Column(children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 12, 8, 8),
            child: Row(children: [
              const Icon(Icons.notes_rounded,
                  color: Color(0xFF26C6DA), size: 22),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                    context.read<MindMapProvider>().t('md.editMarkdown'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 16,
                        fontWeight: FontWeight.w700)),
              ),
              IconButton(
                onPressed: () => Navigator.pop(context),
                icon: const Icon(Icons.close, color: Colors.white70),
              ),
            ]),
          ),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: Align(
              alignment: Alignment.centerLeft,
              child: Text(context.read<MindMapProvider>().t('md.helpText'),
                  style: const TextStyle(color: Colors.white38, fontSize: 11)),
            ),
          ),
          const SizedBox(height: 6),
          Expanded(
            child: isMobile
                ? Column(children: [
                    Expanded(child: _editor()),
                    const Divider(color: Colors.white12, height: 1),
                    Expanded(child: _preview()),
                  ])
                : Row(children: [
                    Expanded(child: _editor()),
                    const VerticalDivider(color: Colors.white12, width: 1),
                    Expanded(child: _preview()),
                  ]),
          ),
          const Divider(color: Colors.white12, height: 1),
          Padding(
            padding: const EdgeInsets.all(10),
            child: Row(children: [
              Text(
                  context
                      .read<MindMapProvider>()
                      .t('md.nodeCount')
                      .replaceFirst('{n}', '${_laid.length}'),
                  style: const TextStyle(color: Colors.white38, fontSize: 12)),
              const Spacer(),
              TextButton(
                  onPressed: () => Navigator.pop(context),
                  child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                      style: const TextStyle(color: Colors.white54))),
              const SizedBox(width: 8),
              ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF26C6DA),
                    foregroundColor: Colors.black),
                onPressed: _laid.isEmpty
                    ? null
                    : () {
                        widget.onApply(_laid);
                        Navigator.pop(context);
                      },
                icon: const Icon(Icons.check_rounded, size: 18),
                label: Text(context.read<MindMapProvider>().t('md.applyToMap')),
              ),
            ]),
          ),
        ]),
      ),
    );
  }
}

class _MarkdownDiagramPainter extends CustomPainter {
  final List<({String text, int parentIndex, double x, double y})> nodes;
  _MarkdownDiagramPainter(this.nodes);
  @override
  void paint(Canvas canvas, Size size) {
    const boxW = 180.0, boxH = 38.0;
    const margin = Offset(24, 24);
    final line = Paint()
      ..color = const Color(0xFF4FC3F7)
      ..strokeWidth = 1.5
      ..style = PaintingStyle.stroke;
    for (int i = 0; i < nodes.length; i++) {
      final p = nodes[i].parentIndex;
      if (p >= 0 && p < nodes.length) {
        final from = Offset(
            nodes[p].x + margin.dx + boxW, nodes[p].y + margin.dy + boxH / 2);
        final to =
            Offset(nodes[i].x + margin.dx, nodes[i].y + margin.dy + boxH / 2);
        final mid = (from.dx + to.dx) / 2;
        final path = Path()
          ..moveTo(from.dx, from.dy)
          ..cubicTo(mid, from.dy, mid, to.dy, to.dx, to.dy);
        canvas.drawPath(path, line);
      }
    }
    for (int i = 0; i < nodes.length; i++) {
      final isRoot = nodes[i].parentIndex < 0;
      final r = Rect.fromLTWH(
          nodes[i].x + margin.dx, nodes[i].y + margin.dy, boxW, boxH);
      final rr = RRect.fromRectAndRadius(r, const Radius.circular(8));
      canvas.drawRRect(
          rr,
          Paint()
            ..color =
                isRoot ? const Color(0xFF1B3A4A) : const Color(0xFF2A2A46));
      canvas.drawRRect(
          rr,
          Paint()
            ..color = const Color(0xFF4FC3F7)
            ..style = PaintingStyle.stroke
            ..strokeWidth = isRoot ? 1.8 : 1.1);
      final tp = TextPainter(
        text: TextSpan(
            text: nodes[i].text,
            style: TextStyle(
                color: Colors.white,
                fontSize: 12,
                fontWeight: isRoot ? FontWeight.w700 : FontWeight.w400)),
        textDirection: TextDirection.ltr,
        maxLines: 2,
        ellipsis: '…',
      )..layout(maxWidth: boxW - 14);
      tp.paint(canvas, Offset(r.left + 7, r.top + (boxH - tp.height) / 2));
    }
  }

  @override
  bool shouldRepaint(covariant _MarkdownDiagramPainter old) => true;
}

