/// drawer の表示アイテム種別 (Shift 範囲選択でフラットインデックスを取るため)
enum _DrawerFlatItemKind { folder, page }

/// drawer のフラット化されたアイテム1件。
/// kind=folder ならフォルダー、kind=page ならページを表す。
class _DrawerFlatItem {
  final _DrawerFlatItemKind kind;
  final String id;
  const _DrawerFlatItem({required this.kind, required this.id});
}

/// ページタイルを上下方向の D&D 並び替え対応にラップする。
/// 別のページタイル (フォルダーヘッダーやルート領域は対象外) からドロップ
/// された際、ホバー位置 (上半分 / 下半分) で挿入位置を決定し、
/// `provider.reorderPages` を呼び出す。
/// 同時に既存の「フォルダー間移動」「ルート移動」の DragTarget は
/// それぞれ別レイヤーで動作するので、こちらでは並び替えのみを担当する。
class _ReorderDropZone extends StatefulWidget {
  final String targetPageId;
  final MindMapProvider provider;
  final VoidCallback? onReordered;
  final Widget child;
  const _ReorderDropZone({
    required this.targetPageId,
    required this.provider,
    required this.child,
    this.onReordered,
  });
  @override
  State<_ReorderDropZone> createState() => _ReorderDropZoneState();
}

class _ReorderDropZoneState extends State<_ReorderDropZone> {
  /// 0.0..1.0 の Y 比率で「ホバー中の挿入位置」を保持。
  /// null = ホバーしていない / 上半分 = 直前挿入 / 下半分 = 直後挿入。
  bool? _insertAbove;

  @override
  Widget build(BuildContext context) {
    return DragTarget<_DrawerPageDragData>(
      // 同じページ自身は受け付けない (移動になっていないため)
      onWillAcceptWithDetails: (details) {
        if (details.data.pageIds.length != 1) return false;
        final dragId = details.data.pageIds.first;
        return dragId != widget.targetPageId;
      },
      onMove: (details) {
        // ホバー位置 (上半分 / 下半分) で挿入位置をリアルタイム表示
        final box = context.findRenderObject() as RenderBox?;
        if (box == null) return;
        final localY = box.globalToLocal(details.offset).dy;
        final ratio = (localY + 24) / box.size.height;
        final above = ratio < 0.5;
        if (_insertAbove != above) {
          setState(() => _insertAbove = above);
        }
      },
      onLeave: (_) {
        if (_insertAbove != null) {
          setState(() => _insertAbove = null);
        }
      },
      onAcceptWithDetails: (details) {
        if (details.data.pageIds.length != 1) return;
        final dragId = details.data.pageIds.first;
        final pages = widget.provider.pages;
        final fromIdx = pages.indexWhere((p) => p.id == dragId);
        final toIdx = pages.indexWhere((p) => p.id == widget.targetPageId);
        if (fromIdx < 0 || toIdx < 0) return;
        // 上半分 → ターゲットの直前、下半分 → 直後
        final inserted = (_insertAbove ?? true) ? toIdx : toIdx + 1;
        widget.provider.reorderPages(fromIdx, inserted);
        // ドロップ先のページのフォルダー所属に合わせて、ドラッグ元の
        // folderId も同じものにする (同じフォルダー内 or ルートで並び替え)
        final targetPage = pages[toIdx];
        final draggedPage = pages.firstWhere((p) => p.id == dragId,
            orElse: () => pages[fromIdx]);
        if (draggedPage.folderId != targetPage.folderId) {
          widget.provider.movePageToFolder(dragId, targetPage.folderId);
        }
        setState(() => _insertAbove = null);
        widget.onReordered?.call();
      },
      builder: (ctx, candidate, rejected) {
        // 挿入位置を視覚化する細い線 (上 or 下)
        final showAbove = candidate.isNotEmpty && (_insertAbove ?? true);
        final showBelow = candidate.isNotEmpty && _insertAbove == false;
        return Stack(
          children: [
            widget.child,
            if (showAbove)
              Positioned(
                top: 0,
                left: 8,
                right: 8,
                child: Container(
                  height: 3,
                  decoration: BoxDecoration(
                    color: const Color(0xFF00E5FF),
                    borderRadius: BorderRadius.circular(2),
                    boxShadow: [
                      BoxShadow(
                          color: const Color(0xFF00E5FF).withValues(alpha: 0.5),
                          blurRadius: 6),
                    ],
                  ),
                ),
              ),
            if (showBelow)
              Positioned(
                bottom: 0,
                left: 8,
                right: 8,
                child: Container(
                  height: 3,
                  decoration: BoxDecoration(
                    color: const Color(0xFF00E5FF),
                    borderRadius: BorderRadius.circular(2),
                    boxShadow: [
                      BoxShadow(
                          color: const Color(0xFF00E5FF).withValues(alpha: 0.5),
                          blurRadius: 6),
                    ],
                  ),
                ),
              ),
          ],
        );
      },
    );
  }
}

/// ページ一覧の「◯ 文字 / ◯ ノード」 の行。
///
/// = ユーザー要望「マークダウンの文字数カウントが、 ページを操作していない
///   のに動くのが目障り。 文字数が変わらないなら動かないで」。
///
/// 以前は `FutureBuilder(future: _drawerPageMetricText(...))` を build の中で
/// 直に作っていたため、 一覧が描き直されるたびに
///   ① いったん初期値 (0 文字) に戻る → ② 数え終わって本当の数に飛ぶ
/// という往復が見えていた。 ここでは**前に出した文字をそのまま出し続け**、
/// 数え直した結果が変わった時だけ書き換える。
class _DrawerMetricText extends StatefulWidget {
  final dynamic page;
  final MindMapProvider provider;
  final TextStyle? style;
  const _DrawerMetricText(
      {required this.page, required this.provider, this.style});

  @override
  State<_DrawerMetricText> createState() => _DrawerMetricTextState();
}

class _DrawerMetricTextState extends State<_DrawerMetricText> {
  /// ページ id → 最後に出した文字。 画面をまたいでも持ち越すので、
  /// 一覧を開き直した時も数え終わるまで前の値を出せる。
  static final Map<String, String> _cache = {};

  String? _text;
  bool _counting = false;

  String get _pageId => (widget.page.id ?? '').toString();

  @override
  void initState() {
    super.initState();
    _text = _cache[_pageId];
    unawaited(_recount());
  }

  @override
  void didUpdateWidget(covariant _DrawerMetricText old) {
    super.didUpdateWidget(old);
    if ((old.page.id ?? '') != (widget.page.id ?? '')) {
      _text = _cache[_pageId];
    }
    unawaited(_recount());
  }

  Future<void> _recount() async {
    if (_counting) return; // 数えている最中に重ねない
    _counting = true;
    try {
      final t = await _drawerPageMetricText(widget.page, widget.provider);
      _cache[_pageId] = t;
      // ★ 変わっていなければ setState しない (= 画面を動かさない)。
      if (mounted && t != _text) setState(() => _text = t);
    } catch (_) {
      // 数えられなかった時は前の表示のまま (0 に戻さない)。
    } finally {
      _counting = false;
    }
  }

  @override
  Widget build(BuildContext context) {
    final t = _text ??
        _drawerPageMetricFallback(widget.page, widget.provider);
    return Text(
      t,
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: widget.style ??
          const TextStyle(color: Colors.white30, fontSize: 10),
    );
  }
}

Future<String> _drawerPageMetricText(
    dynamic page, MindMapProvider provider) async {
  final type = (page.pageType ?? 'normal').toString();
  final id = (page.id ?? '').toString();
  switch (type) {
    case 'bookshelf':
      return '${page.nodes.length} ${provider.t('drawer.itemSuffix')}';
    case 'paint':
      // フリーノートは「ノート数 / ページ数」 を出す (= ユーザー要望)。
      final c = await _paintNotePageCountForPage(id);
      return provider
          .t('drawer.paintCounts')
          .replaceFirst('{notes}', '${c.notes}')
          .replaceFirst('{pages}', '${c.pages}');
    case 'document':
      final chars = await _documentCharCountForPage(id);
      return '$chars ${provider.t('drawer.charSuffix')}';
    // Markdown ページはノードを持たないので、 文書と同じく文字数で
    // 数える (= ユーザー要望: ノード数ではなく要素の量が分かるように)。
    case 'markdown':
      final md = await _markdownStatsForPage(id);
      return md.tabs > 1
          ? '${md.tabs} ${provider.t('md.tabSuffix')} ・ '
              '${md.chars} ${provider.t('drawer.charSuffix')}'
          : '${md.chars} ${provider.t('drawer.charSuffix')}';
    case 'videoEditor':
      final items = await _videoEditorItemCountForPage(id);
      return '$items ${provider.t('drawer.timelineItemSuffix')}';
    default:
      return '${page.nodes.length} ${provider.t('drawer.nodeSuffix')}';
  }
}

/// クラウド側ページの件数テキスト。 ローカルの prefs は当てにできないので、
/// マップ / ギャラリーはページ JSON から、 フリーノートは一緒に受け取った
/// JSON から数える。 それ以外は種別名だけ出す
/// (= ユーザー要望: ノード数で表現しない)。
String _cloudPageMetricText(dynamic page, MindMapProvider provider) {
  final type = (page.pageType ?? 'normal').toString();
  switch (type) {
    case 'normal':
      return provider
          .t('admin.nodeCount')
          .replaceFirst('{n}', '${page.nodes.length}');
    case 'bookshelf':
      return '${page.nodes.length} ${provider.t('drawer.itemSuffix')}';
    case 'paint':
      final raw = provider.cloudPaintJsonFor((page.id ?? '').toString());
      if (raw == null || raw.isEmpty) return provider.pageTypeLabel(type);
      final c = _paintNotePageCountFromJson(raw);
      return provider
          .t('drawer.paintCounts')
          .replaceFirst('{notes}', '${c.notes}')
          .replaceFirst('{pages}', '${c.pages}');
    default:
      return provider.pageTypeLabel(type);
  }
}

String _drawerPageMetricFallback(dynamic page, MindMapProvider provider) {
  final type = (page.pageType ?? 'normal').toString();
  switch (type) {
    case 'bookshelf':
      return '${page.nodes.length} ${provider.t('drawer.itemSuffix')}';
    case 'paint':
      return provider
          .t('drawer.paintCounts')
          .replaceFirst('{notes}', '0')
          .replaceFirst('{pages}', '0');
    case 'document':
    case 'markdown':
      return '0 ${provider.t('drawer.charSuffix')}';
    case 'videoEditor':
      return '0 ${provider.t('drawer.timelineItemSuffix')}';
    default:
      return '${page.nodes.length} ${provider.t('drawer.nodeSuffix')}';
  }
}

Future<bool> _pageHasPlacedContent(dynamic page) async {
  final type = (page.pageType ?? 'normal').toString();
  final id = (page.id ?? '').toString();
  final hasMapContent = page.nodes.isNotEmpty ||
      page.connections.isNotEmpty ||
      page.decorations.isNotEmpty ||
      ((page.backgroundImagePath ?? '').toString().isNotEmpty);
  if (hasMapContent) return true;
  switch (type) {
    case 'normal':
    case 'bookshelf':
      return false;
    case 'document':
      return await _documentCharCountForPage(id) > 0;
    case 'markdown':
      return await _markdownCharCountForPage(id) > 0;
    case 'videoEditor':
      return await _videoEditorItemCountForPage(id) > 0;
    default:
      return true;
  }
}

/// 保存済みフリーノートの要素数。
///
/// 現行形式 `{notes:[{pages:[{s,t,sh,im}]}],noteSel}`、旧 `{sheets,...}`、
/// ストローク配列、`{s,t}` のいずれも読めるようにする。消しゴムマスク (`e:true`)
/// は表示中の対象を削る編集情報であり、独立した要素には数えない。
/// フリーノートの「ノート数」 と「ページ数」 を数える
/// (= ユーザー要望: マップ一覧のフリーノートは要素数ではなく、
/// ページ数とノート数を出す)。
///
/// 保存形式は 3 世代ある:
///   v3: {notes: [{pages: [...]}, ...]}   ← 現行 (ノート ⊃ ページ)
///   v2: {sheets: [...]}                  ← ノートの概念が無い (= ノート 1)
///   v1: [...]                            ← 1 ページぶんの要素配列
Future<({int notes, int pages})> _paintNotePageCountForPage(
    String pageId) async {
  if (pageId.isEmpty) return (notes: 0, pages: 0);
  try {
    final sp = await SharedPreferences.getInstance();
    final raw = sp.getString('paint_$pageId');
    if (raw == null || raw.isEmpty) return (notes: 0, pages: 0);
    return _paintNotePageCountFromJson(raw);
  } catch (_) {}
  return (notes: 0, pages: 0);
}

/// 上と同じ数え方を、 保存済み JSON 文字列に対して行う
/// (= クラウドから受け取った内容の件数表示用)。
({int notes, int pages}) _paintNotePageCountFromJson(String raw) {
  try {
    final decoded = jsonDecode(raw);
    if (decoded is List) {
      // v1: 単一ページ
      return (notes: 1, pages: 1);
    }
    if (decoded is Map) {
      final notes = decoded['notes'];
      if (notes is List) {
        var noteCount = 0;
        var pageCount = 0;
        for (final note in notes) {
          if (note is! Map) continue;
          noteCount++;
          final pages = note['pages'];
          if (pages is List) pageCount += pages.length;
        }
        return (notes: noteCount, pages: pageCount);
      }
      final sheets = decoded['sheets'];
      if (sheets is List) {
        return (notes: 1, pages: sheets.length);
      }
      return (notes: 1, pages: 1);
    }
  } catch (_) {}
  return (notes: 0, pages: 0);
}

/// Markdown ページのタブ数と文字数 (= ユーザー要望: ノード数ではなく
/// 文字数等で要素の量を数える)。 本文は prefs (markdown_<pageId>) にあり、
/// 今はタブの束 (JSON) で入っている (旧い素のテキストも読める)。
Future<({int tabs, int chars})> _markdownStatsForPage(String pageId) async {
  if (pageId.isEmpty) return (tabs: 0, chars: 0);
  try {
    final sp = await SharedPreferences.getInstance();
    final doc = decodeMarkdownDoc(sp.getString('markdown_$pageId'));
    var chars = 0;
    for (final t in doc.tabs) {
      chars += t.text.trim().runes.length;
    }
    return (tabs: doc.tabs.length, chars: chars);
  } catch (_) {}
  return (tabs: 0, chars: 0);
}

Future<int> _markdownCharCountForPage(String pageId) async =>
    (await _markdownStatsForPage(pageId)).chars;

Future<int> _documentCharCountForPage(String pageId) async {
  if (pageId.isEmpty) return 0;
  try {
    final sp = await SharedPreferences.getInstance();
    final raw = sp.getString('document_$pageId');
    if (raw == null || raw.isEmpty) return 0;
    final decoded = jsonDecode(raw);
    if (decoded is List) return _deltaCharCount(decoded);
    if (decoded is Map) {
      final pages = decoded['pages'];
      if (pages is List) {
        var total = 0;
        for (final page in pages) {
          if (page is List) total += _deltaCharCount(page);
        }
        return total;
      }
    }
  } catch (_) {}
  return 0;
}

int _deltaCharCount(List<dynamic> delta) {
  final b = StringBuffer();
  for (final op in delta) {
    if (op is Map) {
      final insert = op['insert'];
      if (insert is String) b.write(insert);
    }
  }
  return b.toString().trim().runes.length;
}

Future<int> _videoEditorItemCountForPage(String pageId) async {
  if (pageId.isEmpty) return 0;
  try {
    final sp = await SharedPreferences.getInstance();
    final raw = sp.getString('videoEditor_$pageId');
    if (raw == null || raw.isEmpty) return 0;
    final decoded = jsonDecode(raw);
    if (decoded is Map && decoded['items'] is List) {
      return (decoded['items'] as List).length;
    }
    if (decoded is List) {
      return decoded.where((e) {
        if (e is! Map) return false;
        return ((e['p'] ?? '').toString()).isNotEmpty;
      }).length;
    }
  } catch (_) {}
  return 0;
}

class _DrawerTile extends StatelessWidget {
  final int index;
  final dynamic page;
  final bool isActive;
  final bool isAutoSync;
  final VoidCallback onTap, onRename;
  final VoidCallback? onDelete;
  final VoidCallback? onToggleAutoSync;

  /// 追加メニューを開くコールバック (フォルダー移動 / JSON エクスポート等)。
  /// 引数: メニューを表示する基準位置の BuildContext。null なら画面中央付近。
  /// 呼び出し側は IconButton 等の Builder 内で渡された btnCtx をそのまま渡せば、
  /// その RenderBox 位置がアンカーとして使われる。
  final void Function(BuildContext?)? onMore;
  final String? sizeText;
  final String? shortcutLabel;

  /// drawer の複数選択モードでこのタイルが選択中かどうか
  final bool isMultiSelected;

  /// タイルの長押し時の追加コールバック (onMore とは別に複数選択トリガー用)
  /// null なら従来通り onMore が呼ばれる。
  final VoidCallback? onLongPress;

  /// 最終更新日時を相対的にフォーマット
  /// 今日 → HH:mm / 昨日 → 昨日 HH:mm / 今年 → M/d HH:mm / それ以前 → yy/M/d
  static String _formatLastModified(DateTime raw, MindMapProvider provider) {
    // UTC で作られた値が混ざっても時刻がずれないように、 必ず地方時に直す。
    final dt = raw.isUtc ? raw.toLocal() : raw;
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final target = DateTime(dt.year, dt.month, dt.day);
    final diffDays = today.difference(target).inDays;
    String two(int n) => n.toString().padLeft(2, '0');
    if (diffDays == 0) {
      return '${provider.t('drawer.time.today')} ${two(dt.hour)}:${two(dt.minute)}';
    } else if (diffDays == 1) {
      return '${provider.t('drawer.time.yesterday')} ${two(dt.hour)}:${two(dt.minute)}';
    } else if (dt.year == now.year) {
      return '${dt.month}/${dt.day} ${two(dt.hour)}:${two(dt.minute)}';
    } else {
      final yy = (dt.year % 100).toString().padLeft(2, '0');
      return "$yy/${dt.month}/${dt.day} ${two(dt.hour)}:${two(dt.minute)}";
    }
  }

  const _DrawerTile(
      {super.key,
      required this.index,
      required this.page,
      required this.isActive,
      required this.onTap,
      required this.onRename,
      this.onDelete,
      this.onMore,
      this.isAutoSync = false,
      this.onToggleAutoSync,
      this.sizeText,
      this.shortcutLabel,
      this.isMultiSelected = false,
      this.onLongPress});
  @override
  Widget build(BuildContext context) {
    final provider = context.watch<MindMapProvider>();
    final baseColor = provider.headerColor;
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
      decoration: BoxDecoration(
        // 複数選択中はシアン背景で目立たせる (active の紫より優先)
        color: isMultiSelected
            ? const Color(0xFF00E5FF).withValues(alpha: 0.18)
            : (isActive
                ? Color.alphaBlend(
                    Colors.white.withValues(alpha: 0.10), baseColor)
                : baseColor.withValues(alpha: 0.16)),
        borderRadius: BorderRadius.circular(10),
        border: isMultiSelected
            ? Border.all(
                color: const Color(0xFF00E5FF).withValues(alpha: 0.6),
                width: 1.5)
            : (isActive
                ? Border.all(color: Colors.white.withValues(alpha: 0.28))
                : Border.all(color: baseColor.withValues(alpha: 0.22))),
      ),
      child: ListTile(
        dense: true,
        contentPadding: const EdgeInsets.only(left: 4, right: 4),
        // 長押し動作: 複数選択 onLongPress が指定されていればそちら、
        //              それ以外は従来の onMore (右クリック相当のメニュー)。
        //              onMore は GlobalKey 引数を取るので null を渡してフォールバック。
        onLongPress:
            onLongPress ?? (onMore == null ? null : () => onMore!(null)),
        leading: SizedBox(
          width: 28,
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
            // ページ種別ごとに分かりやすいアイコンを出す (= ユーザー要望:
            //   ギャラリー / ガントチャート / お絵かきページの専用アイコン)。
            //   ★ 利用者が選んだアイコンがあれば、 そちらを優先する
            //     (= ユーザー要望: ページごと / 種類ごとに変えられるように)。
            child: () {
              final chosen = context
                  .read<MindMapProvider>()
                  .pageIconIndexFor(page.id, page.pageType);
              if (chosen != null &&
                  chosen >= 0 &&
                  chosen < kPageIconChoices.length) {
                final c = _pageIconColorOf(page.pageType);
                return Icon(kPageIconChoices[chosen],
                    size: 16,
                    color: isActive ? c : c.withValues(alpha: 0.6));
              }
              switch (page.pageType) {
                case 'bookshelf':
                  return Icon(Icons.shelves,
                      size: 16,
                      color: isActive
                          ? const Color(0xFFFF7043)
                          : const Color(0xFFFF7043).withValues(alpha: 0.6));
                case 'paint':
                  return Icon(Icons.brush_rounded,
                      size: 16,
                      color: isActive
                          ? const Color(0xFFEC407A)
                          : const Color(0xFFEC407A).withValues(alpha: 0.6));
                case 'document':
                  return Icon(Icons.article_rounded,
                      size: 16,
                      color: isActive
                          ? const Color(0xFF4FC3F7)
                          : const Color(0xFF4FC3F7).withValues(alpha: 0.6));
                // Markdown ページ専用のアイコン (= ユーザー要望)。
                case 'markdown':
                  return Icon(Icons.polyline_rounded,
                      size: 16,
                      color: isActive
                          ? const Color(0xFF5FD3B2)
                          : const Color(0xFF5FD3B2).withValues(alpha: 0.6));
                case 'videoEditor':
                  return Icon(Icons.movie_creation_rounded,
                      size: 16,
                      color: isActive
                          ? const Color(0xFFFF7043)
                          : const Color(0xFFFF7043).withValues(alpha: 0.6));
                default:
                  // マインドマップだけ選択中以外が白 (= 無彩色) で、 他の種類と
                  //   並んだ時に色が付いていないように見えていた
                  //   (= ユーザー要望)。 他と同じく種別の色を薄くして出す。
                  //   青系は文書と被るので、 アプリの基調色の紫を使う。
                  return Icon(isActive ? Icons.map : Icons.map_outlined,
                      size: 16,
                      color: isActive
                          ? const Color(0xFF8B84FF)
                          : const Color(0xFF8B84FF).withValues(alpha: 0.6));
              }
            }(),
          ),
        ),
        title: Text(page.name,
            style: TextStyle(
              color: isActive ? Colors.white : Colors.white60,
              fontSize: 13,
              fontWeight: isActive ? FontWeight.bold : FontWeight.normal,
            ),
            overflow: TextOverflow.ellipsis),
        subtitle: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(children: [
              Flexible(
                child: _DrawerMetricText(page: page, provider: provider),
              ),
              if (sizeText != null) ...[
                const Text(' · ',
                    style: TextStyle(color: Colors.white24, fontSize: 10)),
                const Icon(Icons.data_usage_rounded,
                    size: 9, color: Colors.white38),
                const SizedBox(width: 2),
                Text(sizeText!,
                    style: const TextStyle(
                        color: Colors.white54,
                        fontSize: 10,
                        fontWeight: FontWeight.w600)),
              ],
            ]),
            const SizedBox(height: 2),
            Row(children: [
              const Icon(Icons.schedule_rounded,
                  size: 9, color: Colors.white38),
              const SizedBox(width: 3),
              Text(_formatLastModified(page.lastModifiedAt, provider),
                  style: const TextStyle(color: Colors.white38, fontSize: 10)),
            ]),
          ],
        ),
        trailing: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            // ── 共同編集中の印 (= ユーザー要望: どのページを共有中か
            //    一覧から分かるように)。 セッションを張っているページだけ。 ──
            if (provider.liveActive && provider.livePageId == page.id)
              Tooltip(
                message: provider.t('live.pageBadge'),
                child: Container(
                  margin: const EdgeInsets.only(right: 2),
                  padding:
                      const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                  decoration: BoxDecoration(
                    color: const Color(0xFF43B97F).withValues(alpha: 0.18),
                    borderRadius: BorderRadius.circular(999),
                    border: Border.all(
                        color: const Color(0xFF43B97F).withValues(alpha: 0.6)),
                  ),
                  child: const Icon(Icons.groups_rounded,
                      size: 13, color: Color(0xFF43B97F)),
                ),
              ),
            if (shortcutLabel != null)
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                margin: const EdgeInsets.only(right: 2),
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.08),
                  borderRadius: BorderRadius.circular(4),
                  border: Border.all(color: Colors.white12),
                ),
                child: Text(shortcutLabel!,
                    style: const TextStyle(
                        color: Colors.white38,
                        fontSize: 9,
                        fontWeight: FontWeight.w600)),
              ),
            if (onToggleAutoSync != null)
              GestureDetector(
                onTap: onToggleAutoSync,
                child: Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 4),
                  child: Icon(
                    isAutoSync
                        ? Icons.cloud_done_rounded
                        : Icons.cloud_off_rounded,
                    size: 16,
                    color:
                        isAutoSync ? const Color(0xFF43B97F) : Colors.white24,
                  ),
                ),
              ),
            // ── 「メニューを開く」ボタン (旧 PopupMenuButton 撤廃) ──
            // 以前は「名前変更/その他の操作.../削除」の 3 項目だけ表示する
            // PopupMenuButton で、しかも位置が画面左上に出る不具合があった。
            // 全項目を一度に表示する _showPageContextMenu (= showMenu)
            // に統合し、IconButton の Builder で取得した RenderBox 位置を
            // anchor として渡す。
            Builder(builder: (btnCtx) {
              return IconButton(
                tooltip: provider.t('tooltip.openMenu'),
                padding: EdgeInsets.zero,
                iconSize: 16,
                constraints: const BoxConstraints(minWidth: 24, minHeight: 24),
                icon: const Icon(Icons.more_vert,
                    color: Colors.white30, size: 16),
                onPressed: () {
                  // Builder の btnCtx は IconButton の RenderBox に紐づくので、
                  // そのまま onMore 経由で _showPageContextMenu に渡し、
                  // RelativeRect.fromRect(btnCtx) でメニュー位置を決める。
                  onMore?.call(btnCtx);
                },
              );
            }),
          ],
        ),
        onTap: onTap,
      ),
    );
  }
}

// ─── グリッド背景 ─────────────────────────────────────────────────────────────

// ─── グループ背景ペインター（付箋風にノードの後ろに表示）──────────────────────

class _GroupBackgroundPainter extends CustomPainter {
  final Map<String, Set<String>> groups;
  final Map<String, MindMapNode> nodes;
  final Map<String, int> colorOverrides;
  final Map<String, double> fontSizeOverrides;
  final Map<String, String> fontFamilyOverrides;
  final Map<String, List<double>> paddingOverrides;
  final bool isDark;

  /// グループ枠の表示色プリセット (10 色)。
  /// 同じマップに複数のグループがある場合、ユーザーが上書きしていなければ
  /// この配列の先頭から順に使われる。ユーザーは右クリック → 色変更で
  /// この 10 色から自由に選択可能。
  static const groupColors = [
    Color(0xFFFFB347), // オレンジ
    Color(0xFF4FC3F7), // 水色
    Color(0xFF43B97F), // 緑
    Color(0xFFBA68C8), // 紫
    Color(0xFFFF6B6B), // 赤
    Color(0xFF90CAF9), // 薄青
    Color(0xFFE6EE9C), // 黄緑
    Color(0xFFFFAB91), // サーモン
    Color(0xFF263238), // ブラック (旧 黄色: 視認性が低かったため廃止)
    Color(0xFF6C63FF), // インディゴ
  ];

  _GroupBackgroundPainter({
    required this.groups,
    required this.nodes,
    this.colorOverrides = const {},
    this.fontSizeOverrides = const {},
    this.fontFamilyOverrides = const {},
    this.paddingOverrides = const {},
    this.isDark = true,
  });

  /// グループのバウンディングボックス情報を計算
  static List<_GroupBounds> computeBounds(
      Map<String, Set<String>> groups, Map<String, MindMapNode> nodes,
      [Map<String, int> colorOverrides = const {},
      Map<String, double> fontSizeOverrides = const {},
      Map<String, String> fontFamilyOverrides = const {},
      Map<String, List<double>> paddingOverrides = const {}]) {
    final result = <_GroupBounds>[];
    int colorIdx = 0;
    for (final entry in groups.entries) {
      final validIds = <String>{};
      for (final id in entry.value) {
        if (nodes.containsKey(id)) validIds.add(id);
      }
      if (validIds.isEmpty) {
        colorIdx++;
        continue;
      }

      double minX = double.infinity, minY = double.infinity;
      double maxX = double.negativeInfinity, maxY = double.negativeInfinity;
      for (final id in validIds) {
        final n = nodes[id]!;
        if (n.position.dx < minX) minX = n.position.dx;
        if (n.position.dy < minY) minY = n.position.dy;
        final right = n.position.dx + n.width;
        final bottom = n.position.dy + n.visualHeight;
        if (right > maxX) maxX = right;
        if (bottom > maxY) maxY = bottom;
      }
      // ユーザー指定の追加パディング
      final pad = paddingOverrides[entry.key] ?? const [0.0, 0.0, 0.0, 0.0];
      if (pad.length >= 4) {
        minX -= pad[0];
        minY -= pad[1];
        maxX += pad[2];
        maxY += pad[3];
      }
      final overrideIdx = colorOverrides[entry.key];
      final ci =
          (overrideIdx != null && overrideIdx >= 0) ? overrideIdx : colorIdx;
      final color = groupColors[ci % groupColors.length];
      colorIdx++;
      result.add(_GroupBounds(
        name: entry.key,
        nodeIds: validIds,
        minX: minX,
        minY: minY,
        maxX: maxX,
        maxY: maxY,
        color: color,
        fontSize: fontSizeOverrides[entry.key] ?? 13.0,
        fontFamily: fontFamilyOverrides[entry.key] ?? '',
      ));
    }
    return result;
  }

  @override
  void paint(Canvas canvas, Size size) {
    final bounds = computeBounds(groups, nodes, colorOverrides,
        fontSizeOverrides, fontFamilyOverrides, paddingOverrides);
    const pad = 14.0;
    const labelH = 26.0;

    for (final b in bounds) {
      final color = b.color;
      final hasName = b.name.isNotEmpty;
      // 長い名前の折り返し行数に応じて上部パディングを動的に計算
      double dynamicLabelH = labelH;
      if (hasName) {
        final boxW = ((b.maxX + pad) - (b.minX - pad)).clamp(80.0, 400.0);
        // 内部キーには ZWSP マーカーが含まれることがあるので、表示には
        // 取り除いた `groupDisplayName` を使う (= 裁断モードで分割した
        // グループも元と同じ名前で見える)。
        final displayLabel = MindMapProvider.groupDisplayName(b.name);
        final tp = TextPainter(
          text: TextSpan(
            text: displayLabel,
            style: TextStyle(
                fontSize: b.fontSize,
                fontWeight: FontWeight.w700,
                fontFamily: b.fontFamily.isNotEmpty ? b.fontFamily : null),
          ),
          textDirection: TextDirection.ltr,
          maxLines: 4,
        )..layout(maxWidth: boxW);
        dynamicLabelH = (tp.height + 8).clamp(labelH, labelH * 4);
      }
      final topPad = hasName ? (pad + dynamicLabelH) : pad;

      // ── 外枠（バウンディングボックス） ──
      final outerRect = RRect.fromLTRBR(
        b.minX - pad,
        b.minY - topPad,
        b.maxX + pad,
        b.maxY + pad,
        const Radius.circular(14),
      );
      final bgPaint = Paint()
        ..color = color.withValues(alpha: 0.06)
        ..style = PaintingStyle.fill;
      canvas.drawRRect(outerRect, bgPaint);
      final borderPaint = Paint()
        // ライトモードではアルファと幅を上げて枠線をはっきり見せる
        ..color = color.withValues(alpha: isDark ? 0.3 : 0.85)
        ..style = PaintingStyle.stroke
        ..strokeWidth = isDark ? 1.5 : 2.5;
      canvas.drawRRect(outerRect, borderPaint);

      // ── ラベル（名前がある場合のみ・上中央にテキストのみ、長い名前は折り返し）──
      if (hasName) {
        final boxW = (b.maxX + pad) - (b.minX - pad);
        final maxLabelW = boxW.clamp(80.0, 400.0);
        final boxCenterX = (b.minX - pad + b.maxX + pad) / 2;
        // 内部キーから ZWSP マーカーを除いた表示名を描画する。
        final displayLabel = MindMapProvider.groupDisplayName(b.name);
        final textPainter = TextPainter(
          text: TextSpan(
            text: displayLabel,
            style: TextStyle(
              color: color.withValues(alpha: 0.9),
              fontSize: b.fontSize,
              fontWeight: FontWeight.w700,
              fontFamily: b.fontFamily.isNotEmpty ? b.fontFamily : null,
              letterSpacing: 0.5,
            ),
          ),
          textDirection: TextDirection.ltr,
          maxLines: 4,
          // 折り返した複数行を中央揃えで描画する
          // (これがないと 2 行目以降が左寄せになる)
          textAlign: TextAlign.center,
        )..layout(maxWidth: maxLabelW);
        // ラベルエリアを実際のテキスト高さに合わせて中央揃え
        final actualLabelH = textPainter.height + 4;
        final topOffset = (dynamicLabelH - actualLabelH) / 2;
        textPainter.paint(
            canvas,
            Offset(
              boxCenterX - textPainter.width / 2,
              b.minY - topPad + topOffset.clamp(0.0, double.infinity),
            ));
      }
    }
  }

  double _measureTextWidth(String text, double fontSize) {
    final tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(fontSize: fontSize, fontWeight: FontWeight.w700),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    return tp.width;
  }

  @override
  bool shouldRepaint(_GroupBackgroundPainter old) =>
      old.groups != groups || old.nodes != nodes || old.isDark != isDark;
}

/// グループのバウンディングボックス情報
class _GroupBounds {
  final String name;
  final Set<String> nodeIds;
  final double minX, minY, maxX, maxY;
  final Color color;
  final double fontSize;
  final String fontFamily;
  const _GroupBounds({
    required this.name,
    required this.nodeIds,
    required this.minX,
    required this.minY,
    required this.maxX,
    required this.maxY,
    required this.color,
    this.fontSize = 13.0,
    this.fontFamily = '',
  });
}

/// ノードの上に描画：非メンバーノードにグループ外であることを示す枠を描く
class _GroupForegroundPainter extends CustomPainter {
  final Map<String, Set<String>> groups;
  final Map<String, MindMapNode> nodes;
  final Map<String, int> colorOverrides;

  _GroupForegroundPainter({
    required this.groups,
    required this.nodes,
    this.colorOverrides = const {},
  });

  @override
  void paint(Canvas canvas, Size size) {
    final bounds =
        _GroupBackgroundPainter.computeBounds(groups, nodes, colorOverrides);
    const pad = 14.0;

    for (final b in bounds) {
      final color = b.color;
      final boxRect =
          Rect.fromLTRB(b.minX - pad, b.minY - pad, b.maxX + pad, b.maxY + pad);

      for (final entry in nodes.entries) {
        if (b.nodeIds.contains(entry.key)) continue;
        final n = entry.value;
        final nodeRect = Rect.fromLTWH(
            n.position.dx, n.position.dy, n.width, n.visualHeight);
        if (!boxRect.overlaps(nodeRect)) continue;

        // ノード形状に合った外枠のみ（18 = NodeWidgetと同じ角丸）
        final nrr =
            RRect.fromRectAndRadius(nodeRect, const Radius.circular(18));
        final borderPaint = Paint()
          ..color = color.withValues(alpha: 0.8)
          ..style = PaintingStyle.stroke
          ..strokeWidth = 2.5;
        canvas.drawRRect(nrr, borderPaint);
      }
    }
  }

  @override
  bool shouldRepaint(_GroupForegroundPainter old) =>
      old.groups != groups || old.nodes != nodes;
}

class _MapBackgroundTemplateView extends StatelessWidget {
  final String templateId;
  final Offset scrollOffset;
  final int hueDegrees;
  final int saturationPercent;
  final int brightnessPercent;
  const _MapBackgroundTemplateView({
    required this.templateId,
    this.scrollOffset = Offset.zero,
    this.hueDegrees = 0,
    this.saturationPercent = 100,
    this.brightnessPercent = 100,
  });

  @override
  Widget build(BuildContext context) {
    Widget result = CustomPaint(
      painter: _MapBackgroundTemplatePainter(templateId, scrollOffset),
      child: const SizedBox.expand(),
    );
    final brightness = brightnessPercent.clamp(50, 150) / 100.0;
    if ((brightness - 1.0).abs() > 0.001) {
      result = ColorFiltered(
        colorFilter: ColorFilter.matrix(<double>[
          brightness, 0, 0, 0, 0,
          0, brightness, 0, 0, 0,
          0, 0, brightness, 0, 0,
          0, 0, 0, 1, 0,
        ]),
        child: result,
      );
    }
    final saturation = saturationPercent.clamp(0, 200) / 100.0;
    if ((saturation - 1.0).abs() > 0.001) {
      const red = 0.213;
      const green = 0.715;
      const blue = 0.072;
      final inverse = 1.0 - saturation;
      result = ColorFiltered(
        colorFilter: ColorFilter.matrix(<double>[
          inverse * red + saturation,
          inverse * green,
          inverse * blue,
          0,
          0,
          inverse * red,
          inverse * green + saturation,
          inverse * blue,
          0,
          0,
          inverse * red,
          inverse * green,
          inverse * blue + saturation,
          0,
          0,
          0,
          0,
          0,
          1,
          0,
        ]),
        child: result,
      );
    }
    final radians = hueDegrees.clamp(-180, 180) * math.pi / 180.0;
    if (radians.abs() > 0.001) {
      final cosine = math.cos(radians);
      final sine = math.sin(radians);
      result = ColorFiltered(
        colorFilter: ColorFilter.matrix(<double>[
          0.213 + cosine * 0.787 - sine * 0.213,
          0.715 - cosine * 0.715 - sine * 0.715,
          0.072 - cosine * 0.072 + sine * 0.928,
          0,
          0,
          0.213 - cosine * 0.213 + sine * 0.143,
          0.715 + cosine * 0.285 + sine * 0.140,
          0.072 - cosine * 0.072 - sine * 0.283,
          0,
          0,
          0.213 - cosine * 0.213 - sine * 0.787,
          0.715 - cosine * 0.715 + sine * 0.715,
          0.072 + cosine * 0.928 + sine * 0.072,
          0,
          0,
          0,
          0,
          0,
          1,
          0,
        ]),
        child: result,
      );
    }
    return result;
  }
}

/// ミニマップの描画 (= ユーザー要望: 全体のどこにいるかの縮図)。
/// ノードは小さな四角、 接続は細い線、 今見えている範囲は明るい枠で描く。
/// 説明書きからノードを指す小さな三角 (帯本体はウィジェット側で描く)。
class _CaptionTailPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final path = Path()
      ..moveTo(size.width / 2 - 5, 0)
      ..lineTo(size.width / 2 + 5, 0)
      ..lineTo(size.width / 2, size.height)
      ..close();
    canvas.drawPath(path, Paint()..color = const Color(0xFFFFF3C4));
    canvas.drawPath(
      path,
      Paint()
        ..color = const Color(0xFFE0B34A)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.2,
    );
  }

  @override
  bool shouldRepaint(_CaptionTailPainter old) => false;
}

class _MiniMapPainter extends CustomPainter {
  final Map<String, MindMapNode> nodes;
  final List<NodeConnection> connections;

  /// 映しているキャンバス上の範囲。
  final Rect world;
  final Rect viewport;

  /// world → 縮図 の倍率と、 中央寄せのためのずれ。
  final double scale;
  final Offset offset;

  const _MiniMapPainter({
    required this.nodes,
    required this.connections,
    required this.world,
    required this.viewport,
    required this.scale,
    required this.offset,
  });

  @override
  void paint(Canvas canvas, Size size) {
    if (size.isEmpty || world.width <= 0 || world.height <= 0) return;
    Offset p(Offset o) => Offset(
          (o.dx - world.left) * scale + offset.dx,
          (o.dy - world.top) * scale + offset.dy,
        );

    // 地の色
    canvas.drawRect(Offset.zero & size,
        Paint()..color = const Color(0xFF0A121A).withValues(alpha: 0.55));

    // 接続線 (薄く)
    if (connections.isNotEmpty) {
      final linePaint = Paint()
        ..color = const Color(0xFF6FC3E8).withValues(alpha: 0.28)
        ..strokeWidth = 0.6;
      for (final c in connections) {
        final a = nodes[c.fromId];
        final b = nodes[c.toId];
        if (a == null || b == null) continue;
        canvas.drawLine(
          p(Offset(a.position.dx + a.width / 2,
              a.position.dy + a.visualHeight / 2)),
          p(Offset(b.position.dx + b.width / 2,
              b.position.dy + b.visualHeight / 2)),
          linePaint,
        );
      }
    }

    // ノード (ノード色をそのまま小さく置く)
    for (final n in nodes.values) {
      final tl = p(n.position);
      final r = Rect.fromLTWH(
        tl.dx,
        tl.dy,
        math.max(2.0, n.width * scale),
        math.max(1.5, n.visualHeight * scale),
      );
      canvas.drawRRect(
        RRect.fromRectAndRadius(r, const Radius.circular(1.2)),
        Paint()..color = n.color.withValues(alpha: 0.92),
      );
    }

    // 今見えている範囲
    final vr = Rect.fromPoints(p(viewport.topLeft), p(viewport.bottomRight));
    canvas.drawRect(
        vr, Paint()..color = const Color(0xFF6FC3E8).withValues(alpha: 0.13));
    canvas.drawRect(
      vr,
      Paint()
        ..color = const Color(0xFF8FE1FF)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.4,
    );
  }

  @override
  bool shouldRepaint(_MiniMapPainter old) =>
      old.viewport != viewport ||
      old.world != world ||
      old.scale != scale ||
      old.offset != offset ||
      !identical(old.nodes, nodes) ||
      old.connections.length != connections.length;
}

class _MapBackgroundTemplatePainter extends CustomPainter {
  final String templateId;
  final Offset scrollOffset;
  const _MapBackgroundTemplatePainter(this.templateId, this.scrollOffset);

  Rect _rect(Size size) => Offset.zero & size;

  void _fillGradient(Canvas canvas, Size size, List<Color> colors,
      {Alignment begin = Alignment.topLeft,
      Alignment end = Alignment.bottomRight}) {
    canvas.drawRect(
      _rect(size),
      Paint()
        ..shader = LinearGradient(begin: begin, end: end, colors: colors)
            .createShader(_rect(size)),
    );
  }

  void _drawGlow(Canvas canvas, Offset center, double radius, Color color) {
    final bounds = Rect.fromCircle(center: center, radius: radius);
    canvas.drawCircle(
      center,
      radius,
      Paint()
        ..shader = RadialGradient(colors: [
          color,
          color.withValues(alpha: 0),
        ]).createShader(bounds),
    );
  }

  double _wrap(double value, double extent) {
    if (extent <= 0) return value;
    final wrapped = value % extent;
    return wrapped < 0 ? wrapped + extent : wrapped;
  }

  void _drawSparseStars(Canvas canvas, Size size,
      {required int count,
      required double parallax,
      Color tint = Colors.white}) {
    final span = size.width + 80;
    for (var i = 0; i < count; i++) {
      final baseX = size.width * ((i * 47 + i * i * 13) % 997) / 997;
      final x = _wrap(baseX - scrollOffset.dx * parallax + 40, span) - 40;
      final ySeed = ((i * 83 + i * i * 19 + 31) % 991) / 991;
      final y = size.height * (0.06 + ySeed * 0.66) -
          scrollOffset.dy * parallax * 0.08;
      final radius = i % 9 == 0 ? 1.45 : (i % 4 == 0 ? 0.95 : 0.55);
      final alpha = i % 9 == 0 ? 0.88 : (i % 4 == 0 ? 0.62 : 0.38);
      canvas.drawCircle(
          Offset(x, y), radius, Paint()..color = tint.withValues(alpha: alpha));
      if (i % 13 == 0) {
        final flare = Paint()
          ..color = tint.withValues(alpha: 0.22)
          ..strokeWidth = 0.7;
        canvas.drawLine(Offset(x - 3, y), Offset(x + 3, y), flare);
        canvas.drawLine(Offset(x, y - 3), Offset(x, y + 3), flare);
      }
    }
  }

  void _drawMountainLayer(Canvas canvas, Size size,
      {required double baseY,
      required double parallax,
      required Color color,
      double peakHeight = 0.22}) {
    final shift = _wrap(scrollOffset.dx * parallax, size.width * 0.7);
    final path = Path()..moveTo(-size.width - shift, size.height);
    for (var tile = -2; tile <= 3; tile++) {
      final left = tile * size.width * 0.7 - shift;
      path
        ..lineTo(left, size.height * baseY)
        ..lineTo(
            left + size.width * 0.20, size.height * (baseY - peakHeight * 0.55))
        ..lineTo(left + size.width * 0.36, size.height * (baseY - peakHeight))
        ..lineTo(
            left + size.width * 0.54, size.height * (baseY - peakHeight * 0.42))
        ..lineTo(left + size.width * 0.70, size.height * baseY);
    }
    path
      ..lineTo(size.width * 2, size.height)
      ..close();
    canvas.drawPath(path, Paint()..color = color);
  }

  @override
  void paint(Canvas canvas, Size size) {
    if (size.isEmpty) return;
    // パララックスで負座標にも描く (山並みなど) ため、 自分の領域外へ
    // 描画が漏れないようクリップする (= ユーザー要望: 画面分割時に右側の
    // 背景の一部が左側に進出してしまうバグの修正)。
    canvas.clipRect(Offset.zero & size);
    switch (templateId) {
      case 'blueprint':
        {
          // ブループリント (強化版): 青焼き紙の色ムラ + 図枠とコーナーマーク +
          //   ごく薄いコンパス作図線 + タイトルブロックで「本物の製図」 風に
          //   (= ユーザー要望: もっとリアルでお洒落に)。
          _fillGradient(canvas, size,
              const [Color(0xFF07203C), Color(0xFF11406C), Color(0xFF092A4C)]);
          // 青焼き特有のムラ (ぼかした大きな明暗)
          for (var b = 0; b < 6; b++) {
            canvas.drawCircle(
                Offset(size.width * _hash(b, 401), size.height * _hash(b, 402)),
                size.shortestSide * (0.22 + _hash(b, 403) * 0.25),
                Paint()
                  ..color = (b.isEven
                          ? const Color(0xFF1B5586)
                          : const Color(0xFF06182E))
                      .withValues(alpha: 0.16)
                  ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 60));
          }
          final minor = Paint()
            ..color = const Color(0xFF8BD8FF).withValues(alpha: 0.09)
            ..strokeWidth = 1;
          final major = Paint()
            ..color = const Color(0xFFB9E8FF).withValues(alpha: 0.20)
            ..strokeWidth = 1.3;
          for (var i = 0; i <= 20; i++) {
            final x = size.width * i / 20;
            canvas.drawLine(Offset(x, 0), Offset(x, size.height),
                i % 5 == 0 ? major : minor);
          }
          for (var i = 0; i <= 20; i++) {
            final y = size.height * i / 20;
            canvas.drawLine(Offset(0, y), Offset(size.width, y),
                i % 5 == 0 ? major : minor);
          }
          // コンパスの作図線 (円 + 中心十字) は削除した
          // (= ユーザー要望: 背景の円は要らない)。 方眼と図枠だけ残す。
          // 図枠 (二重線) + コーナーマーク
          final frame = Paint()
            ..color = const Color(0xFFDDF1FF).withValues(alpha: 0.40)
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1.6;
          final inner = Rect.fromLTWH(
              14, 14, size.width - 28, size.height - 28);
          canvas.drawRect(inner, frame);
          canvas.drawRect(
              inner.deflate(5),
              Paint()
                ..color = const Color(0xFFDDF1FF).withValues(alpha: 0.16)
                ..style = PaintingStyle.stroke
                ..strokeWidth = 1);
          for (final c in [
            inner.topLeft,
            inner.topRight,
            inner.bottomLeft,
            inner.bottomRight
          ]) {
            final dx = c.dx < size.width / 2 ? 1.0 : -1.0;
            final dy = c.dy < size.height / 2 ? 1.0 : -1.0;
            canvas.drawLine(c, c.translate(dx * 14, 0), frame);
            canvas.drawLine(c, c.translate(0, dy * 14), frame);
          }
          // 右下のタイトルブロック (図面の記入欄風の四角) は廃止
          //   (= ユーザー要望: 下の余計な四角は要らない)。
          // 白の微細スペックル (紙の繊維感)
          for (var i = 0; i < 130; i++) {
            canvas.drawCircle(
                Offset(size.width * _hash(i, 406), size.height * _hash(i, 407)),
                0.5,
                Paint()
                  ..color = Colors.white
                      .withValues(alpha: 0.02 + _hash(i, 408) * 0.04));
          }
          // 四隅のビネット
          canvas.drawRect(
              _rect(size),
              Paint()
                ..shader = RadialGradient(radius: 1.15, colors: [
                  Colors.transparent,
                  const Color(0xFF03101F).withValues(alpha: 0.42),
                ]).createShader(_rect(size)));
          return;
        }
      case 'paper':
        _fillGradient(
            canvas, size, const [Color(0xFFFFFCF2), Color(0xFFF1E8D2)]);
        final rule = Paint()
          ..color = const Color(0xFF7D9DB5).withValues(alpha: 0.26)
          ..strokeWidth = 1;
        for (var i = 1; i < 22; i++) {
          final y = size.height * i / 22;
          canvas.drawLine(Offset(0, y), Offset(size.width, y), rule);
        }
        canvas.drawLine(
          Offset(size.width * 0.12, 0),
          Offset(size.width * 0.12, size.height),
          Paint()
            ..color = const Color(0xFFD66C6C).withValues(alpha: 0.38)
            ..strokeWidth = 1.5,
        );
        return;
      case 'midnight':
        _fillGradient(canvas, size,
            const [Color(0xFF030817), Color(0xFF0C1833), Color(0xFF18233B)],
            begin: Alignment.topCenter, end: Alignment.bottomCenter);
        final moonX = _wrap(
                size.width * 0.78 - scrollOffset.dx * 0.018, size.width + 140) -
            70;
        final moon = Offset(moonX, size.height * 0.18);
        _drawGlow(
            canvas, moon, size.shortestSide * 0.20, const Color(0x3378A7FF));
        canvas.drawCircle(moon, size.shortestSide * 0.046,
            Paint()..color = const Color(0xFFE4ECFF));
        canvas.drawCircle(
            moon.translate(
                size.shortestSide * 0.018, -size.shortestSide * 0.010),
            size.shortestSide * 0.043,
            Paint()..color = const Color(0xFF08142B));
        _drawSparseStars(canvas, size, count: 34, parallax: 0.012);
        _drawMountainLayer(canvas, size,
            baseY: 0.83,
            parallax: 0.025,
            peakHeight: 0.17,
            color: const Color(0xFF17233A).withValues(alpha: 0.92));
        _drawMountainLayer(canvas, size,
            baseY: 0.94,
            parallax: 0.055,
            peakHeight: 0.25,
            color: const Color(0xFF080E1E));
        return;
      case 'nightSky':
        _fillGradient(canvas, size,
            const [Color(0xFF07152E), Color(0xFF183C61), Color(0xFF496B82)],
            begin: Alignment.topCenter, end: Alignment.bottomCenter);
        final moonX = _wrap(
                size.width * 0.22 - scrollOffset.dx * 0.02, size.width + 120) -
            60;
        _drawGlow(canvas, Offset(moonX, size.height * 0.20),
            size.shortestSide * 0.18, const Color(0x44B6D8FF));
        canvas.drawCircle(
            Offset(moonX, size.height * 0.20),
            size.shortestSide * 0.042,
            Paint()..color = const Color(0xFFF0F5FF));
        _drawSparseStars(canvas, size, count: 26, parallax: 0.016);
        _drawMountainLayer(canvas, size,
            baseY: 0.87,
            parallax: 0.035,
            peakHeight: 0.18,
            color: const Color(0xFF20394A));
        _drawMountainLayer(canvas, size,
            baseY: 0.97,
            parallax: 0.07,
            peakHeight: 0.20,
            color: const Color(0xFF10242B));
        return;
      case 'galaxy':
        _fillGradient(canvas, size,
            const [Color(0xFF050616), Color(0xFF171034), Color(0xFF07162A)]);
        final bandShift = scrollOffset.dx * 0.025;
        final band = Path()
          ..moveTo(-size.width * 0.25 - bandShift, size.height * 0.88)
          ..cubicTo(
              size.width * 0.18 - bandShift,
              size.height * 0.52,
              size.width * 0.58 - bandShift,
              size.height * 0.47,
              size.width * 1.25 - bandShift,
              size.height * 0.06);
        canvas.drawPath(
            band,
            Paint()
              ..color = const Color(0xFF8E67C7).withValues(alpha: 0.18)
              ..style = PaintingStyle.stroke
              ..strokeWidth = size.shortestSide * 0.23
              ..strokeCap = StrokeCap.round
              ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 28));
        _drawGlow(
            canvas,
            Offset(
                _wrap(size.width * 0.66 - scrollOffset.dx * 0.032,
                    size.width + 180),
                size.height * 0.38),
            size.shortestSide * 0.30,
            const Color(0x446F8EFF));
        _drawSparseStars(canvas, size,
            count: 48, parallax: 0.022, tint: const Color(0xFFE8E1FF));
        return;
      case 'rain':
        _fillGradient(canvas, size,
            const [Color(0xFF152533), Color(0xFF344D5A), Color(0xFF73878A)],
            begin: Alignment.topCenter, end: Alignment.bottomCenter);
        for (var i = 0; i < 46; i++) {
          final x = _wrap(
                  size.width * ((i * 61) % 101) / 100 - scrollOffset.dx * 0.05,
                  size.width + 50) -
              25;
          final y = size.height * ((i * 37 + 11) % 97) / 96;
          final length = 8.0 + (i % 5) * 2.5;
          canvas.drawLine(
              Offset(x, y),
              Offset(x - length * 0.28, y + length),
              Paint()
                ..color = const Color(0xFFB9E2F4)
                    .withValues(alpha: i % 3 == 0 ? 0.34 : 0.19)
                ..strokeWidth = i % 4 == 0 ? 1.2 : 0.75
                ..strokeCap = StrokeCap.round);
        }
        _drawMountainLayer(canvas, size,
            baseY: 0.94,
            parallax: 0.06,
            peakHeight: 0.14,
            color: const Color(0xFF263C42).withValues(alpha: 0.88));
        return;
      case 'nature':
        _fillGradient(canvas, size,
            const [Color(0xFF79B9D5), Color(0xFFB9D8C1), Color(0xFFE7D59D)],
            begin: Alignment.topCenter, end: Alignment.bottomCenter);
        final sunX = _wrap(
                size.width * 0.78 - scrollOffset.dx * 0.012, size.width + 160) -
            80;
        _drawGlow(canvas, Offset(sunX, size.height * 0.22),
            size.shortestSide * 0.22, const Color(0x66FFF0A8));
        canvas.drawCircle(
            Offset(sunX, size.height * 0.22),
            size.shortestSide * 0.045,
            Paint()..color = const Color(0xFFFFE7A3));
        _drawMountainLayer(canvas, size,
            baseY: 0.82,
            parallax: 0.025,
            peakHeight: 0.20,
            color: const Color(0xFF789B82).withValues(alpha: 0.72));
        _drawMountainLayer(canvas, size,
            baseY: 0.94,
            parallax: 0.06,
            peakHeight: 0.22,
            color: const Color(0xFF315F45));
        final treePaint = Paint()..color = const Color(0xFF173C2D);
        for (var i = 0; i < 10; i++) {
          final x = _wrap(i * size.width * 0.16 - scrollOffset.dx * 0.10,
                  size.width + 100) -
              50;
          final h = size.height * (0.08 + (i % 3) * 0.018);
          final base = size.height;
          canvas.drawRect(
              Rect.fromLTWH(x - 1.5, base - h * 0.45, 3, h * 0.45), treePaint);
          final crown = Path()
            ..moveTo(x, base - h)
            ..lineTo(x - h * 0.24, base - h * 0.28)
            ..lineTo(x + h * 0.24, base - h * 0.28)
            ..close();
          canvas.drawPath(crown, treePaint);
        }
        return;
      case 'sage':
        {
          // セージ (強化版): 淡いグラデの紙地に、 四隅から差し込むユーカリの
          //   枝葉 + 木漏れ日 + 紙の質感 (= ユーザー要望: もっとリアルで
          //   お洒落に)。 中央は作業の邪魔をしない無地のまま。
          _fillGradient(canvas, size,
              const [Color(0xFFF2F6EE), Color(0xFFD8E4D2), Color(0xFFAEC5AC)],
              begin: Alignment.topCenter, end: Alignment.bottomCenter);
          // 木漏れ日 (ぼかした光)
          _drawGlow(canvas, Offset(size.width * 0.24, size.height * 0.10),
              size.shortestSide * 0.34, const Color(0x33FFF9E0));
          _drawGlow(canvas, Offset(size.width * 0.86, size.height * 0.80),
              size.shortestSide * 0.28, const Color(0x22FFF4D0));
          // ユーカリの枝 1 本を描くヘルパー。
          void branch(Offset root, double angle, double len, Color color,
              double alpha) {
            final dir = Offset(math.cos(angle), math.sin(angle));
            final normal = Offset(-dir.dy, dir.dx);
            final stem = Path()..moveTo(root.dx, root.dy);
            const steps = 8;
            var last = root;
            for (var i = 1; i <= steps; i++) {
              final t = i / steps;
              final bend = math.sin(t * math.pi * 0.9) * len * 0.10;
              final p = root + dir * (len * t) + normal * bend;
              stem.quadraticBezierTo(
                  (last.dx + p.dx) / 2, (last.dy + p.dy) / 2, p.dx, p.dy);
              last = p;
            }
            canvas.drawPath(
                stem,
                Paint()
                  ..color = color.withValues(alpha: alpha)
                  ..style = PaintingStyle.stroke
                  ..strokeWidth = 2.0
                  ..strokeCap = StrokeCap.round);
            // 丸葉を茎に沿って左右交互に付ける
            for (var i = 2; i <= steps * 2 - 1; i++) {
              final t = i / (steps * 2);
              final bend = math.sin(t * math.pi * 0.9) * len * 0.10;
              final p = root + dir * (len * t) + normal * bend;
              final side = i.isEven ? 1.0 : -1.0;
              final leafC = p + normal * side * (len * 0.035);
              final r = len * (0.052 - t * 0.020);
              canvas.drawCircle(
                  leafC,
                  r,
                  Paint()
                    ..color = color.withValues(
                        alpha: alpha * (0.85 - t * 0.25)));
            }
            // 先端の葉
            canvas.drawCircle(last, len * 0.030,
                Paint()..color = color.withValues(alpha: alpha));
          }

          final u = size.shortestSide;
          // 左上から
          branch(Offset(-u * 0.04, size.height * 0.05), 0.55, u * 0.52,
              const Color(0xFF4E7A5E), 0.34);
          branch(Offset(size.width * 0.05, -u * 0.05), 1.05, u * 0.42,
              const Color(0xFF6E947B), 0.30);
          // 右下から
          branch(Offset(size.width + u * 0.03, size.height * 0.96), math.pi - 0.6,
              u * 0.55, const Color(0xFF3F6A50), 0.32);
          branch(Offset(size.width * 0.94, size.height + u * 0.04), -2.05,
              u * 0.44, const Color(0xFF5B8367), 0.28);
          // 右上に小さめ
          branch(Offset(size.width + u * 0.02, size.height * 0.06), math.pi - 2.6,
              u * 0.34, const Color(0xFF77997F), 0.22);
          // 散り葉
          for (var i = 0; i < 14; i++) {
            final c = Offset(size.width * _hash(i, 411),
                size.height * _hash(i, 412));
            canvas.drawCircle(
                c,
                2.2 + _hash(i, 413) * 2.6,
                Paint()
                  ..color = const Color(0xFF57805F)
                      .withValues(alpha: 0.05 + _hash(i, 414) * 0.07));
          }
          // 紙の繊維感 (ごく薄い点々)
          for (var i = 0; i < 110; i++) {
            canvas.drawCircle(
                Offset(size.width * _hash(i, 415), size.height * _hash(i, 416)),
                0.5,
                Paint()
                  ..color = const Color(0xFF31513B)
                      .withValues(alpha: 0.015 + _hash(i, 417) * 0.03));
          }
          // ビネット
          canvas.drawRect(
              _rect(size),
              Paint()
                ..shader = RadialGradient(radius: 1.2, colors: [
                  Colors.transparent,
                  const Color(0xFF44614B).withValues(alpha: 0.16),
                ]).createShader(_rect(size)));
          return;
        }
      case 'sunset':
        {
          // サンセット (強化版): 海に沈む夕日。 下から照らされた雲 + 水平線 +
          //   海面の光の道 + 遠い島影 + 渡り鳥 (= ユーザー要望: もっとリアルで
          //   お洒落に)。
          final horizonY = size.height * 0.62;
          // 空
          final sky = Rect.fromLTRB(0, 0, size.width, horizonY);
          canvas.drawRect(
              sky,
              Paint()
                ..shader = const LinearGradient(
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                    colors: [
                      Color(0xFF5A4A8E),
                      Color(0xFFC96A8B),
                      Color(0xFFF89A6B),
                      Color(0xFFFFD98A),
                    ]).createShader(sky));
          // 太陽 (水平線ぎわ)
          final sunX = _wrap(
                  size.width * 0.56 - scrollOffset.dx * 0.012,
                  size.width + 200) -
              100;
          final sun = Offset(sunX, horizonY - size.shortestSide * 0.035);
          _drawGlow(canvas, sun, size.shortestSide * 0.30,
              const Color(0x66FFE9B0));
          canvas.drawCircle(sun, size.shortestSide * 0.055,
              Paint()..color = const Color(0xFFFFE9B8));
          canvas.drawCircle(sun, size.shortestSide * 0.055,
              Paint()
                ..color = const Color(0xFFFFF6DC).withValues(alpha: 0.8)
                ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6));
          // 下から照らされた層状の雲
          for (var i = 0; i < 7; i++) {
            final cy = size.height * (0.10 + _hash(i, 421) * 0.38);
            final cx = _wrap(
                    size.width * _hash(i, 422) -
                        scrollOffset.dx * (0.02 + _hash(i, 423) * 0.02),
                    size.width + 260) -
                130;
            final w = size.width * (0.16 + _hash(i, 424) * 0.22);
            final h = size.height * (0.012 + _hash(i, 425) * 0.02);
            final lit = cy > size.height * 0.30;
            canvas.drawOval(
                Rect.fromCenter(center: Offset(cx, cy), width: w, height: h),
                Paint()
                  ..color = (lit
                          ? const Color(0xFFFFC9A0)
                          : const Color(0xFF8A6AA8))
                      .withValues(alpha: 0.22 + _hash(i, 426) * 0.18)
                  ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 7));
          }
          // 海
          final sea = Rect.fromLTRB(0, horizonY, size.width, size.height);
          canvas.drawRect(
              sea,
              Paint()
                ..shader = const LinearGradient(
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                    colors: [
                      Color(0xFFE08A6B),
                      Color(0xFF9A5578),
                      Color(0xFF4A3B6E),
                    ]).createShader(sea));
          // 水平線
          canvas.drawLine(
              Offset(0, horizonY),
              Offset(size.width, horizonY),
              Paint()
                ..color = const Color(0xFFFFE2A8).withValues(alpha: 0.55)
                ..strokeWidth = 1.2);
          // 遠い島影
          _drawMountainLayer(canvas, size,
              baseY: horizonY / size.height + 0.001,
              parallax: 0.015,
              peakHeight: 0.045,
              color: const Color(0xFF5A3E63).withValues(alpha: 0.85));
          // 海面の光の道 (太陽の真下に、 下へ行くほど広く・まばらに)
          canvas.save();
          canvas.clipRect(sea);
          for (var i = 0; i < 26; i++) {
            final t = i / 26.0;
            final y = horizonY + (size.height - horizonY) * t * t;
            final halfW =
                size.shortestSide * (0.02 + t * 0.10) * (0.6 + _hash(i, 427));
            final cx2 = sun.dx + (_hash(i, 428) - 0.5) * halfW * 0.9;
            canvas.drawLine(
                Offset(cx2 - halfW / 2, y),
                Offset(cx2 + halfW / 2, y),
                Paint()
                  ..color = const Color(0xFFFFD98A)
                      .withValues(alpha: (0.34 - t * 0.26).clamp(0.04, 0.34))
                  ..strokeWidth = 1.4 + t * 1.6
                  ..strokeCap = StrokeCap.round);
          }
          // 手前のさざ波 (ごく薄い横線)
          for (var i = 0; i < 8; i++) {
            final y = horizonY + (size.height - horizonY) * (0.25 + i * 0.09);
            canvas.drawLine(
                Offset(size.width * _hash(i, 429) * 0.5, y),
                Offset(size.width * (0.5 + _hash(i, 430) * 0.5), y),
                Paint()
                  ..color = Colors.white.withValues(alpha: 0.05)
                  ..strokeWidth = 1);
          }
          canvas.restore();
          // 渡り鳥 (小さな V 字)
          for (var i = 0; i < 5; i++) {
            final bx = size.width * (0.14 + _hash(i, 431) * 0.5);
            final by = size.height * (0.14 + _hash(i, 432) * 0.22);
            final s2 = 4.0 + _hash(i, 433) * 3.5;
            final bird = Paint()
              ..color = const Color(0xFF3A2C50).withValues(alpha: 0.65)
              ..style = PaintingStyle.stroke
              ..strokeWidth = 1.2
              ..strokeCap = StrokeCap.round;
            final path = Path()
              ..moveTo(bx - s2, by)
              ..quadraticBezierTo(bx - s2 * 0.4, by - s2 * 0.7, bx, by)
              ..quadraticBezierTo(bx + s2 * 0.4, by - s2 * 0.7, bx + s2, by);
            canvas.drawPath(path, bird);
          }
          // ビネット
          canvas.drawRect(
              _rect(size),
              Paint()
                ..shader = RadialGradient(radius: 1.2, colors: [
                  Colors.transparent,
                  const Color(0xFF2A1E45).withValues(alpha: 0.30),
                ]).createShader(_rect(size)));
          return;
        }
      // ── よりリアル寄りの新テンプレート (= ユーザー要望) ──
      case 'wood':
        {
          // 木目 (強化版): 板ごとの色ムラ + 面取りハイライト付きの継ぎ目 +
          //   うねる木目 + 年輪入りの節 + 上からの艶とビネット
          //   (= ユーザー要望: もっとおしゃれに)。
          _fillGradient(canvas, size,
              const [Color(0xFF9A6B3F), Color(0xFF7C4E27), Color(0xFF8A5A33)],
              begin: Alignment.topCenter, end: Alignment.bottomCenter);
          // ── 板の継ぎ目 (横線 + 縦線) は廃止 (= ユーザー要望: 木目
          //    テンプレートで方眼は使わないで)。 継ぎ目のない一枚板として、
          //    ゆるやかな色ムラ + 流れる木目 + 節だけで見せる。 ──
          // 大きな色ムラ (帯ではなく、 ぼかした楕円で不規則に)
          for (var b = 0; b < 7; b++) {
            final c = Offset(size.width * _hash(b, 101),
                size.height * _hash(b, 108));
            canvas.drawOval(
                Rect.fromCenter(
                    center: c,
                    width: size.width * (0.35 + _hash(b, 109) * 0.4),
                    height: size.height * (0.12 + _hash(b, 110) * 0.16)),
                Paint()
                  ..color = Color.lerp(const Color(0xFF6E441F),
                          const Color(0xFF9C6C3E), _hash(b, 111))!
                      .withValues(alpha: 0.28)
                  ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 26));
          }
          // 木目 (画面を横切る長い流れ。 太さと濃さをばらつかせる)
          for (var i = 0; i < 26; i++) {
            final y0 = size.height * (i + 0.5) / 26 + _hash(i, 102) * 10 - 5;
            final grain = Path()..moveTo(-10, y0);
            for (var x = 0.0; x <= size.width + 20; x += size.width / 12) {
              final wob = math.sin(x / size.width * math.pi *
                          (1.2 + _hash(i, 103) * 1.6) +
                      i * 1.7) *
                  (2.5 + _hash(i, 104) * 5.0);
              grain.lineTo(x, y0 + wob);
            }
            final strong = i % 4 == 0;
            canvas.drawPath(
                grain,
                Paint()
                  ..color = const Color(0xFF4C2C10)
                      .withValues(alpha: strong ? 0.26 : 0.13)
                  ..style = PaintingStyle.stroke
                  ..strokeWidth = strong ? 1.5 : 0.8);
          }
          // 節 (年輪 + 中心の芯) を 3 箇所
          for (var p = 0; p < 3; p++) {
            final c = Offset(size.width * (0.18 + _hash(p, 106) * 0.64),
                size.height * (0.15 + _hash(p, 107) * 0.7));
            for (var r = 4; r >= 0; r--) {
              canvas.drawOval(
                  Rect.fromCenter(
                      center: c, width: 7.0 + r * 7.0, height: 4.5 + r * 4.4),
                  Paint()
                    ..color = const Color(0xFF3F2410)
                        .withValues(alpha: 0.10 + (4 - r) * 0.055)
                    ..style = PaintingStyle.stroke
                    ..strokeWidth = 1.1);
            }
            canvas.drawOval(
                Rect.fromCenter(center: c, width: 5.5, height: 3.6),
                Paint()
                  ..color = const Color(0xFF2E1A0A).withValues(alpha: 0.5));
          }
          // 上からの艶
          final sheen = Rect.fromLTWH(0, 0, size.width, size.height * 0.25);
          canvas.drawRect(
              sheen,
              Paint()
                ..shader = LinearGradient(
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                    colors: [
                      Colors.white.withValues(alpha: 0.10),
                      Colors.white.withValues(alpha: 0),
                    ]).createShader(sheen));
          // 四隅のビネット
          canvas.drawRect(
              _rect(size),
              Paint()
                ..shader = RadialGradient(radius: 1.1, colors: [
                  Colors.transparent,
                  const Color(0xFF2A1708).withValues(alpha: 0.35),
                ]).createShader(_rect(size)));
          return;
        }
      case 'chalkboard':
        {
          // 黒板 (強化版): 木枠 + 深緑ボード + チョーク粉 + 消し跡 +
          //   手描き風の落書き + チョーク受けの棚 (= ユーザー要望: もっと
          //   おしゃれに)。
          const frameW = 14.0;
          // 木枠
          canvas.drawRect(_rect(size), Paint()..color = const Color(0xFF6B4A2B));
          canvas.drawRect(Rect.fromLTWH(0, 0, size.width, 3),
              Paint()..color = const Color(0xFF8A6740).withValues(alpha: 0.8));
          for (var i = 0; i < 14; i++) {
            final y = size.height * _hash(i, 141);
            canvas.drawLine(
                Offset(0, y),
                Offset(size.width, y),
                Paint()
                  ..color = const Color(0xFF503318).withValues(alpha: 0.25)
                  ..strokeWidth = 0.8);
          }
          // ボード面 (内側の影 + 深緑グラデ)
          final board = Rect.fromLTWH(frameW, frameW, size.width - frameW * 2,
              size.height - frameW * 2);
          canvas.drawRect(board.inflate(2),
              Paint()..color = const Color(0xFF120D06).withValues(alpha: 0.6));
          canvas.drawRect(
              board,
              Paint()
                ..shader = const LinearGradient(
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                    colors: [
                      Color(0xFF2A4437),
                      Color(0xFF1B2E24),
                      Color(0xFF223829),
                    ]).createShader(board));
          canvas.save();
          canvas.clipRect(board);
          // チョーク粉のムラ
          for (var i = 0; i < 260; i++) {
            final x = board.left + board.width * _hash(i, 11);
            final y = board.top + board.height * _hash(i, 12);
            canvas.drawCircle(
                Offset(x, y),
                0.5 + _hash(i, 13) * 0.9,
                Paint()
                  ..color = Colors.white
                      .withValues(alpha: 0.02 + _hash(i, 14) * 0.05));
          }
          // 消し跡
          for (var k = 0; k < 4; k++) {
            final cx = board.left + board.width * (0.1 + _hash(k, 21) * 0.8);
            final cy = board.top + board.height * (0.15 + _hash(k, 22) * 0.7);
            canvas.save();
            canvas.translate(cx, cy);
            canvas.rotate((_hash(k, 23) - 0.5) * 0.9);
            canvas.drawOval(
                Rect.fromCenter(
                    center: Offset.zero,
                    width: board.width * (0.16 + _hash(k, 24) * 0.12),
                    height: board.height * 0.06),
                Paint()
                  ..color = Colors.white.withValues(alpha: 0.05)
                  ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 8));
            canvas.restore();
          }
          // ── 落書き (星 / 惑星 / 波線 / ハート) は廃止
          //    (= ユーザー要望: 文様が作業の邪魔になる)。 板面は書き込みの
          //    邪魔をしない、 ごく薄いチョーク粉と拭き跡だけにする。 ──
          // 上からの淡い照明 (無地でも安っぽく見えないように)
          canvas.drawRect(
              board,
              Paint()
                ..shader = LinearGradient(
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                    colors: [
                      Colors.white.withValues(alpha: 0.05),
                      Colors.white.withValues(alpha: 0),
                    ]).createShader(board));
          canvas.restore();
          // チョーク受けの棚 + チョーク 2 本 + 黒板消し
          final trayRect = Rect.fromLTWH(frameW + 6,
              size.height - frameW - 3, size.width * 0.45, 7);
          canvas.drawRRect(
              RRect.fromRectAndRadius(trayRect, const Radius.circular(2)),
              Paint()..color = const Color(0xFF54371C));
          canvas.drawRRect(
              RRect.fromRectAndRadius(
                  Rect.fromLTWH(
                      trayRect.left + 14, trayRect.top - 4, 26, 4.5),
                  const Radius.circular(2)),
              Paint()..color = const Color(0xFFF2F2EA));
          canvas.drawRRect(
              RRect.fromRectAndRadius(
                  Rect.fromLTWH(
                      trayRect.left + 52, trayRect.top - 4, 22, 4.5),
                  const Radius.circular(2)),
              Paint()..color = const Color(0xFFF6E9A8));
          final er = Rect.fromLTWH(trayRect.left + 90, trayRect.top - 8, 34, 9);
          canvas.drawRRect(
              RRect.fromRectAndRadius(er, const Radius.circular(2)),
              Paint()..color = const Color(0xFF7A4A52));
          canvas.drawRect(Rect.fromLTWH(er.left, er.bottom - 3, er.width, 3),
              Paint()..color = const Color(0xFFDDD5C8));
          return;
        }
      case 'fireworks':
        {
          // 花火 (落ち着き版 = ユーザー要望: もっと作業がしやすい、 気が
          //   散らないテンプレートに)。 遠景の花火を静かに眺める夜。
          //   ・大きな輝きや白い芯を廃止し、 淡い光の玉だけにする
          //   ・光条は短く低コントラスト、 打ち上げの尾と街の窓明かりは廃止
          //   ・画面中央〜下は無地の夜空にして、 ノードの視認性を優先
          _fillGradient(
              canvas,
              size,
              const [
                Color(0xFF080B1E),
                Color(0xFF101634),
                Color(0xFF141B3B),
                Color(0xFF0A0E24),
              ],
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter);
          _drawSparseStars(canvas, size, count: 34, parallax: 0.04);
          // 遠くの花火 (淡い光の玉 + 短く細い光条)
          void softBurst(Offset c, double r, Color col) {
            _drawGlow(canvas, c, r * 1.6, col.withValues(alpha: 0.10));
            for (var i = 0; i < 18; i++) {
              final a = i * 2 * math.pi / 18;
              final dir = Offset(math.cos(a), math.sin(a));
              canvas.drawLine(
                  c + dir * (r * 0.35),
                  c + dir * r,
                  Paint()
                    ..color = col.withValues(alpha: 0.22)
                    ..strokeWidth = 1.0
                    ..strokeCap = StrokeCap.round);
              canvas.drawCircle(
                  c + dir * r, 1.1, Paint()..color = col.withValues(alpha: 0.3));
            }
          }

          final u = size.shortestSide;
          softBurst(Offset(size.width * 0.22, size.height * 0.18), u * 0.10,
              const Color(0xFFFFD9A0));
          softBurst(Offset(size.width * 0.72, size.height * 0.13), u * 0.08,
              const Color(0xFF9FD8E8));
          softBurst(Offset(size.width * 0.87, size.height * 0.27), u * 0.06,
              const Color(0xFFE0AFC6));
          // 静かな水面 (下端のみ、 映り込みは細く淡い横線だけ)
          final water =
              Rect.fromLTRB(0, size.height * 0.88, size.width, size.height);
          canvas.drawRect(
              water,
              Paint()
                ..shader = const LinearGradient(
                        begin: Alignment.topCenter,
                        end: Alignment.bottomCenter,
                        colors: [Color(0xFF0A0F26), Color(0xFF070A18)])
                    .createShader(water));
          canvas.save();
          canvas.clipRect(water);
          for (var i = 0; i < 5; i++) {
            final y = water.top + 6 + i * (water.height / 6);
            canvas.drawLine(
                Offset(size.width * 0.18, y),
                Offset(size.width * 0.30, y),
                Paint()
                  ..color =
                      const Color(0xFFFFD9A0).withValues(alpha: 0.10 - i * 0.015)
                  ..strokeWidth = 1.6
                  ..strokeCap = StrokeCap.round);
            canvas.drawLine(
                Offset(size.width * 0.68, y),
                Offset(size.width * 0.78, y),
                Paint()
                  ..color =
                      const Color(0xFF9FD8E8).withValues(alpha: 0.09 - i * 0.014)
                  ..strokeWidth = 1.6
                  ..strokeCap = StrokeCap.round);
          }
          canvas.restore();
          // 対岸の街 (輪郭だけの低いシルエット。 窓明かりは出さない)
          final town = Path()..moveTo(0, size.height * 0.885);
          var tx = 0.0;
          var ti = 0;
          while (tx < size.width) {
            final w = size.width * (0.06 + _hash(ti, 306) * 0.05);
            final h = size.height * (0.012 + _hash(ti, 307) * 0.02);
            town
              ..lineTo(tx, size.height * 0.885 - h)
              ..lineTo(tx + w, size.height * 0.885 - h)
              ..lineTo(tx + w, size.height * 0.885);
            tx += w;
            ti++;
          }
          town
            ..lineTo(size.width, size.height * 0.90)
            ..lineTo(0, size.height * 0.90)
            ..close();
          canvas.drawPath(town, Paint()..color = const Color(0xFF060814));
          return;
        }
      case 'castle':
        {
          // お城 (= ユーザー要望): 夕暮れ〜藍色の空 + 満月 + 丘の上の
          //   天守閣 (層塔型) + 石垣 + 桜並木のシルエット。
          _fillGradient(
              canvas,
              size,
              const [
                Color(0xFF1B2A5B),
                Color(0xFF3C4C86),
                Color(0xFF8A6B8E),
                Color(0xFFD9906B),
              ],
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter);
          _drawSparseStars(canvas, size, count: 40, parallax: 0.04);
          // 月
          final moon = Offset(size.width * 0.78, size.height * 0.18);
          _drawGlow(canvas, moon, size.shortestSide * 0.22,
              const Color(0x55FFF3C4));
          canvas.drawCircle(moon, size.shortestSide * 0.055,
              Paint()..color = const Color(0xFFFFF6D5));
          // 遠景の山
          _drawMountainLayer(canvas, size,
              baseY: 0.70,
              parallax: 0.02,
              color: const Color(0xFF2A2F53).withValues(alpha: 0.85),
              peakHeight: 0.16);
          // 丘 (城の土台)
          final hill = Path()
            ..moveTo(0, size.height)
            ..lineTo(0, size.height * 0.86)
            ..quadraticBezierTo(size.width * 0.5, size.height * 0.72,
                size.width, size.height * 0.88)
            ..lineTo(size.width, size.height)
            ..close();
          canvas.drawPath(hill, Paint()..color = const Color(0xFF1E2B22));
          // ── 天守閣 ──
          final baseY = size.height * 0.795;
          final cx = size.width * 0.5;
          final unit = size.shortestSide * 0.052;
          final wall = Paint()..color = const Color(0xFFF3EDE2);
          final roof = Paint()..color = const Color(0xFF2E3A46);
          final line = Paint()
            ..color = const Color(0xFF7C8794).withValues(alpha: 0.7)
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1;
          // 石垣 (下広がりの台形)
          final stone = Path()
            ..moveTo(cx - unit * 3.2, baseY)
            ..lineTo(cx + unit * 3.2, baseY)
            ..lineTo(cx + unit * 4.2, baseY + unit * 2.2)
            ..lineTo(cx - unit * 4.2, baseY + unit * 2.2)
            ..close();
          canvas.drawPath(stone, Paint()..color = const Color(0xFF6E6A5F));
          canvas.drawPath(stone, line);
          for (var i = 1; i < 4; i++) {
            final y = baseY + unit * 2.2 * i / 4;
            final t = i / 4;
            canvas.drawLine(
                Offset(cx - (unit * 3.2 + unit * t), y),
                Offset(cx + (unit * 3.2 + unit * t), y),
                Paint()
                  ..color = const Color(0xFF4E4A42).withValues(alpha: 0.5)
                  ..strokeWidth = 1);
          }
          // 層を下から上へ 4 層
          var y = baseY;
          for (var lv = 0; lv < 4; lv++) {
            final w = unit * (3.0 - lv * 0.55);
            final h = unit * (0.95 - lv * 0.06);
            final body = Rect.fromLTRB(cx - w, y - h, cx + w, y);
            canvas.drawRect(body, wall);
            canvas.drawRect(body, line);
            // 窓 (格子)
            final winY = body.top + h * 0.35;
            for (var i = -2; i <= 2; i++) {
              if (lv == 3 && i.abs() == 2) continue;
              canvas.drawRect(
                  Rect.fromCenter(
                      center: Offset(cx + i * w * 0.42, winY),
                      width: unit * 0.36,
                      height: unit * 0.3),
                  Paint()..color = const Color(0xFF2C3540));
            }
            // 屋根 (反り上がった入母屋風)
            final rw = w + unit * (0.75 - lv * 0.08);
            final rh = unit * (0.62 - lv * 0.03);
            final r = Path()
              ..moveTo(cx - rw, y - h)
              ..quadraticBezierTo(
                  cx - rw * 0.55, y - h - rh * 0.75, cx, y - h - rh)
              ..quadraticBezierTo(
                  cx + rw * 0.55, y - h - rh * 0.75, cx + rw, y - h)
              ..quadraticBezierTo(cx + rw * 0.5, y - h + unit * 0.16,
                  cx + w * 0.9, y - h + unit * 0.06)
              ..lineTo(cx - w * 0.9, y - h + unit * 0.06)
              ..quadraticBezierTo(
                  cx - rw * 0.5, y - h + unit * 0.16, cx - rw, y - h)
              ..close();
            canvas.drawPath(r, roof);
            canvas.drawPath(
                r,
                Paint()
                  ..color = const Color(0xFF8FA0AE).withValues(alpha: 0.55)
                  ..style = PaintingStyle.stroke
                  ..strokeWidth = 1);
            y -= h + rh * 0.72;
          }
          // 金の鯱 (最上層の棟の両端)
          for (final sx in [cx - unit * 0.75, cx + unit * 0.75]) {
            final p = Path()
              ..moveTo(sx, y + unit * 0.1)
              ..quadraticBezierTo(
                  sx + unit * 0.12, y - unit * 0.16, sx, y - unit * 0.34)
              ..quadraticBezierTo(
                  sx - unit * 0.12, y - unit * 0.16, sx, y + unit * 0.1)
              ..close();
            canvas.drawPath(p, Paint()..color = const Color(0xFFE7C04B));
          }
          // 桜並木のシルエット (手前左右)
          void sakuraTree(double bx, double by, double s) {
            canvas.drawLine(
                Offset(bx, by),
                Offset(bx - s * 0.12, by - s * 0.6),
                Paint()
                  ..color = const Color(0xFF2B1B22)
                  ..strokeWidth = s * 0.09
                  ..strokeCap = StrokeCap.round);
            for (var i = 0; i < 7; i++) {
              final a = -math.pi * (0.15 + i * 0.11);
              final c = Offset(bx - s * 0.12, by - s * 0.62) +
                  Offset(math.cos(a), math.sin(a)) * s * 0.28;
              canvas.drawCircle(
                  c,
                  s * (0.18 + _hash(i, 311) * 0.08),
                  Paint()
                    ..color = const Color(0xFFE9A7BE)
                        .withValues(alpha: 0.55 + _hash(i, 312) * 0.25));
            }
          }

          sakuraTree(size.width * 0.10, size.height * 0.99,
              size.shortestSide * 0.30);
          sakuraTree(size.width * 0.92, size.height * 1.02,
              size.shortestSide * 0.34);
          // 舞い散る花びら
          for (var i = 0; i < 26; i++) {
            final x = size.width * _hash(i, 313);
            final yy = size.height * (0.35 + _hash(i, 314) * 0.6);
            canvas.save();
            canvas.translate(x, yy);
            canvas.rotate(_hash(i, 315) * math.pi);
            canvas.drawOval(
                Rect.fromCenter(center: Offset.zero, width: 5.5, height: 3.0),
                Paint()
                  ..color = const Color(0xFFF6C6D6)
                      .withValues(alpha: 0.35 + _hash(i, 316) * 0.35));
            canvas.restore();
          }
