            final ray = Path()
              ..moveTo(topX - size.width * 0.015, 0)
              ..lineTo(topX + size.width * 0.03, 0)
              ..lineTo(topX + size.width * (0.12 + _hash(k, 32) * 0.06),
                  size.height * 0.92)
              ..lineTo(topX - size.width * 0.08, size.height * 0.92)
              ..close();
            canvas.drawPath(
                ray,
                Paint()
                  ..color = const Color(0xFFBFF2FF)
                      .withValues(alpha: 0.04 + _hash(k, 33) * 0.05)
                  ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 12));
