            for (var x = 0.0; x <= size.width; x += size.width / 7) {
              wave.quadraticBezierTo(
                  x + size.width / 14,
                  y + math.sin(i * 1.7 + x / size.width * 6.28) * 5 - 5,
                  x + size.width / 7,
