              ..moveTo(-s * 0.3, -s * 0.5)
              ..quadraticBezierTo(0, -s * 1.0, s * 0.45, -s * 0.5)
              ..close();
            canvas.drawPath(
                fin, Paint()..color = accent.withValues(alpha: 0.8));
            canvas.drawCircle(Offset(s * 0.55, -s * 0.12), s * 0.11,
                Paint()..color = Colors.white.withValues(alpha: 0.9));
