          // 手前のカラフルな熱帯魚たち (クマノミ / タン / ピンク / ミント /
          // 紫 / 珊瑚色... 大きさも向きもバラバラ)
          const tropicalCols = [
            [Color(0xFFFF8A3C), Color(0xFFFFFFFF)], // クマノミ (橙 + 白帯)
            [Color(0xFFFFD54F), Color(0xFF37474F)], // 黄タン
            [Color(0xFF4FC3F7), Color(0xFF1A237E)], // 青タン
            [Color(0xFFF06292), Color(0xFFFFF3E0)], // ピンク
            [Color(0xFF80CBC4), Color(0xFF00695C)], // ミント
            [Color(0xFFB39DDB), Color(0xFF4527A0)], // 紫
            [Color(0xFFFF7043), Color(0xFFFFE0B2)], // 珊瑚色
          ];
          for (var i = 0; i < 9; i++) {
            final col = tropicalCols[i % tropicalCols.length];
            tropical(
