            final cy = size.height * (0.16 + _hash(j, 72) * 0.10);
            final r = size.shortestSide * (0.026 + _hash(j, 73) * 0.018);
            _drawGlow(
                canvas, Offset(cx, cy), r * 2.8, const Color(0x2EBFE9FF));
            final bell = Path()
              ..moveTo(cx - r, cy)
              ..arcToPoint(Offset(cx + r, cy),
