            const steps = 26;
            for (var i = 0; i <= steps; i++) {
              final x = size.width * i / steps;
              final wob = math.sin((x + shift) / size.width * math.pi * 2.2 +
                      phase) *
                  amp +
                  math.sin((x + shift) / size.width * math.pi * 5.1 +
                          phase * 1.7) *
                      amp *
                      0.35;
              final y = size.height * baseY + wob;
              if (i == 0) {
                path.moveTo(x, y);
              } else {
                path.lineTo(x, y);
              }
            }
            for (var i = steps; i >= 0; i--) {
              final x = size.width * i / steps;
              final wob = math.sin((x + shift) / size.width * math.pi * 2.2 +
                      phase) *
                  amp *
                  0.7;
              path.lineTo(x, size.height * (baseY - height) + wob);
            }
            path.close();
            final bounds = Rect.fromLTRB(0, size.height * (baseY - height) - amp,
                size.width, size.height * baseY + amp);
            canvas.drawPath(
                path,
                Paint()
                  ..shader = LinearGradient(
                      begin: Alignment.bottomCenter,
                      end: Alignment.topCenter,
                      colors: [
                        color.withValues(alpha: alpha),
                        color.withValues(alpha: alpha * 0.35),
                        color.withValues(alpha: 0),
                      ]).createShader(bounds)
                  ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 14));
          }

          curtain(0.52, size.height * 0.035, 0.4, const Color(0xFF3FE8A8),
              0.34, 0.34);
          curtain(0.44, size.height * 0.045, 2.1, const Color(0xFF6FD8FF),
              0.26, 0.22);
          curtain(0.58, size.height * 0.03, 4.0, const Color(0xFFB07CFF),
              0.20, 0.18);
          // カーテンの縦筋 (光のすだれ)
          for (var i = 0; i < 14; i++) {
            final x = size.width * (0.03 + _hash(i, 441) * 0.94);
            final topY = size.height * (0.16 + _hash(i, 442) * 0.14);
            final botY = size.height * (0.46 + _hash(i, 443) * 0.12);
            final r = Rect.fromLTRB(x - 1, topY, x + 1, botY);
            canvas.drawRect(
                r,
                Paint()
                  ..shader = LinearGradient(
                      begin: Alignment.bottomCenter,
                      end: Alignment.topCenter,
                      colors: [
                        const Color(0xFF7CF2C4)
                            .withValues(alpha: 0.12 + _hash(i, 444) * 0.10),
                        const Color(0xFF7CF2C4).withValues(alpha: 0),
                      ]).createShader(r)
                  ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3));
          }
          // 雪山 (月明かり側をわずかに明るく)
          _drawMountainLayer(canvas, size,
              baseY: 0.86,
              parallax: 0.03,
              peakHeight: 0.20,
              color: const Color(0xFF27334F));
          _drawMountainLayer(canvas, size,
              baseY: 0.95,
              parallax: 0.06,
              peakHeight: 0.24,
              color: const Color(0xFF0E1526));
          // 針葉樹のシルエット (手前)
          final tree = Paint()..color = const Color(0xFF060B16);
          for (var i = 0; i < 12; i++) {
            final x = _wrap(
                    i * size.width * 0.115 - scrollOffset.dx * 0.09 +
                        _hash(i, 445) * 20,
                    size.width + 80) -
                40;
            final h = size.height * (0.06 + _hash(i, 446) * 0.05);
            final base = size.height * 1.0;
            for (var t = 0; t < 3; t++) {
              final w = h * (0.42 - t * 0.10);
              final top = base - h * (0.55 + t * 0.22);
              final layer = Path()
                ..moveTo(x, top - h * 0.10)
                ..lineTo(x - w, top + h * 0.24)
                ..lineTo(x + w, top + h * 0.24)
                ..close();
              canvas.drawPath(layer, tree);
            }
          }
          // 地平のオーロラ反射
          canvas.drawRect(
              Rect.fromLTRB(0, size.height * 0.82, size.width, size.height),
              Paint()
                ..shader = LinearGradient(
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                    colors: [
                      const Color(0xFF3FE8A8).withValues(alpha: 0.05),
                      Colors.transparent,
                    ]).createShader(Rect.fromLTRB(
                        0, size.height * 0.82, size.width, size.height)));
          return;
        }
    }
  }

  /// 決定論的な擬似乱数 (0..1)。 テクスチャがフレーム毎に変わらないように。
  double _hash(int i, int k) {
    final v = math.sin(i * 12.9898 + k * 78.233) * 43758.5453;
    return v - v.floorToDouble();
  }

  @override
  bool shouldRepaint(_MapBackgroundTemplatePainter oldDelegate) =>
      oldDelegate.templateId != templateId ||
      oldDelegate.scrollOffset != scrollOffset;
}

/// 端子ピッカー用の形状アイコン。 実際に描かれる形をそのまま小さく描く
/// (= ユーザー要望: 判断 (ひし形) は ♦ みたいなアイコンに)。
class _FlowShapeIcon extends StatelessWidget {
  final String kind;
  final Color color;
  final Size size;
  const _FlowShapeIcon(this.kind,
      {this.color = const Color(0xFF80CBC4), this.size = const Size(34, 26)});

  @override
  Widget build(BuildContext context) {
    return CustomPaint(
      size: size,
      painter: _FlowShapeIconPainter(kind, color),
    );
  }
}

class _FlowShapeIconPainter extends CustomPainter {
  final String kind;
  final Color color;
  const _FlowShapeIconPainter(this.kind, this.color);

  @override
  void paint(Canvas canvas, Size size) {
    final rect = Rect.fromLTWH(1.5, 1.5, size.width - 3, size.height - 3);
    final col = color;
    final fill = Paint()..color = col.withValues(alpha: 0.30);
    final line = Paint()
      ..color = col
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.6
      ..strokeJoin = StrokeJoin.round;
    Path path;
    switch (kind) {
      case 'rounded':
        path = Path()
          ..addRRect(RRect.fromRectAndRadius(
              rect, Radius.circular(rect.height / 2)));
        break;
      case 'rect':
        path = Path()
          ..addRRect(
              RRect.fromRectAndRadius(rect, const Radius.circular(2.5)));
        break;
      case 'diamond':
        path = Path()
          ..moveTo(rect.center.dx, rect.top)
          ..lineTo(rect.right, rect.center.dy)
          ..lineTo(rect.center.dx, rect.bottom)
          ..lineTo(rect.left, rect.center.dy)
          ..close();
        break;
      case 'hexagon':
        final c = rect.width * 0.18;
        path = Path()
          ..moveTo(rect.left + c, rect.top)
          ..lineTo(rect.right - c, rect.top)
          ..lineTo(rect.right, rect.center.dy)
          ..lineTo(rect.right - c, rect.bottom)
          ..lineTo(rect.left + c, rect.bottom)
          ..lineTo(rect.left, rect.center.dy)
          ..close();
        break;
      case 'document':
        final w = rect.height * 0.2;
        path = Path()
          ..moveTo(rect.left, rect.top)
          ..lineTo(rect.right, rect.top)
          ..lineTo(rect.right, rect.bottom - w)
          ..quadraticBezierTo(rect.left + rect.width * 0.75,
              rect.bottom - w * 2.4, rect.center.dx, rect.bottom - w)
          ..quadraticBezierTo(rect.left + rect.width * 0.25,
              rect.bottom + w * 0.4, rect.left, rect.bottom - w)
          ..close();
        break;
      case 'cylinder':
        final e = rect.height * 0.22;
        path = Path()
          ..moveTo(rect.left, rect.top + e)
          ..arcToPoint(Offset(rect.right, rect.top + e),
              radius: Radius.elliptical(rect.width / 2, e), clockwise: true)
          ..lineTo(rect.right, rect.bottom - e)
          ..arcToPoint(Offset(rect.left, rect.bottom - e),
              radius: Radius.elliptical(rect.width / 2, e), clockwise: true)
          ..close();
        break;
      case 'trapezoid':
        final s = rect.width * 0.16;
        path = Path()
          ..moveTo(rect.left + s, rect.top)
          ..lineTo(rect.right - s, rect.top)
          ..lineTo(rect.right, rect.bottom)
          ..lineTo(rect.left, rect.bottom)
          ..close();
        break;
      case 'chevron':
        final s = rect.width * 0.18;
        path = Path()
          ..moveTo(rect.left, rect.top)
          ..lineTo(rect.right - s, rect.top)
          ..lineTo(rect.right, rect.center.dy)
          ..lineTo(rect.right - s, rect.bottom)
          ..lineTo(rect.left, rect.bottom)
          ..lineTo(rect.left + s, rect.center.dy)
          ..close();
        break;
      case 'circle':
        path = Path()..addOval(rect);
        break;
      default: // parallelogram
        final skew = rect.width * 0.2;
        path = Path()
          ..moveTo(rect.left + skew, rect.top)
          ..lineTo(rect.right, rect.top)
          ..lineTo(rect.right - skew, rect.bottom)
          ..lineTo(rect.left, rect.bottom)
          ..close();
    }
    canvas.drawPath(path, fill);
    canvas.drawPath(path, line);
    // 円筒だけ天面の輪郭を足して立体に見せる。
    if (kind == 'cylinder') {
      final e = rect.height * 0.22;
      canvas.drawOval(
          Rect.fromLTRB(
              rect.left, rect.top, rect.right, rect.top + e * 2),
          line);
    }
  }

  @override
  bool shouldRepaint(_FlowShapeIconPainter oldDelegate) =>
      oldDelegate.kind != kind || oldDelegate.color != color;
}

/// デスクトップ版のフローティングメモ窓 (= ユーザー要望: PC 版でも
/// フローティングメモを使いたい)。 ドラッグ移動 / リサイズ / 折り畳みが
/// でき、 本文は Android のオーバーレイと同じ prefs キーに自動保存される。
class _DesktopFloatingMemo extends StatefulWidget {
  /// アプリの外の窓として開き直す (= ユーザー要望)。
  final MindMapProvider provider;
  final void Function(String text) onAddNode;
  final VoidCallback onClose;
  final VoidCallback onPopOut;
  const _DesktopFloatingMemo({
    required this.provider,
    required this.onAddNode,
    required this.onClose,
    required this.onPopOut,
  });

  @override
  State<_DesktopFloatingMemo> createState() => _DesktopFloatingMemoState();
}

class _DesktopFloatingMemoState extends State<_DesktopFloatingMemo> {
  static const String _kTextKey = 'floating_memo_text_v1';
  static const String _kPosKey = 'desktop_floating_memo_pos_v1';
  final TextEditingController _ctrl = TextEditingController();
  Timer? _debounce;
  Offset _pos = const Offset(80, 90);
  double _w = 320;
  double _h = 360;
  bool _collapsed = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      final sp = await SharedPreferences.getInstance();
      _ctrl.text = sp.getString(_kTextKey) ?? '';
      final raw = sp.getString(_kPosKey) ?? '';
      final m = RegExp(r'^(-?\d+),(-?\d+),(\d+),(\d+)$').firstMatch(raw);
      if (m != null) {
        _pos = Offset(
            double.parse(m.group(1)!), double.parse(m.group(2)!));
        _w = double.parse(m.group(3)!).clamp(220.0, 900.0);
        _h = double.parse(m.group(4)!).clamp(180.0, 900.0);
      }
    } catch (_) {}
    if (mounted) setState(() {});
  }

  void _scheduleSave() {
    _debounce?.cancel();
    _debounce = Timer(const Duration(milliseconds: 400), () async {
      try {
        final sp = await SharedPreferences.getInstance();
        await sp.setString(_kTextKey, _ctrl.text);
      } catch (_) {}
    });
  }

  Future<void> _persistPos() async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setString(_kPosKey,
          '${_pos.dx.round()},${_pos.dy.round()},${_w.round()},${_h.round()}');
    } catch (_) {}
  }

  @override
  void dispose() {
    _debounce?.cancel();
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final p = widget.provider;
    final screen = MediaQuery.of(context).size;
    // ── 画面からはみ出さない大きさに収める (= ユーザー要望: モバイルで
    //    フローティングがオーバーフローする)。 縦は下部バーぶんも空ける。 ──
    final maxW = math.max(200.0, screen.width - 16);
    final maxH = math.max(160.0, screen.height - 120);
    final w = _w > maxW ? maxW : _w;
    final h = _collapsed ? 38.0 : (_h > maxH ? maxH : _h);
    final maxLeft = math.max(0.0, screen.width - w);
    final maxTop = math.max(0.0, screen.height - h);
    return Positioned(
      left: _pos.dx.clamp(0.0, maxLeft),
      top: _pos.dy.clamp(0.0, maxTop),
      child: Material(
        color: Colors.transparent,
        child: Container(
          width: w,
          height: h,
          decoration: BoxDecoration(
            color: const Color(0xFF1B1B2A),
            borderRadius: BorderRadius.circular(12),
            border: Border.all(color: Colors.white24),
            boxShadow: const [BoxShadow(color: Colors.black54, blurRadius: 16)],
          ),
          clipBehavior: Clip.antiAlias,
          child: Column(children: [
            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onPanUpdate: (d) => setState(() => _pos += d.delta),
              onPanEnd: (_) => _persistPos(),
              child: Container(
                height: 34,
                color: const Color(0xFF23233A),
                padding: const EdgeInsets.only(left: 10, right: 2),
                child: Row(children: [
                  const Icon(Icons.sticky_note_2_rounded,
                      size: 15, color: Color(0xFFFFB347)),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(p.t('cmd.floatingMemo'),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: Colors.white70, fontSize: 12)),
                  ),
                  IconButton(
                    visualDensity: VisualDensity.compact,
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 28, minHeight: 28),
                    tooltip: p.t('fmemo.addNode'),
                    icon: const Icon(Icons.add_circle_outline_rounded,
                        size: 16, color: Color(0xFF43B97F)),
                    onPressed: () => widget.onAddNode(_ctrl.text),
                  ),
                  // ── アプリの外に出す (= ユーザー要望: Chrome などで作業
                  //    しながらメモを書けるように)。 別ウィンドウとして開き、
                  //    常に手前に表示される。 ──
                  IconButton(
                    visualDensity: VisualDensity.compact,
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 28, minHeight: 28),
                    tooltip: p.t('fmemo.popOut'),
                    icon: const Icon(Icons.open_in_new_rounded,
                        size: 15, color: Color(0xFF4FC3F7)),
                    onPressed: widget.onPopOut,
                  ),
                  IconButton(
                    visualDensity: VisualDensity.compact,
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 28, minHeight: 28),
                    icon: Icon(
                        _collapsed
                            ? Icons.expand_more_rounded
                            : Icons.expand_less_rounded,
                        size: 16,
                        color: Colors.white54),
                    onPressed: () =>
                        setState(() => _collapsed = !_collapsed),
                  ),
                  IconButton(
                    visualDensity: VisualDensity.compact,
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 28, minHeight: 28),
                    icon: const Icon(Icons.close_rounded,
                        size: 16, color: Colors.white54),
                    onPressed: widget.onClose,
                  ),
                ]),
              ),
            ),
            if (!_collapsed)
              Expanded(
                child: Stack(children: [
                  Padding(
                    padding: const EdgeInsets.fromLTRB(10, 8, 10, 14),
                    child: TextField(
                      controller: _ctrl,
                      maxLines: null,
                      expands: true,
                      textAlignVertical: TextAlignVertical.top,
                      onChanged: (_) => _scheduleSave(),
                      style: const TextStyle(
                          color: Colors.white, fontSize: 13, height: 1.5),
                      decoration: InputDecoration(
                        isDense: true,
                        border: InputBorder.none,
                        hintText: p.t('fmemo.hint'),
                        hintStyle: const TextStyle(
                            color: Colors.white24, fontSize: 12),
                      ),
                    ),
                  ),
                  Positioned(
                    right: 0,
                    bottom: 0,
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onPanUpdate: (d) => setState(() {
                        _w = (_w + d.delta.dx).clamp(220.0, screen.width);
                        _h = (_h + d.delta.dy).clamp(180.0, screen.height);
                      }),
                      onPanEnd: (_) => _persistPos(),
                      child: const Padding(
                        padding: EdgeInsets.all(4),
                        child: Icon(Icons.south_east_rounded,
                            size: 13, color: Colors.white38),
                      ),
                    ),
                  ),
                ]),
              ),
          ]),
        ),
      ),
    );
  }
}

/// 契約中のサブスクを表示して、 その場で解約 / 解約の取り消しをする欄。
/// (= ユーザー要望: Google アカウントから契約中のサブスクを表示して、
///  アプリから解約できるように)
///
/// 契約は課金サーバー (Worker) が uid で持っているので、 Google
/// アカウントでログインしていれば端末を変えても同じ契約が出る。
/// Google Play で買った契約はストア側の管理なので、 その旨だけ出す。
class _SubscriptionPanel extends StatefulWidget {
  final MindMapProvider provider;
  const _SubscriptionPanel({required this.provider});

  @override
  State<_SubscriptionPanel> createState() => _SubscriptionPanelState();
}

class _SubscriptionPanelState extends State<_SubscriptionPanel> {
  bool _loading = true;
  bool _busy = false;
  String? _error;
  Map<String, dynamic>? _info;

  MindMapProvider get _p => widget.provider;

  @override
  void initState() {
    super.initState();
    unawaited(_load());
  }

  Future<void> _load() async {
    if (!_p.googleSignedIn) {
      setState(() {
        _loading = false;
        _info = null;
        _error = null;
      });
      return;
    }
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final info = await _p.fetchSubscriptionInfo();
      if (!mounted) return;
      setState(() {
        _info = info;
        _loading = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _error = '$e'.replaceFirst('Exception: ', '');
        _loading = false;
      });
    }
  }

  /// UNIX 秒 → 「2026/08/13」。
  String _fmtDate(dynamic unixSec) {
    final n = unixSec is num ? unixSec.toInt() : null;
    if (n == null || n <= 0) return '-';
    final d = DateTime.fromMillisecondsSinceEpoch(n * 1000);
    return '${d.year}/${d.month.toString().padLeft(2, '0')}/'
        '${d.day.toString().padLeft(2, '0')}';
  }

  /// 100 円単位 (Stripe は最小単位) → 「¥1,200 / 月」。
  String _fmtAmount(Map<String, dynamic> sub) {
    final amount = sub['amount'];
    if (amount is! num) return '-';
    final cur = '${sub['currency'] ?? ''}'.toUpperCase();
    // 円のように小数を持たない通貨はそのまま、 それ以外は 1/100。
    const zeroDecimal = {'JPY', 'KRW', 'VND', 'CLP'};
    final v = zeroDecimal.contains(cur)
        ? amount.toDouble()
        : amount.toDouble() / 100.0;
    final sym = cur == 'JPY' ? '¥' : (cur == 'USD' ? '\$' : '');
    final body = sym.isEmpty
        ? '${v.toStringAsFixed(zeroDecimal.contains(cur) ? 0 : 2)} $cur'
        : '$sym${v.toStringAsFixed(zeroDecimal.contains(cur) ? 0 : 2)}';
    final interval = '${sub['interval'] ?? ''}';
    final unit = interval == 'year'
        ? _p.t('plan.perYear')
        : (interval == 'month' ? _p.t('plan.perMonth') : '');
    return unit.isEmpty ? body : '$body $unit';
  }

  Future<void> _confirmCancel(Map<String, dynamic> sub) async {
    final until = _fmtDate(sub['currentPeriodEnd']);
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E1E),
        title: Text(_p.t('sub.cancelConfirmTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Text(
            _p.t('sub.cancelConfirmBody').replaceFirst('{date}', until),
            style: const TextStyle(
                color: Colors.white70, fontSize: 13, height: 1.6)),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, false),
            child: Text(_p.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFE57373),
                foregroundColor: Colors.black),
            onPressed: () => Navigator.pop(dctx, true),
            child: Text(_p.t('sub.cancelBtn')),
          ),
        ],
      ),
    );
    if (ok != true) return;
    await _apply(true, until: until);
  }

  Future<void> _apply(bool cancel, {String? until}) async {
    setState(() => _busy = true);
    try {
      final info = await _p.setSubscriptionCancel(cancel);
      if (!mounted) return;
      setState(() {
        _info = info;
        _busy = false;
        _error = null;
      });
      final sub = info['subscription'];
      final end = sub is Map ? _fmtDate(sub['currentPeriodEnd']) : (until ?? '-');
      _appSnack(
        context,
        SnackBar(
          backgroundColor: const Color(0xFF43B97F),
          content: Text(cancel
              ? _p.t('sub.cancelled').replaceFirst('{date}', end)
              : _p.t('sub.resumed')),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _busy = false;
        _error = '$e'.replaceFirst('Exception: ', '');
      });
    }
  }

  Widget _row(String label, String value, {Color? valueColor}) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 2),
        child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          SizedBox(
            width: 92,
            child: Text(label,
                style: const TextStyle(color: Colors.white38, fontSize: 11)),
          ),
          Expanded(
            child: Text(value,
                style: TextStyle(
                    color: valueColor ?? Colors.white,
                    fontSize: 12,
                    fontWeight: FontWeight.w600)),
          ),
        ]),
      );

  @override
  Widget build(BuildContext context) {
    final sub = _info?['subscription'];
    final isPlay = '${_info?['store'] ?? ''}' == 'play';
    final willCancel = sub is Map && sub['cancelAtPeriodEnd'] == true;
    return Container(
      decoration: BoxDecoration(
        color: const Color(0xFF9575CD).withValues(alpha: 0.07),
        borderRadius: BorderRadius.circular(8),
        border:
            Border.all(color: const Color(0xFF9575CD).withValues(alpha: 0.3)),
      ),
      padding: const EdgeInsets.all(10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(children: [
            const Icon(Icons.card_membership_rounded,
                color: Color(0xFF9575CD), size: 18),
            const SizedBox(width: 8),
            Expanded(
              child: Text(_p.t('sub.currentTitle'),
                  style: const TextStyle(
                      color: Color(0xFF9575CD),
                      fontSize: 12,
                      fontWeight: FontWeight.w700)),
            ),
            if (_p.googleSignedIn)
              InkWell(
                onTap: _loading || _busy ? null : _load,
                borderRadius: BorderRadius.circular(6),
                child: const Padding(
                  padding: EdgeInsets.all(4),
                  child: Icon(Icons.refresh_rounded,
                      color: Colors.white38, size: 16),
                ),
              ),
          ]),
          const SizedBox(height: 6),
          if (!_p.googleSignedIn)
            Text(_p.t('sub.needSignIn'),
                style: const TextStyle(
                    color: Color(0xFFFFB74D), fontSize: 11.5, height: 1.5))
          else if (_loading)
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 8),
              child: SizedBox(
                width: 16,
                height: 16,
                child: CircularProgressIndicator(
                    strokeWidth: 2, color: Color(0xFF9575CD)),
              ),
            )
          else if (_error != null)
            Text(_error!,
                style: const TextStyle(
                    color: Color(0xFFFF8A80), fontSize: 11, height: 1.5))
          else if (isPlay)
            Text(_p.t('sub.storeManaged'),
                style: const TextStyle(
                    color: Colors.white54, fontSize: 11, height: 1.5))
          else if (sub is! Map)
            Text(_p.t('sub.none'),
                style: const TextStyle(
                    color: Colors.white54, fontSize: 11.5, height: 1.5))
          else ...[
            _row(
              _p.t('sub.status'),
              willCancel
                  ? _p
                      .t('sub.willCancel')
                      .replaceFirst('{date}', _fmtDate(sub['currentPeriodEnd']))
                  : '${sub['status'] ?? '-'}',
              valueColor: willCancel
                  ? const Color(0xFFFFB74D)
                  : const Color(0xFF9CCC65),
            ),
            _row(
                willCancel ? _p.t('sub.endsOn') : _p.t('sub.nextBilling'),
                _fmtDate(sub['currentPeriodEnd'])),
            _row(_p.t('sub.amount'), _fmtAmount(sub.cast<String, dynamic>())),
            const SizedBox(height: 8),
            SizedBox(
              width: double.infinity,
              child: willCancel
                  ? ElevatedButton.icon(
                      style: ElevatedButton.styleFrom(
                        backgroundColor: const Color(0xFF1A2A14),
                        foregroundColor: Colors.white,
                        side: const BorderSide(
                            color: Color(0xFF9CCC65), width: 1),
                      ),
                      icon: _busy
                          ? const SizedBox(
                              width: 13,
                              height: 13,
                              child: CircularProgressIndicator(
                                  strokeWidth: 2, color: Color(0xFF9CCC65)))
                          : const Icon(Icons.replay_rounded,
                              size: 15, color: Color(0xFF9CCC65)),
                      label: Text(_p.t('sub.resumeBtn'),
                          style: const TextStyle(
                              color: Color(0xFF9CCC65), fontSize: 12)),
                      onPressed: _busy ? null : () => _apply(false),
                    )
                  : ElevatedButton.icon(
                      style: ElevatedButton.styleFrom(
                        backgroundColor: const Color(0xFF2A1A1A),
                        foregroundColor: Colors.white,
                        side: const BorderSide(
                            color: Color(0xFFE57373), width: 1),
                      ),
                      icon: _busy
                          ? const SizedBox(
                              width: 13,
                              height: 13,
                              child: CircularProgressIndicator(
                                  strokeWidth: 2, color: Color(0xFFE57373)))
                          : const Icon(Icons.cancel_outlined,
                              size: 15, color: Color(0xFFE57373)),
                      label: Text(_p.t('sub.cancelBtn'),
                          style: const TextStyle(
                              color: Color(0xFFE57373), fontSize: 12)),
                      onPressed: _busy
                          ? null
                          : () => _confirmCancel(sub.cast<String, dynamic>()),
                    ),
            ),
          ],
        ],
      ),
    );
  }
}

/// 「2 分割に戻す」 アイコン: 左右に四角を 1 つずつ (= ユーザー要望)。
/// 共同編集で他の参加者が編集中の要素に重ねる枠 + 名前
/// (= ユーザー要望: どのユーザーが操作しているか表示されるように)。
class _LiveLockBadge extends StatelessWidget {
