}

/// 分割レイアウトを四角の並びで表すアイコン (= ユーザー要望: マップ分割
/// ボタンは 「次になる分割モード」 に合わせた見た目にして欲しい。 4 分割なら
/// 四角 4 つ、 左右 2 分割なら左右に四角 2 つ)。
class _SplitLayoutIcon extends StatelessWidget {
  /// 1 = 単一画面 / 2 = 2 分割 / 4 = 4 分割。
  final int panes;

  /// 2 分割の時に上下へ並べるか (false = 左右)。
  final bool stacked;
  final Color color;
  final double size;
  const _SplitLayoutIcon({
    required this.panes,
    required this.color,
    this.stacked = false,
    this.size = 15,
  });

  @override
  Widget build(BuildContext context) {
    final deco = BoxDecoration(
      border: Border.all(color: color, width: 1.4),
      borderRadius: BorderRadius.circular(1.5),
    );
    final full = size * 0.86;
    final gap = size * 0.13;
    final half = (full - gap) / 2;
    Widget box(double w, double h) =>
        Container(width: w, height: h, decoration: deco);

    Widget body;
    if (panes <= 1) {
      body = box(full, full);
    } else if (panes == 2) {
      body = stacked
          ? Column(mainAxisSize: MainAxisSize.min, children: [
              box(full, half),
              SizedBox(height: gap),
              box(full, half),
            ])
          : Row(mainAxisSize: MainAxisSize.min, children: [
              box(half, full),
              SizedBox(width: gap),
              box(half, full),
            ]);
    } else {
      Widget pair() => Row(mainAxisSize: MainAxisSize.min, children: [
            box(half, half),
            SizedBox(width: gap),
            box(half, half),
          ]);
      body = Column(mainAxisSize: MainAxisSize.min, children: [
        pair(),
        SizedBox(height: gap),
        pair(),
      ]);
    }
    return SizedBox(width: size, height: size, child: Center(child: body));
  }
}

// ─── 自作背景メーカー (= ユーザー要望: 画像を渡すだけでなく、 テンプレート
//     風の背景画像を自分で作れる編集画面が欲しい) ────────────────────────────
// グラデ 2 色 + 要素 (星 / 光 / 山 / 波 / 方眼 / 花びら / 泡 / ビネット) を
// 組み合わせてプレビューし、 PNG に書き出してページ背景として適用する。
class _CustomBgSpec {
  final Color top;
  final Color bottom;
  final Color accent;
  final bool diagonal;
  final int stars;
  final int glows;
  final int bubbles;
  final int petals;
  final bool mountains;
  final bool waves;
  final bool grid;
  final bool vignette;
  const _CustomBgSpec({
    required this.top,
    required this.bottom,
    required this.accent,
    required this.diagonal,
    required this.stars,
    required this.glows,
    required this.bubbles,
    required this.petals,
    required this.mountains,
    required this.waves,
    required this.grid,
    required this.vignette,
  });
}

class _CustomBgPainter extends CustomPainter {
  final _CustomBgSpec spec;
  const _CustomBgPainter(this.spec);

  double _h(int i, int k) {
    final v = math.sin(i * 12.9898 + k * 78.233) * 43758.5453;
    return v - v.floorToDouble();
  }

  @override
  void paint(Canvas canvas, Size size) {
    if (size.isEmpty) return;
    canvas.clipRect(Offset.zero & size);
    final rect = Offset.zero & size;
    // ベースグラデ (中間色は自動)
    final mid = Color.lerp(spec.top, spec.bottom, 0.55)!;
    canvas.drawRect(
        rect,
        Paint()
          ..shader = LinearGradient(
              begin: spec.diagonal ? Alignment.topLeft : Alignment.topCenter,
              end: spec.diagonal
                  ? Alignment.bottomRight
                  : Alignment.bottomCenter,
              colors: [spec.top, mid, spec.bottom]).createShader(rect));
    // 光のにじみ
    for (var i = 0; i < spec.glows; i++) {
      final c = Offset(
          size.width * _h(i, 201), size.height * (0.08 + _h(i, 202) * 0.5));
      final r = size.shortestSide * (0.25 + _h(i, 203) * 0.25);
      canvas.drawCircle(
          c,
          r,
          Paint()
            ..shader = RadialGradient(colors: [
              spec.accent.withValues(alpha: 0.18),
              spec.accent.withValues(alpha: 0),
            ]).createShader(Rect.fromCircle(center: c, radius: r)));
    }
    // 方眼
    if (spec.grid) {
      final minor = Paint()
        ..color = spec.accent.withValues(alpha: 0.07)
        ..strokeWidth = 1;
      final major = Paint()
        ..color = spec.accent.withValues(alpha: 0.16)
        ..strokeWidth = 1.3;
      for (var i = 0; i <= 24; i++) {
        final x = size.width * i / 24;
        canvas.drawLine(
            Offset(x, 0), Offset(x, size.height), i % 6 == 0 ? major : minor);
      }
      for (var i = 0; i <= 24; i++) {
        final y = size.height * i / 24;
        canvas.drawLine(
            Offset(0, y), Offset(size.width, y), i % 6 == 0 ? major : minor);
      }
    }
    // 星
    for (var i = 0; i < spec.stars; i++) {
      final x = size.width * _h(i, 211);
      final y = size.height * _h(i, 212) * 0.85;
      final r = i % 9 == 0 ? 1.8 : (i % 4 == 0 ? 1.2 : 0.7);
      final a = i % 9 == 0 ? 0.9 : (i % 4 == 0 ? 0.65 : 0.4);
      canvas.drawCircle(
          Offset(x, y), r, Paint()..color = spec.accent.withValues(alpha: a));
      if (i % 11 == 0) {
        final flare = Paint()
          ..color = spec.accent.withValues(alpha: 0.25)
          ..strokeWidth = 0.8;
        canvas.drawLine(Offset(x - 4, y), Offset(x + 4, y), flare);
        canvas.drawLine(Offset(x, y - 4), Offset(x, y + 4), flare);
      }
    }
    // 山並み (奥 + 手前の 2 層。 色は下の色を暗くして自動生成)
    if (spec.mountains) {
      void layer(double baseY, double peak, double alpha, int salt) {
        final col = Color.lerp(spec.bottom, Colors.black, 0.35)!
            .withValues(alpha: alpha);
        final path = Path()
          ..moveTo(0, size.height)
          ..lineTo(0, size.height * baseY);
        var x = 0.0;
        var i = 0;
        while (x < size.width) {
          final w = size.width * (0.18 + _h(i, salt) * 0.14);
          path.lineTo(x + w * 0.5,
              size.height * (baseY - peak * (0.5 + _h(i, salt + 1) * 0.5)));
          path.lineTo(x + w, size.height * baseY);
          x += w;
          i++;
        }
        path
          ..lineTo(size.width, size.height)
          ..close();
        canvas.drawPath(path, Paint()..color = col);
      }

      layer(0.78, 0.30, 0.55, 221);
      layer(0.88, 0.22, 0.85, 231);
    }
    // 波線
    if (spec.waves) {
      for (var i = 0; i < 4; i++) {
        final y = size.height * (0.62 + i * 0.09);
        final wave = Path()..moveTo(0, y);
        for (var x = 0.0; x <= size.width; x += size.width / 8) {
          wave.quadraticBezierTo(
              x + size.width / 16,
              y + math.sin(i * 1.3 + x / size.width * 6.28) * 8 - 8,
              x + size.width / 8,
              y);
        }
        canvas.drawPath(
            wave,
            Paint()
              ..color = spec.accent.withValues(alpha: 0.16 - i * 0.02)
              ..style = PaintingStyle.stroke
              ..strokeWidth = 2.0);
      }
    }
    // 花びら
    for (var i = 0; i < spec.petals; i++) {
      final x = size.width * _h(i, 241);
      final y = size.height * _h(i, 242);
      final s = 2.6 + _h(i, 243) * 4.0;
      canvas.save();
      canvas.translate(x, y);
      canvas.rotate(_h(i, 244) * math.pi);
      canvas.drawOval(
          Rect.fromCenter(center: Offset.zero, width: s * 1.9, height: s),
          Paint()
            ..color = Color(i % 3 == 0 ? 0xFFF7A8C4 : 0xFFFBC7D9)
                .withValues(alpha: 0.5 + _h(i, 245) * 0.35));
      canvas.restore();
    }
    // 泡
    for (var i = 0; i < spec.bubbles; i++) {
      final x = size.width * _h(i, 251);
      final y = size.height * _h(i, 252);
      final r = 1.5 + _h(i, 253) * 3.5;
      canvas.drawCircle(
          Offset(x, y),
          r,
          Paint()
            ..color = spec.accent.withValues(alpha: 0.20)
            ..style = PaintingStyle.stroke
            ..strokeWidth = 0.9);
      canvas.drawCircle(Offset(x - r * 0.3, y - r * 0.3), r * 0.25,
          Paint()..color = spec.accent.withValues(alpha: 0.30));
    }
    // ビネット
    if (spec.vignette) {
      canvas.drawRect(
          rect,
          Paint()
            ..shader = RadialGradient(radius: 1.15, colors: [
              Colors.transparent,
              Colors.black.withValues(alpha: 0.30),
            ]).createShader(rect));
    }
  }

  @override
  bool shouldRepaint(_CustomBgPainter oldDelegate) => true;
}

class _BackgroundMakerDialog extends StatefulWidget {
  final MindMapProvider provider;

  /// 書き出した PNG のパスを受け取って背景に適用するコールバック。
  final Future<void> Function(String path) onSaved;
  const _BackgroundMakerDialog(
      {required this.provider, required this.onSaved});
  @override
  State<_BackgroundMakerDialog> createState() =>
      _BackgroundMakerDialogState();
}

class _BackgroundMakerDialogState extends State<_BackgroundMakerDialog> {
  Color _top = const Color(0xFF0D1B4C);
  Color _bottom = const Color(0xFF2E1A47);
  Color _accent = Colors.white;
  bool _diagonal = false;
  int _stars = 60;
  int _glows = 2;
  int _bubbles = 0;
  int _petals = 0;
  bool _mountains = true;
  bool _waves = false;
  bool _grid = false;
  bool _vignette = true;
  bool _saving = false;

  static const List<Color> _palette = [
    Color(0xFF0D1B4C),
    Color(0xFF2E1A47),
    Color(0xFF071C34),
    Color(0xFF123B62),
    Color(0xFF1B2E24),
    Color(0xFF23392E),
    Color(0xFF6E441F),
    Color(0xFF8A5A33),
    Color(0xFF53C3E0),
    Color(0xFF0F517F),
    Color(0xFFF3D9E4),
    Color(0xFFCDE6F7),
    Color(0xFFFFF3E0),
    Color(0xFFFFD54F),
    Color(0xFFF06292),
    Color(0xFF80CBC4),
    Color(0xFF263238),
    Color(0xFF000000),
    Color(0xFFFFFFFF),
    Color(0xFF6C63FF),
  ];

  _CustomBgSpec get _spec => _CustomBgSpec(
        top: _top,
        bottom: _bottom,
        accent: _accent,
        diagonal: _diagonal,
        stars: _stars,
        glows: _glows,
        bubbles: _bubbles,
        petals: _petals,
        mountains: _mountains,
        waves: _waves,
        grid: _grid,
        vignette: _vignette,
      );

  Widget _swatchRow(String label, Color current, void Function(Color) onPick) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(label,
            style: const TextStyle(color: Colors.white70, fontSize: 12)),
        const SizedBox(height: 6),
        Wrap(
          spacing: 6,
          runSpacing: 6,
          children: [
            for (final c in _palette)
              GestureDetector(
                onTap: () => setState(() => onPick(c)),
                child: Container(
                  width: 22,
                  height: 22,
                  decoration: BoxDecoration(
                    color: c,
                    shape: BoxShape.circle,
                    border: Border.all(
                      color: current == c
                          ? const Color(0xFF8C7CFF)
                          : Colors.white24,
                      width: current == c ? 2.5 : 1,
                    ),
                  ),
                ),
              ),
          ],
        ),
      ],
    );
  }

  Widget _intSlider(
      String label, int value, int max, void Function(int) apply) {
    return Row(children: [
      SizedBox(
        width: 92,
        child: Text('$label ($value)',
            style: const TextStyle(color: Colors.white70, fontSize: 12)),
      ),
      Expanded(
        child: Slider(
          value: value.toDouble(),
          min: 0,
          max: max.toDouble(),
          activeColor: const Color(0xFF6C63FF),
          onChanged: (v) => setState(() => apply(v.round())),
        ),
      ),
    ]);
  }

  Widget _boolChip(String label, bool value, void Function(bool) apply) {
    return FilterChip(
      label: Text(label,
          style: TextStyle(
              color: value ? Colors.white : Colors.white60, fontSize: 12)),
      selected: value,
      showCheckmark: false,
      selectedColor: const Color(0xFF6C63FF),
      backgroundColor: const Color(0xFF1E1E32),
      side: BorderSide(color: value ? Colors.transparent : Colors.white24),
      onSelected: (v) => setState(() => apply(v)),
    );
  }

  Future<void> _save() async {
    if (_saving) return;
    setState(() => _saving = true);
    final provider = widget.provider;
    try {
      final rec = ui.PictureRecorder();
      final canvas = Canvas(rec);
      const outSize = Size(1600, 1000);
      _CustomBgPainter(_spec).paint(canvas, outSize);
      final img = await rec.endRecording().toImage(1600, 1000);
      final bytes = await img.toByteData(format: ui.ImageByteFormat.png);
      if (bytes == null) throw Exception('encode failed');
      final appDir = await getApplicationDocumentsDirectory();
      final dir = Directory('${appDir.path}/attachments');
      if (!await dir.exists()) await dir.create(recursive: true);
      final path =
          '${dir.path}/custombg_${DateTime.now().millisecondsSinceEpoch}.png';
      await File(path)
          .writeAsBytes(bytes.buffer.asUint8List(), flush: true);
      await widget.onSaved(path);
      if (mounted) Navigator.of(context).pop();
    } catch (_) {
      if (mounted) {
        setState(() => _saving = false);
        ScaffoldMessenger.maybeOf(context)?.showSnackBar(SnackBar(
          content: Text(provider.t('bg.makerSaveFailed')),
          backgroundColor: Colors.redAccent,
        ));
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final provider = widget.provider;
    return AlertDialog(
      backgroundColor: const Color(0xFF2A2A3A),
      title: Row(children: [
        const Icon(Icons.palette_rounded, color: Color(0xFF6C63FF)),
        const SizedBox(width: 10),
        Text(provider.t('bg.makerTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
      ]),
      content: SizedBox(
        width: 460,
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // ── ライブプレビュー ──
              Container(
                width: double.infinity,
                height: 160,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: Colors.white12),
                ),
                clipBehavior: Clip.antiAlias,
                child: CustomPaint(
                  painter: _CustomBgPainter(_spec),
                  child: const SizedBox.expand(),
                ),
              ),
              const SizedBox(height: 12),
              _swatchRow(provider.t('bg.makerTop'), _top, (c) => _top = c),
              const SizedBox(height: 10),
              _swatchRow(
                  provider.t('bg.makerBottom'), _bottom, (c) => _bottom = c),
              const SizedBox(height: 10),
              _swatchRow(
                  provider.t('bg.makerAccent'), _accent, (c) => _accent = c),
              const SizedBox(height: 12),
              Wrap(spacing: 8, runSpacing: 8, children: [
                _boolChip(provider.t('bg.makerDiagonal'), _diagonal,
                    (v) => _diagonal = v),
                _boolChip(provider.t('bg.makerMountains'), _mountains,
                    (v) => _mountains = v),
                _boolChip(
                    provider.t('bg.makerWaves'), _waves, (v) => _waves = v),
                _boolChip(
                    provider.t('bg.makerGrid'), _grid, (v) => _grid = v),
                _boolChip(provider.t('bg.makerVignette'), _vignette,
                    (v) => _vignette = v),
              ]),
              const SizedBox(height: 8),
              _intSlider(provider.t('bg.makerStars'), _stars, 120,
                  (v) => _stars = v),
              _intSlider(provider.t('bg.makerGlows'), _glows, 5,
                  (v) => _glows = v),
              _intSlider(provider.t('bg.makerBubbles'), _bubbles, 40,
                  (v) => _bubbles = v),
              _intSlider(provider.t('bg.makerPetals'), _petals, 40,
                  (v) => _petals = v),
            ],
          ),
        ),
      ),
      actions: [
        TextButton(
          onPressed: _saving ? null : () => Navigator.of(context).pop(),
          child: Text(provider.t('common.cancel'),
              style: const TextStyle(color: Colors.white54)),
        ),
        ElevatedButton.icon(
          style: ElevatedButton.styleFrom(
            backgroundColor: const Color(0xFF6C63FF),
            foregroundColor: Colors.white,
          ),
          onPressed: _saving ? null : _save,
          icon: _saving
              ? const SizedBox(
                  width: 14,
                  height: 14,
                  child: CircularProgressIndicator(
                      strokeWidth: 2, color: Colors.white))
              : const Icon(Icons.check_rounded, size: 18),
          label: Text(provider.t('bg.makerSave')),
        ),
      ],
    );
  }
}

class _GridPainter extends CustomPainter {
  final bool isDesktop;
  final bool isDark;
  const _GridPainter({this.isDesktop = false, this.isDark = true});

  @override
  void paint(Canvas canvas, Size size) {
    // デスクトップ: 大マス160px（太め）+ 小マス40px（薄い補助線）
    // モバイル: 40px のみ
    // ライトモード: 線は黒の半透明、ダークモード: 白の半透明
    final base = isDark ? Colors.white : Colors.black;
    if (isDesktop) {
      // 補助グリッド 40px（薄い）
      final subPaint = Paint()
        ..color = base.withValues(alpha: isDark ? 0.04 : 0.08)
        ..strokeWidth = 0.5;
      const subStep = 40.0;
      for (double x = 0; x <= size.width; x += subStep) {
        canvas.drawLine(Offset(x, 0), Offset(x, size.height), subPaint);
      }
      for (double y = 0; y <= size.height; y += subStep) {
        canvas.drawLine(Offset(0, y), Offset(size.width, y), subPaint);
      }
      // メイングリッド 160px（しっかり見える）
      final mainPaint = Paint()
        ..color = base.withValues(alpha: isDark ? 0.11 : 0.22)
        ..strokeWidth = 1.0;
      const mainStep = 160.0;
      for (double x = 0; x <= size.width; x += mainStep) {
        canvas.drawLine(Offset(x, 0), Offset(x, size.height), mainPaint);
      }
      for (double y = 0; y <= size.height; y += mainStep) {
        canvas.drawLine(Offset(0, y), Offset(size.width, y), mainPaint);
      }
    } else {
      final paint = Paint()
        ..color = base.withValues(alpha: isDark ? 0.07 : 0.15)
        ..strokeWidth = 1;
      const step = 40.0;
      for (double x = 0; x <= size.width; x += step) {
        canvas.drawLine(Offset(x, 0), Offset(x, size.height), paint);
      }
      for (double y = 0; y <= size.height; y += step) {
        canvas.drawLine(Offset(0, y), Offset(size.width, y), paint);
      }
    }
  }

  @override
  bool shouldRepaint(_GridPainter old) =>
      old.isDesktop != isDesktop || old.isDark != isDark;
}

/// ギャラリーページ用の背景 (= ユーザー要望: 方眼紙をやめておしゃれな感じに)。
/// 網目グリッドの代わりに、 斜めグラデーション + 柔らかい光の円 (bokeh) を
/// 描き、 各タイル (本) の行の下に極薄の棚ライン + 影を入れて「本が乗って
/// いる」 雰囲気を出す。
class _BookshelfBackgroundPainter extends CustomPainter {
  /// 並んでいるタイルの矩形 (キャンバス座標)。 行ごとに棚ラインを引くのに使う。
  final List<Rect> tileRects;
  final bool isDark;
  const _BookshelfBackgroundPainter(
      {required this.tileRects, this.isDark = true});

  @override
  void paint(Canvas canvas, Size size) {
    // ── ブロックが置かれている所だけ「棚パネル」 を描く ──
    // (= ユーザー要望: ブロック以外の場所に背景パネルを作らない)。
    // キャンバス全体のグラデーションや bokeh は描かない (空きは透明)。
    if (tileRects.isEmpty) return;

    // タイルを行ごとにグルーピング (top をキーに。 同じ行は同じ y)。
    final rowTop = <int, double>{};
    final rowBottom = <int, double>{};
    final rowLeft = <int, double>{};
    final rowRight = <int, double>{};
    for (final r in tileRects) {
      final key = r.top.round();
      rowTop[key] = rowTop[key] == null ? r.top : math.min(rowTop[key]!, r.top);
      rowBottom[key] = rowBottom[key] == null
          ? r.bottom
          : math.max(rowBottom[key]!, r.bottom);
      rowLeft[key] =
          rowLeft[key] == null ? r.left : math.min(rowLeft[key]!, r.left);
      rowRight[key] =
          rowRight[key] == null ? r.right : math.max(rowRight[key]!, r.right);
    }

    for (final key in rowBottom.keys) {
      final top = rowTop[key]!;
      final bottom = rowBottom[key]!;
      final left = rowLeft[key]! - 12;
      final right = rowRight[key]! + 12;
      if (right <= left) continue;
      // ブロックの後ろの柔らかいパネル。
      final panel = Rect.fromLTRB(left, top - 10, right, bottom + 14);
      canvas.drawRRect(
        RRect.fromRectAndRadius(panel, const Radius.circular(14)),
        Paint()
          ..color = (isDark ? const Color(0xFF231B3A) : const Color(0xFFF4F1FF))
              .withValues(alpha: isDark ? 0.55 : 0.75),
      );
      // 本が乗っている感じの柔らかい影。
      canvas.drawRRect(
        RRect.fromRectAndRadius(
            Rect.fromLTWH(left, bottom + 4, right - left, 10),
            const Radius.circular(6)),
        Paint()
          ..color = Colors.black.withValues(alpha: isDark ? 0.28 : 0.12)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6),
      );
      // 細い棚ライン。
      canvas.drawRRect(
        RRect.fromRectAndRadius(
            Rect.fromLTWH(left, bottom + 2, right - left, 3),
            const Radius.circular(2)),
        Paint()
          ..color =
              (isDark ? Colors.white : Colors.black).withValues(alpha: 0.10),
      );
    }
  }

  @override
  bool shouldRepaint(covariant _BookshelfBackgroundPainter old) => true;
}

// ─── 範囲選択矩形ペインター ───────────────────────────────────────────────────

class _RangeSelectionPainter extends CustomPainter {
  final Offset start;
  final Offset end;

  _RangeSelectionPainter({required this.start, required this.end});

  @override
  void paint(Canvas canvas, Size size) {
    final rect = Rect.fromPoints(start, end);

    // 半透明の塗りつぶし
    final fillPaint = Paint()
      ..color = const Color(0xFF4FC3F7).withValues(alpha: 0.12)
      ..style = PaintingStyle.fill;
    canvas.drawRRect(
        RRect.fromRectAndRadius(rect, const Radius.circular(4)), fillPaint);

    // 枠線（ダッシュ風に点線で描画）
    final borderPaint = Paint()
      ..color = const Color(0xFF4FC3F7).withValues(alpha: 0.7)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.5;
    canvas.drawRRect(
        RRect.fromRectAndRadius(rect, const Radius.circular(4)), borderPaint);
  }

  @override
  bool shouldRepaint(_RangeSelectionPainter old) =>
      old.start != start || old.end != end;
}

