// ─── PC版（webview_windows）YouTube検索シート ─────────────────────────────────

class _WindowsYoutubeSearchSheet extends StatefulWidget {
  final String keyword;
  final int count;
  final int minMinutes;
  final int maxMinutes;
  final String searchUrl;
  final void Function(List<String> videoIds, List<String> titles) onResults;
  const _WindowsYoutubeSearchSheet({
    required this.keyword,
    required this.count,
    this.minMinutes = 0,
    this.maxMinutes = 0,
    required this.searchUrl,
    required this.onResults,
  });
  @override
  State<_WindowsYoutubeSearchSheet> createState() =>
      _WindowsYoutubeSearchSheetState();
}

class _WindowsYoutubeSearchSheetState
    extends State<_WindowsYoutubeSearchSheet> {
  final wv_win.WebviewController _controller = wv_win.WebviewController();
  bool _initialized = false;
  bool _loading = true;
  bool _extracted = false;
  int _retryCount = 0;
  final List<String> _foundIds = [];
  final List<String> _foundTitles = [];
  final Set<String> _seenIds = {};

  @override
  void initState() {
    super.initState();
    _initController();
  }

  Future<void> _initController() async {
    // Linux: flutter_linux_webview は JS→Dart チャンネルが無く、 この
    //   スクレイパ (URLスキームで結果を受信) は機能しない。 ハングを防ぐため
    //   即座に空結果でコールバックしてシートを閉じる (= Linux 未対応の縮退)。
    if (Platform.isLinux) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        widget.onResults(const <String>[], const <String>[]);
        Navigator.of(context).maybePop();
      });
      return;
    }
    try {
      await _controller.initialize();
      // ── ユーザー要望: 広告から戻れるように、 ポップアップ / 新規ウィンドウを
      //    別ウィンドウではなく現在の WebView 内で開く。 ──
      try {
        await _controller
            .setPopupWindowPolicy(wv_win.WebviewPopupWindowPolicy.sameWindow);
      } catch (_) {}
      // URLスキーム経由で検索結果を受信
      _controller.url.listen((url) {
        if (url == null || !url.startsWith('flutter-results://')) return;
        if (_extracted) return;
        try {
          final decoded =
              Uri.decodeComponent(url.replaceFirst('flutter-results://', ''));
          final parts = decoded.split('|||');
          for (final p in parts) {
            final kv = p.split(':::');
            if (kv.length == 2 &&
                kv[0].isNotEmpty &&
                !_seenIds.contains(kv[0])) {
              _seenIds.add(kv[0]);
              _foundIds.add(kv[0]);
              _foundTitles.add(kv[1].isEmpty ? widget.keyword : kv[1]);
            }
          }
          if (_foundIds.length >= widget.count) _finalize();
        } catch (_) {}
      });
      _controller.loadingState.listen((state) {
        if (!mounted) return;
        setState(() => _loading = state == wv_win.LoadingState.loading);
        if (state == wv_win.LoadingState.navigationCompleted) {
          Future.delayed(const Duration(seconds: 2), _tryExtract);
          Future.delayed(const Duration(seconds: 7), () {
            if (!_extracted && _foundIds.isNotEmpty && mounted) _finalize();
          });
        }
      });
      await _controller.loadUrl(widget.searchUrl);
      if (mounted) setState(() => _initialized = true);
    } catch (_) {}
  }

  void _finalize() {
    if (_extracted) return;
    _extracted = true;
    if (_foundIds.isNotEmpty) {
      widget.onResults(
        _foundIds.take(widget.count).toList(),
        _foundTitles.take(widget.count).toList(),
      );
      if (mounted) Navigator.pop(context);
    }
  }

  Future<void> _tryExtract() async {
    if (_extracted || !mounted) return;
    _retryCount++;
    final minSec = widget.minMinutes * 60;
    final maxSec = widget.maxMinutes > 0 ? widget.maxMinutes * 60 : 999999;
    final alreadySeen = _seenIds.map((id) => '"$id"').join(',');
    final max = widget.count;

    // JavaScript実行してURLリストを取得する
    // webview_windowsはJSチャンネルがないのでpostMessageの代わりにURLスキームを使う
    try {
      await _controller.executeScript('''
        (function() {
          try {
            var minSec = $minSec;
            var maxSec = $maxSec;
            var already = new Set([$alreadySeen]);
            var need = $max - already.size;
            if (need <= 0) return;

            function parseDuration(text) {
              if (!text) return 0;
              text = text.trim();
              var parts = text.split(':').map(function(x){ return parseInt(x,10)||0; });
              if (parts.length === 3) return parts[0]*3600 + parts[1]*60 + parts[2];
              if (parts.length === 2) return parts[0]*60 + parts[1];
              return 0;
            }

            function getDuration(card) {
              var selectors = [
                'ytd-thumbnail-overlay-time-status-renderer span',
                '.badge-shape-wiz__text',
                'span.style-scope.ytd-thumbnail-overlay-time-status-renderer',
              ];
              for (var s = 0; s < selectors.length; s++) {
                var els = card.querySelectorAll(selectors[s]);
                for (var e = 0; e < els.length; e++) {
                  var t = (els[e].textContent || '').trim();
                  if (/^\\d+:\\d+/.test(t)) return parseDuration(t);
                }
              }
              return 0;
            }

            var cards = document.querySelectorAll(
              'ytd-video-renderer, ytd-rich-item-renderer'
            );
            var results = [];
            for (var i = 0; i < cards.length && results.length < need; i++) {
              var card = cards[i];
              var link = card.querySelector('a[href*="/watch?v="]');
              if (!link) continue;
              var href = link.getAttribute('href') || '';
              var m = href.match(/[?&]v=([a-zA-Z0-9_-]{11})/);
              if (!m || already.has(m[1])) continue;

              var dur = getDuration(card);
              if (dur > 0 && (dur < minSec || dur > maxSec)) continue;

              already.add(m[1]);
              var title = '';
              try {
                var h3 = card.querySelector('#video-title, h3, .title');
                if (h3) title = (h3.textContent || h3.getAttribute('aria-label') || '').trim();
                if (!title) title = (link.getAttribute('aria-label') || '').trim();
              } catch(e) {}
              var durMin = dur > 0 ? Math.floor(dur/60) + ':' + ('0'+dur%60).slice(-2) : '';
              results.push(m[1] + ':::' + title.substring(0, 55) + (durMin ? ' ['+durMin+']' : ''));
            }
            if (results.length > 0) {
              // URLスキームでFlutterに送信
              window.location.href = 'flutter-results://' + encodeURIComponent(results.join('|||'));
            }
          } catch(e) {}
        })();
      ''');
    } catch (_) {}

    if (_retryCount < 4) {
      Future.delayed(const Duration(seconds: 2), () {
        if (!_extracted && _foundIds.length < widget.count && mounted) {
          _controller
              .executeScript('window.scrollBy(0, 800);')
              .catchError((_) {});
          Future.delayed(const Duration(milliseconds: 800), _tryExtract);
        }
      });
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(children: [
      Container(
        color: const Color(0xFF1A1A2E),
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
        child: Row(children: [
          Container(
            width: 24,
            height: 24,
            decoration: const BoxDecoration(
                color: Color(0xFFE53935), shape: BoxShape.circle),
            child: const Icon(Icons.search, color: Colors.white, size: 14),
          ),
          const SizedBox(width: 8),
          Expanded(
              child: Text(
                  context
                      .read<MindMapProvider>()
                      .t('search.searching')
                      .replaceFirst('{kw}', widget.keyword)
                      .replaceFirst('{n}', '${widget.count}'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 13,
                      fontWeight: FontWeight.bold),
                  overflow: TextOverflow.ellipsis)),
          if (_loading)
            const SizedBox(
                width: 16,
                height: 16,
                child: CircularProgressIndicator(
                    strokeWidth: 2,
                    valueColor:
                        AlwaysStoppedAnimation<Color>(Color(0xFFE53935)))),
          IconButton(
            icon: const Icon(Icons.close, color: Colors.white54, size: 20),
            onPressed: () => Navigator.pop(context),
          ),
        ]),
      ),
      if (_loading && !_initialized)
        Expanded(
          child: Center(
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              CircularProgressIndicator(
                  valueColor: AlwaysStoppedAnimation<Color>(Color(0xFFE53935))),
              SizedBox(height: 12),
              Text(context.read<MindMapProvider>().t('webview.initializing'),
                  style: TextStyle(color: Colors.white54, fontSize: 12)),
            ]),
          ),
        )
      else if (_initialized)
        Expanded(
          child: Stack(children: [
            wv_win.Webview(
              _controller,
              permissionRequested: (url, kind, isUserInitiated) =>
                  wv_win.WebviewPermissionDecision.allow,
            ),
            if (_loading)
              const Positioned(
                top: 0,
                left: 0,
                right: 0,
                child: LinearProgressIndicator(
                    valueColor:
                        AlwaysStoppedAnimation<Color>(Color(0xFFE53935)),
                    backgroundColor: Colors.transparent),
              ),
          ]),
        ),
    ]);
  }
}

// ─── PC版（webview_windows）プレイリスト展開シート ────────────────────────────

class _WindowsPlaylistExtractSheet extends StatefulWidget {
  final List<String> urls;
  final String playlistId;
  final bool extractPageTitle;
  final void Function(List<String> videoIds, List<String> titles,
      String? pageTitle, List<int> viewCounts) onResults;
  const _WindowsPlaylistExtractSheet({
    required this.urls,
    required this.playlistId,
    required this.extractPageTitle,
    required this.onResults,
  });
  @override
  State<_WindowsPlaylistExtractSheet> createState() =>
      _WindowsPlaylistExtractSheetState();
}

class _WindowsPlaylistExtractSheetState
    extends State<_WindowsPlaylistExtractSheet> {
  final wv_win.WebviewController _controller = wv_win.WebviewController();
  bool _initialized = false;
  bool _loading = true;
  bool _finished = false;
  int _urlIndex = 0;
  // 全URLからの累積結果
  final List<String> _allIds = [];
  final List<String> _allTitles = [];
  final List<int> _allViewCounts = [];
  final Set<String> _seenIds = {};
  String? _pageTitle;

  Timer? _pollTimer;
  Timer? _safetyTimer;

  @override
  void initState() {
    super.initState();
    _initController();
    // 万一の無限待ち防止（WebView2側で詰まった時の保険）
    _safetyTimer = Timer(const Duration(seconds: 120), () {
      if (!_finished && mounted) _forceFinish();
    });
  }

  Future<void> _initController() async {
    // Linux: JS→Dart 不可でこのスクレイパ (プレイリスト抽出) は機能しない。
    //   既存の打ち切りロジック (_forceFinish) で即終了し、 ハングを防ぐ。
    if (Platform.isLinux) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _forceFinish();
      });
      return;
    }
    try {
      await _controller.initialize();
      _controller.loadingState.listen((state) {
        if (!mounted) return;
        setState(() => _loading = state == wv_win.LoadingState.loading);
        if (state == wv_win.LoadingState.navigationCompleted) {
          // 2秒待ってからJS側で全自動スクロール+抽出
          Future.delayed(const Duration(seconds: 2), _extractAll);
        }
      });
      // ページタイトル取得
      _controller.title.listen((t) {
        if (widget.extractPageTitle &&
            t != null &&
            t.isNotEmpty &&
            _pageTitle == null) {
          final clean = t
              .replaceAll(RegExp(r'\s*-\s*YouTube\s*$'), '')
              .replaceAll(RegExp(r'\s*-\s*Shorts\s*$'), '')
              .trim();
          if (clean.isNotEmpty) _pageTitle = clean;
        }
      });
      await _controller.loadUrl(widget.urls[_urlIndex]);
      if (mounted) setState(() => _initialized = true);
    } catch (_) {}
  }

  void _onExtracted(String encoded) {
    if (_finished) return;
    try {
      final parts = encoded.split('|||');
      for (final p in parts) {
        final kv = p.split(':::');
        if (kv.length >= 2 && kv[0].isNotEmpty) {
          if (_seenIds.add(kv[0])) {
            _allIds.add(kv[0]);
            _allTitles.add(kv[1].isEmpty ? 'Video' : kv[1]);
            _allViewCounts
                .add(kv.length >= 3 ? (int.tryParse(kv[2]) ?? -1) : -1);
          }
        }
      }
    } catch (_) {}
    _advanceOrFinish();
  }

  void _advanceOrFinish() {
    if (_finished) return;
    if (_urlIndex + 1 < widget.urls.length) {
      _urlIndex++;
      // 次URLに行く前にJS側のフラグを明示リセット
      _controller
          .executeScript(
            'window.__MM_PLAYLIST_RESULT__ = null;'
            'window.__MM_PLAYLIST_DONE__ = false;'
            'window.__MM_EXTRACT_RUNNING__ = false;',
          )
          .catchError((_) => null);
      _controller.loadUrl(widget.urls[_urlIndex]).catchError((_) {});
    } else {
      _forceFinish();
    }
  }

  void _forceFinish() {
    if (_finished) return;
    _finished = true;
    _pollTimer?.cancel();
    _pollTimer = null;
    _safetyTimer?.cancel();
    _safetyTimer = null;
    if (_allIds.isNotEmpty || _pageTitle != null) {
      widget.onResults(_allIds, _allTitles, _pageTitle, _allViewCounts);
    }
    if (mounted) Navigator.pop(context);
  }

  // ── JS 側の抽出完了をポーリングで拾う ────────────────────────────────────
  void _startPolling() {
    _pollTimer?.cancel();
    _pollTimer =
        Timer.periodic(const Duration(milliseconds: 500), (timer) async {
      if (_finished || !mounted) {
        timer.cancel();
        return;
      }
      try {
        final doneRaw = await _controller
            .executeScript('(window.__MM_PLAYLIST_DONE__===true)?1:0');
        if (_numFromJsResult(doneRaw) != 1) return;

        final payloadRaw = await _controller
            .executeScript('window.__MM_PLAYLIST_RESULT__||""');
        final payload = _stringFromJsResult(payloadRaw);

        timer.cancel();
        _pollTimer = null;
        _onExtracted(payload);
      } catch (_) {
        // 次のtickで再試行
      }
    });
  }

  /// webview_windows の executeScript は
  ///  - バージョン/環境によって「素の値」または「JSON 文字列」を返す
  /// どちらでも動くようにパースする
  static String _stringFromJsResult(dynamic r) {
    if (r == null) return '';
    if (r is String) {
      // "abc" のようにダブルクォートで囲まれていたら JSON デコード
      if (r.length >= 2 && r.startsWith('"') && r.endsWith('"')) {
        try {
          final decoded = jsonDecode(r);
          if (decoded is String) return decoded;
        } catch (_) {}
      }
      return r;
    }
    return r.toString();
  }

  static int _numFromJsResult(dynamic r) {
    if (r == null) return 0;
    if (r is num) return r.toInt();
    if (r is bool) return r ? 1 : 0;
    final s = r.toString().trim();
    if (s == 'true') return 1;
    if (s == 'false') return 0;
    return int.tryParse(s) ?? 0;
  }

  Future<void> _extractAll() async {
    if (_finished) return;
    try {
      await _controller.executeScript(r'''
        (function() {
          if (window.__MM_EXTRACT_RUNNING__) return;
          window.__MM_EXTRACT_RUNNING__ = true;
          window.__MM_PLAYLIST_RESULT__ = null;
          window.__MM_PLAYLIST_DONE__ = false;

          function countVideos() {
            var links = document.querySelectorAll('a[href*="/watch?v="], a[href*="/shorts/"]');
            var seen = {};
            var count = 0;
            for (var i = 0; i < links.length; i++) {
              var href = links[i].getAttribute('href') || '';
              if (href.indexOf('list=') !== -1 && href.indexOf('index=') === -1) continue;
              var vid = '';
              var m = href.match(/[?&]v=([a-zA-Z0-9_-]{11})/);
              if (m) vid = m[1];
              else {
                var ms = href.match(/\/shorts\/([a-zA-Z0-9_-]{11})/);
                if (ms) vid = ms[1];
              }
              if (!vid || seen[vid]) continue;
              seen[vid] = true;
              count++;
            }
            return count;
          }

          function scrollAll(cb) {
            var lastCount = 0;
            var stable = 0;
            var attempts = 0;
            var maxAttempts = 80;
            function step() {
              attempts++;
              try {
                var sh = Math.max(
                  document.body.scrollHeight,
                  document.documentElement.scrollHeight
                );
                window.scrollTo(0, sh);
                window.scrollBy(0, 3000);
              } catch(e) {}
              setTimeout(function() {
                var c = countVideos();
                if (c > lastCount) { lastCount = c; stable = 0; }
                else { stable++; }
                if (stable >= 5 || attempts >= maxAttempts) { cb(); return; }
                step();
              }, 700);
            }
            step();
          }

          function extractAll() {
            try {
              var links = document.querySelectorAll('a[href*="/watch?v="], a[href*="/shorts/"]');
              var seen = {};
              var results = [];
              for (var i = 0; i < links.length; i++) {
                var href = links[i].getAttribute('href') || '';
                if (href.indexOf('list=') !== -1 && href.indexOf('index=') === -1) continue;
                var vid = '';
                var m = href.match(/[?&]v=([a-zA-Z0-9_-]{11})/);
                if (m) vid = m[1];
                else {
                  var ms = href.match(/\/shorts\/([a-zA-Z0-9_-]{11})/);
                  if (ms) vid = ms[1];
                }
                if (!vid || seen[vid]) continue;
                seen[vid] = true;
                var title = '';
                var views = '-1';
                try {
                  var p = links[i].closest('ytd-playlist-video-renderer, ytd-compact-video-renderer, ytd-rich-item-renderer, ytd-rich-grid-media, ytd-grid-video-renderer, ytd-video-renderer, ytd-reel-item-renderer, ytm-shorts-lockup-view-model');
                  if (p) {
                    var h3 = p.querySelector('#video-title, #video-title-link, h3, .title');
                    if (h3) title = (h3.textContent || h3.getAttribute('title') || '').trim();
                    var metaEls = p.querySelectorAll('#metadata-line span, #metadata span, .inline-metadata-item, ytd-video-meta-block span, .style-scope.ytd-video-meta-block');
                    for (var j = 0; j < metaEls.length; j++) {
                      var txt = (metaEls[j].textContent || '').trim();
                      var vm = txt.match(/([\d,.]+)\s*(万|億|K|M|B)?\s*(回|views|view)/i);
                      if (vm) {
                        var num = parseFloat(vm[1].replace(/,/g, ''));
                        var unit = (vm[2] || '').toUpperCase();
                        if (unit === '万') num *= 10000;
                        else if (unit === '億') num *= 100000000;
                        else if (unit === 'K') num *= 1000;
                        else if (unit === 'M') num *= 1000000;
                        else if (unit === 'B') num *= 1000000000;
                        views = '' + Math.floor(num);
                        break;
                      }
                    }
                  }
                  if (!title) title = (links[i].getAttribute('aria-label') || links[i].getAttribute('title') || links[i].textContent || '').trim();
                } catch(e) {}
                results.push(vid + ':::' + title.substring(0, 55) + ':::' + views);
              }
              // ── フォールバック (= ユーザー要望: ちゃんと取得してこれる
              //    ように)。 DOM から 1 件も取れない時は初期データ JSON の
              //    "videoId" を直接拾う (タイトルは oEmbed で後追い補完)。 ──
              if (results.length === 0) {
                try {
                  var html = document.documentElement.innerHTML;
                  var re = /"videoId"\s*:\s*"([a-zA-Z0-9_-]{11})"/g;
                  var m2, seen2 = {};
                  while ((m2 = re.exec(html)) !== null && results.length < 200) {
                    var v2 = m2[1];
                    if (seen2[v2] || seen[v2]) continue;
                    seen2[v2] = true;
                    results.push(v2 + ':::' + '' + ':::' + '-1');
                  }
                } catch(e) {}
              }
              // URLスキームは長文だとWebView2が届けてくれないので、
              // グローバル変数に格納してFlutterからexecuteScriptで取得する
              window.__MM_PLAYLIST_RESULT__ = results.join('|||');
            } catch(e) {
              window.__MM_PLAYLIST_RESULT__ = '';
            } finally {
              window.__MM_PLAYLIST_DONE__ = true;
              window.__MM_EXTRACT_RUNNING__ = false;
            }
          }

          // ページタイトルを document.title に注入（Flutter側の listener が拾う）
          try {
            var nameEl = document.querySelector('ytd-channel-name #text, ytd-c4-tabbed-header-renderer #channel-name, [class*="channel-name"], meta[property="og:title"]');
            var name = '';
            if (nameEl) {
              name = (nameEl.getAttribute('content') || nameEl.textContent || '').trim();
            }
            if (!name) {
              var t = document.title || '';
              name = t.replace(/\s*-\s*YouTube\s*$/, '').replace(/\s*-\s*Shorts\s*$/, '').trim();
            }
            if (name) document.title = name + ' - YouTube';
          } catch(e) {}

          scrollAll(extractAll);
        })();
      ''');
      // JS 側の完了フラグを定期的に確認
      _startPolling();
    } catch (_) {}
  }

  @override
  void dispose() {
    _pollTimer?.cancel();
    _safetyTimer?.cancel();
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final progress = widget.urls.length > 1
        ? ' (${_urlIndex + 1}/${widget.urls.length})'
        : '';
    return Column(children: [
      Container(
        color: const Color(0xFF1A1A2E),
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
        child: Row(children: [
          Container(
            width: 24,
            height: 24,
            decoration: const BoxDecoration(
                color: Color(0xFFE53935), shape: BoxShape.circle),
            child: const Icon(Icons.playlist_play_rounded,
                color: Colors.white, size: 16),
          ),
          const SizedBox(width: 8),
          Expanded(
              child: Text(
                  '${context.read<MindMapProvider>().t('playlist.fetching')}$progress',
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 13,
                      fontWeight: FontWeight.bold))),
          if (_loading)
            const SizedBox(
                width: 16,
                height: 16,
                child: CircularProgressIndicator(
                    strokeWidth: 2,
                    valueColor:
                        AlwaysStoppedAnimation<Color>(Color(0xFFE53935)))),
          IconButton(
            icon: const Icon(Icons.close, color: Colors.white54, size: 20),
            onPressed: _forceFinish, // ← タイマーも確実に止めて閉じる
          ),
        ]),
      ),
      if (!_initialized)
        Expanded(
          child: Center(
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              CircularProgressIndicator(
                  valueColor: AlwaysStoppedAnimation<Color>(Color(0xFFE53935))),
              SizedBox(height: 12),
              Text(context.read<MindMapProvider>().t('webview.initializing'),
                  style: TextStyle(color: Colors.white54, fontSize: 12)),
            ]),
          ),
        )
      else
        Expanded(
          child: Stack(children: [
            wv_win.Webview(
              _controller,
              permissionRequested: (url, kind, isUserInitiated) =>
                  wv_win.WebviewPermissionDecision.allow,
            ),
            if (_loading)
              const Positioned(
                top: 0,
                left: 0,
                right: 0,
                child: LinearProgressIndicator(
                    valueColor:
                        AlwaysStoppedAnimation<Color>(Color(0xFFE53935)),
                    backgroundColor: Colors.transparent),
              ),
          ]),
        ),
    ]);
  }
}

// ─── ユーザー向け問い合わせダイアログ ───────────────────────────────────────────
class _InquiryDialog extends StatefulWidget {
  final MindMapProvider provider;
  const _InquiryDialog({required this.provider});
  @override
  State<_InquiryDialog> createState() => _InquiryDialogState();
}

class _InquiryDialogState extends State<_InquiryDialog> {
  int _tab = 0; // 0=送信フォーム, 1=過去の問い合わせ, 2=開発者専用
  final _msgCtrl = TextEditingController();
  bool _sending = false;
  String? _sentMsgId;
  List<Map<String, dynamic>>? _myInquiries;
  bool _loadingHistory = false;

  /// 問い合わせ種別: 'bug' (バグ報告) / 'feature' (機能依頼) / 'other' (その他)
  /// 送信時に message 先頭に [バグ報告] のようなプレフィックスが付与される。
  /// デフォルトは 'bug' (バグ報告) — 報告フローを優先したいユーザー意図に沿う。
  String _category = 'bug';

  // (旧 開発者専用タブ用フィールドは削除しました 2026-05。
  //  開発者モード突入は設定画面側に集約)

  // 送信エラーメッセージ
  String? _sendError;

  // 1 日あたりの残り送信回数 (ローカル計測)
  int? _remainingSends;

  @override
  void initState() {
    super.initState();
    _refreshRemaining();
  }

  Future<void> _refreshRemaining() async {
    final n = await widget.provider.remainingInquirySendCount();
    if (!mounted) return;
    setState(() => _remainingSends = n);
  }

  /// 開発者モードで設定された連絡先メールアドレス (admin/settings.inquiryEmail)
  /// を mailto: で開いて、送信内容のコピーが届くようにする。
  ///
  /// クライアントから直接 SMTP 送信する手段は無いため、ユーザーの標準
  /// メールアプリを起動して件名・本文を埋めた状態で開く。ユーザーが
  /// 送信ボタンを押すと開発者宛にメールが届く。
  ///
  /// 失敗 (mailto: ハンドラ無し等) は無視。Firestore には既に保存済みなので
  /// 受信ボックス経由でも開発者は内容を確認できる。
  Future<void> _openMailtoForwardIfNeeded(
      String message, String categoryLabel) async {
    final email = widget.provider.inquiryEmail.trim();
    if (email.isEmpty) return;
    final senderName = widget.provider.displayName.trim();
    final subject = '[${widget.provider.t('app.title')}] $categoryLabel'
        '${senderName.isNotEmpty ? ' - $senderName' : ''}';
    // mailto: で渡す URI はパーセントエンコードが必須。
    // Uri コンストラクタの queryParameters は + 区切りになり改行が壊れるため、
    // 自前で `Uri.encodeComponent` する。
    final body = message;
    final uri = Uri.parse(
      'mailto:$email'
      '?subject=${Uri.encodeComponent(subject)}'
      '&body=${Uri.encodeComponent(body)}',
    );
    try {
      await launchUrl(uri, mode: LaunchMode.externalApplication);
    } catch (e) {
      debugPrint('mailto 起動失敗 (無視): $e');
    }
  }

  @override
  void dispose() {
    _msgCtrl.dispose();
    super.dispose();
  }

  Future<void> _submit() async {
    if (_msgCtrl.text.trim().isEmpty) return;
    // ── ユーザー名 (displayName) 未設定の事前チェック ──
    // provider 側でも例外で弾かれるが、ここで事前にチェックして
    // 「送信エラー」表示ではなく「ユーザー名設定ダイアログ」を出す動線にする。
    if (widget.provider.displayName.trim().isEmpty) {
      // 親 State 側のメソッドを直接呼べないので、SnackBar で案内 + 設定誘導
      _appSnack(
          context,
          SnackBar(
            content: Text(widget.provider.t('msg.displayNameRequired')),
            backgroundColor: const Color(0xFFE53935),
            action: SnackBarAction(
              label: widget.provider.t('msg.openNameSetting'),
              textColor: Colors.white,
              onPressed: () {
                // 設定シートのユーザー名項目に飛ばすのではなく、Provider の
                // displayName をその場で入力してもらうための簡易ダイアログを表示。
                _showInlineDisplayNameDialog();
              },
            ),
            duration: const Duration(seconds: 5),
          ));
      return;
    }
    setState(() {
      _sending = true;
      _sendError = null;
    });
    try {
      // ── カテゴリプレフィックスを message 先頭に付与 ──
      // 受信ボックス側で「バグ報告」「機能依頼」を一目で判別できる
      // ようにする。「その他」も明示的に印字しておく。
      final String categoryKey;
      if (_category == 'feature') {
        categoryKey = 'inquiry.category.feature';
      } else if (_category == 'other') {
        categoryKey = 'inquiry.category.other';
      } else {
        categoryKey = 'inquiry.category.bug';
      }
      final categoryLabel = widget.provider.t(categoryKey);
      final messageWithCategory = '[$categoryLabel] ${_msgCtrl.text.trim()}';

      final id = await widget.provider.sendInquiry(messageWithCategory);
      if (!mounted) return;
      setState(() {
        _sending = false;
        _sentMsgId = id;
        _msgCtrl.clear();
        _sendError = null;
      });
      await _refreshRemaining();
      // ── 開発者メールアドレスへ mailto: で転送 (best-effort) ──
      // admin/settings.inquiryEmail が設定されている場合のみ起動する。
      // 端末にメールクライアントが無い等の理由で失敗しても、Firestore へは
      // 既に書き込み済みなので問題なくスルーする。
      _openMailtoForwardIfNeeded(messageWithCategory, categoryLabel);
    } catch (e) {
      if (!mounted) return;
      // displayName 未設定例外をキャッチした場合 (= レアケース、UI 側
      // チェックを通り抜けたケース): 即座にダイアログで誘導する。
      if (isDisplayNameRequiredError(e)) {
        setState(() => _sending = false);
        _showInlineDisplayNameDialog();
        return;
      }
      // レート制限の Exception はそのままユーザー向けメッセージなので
      // "Exception: " プレフィックスを除去して表示する。
      final raw = e.toString();
      final rateMsg = widget.provider.t('inquiry.rateLimit');
      final isRateLimit = raw.contains(rateMsg);
      setState(() {
        _sending = false;
        if (isRateLimit) {
          _sendError = rateMsg;
        } else {
          _sendError =
              'Firestoreへの送信に失敗しました。\nFirebaseの設定やルールを確認してください。\n詳細: $e';
        }
      });
      await _refreshRemaining();
    }
  }

  /// 送信時にユーザー名が未設定だった場合に出す簡易ダイアログ。
  /// 入力 → 保存 → そのまま送信ボタン側へ戻る (ユーザーが再度送信すれば成功)。
  void _showInlineDisplayNameDialog() {
    final nameCtrl = TextEditingController(text: widget.provider.displayName);
    showDialog<void>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        title: Row(children: [
          const Icon(Icons.account_circle_rounded,
              color: Color(0xFF4FC3F7), size: 22),
          const SizedBox(width: 8),
          Expanded(
            child: Text(widget.provider.t('msg.displayNameRequired'),
                style: const TextStyle(color: Colors.white, fontSize: 14)),
          ),
        ]),
        content: TextField(
          controller: nameCtrl,
          autofocus: true,
          maxLength: 30,
          style: const TextStyle(color: Colors.white, fontSize: 14),
          decoration: InputDecoration(
            hintText: widget.provider.t('msg.displayNameHint'),
            hintStyle: const TextStyle(color: Colors.white38),
            labelText: widget.provider.t('msg.displayNameLabel'),
            labelStyle: const TextStyle(color: Colors.white70),
            filled: true,
            fillColor: Colors.white10,
            counterStyle: const TextStyle(color: Colors.white38),
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(10),
              borderSide: BorderSide.none,
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(widget.provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white60)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF4FC3F7),
                foregroundColor: Color(0xFF10241F),),
            onPressed: () async {
              final name = nameCtrl.text.trim();
              if (name.isEmpty) return;
              await widget.provider.setDisplayName(name);
              if (dctx.mounted) Navigator.pop(dctx);
            },
            child: Text(widget.provider.t('msg.saveBtn'),
                style: const TextStyle(
                    color: Colors.white, fontWeight: FontWeight.w700)),
          ),
        ],
      ),
    );
  }

  Future<void> _loadHistory() async {
    setState(() => _loadingHistory = true);
    try {
      final list = await widget.provider.fetchMyInquiries();
      if (!mounted) return;
      setState(() {
        _myInquiries = list;
        _loadingHistory = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() => _loadingHistory = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final provider = widget.provider;
    return AlertDialog(
      backgroundColor: const Color(0xFF1E1E2E),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      title: Row(children: [
        const Icon(Icons.email_rounded, color: Color(0xFF4FC3F7), size: 20),
        const SizedBox(width: 8),
        Text(provider.t('inquiry.title'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        const Spacer(),
        IconButton(
          icon: const Icon(Icons.close, color: Colors.white54, size: 18),
          onPressed: () => Navigator.pop(context),
        ),
      ]),
      content: SizedBox(
        width: 380,
        height: 440,
        child: Column(children: [
          // タブ: 開発者モード時は「お問い合わせ」(タブ1)が全ユーザー一覧
          // モードに変わる。開発者モード突入は設定画面側に集約したので、
          // このダイアログ内のパスワード認証タブは廃止 (2026-05)。
          Row(children: [
            _tabBtn(provider.t('inquiry.tabNew'), 0),
            const SizedBox(width: 6),
            widget.provider.developerMode
                ? _tabBtn(provider.t('inquiry.tabHistory'), 1,
                    icon: Icons.inbox_rounded, color: const Color(0xFFFFB347))
                : _tabBtn(provider.t('inquiry.tabHistory'), 1),
            const Spacer(),
            // ── 開発者の Instagram (= ユーザー要望: リンクを貼っておく) ──
            InkWell(
              onTap: () => launchUrl(
                  Uri.parse('https://www.instagram.com/study_darksan'),
                  mode: LaunchMode.externalApplication),
              borderRadius: BorderRadius.circular(20),
              // 周りのボタンと同じ白字にする (= ユーザー要望: 1 つだけ
              //   桃色で浮いていた)。 表記も「公式Ig」 に短くする。
              child: Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(20),
                  border: Border.all(color: Colors.white24),
                ),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  const Icon(Icons.photo_camera_rounded,
                      color: Colors.white70, size: 12),
                  const SizedBox(width: 4),
                  Text(provider.t('inquiry.officialIg'),
                      style: const TextStyle(
                          color: Colors.white70,
                          fontSize: 11,
                          fontWeight: FontWeight.w600)),
                ]),
              ),
            ),
          ]),
          const SizedBox(height: 14),
          Expanded(
            child: _tab == 0
                ? _buildForm()
                // 開発者モード: 全ユーザー問い合わせ一覧+返信 / 通常: 自分の履歴
                : (widget.provider.developerMode
                    ? _buildDevHistory()
                    : _buildHistory()),
          ),
        ]),
      ),
    );
  }

  Widget _tabBtn(String label, int idx, {IconData? icon, Color? color}) {
    final selected = _tab == idx;
    final c = color ?? const Color(0xFF4FC3F7);
    return GestureDetector(
      onTap: () {
        setState(() => _tab = idx);
        if (idx == 1 && _myInquiries == null) _loadHistory();
      },
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
        decoration: BoxDecoration(
          color: selected ? c.withValues(alpha: 0.15) : Colors.transparent,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(color: selected ? c : Colors.white24),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          if (icon != null) ...[
            Icon(icon, color: selected ? c : Colors.white38, size: 12),
            const SizedBox(width: 4),
          ],
          Text(label,
              style: TextStyle(
                  color: selected ? c : Colors.white54,
                  fontSize: 11,
                  fontWeight: FontWeight.w600)),
        ]),
      ),
    );
  }

  /// 問い合わせ種別を選択するチップ。タップで `_category` を更新。
  Widget _categoryChip({
    required String value,
    required String label,
    required IconData icon,
    required Color activeColor,
  }) {
    final selected = _category == value;
    return GestureDetector(
      onTap: () => setState(() => _category = value),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 120),
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
        decoration: BoxDecoration(
          color: selected
              ? activeColor.withValues(alpha: 0.18)
              : Colors.transparent,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
              color: selected ? activeColor : Colors.white24, width: 1),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          Icon(icon, color: selected ? activeColor : Colors.white54, size: 13),
          const SizedBox(width: 5),
          Text(label,
              style: TextStyle(
                  color: selected ? activeColor : Colors.white54,
                  fontSize: 11,
                  fontWeight: FontWeight.w700)),
        ]),
      ),
    );
  }

  Widget _buildForm() {
    if (_sentMsgId != null) {
      return Center(
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          const Icon(Icons.check_circle_rounded,
              color: Color(0xFF43B97F), size: 48),
          const SizedBox(height: 12),
          Text(widget.provider.t('inq.sent'),
              style: TextStyle(
                  color: Colors.white,
                  fontSize: 16,
                  fontWeight: FontWeight.w600)),
          const SizedBox(height: 8),
          Text(widget.provider.t('inq.checkHistory'),
              style: TextStyle(color: Colors.white54, fontSize: 12),
              textAlign: TextAlign.center),
          const SizedBox(height: 20),
          TextButton(
            onPressed: () => setState(() => _sentMsgId = null),
            child: Text(widget.provider.t('inquiry.continueBtn'),
                style: const TextStyle(color: Color(0xFF4FC3F7))),
          ),
        ]),
      );
    }
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      // ── カテゴリ選択 (バグ報告 / 機能依頼 / その他) ──
      // 送信時に message 先頭にプレフィックスとして付与される。
      Text(widget.provider.t('inquiry.category.label'),
          style: const TextStyle(color: Colors.white54, fontSize: 12)),
      const SizedBox(height: 6),
      Wrap(spacing: 6, runSpacing: 6, children: [
        _categoryChip(
          value: 'bug',
          label: widget.provider.t('inquiry.category.bug'),
          icon: Icons.bug_report_rounded,
          activeColor: const Color(0xFFE57373),
        ),
        _categoryChip(
          value: 'feature',
          label: widget.provider.t('inquiry.category.feature'),
          icon: Icons.lightbulb_rounded,
          activeColor: const Color(0xFFFFB347),
        ),
        _categoryChip(
          value: 'other',
          label: widget.provider.t('inquiry.category.other'),
          icon: Icons.chat_bubble_outline_rounded,
          activeColor: const Color(0xFF4FC3F7),
        ),
      ]),
      const SizedBox(height: 12),
      Text(widget.provider.t('inquiry.messageLabel'),
          style: const TextStyle(color: Colors.white54, fontSize: 12)),
      const SizedBox(height: 6),
      Expanded(
        child: TextField(
          controller: _msgCtrl,
          maxLines: null,
          expands: true,
          style: const TextStyle(color: Colors.white, fontSize: 13),
          textAlignVertical: TextAlignVertical.top,
          decoration: InputDecoration(
            hintText: widget.provider.t('inquiry.messageHint'),
            hintStyle: const TextStyle(color: Colors.white24, fontSize: 12),
            filled: true,
            fillColor: Colors.white.withValues(alpha: 0.05),
            border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(10),
                borderSide: BorderSide.none),
            contentPadding: const EdgeInsets.all(12),
          ),
        ),
      ),
      const SizedBox(height: 12),
      if (_sendError != null)
        Container(
          width: double.infinity,
          margin: const EdgeInsets.only(bottom: 8),
          padding: const EdgeInsets.all(10),
          decoration: BoxDecoration(
            color: Colors.redAccent.withValues(alpha: 0.1),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: Colors.redAccent.withValues(alpha: 0.4)),
          ),
          child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Icon(Icons.error_outline_rounded,
                color: Colors.redAccent, size: 14),
            const SizedBox(width: 6),
            Expanded(
              child: Text(_sendError!,
                  style:
                      const TextStyle(color: Colors.redAccent, fontSize: 11)),
            ),
          ]),
        ),
      // ── 1 日あたりの残り送信回数表示 ──
      // 0 件まで減ったら警告色で表示してユーザーに気づかせる。
      // -1 は開発者モードによる無制限を意味する (∞ 表示)。
      if (_remainingSends != null)
        Padding(
          padding: const EdgeInsets.only(bottom: 6),
          child: Row(children: [
            Icon(Icons.timelapse_rounded,
                size: 12,
                color: (_remainingSends! == 0)
                    ? Colors.redAccent
                    : Colors.white38),
            const SizedBox(width: 4),
            Text(
              widget.provider.t('inquiry.rateLimitRemaining').replaceAll(
                  '{n}', _remainingSends! < 0 ? '∞' : '$_remainingSends'),
              style: TextStyle(
                  color: (_remainingSends! == 0)
                      ? Colors.redAccent
                      : Colors.white38,
                  fontSize: 11),
            ),
          ]),
        ),
      SizedBox(
        width: double.infinity,
        child: ElevatedButton.icon(
          style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFF4FC3F7),
              foregroundColor: Color(0xFF10241F),
              disabledBackgroundColor:
                  const Color(0xFF4FC3F7).withValues(alpha: 0.3),
              padding: const EdgeInsets.symmetric(vertical: 12)),
          icon: _sending
              ? const SizedBox(
                  width: 16,
                  height: 16,
                  child: CircularProgressIndicator(
                      strokeWidth: 2, color: Colors.black87))
              : const Icon(Icons.send_rounded, size: 16, color: Colors.black87),
          label: Text(
              _sending
                  ? widget.provider.t('inquiry.sending')
                  : widget.provider.t('inquiry.sendBtn'),
              style: const TextStyle(
                  color: Colors.black87, fontWeight: FontWeight.w700)),
          // 残量 0 の時だけ送信不可。-1 (無制限) は OK。
          onPressed: (_sending || _remainingSends == 0) ? null : _submit,
        ),
      ),
    ]);
  }

  // 開発者モード用: 全ユーザーの問い合わせ一覧 + 返信機能（インライン）
  Widget _buildDevHistory() {
    return _DevHistoryInlineView(provider: widget.provider);
  }

  Widget _buildHistory() {
    if (_loadingHistory) {
      return const Center(
          child: CircularProgressIndicator(color: Color(0xFF4FC3F7)));
    }
    if (_myInquiries == null || _myInquiries!.isEmpty) {
      return Center(
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Icon(Icons.inbox_rounded, color: Colors.white24, size: 40),
          SizedBox(height: 8),
          Text(widget.provider.t('inq.noHistory'),
              style: TextStyle(color: Colors.white38, fontSize: 13)),
        ]),
      );
    }
    return ListView.builder(
      itemCount: _myInquiries!.length,
      itemBuilder: (_, i) {
        final inq = _myInquiries![i];
        final ts = inq['timestamp'] as String? ?? '';
        final dt = DateTime.tryParse(ts)?.toLocal();
        final dtStr = dt != null
            ? '${dt.year}/${dt.month.toString().padLeft(2, '0')}/${dt.day.toString().padLeft(2, '0')} ${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}'
            : '';
        final reply = inq['reply'] as String? ?? '';
        final hasReply = reply.isNotEmpty;
        final replyTs = inq['replyTimestamp'] as String? ?? '';
        final replyDt = DateTime.tryParse(replyTs)?.toLocal();
        final replyDtStr = replyDt != null
            ? '${replyDt.year}/${replyDt.month.toString().padLeft(2, '0')}/${replyDt.day.toString().padLeft(2, '0')} ${replyDt.hour.toString().padLeft(2, '0')}:${replyDt.minute.toString().padLeft(2, '0')}'
            : '';

        return Container(
          margin: const EdgeInsets.only(bottom: 10),
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: Colors.white.withValues(alpha: 0.05),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(
                color: hasReply
                    ? const Color(0xFF43B97F).withValues(alpha: 0.4)
                    : Colors.white.withValues(alpha: 0.08)),
          ),
          child:
              Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Row(children: [
              Icon(Icons.chat_bubble_outline_rounded,
                  color: Colors.white38, size: 14),
              const SizedBox(width: 6),
              Text(widget.provider.t('inq.sentAt').replaceFirst('{dt}', dtStr),
                  style: const TextStyle(color: Colors.white38, fontSize: 11)),
              const Spacer(),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                decoration: BoxDecoration(
                  color: hasReply
                      ? const Color(0xFF43B97F).withValues(alpha: 0.2)
                      : Colors.white.withValues(alpha: 0.08),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Text(
                  hasReply ? '返信あり' : '未返信',
                  style: TextStyle(
                      color:
                          hasReply ? const Color(0xFF43B97F) : Colors.white38,
                      fontSize: 10,
                      fontWeight: FontWeight.w600),
                ),
              ),
            ]),
            const SizedBox(height: 6),
            Text(inq['message'] as String? ?? '',
                style: const TextStyle(color: Colors.white, fontSize: 13)),
            if (hasReply) ...[
              const SizedBox(height: 10),
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: const Color(0xFF43B97F).withValues(alpha: 0.08),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                      color: const Color(0xFF43B97F).withValues(alpha: 0.3)),
                ),
                child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(children: [
                        const Icon(Icons.reply_rounded,
                            color: Color(0xFF43B97F), size: 14),
                        const SizedBox(width: 4),
                        Text(
                            widget.provider
                                .t('inq.devReply')
                                .replaceFirst('{dt}', replyDtStr),
                            style: const TextStyle(
                                color: Color(0xFF43B97F),
                                fontSize: 11,
                                fontWeight: FontWeight.w600)),
                      ]),
                      const SizedBox(height: 4),
                      Text(reply,
                          style: const TextStyle(
                              color: Colors.white, fontSize: 13)),
                    ]),
              ),
            ],
            // ── アクション (返信を続ける / 削除) ──
            // ユーザー要望「開発者とやり取りできるようにして」 への対応。
            // 開発者から返信が来ている項目には「返信する」 ボタンを出し、
            // タップで送信フォーム (tab 0) に切り替えて会話を続けられるように
            // する。 (送信は新規の問い合わせとして届くが、 開発者側の受信箱は
            // 同一ユーザーの履歴をまとめて見られるので会話として成立する)
            const SizedBox(height: 4),
            Row(
              mainAxisAlignment: MainAxisAlignment.end,
              children: [
                if (hasReply)
                  TextButton.icon(
                    style: TextButton.styleFrom(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 8, vertical: 4),
                        minimumSize: Size.zero,
                        tapTargetSize: MaterialTapTargetSize.shrinkWrap),
                    icon: const Icon(Icons.reply_rounded,
                        color: Color(0xFF4FC3F7), size: 14),
                    label: Text(widget.provider.t('inq.reply'),
                        style:
                            TextStyle(color: Color(0xFF4FC3F7), fontSize: 11)),
                    onPressed: () {
                      setState(() {
                        _tab = 0; // 送信フォームへ
                        _category = 'other';
                      });
                    },
                  ),
                const Spacer(),
                TextButton.icon(
                  style: TextButton.styleFrom(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 8, vertical: 4),
                      minimumSize: Size.zero,
                      tapTargetSize: MaterialTapTargetSize.shrinkWrap),
                  icon: const Icon(Icons.delete_outline_rounded,
                      color: Colors.white24, size: 13),
                  label: Text(widget.provider.t('btn.delete'),
                      style: TextStyle(color: Colors.white24, fontSize: 11)),
                  onPressed: () async {
                    final msgId = inq['id'] as String;
                    final ok = await widget.provider.deleteMyInquiry(msgId);
                    if (!mounted) return;
                    if (ok) {
                      setState(() => _myInquiries!.removeAt(i));
                    }
                  },
                ),
              ],
            ),
          ]),
        );
      },
    );
  }
}

// ─── 開発者向け受信箱ダイアログ ────────────────────────────────────────────────
class _DevInboxDialog extends StatefulWidget {
  final MindMapProvider provider;
  const _DevInboxDialog({required this.provider});
  @override
  State<_DevInboxDialog> createState() => _DevInboxDialogState();
}

class _DevInboxDialogState extends State<_DevInboxDialog> {
  List<Map<String, dynamic>>? _inquiries;
  bool _loading = true;
  String? _error;
  String? _replyingId;
  final _replyCtrl = TextEditingController();

  /// 今「送信を止めている」 人の uid (= ユーザー要望: スパム判定した人を
  /// 個別に送信不可にする)。 一覧を読んだ時にまとめて確かめる。
  final Set<String> _blockedUids = {};

  @override
  void initState() {
    super.initState();
    _load();
  }

  /// 一覧に出ている送信者が止められているかを調べる。
  Future<void> _refreshBlocked() async {
    final uids = <String>{
      for (final e in (_inquiries ?? const <Map<String, dynamic>>[]))
        if ((e['uid'] as String? ?? '').isNotEmpty) e['uid'] as String,
    };
    final blocked = <String>{};
    for (final u in uids) {
      if (await widget.provider.isUidInquiryBlocked(u)) blocked.add(u);
    }
    if (!mounted) return;
    setState(() {
      _blockedUids
        ..clear()
        ..addAll(blocked);
    });
  }

  /// その人の送信を止める / 戻す。 止める時は理由を聞く (本人に見せる)。
  Future<void> _toggleBlock(String uid) async {
    final provider = widget.provider;
    final nowBlocked = _blockedUids.contains(uid);
    var reason = '';
    if (!nowBlocked) {
      final ctrl = TextEditingController();
      final ok = await showDialog<bool>(
        context: context,
        builder: (dctx) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Text(provider.t('inquiry.blockUser'),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
          content: TextField(
            controller: ctrl,
            autofocus: true,
            style: const TextStyle(color: Colors.white, fontSize: 13),
            decoration: InputDecoration(
              hintText: provider.t('inquiry.blockReasonHint'),
              hintStyle: const TextStyle(color: Colors.white24, fontSize: 12),
              filled: true,
              fillColor: const Color(0xFF15152A),
              border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(8),
                  borderSide: BorderSide.none),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(false),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFE57373),
                  foregroundColor: Colors.black),
              onPressed: () => Navigator.of(dctx).pop(true),
              child: Text(provider.t('inquiry.blockUser')),
            ),
          ],
        ),
      );
      // ★ 捨てる前に読む (捨てた後の .text は例外になる)。
      reason = ctrl.text.trim();
      ctrl.dispose();
      if (ok != true) return;
    }
    final ok =
        await provider.setInquiryBlocked(uid, !nowBlocked, reason: reason);
    if (!mounted) return;
    if (ok) {
      setState(() {
        if (nowBlocked) {
          _blockedUids.remove(uid);
        } else {
          _blockedUids.add(uid);
        }
      });
    }
  }

  @override
  void dispose() {
    _replyCtrl.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final list = await widget.provider.fetchAllInquiries();
      if (!mounted) return;
      setState(() {
        _inquiries = list;
        _loading = false;
      });
      // 誰を止めているかも合わせて調べる (= ユーザー要望の送信停止表示)。
      unawaited(_refreshBlocked());
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _error = e.toString();
        _loading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      backgroundColor: const Color(0xFF0D0D1A),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      title: Row(children: [
        const Icon(Icons.inbox_rounded, color: Color(0xFFFFB347), size: 20),
        const SizedBox(width: 8),
        Text(
          '受信箱 ${_inquiries != null ? "(${_inquiries!.length}件)" : ""}',
          style: const TextStyle(color: Colors.white, fontSize: 16),
        ),
        const Spacer(),
        IconButton(
          icon: const Icon(Icons.refresh_rounded,
              color: Colors.white54, size: 18),
          onPressed: _load,
          tooltip: widget.provider.t('btn.refresh'),
        ),
        IconButton(
          icon: const Icon(Icons.close, color: Colors.white54, size: 18),
          onPressed: () => Navigator.pop(context),
        ),
      ]),
      content: SizedBox(
        width: 500,
        height: 560,
        child: _loading
            ? const Center(
                child: CircularProgressIndicator(color: Color(0xFFFFB347)))
            : _error != null
                ? Center(
                    child: Text(_error!,
                        style: const TextStyle(
                            color: Colors.redAccent, fontSize: 12)))
                : _inquiries == null || _inquiries!.isEmpty
                    ? Center(
                        child:
                            Column(mainAxisSize: MainAxisSize.min, children: [
                        Icon(Icons.inbox_rounded,
                            color: Colors.white24, size: 48),
                        SizedBox(height: 10),
                        Text(widget.provider.t('inq.noInquiries'),
                            style:
                                TextStyle(color: Colors.white38, fontSize: 14)),
                      ]))
                    : ListView.builder(
                        itemCount: _inquiries!.length,
                        itemBuilder: (_, i) => _buildItem(i),
                      ),
      ),
    );
  }

  Widget _buildItem(int i) {
    final inq = _inquiries![i];
    final msgId = inq['id'] as String;
    final ts = inq['timestamp'] as String? ?? '';
    final dt = DateTime.tryParse(ts)?.toLocal();
    final dtStr = dt != null
        ? '${dt.year}/${dt.month.toString().padLeft(2, '0')}/${dt.day.toString().padLeft(2, '0')} ${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}'
        : '';
    final reply = inq['reply'] as String? ?? '';
    final hasReply = reply.isNotEmpty;
    final status = inq['status'] as String? ?? 'open';
    final isReplying = _replyingId == msgId;
    final uid = inq['uid'] as String? ?? '';

    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.04),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(
            color: hasReply
                ? const Color(0xFF43B97F).withValues(alpha: 0.3)
                : Colors.white.withValues(alpha: 0.08)),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        // ヘッダー
        Row(children: [
          Icon(Icons.person_rounded, color: Colors.white38, size: 14),
          const SizedBox(width: 4),
          Expanded(
            child: Text(uid.length > 12 ? '${uid.substring(0, 8)}...' : uid,
                style: const TextStyle(
                    color: Colors.white38,
                    fontSize: 11,
                    fontFamily: 'monospace')),
          ),
          Text(dtStr,
              style: const TextStyle(color: Colors.white24, fontSize: 10)),
          // 送信を止めている人が一目で分かるように (= ユーザー要望)。
          if (_blockedUids.contains(uid)) ...[
            const SizedBox(width: 6),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
              decoration: BoxDecoration(
                color: const Color(0xFFE57373).withValues(alpha: 0.18),
                borderRadius: BorderRadius.circular(8),
              ),
              child: Text(widget.provider.t('inquiry.blockedBadge'),
                  style: const TextStyle(
                      color: Color(0xFFE57373),
                      fontSize: 10,
                      fontWeight: FontWeight.w700)),
            ),
          ],
          const SizedBox(width: 8),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
            decoration: BoxDecoration(
              color: hasReply
                  ? const Color(0xFF43B97F).withValues(alpha: 0.2)
                  : const Color(0xFFFFB347).withValues(alpha: 0.15),
              borderRadius: BorderRadius.circular(8),
            ),
            child: Text(
              status == 'replied' ? '返信済' : '未返信',
              style: TextStyle(
                  color: status == 'replied'
                      ? const Color(0xFF43B97F)
                      : const Color(0xFFFFB347),
                  fontSize: 10,
                  fontWeight: FontWeight.w700),
            ),
          ),
        ]),
        const SizedBox(height: 8),

        // メッセージ本文
        Container(
          width: double.infinity,
          padding: const EdgeInsets.all(10),
          decoration: BoxDecoration(
            color: Colors.white.withValues(alpha: 0.04),
            borderRadius: BorderRadius.circular(8),
          ),
          child: Text(inq['message'] as String? ?? '',
              style: const TextStyle(color: Colors.white, fontSize: 13)),
        ),

        // 既存の返信
        if (hasReply) ...[
          const SizedBox(height: 8),
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              color: const Color(0xFF43B97F).withValues(alpha: 0.08),
              borderRadius: BorderRadius.circular(8),
              border: Border.all(
                  color: const Color(0xFF43B97F).withValues(alpha: 0.3)),
            ),
            child:
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                const Icon(Icons.reply_rounded,
                    color: Color(0xFF43B97F), size: 14),
                const SizedBox(width: 4),
                Text(widget.provider.t('inq.yourReply'),
                    style: const TextStyle(
                        color: Color(0xFF43B97F),
                        fontSize: 11,
                        fontWeight: FontWeight.w600)),
              ]),
              const SizedBox(height: 4),
              Text(reply,
                  style: const TextStyle(color: Colors.white, fontSize: 13)),
            ]),
          ),
        ],

        // 返信フォーム（開閉式）
        if (isReplying) ...[
          const SizedBox(height: 10),
          TextField(
            controller: _replyCtrl,
            maxLines: 3,
            autofocus: true,
            style: const TextStyle(color: Colors.white, fontSize: 13),
            decoration: InputDecoration(
              hintText: widget.provider.t('inq.replyHint'),
              hintStyle: const TextStyle(color: Colors.white24, fontSize: 12),
              filled: true,
              fillColor: Colors.white.withValues(alpha: 0.05),
              border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(8),
                  borderSide: BorderSide.none),
              contentPadding: const EdgeInsets.all(10),
            ),
          ),
          const SizedBox(height: 8),
          Row(children: [
            TextButton(
              onPressed: () => setState(() {
                _replyingId = null;
                _replyCtrl.clear();
              }),
              child: Text(widget.provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white38)),
            ),
            const Spacer(),
            ElevatedButton.icon(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF43B97F),
                  foregroundColor: Colors.white,
                  padding:
                      const EdgeInsets.symmetric(horizontal: 16, vertical: 8)),
              icon:
                  const Icon(Icons.send_rounded, size: 14, color: Colors.white),
              label: Text(widget.provider.t('inq.sendReply'),
                  style: const TextStyle(color: Colors.white)),
              onPressed: () async {
                if (_replyCtrl.text.trim().isEmpty) return;
                final ok = await widget.provider
                    .replyToInquiry(msgId, _replyCtrl.text);
                if (!mounted) return;
                if (ok) {
                  setState(() {
                    _inquiries![i]['reply'] = _replyCtrl.text;
                    _inquiries![i]['status'] = 'replied';
                    _replyingId = null;
                  });
                  _replyCtrl.clear();
                  _appSnack(
                    context,
                    SnackBar(
                        content: Text(widget.provider.t('inq.replySent')),
                        backgroundColor: Color(0xFF43B97F)),
                  );
                } else {
                  _appSnack(
                    context,
                    SnackBar(
                        content: Text(widget.provider.t('inq.replyFailed')),
                        backgroundColor: Colors.redAccent),
                  );
                }
              },
            ),
          ]),
        ] else ...[
          const SizedBox(height: 8),
          Row(children: [
            TextButton.icon(
              style: TextButton.styleFrom(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 10, vertical: 6)),
              icon: const Icon(Icons.reply_rounded,
                  size: 14, color: Color(0xFF4FC3F7)),
              label: Text(hasReply ? '返信を編集' : '返信する',
                  style:
                      const TextStyle(color: Color(0xFF4FC3F7), fontSize: 12)),
              onPressed: () => setState(() {
                _replyingId = msgId;
                _replyCtrl.text = reply;
              }),
            ),
            // ── 迷惑な送信者を止める / 戻す (= ユーザー要望: スパムと
            //    判断した人には個別で送信不可にできるように) ──
            TextButton.icon(
              style: TextButton.styleFrom(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 10, vertical: 6)),
              icon: Icon(
                  _blockedUids.contains(uid)
                      ? Icons.lock_open_rounded
                      : Icons.block_rounded,
                  size: 14,
                  color: _blockedUids.contains(uid)
                      ? const Color(0xFF43B97F)
                      : const Color(0xFFE57373)),
              label: Text(
                  widget.provider.t(_blockedUids.contains(uid)
                      ? 'inquiry.unblockUser'
                      : 'inquiry.blockUser'),
                  style: TextStyle(
                      color: _blockedUids.contains(uid)
                          ? const Color(0xFF43B97F)
                          : const Color(0xFFE57373),
                      fontSize: 12)),
              onPressed: uid.isEmpty ? null : () => unawaited(_toggleBlock(uid)),
            ),
            const Spacer(),
            IconButton(
              icon: const Icon(Icons.delete_rounded,
                  color: Colors.white24, size: 16),
              tooltip: widget.provider.t('btn.delete'),
              onPressed: () async {
                final ok = await widget.provider.deleteInquiry(msgId);
                if (!mounted) return;
                if (ok) {
                  setState(() => _inquiries!.removeAt(i));
                }
              },
            ),
          ]),
        ],
      ]),
    );
  }
}

// ─── 複数ノード一括編集シート ──────────────────────────────────────────────────
class _BulkEditSheet extends StatefulWidget {
  final Set<String> selectedIds;
  final MindMapProvider provider;
  final VoidCallback onClose;
  const _BulkEditSheet({
    required this.selectedIds,
    required this.provider,
    required this.onClose,
  });
  @override
  State<_BulkEditSheet> createState() => _BulkEditSheetState();
}

class _BulkEditSheetState extends State<_BulkEditSheet> {
  // 選択された色 (null=変更しない)
  Color? _selectedColor;
  double _width = 160.0;
  double _height = 42.0;
  double _titleFontSize = 15.0;
  bool _widthChanged = false;
  bool _heightChanged = false;
  bool _fontChanged = false;

  double get _safeWidth => _width.clamp(80.0, 400.0).toDouble();
  double get _safeHeight => _height.clamp(36.0, 200.0).toDouble();
  double get _safeTitleFontSize => _titleFontSize.clamp(8.0, 28.0).toDouble();

  // AI処理状態
  bool _aiRunning = false;
  String _aiStatus = '';
  int _aiProgress = 0;
  int _aiTotal = 0;

  static const _colorOptions = [
    Color(0xFF6C63FF),
    Color(0xFF43B97F),
    Color(0xFFFF6B6B),
    Color(0xFFFFB347),
    Color(0xFF4FC3F7),
    Color(0xFFBA68C8),
    Color(0xFF90CAF9),
    // 旧 0xFFE6EE9C (薄い黄緑) は外した (= ユーザー要望: 黄色は出さない)。
    Color(0xFFA5D6A7),
    Color(0xFFFFAB91),
    Color(0xFF80CBC4),
    Color(0xFFF48FB1),
    Color(0xFFCE93D8),
  ];

  void _applyColor() {
    if (_selectedColor == null) return;
    for (final id in widget.selectedIds) {
      widget.provider.updateNodeColor(id, _selectedColor!);
    }
    setState(() {});
  }

  void _applySize() {
    for (final id in widget.selectedIds) {
      final node = widget.provider.currentPage.nodes[id];
      if (node == null) continue;
      widget.provider.updateNodeSize(
        id,
        _widthChanged ? _safeWidth : node.width,
        _heightChanged ? _safeHeight : node.height,
      );
    }
  }

  void _applyFont() {
    for (final id in widget.selectedIds) {
      widget.provider.updateNodeTitleFontSize(id, _titleFontSize);
    }
  }

  Future<void> _runAiBulk(String mode) async {
    if (!widget.provider.hasActiveAiKey) {
      _appSnack(
        context,
        SnackBar(
            content: Text(widget.provider.t('ai.setGeminiKey')),
            backgroundColor: Colors.redAccent),
      );
      return;
    }
    final ids = widget.selectedIds.toList();
    setState(() {
      _aiRunning = true;
      _aiTotal = ids.length;
      _aiProgress = 0;
      _aiStatus = '';
    });
    for (int i = 0; i < ids.length; i++) {
      final id = ids[i];
      final node = widget.provider.currentPage.nodes[id];
      if (node == null) continue;
      setState(() {
        _aiProgress = i + 1;
        _aiStatus =
            '${node.title.length > 12 ? "${node.title.substring(0, 10)}..." : node.title} を処理中 ($_aiProgress/$_aiTotal)';
      });
      try {
        if (mode == 'explain') {
          await widget.provider.aiExplainNode(id);
        } else if (mode == 'children') {
          await widget.provider.aiGenerateChildren(id);
        }
      } catch (e) {
        // 1件失敗しても続行
        debugPrint('AI bulk error ($id): $e');
      }
    }
    if (!mounted) return;
    setState(() {
      _aiRunning = false;
      _aiStatus = '完了！ ($_aiTotal/${_aiTotal}件処理)';
    });
    await Future.delayed(const Duration(seconds: 2));
    if (mounted) setState(() => _aiStatus = '');
  }

  @override
  Widget build(BuildContext context) {
    final count = widget.selectedIds.length;
    return Container(
      decoration: const BoxDecoration(
        color: Color(0xFF1A1A2E),
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
        border: Border(top: BorderSide(color: Color(0xFF6C63FF), width: 2)),
      ),
      child: SafeArea(
        child: Padding(
          padding: EdgeInsets.only(
            left: 20,
            right: 20,
            top: 16,
            bottom: MediaQuery.of(context).viewInsets.bottom + 16,
          ),
          child: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // ── ヘッダー ──
                Row(children: [
                  Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                    decoration: BoxDecoration(
                      color: const Color(0xFF6C63FF).withValues(alpha: 0.2),
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(
                          color:
                              const Color(0xFF6C63FF).withValues(alpha: 0.6)),
                    ),
                    child: Text(
                        widget.provider
                            .t('groupCreate.selecting')
                            .replaceAll('{n}', '$count'),
                        style: const TextStyle(
                            color: Color(0xFF6C63FF),
                            fontSize: 12,
                            fontWeight: FontWeight.w700)),
                  ),
                  const Spacer(),
                  IconButton(
                    icon: const Icon(Icons.close,
                        color: Colors.white54, size: 20),
                    onPressed: () {
                      Navigator.pop(context);
                      widget.onClose();
                    },
                  ),
                ]),

                const Divider(color: Colors.white12, height: 20),

                // ── 色変更 ──
                _sectionTitle(
                    Icons.palette_rounded, '色を一括変更', const Color(0xFFBA68C8)),
                const SizedBox(height: 8),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: _colorOptions.map((c) {
                    final selected = _selectedColor == c;
                    return GestureDetector(
                      onTap: () {
                        setState(() => _selectedColor = c);
                        _applyColor();
                      },
                      child: AnimatedContainer(
                        duration: const Duration(milliseconds: 150),
                        width: selected ? 36 : 30,
                        height: selected ? 36 : 30,
                        decoration: BoxDecoration(
                          color: c,
                          shape: BoxShape.circle,
                          border: Border.all(
                              color:
                                  selected ? Colors.white : Colors.transparent,
                              width: 2.5),
                          boxShadow: selected
                              ? [
                                  BoxShadow(
                                      color: c.withValues(alpha: 0.7),
                                      blurRadius: 8)
                                ]
                              : null,
                        ),
                      ),
                    );
                  }).toList(),
                ),

                const SizedBox(height: 16),

                // ── サイズ変更 ──
                _sectionTitle(Icons.aspect_ratio_rounded, 'サイズを一括変更',
                    const Color(0xFF4FC3F7)),
                const SizedBox(height: 8),
                Row(children: [
                  Text(widget.provider.t('paint.width'),
                      style: TextStyle(color: Colors.white54, fontSize: 12)),
                  Expanded(
                    child: Slider(
                      value: _safeWidth,
                      min: 80,
                      max: 400,
                      divisions: 32,
                      activeColor: const Color(0xFF4FC3F7),
                      inactiveColor: Colors.white12,
                      label: _width.round().toString(),
                      onChanged: (v) => setState(() {
                        _width = v;
                        _widthChanged = true;
                      }),
                      onChangeEnd: (_) => _applySize(),
                    ),
                  ),
                  SizedBox(
                    width: 36,
                    child: Text('${_width.round()}',
                        style: const TextStyle(
                            color: Colors.white54, fontSize: 12),
                        textAlign: TextAlign.right),
                  ),
                ]),
                Row(children: [
                  Text(widget.provider.t('paint.height'),
                      style: TextStyle(color: Colors.white54, fontSize: 12)),
                  Expanded(
                    child: Slider(
                      value: _safeHeight,
                      min: 36,
                      max: 200,
                      divisions: 20,
                      activeColor: const Color(0xFF4FC3F7),
                      inactiveColor: Colors.white12,
                      label: _height.round().toString(),
                      onChanged: (v) => setState(() {
                        _height = v;
                        _heightChanged = true;
                      }),
                      onChangeEnd: (_) => _applySize(),
                    ),
                  ),
                  SizedBox(
                    width: 36,
                    child: Text('${_height.round()}',
                        style: const TextStyle(
                            color: Colors.white54, fontSize: 12),
                        textAlign: TextAlign.right),
                  ),
                ]),
                Row(children: [
                  Text(widget.provider.t('video.font'),
                      style: TextStyle(color: Colors.white54, fontSize: 12)),
                  Expanded(
                    child: Slider(
                      value: _safeTitleFontSize,
                      min: 8,
                      max: 28,
                      divisions: 20,
                      activeColor: const Color(0xFF4FC3F7),
                      inactiveColor: Colors.white12,
                      label: _titleFontSize.round().toString(),
                      onChanged: (v) => setState(() {
                        _titleFontSize = v;
                        _fontChanged = true;
                      }),
                      onChangeEnd: (_) {
                        if (_fontChanged) _applyFont();
                      },
                    ),
                  ),
                  SizedBox(
                    width: 36,
                    child: Text('${_titleFontSize.round()}pt',
                        style: const TextStyle(
                            color: Colors.white54, fontSize: 12),
                        textAlign: TextAlign.right),
                  ),
                ]),

                const Divider(color: Colors.white12, height: 20),

                // ── AI 一括適用 ──
                _sectionTitle(Icons.auto_awesome_rounded, 'AI機能を一括適用',
                    const Color(0xFFFFB347)),
                const SizedBox(height: 4),
                if (!widget.provider.hasActiveAiKey)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: Text(widget.provider.t('ai.geminiKeyNeeded'),
                        style: TextStyle(
                            color: Colors.orangeAccent, fontSize: 11)),
                  ),

                if (_aiRunning) ...[
                  const SizedBox(height: 4),
                  LinearProgressIndicator(
                    value: _aiTotal > 0 ? _aiProgress / _aiTotal : null,
                    backgroundColor: Colors.white12,
                    valueColor:
                        const AlwaysStoppedAnimation<Color>(Color(0xFFFFB347)),
                    borderRadius: BorderRadius.circular(4),
                  ),
                  const SizedBox(height: 6),
                  Text(_aiStatus,
                      style:
                          const TextStyle(color: Colors.white54, fontSize: 11)),
                  const SizedBox(height: 8),
                ] else if (_aiStatus.isNotEmpty) ...[
                  Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: Row(children: [
                      const Icon(Icons.check_circle_rounded,
                          color: Color(0xFF43B97F), size: 14),
                      const SizedBox(width: 6),
                      Text(_aiStatus,
                          style: const TextStyle(
                              color: Color(0xFF43B97F), fontSize: 12)),
                    ]),
                  ),
                ],

                Row(children: [
                  Expanded(
                    child: _aiActionBtn(
                      icon: Icons.lightbulb_outline_rounded,
                      label: widget.provider.t('bulk.genTermExplain'),
                      sub: '各ノードの説明を子ノードとして追加',
                      color: const Color(0xFF4FC3F7),
                      enabled: !_aiRunning && widget.provider.hasActiveAiKey,
                      onTap: () => _runAiBulk('explain'),
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: _aiActionBtn(
                      icon: Icons.account_tree_rounded,
                      label: widget.provider.t('bulk.genChildren'),
                      sub: '各ノードの構成要素を子ノードとして展開',
                      color: const Color(0xFFBA68C8),
                      enabled: !_aiRunning && widget.provider.hasActiveAiKey,
                      onTap: () => _runAiBulk('children'),
                    ),
                  ),
                ]),
                const Divider(color: Colors.white12, height: 20),

                // ── フラッシュカード登録 (= ユーザー要望: 範囲選択からまとめて
                //    フラッシュカードの表面を新規登録) ──
                _sectionTitle(
                    Icons.style_rounded, 'フラッシュカード', const Color(0xFF26C6DA)),
                const SizedBox(height: 4),
                Row(children: [
                  Expanded(
                    child: _aiActionBtn(
                      icon: Icons.add_card_rounded,
                      label: widget.provider.t('bulk.registerFront'),
                      sub: '選択ノードのタイトルを各カードの表面として新規登録',
                      color: const Color(0xFF26C6DA),
                      enabled: !_aiRunning,
                      onTap: _registerFlashcardFronts,
                    ),
                  ),
                ]),
                const SizedBox(height: 4),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _sectionTitle(IconData icon, String label, Color color) {
    return Row(children: [
      Icon(icon, color: color, size: 15),
      const SizedBox(width: 6),
      Text(label,
          style: TextStyle(
              color: color, fontSize: 13, fontWeight: FontWeight.w700)),
    ]);
  }

  Widget _aiActionBtn({
    required IconData icon,
    required String label,
    required String sub,
    required Color color,
    required bool enabled,
    required VoidCallback onTap,
  }) {
    return GestureDetector(
      onTap: enabled ? onTap : null,
      child: AnimatedOpacity(
        opacity: enabled ? 1.0 : 0.4,
        duration: const Duration(milliseconds: 200),
        child: Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: color.withValues(alpha: 0.08),
            borderRadius: BorderRadius.circular(12),
            border: Border.all(color: color.withValues(alpha: 0.4)),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(children: [
                Icon(icon, color: color, size: 16),
                const SizedBox(width: 6),
                Flexible(
                  child: Text(label,
                      style: TextStyle(
                          color: color,
                          fontSize: 12,
                          fontWeight: FontWeight.w700)),
                ),
              ]),
              const SizedBox(height: 4),
              Text(sub,
                  style: const TextStyle(color: Colors.white38, fontSize: 10)),
            ],
          ),
        ),
      ),
    );
  }

  /// 範囲選択したノードのタイトルを、 現在ページのフラッシュカードデッキに
  /// 「表面」 として新規登録する (= ユーザー要望)。 既に同じ表面のカードが
  /// あればスキップ。 裏面は空 (後から追記できる)。
  Future<void> _registerFlashcardFronts() async {
    final pageId = widget.provider.currentPage.id;
    final existing = await _FlashcardStore.load(pageId);
    final fronts = existing.map((c) => c.front).toSet();
    int added = 0;
    for (final id in widget.selectedIds) {
      final n = widget.provider.nodes[id];
      if (n == null) continue;
      final front = n.title.trim();
      if (front.isEmpty || fronts.contains(front)) continue;
      existing.add((
        front: front,
        back: '',
        group: '',
        global: false,
        image: '',
        imageSide: 'front'
      ));
      fronts.add(front);
      added++;
    }
    if (added > 0) await _FlashcardStore.saveList(pageId, existing);
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(
          added > 0 ? '$added 枚のフラッシュカード(表面)を登録しました' : '新しく登録できるカードがありませんでした'),
      backgroundColor: const Color(0xFF26C6DA),
      duration: const Duration(seconds: 2),
    ));
  }
}

// ─── AI一括適用シート ───────────────────────────────────────────────────────
class _BulkAISheet extends StatefulWidget {
  final Set<String> selectedIds;
  final MindMapProvider provider;

  /// 「APIキーを設定する」ボタン押下時に呼び出されるコールバック。
  /// 親 (_MindMapScreenState) で Gemini API キー設定ダイアログを開く。
  final VoidCallback? onOpenApiKeyDialog;
  const _BulkAISheet({
    required this.selectedIds,
    required this.provider,
    this.onOpenApiKeyDialog,
  });
  @override
  State<_BulkAISheet> createState() => _BulkAISheetState();
}

class _BulkAISheetState extends State<_BulkAISheet> {
  bool _running = false;
  String _status = '';
  int _progress = 0;
  int _total = 0;
  bool _done = false;

  // ── カスタム質問モード ──
  // 第 3 のオプション「カスタム質問で一括処理」 が選ばれた時に、
  // ユーザーが入力した質問文を保持する。 `_customMode` が true の時
  // カードリストの代わりに TextField + 実行ボタンを表示する。
  bool _customMode = false;
  final TextEditingController _customCtrl = TextEditingController();

  @override
  void dispose() {
    _customCtrl.dispose();
    super.dispose();
  }

  Future<void> _run(String mode, {String customPrompt = ''}) async {
    if (!widget.provider.hasActiveAiKey) {
      _appSnack(
        context,
        SnackBar(
          content: Text(widget.provider.t('ai.setGeminiKeyHint')),
          backgroundColor: Colors.redAccent,
          duration: Duration(seconds: 3),
        ),
      );
      return;
    }
    final ids = widget.selectedIds.toList();
    setState(() {
      _running = true;
      _total = ids.length;
      _progress = 0;
      _status = '準備中...';
      _done = false;
    });
    int succeeded = 0;
    for (int i = 0; i < ids.length; i++) {
      final id = ids[i];
      final node = widget.provider.currentPage.nodes[id];
      if (node == null) continue;
      final title = node.title.length > 15
          ? '${node.title.substring(0, 13)}...'
          : node.title;
      setState(() {
        _progress = i + 1;
        _status = '「$title」を処理中 ($_progress/$_total)';
      });
      try {
        if (mode == 'explain') {
          await widget.provider.aiExplainNode(id);
        } else if (mode == 'custom') {
          // ユーザーが書いた自由質問を各ノードについて聞く。
          // provider.aiCustomPrompt は既存メソッドで、 ノードの memoText に
          // AI の回答を追記する形 (見出し付き) で結果を反映する。
          await widget.provider.aiCustomPrompt(id, customPrompt);
        } else {
          await widget.provider.aiGenerateChildren(id);
        }
        succeeded++;
      } catch (e) {
        debugPrint('AI bulk error: $e');
      }
    }
    if (!mounted) return;
    setState(() {
      _running = false;
      _done = true;
      _status = '完了 ($succeeded/${ids.length}件)';
    });
  }

  @override
  Widget build(BuildContext context) {
    final count = widget.selectedIds.length;
    final hasKey = widget.provider.hasActiveAiKey;
    return Container(
      decoration: const BoxDecoration(
        color: Color(0xFF1A1A2E),
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
        border: Border(top: BorderSide(color: Color(0xFFFFB347), width: 2)),
      ),
      child: SafeArea(
        child: Padding(
          padding: EdgeInsets.only(
            left: 20,
            right: 20,
            top: 16,
            bottom: MediaQuery.of(context).viewInsets.bottom + 20,
          ),
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            // ヘッダー
            Row(children: [
              const Icon(Icons.auto_awesome_rounded,
                  color: Color(0xFFFFB347), size: 20),
              const SizedBox(width: 8),
              Text(
                  widget.provider
                      .t('bulk.aiApplyTitle')
                      .replaceFirst('{n}', '$count'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 15,
                      fontWeight: FontWeight.w700)),
              const Spacer(),
              if (!_running)
                IconButton(
                  icon:
                      const Icon(Icons.close, color: Colors.white54, size: 20),
                  onPressed: () => Navigator.pop(context),
                ),
            ]),

            if (!hasKey) ...[
              const SizedBox(height: 10),
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: Colors.orangeAccent.withValues(alpha: 0.1),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                      color: Colors.orangeAccent.withValues(alpha: 0.4)),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    const Row(children: [
                      Icon(Icons.warning_amber_rounded,
                          color: Colors.orangeAccent, size: 16),
                      SizedBox(width: 8),
                      Expanded(
                        child: Text(
                            'Gemini APIキーが未設定です。\nAI機能を使うには APIキーの設定が必要です。',
                            style: TextStyle(
                                color: Colors.orangeAccent, fontSize: 12)),
                      ),
                    ]),
                    const SizedBox(height: 10),
                    // ── 設定画面に飛ぶボタン ──
                    // 押すとこのボトムシートを閉じて Gemini API キー設定
                    // ダイアログを開く。openApiKeyDialog コールバック経由で
                    // 親側 (_MindMapScreenState) のメソッドを呼び出す。
                    SizedBox(
                      width: double.infinity,
                      child: ElevatedButton.icon(
                        icon: const Icon(Icons.key_rounded, size: 16),
                        label: Text(widget.provider.t('ai.setApiKeyBtn')),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.orangeAccent,
                          foregroundColor: Colors.black87,
                          textStyle: const TextStyle(
                              fontSize: 13, fontWeight: FontWeight.w700),
                          padding: const EdgeInsets.symmetric(vertical: 10),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(8),
                          ),
                        ),
                        onPressed: () {
                          // 先にこのボトムシートを閉じてから、親に通知して
                          // API キー設定ダイアログを開かせる。
                          Navigator.pop(context);
                          widget.onOpenApiKeyDialog?.call();
                        },
                      ),
                    ),
                  ],
                ),
              ),
            ],

            const SizedBox(height: 16),
            const Divider(color: Colors.white12, height: 1),
            const SizedBox(height: 16),

            if (_running) ...[
              LinearProgressIndicator(
                value: _total > 0 ? _progress / _total : null,
                backgroundColor: Colors.white12,
                valueColor:
                    const AlwaysStoppedAnimation<Color>(Color(0xFFFFB347)),
                borderRadius: BorderRadius.circular(4),
                minHeight: 6,
              ),
              const SizedBox(height: 10),
              Text(_status,
                  style: const TextStyle(color: Colors.white70, fontSize: 13)),
              const SizedBox(height: 16),
            ] else if (_done) ...[
              Row(children: [
                const Icon(Icons.check_circle_rounded,
                    color: Color(0xFF43B97F), size: 18),
                const SizedBox(width: 8),
                Text(_status,
                    style: const TextStyle(
                        color: Color(0xFF43B97F),
                        fontSize: 14,
                        fontWeight: FontWeight.w600)),
              ]),
              const SizedBox(height: 12),
              SizedBox(
                width: double.infinity,
                child: TextButton(
                  onPressed: () => Navigator.pop(context),
                  child: Text(widget.provider.t('btn.close'),
                      style: const TextStyle(color: Colors.white54)),
                ),
              ),
            ] else ...[
              if (_customMode) ...[
                // ── カスタム質問モード: TextField + 実行ボタン ──
                Row(children: [
                  IconButton(
                    icon: const Icon(Icons.arrow_back_rounded,
                        color: Colors.white54, size: 18),
                    tooltip: widget.provider.t('bulk.backToMenu'),
                    onPressed: () => setState(() {
                      _customMode = false;
                    }),
                  ),
                  const SizedBox(width: 4),
                  const Expanded(
                    child: Text(
                      'カスタム質問で一括処理',
                      style: TextStyle(
                        color: Color(0xFFE57373),
                        fontSize: 14,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ),
                ]),
                const SizedBox(height: 8),
                Text(
                  '選択した $count 個のノードそれぞれに対して同じ質問を投げ、 '
                  '各ノードのメモ欄に回答を追記します。',
                  style: const TextStyle(
                      color: Colors.white70, fontSize: 12, height: 1.4),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: _customCtrl,
                  style: const TextStyle(color: Colors.white, fontSize: 13),
                  minLines: 3,
                  maxLines: 6,
                  keyboardType: TextInputType.multiline,
                  textInputAction: TextInputAction.newline,
                  decoration: InputDecoration(
                    hintText:
                        '例) この用語の歴史的背景は?\n   この概念を初心者向けに説明して\n   関連する人物を 3 人挙げて',
                    hintStyle:
                        const TextStyle(color: Colors.white38, fontSize: 12),
                    filled: true,
                    fillColor: Colors.white.withValues(alpha: 0.06),
                    isDense: true,
                    contentPadding: const EdgeInsets.all(12),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                      borderSide: BorderSide.none,
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton.icon(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: const Color(0xFFE57373),
                      foregroundColor: Colors.white,
                      padding: const EdgeInsets.symmetric(vertical: 12),
                    ),
                    icon: const Icon(Icons.send_rounded, size: 18),
                    label: Text(
                        widget.provider
                            .t('bulk.askNodes')
                            .replaceFirst('{n}', '$count'),
                        style: const TextStyle(
                            fontSize: 13, fontWeight: FontWeight.w700)),
                    onPressed: !hasKey
                        ? null
                        : () {
                            final p = _customCtrl.text.trim();
                            if (p.isEmpty) {
                              _appSnack(
                                context,
                                SnackBar(
                                  content: Text(
                                      widget.provider.t('bulk.enterQuestion')),
                                  duration: Duration(seconds: 2),
                                ),
                              );
                              return;
                            }
                            _run('custom', customPrompt: p);
                          },
                  ),
                ),
                const SizedBox(height: 8),
              ] else ...[
                // ── 用語説明 ──
                _aiCard(
                  icon: Icons.lightbulb_rounded,
                  color: const Color(0xFF4FC3F7),
                  title: context.read<MindMapProvider>().t('bulkai.explainTerms'),
                  description: '選択した各ノードのタイトルについて、AIが説明文を作成して子ノードとして追加します。',
                  example: '例) 「機械学習」→ 説明ノードが右側に展開',
                  enabled: hasKey,
                  onTap: () => _run('explain'),
                ),
                const SizedBox(height: 12),
                // ── 子ノード生成 ──
                _aiCard(
                  icon: Icons.account_tree_rounded,
                  color: const Color(0xFFBA68C8),
                  title: context.read<MindMapProvider>().t('bulkai.genChildren'),
                  description: '選択した各ノードの構成要素・関連項目をAIが列挙して子ノードとして展開します。',
                  example: '例) 「日本の城」→「姫路城」「松本城」... が子ノードに',
                  enabled: hasKey,
                  onTap: () => _run('children'),
                ),
                const SizedBox(height: 12),
                // ── カスタム質問 (新規) ──
                // ユーザーが自由に質問文を書いて、 選択した各ノードに対して
                // 個別に AI に問い合わせる。 結果は各ノードのメモ欄に追記される。
                _aiCard(
                  icon: Icons.help_rounded,
                  color: const Color(0xFFE57373),
                  title: context.read<MindMapProvider>().t('bulkai.customPrompt'),
                  description: '選択した各ノードについて、 自分で書いた質問を AI に投げて回答をメモ欄に追加します。',
                  example: '例) 「この概念の応用例を 3 つ挙げて」 を全ノードに',
                  enabled: hasKey,
                  onTap: () => setState(() {
                    _customMode = true;
                  }),
                ),
                const SizedBox(height: 8),
              ],
            ],
          ]),
        ),
      ),
    );
  }

  Widget _aiCard({
    required IconData icon,
    required Color color,
    required String title,
    required String description,
    required String example,
    required bool enabled,
    required VoidCallback onTap,
  }) {
    return GestureDetector(
      onTap: enabled ? onTap : null,
      child: AnimatedOpacity(
        opacity: enabled ? 1.0 : 0.45,
        duration: const Duration(milliseconds: 150),
        child: Container(
          width: double.infinity,
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            color: color.withValues(alpha: 0.07),
            borderRadius: BorderRadius.circular(14),
            border: Border.all(color: color.withValues(alpha: 0.45)),
          ),
          child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Container(
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: color.withValues(alpha: 0.15),
                borderRadius: BorderRadius.circular(10),
              ),
              child: Icon(icon, color: color, size: 22),
            ),
            const SizedBox(width: 14),
            Expanded(
              child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(title,
                        style: TextStyle(
                            color: color,
                            fontSize: 14,
                            fontWeight: FontWeight.w700)),
                    const SizedBox(height: 4),
                    Text(description,
                        style: const TextStyle(
                            color: Colors.white70, fontSize: 12)),
                    const SizedBox(height: 4),
                    Text(example,
                        style: TextStyle(
                            color: Colors.white38,
                            fontSize: 11,
                            fontStyle: FontStyle.italic)),
                  ]),
            ),
            const SizedBox(width: 8),
            Icon(Icons.arrow_forward_ios_rounded,
                color: color.withValues(alpha: 0.6), size: 14),
          ]),
        ),
      ),
    );
  }
}

// ─── 複数ノード選択アクションオーバーレイ ─────────────────────────────────────
class _MultiNodeActionOverlay extends StatelessWidget {
  final Offset screenPos;
  final int count;
  final VoidCallback onClose;
  final VoidCallback onBulkAI;

  /// AI 一括ボタンの右クリック / 長押し → モデル切替 / 前提条件の設定
  /// (= ユーザー要望: 要素の AI ボタンと同じくモード選択を出す)。
  final VoidCallback onBulkAIMode;
  final VoidCallback onDelete;
  final VoidCallback onCopy;
  final VoidCallback onGroup;

  /// 「複製」: 選択ノードをその場で複製 (旧: ヘッダー右上のボタン列から移設)。
  final VoidCallback onDuplicate;

  /// 「一括DL」: 選択ノードの添付 / YouTube 動画の一括ダウンロード
  /// (対象が無い時は null → ボタン非表示。 旧: ヘッダー右上から移設)。
  final VoidCallback? onBulkDownload;
  final IconData bulkDownloadIcon;
  final Color bulkDownloadColor;

  const _MultiNodeActionOverlay({
    required this.screenPos,
    required this.count,
    required this.onClose,
    required this.onBulkAI,
    required this.onBulkAIMode,
    required this.onDelete,
    required this.onCopy,
    required this.onGroup,
    required this.onDuplicate,
    this.onBulkDownload,
    this.bulkDownloadIcon = Icons.download_rounded,
    this.bulkDownloadColor = const Color(0xFF43B97F),
  });

  @override
  Widget build(BuildContext context) {
    final provider = context.watch<MindMapProvider>();
    final mq = MediaQuery.of(context);
    final isMobile = mq.size.width < 600;
    final btnSize = isMobile ? 34.0 : 38.0;
    final btnWidth = isMobile ? 56.0 : 68.0;
    final gap = isMobile ? 6.0 : 8.0;
    final pad = isMobile ? 6.0 : 8.0;
    _Btn multiBtn({
      required IconData icon,
      required String label,
      required Color color,
      required double size,
      required VoidCallback onTap,
    }) =>
        _Btn(
          icon: icon,
          label: label,
          color: color,
          size: size,
          width: btnWidth,
          onTap: onTap,
        );
    final buttons = [
      // AI 一括: 左タップ=まとめてブラウザ AI へ / 右クリック・長押し=モデル切替 /
      //   前提条件の設定 (= ユーザー要望: 要素の AI ボタンと同じモード選択)。
      GestureDetector(
        onSecondaryTapDown: (_) => onBulkAIMode(),
        child: _Btn(
          icon: Icons.auto_awesome_rounded,
          label: provider.t('multi.bulkAi'),
          color: const Color(0xFFFFB347),
          size: btnSize,
          width: btnWidth,
          onTap: onBulkAI,
          onLongPress: onBulkAIMode,
        ),
      ),
      // ── 複製 (= 旧ヘッダー右上ボタン列から移設) ──
      multiBtn(
        icon: Icons.content_copy_rounded,
        label: provider.t('multi.duplicate'),
        color: const Color(0xFF43B97F),
        size: btnSize,
        onTap: onDuplicate,
      ),
      multiBtn(
        icon: Icons.drive_file_move_rounded,
        label: provider.t('multi.copy'),
        // 緑が続きすぎないよう色を分散 (= ユーザー要望: 色んな色が順に並ぶ)。
        color: const Color(0xFF4FC3F7),
        size: btnSize,
        onTap: onCopy,
      ),
      multiBtn(
        icon: Icons.bookmark_add_rounded,
        label: provider.t('multi.group'),
        color: const Color(0xFFBA68C8),
        size: btnSize,
        onTap: onGroup,
      ),
      // ── 一括DL (= 旧ヘッダー右上ボタン列から移設。 対象がある時だけ) ──
      if (onBulkDownload != null)
        multiBtn(
          icon: bulkDownloadIcon,
          label: provider.t('multi.bulkDl'),
          color: bulkDownloadColor,
          size: btnSize,
          onTap: onBulkDownload!,
        ),
      // (「カード化」 ボタンは廃止 = ユーザー要望: 複数選択した時の項目に
      //  カード化は要らない。 フラッシュカードはヘッダーの専用ボタンから)
      // ── 「画像を一括保存」 は独立ボタンを廃止 (= ユーザー要望: 画像保存は
      //    一括DL に纏めて)。 画像もノードの添付なので、 上の「一括DL」 が
      //    そのまま受け持つ (画像だけを選んでいる時は、 そのボタンが
      //    画像保存の流れになる)。 ──
      // 注: 旧 整列(横/縦)ボタンは削除しました (2026-04)。
      multiBtn(
        icon: Icons.delete_outline_rounded,
        label: provider.t('multi.delete'),
        color: Colors.redAccent,
        size: btnSize,
        onTap: onDelete,
      ),
    ];

    final double contentW = buttons.length * btnWidth +
        math.max(0, buttons.length - 1).toDouble() * gap;
    final double totalW =
        math.max(160.0, math.min(contentW + pad * 2, mq.size.width - 16.0));
    // ボタン数からおおよその高さを見積もり、 メニュー全体が画面内に収まるよう
    // クランプする (= ユーザー要望: 複数選択メニューが画面/範囲の外にはみ出さない
    // ように)。 320px 幅に約 5 個並ぶので行数を概算。 clamp の上限が 8 未満に
    // ならないよう下限を 8 に固定し、 狭い画面での ArgumentError も防ぐ。
    final estH = pad * 2 + btnSize + 20.0;
    final double maxLeft =
        (mq.size.width - totalW - 8).clamp(8.0, double.infinity).toDouble();
    final double maxTop =
        (mq.size.height - estH - 8).clamp(8.0, double.infinity).toDouble();
    final double left =
        (screenPos.dx - totalW / 2).clamp(8.0, maxLeft).toDouble();
    // screenPos.dy は「バー上端を置きたい位置」 (= ヘッダー直下) の上端アンカー。
    final double top = screenPos.dy.clamp(8.0, maxTop).toDouble();

    return Stack(children: [
      // 背景タップで閉じる
      Positioned.fill(
        child: GestureDetector(
          onTap: onClose,
          behavior: HitTestBehavior.translucent,
          child: const SizedBox.expand(),
        ),
      ),
      Positioned(
        left: left,
        top: top,
        child: Material(
          color: Colors.transparent,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            // ラベル (= 「~個選択中」) はモバイルでは画面を圧迫するため削除。
            // ボタン行
            Container(
              width: totalW,
              padding: EdgeInsets.all(pad),
              decoration: BoxDecoration(
                color: const Color(0xFF1E1E32).withValues(alpha: 0.96),
                borderRadius: BorderRadius.circular(isMobile ? 14 : 18),
                border: Border.all(
                    color: const Color(0xFF6C63FF).withValues(alpha: 0.4)),
                boxShadow: [
                  BoxShadow(
                      color: Colors.black.withValues(alpha: 0.5),
                      blurRadius: 20,
                      offset: const Offset(0, 6)),
                ],
              ),
              child: SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    for (int i = 0; i < buttons.length; i++) ...[
                      if (i > 0) SizedBox(width: gap),
                      buttons[i],
                    ],
                  ],
                ),
              ),
            ),
          ]),
        ),
      ),
    ]);
  }
}

// ─── 開発者モード: 送信履歴タブ内インライン受信箱 ────────────────────────────────
class _DevHistoryInlineView extends StatefulWidget {
  final MindMapProvider provider;
  const _DevHistoryInlineView({required this.provider});
  @override
  State<_DevHistoryInlineView> createState() => _DevHistoryInlineViewState();
}

class _DevHistoryInlineViewState extends State<_DevHistoryInlineView> {
  List<Map<String, dynamic>>? _inquiries;
  bool _loading = true;
  String? _replyingId;
  final _replyCtrl = TextEditingController();

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _replyCtrl.dispose();
    super.dispose();
  }

  String? _loadError;

  Future<void> _load() async {
    setState(() {
      _loading = true;
      _loadError = null;
    });
    try {
      final list = await widget.provider.fetchAllInquiries();
      if (!mounted) return;
      setState(() {
        _inquiries = list;
        _loading = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _loading = false;
        _loadError = e.toString();
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) {
      return const Center(
          child: CircularProgressIndicator(color: Color(0xFFBA68C8)));
    }
    if (_loadError != null) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(12),
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            const Icon(Icons.error_outline_rounded,
                color: Colors.redAccent, size: 36),
            const SizedBox(height: 8),
            Text(_loadError!,
                style: const TextStyle(color: Colors.redAccent, fontSize: 11),
                textAlign: TextAlign.center),
            const SizedBox(height: 12),
            ElevatedButton.icon(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFFFB347),
                  foregroundColor: Color(0xFF10241F),),
              icon: const Icon(Icons.refresh_rounded, size: 16),
              label: Text(widget.provider.t('fsv.retry')),
              onPressed: _load,
            ),
          ]),
        ),
      );
    }
    if (_inquiries == null || _inquiries!.isEmpty) {
      return Center(
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          const Icon(Icons.inbox_rounded, color: Colors.white24, size: 40),
          const SizedBox(height: 8),
          Text(widget.provider.t('inq.noInquiriesShort'),
              style: TextStyle(color: Colors.white38, fontSize: 13)),
          const SizedBox(height: 12),
          TextButton.icon(
            icon: const Icon(Icons.refresh_rounded,
                color: Colors.white38, size: 16),
            label: Text(widget.provider.t('btn.refresh'),
                style: const TextStyle(color: Colors.white38)),
            onPressed: _load,
          ),
        ]),
      );
    }
    return Column(children: [
      // ヘッダー
      Row(children: [
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
          decoration: BoxDecoration(
            color: const Color(0xFFBA68C8).withValues(alpha: 0.15),
            borderRadius: BorderRadius.circular(8),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            const Icon(Icons.admin_panel_settings_rounded,
                color: Color(0xFFBA68C8), size: 12),
            const SizedBox(width: 4),
            Text(
                widget.provider
                    .t('common.itemsN')
                    .replaceFirst('{n}', '${_inquiries!.length}'),
                style: const TextStyle(
                    color: Color(0xFFBA68C8),
                    fontSize: 11,
                    fontWeight: FontWeight.w700)),
          ]),
        ),
        const Spacer(),
        IconButton(
          icon: const Icon(Icons.refresh_rounded,
              color: Colors.white38, size: 16),
          onPressed: _load,
          tooltip: widget.provider.t('btn.refresh'),
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
        ),
      ]),
      const SizedBox(height: 6),
      Expanded(
        child: ListView.builder(
          itemCount: _inquiries!.length,
          itemBuilder: (_, i) => _buildItem(i),
        ),
      ),
    ]);
  }

  Widget _buildItem(int i) {
    final inq = _inquiries![i];
    final msgId = inq['id'] as String;
    final ts = inq['timestamp'] as String? ?? '';
    final dt = DateTime.tryParse(ts)?.toLocal();
    final dtStr = dt != null
        ? '${dt.month}/${dt.day} ${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}'
        : '';
    final reply = inq['reply'] as String? ?? '';
    final hasReply = reply.isNotEmpty;
    final uid = (inq['uid'] as String? ?? '');
    final shortUid = uid.length > 8 ? '${uid.substring(0, 6)}...' : uid;
    final isReplying = _replyingId == msgId;
    final status = inq['status'] as String? ?? 'open';
    final senderPlan = (inq['senderPlan'] as String? ?? '').toLowerCase();
    final senderName = (inq['senderName'] as String? ?? '').trim();

    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.04),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(
            color: hasReply
                ? const Color(0xFF43B97F).withValues(alpha: 0.35)
                : Colors.white.withValues(alpha: 0.08)),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        // ── プランバッジ + 送信者名 + UID + 日時 + ステータス ──
        Row(children: [
          // プランバッジ (Max → Pro → Coupon → Free の順で色分け)
          _senderPlanBadge(senderPlan),
          if (senderName.isNotEmpty) ...[
            const SizedBox(width: 6),
            Flexible(
              child: Text(senderName,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 11,
                      fontWeight: FontWeight.w700)),
            ),
          ],
          const SizedBox(width: 6),
          Text(shortUid,
              style: const TextStyle(
                  color: Colors.white38,
                  fontSize: 10,
                  fontFamily: 'monospace')),
          const SizedBox(width: 6),
          Text(dtStr,
              style: const TextStyle(color: Colors.white24, fontSize: 10)),
          const Spacer(),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 0),
            decoration: BoxDecoration(
              color: status == 'replied'
                  ? const Color(0xFF43B97F).withValues(alpha: 0.2)
                  : const Color(0xFFFFB347).withValues(alpha: 0.15),
              borderRadius: BorderRadius.circular(6),
            ),
            child: Text(
              status == 'replied' ? '返信済' : '未返信',
              style: TextStyle(
                  color: status == 'replied'
                      ? const Color(0xFF43B97F)
                      : const Color(0xFFFFB347),
                  fontSize: 9,
                  fontWeight: FontWeight.w700),
            ),
          ),
        ]),
        const SizedBox(height: 6),
        // メッセージ本文
        Text(inq['message'] as String? ?? '',
            style: const TextStyle(color: Colors.white, fontSize: 12)),
        // 既存の返信
        if (hasReply) ...[
          const SizedBox(height: 6),
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
              color: const Color(0xFF43B97F).withValues(alpha: 0.08),
              borderRadius: BorderRadius.circular(6),
              border: Border.all(
                  color: const Color(0xFF43B97F).withValues(alpha: 0.3)),
            ),
            child:
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                const Icon(Icons.reply_rounded,
                    color: Color(0xFF43B97F), size: 12),
                const SizedBox(width: 4),
                Text(widget.provider.t('inq.yourReply'),
                    style: const TextStyle(
                        color: Color(0xFF43B97F),
                        fontSize: 10,
                        fontWeight: FontWeight.w600)),
              ]),
              const SizedBox(height: 3),
              Text(reply,
                  style: const TextStyle(color: Colors.white70, fontSize: 12)),
            ]),
          ),
        ],
        // 返信フォーム or 返信ボタン
        if (isReplying) ...[
          const SizedBox(height: 8),
          TextField(
            controller: _replyCtrl,
            maxLines: 3,
            autofocus: true,
            style: const TextStyle(color: Colors.white, fontSize: 12),
            decoration: InputDecoration(
              hintText: widget.provider.t('inq.replyHint2'),
              hintStyle: const TextStyle(color: Colors.white24, fontSize: 11),
              filled: true,
              fillColor: Colors.white.withValues(alpha: 0.05),
              border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(6),
                  borderSide: BorderSide.none),
              contentPadding: const EdgeInsets.all(8),
              isDense: true,
            ),
          ),
          const SizedBox(height: 6),
          Row(children: [
            TextButton(
              onPressed: () => setState(() {
                _replyingId = null;
                _replyCtrl.clear();
              }),
              style: TextButton.styleFrom(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                  minimumSize: Size.zero,
                  tapTargetSize: MaterialTapTargetSize.shrinkWrap),
              child: Text(widget.provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white38, fontSize: 11)),
            ),
            const Spacer(),
            ElevatedButton.icon(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF43B97F),
                  foregroundColor: Colors.white,
                  padding:
                      const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                  minimumSize: Size.zero,
                  tapTargetSize: MaterialTapTargetSize.shrinkWrap),
              icon:
                  const Icon(Icons.send_rounded, size: 12, color: Colors.white),
              label: Text(widget.provider.t('btn.send'),
                  style: const TextStyle(color: Colors.white, fontSize: 12)),
              onPressed: () async {
                if (_replyCtrl.text.trim().isEmpty) return;
                final ok = await widget.provider
                    .replyToInquiry(msgId, _replyCtrl.text);
                if (!mounted) return;
                if (ok) {
                  setState(() {
                    _inquiries![i]['reply'] = _replyCtrl.text;
                    _inquiries![i]['status'] = 'replied';
                    _replyingId = null;
                  });
                  _replyCtrl.clear();
                }
              },
            ),
          ]),
        ] else ...[
          const SizedBox(height: 4),
          Align(
            alignment: Alignment.centerRight,
            child: TextButton.icon(
              style: TextButton.styleFrom(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                  minimumSize: Size.zero,
                  tapTargetSize: MaterialTapTargetSize.shrinkWrap),
              icon: const Icon(Icons.reply_rounded,
                  size: 13, color: Color(0xFF4FC3F7)),
              label: Text(hasReply ? '返信を編集' : '返信する',
                  style:
                      const TextStyle(color: Color(0xFF4FC3F7), fontSize: 11)),
              onPressed: () => setState(() {
                _replyingId = msgId;
                _replyCtrl.text = reply;
              }),
            ),
          ),
        ],
      ]),
    );
  }

  /// 送信者プランを示す小さな pill バッジ。
  /// 受信ボックス上で「Max ユーザーが先頭に並ぶ」のを視覚的に強調する。
  /// max → 紫赤 / developer → 紫 / pro → オレンジ / coupon → 水色 / free → 灰
  Widget _senderPlanBadge(String plan) {
    final p = plan.toLowerCase();
    late final Color color;
    late final String label;
    switch (p) {
      case 'max':
        color = const Color(0xFFE91E63);
        label = 'MAX';
        break;
      case 'developer':
        color = const Color(0xFFBA68C8);
        label = 'DEV';
        break;
      case 'pro':
        color = const Color(0xFFFFB347);
        label = 'PRO';
        break;
      case 'coupon':
        color = const Color(0xFF4FC3F7);
        label = 'CPN';
        break;
      case 'free':
        color = Colors.white38;
        label = 'FREE';
        break;
      default:
        color = Colors.white24;
        label = '?';
    }
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.18),
        borderRadius: BorderRadius.circular(6),
        border: Border.all(color: color.withValues(alpha: 0.6), width: 1),
      ),
      child: Text(
        label,
        style: TextStyle(
          color: color,
          fontSize: 9,
          fontWeight: FontWeight.w800,
          letterSpacing: 0.5,
        ),
      ),
    );
  }
}

/// グループ枠の拡張ハンドル。通常時は完全透明、ホバー時のみ薄く表示。
class _GroupResizeHandle extends StatefulWidget {
  final Color color;
  final void Function(DragUpdateDetails) onPanUpdate;
  const _GroupResizeHandle({required this.color, required this.onPanUpdate});
  @override
  State<_GroupResizeHandle> createState() => _GroupResizeHandleState();
}

class _GroupResizeHandleState extends State<_GroupResizeHandle> {
  bool _hover = false;
  @override
  Widget build(BuildContext context) {
    return MouseRegion(
      cursor: SystemMouseCursors.resizeDownRight,
      onEnter: (_) => setState(() => _hover = true),
      onExit: (_) => setState(() => _hover = false),
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onPanUpdate: widget.onPanUpdate,
        child: AnimatedOpacity(
          opacity: _hover ? 0.4 : 0.0,
          duration: const Duration(milliseconds: 150),
          child: Container(
            decoration: BoxDecoration(
              color: widget.color,
              shape: BoxShape.circle,
            ),
          ),
        ),
      ),
    );
  }
}

/// 裁断モードのプレビュー線を描画するカスタムペインター。
/// 2 クリック方式: 1 回目のクリックで始点が記録され、
/// マウスの現在位置（または 2 回目のクリック位置）までの直線を
/// 赤い破線で表示する。
/// [solid] = true の場合は破線ではなく実線で太めに描く（裁断実行直後の視覚フィードバック用）。
class _CutPreviewPainter extends CustomPainter {
  final Offset start;
  final Offset end;
  final bool solid;
  _CutPreviewPainter(
      {required this.start, required this.end, this.solid = false});

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = const Color(0xFFFF6B6B)
      ..strokeWidth = solid ? 3.5 : 2.5
      ..style = PaintingStyle.stroke;

    final delta = end - start;
    final total = delta.distance;
    if (total <= 0.01) {
      canvas.drawCircle(start, 4, Paint()..color = const Color(0xFFFF6B6B));
      return;
    }

    if (solid) {
      // 実線（裁断直後の一瞬）: グローを付けて視認性を高める
      final glow = Paint()
        ..color = const Color(0xFFFF6B6B).withValues(alpha: 0.5)
        ..strokeWidth = 10
        ..style = PaintingStyle.stroke;
      canvas.drawLine(start, end, glow);
      canvas.drawLine(start, end, paint);
    } else {
      // 破線を手動で描く
      const dashLen = 8.0;
      const gapLen = 5.0;
      final dirX = delta.dx / total;
      final dirY = delta.dy / total;
      double t = 0;
      while (t < total) {
        final t2 = (t + dashLen).clamp(0.0, total).toDouble();
        canvas.drawLine(
          Offset(start.dx + dirX * t, start.dy + dirY * t),
          Offset(start.dx + dirX * t2, start.dy + dirY * t2),
          paint,
        );
        t = t2 + gapLen;
      }
    }

    // 始点のマーカー
    canvas.drawCircle(start, 5, Paint()..color = const Color(0xFFFF6B6B));
    canvas.drawCircle(
        start,
        5,
        Paint()
          ..color = Colors.white
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.5);
    // 終点のマーカー（始点と同じでなければ）
    if (total > 3) {
      canvas.drawCircle(end, 5, Paint()..color = const Color(0xFFFF6B6B));
      canvas.drawCircle(
          end,
          5,
          Paint()
            ..color = Colors.white
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1.5);
    }
  }

  @override
  bool shouldRepaint(covariant _CutPreviewPainter old) =>
      old.start != start || old.end != end || old.solid != solid;
}

/// 装飾図形 (= 直線/矢印/長方形/楕円) を描画する CustomPainter。
///
/// ユーザー要望「直線や矢印線、 長方形等の図形を挿入できるようにして」 への
/// 対応で導入。 [MapDecoration] のリストを受け取り、 各図形を CustomPaint
/// 上に描画する。 マップ座標系 (= ノードと同じ系) で描画されるため、 マップの
/// パン/ズームに自動追従する。
/// 中を塗れる図形 (= 線の仲間ではない、 閉じた形)。
const Set<MapDecorationKind> _kClosedDecorationKinds = {
  MapDecorationKind.rectangle,
  MapDecorationKind.filledRectangle,
  MapDecorationKind.ellipse,
  MapDecorationKind.circle,
  MapDecorationKind.hollowCircle,
  MapDecorationKind.hollowTriangle,
  MapDecorationKind.hollowDiamond,
  MapDecorationKind.star,
  MapDecorationKind.pentagon,
  MapDecorationKind.hexagon,
  MapDecorationKind.heart,
  MapDecorationKind.cross,
};

class _DecorationPainter extends CustomPainter {
  final List<MapDecoration> decorations;
  final String? selectedId;

  /// 範囲選択で捕捉された図形 ID。 ハイライト表示する。
  final Set<String> rangeSelectedIds;

  /// 範囲ドラッグ中の移動量。 範囲選択された図形を描画時にずらす。
  final Offset rangeDragDelta;

  /// 当たり判定をズームに合わせるための現在スケール (画面上で約14px相当)。
  final double hitScale;

  /// このペインターが描くレイヤー番号 (= ユーザー要望: 5 段階のレイヤー)。
  /// null なら全部。 レイヤー 4〜5 はノードより手前の別ペインターで描くため、
  /// ノード下のペインターには {1,2,3} を渡す。
  final Set<int>? layers;
  _DecorationPainter({
    required this.decorations,
    this.selectedId,
    this.rangeSelectedIds = const {},
    this.rangeDragDelta = Offset.zero,
    this.hitScale = 1.0,
    this.layers,
  });

  /// 描画対象 (レイヤーで絞った上で、 番号の小さい層から順に。 同じ層は
  /// 従来どおりリスト順 = 後から描いた物が手前)。 sort は不安定なので
  /// 元の並び順をタイブレークに使う。
  List<MapDecoration> get _visibleSorted {
    final list = <(int, MapDecoration)>[];
    for (var i = 0; i < decorations.length; i++) {
      final d = decorations[i];
      if (layers != null && !layers!.contains(d.layer)) continue;
      list.add((i, d));
    }
    list.sort((a, b) {
      final byLayer = a.$2.layer.compareTo(b.$2.layer);
      return byLayer != 0 ? byLayer : a.$1.compareTo(b.$1);
    });
    return [for (final e in list) e.$2];
  }

  /// 点 [position] (キャンバス座標) が図形上なら true。
  /// これを返すことで CustomPaint が hitTestSelf=true になり、 これを包む
  /// GestureDetector(deferToChild) が「図形の上のタップ」 だけを拾える。
  static double _distToSeg(Offset p, Offset a, Offset b) {
    final ab = b - a;
    final lenSq = ab.dx * ab.dx + ab.dy * ab.dy;
    if (lenSq < 1e-6) return (p - a).distance;
    var t = ((p.dx - a.dx) * ab.dx + (p.dy - a.dy) * ab.dy) / lenSq;
    t = t.clamp(0.0, 1.0);
    return (p - Offset(a.dx + ab.dx * t, a.dy + ab.dy * t)).distance;
  }

  @override
  bool? hitTest(Offset position) {
    final s = hitScale <= 0 ? 1.0 : hitScale;
    final t = (14.0 / s).clamp(6.0, 90.0);
    for (final d in decorations) {
      // レイヤーで絞っている時は、 描いていない図形では当たらない。
      if (layers != null && !layers!.contains(d.layer)) continue;
      switch (d.kind) {
        case MapDecorationKind.polyline:
          // 各区間のどれかに近ければ当たり (= 折れ線)。
          final pts = d.points;
          for (var i = 0; i + 1 < pts.length; i++) {
            if (_distToSeg(position, pts[i], pts[i + 1]) <=
                t + d.strokeWidth) {
              return true;
            }
          }
          break;
        case MapDecorationKind.line:
        case MapDecorationKind.arrow:
        case MapDecorationKind.wavyLine:
          if (_distToSeg(position, d.start, d.end) <= t + d.strokeWidth) {
            return true;
          }
          break;
        default:
          if (Rect.fromPoints(d.start, d.end).inflate(t).contains(position)) {
            return true;
          }
      }
    }
    return false;
  }

  @override
  void paint(Canvas canvas, Size size) {
    for (final d0 in _visibleSorted) {
      final isSelected = d0.id == selectedId;
      final isRangeSel = rangeSelectedIds.contains(d0.id);
      // 範囲ドラッグ中は、 範囲選択された図形を delta だけずらして描画する。
      final d = (isRangeSel && rangeDragDelta != Offset.zero)
          ? d0.copyWith(
              start: d0.start + rangeDragDelta, end: d0.end + rangeDragDelta)
          : d0;
      final baseColor = Color(0xFF000000 | d.colorRgb);
      // 中を塗るかは図形の札で決める (= ユーザー要望: 星や♡も塗れる)。
      // 昔の絵は種類から決まる (isFilled が面倒を見る)。
      // 線・矢印・波線・折れ線は「中」 が無いので必ず線で描く。
      final filled = d.isFilled && _kClosedDecorationKinds.contains(d.kind);
      // 選択中はハイライト効果として外周にグロー (枠線) を描く
      if (isSelected || isRangeSel) {
        final glow = Paint()
          ..color =
              (isSelected ? const Color(0xFF4FC3F7) : const Color(0xFFFFB300))
                  .withValues(alpha: 0.5)
          ..strokeWidth = d.strokeWidth + 6
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round
          ..isAntiAlias = true;
        _drawShape(canvas, d, glow);
      }
      final paint = Paint()
        ..color = baseColor
        ..strokeWidth = d.strokeWidth
        ..style = filled ? PaintingStyle.fill : PaintingStyle.stroke
        ..strokeCap = StrokeCap.round
        ..isAntiAlias = true;
      _drawShape(canvas, d, paint);
      // ── 図形内の文字 (ユーザー要望) ──
      // 外接矩形の中央に描画。 どの色の図形でも読めるよう、 黒い縁取り +
      //   白文字で描く。 fontSize はキャンバス座標なのでズームに追従する。
      if (d.text.isNotEmpty) {
        final bbox = Rect.fromPoints(d.start, d.end);
        final maxW = bbox.width.abs();
        final span = (Paint? stroke) => TextSpan(
              text: d.text,
              style: TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w700,
                height: 1.15,
                foreground: stroke,
                color: stroke == null ? Colors.white : null,
              ),
            );
        // 縁取り (黒)
        final strokePaint = Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 3.0
          ..color = const Color(0xFF000000)
          ..isAntiAlias = true;
        final tpStroke = TextPainter(
          text: span(strokePaint),
          textAlign: TextAlign.center,
          textDirection: TextDirection.ltr,
        )..layout(maxWidth: maxW > 20 ? maxW : double.infinity);
        // 本体 (白)
        final tpFill = TextPainter(
          text: span(null),
          textAlign: TextAlign.center,
          textDirection: TextDirection.ltr,
        )..layout(maxWidth: maxW > 20 ? maxW : double.infinity);
        // ── アンカー位置 (0..1) に従って配置 ──
        // ax=0 左 / 0.5 中央 / 1 右、 ay=0 上 / 0.5 中央 / 1 下。
        // 自由ドラッグでも任意の正規化座標を取れる (ユーザー要望)。
        final textW = tpFill.width;
        final textH = tpFill.height;
        final off = Offset(
          bbox.left + (bbox.width - textW) * d.textAnchorX,
          bbox.top + (bbox.height - textH) * d.textAnchorY,
        );
        tpStroke.paint(canvas, off);
        tpFill.paint(canvas, off);
      }
    }
  }

  /// 円 (= 正円) 用の正方形 Rect を start/end の対角から作る。
  Rect _circleRect(MapDecoration d) {
    final r = Rect.fromPoints(d.start, d.end);
    final side = math.min(r.width, r.height);
    return Rect.fromCenter(center: r.center, width: side, height: side);
  }

  void _drawShape(Canvas canvas, MapDecoration d, Paint paint) {
    switch (d.kind) {
      // ── 折れ線 (= ユーザー要望: 節点の沢山ついた折れ曲がった直線) ──
      case MapDecorationKind.polyline:
        final pts = d.points;
        if (pts.length < 2) {
          canvas.drawLine(d.start, d.end, paint);
          break;
        }
        final path = Path()..moveTo(pts.first.dx, pts.first.dy);
        for (var i = 1; i < pts.length; i++) {
          path.lineTo(pts[i].dx, pts[i].dy);
        }
        // 角を丸めて折れ目が汚くならないようにする。
        final pen = Paint()
          ..color = paint.color
          ..strokeWidth = paint.strokeWidth
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round
          ..strokeJoin = StrokeJoin.round
          ..isAntiAlias = true;
        canvas.drawPath(path, pen);
        break;
      case MapDecorationKind.line:
        canvas.drawLine(d.start, d.end, paint);
        break;
      case MapDecorationKind.arrow:
        _drawArrow(canvas, d.start, d.end, paint);
        break;
      case MapDecorationKind.wavyLine:
        _drawWavyLine(canvas, d.start, d.end, paint);
        break;
      case MapDecorationKind.rectangle:
        canvas.drawRect(Rect.fromPoints(d.start, d.end), paint);
        break;
      case MapDecorationKind.filledRectangle:
        canvas.drawRect(Rect.fromPoints(d.start, d.end), paint);
        break;
      case MapDecorationKind.ellipse:
        canvas.drawOval(Rect.fromPoints(d.start, d.end), paint);
        break;
      case MapDecorationKind.hollowCircle:
        canvas.drawOval(_circleRect(d), paint);
        break;
      case MapDecorationKind.hollowTriangle:
        final tr = Rect.fromPoints(d.start, d.end);
        final tri = Path()
          ..moveTo(tr.center.dx, tr.top)
          ..lineTo(tr.left, tr.bottom)
          ..lineTo(tr.right, tr.bottom)
          ..close();
        canvas.drawPath(tri, paint);
        break;
      case MapDecorationKind.hollowDiamond:
        final dr = Rect.fromPoints(d.start, d.end);
        final dia = Path()
          ..moveTo(dr.center.dx, dr.top)
          ..lineTo(dr.right, dr.center.dy)
          ..lineTo(dr.center.dx, dr.bottom)
          ..lineTo(dr.left, dr.center.dy)
          ..close();
        canvas.drawPath(dia, paint);
        break;
      case MapDecorationKind.circle:
        canvas.drawOval(_circleRect(d), paint);
        break;
      // ── 追加図形 (= ユーザー要望: 星マークなど挿入できる図形を増やす)。
      //    Path 計算はフリーノート側の共通ヘルパーを再利用する。 ──
      case MapDecorationKind.star:
        canvas.drawPath(
            _paintStarPath(Rect.fromPoints(d.start, d.end)), paint);
        break;
      case MapDecorationKind.pentagon:
        canvas.drawPath(
            _paintRegularPolygonPath(Rect.fromPoints(d.start, d.end), 5),
            paint);
        break;
      case MapDecorationKind.hexagon:
        canvas.drawPath(
            _paintRegularPolygonPath(Rect.fromPoints(d.start, d.end), 6),
            paint);
        break;
      case MapDecorationKind.heart:
        canvas.drawPath(
            _paintHeartPath(Rect.fromPoints(d.start, d.end)), paint);
        break;
      case MapDecorationKind.cross:
        canvas.drawPath(
            _paintCrossPath(Rect.fromPoints(d.start, d.end)), paint);
        break;
    }
  }

  /// 波線 (= 始点→終点を結ぶ正弦波)。 振幅/波長は線の太さに比例。
  void _drawWavyLine(Canvas canvas, Offset a, Offset b, Paint paint) {
    final delta = b - a;
    final len = delta.distance;
    if (len < 0.01) {
      canvas.drawLine(a, b, paint);
      return;
    }
    final dir = delta / len;
    final normal = Offset(-dir.dy, dir.dx);
    final amplitude = math.max(4.0, paint.strokeWidth * 2);
    final wavelength = math.max(16.0, amplitude * 3);
    final steps = (len / 2).clamp(2, 800).toInt();
    final path = Path()..moveTo(a.dx, a.dy);
    for (int i = 1; i <= steps; i++) {
      final along = len * (i / steps);
      final off = math.sin(along / wavelength * 2 * math.pi) * amplitude;
      final p = a + dir * along + normal * off;
      path.lineTo(p.dx, p.dy);
    }
    // 波線は常に線 (塗り無し)。 グロー用 paint も stroke なのでそのまま使える。
    final sp = paint.style == PaintingStyle.fill
        ? (Paint()
          ..color = paint.color
          ..strokeWidth = paint.strokeWidth
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round
          ..isAntiAlias = true)
        : paint;
    canvas.drawPath(path, sp);
  }

  void _drawArrow(Canvas canvas, Offset start, Offset end, Paint paint) {
    canvas.drawLine(start, end, paint);
    // 矢じり (= end 側に三角を描く)。 サイズは線の太さに比例。
    final delta = end - start;
    final dist = delta.distance;
    if (dist < 0.01) return;
    final headLen = math.max(12.0, paint.strokeWidth * 4);
    final angle = math.atan2(delta.dy, delta.dx);
    const headAngle = 0.45; // 約 26°
    final p1 = Offset(end.dx - headLen * math.cos(angle - headAngle),
        end.dy - headLen * math.sin(angle - headAngle));
    final p2 = Offset(end.dx - headLen * math.cos(angle + headAngle),
        end.dy - headLen * math.sin(angle + headAngle));
    // 矢じりは塗りつぶしの三角に
    final headPath = Path()
      ..moveTo(end.dx, end.dy)
      ..lineTo(p1.dx, p1.dy)
      ..lineTo(p2.dx, p2.dy)
      ..close();
    final fillPaint = Paint()
      ..color = paint.color
      ..style = PaintingStyle.fill
      ..isAntiAlias = true;
    canvas.drawPath(headPath, fillPaint);
  }

  @override
  bool shouldRepaint(covariant _DecorationPainter old) =>
      // decorations は provider 側で in-place 更新されるため参照比較では
      //   文字/色などの変更を検知できない。 図形数は少なく描画も軽量なので
      //   常に再描画して確実に反映させる。
      true;
}

/// 初回起動のタイムゾーン選択用「メルカトル風 世界地図」 を描く CustomPainter。
/// ・経度を線形 (x)、 緯度をメルカトル変換 (y) でマッピング
/// ・簡略化した大陸シルエット + 15° ごとのタイムゾーン境界線
/// ・選択中の UTC オフセットの帯をハイライト + 中心にマーカー + ラベル
class _TimezoneMapPainter extends CustomPainter {
  final int selectedUtcMinutes;

  /// 地図中央に置く経度。設定言語/初期タイムゾーンを中央に表示するために使う。
  final double centerLon;
  _TimezoneMapPainter({
    required this.selectedUtcMinutes,
    this.centerLon = 0,
  });

  // 表示する緯度範囲 (メルカトルは極で発散するのでクロップ)。
  static const double _latTop = 78;
  static const double _latBottom = -56;

  static double _mercRaw(double latDeg) {
    final lat = latDeg * math.pi / 180.0;
    return math.log(math.tan(math.pi / 4 + lat / 2));
  }

  // 大陸 (経度, 緯度) ポリゴン。正確な海岸線ではないが、主要な半島・島・
  // 湾の特徴を反映して「世界地図に見える」 程度に詳細化した近似。
  static const List<List<List<double>>> _continents = [
