  @override
  void paint(Canvas canvas, Size size) {
    final w = size.width, h = size.height;
    final mTop = _mercRaw(_latTop), mBot = _mercRaw(_latBottom);
    // 経度 → centerLon を画面中央に置いた相対経度 (±180 でラップ)。
    double relOf(double lon) {
      double rel = lon - centerLon;
      while (rel > 180) rel -= 360;
      while (rel < -180) rel += 360;
      return rel;
    }

    double xOf(double lon) => (relOf(lon) + 180.0) / 360.0 * w;
    double yOf(double lat) {
      final m = _mercRaw(lat.clamp(_latBottom, _latTop));
      return (mTop - m) / (mTop - mBot) * h;
    }

    // 海 (背景)
    final ocean = Paint()..color = const Color(0xFF14304A);
    canvas.drawRect(Rect.fromLTWH(0, 0, w, h), ocean);

    // 緯線/経線 (薄いグリッド)
    final grid = Paint()
      ..color = Colors.white.withValues(alpha: 0.05)
      ..strokeWidth = 1;
    for (int d = -180; d <= 180; d += 30) {
      final x = xOf(centerLon + d);
      canvas.drawLine(Offset(x, 0), Offset(x, h), grid);
    }
    for (int lat = -40; lat <= 60; lat += 20) {
      final y = yOf(lat.toDouble());
      canvas.drawLine(Offset(0, y), Offset(w, y), grid);
    }

    // 大陸 (日付変更線をまたぐ辺は線を切ってサブパス化し、横断線の歪みを防ぐ)
    final land = Paint()
      ..color = const Color(0xFF3E7A52)
      ..style = PaintingStyle.fill
      ..isAntiAlias = true;
    final coast = Paint()
      ..color = const Color(0xFF5A9E6F)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 0.8
      ..isAntiAlias = true;
    for (final poly in _continents) {
      final path = Path();
      double? prevRel;
      bool started = false;
      for (final v in poly) {
        final rel = relOf(v[0]);
        final x = (rel + 180.0) / 360.0 * w;
        final y = yOf(v[1]);
        if (!started) {
          path.moveTo(x, y);
          started = true;
        } else if (prevRel != null && (rel - prevRel).abs() > 180) {
          path.moveTo(x, y); // ラップまたぎ → 線を切る
        } else {
          path.lineTo(x, y);
        }
        prevRel = rel;
      }
      path.close();
      canvas.drawPath(path, land);
      canvas.drawPath(path, coast);
    }

    // タイムゾーン境界線 (15° ごと)
    final tzLine = Paint()
      ..color = Colors.white.withValues(alpha: 0.10)
      ..strokeWidth = 1;
    for (int d = -180; d <= 180; d += 15) {
      final x = xOf(centerLon + d);
      canvas.drawLine(Offset(x, 0), Offset(x, h), tzLine);
    }

    // 選択中の UTC 帯をハイライト
    final utcH = selectedUtcMinutes / 60.0;
    final selLon = utcH * 15.0;
    final bandCx = xOf(selLon);
    final bandHalf = (7.5 / 360.0) * w;
    final bandPaint = Paint()
      ..color = const Color(0xFF4FC3F7).withValues(alpha: 0.28);
    canvas.drawRect(
        Rect.fromLTRB(bandCx - bandHalf, 0, bandCx + bandHalf, h), bandPaint);
    // 中心のマーカー線
    final marker = Paint()
      ..color = const Color(0xFF4FC3F7)
      ..strokeWidth = 2;
    canvas.drawLine(Offset(bandCx, 0), Offset(bandCx, h), marker);
    // ピン (上端)
    canvas.drawCircle(
        Offset(bandCx, 8), 4, Paint()..color = const Color(0xFF4FC3F7));

    // ラベル (UTC±H)
    final sign = selectedUtcMinutes < 0 ? '-' : '+';
    final am = selectedUtcMinutes.abs();
    final label = 'UTC$sign${am ~/ 60}';
    final tp = TextPainter(
      text: TextSpan(
          text: label,
          style: const TextStyle(
              color: Colors.white, fontSize: 12, fontWeight: FontWeight.w700)),
      textDirection: TextDirection.ltr,
    )..layout();
    double labelX = bandCx - tp.width / 2;
    labelX = labelX.clamp(2.0, w - tp.width - 2);
    // ラベル背景
    canvas.drawRRect(
      RRect.fromRectAndRadius(
          Rect.fromLTWH(
              labelX - 4, h - tp.height - 6, tp.width + 8, tp.height + 4),
          const Radius.circular(4)),
      Paint()..color = const Color(0xFF1A1A2E).withValues(alpha: 0.85),
    );
    tp.paint(canvas, Offset(labelX, h - tp.height - 4));
  }

  @override
  bool shouldRepaint(covariant _TimezoneMapPainter old) =>
      old.selectedUtcMinutes != selectedUtcMinutes ||
      old.centerLon != centerLon;
}

/// カレンダーイベントのドラッグペイロード。
/// Draggable / DragTarget の型パラメータとして使い、どの日のどのイベントが
/// ドラッグされているかを識別する。
class _CalendarDragPayload {
  final String fromDateKey;
  final String eventId;
  const _CalendarDragPayload({
    required this.fromDateKey,
    required this.eventId,
  });
}

// ════════════════════════════════════════════════════════════════════════════
// フローティングツール（Overlay 上に浮かぶ非モーダルパネル）
// ════════════════════════════════════════════════════════════════════════════

/// 5 つあるフローティングツール (計算機 / ストップウォッチ / 関数電卓 /
/// ポモドーロ / 天気) を畳んだ時の共通幅。本来パネルごとに違う panelW を
/// 持つので、畳んだ時の見た目もバラバラだったのを揃えるため統一値を定義。
/// ヘッダー要素 (ドラッグハンドル + アイコン + タイトル + chevron + 閉じる)
/// が無理なく収まる最小限の幅にしている。
const double _kCollapsedFloatingWidthMobile = 200.0;
const double _kCollapsedFloatingWidthDesktop = 220.0;

/// 上記をプラットフォーム判定込みで返すヘルパ。各ウィジェットの build() 内で
/// `_collapsedFloatingWidth(isMobile)` の形で使う。
double _collapsedFloatingWidth(bool isMobile) =>
    isMobile ? _kCollapsedFloatingWidthMobile : _kCollapsedFloatingWidthDesktop;

/// フローティング計算機パネル（Ctrl+M で起動）
/// - 画面の他所をタップしても閉じない（Overlay ベース）
/// - ヘッダー部分をドラッグして位置を自由に動かせる
/// - 物理キーボード入力対応: 0-9, ., + - * /, Enter(=), Backspace, Esc(クリア)
/// 浮遊する道具 (計算機・ストップウォッチ等) でヘッダーを隠している時に
/// 残す細い帯 (= ユーザー要望: 他と同様、 カーソルを乗せた時だけ表示ボタンが
/// 出るように)。 押すとヘッダーが戻る。
class _FloatingToolHiddenHeader extends StatefulWidget {
  final VoidCallback onShow;
  final Color color;
  const _FloatingToolHiddenHeader({required this.onShow, required this.color});

  @override
  State<_FloatingToolHiddenHeader> createState() =>
      _FloatingToolHiddenHeaderState();
}

class _FloatingToolHiddenHeaderState extends State<_FloatingToolHiddenHeader> {
  bool _hover = false;

  @override
  Widget build(BuildContext context) {
    return MouseRegion(
      onEnter: (_) {
        if (!_hover) setState(() => _hover = true);
      },
      onExit: (_) {
        if (_hover) setState(() => _hover = false);
      },
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: widget.onShow,
        child: Container(
          height: 14,
          decoration: BoxDecoration(
            color: widget.color.withValues(alpha: 0.25),
            borderRadius: const BorderRadius.only(
              topLeft: Radius.circular(13),
              topRight: Radius.circular(13),
            ),
          ),
          alignment: Alignment.center,
          child: _hover
              ? const Icon(Icons.keyboard_double_arrow_down_rounded,
                  size: 12, color: Colors.white70)
              : null,
        ),
      ),
    );
  }
}

class _FloatingCalculator extends StatefulWidget {
  final MindMapProvider provider;
  final Offset initialOffset;
  final VoidCallback onClose;

  /// drawer / popup menu / カレンダーが表示されている間、計算機を裏に隠す。
  /// State はそのまま (Offstage で widget tree から外さない) なので
  /// 計算結果や入力中の式は維持される。
  final bool hidden;

  /// 分割ペインの中に埋め込んで表示するか (= ユーザー要望: 分割画面に
  /// 置いたボタンから開いた時は、 浮かせずにそのペインいっぱいに開く)。
  /// true の時はドラッグ移動も画面外クランプもしない。
  final bool embedded;
  const _FloatingCalculator({
    super.key,
    required this.provider,
    required this.initialOffset,
    required this.onClose,
    this.hidden = false,
    this.embedded = false,
  });
  @override
  State<_FloatingCalculator> createState() => _FloatingCalculatorState();
}

class _FloatingCalculatorState extends State<_FloatingCalculator> {
  late Offset _offset;

  /// ヘッダーを隠しているか (= ユーザー要望: 他と同様に隠せるように)。
  bool _headerHidden = false;
  String _display = '0';
  double? _pendingValue;
  String? _pendingOp;
  bool _justComputed = false;

  /// 折り畳み状態 (true ならヘッダーだけが残り、ボタンは隠れる)。
  bool _collapsed = false;

  @override
  void initState() {
    super.initState();
    _offset = widget.initialOffset;
    // 背景のショートカットを邪魔しないように、FocusNode ではなく
    // HardwareKeyboard に直接ハンドラを登録する。
    // 計算機が消費するのは数字・演算子・Enter・Backspace・Esc のみ。
    // 他のキー (Ctrl+S, Ctrl+Z, 矢印など) は背景に流す（= false を返す）。
    //
    // 分割ペインに埋め込んだ計算機は開きっぱなしになるので、 キーを取ると
    // 別ペインでの入力まで奪ってしまう。 埋め込み時は登録しない
    // (マウス操作で使う)。
    if (!widget.embedded) {
      HardwareKeyboard.instance.addHandler(_handleCalcKey);
    }
  }

  @override
  void dispose() {
    HardwareKeyboard.instance.removeHandler(_handleCalcKey);
    super.dispose();
  }

  bool _handleCalcKey(KeyEvent event) {
    if (event is! KeyDownEvent) return false;
    // 修飾キー単独は無視
    final isCtrl = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    // テキスト編集中は干渉しない
    final focused = FocusManager.instance.primaryFocus;
    if (focused != null && focused.context?.widget is EditableText) {
      return false;
    }
    // Ctrl/Meta 押下中は計算機入力にせず、背景のショートカットに委譲
    if (isCtrl) return false;
    final k = event.logicalKey;
    if (k == LogicalKeyboardKey.digit0 || k == LogicalKeyboardKey.numpad0) {
      _pressDigit('0');
      return true;
    }
    if (k == LogicalKeyboardKey.digit1 || k == LogicalKeyboardKey.numpad1) {
      _pressDigit('1');
      return true;
    }
    if (k == LogicalKeyboardKey.digit2 || k == LogicalKeyboardKey.numpad2) {
      _pressDigit('2');
      return true;
    }
    if (k == LogicalKeyboardKey.digit3 || k == LogicalKeyboardKey.numpad3) {
      _pressDigit('3');
      return true;
    }
    if (k == LogicalKeyboardKey.digit4 || k == LogicalKeyboardKey.numpad4) {
      _pressDigit('4');
      return true;
    }
    if (k == LogicalKeyboardKey.digit5 || k == LogicalKeyboardKey.numpad5) {
      _pressDigit('5');
      return true;
    }
    if (k == LogicalKeyboardKey.digit6 || k == LogicalKeyboardKey.numpad6) {
      _pressDigit('6');
      return true;
    }
    if (k == LogicalKeyboardKey.digit7 || k == LogicalKeyboardKey.numpad7) {
      _pressDigit('7');
      return true;
    }
    if (k == LogicalKeyboardKey.digit8 || k == LogicalKeyboardKey.numpad8) {
      _pressDigit('8');
      return true;
    }
    if (k == LogicalKeyboardKey.digit9 || k == LogicalKeyboardKey.numpad9) {
      _pressDigit('9');
      return true;
    }
    if (k == LogicalKeyboardKey.period ||
        k == LogicalKeyboardKey.numpadDecimal) {
      _pressDot();
      return true;
    }
    if (k == LogicalKeyboardKey.add || k == LogicalKeyboardKey.numpadAdd) {
      _pressOp('+');
      return true;
    }
    if (k == LogicalKeyboardKey.minus ||
        k == LogicalKeyboardKey.numpadSubtract) {
      _pressOp('-');
      return true;
    }
    if (k == LogicalKeyboardKey.asterisk ||
        k == LogicalKeyboardKey.numpadMultiply) {
      _pressOp('*');
      return true;
    }
    if (k == LogicalKeyboardKey.slash || k == LogicalKeyboardKey.numpadDivide) {
      _pressOp('/');
      return true;
    }
    if (k == LogicalKeyboardKey.enter ||
        k == LogicalKeyboardKey.numpadEnter ||
        k == LogicalKeyboardKey.equal) {
      _pressEquals();
      return true;
    }
    if (k == LogicalKeyboardKey.backspace) {
      _pressBackspace();
      return true;
    }
    // Esc で折り畳み/展開をトグル (閉じるのではない)。
    // 計算結果や式は維持されるので、邪魔な時に Esc → 必要になったら再 Esc。
    if (k == LogicalKeyboardKey.escape) {
      setState(() => _collapsed = !_collapsed);
      return true;
    }
    // それ以外は背景に委譲
    return false;
  }

  String _formatNum(double v) {
    if (v.isNaN || v.isInfinite) return 'Error';
    if (v == v.truncate() && v.abs() < 1e15) {
      return v.toInt().toString();
    }
    var s = v.toStringAsFixed(10);
    if (s.contains('.')) {
      s = s.replaceFirst(RegExp(r'0+$'), '');
      s = s.replaceFirst(RegExp(r'\.$'), '');
    }
    return s;
  }

  double? _compute(double a, String op, double b) {
    switch (op) {
      case '+':
        return a + b;
      case '-':
        return a - b;
      case '*':
        return a * b;
      case '/':
        return b == 0 ? double.nan : a / b;
    }
    return null;
  }

  void _pressDigit(String d) {
    setState(() {
      if (_justComputed) {
        _display = d;
        _justComputed = false;
      } else if (_display == '0') {
        _display = d;
      } else {
        _display = _display + d;
      }
    });
  }

  void _pressDot() {
    setState(() {
      if (_justComputed) {
        _display = '0.';
        _justComputed = false;
      } else if (!_display.contains('.')) {
        _display = '$_display.';
      }
    });
  }

  void _pressOp(String op) {
    setState(() {
      final current = double.tryParse(_display) ?? 0;
      if (_pendingValue != null && _pendingOp != null && !_justComputed) {
        final result = _compute(_pendingValue!, _pendingOp!, current);
        if (result != null) {
          _display = _formatNum(result);
          _pendingValue = result;
        }
      } else {
        _pendingValue = current;
      }
      _pendingOp = op;
      _justComputed = true;
    });
  }

  void _pressEquals() {
    setState(() {
      if (_pendingValue != null && _pendingOp != null) {
        final current = double.tryParse(_display) ?? 0;
        final result = _compute(_pendingValue!, _pendingOp!, current);
        if (result != null) {
          _display = _formatNum(result);
          _pendingValue = null;
          _pendingOp = null;
          _justComputed = true;
        }
      }
    });
  }

  void _pressClear() {
    setState(() {
      _display = '0';
      _pendingValue = null;
      _pendingOp = null;
      _justComputed = false;
    });
  }

  void _pressBackspace() {
    setState(() {
      if (_justComputed || _display.length <= 1) {
        _display = '0';
        _justComputed = false;
      } else {
        _display = _display.substring(0, _display.length - 1);
        if (_display == '-') _display = '0';
      }
    });
  }

  void _pressNegate() {
    setState(() {
      if (_display == '0') return;
      if (_display.startsWith('-')) {
        _display = _display.substring(1);
      } else {
        _display = '-$_display';
      }
    });
  }

  Widget _calcButton(String label,
      {Color? bg,
      Color? fg,
      VoidCallback? onPressed,
      int flex = 1,
      bool compact = false}) {
    // compact=true でモバイル向けに詰めたサイズにする
    return Expanded(
      flex: flex,
      child: Padding(
        padding: EdgeInsets.all(compact ? 2 : 3),
        child: ElevatedButton(
          style: ElevatedButton.styleFrom(
            backgroundColor: bg ?? const Color(0xFF2A2A3E),
            foregroundColor: fg ?? Colors.white,
            padding: EdgeInsets.symmetric(vertical: compact ? 9 : 14),
            minimumSize: Size.zero,
            tapTargetSize: MaterialTapTargetSize.shrinkWrap,
            shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(compact ? 6 : 8)),
          ),
          onPressed: onPressed,
          child: Text(label,
              style: TextStyle(
                  fontSize: compact ? 14 : 18, fontWeight: FontWeight.w600)),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final mq = MediaQuery.of(context);
    final screen = mq.size;
    // モバイル (狭い画面) ではよりコンパクトなサイズに切り替える
    final bool isMobile = screen.width < 600;
    // 画面外に飛び出さないよう左上位置をクランプ
    // 旧サイズ: 220x340 → モバイルで操作しやすい 180x280 に縮小
    final double panelW = isMobile ? 180.0 : 300.0;
    final double panelH = isMobile ? 280.0 : 440.0;
    // 折り畳み時はヘッダーのみ表示するので、共通の小さな幅に揃える。
    // (展開ボタンを押すと panelW に戻る)
    final double effectiveW =
        _collapsed ? _collapsedFloatingWidth(isMobile) : panelW;
    // 上端はステータスバー(SafeArea上端)より下、下端はパネルのヘッダー
    // (上端 ~36px) だけが画面内に残れば OK。これによりユーザーが「画面下端
    // 近くに置きたい」場合でもドラッグで動かせる(旧実装はパネル全体が
    // 画面内に収まる位置までしか動かせず、下半分しか移動できなかった)。
    const double headerVisible = 36.0;
    final double safeTop = mq.padding.top;
    final double safeBottom = mq.padding.bottom;
    final double maxLeft = (screen.width - effectiveW).clamp(0.0, screen.width);
    final double maxTop = (screen.height - safeBottom - headerVisible)
        .clamp(safeTop, screen.height);
    final clampedLeft = _offset.dx.clamp(0.0, maxLeft);
    final clampedTop = _offset.dy.clamp(safeTop, maxTop);
    // ExcludeFocus: ボタンタップでメインキャンバスの FocusNode がフォーカスを
    // 失い、他のショートカット (Ctrl+S, Ctrl+Z 等) が効かなくなるバグを防ぐ。
    // 計算機の入力は HardwareKeyboard ハンドラ側で処理するためフォーカス不要。
    // パネル本体。 浮かせる時と分割ペインに埋め込む時で同じ物を使う。
    final panel = ExcludeFocus(
          child: Material(
            elevation: 12,
            borderRadius: BorderRadius.circular(14),
            color: Colors.transparent,
            child: Container(
              width: effectiveW,
              decoration: BoxDecoration(
                color: const Color(0xFF1E1E32),
                borderRadius: BorderRadius.circular(14),
                border: Border.all(
                    color: const Color(0xFFBA68C8).withValues(alpha: 0.5),
                    width: 1.5),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withValues(alpha: 0.5),
                    blurRadius: 16,
                    offset: const Offset(0, 6),
                  ),
                ],
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  // ── ドラッグ可能ヘッダー ─────
                  //    隠している時は細い帯だけ残す (= ユーザー要望)。
                  if (_headerHidden)
                    _FloatingToolHiddenHeader(
                      color: const Color(0xFFBA68C8),
                      onShow: () => setState(() => _headerHidden = false),
                    )
                  else
                  GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onPanUpdate: (details) {
                      setState(() {
                        // _offset 自体をクランプして、画面外への蓄積を防ぐ。
                        // これにより、上端まで到達後さらに上へドラッグしても
                        // 余計な「下へ戻す距離」が生じず、すぐ反応する。
                        _offset = Offset(
                          (_offset.dx + details.delta.dx).clamp(0.0, maxLeft),
                          (_offset.dy + details.delta.dy)
                              .clamp(safeTop, maxTop),
                        );
                      });
                    },
                    child: MouseRegion(
                      cursor: SystemMouseCursors.move,
                      child: Container(
                        padding: EdgeInsets.symmetric(
                            horizontal: isMobile ? 8 : 10,
                            vertical: isMobile ? 5 : 8),
                        decoration: BoxDecoration(
                          color:
                              const Color(0xFFBA68C8).withValues(alpha: 0.25),
                          borderRadius: const BorderRadius.only(
                            topLeft: Radius.circular(13),
                            topRight: Radius.circular(13),
                          ),
                        ),
                        child: Row(children: [
                          Icon(Icons.drag_indicator_rounded,
                              color: Colors.white54, size: isMobile ? 14 : 16),
                          const SizedBox(width: 4),
                          Icon(Icons.calculate_rounded,
                              color: const Color(0xFFBA68C8),
                              size: isMobile ? 15 : 18),
                          const SizedBox(width: 6),
                          Expanded(
                            child: Text(widget.provider.t('cmd.openCalculator'),
                                style: TextStyle(
                                    color: Colors.white,
                                    fontSize: isMobile ? 11 : 13,
                                    fontWeight: FontWeight.w700)),
                          ),
                          // 折り畳みボタン: タップで本体を非表示にしてヘッダーだけ残す。
                          // 別のフローティングツールと併用したいときに画面占有を抑える用途。
                          MouseRegion(
                            cursor: SystemMouseCursors.click,
                            child: GestureDetector(
                              onTap: () =>
                                  setState(() => _collapsed = !_collapsed),
                              child: Padding(
                                padding: EdgeInsets.all(isMobile ? 3 : 4),
                                child: Icon(
                                    _collapsed
                                        ? Icons.expand_more_rounded
                                        : Icons.expand_less_rounded,
                                    color: Colors.white70,
                                    size: isMobile ? 16 : 18),
                              ),
                            ),
                          ),
                          // ── ヘッダーを隠す (= ユーザー要望: 他と同様、
                          //    隠した後はカーソルを乗せた時だけ表示ボタンが
                          //    出るように) ──
                          MouseRegion(
                            cursor: SystemMouseCursors.click,
                            child: GestureDetector(
                              onTap: () =>
                                  setState(() => _headerHidden = true),
                              child: Padding(
                                padding: EdgeInsets.all(isMobile ? 3 : 4),
                                child: Icon(
                                    Icons.keyboard_double_arrow_up_rounded,
                                    color: Colors.white54,
                                    size: isMobile ? 14 : 16),
                              ),
                            ),
                          ),
                          MouseRegion(
                            cursor: SystemMouseCursors.click,
                            child: GestureDetector(
                              onTap: widget.onClose,
                              child: Padding(
                                padding: EdgeInsets.all(isMobile ? 3 : 4),
                                child: Icon(Icons.close,
                                    color: Colors.white54,
                                    size: isMobile ? 14 : 16),
                              ),
                            ),
                          ),
                        ]),
                      ),
                    ),
                  ),
                  // ── 本体（ディスプレイ + ボタン）─────
                  // 折り畳み中はヘッダーだけ残してボタンを隠す。state は維持されるので
                  // 再度開くと直前の計算続きから操作できる。
                  if (!_collapsed)
                    Padding(
                      padding: EdgeInsets.all(isMobile ? 6 : 10),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Container(
                            width: double.infinity,
                            padding: EdgeInsets.all(isMobile ? 10 : 16),
                            margin: const EdgeInsets.only(bottom: 6),
                            decoration: BoxDecoration(
                              color: const Color(0xFF0B0B1E),
                              borderRadius: BorderRadius.circular(8),
                              border: Border.all(color: Colors.white12),
                            ),
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.end,
                              children: [
                                if (_pendingValue != null && _pendingOp != null)
                                  Text(
                                    '${_formatNum(_pendingValue!)} ${_pendingOp!.replaceAll('*', '×').replaceAll('/', '÷')}',
                                    style: TextStyle(
                                        color: Colors.white38,
                                        fontSize: isMobile ? 10 : 12,
                                        fontFamily: 'monospace'),
                                  ),
                                Text(_display,
                                    style: TextStyle(
                                        color: Colors.white,
                                        fontSize: isMobile ? 20 : 26,
                                        fontFamily: 'monospace',
                                        fontWeight: FontWeight.w700)),
                              ],
                            ),
                          ),
                          Row(children: [
                            _calcButton('C',
                                compact: isMobile,
                                bg: const Color(0xFFFF6B6B)
                                    .withValues(alpha: 0.8),
                                onPressed: _pressClear),
                            _calcButton('⌫',
                                compact: isMobile,
                                bg: const Color(0xFF555577),
                                onPressed: _pressBackspace),
                            _calcButton('±',
                                compact: isMobile,
                                bg: const Color(0xFF555577),
                                onPressed: _pressNegate),
                            _calcButton('÷',
                                compact: isMobile,
                                bg: const Color(0xFFBA68C8),
                                onPressed: () => _pressOp('/')),
                          ]),
                          Row(children: [
                            _calcButton('7',
                                compact: isMobile,
                                onPressed: () => _pressDigit('7')),
                            _calcButton('8',
                                compact: isMobile,
                                onPressed: () => _pressDigit('8')),
                            _calcButton('9',
                                compact: isMobile,
                                onPressed: () => _pressDigit('9')),
                            _calcButton('×',
                                compact: isMobile,
                                bg: const Color(0xFFBA68C8),
                                onPressed: () => _pressOp('*')),
                          ]),
                          Row(children: [
                            _calcButton('4',
                                compact: isMobile,
                                onPressed: () => _pressDigit('4')),
                            _calcButton('5',
                                compact: isMobile,
                                onPressed: () => _pressDigit('5')),
                            _calcButton('6',
                                compact: isMobile,
                                onPressed: () => _pressDigit('6')),
                            _calcButton('-',
                                compact: isMobile,
                                bg: const Color(0xFFBA68C8),
                                onPressed: () => _pressOp('-')),
                          ]),
                          Row(children: [
                            _calcButton('1',
                                compact: isMobile,
                                onPressed: () => _pressDigit('1')),
                            _calcButton('2',
                                compact: isMobile,
                                onPressed: () => _pressDigit('2')),
                            _calcButton('3',
                                compact: isMobile,
                                onPressed: () => _pressDigit('3')),
                            _calcButton('+',
                                compact: isMobile,
                                bg: const Color(0xFFBA68C8),
                                onPressed: () => _pressOp('+')),
                          ]),
                          Row(children: [
                            _calcButton('0',
                                compact: isMobile,
                                flex: 2,
                                onPressed: () => _pressDigit('0')),
                            _calcButton('.',
                                compact: isMobile, onPressed: _pressDot),
                            _calcButton('=',
                                compact: isMobile,
                                bg: const Color(0xFF43B97F),
                                onPressed: _pressEquals),
                          ]),
                        ],
                      ),
                    ),
                ],
              ),
            ),
          ),
        ); // panel
    // ── 分割ペインへの埋め込み (= ユーザー要望: 分割画面に置いたボタンから
    //    開いた時は、 浮かせずにそのペインいっぱいに開く) ──
    //    ペインの大きさに合わせて拡大する。 ドラッグ用の _offset は使わない。
    if (widget.embedded) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(8),
          child: FittedBox(fit: BoxFit.contain, child: panel),
        ),
      );
    }
    // ── 裏に隠す処理 ──
    // Positioned 自体は Stack (= Overlay) の直接の子でなければならない
    // ので、Offstage は Positioned の child 側で適用する。
    // Offstage(offstage:true) は paint・hit-test されないが State は維持
    // されるので、計算結果や入力中の式はカレンダー操作後も生きている。
    return Positioned(
      left: clampedLeft,
      top: clampedTop,
      child: Offstage(offstage: widget.hidden, child: panel),
    );
  }
}

/// フローティングストップウォッチ/タイマー パネル（Ctrl+T で起動）
/// - 2 タブ: ストップウォッチ / タイマー
/// - 非モーダル (背景の画面操作 & ショートカットがそのまま使える)
/// - ヘッダーをドラッグして移動可
/// - ストップウォッチ: スタート/停止/ラップ（最大 5 件履歴）
/// - タイマー: 時・分・秒を指定してカウントダウン、0 で通知音を鳴らす
class _FloatingStopwatch extends StatefulWidget {
  final MindMapProvider provider;
  final Offset initialOffset;
  final VoidCallback onClose;
  final bool hidden;
  const _FloatingStopwatch({
    required this.provider,
    required this.initialOffset,
    required this.onClose,
    this.hidden = false,
  });
  @override
  State<_FloatingStopwatch> createState() => _FloatingStopwatchState();
}

class _FloatingStopwatchState extends State<_FloatingStopwatch> {

  /// ヘッダーを隠しているか (= ユーザー要望: 他と同様に隠せるように)。
  bool _headerHidden = false;
  late Offset _offset;

  /// 0=ストップウォッチ, 1=タイマー
  int _tabIndex = 0;

  /// 折り畳み状態 (true ならヘッダーだけ表示)。タイマー稼働中も折り畳めるよう、
  /// 内部の Timer はそのまま動かし続ける。
  bool _collapsed = false;

  /// モバイル(狭い画面)かどうかを判定するヘルパー。
  /// 子ウィジェットビルダ (_buildStopwatchBody 等) も同じロジックで縮小する。
  bool get _isMobileScreen => MediaQuery.of(context).size.width < 600;

  // ── ストップウォッチ側 ──
  final Stopwatch _stopwatch = Stopwatch();
  Timer? _swTick;

  /// ラップ履歴: 新しいもの先頭、最大 3 件
  final List<Duration> _laps = [];

  /// 過去の完了履歴（スタート→リセットの区切りで保存）最大 3 件
  final List<Duration> _swHistory = [];

  // ── タイマー側 ──
  int _timerHours = 0;
  int _timerMinutes = 5;
  int _timerSeconds = 0;

  /// 実行中の残り時間 (ミリ秒)
  int? _timerRemainMs;
  Timer? _timerTick;
  DateTime? _timerEndAt;

  /// タイマー終了時にアラーム音を鳴らす (トグル可能)
  bool _alarmSoundEnabled = true;

  /// タイマー終了時にシステム通知（Windows/Android 等）を出す (トグル可能)
  /// ※外部プラグインなしの範囲で: アプリを前面に引き戻し + SystemSound + SnackBar
  bool _notifySystemEnabled = true;

  // 注: 旧実装では FocusNode + KeyboardListener で Esc を受けていたが、
  // 本体のメインキャンバス (_keyboardFocusNode) からフォーカスを奪ってしまい、
  // ストップウォッチを開いた後に他のショートカット (Ctrl+S 等) が効かなくなる
  // バグがあった。電卓と同様に HardwareKeyboard にハンドラを直接登録する方式へ変更。

  @override
  void initState() {
    super.initState();
    _offset = widget.initialOffset;
    // Esc キーだけを拾うための軽量ハンドラ
    HardwareKeyboard.instance.addHandler(_handleKey);
  }

  @override
  void dispose() {
    HardwareKeyboard.instance.removeHandler(_handleKey);
    _swTick?.cancel();
    _stopwatch.stop();
    _timerTick?.cancel();
    // wakelock を念のため OFF にしておく (タイマー実行中のままウィンドウ
    // を閉じたケースで disable し忘れないように)。
    try {
      WakelockPlus.disable();
    } catch (_) {}
    super.dispose();
  }

  /// Esc でストップウォッチを閉じる。それ以外のキーは背景に委譲。
  bool _handleKey(KeyEvent event) {
    if (event is! KeyDownEvent) return false;
    // テキスト編集中 (タイマーの時/分/秒入力など) は干渉しない
    final focused = FocusManager.instance.primaryFocus;
    if (focused != null && focused.context?.widget is EditableText) {
      return false;
    }
    // Ctrl/Meta 押下中は背景のショートカットに委譲
    final isCtrl = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    if (isCtrl) return false;
    if (event.logicalKey == LogicalKeyboardKey.escape) {
      // Esc で折り畳み/展開をトグル。Tick は継続するので残時間は進み続ける。
      setState(() => _collapsed = !_collapsed);
      return true;
    }
    return false;
  }

  String _formatDuration(Duration d) {
    final h = d.inHours;
    final m = d.inMinutes.remainder(60);
    final s = d.inSeconds.remainder(60);
    final cs = (d.inMilliseconds.remainder(1000) ~/ 10);
    if (h > 0) {
      return '${h.toString().padLeft(2, '0')}:'
          '${m.toString().padLeft(2, '0')}:'
          '${s.toString().padLeft(2, '0')}.'
          '${cs.toString().padLeft(2, '0')}';
    }
    return '${m.toString().padLeft(2, '0')}:'
        '${s.toString().padLeft(2, '0')}.'
        '${cs.toString().padLeft(2, '0')}';
  }

  String _formatTimerRemain(int remainMs) {
    final d = Duration(milliseconds: remainMs < 0 ? 0 : remainMs);
    final h = d.inHours;
    final m = d.inMinutes.remainder(60);
    final s = d.inSeconds.remainder(60);
    return '${h.toString().padLeft(2, '0')}:'
        '${m.toString().padLeft(2, '0')}:'
        '${s.toString().padLeft(2, '0')}';
  }

  // ── ストップウォッチ操作 ──
  void _swStartOrStop() {
    if (_stopwatch.isRunning) {
      _stopwatch.stop();
      _swTick?.cancel();
      _swTick = null;
      setState(() {});
    } else {
      _stopwatch.start();
      _swTick = Timer.periodic(const Duration(milliseconds: 50), (_) {
        if (mounted) setState(() {});
      });
      setState(() {});
    }
  }

  void _swReset() {
    // 現在の計測を履歴に積む（> 0 の時）
    if (_stopwatch.elapsed.inMilliseconds > 0) {
      _swHistory.insert(0, _stopwatch.elapsed);
      while (_swHistory.length > 3) {
        _swHistory.removeLast();
      }
    }
    _stopwatch.stop();
    _stopwatch.reset();
    _swTick?.cancel();
    _swTick = null;
    _laps.clear();
    setState(() {});
  }

  void _swLap() {
    if (_stopwatch.isRunning) {
      _laps.insert(0, _stopwatch.elapsed);
      // ラップも最大 3 件で制限
      while (_laps.length > 3) {
        _laps.removeLast();
      }
      setState(() {});
    }
  }

  // ── タイマー操作 ──
  int _timerTotalMs() =>
      ((_timerHours * 3600) + (_timerMinutes * 60) + _timerSeconds) * 1000;

  void _timerStart() {
    if (_timerRemainMs != null && _timerRemainMs! > 0) {
      // 一時停止からの再開
      _timerEndAt = DateTime.now().add(Duration(milliseconds: _timerRemainMs!));
    } else {
      final total = _timerTotalMs();
      if (total <= 0) return;
      _timerRemainMs = total;
      _timerEndAt = DateTime.now().add(Duration(milliseconds: total));
    }
    // 画面ロック防止 ON。画面オフで Activity が onStop に入っても
    // タイマー自体は実時間ベース (_timerEndAt) で動くが、Android では
    // Doze モードに入ると Timer.periodic の発火頻度が落ちる。画面 ON
    // を維持することで Doze を回避し、終了通知 (_timerNotify) も確実に
    // 発火する。タイマー停止 (_timerPause / _timerReset / 終了) で OFF。
    try {
      WakelockPlus.enable();
    } catch (_) {}
    _timerTick?.cancel();
    _timerTick = Timer.periodic(const Duration(milliseconds: 100), (_) {
      if (!mounted) return;
      if (_timerEndAt == null) return;
      final now = DateTime.now();
      final remain = _timerEndAt!.difference(now).inMilliseconds;
      if (remain <= 0) {
        setState(() {
          _timerRemainMs = 0;
          _timerEndAt = null;
        });
        _timerTick?.cancel();
        _timerTick = null;
        // タイマー終了 → wakelock OFF。
        try {
          WakelockPlus.disable();
        } catch (_) {}
        _timerNotify();
      } else {
        setState(() => _timerRemainMs = remain);
      }
    });
    setState(() {});
  }

  void _timerPause() {
    _timerTick?.cancel();
    _timerTick = null;
    if (_timerEndAt != null) {
      final now = DateTime.now();
      _timerRemainMs = _timerEndAt!.difference(now).inMilliseconds;
      if (_timerRemainMs! < 0) _timerRemainMs = 0;
    }
    _timerEndAt = null;
    // 一時停止 → wakelock OFF (再開時に再度 enable)。
    try {
      WakelockPlus.disable();
    } catch (_) {}
    setState(() {});
  }

  void _timerReset() {
    _timerTick?.cancel();
    _timerTick = null;
    _timerRemainMs = null;
    _timerEndAt = null;
    try {
      WakelockPlus.disable();
    } catch (_) {}
    setState(() {});
  }

  /// タイマー終了時の通知
  /// - 音: _alarmSoundEnabled が true なら _AudioAlarm.playAlarm
  ///   * ユーザーがカスタム音 (mp3/mp4 等) を設定していればそれを鳴らす
  ///   * 未設定 / 再生失敗時は SystemSound.alert を 8 連打する大きめの既定音
  /// - システム通知: _notifySystemEnabled が true なら
  ///   * ウィンドウを前面に復帰（Windows/Linux/macOS 対応）
  ///   * アプリ内バナー（SnackBar）
  void _timerNotify() async {
    // 1) 音声フィードバック（設定で OFF 可能）
    if (_alarmSoundEnabled) {
      // カスタム音があればそちら、無ければ強化された既定音 (8 連打) を再生。
      // 旧実装は SystemSound.alert を 3 回だけだったが、見落としやすいと
      // 指摘があり、ヘルパ側でデフォルトを倍以上に強化した。
      _AudioAlarm.playAlarm(_AudioAlarm.prefKeyTimer);
    } else {
      // 音 OFF でも軽いクリック音＋触覚だけは出す（気付き用）
      SystemSound.play(SystemSoundType.click);
      HapticFeedback.mediumImpact();
    }

    // 2) システム通知 = アプリを前面に復帰（Windows/Linux/macOS）
    //    モバイルでは効果ないがエラーにもならない
    if (_notifySystemEnabled) {
      try {
        // アプリが最小化されていれば復元、非アクティブなら前面化
        final isMin = await windowManager.isMinimized();
        if (isMin) {
          await windowManager.restore();
        }
        await windowManager.show();
        await windowManager.focus();
        // Windows のタスクバーで点滅（注意喚起）
        // flash は対応プラットフォームのみ動作（Win32 FlashWindow）
        await windowManager.setAlwaysOnTop(true);
        await Future.delayed(const Duration(milliseconds: 2000));
        await windowManager.setAlwaysOnTop(false);
      } catch (_) {
        // 非デスクトップや window_manager 未初期化でもクラッシュさせない
      }
    }

    if (!mounted) return;
    // 3) アプリ内バナー
    _appSnack(
        context,
        SnackBar(
          content: Row(children: [
            const Icon(Icons.alarm_rounded, color: Colors.white),
            const SizedBox(width: 8),
            Text(context.read<MindMapProvider>().t('timer.finished'),
                style: const TextStyle(fontWeight: FontWeight.w700)),
          ]),
          backgroundColor: const Color(0xFFFF6B6B),
          duration: const Duration(seconds: 6),
          action: SnackBarAction(
            label: context.read<MindMapProvider>().t('btn.close'),
            textColor: Colors.white,
            onPressed: () {
              ScaffoldMessenger.of(context).hideCurrentSnackBar();
            },
          ),
        ));
  }

  bool get _timerRunning => _timerTick != null;
  bool get _timerPaused =>
      !_timerRunning && _timerRemainMs != null && _timerRemainMs! > 0;

  @override
  Widget build(BuildContext context) {
    final mq = MediaQuery.of(context);
    final screen = mq.size;
    // モバイル (狭い画面) ではコンパクトサイズに切り替える
    final bool isMobile = screen.width < 600;
    final double panelW = isMobile
        ? math.min(320.0, math.max(260.0, screen.width - 16.0))
        : 360.0;
    final double panelH = isMobile ? 320.0 : 500.0;
    // 折り畳み時はヘッダーのみ。共通の小さな幅に揃える。
    final double effectiveW =
        _collapsed ? _collapsedFloatingWidth(isMobile) : panelW;
    // ヘッダー (上端 ~36px) だけ画面内に残れば下端ぎりぎりまで動かせる。
    // 旧実装は panelH 全体を引いていたので画面下半分にしか移動できなかった。
    const double headerVisible = 36.0;
    final double safeTop = mq.padding.top;
    final double safeBottom = mq.padding.bottom;
    final double maxLeft = (screen.width - effectiveW).clamp(0.0, screen.width);
    final double maxTop = (screen.height - safeBottom - headerVisible)
        .clamp(safeTop, screen.height);
    final clampedLeft = _offset.dx.clamp(0.0, maxLeft);
    final clampedTop = _offset.dy.clamp(safeTop, maxTop);
    // ExcludeFocus: ボタンタップでメインキャンバスの FocusNode がフォーカスを
    // 失い、他のショートカット (Ctrl+S, Ctrl+Z 等) が効かなくなるバグを防ぐ。
    return Positioned(
      left: clampedLeft,
      top: clampedTop,
      // Offstage で裏に隠す (タイマー State は維持)。
      child: Offstage(
        offstage: widget.hidden,
        child: ExcludeFocus(
          child: Material(
            elevation: 12,
            borderRadius: BorderRadius.circular(14),
            color: Colors.transparent,
            child: Container(
              width: effectiveW,
              decoration: BoxDecoration(
                color: const Color(0xFF1E1E32),
                borderRadius: BorderRadius.circular(14),
                border: Border.all(
                    color: const Color(0xFF4FC3F7).withValues(alpha: 0.5),
                    width: 1.5),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withValues(alpha: 0.5),
                    blurRadius: 16,
                    offset: const Offset(0, 6),
                  ),
                ],
              ),
              // 旧: KeyboardListener(focusNode: _focusNode, autofocus: true, ...)
              // 削除済み — フォーカス奪取によるショートカット機能喪失バグを避けるため
              // Esc キーは HardwareKeyboard.addHandler 側で処理する
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  // ── ドラッグ可能ヘッダー ─────
                  //    隠している時は細い帯だけ残す (= ユーザー要望)。
                  if (_headerHidden)
                    _FloatingToolHiddenHeader(
                      color: const Color(0xFF4FC3F7),
                      onShow: () => setState(() => _headerHidden = false),
                    )
                  else
                  GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onPanUpdate: (details) {
                      setState(() {
                        // _offset 自体をクランプして、画面外への蓄積を防ぐ。
                        // 計算機と同様、上端到達後さらに上にドラッグした際の
                        // 「動かせない」問題を防ぐ。
                        _offset = Offset(
                          (_offset.dx + details.delta.dx).clamp(0.0, maxLeft),
                          (_offset.dy + details.delta.dy)
                              .clamp(safeTop, maxTop),
                        );
                      });
                    },
                    child: MouseRegion(
                      cursor: SystemMouseCursors.move,
                      child: Container(
                        padding: EdgeInsets.symmetric(
                            horizontal: isMobile ? 8 : 10,
                            vertical: isMobile ? 5 : 8),
                        decoration: BoxDecoration(
                          color:
                              const Color(0xFF4FC3F7).withValues(alpha: 0.22),
                          borderRadius: const BorderRadius.only(
                            topLeft: Radius.circular(13),
                            topRight: Radius.circular(13),
                          ),
                        ),
                        child: Row(children: [
                          Icon(Icons.drag_indicator_rounded,
                              color: Colors.white54, size: isMobile ? 14 : 16),
                          const SizedBox(width: 4),
                          Icon(
                              _tabIndex == 0
                                  ? Icons.timer_rounded
                                  : Icons.hourglass_bottom_rounded,
                              color: const Color(0xFF4FC3F7),
                              size: isMobile ? 15 : 18),
                          const SizedBox(width: 6),
                          Expanded(
                            child: Text(widget.provider.t('cmd.openStopwatch'),
                                style: TextStyle(
                                    color: Colors.white,
                                    fontSize: isMobile ? 11 : 13,
                                    fontWeight: FontWeight.w700)),
                          ),
                          MouseRegion(
                            cursor: SystemMouseCursors.click,
                            child: GestureDetector(
                              onTap: () =>
                                  setState(() => _collapsed = !_collapsed),
                              child: Padding(
                                padding: EdgeInsets.all(isMobile ? 3 : 4),
                                child: Icon(
                                    _collapsed
                                        ? Icons.expand_more_rounded
                                        : Icons.expand_less_rounded,
                                    color: Colors.white70,
                                    size: isMobile ? 16 : 18),
                              ),
                            ),
                          ),
                          // ── ヘッダーを隠す (= ユーザー要望: 他と同様、
                          //    隠した後はカーソルを乗せた時だけ表示ボタンが
                          //    出るように) ──
                          MouseRegion(
                            cursor: SystemMouseCursors.click,
                            child: GestureDetector(
                              onTap: () =>
                                  setState(() => _headerHidden = true),
                              child: Padding(
                                padding: EdgeInsets.all(isMobile ? 3 : 4),
                                child: Icon(
                                    Icons.keyboard_double_arrow_up_rounded,
                                    color: Colors.white54,
                                    size: isMobile ? 14 : 16),
                              ),
                            ),
                          ),
                          MouseRegion(
                            cursor: SystemMouseCursors.click,
                            child: GestureDetector(
                              onTap: widget.onClose,
                              child: Padding(
                                padding: EdgeInsets.all(isMobile ? 3 : 4),
                                child: Icon(Icons.close,
                                    color: Colors.white54,
                                    size: isMobile ? 14 : 16),
                              ),
                            ),
                          ),
                        ]),
                      ),
                    ),
                  ),
                  // ── タブ切替 ─────
                  // 折り畳み中は隠す。Timer/Stopwatch の Tick は維持されるので
                  // 再度開いた時経過時間がそのまま続いている。
                  if (!_collapsed)
                    Container(
                      padding: EdgeInsets.all(isMobile ? 4 : 6),
                      child: Row(children: [
                        Expanded(
                          child: _buildTabButton(
                              label: widget.provider.t('stopwatch.tab'),
                              icon: Icons.timer_outlined,
                              selected: _tabIndex == 0,
                              onTap: () => setState(() => _tabIndex = 0)),
                        ),
                        const SizedBox(width: 6),
                        Expanded(
                          child: _buildTabButton(
                              label: widget.provider.t('timer.tab'),
                              icon: Icons.hourglass_bottom,
                              selected: _tabIndex == 1,
                              onTap: () => setState(() => _tabIndex = 1)),
                        ),
                      ]),
                    ),
                  // ── 本体（タブに応じて切替）─────
                  if (!_collapsed)
                    Padding(
                      padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
                      child: _tabIndex == 0
                          ? _buildStopwatchBody()
                          : _buildTimerBody(),
                    ),
                ],
              ), // Column
            ), // Container
          ), // Material
        ), // ExcludeFocus
      ), // Offstage
    ); // Positioned
  }

  Widget _buildTabButton({
    required String label,
    required IconData icon,
    required bool selected,
    required VoidCallback onTap,
  }) {
    final bool m = _isMobileScreen;
    return GestureDetector(
      onTap: onTap,
      child: Container(
        padding:
            EdgeInsets.symmetric(vertical: m ? 6 : 8, horizontal: m ? 8 : 10),
        decoration: BoxDecoration(
          color: selected
              ? const Color(0xFF4FC3F7).withValues(alpha: 0.25)
              : Colors.white.withValues(alpha: 0.04),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(
              color: selected
                  ? const Color(0xFF4FC3F7).withValues(alpha: 0.7)
                  : Colors.white12),
        ),
        child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
          Icon(icon,
              size: m ? 13 : 15,
              color: selected ? const Color(0xFF4FC3F7) : Colors.white54),
          const SizedBox(width: 6),
          Text(label,
              style: TextStyle(
                  color: selected ? Colors.white : Colors.white60,
                  fontSize: m ? 10 : 12,
                  fontWeight: selected ? FontWeight.w700 : FontWeight.w500)),
        ]),
      ),
    );
  }

  // ══════════════════════════════════════════════════════════════════
  // ストップウォッチタブ
  // ══════════════════════════════════════════════════════════════════
  Widget _buildStopwatchBody() {
    final bool m = _isMobileScreen;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Container(
          width: double.infinity,
          padding: EdgeInsets.symmetric(vertical: m ? 14 : 22),
          decoration: BoxDecoration(
            color: const Color(0xFF0B0B1E),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(
              color: _stopwatch.isRunning
                  ? const Color(0xFF43B97F).withValues(alpha: 0.5)
                  : Colors.white12,
              width: 2,
            ),
          ),
          alignment: Alignment.center,
          child: Text(
            _formatDuration(_stopwatch.elapsed),
            style: TextStyle(
                color: Colors.white,
                fontSize: m ? 24 : 32,
                fontFamily: 'monospace',
                fontWeight: FontWeight.w700),
          ),
        ),
        SizedBox(height: m ? 6 : 10),
        // 操作ボタン
        Row(children: [
          Expanded(
            child: ElevatedButton.icon(
              icon: Icon(
                  _stopwatch.isRunning
                      ? Icons.pause_rounded
                      : Icons.play_arrow_rounded,
                  size: m ? 14 : 18),
              label: Text(
                  _stopwatch.isRunning
                      ? widget.provider.t('stopwatch.stop')
                      : widget.provider.t('stopwatch.start'),
                  style: TextStyle(
                      fontSize: m ? 10 : 12, fontWeight: FontWeight.w700)),
              style: ElevatedButton.styleFrom(
                backgroundColor: _stopwatch.isRunning
                    ? const Color(0xFFFFB347)
                    : const Color(0xFF43B97F),
                foregroundColor: Colors.white,
                padding: const EdgeInsets.symmetric(vertical: 10),
              ),
              onPressed: _swStartOrStop,
            ),
          ),
          const SizedBox(width: 6),
          Expanded(
            child: ElevatedButton.icon(
              icon: const Icon(Icons.flag_rounded, size: 14),
              label: Text(widget.provider.t('stopwatch.lap'),
                  style: const TextStyle(
                      fontSize: 12, fontWeight: FontWeight.w700)),
              style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFBA68C8),
                foregroundColor: Colors.white,
                padding: const EdgeInsets.symmetric(vertical: 10),
              ),
              onPressed: _stopwatch.isRunning ? _swLap : null,
            ),
          ),
          const SizedBox(width: 6),
          Expanded(
            child: ElevatedButton.icon(
              icon: const Icon(Icons.restart_alt_rounded, size: 14),
              label: Text(widget.provider.t('stopwatch.reset'),
                  style: const TextStyle(
                      fontSize: 12, fontWeight: FontWeight.w700)),
              style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFFF6B6B),
                foregroundColor: Colors.white,
                padding: const EdgeInsets.symmetric(vertical: 10),
              ),
              onPressed:
                  (_stopwatch.elapsed.inMilliseconds > 0 || _laps.isNotEmpty)
                      ? _swReset
                      : null,
            ),
          ),
        ]),
        // ラップ一覧（現在の計測中）
        if (_laps.isNotEmpty) ...[
          const SizedBox(height: 10),
          const Divider(color: Colors.white12, height: 1),
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 6),
            child: Row(children: [
              const Icon(Icons.flag, color: Color(0xFFBA68C8), size: 12),
              const SizedBox(width: 4),
              Text(context.read<MindMapProvider>().t('sw.lap'),
                  style: const TextStyle(
                      color: Colors.white38,
                      fontSize: 10,
                      fontWeight: FontWeight.w700)),
            ]),
          ),
          SizedBox(
            height: 90,
            child: ListView.builder(
              itemCount: _laps.length,
              itemBuilder: (_, i) {
                final total = _laps[i];
                final lapNum = _laps.length - i;
                final diff =
                    i < _laps.length - 1 ? total - _laps[i + 1] : total;
                return Padding(
                  padding: const EdgeInsets.symmetric(vertical: 2),
                  child: Row(children: [
                    SizedBox(
                      width: 28,
                      child: Text('#$lapNum',
                          style: const TextStyle(
                              color: Colors.white54,
                              fontSize: 11,
                              fontWeight: FontWeight.w700)),
                    ),
                    Expanded(
                      child: Text('+${_formatDuration(diff)}',
                          style: const TextStyle(
                              color: Color(0xFF4FC3F7),
                              fontSize: 11,
                              fontFamily: 'monospace')),
                    ),
                    Text(_formatDuration(total),
                        style: const TextStyle(
                            color: Colors.white70,
                            fontSize: 11,
                            fontFamily: 'monospace')),
                  ]),
                );
              },
            ),
          ),
        ],
        // 過去の完了履歴
        if (_swHistory.isNotEmpty) ...[
          const SizedBox(height: 8),
          const Divider(color: Colors.white12, height: 1),
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 6),
            child: Row(children: [
              const Icon(Icons.history, color: Color(0xFF00E5FF), size: 12),
              const SizedBox(width: 4),
              Text(context.read<MindMapProvider>().t('sw.history'),
                  style: TextStyle(
                      color: Colors.white38,
                      fontSize: 10,
                      fontWeight: FontWeight.w700)),
              const Spacer(),
              GestureDetector(
                onTap: () => setState(_swHistory.clear),
                child: const Icon(Icons.clear_all,
                    color: Colors.white38, size: 14),
              ),
            ]),
          ),
          SizedBox(
            height: 80,
            child: ListView.builder(
              itemCount: _swHistory.length,
              itemBuilder: (_, i) {
                return Padding(
                  padding: const EdgeInsets.symmetric(vertical: 2),
                  child: Row(children: [
                    SizedBox(
                      width: 28,
                      child: Text('#${i + 1}',
                          style: const TextStyle(
                              color: Colors.white38,
                              fontSize: 11,
                              fontWeight: FontWeight.w700)),
                    ),
                    Expanded(
                      child: Text(_formatDuration(_swHistory[i]),
                          style: const TextStyle(
                              color: Color(0xFF00E5FF),
                              fontSize: 11,
                              fontFamily: 'monospace')),
                    ),
                  ]),
                );
              },
            ),
          ),
        ],
      ],
    );
  }

  // ══════════════════════════════════════════════════════════════════
  // タイマータブ
  // ══════════════════════════════════════════════════════════════════
  Widget _buildTimerBody() {
    // 表示する残り時間（実行中/停止中/未開始で切り替え）
    final int showMs = _timerRemainMs ?? _timerTotalMs();
    final double progress = () {
      final total = _timerTotalMs();
      if (total <= 0 || _timerRemainMs == null) return 0.0;
      return ((total - _timerRemainMs!) / total).clamp(0.0, 1.0);
    }();
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        // 表示領域（プログレスバー付き）
        Container(
          width: double.infinity,
          padding: const EdgeInsets.symmetric(vertical: 20),
          decoration: BoxDecoration(
            color: const Color(0xFF0B0B1E),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(
              color: _timerRunning
                  ? const Color(0xFF43B97F).withValues(alpha: 0.5)
                  : Colors.white12,
              width: 2,
            ),
          ),
          child: Column(children: [
            Text(
              _formatTimerRemain(showMs),
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 32,
                  fontFamily: 'monospace',
                  fontWeight: FontWeight.w700),
            ),
            if (_timerRemainMs != null) ...[
              const SizedBox(height: 8),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 20),
                child: LinearProgressIndicator(
                  value: progress,
                  backgroundColor: Colors.white12,
                  valueColor: const AlwaysStoppedAnimation(Color(0xFF43B97F)),
                  minHeight: 4,
                ),
              ),
            ],
          ]),
        ),
        const SizedBox(height: 10),
        // 時間選択 (未開始時のみ編集可能)
        if (_timerRemainMs == null) ...[
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              _buildTimeWheel(
                  value: _timerHours,
                  label: widget.provider.t('timer.hour'),
                  max: 23,
                  onChanged: (v) => setState(() => _timerHours = v)),
              const Text(' : ',
                  style: TextStyle(color: Colors.white, fontSize: 22)),
              _buildTimeWheel(
                  value: _timerMinutes,
                  label: widget.provider.t('timer.minute'),
                  max: 59,
                  onChanged: (v) => setState(() => _timerMinutes = v)),
              const Text(' : ',
                  style: TextStyle(color: Colors.white, fontSize: 22)),
              _buildTimeWheel(
                  value: _timerSeconds,
                  label: widget.provider.t('timer.second'),
                  max: 59,
                  onChanged: (v) => setState(() => _timerSeconds = v)),
            ],
          ),
          const SizedBox(height: 10),
          // プリセット
          // 短時間 (秒単位) + よく使う分数。
          // 不要だった +3分/+10分/+25分 は削除し、代わりに +10秒を先頭に追加。
          Wrap(
            spacing: 6,
            runSpacing: 6,
            alignment: WrapAlignment.center,
            children: [
              _timerPreset(
                  widget.provider
                      .t('timer.presetSeconds')
                      .replaceAll('{n}', '10'),
                  0,
                  0,
                  10),
              _timerPreset(
                  widget.provider
                      .t('timer.presetMinutes')
                      .replaceAll('{n}', '1'),
                  0,
                  1,
                  0),
              _timerPreset(
                  widget.provider
                      .t('timer.presetMinutes')
                      .replaceAll('{n}', '5'),
                  0,
                  5,
                  0),
              _timerPreset(
                  widget.provider
                      .t('timer.presetMinutes')
                      .replaceAll('{n}', '15'),
                  0,
                  15,
                  0),
              _timerPreset(
                  widget.provider
                      .t('timer.presetMinutes')
                      .replaceAll('{n}', '30'),
                  0,
                  30,
                  0),
              _timerPreset(
                  widget.provider
                      .t('timer.presetMinutes')
                      .replaceAll('{n}', '60'),
                  1,
                  0,
                  0),
            ],
          ),
          const SizedBox(height: 10),
        ],
        // 操作ボタン
        Row(children: [
          Expanded(
            child: ElevatedButton.icon(
              icon: Icon(
                  _timerRunning
                      ? Icons.pause_rounded
                      : Icons.play_arrow_rounded,
                  size: 18),
              label: Text(
                  _timerRunning
                      ? widget.provider.t('timer.pause')
                      : _timerPaused
                          ? widget.provider.t('timer.resume')
                          : widget.provider.t('stopwatch.start'),
                  style: const TextStyle(
                      fontSize: 12, fontWeight: FontWeight.w700)),
              style: ElevatedButton.styleFrom(
                backgroundColor: _timerRunning
                    ? const Color(0xFFFFB347)
                    : const Color(0xFF43B97F),
                foregroundColor: Colors.white,
                padding: const EdgeInsets.symmetric(vertical: 10),
              ),
              onPressed: (_timerTotalMs() > 0 || _timerPaused)
                  ? (_timerRunning ? _timerPause : _timerStart)
                  : null,
            ),
          ),
          const SizedBox(width: 6),
          Expanded(
            child: ElevatedButton.icon(
              icon: const Icon(Icons.restart_alt_rounded, size: 14),
              label: Text(widget.provider.t('stopwatch.reset'),
                  style: const TextStyle(
                      fontSize: 12, fontWeight: FontWeight.w700)),
              style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFFF6B6B),
                foregroundColor: Colors.white,
                padding: const EdgeInsets.symmetric(vertical: 10),
              ),
              onPressed: (_timerRemainMs != null) ? _timerReset : null,
            ),
          ),
        ]),
        const SizedBox(height: 10),
        // ── 通知設定（音 ON/OFF + システム通知 ON/OFF）──
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
          decoration: BoxDecoration(
            color: Colors.white.withValues(alpha: 0.04),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: Colors.white12),
          ),
          child: Column(children: [
            // 音
            InkWell(
              onTap: () =>
                  setState(() => _alarmSoundEnabled = !_alarmSoundEnabled),
              borderRadius: BorderRadius.circular(6),
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 4),
                child: Row(children: [
                  Icon(
                      _alarmSoundEnabled
                          ? Icons.volume_up_rounded
                          : Icons.volume_off_rounded,
                      color: _alarmSoundEnabled
                          ? const Color(0xFFFFB347)
                          : Colors.white38,
                      size: 16),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(widget.provider.t('timer.notifySound'),
                        style:
                            const TextStyle(color: Colors.white, fontSize: 11)),
                  ),
                  // カスタム Switch (Material のデフォルトはサイズが大きいため)
                  Container(
                    width: 32,
                    height: 18,
                    decoration: BoxDecoration(
                      color: _alarmSoundEnabled
                          ? const Color(0xFF43B97F)
                          : Colors.white12,
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: AnimatedAlign(
