/// 集中ロックより前面に挿入した専用 Navigator の初期ルート。
///
/// [onOpen] が同 Navigator (`useRootNavigator: false`) にファイルビューアを
/// push し、ビューアが閉じるまで待ってからロック前面 Overlay も片付ける。
/// これによりファイル形式ごとにロック画面の重なり順を実装し直す必要がない。
class _LockFrontContentLauncher extends StatefulWidget {
  final Future<void> Function(BuildContext viewerContext) onOpen;
  final VoidCallback onFinished;

  const _LockFrontContentLauncher({
    required this.onOpen,
    required this.onFinished,
  });

  @override
  State<_LockFrontContentLauncher> createState() =>
      _LockFrontContentLauncherState();
}

class _LockFrontContentLauncherState
    extends State<_LockFrontContentLauncher> {
  bool _started = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _open());
  }

  Future<void> _open() async {
    if (_started || !mounted) return;
    _started = true;
    try {
      await widget.onOpen(context);
    } catch (e) {
      debugPrint('ロック前面ファイルビューアの起動に失敗: $e');
    } finally {
      if (mounted) widget.onFinished();
    }
  }

  @override
  Widget build(BuildContext context) {
    return const PopScope(
      canPop: false,
      child: ColoredBox(
        color: Color(0xFF1A1A24),
        child: Center(child: CircularProgressIndicator()),
      ),
    );
  }
}

// ─── 集中ロック オーバーレイ (Android のみ) ──────────────────────────────
// 設定した時間だけ全画面をロックして集中するためのフルスクリーン UI。
//
// ・PopScope(canPop:false) で「戻る」 を無効化。
// ・SystemUiMode.immersiveSticky でステータス/ナビゲーションバーを隠す。
// ・WakelockPlus で画面 ON を維持し、 カウントダウンが消えないようにする。
// ・終了予定時刻に合わせて OS のローカル通知を予約 (アプリが裏に回っても
//   終了を知らせる)。 自然終了時はアラーム音 + 触覚フィードバックも鳴らす。
// ・緊急時は中央のボタンを 3 秒長押しで早期解除できる (= 完全に閉じ込め
//   ないための安全弁)。
//
// ※ 通常アプリは OS 全体をロックできないため、 これは「アプリ内ロック」。
/// 集中ロック中の YouTube 一覧 (= ユーザー要望: メモの言葉を含まない動画は
/// 見られないようにする)。
///
/// メモから取り出した言葉が動画のタイトルに入っているものだけ再生できる。
/// 入っていないものは灰色にして、 押しても再生しない (理由を出す)。
class _LockYoutubePicker extends StatelessWidget {
  final MindMapProvider provider;
  final List<String> videoIds;
  final List<String> titles;
  final List<String> keywords;
  final void Function(String videoId) onPlay;
  const _LockYoutubePicker({
    required this.provider,
    required this.videoIds,
    required this.titles,
    required this.keywords,
    required this.onPlay,
  });

  @override
  Widget build(BuildContext context) {
    return Dialog(
      backgroundColor: const Color(0xFF14141F),
      insetPadding: const EdgeInsets.all(16),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 560, maxHeight: 640),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 8, 8),
            child: Row(children: [
              const Icon(Icons.smart_display_rounded,
                  color: Color(0xFFEF5350), size: 20),
              const SizedBox(width: 8),
              Expanded(
                child: Text(provider.t('lock.youtubeSearch'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 15,
                        fontWeight: FontWeight.w700)),
              ),
              IconButton(
                icon: const Icon(Icons.close_rounded, color: Colors.white54),
                onPressed: () => Navigator.of(context).pop(),
              ),
            ]),
          ),
          if (keywords.isNotEmpty)
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 8),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text(
                    provider
                        .t('lock.youtubeAllowedWords')
                        .replaceFirst('{words}', keywords.join(' / ')),
                    style: const TextStyle(
                        color: Colors.white38, fontSize: 11, height: 1.5)),
              ),
            ),
          const Divider(height: 1, color: Colors.white12),
          Flexible(
            child: ListView.builder(
              padding: const EdgeInsets.symmetric(vertical: 4),
              itemCount: videoIds.length,
              itemBuilder: (ctx, i) {
                final id = videoIds[i];
                final title = i < titles.length ? titles[i] : '';
                final ok = MindMapProvider.titleMatchesFocusKeywords(
                    title, keywords);
                return ListTile(
                  dense: true,
                  leading: Icon(
                      ok ? Icons.play_circle_rounded : Icons.lock_rounded,
                      color: ok ? const Color(0xFF9CCC65) : Colors.white24,
                      size: 22),
                  title: Text(title.isEmpty ? id : title,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                          color: ok ? Colors.white : Colors.white38,
                          fontSize: 12.5,
                          height: 1.4)),
                  subtitle: ok
                      ? null
                      : Text(provider.t('lock.youtubeBlocked'),
                          style: const TextStyle(
                              color: Color(0xFFEF9A9A), fontSize: 10.5)),
                  onTap: () {
                    if (!ok) {
                      ScaffoldMessenger.maybeOf(ctx)?.showSnackBar(SnackBar(
                        content: Text(provider.t('lock.youtubeBlocked')),
                        duration: const Duration(seconds: 3),
                      ));
                      return;
                    }
                    onPlay(id);
                  },
                );
              },
            ),
          ),
        ]),
      ),
    );
  }
}

/// ロック画面より前で時刻を選ぶための入れ物 (= ユーザー要望: 集中ロックの
/// アラーム設定がロック画面の下に出てしまう)。
///
/// showTimePicker は Navigator を使うため、 root オーバーレイに直接乗せた
/// ロック画面の下に描かれてしまう。 ここでは自前の Navigator を挟んで、
/// ロック画面の「上」 に置いた領域の中でピッカーを開く。
class _LockFrontTimePicker extends StatefulWidget {
  final TimeOfDay initial;
  final void Function(TimeOfDay?) onDone;

  const _LockFrontTimePicker({required this.initial, required this.onDone});

  @override
  State<_LockFrontTimePicker> createState() => _LockFrontTimePickerState();
}

class _LockFrontTimePickerState extends State<_LockFrontTimePicker> {
  @override
  Widget build(BuildContext context) {
    final size = MediaQuery.sizeOf(context);
    return SizedBox(
      width: size.width,
      height: size.height,
      child: Navigator(
        onGenerateRoute: (_) => MaterialPageRoute<void>(
          builder: (navCtx) => _LockFrontTimePickerLauncher(
            initial: widget.initial,
            onDone: widget.onDone,
          ),
        ),
      ),
    );
  }
}

class _LockFrontTimePickerLauncher extends StatefulWidget {
