}

class _FocusLockOverlay extends StatefulWidget {
  final Duration duration;
  final bool taskMode;
  final MindMapProvider provider;
  final Future<void> Function(
    MindMapNode node, {
    BuildContext? presentationContext,
  }) onOpenContent;
  final VoidCallback onClose;

  /// ロック中に選ばれた動画を再生する係 (= ユーザー要望: ロック中でも
  /// メモに関係する動画だけは見られるように)。 本体側の再生機能を借りる。
  final void Function(String url)? onPlayVideo;
  const _FocusLockOverlay({
    required this.duration,
    this.taskMode = false,
    required this.provider,
    required this.onOpenContent,
    required this.onClose,
    this.onPlayVideo,
  });
  @override
  State<_FocusLockOverlay> createState() => _FocusLockOverlayState();
}

class _FocusLockOverlayState extends State<_FocusLockOverlay>
    with WidgetsBindingObserver {
  /// 終了予定時刻 (1 秒積み上げ誤差を避けるため絶対時刻で管理)。
  late final DateTime _endAt;
  late int _remainSec;
  Timer? _tick;

  /// 緊急解除の長押し進捗 (0.0〜1.0)。
  double _holdProgress = 0.0;
  Timer? _holdTimer;

  /// 二重発火防止フラグ。
  bool _finished = false;

  /// 全タスク完了後の解除確認を重ねて表示しないためのフラグ。
  /// キャンセル時は完了チェックもロックも維持し、後から再確認できる。
  bool _taskUnlockConfirmationOpen = false;

  static const String _kLockMemoPrefsKey = 'focus_lock_memos_v2';
  static const String _kLegacyLockMemoPrefsKey = 'focus_lock_memo';

  final List<TextEditingController> _lockMemoCtrls = [
    TextEditingController(),
  ];
  int _activeLockMemoIndex = 0;
  TextEditingController get _lockMemoCtrl => _lockMemoCtrls[
      _activeLockMemoIndex.clamp(0, _lockMemoCtrls.length - 1).toInt()];
  final stt.SpeechToText _lockSpeech = stt.SpeechToText();
  Timer? _lockMemoSaveDebounce;
  bool _lockSpeechInit = false;
  bool _lockListening = false;
  String _lockSpeechBaseText = '';
  OverlayEntry? _lockAiSettingsOverlay;
  TextEditingController? _lockAiSettingsPrefixCtrl;
  final Set<OverlayEntry> _lockModalOverlays = <OverlayEntry>{};

  /// 完了通知の固定 ID (キャンセル用)。
  static const int _kFocusLockNotifId = 99310;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _remainSec = widget.duration.inSeconds;
    _endAt = DateTime.now().add(widget.duration);

    // 画面 ON 維持 + 没入モード (システムバー非表示)。
    WakelockPlus.enable();
    SystemChrome.setEnabledSystemUIMode(SystemUiMode.immersiveSticky);

    _loadLockMemo();
    // 埋め込みポモドーロの設定 (浮遊ポモドーロと同じ prefs キー) を読み込む。
    _loadLockPomoSettings();
    if (!widget.taskMode) {
      // 終了予定時刻に OS 通知を予約 (アプリが裏に回っても気付ける)。
      _scheduleCompletionNotification();
      _tick = Timer.periodic(const Duration(seconds: 1), (_) {
        final left = _endAt.difference(DateTime.now()).inSeconds;
        if (left <= 0) {
          _onComplete();
        } else {
          if (mounted) setState(() => _remainSec = left);
        }
      });
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _tick?.cancel();
    _holdTimer?.cancel();
    _lockMemoSaveDebounce?.cancel();
    _lockAiSettingsOverlay?.remove();
    _lockAiSettingsOverlay = null;
    for (final entry in _lockModalOverlays.toList()) {
      try {
        entry.remove();
      } catch (_) {}
    }
    _lockModalOverlays.clear();
    _lockPomoTick?.cancel();
    // ロック解除時はアラームも解除する (画面ロック内の機能のため)。
    _lockAlarmTimer?.cancel();
    _lockAlarmRepeatTimer?.cancel();
    if (_lockAlarmRinging) {
      // ignore: discarded_futures
      _AudioAlarm.stop();
    }
    // ロック解除時に自然音を止める (= 鳴りっぱなしにしない)。
    // ignore: discarded_futures
    _AmbientSound.stop();
    _lockAiSettingsPrefixCtrl?.dispose();
    _lockAiSettingsPrefixCtrl = null;
    // ignore: discarded_futures
    _saveLockMemoNow();
    try {
      _lockSpeech.cancel();
    } catch (_) {}
    for (final ctrl in _lockMemoCtrls) {
      ctrl.dispose();
    }
    // システム UI とウェイクロックを元に戻す。
    WakelockPlus.disable();
    SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    super.didChangeAppLifecycleState(state);
    // ── SMS / 電話 等での離脱後の再ロック (ユーザー要望) ──
    // ロック中に許可ショートカット (電話 / SMS / Wi-Fi / テザリング) で
    //   外部アプリへ飛ぶと、 一時的に OS の画面固定 (lock task) を解除する。
    //   そのまま OS のホームへ抜けられてしまうため、 アプリに戻ってきた
    //   (resumed) タイミングで必ずロックを再適用し、 抜けられないようにする。
    //   ・画面固定 (startLock) を再要求
    //   ・没入モード (システムバー非表示) を再適用 ← 戻ると解除されるため
    //   ・ウェイクロックを再有効化
    // ※ 集中ロックは Android 専用。 startLock は Android 以外では no-op。
    if (_finished) return; // 終了処理中 (= もうすぐ閉じる) なら何もしない
    if (state == AppLifecycleState.resumed) {
      WakelockPlus.enable();
      SystemChrome.setEnabledSystemUIMode(SystemUiMode.immersiveSticky);
      _reassertOsLock();
    }
  }

  /// OS レベルの画面固定 (lock task) を再要求する。 既に固定中なら no-op。
  Future<void> _reassertOsLock() async {
    if (kIsWeb || !Platform.isAndroid) return;
    try {
      await const MethodChannel('app/lock').invokeMethod('startLock');
    } catch (_) {
      // ネイティブ未実装 / 失敗時はアプリ内オーバーレイのみで継続。
    }
  }

  /// 終了予定時刻に合わせて完了通知を予約する。
  Future<void> _scheduleCompletionNotification() async {
    if (kIsWeb || !Platform.isAndroid) return;
    try {
      final scheduled = tz.TZDateTime.from(_endAt, tz.local);
      await flutterLocalNotificationsPlugin.zonedSchedule(
        _kFocusLockNotifId,
        widget.provider.t('focusLock.doneTitle'),
        widget.provider.t('focusLock.doneBody'),
        scheduled,
        NotificationDetails(
          android: AndroidNotificationDetails(
            kNodeReminderChannelId,
            kNodeReminderChannelName,
            channelDescription: kNodeReminderChannelDescription,
            importance: Importance.high,
            priority: Priority.high,
            enableVibration: true,
            playSound: true,
          ),
        ),
        androidScheduleMode: AndroidScheduleMode.exactAllowWhileIdle,
        uiLocalNotificationDateInterpretation:
            UILocalNotificationDateInterpretation.absoluteTime,
      );
    } catch (e) {
      debugPrint('集中ロック完了通知の予約に失敗: $e');
    }
  }

  /// 予約済みの完了通知をキャンセルする (早期解除時)。
  Future<void> _cancelCompletionNotification() async {
    try {
      await flutterLocalNotificationsPlugin.cancel(_kFocusLockNotifId);
    } catch (_) {}
  }

  /// 時間満了 (自然終了)。
  void _onComplete() {
    if (_finished) return;
    _finished = true;
    _tick?.cancel();
    HapticFeedback.heavyImpact();
    // アプリが前面なら音も鳴らす (予約通知とは別。前面では通知バナーより
    // 音の方が気付きやすい)。
    _AudioAlarm.playAlarm(_AudioAlarm.prefKeyPomodoro);
    widget.onClose();
  }

  Future<void> _setFocusTaskCompleted(
      FocusLockTask task, bool completed) async {
    if (_finished || !widget.taskMode) return;
    await widget.provider.setFocusLockTaskCompleted(task.id, completed);
    if (!mounted || _finished) return;
    setState(() {});
    // 空リストは完了扱いにしない。登録済みの全件完了時は、解除前に
    // 明示確認を求める。チェックだけで一瞬にロックを閉じない。
    if (widget.provider.areAllFocusLockTasksCompleted) {
      await _requestFocusTaskUnlockConfirmation();
    }
  }

  /// タスクを全部消して 0 件になった時に、 ロックを解除するか聞く
  /// (= ユーザー要望)。 「続ける」 を選べばロックはそのまま。
  Future<void> _confirmUnlockAfterAllTasksRemoved() async {
    if (_finished ||
        !mounted ||
        !widget.taskMode ||
        widget.provider.focusLockTasks.isNotEmpty ||
        _taskUnlockConfirmationOpen) {
      return;
    }
    setState(() => _taskUnlockConfirmationOpen = true);
    final confirmed = await _showLockFrontDialog<bool>(
      (dialogContext, close) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: const Text('やることが無くなりました',
            style: TextStyle(color: Colors.white, fontSize: 16)),
        content: const Text('登録したやることが 0 件になりました。\nロックを解除しますか?',
            style: TextStyle(color: Colors.white70)),
        actions: [
          TextButton(
            onPressed: () => close(false),
            child: const Text('続ける'),
          ),
          FilledButton(
            onPressed: () => close(true),
            child: Text(widget.provider.t('focusLock.taskUnlockConfirmAction')),
          ),
        ],
      ),
    );
    if (!mounted) return;
    setState(() => _taskUnlockConfirmationOpen = false);
    // 待っている間にタスクが増えていたら解除しない。
    if (confirmed == true && widget.provider.focusLockTasks.isEmpty) {
      _finished = true;
      _tick?.cancel();
      HapticFeedback.heavyImpact();
      widget.onClose();
    }
  }

  Future<void> _requestFocusTaskUnlockConfirmation() async {
    if (_finished ||
        !mounted ||
        !widget.taskMode ||
        !widget.provider.areAllFocusLockTasksCompleted ||
        _taskUnlockConfirmationOpen) {
      return;
    }
    setState(() => _taskUnlockConfirmationOpen = true);
    // ロック用オーバーレイは root オーバーレイへ直接 insert しているため、
    // 通常の showDialog はロック画面の *背面* に描画されて操作できない
    // (= 全タスク完了しても解除ボタンが押せない不具合の原因)。
    // ロック画面より前面に出る _showLockFrontDialog を必ず使う。
    final confirmed = await _showLockFrontDialog<bool>(
      (dialogContext, close) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(widget.provider.t('focusLock.taskUnlockConfirmTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        content: Text(widget.provider.t('focusLock.taskUnlockConfirmBody'),
            style: const TextStyle(color: Colors.white70)),
        actions: [
          TextButton(
            onPressed: () => close(false),
            child: Text(widget.provider.t('focusLock.cancel')),
          ),
          FilledButton(
            onPressed: () => close(true),
            child: Text(widget.provider.t('focusLock.taskUnlockConfirmAction')),
          ),
        ],
      ),
    );
    if (!mounted) return;
    setState(() => _taskUnlockConfirmationOpen = false);
    // ダイアログ表示中に状態が変わっていた場合は、解除しない。
    if (confirmed == true && widget.provider.areAllFocusLockTasksCompleted) {
      _completeFocusTaskLock();
    }
  }

  void _completeFocusTaskLock() {
    if (_finished || !widget.provider.areAllFocusLockTasksCompleted) return;
    _finished = true;
    _tick?.cancel();
    HapticFeedback.heavyImpact();
    _AudioAlarm.playAlarm(_AudioAlarm.prefKeyPomodoro);
    widget.onClose();
  }

  /// ロック画面からタスクを追加する (= ユーザー要望: ロック中でも
  /// 集中タスクを増やせる)。前面ダイアログでタイトルを入力させる。
  Future<void> _addFocusTaskFromLock() async {
    if (_finished || !widget.taskMode) return;
    final ctrl = TextEditingController();
    final title = await _showLockFrontDialog<String>(
      (dialogContext, close) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(widget.provider.t('focusLock.addTask'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        content: SizedBox(
          width: 340,
          child: TextField(
            controller: ctrl,
            autofocus: true,
            style: const TextStyle(color: Colors.white),
            textInputAction: TextInputAction.done,
            onSubmitted: (v) => close(v),
            decoration: InputDecoration(
              hintText: widget.provider.t('lock.taskHint'),
              hintStyle: const TextStyle(color: Colors.white38),
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => close(null),
            child: Text(widget.provider.t('focusLock.cancel')),
          ),
          FilledButton(
            onPressed: () => close(ctrl.text),
            child: Text(widget.provider.t('btn.add')),
          ),
        ],
      ),
    );
    ctrl.dispose();
    final trimmed = (title ?? '').trim();
    if (trimmed.isEmpty) return;
    await widget.provider.addFocusLockTask(trimmed);
    if (!mounted) return;
    // タスクが増えたので完了状態が崩れる → 解除ボタンは自動的に隠れる。
    setState(() {});
  }

  /// 緊急解除 (時間前に閉じる)。予約通知もキャンセル。
  void _emergencyExit() {
    if (widget.taskMode) {
      if (!widget.provider.areAllFocusLockTasksCompleted) return;
      // 全件完了済みでも、長押しなどの解除操作は確認を経由する。
      unawaited(_requestFocusTaskUnlockConfirmation());
      return;
    }
    if (_finished) return;
    _finished = true;
    _tick?.cancel();
    _holdTimer?.cancel();
    _cancelCompletionNotification();
    HapticFeedback.mediumImpact();
    widget.onClose();
  }

  // ── 長押し緊急解除 ──
  void _startHold() {
    if (_finished) return;
    _holdTimer?.cancel();
    const totalMs = 3000;
    const stepMs = 50;
    int elapsed = 0;
    _holdTimer = Timer.periodic(const Duration(milliseconds: stepMs), (t) {
      elapsed += stepMs;
      if (mounted) {
        setState(() => _holdProgress = (elapsed / totalMs).clamp(0.0, 1.0));
      }
      if (elapsed >= totalMs) {
        t.cancel();
        _emergencyExit();
      }
    });
  }

  void _cancelHold() {
    _holdTimer?.cancel();
    _holdTimer = null;
    if (mounted) setState(() => _holdProgress = 0.0);
  }

  String _todayDateKey() {
    final now = DateTime.now();
    return '${now.year}-${now.month.toString().padLeft(2, '0')}-'
        '${now.day.toString().padLeft(2, '0')}';
  }

  Future<void> _loadLockMemo() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kLockMemoPrefsKey);
      final legacy = prefs.getString(_kLegacyLockMemoPrefsKey) ?? '';
      final texts = <String>[];
      if (raw != null && raw.trim().isNotEmpty) {
        final decoded = jsonDecode(raw);
        if (decoded is List) {
          for (final item in decoded) {
            texts.add(item?.toString() ?? '');
          }
        }
      }
      if (texts.isEmpty && legacy.trim().isNotEmpty) {
        texts.add(legacy);
      }
      if (texts.isEmpty) texts.add('');
      if (!mounted) return;
      setState(() {
        for (final ctrl in _lockMemoCtrls) {
          ctrl.dispose();
        }
        _lockMemoCtrls
          ..clear()
          ..addAll(texts.map((text) {
            final ctrl = TextEditingController(text: text);
            ctrl.selection = TextSelection.collapsed(offset: ctrl.text.length);
            return ctrl;
          }));
        _activeLockMemoIndex = 0;
      });
    } catch (_) {}
  }

  void _scheduleLockMemoSave() {
    _lockMemoSaveDebounce?.cancel();
    _lockMemoSaveDebounce = Timer(const Duration(milliseconds: 500), () {
      // ignore: discarded_futures
      _saveLockMemoNow();
    });
  }

  Future<void> _saveLockMemoNow() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final texts = _lockMemoCtrls.map((ctrl) => ctrl.text).toList();
      if (texts.every((text) => text.trim().isEmpty)) {
        await prefs.remove(_kLockMemoPrefsKey);
      } else {
        await prefs.setString(_kLockMemoPrefsKey, jsonEncode(texts));
      }
    } catch (_) {}
  }

  String _lockMemoToolText() => _lockMemoCtrl.text.trim();

  void _selectLockMemo(int index) {
    if (index < 0 || index >= _lockMemoCtrls.length) return;
    setState(() => _activeLockMemoIndex = index);
  }

  void _addLockMemo() {
    setState(() {
      _lockMemoCtrls.add(TextEditingController());
      _activeLockMemoIndex = _lockMemoCtrls.length - 1;
    });
    _scheduleLockMemoSave();
  }

  void _deleteActiveLockMemo() {
    if (_lockMemoCtrls.length <= 1) {
      _lockMemoCtrl.clear();
      _scheduleLockMemoSave();
      setState(() {});
      return;
    }
    final removeIndex = _activeLockMemoIndex;
    final removed = _lockMemoCtrls.removeAt(removeIndex);
    removed.dispose();
    setState(() {
      _activeLockMemoIndex =
          math.min(removeIndex, _lockMemoCtrls.length - 1).toInt();
    });
    _scheduleLockMemoSave();
  }

  ({double width, double height}) _lockFloatingWindowSize() {
    final size = MediaQuery.of(context).size;
    return (
      width: math.min(520.0, math.max(320.0, size.width - 24.0)),
      height: math.min(380.0, math.max(300.0, size.height * 0.48)),
    );
  }

  Future<void> _openLockMemoGoogleSearch() async {
    final text = _lockMemoToolText();
    if (text.isEmpty) {
      _appSnack(context,
          SnackBar(content: Text(widget.provider.t('lock.memoEmptySearch'))));
      return;
    }
    await _saveLockMemoNow();
    if (!mounted) return;
    final isMobile = !kIsWeb && (Platform.isAndroid || Platform.isIOS);
    if (isMobile) {
      GoogleSearchDialog.showFloating(
        context,
        initialQuery: text,
        initialMemo: text,
        customTitle: 'ロック中メモを検索',
        singletonKey: 'focus_lock_google',
        initiallyExpanded: true,
        hideChromeWhenExpanded: true,
        onAddNode: (_, __, ___) {},
      );
      return;
    }
    final win = _lockFloatingWindowSize();
    GoogleSearchDialog.showFloating(
      context,
      initialQuery: text,
      initialMemo: text,
      customTitle: 'ロック中メモを検索',
      anchorPos: const Offset(12, 8),
      singletonKey: 'focus_lock_google',
      initialWidth: win.width,
      initialHeight: win.height,
      hideChromeWhenExpanded: true,
      onAddNode: (_, __, ___) {},
    );
  }

  /// メモの内容で YouTube を探す (= ユーザー要望)。
  ///
  /// メモに書いた言葉を「見てよい動画の条件」 として持ち回り、 一覧から
  /// 動画を選んだ時にタイトルへその言葉が入っているかを確かめる。
  /// 入っていなければ再生しない。 これで、 調べものの動画だけが見られる。
  Future<void> _openLockMemoYoutubeSearch() async {
    final text = _lockMemoToolText();
    if (text.isEmpty) {
      _appSnack(context,
          SnackBar(content: Text(widget.provider.t('lock.memoEmptySearch'))));
      return;
    }
    await _saveLockMemoNow();
    if (!mounted) return;
    final keywords = widget.provider.focusLockYoutubeKeywordGate
        ? MindMapProvider.focusKeywordsOf(text)
        : const <String>[];

    // ① まず検索結果を集める (既存の抽出シートをそのまま使う)。
    List<String> ids = const [];
    List<String> titles = const [];
    final url = 'https://m.youtube.com/results?search_query='
        '${Uri.encodeQueryComponent(text)}';
    final isDesktop =
        !kIsWeb && (Platform.isWindows || Platform.isLinux || Platform.isMacOS);
    await showDialog<void>(
      context: context,
      barrierColor: Colors.black87,
      builder: (_) => isDesktop
          ? _WindowsYoutubeSearchSheet(
              keyword: text,
              count: 20,
              searchUrl: url,
              onResults: (v, t) {
                ids = v;
                titles = t;
              },
            )
          : _YoutubeSearchSheet(
              keyword: text,
              count: 20,
              searchUrl: url,
              onResults: (v, t) {
                ids = v;
                titles = t;
              },
            ),
    );
    if (!mounted || ids.isEmpty) return;

    // ② メモの言葉が入っている動画だけを選べる一覧を出す。
    await showDialog<void>(
      context: context,
      barrierColor: Colors.black87,
      builder: (dctx) => _LockYoutubePicker(
        provider: widget.provider,
        videoIds: ids,
        titles: titles,
        keywords: keywords,
        onPlay: (id) {
          Navigator.of(dctx).pop();
          _openLockVideo(id);
        },
      ),
    );
  }

  /// ロック中に選ばれた動画を再生する。
  void _openLockVideo(String videoId) {
    final url = 'https://www.youtube.com/watch?v=$videoId';
    final play = widget.onPlayVideo;
    if (play != null) {
      play(url);
      return;
    }
    unawaited(
        launchUrl(Uri.parse(url), mode: LaunchMode.externalApplication));
  }

  Future<void> _sendLockMemoToBrowserAi() async {
    final text = _lockMemoToolText();
    if (text.isEmpty) {
      _appSnack(context,
          SnackBar(content: Text(widget.provider.t('lock.memoEmptyAi'))));
      return;
    }
    await _saveLockMemoNow();
    final query = widget.provider.browserAiApplyPrefix(text);
    await Clipboard.setData(ClipboardData(text: query));
    if (!mounted) return;
    final isMobile = !kIsWeb && (Platform.isAndroid || Platform.isIOS);
    if (isMobile) {
      // 集中ロック自体がルート Overlay 上にあるため、通常の全画面 Route は
      // その背面へ回る。ロックより後にルート Overlay へ全画面で挿入する。
      // 同じ OverlayEntry を維持するので ChatGPT の不用意な再読込も避けられる。
      GoogleSearchDialog.showFloating(
        context,
        initialUrl: widget.provider.browserAiUrlForQuery(query),
        initialMemo: text,
        initialAiPrompt: query,
        customTitle: '${widget.provider.browserAiTargetLabel} / ロック中メモ',
        singletonKey: 'focus_lock_ai',
        initiallyExpanded: true,
        hideChromeWhenExpanded: true,
        onAddNode: (_, __, ___) {},
      );
      return;
    }
    final win = _lockFloatingWindowSize();
    GoogleSearchDialog.showFloating(
      context,
      initialUrl: widget.provider.browserAiUrlForQuery(query),
      initialMemo: text,
      customTitle: '${widget.provider.browserAiTargetLabel} / ロック中メモ',
      anchorPos: const Offset(12, 8),
      singletonKey: 'focus_lock_ai',
      initialWidth: win.width,
      initialHeight: win.height,
      hideChromeWhenExpanded: true,
      onAddNode: (_, __, ___) {},
    );
  }

  /// ロック中メモを「どのページに送るか」を選ばせてから 1 ノードとして送る
  /// (= ユーザー要望)。 ロック Overlay はルート Overlay 上にあるため通常の
  /// showDialog は背面に回る。 必ず _showLockFrontDialog を使う。
  Future<void> _sendLockMemoToPage() async {
    final text = _lockMemoCtrl.text.trim();
    if (text.isEmpty) {
      _appSnack(context,
          SnackBar(content: Text(widget.provider.t('lock.memoEmptySend'))));
      return;
    }
    await _saveLockMemoNow();
    if (!mounted) return;
    final provider = widget.provider;
    final pages = provider.pages;
    // ページが 1 つだけなら選ぶ余地がないのでそのまま送る。
    if (pages.length <= 1) {
      provider.addMemoNodeToCurrentPage(text);
      if (!mounted) return;
      _appSnack(context,
          SnackBar(content: Text(widget.provider.t('lock.memoSent'))));
      return;
    }
    final currentIdx = provider.currentPageIndex;
    final listH = (pages.length * 52).clamp(60, 360).toDouble();
    final chosen = await _showLockFrontDialog<int>(
      (dctx, close) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(widget.provider.t('lock.selectPageToSend'),
            style: const TextStyle(color: Colors.white, fontSize: 16)),
        contentPadding: const EdgeInsets.fromLTRB(12, 12, 12, 0),
        content: SizedBox(
          width: 340,
          height: listH,
          child: Scrollbar(
            child: ListView.builder(
              itemCount: pages.length,
              itemBuilder: (_, i) {
                final isCurrent = i == currentIdx;
                return ListTile(
                  dense: true,
                  leading: Icon(isCurrent ? Icons.map : Icons.map_outlined,
                      color: isCurrent
                          ? const Color(0xFFFFD54F)
                          : Colors.white54,
                      size: 20),
                  title: Text(
                    isCurrent ? '${pages[i].name}（現在）' : pages[i].name,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                        color: isCurrent
                            ? const Color(0xFFFFD54F)
                            : Colors.white,
                        fontSize: 14),
                  ),
                  shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(10)),
                  onTap: () => close(i),
                );
              },
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => close(),
            child: Text(widget.provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white70)),
          ),
        ],
      ),
    );
    if (chosen == null || !mounted) return;
    provider.addMemoNodeToPage(chosen, text);
    if (!mounted) return;
    _appSnack(
        context,
        SnackBar(
            content: Text(widget.provider
                .t('lock.memoSentTo')
                .replaceFirst('{name}', pages[chosen].name))));
  }

