  Future<bool> _ensureLockSpeechReady() async {
    if (_lockSpeechInit) return true;
    if (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) {
      var mic = await Permission.microphone.status;
      if (!mic.isGranted) mic = await Permission.microphone.request();
      if (!mic.isGranted) {
        if (mounted) {
          _appSnack(context,
              SnackBar(content: Text(widget.provider.t('stt.micPermission'))));
        }
        return false;
      }
    }
    try {
      _lockSpeechInit = await _lockSpeech.initialize(
        onStatus: (status) {
          if (!mounted) return;
          if (status == 'done' || status == 'notListening') {
            setState(() => _lockListening = false);
          }
        },
        onError: (error) {
          if (!mounted) return;
          setState(() => _lockListening = false);
        },
      );
    } catch (_) {
      _lockSpeechInit = false;
    }
    if (!_lockSpeechInit && mounted) {
      _appSnack(context,
          SnackBar(content: Text(widget.provider.t('stt.unavailable'))));
    }
    return _lockSpeechInit;
  }

  Future<void> _toggleLockMemoSpeech() async {
    if (_lockListening || _lockSpeech.isListening) {
      try {
        await _lockSpeech.stop();
      } catch (_) {}
      if (mounted) setState(() => _lockListening = false);
      return;
    }
    if (!await _ensureLockSpeechReady()) return;
    _lockSpeechBaseText = _lockMemoCtrl.text.trimRight();
    try {
      if (mounted) setState(() => _lockListening = true);
      await _lockSpeech.listen(
        onResult: (result) {
          if (!mounted) return;
          final words = result.recognizedWords.trim();
          final next = words.isEmpty
              ? _lockSpeechBaseText
              : _lockSpeechBaseText.isEmpty
                  ? words
                  : '$_lockSpeechBaseText\n$words';
          setState(() {
            _lockMemoCtrl.text = next;
            _lockMemoCtrl.selection =
                TextSelection.collapsed(offset: _lockMemoCtrl.text.length);
          });
          _scheduleLockMemoSave();
        },
        localeId: widget.provider.speechLocaleId,
        pauseFor: Duration(seconds: widget.provider.voicePauseSeconds),
        listenOptions: stt.SpeechListenOptions(
          partialResults: true,
          listenMode: stt.ListenMode.dictation,
          cancelOnError: false,
        ),
      );
    } catch (e) {
      if (!mounted) return;
      setState(() => _lockListening = false);
      _appSnack(
          context,
          SnackBar(
              content: Text(widget.provider
                  .t('stt.startFailed')
                  .replaceFirst('{e}', '$e'))));
    }
  }

  Future<T?> _showLockFrontDialog<T>(
    Widget Function(BuildContext context, void Function([T? result]) close)
        builder,
  ) {
    final completer = Completer<T?>();
    late OverlayEntry entry;
    void close([T? result]) {
      if (entry.mounted) {
        try {
          entry.remove();
        } catch (_) {}
      }
      _lockModalOverlays.remove(entry);
      if (!completer.isCompleted) completer.complete(result);
    }

    entry = OverlayEntry(
      builder: (overlayCtx) => Material(
        type: MaterialType.transparency,
        child: Stack(
          children: [
            Positioned.fill(
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: () => close(),
                child: Container(color: Colors.black54),
              ),
            ),
            Center(
              child: builder(overlayCtx, close),
            ),
          ],
        ),
      ),
    );
    _lockModalOverlays.add(entry);
    Overlay.of(context, rootOverlay: true).insert(entry);
    return completer.future;
  }

  Future<void> _showLockEventEditor([CalendarEvent? event]) async {
    final p = widget.provider;
    final dateKey = _todayDateKey();
    if (event != null &&
        (event.isGoogleEvent || event.isOthersEvent(p.currentUid))) {
      _appSnack(context,
          SnackBar(content: Text(widget.provider.t('lock.eventReadOnly'))));
      return;
    }

    final titleCtrl = TextEditingController(text: event?.title ?? '');

    Future<void> save(VoidCallback closeDialog) async {
      final title = titleCtrl.text.trim();
      if (title.isEmpty) {
        _appSnack(context,
            SnackBar(content: Text(widget.provider.t('lock.taskNameRequired'))));
        return;
      }
      // ── タスクモード (= ユーザー要望: ロック中の「取り組むべきタスク」は
      //    開始/終了時刻もメモも入力させず、タスク名だけで登録する)。
      //    既存イベントのメモは編集で消さずそのまま保持する。 ──
      const String? startTime = null;
      const String? endTime = null;
      final memo = (event?.memo ?? '').trim();
      if (event == null) {
        await p.addCalendarEvent(
          dateKey,
          title,
          memo: memo.isEmpty ? null : memo,
          startTime: startTime,
          endTime: endTime,
          colorArgb: const Color(0xFF4FC3F7).value,
        );
      } else {
        await p.updateCalendarEvent(
          dateKey,
          event.id,
          title,
          memo: memo.isEmpty ? null : memo,
          startTime: startTime,
          endTime: endTime,
          colorArgb: event.colorArgb,
        );
      }
      if (!mounted) return;
      closeDialog();
      setState(() {});
    }

    try {
      await _showLockFrontDialog<void>(
        (dctx, close) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Text(event == null ? 'タスク追加' : 'タスク編集',
              style: const TextStyle(color: Colors.white, fontSize: 16)),
          content: SizedBox(
            width: 360,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: titleCtrl,
                  autofocus: true,
                  onSubmitted: (_) => save(() => close()),
                  style: const TextStyle(color: Colors.white),
                  decoration: InputDecoration(
                    labelText: widget.provider.t('lock.taskName'),
                    labelStyle: const TextStyle(color: Colors.white54),
                  ),
                ),
              ],
            ),
          ),
          actions: [
            if (event != null)
              TextButton.icon(
                icon: const Icon(Icons.delete_outline_rounded,
                    color: Color(0xFFFF8A80), size: 18),
                label: Text(widget.provider.t('btn.delete'),
                    style: const TextStyle(color: Color(0xFFFF8A80))),
                onPressed: () async {
                  close();
                  await p.removeCalendarEvent(dateKey, event.id);
                  if (mounted) setState(() {});
                },
              ),
            TextButton(
              onPressed: () => close(),
              child: Text(widget.provider.t('btn.close'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF4FC3F7),
                foregroundColor: Colors.black,
              ),
              onPressed: () => save(() => close()),
              child: Text(widget.provider.t('btn.save')),
            ),
          ],
        ),
      );
    } finally {
      titleCtrl.dispose();
    }
  }

  /// ロック中でも許可する操作 (電話 / SMS / Wi-Fi / テザリング) を起動する
  /// (ユーザー要望)。 OS の画面固定中は他アプリへ飛べないため、 一旦固定を
  /// 解除してから起動する。 アプリに戻ると didChangeAppLifecycleState が
  /// 自動で再固定する (= ロックは継続)。
  Future<void> _launchWhileLocked(Future<void> Function() action) async {
    if (kIsWeb || !Platform.isAndroid) return;
    try {
      await const MethodChannel('app/lock').invokeMethod('stopLock');
    } catch (_) {}
    await Future<void>.delayed(const Duration(milliseconds: 150));
    try {
      await action();
    } catch (e) {
      debugPrint('ロック中の許可操作の起動に失敗: $e');
    }
  }

  /// テザリング設定を開く (端末によりアクション名が違うので順に試す)。
  Future<void> _openTetheringSettings() async {
    for (final act in const [
      'android.settings.TETHER_SETTINGS',
      'android.settings.WIRELESS_SETTINGS',
      'android.settings.DATA_ROAMING_SETTINGS',
    ]) {
      try {
        await AndroidIntent(action: act).launch();
        return;
      } catch (_) {}
    }
  }

  /// ロック中も使える通信系ショートカット (電話 / SMS / Wi-Fi / テザリング)。
  Widget _buildLockAllowedActions() {
    if (kIsWeb || !Platform.isAndroid) return const SizedBox.shrink();
    Widget btn(IconData icon, String label, VoidCallback onTap) {
      return Expanded(
        child: InkWell(
          onTap: onTap,
          borderRadius: BorderRadius.circular(12),
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 10),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(icon, color: Colors.white70, size: 22),
                const SizedBox(height: 4),
                Text(label,
                    style:
                        const TextStyle(color: Colors.white60, fontSize: 11)),
              ],
            ),
          ),
        ),
      );
    }

    return Container(
      constraints: const BoxConstraints(maxWidth: 360),
      margin: const EdgeInsets.symmetric(horizontal: 24),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: Colors.white12),
      ),
      child: Row(
        children: [
          btn(
              Icons.call_rounded,
              '電話',
              () => _launchWhileLocked(() => launchUrl(Uri.parse('tel:'),
                  mode: LaunchMode.externalApplication))),
          btn(
              Icons.sms_rounded,
              'SMS',
              () => _launchWhileLocked(() => launchUrl(Uri.parse('sms:'),
                  mode: LaunchMode.externalApplication))),
          btn(
              Icons.wifi_rounded,
              'Wi-Fi',
              () => _launchWhileLocked(() =>
                  AndroidIntent(action: 'android.settings.WIFI_SETTINGS')
                      .launch())),
          btn(Icons.wifi_tethering_rounded, 'テザリング',
              () => _launchWhileLocked(_openTetheringSettings)),
        ],
      ),
    );
  }

  String _fmt(int sec) {
    final s = sec < 0 ? 0 : sec;
    // ── 秒表示設定 ──
    // キー名は hideSeconds だが、現行UIでは true = 秒を表示する。
    // OFF の時は残り分 (繰り上げ) のみ表示する。
    if (!widget.provider.focusLockHideSeconds) {
      final mins = (s / 60).ceil();
      final h = mins ~/ 60;
      final m = mins % 60;
      String two(int v) => v.toString().padLeft(2, '0');
      if (h > 0) return '${two(h)}:${two(m)}';
      return '$mins${widget.provider.t('focusLock.minutesSuffix')}';
    }
    final h = s ~/ 3600;
    final m = (s % 3600) ~/ 60;
    final ss = s % 60;
    String two(int v) => v.toString().padLeft(2, '0');
    if (h > 0) return '${two(h)}:${two(m)}:${two(ss)}';
    return '${two(m)}:${two(ss)}';
  }

  /// 時刻を HH:mm 形式で返す (現在時刻・解除時刻の表示用)。
  String _fmtClock(DateTime dt) => '${dt.hour.toString().padLeft(2, '0')}:'
      '${dt.minute.toString().padLeft(2, '0')}';

  /// 今日のタイムラインをロック画面に表示し、その場で追加・編集できる。
  Widget _buildUpcomingEvents() {
    final key = _todayDateKey();
    // タスク (時刻なし) は集中タスクのパネルに一本化したので、 ここは
    // 時刻付きの予定だけを出す (= ユーザー要望: 2 つのタスク欄をまとめる)。
    final events = [
      ...widget.provider.eventsOn(key).where((e) => e.startTime != null)
    ];
    if (events.isEmpty) return const SizedBox.shrink();
    int? startMinOf(CalendarEvent e) {
      if (e.startTime == null) return null;
      final parts = e.startTime!.split(':');
      if (parts.length != 2) return null;
      final hh = int.tryParse(parts[0]);
      final mm = int.tryParse(parts[1]);
      if (hh == null || mm == null) return null;
      return hh * 60 + mm;
    }

    events.sort((a, b) {
      final am = startMinOf(a);
      final bm = startMinOf(b);
      if (am == null && bm == null) return 0;
      if (am == null) return -1;
      if (bm == null) return 1;
      return am.compareTo(bm);
    });

    Widget row(CalendarEvent e) {
      final c =
          e.colorArgb != null ? Color(e.colorArgb!) : const Color(0xFF4FC3F7);
      // タスク (時刻なし) では時刻カラムを詰めてタスク名を左に寄せる。
      final timeLabel = e.startTime ?? '';
      final readOnly =
          e.isGoogleEvent || e.isOthersEvent(widget.provider.currentUid);
      return Padding(
        padding: const EdgeInsets.only(bottom: 6),
        child: Material(
          color: Colors.transparent,
          child: InkWell(
            onTap: readOnly
                ? () => _appSnack(
                    context,
                    SnackBar(
                        content: Text(widget.provider.t('lock.eventReadOnly'))))
                : () => _showLockEventEditor(e),
            borderRadius: BorderRadius.circular(10),
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 2, vertical: 5),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Container(
                    width: 4,
                    height: e.memo?.trim().isNotEmpty == true ? 34 : 18,
                    margin: const EdgeInsets.only(top: 1, right: 8),
                    decoration: BoxDecoration(
                        color: c, borderRadius: BorderRadius.circular(2)),
                  ),
                  SizedBox(
                    width: e.startTime != null ? 46 : 4,
                    child: e.startTime != null
                        ? Text(timeLabel,
                            style: const TextStyle(
                                color: Colors.white60,
                                fontSize: 12,
                                fontFeatures: [FontFeature.tabularFigures()]))
                        : null,
                  ),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(e.title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: Colors.white, fontSize: 13)),
                        if (e.memo?.trim().isNotEmpty == true) ...[
                          const SizedBox(height: 2),
                          Text(e.memo!.trim(),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: Colors.white54, fontSize: 11)),
                        ],
                      ],
                    ),
                  ),
                  const SizedBox(width: 6),
                  Icon(readOnly ? Icons.visibility_rounded : Icons.edit_rounded,
                      color: Colors.white38, size: 15),
                ],
              ),
            ),
          ),
        ),
      );
    }

    return Container(
      constraints: const BoxConstraints(maxWidth: 360),
      margin: const EdgeInsets.symmetric(horizontal: 24),
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: Colors.white12),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(Icons.event_available_rounded,
                  color: Color(0xFF4FC3F7), size: 16),
              const SizedBox(width: 6),
              Expanded(
                child: Text(
                  widget.provider.t('lock.todaySchedule'),
                  style: TextStyle(
                      color: Colors.white.withValues(alpha: 0.8),
                      fontSize: 12,
                      fontWeight: FontWeight.w700),
                ),
              ),

            ],
          ),
          const SizedBox(height: 8),
          if (events.isEmpty)
            Text(widget.provider.t('lock.noTasksHint'),
                style:
                    const TextStyle(color: Colors.white54, fontSize: 12))
          else
            ConstrainedBox(
              constraints: const BoxConstraints(maxHeight: 170),
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [for (final e in events) row(e)],
                ),
              ),
            ),
        ],
      ),
    );
  }

  List<({MindMapPage page, MindMapNode node, String kind, String value})>
      _lockContentItems() {
    final provider = widget.provider;
    var targetPageId = provider.focusLockContentPageIds.isNotEmpty
        ? provider.focusLockContentPageIds.first
        : provider.currentPage.id;
    if (!provider.pages.any((page) => page.id == targetPageId)) {
      targetPageId = provider.currentPage.id;
    }
    final items =
        <({MindMapPage page, MindMapNode node, String kind, String value})>[];
    for (final page in provider.pages) {
      if (page.id != targetPageId) continue;
      for (final node in page.nodes.values) {
        final yt = (node.youtubeUrl ?? '').trim();
        final att = (node.attachmentPath ?? '').trim();
        final link = (node.linkUrl ?? '').trim();
        if (yt.isNotEmpty) {
          items.add((page: page, node: node, kind: '動画', value: yt));
        } else if (att.isNotEmpty) {
          items.add((page: page, node: node, kind: 'ファイル', value: att));
        } else if (link.isNotEmpty) {
          items.add((page: page, node: node, kind: 'リンク', value: link));
        }
      }
    }
    return items;
  }

  Future<void> _openLockContent(MindMapNode node) async {
    final yt = (node.youtubeUrl ?? '').trim();
    final att = (node.attachmentPath ?? '').trim();
    final link = (node.linkUrl ?? '').trim();

    if (att.isNotEmpty) {
      // ローカルの添付ビューアは root Navigator に積むと、先に root
      // Overlay へ挿入されたロック画面の背面へ入る。画像だけを特別扱い
      // せず、Office / PDF / ipynb / テキストを含む全ての内蔵ビューアを
      // ロック画面より後に挿入した専用 Navigator 上で開く。
      if (_isRemoteLockPath(att) || _isLockFloatingVideoPath(att)) {
        _openLockContentFloating(node, att);
        return;
      }
      final localPath = _lockLocalFilePath(att);
      final openNode = localPath == att
          ? node
          : node.copyWith(attachmentPath: localPath);
      if (await File(localPath).exists() &&
          _canOpenLockAttachmentInApp(localPath)) {
        await _openLockAttachmentInApp(openNode);
      } else {
        // 内蔵ビューア対象外、設定で外部表示を選んでいる形式、または
        // 消失済みファイルは従来どおり外部起動へ渡す。Android の画面固定
        // は一時解除し、外部アプリがロック画面より前に出られるようにする。
        if (!kIsWeb && Platform.isAndroid) {
          await _launchWhileLocked(() => widget.onOpenContent(openNode));
        } else {
          await widget.onOpenContent(openNode);
        }
      }
      return;
    }

    final target = yt.isNotEmpty
        ? yt
        : _isLockFloatingVideoPath(att)
            ? att
            : link;
    if (target.isNotEmpty) {
      // 通常の Navigator route は root Overlay 上のロック画面より背面に
      // 積まれる。Web だけでなく YouTube / mp4 もロック後に挿入する
      // 全画面 Overlay で開き、閉じた時は下のロック画面へそのまま戻す。
      _openLockContentFloating(node, target);
      return;
    }
    if (kIsWeb || !Platform.isAndroid) {
      await widget.onOpenContent(node);
      return;
    }
    await _launchWhileLocked(() => widget.onOpenContent(node));
  }

  bool _isRemoteLockPath(String path) {
    final lower = path.trim().toLowerCase();
    return lower.startsWith('http://') || lower.startsWith('https://');
  }

  String _lockLocalFilePath(String path) {
    final uri = Uri.tryParse(path.trim());
    if (uri?.scheme.toLowerCase() == 'file') {
      try {
        return uri!.toFilePath();
      } catch (_) {}
    }
    return path.trim();
  }

  String _lockPathWithoutQuery(String path) {
    final query = path.indexOf('?');
    final fragment = path.indexOf('#');
    var end = path.length;
    if (query >= 0 && query < end) end = query;
    if (fragment >= 0 && fragment < end) end = fragment;
    return path.substring(0, end).toLowerCase();
  }

  bool _isLockImagePath(String path) {
    final lower = _lockPathWithoutQuery(path);
    return lower.endsWith('.jpg') ||
        lower.endsWith('.jpeg') ||
        lower.endsWith('.png') ||
        lower.endsWith('.gif') ||
        lower.endsWith('.webp') ||
        lower.endsWith('.bmp');
  }

  bool _canOpenLockAttachmentInApp(String path) {
    if (_isLockImagePath(path)) return true;
    if (!widget.provider.openLinksInApp) return false;
    final lower = _lockPathWithoutQuery(path).replaceAll('\\', '/');
    final name = lower.split('/').last;
    final dot = name.lastIndexOf('.');
    final ext = dot >= 0 ? name.substring(dot + 1) : '';
    if (const {
      'xlsx',
      'xls',
      'csv',
      'tsv',
      'docx',
      'pptx',
      'ppt',
      'ipynb',
      'pdf',
    }.contains(ext)) {
      return true;
    }
    return _MindMapScreenState._kTextEditorExts.contains(ext) ||
        name == 'dockerfile' ||
        name == 'makefile';
  }

  bool _isLockFloatingVideoPath(String path) {
    final lower = _lockPathWithoutQuery(path.trim());
    if (lower.isEmpty) return false;
    if (lower.startsWith('http://') || lower.startsWith('https://')) {
      return NodeWidget.isMp4Url(lower) ||
          lower.contains('youtube.com') ||
          lower.contains('youtu.be') ||
          lower.contains('vimeo.com') ||
          lower.contains('nicovideo.jp');
    }
    return lower.endsWith('.mp4') ||
        lower.endsWith('.webm') ||
        lower.endsWith('.m4v') ||
        lower.endsWith('.mov');
  }

  Future<void> _openLockAttachmentInApp(MindMapNode node) async {
    await _showLockFrontDialog<void>((overlayContext, close) {
      final size = MediaQuery.sizeOf(overlayContext);
      return SizedBox(
        width: size.width,
        height: size.height,
        child: Navigator(
          onGenerateRoute: (_) => MaterialPageRoute<void>(
            builder: (_) => _LockFrontContentLauncher(
              onOpen: (viewerContext) => widget.onOpenContent(
                node,
                presentationContext: viewerContext,
              ),
              onFinished: close,
            ),
          ),
        ),
      );
    });
  }

  void _openLockContentFloating(MindMapNode node, String rawUrl) {
    String loadUrl = rawUrl.trim();
    if (!kIsWeb &&
        loadUrl.isNotEmpty &&
        !RegExp(r'^[a-zA-Z][a-zA-Z0-9+.-]*:').hasMatch(loadUrl)) {
      try {
        loadUrl = Uri.file(loadUrl).toString();
      } catch (_) {}
    }
    if (loadUrl.isEmpty) return;
    final isMobile = !kIsWeb && (Platform.isAndroid || Platform.isIOS);
    final win = _lockFloatingWindowSize();
    final title = node.title.trim().isEmpty ? 'ロック中コンテンツ' : node.title.trim();
    final singletonKey = 'focus_lock_content_${node.id}';
    GoogleSearchDialog.showFloating(
      context,
      initialUrl: loadUrl,
      customTitle: title,
      anchorPos: const Offset(12, 8),
      singletonKey: singletonKey,
      initialWidth: win.width,
      initialHeight: win.height,
      initiallyExpanded: isMobile,
      hideChromeWhenExpanded: true,
      onAddNode: (_, __, ___) {},
    );
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      GoogleSearchDialog.bringFloatingSingletonToFront(context, singletonKey);
    });
  }

  /// ページに「ロック中に開けるコンテンツ」(動画 / ファイル / リンク) を持つ
  /// ノードが 1 つでもあるか。 = ユーザー要望: 中身が無いページは
  /// ロック中コンテンツのページ選択の選択肢に含めない。
  bool _pageHasLockOpenableContent(MindMapPage page) {
    for (final node in page.nodes.values) {
      if ((node.youtubeUrl ?? '').trim().isNotEmpty) return true;
      if ((node.attachmentPath ?? '').trim().isNotEmpty) return true;
      if ((node.linkUrl ?? '').trim().isNotEmpty) return true;
    }
    return false;
  }

  Future<void> _showLockContentPageSelector() async {
    final provider = widget.provider;
    await _showLockFrontDialog<void>(
      (dctx, close) => StatefulBuilder(
        builder: (dctx, setS) {
          final selectedPageId = provider.focusLockContentPageIds.isNotEmpty
              ? provider.focusLockContentPageIds.first
              : provider.currentPage.id;
          return AlertDialog(
            backgroundColor: const Color(0xFF1E1E32),
            title: Text(widget.provider.t('lock.pageToShow'),
                style: const TextStyle(color: Colors.white, fontSize: 16)),
            content: SizedBox(
              width: math.min(360.0, MediaQuery.of(dctx).size.width - 48),
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxHeight: 360),
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      // = ユーザー要望: 中身の無いページは選択肢に出さない。
                      //   現在のページだけは常に選べるように残す。
                      for (final page in provider.pages)
                        if (page.id == provider.currentPage.id ||
                            _pageHasLockOpenableContent(page))
                          RadioListTile<String>(
                            dense: true,
                            visualDensity: VisualDensity.compact,
                            controlAffinity: ListTileControlAffinity.leading,
                            activeColor: const Color(0xFF43B97F),
                            value: page.id,
                            groupValue: selectedPageId,
                          onChanged: (value) {
                            if (value == null) return;
                            // ignore: discarded_futures
                            provider.setFocusLockContentPageIds(
                                value == provider.currentPage.id
                                    ? <String>{}
                                    : <String>{value});
                            setS(() {});
                            if (mounted) setState(() {});
                          },
                          title: Text(
                            page.id == provider.currentPage.id
                                ? '${page.name}（現在のページ）'
                                : page.name,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              color: page.id == selectedPageId
                                  ? Colors.white
                                  : Colors.white70,
                              fontSize: 13,
                            ),
                          ),
                        ),
                    ],
                  ),
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => close(),
                child: Text(widget.provider.t('btn.close'),
                    style: const TextStyle(color: Colors.white70)),
              ),
            ],
          );
        },
      ),
    );
  }

  Widget _buildLockContentPanel() {
    if (!widget.provider.focusLockAllowContentAccess) {
      return const SizedBox.shrink();
    }
    final items = _lockContentItems();

    IconData iconFor(String kind) {
      switch (kind) {
        case '動画':
          return Icons.play_circle_fill_rounded;
        case 'ファイル':
          return Icons.insert_drive_file_rounded;
        default:
          return Icons.link_rounded;
      }
    }

    String titleFor(MindMapNode node, String value) {
      final title = node.title.trim();
      if (title.isNotEmpty) return title;
      final tail = value.split(RegExp(r'[\\/]')).last.trim();
      return tail.isEmpty ? value : tail;
    }

    return Container(
      constraints: const BoxConstraints(maxWidth: 360),
      margin: const EdgeInsets.symmetric(horizontal: 24),
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: Colors.white12),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(Icons.folder_open_rounded,
                  color: Color(0xFF43B97F), size: 16),
              const SizedBox(width: 6),
              Expanded(
                child: Text(widget.provider.t('lock.pageContent'),
                    style: TextStyle(
                        color: Colors.white.withValues(alpha: 0.8),
                        fontSize: 12,
                        fontWeight: FontWeight.w700)),
              ),
              TextButton.icon(
                style: TextButton.styleFrom(
                  foregroundColor: const Color(0xFF43B97F),
                  padding:
                      const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                  minimumSize: const Size(0, 28),
                  tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                ),
                icon: const Icon(Icons.tune_rounded, size: 14),
                label: Text(widget.provider.t('lock.pageSelect'),
                    style:
                        TextStyle(fontSize: 11, fontWeight: FontWeight.w700)),
                onPressed: _showLockContentPageSelector,
              ),
            ],
          ),
          const SizedBox(height: 8),
          ConstrainedBox(
            constraints: const BoxConstraints(maxHeight: 156),
            child: items.isEmpty
                ? Padding(
                    padding: const EdgeInsets.symmetric(vertical: 8),
                    child: Text(widget.provider.t('lock.noPageContent'),
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 12)),
                  )
                : SingleChildScrollView(
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        for (final item in items.take(30))
                          Padding(
                            padding: const EdgeInsets.only(bottom: 6),
                            child: Material(
                              color: Colors.transparent,
                              child: InkWell(
                                onTap: () => _openLockContent(item.node),
                                borderRadius: BorderRadius.circular(10),
                                child: Padding(
                                  padding: const EdgeInsets.symmetric(
                                      horizontal: 2, vertical: 6),
                                  child: Row(
                                    children: [
                                      Icon(iconFor(item.kind),
