  }

  Widget _buildFocusTaskPanel() {
    final p = widget.provider;
    final tasks = p.focusLockTasks;
    final completed = tasks.where((task) => task.completed).length;
    final title = p
        .t('focusLock.taskProgress')
        .replaceAll('{done}', '$completed')
        .replaceAll('{total}', '${tasks.length}');

    return Container(
      constraints: const BoxConstraints(maxWidth: 380),
      margin: const EdgeInsets.symmetric(horizontal: 24),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(14),
        border:
            Border.all(color: const Color(0xFF43B97F).withValues(alpha: 0.5)),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Text(title,
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 14,
                  fontWeight: FontWeight.w700)),
          const SizedBox(height: 10),
          LinearProgressIndicator(
            value: tasks.isEmpty ? 0 : completed / tasks.length,
            minHeight: 5,
            borderRadius: BorderRadius.circular(3),
            backgroundColor: Colors.white12,
            valueColor: const AlwaysStoppedAnimation<Color>(Color(0xFF43B97F)),
          ),
          const SizedBox(height: 8),
          if (tasks.isEmpty)
            Text(p.t('focusLock.noTasks'),
                style: const TextStyle(color: Colors.white54, fontSize: 12))
          else
            // 並べ替え + 編集に対応 (= ユーザー要望: ロック画面からも編集
            // したい / 表示順を入れ替えたい)。
            ReorderableListView.builder(
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              buildDefaultDragHandles: false,
              itemCount: tasks.length,
              onReorder: (oldIndex, newIndex) async {
                await p.reorderFocusLockTask(oldIndex, newIndex);
                if (mounted) setState(() {});
              },
              itemBuilder: (_, i) {
                final task = tasks[i];
                return Row(key: ValueKey(task.id), children: [
                  ReorderableDragStartListener(
                    index: i,
                    child: const Icon(Icons.drag_indicator_rounded,
                        color: Colors.white24, size: 18),
                  ),
                  Checkbox(
                    value: task.completed,
                    activeColor: const Color(0xFF43B97F),
                    visualDensity: VisualDensity.compact,
                    onChanged: (value) =>
                        _setFocusTaskCompleted(task, value ?? false),
                  ),
                  Expanded(
                    child: Text(task.title,
                        style: TextStyle(
                            color:
                                task.completed ? Colors.white54 : Colors.white,
                            fontSize: 13,
                            decoration: task.completed
                                ? TextDecoration.lineThrough
                                : null)),
                  ),
                  IconButton(
                    visualDensity: VisualDensity.compact,
                    icon: const Icon(Icons.edit_rounded,
                        color: Colors.white38, size: 16),
                    onPressed: () => _editFocusTaskFromLock(task),
                  ),
                  IconButton(
                    visualDensity: VisualDensity.compact,
                    icon: const Icon(Icons.delete_outline_rounded,
                        color: Colors.white38, size: 16),
                    onPressed: () async {
                      await p.removeFocusLockTask(task.id);
                      if (!mounted) return;
                      setState(() {});
                      // 最後の 1 件を消して空になったら、 解除するか聞く
                      // (= ユーザー要望: 完了ではなく削除で 0 件になった時)。
                      if (p.focusLockTasks.isEmpty) {
                        await _confirmUnlockAfterAllTasksRemoved();
                      }
                    },
                  ),
                ]);
              },
            ),
          const SizedBox(height: 4),
          // ── ロック中でもタスクを追加できる (= ユーザー要望) ──
          Align(
            alignment: Alignment.centerLeft,
            child: TextButton.icon(
              onPressed: _addFocusTaskFromLock,
              style: TextButton.styleFrom(
                foregroundColor: const Color(0xFF43B97F),
                padding: const EdgeInsets.symmetric(horizontal: 6),
                minimumSize: const Size(0, 32),
                tapTargetSize: MaterialTapTargetSize.shrinkWrap,
              ),
              icon: const Icon(Icons.add_rounded, size: 18),
              label: Text(widget.provider.t('focusLock.addTask'),
                  style: const TextStyle(fontSize: 12)),
            ),
          ),
          const SizedBox(height: 2),
          Text(p.t('focusLock.taskUnlockHint'),
              textAlign: TextAlign.center,
              style: const TextStyle(color: Colors.white38, fontSize: 11)),
          if (p.areAllFocusLockTasksCompleted) ...[
            const SizedBox(height: 8),
            FilledButton.icon(
              style: FilledButton.styleFrom(
                backgroundColor: const Color(0xFF43B97F),
                foregroundColor: Colors.white,
              ),
              onPressed: _taskUnlockConfirmationOpen
                  ? null
                  : _requestFocusTaskUnlockConfirmation,
              icon: const Icon(Icons.lock_open_rounded, size: 17),
              label: Text(p.t('focusLock.taskUnlockPendingAction')),
            ),
          ],
        ],
      ),
    );
  }

  /// ロック画面からタスク名を編集する (= ユーザー要望)。
  Future<void> _editFocusTaskFromLock(FocusLockTask task) async {
    final p = widget.provider;
    final ctrl = TextEditingController(text: task.title);
    final name = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(p.t('focusLock.editTask'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white, fontSize: 13),
          decoration: InputDecoration(
            hintText: p.t('focusLock.taskInputHint'),
            hintStyle: const TextStyle(color: Colors.white38, fontSize: 12),
            filled: true,
            fillColor: Colors.white.withValues(alpha: 0.07),
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(9),
              borderSide: BorderSide.none,
            ),
          ),
          onSubmitted: (v) => Navigator.pop(dctx, v.trim()),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(p.t('common.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF43B97F),
                foregroundColor: Colors.white),
            onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
            child: Text(p.t('btn.save')),
          ),
        ],
      ),
    );
    if (name == null || name.isEmpty) return;
    await p.renameFocusLockTask(task.id, name);
    if (mounted) setState(() {});
  }

  // ── 自然音 / ブラウンノイズ (= ユーザー要望: 人気音楽ボタンは削除して、
  //    代わりにフリー素材の自然音やブラウンノイズを聴けるボタンに) ──
  // 音源は `_AmbientSound` がアプリ内で合成して端末に保存し、 以後はその
  // ファイルをループ再生する (= オフラインでも必ず鳴る / 権利関係もクリア)。
  // ポモドーロと同じく、 別窓を出さずロック画面「内」に埋め込む。
  bool _lockAmbientOpen = false;
  bool _lockAmbientBusy = false;
  String? _lockAmbientPlaying = _AmbientSound.playing;
  double _lockAmbientVolume = 0.6;

  // ── ロック画面内アラーム (= ユーザー要望: 画面ロック機能の中にも
  //    アラームを設定できるように)。 ロック中に指定時刻で鳴らす。 ──
  bool _lockAlarmOpen = false;
  DateTime? _lockAlarmAt;
  Timer? _lockAlarmTimer;
  Timer? _lockAlarmRepeatTimer;
  bool _lockAlarmRinging = false;

  void _scheduleLockAlarm(DateTime at) {
    _lockAlarmTimer?.cancel();
    var target = at;
    // 過去時刻なら翌日として扱う (時刻指定で今より前を選んだ場合)。
    if (!target.isAfter(DateTime.now())) {
      target = target.add(const Duration(days: 1));
    }
    setState(() {
      _lockAlarmAt = target;
      _lockAlarmRinging = false;
    });
    _lockAlarmTimer = Timer(target.difference(DateTime.now()), _fireLockAlarm);
  }

  void _fireLockAlarm() {
    if (!mounted) return;
    setState(() => _lockAlarmRinging = true);
    // 止めるまで繰り返し鳴らす (アラームなので鳴りっぱなしが正)。
    // ignore: discarded_futures
    _AudioAlarm.playAlarm(_AudioAlarm.prefKeyTimer);
    _lockAlarmRepeatTimer?.cancel();
    _lockAlarmRepeatTimer = Timer.periodic(const Duration(seconds: 10), (_) {
      if (!mounted || !_lockAlarmRinging) return;
      // ignore: discarded_futures
      _AudioAlarm.playAlarm(_AudioAlarm.prefKeyTimer);
    });
  }

  void _stopLockAlarmRinging() {
    _lockAlarmRepeatTimer?.cancel();
    _lockAlarmRepeatTimer = null;
    // ignore: discarded_futures
    _AudioAlarm.stop();
    setState(() {
      _lockAlarmRinging = false;
      _lockAlarmAt = null;
    });
  }

  void _cancelLockAlarm() {
    _lockAlarmTimer?.cancel();
    _lockAlarmTimer = null;
    _lockAlarmRepeatTimer?.cancel();
    _lockAlarmRepeatTimer = null;
    // ignore: discarded_futures
    _AudioAlarm.stop();
    setState(() {
      _lockAlarmAt = null;
      _lockAlarmRinging = false;
    });
  }

  /// ロック画面のアラームパネル。
  Widget _buildLockAlarmPanel() {
    final p = widget.provider;
    String two(int n) => n.toString().padLeft(2, '0');
    final at = _lockAlarmAt;
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 24, vertical: 4),
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
      constraints: const BoxConstraints(maxWidth: 380),
      decoration: BoxDecoration(
        color: _lockAlarmRinging
            ? const Color(0xFFEF5350).withValues(alpha: 0.18)
            : Colors.white.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
            color: _lockAlarmRinging
                ? const Color(0xFFEF5350)
                : Colors.white.withValues(alpha: 0.14)),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(children: [
            Icon(Icons.alarm_rounded,
                size: 16,
                color: _lockAlarmRinging
                    ? const Color(0xFFEF5350)
                    : const Color(0xFFFFB347)),
            const SizedBox(width: 6),
            Expanded(
              child: Text(p.t('lockAlarm.title'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 13,
                      fontWeight: FontWeight.w700)),
            ),
            IconButton(
              tooltip: p.t('btn.close'),
              padding: EdgeInsets.zero,
              constraints:
                  const BoxConstraints.tightFor(width: 28, height: 28),
              icon: const Icon(Icons.expand_less_rounded,
                  color: Colors.white54, size: 20),
              onPressed: () => setState(() => _lockAlarmOpen = false),
            ),
          ]),
          const SizedBox(height: 8),
          if (_lockAlarmRinging) ...[
            Row(children: [
              Expanded(
                child: Text(p.t('lockAlarm.ringing'),
                    style: const TextStyle(
                        color: Color(0xFFEF5350),
                        fontSize: 13,
                        fontWeight: FontWeight.w700)),
              ),
              ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFEF5350),
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                      horizontal: 14, vertical: 8),
                ),
                icon: const Icon(Icons.alarm_off_rounded, size: 16),
                label: Text(p.t('lockAlarm.stop'),
                    style: const TextStyle(fontSize: 12)),
                onPressed: _stopLockAlarmRinging,
              ),
            ]),
          ] else if (at != null) ...[
            Row(children: [
              const Icon(Icons.schedule_rounded,
                  size: 14, color: Colors.white54),
              const SizedBox(width: 6),
              Expanded(
                child: Text(
                    p.t('lockAlarm.ringAt').replaceFirst(
                        '{t}', '${two(at.hour)}:${two(at.minute)}'),
                    style: const TextStyle(
                        color: Colors.white70, fontSize: 12.5)),
              ),
              TextButton.icon(
                onPressed: _cancelLockAlarm,
                icon: const Icon(Icons.alarm_off_rounded,
                    size: 15, color: Colors.white54),
                label: Text(p.t('lockAlarm.cancel'),
                    style:
                        const TextStyle(color: Colors.white54, fontSize: 11)),
                style: TextButton.styleFrom(
                  visualDensity: VisualDensity.compact,
                  padding: const EdgeInsets.symmetric(horizontal: 6),
                  minimumSize: const Size(0, 28),
                ),
              ),
            ]),
          ] else ...[
            // ── 時間の選択 ──
            // ActionChip はやめる (= ユーザー報告: ロック画面のアラームの
            //   ボタンが白飛びして文字が読めない)。 Material 3 の Chip は
            //   背景色の指定より配色側の既定が優先され、 暗い画面の上で
            //   真っ白なチップになっていた。 他のロック画面のボタンと同じ
            //   OutlinedButton に揃えると、 見た目も統一される。
            Wrap(spacing: 6, runSpacing: 6, children: [
              for (final min in [5, 10, 30, 60])
                OutlinedButton(
                  style: OutlinedButton.styleFrom(
                    foregroundColor: Colors.white70,
                    side: BorderSide(
                        color: Colors.white.withValues(alpha: 0.24)),
                    backgroundColor: Colors.white.withValues(alpha: 0.06),
                    padding: const EdgeInsets.symmetric(
                        horizontal: 12, vertical: 6),
                    minimumSize: const Size(0, 34),
                    tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  ),
                  onPressed: () => _scheduleLockAlarm(
                      DateTime.now().add(Duration(minutes: min))),
                  child: Text('+$min${p.t('lockAlarm.minSuffix')}',
                      style: const TextStyle(
                          color: Colors.white70, fontSize: 12)),
                ),
              OutlinedButton.icon(
                style: OutlinedButton.styleFrom(
                  foregroundColor: Colors.white70,
                  side:
                      BorderSide(color: Colors.white.withValues(alpha: 0.24)),
                  backgroundColor: Colors.white.withValues(alpha: 0.06),
                  padding:
                      const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                  minimumSize: const Size(0, 34),
                  tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                ),
                icon: const Icon(Icons.schedule_rounded,
                    size: 14, color: Colors.white54),
                label: Text(p.t('lockAlarm.pickTime'),
                    style:
                        const TextStyle(color: Colors.white70, fontSize: 12)),
                onPressed: () async {
                  final now = DateTime.now();
                  // ── ロック画面は root オーバーレイに直接乗せているので、
                  //    普通の showTimePicker はその「下」 に出てしまう
                  //    (= ユーザー報告)。 前面に出す入れ物の中で開く。 ──
                  final picked = await _showLockFrontDialog<TimeOfDay>(
                    (dctx, close) => _LockFrontTimePicker(
                      initial: TimeOfDay.fromDateTime(
                          now.add(const Duration(minutes: 30))),
                      onDone: close,
                    ),
                  );
                  if (picked == null || !mounted) return;
                  _scheduleLockAlarm(DateTime(now.year, now.month, now.day,
                      picked.hour, picked.minute));
                },
              ),
            ]),
          ],
        ],
      ),
    );
  }

  /// アラームパネルを開くボタン (自然音ボタンと同じ見た目)。
  Widget _buildLockAlarmButton() {
    final p = widget.provider;
    String two(int n) => n.toString().padLeft(2, '0');
    final at = _lockAlarmAt;
    final label = _lockAlarmRinging
        ? p.t('lockAlarm.ringing')
        : (at == null
            ? p.t('lockAlarm.title')
            : p
                .t('lockAlarm.ringAt')
                .replaceFirst('{t}', '${two(at.hour)}:${two(at.minute)}'));
    final color =
        _lockAlarmRinging ? const Color(0xFFEF5350) : const Color(0xFFFFB347);
    return ConstrainedBox(
      constraints: const BoxConstraints(maxWidth: 380),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 24),
        child: OutlinedButton.icon(
          style: OutlinedButton.styleFrom(
            foregroundColor: color,
            side: BorderSide(color: color),
            padding: const EdgeInsets.symmetric(vertical: 10),
            minimumSize: const Size(double.infinity, 0),
          ),
          icon: Icon(
              _lockAlarmRinging
                  ? Icons.alarm_on_rounded
                  : Icons.alarm_rounded,
              size: 18),
          label: Text(label),
          onPressed: () => setState(() => _lockAlarmOpen = true),
        ),
      ),
    );
  }

  Future<void> _loadLockAmbientVolume() async {
    final v = await _AmbientSound.volume();
    if (mounted) setState(() => _lockAmbientVolume = v);
  }

  Future<void> _toggleLockAmbient(String kind) async {
    if (_lockAmbientBusy) return;
    setState(() => _lockAmbientBusy = true);
    final started = await _AmbientSound.toggle(kind);
    if (!mounted) return;
    setState(() {
      _lockAmbientBusy = false;
      _lockAmbientPlaying = started ? kind : null;
    });
  }

  Future<void> _stopLockAmbient() async {
    await _AmbientSound.stop();
    if (mounted) setState(() => _lockAmbientPlaying = null);
  }

  /// ロック画面に埋め込む自然音パネル。
  Widget _buildLockAmbientPanel() {
    final p = widget.provider;
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 24, vertical: 4),
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
      constraints: const BoxConstraints(maxWidth: 380),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: Colors.white.withValues(alpha: 0.14)),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(children: [
            const Icon(Icons.spa_rounded, size: 16, color: Color(0xFF66BB6A)),
            const SizedBox(width: 6),
            Expanded(
              child: Text(p.t('ambient.title'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 13,
                      fontWeight: FontWeight.w700)),
            ),
            if (_lockAmbientPlaying != null)
              TextButton.icon(
                onPressed: _stopLockAmbient,
                icon: const Icon(Icons.stop_rounded,
                    size: 16, color: Colors.white70),
                label: Text(p.t('ambient.stop'),
                    style:
                        const TextStyle(color: Colors.white70, fontSize: 11)),
                style: TextButton.styleFrom(
                  visualDensity: VisualDensity.compact,
                  padding: const EdgeInsets.symmetric(horizontal: 6),
                  minimumSize: const Size(0, 28),
                ),
              ),
            IconButton(
              tooltip: p.t('btn.close'),
              padding: EdgeInsets.zero,
              constraints:
                  const BoxConstraints.tightFor(width: 28, height: 28),
              icon: const Icon(Icons.expand_less_rounded,
                  color: Colors.white54, size: 20),
              onPressed: () => setState(() => _lockAmbientOpen = false),
            ),
          ]),
          const SizedBox(height: 8),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: [
              for (final kind in _kAmbientKinds)
                _buildLockAmbientChip(kind),
            ],
          ),
          const SizedBox(height: 4),
          Row(children: [
            const Icon(Icons.volume_up_rounded,
                size: 16, color: Colors.white54),
            Expanded(
              child: SliderTheme(
                data: SliderTheme.of(context).copyWith(
                  trackHeight: 2,
                  thumbShape:
                      const RoundSliderThumbShape(enabledThumbRadius: 6),
                  activeTrackColor: const Color(0xFF66BB6A),
                  inactiveTrackColor: Colors.white24,
                  thumbColor: const Color(0xFF66BB6A),
                ),
                child: Slider(
                  value: _lockAmbientVolume.clamp(0.0, 1.0),
                  onChanged: (v) => setState(() => _lockAmbientVolume = v),
                  onChangeEnd: (v) => _AmbientSound.setVolume(v),
                ),
              ),
            ),
            Text('${(_lockAmbientVolume * 100).round()}%',
                style: const TextStyle(color: Colors.white54, fontSize: 11)),
          ]),
          Text(p.t('ambient.hint'),
              style: const TextStyle(color: Colors.white38, fontSize: 10.5)),
        ],
      ),
    );
