  Widget _buildLockAmbientChip(String kind) {
    final p = widget.provider;
    final on = _lockAmbientPlaying == kind;
    return InkWell(
      borderRadius: BorderRadius.circular(9),
      onTap: _lockAmbientBusy ? null : () => _toggleLockAmbient(kind),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
        decoration: BoxDecoration(
          color: on
              ? const Color(0xFF66BB6A).withValues(alpha: 0.22)
              : Colors.white.withValues(alpha: 0.05),
          borderRadius: BorderRadius.circular(9),
          border: Border.all(
              color: on ? const Color(0xFF66BB6A) : Colors.white24),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          Icon(on ? Icons.pause_rounded : _ambientIcon(kind),
              size: 15,
              color: on ? const Color(0xFF66BB6A) : Colors.white70),
          const SizedBox(width: 5),
          Text(p.t('ambient.kind.$kind'),
              style: TextStyle(
                  color: on ? Colors.white : Colors.white70,
                  fontSize: 12,
                  fontWeight: on ? FontWeight.w700 : FontWeight.w500)),
        ]),
      ),
    );
  }

  // ─── ポモドーロタイマー (ロック画面埋め込み) ─────────────────────────────
  /// = ユーザー要望: 新しい項目 (浮遊窓) を立ち上げるのではなく、
  ///   ロック画面「内」にタイマーを埋め込む。
  /// 設定 (作業/休憩の分数・サイクル数) は浮遊ポモドーロと同じ
  /// SharedPreferences キーを共有し、既存の設定がそのまま反映される。
  bool _lockPomodoroOpen = false;
  String _lockPomoPhase = 'work'; // 'work' / 'short' / 'long'
  bool _lockPomoRunning = false;
  Timer? _lockPomoTick;
  DateTime? _lockPomoEndAt;
  int _lockPomoRemainSec = 25 * 60;
  int _lockPomoDoneCycles = 0;
  int _lockPomoWorkMin = 25;
  int _lockPomoShortMin = 5;
  int _lockPomoLongMin = 15;
  int _lockPomoCyclesUntilLong = 4;

  int _lockPomoPhaseSec(String phase) => switch (phase) {
        'short' => _lockPomoShortMin * 60,
        'long' => _lockPomoLongMin * 60,
        _ => _lockPomoWorkMin * 60,
      };

  Future<void> _loadLockPomoSettings() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      if (!mounted) return;
      setState(() {
        _lockPomoWorkMin = prefs.getInt('pomodoro_workMin') ?? 25;
        _lockPomoShortMin = prefs.getInt('pomodoro_shortMin') ?? 5;
        _lockPomoLongMin = prefs.getInt('pomodoro_longMin') ?? 15;
        _lockPomoCyclesUntilLong = prefs.getInt('pomodoro_cyclesUntilLong') ?? 4;
        if (!_lockPomoRunning) {
          _lockPomoRemainSec = _lockPomoPhaseSec(_lockPomoPhase);
        }
      });
    } catch (_) {}
  }

  void _lockPomoStartPause() {
    if (_lockPomoRunning) {
      _lockPomoTick?.cancel();
      _lockPomoTick = null;
      setState(() {
        _lockPomoRunning = false;
        // 残りは endAt から確定させる (誤差の持ち越し防止)。
        if (_lockPomoEndAt != null) {
          _lockPomoRemainSec = _lockPomoEndAt!
              .difference(DateTime.now())
              .inSeconds
              .clamp(0, 24 * 3600);
        }
        _lockPomoEndAt = null;
      });
      return;
    }
    setState(() {
      _lockPomoRunning = true;
      _lockPomoEndAt =
          DateTime.now().add(Duration(seconds: _lockPomoRemainSec));
    });
    _lockPomoTick =
        Timer.periodic(const Duration(milliseconds: 500), (_) {
      final endAt = _lockPomoEndAt;
      if (endAt == null) return;
      final left = endAt.difference(DateTime.now()).inSeconds;
      if (left <= 0) {
        _lockPomoAdvancePhase();
      } else if (mounted && left != _lockPomoRemainSec) {
        setState(() => _lockPomoRemainSec = left);
      }
    });
  }

  /// フェーズ終了 → 次フェーズへ自動移行 (作業→休憩→作業…)。
  void _lockPomoAdvancePhase() {
    try {
      HapticFeedback.mediumImpact();
    } catch (_) {}
    String next;
    if (_lockPomoPhase == 'work') {
      _lockPomoDoneCycles++;
      next = (_lockPomoCyclesUntilLong > 0 &&
              _lockPomoDoneCycles % _lockPomoCyclesUntilLong == 0)
          ? 'long'
          : 'short';
    } else {
      next = 'work';
    }
    if (!mounted) return;
    setState(() {
      _lockPomoPhase = next;
      _lockPomoRemainSec = _lockPomoPhaseSec(next);
      _lockPomoEndAt =
          DateTime.now().add(Duration(seconds: _lockPomoRemainSec));
    });
  }

  void _lockPomoReset() {
    _lockPomoTick?.cancel();
    _lockPomoTick = null;
    setState(() {
      _lockPomoRunning = false;
      _lockPomoPhase = 'work';
      _lockPomoDoneCycles = 0;
      _lockPomoEndAt = null;
      _lockPomoRemainSec = _lockPomoPhaseSec('work');
    });
  }

  String _lockPomoFmt(int sec) {
    final s = sec < 0 ? 0 : sec;
    final m = s ~/ 60;
    final ss = s % 60;
    return '${m.toString().padLeft(2, '0')}:${ss.toString().padLeft(2, '0')}';
  }

  Widget _buildLockPomodoroButton() {
    final p = widget.provider;
    return ConstrainedBox(
      constraints: const BoxConstraints(maxWidth: 380),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 24),
        child: OutlinedButton.icon(
          style: OutlinedButton.styleFrom(
            foregroundColor: const Color(0xFFFF8A65),
            side: const BorderSide(color: Color(0xFFFF8A65)),
            padding: const EdgeInsets.symmetric(vertical: 10),
            minimumSize: const Size(double.infinity, 0),
          ),
          icon: Icon(
              _lockPomodoroOpen
                  ? Icons.expand_less_rounded
                  : Icons.timer_rounded,
              size: 18),
          label: Text(p.t('focusLock.pomodoro')),
          onPressed: () =>
              setState(() => _lockPomodoroOpen = !_lockPomodoroOpen),
        ),
      ),
    );
  }

  /// ロック画面内に埋め込むポモドーロタイマー本体。
  Widget _buildLockPomodoroPanel() {
    const accent = Color(0xFFFF8A65);
    final phaseLabel = switch (_lockPomoPhase) {
      'short' => '休憩',
      'long' => '長い休憩',
      _ => '作業',
    };
    final total = _lockPomoPhaseSec(_lockPomoPhase);
    final progress = total <= 0
        ? 0.0
        : (1.0 - _lockPomoRemainSec / total).clamp(0.0, 1.0).toDouble();
    return Container(
      constraints: const BoxConstraints(maxWidth: 380),
      margin: const EdgeInsets.symmetric(horizontal: 24),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: accent.withValues(alpha: 0.5)),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Row(
            children: [
              Icon(
                  _lockPomoPhase == 'work'
                      ? Icons.edit_note_rounded
                      : Icons.free_breakfast_rounded,
                  color: accent,
                  size: 17),
              const SizedBox(width: 6),
              Text(phaseLabel,
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 13,
                      fontWeight: FontWeight.w700)),
              const Spacer(),
              Text(
                  widget.provider
                      .t('pomo.cycleN')
                      .replaceFirst('{n}', '$_lockPomoDoneCycles'),
                  style:
                      const TextStyle(color: Colors.white54, fontSize: 11)),
            ],
          ),
          const SizedBox(height: 8),
          Text(
            _lockPomoFmt(_lockPomoRemainSec),
            style: const TextStyle(
              color: Colors.white,
              fontSize: 40,
              fontWeight: FontWeight.w800,
              fontFeatures: [FontFeature.tabularFigures()],
            ),
          ),
          const SizedBox(height: 8),
          LinearProgressIndicator(
            value: progress,
            minHeight: 5,
            borderRadius: BorderRadius.circular(3),
            backgroundColor: Colors.white12,
            valueColor: const AlwaysStoppedAnimation<Color>(accent),
          ),
          const SizedBox(height: 12),
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              FilledButton.icon(
                style: FilledButton.styleFrom(
                  backgroundColor: accent,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                      horizontal: 18, vertical: 8),
                ),
                icon: Icon(
                    _lockPomoRunning
                        ? Icons.pause_rounded
                        : Icons.play_arrow_rounded,
                    size: 20),
                label: Text(_lockPomoRunning ? '一時停止' : '開始'),
                onPressed: _lockPomoStartPause,
              ),
              const SizedBox(width: 10),
              IconButton(
                tooltip: widget.provider.t('pomo.nextPhase'),
                icon: const Icon(Icons.skip_next_rounded,
                    color: Colors.white70),
                onPressed: _lockPomoAdvancePhase,
              ),
              IconButton(
                tooltip: widget.provider.t('pomodoro.reset'),
                icon: const Icon(Icons.restart_alt_rounded,
                    color: Colors.white70),
                onPressed: _lockPomoReset,
              ),
            ],
          ),
        ],
      ),
    );
  }

  /// 自然音 / ノイズのパネルを開くボタン (= 旧「人気音楽を聴く」 の置き換え)。
  Widget _buildLockAmbientButton() {
    final p = widget.provider;
    return ConstrainedBox(
      constraints: const BoxConstraints(maxWidth: 380),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 24),
        child: OutlinedButton.icon(
          style: OutlinedButton.styleFrom(
            foregroundColor: const Color(0xFF66BB6A),
            side: const BorderSide(color: Color(0xFF66BB6A)),
            padding: const EdgeInsets.symmetric(vertical: 10),
            minimumSize: const Size(double.infinity, 0),
          ),
          icon: const Icon(Icons.spa_rounded, size: 18),
          label: Text(p.t('ambient.title')),
          onPressed: () {
            setState(() => _lockAmbientOpen = true);
            _loadLockAmbientVolume();
          },
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final p = widget.provider;
    final totalSec = widget.duration.inSeconds;
    final progress =
        totalSec <= 0 ? 1.0 : (1.0 - (_remainSec / totalSec)).clamp(0.0, 1.0);

    return PopScope(
      canPop: false,
      child: Material(
        color: const Color(0xFF0A0A14),
        child: SafeArea(
          child: Column(
            children: [
              Expanded(
                child: Center(
                  child: SingleChildScrollView(
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Icon(
                            widget.taskMode
                                ? Icons.task_alt_rounded
                                : Icons.lock_clock_rounded,
                      color: widget.taskMode
                          ? const Color(0xFF43B97F)
                          : const Color(0xFFEF5350),
                      size: 48),
                  const SizedBox(height: 12),
                  Text(
                    p.t('focusLock.locked'),
                    style: const TextStyle(
                        color: Colors.white70,
                        fontSize: 15,
                        fontWeight: FontWeight.w600,
                        letterSpacing: 1.0),
                  ),
                  const SizedBox(height: 24),
                  // タスク一覧は常に表示する (= ユーザー要望: 「取り組むべき
                  // タスク」 と 「集中タスク」 は同じものなので 1 つに統合)。
                  if (widget.taskMode)
                    _buildFocusTaskPanel()
                  else ...[
                    // ── カウントダウン (円形プログレス付き) ──
                    SizedBox(
                      width: 220,
                      height: 220,
                      child: Stack(
                        alignment: Alignment.center,
                        children: [
                          SizedBox(
                            width: 220,
                            height: 220,
                            child: CircularProgressIndicator(
                              value: progress,
                              strokeWidth: 8,
                              backgroundColor:
                                  Colors.white.withValues(alpha: 0.08),
                              valueColor: const AlwaysStoppedAnimation(
                                  Color(0xFFEF5350)),
                            ),
                          ),
                          Text(
                            _fmt(_remainSec),
                            style: const TextStyle(
                              color: Colors.white,
                              fontSize: 44,
                              fontWeight: FontWeight.w800,
                              fontFeatures: [FontFeature.tabularFigures()],
                              letterSpacing: 1.0,
                            ),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(height: 16),
                    // ── 現在時刻 → 解除時刻 (ユーザー要望) ──
                    Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        const Icon(Icons.schedule_rounded,
                            color: Colors.white38, size: 15),
                        const SizedBox(width: 6),
                        Text(
                          '${_fmtClock(DateTime.now())}  →  '
                          '${_fmtClock(_endAt)} ${p.t('focusLock.unlockAt')}',
                          style: const TextStyle(
                              color: Colors.white54,
                              fontSize: 14,
                              fontFeatures: [FontFeature.tabularFigures()]),
                        ),
                      ],
                    ),
                  ],
                  const SizedBox(height: 20),
                  // タイマーモードでもタスクを見て消化できるように
                  // (= 統合後の唯一のタスク一覧)。
                  if (!widget.taskMode) ...[
                    _buildFocusTaskPanel(),
                    const SizedBox(height: 12),
                  ],
                  // ── 今日の予定 (時刻付きのみ) + ロック中メモ ──
                  _buildUpcomingEvents(),
                  const SizedBox(height: 12),
                  _buildLockMemoPanel(),
                  const SizedBox(height: 12),
                  _buildLockContentPanel(),
                  const SizedBox(height: 12),
                  // ── 人気音楽 TOP を自動取得して聴くモード (= ユーザー要望) ──
                  // 自然音 / ノイズ: 閉じている間はボタン、 開いたら
                  // ロック画面内に埋め込んだパネル (= ユーザー要望)。
                  // 自然音は設定で無効にできる (= ユーザー要望)。
                  if (p.lockAmbientEnabled)
                    if (_lockAmbientOpen)
                      _buildLockAmbientPanel()
                    else
                      _buildLockAmbientButton(),
                  const SizedBox(height: 10),
                  // ── ポモドーロタイマー / アラーム ──
                  //    置くかどうかは設定で選べる (= ユーザー要望: 配置
                  //    するかの設定項目)。
                  if (p.focusLockShowPomodoro) ...[
                    _buildLockPomodoroButton(),
                    if (_lockPomodoroOpen) ...[
                      const SizedBox(height: 10),
                      _buildLockPomodoroPanel(),
                    ],
                    const SizedBox(height: 10),
                  ],
                  if (p.focusLockShowAlarm)
                    if (_lockAlarmOpen)
                      _buildLockAlarmPanel()
                    else
                      _buildLockAlarmButton(),
                  // ── 通信系操作 (電話/SMS/Wi-Fi/テザリング) は非表示
                  //    (= ユーザー要望: 集中ロック画面に 4 項目を出さない) ──
                  const SizedBox(height: 20),
                  // ── 緊急解除ボタン (3 秒長押し) ──
                  // 設定で表示/非表示を切り替える。現行UIでは
                  // focusLockHideUnlockButton == true が「表示する」。
                  // タスク完了制でも表示する (= ユーザー報告: 「解除ボタンを
                  // 表示する」 にしても出てこない)。
                  if (p.focusLockHideUnlockButton) ...[
                    GestureDetector(
                      onTapDown: (_) => _startHold(),
                      onTapUp: (_) => _cancelHold(),
                      onTapCancel: _cancelHold,
                      child: SizedBox(
                        width: 76,
                        height: 76,
                        child: Stack(
                          alignment: Alignment.center,
                          children: [
                            SizedBox(
                              width: 76,
                              height: 76,
                              child: CircularProgressIndicator(
                                value: _holdProgress,
                                strokeWidth: 4,
                                backgroundColor:
                                    Colors.white.withValues(alpha: 0.12),
                                valueColor: const AlwaysStoppedAnimation(
                                    Colors.white70),
                              ),
                            ),
                            Container(
                              width: 60,
                              height: 60,
                              decoration: BoxDecoration(
                                shape: BoxShape.circle,
                                color: Colors.white.withValues(alpha: 0.06),
                                border:
                                    Border.all(color: Colors.white24, width: 1),
                              ),
                              child: const Icon(Icons.lock_open_rounded,
                                  color: Colors.white60, size: 26),
                            ),
                          ],
                        ),
                      ),
                    ),
                    const SizedBox(height: 14),
                    Text(
                      p.t('focusLock.holdToExit'),
                      style:
                          const TextStyle(color: Colors.white38, fontSize: 12),
                    ),
                        ],
                      ],
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ─── ポモドーロタイマー（フローティング）─────────────────────────────────────
// 作業 → 短い休憩 (×N サイクル) → 長い休憩 のループ。
// デフォルト: 25 分作業 / 5 分休憩 / 4 サイクル後に 15 分休憩。
// 設定は SharedPreferences で永続化。Esc で閉じる。
class _FloatingPomodoro extends StatefulWidget {
  final MindMapProvider provider;
  final Offset initialOffset;
  final ValueChanged<Duration>? onLockDuringWork;
  final VoidCallback onClose;
  final bool hidden;
  const _FloatingPomodoro({
    required this.provider,
    required this.initialOffset,
    this.onLockDuringWork,
    required this.onClose,
    this.hidden = false,
  });
  @override
  State<_FloatingPomodoro> createState() => _FloatingPomodoroState();
}

class _FloatingPomodoroState extends State<_FloatingPomodoro> {
  late Offset _offset;

  /// 折り畳み状態 (true ならヘッダーだけ表示。Tick は維持される)。
  bool _collapsed = false;

  // ── 設定（永続化）─────────────────────────────
  static const _kWork = 'pomodoro_workMin';
  static const _kShort = 'pomodoro_shortMin';
  static const _kLong = 'pomodoro_longMin';
  static const _kCycles = 'pomodoro_cyclesUntilLong';
  static const _kAlarm = 'pomodoro_alarmEnabled';
  static const _kAutoNext = 'pomodoro_autoNext';
  static const _kLockDuringWork = 'pomodoro_lockDuringWorkMobile';
  int _workMin = 25;
  int _shortBreakMin = 5;
  int _longBreakMin = 15;
  int _cyclesUntilLong = 4;
  bool _alarmEnabled = true;
  bool _autoNext = true;
  bool _lockDuringWork = false;

  // ── 実行状態 ─────────────────────────────────
  /// 'work' / 'short' / 'long'
  String _phase = 'work';
  int _completedWorkCycles = 0;
  int _remainSec = 25 * 60;
  Timer? _tick;
  bool _running = false;

  /// _running 中の終了予定時刻 (1 秒の積み上げ誤差を回避)
  DateTime? _endAt;

  /// 設定編集モード (true なら設定 UI を、false なら時計を表示)
  bool _settingsMode = false;

  bool get _isMobileScreen => MediaQuery.of(context).size.width < 600;
  bool get _canLockDuringWork =>
      !kIsWeb &&
      (Platform.isAndroid || Platform.isIOS) &&
      _isMobileScreen &&
      widget.onLockDuringWork != null;

  @override
  void initState() {
    super.initState();
    _offset = widget.initialOffset;
    _loadSettings();
    HardwareKeyboard.instance.addHandler(_handleKey);
  }

  @override
  void dispose() {
    HardwareKeyboard.instance.removeHandler(_handleKey);
    _tick?.cancel();
    super.dispose();
  }

  Future<void> _loadSettings() async {
    final prefs = await SharedPreferences.getInstance();
    if (!mounted) return;
    setState(() {
      _workMin = prefs.getInt(_kWork) ?? 25;
      _shortBreakMin = prefs.getInt(_kShort) ?? 5;
      _longBreakMin = prefs.getInt(_kLong) ?? 15;
      _cyclesUntilLong = prefs.getInt(_kCycles) ?? 4;
      _alarmEnabled = prefs.getBool(_kAlarm) ?? true;
      _autoNext = prefs.getBool(_kAutoNext) ?? true;
      _lockDuringWork = prefs.getBool(_kLockDuringWork) ?? false;
      // 残り時間は work の設定に同期（停止中のみ）
      if (!_running) {
        _remainSec = _phase == 'work'
            ? _workMin * 60
            : (_phase == 'short' ? _shortBreakMin * 60 : _longBreakMin * 60);
      }
    });
  }

  Future<void> _saveSettings() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setInt(_kWork, _workMin);
    await prefs.setInt(_kShort, _shortBreakMin);
    await prefs.setInt(_kLong, _longBreakMin);
    await prefs.setInt(_kCycles, _cyclesUntilLong);
    await prefs.setBool(_kAlarm, _alarmEnabled);
    await prefs.setBool(_kAutoNext, _autoNext);
    await prefs.setBool(_kLockDuringWork, _lockDuringWork);
  }

  bool _handleKey(KeyEvent event) {
    if (event is! KeyDownEvent) return false;
    final focused = FocusManager.instance.primaryFocus;
    if (focused != null && focused.context?.widget is EditableText) {
      return false;
    }
    if (event.logicalKey == LogicalKeyboardKey.escape) {
      // 旧: Esc で閉じる → タイマーがリセットされるのが不便。
      // 新: Esc は畳む/展開のトグル。タイマー Tick は維持されるので
      //     残時間は進み続け、再 Esc で本体が戻ってくる。
      setState(() => _collapsed = !_collapsed);
      return true;
    }
    // Space で再生/停止 (テキスト編集中以外)
    if (event.logicalKey == LogicalKeyboardKey.space) {
      _toggleStartStop();
      return true;
    }
    return false;
  }

  void _toggleStartStop() {
    if (_running) {
      _stop();
    } else {
      _start();
    }
  }

  void _start() {
    if (_remainSec <= 0) {
      _setPhaseDuration();
    }
    _running = true;
    _endAt = DateTime.now().add(Duration(seconds: _remainSec));
    if (_phase == 'work' && _lockDuringWork && _canLockDuringWork) {
      widget.onLockDuringWork?.call(Duration(seconds: _remainSec));
    }
    _tick?.cancel();
    _tick = Timer.periodic(const Duration(milliseconds: 250), (_) {
      if (!mounted || !_running) return;
      final now = DateTime.now();
      final remain = _endAt!.difference(now).inSeconds;
      if (remain <= 0) {
        _onPhaseEnd();
      } else {
        if (remain != _remainSec) {
          setState(() => _remainSec = remain);
        }
      }
    });
    setState(() {});
  }

  void _stop() {
    _running = false;
    _tick?.cancel();
    if (_endAt != null) {
      _remainSec = _endAt!.difference(DateTime.now()).inSeconds.clamp(0, 99999);
    }
    setState(() {});
  }

  void _reset() {
    _running = false;
    _tick?.cancel();
    _completedWorkCycles = 0;
    _phase = 'work';
    _setPhaseDuration();
    setState(() {});
  }

  void _skipPhase() {
    _running = false;
    _tick?.cancel();
    _onPhaseEnd(skipAudio: true);
  }

  void _setPhaseDuration() {
    switch (_phase) {
      case 'work':
        _remainSec = _workMin * 60;
        break;
      case 'short':
        _remainSec = _shortBreakMin * 60;
        break;
      case 'long':
        _remainSec = _longBreakMin * 60;
        break;
    }
  }

  void _onPhaseEnd({bool skipAudio = false}) {
    final wasWork = _phase == 'work';
    final endedPhase = _phase;
    if (wasWork) {
      _completedWorkCycles++;
      // N サイクル完了したら長い休憩、そうでなければ短い休憩
      if (_completedWorkCycles % _cyclesUntilLong == 0) {
        _phase = 'long';
      } else {
        _phase = 'short';
      }
    } else {
      _phase = 'work';
    }
    _setPhaseDuration();
    if (_alarmEnabled && !skipAudio) {
      // ユーザー設定のカスタム音 (mp3/mp4 等) → 失敗時は SystemSound 連打の
      // 既定音にフォールバック。旧実装は alert 1 回だけだったので
      // 気付きにくいという指摘があり、ヘルパ側でデフォルトを強化済。
      _AudioAlarm.playAlarm(_AudioAlarm.prefKeyPomodoro);
    }
    // ── システム通知 (SnackBar) ──
    // ユーザー要望: カウントダウン終了時に分かりやすい通知が欲しい。
    // 外部プラグイン (flutter_local_notifications) を増やさず、アプリ内
    // SnackBar で目立つ通知を出す。skipAudio=true (手動スキップ) では
    // 通知も出さない。
    if (!skipAudio) {
      _showPhaseEndNotification(endedPhase, _phase);
    }
    _running = false;
    _tick?.cancel();
    if (_autoNext && !skipAudio) {
      // 自動で次のフェーズを開始
      _start();
    } else {
      setState(() {});
    }
  }

  /// フェーズ終了時の SnackBar 通知。
  /// 「作業 終了 → 休憩 開始」のように、終わったフェーズと次のフェーズを
  /// 一目で分かる形で表示。色も次フェーズに合わせる。
  void _showPhaseEndNotification(String endedPhase, String nextPhase) {
    final p = widget.provider;
    final overlay = Overlay.maybeOf(context, rootOverlay: true);
    if (overlay == null) return;
    final ctx = overlay.context;
    final messenger = ScaffoldMessenger.maybeOf(ctx);
    if (messenger == null) return;
    String labelOf(String ph) {
      switch (ph) {
        case 'work':
          return p.t('pomodoro.work');
        case 'short':
          return p.t('pomodoro.shortBreak');
        case 'long':
          return p.t('pomodoro.longBreak');
        default:
          return ph;
      }
    }

    Color colorOf(String ph) {
      switch (ph) {
        case 'work':
          return const Color(0xFFFF6B6B);
        case 'short':
          return const Color(0xFF43B97F);
        case 'long':
          return const Color(0xFF4FC3F7);
        default:
          return Colors.white;
      }
    }

    final endedLabel = labelOf(endedPhase);
    final nextLabel = labelOf(nextPhase);
    final nextColor = colorOf(nextPhase);
    _appSnackM(
        messenger,
        SnackBar(
          backgroundColor: const Color(0xFF2A2A3E),
          duration: const Duration(seconds: 6),
          behavior: SnackBarBehavior.floating,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(10),
            side: BorderSide(color: nextColor, width: 1.5),
          ),
          content: Row(children: [
            Icon(Icons.notifications_active_rounded,
                color: nextColor, size: 22),
            const SizedBox(width: 10),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text('🍅 $endedLabel ${p.t('pomodoro.notify.ended')}',
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 13,
                          fontWeight: FontWeight.w700)),
                  Text('${p.t('pomodoro.notify.next')}: $nextLabel',
                      style: TextStyle(
                          color: nextColor,
                          fontSize: 11,
                          fontWeight: FontWeight.w600)),
                ],
              ),
            ),
          ]),
        ));
  }

  String _formatTime(int seconds) {
    final m = (seconds ~/ 60).toString().padLeft(2, '0');
    final s = (seconds % 60).toString().padLeft(2, '0');
    return '$m:$s';
  }

  String _phaseLabel(MindMapProvider p) {
    switch (_phase) {
      case 'work':
        return p.t('pomodoro.work');
      case 'short':
        return p.t('pomodoro.shortBreak');
      case 'long':
        return p.t('pomodoro.longBreak');
      default:
        return '';
    }
  }

  Color _phaseColor() {
    switch (_phase) {
      case 'work':
        return const Color(0xFFFF6B6B);
      case 'short':
        return const Color(0xFF43B97F);
      case 'long':
        return const Color(0xFF4FC3F7);
      default:
        return Colors.white;
    }
  }

  @override
  Widget build(BuildContext context) {
    final mq = MediaQuery.of(context);
    final screen = mq.size;
    final bool isMobile = _isMobileScreen;
    final double panelW = isMobile ? 220.0 : 280.0;
    final double panelH =
        _settingsMode ? (isMobile ? 360.0 : 420.0) : (isMobile ? 300.0 : 360.0);
    // 折り畳み時はヘッダーのみ。共通の小さな幅に揃える。
    final double effectiveW =
        _collapsed ? _collapsedFloatingWidth(isMobile) : panelW;
    // ヘッダーだけ画面内に残れば下端まで動かせる仕様で統一
    const double headerVisible = 36.0;
    final double safeTop = mq.padding.top;
    final double safeBottom = mq.padding.bottom;
    final double maxLeft = (screen.width - effectiveW).clamp(0.0, screen.width);
    final double maxTop = (screen.height - safeBottom - headerVisible)
        .clamp(safeTop, screen.height);
    final clampedLeft = _offset.dx.clamp(0.0, maxLeft);
    final clampedTop = _offset.dy.clamp(safeTop, maxTop);
    final p = widget.provider;
    final phaseColor = _phaseColor();

    return Positioned(
      left: clampedLeft,
      top: clampedTop,
      // Offstage で裏に隠す (Tick・残時間・サイクル数は維持される)。
      child: Offstage(
        offstage: widget.hidden,
        child: ExcludeFocus(
          child: Material(
            elevation: 12,
            borderRadius: BorderRadius.circular(14),
            color: Colors.transparent,
            child: Container(
              width: effectiveW,
              decoration: BoxDecoration(
                color: const Color(0xFF1E1E32),
                borderRadius: BorderRadius.circular(14),
                border: Border.all(
                    color: phaseColor.withValues(alpha: 0.5), width: 1.5),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withValues(alpha: 0.5),
                    blurRadius: 16,
                    offset: const Offset(0, 6),
                  ),
                ],
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  // ── ヘッダー（ドラッグ + フェーズ表示 + 設定/閉じる）─────
                  GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onPanUpdate: (d) {
                      setState(() {
                        _offset = Offset(
                          (_offset.dx + d.delta.dx).clamp(0.0, maxLeft),
                          (_offset.dy + d.delta.dy).clamp(safeTop, maxTop),
                        );
                      });
                    },
                    child: MouseRegion(
                      cursor: SystemMouseCursors.move,
                      child: Container(
                        padding: EdgeInsets.symmetric(
                            horizontal: isMobile ? 8 : 10,
                            vertical: isMobile ? 5 : 8),
                        decoration: BoxDecoration(
                          color: phaseColor.withValues(alpha: 0.22),
                          borderRadius: const BorderRadius.only(
                            topLeft: Radius.circular(13),
                            topRight: Radius.circular(13),
                          ),
                        ),
                        child: Row(children: [
                          Icon(Icons.drag_indicator_rounded,
                              color: Colors.white54, size: isMobile ? 14 : 16),
                          const SizedBox(width: 4),
                          Icon(Icons.av_timer_rounded,
                              color: phaseColor, size: isMobile ? 15 : 18),
                          const SizedBox(width: 6),
                          Expanded(
                            child: Text(p.t('hdr.pomodoro'),
                                style: TextStyle(
                                    color: Colors.white,
                                    fontSize: isMobile ? 11 : 13,
                                    fontWeight: FontWeight.w700)),
                          ),
                          // 設定モード切替 (折り畳み時はヘッダー幅を最小化するため非表示)
                          if (!_collapsed)
                            MouseRegion(
                              cursor: SystemMouseCursors.click,
                              child: GestureDetector(
                                onTap: () {
                                  if (_settingsMode) _saveSettings();
                                  setState(
                                      () => _settingsMode = !_settingsMode);
                                },
                                child: Padding(
                                  padding: EdgeInsets.all(isMobile ? 3 : 4),
                                  child: Icon(
                                    _settingsMode
                                        ? Icons.timer_rounded
                                        : Icons.settings_rounded,
                                    color: Colors.white54,
                                    size: isMobile ? 14 : 16,
                                  ),
                                ),
                              ),
                            ),
                          // 折り畳みボタン: 本体を隠してヘッダーだけ残す。
                          // タイマー Tick は維持されるので残時間は進み続ける。
                          MouseRegion(
                            cursor: SystemMouseCursors.click,
                            child: GestureDetector(
                              onTap: () =>
                                  setState(() => _collapsed = !_collapsed),
                              child: Padding(
                                padding: EdgeInsets.all(isMobile ? 3 : 4),
                                child: Icon(
                                    _collapsed
                                        ? Icons.expand_more_rounded
                                        : Icons.expand_less_rounded,
                                    color: Colors.white70,
                                    size: isMobile ? 16 : 18),
                              ),
                            ),
                          ),
                          MouseRegion(
                            cursor: SystemMouseCursors.click,
                            child: GestureDetector(
                              onTap: widget.onClose,
                              child: Padding(
                                padding: EdgeInsets.all(isMobile ? 3 : 4),
                                child: Icon(Icons.close,
                                    color: Colors.white54,
                                    size: isMobile ? 14 : 16),
                              ),
                            ),
                          ),
                        ]),
                      ),
                    ),
                  ),
                  // ── 本体 ─────
                  if (!_collapsed)
                    Padding(
                      padding: EdgeInsets.all(isMobile ? 10 : 14),
                      child: _settingsMode
                          ? _buildSettingsBody(p, isMobile)
                          : _buildTimerBody(p, isMobile, phaseColor),
                    ),
                ],
              ),
            ),
          ),
        ),
      ), // Offstage
    );
  }

  Widget _buildTimerBody(MindMapProvider p, bool isMobile, Color phaseColor) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        // フェーズラベル
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
          decoration: BoxDecoration(
            color: phaseColor.withValues(alpha: 0.18),
            borderRadius: BorderRadius.circular(20),
            border: Border.all(color: phaseColor.withValues(alpha: 0.5)),
          ),
          child: Text(
            _phaseLabel(p),
            style: TextStyle(
                color: phaseColor,
                fontSize: isMobile ? 12 : 14,
                fontWeight: FontWeight.w700),
          ),
        ),
        SizedBox(height: isMobile ? 14 : 18),
        // 大きい時計
        Text(
          _formatTime(_remainSec),
          style: TextStyle(
              color: Colors.white,
              fontSize: isMobile ? 48 : 60,
              fontWeight: FontWeight.w300,
              fontFeatures: const [FontFeature.tabularFigures()]),
        ),
        SizedBox(height: isMobile ? 10 : 14),
        // サイクル進捗（ドット表示）
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: List.generate(_cyclesUntilLong, (i) {
            final completed = (_completedWorkCycles % _cyclesUntilLong) > i;
            final current = (_completedWorkCycles % _cyclesUntilLong) == i &&
                _phase == 'work';
            return Container(
              width: 9,
              height: 9,
              margin: const EdgeInsets.symmetric(horizontal: 3),
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: completed
                    ? const Color(0xFFFF6B6B)
                    : (current
                        ? const Color(0xFFFF6B6B).withValues(alpha: 0.4)
                        : Colors.white.withValues(alpha: 0.15)),
                border: current
                    ? Border.all(color: const Color(0xFFFF6B6B), width: 1.5)
                    : null,
              ),
            );
          }),
        ),
        SizedBox(height: isMobile ? 14 : 18),
        // 操作ボタン
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceEvenly,
          children: [
            _PomodoroBtn(
              icon: Icons.refresh_rounded,
              color: Colors.white54,
              onTap: _reset,
              size: isMobile ? 36 : 40,
              tooltip: p.t('pomodoro.reset'),
            ),
            _PomodoroBtn(
              icon: _running ? Icons.pause_rounded : Icons.play_arrow_rounded,
              color: phaseColor,
              onTap: _toggleStartStop,
              size: isMobile ? 50 : 58,
              filled: true,
              tooltip: _running ? p.t('pomodoro.pause') : p.t('pomodoro.start'),
            ),
            _PomodoroBtn(
              icon: Icons.skip_next_rounded,
              color: Colors.white54,
              onTap: _skipPhase,
              size: isMobile ? 36 : 40,
              tooltip: p.t('pomodoro.skip'),
            ),
          ],
        ),
      ],
    );
  }

  /// ポモドーロ設定の数値を直接入力するためのダイアログを開く。
  /// 数値表示部 (intRow) のタップから呼ばれる。
  /// min〜max の範囲外なら自動的にクランプして適用する。
  Future<void> _editPomodoroIntValue(
    MindMapProvider p,
    String label,
    int currentValue,
    int min,
    int max,
    ValueChanged<int> onChanged,
  ) async {
    final ctrl = TextEditingController(text: '$currentValue');
    // 開いた瞬間に既存の値を選択状態にしておく → 即上書き入力可能
    ctrl.selection =
        TextSelection(baseOffset: 0, extentOffset: ctrl.text.length);
    final result = await showDialog<int>(
      context: context,
      useRootNavigator: true,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(label,
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            TextField(
              controller: ctrl,
              autofocus: true,
              keyboardType: TextInputType.number,
              inputFormatters: [FilteringTextInputFormatter.digitsOnly],
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 18,
                  fontWeight: FontWeight.w700),
              textAlign: TextAlign.center,
              decoration: InputDecoration(
                isDense: true,
                contentPadding:
                    const EdgeInsets.symmetric(horizontal: 12, vertical: 12),
                enabledBorder: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(8),
                  borderSide: const BorderSide(color: Colors.white24),
                ),
                focusedBorder: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(8),
                  borderSide:
                      const BorderSide(color: Color(0xFFFF6B6B), width: 2),
                ),
              ),
              onSubmitted: (v) {
                final n = int.tryParse(v.trim());
                if (n != null) Navigator.pop(dctx, n.clamp(min, max));
              },
            ),
            const SizedBox(height: 6),
            Text('$min - $max',
                style: const TextStyle(color: Colors.white54, fontSize: 11)),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(p.t('btn.cancel')),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFFF6B6B),
                foregroundColor: Colors.white,),
            onPressed: () {
              final n = int.tryParse(ctrl.text.trim());
              if (n != null) Navigator.pop(dctx, n.clamp(min, max));
            },
            child: Text(p.t('btn.ok')),
          ),
        ],
      ),
    );
    ctrl.dispose();
    if (result != null) {
      setState(() => onChanged(result));
    }
  }

  Widget _buildSettingsBody(MindMapProvider p, bool isMobile) {
    Widget intRow({
      required String label,
      required int value,
      required int min,
      required int max,
      required ValueChanged<int> onChanged,
    }) {
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 4),
        child: Row(children: [
          Expanded(
            child: Text(label,
                style: TextStyle(
                    color: Colors.white, fontSize: isMobile ? 11 : 12)),
          ),
          IconButton(
            icon: const Icon(Icons.remove_circle_outline,
                color: Colors.white54, size: 18),
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
            onPressed:
                value > min ? () => setState(() => onChanged(value - 1)) : null,
          ),
          // ── 数値表示 (タップで直接入力可能に) ──
          // ユーザー要望: +/- ボタンだけだと大きい値にする際クリック数が多い。
          // 数値部をタップすると入力ダイアログが開き、min〜max の範囲で
          // 任意の数値を直接入力できるようにする。
          Tooltip(
            message: p.t('pomodoro.tip.tapToEdit'),
            child: InkWell(
              onTap: () =>
                  _editPomodoroIntValue(p, label, value, min, max, onChanged),
              borderRadius: BorderRadius.circular(4),
              child: Container(
                width: 38,
                padding: const EdgeInsets.symmetric(vertical: 2),
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.06),
                  borderRadius: BorderRadius.circular(4),
                  border:
                      Border.all(color: Colors.white.withValues(alpha: 0.12)),
                ),
                child: Text('$value',
                    textAlign: TextAlign.center,
                    style: TextStyle(
                        color: Colors.white,
                        fontSize: isMobile ? 13 : 15,
                        fontWeight: FontWeight.w700)),
              ),
            ),
          ),
          IconButton(
            icon: const Icon(Icons.add_circle_outline,
                color: Colors.white54, size: 18),
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
            onPressed:
                value < max ? () => setState(() => onChanged(value + 1)) : null,
          ),
        ]),
      );
    }

    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        intRow(
          label: '${p.t('pomodoro.work')} (${p.t('pomodoro.minutes')})',
          value: _workMin,
          min: 1,
          max: 90,
          onChanged: (v) => _workMin = v,
        ),
        intRow(
          label: '${p.t('pomodoro.shortBreak')} (${p.t('pomodoro.minutes')})',
          value: _shortBreakMin,
          min: 1,
          max: 30,
          onChanged: (v) => _shortBreakMin = v,
        ),
        intRow(
          label: '${p.t('pomodoro.longBreak')} (${p.t('pomodoro.minutes')})',
          value: _longBreakMin,
          min: 5,
          max: 60,
          onChanged: (v) => _longBreakMin = v,
        ),
        intRow(
          label: p.t('pomodoro.cyclesUntilLong'),
          value: _cyclesUntilLong,
          min: 2,
          max: 8,
          onChanged: (v) => _cyclesUntilLong = v,
        ),
        const Divider(color: Colors.white12, height: 18),
        Row(children: [
          Expanded(
            child: Text(p.t('pomodoro.alarm'),
                style: TextStyle(
                    color: Colors.white, fontSize: isMobile ? 11 : 12)),
          ),
          Switch(
            value: _alarmEnabled,
            onChanged: (v) => setState(() => _alarmEnabled = v),
            activeThumbColor: const Color(0xFFFF6B6B),
          ),
        ]),
        // ── カスタムアラーム音 (mp3/mp4/wav 等) ──
        // アラーム ON の時だけ操作可能。タップでファイル選択 + 試聴。
        if (_alarmEnabled)
          InkWell(
            onTap: () => _AlarmSoundPickerDialog.show(
              context,
              p,
              prefKey: _AudioAlarm.prefKeyPomodoro,
              title: context.read<MindMapProvider>().t('pomo.sound'),
            ),
            borderRadius: BorderRadius.circular(6),
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 6),
              child: Row(children: [
                const Icon(Icons.music_note_rounded,
                    color: Color(0xFFBA68C8), size: 16),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(p.t('alarm.customSound'),
                      style: TextStyle(
                          color: Colors.white, fontSize: isMobile ? 11 : 12)),
                ),
                const Icon(Icons.chevron_right_rounded,
                    color: Colors.white38, size: 16),
              ]),
            ),
          ),
        Row(children: [
          Expanded(
            child: Text(p.t('pomodoro.autoNext'),
                style: TextStyle(
                    color: Colors.white, fontSize: isMobile ? 11 : 12)),
          ),
          Switch(
            value: _autoNext,
            onChanged: (v) => setState(() => _autoNext = v),
            activeThumbColor: const Color(0xFFFF6B6B),
          ),
        ]),
        if (_canLockDuringWork)
          Row(children: [
            const Icon(Icons.lock_clock_rounded,
                color: Color(0xFFFF6B6B), size: 16),
            const SizedBox(width: 8),
            Expanded(
              child: Text(context.read<MindMapProvider>().t('pomo.lockDuringWork'),
                  style: TextStyle(
                      color: Colors.white, fontSize: isMobile ? 11 : 12)),
            ),
            Switch(
              value: _lockDuringWork,
              onChanged: (v) {
                setState(() => _lockDuringWork = v);
                // ignore: discarded_futures
                _saveSettings();
              },
              activeThumbColor: const Color(0xFFFF6B6B),
            ),
          ]),
        const SizedBox(height: 10),
        ElevatedButton.icon(
          onPressed: () {
            _saveSettings();
            // 停止中なら新しい長さを反映
            if (!_running) _setPhaseDuration();
            setState(() => _settingsMode = false);
          },
          icon: const Icon(Icons.check_rounded, size: 16),
          label: Text(p.t('btn.ok')),
          style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFFFF6B6B),
              foregroundColor: Colors.white,
              padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 14)),
        ),
      ],
    );
  }
}

/// 円形のポモドーロ操作ボタン
class _PomodoroBtn extends StatelessWidget {
  final IconData icon;
  final Color color;
  final VoidCallback onTap;
  final double size;
  final bool filled;
  final String? tooltip;
  const _PomodoroBtn({
    required this.icon,
    required this.color,
    required this.onTap,
    required this.size,
    this.filled = false,
    this.tooltip,
  });
  @override
  Widget build(BuildContext context) {
    final btn = MouseRegion(
      cursor: SystemMouseCursors.click,
      child: GestureDetector(
        onTap: onTap,
        child: Container(
          width: size,
          height: size,
          decoration: BoxDecoration(
            shape: BoxShape.circle,
            color: filled ? color : Colors.transparent,
            border: filled ? null : Border.all(color: color, width: 2),
          ),
          child: Icon(icon,
              color: filled ? Colors.white : color, size: size * 0.55),
        ),
      ),
    );
    return tooltip != null ? Tooltip(message: tooltip!, child: btn) : btn;
  }
}

// ─── 天気予報（フローティング）────────────────────────────────────────────────
// open-meteo.com の無料 API を使用 (APIキー不要)。
//   - ジオコーディング: https://geocoding-api.open-meteo.com/v1/search
//   - 天気予報:        https://api.open-meteo.com/v1/forecast
// 都市名でジオコーディング → lat/lon を SharedPreferences に保存 → 次回以降は
// 直接予報取得。1 時間キャッシュで API 連打を回避。
class _FloatingWeather extends StatefulWidget {
  final MindMapProvider provider;
  final Offset initialOffset;
  final VoidCallback onClose;
  final bool hidden;
  const _FloatingWeather({
    required this.provider,
    required this.initialOffset,
    required this.onClose,
    this.hidden = false,
  });
  @override
  State<_FloatingWeather> createState() => _FloatingWeatherState();
}

class _FloatingWeatherState extends State<_FloatingWeather> {
  late Offset _offset;

  // 永続化キー
  static const _kCity = 'weather_cityName';
  static const _kLat = 'weather_lat';
  static const _kLon = 'weather_lon';
  // hourly に weather_code が増えたため、旧キャッシュを使わせないようキー名 v2 へ
  static const _kCacheJson = 'weather_cache_json_v2';
  static const _kCacheAt = 'weather_cache_at_ms_v2';

  /// パネルサイズの倍率 (1.0 = デフォルト)。ユーザーが拡大ボタンで切替。
  static const _kScale = 'weather_panel_scale';

  /// キャッシュ TTL: 1 時間
  static const int _cacheTtlMs = 60 * 60 * 1000;

  /// 入力中の都市名
  final TextEditingController _cityCtrl = TextEditingController();

  /// 表示中の都市名
  String? _cityName;
  double? _lat;
  double? _lon;

  /// 予報データ (open-meteo の forecast レスポンスをそのまま保持)
  Map<String, dynamic>? _forecast;
  bool _loading = false;
  String? _error;

  /// ジオコーディング検索の候補 (複数ヒット時に選択 UI を表示)
  List<Map<String, dynamic>> _searchCandidates = [];

  /// 日付行を展開して時間別予報を表示している日のインデックス。null = 折り畳み。
  /// タップ済みの日を再タップすると null に戻り閉じる(アコーディオン動作)。
  int? _expandedDayIndex;

  /// パネルサイズの倍率。ユーザーがヘッダーの拡大/縮小ボタンで切替。
  /// 1.0 = デフォルト、1.6 = 拡大。さらに増やしたい場合はトグル順を変更。
  double _userScale = 1.0;

  /// 折り畳み状態 (true ならヘッダーだけ表示)。
  bool _panelCollapsed = false;
  static const List<double> _scalePresets = [1.0, 1.4, 1.8];

  /// 時間別ストリップ用の横スクロールコントローラ。Scrollbar 表示と
  /// プログラム的スクロール (左右ボタン) の両方で利用するため state に保持。
  /// 展開中の日が切り替わったら念のため位置を 0 にリセットする。
  final ScrollController _hourlyScrollCtrl = ScrollController();

  /// 指定した日 (dayIndex) に対応する時間別予報データを抽出する。
  /// 戻り値は [{ 'time': 'YYYY-MM-DDTHH:00', 'temp': num?, 'pop': num?, 'code': int? }, ...]
  /// open-meteo は forecast_days=5 で 120 時間分まとめて返してくるため、
  /// daily.time[dayIndex] (YYYY-MM-DD) を prefix に持つエントリだけ取り出す。
  List<Map<String, dynamic>> _hourlyForDay(int dayIndex) {
    final hourly = _forecast?['hourly'] as Map<String, dynamic>?;
    final daily = _forecast?['daily'] as Map<String, dynamic>?;
    if (hourly == null || daily == null) return const [];
    final times =
        (hourly['time'] as List<dynamic>?)?.cast<String>() ?? const [];
    final temps =
        (hourly['temperature_2m'] as List<dynamic>?)?.cast<num>() ?? const [];
    final pops =
        (hourly['precipitation_probability'] as List<dynamic>?)?.cast<num>() ??
            const [];
    final codes =
        (hourly['weather_code'] as List<dynamic>?)?.cast<num>() ?? const [];
    final dates = (daily['time'] as List<dynamic>?)?.cast<String>() ?? const [];
    if (dayIndex < 0 || dayIndex >= dates.length) return const [];
    final dayPrefix = dates[dayIndex]; // 'YYYY-MM-DD'
    final result = <Map<String, dynamic>>[];
    for (int i = 0; i < times.length; i++) {
      if (!times[i].startsWith(dayPrefix)) continue;
      result.add({
        'time': times[i],
        'temp': i < temps.length ? temps[i] : null,
        'pop': i < pops.length ? pops[i] : null,
        'code': i < codes.length ? codes[i].toInt() : null,
      });
    }
    return result;
  }

