  /// 現在の言語に対応する代表都市リスト
  List<List<String>> get _popularCities =>
      _popularCitiesByLang[widget.provider.appLanguage] ??
      _popularCitiesByLang['en']!;

  bool get _isMobileScreen => MediaQuery.of(context).size.width < 600;

  /// 都市が未設定（初回または設定モード）
  bool get _needsCity => _lat == null || _lon == null;

  @override
  void initState() {
    super.initState();
    _offset = widget.initialOffset;
    HardwareKeyboard.instance.addHandler(_handleKey);
    _loadAndFetch();
  }

  @override
  void dispose() {
    HardwareKeyboard.instance.removeHandler(_handleKey);
    _cityCtrl.dispose();
    _hourlyScrollCtrl.dispose();
    super.dispose();
  }

  bool _handleKey(KeyEvent event) {
    if (event is! KeyDownEvent) return false;
    final focused = FocusManager.instance.primaryFocus;
    if (focused != null && focused.context?.widget is EditableText) {
      // テキスト入力中は Esc を入力に渡さない（フォーカスを外すだけ）
      if (event.logicalKey == LogicalKeyboardKey.escape) {
        FocusScope.of(context).unfocus();
        return true;
      }
      return false;
    }
    if (event.logicalKey == LogicalKeyboardKey.escape) {
      // 旧: Esc で閉じる → 予報状態を毎回読み込み直すことになり煩わしい。
      // 新: Esc は畳む/展開のトグル。再 Esc で本体が戻ってくる。
      setState(() => _panelCollapsed = !_panelCollapsed);
      return true;
    }
    return false;
  }

  Future<void> _loadAndFetch() async {
    final prefs = await SharedPreferences.getInstance();
    // 保存されたパネル倍率を読み込み (range をクランプ)
    final scale = prefs.getDouble(_kScale) ?? 1.0;
    _userScale = scale.clamp(_scalePresets.first, _scalePresets.last);
    final city = prefs.getString(_kCity);
    final lat = prefs.getDouble(_kLat);
    final lon = prefs.getDouble(_kLon);
    if (city != null && lat != null && lon != null) {
      setState(() {
        _cityName = city;
        _lat = lat;
        _lon = lon;
        _cityCtrl.text = city;
      });
      // キャッシュチェック
      final cachedJson = prefs.getString(_kCacheJson);
      final cachedAt = prefs.getInt(_kCacheAt) ?? 0;
      final age = DateTime.now().millisecondsSinceEpoch - cachedAt;
      if (cachedJson != null && age < _cacheTtlMs) {
        try {
          setState(() {
            _forecast = jsonDecode(cachedJson) as Map<String, dynamic>;
          });
          return;
        } catch (_) {}
      }
      await _fetchForecast();
    } else {
      // 都市未設定時もスケール反映のため再描画
      if (mounted) setState(() {});
    }
  }

  /// パネル倍率の `−` / `+` ボタンを生成するヘルパー。
  /// `enabled=false` の時は灰色で無反応にする(上限/下限到達時)。
  Widget _buildScaleButton({
    required IconData icon,
    required bool enabled,
    required String tooltip,
    required VoidCallback onTap,
    required bool isMobile,
  }) {
    return Tooltip(
      message: tooltip,
      child: MouseRegion(
        cursor: enabled ? SystemMouseCursors.click : SystemMouseCursors.basic,
        child: GestureDetector(
          onTap: enabled ? onTap : null,
          child: Padding(
            padding: EdgeInsets.all(isMobile ? 3 : 4),
            child: Icon(icon,
                color: enabled ? Colors.white70 : Colors.white24,
                size: isMobile ? 14 : 16),
          ),
        ),
      ),
    );
  }

  /// パネル倍率を 1 段階上げる (1.0 → 1.4 → 1.8)。上限なら何もしない。
  Future<void> _increasePanelScale() async {
    final idx = _scalePresets.indexOf(_userScale);
    if (idx < 0 || idx >= _scalePresets.length - 1) return;
    setState(() => _userScale = _scalePresets[idx + 1]);
    final prefs = await SharedPreferences.getInstance();
    await prefs.setDouble(_kScale, _userScale);
  }

  /// パネル倍率を 1 段階下げる (1.8 → 1.4 → 1.0)。下限なら何もしない。
  Future<void> _decreasePanelScale() async {
    final idx = _scalePresets.indexOf(_userScale);
    if (idx <= 0) return;
    setState(() => _userScale = _scalePresets[idx - 1]);
    final prefs = await SharedPreferences.getInstance();
    await prefs.setDouble(_kScale, _userScale);
  }

  Future<void> _searchCity() async {
    final raw = _cityCtrl.text.trim();
    if (raw.isEmpty) return;
    setState(() {
      _loading = true;
      _error = null;
      _searchCandidates = [];
    });
    // ── 検索クエリのバリエーション生成 ──
    // ユーザーは「横浜市,日本」「Tokyo, Japan」のようにカンマ区切りで国を
    // 含めたり、「市」「都」「府」suffix を付けたりするが、open-meteo の
    // ジオコーディングは正確な city 名でないとヒットしないことが多い。
    // → 元のクエリ → カンマで前半だけ → suffix 削除 の順で試行する。
    final queries = <String>{raw};
    // カンマ/読点があれば前半だけ
    for (final sep in [',', ',', '、']) {
      if (raw.contains(sep)) {
        final left = raw.split(sep).first.trim();
        if (left.isNotEmpty) queries.add(left);
      }
    }
    // 都市行政 suffix を取り除いたバリエーション (どの言語も)
    const suffixes = [
      '市', '区', '町', '村', '郡', '都', '府', '県', '州',
      '시', '구', '도', // ko
      '市', '区', '县', // zh
      ' City', ' city', ' Si', ' Shi',
    ];
    for (final q in List.of(queries)) {
      for (final s in suffixes) {
        if (q.endsWith(s) && q.length > s.length) {
          queries.add(q.substring(0, q.length - s.length).trim());
        }
      }
    }
    final lang = widget.provider.appLanguage;
    try {
      List<dynamic>? results;
      String? successQuery;
      // 各バリエーションを順に試行(最初にヒットしたものを使用)
      for (final q in queries) {
        if (q.trim().isEmpty) continue;
        final url =
            'https://geocoding-api.open-meteo.com/v1/search?name=${Uri.encodeQueryComponent(q)}&count=10&language=$lang&format=json';
        final res = await http.get(Uri.parse(url));
        if (res.statusCode != 200) continue;
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        final r = data['results'] as List<dynamic>?;
        if (r != null && r.isNotEmpty) {
          results = r;
          successQuery = q;
          break;
        }
      }
      if (results == null || results.isEmpty) {
        setState(() {
          _loading = false;
          _error = widget.provider.t('weather.cityNotFound');
        });
        return;
      }
      debugPrint('Geocoding hit on query: "$successQuery" '
          '(${results.length} results, original was "$raw")');
      // 1 件だけなら自動選択、複数なら候補リストを表示してユーザーに選ばせる
      if (results.length == 1) {
        await _selectCandidate((results.first as Map).cast<String, dynamic>());
      } else {
        setState(() {
          _loading = false;
          _searchCandidates =
              results!.map((e) => (e as Map).cast<String, dynamic>()).toList();
        });
      }
    } catch (e) {
      setState(() {
        _loading = false;
        _error = '${widget.provider.t('weather.fetchFail')}: $e';
      });
    }
  }

  /// 検索候補 1 件を選択し、永続化 → 予報取得まで実行。
  Future<void> _selectCandidate(Map<String, dynamic> result) async {
    final lat = (result['latitude'] as num).toDouble();
    final lon = (result['longitude'] as num).toDouble();

    // ── 表示名の取得方針 ──
    // open-meteo の geocoding API は language=ja 指定でカタカナ転写名
    // (例: "横浜" → "ヨコハマシ") を返すことが多く、見栄えが悪い。
    // → まず Nominatim (OSM) の reverse geocoding でローカル文字の自然な
    //    名前を取得し、それが取れなかった時だけ open-meteo の name に
    //    フォールバックする。Nominatim は city/town/village/admin/country
    //    を構造化して返すため、自然な「市, 県, 国」の表示が組める。
    String? displayName = await _reverseGeocodeName(lat, lon);
    if (displayName == null || displayName.trim().isEmpty) {
      final name = result['name'] as String? ?? '';
      final country = result['country'] as String? ?? '';
      final admin1 = result['admin1'] as String? ?? '';
      final parts = <String>[name];
      if (admin1.isNotEmpty && admin1 != name) parts.add(admin1);
      if (country.isNotEmpty) parts.add(country);
      displayName = parts.join(', ');
    }

    await _applyPickedLocation(displayName, lat, lon);
  }

  /// Nominatim (OSM) を使った reverse geocoding で、ローカル言語での
  /// 自然な「都市名, 行政区, 国」の文字列を組む。
  /// open-meteo のカタカナ転写を回避するために使用。
  /// 失敗時は null を返し、呼び出し側がフォールバックする。
  Future<String?> _reverseGeocodeName(double lat, double lon) async {
    try {
      final lang = widget.provider.appLanguage;
      final url = 'https://nominatim.openstreetmap.org/reverse'
          '?lat=$lat&lon=$lon&format=json&zoom=10&accept-language=$lang';
      final res = await http.get(Uri.parse(url), headers: {
        'User-Agent': 'MindMapApp/1.0 (weather widget)',
      });
      if (res.statusCode != 200) return null;
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      final addr = data['address'] as Map<String, dynamic>?;
      if (addr == null) return null;
      // 優先順位: city > town > village > municipality > county
      String? bestName;
      for (final key in [
        'city',
        'town',
        'village',
        'municipality',
        'county',
      ]) {
        final v = addr[key];
        if (v is String && v.isNotEmpty) {
          bestName = v;
          break;
        }
      }
      if (bestName == null) return null;
      final state = addr['state'] as String? ?? '';
      final country = addr['country'] as String? ?? '';
      final parts = <String>[bestName];
      if (state.isNotEmpty && state != bestName) parts.add(state);
      if (country.isNotEmpty) parts.add(country);
      return parts.join(', ');
    } catch (_) {
      return null;
    }
  }

  /// 任意の (displayName, lat, lon) を保存して予報を取得する共通処理。
  /// _selectCandidate と _onMapPick (地図選択) から共通利用される。
  Future<void> _applyPickedLocation(
      String displayName, double lat, double lon) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(_kCity, displayName);
    await prefs.setDouble(_kLat, lat);
    await prefs.setDouble(_kLon, lon);
    // 古いキャッシュを破棄
    await prefs.remove(_kCacheJson);
    await prefs.remove(_kCacheAt);

    if (!mounted) return;
    setState(() {
      _cityName = displayName;
      _lat = lat;
      _lon = lon;
      _forecast = null;
      _searchCandidates = [];
      _error = null;
    });
    await _fetchForecast();
  }

  /// 地図から場所を選択するダイアログを開く。
  /// OpenStreetMap + Leaflet を InAppWebView で表示し、ユーザーがクリック
  /// した位置の lat/lon を JavaScript handler 経由で受け取る。
  /// 受け取った後 Nominatim (OSM の reverse geocoding) で最も近い
  /// 都市名/地名を取得する。
  Future<void> _showMapPicker(BuildContext ctx) async {
    // 初期表示位置: 既に位置設定済みならそこを中心に、未設定なら東京
    final initialLat = _lat ?? 35.6812;
    final initialLon = _lon ?? 139.7671;
    // ── ダイアログのナビゲーター ──
    // 天気ウィジェットは Overlay.of(rootOverlay: true) に挿入されているため、
    // useRootNavigator: true (デフォルト) では Navigator が見つからずダイアログが
    // 表示されないことがある。useRootNavigator: false で最も近い Navigator
    // (= MaterialApp の Navigator) を使うことで確実に開く。
    try {
      await showDialog(
        context: ctx,
        useRootNavigator: false,
        barrierDismissible: true,
        builder: (dctx) => Dialog(
          backgroundColor: const Color(0xFF1E1E32),
          insetPadding: const EdgeInsets.all(16),
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
          child: SizedBox(
            width: 600,
            height: 520,
            child: _MapPickerDialog(
              initialLat: initialLat,
              initialLon: initialLon,
              provider: widget.provider,
              onPick: (lat, lon) async {
                Navigator.of(dctx).pop();
                await _onMapPick(lat, lon);
              },
            ),
          ),
        ),
      );
    } catch (e) {
      // 万一ダイアログが開けなかった場合のフォールバック (空エラー回避)
      debugPrint('Map picker dialog failed: $e');
      if (!mounted) return;
      setState(() {
        _error = '${widget.provider.t('weather.fetchFail')}: $e';
      });
    }
  }

  /// 地図から選択された lat/lon に対して reverse geocoding し、
  /// 最も近い都市名で _applyPickedLocation を呼び出す。
  Future<void> _onMapPick(double lat, double lon) async {
    if (!mounted) return;
    setState(() {
      _loading = true;
      _searchCandidates = [];
      _error = null;
    });
    String displayName;
    try {
      // Nominatim (OpenStreetMap) の reverse geocoding。
      // User-Agent ヘッダーは Nominatim 利用規約で必須。
      final lang = widget.provider.appLanguage;
      final url = 'https://nominatim.openstreetmap.org/reverse'
          '?lat=$lat&lon=$lon&format=json&zoom=10&accept-language=$lang';
      final res = await http.get(Uri.parse(url), headers: {
        'User-Agent': 'MindMapApp/1.0 (weather widget)',
      });
      if (res.statusCode == 200) {
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        final addr = data['address'] as Map<String, dynamic>?;
        // 優先順位: city > town > village > county > state
        String? bestName;
        if (addr != null) {
          for (final key in [
            'city',
            'town',
            'village',
            'municipality',
            'county',
            'state',
          ]) {
            final v = addr[key];
            if (v is String && v.isNotEmpty) {
              bestName = v;
              break;
            }
          }
        }
        final country = addr?['country'] as String? ?? '';
        if (bestName != null) {
          displayName = country.isNotEmpty ? '$bestName, $country' : bestName;
        } else {
          // フォールバック: data.display_name の先頭部分
          final disp = data['display_name'] as String?;
          if (disp != null && disp.isNotEmpty) {
            displayName = disp.split(',').take(2).join(',').trim();
          } else {
            displayName =
                '${lat.toStringAsFixed(3)}, ${lon.toStringAsFixed(3)}';
          }
        }
      } else {
        displayName = '${lat.toStringAsFixed(3)}, ${lon.toStringAsFixed(3)}';
      }
    } catch (e) {
      // reverse geocoding が失敗しても天気予報自体は (lat,lon) で取得可能。
      // 表示名だけ座標フォールバックする。
      debugPrint('Nominatim reverse geocode failed: $e');
      displayName = '${lat.toStringAsFixed(3)}, ${lon.toStringAsFixed(3)}';
    }
    await _applyPickedLocation(displayName, lat, lon);
  }

  Future<void> _fetchForecast() async {
    if (_lat == null || _lon == null) return;
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final url = 'https://api.open-meteo.com/v1/forecast'
          '?latitude=$_lat&longitude=$_lon'
          '&current_weather=true'
          '&hourly=temperature_2m,precipitation_probability,weather_code'
          '&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max'
          '&timezone=auto'
          '&forecast_days=5';
      final res = await http.get(Uri.parse(url));
      if (res.statusCode != 200) {
        throw Exception('HTTP ${res.statusCode}');
      }
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      // キャッシュ書き込み
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_kCacheJson, res.body);
      await prefs.setInt(_kCacheAt, DateTime.now().millisecondsSinceEpoch);
      setState(() {
        _forecast = data;
        _loading = false;
      });
    } catch (e) {
      setState(() {
        _loading = false;
        _error = '${widget.provider.t('weather.fetchFail')}: $e';
      });
    }
  }

  /// open-meteo WMO weather code → アイコン + 簡潔な日本語ラベル
  /// 参考: https://open-meteo.com/en/docs (WMO Weather interpretation codes)
  static IconData _iconForCode(int code) {
    if (code == 0) return Icons.wb_sunny_rounded;
    if (code == 1 || code == 2) return Icons.wb_cloudy_rounded;
    if (code == 3) return Icons.cloud_rounded;
    if (code == 45 || code == 48) return Icons.foggy;
    if (code >= 51 && code <= 57) return Icons.grain_rounded;
    if (code >= 61 && code <= 67) return Icons.water_drop_rounded;
    if (code >= 71 && code <= 77) return Icons.ac_unit_rounded;
    if (code >= 80 && code <= 82) return Icons.water_drop_rounded;
    if (code >= 85 && code <= 86) return Icons.ac_unit_rounded;
    if (code >= 95 && code <= 99) return Icons.flash_on_rounded;
    return Icons.help_outline_rounded;
  }

  String _labelForCode(int code, MindMapProvider p) {
    if (code == 0) return p.t('weather.clear');
    if (code == 1) return p.t('weather.mainlyClear');
    if (code == 2) return p.t('weather.partlyCloudy');
    if (code == 3) return p.t('weather.overcast');
    if (code == 45 || code == 48) return p.t('weather.fog');
    if (code >= 51 && code <= 57) return p.t('weather.drizzle');
    if (code >= 61 && code <= 67) return p.t('weather.rain');
    if (code >= 71 && code <= 77) return p.t('weather.snow');
    if (code >= 80 && code <= 82) return p.t('weather.showers');
    if (code >= 85 && code <= 86) return p.t('weather.snowShowers');
    if (code >= 95 && code <= 99) return p.t('weather.thunderstorm');
    return '?';
  }

  Color _colorForCode(int code) {
    if (code == 0) return const Color(0xFFFFB347);
    if (code == 1 || code == 2) return const Color(0xFF90CAF9);
    if (code == 3) return const Color(0xFF78909C);
    if (code >= 51 && code <= 67) return const Color(0xFF4FC3F7);
    if (code >= 71 && code <= 77 || code >= 85 && code <= 86) {
      return const Color(0xFFB3E5FC);
    }
    if (code >= 95) return const Color(0xFFBA68C8);
    return Colors.white54;
  }

  @override
  Widget build(BuildContext context) {
    final mq = MediaQuery.of(context);
    final screen = mq.size;
    final bool isMobile = _isMobileScreen;
    // ── ベースサイズ × ユーザー指定倍率 ─────
    // デフォルト倍率 1.0 では従来通りのサイズ。1.4 / 1.8 倍に拡大可能。
    final double baseW = isMobile ? 260.0 : 320.0;
    final double panelW = (baseW * _userScale).clamp(baseW, screen.width - 16);
    // 折り畳み時はヘッダーのみ。共通の小さな幅に揃える。
    // (天気パネルにはユーザーが設定するパネル拡大倍率 _userScale があるが、
    //  畳んでいる時は意味が無いので無視して固定幅にする。展開すると元に戻る)
    final double effectiveW =
        _panelCollapsed ? _collapsedFloatingWidth(isMobile) : panelW;
    // パネル高: 都市入力モードは内容に応じて拡張する。
    //   - 検索候補表示中: 候補リスト最大 200px + 検索 UI 余白
    //   - 通常 (人気都市チップ表示): 9 言語のチップが 2-3 行入る高さ
    //   - 予報表示中: 5 日先予報が入る高さ
    final double basePanelH = _needsCity
        ? (_searchCandidates.isNotEmpty
            ? (isMobile ? 420.0 : 440.0)
            : (isMobile ? 320.0 : 340.0))
        : (isMobile ? 350.0 : 400.0);
    final double panelH =
        (basePanelH * _userScale).clamp(basePanelH, screen.height - 32);
    // ヘッダーだけ画面内に残れば下端まで動かせる仕様で統一
    const double headerVisible = 36.0;
    final double safeTop = mq.padding.top;
    final double safeBottom = mq.padding.bottom;
    final double maxLeft = (screen.width - effectiveW).clamp(0.0, screen.width);
    final double maxTop = (screen.height - safeBottom - headerVisible)
        .clamp(safeTop, screen.height);
    final clampedLeft = _offset.dx.clamp(0.0, maxLeft);
    final clampedTop = _offset.dy.clamp(safeTop, maxTop);
    final p = widget.provider;

    return Positioned(
      left: clampedLeft,
      top: clampedTop,
      // Offstage で裏に隠す (予報キャッシュ・入力中の都市名は維持される)。
      child: Offstage(
        offstage: widget.hidden,
        child: ExcludeFocus(
          excluding: false, // テキスト入力するのでフォーカスは許可
          child: Material(
            elevation: 12,
            borderRadius: BorderRadius.circular(14),
            color: Colors.transparent,
            child: Container(
              width: effectiveW,
              decoration: BoxDecoration(
                color: const Color(0xFF1E1E32),
                borderRadius: BorderRadius.circular(14),
                border: Border.all(
                    color: const Color(0xFF4FC3F7).withValues(alpha: 0.5),
                    width: 1.5),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withValues(alpha: 0.5),
                    blurRadius: 16,
                    offset: const Offset(0, 6),
                  ),
                ],
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  // ── ヘッダー ─────
                  GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onPanUpdate: (d) {
                      setState(() {
                        _offset = Offset(
                          (_offset.dx + d.delta.dx).clamp(0.0, maxLeft),
                          (_offset.dy + d.delta.dy).clamp(safeTop, maxTop),
                        );
                      });
                    },
                    child: MouseRegion(
                      cursor: SystemMouseCursors.move,
                      child: Container(
                        padding: EdgeInsets.symmetric(
                            horizontal: isMobile ? 8 : 10,
                            vertical: isMobile ? 5 : 8),
                        decoration: BoxDecoration(
                          color:
                              const Color(0xFF4FC3F7).withValues(alpha: 0.22),
                          borderRadius: const BorderRadius.only(
                            topLeft: Radius.circular(13),
                            topRight: Radius.circular(13),
                          ),
                        ),
                        child: Row(children: [
                          Icon(Icons.drag_indicator_rounded,
                              color: Colors.white54, size: isMobile ? 14 : 16),
                          const SizedBox(width: 4),
                          Icon(Icons.cloud_rounded,
                              color: const Color(0xFF4FC3F7),
                              size: isMobile ? 15 : 18),
                          const SizedBox(width: 6),
                          Expanded(
                            child: Text(_cityName ?? p.t('hdr.weather'),
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: TextStyle(
                                    color: Colors.white,
                                    fontSize: isMobile ? 11 : 13,
                                    fontWeight: FontWeight.w700)),
                          ),
                          if (!_panelCollapsed && _lat != null)
                            // ── 更新 ──
                            Tooltip(
                              message: p.t('weather.tip.refresh'),
                              child: MouseRegion(
                                cursor: SystemMouseCursors.click,
                                child: GestureDetector(
                                  onTap: _loading ? null : _fetchForecast,
                                  child: Padding(
                                    padding: EdgeInsets.all(isMobile ? 3 : 4),
                                    child: Icon(Icons.refresh_rounded,
                                        color: _loading
                                            ? Colors.white24
                                            : Colors.white54,
                                        size: isMobile ? 14 : 16),
                                  ),
                                ),
                              ),
                            ),
                          if (!_panelCollapsed && _lat != null)
                            // ── 都市変更モード(検索画面に戻る)──
                            Tooltip(
                              message: p.t('weather.tip.editLocation'),
                              child: MouseRegion(
                                cursor: SystemMouseCursors.click,
                                child: GestureDetector(
                                  onTap: () => setState(() {
                                    _lat = null;
                                    _lon = null;
                                  }),
                                  child: Padding(
                                    padding: EdgeInsets.all(isMobile ? 3 : 4),
                                    child: Icon(Icons.edit_location_alt_rounded,
                                        color: Colors.white54,
                                        size: isMobile ? 14 : 16),
                                  ),
                                ),
                              ),
                            ),
                          // 予報表示中でも地図から直接場所変更可能にする
                          if (!_panelCollapsed && _lat != null)
                            // ── 地図から場所を選択 ──
                            Tooltip(
                              message: p.t('weather.tip.openMap'),
                              child: MouseRegion(
                                cursor: SystemMouseCursors.click,
                                child: GestureDetector(
                                  onTap: () => _showMapPicker(context),
                                  child: Padding(
                                    padding: EdgeInsets.all(isMobile ? 3 : 4),
                                    child: Icon(Icons.map_outlined,
                                        color: Colors.white54,
                                        size: isMobile ? 14 : 16),
                                  ),
                                ),
                              ),
                            ),
                          // ── 拡大率コントロール (- 100% +) ──
                          // 折り畳み中はパネル幅を最小化するため、ズーム関連は
                          // 全部隠す。展開した瞬間に元通り戻ってくる。
                          if (!_panelCollapsed)
                            _buildScaleButton(
                              icon: Icons.remove_circle_outline_rounded,
                              enabled: _userScale > _scalePresets.first,
                              tooltip: p.t('weather.tip.zoomOut'),
                              onTap: _decreasePanelScale,
                              isMobile: isMobile,
                            ),
                          if (!_panelCollapsed)
                            Tooltip(
                              message: p.t('weather.tip.scaleLabel'),
                              child: Padding(
                                padding:
                                    const EdgeInsets.symmetric(horizontal: 2),
                                child: Text(
                                  '${(_userScale * 100).round()}%',
                                  style: TextStyle(
                                      color: _userScale > 1.0
                                          ? const Color(0xFF4FC3F7)
                                          : Colors.white54,
                                      fontSize: isMobile ? 9 : 10,
                                      fontWeight: FontWeight.w600,
                                      fontFeatures: const [
                                        FontFeature.tabularFigures()
                                      ]),
                                ),
                              ),
                            ),
                          if (!_panelCollapsed)
                            _buildScaleButton(
                              icon: Icons.add_circle_outline_rounded,
                              enabled: _userScale < _scalePresets.last,
                              tooltip: p.t('weather.tip.zoomIn'),
                              onTap: _increasePanelScale,
                              isMobile: isMobile,
                            ),
                          // 折り畳みボタン: 本体を隠してヘッダーだけ残す。
                          // 予報のキャッシュは維持されるので再展開時は即時表示。
                          Tooltip(
                            message: _panelCollapsed
                                ? p.t('weather.tip.expand')
                                : p.t('weather.tip.collapse'),
                            child: MouseRegion(
                              cursor: SystemMouseCursors.click,
                              child: GestureDetector(
                                onTap: () => setState(
                                    () => _panelCollapsed = !_panelCollapsed),
                                child: Padding(
                                  padding: EdgeInsets.all(isMobile ? 3 : 4),
                                  child: Icon(
                                      _panelCollapsed
                                          ? Icons.expand_more_rounded
                                          : Icons.expand_less_rounded,
                                      color: Colors.white70,
                                      size: isMobile ? 16 : 18),
                                ),
                              ),
                            ),
                          ),
                          // ── 閉じる ──
                          Tooltip(
                            message: p.t('weather.tip.close'),
                            child: MouseRegion(
                              cursor: SystemMouseCursors.click,
                              child: GestureDetector(
                                onTap: widget.onClose,
                                child: Padding(
                                  padding: EdgeInsets.all(isMobile ? 3 : 4),
                                  child: Icon(Icons.close,
                                      color: Colors.white54,
                                      size: isMobile ? 14 : 16),
                                ),
                              ),
                            ),
                          ),
                        ]),
                      ),
                    ),
                  ),
                  // ── 本体 ─────
                  // 折り畳み中は本体ごと非表示。再展開時は state が維持されているので
                  // 直前の都市の予報がそのまま見られる。
                  if (!_panelCollapsed)
                    Expanded(
                      child: MediaQuery(
                        data: MediaQuery.of(context).copyWith(
                          textScaler: TextScaler.linear(
                              // テキストはやや控えめに (パネル全体倍率より緩く)
                              1.0 + (_userScale - 1.0) * 0.6),
                        ),
                        child: Padding(
                          padding: EdgeInsets.all(isMobile ? 12 : 16),
                          child: _needsCity
                              ? _buildCityInputBody(p, isMobile)
                              : _buildForecastBody(p, isMobile),
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
        ),
      ), // Offstage
    );
  }

  Widget _buildCityInputBody(MindMapProvider p, bool isMobile) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Text(p.t('weather.enterCity'),
            style: const TextStyle(color: Colors.white70, fontSize: 12)),
        const SizedBox(height: 10),
        TextField(
          controller: _cityCtrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white, fontSize: 14),
          decoration: InputDecoration(
            hintText: p.t('weather.cityHint'),
            hintStyle: const TextStyle(color: Colors.white38),
            prefixIcon:
                const Icon(Icons.search, color: Colors.white38, size: 18),
            isDense: true,
            contentPadding:
                const EdgeInsets.symmetric(horizontal: 8, vertical: 10),
            enabledBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: const BorderSide(color: Colors.white24),
            ),
            focusedBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: const BorderSide(color: Color(0xFF4FC3F7)),
            ),
          ),
          onSubmitted: (_) => _searchCity(),
        ),
        if (_error != null) ...[
          const SizedBox(height: 8),
          Text(_error!,
              style: const TextStyle(color: Color(0xFFFF6B6B), fontSize: 11)),
        ],
        const SizedBox(height: 8),
        Row(children: [
          Expanded(
            child: ElevatedButton.icon(
              onPressed: _loading ? null : _searchCity,
              icon: _loading
                  ? const SizedBox(
                      width: 14,
                      height: 14,
                      child: CircularProgressIndicator(
                          strokeWidth: 2, color: Colors.white))
                  : const Icon(Icons.search, size: 16),
              label: Text(p.t('weather.searchCity')),
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF4FC3F7),
                  foregroundColor: Color(0xFF10241F),
                  padding:
                      const EdgeInsets.symmetric(vertical: 10, horizontal: 10)),
            ),
          ),
          const SizedBox(width: 8),
          // ── 地図から選択ボタン ──
          // OpenStreetMap (Leaflet) を WebView で表示し、ユーザーが
          // タップした座標から最も近い都市を Nominatim で逆ジオコーディング。
          ElevatedButton.icon(
            onPressed: _loading ? null : () => _showMapPicker(context),
            icon: const Icon(Icons.map_outlined, size: 16),
            label: Text(p.t('weather.pickFromMap')),
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF43B97F),
                foregroundColor: Colors.white,
                padding:
                    const EdgeInsets.symmetric(vertical: 10, horizontal: 10)),
          ),
        ]),

        // ── 検索結果の候補リスト（複数ヒット時に表示）─────────
        if (_searchCandidates.isNotEmpty) ...[
          const SizedBox(height: 12),
          Row(children: [
            const Icon(Icons.list_alt_rounded, color: Colors.white54, size: 14),
            const SizedBox(width: 4),
            Text(p.t('weather.candidates'),
                style: const TextStyle(
                    color: Colors.white54,
                    fontSize: 11,
                    fontWeight: FontWeight.w600)),
          ]),
          const SizedBox(height: 6),
          // スクロール可能な候補リスト（最大 200px 高）
          ConstrainedBox(
            constraints: const BoxConstraints(maxHeight: 200),
            child: ListView.builder(
              shrinkWrap: true,
              itemCount: _searchCandidates.length,
              itemBuilder: (_, i) {
                final c = _searchCandidates[i];
                final name = c['name'] as String? ?? '';
                final admin1 = c['admin1'] as String? ?? '';
                final country = c['country'] as String? ?? '';
                final subParts = <String>[];
                if (admin1.isNotEmpty && admin1 != name) subParts.add(admin1);
                if (country.isNotEmpty) subParts.add(country);
                final sub = subParts.join(', ');
                return InkWell(
                  onTap: () => _selectCandidate(c),
                  child: Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
                    decoration: BoxDecoration(
                      border: Border(
                        bottom: BorderSide(
                            color: Colors.white.withValues(alpha: 0.06)),
                      ),
                    ),
                    child: Row(children: [
                      const Icon(Icons.location_on_outlined,
                          color: Color(0xFF4FC3F7), size: 14),
                      const SizedBox(width: 6),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(name,
                                style: const TextStyle(
                                    color: Colors.white,
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600)),
                            if (sub.isNotEmpty)
                              Text(sub,
                                  style: const TextStyle(
                                      color: Colors.white54, fontSize: 10)),
                          ],
                        ),
                      ),
                      const Icon(Icons.arrow_forward_ios_rounded,
                          color: Colors.white24, size: 11),
                    ]),
                  ),
                );
              },
            ),
          ),
        ],

        // ── 人気の都市（言語別プリセット）チップ ─────────
        // ユーザーが何も入力していない or 候補が無い時にだけ表示する。
        if (_searchCandidates.isEmpty) ...[
          const SizedBox(height: 14),
          Row(children: [
            const Icon(Icons.star_outline_rounded,
                color: Colors.white54, size: 14),
            const SizedBox(width: 4),
            Text(p.t('weather.popularCities'),
                style: const TextStyle(
                    color: Colors.white54,
                    fontSize: 11,
                    fontWeight: FontWeight.w600)),
          ]),
          const SizedBox(height: 6),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: _popularCities.map((entry) {
              final localLabel = entry[0];
              final searchQuery = entry[1];
              return InkWell(
                borderRadius: BorderRadius.circular(14),
                onTap: _loading
                    ? null
                    : () {
                        _cityCtrl.text = searchQuery;
                        _searchCity();
                      },
                child: Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                  decoration: BoxDecoration(
                    color: const Color(0xFF4FC3F7).withValues(alpha: 0.15),
                    borderRadius: BorderRadius.circular(14),
                    border: Border.all(
                        color: const Color(0xFF4FC3F7).withValues(alpha: 0.4)),
                  ),
                  child: Text(localLabel,
                      style:
                          const TextStyle(color: Colors.white, fontSize: 11)),
                ),
              );
            }).toList(),
          ),
        ],
      ],
    );
  }

  Widget _buildForecastBody(MindMapProvider p, bool isMobile) {
    if (_loading && _forecast == null) {
      return const SizedBox(
        height: 100,
        child: Center(
          child: CircularProgressIndicator(color: Color(0xFF4FC3F7)),
        ),
      );
    }
    if (_error != null && _forecast == null) {
      return Padding(
        padding: const EdgeInsets.all(8),
        child: Text(_error!,
            style: const TextStyle(color: Color(0xFFFF6B6B), fontSize: 12)),
      );
    }
    if (_forecast == null) return const SizedBox.shrink();

    final current = _forecast!['current_weather'] as Map<String, dynamic>?;
    final daily = _forecast!['daily'] as Map<String, dynamic>?;
    if (current == null || daily == null) return const SizedBox.shrink();

    final curTemp = (current['temperature'] as num?)?.toDouble();
    final curCode = (current['weathercode'] as num?)?.toInt() ?? 0;
    final curWind = (current['windspeed'] as num?)?.toDouble();

    final dates = (daily['time'] as List<dynamic>?)?.cast<String>() ?? [];
    final codes = (daily['weather_code'] as List<dynamic>?)?.cast<num>() ?? [];
    final tMax =
        (daily['temperature_2m_max'] as List<dynamic>?)?.cast<num>() ?? [];
    final tMin =
        (daily['temperature_2m_min'] as List<dynamic>?)?.cast<num>() ?? [];
    final pop = (daily['precipitation_probability_max'] as List<dynamic>?)
            ?.cast<num>() ??
        [];

    return SingleChildScrollView(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // 現在の天気
          Row(children: [
            Icon(_iconForCode(curCode),
                color: _colorForCode(curCode), size: 48),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    curTemp != null ? '${curTemp.round()}°' : '--',
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 32,
                        fontWeight: FontWeight.w300),
                  ),
                  Text(_labelForCode(curCode, p),
                      style:
                          const TextStyle(color: Colors.white70, fontSize: 12)),
                  if (curWind != null)
                    Text(
                        '${p.t('weather.wind')}: ${curWind.toStringAsFixed(1)} km/h',
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 10)),
                ],
              ),
            ),
          ]),
          const Divider(color: Colors.white12, height: 18),
          // 予報リスト (タップで時間別予報を展開)
          for (int i = 0; i < dates.length && i < 5; i++) ...[
            InkWell(
              onTap: () {
                final wasExpanded = _expandedDayIndex == i;
                setState(() {
                  _expandedDayIndex = wasExpanded ? null : i;
                });
                // 「今日」を新たに展開した時は、現在時刻のセルが
                // 中央に来るよう次フレーム後に自動スクロールする
                if (!wasExpanded && i == 0) {
                  WidgetsBinding.instance
                      .addPostFrameCallback((_) => _scrollToCurrentHour());
                }
              },
              borderRadius: BorderRadius.circular(6),
              child: Padding(
                padding: const EdgeInsets.symmetric(vertical: 5, horizontal: 4),
                child: Row(children: [
                  SizedBox(
                    width: 56,
                    child: Text(
                      i == 0
                          ? p.t('weather.today')
                          : (i == 1
                              ? p.t('weather.tomorrow')
                              : _shortDateLabel(dates[i])),
                      style: TextStyle(
                          color: i == 0 ? Colors.white : Colors.white70,
                          fontSize: 11,
                          fontWeight:
                              i == 0 ? FontWeight.w700 : FontWeight.normal),
                    ),
                  ),
                  Icon(
                    _iconForCode(codes.length > i ? codes[i].toInt() : 0),
                    color:
                        _colorForCode(codes.length > i ? codes[i].toInt() : 0),
                    size: 22,
                  ),
                  const SizedBox(width: 8),
                  if (pop.length > i && pop[i] > 0) ...[
                    const Icon(Icons.water_drop_outlined,
                        color: Color(0xFF4FC3F7), size: 12),
                    Text('${pop[i].toInt()}%',
                        style: const TextStyle(
                            color: Color(0xFF4FC3F7), fontSize: 10)),
                    const SizedBox(width: 6),
                  ],
                  Expanded(child: const SizedBox.shrink()),
                  Text(
                    tMax.length > i ? '${tMax[i].round()}°' : '--',
                    style: const TextStyle(
                        color: Color(0xFFFF6B6B),
                        fontSize: 12,
                        fontWeight: FontWeight.w700),
                  ),
                  const SizedBox(width: 4),
                  Text('/',
                      style: TextStyle(color: Colors.white24, fontSize: 11)),
                  const SizedBox(width: 4),
                  Text(
                    tMin.length > i ? '${tMin[i].round()}°' : '--',
                    style: const TextStyle(
                        color: Color(0xFF4FC3F7),
                        fontSize: 12,
                        fontWeight: FontWeight.w700),
                  ),
                  const SizedBox(width: 4),
                  // 折り畳み/展開を示すシェブロン (回転アニメ付き)
                  AnimatedRotation(
                    turns: _expandedDayIndex == i ? 0.5 : 0.0,
                    duration: const Duration(milliseconds: 180),
                    child: const Icon(Icons.keyboard_arrow_down_rounded,
                        color: Colors.white38, size: 16),
                  ),
                ]),
              ),
            ),
            // ── 展開時の時間別予報 (横スクロール) ──
            // open-meteo の hourly は forecast_days=5 で 120 時間分まとめて
            // 返されるので、その日の prefix で絞り込み 24 時間表示する。
            if (_expandedDayIndex == i) _buildHourlyStrip(i, p),
          ],
        ],
      ),
    );
  }

  /// 指定日の時間別予報を横スクロールで表示する。
  /// 各セル: 時刻 / アイコン / 気温 / 降水確率 を縦に並べる。
  /// 1 セル幅 ~50px (モバイル) / ~58px (デスクトップ) 想定。
  Widget _buildHourlyStrip(int dayIndex, MindMapProvider p) {
    final hours = _hourlyForDay(dayIndex);
    if (hours.isEmpty) {
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 8),
        child: Text(p.t('weather.noHourly'),
            style: const TextStyle(color: Colors.white38, fontSize: 11)),
      );
    }
    final isMobile = _isMobileScreen;
    // 旧サイズ (46/52) ではセル数 24 個に対して時刻ラベルを大きくできず
    // ユーザーが「01 が何時か分からない」と感じたため広めに変更。
    final double cellW = isMobile ? 50 : 58;
    final now = DateTime.now();
    return Container(
      margin: const EdgeInsets.only(top: 4, bottom: 8),
      padding: const EdgeInsets.symmetric(vertical: 6, horizontal: 6),
      decoration: BoxDecoration(
        color: const Color(0xFF4FC3F7).withValues(alpha: 0.08),
        borderRadius: BorderRadius.circular(8),
        border:
            Border.all(color: const Color(0xFF4FC3F7).withValues(alpha: 0.25)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisSize: MainAxisSize.min,
        children: [
          // ── 見出し ──
          Padding(
            padding: const EdgeInsets.only(left: 4, bottom: 4),
            child: Row(children: [
              const Icon(Icons.access_time_rounded,
                  color: Colors.white54, size: 12),
              const SizedBox(width: 4),
              Text(p.t('weather.hourlyHeader'),
                  style: const TextStyle(
                      color: Colors.white54,
                      fontSize: 10,
                      fontWeight: FontWeight.w600)),
              const SizedBox(width: 6),
              const Expanded(
                child: Divider(color: Colors.white12, height: 1),
              ),
              const SizedBox(width: 4),
              Icon(Icons.swipe_rounded, color: Colors.white24, size: 11),
            ]),
          ),
          // ── 横スクロール本体 ──
          // 左右ボタン + Scrollbar 付き ListView。マウスでドラッグ可能。
          // 旧実装 (SingleChildScrollView + Row) では一部環境で
          // 横スワイプ/マウスドラッグが効かなかったため、より直接的な
          // ListView + 制御 UI に変更。
          Row(
            children: [
              // 左へスクロール (デスクトップ等で離散ジャンプ用)
              _HourlyScrollBtn(
                icon: Icons.chevron_left_rounded,
                onTap: () => _scrollHourly(-cellW * 4),
                tooltip: p.t('weather.scrollLeft'),
              ),
              Expanded(
                child: SizedBox(
                  height: 96,
                  // ScrollConfiguration: マウスでもタッチでもドラッグ可能に
                  child: ScrollConfiguration(
                    behavior: const _AlwaysDraggableScrollBehavior(),
                    child: Scrollbar(
                      controller: _hourlyScrollCtrl,
                      thumbVisibility: true,
                      thickness: 4,
                      radius: const Radius.circular(2),
                      child: ListView.builder(
                        controller: _hourlyScrollCtrl,
                        scrollDirection: Axis.horizontal,
                        physics: const AlwaysScrollableScrollPhysics(),
                        padding:
                            const EdgeInsets.only(left: 4, right: 4, bottom: 8),
                        itemCount: hours.length,
                        itemExtent: cellW,
                        itemBuilder: (_, idx) {
                          final h = hours[idx];
                          final timeStr = h['time'] as String? ?? '';
                          int hour = 0;
                          try {
                            hour = DateTime.parse(timeStr).hour;
                          } catch (_) {}
                          final temp = h['temp'] as num?;
                          final pop = h['pop'] as num?;
                          final code = h['code'] as int? ?? 0;
                          final isCurrentHour =
                              dayIndex == 0 && hour == now.hour;
                          return Container(
                            margin: const EdgeInsets.symmetric(horizontal: 1),
                            padding: const EdgeInsets.symmetric(vertical: 4),
                            decoration: BoxDecoration(
                              color: isCurrentHour
                                  ? const Color(0xFF4FC3F7)
                                      .withValues(alpha: 0.22)
                                  : Colors.transparent,
                              borderRadius: BorderRadius.circular(6),
                              border: isCurrentHour
                                  ? Border.all(
                                      color: const Color(0xFF4FC3F7),
                                      width: 1.2)
                                  : null,
                            ),
                            child: Column(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                Text(
                                  '${hour.toString().padLeft(2, '0')}:00',
                                  style: TextStyle(
                                      color: isCurrentHour
                                          ? Colors.white
                                          : Colors.white60,
                                      fontSize: 10,
                                      fontWeight: FontWeight.w600),
                                ),
                                const SizedBox(height: 2),
                                Icon(_iconForCode(code),
                                    color: _colorForCode(code), size: 18),
                                const SizedBox(height: 2),
                                Text(
                                  temp != null ? '${temp.round()}°' : '--',
                                  style: const TextStyle(
                                      color: Colors.white,
                                      fontSize: 11,
                                      fontWeight: FontWeight.w700),
                                ),
                                Row(
                                  mainAxisAlignment: MainAxisAlignment.center,
                                  children: [
                                    Icon(Icons.water_drop_outlined,
                                        color: (pop != null && pop > 0)
                                            ? const Color(0xFF4FC3F7)
                                            : Colors.white12,
                                        size: 9),
                                    const SizedBox(width: 1),
                                    Text(
                                      pop != null ? '${pop.toInt()}' : '0',
                                      style: TextStyle(
                                          color: (pop != null && pop > 0)
                                              ? const Color(0xFF4FC3F7)
                                              : Colors.white24,
                                          fontSize: 9),
                                    ),
                                  ],
                                ),
                              ],
                            ),
                          );
                        },
                      ),
                    ),
                  ),
                ),
              ),
              _HourlyScrollBtn(
                icon: Icons.chevron_right_rounded,
                onTap: () => _scrollHourly(cellW * 4),
                tooltip: p.t('weather.scrollRight'),
              ),
            ],
          ),
        ],
      ),
    );
  }

  /// 時間別ストリップを左右にスクロールする (左右ボタン用)。
  /// `delta` ピクセル分だけアニメーションでスクロールする。
  void _scrollHourly(double delta) {
    if (!_hourlyScrollCtrl.hasClients) return;
    final pos = _hourlyScrollCtrl.position;
    final target =
        (pos.pixels + delta).clamp(pos.minScrollExtent, pos.maxScrollExtent);
    _hourlyScrollCtrl.animateTo(
      target,
      duration: const Duration(milliseconds: 250),
      curve: Curves.easeOut,
    );
  }

  /// 「今日」を展開した直後に、現在時刻のセルがビューポート中央に
  /// 来るようスクロール位置を計算してアニメーション。
  /// ListView の構築直後はまだ position.viewportDimension が 0 のことが
  /// あるので、必要なら遅延リトライする。
  void _scrollToCurrentHour({int retry = 0}) {
    if (!mounted) return;
    if (!_hourlyScrollCtrl.hasClients) {
      if (retry < 8) {
        Future.delayed(const Duration(milliseconds: 50), () {
          _scrollToCurrentHour(retry: retry + 1);
        });
      }
      return;
    }
    final pos = _hourlyScrollCtrl.position;
    if (pos.viewportDimension <= 0) {
      if (retry < 8) {
        Future.delayed(const Duration(milliseconds: 50), () {
          _scrollToCurrentHour(retry: retry + 1);
        });
      }
      return;
    }
    final isMobile = _isMobileScreen;
    final double cellW = isMobile ? 50 : 58;
    final hour = DateTime.now().hour;
    // セルの左端 X = hour * cellW、中央に置きたい X = viewportW / 2 - cellW / 2
    final target = (hour * cellW - pos.viewportDimension / 2 + cellW / 2)
        .clamp(pos.minScrollExtent, pos.maxScrollExtent);
    _hourlyScrollCtrl.animateTo(
      target,
      duration: const Duration(milliseconds: 350),
      curve: Curves.easeOutCubic,
    );
  }

  /// 'YYYY-MM-DD' → 'M/D'
  String _shortDateLabel(String iso) {
    try {
      final d = DateTime.parse(iso);
      return '${d.month}/${d.day}';
    } catch (_) {
      return iso;
    }
  }
}

// ─── 地図ピッカーダイアログ ──────────────────────────────────────────────
// OpenStreetMap タイル + Leaflet.js を InAppWebView で表示し、ユーザーが
// タップした位置の lat/lon を JavaScript handler 経由で受け取る。
// open-meteo は任意の lat/lon で予報を返してくれるため、地図上のタップ位置
// そのまま天気予報を取得できる (もっとも近い既存都市にスナップする必要なし)。
class _MapPickerDialog extends StatefulWidget {
  final double initialLat;
  final double initialLon;
  final MindMapProvider provider;

  /// (lat, lon) を受け取って画面側に処理を委譲。Navigator.pop は
  /// 呼び出し元 (_FloatingWeatherState._showMapPicker) で行う。
  final Future<void> Function(double lat, double lon) onPick;
  const _MapPickerDialog({
    required this.initialLat,
    required this.initialLon,
    required this.provider,
    required this.onPick,
  });
  @override
  State<_MapPickerDialog> createState() => _MapPickerDialogState();
}

class _MapPickerDialogState extends State<_MapPickerDialog> {
  iaw.InAppWebViewController? _ctrl;
  // Windows desktop 用の WebView2 コントローラ。
  // _isWindowsDesktop の時だけ初期化される。
  wv_win.WebviewController? _winCtrl;
  bool _winInitialized = false;
  bool _winError = false;
  StreamSubscription<dynamic>? _winMsgSub;

  /// Windows デスクトップかどうか (タッチデバイス Surface などはモバイル扱い)
  bool get _isWindowsDesktop {
    if (kIsWeb) return false;
    if (!Platform.isWindows) return false;
    // 画面幅 600px 未満ならタブレット/タッチ Surface とみなしモバイル扱い
    final w = MediaQuery.of(context).size.width;
    return w >= 600;
  }

  /// ユーザーが地図上をタップして暫定的に選択した位置 (まだ確定前)。
  double? _pendingLat;
  double? _pendingLon;

  @override
  void initState() {
    super.initState();
    if (_isPlatformWindowsDesktopAtInit()) {
      _initWindowsWebview();
    }
  }

  /// initState 時点では context が制限されるので Platform 直接判定する。
  /// 画面幅判定は build 内で再評価する。
  bool _isPlatformWindowsDesktopAtInit() {
    if (kIsWeb) return false;
    return Platform.isWindows;
  }

  Future<void> _initWindowsWebview() async {
    try {
      final ctrl = wv_win.WebviewController();
      await ctrl.initialize();
      // ── JS → Dart メッセージ受信 ──
      // JS 側で window.chrome.webview.postMessage(JSON.stringify({lat, lon}))
      // を呼び出す。webMessage は既に JSON パース済みで届く。
      _winMsgSub = ctrl.webMessage.listen((msg) {
        try {
          double? lat;
          double? lon;
          if (msg is Map) {
            lat = (msg['lat'] as num?)?.toDouble();
            lon = (msg['lon'] as num?)?.toDouble();
          } else if (msg is String) {
            final m = jsonDecode(msg) as Map<String, dynamic>;
            lat = (m['lat'] as num?)?.toDouble();
            lon = (m['lon'] as num?)?.toDouble();
          }
          if (lat != null && lon != null && mounted) {
            setState(() {
              _pendingLat = lat;
              _pendingLon = lon;
            });
          }
        } catch (e) {
          debugPrint('Map picker (Windows) message parse error: $e');
        }
      });
      // HTML を data URL でロード (loadUrl で data: スキーム可)
      final dataUrl =
          'data:text/html;charset=utf-8;base64,${base64Encode(utf8.encode(_buildHtml(forWindows: true)))}';
      await ctrl.loadUrl(dataUrl);
      if (mounted) {
        setState(() {
          _winCtrl = ctrl;
          _winInitialized = true;
        });
      }
    } catch (e) {
      debugPrint('Windows webview init failed for map picker: $e');
      if (mounted) setState(() => _winError = true);
    }
  }

  /// Leaflet.js + OSM タイルを表示する HTML。
  /// クリックでマーカーを置き、JavaScript handler 'pick' で Flutter に通知。
  /// forWindows=true の場合は wv_win 用 (window.chrome.webview.postMessage)、
  /// それ以外は iaw 用 (window.flutter_inappwebview.callHandler) のメッセージ
  /// 送信コードを生成する。
  String _buildHtml({bool forWindows = false}) {
    final messageJs = forWindows
        ? '''
        if (window.chrome && window.chrome.webview && window.chrome.webview.postMessage) {
          window.chrome.webview.postMessage({lat: lat, lon: lon});
        }
        '''
        : '''
        if (window.flutter_inappwebview && window.flutter_inappwebview.callHandler) {
          window.flutter_inappwebview.callHandler('pick', lat, lon);
        }
        ''';
    return '''
<!DOCTYPE html>
<html lang="ja">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
  <title>Map Picker</title>
  <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" crossorigin="" />
  <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" crossorigin=""></script>
  <style>
    html, body, #map { margin: 0; padding: 0; height: 100%; width: 100%; background: #1E1E32; }
    .leaflet-container { background: #1E1E32; }
    .pick-tip {
      position: fixed; top: 8px; left: 50%; transform: translateX(-50%);
      background: rgba(30,30,50,0.85); color: #fff; padding: 6px 12px;
      border-radius: 16px; font-size: 12px; z-index: 1000;
      box-shadow: 0 2px 8px rgba(0,0,0,0.4); pointer-events: none;
    }
  </style>
</head>
<body>
  <div id="map"></div>
  <div class="pick-tip" id="tip">タップで場所を選択 / Tap to select</div>
  <script>
    var map = L.map('map').setView([${widget.initialLat}, ${widget.initialLon}], 9);
    // ── タイルレイヤー ──
    // 旧 'tile.openstreetmap.org' は Referer ヘッダー必須のため data: URL
    // から開いた WebView では「Access blocked」となり拒否される。
    // 旧 CARTO Dark Matter は読みづらかったため CARTO Voyager に変更:
    //   - Referer 不要 + 無料 + 商用 OK
    //   - 中間色で地名/道路がはっきり見える
    //   - ダークなダイアログ背景にも比較的馴染む
    L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
      attribution: '&copy; OpenStreetMap &copy; CARTO',
      subdomains: 'abcd',
      maxZoom: 19,
    }).addTo(map);
    var marker = L.marker([${widget.initialLat}, ${widget.initialLon}]).addTo(map);
    function send(lat, lon) {
      $messageJs
    }
    map.on('click', function(e) {
      marker.setLatLng(e.latlng);
      send(e.latlng.lat, e.latlng.lng);
    });
  </script>
</body>
</html>
''';
  }

  /// 各プラットフォームの WebView ウィジェットを生成。
  /// Windows 11 などのデスクトップでは wv_win、それ以外は iaw を使用。
  Widget _buildWebView() {
    if (_isWindowsDesktop) {
      if (_winError) {
        return Center(
          child: Padding(
            padding: const EdgeInsets.all(24),
            child: Text(
              widget.provider.t('weather.fetchFail'),
              style: const TextStyle(color: Color(0xFFFF6B6B), fontSize: 13),
              textAlign: TextAlign.center,
            ),
          ),
        );
      }
      if (!_winInitialized || _winCtrl == null) {
        return const Center(
          child: CircularProgressIndicator(color: Color(0xFF43B97F)),
        );
      }
      return wv_win.Webview(
        _winCtrl!,
        permissionRequested: (url, kind, isUserInitiated) =>
            wv_win.WebviewPermissionDecision.allow,
      );
    }
    // ── iaw 経路 ──
    // initialData ではなく onWebViewCreated 後に loadData する方が確実。
    // (一部プラットフォームで initialData が無視されるケースがあるため)
    return iaw.InAppWebView(
      initialUrlRequest: iaw.URLRequest(
        url: iaw.WebUri('about:blank'),
      ),
      initialSettings: iaw.InAppWebViewSettings(
        javaScriptEnabled: true,
        domStorageEnabled: true,
        useHybridComposition: true,
        transparentBackground: false,
        supportZoom: true,
        builtInZoomControls: false,
      ),
      onWebViewCreated: (controller) {
        _ctrl = controller;
        controller.addJavaScriptHandler(
          handlerName: 'pick',
          callback: (args) {
            if (args.length < 2) return;
            final lat = (args[0] as num).toDouble();
            final lon = (args[1] as num).toDouble();
            if (mounted) {
              setState(() {
                _pendingLat = lat;
                _pendingLon = lon;
              });
            }
          },
        );
        // WebView 作成後に HTML をロード(initialData より確実)
        controller.loadData(
          data: _buildHtml(),
          mimeType: 'text/html',
          encoding: 'utf-8',
          baseUrl: iaw.WebUri('https://map.local/'),
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final p = widget.provider;
    return Column(
      children: [
        // ── ヘッダー ──
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
          decoration: const BoxDecoration(
            color: Color(0xFF2A2A3E),
            borderRadius: BorderRadius.vertical(top: Radius.circular(14)),
          ),
          child: Row(children: [
            const Icon(Icons.map_outlined, color: Color(0xFF43B97F), size: 18),
            const SizedBox(width: 8),
            Expanded(
              child: Text(p.t('weather.pickFromMap'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 14,
                      fontWeight: FontWeight.w700)),
            ),
            IconButton(
              icon: const Icon(Icons.close, color: Colors.white54, size: 20),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints(minWidth: 32, minHeight: 32),
              onPressed: () => Navigator.of(context).pop(),
            ),
          ]),
        ),
        // ── マップ本体 (プラットフォーム別) ──
        Expanded(
          child: ClipRRect(child: _buildWebView()),
        ),
        // ── 確定ボタン ──
        Container(
          padding: const EdgeInsets.all(12),
          decoration: const BoxDecoration(
            color: Color(0xFF2A2A3E),
            borderRadius: BorderRadius.vertical(bottom: Radius.circular(14)),
          ),
          child: Row(children: [
            Expanded(
              child: Text(
                _pendingLat == null
                    ? p.t('weather.tapMapHint')
                    // 暫定選択中は座標を表示
                    : '${_pendingLat!.toStringAsFixed(4)}, ${_pendingLon!.toStringAsFixed(4)}',
                style: TextStyle(
                    color: _pendingLat == null ? Colors.white54 : Colors.white,
                    fontSize: 11),
              ),
            ),
            const SizedBox(width: 8),
            ElevatedButton.icon(
              onPressed: _pendingLat == null
                  ? null
                  : () async {
                      final lat = _pendingLat!;
                      final lon = _pendingLon!;
                      // pop は親側で行う (await 中に context が無効化されないように)
                      await widget.onPick(lat, lon);
                    },
              icon: const Icon(Icons.check_rounded, size: 16),
              label: Text(p.t('weather.confirmLocation')),
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF43B97F),
                  foregroundColor: Colors.white,
                  padding:
                      const EdgeInsets.symmetric(vertical: 8, horizontal: 14)),
            ),
          ]),
        ),
      ],
    );
  }

  @override
  void dispose() {
    _ctrl = null;
    _winMsgSub?.cancel();
    _winCtrl?.dispose();
    super.dispose();
  }
}

// ─── 時間別ストリップ用の左右スクロールボタン ──────────────────────────────
// マウス/タッチ両対応。タップでストリップを離散ジャンプ。
class _HourlyScrollBtn extends StatelessWidget {
  final IconData icon;
  final VoidCallback onTap;
  final String tooltip;
  const _HourlyScrollBtn({
    required this.icon,
    required this.onTap,
    required this.tooltip,
  });
  @override
  Widget build(BuildContext context) {
    return Tooltip(
      message: tooltip,
      child: InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(14),
        child: Container(
          width: 24,
          height: 88,
          alignment: Alignment.center,
          child: Icon(icon, color: Colors.white54, size: 18),
        ),
      ),
    );
  }
}

/// マウスでもタッチでもドラッグでスクロール可能にする ScrollBehavior。
/// Flutter のデフォルトはデスクトップではマウスドラッグでのスクロールが
/// 無効化されているため、明示的に [PointerDeviceKind.mouse] を含めている。
class _AlwaysDraggableScrollBehavior extends MaterialScrollBehavior {
  const _AlwaysDraggableScrollBehavior();
  @override
  Set<PointerDeviceKind> get dragDevices => {
        PointerDeviceKind.touch,
        PointerDeviceKind.mouse,
        PointerDeviceKind.stylus,
        PointerDeviceKind.trackpad,
        PointerDeviceKind.invertedStylus,
      };
}

/// 横に収まらないツール列の包み (= ユーザー報告: 窓を小さくすると消しゴム
/// などの項目に届かない)。 マウスを乗せて左右に動かすだけで、 カーソルの
/// 位置に比例して列が横スクロールする (左端 = 先頭、 右端 = 末尾)。
/// 収まっている時は何もしない。 タッチ / マウスのドラッグでも動かせる。
class _HoverScrollRow extends StatefulWidget {
  const _HoverScrollRow({required this.child});
  final Widget child;
  @override
  State<_HoverScrollRow> createState() => _HoverScrollRowState();
}

class _HoverScrollRowState extends State<_HoverScrollRow> {
  final ScrollController _ctrl = ScrollController();

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  void _onHover(PointerHoverEvent e) {
    if (!_ctrl.hasClients) return;
    final pos = _ctrl.position;
    final max = pos.maxScrollExtent;
    if (max <= 0) return; // 収まっている時は何もしない
    // 端に少し遊びを置き、 端まで行き切れるようにする。
    const edge = 24.0;
    final w = pos.viewportDimension;
    if (w <= edge * 2) return;
    final t = ((e.localPosition.dx - edge) / (w - edge * 2)).clamp(0.0, 1.0);
    _ctrl.jumpTo(max * t);
  }

  @override
  Widget build(BuildContext context) {
    return MouseRegion(
      onHover: _onHover,
      child: ScrollConfiguration(
        behavior: const _AlwaysDraggableScrollBehavior(),
        child: SingleChildScrollView(
          controller: _ctrl,
          scrollDirection: Axis.horizontal,
          child: widget.child,
        ),
      ),
    );
  }
}

// ─── バックグラウンド再生 (audio_service ベース) ────────────────────────────
//
// 設計:
//   - audio_service の AudioHandler を実装して、Android の Foreground Service
//     + MediaSession を起動する。
//   - 当アプリは音声を Flutter 側で再生していない (WebView 内 <video> が
//     ブラウザネイティブで音を出している) ので、AudioHandler としては
//     無音の loop を流して Service を生かしておくだけ。
//   - 動画再生開始時に `_BgPlaybackController.start()` で Service 起動、
//     動画ページ閉じる時に `stop()` で停止。
//
// 効果:
//   - Service が生きている間、Activity が onStop に達しても完全には殺され
//     ないため、WebView の <video> 音声が画面オフでも継続される。
//   - 通知バーに「動画再生中」常駐通知 + ロック画面にメディアコントロール
//     が表示される。
//   - 制限: メディアコントロールの play/pause は WebView 内 <video> と
//     同期しない (= 当アプリは音源を持たない構造のため)。シンプル化。

/// audio_service が要求する AudioHandler 実装 (ダミー無音版)。
class _BackgroundAudioHandler extends BaseAudioHandler {
  /// ダミー無音 player。loop で再生し続ける。
  /// audio_service は最低でも 1 つの player が再生中であることを Service
  /// 維持の条件としているので、これがないと数秒で Service が終わってしまう。
  ///
  /// `handleAudioSessionActivation: false` は最重要設定:
  /// just_audio はデフォルトで audio session の自動取得を行うが、画面オフ
  /// →オンを繰り返すと OS が他アプリ (システム音・通知) に focus を渡し、
  /// その通知を受けて just_audio が player を pause してしまう。これが
  /// 「2 回目以降の画面オフでバックグラウンド再生が止まる」現象の正体。
  /// false にすると just_audio は audio focus を取りに行かず、focus loss
  /// イベントも無視するので、画面オン/オフサイクルでも player は動き続ける。
  /// (当 player は無音なので audio focus を取る必要はそもそもない)
  ///
  /// 注: `handleInterruptionsAutomatically` パラメータは just_audio 0.10.x
  /// 以降の新しいオプションで、当アプリで使っている 0.9.46 には存在しない。
  /// 0.9.46 では `handleAudioSessionActivation: false` が割込み無視の役目も
  /// 兼ねている。
  final ja.AudioPlayer _player = ja.AudioPlayer(
    handleAudioSessionActivation: false,
  );

  /// 無音 player が何らかの理由で停止したら自動再開する watchdog Timer。
  Timer? _watchdog;

  /// `stop()` が明示的に呼ばれたら true。watchdog はこのフラグが false の
  /// 間だけ動く (= ユーザー意図の停止は尊重)。
  bool _stoppedExplicitly = false;

  /// 多言語対応の通知タイトル / アーティスト (= 説明文)。play() 時に
  /// mediaItem に設定する。
  String _notifTitle;
  String _notifArtist;

  _BackgroundAudioHandler({
    String notifTitle = 'マインドマップ',
    String notifArtist = '動画再生中',
  })  : _notifTitle = notifTitle,
        _notifArtist = notifArtist {
    // 1秒の無音 (data URI の WAV) をループ再生する。
    _initSilentLoop();
    // playerStateStream で停止検知 → 自動再開 (二重保険)
    _player.playerStateStream.listen((state) {
      if (!_stoppedExplicitly &&
          !state.playing &&
          state.processingState != ja.ProcessingState.idle &&
          state.processingState != ja.ProcessingState.completed) {
        _player.play().catchError((_) {});
      }
    });
  }

  /// 言語切替時にラベルを更新する。次回の play() で反映される。
  /// 既に再生中なら mediaItem も即座に更新。
  void updateLabels(String title, String artist) {
    _notifTitle = title;
    _notifArtist = artist;
    if (playbackState.value.playing) {
      mediaItem.add(MediaItem(
        id: 'mindmap-bg-audio',
        title: title,
        artist: artist,
      ));
    }
  }

  Future<void> _initSilentLoop() async {
    try {
      // ── audio_session の設定 ──
      // 動画再生用の AudioSession として明示することで、OS にも「これは
      // メディア再生中」を宣言する。focus を取りには行かないが、属性は
      // 正しく設定する。
      // (audio_service が裏で audio_session も持っているので、こちらは
      //  最小限の宣言だけ)
      // 1 秒の無音 PCM WAV (44 byte header + 1秒分のゼロサンプル)。
      const silentWavBase64 =
          'UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA=';
      await _player.setAudioSource(
        ja.AudioSource.uri(Uri.parse('data:audio/wav;base64,$silentWavBase64')),
        preload: true,
      );
      await _player.setLoopMode(ja.LoopMode.all);
      await _player.setVolume(0.0); // 完全無音
    } catch (e) {
      debugPrint('Silent loop init failed: $e');
    }
  }

  /// watchdog Timer を起動。play() 中だけ動く。
  /// 500ms ごとに player.play() を強制呼び出し + playbackState に
  /// playing:true を発信し続ける。audio focus loss・OS の player 制御
  /// による中断を、こちらの呼び出しで上書きし続けるのが目的。
  /// (頻度を上げているのは、画面オン/オフサイクルでの一瞬の中断も
  ///  検知して即復帰させるため。CPU/電池負担は data URI 無音 loop
  ///  なので無視できる程度)
  void _startWatchdog() {
    _watchdog?.cancel();
    _watchdog = Timer.periodic(const Duration(milliseconds: 500), (_) {
      if (_stoppedExplicitly) return;
      try {
        // 状態判定をせず無条件で play() を呼ぶ。
        // 既に play 中なら no-op。idle 状態なら再開を試みる。
        // audio_service が Service を維持する判定の鍵になる、player の
        // 内部状態を play 側に常に押し戻す。
        _player.play().catchError((_) {});
        // playbackState は常に playing: true で発信し続ける。
        // audio_service は playbackState を見て Service の生死を決める
        // ため、これが false に落ちると Foreground Service が停止される。
        playbackState.add(playbackState.value.copyWith(
          playing: true,
          controls: [MediaControl.pause, MediaControl.stop],
          processingState: AudioProcessingState.ready,
        ));
      } catch (_) {}
    });
  }

  void _stopWatchdog() {
    _watchdog?.cancel();
    _watchdog = null;
  }

  @override
  Future<void> play() async {
    _stoppedExplicitly = false;
    try {
      await _player.play();
      playbackState.add(playbackState.value.copyWith(
        playing: true,
        controls: [MediaControl.pause, MediaControl.stop],
        processingState: AudioProcessingState.ready,
      ));
      mediaItem.add(MediaItem(
        id: 'mindmap-bg-audio',
        title: _notifTitle,
        artist: _notifArtist,
      ));
      _startWatchdog();
    } catch (e) {
      debugPrint('AudioHandler play failed: $e');
    }
  }

  @override
  Future<void> pause() async {
    // ユーザーがロック画面のメディアコントロールから pause を押した場合
    // でも、ここで pause すると Service が止まってしまう。当アプリは
    // バックグラウンド「動画」再生のための Service なので、無音 player は
    // 常に play 状態を維持し、ユーザー pause は無視する。
    // pause を効かせたい場合は stop() を呼ぶか、UI 側で背景再生 OFF。
    debugPrint('AudioHandler pause requested but ignored '
        '(silent loop must keep playing for video bg playback)');
  }

  @override
  Future<void> stop() async {
    _stoppedExplicitly = true;
    _stopWatchdog();
    try {
      await _player.stop();
      playbackState.add(playbackState.value.copyWith(
        playing: false,
        processingState: AudioProcessingState.idle,
        controls: [],
      ));
    } catch (_) {}
    await super.stop();
  }
}

/// バックグラウンド再生 Service の起動・停止を一元管理する静的クラス。
///
/// 参照カウント方式:
///   `acquire()` で開始時にカウント+1、`release()` で終了時にカウント-1。
///   - カウントが 0→1 になった時 Service を起動
///   - カウントが 1→0 になった時 Service を停止 (1秒の grace period 付き)
///
/// これによりフルスクリーン↔PiP 遷移で
///   ・フルスクリーン dispose (release) → カウント1
///   ・PiP initState (acquire) → カウント2
///   ・(古い) フルスクリーン dispose のクリーンアップ → カウント1
///   ・PiP dispose (release) → カウント0 → Service 停止
/// のように、競合せず安全に維持できる。
///
/// 旧 `start()` / `stop()` API は互換のため残してあるが、内部的には
/// `acquire()` / `release()` を呼ぶ。
class _BgPlaybackController {
  static _BackgroundAudioHandler? _handler;
  static bool _initializing = false;

  /// 「動画ページの数」参照カウント。0 の時 Service 停止、1 以上で維持。
  static int _refCount = 0;

  /// release 時の遅延停止 Timer。1秒以内に再 acquire されたらキャンセル
  /// される (= フルスクリーン↔PiP 遷移中の一瞬の 0 を許容)。
  static Timer? _stopTimer;

  /// 多言語対応: Service 起動時に渡す翻訳済みの通知ラベル群。
  /// `acquire()` を呼ぶ前に provider から取得して `setLabels()` で
  /// 設定しておく (動画ページの initState 経由で必ず最新の言語に更新)。
  /// 既定値は日本語 (フォールバック)。
  static String _channelName = 'バックグラウンド再生';
  static String _channelDesc = '動画の音声をバックグラウンドで継続再生するための常駐通知';
  static String _notifTitle = 'マインドマップ';
  static String _notifArtist = '動画再生中';

  /// 多言語対応の翻訳済み通知ラベルを設定する。
  /// 動画ページが起動するたびに最新の言語で呼び直すこと。
  static void setLabels({
    required String channelName,
    required String channelDesc,
    required String notifTitle,
    required String notifArtist,
  }) {
    _channelName = channelName;
    _channelDesc = channelDesc;
    _notifTitle = notifTitle;
    _notifArtist = notifArtist;
    // handler が既に動いていれば mediaItem も更新
    final h = _handler;
    if (h != null) {
      h.updateLabels(notifTitle, notifArtist);
    }
  }

  /// 旧 API 互換: 内部的に acquire を呼ぶ。
  static Future<void> start() => acquire();

  /// 旧 API 互換: 内部的に release を呼ぶ。
  static Future<void> stop() => release();

  /// 動画ページが開いた時呼ぶ。Service を起動 or 維持。
  static Future<void> acquire() async {
    if (!Platform.isAndroid) return;
    _refCount++;
    debugPrint('BgPlayback: acquire (refCount=$_refCount)');
    // 既に保留中の停止 Timer があれば取消 (= 0 にはならず維持される)
    _stopTimer?.cancel();
    _stopTimer = null;
    await _ensureRunning();
  }

  /// 動画ページが閉じた時呼ぶ。1秒の grace period 後にカウント 0 なら停止。
  /// 1秒以内に新しい動画ページが acquire したら停止しない (= 遷移中の維持)。
  static Future<void> release() async {
    if (!Platform.isAndroid) return;
    _refCount--;
    if (_refCount < 0) _refCount = 0;
    debugPrint('BgPlayback: release (refCount=$_refCount)');
    if (_refCount > 0) return; // まだ他のページが開いている
    // 遅延停止: 1秒後にもまだ 0 なら本当に停止する
    _stopTimer?.cancel();
    _stopTimer = Timer(const Duration(seconds: 1), () async {
      if (_refCount > 0) return; // 復帰していれば停止しない
      await _stopNow();
    });
  }

  /// Service を実際に止める (内部用)。
  static Future<void> _stopNow() async {
    if (_handler == null) return;
    try {
      await _handler!.stop();
      debugPrint('BgPlayback: service stopped');
    } catch (e) {
      debugPrint('BgPlayback stop failed: $e');
    }
  }

  /// Service を確実に起動状態にする (内部用)。
  /// 初期化未済なら AudioService.init を呼ぶ。初期化済みでも play() を
  /// 呼び直して、player が止まっていた場合に確実に再開する。
  static Future<void> _ensureRunning() async {
    // 初期化中なら、それが完了するまで待ってから play() を呼ぶ。
    // 旧実装は初期化中に呼ばれると return するだけだったので、後発の
    // acquire が「Service 起動を完了させない」ケースが発生しうるバグ。
    while (_initializing) {
      await Future.delayed(const Duration(milliseconds: 50));
    }
    if (_handler != null) {
      // 既に初期化済み: play() だけ呼ぶ
      try {
        await _handler!.play();
        debugPrint('BgPlayback: re-play (handler already exists)');
      } catch (e) {
        debugPrint('BgPlayback re-play failed: $e');
      }
      return;
    }
    _initializing = true;
    try {
      _handler = await AudioService.init(
        builder: () => _BackgroundAudioHandler(
          notifTitle: _notifTitle,
          notifArtist: _notifArtist,
        ),
        config: AudioServiceConfig(
          androidNotificationChannelId: 'com.mindmap.audio.channel',
          androidNotificationChannelName: _channelName,
          androidNotificationChannelDescription: _channelDesc,
          // androidNotificationOngoing: true は通知をスワイプで消せなく
          // する設定。これを true にするには androidStopForegroundOnPause が
          // true (デフォルト) であることがアサーションで要求される。
          // 当アプリではダミー無音 loop なので pause が来ない設計
          // (_BackgroundAudioHandler.pause は no-op) であり、デフォルト
          // 設定で問題ない。
          androidNotificationIcon: 'mipmap/ic_launcher',
        ),
      );
      await _handler!.play();
      debugPrint('BgPlayback: service started');
    } catch (e, st) {
      debugPrint('BgPlayback init failed: $e\n$st');
    } finally {
      _initializing = false;
    }
  }

  /// `_ensureRunning()` を直接呼びたい場合 (= ライフサイクル経路で
  /// 単に「動いてるか確認したい」だけの用途) のための公開 API。
  /// refCount は変えない。Watchdog 的な使い方。
  static Future<void> ensureRunning() async {
    if (!Platform.isAndroid) return;
    if (_refCount <= 0) return; // 誰も使っていないので起動しない
    await _ensureRunning();
  }

  /// バックグラウンド再生を即座に強制停止する (ユーザー意図の明示停止用)。
  /// 通常の `release()` は 1 秒の grace period があり、また refCount > 0 なら
  /// 止まらないが、forceStop() は refCount を 0 にリセットして即座に Service
  /// を停止する。
  ///
  /// ユーザー要望: 「動画を止めて画面を閉じてもバックグラウンド再生が起動して
  /// しまう」 → アプリ内のプレイヤーから 1 タップで完全停止できるボタンが必要。
  /// 通知バーの停止ボタンを使わなくても済むようにする。
  static Future<void> forceStop() async {
    if (!Platform.isAndroid) return;
    debugPrint('BgPlayback: forceStop (was refCount=$_refCount)');
    _refCount = 0;
    _stopTimer?.cancel();
    _stopTimer = null;
    await _stopNow();
  }

  /// バックグラウンド再生 Service が現在動いているか (UI 表示判定用)。
  /// initializing 中も含めて「動いている扱い」とする。
  static bool get isRunning {
    if (!Platform.isAndroid) return false;
    return _handler != null && (_refCount > 0 || _stopTimer != null);
  }
}

/// Pro 機能 (動画ダウンロード等) が必要なときに表示する案内ダイアログ。
/// トップレベル関数なので、`_MindMapScreenState` と `_FullscreenVideoPageState`
/// など複数の場所から共通で呼べる。
///
/// 「アップグレード」ボタンを押すと、Pro 加入動線に進む (現状は将来の
/// 課金導入用に準備中ステータスを SnackBar で出すのみ。RevenueCat 等の
/// 実装が完成次第、ここから直接 paywall を呼ぶように差し替える)。
/// アプリ統一の SnackBar 表示ヘルパ。
///
/// 旧来 `_appSnack(ctx, ...)` を直接呼んでいた箇所は
/// 全てこの関数経由に統一する。これにより:
///   1. 表示中は下部ツールバー (`provider.bottomBarLifted`) を 80px
///      持ち上げ → メッセージとボタンが重ならない
///   2. SnackBar が閉じたら自動でバーを元に戻す
///   3. `processing == false` (デフォルト) の場合は 5 秒で自動で閉じる
///      ようにオーバーライド (元の SnackBar.duration よりも厳密に短い場合
///      のみ尊重)。 `processing == true` の場合は元の duration を維持
///      (= 長時間処理中は SnackBar が出続ける)。
///
/// 戻り値: 元の `showSnackBar` と同じ `ScaffoldFeatureController`。
// ─── Floating PiP Google Search ─────────────────────────────────────────
//
// PDF/URL メモの 🔍 アイコンから呼び出される、 Google 検索をアプリ内 WebView
// でコンパクトに表示するフローティングオーバーレイ。 計算機/ストップウォッチ
// と同じ OverlayEntry パターンで実装。 マップを操作しながら横で検索結果を
// 確認できる。
//
// 仕様:
//   - 同時に開けるのは 1 つ (新しいクエリで開いたら古いものは閉じる)
//   - サイズ: 380x520 (デスクトップ) / 300x420 (モバイル)
//   - 位置: 画面右上寄りに初期配置。 ヘッダーをドラッグして自由に移動可
//   - WebView: モバイル/iOS = flutter_inappwebview、 Windows = webview_windows
//   - 「ドックボタン」 でサイドバーに移動可能 (`_dockedGoogleSearchNotifier`)

/// サイドバーにドックされた Google 検索の状態を表す。 query は表示用
/// (= 「Google: <クエリ>」 のラベル)、 url は WebView 読み込み URL。
/// null の時はどこにもドックされていない。
class _DockedGoogleSearchState {
  final String query;
  final String url;
  const _DockedGoogleSearchState({required this.query, required this.url});
}

/// `_PdfMemoPanelState.build` で監視され、 非 null の時検索 WebView を
/// メモ一覧の代わりにサイドバー全部に表示する。 PiP の「ドック」 ボタンが
/// 値を書き込み、 「閉じる」/「フロート」 ボタンが null に戻す。
final ValueNotifier<_DockedGoogleSearchState?> _dockedGoogleSearchNotifier =
    ValueNotifier<_DockedGoogleSearchState?>(null);

OverlayEntry? _activeGoogleSearchOverlay;

// ─── YouTube ヘッドレス再生 ──────────────────────────────────────────────
// ユーザー要望: 「YouTubeをヘッドレスで再生するボタンを作って、 押したら
// ヘッドレス再生を止めるボタンが出てきてプレイヤーが閉じてバックグラウンド
// 再生されるようにして」 への対応。
//
// 仕組み:
//   1. ビューワーのツールバーに「ヘッドレス開始」 ボタンを置く。
//   2. タップで現在の動画 URL を捕捉して `startHeadlessYoutube(url)` を呼ぶ。
//   3. `HeadlessInAppWebView` を起動して `run()` する (UI 非表示で内部で
//      動画ページを開き、 音声だけ再生継続)。
//   4. ビューワー画面は閉じる (Navigator.pop)。
//   5. メインキャンバスの右下にフローティング「停止」 ボタンを常設表示
//      (= ValueListenableBuilder で `_headlessYoutubeUrlNotifier` を監視)。
//   6. 停止ボタンタップで `stopHeadlessYoutube()` → ヘッドレス WebView を
//      dispose → 通知も null → フローティングボタン自動消滅。
//
// 注: `HeadlessInAppWebView` は Android / iOS のみで動く (Windows desktop の
// webview_windows には同等機構がないため、 デスクトップでは無効)。

// ── 全角数字 → 半角数字への変換 ──
// (= ユーザー要望: ページ番号は全角で入力しても半角に自動で変換される
// ように)。 ０-９ (U+FF10..U+FF19) を 0-9 (U+0030..U+0039) に置換。
String _toHalfWidthDigits(String s) {
  final buf = StringBuffer();
  for (final cu in s.codeUnits) {
    if (cu >= 0xFF10 && cu <= 0xFF19) {
      buf.writeCharCode(cu - 0xFF10 + 0x30);
    } else {
      buf.writeCharCode(cu);
    }
  }
  return buf.toString();
}

/// ページ番号用の TextField に付与するフォーマッタ。 IME 等で入力された
/// 全角数字をリアルタイムで半角に変換する。
class _FullWidthDigitToHalfFormatter extends TextInputFormatter {
  const _FullWidthDigitToHalfFormatter();
  @override
  TextEditingValue formatEditUpdate(
      TextEditingValue oldValue, TextEditingValue newValue) {
    final converted = _toHalfWidthDigits(newValue.text);
    if (converted == newValue.text) return newValue;
    // カーソル位置は末尾に寄せる (= 文字数は変わらないため許容範囲)。
    return TextEditingValue(
      text: converted,
      selection: TextSelection.collapsed(
          offset: converted.length.clamp(0, converted.length)),
    );
  }
}

/// メモパネルでフォルダをドラッグ並び替えする際の専用データ型。
/// 既存のメモドラッグ (`DragTarget<String>`) と区別するために専用クラス。
class _PdfFolderDragData {
  final String name;
  const _PdfFolderDragData(this.name);
}

// ── メモ画像マーカー ──
// PdfMemo モデルに imagePath フィールドを足さずに「メモに画像」 を実現する
// ため (= ビルド環境のモデル更新漏れでもビルドが通るように)、 画像パスは
// メモ本文 (text) の先頭に `__MMIMG__::<path>` 行として埋め込む。
const String _kMemoImgPrefix = '__MMIMG__::';

// ── デフォルトのユーザーアイコン (= ユーザー要望: デフォルトアイコンが
//    怖いので、 もっと可愛くて地味なものに) ──
// 旧デフォルトの '👤' (黒いシルエット) は環境によっては不気味に見えるため、
//   柔らかく親しみやすい控えめな顔の絵文字を既定にする。
const String _kDefaultAvatarEmoji = '🙂';

/// メモ本文から画像パスと表示用テキストを分離する。
/// 戻り値: (imagePath または null, 画像マーカーを除いた表示テキスト)。
(String?, String) _parseMemoImage(String text) {
  if (!text.startsWith(_kMemoImgPrefix)) return (null, text);
  final nl = text.indexOf('\n');
  if (nl < 0) {
    // マーカー行のみ (画像だけのメモ)
    return (text.substring(_kMemoImgPrefix.length), '');
  }
  final path = text.substring(_kMemoImgPrefix.length, nl);
  final body = text.substring(nl + 1);
  return (path, body);
}

/// いま押されている Esc から来た「閉じて」 か (= 設定が OFF なら無視する
/// ための判定)。 ダイアログ枠は Esc を DismissIntent → maybePop に変えて
/// 送ってくるので、 その瞬間はまだ Esc が押されたままになっている。
bool _isEscClosePressed(BuildContext context) {
  final fromEsc = HardwareKeyboard.instance.logicalKeysPressed
      .contains(LogicalKeyboardKey.escape);
  if (!fromEsc) return false;
  try {
    return !context.read<MindMapProvider>().closeViewerWithEsc;
  } catch (_) {
    return true;
  }
}

/// この編集画面が「自分だけの画面」 として開かれているか。
///
/// 画面分割のペインの中に直接置かれている時は、 アプリ本体の画面と同じ
/// 入れ物 (ルート) に乗っている。 そこで戻る操作を横取りすると、 Android
/// の戻るボタンでアプリ本体の画面まで閉じてしまい、 真っ黒な画面が残る。
/// 一番下の画面に乗っている時は横取りしない。
bool _ownsCloseRoute(BuildContext context) {
  final route = ModalRoute.of(context);
  if (route == null) return false;
  return !route.isFirst;
}

/// いまビューアで開いている PDF のパス (= 同じファイルを別の処理が
/// 同時に触って落ちるのを避けるための控え。 ユーザー報告: 手書きを保存
/// した直後にアプリが落ちる)。
final Set<String> kOpenPdfPaths = <String>{};

/// 同じファイルを指しているか。
///
/// ★ ノードに保存されている添付パスは
///   `C:\Users\...\ドキュメント/attachments/サンプル.pdf` のように区切り文字が
///   混ざっている一方、 ビューアは `Uri.toFilePath()` で全て `\` に揃えた
///   パスを使う。 そのまま == で比べると別物と判定され、 描き込みを保存しても
///   サムネイルを作り直す相手が見つからなかった (= ユーザー報告: PDF に
///   手書きしてもサムネイルに反映されない)。 Windows は大文字小文字も無視する。
bool isSameFilePath(String a, String b) {
  if (a == b) return true;
  if (a.isEmpty || b.isEmpty) return false;
  String norm(String v) {
    final t = v.replaceAll('\\', '/');
    return Platform.isWindows ? t.toLowerCase() : t;
  }

  return norm(a) == norm(b);
}

/// その PDF がビューアで開かれている最中か (区切り文字の違いを吸収して見る)。
/// 開いている間にラスタライズすると、 同じファイルを読んでいるネイティブ側を
/// 巻き添えにして落ちるため、 サムネイル生成はこれで待つ。
bool isPdfOpenNow(String path) {
  for (final p in kOpenPdfPaths) {
    if (isSameFilePath(p, path)) return true;
  }
  return false;
}

/// 現在ヘッドレス再生中の URL。 null なら停止中。 メインキャンバスの
/// フローティング停止ボタンの表示判定 + 在アプリビューワー側の「もう
/// 再生中」 表示判定に使う。
final ValueNotifier<String?> _headlessYoutubeUrlNotifier =
    ValueNotifier<String?>(null);

/// ── PDF メモパネル のキーボードフォーカス状態 (= ユーザー要望対応用) ──
/// _PdfMemoPanelState の `_kbdFocusNode` がフォーカスを持っているかどうかを
/// 公開する。 ビューワー側 (`_InAppViewerDialogState`) の
/// `_globalPdfKeyHandler` がここを参照し、 メモパネルにフォーカスがある
/// 間は ↑/↓ などをパネル専用に予約して PDF を巻き添えで動かさない。
/// (= ユーザー要望: メモ欄を上下キーで移動しているのに PDF まで動いてしまう
/// バグの修正)。
final ValueNotifier<bool> _pdfMemoPanelHasKeyboardFocus =
    ValueNotifier<bool>(false);

/// ── PDF メモパネル のインライン編集 (ダブルクリック編集) 状態 ──
/// インライン編集中は、 たとえ TextField が一時的にフォーカスを失っていても
/// (= ユーザーが PDF をクリックした等)、 N/M/B などの単キーを無効化して
/// 新規メモが立ち上がらないようにする (= ユーザー要望: ダブルクリックで
/// メモを編集中なのに半角の N で新規メモの編集画面が立ち上がってしまう
/// 問題の修正)。
final ValueNotifier<bool> _pdfMemoInlineEditing = ValueNotifier<bool>(false);

/// 現在動いているヘッドレス WebView の参照。 startHeadlessYoutube() が
/// 上書き時に必ず古いものを dispose する (= 二重再生防止)。
iaw.HeadlessInAppWebView? _activeHeadlessYoutubeWebView;

/// ヘッドレス YouTube 再生を開始する。 `url` は通常 `m.youtube.com/watch?v=...`
/// もしくは `youtube.com/watch?v=...` を渡す。 既存の再生は止めて新規に開始。
Future<void> startHeadlessYoutube(String url) async {
  // リリース前コンプライアンス対応:
  // YouTube の画面なし/バックグラウンド再生は規約リスクが高いため無効化。
  await stopHeadlessYoutube();
  debugPrint('YouTube headless playback is disabled for release compliance.');
}

/// ヘッドレス YouTube 再生を止めて WebView を破棄。
Future<void> stopHeadlessYoutube() async {
  final wv = _activeHeadlessYoutubeWebView;
  _activeHeadlessYoutubeWebView = null;
  _headlessYoutubeUrlNotifier.value = null;
  if (wv != null) {
    try {
      await wv.dispose();
    } catch (_) {}
  }
}

/// メモ本文から検索に適したクエリを抽出する。
///
/// クイズメモの保存時に `[searchKey: ...]` という追記を入れているので、
/// そこから検索キーワードを優先的に取り出す。 見つからない場合は:
/// - Q: ... 行があれば質問本文を使う
/// - それ以外はメモ全文の先頭 80 文字 (= 全文ベタ書きで送るのを回避)
///
/// ユーザー要望「検索に与える時は本文そのまま入れるのではなく、 要素分けされた
/// 適切な要素が入れられるようにして欲しい」 への対応。
String _extractSearchQuery(String memoText) {
  // 画像メモは先頭行が `_kMemoImgPrefix + パス` のマーカー。 これを
  // そのまま検索語にすると画像の保存先が Google に送られてしまう
  // (= ユーザー報告)。 本文だけを取り出してから判定する。
  final (_, bodyOnly) = _parseMemoImage(memoText);
  final t = bodyOnly.trim();
  if (t.isEmpty) return '';
  // 1) [searchKey: ...] パターンを優先抽出
  final keyMatch = RegExp(r'\[\s*searchKey\s*:\s*([^\]]+)\]').firstMatch(t);
  if (keyMatch != null) {
    final key = keyMatch.group(1)!.trim();
    if (key.isNotEmpty) return key;
  }
  // 2) Q: ... 行を取り出す (○× の [○×] プレフィックスは除去)
  for (final line in t.split('\n')) {
    final m = RegExp(r'^Q(?:\s*\[○×\])?\s*[::]\s*(.+)$').firstMatch(line);
    if (m != null) {
      var q = m.group(1)!.trim();
      // 末尾の「(である|であるか)」 等は検索の邪魔になるので軽く除去
      q = q.replaceAll(RegExp(r'(である|か[。?？]?$|。$)'), '').trim();
      if (q.isNotEmpty) return q;
    }
  }
  // 3) fallback: 先頭 80 文字
  return t.length <= 80 ? t : t.substring(0, 80);
}

/// PdfMemo / ハイライト等から「Google で検索」 を呼び出すエントリポイント。
/// アプリ内のフローティング PiP WebView でコンパクトに表示する。
void _launchGoogleSearchForMemo(BuildContext ctx, String rawText) {
  final query = rawText.trim();
  if (query.isEmpty) return;
  _openFloatingGoogleSearch(ctx, query);
}

void _openFloatingGoogleSearch(BuildContext ctx, String query) {
  _activeGoogleSearchOverlay?.remove();
  _activeGoogleSearchOverlay = null;

  final overlay = Overlay.maybeOf(ctx, rootOverlay: true);
  if (overlay == null) return;

  late OverlayEntry entry;
  entry = OverlayEntry(
    builder: (_) => _FloatingGoogleSearch(
      query: query,
      onClose: () {
        entry.remove();
        if (identical(_activeGoogleSearchOverlay, entry)) {
          _activeGoogleSearchOverlay = null;
        }
      },
    ),
  );
  _activeGoogleSearchOverlay = entry;
  overlay.insert(entry);
}

class _FloatingGoogleSearch extends StatefulWidget {
  final String query;
  final VoidCallback onClose;
  const _FloatingGoogleSearch({
    required this.query,
    required this.onClose,
  });
  @override
  State<_FloatingGoogleSearch> createState() => _FloatingGoogleSearchState();
}

class _FloatingGoogleSearchState extends State<_FloatingGoogleSearch> {
  Offset _offset = const Offset(40, 80);
  bool _placed = false;
  // ── WebView コントローラ参照 (= ユーザー要望: ノードから立ち上げる
  //    検索ボックスでも戻る/進むボタンを付けて、 Alt+←/→ に対応させる) ──
  iaw.InAppWebViewController? _iawCtrl;
  wv_win.WebviewController? _winCtrl;
  // Alt+←/→ を受け取るためのフォーカスノード (autofocus で取得)
  final FocusNode _keyFocus = FocusNode(debugLabel: 'FloatingGoogleSearch.key');
  // ── ユーザーが境界ドラッグで調整した幅・高さ (= ユーザー要望: 検索
  //    ボックスを横を広げて縦長にして、 境界ドラッグでサイズ調整可能に) ──
  // null の間はビルトインのデフォルトサイズを使う。
  double? _userW;
  double? _userH;

  @override
  void dispose() {
    _keyFocus.dispose();
    super.dispose();
  }

  bool get _isDesktop =>
      Theme.of(context).platform == TargetPlatform.windows ||
      Theme.of(context).platform == TargetPlatform.macOS ||
      Theme.of(context).platform == TargetPlatform.linux;

  Future<void> _goBack() async {
    try {
      if (_isDesktop) {
        await _winCtrl?.goBack();
      } else {
        await _iawCtrl?.goBack();
      }
    } catch (_) {}
  }

  Future<void> _goForward() async {
    try {
      if (_isDesktop) {
        await _winCtrl?.goForward();
      } else {
        await _iawCtrl?.goForward();
      }
    } catch (_) {}
  }

  Future<void> _reload() async {
    try {
      if (_isDesktop) {
        await _winCtrl?.reload();
      } else {
        await _iawCtrl?.reload();
      }
    } catch (_) {}
  }

  KeyEventResult _handleKey(FocusNode node, KeyEvent event) {
    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
      return KeyEventResult.ignored;
    }
    // Alt + ← で戻る、 Alt + → で進む (= ブラウザ標準ショートカット)
    final isAlt = HardwareKeyboard.instance.isAltPressed;
    if (isAlt) {
      if (event.logicalKey == LogicalKeyboardKey.arrowLeft) {
        _goBack();
        return KeyEventResult.handled;
      }
      if (event.logicalKey == LogicalKeyboardKey.arrowRight) {
        _goForward();
        return KeyEventResult.handled;
      }
    }
    return KeyEventResult.ignored;
  }

  @override
  Widget build(BuildContext context) {
    final mq = MediaQuery.of(context);
    final isMobile = mq.size.width < 600;
    final isDesktop = _isDesktop;
    // ── デフォルトサイズを拡大: ユーザー要望「もう少し横を広げて縦長に」 ──
    // デスクトップ: 760x860、 モバイル: 340x600。
    // ユーザーがドラッグで調整した値があればそちらを優先 (_userW/_userH)。
    final double defaultW = isMobile ? 340.0 : 760.0;
    final double defaultH = isMobile ? 600.0 : 860.0;
    // 画面サイズに収まるよう clamp。
    final double maxW = (mq.size.width - 24).clamp(220.0, 2000.0);
    final double maxH =
        (mq.size.height - mq.padding.top - mq.padding.bottom - 24)
            .clamp(280.0, 2400.0);
    final double panelW = (_userW ?? defaultW).clamp(260.0, maxW);
    final double panelH = (_userH ?? defaultH).clamp(280.0, maxH);

    if (!_placed) {
      _placed = true;
      _offset = Offset(
        (mq.size.width - panelW - 16).clamp(20.0, mq.size.width - 20.0),
        mq.padding.top + 80.0,
      );
    }

    const double headerVisible = 36.0;
    final double safeTop = mq.padding.top;
    final double safeBottom = mq.padding.bottom;
    final double maxLeft = (mq.size.width - panelW).clamp(0.0, mq.size.width);
    final double maxTop = (mq.size.height - safeBottom - headerVisible)
        .clamp(safeTop, mq.size.height);
    final clampedLeft = _offset.dx.clamp(0.0, maxLeft);
    final clampedTop = _offset.dy.clamp(safeTop, maxTop);

    final url =
        'https://www.google.com/search?q=${Uri.encodeQueryComponent(widget.query)}';

    return Positioned(
      left: clampedLeft,
      top: clampedTop,
      child: Material(
        elevation: 12,
        borderRadius: BorderRadius.circular(14),
        color: Colors.transparent,
        child: Focus(
          focusNode: _keyFocus,
          autofocus: true,
          onKeyEvent: _handleKey,
          child: SizedBox(
            width: panelW,
            height: panelH,
            child: Stack(
              children: [
                Container(
                  width: panelW,
                  height: panelH,
                  decoration: BoxDecoration(
                    color: const Color(0xFF1E1E32),
                    borderRadius: BorderRadius.circular(14),
                    border: Border.all(
                      color: const Color(0xFF4FC3F7).withValues(alpha: 0.5),
                      width: 1.5,
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black.withValues(alpha: 0.5),
                        blurRadius: 16,
                        offset: const Offset(0, 6),
                      ),
                    ],
                  ),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onPanUpdate: (details) {
                          setState(() {
                            _offset = Offset(
                              (_offset.dx + details.delta.dx)
                                  .clamp(0.0, maxLeft),
                              (_offset.dy + details.delta.dy)
                                  .clamp(safeTop, maxTop),
                            );
                          });
                        },
                        child: MouseRegion(
                          cursor: SystemMouseCursors.move,
                          child: Container(
                            height: headerVisible,
                            padding: const EdgeInsets.symmetric(
                                horizontal: 4, vertical: 4),
                            decoration: BoxDecoration(
                              color: const Color(0xFF4FC3F7)
                                  .withValues(alpha: 0.20),
                              borderRadius: const BorderRadius.only(
                                topLeft: Radius.circular(13),
                                topRight: Radius.circular(13),
                              ),
                            ),
                            child: Row(children: [
                              // ── 戻る / 進む / 再読み込み (= ユーザー要望:
                              //    Windows 版のノード起点の検索ボックスにも遷移
                              //    ボタンを追加。 Alt+←/→ にも対応) ──
                              InkWell(
                                onTap: _goBack,
                                borderRadius: BorderRadius.circular(4),
                                child: Padding(
                                  padding: EdgeInsets.all(4),
                                  child: Tooltip(
                                    message: context
                                        .read<MindMapProvider>()
                                        .t('nav.backAlt'),
                                    child: Icon(Icons.arrow_back_rounded,
                                        color: Colors.white70, size: 16),
                                  ),
                                ),
                              ),
                              InkWell(
                                onTap: _goForward,
                                borderRadius: BorderRadius.circular(4),
                                child: Padding(
                                  padding: EdgeInsets.all(4),
                                  child: Tooltip(
                                    message: context
                                        .read<MindMapProvider>()
                                        .t('nav.forwardAlt'),
                                    child: Icon(Icons.arrow_forward_rounded,
                                        color: Colors.white70, size: 16),
                                  ),
                                ),
                              ),
                              InkWell(
                                onTap: _reload,
                                borderRadius: BorderRadius.circular(4),
                                child: Padding(
                                  padding: EdgeInsets.all(4),
                                  child: Tooltip(
                                    message: context
                                        .read<MindMapProvider>()
                                        .t('player.reload'),
                                    child: Icon(Icons.refresh_rounded,
                                        color: Colors.white70, size: 16),
                                  ),
                                ),
                              ),
                              const SizedBox(width: 4),
                              const Icon(Icons.travel_explore_rounded,
                                  color: Color(0xFF4FC3F7), size: 16),
                              const SizedBox(width: 4),
                              Expanded(
                                child: Text(
                                  widget.query,
                                  style: const TextStyle(
                                      color: Colors.white,
                                      fontSize: 12,
                                      fontWeight: FontWeight.w600),
                                  overflow: TextOverflow.ellipsis,
                                  maxLines: 1,
                                ),
                              ),
                              // 📥 ドックボタン: 検索をサイドバーに移す。
                              InkWell(
                                onTap: () {
                                  _dockedGoogleSearchNotifier.value =
                                      _DockedGoogleSearchState(
                                    query: widget.query,
                                    url: url,
                                  );
                                  widget.onClose();
                                },
                                borderRadius: BorderRadius.circular(4),
                                child: Padding(
                                  padding: EdgeInsets.all(4),
                                  child: Tooltip(
                                    message: context
                                        .read<MindMapProvider>()
                                        .t('gs.dockSidebar'),
                                    child: Icon(
                                        Icons.vertical_align_bottom_rounded,
                                        color: Colors.white70,
                                        size: 16),
                                  ),
                                ),
                              ),
                              InkWell(
                                onTap: widget.onClose,
                                borderRadius: BorderRadius.circular(4),
                                child: const Padding(
                                  padding: EdgeInsets.all(4),
                                  child: Icon(Icons.close,
                                      color: Colors.white70, size: 16),
                                ),
                              ),
                            ]),
                          ),
                        ),
                      ),
                      SizedBox(
                        width: panelW,
                        height: panelH - headerVisible,
                        child: ClipRRect(
                          borderRadius: const BorderRadius.only(
                            bottomLeft: Radius.circular(13),
                            bottomRight: Radius.circular(13),
                          ),
                          child: isDesktop
                              ? _WinGoogleSearchView(
                                  url: url,
                                  onController: (c) => _winCtrl = c,
                                )
                              : iaw.InAppWebView(
                                  initialUrlRequest:
                                      iaw.URLRequest(url: iaw.WebUri(url)),
                                  initialSettings: iaw.InAppWebViewSettings(
                                    javaScriptEnabled: true,
                                    transparentBackground: false,
                                    useShouldOverrideUrlLoading: false,
                                  ),
                                  onWebViewCreated: (c) => _iawCtrl = c,
                                ),
                        ),
                      ),
                    ],
                  ),
                ),
                // ── 4 辺リサイズエッジ (= ユーザー要望: 縦横の幅を境界をドラッグ
                //    することで広げられるように) ──
                // 右辺: 横幅のみ変更。
                Positioned(
                  right: 0,
                  top: 8,
                  bottom: 24,
                  width: 6,
                  child: MouseRegion(
                    cursor: SystemMouseCursors.resizeLeftRight,
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onPanUpdate: (d) {
                        setState(() {
                          _userW = (panelW + d.delta.dx).clamp(260.0, maxW);
                        });
                      },
                      child: const SizedBox.expand(),
                    ),
                  ),
                ),
                // 下辺: 縦幅のみ変更。
                Positioned(
                  left: 8,
                  right: 24,
                  bottom: 0,
                  height: 6,
                  child: MouseRegion(
                    cursor: SystemMouseCursors.resizeUpDown,
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onPanUpdate: (d) {
                        setState(() {
                          _userH = (panelH + d.delta.dy).clamp(280.0, maxH);
                        });
                      },
                      child: const SizedBox.expand(),
                    ),
                  ),
                ),
                // 左辺: 横幅のみ変更 (= 拡張側に伸ばすため、 _offset.dx も同時に
                //   ずらして見た目の左端を維持)。
                Positioned(
                  left: 0,
                  top: 8,
                  bottom: 24,
                  width: 6,
                  child: MouseRegion(
                    cursor: SystemMouseCursors.resizeLeftRight,
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onPanUpdate: (d) {
                        setState(() {
                          final newW = (panelW - d.delta.dx).clamp(260.0, maxW);
                          final actualDelta = panelW - newW;
                          _offset =
                              Offset(_offset.dx + actualDelta, _offset.dy);
                          _userW = newW;
                        });
                      },
                      child: const SizedBox.expand(),
                    ),
                  ),
                ),
                // 上辺: 縦幅のみ変更 (= 同じく _offset.dy をずらす)。
                // ただしヘッダー (= 上 24px) はドラッグ移動用なので、 そこより
                //   1px だけ被せて上端 3px のみ受ける。
                Positioned(
                  left: 8,
                  right: 24,
                  top: 0,
                  height: 3,
                  child: MouseRegion(
                    cursor: SystemMouseCursors.resizeUpDown,
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onPanUpdate: (d) {
                        setState(() {
                          final newH = (panelH - d.delta.dy).clamp(280.0, maxH);
                          final actualDelta = panelH - newH;
                          _offset =
                              Offset(_offset.dx, _offset.dy + actualDelta);
                          _userH = newH;
                        });
                      },
                      child: const SizedBox.expand(),
                    ),
                  ),
                ),
                // ── 右下のリサイズハンドル (= ユーザー要望: 境界をドラッグ
                //    することで大きさを調整できるように) ──
                // 半透明の小さなつまみ。 ドラッグで _userW / _userH を更新し、
                //   ビルトインのデフォルトサイズを上書きする。
                Positioned(
                  right: 0,
                  bottom: 0,
                  child: MouseRegion(
                    cursor: SystemMouseCursors.resizeDownRight,
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onPanUpdate: (d) {
                        setState(() {
                          final newW = panelW + d.delta.dx;
                          final newH = panelH + d.delta.dy;
                          _userW = newW.clamp(260.0, maxW);
                          _userH = newH.clamp(280.0, maxH);
                        });
                      },
                      child: Container(
                        width: 18,
                        height: 18,
                        alignment: Alignment.bottomRight,
                        padding: const EdgeInsets.only(right: 2, bottom: 2),
                        decoration: BoxDecoration(
                          color:
                              const Color(0xFF4FC3F7).withValues(alpha: 0.35),
                          borderRadius: const BorderRadius.only(
                            bottomRight: Radius.circular(13),
                            topLeft: Radius.circular(6),
                          ),
                        ),
                        child: const Icon(
                          Icons.south_east_rounded,
                          color: Colors.white,
                          size: 12,
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

/// Windows 専用: フローティング Google 検索の WebView 部分。
/// フローティング AI パネル (= ユーザー要望: モデルを切り替えるボタン付き)。
/// 上部に AI サービス (ChatGPT / Gemini / Perplexity / Claude / Grok /
/// DeepSeek) の切替バーを出し、 下に WebView を表示する。 切替は provider の
/// browserAiTarget にも保存され、 次回以降の AI ボタンにも反映される。
class _FloatingAiSwitcherPanel extends StatefulWidget {
  final String query;
  const _FloatingAiSwitcherPanel({this.query = ''});
  @override
  State<_FloatingAiSwitcherPanel> createState() =>
      _FloatingAiSwitcherPanelState();
}

class _FloatingAiSwitcherPanelState extends State<_FloatingAiSwitcherPanel> {
  late String _targetId;

  /// サービス名の並びを隠しているか (= ユーザー要望: 名前が気になるので
  /// しまえるように)。 隠している間も切替アイコンだけは残す。
  /// 次に開いた時も同じ状態にする。
  bool _barHidden = false;
  static const String _barPrefsKey = 'floatingAiBarHidden';

  @override
  void initState() {
    super.initState();
    _targetId = context.read<MindMapProvider>().browserAiTarget;
    unawaited(_loadBarHidden());
  }

  Future<void> _loadBarHidden() async {
    try {
      final sp = await SharedPreferences.getInstance();
      final v = sp.getBool(_barPrefsKey) ?? false;
      if (mounted && v != _barHidden) setState(() => _barHidden = v);
    } catch (_) {}
  }

  Future<void> _toggleBar() async {
    final next = !_barHidden;
    setState(() => _barHidden = next);
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.setBool(_barPrefsKey, next);
    } catch (_) {}
  }

  String get _url {
    final def = MindMapProvider.browserAiTargets.firstWhere(
      (e) => e['id'] == _targetId,
      orElse: () => MindMapProvider.browserAiTargets.first,
    );
    final tmpl = def['url'] ?? 'https://chatgpt.com/';
    final q = widget.query;
    return q.isEmpty
        ? tmpl.replaceAll('{q}', '')
        : tmpl.replaceAll('{q}', Uri.encodeComponent(q));
  }

  @override
  Widget build(BuildContext context) {
    final provider = context.read<MindMapProvider>();
    return Column(children: [
      // ── モデル切替バー ──
      Container(
        height: 34,
        color: const Color(0xFF23233A),
        padding: const EdgeInsets.symmetric(horizontal: 6),
        child: Row(children: [
          // サービス名の並びを開閉するボタン (= ユーザー要望)。
          InkWell(
            borderRadius: BorderRadius.circular(6),
            onTap: _toggleBar,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 4),
              child: Icon(
                  _barHidden
                      ? Icons.chevron_right_rounded
                      : Icons.chevron_left_rounded,
                  color: Colors.white54,
                  size: 16),
            ),
          ),
          // 隠している時は AI のマークと今のサービス名も出さない
          //   (= ユーザー要望)。 戻すための「>」 だけ残す。
          if (!_barHidden) ...[
            const Icon(Icons.smart_toy_rounded,
                color: Color(0xFF4FC3F7), size: 14),
            const SizedBox(width: 6),
          ],
          if (_barHidden)
            const Spacer()
          else
          Expanded(
            child: SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              child: Row(children: [
                for (final t in MindMapProvider.browserAiTargets)
                  Padding(
                    padding: const EdgeInsets.only(right: 4),
                    child: InkWell(
                      borderRadius: BorderRadius.circular(6),
                      onTap: () {
                        final id = t['id'] ?? '';
                        if (id.isEmpty || _targetId == id) return;
                        setState(() => _targetId = id);
                        // アプリ全体の既定 AI にも反映する。
                        unawaited(provider.setBrowserAiTarget(id));
                      },
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 8, vertical: 4),
                        decoration: BoxDecoration(
                          color: _targetId == t['id']
                              ? const Color(0xFF4FC3F7)
                                  .withValues(alpha: 0.25)
                              : Colors.transparent,
                          borderRadius: BorderRadius.circular(6),
                        ),
                        child: Text(t['label'] ?? '',
                            style: TextStyle(
                                color: _targetId == t['id']
                                    ? const Color(0xFF4FC3F7)
                                    : Colors.white60,
                                fontSize: 11,
                                fontWeight: FontWeight.w700)),
                      ),
                    ),
                  ),
              ]),
            ),
          ),
        ]),
      ),
      Expanded(
        child: _WinGoogleSearchView(
          key: ValueKey('floating_ai_$_targetId'),
          url: _url,
        ),
      ),
    ]);
  }
}

class _WinGoogleSearchView extends StatefulWidget {
  final String url;

  /// 初期化完了時に webview_windows のコントローラを親へ渡すコールバック。
  /// 親 (= ドックペイン) が戻る/進むを呼べるようにするため (= ユーザー要望)。
  /// ★ デスクトップでしか呼ばれない (モバイルは別のエンジンを使う)。
  final void Function(wv_win.WebviewController controller)? onController;

  /// WebView をどうしても作れなかった時に呼ばれる (= ユーザー報告:
  /// フローティングで YouTube を開くと「WebView を初期化できませんでした」)。
  /// これがある時は自分では外の窓を開かず、 親 (浮遊窓) に任せる。
  /// 親は同じ位置・大きさで外の窓を開き、 自分は閉じる。
  final VoidCallback? onInitFailed;

  /// 表示中の URL が変わるたびに呼ばれる (デスクトップ / モバイル共通)。
  /// 浮遊窓から分割セルへ埋め込む時に「今見ているページ」 を渡すために使う。
  final void Function(String url)? onUrlChanged;
  const _WinGoogleSearchView(
      {super.key,
      required this.url,
      this.onController,
      this.onUrlChanged,
      this.onInitFailed});
  @override
  State<_WinGoogleSearchView> createState() => _WinGoogleSearchViewState();
}

/// カスタムスキーム (kindle:// 等) で外部アプリが起動するのを防ぐ JS。
/// document start で流し込む。 ASIN が拾えれば Kindle Web リーダーへ誘導する。
const String _kBlockExternalAppJs = r"""
(function(){
  if (window.__MM_NO_EXTERNAL_APP__) return;
  window.__MM_NO_EXTERNAL_APP__ = true;
  var BAD = /^(kindle|amzn|com-amazon|ms-windows-store|itms-apps|market):/i;
  function webFallback(href){
    try {
      var m = /asin=([A-Za-z0-9]+)/i.exec(href);
      if (m) { return 'https://read.amazon.co.jp/?asin=' + m[1]; }
    } catch(e){}
    return null;
  }
  document.addEventListener('click', function(ev){
    try {
      var a = ev.target && ev.target.closest ? ev.target.closest('a') : null;
      if (!a || !a.href) { return; }
      if (!BAD.test(a.href)) { return; }
      ev.preventDefault();
      ev.stopPropagation();
      var alt = webFallback(a.href);
      if (alt) { window.location.href = alt; }
    } catch(e){}
  }, true);
  try {
    var open0 = window.open;
    window.open = function(u){
      if (u && BAD.test(String(u))) {
        var alt = webFallback(String(u));
        if (alt) { window.location.href = alt; }
        return null;
      }
      return open0.apply(window, arguments);
    };
  } catch(e){}
})();
""";

class _WinGoogleSearchViewState extends State<_WinGoogleSearchView> {
  /// 生きている WebView の一覧 (= ユーザー報告: 分割セルや浮遊窓で AI を
  /// 開いた時に画像が渡らない。 旧実装は左右分割パネルにしか注入できな
  /// かったので、 どこで開いていても届くよう共通の登録簿を持つ)。
  static final Set<_WinGoogleSearchViewState> liveViews =
      <_WinGoogleSearchViewState>{};

  /// 現在 URL (外から参照する)。
  String get currentUrl => _cur.isEmpty ? widget.url : _cur;

  /// モバイル (Android / iOS) かどうか。
  /// ★ webview_windows はモバイルで初期化できず、 そのままだと
  ///   「WebView を初期化できませんでした」 の灰色画面になる
  ///   (= ユーザー報告: 分割画面で要素から YouTube を押した時)。
  ///   この widget はアプリ中のあちこちから使われるので、 使う側ごとに
  ///   分岐させず、 ここで flutter_inappwebview に切り替える。
  static bool get _isMobile =>
      !kIsWeb && (Platform.isAndroid || Platform.isIOS);

  /// JS を流す (未初期化なら無視)。
  Future<void> execJs(String js) async {
    if (_isMobile) {
      try {
        await _iawCtrl?.evaluateJavascript(source: js);
      } catch (_) {}
      return;
    }
    if (!_ready || Platform.isLinux) return;
    try {
      await _ctrl.executeScript(js);
    } catch (_) {}
  }

  /// 音楽サイトなら「裏に回っても止めない」 JS を流す (= ユーザー要望:
  /// SoundCloud / Spotify 等のバックグラウンド再生)。 設定が OFF なら何も
  /// しない。 対象サイト以外にも流さない (普通のページの挙動は変えない)。
  void _applyWebAudioKeepAlive(String url) {
    if (!mounted) return;
    try {
      final p = context.read<MindMapProvider>();
      if (!p.webAudioBackground) return;
      if (!MindMapProvider.isBackgroundAudioSite(url)) return;
      // Spotify / YouTube は仕組み上うまくいかないので流さない
      // (= ユーザー要望: 問題があるサイトではできないように)。
      if (MindMapProvider.isBackgroundAudioBlockedSite(url)) return;
      // 読み込み直後は要素が揃っていないことがあるので少し置いて流す。
      Future.delayed(const Duration(milliseconds: 600), () {
        if (mounted) execJs(_kWebAudioKeepAliveJs);
      });
    } catch (_) {}
  }

  // ★ final にしない: 一度初期化に失敗した controller は壊れたままの
  //   ことがあり、 同じ物で何回やり直しても失敗し続ける (= ユーザー報告:
  //   分割中に要素から YouTube を開くと「初期化できませんでした」)。
  //   やり直す時は作り直す。
  wv_win.WebviewController _ctrl = wv_win.WebviewController();

  /// モバイル側のコントローラ (= flutter_inappwebview)。
  iaw.InAppWebViewController? _iawCtrl;
  bool _ready = false;
  bool _failed = false;

  @override
  void initState() {
    super.initState();
    liveViews.add(this);
    _init();
  }

  /// 現在 URL (検索結果がホームへ丸められた時の検知に使う)。
  String _cur = '';
  StreamSubscription<String>? _urlSub;
  Timer? _resultsGuard;
  bool _retried = false;

  /// 検索結果ページを開くつもりの URL か。
  bool get _wantsResults => widget.url.contains('/results?');

  /// YouTube が検索結果でなくホームに着地した時、 検索結果 URL を
  /// もう一度読み込む (= ユーザー報告: 検索結果ではなくホーム画面が開く)。
  void _retryResultsIfHome() {
    if (_retried || !_wantsResults || !mounted) return;
    final u = Uri.tryParse(_cur);
    final onResults = _cur.contains('/results');
    final onYoutube = u != null && u.host.endsWith('youtube.com');
    if (onResults) return;
    if (_cur.isNotEmpty && !onYoutube) return; // 別サイトへ遷移済みなら触らない
    _retried = true;
    try {
      _ctrl.loadUrl(widget.url);
    } catch (_) {}
  }

  /// 初期化に失敗した時のエラー内容 (画面に小さく出して原因調査に使う)。
  String _failMsg = '';

  /// 初期化のやり直し回数 (= ユーザー報告: 埋め込みを窓に戻すと
  /// 「WebView を初期化できませんでした」 と出る)。 直前まで別の WebView が
  /// 生きていると、 その片付けと重なって最初の初期化だけ失敗することがある。
  /// 少し待って一度だけやり直せば大抵うまくいく。
  int _initAttempt = 0;

  Future<void> _init() async {
    // Linux: webview_windows 非対応 → CEF (build 側の LinuxWebViewWidget) で
    //   表示する。 wv_win コントローラは初期化しない (呼ぶと例外)。
    if (Platform.isLinux) return;
    // モバイル: build 側で InAppWebView を出す。 ここでは何もしない。
    if (_isMobile) return;
    try {
      await _ctrl.initialize();
      // ── 外部アプリの起動を止める (= ユーザー報告: 分割画面で Kindle の
      //    書籍を開くと PC の Kindle アプリが立ち上がってしまう) ──
      //    Amazon 等のページには `kindle://` `amzn://` `ms-windows-store://`
      //    といったカスタムスキームのリンクがあり、 WebView2 は既定で OS に
      //    渡してしまう。 クリックと window.open を横取りして、 可能なら
      //    Web 版 (read.amazon) の URL に読み替えてアプリ内で開く。
      try {
        await _ctrl.addScriptToExecuteOnDocumentCreated(_kBlockExternalAppJs);
      } catch (_) {}
      // ── 位置情報を渡す (= ユーザー報告: Google マップ / Earth で現在地が
      //    表示されない)。 WebView2 は Windows の位置情報プロバイダに繋がって
      //    いないことが多く navigator.geolocation が応答しないので、 IP から
      //    求めたおおよその座標を差し込む。 ──
      try {
        final prov = context.read<MindMapProvider>();
        await prov.ensureApproxLocation();
        final geoJs = prov.geolocationShimJs();
        if (geoJs != null) {
          await _ctrl.addScriptToExecuteOnDocumentCreated(geoJs);
        }
      } catch (_) {}
      // 親に渡して戻る/進む操作を可能にする (loadUrl より先に渡して、
      // 最初のナビゲーションも親が拾えるようにする)。
      widget.onController?.call(_ctrl);
      _urlSub = _ctrl.url.listen((u) {
        if (u.isEmpty) return;
        _cur = u;
        widget.onUrlChanged?.call(u);
        _applyWebAudioKeepAlive(u);
        // 検索結果を開いたはずがホームに丸められたら一度だけ再読込。
        final uu = Uri.tryParse(u);
        if (_wantsResults &&
            uu != null &&
            uu.host.endsWith('youtube.com') &&
            (uu.path.isEmpty || uu.path == '/')) {
          _retryResultsIfHome();
        }
      });
      await _ctrl.loadUrl(widget.url);
      // ナビゲーションイベントを取り逃した場合の保険。
      if (_wantsResults) {
        _resultsGuard = Timer(const Duration(milliseconds: 2200),
            () => _retryResultsIfHome());
      }
      if (mounted) setState(() => _ready = true);
    } catch (e) {
      if (!mounted) return;
      // 直前の WebView の片付けと重なった時は、 少し置いてやり直す。
      // ★ 失敗した controller は捨てて作り直す (= 同じ物での再挑戦は
      //   失敗し続けることがある)。 回数も 2 → 4 に増やし、 間隔を
      //   だんだん延ばす。
      if (_initAttempt < 4) {
        _initAttempt++;
        debugPrint('WebView の初期化に失敗、 やり直します ($_initAttempt): $e');
        try {
          _ctrl.dispose();
        } catch (_) {}
        _ctrl = wv_win.WebviewController();
        await Future<void>.delayed(
            Duration(milliseconds: 450 * _initAttempt));
        if (!mounted) return;
        return _init();
      }
      // ── 親が引き継げるならそちらに任せる (= 浮遊窓は同じ位置・大きさで
      //    外の窓になり、 灰色の画面は残さない) ──
      if (widget.onInitFailed != null) {
        _failMsg = '$e';
        if (mounted) setState(() => _failed = true);
        widget.onInitFailed!();
        return;
      }
      // ── 全部失敗したら「外の窓」 で開いて助ける ──
      // = ユーザー報告「未だに分割画面で要素から YouTube を開くと WebView を
      //   初期化できませんでしたと出る」「外部に出すと正しく表示される」。
      // アプリ内で作れなかった時に灰色の画面だけ残すより、 別プロセスの窓
      // (= WebView2 の後始末が独立するので確実に開ける) で開いてしまう。
      // 1 回だけ。 ふつうの Web ページ以外 (ローカル動画等) は対象外。
      final u = currentUrl;
      if (!_poppedOutOnFailure &&
          (u.startsWith('http://') || u.startsWith('https://'))) {
        _poppedOutOnFailure = openExternalWebWindow(u);
      }
      // 原因調査のため、 何のエラーかを画面に出す (= ユーザー報告が続く)。
      _failMsg = '$e';
      setState(() => _failed = true);
    }
  }

  /// 初期化に全部失敗して「外の窓」 で開き直したか (= 二重に開かない)。
  bool _poppedOutOnFailure = false;

  @override
  void dispose() {
    liveViews.remove(this);
    _resultsGuard?.cancel();
    _urlSub?.cancel();
    // モバイルでは初期化していないので dispose も呼ばない。
    // ── 音が鳴り続ける対策 (= ユーザー報告: 画面を閉じても YouTube の
    //    音声が流れ続けることがある)。 about:blank でページごと止めてから
    //    次のイベントループで破棄する。 ──
    if (!Platform.isLinux && !_isMobile) {
      final ctrl = _ctrl;
      Future(() async {
        try {
          await ctrl.loadUrl('about:blank');
        } catch (_) {}
        try {
          await ctrl.dispose();
        } catch (_) {}
      });
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    // Linux: CEF (LinuxWebViewWidget) で表示 (webview_windows 非対応)。
    //   JS→Dart チャンネルが無いためメモ注入等は縮退するが、 検索/閲覧は可能。
    if (Platform.isLinux) {
      return linux_wv.LinuxWebViewWidget(url: widget.url);
    }
    // モバイル: flutter_inappwebview で表示する (アプリ全体の使い分けと同じ)。
    //   これが無いと webview_windows の初期化に失敗して灰色の
    //   「WebView を初期化できませんでした」 だけが出ていた。
    if (_isMobile) {
      return iaw.InAppWebView(
        initialUrlRequest: iaw.URLRequest(url: iaw.WebUri(widget.url)),
        initialSettings: iaw.InAppWebViewSettings(
          javaScriptEnabled: true,
          domStorageEnabled: true,
          useHybridComposition: true,
          mediaPlaybackRequiresUserGesture: false,
          allowsInlineMediaPlayback: true,
          transparentBackground: false,
          mixedContentMode: iaw.MixedContentMode.MIXED_CONTENT_COMPATIBILITY_MODE,
        ),
        onWebViewCreated: (c) => _iawCtrl = c,
        onLoadStop: (c, url) {
          if (url == null) return;
          _cur = url.toString();
          widget.onUrlChanged?.call(_cur);
          _applyWebAudioKeepAlive(_cur);
        },
        // YouTube 等の SPA は onLoadStop が走らないので history でも拾う。
        onUpdateVisitedHistory: (c, url, _) {
          if (url == null) return;
          _cur = url.toString();
          widget.onUrlChanged?.call(_cur);
          _applyWebAudioKeepAlive(_cur);
        },
      );
    }
    if (_failed) {
      return Container(
        color: const Color(0xFF1E1E32),
        alignment: Alignment.center,
        padding: const EdgeInsets.all(16),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          const Text(
            'WebView を初期化できませんでした',
            style: TextStyle(color: Colors.white60, fontSize: 12),
            textAlign: TextAlign.center,
          ),
          // 自動で外の窓に逃がした時は、 どこへ行ったのかを知らせる。
          if (_poppedOutOnFailure) ...[
            const SizedBox(height: 6),
            const Text(
              '外部の窓で開き直しました',
              style: TextStyle(color: Color(0xFFFFB347), fontSize: 11),
              textAlign: TextAlign.center,
            ),
          ],
          if (_failMsg.isNotEmpty) ...[
            const SizedBox(height: 6),
            // 原因調査用にエラー内容も小さく出す。
            SelectableText(
              _failMsg.length > 220
                  ? '${_failMsg.substring(0, 220)}…'
                  : _failMsg,
              style: const TextStyle(color: Colors.white30, fontSize: 9.5),
              textAlign: TextAlign.center,
            ),
          ],
          const SizedBox(height: 10),
          Row(mainAxisSize: MainAxisSize.min, children: [
            // 手でやり直せる口を残す (= 全滅した時の救済)。
            OutlinedButton.icon(
              style: OutlinedButton.styleFrom(
                  side: const BorderSide(color: Colors.white24)),
              icon: const Icon(Icons.refresh_rounded,
                  size: 15, color: Color(0xFF4FC3F7)),
              label: const Text('再試行',
                  style: TextStyle(color: Color(0xFF4FC3F7), fontSize: 12)),
              onPressed: () {
                setState(() {
                  _failed = false;
                  _initAttempt = 0;
                });
                try {
                  _ctrl.dispose();
                } catch (_) {}
                _ctrl = wv_win.WebviewController();
                // ignore: discarded_futures
                _init();
              },
            ),
            const SizedBox(width: 8),
            // アプリ内で開けない時の逃げ道 (= ユーザー報告: 外部に出すと
            // 正しく表示される)。 外の本物の窓で開き直す。
            OutlinedButton.icon(
              style: OutlinedButton.styleFrom(
                  side: const BorderSide(color: Colors.white24)),
              icon: const Icon(Icons.open_in_new_rounded,
                  size: 15, color: Color(0xFFFFB347)),
              label: const Text('外部の窓で開く',
                  style: TextStyle(color: Color(0xFFFFB347), fontSize: 12)),
              onPressed: () => openExternalWebWindow(currentUrl),
            ),
          ]),
        ]),
      );
    }
    if (!_ready) {
      return Container(
        color: const Color(0xFF1E1E32),
        alignment: Alignment.center,
        child: const SizedBox(
          width: 28,
          height: 28,
          child: CircularProgressIndicator(
            strokeWidth: 2.5,
            valueColor: AlwaysStoppedAnimation<Color>(Color(0xFF4FC3F7)),
          ),
        ),
      );
    }
    // ── タッチパッドのピンチイン / アウトを WebView へ中継する
    //    (= ユーザー要望: Google マップや Earth をピンチで拡大縮小したい)。
    //    webview_windows はズーム API を持たず、 プラグイン側の Listener も
    //    ホイールしか転送しないため、 ここでトラックパッドのスケール値を
    //    受けて JS の wheel イベントとしてページへ流し込む。 ──
    return Listener(
      behavior: HitTestBehavior.translucent,
      onPointerPanZoomStart: (e) {
        _pinchScale = 1.0;
        _pinchPos = e.localPosition;
      },
      onPointerPanZoomUpdate: (e) {
        _pinchPos = e.localPosition;
        _handlePinch(e.scale);
      },
      onPointerPanZoomEnd: (_) => _pinchScale = 1.0,
      onPointerSignal: (s) {
        // macOS / 一部環境ではピンチが PointerScaleEvent で届く。
        if (s is PointerScaleEvent) {
          _pinchPos = s.localPosition;
          _handlePinch(s.scale);
        }
      },
      child: wv_win.Webview(
        _ctrl,
        permissionRequested: (url, kind, isUserInitiated) async =>
            wv_win.WebviewPermissionDecision.allow,
      ),
    );
  }

  // ── ピンチ操作の状態 ──
  double _pinchScale = 1.0;
  Offset _pinchPos = Offset.zero;
  DateTime _lastPinchSend = DateTime.fromMillisecondsSinceEpoch(0);

  /// 直前に送った倍率からの変化が一定を超えたら、 その位置で wheel イベントを
  /// 発火させる (地図系サイトはホイールで拡大縮小する)。
  void _handlePinch(double scale) {
    if (scale <= 0 || !_ready || Platform.isLinux) return;
    final ratio = scale / _pinchScale;
    // 連打しすぎるとサイト側が追従できないので間隔も見る。
    final now = DateTime.now();
    if (now.difference(_lastPinchSend).inMilliseconds < 60) return;
    if (ratio > 1.06) {
      _pinchScale = scale;
      _lastPinchSend = now;
      _sendWheelToPage(-120);
    } else if (ratio < 0.94) {
      _pinchScale = scale;
      _lastPinchSend = now;
      _sendWheelToPage(120);
    }
  }

  /// ページのポインタ位置に wheel イベントを送る (deltaY<0 = 拡大)。
  Future<void> _sendWheelToPage(double deltaY) async {
    final x = _pinchPos.dx.round();
    final y = _pinchPos.dy.round();
    final js = '(function(){'
        'var el=document.elementFromPoint($x,$y)||document.body;'
        'var o={deltaY:$deltaY,deltaMode:0,clientX:$x,clientY:$y,'
        'bubbles:true,cancelable:true,composed:true};'
        'el.dispatchEvent(new WheelEvent("wheel",o));'
        '})();';
    try {
      await _ctrl.executeScript(js);
    } catch (_) {}
  }
}

/// サイドバーにドックされた Google 検索ペイン。
/// `_PdfMemoPanelState` の build が ValueNotifier で監視し、 ドック中は
/// メモ UI を完全に置き換えてここを縦全部に広げる。
class _DockedGoogleSearchPane extends StatefulWidget {
  final _DockedGoogleSearchState state;
  const _DockedGoogleSearchPane({required this.state});

  @override
  State<_DockedGoogleSearchPane> createState() =>
      _DockedGoogleSearchPaneState();
}

class _DockedGoogleSearchPaneState extends State<_DockedGoogleSearchPane> {
  // ── 戻る/進む用の WebView コントローラ参照 (= ユーザー要望: メモ欄から
  //    サイトを開いた時にリンクへ飛んでも戻れるよう遷移ボタンを追加) ──
  iaw.InAppWebViewController? _iawCtrl; // モバイル
  wv_win.WebviewController? _winCtrl; // デスクトップ

  bool get _isDesktop =>
      Theme.of(context).platform == TargetPlatform.windows ||
      Theme.of(context).platform == TargetPlatform.macOS ||
      Theme.of(context).platform == TargetPlatform.linux;

  Future<void> _goBack() async {
    try {
      if (_isDesktop) {
        await _winCtrl?.goBack();
      } else {
        await _iawCtrl?.goBack();
      }
    } catch (_) {}
  }

  Future<void> _goForward() async {
    try {
      if (_isDesktop) {
        await _winCtrl?.goForward();
      } else {
        await _iawCtrl?.goForward();
      }
    } catch (_) {}
  }

  Future<void> _reload() async {
    try {
      if (_isDesktop) {
        await _winCtrl?.reload();
      } else {
        await _iawCtrl?.reload();
      }
    } catch (_) {}
  }

  @override
  Widget build(BuildContext context) {
    final isDesktop = _isDesktop;
    final state = widget.state;
    return Container(
      decoration: const BoxDecoration(
        color: Color(0xFF1A1A24),
      ),
      child: Column(
        children: [
          Container(
            height: 32,
            padding: const EdgeInsets.symmetric(horizontal: 4),
            decoration: BoxDecoration(
              color: Colors.white.withValues(alpha: 0.04),
              border: const Border(
                bottom: BorderSide(color: Colors.white12, width: 1),
              ),
            ),
            child: Row(children: [
              // ── 戻る / 進む / 再読み込み (= ユーザー要望の遷移ボタン) ──
              InkWell(
                onTap: _goBack,
                borderRadius: BorderRadius.circular(4),
                child: Padding(
                  padding: EdgeInsets.all(4),
                  child: Tooltip(
                    message: context.read<MindMapProvider>().t('btn.back'),
                    child: Icon(Icons.arrow_back_rounded,
                        color: Colors.white70, size: 16),
                  ),
                ),
              ),
              InkWell(
                onTap: _goForward,
                borderRadius: BorderRadius.circular(4),
                child: Padding(
                  padding: EdgeInsets.all(4),
                  child: Tooltip(
                    message: context.read<MindMapProvider>().t('split.forward'),
                    child: Icon(Icons.arrow_forward_rounded,
                        color: Colors.white70, size: 16),
                  ),
                ),
              ),
              InkWell(
                onTap: _reload,
                borderRadius: BorderRadius.circular(4),
                child: Padding(
                  padding: EdgeInsets.all(4),
                  child: Tooltip(
                    message: context.read<MindMapProvider>().t('player.reload'),
                    child: Icon(Icons.refresh_rounded,
                        color: Colors.white70, size: 16),
                  ),
                ),
              ),
              const SizedBox(width: 4),
              const Icon(Icons.travel_explore_rounded,
                  color: Colors.white54, size: 16),
              const SizedBox(width: 6),
              Expanded(
                child: Text(
                  state.query,
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 12,
                      fontWeight: FontWeight.w600),
                  overflow: TextOverflow.ellipsis,
                  maxLines: 1,
                ),
              ),
              // ── 音楽サイトのバックグラウンド再生 (= ユーザー要望: 動作設定
              //    ではなく、 開いた項目のヘッダーで切り替える) ──
              //    音楽サイトを開いている時だけ出す。 Spotify / YouTube は
              //    仕組み上うまくいかないので、 押せない印だけ出す。
              if (MindMapProvider.isBackgroundAudioSite(state.url))
                Builder(builder: (ctx) {
                  final p = ctx.watch<MindMapProvider>();
                  final blocked =
                      MindMapProvider.isBackgroundAudioBlockedSite(state.url);
                  final on = p.webAudioBackground && !blocked;
                  return InkWell(
                    onTap: blocked
                        ? null
                        : () => p.setWebAudioBackground(!p.webAudioBackground),
                    borderRadius: BorderRadius.circular(4),
                    child: Padding(
                      padding: const EdgeInsets.all(4),
                      child: Tooltip(
                        message: blocked
                            ? p.t('bgAudio.blocked')
                            : p.t(on ? 'bgAudio.on' : 'bgAudio.off'),
                        child: Icon(
                          blocked
                              ? Icons.music_off_rounded
                              : (on
                                  ? Icons.music_note_rounded
                                  : Icons.music_off_rounded),
                          color: blocked
                              ? Colors.white24
                              : (on
                                  ? const Color(0xFF66BB6A)
                                  : Colors.white60),
                          size: 14,
                        ),
                      ),
                    ),
                  );
                }),
              InkWell(
                onTap: () {
                  final q = state.query;
                  _dockedGoogleSearchNotifier.value = null;
                  _openFloatingGoogleSearch(context, q);
                },
                borderRadius: BorderRadius.circular(4),
                child: Padding(
                  padding: EdgeInsets.all(4),
                  child: Tooltip(
                    message: context.read<MindMapProvider>().t('gs.toFloating'),
                    child: Icon(Icons.open_in_new_rounded,
                        color: Colors.white60, size: 14),
                  ),
                ),
              ),
              InkWell(
                onTap: () {
                  _dockedGoogleSearchNotifier.value = null;
                },
                borderRadius: BorderRadius.circular(4),
                child: Padding(
                  padding: EdgeInsets.all(4),
                  child: Tooltip(
                    message:
                        context.read<MindMapProvider>().t('search.closeSearch'),
                    child: Icon(Icons.close, color: Colors.white60, size: 14),
                  ),
                ),
              ),
            ]),
          ),
          Expanded(
            child: isDesktop
                ? _WinGoogleSearchView(
                    url: state.url,
                    onController: (c) => _winCtrl = c,
                  )
                : iaw.InAppWebView(
                    initialUrlRequest:
                        iaw.URLRequest(url: iaw.WebUri(state.url)),
                    initialSettings: iaw.InAppWebViewSettings(
                      javaScriptEnabled: true,
                      transparentBackground: false,
                      useShouldOverrideUrlLoading: false,
                    ),
                    onWebViewCreated: (c) => _iawCtrl = c,
                  ),
          ),
        ],
      ),
    );
  }
}

final ValueNotifier<bool> _bottomToolbarExpandedNotifier =
    ValueNotifier<bool>(true);

double _snackBarBottomClearance(BuildContext context) {
  final safeBottom = MediaQuery.maybeOf(context)?.padding.bottom ?? 0.0;
  // メッセージはボタンバーより画面下端側へ表示する。重なりそうな時は
  // メッセージを上へ逃がさず、表示中だけボタンバーを持ち上げる。
  return safeBottom + 12.0;
}

/// 通知 (SnackBar) を浮かせる余白を返す。 モバイル下部バーの上に出しつつ、
/// デスクトップで左右 / 下にドックしたカスタムボタンバーとも重ならないよう
/// 内側へ寄せる (= ユーザー要望: 左右にバーを置くとメッセージがバーの下に
/// 潜って読めない → バーを避けた位置に出す)。
EdgeInsets _snackBarFloatingMargin(BuildContext context) {
  double left = 12.0;
  double right = 12.0;
  double bottom = _snackBarBottomClearance(context);
  final isDesktop =
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
  if (isDesktop) {
    try {
      final p = context.read<MindMapProvider>();
      // 左右ドック (幅 60 + 端 10) を避けて内側へ寄せる。
      if (p.desktopHeaderButtonsForPlacement('left').isNotEmpty) {
        left = 84.0;
      }
      if (p.desktopHeaderButtonsForPlacement('right').isNotEmpty) {
        right = 84.0;
      }
      // ── 下部バーの「実際の位置」 の上へメッセージを出す ──
      // (= ユーザー要望: 下部のバーを動かすとメッセージと被ってしまう時が
      //  あるので、 メッセージ自体がバーより上に出るように)。
      // 旧: 一律 +84px だったため、 バーを自由配置で上へ動かすと被った。
      if (p.desktopHeaderButtonsForPlacement('bottom').isNotEmpty) {
        final screenH = MediaQuery.sizeOf(context).height;
        final collapsed = p.desktopHeaderDockCollapsedAt('bottom');
        final dockH = collapsed ? 46.0 : 66.0;
        final double barTop;
        if (p.desktopBottomDockFloating) {
          barTop = p.desktopBottomDockY * screenH - dockH / 2;
        } else {
          barTop = screenH - dockH - (p.desktopBottomDockEmbedded ? 0.0 : 12.0);
        }
        // バー上端 + 10px の余白。 バーを画面上部まで動かした場合に
        // メッセージが画面外へ飛ばないよう、 画面の 60% までに制限する。
        final needed =
            (screenH - barTop + 10.0).clamp(0.0, screenH * 0.6).toDouble();
        if (needed > bottom) bottom = needed;
      }
    } catch (_) {}
  }
  return EdgeInsets.fromLTRB(left, 0, right, bottom);
}

int _appSnackGeneration = 0;

/// メイン画面の Scaffold (ドロワーが開いているかを見るため)。
/// _MindMapScreenState.initState が設定する。
GlobalKey<ScaffoldState>? appMainScaffoldKey;

/// ドロワーより手前に出すメッセージの写し (= ユーザー要望: 下部の
/// メッセージがサイドメニューの上に表示されるように)。
///
/// SnackBar は Scaffold の中に描かれるため、 ドロワー (サイドメニュー) が
/// 開いていると後ろに隠れて読めない。 ドロワーが開いている間だけ、 同じ
/// 見た目の帯をルートの Overlay (= 何よりも手前) に重ねて出す。 本物の
/// SnackBar もそのまま出しているので、 戻り値やアクションの動きは従来通り。
OverlayEntry? _drawerSnackEntry;
Timer? _drawerSnackTimer;
void _showSnackAboveDrawer(BuildContext ctx, SnackBar patched) {
  final scaffold = appMainScaffoldKey?.currentState;
  if (scaffold == null || !scaffold.isDrawerOpen) return;
  final overlay = Overlay.maybeOf(ctx, rootOverlay: true);
  if (overlay == null) return;
  _drawerSnackTimer?.cancel();
  try {
    _drawerSnackEntry?.remove();
  } catch (_) {}
  final entry = OverlayEntry(
    builder: (_) => Positioned(
      left: 12,
      right: 12,
      bottom: 20,
      child: Material(
        color: Colors.transparent,
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
          decoration: BoxDecoration(
            color: patched.backgroundColor ?? const Color(0xFF2A2A3E),
            borderRadius: BorderRadius.circular(6),
            boxShadow: const [
              BoxShadow(color: Colors.black54, blurRadius: 10),
            ],
          ),
          child: Row(children: [
            Expanded(child: _readableSnackContent(patched.content)),
            if (patched.action != null)
              TextButton(
                onPressed: () {
                  patched.action!.onPressed();
                  _drawerSnackTimer?.cancel();
                  try {
                    _drawerSnackEntry?.remove();
                  } catch (_) {}
                  _drawerSnackEntry = null;
                },
                child: Text(patched.action!.label,
                    style: TextStyle(
                        color:
                            patched.action!.textColor ?? Colors.white)),
              ),
          ]),
        ),
      ),
    ),
  );
  _drawerSnackEntry = entry;
  overlay.insert(entry);
  _drawerSnackTimer = Timer(patched.duration, () {
    if (_drawerSnackEntry != entry) return;
    try {
      entry.remove();
    } catch (_) {}
    _drawerSnackEntry = null;
  });
}

ScaffoldFeatureController<SnackBar, SnackBarClosedReason>? _appSnack(
  BuildContext ctx,
  SnackBar bar, {
  bool processing = false,
}) {
  final messenger = ScaffoldMessenger.of(ctx);
  final generation = ++_appSnackGeneration;
  MindMapProvider? provider;
  messenger.hideCurrentSnackBar();
  final patched = _patchSnackBarDuration(ctx, bar, processing: processing);
  // ── ドロワーが開いている間は、 手前の写しだけを出す (= ユーザー報告:
  //    上下に二重で表示される)。 本物の SnackBar はドロワーの後ろに
  //    隠れる位置に出るので、 この間は出さない。 ──
  if (appMainScaffoldKey?.currentState?.isDrawerOpen == true) {
    _showSnackAboveDrawer(ctx, patched);
    return null;
  }
  try {
    provider = ctx.read<MindMapProvider>();
    provider.setBottomBarLifted(true);
  } catch (_) {}
  final controller = messenger.showSnackBar(patched);
  controller.closed.whenComplete(() {
    if (_appSnackGeneration != generation) return;
    try {
      provider?.setBottomBarLifted(false);
    } catch (_) {}
  });
  return controller;
}

/// SnackBar の duration / 表示位置を要件に従って調整するヘルパ。
///
/// duration:
///   - processing == true → そのまま尊重 (進行中の処理を表示し続ける)
///   - 元の duration が 30 秒以上 → そのまま尊重 (= 長時間処理用と判断)
///   - それ以外で 4 秒超 → 4 秒に短縮 (= 通常通知をだらだら出さない)
///
/// 表示位置:
///   - behavior が未指定なら `SnackBarBehavior.floating` を強制
///   - margin が未指定なら 「下のボタンと重ならない」高さ + 横余白を付ける
///     (= モバイル下部バーの上に浮かせる) これにより SnackBar が下部 UI
///     を覆って操作不能にしないようにする。
Widget _readableSnackContent(Widget content) {
  return IconTheme.merge(
    data: const IconThemeData(color: Colors.white),
    child: DefaultTextStyle.merge(
      style: const TextStyle(color: Colors.white),
      child: content,
    ),
  );
}

SnackBar _patchSnackBarDuration(BuildContext context, SnackBar bar,
    {required bool processing}) {
  final original = bar.duration;
  Duration finalDuration = original;
  final isLongRunning = original >= const Duration(seconds: 30);
  if (!processing && !isLongRunning) {
    if (original > const Duration(seconds: 4)) {
      finalDuration = const Duration(seconds: 4);
    }
  }

  // 通知はSafeArea直上へ置き、重なる下部バー側を表示中だけ退避させる。
  final behavior = bar.behavior ?? SnackBarBehavior.floating;
  final margin = bar.margin ??
      (behavior == SnackBarBehavior.floating
          ? _snackBarFloatingMargin(context)
          : null);

  return SnackBar(
    key: bar.key,
    content: _readableSnackContent(bar.content),
    backgroundColor: bar.backgroundColor ?? const Color(0xFF2A2A3E),
    elevation: bar.elevation,
    margin: margin,
    padding: bar.padding,
    width: bar.width,
    shape: bar.shape,
    behavior: behavior,
    action: bar.action,
    duration: finalDuration,
    animation: bar.animation,
    onVisible: bar.onVisible,
    dismissDirection: bar.dismissDirection,
    clipBehavior: bar.clipBehavior,
  );
}

/// `_appSnack` の `ScaffoldMessengerState` 引数版。
///
/// コードベースには「`final messenger = ScaffoldMessenger.of(ctx);` で
/// 取得しておき、後で `_appSnackM(messenger, ...)` する」形のパターンが
/// 多数ある。それらの置換用。
///
/// `messenger == null` の場合は何もせず null を返す。
ScaffoldFeatureController<SnackBar, SnackBarClosedReason>? _appSnackM(
  ScaffoldMessengerState? messenger,
  SnackBar bar, {
  bool processing = false,
}) {
  if (messenger == null) return null;
  final generation = ++_appSnackGeneration;
  MindMapProvider? provider;
  messenger.hideCurrentSnackBar();
  final patched =
      _patchSnackBarDuration(messenger.context, bar, processing: processing);
  // ドロワーが開いている間は手前の写しだけ (= 二重表示させない)。
  if (appMainScaffoldKey?.currentState?.isDrawerOpen == true) {
    _showSnackAboveDrawer(messenger.context, patched);
    return null;
  }
  try {
    provider = messenger.context.read<MindMapProvider>();
    provider.setBottomBarLifted(true);
  } catch (_) {}
  final controller = messenger.showSnackBar(patched);
  controller.closed.whenComplete(() {
    if (_appSnackGeneration != generation) return;
    try {
      provider?.setBottomBarLifted(false);
    } catch (_) {}
  });
  return controller;
}

