// ─── 動画ダウンロード共通ヘルパー (モバイル/デスクトップ両方から使用) ──────

/// ファイル名に使えない文字を `_` に置換し、ASCII 範囲外も `_` に。
/// CJK / 絵文字を含むタイトルでも safe なファイル名になる。
/// 60 文字を超えるとトリム。空になったら 'video' をフォールバック。
String _dlSanitizeFilename(String name) {
  var s = name
      .replaceAll(RegExp(r'[<>:"/\\|?*\x00-\x1F]'), '_')
      .replaceAll(RegExp(r'[^\x20-\x7E]'), '_')
      .trim()
      .replaceAll(RegExp(r'\s+'), '_')
      .replaceAll(RegExp(r'_+'), '_')
      .replaceAll(RegExp(r'^_+|_+$'), '');
  if (s.length > 60) s = s.substring(0, 60);
  if (s.isEmpty) s = 'video';
  return s;
}

/// 同名ファイルが既に存在する場合は `_1`, `_2` のサフィックスを付ける。
String _dlEnsureUniquePath(String path) {
  if (!File(path).existsSync()) return path;
  final dot = path.lastIndexOf('.');
  final stem = dot >= 0 ? path.substring(0, dot) : path;
  final ext = dot >= 0 ? path.substring(dot) : '';
  for (var i = 1; i < 1000; i++) {
    final candidate = '${stem}_$i$ext';
    if (!File(candidate).existsSync()) return candidate;
  }
  return path;
}

/// バイト数を人間に読みやすい文字列に整形する (1.2 MB / 345 KB 等)。
String _dlHumanBytes(int bytes) {
  if (bytes < 1024) return '$bytes B';
  if (bytes < 1024 * 1024) {
    return '${(bytes / 1024).toStringAsFixed(1)} KB';
  }
  if (bytes < 1024 * 1024 * 1024) {
    return '${(bytes / 1024 / 1024).toStringAsFixed(1)} MB';
  }
  return '${(bytes / 1024 / 1024 / 1024).toStringAsFixed(2)} GB';
}

/// YouTube の CDN サムネ (sd → hq) を取得してローカル保存する。
/// 成功で保存先パス、失敗で null。`baseDir` 配下に `video_thumbs/` を
/// 自動作成する。
Future<String?> _dlYoutubeThumb(String videoId, Directory baseDir) async {
  final urls = [
    'https://i.ytimg.com/vi/$videoId/sddefault.jpg',
    'https://i.ytimg.com/vi/$videoId/hqdefault.jpg',
  ];
  final thumbDir =
      Directory('${baseDir.path}${Platform.pathSeparator}video_thumbs');
  try {
    if (!await thumbDir.exists()) {
      await thumbDir.create(recursive: true);
    }
  } catch (_) {
    return null;
  }
  final outPath = '${thumbDir.path}${Platform.pathSeparator}yt_$videoId.jpg';
  for (final url in urls) {
    try {
      final resp =
          await http.get(Uri.parse(url)).timeout(const Duration(seconds: 15));
      if (resp.statusCode == 200 && resp.bodyBytes.isNotEmpty) {
        if (resp.bodyBytes.length < 1024) continue;
        await File(outPath).writeAsBytes(resp.bodyBytes);
        return outPath;
      }
    } catch (_) {}
  }
  return null;
}

/// YouTube 関連動画の自動取得。
///
/// リリース前コンプライアンス対応:
/// YouTube 検索結果 HTML のスクレイピングは規約リスクが高いため無効化。
/// 将来復活させる場合は YouTube Data API 等の公式APIに差し替える。
Future<List<Map<String, String>>> _fetchRelatedVideos(String query,
    {int limit = 5, String youtubeRegionQuery = 'hl=ja&gl=JP'}) async {
  return const [];
}

List<Map<String, String>> _extractVideosFromYoutubeHtml(
    String body, int limit) {
  // ── 新 youtube_web フロントエンド対応 (2026-06〜) ──
  // 新しい YouTube 検索結果ページは ytInitialData を JS 文字列として埋め込み、
  //   引用符や波括弧を `\xNN` の 16進エスケープで書いている
  //   (例: `\x7b\x22videoId\x22:\x22hQ4-H-nNNz4\x22` = `{"videoId":"hQ4-H-nNNz4"`)。
  //   そのままだと下の `"videoId":"..."` 系の正規表現が一切マッチせず 0 件に
  //   なる (= ユーザー報告: モバイルで YouTube 検索が結果を返さない)。
  //   `\xNN` を実文字へ戻してから抽出する。 旧形式 (生の `"videoId"`) には
  //   `\x` が無いのでこのデコードは無害 (べき等)。
  if (body.contains(r'\x22')) {
    body = body.replaceAllMapped(
      RegExp(r'\\x([0-9a-fA-F]{2})'),
      (m) => String.fromCharCode(int.parse(m.group(1)!, radix: 16)),
    );
  }
  final results = <Map<String, String>>[];
  final seen = <String>{};

  // タイトルのエスケープを戻す (\u003d / \" 等)
  String decodeJsonString(String s) {
    var t = s
        .replaceAll(r'\"', '"')
        .replaceAll(r'\\', r'\')
        .replaceAll(r'\/', '/')
        .replaceAll(r'\n', ' ')
        .replaceAll(r'\t', ' ');
    // \uXXXX をデコード
    t = t.replaceAllMapped(
      RegExp(r'\\u([0-9a-fA-F]{4})'),
      (m) => String.fromCharCode(int.parse(m.group(1)!, radix: 16)),
    );
    return t.trim();
  }

  void addIfNew(String vid, String title) {
    if (vid.isEmpty || seen.contains(vid)) return;
    if (results.length >= limit) return;
    seen.add(vid);
    results.add({
      'videoId': vid,
      'title': title.isNotEmpty ? title : 'YouTube video',
    });
  }

  // ── パターン 1: 旧 videoRenderer / compactVideoRenderer
  //    "videoId":"XXX" ... "title":{"runs":[{"text":"..."}]}
  //    char window を 400 → 2000 に拡大 (新形式は間に余分な JSON が入る)
  final p1 = RegExp(
    r'"videoId":"([a-zA-Z0-9_-]{11})"[\s\S]{0,2000}?"title":\{"runs":\[\{"text":"((?:[^"\\]|\\.)*)"',
  );
  for (final m in p1.allMatches(body)) {
    if (results.length >= limit) break;
    addIfNew(m.group(1) ?? '', decodeJsonString(m.group(2) ?? ''));
  }
  if (results.length >= limit) return results;

  // ── パターン 2: simpleText 形式
  //    "videoId":"XXX" ... "title":{"simpleText":"..."}
  final p2 = RegExp(
    r'"videoId":"([a-zA-Z0-9_-]{11})"[\s\S]{0,2000}?"title":\{"simpleText":"((?:[^"\\]|\\.)*)"',
  );
  for (final m in p2.allMatches(body)) {
    if (results.length >= limit) break;
    addIfNew(m.group(1) ?? '', decodeJsonString(m.group(2) ?? ''));
  }
  if (results.length >= limit) return results;

  // ── パターン 3: 新 lockupViewModel / compactVideoCardViewModel
  //    "contentId":"XXX" ... "title":{"content":"..."}
  //    accessibility 情報や thumbnail JSON が間に挟まるので window を 3000 に
  final p3 = RegExp(
    r'"contentId":"([a-zA-Z0-9_-]{11})"[\s\S]{0,3000}?"title":\{(?:[^{}]*?)"content":"((?:[^"\\]|\\.)*)"',
  );
  for (final m in p3.allMatches(body)) {
    if (results.length >= limit) break;
    addIfNew(m.group(1) ?? '', decodeJsonString(m.group(2) ?? ''));
  }
  if (results.length >= limit) return results;

  // ── パターン 4: 最終フォールバック (タイトル取得失敗してでも videoId は返す)
  //    HTML 内に出現する videoId / contentId を順に拾い、その近傍 (前後
  //    2500 文字) で title 候補を探す。見つからなければ汎用タイトル。
  final pVid = RegExp(r'"(?:videoId|contentId)":"([a-zA-Z0-9_-]{11})"');
  for (final m in pVid.allMatches(body)) {
    if (results.length >= limit) break;
    final vid = m.group(1) ?? '';
    if (vid.isEmpty || seen.contains(vid)) continue;

    final start = m.start;
    final end = (m.end + 2500).clamp(0, body.length);
    final segment = body.substring(start, end);

    String title = '';
    // この近傍に出てくる title フィールドを順に試す
    final tm = RegExp(
      r'"title":\{(?:[^{}]*?)(?:"runs":\[\{"text":"((?:[^"\\]|\\.)*)"|'
      r'"simpleText":"((?:[^"\\]|\\.)*)"|'
      r'"content":"((?:[^"\\]|\\.)*)")',
    ).firstMatch(segment);
    if (tm != null) {
      title = decodeJsonString(
        tm.group(1) ?? tm.group(2) ?? tm.group(3) ?? '',
      );
    }
    addIfNew(vid, title);
  }

  return results;
}

// ──────────────────────────────────────────────────────────────────────────
// アプリ内ビューア (URL / PDF) — 共通 State (デスクトップ + モバイル)
// ──────────────────────────────────────────────────────────────────────────
//
// 設計メモ:
//   - PDF は Windows: WebView2 / macOS+iOS+Linux: WKWebView (flutter_inappwebview
//     経由) が組み込み PDF ビューアで描画する。 描画自体は WebView 任せで、
//     こちら側ではページジャンプを `#page=N` フラグメントで制御する。
//   - メモ機能:
//     ・「メモ配置モード」 トグル → WebView の上に透明な GestureDetector
//       が乗り、 タップ位置を `xRatio/yRatio` (0.0〜1.0 の比率) で保存。
//     ・既存メモは現在ページ (PDF) もしくは現在 URL に一致するものだけ
//       マーカーとしてオーバーレイ描画。
//     ・サイドパネルのメモ行をタップ → 該当ページ / URL にジャンプ +
//       マーカーをパルスでハイライト。
//   - URL 切替検知:
//     ・flutter_inappwebview: `onLoadStart` で `_currentUrl` 更新
//     ・webview_windows: `url` ストリームを listen
//   - 動画系 URL はここに来ない (呼び出し側 `_openLink` / `_openNodeLink`
//     で先に専用プレイヤーへ振り分け済み)。

/// メモのマーカーをアニメーション付きで描画するヘルパ。
///
/// - 通常時: 影付きの丸アイコン
/// - ハイライト時: パルス (= 影が広がる + 縮む) を _highlightCtrl の値で
///   2 秒程度走らせる。 ジャンプ直後の「どこに飛んだか」 を視覚化する用。
Widget _buildMemoMarker({
  required PdfMemo memo,
  required Size area,
  required bool isHighlighted,
  required Animation<double> pulse,
  required VoidCallback onTap,
  required VoidCallback onLongPress,
}) {
  final color = Color(memo.colorValue);
  // 32x32 のマーカーを座標中心に置く → -16 オフセット。
  // クランプで枠外には出さない (= 端の方をタップしてもマーカーは見える)。
  final left =
      (((memo.xRatio ?? 0.5) * area.width) - 16).clamp(0.0, area.width - 32);
  final top =
      (((memo.yRatio ?? 0.5) * area.height) - 16).clamp(0.0, area.height - 32);
  return Positioned(
    left: left,
    top: top,
    child: AnimatedBuilder(
      animation: pulse,
      builder: (_, __) {
        final p = isHighlighted ? pulse.value : 0.0;
        return GestureDetector(
          onTap: onTap,
          onLongPress: onLongPress,
          child: Container(
            width: 32,
            height: 32,
            decoration: BoxDecoration(
              color: color,
              shape: BoxShape.circle,
              border: Border.all(color: Colors.white, width: 2),
              boxShadow: [
                if (isHighlighted)
                  BoxShadow(
                    color: color.withValues(alpha: 0.8),
                    blurRadius: 8 + p * 16,
                    spreadRadius: 1 + p * 6,
                  )
                else
                  const BoxShadow(
                    color: Colors.black54,
                    blurRadius: 4,
                    offset: Offset(0, 2),
                  ),
              ],
            ),
            child:
                const Icon(Icons.sticky_note_2, color: Colors.white, size: 18),
          ),
        );
      },
    ),
  );
}

