/// ビューアの立ち上がりを測るための時計 (= ユーザー要望: 起動をもっと速く)。
/// どこで時間が掛かっているかを実測するために置いている。 出力は 1 回の
/// オープンにつき数行だけなので、 そのまま入れておいても負荷にならない。
Stopwatch? _gViewerOpenSw;
void _viewerMark(String label) {
  final sw = _gViewerOpenSw;
  if (sw == null) return;
  debugPrint('[viewer] ${sw.elapsedMilliseconds}ms  $label');
}

// ── SfPdfViewer 用に File を「パス単位でキャッシュ」して同一インスタンスを返す ──
// (= ユーザー要望: PDF がページめくりの度に読み込まれて重い問題の修正)。
// 原因: `SfPdfViewer.file(File(path))` で build の度に新しい File オブジェクトを
// 渡すと、 syncfusion が「ファイルソースが変わった」 と判定してドキュメントを
// 再ロードしてしまう (File は == を override しないので毎回別物扱い)。 パスが
// 同じ間は同じ File を返すことで、 ページ移動時の setState で再ロードされなくなる。
String? _gStablePdfPath;
File? _gStablePdfFile;
File _stablePdfFile(String path) {
  if (_gStablePdfPath != path || _gStablePdfFile == null) {
    _gStablePdfPath = path;
    _gStablePdfFile = File(path);
  }
  return _gStablePdfFile!;
}

/// Printing.raster は PDF 全体をメモリへ読み込むため、ビューア本体と同時に
/// 大きな文書をラスタ化すると OS に終了されることがある。通常の
/// SfPdfViewer 表示は維持し、サムネイル／見開き画像だけに安全上限を設ける。
int get _pdfRasterSourceLimitBytes {
  if (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) {
    return 32 * 1024 * 1024;
  }
  return 96 * 1024 * 1024;
}

bool _isPdfRasterSourceSafe(String path) {
  try {
    return File(path).lengthSync() <= _pdfRasterSourceLimitBytes;
  } catch (_) {
    return false;
  }
}

/// 見開きでは PDF バイトの転送に加えて 2 ページ分の描画を行うため、1 ページの
/// サムネイルより厳しい上限を使う。上限超過時はライブビューアを維持して、OOM に
/// よるアプリ終了より安全な通常表示へのフォールバックを優先する。
int get _pdfSpreadRasterSourceLimitBytes {
  if (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) {
    return 20 * 1024 * 1024;
  }
  return 64 * 1024 * 1024;
}

bool _isPdfSpreadRasterSourceSafe(String path) {
  try {
    return File(path).lengthSync() <= _pdfSpreadRasterSourceLimitBytes;
  } catch (_) {
    return false;
  }
}

/// PDF の 1 ページ目をラスタライズしてサムネイル画像ファイルに保存する。
/// 返り値はパスとアスペクト比 (= 幅/高さ)。 失敗時は null。
/// (= ユーザー要望: PDF をダウンロード/取得してもノードにサムネイルを出す)
Future<({String path, double aspect})?> _renderPdfThumbToFile(
    String pdfPath, String thumbDir) async {
  try {
    if (!_isPdfRasterSourceSafe(pdfPath)) return null;
    final bytes = await File(pdfPath).readAsBytes();
    await for (final page
        in printing.Printing.raster(bytes, pages: [0], dpi: 96)) {
      final png = await page.toPng();
      final outPath = '$thumbDir/thumb_${pdfPath.hashCode}_p1.png';
      await File(outPath).writeAsBytes(png);
      final aspect = page.height > 0 ? page.width / page.height : 0.71;
      return (path: outPath, aspect: aspect);
    }
  } catch (_) {}
  return null;
}

/// ページ番号の目印を挟んで PDF 本文を取り出す (= ユーザー要望: 要約の各項目に
/// 「p.12」 を付けたい / 図のあるページを AI に指定させたい)。
/// 目印は `=== p.12 ===` の形。 重い処理なのでアイソレートで動かす。
String? _extractPdfTextWithPagesForIsolate(Uint8List bytes) {
  try {
    final doc = sfpdf.PdfDocument(inputBytes: bytes);
    final count = doc.pages.count;
    final extractor = sfpdf.PdfTextExtractor(doc);
    final buf = StringBuffer();
    const maxChars = 55000;
    for (int i = 0; i < count; i++) {
      final t =
          extractor.extractText(startPageIndex: i, endPageIndex: i).trim();
      if (t.isEmpty) continue;
      buf.writeln('=== p.${i + 1} ===');
      buf.writeln(t);
      if (buf.length > maxChars) {
        buf.writeln('... [truncated]');
        break;
      }
    }
    doc.dispose();
    final out = buf.toString().trim();
    if (out.isEmpty) return null;
    // 文字の対応表を持たない PDF (作成ソフトによっては日本語がこうなる) では、
    //   本文の代わりに `uni00003042` `cid:1234` のような字形の名前が並ぶ。
    //   このまま AI に渡しても「読めない」 という要約が返るだけで、
    //   料金だけ掛かる。 判読不能と分かったらここで諦める。
    return _looksUnreadableText(out) ? null : out;
  } catch (_) {
    return null;
  }
}

/// 取り出した本文が「字形の名前の羅列」 で判読できないかを見る。
/// 目安として、 その手の並びが全体の 3 割を超えたら判読不能とみなす。
bool _looksUnreadableText(String text) {
  if (text.length < 40) return false;
  final re = RegExp(r'(uni[0-9A-Fa-f]{4,6}|cid:\d+|glyph\d+|g\d{2,5}\b)');
  var covered = 0;
  for (final m in re.allMatches(text)) {
    covered += m.end - m.start;
  }
  return covered > text.length * 0.3;
}

/// [_extractPdfTextWithPagesForIsolate] の呼び出し口。
Future<String?> _extractPdfTextWithPagesForAi(String path) async {
  try {
    final bytes = await File(path).readAsBytes();
    return await compute(_extractPdfTextWithPagesForIsolate, bytes);
  } catch (_) {
    return null;
  }
}

/// 資料の 1 ページを画像にして保存する (= ユーザー要望: 要約に図も入れたい)。
/// [pageNumber] は 1 始まり。 失敗したら null (図が無くても要約は成立する)。
Future<String?> _renderDocPageToFile(String pdfPath, int pageNumber) async {
  try {
    if (!_isPdfRasterSourceSafe(pdfPath)) return null;
    if (pageNumber < 1) return null;
    final dir = await getApplicationDocumentsDirectory();
    final outDir = Directory('${dir.path}/ai_figures');
    if (!await outDir.exists()) await outDir.create(recursive: true);
    final bytes = await File(pdfPath).readAsBytes();
    // 貼った画像を拡大して読むこともあるので、 サムネイル (96dpi) より高め。
    await for (final page in printing.Printing.raster(bytes,
        pages: [pageNumber - 1], dpi: 150)) {
      final png = await page.toPng();
      final outPath =
          '${outDir.path}/fig_${pdfPath.hashCode}_p$pageNumber.png';
      await File(outPath).writeAsBytes(png);
      return outPath;
    }
  } catch (_) {}
  return null;
}

/// アイソレートで実行する PDF テキスト抽出本体 (= ユーザー要望: PDF を開くと
/// フリーズする問題の対策)。 `PdfDocument` 構築と `PdfTextExtractor.extractText`
/// は **同期** で重い (大きな PDF ではメインアイソレートを数秒〜数十秒ブロック
/// して UI が固まる) ため、 `compute` でバックグラウンドアイソレートに逃がす。
/// syncfusion_flutter_pdf は純 Dart なのでアイソレート内で安全に動く。
String? _extractPdfTextSyncForIsolate(Uint8List bytes) {
  try {
    final doc = sfpdf.PdfDocument(inputBytes: bytes);
    var text = sfpdf.PdfTextExtractor(doc).extractText();
    doc.dispose();
    text = text.trim();
    if (text.isEmpty) return null;
    const maxChars = 50000;
    if (text.length > maxChars) text = text.substring(0, maxChars);
    return text;
  } catch (_) {
    return null;
  }
}

/// ページ範囲を限定して PDF テキスト抽出 (= ユーザー要望: 読む範囲を設定)。
/// start/end は 1-based ページ番号。 [strip] が true の時は、 ページをまたいで
/// 繰り返すヘッダー/フッター (会社ロゴ周りの定型文・著作権・ページ番号) を除去する
/// (= ユーザー要望: copyright やヘッダーの定型は読み上げない)。
String? _extractPdfTextRangeForIsolate(
    ({Uint8List bytes, int start, int end, bool strip}) arg) {
  try {
    final doc = sfpdf.PdfDocument(inputBytes: arg.bytes);
    final last = doc.pages.count;
    final s = (arg.start - 1).clamp(0, last - 1);
    final e = (arg.end - 1).clamp(s, last - 1);
    final extractor = sfpdf.PdfTextExtractor(doc);
    String text;
    if (arg.strip) {
      // ページ毎に抽出して、 定型行 (ヘッダー/フッター) を除去してから連結する。
      final pageLines = <List<String>>[];
      for (int i = s; i <= e; i++) {
        final pt = extractor.extractText(startPageIndex: i, endPageIndex: i);
        pageLines.add(pt.split('\n'));
      }
      text = _stripPdfBoilerplate(pageLines);
    } else {
      text = extractor.extractText(startPageIndex: s, endPageIndex: e);
    }
    doc.dispose();
    text = text.trim();
    if (text.isEmpty) return null;
    const maxChars = 50000;
    if (text.length > maxChars) text = text.substring(0, maxChars);
    return text;
  } catch (_) {
    return null;
  }
}

/// ページ毎の行リストから、 ヘッダー/フッターなど「読み上げ不要な定型行」 を除いて
/// 本文だけを連結して返す (= ユーザー要望: フッターの copyright やヘッダーの
/// 会社ロゴ周りの定型を読み上げない)。
///   - 半数以上のページに現れる短い行 = ヘッダー/フッター/ロゴキャプション とみなす
///   - copyright / © / All rights reserved を含む行
///   - ページ番号だけの行 ("12" / "Page 12" / "12 / 30")
/// ページ毎の行リストから「読み上げ不要な定型行 (ヘッダー/フッター/ページ番号/
/// 著作権)」 の集合を求める。 _stripPdfBoilerplate とページ毎抽出の両方で使う。
Set<String> _pdfBoilerplateLines(List<List<String>> pages) {
  final freq = <String, int>{};
  for (final lines in pages) {
    final seen = <String>{};
    for (final raw in lines) {
      final l = raw.trim();
      if (l.isEmpty) continue;
      if (seen.add(l)) freq[l] = (freq[l] ?? 0) + 1;
    }
  }
  final n = pages.length;
  final threshold = (n / 2).ceil();
  final out = <String>{};
  for (final entry in freq.entries) {
    final l = entry.key;
    final low = l.toLowerCase();
    final repeated = n >= 3 && entry.value >= threshold && l.length <= 80;
    final boiler = l.contains('©') ||
        low.contains('copyright') ||
        low.contains('all rights reserved') ||
        low.contains('(c)') ||
        RegExp(r'^(page\s*)?\d+(\s*[/／]\s*\d+)?$', caseSensitive: false)
            .hasMatch(l);
    if (repeated || boiler) out.add(l);
  }
  return out;
}

String _stripPdfBoilerplate(List<List<String>> pages) {
  if (pages.isEmpty) return '';
  final boiler = _pdfBoilerplateLines(pages);
  final buf = StringBuffer();
  for (final lines in pages) {
    for (final raw in lines) {
      final l = raw.trim();
      if (l.isEmpty) continue;
      if (boiler.contains(l)) continue;
      buf.writeln(l);
    }
  }
  return buf.toString();
}

/// ページ範囲を 1 ページずつ抽出してリストで返す (= 読み上げのページ追従用)。
/// start/end は 1-based。 戻り値[i] は (start+i) ページの本文。 [strip] が true なら
/// ページ間で繰り返す定型 (ヘッダー/フッター等) を各ページから除去する。 1 回の
/// アイソレートでまとめて処理する (= ページ毎に compute を呼ぶより速い)。
List<String>? _extractPdfPerPageForIsolate(
    ({Uint8List bytes, int start, int end, bool strip}) arg) {
  try {
    final doc = sfpdf.PdfDocument(inputBytes: arg.bytes);
    final last = doc.pages.count;
    final s = (arg.start - 1).clamp(0, last - 1);
    final e = (arg.end - 1).clamp(s, last - 1);
    final extractor = sfpdf.PdfTextExtractor(doc);
    final pageLines = <List<String>>[];
    for (int i = s; i <= e; i++) {
      final pt = extractor.extractText(startPageIndex: i, endPageIndex: i);
      pageLines.add(pt.split('\n'));
    }
    doc.dispose();
    final boiler =
        arg.strip ? _pdfBoilerplateLines(pageLines) : const <String>{};
    final out = <String>[];
    for (final lines in pageLines) {
      final buf = StringBuffer();
      for (final raw in lines) {
        final l = raw.trim();
        if (l.isEmpty) continue;
        if (boiler.contains(l)) continue;
        buf.writeln(l);
      }
      out.add(buf.toString().trim());
    }
    return out;
  } catch (_) {
    return null;
  }
}

/// PDF をページ範囲で 1 ページずつ抽出する (= 読み上げのページ追従用)。
Future<List<String>?> _extractPdfPerPage(String path, int start, int end,
    {bool strip = true}) async {
  try {
    final bytes = await File(path).readAsBytes();
    return await compute(_extractPdfPerPageForIsolate,
        (bytes: bytes, start: start, end: end, strip: strip));
  } catch (_) {
    return null;
  }
}

/// PDF 本文のテキストを抽出して返す (= ユーザー要望: PDF の内容を AI チャットに
/// 渡す)。 AI 入力上限を考慮して先頭 5 万文字でカット。 失敗/空なら null。
/// 重い同期処理はアイソレートで実行し UI のフリーズを防ぐ (= ユーザー要望)。
Future<String?> _extractPdfTextForAi(String path,
    {int? startPage, int? endPage, bool stripBoilerplate = false}) async {
  try {
    final bytes = await File(path).readAsBytes();
    if (startPage != null && endPage != null) {
      return await compute(_extractPdfTextRangeForIsolate, (
        bytes: bytes,
        start: startPage,
        end: endPage,
        strip: stripBoilerplate
      ));
    }
    return await compute(_extractPdfTextSyncForIsolate, bytes);
  } catch (_) {
    return null;
  }
}

/// 読み上げの開始ページを尋ねるダイアログ (= ユーザー要望: 読み上げるページを
/// 指定できるように)。 既定値は「今見ているページ」 (= 動的に割り当て)。
/// 戻り値: 選択した 1-based 開始ページ。 キャンセルなら null。
Future<int?> _askReadAloudStartPage(
    BuildContext context, int defStart, int? total) {
  final provider = context.read<MindMapProvider>();
  final ctrl = TextEditingController(text: '$defStart');
  return showDialog<int>(
    context: context,
    builder: (dctx) => AlertDialog(
      backgroundColor: const Color(0xFF1E1E32),
      title: Text(provider.t('readaloud.startTitle'),
          style: const TextStyle(color: Colors.white, fontSize: 15)),
      content: Row(mainAxisSize: MainAxisSize.min, children: [
        Text(provider.t('readaloud.fromPage'),
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        const SizedBox(width: 8),
        SizedBox(
          width: 70,
          child: TextField(
            controller: ctrl,
            autofocus: true,
            keyboardType: TextInputType.number,
            textAlign: TextAlign.center,
            style: const TextStyle(color: Colors.white, fontSize: 14),
            onSubmitted: (_) {
              var v = int.tryParse(ctrl.text.trim()) ?? defStart;
              if (v < 1) v = 1;
              if (total != null && v > total) v = total;
              Navigator.pop(dctx, v);
            },
            decoration: InputDecoration(
              isDense: true,
              filled: true,
              fillColor: Colors.white.withValues(alpha: 0.08),
              border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(8),
                  borderSide: BorderSide.none),
            ),
          ),
        ),
        if (total != null)
          Padding(
            padding: const EdgeInsets.only(left: 6),
            child: Text('/ $total',
                style: const TextStyle(color: Colors.white38, fontSize: 13)),
          ),
      ]),
      actions: [
        TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54))),
        ElevatedButton(
            onPressed: () {
              var v = int.tryParse(ctrl.text.trim()) ?? defStart;
              if (v < 1) v = 1;
              if (total != null && v > total) v = total;
              Navigator.pop(dctx, v);
            },
            child: Text(provider.t('readaloud.start'))),
      ],
    ),
  );
}

/// PDF 本文を抽出してクリップボードへコピーし、 AI チャット欄を開く
/// (= ユーザー要望: PDF 自体を AI チャットに渡すボタン)。 Web の AI チャットには
/// 直接プログラム注入できないため、 クリップボード経由で貼り付けてもらう方式。
Future<void> _sendPdfTextToAi(BuildContext context, String? pdfPath,
    bool aiPanelOpen, VoidCallback openAiPanel) async {
  final messenger = ScaffoldMessenger.maybeOf(context);
  final provider = context.read<MindMapProvider>();
  if (pdfPath == null || !File(pdfPath).existsSync()) {
    messenger?.showSnackBar(SnackBar(
        content: Text(provider.t('pdf.noPdf')),
        duration: const Duration(seconds: 2)));
    return;
  }
  messenger?.showSnackBar(SnackBar(
      content: Text(provider.t('pdf.reading')),
      duration: const Duration(seconds: 1)));
  final text = await _extractPdfTextForAi(pdfPath);
  if (!context.mounted) return;
  if (text == null || text.isEmpty) {
    messenger?.showSnackBar(SnackBar(
        content: Text(provider.t('pdf.noTextExtract')),
        duration: const Duration(seconds: 3)));
    return;
  }
  await Clipboard.setData(ClipboardData(text: text));
  if (!aiPanelOpen) openAiPanel();
  if (!context.mounted) return;
  final isDesktop =
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);
  messenger?.showSnackBar(SnackBar(
    content: Text(provider.t(isDesktop ? 'pdf.copied' : 'pdf.copiedMobile')),
    backgroundColor: const Color(0xFF43B97F),
    duration: Duration(seconds: 4),
  ));
}

/// ノードの PDF サムネイルが無ければ生成して設定する (= ユーザー要望:
/// PDF をダウンロード/取得した直後でもノードにサムネイルが表示されるように)。
/// 既に有効なサムネイル (ファイルが存在) があれば何もしない。
Future<void> _ensurePdfThumbForNode(
    BuildContext context, String? nodeId, String? pdfPath) async {
  if (nodeId == null || pdfPath == null || pdfPath.isEmpty) return;
  if (!pdfPath.toLowerCase().endsWith('.pdf')) return;
  if (!File(pdfPath).existsSync()) return;
  // モバイルでは、表示中の SfPdfViewer と同じ PDF をサムネイル用にもう一度
  // 全読み込みしない。添付時に作成済みのサムネイルはそのまま利用する。
  if (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) return;
  if (!_isPdfRasterSourceSafe(pdfPath)) return;
  final provider = context.read<MindMapProvider>();
  final node = provider.nodes[nodeId];
  if (node == null) return;
  final existing = node.attachmentThumbPath;
  if (existing != null && existing.isNotEmpty && File(existing).existsSync()) {
    return; // 既にサムネあり
  }
  try {
    final appDir = await getApplicationDocumentsDirectory();
    final thumbDir = Directory('${appDir.path}/attachments');
    if (!thumbDir.existsSync()) thumbDir.createSync(recursive: true);
    final thumb = await _renderPdfThumbToFile(pdfPath, thumbDir.path);
    if (thumb != null && context.mounted) {
      provider.setAttachmentThumb(nodeId, thumb.path, thumb.aspect);
    }
  } catch (_) {}
}

// ──────────────────────────────────────────────────────────────────────────
// アプリ内ビューア — デスクトップ版 Dialog
// ──────────────────────────────────────────────────────────────────────────
class _InAppViewerDialog extends StatefulWidget {
  final String url;
  final bool isPdf;
  final String? nodeId;

  /// 現在の URL を画面分割パネルに移して表示するコールバック。
  /// null なら「画面分割で開く」 ボタンは出ない。
  final void Function(String currentUrl, {bool isLeftPanel})?
      onMoveToSplitPanel;

  /// PDF から AI で一問一答クイズを生成するコールバック。
  /// 引数は現在表示中の PDF パス/URL。 null なら一問一答ボタンは出ない。
  final void Function(String pdfPathOrUrl)? onGenerateQuiz;

  /// メモを AI (API) に質問して、 回答をマップ/メモに書き戻すコールバック
  /// (= ユーザー要望)。 null なら「回答を取得」 は出ない。
  final void Function(PdfMemo memo)? onAskAiMemo;

  /// ファイル本体を書き換えた時に呼ぶ (= 手書きの焼き込み等)。
  /// マップ側でサムネイルを作り直すために使う (= ユーザー報告)。
  final VoidCallback? onSavedToFile;

  /// 全画面表示の初期再生速度 (= 画面分割から引き継ぐ。 ユーザー要望)。
  final double initialRate;

  /// 添付ノードがまだ無い時に、 必要になった時点でマップへ追加して
  /// そのノード ID を返すコールバック (= ユーザー要望: 「プログラムから
  /// 開く」 で開いた時も、 埋め込んだ時と同じようにメモ欄 / AI 欄が使える
  /// ように)。 null ならこのビューアはノードを作らない。
  /// まだマップに載っていないファイルをノードとして追加する。
  /// [pageId] を渡すとそのページへ、 省略すると現在のページへ追加する
  /// (= ユーザー要望: 追加先ページを選べるように)。
  final Future<String?> Function({String? pageId})? onEnsureNode;

  /// 開いているファイルの添付ノードを別のページへ移すコールバック
  /// (= ユーザー要望: 開いている PDF をページに埋め込んだり移動したり)。
  final void Function(String nodeId)? onMoveNodeToPage;
  const _InAppViewerDialog({
    required this.url,
    required this.isPdf,
    this.nodeId,
    this.onMoveToSplitPanel,
    this.onGenerateQuiz,
    this.onAskAiMemo,
    this.onSavedToFile,
    this.onEnsureNode,
    this.onMoveNodeToPage,
    this.initialRate = 1.0,
    this.compactHost = false,
  });

  /// フローティング窓・分割ペインなど狭い場所で開かれているか。
  /// true の時はメモ / AI パネルを自動で開かない (= ユーザー要望:
  /// 表示領域が小さい時に勝手に開かれると本体が見えない)。
  final bool compactHost;

  @override
  State<_InAppViewerDialog> createState() => _InAppViewerDialogState();
}

class _InAppViewerDialogState extends State<_InAppViewerDialog>
    with TickerProviderStateMixin {
  // ── 添付ノード ID ──
  // 「プログラムから開く」 で開いた時は最初 null で、 メモや AI を使った
  // 時点 (または「ページに追加」 ボタン) でマップにノードを作って埋まる
  // (= ユーザー要望: 開くときに確認を出さず、 でも埋め込んだ時と同じ機能を
  //  使えるように)。
  String? _lazyNodeId;
  String? get _nodeId => _lazyNodeId ?? widget.nodeId;

  /// マップにまだ載っていない (= 「ページに追加」 が押せる) 状態か。
  bool get _canAddToPage => _nodeId == null && widget.onEnsureNode != null;

  /// ノードが必要な操作の直前に呼ぶ。 無ければその場でマップに追加する。
  Future<String?> _ensureNode({String? pageId}) async {
    final cur = _nodeId;
    if (cur != null) return cur;
    final cb = widget.onEnsureNode;
    if (cb == null) return null;
    final id = await cb(pageId: pageId);
    if (id != null && mounted) setState(() => _lazyNodeId = id);
    return id;
  }

  /// 追加先のページを選んでから追加する (= ユーザー要望: 「このページに
  /// 追加」 がどのページか分からないので選べるように)。
  /// ページが 1 つしかない時はそのまま追加する。
  Future<String?> _ensureNodeWithPagePicker(BuildContext btnCtx) async {
    final cur = _nodeId;
    if (cur != null) return cur;
    final provider = context.read<MindMapProvider>();
    final targets = provider.pages
        .where((p) => p.pageType == 'normal' || p.pageType == 'bookshelf')
        .toList();
    if (targets.length <= 1) return _ensureNode();
    final curId = provider.currentPage.id;
    final box = btnCtx.findRenderObject() as RenderBox?;
    final pos =
        box == null ? const Offset(80, 80) : box.localToGlobal(Offset.zero);
    final chosen = await showMenu<String>(
      context: btnCtx,
      position: RelativeRect.fromLTRB(
          pos.dx - 160, pos.dy + 28, pos.dx + 1, pos.dy + 29),
      color: const Color(0xFF1E2430),
      items: [
        PopupMenuItem<String>(
          enabled: false,
          height: 30,
          child: Text(provider.t('openWith.choosePage'),
              style: const TextStyle(
                  color: Color(0xFF8FA6B4),
                  fontSize: 11,
                  fontWeight: FontWeight.w700)),
        ),
        for (final pg in targets)
          PopupMenuItem<String>(
            value: pg.id,
            height: 36,
            child: Row(children: [
              // ページ種別ごとのアイコン (= マップ一覧と同じ見た目。
              //   今開いているページだけは「ここ」 の印を優先)。
              Icon(
                  pg.id == curId
                      ? Icons.radio_button_checked_rounded
                      : _MindMapScreenState._pageKindIconOf(pg).$1,
                  size: 15,
                  color: pg.id == curId
                      ? const Color(0xFF43B97F)
                      : _MindMapScreenState._pageKindIconOf(pg).$2),
              const SizedBox(width: 8),
              Flexible(
                child: Text(pg.name,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style:
                        const TextStyle(color: Colors.white, fontSize: 12.5)),
              ),
            ]),
          ),
      ],
    );
    if (chosen == null) return null;
    return _ensureNode(pageId: chosen);
  }

  /// PDF 描画エリアの GlobalKey (= 右クリック位置からメモの xRatio/yRatio を
  /// 算出するために、 エリアのサイズを取得するのに使う)。
  final GlobalKey _pdfAreaKey = GlobalKey();

  /// 掴んで動かすモード (= ユーザー要望: クリックしながらドラッグで表示領域を
  /// 移動)。 ON の間は文字選択の代わりにパンになる。 設定は次回も引き継ぐ。
  bool _pdfPanMode = false;

  /// PDF 図形・線 描き込みモード (= ユーザー要望)。
  bool _pdfDrawActive = false;

  /// PDF への描き込み (ペン / 直線 / 矢印 / 四角 / 楕円) の ON/OFF。
  /// ヘッダーの常設ボタンと設定メニューの両方から呼ぶ。
  void _togglePdfDrawMode() {
    setState(() => _pdfDrawActive = !_pdfDrawActive);
    if (_pdfDrawActive && mounted) {
      _appSnack(
        context,
        SnackBar(
            content:
                Text(context.read<MindMapProvider>().t('pdfdraw.hint')),
            duration: const Duration(seconds: 3)),
      );
    }
  }

  /// 描き込み保存後にビューアを読み直すための鍵。
  int _pdfDrawReloadTick = 0;
  static const String _kPdfPanModeKey = 'pdfPanMode';

  Future<void> _loadPdfPanMode() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final v = prefs.getBool(_kPdfPanModeKey);
      if (v != null && mounted) setState(() => _pdfPanMode = v);
    } catch (_) {}
  }

  Future<void> _togglePdfPanMode() async {
    setState(() => _pdfPanMode = !_pdfPanMode);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool(_kPdfPanModeKey, _pdfPanMode);
    } catch (_) {}
    if (!mounted) return;
    final p = context.read<MindMapProvider>();
    _appSnack(
      context,
      SnackBar(
        content: Text(
            p.t(_pdfPanMode ? 'pdf.panModeOn' : 'pdf.panModeOff'),
            style: const TextStyle(fontSize: 12)),
        duration: const Duration(seconds: 2),
      ),
    );
  }

  /// PDF 内のリンクを踏んだ時の確認 (= ユーザー要望: 英語のままなので
  /// 多言語に + 外部アプリか、 アプリ内の別タブかを選べるように)。
  Future<void> _showPdfHyperlinkDialog(String? rawUrl) async {
    final url = (rawUrl ?? '').trim();
    if (url.isEmpty || !mounted) return;
    final p = context.read<MindMapProvider>();
    final choice = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        shape:
            RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        title: Row(children: [
          const Icon(Icons.link_rounded, color: Color(0xFF4FC3F7), size: 20),
          const SizedBox(width: 8),
          Expanded(
            child: Text(p.t('pdfLink.title'),
                style: const TextStyle(
                    color: Colors.white,
                    fontSize: 15,
                    fontWeight: FontWeight.w700)),
          ),
        ]),
        content: SizedBox(
          width: 420,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Container(
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.06),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: SelectableText(url,
                    maxLines: 3,
                    style: const TextStyle(
                        color: Color(0xFF9FD8F0),
                        fontSize: 12,
                        height: 1.4)),
              ),
              const SizedBox(height: 12),
              Text(p.t('pdfLink.chooseHow'),
                  style: const TextStyle(
                      color: Colors.white54, fontSize: 11.5, height: 1.4)),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, 'cancel'),
            child: Text(p.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          TextButton.icon(
            icon: const Icon(Icons.open_in_browser_rounded,
                size: 16, color: Color(0xFF4FC3F7)),
            label: Text(p.t('pdfLink.external'),
                style:
                    const TextStyle(color: Color(0xFF4FC3F7), fontSize: 12.5)),
            onPressed: () => Navigator.pop(dctx, 'external'),
          ),
          ElevatedButton.icon(
            style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFF6C63FF),
              foregroundColor: Colors.white,
            ),
            icon: const Icon(Icons.tab_rounded, size: 16),
            label: Text(p.t('pdfLink.inAppTab'),
                style: const TextStyle(fontSize: 12.5)),
            onPressed: () => Navigator.pop(dctx, 'inapp'),
          ),
        ],
      ),
    );
    if (choice == null || choice == 'cancel' || !mounted) return;
    if (choice == 'external') {
      try {
        await launchUrl(Uri.parse(url), mode: LaunchMode.externalApplication);
      } catch (e) {
        if (!mounted) return;
        _appSnack(
          context,
          SnackBar(
            content: Text('${p.t('pdfLink.openFailed')}: $e'),
            backgroundColor: const Color(0xFFE57373),
          ),
        );
      }
      return;
    }
    // アプリ内の別タブ (= もう 1 枚ビューアを重ねて開く)。
    final isPdfLink = url.toLowerCase().split('?').first.endsWith('.pdf');
    await showDialog<void>(
      context: context,
      useRootNavigator: true,
      barrierColor: Colors.black.withValues(alpha: 0.92),
      builder: (dctx) => Dialog.fullscreen(
        backgroundColor: const Color(0xFF1A1A24),
        child: _InAppViewerDialog(url: url, isPdf: isPdfLink),
      ),
    );
  }

  /// 全画面 PDF ビューア上の右クリックメニュー。
  /// 右クリック位置にメモを追加できる + PDF ページ非表示 / シャッフル等。
  /// [localPos] は PDF エリア内のローカル座標 (メモ配置位置の算出に使う)。
  // ── ピンチ / Ctrl+ホイールで PDF を拡大縮小する (= ユーザー要望) ──
  // トラックパッドのピンチは PointerPanZoom、 一部環境では PointerScaleEvent
  // で届く。 マウスは Ctrl+ホイールを拡大縮小に割り当てる。
  double _pinchBaseZoom = 1.0;

  void _pdfSetZoom(double z) {
    final c = _pdfViewerCtrl;
    if (c == null) return;
    try {
      c.zoomLevel = z.clamp(1.0, 8.0).toDouble();
      // ズーム直後の onPageChanged 巻き添えを抑制 (キー操作と同じ扱い)。
      _suppressPageChangeUntilMs =
          DateTime.now().millisecondsSinceEpoch + 700;
    } catch (_) {}
  }

  void _pdfPinchStart() {
    try {
      _pinchBaseZoom = _pdfViewerCtrl?.zoomLevel ?? 1.0;
    } catch (_) {
      _pinchBaseZoom = 1.0;
    }
  }

  void _pdfPinchUpdate(double scale) {
    if (scale <= 0) return;
    _pdfSetZoom(_pinchBaseZoom * scale);
  }

  void _pdfWheelZoom(PointerSignalEvent e) {
    if (e is! PointerScrollEvent) return;
    if (!HardwareKeyboard.instance.isControlPressed &&
        !HardwareKeyboard.instance.isMetaPressed) {
      return; // Ctrl 無しは通常のスクロール
    }
    final cur = _pdfViewerCtrl?.zoomLevel ?? 1.0;
    // ホイール 1 ノッチ (120) で 0.1 くらい動かす (= 細かく効く)。
    _pdfSetZoom(cur - e.scrollDelta.dy / 1200.0);
  }

  void _showFullscreenPdfContextMenu(Offset globalPos,
      {Offset? localPos}) async {
    if (_pdfFilePath == null || _pdfViewerCtrl == null) return;
    final provider = context.read<MindMapProvider>();
    final horiz = provider.pdfScrollHorizontal;
    // ── 右クリックメニューは 2 つだけ (= ユーザー要望: 縦/横読みの
    //    切り替えと付箋メモを貼るだけでいい)。 ページへの追加 / 移動は
    //    ツールバーの「ページに追加」 と設定メニューから使える。 ──
    final selected = await showMenu<String>(
      context: context,
      position: RelativeRect.fromLTRB(
          globalPos.dx, globalPos.dy, globalPos.dx + 1, globalPos.dy + 1),
      color: const Color(0xFF1E2024),
      items: [
        // 縦読み ⇔ 横読み
        PopupMenuItem<String>(
          value: 'toggleScrollDir',
          child: Row(children: [
            Icon(horiz ? Icons.swap_vert_rounded : Icons.swap_horiz_rounded,
                color: const Color(0xFF4FC3F7), size: 18),
            const SizedBox(width: 8),
            Text(
                provider.t(
                    horiz ? 'pdf.readVertical' : 'pdf.readHorizontal'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        // 表示領域に付箋を貼ってメモを書く
        PopupMenuItem<String>(
          value: 'stickyMemo',
          child: Row(children: [
            const Icon(Icons.push_pin_rounded,
                color: Color(0xFFFFC107), size: 18),
            const SizedBox(width: 8),
            Text(provider.t('pdf.stickyMemoHere'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        // ── 図形・線を描き込む (= ユーザー要望: 本文中の右クリックからも
        //    描き込みを始められるように) ──
        PopupMenuItem<String>(
          value: 'drawShapes',
          child: Row(children: [
            Icon(_pdfDrawActive ? Icons.draw_rounded : Icons.draw_outlined,
                color: const Color(0xFF5FD3B2), size: 18),
            const SizedBox(width: 8),
            Text(provider.t('pdf.drawShapes'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
      ],
    );
    if (!mounted || selected == null) return;
    switch (selected) {
      case 'toggleScrollDir':
        _suppressPdfPageChangeBriefly();
        await provider.setPdfScrollHorizontal(!horiz);
        break;
      case 'stickyMemo':
        // 付箋は添付ノードにぶら下がるので、 先にマップへ載せる。
        final id = await _ensureNode();
        if (id == null || !mounted) break;
        setState(() => _placingMemo = true);
        _appSnack(
          context,
          SnackBar(
            content: Text(provider.t('pdf.stickyMemoHint'),
                style: const TextStyle(fontSize: 12)),
            duration: const Duration(seconds: 3),
          ),
        );
        break;
      case 'drawShapes':
        // 描き込みモードの ON/OFF (= ヘッダーのボタンと同じ働き)。
        _togglePdfDrawMode();
        break;
    }
  }

  // Windows: webview_windows (URL モード時のみ使用)
  wv_win.WebviewController? _winCtrl;
  bool _winReady = false;
  String? _winError;
  String _oauthLastSafeServiceUrl = '';
  bool _oauthHandoffInProgress = false;
  DateTime? _lastOAuthHandoffAt;
  // macOS / Linux / iOS / Android: flutter_inappwebview (URL モード時)
  iaw.InAppWebViewController? _iawCtrl;
  // PDF モード: syncfusion ネイティブ描画コントローラ
  // SfPdfViewer 自身がドキュメント読み込みを行うので、 こちらでは
  // ファイルパスを保持してウィジェットに渡すだけで OK。
  sf_pdf.PdfViewerController? _pdfViewerCtrl;
  String? _pdfFilePath;
  String? _pdfError;
  int _pdfTotalPages = 0;

  /// 左右キーの挙動: false = ページ移動 (既定) / true = 表示領域を横に移動 (パン)。
  /// PDF 右クリックメニューから切り替える (ユーザー要望)。
  bool _pdfArrowPanMode = false;

  /// 現在の PDF ズームレベル (全画面)。 拡大時に表示幅を広げて横スクロールを
  /// 減らすために追跡する (ユーザー要望)。
  double _pdfZoomLevel = 1.0;

  // ── ページ全体表示 (フィット) モード ───────────────────────────
  // syncfusion は minZoom が 1.0 (= ページ幅フィット) で固定されており、
  // 縦長ページの全体をビューアに収めることが出来ない (ユーザー要望:
  // 「一番拡大率を下げてもその一ページの全体が見えない」)。
  // 対策として、 現在ページをラスタライズした画像を BoxFit.contain で
  // 表示するオーバーレイを被せる。 縦横比が合わない分は余白になる
  // (= ユーザー了承: 「余白を入れても構わない」)。 画像なのでテキスト選択は
  // 出来ないが、 ページめくり (←/→・ページジャンプ) はそのまま効く。
  bool _fitPageMode = false;
  Uint8List? _fitPageImage;
  int _fitPageRenderedFor = -1;
  bool _fitPageRendering = false;
  bool _spreadPageMode = false;
  bool _spreadFitPageMode = false;
  final Map<int, printing.PdfRaster> _spreadPageImages =
      <int, printing.PdfRaster>{};
  final Map<int, Size> _spreadPageImageSizes = <int, Size>{};
  /// 見開きを開いた時の既定の拡大率 (= ユーザー要望: 拡大率が小さ過ぎる)。
  /// 1.0 = 画面に収まるまで縮小 (従来)。 はみ出した分はドラッグで見る。
  static const double _kSpreadInitialZoom = 1.35;

  final TransformationController _spreadTransformController =
      TransformationController();

  /// 見開きの倍率を既定へ戻す。
  /// InteractiveViewer は原点基準で拡大するため、 中心がずれないように
  /// 平行移動で打ち消す (= ユーザー要望: 見開きをもう少し大きく)。
  void _resetSpreadZoom() {
    const z = _kSpreadInitialZoom;
    if (z == 1.0) {
      _spreadTransformController.value = Matrix4.identity();
      return;
    }
    Size view;
    try {
      view = MediaQuery.of(context).size;
    } catch (_) {
      _spreadTransformController.value = Matrix4.identity();
      return;
    }
    _spreadTransformController.value = Matrix4.identity()
      ..setEntry(0, 0, z)
      ..setEntry(1, 1, z)
      ..setTranslationRaw(
          -(z - 1) * view.width / 2, -(z - 1) * view.height / 2, 0);
  }
  int _spreadRenderedForStart = -1;
  bool _spreadRendering = false;
  bool _spreadRenderPending = false;
  int _spreadRenderGeneration = 0;
  static const Duration _spreadRasterTimeout = Duration(seconds: 18);
  static const int _spreadRasterMaxPixels = 8 * 1000 * 1000;
  // PDF バイト列はページめくりの度に読み直すと重いので一度だけ読んでキャッシュ
  //   する (= ユーザー報告: メモ/AI 欄が開くタイミングでフリーズ。 ラスタ処理の
  //   負荷を減らす一手)。
  Uint8List? _fitPageBytes;
  // ページめくりの度に main-isolate でラスタすると、 AI/メモ欄が同時に開いている
  //   状態で処理が積み上がってクラッシュする (= ユーザー報告: ページをめくると
  //   落ちる)。 連続めくりでは「最後に落ち着いたページ」 だけを 1 回ラスタする
  //   よう debounce する。
  Timer? _fitPageDebounce;
  Timer? _spreadPageDebounce;

  /// ページ変更時の再ラスタを debounce する。 連続めくりで毎回ラスタして
  /// main-isolate を詰まらせない。 直近のページが落ち着いてから 1 回だけ実行。
  void _scheduleFitPageRender() {
    // フリーズ対策: ページ全体表示では PDF を画像化しない。
    // 旧実装の Printing.raster は AI WebView と同時に動くと UI スレッドを
    // 詰まらせるため、現在はライブの SfPdfViewer を幅だけ縮めて表示する。
  }

  Future<void> _renderFitPage() async {
    // no-op: ラスタライズ禁止。_buildPureWebView 側でライブ縮小表示する。
  }

  void _toggleFitPage() {
    setState(() {
      _fitPageMode = !_fitPageMode;
      if (_fitPageMode) {
        _spreadPageMode = false;
        _spreadFitPageMode = false;
        _spreadRenderGeneration++;
        _spreadRenderPending = false;
        _fitPageBytes = null;
        _resetSpreadZoom();
        _spreadPageImages.clear();
        _spreadPageImageSizes.clear();
        _spreadRenderedForStart = -1;
        _fitPageImage = null;
        _fitPageRenderedFor = -1;
      }
    });
    if (_fitPageMode) {
      _suppressPdfPageChangeBriefly();
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        try {
          _pdfViewerCtrl?.jumpToPage(_currentPage);
        } catch (_) {}
      });
    }
    // 既定として永続化 (= 次回以降の PDF 初期表示に反映。 ページ全体表示が
    //   不要なら 1 度オフにすれば以降オフのまま)。
    context.read<MindMapProvider>().setPdfFitPageDefault(_fitPageMode);
  }

  int get _spreadStartPage {
    if (_pdfTotalPages <= 1) return 1;
    final page = _currentPage.clamp(1, _pdfTotalPages).toInt();
    if (page <= 1) return 1;
    return page.isEven ? page : page - 1;
  }

  bool _canEnableSpreadRaster() {
    final path = _pdfFilePath;
    if (path != null && _isPdfSpreadRasterSourceSafe(path)) return true;
    final limitMb = _pdfSpreadRasterSourceLimitBytes ~/ (1024 * 1024);
    ScaffoldMessenger.maybeOf(context)?.showSnackBar(
      SnackBar(
        content: Text(
          'このPDFはサイズが大きいため、安定性を優先して見開き画像表示を無効にしました（上限 ${limitMb}MB）。',
        ),
        duration: const Duration(seconds: 4),
      ),
    );
    return false;
  }

  void _adjustSpreadZoom(bool zoomIn) {
    final current =
        _spreadTransformController.value.getMaxScaleOnAxis().clamp(0.5, 6.0);
    final next = (current + (zoomIn ? 0.1 : -0.1)).clamp(0.5, 6.0);
    _spreadTransformController.value = Matrix4.identity()
      ..setEntry(0, 0, next)
      ..setEntry(1, 1, next);
  }

  void _scheduleSpreadPageRender(
      [Duration delay = const Duration(milliseconds: 320)]) {
    _spreadPageDebounce?.cancel();
    if (!_spreadFitPageMode) return;
    // 1 文書につき raster は常に 1 本だけ。ページ送りが重なった場合は
    // pending を立て、実行中の処理が終わった後に「最後のページ」だけ描画する。
    if (_spreadRendering) {
      _spreadRenderPending = true;
      return;
    }
    _spreadPageDebounce = Timer(delay, () {
      if (mounted && _spreadFitPageMode) _renderSpreadPages();
    });
  }

  /// 指定ページ群のうち未キャッシュのものをラスタしてキャッシュへ足す。
  /// [prefetch] = true は先読み (= エラー時のモード解除や再スケジュールを
  /// 行わない)。 戻り値: 対象ページが全てキャッシュ済みになったか。
  ///
  /// ユーザー要望 2026-07「見開きページモードで開くと PDF の読み込みが
  /// 重たくなってフリーズしてしまう」 への対応:
  ///   - 旧実装はページをめくる度にキャッシュを全消しして 2 ページを
  ///     ラスタし直していた (= 巨大 PDF ではめくる度に全文書パースが
  ///     走り、 行き来するだけで毎回固まる)。
  ///   - 新実装はページ番号キーの追加型キャッシュ + 隣の見開きの先読みで、
  ///     一度表示した/先読み済みの見開きへは即座に切り替わる。
  Future<bool> _rasterSpreadPagesInto(List<int> pages,
      {bool prefetch = false}) async {
    final path = _pdfFilePath;
    if (path == null) return false;
    final need = <int>[
      for (final p in pages)
        if (p >= 1 &&
            (_pdfTotalPages <= 0 || p <= _pdfTotalPages) &&
            !_spreadPageImages.containsKey(p))
          p
    ];
    if (need.isEmpty) return true;
    final requestedStart = pages.first;
    if (_spreadRendering) {
      if (!prefetch) _spreadRenderPending = true;
      return false;
    }
    _spreadRendering = true;
    final generation = _spreadRenderGeneration;
    try {
      if (!_isPdfSpreadRasterSourceSafe(path)) {
        throw StateError('PDF is too large for safe spread rasterization');
      }
      // Printing.raster は Uint8List をプラットフォーム側へコピーする。ここを
      // フィールドに保持すると、SfPdfViewer の文書データ + Dart の PDF バイト +
      // ネイティブ側コピーが見開き中ずっと共存するため、大きな PDF で急激に
      // メモリを消費する。1 回の描画にだけローカル保持して、完了後に解放する。
      final pdfBytes = await File(path).readAsBytes();
      if (!mounted ||
          !_spreadFitPageMode ||
          generation != _spreadRenderGeneration ||
          (!prefetch && _spreadStartPage != requestedStart)) {
        return false;
      }
      final rasterDpi =
          (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) ? 56.0 : 64.0;
      // printing 5.14.3 の Windows 実装は MethodChannel ハンドラ内で
      // PDFium のページループを同期実行する。複数ページを一度に渡すと、Dart の
      // timeout や描画フレームが全ページ終了まで動けない。PDF の再解析回数は
      // 増えるが、1 ページずつネイティブ処理を返し、間にフレームと世代確認を
      // 挟むことで、連続したUI停止と複数RGBAバッファの滞留を防ぐ。
      for (var i = 0; i < need.length; i++) {
        final n = need[i];
        printing.PdfRaster? page;
        await for (final raster in printing.Printing.raster(
          pdfBytes,
          pages: <int>[n - 1],
          dpi: rasterDpi,
        ).timeout(_spreadRasterTimeout)) {
          if (page != null) {
            throw StateError('PDF rasterizer returned duplicate page data');
          }
          page = raster;
        }
        if (page == null) {
          throw StateError('PDF rasterizer returned incomplete spread pages');
        }
        final pixelCount = page.width * page.height;
        if (pixelCount > _spreadRasterMaxPixels) {
          // printing API はRGBA確保後にだけ寸法を返すため事前判定はできない。
          // ここで止めることで、少なくとも ui.Image 側の追加確保は防止する。
          throw StateError('PDF page is too large for safe spread rendering');
        }
        if (!mounted ||
            !_spreadFitPageMode ||
            generation != _spreadRenderGeneration ||
            (!prefetch && _spreadStartPage != requestedStart)) {
          return false;
        }
        // PdfRaster は既に RGBA 画像。toPng() で圧縮して Image.memory で再び
        // 展開する旧経路は UI アイソレートを詰まらせるため、そのまま保持する。
        _spreadPageImages[n] = page;
        _spreadPageImageSizes[n] =
            Size(page.width.toDouble(), page.height.toDouble());
        if (i + 1 < need.length) {
          await WidgetsBinding.instance.endOfFrame;
          if (!mounted ||
              !_spreadFitPageMode ||
              generation != _spreadRenderGeneration ||
              (!prefetch && _spreadStartPage != requestedStart)) {
            return false;
          }
        }
      }
      // 見開き画像は現在の 1～2 ページだけを保持する。RGBA ページ画像と
      // Flutter の ui.Image の両方がメモリを使うため、複数見開きの先読み
      // キャッシュは低メモリ端末での終了原因になる。
      final keep = pages.toSet();
      for (final cached in _spreadPageImages.keys.toList()) {
        if (keep.contains(cached)) continue;
        _spreadPageImages.remove(cached);
        _spreadPageImageSizes.remove(cached);
      }
      return true;
    } catch (e) {
      debugPrint('見開き全体表示の生成失敗: $e');
      if (!prefetch &&
          mounted &&
          _spreadFitPageMode &&
          generation == _spreadRenderGeneration) {
        setState(() {
          _spreadFitPageMode = false;
          _fitPageBytes = null;
          _spreadPageImages.clear();
          _spreadPageImageSizes.clear();
          _spreadRenderedForStart = -1;
          _resetSpreadZoom();
        });
        _appSnack(
          context,
          SnackBar(
            content: Text(context.read<MindMapProvider>().t('pdf.pageImageFallback')),
            duration: const Duration(seconds: 4),
          ),
        );
      }
      return false;
    } finally {
      _spreadRendering = false;
      // 先読み中にページ送りされた場合も、先読み完了後に保留中の前景描画を
      // 必ず再開する。旧実装は prefetch の finally では pending を処理せず、
      // 「見開きモードを準備中」のまま止まっていた。
      if (mounted && _spreadFitPageMode && _spreadRenderPending) {
        _spreadRenderPending = false;
        _scheduleSpreadPageRender();
      }
    }
  }

  Future<void> _renderSpreadPages() async {
    if (!_spreadFitPageMode) return;
    final start = _spreadStartPage;
    final pages = <int>[start];
    if (start > 1 && start + 1 <= _pdfTotalPages) pages.add(start + 1);
    final ok = await _rasterSpreadPagesInto(pages);
    if (!mounted || !_spreadFitPageMode) return;
    if (!ok || _spreadStartPage != start) return;
    setState(() => _spreadRenderedForStart = start);
    // ── 隣の見開き (次/前) を背景で先読みして、 ページ送りを即時に ──
  }

  void _toggleSpreadPages() {
    _toggleSpreadFitPage();
  }

  /// 見開きに入る前のメモ / AI パネルの開閉状態 (戻す時に復元する)。
  bool? _spreadPrevMemoOpen;
  bool? _spreadPrevAiOpen;

  void _toggleSpreadFitPage() {
    final enabling = !_spreadFitPageMode;
    if (enabling && !_canEnableSpreadRaster()) return;
    setState(() {
      // ── 見開き中は横幅を全部ページに使う (= ユーザー要望: 見開きモードで
      //    画面が小さくなり過ぎる)。 抜けたら元の開閉状態に戻す。 ──
      if (enabling) {
        _spreadPrevMemoOpen = _memoPanelOpen;
        _spreadPrevAiOpen = _aiPanelOpen;
        _memoPanelOpen = false;
        _aiPanelOpen = false;
      } else {
        if (_spreadPrevMemoOpen != null) _memoPanelOpen = _spreadPrevMemoOpen!;
        if (_spreadPrevAiOpen != null) _aiPanelOpen = _spreadPrevAiOpen!;
        _spreadPrevMemoOpen = null;
        _spreadPrevAiOpen = null;
      }
      _spreadFitPageMode = enabling;
      _spreadRenderGeneration++;
      _spreadRenderPending = false;
      if (_spreadFitPageMode) {
        _fitPageMode = false;
        _spreadPageMode = false;
        _fitPageImage = null;
        _fitPageRenderedFor = -1;
        _spreadRenderedForStart = -1;
      } else {
        _fitPageBytes = null;
        _spreadPageImages.clear();
        _spreadPageImageSizes.clear();
        _spreadRenderedForStart = -1;
        _resetSpreadZoom();
      }
    });
    if (_spreadFitPageMode) {
      _suppressPdfPageChangeBriefly();
      // このフレームで背面 SfPdfViewer をツリーから外し、文書解析・ページ描画と
      // Printing.raster が同時に走らないようにする。解放処理用にさらに少し待つ。
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _scheduleSpreadPageRender(const Duration(milliseconds: 480));
      });
    } else {
      // 見開き中は背面 SfPdfViewer を動かさないため、解除時に一度だけ同期する。
      _suppressPdfPageChangeBriefly();
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        try {
          _pdfViewerCtrl?.jumpToPage(_currentPage);
        } catch (_) {}
      });
    }
  }

  void _jumpSpreadPages(int delta) {
    if (_pdfTotalPages <= 0) return;
    final target = (_spreadStartPage + delta).clamp(1, _pdfTotalPages).toInt();
    _spreadPageDebounce?.cancel();
    // 見開き画像と背面 SfPdfViewer の二重描画を避ける。ページ番号と保存値だけ
    // 更新し、SfPdfViewer は見開き解除時に現在ページへ同期する。
    setState(() {
      _currentPage = target;
      _pageInputCtrl.text = '$target';
      _spreadRenderedForStart = -1;
    });
    if (_pdfFilePath != null) {
      context.read<MindMapProvider>().setLastPdfPage(_pdfFilePath!, target);
    }
    _scheduleSpreadPageRender();
  }

  /// フィットモード中に表示する、 現在ページのラスタ画像オーバーレイ。
  Widget _buildFitPageOverlay() {
    return const SizedBox.shrink();
  }

  Widget _buildSpreadPageImage(int pageNumber) {
    final pageSize = _spreadPageImageSizes[pageNumber] ?? const Size(794, 1123);
    return SizedBox(
      width: pageSize.width,
      height: pageSize.height,
      child: Image(
        image: printing.PdfRasterImage(_spreadPageImages[pageNumber]!),
        fit: BoxFit.fill,
        gaplessPlayback: false,
        filterQuality: FilterQuality.low,
      ),
    );
  }

  Widget _buildSpreadPageOverlay() {
    if (!_spreadFitPageMode) return const SizedBox.shrink();
    final start = _spreadStartPage;
    final pages = <int>[start];
    if (start > 1 && start + 1 <= _pdfTotalPages) pages.add(start + 1);
    // キャッシュにあれば即表示 (= 先読み済みの見開きは「準備中」を出さない)。
    final ready = pages.every((page) => _spreadPageImages.containsKey(page));
    final pageLabel = pages.length == 1
        ? '$start / $_pdfTotalPages'
        : '$start-${pages.last} / $_pdfTotalPages';
    return Positioned.fill(
      child: Container(
        color: Colors.white,
        // ── 見開きは画面いっぱいに使う (= ユーザー要望: 見開きモードだと
        //    画面が小さくなり過ぎる)。 余白は最小限に。 ──
        padding: const EdgeInsets.symmetric(horizontal: 2, vertical: 2),
        child: Stack(
          children: [
            Positioned.fill(
              child: ready
                  ? InteractiveViewer(
                      transformationController: _spreadTransformController,
                      minScale: 0.5,
                      maxScale: 6.0,
                      child: Center(
                        child: FittedBox(
                          fit: BoxFit.contain,
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            crossAxisAlignment: CrossAxisAlignment.center,
                            children: [
                              for (int i = 0; i < pages.length; i++) ...[
                                _buildSpreadPageImage(pages[i]),
                                if (i != pages.length - 1)
                                  const SizedBox(width: 4),
                              ],
                            ],
                          ),
                        ),
                      ),
                    )
                  : Center(
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: const [
                          CircularProgressIndicator(strokeWidth: 2),
                          SizedBox(height: 12),
                          Text(
                            '見開きモードを準備中...',
                            style:
                                TextStyle(color: Colors.black54, fontSize: 13),
                          ),
                        ],
                      ),
                    ),
            ),
            Positioned(
              left: 12,
              top: 12,
              child: Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                decoration: BoxDecoration(
                  color: Colors.black.withValues(alpha: 0.55),
                  borderRadius: BorderRadius.circular(18),
                ),
                child: Text(
                  '見開き全体 $pageLabel',
                  style: const TextStyle(color: Colors.white70, fontSize: 12),
                ),
              ),
            ),
            Positioned(
              left: 10,
              top: 0,
              bottom: 0,
              child: Center(
                child: IconButton.filledTonal(
                  tooltip: context.read<MindMapProvider>().t('pdf.prevSpread'),
                  onPressed: start <= 1 ? null : () => _jumpSpreadPages(-2),
                  icon: const Icon(Icons.chevron_left_rounded),
                ),
              ),
            ),
            Positioned(
              right: 10,
              top: 0,
              bottom: 0,
              child: Center(
                child: IconButton.filledTonal(
                  tooltip: context.read<MindMapProvider>().t('pdf.nextSpread'),
                  onPressed: start >= _pdfTotalPages
                      ? null
                      : () => _jumpSpreadPages(2),
                  icon: const Icon(Icons.chevron_right_rounded),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  double _pdfLiveWidthFactor(BoxConstraints constraints) {
    if (!_fitPageMode) return 1.0;
    final width = constraints.maxWidth;
    final height = constraints.maxHeight;
    if (!width.isFinite || !height.isFinite || width <= 0 || height <= 0) {
      return 0.62;
    }
    const a4HeightOverWidth = 1.41421356237;
    return (height / (width * a4HeightOverWidth) * 0.96)
        .clamp(0.28, 1.0)
        .toDouble();
  }

  // ビューアタイプを問わない共通状態
  int _currentPage = 1;

  /// ズーム操作 (Ctrl + / -) の直後に onPageChanged が巻き添えで発火して
  /// ページ番号が動くのを防ぐための抑制期限 (epoch ms)。
  int _suppressPageChangeUntilMs = 0;

  /// PDF の onPageChanged を一定時間だけ抑制する (= ユーザー要望: サイド
  /// メニューを開いたり幅を変えると SfPdfViewer が再レイアウトして
  /// onPageChanged が巻き添え発火し、 表示ページが飛んでしまうのを防ぐ)。
  /// パネルの開閉・リサイズの直前に呼ぶ。
  void _suppressPdfPageChangeBriefly([int ms = 1500]) {
    final until = DateTime.now().millisecondsSinceEpoch + ms;
    if (until > _suppressPageChangeUntilMs) {
      _suppressPageChangeUntilMs = until;
    }
    // ── サイドバー (メモ/AI) 開閉で SfPdfViewer がリサイズすると、
    //    内部のスクロール位置がリサイズ比率で動いてしまい、 表示ページが
    //    変わってしまうバグの修正 (= ユーザー要望) ──
    // onPageChanged は上の抑制機構で _currentPage への反映を防げるが、
    //   画面が実際に動いてしまうのは別問題。 ここでレイアウト完了後の
    //   タイミングで明示的に jumpToPage(_currentPage) を呼び戻すことで、
    //   ページ表示を固定する。 ms 未満で複数回呼ばれても上書きされるだけで害なし。
    final preservedPage = _currentPage;
    if (preservedPage < 1) return;
    // 300ms と 700ms の 2 段で復元 (1 段目で間に合わない大きな PDF 対策)
    void restore() {
      if (!mounted) return;
      if (preservedPage < 1 || preservedPage > _pdfTotalPages) return;
      try {
        _pdfViewerCtrl?.jumpToPage(preservedPage);
      } catch (_) {}
    }

    Future.delayed(const Duration(milliseconds: 300), restore);
    Future.delayed(const Duration(milliseconds: 700), restore);
  }

  late String _currentUrl;
  String _title = '';
  bool _memoPanelOpen = true;
  // ─── 音声読み上げ (TTS) (= ユーザー要望: PDF の音声読み上げ) ───
  /// 読み上げコントローラ。 初回利用時に生成する。
  ReadAloudController? _reader;

  /// 読み上げ操作バーを表示中か。
  bool _readerVisible = false;

  /// PDF 本文を抽出して現在ページから読み上げ開始する。
  Future<void> _startReadAloud() async {
    final path = _pdfFilePath;
    final provider = context.read<MindMapProvider>();
    final messenger = ScaffoldMessenger.maybeOf(context);
    if (path == null || !File(path).existsSync()) {
      messenger?.showSnackBar(SnackBar(
          content: Text(provider.t('pdf.noReadablePdf')),
          duration: const Duration(seconds: 2)));
      return;
    }
    // ── 開始ページを指定 (= ユーザー要望)。 既定は今見ているページ (動的割当) ──
    final total = (_pdfTotalPages > 0) ? _pdfTotalPages : null;
    final defStart = (_currentPage >= 1) ? _currentPage : 1;
    final start = await _askReadAloudStartPage(context, defStart, total);
    if (start == null || !mounted) return; // キャンセル
    messenger?.showSnackBar(SnackBar(
        content: Text(provider.t('pdf.loadingText')),
        duration: const Duration(seconds: 1)));
    final loc = provider.speechLocaleId;
    _reader ??= ReadAloudController(language: loc);
    // ページ追従リスナを一度だけ張る (= 読み上げページと表示ページを一致させる)。
    _reader!.removeListener(_followReaderPage);
    _reader!.addListener(_followReaderPage);
    _lastFollowedPage = -1;
    if (total != null) {
      // ── ページ毎に抽出してチャンクへページ番号を割り当て、 読み上げの進行に
      //    合わせて表示ページを追従させる (= ユーザー要望: 一致させる) ──
      final perPage = await _extractPdfPerPage(path, start, total, strip: true);
      if (!mounted) return;
      if (perPage == null || perPage.every((t) => t.trim().isEmpty)) {
        messenger?.showSnackBar(SnackBar(
            content: Text(provider.t('pdf.noTextExtract')),
            duration: const Duration(seconds: 3)));
        return;
      }
      final chunks = <String>[];
      final pages = <int>[];
      for (int k = 0; k < perPage.length; k++) {
        final pageNo = start + k;
        for (final c in ReadAloudController.chunkText(perPage[k])) {
          chunks.add(c);
          pages.add(pageNo);
        }
      }
      if (chunks.isEmpty) {
        messenger?.showSnackBar(SnackBar(
            content: Text(provider.t('pdf.noTextExtract')),
            duration: const Duration(seconds: 3)));
        return;
      }
      setState(() => _readerVisible = true);
      final ok = await _reader!
          .startChunks(chunks, pages: pages, sampleText: chunks.first);
      if (!mounted) return;
      if (!ok) {
        setState(() => _readerVisible = false);
        messenger?.showSnackBar(SnackBar(
            content: Text(provider.t('pdf.ttsUnavailable')),
            duration: const Duration(seconds: 3)));
      }
      return;
    }
    // フォールバック: ページ数不明なら従来どおり全文を一括読み上げ (追従なし)。
    final text = await _extractPdfTextForAi(path, stripBoilerplate: true);
    if (!mounted) return;
    if (text == null || text.trim().isEmpty) {
      messenger?.showSnackBar(SnackBar(
          content: Text(provider.t('pdf.noTextExtract')),
          duration: const Duration(seconds: 3)));
      return;
    }
    setState(() => _readerVisible = true);
    final ok = await _reader!.start(text);
    if (!mounted) return;
    if (!ok) {
      setState(() => _readerVisible = false);
      messenger?.showSnackBar(SnackBar(
          content: Text(provider.t('pdf.ttsUnavailable')),
          duration: const Duration(seconds: 3)));
    }
  }

  /// 読み上げ中チャンクの元ページへ PDF をジャンプし、 表示ページを読み上げ
  /// ページに一致させる (= ユーザー要望: 読み上げページと開いているページの一致)。
  int _lastFollowedPage = -1;
  void _followReaderPage() {
    if (!mounted) return;
    final p = _reader?.currentSourcePage;
    if (p == null || p == _lastFollowedPage) return;
    _lastFollowedPage = p;
    if (p >= 1 && _pdfTotalPages > 0 && p <= _pdfTotalPages) {
      try {
        _pdfViewerCtrl?.jumpToPage(p);
      } catch (_) {}
    }
  }

  void _stopReadAloud() {
    _reader?.removeListener(_followReaderPage);
    _reader?.stop();
    if (mounted) setState(() => _readerVisible = false);
  }

  // ─── PDF ビューア横の生成 AI チャット欄 (= ユーザー要望) ───
  /// AI チャット欄を開いているか。
  bool _aiPanelOpen = false;

  /// メモ欄 / AI 欄の「場所」 を、 中身より先に確保しておくか。
  /// 立ち上がりで PDF を全幅 → 狭める と二度レイアウトするのを避けるため
  /// (= ユーザー要望: 立ち上げをもっと速く)。
  bool _panelSlotsReserved = false;

  /// 場所取りをやめる。 中身が入った後 (または読み込みに失敗した後) に呼ぶ。
  /// ここを忘れると、 利用者がパネルを閉じても空の帯が残ってしまう。
  void _releasePanelSlotReservation() {
    if (!_panelSlotsReserved) return;
    if (!mounted) {
      _panelSlotsReserved = false;
      return;
    }
    setState(() => _panelSlotsReserved = false);
  }

  /// PDF 読み込み完了後に AI パネルを自動オープンする予約フラグ。
  /// ★ フリーズ対策 (= ユーザー報告): PDF(SfPdfViewer) と AI(WebView) を同時に
  ///   生成すると固まりやすいので、 AI は onDocumentLoaded 後に遅延して開く。
  bool _pendingAiAutoOpen = false;

  /// 開いている AI の URL (= ChatGPT 等)。
  String _aiPanelUrl = '';

  /// ★ フリーズ対策の WebView キャッシュ (Windows) ★
  /// (= ユーザー報告: AI 欄を開いた状態で PDF をスクロールするとアプリが
  ///  完全に固まる) への対応。 PDF を続けてスクロールすると onPageChanged の
  ///  setState がページごとに走り、 ビューア本体 (この State) が再構築される。
  ///  その時 AI 欄の webview_windows (ネイティブ View) ウィジェットまで毎回
  ///  作り直されると、 Windows でネイティブ View の再生成が競合してハングする。
  ///  一度生成した AI 欄 WebView ウィジェットの「実体」 を保持し、 同一
  ///  インスタンスを返すことで Flutter にこのサブツリーの更新を完全にスキップ
  ///  させる。 AI 欄を閉じる (_aiPanelOpen=false) ときに null へ戻して破棄する。
  Widget? _aiWebViewCache;

  /// AI チャット欄の幅 (ドラッグで可変)。
  double _aiPanelWidth = 380.0;

  /// メモ欄の幅 (ドラッグで可変)。
  double _memoPanelWidth = 320.0;

  /// メモ欄と AI 欄の左右位置を入れ替えているか。
  /// 既定 (false) = メモ左 / AI 右。true で左右逆。
  bool _panelsSwapped = false;

  /// Windows 用 AI WebView コントローラ。
  wv_win.WebviewController? _aiWinController;

  /// モバイル AI チャット欄の InAppWebView コントローラ参照 (= JS 注入用)。
  iaw.InAppWebViewController? _aiIawController;

  /// AI 欄に入力された質問を自動で Q&A 履歴へ保存するためのポーリング Timer。
  /// AI サイトは外部 Web ページのため、 送信された質問は WebView 内の JS で
  /// `window.__mmLastQ` / `window.__mmQSeq` に控えておき、 ここから定期的に
  /// 読み取って新規分を履歴へ記録する (= ユーザー要望: 質問の自動保存)。
  Timer? _aiQCaptureTimer;

  /// 既に履歴へ記録済みの質問シーケンス番号。
  int _lastAiQSeq = 0;

  /// 生成 AI チャット欄を開く / 切り替える (5 種類から選択)。
  /// URL はカスタムボタン (openChatGPT 等) と同一。
  /// 選んだ AI は既定として永続化し、別の回で開いても同じ AI が出る。
  void _openAiPanel(String aiId) {
    const urls = <String, String>{
      'chatgpt': 'https://chatgpt.com/',
      'gemini': 'https://gemini.google.com/app',
      'claude': 'https://claude.ai/',
      'deepseek': 'https://chat.deepseek.com/',
      'grok': 'https://grok.com/',
    };
    final url = urls[aiId];
    if (url == null) return;
    // パネル出現で PDF が再レイアウトしてページが飛ぶのを防ぐ
    _suppressPdfPageChangeBriefly();
    setState(() {
      _aiPanelUrl = url;
      _aiPanelOpen = true;
    });
    // 選択した AI を既定として永続化 (= ユーザー要望「別の回でも同じ AI」)。
    try {
      context.read<MindMapProvider>().setPdfAiPanelDefault(aiId);
    } catch (_) {}
    if (Platform.isWindows) {
      try {
        _aiWinController?.loadUrl(url);
      } catch (_) {}
    }
    // 選択キャプチャ JS を (ページ描画後に) 注入する。
    for (final ms in const [800, 1800, 3500]) {
      Future.delayed(Duration(milliseconds: ms), _injectAiSelectionCapture);
    }
    // 入力された質問を自動で履歴に保存するためのキャプチャを開始 (= ユーザー要望)。
    _startAiQuestionCapture();
  }

  /// AI 画面でのテキスト選択を `window.__mmLastSel` に常時記録する JS を注入。
  /// (= ユーザー要望: 「回答を選択 → 保存ボタン」 で選択が消えて保存されない
  ///  問題の対策。 選択した時点で変数に控えておき、 保存時にそれを読む)。
  void _injectAiSelectionCapture() {
    if (!mounted) return;
    const js = '''
(function(){
  if (window.__mmSelCapInit) return;
  window.__mmSelCapInit = true;
  function cap(){ try { var s = (window.getSelection()||'').toString(); if (s && s.trim()) window.__mmLastSel = s; } catch(e){} }
  document.addEventListener('mouseup', cap, true);
  document.addEventListener('keyup', cap, true);
  document.addEventListener('selectionchange', cap, true);
})();
''';
    try {
      if (Platform.isWindows) {
        _aiWinController?.executeScript(js);
      } else {
        _aiIawController?.evaluateJavascript(source: js);
      }
    } catch (_) {}
  }

  /// AI 欄に送信された質問を `window.__mmLastQ` / `window.__mmQSeq` に
  /// 控える JS を注入する。 Enter 送信 (Shift+Enter は改行扱い) と、
  /// サイトの送信ボタンクリックの両方を捕捉する。 `__mmQCapInit` で
  /// 二重注入を防ぐ。
  void _injectAiQuestionCapture() {
    if (!mounted) return;
    const js = '''
(function(){
  if (window.__mmQCapInit) return;
  window.__mmQCapInit = true;
  if (typeof window.__mmQSeq !== 'number') window.__mmQSeq = 0;
  if (typeof window.__mmLastQ !== 'string') window.__mmLastQ = '';
  function txt(el){ try{
    if(!el) return '';
    var t=(el.tagName||'').toLowerCase();
    if(t==='textarea'||t==='input') return (el.value||'');
    return (el.innerText||el.textContent||'');
  }catch(e){return '';} }
  function editable(el){
    if(!el) return false;
    var t=(el.tagName||'').toLowerCase();
    if(t==='textarea') return true;
    if(t==='input'){ var ty=(el.type||'text').toLowerCase(); return ty==='text'||ty==='search'||ty===''; }
    return !!el.isContentEditable;
  }
  function record(el){
    var s=txt(el).trim();
    if(s && s!==window.__mmLastQ){ window.__mmLastQ=s; window.__mmQSeq=(window.__mmQSeq||0)+1; }
  }
  document.addEventListener('keydown', function(e){ try{
    if(e.key!=='Enter'||e.shiftKey||e.altKey||e.isComposing) return;
    var el=e.target; if(!editable(el)) return; record(el);
  }catch(_){} }, true);
  document.addEventListener('click', function(e){ try{
    var el=e.target;
    var btn=(el&&el.closest)?el.closest('button,[role=button],[type=submit]'):null;
    if(!btn) return;
    var ae=document.activeElement;
    if(editable(ae)) record(ae);
    else { var ta=document.querySelector('textarea'); if(ta) record(ta); }
  }catch(_){} }, true);
})();
''';
    try {
      if (Platform.isWindows) {
        _aiWinController?.executeScript(js);
      } else {
        _aiIawController?.evaluateJavascript(source: js);
      }
    } catch (_) {}
  }

  /// 質問キャプチャのポーリングを開始する (AI 欄を開いた時)。
  void _startAiQuestionCapture() {
    _aiQCaptureTimer?.cancel();
    _lastAiQSeq = 0;
    _aiQCaptureTimer = Timer.periodic(
        const Duration(milliseconds: 1200), (_) => _pollAiQuestionCapture());
  }

  /// 質問キャプチャのポーリングを停止する。
  void _stopAiQuestionCapture() {
    _aiQCaptureTimer?.cancel();
    _aiQCaptureTimer = null;
  }

  /// WebView 内の `window.__mmLastQ` を読み、 未記録の新しい質問があれば
  /// Q&A 履歴へ保存する。 AI 欄が閉じたら自動的にポーリングを止める。
  Future<void> _pollAiQuestionCapture() async {
    if (!mounted || !_aiPanelOpen) {
      _stopAiQuestionCapture();
      return;
    }
    // ページ遷移後も効くよう、 毎回 (冪等に) キャプチャ JS を注入する。
    _injectAiQuestionCapture();
    const readJs =
        "(function(){try{return JSON.stringify({s:window.__mmQSeq||0,q:window.__mmLastQ||''});}catch(e){return '';}})()";
    String raw = '';
    try {
      if (Platform.isWindows) {
        final r = await _aiWinController?.executeScript(readJs);
        raw = (r ?? '').toString();
      } else {
        final r = await _aiIawController?.evaluateJavascript(source: readJs);
        raw = (r ?? '').toString();
      }
    } catch (_) {
      return;
    }
    if (raw.isEmpty) return;
    // executeScript / evaluateJavascript の戻り値は二重 JSON エンコードに
    //   なる場合があるので、 Map になるまで最大 2 回 decode する。
    dynamic decoded;
    try {
      decoded = jsonDecode(raw);
      if (decoded is String) decoded = jsonDecode(decoded);
    } catch (_) {
      return;
    }
    if (decoded is! Map) return;
    final seq = (decoded['s'] as num?)?.toInt() ?? 0;
    final q = (decoded['q'] ?? '').toString();
    if (seq < _lastAiQSeq) _lastAiQSeq = 0; // ページ再読込でリセットされた
    if (seq > _lastAiQSeq) {
      _lastAiQSeq = seq;
      _recordAiQuestionToHistory(q);
    }
  }

  /// DeepL を AI 側パネルに開く (= ユーザー要望: PDF ビューアにも DeepL を搭載)。
  /// 翻訳用途なので AI の既定 (pdfAiPanelDefault) は変更しない。
  void _openDeepLPanel() {
    const url = 'https://www.deepl.com/translator';
    _suppressPdfPageChangeBriefly();
    // 翻訳パネルでは質問キャプチャを動かさない (= 翻訳入力を質問として
    // 誤記録しないため)。 直前に AI 欄を開いていた場合に備えて停止する。
    _stopAiQuestionCapture();
    setState(() {
      _aiPanelUrl = url;
      _aiPanelOpen = true;
    });
    if (Platform.isWindows) {
      try {
        _aiWinController?.loadUrl(url);
      } catch (_) {}
    }
  }

  /// 選んだ AI を既定にして開く (_openAiPanel が永続化する)。
  Future<void> _showAiPickerMenu(Offset globalPos) async {
    final overlay =
        Overlay.of(context).context.findRenderObject() as RenderBox?;
    if (overlay == null) return;
    final sel = await showMenu<String>(
      context: context,
      color: const Color(0xFF1E1E32),
      position: RelativeRect.fromRect(
        Rect.fromPoints(globalPos, globalPos),
        Offset.zero & overlay.size,
      ),
      items: _aiMenuItems(),
    );
    if (sel == null) return;
    if (sel == '__prefix__') {
      await _showAiPrefixDialog();
      return;
    }
    _openAiPanel(sel);
  }

