  Widget _buildMemoPanelInner(MindMapProvider provider) {
    return _PdfMemoPanel(
      nodeId: _nodeId!,
      isPdf: widget.isPdf,
      currentPage: _currentPage,
      currentUrl: _currentUrl,
      highlightMemoId: _highlightMemoId,
      onJumpToMemo: _jumpToMemo,
      onAddHere: () => setState(() => _placingMemo = true),
      onClosePanel: () {
        _suppressPdfPageChangeBriefly();
        setState(() => _memoPanelOpen = false);
      },
      // メモ欄ヘッダーからも左右入れ替え (= ユーザー要望)。
      onSwapSides: () {
        _suppressPdfPageChangeBriefly();
        setState(() => _panelsSwapped = !_panelsSwapped);
      },
      // ── メモ内容を AI チャット欄に送る (= ユーザー要望) ──
      // AI 欄が閉じていれば自動で開き、 メモ本文をクリップボードへコピー
      //   して案内 SnackBar を出す。 AI サイトの DOM 差異が大きいため、
      //   入力欄に自動挿入はせず、 ユーザー操作 (Ctrl+V → 送信) に委ねる。
      onSendMemoToAi: (memo) => _sendMemoToAiPanel(memo),
      // ── メモの本文で YouTube 検索を開く (= ユーザー要望) ──
      onSearchYoutube: _openMemoYoutubeSearch,
      // ── メモをまとめて AI に送る (= ユーザー要望) ──
      onSendAllToAi: _sendCombinedTextToAiPanel,
    );
  }

  /// まとめたメモ本文 (メモ毎に改行済み) をブラウザ AI へ渡す
  /// (= ユーザー要望)。 単発の _sendMemoToAiPanel と同じ挿入経路。
  void _sendCombinedTextToAiPanel(String text) {
    final t = text.trim();
    if (t.isEmpty) return;
    _recordAiQuestionToHistory(t);
    Clipboard.setData(ClipboardData(text: t));
    final provider = context.read<MindMapProvider>();
    final wasOpen = _aiPanelOpen;
    if (!wasOpen) {
      _openAiPanel(provider.pdfAiPanelDefault);
    }
    final initialDelay = wasOpen
        ? const Duration(milliseconds: 300)
        : const Duration(milliseconds: 1500);
    final sendText = provider.browserAiApplyPrefix(t);
    final token = ++_pdfAiInjectSeq;
    Future.delayed(initialDelay, () => _injectTextToAi(sendText, token));
    Future.delayed(initialDelay + const Duration(milliseconds: 1200),
        () => _injectTextToAi(sendText, token));
    Future.delayed(initialDelay + const Duration(milliseconds: 2800),
        () => _injectTextToAi(sendText, token));
  }

  /// メモの本文で YouTube 検索を開く (= ユーザー要望: メモから YouTube
  /// 検索を開くボタン)。 ブラウズ用の YouTube シートをダイアログで重ねる。
  void _openMemoYoutubeSearch(PdfMemo memo) {
    if (!Platform.isWindows) return;
    final (_, body) = _parseMemoImage(memo.text);
    final text = body.trim();
    if (text.isEmpty) return;
    final url = 'https://www.youtube.com/results?search_query='
        '${Uri.encodeQueryComponent(text)}';
    showDialog<void>(
      context: context,
      barrierColor: Colors.black.withValues(alpha: 0.75),
      builder: (_) => Dialog(
        backgroundColor: Colors.transparent,
        // ほぼ全画面で開く (= ユーザー要望: もう少し大きく)。
        insetPadding: const EdgeInsets.symmetric(horizontal: 20, vertical: 14),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(16),
          child: _WindowsWebViewSheet(
            url: url,
            // 履歴を復元せず、 必ずこの検索結果から開始する。
            forceHome: true,
            // ブラウズ用途なのでフォーカス CSS は入れない。
            focusMode: false,
          ),
        ),
      ),
    );
  }

  /// メモ内容を AI チャット欄に送る (= ユーザー要望)。
  /// 1. AI 欄が閉じていれば既定 AI で自動で開く
  /// 2. メモ本文 (= 画像マーカーを除いたテキスト) をクリップボードへコピー
  /// 3. JavaScript で AI 入力欄に「**改行付きで追加**」 (= ユーザー要望:
  ///    値が更新されるのではなく、 改行入れて追加されるように)。 既に
  ///    入力欄に内容があれば末尾に `\n` を挟んで連結する。
  /// 4. メモに画像があれば、 base64 で読み込んで JS の paste イベントを
  ///    合成し、 AI 入力欄に画像も貼り付ける (= ユーザー要望)。
  void _sendMemoToAiPanel(PdfMemo memo) async {
    // ── 確認を出さず、 そのままブラウザ版 AI に渡す (= ユーザー要望) ──
    final (imgPath, body) = _parseMemoImage(memo.text);
    final text = body.trim();
    // 送った質問を Q&A 履歴に記録 (= ユーザー要望: 回答を履歴で保存できるように)。
    if (text.isNotEmpty) _recordAiQuestionToHistory(text);
    final hasImg = imgPath != null && imgPath.isNotEmpty;
    if (text.isEmpty && !hasImg) {
      if (mounted) {
        _appSnack(
            context,
            SnackBar(
              content: Text(context.read<MindMapProvider>().t('ai.memoEmpty')),
              duration: const Duration(seconds: 2),
              backgroundColor: const Color(0xFF2A2A3E),
            ));
      }
      return;
    }
    // クリップボードへコピー (フォールバック手段として常に実行)
    if (text.isNotEmpty) {
      Clipboard.setData(ClipboardData(text: text));
    }
    final provider = context.read<MindMapProvider>();
    final wasOpen = _aiPanelOpen;
    if (!wasOpen) {
      _openAiPanel(provider.pdfAiPanelDefault);
    }
    final initialDelay = wasOpen
        ? const Duration(milliseconds: 300)
        : const Duration(milliseconds: 1500);
    // ── テキスト挿入 (1 回だけ確実に) ──
    // ページ (SPA) の描画タイミングに合わせて数回試すが、 token で
    //   「最初に成功した 1 回だけ挿入」 する (= ユーザー要望: 同じ文章が
    //   3 連続で送られてしまうのを修正)。
    if (text.isNotEmpty) {
      // ── 前提条件 (「日本語で答えて」 等) を先頭に付けて渡す (= ユーザー要望) ──
      //   履歴記録・クリップボードは元の本文のまま、 AI へ流す文章にだけ付与。
      final sendText = provider.browserAiApplyPrefix(text);
      final token = ++_pdfAiInjectSeq;
      Future.delayed(initialDelay, () => _injectTextToAi(sendText, token));
      Future.delayed(initialDelay + const Duration(milliseconds: 1200),
          () => _injectTextToAi(sendText, token));
      Future.delayed(initialDelay + const Duration(milliseconds: 2800),
          () => _injectTextToAi(sendText, token));
    }
    // ── 画像挿入 ──
    if (hasImg) {
      try {
        final f = File(imgPath);
        if (await f.exists()) {
          final bytes = await f.readAsBytes();
          final b64 = base64Encode(bytes);
          // MIME を拡張子から推定
          final lower = imgPath.toLowerCase();
          final mime = lower.endsWith('.png')
              ? 'image/png'
              : lower.endsWith('.jpg') || lower.endsWith('.jpeg')
                  ? 'image/jpeg'
                  : lower.endsWith('.gif')
                      ? 'image/gif'
                      : lower.endsWith('.webp')
                          ? 'image/webp'
                          : 'image/png';
          // テキストより遅らせて挿入 (テキストにフォーカスを取られた直後)。
          Future.delayed(initialDelay + const Duration(milliseconds: 600),
              () => _injectImageToAi(b64, mime));
          Future.delayed(initialDelay + const Duration(milliseconds: 2000),
              () => _injectImageToAi(b64, mime));
        }
      } catch (_) {}
    }
    // 「AI 入力欄に追加しました」 の通知は出さない (= ユーザー要望: 鬱陶しい)。
  }

  /// PDF 本文を抽出して AI チャット入力欄に直接挿入する (= ユーザー報告:
  /// 「AI に PDF の内容が与えられていない」)。 旧実装はクリップボードへコピー
  /// して手動 Ctrl+V を促すだけだったので、 メモ→AI と同じ _injectTextToAi 経路
  /// で入力欄へ自動投入する。 長すぎる PDF は AI の入力欄/コンテキストに収まら
  /// ないため上限でカットする。 デスクトップ (Windows) の AI 欄が対象。
  Future<void> _sendPdfContentToAi() async {
    final path = _pdfFilePath;
    final provider = context.read<MindMapProvider>();
    if (path == null || !File(path).existsSync()) {
      _appSnack(
          context,
          SnackBar(
              content: Text(provider.t('pdf.noPdf')),
              duration: const Duration(seconds: 2)));
      return;
    }
    _appSnack(
        context,
        SnackBar(
            content: Text(provider.t('pdf.reading')),
            duration: const Duration(seconds: 1)));
    var text = await _extractPdfTextForAi(path);
    if (!mounted) return;
    if (text == null || text.trim().isEmpty) {
      _appSnack(
          context,
          SnackBar(
              content: Text(provider.t('pdf.noTextExtract')),
              duration: const Duration(seconds: 3)));
      return;
    }
    // 長文対策: AI の入力欄/コンテキストに収まる上限でカットする。
    const int kMaxAiChars = 30000;
    bool truncated = false;
    if (text.length > kMaxAiChars) {
      text = text.substring(0, kMaxAiChars);
      truncated = true;
    }
    // フォールバックとしてクリップボードにもコピーしておく。
    await Clipboard.setData(ClipboardData(text: text));
    final wasOpen = _aiPanelOpen;
    if (!wasOpen) _openAiPanel(provider.pdfAiPanelDefault);
    final header = truncated
        ? '次のPDF本文（長いため冒頭のみ）の内容について答えてください:\n\n'
        : '次のPDF本文の内容について答えてください:\n\n';
    final sendText = provider.browserAiApplyPrefix(header + text);
    _recordAiQuestionToHistory('（PDF本文をAIに送信）');
    // メモ→AI と同様に、 SPA の描画タイミングに合わせて数回試し、 token で
    //   「最初に成功した 1 回だけ」 挿入する。
    final token = ++_pdfAiInjectSeq;
    final initialDelay = wasOpen
        ? const Duration(milliseconds: 300)
        : const Duration(milliseconds: 1500);
    Future.delayed(initialDelay, () => _injectTextToAi(sendText, token));
    Future.delayed(initialDelay + const Duration(milliseconds: 1200),
        () => _injectTextToAi(sendText, token));
    Future.delayed(initialDelay + const Duration(milliseconds: 2800),
        () => _injectTextToAi(sendText, token));
    if (!mounted) return;
    _appSnack(
        context,
        SnackBar(
            content:
                Text(truncated ? 'PDFの内容（冒頭のみ）をAIに送信しました' : 'PDFの内容をAIに送信しました'),
            backgroundColor: const Color(0xFF43B97F),
            duration: const Duration(seconds: 3)));
  }

  /// AI サイトの入力欄に [text] を**追加**挿入 (= 既存テキストの末尾に改行で
  /// 連結)。 contenteditable と textarea を総当たりで探し、 一番大きい画面内
  /// 要素にフォーカス + カーソルを末尾へ移動 + insertText。
  /// 同一送信内の二重挿入を防ぐトークン (= ユーザー要望: AI に同じ文章が
  /// 3 連続で送られる不具合の修正)。 _sendMemoToAiPanel で 1 送信ごとに ++。
  int _pdfAiInjectSeq = 0;
  void _injectTextToAi(String text, int token) {
    if (!mounted) return;
    final escaped = jsonEncode(text);
    final js = '''
(function() {
  try {
    // 既にこの送信トークンで挿入済みなら何もしない (= リトライの重複防止)。
    if (window.__mmPdfAiToken === $token) return 'dup';
    var text = $escaped;
    var ceSelectors = [
      'div.ProseMirror[contenteditable="true"]',
      '#prompt-textarea',
      'div[contenteditable="true"].ql-editor',
      'div[contenteditable="true"]',
    ];
    function visibleArea(el) {
      var r = el.getBoundingClientRect();
      if (r.width < 80 || r.height < 16) return 0;
      if (r.bottom < 0 || r.top > window.innerHeight) return 0;
      return r.width * r.height;
    }
    function moveCursorToEnd(el) {
      el.focus();
      try {
        var range = document.createRange();
        range.selectNodeContents(el);
        range.collapse(false);
        var sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
      } catch (e) {}
    }
    var best = null;
    var bestArea = 0;
    for (var i = 0; i < ceSelectors.length; i++) {
      var nodes = document.querySelectorAll(ceSelectors[i]);
      for (var j = 0; j < nodes.length; j++) {
        var n = nodes[j];
        var a = visibleArea(n);
        if (a > bestArea) { bestArea = a; best = n; }
      }
      if (best) break;
    }
    if (best) {
      var existing = (best.innerText || best.textContent || '').trim();
      moveCursorToEnd(best);
      var prefix = existing.length > 0 ? '\\n' : '';
      try {
        document.execCommand('insertText', false, prefix + text);
      } catch (e) {
        best.innerText = (existing + prefix + text);
        best.dispatchEvent(new InputEvent('input', { bubbles: true, data: text }));
      }
      window.__mmPdfAiToken = $token;
      return 'ok-ce';
    }
    // textarea / input fallback
    var taList = document.querySelectorAll('textarea, input[type="text"]');
    var bestTa = null;
    var bestTaArea = 0;
    for (var k = 0; k < taList.length; k++) {
      var t = taList[k];
      var ta = visibleArea(t);
      if (ta > bestTaArea) { bestTaArea = ta; bestTa = t; }
    }
    if (bestTa) {
      bestTa.focus();
      var existing = bestTa.value || '';
      var prefix = existing.length > 0 ? '\\n' : '';
      var newVal = existing + prefix + text;
      var proto = bestTa.tagName === 'TEXTAREA'
        ? window.HTMLTextAreaElement.prototype
        : window.HTMLInputElement.prototype;
      var setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
      setter.call(bestTa, newVal);
      bestTa.dispatchEvent(new Event('input', { bubbles: true }));
      // カーソルを末尾へ
      try {
        bestTa.selectionStart = bestTa.selectionEnd = newVal.length;
      } catch (e) {}
      window.__mmPdfAiToken = $token;
      return 'ok-ta';
    }
    return 'not-found';
  } catch (e) {
    return 'error: ' + e;
  }
})();
''';
    try {
      if (Platform.isWindows) {
        _aiWinController?.executeScript(js);
      } else {
        _aiIawController?.evaluateJavascript(source: js);
      }
    } catch (_) {}
  }

  /// AI サイトの入力欄に画像を貼り付け (= ユーザー要望: メモに入っている
  /// 画像も AI に渡すように)。 base64 から Blob を生成し、 DataTransfer に
  /// 載せて paste イベントを合成する。 ChatGPT/Claude/Gemini など多くの AI
  /// サイトは paste イベントを listen して画像添付を受け付ける。
  void _injectImageToAi(String base64Img, String mime) {
    if (!mounted) return;
    final escB64 = jsonEncode(base64Img);
    final escMime = jsonEncode(mime);
    final js = '''
(function() {
  try {
    var b64 = $escB64;
    var mime = $escMime;
    // base64 → Uint8Array
    var bin = atob(b64);
    var arr = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    var blob = new Blob([arr], { type: mime });
    var ext = mime.split('/')[1] || 'png';
    var file = new File([blob], 'memo.' + ext, { type: mime, lastModified: Date.now() });
    // 入力対象を探す
    function visibleArea(el) {
      var r = el.getBoundingClientRect();
      if (r.width < 80 || r.height < 16) return 0;
      if (r.bottom < 0 || r.top > window.innerHeight) return 0;
      return r.width * r.height;
    }
    var ceSelectors = [
      'div.ProseMirror[contenteditable="true"]',
      '#prompt-textarea',
      'div[contenteditable="true"].ql-editor',
      'div[contenteditable="true"]',
      'textarea',
    ];
    var target = null;
    var targetArea = 0;
    for (var s = 0; s < ceSelectors.length; s++) {
      var nodes = document.querySelectorAll(ceSelectors[s]);
      for (var j = 0; j < nodes.length; j++) {
        var n = nodes[j];
        var a = visibleArea(n);
        if (a > targetArea) { targetArea = a; target = n; }
      }
      if (target) break;
    }
    if (!target) return 'no-target';
    target.focus();
    // paste イベントを合成
    var dt = new DataTransfer();
    dt.items.add(file);
    var pasteEvt = new ClipboardEvent('paste', {
      clipboardData: dt,
      bubbles: true,
      cancelable: true,
    });
    target.dispatchEvent(pasteEvt);
    // フォールバック: drop イベントも試す
    var dropEvt = new DragEvent('drop', {
      dataTransfer: dt,
      bubbles: true,
      cancelable: true,
    });
    target.dispatchEvent(dropEvt);
    return 'ok';
  } catch (e) {
    return 'error: ' + e;
  }
})();
''';
    try {
      if (Platform.isWindows) {
        _aiWinController?.executeScript(js);
      } else {
        _aiIawController?.evaluateJavascript(source: js);
      }
    } catch (_) {}
  }

  /// 境界ドラッグでパネル幅を可変にするラッパー。
  /// [handleOnLeft] = true でハンドルを左端に出す (= パネルが右側にある場合)。
  /// [onResizeDelta] には生のドラッグ量 dx を渡し、呼び出し側で符号と
  /// clamp を解決する。
  Widget _buildResizableDock({
    required Widget panel,
    required double width,
    required bool handleOnLeft,
    required ValueChanged<double> onResizeDelta,
  }) {
    final handle = MouseRegion(
      cursor: SystemMouseCursors.resizeLeftRight,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onHorizontalDragUpdate: (d) => onResizeDelta(d.delta.dx),
        child: Container(
          width: 6,
          color: Colors.white.withValues(alpha: 0.04),
          child: Center(
            child: Container(
              width: 2,
              height: 32,
              decoration: BoxDecoration(
                color: Colors.white.withValues(alpha: 0.35),
                borderRadius: BorderRadius.circular(1),
              ),
            ),
          ),
        ),
      ),
    );
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        if (handleOnLeft) handle,
        SizedBox(width: width, child: panel),
        if (!handleOnLeft) handle,
      ],
    );
  }

  /// 現在パネルに開いているサービスが DeepL か (= 翻訳)。
  bool get _aiPanelIsDeepL => _aiPanelUrl.toLowerCase().contains('deepl');

  /// パネルヘッダーに出す名前 (= ユーザー要望: DeepL を開いたら「AI」 ではなく
  /// ちゃんと「DeepL」 と表示する)。
  String get _aiPanelLabel {
    final u = _aiPanelUrl.toLowerCase();
    if (u.contains('deepl')) return 'DeepL';
    if (u.contains('chatgpt') || u.contains('openai')) return 'ChatGPT';
    if (u.contains('gemini')) return 'Gemini';
    if (u.contains('claude')) return 'Claude';
    if (u.contains('deepseek')) return 'DeepSeek';
    if (u.contains('grok') || u.contains('x.ai')) return 'Grok';
    return 'AI';
  }

  /// AI パネルのホイールスクロール。 webview_windows はホイールを内部スクロール
  /// に転送しないことがあるため、 分割ビューと同じく JS で直接動かす。
  /// ChatGPT 等は本文を内側の overflow コンテナでスクロールするので、
  /// document ではなく最適なスクロール要素を探す [_webWheelScrollJs] を使う
  /// (= ユーザー要望: AI チャット欄をマウスホイールで上下に動かせるように)。
  void _scrollAiPanelByWheel(PointerSignalEvent event) {
    if (event is! PointerScrollEvent) return;
    if (!Platform.isWindows) return; // モバイル (iaw) はネイティブスクロール
    final dx = event.scrollDelta.dx.round();
    final dy = event.scrollDelta.dy.round();
    if (dx == 0 && dy == 0) return;
    try {
      _aiWinController?.executeScript(_webWheelScrollJs(dx, dy));
    } catch (_) {}
  }

  /// PDF ビューア横の生成 AI チャット欄の中身 (幅は _buildResizableDock 側)。
  Widget _buildAiPanelInner(MindMapProvider provider) {
    Widget webView;
    if (_aiPanelUrl.isEmpty) {
      webView = Center(
        child: Text(context.read<MindMapProvider>().t('pdf.aiSelect'),
            style: TextStyle(color: Colors.white38, fontSize: 12)),
      );
    } else if (Platform.isWindows) {
      // ★ フリーズ対策 ★ — 一度生成した WebView ウィジェットの実体を保持し、
      //   同一インスタンスを返す。 PDF スクロール中の setState では
      //   identical(child.widget, newWidget) によりこのサブツリーの更新が
      //   スキップされ、 webview_windows (ネイティブ View) が作り直されない。
      //   AI の切替は既存コントローラの loadUrl で行うので作り直し不要。
      webView = _aiWebViewCache ??= _SplitWindowsWebView(
        url: _aiPanelUrl,
        onControllerReady: (c) => _aiWinController = c,
        onInitialized: () {},
        onUrlChanged: (u) {
          if (mounted && u != _aiPanelUrl) _aiPanelUrl = u;
        },
      );
    } else {
      webView = iaw.InAppWebView(
        initialUrlRequest: iaw.URLRequest(url: iaw.WebUri(_aiPanelUrl)),
        initialSettings: iaw.InAppWebViewSettings(
          javaScriptEnabled: true,
          domStorageEnabled: true,
          useHybridComposition: true,
          transparentBackground: false,
        ),
        // メモを AI 欄に注入するため、 コントローラを保持 (= ユーザー要望)。
        onWebViewCreated: (c) => _aiIawController = c,
      );
    }
    return Container(
      decoration: const BoxDecoration(
        color: Color(0xFF1E1E32),
        border: Border(
          left: BorderSide(color: Colors.white24),
          right: BorderSide(color: Colors.white24),
        ),
      ),
      // ── AI パネルのホイールスクロール (= ユーザー要望) ──
      // 以前は MouseRegion(opaque)+Listener(opaque) で包んでいたが、 それが
      // webview_windows へのネイティブホイール転送を阻んでスクロール不能に
      // していた。 Google 検索 (= 素の Webview) は包まず普通にスクロールできて
      // いるので、 ここも包まず素の WebView に直接ホイールを届ける。
      child: Column(
        children: [
          // ── ヘッダー: AI 選択 (5 種類) + 左右入れ替え + 閉じる ──
          Container(
            padding: const EdgeInsets.fromLTRB(10, 4, 2, 4),
            color: const Color(0xFF12121C),
            child: Row(children: [
              Icon(
                  _aiPanelIsDeepL
                      ? Icons.translate_rounded
                      : Icons.smart_toy_rounded,
                  color: const Color(0xFF4FC3F7),
                  size: 18),
              const SizedBox(width: 6),
              Flexible(
                child: Text(_aiPanelLabel,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 13,
                        fontWeight: FontWeight.w700)),
              ),
              // ── モデル (AI) 切替は名前のすぐ右に置く (= ユーザー要望:
              //    右端まで離れていると切替ボタンだと分からない)。 ──
              PopupMenuButton<String>(
                tooltip: context.read<MindMapProvider>().t('pdf.aiSelectTip'),
                icon: const Icon(Icons.expand_more_rounded,
                    color: Colors.white70, size: 18),
                color: const Color(0xFF1E1E32),
                onSelected: _openAiPanel,
                itemBuilder: (_) => _aiMenuItems(),
              ),
              const Spacer(),
              // ── 戻る (= ユーザー要望: リンクを踏んだ時に戻れるように) ──
              IconButton(
                tooltip: context.read<MindMapProvider>().t('btn.back'),
                icon: const Icon(Icons.arrow_back_rounded,
                    color: Colors.white70, size: 18),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
                onPressed: _aiPanelGoBack,
              ),
              // ── AI チャット画面の再読み込み (= ユーザー要望) ──
              IconButton(
                tooltip: context.read<MindMapProvider>().t('pdf.aiReload'),
                icon: const Icon(Icons.refresh_rounded,
                    color: Colors.white70, size: 18),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
                onPressed: _reloadAiPanel,
              ),
              // ── 質問履歴を開く (質問は自動保存。 回答の手動保存も
              //    履歴ダイアログ内に統合した = ユーザー要望: 2 ボタンを 1 つに) ──
              IconButton(
                tooltip: context.read<MindMapProvider>().t('pdf.aiHistory'),
                icon: const Icon(Icons.history_rounded,
                    color: Colors.white70, size: 18),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
                onPressed: _showAiQaHistoryDialog,
              ),
              IconButton(
                tooltip: context.read<MindMapProvider>().t('pdf.aiSwap'),
                icon: const Icon(Icons.swap_horiz_rounded,
                    color: Colors.white70, size: 18),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
                onPressed: () {
                  _suppressPdfPageChangeBriefly();
                  setState(() => _panelsSwapped = !_panelsSwapped);
                },
              ),
              IconButton(
                tooltip: context.read<MindMapProvider>().t('pdf.aiClose'),
                icon: const Icon(Icons.close_rounded,
                    color: Colors.white60, size: 18),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
                onPressed: () {
                  _suppressPdfPageChangeBriefly();
                  setState(() {
                    _aiPanelOpen = false;
                    _aiWebViewCache = null; // ★ フリーズ対策: 閉じたら WebView キャッシュを破棄
                  });
                },
              ),
            ]),
          ),
          Expanded(
            child: Listener(
              onPointerSignal: _scrollAiPanelByWheel,
              child: webView,
            ),
          ),
        ],
      ),
    );
  }

  /// メモから AI に投げた質問を Q&A 履歴に記録する (= ユーザー要望)。
  void _recordAiQuestionToHistory(String question) {
    final q = question.trim();
    if (q.isEmpty) return;
    _AiQaHistoryStore.addQuestion(q, DateTime.now().millisecondsSinceEpoch);
  }

  /// AI チャット画面を再読み込みする (= ユーザー要望: 画面更新ボタン)。
  void _reloadAiPanel() {
    try {
      if (Platform.isWindows) {
        _aiWinController?.reload();
      } else {
        _aiIawController?.reload();
      }
    } catch (_) {}
  }

  /// AI チャット画面でリンクを踏んだ時に 1 つ前へ戻る (= ユーザー要望)。
  void _aiPanelGoBack() {
    try {
      if (Platform.isWindows) {
        _aiWinController?.executeScript('window.history.back();');
      } else {
        _aiIawController?.goBack();
      }
    } catch (_) {}
  }

  /// AI 画面で選択中のテキストを「最新の質問の回答」 として履歴に保存する。
  /// 保存できたら true、 選択が無く保存しなかった場合は false を返す。
  Future<bool> _saveAiAnswerFromSelection() async {
    // 選択時に控えておいた __mmLastSel を優先して読む (= ボタン押下で選択が
    //   消えても保存できるように)。 無ければライブの選択にフォールバック。
    const readJs =
        "(window.__mmLastSel || (window.getSelection?window.getSelection().toString():'') || '')";
    String sel = '';
    try {
      if (Platform.isWindows) {
        final r = await _aiWinController?.executeScript(readJs);
        sel = (r ?? '').toString();
      } else {
        final r = await _aiIawController?.evaluateJavascript(source: readJs);
        sel = (r ?? '').toString();
      }
    } catch (_) {}
    sel = sel.trim();
    if (!mounted) return false;
    if (sel.isEmpty) {
      _appSnack(
        context,
        SnackBar(
          content:
              Text(context.read<MindMapProvider>().t('pdf.aiSelectAnswer')),
          backgroundColor: Color(0xFF2A2A3E),
          duration: Duration(seconds: 3),
        ),
      );
      return false;
    }
    // 履歴に保存 (最新の未回答質問に紐づけ、 無ければ新規エントリを作る)。
    await _AiQaHistoryStore.saveAnswer(
        sel, DateTime.now().millisecondsSinceEpoch);
    // 次の保存で同じテキストを拾わないようクリア。
    try {
      const clearJs = 'window.__mmLastSel = "";';
      if (Platform.isWindows) {
        _aiWinController?.executeScript(clearJs);
      } else {
        _aiIawController?.evaluateJavascript(source: clearJs);
      }
    } catch (_) {}
    if (!mounted) return true;
    _appSnack(
      context,
      SnackBar(
        content: Text(context.read<MindMapProvider>().t('pdf.answerSaved')),
        backgroundColor: Color(0xFF43B97F),
        duration: Duration(seconds: 2),
      ),
    );
    return true;
  }

  /// AI Q&A 履歴を一覧表示するダイアログ。
  Future<void> _showAiQaHistoryDialog() async {
    var list = await _AiQaHistoryStore.load();
    if (!mounted) return;
    await showDialog<void>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            const Icon(Icons.history_rounded,
                color: Color(0xFF4FC3F7), size: 20),
            const SizedBox(width: 8),
            Text(context.read<MindMapProvider>().t('pdf.aiHistoryTitle'),
                style: const TextStyle(color: Colors.white, fontSize: 16)),
          ]),
          content: SizedBox(
            width: 460,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                // ── 回答の手動保存 (AI 画面で回答テキストを選択してから押す)。
                //    旧「回答を保存」 ボタンをここへ統合 (= ユーザー要望) ──
                Align(
                  alignment: Alignment.centerLeft,
                  child: TextButton.icon(
                    onPressed: () async {
                      final saved = await _saveAiAnswerFromSelection();
                      if (saved) {
                        list = await _AiQaHistoryStore.load();
                        setD(() {});
                      }
                    },
                    icon: const Icon(Icons.bookmark_add_rounded,
                        color: Color(0xFF43B97F), size: 18),
                    label: Text(
                        context
                            .read<MindMapProvider>()
                            .t('pdf.saveSelectedAnswer'),
                        style:
                            TextStyle(color: Color(0xFF43B97F), fontSize: 12)),
                  ),
                ),
                const Divider(color: Colors.white12, height: 12),
                list.isEmpty
                    ? Padding(
                        padding: const EdgeInsets.all(16),
                        child: Text(
                            context.read<MindMapProvider>().t('pdf.noHistory'),
                            style: TextStyle(color: Colors.white38)),
                      )
                    : ConstrainedBox(
                        constraints: const BoxConstraints(maxHeight: 420),
                        child: ListView.separated(
                          shrinkWrap: true,
                          itemCount: list.length,
                          separatorBuilder: (_, __) =>
                              const Divider(color: Colors.white12, height: 16),
                          itemBuilder: (_, i) {
                            final e = list[i];
                            return Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Row(children: [
                                  const Icon(Icons.help_outline_rounded,
                                      color: Color(0xFFBA68C8), size: 15),
                                  const SizedBox(width: 6),
                                  Expanded(
                                    child: SelectableText(e.question,
                                        style: const TextStyle(
                                            color: Colors.white,
                                            fontSize: 13,
                                            fontWeight: FontWeight.w600)),
                                  ),
                                  InkWell(
                                    onTap: () async {
                                      await _AiQaHistoryStore.removeAt(i);
                                      list = await _AiQaHistoryStore.load();
                                      setD(() {});
                                    },
                                    child: const Padding(
                                      padding: EdgeInsets.all(3),
                                      child: Icon(Icons.delete_outline_rounded,
                                          color: Color(0xFFE57373), size: 18),
                                    ),
                                  ),
                                ]),
                                const SizedBox(height: 4),
                                if (e.answer.isNotEmpty)
                                  SelectableText(e.answer,
                                      style: const TextStyle(
                                          color: Colors.white70, fontSize: 12))
                                else
                                  const Text(
                                      '（回答未保存）AI 画面で回答を選択 → 上の「選択中の回答を保存」',
                                      style: TextStyle(
                                          color: Colors.white30, fontSize: 11)),
                              ],
                            );
                          },
                        ),
                      ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(context.read<MindMapProvider>().t('btn.close'),
                  style: const TextStyle(color: Colors.white54)),
            ),
          ],
        );
      }),
    );
  }

  /// 動画の再生速度 (0.25 〜 2.0)。 動画サイトを開いた時に上部に
  /// オーバーレイ表示される Slider で操作。 デフォルト 1.0x。
  double _videoPlaybackRate = 1.0;
  bool _webHasVideo = false;

  /// メモ配置モード: 有効ならビューアの上に GestureDetector が乗る
  /// ドック中の Google 検索サイドバーの横幅。
  /// 通常モード (= 検索ドック解除中) はこの値は使わず、 固定 280px。
  /// リサイズハンドルのドラッグで更新される。 ダイアログを閉じるまで保持。
  double _dockedSidebarWidth = 480.0;
  bool _placingMemo = false;

  /// ハイライト中のメモ ID (パルスアニメ用)
  String? _highlightMemoId;

  /// ── PDF 内検索でメモ本文にもヒットさせる (= ユーザー要望) ──
  /// 検索語にマッチしたメモの一覧と、 現在ジャンプ中のインデックス。
  List<PdfMemo> _memoSearchMatches = [];
  int _memoSearchActiveIdx = 0;
  late final AnimationController _pulseCtrl;

  /// URL モード時の現在スクロール位置 (Y, ピクセル)。 メモ追加時に
  /// snapshot して保存し、 メモジャンプ時に scrollTo で復元する。
  double _currentScrollY = 0;

  // ─── ページ番号ジャンプ + 検索 (PDF モード) ──
  /// タイトルバー右側のページ番号入力欄
  late final TextEditingController _pageInputCtrl;

  /// 検索バーの入力欄
  late final TextEditingController _searchCtrl;

  /// 検索バーが開いているか
  bool _searchBarOpen = false;

  /// SfPdfViewer の検索結果。 add/notify でハイライトと件数が同期される。
  sf_pdf.PdfTextSearchResult? _searchResult;
  // ─── URL モードの Find in Page (検索) ──
  /// flutter_inappwebview の `findAllAsync` がヒットしたインスタンス番号
  /// (1-indexed)。 onFindResultReceived で更新される。 0 = 未検索。
  int _urlActiveMatch = 0;

  /// 同 ヒット総数。 webview_windows (`window.find`) では取得不可なので 0。
  int _urlMatchCount = 0;

  /// 直前に検索した文字列 (`window.find` を「次へ / 前へ」 で使い回すため)。
  String _lastSearchQuery = '';
  // ─── ホイールスクロール感度ブースト ──
  /// SfPdfViewer 単体ではマウスホイール 1 ティックでわずかしか動かず
  /// (Windows の OS 行数設定に従うため)、 大きい PDF を読むのが遅い。
  /// Listener で PointerScrollEvent を捕捉してデルタを蓄積し、 閾値を
  /// 超えるごとに `previousPage / nextPage` を追加で叩くことで、
  /// syncfusion 内部の連続スクロールに加えて 1 ページ単位の高速送りを
  /// 上乗せする。 結果ホイール 1 ティックでざっくり 1 ページ動く感覚に。
  double _wheelAccum = 0;
  // ─── PDF キーボード操作 ──
  /// ↑↓ で小刻みスクロール、 PageUp/PageDown でページ送りするための
  /// Focus ノード。 ビューアにキャプチャするキーボードイベントを担う。
  /// 検索バーや配置モード時は子 TextField がフォーカスを奪うので競合しない。
  late final FocusNode _pdfFocusNode;

  /// 現在 PDF ビューア内で選択中のテキスト。 null または空文字なら未選択。
  /// `onTextSelectionChanged` で更新され、 ハイライト追加ボタンの表示制御に使う。
  String? _selectedPdfText;

  /// 選択中テキストの行ごとの bounds (= List<PdfTextLine> 相当)。
  /// 新しめの syncfusion では `PdfTextSelectionChangedDetails.selectedTextLines`
  /// として渡ってくるが、 古いバージョンにはこのプロパティが無いため `dynamic` で
  /// 受けて存在チェック付きで使う。 HighlightAnnotation に渡す素材。
  dynamic _selectedPdfLines;

  /// 現在選択中のマーカー色。 null = マーカーモード OFF (マーカー追加 FAB は出ない)。
  /// non-null = マーカーモード ON で、 テキスト選択中に FAB が出てこの色で
  /// HighlightAnnotation が追加される。 ツールバーのマーカーボタンから切替可能。
  Color? _activeMarkerColor;

  /// 今セッションで追加したマーカーの ID 集合。 PDF を閉じるときに
  /// 「破棄して閉じる」 を選ばれた場合、 この集合の ID を provider から削除する。
  /// auto-save 直後に追加するので、 アプリ再起動された場合は既に保存済み扱い
  /// (= rollback 不能) で問題なし。
  final Set<String> _sessionAddedHighlightIds = {};

  /// マーカーモード ON 中の自動適用デバウンス用タイマ。 テキスト選択中に
  /// `onTextSelectionChanged` が連続で発火するため、 「選択が安定して N ms
  /// 経った」 ら適用する設計。 範囲ドラッグ中の中間状態で適用されるのを防ぐ。
  Timer? _highlightAutoTimer;

  /// 直近で auto-apply したテキスト (重複適用ガード)。 同じ選択を 2 度自動
  /// ハイライトしないために覚えておく。
  String? _lastAutoAppliedText;

  /// 自分で `addAnnotation` を呼ぶとき、 syncfusion の `onAnnotationAdded`
  /// コールバックが回って二重保存になるのを防ぐためのガードフラグ。
  /// `_addHighlightForSelection` / `_restoreSavedHighlights` 中だけ true。
  bool _suppressAnnotationCallback = false;

  /// ←/→ や PageUp/Down 等の単発ページ操作の overshoot 抑止 (キー単位ロック)。
  /// KeyDown でロック (timestamp) を入れ、 KeyUp で解除する。 ロック中の
  /// 同キーの追加 KeyDown は無視され、 1 押下 = 1 アクションが保証される。
  /// KeyUp が届かなかった場合のセーフティとして 2 秒で自動解除。
  final Map<LogicalKeyboardKey, DateTime> _heldPageActionKeyAt = {};
  static const Duration _heldPageActionTimeout = Duration(seconds: 2);

  bool get _useWebView2 => Platform.isWindows && !widget.isPdf;

  @override
  void initState() {
    super.initState();
    _currentUrl = widget.url;
    if (isSafeExternalServiceUrl(widget.url)) {
      _oauthLastSafeServiceUrl = widget.url;
    }
    // 画面分割から引き継いだ再生速度を初期値に (ユーザー要望)。
    _videoPlaybackRate = widget.initialRate;
    _pulseCtrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 2400),
    );
    _pageInputCtrl = TextEditingController();
    _searchCtrl = TextEditingController();
    // ── メモ欄の初期表示 ──
    // PDF は「ページ紐付けメモ」 が主機能なので開いた状態で始める。
    // 一方、 URL を踏んで開いた Web ページではメモが勝手に開くと邪魔なので
    //   閉じた状態で始める (= ユーザー要望: 普通の Google 検索と同じ見た目に)。
    //   必要ならメモボタン で開ける。
    // 狭い場所 (フローティング / 分割) ではメモも自動では開かない
    // (= ユーザー要望)。
    _memoPanelOpen = widget.isPdf && !widget.compactHost;
    // ── PC で PDF を開いたら、 メモ欄と AI 欄を「PDF 読み込み後に同時に」 開く
    //    (= ユーザー要望: メモだけ起動時に付いて AI が後から開くのは変なので、
    //     読み込んでから両方一緒に出す)。 そのため、 この自動オープン対象では
    //     メモも起動時には開かず、 onDocumentLoaded 後に AI と同時に開く予約だけ
    //     立てる。 PDF と AI(WebView) を同時生成して固まるのを防ぐ遅延も維持。 ──
    // 「プログラムから開く」 (まだノード未紐付け = onEnsureNode あり) でも
    // 普通に埋め込んで開いた時と同じく自動で開く (= ユーザー要望)。
    if (widget.isPdf &&
        !widget.compactHost &&
        (_nodeId != null || widget.onEnsureNode != null) &&
        Platform.isWindows) {
      _pendingAiAutoOpen = true;
      // 読み込み後に AI と一緒に開くので、 起動時はメモも閉じておく。
      _memoPanelOpen = false;
      // ただし 「場所」 だけは最初から取っておく (= ユーザー要望: 立ち上がりを
      //   速く)。 後から割り込ませると PDF が二度描かれて遅く見える。
      _panelSlotsReserved = true;
    }
    _pdfFocusNode = FocusNode(debugLabel: 'pdf_viewer_dialog');
    // ignore: discarded_futures
    _loadPdfPanMode();
    // メモ/AI パネルのトグルを WebView・PDF どちらでも効かせる
    //   ため、 グローバルキーハンドラは常に登録する (= ユーザー要望: URL
    //   から開いた Web ページでもショートカットを使えるようにする)。
    HardwareKeyboard.instance.addHandler(_globalPdfKeyHandler);
    if (widget.isPdf) {
      _initPdf();
    } else if (_useWebView2) {
      _initWindows();
    }
  }

  /// widget.url から実ファイルパスを抽出。
  /// file:// URL もしくは生のパス文字列を扱う。 http(s) URL はサポート外。
  String? _resolveLocalPdfPath() {
    String u = widget.url;
    final qi = u.indexOf('?');
    if (qi >= 0) u = u.substring(0, qi);
    final hi = u.indexOf('#');
    if (hi >= 0) u = u.substring(0, hi);
    if (u.startsWith('file://')) {
      try {
        return Uri.parse(u).toFilePath(windows: Platform.isWindows);
      } catch (_) {
        return null;
      }
    }
    if (!u.contains('://')) return u;
    return null;
  }

  void _initPdf() {
    final path = _resolveLocalPdfPath();
    if (path == null) {
      setState(() => _pdfError = 'PDF パスを解決できませんでした');
      return;
    }
    final file = File(path);
    if (!file.existsSync()) {
      setState(() => _pdfError = 'ファイルが見つかりません: $path');
      return;
    }
    final fname = path.split(Platform.isWindows ? '\\' : '/').last;
    // 開いている間は控えておく (= 同じファイルを他の処理が同時に触って
    // 落ちるのを避ける。 ユーザー報告: 手書き保存の直後に落ちる)。
    kOpenPdfPaths.add(path);
    setState(() {
      _pdfFilePath = path;
      _pdfViewerCtrl = sf_pdf.PdfViewerController();
      if (_title.isEmpty) _title = fname;
    });
    _viewerMark('initPdf done');
  }

  Future<void> _handoffViewerOAuthToExternalBrowser(
    wv_win.WebviewController ctrl,
  ) async {
    final now = DateTime.now();
    final last = _lastOAuthHandoffAt;
    if (_oauthHandoffInProgress ||
        (last != null && now.difference(last) < const Duration(seconds: 30))) {
      return;
    }
    final fallback = isSafeExternalServiceUrl(_oauthLastSafeServiceUrl)
        ? _oauthLastSafeServiceUrl
        : (isSafeExternalServiceUrl(widget.url) ? widget.url : '');
    if (fallback.isEmpty) return;

    _oauthHandoffInProgress = true;
    _lastOAuthHandoffAt = now;
    try {
      final opened = await launchUrl(
        Uri.parse(fallback),
        mode: LaunchMode.externalApplication,
      );
      if (opened && mounted) {
        _appSnack(
          context,
          SnackBar(
            content: Text(context.read<MindMapProvider>().t('login.externalBrowser')),
            backgroundColor: const Color(0xFF6C63FF),
            duration: Duration(seconds: 3),
          ),
        );
      }
    } catch (e) {
      debugPrint('OAuth 外部ブラウザ起動失敗: $e');
    } finally {
      // 認証 URL を WebView2 に残すと更新が繰り返されるため、直前の
      // サービス画面へ一度だけ戻す。外部ブラウザ側ではそのまま認証できる。
      try {
        await ctrl.loadUrl(fallback);
      } catch (_) {}
      Future<void>.delayed(const Duration(seconds: 2), () {
        if (mounted) _oauthHandoffInProgress = false;
      });
    }
  }

  Future<void> _initWindows() async {
    try {
      final ctrl = wv_win.WebviewController();
      await ctrl.initialize();
      try {
        await ctrl
            .setPopupWindowPolicy(wv_win.WebviewPopupWindowPolicy.sameWindow);
      } catch (_) {}
      ctrl.title.listen((t) {
        if (mounted && t.isNotEmpty) setState(() => _title = t);
      });
      // URL 変化を listen してメモのフィルタリングに反映
      ctrl.url.listen((u) {
        if (isBlockedEmbeddedOAuthUrl(u)) {
          unawaited(_handoffViewerOAuthToExternalBrowser(ctrl));
          return;
        }
        if (isSafeExternalServiceUrl(u)) {
          _oauthLastSafeServiceUrl = u;
        }
        if (mounted && u.isNotEmpty) {
          setState(() => _currentUrl = u);
          _scheduleWebVideoProbe();
        }
      });
      // 初回リダイレクトも認証 URL 監視の対象にする。
      await ctrl.loadUrl(widget.url);
      if (mounted) {
        setState(() {
          _winCtrl = ctrl;
          _winReady = true;
        });
        _scheduleWebVideoProbe();
      }
    } catch (e) {
      if (mounted) {
        setState(() => _winError = '$e');
      }
    }
  }

  /// 現在のスクロール位置を取得 (URL モード)。
  /// - WebView2 (Windows): executeScript で `window.scrollY` を読む
  /// - InAppWebView: onScrollChanged で更新済みの `_currentScrollY` を返す
  Future<double> _getCurrentScrollY() async {
    if (widget.isPdf) return 0;
    if (_useWebView2 && _winCtrl != null) {
      try {
        final v = await _winCtrl!.executeScript('window.scrollY');
        if (v is num) return v.toDouble();
        if (v is String) return double.tryParse(v) ?? 0;
      } catch (_) {}
      return 0;
    }
    return _currentScrollY;
  }

  /// JavaScript で window.scrollTo を実行してスクロール位置を復元。
  Future<void> _restoreScrollY(double y) async {
    if (widget.isPdf) return;
    final js = 'window.scrollTo(0, $y)';
    if (_useWebView2 && _winCtrl != null) {
      try {
        await _winCtrl!.executeScript(js);
      } catch (_) {}
    } else if (_iawCtrl != null) {
      try {
        await _iawCtrl!.evaluateJavascript(source: js);
      } catch (_) {}
    }
    _currentScrollY = y;
  }

  @override
  void dispose() {
    // 開いていた PDF の控えを外す (= 他の処理が触ってよくなる)。
    final op = _pdfFilePath;
    if (op != null) kOpenPdfPaths.remove(op);
    // 登録を常時化したので解除も常時行う (PDF/Web どちらでも)。
    HardwareKeyboard.instance.removeHandler(_globalPdfKeyHandler);
    _pulseCtrl.dispose();
    _winCtrl?.dispose();
    _aiWinController?.dispose();
    _pdfViewerCtrl?.dispose();
    _pageInputCtrl.dispose();
    _searchCtrl.dispose();
    _pdfFocusNode.dispose();
    _searchResult?.removeListener(_onSearchUpdated);
    _searchResult?.clear();
    _highlightAutoTimer?.cancel();
    // AI 質問キャプチャのポーリング Timer もキャンセル。
    _aiQCaptureTimer?.cancel();
    _fitPageDebounce?.cancel();
    _spreadPageDebounce?.cancel();
    _spreadRenderGeneration++;
    _fitPageBytes = null;
    _spreadPageImages.clear();
    _spreadPageImageSizes.clear();
    _spreadTransformController.dispose();
    // 音声読み上げを停止・破棄 (= ユーザー要望)。
    _reader?.dispose();
    super.dispose();
  }

  /// SfPdfViewer 上のマウスホイールイベントを受けて、 内部スクロールに加えて
  /// 細かいスクロールを足す。
  /// 旧実装はデルタを 80px 溜めるごとに `previousPage / nextPage` を叩いて
  /// いたため、 「カーソルを少し動かしただけでページが飛んでしまう」 という
  /// 指摘があった (= ユーザー要望)。 continuous モードでは scrollOffset を直接
  /// ずらせるので、 _onPdfKeyEvent の ↑/↓ と同じ 1/N ページぶん
  /// (N = pdfArrowStepDivisor) だけ jumpTo して、 ホイールも「上下キー入力と
  /// 同程度」 の細かさでスクロールするようにする。
  /// (PDF が開かれていないときや非 PDF モードでは何もしない)
  void _onPdfPointerSignal(PointerSignalEvent event) {
    if (event is! PointerScrollEvent) return;
    if (_pdfViewerCtrl == null || _pdfTotalPages <= 0) return;
    _wheelAccum += event.scrollDelta.dy;
    // この量デルタが溜まるごとに「上下キー 1 回ぶん」 のステップを 1 つ送る。
    const double notch = 80.0;
    if (_wheelAccum.abs() < notch) return;
    final notches = (_wheelAccum / notch).truncate(); // 符号付きノッチ数
    _wheelAccum -= notches * notch; // 端数は次回へ持ち越し
    try {
      final divisor =
          context.read<MindMapProvider>().pdfArrowStepDivisor.clamp(1, 100);
      // ↑/↓ キーと同じステップ量 (1 ページの 1/N) を算出する。
      final viewportH = MediaQuery.of(context).size.height;
      final estimatedPageH = viewportH > 0 ? viewportH * 1.0 : 800.0;
      final step = estimatedPageH / divisor;
      final cur = _pdfViewerCtrl!.scrollOffset;
      _pdfViewerCtrl!.jumpTo(
        xOffset: cur.dx,
        yOffset: cur.dy + step * notches,
      );
    } catch (_) {}
  }

  /// PDF ビューアにフォーカスがある時のキーボード入力を捕捉。
  /// - ↑/↓: scrollOffset を 1/N ページ分ずつずらす細かいスクロール
  ///   (N は `pdfArrowStepDivisor` 設定値)。 continuous レイアウトなので
  ///   ページ境界もそのまま跨いで滑らかにスクロールする。
  /// - ←/→ / PageUp/PageDown: 即時 1 ページ送り
  /// - Home / End: 先頭 / 末尾ページへジャンプ
  /// - M: メモ配置モードのトグル (メモ機能が利用可能なときのみ)
  ///
  /// 注: 検索バーや配置モード時は子 TextField がフォーカスを取るので、
  ///     ↑↓ がカーソル移動に使われ PDF には届かない (= 自然な競合解消)。
  KeyEventResult _onPdfKeyEvent(FocusNode node, KeyEvent event) {
    // KeyUp はロック解除のためだけにハンドル (アクションは起こさない)
    if (event is KeyUpEvent) {
      _heldPageActionKeyAt.remove(event.logicalKey);
      return KeyEventResult.ignored;
    }
    // KeyDown / KeyRepeat (= 押しっぱなし) のみアクション対象
    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
      return KeyEventResult.ignored;
    }
    // ── メモパネル / AI パネルの ON/OFF トグル (= ユーザー要望) ──
    // Ctrl+M = メモパネル開閉、 Ctrl+I (または F4) = AI チャット
    //   欄開閉。 PDF コントローラの有無に関係なく (URL ビューワーでも) 効くよう、
    //   `_pdfViewerCtrl == null` の早期 return より前に処理する。
    // KeyRepeat では連続トグルしないよう KeyDown のみ受ける。
    if (event is KeyDownEvent) {
      final isCtrlForPanel = HardwareKeyboard.instance.isControlPressed ||
          HardwareKeyboard.instance.isMetaPressed;
      if (isCtrlForPanel && event.logicalKey == LogicalKeyboardKey.keyM) {
        _suppressPdfPageChangeBriefly();
        setState(() => _memoPanelOpen = !_memoPanelOpen);
        return KeyEventResult.handled;
      }
      // AI チャット欄: Ctrl+I または F4 (= 同上、 ずらして F4 に)
      if ((isCtrlForPanel && event.logicalKey == LogicalKeyboardKey.keyI) ||
          event.logicalKey == LogicalKeyboardKey.f4) {
        if (_aiPanelOpen) {
          _suppressPdfPageChangeBriefly();
          setState(() {
            _aiPanelOpen = false;
            _aiWebViewCache = null; // ★ フリーズ対策: 閉じたら WebView キャッシュを破棄
          });
        } else {
          _openAiPanel(context.read<MindMapProvider>().pdfAiPanelDefault);
        }
        return KeyEventResult.handled;
      }
    }
    if (_pdfViewerCtrl == null || _pdfTotalPages <= 0) {
      return KeyEventResult.ignored;
    }
    final key = event.logicalKey;

    // ── Ctrl+Z / Ctrl+Shift+Z / Ctrl+Y: 元に戻す / やり直し ──
    // ユーザー要望「Ctrl+Z で削除したメモを復元」。削除はページ単位の
    //   undo 履歴に積まるので provider.undo() で復元できる。ここ
    //   (_onPdfKeyEvent) に集約することで、PDF 本体・メモ欄・どこに
    //   フォーカスがあっても (グローバルハンドラ経由で) 単発で動く。
    final isCtrlForUndo = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    if (isCtrlForUndo && key == LogicalKeyboardKey.keyZ) {
      final provider = context.read<MindMapProvider>();
      if (HardwareKeyboard.instance.isShiftPressed) {
        provider.redo();
      } else {
        provider.undo();
      }
      return KeyEventResult.handled;
    }
    if (isCtrlForUndo && key == LogicalKeyboardKey.keyY) {
      context.read<MindMapProvider>().redo();
      return KeyEventResult.handled;
    }

    // ── Ctrl+\ / Ctrl+^: フルスクリーン PDF を閉じて画面分割に切替 ──
    // ユーザー要望: 「全画面表示の画面からもこのショートカットキーで画面
    // 分割画面に切り替わるようにして」。
    final isCtrlForSplit = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    final isShiftForSplit = HardwareKeyboard.instance.isShiftPressed;
    if (isCtrlForSplit && _pdfFilePath != null) {
      final isSplitRight =
          !isShiftForSplit && key == LogicalKeyboardKey.backslash;
      final isSplitLeft = key == LogicalKeyboardKey.caret ||
          event.physicalKey == PhysicalKeyboardKey.equal ||
          (event.character ?? '') == '^' ||
          (isShiftForSplit &&
              (key == LogicalKeyboardKey.digit6 ||
                  key == LogicalKeyboardKey.numpad6));
      if (isSplitRight || isSplitLeft) {
        final cb = widget.onMoveToSplitPanel;
        if (cb != null) {
          try {
            cb(_pdfFilePath!, isLeftPanel: isSplitLeft);
          } catch (e) {
            debugPrint('画面分割への切替失敗: $e');
          }
        }
        try {
          Navigator.of(context).pop();
        } catch (_) {}
        return KeyEventResult.handled;
      }
    }

    // ── Ctrl+ / Ctrl- : PDF ズームレベル調整 (Dialog 版) ──
    // ユーザー要望: 「ctrl+ \"+\" or \"-\" で閲覧している PDF の拡大率を調整
    // できるようにして」。 syncfusion の zoomLevel は 1.0〜maxZoomLevel (4.0)。
    final isCtrl = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    if (isCtrl) {
      final isZoomIn = key == LogicalKeyboardKey.equal ||
          key == LogicalKeyboardKey.add ||
          key == LogicalKeyboardKey.numpadAdd;
      final isZoomOut = key == LogicalKeyboardKey.minus ||
          key == LogicalKeyboardKey.numpadSubtract;
      if (isZoomIn || isZoomOut) {
        if (_spreadFitPageMode) {
          _adjustSpreadZoom(isZoomIn);
          return KeyEventResult.handled;
        }
        try {
          if (isZoomIn && _fitPageMode) {
            _toggleFitPage();
            return KeyEventResult.handled;
          }
          final current = _pdfViewerCtrl!.zoomLevel;
          if (isZoomOut && current <= 1.001 && !_fitPageMode) {
            _toggleFitPage();
            return KeyEventResult.handled;
          }
          // ステップを 0.1 に小さくして微調整できるように (= ユーザー要望)。
          // ステップを 0.05 に細かくし、 上限も 8.0 まで広げる
          // (= ユーザー要望: 拡大率をもっと微調整できるように)。
          // Shift を押している間はさらに細かく 0.02 刻み。
          final fine = HardwareKeyboard.instance.isShiftPressed;
          final step = fine ? 0.02 : 0.05;
          final delta = isZoomIn ? step : -step;
          final next = (current + delta).clamp(1.0, 8.0);
          _pdfViewerCtrl!.zoomLevel = next;
          // ズーム直後に onPageChanged が巻き添え発火してページ番号が
          //   動くのを防ぐ (= ユーザー要望)。一定時間ページ更新を抑制。
          _suppressPageChangeUntilMs =
              DateTime.now().millisecondsSinceEpoch + 700;
        } catch (e) {
          debugPrint('PDF zoom 調整失敗: $e');
        }
        return KeyEventResult.handled;
      }
    }
    // ── ↑/↓: 1/N ページ分の sub-page スクロール (= 以前の挙動を復元) ──
    // ユーザー要望: 「以前の様な ↑↓ で 1/20 ページずつ動く」 挙動に戻す。
    // continuous モードなので、 scrollOffset を直接操作することで
    // ページ境界も跨いで滑らかに移動する。 N は pdfArrowStepDivisor 設定値。
    if (key == LogicalKeyboardKey.arrowDown ||
        key == LogicalKeyboardKey.arrowUp) {
      // 横読み (左右) の時は上下キーでページ移動 / スクロールしない
      //   (= ユーザー要望)。 ページ送りは左右キーで行う。
      if (context.read<MindMapProvider>().pdfScrollHorizontal) {
        return KeyEventResult.handled;
      }
      try {
        final dir = key == LogicalKeyboardKey.arrowDown ? 1 : -1;
        // 1 ページの 1/N (= デフォルト 1/20) スクロール量を計算
        final provider = context.read<MindMapProvider>();
        final divisor = provider.pdfArrowStepDivisor.clamp(1, 100);
        // 現在表示中の 1 ページの高さを近似 (= ビューポート高さの 1.4 倍程度)
        final viewportH = MediaQuery.of(context).size.height;
        final estimatedPageH = viewportH > 0 ? viewportH * 1.0 : 800.0;
        final step = estimatedPageH / divisor;
        final cur = _pdfViewerCtrl!.scrollOffset;
        _pdfViewerCtrl!.jumpTo(
          xOffset: cur.dx,
          yOffset: cur.dy + step * dir,
        );
      } catch (_) {}
      return KeyEventResult.handled;
    }
    // ── ここから下は単発キー (1 押下 = 1 アクション) ──
    // KeyRepeat は無視。 KeyDown もキー単位ロックで「押しっぱなし中の追加発火」
    // と「OS/ドライバ起因の二重発火」 を全部潰す。
    if (event is KeyRepeatEvent) {
      return KeyEventResult.handled;
    }
    // ←/→: 既定では syncfusion 組み込みの 1 ページ送り (ignored で委譲)。
    // パンモード (_pdfArrowPanMode) の時はページ送りせず、 表示領域を横方向に
    // スクロールする (ユーザー要望: 拡大時に左右キーで横を見たい)。
    if (key == LogicalKeyboardKey.arrowRight ||
        key == LogicalKeyboardKey.arrowLeft) {
      if (_spreadPageMode || _spreadFitPageMode) {
        _jumpSpreadPages(key == LogicalKeyboardKey.arrowRight ? 2 : -2);
        return KeyEventResult.handled;
      }
      if (_pdfArrowPanMode) {
        try {
          final dir = key == LogicalKeyboardKey.arrowRight ? 1 : -1;
          final viewportW = MediaQuery.of(context).size.width;
          final step = (viewportW > 0 ? viewportW : 800.0) / 6;
          final cur = _pdfViewerCtrl!.scrollOffset;
          _pdfViewerCtrl!.jumpTo(
            xOffset: cur.dx + step * dir,
            yOffset: cur.dy,
          );
        } catch (_) {}
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    }
    final isSingleShotKey = key == LogicalKeyboardKey.pageDown ||
        key == LogicalKeyboardKey.pageUp ||
        key == LogicalKeyboardKey.home ||
        key == LogicalKeyboardKey.end;
    if (isSingleShotKey) {
      final lockedAt = _heldPageActionKeyAt[key];
      if (lockedAt != null &&
          DateTime.now().difference(lockedAt) < _heldPageActionTimeout) {
        return KeyEventResult.handled;
      }
      _heldPageActionKeyAt[key] = DateTime.now();
    }
    // ── PageUp/PageDown: 1 ページ単位のページめくり ──
    if (key == LogicalKeyboardKey.pageDown) {
      if (_spreadPageMode || _spreadFitPageMode) {
        _jumpSpreadPages(2);
        return KeyEventResult.handled;
      }
      try {
        _pdfViewerCtrl!.nextPage();
      } catch (_) {}
      return KeyEventResult.handled;
    } else if (key == LogicalKeyboardKey.pageUp) {
      if (_spreadPageMode || _spreadFitPageMode) {
        _jumpSpreadPages(-2);
        return KeyEventResult.handled;
      }
      try {
        _pdfViewerCtrl!.previousPage();
      } catch (_) {}
      return KeyEventResult.handled;
    }
    // ── テキスト編集中は単キーショートカット (M/B/N) を無効化 ──
    // (= ユーザー要望: メモのインライン編集中に半角の n/N で新規メモが
    //   立ち上がってしまうのを防ぐ)。検索バーやメモ編集の EditableText に
    //   フォーカスがある間は、 文字キーは純粋な文字入力に専念させる。
    // Ctrl 系ショートカット (Ctrl+M / Ctrl+I 等) は上で処理済み。
    final editingTextField =
        FocusManager.instance.primaryFocus?.context?.widget is EditableText;
    // インライン編集中も (フォーカスが TextField から外れていても) ガード
    final inlineEditing = _pdfMemoInlineEditing.value;
    if ((editingTextField || inlineEditing) &&
        (key == LogicalKeyboardKey.keyM ||
            key == LogicalKeyboardKey.keyB ||
            key == LogicalKeyboardKey.keyN)) {
      return KeyEventResult.ignored;
    }
    if (key == LogicalKeyboardKey.home) {
      try {
        _pdfViewerCtrl!.firstPage();
      } catch (_) {}
      return KeyEventResult.handled;
    } else if (key == LogicalKeyboardKey.end) {
      try {
        _pdfViewerCtrl!.lastPage();
      } catch (_) {}
      return KeyEventResult.handled;
    } else if (key == LogicalKeyboardKey.keyM) {
      // ── M: メモ配置モードのトグル (メモ機能が有効なときだけ) ──
      // KeyDown の最初の 1 回だけ反応 (押しっぱなしでも連発しない)
      if (event is KeyDownEvent && _nodeId != null) {
        setState(() => _placingMemo = !_placingMemo);
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    } else if (key == LogicalKeyboardKey.keyB) {
      // ── B: メモパネルの開閉トグル ──
      if (event is KeyDownEvent && _nodeId != null) {
        _suppressPdfPageChangeBriefly();
        setState(() => _memoPanelOpen = !_memoPanelOpen);
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    } else if (key == LogicalKeyboardKey.keyN) {
      // ── N: フリーメモ追加ダイアログ ──
      if (event is KeyDownEvent && _nodeId != null) {
        _openFreeMemoQuickDialog();
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    } else if (key == LogicalKeyboardKey.keyZ) {
      // ── Ctrl+Z (⌘+Z): Undo ──
      // ビューアは modal route のためメイン画面のキーボード handler が
      // 走らない。 ビューア内で削除した PdfMemo もここで戻せる。
      final hk = HardwareKeyboard.instance;
      final ctrlOrCmd =
          hk.isLogicalKeyPressed(LogicalKeyboardKey.controlLeft) ||
              hk.isLogicalKeyPressed(LogicalKeyboardKey.controlRight) ||
              hk.isLogicalKeyPressed(LogicalKeyboardKey.metaLeft) ||
              hk.isLogicalKeyPressed(LogicalKeyboardKey.metaRight);
      if (event is KeyDownEvent && ctrlOrCmd) {
        try {
          context.read<MindMapProvider>().undo();
        } catch (_) {}
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    }
    return KeyEventResult.ignored;
  }

  /// フリーメモ追加ダイアログを開く (= N キーから呼ばれる)。
  /// メモパネルが閉じている場合は同時に開いて、 結果がすぐ見えるようにする。
  Future<void> _openFreeMemoQuickDialog() async {
    final nid = await _ensureNode();
    if (nid == null || !mounted) return;
    if (mounted && !_memoPanelOpen) {
      _suppressPdfPageChangeBriefly();
      setState(() => _memoPanelOpen = true);
    }
    final provider = context.read<MindMapProvider>();
    final created = await showDialog<PdfMemo?>(
      context: context,
      builder: (_) => const _PdfMemoEditDialog(freeMode: true),
    );
    if (created != null) {
      provider.addPdfMemo(
        nid,
        text: created.text,
        pageNumber: created.pageNumber,
        colorValue: created.colorValue,
      );
    }
  }

  /// SfPdfViewer は内部のジェスチャ系ウィジェットがクリック時に focus を
  /// 奪うため、 Focus widget の onKeyEvent だけだとビューアを一度クリック
  /// した瞬間に ↑↓ が届かなくなる。 これを回避するため、 メインキャンバス
  /// と同じく HardwareKeyboard レベルでもグローバルに捕捉して
  /// `_onPdfKeyEvent` に転送する。
  ///
  /// 譲る条件:
  ///   - PDF モードでない / ビューア未準備
  ///   - 別の route が前面 (このダイアログより上にダイアログが乗ってる等)
  ///   - TextField が編集中 (検索バー / ページ番号入力欄など)
  bool _globalPdfKeyHandler(KeyEvent event) {
    if (!mounted) return false;
    if (event is! KeyDownEvent && event is! KeyRepeatEvent) return false;

    // ★ PDF の Focus がフォーカスを持っているなら Focus.onKeyEvent が
    //   既に処理するので、 HardwareKeyboard 経由の重複起動を防ぐ。
    if (_pdfFocusNode.hasFocus) return false;

    final route = ModalRoute.of(context);
    if (route == null || !route.isCurrent) return false;

    final focused = FocusManager.instance.primaryFocus;
    if (focused != null && focused.context?.widget is EditableText) {
      return false;
    }

    // ── メモ / AI パネルのトグルは PDF・Web どちらのビューアでも効かせる ──
    // (= ユーザー要望: Web サイトのリンクを開いた時にもショートカットが
    //   効くように。 旧実装は冒頭で `!widget.isPdf` の場合に即 return して
    //   いたため、 Web ページ表示中は WebView がフォーカスを握り、
    //   Ctrl+M (メモ) ・ Ctrl+I/F4 (AI) が効かなかった。)
    if (event is KeyDownEvent) {
      final isCtrlForPanel = HardwareKeyboard.instance.isControlPressed ||
          HardwareKeyboard.instance.isMetaPressed;
      if (isCtrlForPanel && event.logicalKey == LogicalKeyboardKey.keyM) {
        _suppressPdfPageChangeBriefly();
        setState(() => _memoPanelOpen = !_memoPanelOpen);
        return true;
      }
      if ((isCtrlForPanel && event.logicalKey == LogicalKeyboardKey.keyI) ||
          event.logicalKey == LogicalKeyboardKey.f4) {
        if (_aiPanelOpen) {
          _suppressPdfPageChangeBriefly();
          setState(() {
            _aiPanelOpen = false;
            _aiWebViewCache = null; // ★ フリーズ対策: 閉じたら WebView キャッシュを破棄
          });
        } else {
          _openAiPanel(context.read<MindMapProvider>().pdfAiPanelDefault);
        }
        return true;
      }
      // F6: メモ欄 / AI 欄(サイドパネル)の左右を入れ替え (= ユーザー要望)
      if (event.logicalKey == LogicalKeyboardKey.f6) {
        _suppressPdfPageChangeBriefly();
        setState(() => _panelsSwapped = !_panelsSwapped);
        return true;
      }
    }

    // ── ここから先は PDF 専用 (ページ送り等) ──
    if (!widget.isPdf) return false;
    if (_pdfViewerCtrl == null || _pdfTotalPages <= 0) return false;

    // ── メモパネルにキーボードフォーカスがある間は ↑/↓ をパネル専用に
    //    予約 (= ユーザー要望: メモ欄を上下キーで移動しているのに PDF
    //    まで動いてしまうバグの修正) ──
    if (_pdfMemoPanelHasKeyboardFocus.value &&
        (event.logicalKey == LogicalKeyboardKey.arrowUp ||
            event.logicalKey == LogicalKeyboardKey.arrowDown ||
            event.logicalKey == LogicalKeyboardKey.arrowLeft ||
            event.logicalKey == LogicalKeyboardKey.arrowRight ||
            event.logicalKey == LogicalKeyboardKey.pageUp ||
            event.logicalKey == LogicalKeyboardKey.pageDown ||
            event.logicalKey == LogicalKeyboardKey.home ||
            event.logicalKey == LogicalKeyboardKey.end ||
            event.logicalKey == LogicalKeyboardKey.space)) {
      // メモ欄がアクティブな間は PDF 側のキー処理を完全に分離 (= ユーザー
      //   要望: メモ欄がアクティブになっていても PDF 欄が動いてしまうのを
      //   独立に動作させる)。 上下左右 / PageUp/Down / Home/End / Space を
      //   全部メモ側専用に予約。
      return false;
    }

    // ── インライン編集中は N/M/B キーを無効化 (= ユーザー要望: ダブル
    //    クリックでメモを編集中なのに半角の N で新規メモが立ち上がって
    //    しまう問題の修正) ──
    if (_pdfMemoInlineEditing.value &&
        (event.logicalKey == LogicalKeyboardKey.keyN ||
            event.logicalKey == LogicalKeyboardKey.keyM ||
            event.logicalKey == LogicalKeyboardKey.keyB)) {
      return false;
    }

    return _onPdfKeyEvent(_pdfFocusNode, event) == KeyEventResult.handled;
  }

  /// PDF キーバインドの設定ダイアログを開く。
  /// ↑/↓ の sub-page scroll の細かさ (divisor) と ←/→ のページジャンプ数を
  /// それぞれスライダーで調整できる。 値は MindMapProvider に保存される。
  Future<void> _showPdfArrowSettings() async {
    final provider = context.read<MindMapProvider>();
    final curDiv = provider.pdfArrowStepDivisor;
    final curJump = provider.pdfPageJumpCount;
    int? pickedDiv;
    int? pickedJump;
    await showDialog<void>(
      context: context,
      builder: (dctx) {
        double divVal = curDiv.toDouble().clamp(1.0, 100.0);
        double jumpVal = curJump.toDouble().clamp(1.0, 50.0);
        return StatefulBuilder(
          builder: (sctx, setLocal) => AlertDialog(
            // PDF の中央を隠さず値を見比べられるよう、設定欄は画面端へ寄せる。
            alignment: AlignmentDirectional.centerEnd,
            insetPadding: const EdgeInsets.fromLTRB(12, 24, 12, 24),
            title:
                Text(context.read<MindMapProvider>().t('pdf.keySettingsTitle')),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(context.read<MindMapProvider>().t('pdf.keyUpDown'),
                      style: TextStyle(fontWeight: FontWeight.w600)),
                  const SizedBox(height: 4),
                  Text(
                    '${divVal.round()} 回 (= 1 押下で 1/${divVal.round()} ページ移動)',
                    style: TextStyle(
                      fontSize: 11,
                      color: Theme.of(sctx).hintColor,
                    ),
                  ),
                  Slider(
                    min: 1,
                    max: 100,
                    divisions: 99,
                    value: divVal,
                    label: '${divVal.round()}',
                    onChanged: (v) {
                      setLocal(() => divVal = v);
                    },
                  ),
                  const Divider(height: 24),
                  Text(context.read<MindMapProvider>().t('pdf.keyLeftRight'),
                      style: TextStyle(fontWeight: FontWeight.w600)),
                  const SizedBox(height: 4),
                  Text(
                    '${jumpVal.round()} ページ (1 = 通常、 5 = 5 ページずつ飛ばし読み)',
                    style: TextStyle(
                      fontSize: 11,
                      color: Theme.of(sctx).hintColor,
                    ),
                  ),
                  Slider(
                    min: 1,
                    max: 50,
                    divisions: 49,
                    value: jumpVal,
                    label: '${jumpVal.round()}',
                    onChanged: (v) {
                      setLocal(() => jumpVal = v);
                    },
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dctx).pop(),
                child: Text(context.read<MindMapProvider>().t('btn.cancel')),
              ),
              FilledButton(
                onPressed: () {
                  pickedDiv = divVal.round().clamp(1, 100);
                  pickedJump = jumpVal.round().clamp(1, 50);
                  Navigator.of(dctx).pop();
                },
                child: Text(context.read<MindMapProvider>().t('btn.save')),
              ),
            ],
          ),
        );
      },
    );
    if (pickedDiv != null && pickedDiv != curDiv) {
      await provider.setPdfArrowStepDivisor(pickedDiv!);
    }
    if (pickedJump != null && pickedJump != curJump) {
      await provider.setPdfPageJumpCount(pickedJump!);
    }
  }

  /// 選択中のテキストに HighlightAnnotation を追加し、 provider にも保存。
  /// `onTextSelectionChanged` で `_selectedPdfText` / `_selectedPdfLines` が
  /// セットされている前提。 行 bounds の取得元として
  ///   1) `_selectedPdfLines` (= details.selectedTextLines, 新しめの API)
  ///   2) controller.getSelectedTextLines() を dynamic 越しに (古めの API)
  /// の順で試行する。 どちらも取れないバージョンでは SnackBar で告知。
  Future<void> _addHighlightForSelection() async {
    if (_pdfViewerCtrl == null || _nodeId == null) return;
    if (_selectedPdfText == null || _selectedPdfText!.isEmpty) return;

    // ── 行 bounds をなんとかして手に入れる ──
    List<dynamic> rawLines = const [];
    try {
      final cached = _selectedPdfLines;
      if (cached is List && cached.isNotEmpty) {
        rawLines = List<dynamic>.from(cached);
      }
    } catch (_) {}
    if (rawLines.isEmpty) {
      try {
        final fromCtrl = (_pdfViewerCtrl as dynamic).getSelectedTextLines();
        if (fromCtrl is List && fromCtrl.isNotEmpty) {
          rawLines = List<dynamic>.from(fromCtrl);
        }
      } catch (_) {}
    }
    if (rawLines.isEmpty) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(context.read<MindMapProvider>().t('pdf.noBounds')),
            duration: Duration(seconds: 3),
          ),
        );
      }
      return;
    }

    // 適用色: マーカーモード ON 時のみ呼ばれる前提だが、 念のためフォールバック
    final markerColor = _activeMarkerColor ?? const Color(0xFFFFEB3B);

    try {
      // ── ビューアにハイライト注釈を即時追加 ──
      final annotation = sf_pdf.HighlightAnnotation(
        textBoundsCollection: rawLines.cast<sf_pdf.PdfTextLine>(),
      );
      // 色を反映 (バージョンによっては color プロパティが存在しないので dynamic で)
      try {
        (annotation as dynamic).color = markerColor;
      } catch (_) {}
      // onAnnotationAdded コールバックでの二重保存を防ぐ
      _suppressAnnotationCallback = true;
      try {
        _pdfViewerCtrl!.addAnnotation(annotation);
      } finally {
        _suppressAnnotationCallback = false;
      }

      // ── 保存用に各行の bounds / text / page を抽出 ──
      // PdfTextLine は (bounds, text, pageNumber) フィールドを持つので
      // dynamic 越しに取り出して PdfHighlightLine に変換。
      final savedLines = <PdfHighlightLine>[];
      for (final dyn in rawLines) {
        try {
          final dynamic line = dyn;
          final Rect bounds = line.bounds as Rect;
          final String txt = line.text as String;
          final int page = line.pageNumber as int;
          savedLines.add(PdfHighlightLine(
            pageNumber: page,
            left: bounds.left,
            top: bounds.top,
            right: bounds.right,
            bottom: bounds.bottom,
            text: txt,
          ));
        } catch (_) {
          // 個別の行抽出失敗はスキップ
        }
      }

      final saved = PdfHighlight(
        id: '${DateTime.now().millisecondsSinceEpoch}',
        text: _selectedPdfText ?? '',
        lines: savedLines,
        createdAt: DateTime.now().millisecondsSinceEpoch,
        // ignore: deprecated_member_use
        colorValue: markerColor.value,
      );
      if (mounted) {
        await context
            .read<MindMapProvider>()
            .addPdfHighlight(_nodeId!, saved);
        // 今セッションで追加したことを記録 (閉じる前確認の rollback 用)
        _sessionAddedHighlightIds.add(saved.id);
      }

      // 選択クリア → FAB 消える (マーカーモード自体は維持して連続適用可能に)
      if (mounted) {
        setState(() {
          _selectedPdfText = null;
          _selectedPdfLines = null;
        });
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(context
                .read<MindMapProvider>()
                .t('pdf.highlightFailed')
                .replaceFirst('{err}', '$e')),
            duration: const Duration(seconds: 3),
          ),
        );
      }
    }
  }

  /// 保存済みハイライトを PdfViewerController.addAnnotation で復元する。
  /// `onDocumentLoaded` で呼び出され、 過去セッションで追加されたマーカーを
  /// 画面に再表示する。 各ハイライトの保存色も反映する。
  /// 個々の annotation 作成失敗はスキップする (壊れたデータがあっても他は復元)。
  /// onAnnotationAdded コールバックが回って二重保存にならないよう、
  /// suppress フラグを立ててから addAnnotation を呼ぶ。
  void _restoreSavedHighlights() {
    if (_pdfViewerCtrl == null || _nodeId == null) return;
    _suppressAnnotationCallback = true;
    try {
      final saved =
          context.read<MindMapProvider>().getPdfHighlights(_nodeId!);
      for (final h in saved) {
        try {
          final lines = h.lines
              .map((l) => sf_pdf.PdfTextLine(
                    Rect.fromLTRB(l.left, l.top, l.right, l.bottom),
                    l.text,
                    l.pageNumber,
                  ))
              .toList();
          if (lines.isEmpty) continue;
          final ann = sf_pdf.HighlightAnnotation(textBoundsCollection: lines);
          // 保存時の色を反映 (color プロパティが無いバージョンは黄色のまま)
          try {
            (ann as dynamic).color = Color(h.colorValue);
          } catch (_) {}
          _pdfViewerCtrl!.addAnnotation(ann);
        } catch (_) {
          // 個々の annotation 作成失敗はスキップしてループ続行
        }
      }
    } catch (_) {
    } finally {
      _suppressAnnotationCallback = false;
    }
  }

  /// syncfusion の onAnnotationAdded コールバック実体。
  /// テキスト選択メニュー (Copy / Highlight / Underline / ...) の「Highlight」 を
  /// ユーザーがタップした時、 syncfusion が `HighlightAnnotation` を addAnnotation
  /// で追加する。 そのタイミングをここで掴む。
  ///
  /// 動作:
  ///   1. 自前の addAnnotation 経由 (= suppress フラグ立ってる) なら何もしない
  ///   2. HighlightAnnotation 以外 (Underline 等) も無視
  ///   3. マーカーモード ON ならその色を annotation に反映
  ///   4. annotation の textBoundsCollection から行情報を抜き出し PdfHighlight に変換
  ///   5. provider に保存 + session set に追加 (PDF を閉じる時の rollback 対象)
  void _handleAnnotationAdded(sf_pdf.Annotation annotation) {
    if (_suppressAnnotationCallback) return;
    if (_nodeId == null) return;
    if (annotation is! sf_pdf.HighlightAnnotation) return;

    // 色: マーカーモードが ON ならその色、 OFF なら syncfusion デフォルトの黄色を採用。
    final markerColor = _activeMarkerColor ?? const Color(0xFFFFEB3B);
    if (_activeMarkerColor != null) {
      try {
        (annotation as dynamic).color = markerColor;
      } catch (_) {}
    }

    // textBoundsCollection から各行を取り出して PdfHighlightLine に変換
    try {
      final dynamic ann = annotation;
      final dynamic rawLines = ann.textBoundsCollection;
      if (rawLines is! List) return;

      final savedLines = <PdfHighlightLine>[];
      final textBuffer = StringBuffer();
      for (final dyn in rawLines) {
        try {
          final dynamic line = dyn;
          final Rect bounds = line.bounds as Rect;
          final String txt = (line.text as String?) ?? '';
          final int page = line.pageNumber as int;
          savedLines.add(PdfHighlightLine(
            pageNumber: page,
            left: bounds.left,
            top: bounds.top,
            right: bounds.right,
            bottom: bounds.bottom,
            text: txt,
          ));
          if (textBuffer.isNotEmpty) textBuffer.write(' ');
          textBuffer.write(txt);
        } catch (_) {
          // 個別行の取り出し失敗はスキップ
        }
      }
      if (savedLines.isEmpty) return;

      final saved = PdfHighlight(
        id: '${DateTime.now().millisecondsSinceEpoch}',
        text: textBuffer.toString(),
        lines: savedLines,
        createdAt: DateTime.now().millisecondsSinceEpoch,
        // ignore: deprecated_member_use
        colorValue: markerColor.value,
      );
      // mounted ガードはコールバック内で確認
      if (mounted) {
        context.read<MindMapProvider>().addPdfHighlight(_nodeId!, saved);
        _sessionAddedHighlightIds.add(saved.id);
      }
    } catch (_) {}
  }

  /// このノードに保存されている全ハイライトをクリア。
  /// マーカーボタンの「全マーカー削除」 から呼ばれる。
  Future<void> _clearAllHighlights() async {
    if (_nodeId == null) return;
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        title: Text(context.read<MindMapProvider>().t('pdf.deleteAllMarkers')),
        content:
            Text(context.read<MindMapProvider>().t('pdf.deleteAllMarkersBody')),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dctx).pop(false),
            child: Text(context.read<MindMapProvider>().t('btn.cancel')),
          ),
          FilledButton(
            style: FilledButton.styleFrom(
              backgroundColor: Colors.redAccent,
              foregroundColor: Colors.white,
            ),
            onPressed: () => Navigator.of(dctx).pop(true),
            child: Text(context.read<MindMapProvider>().t('btn.delete')),
          ),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    await context.read<MindMapProvider>().clearPdfHighlights(_nodeId!);
    // syncfusion 側からも annotation を全削除
    try {
      final ctrl = _pdfViewerCtrl;
      if (ctrl != null) {
        // getAnnotations のコピーを取って削除 (イテレート中の collection 変更回避)
        final list = List.from(ctrl.getAnnotations());
        for (final a in list) {
          try {
            ctrl.removeAnnotation(a);
          } catch (_) {}
        }
      }
    } catch (_) {}
  }

  /// マーカーメニューの 1 行を作るヘルパー (色プレビュー + ラベル)。
  PopupMenuItem<String> _markerMenuItem(String key, String label, Color color) {
    final isActive = _activeMarkerColor?.value == color.value;
    return PopupMenuItem<String>(
      value: key,
      child: Row(
        children: [
          Container(
            width: 18,
            height: 18,
            decoration: BoxDecoration(
              color: color,
              borderRadius: BorderRadius.circular(3),
              border: Border.all(
                color: isActive ? Colors.black87 : Colors.black26,
                width: isActive ? 2 : 1,
              ),
            ),
          ),
          const SizedBox(width: 10),
          Text(label),
          if (isActive) ...[
            const Spacer(),
            const Icon(Icons.check, size: 16, color: Colors.black54),
          ],
        ],
      ),
    );
  }

  /// マーカーメニュー選択時のハンドラ。 色キー選択でマーカーモード ON、
  /// 'off' で OFF、 'clear' で全マーカー削除。
  /// 色を切り替えるたびに自動適用タイマと重複ガードをリセットする
  /// (= 同じ箇所を別の色で塗り直したいケースに対応)。
  void _onMarkerMenuSelected(String key) {
    _highlightAutoTimer?.cancel();
    _lastAutoAppliedText = null;
    switch (key) {
      case 'yellow':
        setState(() => _activeMarkerColor = const Color(0xFFFFEB3B));
        break;
      case 'green':
        setState(() => _activeMarkerColor = const Color(0xFFA5D6A7));
        break;
      case 'pink':
        setState(() => _activeMarkerColor = const Color(0xFFF48FB1));
        break;
      case 'blue':
        setState(() => _activeMarkerColor = const Color(0xFF90CAF9));
        break;
      case 'off':
        setState(() => _activeMarkerColor = null);
        break;
      case 'clear':
        _clearAllHighlights();
        break;
    }
  }

  /// PDF を閉じる前に、 今セッションで追加したマーカーをどう扱うか確認するダイアログ。
  /// 戻り値:
  ///   true  = 閉じて OK (保存された状態のままか、 破棄処理は完了済み)
  ///   false = 閉じずに作業継続 (キャンセル)
  /// セッションで何も追加していない場合は確認スキップして即 true を返す。
  Future<bool> _confirmCloseIfNeeded() async {
    if (_sessionAddedHighlightIds.isEmpty || _nodeId == null) {
      return true;
    }
    final n = _sessionAddedHighlightIds.length;
    final action = await showDialog<String>(
      context: context,
      barrierDismissible: false,
      builder: (dctx) => AlertDialog(
        title: Text(context.read<MindMapProvider>().t('pdf.saveMarkersTitle')),
        content: Text(
          context
              .read<MindMapProvider>()
              .t('pdf.saveMarkersBody')
              .replaceFirst('{n}', '$n'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dctx).pop('cancel'),
            child: Text(context.read<MindMapProvider>().t('btn.cancel')),
          ),
          TextButton(
            style: TextButton.styleFrom(foregroundColor: Colors.redAccent),
            onPressed: () => Navigator.of(dctx).pop('discard'),
            child: Text(context.read<MindMapProvider>().t('pdf.discardClose')),
          ),
          FilledButton(
            onPressed: () => Navigator.of(dctx).pop('save'),
            child: Text(context.read<MindMapProvider>().t('pdf.saveClose')),
          ),
        ],
      ),
    );
    if (action == 'save') {
      _sessionAddedHighlightIds.clear(); // 状態を綺麗に
      return true;
    } else if (action == 'discard') {
      // 今セッションで追加した分だけ provider から削除 (auto-save 済みを rollback)
      try {
        final provider = context.read<MindMapProvider>();
        for (final id in _sessionAddedHighlightIds) {
          await provider.removePdfHighlight(_nodeId!, id);
        }
      } catch (_) {}
      _sessionAddedHighlightIds.clear();
      return true;
    }
    // 'cancel' or null (barrier 等) → 閉じない
    return false;
  }

  /// 検索結果が更新されるたびに呼ばれる listener。
  /// `searchText()` の返す PdfTextSearchResult は ChangeNotifier 互換で、
  /// PDF 全体の走査が進む or ヒットを移動するたびに通知される。
  /// UI のヒット件数表示 (`X / Y`) を更新するために rebuild を要求する。
  void _onSearchUpdated() {
    if (mounted) setState(() {});
  }

  /// URL モード用: JavaScript の `window.find()` 呼び出し文字列を組み立てる。
  /// シングルクォート / バックスラッシュをエスケープして JS に埋め込む。
  /// 引数: searchString, caseSensitive, backwards, wrapAround, wholeWord,
  ///       searchInFrames, showDialog
  String _buildWindowFindScript(String text, {bool backwards = false}) {
    final esc = text.replaceAll(r'\', r'\\').replaceAll("'", r"\'");
    return "window.find('$esc', false, $backwards, true, false, false, false)";
  }

  /// テキスト検索を開始 / 更新。 PDF / URL 両モードに対応。
  /// PDF: PDF 全体を走査するため、 大きい PDF では数百 ms 〜数秒かかる。
  ///      結果は listener で逐次反映。
  /// URL: WebView の find API を呼ぶ。
  ///      iaw は onFindResultReceived で件数取得可、 webview_windows は不可。
  Future<void> _startSearch(String text) async {
    _lastSearchQuery = text.trim();
    // ── メモ本文も検索対象にする (= ユーザー要望: PDF内検索でメモの内容にも
    //    反応) ──
    _computeMemoSearchMatches(_lastSearchQuery);
    if (widget.isPdf) {
      // 直前の検索結果はクリア (前回ヒットのハイライトを消す)
      _searchResult?.removeListener(_onSearchUpdated);
      _searchResult?.clear();
      if (_lastSearchQuery.isEmpty || _pdfViewerCtrl == null) {
        setState(() => _searchResult = null);
        return;
      }
      final result = _pdfViewerCtrl!.searchText(_lastSearchQuery);
      result.addListener(_onSearchUpdated);
      setState(() => _searchResult = result);
    } else {
      // URL モード
      setState(() {
        _urlActiveMatch = 0;
        _urlMatchCount = 0;
      });
      if (_lastSearchQuery.isEmpty) return;
      if (_useWebView2 && _winCtrl != null) {
        try {
          await _winCtrl!
              .executeScript(_buildWindowFindScript(_lastSearchQuery));
        } catch (_) {}
      } else if (_iawCtrl != null) {
        try {
          await _iawCtrl!.findAllAsync(find: _lastSearchQuery);
        } catch (_) {}
      }
    }
  }

  /// 検索語にマッチするメモを集める (= ユーザー要望: PDF内検索でメモの内容
  /// にも反応)。大文字小文字を無視して部分一致。
  void _computeMemoSearchMatches(String query) {
    final q = query.trim().toLowerCase();
    if (q.isEmpty) {
      setState(() {
        _memoSearchMatches = [];
        _memoSearchActiveIdx = 0;
      });
      return;
    }
    List<PdfMemo> matches = const [];
    try {
      final node = context.read<MindMapProvider>().nodes[_nodeId];
      final memos = node?.pdfMemos ?? const <PdfMemo>[];
      matches = memos
          .where((m) =>
              m.text.toLowerCase().contains(q) ||
              (m.folder ?? '').toLowerCase().contains(q))
          .toList();
    } catch (_) {}
    setState(() {
      _memoSearchMatches = matches;
      _memoSearchActiveIdx = 0;
    });
  }

  /// マッチしたメモを順にジャンプ表示する (= 検索バーの「メモ N」 ボタン)。
  void _jumpToNextMemoMatch() {
    if (_memoSearchMatches.isEmpty) return;
    // メモパネルが閉じていれば開く (= マッチが見えるように)。
    if (!_memoPanelOpen) {
      _suppressPdfPageChangeBriefly();
      setState(() => _memoPanelOpen = true);
    }
    final memo =
        _memoSearchMatches[_memoSearchActiveIdx % _memoSearchMatches.length];
    _memoSearchActiveIdx =
        (_memoSearchActiveIdx + 1) % _memoSearchMatches.length;
    // 既存のメモジャンプ機構を再利用 (PDF ページ移動 + ハイライト)。
    _jumpToMemo(memo);
    setState(() {});
  }

  void _searchNext() {
    if (widget.isPdf) {
      final r = _searchResult;
      if (r == null || !r.hasResult) return;
      r.nextInstance();
      setState(() {});
    } else {
      if (_lastSearchQuery.isEmpty) return;
      if (_useWebView2 && _winCtrl != null) {
        // window.find は呼ぶたびに次のヒットへ進む (forward=default)
        try {
          _winCtrl!.executeScript(_buildWindowFindScript(_lastSearchQuery));
        } catch (_) {}
      } else if (_iawCtrl != null) {
        try {
          _iawCtrl!.findNext(forward: true);
        } catch (_) {}
      }
    }
  }

  void _searchPrev() {
    if (widget.isPdf) {
      final r = _searchResult;
      if (r == null || !r.hasResult) return;
      r.previousInstance();
      setState(() {});
    } else {
      if (_lastSearchQuery.isEmpty) return;
      if (_useWebView2 && _winCtrl != null) {
        try {
          _winCtrl!.executeScript(
              _buildWindowFindScript(_lastSearchQuery, backwards: true));
        } catch (_) {}
      } else if (_iawCtrl != null) {
        try {
          _iawCtrl!.findNext(forward: false);
        } catch (_) {}
      }
    }
  }

  void _closeSearchBar() {
    // PDF 側
    _searchResult?.removeListener(_onSearchUpdated);
    _searchResult?.clear();
    // URL 側 (両 WebView ともクリア)
    if (_useWebView2 && _winCtrl != null) {
      try {
        // selection を解除して window.find のハイライトを消す
        _winCtrl!.executeScript('window.getSelection().removeAllRanges()');
      } catch (_) {}
    } else if (_iawCtrl != null) {
      try {
        _iawCtrl!.clearMatches();
      } catch (_) {}
    }
    setState(() {
      _searchResult = null;
      _searchBarOpen = false;
      _searchCtrl.clear();
      _lastSearchQuery = '';
      _urlActiveMatch = 0;
      _urlMatchCount = 0;
    });
  }

  /// 検索バーから「Google で検索」 を起動。 検索キーワードを Google 検索 URL
  /// に埋め込み、 別の Dialog (= 新しい _InAppViewerDialog) を上に重ねる。
  /// ✕ で閉じれば元のビューア (PDF / URL) に戻る。
  void _openGoogleSearch() {
    final keyword = _searchCtrl.text.trim();
    if (keyword.isEmpty) return;
    final googleUrl =
        'https://www.google.com/search?q=${Uri.encodeQueryComponent(keyword)}';
    showDialog<void>(
      context: context,
      barrierColor: Colors.black.withValues(alpha: 0.92),
      builder: (dctx) {
        // _showInAppViewer と同じくフルスクリーン Dialog で重ねる
        return Dialog.fullscreen(
          backgroundColor: const Color(0xFF1A1A24),
          child: _InAppViewerDialog(
            url: googleUrl,
            isPdf: false,
            nodeId: _nodeId,
          ),
        );
      },
    );
  }

  /// タイトルバー右側のページ番号ナビ。 [<] [n] / total [>]
  /// 設定メニュー 1 項目 (アイコン + ラベル)。
  PopupMenuItem<String> _pdfMenuItem(
      String value, Object icon, String label, Color color) {
    return PopupMenuItem<String>(
      value: value,
      child: Row(children: [
        icon is IconData
            ? Icon(icon, color: color, size: 18)
            : SizedBox(
                width: 18, height: 18, child: Center(child: icon as Widget)),
        const SizedBox(width: 10),
        Text(label, style: const TextStyle(color: Colors.white, fontSize: 13)),
      ]),
    );
  }

  /// ヘッダーに収まりきらない操作をまとめる「設定」 ポップアップ
  /// (= ユーザー要望: ヘッダーのオーバーフロー対策。 メモ/AI/読む方向だけ
  /// 外に出し、 残りはここに格納する)。
  Widget _buildPdfSettingsMenu(bool hasMemoPanel) {
    return PopupMenuButton<String>(
      tooltip: context.read<MindMapProvider>().t('pdf.settingsOther'),
      icon: const Icon(Icons.tune_rounded, color: Colors.white70, size: 20),
      color: const Color(0xFF252535),
      onSelected: (v) {
        switch (v) {
          case 'toggleReadDir':
            // = ユーザー要望: 読む方向 (横↔縦) を切り替え。
            final p = context.read<MindMapProvider>();
            p.setPdfScrollHorizontal(!p.pdfScrollHorizontal);
            break;
          case 'panMode':
            // = ユーザー要望: クリックしながらドラッグで表示領域を移動。
            // ignore: discarded_futures
            _togglePdfPanMode();
            break;
          case 'drawShapes':
            // = ユーザー要望: PDF 上に図形や線を書き込める機能。
            _togglePdfDrawMode();
            break;
          case 'fitPage':
            // = ユーザー要望: ページ全体がビューアに収まる表示。
            _toggleFitPage();
            break;
          case 'spreadPages':
            // 見開きモードを画面内に収めて表示。
            _toggleSpreadPages();
            break;
          case 'spreadPages':
            // = ユーザー要望: 見開きモードを画面を引いた状態で全体表示。
            _toggleSpreadPages();
            break;
          case 'search':
            setState(() {
              _searchBarOpen = !_searchBarOpen;
              if (!_searchBarOpen) _closeSearchBar();
            });
            break;
          case 'placeMemo':
            setState(() => _placingMemo = !_placingMemo);
            break;
          case 'deepl':
            _openDeepLPanel();
            break;
          case 'sendPdfToAi':
            // PDF 本文を AI チャット入力欄へ直接挿入する (= ユーザー報告: AI に
            //   PDF の内容が渡っていない → クリップボード任せをやめ自動投入)。
            _sendPdfContentToAi();
            break;
          case 'readAloud':
            // PDF 本文を音声で読み上げる (= ユーザー要望)。
            _startReadAloud();
            break;
          case 'switchPdf':
            _switchPdfFile();
            break;
          case 'reload':
            _reload();
            break;
          case 'openExternal':
            _openExternally();
            break;
          case 'download':
            _downloadCurrentFile();
            break;
          case 'quiz':
            final pdfPath = _pdfFilePath ?? widget.url;
            widget.onGenerateQuiz?.call(pdfPath);
            break;
          case 'splitLeft':
            final u = widget.isPdf && _pdfFilePath != null
                ? _pdfFilePath!
                : widget.url;
            widget.onMoveToSplitPanel?.call(u, isLeftPanel: true);
            Navigator.of(context).pop();
            break;
          case 'splitRight':
            final u = widget.isPdf && _pdfFilePath != null
                ? _pdfFilePath!
                : widget.url;
            widget.onMoveToSplitPanel?.call(u, isLeftPanel: false);
            Navigator.of(context).pop();
            break;
          case 'prevPage':
            if (_spreadPageMode || _spreadFitPageMode) {
              _jumpSpreadPages(-2);
              break;
            }
            try {
              _pdfViewerCtrl?.previousPage();
            } catch (_) {}
            break;
          case 'nextPage':
            if (_spreadPageMode || _spreadFitPageMode) {
              _jumpSpreadPages(2);
              break;
            }
            try {
              _pdfViewerCtrl?.nextPage();
            } catch (_) {}
            break;
          case 'jumpPage':
            _showJumpToPageDialog();
            break;
        }
      },
      itemBuilder: (_) => [
        // ── 読む方向 (横↔縦) 切替 (= ユーザー要望: 設定の一番上に配置) ──
        // ── 読む方向 (横↔縦) 切替: 現在の向きが分かるラベルにする (= ユーザー
        //   要望: 今どっちの向きで読める状態か分からない) ──
        if (widget.isPdf)
          _pdfMenuItem(
              'toggleReadDir',
              context.read<MindMapProvider>().pdfScrollHorizontal
                  ? Icons.swap_horiz_rounded
                  : Icons.swap_vert_rounded,
              context.read<MindMapProvider>().pdfScrollHorizontal
                  ? '現在：横めくり（タップで縦めくりに）'
                  : '現在：縦めくり（タップで横めくりに）',
              const Color(0xFF4FC3F7)),
        // ── ドラッグで表示領域を移動 / 文字選択 の切替 (= ユーザー要望) ──
        if (widget.isPdf)
          _pdfMenuItem(
              'panMode',
              _pdfPanMode ? Icons.pan_tool_rounded : Icons.text_fields_rounded,
              _pdfPanMode ? '現在：ドラッグで移動（タップで文字選択に）'
                  : '現在：文字選択（タップでドラッグ移動に）',
              const Color(0xFFB39DDB)),
        // ── 「図形・線を描き込む」 は設定から外した (= ユーザー要望:
        //    設定項目が多過ぎる。 同じボタンがヘッダーに常設されている)。 ──
        if (widget.isPdf)
          _pdfMenuItem(
              'fitPage',
              _fitPageMode
                  ? Icons.fit_screen_rounded
                  : Icons.fit_screen_outlined,
              _fitPageMode ? '通常表示に戻す' : '1ページ全体を表示',
              const Color(0xFF80CBC4)),
        if (widget.isPdf)
          _pdfMenuItem(
              'spreadPages',
              _spreadFitPageMode
                  ? Icons.view_week_rounded
                  : Icons.view_week_outlined,
              _spreadFitPageMode ? '見開きモードを解除' : '見開きモード',
              const Color(0xFFFFB74D)),
        // ── ページ移動 (= ユーザー要望: 設定の中に入れる) ──
        if (widget.isPdf && _pdfTotalPages > 0) ...[
          _pdfMenuItem(
              'jumpPage', Icons.numbers, 'ページ番号を指定', const Color(0xFF4FC3F7)),
        ],
        // PDF内検索は廃止 (= ユーザー要望)。
        if (hasMemoPanel)
          _pdfMenuItem(
              'placeMemo',
              _placingMemo ? Icons.cancel : Icons.add_location_alt,
              _placingMemo ? 'メモ配置モードを解除 (M)' : 'ここにメモを置く (M)',
              const Color(0xFFFFC107)),
        _pdfMenuItem('deepl', Icons.translate_rounded, 'DeepL で翻訳 (側パネル)',
            const Color(0xFF4FC3F7)),
        // ── PDF の内容を AI チャットに渡す (= ユーザー要望) ──
        if (widget.isPdf && _pdfFilePath != null)
          _pdfMenuItem('sendPdfToAi', Icons.smart_toy_rounded, 'PDFの内容をAIチャットへ',
              const Color(0xFFBA68C8)),
        // ── PDF を音声で読み上げ (= ユーザー要望) ──
        if (widget.isPdf && _pdfFilePath != null)
          _pdfMenuItem('readAloud', Icons.record_voice_over_rounded,
              '音声で読み上げ（現在のページから）', const Color(0xFF4FC3F7)),
        if (!widget.isPdf)
          _pdfMenuItem('reload', Icons.refresh, '再読み込み', Colors.white70),
        _pdfMenuItem(
            'openExternal', Icons.open_in_new, '外部で開く', Colors.white70),
        // 「ダウンロード」 「左/右に分割」 は設定から外してヘッダーに並べた
        // (= ユーザー要望)。
        // ── 別の PDF に切り替え (= ユーザー要望: 項目の一番下に配置) ──
        if (widget.isPdf)
          _pdfMenuItem('switchPdf', Icons.file_open_rounded, '別の PDF に切り替え',
              const Color(0xFF4FC3F7)),
      ],
    );
  }


  /// 描き込みの道具箱をヘッダーの下に出すための受け口
  /// (= ユーザー要望: PDF の上部が道具箱と被って描けないので、 ヘッダーの所へ)。
  /// 描き込みモードの間だけ中身が入る。
  final ValueNotifier<Widget?> _pdfDrawToolbar = ValueNotifier<Widget?>(null);

  /// ヘッダーの下に出す道具箱の帯 (モードの間だけ出る)。
  Widget _buildPdfDrawToolbarBar() {
    return ValueListenableBuilder<Widget?>(
      valueListenable: _pdfDrawToolbar,
      builder: (_, w, __) {
        if (w == null) return const SizedBox.shrink();
        return Container(
          width: double.infinity,
          color: const Color(0xFF17172A),
          padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 6),
          // 真ん中に置く (= ユーザー要望)。 幅が足りない時だけ横に流して
          // 全部触れるようにする。
          child: LayoutBuilder(
            builder: (_, cons) => SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              child: ConstrainedBox(
                constraints: BoxConstraints(minWidth: cons.maxWidth),
                child: Center(child: w),
              ),
            ),
          ),
        );
      },
    );
  }

  /// 開いているファイルを画面分割の左 / 右のペインへ移す
  /// (= ユーザー要望: ヘッダーに左右分割ボタンを置く。 右分割を押すと
  ///  2 分割の右半分がこのファイルになる)。
  void _moveToSplitPane({required bool left}) {
    final u =
        widget.isPdf && _pdfFilePath != null ? _pdfFilePath! : widget.url;
    widget.onMoveToSplitPanel?.call(u, isLeftPanel: left);
    Navigator.of(context).pop();
  }

  /// 開いているファイル (PDF 等) をユーザーが選んだ場所に保存する
  /// (= ユーザー要望: 設定からダウンロードできるように)。
  Future<void> _downloadCurrentFile() async {
    final src = _pdfFilePath ?? '';
    final messenger = ScaffoldMessenger.maybeOf(context);
    void snack(String m, Color c) {
      messenger?.showSnackBar(SnackBar(
          content: Text(m),
          backgroundColor: c,
          duration: const Duration(seconds: 2)));
    }

    if (src.isEmpty || !await File(src).exists()) {
      snack('保存できるファイルがありません', const Color(0xFF2A2A3E));
      return;
    }
    var name = src.split(RegExp(r'[\\/]')).last;
    if (!name.toLowerCase().endsWith('.pdf')) name = '$name.pdf';
    try {
      final bytes = await File(src).readAsBytes();
      final outPath = await FilePicker.platform.saveFile(
        dialogTitle: context.read<MindMapProvider>().t('save.pdf'),
        fileName: name,
        bytes: bytes,
      );
      if (outPath == null) return; // キャンセル
      // デスクトップでは saveFile が bytes を書き込まない場合があるので保険。
      try {
        final out = File(outPath);
        if (!await out.exists() || (await out.length()) == 0) {
          await out.writeAsBytes(bytes);
        }
      } catch (_) {}
      snack('保存しました', const Color(0xFF43B97F));
    } catch (_) {
      snack('保存に失敗しました', const Color(0xFFE53935));
    }
  }

  /// 「ページにジャンプ」 ダイアログ (= 設定メニューから呼ぶ)。
  Future<void> _showJumpToPageDialog() async {
    final ctrl = TextEditingController(text: '$_currentPage');
    await showDialog<void>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E2E),
        title: Text(context.read<MindMapProvider>().t('pdf.jumpToPage'),
            style: const TextStyle(color: Colors.white)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          keyboardType: TextInputType.number,
          style: const TextStyle(color: Colors.white),
          decoration: InputDecoration(
            labelText: context
                .read<MindMapProvider>()
                .t('pdf.pageRangeHint')
                .replaceFirst('{max}', '$_pdfTotalPages'),
            labelStyle: const TextStyle(color: Colors.white70),
            enabledBorder: const UnderlineInputBorder(
              borderSide: BorderSide(color: Colors.white24),
            ),
          ),
          onSubmitted: (v) {
            final n = int.tryParse(v.trim());
            if (n != null && n >= 1 && n <= _pdfTotalPages) {
              Navigator.of(dctx).pop();
              _jumpToPage(n);
            }
          },
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dctx).pop(),
            child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                style: const TextStyle(color: Colors.white60)),
          ),
          ElevatedButton(
            onPressed: () {
              final n = int.tryParse(ctrl.text.trim());
              if (n != null && n >= 1 && n <= _pdfTotalPages) {
                Navigator.of(dctx).pop();
                _jumpToPage(n);
              }
            },
            child: Text(context.read<MindMapProvider>().t('pdf.jump')),
          ),
        ],
      ),
    );
  }

  /// 開いている PDF を、 同じマップ/ギャラリーに置いてある別の PDF に切り替える
  /// (= ユーザー要望: ファイル選択ではなく、 そのページの PDF から選ぶ)。
  Future<void> _switchPdfFile() async {
    final provider = context.read<MindMapProvider>();
    final pdfNodes = provider.currentPage.nodes.values.where((n) {
      final p = (n.attachmentPath ?? '').toLowerCase();
      return p.endsWith('.pdf');
    }).toList();
    if (pdfNodes.isEmpty) {
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(SnackBar(
        content: Text(context.read<MindMapProvider>().t('pdf.noPdfOnPage')),
        duration: Duration(seconds: 2),
      ));
      return;
    }
    String nameOf(MindMapNode n) {
      if (n.title.trim().isNotEmpty) return n.title.trim();
      final base = (n.attachmentPath ?? '').split(RegExp(r'[\\/]')).last;
      return base.isNotEmpty ? base : 'PDF';
    }

    final chosen = await showDialog<String>(
      context: context,
      builder: (dctx) => SimpleDialog(
        backgroundColor: const Color(0xFF1E1E2E),
        title: Text(context.read<MindMapProvider>().t('pdf.selectPdf'),
            style: TextStyle(color: Colors.white, fontSize: 16)),
        children: [
          for (final n in pdfNodes)
            SimpleDialogOption(
              onPressed: () => Navigator.pop(dctx, n.attachmentPath),
              child: Row(children: [
                Icon(Icons.picture_as_pdf_rounded,
                    color: n.attachmentPath == _pdfFilePath
                        ? const Color(0xFF43B97F)
                        : const Color(0xFFFF6B6B),
                    size: 20),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(nameOf(n),
                      style: const TextStyle(color: Colors.white, fontSize: 13),
                      overflow: TextOverflow.ellipsis),
                ),
                if (n.attachmentPath == _pdfFilePath)
                  Padding(
                    padding: const EdgeInsets.only(left: 8),
                    child: Text(
                        context.read<MindMapProvider>().t('pdf.showing'),
                        style:
                            TextStyle(color: Color(0xFF43B97F), fontSize: 11)),
                  ),
              ]),
            ),
        ],
      ),
    );
    if (chosen == null || chosen.isEmpty || !mounted) return;
    if (chosen == _pdfFilePath) return;
    setState(() {
      _pdfFilePath = chosen;
      _currentPage = 1;
      _pdfTotalPages = 0;
      _fitPageImage = null;
      _fitPageRenderedFor = -1;
      _fitPageBytes = null;
      _spreadPageImages.clear();
      _spreadPageImageSizes.clear();
      _spreadRenderedForStart = -1;
      _spreadRenderGeneration++;
      _spreadRenderPending = false;
      // 新しいファイル用にコントローラを作り直して確実に再ロードする。
      _pdfViewerCtrl = sf_pdf.PdfViewerController();
    });
  }

