              const Icon(Icons.chevron_right, color: Colors.white70, size: 20),
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
          onPressed: _currentPage < _pdfTotalPages
              ? () {
                  try {
                    _pdfViewerCtrl?.nextPage();
                  } catch (_) {}
                }
              : null,
        ),
        // ── 縦めくり / 横めくり 切替 (= ユーザー要望) ──
        IconButton(
          tooltip: context.watch<MindMapProvider>().pdfScrollHorizontal
              ? '横めくり中 → 縦めくりに切替'
              : '縦めくり中 → 横めくりに切替',
          icon: Icon(
              context.watch<MindMapProvider>().pdfScrollHorizontal
                  ? Icons.swap_horiz_rounded
                  : Icons.swap_vert_rounded,
              color: const Color(0xFF4FC3F7),
              size: 20),
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
          onPressed: () {
            final p = context.read<MindMapProvider>();
            final page = _currentPage;
            p.setPdfScrollHorizontal(!p.pdfScrollHorizontal);
            // 方向変更で再レイアウトされても現在ページを保つ。
            Future.delayed(const Duration(milliseconds: 350), () {
              if (!mounted) return;
              try {
                _pdfViewerCtrl?.jumpToPage(page);
              } catch (_) {}
            });
          },
        ),
      ],
