  /// タイトルバー直下に出る検索バー (PDF / URL 内テキスト検索)。
  Widget _buildSearchBar() {
    // 件数表示の値: PDF と URL でソースが違う
    String counterText = '';
    bool canNavigate = false;
    if (widget.isPdf) {
      final r = _searchResult;
      if (r != null && r.hasResult) {
        counterText = '${r.currentInstanceIndex} / ${r.totalInstanceCount}';
        canNavigate = true;
      } else if (r != null) {
        counterText = '0 件';
      }
    } else {
      // URL モード
      if (_lastSearchQuery.isNotEmpty) {
        if (_urlMatchCount > 0) {
          counterText = '$_urlActiveMatch / $_urlMatchCount';
          canNavigate = true;
        } else if (_useWebView2) {
          // WebView2 では件数取得 API がないため、 検索後は件数表示なし。
          // 「次/前へ」 だけ機能する (window.find のラッパ)。
          counterText = '';
          canNavigate = true;
        } else {
          counterText = '0 件';
        }
      }
    }
    return Container(
      height: 40,
      color: const Color(0xFF1B1B26),
      padding: const EdgeInsets.symmetric(horizontal: 10),
      child: Row(
        children: [
          const Icon(Icons.search, color: Colors.white60, size: 18),
          const SizedBox(width: 8),
          Expanded(
            child: TextField(
              controller: _searchCtrl,
              autofocus: true,
              style: const TextStyle(color: Colors.white, fontSize: 13),
              decoration: InputDecoration(
                isDense: true,
                contentPadding: const EdgeInsets.symmetric(vertical: 8),
                hintText: widget.isPdf ? 'PDF 内を検索...' : 'ページ内を検索...',
                hintStyle: const TextStyle(color: Colors.white38, fontSize: 13),
                border: InputBorder.none,
              ),
              onSubmitted: (v) => _startSearch(v),
            ),
          ),
          if (counterText.isNotEmpty)
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 6),
              child: Text(
                counterText,
                style: const TextStyle(color: Colors.white60, fontSize: 12),
              ),
            ),
          // ── メモ本文ヒット (= ユーザー要望: PDF内検索でメモにも反応) ──
          if (_memoSearchMatches.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(left: 2, right: 4),
              child: InkWell(
                onTap: _jumpToNextMemoMatch,
                borderRadius: BorderRadius.circular(10),
                child: Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                  decoration: BoxDecoration(
                    color: const Color(0xFFFFC107).withValues(alpha: 0.18),
                    borderRadius: BorderRadius.circular(10),
                    border:
                        Border.all(color: const Color(0xFFFFC107), width: 1),
                  ),
                  child: Row(mainAxisSize: MainAxisSize.min, children: [
                    const Icon(Icons.sticky_note_2_rounded,
                        color: Color(0xFFFFC107), size: 14),
                    const SizedBox(width: 4),
                    Text(
                        context
                            .read<MindMapProvider>()
                            .t('pmemo.count')
                            .replaceFirst(
                                '{n}', '${_memoSearchMatches.length}'),
                        style: const TextStyle(
                            color: Color(0xFFFFC107), fontSize: 12)),
                  ]),
                ),
              ),
            ),
          IconButton(
            tooltip: context.read<MindMapProvider>().t('search.prevHit'),
            icon: const Icon(Icons.keyboard_arrow_up,
                color: Colors.white70, size: 20),
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 30, minHeight: 30),
