  Future<void> _jumpToPage(int page) async {
    setState(() => _currentPage = page);
    if (_fitPageMode) _scheduleFitPageRender();
    if (_spreadFitPageMode) _scheduleSpreadPageRender();
    if (widget.isPdf) {
      // SfPdfViewer: 同期 API で即時ジャンプ。 内部でスムーズスクロール。
      try {
        _pdfViewerCtrl?.jumpToPage(page);
      } catch (_) {}
    } else {
      final base = widget.url.split('#').first;
      final newUrl = '$base#page=$page';
      if (_useWebView2 && _winCtrl != null) {
        await _winCtrl!.loadUrl(newUrl);
      } else if (_iawCtrl != null) {
        await _iawCtrl!
            .loadUrl(urlRequest: iaw.URLRequest(url: iaw.WebUri(newUrl)));
      }
    }
  }

  Future<void> _loadUrl(String url) async {
    setState(() => _currentUrl = url);
    if (_useWebView2 && _winCtrl != null) {
      await _winCtrl!.loadUrl(url);
    } else if (_iawCtrl != null) {
      await _iawCtrl!.loadUrl(urlRequest: iaw.URLRequest(url: iaw.WebUri(url)));
    }
  }

  /// メモへジャンプ: ページ / URL / scrollY を合わせ → ハイライトパルスを
  /// 3 秒走らせる。 URL メモで scrollY がある場合は WebView 読み込み完了後に
  /// `window.scrollTo(0, scrollY)` で復元する。
  Future<void> _jumpToMemo(PdfMemo memo) async {
    if (memo.pageNumber != null && widget.isPdf) {
      await _jumpToPage(memo.pageNumber!);
    } else if (memo.url != null) {
      // URL メモ: 必要なら別 URL に遷移してからスクロール復元
      if (memo.url != _currentUrl) {
        await _loadUrl(memo.url!);
        // ページ初回ロードに少し時間がかかるため待機。 onLoadStop 経由の
        // 厳密復元もできるが、 シンプルにディレイで対応する。
        await Future.delayed(const Duration(milliseconds: 800));
      }
      if (memo.scrollY != null) {
        await _restoreScrollY(memo.scrollY!);
      }
    }
    if (!mounted) return;
    setState(() => _highlightMemoId = memo.id);
    _pulseCtrl.forward(from: 0.0);
    Future.delayed(const Duration(milliseconds: 3000), () {
      if (!mounted) return;
      if (_highlightMemoId == memo.id) {
        setState(() => _highlightMemoId = null);
      }
    });
  }

  Future<void> _reload() async {
    if (_useWebView2 && _winCtrl != null) {
      await _winCtrl!.reload();
    } else if (_iawCtrl != null) {
      await _iawCtrl!.reload();
    }
  }

  Future<void> _openExternally() async {
    // PDF モード: file:// URL は launchUrl では開けない環境が多いので
    // OpenFilex (= OS のデフォルト PDF アプリ) で開く。
    if (widget.isPdf) {
      final path = _resolveLocalPdfPath();
      if (path != null) {
        try {
          await OpenFilex.open(path);
        } catch (_) {}
      }
      return;
    }
    final uri = Uri.tryParse(_currentUrl);
    if (uri == null) return;
    try {
      await launchUrl(uri, mode: LaunchMode.externalApplication);
    } catch (_) {}
  }

  /// 現在ハイライト中のメモを取得 (なければ null)。 マーカー描画は
  /// このメモに対してだけ行う (= 全メモを常時オーバーレイしない)。
  /// 位置情報 (xRatio/yRatio) を持たないメモはマーカー描画対象外。
  PdfMemo? _findActiveMemo(MindMapProvider provider) {
    final id = _nodeId;
    final highlight = _highlightMemoId;
    if (id == null || highlight == null) return null;
    final node = provider.nodes[id];
    if (node?.pdfMemos == null) return null;
    for (final m in node!.pdfMemos!) {
      if (m.id == highlight && m.xRatio != null && m.yRatio != null) {
        return m;
      }
    }
    return null;
  }

  /// メモ配置モードでタップされた時の処理。
  /// タップ位置を WebView 領域内の比率に変換 → 編集ダイアログを開いて
  /// テキスト入力させ、 確定したら addPdfMemo。
  Future<void> _onPlaceTap(TapDownDetails details, Size area) async {
    final id = await _ensureNode();
    if (id == null || !mounted) return;
    final xRatio = (details.localPosition.dx / area.width).clamp(0.0, 1.0);
    final yRatio = (details.localPosition.dy / area.height).clamp(0.0, 1.0);
    // ── ページ番号 / URL / scrollY のスナップショット ──
    // PDF: syncfusion の `_currentPage` (= onPageChanged で逐次更新) が
    //      WebView と違って正しく現在ページを保持している。
    // URL: 配置タップした瞬間の scrollY を取得して保存。 メモジャンプ時に
    //      `window.scrollTo` で復元できる。
    final int? snapshotPage = widget.isPdf ? _currentPage : null;
    final String? snapshotUrl = widget.isPdf ? null : _currentUrl;
    final double? snapshotScrollY =
        widget.isPdf ? null : await _getCurrentScrollY();

    final created = await showDialog<PdfMemo?>(
      context: context,
      builder: (_) => _PdfMemoEditDialog(
        initialPage: snapshotPage,
        initialUrl: snapshotUrl,
        // 配置モード: ページは確定済みなのでダイアログ側で入力 UI 不要
        placedMode: true,
      ),
    );
    if (created != null && mounted) {
      final provider = context.read<MindMapProvider>();
      final added = provider.addPdfMemo(
        id,
        text: created.text,
        pageNumber: snapshotPage,
        url: snapshotUrl,
        scrollY: snapshotScrollY,
        xRatio: xRatio,
        yRatio: yRatio,
        colorValue: created.colorValue,
      );
      // 追加直後にハイライトを点ける
      setState(() {
        _highlightMemoId = added.id;
      });
      _pulseCtrl.forward(from: 0.0);
      Future.delayed(const Duration(milliseconds: 3000), () {
        if (mounted && _highlightMemoId == added.id) {
          setState(() => _highlightMemoId = null);
        }
      });
    }
    if (mounted) setState(() => _placingMemo = false);
  }

  /// 右クリック位置 (PDF エリアのローカル座標) にメモを追加する
  /// (= ユーザー要望: PDF 上を右クリックでメモ追加)。 _onPlaceTap と同じ
  /// 流れだが、 タップではなく右クリック位置から xRatio/yRatio を算出する。
  Future<void> _addMemoAtPdfLocal(Offset? localPos) async {
    final id = _nodeId;
    if (id == null) return;
    double xRatio = 0.5, yRatio = 0.5;
    final box = _pdfAreaKey.currentContext?.findRenderObject() as RenderBox?;
    if (localPos != null && box != null && box.hasSize) {
      final sz = box.size;
      if (sz.width > 0 && sz.height > 0) {
        xRatio = (localPos.dx / sz.width).clamp(0.0, 1.0);
        yRatio = (localPos.dy / sz.height).clamp(0.0, 1.0);
      }
    }
    final int? snapshotPage = widget.isPdf ? _currentPage : null;
    final String? snapshotUrl = widget.isPdf ? null : _currentUrl;
    final double? snapshotScrollY =
        widget.isPdf ? null : await _getCurrentScrollY();
    final created = await showDialog<PdfMemo?>(
      context: context,
      builder: (_) => _PdfMemoEditDialog(
        initialPage: snapshotPage,
        initialUrl: snapshotUrl,
        placedMode: true,
      ),
    );
    if (created != null && mounted) {
      final provider = context.read<MindMapProvider>();
      final added = provider.addPdfMemo(
        id,
        text: created.text,
        pageNumber: snapshotPage,
        url: snapshotUrl,
        scrollY: snapshotScrollY,
        xRatio: xRatio,
        yRatio: yRatio,
        colorValue: created.colorValue,
      );
      setState(() => _highlightMemoId = added.id);
      _pulseCtrl.forward(from: 0.0);
      Future.delayed(const Duration(milliseconds: 3000), () {
        if (mounted && _highlightMemoId == added.id) {
          setState(() => _highlightMemoId = null);
        }
      });
    }
  }

  /// PDF / URL のメインビューア (オーバーレイ抜きの中身)。
  /// - PDF: SfPdfViewer (Syncfusion ネイティブ描画 + 縦スクロール + ピンチズーム)
  /// - URL: webview_windows / flutter_inappwebview
  Widget _buildPureWebView() {
    if (widget.isPdf) {
      if (_pdfError != null) {
        return Center(
          child: Padding(
            padding: const EdgeInsets.all(16),
            child: Text(
              'PDF を開けませんでした:\n$_pdfError',
              style: const TextStyle(color: Colors.white70, fontSize: 13),
              textAlign: TextAlign.center,
            ),
          ),
        );
      }
      if (_pdfFilePath == null || _pdfViewerCtrl == null) {
        return const Center(
          child: CircularProgressIndicator(strokeWidth: 2),
        );
      }
      // PDF めくり方向 (= ユーザー要望: 縦めくり/横めくりを選択できるように)。
      final pdfHoriz = context.watch<MindMapProvider>().pdfScrollHorizontal;
      return Focus(
        focusNode: _pdfFocusNode,
        autofocus: true,
        onKeyEvent: _onPdfKeyEvent,
        child: Listener(
          // ── ホイールは SfPdfViewer のネイティブスクロールに任せる ──
          // ユーザー要望: 入力に対するスクロール量の独自処理 (1/N ページずつ)
          // をやめ、 標準の滑らかなスクロールに戻す。
          // SfPdfViewer の上に「ハイライト追加」 ボタンをオーバーレイするため Stack に。
          child: Stack(
            children: [
              // ── continuous モード + 表示幅 65% で「1 ページがほぼ画面に収まる
              //    かつ ↑/↓ で sub-page スクロール可能」 を両立 ──
              // single モードは syncfusion 側のページ管理が独自で、 jumpTo による
              // 細かなスクロールが効かない (= ↑↓ が誤動作する) 。 continuous モードに
              // 戻し、 FractionallySizedBox で表示幅を絞って 1 ページが画面に収まる
              // 視覚を保つ。 Localizations で日本語ロケールを SfPdfViewer 配下に
              // ── widthFactor をプラットフォームで切替 ──
              // デスクトップは 0.65 (1 ページがビューポートにほぼ収まる視覚)、
              // モバイル (Android/iOS) は 1.0 で全幅表示する。
              // ユーザー要望: 「Android 版で左右の黒のスペース要らないから
              //   大きめに表示して欲しい」 への対応。
              // ── 表示幅は常にビューポートいっぱい (widthFactor 1.0) ──
              // 旧実装はデスクトップで 0.65 に絞って中央寄せしていたが、
              //   両脇に暗い背景が残り「サイドの AI / メモとの間に要らない
              //   黒い空間ができる」「拡大すると表示幅が広がってサイドと
              //   重なる」 という指摘につながっていた (= ユーザー要望)。
              //   PDF は Expanded (= 本体 Row のセル) に収まるので、 1.0 でも
              //   サイドパネルの領域には食い込まない。
              // 見開き画像の生成中は SfPdfViewer をツリーから外す。同じ PDF を
              // Syncfusion と Printing が同時に解析・描画することが、切替時の
              // フリーズとメモリ急増の主因だった。解除時は onDocumentLoaded の
              // 既存復元処理で現在ページとハイライトを戻す。
              if (!_spreadFitPageMode)
                LayoutBuilder(
                  builder: (viewerCtx, viewerConstraints) {
                    final hasHiddenPdfPages = _pdfFilePath != null &&
                        context
                            .read<MindMapProvider>()
                            .hiddenPdfPagesFor(_pdfFilePath!)
                            .isNotEmpty;
                    final liveWidthFactor =
                        (_spreadPageMode || _spreadFitPageMode)
                            ? 1.0
                            : _pdfLiveWidthFactor(viewerConstraints);
                    final liveLayoutMode = _fitPageMode
                        ? sf_pdf.PdfPageLayoutMode.single
                        : (_spreadPageMode || _spreadFitPageMode)
                            ? sf_pdf.PdfPageLayoutMode.continuous
                            : (pdfHoriz && hasHiddenPdfPages)
                                ? sf_pdf.PdfPageLayoutMode.single
                                : sf_pdf.PdfPageLayoutMode.continuous;
                    final liveScrollDirection = (_fitPageMode ||
                            _spreadPageMode ||
                            _spreadFitPageMode ||
                            pdfHoriz)
                        ? sf_pdf.PdfScrollDirection.horizontal
                        : sf_pdf.PdfScrollDirection.vertical;
                    return Align(
                      alignment: Alignment.topCenter,
                      child: FractionallySizedBox(
                        widthFactor: liveWidthFactor,
                        heightFactor: 1.0,
                        child: Localizations(
                          locale: const Locale('ja'),
                          delegates: const [
                            GlobalMaterialLocalizations.delegate,
                            GlobalWidgetsLocalizations.delegate,
                            GlobalCupertinoLocalizations.delegate,
                          ],
                          // ── 図形・線 描き込みレイヤー (= ユーザー要望) ──
                          child: PdfDrawLayer(
                            active: _pdfDrawActive &&
                                widget.isPdf &&
                                _pdfFilePath != null,
                            filePath: _pdfFilePath,
                            controller: _pdfViewerCtrl,
                            tr: context.read<MindMapProvider>().t,
                            toolbarSink: _pdfDrawToolbar,
                            onExit: () {
                              if (mounted) {
                                setState(() => _pdfDrawActive = false);
                              }
                            },
                            onSaved: () {
                              if (mounted) {
                                setState(() => _pdfDrawReloadTick++);
                              }
                              // マップのサムネイルも作り直す
                              // (= ユーザー報告: 書いた内容が出ない)。
                              widget.onSavedToFile?.call();
                            },
                            child: Listener(
                            key: _pdfAreaKey,
                            behavior: HitTestBehavior.translucent,
                            // ── 右クリック検出 (全画面 PDF) ──
                            // 右クリックでメニュー (= メモ追加 / ページ非表示 等)。
                            // localPosition を渡してその位置にメモを置けるようにする。
                            onPointerDown: (event) {
                              if (event.kind == PointerDeviceKind.mouse &&
                                  event.buttons == kSecondaryMouseButton) {
                                _showFullscreenPdfContextMenu(event.position,
                                    localPos: event.localPosition);
                              }
                            },
                            // ピンチイン / ピンチアウト + Ctrl+ホイール
                            // (= ユーザー要望)。
                            onPointerPanZoomStart: (_) => _pdfPinchStart(),
                            onPointerPanZoomUpdate: (e) =>
                                _pdfPinchUpdate(e.scale),
                            onPointerSignal: (e) {
                              if (e is PointerScaleEvent) {
                                _pdfPinchStart();
                                _pdfPinchUpdate(e.scale);
                                return;
                              }
                              _pdfWheelZoom(e);
                            },
                            child: sf_pdf.SfPdfViewer.file(
                              _stablePdfFile(_pdfFilePath!),
                              // 描き込み保存後は tick が進んでファイルを
                              // 読み直す (= ユーザー要望: 図形・線の描き込み)。
                              key: ValueKey(
                                  '${_pdfFilePath}_draw$_pdfDrawReloadTick'),
                              controller: _pdfViewerCtrl,
                              // ── ページレイアウト: continuous (Word ライクな縦連続流) ──
                              // ↑/↓ で sub-page スクロール (1/N ページずつ滑らかに移動) を可能にするため。
                              // 1 ページがビューポートに収まる視覚は FractionallySizedBox で表示幅を絞って
                              // 実現する。 ←/→ overshoot は HardwareKeyboard ハンドラと Focus.onKeyEvent
                              // の二重起動が原因だったので、 そちらでガードを入れて解消した。
                              // ── ユーザー要望: PDF ページ非表示が確実にスキップされるよう ──
                              // single モードに変更 (= 連続スクロール無効、 1 ページずつ表示)。
                              // continuous モードだと「ページ移動後にスクロールで戻ると非表示
                              // ページが見える」 バグがあった。 single モードでは jumpToPage 後
                              // は確実にそのページだけが画面に映る。
                              // = ユーザー要望: ページめくりをシームレスに。 single モードは
                              //   1 ページごとに再ラスタライズされて「読み込み」 が入り重いので、
                              //   既定では横/縦とも continuous に統一する。 ただし非表示ページが
                              //   設定されている時だけは strict な single にして確実にスキップする
                              //   (continuous だとスクロールで非表示ページが見えてしまうため)。
                              pageLayoutMode: liveLayoutMode,
                              scrollDirection: liveScrollDirection,
                              // テキスト選択を有効にすると、 ドラッグでテキストを選択できる
                              // (= 選択 + コピーが可能、 syncfusion 側でハイライト等のマーカー
                              //  メニューも出るバージョンがある)。
                              // 副作用としてビューア空白部分のドラッグでパンができなくなるが、
                              // continuous モードでのスクロールはホイール / 矢印キーが主なので OK。
                              enableTextSelection: !_pdfPanMode,
                              // ── ドラッグで表示領域を動かす (= ユーザー要望) ──
                              // pan にすると押しながらのドラッグで紙を掴んで
                              // 動かせる。 selection は文字を選ぶモード。
                              interactionMode: _pdfPanMode
                                  ? sf_pdf.PdfInteractionMode.pan
                                  : sf_pdf.PdfInteractionMode.selection,
                              // ── リンクは自前のダイアログで開く (= ユーザー要望:
                              //    英語のままなので多言語に + 外部アプリ / アプリ内
                              //    タブを選べるように) ──
                              enableHyperlinkNavigation: false,
                              onHyperlinkClicked: (details) {
                                // ignore: discarded_futures
                                _showPdfHyperlinkDialog(details.uri);
                              },
                              // ダブルタップによるズームを切ると、 配置モード時の単タップが
                              // 確実に拾える (ダブルタップ判定の遅延がなくなる)。
                              enableDoubleTapZooming: false,
                              // ズーム上限を 4.0 まで広げる (デフォルト 3.0)。
                              // 注: syncfusion v28 系では minZoomLevel が公開されておらず、
                              //     最小ズームは内部的に 1.0 で固定。 そのため「ページ幅が
                              //     ビューア幅にぴったり」 (= zoom 1.0) より引きで表示する
                              //     ことはこのライブラリでは出来ない。 ご了承ください。
                              maxZoomLevel: 8.0,
                              // ── ズーム変化を追跡 ──
                              // 拡大率に応じて表示幅 (widthFactor) を広げ、 横スクロールを
                              // 減らすため (ユーザー要望)。 Ctrl+/Ctrl- / ピンチ両方で発火。
                              onZoomLevelChanged: (details) {
                                final z = details.newZoomLevel;
                                if (mounted &&
                                    (z - _pdfZoomLevel).abs() > 0.001) {
                                  setState(() => _pdfZoomLevel = z);
                                }
                              },
                              // ── syncfusion 側でアノテーションが追加された時のフック ──
                              // ユーザーがテキスト選択メニューの「Highlight」 を押した時、
                              // syncfusion 内部で HighlightAnnotation が addAnnotation される。
                              // このタイミングを捕まえて、 マーカーモードの色を反映 + 永続化する。
                              // 自前の `_addHighlightForSelection` 経由で追加したものは
                              // `_suppressAnnotationCallback` で除外して二重保存を防ぐ。
                              onAnnotationAdded: (annotation) {
                                _handleAnnotationAdded(annotation);
                              },
                              // ── テキスト選択中の文字列 + 行 bounds を追跡 ──
                              // マーカーモード ON 中は、 選択が安定したら自動でハイライトを適用する。
                              // (= 「マーカーボタン → モード ON → 範囲選択するだけでマーカーが引かれる」 体験)。
                              onTextSelectionChanged: (details) {
                                if (!mounted) return;
                                final t = details.selectedText;
                                dynamic lines;
                                try {
                                  lines =
                                      (details as dynamic).selectedTextLines;
                                } catch (_) {}
                                if (t != _selectedPdfText ||
                                    lines != _selectedPdfLines) {
                                  setState(() {
                                    _selectedPdfText = t;
                                    _selectedPdfLines = lines;
                                  });
                                }
                                // ── 自動適用デバウンス ──
                                // 選択直後すぐ適用したいので 100ms に短縮。 syncfusion が選択を
                                // 勝手にクリアする (= _selectedPdfText が空になる) ケースがある
                                // ため、 timer 発火時の "現在状態" 一致ガードは撤去し、 トリガー
                                // 時点の text / lines をクロージャで持ち越して使う方式に変更。
                                _highlightAutoTimer?.cancel();
                                if (_activeMarkerColor != null &&
                                    t != null &&
                                    t.isNotEmpty &&
                                    t != _lastAutoAppliedText &&
                                    _nodeId != null) {
                                  final triggerText = t;
                                  final triggerLines = lines;
                                  _highlightAutoTimer = Timer(
                                      const Duration(milliseconds: 100), () {
                                    if (!mounted) return;
                                    if (_activeMarkerColor == null) return;
                                    _lastAutoAppliedText = triggerText;
                                    // 状態が変わっていても、 トリガー時の値で適用できるように
                                    // 一時的に _selectedPdf* を上書きしてから適用 → 元に戻す。
                                    final savedText = _selectedPdfText;
                                    final savedLines = _selectedPdfLines;
                                    _selectedPdfText = triggerText;
                                    _selectedPdfLines = triggerLines;
                                    _addHighlightForSelection().then((_) {
                                      if (!mounted) return;
                                      // 適用後 _selectedPdfText/_selectedPdfLines は null に
                                      // なっているので、 通常の状態保持は不要。
                                    }).catchError((_) {
                                      // 失敗時は元の状態に戻す
                                      if (!mounted) return;
                                      setState(() {
                                        _selectedPdfText = savedText;
                                        _selectedPdfLines = savedLines;
                                      });
                                    });
                                  });
                                }
                              },
                              onPageChanged: (details) {
                                // ズーム直後 (Ctrl + / -) はページ番号の巻き添え更新を無視
                                //   する (= ユーザー要望「ズームで表示ページ番号が変わるのを
                                //   防いで」)。
                                final suppressed =
                                    DateTime.now().millisecondsSinceEpoch <
                                        _suppressPageChangeUntilMs;
                                if (suppressed) return;
                                // ページが実際に変わった時だけ再構築 (= ユーザー要望: ページ
                                //   めくりのたびに画面全体が再構築されて重いのを軽減)。
                                if (mounted &&
                                    _currentPage != details.newPageNumber) {
                                  setState(() {
                                    _currentPage = details.newPageNumber;
                                    // タイトルバーのページ入力欄も追従させる
                                    if (_pageInputCtrl.text !=
                                        '${details.newPageNumber}') {
                                      _pageInputCtrl.text =
                                          '${details.newPageNumber}';
                                    }
                                  });
                                  // フィット表示中はページが変わったら画像を作り直す。
                                  //   連続めくりで毎回ラスタすると落ちるので debounce。
                                  if (_fitPageMode) _scheduleFitPageRender();
                                  if (_spreadFitPageMode)
                                    _scheduleSpreadPageRender();
                                }
                                // ── PDF 最終ページ記録 (= 次回オープン時に復元) ──
                                // ユーザー要望: 「PDF を再度開き直す時に一番最後に開いたページ
                                // からスタート」。 onPageChanged は連続発火するが、 provider 側
                                // で「値が変わらないなら書かない」 ガードがあるため低負荷。
                                if (_pdfFilePath != null) {
                                  try {
                                    context
                                        .read<MindMapProvider>()
                                        .setLastPdfPage(_pdfFilePath!,
                                            details.newPageNumber);
                                  } catch (_) {/* context 無効時は無視 */}
                                }
                                // ── 非表示 PDF ページ → 自動スキップ ──
                                // 画面分割版 (`_handleSplitPdfPageChanged`) と同じロジックに
                                // 揃え、 末尾 / 先頭で詰まらないように方向反転まで実装する。
                                if (_pdfFilePath != null &&
                                    _pdfViewerCtrl != null) {
                                  final provider =
                                      context.read<MindMapProvider>();
                                  final hidden =
                                      provider.hiddenPdfPagesFor(_pdfFilePath!);
                                  if (hidden.contains(details.newPageNumber)) {
                                    final isForward = details.newPageNumber >=
                                        details.oldPageNumber;
                                    final maxPage = _pdfViewerCtrl!.pageCount;
                                    if (maxPage > 0) {
                                      int target = details.newPageNumber;
                                      bool decided = false;
                                      for (int i = 0; i < maxPage; i++) {
                                        if (isForward) {
                                          target++;
                                          if (target > maxPage) {
                                            // 末尾を超えたら戻り方向にやり直す
                                            target = details.newPageNumber - 1;
                                            if (target < 1) break;
                                            for (int j = 0; j < maxPage; j++) {
                                              if (!hidden.contains(target)) {
                                                decided = true;
                                                break;
                                              }
                                              target--;
                                              if (target < 1) break;
                                            }
                                            break;
                                          }
                                        } else {
                                          target--;
                                          if (target < 1) {
                                            // 先頭を下回ったら前進方向にやり直す
                                            target = details.newPageNumber + 1;
                                            if (target > maxPage) break;
                                            for (int j = 0; j < maxPage; j++) {
                                              if (!hidden.contains(target)) {
                                                decided = true;
                                                break;
                                              }
                                              target++;
                                              if (target > maxPage) break;
                                            }
                                            break;
                                          }
                                        }
                                        if (!hidden.contains(target)) {
                                          decided = true;
                                          break;
                                        }
                                      }
                                      if (decided &&
                                          target != details.newPageNumber) {
                                        WidgetsBinding.instance
                                            .addPostFrameCallback((_) {
                                          if (!mounted ||
                                              _pdfViewerCtrl == null) return;
                                          try {
                                            _pdfViewerCtrl!.jumpToPage(target);
                                          } catch (_) {}
                                        });
                                      }
                                    }
                                  }
                                }
                              },
                              onDocumentLoaded: (details) {
                                _viewerMark('onDocumentLoaded');
                                WidgetsBinding.instance
                                    .addPostFrameCallback((_) {
                                  _viewerMark('first frame after load');
                                });
                                if (mounted) {
                                  setState(() {
                                    _pdfTotalPages =
                                        details.document.pages.count;
                                    _pageInputCtrl.text = '$_currentPage';
                                  });
                                  // ── PDF サムネイルが無ければ生成 (= ユーザー要望) ──
                                  // 1 ページ目のラスタ化は PDF 全体をメモリへ
                                  //   読み込む重い処理。 開いた直後に走らせると
                                  //   最初の描画と取り合いになって表示が遅れる
                                  //   ので、 画面が出てから静かに作る。
                                  Future<void>.delayed(
                                      const Duration(milliseconds: 1200), () {
                                    if (!mounted) return;
                                    _ensurePdfThumbForNode(
                                        context, _nodeId, _pdfFilePath);
                                  });
                                  // 非表示ページがある場合、 最初の表示可能ページに自動ジャンプ
                                  if (_pdfFilePath != null) {
                                    final provider =
                                        context.read<MindMapProvider>();
                                    final hidden = provider
                                        .hiddenPdfPagesFor(_pdfFilePath!);
                                    if (hidden.isNotEmpty) {
                                      int first = 1;
                                      while (first <= _pdfTotalPages &&
                                          hidden.contains(first)) {
                                        first++;
                                      }
                                      if (first > 1 &&
                                          first <= _pdfTotalPages) {
                                        WidgetsBinding.instance
                                            .addPostFrameCallback((_) {
                                          if (!mounted ||
                                              _pdfViewerCtrl == null) return;
                                          try {
                                            _pdfViewerCtrl!.jumpToPage(first);
                                          } catch (_) {}
                                        });
                                      }
                                    }
                                  }
                                  // ドキュメント開いた直後に PDF にフォーカスを戻す
                                  // (検索バーから戻った時など、 すぐ ↑↓ が効くように)
                                  _pdfFocusNode.requestFocus();
                                  // 初期 zoom を少し引き気味 (0.7) にして画面に余裕を持たせる。
                                  // continuous モードでは zoomLevel=1.0 がページ幅 = ビューア幅
                                  // (fit-width) 相当なので、 ここを下げると画面に対してページが
                                  // 一回り小さく表示され、 縦の見える範囲も広がる。
                                  // single モードでは syncfusion が自動でページを viewport にフィットさせるため、
                                  // 明示的な zoomLevel 設定は不要。 保存済みハイライトの復元のみ実施。
                                  WidgetsBinding.instance
                                      .addPostFrameCallback((_) {
                                    if (!mounted || _pdfViewerCtrl == null)
                                      return;
                                    _restoreSavedHighlights();
                                    if (_spreadFitPageMode)
                                      _scheduleSpreadPageRender();
                                  });
                                  // ── ページ全体表示 (fit-page) の既定 ON は廃止 ──
                                  //   (= ユーザー要望: 機能していないので削除)。 PDF は
                                  //   ライブの SfPdfViewer (幅フィット) のみで表示する。
                                  //   raster オーバーレイは使わないので AI 欄との競合
                                  //   フリーズも根本的に起きない。
                                  // ── PDF 最終ページ復元 ──
                                  // ユーザー要望: 「PDF を再度開き直す時に一番最後に開いたページ
                                  // からスタート」。 hidden ロジックが先に first jump していても、
                                  // ここで上書きで最終ページに飛ぶ (= 直近の閲覧位置を優先)。
                                  if (_pdfFilePath != null) {
                                    try {
                                      final lastPage = context
                                          .read<MindMapProvider>()
                                          .lastPdfPageFor(_pdfFilePath!);
                                      // 既に同じページを開いているなら飛ばない。
                                      //   飛ぶと描き直しになり、 開いた直後に
                                      //   一瞬白くなって遅く見えていた。
                                      // ★ ただし描き込みの焼き直しで**ビューアを
                                      //   作り直した**時は別。 表示は 1 ページ目に
                                      //   戻っているのに _currentPage は前の値の
                                      //   ままなので、 この条件で弾かれて戻れず、
                                      //   「消したら画面が飛ぶ」 に見えていた
                                      //   (= ユーザー報告)。 焼き直し後は必ず戻す。
                                      final afterReburn = _pdfDrawReloadTick > 0;
                                      if (lastPage != null &&
                                          (afterReburn ||
                                              lastPage != _currentPage) &&
                                          lastPage >= 1 &&
                                          lastPage <= _pdfTotalPages) {
                                        // syncfusion の jumpToPage はロード直後では確実に動作
                                        // しないため、 Future.delayed で 200ms 待ってから実行。
                                        Future.delayed(
                                            const Duration(milliseconds: 200),
                                            () {
                                          if (!mounted ||
                                              _pdfViewerCtrl == null) return;
                                          try {
                                            _pdfViewerCtrl!
                                                .jumpToPage(lastPage);
                                            setState(() {
                                              _currentPage = lastPage;
                                              _pageInputCtrl.text = '$lastPage';
                                            });
                                          } catch (e) {
                                            debugPrint('最終ページ復元失敗: $e');
                                          }
                                        });
                                      }
                                    } catch (_) {/* context 無効時は無視 */}
                                  }
                                  // ── AI パネルは「PDF が完全に描画されてから」 開く ──
                                  // PDF(SfPdfViewer) と AI(WebView=Chromium) を同時に
                                  // 生成するとフリーズ + メモリ圧迫する (= ユーザー報告)。
                                  // onDocumentLoaded は「解析完了」 であって初回ページの
                                  // 描画完了ではないため、 ここで最初の描画フレームを待ち、
                                  // さらに 2 秒の余裕を取ってから AI を生成する。 こうすると
                                  // PDF を先に軽快に読み始められ、 WebView 生成が描画と
                                  // 競合しない (= サクサク)。
                                  if (_pendingAiAutoOpen && !_aiPanelOpen) {
                                    _pendingAiAutoOpen = false;
                                    WidgetsBinding.instance
                                        .addPostFrameCallback((_) {
                                      // 一律 2 秒待っていたが、 場所は最初から
                                      //   確保済みで PDF の初回描画も終わって
                                      //   いるので、 ひと呼吸だけ置けば十分
                                      //   (= ユーザー要望: 立ち上げを速く)。
                                      Future.delayed(
                                          const Duration(milliseconds: 250),
                                          () {
                                        if (!mounted || _aiPanelOpen) return;
                                        // メモ欄も AI 欄と「同時に」 開く (= ユーザー要望:
                                        //   メモだけ起動時に付いて AI が後から開くのは変
                                        //   なので、 読み込み後に両方まとめて出す)。
                                        //   「プログラムから開く」 でもメモ欄を出す
                                        //   (= ユーザー要望)。
                                        if (_nodeId != null ||
                                            widget.onEnsureNode != null) {
                                          setState(() => _memoPanelOpen = true);
                                        }
                                        _openAiPanel(context
                                            .read<MindMapProvider>()
                                            .pdfAiPanelDefault);
                                        // 中身が入ったので「場所取り」 は役目を
                                        //   終える。 外し忘れると、 利用者が
                                        //   パネルを閉じた後も空の帯が残って
                                        //   場所を取り続けてしまう。
                                        _releasePanelSlotReservation();
                                      });
                                    });
                                  }
                                }
                              },
                              onDocumentLoadFailed: (details) {
                                if (mounted) {
                                  setState(() => _pdfError =
                                      '${details.error}: ${details.description}');
                                }
                                // 読み込めなかった時も場所取りは解除する。
                                _releasePanelSlotReservation();
                              },
                            ),
                          ), // Listener 閉じ (= 全画面 PDF の右クリック検出)
                          ), // PdfDrawLayer 閉じ
                        ),
                      ),
                    );
                  },
                ),
              // マーカーバナー / FAB は廃止 (syncfusion 標準メニュー統合のため不要)
              // ── ページ全体表示オーバーレイ (= ユーザー要望) ──
              if (_spreadFitPageMode) _buildSpreadPageOverlay(),
              // ── 音声読み上げ操作バー (= ユーザー要望: PDF 音声読み上げ) ──
              if (_readerVisible && _reader != null)
                Positioned(
                  left: 0,
                  right: 0,
                  bottom: 14,
                  child: Center(
                    child: ReadAloudBar(
                      controller: _reader!,
                      onClose: _stopReadAloud,
                    ),
                  ),
                ),
            ],
          ),
        ),
      );
    }
    // ── Linux: webview_windows / iaw 非対応 → CEF (LinuxWebViewWidget) で表示 ──
    //   (= Linux でも Web ページ (PDF 以外) を開けるように)。 _useWebView2 は
    //   Windows 限定なので Linux はここを通り、 下の iaw 経路には乗らない。
    if (Platform.isLinux) {
      return linux_wv.LinuxWebViewWidget(
        url: _currentUrl.isNotEmpty ? _currentUrl : widget.url,
        onUrlChanged: (u) {
          if (mounted && u.isNotEmpty) _currentUrl = u;
        },
      );
    }
    if (_useWebView2) {
      if (_winError != null) {
        return Center(
          child: Padding(
            padding: const EdgeInsets.all(16),
            child: Text(
              'WebView2 を初期化できませんでした:\n$_winError\n'
              'Microsoft Edge WebView2 ランタイムをインストールしてください。',
              style: const TextStyle(color: Colors.white70, fontSize: 13),
              textAlign: TextAlign.center,
            ),
          ),
        );
      }
      if (!_winReady || _winCtrl == null) {
        return const Center(
          child: CircularProgressIndicator(strokeWidth: 2),
        );
      }
      return Stack(
        children: [
          Positioned.fill(
            // ── マウスホイールでスクロールできるようにする (= ユーザー要望:
            //    サイドメニューの Web (DeepSeek 等の AI) を全画面にすると
            //    スクロールが効かない) ──。 webview_windows はホイールを内部
            //    スクロールに転送しないため、 分割パネルと同じくホイール量を JS で
            //    スクロールさせる。
            child: Listener(
              onPointerSignal: (e) {
                if (e is PointerScrollEvent) {
                  final dx = e.scrollDelta.dx.round();
                  final dy = e.scrollDelta.dy.round();
                  if (dx != 0 || dy != 0) {
                    try {
                      _winCtrl?.executeScript(_webWheelScrollJs(dx, dy));
                    } catch (_) {}
                  }
                }
              },
              child: wv_win.Webview(_winCtrl!),
            ),
          ),
          // ── 右下の緑メモ FAB は廃止 (= ユーザー要望: メモは左サイド
          //    メニューから追加するので不要) ──
        ],
      );
    }
    return Stack(
      children: [
        Positioned.fill(
          child: iaw.InAppWebView(
            initialUrlRequest: iaw.URLRequest(url: iaw.WebUri(widget.url)),
            initialSettings: iaw.InAppWebViewSettings(
              transparentBackground: false,
              allowFileAccess: true,
              allowFileAccessFromFileURLs: true,
              allowUniversalAccessFromFileURLs: true,
            ),
            onWebViewCreated: (c) => _iawCtrl = c,
            onTitleChanged: (c, t) {
              if (mounted && t != null && t.isNotEmpty) {
                setState(() => _title = t);
              }
            },
            onLoadStart: (c, u) {
              if (mounted && u != null) {
                setState(() => _currentUrl = u.toString());
              }
            },
            onLoadStop: (c, u) async {
              if (mounted && u != null) {
                setState(() => _currentUrl = u.toString());
              }
              // 画面分割から引き継いだ再生速度を動画へ適用 (ユーザー要望)。
              if ((_videoPlaybackRate - 1.0).abs() > 0.001) {
                for (final ms in const [300, 1000, 2500]) {
                  await Future<void>.delayed(Duration(milliseconds: ms));
                  if (!mounted) break;
                  await _applyInAppVideoRate(_videoPlaybackRate);
                }
              }
              _scheduleWebVideoProbe();
            },
            onUpdateVisitedHistory: (c, u, __) {
              if (mounted && u != null) {
                setState(() => _currentUrl = u.toString());
                _scheduleWebVideoProbe();
              }
            },
            // 配置モード時に scrollY を保存できるよう、 常時スクロール位置を追跡
            onScrollChanged: (c, x, y) {
              _currentScrollY = y.toDouble();
            },
            // ── ページ内検索のヒット件数を listen ──
            // findAllAsync で開始した検索の進捗が通知される。
            // activeMatchOrdinal は 0-indexed。
            onFindResultReceived:
                (c, activeMatchOrdinal, numberOfMatches, isDoneCounting) {
              if (mounted) {
                setState(() {
                  _urlActiveMatch =
                      numberOfMatches > 0 ? activeMatchOrdinal + 1 : 0;
                  _urlMatchCount = numberOfMatches;
                });
              }
            },
          ),
        ),
        // ── Web ページメモパネル / 緑 FAB は廃止 (= ユーザー要望: メモは
        //    左サイドメニューから追加するので、 右下の緑ボタンは不要) ──
      ],
    );
  }

  // ── 右下の緑メモ FAB / Web ページメモパネルは完全廃止 ──
  //   (= ユーザー要望: メモは左サイドメニューから追加するため不要)。
  //   旧 _buildWebMemoFab / _buildWebMemoPanel / _webMemoPanelOpen を削除。

  /// WebView 本体 + メモマーカーオーバーレイ + 配置モードオーバーレイ
  Widget _buildWebViewArea(MindMapProvider provider) {
    final hasNode = _nodeId != null;
    return LayoutBuilder(
      builder: (lctx, constraints) {
        final area = Size(constraints.maxWidth, constraints.maxHeight);
        // ── マーカーは「直近にタップ / 追加されたメモ 1 個」 のみ表示 ──
        // PDF ビューアの内部スクロール / ページめくりは Flutter からは
        // 検知できないため、 全メモを常時オーバーレイすると PDF 上で
        // ページが進んでもマーカーが画面に居座ってしまう (= 位置がずれる)。
        // 解決策: 「アクティブ表示」 のみに限定する。
        //   - ジャンプ直後 / 追加直後だけ 3 秒程度パルスでハイライト
        //   - その後は自動で消える → ユーザーが PDF を読み進めても
        //     古い位置にマーカーが残らない
        // 全メモの一覧 + ジャンプはサイドパネル側で担当する。
        final activeMemo = (hasNode && _highlightMemoId != null)
            ? _findActiveMemo(provider)
            : null;
        return Stack(
          children: [
            Positioned.fill(child: _buildPureWebView()),
            // ── 動画サイトなら再生速度バーを上にオーバーレイ ──
            // 画面分割と同じ仕組み: <video> タグの playbackRate を JS で操作。
            if (_isVideoSiteUrl(_currentUrl) || _webHasVideo)
              Positioned(
                top: 8,
                left: 8,
                right: 8,
                child: _buildInAppVideoSpeedBar(),
              ),
            if (activeMemo != null)
              _buildMemoMarker(
                memo: activeMemo,
                area: area,
                isHighlighted: true,
                pulse: _pulseCtrl,
                onTap: () => _showMemoDetailPopup(
                    context, provider, _nodeId!, activeMemo),
                onLongPress: () => _editMemoInline(provider, activeMemo),
              ),
            // メモ配置モード: WebView を覆う透明オーバーレイ
            if (_placingMemo && hasNode)
              Positioned.fill(
                child: GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTapDown: (d) => _onPlaceTap(d, area),
                  child: Container(
                    color: Colors.black.withValues(alpha: 0.18),
                    child: Stack(
                      children: [
                        Positioned(
                          top: 14,
                          left: 0,
                          right: 0,
                          child: Center(
                            child: Container(
                              padding: const EdgeInsets.symmetric(
                                  horizontal: 14, vertical: 8),
                              decoration: BoxDecoration(
                                color: const Color(0xFFFFC107),
                                borderRadius: BorderRadius.circular(20),
                                boxShadow: const [
                                  BoxShadow(
                                      color: Colors.black45, blurRadius: 6),
                                ],
                              ),
                              child: const Text(
                                'メモを置きたい場所をタップ ・ ESC で取消',
                                style: TextStyle(
                                    color: Colors.black87,
                                    fontWeight: FontWeight.w700,
                                    fontSize: 13),
                              ),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
          ],
        );
      },
    );
  }

  /// URL が動画サイトか判定 (= 速度バー表示の条件)。
  bool _isVideoSiteUrl(String url) {
    return _isLikelyEmbeddedVideoUrl(url);
  }

  /// JS で <video> タグの再生速度を設定。
  Future<void> _applyInAppVideoRate(double rate) async {
    final js = webVideoRateJs(rate);
    try {
      if (Platform.isWindows && _winReady) {
        await _winCtrl?.executeScript(js);
      } else if (_iawCtrl != null) {
        await _iawCtrl!.evaluateJavascript(source: js);
      }
    } catch (_) {}
  }

  Future<void> _probeWebVideoPresence() async {
    if (!mounted || widget.isPdf) return;
    dynamic result;
    try {
      if (_useWebView2 && _winCtrl != null && _winReady) {
        result = await _winCtrl!.executeScript(_webVideoPresenceJs());
      } else if (_iawCtrl != null) {
        result =
            await _iawCtrl!.evaluateJavascript(source: _webVideoPresenceJs());
      } else {
        return;
      }
    } catch (_) {
      return;
    }
    final hasVideo = _webJsTruthy(result);
    if (mounted && hasVideo != _webHasVideo) {
      setState(() => _webHasVideo = hasVideo);
    }
  }

  void _scheduleWebVideoProbe() {
    for (final ms in const [250, 1200, 3000]) {
      Future.delayed(Duration(milliseconds: ms), () {
        if (mounted) _probeWebVideoPresence();
      });
    }
  }

  /// 動画サイトを開いている時のオーバーレイ再生速度バー (全画面ビューア用)。
  /// 画面分割の `_buildSplitVideoSpeedBar` と同じ仕組み: Slider + プリセット。
  Widget _buildInAppVideoSpeedBar() {
    // 通常画面・画面分割と共通の最大倍率を使う (= 設定で変更可能、 既定 5.0)。
    // ユーザー要望: 全画面表示に戻すと 2 倍までしか出せないのを解消。
    final maxRate =
        context.watch<MindMapProvider>().videoMaxRate.clamp(1.5, 16.0);
    final List<double> rawPresets;
    if (maxRate <= 2.0 + 0.01) {
      rawPresets = [0.5, 1.0, 1.5, 2.0];
    } else if (maxRate <= 4.0 + 0.01) {
      rawPresets = [1.0, 1.5, 2.0, 3.0, maxRate];
    } else if (maxRate <= 8.0 + 0.01) {
      rawPresets = [1.0, 2.0, 4.0, maxRate];
    } else {
      rawPresets = [1.0, 2.0, 4.0, 8.0, maxRate];
    }
    final presetSet = <double>{};
    for (final p in rawPresets) {
      presetSet.add(double.parse(p.toStringAsFixed(2)));
    }
    final presets = presetSet.toList()..sort();
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: Colors.black.withValues(alpha: 0.75),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: Colors.white12),
      ),
      child: Row(
        children: [
          const Icon(Icons.speed_rounded, color: Color(0xFF6C63FF), size: 18),
          const SizedBox(width: 6),
          Text(
            '${_videoPlaybackRate.toStringAsFixed(2)}x',
            style: const TextStyle(
              color: Colors.white,
              fontSize: 12,
              fontWeight: FontWeight.w700,
              fontFeatures: [FontFeature.tabularFigures()],
            ),
          ),
          const SizedBox(width: 4),
          Expanded(
            child: SliderTheme(
              data: SliderTheme.of(context).copyWith(
                trackHeight: 3,
                thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 7),
                overlayShape: const RoundSliderOverlayShape(overlayRadius: 14),
                activeTrackColor: const Color(0xFF6C63FF),
                inactiveTrackColor: Colors.white24,
                thumbColor: const Color(0xFF6C63FF),
                overlayColor: const Color(0xFF6C63FF).withValues(alpha: 0.3),
              ),
              child: Slider(
                value: _videoPlaybackRate.clamp(0.25, maxRate),
                min: 0.25,
                max: maxRate,
                divisions: ((maxRate - 0.25) * 4).round().clamp(10, 200),
                onChanged: (v) {
                  setState(() => _videoPlaybackRate = v);
                  _applyInAppVideoRate(v);
                },
              ),
            ),
          ),
          for (final preset in presets)
            Padding(
              padding: const EdgeInsets.only(left: 4),
              child: InkWell(
                borderRadius: BorderRadius.circular(4),
                onTap: () {
                  setState(() => _videoPlaybackRate = preset);
                  _applyInAppVideoRate(preset);
                },
                child: Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
                  decoration: BoxDecoration(
                    color: (_videoPlaybackRate - preset).abs() < 0.01
                        ? const Color(0xFF6C63FF).withValues(alpha: 0.25)
                        : Colors.transparent,
                    borderRadius: BorderRadius.circular(4),
                    border: Border.all(
                      color: (_videoPlaybackRate - preset).abs() < 0.01
                          ? const Color(0xFF6C63FF)
                          : Colors.white24,
                      width: 0.5,
                    ),
                  ),
                  child: Text(
                    '${preset.toStringAsFixed(preset == preset.truncateToDouble() ? 0 : 1)}x',
                    style: TextStyle(
                      color: (_videoPlaybackRate - preset).abs() < 0.01
                          ? const Color(0xFF6C63FF)
                          : Colors.white70,
                      fontSize: 11,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }

  Future<void> _editMemoInline(MindMapProvider provider, PdfMemo m) async {
    final updated = await showDialog<PdfMemo?>(
      context: context,
      builder: (_) => _PdfMemoEditDialog(initial: m),
    );
    if (updated != null) {
      provider.updatePdfMemo(
        _nodeId!,
        m.id,
        text: updated.text,
        pageNumber: updated.pageNumber,
        url: updated.url,
        colorValue: updated.colorValue,
      );
    }
  }

  Widget _floatingPdfToolButton({
    required IconData icon,
    required String label,
    required Color color,
    required VoidCallback onTap,
  }) {
    return Material(
      color: const Color(0xE61B1B2A),
      borderRadius: BorderRadius.circular(18),
      child: InkWell(
        borderRadius: BorderRadius.circular(18),
        onTap: onTap,
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            Icon(icon, color: color, size: 17),
            const SizedBox(width: 5),
            Text(label,
                style: const TextStyle(color: Colors.white70, fontSize: 12)),
          ]),
        ),
      ),
    );
  }

  Widget _floatingPdfPanel({
    required Widget child,
    required double width,
    required double height,
  }) {
    return Material(
      color: Colors.transparent,
      elevation: 10,
      borderRadius: BorderRadius.circular(14),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(14),
        child: SizedBox(width: width, height: height, child: child),
      ),
    );
  }

  /// 見開き時の左右ドックを、PDF本体と区別しやすいカード状に整える。
  /// 通常表示では既存のパネル外観を維持する。
  Widget _spreadDockSurface({
    required Widget child,
    required Color accent,
  }) {
    if (!_spreadFitPageMode) return child;
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 10),
      child: DecoratedBox(
        decoration: BoxDecoration(
          color: const Color(0xFF191927),
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: accent.withValues(alpha: 0.42)),
          boxShadow: const [
            BoxShadow(
              color: Colors.black45,
              blurRadius: 16,
              offset: Offset(0, 5),
            ),
          ],
        ),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(13),
          child: child,
        ),
      ),
    );
  }

  Widget _buildCompactPdfFloatingTools(
      MindMapProvider provider, bool hasMemoPanel) {
    final screen = MediaQuery.of(context).size;
    // ── 高さは画面いっぱいを使う ──
    // 旧: 上限 520px にクランプしていたため、 ページ全体表示/見開き等の
    // フィット系モードに入るとメモ欄/AI チャット欄が縦に縮んで見えた
    // (= ユーザー要望 2026-07: 拡大率を小さくしても表示領域が変わらない
    // ように)。 通常ドックと同じく画面高さ − ヘッダー分を確保する。
    final panelHeight = math.max(260.0, screen.height - 120.0);
    final memoWidth = (screen.width * 0.22).clamp(240.0, 320.0);
    final aiWidth = (screen.width * 0.26).clamp(280.0, 380.0);
    return IgnorePointer(
      ignoring: false,
      child: Stack(children: [
        if (hasMemoPanel)
          Positioned(
            top: 12,
            left: 12,
            child: _memoPanelOpen
                ? _floatingPdfPanel(
                    width: memoWidth,
                    height: panelHeight,
                    child: _nodeId == null
                        ? _buildMemoPanelPlaceholder(provider)
                        : _buildMemoPanelInner(provider),
                  )
                : _floatingPdfToolButton(
                    icon: Icons.sticky_note_2_outlined,
                    label: 'メモ',
                    color: const Color(0xFFFFC107),
                    onTap: () => setState(() => _memoPanelOpen = true),
                  ),
          ),
        Positioned(
          top: 12,
          right: 12,
          child: _aiPanelOpen
              ? _floatingPdfPanel(
                  width: aiWidth,
                  height: panelHeight,
                  child: _buildAiPanelInner(provider),
                )
              : _floatingPdfToolButton(
                  icon: Icons.smart_toy_outlined,
                  label: 'AI',
                  color: const Color(0xFF4FC3F7),
                  onTap: () => _openAiPanel(
                      context.read<MindMapProvider>().pdfAiPanelDefault),
                ),
        ),
      ]),
    );
  }

  /// 動画視聴中は現在の再生位置を URL に付けて返す (= ユーザー要望:
  /// 画面分割へ移った時に画面が更新されて頭から再生し直しにならないように)。
  Future<String> _viewerUrlWithVideoPosition(String url) async {
    double sec = 0;
    try {
      final ctrl = _winCtrl;
      if (ctrl != null) {
        final result = await ctrl.executeScript(
            "(function(){try{var v=document.querySelector('video');"
            "return v?v.currentTime:0;}catch(e){return 0;}})()");
        if (result != null) {
          sec = double.tryParse(
                  result.toString().replaceAll('"', '').trim()) ??
              0;
        }
      }
    } catch (_) {}
    if (sec < 3) return url;
    final t = sec.floor();
    final uri = Uri.tryParse(url);
    if (uri != null &&
        (url.contains('youtube.com/watch') || url.contains('youtu.be/'))) {
      final qp = Map<String, String>.from(uri.queryParameters);
      qp['t'] = '${t}s';
      return uri.replace(queryParameters: qp).toString();
    }
    return url;
  }

  @override
  Widget build(BuildContext context) {
    // メモ / AI パネルは、 マップに未追加でも使えるようにする
    // (= ユーザー要望: 「プログラムから開く」 で開いた時も埋め込んだ時と
    //  同じようにメモ欄 / AI 欄が立ち上がるように)。 実際に書き込む時点で
    //  マップへ追加される。
    final hasMemoPanel = _nodeId != null || widget.onEnsureNode != null;
    // ── キー入力を受け取って画面分割ショートカットを処理 ──
    // ユーザー要望「全画面表示からの画面分割がショートカットキーでできなく
    //   なっている」 への対応。 Dialog.fullscreen で全画面 viewer を開くと
    //   メイン画面の KeyboardListener にはキー入力が届かないため、 ここで
    //   Focus widget を被せて Ctrl+\\ / Ctrl+^ を直接処理する。
    //   * Ctrl+\\ → 右画面分割パネルへ移動
    //   * Ctrl+^  → 左画面分割パネルへ移動
    return Focus(
      autofocus: true,
      onKeyEvent: (node, event) {
        if (event is! KeyDownEvent) return KeyEventResult.ignored;
        // ── Esc で閉じない (= ユーザー要望: Esc でファイルを閉じる機能は
        //    無効化して、 描き込み中は「選ぶ」 への切り替えに使う)。
        //    PDF は設定に関わらず常に閉じない。 それ以外は従来どおり設定に従う。
        //    消費して既定の dismiss へ流さない。 ──
        if (event.logicalKey == LogicalKeyboardKey.escape &&
            (widget.isPdf ||
                !context.read<MindMapProvider>().closeViewerWithEsc)) {
          return KeyEventResult.handled;
        }
        final isCtrl = HardwareKeyboard.instance.isControlPressed ||
            HardwareKeyboard.instance.isMetaPressed;
        if (!isCtrl) return KeyEventResult.ignored;
        // 動画の再生位置を取ってから pop → 分割へ引き継ぐ共通処理
        // (= ユーザー要望: 分割時に再生位置が最初に戻らない)。
        void moveToSplitKeepingPosition({required bool isLeftPanel}) {
          unawaited(() async {
            final url = await _viewerUrlWithVideoPosition(_currentUrl);
            if (!mounted) return;
            Navigator.of(context).pop();
            widget.onMoveToSplitPanel!(url, isLeftPanel: isLeftPanel);
          }());
        }

        // Ctrl+\\ → 右画面分割で開く
        if (event.logicalKey == LogicalKeyboardKey.backslash &&
            !HardwareKeyboard.instance.isShiftPressed &&
            widget.onMoveToSplitPanel != null) {
          moveToSplitKeepingPosition(isLeftPanel: false);
          return KeyEventResult.handled;
        }
        // Ctrl+^ → 左画面分割で開く (日本語キーボード対応の複数判定)
        final logicalCaret = event.logicalKey == LogicalKeyboardKey.caret;
        final physicalCaret = event.physicalKey == PhysicalKeyboardKey.equal;
        final charCaret = (event.character ?? '') == '^';
        final isShift6 = HardwareKeyboard.instance.isShiftPressed &&
            (event.logicalKey == LogicalKeyboardKey.digit6 ||
                event.logicalKey == LogicalKeyboardKey.numpad6);
        if ((logicalCaret || physicalCaret || charCaret || isShift6) &&
            widget.onMoveToSplitPanel != null) {
          moveToSplitKeepingPosition(isLeftPanel: true);
          return KeyEventResult.handled;
        }
        return KeyEventResult.ignored;
      },
      child: PopScope(
        // 今セッションで追加したマーカーがあるときは pop を一旦止めて確認ダイアログ
        canPop: _sessionAddedHighlightIds.isEmpty,
        onPopInvoked: (didPop) async {
          if (didPop) return;
          final ok = await _confirmCloseIfNeeded();
          if (ok && mounted) {
            Navigator.of(context).pop();
          }
        },
        child: Consumer<MindMapProvider>(
          builder: (ctx, provider, _) {
            return Container(
              color: const Color(0xFF1A1A24),
              child: Column(
                children: [
                  // ── タイトルバー ──
                  Container(
                    height: 44,
                    color: const Color(0xFF252535),
                    padding: const EdgeInsets.symmetric(horizontal: 12),
                    child: Row(
                      children: [
                        Icon(widget.isPdf ? Icons.picture_as_pdf : Icons.public,
                            color: Colors.white70, size: 18),
                        const SizedBox(width: 10),
                        Expanded(
                          child: Text(
                            _title.isNotEmpty ? _title : _currentUrl,
                            style: const TextStyle(
                                color: Colors.white, fontSize: 13),
                            overflow: TextOverflow.ellipsis,
                          ),
                        ),
                        // ── PDF: ページ番号ナビ ──
                        // タイトルバー右側に「[<] [3] / 92 [>]」 を配置。
                        // ページ番号入力欄に直接打ち込んで Enter で即ジャンプ。
                        // ページ移動は設定メニューに集約 (= ユーザー要望)。
                        // ここは現在ページ表示のみ残す。
                        if (widget.isPdf && _pdfTotalPages > 0) ...[
                          Padding(
                            padding: const EdgeInsets.symmetric(horizontal: 4),
                            child: Text('$_currentPage / $_pdfTotalPages',
                                style: const TextStyle(
                                    color: Colors.white60, fontSize: 12)),
                          ),
                        ],
                        // 読む方向の切替は ⋮ 設定メニューの一番上へ移動 (= ユーザー要望)。
                        // ── メモパネルの開閉 (外に出す) ──
                        // ★ メモは左パネルに開くので、 ボタンも AI (右パネル) より
                        //   左に置く (= ユーザー要望: ヘッダーの並びと開かれる
                        //   左右が逆なのが気になる)。
                        if (hasMemoPanel)
                          IconButton(
                            tooltip: _memoPanelOpen
                                ? 'メモパネルを閉じる (Ctrl+M)'
                                : 'メモパネルを開く (Ctrl+M)',
                            icon: Icon(
                              _memoPanelOpen
                                  ? Icons.sticky_note_2
                                  : Icons.sticky_note_2_outlined,
                              color: const Color(0xFFFFC107),
                              size: 20,
                            ),
                            onPressed: () async {
                              _suppressPdfPageChangeBriefly();
                              // 開くタイミングでマップへ追加する (メモは
                              // ノードに紐付くため)。
                              if (!_memoPanelOpen) await _ensureNode();
                              if (!mounted) return;
                              setState(() => _memoPanelOpen = !_memoPanelOpen);
                            },
                          ),
                        // ── 生成 AI チャット欄を開く / 閉じる (トグル) ──
                        // 左クリック: 開いていなければ既定 AI を開く。 既に
                        //   開いていれば閉じる (= ユーザー要望「AI のアイコンを
                        //   再度押したら閉じれるように」)。
                        // 右クリック: 開く AI を切り替える (永続化される)。
                        GestureDetector(
                          onSecondaryTapDown: (d) =>
                              _showAiPickerMenu(d.globalPosition),
                          child: IconButton(
                            tooltip: _aiPanelOpen
                                ? 'AI チャット欄を閉じる (Ctrl+I / F4)'
                                : 'AI チャット欄を開く (Ctrl+I / F4, 右クリックで切替)',
                            icon: Icon(
                                _aiPanelOpen
                                    ? Icons.smart_toy_rounded
                                    : Icons.smart_toy_outlined,
                                color: _aiPanelOpen
                                    ? const Color(0xFF4FC3F7)
                                    : const Color(0xFF4FC3F7),
                                size: 20),
                            onPressed: () {
                              if (_aiPanelOpen) {
                                _suppressPdfPageChangeBriefly();
                                setState(() {
                                  _aiPanelOpen = false;
                                  _aiWebViewCache =
                                      null; // ★ フリーズ対策: 閉じたら WebView キャッシュを破棄
                                });
                              } else {
                                _openAiPanel(context
                                    .read<MindMapProvider>()
                                    .pdfAiPanelDefault);
                              }
                            },
                          ),
                        ),
                        // ── ページに追加 (= ユーザー要望) ──
                        // まだマップに載っていない時だけ出す。
                        if (_canAddToPage)
                          Builder(builder: (btnCtx) {
                            return IconButton(
                              tooltip: context
                                  .read<MindMapProvider>()
                                  .t('openWith.addToPage'),
                              icon: const Icon(Icons.add_to_photos_rounded,
                                  color: Color(0xFF43B97F), size: 20),
                              // 追加先ページを選んでから追加する
                              // (= ユーザー要望)。
                              onPressed: () async {
                                await _ensureNodeWithPagePicker(btnCtx);
                              },
                            );
                          }),
                        // ── その他のボタンは「設定」 メニューに格納 (= ユーザー要望:
                        //    ヘッダーのオーバーフロー対策。 検索 / メモ配置 / DeepL /
                        //    再読み込み / ブラウザで開く / クイズ / 画面分割 をまとめる)。
                        //    位置は「ページに追加」 の右 (= ユーザー要望)。 ──
                        // ── PDF への描き込み (= ユーザー要望: PDF に
                        //    書き込んだり図形を上に書けるように)。 設定
                        //    メニューの奥ではなくヘッダーに出す。 ──
                        if (widget.isPdf && _pdfFilePath != null)
                          IconButton(
                            tooltip: context
                                .read<MindMapProvider>()
                                .t('pdf.drawShapes'),
                            icon: Icon(
                                _pdfDrawActive
                                    ? Icons.draw_rounded
                                    : Icons.draw_outlined,
                                color: _pdfDrawActive
                                    ? const Color(0xFF5FD3B2)
                                    : Colors.white70,
                                size: 20),
                            onPressed: _togglePdfDrawMode,
                          ),
                        // ── ダウンロード / 左・右に分割 (= ユーザー要望:
                        //    設定の奥ではなくヘッダーに並べる) ──
                        if (widget.isPdf && _pdfFilePath != null)
                          IconButton(
                            tooltip: context
                                .read<MindMapProvider>()
                                .t('fsv.download'),
                            icon: const Icon(Icons.download_rounded,
                                color: Color(0xFF4FC3F7), size: 20),
                            onPressed: () =>
                                unawaited(_downloadCurrentFile()),
                          ),
                        if (widget.onMoveToSplitPanel != null) ...[
                          IconButton(
                            tooltip: context
                                .read<MindMapProvider>()
                                .t('openStyle.splitLeft'),
                            icon: _splitPanelIcon(_SplitIconFill.left,
                                color: const Color(0xFFFF6B6B), size: 19),
                            onPressed: () => _moveToSplitPane(left: true),
                          ),
                          IconButton(
                            tooltip: context
                                .read<MindMapProvider>()
                                .t('openStyle.splitRight'),
                            icon: _splitPanelIcon(_SplitIconFill.right,
                                color: const Color(0xFF2196F3), size: 19),
                            onPressed: () => _moveToSplitPane(left: false),
                          ),
                        ],
                        _buildPdfSettingsMenu(hasMemoPanel),
                        IconButton(
                          tooltip:
                              context.read<MindMapProvider>().t('btn.close'),
                          icon: const Icon(Icons.close,
                              color: Colors.white, size: 20),
                          onPressed: () => Navigator.of(context).pop(),
                        ),
                      ],
                    ),
                  ),
                  // ── 検索バー (PDF / URL 両方、 トグル開閉) ──
                  if (_searchBarOpen) _buildSearchBar(),
                  // ── 描き込みの道具箱 (= ユーザー要望: PDF の上に被らない
                  //    ようヘッダーの下に出す。 モードの時だけ) ──
                  _buildPdfDrawToolbarBar(),
                  // ── 本体 ──
                  Expanded(
                    child: Builder(builder: (_) {
                      final compactPdfMode = widget.isPdf &&
                          (_fitPageMode ||
                              _spreadPageMode ||
                              _spreadFitPageMode);
                      // 見開きではフローティングパネルをPDF上へ重ねず、通常時と
                      // 同じ左右ドックを使う。ページ・ナビ矢印を隠さず、幅変更と
                      // 左右入れ替えもそのまま利用できる。
                      final useDockedSpreadPanels = _spreadFitPageMode;
                      // ── 開く前から両脇の場所だけ取っておく (= ユーザー要望:
                      //    立ち上がりを速く) ──
                      //    以前は PDF を全幅で描いた後にメモ欄と AI 欄が
                      //    割り込み、 その度に PDF が幅を変えて描き直されて
                      //    いた (= 表示までに二度手間で、 見た目にもガタつく)。
                      //    先に幅を確保しておけば、 PDF の描画は一度で済む。
                      final reserveSlots =
                          _panelSlotsReserved && (!compactPdfMode || useDockedSpreadPanels);
                      final showMemo = hasMemoPanel &&
                          _memoPanelOpen &&
                          (!compactPdfMode || useDockedSpreadPanels);
                      // 既定: メモ=左 / AI=右。入れ替え時は左右逆。
                      final memoOnLeft = !_panelsSwapped;
                      final screenW = MediaQuery.of(context).size.width;
                      final maxW = (screenW * 0.8).clamp(280.0, 1400.0);
                      final memoSlot = (showMemo || (reserveSlots && hasMemoPanel))
                          ? _buildResizableDock(
                              panel: _spreadDockSurface(
                                child: !showMemo
                                    ? const SizedBox.expand()
                                    : (_nodeId == null
                                        ? _buildMemoPanelPlaceholder(provider)
                                        : _buildMemoPanelInner(provider)),
                                accent: const Color(0xFFFFC107),
                              ),
                              width: _memoPanelWidth.clamp(240.0, maxW),
                              handleOnLeft: !memoOnLeft,
                              onResizeDelta: (dx) {
                                final signed = memoOnLeft ? dx : -dx;
                                // 幅変更で PDF が再レイアウトしてページが飛ぶのを防ぐ
                                _suppressPdfPageChangeBriefly();
                                setState(() => _memoPanelWidth =
                                    (_memoPanelWidth + signed)
                                        .clamp(240.0, maxW));
                              },
                            )
                          : null;
                      final showAi = _aiPanelOpen &&
                          (!compactPdfMode || useDockedSpreadPanels);
                      final aiSlot = (showAi || reserveSlots)
                          ? _buildResizableDock(
                              panel: _spreadDockSurface(
                                child: !showAi
                                    ? const SizedBox.expand()
                                    : _buildAiPanelInner(provider),
                                accent: const Color(0xFF4FC3F7),
                              ),
                              width: _aiPanelWidth.clamp(280.0, maxW),
                              handleOnLeft: memoOnLeft,
                              onResizeDelta: (dx) {
                                final signed = memoOnLeft ? -dx : dx;
                                // 幅変更で PDF が再レイアウトしてページが飛ぶのを防ぐ
                                _suppressPdfPageChangeBriefly();
                                setState(() => _aiPanelWidth =
                                    (_aiPanelWidth + signed)
                                        .clamp(280.0, maxW));
                              },
                            )
                          : null;
                      final leftSlot = memoOnLeft ? memoSlot : aiSlot;
                      final rightSlot = memoOnLeft ? aiSlot : memoSlot;
                      final body = Row(
                        children: [
                          if (leftSlot != null) leftSlot,
                          // PDF/Web 本体。ClipRect で囲み、拡大しても描画が
                          //   サイドパネルの領域へはみ出さない (= 重ならない)
                          //   ようにする (= ユーザー要望)。
                          Expanded(
                            child: ClipRect(
                              child: _buildWebViewArea(provider),
                            ),
                          ),
                          if (rightSlot != null) rightSlot,
                        ],
                      );
                      if (!compactPdfMode || useDockedSpreadPanels) {
                        return body;
                      }
                      return Stack(
                        children: [
                          Positioned.fill(child: body),
                          _buildCompactPdfFloatingTools(provider, hasMemoPanel),
                        ],
                      );
                    }),
                  ),
                ],
              ),
            );
          },
        ),
      ),
    );
  }
}

// ──────────────────────────────────────────────────────────────────────────
// アプリ内ビューア — モバイル フルスクリーン版
// ──────────────────────────────────────────────────────────────────────────
class _InAppViewerPage extends StatefulWidget {
  final String url;
  final bool isPdf;
  final String? nodeId;

  /// 現在の URL を画面分割パネルに移して表示するコールバック。
  final void Function(String currentUrl, {bool isLeftPanel})?
      onMoveToSplitPanel;

  /// PDF から AI で一問一答クイズを生成するコールバック。
  final void Function(String pdfPathOrUrl)? onGenerateQuiz;

  /// メモを AI に質問するコールバック (= ユーザー要望: モバイルのメモにも
  /// AI ボタンを搭載)。 API 経由で回答をマップ/メモに書き戻す。
  final void Function(PdfMemo memo)? onAskAiMemo;

  /// ファイル本体を書き換えた時に呼ぶ (= 手書きの焼き込み等)。
  /// マップ側でサムネイルを作り直すために使う (= ユーザー報告)。
  final VoidCallback? onSavedToFile;

  /// 全画面表示の初期再生速度 (= 画面分割から引き継ぐ。 ユーザー要望)。
  final double initialRate;
  const _InAppViewerPage({
    required this.url,
    required this.isPdf,
    this.nodeId,
    this.onMoveToSplitPanel,
    this.onGenerateQuiz,
    this.onAskAiMemo,
    this.onSavedToFile,
    this.initialRate = 1.0,
  });

  @override
  State<_InAppViewerPage> createState() => _InAppViewerPageState();
}

class _InAppViewerPageState extends State<_InAppViewerPage>
    with TickerProviderStateMixin {
  iaw.InAppWebViewController? _ctrl;
  sf_pdf.PdfViewerController? _pdfViewerCtrl;
  String? _pdfFilePath;
  String? _pdfError;
  int _pdfTotalPages = 0;
  String _title = '';
  int _currentPage = 1;

  /// PDF 図形・線 描き込みモード (= ユーザー要望)。
  bool _pdfDrawActive = false;

  /// 描き込みの道具箱をヘッダーの下に出すための受け口
  /// (= ユーザー要望: PDF の上部が道具箱と被って描けない)。
  final ValueNotifier<Widget?> _pdfDrawToolbar = ValueNotifier<Widget?>(null);

  /// ヘッダーの下に出す道具箱の帯 (モードの間だけ出る)。
  Widget _buildPdfDrawToolbarBar() {
    return ValueListenableBuilder<Widget?>(
      valueListenable: _pdfDrawToolbar,
      builder: (_, w, __) {
        if (w == null) return const SizedBox.shrink();
        return Container(
          width: double.infinity,
          color: const Color(0xFF17172A),
          padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 6),
          // 真ん中に置く (= ユーザー要望)。
          child: LayoutBuilder(
            builder: (_, cons) => SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              child: ConstrainedBox(
                constraints: BoxConstraints(minWidth: cons.maxWidth),
                child: Center(child: w),
              ),
            ),
          ),
        );
      },
    );
  }

  /// PDF への描き込み (ペン / 直線 / 矢印 / 四角 / 楕円) の ON/OFF。
  /// ヘッダーの常設ボタンと設定メニューの両方から呼ぶ。
  void _togglePdfDrawMode() {
    setState(() => _pdfDrawActive = !_pdfDrawActive);
    if (_pdfDrawActive && mounted) {
      _appSnack(
        context,
        SnackBar(
            content:
                Text(context.read<MindMapProvider>().t('pdfdraw.hint')),
            duration: const Duration(seconds: 3)),
      );
    }
  }

  /// 描き込み保存後にビューアを読み直すための鍵。
  int _pdfDrawReloadTick = 0;

  // ─── 音声読み上げ (TTS) (= ユーザー要望: PDF の音声読み上げ) ───
  ReadAloudController? _reader;
  bool _readerVisible = false;

  /// PDF 本文を抽出して現在ページから読み上げ開始する。
  Future<void> _startReadAloud() async {
    final path = _pdfFilePath;
    final provider = context.read<MindMapProvider>();
    final messenger = ScaffoldMessenger.maybeOf(context);
    if (path == null || !File(path).existsSync()) {
      messenger?.showSnackBar(SnackBar(
          content: Text(provider.t('pdf.noReadablePdf')),
          duration: const Duration(seconds: 2)));
      return;
    }
    // ── 開始ページを指定 (= ユーザー要望)。 既定は今見ているページ (動的割当) ──
    final total = (_pdfTotalPages > 0) ? _pdfTotalPages : null;
    final defStart = (_currentPage >= 1) ? _currentPage : 1;
    final start = await _askReadAloudStartPage(context, defStart, total);
    if (start == null || !mounted) return; // キャンセル
    messenger?.showSnackBar(SnackBar(
        content: Text(provider.t('pdf.loadingText')),
        duration: const Duration(seconds: 1)));
    final loc = provider.speechLocaleId;
    _reader ??= ReadAloudController(language: loc);
    // ページ追従リスナを一度だけ張る (= 読み上げページと表示ページを一致させる)。
    _reader!.removeListener(_followReaderPage);
    _reader!.addListener(_followReaderPage);
    _lastFollowedPage = -1;
    if (total != null) {
      // ── ページ毎に抽出してチャンクへページ番号を割り当て、 読み上げの進行に
      //    合わせて表示ページを追従させる (= ユーザー要望: 一致させる) ──
      final perPage = await _extractPdfPerPage(path, start, total, strip: true);
      if (!mounted) return;
      if (perPage == null || perPage.every((t) => t.trim().isEmpty)) {
        messenger?.showSnackBar(SnackBar(
            content: Text(provider.t('pdf.noTextExtract')),
            duration: const Duration(seconds: 3)));
        return;
      }
      final chunks = <String>[];
      final pages = <int>[];
      for (int k = 0; k < perPage.length; k++) {
        final pageNo = start + k;
        for (final c in ReadAloudController.chunkText(perPage[k])) {
          chunks.add(c);
          pages.add(pageNo);
        }
      }
      if (chunks.isEmpty) {
        messenger?.showSnackBar(SnackBar(
            content: Text(provider.t('pdf.noTextExtract')),
            duration: const Duration(seconds: 3)));
        return;
      }
      setState(() => _readerVisible = true);
      final ok = await _reader!
          .startChunks(chunks, pages: pages, sampleText: chunks.first);
      if (!mounted) return;
      if (!ok) {
        setState(() => _readerVisible = false);
        messenger?.showSnackBar(SnackBar(
            content: Text(provider.t('pdf.ttsUnavailable')),
            duration: const Duration(seconds: 3)));
      }
      return;
    }
    // フォールバック: ページ数不明なら従来どおり全文を一括読み上げ (追従なし)。
    final text = await _extractPdfTextForAi(path, stripBoilerplate: true);
    if (!mounted) return;
    if (text == null || text.trim().isEmpty) {
      messenger?.showSnackBar(SnackBar(
          content: Text(provider.t('pdf.noTextExtract')),
          duration: const Duration(seconds: 3)));
      return;
    }
    setState(() => _readerVisible = true);
    final ok = await _reader!.start(text);
    if (!mounted) return;
    if (!ok) {
      setState(() => _readerVisible = false);
      messenger?.showSnackBar(SnackBar(
          content: Text(provider.t('pdf.ttsUnavailable')),
          duration: const Duration(seconds: 3)));
    }
  }

  /// 読み上げ中チャンクの元ページへ PDF をジャンプし、 表示ページを読み上げ
  /// ページに一致させる (= ユーザー要望: 読み上げページと開いているページの一致)。
  int _lastFollowedPage = -1;
  void _followReaderPage() {
    if (!mounted) return;
    final p = _reader?.currentSourcePage;
    if (p == null || p == _lastFollowedPage) return;
    _lastFollowedPage = p;
    if (p >= 1 && _pdfTotalPages > 0 && p <= _pdfTotalPages) {
      try {
        _pdfViewerCtrl?.jumpToPage(p);
      } catch (_) {}
    }
  }

  void _stopReadAloud() {
    _reader?.removeListener(_followReaderPage);
    _reader?.stop();
    if (mounted) setState(() => _readerVisible = false);
  }

  // ── ページ全体表示 (フィット) モード = ユーザー要望 ──
  // syncfusion の最小ズーム (1.0 = ページ幅フィット) では縦長ページの全体が
  // 収まらないため、 現在ページのラスタ画像を BoxFit.contain で被せる。
  bool _fitPageMode = false;
  Uint8List? _fitPageImage;
  int _fitPageRenderedFor = -1;
  bool _fitPageRendering = false;
  // PDF バイト列はページめくりの度に読み直すと重いので一度だけ読んでキャッシュ
  //   する (= ユーザー報告: メモ/AI 欄が開くタイミングでフリーズ。 ラスタ処理の
  //   負荷を減らす一手)。
  Uint8List? _fitPageBytes;
  // 連続めくりで毎回ラスタすると処理が積み上がって落ちるので debounce する
  //   (= ユーザー報告: ページをめくると落ちる)。
  Timer? _fitPageDebounce;
  bool _spreadFitPageMode = false;
  final Map<int, printing.PdfRaster> _spreadPageImages =
      <int, printing.PdfRaster>{};
  final Map<int, Size> _spreadPageImageSizes = <int, Size>{};
  /// 見開きを開いた時の既定の拡大率 (= ユーザー要望: 拡大率が小さ過ぎる)。
  /// 1.0 = 画面に収まるまで縮小 (従来)。 はみ出した分はドラッグで見る。
  static const double _kSpreadInitialZoom = 1.35;

  final TransformationController _spreadTransformController =
      TransformationController();

  /// 見開きの倍率を既定へ戻す。
  /// InteractiveViewer は原点基準で拡大するため、 中心がずれないように
  /// 平行移動で打ち消す (= ユーザー要望: 見開きをもう少し大きく)。
  void _resetSpreadZoom() {
    const z = _kSpreadInitialZoom;
    if (z == 1.0) {
      _spreadTransformController.value = Matrix4.identity();
      return;
    }
    Size view;
    try {
      view = MediaQuery.of(context).size;
    } catch (_) {
      _spreadTransformController.value = Matrix4.identity();
      return;
    }
    _spreadTransformController.value = Matrix4.identity()
      ..setEntry(0, 0, z)
      ..setEntry(1, 1, z)
      ..setTranslationRaw(
          -(z - 1) * view.width / 2, -(z - 1) * view.height / 2, 0);
  }
  int _spreadRenderedForStart = -1;
  bool _spreadRendering = false;
  bool _spreadRenderPending = false;
  int _spreadRenderGeneration = 0;
  Timer? _spreadPageDebounce;
  static const Duration _spreadRasterTimeout = Duration(seconds: 18);
  static const int _spreadRasterMaxPixels = 8 * 1000 * 1000;

  /// ページ全体表示はライブの SfPdfViewer を縮小表示する。
  /// ラスタ画像の生成は AI WebView と競合してフリーズしやすいため使わない。
  void _scheduleFitPageRender() {
    _fitPageDebounce?.cancel();
  }

  Future<void> _renderFitPage() async {
    // フリーズ対策: raster 変換は使わず、SfPdfViewer の表示幅だけを変える。
  }

  void _toggleFitPage() {
    final keepPage = _currentPage;
    setState(() {
      _fitPageMode = !_fitPageMode;
      if (_fitPageMode) {
        _spreadFitPageMode = false;
        _fitPageBytes = null;
        _spreadPageImages.clear();
        _spreadPageImageSizes.clear();
        _spreadRenderedForStart = -1;
        _spreadRenderGeneration++;
        _spreadRenderPending = false;
        _resetSpreadZoom();
      }
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || _pdfViewerCtrl == null) return;
      try {
        _pdfViewerCtrl!.jumpToPage(keepPage);
      } catch (_) {}
    });
    // 既定として永続化 (= 次回以降の PDF 初期表示に反映)。
    context.read<MindMapProvider>().setPdfFitPageDefault(_fitPageMode);
  }

  Widget _buildFitPageOverlay() {
    return const SizedBox.shrink();
  }

  int get _spreadStartPage {
    if (_pdfTotalPages <= 1) return 1;
    final page = _currentPage.clamp(1, _pdfTotalPages).toInt();
    if (page <= 1) return 1;
    return page.isEven ? page : page - 1;
  }

  bool _canEnableSpreadRaster() {
    final path = _pdfFilePath;
    if (path != null && _isPdfSpreadRasterSourceSafe(path)) return true;
    final limitMb = _pdfSpreadRasterSourceLimitBytes ~/ (1024 * 1024);
    ScaffoldMessenger.maybeOf(context)?.showSnackBar(
      SnackBar(
        content: Text(
          'このPDFはサイズが大きいため、安定性を優先して見開き画像表示を無効にしました（上限 ${limitMb}MB）。',
        ),
        duration: const Duration(seconds: 4),
      ),
    );
    return false;
  }

  void _adjustSpreadZoom(bool zoomIn) {
    final current =
        _spreadTransformController.value.getMaxScaleOnAxis().clamp(0.5, 6.0);
    final next = (current + (zoomIn ? 0.1 : -0.1)).clamp(0.5, 6.0);
    _spreadTransformController.value = Matrix4.identity()
      ..setEntry(0, 0, next)
      ..setEntry(1, 1, next);
  }

  void _scheduleSpreadPageRender(
      [Duration delay = const Duration(milliseconds: 320)]) {
    _spreadPageDebounce?.cancel();
    if (!_spreadFitPageMode) return;
    // 実行中の raster と次要求を並列化しない。連続ページ送りは最後の要求へ
    // 畳み込み、完了後に 1 回だけ再実行する。
    if (_spreadRendering) {
      _spreadRenderPending = true;
      return;
    }
    _spreadPageDebounce = Timer(delay, () {
      if (mounted && _spreadFitPageMode) _renderSpreadPages();
    });
  }

  /// 指定ページ群のうち未キャッシュのものをラスタしてキャッシュへ足す
  /// (デスクトップ版と同じ、 追加型キャッシュ + 先読み方式。 ユーザー要望
  /// 2026-07: 見開きモードが重い/フリーズする問題への対応)。
  Future<bool> _rasterSpreadPagesInto(List<int> pages,
      {bool prefetch = false}) async {
    final path = _pdfFilePath;
    if (path == null) return false;
    final need = <int>[
      for (final p in pages)
        if (p >= 1 &&
            (_pdfTotalPages <= 0 || p <= _pdfTotalPages) &&
            !_spreadPageImages.containsKey(p))
          p
    ];
    if (need.isEmpty) return true;
    final requestedStart = pages.first;
    if (_spreadRendering) {
      if (!prefetch) _spreadRenderPending = true;
      return false;
    }
    _spreadRendering = true;
    final generation = _spreadRenderGeneration;
    try {
      if (!_isPdfSpreadRasterSourceSafe(path)) {
        throw StateError('PDF is too large for safe spread rasterization');
      }
      // PDF バイトは raster 呼び出し中だけ保持する。SfPdfViewer と Dart と
      // プラットフォーム側で同じ文書を三重保持し続けるのを防ぐ。
      final pdfBytes = await File(path).readAsBytes();
      if (!mounted ||
          !_spreadFitPageMode ||
          generation != _spreadRenderGeneration ||
          (!prefetch && _spreadStartPage != requestedStart)) {
        return false;
      }
      final rasterDpi =
          (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) ? 56.0 : 64.0;
      // Windows の printing プラグインはネイティブ側で全指定ページを同期処理
      // するため、見開き2ページを別ジョブに分割する。各ページの間でFlutterへ
      // 制御を戻し、モード解除・ページ変更の世代を再確認する。
      for (var i = 0; i < need.length; i++) {
        final n = need[i];
        printing.PdfRaster? page;
        await for (final raster in printing.Printing.raster(
          pdfBytes,
          pages: <int>[n - 1],
          dpi: rasterDpi,
        ).timeout(_spreadRasterTimeout)) {
          if (page != null) {
            throw StateError('PDF rasterizer returned duplicate page data');
          }
          page = raster;
        }
        if (page == null) {
          throw StateError('PDF rasterizer returned incomplete spread pages');
        }
        final pixelCount = page.width * page.height;
        if (pixelCount > _spreadRasterMaxPixels) {
          // 寸法はRGBA生成後に返るAPIなので、追加のui.Image確保前に打ち切る。
          throw StateError('PDF page is too large for safe spread rendering');
        }
        if (!mounted ||
            !_spreadFitPageMode ||
            generation != _spreadRenderGeneration ||
            (!prefetch && _spreadStartPage != requestedStart)) {
          return false;
        }
        // PNG への再エンコードを挟まず、raster の RGBA 画像を直接表示する。
        _spreadPageImages[n] = page;
        _spreadPageImageSizes[n] =
            Size(page.width.toDouble(), page.height.toDouble());
        if (i + 1 < need.length) {
          await WidgetsBinding.instance.endOfFrame;
          if (!mounted ||
              !_spreadFitPageMode ||
              generation != _spreadRenderGeneration ||
              (!prefetch && _spreadStartPage != requestedStart)) {
            return false;
          }
        }
      }
      // デコード済み画像を含むピークメモリを一定にするため、現在の見開きだけを
      // 保持する。端末の画像キャッシュと合わせても最大 2 ページ相当に抑える。
      final keep = pages.toSet();
      for (final cached in _spreadPageImages.keys.toList()) {
        if (keep.contains(cached)) continue;
        _spreadPageImages.remove(cached);
        _spreadPageImageSizes.remove(cached);
      }
      return true;
    } catch (e) {
      debugPrint('見開き全体表示の生成失敗: $e');
      if (!prefetch &&
          mounted &&
          _spreadFitPageMode &&
          generation == _spreadRenderGeneration) {
        setState(() {
          _spreadFitPageMode = false;
          _fitPageBytes = null;
          _spreadPageImages.clear();
          _spreadPageImageSizes.clear();
          _spreadRenderedForStart = -1;
          _resetSpreadZoom();
        });
        _appSnack(
          context,
          SnackBar(
            content: Text(context.read<MindMapProvider>().t('pdf.pageImageFallback')),
            duration: const Duration(seconds: 4),
          ),
        );
      }
      return false;
    } finally {
      _spreadRendering = false;
      // 先読み中に入ったページ送り要求も、先読み完了後に必ず処理する。
      if (mounted && _spreadFitPageMode && _spreadRenderPending) {
        _spreadRenderPending = false;
        _scheduleSpreadPageRender();
      }
    }
  }

  Future<void> _renderSpreadPages() async {
    if (!_spreadFitPageMode) return;
    final start = _spreadStartPage;
    final pages = <int>[start];
    if (start > 1 && start + 1 <= _pdfTotalPages) pages.add(start + 1);
    final ok = await _rasterSpreadPagesInto(pages);
    if (!mounted || !_spreadFitPageMode) return;
    if (!ok || _spreadStartPage != start) return;
    setState(() => _spreadRenderedForStart = start);
  }

  void _toggleSpreadPages() {
    final enabling = !_spreadFitPageMode;
    if (enabling && !_canEnableSpreadRaster()) return;
    setState(() {
      _spreadFitPageMode = enabling;
      _spreadRenderGeneration++;
      _spreadRenderPending = false;
      if (_spreadFitPageMode) {
        _fitPageMode = false;
        _spreadRenderedForStart = -1;
      } else {
        _fitPageBytes = null;
        _spreadPageImages.clear();
        _spreadPageImageSizes.clear();
        _spreadRenderedForStart = -1;
        _resetSpreadZoom();
      }
    });
    if (_spreadFitPageMode) {
      // このフレームで SfPdfViewer を描画ツリーから外してから raster を開始する。
      // 同じ PDF の二重解析・二重描画が重ならないよう、解放用の猶予も設ける。
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _scheduleSpreadPageRender(const Duration(milliseconds: 480));
      });
    } else {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        try {
          _pdfViewerCtrl?.jumpToPage(_currentPage);
        } catch (_) {}
      });
    }
  }

  void _jumpSpreadPages(int delta) {
    if (_pdfTotalPages <= 0) return;
    final target = (_spreadStartPage + delta).clamp(1, _pdfTotalPages).toInt();
    _spreadPageDebounce?.cancel();
    setState(() {
      _currentPage = target;
      _spreadRenderedForStart = -1;
    });
    if (_pdfFilePath != null) {
      context.read<MindMapProvider>().setLastPdfPage(_pdfFilePath!, target);
    }
    _scheduleSpreadPageRender();
  }

  Widget _buildSpreadPageImage(int pageNumber) {
    final pageSize = _spreadPageImageSizes[pageNumber] ?? const Size(794, 1123);
    return SizedBox(
      width: pageSize.width,
      height: pageSize.height,
      child: Image(
        image: printing.PdfRasterImage(_spreadPageImages[pageNumber]!),
        fit: BoxFit.fill,
        gaplessPlayback: false,
        filterQuality: FilterQuality.low,
      ),
    );
  }

  Widget _buildSpreadPageOverlay() {
    if (!_spreadFitPageMode) return const SizedBox.shrink();
    final start = _spreadStartPage;
    final pages = <int>[start];
    if (start > 1 && start + 1 <= _pdfTotalPages) pages.add(start + 1);
    // キャッシュにあれば即表示 (= 先読み済みの見開きは「準備中」を出さない)。
    final ready = pages.every((page) => _spreadPageImages.containsKey(page));
    final pageLabel = pages.length == 1
        ? '$start / $_pdfTotalPages'
        : '$start-${pages.last} / $_pdfTotalPages';
    return Positioned.fill(
      child: Container(
        color: Colors.white,
        // ── 見開きは画面いっぱいに使う (= ユーザー要望: 見開きモードだと
        //    画面が小さくなり過ぎる)。 余白は最小限に。 ──
        padding: const EdgeInsets.symmetric(horizontal: 2, vertical: 2),
        child: Stack(
          children: [
            Positioned.fill(
              child: ready
                  ? InteractiveViewer(
                      transformationController: _spreadTransformController,
                      minScale: 0.5,
                      maxScale: 6.0,
                      child: Center(
                        child: FittedBox(
                          fit: BoxFit.contain,
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            crossAxisAlignment: CrossAxisAlignment.center,
                            children: [
                              for (int i = 0; i < pages.length; i++) ...[
                                _buildSpreadPageImage(pages[i]),
                                if (i != pages.length - 1)
                                  const SizedBox(width: 4),
                              ],
                            ],
                          ),
                        ),
                      ),
                    )
                  : const Center(
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          CircularProgressIndicator(strokeWidth: 2),
                          SizedBox(height: 12),
                          Text(
                            '見開きモードを準備中...',
                            style:
                                TextStyle(color: Colors.black54, fontSize: 13),
                          ),
                        ],
                      ),
                    ),
            ),
            Positioned(
              left: 12,
              top: 12,
              child: Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                decoration: BoxDecoration(
                  color: Colors.black.withValues(alpha: 0.55),
                  borderRadius: BorderRadius.circular(18),
                ),
                child: Text(
                  '見開き全体 $pageLabel',
                  style: const TextStyle(color: Colors.white70, fontSize: 12),
                ),
              ),
            ),
            Positioned(
              left: 10,
              top: 0,
              bottom: 0,
              child: Center(
                child: IconButton.filledTonal(
                  tooltip: context.read<MindMapProvider>().t('pdf.prevSpread'),
                  onPressed: start <= 1 ? null : () => _jumpSpreadPages(-2),
                  icon: const Icon(Icons.chevron_left_rounded),
                ),
              ),
            ),
            Positioned(
              right: 10,
              top: 0,
              bottom: 0,
              child: Center(
                child: IconButton.filledTonal(
                  tooltip: context.read<MindMapProvider>().t('pdf.nextSpread'),
                  onPressed: start >= _pdfTotalPages
                      ? null
                      : () => _jumpSpreadPages(2),
                  icon: const Icon(Icons.chevron_right_rounded),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  double _pdfLiveWidthFactor(BoxConstraints constraints) {
    if (!_fitPageMode && !_spreadFitPageMode) {
      return (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) ? 1.0 : 0.65;
    }
    final width = constraints.maxWidth;
    final height = constraints.maxHeight;
    if (!width.isFinite || !height.isFinite || width <= 0 || height <= 0) {
      return (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) ? 0.62 : 0.46;
    }
    const a4HeightOverWidth = 1.41421356237;
    return (height / (width * a4HeightOverWidth) * 0.96)
        .clamp(0.28, 1.0)
        .toDouble();
  }

  late String _currentUrl;
  bool _placingMemo = false;
  String? _highlightMemoId;
  late final AnimationController _pulseCtrl;

  /// 現在の Y スクロール位置。 onScrollChanged でリアルタイム更新。
  double _currentScrollY = 0;

  /// 動画の再生速度 (モバイル全画面ビューア)。
  double _videoPlaybackRate = 1.0;
  bool _webHasVideo = false;

  bool _isVideoSiteUrlMobile(String url) {
    return _isLikelyEmbeddedVideoUrl(url);
  }

  Future<void> _applyMobileVideoRate(double rate) async {
    final js = webVideoRateJs(rate);
    try {
      if (_ctrl != null) {
        await _ctrl!.evaluateJavascript(source: js);
      }
    } catch (_) {}
  }

  Future<void> _probeMobileVideoPresence() async {
    if (!mounted || widget.isPdf || _ctrl == null) return;
    dynamic result;
    try {
      result = await _ctrl!.evaluateJavascript(source: _webVideoPresenceJs());
    } catch (_) {
      return;
    }
    final hasVideo = _webJsTruthy(result);
    if (mounted && hasVideo != _webHasVideo) {
      setState(() => _webHasVideo = hasVideo);
    }
  }

  void _scheduleMobileVideoProbe() {
    for (final ms in const [250, 1200, 3000]) {
      Future.delayed(Duration(milliseconds: ms), () {
        if (mounted) _probeMobileVideoPresence();
      });
    }
  }

  Widget _buildMobileVideoSpeedBar() {
    // 通常画面・画面分割と共通の最大倍率 (= 設定で変更可能、 既定 5.0)。
    // ユーザー要望: 全画面表示に戻すと 2 倍までしか出せないのを解消。
    final maxRate =
        context.watch<MindMapProvider>().videoMaxRate.clamp(1.5, 16.0);
    final List<double> rawPresets;
    if (maxRate <= 2.0 + 0.01) {
      rawPresets = [0.5, 1.0, 1.5, 2.0];
    } else if (maxRate <= 4.0 + 0.01) {
      rawPresets = [1.0, 1.5, 2.0, 3.0, maxRate];
    } else if (maxRate <= 8.0 + 0.01) {
      rawPresets = [1.0, 2.0, 4.0, maxRate];
    } else {
      rawPresets = [1.0, 2.0, 4.0, 8.0, maxRate];
    }
    final presetSet = <double>{};
    for (final p in rawPresets) {
      presetSet.add(double.parse(p.toStringAsFixed(2)));
    }
    final presets = presetSet.toList()..sort();
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: Colors.black.withValues(alpha: 0.75),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: Colors.white12),
      ),
      child: Row(
        children: [
          const Icon(Icons.speed_rounded, color: Color(0xFF6C63FF), size: 18),
          const SizedBox(width: 6),
          Text(
            '${_videoPlaybackRate.toStringAsFixed(2)}x',
            style: const TextStyle(
              color: Colors.white,
              fontSize: 12,
              fontWeight: FontWeight.w700,
              fontFeatures: [FontFeature.tabularFigures()],
            ),
          ),
          const SizedBox(width: 4),
          Expanded(
            child: SliderTheme(
              data: SliderTheme.of(context).copyWith(
                trackHeight: 3,
                thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 7),
                overlayShape: const RoundSliderOverlayShape(overlayRadius: 14),
                activeTrackColor: const Color(0xFF6C63FF),
                inactiveTrackColor: Colors.white24,
                thumbColor: const Color(0xFF6C63FF),
                overlayColor: const Color(0xFF6C63FF).withValues(alpha: 0.3),
              ),
              child: Slider(
                value: _videoPlaybackRate.clamp(0.25, maxRate),
                min: 0.25,
                max: maxRate,
                divisions: ((maxRate - 0.25) * 4).round().clamp(10, 200),
                onChanged: (v) {
                  setState(() => _videoPlaybackRate = v);
                  _applyMobileVideoRate(v);
                },
              ),
            ),
          ),
          for (final preset in presets)
            Padding(
              padding: const EdgeInsets.only(left: 4),
              child: InkWell(
                borderRadius: BorderRadius.circular(4),
                onTap: () {
                  setState(() => _videoPlaybackRate = preset);
                  _applyMobileVideoRate(preset);
                },
                child: Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
                  decoration: BoxDecoration(
                    color: (_videoPlaybackRate - preset).abs() < 0.01
                        ? const Color(0xFF6C63FF).withValues(alpha: 0.25)
                        : Colors.transparent,
                    borderRadius: BorderRadius.circular(4),
                    border: Border.all(
                      color: (_videoPlaybackRate - preset).abs() < 0.01
                          ? const Color(0xFF6C63FF)
                          : Colors.white24,
                      width: 0.5,
                    ),
                  ),
                  child: Text(
                    '${preset.toStringAsFixed(preset == preset.truncateToDouble() ? 0 : 1)}x',
                    style: TextStyle(
                      color: (_videoPlaybackRate - preset).abs() < 0.01
                          ? const Color(0xFF6C63FF)
                          : Colors.white70,
                      fontSize: 11,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }

  // ─── ページ番号ジャンプ + 検索 (Dialog 版と同じ) ──
  late final TextEditingController _pageInputCtrl;
  late final TextEditingController _searchCtrl;
  bool _searchBarOpen = false;
  sf_pdf.PdfTextSearchResult? _searchResult;
  // ─── URL モードの Find in Page (検索) ──
  int _urlActiveMatch = 0;
  int _urlMatchCount = 0;
  String _lastSearchQuery = '';

  /// PDF キーボード操作用 FocusNode (Bluetooth キーボード接続時の ↑↓ 用)
  late final FocusNode _pdfFocusNode;

  /// 現在 PDF ビューア内で選択中のテキスト。 null または空文字なら未選択。
  /// `onTextSelectionChanged` で更新され、 ハイライト追加ボタンの表示制御に使う。
  String? _selectedPdfText;

  /// 選択中テキストの行ごとの bounds (= List<PdfTextLine> 相当)。
  /// 新しめの syncfusion では `PdfTextSelectionChangedDetails.selectedTextLines`
  /// として渡ってくるが、 古いバージョンにはこのプロパティが無いため `dynamic` で
  /// 受けて存在チェック付きで使う。 HighlightAnnotation に渡す素材。
  dynamic _selectedPdfLines;

  /// 現在選択中のマーカー色。 null = マーカーモード OFF (マーカー追加 FAB は出ない)。
  /// non-null = マーカーモード ON で、 テキスト選択中に FAB が出てこの色で
  /// HighlightAnnotation が追加される。 ツールバーのマーカーボタンから切替可能。
  Color? _activeMarkerColor;

  /// 今セッションで追加したマーカーの ID 集合。 PDF を閉じるときに
  /// 「破棄して閉じる」 を選ばれた場合、 この集合の ID を provider から削除する。
  /// auto-save 直後に追加するので、 アプリ再起動された場合は既に保存済み扱い
  /// (= rollback 不能) で問題なし。
  final Set<String> _sessionAddedHighlightIds = {};

  /// マーカーモード ON 中の自動適用デバウンス用タイマ。 テキスト選択中に
  /// `onTextSelectionChanged` が連続で発火するため、 「選択が安定して N ms
  /// 経った」 ら適用する設計。 範囲ドラッグ中の中間状態で適用されるのを防ぐ。
  Timer? _highlightAutoTimer;

  /// 直近で auto-apply したテキスト (重複適用ガード)。 同じ選択を 2 度自動
  /// ハイライトしないために覚えておく。
  String? _lastAutoAppliedText;

  /// 自分で `addAnnotation` を呼ぶとき、 syncfusion の `onAnnotationAdded`
  /// コールバックが回って二重保存になるのを防ぐためのガードフラグ。
  /// `_addHighlightForSelection` / `_restoreSavedHighlights` 中だけ true。
  bool _suppressAnnotationCallback = false;

  /// ←/→ や PageUp/Down 等の単発ページ操作の overshoot 抑止 (キー単位ロック)。
  /// KeyDown でロック (timestamp) を入れ、 KeyUp で解除する。 ロック中の
  /// 同キーの追加 KeyDown は無視され、 1 押下 = 1 アクションが保証される。
  /// KeyUp が届かなかった場合のセーフティとして 2 秒で自動解除。
  final Map<LogicalKeyboardKey, DateTime> _heldPageActionKeyAt = {};
  static const Duration _heldPageActionTimeout = Duration(seconds: 2);

  @override
  void initState() {
    super.initState();
    _currentUrl = widget.url;
    // 画面分割から引き継いだ再生速度を初期値に (ユーザー要望)。
    _videoPlaybackRate = widget.initialRate;
    _pulseCtrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 2400),
    );
    _pageInputCtrl = TextEditingController();
    _searchCtrl = TextEditingController();
    _pdfFocusNode = FocusNode(debugLabel: 'pdf_viewer_page');
    if (widget.isPdf) {
      _initPdf();
      // SfPdfViewer は内部 focus 競合があるので、 グローバルに ↑↓ を捕捉
      HardwareKeyboard.instance.addHandler(_globalPdfKeyHandler);
    }
  }

  String? _resolveLocalPdfPath() {
    String u = widget.url;
    final qi = u.indexOf('?');
    if (qi >= 0) u = u.substring(0, qi);
    final hi = u.indexOf('#');
    if (hi >= 0) u = u.substring(0, hi);
    if (u.startsWith('file://')) {
      try {
        return Uri.parse(u).toFilePath(windows: Platform.isWindows);
      } catch (_) {
        return null;
      }
    }
    if (!u.contains('://')) return u;
    return null;
  }

  void _initPdf() {
    final path = _resolveLocalPdfPath();
    if (path == null) {
      setState(() => _pdfError = 'PDF パスを解決できませんでした');
      return;
    }
    final file = File(path);
    if (!file.existsSync()) {
      setState(() => _pdfError = 'ファイルが見つかりません: $path');
      return;
    }
    final fname = path.split(Platform.isWindows ? '\\' : '/').last;
    // 開いている間は控えておく (= 同じファイルを他の処理が同時に触って
    // 落ちるのを避ける。 ユーザー報告: 手書き保存の直後に落ちる)。
    kOpenPdfPaths.add(path);
    setState(() {
      _pdfFilePath = path;
      _pdfViewerCtrl = sf_pdf.PdfViewerController();
      if (_title.isEmpty) _title = fname;
    });
    _viewerMark('initPdf done');
  }

  @override
  void dispose() {
    // 開いていた PDF の控えを外す (= 他の処理が触ってよくなる)。
    final op = _pdfFilePath;
    if (op != null) kOpenPdfPaths.remove(op);
    if (widget.isPdf) {
      HardwareKeyboard.instance.removeHandler(_globalPdfKeyHandler);
    }
    _pulseCtrl.dispose();
    _pdfViewerCtrl?.dispose();
    _pageInputCtrl.dispose();
    _searchCtrl.dispose();
    _pdfFocusNode.dispose();
    _searchResult?.removeListener(_onSearchUpdated);
    _searchResult?.clear();
    _highlightAutoTimer?.cancel();
    _fitPageDebounce?.cancel();
    _spreadPageDebounce?.cancel();
    _spreadRenderGeneration++;
    _fitPageBytes = null;
    _spreadPageImages.clear();
    _spreadPageImageSizes.clear();
    _spreadTransformController.dispose();
    // 音声読み上げを停止・破棄 (= ユーザー要望)。
    _reader?.dispose();
    super.dispose();
  }

  /// PDF キー操作 (Dialog 版と同じ。 Bluetooth キーボード等接続時に有効)
  /// - ↑/↓: scrollOffset を 1/N ページ分ずつずらす細かいスクロール
  /// - ←/→ / PageUp/PageDown: 即時 1 ページ送り
  /// - Home / End: 先頭 / 末尾ページへジャンプ
  /// - M: メモ配置モードのトグル (メモ機能が利用可能なときのみ)
  KeyEventResult _onPdfKeyEvent(FocusNode node, KeyEvent event) {
    // KeyUp はロック解除のためだけにハンドル (Dialog 版と同じ)
    if (event is KeyUpEvent) {
      _heldPageActionKeyAt.remove(event.logicalKey);
      return KeyEventResult.ignored;
    }
    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
      return KeyEventResult.ignored;
    }
    if (_pdfViewerCtrl == null || _pdfTotalPages <= 0) {
      return KeyEventResult.ignored;
    }
    final key = event.logicalKey;

    // ── Ctrl+\ / Ctrl+^: フルスクリーン PDF を閉じて画面分割に切替 ──
    // (NodePdfView 版)
    final isCtrlForSplit = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    final isShiftForSplit = HardwareKeyboard.instance.isShiftPressed;
    if (isCtrlForSplit && _pdfFilePath != null) {
      final isSplitRight =
          !isShiftForSplit && key == LogicalKeyboardKey.backslash;
      final isSplitLeft = key == LogicalKeyboardKey.caret ||
          event.physicalKey == PhysicalKeyboardKey.equal ||
          (event.character ?? '') == '^' ||
          (isShiftForSplit &&
              (key == LogicalKeyboardKey.digit6 ||
                  key == LogicalKeyboardKey.numpad6));
      if (isSplitRight || isSplitLeft) {
        final cb = widget.onMoveToSplitPanel;
        if (cb != null) {
          try {
            cb(_pdfFilePath!, isLeftPanel: isSplitLeft);
          } catch (e) {
            debugPrint('画面分割への切替失敗: $e');
          }
        }
        try {
          Navigator.of(context).pop();
        } catch (_) {}
        return KeyEventResult.handled;
      }
    }

    // ── Ctrl+ / Ctrl- : PDF ズームレベル調整 (NodePdfView 版) ──
    // ユーザー要望: 「ctrl+ \"+\" or \"-\" で閲覧している PDF の拡大率を調整
    // できるようにして」。 syncfusion の zoomLevel は 1.0〜maxZoomLevel (4.0)。
    final isCtrl = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    if (isCtrl) {
      final isZoomIn = key == LogicalKeyboardKey.equal ||
          key == LogicalKeyboardKey.add ||
          key == LogicalKeyboardKey.numpadAdd;
      final isZoomOut = key == LogicalKeyboardKey.minus ||
          key == LogicalKeyboardKey.numpadSubtract;
      if (isZoomIn || isZoomOut) {
        if (_spreadFitPageMode) {
          _adjustSpreadZoom(isZoomIn);
          return KeyEventResult.handled;
        }
        try {
          final current = _pdfViewerCtrl!.zoomLevel;
          // ステップを 0.1 に小さくして微調整できるように (= ユーザー要望)。
          // ステップを 0.05 に細かくし、 上限も 8.0 まで広げる
          // (= ユーザー要望: 拡大率をもっと微調整できるように)。
          // Shift を押している間はさらに細かく 0.02 刻み。
          final fine = HardwareKeyboard.instance.isShiftPressed;
          final step = fine ? 0.02 : 0.05;
          final delta = isZoomIn ? step : -step;
          final next = (current + delta).clamp(1.0, 8.0);
          _pdfViewerCtrl!.zoomLevel = next;
        } catch (e) {
          debugPrint('PDF zoom 調整失敗: $e');
        }
        return KeyEventResult.handled;
      }
    }
    // ── ↑/↓: 1/N ページ分の sub-page スクロール (= 以前の挙動を復元) ──
    // ユーザー要望: 「以前の様な ↑↓ で 1/20 ページずつ動く」 挙動に戻す。
    // continuous モードなので、 scrollOffset を直接操作することで
    // ページ境界も跨いで滑らかに移動する。 N は pdfArrowStepDivisor 設定値。
    if (key == LogicalKeyboardKey.arrowDown ||
        key == LogicalKeyboardKey.arrowUp) {
      // 横読み (左右) の時は上下キーでページ移動 / スクロールしない
      //   (= ユーザー要望)。 ページ送りは左右キーで行う。
      if (context.read<MindMapProvider>().pdfScrollHorizontal) {
        return KeyEventResult.handled;
      }
      try {
        final dir = key == LogicalKeyboardKey.arrowDown ? 1 : -1;
        // 1 ページの 1/N (= デフォルト 1/20) スクロール量を計算
        final provider = context.read<MindMapProvider>();
        final divisor = provider.pdfArrowStepDivisor.clamp(1, 100);
        // 現在表示中の 1 ページの高さを近似 (= ビューポート高さの 1.4 倍程度)
        final viewportH = MediaQuery.of(context).size.height;
        final estimatedPageH = viewportH > 0 ? viewportH * 1.0 : 800.0;
        final step = estimatedPageH / divisor;
        final cur = _pdfViewerCtrl!.scrollOffset;
        _pdfViewerCtrl!.jumpTo(
          xOffset: cur.dx,
          yOffset: cur.dy + step * dir,
        );
      } catch (_) {}
      return KeyEventResult.handled;
    }
    // ── ここから下は単発キー (1 押下 = 1 アクション) ──
    // KeyRepeat は無視。 KeyDown もキー単位ロックで「押しっぱなし中の追加発火」
    // と「OS/ドライバ起因の二重発火」 を全部潰す。
    if (event is KeyRepeatEvent) {
      return KeyEventResult.handled;
    }
    // ←/→ は syncfusion 自身が組み込みで 1 ページずつ処理する。
    // 自前で nextPage/previousPage を呼ぶと 2 重発火 (= 1 押下で 2 ページ進む)
    // になるので、 ここでは何もせず ignored を返して syncfusion 側に処理を譲る。
    // (= ユーザー要望「1 押下 = 1 ページ進む」 を確実にする)
    if (key == LogicalKeyboardKey.arrowRight ||
        key == LogicalKeyboardKey.arrowLeft) {
      if (_spreadFitPageMode) {
        _jumpSpreadPages(key == LogicalKeyboardKey.arrowRight ? 2 : -2);
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    }
    final isSingleShotKey = key == LogicalKeyboardKey.pageDown ||
        key == LogicalKeyboardKey.pageUp ||
        key == LogicalKeyboardKey.home ||
        key == LogicalKeyboardKey.end;
    if (isSingleShotKey) {
      final lockedAt = _heldPageActionKeyAt[key];
      if (lockedAt != null &&
          DateTime.now().difference(lockedAt) < _heldPageActionTimeout) {
        return KeyEventResult.handled;
      }
      _heldPageActionKeyAt[key] = DateTime.now();
    }
    // ── PageUp/PageDown: 1 ページ単位のページめくり ──
    if (key == LogicalKeyboardKey.pageDown) {
      if (_spreadFitPageMode) {
        _jumpSpreadPages(2);
        return KeyEventResult.handled;
      }
      try {
        _pdfViewerCtrl!.nextPage();
      } catch (_) {}
      return KeyEventResult.handled;
    } else if (key == LogicalKeyboardKey.pageUp) {
      if (_spreadFitPageMode) {
        _jumpSpreadPages(-2);
        return KeyEventResult.handled;
      }
      try {
        _pdfViewerCtrl!.previousPage();
      } catch (_) {}
      return KeyEventResult.handled;
    }
    // ── テキスト編集中は単キーショートカット (M/B/N) を無効化 ──
    // (= ユーザー要望: メモ編集中に半角の n/N で新規メモが立ち上がるのを防ぐ)
    final editingTextField =
        FocusManager.instance.primaryFocus?.context?.widget is EditableText;
    // インライン編集中も (フォーカスが TextField から外れていても) ガード
    final inlineEditing = _pdfMemoInlineEditing.value;
    if ((editingTextField || inlineEditing) &&
        (key == LogicalKeyboardKey.keyM ||
            key == LogicalKeyboardKey.keyB ||
            key == LogicalKeyboardKey.keyN)) {
      return KeyEventResult.ignored;
    }
    if (key == LogicalKeyboardKey.home) {
      try {
        _pdfViewerCtrl!.firstPage();
      } catch (_) {}
      return KeyEventResult.handled;
    } else if (key == LogicalKeyboardKey.end) {
      try {
        _pdfViewerCtrl!.lastPage();
      } catch (_) {}
      return KeyEventResult.handled;
    } else if (key == LogicalKeyboardKey.keyM) {
      // ── M: メモ配置モードのトグル (メモ機能が有効なときだけ) ──
      // KeyDown の最初の 1 回だけ反応 (押しっぱなしでも連発しない)
      if (event is KeyDownEvent && widget.nodeId != null) {
        setState(() => _placingMemo = !_placingMemo);
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    } else if (key == LogicalKeyboardKey.keyB) {
      // ── B: メモシート (ボトムシート) を開く ──
      // (外部キーボード接続したモバイル端末用; ソフトキーボードでは押せない)
      if (event is KeyDownEvent && widget.nodeId != null) {
        _showMemoSheet();
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    } else if (key == LogicalKeyboardKey.keyN) {
      // ── N: フリーメモ追加ダイアログ ──
      if (event is KeyDownEvent && widget.nodeId != null) {
        _openFreeMemoQuickDialog();
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    } else if (key == LogicalKeyboardKey.keyZ) {
      // ── Ctrl+Z (⌘+Z): Undo ──
      final hk = HardwareKeyboard.instance;
      final ctrlOrCmd =
          hk.isLogicalKeyPressed(LogicalKeyboardKey.controlLeft) ||
              hk.isLogicalKeyPressed(LogicalKeyboardKey.controlRight) ||
              hk.isLogicalKeyPressed(LogicalKeyboardKey.metaLeft) ||
              hk.isLogicalKeyPressed(LogicalKeyboardKey.metaRight);
      if (event is KeyDownEvent && ctrlOrCmd) {
        try {
          context.read<MindMapProvider>().undo();
        } catch (_) {}
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored;
    }
    return KeyEventResult.ignored;
  }

  /// フリーメモ追加ダイアログ (= N キーから呼ばれる)。
  Future<void> _openFreeMemoQuickDialog() async {
    final nid = widget.nodeId;
    if (nid == null) return;
    final provider = context.read<MindMapProvider>();
    final created = await showDialog<PdfMemo?>(
      context: context,
      builder: (_) => const _PdfMemoEditDialog(freeMode: true),
    );
    if (created != null) {
      provider.addPdfMemo(
        nid,
        text: created.text,
        pageNumber: created.pageNumber,
        colorValue: created.colorValue,
      );
    }
  }

  /// SfPdfViewer は内部のジェスチャ系ウィジェットがクリック時に focus を
  /// 奪うため、 Focus widget の onKeyEvent だけだとビューアを一度クリック
  /// した瞬間に ↑↓ が届かなくなる。 これを回避するため、 メインキャンバス
  /// と同じく HardwareKeyboard レベルでもグローバルに捕捉して
  /// `_onPdfKeyEvent` に転送する。 (Dialog 版と同じ実装)
  ///
  /// 譲る条件:
  ///   - PDF モードでない / ビューア未準備
  ///   - 別の route が前面 (このページより上にダイアログが乗ってる等)
  ///   - TextField が編集中 (検索バー / ページ番号入力欄など)
  bool _globalPdfKeyHandler(KeyEvent event) {
    if (!mounted) return false;
    if (event is! KeyDownEvent && event is! KeyRepeatEvent) return false;

    // ★ PDF の Focus がフォーカスを持っているなら Focus.onKeyEvent が
    //   既に処理するので、 HardwareKeyboard 経由の重複起動を防ぐ。
    if (_pdfFocusNode.hasFocus) return false;

    final route = ModalRoute.of(context);
    if (route == null || !route.isCurrent) return false;

    final focused = FocusManager.instance.primaryFocus;
    if (focused != null && focused.context?.widget is EditableText) {
      return false;
    }

    // ── ここから先は PDF 専用 (ページ送り等) ──
    if (!widget.isPdf) return false;
    if (_pdfViewerCtrl == null || _pdfTotalPages <= 0) return false;

    // ── メモパネルにキーボードフォーカスがある間は ↑/↓ をパネル専用に
    //    予約 (= ユーザー要望: メモ欄を上下キーで移動しているのに PDF
    //    まで動いてしまうバグの修正) ──
    if (_pdfMemoPanelHasKeyboardFocus.value &&
        (event.logicalKey == LogicalKeyboardKey.arrowUp ||
            event.logicalKey == LogicalKeyboardKey.arrowDown ||
            event.logicalKey == LogicalKeyboardKey.arrowLeft ||
            event.logicalKey == LogicalKeyboardKey.arrowRight ||
            event.logicalKey == LogicalKeyboardKey.pageUp ||
            event.logicalKey == LogicalKeyboardKey.pageDown ||
            event.logicalKey == LogicalKeyboardKey.home ||
            event.logicalKey == LogicalKeyboardKey.end ||
            event.logicalKey == LogicalKeyboardKey.space)) {
      // メモ欄がアクティブな間は PDF 側のキー処理を完全に分離 (= ユーザー
      //   要望: メモ欄がアクティブになっていても PDF 欄が動いてしまうのを
      //   独立に動作させる)。 上下左右 / PageUp/Down / Home/End / Space を
      //   全部メモ側専用に予約。
      return false;
    }

    // ── インライン編集中は N/M/B キーを無効化 (= ユーザー要望: ダブル
    //    クリックでメモを編集中なのに半角の N で新規メモが立ち上がって
    //    しまう問題の修正) ──
    if (_pdfMemoInlineEditing.value &&
        (event.logicalKey == LogicalKeyboardKey.keyN ||
            event.logicalKey == LogicalKeyboardKey.keyM ||
            event.logicalKey == LogicalKeyboardKey.keyB)) {
      return false;
    }

    return _onPdfKeyEvent(_pdfFocusNode, event) == KeyEventResult.handled;
  }

  /// 設定メニュー 1 項目 (アイコン + ラベル)。
  PopupMenuItem<String> _pdfMenuItem(
      String value, Object icon, String label, Color color) {
    return PopupMenuItem<String>(
      value: value,
      child: Row(children: [
        icon is IconData
            ? Icon(icon, color: color, size: 18)
            : SizedBox(
                width: 18, height: 18, child: Center(child: icon as Widget)),
        const SizedBox(width: 10),
        Text(label, style: const TextStyle(color: Colors.white, fontSize: 13)),
      ]),
    );
  }

  /// ヘッダーに収まりきらない操作をまとめる「設定」 ポップアップ
  /// (= ユーザー要望: メモ/読む方向だけ外に出し、 残りはここへ格納)。
  Widget _buildPdfSettingsMenu(bool hasMemoPanel) {
    return PopupMenuButton<String>(
      tooltip: context.read<MindMapProvider>().t('pdf.settingsOther'),
      icon: const Icon(Icons.tune_rounded),
      color: const Color(0xFF252535),
      onSelected: (v) {
        switch (v) {
          case 'toggleReadDir':
            // = ユーザー要望: 読む方向 (横↔縦) を切り替え。
            final p = context.read<MindMapProvider>();
            p.setPdfScrollHorizontal(!p.pdfScrollHorizontal);
            break;
          case 'fitPage':
            // = ユーザー要望: ページ全体がビューアに収まる表示。
            _toggleFitPage();
            break;
          case 'drawShapes':
            // = ユーザー要望: PDF 上に図形や線を書き込める機能。
            _togglePdfDrawMode();
            break;
          case 'search':
            setState(() {
              _searchBarOpen = !_searchBarOpen;
              if (!_searchBarOpen) _closeSearchBar();
            });
            break;
          case 'placeMemo':
            setState(() => _placingMemo = !_placingMemo);
            break;
          case 'reload':
            _ctrl?.reload();
            break;
          case 'openExternal':
            _openExternally();
            break;
          case 'download':
            _downloadCurrentFile();
            break;
          case 'quiz':
            final pdfPath = _pdfFilePath ?? widget.url;
            widget.onGenerateQuiz?.call(pdfPath);
            break;
          case 'splitUp':
            final u = widget.isPdf && _pdfFilePath != null
                ? _pdfFilePath!
                : _currentUrl;
            widget.onMoveToSplitPanel?.call(u, isLeftPanel: true);
            Navigator.of(context).pop();
            break;
          case 'splitDown':
            final u = widget.isPdf && _pdfFilePath != null
                ? _pdfFilePath!
                : _currentUrl;
            widget.onMoveToSplitPanel?.call(u, isLeftPanel: false);
            Navigator.of(context).pop();
            break;
          case 'aiChat':
            // = ユーザー要望: モバイルでも AI チャットを使えるように。 設定中の
            //   ブラウザ AI を「分割パネル」 で開く (= 既存の splitUp/Down と同じ
            //   ハンドオフ。 モバイル対応済みの InAppWebView 分割パネルを再利用
            //   するので確実に表示できる)。
            final p = context.read<MindMapProvider>();
            final aiId = p.browserAiTarget;
            final t = MindMapProvider.browserAiTargets.firstWhere(
                (e) => e['id'] == aiId && e['id'] != 'google',
                orElse: () => const {'url': 'https://chatgpt.com/'});
            final aiUrl = (t['url'] ?? 'https://chatgpt.com/').toString();
            widget.onMoveToSplitPanel?.call(aiUrl, isLeftPanel: false);
            Navigator.of(context).pop();
            break;
          case 'readAloud':
            // PDF 本文を音声で読み上げる (= ユーザー要望)。
            _startReadAloud();
            break;
          case 'prevPage':
            if (_spreadFitPageMode) {
              _jumpSpreadPages(-2);
              break;
            }
            try {
              _pdfViewerCtrl?.previousPage();
            } catch (_) {}
            break;
          case 'nextPage':
            if (_spreadFitPageMode) {
              _jumpSpreadPages(2);
              break;
            }
            try {
              _pdfViewerCtrl?.nextPage();
            } catch (_) {}
            break;
          case 'jumpPage':
            _showJumpToPageDialog();
            break;
        }
      },
      itemBuilder: (_) => [
        // ── 読む方向 (横↔縦) 切替 (= ユーザー要望: 設定の一番上に配置) ──
        // ── 読む方向 (横↔縦) 切替: 現在の向きが分かるラベルにする (= ユーザー
        //   要望: 今どっちの向きで読める状態か分からない) ──
        if (widget.isPdf)
          _pdfMenuItem(
              'toggleReadDir',
              context.read<MindMapProvider>().pdfScrollHorizontal
                  ? Icons.swap_horiz_rounded
                  : Icons.swap_vert_rounded,
              context.read<MindMapProvider>().pdfScrollHorizontal
                  ? '現在：横めくり（タップで縦めくりに）'
                  : '現在：縦めくり（タップで横めくりに）',
              const Color(0xFF4FC3F7)),
        // ── 「図形・線を描き込む」 は設定から外した (= ユーザー要望:
        //    設定項目が多過ぎる。 同じボタンがヘッダーに常設されている)。 ──
        if (widget.isPdf)
          _pdfMenuItem(
              'fitPage',
              _fitPageMode
                  ? Icons.fit_screen_rounded
                  : Icons.fit_screen_outlined,
              _fitPageMode ? '通常表示に戻す' : '1ページ全体を表示',
              const Color(0xFF80CBC4)),
        if (widget.isPdf)
          _pdfMenuItem(
              'spreadPages',
              _spreadFitPageMode
                  ? Icons.view_week_rounded
                  : Icons.view_week_outlined,
              _spreadFitPageMode ? '見開きモードを解除' : '見開きモード',
              const Color(0xFFFFB74D)),
        // ── ページ移動 (= ユーザー要望: 設定の中に入れる) ──
        if (widget.isPdf && _pdfTotalPages > 0) ...[
          _pdfMenuItem(
              'jumpPage', Icons.numbers, 'ページ番号を指定', const Color(0xFF4FC3F7)),
        ],
        // PDF内検索は廃止 (= ユーザー要望)。
        if (hasMemoPanel)
          _pdfMenuItem(
              'placeMemo',
              _placingMemo ? Icons.cancel : Icons.add_location_alt,
              _placingMemo ? '配置モード解除 (M)' : 'ここにメモを置く (M)',
              const Color(0xFFFFC107)),
        // ── PDF を音声で読み上げ (= ユーザー要望) ──
        if (widget.isPdf && _pdfFilePath != null)
          _pdfMenuItem('readAloud', Icons.record_voice_over_rounded,
              '音声で読み上げ（現在のページから）', const Color(0xFF4FC3F7)),
        if (!widget.isPdf)
          _pdfMenuItem('reload', Icons.refresh, '再読み込み', Colors.white70),
        _pdfMenuItem(
            'openExternal', Icons.open_in_new, '外部で開く', Colors.white70),
        if (widget.isPdf && _pdfFilePath != null)
          _pdfMenuItem('download', Icons.download_rounded, 'ダウンロード',
              const Color(0xFF4FC3F7)),
        // 「AI でフラッシュカードを作成」 は設定から外した (= ユーザー要望)。
        if (widget.onMoveToSplitPanel != null) ...[
          // AI チャット (= ユーザー要望: モバイルでも AI チャットを使えるように)
          _pdfMenuItem('aiChat', Icons.smart_toy_rounded, 'AI チャットを開く',
              const Color(0xFFBA68C8)),
          _pdfMenuItem(
              'splitUp',
              _splitPanelIcon(_SplitIconFill.top,
                  color: const Color(0xFFFF6B6B), size: 18),
              '上に分割',
              const Color(0xFFFF6B6B)),
          _pdfMenuItem(
              'splitDown',
              _splitPanelIcon(_SplitIconFill.bottom,
                  color: const Color(0xFF2196F3), size: 18),
              '下に分割',
              const Color(0xFF2196F3)),
        ],
      ],
    );
  }

  /// 開いているファイル (PDF 等) をユーザーが選んだ場所に保存する
  /// (= ユーザー要望: 設定からダウンロードできるように)。
  Future<void> _downloadCurrentFile() async {
    final src = _pdfFilePath ?? '';
    final messenger = ScaffoldMessenger.maybeOf(context);
    void snack(String m, Color c) {
      messenger?.showSnackBar(SnackBar(
          content: Text(m),
          backgroundColor: c,
          duration: const Duration(seconds: 2)));
    }

    if (src.isEmpty || !await File(src).exists()) {
      snack('保存できるファイルがありません', const Color(0xFF2A2A3E));
      return;
    }
    var name = src.split(RegExp(r'[\\/]')).last;
    if (!name.toLowerCase().endsWith('.pdf')) name = '$name.pdf';
    try {
      final bytes = await File(src).readAsBytes();
      final outPath = await FilePicker.platform.saveFile(
        dialogTitle: context.read<MindMapProvider>().t('save.pdf'),
        fileName: name,
        bytes: bytes,
      );
      if (outPath == null) return; // キャンセル
      try {
        final out = File(outPath);
        if (!await out.exists() || (await out.length()) == 0) {
          await out.writeAsBytes(bytes);
        }
      } catch (_) {}
      snack('保存しました', const Color(0xFF43B97F));
    } catch (_) {
      snack('保存に失敗しました', const Color(0xFFE53935));
    }
  }

  /// PDF キーバインドの設定ダイアログ (Dialog 版と同じ実装)

  Future<void> _showPdfArrowSettings() async {
    final provider = context.read<MindMapProvider>();
    final curDiv = provider.pdfArrowStepDivisor;
    final curJump = provider.pdfPageJumpCount;
    int? pickedDiv;
    int? pickedJump;
    await showDialog<void>(
      context: context,
      builder: (dctx) {
        double divVal = curDiv.toDouble().clamp(1.0, 100.0);
        double jumpVal = curJump.toDouble().clamp(1.0, 50.0);
        return StatefulBuilder(
          builder: (sctx, setLocal) => AlertDialog(
            // モバイル版も中央の PDF 表示を避け、読み方向に応じた終端へ配置。
            alignment: AlignmentDirectional.centerEnd,
            insetPadding: const EdgeInsets.fromLTRB(12, 24, 12, 24),
            title:
                Text(context.read<MindMapProvider>().t('pdf.keySettingsTitle')),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(context.read<MindMapProvider>().t('pdf.keyUpDown'),
                      style: TextStyle(fontWeight: FontWeight.w600)),
                  const SizedBox(height: 4),
                  Text(
                    '${divVal.round()} 回 (= 1 押下で 1/${divVal.round()} ページ移動)',
                    style: TextStyle(
                      fontSize: 11,
                      color: Theme.of(sctx).hintColor,
                    ),
                  ),
                  Slider(
                    min: 1,
                    max: 100,
                    divisions: 99,
                    value: divVal,
                    label: '${divVal.round()}',
                    onChanged: (v) {
                      setLocal(() => divVal = v);
                    },
                  ),
                  const Divider(height: 24),
                  Text(context.read<MindMapProvider>().t('pdf.keyLeftRight'),
                      style: TextStyle(fontWeight: FontWeight.w600)),
                  const SizedBox(height: 4),
                  Text(
                    '${jumpVal.round()} ページ (1 = 通常、 5 = 5 ページずつ飛ばし読み)',
                    style: TextStyle(
                      fontSize: 11,
                      color: Theme.of(sctx).hintColor,
                    ),
                  ),
                  Slider(
                    min: 1,
                    max: 50,
                    divisions: 49,
                    value: jumpVal,
                    label: '${jumpVal.round()}',
                    onChanged: (v) {
                      setLocal(() => jumpVal = v);
                    },
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dctx).pop(),
                child: Text(context.read<MindMapProvider>().t('btn.cancel')),
              ),
              FilledButton(
                onPressed: () {
                  pickedDiv = divVal.round().clamp(1, 100);
                  pickedJump = jumpVal.round().clamp(1, 50);
                  Navigator.of(dctx).pop();
                },
                child: Text(context.read<MindMapProvider>().t('btn.save')),
              ),
            ],
          ),
        );
      },
    );
    if (pickedDiv != null && pickedDiv != curDiv) {
      await provider.setPdfArrowStepDivisor(pickedDiv!);
    }
    if (pickedJump != null && pickedJump != curJump) {
      await provider.setPdfPageJumpCount(pickedJump!);
    }
  }

  /// 選択中のテキストに HighlightAnnotation を追加し、 provider にも保存。
  /// `onTextSelectionChanged` で `_selectedPdfText` / `_selectedPdfLines` が
  /// セットされている前提。 行 bounds の取得元として
  ///   1) `_selectedPdfLines` (= details.selectedTextLines, 新しめの API)
  ///   2) controller.getSelectedTextLines() を dynamic 越しに (古めの API)
  /// の順で試行する。 どちらも取れないバージョンでは SnackBar で告知。
  Future<void> _addHighlightForSelection() async {
    if (_pdfViewerCtrl == null || widget.nodeId == null) return;
    if (_selectedPdfText == null || _selectedPdfText!.isEmpty) return;

    // ── 行 bounds をなんとかして手に入れる ──
    List<dynamic> rawLines = const [];
    try {
      final cached = _selectedPdfLines;
      if (cached is List && cached.isNotEmpty) {
        rawLines = List<dynamic>.from(cached);
      }
    } catch (_) {}
    if (rawLines.isEmpty) {
      try {
        final fromCtrl = (_pdfViewerCtrl as dynamic).getSelectedTextLines();
        if (fromCtrl is List && fromCtrl.isNotEmpty) {
          rawLines = List<dynamic>.from(fromCtrl);
        }
      } catch (_) {}
    }
    if (rawLines.isEmpty) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(context.read<MindMapProvider>().t('pdf.noBounds')),
            duration: Duration(seconds: 3),
          ),
        );
      }
      return;
    }

    // 適用色: マーカーモード ON 時のみ呼ばれる前提だが、 念のためフォールバック
    final markerColor = _activeMarkerColor ?? const Color(0xFFFFEB3B);

    try {
      // ── ビューアにハイライト注釈を即時追加 ──
      final annotation = sf_pdf.HighlightAnnotation(
        textBoundsCollection: rawLines.cast<sf_pdf.PdfTextLine>(),
      );
      // 色を反映 (バージョンによっては color プロパティが存在しないので dynamic で)
      try {
        (annotation as dynamic).color = markerColor;
      } catch (_) {}
      // onAnnotationAdded コールバックでの二重保存を防ぐ
      _suppressAnnotationCallback = true;
      try {
        _pdfViewerCtrl!.addAnnotation(annotation);
      } finally {
        _suppressAnnotationCallback = false;
      }

      // ── 保存用に各行の bounds / text / page を抽出 ──
      // PdfTextLine は (bounds, text, pageNumber) フィールドを持つので
      // dynamic 越しに取り出して PdfHighlightLine に変換。
      final savedLines = <PdfHighlightLine>[];
      for (final dyn in rawLines) {
        try {
          final dynamic line = dyn;
          final Rect bounds = line.bounds as Rect;
          final String txt = line.text as String;
          final int page = line.pageNumber as int;
          savedLines.add(PdfHighlightLine(
            pageNumber: page,
            left: bounds.left,
            top: bounds.top,
            right: bounds.right,
            bottom: bounds.bottom,
            text: txt,
          ));
        } catch (_) {
          // 個別の行抽出失敗はスキップ
        }
      }

      final saved = PdfHighlight(
        id: '${DateTime.now().millisecondsSinceEpoch}',
        text: _selectedPdfText ?? '',
        lines: savedLines,
        createdAt: DateTime.now().millisecondsSinceEpoch,
        // ignore: deprecated_member_use
        colorValue: markerColor.value,
      );
      if (mounted) {
        await context
            .read<MindMapProvider>()
            .addPdfHighlight(widget.nodeId!, saved);
        // 今セッションで追加したことを記録 (閉じる前確認の rollback 用)
        _sessionAddedHighlightIds.add(saved.id);
      }

      // 選択クリア → FAB 消える (マーカーモード自体は維持して連続適用可能に)
      if (mounted) {
        setState(() {
          _selectedPdfText = null;
          _selectedPdfLines = null;
        });
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(context
                .read<MindMapProvider>()
                .t('pdf.highlightFailed')
                .replaceFirst('{err}', '$e')),
            duration: const Duration(seconds: 3),
          ),
        );
      }
    }
  }

  /// 保存済みハイライトを PdfViewerController.addAnnotation で復元する。
  /// `onDocumentLoaded` で呼び出され、 過去セッションで追加されたマーカーを
  /// 画面に再表示する。 各ハイライトの保存色も反映する。
  /// 個々の annotation 作成失敗はスキップする (壊れたデータがあっても他は復元)。
  /// onAnnotationAdded コールバックが回って二重保存にならないよう、
  /// suppress フラグを立ててから addAnnotation を呼ぶ。
  void _restoreSavedHighlights() {
    if (_pdfViewerCtrl == null || widget.nodeId == null) return;
    _suppressAnnotationCallback = true;
    try {
      final saved =
          context.read<MindMapProvider>().getPdfHighlights(widget.nodeId!);
      for (final h in saved) {
        try {
          final lines = h.lines
              .map((l) => sf_pdf.PdfTextLine(
                    Rect.fromLTRB(l.left, l.top, l.right, l.bottom),
                    l.text,
                    l.pageNumber,
                  ))
              .toList();
          if (lines.isEmpty) continue;
          final ann = sf_pdf.HighlightAnnotation(textBoundsCollection: lines);
          // 保存時の色を反映 (color プロパティが無いバージョンは黄色のまま)
          try {
            (ann as dynamic).color = Color(h.colorValue);
          } catch (_) {}
          _pdfViewerCtrl!.addAnnotation(ann);
        } catch (_) {
          // 個々の annotation 作成失敗はスキップしてループ続行
        }
      }
    } catch (_) {
    } finally {
      _suppressAnnotationCallback = false;
    }
  }

  /// syncfusion の onAnnotationAdded コールバック実体。
  /// テキスト選択メニュー (Copy / Highlight / Underline / ...) の「Highlight」 を
  /// ユーザーがタップした時、 syncfusion が `HighlightAnnotation` を addAnnotation
  /// で追加する。 そのタイミングをここで掴む。
  ///
  /// 動作:
  ///   1. 自前の addAnnotation 経由 (= suppress フラグ立ってる) なら何もしない
  ///   2. HighlightAnnotation 以外 (Underline 等) も無視
  ///   3. マーカーモード ON ならその色を annotation に反映
  ///   4. annotation の textBoundsCollection から行情報を抜き出し PdfHighlight に変換
  ///   5. provider に保存 + session set に追加 (PDF を閉じる時の rollback 対象)
  void _handleAnnotationAdded(sf_pdf.Annotation annotation) {
    if (_suppressAnnotationCallback) return;
    if (widget.nodeId == null) return;
    if (annotation is! sf_pdf.HighlightAnnotation) return;

    // 色: マーカーモードが ON ならその色、 OFF なら syncfusion デフォルトの黄色を採用。
    final markerColor = _activeMarkerColor ?? const Color(0xFFFFEB3B);
    if (_activeMarkerColor != null) {
      try {
        (annotation as dynamic).color = markerColor;
      } catch (_) {}
    }

    // textBoundsCollection から各行を取り出して PdfHighlightLine に変換
    try {
      final dynamic ann = annotation;
      final dynamic rawLines = ann.textBoundsCollection;
      if (rawLines is! List) return;

      final savedLines = <PdfHighlightLine>[];
      final textBuffer = StringBuffer();
      for (final dyn in rawLines) {
        try {
          final dynamic line = dyn;
          final Rect bounds = line.bounds as Rect;
          final String txt = (line.text as String?) ?? '';
          final int page = line.pageNumber as int;
          savedLines.add(PdfHighlightLine(
            pageNumber: page,
            left: bounds.left,
            top: bounds.top,
            right: bounds.right,
            bottom: bounds.bottom,
            text: txt,
          ));
          if (textBuffer.isNotEmpty) textBuffer.write(' ');
          textBuffer.write(txt);
        } catch (_) {
          // 個別行の取り出し失敗はスキップ
        }
      }
      if (savedLines.isEmpty) return;

      final saved = PdfHighlight(
        id: '${DateTime.now().millisecondsSinceEpoch}',
        text: textBuffer.toString(),
        lines: savedLines,
        createdAt: DateTime.now().millisecondsSinceEpoch,
        // ignore: deprecated_member_use
        colorValue: markerColor.value,
      );
      // mounted ガードはコールバック内で確認
      if (mounted) {
        context.read<MindMapProvider>().addPdfHighlight(widget.nodeId!, saved);
        _sessionAddedHighlightIds.add(saved.id);
      }
    } catch (_) {}
  }

  /// このノードに保存されている全ハイライトをクリア。
  /// マーカーボタンの「全マーカー削除」 から呼ばれる。
  Future<void> _clearAllHighlights() async {
    if (widget.nodeId == null) return;
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        title: Text(context.read<MindMapProvider>().t('pdf.deleteAllMarkers')),
        content:
            Text(context.read<MindMapProvider>().t('pdf.deleteAllMarkersBody')),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dctx).pop(false),
            child: Text(context.read<MindMapProvider>().t('btn.cancel')),
          ),
          FilledButton(
            style: FilledButton.styleFrom(
              backgroundColor: Colors.redAccent,
              foregroundColor: Colors.white,
            ),
            onPressed: () => Navigator.of(dctx).pop(true),
            child: Text(context.read<MindMapProvider>().t('btn.delete')),
          ),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    await context.read<MindMapProvider>().clearPdfHighlights(widget.nodeId!);
    // syncfusion 側からも annotation を全削除
    try {
      final ctrl = _pdfViewerCtrl;
      if (ctrl != null) {
        // getAnnotations のコピーを取って削除 (イテレート中の collection 変更回避)
        final list = List.from(ctrl.getAnnotations());
        for (final a in list) {
          try {
            ctrl.removeAnnotation(a);
          } catch (_) {}
        }
      }
    } catch (_) {}
  }

  /// マーカーメニューの 1 行を作るヘルパー (色プレビュー + ラベル)。
  PopupMenuItem<String> _markerMenuItem(String key, String label, Color color) {
    final isActive = _activeMarkerColor?.value == color.value;
    return PopupMenuItem<String>(
      value: key,
      child: Row(
        children: [
          Container(
            width: 18,
            height: 18,
            decoration: BoxDecoration(
              color: color,
              borderRadius: BorderRadius.circular(3),
              border: Border.all(
                color: isActive ? Colors.black87 : Colors.black26,
                width: isActive ? 2 : 1,
              ),
            ),
          ),
          const SizedBox(width: 10),
          Text(label),
          if (isActive) ...[
            const Spacer(),
            const Icon(Icons.check, size: 16, color: Colors.black54),
          ],
        ],
      ),
    );
  }

  /// マーカーメニュー選択時のハンドラ。 色キー選択でマーカーモード ON、
  /// 'off' で OFF、 'clear' で全マーカー削除。
  /// 色を切り替えるたびに自動適用タイマと重複ガードをリセットする
  /// (= 同じ箇所を別の色で塗り直したいケースに対応)。
  void _onMarkerMenuSelected(String key) {
    _highlightAutoTimer?.cancel();
    _lastAutoAppliedText = null;
    switch (key) {
      case 'yellow':
        setState(() => _activeMarkerColor = const Color(0xFFFFEB3B));
        break;
      case 'green':
        setState(() => _activeMarkerColor = const Color(0xFFA5D6A7));
        break;
      case 'pink':
        setState(() => _activeMarkerColor = const Color(0xFFF48FB1));
        break;
      case 'blue':
        setState(() => _activeMarkerColor = const Color(0xFF90CAF9));
        break;
      case 'off':
        setState(() => _activeMarkerColor = null);
        break;
      case 'clear':
        _clearAllHighlights();
        break;
    }
  }

  /// PDF を閉じる前に、 今セッションで追加したマーカーをどう扱うか確認するダイアログ。
  /// 戻り値:
  ///   true  = 閉じて OK (保存された状態のままか、 破棄処理は完了済み)
  ///   false = 閉じずに作業継続 (キャンセル)
  /// セッションで何も追加していない場合は確認スキップして即 true を返す。
  Future<bool> _confirmCloseIfNeeded() async {
    if (_sessionAddedHighlightIds.isEmpty || widget.nodeId == null) {
      return true;
    }
    final n = _sessionAddedHighlightIds.length;
    final action = await showDialog<String>(
      context: context,
      barrierDismissible: false,
      builder: (dctx) => AlertDialog(
        title: Text(context.read<MindMapProvider>().t('pdf.saveMarkersTitle')),
        content: Text(
          context
              .read<MindMapProvider>()
              .t('pdf.saveMarkersBody')
              .replaceFirst('{n}', '$n'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dctx).pop('cancel'),
            child: Text(context.read<MindMapProvider>().t('btn.cancel')),
          ),
          TextButton(
            style: TextButton.styleFrom(foregroundColor: Colors.redAccent),
            onPressed: () => Navigator.of(dctx).pop('discard'),
            child: Text(context.read<MindMapProvider>().t('pdf.discardClose')),
          ),
          FilledButton(
            onPressed: () => Navigator.of(dctx).pop('save'),
            child: Text(context.read<MindMapProvider>().t('pdf.saveClose')),
          ),
        ],
      ),
    );
    if (action == 'save') {
      _sessionAddedHighlightIds.clear(); // 状態を綺麗に
      return true;
    } else if (action == 'discard') {
      // 今セッションで追加した分だけ provider から削除 (auto-save 済みを rollback)
      try {
        final provider = context.read<MindMapProvider>();
        for (final id in _sessionAddedHighlightIds) {
          await provider.removePdfHighlight(widget.nodeId!, id);
        }
      } catch (_) {}
      _sessionAddedHighlightIds.clear();
      return true;
    }
    // 'cancel' or null (barrier 等) → 閉じない
    return false;
  }

  void _onSearchUpdated() {
    if (mounted) setState(() {});
  }

  Future<void> _startSearch(String text) async {
    _lastSearchQuery = text.trim();
    if (widget.isPdf) {
      _searchResult?.removeListener(_onSearchUpdated);
      _searchResult?.clear();
      if (_lastSearchQuery.isEmpty || _pdfViewerCtrl == null) {
        setState(() => _searchResult = null);
        return;
      }
      final result = _pdfViewerCtrl!.searchText(_lastSearchQuery);
      result.addListener(_onSearchUpdated);
      setState(() => _searchResult = result);
    } else {
      // URL モード (モバイルは flutter_inappwebview のみ)
      setState(() {
        _urlActiveMatch = 0;
        _urlMatchCount = 0;
      });
      if (_lastSearchQuery.isEmpty) return;
      try {
        await _ctrl?.findAllAsync(find: _lastSearchQuery);
      } catch (_) {}
    }
  }

  void _searchNext() {
    if (widget.isPdf) {
      final r = _searchResult;
      if (r == null || !r.hasResult) return;
      r.nextInstance();
      setState(() {});
    } else {
      if (_lastSearchQuery.isEmpty) return;
      try {
        _ctrl?.findNext(forward: true);
      } catch (_) {}
    }
  }

  void _searchPrev() {
    if (widget.isPdf) {
      final r = _searchResult;
      if (r == null || !r.hasResult) return;
      r.previousInstance();
      setState(() {});
    } else {
      if (_lastSearchQuery.isEmpty) return;
      try {
        _ctrl?.findNext(forward: false);
      } catch (_) {}
    }
  }

  void _closeSearchBar() {
    _searchResult?.removeListener(_onSearchUpdated);
    _searchResult?.clear();
    try {
      _ctrl?.clearMatches();
    } catch (_) {}
    setState(() {
      _searchResult = null;
      _searchBarOpen = false;
      _searchCtrl.clear();
      _lastSearchQuery = '';
      _urlActiveMatch = 0;
      _urlMatchCount = 0;
    });
  }

  /// Google 検索を新しい _InAppViewerPage で開く (Dialog 版と同じ思想)。
  /// ✕で閉じれば元のビューア (PDF/URL) に戻る。
  void _openGoogleSearch() {
    final keyword = _searchCtrl.text.trim();
    if (keyword.isEmpty) return;
    final googleUrl =
        'https://www.google.com/search?q=${Uri.encodeQueryComponent(keyword)}';
    Navigator.of(context).push(MaterialPageRoute<void>(
      fullscreenDialog: true,
      builder: (_) => _InAppViewerPage(
        url: googleUrl,
        isPdf: false,
        nodeId: widget.nodeId,
      ),
    ));
  }

  /// モバイル: 「ページにジャンプ」 ダイアログ。 番号を打って OK で遷移。
  Future<void> _showJumpToPageDialog() async {
    final ctrl = TextEditingController(text: '$_currentPage');
    await showDialog<void>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E2E),
        title: Text(context.read<MindMapProvider>().t('pdf.jumpToPage'),
            style: const TextStyle(color: Colors.white)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          keyboardType: TextInputType.number,
          style: const TextStyle(color: Colors.white),
          decoration: InputDecoration(
            labelText: context
                .read<MindMapProvider>()
                .t('pdf.pageRangeHint')
                .replaceFirst('{max}', '$_pdfTotalPages'),
            labelStyle: const TextStyle(color: Colors.white70),
            enabledBorder: const UnderlineInputBorder(
              borderSide: BorderSide(color: Colors.white24),
            ),
          ),
          onSubmitted: (v) {
            final n = int.tryParse(v.trim());
            if (n != null && n >= 1 && n <= _pdfTotalPages) {
              Navigator.of(dctx).pop();
              _jumpToPage(n);
            }
          },
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dctx).pop(),
            child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                style: const TextStyle(color: Colors.white60)),
          ),
          ElevatedButton(
            onPressed: () {
              final n = int.tryParse(ctrl.text.trim());
              if (n != null && n >= 1 && n <= _pdfTotalPages) {
                Navigator.of(dctx).pop();
                _jumpToPage(n);
              }
            },
            child: Text(context.read<MindMapProvider>().t('pdf.jump')),
          ),
        ],
      ),
    );
  }

  Future<void> _jumpToPage(int page) async {
    setState(() => _currentPage = page);
    if (widget.isPdf) {
      try {
        _pdfViewerCtrl?.jumpToPage(page);
      } catch (_) {}
    } else {
      final base = widget.url.split('#').first;
      final newUrl = '$base#page=$page';
      await _ctrl?.loadUrl(urlRequest: iaw.URLRequest(url: iaw.WebUri(newUrl)));
    }
  }

  Future<void> _loadUrl(String url) async {
    setState(() => _currentUrl = url);
    await _ctrl?.loadUrl(urlRequest: iaw.URLRequest(url: iaw.WebUri(url)));
  }

  Future<void> _restoreScrollY(double y) async {
    if (widget.isPdf) return;
    try {
      await _ctrl?.evaluateJavascript(source: 'window.scrollTo(0, $y)');
      _currentScrollY = y;
    } catch (_) {}
  }

  Future<void> _jumpToMemo(PdfMemo memo) async {
    if (memo.pageNumber != null && widget.isPdf) {
      await _jumpToPage(memo.pageNumber!);
    } else if (memo.url != null) {
      if (memo.url != _currentUrl) {
        await _loadUrl(memo.url!);
        await Future.delayed(const Duration(milliseconds: 800));
      }
      if (memo.scrollY != null) {
        await _restoreScrollY(memo.scrollY!);
      }
    }
    if (!mounted) return;
    setState(() => _highlightMemoId = memo.id);
    _pulseCtrl.forward(from: 0.0);
    Future.delayed(const Duration(milliseconds: 3000), () {
      if (mounted && _highlightMemoId == memo.id) {
        setState(() => _highlightMemoId = null);
      }
    });
  }

  Future<void> _openExternally() async {
    // PDF モードでは OpenFilex (Dialog 版と同じ理由)
    if (widget.isPdf) {
      final path = _resolveLocalPdfPath();
      if (path != null) {
        try {
          await OpenFilex.open(path);
        } catch (_) {}
      }
      return;
    }
    final uri = Uri.tryParse(_currentUrl);
    if (uri == null) return;
    try {
      await launchUrl(uri, mode: LaunchMode.externalApplication);
    } catch (_) {}
  }

  /// アクティブメモ取得 (Dialog 版と同じ思想)。
  PdfMemo? _findActiveMemo(MindMapProvider provider) {
    final id = widget.nodeId;
    final highlight = _highlightMemoId;
    if (id == null || highlight == null) return null;
    final node = provider.nodes[id];
    if (node?.pdfMemos == null) return null;
    for (final m in node!.pdfMemos!) {
      if (m.id == highlight && m.xRatio != null && m.yRatio != null) {
        return m;
      }
    }
    return null;
  }

  Future<void> _onPlaceTap(TapDownDetails details, Size area) async {
    final id = widget.nodeId;
    if (id == null) return;
    final xRatio = (details.localPosition.dx / area.width).clamp(0.0, 1.0);
    final yRatio = (details.localPosition.dy / area.height).clamp(0.0, 1.0);
    // ── ページ番号 / URL / scrollY のスナップショット (Dialog 版と同じ) ──
    final int? snapshotPage = widget.isPdf ? _currentPage : null;
    final String? snapshotUrl = widget.isPdf ? null : _currentUrl;
    final double? snapshotScrollY = widget.isPdf ? null : _currentScrollY;

    final created = await showDialog<PdfMemo?>(
      context: context,
      builder: (_) => _PdfMemoEditDialog(
        initialPage: snapshotPage,
        initialUrl: snapshotUrl,
        // 配置モード: ページは確定済みなのでダイアログ側で入力 UI 不要
        placedMode: true,
      ),
    );
    if (created != null && mounted) {
      final provider = context.read<MindMapProvider>();
      final added = provider.addPdfMemo(
        id,
        text: created.text,
        pageNumber: snapshotPage,
        url: snapshotUrl,
        scrollY: snapshotScrollY,
        xRatio: xRatio,
        yRatio: yRatio,
        colorValue: created.colorValue,
      );
      setState(() => _highlightMemoId = added.id);
      _pulseCtrl.forward(from: 0.0);
      Future.delayed(const Duration(milliseconds: 3000), () {
        if (mounted && _highlightMemoId == added.id) {
          setState(() => _highlightMemoId = null);
        }
      });
    }
    if (mounted) setState(() => _placingMemo = false);
  }

  Future<void> _editMemoInline(MindMapProvider provider, PdfMemo m) async {
    final updated = await showDialog<PdfMemo?>(
      context: context,
      builder: (_) => _PdfMemoEditDialog(initial: m),
    );
    if (updated != null) {
      provider.updatePdfMemo(
        widget.nodeId!,
        m.id,
        text: updated.text,
        pageNumber: updated.pageNumber,
        url: updated.url,
        colorValue: updated.colorValue,
      );
    }
  }

  void _showMemoSheet() {
    if (widget.nodeId == null) return;
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: const Color(0xFF1E1E2E),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(18)),
      ),
      isScrollControlled: true,
      builder: (_) => SizedBox(
        height: MediaQuery.of(context).size.height * 0.7,
        child: _PdfMemoPanel(
          nodeId: widget.nodeId!,
          isPdf: widget.isPdf,
          currentPage: _currentPage,
          currentUrl: _currentUrl,
          highlightMemoId: _highlightMemoId,
          onJumpToMemo: (m) {
            Navigator.of(context).pop();
            _jumpToMemo(m);
          },
          onAddHere: () {
            Navigator.of(context).pop();
            setState(() => _placingMemo = true);
          },
          // モバイル: ボトムシートを閉じる = メモパネル閉じる。
          onClosePanel: () => Navigator.of(context).pop(),
          // メモを AI に質問するボタン (= ユーザー要望: モバイルのメモにも AI)。
          onSendMemoToAi: widget.onAskAiMemo == null
              ? null
              : (memo) => widget.onAskAiMemo!(memo),
        ),
      ),
    );
  }

  /// PDF (SfPdfViewer) もしくは URL (InAppWebView) のメインビューア部分を構築。
  Widget _buildViewerCore() {
    if (widget.isPdf) {
      if (_pdfError != null) {
        return Center(
          child: Padding(
            padding: const EdgeInsets.all(16),
            child: Text(
              'PDF を開けませんでした:\n$_pdfError',
              style: const TextStyle(color: Colors.white70, fontSize: 13),
              textAlign: TextAlign.center,
            ),
          ),
        );
      }
      if (_pdfFilePath == null || _pdfViewerCtrl == null) {
        return const Center(
          child: CircularProgressIndicator(strokeWidth: 2),
        );
      }
      // PDF めくり方向 (= ユーザー要望: 縦めくり/横めくりを選択できるように)。
      final pdfHoriz = context.watch<MindMapProvider>().pdfScrollHorizontal;
      return Focus(
        focusNode: _pdfFocusNode,
        autofocus: true,
        onKeyEvent: _onPdfKeyEvent,
        // SfPdfViewer の上にハイライト追加ボタンを重ねるため Stack でラップ
        child: Stack(
          children: [
            // continuous モード + widthFactor 0.65 + 日本語 Localizations (Dialog 版と同じ)
            // ── widthFactor をプラットフォームで切替 ──
            // デスクトップ: 0.65 (= ノートやメモパネルを横に並べる用)
            // モバイル (Android/iOS): 1.0 (= 全幅で大きく表示)
            // ユーザー要望: 「PDF ビューワーの表示領域が小さい、 特に
            //   Android 版で左右の黒のスペース要らないから大きめに表示
            //   して欲しい」 への対応。
            // 見開き中はライブビューアを停止し、PDF の二重解析・二重描画を
            // 避ける。Focus は親に残るため Ctrl+/- と見開きページ送りは維持される。
            if (!_spreadFitPageMode)
              LayoutBuilder(
                builder: (viewerCtx, viewerConstraints) {
                  final hasHiddenPdfPages = _pdfFilePath != null &&
                      context
                          .read<MindMapProvider>()
                          .hiddenPdfPagesFor(_pdfFilePath!)
                          .isNotEmpty;
                  final liveWidthFactor =
                      _pdfLiveWidthFactor(viewerConstraints);
                  final liveLayoutMode = (_fitPageMode || _spreadFitPageMode)
                      ? sf_pdf.PdfPageLayoutMode.single
                      : (pdfHoriz && hasHiddenPdfPages)
                          ? sf_pdf.PdfPageLayoutMode.single
                          : sf_pdf.PdfPageLayoutMode.continuous;
                  final liveScrollDirection =
                      (_fitPageMode || _spreadFitPageMode || pdfHoriz)
                          ? sf_pdf.PdfScrollDirection.horizontal
                          : sf_pdf.PdfScrollDirection.vertical;
                  return Align(
                    alignment: Alignment.topCenter,
                    child: FractionallySizedBox(
                      widthFactor: liveWidthFactor,
                      heightFactor: 1.0,
                      child: Localizations(
                        locale: const Locale('ja'),
                        delegates: const [
                          GlobalMaterialLocalizations.delegate,
                          GlobalWidgetsLocalizations.delegate,
                          GlobalCupertinoLocalizations.delegate,
                        ],
                        // ── 図形・線 描き込みレイヤー (= ユーザー要望) ──
                        child: PdfDrawLayer(
                          active: _pdfDrawActive && _pdfFilePath != null,
                          filePath: _pdfFilePath,
                          controller: _pdfViewerCtrl,
                          tr: context.read<MindMapProvider>().t,
                          toolbarSink: _pdfDrawToolbar,
                          onExit: () {
                            if (mounted) {
                              setState(() => _pdfDrawActive = false);
                            }
                          },
                          onSaved: () {
                            if (mounted) {
                              setState(() => _pdfDrawReloadTick++);
                            }
                            // マップのサムネイルも作り直す (= ユーザー報告)。
                            widget.onSavedToFile?.call();
                          },
                          child: sf_pdf.SfPdfViewer.file(
                          _stablePdfFile(_pdfFilePath!),
                          // 描き込み保存後は tick が進んでファイルを読み直す。
                          key: ValueKey(
                              '${_pdfFilePath}_draw$_pdfDrawReloadTick'),
                          controller: _pdfViewerCtrl,
                          // ── ユーザー要望: PDF ページ非表示が全画面でも効くように ──
                          // continuous モードだとスクロールで戻ると非表示ページが見えてしまう
                          // バグがあったため、 single モードに変更 (= 1 ページずつ表示)。
                          // = ユーザー要望: シームレスなページめくり。 既定 continuous、
                          //   非表示ページ設定時のみ strict single (上の全画面版と同方針)。
                          pageLayoutMode: liveLayoutMode,

                          scrollDirection: liveScrollDirection,

                          enableTextSelection:
                              true, // テキスト選択 + コピー対応 (Dialog 版と同じ)
                          enableDoubleTapZooming: false,
                          // ズーム上限を 4.0 (Dialog 版と同じ。 minZoomLevel は v28 で未公開)
                          maxZoomLevel: 8.0,
                          // syncfusion がアノテーションを追加した時のフック (Dialog 版と同じ)
                          onAnnotationAdded: (annotation) {
                            _handleAnnotationAdded(annotation);
                          },
                          // 選択中テキスト + 行 bounds の追跡 + マーカー自動適用 (Dialog 版と同じ)
                          onTextSelectionChanged: (details) {
                            if (!mounted) return;
                            final t = details.selectedText;
                            dynamic lines;
                            try {
                              lines = (details as dynamic).selectedTextLines;
                            } catch (_) {}
                            if (t != _selectedPdfText ||
                                lines != _selectedPdfLines) {
                              setState(() {
                                _selectedPdfText = t;
                                _selectedPdfLines = lines;
                              });
                            }
                            _highlightAutoTimer?.cancel();
                            if (_activeMarkerColor != null &&
                                t != null &&
                                t.isNotEmpty &&
                                t != _lastAutoAppliedText &&
                                widget.nodeId != null) {
                              final triggerText = t;
                              final triggerLines = lines;
                              _highlightAutoTimer =
                                  Timer(const Duration(milliseconds: 100), () {
                                if (!mounted) return;
                                if (_activeMarkerColor == null) return;
                                _lastAutoAppliedText = triggerText;
                                final savedText = _selectedPdfText;
                                final savedLines = _selectedPdfLines;
                                _selectedPdfText = triggerText;
                                _selectedPdfLines = triggerLines;
                                _addHighlightForSelection().catchError((_) {
                                  if (!mounted) return;
                                  setState(() {
                                    _selectedPdfText = savedText;
                                    _selectedPdfLines = savedLines;
                                  });
                                });
                              });
                            }
                          },
                          onPageChanged: (details) {
                            // ページが実際に変わった時だけ再構築 (= ユーザー要望: ページめくりの
                            //   たびに画面全体が再構築されて重いのを軽減)。
                            if (mounted &&
                                _currentPage != details.newPageNumber) {
                              setState(() {
                                _currentPage = details.newPageNumber;
                                if (_pageInputCtrl.text !=
                                    '${details.newPageNumber}') {
                                  _pageInputCtrl.text =
                                      '${details.newPageNumber}';
                                }
                              });
                              // 連続めくりで毎回ラスタすると落ちるので debounce。
                              if (_fitPageMode) _scheduleFitPageRender();
                              if (_spreadFitPageMode)
                                _scheduleSpreadPageRender();
                            }
                            // ── PDF 最終ページ記録 (= 次回オープン時に復元) ──
                            // ユーザー要望: 「最後に開いた PDF のページが開かれるようにして」。
                            // NodePdfView (= ノードに添付した PDF を全画面表示する版) でも
                            // ページ移動のたびに provider に保存する。
                            if (_pdfFilePath != null) {
                              try {
                                context.read<MindMapProvider>().setLastPdfPage(
                                    _pdfFilePath!, details.newPageNumber);
                              } catch (_) {/* context 無効時は無視 */}
                            }
                            // ── 非表示 PDF ページ → 自動スキップ ──
                            // 画面分割版 (`_handleSplitPdfPageChanged`) と同じロジックに
                            // 揃え、 末尾 / 先頭で詰まらないように方向反転まで実装する。
                            if (_pdfFilePath != null &&
                                _pdfViewerCtrl != null) {
                              final provider = context.read<MindMapProvider>();
                              final hidden =
                                  provider.hiddenPdfPagesFor(_pdfFilePath!);
                              if (hidden.contains(details.newPageNumber)) {
                                final isForward = details.newPageNumber >=
                                    details.oldPageNumber;
                                final maxPage = _pdfViewerCtrl!.pageCount;
                                if (maxPage > 0) {
                                  int target = details.newPageNumber;
                                  bool decided = false;
                                  for (int i = 0; i < maxPage; i++) {
                                    if (isForward) {
                                      target++;
                                      if (target > maxPage) {
                                        target = details.newPageNumber - 1;
                                        if (target < 1) break;
                                        for (int j = 0; j < maxPage; j++) {
                                          if (!hidden.contains(target)) {
                                            decided = true;
                                            break;
                                          }
                                          target--;
                                          if (target < 1) break;
                                        }
                                        break;
                                      }
                                    } else {
                                      target--;
                                      if (target < 1) {
                                        target = details.newPageNumber + 1;
                                        if (target > maxPage) break;
                                        for (int j = 0; j < maxPage; j++) {
                                          if (!hidden.contains(target)) {
                                            decided = true;
                                            break;
                                          }
                                          target++;
                                          if (target > maxPage) break;
                                        }
                                        break;
                                      }
                                    }
                                    if (!hidden.contains(target)) {
                                      decided = true;
                                      break;
                                    }
                                  }
                                  if (decided &&
                                      target != details.newPageNumber) {
                                    WidgetsBinding.instance
                                        .addPostFrameCallback((_) {
                                      if (!mounted || _pdfViewerCtrl == null)
                                        return;
                                      try {
                                        _pdfViewerCtrl!.jumpToPage(target);
                                      } catch (_) {}
                                    });
                                  }
                                }
                              }
                            }
                          },
                          onDocumentLoaded: (details) {
                            if (mounted) {
                              setState(() {
                                _pdfTotalPages = details.document.pages.count;
                                _pageInputCtrl.text = '$_currentPage';
                              });
                              // ── PDF サムネイルが無ければ生成 (= ユーザー要望) ──
                              _ensurePdfThumbForNode(
                                  context, widget.nodeId, _pdfFilePath);
                              _pdfFocusNode.requestFocus();
                              // 初期 zoom を少し引き気味に (Dialog 版と同じ)
                              // single モードで自動 fit (Dialog 版と同じ理由)
                              WidgetsBinding.instance.addPostFrameCallback((_) {
                                if (!mounted || _pdfViewerCtrl == null) return;
                                _restoreSavedHighlights();
                              });
                              // ── ページ全体表示 (fit-page) の既定 ON は廃止 ──
                              //   (= ユーザー要望: 機能していないので削除)。 PDF は
                              //   ライブの SfPdfViewer (幅フィット) のみで表示する。
                              if (_spreadFitPageMode)
                                _scheduleSpreadPageRender();
                              // 非表示ページがある場合、 最初の表示可能ページに自動ジャンプ
                              if (_pdfFilePath != null) {
                                final provider =
                                    context.read<MindMapProvider>();
                                final hidden =
                                    provider.hiddenPdfPagesFor(_pdfFilePath!);
                                if (hidden.isNotEmpty) {
                                  int first = 1;
                                  while (first <= _pdfTotalPages &&
                                      hidden.contains(first)) {
                                    first++;
                                  }
                                  if (first > 1 && first <= _pdfTotalPages) {
                                    WidgetsBinding.instance
                                        .addPostFrameCallback((_) {
                                      if (!mounted || _pdfViewerCtrl == null)
                                        return;
                                      try {
                                        _pdfViewerCtrl!.jumpToPage(first);
                                      } catch (_) {}
                                    });
                                  }
                                }
                              }
                              // ── PDF 最終ページ復元 (NodePdfView 版) ──
                              // ユーザー要望: 「最後に開いた PDF のページが開かれるようにして」。
                              // hidden ロジックが先に first jump していても、 ここで上書きで
                              // 最終ページに飛ぶ (= 直近の閲覧位置を優先)。
                              // syncfusion の jumpToPage はロード直後だと無視されることがある
                              // ので、 Future.delayed で 200ms 待ってから実行する。
                              if (_pdfFilePath != null) {
                                try {
                                  final lastPage = context
                                      .read<MindMapProvider>()
                                      .lastPdfPageFor(_pdfFilePath!);
                                  if (lastPage != null &&
                                      lastPage >= 1 &&
                                      lastPage <= _pdfTotalPages) {
                                    Future.delayed(
                                        const Duration(milliseconds: 200), () {
                                      if (!mounted || _pdfViewerCtrl == null)
                                        return;
                                      try {
                                        _pdfViewerCtrl!.jumpToPage(lastPage);
                                        setState(() {
                                          _currentPage = lastPage;
                                          _pageInputCtrl.text = '$lastPage';
                                        });
                                      } catch (e) {
                                        debugPrint('最終ページ復元失敗: $e');
                                      }
                                    });
                                  }
                                } catch (_) {/* context 無効時は無視 */}
                              }
                            }
                          },
                          onDocumentLoadFailed: (details) {
                            if (mounted) {
                              setState(() => _pdfError =
                                  '${details.error}: ${details.description}');
                            }
                          },
                        ),
                        ), // PdfDrawLayer 閉じ
                      ),
                    ),
                  );
                },
              ),
            // マーカーバナー / FAB 廃止 (Dialog 版と同じ理由)
            if (_spreadFitPageMode) _buildSpreadPageOverlay(),
            // ── 音声読み上げ操作バー (= ユーザー要望: PDF 音声読み上げ) ──
            if (_readerVisible && _reader != null)
              Positioned(
                left: 0,
                right: 0,
                bottom: 14,
                child: Center(
                  child: ReadAloudBar(
                    controller: _reader!,
                    onClose: _stopReadAloud,
                  ),
                ),
              ),
          ],
        ),
      );
    }
    return iaw.InAppWebView(
      initialUrlRequest: iaw.URLRequest(url: iaw.WebUri(widget.url)),
      initialSettings: iaw.InAppWebViewSettings(
        transparentBackground: false,
        allowFileAccess: true,
        allowFileAccessFromFileURLs: true,
        allowUniversalAccessFromFileURLs: true,
      ),
      onWebViewCreated: (c) => _ctrl = c,
      onTitleChanged: (c, t) {
        if (mounted && t != null && t.isNotEmpty) {
          setState(() => _title = t);
        }
      },
      onLoadStart: (c, u) {
        if (mounted && u != null) {
          setState(() => _currentUrl = u.toString());
        }
      },
      onLoadStop: (c, u) async {
        if (mounted && u != null) {
          setState(() => _currentUrl = u.toString());
        }
        // 画面分割から引き継いだ再生速度を動画へ適用 (ユーザー要望)。
        if ((_videoPlaybackRate - 1.0).abs() > 0.001) {
          for (final ms in const [300, 1000, 2500]) {
            await Future<void>.delayed(Duration(milliseconds: ms));
            if (!mounted) break;
            await _applyMobileVideoRate(_videoPlaybackRate);
          }
        }
        _scheduleMobileVideoProbe();
      },
      onUpdateVisitedHistory: (c, u, __) {
        if (mounted && u != null) {
          setState(() => _currentUrl = u.toString());
          _scheduleMobileVideoProbe();
        }
      },
      onScrollChanged: (c, x, y) {
        _currentScrollY = y.toDouble();
      },
      onFindResultReceived:
          (c, activeMatchOrdinal, numberOfMatches, isDoneCounting) {
        if (mounted) {
          setState(() {
            _urlActiveMatch = numberOfMatches > 0 ? activeMatchOrdinal + 1 : 0;
            _urlMatchCount = numberOfMatches;
          });
        }
      },
    );
  }

  Widget _buildWebViewBody(MindMapProvider provider) {
    final hasNode = widget.nodeId != null;
    return LayoutBuilder(
      builder: (lctx, constraints) {
        final area = Size(constraints.maxWidth, constraints.maxHeight);
        // ハイライト中のメモ 1 個のみマーカー描画 (Dialog 版と同じ理由)
        final activeMemo = (hasNode && _highlightMemoId != null)
            ? _findActiveMemo(provider)
            : null;
        return Stack(
          children: [
            Positioned.fill(child: _buildViewerCore()),
            // ── 動画サイトなら再生速度バーを上にオーバーレイ ──
            // 全画面表示でも動画再生速度を変更可能。 Slider + プリセット。
            if (_isVideoSiteUrlMobile(_currentUrl) || _webHasVideo)
              Positioned(
                top: 8,
                left: 8,
                right: 8,
                child: _buildMobileVideoSpeedBar(),
              ),
            if (activeMemo != null)
              _buildMemoMarker(
                memo: activeMemo,
                area: area,
                isHighlighted: true,
                pulse: _pulseCtrl,
                onTap: () => _showMemoDetailPopup(
                    context, provider, widget.nodeId!, activeMemo),
                onLongPress: () => _editMemoInline(provider, activeMemo),
              ),
            if (_placingMemo && hasNode)
              Positioned.fill(
                child: GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTapDown: (d) => _onPlaceTap(d, area),
                  child: Container(
                    color: Colors.black.withValues(alpha: 0.18),
                    alignment: Alignment.topCenter,
                    padding: const EdgeInsets.only(top: 14),
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 14, vertical: 8),
                      decoration: BoxDecoration(
                        color: const Color(0xFFFFC107),
                        borderRadius: BorderRadius.circular(20),
                      ),
                      child: const Text(
                        'メモを置きたい場所をタップ',
                        style: TextStyle(
                            color: Colors.black87,
                            fontWeight: FontWeight.w700,
                            fontSize: 13),
                      ),
                    ),
                  ),
                ),
              ),
          ],
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final showMemoBtn = widget.nodeId != null;
    return PopScope(
      canPop: _sessionAddedHighlightIds.isEmpty,
      onPopInvoked: (didPop) async {
        if (didPop) return;
        final ok = await _confirmCloseIfNeeded();
        if (ok && mounted) {
          Navigator.of(context).pop();
        }
      },
      child: Consumer<MindMapProvider>(
        builder: (ctx, provider, _) {
          return Scaffold(
            backgroundColor: const Color(0xFF1A1A24),
            appBar: AppBar(
              backgroundColor: const Color(0xFF252535),
              foregroundColor: Colors.white,
              elevation: 0,
              // PDF モード時はタイトル横に「3 / 92」 を出して位置感覚を提示
              title: Row(
                children: [
                  Expanded(
                    child: Text(
                      _title.isNotEmpty ? _title : _currentUrl,
                      style: const TextStyle(fontSize: 14),
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                  if (widget.isPdf && _pdfTotalPages > 0)
                    Padding(
                      padding: const EdgeInsets.only(left: 8),
                      child: Text(
                        '$_currentPage / $_pdfTotalPages',
                        style: const TextStyle(
                            color: Colors.white60, fontSize: 12),
                      ),
                    ),
                ],
              ),
              actions: [
                // ── ページ移動・読む方向の切替は ⋮ 設定メニューに集約 (= ユーザー
                //    要望: 読む方向は設定メニューの一番上へ移動) ──
                // ── メモ一覧 (外に出す) ──
                if (showMemoBtn)
                  IconButton(
                    tooltip: context.read<MindMapProvider>().t('pmemo.list'),
                    icon: const Icon(Icons.sticky_note_2,
                        color: Color(0xFFFFC107)),
                    onPressed: _showMemoSheet,
                  ),
                // ── その他は「設定」 メニューに格納 (= ユーザー要望:
                //    ヘッダーのオーバーフロー対策。 キー操作設定ボタンも撤去) ──
                // ── PDF への描き込み (= ユーザー要望: PDF に
                //    書き込んだり図形を上に書けるように)。 設定
                //    メニューの奥ではなくヘッダーに出す。 ──
                if (widget.isPdf && _pdfFilePath != null)
                  IconButton(
                    tooltip: context
                        .read<MindMapProvider>()
                        .t('pdf.drawShapes'),
                    icon: Icon(
                        _pdfDrawActive
                            ? Icons.draw_rounded
                            : Icons.draw_outlined,
                        color: _pdfDrawActive
                            ? const Color(0xFF5FD3B2)
                            : Colors.white70,
                        size: 20),
                    onPressed: _togglePdfDrawMode,
                  ),
                _buildPdfSettingsMenu(showMemoBtn),
              ],
              // 検索バー / 描き込みの道具箱は AppBar の bottom に差し込む
              // (= ユーザー要望: 道具箱が PDF の上に被らないように)。
              bottom: _searchBarOpen
                  ? PreferredSize(
                      preferredSize: const Size.fromHeight(40),
                      child: _buildSearchBar(),
                    )
                  : (_pdfDrawActive
                      ? PreferredSize(
                          preferredSize: const Size.fromHeight(76),
                          child: _buildPdfDrawToolbarBar(),
                        )
                      : null),
            ),
            body: _buildWebViewBody(provider),
          );
        },
      ),
    );
  }

  /// AppBar の bottom に出す検索バー (PDF / URL 両対応、 Dialog 版と同じ思想)。
  Widget _buildSearchBar() {
    String counterText = '';
    bool canNavigate = false;
    if (widget.isPdf) {
      final r = _searchResult;
      if (r != null && r.hasResult) {
        counterText = '${r.currentInstanceIndex} / ${r.totalInstanceCount}';
        canNavigate = true;
      } else if (r != null) {
        counterText = '0 件';
      }
    } else {
      if (_lastSearchQuery.isNotEmpty) {
        if (_urlMatchCount > 0) {
          counterText = '$_urlActiveMatch / $_urlMatchCount';
          canNavigate = true;
        } else {
          counterText = '0 件';
        }
      }
    }
    return Container(
      height: 40,
      color: const Color(0xFF1B1B26),
      padding: const EdgeInsets.symmetric(horizontal: 10),
      child: Row(
        children: [
          const Icon(Icons.search, color: Colors.white60, size: 18),
          const SizedBox(width: 8),
          Expanded(
            child: TextField(
              controller: _searchCtrl,
              autofocus: true,
              style: const TextStyle(color: Colors.white, fontSize: 13),
              decoration: InputDecoration(
                isDense: true,
                contentPadding: const EdgeInsets.symmetric(vertical: 8),
                hintText: widget.isPdf ? 'PDF 内を検索...' : 'ページ内を検索...',
                hintStyle: const TextStyle(color: Colors.white38, fontSize: 13),
                border: InputBorder.none,
              ),
              onSubmitted: (v) => _startSearch(v),
            ),
          ),
          if (counterText.isNotEmpty)
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 6),
              child: Text(
                counterText,
                style: const TextStyle(color: Colors.white60, fontSize: 12),
              ),
            ),
          IconButton(
            tooltip: context.read<MindMapProvider>().t('search.prevHit'),
            icon: const Icon(Icons.keyboard_arrow_up,
                color: Colors.white70, size: 20),
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 30, minHeight: 30),
            onPressed: canNavigate ? _searchPrev : null,
          ),
          IconButton(
            tooltip: context.read<MindMapProvider>().t('search.nextHit'),
            icon: const Icon(Icons.keyboard_arrow_down,
                color: Colors.white70, size: 20),
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 30, minHeight: 30),
            onPressed: canNavigate ? _searchNext : null,
          ),
          // Google 検索: 入力テキストで Google 結果を新ページで開く
          IconButton(
            tooltip: context.read<MindMapProvider>().t('search.googleSearch'),
            icon: const Icon(Icons.travel_explore,
                color: Color(0xFF4FC3F7), size: 20),
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 30, minHeight: 30),
            onPressed: _openGoogleSearch,
          ),
          IconButton(
            tooltip: context.read<MindMapProvider>().t('search.closeSearch'),
            icon: const Icon(Icons.close, color: Colors.white60, size: 18),
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 30, minHeight: 30),
            onPressed: _closeSearchBar,
          ),
        ],
      ),
    );
  }
}

// ──────────────────────────────────────────────────────────────────────────
// PDF / URL メモ サイドパネル
// ──────────────────────────────────────────────────────────────────────────
//
// アプリ内ビューア内の右ペイン (デスクトップ) または ボトムシート (モバイル)
// として開かれる。 「マップの外」 用フローティングパネルと違い、 こちらは
// 1 ノード分だけ表示する。
class _PdfMemoPanel extends StatefulWidget {
  final String nodeId;
  final bool isPdf;
  final int currentPage;
  final String currentUrl;
  final String? highlightMemoId;
  final void Function(PdfMemo memo) onJumpToMemo;
  final VoidCallback? onAddHere;

  /// パネル自身を閉じる (= 親側で `_memoPanelOpen = false` にする) コールバック。
  /// 指定された場合のみパネルヘッダ右端に「閉じる」 ボタン (chevron) が出る。
  /// ユーザー要望: メモパネルを非表示にして PDF を横幅いっぱい広げたい。
  final VoidCallback? onClosePanel;

  /// メモ欄ヘッダーから AI 欄と左右入れ替えするコールバック。
  /// null ならヘッダーに入れ替えボタンを出さない。
  final VoidCallback? onSwapSides;

  /// メモの内容を AI チャット欄に送るコールバック (= ユーザー要望)。
  /// 親 (ビューワー state) で AI パネルを開いてクリップボードコピーする。
  /// null なら各メモタイルに「AI に送る」 ボタンを出さない。
  final void Function(PdfMemo memo)? onSendMemoToAi;

  /// メモの本文で YouTube 検索を開くコールバック (= ユーザー要望: PDF
  /// ビューアやテキストエディタのメモから YouTube 検索を開けるように)。
  /// null なら各メモタイルに YouTube ボタンを出さない。
  final void Function(PdfMemo memo)? onSearchYoutube;

  /// 全メモを「メモ毎に改行を入れて」 1 つのテキストにまとめ、 ブラウザ AI
  /// へ渡すコールバック (= ユーザー要望)。 null ならヘッダーにボタンを
  /// 出さない。
  final void Function(String text)? onSendAllToAi;

  const _PdfMemoPanel({
    required this.nodeId,
    required this.isPdf,
    required this.currentPage,
    required this.currentUrl,
    required this.highlightMemoId,
    required this.onJumpToMemo,
    this.onAddHere,
    this.onClosePanel,
    this.onSwapSides,
    this.onSendMemoToAi,
    this.onSearchYoutube,
    this.onSendAllToAi,
  });

  @override
  State<_PdfMemoPanel> createState() => _PdfMemoPanelState();
}

class _PdfMemoPanelState extends State<_PdfMemoPanel> {
  static bool get _isDesktop =>
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);

  /// 複数選択モード中かどうか。 ヘッダーの「選択」 ボタンで ON/OFF。
  /// Ctrl / ⌘ / Shift + クリックでも自動突入する (= ファイラー風 UX)。
  bool _selectionMode = false;

  /// 選択モード中にチェック済みのメモ ID 集合。
  final Set<String> _selectedIds = <String>{};

  /// 最後にクリックされたメモの (sort 後) インデックス。
  /// Shift + クリックの範囲選択の起点として使う。
  int? _lastSelectedIndex;

  /// ↑/↓ キーで移動中のフォーカス対象メモのインデックス。
  /// -1 または null = まだフォーカス未確定。 メモ一覧パネル上に
  /// マウスホバーしたタイミングで 0 にセットされ、 そこから ↑/↓ で移動。
  int? _focusedIndex;

  /// 展開中のフォルダ名集合。 ユーザー要望「クイズが作成されたらフォルダが
  /// 生成されて、 手動でフォルダを開く形」 → デフォルト空 (全フォルダ折り
  /// 畳み)。 ユーザーがフォルダヘッダーをタップすると展開状態がトグル。
  /// 「問題」 フォルダなど、 一度開けばこの集合に保持され、 再 build しても
  /// 同じ展開状態を維持する。
  final Set<String> _expandedFolders = <String>{};

  /// キーボードフォーカス中のフォルダ名 (= ユーザー要望: フォルダーを
  /// Backspace/Del で削除できるように)。 フォルダヘッダーをタップすると
  /// セットされ、 メモタップや空白タップで解除。 Backspace/Del 押下時に
  /// 値が入っていれば確認ダイアログを出してフォルダごと削除する。
  String? _focusedFolder;

  /// 現在表示中 (= 未分類 + 展開済みフォルダの中身) のメモ並び。
  /// build 内で計算され、 onKeyEvent (↑/↓) で参照するためにキャッシュ。
  /// 折り畳まれているフォルダのメモは含まれない。
  List<PdfMemo> _visibleMemos = const [];

  /// メモ / フォルダをドラッグ並び替え中かどうか (= ユーザー要望:
  /// メモ・フォルダ間の隙間は普段は詰めて、 位置替え (ドラッグ) の時だけ
  /// 挿入候補の隙間が開くようにする)。 各 Draggable の onDragStarted で true、
  /// onDragEnd / キャンセルで false に戻す。 true の間だけドロップ用の隙間
  /// (DragTarget) を 12px に広げ、 普段は 2px まで詰める。
  bool _isReordering = false;

  /// ドラッグ開始 / 終了をまとめて扱うヘルパ。 多重 setState を避ける。
  void _setReordering(bool v) {
    if (_isReordering == v) return;
    if (mounted) setState(() => _isReordering = v);
  }

  /// 解答を開示済みのクイズメモ ID 集合。
  /// メモ一覧でクイズメモは答えと解説が隠された状態で表示され、 「答えを見る」
  /// ボタンタップでここに ID が追加 → 表示が切り替わる。 メモごとに独立して
  /// 開示状態を持つ。 ユーザー要望「埋め込んでも解答を隠したり、 回答できる
  /// ようにして」 への対応。
  final Set<String> _revealedQuizMemos = <String>{};

  /// クイズメモのユーザー解答 (memoId → 入力中テキスト)。
  /// 解答開示前にユーザーが書いておく欄。 setState のたびに
  /// TextEditingController がリビルドされないよう Map で永続保持。
  final Map<String, TextEditingController> _quizAnswerCtrls =
      <String, TextEditingController>{};

  /// 答え合わせの結果 (memoId → true:正解 / false:不正解 / null:未判定)。
  final Map<String, bool?> _quizCheckResults = <String, bool?>{};

  /// 各クイズメモ用の TextEditingController を取得 (なければ作る)。
  TextEditingController _quizAnswerCtrl(String memoId) {
    return _quizAnswerCtrls.putIfAbsent(memoId, () => TextEditingController());
  }

  /// 解答テキストから「答え合わせに使う正解文字列」 を抽出。
  /// 解答が単純な場合 (= 1 行 30 文字以下) のみ自動判定可能と判断。
  /// 解答パターン例:
  ///   "A: ○"     → "○"     (二択)
  ///   "A: パリ"  → "パリ"  (穴埋め)
  ///   "A: ① 太郎" → "① 太郎" (選択肢)
  ///   "A: 長文の解説 ..." → null (= 自動答え合わせ不能、 手動で見比べる)
  String? _extractQuizCanonicalAnswer(String memoText) {
    final aPos = RegExp(r'\nA\s*[::]').firstMatch(memoText);
    if (aPos == null) return null;
    var ans = memoText.substring(aPos.end).trim();
    ans = ans.split('\n').first.trim();
    ans = ans.replaceAll(RegExp(r'\[searchKey:[^\]]*\]'), '').trim();
    if (ans.isEmpty || ans.length > 30) return null;
    return ans;
  }

  /// 自動答え合わせ。 ユーザー入力と正解文字列を比較。
  /// 全角半角・大文字小文字・前後空白を正規化して比較する。
  bool _checkQuizAnswer(String userAnswer, String canonical) {
    String norm(String s) {
      var x = s.trim().toLowerCase();
      final buf = StringBuffer();
      for (final code in x.runes) {
        if (code >= 0xFF01 && code <= 0xFF5E) {
          buf.writeCharCode(code - 0xFEE0);
        } else {
          buf.writeCharCode(code);
        }
      }
      x = buf.toString();
      x = x.replaceAll(RegExp(r'\s+'), '');
      return x;
    }

    return norm(userAnswer) == norm(canonical);
  }

  /// メモリストのスクロールコントローラ。 ↑/↓ で移動した時に
  /// 該当メモが画面外なら自動スクロールするのに使う。
  final ScrollController _memoListScrollCtrl = ScrollController();

  /// Del / Backspace を受け取るための FocusNode。 選択モードに入った瞬間に
  /// requestFocus して、 ハードウェアキー入力を吸い込む。
  /// パネル上にマウスが乗った時も自動 requestFocus → ↑/↓ がメモ一覧の
  /// 移動になり、 PDF 本体をスクロールしない。
  final FocusNode _kbdFocusNode = FocusNode(debugLabel: 'PdfMemoPanel.kbd');

  /// ダブルクリックでインライン編集中のメモ ID (= ユーザー要望
  ///   「メモをダブルクリックでそのまま書き込めるように」)。null なら非編集。
  String? _inlineEditingMemoId;

  /// インライン編集用 TextField のコントローラ。
  final TextEditingController _inlineEditCtrl = TextEditingController();
  final FocusNode _inlineEditFocus =
      FocusNode(debugLabel: 'PdfMemoPanel.inlineEdit');

  /// 指定メモのインライン編集を開始する。
  void _beginInlineEdit(PdfMemo m) {
    // 画像マーカーは編集欄に出さず、 本文だけを編集対象にする。
    final (_, body) = _parseMemoImage(m.text);
    setState(() {
      _inlineEditingMemoId = m.id;
      _inlineEditCtrl.text = body;
    });
    // ── インライン編集状態をグローバルに公開 (= ユーザー要望: ダブル
    //    クリックでメモを編集中なのに半角の N で新規メモが立ち上がる
    //    のを防ぐ。 TextField が一時的にフォーカスを失っても、 編集
    //    状態である限り N/M/B を無効化するためのフラグ) ──
    _pdfMemoInlineEditing.value = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _inlineEditFocus.requestFocus();
    });
  }

  /// インライン編集を確定して保存する。
  void _commitInlineEdit(MindMapProvider provider) {
    final id = _inlineEditingMemoId;
    if (id == null) return;
    // 元メモに画像マーカーがあれば維持したまま本文だけ差し替える。
    final node = provider.nodes[widget.nodeId];
    final old = node?.pdfMemos?.firstWhere(
      (m) => m.id == id,
      orElse: () => PdfMemo(id: id, text: ''),
    );
    final (imgPath, _) = _parseMemoImage(old?.text ?? '');
    final body = _inlineEditCtrl.text;
    final newText = (imgPath != null && imgPath.isNotEmpty)
        ? '$_kMemoImgPrefix$imgPath\n$body'
        : body;
    provider.updatePdfMemo(widget.nodeId, id, text: newText);
    setState(() => _inlineEditingMemoId = null);
    _pdfMemoInlineEditing.value = false;
  }

  /// インライン編集をキャンセルする (保存しない)。
  void _cancelInlineEdit() {
    setState(() => _inlineEditingMemoId = null);
    _pdfMemoInlineEditing.value = false;
  }

  /// 何もない所をタップしたらフォルダ/メモの選択・フォーカスを解除する
  /// (= ユーザー要望)。 インライン編集中は触らない。
  void _clearMemoSelection() {
    if (_inlineEditingMemoId != null) return;
    if (_selectionMode) _exitSelectionMode();
    if (_focusedIndex != null || _focusedFolder != null) {
      setState(() {
        _focusedIndex = null;
        _focusedFolder = null;
      });
    }
  }

  /// クリップボードの画像をメモに貼り付ける (= ユーザー要望: メモに Ctrl+V で
  /// 画像を貼り付けられるように)。
  /// インライン編集中のメモがあればそのメモに画像を添付、 無ければ画像メモを
  /// 新規作成する。 画像は `attachments/` に保存して安定パスにする。
  Future<void> _pasteImageIntoMemo(MindMapProvider provider) async {
    try {
      final clipboard = SystemClipboard.instance;
      if (clipboard == null) return;
      final reader = await clipboard.read();
      final candidates = <(FileFormat, String)>[
        (Formats.png, 'png'),
        (Formats.jpeg, 'jpg'),
        (Formats.gif, 'gif'),
        (Formats.webp, 'webp'),
        (Formats.bmp, 'bmp'),
      ];
      Uint8List? bytes;
      String ext = 'png';
      for (final (fmt, e) in candidates) {
        if (reader.canProvide(fmt)) {
          bytes = await _readMemoClipboardBytes(reader, fmt);
          if (bytes != null && bytes.isNotEmpty) {
            ext = e;
            break;
          }
        }
      }
      // Android 保険: content:// で canProvide が取りこぼすケース
      if (bytes == null || bytes.isEmpty) {
        final pf = reader.platformFormats;
        final hasImage = pf.any((f) {
          final l = f.toLowerCase();
          return l.contains('image') ||
              l.endsWith('.png') ||
              l.endsWith('.jpeg') ||
              l.endsWith('.jpg');
        });
        if (hasImage) {
          for (final (fmt, e) in candidates) {
            bytes = await _readMemoClipboardBytes(reader, fmt);
            if (bytes != null && bytes.isNotEmpty) {
              ext = e;
              break;
            }
          }
        }
      }
      if (bytes == null || bytes.isEmpty) {
        // ── 画像が無ければテキストを試す (= ユーザー要望: Ctrl+V で
        //    テキストもメモに貼り付けられるように) ──
        try {
          if (reader.canProvide(Formats.plainText)) {
            final txt = await reader.readValue(Formats.plainText);
            final trimmed = txt?.trim() ?? '';
            if (trimmed.isNotEmpty) {
              if (_inlineEditingMemoId != null) {
                // 編集中メモのカーソル位置にテキストを挿入。
                final ctrl = _inlineEditCtrl;
                final sel = ctrl.selection;
                final cur = ctrl.text;
                final start = sel.isValid ? sel.start : cur.length;
                final end = sel.isValid ? sel.end : cur.length;
                final newText =
                    cur.substring(0, start) + trimmed + cur.substring(end);
                final newOffset = start + trimmed.length;
                ctrl.value = TextEditingValue(
                  text: newText,
                  selection: TextSelection.collapsed(offset: newOffset),
                );
              } else {
                // 新規テキストメモを作成。
                provider.addPdfMemo(widget.nodeId, text: trimmed);
              }
              if (mounted) {
                _showInlineBanner('📋 テキストをメモに貼り付けました',
                    color: const Color(0xFF43B97F));
              }
              return;
            }
          }
        } catch (_) {
          // テキスト読み取りも失敗したら下のメッセージへ
        }
        _showInlineBanner('クリップボードに画像/テキストがありません',
            color: const Color(0xFFE57373));
        return;
      }
      // attachments/ に保存
      final appDir = await getApplicationDocumentsDirectory();
      final attachDir = Directory('${appDir.path}/attachments');
      if (!await attachDir.exists()) {
        await attachDir.create(recursive: true);
      }
      final name = 'memoimg_${DateTime.now().millisecondsSinceEpoch}.$ext';
      final destPath = '${attachDir.path}/$name';
      await File(destPath).writeAsBytes(bytes);

      if (_inlineEditingMemoId != null) {
        // 編集中メモに画像を添付 (テキストの先頭に画像マーカーを付与)。
        // PdfMemo モデルを変更せずに済むよう、 画像パスは text 先頭の
        //   `__MMIMG__::<path>` マーカー行として保存する。
        final id = _inlineEditingMemoId!;
        final body = _inlineEditCtrl.text;
        provider.updatePdfMemo(widget.nodeId, id,
            text: '$_kMemoImgPrefix$destPath\n$body');
        setState(() => _inlineEditingMemoId = null);
      } else {
        // 画像メモを新規作成 (text にマーカーのみ)
        provider.addPdfMemo(widget.nodeId, text: '$_kMemoImgPrefix$destPath');
      }
      if (mounted) {
        _showInlineBanner('🖼️ 画像をメモに貼り付けました', color: const Color(0xFF43B97F));
      }
    } catch (e) {
      _showInlineBanner('画像の貼り付けに失敗: $e', color: const Color(0xFFE57373));
    }
  }

  /// 画像ファイルを選んでメモに添付する (= ユーザー要望: メモ欄に画像等を
  /// 貼り付けられるように)。 クリップボード貼り付けと同じ保存形式
  /// (attachments/ + __MMIMG__ マーカー) を使う。
  Future<void> _attachImageFileAsMemo(MindMapProvider provider) async {
    try {
      final res = await FilePicker.platform.pickFiles(
        type: FileType.image,
        allowMultiple: true,
      );
      if (res == null || res.files.isEmpty) return;
      final appDir = await getApplicationDocumentsDirectory();
      final attachDir = Directory('${appDir.path}/attachments');
      if (!await attachDir.exists()) {
        await attachDir.create(recursive: true);
      }
      var added = 0;
      for (final pf in res.files) {
        final srcPath = pf.path;
        if (srcPath == null) continue;
        final dot = srcPath.lastIndexOf('.');
        final ext = dot >= 0 ? srcPath.substring(dot + 1) : 'png';
        final name =
            'memoimg_${DateTime.now().millisecondsSinceEpoch}_$added.$ext';
        final destPath = '${attachDir.path}/$name';
        await File(srcPath).copy(destPath);
        provider.addPdfMemo(widget.nodeId, text: '$_kMemoImgPrefix$destPath');
        added++;
      }
      if (added > 0 && mounted) {
        _showInlineBanner('🖼️ 画像をメモに追加しました',
            color: const Color(0xFF43B97F));
      }
    } catch (e) {
      _showInlineBanner('画像の追加に失敗: $e', color: const Color(0xFFE57373));
    }
  }

  /// メモパネル用のクリップボードバイト読み取り (super_clipboard)。
  Future<Uint8List?> _readMemoClipboardBytes(
      ClipboardReader reader, FileFormat format) async {
    final completer = Completer<Uint8List?>();
    try {
      reader.getFile(format, (file) async {
        try {
          final stream = file.getStream();
          final chunks = <int>[];
          await for (final chunk in stream) {
            chunks.addAll(chunk);
          }
          if (!completer.isCompleted) {
            completer.complete(Uint8List.fromList(chunks));
          }
        } catch (_) {
          if (!completer.isCompleted) completer.complete(null);
        }
      }, onError: (_) {
        if (!completer.isCompleted) completer.complete(null);
      });
    } catch (_) {
      if (!completer.isCompleted) completer.complete(null);
    }
    return completer.future
        .timeout(const Duration(seconds: 10), onTimeout: () => null);
  }

  /// フォルダーヘッダーの「+」 ボタン用: そのフォルダーに空メモを作って
  /// すぐインライン編集を開始する (= ユーザー要望「VSCode みたいに
  ///   フォルダーの + ボタンでそのフォルダーにメモを追加」)。
  void _addMemoToFolder(MindMapProvider provider, String folder) {
    final created =
        provider.addPdfMemo(widget.nodeId, text: '', folder: folder);
    setState(() {
      _expandedFolders.add(folder);
    });
    _beginInlineEdit(created);
  }

  /// パネル内インラインバナー (= ビューワー越しでも見える通知)。
  /// ScaffoldMessenger 経由の SnackBar は viewer ダイアログ越しだと
  /// 親アプリ側に出てしまい画面に見えないため、 panel 内オーバーレイで
  /// 通知を出す。 タイマで自動的に消える。
  String? _bannerText;
  Color _bannerColor = const Color(0xFF43B97F);
  Timer? _bannerTimer;

  /// パネル内インラインバナーを表示する。
  void _showInlineBanner(String text,
      {Color color = const Color(0xFF43B97F),
      Duration duration = const Duration(seconds: 2)}) {
    _bannerTimer?.cancel();
    setState(() {
      _bannerText = text;
      _bannerColor = color;
    });
    _bannerTimer = Timer(duration, () {
      if (!mounted) return;
      setState(() => _bannerText = null);
    });
  }

  /// フォーカス中のメモを 1 つ上/下へ移動する (= ↑/↓ キーと、 マウス
  /// ホイールの両方から呼ぶ共通ロジック)。
  /// ユーザー要望「マウスの上下入力も上下キー入力と同じ動きに」 への対応。
  void _moveFocusedMemo(bool down) {
    if (_visibleMemos.isEmpty) return;
    final cur = _focusedIndex ?? -1;
    int next;
    if (down) {
      next = (cur < 0 ? 0 : cur + 1).clamp(0, _visibleMemos.length - 1);
    } else {
      next = (cur <= 0 ? 0 : cur - 1).clamp(0, _visibleMemos.length - 1);
    }
    if (next != cur) {
      setState(() => _focusedIndex = next);
      _scrollFocusedMemoIntoView(next, _visibleMemos.length);
      // PDF ジャンプは行わない (= ↑/↓ はあくまでメモ選択の移動)。
      //   該当 PDF ページに飛びたい場合は Enter で確定。
    }
  }

  /// ↑/↓ で移動したメモが画面外なら自動スクロールする。
  /// 各メモ行のおおよその高さ (= padding + 本文 + margin) を基準に
  /// メモ index から目標スクロール位置を概算する。 厳密でなくてよく、
  /// 「画面内に入る程度」 でユーザー体験は十分。
  void _scrollFocusedMemoIntoView(int index, int total) {
    if (!_memoListScrollCtrl.hasClients) return;
    // 1 メモあたりの推定高さ (実測値: free バッジ + 本文 + アクション行
    // 入れて 80〜110 px。 余裕を見て 96 px)
    const tileH = 96.0;
    final viewportH = _memoListScrollCtrl.position.viewportDimension;
    final maxScroll = _memoListScrollCtrl.position.maxScrollExtent;
    final cur = _memoListScrollCtrl.offset;
    final target = index * tileH;
    // 目標位置がビューポートの外なら、 中央付近に来るようにスクロール
    if (target < cur + 8 || target + tileH > cur + viewportH - 8) {
      final desired =
          (target - viewportH / 2 + tileH / 2).clamp(0.0, maxScroll);
      _memoListScrollCtrl.animateTo(
        desired,
        duration: const Duration(milliseconds: 180),
        curve: Curves.easeOut,
      );
    }
  }

  @override
  void initState() {
    super.initState();
    // ── キーボードフォーカス状態をグローバル Notifier に反映 (= ユーザー
    //    要望: メモ欄を上下キーで移動しているのに PDF まで動いてしまう
    //    バグの修正)。 ビューワー側の _globalPdfKeyHandler がこの値を
    //    見て、 メモパネルにフォーカスがある間は ↑/↓ を PDF に流さない ──
    _kbdFocusNode.addListener(_onKbdFocusChanged);
  }

  void _onKbdFocusChanged() {
    _pdfMemoPanelHasKeyboardFocus.value = _kbdFocusNode.hasFocus;
  }

  @override
  void dispose() {
    _bannerTimer?.cancel();
    _kbdFocusNode.removeListener(_onKbdFocusChanged);
    // パネル破棄時はフラグもクリアして残留しないようにする。
    _pdfMemoPanelHasKeyboardFocus.value = false;
    _pdfMemoInlineEditing.value = false;
    _kbdFocusNode.dispose();
    _memoListScrollCtrl.dispose();
    _inlineEditCtrl.dispose();
    _inlineEditFocus.dispose();
    super.dispose();
  }

  /// Ctrl (Win/Linux) または ⌘ (macOS) が押下中かどうか。
  bool _isCtrlOrCmdPressed() {
    final hk = HardwareKeyboard.instance;
    return hk.isLogicalKeyPressed(LogicalKeyboardKey.controlLeft) ||
        hk.isLogicalKeyPressed(LogicalKeyboardKey.controlRight) ||
        hk.isLogicalKeyPressed(LogicalKeyboardKey.metaLeft) ||
        hk.isLogicalKeyPressed(LogicalKeyboardKey.metaRight);
  }

  /// Shift が押下中かどうか。
  bool _isShiftPressed() {
    final hk = HardwareKeyboard.instance;
    return hk.isLogicalKeyPressed(LogicalKeyboardKey.shiftLeft) ||
        hk.isLogicalKeyPressed(LogicalKeyboardKey.shiftRight);
  }

  void _toggleSelection(String memoId) {
    if (_selectedIds.contains(memoId)) {
      _selectedIds.remove(memoId);
    } else {
      _selectedIds.add(memoId);
    }
  }

  void _exitSelectionMode() {
    setState(() {
      _selectionMode = false;
      _selectedIds.clear();
    });
  }

  Future<void> _confirmAndBulkDelete(
      BuildContext ctx, MindMapProvider provider) async {
    if (_selectedIds.isEmpty) return;
    final count = _selectedIds.length;
    final confirmed = await showDialog<bool>(
      context: ctx,
      builder: (dctx) {
        // ダイアログ全体を Focus + onKeyEvent でラップして Enter / Esc に
        // 対応 (Enter = 削除確定、 Esc = キャンセル)。
        final node = FocusNode(debugLabel: 'BulkDeleteDialog.kbd');
        WidgetsBinding.instance.addPostFrameCallback((_) {
          node.requestFocus();
        });
        return Focus(
          focusNode: node,
          onKeyEvent: (FocusNode _, KeyEvent event) {
            if (event is KeyDownEvent) {
              if (event.logicalKey == LogicalKeyboardKey.enter ||
                  event.logicalKey == LogicalKeyboardKey.numpadEnter) {
                Navigator.pop(dctx, true);
                return KeyEventResult.handled;
              }
              if (event.logicalKey == LogicalKeyboardKey.escape) {
                Navigator.pop(dctx, false);
                return KeyEventResult.handled;
              }
            }
            return KeyEventResult.ignored;
          },
          child: AlertDialog(
            backgroundColor: const Color(0xFF1E1E2E),
            title: Text(provider.t('pdfMemo.bulkDeleteTitle'),
                style: const TextStyle(color: Colors.white, fontSize: 16)),
            content: Text(
              provider
                  .t(_isDesktop
                      ? 'pdfMemo.bulkDeleteBody'
                      : 'pdfMemo.bulkDeleteBodyMobile')
                  .replaceAll('{n}', '$count'),
              style: const TextStyle(color: Colors.white70, fontSize: 13),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dctx, false),
                child: Text(provider.t('pdfMemo.dialogCancel'),
                    style: const TextStyle(color: Colors.white60)),
              ),
              ElevatedButton(
                autofocus: true,
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFE57373),
                  foregroundColor: Colors.white,
                ),
                onPressed: () => Navigator.pop(dctx, true),
                child: Text(provider.t('pdfMemo.bulkDeleteConfirm')),
              ),
            ],
          ),
        );
      },
    );
    if (confirmed != true) return;
    provider.removePdfMemos(widget.nodeId, _selectedIds.toSet());
    if (!mounted) return;
    _exitSelectionMode();
  }

  @override
  Widget build(BuildContext context) {
    return Consumer<MindMapProvider>(
      builder: (ctx, provider, _) {
        final node = provider.nodes[widget.nodeId];
        final memos = List<PdfMemo>.from(node?.pdfMemos ?? const []);
        // ── ソート優先順位 ──
        // 1. ピン止め済みが先頭
        // 2. フォルダ名 (= 同一フォルダ内をまとめる、 未分類は最後)
        // 3. PDF メモはページ番号昇順
        // 4. 同条件なら更新時刻新しい順
        // 手動並び (↑↓ ボタン / ドラッグ) を尊重するため、ソート前の
        //   リスト順を記録しておく。
        final origIndex = <String, int>{};
        for (int i = 0; i < memos.length; i++) {
          origIndex[memos[i].id] = i;
        }
        memos.sort((a, b) {
          if (a.pinned != b.pinned) return a.pinned ? -1 : 1;
          final fa = (a.folder ?? '').isEmpty ? '~' : a.folder!;
          final fb = (b.folder ?? '').isEmpty ? '~' : b.folder!;
          if (fa != fb) return fa.compareTo(fb);
          // ページ番号や更新時刻ではなく、元のリスト順 (= 手動で並び替えた
          //   結果) を採用する。これで ↑↓ / ドラッグの並びが表示に反映される。
          return (origIndex[a.id] ?? 0).compareTo(origIndex[b.id] ?? 0);
        });

        // 選択モード中、 削除等で集合からはみ出した ID を除去 (ステート整合)
        if (_selectionMode && _selectedIds.isNotEmpty) {
          final liveIds = memos.map((m) => m.id).toSet();
          _selectedIds.removeWhere((id) => !liveIds.contains(id));
        }

        return Focus(
          focusNode: _kbdFocusNode,
          onKeyEvent: (FocusNode node, KeyEvent event) {
            if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
              return KeyEventResult.ignored;
            }
            // ── 選択モード中の Esc は「選択モードを抜ける」だけにして、
            //    ビューワー自体は閉じない (= ユーザー要望) ──
            // 選択が 0 件でも有効。これを選択件数で gating していたため、
            //   未選択のまま Esc を押すとビューワーが閉じてしまっていた。
            if (_selectionMode &&
                event.logicalKey == LogicalKeyboardKey.escape) {
              _exitSelectionMode();
              return KeyEventResult.handled;
            }
            // ── フォーカス中のフォルダを Backspace/Del で削除 (= ユーザー
            //    要望: フォルダーが削除できないのを backspace/del で削除
            //    できるように) ──
            if (_focusedFolder != null &&
                !_selectionMode &&
                _inlineEditingMemoId == null &&
                (event.logicalKey == LogicalKeyboardKey.delete ||
                    event.logicalKey == LogicalKeyboardKey.backspace)) {
              _confirmDeleteFolder(ctx, provider, _focusedFolder!);
              return KeyEventResult.handled;
            }
            // ── フォーカス中の単一メモを Backspace/Del で削除 (= ユーザー
            //    要望: PDF ビューアのメモが Backspace/Del で削除できないので
            //    削除できるように) ──
            // 選択モードでもフォルダフォーカスでもインライン編集中でもない、
            //   ↑/↓ ナビゲートまたはクリックで 1 件フォーカス中のメモを
            //   直接削除する。 removePdfMemo は undo を積むので Ctrl+Z で
            //   復元できる。 削除後は build 側で _focusedIndex が範囲内に
            //   丸められ、 自然と次のメモへフォーカスが移る。
            if (_focusedIndex != null &&
                !_selectionMode &&
                _focusedFolder == null &&
                _inlineEditingMemoId == null &&
                (event.logicalKey == LogicalKeyboardKey.delete ||
                    event.logicalKey == LogicalKeyboardKey.backspace)) {
              final idx = _focusedIndex!;
              if (idx >= 0 && idx < _visibleMemos.length) {
                final target = _visibleMemos[idx];
                provider.removePdfMemo(widget.nodeId, target.id);
                _showInlineBanner(
                    _isDesktop
                        ? '🗑️ メモを削除しました（Ctrl+Z で元に戻せます）'
                        : provider.t('pdfMemo.deletedHintMobile'),
                    color: const Color(0xFF4FC3F7));
                return KeyEventResult.handled;
              }
            }
            // ── _focusedIndex (= ↑/↓ で選択中のメモ) が設定されていれば、
            //    最初の Esc では _focusedIndex をクリアするだけにして
            //    ビューワーは閉じない (= ユーザー要望: メモが選択された
            //    状態で Esc を押すと何も選択されていない状態になり、
            //    その状態でもう一度 Esc を押さないと画面が閉じないように) ──
            if (_focusedIndex != null &&
                !_selectionMode &&
                _focusedFolder == null &&
                _inlineEditingMemoId == null &&
                event.logicalKey == LogicalKeyboardKey.escape) {
              setState(() => _focusedIndex = null);
              return KeyEventResult.handled;
            }
            // Esc でフォルダフォーカスを解除
            if (_focusedFolder != null &&
                event.logicalKey == LogicalKeyboardKey.escape) {
              setState(() => _focusedFolder = null);
              return KeyEventResult.handled;
            }
            // ── 選択モード中: Del/Backspace で削除、 Escape で抜ける ──
            if (_selectionMode && _selectedIds.isNotEmpty) {
              if (event.logicalKey == LogicalKeyboardKey.delete ||
                  event.logicalKey == LogicalKeyboardKey.backspace) {
                _confirmAndBulkDelete(ctx, provider);
                return KeyEventResult.handled;
              }
              // ── Ctrl+G (⌘+G): 選択メモをフォルダにまとめて格納 ──
              // (= ユーザー要望)。
              if (event.logicalKey == LogicalKeyboardKey.keyG &&
                  _isCtrlOrCmdPressed()) {
                _moveSelectedMemosToFolder(ctx, provider);
                return KeyEventResult.handled;
              }
            }
            // ── Ctrl+A (⌘+A) で「今表示されている階層」 のメモを選択 ──
            // ユーザー要望: 折り畳まれたフォルダの中のメモまで選択されると
            //   使いにくい → 画面に出ている (= 未分類 + 展開中フォルダの中身)
            //   メモだけを選択対象にする。_visibleMemos がまさにそれ。
            if (event.logicalKey == LogicalKeyboardKey.keyA &&
                _isCtrlOrCmdPressed() &&
                _visibleMemos.isNotEmpty) {
              setState(() {
                _selectionMode = true;
                _selectedIds
                  ..clear()
                  ..addAll(_visibleMemos.map((m) => m.id));
                _lastSelectedIndex = _visibleMemos.length - 1;
              });
              return KeyEventResult.handled;
            }
            // ── ↑/↓ でメモ間を移動 (PDF 本体のスクロールを吸収) ──
            // 折り畳まれているフォルダのメモは除外。
            // メモが 1 件もない時は移動できない (= 通常通り親に伝播させない)
            if (_visibleMemos.isEmpty) return KeyEventResult.ignored;
            final isUp = event.logicalKey == LogicalKeyboardKey.arrowUp;
            final isDown = event.logicalKey == LogicalKeyboardKey.arrowDown;
            // インライン編集中は ↑/↓ をメモ移動に使わず、 TextField のカーソル
            //   行移動に委ねる (= ユーザー要望: 行が変わらずメモが変わるのは
            //   使いにくい → 行が変わるだけにして)。
            if ((isUp || isDown) && _inlineEditingMemoId == null) {
              _moveFocusedMemo(isDown);
              return KeyEventResult.handled;
            }
            // ── Enter: フォーカス中のメモにジャンプ ──
            if (event.logicalKey == LogicalKeyboardKey.enter ||
                event.logicalKey == LogicalKeyboardKey.numpadEnter) {
              final idx = _focusedIndex;
              if (idx != null && idx >= 0 && idx < _visibleMemos.length) {
                widget.onJumpToMemo(_visibleMemos[idx]);
                return KeyEventResult.handled;
              }
            }
            // ── F2: フォーカス中のメモをインライン編集開始 (= ユーザー要望:
            //    F2 はメモの中身編集を割り当てて欲しい) ──
            // ダブルクリックと同じ挙動。 フォーカス中のメモが無ければ無視。
            if (event.logicalKey == LogicalKeyboardKey.f2) {
              final idx = _focusedIndex;
              if (idx != null && idx >= 0 && idx < _visibleMemos.length) {
                _beginInlineEdit(_visibleMemos[idx]);
                return KeyEventResult.handled;
              }
              return KeyEventResult.handled;
            }
            // ── F8: 新規フォルダを作成 (= ユーザー要望: フォルダーを作成
            //    するショートカットキー) ──
            if (event.logicalKey == LogicalKeyboardKey.f8) {
              _showQuickCreateFolderDialog(ctx, provider);
              return KeyEventResult.handled;
            }
            // ── Ctrl+V (⌘+V): クリップボードの画像/テキストをメモに貼り付け ──
            // (= ユーザー要望: メモに Ctrl+V で画像を貼り付け + テキストも
            //   メモに貼り付けられるように)。
            // インライン編集中のテキストフィールドにフォーカスがある間は
            //   TextField 標準のテキスト貼り付けが効くので、 ここでは処理
            //   しない。 EditableText 外なら _pasteImageIntoMemo が画像
            //   優先で、 無ければテキストにフォールバックする。
            if (event.logicalKey == LogicalKeyboardKey.keyV &&
                _isCtrlOrCmdPressed() &&
                !(FocusManager.instance.primaryFocus?.context?.widget
                    is EditableText)) {
              _pasteImageIntoMemo(provider);
              return KeyEventResult.handled;
            }
            // ── Ctrl+A / Cmd+A: 全選択 (= 選択モード突入 + 全 ID を選択) ──
            // 既に選択モード中ならトグル動作: 全選択済みなら全解除、 そうでなければ全選択。
            // Delete でまとめて削除できるので、 「全削除」 操作の起点になる。
            if (event.logicalKey == LogicalKeyboardKey.keyA &&
                _isCtrlOrCmdPressed()) {
              setState(() {
                if (_selectionMode &&
                    _selectedIds.length == _visibleMemos.length) {
                  // 全部選択中 → 全解除
                  _selectedIds.clear();
                } else {
                  _selectionMode = true;
                  _selectedIds
                    ..clear()
                    ..addAll(_visibleMemos.map((m) => m.id));
                  _lastSelectedIndex = _visibleMemos.isEmpty ? null : 0;
                }
              });
              return KeyEventResult.handled;
            }
            return KeyEventResult.ignored;
          },
          child: ValueListenableBuilder<_DockedGoogleSearchState?>(
            valueListenable: _dockedGoogleSearchNotifier,
            builder: (_, dockedState, __) {
              // ── ドック中: メモ UI を完全に隠し、 縦全部を Google 検索に使う ──
              if (dockedState != null) {
                return Container(
                  color: const Color(0xFF1E1E2E),
                  child: _DockedGoogleSearchPane(state: dockedState),
                );
              }
              // ── 通常モード: メモヘッダー + メモ一覧 ──
              // 通知バナーをパネル最前面に出すため Stack で重ねる。
              return Container(
                color: const Color(0xFF1E1E2E),
                child: Stack(
                  children: [
                    Column(
                      children: [
                        Container(
                          height: 44,
                          padding: const EdgeInsets.symmetric(horizontal: 12),
                          decoration: const BoxDecoration(
                            border: Border(
                              bottom:
                                  BorderSide(color: Colors.white12, width: 1),
                            ),
                          ),
                          child: _selectionMode
                              ? _buildSelectionHeader(ctx, provider, memos)
                              : _buildNormalHeader(ctx, provider, memos),
                        ),
                        Expanded(
                          child: memos.isEmpty
                              ? GestureDetector(
                                  // ── 空状態でも右クリックでメニューを出す
                                  //    (= ユーザー要望: メモ欄の何もないところで
                                  //    右クリックすると新規メモを追加できるように) ──
                                  behavior: HitTestBehavior.opaque,
                                  onSecondaryTapDown: (d) =>
                                      _showMemoPanelContextMenu(ctx, provider,
                                          memos, d.globalPosition),
                                  child: Center(
                                    child: Padding(
                                      padding: const EdgeInsets.all(20),
                                      child: Text(
                                        // = ユーザー要望: 空の時は簡潔に。
                                        provider.t('memoList.empty'),
                                        style: TextStyle(
                                            color: Colors.white38,
                                            fontSize: 12),
                                        textAlign: TextAlign.center,
                                      ),
                                    ),
                                  ),
                                )
                              : MouseRegion(
                                  // ── パネルにマウスが乗ったら自動でキーボード
                                  //    フォーカスを取得 → ↑/↓ がメモ移動になり、
                                  //    PDF 本体側にイベントを吸われない。
                                  onEnter: (_) {
                                    if (!_kbdFocusNode.hasFocus) {
                                      _kbdFocusNode.requestFocus();
                                    }
                                  },
                                  child: Builder(builder: (innerCtx) {
                                    // ── メモを「未分類」 + 「各フォルダ」 にグルーピング ──
                                    // 「未分類」 (folder=null or '') のメモは一覧の
                                    // 先頭に直接表示。 フォルダのあるメモは折り畳み
                                    // 可能なヘッダーの下にぶら下げる。
                                    final unfiltered = memos
                                        .where((m) => (m.folder ?? '').isEmpty)
                                        .toList();
                                    final byFolder = <String, List<PdfMemo>>{};
                                    for (final m in memos) {
                                      final f = m.folder ?? '';
                                      if (f.isEmpty) continue;
                                      byFolder.putIfAbsent(f, () => []).add(m);
                                    }
                                    // 空フォルダ (明示作成・メモ 0 件) も一覧に出す
                                    //   (= ユーザー要望「空のフォルダーも作成」)。
                                    for (final f in provider
                                        .getPdfMemoFolders(widget.nodeId)) {
                                      if (f.isNotEmpty) {
                                        byFolder.putIfAbsent(f, () => []);
                                      }
                                    }
                                    // ピン留めフォルダを先頭に、 残りはユーザーが
                                    //   ドラッグで決めた順序 (= provider.getPdfMemoFolders
                                    //   の宣言順) を尊重 (= ユーザー要望: フォルダの
                                    //   位置替えができるように。 以前はアルファベット
                                    //   順だったため reorder しても見た目が変わらな
                                    //   かった)。 未登録フォルダ (メモから自動推測)
                                    //   はリスト末尾に回し、 同順位はアルファベット順。
                                    final pinnedSet = provider
                                        .getPdfMemoPinnedFolders(widget.nodeId)
                                        .toSet();
                                    final declaredOrder = provider
                                        .getPdfMemoFolders(widget.nodeId);
                                    final orderIndex = <String, int>{};
                                    for (int i = 0;
                                        i < declaredOrder.length;
                                        i++) {
                                      orderIndex[declaredOrder[i]] = i;
                                    }
                                    final folderNames = byFolder.keys.toList()
                                      ..sort((a, b) {
                                        final pa = pinnedSet.contains(a);
                                        final pb = pinnedSet.contains(b);
                                        if (pa != pb) return pa ? -1 : 1;
                                        final ai = orderIndex[a] ?? 0x7FFFFFFF;
                                        final bi = orderIndex[b] ?? 0x7FFFFFFF;
                                        if (ai != bi) return ai.compareTo(bi);
                                        return a.compareTo(b);
                                      });
                                    // 表示順を作る (= ↑/↓ キー用 visibleMemos と同じ
                                    //   順番)。 フォルダの top 位置 + 階層を考慮。
                                    // 各ルートフォルダの実効 top 位置を集めて、 同じ
                                    //   位置に複数フォルダがある場合は folderNames
                                    //   の順序を尊重する。
                                    final _rootFoldersForVisible = <String>[];
                                    final _childFoldersForVisible =
                                        <String, List<String>>{};
                                    for (final f in folderNames) {
                                      final lastSlash = f.lastIndexOf('/');
                                      if (lastSlash < 0) {
                                        _rootFoldersForVisible.add(f);
                                      } else {
                                        final parent =
                                            f.substring(0, lastSlash);
                                        if (folderNames.contains(parent)) {
                                          _childFoldersForVisible
                                              .putIfAbsent(
                                                  parent, () => <String>[])
                                              .add(f);
                                        } else {
                                          _rootFoldersForVisible.add(f);
                                        }
                                      }
                                    }
                                    final _foldersByPosForVisible =
                                        <int, List<String>>{};
                                    for (final f in _rootFoldersForVisible) {
                                      var pos =
                                          provider.getPdfMemoFolderTopIndex(
                                                  widget.nodeId, f) ??
                                              unfiltered.length;
                                      pos = pos.clamp(0, unfiltered.length);
                                      _foldersByPosForVisible
                                          .putIfAbsent(pos, () => <String>[])
                                          .add(f);
                                    }
                                    final visibleMemos = <PdfMemo>[];
                                    void collectFolderMemos(String f) {
                                      if (!_expandedFolders.contains(f)) return;
                                      final inside = byFolder[f];
                                      if (inside != null) {
                                        visibleMemos.addAll(inside);
                                      }
                                      final subs = _childFoldersForVisible[f];
                                      if (subs != null) {
                                        for (final sub in subs) {
                                          collectFolderMemos(sub);
                                        }
                                      }
                                    }

                                    for (int i = 0;
                                        i <= unfiltered.length;
                                        i++) {
                                      final fs = _foldersByPosForVisible[i];
                                      if (fs != null) {
                                        for (final f in fs) {
                                          collectFolderMemos(f);
                                        }
                                      }
                                      if (i < unfiltered.length) {
                                        visibleMemos.add(unfiltered[i]);
                                      }
                                    }
                                    // onKeyEvent (↑/↓ / Enter) からも参照できるよう
                                    // state にキャッシュ。 副作用回避のため値が変わる
                                    // ときだけ代入。
                                    _visibleMemos = visibleMemos;
                                    // _focusedIndex を visibleMemos の範囲内に丸める
                                    if (_focusedIndex != null &&
                                        _focusedIndex! >= visibleMemos.length) {
                                      _focusedIndex = visibleMemos.isEmpty
                                          ? null
                                          : visibleMemos.length - 1;
                                    }
                                    // 表示 widget を組み立てる
                                    final children = <Widget>[];
                                    // ── 最上段の「一番上へ」 ドロップゾーン (= ユーザー
                                    //    要望: メモを直接一番上まで持っていけるように) ──
                                    // 一番上のフォルダーが topIndex 0 に貼り付いていると
                                    //   その上にメモを置くスロットが無いため、 ここに
                                    //   落とすと moveMemoToVeryTop で先頭フォルダを下げて
                                    //   メモを最上段にする。 並び替え中だけ出して普段は
                                    //   隙間を作らない (= 下端の受け皿と対称)。
                                    children.add(
                                      SizedBox(
                                        height: _isReordering ? 44.0 : 0.0,
                                        child: _isReordering
                                            ? Stack(
                                                children: [
                                                  // フォルダ受入: 先頭 = topIndex 0
                                                  DragTarget<
                                                      _PdfFolderDragData>(
                                                    onWillAcceptWithDetails:
                                                        (d) => true,
                                                    onAcceptWithDetails: (d) {
                                                      var name = d.data.name;
                                                      if (name.contains('/')) {
                                                        provider
                                                            .movePdfFolderInto(
                                                                widget.nodeId,
                                                                name,
                                                                null);
                                                        name = name
                                                            .split('/')
                                                            .last;
                                                      }
                                                      provider
                                                          .setPdfMemoFolderTopIndex(
                                                              widget.nodeId,
                                                              name,
                                                              0);
                                                    },
                                                    builder: (_, cand, __) {
                                                      return Container(
                                                        decoration: cand
                                                                .isNotEmpty
                                                            ? BoxDecoration(
                                                                color: const Color(
                                                                        0xFF4FC3F7)
                                                                    .withValues(
                                                                        alpha:
                                                                            0.06),
                                                                borderRadius:
                                                                    BorderRadius
                                                                        .circular(
                                                                            8),
                                                                border:
                                                                    Border.all(
                                                                  color: const Color(
                                                                      0xFF4FC3F7),
                                                                  width: 1.5,
                                                                ),
                                                              )
                                                            : null,
                                                      );
                                                    },
                                                  ),
                                                  // メモ受入: 一番上へ
                                                  Positioned.fill(
                                                    child: DragTarget<String>(
                                                      onWillAcceptWithDetails:
                                                          (d) => true,
                                                      onAcceptWithDetails: (d) {
                                                        provider
                                                            .moveMemoToVeryTop(
                                                                widget.nodeId,
                                                                d.data);
                                                      },
                                                      builder: (_, cand, __) {
                                                        return Center(
                                                          child: cand.isNotEmpty
                                                              ? Container(
                                                                  margin: const EdgeInsets
                                                                      .symmetric(
                                                                      horizontal:
                                                                          12),
                                                                  padding: const EdgeInsets
                                                                      .symmetric(
                                                                      horizontal:
                                                                          12,
                                                                      vertical:
                                                                          8),
                                                                  decoration:
                                                                      BoxDecoration(
                                                                    color: const Color(
                                                                            0xFFFFB347)
                                                                        .withValues(
                                                                            alpha:
                                                                                0.18),
                                                                    borderRadius:
                                                                        BorderRadius
                                                                            .circular(6),
                                                                    border:
                                                                        Border
                                                                            .all(
                                                                      color: const Color(
                                                                          0xFFFFB347),
                                                                      width:
                                                                          1.5,
                                                                    ),
                                                                  ),
                                                                  child:
                                                                      const Text(
                                                                    '⬆ 一番上に移動',
                                                                    style:
                                                                        TextStyle(
                                                                      color: Color(
                                                                          0xFFFFB347),
                                                                      fontSize:
                                                                          11,
                                                                      fontWeight:
                                                                          FontWeight
                                                                              .w700,
                                                                    ),
                                                                  ),
                                                                )
                                                              : const SizedBox(),
                                                        );
                                                      },
                                                    ),
                                                  ),
                                                ],
                                              )
                                            : null,
                                      ),
                                    );
                                    // ── unfiltered メモ + フォルダを混在順で描画
                                    //    (= ユーザー要望: フォルダーの位置を同じ階層
                                    //    のメモよりも上に上げたり下に下げたり自由に
                                    //    ドラッグで並び替えできるように) ──
                                    int curVisIdx = 0;
                                    // ── フォルダ階層化対応 ──
                                    // folder 名に slash があれば階層 (例: `親A/子1`)。
                                    //   親が展開状態の時だけ子を表示する。
                                    //   ルート (depth=0) フォルダだけが topIndex で
                                    //   メモと混在配置される。 サブフォルダは親の
                                    //   直下に階層表示。
                                    // 親フォルダ → そのサブフォルダ一覧 を計算。
                                    final childFolders =
                                        <String, List<String>>{};
                                    final rootFolders = <String>[];
                                    for (final f in folderNames) {
                                      final lastSlash = f.lastIndexOf('/');
                                      if (lastSlash < 0) {
                                        rootFolders.add(f);
                                      } else {
                                        final parent =
                                            f.substring(0, lastSlash);
                                        // 親が folderNames に存在しなければ root として
                                        //   扱う (= orphan / 自動推測ケース)。
                                        if (folderNames.contains(parent)) {
                                          childFolders
                                              .putIfAbsent(
                                                  parent, () => <String>[])
                                              .add(f);
                                        } else {
                                          rootFolders.add(f);
                                        }
                                      }
                                    }
                                    void emitFolder(String f, {int depth = 0}) {
                                      final inside =
                                          byFolder[f] ?? const <PdfMemo>[];
                                      final expanded =
                                          _expandedFolders.contains(f);
                                      children.add(_buildFolderHeader(ctx,
                                          provider, f, inside.length, expanded,
                                          depth: depth));
                                      if (expanded) {
                                        // 直下のメモ (= 階層分インデント。 親フォルダ
                                        //   と視覚的に揃え、 サブフォルダの所属が
                                        //   見て分かるように)
                                        final double memoIndent =
                                            (depth + 1) * 28.0;
                                        for (final m in inside) {
                                          children.add(Padding(
                                            padding: EdgeInsets.only(
                                                left: memoIndent),
                                            child: _buildMemoTileWidget(
                                                ctx,
                                                provider,
                                                memos,
                                                m,
                                                curVisIdx,
                                                visibleMemos),
                                          ));
                                          curVisIdx++;
                                        }
                                        // サブフォルダを再帰的に
                                        final subs = childFolders[f];
                                        if (subs != null) {
                                          for (final sub in subs) {
                                            emitFolder(sub, depth: depth + 1);
                                          }
                                        }
                                      }
                                    }

                                    // 各 ROOT フォルダの実効 top 位置を集めて、 同じ
                                    //   位置に複数フォルダがある場合は folderNames の
                                    //   順序を尊重する。
                                    final foldersByPos = <int, List<String>>{};
                                    for (final f in rootFolders) {
                                      var pos =
                                          provider.getPdfMemoFolderTopIndex(
                                                  widget.nodeId, f) ??
                                              unfiltered.length;
                                      pos = pos.clamp(0, unfiltered.length);
                                      foldersByPos
                                          .putIfAbsent(pos, () => <String>[])
                                          .add(f);
                                    }
                                    for (int i = 0;
                                        i <= unfiltered.length;
                                        i++) {
                                      // 位置 i に紐づくフォルダを emit
                                      final fs = foldersByPos[i];
                                      if (fs != null) {
                                        for (final f in fs) {
                                          emitFolder(f);
                                        }
                                      }
                                      // 位置 i のメモを emit (i == unfiltered.length は無)
                                      if (i < unfiltered.length) {
                                        final m = unfiltered[i];
                                        final memoIdx = i;
                                        final tile = _buildMemoTileWidget(
                                            ctx,
                                            provider,
                                            memos,
                                            m,
                                            curVisIdx,
                                            visibleMemos);
                                        // ── フォルダドロップ位置を Y 座標で「上半分=
                                        //    メモの上に挿入 / 下半分=メモの下に挿入」
                                        //    で判定 (= ユーザー要望: フォルダー1、
                                        //    メモ、 フォルダー2 の順から メモ、
                                        //    フォルダー1、 フォルダー2 の順に並べら
                                        //    れるように) ──
                                        // ── フォルダドロップ + メモドロップを両方
                                        //    受け入れる挿入線 (= ユーザー要望: メモも
                                        //    ドラッグで自由に上下を入れ替えられるように) ──
                                        // 縦に 2 段の DragTarget。 上段は memoIdx
                                        //   (= 上に挿入)、 下段は memoIdx+1 (= 下に挿入)。
                                        Widget dropZone({
                                          required int insertPos,
                                          required bool top,
                                        }) {
                                          return Stack(
                                            children: [
                                              // フォルダ受入
                                              DragTarget<_PdfFolderDragData>(
                                                onWillAcceptWithDetails: (d) =>
                                                    true,
                                                onAcceptWithDetails: (d) {
                                                  // ── サブフォルダがドロップされたら
                                                  //    自動的に親解除してルート化
                                                  //    (= ユーザー要望: ドラッグで
                                                  //    上の階層に行けるように) ──
                                                  var name = d.data.name;
                                                  if (name.contains('/')) {
                                                    provider.movePdfFolderInto(
                                                        widget.nodeId,
                                                        name,
                                                        null);
                                                    // 親解除でフォルダ名が変わるので、
                                                    //   新しいルート名で topIndex を
                                                    //   設定する。
                                                    name = name.split('/').last;
                                                  }
                                                  provider
                                                      .setPdfMemoFolderTopIndex(
                                                          widget.nodeId,
                                                          name,
                                                          insertPos);
                                                },
                                                builder: (_, cand, __) {
                                                  // ── 隙間は普段詰めて、 並び替え中
                                                  //    だけ挿入候補として開く (= ユーザー
                                                  //    要望) ──
                                                  return SizedBox(
                                                    height: _isReordering
                                                        ? 12.0
                                                        : 2.0,
                                                    child: cand.isNotEmpty
                                                        ? Center(
                                                            child: Container(
                                                              height: 3,
                                                              margin:
                                                                  const EdgeInsets
                                                                      .symmetric(
                                                                      horizontal:
                                                                          12),
                                                              decoration:
                                                                  BoxDecoration(
                                                                color: const Color(
                                                                    0xFF4FC3F7),
                                                                borderRadius:
                                                                    BorderRadius
                                                                        .circular(
                                                                            2),
                                                              ),
                                                            ),
                                                          )
                                                        : null,
                                                  );
                                                },
                                              ),
                                              // メモ受入 (= ユーザー要望: メモも
                                              //   ドラッグで上下入れ替え)
                                              Positioned.fill(
                                                child: DragTarget<String>(
                                                  onWillAcceptWithDetails:
                                                      (d) => d.data != m.id,
                                                  onAcceptWithDetails: (d) {
                                                    provider
                                                        .reorderPdfMemoToUnfilteredIndex(
                                                            widget.nodeId,
                                                            d.data,
                                                            insertPos);
                                                  },
                                                  builder: (_, cand, __) {
                                                    return SizedBox(
                                                      height: 12,
                                                      child: cand.isNotEmpty
                                                          ? Center(
                                                              child: Container(
                                                                height: 3,
                                                                margin: const EdgeInsets
                                                                    .symmetric(
                                                                    horizontal:
                                                                        12),
                                                                decoration:
                                                                    BoxDecoration(
                                                                  color: const Color(
                                                                      0xFFFFB347),
                                                                  borderRadius:
                                                                      BorderRadius
                                                                          .circular(
                                                                              2),
                                                                ),
                                                              ),
                                                            )
                                                          : null,
                                                    );
                                                  },
                                                ),
                                              ),
                                            ],
                                          );
                                        }

                                        // メモタイル自身は _buildMemoTileWidget 内で
                                        //   既に Draggable<String>(data: m.id) として
                                        //   ラップ済み。 ここでは追加でラップしない。
                                        children.add(Column(
                                          mainAxisSize: MainAxisSize.min,
                                          children: [
                                            dropZone(
                                                insertPos: memoIdx, top: true),
                                            tile,
                                            dropZone(
                                                insertPos: memoIdx + 1,
                                                top: false),
                                          ],
                                        ));
                                        curVisIdx++;
                                      }
                                    }
                                    // ── 最下段の空白ドロップゾーン (= ユーザー要望:
                                    //    一番下の何もない所にドラッグしても上の階層
                                    //    に上がれるように) ──
                                    // 高さ 180px の透明エリアを最後に追加。 メモも
                                    //   フォルダも受け入れ、 リスト末尾 (=未分類化) に
                                    //   配置する。
                                    children.add(
                                      SizedBox(
                                        // 並び替え中だけ広い受け皿に、 普段は
                                        //   下部の余白を詰める (= ユーザー要望)。
                                        height: _isReordering ? 180.0 : 40.0,
                                        child: Stack(
                                          children: [
                                            // フォルダ受入: 末尾 = unfiltered.length
                                            DragTarget<_PdfFolderDragData>(
                                              onWillAcceptWithDetails: (d) =>
                                                  true,
                                              onAcceptWithDetails: (d) {
                                                var name = d.data.name;
                                                if (name.contains('/')) {
                                                  provider.movePdfFolderInto(
                                                      widget.nodeId,
                                                      name,
                                                      null);
                                                  name = name.split('/').last;
                                                }
                                                provider
                                                    .setPdfMemoFolderTopIndex(
                                                        widget.nodeId,
                                                        name,
                                                        unfiltered.length);
                                              },
                                              builder: (_, cand, __) {
                                                return Container(
                                                  decoration: cand.isNotEmpty
                                                      ? BoxDecoration(
                                                          color: const Color(
                                                                  0xFF4FC3F7)
                                                              .withValues(
                                                                  alpha: 0.06),
                                                          borderRadius:
                                                              BorderRadius
                                                                  .circular(8),
                                                          border: Border.all(
                                                            color: const Color(
                                                                0xFF4FC3F7),
                                                            width: 1.5,
                                                          ),
                                                        )
                                                      : null,
                                                );
                                              },
                                            ),
                                            // メモ受入: 一番下 (= 最下段フォルダー
                                            //   よりさらに下) へ移動する。
                                            Positioned.fill(
                                              child: DragTarget<String>(
                                                onWillAcceptWithDetails: (d) =>
                                                    true,
                                                onAcceptWithDetails: (d) {
                                                  // 末尾フォルダーをメモの上へ押し
                                                  //   上げて、 メモを最下段に置く
                                                  //   (= ユーザー要望)。
                                                  provider.moveMemoToVeryBottom(
                                                      widget.nodeId, d.data);
                                                },
                                                builder: (_, cand, __) {
                                                  return Center(
                                                    child: cand.isNotEmpty
                                                        ? Container(
                                                            margin:
                                                                const EdgeInsets
                                                                    .symmetric(
                                                                    horizontal:
                                                                        12),
                                                            padding:
                                                                const EdgeInsets
                                                                    .symmetric(
                                                                    horizontal:
                                                                        12,
                                                                    vertical:
                                                                        8),
                                                            decoration:
                                                                BoxDecoration(
                                                              color: const Color(
                                                                      0xFFFFB347)
                                                                  .withValues(
                                                                      alpha:
                                                                          0.18),
                                                              borderRadius:
                                                                  BorderRadius
                                                                      .circular(
                                                                          6),
                                                              border:
                                                                  Border.all(
                                                                color: const Color(
                                                                    0xFFFFB347),
                                                                width: 1.5,
                                                              ),
                                                            ),
                                                            child: const Text(
                                                              '⬇ 一番下に移動',
                                                              style: TextStyle(
                                                                color: Color(
                                                                    0xFFFFB347),
                                                                fontSize: 11,
                                                                fontWeight:
                                                                    FontWeight
                                                                        .w700,
                                                              ),
                                                            ),
                                                          )
                                                        : const SizedBox(),
                                                  );
                                                },
                                              ),
                                            ),
                                          ],
                                        ),
                                      ),
                                    );
                                    return NotificationListener<
                                        ScrollNotification>(
                                      // ── メモ欄のスクロールが PDF 本体に連動して
                                      //    PDF まで動いてしまう問題への対応 ──
                                      //    (ユーザー要望)。ここで ScrollNotification を
                                      //    止め、祖先 (PDF ビューア) へ伝播させない。
                                      onNotification: (_) => true,
                                      // ── メモ欄の何もないところで右クリック →
                                      //    新規メモ / フォルダ作成メニュー (= ユーザー
                                      //    要望) ──
                                      // onSecondaryTapDown だけを宣言するので、 通常
                                      //   タップ / スクロールは下の ListView に通る。
                                      //   メモタイル自体は右クリックを扱わないので、
                                      //   タイル上で右クリックしてもこのメニューが出る。
                                      child: Listener(
                                        // ── マウスホイールは ListView をそのまま
                                        //    スクロールするだけ (= ユーザー要望: スク
                                        //    ロールしただけでは選択メモ/フォルダは
                                        //    変えない)。 以前はホイールで _moveFocusedMemo
                                        //    を呼んでフォーカスを移動していたが廃止。
                                        child: GestureDetector(
                                          behavior: HitTestBehavior.translucent,
                                          // 何もない所をタップしたらフォルダ/メモの選択を
                                          //   解除 (= ユーザー要望)。 タイル上のタップは
                                          //   各タイルの onTap が先に消費するのでここには
                                          //   来ない (= 空白部分のみ反応)。
                                          onTap: _clearMemoSelection,
                                          onSecondaryTapDown: (d) =>
                                              _showMemoPanelContextMenu(
                                                  ctx,
                                                  provider,
                                                  memos,
                                                  d.globalPosition),
                                          child: ListView(
                                            controller: _memoListScrollCtrl,
                                            // ホイールはフォーカス移動に使うため、
                                            //   ListView 自体のネイティブスクロールは
                                            //   無効化 (= 二重スクロール防止)。 タッチ
                                            //   ドラッグもフォーカス移動と競合するので
                                            //   ここでは physics を切り、 表示位置は
                                            //   _scrollFocusedMemoIntoView が制御する。
                                            physics:
                                                const ClampingScrollPhysics(),
                                            padding: const EdgeInsets.symmetric(
                                                vertical: 6),
                                            children: children,
                                          ),
                                        ),
                                      ),
                                    );
                                  }),
                                ),
                        ),
                      ],
                    ),
                    // ── 通知バナー (パネル内オーバーレイ) ──
                    // viewer ダイアログ越しに SnackBar が見えないので、
                    // パネル内でアニメーション付きのバナーを直接出す。
                    if (_bannerText != null)
                      Positioned(
                        left: 8,
                        right: 8,
                        // ヘッダー (高さ 44) と被らないよう、その下に表示する。
                        top: 52,
                        child: AnimatedSlide(
                          offset: Offset.zero,
                          duration: const Duration(milliseconds: 220),
                          child: AnimatedOpacity(
                            opacity: _bannerText != null ? 1.0 : 0.0,
                            duration: const Duration(milliseconds: 220),
                            child: Material(
                              color: Colors.transparent,
                              child: Container(
                                padding: const EdgeInsets.symmetric(
                                    horizontal: 12, vertical: 10),
                                decoration: BoxDecoration(
                                  color: _bannerColor.withValues(alpha: 0.95),
                                  borderRadius: BorderRadius.circular(8),
                                  boxShadow: [
                                    BoxShadow(
                                      color:
                                          Colors.black.withValues(alpha: 0.35),
                                      blurRadius: 8,
                                      offset: const Offset(0, 2),
                                    ),
                                  ],
                                ),
                                child: Row(
                                  children: [
                                    const Icon(
                                      Icons.check_circle_rounded,
                                      color: Colors.white,
                                      size: 18,
                                    ),
                                    const SizedBox(width: 8),
                                    Expanded(
                                      child: Text(
                                        _bannerText ?? '',
                                        style: const TextStyle(
                                          color: Colors.white,
                                          fontSize: 12.5,
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ),
                          ),
                        ),
                      ),
                  ],
                ),
              );
            },
          ),
        );
      },
    );
  }

  /// 階層化メモリストの 1 行: 個別の `_PdfMemoTile` をラップして
  /// グルーピング後のインデックス (= visibleMemos 中の位置) と
  /// 元の memos リストでのインデックスを橋渡しする。
  /// ドラッグ中に指先 (カーソル) に追従して表示されるメモのプレビュー。
  Widget _memoDragFeedback(PdfMemo m) {
    return Material(
      color: Colors.transparent,
      child: Container(
        constraints: const BoxConstraints(maxWidth: 280),
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
        decoration: BoxDecoration(
          color: const Color(0xFF2A2A40),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: const Color(0xFF4FC3F7), width: 1.5),
        ),
        child: Text(
          m.text.trim().isEmpty
              ? context.read<MindMapProvider>().t('memoList.emptyMemo')
              : m.text.split('\n').first,
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: const TextStyle(color: Colors.white, fontSize: 13),
        ),
      ),
    );
  }

  Widget _buildMemoTileWidget(
      BuildContext ctx,
      MindMapProvider provider,
      List<PdfMemo> allMemos,
      PdfMemo m,
      int visIdx,
      List<PdfMemo> visibleMemos) {
    // 元 memos での位置 (= Shift 範囲選択の起点として使う)
    final fullIdx = allMemos.indexWhere((x) => x.id == m.id);
    // ── ダブルクリックでインライン編集中: その場で TextField を表示 ──
    if (_inlineEditingMemoId == m.id) {
      return TapRegion(
        // ── 他の箇所をクリックしたら編集モードを解除 (= ユーザー要望:
        //    また他の箇所をクリックしたら選択モードが解除されるように) ──
        // TapRegion 外側のタップで現在のテキストを保存して編集終了。
        onTapOutside: (_) {
          if (_inlineEditingMemoId == m.id) {
            _commitInlineEdit(provider);
          }
        },
        child: Container(
          margin: const EdgeInsets.symmetric(horizontal: 6, vertical: 0),
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
          decoration: BoxDecoration(
            color: const Color(0xFF4FC3F7).withValues(alpha: 0.10),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: const Color(0xFF4FC3F7), width: 1.5),
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              // ── 画像プレビュー (= ユーザー要望: 画像を貼り付けたメモに
              //    何かテキストを加えたりできるように) ──
              // 編集中も画像を見せて、 何の画像に対するキャプションを書いて
              //   いるか分かるようにする。
              Builder(builder: (_) {
                final (imgPath, _) = _parseMemoImage(m.text);
                if (imgPath == null ||
                    imgPath.isEmpty ||
                    !File(imgPath).existsSync()) {
                  return const SizedBox.shrink();
                }
                return Padding(
                  padding: const EdgeInsets.only(bottom: 6),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(6),
                    child: ConstrainedBox(
                      constraints: const BoxConstraints(maxHeight: 160),
                      // cacheWidth で表示サイズに縮小して復号しメモリを節約
                      //   (= ユーザー要望: メモのメモリ使用量を極限まで抑える)。
                      child: Image.file(
                        File(imgPath),
                        fit: BoxFit.contain,
                        gaplessPlayback: true,
                        cacheWidth: 600,
                        filterQuality: FilterQuality.low,
                        errorBuilder: (_, __, ___) => const SizedBox.shrink(),
                      ),
                    ),
                  ),
                );
              }),
              Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Expanded(
                    child: Focus(
                      // ── Enter で確定、 Shift+Enter で改行 (= ユーザー要望:
                      //    ダブルクリックで入力後 Enter で確定) ──
                      // multiline TextField は onSubmitted が Enter で発火せず
                      //   改行が入ってしまうため、 ここで物理 Enter を横取りして
                      //   確定する。 Shift 併用時は改行として通す。
                      // canRequestFocus:false で子 TextField のフォーカスを奪わない。
                      canRequestFocus: false,
                      skipTraversal: true,
                      onKeyEvent: (node, event) {
                        if (event is! KeyDownEvent) {
                          return KeyEventResult.ignored;
                        }
                        // ── 上下キー: メモ編集中は TextField 内のカーソル (行) 移動
                        //    に使う (= ユーザー要望: 行が変わらずメモが変わるのは
                        //    使いにくい → 行が変わるだけにして)。 ここでは横取りせず
                        //    標準のテキスト編集 (カーソル行移動) に委ねるため、 上下キーは
                        //    そのまま ignored を返して通過させる。
                        // Enter (Shift なし): 確定
                        if ((event.logicalKey == LogicalKeyboardKey.enter ||
                                event.logicalKey ==
                                    LogicalKeyboardKey.numpadEnter) &&
                            !HardwareKeyboard.instance.isShiftPressed) {
                          _commitInlineEdit(provider);
                          return KeyEventResult.handled;
                        }
                        return KeyEventResult.ignored;
                      },
                      child: TextField(
                        controller: _inlineEditCtrl,
                        focusNode: _inlineEditFocus,
                        autofocus: true,
                        maxLines: null,
                        minLines: 1,
                        keyboardType: TextInputType.multiline,
                        textInputAction: TextInputAction.newline,
                        style: const TextStyle(
                            color: Colors.white, fontSize: 13, height: 1.4),
                        cursorColor: const Color(0xFF4FC3F7),
                        decoration: InputDecoration(
                          isDense: true,
                          border: InputBorder.none,
                          hintText: context
                              .read<MindMapProvider>()
                              .t('pmemo.inputHint'),
                          hintStyle:
                              TextStyle(color: Colors.white38, fontSize: 13),
                        ),
                        // モバイル等で onSubmitted が発火するケースの保険。
                        onSubmitted: (_) => _commitInlineEdit(provider),
                      ),
                    ),
                  ),
                  IconButton(
                    tooltip: context.read<MindMapProvider>().t('btn.save'),
                    icon: const Icon(Icons.check_rounded,
                        color: Color(0xFF43B97F), size: 18),
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 26, minHeight: 26),
                    onPressed: () => _commitInlineEdit(provider),
                  ),
                  IconButton(
                    tooltip: context.read<MindMapProvider>().t('btn.cancel'),
                    icon: const Icon(Icons.close_rounded,
                        color: Color(0xFFE57373), size: 18),
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 26, minHeight: 26),
                    onPressed: _cancelInlineEdit,
                  ),
                ],
              ),
            ],
          ),
        ),
      );
    }
    final rawTile = _PdfMemoTile(
      memo: m,
      // ダブルクリックでインライン編集を開始 (= ユーザー要望: ダブル
      //   クリックでメモの中身を入力できるように)。確定は Enter または
      //   チェックボタン (下の TextField の Focus.onKeyEvent で Enter 確定)。
      onDoubleTap: () => _beginInlineEdit(m),
      onMoveUp: () => provider.movePdfMemoUp(widget.nodeId, m.id),
      onMoveDown: () => provider.movePdfMemoDown(widget.nodeId, m.id),
      highlighted: m.id == widget.highlightMemoId,
      // ↑/↓ でフォーカスされた行を視覚的に区別 (visibleMemos での位置)
      focused: _focusedIndex == visIdx,
      selectionMode: _selectionMode,
      selected: _selectedIds.contains(m.id),
      onTap: () {
        // タップでフォーカスも合わせる
        if (!_selectionMode && _focusedIndex != visIdx) {
          setState(() => _focusedIndex = visIdx);
        }
        // メモタップ時はフォルダフォーカスを解除 (= ユーザー要望: 他の
        //   箇所をクリックしたら選択モードが解除されるように)
        if (_focusedFolder != null) {
          setState(() => _focusedFolder = null);
        }
        if (_selectionMode) {
          if (_isShiftPressed() && _lastSelectedIndex != null) {
            final from =
                _lastSelectedIndex! < fullIdx ? _lastSelectedIndex! : fullIdx;
            final to =
                _lastSelectedIndex! < fullIdx ? fullIdx : _lastSelectedIndex!;
            setState(() {
              for (int k = from; k <= to; k++) {
                _selectedIds.add(allMemos[k].id);
              }
              _lastSelectedIndex = fullIdx;
            });
          } else {
            setState(() {
              _toggleSelection(m.id);
              _lastSelectedIndex = fullIdx;
            });
          }
          // ── 選択モード中はタップ後もキーボードフォーカスをパネルに
          //    戻す (= ユーザー要望: 選択モード中の Esc でビューワーごと
          //    閉じてしまうのを防ぐ。 Esc をパネルが捕まえられるように
          //    フォーカスを保持する) ──
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (mounted) _kbdFocusNode.requestFocus();
          });
        } else if (_isCtrlOrCmdPressed() || _isShiftPressed()) {
          setState(() {
            _selectionMode = true;
            _selectedIds.add(m.id);
            _lastSelectedIndex = fullIdx;
          });
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (mounted) _kbdFocusNode.requestFocus();
          });
        } else {
          // ── 単一クリックでフォーカスも設定 (= ユーザー要望: メモを
          //    クリックしてそのまま Backspace/Del で削除できるように) ──
          // これで _focusedIndex がセットされ、 onKeyEvent の削除分岐が
          //   効くようになる。 マウスホバーで既にパネルへキーボード
          //   フォーカスが当たっているので、 そのまま Del が届く。
          setState(() => _focusedIndex = visIdx);
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (mounted) _kbdFocusNode.requestFocus();
          });
          widget.onJumpToMemo(m);
        }
      },
      // ── 中央にダイアログを出さず、 メモ欄の中でそのまま書く
      //    (= ユーザー要望)。 ダブルクリックと同じ入口にする。 ──
      onEdit: () => _beginInlineEdit(m),
      onDelete: () => provider.removePdfMemo(widget.nodeId, m.id),
      // ユーザー要望: 小さなフローティング箱ではなく、いきなりメモ欄を
      //   覆う形で検索を出す → _dockedGoogleSearchNotifier に直接セット。
      //   (_PdfMemoPanelState.build が監視し、メモ一覧の代わりに検索
      //    WebView をパネル全体に表示する)
      onSearchGoogle: () {
        final q = _extractSearchQuery(m.text).trim();
        if (q.isEmpty) {
          // 画像だけのメモは検索する言葉が無い (= ユーザー要望: 押しても
          // 何も起きないのではなく、 空だと知らせる)。
          _showInlineBanner('テキストが空です',
              color: const Color(0xFFFF6B6B));
          return;
        }
        final url =
            'https://www.google.com/search?q=${Uri.encodeQueryComponent(q)}';
        _dockedGoogleSearchNotifier.value =
            _DockedGoogleSearchState(query: q, url: url);
      },
      onSendToMap: () => _exportMemoToMap(ctx, provider, m),
      onTogglePinned: () => provider.togglePdfMemoPinned(widget.nodeId, m.id),
      // AI チャット欄に送る (= ユーザー要望)。 widget.onSendMemoToAi が
      //   渡されていれば対応ボタンが表示され、 タップで親のコールバック発火。
      onSendToAi: widget.onSendMemoToAi == null
          ? null
          : () => widget.onSendMemoToAi!(m),
      // メモの本文で YouTube 検索 (= ユーザー要望)。
      onSearchYoutube: widget.onSearchYoutube == null
          ? null
          : () {
              final (_, body) = _parseMemoImage(m.text);
              if (body.trim().isEmpty) {
                // 画像だけのメモは検索できない (= ユーザー要望)。
                _showInlineBanner('テキストが空です',
                    color: const Color(0xFFFF6B6B));
                return;
              }
              widget.onSearchYoutube!(m);
            },
      // ── メモをフラッシュカードに登録 (= ユーザー要望: メモ全般に登録機能) ──
      // 表面 = メモ本文、 裏面 = 空 (後で編集 / 「裏面を AI 生成」 で補完)。
      onRegisterFlashcard: () async {
        final (_, body) = _parseMemoImage(m.text);
        final front = body.trim();
        if (front.isEmpty) {
          _showInlineBanner('本文が空のためフラッシュカードにできません',
              color: const Color(0xFFFF6B6B));
          return;
        }
        final pageId = context.read<MindMapProvider>().currentPage.id;
        await _FlashcardStore.add(pageId, (
          front: front,
          back: '',
          group: '',
          global: false,
          image: '',
          imageSide: 'front'
        ));
        if (mounted) {
          _showInlineBanner('🃏 フラッシュカードに登録しました（裏面は後で編集/AI生成）',
              color: const Color(0xFF26C6DA));
        }
      },
      // 上の階層に戻す (= ユーザー要望)。 メモが何らかのフォルダに入って
      //   いる時だけボタンを表示。
      onMoveUpHierarchy: (m.folder == null || m.folder!.isEmpty)
          ? null
          : () {
              final cur = m.folder!;
              final lastSlash = cur.lastIndexOf('/');
              final newFolder =
                  lastSlash < 0 ? null : cur.substring(0, lastSlash);
              provider.movePdfMemo(widget.nodeId, m.id, folder: newFolder);
            },
      // クイズメモの解答開示状態
      quizRevealed: _revealedQuizMemos.contains(m.id),
      onToggleQuizReveal: () {
        setState(() {
          if (_revealedQuizMemos.contains(m.id)) {
            _revealedQuizMemos.remove(m.id);
          } else {
            _revealedQuizMemos.add(m.id);
          }
        });
      },
      // 自分の解答入力 + 答え合わせ
      quizAnswerCtrl: _quizAnswerCtrl(m.id),
      quizCheckResult: _quizCheckResults[m.id],
      canAutoCheckQuiz: _extractQuizCanonicalAnswer(m.text) != null,
      onCheckQuizAnswer: () {
        final canonical = _extractQuizCanonicalAnswer(m.text);
        if (canonical == null) return;
        final user = _quizAnswerCtrl(m.id).text;
        setState(() {
          _quizCheckResults[m.id] = _checkQuizAnswer(user, canonical);
          // 答え合わせと同時に解答も開示する (= UX 向上)
          _revealedQuizMemos.add(m.id);
        });
      },
    );
    // 右クリック (デスクトップ) で削除 / 編集メニュー (= ユーザー要望)。
    final tile = GestureDetector(
      behavior: HitTestBehavior.translucent,
      onSecondaryTapDown: (d) =>
          _showPdfMemoCtxMenu(ctx, provider, m, d.globalPosition),
      child: rawTile,
    );
    // ── ドラッグでメモを自由に並び替え / フォルダ移動 (= 階層/位置移動) ──
    // 長押しでドラッグ開始。このタイルにドロップ → このタイルの直前
    //   (同じ folder 内) へ挿入。フォルダヘッダーにドロップ → そのフォルダへ。
    return DragTarget<String>(
      onWillAcceptWithDetails: (d) => d.data != m.id,
      onAcceptWithDetails: (d) {
        provider.movePdfMemo(widget.nodeId, d.data,
            folder: m.folder, beforeId: m.id);
      },
      builder: (dctx, candidate, rejected) {
        final hover = candidate.isNotEmpty;
        return Container(
          decoration: hover
              ? const BoxDecoration(
                  border: Border(
                      top: BorderSide(color: Color(0xFF4FC3F7), width: 2)))
              : null,
          child: (Platform.isWindows || Platform.isMacOS || Platform.isLinux)
              // デスクトップ: 長押し不要で即ドラッグして並び替え
              //   (= ユーザー要望「ドラッグしたら自由に位置を変えられる」)。
              //   一覧スクロールはマウスホイールなので競合しない。
              ? Draggable<String>(
                  data: m.id,
                  // ── 並び替え中フラグ: ドラッグ中だけ挿入用の隙間を開く ──
                  onDragStarted: () => _setReordering(true),
                  onDragEnd: (_) => _setReordering(false),
                  onDraggableCanceled: (_, __) => _setReordering(false),
                  onDragCompleted: () => _setReordering(false),
                  feedback: _memoDragFeedback(m),
                  childWhenDragging: Opacity(opacity: 0.35, child: tile),
                  child: tile,
                )
              // モバイル: 一覧の指スクロールと競合しないよう長押しドラッグ。
              : LongPressDraggable<String>(
                  data: m.id,
                  onDragStarted: () => _setReordering(true),
                  onDragEnd: (_) => _setReordering(false),
                  onDraggableCanceled: (_, __) => _setReordering(false),
                  onDragCompleted: () => _setReordering(false),
                  feedback: _memoDragFeedback(m),
                  childWhenDragging: Opacity(opacity: 0.35, child: tile),
                  child: tile,
                ),
        );
      },
    );
  }

  /// フォルダ折り畳みヘッダー: タップで展開/折り畳み切替。
  /// 紫の📁アイコン + フォルダ名 + メモ件数 + 展開状態の▶/▼。
  Widget _buildFolderHeader(BuildContext ctx, MindMapProvider provider,
      String folder, int count, bool expanded,
      {int depth = 0}) {
    final isFocused = _focusedFolder == folder;
    // ── 階層化対応 (= ユーザー要望: フォルダーの中にもフォルダーを作成
    //    できるように) ──
    // フォルダ名は slash 区切りで階層を表現 (例: `親A/子1`)。 ヘッダー
    //   描画時の表示名は最後の `/` より後ろの部分のみ。 [depth] でインデント。
    final displayName = folder.contains('/') ? folder.split('/').last : folder;
    // 階層インデント量 (= ユーザー要望: サブ階層は少しだけ左側に余白を入れて
    //   右に寄せて分かるように)。 28px/階層で十分視覚的に分かる。
    final double indent = depth * 28.0;
    // ── ヘッダーの本体 (装飾済みコンテナ + Row 中身) ──
    // ユーザー要望:
    //   - ドラッグは左端のつまみを掴んだ時だけ反応するように
    //   - フォルダはワンクリックで開閉できるように (= ダブルクリック不要)
    //   - 削除ボタンは廃止 (Backspace/Del で代用)
    // なので、 LongPressDraggable は「つまみ部分だけ」 に巻く形に変更。
    // 本体 Row 全体の InkWell.onTap で開閉する (= シングルクリック反応)。
    // ドラッグフィードバック用 (= ドラッグ中の浮遊コピー) と通常表示で同じ
    //   見た目を共有するため buildBody は引数で chrome の有無を選べる形に。
    Widget buildBody({required bool showHandle, bool dim = false}) {
      return Container(
        margin:
            EdgeInsets.only(left: 6.0 + indent, right: 6, top: 0, bottom: 0),
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
        decoration: BoxDecoration(
          color: expanded
              ? const Color(0xFF6C63FF).withValues(alpha: 0.20)
              : const Color(0xFF6C63FF).withValues(alpha: 0.10),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(
              color: isFocused
                  ? const Color(0xFFFFC107)
                  : const Color(0xFF6C63FF).withValues(alpha: 0.45),
              width: isFocused ? 2 : 1),
        ),
        child: Opacity(
          opacity: dim ? 0.6 : 1.0,
          // ── 2 行構成 (= ユーザー要望: フォルダもメモと同じようにボタンと
          //    名前を違う行に書いて欲しい) ──
          // 1 行目: ▶/▼ + 📁 + フォルダ名 + 件数バッジ
          // 2 行目: アクションボタン群 (サブフォルダ作成 / 上の階層 / メモ追加 /
          //                          ピン留め / マップに出す)
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            mainAxisSize: MainAxisSize.min,
            children: [
              // ── 1 行目: フォルダ名 ──
              Row(children: [
                // 展開状態の三角アイコン (▶ / ▼)
                AnimatedRotation(
                  turns: expanded ? 0.25 : 0,
                  duration: const Duration(milliseconds: 180),
                  child: const Icon(Icons.play_arrow_rounded,
                      color: Color(0xFF6C63FF), size: 18),
                ),
                const SizedBox(width: 4),
                Icon(
                    expanded ? Icons.folder_open_rounded : Icons.folder_rounded,
                    color: const Color(0xFF6C63FF),
                    size: 18),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(displayName,
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 13,
                          fontWeight: FontWeight.w700),
                      overflow: TextOverflow.ellipsis),
                ),
                // 件数バッジ
                Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                  decoration: BoxDecoration(
                    color: const Color(0xFF6C63FF).withValues(alpha: 0.3),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: Text(
                      context
                          .read<MindMapProvider>()
                          .t('common.itemsN')
                          .replaceFirst('{n}', '$count'),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 11,
                          fontWeight: FontWeight.w600)),
                ),
              ]),
              const SizedBox(height: 2),
              // ── 2 行目: アクションボタン群 ──
              Row(children: [
                // サブフォルダを作成
                IconButton(
                  tooltip: context
                      .read<MindMapProvider>()
                      .t('pmemo.createSubfolder'),
                  icon: const Icon(Icons.create_new_folder_outlined,
                      color: Color(0xFF6C63FF), size: 16),
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints(minWidth: 28, minHeight: 28),
                  onPressed: () => _showQuickCreateFolderDialog(ctx, provider,
                      parent: folder),
                ),
                // 上の階層に戻す (= サブフォルダのみ表示)
                if (folder.contains('/'))
                  IconButton(
                    tooltip: context.read<MindMapProvider>().t('pmemo.goUp'),
                    icon: const Icon(Icons.subdirectory_arrow_left_rounded,
                        color: Color(0xFFFFB347), size: 16),
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 28, minHeight: 28),
                    onPressed: () {
                      final lastSlash = folder.lastIndexOf('/');
                      final myParent = folder.substring(0, lastSlash);
                      final grandSlash = myParent.lastIndexOf('/');
                      final newParent = grandSlash < 0
                          ? null
                          : myParent.substring(0, grandSlash);
                      provider.movePdfFolderInto(
                          widget.nodeId, folder, newParent);
                      setState(() {});
                    },
                  ),
                // このフォルダにメモを追加 (VSCode 風 + ボタン)
                IconButton(
                  tooltip:
                      context.read<MindMapProvider>().t('pmemo.addMemoHere'),
                  icon: const Icon(Icons.add_rounded,
                      color: Color(0xFF6C63FF), size: 18),
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints(minWidth: 28, minHeight: 28),
                  onPressed: () => _addMemoToFolder(provider, folder),
                ),
                // ピン留めトグル
                Builder(builder: (_) {
                  final pinned =
                      provider.isPdfMemoFolderPinned(widget.nodeId, folder);
                  return IconButton(
                    tooltip: pinned ? 'ピン留めを解除' : 'フォルダをピン留め',
                    icon: Icon(
                        pinned ? Icons.push_pin : Icons.push_pin_outlined,
                        color: pinned
                            ? const Color(0xFFFFC107)
                            : const Color(0xFF6C63FF),
                        size: 16),
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints(minWidth: 28, minHeight: 28),
                    onPressed: () {
                      provider.togglePdfMemoFolderPinned(widget.nodeId, folder);
                      setState(() {});
                    },
                  );
                }),
                // マップに出す
                IconButton(
                  tooltip:
                      context.read<MindMapProvider>().t('pmemo.folderToMap'),
                  icon: const Icon(Icons.account_tree_rounded,
                      color: Color(0xFF6C63FF), size: 16),
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints(minWidth: 28, minHeight: 28),
                  onPressed: () =>
                      _exportFolderToMap(ctx, provider, folder, count),
                ),
                const Spacer(),
              ]),
            ],
          ),
        ),
      );
    }

    // ── DragTarget の 3 層構造 ──
    // 1. 外側: メモのドロップ受け入れ (このフォルダにメモを移動)
    // 2. 本体上下に細い 12px の DropZone を追加 (= フォルダ並び替え)
    //    ROOT フォルダのみ topIndex の前後挿入を行う。 サブフォルダ
    //    (slash を含むフォルダ) では特に動作しない。
    // 3. 本体中央: 別フォルダの「中に入れる」 受け入れ
    //    (= movePdfFolderInto で親変更 = サブフォルダ化、 ユーザー要望)
    // child の InkWell は本体 Row 全体のワンクリックで開閉。
    final isRootFolder = !folder.contains('/');
    int? thisFolderTopIdx = isRootFolder
        ? provider.getPdfMemoFolderTopIndex(widget.nodeId, folder)
        : null;
    // 上下細い挿入線。 ドロップ予定時に水色のラインを表示。
    // [insertPos] が null = このフォルダが topIndex 未設定 (= デフォルト末尾)。
    //   その場合は topIndex の操作はせず、 declaredOrder の reorder だけで
    //   順序を入れ替える (= 同じ topIndex 同士の並び順は declaredOrder で
    //   決まる)。 [isBelow] = true なら「このフォルダの下に挿入」、 false なら
    //   「このフォルダの上に挿入」 を表す。
    Widget folderDropLine({required int? insertPos, required bool isBelow}) {
      return SizedBox(
        // 隙間は普段詰めて、 並び替え (ドラッグ) 中だけ挿入候補として
        //   開く (= ユーザー要望)。
        height: _isReordering ? 12.0 : 2.0,
        child: Stack(
          children: [
            // フォルダ受入 (= 並び替え)
            DragTarget<_PdfFolderDragData>(
              onWillAcceptWithDetails: (d) => d.data.name != folder,
              onAcceptWithDetails: (d) {
                var name = d.data.name;
                if (name.contains('/')) {
                  // サブフォルダなら一旦ルートに引き上げる。
                  provider.movePdfFolderInto(widget.nodeId, name, null);
                  name = name.split('/').last;
                }
                if (insertPos != null) {
                  // このフォルダの topIndex が明示設定されているなら、
                  //   そこに揃える (= 上挿入は同じ、 下挿入は +1)。
                  provider.setPdfMemoFolderTopIndex(
                      widget.nodeId, name, insertPos);
                }
                // declaredOrder 上で並び順を入れ替え。 placeAfter で
                //   「下に挿入」 か「上に挿入」 を切替える (= ユーザー要望:
                //   上からの表示順を入れ替えたりが上手くいかないバグの修正)。
                provider.reorderPdfMemoFolders(widget.nodeId, name, folder,
                    placeAfter: isBelow);
              },
              builder: (_, cand, __) {
                return cand.isNotEmpty
                    ? Center(
                        child: Container(
                          height: 3,
                          margin: const EdgeInsets.symmetric(horizontal: 12),
                          decoration: BoxDecoration(
                            color: const Color(0xFF4FC3F7),
                            borderRadius: BorderRadius.circular(2),
                          ),
                        ),
                      )
                    : const SizedBox.expand();
              },
            ),
            // メモ受入 (= 未分類化してこの位置に挿入 = 上の階層へ移動)
            Positioned.fill(
              child: DragTarget<String>(
                onWillAcceptWithDetails: (d) => true,
                onAcceptWithDetails: (d) {
                  // メモを未分類化してこの位置に挿入。 insertPos が null
                  //   ならリスト末尾扱い (= unfiltered.length 相当)。
                  provider.reorderPdfMemoToUnfilteredIndex(
                      widget.nodeId, d.data, insertPos ?? 0x7FFFFFFF);
                },
                builder: (_, cand, __) {
                  return cand.isNotEmpty
                      ? Center(
                          child: Container(
                            height: 3,
                            margin: const EdgeInsets.symmetric(horizontal: 12),
                            decoration: BoxDecoration(
                              color: const Color(0xFFFFB347),
                              borderRadius: BorderRadius.circular(2),
                            ),
                          ),
                        )
                      : const SizedBox.expand();
                },
              ),
            ),
          ],
        ),
      );
    }

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        // 上挿入ライン: フォルダの topIndex 位置に挿入。
        folderDropLine(insertPos: thisFolderTopIdx, isBelow: false),
        DragTarget<String>(
          onWillAcceptWithDetails: (d) => true,
          onAcceptWithDetails: (d) {
            provider.movePdfMemo(widget.nodeId, d.data, folder: folder);
            setState(() => _expandedFolders.add(folder));
          },
          builder: (dctx, candidate, rejected) {
            return DragTarget<_PdfFolderDragData>(
              onWillAcceptWithDetails: (d) => d.data.name != folder,
              onAcceptWithDetails: (d) {
                // ── 中央ドロップ = フォルダの中に入れる
                //    (= ユーザー要望: フォルダーにフォルダーを
                //    ドラッグ&ドロップで入れられるように) ──
                provider.movePdfFolderInto(widget.nodeId, d.data.name, folder);
                setState(() {
                  _expandedFolders.add(folder);
                });
              },
              builder: (dctx2, candidate2, rejected2) {
                final isDropTarget = candidate2.isNotEmpty;
                // ── フォルダ全体をドラッグできるよう Draggable/LongPress
                //    で包む (= ユーザー要望: 左端のつまみは消して、 メモと
                //    同じ感じでドラッグで自由に位置を変えられるように) ──
                final body = GestureDetector(
                    behavior: HitTestBehavior.translucent,
                    // 右クリックで削除 / 名前変更メニュー (= ユーザー要望)
                    onSecondaryTapDown: (d) => _showPdfFolderCtxMenu(
                        ctx, provider, folder, d.globalPosition),
                    child: Material(
                      color: Colors.transparent,
                      child: InkWell(
                        onTap: () {
                          setState(() {
                            if (expanded) {
                              _expandedFolders.remove(folder);
                            } else {
                              _expandedFolders.add(folder);
                            }
                            _focusedFolder = folder;
                            _focusedIndex = null;
                          });
                          WidgetsBinding.instance.addPostFrameCallback((_) {
                            if (mounted) _kbdFocusNode.requestFocus();
                          });
                        },
                        borderRadius: BorderRadius.circular(8),
                        child: Container(
                          decoration: isDropTarget
                              ? BoxDecoration(
                                  color: const Color(0xFF6C63FF)
                                      .withValues(alpha: 0.18),
                                  borderRadius: BorderRadius.circular(8),
                                  border: Border.all(
                                      color: const Color(0xFF6C63FF), width: 2),
                                )
                              : null,
                          child: Stack(
                            children: [
                              buildBody(showHandle: false),
                              // ホバー中は「中に入れる」 のヒント表示
                              if (isDropTarget)
                                Positioned(
                                  right: 12,
                                  top: 0,
                                  bottom: 0,
                                  child: Center(
                                    child: Container(
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 8, vertical: 4),
                                      decoration: BoxDecoration(
                                        color: const Color(0xFF6C63FF),
                                        borderRadius: BorderRadius.circular(10),
                                      ),
                                      child: const Text(
                                        '📁 中に入れる',
                                        style: TextStyle(
                                            color: Colors.white,
                                            fontSize: 10,
                                            fontWeight: FontWeight.w700),
                                      ),
                                    ),
                                  ),
                                ),
                            ],
                          ),
                        ),
                      ),
                    ));
                // フォルダ全体を Draggable で包む。 デスクトップは即ドラッグ、
                //   モバイルは長押し (= 一覧スクロールとの競合回避)。
                if (Platform.isWindows ||
                    Platform.isMacOS ||
                    Platform.isLinux) {
                  return Draggable<_PdfFolderDragData>(
                    data: _PdfFolderDragData(folder),
                    onDragStarted: () => _setReordering(true),
                    onDragEnd: (_) => _setReordering(false),
                    onDraggableCanceled: (_, __) => _setReordering(false),
                    onDragCompleted: () => _setReordering(false),
                    feedback: Material(
                      color: Colors.transparent,
                      child: Opacity(
                        opacity: 0.7,
                        child: SizedBox(
                            width: 320,
                            child: buildBody(showHandle: false, dim: true)),
                      ),
                    ),
                    childWhenDragging: Opacity(opacity: 0.35, child: body),
                    child: body,
                  );
                } else {
                  return LongPressDraggable<_PdfFolderDragData>(
                    data: _PdfFolderDragData(folder),
                    delay: const Duration(milliseconds: 200),
                    onDragStarted: () => _setReordering(true),
                    onDragEnd: (_) => _setReordering(false),
                    onDraggableCanceled: (_, __) => _setReordering(false),
                    onDragCompleted: () => _setReordering(false),
                    feedback: Material(
                      color: Colors.transparent,
                      child: Opacity(
                        opacity: 0.7,
                        child: SizedBox(
                            width: 320,
                            child: buildBody(showHandle: false, dim: true)),
                      ),
                    ),
                    childWhenDragging: Opacity(opacity: 0.35, child: body),
                    child: body,
                  );
                }
              },
            );
          },
        ),
        // 下挿入ライン (ROOT のみ): フォルダの topIndex+1 位置に挿入。
        folderDropLine(
            insertPos: thisFolderTopIdx == null ? null : thisFolderTopIdx + 1,
            isBelow: true),
      ],
    );
  }

  /// 確認ダイアログを出してフォルダを削除する (中のメモは未分類に戻す)。
  /// フォルダの右クリックメニュー (= ユーザー要望: 削除・名前変更)。
  Future<void> _showPdfFolderCtxMenu(BuildContext ctx, MindMapProvider provider,
      String folder, Offset pos) async {
    final displayName = folder.contains('/') ? folder.split('/').last : folder;
    final sel = await showMenu<String>(
      context: ctx,
      color: const Color(0xFF2A2A3E),
      position: RelativeRect.fromLTRB(pos.dx, pos.dy, pos.dx, pos.dy),
      items: [
        PopupMenuItem<String>(
          value: 'rename',
          child: Row(children: [
            const Icon(Icons.drive_file_rename_outline_rounded,
                color: Color(0xFF4FC3F7), size: 18),
            const SizedBox(width: 8),
            Text(provider.t('pmemo.rename'),
                style: const TextStyle(color: Colors.white)),
          ]),
        ),
        PopupMenuItem<String>(
          value: 'delete',
          child: Row(children: [
            const Icon(Icons.delete_outline_rounded,
                color: Color(0xFFFF6B6B), size: 18),
            const SizedBox(width: 8),
            Text(provider.t('btn.delete'),
                style: const TextStyle(color: Colors.white)),
          ]),
        ),
      ],
    );
    if (!mounted) return;
    if (sel == 'rename') {
      final newName = await _promptRenameDialog(ctx, 'フォルダー名を変更', displayName);
      if (newName != null && newName.trim().isNotEmpty) {
        provider.renamePdfMemoFolder(widget.nodeId, folder, newName.trim());
      }
    } else if (sel == 'delete') {
      _confirmDeleteFolder(ctx, provider, folder);
    }
  }

  /// メモの右クリックメニュー (= ユーザー要望: 削除・編集)。
  Future<void> _showPdfMemoCtxMenu(
      BuildContext ctx, MindMapProvider provider, PdfMemo m, Offset pos) async {
    final sel = await showMenu<String>(
      context: ctx,
      color: const Color(0xFF2A2A3E),
      position: RelativeRect.fromLTRB(pos.dx, pos.dy, pos.dx, pos.dy),
      items: [
        PopupMenuItem<String>(
          value: 'edit',
          child: Row(children: [
            const Icon(Icons.edit_outlined, color: Color(0xFF4FC3F7), size: 18),
            const SizedBox(width: 8),
            Text(provider.t('btn.edit'),
                style: const TextStyle(color: Colors.white)),
          ]),
        ),
        PopupMenuItem<String>(
          value: 'delete',
          child: Row(children: [
            const Icon(Icons.delete_outline_rounded,
                color: Color(0xFFFF6B6B), size: 18),
            const SizedBox(width: 8),
            Text(provider.t('btn.delete'),
                style: const TextStyle(color: Colors.white)),
          ]),
        ),
      ],
    );
    if (!mounted) return;
    if (sel == 'edit') {
      _beginInlineEdit(m);
    } else if (sel == 'delete') {
      provider.removePdfMemo(widget.nodeId, m.id);
      _showInlineBanner(
          _isDesktop
              ? '🗑️ メモを削除しました（Ctrl+Z で元に戻せます）'
              : provider.t('pdfMemo.deletedHintMobile'),
          color: const Color(0xFF4FC3F7));
    }
  }

  /// 名前変更用の小さな入力ダイアログ。
  Future<String?> _promptRenameDialog(
      BuildContext ctx, String title, String initial) {
    final c = TextEditingController(text: initial);
    return showDialog<String>(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(title,
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: TextField(
          controller: c,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          decoration: InputDecoration(
            hintText: context.read<MindMapProvider>().t('folder.newNameHint'),
            hintStyle: const TextStyle(color: Colors.white38),
          ),
          onSubmitted: (v) => Navigator.pop(dctx, v),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dctx, c.text),
            child: Text(context.read<MindMapProvider>().t('btn.change')),
          ),
        ],
      ),
    );
  }

  void _confirmDeleteFolder(
      BuildContext ctx, MindMapProvider provider, String folder) {
    void doDelete(BuildContext dctx) {
      provider.deletePdfMemoFolder(widget.nodeId, folder);
      Navigator.pop(dctx);
      setState(() {
        _focusedFolder = null;
        _expandedFolders.remove(folder);
      });
      _showInlineBanner(
          provider.t('pmemo.folderDeleted').replaceFirst('{folder}', folder),
          color: const Color(0xFF6C63FF));
    }

    showDialog<void>(
      context: ctx,
      builder: (dctx) {
        // ── ダイアログに Focus を被せて Enter/Esc で確定/キャンセル
        //    (= ユーザー要望: フォルダー削除もそのまま Enter で削除される
        //    ように) ──
        // autofocus でフォーカスを Focus 自身に取り、 Enter キーを横取り
        //   して deleteを呼ぶ。 Esc はキャンセル相当 (Navigator.pop)。
        final node = FocusNode(debugLabel: 'ConfirmDeleteFolder.key');
        WidgetsBinding.instance.addPostFrameCallback((_) {
          node.requestFocus();
        });
        return Focus(
          focusNode: node,
          onKeyEvent: (_, event) {
            if (event is! KeyDownEvent) return KeyEventResult.ignored;
            if (event.logicalKey == LogicalKeyboardKey.enter ||
                event.logicalKey == LogicalKeyboardKey.numpadEnter) {
              doDelete(dctx);
              return KeyEventResult.handled;
            }
            if (event.logicalKey == LogicalKeyboardKey.escape) {
              Navigator.pop(dctx);
              return KeyEventResult.handled;
            }
            return KeyEventResult.ignored;
          },
          child: AlertDialog(
            backgroundColor: const Color(0xFF1E1E32),
            title: Text(
                provider
                    .t('pmemo.deleteFolderConfirm')
                    .replaceFirst('{folder}', folder),
                style: const TextStyle(color: Colors.white)),
            content: Text(provider.t('pmemo.deleteFolderBody'),
                style: const TextStyle(color: Colors.white70)),
            actions: [
              TextButton(
                  onPressed: () => Navigator.pop(dctx),
                  child: Text(provider.t('btn.cancel'),
                      style: const TextStyle(color: Colors.white70))),
              ElevatedButton(
                style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFFE57373),
                    foregroundColor: Colors.white,),
                onPressed: () => doDelete(dctx),
                child: Text(provider.t('btn.delete'),
                    style: const TextStyle(color: Colors.white)),
              ),
            ],
          ),
        );
      },
    );
  }

  /// 通常モードのヘッダ: タイトル + 配置メモ追加 + フリーメモ追加 + 選択モード切替。
  Widget _buildNormalHeader(
      BuildContext ctx, MindMapProvider provider, List<PdfMemo> memos) {
    return Row(
      children: [
        // 「Memo」 の文字は出さない (= ユーザー報告: 幅が足りず 2 行に
        //   折り返して見苦しい)。 アイコンだけにして横のボタンに場所を譲る。
        Icon(Icons.sticky_note_2, color: const Color(0xFFFFC107), size: 18,
            semanticLabel: context.read<MindMapProvider>().t('common.memoLabel')),
        const Spacer(),
        // 選択モード突入ボタン (メモが 1 つもない時は非表示)
        if (memos.isNotEmpty)
          IconButton(
            tooltip: provider.t('pdfMemo.tooltipSelectMode'),
            icon: const Icon(Icons.checklist_rounded,
                color: Color(0xFFFFC107), size: 20),
            onPressed: () {
              setState(() => _selectionMode = true);
              WidgetsBinding.instance.addPostFrameCallback((_) {
                if (mounted) _kbdFocusNode.requestFocus();
              });
            },
          ),
        // ── フォルダ作成ボタン (= 新しいフォルダを作って、 そのフォルダに
        //    既存メモを移動するためのダイアログを開く) ──
        IconButton(
          tooltip:
              context.read<MindMapProvider>().t('pmemo.createFolderOrMove'),
          icon: const Icon(Icons.create_new_folder_rounded,
              color: Color(0xFF6C63FF), size: 20),
          onPressed: () => _showFolderManageDialog(ctx, provider, memos),
        ),
        if (widget.onAddHere != null)
          IconButton(
            tooltip: context.read<MindMapProvider>().t('pmemo.placeHere'),
            icon: const Icon(Icons.add_location_alt,
                color: Color(0xFFFFC107), size: 20),
            onPressed: widget.onAddHere,
          ),
        IconButton(
          tooltip: provider.t('pdfMemo.tooltipFreeAdd'),
          icon: const Icon(Icons.note_add, color: Color(0xFFFFC107), size: 20),
          onPressed: () async {
            final created = await showDialog<PdfMemo?>(
              context: ctx,
              builder: (_) => const _PdfMemoEditDialog(freeMode: true),
            );
            if (created != null) {
              provider.addPdfMemo(
                widget.nodeId,
                text: created.text,
                pageNumber: created.pageNumber,
                colorValue: created.colorValue,
              );
            }
          },
        ),
        // ── クリップボード貼り付け (画像 / テキスト) (= ユーザー要望:
        //    メモ欄に画像等を貼り付けられるように。 Ctrl+V と同じ処理を
        //    ボタンでも押せるようにする) ──
        IconButton(
          tooltip: provider.t('pmemo.paste'),
          icon: const Icon(Icons.content_paste_rounded,
              color: Color(0xFFFFC107), size: 19),
          onPressed: () => _pasteImageIntoMemo(provider),
        ),
        // ── 画像ファイルを選んでメモに添付 (= ユーザー要望) ──
        IconButton(
          tooltip: provider.t('pmemo.attachImage'),
          icon: const Icon(Icons.add_photo_alternate_outlined,
              color: Color(0xFFFFC107), size: 20),
          onPressed: () => _attachImageFileAsMemo(provider),
        ),
        // ── メモをまとめて AI に送る (= ユーザー要望: メモ毎に改行を
        //    入れて一括でブラウザ AI へ渡す) ──
        if (widget.onSendAllToAi != null && memos.isNotEmpty)
          IconButton(
            tooltip: context.read<MindMapProvider>().t('memo.sendAllToAi'),
            icon: const Icon(Icons.smart_toy_rounded,
                color: Colors.white70, size: 20),
            onPressed: () {
              final parts = <String>[];
              for (final m in memos) {
                final body = m.text
                    .split('\n')
                    .where((l) => !l.startsWith(_kMemoImgPrefix))
                    .join('\n')
                    .trim();
                if (body.isNotEmpty) parts.add(body);
              }
              if (parts.isEmpty) return;
              // メモ毎に改行を入れて 1 つのテキストにまとめる。
              widget.onSendAllToAi!(parts.join('\n'));
            },
          ),
        // ── 左右入れ替えボタン (= AI 欄とメモ欄の位置を入れ替え) ──
        // ユーザー要望: 入れ替えボタンをメモ欄にも搭載。
        if (widget.onSwapSides != null)
          IconButton(
            tooltip: context.read<MindMapProvider>().t('pmemo.swapAi'),
            icon: const Icon(Icons.swap_horiz_rounded,
                color: Colors.white70, size: 20),
            onPressed: widget.onSwapSides,
          ),
        // ── メモパネルを閉じる ボタン (ユーザー要望) ──
        // ON 押下でパネル自体を非表示にし、 PDF ビューを横幅いっぱい広げる。
        if (widget.onClosePanel != null)
          IconButton(
            tooltip: provider.t('pdfMemo.tooltipClosePanel'),
            icon: const Icon(Icons.chevron_right_rounded,
                color: Colors.white70, size: 22),
            onPressed: widget.onClosePanel,
          ),
      ],
    );
  }

  /// メモ欄の空白部分を右クリックした時のコンテキストメニュー
  /// (= ユーザー要望「メモ欄の何もないところで右クリックすると新規メモや
  ///   フォルダーを作成する項目が出てくるように」)。
  /// 「新規メモを作成」 と「フォルダーを作成」 を表示する。
  Future<void> _showMemoPanelContextMenu(BuildContext ctx,
      MindMapProvider provider, List<PdfMemo> memos, Offset globalPos) async {
    final overlay = Overlay.of(ctx).context.findRenderObject() as RenderBox?;
    if (overlay == null) return;
    final selected = await showMenu<String>(
      context: ctx,
      color: const Color(0xFF2A2A3E),
      position: RelativeRect.fromRect(
        Rect.fromLTWH(globalPos.dx, globalPos.dy, 0, 0),
        Offset.zero & overlay.size,
      ),
      items: [
        PopupMenuItem<String>(
          value: 'newMemo',
          child: Row(children: [
            const Icon(Icons.note_add, color: Color(0xFFFFC107), size: 18),
            const SizedBox(width: 10),
            Text(provider.t('pmemo.newMemo'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
        PopupMenuItem<String>(
          value: 'newFolder',
          child: Row(children: [
            const Icon(Icons.create_new_folder_rounded,
                color: Color(0xFF6C63FF), size: 18),
            const SizedBox(width: 10),
            Text(provider.t('pmemo.createFolder'),
                style: const TextStyle(color: Colors.white, fontSize: 13)),
          ]),
        ),
      ],
    );
    if (selected == null || !mounted) return;
    if (selected == 'newMemo') {
      // フリーメモ追加ダイアログ → 作成内容を addPdfMemo。
      final created = await showDialog<PdfMemo?>(
        context: ctx,
        builder: (_) => const _PdfMemoEditDialog(freeMode: true),
      );
      if (created != null) {
        provider.addPdfMemo(
          widget.nodeId,
          text: created.text,
          pageNumber: created.pageNumber,
          colorValue: created.colorValue,
        );
      }
    } else if (selected == 'newFolder') {
      // 新規フォルダ作成専用の軽量ダイアログ (名前だけ入力)。
      await _showQuickCreateFolderDialog(ctx, provider);
    }
  }

  /// 新規フォルダ名だけを入力して作るシンプルなダイアログ。
  /// (右クリックメニューの「フォルダーを作成」 から呼ばれる)
  /// [parent] が指定されればその直下に作るサブフォルダ扱い (= ユーザー要望:
  /// フォルダーの中にもフォルダーを作成できるように)。 内部的にはフォルダ名を
  /// `親フォルダ名/子フォルダ名` の slash 区切りで表現する。
  Future<void> _showQuickCreateFolderDialog(
      BuildContext ctx, MindMapProvider provider,
      {String? parent}) async {
    final ctrl = TextEditingController();
    final name = await showDialog<String?>(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Row(children: [
          const Icon(Icons.create_new_folder_rounded,
              color: Color(0xFF6C63FF), size: 20),
          const SizedBox(width: 10),
          Text(
              parent == null
                  ? provider.t('pmemo.newFolderTitle')
                  : provider
                      .t('pmemo.subfolderTitle')
                      .replaceFirst('{parent}', parent),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
        ]),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          decoration: InputDecoration(
            hintText: provider.t('folder.nameLabel'),
            hintStyle: const TextStyle(color: Colors.white38),
            filled: true,
            fillColor: Colors.white.withValues(alpha: 0.07),
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: BorderSide.none,
            ),
          ),
          onSubmitted: (v) => Navigator.pop(dctx, v.trim()),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, null),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF6C63FF),
                foregroundColor: Colors.white,),
            onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
            child: Text(provider.t('btn.create')),
          ),
        ],
      ),
    );
    if (name == null || name.isEmpty || !mounted) return;
    // slash を含むのは階層区切りなので、 ユーザーが手入力するのを防ぐため
    //   フォルダ名内の / は - に置換しておく。
    final safeName = name.replaceAll('/', '-');
    final fullName = parent == null ? safeName : '$parent/$safeName';
    provider.createPdfMemoFolder(widget.nodeId, fullName);
    // 親フォルダも自分も展開状態にして見やすくする。
    setState(() {
      if (parent != null) _expandedFolders.add(parent);
      _expandedFolders.add(fullName);
    });
  }

  /// フォルダ管理ダイアログ。
  /// - 新規フォルダの作成 (TextField で名前入力)
  /// - 既存フォルダの一覧表示 + そのフォルダ内のメモ数
  /// - 各メモを別フォルダに移動 (= フォルダ内メモタップ → 移動先選択)
  ///
  /// シンプルな MVP として実装: 新規作成 + 全メモを別フォルダに移動の
  /// 切り替え UI。 メモごとの細かい移動はメモ一覧の長押しコンテキスト
  /// メニュー側でも対応する想定 (= 別途実装可能)。
  Future<void> _showFolderManageDialog(
      BuildContext ctx, MindMapProvider provider, List<PdfMemo> memos) async {
    final newFolderCtrl = TextEditingController();
    await showDialog<void>(
      context: ctx,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setSt) {
        final folders = provider.getPdfMemoFolders(widget.nodeId);
        final noFolderCount =
            memos.where((m) => (m.folder ?? '').isEmpty).length;
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(18),
              side: const BorderSide(color: Color(0xFF6C63FF), width: 1)),
          title: Row(children: [
            const Icon(Icons.folder_rounded,
                color: Color(0xFF6C63FF), size: 20),
            const SizedBox(width: 8),
            Expanded(
              child: Text(provider.t('pmemo.manageFolders'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 15,
                      fontWeight: FontWeight.bold)),
            ),
          ]),
          content: SizedBox(
            width: 460,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  // ── 新規フォルダ作成 ──
                  Text(provider.t('pmemo.createNewFolder'),
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 13,
                          fontWeight: FontWeight.w600)),
                  const SizedBox(height: 8),
                  Builder(builder: (bctx) {
                    // ── フォルダ作成処理をクロージャ化して、 Enter キー
                    //    (onSubmitted) と「作成」 ボタンの両方から呼べるよう
                    //    にする (= ユーザー要望: Enter でそのまま作成して
                    //    格納できるように) ──
                    void createFolder() {
                      final name = newFolderCtrl.text.trim();
                      if (name.isEmpty) return;
                      // 空のフォルダとして永続作成 (= ユーザー要望)。
                      //   メモを 1 件も入れなくてもフォルダは残る。
                      provider.createPdfMemoFolder(widget.nodeId, name);
                      newFolderCtrl.clear();
                      Navigator.pop(dctx);
                      // ルート ScaffoldMessenger の SnackBar は PDF ビューワー越し
                      //   だと見えない (= ユーザー要望: パネルの上に出す)。 同じ
                      //   クラスが持つパネル内バナーで通知する。
                      _showInlineBanner(
                          provider
                              .t('pmemo.folderCreated')
                              .replaceFirst('{name}', name),
                          color: const Color(0xFF6C63FF));
                      // 続けてメモを追加したい場合のために選択ダイアログを
                      //   開く。キャンセルすれば空フォルダのまま残る。
                      _showMemoMoveToFolderDialog(ctx, provider, memos, name);
                    }

                    return Row(children: [
                      Expanded(
                        child: TextField(
                          controller: newFolderCtrl,
                          autofocus: true,
                          textInputAction: TextInputAction.done,
                          // Enter で確定 → そのまま作成して格納フローへ。
                          onSubmitted: (_) => createFolder(),
                          style: const TextStyle(
                              color: Colors.white, fontSize: 13),
                          decoration: InputDecoration(
                            isDense: true,
                            hintText: provider.t('pmemo.folderExampleHint'),
                            hintStyle: const TextStyle(
                                color: Colors.white38, fontSize: 12),
                            filled: true,
                            fillColor: const Color(0xFF2A2A3E),
                            contentPadding: const EdgeInsets.symmetric(
                                horizontal: 10, vertical: 8),
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(8),
                              borderSide:
                                  const BorderSide(color: Colors.white24),
                            ),
                            enabledBorder: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(8),
                              borderSide:
                                  const BorderSide(color: Colors.white24),
                            ),
                            focusedBorder: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(8),
                              borderSide:
                                  const BorderSide(color: Color(0xFF6C63FF)),
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      ElevatedButton(
                        style: ElevatedButton.styleFrom(
                            backgroundColor: const Color(0xFF6C63FF),
                            foregroundColor: Colors.white,),
                        onPressed: createFolder,
                        child: Text(provider.t('btn.create'),
                            style: const TextStyle(color: Colors.white)),
                      ),
                    ]);
                  }),
                  const SizedBox(height: 16),
                  const Divider(color: Colors.white12, height: 1),
                  const SizedBox(height: 12),
                  // ── 既存フォルダ一覧 ──
                  Text(
                      provider
                          .t('pmemo.existingFolders')
                          .replaceFirst('{n}', '${folders.length}')
                          .replaceFirst('{m}', '$noFolderCount'),
                      style: const TextStyle(
                          color: Colors.white70,
                          fontSize: 12,
                          fontWeight: FontWeight.w600)),
                  const SizedBox(height: 6),
                  if (folders.isEmpty)
                    Padding(
                      padding: const EdgeInsets.all(8),
                      child: Text(provider.t('pmemo.noFolders'),
                          style: const TextStyle(
                              color: Colors.white38, fontSize: 11)),
                    ),
                  ...folders.map((f) {
                    final count = memos.where((m) => m.folder == f).length;
                    return ListTile(
                      dense: true,
                      contentPadding: EdgeInsets.zero,
                      leading: const Icon(Icons.folder_rounded,
                          color: Color(0xFF6C63FF), size: 18),
                      title: Text(f,
                          style: const TextStyle(
                              color: Colors.white, fontSize: 13)),
                      subtitle: Text(
                          provider
                              .t('common.itemsN')
                              .replaceFirst('{n}', '$count'),
                          style: const TextStyle(
                              color: Colors.white54, fontSize: 11)),
                      trailing: Row(mainAxisSize: MainAxisSize.min, children: [
                        IconButton(
                          tooltip: context
                              .read<MindMapProvider>()
                              .t('pmemo.addMemoHere'),
                          icon: const Icon(Icons.drive_file_move_rounded,
                              size: 16, color: Color(0xFF4FC3F7)),
                          onPressed: () {
                            Navigator.pop(dctx);
                            _showMemoMoveToFolderDialog(
                                ctx, provider, memos, f);
                          },
                        ),
                        IconButton(
                          tooltip: context
                              .read<MindMapProvider>()
                              .t('pmemo.dissolveFolder'),
                          icon: const Icon(Icons.delete_outline,
                              size: 16, color: Color(0xFFE57373)),
                          onPressed: () {
                            final ids = memos
                                .where((m) => m.folder == f)
                                .map((m) => m.id)
                                .toSet();
                            provider.setPdfMemosFolder(
                                widget.nodeId, ids, null);
                            setSt(() {});
                          },
                        ),
                      ]),
                    );
                  }),
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(context.read<MindMapProvider>().t('btn.close'),
                  style: const TextStyle(color: Colors.white54)),
            ),
          ],
        );
      }),
    ).whenComplete(() => newFolderCtrl.dispose());
  }

  /// 指定フォルダに「どのメモを入れるか」 を選ぶダイアログ。
  /// チェックボックス付きの一覧で、 ユーザーが入れたいメモを選んで保存。
  Future<void> _showMemoMoveToFolderDialog(BuildContext ctx,
      MindMapProvider provider, List<PdfMemo> memos, String folderName) async {
    // ユーザー要望: フォルダ作成時に問われるメモ候補から、他フォルダに
    //   既に含まれているメモは除外する。未分類 + このフォルダに既に
    //   入っているメモだけを候補にする。
    final selectable = memos
        .where((m) => (m.folder ?? '').isEmpty || m.folder == folderName)
        .toList();
    final selected = <String>{
      // デフォルトでは「現在そのフォルダに入っているメモ」 を選択済み
      ...memos.where((m) => m.folder == folderName).map((m) => m.id),
    };
    // Shift+クリックの範囲選択用アンカー (= 最後に単独クリックした行の index)。
    int? anchorIndex;
    await showDialog<void>(
      context: ctx,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setSt) {
        // 「保存」 ボタンと Enter キー両方から呼ばれる確定処理。
        // 選択されたメモを folderName に、 そうでないメモのうち元々この
        // フォルダにいたものは「未分類」 (null) に戻す。
        void doSave() {
          final wasInFolder = memos
              .where((m) => m.folder == folderName)
              .map((m) => m.id)
              .toSet();
          final toMove = selected.difference(wasInFolder);
          final toRemove = wasInFolder.difference(selected);
          provider.setPdfMemosFolder(widget.nodeId, toMove, folderName);
          provider.setPdfMemosFolder(widget.nodeId, toRemove, null);
          Navigator.pop(dctx);
          // ルート SnackBar は PDF ビューワー越しだと見えないので、 同じクラスの
          //   パネル内バナーで通知する (= ユーザー要望: パネルの上に出す)。
          _showInlineBanner('「$folderName」 に ${selected.length} 件のメモを設定しました',
              color: const Color(0xFF6C63FF));
        }

        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(18),
              side: const BorderSide(color: Color(0xFF6C63FF), width: 1)),
          title: Row(children: [
            const Icon(Icons.folder_open_rounded,
                color: Color(0xFF6C63FF), size: 20),
            const SizedBox(width: 8),
            Expanded(
              child: Text(
                  provider
                      .t('pmemo.selectMemosFor')
                      .replaceFirst('{folder}', folderName),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 15,
                      fontWeight: FontWeight.bold)),
            ),
          ]),
          content: Focus(
            autofocus: true,
            // Ctrl+A / Cmd+A で全選択 (全選択済みなら全解除のトグル)。
            onKeyEvent: (fnode, event) {
              final kb = HardwareKeyboard.instance;
              final isCtrl = kb.isControlPressed || kb.isMetaPressed;
              if (event is KeyDownEvent &&
                  isCtrl &&
                  event.logicalKey == LogicalKeyboardKey.keyA) {
                setSt(() {
                  if (selected.length >= selectable.length) {
                    selected.clear();
                  } else {
                    selected.addAll(selectable.map((m) => m.id));
                  }
                });
                return KeyEventResult.handled;
              }
              // Enter / Numpad Enter でそのまま保存確定 (= ユーザー要望)。
              if (event is KeyDownEvent &&
                  (event.logicalKey == LogicalKeyboardKey.enter ||
                      event.logicalKey == LogicalKeyboardKey.numpadEnter)) {
                doSave();
                return KeyEventResult.handled;
              }
              return KeyEventResult.ignored;
            },
            child: SizedBox(
              width: 520,
              height: 500,
              child: ListView.builder(
                itemCount: selectable.length,
                itemBuilder: (_, i) {
                  final m = selectable[i];
                  final isCurrentlyInFolder = m.folder == folderName;
                  final firstLine = m.text.split('\n').first;
                  return CheckboxListTile(
                    dense: true,
                    value: selected.contains(m.id),
                    activeColor: const Color(0xFF6C63FF),
                    contentPadding: EdgeInsets.zero,
                    controlAffinity: ListTileControlAffinity.leading,
                    title: Text(
                        firstLine.length > 80
                            ? '${firstLine.substring(0, 80)}…'
                            : firstLine,
                        style:
                            const TextStyle(color: Colors.white, fontSize: 12)),
                    subtitle: Row(children: [
                      if ((m.folder ?? '').isNotEmpty)
                        Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 6, vertical: 0),
                          decoration: BoxDecoration(
                            color: isCurrentlyInFolder
                                ? const Color(0xFF6C63FF).withValues(alpha: 0.4)
                                : Colors.white.withValues(alpha: 0.1),
                            borderRadius: BorderRadius.circular(4),
                          ),
                          child: Text(m.folder!,
                              style: const TextStyle(
                                  color: Colors.white70, fontSize: 10)),
                        )
                      else
                        Text(provider.t('pmemo.uncategorized'),
                            style: const TextStyle(
                                color: Colors.white38, fontSize: 10)),
                    ]),
                    onChanged: (v) {
                      final kb = HardwareKeyboard.instance;
                      final isShift = kb.isShiftPressed;
                      setSt(() {
                        if (isShift && anchorIndex != null) {
                          // Shift+クリック: アンカー〜この行までを範囲選択 (追加)。
                          final lo = math.min(anchorIndex!, i);
                          final hi = math.max(anchorIndex!, i);
                          for (int k = lo; k <= hi; k++) {
                            selected.add(selectable[k].id);
                          }
                        } else {
                          // 通常 / Ctrl+クリック: この行をトグルしてアンカー更新。
                          if (v == true) {
                            selected.add(m.id);
                          } else {
                            selected.remove(m.id);
                          }
                          anchorIndex = i;
                        }
                      });
                    },
                  );
                },
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            ElevatedButton.icon(
              icon:
                  const Icon(Icons.save_rounded, size: 14, color: Colors.white),
              label: Text(provider.t('btn.save'),
                  style: const TextStyle(color: Colors.white)),
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF6C63FF),
                  foregroundColor: Colors.white,),
              onPressed: doSave,
            ),
          ],
        );
      }),
    );
  }

  /// 選択モード時のヘッダ: 「N 件選択中」 + 全選択 + キャンセル + 削除。
  /// PdfMemo を 1 件、 親ノードに接続されたマップノードとして出す。
  /// provider.addPdfMemoAsNode が既存実装で、 親ノードの右側に配置 + 接続まで
  /// 一括でやってくれる。 失敗は snackbar で通知。
  /// フォルダをまるごとマップに出す (= ユーザー要望)。 フォルダ名を親ノード、
  /// フォルダ内の各メモを子ノードにして、 PDF ノードの右側に展開する。
  void _exportFolderToMap(
      BuildContext ctx, MindMapProvider provider, String folder, int count) {
    // フォルダ内のメモを provider から集める。
    final node = provider.nodes[widget.nodeId];
    final memos = (node?.pdfMemos ?? const <PdfMemo>[])
        .where((m) => (m.folder ?? '') == folder)
        .toList();
    final folderNode = provider.addPdfMemoFolderAsNodes(
      parentNodeId: widget.nodeId,
      folder: folder,
      memos: memos,
    );
    if (!mounted) return;
    if (folderNode != null) {
      _showInlineBanner(
        '🌲 フォルダ「$folder」 をマップに出しました (${memos.length} 件)',
        color: const Color(0xFF43B97F),
        duration: const Duration(seconds: 3),
      );
    } else {
      _showInlineBanner(
        provider.t('pdfMemo.bannerExportFailed'),
        color: const Color(0xFFE53935),
      );
    }
  }

  void _exportMemoToMap(
      BuildContext ctx, MindMapProvider provider, PdfMemo memo) {
    final node = provider.addPdfMemoAsNode(
      parentNodeId: widget.nodeId,
      memo: memo,
    );
    if (!mounted) return;
    if (node != null) {
      // パネル内バナーで通知 (ScaffoldMessenger は viewer ダイアログ越しに
      // 親アプリ側を探すため、 SnackBar が画面に見えなかったのを回避)。
      _showInlineBanner(
        provider.t('pdfMemo.bannerExportedSingle'),
        color: const Color(0xFF43B97F),
      );
    } else {
      _showInlineBanner(
        provider.t('pdfMemo.bannerExportFailed'),
        color: const Color(0xFFE53935),
      );
    }
  }

  /// 選択中の PdfMemo を一括でマップノードとして出す。 選択モード中の
  /// header から呼び出される。 成功数をパネル内バナーで表示し、 選択は解除する。
  void _exportSelectedMemosToMap(
      BuildContext ctx, MindMapProvider provider, List<PdfMemo> memos) {
    int added = 0;
    for (final m in memos) {
      if (!_selectedIds.contains(m.id)) continue;
      final n = provider.addPdfMemoAsNode(
        parentNodeId: widget.nodeId,
        memo: m,
      );
      if (n != null) added++;
    }
    if (!mounted) return;
    _showInlineBanner(
      provider.t('pdfMemo.bannerExportedMulti').replaceAll('{n}', '$added'),
      color: const Color(0xFF43B97F),
      duration: const Duration(seconds: 3),
    );
    setState(() {
      _selectionMode = false;
      _selectedIds.clear();
      _lastSelectedIndex = null;
    });
  }

  Widget _buildSelectionHeader(
      BuildContext ctx, MindMapProvider provider, List<PdfMemo> memos) {
    final n = _selectedIds.length;
    // 全選択判定・全選択ボタンも「表示中の階層」 (= _visibleMemos) を基準に
    //   する (= Ctrl+A と挙動を揃える。折り畳みフォルダの中は対象外)。
    final allSelected =
        _visibleMemos.isNotEmpty && _selectedIds.length == _visibleMemos.length;
    return Row(
      children: [
        IconButton(
          tooltip: provider.t('pdfMemo.cancelSelection'),
          icon: const Icon(Icons.close, color: Colors.white60, size: 20),
          onPressed: _exitSelectionMode,
        ),
        Expanded(
          child: Text(
            provider.t('pdfMemo.selectedCount').replaceAll('{n}', '$n'),
            style: const TextStyle(
                color: Colors.white, fontSize: 13, fontWeight: FontWeight.w600),
          ),
        ),
        IconButton(
          tooltip: allSelected
              ? provider.t('pdfMemo.deselectAll')
              : provider.t('pdfMemo.selectAll'),
          icon: Icon(
            allSelected ? Icons.deselect_rounded : Icons.select_all_rounded,
            color: const Color(0xFF6C63FF),
            size: 20,
          ),
          onPressed: () {
            setState(() {
              if (allSelected) {
                _selectedIds.clear();
              } else {
                _selectedIds
                  ..clear()
                  ..addAll(_visibleMemos.map((m) => m.id));
              }
            });
          },
        ),
        // 🌲 一括: 選択メモをマップ上のノードとして出す。 色はトーンを揃えて
        // グレー系 (削除のような destructive ではないのでアクセント色は不要)。
        IconButton(
          tooltip: context.read<MindMapProvider>().t('pmemo.selectedToMap'),
          icon: Icon(
            Icons.account_tree_outlined,
            color: n > 0 ? Colors.white60 : Colors.white24,
            size: 20,
          ),
          onPressed: n > 0
              ? () => _exportSelectedMemosToMap(ctx, provider, memos)
              : null,
        ),
        // 📁 一括: 選択メモをフォルダにまとめて格納 (= ユーザー要望)。
        IconButton(
          tooltip: context.read<MindMapProvider>().t('pmemo.selectedToFolder'),
          icon: Icon(
            Icons.drive_file_move_rounded,
            color: n > 0 ? const Color(0xFF6C63FF) : Colors.white24,
            size: 20,
          ),
          onPressed:
              n > 0 ? () => _moveSelectedMemosToFolder(ctx, provider) : null,
        ),
        IconButton(
          tooltip: provider.t('pdfMemo.bulkDeleteTitle'),
          icon: Icon(
            Icons.delete_rounded,
            color: n > 0 ? const Color(0xFFE57373) : Colors.white24,
            size: 20,
          ),
          onPressed: n > 0 ? () => _confirmAndBulkDelete(ctx, provider) : null,
        ),
      ],
    );
  }

  /// 選択中のメモをまとめてフォルダへ格納する (= ユーザー要望)。
  /// 新規フォルダ名を入力するか、既存フォルダを選ぶ。空文字 = 未分類に戻す。
  Future<void> _moveSelectedMemosToFolder(
      BuildContext ctx, MindMapProvider provider) async {
    final ids = _selectedIds.toSet();
    if (ids.isEmpty) return;
    final existing = provider.getPdfMemoFolders(widget.nodeId);
    final newCtrl = TextEditingController();
    final chosen = await showDialog<String?>(
      context: ctx,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setSt) {
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(18),
              side: const BorderSide(color: Color(0xFF6C63FF), width: 1)),
          title: Row(children: [
            const Icon(Icons.drive_file_move_rounded,
                color: Color(0xFF6C63FF), size: 20),
            const SizedBox(width: 8),
            Expanded(
              child: Text(
                  provider
                      .t('pmemo.storeNToFolder')
                      .replaceFirst('{n}', '${ids.length}'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 15,
                      fontWeight: FontWeight.bold)),
            ),
          ]),
          content: SizedBox(
            width: 420,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  // 新規フォルダを作って格納
                  Row(children: [
                    Expanded(
                      child: TextField(
                        controller: newCtrl,
                        style:
                            const TextStyle(color: Colors.white, fontSize: 13),
                        decoration: InputDecoration(
                          isDense: true,
                          hintText: provider.t('pmemo.newFolderNameHint'),
                          hintStyle: const TextStyle(
                              color: Colors.white38, fontSize: 12),
                          filled: true,
                          fillColor: const Color(0xFF2A2A3E),
                          contentPadding: const EdgeInsets.symmetric(
                              horizontal: 10, vertical: 8),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(8),
                            borderSide: const BorderSide(color: Colors.white24),
                          ),
                          enabledBorder: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(8),
                            borderSide: const BorderSide(color: Colors.white24),
                          ),
                        ),
                      ),
                    ),
                    const SizedBox(width: 8),
                    ElevatedButton(
                      style: ElevatedButton.styleFrom(
                          backgroundColor: const Color(0xFF6C63FF),
                          foregroundColor: Colors.white,),
                      onPressed: () {
                        final name = newCtrl.text.trim();
                        if (name.isEmpty) return;
                        Navigator.pop(dctx, name);
                      },
                      child: Text(provider.t('pmemo.createAndStore'),
                          style: const TextStyle(color: Colors.white)),
                    ),
                  ]),
                  if (existing.isNotEmpty) ...[
                    const SizedBox(height: 14),
                    Text(provider.t('pmemo.storeToExisting'),
                        style: const TextStyle(
                            color: Colors.white70, fontSize: 12)),
                    const SizedBox(height: 4),
                    ...existing.map((f) => ListTile(
                          dense: true,
                          contentPadding: EdgeInsets.zero,
                          leading: const Icon(Icons.folder_rounded,
                              color: Color(0xFF6C63FF), size: 18),
                          title: Text(f,
                              style: const TextStyle(
                                  color: Colors.white, fontSize: 13)),
                          onTap: () => Navigator.pop(dctx, f),
                        )),
                  ],
                  const SizedBox(height: 6),
                  TextButton.icon(
                    onPressed: () => Navigator.pop(dctx, ''),
                    icon: const Icon(Icons.folder_off_rounded,
                        color: Colors.white54, size: 18),
                    label: Text(provider.t('pmemo.backToUncategorized'),
                        style: const TextStyle(color: Colors.white54)),
                  ),
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx, null),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
          ],
        );
      }),
    );
    if (chosen == null) return; // キャンセル
    final folder = chosen.isEmpty ? null : chosen;
    provider.setPdfMemosFolder(widget.nodeId, ids, folder);
    _exitSelectionMode();
    if (mounted) {
      _showInlineBanner(
          folder == null
              ? '${ids.length} 件を未分類に戻しました'
              : '「$folder」 に ${ids.length} 件を格納しました',
          color: const Color(0xFF6C63FF));
    }
  }
}

class _PdfMemoTile extends StatelessWidget {
  final PdfMemo memo;
  final bool highlighted;

  /// 通常モード中、 ↑/↓ キーでフォーカスされた行か。 true の時青枠で表示。
  final bool focused;
  final VoidCallback onTap;

  /// ダブルクリック (ダブルタップ) コールバック。インライン編集の開始に使う。
  final VoidCallback? onDoubleTap;

  /// メモを 1 つ上へ移動 (= 上下入れ替え)。null ならボタン非表示。
  final VoidCallback? onMoveUp;

  /// メモを 1 つ下へ移動。null ならボタン非表示。
  final VoidCallback? onMoveDown;
  final VoidCallback onEdit;
  final VoidCallback onDelete;

  /// メモ本文を Google 検索で開くコールバック (🔍 アイコン)。
  /// アプリ内のフローティング PiP オーバーレイで開く。
  /// 空文字メモではアイコン自体を出さない。
  final VoidCallback onSearchGoogle;

  /// メモ本文で YouTube 検索を開くコールバック (= ユーザー要望: PDF
  /// ビューアやテキストエディタのメモから YouTube 検索を開けるように)。
  /// null または空メモでは非表示。
  final VoidCallback? onSearchYoutube;

  /// メモをマップ上のノードとして出すコールバック (🌲 ノード化アイコン)。
  /// 親ノードに接続された子ノードとして配置される。
  final VoidCallback onSendToMap;

  /// ピン止め切替コールバック (画びょうアイコン)。
  /// ピン済みメモはメモ一覧でフォルダ内/全体の先頭にソートされる。
  final VoidCallback onTogglePinned;

  /// メモの内容を AI チャット欄に送るコールバック (= ユーザー要望)。
  /// null の場合は「AI に送る」 ボタンを表示しない。
  final VoidCallback? onSendToAi;

  /// メモをフラッシュカードに登録するコールバック (= ユーザー要望: メモ全般に
  /// フラッシュカード登録機能)。 null の場合はボタンを表示しない。
  final VoidCallback? onRegisterFlashcard;

  /// メモを上の階層 (= 親フォルダ or 未分類) に戻すコールバック (= ユーザー要望:
  /// メモを上の階層に戻したりできるように)。 メモが既に未分類なら呼び出されない。
  /// null なら「↰ 上へ」 ボタンを表示しない。
  final VoidCallback? onMoveUpHierarchy;

  /// メモがクイズ形式 (= text が "Q" で始まる) の時、 解答を開示済みか。
  /// false の間は答えと解説が隠され、 「タップで解答を見る」 ボタンが出る。
  final bool quizRevealed;

  /// 解答開示状態をトグルするコールバック (= クイズメモ専用)。
  final VoidCallback onToggleQuizReveal;

  /// 自分の解答入力用 TextEditingController (= クイズメモ専用)。
  /// 親側で memoId ごとに保持されている。
  final TextEditingController? quizAnswerCtrl;

  /// 自動答え合わせの結果。 true: 正解 / false: 不正解 / null: 未判定。
  /// 非 null の場合は ○ または ✕ と結果アイコンを表示。
  final bool? quizCheckResult;

  /// 「答え合わせ」 ボタン押下時のコールバック。
  final VoidCallback? onCheckQuizAnswer;

  /// 自動答え合わせ可能かどうか。 false の場合は「答え合わせ」 ボタン非表示。
  final bool canAutoCheckQuiz;

  /// 選択モード中かどうか。 true の時は onTap がチェック切替に変わり、
  /// 編集・削除アイコンは隠される (= 選択 UI に専念)。
  final bool selectionMode;

  /// 選択モード中、 このメモがチェック済みか。
  final bool selected;
  const _PdfMemoTile({
    required this.memo,
    required this.highlighted,
    this.focused = false,
    required this.onTap,
    this.onDoubleTap,
    this.onMoveUp,
    this.onMoveDown,
    required this.onEdit,
    required this.onDelete,
    required this.onSearchGoogle,
    this.onSearchYoutube,
    required this.onSendToMap,
    required this.onTogglePinned,
    this.onSendToAi,
    this.onRegisterFlashcard,
    this.onMoveUpHierarchy,
    this.quizRevealed = false,
    required this.onToggleQuizReveal,
    this.quizAnswerCtrl,
    this.quizCheckResult,
    this.onCheckQuizAnswer,
    this.canAutoCheckQuiz = false,
    this.selectionMode = false,
    this.selected = false,
  });

  @override
  Widget build(BuildContext context) {
    final color = Color(memo.colorValue);
    final hasPosition = memo.xRatio != null && memo.yRatio != null;
    return InkWell(
      onTap: onTap,
      onDoubleTap: onDoubleTap,
      // 長押しは親側の LongPressDraggable (ドラッグ移動) に譲るため、
      // ここでは onLongPress を設定しない。編集はダブルクリックと
      // 編集アイコンから行う (= ユーザー要望のドラッグ移動と両立させる)。
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 240),
        margin: const EdgeInsets.symmetric(horizontal: 6, vertical: 0),
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
        decoration: BoxDecoration(
          color: selectionMode && selected
              ? const Color(0xFF6C63FF).withValues(alpha: 0.20)
              : focused
                  ? const Color(0xFF4FC3F7).withValues(alpha: 0.12)
                  : highlighted
                      ? color.withValues(alpha: 0.18)
                      : Colors.white.withValues(alpha: 0.04),
          borderRadius: BorderRadius.circular(8),
          // ↑/↓ でフォーカス中の行は青枠で囲む
          border: Border.all(
            color: focused ? const Color(0xFF4FC3F7) : Colors.transparent,
            width: focused ? 2 : 0,
          ),
        ),
        // 左端の縦線は二重 Border を使う代わりに Container をオーバーレイ
        // して表現すると複雑になるので、 ここではフォーカス時のみ全周線、
        // それ以外は左縦線というシンプルな切替に。 デザイン優先度:
        //   選択 > フォーカス > ハイライト > 通常
        foregroundDecoration: focused
            ? null
            : BoxDecoration(
                borderRadius: BorderRadius.circular(8),
                border: Border(
                  left: BorderSide(
                    color: selectionMode && selected
                        ? const Color(0xFF6C63FF)
                        : color,
                    width: (highlighted || (selectionMode && selected)) ? 5 : 3,
                  ),
                ),
              ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                // 選択モード時は左端にチェックボックス
                if (selectionMode)
                  Padding(
                    padding: const EdgeInsets.only(right: 6),
                    child: Icon(
                      selected
                          ? Icons.check_circle_rounded
                          : Icons.radio_button_unchecked,
                      color:
                          selected ? const Color(0xFF6C63FF) : Colors.white38,
                      size: 18,
                    ),
                  ),
                if (memo.pageNumber != null)
                  Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                    decoration: BoxDecoration(
                      color: color.withValues(alpha: 0.22),
                      borderRadius: BorderRadius.circular(4),
                    ),
                    child: Text(
                      'p.${memo.pageNumber}',
                      style: TextStyle(
                          color: color,
                          fontSize: 11,
                          fontWeight: FontWeight.w700),
                    ),
                  )
                else if (memo.url != null)
                  Flexible(
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 6, vertical: 2),
                      decoration: BoxDecoration(
                        color: color.withValues(alpha: 0.18),
                        borderRadius: BorderRadius.circular(4),
                      ),
                      child: Text(
                        Uri.tryParse(memo.url!)?.host ?? 'web',
                        style: TextStyle(
                            color: color,
                            fontSize: 11,
                            fontWeight: FontWeight.w600),
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                  )
                else
                  Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                    decoration: BoxDecoration(
                      color: Colors.white12,
                      borderRadius: BorderRadius.circular(4),
                    ),
                    child: const Text(
                      'free',
                      style: TextStyle(color: Colors.white60, fontSize: 11),
                    ),
                  ),
                // フォルダバッジ (= 「問題」 など、 メモが属するフォルダ名)
                if ((memo.folder ?? '').isNotEmpty) ...[
                  const SizedBox(width: 4),
                  Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                    decoration: BoxDecoration(
                      color: const Color(0xFF6C63FF).withValues(alpha: 0.22),
                      borderRadius: BorderRadius.circular(4),
                    ),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      const Icon(Icons.folder_rounded,
                          size: 10, color: Color(0xFF6C63FF)),
                      const SizedBox(width: 3),
                      Text(memo.folder!,
                          style: const TextStyle(
                              color: Color(0xFF6C63FF),
                              fontSize: 10,
                              fontWeight: FontWeight.w700)),
                    ]),
                  ),
                ],
                if (hasPosition) ...[
                  const SizedBox(width: 4),
                  Icon(Icons.place, size: 12, color: color),
                ],
                const Spacer(),
              ],
            ),
            const SizedBox(height: 4),
            // ── 添付画像 (= ユーザー要望: メモに Ctrl+V で画像貼り付け) ──
            // 画像パスは本文先頭の `__MMIMG__::<path>` マーカーから取得
            //   (PdfMemo モデル非依存)。
            Builder(builder: (_) {
              final (imgPath, _) = _parseMemoImage(memo.text);
              if (imgPath == null ||
                  imgPath.isEmpty ||
                  !File(imgPath).existsSync()) {
                return const SizedBox.shrink();
              }
              return Padding(
                padding: const EdgeInsets.only(bottom: 6),
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(6),
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(maxHeight: 220),
                    // cacheWidth で表示サイズに縮小して復号しメモリを節約
                    //   (= ユーザー要望: メモのメモリ使用量を極限まで抑える)。
                    child: Image.file(
                      File(imgPath),
                      fit: BoxFit.contain,
                      gaplessPlayback: true,
                      cacheWidth: 600,
                      filterQuality: FilterQuality.low,
                      errorBuilder: (_, __, ___) => const SizedBox.shrink(),
                    ),
                  ),
                ),
              );
            }),
            // ── 本文表示 ──
            // クイズメモ (= text が "Q" で始まり、 "\nA" を含む) は、
            // 解答 & 解説部分を `quizRevealed` で表示制御する。 デフォルト
            // 非表示で、 ユーザーが「タップして解答を見る」 を押すと開く。
            // 通常メモはそのまま全文表示。
            Builder(builder: (_) {
              // 画像マーカーを取り除いた表示用テキスト。
              final (imgPath, t) = _parseMemoImage(memo.text);
              final hasImage = imgPath != null && imgPath.isNotEmpty;
              final isQuizMemo =
                  t.startsWith('Q') && RegExp(r'\nA\s*[::]').hasMatch(t);
              if (!isQuizMemo) {
                // 通常メモ。画像付きで本文が空ならテキスト行は出さない。
                if (t.isEmpty && hasImage) {
                  return const SizedBox.shrink();
                }
                return Text(
                  t.isEmpty
                      ? context.read<MindMapProvider>().t('memoList.emptyMemo')
                      : t,
                  style: TextStyle(
                    color: t.isEmpty ? Colors.white38 : Colors.white,
                    fontSize: 12.5,
                    height: 1.35,
                  ),
                );
              }
              // クイズメモを Q と A 以降に分割
              final aPos = RegExp(r'\nA\s*[::]').firstMatch(t);
              final questionPart =
                  aPos == null ? t : t.substring(0, aPos.start).trimRight();
              final answerAndAfter =
                  aPos == null ? '' : t.substring(aPos.start).trimLeft();
              // searchKey 行は答え合わせの邪魔なので隠し表示からも除外
              String hiddenContent = answerAndAfter
                  .replaceAll(RegExp(r'\n\[searchKey:[^\]]*\]'), '')
                  .trim();
              return Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  // Q 部分は常に表示
                  Text(
                    questionPart,
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 12.5,
                      height: 1.35,
                    ),
                  ),
                  const SizedBox(height: 8),
                  // ── 自分の解答入力欄 (= 解答開示前に書いておく) ──
                  // 解答表示後も残しておくので、 答え合わせ後に見比べ可能。
                  if (quizAnswerCtrl != null) ...[
                    Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Expanded(
                          child: TextField(
                            controller: quizAnswerCtrl,
                            maxLines: 2,
                            minLines: 1,
                            enabled: quizCheckResult == null,
                            style: TextStyle(
                              color: quizCheckResult == true
                                  ? const Color(0xFF43B97F)
                                  : quizCheckResult == false
                                      ? const Color(0xFFE57373)
                                      : Colors.white,
                              fontSize: 12,
                            ),
                            decoration: InputDecoration(
                              isDense: true,
                              contentPadding: const EdgeInsets.symmetric(
                                  horizontal: 8, vertical: 6),
                              hintText: context
                                  .read<MindMapProvider>()
                                  .t('quiz.yourAnswer'),
                              hintStyle: const TextStyle(
                                  color: Colors.white38, fontSize: 12),
                              filled: true,
                              fillColor: Colors.white.withValues(alpha: 0.06),
                              border: OutlineInputBorder(
                                borderRadius: BorderRadius.circular(6),
                                borderSide: BorderSide(
                                  color: quizCheckResult == true
                                      ? const Color(0xFF43B97F)
                                      : quizCheckResult == false
                                          ? const Color(0xFFE57373)
                                          : Colors.white24,
                                  width: quizCheckResult != null ? 1.5 : 1,
                                ),
                              ),
                              enabledBorder: OutlineInputBorder(
                                borderRadius: BorderRadius.circular(6),
                                borderSide: BorderSide(
                                  color: quizCheckResult == true
                                      ? const Color(0xFF43B97F)
                                      : quizCheckResult == false
                                          ? const Color(0xFFE57373)
                                          : Colors.white24,
                                  width: quizCheckResult != null ? 1.5 : 1,
                                ),
                              ),
                              suffixIcon: quizCheckResult == null
                                  ? null
                                  : Icon(
                                      quizCheckResult == true
                                          ? Icons.check_circle_rounded
                                          : Icons.cancel_rounded,
                                      color: quizCheckResult == true
                                          ? const Color(0xFF43B97F)
                                          : const Color(0xFFE57373),
                                      size: 18,
                                    ),
                            ),
                          ),
                        ),
                        if (canAutoCheckQuiz && quizCheckResult == null) ...[
                          const SizedBox(width: 6),
                          OutlinedButton(
                            onPressed: onCheckQuizAnswer,
                            style: OutlinedButton.styleFrom(
                              foregroundColor: const Color(0xFF43B97F),
                              side: const BorderSide(color: Color(0xFF43B97F)),
                              padding: const EdgeInsets.symmetric(
                                  horizontal: 10, vertical: 8),
                              textStyle: const TextStyle(fontSize: 11),
                              minimumSize: const Size(0, 36),
                            ),
                            child: Text(context
                                .read<MindMapProvider>()
                                .t('quiz.checkAnswer')),
                          ),
                        ],
                      ],
                    ),
                    if (quizCheckResult != null) ...[
                      const SizedBox(height: 4),
                      Row(
                        children: [
                          Icon(
                            quizCheckResult == true
                                ? Icons.celebration_rounded
                                : Icons.replay_rounded,
                            size: 13,
                            color: quizCheckResult == true
                                ? const Color(0xFF43B97F)
                                : const Color(0xFFE57373),
                          ),
                          const SizedBox(width: 4),
                          Text(
                            quizCheckResult == true
                                ? '正解！'
                                : '不正解 (もう一度確認してみよう)',
                            style: TextStyle(
                              color: quizCheckResult == true
                                  ? const Color(0xFF43B97F)
                                  : const Color(0xFFE57373),
                              fontSize: 11,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ],
                      ),
                    ],
                    const SizedBox(height: 8),
                  ] else
                    const SizedBox(height: 6),
                  // 解答ボタン / 解答表示
                  if (quizRevealed) ...[
                    Container(
                      padding: const EdgeInsets.all(8),
                      decoration: BoxDecoration(
                        color: const Color(0xFFFFC107).withValues(alpha: 0.10),
                        borderRadius: BorderRadius.circular(6),
                        border: Border.all(
                            color:
                                const Color(0xFFFFC107).withValues(alpha: 0.4),
                            width: 1),
                      ),
                      child: Text(
                        hiddenContent,
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 12,
                          height: 1.4,
                        ),
                      ),
                    ),
                    const SizedBox(height: 4),
                    InkWell(
                      onTap: onToggleQuizReveal,
                      borderRadius: BorderRadius.circular(6),
                      child: Padding(
                        padding:
                            EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                        child: Row(mainAxisSize: MainAxisSize.min, children: [
                          Icon(Icons.visibility_off_outlined,
                              size: 13, color: Colors.white54),
                          SizedBox(width: 4),
                          Text(
                              context
                                  .read<MindMapProvider>()
                                  .t('quiz.hideAnswer'),
                              style: TextStyle(
                                  color: Colors.white54, fontSize: 11)),
                        ]),
                      ),
                    ),
                  ] else
                    InkWell(
                      onTap: onToggleQuizReveal,
                      borderRadius: BorderRadius.circular(6),
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 10, vertical: 8),
                        decoration: BoxDecoration(
                          color:
                              const Color(0xFF4FC3F7).withValues(alpha: 0.12),
                          borderRadius: BorderRadius.circular(6),
                          border: Border.all(
                              color: const Color(0xFF4FC3F7)
                                  .withValues(alpha: 0.4),
                              width: 1),
                        ),
                        child: Row(children: const [
                          Icon(Icons.lightbulb_outline,
                              size: 14, color: Color(0xFF4FC3F7)),
                          SizedBox(width: 6),
                          Expanded(
                            child: Text(
                              'タップして解答を見る',
                              style: TextStyle(
                                  color: Color(0xFF4FC3F7),
                                  fontSize: 11,
                                  fontWeight: FontWeight.w600),
                            ),
                          ),
                        ]),
                      ),
                    ),
                ],
              );
            }),
            // ── ボタン行 (= ユーザー要望: メモとフォルダーを同じ感じの UI に。
            //    上段=本文、 下段=ボタンの構成にする) ──
            if (!selectionMode)
              Padding(
                padding: const EdgeInsets.only(top: 6),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.end,
                  children: [
                    InkWell(
                      onTap: onTogglePinned,
                      child: Padding(
                        padding: const EdgeInsets.all(4),
                        child: Icon(
                            memo.pinned
                                ? Icons.push_pin
                                : Icons.push_pin_outlined,
                            color: memo.pinned
                                ? const Color(0xFFFFC107)
                                : Colors.white54,
                            size: 16),
                      ),
                    ),
                    // 🔍 Google 検索ボタン (空メモは非表示)。色は中立な白系で、
                    // 編集アイコンと並んだときに目立たないようにしている。
                    if (memo.text.trim().isNotEmpty)
                      InkWell(
                        onTap: onSearchGoogle,
                        child: const Padding(
                          padding: EdgeInsets.all(4),
                          child: Icon(Icons.travel_explore_rounded,
                              color: Colors.white54, size: 16),
                        ),
                      ),
                    // ▶ YouTube 検索ボタン (= ユーザー要望: メモから YouTube
                    //    検索を開けるように)。 空メモは非表示。
                    if (onSearchYoutube != null && memo.text.trim().isNotEmpty)
                      InkWell(
                        onTap: onSearchYoutube,
                        child: Padding(
                          padding: const EdgeInsets.all(4),
                          child: Tooltip(
                            message: context
                                .read<MindMapProvider>()
                                .t('memo.searchYoutube'),
                            child: const Icon(Icons.smart_display_outlined,
                                color: Colors.white54, size: 16),
                          ),
                        ),
                      ),
                    // 🌲 マップにノードとして出す。 空メモも対象 (ページ番号付きで
                    // ノード化したいケースがあるため非表示にしない)。 色は中立。
                    InkWell(
                      onTap: onSendToMap,
                      child: const Padding(
                        padding: EdgeInsets.all(4),
                        child: Icon(Icons.account_tree_outlined,
                            color: Colors.white54, size: 16),
                      ),
                    ),
                    // ── 上下移動ボタン (= メモの上下を入れ替え) ──
                    // フォーカス中のタイルだけに表示し、アイコン過密と
                    // 横幅オーバーフローを防ぐ。コンパクトサイズ。
                    if (focused && onMoveUp != null)
                      InkWell(
                        onTap: onMoveUp,
                        child: const Padding(
                          padding:
                              EdgeInsets.symmetric(horizontal: 1, vertical: 4),
                          child: Icon(Icons.keyboard_arrow_up_rounded,
                              color: Colors.white70, size: 16),
                        ),
                      ),
                    if (focused && onMoveDown != null)
                      InkWell(
                        onTap: onMoveDown,
                        child: const Padding(
                          padding:
                              EdgeInsets.symmetric(horizontal: 1, vertical: 4),
                          child: Icon(Icons.keyboard_arrow_down_rounded,
                              color: Colors.white70, size: 16),
                        ),
                      ),
                    InkWell(
                      onTap: onEdit,
                      child: const Padding(
                        padding: EdgeInsets.all(4),
                        child: Icon(Icons.edit_note,
                            color: Colors.white54, size: 16),
                      ),
                    ),
                    // ── 「AI に送る」 ボタン (= ユーザー要望: メモの内容を
                    //    AI のチャット欄に与えるボタン) ──
                    // タップで親 (ビューワー state) のコールバックを呼び、
                    //   AI パネル開閉 + クリップボードコピー + 案内 を実施。
                    if (onSendToAi != null)
                      InkWell(
                        onTap: onSendToAi,
                        child: Padding(
                          padding: EdgeInsets.all(4),
                          child: Tooltip(
                            message: context
                                .read<MindMapProvider>()
                                .t('memo.sendToAiChat'),
                            child: Icon(Icons.smart_toy_rounded,
                                color: Colors.white54, size: 16),
                          ),
                        ),
                      ),
                    // ── フラッシュカードに登録 (= ユーザー要望: メモ全般に) ──
                    // 色は他のボタンと同じ中立な白系に統一 (= ユーザー要望:
                    // 一部のボタンだけ色が付いているのはおかしい)。
                    if (onRegisterFlashcard != null)
                      InkWell(
                        onTap: onRegisterFlashcard,
                        child: Padding(
                          padding: EdgeInsets.all(4),
                          child: Tooltip(
                            message: context
                                .read<MindMapProvider>()
                                .t('node.registerFlashcard'),
                            child: Icon(Icons.style_rounded,
                                color: Colors.white54, size: 16),
                          ),
                        ),
                      ),
                    // ── 上の階層に戻す (= ユーザー要望) ──
                    if (onMoveUpHierarchy != null)
                      InkWell(
                        onTap: onMoveUpHierarchy,
                        child: Padding(
                          padding: EdgeInsets.all(4),
                          child: Tooltip(
                            message:
                                context.read<MindMapProvider>().t('pmemo.goUp'),
                            child: Icon(Icons.subdirectory_arrow_left_rounded,
                                color: Colors.white54, size: 16),
                          ),
                        ),
                      ),
                    // ── 削除 (= ユーザー要望: モバイルには Backspace/Del キー
                    //    が無くメモを削除できないため、 メモ欄に削除ボタンを
                    //    再追加。 削除は undo 可能)。 ──
                    InkWell(
                      onTap: onDelete,
                      child: Padding(
                        padding: EdgeInsets.all(4),
                        child: Tooltip(
                          message:
                              context.read<MindMapProvider>().t('memo.delete'),
                          // 色は他のボタンと同じ白系に統一 (= ユーザー要望)。
                          child: Icon(Icons.delete_outline_rounded,
                              color: Colors.white54, size: 16),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
          ],
        ),
      ),
    );
  }
}

// ──────────────────────────────────────────────────────────────────────────
// PDF / URL メモ 編集ダイアログ
// ──────────────────────────────────────────────────────────────────────────
//
// 使用パターン:
//   - フリーメモ (位置・ページ・URL なし): _PdfMemoEditDialog(freeMode: true)
//     → テキストとカラーだけ。 ページや URL の入力欄は出さない。
//   - 配置モードでタップした直後: _PdfMemoEditDialog(initialPage: 5)
//                                      または _PdfMemoEditDialog(initialUrl: '...')
//     → ページ番号 / URL は確定済みなので表示専用 (編集不可) で見せる。
//        ユーザーはテキストとカラーを入れるだけで OK。
//   - 編集: _PdfMemoEditDialog(initial: existingMemo)
//     → 既存値をすべて表示し、 テキスト/カラーは編集可。 ページ・URL は
//        表示専用 (位置や紐付けを変えたい場合は削除→再追加してもらう)。
//
// 戻り値:
//   作成 / 更新内容を含む PdfMemo (id は呼び出し元で再採番されるためダミー)。
//   キャンセル時は null。
class _PdfMemoEditDialog extends StatefulWidget {
  final PdfMemo? initial;
  final int? initialPage;
  final String? initialUrl;

  /// 位置・ページ・URL すべて null のフリーメモを作るモード。
  /// (= ノードに緩く紐づくだけのメモ。 マップの外パネル等から見るのが主用途)
  final bool freeMode;

  /// 配置モード経由 (= 「ここに置く」 タップ後) の新規作成。
  /// この場合、 ページ番号は配置タップ時点のものに既に確定しているため、
  /// ダイアログ側でページ番号入力 UI を出さず、 表示専用バッジを出す。
  final bool placedMode;
  const _PdfMemoEditDialog({
    this.initial,
    this.initialPage,
    this.initialUrl,
    this.freeMode = false,
    this.placedMode = false,
  });

  @override
  State<_PdfMemoEditDialog> createState() => _PdfMemoEditDialogState();
}

class _PdfMemoEditDialogState extends State<_PdfMemoEditDialog> {
  late TextEditingController _textCtrl;
  late int _colorValue;

  /// 確定済みのページ番号 (= 配置モードでタップした時点の現在ページ、
  /// もしくは編集対象のメモが持つ既存値)。 ユーザーは数値入力で変更可。
  int? _pageNumber;

  /// ページ番号テキスト入力用コントローラ。 空文字 = 「ページなし」 (フリー化)。
  late TextEditingController _pageCtrl;

  /// 確定済みの URL (URL メモの場合のみ非 null)。 同じく表示専用。
  String? _url;

  /// このメモに添付された画像のパス (= 本文先頭の `__MMIMG__::` マーカー
  /// から分離して保持)。 編集中は本文テキストには出さず、 保存時に
  /// もう一度先頭にマーカーを付け直すことで、 「画像つきメモを編集すると
  /// 画像が消える」 バグを防ぐ (= ユーザー要望)。
  String? _attachedImagePath;

  /// メモの色 (= ユーザー要望: カラーバリエーションが少ないから増やす)。
  static const _palette = <int>[
    0xFFFFC107, // amber
    0xFF4FC3F7, // light blue
    0xFF43B97F, // green
    0xFFE57373, // red
    0xFF9575CD, // purple
    0xFFFFB347, // orange
    0xFF26C6DA, // cyan
    0xFFF06292, // pink
    0xFFAED581, // light green
    0xFF7986CB, // indigo
    0xFFA1887F, // brown
    0xFF90A4AE, // blue grey
    0xFFFFF176, // light yellow
    0xFFFFFFFF, // white
  ];

  @override
  void initState() {
    super.initState();
    final init = widget.initial;
    // ── 画像マーカーを分離してから TextField に入れる ──
    // (= ユーザー要望「画像を貼り付けた後にテキストを同じメモに書くと
    //   画像が URL だけになって表示されなくなる問題を解決」)。
    // 元テキストが `__MMIMG__::<path>\n<body>` 形式なら、 画像パスは
    //   _attachedImagePath に保持し、 TextField には本文のみを入れる。
    //   保存時にマーカーを再付与する。
    final raw = init?.text ?? '';
    final (imgPath, body) = _parseMemoImage(raw);
    _attachedImagePath = imgPath;
    _textCtrl = TextEditingController(text: body);
    _colorValue = init?.colorValue ?? _palette.first;
    if (widget.freeMode) {
      _pageNumber = null;
      _url = null;
    } else {
      _pageNumber = init?.pageNumber ?? widget.initialPage;
      _url = init?.url ?? widget.initialUrl;
    }
    _pageCtrl =
        TextEditingController(text: _pageNumber != null ? '$_pageNumber' : '');
  }

  @override
  void dispose() {
    _textCtrl.dispose();
    _pageCtrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final provider = context.read<MindMapProvider>();
    final isEdit = widget.initial != null;
    // ヘッダー: メモの「種類バッジ」 を上部に出す。
    //   - 配置メモ (xRatio/yRatio あり / placedMode): ページ表示のみ
    //   - フリーメモ (位置なし、 URL なし): ページ任意入力
    //   - URL メモ: URL 表示
    Widget? headerBadge;
    final isPlacedMemo = widget.placedMode ||
        (widget.initial?.xRatio != null && widget.initial?.yRatio != null);
    final isFreeKind = !isPlacedMemo && _url == null;

    if (isPlacedMemo && _pageNumber != null) {
      headerBadge = Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
        decoration: BoxDecoration(
          color: const Color(0xFFFFC107).withValues(alpha: 0.18),
          borderRadius: BorderRadius.circular(6),
          border:
              Border.all(color: const Color(0xFFFFC107).withValues(alpha: 0.4)),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(Icons.place, color: Color(0xFFFFC107), size: 16),
            const SizedBox(width: 6),
            Text(
                context
                    .read<MindMapProvider>()
                    .t('pmemo.saveWithPosition')
                    .replaceFirst('{n}', '$_pageNumber'),
                style: const TextStyle(
                    color: Color(0xFFFFC107),
                    fontWeight: FontWeight.w600,
                    fontSize: 12.5)),
          ],
        ),
      );
    } else if (isFreeKind) {
      // フリーメモ: ページを任意で指定できる入力 UI
      headerBadge = Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
        decoration: BoxDecoration(
          color: Colors.white.withValues(alpha: 0.06),
          borderRadius: BorderRadius.circular(6),
        ),
        child: Row(
          children: [
            const Icon(Icons.notes, color: Colors.white60, size: 16),
            const SizedBox(width: 6),
            Flexible(
              child: Text(provider.t('pdfMemo.headerFreeMemo'),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style:
                      const TextStyle(color: Colors.white60, fontSize: 12.5)),
            ),
            const SizedBox(width: 8),
            Container(width: 1, height: 18, color: Colors.white12),
            const SizedBox(width: 6),
            Text(
              provider.t('pdfMemo.pageOptional'),
              style: const TextStyle(color: Colors.white54, fontSize: 12),
            ),
            const SizedBox(width: 4),
            InkWell(
              onTap: () {
                final cur = int.tryParse(_pageCtrl.text) ?? 0;
                if (cur > 1) {
                  setState(() {
                    _pageNumber = cur - 1;
                    _pageCtrl.text = '$_pageNumber';
                  });
                }
              },
              borderRadius: BorderRadius.circular(4),
              child: const Padding(
                padding: EdgeInsets.all(2),
                child: Icon(Icons.remove, color: Colors.white60, size: 16),
              ),
            ),
            SizedBox(
              width: 56,
              child: TextField(
                controller: _pageCtrl,
                keyboardType: TextInputType.number,
                textAlign: TextAlign.center,
                style: const TextStyle(
                    color: Colors.white,
                    fontSize: 13,
                    fontWeight: FontWeight.w700),
                decoration: InputDecoration(
                  isDense: true,
                  contentPadding:
                      const EdgeInsets.symmetric(horizontal: 4, vertical: 6),
                  hintText: provider.t('pdfMemo.pageHint'),
                  hintStyle:
                      const TextStyle(color: Colors.white24, fontSize: 12),
                  enabledBorder: const UnderlineInputBorder(
                    borderSide: BorderSide(color: Colors.white24, width: 1),
                  ),
                  focusedBorder: const UnderlineInputBorder(
                    borderSide:
                        BorderSide(color: Color(0xFFFFC107), width: 1.5),
                  ),
                ),
                onChanged: (v) {
                  final n = int.tryParse(v);
                  setState(() {
                    _pageNumber = (n != null && n >= 1) ? n : null;
                  });
                },
              ),
            ),
            InkWell(
              onTap: () {
                final cur = int.tryParse(_pageCtrl.text) ?? 0;
                setState(() {
                  _pageNumber = cur + 1;
                  _pageCtrl.text = '$_pageNumber';
                });
              },
              borderRadius: BorderRadius.circular(4),
              child: const Padding(
                padding: EdgeInsets.all(2),
                child: Icon(Icons.add, color: Colors.white60, size: 16),
              ),
            ),
          ],
        ),
      );
    } else if (_url != null) {
      headerBadge = Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
        decoration: BoxDecoration(
          color: const Color(0xFF4FC3F7).withValues(alpha: 0.10),
          borderRadius: BorderRadius.circular(6),
          border:
              Border.all(color: const Color(0xFF4FC3F7).withValues(alpha: 0.3)),
        ),
        child: Row(
          children: [
            const Icon(Icons.public, color: Color(0xFF4FC3F7), size: 16),
            const SizedBox(width: 8),
            Expanded(
              child: Text(
                _url!,
                style: const TextStyle(color: Colors.white70, fontSize: 12),
                overflow: TextOverflow.ellipsis,
              ),
            ),
          ],
        ),
      );
    } else {
      headerBadge = const SizedBox.shrink();
    }

    return AlertDialog(
      backgroundColor: const Color(0xFF1E1E2E),
      // 多言語対応 (= ユーザー報告: タイトルと追加ボタンが日本語固定だった)。
      title: Text(
          context
              .read<MindMapProvider>()
              .t(isEdit ? 'pmemo.editTitle' : 'pmemo.addTitle'),
          style: const TextStyle(color: Colors.white)),
      content: SizedBox(
        width: 380,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            headerBadge,
            const SizedBox(height: 12),
            // メモ本文 TextField。
            // Enter で確定、 Shift/Alt+Enter で改行。
            Shortcuts(
              shortcuts: <ShortcutActivator, Intent>{
                const SingleActivator(LogicalKeyboardKey.enter):
                    const _SubmitMemoIntent(),
                const SingleActivator(LogicalKeyboardKey.numpadEnter):
                    const _SubmitMemoIntent(),
              },
              child: Actions(
                actions: <Type, Action<Intent>>{
                  _SubmitMemoIntent: CallbackAction<_SubmitMemoIntent>(
                    onInvoke: (_) {
                      _handleConfirm();
                      return null;
                    },
                  ),
                },
                child: TextField(
                  controller: _textCtrl,
                  autofocus: true,
                  maxLines: 5,
                  minLines: 3,
                  style: const TextStyle(color: Colors.white, height: 1.4),
                  decoration: InputDecoration(
                    labelText:
                        context.read<MindMapProvider>().t('pmemo.memoContent'),
                    labelStyle: TextStyle(color: Colors.white70),
                    alignLabelWithHint: true,
                    enabledBorder: OutlineInputBorder(
                      borderSide: BorderSide(color: Colors.white24),
                    ),
                    focusedBorder: OutlineInputBorder(
                      borderSide: BorderSide(color: Color(0xFFFFC107)),
                    ),
                  ),
                ),
              ),
            ),
            const SizedBox(height: 12),
            Text(context.read<MindMapProvider>().t('common.color'),
                style: const TextStyle(color: Colors.white60, fontSize: 12)),
            const SizedBox(height: 6),
            Wrap(
              spacing: 8,
              children: _palette.map((c) {
                final picked = c == _colorValue;
                return GestureDetector(
                  onTap: () => setState(() => _colorValue = c),
                  child: Container(
                    width: 28,
                    height: 28,
                    decoration: BoxDecoration(
                      color: Color(c),
                      shape: BoxShape.circle,
                      border: Border.all(
                        color: picked ? Colors.white : Colors.transparent,
                        width: 2,
                      ),
                    ),
                  ),
                );
              }).toList(),
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(context).pop(),
          child: Text(context.read<MindMapProvider>().t('btn.cancel'),
              style: const TextStyle(color: Colors.white60)),
        ),
        ElevatedButton(
          style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFFFFC107),
              foregroundColor: Colors.black87),
          onPressed: _handleConfirm,
          child: Text(context
              .read<MindMapProvider>()
              .t(isEdit ? 'btn.update' : 'btn.add')),
        ),
      ],
    );
  }

  /// 「追加 / 更新」 ボタンと Enter キー両方から呼ばれる確定処理。
  void _handleConfirm() {
    final body = _textCtrl.text.trim();
    // ── 添付画像があれば必ずマーカーを再付与 (= ユーザー要望) ──
    // 画像のみのメモ (= 本文 0 文字) でもマーカーは残す。 本文も画像も
    //   無い (= 完全に空のメモ) ときだけキャンセル扱い。
    final hasImg = _attachedImagePath != null && _attachedImagePath!.isNotEmpty;
    if (body.isEmpty && !hasImg) {
      Navigator.of(context).pop();
      return;
    }
    final text = hasImg
        ? (body.isEmpty
            ? '$_kMemoImgPrefix${_attachedImagePath!}'
            : '$_kMemoImgPrefix${_attachedImagePath!}\n$body')
        : body;
    final result = PdfMemo(
      id: widget.initial?.id ?? 'tmp',
      text: text,
      pageNumber: _pageNumber,
      url: _url,
      xRatio: widget.initial?.xRatio,
      yRatio: widget.initial?.yRatio,
      colorValue: _colorValue,
    );
    Navigator.of(context).pop(result);
  }
}

/// Enter キーで PdfMemo 編集ダイアログを確定するための Intent。
/// `Shortcuts` + `Actions` で、 SingleActivator(enter) は修飾キー無しの時だけ
/// マッチする (= Shift/Alt/Ctrl/⌘ + Enter は TextField のデフォルト改行に流れる)。
class _SubmitMemoIntent extends Intent {
  const _SubmitMemoIntent();
}

// ──────────────────────────────────────────────────────────────────────────
// 「マップの外」 メモ フローティングパネル
// ──────────────────────────────────────────────────────────────────────────
//
// 現在のページ全体を横断して、 全ノードの `pdfMemos` を一覧表示するパネル。
// 設定シート / ヘッダーボタン / コンテキストメニューから開かれる。
// メモをクリックすると、 そのメモを持つノードの PDF / URL をアプリ内
// ビューアで開き、 該当ページ + 位置 (xRatio/yRatio はビューア内で
// マーカー描画) にジャンプ + パルスでハイライトする。
/// メモ一覧の 1 グループ (マップ単位) を折り畳めるようにするウィジェット
/// (= ユーザー要望: フォルダーやマップ毎にメモを折り畳める)。 ヘッダーをタップ
/// すると配下のメモタイルの表示/非表示が切り替わる。
class _CollapsibleMemoGroup extends StatefulWidget {
  final IconData icon;
  final Color iconColor;
  final Color labelColor;
  final String label;
  final int count;
  final List<Widget> children;
  final bool initiallyExpanded;
  const _CollapsibleMemoGroup({
    super.key,
    required this.icon,
    required this.iconColor,
    required this.labelColor,
    required this.label,
    required this.count,
    required this.children,
    this.initiallyExpanded = true,
  });
  @override
  State<_CollapsibleMemoGroup> createState() => _CollapsibleMemoGroupState();
}

class _CollapsibleMemoGroupState extends State<_CollapsibleMemoGroup> {
  late bool _expanded = widget.initiallyExpanded;
  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        InkWell(
          onTap: () => setState(() => _expanded = !_expanded),
          child: Padding(
            padding: const EdgeInsets.fromLTRB(8, 10, 12, 4),
            child: Row(children: [
              Icon(
                  _expanded
                      ? Icons.expand_more_rounded
                      : Icons.chevron_right_rounded,
                  color: Colors.white38,
                  size: 18),
              const SizedBox(width: 2),
              Icon(widget.icon, color: widget.iconColor, size: 16),
              const SizedBox(width: 6),
              Expanded(
                child: Text(widget.label,
                    style: TextStyle(
                        color: widget.labelColor,
                        fontSize: 12,
                        fontWeight: FontWeight.w700),
                    overflow: TextOverflow.ellipsis),
              ),
              Text('${widget.count}',
                  style: const TextStyle(color: Colors.white38, fontSize: 11)),
            ]),
          ),
        ),
        if (_expanded) ...widget.children,
      ],
    );
  }
}

class _MapPdfMemoListPanel extends StatelessWidget {
  /// 親の State から呼び戻すためのコールバック。
  /// 引数: nodeId, attachmentPath / URL, page (PDF), urlOverride (URL メモ)
  final void Function(
          String nodeId, String pathOrUrl, int? page, String? urlOverride)
      onOpenMemo;

  /// 「その他」タブでノードメモをタップした時、 そのノードへ画面を移動する。
  final void Function(String nodeId)? onFocusNode;

  const _MapPdfMemoListPanel({required this.onOpenMemo, this.onFocusNode});

  @override
  Widget build(BuildContext context) {
    return Consumer<MindMapProvider>(
      builder: (ctx, provider, _) {
        return Material(
          color: const Color(0xFF1E1E2E),
          // PDF/サイトのメモ と それ以外 (ノードメモ・サイトメモ・Google 検索メモ)
          // をタブで切り替えられる「メモ一覧」。
          child: DefaultTabController(
            length: 2,
            child: Column(
              children: [
                // ── ヘッダー ──
                Container(
                  height: 48,
                  padding: const EdgeInsets.symmetric(horizontal: 14),
                  decoration: const BoxDecoration(
                    border: Border(
                      bottom: BorderSide(color: Colors.white12, width: 1),
                    ),
                  ),
                  child: Row(
                    children: [
                      const Icon(Icons.sticky_note_2,
                          color: Color(0xFFFFC107), size: 20),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                            context.read<MindMapProvider>().t('pmemo.list'),
                            style: const TextStyle(
                                color: Colors.white,
                                fontSize: 15,
                                fontWeight: FontWeight.w700)),
                      ),
                      IconButton(
                        icon: const Icon(Icons.close,
                            color: Colors.white70, size: 20),
                        onPressed: () => Navigator.of(context).maybePop(),
                      ),
                    ],
                  ),
                ),
                // ── タブ ──
                const TabBar(
                  labelColor: Color(0xFFFFC107),
                  unselectedLabelColor: Colors.white54,
                  indicatorColor: Color(0xFFFFC107),
                  labelStyle:
                      TextStyle(fontSize: 13, fontWeight: FontWeight.w700),
                  tabs: [
                    Tab(text: 'PDF / サイト'),
                    Tab(text: 'その他'),
                  ],
                ),
                Expanded(
                  child: TabBarView(
                    children: [
                      _buildPdfMemoList(ctx, provider),
                      _buildOtherMemoList(ctx, provider),
                    ],
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  /// 「PDF / サイト」 タブ: 既存の PDF / URL メモ (PdfMemo) 一覧。
  Widget _buildPdfMemoList(BuildContext ctx, MindMapProvider provider) {
    // = ユーザー要望: 他のマップ / PDF ビューワーで書いたメモも参照・編集でき、
    //   メモの場所 (マップ) 毎にグループ化して表示する。
    final list = provider.allPdfMemos;
    if (list.isEmpty) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Text(
            provider.t('memoList.empty'),
            style: const TextStyle(color: Colors.white38, fontSize: 13),
            textAlign: TextAlign.center,
          ),
        ),
      );
    }
    // 場所 (マップ = pageId) 毎にグループ化。 list は更新日時降順なので、
    //   各グループの先頭が最新。 グループ順も最新メモ順。
    final groups = <String,
        List<
            ({String pageId, String pageName, String nodeId, PdfMemo memo})>>{};
    final pageNames = <String, String>{};
    for (final e in list) {
      groups.putIfAbsent(e.pageId, () => []).add(e);
      pageNames[e.pageId] = e.pageName;
    }
    final orderedPageIds = groups.keys.toList()
      ..sort((a, b) => groups[b]!
          .first
          .memo
          .updatedAtMs
          .compareTo(groups[a]!.first.memo.updatedAtMs));

    final items = <Widget>[];
    for (final pid in orderedPageIds) {
      final pname =
          (pageNames[pid] ?? '').isEmpty
              ? provider.t('memoList.untitledMap')
              : pageNames[pid]!;
      final isCurrent = pid == provider.currentPage.id;
      // ── マップ毎にメモを折り畳める (= ユーザー要望) ──
      //   各グループのタイルを集めて _CollapsibleMemoGroup で包む。
      final tiles = <Widget>[];
      for (final e in groups[pid]!) {
        // メモが属するノードを「そのページから」 取得 (= 他マップ対応)。
        MindMapNode? node;
        for (final p in provider.pages) {
          if (p.id == pid) {
            node = p.nodes[e.nodeId];
            break;
          }
        }
        final nodeTitle = (node?.title ?? '').isEmpty ? '(無題ノード)' : node!.title;
        final memo = e.memo;
        final attachPath = node?.attachmentPath ?? '';
        final linkUrl = (node?.linkUrl ?? '').isNotEmpty
            ? node!.linkUrl!
            : (node?.youtubeUrl ?? '');
        final canJump =
            (memo.url != null) || attachPath.isNotEmpty || linkUrl.isNotEmpty;
        tiles.add(_MapMemoListTile(
          nodeTitle: nodeTitle,
          memo: memo,
          canJump: canJump,
          onTap: canJump
              ? () {
                  if (memo.url != null) {
                    onOpenMemo(e.nodeId, memo.url!, null, memo.url);
                  } else if (attachPath.isNotEmpty) {
                    onOpenMemo(e.nodeId, attachPath, memo.pageNumber, null);
                  } else if (linkUrl.isNotEmpty) {
                    onOpenMemo(e.nodeId, linkUrl, null, null);
                  }
                }
              : null,
          onEdit: () async {
            final updated = await showDialog<PdfMemo?>(
              context: ctx,
              builder: (_) => _PdfMemoEditDialog(initial: memo),
            );
            if (updated != null) {
              provider.updatePdfMemoOnPage(
                pid,
                e.nodeId,
                memo.id,
                text: updated.text,
                pageNumber: updated.pageNumber,
                url: updated.url,
                colorValue: updated.colorValue,
              );
            }
          },
          onDelete: () => provider.removePdfMemoOnPage(pid, e.nodeId, memo.id),
        ));
      }
      items.add(_CollapsibleMemoGroup(
        key: ValueKey('pdfMemoGroup_$pid'),
        icon: Icons.folder_rounded,
        iconColor: isCurrent ? const Color(0xFFFFC107) : Colors.white38,
        labelColor: isCurrent ? const Color(0xFFFFC107) : Colors.white70,
        label: isCurrent ? '$pname (このマップ)' : pname,
        count: groups[pid]!.length,
        children: tiles,
      ));
    }
    return ListView(
      padding: const EdgeInsets.symmetric(vertical: 8),
      children: items,
    );
  }

  /// 「その他」 タブ: ノードのメモ (memoText)・サイトのメモ (web_page_memos)・
  /// Google 検索メモをまとめて表示する。
  Widget _buildOtherMemoList(BuildContext ctx, MindMapProvider provider) {
    // ① 現在ページのノードメモ
    final nodeMemos = <({String nodeId, String title, String text})>[];
    provider.nodes.forEach((id, n) {
      final t = (n.memoText ?? '').trim();
      if (t.isNotEmpty) {
        nodeMemos.add((
          nodeId: id,
          title: n.title.trim().isEmpty ? '(無題ノード)' : n.title.trim(),
          text: t,
        ));
      }
    });
    // ② サイトのメモ (web_page_memos: URL ごとのメモ文字列リスト)
    final webMemos = <({String url, String text})>[];
    provider.webPageMemos.forEach((url, memos) {
      for (final m in memos) {
        if (m.trim().isNotEmpty) webMemos.add((url: url, text: m.trim()));
      }
    });
    // ③ Google 検索メモ
    final gsMemos = provider.googleSearchMemos;

    if (nodeMemos.isEmpty && webMemos.isEmpty && gsMemos.isEmpty) {
      return const Center(
        child: Padding(
          padding: EdgeInsets.all(24),
          child: Text(
            'ノードのメモ・サイトのメモ・Google 検索メモは\nまだありません。',
            style: TextStyle(color: Colors.white38, fontSize: 13),
            textAlign: TextAlign.center,
          ),
        ),
      );
    }

    return ListView(
      padding: const EdgeInsets.symmetric(vertical: 8),
      children: [
        if (nodeMemos.isNotEmpty) ...[
          _otherSectionHeader(
              'ノードのメモ', Icons.notes_rounded, const Color(0xFF4FC3F7)),
          for (final m in nodeMemos)
            _otherMemoTile(
              icon: Icons.notes_rounded,
              color: const Color(0xFF4FC3F7),
              title: m.title,
              body: m.text,
              actionIcon: Icons.my_location_rounded,
              onTap: onFocusNode == null ? null : () => onFocusNode!(m.nodeId),
            ),
        ],
        if (webMemos.isNotEmpty) ...[
          _otherSectionHeader(
              'サイトのメモ', Icons.language_rounded, const Color(0xFF81C784)),
          for (final m in webMemos)
            _otherMemoTile(
              icon: Icons.language_rounded,
              color: const Color(0xFF81C784),
              title: _hostOf(m.url),
              body: m.text,
              actionIcon: Icons.open_in_new_rounded,
              onTap: () => onOpenMemo('', m.url, null, m.url),
            ),
        ],
        if (gsMemos.isNotEmpty) ...[
          _otherSectionHeader(
              'Google 検索メモ', Icons.search_rounded, const Color(0xFF90CAF9)),
          for (final m in gsMemos)
            _otherMemoTile(
              icon: Icons.search_rounded,
              color: const Color(0xFF90CAF9),
              title: m.displayTitle,
              body: m.text,
              onTap: null,
            ),
        ],
      ],
    );
  }

  String _hostOf(String url) {
    final u = Uri.tryParse(url);
    final h = u?.host ?? '';
    return h.isEmpty ? url : h;
  }

  Widget _otherSectionHeader(String label, IconData icon, Color color) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 12, 14, 6),
      child: Row(
        children: [
          Icon(icon, size: 15, color: color),
          const SizedBox(width: 6),
          Text(label,
              style: TextStyle(
                  color: color, fontSize: 12, fontWeight: FontWeight.w700)),
        ],
      ),
    );
  }

  Widget _otherMemoTile({
    required IconData icon,
    required Color color,
    required String title,
    required String body,
    IconData? actionIcon,
    VoidCallback? onTap,
  }) {
    return InkWell(
      onTap: onTap,
      child: Container(
        margin: const EdgeInsets.symmetric(horizontal: 10, vertical: 3),
        padding: const EdgeInsets.all(10),
        decoration: BoxDecoration(
          color: const Color(0xFF26263A),
          borderRadius: BorderRadius.circular(10),
          border: Border(left: BorderSide(color: color, width: 3)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Expanded(
                  child: Text(
                    title,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 13,
                        fontWeight: FontWeight.w700),
                  ),
                ),
                if (onTap != null && actionIcon != null)
                  Icon(actionIcon, size: 14, color: Colors.white38),
              ],
            ),
            const SizedBox(height: 4),
            Text(
              body,
              maxLines: 4,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(color: Colors.white70, fontSize: 12),
            ),
          ],
        ),
      ),
    );
  }
}

