class _CreateTableResult {
  final int rows;
  final int cols;
  const _CreateTableResult(this.rows, this.cols);
}

class _CreateTableDialog extends StatefulWidget {
  final MindMapProvider provider;
  final bool isDarkMode;
  const _CreateTableDialog({
    required this.provider,
    required this.isDarkMode,
  });

  @override
  State<_CreateTableDialog> createState() => _CreateTableDialogState();
}

class _CreateTableDialogState extends State<_CreateTableDialog> {
  int _hoverRows = 3;
  int _hoverCols = 3;
  late final TextEditingController _rowCtrl;
  late final TextEditingController _colCtrl;
  bool _popped = false; // 二重 pop 防止 (onTapUp と onPanEnd が両方発火しうる)

  static const int _maxQuickRows = 10;
  static const int _maxQuickCols = 10;
  static const int _maxRows = 100;
  static const int _maxCols = 30;
  static const double _cellSize = 22.0;
  static const double _cellGap = 2.0;

  @override
  void initState() {
    super.initState();
    _rowCtrl = TextEditingController(text: _hoverRows.toString());
    _colCtrl = TextEditingController(text: _hoverCols.toString());
  }

  @override
  void dispose() {
    _rowCtrl.dispose();
    _colCtrl.dispose();
    super.dispose();
  }

  void _setHoverFromLocal(Offset local) {
    const stride = _cellSize + _cellGap;
    int col = ((local.dx) / stride).floor() + 1;
    int row = ((local.dy) / stride).floor() + 1;
    col = col.clamp(0, _maxQuickCols);
    row = row.clamp(0, _maxQuickRows);
    if (row != _hoverRows || col != _hoverCols) {
      setState(() {
        _hoverRows = row;
        _hoverCols = col;
        _rowCtrl.text = row.toString();
        _colCtrl.text = col.toString();
      });
    }
  }

  void _confirmFromQuick() {
    if (_popped) return;
    _popped = true;
    final r = _hoverRows.clamp(1, _maxRows);
    final c = _hoverCols.clamp(1, _maxCols);
    Navigator.of(context).pop<_CreateTableResult>(_CreateTableResult(r, c));
  }

  void _confirmFromInput() {
    if (_popped) return;
    _popped = true;
    final r = (int.tryParse(_rowCtrl.text.trim()) ?? 3).clamp(1, _maxRows);
    final c = (int.tryParse(_colCtrl.text.trim()) ?? 3).clamp(1, _maxCols);
    Navigator.of(context).pop<_CreateTableResult>(_CreateTableResult(r, c));
  }

  @override
  Widget build(BuildContext context) {
    final p = widget.provider;
    final isDark = widget.isDarkMode;
    final bg = isDark ? const Color(0xFF2A2A35) : const Color(0xFFFAFAFA);
    final fg = isDark ? Colors.white : const Color(0xFF222222);
    final mutedFg = isDark ? Colors.white70 : const Color(0xFF555555);
    const accent = Color(0xFF6C63FF);

    final gridW = _maxQuickCols * _cellSize + (_maxQuickCols - 1) * _cellGap;
    final gridH = _maxQuickRows * _cellSize + (_maxQuickRows - 1) * _cellGap;

    return Focus(
      // ダイアログを開いた直後、 どの TextField にもフォーカスが無い状態で
      // Enter を押すと _confirmFromInput が呼ばれて作成される。 TextField
      // にフォーカスがある場合は TextField の onSubmitted (rows/cols 両方
      // に設定済み) が先に発火する。
      // ユーザー要望: 「作成のボタンは Enter でそのまま進めるようにして」。
      autofocus: true,
      onKeyEvent: (node, event) {
        if (event is KeyDownEvent &&
            (event.logicalKey == LogicalKeyboardKey.enter ||
                event.logicalKey == LogicalKeyboardKey.numpadEnter)) {
          _confirmFromInput();
          return KeyEventResult.handled;
        }
        return KeyEventResult.ignored;
      },
      child: Dialog(
        backgroundColor: bg,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 360),
          child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 18, 20, 14),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(children: [
                  const Icon(Icons.grid_on_rounded, color: accent, size: 22),
                  const SizedBox(width: 8),
                  Text(p.t('tableDialog.title'),
                      style: TextStyle(
                          color: fg,
                          fontSize: 17,
                          fontWeight: FontWeight.w700)),
                ]),
                const SizedBox(height: 14),
                Center(
                  child: MouseRegion(
                    onHover: (e) => _setHoverFromLocal(e.localPosition),
                    child: GestureDetector(
                      onTapDown: (d) => _setHoverFromLocal(d.localPosition),
                      onPanStart: (d) => _setHoverFromLocal(d.localPosition),
                      onPanUpdate: (d) => _setHoverFromLocal(d.localPosition),
                      onTapUp: (_) => _confirmFromQuick(),
                      onPanEnd: (_) => _confirmFromQuick(),
                      child: SizedBox(
                        width: gridW,
                        height: gridH,
                        child: CustomPaint(
                          painter: _CreateTableGridPainter(
                            rows: _maxQuickRows,
                            cols: _maxQuickCols,
                            cellSize: _cellSize,
                            gap: _cellGap,
                            selectedRows: _hoverRows,
                            selectedCols: _hoverCols,
                            accent: accent,
                            baseColor: isDark
                                ? const Color(0xFF3A3A45)
                                : const Color(0xFFE0E0E0),
                            borderColor: isDark
                                ? const Color(0xFF555560)
                                : const Color(0xFFBBBBBB),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
                const SizedBox(height: 10),
                Center(
                  child: Text(
                    '${_hoverRows}${p.t("tableDialog.rows")} × ${_hoverCols}${p.t("tableDialog.cols")}',
                    style: TextStyle(
                        color: fg, fontSize: 15, fontWeight: FontWeight.w600),
                  ),
                ),
                const SizedBox(height: 16),
                Text(p.t('tableDialog.customSize'),
                    style: TextStyle(
                        color: mutedFg,
                        fontSize: 12,
                        fontWeight: FontWeight.w600)),
                const SizedBox(height: 6),
                Row(children: [
                  Expanded(
                    child: _numField(
                      controller: _rowCtrl,
                      label: p.t('tableDialog.rows'),
                      fg: fg,
                      mutedFg: mutedFg,
                      accent: accent,
                      onChanged: (v) {
                        final r = int.tryParse(v) ?? 0;
                        if (r >= 1 && r <= _maxQuickRows) {
                          setState(() => _hoverRows = r);
                        }
                      },
                      // 行数フィールドで Enter → そのまま作成
                      onSubmitted: (_) => _confirmFromInput(),
                    ),
                  ),
                  const SizedBox(width: 10),
                  Text('×', style: TextStyle(color: mutedFg, fontSize: 18)),
                  const SizedBox(width: 10),
                  Expanded(
                    child: _numField(
                      controller: _colCtrl,
                      label: p.t('tableDialog.cols'),
                      fg: fg,
                      mutedFg: mutedFg,
                      accent: accent,
                      onChanged: (v) {
                        final c = int.tryParse(v) ?? 0;
                        if (c >= 1 && c <= _maxQuickCols) {
                          setState(() => _hoverCols = c);
                        }
                      },
                      onSubmitted: (_) => _confirmFromInput(),
                    ),
                  ),
                ]),
                const SizedBox(height: 16),
                Row(
                  mainAxisAlignment: MainAxisAlignment.end,
                  children: [
                    TextButton(
                      onPressed: () => Navigator.of(context).pop(),
                      child: Text(p.t('tableDialog.cancel'),
                          style: TextStyle(color: mutedFg)),
                    ),
                    const SizedBox(width: 8),
                    ElevatedButton.icon(
                      onPressed: _confirmFromInput,
                      icon: const Icon(Icons.check_rounded, size: 18),
                      label: Text(p.t('tableDialog.create')),
                      style: ElevatedButton.styleFrom(
                        backgroundColor: accent,
                        foregroundColor: Colors.white,
                        shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(10)),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _numField({
    required TextEditingController controller,
    required String label,
    required Color fg,
    required Color mutedFg,
    required Color accent,
    ValueChanged<String>? onChanged,
    ValueChanged<String>? onSubmitted,
  }) {
    return TextField(
      controller: controller,
      keyboardType: TextInputType.number,
      inputFormatters: [FilteringTextInputFormatter.digitsOnly],
      style: TextStyle(color: fg, fontSize: 14),
      decoration: InputDecoration(
        labelText: label,
        labelStyle: TextStyle(color: mutedFg, fontSize: 12),
        isDense: true,
        contentPadding:
            const EdgeInsets.symmetric(horizontal: 10, vertical: 10),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(8),
          borderSide: BorderSide(color: mutedFg.withValues(alpha: 0.4)),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(8),
          borderSide: BorderSide(color: accent, width: 1.4),
        ),
      ),
      onChanged: onChanged,
      onSubmitted: onSubmitted,
    );
  }
}

/// `_CreateTableDialog` のグリッド描画 CustomPainter。
class _CreateTableGridPainter extends CustomPainter {
  final int rows;
  final int cols;
  final double cellSize;
  final double gap;
  final int selectedRows;
  final int selectedCols;
  final Color accent;
  final Color baseColor;
  final Color borderColor;

  _CreateTableGridPainter({
    required this.rows,
    required this.cols,
    required this.cellSize,
    required this.gap,
    required this.selectedRows,
    required this.selectedCols,
    required this.accent,
    required this.baseColor,
    required this.borderColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final base = Paint()..color = baseColor;
    final sel = Paint()..color = accent.withValues(alpha: 0.85);
    final border = Paint()
      ..color = borderColor
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.0;
    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        final x = c * (cellSize + gap);
        final y = r * (cellSize + gap);
        final rect = Rect.fromLTWH(x, y, cellSize, cellSize);
        final isSelected = r < selectedRows && c < selectedCols;
        canvas.drawRRect(
          RRect.fromRectAndRadius(rect, const Radius.circular(3)),
          isSelected ? sel : base,
        );
        canvas.drawRRect(
          RRect.fromRectAndRadius(rect, const Radius.circular(3)),
          border,
        );
      }
    }
  }

  @override
  bool shouldRepaint(_CreateTableGridPainter old) =>
      old.selectedRows != selectedRows ||
      old.selectedCols != selectedCols ||
      old.rows != rows ||
      old.cols != cols ||
      old.accent != accent;
}

// ─── 画面分割パネル: Windows 専用 WebView ラッパー ──────────────────────
//
// webview_windows は WebviewController の初期化が非同期 (WebView2 runtime
// との接続) なので、 StatefulWidget で initialize() の完了を待ち、 準備が
// できてから wv_win.Webview を描画する。 親の _MindMapScreenState からは
// onControllerReady でコントローラを受け取って goBack/reload/loadUrl を
// 操作できるようにする。
class _SplitWindowsWebView extends StatefulWidget {
  final String url;
  final ValueChanged<wv_win.WebviewController> onControllerReady;
  final VoidCallback onInitialized;

  /// ── 現在 URL の変更通知 ──
  /// ユーザー要望「画面分割と全画面を切り替える際に画面が更新されて
  ///   セッションが失われてしまう」 への対応。 split webview 内でページ
  ///   遷移した時、 親 (_MindMapScreenState) の _splitCurrentUrl /
  ///   _splitLeftCurrentUrl を最新に保つためのコールバック。 これで全画面
  ///   切り替え時に「最初に開いた URL」 ではなく「今見ているページ」 を
  ///   開き直せる (ログイン Cookie は WebView2 共有プロファイルで保持)。
  final ValueChanged<String>? onUrlChanged;
  const _SplitWindowsWebView({
    super.key,
    required this.url,
    required this.onControllerReady,
    required this.onInitialized,
    this.onUrlChanged,
  });
  @override
  State<_SplitWindowsWebView> createState() => _SplitWindowsWebViewState();
}

class _SplitWindowsWebViewState extends State<_SplitWindowsWebView> {
  wv_win.WebviewController _controller = wv_win.WebviewController();
  bool _initialized = false;
  bool _initializing = false;
  int _initAttempt = 0;
  Timer? _initRetryTimer;
  String? _error;
  bool _oauthHandoffInProgress = false;
  DateTime? _lastOAuthHandoffAt;
  String _lastSafeServiceUrl = '';

  /// 直近にロード / 報告した URL。 onUrlChanged で親へ通知した URL が
  /// 親の setState 経由で widget.url に echo されてきても、 didUpdateWidget
  /// で再ロードしてしまわないようにするためのガード。
  String _lastLoadedOrReportedUrl = '';

  /// 埋め込み WebView を拒否する OAuth 画面へ移動したら、認証 URL 自体では
  /// なく直前のサービス URL を既定ブラウザで開く。ブラウザ側でもう一度
  /// 「Google で続行」を押せば通常のブラウザセッションで認証できる。
  ///
  /// 同時に WebView を直前ページへ戻すことで、認証画面とサービス画面を
  /// 行き来する SourceChanged の更新ループを止める。
  Future<void> _handoffOAuthToExternalBrowser() async {
    if (_oauthHandoffInProgress) return;
    final fallback = isSafeExternalServiceUrl(_lastSafeServiceUrl)
        ? _lastSafeServiceUrl
        : (isSafeExternalServiceUrl(widget.url) ? widget.url : '');
    if (fallback.isEmpty) return;

    _oauthHandoffInProgress = true;
    try {
      final now = DateTime.now();
      final recentlyOpened = _lastOAuthHandoffAt != null &&
          now.difference(_lastOAuthHandoffAt!) < const Duration(seconds: 30);
      if (!recentlyOpened) {
        _lastOAuthHandoffAt = now;
        try {
          final opened = await launchUrl(
            Uri.parse(fallback),
            mode: LaunchMode.externalApplication,
          );
          if (opened && mounted) {
            _appSnack(
              context,
              SnackBar(
                content: Text(context.read<MindMapProvider>().t('login.externalBrowserDefault')),
                backgroundColor: const Color(0xFF6C63FF),
                duration: const Duration(seconds: 3),
              ),
            );
          }
        } catch (e) {
          debugPrint('OAuth external-browser handoff failed: $e');
        }
      }

      _lastLoadedOrReportedUrl = fallback;
      try {
        await _controller.loadUrl(fallback);
      } catch (_) {}
    } finally {
      Future<void>.delayed(const Duration(seconds: 2), () {
        if (mounted) _oauthHandoffInProgress = false;
      });
    }
  }

  @override
  void initState() {
    super.initState();
    if (isSafeExternalServiceUrl(widget.url)) {
      _lastSafeServiceUrl = widget.url;
    }
    _init();
  }

  Future<void> _init() async {
    if (_initialized || _initializing || !mounted) return;
    // ── Linux: webview_windows 非対応 → CEF (build 側の LinuxWebViewWidget) に
    //   委譲する。 wv_win コントローラは初期化しない (= 呼ぶと例外)。 初期化済み
    //   フラグだけ立てて表示に進める。 コントローラ駆動の JS 注入機能は Linux
    //   では縮退するが、 ページ表示・基本ナビゲーションは LinuxWebViewWidget が
    //   担う。 Windows 側のコードは下の try ブロックのまま無変更。
    if (Platform.isLinux) {
      if (!mounted) return;
      widget.onInitialized();
      setState(() => _initialized = true);
      return;
    }
    _initializing = true;
    final attempt = ++_initAttempt;
    final controller = _controller;
    try {
      // WebView2 Runtime が稀に initialize Future を完了しないことがある。
      // 永久スピナーを避け、一定時間後に新しい controller で自動再試行する。
      await controller
          .initialize()
          .timeout(const Duration(seconds: 12));
      if (!mounted || !identical(controller, _controller)) return;
      await controller.setBackgroundColor(const Color(0xFF0F0F1A));
      // popup を現在の WebView に流し、URL stream で OAuth 遷移を検知する。
      // window.open の偽装は認証 SDK の popup polling/postMessage を壊し、
      // 同じ画面を再読込し続ける原因になるため行わない。
      try {
        await controller
            .setPopupWindowPolicy(wv_win.WebviewPopupWindowPolicy.sameWindow);
      } catch (_) {}
      controller.url.listen((u) {
        if (u.isEmpty) return;
        if (isBlockedEmbeddedOAuthUrl(u)) {
          unawaited(_handoffOAuthToExternalBrowser());
          return;
        }
        if (isSafeExternalServiceUrl(u)) {
          _lastSafeServiceUrl = u;
        }
        _lastLoadedOrReportedUrl = u;
        widget.onUrlChanged?.call(u);
      });
      // Runtime の準備が終わった時点で初期化画面を外す。以前は AI サイトの
      // loadUrl 完了までスピナーを出していたため、通信遅延も初期化停止に見えた。
      setState(() {
        _initialized = true;
        _initializing = false;
        _error = null;
      });
      widget.onControllerReady(controller);
      widget.onInitialized();
      try {
        await controller
            .loadUrl(widget.url)
            .timeout(const Duration(seconds: 15));
      } catch (e) {
        debugPrint('Split WebView initial navigation delayed/failed: $e');
      }
      _lastLoadedOrReportedUrl = widget.url;
    } catch (e) {
      if (!mounted || !identical(controller, _controller)) return;
      _initializing = false;
      if (attempt < 3) {
        // タイムアウトした controller を使い回さず、短いバックオフ後に交換する。
        _initRetryTimer?.cancel();
        _initRetryTimer = Timer(Duration(milliseconds: 700 * attempt), () {
          if (!mounted || _initialized) return;
          final previous = _controller;
          _controller = wv_win.WebviewController();
          try {
            unawaited(previous.dispose());
          } catch (_) {}
          _init();
          setState(() {});
        });
        setState(() => _error = null);
      } else {
        setState(() => _error = e.toString());
      }
    }
  }

  void _retryInitialization() {
    if (_initializing) return;
    _initRetryTimer?.cancel();
    final previous = _controller;
    _controller = wv_win.WebviewController();
    try {
      unawaited(previous.dispose());
    } catch (_) {}
    setState(() {
      _error = null;
      _initAttempt = 0;
    });
    _init();
  }

  @override
  void didUpdateWidget(covariant _SplitWindowsWebView oldWidget) {
    super.didUpdateWidget(oldWidget);
    // URL が外部から変わったら反映 (URL 入力欄から再ロードされた時)。
    // ただし、 webview 自身の遷移を onUrlChanged で親へ通知 → 親の
    // setState で widget.url に echo されてきたケースでは再ロードしない
    // (= 無限ループ / 余計なリロード防止)。
    if (!_initialized ||
        widget.url == oldWidget.url ||
        widget.url.isEmpty ||
        widget.url == _lastLoadedOrReportedUrl) return;
    if (isBlockedEmbeddedOAuthUrl(widget.url)) {
      unawaited(_handoffOAuthToExternalBrowser());
      return;
    }
    if (isSafeExternalServiceUrl(widget.url)) {
      _lastSafeServiceUrl = widget.url;
    }
    _lastLoadedOrReportedUrl = widget.url;
    _controller.loadUrl(widget.url);
  }

  @override
  void dispose() {
    _initRetryTimer?.cancel();
    // Linux では _controller を initialize していないので dispose しない。
    // ── 音が鳴り続ける対策 (= ユーザー報告: YouTube の画面を閉じても
    //    音声が流れ続けることがある)。 再生中に dispose だけすると、 下の
    //    WebView2 が再生を続けたまま残ることがある。 about:blank へ移して
    //    ページごと止めてから、 次のイベントループで破棄する。 ──
    if (!Platform.isLinux) {
      final ctrl = _controller;
      Future(() async {
        try {
          await ctrl.loadUrl('about:blank');
        } catch (_) {}
        try {
          await ctrl.dispose();
        } catch (_) {}
      });
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    // ── Linux: CEF (LinuxWebViewWidget) で表示。 Windows/モバイルは従来通り。
    if (Platform.isLinux) {
      return linux_wv.LinuxWebViewWidget(
        url: widget.url,
        onUrlChanged: widget.onUrlChanged,
      );
    }
    if (_error != null) {
      return Container(
        color: const Color(0xFF0F0F1A),
        alignment: Alignment.center,
        padding: const EdgeInsets.all(24),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              'WebView 初期化エラー:\n$_error',
              style:
                  const TextStyle(color: Colors.redAccent, fontSize: 12),
              textAlign: TextAlign.center,
            ),
            const SizedBox(height: 14),
            OutlinedButton.icon(
              onPressed: _retryInitialization,
              icon: const Icon(Icons.refresh_rounded, size: 17),
              label: Text(
                context.read<MindMapProvider>().t('fsv.retry'),
              ),
              style: OutlinedButton.styleFrom(
                foregroundColor: Colors.white70,
                side: const BorderSide(color: Colors.white24),
              ),
            ),
          ],
        ),
      );
    }
    if (!_initialized) {
      return Container(
        color: const Color(0xFF0F0F1A),
        alignment: Alignment.center,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            CircularProgressIndicator(
                valueColor: AlwaysStoppedAnimation<Color>(Color(0xFF6C63FF))),
            SizedBox(height: 12),
            Text(context.read<MindMapProvider>().t('webview.initializing2'),
                style: TextStyle(color: Colors.white54, fontSize: 12)),
          ],
        ),
      );
    }
    return wv_win.Webview(
      _controller,
      permissionRequested: (url, kind, isUserInitiated) =>
          wv_win.WebviewPermissionDecision.allow,
    );
  }
}

// ════════════════════════════════════════════════════════════════════════

// ════════════════════════════════════════════════════════════════════════
//  CSV / XLSX エディタ (アプリ内編集)
// ════════════════════════════════════════════════════════════════════════
//
// _openAttachment から呼び出され、外部アプリ (Excel / Numbers 等) を起動せず
// アプリ内で表計算ファイルを直接編集できるようにする。
//
// 対応形式:
//   - .csv  : csv パッケージで decode / encode (UTF-8、BOM 付き出力で Excel 互換)
//   - .tsv  : タブ区切りとして同様に decode / encode
//   - .xlsx : excel パッケージで decode / encode (最初のシートを表示。
//             複数シートあればタブで切替可能)
//
// 設計:
//   - 内部表現は List<List<String>> (rows × cols) に統一
//   - 編集はインライン (セルをタップ→TextField→Enter で確定)
//   - PC ではキーボードナビ (Tab / Shift+Tab / 矢印 / Enter / Esc / Ctrl+S)
//   - 保存時は元パスに同形式で上書き、Excel インスタンスを使い回して書式保持
//   - 未保存変更がある状態で閉じようとしたら確認ダイアログ

/// 表 (= ユーザー要望: xlsx で表の挿入ができるように) 1 個分。
/// セルの中身は今までどおり文字列のまま持ち、 見た目 (見出しの塗り / 縞 /
/// 罫線) だけをこの範囲情報として重ねる。 保存時は excel の CellStyle に
/// 変換して書き出すので、 本家 Excel で開いても同じ見た目になる。
class _SsTable {
  int row;
  int col;
  int rows;
  int cols;

  /// 見出し行の背景色 / 文字色 / 縞 / 罫線 (RGB 24bit、 null = 無し)。
  final int? headerFill;
  final int? headerFont;
  final int? bandFill;
  final int? line;

  _SsTable({
    required this.row,
    required this.col,
    required this.rows,
    required this.cols,
    this.headerFill,
    this.headerFont,
    this.bandFill,
    this.line,
  });

  bool contains(int r, int c) =>
      r >= row && r < row + rows && c >= col && c < col + cols;

  _SsTable copy() => _SsTable(
        row: row,
        col: col,
        rows: rows,
        cols: cols,
        headerFill: headerFill,
        headerFont: headerFont,
        bandFill: bandFill,
        line: line,
      );

  Map<String, dynamic> toJson() => {
        'r': row,
        'c': col,
        'rows': rows,
        'cols': cols,
        if (headerFill != null) 'head': headerFill,
        if (headerFont != null) 'headFont': headerFont,
        if (bandFill != null) 'band': bandFill,
        if (line != null) 'line': line,
      };

  static _SsTable? fromJson(Map m) {
    final r = (m['r'] as num?)?.toInt();
    final c = (m['c'] as num?)?.toInt();
    final rows = (m['rows'] as num?)?.toInt();
    final cols = (m['cols'] as num?)?.toInt();
    if (r == null || c == null || rows == null || cols == null) return null;
    return _SsTable(
      row: r,
      col: c,
      rows: rows,
      cols: cols,
      headerFill: (m['head'] as num?)?.toInt(),
      headerFont: (m['headFont'] as num?)?.toInt(),
      bandFill: (m['band'] as num?)?.toInt(),
      line: (m['line'] as num?)?.toInt(),
    );
  }
}

/// シートに貼った図 (= ユーザー要望: xlsx で図の挿入ができるように)。
/// 位置はセル番号 + そこからのピクセル、 大きさはピクセルで持つ。
/// 保存時に xlsx の drawing (xl/media + xl/drawings) として書き出す。
class _SsImage {
  final Uint8List bytes;
  final String ext;
  final String mediaName;
  int row;
  int col;
  double width;
  double height;

  /// セルの位置からのずれ (px)。 自由な場所に置けるようにするため
  /// (= ユーザー要望: 図をドラッグして好きな位置へ)。
  double dx;
  double dy;

  /// グラフとして作った物なら、 その元になった設定
  /// (= ユーザー要望: 題名・凡例・軸を後から変えられるように)。
  /// 元の範囲 (A1 形式) と、 作った時の指定を覚えておく。
  Map<String, dynamic>? chart;

  _SsImage({
    required this.bytes,
    required this.ext,
    required this.mediaName,
    required this.row,
    required this.col,
    required this.width,
    required this.height,
    this.dx = 0,
    this.dy = 0,
    this.chart,
  });

  _SsImage copy() => _SsImage(
        bytes: bytes,
        ext: ext,
        mediaName: mediaName,
        row: row,
        col: col,
        dx: dx,
        dy: dy,
        chart: chart == null ? null : Map<String, dynamic>.from(chart!),
        width: width,
        height: height,
      );

  /// 中身 (bytes) は xl/media 側に入るので、 ここでは置き場所だけ。
  Map<String, dynamic> toJson() => {
        'media': mediaName,
        if (dx != 0) 'dx': dx,
        if (dy != 0) 'dy': dy,
        if (chart != null) 'chart': chart,
        'ext': ext,
        'r': row,
        'c': col,
        'w': width,
        'h': height,
      };
}

enum _SpreadsheetKind { csv, tsv, xlsx }

/// _SpreadsheetEditorDialog の undo/redo 用スナップショット。
/// シート全体 (= 全シートの 2 次元セル値) + 選択状態を持つ。
class _SheetSnapshot {
  /// 表 / 図も一緒に控える (= ユーザー要望: Ctrl+Z で作った表も取り消せる
  /// ように)。 シート名 → その中身。
  Map<String, List<_SsTable>> tables = const {};
  Map<String, List<_SsImage>> images = const {};

  final Map<String, List<List<String>>> sheets;
  final List<String> sheetNames;
  final String activeSheet;
  final int selRow;
  final int selCol;
  _SheetSnapshot(
      this.sheets, this.sheetNames, this.activeSheet, this.selRow, this.selCol);
}

class _SpreadsheetEditorDialog extends StatefulWidget {
  final String filePath;
  final String fileName;
  final bool isDarkMode;
  final VoidCallback? onSaved;

  /// ファイル名変更後に呼ばれる。 (newPath, newName) を受け取って、
  /// 呼び出し側 (ノード) の attachmentPath/Name を更新するために使う。
  final void Function(String newPath, String newName)? onRenamed;

  /// 「画面分割で開く」 ボタン押下時に呼ばれる。 画面分割パネル内で
  /// 表示されている時は null を渡してボタン非表示。
  /// ユーザー要望: 「word や excel が左画面分割に対応していないから対応
  ///   するようにして」 + 左右指定 (`isLeftPanel`)。
  final void Function(String path, String name, {bool isLeftPanel})?
      onSplitOpen;

  const _SpreadsheetEditorDialog({
    required this.filePath,
    required this.fileName,
    this.isDarkMode = true,
    this.onSaved,
    this.onRenamed,
    this.onSplitOpen,
  });

  @override
  State<_SpreadsheetEditorDialog> createState() =>
      _SpreadsheetEditorDialogState();
}

class _SpreadsheetEditorDialogState extends State<_SpreadsheetEditorDialog> {
  // シート名 → 2 次元セル値 (rows[r][c])
  final Map<String, List<List<String>>> _sheets = {};
  List<String> _sheetNames = [];
  String _activeSheet = '';

  // ─── ファイルパス / 名前 (リネーム対応) ─────────────────────────────
  /// 現在のファイルパス。 widget.filePath を初期値とし、 リネーム時に更新。
  late String _currentFilePath = widget.filePath;

  /// 現在のファイル表示名。 widget.fileName を初期値とし、 リネーム時に更新。
  late String _currentFileName = widget.fileName;

  // ─── AI 編集 ─────────────────────────────────────────────────────
  /// AI 編集中フラグ (ヘッダのスピナー表示用)
  bool _aiBusy = false;

  /// AI 編集前のスナップショット ([sheetName] → 行データ)
  /// 「元に戻す」 用。AI 編集を実行するたび上書き。
  Map<String, List<List<String>>>? _aiUndoSnapshot;

  // ─── 数式 ────────────────────────────────────────────────────────
  /// 数式を評価して結果を表示するか (true)、 数式そのものを表示するか (false)
  /// デフォルトは true。 ヘッダのトグルで切替。
  bool _showFormulaResults = true;

  /// 現在シートの数式エバリュエータ。 シート切替や編集時にリセットされる。
  _FormulaEvaluator? _formulaEval;

  /// XLSX 読み込み時の Excel インスタンス。書き戻し時に再利用して書式保持。
  xls.Excel? _excel;
  _SpreadsheetKind _kind = _SpreadsheetKind.csv;

  bool _loading = true;
  bool _dirty = false;
  String? _loadError;

  // 編集中セル
  int? _editingRow;
  int? _editingCol;

  final TextEditingController _editCtrl = TextEditingController();
  final FocusNode _editFocus = FocusNode();
  final FocusNode _keyFocus = FocusNode();

  final ScrollController _vScroll = ScrollController();
  final ScrollController _hScroll = ScrollController();

  static const double _cellWidth = 120.0;
  static const double _cellHeight = 32.0;
  static const double _rowHeaderWidth = 48.0;
  static const double _colHeaderHeight = 28.0;

  // ─── Undo / Redo ────────────────────────────────────────────────
  final List<_SheetSnapshot> _undoStack = [];
  final List<_SheetSnapshot> _redoStack = [];
  static const int _maxHistory = 100;

  /// 現在の状態を _SheetSnapshot にキャプチャ (ディープコピー)。
  _SheetSnapshot _captureSnapshot() {
    final copy = <String, List<List<String>>>{};
    for (final e in _sheets.entries) {
      copy[e.key] = e.value.map((row) => List<String>.from(row)).toList();
    }
    final snap = _SheetSnapshot(
      copy,
      List<String>.from(_sheetNames),
      _activeSheet,
      _selRow,
      _selCol,
    );
    // 表 / 図も控える (= ユーザー要望: Ctrl+Z で作った表を取り消せるように)。
    snap.tables = {
      for (final e in _sheetTables.entries)
        e.key: [for (final t in e.value) t.copy()],
    };
    snap.images = {
      for (final e in _sheetImages.entries)
        e.key: [for (final i in e.value) i.copy()],
    };
    return snap;
  }

  /// スナップショットから状態を復元 (編集モードは解除)。
  void _restoreSnapshot(_SheetSnapshot s) {
    setState(() {
      _sheets.clear();
      for (final e in s.sheets.entries) {
        _sheets[e.key] = e.value.map((row) => List<String>.from(row)).toList();
      }
      _sheetNames
        ..clear()
        ..addAll(s.sheetNames);
      _activeSheet = s.activeSheet;
      _selRow = s.selRow;
      _selCol = s.selCol;
      _sheetTables
        ..clear()
        ..addAll({
          for (final e in s.tables.entries)
            e.key: [for (final t in e.value) t.copy()],
        });
      _sheetImages
        ..clear()
        ..addAll({
          for (final e in s.images.entries)
            e.key: [for (final i in e.value) i.copy()],
        });
      _editingRow = null;
      _editingCol = null;
      _dirty = true;
      _invalidateFormulaCache();
    });
  }

  /// 編集の **前** に呼ぶ。
  void _pushUndo() {
    _undoStack.add(_captureSnapshot());
    if (_undoStack.length > _maxHistory) _undoStack.removeAt(0);
    _redoStack.clear();
  }

  bool get _canUndo => _undoStack.isNotEmpty;
  bool get _canRedo => _redoStack.isNotEmpty;

  void _undo() {
    if (_undoStack.isEmpty) return;
    _commitEdit();
    final cur = _captureSnapshot();
    final prev = _undoStack.removeLast();
    _redoStack.add(cur);
    if (_redoStack.length > _maxHistory) _redoStack.removeAt(0);
    _restoreSnapshot(prev);
  }

  void _redo() {
    if (_redoStack.isEmpty) return;
    _commitEdit();
    final cur = _captureSnapshot();
    final next = _redoStack.removeLast();
    _undoStack.add(cur);
    if (_undoStack.length > _maxHistory) _undoStack.removeAt(0);
    _restoreSnapshot(next);
  }

  // 選択中セル
  int _selRow = 0;
  int _selCol = 0;

  @override
  void initState() {
    super.initState();
    _detectKind();
    _loadFile();
  }

  @override
  void dispose() {
    _sheetToastTimer?.cancel();
    _editCtrl.dispose();
    _editFocus.dispose();
    _keyFocus.dispose();
    _formulaCtrl.dispose();
    _formulaFocus.dispose();
    _stopDragAutoScroll();
    _vScroll.dispose();
    _hScroll.dispose();
    super.dispose();
  }

  // ── 数式バー (= ユーザー要望: Excel と同じく上部にセル内容/数式) ──
  final TextEditingController _formulaCtrl = TextEditingController();
  final FocusNode _formulaFocus = FocusNode();

  // ── 範囲選択 (= ユーザー要望: セルの範囲を選んで図や表にできるように) ──
  /// シートごとの表 (= ユーザー要望: 図や表の挿入)。 キーはシート名。
  final Map<String, List<_SsTable>> _sheetTables = {};

  /// シートごとの図 (= ユーザー要望: 図や表の挿入)。 キーはシート名。
  final Map<String, List<_SsImage>> _sheetImages = {};

  List<_SsTable> get _tables => _sheetTables[_activeSheet] ??= [];
  List<_SsImage> get _images => _sheetImages[_activeSheet] ??= [];

  /// [r],[c] を含む表 (無ければ null)。 セルの色付けに使う。
  _SsTable? _tableAt(int r, int c) {
    for (final t in _tables) {
      if (t.contains(r, c)) return t;
    }
    return null;
  }

  /// 表のセル背景色 (見出し行 / 縞)。 表の外なら null。
  int? _tableFillAt(int r, int c) {
    final t = _tableAt(r, c);
    if (t == null) return null;
    final rel = r - t.row;
    if (rel == 0) return t.headerFill;
    if (t.bandFill != null && rel % 2 == 0) return t.bandFill;
    return null;
  }

  /// マウスのボタンを押したままセルをなぞっている最中か
  /// (= ユーザー要望: ドラッグで範囲選択)。 Listener + MouseRegion で
  /// 見ているので、 指でのスクロールは今までどおり効く。
  bool _dragSelecting = false;

  /// ドラッグ開始セル (= 範囲の起点)。
  int? _dragAnchorRow;
  int? _dragAnchorCol;

  /// 端をなぞっている間、 表を少しずつ送るためのタイマー
  /// (= ユーザー要望: 画面外に出ようとしたら画面が追いかける)。
  Timer? _dragAutoScrollTimer;

  /// 送る向き (px / 1 回)。
  double _dragScrollDx = 0;
  double _dragScrollDy = 0;

  /// 指 / マウスの位置から、 端に近ければ表を送り続ける。
  void _updateDragAutoScroll(Offset globalPos) {
    final box = context.findRenderObject() as RenderBox?;
    if (box == null || !box.hasSize) return;
    final local = box.globalToLocal(globalPos);
    final size = box.size;
    // 端から 60px を「送る帯」 とする。 近いほど速く送る。
    const edge = 60.0;
    const maxStep = 26.0;
    double calc(double v, double len) {
      if (v < edge) return -maxStep * ((edge - v) / edge).clamp(0.0, 1.0);
      if (v > len - edge) {
        return maxStep * ((v - (len - edge)) / edge).clamp(0.0, 1.0);
      }
      return 0.0;
    }

    _dragScrollDx = calc(local.dx, size.width);
    _dragScrollDy = calc(local.dy, size.height);
    if (_dragScrollDx == 0 && _dragScrollDy == 0) {
      _stopDragAutoScroll();
      return;
    }
    _dragAutoScrollTimer ??=
        Timer.periodic(const Duration(milliseconds: 16), (_) {
      if (!_dragSelecting || !mounted) {
        _stopDragAutoScroll();
        return;
      }
      if (_dragScrollDx != 0 && _hScroll.hasClients) {
        _hScroll.jumpTo((_hScroll.offset + _dragScrollDx)
            .clamp(0.0, _hScroll.position.maxScrollExtent));
      }
      if (_dragScrollDy != 0 && _vScroll.hasClients) {
        _vScroll.jumpTo((_vScroll.offset + _dragScrollDy)
            .clamp(0.0, _vScroll.position.maxScrollExtent));
      }
    });
  }

  void _stopDragAutoScroll() {
    _dragAutoScrollTimer?.cancel();
    _dragAutoScrollTimer = null;
    _dragScrollDx = 0;
    _dragScrollDy = 0;
  }

  // 選択の起点。 null なら 1 セルだけの選択 (_selRow/_selCol)。
  int? _rangeAnchorRow;
  int? _rangeAnchorCol;

  /// 選択範囲 (行/列の開始・終了。 いずれも含む)。
  ({int r1, int c1, int r2, int c2}) get _range {
    final ar = _rangeAnchorRow ?? _selRow;
    final ac = _rangeAnchorCol ?? _selCol;
    return (
      r1: math.min(ar, _selRow),
      c1: math.min(ac, _selCol),
      r2: math.max(ar, _selRow),
      c2: math.max(ac, _selCol),
    );
  }

  bool get _hasRange {
    final r = _range;
    return r.r1 != r.r2 || r.c1 != r.c2;
  }

  bool _inRange(int r, int c) {
    final s = _range;
    return r >= s.r1 && r <= s.r2 && c >= s.c1 && c <= s.c2;
  }

  /// 選択範囲の中身を行 × 列で取り出す (数式は計算結果を使う)。
  List<List<String>> _rangeCells() {
    final s = _range;
    final out = <List<String>>[];
    for (var r = s.r1; r <= s.r2 && r < _rowCount; r++) {
      final row = <String>[];
      for (var c = s.c1; c <= s.c2 && c < _colCount; c++) {
        row.add(_displayValue(r, c));
      }
      out.add(row);
    }
    return out;
  }

  /// 選択の起点を今のセルに置き直す (ふつうのクリック)。
  void _resetRangeAnchor() {
    _rangeAnchorRow = null;
    _rangeAnchorCol = null;
  }

  /// Shift 併用でクリック / 矢印した時に、 起点を覚えて範囲を伸ばす。
  void _ensureRangeAnchor() {
    _rangeAnchorRow ??= _selRow;
    _rangeAnchorCol ??= _selCol;
  }

  // ── 画面内のお知らせ ──
  // ★ この画面は全画面のダイアログなので、 SnackBar を出すと後ろに隠れて
  //   「押しても何も起きない」 ように見える。 画面の中に自分で出す。
  String? _sheetToastMsg;
  Color _sheetToastColor = const Color(0xFF43B97F);
  Timer? _sheetToastTimer;

  void _sheetToast(String msg, {bool error = false}) {
    _sheetToastTimer?.cancel();
    setState(() {
      _sheetToastMsg = msg;
      _sheetToastColor =
          error ? const Color(0xFFE57373) : const Color(0xFF43B97F);
    });
    _sheetToastTimer = Timer(const Duration(seconds: 4), () {
      if (mounted) setState(() => _sheetToastMsg = null);
    });
  }

  /// 選択範囲を表ノードにしてマップへ置く。
  /// 選択範囲を「表」 にする。
  ///
  /// まずシートの上で表として飾る (= ユーザー要望: 作った表はまず xlsx の
  /// 編集画面に置く)。 マップへ出したい時は、 表の中にカーソルを置いた時に
  /// 出るボタン (もしくは表を押して出るメニュー) から。
  void _rangeToTable() {
    final provider = context.read<MindMapProvider>();
    if (!_hasRange) return;
    final sel = _range;
    final rows = sel.r2 - sel.r1 + 1;
    final cols = sel.c2 - sel.c1 + 1;
    if (rows < 1 || cols < 1) return;
    _pushUndo();
    // 「表を挿入」 と同じ色の組を使う。
    final th = _kSsTableThemes[
        _ssTableTheme.clamp(0, _kSsTableThemes.length - 1)];
    setState(() {
      // 同じ場所にある古い飾りは置き換える。
      _tables.removeWhere((t) => t.row == sel.r1 && t.col == sel.c1);
      _tables.add(_SsTable(
        row: sel.r1,
        col: sel.c1,
        rows: rows,
        cols: cols,
        headerFill: th.head,
        headerFont: th.headFont,
        bandFill: th.band,
        line: th.line,
      ));
      _dirty = true;
    });
    _sheetToast(provider.t('sheet.rangeToTableDone'));
  }

  // ── グラフの設定 (= ユーザー要望: 軸の最大/最小・目盛りの間隔・凡例) ──
  String _chartTitle = '';
  String _chartYMin = '';
  String _chartYMax = '';
  String _chartYStep = '';
  bool _chartLegend = true;

  /// よこの軸に出す項目の範囲 (1 始まり。 空なら全部)。
  String _chartXFrom = '';
  String _chartXTo = '';

  /// グラフの細かい設定を聞くダイアログ。 OK なら true。
  Future<bool> _showChartSettings({String focus = 'all'}) async {
    final titleCtrl = TextEditingController(
        text: _chartTitle.isEmpty
            ? _currentFileName.replaceAll(RegExp(r'\.[^.]+$'), '')
            : _chartTitle);
    final minCtrl = TextEditingController(text: _chartYMin);
    final maxCtrl = TextEditingController(text: _chartYMax);
    final stepCtrl = TextEditingController(text: _chartYStep);
    final xFromCtrl = TextEditingController(text: _chartXFrom);
    final xToCtrl = TextEditingController(text: _chartXTo);
    var legend = _chartLegend;
    Widget numField(String label, TextEditingController c, String hint) =>
        SizedBox(
          width: 120,
          child: TextField(
            controller: c,
            keyboardType: TextInputType.number,
            style: const TextStyle(color: Colors.white, fontSize: 13),
            decoration: InputDecoration(
              isDense: true,
              labelText: label,
              labelStyle:
                  const TextStyle(color: Colors.white54, fontSize: 11),
              hintText: hint,
              hintStyle: const TextStyle(color: Colors.white24, fontSize: 11),
              enabledBorder: const UnderlineInputBorder(
                  borderSide: BorderSide(color: Colors.white24)),
            ),
          ),
        );
    final ok = await showDialog<bool>(
      context: context,
      // 分割セルに埋め込んでいる時は、 そのセルの中に出す
      // (= ユーザー要望: 画面全体の真ん中に出るのは変)。
      useRootNavigator: false,
      builder: (dctx) => StatefulBuilder(
        builder: (dctx, setD) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E2E),
          title: Text(
              focus == 'y'
                  ? 'たての軸の設定'
                  : (focus == 'x'
                      ? 'よこの軸と凡例'
                      : (focus == 'title' ? 'グラフの題名' : 'グラフの設定')),
              style: const TextStyle(color: Colors.white, fontSize: 15)),
          content: SizedBox(
            width: 420,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              TextField(
                controller: titleCtrl,
                style: const TextStyle(color: Colors.white, fontSize: 13),
                decoration: const InputDecoration(
                  isDense: true,
                  labelText: '題名',
                  labelStyle: TextStyle(color: Colors.white54, fontSize: 11),
                  enabledBorder: UnderlineInputBorder(
                      borderSide: BorderSide(color: Colors.white24)),
                ),
              ),
              const SizedBox(height: 14),
              const Align(
                alignment: Alignment.centerLeft,
                child: Text('たての軸の範囲 (空欄なら自動)',
                    style: TextStyle(color: Colors.white38, fontSize: 11)),
              ),
              const SizedBox(height: 4),
              Row(children: [
                numField('最小', minCtrl, '自動'),
                const SizedBox(width: 10),
                numField('最大', maxCtrl, '自動'),
              ]),
              const SizedBox(height: 12),
              const Align(
                alignment: Alignment.centerLeft,
                child: Text('よこの軸の範囲 (何番目の項目から何番目まで)',
                    style: TextStyle(color: Colors.white38, fontSize: 11)),
              ),
              const SizedBox(height: 4),
              Row(children: [
                numField('最初', xFromCtrl, '1'),
                const SizedBox(width: 10),
                numField('最後', xToCtrl, '最後まで'),
              ]),
              const SizedBox(height: 12),
              Row(children: [
                Switch(
                  value: legend,
                  onChanged: (v) => setD(() => legend = v),
                ),
                const SizedBox(width: 4),
                const Text('凡例を出す',
                    style: TextStyle(color: Colors.white70, fontSize: 12.5)),
              ]),
            ]),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx, false),
              child: const Text('やめる',
                  style: TextStyle(color: Colors.white54)),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF7CB342),
                  foregroundColor: Colors.white),
              onPressed: () => Navigator.pop(dctx, true),
              child: const Text('作る'),
            ),
          ],
        ),
      ),
    );
    if (ok == true) {
      _chartTitle = titleCtrl.text.trim();
      _chartYMin = minCtrl.text.trim();
      _chartYMax = maxCtrl.text.trim();
      _chartYStep = stepCtrl.text.trim();
      _chartXFrom = xFromCtrl.text.trim();
      _chartXTo = xToCtrl.text.trim();
      _chartLegend = legend;
    }
    titleCtrl.dispose();
    minCtrl.dispose();
    maxCtrl.dispose();
    stepCtrl.dispose();
    xFromCtrl.dispose();
    xToCtrl.dispose();
    return ok == true;
  }

  /// 選択範囲を棒グラフにして、 まずシートの上に置く (= ユーザー要望)。
  Future<void> _rangeToChart() async {
    final provider = context.read<MindMapProvider>();
    final cells = _rangeCells();
    if (cells.isEmpty) return;
    final srcRange = _range;
    // 作る前に細かい設定を聞く (= ユーザー要望)。
    if (!await _showChartSettings() || !mounted) return;
    var useCells = cells;
    // よこの軸の範囲 (= ユーザー要望: 何番目から何番目まで) を切り出す。
    final xFrom = int.tryParse(_chartXFrom);
    final xTo = int.tryParse(_chartXTo);
    if (xFrom != null || xTo != null) {
      // 1 行目が見出しなら残す。
      final head = useCells.isNotEmpty &&
              useCells.first.skip(1).every((v) =>
                  double.tryParse(v.trim().replaceAll(',', '')) == null)
          ? useCells.first
          : null;
      final body = head == null ? useCells : useCells.sublist(1);
      final a = ((xFrom ?? 1) - 1).clamp(0, body.isEmpty ? 0 : body.length - 1);
      final b = (xTo == null ? body.length : xTo).clamp(a + 1, body.length);
      final picked = body.sublist(a, b);
      useCells = [if (head != null) head, ...picked];
    }

    final path = await provider.renderChartPngFromCells(useCells,
        title: _chartTitle,
        yMin: double.tryParse(_chartYMin),
        yMax: double.tryParse(_chartYMax),
        yStep: double.tryParse(_chartYStep),
        showLegend: _chartLegend);
    if (!mounted) return;
    if (path == null) {
      _sheetToast(provider.t('sheet.rangeNeedsNumbers'), error: true);
      return;
    }
    Uint8List? bytes;
    try {
      bytes = await File(path).readAsBytes();
    } catch (_) {}
    if (bytes == null || !mounted) {
      _sheetToast(provider.t('sheet.rangeFailed'), error: true);
      return;
    }
    _pushUndo();
    setState(() {
      // 選んだ範囲のすぐ右下に置く。
      _images.add(_SsImage(
        bytes: bytes!,
        ext: 'png',
        mediaName: 'hnchart_${DateTime.now().millisecondsSinceEpoch}.png',
        row: _hasRange ? _range.r2 + 1 : _selRow,
        col: _hasRange ? _range.c1 : _selCol,
        width: 360,
        height: 270,
        // 後から題名や軸を変えられるように、 元の範囲と設定を覚える
        // (= ユーザー要望)。
        chart: {
          'r1': srcRange.r1,
          'c1': srcRange.c1,
          'r2': srcRange.r2,
          'c2': srcRange.c2,
          'title': _chartTitle,
          'yMin': _chartYMin,
          'yMax': _chartYMax,
          'yStep': _chartYStep,
          'xFrom': _chartXFrom,
          'xTo': _chartXTo,
          'legend': _chartLegend,
        },
      ));
      _dirty = true;
    });
    _sheetToast('✓ グラフをシートに置きました (左上の ↗ でマップへ出せます)');
  }



  void _invalidateFormulaCache() {
    _formulaEval = null;
  }

  /// 表示用にセル値を取得。 数式 (= で始まる) は評価結果を返す。
  /// 編集モード中のセルや、 表示モードが OFF の時は生の値を返す。
  String _displayValue(int r, int c) {
    if (r < 0 || r >= _rowCount || c < 0 || c >= _colCount) return '';
    final raw = _rows[r][c];
    if (!_showFormulaResults) return raw;
    if (!raw.startsWith('=') || raw.length < 2) return raw;
    // 編集中セルは生の数式を見せたいので別経路 (build 側でガード)
    _formulaEval ??= _FormulaEvaluator(_rows);
    final result = _formulaEval!.evalCell(r, c);
    return _FormulaEvaluator.formatResult(result);
  }

  void _detectKind() {
    final lower = _currentFileName.toLowerCase();
    if (lower.endsWith('.xlsx') || lower.endsWith('.xls')) {
      _kind = _SpreadsheetKind.xlsx;
    } else if (lower.endsWith('.tsv')) {
      _kind = _SpreadsheetKind.tsv;
    } else {
      _kind = _SpreadsheetKind.csv;
    }
  }

  // ─── xlsx の読み取り代替 (= ユーザー報告: 表計算ファイルが開けない) ────
  //
  // excel パッケージ (4.x) は、 他のソフトが作った .xlsx を読むと
  //   「Null check operator used on a null value」 で落ちることがある。
  //   実際に Excel / LibreOffice / openpyxl が作った素朴なファイルでも
  //   落ちるため、 アプリ自身が作った xlsx しか開けない状態だった。
  //
  // そこで、 パッケージが落ちた時は中身 (OOXML) を自前で読む。
  //   xlsx は zip の中に XML が入っているだけなので、 セルの値を拾うには
  //   共有文字列表とシートの XML が読めれば足りる。
  //   ここで読めれば表示・編集はでき、 保存はいつもの経路で行える。

  static String _unescapeXml(String s) {
    if (!s.contains('&')) return s;
    var out = s
        .replaceAll('&lt;', '<')
        .replaceAll('&gt;', '>')
        .replaceAll('&quot;', '"')
        .replaceAll('&apos;', "'");
    out = out.replaceAllMapped(RegExp(r'&#(x?)([0-9A-Fa-f]+);'), (m) {
      final hex = m.group(1) == 'x';
      final code = int.tryParse(m.group(2)!, radix: hex ? 16 : 10);
      return code == null ? m.group(0)! : String.fromCharCode(code);
    });
    return out.replaceAll('&amp;', '&'); // & は最後に戻す
  }

  /// 'BC12' のような参照から 0 始まりの列番号を出す。
  static int _colIndexFromRef(String ref) {
    var col = 0;
    for (final unit in ref.codeUnits) {
      if (unit >= 65 && unit <= 90) {
        col = col * 26 + (unit - 64);
      } else if (unit >= 97 && unit <= 122) {
        col = col * 26 + (unit - 96);
      } else {
        break;
      }
    }
    return col > 0 ? col - 1 : 0;
  }

  /// zip の中の 1 ファイルを文字列で取り出す。
  static String? _zipText(Archive archive, String name) {
    for (final f in archive.files) {
      if (f.isFile && f.name == name) {
        try {
          return utf8.decode(f.content as List<int>, allowMalformed: true);
        } catch (_) {
          return null;
        }
      }
    }
    return null;
  }

  /// excel パッケージが落ちた時用の自前読み取り。
  /// 読めなければ null。
  static Map<String, List<List<String>>>? _parseXlsxFallback(
      List<int> bytes) {
    try {
      final archive = ZipDecoder().decodeBytes(bytes);

      // ① 共有文字列表 (セルの文字はここに集約されている)
      final shared = <String>[];
      final ssXml = _zipText(archive, 'xl/sharedStrings.xml');
      if (ssXml != null) {
        for (final si
            in RegExp(r'<si\b[^>]*>(.*?)</si>', dotAll: true).allMatches(ssXml)) {
          final buf = StringBuffer();
          for (final t in RegExp(r'<t\b[^>]*>(.*?)</t>', dotAll: true)
              .allMatches(si.group(1) ?? '')) {
            buf.write(_unescapeXml(t.group(1) ?? ''));
          }
          shared.add(buf.toString());
        }
      }

      // ② シート名と、 実体 XML の場所の対応
      final relTarget = <String, String>{};
      final relsXml = _zipText(archive, 'xl/_rels/workbook.xml.rels');
      if (relsXml != null) {
        for (final r in RegExp(r'<Relationship\b[^>]*>').allMatches(relsXml)) {
          final tag = r.group(0)!;
          final id = RegExp(r'Id="([^"]+)"').firstMatch(tag)?.group(1);
          final target = RegExp(r'Target="([^"]+)"').firstMatch(tag)?.group(1);
          if (id != null && target != null) {
            relTarget[id] = target.startsWith('/')
                ? target.substring(1)
                : (target.startsWith('xl/') ? target : 'xl/$target');
          }
        }
      }

      final sheetOrder = <String, String>{}; // シート名 → XML のパス
      final wbXml = _zipText(archive, 'xl/workbook.xml');
      if (wbXml != null) {
        var i = 0;
        for (final m in RegExp(r'<sheet\b[^>]*/?>').allMatches(wbXml)) {
          final tag = m.group(0)!;
          final name = _unescapeXml(
              RegExp(r'name="([^"]*)"').firstMatch(tag)?.group(1) ?? '');
          final rid = RegExp(r'r:id="([^"]+)"').firstMatch(tag)?.group(1);
          i++;
          final path = (rid != null ? relTarget[rid] : null) ??
              'xl/worksheets/sheet$i.xml';
          if (name.isNotEmpty) sheetOrder[name] = path;
        }
      }
      if (sheetOrder.isEmpty) {
        sheetOrder['Sheet1'] = 'xl/worksheets/sheet1.xml';
      }

      // ③ 各シートのセルを拾う
      final out = <String, List<List<String>>>{};
      for (final entry in sheetOrder.entries) {
        final xml = _zipText(archive, entry.value);
        final rows = <List<String>>[];
        if (xml != null) {
          for (final rowM in RegExp(r'<row\b[^>]*>(.*?)</row>', dotAll: true)
              .allMatches(xml)) {
            final rowTag = xml.substring(rowM.start,
                xml.indexOf('>', rowM.start) + 1);
            final rIdx = int.tryParse(
                    RegExp(r'\br="(\d+)"').firstMatch(rowTag)?.group(1) ?? '');
            final cells = <int, String>{};
            for (final cM in RegExp(
                    r'<c\b([^>]*)(?:/>|>(.*?)</c>)', dotAll: true)
                .allMatches(rowM.group(1) ?? '')) {
              final attrs = cM.group(1) ?? '';
              final body = cM.group(2) ?? '';
              final ref = RegExp(r'r="([A-Za-z]+)').firstMatch(attrs)?.group(1);
              final type = RegExp(r't="([^"]+)"').firstMatch(attrs)?.group(1);
              final col = ref != null
                  ? _colIndexFromRef(ref)
                  : (cells.isEmpty ? 0 : cells.keys.reduce(math.max) + 1);
              String text = '';
              if (type == 'inlineStr') {
                final buf = StringBuffer();
                for (final t in RegExp(r'<t\b[^>]*>(.*?)</t>', dotAll: true)
                    .allMatches(body)) {
                  buf.write(_unescapeXml(t.group(1) ?? ''));
                }
                text = buf.toString();
              } else {
                final v = RegExp(r'<v\b[^>]*>(.*?)</v>', dotAll: true)
                    .firstMatch(body)
                    ?.group(1);
                // 計算結果を保存していない数式セルは、 空にせず式そのものを
                //   見せる (他のソフトは結果を書かずに保存することがある)。
                // <v></v> と空で書かれることもあるので中身で判断する。
                if (v == null || v.trim().isEmpty) {
                  final f = RegExp(r'<f\b[^>]*>(.*?)</f>', dotAll: true)
                      .firstMatch(body)
                      ?.group(1);
                  if (f != null && f.trim().isNotEmpty) {
                    cells[col] = '=${_unescapeXml(f)}';
                    continue;
                  }
                }
                if (v != null) {
                  if (type == 's') {
                    final idx = int.tryParse(v.trim());
                    text = (idx != null && idx >= 0 && idx < shared.length)
                        ? shared[idx]
                        : '';
                  } else if (type == 'b') {
                    text = v.trim() == '1' ? 'TRUE' : 'FALSE';
                  } else {
                    text = _unescapeXml(v);
                    // 1.0 のような整数は素直に見せる
                    final d = double.tryParse(text);
                    if (d != null && d == d.roundToDouble() &&
                        d.abs() < 1e15 && !text.contains('E') &&
                        !text.contains('e')) {
                      text = d.toInt().toString();
                    }
                  }
                }
              }
              cells[col] = text;
            }
            // 行番号どおりの位置に置く (空行も保つ)
            final targetIndex = (rIdx != null && rIdx > 0) ? rIdx - 1 : rows.length;
            while (rows.length <= targetIndex) {
              rows.add(<String>[]);
            }
            final maxCol = cells.isEmpty ? -1 : cells.keys.reduce(math.max);
            // growable: true を忘れると、 後段の桁揃えで add できずに落ちる。
            final line = List<String>.filled(maxCol + 1, '', growable: true);
            cells.forEach((c, t) => line[c] = t);
            rows[targetIndex] = line;
          }
        }
        if (rows.isEmpty) rows.add(['']);
        final maxCols = rows.fold<int>(0, (m, r) => r.length > m ? r.length : m);
        for (final r in rows) {
          while (r.length < maxCols) {
            r.add('');
          }
        }
        out[entry.key] = rows;
      }
      return out.isEmpty ? null : out;
    } catch (e) {
      debugPrint('xlsx 代替読み取りも失敗: $e');
      return null;
    }
  }

  /// 保存時に入れておいたアプリ用の控え (xl/hnMeta.json) から、 表と図を
  /// 復元する (= ユーザー要望: 図や表を excel ファイル上に置いたままに)。
  /// 図の中身は xl/media から読み直す。
  void _restoreSheetExtras(Uint8List bytes) {
    try {
      final archive = ZipDecoder().decodeBytes(bytes);
      List<int>? find(String name) {
        for (final f in archive.files) {
          if (f.name == name && f.isFile) return f.content as List<int>;
        }
        return null;
      }

      final raw = find('xl/hnMeta.json');
      if (raw == null) return;
      final meta = jsonDecode(utf8.decode(raw, allowMalformed: true));
      if (meta is! Map) return;
      _sheetTables.clear();
      _sheetImages.clear();
      final tables = meta['tables'];
      if (tables is Map) {
        tables.forEach((k, v) {
          if (v is! List) return;
          final list = <_SsTable>[];
          for (final e in v) {
            if (e is Map) {
              final t = _SsTable.fromJson(e);
              if (t != null) list.add(t);
            }
          }
          if (list.isNotEmpty) _sheetTables['$k'] = list;
        });
      }
      final images = meta['images'];
      if (images is Map) {
        images.forEach((k, v) {
          if (v is! List) return;
          final list = <_SsImage>[];
          for (final e in v) {
            if (e is! Map) continue;
            final media = '${e['media'] ?? ''}';
            if (media.isEmpty) continue;
            final data = find('xl/media/$media');
            if (data == null) continue;
            list.add(_SsImage(
              bytes: Uint8List.fromList(data),
              ext: '${e['ext'] ?? 'png'}',
              mediaName: media,
              row: (e['r'] as num?)?.toInt() ?? 0,
              col: (e['c'] as num?)?.toInt() ?? 0,
              width: (e['w'] as num?)?.toDouble() ?? 240,
              height: (e['h'] as num?)?.toDouble() ?? 180,
              dx: (e['dx'] as num?)?.toDouble() ?? 0,
              dy: (e['dy'] as num?)?.toDouble() ?? 0,
              chart: e['chart'] is Map
                  ? Map<String, dynamic>.from(e['chart'] as Map)
                  : null,
            ));
          }
          if (list.isNotEmpty) _sheetImages['$k'] = list;
        });
      }
    } catch (e) {
      debugPrint('xlsx の表 / 図の復元に失敗: $e');
    }
  }

  Future<void> _loadFile() async {
    try {
      final bytes = await File(_currentFilePath).readAsBytes();
      if (_kind == _SpreadsheetKind.xlsx) {
        // 前回置いた表 / 図を戻す (= ユーザー要望)。
        _restoreSheetExtras(bytes);
        xls.Excel? excel;
        try {
          excel = xls.Excel.decodeBytes(bytes);
        } catch (e) {
          // パッケージが読めないファイルは自前で読む (下の代替へ)。
          debugPrint('excel パッケージでの読み込みに失敗、 代替へ: $e');
        }
        if (excel == null) {
          final parsed = _parseXlsxFallback(bytes);
          if (parsed == null) {
            throw Exception('この xlsx は読み取れませんでした');
          }
          _excel = null;
          _sheetNames = parsed.keys.toList();
          for (final e in parsed.entries) {
            _padSheetForDisplay(e.value);
            _sheets[e.key] = e.value;
          }
          _activeSheet = _sheetNames.first;
          if (!mounted) return;
          setState(() => _loading = false);
          return;
        }
        _excel = excel;
        _sheetNames = excel.tables.keys.toList();
        if (_sheetNames.isEmpty) {
          excel['Sheet1'];
          _sheetNames = ['Sheet1'];
        }
        for (final name in _sheetNames) {
          final table = excel.tables[name];
          final rows = <List<String>>[];
          if (table != null) {
            for (final row in table.rows) {
              rows.add(row.map((c) {
                if (c == null) return '';
                final v = c.value;
                if (v == null) return '';
                // 日付フォーマットが適用されたセルなら、 シリアル値を日付文字列に変換
                final fmt = _tryGetCellNumFormat(c);
                if (fmt != null && _isDateNumFormat(fmt)) {
                  final serial = _cellValueToSerial(v);
                  if (serial != null) {
                    // 数値型 (IntCellValue/DoubleCellValue) で値が小さい場合は
                    // 日付として扱わない。 ユーザーが入力した 1, 2, 3 等の
                    // 数値が、 列の数値書式継承で 1899/12/31 等の日付に化ける
                    // のを防ぐ。 367 = 1年分強の閾値 (Excel シリアル値の
                    // 1900/1/1 = 1, 1901/1/1 = 367)。
                    final isPureNumeric =
                        v is xls.IntCellValue || v is xls.DoubleCellValue;
                    if (isPureNumeric && serial < 367) {
                      return _xlsxValueToString(v);
                    }
                    return _excelSerialToDateString(serial, fmt);
                  }
                }
                return _xlsxValueToString(v);
              }).toList());
            }
          }
          if (rows.isEmpty) rows.add(['']);
          final maxCols =
              rows.fold<int>(0, (m, r) => r.length > m ? r.length : m);
          for (final r in rows) {
            while (r.length < maxCols) {
              r.add('');
            }
          }
          // ── 余白セルの追加 ──
          // ユーザーが小さいシート (3行 5列 等) を読み込んだ時、 編集
          // 可能領域がすぐ尽きるのを防ぐため、 表示用に空セルを追加して
          // ある程度のスペースを確保する。 保存時は _findDataBounds で
          // 実データ範囲のみ書き戻すので、 ファイル自体は膨らまない。
          _padSheetForDisplay(rows);
          _sheets[name] = rows;
        }
        _activeSheet = _sheetNames.first;
      } else {
        String text;
        try {
          text = await File(_currentFilePath).readAsString();
        } catch (_) {
          text = String.fromCharCodes(bytes);
        }
        if (text.startsWith('\uFEFF')) text = text.substring(1);
        text = text.replaceAll('\r\n', '\n').replaceAll('\r', '\n');
        final delim = _kind == _SpreadsheetKind.tsv ? '\t' : ',';
        final list = CsvToListConverter(
          fieldDelimiter: delim,
          eol: '\n',
          shouldParseNumbers: false,
        ).convert(text);
        final rows = list
            .map((row) => row.map((c) => c?.toString() ?? '').toList())
            .toList();
        if (rows.isEmpty) rows.add(['']);
        final maxCols =
            rows.fold<int>(0, (m, r) => r.length > m ? r.length : m);
        for (final r in rows) {
          while (r.length < maxCols) {
            r.add('');
          }
        }
        // CSV/TSV も同様に余白セルを追加
        _padSheetForDisplay(rows);
        _sheetNames = ['CSV'];
        _activeSheet = 'CSV';
        _sheets['CSV'] = rows;
      }
      if (mounted) setState(() => _loading = false);
    } catch (e, st) {
      debugPrint('SpreadsheetEditor load error: $e\n$st');
      if (mounted) {
        setState(() {
          _loading = false;
          _loadError = '$e';
        });
      }
    }
  }

  /// XLSX セルの numberFormat 文字列を取得。 excel パッケージのバージョン差を
  /// 吸収するため dynamic で複数のアクセスパターンを試す。 取れなければ null。
  String? _tryGetCellNumFormat(dynamic cell) {
    try {
      final style = cell.cellStyle;
      if (style == null) return null;
      // excel 4.x: cellStyle.numberFormat (NumFormat 型)
      try {
        final f = style.numberFormat;
        if (f != null) {
          // NumFormat.toString() で表示用の format string が返ってくる実装が多い
          final s = f.toString();
          if (s.isNotEmpty && s != 'null') return s;
        }
      } catch (_) {}
      // 古い版: numFmt
      try {
        final f = style.numFmt;
        if (f != null) return f.toString();
      } catch (_) {}
      // formatCode を直接持つ版
      try {
        final f = style.formatCode;
        if (f is String && f.isNotEmpty) return f;
      } catch (_) {}
    } catch (_) {}
    return null;
  }

  /// numberFormat 文字列が日付/時刻フォーマットかを判定。
  /// Excel の典型的な日付フォーマット (yyyy/m/d, mm-dd, d-mmm-yy, h:mm,
  /// yyyy年m月d日 など) を網羅的に検知する。
  bool _isDateNumFormat(String fmt) {
    // " で囲まれたリテラル文字列を除去
    final stripped = fmt.replaceAll(RegExp(r'"[^"]*"'), '');
    // [$-411] のような ロケール指定を除去
    final cleaned = stripped.replaceAll(RegExp(r'\[\$-[^\]]*\]'), '');
    final lower = cleaned.toLowerCase();
    // 'General' や数値専用フォーマットは日付ではない
    if (lower.trim() == 'general' || lower.trim() == '@') return false;
    // 日付/時刻系の文字が含まれていれば日付扱い
    final hasDate = RegExp(r'[ymd]').hasMatch(lower) ||
        fmt.contains('年') ||
        fmt.contains('月') ||
        fmt.contains('日');
    final hasTime = lower.contains('h') ||
        lower.contains('s') ||
        lower.contains('am/pm') ||
        lower.contains('a/p');
    return hasDate || hasTime;
  }

  /// CellValue (Int / Double / DateCellValue 等) から Excel シリアル値を取り出す。
  num? _cellValueToSerial(xls.CellValue v) {
    if (v is xls.IntCellValue) return v.value;
    if (v is xls.DoubleCellValue) return v.value;
    // DateCellValue が来た場合は内部の日付情報からシリアル値を逆算
    if (v is xls.DateCellValue) {
      final d = DateTime(v.year, v.month, v.day);
      final base = DateTime(1899, 12, 30);
      return d.difference(base).inDays;
    }
    if (v is xls.DateTimeCellValue) {
      final d = DateTime(v.year, v.month, v.day, v.hour, v.minute, v.second);
      final base = DateTime(1899, 12, 30);
      final diff = d.difference(base);
      return diff.inMicroseconds / Duration.microsecondsPerDay;
    }
    return null;
  }

  /// Excel のシリアル値を日付文字列に変換。
  /// Excel エポックは 1900/1/1 = serial 1 だが、 1900 年を閏年扱いするバグの
  /// 補正のため、 day 0 を 1899/12/30 として計算する。
  /// [fmt] の内容から年月日のみ / 時刻含み / 日本語形式 等を切り替える。
  String _excelSerialToDateString(num serial, String fmt) {
    final intPart = serial.floor();
    final fracPart = (serial - intPart).abs();
    final base = DateTime(1899, 12, 30);
    final date = base.add(Duration(days: intPart));
    final totalSec = (fracPart * 86400).round();
    final hour = totalSec ~/ 3600;
    final minute = (totalSec % 3600) ~/ 60;
    final second = totalSec % 60;

    String p2(int n) => n.toString().padLeft(2, '0');

    final lower = fmt.toLowerCase();
    final hasTime = lower.contains('h') ||
        lower.contains('s') ||
        lower.contains('am/pm') ||
        lower.contains('a/p');
    final hasDate = RegExp(r'[ymd]').hasMatch(lower) ||
        fmt.contains('年') ||
        fmt.contains('月') ||
        fmt.contains('日');

    // セルの実際の時刻が 00:00:00 = 「ユーザーが時刻部分を入力していない」
    // ので、 numFormat に時刻指定があっても表示しない。 (= 5/20 のような
    // 純粋な日付を「5月20日 00:00」 で表示するのを防ぐ)
    final hasActualTime = hour != 0 || minute != 0 || second != 0;
    final showTime = hasTime && hasActualTime;

    // 日本語形式 (yyyy年m月d日 / m月d日 / 月日のみ など) を優先判定
    final isJapanese =
        fmt.contains('年') || fmt.contains('月') || fmt.contains('日');
    if (isJapanese && hasDate) {
      final buf = StringBuffer();
      if (fmt.contains('年')) buf.write('${date.year}年');
      if (fmt.contains('月')) buf.write('${date.month}月');
      if (fmt.contains('日')) buf.write('${date.day}日');
      if (showTime) {
        buf.write(' ${p2(hour)}:${p2(minute)}');
        if (lower.contains('s')) buf.write(':${p2(second)}');
      }
      return buf.toString();
    }

    // 時刻のみ (= numFormat が時刻フォーマットでも、 実際 00:00:00 なら
    // 空文字を返さず、 00:00 を出すのは仕様通り)
    if (hasTime && !hasDate) {
      if (lower.contains('s')) {
        return '${p2(hour)}:${p2(minute)}:${p2(second)}';
      }
      return '${p2(hour)}:${p2(minute)}';
    }

    // 日付 + 時刻 (実時刻が 00:00:00 なら時刻を省略)
    if (hasDate && hasTime) {
      if (showTime) {
        return '${date.year}/${date.month}/${date.day} '
            '${p2(hour)}:${p2(minute)}'
            '${lower.contains('s') ? ':${p2(second)}' : ''}';
      }
      return '${date.year}/${date.month}/${date.day}';
    }

    // デフォルト日付: yyyy/m/d
    return '${date.year}/${date.month}/${date.day}';
  }

  String _xlsxValueToString(xls.CellValue v) {
    if (v is xls.TextCellValue) {
      // excel 4.x: TextCellValue.value は excel パッケージ独自の TextSpan 型
      // (Flutter painting の InlineSpan/TextSpan とは別物)。
      // 構造的には .text と .children を持つので、 dynamic で受けて
      // 再帰的に走査し文字列を結合する。
      final buf = StringBuffer();
      void walk(dynamic span) {
        if (span == null) return;
        try {
          final t = span.text;
          if (t is String) buf.write(t);
        } catch (_) {}
        try {
          final children = span.children;
          if (children is Iterable) {
            for (final c in children) {
              walk(c);
            }
          }
        } catch (_) {}
      }

      walk(v.value);
      final result = buf.toString();
      return result.isEmpty ? v.value.toString() : result;
    }
    if (v is xls.IntCellValue) return v.value.toString();
    if (v is xls.DoubleCellValue) {
      final d = v.value;
      if (d == d.truncateToDouble()) return d.toInt().toString();
      return d.toString();
    }
    if (v is xls.BoolCellValue) return v.value ? 'TRUE' : 'FALSE';
    if (v is xls.DateCellValue) {
      return '${v.year.toString().padLeft(4, '0')}-'
          '${v.month.toString().padLeft(2, '0')}-'
          '${v.day.toString().padLeft(2, '0')}';
    }
    if (v is xls.TimeCellValue) {
      return '${v.hour.toString().padLeft(2, '0')}:'
          '${v.minute.toString().padLeft(2, '0')}:'
          '${v.second.toString().padLeft(2, '0')}';
    }
    if (v is xls.DateTimeCellValue) {
      return '${v.year.toString().padLeft(4, '0')}-'
          '${v.month.toString().padLeft(2, '0')}-'
          '${v.day.toString().padLeft(2, '0')} '
          '${v.hour.toString().padLeft(2, '0')}:'
          '${v.minute.toString().padLeft(2, '0')}:'
          '${v.second.toString().padLeft(2, '0')}';
    }
    if (v is xls.FormulaCellValue) return '=${v.formula}';
    return v.toString();
  }

  /// ファイル名変更ダイアログを表示。 OK ならファイルをリネームし、
  /// onRenamed コールバックで呼び出し側に伝える。
  /// 拡張子は元と同じものに固定する (途中で変えるとエディタ種別が変わるため)。
  Future<void> _showRenameDialog() async {
    final ctrl = TextEditingController(text: _currentFileName);
    final newName = await showDialog<String>(
      context: context,
      builder: (dctx) {
        return AlertDialog(
          backgroundColor:
              widget.isDarkMode ? const Color(0xFF22222E) : Colors.white,
          title: Row(
            children: [
              const Icon(Icons.drive_file_rename_outline_rounded,
                  color: Color(0xFF6C63FF)),
              const SizedBox(width: 8),
              Text(context.read<MindMapProvider>().t('doc.renameFile')),
            ],
          ),
          content: SizedBox(
            width: 380,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  '新しいファイル名を入力してください。\n'
                  '拡張子は元のまま (.${_currentFileName.split('.').last}) になります。',
                  style: TextStyle(
                    fontSize: 12,
                    color: widget.isDarkMode ? Colors.white60 : Colors.black54,
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: ctrl,
                  autofocus: true,
                  decoration: InputDecoration(
                    hintText:
                        context.read<MindMapProvider>().t('doc.fileNameHint'),
                    border: OutlineInputBorder(),
                  ),
                  onSubmitted: (_) => Navigator.of(dctx).pop(ctrl.text),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
              child: Text(context.read<MindMapProvider>().t('btn.cancel')),
            ),
            FilledButton(
              onPressed: () => Navigator.of(dctx).pop(ctrl.text),
              child: Text(context.read<MindMapProvider>().t('btn.change')),
            ),
          ],
        );
      },
    );
    if (newName == null) return;
    await _performRename(newName.trim());
  }

  Future<void> _performRename(String input) async {
    if (input.isEmpty || input == _currentFileName) return;
    // パス区切り文字は禁止
    if (input.contains('/') || input.contains('\\')) {
      _showSnack('ファイル名にパス区切り文字 ( / \\ ) は使えません');
      return;
    }
    // 元の拡張子を保持
    final origExt = _currentFileName.contains('.')
        ? _currentFileName.substring(_currentFileName.lastIndexOf('.'))
        : '';
    String newName = input;
    if (origExt.isNotEmpty &&
        !newName.toLowerCase().endsWith(origExt.toLowerCase())) {
      // 拡張子を補完
      if (newName.contains('.')) {
        newName = '${newName.substring(0, newName.lastIndexOf('.'))}$origExt';
      } else {
        newName = '$newName$origExt';
      }
    }
    try {
      final oldFile = File(_currentFilePath);
      if (!await oldFile.exists()) {
        _showSnack('元ファイルが見つかりません');
        return;
      }
      // 同じディレクトリ内の新パスを構築
      final sep = _currentFilePath.contains('\\') ? '\\' : '/';
      final dirEnd = _currentFilePath.lastIndexOf(sep);
      final dir = dirEnd >= 0 ? _currentFilePath.substring(0, dirEnd) : '';
      final newPath = dir.isEmpty ? newName : '$dir$sep$newName';
      // 同名ファイルが既にあれば拒否
      if (await File(newPath).exists() && newPath != _currentFilePath) {
        _showSnack('同名のファイルが既に存在します');
        return;
      }
      // 未保存変更があれば先に保存
      if (_dirty) {
        await _save();
      }
      final renamed = await oldFile.rename(newPath);
      setState(() {
        _currentFilePath = renamed.path;
        _currentFileName = newName;
      });
      widget.onRenamed?.call(renamed.path, newName);
      _showSnack('ファイル名を変更しました: $newName');
    } catch (e) {
      _showSnack('ファイル名変更に失敗: $e');
    }
  }

  void _showSnack(String msg) {
    if (!mounted) return;
    ScaffoldMessenger.maybeOf(context)?.showSnackBar(SnackBar(
      content: Text(msg),
      duration: const Duration(seconds: 3),
    ));
  }

  // ── 余白セル設定 ──
  // ロード時に追加する空セルの最小数。 ユーザーが小さいシート (1行 1列 等)
  // を読み込んだ時、 すぐに編集領域が尽きないようにする。
  static const int _kMinPaddedRows = 30;
  static const int _kMinPaddedCols = 15;
  // 既存データの末尾に追加する余白分。 元データが大きいシート (例: 500行)
  // でも、 末尾に追加で書ける空セルを少しだけ確保する。
  static const int _kExtraRowsPadding = 10;
  static const int _kExtraColsPadding = 5;

  /// 表示用に空セルでパディング。 引数の `rows` を in-place で変更する。
  /// 既存の最大列数 + 余白を計算して、 全ての行を同じ列数に揃え、
  /// 不足分の空行を末尾に追加する。
  void _padSheetForDisplay(List<List<String>> rows) {
    final currentMaxCols =
        rows.fold<int>(0, (m, r) => r.length > m ? r.length : m);
    final targetCols =
        math.max(currentMaxCols + _kExtraColsPadding, _kMinPaddedCols);
    for (final r in rows) {
      while (r.length < targetCols) {
        r.add('');
      }
    }
    final targetRows =
        math.max(rows.length + _kExtraRowsPadding, _kMinPaddedRows);
    while (rows.length < targetRows) {
      rows.add(List<String>.filled(targetCols, ''));
    }
  }

  /// `rows` から「実際にデータが入っている範囲」 の (rowCount, colCount) を
  /// 返す。 末尾の空行 / 空列は除外。 保存時はこの範囲だけを書き出す。
  (int, int) _findDataBounds(List<List<String>> rows) {
    int lastDataRow = -1;
    int lastDataCol = -1;
    for (int r = 0; r < rows.length; r++) {
      for (int c = 0; c < rows[r].length; c++) {
        if (rows[r][c].isNotEmpty) {
          if (r > lastDataRow) lastDataRow = r;
          if (c > lastDataCol) lastDataCol = c;
        }
      }
    }
    // 全て空の場合でも最低 1行 1列は確保 (= 完全に空のファイルでもエラーに
    // ならないように)
    final rowCount = lastDataRow + 1 > 0 ? lastDataRow + 1 : 1;
    final colCount = lastDataCol + 1 > 0 ? lastDataCol + 1 : 1;
    return (rowCount, colCount);
  }

  /// 挿入した表の見た目を excel の CellStyle に変換して当てる。
  /// (見出し行の塗り + 白文字 + 太字 / 縞 / 罫線)。
  void _applyTableStyles(xls.Excel excel) {
    xls.ExcelColor col(int? rgb) => rgb == null
        ? xls.ExcelColor.none
        : xls.ExcelColor.fromHexString(
            'FF${(rgb & 0xFFFFFF).toRadixString(16).padLeft(6, '0').toUpperCase()}');
    for (final name in _sheetNames) {
      final tables = _sheetTables[name];
      if (tables == null || tables.isEmpty) continue;
      final sheet = excel[name];
      for (final t in tables) {
        final border = t.line == null
            ? null
            : xls.Border(
                borderStyle: xls.BorderStyle.Thin, borderColorHex: col(t.line));
        for (int r = t.row; r < t.row + t.rows; r++) {
          final rel = r - t.row;
          final isHeader = rel == 0;
          final banded = t.bandFill != null && rel > 0 && rel % 2 == 0;
          for (int c = t.col; c < t.col + t.cols; c++) {
            sheet
                .cell(xls.CellIndex.indexByColumnRow(
                    columnIndex: c, rowIndex: r))
                .cellStyle = xls.CellStyle(
              backgroundColorHex: isHeader
                  ? col(t.headerFill)
                  : (banded ? col(t.bandFill) : xls.ExcelColor.none),
              fontColorHex:
                  isHeader && t.headerFont != null ? col(t.headerFont) : col(0),
              bold: isHeader,
              leftBorder: border,
              rightBorder: border,
              topBorder: border,
              bottomBorder: border,
            );
          }
        }
      }
    }
  }

  /// 出来上がった xlsx の zip に、 貼った図を drawing として足す。
  /// 図が無ければ元のバイト列をそのまま返す。
  Uint8List _embedImagesIntoXlsx(Uint8List src) {
    final hasImages = _sheetImages.values.any((v) => v.isNotEmpty);
    final hasTables = _sheetTables.values.any((v) => v.isNotEmpty);
    if (!hasImages && !hasTables) return src;
    try {
      final archive = ZipDecoder().decodeBytes(src);
      final out = Archive();
      // シート名 → xl/worksheets/sheetN.xml を workbook.xml + rels から引く。
      String part(String name) {
        for (final f in archive.files) {
          if (f.name == name && f.isFile) {
            return utf8.decode(f.content as List<int>, allowMalformed: true);
          }
        }
        return '';
      }

      final wb = part('xl/workbook.xml');
      final wbRels = part('xl/_rels/workbook.xml.rels');
      // シート名 → sheet ファイル名
      final sheetFileOf = <String, String>{};
      for (final m in RegExp(r'<sheet\b[^>]*/?>').allMatches(wb)) {
        final tag = m.group(0)!;
        final nm = RegExp(r'name="([^"]*)"').firstMatch(tag)?.group(1);
        final rid = RegExp(r'r:id="([^"]+)"').firstMatch(tag)?.group(1);
        if (nm == null || rid == null) continue;
        final rel =
            RegExp('<Relationship[^>]*Id="$rid"[^>]*>').firstMatch(wbRels);
        if (rel == null) continue;
        final target =
            RegExp(r'Target="([^"]+)"').firstMatch(rel.group(0)!)?.group(1);
        if (target == null) continue;
        sheetFileOf[nm] =
            target.startsWith('/') ? target.substring(1) : 'xl/$target';
      }

      final updated = <String, List<int>>{};
      var types = part('[Content_Types].xml');
      var drawingNo = 0;
      final exts = <String>{};

      for (final entry in _sheetImages.entries) {
        final imgs = entry.value;
        if (imgs.isEmpty) continue;
        final sheetPath = sheetFileOf[entry.key];
        if (sheetPath == null) continue;
        drawingNo++;
        final drawingPath = 'xl/drawings/hnDrawing$drawingNo.xml';
        final drawingRelsPath =
            'xl/drawings/_rels/hnDrawing$drawingNo.xml.rels';
        final anchors = StringBuffer();
        final drels = StringBuffer(
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">');
        var i = 0;
        for (final im in imgs) {
          i++;
          exts.add(im.ext);
          updated['xl/media/${im.mediaName}'] = im.bytes;
          drels.write('<Relationship Id="rIdHN$i" '
              'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" '
              'Target="../media/${im.mediaName}"/>');
          // 画面の 1px ≒ 9525 EMU。 セル番号をそのままアンカーに使う。
          final cx = (im.width * 9525).round();
          final cy = (im.height * 9525).round();
          anchors.write('<xdr:oneCellAnchor>'
              '<xdr:from><xdr:col>${im.col}</xdr:col><xdr:colOff>0</xdr:colOff>'
              '<xdr:row>${im.row}</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from>'
              '<xdr:ext cx="$cx" cy="$cy"/>'
              '<xdr:pic><xdr:nvPicPr>'
              '<xdr:cNvPr id="${1000 + i}" name="HNImage$i"/>'
              '<xdr:cNvPicPr><a:picLocks noChangeAspect="1"/></xdr:cNvPicPr>'
              '</xdr:nvPicPr>'
              '<xdr:blipFill><a:blip r:embed="rIdHN$i"/>'
              '<a:stretch><a:fillRect/></a:stretch></xdr:blipFill>'
              '<xdr:spPr><a:xfrm><a:off x="0" y="0"/>'
              '<a:ext cx="$cx" cy="$cy"/></a:xfrm>'
              '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr>'
              '</xdr:pic><xdr:clientData/></xdr:oneCellAnchor>');
        }
        drels.write('</Relationships>');
        updated[drawingRelsPath] = utf8.encode(drels.toString());
        updated[drawingPath] = utf8.encode(
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" '
            'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
            'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
            '$anchors</xdr:wsDr>');

        // シート側: rels に drawing を足して <drawing r:id> を付ける。
        final base = sheetPath.split('/').last;
        final relsPath =
            '${sheetPath.substring(0, sheetPath.length - base.length)}_rels/$base.rels';
        var rels = updated.containsKey(relsPath)
            ? utf8.decode(updated[relsPath]!)
            : part(relsPath);
        if (rels.isEmpty) {
          rels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '</Relationships>';
        }
        final drawRid = 'rIdHNDraw$drawingNo';
        if (!rels.contains(drawRid)) {
          rels = rels.replaceFirst(
              '</Relationships>',
              '<Relationship Id="$drawRid" '
              'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" '
              'Target="../drawings/hnDrawing$drawingNo.xml"/></Relationships>');
        }
        updated[relsPath] = utf8.encode(rels);

        var sx = updated.containsKey(sheetPath)
            ? utf8.decode(updated[sheetPath]!)
            : part(sheetPath);
        if (sx.isNotEmpty && !sx.contains('<drawing ')) {
          // <drawing> は </worksheet> の直前 (仕様上ほぼ最後の要素)。
          sx = sx.replaceFirst(
              '</worksheet>', '<drawing r:id="$drawRid"/></worksheet>');
          updated[sheetPath] = utf8.encode(sx);
        }

        if (types.isNotEmpty && !types.contains('/$drawingPath')) {
          types = types.replaceFirst(
              '</Types>',
              '<Override PartName="/$drawingPath" '
              'ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/>'
              '</Types>');
        }
      }
      for (final ext in exts) {
        if (types.isNotEmpty && !types.contains('Extension="$ext"')) {
          types = types.replaceFirst('</Types>',
              '<Default Extension="$ext" ContentType="image/$ext"/></Types>');
        }
      }
      // ── アプリ用の控え (= ユーザー要望: 図や表を excel ファイル上に
      //    置いたままにする)。 これを読み戻すことで、 開き直しても表の
      //    テンプレートや図の位置がそのまま復元できる。 Excel は知らない
      //    パートを無視するので、 本家で開いても問題にならない。 ──
      updated['xl/hnMeta.json'] = utf8.encode(jsonEncode({
        'tables': {
          for (final e in _sheetTables.entries)
            if (e.value.isNotEmpty)
              e.key: [for (final t in e.value) t.toJson()],
        },
        'images': {
          for (final e in _sheetImages.entries)
            if (e.value.isNotEmpty)
              e.key: [for (final i in e.value) i.toJson()],
        },
      }));
      if (types.isNotEmpty && !types.contains('Extension="json"')) {
        types = types.replaceFirst('</Types>',
            '<Default Extension="json" ContentType="application/json"/>'
            '</Types>');
      }
      if (types.isNotEmpty) updated['[Content_Types].xml'] = utf8.encode(types);

      final written = <String>{};
      for (final f in archive.files) {
        if (!f.isFile) continue;
        written.add(f.name);
        final u = updated[f.name];
        if (u != null) {
          out.addFile(ArchiveFile(f.name, u.length, u));
        } else {
          out.addFile(ArchiveFile(f.name, f.size, f.content as List<int>));
        }
      }
      updated.forEach((name, data) {
        if (!written.contains(name)) {
          out.addFile(ArchiveFile(name, data.length, data));
        }
      });
      final zipped = ZipEncoder().encode(out);
      if (zipped == null) return src;
      return Uint8List.fromList(zipped);
    } catch (e) {
      debugPrint('xlsx への図の埋め込みに失敗: $e');
      return src; // 図が入らないだけで、 表データは失わない。
    }
  }

  Future<void> _save() async {
    try {
      final file = File(_currentFilePath);
      if (_kind == _SpreadsheetKind.xlsx) {
        final excel = _excel ?? xls.Excel.createExcel();
        for (final name in _sheetNames) {
          final rows = _sheets[name] ?? const [];
          final sheet = excel[name];
          final oldRowCount = sheet.maxRows;
          final oldColCount = sheet.maxColumns;
          for (int r = 0; r < oldRowCount; r++) {
            for (int c = 0; c < oldColCount; c++) {
              sheet.updateCell(
                xls.CellIndex.indexByColumnRow(columnIndex: c, rowIndex: r),
                xls.TextCellValue(''),
              );
            }
          }
          // 実データ範囲のみ書き出し (= 余白の空セルはファイルに残さない)
          final (dataRows, dataCols) = _findDataBounds(rows);
          for (int r = 0; r < dataRows; r++) {
            for (int c = 0; c < dataCols; c++) {
              sheet.updateCell(
                xls.CellIndex.indexByColumnRow(columnIndex: c, rowIndex: r),
                _parseStringToCellValue(rows[r][c]),
              );
            }
          }
        }
        // ── 表の見た目を CellStyle として焼き込む (= ユーザー要望:
        //    表の挿入。 本家 Excel で開いても同じ見た目になる) ──
        _applyTableStyles(excel);
        final bytes = excel.encode();
        if (bytes == null) throw Exception('XLSX エンコード失敗');
        // ── 貼った図を xlsx へ埋め込む (= ユーザー要望: 図の挿入)。
        //    excel パッケージは図を扱えないので、 出来た zip に
        //    xl/media + xl/drawings を足して結び直す。 ──
        final withImages = _embedImagesIntoXlsx(Uint8List.fromList(bytes));
        await file.writeAsBytes(withImages, flush: true);
      } else {
        final rows = _sheets[_activeSheet] ?? const [];
        // CSV/TSV も実データ範囲のみ書き出し
        final (dataRows, dataCols) = _findDataBounds(rows);
        final trimmedRows = <List<String>>[
          for (int r = 0; r < dataRows; r++)
            [for (int c = 0; c < dataCols; c++) rows[r][c]],
        ];
        final delim = _kind == _SpreadsheetKind.tsv ? '\t' : ',';
        final out = ListToCsvConverter(fieldDelimiter: delim, eol: '\n')
            .convert(trimmedRows);
        final withBom = '\uFEFF$out\n'; // Excel 互換のため BOM 付与
        await file.writeAsString(withBom, flush: true);
      }
      if (!mounted) return;
      setState(() => _dirty = false);
      widget.onSaved?.call();
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        SnackBar(
          backgroundColor: const Color(0xFF1A1A2E),
          content: Text(
              context
                  .read<MindMapProvider>()
                  .t('doc.saved')
                  .replaceFirst('{name}', _currentFileName),
              style: const TextStyle(color: Colors.white)),
          duration: const Duration(seconds: 2),
        ),
      );
    } catch (e, st) {
      debugPrint('SpreadsheetEditor save error: $e\n$st');
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        SnackBar(
          backgroundColor: const Color(0xFFFF6B6B),
          content: Text(
              context
                  .read<MindMapProvider>()
                  .t('doc.saveFailed')
                  .replaceFirst('{err}', '$e'),
              style: const TextStyle(color: Colors.white)),
        ),
      );
    }
  }

  /// 入力文字列を CellValue に変換する。
  ///
  /// 判定ルール (上から順に):
  ///   1. 空文字 → 空テキスト
  ///   2. `=` 始まり → 数式 (例: `=4/1` は計算結果の 4 になる)
  ///   3. `/` を含まない & 整数として解釈可能 → IntCellValue
  ///   4. `/` を含まない & 小数として解釈可能 → DoubleCellValue
  ///   5. `4/1` / `2026/5/16` / `5月16日` 等の日付パターン → DateCellValue
  ///   6. その他 → テキスト
  ///
  /// `/` を含む文字列は、 `=` で始まっていなければ日付候補として解釈する。
  /// `4/1` は 4 ÷ 1 ではなく 4 月 1 日になる。
  /// 計算したいときは `=4/1` のように `=` を付ける。
  xls.CellValue _parseStringToCellValue(String raw) {
    if (raw.isEmpty) return xls.TextCellValue('');
    if (raw.startsWith('=') && raw.length > 1) {
      return xls.FormulaCellValue(raw.substring(1));
    }
    // `/` を含まなければ数値として解釈を試みる
    // (含む場合は日付候補なので数値判定はスキップ)
    if (!raw.contains('/')) {
      // 整数 (先頭ゼロは電話番号等のため文字列維持)
      if (!raw.startsWith('0') || raw == '0' || raw.startsWith('-')) {
        final i = int.tryParse(raw);
        if (i != null) return xls.IntCellValue(i);
      }
      // 小数
      final d = double.tryParse(raw);
      if (d != null &&
          (!raw.startsWith('0') ||
              raw.startsWith('0.') ||
              raw.startsWith('-'))) {
        return xls.DoubleCellValue(d);
      }
    }
    // 日付パターン (M/D / YYYY/M/D / M月D日 / YYYY年M月D日 等)
    final date = _tryParseDateString(raw);
    if (date != null) {
      return xls.DateCellValue(
          year: date.year, month: date.month, day: date.day);
    }
    return xls.TextCellValue(raw);
  }

  /// `4/1`、 `2026/5/16`、 `5月16日`、 `2026年5月16日` などの日付文字列を
  /// DateTime に変換。 認識できなければ null。
  ///
  /// 年が省略されている場合は現在の年を補う。
  static DateTime? _tryParseDateString(String raw) {
    final s = raw.trim();
    if (s.isEmpty) return null;
    // YYYY/M/D
    var m = RegExp(r'^(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})$').firstMatch(s);
    if (m != null) {
      final y = int.parse(m.group(1)!);
      final mo = int.parse(m.group(2)!);
      final d = int.parse(m.group(3)!);
      if (_validDate(y, mo, d)) return DateTime(y, mo, d);
    }
    // M/D (年なし)
    m = RegExp(r'^(\d{1,2})[/\-\.](\d{1,2})$').firstMatch(s);
    if (m != null) {
      final mo = int.parse(m.group(1)!);
      final d = int.parse(m.group(2)!);
      final y = DateTime.now().year;
      if (_validDate(y, mo, d)) return DateTime(y, mo, d);
    }
    // YYYY年M月D日
    m = RegExp(r'^(\d{4})年\s*(\d{1,2})月\s*(\d{1,2})日?$').firstMatch(s);
    if (m != null) {
      final y = int.parse(m.group(1)!);
      final mo = int.parse(m.group(2)!);
      final d = int.parse(m.group(3)!);
      if (_validDate(y, mo, d)) return DateTime(y, mo, d);
    }
    // M月D日
    m = RegExp(r'^(\d{1,2})月\s*(\d{1,2})日?$').firstMatch(s);
    if (m != null) {
      final mo = int.parse(m.group(1)!);
      final d = int.parse(m.group(2)!);
      final y = DateTime.now().year;
      if (_validDate(y, mo, d)) return DateTime(y, mo, d);
    }
    return null;
  }

  static bool _validDate(int y, int m, int d) {
    if (m < 1 || m > 12) return false;
    if (d < 1 || d > 31) return false;
    try {
      final dt = DateTime(y, m, d);
      return dt.year == y && dt.month == m && dt.day == d;
    } catch (_) {
      return false;
    }
  }

  /// 図やグラフ・表をファイルに保存できる形式か。
  ///
  /// csv / tsv は文字だけのファイルなので、 図やグラフを置いても保存すると
  /// 消えてしまう (= _save の csv 分岐はセルの文字しか書き出さない)。
  /// そのため csv / tsv では図・グラフ・表を作る入口を出さない
  /// (= ユーザー要望: 保存できないなら機能ごと外して)。
  bool get _canHoldObjects => _kind == _SpreadsheetKind.xlsx;

  List<List<String>> get _rows => _sheets[_activeSheet] ?? const [];
  int get _rowCount => _rows.length;
  int get _colCount => _rows.isEmpty ? 0 : _rows.first.length;

  void _beginEdit(int row, int col) {
    if (row < 0 || row >= _rowCount || col < 0 || col >= _colCount) return;
    _pushUndo();
    _commitEdit();
    setState(() {
      _editingRow = row;
      _editingCol = col;
      _selRow = row;
      _selCol = col;
      _editCtrl.text = _rows[row][col];
      _editCtrl.selection = TextSelection(
        baseOffset: 0,
        extentOffset: _editCtrl.text.length,
      );
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _editFocus.requestFocus();
    });
  }

  void _commitEdit() {
    final r = _editingRow;
    final c = _editingCol;
    if (r == null || c == null) return;
    if (r < _rowCount && c < _colCount) {
      final old = _rows[r][c];
      final neu = _editCtrl.text;
      if (old != neu) {
        _rows[r][c] = neu;
        _dirty = true;
        _invalidateFormulaCache();
      }
    }
    setState(() {
      _editingRow = null;
      _editingCol = null;
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _keyFocus.requestFocus();
    });
  }

  void _cancelEdit() {
    setState(() {
      _editingRow = null;
      _editingCol = null;
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _keyFocus.requestFocus();
    });
  }

  // ─── ダウンロード (= ユーザー要望: xlsx にもダウンロードボタン) ─────

  /// 保存先を聞いてバイト列を書き出す共通部分。 取り消しなら false。
  Future<bool> _saveBytesAs(
      String defaultName, String ext, List<int> bytes) async {
    String? outPath;
    if (Platform.isWindows || Platform.isMacOS || Platform.isLinux) {
      outPath = await FilePicker.platform.saveFile(
        dialogTitle: context.read<MindMapProvider>().t('fsv.download'),
        fileName: defaultName,
        type: FileType.custom,
        allowedExtensions: [ext],
      );
      if (outPath == null) return false;
      if (!outPath.toLowerCase().endsWith('.$ext')) outPath = '$outPath.$ext';
      await File(outPath).writeAsBytes(bytes, flush: true);
    } else {
      final dir = await getApplicationDocumentsDirectory();
      final exportDir = Directory('${dir.path}/exports');
      if (!await exportDir.exists()) await exportDir.create(recursive: true);
      outPath = '${exportDir.path}/$defaultName';
      await File(outPath).writeAsBytes(bytes, flush: true);
      await OpenFilex.open(outPath);
    }
    if (mounted) _showSnack('ダウンロード完了: $outPath');
    return true;
  }

  /// 今の中身をそのままの形式で別の場所へ保存する。
  Future<void> _downloadSheetCopy() async {
    try {
      _commitEdit();
      // 保存済みの内容を書き出す (未保存分も含めたいので、 先に保存する)。
      await _save();
      final bytes = await File(_currentFilePath).readAsBytes();
      final ext = _kind == _SpreadsheetKind.xlsx
          ? 'xlsx'
          : (_kind == _SpreadsheetKind.tsv ? 'tsv' : 'csv');
      await _saveBytesAs(_currentFileName, ext, bytes);
    } catch (e) {
      if (mounted) _showSnack('ダウンロードに失敗: $e');
    }
  }

  /// 今のシートを CSV にして保存する。
  Future<void> _downloadSheetAsCsv() async {
    try {
      _commitEdit();
      final rows = _rows;
      final (dataRows, dataCols) = _findDataBounds(rows);
      final trimmed = <List<String>>[
        for (int r = 0; r < dataRows; r++)
          [for (int c = 0; c < dataCols; c++) rows[r][c]],
      ];
      final out =
          const ListToCsvConverter(fieldDelimiter: ',', eol: '\n')
              .convert(trimmed);
      final base = _currentFileName.contains('.')
          ? _currentFileName.substring(0, _currentFileName.lastIndexOf('.'))
          : _currentFileName;
      await _saveBytesAs(
          '$base-$_activeSheet.csv', 'csv', utf8.encode('\uFEFF$out\n'));
    } catch (e) {
      if (mounted) _showSnack('ダウンロードに失敗: $e');
    }
  }

  /// 今のシートを PDF にして保存する。
  Future<void> _downloadSheetAsPdf() async {
    try {
      _commitEdit();
      final ok = await _PdfExporter.ensureJapaneseFontOrConfirm(context);
      if (!ok) return;
      final rows = _rows;
      final (dataRows, dataCols) = _findDataBounds(rows);
      // 表示どおり (数式は結果) で出す。
      final trimmed = <List<String>>[
        for (int r = 0; r < dataRows; r++)
          [for (int c = 0; c < dataCols; c++) _displayValue(r, c)],
      ];
      final bytes = await _PdfExporter.exportSheet(
          '$_currentFileName — $_activeSheet', trimmed);
      final base = _currentFileName.contains('.')
          ? _currentFileName.substring(0, _currentFileName.lastIndexOf('.'))
          : _currentFileName;
      await _saveBytesAs('$base.pdf', 'pdf', bytes);
    } catch (e) {
      if (mounted) _showSnack('PDF にできませんでした: $e');
    }
  }

  // ─── コピー / 貼り付け / オートフィル (= ユーザー要望) ─────────────

  /// アプリ内のコピー控え (行 × 列)。 別のアプリへは TSV で渡す。
  List<List<String>>? _clipCells;

  /// 選択範囲 (無ければ 1 セル) を TSV にして返す。
  List<List<String>> _selectedCells() {
    final rg = _hasRange
        ? _range
        : (r1: _selRow, c1: _selCol, r2: _selRow, c2: _selCol);
    return [
      for (int r = rg.r1; r <= rg.r2 && r < _rowCount; r++)
        [
          for (int c = rg.c1; c <= rg.c2 && c < _colCount; c++) _rows[r][c],
        ],
    ];
  }

  /// セルのコピー (= ユーザー要望)。 他のアプリにも TSV で渡す。
  Future<void> _copyCells({bool cut = false}) async {
    _commitEdit();
    final cells = _selectedCells();
    if (cells.isEmpty) return;
    _clipCells = [for (final r in cells) List<String>.from(r)];
    try {
      await Clipboard.setData(
          ClipboardData(text: cells.map((r) => r.join('\t')).join('\n')));
    } catch (_) {}
    if (cut) {
      _pushUndo();
      final rg = _hasRange
          ? _range
          : (r1: _selRow, c1: _selCol, r2: _selRow, c2: _selCol);
      setState(() {
        for (int r = rg.r1; r <= rg.r2 && r < _rowCount; r++) {
          for (int c = rg.c1; c <= rg.c2 && c < _colCount; c++) {
            _rows[r][c] = '';
          }
        }
        _dirty = true;
      });
      _invalidateFormulaCache();
    }
    _showSnack(cut ? '切り取りました' : 'コピーしました');
  }

  /// 貼り付け (= ユーザー要望)。 選択セルを左上として流し込む。
  /// 外のアプリからの TSV / CSV も受け取れる。
  Future<void> _pasteCells() async {
    _commitEdit();
    List<List<String>>? cells;
    try {
      final data = await Clipboard.getData('text/plain');
      final text = data?.text;
      if (text != null && text.trim().isNotEmpty) {
        final lines = text.replaceAll('\r\n', '\n').split('\n');
        while (lines.isNotEmpty && lines.last.isEmpty) {
          lines.removeLast();
        }
        // タブ区切りが 1 つでもあれば TSV、 無ければカンマで割る。
        final delim = text.contains('\t') ? '\t' : ',';
        cells = [for (final l in lines) l.split(delim)];
      }
    } catch (_) {}
    cells ??= _clipCells;
    if (cells == null || cells.isEmpty) return;
    _pushUndo();
    final r0 = _selRow;
    final c0 = _selCol;
    setState(() {
      for (int i = 0; i < cells!.length; i++) {
        final r = r0 + i;
        while (_rowCount <= r) {
          _rows.add(List<String>.filled(math.max(1, _colCount), '',
              growable: true));
        }
        for (int j = 0; j < cells[i].length; j++) {
          final c = c0 + j;
          for (final row in _rows) {
            while (row.length <= c) {
              row.add('');
            }
          }
          _rows[r][c] = cells[i][j];
        }
      }
      _dirty = true;
    });
    _invalidateFormulaCache();
  }

  /// オートフィルのドラッグ中の行き先 (null = ドラッグしていない)。
  int? _fillToRow;
  int? _fillToCol;

  /// オートフィルを確定する (= ユーザー要望)。
  /// 元の範囲を下 / 右へ伸ばす。 数字や「1 月」 のような連番は増やし、
  /// それ以外は繰り返しコピーする。
  void _applyAutoFill() {
    final toR = _fillToRow;
    final toC = _fillToCol;
    setState(() {
      _fillToRow = null;
      _fillToCol = null;
    });
    if (toR == null || toC == null) return;
    final rg = _hasRange
        ? _range
        : (r1: _selRow, c1: _selCol, r2: _selRow, c2: _selCol);
    // 下方向 / 右方向のどちらへ伸ばすか (大きく動いた方)。
    final downCount = toR - rg.r2;
    final rightCount = toC - rg.c2;
    if (downCount <= 0 && rightCount <= 0) return;
    final vertical = downCount >= rightCount;
    _pushUndo();
    setState(() {
      if (vertical) {
        final srcRows = rg.r2 - rg.r1 + 1;
        while (_rowCount <= toR) {
          _rows.add(List<String>.filled(math.max(1, _colCount), '',
              growable: true));
        }
        for (int c = rg.c1; c <= rg.c2 && c < _colCount; c++) {
          final src = [
            for (int r = rg.r1; r <= rg.r2 && r < _rowCount; r++) _rows[r][c],
          ];
          final step = _fillStep(src);
          for (int r = rg.r2 + 1; r <= toR; r++) {
            final n = r - rg.r2; // 1 始まり
            final base = src[(n - 1) % srcRows];
            _rows[r][c] = _fillValue(base, step, ((n - 1) ~/ srcRows) + 1);
          }
        }
      } else {
        final srcCols = rg.c2 - rg.c1 + 1;
        for (final row in _rows) {
          while (row.length <= toC) {
            row.add('');
          }
        }
        for (int r = rg.r1; r <= rg.r2 && r < _rowCount; r++) {
          final src = [
            for (int c = rg.c1; c <= rg.c2 && c < _rows[r].length; c++)
              _rows[r][c],
          ];
          final step = _fillStep(src);
          for (int c = rg.c2 + 1; c <= toC; c++) {
            final n = c - rg.c2;
            final base = src[(n - 1) % srcCols];
            _rows[r][c] = _fillValue(base, step, ((n - 1) ~/ srcCols) + 1);
          }
        }
      }
      _dirty = true;
    });
    _invalidateFormulaCache();
  }

  /// 連番の増分。 元が数字 2 個以上なら差、 数字 1 個なら 1、
  /// 数字でなければ null (= そのままコピー)。
  num? _fillStep(List<String> src) {
    final nums = <num>[];
    for (final v in src) {
      final n = num.tryParse(v.trim());
      if (n == null) return null; // 1 つでも数字でなければコピー扱い
      nums.add(n);
    }
    if (nums.isEmpty) return null;
    if (nums.length == 1) return 1;
    final d = nums[1] - nums[0];
    // 等差になっていない時は最初の差をそのまま使う (Excel と同じ考え方)。
    return d;
  }

  /// [base] を [round] 周目としてずらした値。
  String _fillValue(String base, num? step, int round) {
    if (step == null) return base;
    final n = num.tryParse(base.trim());
    if (n == null) return base;
    final v = n + step * round;
    if (v is int || v == v.roundToDouble()) return v.toInt().toString();
    return '$v';
  }

