  /// 表のテンプレート (Excel の「テーブルスタイル」 に相当する簡易版)。
  static const List<({String name, int? head, int? headFont, int? band,
      int? line})> _kSsTableThemes = [
    (name: '罫線のみ', head: null, headFont: null, band: null, line: 0x9E9E9E),
    (
      name: 'ブルー',
      head: 0x4472C4,
      headFont: 0xFFFFFF,
      band: 0xD9E2F3,
      line: 0x8EAADB
    ),
    (
      name: 'グリーン',
      head: 0x70AD47,
      headFont: 0xFFFFFF,
      band: 0xE2EFDA,
      line: 0xA9D18E
    ),
    (
      name: 'オレンジ',
      head: 0xED7D31,
      headFont: 0xFFFFFF,
      band: 0xFBE5D6,
      line: 0xF4B183
    ),
    (
      name: 'モノクロ',
      head: 0x404040,
      headFont: 0xFFFFFF,
      band: 0xEDEDED,
      line: 0xBFBFBF
    ),
  ];

  /// 前に選んだ表テンプレート (セッション内で覚える)。
  int _ssTableTheme = 1;

  /// 表を挿入する (= ユーザー要望: xlsx で表の挿入)。
  /// 選んでいるセルを左上として、 行数 × 列数の範囲に見出し行・縞・罫線を
  /// 付ける。 範囲を選んでいればその大きさを初期値にする。
  Future<void> _insertSpreadsheetTable() async {
    if (_kind != _SpreadsheetKind.xlsx) {
      _showSnack('表を挿入できるのは xlsx だけです');
      return;
    }
    _commitEdit();
    // 範囲を選んでいれば、 その大きさを初期値にする。
    final sel = _hasRange ? _range : null;
    final rowsCtrl = TextEditingController(
        text: '${sel == null ? 4 : (sel.r2 - sel.r1 + 1)}');
    final colsCtrl = TextEditingController(
        text: '${sel == null ? 3 : (sel.c2 - sel.c1 + 1)}');
    var theme = _ssTableTheme.clamp(0, _kSsTableThemes.length - 1);
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (sctx, setD) {
        final th = _kSsTableThemes[theme];
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E2E),
          title: const Text('表を挿入',
              style: TextStyle(color: Colors.white, fontSize: 15)),
          content: SizedBox(
            width: 280,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              Row(children: [
                Expanded(
                  child: TextField(
                    controller: rowsCtrl,
                    keyboardType: TextInputType.number,
                    style: const TextStyle(color: Colors.white),
                    decoration: const InputDecoration(
                        labelText: '行数',
                        labelStyle: TextStyle(color: Colors.white60)),
                    onChanged: (_) => setD(() {}),
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: TextField(
                    controller: colsCtrl,
                    keyboardType: TextInputType.number,
                    style: const TextStyle(color: Colors.white),
                    decoration: const InputDecoration(
                        labelText: '列数',
                        labelStyle: TextStyle(color: Colors.white60)),
                    onChanged: (_) => setD(() {}),
                  ),
                ),
              ]),
              const SizedBox(height: 12),
              Wrap(
                spacing: 4,
                runSpacing: 4,
                children: [
                  for (int i = 0; i < _kSsTableThemes.length; i++)
                    InkWell(
                      borderRadius: BorderRadius.circular(6),
                      onTap: () => setD(() => theme = i),
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 8, vertical: 4),
                        decoration: BoxDecoration(
                          color: theme == i
                              ? const Color(0xFF6C63FF)
                              : Colors.white.withValues(alpha: 0.08),
                          borderRadius: BorderRadius.circular(6),
                        ),
                        child: Text(_kSsTableThemes[i].name,
                            style: TextStyle(
                                fontSize: 11,
                                color: theme == i
                                    ? Colors.white
                                    : Colors.white70)),
                      ),
                    ),
                ],
              ),
              const SizedBox(height: 10),
              // ちいさなプレビュー。
              SizedBox(
                width: 240,
                height: 96,
                child: Column(children: [
                  for (var r = 0;
                      r < math.min(int.tryParse(rowsCtrl.text) ?? 4, 8);
                      r++)
                    Expanded(
                      child: Row(children: [
                        for (var c = 0;
                            c < math.min(int.tryParse(colsCtrl.text) ?? 3, 8);
                            c++)
                          Expanded(
                            child: Container(
                              margin: const EdgeInsets.all(0.5),
                              decoration: BoxDecoration(
                                color: r == 0
                                    ? (th.head != null
                                        ? Color(0xFF000000 | th.head!)
                                        : Colors.white10)
                                    : (th.band != null && r % 2 == 0
                                        ? Color(0xFF000000 | th.band!)
                                        : Colors.white.withValues(alpha: 0.05)),
                                border: Border.all(
                                    color: th.line != null
                                        ? Color(0xFF000000 | th.line!)
                                        : Colors.white24,
                                    width: 0.5),
                              ),
                            ),
                          ),
                      ]),
                    ),
                ]),
              ),
            ]),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dctx, false),
              child:
                  const Text('キャンセル', style: TextStyle(color: Colors.white54)),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(dctx, true),
              child: const Text('挿入'),
            ),
          ],
        );
      }),
    );
    final rows = (int.tryParse(rowsCtrl.text) ?? 4).clamp(1, 200);
    final cols = (int.tryParse(colsCtrl.text) ?? 3).clamp(1, 60);
    rowsCtrl.dispose();
    colsCtrl.dispose();
    if (ok != true || !mounted) return;
    _pushUndo();
    _ssTableTheme = theme;
    final th = _kSsTableThemes[theme];
    final r0 = sel?.r1 ?? _selRow;
    final c0 = sel?.c1 ?? _selCol;
    setState(() {
      // 足りない行 / 列は伸ばしておく (= はみ出して置けないのを防ぐ)。
      while (_rowCount < r0 + rows) {
        _rows.add(List<String>.filled(
            math.max(1, _colCount), '',
            growable: true));
      }
      final needCols = c0 + cols;
      if (_colCount < needCols) {
        for (final row in _rows) {
          while (row.length < needCols) {
            row.add('');
          }
        }
      }
      _tables.add(_SsTable(
        row: r0,
        col: c0,
        rows: rows,
        cols: cols,
        headerFill: th.head,
        headerFont: th.headFont,
        bandFill: th.band,
        line: th.line,
      ));
      _dirty = true;
    });
  }

  /// 図を挿入する (= ユーザー要望: xlsx で図の挿入)。
  /// 選んでいるセルの位置に貼り、 保存時に xlsx へ埋め込む。
  Future<void> _insertSpreadsheetImage() async {
    if (_kind != _SpreadsheetKind.xlsx) {
      _showSnack('図を挿入できるのは xlsx だけです');
      return;
    }
    final res = await FilePicker.platform.pickFiles(
      type: FileType.custom,
      allowedExtensions: ['png', 'jpg', 'jpeg', 'gif', 'bmp'],
      withData: true,
    );
    if (res == null || res.files.isEmpty || !mounted) return;
    final f = res.files.first;
    Uint8List? bytes = f.bytes;
    if (bytes == null && f.path != null) {
      try {
        bytes = await File(f.path!).readAsBytes();
      } catch (_) {}
    }
    if (bytes == null || !mounted) {
      _showSnack('画像を読み込めませんでした');
      return;
    }
    var ext = (f.extension ?? 'png').toLowerCase();
    if (ext == 'jpg') ext = 'jpeg';
    double aspect = 4 / 3;
    try {
      final codec = await ui.instantiateImageCodec(bytes);
      final frame = await codec.getNextFrame();
      aspect = frame.image.width / frame.image.height;
      frame.image.dispose();
    } catch (_) {}
    if (!mounted) return;
    _pushUndo();
    const baseW = 240.0;
    setState(() {
      _images.add(_SsImage(
        bytes: bytes!,
        ext: ext,
        mediaName:
            'hnimg_${DateTime.now().millisecondsSinceEpoch}_${_images.length}.$ext',
        row: _selRow,
        col: _selCol,
        width: baseW,
        height: baseW / (aspect <= 0 ? 1.3333 : aspect),
      ));
      _dirty = true;
    });
    _showSnack('✓ 図を挿入しました (保存で xlsx に埋め込まれます)');
  }

  /// CSV を取り込んでシートとして追加する (= ユーザー要望: xlsx 編集画面の
  /// 中に csv ファイルの取り込みを付けて、 csv を xlsx の中に埋め込める
  /// ように)。 取り込んだ内容は新しいシートになる。
  Future<void> _importCsvIntoWorkbook() async {
    if (_kind != _SpreadsheetKind.xlsx) {
      _showSnack('CSV を取り込めるのは xlsx だけです');
      return;
    }
    final res = await FilePicker.platform.pickFiles(
      type: FileType.custom,
      allowedExtensions: ['csv', 'tsv', 'txt'],
      withData: true,
    );
    if (res == null || res.files.isEmpty || !mounted) return;
    final f = res.files.first;
    String? text;
    try {
      final data = f.bytes ??
          (f.path != null ? await File(f.path!).readAsBytes() : null);
      if (data != null) {
        // BOM 付き / 無しの UTF-8 を読む (壊れた文字は落とさず置換)。
        text = utf8.decode(data, allowMalformed: true);
        if (text.isNotEmpty && text.codeUnitAt(0) == 0xFEFF) {
          text = text.substring(1);
        }
      }
    } catch (_) {}
    if (text == null || !mounted) {
      _showSnack('CSV を読み込めませんでした');
      return;
    }
    final delim = (f.extension ?? '').toLowerCase() == 'tsv' ? '\t' : ',';
    List<List<String>> rows;
    try {
      final parsed = const CsvToListConverter(shouldParseNumbers: false)
          .convert(text, fieldDelimiter: delim, eol: '\n');
      rows = [
        for (final r in parsed) [for (final c in r) '$c'],
      ];
    } catch (_) {
      rows = [
        for (final line in text.split(RegExp(r'\r?\n')))
          line.split(delim),
      ];
    }
    // 末尾の空行を落とす。
    while (rows.isNotEmpty && rows.last.every((c) => c.trim().isEmpty)) {
      rows.removeLast();
    }
    if (rows.isEmpty) {
      _showSnack('CSV が空でした');
      return;
    }
    // 列数を揃える (= 行ごとに長さが違うと編集で落ちるため)。
    final cols = rows.fold<int>(0, (a, r) => math.max(a, r.length));
    for (final r in rows) {
      while (r.length < cols) {
        r.add('');
      }
    }
    _commitEdit();
    _pushUndo();
    // シート名はファイル名から (Excel の制限に合わせて 31 文字 + 記号除去)。
    var base = (f.name.contains('.')
            ? f.name.substring(0, f.name.lastIndexOf('.'))
            : f.name)
        .replaceAll(RegExp(r'[\\/*?\[\]:]'), '_')
        .trim();
    if (base.isEmpty) base = 'CSV';
    if (base.length > 28) base = base.substring(0, 28);
    var name = base;
    var n = 2;
    while (_sheetNames.contains(name)) {
      name = '$base$n';
      n++;
    }
    setState(() {
      _sheets[name] = rows;
      _sheetNames.add(name);
      _activeSheet = name;
      _selRow = 0;
      _selCol = 0;
      _rangeAnchorRow = null;
      _rangeAnchorCol = null;
      _dirty = true;
    });
    _invalidateFormulaCache();
    _showSnack('✓ 「$name」 として取り込みました (保存で xlsx に入ります)');
  }

  /// 新しいシートを足す (= ユーザー要望: シート名の右端の + から追加)。
  /// csv / tsv は 1 枚しか書き出せないので、 xlsx の時だけ有効。
  void _addSheet() {
    if (_kind != _SpreadsheetKind.xlsx) {
      _showSnack('シートを増やせるのは xlsx だけです');
      return;
    }
    _commitEdit();
    _pushUndo();
    // 「Sheet2」 「Sheet3」 … と空いている番号を探す。
    var n = _sheetNames.length + 1;
    var name = 'Sheet$n';
    while (_sheetNames.contains(name)) {
      n++;
      name = 'Sheet$n';
    }
    setState(() {
      // 既定の広さは今のシートと揃える (= 空すぎて使いにくいのを防ぐ)。
      final rows = math.max(30, _rowCount);
      final cols = math.max(15, _colCount);
      _sheets[name] = List.generate(
          rows, (_) => List<String>.filled(cols, '', growable: true),
          growable: true);
      _sheetNames.add(name);
      _activeSheet = name;
      _selRow = 0;
      _selCol = 0;
      _rangeAnchorRow = null;
      _rangeAnchorCol = null;
      _dirty = true;
    });
    _invalidateFormulaCache();
  }

  void _insertRow(int at) {
    _pushUndo();
    final cols = _colCount.clamp(1, 1 << 30);
    _rows.insert(at, List.filled(cols, '', growable: true));
    _invalidateFormulaCache();
    setState(() => _dirty = true);
  }

  void _removeRow(int at) {
    _pushUndo();
    if (_rowCount <= 1) {
      for (int c = 0; c < _colCount; c++) {
        _rows[0][c] = '';
      }
    } else {
      _rows.removeAt(at);
      if (_selRow >= _rowCount) _selRow = _rowCount - 1;
    }
    _invalidateFormulaCache();
    setState(() => _dirty = true);
  }

  void _insertColumn(int at) {
    _pushUndo();
    for (final row in _rows) {
      row.insert(at, '');
    }
    _invalidateFormulaCache();
    setState(() => _dirty = true);
  }

  void _removeColumn(int at) {
    _pushUndo();
    if (_colCount <= 1) {
      for (int r = 0; r < _rowCount; r++) {
        _rows[r][0] = '';
      }
    } else {
      for (final row in _rows) {
        row.removeAt(at);
      }
      if (_selCol >= _colCount) _selCol = _colCount - 1;
    }
    _invalidateFormulaCache();
    setState(() => _dirty = true);
  }

  KeyEventResult _onKeyEvent(FocusNode node, KeyEvent event) {
    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
      return KeyEventResult.ignored;
    }
    final ctrl = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    final shift = HardwareKeyboard.instance.isShiftPressed;

    if (ctrl && event.logicalKey == LogicalKeyboardKey.keyS) {
      _save();
      return KeyEventResult.handled;
    }
    // ── セルのコピー / 切り取り / 貼り付け (= ユーザー要望) ──
    //    セルを編集中は普通の文字コピーに任せる。
    if (ctrl && _editingRow == null) {
      if (event.logicalKey == LogicalKeyboardKey.keyC) {
        unawaited(_copyCells());
        return KeyEventResult.handled;
      }
      if (event.logicalKey == LogicalKeyboardKey.keyX) {
        unawaited(_copyCells(cut: true));
        return KeyEventResult.handled;
      }
      if (event.logicalKey == LogicalKeyboardKey.keyV) {
        unawaited(_pasteCells());
        return KeyEventResult.handled;
      }
    }
    // Ctrl+Z = Undo, Ctrl+Shift+Z = Redo
    if (ctrl && event.logicalKey == LogicalKeyboardKey.keyZ) {
      if (shift) {
        _redo();
      } else {
        _undo();
      }
      return KeyEventResult.handled;
    }
    // Ctrl+Y = Redo (Windows 慣習)
    if (ctrl && event.logicalKey == LogicalKeyboardKey.keyY) {
      _redo();
      return KeyEventResult.handled;
    }

    // ── Esc の扱い ──
    // 編集中なら「編集をやめる」 (Excel と同じ)。 それ以外は、 設定で
    // 「Esc で閲覧画面を閉じる」 を切っていれば何もしないで消費する
    // (= ユーザー要望: Excel などが Esc で閉じてしまうのを止めたい)。
    if (event.logicalKey == LogicalKeyboardKey.escape) {
      if (_editingRow != null) {
        _cancelEdit();
        return KeyEventResult.handled;
      }
      if (!context.read<MindMapProvider>().closeViewerWithEsc) {
        return KeyEventResult.handled;
      }
      return KeyEventResult.ignored; // 従来どおりダイアログを閉じる
    }

    if (_editingRow != null) return KeyEventResult.ignored;

    // ── 矢印キー: Shift 併用なら範囲を伸ばす (= ユーザー要望: 範囲選択) ──
    void moveSel(int dr, int dc) {
      setState(() {
        if (shift) {
          _ensureRangeAnchor();
        } else {
          _resetRangeAnchor();
        }
        _selRow = (_selRow + dr).clamp(0, _rowCount - 1);
        _selCol = (_selCol + dc).clamp(0, _colCount - 1);
      });
      _ensureSelVisible();
    }

    if (event.logicalKey == LogicalKeyboardKey.arrowDown) {
      moveSel(1, 0);
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.arrowUp) {
      moveSel(-1, 0);
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.arrowRight) {
      moveSel(0, 1);
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.arrowLeft) {
      moveSel(0, -1);
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.tab) {
      setState(() {
        _resetRangeAnchor();
        _selCol = (_selCol + (shift ? -1 : 1)).clamp(0, _colCount - 1);
      });
      _ensureSelVisible();
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.enter ||
        event.logicalKey == LogicalKeyboardKey.f2) {
      _beginEdit(_selRow, _selCol);
      return KeyEventResult.handled;
    }
    // ── Delete   = 選んでいるセルを全部消す (範囲選択ならその範囲すべて)
    //    Backspace = 今いる 1 セルだけ消す (範囲を選んでいても)
    //    (= ユーザー要望: Del は範囲まるごと、 Backspace は今のセルだけ)
    if (event.logicalKey == LogicalKeyboardKey.delete ||
        event.logicalKey == LogicalKeyboardKey.backspace) {
      final wholeRange =
          event.logicalKey == LogicalKeyboardKey.delete && _hasRange;
      _clearCells(wholeRange: wholeRange);
      return KeyEventResult.handled;
    }
    // ── Excel ライク: 印刷可能な文字キーで直接編集モードに入る ──
    // Enter を押さなくても文字を打ち始めるとそのセルが編集状態になり、
    // 押した文字が最初の入力として置き換わる (= 既存値は破棄)。
    // Ctrl/Meta が押されてる場合 (= ショートカット) は除外。
    if (!ctrl && event.character != null) {
      final ch = event.character!;
      // 印刷可能な文字のみ (制御文字・空文字を除く)。
      // 制御文字は code unit が 0x20 (space) 未満または 0x7F (DEL)。
      if (ch.isNotEmpty &&
          ch.codeUnitAt(0) >= 0x20 &&
          ch.codeUnitAt(0) != 0x7F) {
        if (_rowCount > 0 &&
            _colCount > 0 &&
            _selRow < _rowCount &&
            _selCol < _colCount) {
          _beginEdit(_selRow, _selCol);
          // _beginEdit 内で text を既存値 + 全選択 にしているので、
          // ここで上書きして 1 文字だけにし、 カーソルを末尾へ。
          _editCtrl.text = ch;
          _editCtrl.selection = TextSelection.collapsed(offset: ch.length);
          return KeyEventResult.handled;
        }
      }
    }
    return KeyEventResult.ignored;
  }

  /// 選んでいるセルの中身を消す。
  /// [wholeRange] が true なら範囲すべて、 false なら今いる 1 セルだけ
  /// (= ユーザー要望: Delete は範囲まるごと / Backspace は 1 セルだけ)。
  void _clearCells({required bool wholeRange}) {
    if (_rowCount <= 0 || _colCount <= 0) return;
    final sel = wholeRange
        ? _range
        : (r1: _selRow, c1: _selCol, r2: _selRow, c2: _selCol);
    var changed = false;
    for (var r = sel.r1; r <= sel.r2; r++) {
      if (r < 0 || r >= _rowCount) continue;
      for (var c = sel.c1; c <= sel.c2; c++) {
        if (c < 0 || c >= _colCount) continue;
        if (_rows[r][c].isEmpty) continue;
        if (!changed) {
          _pushUndo();
          changed = true;
        }
        _rows[r][c] = '';
      }
    }
    if (!changed) return;
    // 数式の計算結果も作り直す (= 消したセルを参照している式に効く)。
    _invalidateFormulaCache();
    setState(() => _dirty = true);
  }

  void _ensureSelVisible() {
    final x = _selCol * _cellWidth;
    final y = _selRow * _cellHeight;
    if (_hScroll.hasClients) {
      final v = _hScroll.offset;
      final w = _hScroll.position.viewportDimension;
      if (x < v)
        _hScroll.jumpTo(x.clamp(0.0, _hScroll.position.maxScrollExtent));
      if (x + _cellWidth > v + w) {
        _hScroll.jumpTo(
            (x + _cellWidth - w).clamp(0.0, _hScroll.position.maxScrollExtent));
      }
    }
    if (_vScroll.hasClients) {
      final v = _vScroll.offset;
      final h = _vScroll.position.viewportDimension;
      if (y < v)
        _vScroll.jumpTo(y.clamp(0.0, _vScroll.position.maxScrollExtent));
      if (y + _cellHeight > v + h) {
        _vScroll.jumpTo((y + _cellHeight - h)
            .clamp(0.0, _vScroll.position.maxScrollExtent));
      }
    }
  }

  Future<bool> _confirmDiscard({BuildContext? anchor}) async {
    if (!_dirty) return true;
    // × ボタンの近く + フローティング窓の上に出す (= ユーザー要望)。
    final r = await _showUnsavedConfirmNear(anchor ?? context);
    if (r == 'save') {
      await _save();
      return true;
    }
    return r == 'discard';
  }

  // ─── AI 編集 ─────────────────────────────────────────────────────
  /// AI サイドパネルを開いているか (= ユーザー要望: pptx と同じ形式)。
  bool _aiChatPanelOpen = false;

  /// AI に渡す今のシート (CSV)。
  String _collectSheetCsvForAi() {
    _commitEdit();
    try {
      return const ListToCsvConverter(fieldDelimiter: ',', eol: '\n')
          .convert(_rows);
    } catch (_) {
      return '';
    }
  }

  /// AI の返事 (CSV) をシートに反映する。
  Future<void> _applyAiCsvReply(String reply) async {
    final cleaned = _stripCodeFence(reply).trim();
    if (cleaned.isEmpty) return;
    try {
      final parsed = const CsvToListConverter(
        fieldDelimiter: ',',
        eol: '\n',
        shouldParseNumbers: false,
      ).convert(cleaned);
      final newRows = parsed
          .map((r) => r.map((c) => c?.toString() ?? '').toList())
          .toList();
      if (newRows.isEmpty) return;
      final maxCols =
          newRows.fold<int>(0, (m, r) => r.length > m ? r.length : m);
      for (final r in newRows) {
        while (r.length < maxCols) {
          r.add('');
        }
      }
      // 元に戻せるように控えておく (= 既存の Undo と同じ仕組み)。
      _aiUndoSnapshot = {
        for (final e in _sheets.entries)
          e.key: e.value.map((r) => [...r]).toList(),
      };
      setState(() {
        _sheets[_activeSheet] = newRows;
        _dirty = true;
        _selRow = 0;
        _selCol = 0;
        _invalidateFormulaCache();
      });
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
          SnackBar(content: Text('反映できませんでした: $e')));
    }
  }

  Future<void> _showAiEditDialog() async {
    _commitEdit();
    final ctrl = TextEditingController();
    final instruction = await showDialog<String>(
      context: context,
      builder: (dctx) {
        return AlertDialog(
          backgroundColor:
              widget.isDarkMode ? const Color(0xFF22222E) : Colors.white,
          title: Row(
            children: [
              const Icon(Icons.auto_awesome_rounded, color: Color(0xFFAB47BC)),
              const SizedBox(width: 8),
              Text(context.read<MindMapProvider>().t('doc.aiRewrite')),
            ],
          ),
          content: SizedBox(
            width: 460,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  context
                      .read<MindMapProvider>()
                      .t('ss.aiEditDesc')
                      .replaceFirst('{sheet}', '$_activeSheet'),
                  style: TextStyle(
                    fontSize: 12,
                    color: widget.isDarkMode ? Colors.white60 : Colors.black54,
                  ),
                ),
                const SizedBox(height: 12),
                // ── モデル / 推論レベルの選択 (= ユーザー要望) ──
                const _AiModelReasoningRow(),
                const SizedBox(height: 10),
                TextField(
                  controller: ctrl,
                  autofocus: true,
                  maxLines: 4,
                  minLines: 3,
                  decoration: InputDecoration(
                    hintText: context
                        .read<MindMapProvider>()
                        .t('doc.instructionHint'),
                    border: const OutlineInputBorder(),
                  ),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
              child: Text(context.read<MindMapProvider>().t('btn.cancel')),
            ),
            FilledButton.icon(
              icon: const Icon(Icons.auto_awesome_rounded, size: 16),
              label: Text(context.read<MindMapProvider>().t('doc.aiExecute')),
              style: FilledButton.styleFrom(
                backgroundColor: const Color(0xFFAB47BC),
                foregroundColor: Colors.white,
              ),
              onPressed: () => Navigator.of(dctx).pop(ctrl.text),
            ),
          ],
        );
      },
    );
    if (instruction == null || instruction.trim().isEmpty) return;
    await _applyAiEdit(instruction.trim());
  }

  Future<void> _applyAiEdit(String instruction) async {
    setState(() => _aiBusy = true);
    try {
      final rows = _rows;
      // CSV 形式でシリアライズして AI に渡す
      final csvText = const ListToCsvConverter(fieldDelimiter: ',', eol: '\n')
          .convert(rows);
      final prompt =
          '''以下は CSV 形式の表データです。 ユーザーの指示に従って表を書き換え、 書き換え後の CSV データだけを返してください。

- 説明文・コードブロック (\`\`\`) ・前後のテキストは一切含めず、 CSV データそのものだけを返す
- 行の区切りは LF、 セル区切りはカンマ
- セル内にカンマや改行を含む場合は CSV ルールに従って二重引用符でエスケープ
- 数値は引用符なしの数値リテラル、 文字列はそのまま
- 数式を使う場合は = で始める (例: =SUM(A1:A3))
- 列数・行数を必要に応じて変更してよい

【ユーザーの指示】
$instruction

【現在のデータ (CSV)】
$csvText
''';

      final provider = context.read<MindMapProvider>();
      final response = await provider.askAi(prompt);
      final cleaned = _stripCodeFence(response);
      if (cleaned.trim().isEmpty) {
        throw Exception('AI が空の応答を返しました');
      }
      final parsed = const CsvToListConverter(
        fieldDelimiter: ',',
        eol: '\n',
        shouldParseNumbers: false,
      ).convert(cleaned);
      final newRows = parsed
          .map((r) => r.map((c) => c?.toString() ?? '').toList())
          .toList();
      if (newRows.isEmpty) {
        throw Exception('AI 応答から行を取り出せませんでした');
      }
      // 列数を揃える
      final maxCols =
          newRows.fold<int>(0, (m, r) => r.length > m ? r.length : m);
      for (final r in newRows) {
        while (r.length < maxCols) {
          r.add('');
        }
      }
      // スナップショット保存 (全シート分。 マルチシートの場合に他シートも一括復元できるように)
      _aiUndoSnapshot = {
        for (final e in _sheets.entries)
          e.key: e.value.map((r) => [...r]).toList(),
      };
      setState(() {
        _sheets[_activeSheet] = newRows;
        _dirty = true;
        _selRow = 0;
        _selCol = 0;
        _invalidateFormulaCache();
      });
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        SnackBar(
          backgroundColor: const Color(0xFF1A1A2E),
          duration: const Duration(seconds: 8),
          content: Row(
            children: [
              const Icon(Icons.auto_awesome_rounded,
                  color: Color(0xFFAB47BC), size: 18),
              const SizedBox(width: 8),
              const Expanded(
                child: Text(
                  'AI で書き換えました',
                  style: TextStyle(color: Colors.white),
                ),
              ),
              TextButton(
                onPressed: _undoAiEdit,
                child: const Text(
                  '元に戻す',
                  style: TextStyle(
                      color: Color(0xFFFFCA28), fontWeight: FontWeight.w700),
                ),
              ),
            ],
          ),
        ),
      );
    } catch (e, st) {
      debugPrint('AI edit error: $e\n$st');
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        SnackBar(
          backgroundColor: const Color(0xFFFF6B6B),
          content: Text(
              context
                  .read<MindMapProvider>()
                  .t('doc.aiEditFailed')
                  .replaceFirst('{err}', '$e'),
              style: const TextStyle(color: Colors.white)),
          duration: const Duration(seconds: 5),
        ),
      );
    } finally {
      if (mounted) setState(() => _aiBusy = false);
    }
  }

  void _undoAiEdit() {
    if (_aiUndoSnapshot == null) return;
    setState(() {
      _sheets
        ..clear()
        ..addAll(_aiUndoSnapshot!);
      _aiUndoSnapshot = null;
      _invalidateFormulaCache();
    });
    ScaffoldMessenger.maybeOf(context)?.hideCurrentSnackBar();
  }

  /// AI 応答から code fence (\`\`\`xxx ... \`\`\`) を除去する。
  static String _stripCodeFence(String text) {
    var t = text.trim();
    // 先頭の ```lang を剥がす
    final start = RegExp(r'^```[a-zA-Z0-9_-]*\s*\n?').firstMatch(t);
    if (start != null) {
      t = t.substring(start.end);
      // 末尾の ``` を剥がす
      final end = RegExp(r'\n?```\s*\$').firstMatch(t);
      if (end != null) {
        t = t.substring(0, end.start);
      }
    }
    return t;
  }

  @override
  Widget build(BuildContext context) {
    final dark = widget.isDarkMode;
    final bg = dark ? const Color(0xFF1A1A24) : const Color(0xFFEFEFEA);
    final fg = dark ? Colors.white : const Color(0xFF1A1A24);

    Widget body;
    if (_loading) {
      body = const Center(child: CircularProgressIndicator());
    } else if (_loadError != null) {
      body = Center(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(Icons.error_outline,
                  color: Colors.redAccent, size: 48),
              const SizedBox(height: 12),
              Text(context.read<MindMapProvider>().t('doc.cannotOpenFile'),
                  style: TextStyle(
                      color: fg, fontSize: 16, fontWeight: FontWeight.w600)),
              const SizedBox(height: 6),
              Text(_loadError!,
                  style: TextStyle(color: fg.withValues(alpha: 0.7))),
            ],
          ),
        ),
      );
    } else {
      body = _buildSheet(dark, fg);
    }

    // 埋め込みで使われている時 (画面分割のペインの中など) は、 アプリ本体の
    // 画面と入れ物を共有しているので横取りしない (= 横取りすると Android の
    // 戻るでアプリ本体まで閉じてしまう)。
    return PopScope(
      canPop: !_ownsCloseRoute(context),
      onPopInvokedWithResult: (didPop, _) async {
        if (didPop) return;
        // Esc で閉じない設定の時は、 Esc からの「閉じて」 は無視する
        // (= ユーザー要望: 編集中に閉じられると厄介)。
        if (_isEscClosePressed(context)) return;
        if (await _confirmDiscard()) {
          if (mounted) Navigator.of(context).pop();
        }
      },
      child: Container(
        color: bg,
        child: Stack(children: [
          Column(
            children: [
              _buildHeader(dark, fg),
              // ── 数式バー (= ユーザー要望: Excel と同じく上のバーに選択中の
              //    セルの内容・数式を表示 / 編集できるように)。 以前この位置に
              //    あったシートタブと紛らわしかった (「メモ」 と書かれた所) ──
              if (!_loading && _loadError == null) _buildFormulaBar(dark, fg),
              Expanded(
                child: Row(children: [
                  Expanded(child: body),
                  // ── AI アシスタント (= ユーザー要望: pptx と同じ
                  //    サイドメニュー形式に) ──
                  if (_aiChatPanelOpen)
                    _AiDocChatPanel(
                      title: 'AI アシスタント (表)',
                      hint: '「B 列を全部 2 倍にして」「合計行を末尾に追加して」 のように書けます。',
                      docContextGetter: _collectSheetCsvForAi,
                      roleLine: _kSheetAiRoleLine,
                      applyLabel: 'シートに反映',
                      appliedMsg: 'シートに反映しました',
                      historyKey:
                          'docAiChat_ss_${widget.filePath.hashCode.toRadixString(16)}',
                      onApply: (reply) =>
                          unawaited(_applyAiCsvReply(reply)),
                      onClose: () =>
                          setState(() => _aiChatPanelOpen = false),
                    ),
                ]),
              ),
              // ── シートの切り替えタブは左下へ (= ユーザー要望: Excel と同じ) ──
              if (_kind == _SpreadsheetKind.xlsx && _sheetNames.isNotEmpty)
                _buildSheetTabs(dark, fg),
              _buildStatusBar(dark, fg),
            ],
          ),
          // 画面内のお知らせ (全画面ダイアログなので SnackBar は使えない)。
          if (_sheetToastMsg != null)
            Positioned(
              left: 0,
              right: 0,
              bottom: 56,
              child: Center(
                child: Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
                  decoration: BoxDecoration(
                    color: _sheetToastColor,
                    borderRadius: BorderRadius.circular(10),
                    boxShadow: const [
                      BoxShadow(color: Colors.black45, blurRadius: 10),
                    ],
                  ),
                  child: Text(_sheetToastMsg!,
                      style: const TextStyle(
                          color: Colors.black87,
                          fontSize: 12.5,
                          fontWeight: FontWeight.w700)),
                ),
              ),
            ),
        ]),
      ),
    );
  }

  Widget _buildHeader(bool dark, Color fg) {
    return Container(
      height: 52,
      padding: const EdgeInsets.symmetric(horizontal: 12),
      decoration: BoxDecoration(
        color: dark ? const Color(0xFF22222E) : const Color(0xFFE0E0DA),
        border: Border(
          bottom: BorderSide(color: dark ? Colors.white12 : Colors.black12),
        ),
      ),
      child: Row(
        children: [
          Icon(
            _kind == _SpreadsheetKind.xlsx
                ? Icons.table_chart_rounded
                : Icons.grid_on_rounded,
            color: _kind == _SpreadsheetKind.xlsx
                ? Colors.green
                : const Color(0xFF6C63FF),
          ),
          const SizedBox(width: 8),
          // ファイル名 (タップで変更)
          Flexible(
            child: InkWell(
              onTap: _showRenameDialog,
              borderRadius: BorderRadius.circular(6),
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Flexible(
                      child: Text(_currentFileName,
                          style: TextStyle(
                              color: fg,
                              fontSize: 15,
                              fontWeight: FontWeight.w600),
                          overflow: TextOverflow.ellipsis),
                    ),
                    const SizedBox(width: 4),
                    Icon(Icons.edit_outlined,
                        size: 14, color: fg.withValues(alpha: 0.5)),
                  ],
                ),
              ),
            ),
          ),
          if (_dirty)
            Container(
              margin: const EdgeInsets.only(left: 8),
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
              // ★ 白いヘッダーの上では黄色の文字が読めないので、 塗り潰した
              //   帯に白抜きの文字にする (= ユーザー要望: 未保存の文字が
              //   黄色で見にくい)。 暗い配色でも同じように読める。
              decoration: BoxDecoration(
                color: const Color(0xFFD84315),
                borderRadius: BorderRadius.circular(10),
              ),
              child: Text(context.read<MindMapProvider>().t('doc.unsaved'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 11,
                      fontWeight: FontWeight.w700)),
            ),
          const Spacer(),
          // ── 画面分割で開く (左/右の 2 ボタン) ──
          // (左右の画面分割ボタンは廃止 = ユーザー要望: 分割表示中は
          //  ファイルが自動でペインに開くため不要になった)
          // 数式表示トグル (= 結果表示 / 数式そのものを表示)
          // OFF の時は amber 色で目立たせて「数式が計算されないバグ」 と
          // 勘違いされないようにする。
          if (!_showFormulaResults)
            Container(
              margin: const EdgeInsets.only(right: 6),
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
              decoration: BoxDecoration(
                color: Colors.amber.withValues(alpha: 0.2),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: Colors.amber, width: 1),
              ),
              child: InkWell(
                onTap: () {
                  _commitEdit();
                  _invalidateFormulaCache();
                  setState(() => _showFormulaResults = true);
                },
                borderRadius: BorderRadius.circular(10),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Icon(Icons.warning_amber_rounded,
                        size: 14, color: Colors.amber),
                    const SizedBox(width: 4),
                    Text(context.read<MindMapProvider>().t('ss.formulaOff'),
                        style: const TextStyle(
                            color: Colors.amber,
                            fontSize: 11,
                            fontWeight: FontWeight.w700)),
                    const SizedBox(width: 4),
                    Text(context.read<MindMapProvider>().t('ss.tapToOn'),
                        style: const TextStyle(
                            color: Colors.amber,
                            fontSize: 10,
                            fontWeight: FontWeight.w500)),
                  ],
                ),
              ),
            ),
          IconButton(
            tooltip: _showFormulaResults
                ? '数式の結果を表示中\n(タップで数式テキストを表示)'
                : '数式テキストを表示中\n(タップで結果を表示)',
            icon: Stack(
              clipBehavior: Clip.none,
              alignment: Alignment.center,
              children: [
                Icon(
                  Icons.functions_rounded,
                  color: _showFormulaResults
                      ? const Color(0xFF6C63FF)
                      : Colors.amber,
                ),
                if (!_showFormulaResults)
                  // 斜線で OFF を表現
                  Positioned.fill(
                    child: CustomPaint(
                      painter: _DiagonalSlashPainter(color: Colors.amber),
                    ),
                  ),
              ],
            ),
            onPressed: () {
              _commitEdit();
              _invalidateFormulaCache();
              setState(() => _showFormulaResults = !_showFormulaResults);
            },
          ),
          // ── 図 / 表の挿入・CSV 取り込み (= ユーザー要望)。 xlsx だけ ──
          if (_kind == _SpreadsheetKind.xlsx) ...[
            IconButton(
              tooltip: context.read<MindMapProvider>().t('tip.insertPicture'),
              icon: const Icon(Icons.image_outlined, color: Color(0xFF4FC3F7)),
              onPressed: () => unawaited(_insertSpreadsheetImage()),
            ),
            IconButton(
              tooltip: context.read<MindMapProvider>().t('pptx.insertTable'),
              icon: const Icon(Icons.grid_on_rounded, color: Color(0xFF43B97F)),
              onPressed: () => unawaited(_insertSpreadsheetTable()),
            ),
          ],
          // ── 選んだ範囲を表 / グラフにする (= ユーザー要望: 端の小さな
          //    ボタンだと気付かないので、 ヘッダーに出す)。 範囲を選んで
          //    いない間は押せない見た目にする。 ──
          // ★ csv / tsv では出さない (= ユーザー要望: csv は文字だけの
          //   ファイルなので、 作った図や表を保存できない。 保存すると
          //   黙って消えるので、 機能ごと出さないようにする)。
          if (_canHoldObjects) ...[
            IconButton(
              tooltip: _hasRange
                  ? '選んだ範囲を表にする'
                  : '表にする (先にセルの範囲を選んでください)',
              icon: Icon(Icons.table_view_rounded,
                  color: _hasRange
                      ? const Color(0xFF26C6DA)
                      : const Color(0xFF26C6DA).withValues(alpha: 0.3)),
              onPressed: _hasRange ? _rangeToTable : null,
            ),
            IconButton(
              tooltip: _hasRange
                  ? '選んだ範囲をグラフにする'
                  : 'グラフにする (先にセルの範囲を選んでください)',
              icon: Icon(Icons.bar_chart_rounded,
                  color: _hasRange
                      ? const Color(0xFF7CB342)
                      : const Color(0xFF7CB342).withValues(alpha: 0.3)),
              onPressed: _hasRange ? () => unawaited(_rangeToChart()) : null,
            ),
          ],
          if (_kind == _SpreadsheetKind.xlsx) ...[
            IconButton(
              tooltip: context.read<MindMapProvider>().t('tip.importCsv'),
              // 黄色は背景に埋もれて読みづらい (= ユーザー報告)。
              icon: const Icon(Icons.file_download_outlined,
                  color: Color(0xFF2E7D32)),
              onPressed: () => unawaited(_importCsvIntoWorkbook()),
            ),
          ],
          // AI 編集ボタン
          IconButton(
            tooltip: context.read<MindMapProvider>().t('doc.aiRewrite'),
            icon: _aiBusy
                ? const SizedBox(
                    width: 18,
                    height: 18,
                    child: CircularProgressIndicator(
                        strokeWidth: 2,
                        valueColor: AlwaysStoppedAnimation(Color(0xFFAB47BC))),
                  )
                : const Icon(Icons.auto_awesome_rounded,
                    color: Color(0xFFAB47BC)),
            onPressed: _aiBusy
                ? null
                : () => setState(() => _aiChatPanelOpen = !_aiChatPanelOpen),
          ),
          const SizedBox(width: 6),
          TextButton.icon(
            onPressed: _save,
            icon: const Icon(Icons.save_rounded, size: 18),
            label: Text(context.read<MindMapProvider>().t('btn.save')),
            style: TextButton.styleFrom(
              foregroundColor: Colors.white,
              backgroundColor: const Color(0xFF6C63FF),
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
            ),
          ),
          const SizedBox(width: 6),
          // ── ダウンロード (= ユーザー要望: xlsx にもダウンロードボタン) ──
          PopupMenuButton<String>(
            tooltip: context.read<MindMapProvider>().t('fsv.download'),
            icon: Icon(Icons.download_rounded, color: fg),
            color: dark ? const Color(0xFF22222E) : Colors.white,
            onSelected: (v) async {
              if (v == 'same') {
                await _downloadSheetCopy();
              } else if (v == 'csv') {
                await _downloadSheetAsCsv();
              } else if (v == 'pdf') {
                await _downloadSheetAsPdf();
              }
            },
            itemBuilder: (_) => [
              PopupMenuItem(
                value: 'same',
                child: Row(children: [
                  const Icon(Icons.table_chart_outlined,
                      size: 16, color: Color(0xFF2E7D32)),
                  const SizedBox(width: 8),
                  Text('このまま保存', style: TextStyle(color: fg, fontSize: 13)),
                ]),
              ),
              PopupMenuItem(
                value: 'csv',
                child: Row(children: [
                  const Icon(Icons.view_list_outlined,
                      size: 16, color: Color(0xFF7B1FA2)),
                  const SizedBox(width: 8),
                  Text('CSV として保存 (今のシート)',
                      style: TextStyle(color: fg, fontSize: 13)),
                ]),
              ),
              PopupMenuItem(
                value: 'pdf',
                child: Row(children: [
                  const Icon(Icons.picture_as_pdf_outlined,
                      size: 16, color: Color(0xFFFF6B6B)),
                  const SizedBox(width: 8),
                  Text('PDF に変換', style: TextStyle(color: fg, fontSize: 13)),
                ]),
              ),
            ],
          ),
          // ── 左 / 右に分割 (= ユーザー要望: xlsx にも分割ボタンを置いて、
          //    右分割を押したら 2 分割の右半分がこの表になるように) ──
          //    分割ペインの中で開いている時 (onSplitOpen == null) は出さない。
          if (widget.onSplitOpen != null) ...[
            IconButton(
              tooltip: context.read<MindMapProvider>().t('openStyle.splitLeft'),
              icon: _splitPanelIcon(_SplitIconFill.left,
                  color: const Color(0xFFFF6B6B), size: 19),
              // ★ onSplitOpen の実装側がビューアを閉じるので、 ここでは
              //   閉じない (二重に pop すると後ろの画面まで閉じてしまう)。
              onPressed: () => widget.onSplitOpen!(
                  _currentFilePath, _currentFileName,
                  isLeftPanel: true),
            ),
            IconButton(
              tooltip:
                  context.read<MindMapProvider>().t('openStyle.splitRight'),
              icon: _splitPanelIcon(_SplitIconFill.right,
                  color: const Color(0xFF2196F3), size: 19),
              onPressed: () => widget.onSplitOpen!(
                  _currentFilePath, _currentFileName,
                  isLeftPanel: false),
            ),
          ],
          // ── 使える関数の一覧 (= ユーザー要望: 端に置く) ──
          IconButton(
            tooltip: context.read<MindMapProvider>().t('tip.formulaHelp'),
            icon: const Icon(Icons.help_outline_rounded,
                color: Color(0xFF82AAFF)),
            onPressed: () => unawaited(_showFormulaHelp()),
          ),
          // Builder で × ボタン自身の context を取り、 未保存確認をその
          // すぐ近くに出す (= ユーザー要望)。
          Builder(
            builder: (btnCtx) => IconButton(
              tooltip: context.read<MindMapProvider>().t('btn.close'),
              icon: Icon(Icons.close_rounded, color: fg),
              onPressed: () async {
                if (await _confirmDiscard(anchor: btnCtx)) {
                  if (mounted) Navigator.of(context).pop();
                }
              },
            ),
          ),
        ],
      ),
    );
  }

  /// 数式バー (= ユーザー要望: Excel と同じく上部にセル参照 + 内容/数式)。
  /// 選択セルの生の値 (数式なら = から) を表示し、 ここで書いて Enter で
  /// そのセルへ反映できる。 バーに入力中は追従を止める。
  Widget _buildFormulaBar(bool dark, Color fg) {
    final hasCell = _rowCount > 0 && _selRow < _rowCount && _selCol < _colCount;
    final raw = hasCell ? _rows[_selRow][_selCol] : '';
    if (!_formulaFocus.hasFocus && _formulaCtrl.text != raw) {
      _formulaCtrl.text = raw;
    }
    return Container(
      height: 34,
      decoration: BoxDecoration(
        color: dark ? const Color(0xFF1E1E2A) : const Color(0xFFF6F6F2),
        border: Border(
          bottom: BorderSide(color: dark ? Colors.white10 : Colors.black12),
        ),
      ),
      child: Row(children: [
        // セル参照 (A1 形式)
        Container(
          width: 64,
          alignment: Alignment.center,
          decoration: BoxDecoration(
            border: Border(
              right:
                  BorderSide(color: dark ? Colors.white12 : Colors.black12),
            ),
          ),
          child: Text(
            hasCell ? '${_colLabel(_selCol)}${_selRow + 1}' : '',
            style: TextStyle(
                color: fg.withValues(alpha: 0.85),
                fontSize: 12.5,
                fontWeight: FontWeight.w700,
                fontFeatures: const [FontFeature.tabularFigures()]),
          ),
        ),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 8),
          child: Text('fx',
              style: TextStyle(
                  color: fg.withValues(alpha: 0.45),
                  fontSize: 12,
                  fontStyle: FontStyle.italic,
                  fontWeight: FontWeight.w700)),
        ),
        Expanded(
          // Esc はバーから抜けるだけにして、 画面を閉じる方へは流さない。
          child: Focus(
            onKeyEvent: (n, e) {
              if (e is KeyDownEvent &&
                  e.logicalKey == LogicalKeyboardKey.escape) {
                _keyFocus.requestFocus();
                return KeyEventResult.handled;
              }
              return KeyEventResult.ignored;
            },
            child: TextField(
            controller: _formulaCtrl,
            focusNode: _formulaFocus,
            enabled: hasCell,
            style: TextStyle(color: fg, fontSize: 13),
            cursorColor: const Color(0xFF6C63FF),
            decoration: InputDecoration(
              isDense: true,
              border: InputBorder.none,
              hintText: context.read<MindMapProvider>().t('sheet.formulaHint'),
              hintStyle:
                  TextStyle(color: fg.withValues(alpha: 0.3), fontSize: 12),
            ),
            // バーを触った時点でセル内の編集は確定しておく (二重編集を防ぐ)。
            onTap: _commitEdit,
            onSubmitted: _commitFormulaBar,
            ),
          ),
        ),
        // ── カーソルが挿入した表の中にある時は、 その表をそのまま
        //    マップへ出せるようにする (= ユーザー要望) ──
        if (!_hasRange && _tableAt(_selRow, _selCol) != null)
          _sheetRangeButton(
            icon: Icons.table_chart_rounded,
            color: const Color(0xFF26C6DA),
            label: 'この表をマップへ出す',
            onTap: () => _sendTableToMap(_tableAt(_selRow, _selCol)!),
          ),
        // ── 選択範囲を図/表にする (= ユーザー要望: .xlsx や .csv でセルの
        //    範囲を選んで図や表化)。 範囲を選んでいる時だけ出す。 ──
        if (_hasRange) ...[
          Builder(builder: (_) {
            final s = _range;
            final label = '${_colLabel(s.c1)}${s.r1 + 1}:'
                '${_colLabel(s.c2)}${s.r2 + 1}';
            return Padding(
              padding: const EdgeInsets.only(right: 6),
              child: Text(label,
                  style: TextStyle(
                      color: fg.withValues(alpha: 0.55), fontSize: 11)),
            );
          }),
          // csv / tsv は図や表をファイルに保存できないので出さない
          // (= ユーザー要望: 保存できないなら機能ごと外して)。
          if (_canHoldObjects) ...[
            _sheetRangeButton(
              icon: Icons.table_chart_rounded,
              color: const Color(0xFF26C6DA),
              label: context.read<MindMapProvider>().t('sheet.rangeToTable'),
              onTap: _rangeToTable,
            ),
            const SizedBox(width: 4),
            _sheetRangeButton(
              icon: Icons.bar_chart_rounded,
              color: const Color(0xFF9CCC65),
              label: context.read<MindMapProvider>().t('sheet.rangeToChart'),
              onTap: () {
                // ignore: discarded_futures
                _rangeToChart();
              },
            ),
          ],
        ],
        const SizedBox(width: 8),
      ]),
    );
  }

  /// 数式バー右側の「選択範囲を〜」 ボタン。
  Widget _sheetRangeButton({
    required IconData icon,
    required Color color,
    required String label,
    required VoidCallback onTap,
  }) {
    return Tooltip(
      message: label,
      child: InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(6),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
          decoration: BoxDecoration(
            color: color.withValues(alpha: 0.14),
            borderRadius: BorderRadius.circular(6),
            border: Border.all(color: color.withValues(alpha: 0.5)),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            Icon(icon, size: 14, color: color),
            const SizedBox(width: 4),
            Text(label,
                style: TextStyle(
                    color: color, fontSize: 11, fontWeight: FontWeight.w700)),
          ]),
        ),
      ),
    );
  }

  /// 数式バーの内容を選択セルへ反映する。
  void _commitFormulaBar(String v) {
    if (_rowCount > 0 && _selRow < _rowCount && _selCol < _colCount) {
      if (_rows[_selRow][_selCol] != v) {
        _pushUndo();
        setState(() {
          _rows[_selRow][_selCol] = v;
          _dirty = true;
        });
        _invalidateFormulaCache();
      }
    }
    _keyFocus.requestFocus();
  }

  Widget _buildSheetTabs(bool dark, Color fg) {
    return Container(
      height: 36,
      decoration: BoxDecoration(
        color: dark ? const Color(0xFF1E1E2A) : const Color(0xFFE8E8E2),
        // 下段配置になったので区切り線は上側に (= ユーザー要望: シートの
        // 切り替えは左下に)。
        border: Border(
          top: BorderSide(color: dark ? Colors.white10 : Colors.black12),
        ),
      ),
      child: ListView.builder(
        scrollDirection: Axis.horizontal,
        // 末尾に「+」 を 1 つ足す (= ユーザー要望: シート名の右端の + で
        // 新しいシートを追加できるように)。
        itemCount: _sheetNames.length + 1,
        itemBuilder: (_, i) {
          if (i == _sheetNames.length) {
            return InkWell(
              onTap: _addSheet,
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 14),
                alignment: Alignment.center,
                child: Icon(Icons.add_rounded,
                    size: 18, color: fg.withValues(alpha: 0.7)),
              ),
            );
          }
          final name = _sheetNames[i];
          final active = name == _activeSheet;
          return InkWell(
            onTap: () {
              _commitEdit();
              _invalidateFormulaCache();
              setState(() {
                _activeSheet = name;
                _selRow = 0;
                _selCol = 0;
              });
            },
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: active
                    ? (dark ? const Color(0xFF2A2A3E) : Colors.white)
                    : Colors.transparent,
                border: Border(
                  bottom: BorderSide(
                    color:
                        active ? const Color(0xFF6C63FF) : Colors.transparent,
                    width: 2,
                  ),
                ),
              ),
              child: Text(
                name,
                style: TextStyle(
                  color: active ? const Color(0xFF6C63FF) : fg,
                  fontSize: 13,
                  fontWeight: active ? FontWeight.w700 : FontWeight.w500,
                ),
              ),
            ),
          );
        },
      ),
    );
  }

  Widget _buildStatusBar(bool dark, Color fg) {
    return Container(
      height: 26,
      padding: const EdgeInsets.symmetric(horizontal: 12),
      decoration: BoxDecoration(
        color: dark ? const Color(0xFF22222E) : const Color(0xFFE0E0DA),
        border: Border(
          top: BorderSide(color: dark ? Colors.white12 : Colors.black12),
        ),
      ),
      alignment: Alignment.centerLeft,
      child: Text(
        '行: $_rowCount  列: $_colCount  '
        '選択: ${_colLabel(_selCol)}${_selRow + 1}',
        style: TextStyle(color: fg.withValues(alpha: 0.7), fontSize: 11),
      ),
    );
  }

  Widget _buildSheet(bool dark, Color fg) {
    return Focus(
      focusNode: _keyFocus,
      autofocus: true,
      onKeyEvent: _onKeyEvent,
      // ── 指 / マウスを離したら範囲ドラッグを終える (= ユーザー要望:
      //    ドラッグで範囲選択)。 セルの外で離しても確実に止まるよう、
      //    表全体で受ける。 ──
      child: Listener(
        onPointerUp: (_) {
          _dragSelecting = false;
          _stopDragAutoScroll();
        },
        onPointerCancel: (_) {
          _dragSelecting = false;
          _stopDragAutoScroll();
        },
        // なぞったまま端に来たら表を送る (= ユーザー要望)。
        onPointerMove: (e) {
          if (!_dragSelecting) return;
          _updateDragAutoScroll(e.position);
        },
        child: LayoutBuilder(
        builder: (ctx, cons) {
          final tableW = _rowHeaderWidth + _colCount * _cellWidth + _cellWidth;
          final tableH =
              _colHeaderHeight + _rowCount * _cellHeight + _cellHeight;
          // ── 左上配置 ──
          // SingleChildScrollView の child が viewport より小さいと、
          // 環境によっては中央寄せに見える事がある。 Align.topLeft で
          // 明示的に左上に固定して、 A1 セルが常に左上に来るようにする。
          return Align(
            alignment: Alignment.topLeft,
            child: Scrollbar(
              controller: _hScroll,
              child: SingleChildScrollView(
                controller: _hScroll,
                scrollDirection: Axis.horizontal,
                child: Scrollbar(
                  controller: _vScroll,
                  child: SingleChildScrollView(
                    controller: _vScroll,
                    scrollDirection: Axis.vertical,
                    child: SizedBox(
                      width: tableW,
                      height: tableH,
                      child: Stack(children: [
                        Column(
                          children: [
                            _buildColumnHeaderRow(dark, fg),
                            ...List.generate(
                                _rowCount, (r) => _buildDataRow(r, dark, fg)),
                            _buildAppendRow(dark, fg),
                          ],
                        ),
                        // ── 貼った図 (= ユーザー要望: 図の挿入)。
                        //    ドラッグで動かせる。 ✕ で消す。 ──
                        for (final im in _images) _buildSheetImage(im),
                      ]),
                    ),
                  ),
                ),
              ),
            ),
          );
        },
      ),
      ),
    );
  }

  /// シートに貼った図 1 個 (= ユーザー要望: 図の挿入)。
  /// 位置はセル番号から計算し、 ドラッグで動かす。 右下でサイズ変更。
  Widget _buildSheetImage(_SsImage im) {
    final left = _rowHeaderWidth + im.col * _cellWidth + im.dx;
    final top = _colHeaderHeight + im.row * _cellHeight + im.dy;
    return Positioned(
      left: left,
      top: top,
      width: im.width,
      height: im.height,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        // ── ドラッグで自由に動かす (= ユーザー要望: セル単位ではなく
        //    好きな位置へ)。 ずれが 1 セル分を超えたらセル番号側へ繰り上げて、
        //    xlsx に書き出した時も同じ場所に来るようにする。 ──
        onPanUpdate: (d) {
          setState(() {
            im.dx += d.delta.dx;
            im.dy += d.delta.dy;
            while (im.dx >= _cellWidth && im.col < _colCount - 1) {
              im.dx -= _cellWidth;
              im.col++;
            }
            while (im.dx < 0 && im.col > 0) {
              im.dx += _cellWidth;
              im.col--;
            }
            while (im.dy >= _cellHeight && im.row < _rowCount - 1) {
              im.dy -= _cellHeight;
              im.row++;
            }
            while (im.dy < 0 && im.row > 0) {
              im.dy += _cellHeight;
              im.row--;
            }
            if (im.col <= 0 && im.dx < 0) im.dx = 0;
            if (im.row <= 0 && im.dy < 0) im.dy = 0;
            _dirty = true;
          });
        },
        child: Stack(clipBehavior: Clip.none, children: [
          Positioned.fill(
            child: Container(
              decoration: BoxDecoration(
                border: Border.all(
                    color: const Color(0xFF4FC3F7).withValues(alpha: 0.6)),
              ),
              child: Image.memory(im.bytes, fit: BoxFit.fill),
            ),
          ),
          // 右下: 大きさを変える
          Positioned(
            right: -6,
            bottom: -6,
            child: GestureDetector(
              behavior: HitTestBehavior.opaque,
              onPanUpdate: (d) {
                setState(() {
                  im.width = math.max(40.0, im.width + d.delta.dx);
                  im.height = math.max(30.0, im.height + d.delta.dy);
                  _dirty = true;
                });
              },
              child: Container(
                width: 13,
                height: 13,
                decoration: BoxDecoration(
                  color: const Color(0xFF4FC3F7),
                  borderRadius: BorderRadius.circular(3),
                  border: Border.all(color: Colors.white, width: 1.2),
                ),
              ),
            ),
          ),
          // 図そのものを押したらメニュー (= ユーザー要望: 置いた物を
          //   押してマップに転送できるように)。
          Positioned.fill(
            child: GestureDetector(
              behavior: HitTestBehavior.translucent,
              onTapUp: (d) {
                // グラフは押した場所で開く物を変える (= ユーザー要望:
                // 軸をクリックして範囲や最大/最小を変えられるように)。
                if (im.chart != null) {
                  final w = im.width <= 0 ? 1.0 : im.width;
                  final h = im.height <= 0 ? 1.0 : im.height;
                  final fx = d.localPosition.dx / w;
                  final fy = d.localPosition.dy / h;
                  if (fx < 0.18) {
                    // 左端 = たての軸
                    unawaited(_editChartImage(im, focus: 'y'));
                    return;
                  }
                  if (fy > 0.82) {
                    // 下端 = よこの軸 / 凡例
                    unawaited(_editChartImage(im, focus: 'x'));
                    return;
                  }
                  if (fy < 0.16) {
                    // 上端 = 題名
                    unawaited(_editChartImage(im, focus: 'title'));
                    return;
                  }
                }
                unawaited(_showSheetImageMenu(im, d.globalPosition));
              },
            ),
          ),
        ]),
      ),
    );
  }

  /// 置いてあるグラフを作り直す (= ユーザー要望: 題名・凡例・軸を後から)。
  ///
  /// [focus] は最初に見せたい所 ('y' = たての軸 / 'x' = よこの軸と凡例 /
  /// 'title' = 題名)。 元にした範囲を覚えているので、 セルの値が変わって
  /// いれば新しい値で描き直される。
  Future<void> _editChartImage(_SsImage im, {String focus = 'all'}) async {
    final meta = im.chart;
    if (meta == null) return;
    // 覚えている設定を編集欄の初期値にする。
    _chartTitle = '${meta['title'] ?? ''}';
    _chartYMin = '${meta['yMin'] ?? ''}';
    _chartYMax = '${meta['yMax'] ?? ''}';
    _chartYStep = '${meta['yStep'] ?? ''}';
    _chartXFrom = '${meta['xFrom'] ?? ''}';
    _chartXTo = '${meta['xTo'] ?? ''}';
    _chartLegend = meta['legend'] != false;
    if (!await _showChartSettings(focus: focus) || !mounted) return;
    // 元の範囲からセルを取り直す (値が変わっていれば新しい値で描く)。
    final r1 = (meta['r1'] as num?)?.toInt() ?? 0;
    final c1 = (meta['c1'] as num?)?.toInt() ?? 0;
    final r2 = (meta['r2'] as num?)?.toInt() ?? r1;
    final c2 = (meta['c2'] as num?)?.toInt() ?? c1;
    final cells = <List<String>>[];
    for (var r = r1; r <= r2 && r < _rowCount; r++) {
      final row = <String>[];
      for (var c = c1; c <= c2 && c < _colCount; c++) {
        row.add(_displayValue(r, c));
      }
      cells.add(row);
    }
    if (cells.isEmpty) return;
    var useCells = cells;
    // よこの軸の範囲 (= ユーザー要望: 何番目から何番目まで) を切り出す。
    final xFrom = int.tryParse(_chartXFrom);
    final xTo = int.tryParse(_chartXTo);
    if (xFrom != null || xTo != null) {
      // 1 行目が見出しなら残す。
      final head = useCells.isNotEmpty &&
              useCells.first.skip(1).every((v) =>
                  double.tryParse(v.trim().replaceAll(',', '')) == null)
          ? useCells.first
          : null;
      final body = head == null ? useCells : useCells.sublist(1);
      final a = ((xFrom ?? 1) - 1).clamp(0, body.isEmpty ? 0 : body.length - 1);
      final b = (xTo == null ? body.length : xTo).clamp(a + 1, body.length);
      final picked = body.sublist(a, b);
      useCells = [if (head != null) head, ...picked];
    }
    final provider = context.read<MindMapProvider>();
    final path = await provider.renderChartPngFromCells(useCells,
        title: _chartTitle,
        yMin: double.tryParse(_chartYMin),
        yMax: double.tryParse(_chartYMax),
        yStep: double.tryParse(_chartYStep),
        showLegend: _chartLegend);
    if (path == null || !mounted) {
      if (mounted) {
        _sheetToast(provider.t('sheet.rangeNeedsNumbers'), error: true);
      }
      return;
    }
    Uint8List? bytes;
    try {
      bytes = await File(path).readAsBytes();
    } catch (_) {}
    if (bytes == null || !mounted) return;
    _pushUndo();
    setState(() {
      final idx = _images.indexOf(im);
      if (idx >= 0) {
        _images[idx] = _SsImage(
          bytes: bytes!,
          ext: 'png',
          mediaName: 'hnchart_${DateTime.now().millisecondsSinceEpoch}.png',
          row: im.row,
          col: im.col,
          dx: im.dx,
          dy: im.dy,
          width: im.width,
          height: im.height,
          chart: {
            ...meta,
            'title': _chartTitle,
            'yMin': _chartYMin,
            'yMax': _chartYMax,
            'yStep': _chartYStep,
            'xFrom': _chartXFrom,
            'xTo': _chartXTo,
            'legend': _chartLegend,
          },
        );
      }
      _dirty = true;
    });
    _sheetToast('✓ グラフを作り直しました');
  }

  /// シートに置いた図を押した時のメニュー (= ユーザー要望)。
  Future<void> _showSheetImageMenu(_SsImage im, Offset globalPos) async {
    final box = Overlay.of(context).context.findRenderObject() as RenderBox?;
    if (box == null) return;
    final sel = await showMenu<String>(
      context: context,
      color: const Color(0xFF1E1E2E),
      position: RelativeRect.fromRect(
          globalPos & const Size(1, 1), Offset.zero & box.size),
      items: [
        if (im.chart != null)
          const PopupMenuItem<String>(
            value: 'chart',
            height: 36,
            child: Row(children: [
              Icon(Icons.tune_rounded, size: 15, color: Color(0xFF7CB342)),
              SizedBox(width: 8),
              Text('グラフの設定を変える',
                  style: TextStyle(color: Colors.white, fontSize: 12.5)),
            ]),
          ),
        const PopupMenuItem<String>(
          value: 'map',
          height: 36,
          child: Row(children: [
            Icon(Icons.open_in_new_rounded, size: 15, color: Color(0xFF6C63FF)),
            SizedBox(width: 8),
            Text('マップに出す',
                style: TextStyle(color: Colors.white, fontSize: 12.5)),
          ]),
        ),
        const PopupMenuItem<String>(
          value: 'reset',
          height: 36,
          child: Row(children: [
            Icon(Icons.aspect_ratio_rounded, size: 15, color: Color(0xFF4FC3F7)),
            SizedBox(width: 8),
            Text('大きさを戻す',
                style: TextStyle(color: Colors.white, fontSize: 12.5)),
          ]),
        ),
        const PopupMenuItem<String>(
          value: 'delete',
          height: 36,
          child: Row(children: [
            Icon(Icons.delete_outline_rounded,
                size: 15, color: Color(0xFFE57373)),
            SizedBox(width: 8),
            Text('消す',
                style: TextStyle(color: Color(0xFFE57373), fontSize: 12.5)),
          ]),
        ),
      ],
    );
    if (sel == null || !mounted) return;
    if (sel == 'chart') {
      await _editChartImage(im);
    } else if (sel == 'map') {
      await _sendImageToMap(im);
    } else if (sel == 'reset') {
      setState(() {
        im.width = 360;
        im.height = 270;
        _dirty = true;
      });
    } else if (sel == 'delete') {
      _pushUndo();
      setState(() {
        _images.remove(im);
        _dirty = true;
      });
    }
  }

  Widget _buildColumnHeaderRow(bool dark, Color fg) {
    return SizedBox(
      height: _colHeaderHeight,
      child: Row(
        children: [
          Container(
            width: _rowHeaderWidth,
            height: _colHeaderHeight,
            decoration: _headerDeco(dark),
          ),
          ...List.generate(
            _colCount,
            (c) => _SsColumnHeaderCell(
              width: _cellWidth,
              height: _colHeaderHeight,
              label: _colLabel(c),
              selected: c == _selCol,
              dark: dark,
              onTap: () {
                _commitEdit();
                setState(() => _selCol = c);
              },
              onInsertLeft: () => _insertColumn(c),
              onInsertRight: () => _insertColumn(c + 1),
              onRemove: () => _removeColumn(c),
              onClear: () {
                for (int r = 0; r < _rowCount; r++) {
                  _rows[r][c] = '';
                }
                setState(() => _dirty = true);
              },
            ),
          ),
          // ── 列追加ボタン ──
          // 左クリック: 1 列追加 (= 既存挙動)
          // 右クリック / 長押し: 「N 列追加」 ダイアログ
          GestureDetector(
            onSecondaryTap: () => _showBulkInsertDialog(isRow: false),
            child: InkWell(
              onTap: () => _insertColumn(_colCount),
              onLongPress: () => _showBulkInsertDialog(isRow: false),
              child: Container(
                width: _cellWidth,
                height: _colHeaderHeight,
                decoration: _headerDeco(dark),
                alignment: Alignment.center,
                child:
                    Icon(Icons.add, size: 16, color: fg.withValues(alpha: 0.6)),
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildDataRow(int r, bool dark, Color fg) {
    return SizedBox(
      height: _cellHeight,
      child: Row(
        children: [
          _SsRowHeaderCell(
            width: _rowHeaderWidth,
            height: _cellHeight,
            index: r,
            selected: r == _selRow,
            dark: dark,
            onTap: () {
              _commitEdit();
              setState(() => _selRow = r);
            },
            onInsertAbove: () => _insertRow(r),
            onInsertBelow: () => _insertRow(r + 1),
            onRemove: () => _removeRow(r),
            onClear: () {
              for (int c = 0; c < _colCount; c++) {
                _rows[r][c] = '';
              }
              setState(() => _dirty = true);
            },
          ),
          ...List.generate(_colCount, (c) {
            final editing = _editingRow == r && _editingCol == c;
            final selected = _selRow == r && _selCol == c;
            // 数式セルは編集中以外は評価結果を表示
            final cellValue = editing ? _rows[r][c] : _displayValue(r, c);
            // 元の値が = で始まり、表示モード ON の時は数式マーカー
            final isFormula =
                !editing && _showFormulaResults && _rows[r][c].startsWith('=');
            final tbl = _tableAt(r, c);
            // オートフィルの取っ手は、 選択 (範囲) の右下のセルに出す。
            final rg = _hasRange
                ? _range
                : (r1: _selRow, c1: _selCol, r2: _selRow, c2: _selCol);
            final isFillHandleCell = r == rg.r2 && c == rg.c2;
            // ドラッグ中に「ここまで入りますよ」 と示す枠。
            final inFillPreview = _fillToRow != null &&
                _fillToCol != null &&
                r >= rg.r1 &&
                c >= rg.c1 &&
                r <= math.max(rg.r2, _fillToRow!) &&
                c <= math.max(rg.c2, _fillToCol!) &&
                (r > rg.r2 || c > rg.c2);
            return _SsDataCell(
              width: _cellWidth,
              height: _cellHeight,
              value: cellValue,
              isFormula: isFormula,
              editing: editing,
              selected: selected,
              dark: dark,
              // オートフィル (= ユーザー要望)。
              showFillHandle: isFillHandleCell && _editingRow == null,
              inFillPreview: inFillPreview,
              onFillDrag: (delta) {
                setState(() {
                  final baseX = (rg.c2 + 1) * _cellWidth;
                  final baseY = (rg.r2 + 1) * _cellHeight;
                  final curX = (_fillToCol == null
                          ? baseX
                          : (_fillToCol! + 1) * _cellWidth) +
                      delta.dx;
                  final curY = (_fillToRow == null
                          ? baseY
                          : (_fillToRow! + 1) * _cellHeight) +
                      delta.dy;
                  _fillToCol = (curX / _cellWidth).round() - 1;
                  _fillToRow = (curY / _cellHeight).round() - 1;
                  if (_fillToCol! < rg.c2) _fillToCol = rg.c2;
                  if (_fillToRow! < rg.r2) _fillToRow = rg.r2;
                  // 伸ばせるのは 1 方向だけ (Excel と同じ)。
                  if (_fillToRow! - rg.r2 >= _fillToCol! - rg.c2) {
                    _fillToCol = rg.c2;
                  } else {
                    _fillToRow = rg.r2;
                  }
                });
              },
              onFillEnd: _applyAutoFill,
              // 表 (= ユーザー要望: 表の挿入) の見た目。
              tableFill: _tableFillAt(r, c),
              tableLine: tbl?.line,
              tableHeaderFont: (tbl != null && r == tbl.row)
                  ? tbl.headerFont
                  : null,
              controller: editing ? _editCtrl : null,
              focusNode: editing ? _editFocus : null,
              inRange: _hasRange && _inRange(r, c),
              onTap: () {
                // ★ キー操作の受け口に焦点を戻す (= ユーザー報告: Delete /
                //   Backspace / F2 が効かない)。 ツールバーや数式バーを触ると
                //   焦点が外れたままになり、 _onKeyEvent にキーが届かない。
                if (!_keyFocus.hasFocus) _keyFocus.requestFocus();
                // Shift + クリックで範囲選択 (= ユーザー要望: 範囲を選んで
                //   図や表にできるように)。 ふつうのクリックは 1 セル選択。
                final shift = HardwareKeyboard.instance.isShiftPressed;
                if (shift) {
                  _commitEdit();
                  setState(() {
                    _ensureRangeAnchor();
                    _selRow = r;
                    _selCol = c;
                  });
                  return;
                }
                if (selected && !_hasRange) {
                  _beginEdit(r, c);
                } else {
                  _commitEdit();
                  setState(() {
                    _resetRangeAnchor();
                    _selRow = r;
                    _selCol = c;
                  });
                }
              },
              // ── ドラッグで範囲選択 (= ユーザー要望) ──
              //    押した所を起点にして、 なぞったセルまでを範囲にする。
              onPointerDown: () {
                if (!_keyFocus.hasFocus) _keyFocus.requestFocus();
                if (_editingRow != null) return;
                _dragSelecting = true;
                _dragAnchorRow = r;
                _dragAnchorCol = c;
              },
              onPointerEnter: () {
                if (!_dragSelecting) return;
                final ar = _dragAnchorRow;
                final ac = _dragAnchorCol;
                if (ar == null || ac == null) return;
                if (_selRow == r && _selCol == c && _hasRange) return;
                _commitEdit();
                setState(() {
                  _rangeAnchorRow = ar;
                  _rangeAnchorCol = ac;
                  _selRow = r;
                  _selCol = c;
                });
              },
              onDoubleTap: () => _beginEdit(r, c),
              onSubmitted: () {
                _commitEdit();
                if (_selRow + 1 < _rowCount) {
                  setState(() => _selRow += 1);
                }
              },
              onEscape: _cancelEdit,
              onTabNext: () {
                _commitEdit();
                if (_selCol + 1 < _colCount) {
                  setState(() => _selCol += 1);
                }
              },
              onTabPrev: () {
                _commitEdit();
                if (_selCol - 1 >= 0) {
                  setState(() => _selCol -= 1);
                }
              },
            );
          }),
          Container(width: _cellWidth, height: _cellHeight),
        ],
      ),
    );
  }

  Widget _buildAppendRow(bool dark, Color fg) {
    return SizedBox(
      height: _cellHeight,
      child: Row(
        children: [
          // ── 行追加ボタン ──
          // 左クリック: 1 行追加 (= 既存挙動)
          // 右クリック / 長押し: 「N 行追加」 ダイアログ
          GestureDetector(
            onSecondaryTap: () => _showBulkInsertDialog(isRow: true),
            child: InkWell(
              onTap: () => _insertRow(_rowCount),
              onLongPress: () => _showBulkInsertDialog(isRow: true),
              child: Container(
                width: _rowHeaderWidth,
                height: _cellHeight,
                decoration: _headerDeco(dark),
                alignment: Alignment.center,
                child:
                    Icon(Icons.add, size: 16, color: fg.withValues(alpha: 0.6)),
              ),
            ),
          ),
          Container(
            width: _colCount * _cellWidth + _cellWidth,
            height: _cellHeight,
            decoration: BoxDecoration(
              color: dark ? const Color(0xFF1A1A24) : const Color(0xFFF5F5F0),
            ),
          ),
        ],
      ),
    );
  }

  /// 「+」 ボタン右クリック / 長押し時の「N 行/列を一気に追加」 ダイアログ。
  /// isRow=true なら行追加、 false なら列追加。
  Future<void> _showBulkInsertDialog({required bool isRow}) async {
    final ctrl = TextEditingController(text: '10');
    final result = await showDialog<int>(
      context: context,
      builder: (dctx) {
        return StatefulBuilder(builder: (sctx, setS) {
          int? parseV() {
            final s = ctrl.text.trim();
            if (s.isEmpty) return null;
            final n = int.tryParse(s);
            if (n == null || n <= 0 || n > 1000) return null;
            return n;
          }

          return AlertDialog(
            backgroundColor: const Color(0xFF22222E),
            title: Text(isRow ? '行を追加' : '列を追加',
                style: const TextStyle(color: Colors.white)),
            content: SizedBox(
              width: 260,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    isRow ? '末尾に追加する行数 (1〜1000)' : '末尾に追加する列数 (1〜1000)',
                    style: const TextStyle(color: Colors.white70, fontSize: 12),
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: ctrl,
                    autofocus: true,
                    keyboardType: TextInputType.number,
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 22,
                        fontWeight: FontWeight.w700),
                    decoration: InputDecoration(
                      filled: true,
                      fillColor: const Color(0xFF1A1A24),
                      contentPadding: const EdgeInsets.symmetric(
                          horizontal: 12, vertical: 10),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(6),
                      ),
                      suffixText: isRow ? '行' : '列',
                      suffixStyle: const TextStyle(color: Colors.white54),
                    ),
                    onChanged: (_) => setS(() {}),
                    onSubmitted: (_) {
                      final v = parseV();
                      if (v != null) Navigator.of(dctx).pop(v);
                    },
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dctx).pop(),
                child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                    style: const TextStyle(color: Colors.white54)),
              ),
              FilledButton.icon(
                onPressed: parseV() == null
                    ? null
                    : () => Navigator.of(dctx).pop(parseV()),
                icon: const Icon(Icons.add_rounded, size: 16),
                label: Text(context.read<MindMapProvider>().t('btn.add')),
                style: FilledButton.styleFrom(
                  backgroundColor: const Color(0xFF43B97F),
                  foregroundColor: Colors.white,
                ),
              ),
            ],
          );
        });
      },
    );
    ctrl.dispose();
    if (result == null) return;
    // 一気に N 個追加 (= ループで insertRow / insertColumn を呼ぶ)
    if (isRow) {
      for (int i = 0; i < result; i++) {
        _insertRow(_rowCount);
      }
    } else {
      for (int i = 0; i < result; i++) {
        _insertColumn(_colCount);
      }
    }
  }

  BoxDecoration _headerDeco(bool dark) {
    return BoxDecoration(
      color: dark ? const Color(0xFF2A2A3E) : const Color(0xFFD0D0CA),
      border: Border(
        right: BorderSide(color: dark ? Colors.white10 : Colors.black12),
        bottom: BorderSide(color: dark ? Colors.white10 : Colors.black12),
      ),
    );
  }

  static String _colLabel(int c) {
    if (c < 0) return '';
    var n = c;
    final sb = StringBuffer();
    while (true) {
      sb.write(String.fromCharCode(65 + (n % 26)));
      n = n ~/ 26 - 1;
      if (n < 0) break;
    }
    return sb.toString().split('').reversed.join();
  }
}

class _SsDataCell extends StatelessWidget {
  final double width;
  final double height;
  final String value;
  final bool editing;
  final bool selected;
  final bool dark;

  /// 数式 (= で始まる) を評価表示中かどうか。 true ならフォントを少し
  /// 区別 (青系 + italic) して 「これは数式の結果」 と分かるようにする。
  final bool isFormula;

  /// 範囲選択に含まれているか (= ユーザー要望: 範囲を選んで図や表に)。
  final bool inRange;
  final TextEditingController? controller;
  final FocusNode? focusNode;
  final VoidCallback onTap;
  final VoidCallback onDoubleTap;
  final VoidCallback onSubmitted;
  final VoidCallback onEscape;
  final VoidCallback onTabNext;
  final VoidCallback onTabPrev;

  /// マウスのボタンを押した瞬間 (= 範囲ドラッグの起点)。
  /// Listener なのでジェスチャの取り合いにならず、 指でのスクロールは
  /// そのまま効く (= ユーザー要望: ドラッグで範囲選択)。
  final VoidCallback? onPointerDown;

  /// ボタンを押したままこのセルに入ってきた時 (= 範囲を伸ばす)。
  final VoidCallback? onPointerEnter;

  /// オートフィルの取っ手を出すか (= 選択の右下のセル)。
  final bool showFillHandle;

  /// オートフィルのドラッグ中で、 このセルが埋まる予定か。
  final bool inFillPreview;

  /// 取っ手をドラッグした量 / 離した合図。
  final void Function(Offset delta)? onFillDrag;
  final VoidCallback? onFillEnd;

  /// 表 (= ユーザー要望: 表の挿入) の見た目。 いずれも RGB 24bit、
  /// null なら普通のセルとして描く。
  final int? tableFill;
  final int? tableLine;
  final int? tableHeaderFont;

  const _SsDataCell({
    required this.width,
    required this.height,
    required this.value,
    required this.editing,
    required this.selected,
    required this.dark,
    required this.onTap,
    required this.onDoubleTap,
    required this.onSubmitted,
    required this.onEscape,
    required this.onTabNext,
    required this.onTabPrev,
    this.isFormula = false,
    this.inRange = false,
    this.controller,
    this.focusNode,
    this.onPointerDown,
    this.onPointerEnter,
    this.tableFill,
    this.tableLine,
    this.tableHeaderFont,
    this.showFillHandle = false,
    this.inFillPreview = false,
    this.onFillDrag,
    this.onFillEnd,
  });

  @override
  Widget build(BuildContext context) {
    final bg = editing
        ? (dark ? const Color(0xFF2D2D40) : Colors.white)
        : selected
            ? (dark
                ? const Color(0xFF3A3A55).withValues(alpha: 0.55)
                : const Color(0xFFD0D8FF).withValues(alpha: 0.55))
            // 範囲選択の中は薄く塗る (= ユーザー要望: 範囲が分かるように)。
            : inRange
                ? (dark
                    ? const Color(0xFF3A3A55).withValues(alpha: 0.30)
                    : const Color(0xFFD0D8FF).withValues(alpha: 0.35))
                // 表の塗り (= ユーザー要望: 表の挿入)。
                : tableFill != null
                    ? Color(0xFF000000 | tableFill!)
                    : (dark ? const Color(0xFF1A1A24) : Colors.white);
    final fg = tableHeaderFont != null
        ? Color(0xFF000000 | tableHeaderFont!)
        : (dark ? Colors.white : const Color(0xFF1A1A24));
    final borderColor = selected
        ? const Color(0xFF6C63FF)
        : tableLine != null
            ? Color(0xFF000000 | tableLine!)
            : (dark ? Colors.white10 : Colors.black12);

    return MouseRegion(
      onEnter: onPointerEnter == null ? null : (_) => onPointerEnter!.call(),
      child: Listener(
        onPointerDown:
            onPointerDown == null ? null : (_) => onPointerDown!.call(),
        child: Stack(clipBehavior: Clip.none, children: [
          GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: onTap,
      onDoubleTap: onDoubleTap,
      child: Container(
        width: width,
        height: height,
        decoration: BoxDecoration(
          color: bg,
          // オートフィルで埋まる予定の所は枠を出す (= ユーザー要望)。
          border: inFillPreview
              ? Border.all(
                  color: const Color(0xFF6C63FF).withValues(alpha: 0.7),
                  width: 1)
              : Border.all(color: borderColor, width: selected ? 1.5 : 0.5),
        ),
        padding: const EdgeInsets.symmetric(horizontal: 6),
        alignment: Alignment.centerLeft,
        child: editing
            ? KeyboardListener(
                focusNode: FocusNode(skipTraversal: true),
                onKeyEvent: (event) {
                  if (event is! KeyDownEvent) return;
                  final shift = HardwareKeyboard.instance.isShiftPressed;
                  if (event.logicalKey == LogicalKeyboardKey.escape) {
                    onEscape();
                  } else if (event.logicalKey == LogicalKeyboardKey.tab) {
                    if (shift) {
                      onTabPrev();
                    } else {
                      onTabNext();
                    }
                  }
                },
                child: TextField(
                  controller: controller,
                  focusNode: focusNode,
                  autofocus: true,
                  style: TextStyle(color: fg, fontSize: 13),
                  decoration: const InputDecoration(
                    border: InputBorder.none,
                    isDense: true,
                    contentPadding: EdgeInsets.zero,
                  ),
                  onSubmitted: (_) => onSubmitted(),
                ),
              )
            : Text(value,
                style: TextStyle(
                  color: isFormula
                      ? (dark
                          ? const Color(0xFF82AAFF)
                          : const Color(0xFF1565C0))
                      : fg,
                  fontSize: 13,
                  fontStyle: isFormula ? FontStyle.italic : FontStyle.normal,
                ),
                maxLines: 1,
                overflow: TextOverflow.ellipsis),
      ),
          ), // GestureDetector
          // ── オートフィルの取っ手 (= ユーザー要望) ──
          //    右下の小さな四角。 下 / 右へ引っ張ると連番やコピーで埋まる。
          if (showFillHandle)
            Positioned(
              right: -3,
              bottom: -3,
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onPanUpdate: (d) => onFillDrag?.call(d.delta),
                onPanEnd: (_) => onFillEnd?.call(),
                onPanCancel: () => onFillEnd?.call(),
                child: MouseRegion(
                  cursor: SystemMouseCursors.precise,
                  child: Container(
                    width: 9,
                    height: 9,
                    decoration: BoxDecoration(
                      color: const Color(0xFF6C63FF),
                      border: Border.all(color: Colors.white, width: 1),
                    ),
                  ),
                ),
              ),
            ),
        ]), // Stack
      ), // Listener
    );
  }
}

class _SsColumnHeaderCell extends StatelessWidget {
  final double width;
  final double height;
  final String label;
  final bool selected;
  final bool dark;
  final VoidCallback onTap;
  final VoidCallback onInsertLeft;
  final VoidCallback onInsertRight;
  final VoidCallback onRemove;
  final VoidCallback onClear;

  const _SsColumnHeaderCell({
    required this.width,
    required this.height,
    required this.label,
    required this.selected,
    required this.dark,
    required this.onTap,
    required this.onInsertLeft,
    required this.onInsertRight,
    required this.onRemove,
    required this.onClear,
  });

  @override
  Widget build(BuildContext context) {
    final fg = dark ? Colors.white : const Color(0xFF1A1A24);
    final bg = selected
        ? const Color(0xFF6C63FF).withValues(alpha: 0.35)
        : (dark ? const Color(0xFF2A2A3E) : const Color(0xFFD0D0CA));
    return GestureDetector(
      onTap: onTap,
      onSecondaryTapDown: (d) => _showMenu(context, d.globalPosition),
      onLongPressStart: (d) => _showMenu(context, d.globalPosition),
      child: Container(
        width: width,
        height: height,
        decoration: BoxDecoration(
          color: bg,
          border: Border(
            right: BorderSide(color: dark ? Colors.white10 : Colors.black12),
            bottom: BorderSide(color: dark ? Colors.white10 : Colors.black12),
          ),
        ),
        alignment: Alignment.center,
        child: Text(label,
            style: TextStyle(
                color: fg, fontSize: 11, fontWeight: FontWeight.w700)),
      ),
    );
  }

  void _showMenu(BuildContext context, Offset pos) async {
    final sel = await showMenu<String>(
      context: context,
      position: RelativeRect.fromLTRB(pos.dx, pos.dy, pos.dx, pos.dy),
      items: [
        PopupMenuItem(
            value: 'insertLeft',
            child: Text(context.read<MindMapProvider>().t('ss.insertColLeft'))),
        PopupMenuItem(
            value: 'insertRight',
            child:
                Text(context.read<MindMapProvider>().t('ss.insertColRight'))),
        PopupMenuItem(
            value: 'clear',
            child: Text(context.read<MindMapProvider>().t('ss.clearColumn'))),
        PopupMenuItem(
            value: 'remove',
            child: Text(context.read<MindMapProvider>().t('ss.deleteColumn'))),
      ],
    );
    switch (sel) {
      case 'insertLeft':
        onInsertLeft();
        break;
      case 'insertRight':
        onInsertRight();
        break;
      case 'clear':
        onClear();
        break;
      case 'remove':
        onRemove();
        break;
    }
  }
}

