    );
    if (picked == null) return;
    // pt → 1/100 pt
    _applyRunStyleToSelection(
      shape,
      shape.text,
      start,
      end,
      newFontSize: picked * 100,
      newFontFamily: null,
    );
    if (mounted) {
      setState(() {
        _slides[_currentIndex].dirty = true;
      });
    }
  }

  /// 現在選択中の表グループに対する選択枠 + リサイズハンドルを描画。
  /// `_selectedTableGroupId == null` なら何も描画しない。
  ///
  /// PowerPoint 風に、 表全体の bounding box の 4 隅 + 4 辺に小さな
  /// ハンドルを表示し、 ドラッグで全セルを比例リサイズできる。
  /// ユーザー要望: 「表の大きさ自体を powerpoint みたいに変えられる
  /// ようにして」 への対応。
  List<Widget> _buildTableGroupSelectionWidgets(
      double canvasW, double canvasH) {
    final groupId = _selectedTableGroupId;
    if (groupId == null) return const <Widget>[];
    if (_currentIndex < 0 || _currentIndex >= _slides.length) {
      return const <Widget>[];
    }
    final slide = _slides[_currentIndex];
    final cells =
        slide.textShapes.where((s) => s.tableGroupId == groupId).toList();
    if (cells.isEmpty) return const <Widget>[];

    // bounding box を EMU で計算
    int minX = cells.first.offX;
    int minY = cells.first.offY;
    int maxX = cells.first.offX + cells.first.extCx;
    int maxY = cells.first.offY + cells.first.extCy;
    for (final c in cells) {
      if (c.offX < minX) minX = c.offX;
      if (c.offY < minY) minY = c.offY;
      if (c.offX + c.extCx > maxX) maxX = c.offX + c.extCx;
      if (c.offY + c.extCy > maxY) maxY = c.offY + c.extCy;
    }
    final bboxW = maxX - minX;
    final bboxH = maxY - minY;
    if (bboxW <= 0 || bboxH <= 0) return const <Widget>[];

    // ピクセル座標に変換
    final left = (minX / _slideWidthEmu) * canvasW;
    final top = (minY / _slideHeightEmu) * canvasH;
    final width = (bboxW / _slideWidthEmu) * canvasW;
    final height = (bboxH / _slideHeightEmu) * canvasH;
    const handleSize = 10.0;
    const half = handleSize / 2;

    // ── 比例リサイズの実装 ──
    // ハンドルドラッグ時、 bounding box の対応する辺/隅を動かして、
    // 各セルを bounding box 内での相対位置に基づき比例計算で再配置する。
    //
    // 各セルの新位置:
    //   relX = (oldX - oldMinX) / oldW
    //   relY = (oldY - oldMinY) / oldH
    //   newCellX = newMinX + relX * newW
    //   newCellY = newMinY + relY * newH
    // 同じく extCx, extCy も比例計算。
    void applyResize(int newMinX, int newMinY, int newMaxX, int newMaxY) {
      // 制限: スライド範囲内、 最小サイズ 1cm (= 360000 EMU)
      newMinX = newMinX.clamp(0, _slideWidthEmu - 360000);
      newMinY = newMinY.clamp(0, _slideHeightEmu - 360000);
      newMaxX = newMaxX.clamp(newMinX + 360000, _slideWidthEmu);
      newMaxY = newMaxY.clamp(newMinY + 360000, _slideHeightEmu);
      final newW = newMaxX - newMinX;
      final newH = newMaxY - newMinY;
      final oldW = bboxW;
      final oldH = bboxH;
      setState(() {
        for (final c in cells) {
          final relX = (c.offX - minX) / oldW;
          final relY = (c.offY - minY) / oldH;
          final relW = c.extCx / oldW;
          final relH = c.extCy / oldH;
          c.offX = (newMinX + relX * newW).round();
          c.offY = (newMinY + relY * newH).round();
          c.extCx = (relW * newW).round().clamp(1, _slideWidthEmu);
          c.extCy = (relH * newH).round().clamp(1, _slideHeightEmu);
        }
        slide.dirty = true;
      });
    }

    // px → EMU 変換ヘルパー
    int pxToEmuX(double px) => (px / canvasW * _slideWidthEmu).round();
    int pxToEmuY(double px) => (px / canvasH * _slideHeightEmu).round();

    // ハンドル 1 個分を生成。 [dx, dy] は「どの辺/隅か」 のフラグ:
    //   -1 = その辺を動かす (左/上)、 +1 = その辺を動かす (右/下)、
    //    0 = その軸は動かさない。
    Widget makeHandle(double x, double y, int dx, int dy, MouseCursor cursor) {
      return Positioned(
        left: x - half,
        top: y - half,
        width: handleSize,
        height: handleSize,
        child: MouseRegion(
          cursor: cursor,
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onPanUpdate: (details) {
              final dxEmu = pxToEmuX(details.delta.dx);
              final dyEmu = pxToEmuY(details.delta.dy);
              int newMinX = minX;
              int newMinY = minY;
              int newMaxX = maxX;
              int newMaxY = maxY;
              if (dx == -1) newMinX += dxEmu;
              if (dx == 1) newMaxX += dxEmu;
              if (dy == -1) newMinY += dyEmu;
              if (dy == 1) newMaxY += dyEmu;
              applyResize(newMinX, newMinY, newMaxX, newMaxY);
            },
            child: Container(
              decoration: BoxDecoration(
                color: Colors.white,
                border: Border.all(color: const Color(0xFF4FC3F7), width: 1.5),
                borderRadius: BorderRadius.circular(2),
              ),
            ),
          ),
        ),
      );
    }

    return [
      // ── 表全体の枠 (= 視認用、 HitTest 透過してセル個別操作を邪魔しない) ──
      Positioned(
        left: left,
        top: top,
        width: width,
        height: height,
        child: IgnorePointer(
          ignoring: true,
          child: Container(
            decoration: BoxDecoration(
              border: Border.all(color: const Color(0xFF4FC3F7), width: 1.5),
              color: Colors.transparent,
            ),
          ),
        ),
      ),
      // ── 8 つのリサイズハンドル ──
      // 4 隅
      makeHandle(left, top, -1, -1, SystemMouseCursors.resizeUpLeftDownRight),
      makeHandle(
          left + width, top, 1, -1, SystemMouseCursors.resizeUpRightDownLeft),
      makeHandle(
          left, top + height, -1, 1, SystemMouseCursors.resizeUpRightDownLeft),
      makeHandle(left + width, top + height, 1, 1,
          SystemMouseCursors.resizeUpLeftDownRight),
      // 4 辺中央
      makeHandle(left + width / 2, top, 0, -1, SystemMouseCursors.resizeUpDown),
      makeHandle(left + width / 2, top + height, 0, 1,
          SystemMouseCursors.resizeUpDown),
      makeHandle(
          left, top + height / 2, -1, 0, SystemMouseCursors.resizeLeftRight),
      makeHandle(left + width, top + height / 2, 1, 0,
          SystemMouseCursors.resizeLeftRight),
    ];
  }

  /// 現在のスライドを画像化して PNG として保存。
  /// [allSlides] が true なら全スライドを順次キャプチャしてフォルダに保存。
  ///
  /// JPG 形式は標準 Flutter / dart には無く、 'package:image' への依存追加
  /// が必要なため現状未対応 (PNG のみ)。 PNG はロスレスで品質が高く、
  /// 多くの用途で代替可能。 JPG が必要な場合は次のターンで対応予定。
  Future<void> _exportSlideAsPng({bool allSlides = false}) async {
    final provider = context.read<MindMapProvider>();
    if (_slides.isEmpty) {
      _showSnack('スライドがありません');
      return;
    }
    try {
      final base = await getApplicationDocumentsDirectory();
      final stem = _currentFileName.replaceAll(
          RegExp(r'\.pptx$', caseSensitive: false), '');
      if (allSlides) {
        final outDir = Directory(
            '${base.path}/Kamispec_PptxExport_${DateTime.now().millisecondsSinceEpoch}');
        await outDir.create(recursive: true);
        final originalIndex = _currentIndex;
        var savedCount = 0;
        for (int i = 0; i < _slides.length; i++) {
          setState(() => _currentIndex = i);
          // build 完了 + Repaint まで待つ (= 1 フレーム以上)
          await Future.delayed(const Duration(milliseconds: 120));
          final bytes = await _captureCanvasAsPngBytes();
          if (bytes == null) continue;
          final fname =
              '${stem}_slide${(i + 1).toString().padLeft(2, '0')}.png';
          await File('${outDir.path}/$fname').writeAsBytes(bytes, flush: true);
          savedCount++;
        }
        setState(() => _currentIndex = originalIndex);
        if (mounted) {
          _showSnack(savedCount == 0
              ? provider.t('export.fail')
              : provider
                  .t('export.success')
                  .replaceFirst('{path}', outDir.path));
        }
      } else {
        // 1 枚だけ
        final bytes = await _captureCanvasAsPngBytes();
        if (bytes == null) {
          _showSnack('画像化に失敗しました');
          return;
        }
        final fname =
            '${stem}_slide${(_currentIndex + 1).toString().padLeft(2, '0')}.png';
        final outPath = '${base.path}/$fname';
        await File(outPath).writeAsBytes(bytes, flush: true);
        if (mounted) {
          _showSnack(
              provider.t('export.success').replaceFirst('{path}', outPath));
        }
      }
    } catch (e, st) {
      debugPrint('画像エクスポート失敗: $e\n$st');
      if (mounted) {
        _showSnack(provider.t('doc.saveFailed').replaceFirst('{err}', '$e'));
      }
    }
  }

  /// キャンバス全体を ui.Image → PNG バイト列に変換。
  /// pixelRatio = 2.0 で Retina 相当の高解像度 (= 印刷でも見栄え良い)。
  Future<Uint8List?> _captureCanvasAsPngBytes() async {
    try {
      final ro = _canvasKey.currentContext?.findRenderObject();
      if (ro is! RenderRepaintBoundary) return null;
      final image = await ro.toImage(pixelRatio: 2.0);
      final bd = await image.toByteData(format: ui.ImageByteFormat.png);
      return bd?.buffer.asUint8List();
    } catch (e, st) {
      debugPrint('キャンバスキャプチャ失敗: $e\n$st');
      return null;
    }
  }

  /// 発表者ノート (= スライドメモ) のパネル。 PowerPoint と同じく、 メイン
  /// スライドの直下に表示。
  ///
  /// ユーザー要望「powerpoint に書かれたメモを表示する欄を本家の powerpoint
  ///   みたいに下に搭載して」 への対応。
  ///
  /// 機能:
  ///   - 開閉ボタンで折りたたみ可能 (= デフォルトは展開)
  ///   - TextField でメモを編集 (= notesDirty フラグが立って保存対象に)
  ///   - 「発表者モード」 ボタンで全画面モードへ切替
  Widget _buildNotesPanel(bool dark, Color fg) {
    if (_slides.isEmpty ||
        _currentIndex < 0 ||
        _currentIndex >= _slides.length) {
      return const SizedBox.shrink();
    }
    final slide = _slides[_currentIndex];
    // スライドが変わったら controller を作り直し、 前のメモは確定保存
    if (_notesShownForIndex != _currentIndex) {
      _commitNotesEditing();
      _notesCtrl?.dispose();
      _notesFocus?.dispose();
      _notesCtrl = TextEditingController(text: slide.notes);
      _notesFocus = FocusNode();
      _notesShownForIndex = _currentIndex;
    }
    final headerBg = dark ? const Color(0xFF1E1E2A) : const Color(0xFFE8E8E2);
    final bodyBg = dark ? const Color(0xFF22222E) : const Color(0xFFF5F5F0);
    return Container(
      decoration: BoxDecoration(
        color: bodyBg,
        border: Border(
          top: BorderSide(color: dark ? Colors.white10 : Colors.black12),
        ),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          // ── ヘッダー (= タイトル + 折り畳みボタン + 発表者モードボタン) ──
          Container(
            height: 28,
            padding: const EdgeInsets.symmetric(horizontal: 12),
            color: headerBg,
            child: Row(children: [
              Icon(Icons.sticky_note_2_outlined,
                  size: 14, color: fg.withValues(alpha: 0.6)),
              const SizedBox(width: 6),
              Text(
                'Notes (発表者メモ)',
                style: TextStyle(
                    color: fg.withValues(alpha: 0.6),
                    fontSize: 11,
                    fontWeight: FontWeight.w600),
              ),
              const SizedBox(width: 8),
              if (slide.notesDirty)
                Container(
                  width: 6,
                  height: 6,
                  decoration: const BoxDecoration(
                    color: Color(0xFFFFB74D),
                    shape: BoxShape.circle,
                  ),
                ),
              const Spacer(),
              // 発表者モード起動ボタン
              TextButton.icon(
                onPressed: _startPresenterMode,
                icon: const Icon(Icons.slideshow_rounded,
                    size: 14, color: Color(0xFF43B97F)),
                label: Text(
                    context.read<MindMapProvider>().t('pptx.presenterMode'),
                    style: TextStyle(color: Color(0xFF43B97F), fontSize: 11)),
                style: TextButton.styleFrom(
                  minimumSize: const Size(0, 24),
                  padding: const EdgeInsets.symmetric(horizontal: 8),
                ),
              ),
              IconButton(
                tooltip: _notesExpanded ? 'メモを隠す' : 'メモを表示',
                icon: Icon(
                  _notesExpanded
                      ? Icons.keyboard_arrow_down_rounded
                      : Icons.keyboard_arrow_up_rounded,
                  size: 18,
                  color: fg.withValues(alpha: 0.7),
                ),
                onPressed: () =>
                    setState(() => _notesExpanded = !_notesExpanded),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 24, minHeight: 24),
              ),
            ]),
          ),
          // ── メモ本文 (展開時のみ) ──
          if (_notesExpanded)
            ConstrainedBox(
              constraints: const BoxConstraints(maxHeight: 120),
              child: Padding(
                padding: const EdgeInsets.fromLTRB(12, 6, 12, 8),
                child: TextField(
                  controller: _notesCtrl,
                  focusNode: _notesFocus,
                  maxLines: null,
                  expands: false,
                  style: TextStyle(
                    color: fg,
                    fontSize: 13,
                    height: 1.4,
                  ),
                  decoration: InputDecoration(
                    isDense: true,
                    hintText: context
                        .read<MindMapProvider>()
                        .t('pptx.presenterNoteHint'),
                    hintStyle: TextStyle(
                        color: fg.withValues(alpha: 0.3), fontSize: 12),
                    filled: true,
                    fillColor: dark
                        ? const Color(0xFF1A1A24)
                        : const Color(0xFFFFFFFF),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(4),
                      borderSide: BorderSide(
                        color: dark ? Colors.white12 : Colors.black12,
                      ),
                    ),
                    contentPadding: const EdgeInsets.all(8),
                  ),
                  onChanged: (v) {
                    slide.notes = v;
                    slide.notesDirty = true;
                    setState(() {});
                  },
                ),
              ),
            ),
        ],
      ),
    );
  }

  /// メモ TextField の編集内容を確定 (= スライド切替時など)。
  void _commitNotesEditing() {
    if (_notesCtrl == null || _notesShownForIndex == null) return;
    if (_notesShownForIndex! < 0 || _notesShownForIndex! >= _slides.length) {
      return;
    }
    final slide = _slides[_notesShownForIndex!];
    if (slide.notes != _notesCtrl!.text) {
      slide.notes = _notesCtrl!.text;
      slide.notesDirty = true;
    }
  }

  /// 発表者モードを起動 (= 全画面でスライドを大表示 + メモを横/下に表示)。
  ///
  /// ユーザー要望「発表者モード作ってメモ見ながら発表できるようにして」 への
  ///   対応。 別ダイアログ (= フルスクリーン) で `_PresenterModeDialog` を
  ///   開く。 そこではキー操作 (= 矢印 / Space) でスライドを進められ、 メモ
  ///   と次のスライドのサムネが表示される。 Esc で抜ける。
  Future<void> _startPresenterMode() async {
    // メモ編集中なら先に確定保存
    _commitNotesEditing();
    if (_slides.isEmpty) return;
    // 編集モード中なら一旦抜ける (= プレゼン中に編集 UI が出ないよう)
    if (_editingShapeId != null) _exitShapeEditMode();
    await showGeneralDialog(
      context: context,
      barrierDismissible: false,
      barrierColor: Colors.black,
      transitionDuration: const Duration(milliseconds: 200),
      pageBuilder: (ctx, _, __) => _PresenterModeDialog(
        slides: _slides,
        startIndex: _currentIndex,
        media: _media,
        slideWidthEmu: _slideWidthEmu,
        slideHeightEmu: _slideHeightEmu,
        isDarkMode: widget.isDarkMode,
      ),
    );
  }

  /// スライドの並び順を変えたか (= 保存時に presentation.xml の
  /// `<p:sldIdLst>` を書き換える必要があるか)。
  bool _slideOrderDirty = false;

  /// デスクトップか (サムネイルのドラッグ方式を分けるため)。
  static bool get _isDesktopPptx =>
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);

  /// スライドを [from] 番目から [to] 番目へ動かす (= ユーザー要望:
  /// ドラッグで表示順番を変えられるように)。 ファイル名 (slideN.xml) は
  /// そのままで、 並び順だけを入れ替える。 表示のページ番号は「並びの
  /// 何番目か」 なので、 動かすだけで自動的に振り直される。
  void _reorderSlides(int from, int to) {
    if (from == to || from < 0 || from >= _slides.length) return;
    final dst = to.clamp(0, _slides.length - 1);
    setState(() {
      final moved = _slides.removeAt(from);
      _slides.insert(dst, moved);
      // 選択中のスライドを追いかける。
      if (_currentIndex == from) {
        _currentIndex = dst;
      } else if (from < _currentIndex && dst >= _currentIndex) {
        _currentIndex--;
      } else if (from > _currentIndex && dst <= _currentIndex) {
        _currentIndex++;
      }
      _currentIndex = _currentIndex.clamp(0, _slides.length - 1);
      _slideOrderDirty = true;
    });
  }

  Widget _buildThumbStrip(bool dark, Color fg) {
    return Container(
      height: 110,
      decoration: BoxDecoration(
        color: dark ? const Color(0xFF1E1E2A) : const Color(0xFFE8E8E2),
        border: Border(
          top: BorderSide(color: dark ? Colors.white10 : Colors.black12),
        ),
      ),
      padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 6),
      child: ListView.builder(
        controller: _thumbScroll,
        scrollDirection: Axis.horizontal,
        // 末尾に「+」 を 1 つ足す (= ユーザー要望: スライド一覧の右端の +
        // で新しいスライドを追加できるように)。
        itemCount: _slides.length + 1,
        itemBuilder: (_, i) {
          if (i == _slides.length) {
            return InkWell(
              onTap: _addNewSlide,
              child: Container(
                width: 64,
                margin: const EdgeInsets.symmetric(horizontal: 4),
                decoration: BoxDecoration(
                  color: dark
                      ? Colors.white.withValues(alpha: 0.04)
                      : Colors.black.withValues(alpha: 0.03),
                  border: Border.all(
                      color: dark ? Colors.white24 : Colors.black26),
                  borderRadius: BorderRadius.circular(6),
                ),
                alignment: Alignment.center,
                child: Icon(Icons.add_rounded,
                    size: 22, color: fg.withValues(alpha: 0.7)),
              ),
            );
          }
          final s = _slides[i];
          final active = i == _currentIndex;
          final tile = InkWell(
            onTap: () {
              setState(() => _currentIndex = i);
            },
            child: Container(
              width: 110,
              margin: const EdgeInsets.symmetric(horizontal: 4),
              decoration: BoxDecoration(
                color: active
                    ? const Color(0xFF6C63FF).withValues(alpha: 0.18)
                    : (dark ? const Color(0xFF22222E) : Colors.white),
                border: Border.all(
                  color: active
                      ? const Color(0xFF6C63FF)
                      : (dark ? Colors.white10 : Colors.black12),
                  width: active ? 1.5 : 0.5,
                ),
                borderRadius: BorderRadius.circular(6),
              ),
              padding: const EdgeInsets.all(3),
              // ── ミニチュア描画 (= ユーザー要望: 青色の図形を貼り付けたら
              //    略図も青くなるといった様に、 編集中の内容が略図に反映
              //    されるように)。 旧: 先頭テキストの文字表示だけだった。 ──
              child: Stack(children: [
                Positioned.fill(
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(4),
                    child: CustomPaint(
                      painter: _PptxThumbPainter(
                          s, _slideWidthEmu, _slideHeightEmu),
                    ),
                  ),
                ),
                Positioned(
                  left: 2,
                  top: 1,
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 4, vertical: 1),
                    decoration: BoxDecoration(
                      color: active
                          ? const Color(0xFF6C63FF)
                          : Colors.black.withValues(alpha: 0.35),
                      borderRadius: BorderRadius.circular(4),
                    ),
                    child: Text(
                      // ファイル内の番号ではなく「今の並びの何番目か」。
                      // (= ユーザー要望: 並べ替えたらページ番号も変わる)
                      '${i + 1}',
                      style: const TextStyle(
                        color: Colors.white,
                        fontSize: 9,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ),
                ),
              ]),
            ),
          );
          // ── 右クリックで追加 / 複製 / 削除 (= ユーザー要望) ──
          final tileWithMenu = GestureDetector(
            behavior: HitTestBehavior.opaque,
            onSecondaryTapDown: (d) =>
                unawaited(_showThumbContextMenu(i, d.globalPosition)),
            child: tile,
          );
          // ── ドラッグで並べ替え (= ユーザー要望) ──
          //   デスクトップは掴んですぐ、 触って操作する端末は長押しから
          //   (すぐ動かすと一覧の横スクロールができなくなるため)。
          final feedback = Material(
            color: Colors.transparent,
            child: Opacity(
              opacity: 0.85,
              child: SizedBox(width: 110, height: 84, child: tile),
            ),
          );
          final draggable = _isDesktopPptx
              ? Draggable<int>(
                  data: i,
                  axis: Axis.horizontal,
                  feedback: feedback,
                  childWhenDragging: Opacity(opacity: 0.3, child: tile),
                  child: tileWithMenu,
                )
              : LongPressDraggable<int>(
                  data: i,
                  axis: Axis.horizontal,
                  feedback: feedback,
                  childWhenDragging: Opacity(opacity: 0.3, child: tile),
                  child: tileWithMenu,
                );
          return DragTarget<int>(
            onWillAcceptWithDetails: (d) => d.data != i,
            onAcceptWithDetails: (d) => _reorderSlides(d.data, i),
            builder: (ctx, cand, _) => Stack(children: [
              draggable,
              // 落とす場所の目印。
              if (cand.isNotEmpty)
                Positioned(
                  left: 0,
                  top: 0,
                  bottom: 0,
                  child: Container(width: 3, color: const Color(0xFF6C63FF)),
                ),
            ]),
          );
        },
      ),
    );
  }
}

// ════════════════════════════════════════════════════════════════════════
//  テキストエディタ (仮想化版) — txt / md / py / js / dart / cpp / java など
// ════════════════════════════════════════════════════════════════════════
//
// 大きなファイル (1,000 行〜) でもフリーズしないよう、 ListView.builder で
// 行ごとに遅延描画する。 編集はタップした行だけ TextField になり、 他は
// 軽量な Text ウィジェットで表示する。
//
// 機能:
//   - 行単位の仮想化スクロール (任意の行数で動く、 100,000 行でも OK)
//   - タップで行編集 (TextField 1 つだけがアクティブ)
//   - Enter で行分割 / 末尾改行、 Backspace 行頭で前行と結合
//   - Ctrl+S 保存、 Tab で 4 スペース挿入
//   - 数式プレビューモード (.md / .tex / .markdown で $...$ / $$...$$ を
//     flutter_math_fork で描画)
//   - 言語検出 + 色付きバッジ、 行番号、 monospace、 ダーク/ライト追従
//   - リネーム、 AI 編集、 外部アプリで開く

/// _TextEditorDialog の undo/redo 用スナップショット。
class _TextSnapshot {
  final List<String> lines;
  _TextSnapshot(this.lines);
}

class _TextEditorDialog extends StatefulWidget {
  final String filePath;
  final String fileName;
  final bool isDarkMode;

  /// 開いた元の添付ノード。 あればメモ欄 (= PDF ビューアと同じ PdfMemo) を
  /// このノードに紐づけて使える。
  final String? nodeId;

  /// ノード未紐付け (= 「アプリで開く」 等) の時、 「ページに追加」 ボタンで
  /// このファイルをノード化するコールバック (= PDF ビューアと同じ仕組み。
  /// ユーザー要望: アプリで開くとメモが書けない問題の対応)。
  final Future<String?> Function({String? pageId})? onEnsureNode;
  final VoidCallback? onSaved;
  final void Function(String newPath, String newName)? onRenamed;

  const _TextEditorDialog({
    required this.filePath,
    required this.fileName,
    this.isDarkMode = true,
    this.nodeId,
    this.onEnsureNode,
    this.onSaved,
    this.onRenamed,
    this.compactHost = false,
  });

  /// フローティング窓・分割ペインなど狭い場所で開かれているか。
  /// true の時はメモ / AI パネルを自動で開かない (= ユーザー要望:
  /// 表示領域が小さい時に勝手に開かれると本文が見えない)。
  final bool compactHost;

  @override
  State<_TextEditorDialog> createState() => _TextEditorDialogState();
}

class _TextEditorDialogState extends State<_TextEditorDialog> {
  // ─── ファイルパス / 名前 (リネーム対応) ─────────────────────────────
  late String _currentFilePath = widget.filePath;
  late String _currentFileName = widget.fileName;

  // ─── 内容 (行単位) ──────────────────────────────────────────────
  /// 行ごとに分解した内容。 ファイル全体の source of truth。
  final List<String> _lines = [];

  /// 編集中の行 (null なら閲覧モード)
  int? _editingIdx;

  // ── 複数行の範囲選択 (= ユーザー要望: Ctrl+Shift+↑↓ で複数行を
  //    まとめて選べるように) ──
  /// 選び始めた行。 null = 選択していない。
  /// 行の上をなぞって複数行を選んでいる最中か (= ユーザー要望: 選択状態で
  /// 上下にドラッグしたら複数行選択されるように)。 Listener + MouseRegion
  /// で見ているので、 指でのスクロールは今までどおり効く。
  bool _lineDragSelecting = false;
  int? _lineDragAnchor;

  int? _selAnchorLine;

  /// 今いる行 (アンカーとの間が選択範囲になる)。
  int? _selFocusLine;

  /// 「今いる行」 に付ける目印。 画面内へ引き戻す時の基準にする
  /// (= ユーザー要望: カーソルの追従を素早く)。
  final GlobalKey _curLineKey = GlobalKey();
  final TextEditingController _editCtrl = TextEditingController();
  final FocusNode _editFocus = FocusNode();

  /// 編集中行の前の値 (= 変更検知用)
  String _editOriginal = '';

  // ─── 状態 ───────────────────────────────────────────────────────
  String _loadedHash = '';
  bool _loading = true;
  bool _dirty = false;
  String? _loadError;
  String _language = 'text';

  // ─── スクロール / フォーカス ─────────────────────────────────────
  final ScrollController _scroll = ScrollController();
  final FocusNode _keyFocus = FocusNode();

  // ─── AI 編集 ────────────────────────────────────────────────────
  bool _aiBusy = false;
  String? _aiUndoSnapshot;

  // ─── 表示設定 (= ユーザー要望: 中央揃えで開く / ヘッダーの表示切替) ───
  /// 本文を中央揃えで表示するか。 既定 ON (= ユーザー要望)。
  // ── 本文の揃え (= ユーザー要望: 既定は左揃え、 右揃えもできるように)。
  //    'left' / 'center' / 'right' の 3 段階をボタンで循環する。
  String _alignMode = 'left';

  TextAlign get _bodyAlign => _alignMode == 'center'
      ? TextAlign.center
      : _alignMode == 'right'
          ? TextAlign.end
          : TextAlign.start;

  /// ヘッダー (ファイル名やボタンの列) を表示するか。
  bool _headerVisible = true;

  /// 閲覧行のタップ位置 (クリックした場所にカーソルを置くため)。
  Offset? _lineTapPos;

  // ─── 左右パネル (= ユーザー要望: PDF ビューアと同じメモ欄 / AI 欄) ───
  bool _memoPanelOpen = false;
  bool _aiPanelOpen = false;

  /// メモ欄 / AI 欄の幅 (= ユーザー要望: 境界をドラッグで動かせるように)。
  double _memoPanelW = 320.0;
  double _aiPanelW = 380.0;

  /// メモの紐付け先ノード。 widget.nodeId が無い場合 (= アプリで開く) は
  /// 「ページに追加」 でノード化した時にここへ入る (= ユーザー要望)。
  String? _nodeId;

  // ── ブラウザ版 AI チャット欄 (= ユーザー要望: API キーを叩くものでは
  //    なく、 ブラウザ版の AI が開かれるように)。 PDF ビューアの AI 欄と
  //    同じ仕組み (webview_windows + キャッシュ + 既定 AI 共有)。 ──
  /// 開いている AI の URL (空 = 未選択)。
  String _aiPanelUrl = '';

  /// ★ フリーズ対策の WebView キャッシュ (PDF ビューアと同じ理由) ★
  /// 一度生成した WebView ウィジェットの実体を保持して再生成を防ぐ。
  Widget? _aiWebCache;

  /// Windows 用 AI WebView コントローラ (JS 注入 / ホイールスクロール用)。
  wv_win.WebviewController? _aiWinCtrl;

  /// メモ→AI 送信の重複挿入防止トークン。
  int _aiInjectSeq = 0;

  /// AI編集 (MCP でファイルを書き換えるチャット) の履歴。
  final List<({String role, String text})> _aiChat = [];

  /// AI編集チャットの履歴をファイルごとに保存 / 復元する (= ユーザー要望:
  /// AI 会話の履歴を保存しておけるように)。 直近 40 件まで。
  String get _aiChatLogKey =>
      'aiEditChatLog_${_currentFilePath.hashCode.toRadixString(16)}';

  Future<void> _loadAiChatLog() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_aiChatLogKey);
      if (raw == null || raw.isEmpty || !mounted) return;
      final list = jsonDecode(raw);
      if (list is! List) return;
      setState(() {
        _aiChat.clear();
        for (final e in list) {
          if (e is Map && e['r'] is String && e['t'] is String) {
            _aiChat.add((role: e['r'] as String, text: e['t'] as String));
          }
        }
      });
    } catch (_) {}
  }

  Future<void> _saveAiChatLog() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final list = _aiChat.length > 40
          ? _aiChat.sublist(_aiChat.length - 40)
          : _aiChat;
      await prefs.setString(
          _aiChatLogKey,
          jsonEncode([
            for (final m in list) {'r': m.role, 't': m.text}
          ]));
    } catch (_) {}
  }
  final TextEditingController _aiInput = TextEditingController();

  // ── AI編集チャットの添付 (= ユーザー要望: 画像やファイルを渡せるように)。
  //    画像はそのまま画像として、 テキスト系ファイルは中身を指示文に足す。 ──
  final List<({String path, String name, bool isImage})> _aiPendingFiles = [];

  // ── ↑キーで過去のプロンプトを呼び出す (= ユーザー要望)。
  //    履歴はアプリ全体で共有し、 prefs 'aiEditPromptHistory' に保存。 ──
  static List<String>? _aiPromptHistoryCache;
  int? _aiHistIdx;
  String _aiDraftBeforeHist = '';

  Future<List<String>> _aiHistory() async {
    var cache = _aiPromptHistoryCache;
    if (cache != null) return cache;
    try {
      final prefs = await SharedPreferences.getInstance();
      cache = prefs.getStringList('aiEditPromptHistory') ?? <String>[];
    } catch (_) {
      cache = <String>[];
    }
    _aiPromptHistoryCache = cache;
    return cache;
  }

  Future<void> _aiHistoryAdd(String q) async {
    final hist = await _aiHistory();
    hist.remove(q); // 重複は最新側へ寄せる
    hist.add(q);
    while (hist.length > 50) {
      hist.removeAt(0);
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setStringList('aiEditPromptHistory', hist);
    } catch (_) {}
  }

  /// ↑ = 一つ古いプロンプトを入力欄へ。 ↓ = 新しい方向 (末端で下書きに戻す)。
  Future<void> _aiHistMove(int delta) async {
    final hist = await _aiHistory();
    if (hist.isEmpty || !mounted) return;
    var idx = _aiHistIdx;
    if (idx == null) {
      if (delta > 0) return; // 履歴に入っていない時の ↓ は何もしない
      _aiDraftBeforeHist = _aiInput.text;
      idx = hist.length - 1;
    } else {
      idx += delta;
    }
    if (idx >= hist.length) {
      // 一番新しい所を超えた → 下書きへ戻る
      _aiHistIdx = null;
      _aiInput.text = _aiDraftBeforeHist;
      _aiInput.selection =
          TextSelection.collapsed(offset: _aiInput.text.length);
      return;
    }
    idx = idx.clamp(0, hist.length - 1);
    _aiHistIdx = idx;
    _aiInput.text = hist[idx];
    _aiInput.selection = TextSelection.collapsed(offset: _aiInput.text.length);
  }

  /// 添付ファイルを選ぶ (画像 + テキスト系)。
  Future<void> _pickAiAttachment() async {
    try {
      final result = await FilePicker.platform.pickFiles(allowMultiple: true);
      final files = result?.files ?? const [];
      if (files.isEmpty || !mounted) return;
      setState(() {
        for (final f in files) {
          final p = f.path;
          if (p == null) continue;
          final ext = p.contains('.')
              ? p.substring(p.lastIndexOf('.') + 1).toLowerCase()
              : '';
          final isImage = const {'png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp'}
              .contains(ext);
          if (_aiPendingFiles.length >= 6) break;
          _aiPendingFiles.add((
            path: p,
            name: p.replaceAll('\\', '/').split('/').last,
            isImage: isImage,
          ));
        }
      });
    } catch (e) {
      _showSnackBar('$e');
    }
  }

  /// LaTeX 数式を挿入する (= ユーザー要望: Word の数式挿入ボタンを
  /// テキストファイルにも)。 数式プレビューが描画できる $$ 行として、
  /// 編集中の行 (無ければ末尾) の下に入れる。
  Future<void> _insertMathText() async {
    final tex = await _showLatexInsertDialog(context,
        isDarkMode: widget.isDarkMode);
    if (tex == null || tex.trim().isEmpty || !mounted) return;
    _commitEdit();
    setState(() {
      final at = ((_editingIdx ?? _lines.length - 1) + 1)
          .clamp(0, _lines.length);
      _lines.insertAll(at, [r'$$', tex.trim(), r'$$']);
      _markDirty();
    });
  }
  final ScrollController _aiScroll = ScrollController();
  bool _aiChatBusy = false;

  /// true = ブラウザ AI の上に「AI編集」 (MCP) チャットを重ねて表示。
  bool _aiEditChatMode = false;

  // ─── MCP 連携 (= ユーザー要望: MCP で中身を編集できる AI) ───────────
  MindMapProvider? _providerRef;
  McpTextFileBinding? _mcpBinding;

  bool get _isDesktopEditor =>
      !kIsWeb && (Platform.isWindows || Platform.isMacOS || Platform.isLinux);

  // ─── Undo / Redo ────────────────────────────────────────────────
  /// undo スタック (最新の編集前状態を末尾に持つ)。 上限 _maxHistory。
  final List<_TextSnapshot> _undoStack = [];

  /// redo スタック。 _undo() で _undoStack から取り出した直前状態を push。
  final List<_TextSnapshot> _redoStack = [];
  static const int _maxHistory = 100;

  /// 現在の状態を _TextSnapshot にキャプチャ。
  _TextSnapshot _captureSnapshot() => _TextSnapshot(List.from(_lines));

  /// スナップショットから状態を復元 (編集モードは解除)。
  void _restoreSnapshot(_TextSnapshot s) {
    setState(() {
      _lines
        ..clear()
        ..addAll(s.lines);
      if (_lines.isEmpty) _lines.add('');
      _editingIdx = null;
    });
    _markDirty();
  }

  /// 編集の **前** に呼ぶ。 redo スタックはクリア (= 履歴分岐回避)。
  void _pushUndo() {
    _undoStack.add(_captureSnapshot());
    if (_undoStack.length > _maxHistory) _undoStack.removeAt(0);
    _redoStack.clear();
  }

  bool get _canUndo => _undoStack.isNotEmpty;
  bool get _canRedo => _redoStack.isNotEmpty;

  void _undo() {
    if (_undoStack.isEmpty) return;
    _commitEdit();
    final cur = _captureSnapshot();
    final prev = _undoStack.removeLast();
    _redoStack.add(cur);
    if (_redoStack.length > _maxHistory) _redoStack.removeAt(0);
    _restoreSnapshot(prev);
  }

  void _redo() {
    if (_redoStack.isEmpty) return;
    _commitEdit();
    final cur = _captureSnapshot();
    final next = _redoStack.removeLast();
    _undoStack.add(cur);
    if (_undoStack.length > _maxHistory) _undoStack.removeAt(0);
    _restoreSnapshot(next);
  }

  // ─── 数式プレビュー ─────────────────────────────────────────────
  /// 数式を含む可能性のあるファイル (.md / .markdown / .tex / .txt)
  bool get _mathCapable {
    final l = _currentFileName.toLowerCase();
    return l.endsWith('.md') ||
        l.endsWith('.markdown') ||
        l.endsWith('.tex') ||
        l.endsWith('.txt') ||
        l.endsWith('.rst');
  }

  /// 数式プレビューモード ON の時、 $...$ / $$...$$ を MathJax 風に描画。
  bool _mathPreview = false;

  // ── Markdown プレビュー (= ユーザー要望: マークダウン形式を開いた時の
  //    プレビュー機能 + Mermaid 記法) ──
  /// Markdown ファイルか (.md / .markdown)。
  bool get _isMarkdownFile {
    final l = _currentFileName.toLowerCase();
    return l.endsWith('.md') || l.endsWith('.markdown');
  }

  /// HTML ファイルか (= ユーザー要望: html もマークダウンみたいに編集して
  /// プレビュー画面を表示できるように)。 プレビューは書いた HTML を
  /// そのまま WebView で表示する。
  bool get _isHtmlFile {
    final l = _currentFileName.toLowerCase();
    return l.endsWith('.html') || l.endsWith('.htm');
  }

  /// プレビュー (編集⇔表示の切り替え / 左右分割) を出せるファイルか。
  bool get _isPreviewableFile => _isMarkdownFile || _isHtmlFile;

  /// Markdown プレビューモード (編集ビューと切り替え)。
  bool _mdPreview = false;

  /// プレビュー用 WebView (デスクトップ = WebView2 / モバイル = iaw)。
  wv_win.WebviewController? _mdWin;
  bool _mdWinReady = false;
  bool _mdWinFailed = false;
  iaw.InAppWebViewController? _mdIaw;

  /// プレビュー内の Mermaid 図のボタン (AI / AI修正 / コピー / 保存 /
  /// マップへ) からの通知 (= ユーザー要望)。 webview_windows の
  /// webMessage 経由。
  StreamSubscription<dynamic>? _mdMsgSub;

  /// 編集×プレビューの左右分割 (= ユーザー要望: プレビューの発展)。
  bool _mdSplitView = false;
  Timer? _mdSplitRenderDebounce;
  Timer? _mdScrollSyncThrottle;

  void _onMdPreviewMessage(dynamic msg) {
    try {
      dynamic m = msg;
      if (m is String) m = jsonDecode(m);
      if (m is! Map) return;
      final type = '${m['type'] ?? ''}';
      final code = '${m['code'] ?? ''}'.trim();
      switch (type) {
        case 'mermaidToAi':
          // 図の Mermaid ソースをブラウザ AI の入力欄へ (閉じていれば開く)。
          // 質問文は利用者が前後に書き足せるよう、 コードだけを渡す。
          if (code.isEmpty) return;
          _sendTextToBrowserAi('```mermaid\n$code\n```');
          break;
        case 'mermaidCopy':
          if (code.isEmpty) return;
          Clipboard.setData(ClipboardData(text: code));
          _showSnackBar(
              context.read<MindMapProvider>().t('md.mermaidCopied'));
          break;
        case 'mermaidFix':
          // AI編集 (MCP) にこの図の修正を頼む (= ユーザー要望: 発展案)。
          if (code.isEmpty) return;
          unawaited(_askMermaidFix(code));
          break;
        case 'mermaidSave':
          unawaited(_saveDiagramExport(m.cast<dynamic, dynamic>()));
          break;
        case 'mermaidToMap':
          unawaited(_sendDiagramToMap(m.cast<dynamic, dynamic>()));
          break;
      }
    } catch (_) {}
  }

  /// 図の PNG (無ければ SVG) をバイト列に直す。
  (Uint8List, String)? _diagramBytesOf(Map<dynamic, dynamic> m) {
    final png = '${m['png'] ?? ''}';
    if (png.startsWith('data:image/png;base64,')) {
      try {
        return (
          base64Decode(png.substring('data:image/png;base64,'.length)),
          'png'
        );
      } catch (_) {}
    }
    final svg = '${m['svg'] ?? ''}'.trim();
    if (svg.isNotEmpty) {
      return (Uint8List.fromList(utf8.encode(svg)), 'svg');
    }
    return null;
  }

  /// 図を画像ファイルとして保存 (= ユーザー要望: 発展案)。
  Future<void> _saveDiagramExport(Map<dynamic, dynamic> m) async {
    final data = _diagramBytesOf(m);
    if (data == null) return;
    final (bytes, ext) = data;
    try {
      final name =
          'mermaid_${DateTime.now().millisecondsSinceEpoch}.$ext';
      final path = await FilePicker.platform.saveFile(
        fileName: name,
        type: FileType.custom,
        allowedExtensions: [ext],
      );
      if (path == null) return;
      var fixed = path;
      if (!fixed.toLowerCase().endsWith('.$ext')) fixed = '$fixed.$ext';
      await File(fixed).writeAsBytes(bytes, flush: true);
      if (mounted) {
        _showSnackBar(context
            .read<MindMapProvider>()
            .t('md.diagramSaved')
            .replaceFirst('{path}', fixed));
      }
    } catch (e) {
      _showSnackBar('$e');
    }
  }

  /// 図を画像ノードとして今のページへ貼る (= ユーザー要望: 発展案)。
  Future<void> _sendDiagramToMap(Map<dynamic, dynamic> m) async {
    final data = _diagramBytesOf(m);
    if (data == null) return;
    final (bytes, ext) = data;
    if (ext != 'png') {
      // 画像ノードは PNG のみ対応 (SVG しか作れなかった時は保存を促す)。
      await _saveDiagramExport(m);
      return;
    }
    try {
      final provider = context.read<MindMapProvider>();
      final appDir = await getApplicationDocumentsDirectory();
      final dir = Directory('${appDir.path}/attachments');
      if (!await dir.exists()) await dir.create(recursive: true);
      final path =
          '${dir.path}/mermaid_${DateTime.now().millisecondsSinceEpoch}.png';
      await File(path).writeAsBytes(bytes, flush: true);
      final id = provider.mcpAddImageNode(provider.currentPage.id,
          filePath: path, title: 'Mermaid');
      if (mounted) {
        _showSnackBar(id == null
            ? context.read<MindMapProvider>().t('mcp.failed')
            : context
                .read<MindMapProvider>()
                .t('md.sentToMap')
                .replaceFirst('{page}', provider.currentPage.name));
      }
    } catch (e) {
      _showSnackBar('$e');
    }
  }

  /// 「AIで図を修正」 — 指示を聞いてから AI編集 (MCP) に、 ファイル内の
  /// この Mermaid ブロックの書き換えを頼む (= ユーザー要望: 発展案)。
  Future<void> _askMermaidFix(String code) async {
    final provider = context.read<MindMapProvider>();
    if (!provider.hasActiveAiKey) {
      _showSnackBar(provider.t('text.aiNeedKey'));
      return;
    }
    final ctrl = TextEditingController();
    final instruction = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Row(children: [
          const Icon(Icons.auto_fix_high_rounded,
              color: Color(0xFF6C63FF), size: 20),
          const SizedBox(width: 8),
          Expanded(
            child: Text(provider.t('md.fixTitle'),
                style: const TextStyle(color: Colors.white, fontSize: 15)),
          ),
        ]),
        content: SizedBox(
          width: 420,
          child:
              Column(mainAxisSize: MainAxisSize.min, children: [
            // ── モデル / 推論レベルの選択 (= ユーザー要望) ──
            const Align(
                alignment: Alignment.centerLeft,
                child: _AiModelReasoningRow()),
            const SizedBox(height: 10),
            TextField(
            controller: ctrl,
            autofocus: true,
            minLines: 2,
            maxLines: 4,
            style: const TextStyle(color: Colors.white, fontSize: 13),
            decoration: InputDecoration(
              hintText: provider.t('md.fixHint'),
              hintStyle:
                  const TextStyle(color: Colors.white24, fontSize: 12),
              filled: true,
              fillColor: Colors.white.withValues(alpha: 0.06),
              border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(8),
                  borderSide: BorderSide.none),
            ),
          ),
          ]),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF6C63FF),
                foregroundColor: Colors.white),
            onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
            child: Text(provider.t('doc.aiExecute')),
          ),
        ],
      ),
    );
    ctrl.dispose();
    if (instruction == null || instruction.isEmpty || !mounted) return;
    // AI 欄を AI編集モードで開き、 エージェントに依頼する。
    setState(() {
      _aiPanelOpen = true;
      _aiEditChatMode = true;
    });
    if (_aiPanelUrl.isEmpty) {
      _openTextAiPanel(provider.pdfAiPanelDefault);
      setState(() => _aiEditChatMode = true);
    }
    final combined = 'ファイル内の次の Mermaid ブロックを、 指示に従って '
        'text_file_edit で書き換えてください。 ブロックの前後 (フェンス行) は '
        '崩さないこと。\n```mermaid\n$code\n```\n【指示】$instruction';
    setState(() {
      _aiChat.add((role: 'user', text: '${provider.t('md.fixTitle')}: '
          '$instruction'));
      _aiChatBusy = true;
    });
    _aiChatScrollEnd();
    try {
      await _runAiFileEditAgent(provider, combined);
    } catch (e) {
      if (mounted) setState(() => _aiChat.add((role: 'ai', text: '⚠ $e')));
    } finally {
      if (mounted) setState(() => _aiChatBusy = false);
      unawaited(_saveAiChatLog());
      _aiChatScrollEnd();
    }
  }

  /// プレビューを開く / 閉じる。 開く時に現在の本文を描画する。
  /// プレビュー用 WebView の初期化 (通常プレビューと分割プレビューで共用)。
  Future<bool> _ensureMdWebView() async {
    if (kIsWeb ||
        !(Platform.isWindows || Platform.isMacOS || Platform.isLinux)) {
      return true; // モバイルは InAppWebView 側で処理
    }
    if (_mdWin != null) return true;
    if (_mdWinFailed) return false;
    try {
      final c = wv_win.WebviewController();
      await c.initialize().timeout(const Duration(seconds: 12));
      await c.setBackgroundColor(const Color(0xFF14141F));
      if (!mounted || (!_mdPreview && !_mdSplitView)) {
        await c.dispose();
        return false;
      }
      // Mermaid 図の AI / コピー等のボタンからの通知を受ける (= ユーザー要望)。
      _mdMsgSub = c.webMessage.listen(_onMdPreviewMessage);
      setState(() {
        _mdWin = c;
        _mdWinReady = true;
      });
      return true;
    } catch (e) {
      debugPrint('markdown ファイルプレビューの初期化に失敗: $e');
      if (mounted) setState(() => _mdWinFailed = true);
      return false;
    }
  }

  Future<void> _toggleMdPreview() async {
    _commitEdit();
    final next = !_mdPreview;
    setState(() {
      _mdPreview = next;
      if (next) _mdSplitView = false;
    });
    if (!next) return;
    if (!await _ensureMdWebView()) return;
    await _renderMdPreview();
  }

  /// 編集×プレビューの左右分割 (= ユーザー要望: プレビューの発展)。
  /// 打鍵は 600ms 待ってから window.__mmUpdate でページ内再描画する
  /// (リロードしないのでちらつかない)。
  Future<void> _toggleMdSplitView() async {
    _commitEdit();
    final next = !_mdSplitView;
    setState(() {
      _mdSplitView = next;
      if (next) {
        _mdPreview = false;
        _mathPreview = false;
      }
    });
    if (!next) return;
    if (!await _ensureMdWebView()) return;
    await _renderMdPreview();
  }

  /// 分割プレビュー中の内容更新 (ページ内 JS で再描画。 リロード無し)。
  void _scheduleSplitPreviewUpdate() {
    if (!_mdSplitView) return;
    _mdSplitRenderDebounce?.cancel();
    _mdSplitRenderDebounce = Timer(const Duration(milliseconds: 600), () {
      if (!mounted || !_mdSplitView) return;
      // HTML は書いた物がそのままページなので、 読み込み直す
      // (Markdown のような「本文だけ差し替える」 入口が無いため)。
      if (_isHtmlFile) {
        unawaited(_renderMdPreview());
        return;
      }
      if (!_mdWinReady) return;
      try {
        final js = 'window.__mmUpdate(${jsonEncode(_previewSourceText())});';
        _mdWin?.executeScript(js);
      } catch (_) {}
    });
  }

  /// 編集側のスクロールにプレビューを追従させる (= スクロール同期)。
  void _syncSplitPreviewScroll() {
    if (!_mdSplitView || !_mdWinReady || !_scroll.hasClients) return;
    if (_mdScrollSyncThrottle?.isActive ?? false) return;
    _mdScrollSyncThrottle = Timer(const Duration(milliseconds: 120), () {});
    final max = _scroll.position.maxScrollExtent;
    final frac = max <= 0 ? 0.0 : (_scroll.offset / max).clamp(0.0, 1.0);
    try {
      _mdWin?.executeScript(
          'window.scrollTo(0, (document.documentElement.scrollHeight - '
          'window.innerHeight) * $frac);');
    } catch (_) {}
  }

  Future<void> _renderMdPreview() async {
    if (!mounted || (!_mdPreview && !_mdSplitView)) return;
    // ── HTML ファイルは書いた内容をそのまま表示する (= ユーザー要望) ──
    //    デスクトップは元ファイルの隣に控えを書いて file:// で開く
    //    (画像や css の相対パスがそのまま効くように)。
    if (_isHtmlFile) {
      // 明るい配色を明示する (= ユーザー報告: プレビューが暗転する)。
      final src = _htmlPreviewWithLightScheme(_previewSourceText());
      try {
        if (!kIsWeb &&
            (Platform.isWindows || Platform.isMacOS || Platform.isLinux)) {
          // WebView の下地も白に戻す (指定色が透けて暗く見えるため)。
          try {
            await _mdWin?.setBackgroundColor(Colors.white);
          } catch (_) {}
          // ── 元ファイルの隣に控えを書いて file:// で開く。
          //    (画像や css の相対パスをそのまま効かせるため) ──
          //    書けない場所なら一時フォルダーへ、 それも駄目なら
          //    中身を直接流し込む (= ユーザー報告: プレビューが出ない)。
          String? fileUrl;
          final tmpName =
              '.hn_preview_${_currentFileName.hashCode.toRadixString(16)}.html';
          for (final dir in <String>[
            File(_currentFilePath).parent.path,
            Directory.systemTemp.path,
          ]) {
            try {
              final tmp = File('$dir${Platform.pathSeparator}$tmpName');
              await tmp.writeAsString(src, flush: true);
              fileUrl = Uri.file(tmp.path).toString();
              break;
            } catch (_) {}
          }
          if (!mounted || (!_mdPreview && !_mdSplitView)) return;
          if (!_mdWinReady || _mdWin == null) return;
          var shown = false;
          if (fileUrl != null) {
            try {
              await _mdWin!.loadUrl(fileUrl);
              shown = true;
            } catch (e) {
              debugPrint('HTML プレビュー: file:// で開けませんでした: $e');
            }
          }
          if (!shown) await _mdWin!.loadStringContent(src);
        } else {
          final uri =
              Uri.dataFromString(src, mimeType: 'text/html', encoding: utf8)
                  .toString();
          await _mdIaw?.loadUrl(
              urlRequest: iaw.URLRequest(url: iaw.WebUri(uri)));
        }
      } catch (e) {
        debugPrint('HTML プレビューの描画に失敗: $e');
      }
      return;
    }
    final html = _markdownPreviewHtml(_lines.join('\n'), widget.isDarkMode);
    try {
      if (!kIsWeb &&
          (Platform.isWindows || Platform.isMacOS || Platform.isLinux)) {
        // HTML を見た後に戻ってきた時のため、 下地を戻す。
        try {
          await _mdWin?.setBackgroundColor(
              widget.isDarkMode ? const Color(0xFF14141F) : Colors.white);
        } catch (_) {}
        // ── file:// で開く (= Mermaid 描画対応。 about:blank だと CDN の
        //    スクリプトが読めない環境がある)。 準備できない時だけ従来の
        //    loadStringContent + CDN にフォールバック。 ──
        final localHtml = _markdownPreviewHtml(
            _lines.join('\n'), widget.isDarkMode,
            markedSrc: 'marked.min.js',
            mermaidSrc: 'mermaid.min.js',
            hljsSrc: 'highlight.min.js',
            hljsCssSrc:
                widget.isDarkMode ? 'hljs-dark.css' : 'hljs-light.css',
            mathjaxSrc: 'tex-svg.js',
            tocLabel: context.read<MindMapProvider>().t('md.toc'),
            // 図の AI / コピーボタン (= ユーザー要望: 図の中身を AI に渡す)。
            aiBridge: true);
        final fileUrl = await _prepareMarkdownPreviewFile(localHtml);
        if (!mounted || (!_mdPreview && !_mdSplitView)) return;
        if (fileUrl != null) {
          if (_mdWinReady) await _mdWin?.loadUrl(fileUrl);
          return;
        }
        if (_mdWinReady) {
          await _mdWin?.loadStringContent(_markdownPreviewHtml(
              _lines.join('\n'), widget.isDarkMode,
              aiBridge: true));
        }
      } else {
        final uri =
            Uri.dataFromString(html, mimeType: 'text/html', encoding: utf8)
                .toString();
        await _mdIaw?.loadUrl(
            urlRequest: iaw.URLRequest(url: iaw.WebUri(uri)));
      }
    } catch (e) {
      debugPrint('markdown ファイルプレビューの描画に失敗: $e');
    }
  }

  /// プレビュー本体 (デスクトップ = WebView2 / モバイル = InAppWebView)。
  Widget _buildMdPreviewBody() {
    if (!kIsWeb &&
        (Platform.isWindows || Platform.isMacOS || Platform.isLinux)) {
      if (_mdWinFailed) {
        return Center(
          child: Padding(
            padding: const EdgeInsets.all(24),
            child: Text(
                context.read<MindMapProvider>().t('md.previewUnavailable'),
                style: const TextStyle(color: Colors.white54, fontSize: 12)),
          ),
        );
      }
      if (!_mdWinReady || _mdWin == null) {
        return const Center(child: CircularProgressIndicator(strokeWidth: 2));
      }
      return wv_win.Webview(_mdWin!);
    }
    // HTML ファイルは書いた物をそのまま表示する (= ユーザー報告: html の
    // プレビューが出ない。 markdown として組み直していたのが原因)。
    final src = _isHtmlFile
        ? _htmlPreviewWithLightScheme(_lines.join('\n'))
        : _markdownPreviewHtml(_lines.join('\n'), widget.isDarkMode);
    final uri =
        Uri.dataFromString(src, mimeType: 'text/html', encoding: utf8)
            .toString();
    return iaw.InAppWebView(
      initialUrlRequest: iaw.URLRequest(url: iaw.WebUri(uri)),
      onWebViewCreated: (c) => _mdIaw = c,
    );
  }

  // ─── レイアウト定数 ─────────────────────────────────────────────
  static const double _lineHeight = 22.0;
  static const double _gutterWidth = 52.0;
  static const double _fontSize = 13.0;

  @override
  void initState() {
    super.initState();
    _language = _detectLanguage(_currentFileName);
    _nodeId = widget.nodeId;
    _loadFile();
    _loadEditorPrefs();
    // AI編集チャットの履歴を復元 (= ユーザー要望)。
    unawaited(_loadAiChatLog());
    // 分割プレビューの追従 (打鍵 / スクロール) (= ユーザー要望: 発展案)。
    _editCtrl.addListener(_scheduleSplitPreviewUpdate);
    _scroll.addListener(_syncSplitPreviewScroll);
    // ── 左右パネルは自動で立ち上げる (= ユーザー要望)。 AI (WebView) は
    //    本文の表示を待ってから少し遅らせて開く。 ──
    // フローティング / 分割ペインなど狭い場所では自動で開かない
    // (= ユーザー要望: 表示領域が小さいので勝手に開かれると邪魔)。
    if (_isDesktopEditor && !widget.compactHost) {
      _memoPanelOpen = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        Future.delayed(const Duration(milliseconds: 400), () {
          if (mounted && !_aiPanelOpen) {
            _openTextAiPanel(
                context.read<MindMapProvider>().pdfAiPanelDefault);
          }
        });
      });
    }
    // ── MCP に「今開いているテキストファイル」 として登録する
    //    (= ユーザー要望: MCP で中身を編集できる AI 機能) ──
    _providerRef = context.read<MindMapProvider>();
    final binding = McpTextFileBinding(
      fileName: () => _currentFileName,
      getLines: () => List<String>.from(_lines),
      applyEdits: _applyMcpEdits,
    );
    _mcpBinding = binding;
    _providerRef!.mcpBindTextFile(binding);
    // ── アプリ本体の × でも未保存確認が出るよう登録 (= ユーザー要望) ──
    kUnsavedCloseGuards[identityHashCode(this)] = () async {
      if (!mounted) return true;
      return _confirmDiscard();
    };
  }

  @override
  void dispose() {
    kUnsavedCloseGuards.remove(identityHashCode(this));
    final b = _mcpBinding;
    if (b != null) _providerRef?.mcpUnbindTextFile(b);
    _editCtrl.dispose();
    _editFocus.dispose();
    _keyFocus.dispose();
    _scroll.dispose();
    _aiInput.dispose();
    _aiScroll.dispose();
    _reader?.dispose();
    unawaited(_mdMsgSub?.cancel());
    _mdSplitRenderDebounce?.cancel();
    _mdScrollSyncThrottle?.cancel();
    try {
      _mdWin?.dispose();
    } catch (_) {}
    super.dispose();
  }

  /// 表示設定 (本文の揃え) を読み込む。
  /// 旧キー 'textEditorCenterAlign' (中央揃え既定 ON) は廃止し、 新キーが
  /// 無い時は左揃えで始める (= ユーザー要望: 既定は左揃え)。
  Future<void> _loadEditorPrefs() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final v = prefs.getString('textEditorAlignMode') ?? 'left';
      if (mounted &&
          v != _alignMode &&
          const {'left', 'center', 'right'}.contains(v)) {
        setState(() => _alignMode = v);
      }
    } catch (_) {}
  }

  Future<void> _toggleCenterAlign() async {
    setState(() {
      _alignMode = _alignMode == 'left'
          ? 'center'
          : _alignMode == 'center'
              ? 'right'
              : 'left';
    });
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('textEditorAlignMode', _alignMode);
    } catch (_) {}
  }

  // ─── MCP からの編集適用 (= ユーザー要望: MCP で中身を編集できる AI) ───
  /// [edits] をまとめて検証してから適用する。 成功なら null、 失敗なら
  /// 理由 (英文 = AI へ返すエラー) を返す。 途中失敗で中途半端に書き
  /// 換わらないよう、 検証は全件先に済ませる。
  String? _applyMcpEdits(List<Map<String, dynamic>> edits) {
    if (!mounted) return 'the text editor was closed';
    if (edits.isEmpty) return 'edits is empty';
    _commitEdit();
    final hasSetAll = edits.any((e) => '${e['action']}' == 'set_all');
    if (hasSetAll && edits.length > 1) {
      return 'set_all must be the only edit in the call';
    }
    final len = _lines.length;
    for (final e in edits) {
      final action = '${e['action'] ?? ''}';
      final start = (e['start'] as num?)?.toInt();
      final end = (e['end'] as num?)?.toInt() ?? start;
      switch (action) {
        case 'set_all':
          if (e['text'] is! String) return 'set_all requires "text"';
          break;
        case 'insert':
          if (start == null || start < 1 || start > len + 1) {
            return 'insert: start out of range (1..${len + 1}): $start';
          }
          if (e['text'] is! String) return 'insert requires "text"';
          break;
        case 'replace':
          if (start == null ||
              end == null ||
              start < 1 ||
              end < start ||
              end > len) {
            return 'replace: bad range start=$start end=$end '
                '(file has $len lines)';
          }
          if (e['text'] is! String) return 'replace requires "text"';
          break;
        case 'delete':
          if (start == null ||
              end == null ||
              start < 1 ||
              end < start ||
              end > len) {
            return 'delete: bad range start=$start end=$end '
                '(file has $len lines)';
          }
          break;
        default:
          return 'unknown action: "$action" '
              '(use replace / insert / delete / set_all)';
      }
    }
    _pushUndo();
    String normalize(Object? t) =>
        '${t ?? ''}'.replaceAll('\r\n', '\n').replaceAll('\r', '\n');
    if (hasSetAll) {
      final text = normalize(edits.first['text']);
      _lines
        ..clear()
        ..addAll(text.split('\n'));
    } else {
      // 下の行から適用すれば、 前方の行番号が崩れない。
      final sorted = [...edits]..sort((a, b) =>
          ((b['start'] as num).toInt()).compareTo((a['start'] as num).toInt()));
      for (final e in sorted) {
        final action = '${e['action']}';
        final start = (e['start'] as num).toInt();
        final end = (e['end'] as num?)?.toInt() ?? start;
        switch (action) {
          case 'insert':
            _lines.insertAll(start - 1, normalize(e['text']).split('\n'));
            break;
          case 'replace':
            _lines.replaceRange(start - 1, end, normalize(e['text']).split('\n'));
            break;
          case 'delete':
            _lines.removeRange(start - 1, end);
            break;
        }
      }
    }
    if (_lines.isEmpty) _lines.add('');
    setState(() {});
    _markDirty();
    return null;
  }

  // ─── 音声読み上げ (TTS) (= ユーザー要望: テキストファイルの音声読み上げ) ───
  ReadAloudController? _reader;
  bool _readerVisible = false;

  /// 本文全体を音声で読み上げる。
  Future<void> _startReadAloud() async {
    final text = _lines.join('\n').trim();
    final messenger = ScaffoldMessenger.maybeOf(context);
    if (text.isEmpty) {
      messenger?.showSnackBar(SnackBar(
          content: Text(context.read<MindMapProvider>().t('tts.noText')),
          duration: Duration(seconds: 2)));
      return;
    }
    final loc = context.read<MindMapProvider>().speechLocaleId;
    _reader ??= ReadAloudController(language: loc);
    setState(() => _readerVisible = true);
    final ok = await _reader!.start(text);
    if (!mounted) return;
    if (!ok) {
      setState(() => _readerVisible = false);
      messenger?.showSnackBar(SnackBar(
          content:
              Text(context.read<MindMapProvider>().t('pdf.ttsUnavailable')),
          duration: const Duration(seconds: 3)));
    }
  }

  void _stopReadAloud() {
    _reader?.stop();
    if (mounted) setState(() => _readerVisible = false);
  }

  // ─── 読み込み ───────────────────────────────────────────────────
  Future<void> _loadFile() async {
    try {
      String text;
      try {
        text = await File(_currentFilePath).readAsString();
      } catch (_) {
        final bytes = await File(_currentFilePath).readAsBytes();
        text = String.fromCharCodes(bytes);
      }
      if (text.startsWith('\uFEFF')) text = text.substring(1);
      // 改行コードを LF に正規化
      text = text.replaceAll('\r\n', '\n').replaceAll('\r', '\n');
      _lines
        ..clear()
        ..addAll(text.split('\n'));
      // 空ファイルでも 1 行表示
      if (_lines.isEmpty) _lines.add('');
      _loadedHash = _fullText.hashCode.toString();
      if (mounted) setState(() => _loading = false);
    } catch (e, st) {
      debugPrint('TextEditor load error: $e\n$st');
      if (mounted) {
        setState(() {
          _loading = false;
          _loadError = '$e';
        });
      }
    }
  }

  String get _fullText => _lines.join('\n');

  void _markDirty() {
    final h = _fullText.hashCode.toString();
    final newDirty = h != _loadedHash;
    if (newDirty != _dirty) {
      setState(() => _dirty = newDirty);
    }
    // 分割プレビュー中は内容変更を反映 (= ユーザー要望: 発展案)。
    _scheduleSplitPreviewUpdate();
  }

  /// プレビューへ渡す本文 (編集中の行は入力欄の現在値を使う)。
  String _previewSourceText() {
    if (_editingIdx == null) return _lines.join('\n');
    final copy = List<String>.from(_lines);
    if (_editingIdx! < copy.length) copy[_editingIdx!] = _editCtrl.text;
    return copy.join('\n');
  }

  // ─── 複数行の範囲選択 (= ユーザー要望) ──────────────────────────
  /// 選択している行の範囲 (両端を含む)。 選択が無ければ null。
  ({int start, int end})? get _selRange {
    final a = _selAnchorLine;
    final b = _selFocusLine;
    if (a == null || b == null || _lines.isEmpty) return null;
    final st = math.min(a, b).clamp(0, _lines.length - 1);
    final en = math.max(a, b).clamp(0, _lines.length - 1);
    return (start: st, end: en);
  }

  bool _isLineSelected(int idx) {
    final r = _selRange;
    return r != null && idx >= r.start && idx <= r.end;
  }

  void _clearLineSelection() {
    if (_selAnchorLine == null && _selFocusLine == null) return;
    setState(() {
      _selAnchorLine = null;
      _selFocusLine = null;
    });
  }

  /// Ctrl+Shift+↑ / ↓ で選択範囲を 1 行伸ばす (縮める)。
  /// 編集中に押した時は、 その行を確定してから選択に移る。
  /// メモ欄や AI 欄の入力中は本文の行選択を働かせない
  /// (同じ Focus の下にぶら下がっているので、 素通しにすると
  /// そちらの文字入力を奪ってしまう)。
  bool get _bodyHasFocus =>
      _keyFocus.hasPrimaryFocus || _editFocus.hasPrimaryFocus;

  bool _extendLineSelection(int delta) {
    if (_lines.isEmpty || !_bodyHasFocus) return false;
    final base = _selFocusLine ?? _editingIdx ?? 0;
    final next = (base + delta).clamp(0, _lines.length - 1);
    if (_editingIdx != null) _commitEdit();
    setState(() {
      _selAnchorLine ??= base;
      _selFocusLine = next;
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _keyFocus.requestFocus();
      _ensureLineVisible(next, downward: delta > 0);
    });
    return true;
  }

  /// 選択している行を続きの文字列にする (行区切りは改行)。
  String get _selectedLinesText {
    final r = _selRange;
    if (r == null) return '';
    return _lines.sublist(r.start, r.end + 1).join('\n');
  }

  Future<void> _copySelectedLines() async {
    final t = _selectedLinesText;
    if (t.isEmpty) return;
    await Clipboard.setData(ClipboardData(text: t));
  }

  void _deleteSelectedLines() {
    final r = _selRange;
    if (r == null) return;
    _pushUndo();
    _lines.removeRange(r.start, r.end + 1);
    if (_lines.isEmpty) _lines.add('');
    setState(() {
      _selAnchorLine = null;
      _selFocusLine = null;
      _editingIdx = null;
    });
    _markDirty();
  }

  /// 貼り付け (選択中なら置き換え)。 複数行はそのまま行に割り付ける。
  Future<void> _pasteIntoSelection() async {
    final data = await Clipboard.getData(Clipboard.kTextPlain);
    final text = data?.text;
    if (text == null || text.isEmpty) return;
    final r = _selRange;
    _pushUndo();
    final add = text.replaceAll('\r\n', '\n').split('\n');
    final at = r?.start ?? (_editingIdx ?? _lines.length);
    if (r != null) _lines.removeRange(r.start, r.end + 1);
    _lines.insertAll(at.clamp(0, _lines.length), add);
    setState(() {
      _selAnchorLine = at;
      _selFocusLine = at + add.length - 1;
      _editingIdx = null;
    });
    _markDirty();
  }

  /// 指定した行を必ず画面の中に入れる。
  ///
  /// = ユーザー要望「カーソルが画面外に出た時の追跡が遅く鈍いので、 敏感に
  ///   素早く反応するように」。 入力欄まかせの追従はアニメーション付きで
  ///   一拍遅れるため、 時間 0 で引き戻し、 さらに 1 行半ぶんの余白を足して
  ///   画面の縁に貼り付かないようにする。
  void _ensureLineVisible(int idx, {bool downward = true}) {
    if (!_scroll.hasClients) return;
    final pos = _scroll.position;
    if (pos.viewportDimension <= 0) return;
    final margin = _lineHeight * 1.5;
    final ctx = _curLineKey.currentContext;
    if (ctx != null) {
      // 行の高さは折り返しで変わるので、 実物の位置から求めるのが正確。
      final before = pos.pixels;
      Scrollable.ensureVisible(
        ctx,
        duration: Duration.zero,
        alignmentPolicy: downward
            ? ScrollPositionAlignmentPolicy.keepVisibleAtEnd
            : ScrollPositionAlignmentPolicy.keepVisibleAtStart,
      );
      final after = pos.pixels;
      if ((after - before).abs() > 0.5) {
        final t = (after + (after > before ? margin : -margin))
            .clamp(pos.minScrollExtent, pos.maxScrollExtent);
        if ((t - after).abs() > 0.5) _scroll.jumpTo(t);
      }
      return;
    }
    // まだ組み立てられていない (画面から遠い) 行は行高から見当を付ける。
    final top = idx * _lineHeight;
    final bottom = top + _lineHeight;
    var target = pos.pixels;
    if (top - margin < pos.pixels) {
      target = top - margin;
    } else if (bottom + margin > pos.pixels + pos.viewportDimension) {
      target = bottom + margin - pos.viewportDimension;
    }
    target = target.clamp(pos.minScrollExtent, pos.maxScrollExtent);
    if ((target - pos.pixels).abs() > 0.5) _scroll.jumpTo(target);
  }

  // ─── 編集 ───────────────────────────────────────────────────────
  /// [caret] を渡すとその文字位置にカーソルを置く (= ユーザー要望:
  /// クリックした場所がすぐ編集できるように)。 省略時は行末。
  void _beginEditLine(int idx, {int? caret}) {
    if (idx < 0 || idx >= _lines.length) return;
    _pushUndo();
    _commitEdit();
    final off =
        (caret ?? _lines[idx].length).clamp(0, _lines[idx].length).toInt();
    final down = _editingIdx == null || idx >= _editingIdx!;
    setState(() {
      _editingIdx = idx;
      _editOriginal = _lines[idx];
      _editCtrl.text = _lines[idx];
      _editCtrl.selection = TextSelection.collapsed(offset: off);
      // 行を編集し始めたら、 まとめ選択は解く。
      _selAnchorLine = null;
      _selFocusLine = null;
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _editFocus.requestFocus();
      // 入力欄まかせの追従は一拍遅れるので、 自分で即座に引き戻す
      // (= ユーザー要望: カーソルの追従を敏感に素早く)。
      _ensureLineVisible(idx, downward: down);
      // ★ デスクトップの TextField はフォーカスを渡した瞬間に「全選択」
      //   になる (= ユーザー報告: クリックすると最初ブロック選択になって
      //   1 テンポ遅れる)。 フォーカスが乗った次のフレームでクリック位置の
      //   カーソルに置き直し、 最初から入力できる状態にする。
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || _editingIdx != idx) return;
        _editCtrl.selection = TextSelection.collapsed(offset: off);
      });
    });
  }

  void _commitEdit() {
    final idx = _editingIdx;
    if (idx == null) return;
    if (idx < _lines.length) {
      final newVal = _editCtrl.text;
      if (newVal != _editOriginal) {
        _lines[idx] = newVal;
      }
    }
    setState(() => _editingIdx = null);
    _markDirty();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _keyFocus.requestFocus();
    });
  }

  void _cancelEdit() {
    setState(() => _editingIdx = null);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _keyFocus.requestFocus();
    });
  }

  /// 編集中行で Enter — カーソル位置で行を分割し、 次の行を編集モードに。
  void _splitLineAtCursor() {
    final idx = _editingIdx;
    if (idx == null) return;
    _pushUndo();
    final cursorPos =
        _editCtrl.selection.baseOffset.clamp(0, _editCtrl.text.length);
    final before = _editCtrl.text.substring(0, cursorPos);
    final after = _editCtrl.text.substring(cursorPos);
    _lines[idx] = before;
    _lines.insert(idx + 1, after);
    setState(() {
      _editingIdx = idx + 1;
      _editOriginal = after;
      _editCtrl.text = after;
      _editCtrl.selection = const TextSelection.collapsed(offset: 0);
    });
    _markDirty();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _editFocus.requestFocus();
      _ensureLineVisible(idx + 1);
    });
  }

  /// 編集中行頭で Backspace — 前の行と結合。
  void _mergeWithPrev() {
    final idx = _editingIdx;
    if (idx == null || idx == 0) return;
    _pushUndo();
    final prevLen = _lines[idx - 1].length;
    _lines[idx - 1] = _lines[idx - 1] + _editCtrl.text;
    _lines.removeAt(idx);
    setState(() {
      _editingIdx = idx - 1;
      _editOriginal = _lines[idx - 1];
      _editCtrl.text = _lines[idx - 1];
      _editCtrl.selection = TextSelection.collapsed(offset: prevLen);
    });
    _markDirty();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _editFocus.requestFocus();
      _ensureLineVisible(idx - 1, downward: false);
    });
  }

  /// 末尾に空行を追加して編集モードへ。
  void _appendBlankLine() {
    _pushUndo();
    _commitEdit();
    _lines.add('');
    _markDirty();
    _beginEditLine(_lines.length - 1);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _scroll.animateTo(
        _scroll.position.maxScrollExtent,
        duration: const Duration(milliseconds: 200),
        curve: Curves.easeOut,
      );
    });
  }

  // ─── 保存 ───────────────────────────────────────────────────────
  Future<void> _save() async {
    try {
      _commitEdit();
      await File(_currentFilePath).writeAsString(_fullText, flush: true);
      _loadedHash = _fullText.hashCode.toString();
      if (!mounted) return;
      setState(() => _dirty = false);
      widget.onSaved?.call();
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        SnackBar(
          backgroundColor: const Color(0xFF1A1A2E),
          content: Text(
              context
                  .read<MindMapProvider>()
                  .t('doc.saved')
                  .replaceFirst('{name}', _currentFileName),
              style: const TextStyle(color: Colors.white)),
          duration: const Duration(seconds: 2),
        ),
      );
    } catch (e) {
      _showSnackBar('保存に失敗: $e');
    }
  }

  Future<bool> _confirmDiscard({BuildContext? anchor}) async {
    if (!_dirty) return true;
    // × ボタンの近く + フローティング窓の上に出す (= ユーザー要望)。
    final r = await _showUnsavedConfirmNear(anchor ?? context);
    if (r == 'save') {
      await _save();
      return true;
    }
    return r == 'discard';
  }

  // ─── キーボードショートカット ────────────────────────────────────
  KeyEventResult _onKey(FocusNode node, KeyEvent event) {
    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
      return KeyEventResult.ignored;
    }
    final isCtrl = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    final isShift = HardwareKeyboard.instance.isShiftPressed;
    // ── Ctrl+Shift+↑ / ↓ = 複数行の範囲選択 (= ユーザー要望) ──
    //    1 行ずつの入力欄なので、 行をまたぐ選択は自前で持つ。
    if (isCtrl &&
        isShift &&
        (event.logicalKey == LogicalKeyboardKey.arrowUp ||
            event.logicalKey == LogicalKeyboardKey.arrowDown)) {
      if (_extendLineSelection(
          event.logicalKey == LogicalKeyboardKey.arrowDown ? 1 : -1)) {
        return KeyEventResult.handled;
      }
    }
    // ── 選択している行に対する操作 ──
    final selRange = _bodyHasFocus ? _selRange : null;
    if (selRange != null) {
      if (event.logicalKey == LogicalKeyboardKey.escape) {
        _clearLineSelection();
        return KeyEventResult.handled;
      }
      if (isCtrl && event.logicalKey == LogicalKeyboardKey.keyC) {
        // ignore: discarded_futures
        _copySelectedLines();
        return KeyEventResult.handled;
      }
      if (isCtrl && event.logicalKey == LogicalKeyboardKey.keyX) {
        // ignore: discarded_futures
        _copySelectedLines().then((_) {
          if (mounted) _deleteSelectedLines();
        });
        return KeyEventResult.handled;
      }
      if (isCtrl && event.logicalKey == LogicalKeyboardKey.keyV) {
        // ignore: discarded_futures
        _pasteIntoSelection();
        return KeyEventResult.handled;
      }
      if (event.logicalKey == LogicalKeyboardKey.delete ||
          event.logicalKey == LogicalKeyboardKey.backspace) {
        _deleteSelectedLines();
        return KeyEventResult.handled;
      }
      // 矢印 / Enter で選択を解いて、 その行の編集に戻る。
      if (event.logicalKey == LogicalKeyboardKey.arrowUp ||
          event.logicalKey == LogicalKeyboardKey.arrowDown ||
          event.logicalKey == LogicalKeyboardKey.enter ||
          event.logicalKey == LogicalKeyboardKey.numpadEnter) {
        final go = (_selFocusLine ?? selRange.start)
            .clamp(0, _lines.length - 1);
        _clearLineSelection();
        _beginEditLine(go);
        return KeyEventResult.handled;
      }
    }
    if (isCtrl && event.logicalKey == LogicalKeyboardKey.keyS) {
      _save();
      return KeyEventResult.handled;
    }
    // Ctrl+Z = Undo, Ctrl+Shift+Z = Redo
    if (isCtrl && event.logicalKey == LogicalKeyboardKey.keyZ) {
      if (isShift) {
        _redo();
      } else {
        _undo();
      }
      return KeyEventResult.handled;
    }
    // Ctrl+Y = Redo (Windows 慣習)
    if (isCtrl && event.logicalKey == LogicalKeyboardKey.keyY) {
      _redo();
      return KeyEventResult.handled;
    }
    // Ctrl+Shift+N = 新規フリーメモの編集画面 (= ユーザー要望)
    if (isCtrl && isShift && event.logicalKey == LogicalKeyboardKey.keyN) {
      // ignore: discarded_futures
      _openFreeMemoDialogFromEditor();
      return KeyEventResult.handled;
    }
    // ── Esc で閉じない設定 (= ユーザー要望: 開いた画面が Esc で閉じるのを
    //    止めたい)。 消費して既定の「ダイアログを閉じる」 へ流さない。 ──
    if (event.logicalKey == LogicalKeyboardKey.escape &&
        !context.read<MindMapProvider>().closeViewerWithEsc) {
      return KeyEventResult.handled;
    }
    return KeyEventResult.ignored;
  }

  // ─── リネーム ───────────────────────────────────────────────────
  Future<void> _showRenameDialog() async {
    final ctrl = TextEditingController(text: _currentFileName);
    final newName = await showDialog<String>(
      context: context,
      builder: (dctx) {
        return AlertDialog(
          backgroundColor:
              widget.isDarkMode ? const Color(0xFF22222E) : Colors.white,
          title: Row(children: [
            const Icon(Icons.drive_file_rename_outline_rounded,
                color: Color(0xFF6C63FF)),
            const SizedBox(width: 8),
            Text(context.read<MindMapProvider>().t('doc.renameFile')),
          ]),
          content: SizedBox(
            width: 380,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  '新しいファイル名を入力してください。\n'
                  '拡張子は元のまま'
                  '${_currentFileName.contains('.') ? ' (.${_currentFileName.split('.').last})' : ''}'
                  ' になります。',
                  style: TextStyle(
                    fontSize: 12,
                    color: widget.isDarkMode ? Colors.white60 : Colors.black54,
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: ctrl,
                  autofocus: true,
                  decoration: InputDecoration(
                    hintText: context.read<MindMapProvider>().t('doc.fileName'),
                    border: OutlineInputBorder(),
                  ),
                  onSubmitted: (_) => Navigator.of(dctx).pop(ctrl.text),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
              child: Text(context.read<MindMapProvider>().t('btn.cancel')),
            ),
            FilledButton(
              onPressed: () => Navigator.of(dctx).pop(ctrl.text),
              child: Text(context.read<MindMapProvider>().t('btn.change')),
            ),
          ],
        );
      },
    );
    if (newName == null) return;
    final input = newName.trim();
    if (input.isEmpty || input == _currentFileName) return;
    if (input.contains('/') || input.contains('\\')) {
      _showSnackBar('ファイル名にパス区切り文字 ( / \\ ) は使えません');
      return;
    }
    final origExt = _currentFileName.contains('.')
        ? _currentFileName.substring(_currentFileName.lastIndexOf('.'))
        : '';
    String fixed = input;
    if (origExt.isNotEmpty &&
        !fixed.toLowerCase().endsWith(origExt.toLowerCase())) {
      if (fixed.contains('.')) {
        fixed = '${fixed.substring(0, fixed.lastIndexOf('.'))}$origExt';
      } else {
        fixed = '$fixed$origExt';
      }
    }
    try {
      if (_dirty) await _save();
      final oldFile = File(_currentFilePath);
      if (!await oldFile.exists()) {
        _showSnackBar('元ファイルが見つかりません');
        return;
      }
      final sep = _currentFilePath.contains('\\') ? '\\' : '/';
      final dirEnd = _currentFilePath.lastIndexOf(sep);
      final dir = dirEnd >= 0 ? _currentFilePath.substring(0, dirEnd) : '';
      final newPath = dir.isEmpty ? fixed : '$dir$sep$fixed';
      if (await File(newPath).exists() && newPath != _currentFilePath) {
        _showSnackBar('同名のファイルが既に存在します');
        return;
      }
      final renamed = await oldFile.rename(newPath);
      setState(() {
        _currentFilePath = renamed.path;
        _currentFileName = fixed;
        _language = _detectLanguage(fixed);
      });
      widget.onRenamed?.call(renamed.path, fixed);
      _showSnackBar('ファイル名を変更しました: $fixed');
    } catch (e) {
      _showSnackBar('ファイル名変更に失敗: $e');
    }
  }

  void _showSnackBar(String msg) {
    if (!mounted) return;
    ScaffoldMessenger.maybeOf(context)?.showSnackBar(SnackBar(
      content: Text(msg),
      duration: const Duration(seconds: 3),
    ));
  }

  // ─── AI 編集 ────────────────────────────────────────────────────
