                ),
                // ── 添付中のファイル (= ユーザー要望) ──
                if (_aiPendingFiles.isNotEmpty) ...[
                  const SizedBox(height: 8),
                  Wrap(spacing: 4, runSpacing: 4, children: [
                    for (var i = 0; i < _aiPendingFiles.length; i++)
                      Container(
