                        decoration: BoxDecoration(
                          color: widget.isDarkMode
                              ? const Color(0xFF262636)
                              : const Color(0xFFEDEDE6),
                          borderRadius: BorderRadius.circular(10),
                          border: Border.all(
                              color: widget.isDarkMode
                                  ? Colors.white12
                                  : Colors.black12),
                        ),
                        child:
                            Row(mainAxisSize: MainAxisSize.min, children: [
                          Icon(
                              _aiPendingFiles[i].isImage
                                  ? Icons.image_rounded
                                  : Icons.description_rounded,
                              size: 12,
                              color: const Color(0xFF4FC3F7)),
                          const SizedBox(width: 4),
                          ConstrainedBox(
                            constraints:
                                const BoxConstraints(maxWidth: 140),
                            child: Text(_aiPendingFiles[i].name,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(fontSize: 10.5)),
                          ),
                          InkWell(
                            onTap: () =>
                                setD(() => _aiPendingFiles.removeAt(i)),
                            child: const Padding(
                              padding: EdgeInsets.all(2),
                              child: Icon(Icons.close_rounded, size: 12),
                            ),
                          ),
                        ]),
                      ),
                  ]),
                ],
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
              child: Text(context.read<MindMapProvider>().t('btn.cancel')),
            ),
            FilledButton.icon(
              icon: const Icon(Icons.auto_awesome_rounded, size: 16),
              label: Text(context.read<MindMapProvider>().t('doc.aiExecute')),
              style: FilledButton.styleFrom(
                backgroundColor: const Color(0xFFAB47BC),
                foregroundColor: Colors.white,
              ),
              onPressed: () => Navigator.of(dctx).pop(ctrl.text),
            ),
          ],
        );
        });
      },
    );
    if (instruction == null || instruction.trim().isEmpty) return;
    await _applyAiEdit(instruction.trim());
  }

  Future<void> _applyAiEdit(String instruction) async {
    setState(() => _aiBusy = true);
    try {
      _commitEdit();
      final currentText = _fullText;
      // ── 添付 (画像 / テキストファイル) を組み立てる (= ユーザー要望:
      //    AI で書き換えるにもファイルを上げられるように)。 ──
      final images = <AiInputImage>[];
      final attachNote = StringBuffer();
      final pendingFiles =
          List<({String path, String name, bool isImage})>.from(
              _aiPendingFiles);
      _aiPendingFiles.clear();
      for (final f in pendingFiles) {
        try {
          if (f.isImage) {
            final bytes = await File(f.path).readAsBytes();
            final ext = f.name.contains('.')
                ? f.name.substring(f.name.lastIndexOf('.') + 1)
                : 'png';
            images.add(AiInputImage(
                mime: AiInputImage.mimeForExt(ext),
                base64: base64Encode(bytes),
                name: f.name));
          } else {
            var body = await File(f.path).readAsString();
            if (body.length > 12000) {
              body = '${body.substring(0, 12000)}\n…(長いので省略)';
            }
            attachNote.writeln('\n【添付ファイル ${f.name}】\n$body');
          }
        } catch (_) {}
      }
      final prompt =
          '''以下のファイル ($_currentFileName、 言語: $_language) の内容を、 ユーザーの指示に従って書き換え、 書き換え後の内容だけを返してください。

- 説明文・コードブロック (\`\`\`) ・前後のテキストは一切含めず、 ファイル本体のテキストだけを返す
- 元のファイル形式 / 言語の構文を尊重する
- 改行コードは LF
- 大きく削減・追加してよいが、 元の意図を保つ

【ユーザーの指示】
$instruction
$attachNote
【現在の内容】
$currentText
''';
      final provider = context.read<MindMapProvider>();
      final response = await provider.askAi(prompt,
          images: images.isEmpty ? null : images);
      final cleaned = _SpreadsheetEditorDialogState._stripCodeFence(response);
      if (cleaned.trim().isEmpty) {
        throw Exception('AI が空の応答を返しました');
      }
      _aiUndoSnapshot = currentText;
      _lines
        ..clear()
        ..addAll(cleaned.replaceAll('\r\n', '\n').split('\n'));
      if (_lines.isEmpty) _lines.add('');
      _markDirty();
      if (mounted) {
        setState(() {});
        // 「AI 編集を適用しました」 の通知は出さない (= ユーザー要望)。
        //   本文が書き換わるのは見れば分かるため。 取り消しは Ctrl+Z 等の
        //   通常の編集操作で行う。
      }
    } catch (e) {
      _showSnackBar('AI 編集に失敗: $e');
    } finally {
      if (mounted) setState(() => _aiBusy = false);
    }
  }

  void _undoAiEdit() {
    final snap = _aiUndoSnapshot;
    if (snap == null) return;
    setState(() {
      _lines
        ..clear()
        ..addAll(snap.split('\n'));
      if (_lines.isEmpty) _lines.add('');
      _aiUndoSnapshot = null;
      _markDirty();
    });
    ScaffoldMessenger.maybeOf(context)?.hideCurrentSnackBar();
  }

  // ─── 言語検出 ───────────────────────────────────────────────────
  String _detectLanguage(String fileName) {
    final l = fileName.toLowerCase();
    final lower = l.split(RegExp(r'[/\\]')).last;
    if (lower == 'dockerfile') return 'Docker';
    if (lower == 'makefile') return 'Makefile';
    final ext = l.contains('.') ? l.substring(l.lastIndexOf('.') + 1) : '';
    const map = {
      'py': 'Python',
      'pyw': 'Python',
      'dart': 'Dart',
      'js': 'JavaScript',
      'mjs': 'JavaScript',
      'cjs': 'JavaScript',
      'ts': 'TypeScript',
      'tsx': 'TypeScript',
      'jsx': 'JavaScript',
      'vue': 'Vue',
      'html': 'HTML',
      'htm': 'HTML',
      'css': 'CSS',
      'scss': 'SCSS',
      'sass': 'Sass',
      'less': 'Less',
      'java': 'Java',
      'kt': 'Kotlin',
      'kts': 'Kotlin',
      'scala': 'Scala',
      'c': 'C',
      'h': 'C',
      'cpp': 'C++',
      'cc': 'C++',
      'cxx': 'C++',
      'hpp': 'C++',
      'hh': 'C++',
      'hxx': 'C++',
      'cs': 'C#',
      'go': 'Go',
      'rb': 'Ruby',
      'rs': 'Rust',
      'swift': 'Swift',
      'php': 'PHP',
      'lua': 'Lua',
      'r': 'R',
      'pl': 'Perl',
      'pm': 'Perl',
      'tcl': 'Tcl',
      'hs': 'Haskell',
      'ex': 'Elixir',
      'exs': 'Elixir',
      'sh': 'Shell',
      'bash': 'Bash',
      'zsh': 'Zsh',
      'fish': 'Fish',
      'bat': 'Batch',
      'cmd': 'Batch',
      'ps1': 'PowerShell',
      'sql': 'SQL',
      'json': 'JSON',
      'yml': 'YAML',
      'yaml': 'YAML',
      'xml': 'XML',
      'toml': 'TOML',
      'ini': 'INI',
      'md': 'Markdown',
      'markdown': 'Markdown',
      'rst': 'reST',
      'tex': 'LaTeX',
      'gradle': 'Gradle',
      'cmake': 'CMake',
      'txt': 'Text',
      'log': 'Log',
      'env': 'env',
      'conf': 'conf',
      'config': 'conf',
    };
    return map[ext] ?? 'text';
  }

  Color _languageColor(String lang) {
    switch (lang) {
      case 'Dart':
        return const Color(0xFF02569B);
      case 'JavaScript':
      case 'TypeScript':
        return const Color(0xFFF7DF1E);
      case 'Python':
        return const Color(0xFF3776AB);
      case 'Go':
        return const Color(0xFF00ADD8);
      case 'Rust':
        return const Color(0xFFCE412B);
      case 'Java':
      case 'Kotlin':
        return const Color(0xFFEF6C00);
      case 'C':
      case 'C++':
      case 'C#':
        return const Color(0xFF5C6BC0);
      case 'Ruby':
        return const Color(0xFFCC342D);
      case 'Swift':
        return const Color(0xFFFA7343);
      case 'PHP':
        return const Color(0xFF777BB4);
      case 'HTML':
        return const Color(0xFFE34F26);
      case 'CSS':
      case 'SCSS':
      case 'Sass':
      case 'Less':
        return const Color(0xFF1572B6);
      case 'Markdown':
      case 'reST':
      case 'LaTeX':
        return const Color(0xFF6C63FF);
      case 'JSON':
      case 'YAML':
      case 'XML':
      case 'TOML':
      case 'INI':
        return const Color(0xFF607D8B);
      case 'Shell':
      case 'Bash':
      case 'Zsh':
      case 'Fish':
      case 'Batch':
      case 'PowerShell':
        return const Color(0xFF4CAF50);
      case 'SQL':
        return const Color(0xFFFF9800);
      case 'Docker':
        return const Color(0xFF2496ED);
      case 'Makefile':
      case 'CMake':
      case 'Gradle':
        return const Color(0xFF795548);
      default:
        return const Color(0xFF9E9E9E);
