  }

  IconData _languageIcon(String lang) {
    switch (lang) {
      case 'Markdown':
      case 'reST':
      case 'Text':
      case 'Log':
        return Icons.article_outlined;
      case 'JSON':
      case 'YAML':
      case 'XML':
      case 'TOML':
      case 'INI':
        return Icons.data_object_rounded;
      case 'HTML':
        return Icons.html_rounded;
      case 'CSS':
      case 'SCSS':
      case 'Sass':
      case 'Less':
        return Icons.css_rounded;
      case 'Shell':
      case 'Bash':
      case 'Zsh':
      case 'Fish':
      case 'Batch':
      case 'PowerShell':
        return Icons.terminal_rounded;
      case 'SQL':
        return Icons.storage_rounded;
      case 'Docker':
        return Icons.developer_board_rounded;
      case 'LaTeX':
        return Icons.functions_rounded;
      default:
        return Icons.code_rounded;
    }
  }

  // ─── ビルド ─────────────────────────────────────────────────────
  @override
  Widget build(BuildContext context) {
    final dark = widget.isDarkMode;
    final fg = dark ? Colors.white : const Color(0xFF1A1A24);
    Widget body;
    if (_loading) {
      body = const Center(child: CircularProgressIndicator());
    } else if (_loadError != null) {
      body = Center(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(Icons.error_outline_rounded,
                  color: Colors.redAccent, size: 48),
              const SizedBox(height: 12),
              Text(
                  context
                      .read<MindMapProvider>()
                      .t('doc.loadError')
                      .replaceFirst('{err}', '$_loadError'),
                  style: TextStyle(color: fg),
                  textAlign: TextAlign.center),
              const SizedBox(height: 16),
              FilledButton.icon(
                onPressed: () async {
                  if (_currentFilePath.isEmpty) {
                    ScaffoldMessenger.maybeOf(context)?.showSnackBar(
                      SnackBar(
                        backgroundColor: const Color(0xFFE57373),
                        content: Text(context
                            .read<MindMapProvider>()
                            .t('pptx.notSavedYet')),
                      ),
                    );
                    return;
                  }
                  try {
                    final r = await OpenFilex.open(_currentFilePath);
                    if (r.type != ResultType.done && mounted) {
                      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
                        SnackBar(
                          backgroundColor: const Color(0xFFE57373),
                          content: Text(context
                              .read<MindMapProvider>()
                              .t('pptx.cannotOpenExternal')
                              .replaceFirst('{err}', '${r.message}')),
                        ),
                      );
                    }
                  } catch (e) {
                    if (mounted) {
                      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
                        SnackBar(
                          backgroundColor: const Color(0xFFE57373),
                          content: Text(context
                              .read<MindMapProvider>()
                              .t('pptx.externalLaunchFailed')
                              .replaceFirst('{err}', '$e')),
                        ),
                      );
                    }
                  }
                },
                icon: const Icon(Icons.open_in_new_rounded, size: 16),
                label: Text(
                    context.read<MindMapProvider>().t('pptx.openExternal')),
              ),
            ],
          ),
        ),
      );
    } else if (_mdSplitView && _isPreviewableFile) {
      // 編集×プレビューの左右分割 (= ユーザー要望: 発展案)。
      body = Row(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Expanded(child: _buildEditor(dark, fg)),
          Container(width: 1, color: dark ? Colors.white12 : Colors.black12),
          Expanded(child: _buildMdPreviewBody()),
        ],
      );
    } else if (_mdPreview && _isPreviewableFile) {
      // Markdown / HTML プレビュー (= ユーザー要望: Mermaid 記法も描画。
      //   HTML は書いた物をそのまま表示)。
      body = _buildMdPreviewBody();
    } else if (_mathPreview && _mathCapable) {
      body = _buildMathPreview(dark, fg);
    } else {
      body = _buildEditor(dark, fg);
    }
    // ── Esc で閉じないようにする (= ユーザー要望: 編集中に閉じられると
    //    厄介)。 Focus はフォーカスがどこにも無い時に取りこぼすので、
    //    ダイアログ枠からの「閉じて」 も PopScope で押さえる。 ──
    // 埋め込みで使われている時 (画面分割のペインの中など) は、 アプリ本体の
    // 画面と入れ物を共有しているので横取りしない (= 横取りすると Android の
    // 戻るでアプリ本体まで閉じてしまう)。
    return PopScope(
      canPop: !_ownsCloseRoute(context),
      onPopInvokedWithResult: (didPop, _) {
        if (didPop || !mounted) return;
        if (_isEscClosePressed(context)) return;
        unawaited(() async {
          if (await _confirmDiscard()) {
            if (mounted) Navigator.of(context).pop();
          }
        }());
      },
      child: Focus(
      focusNode: _keyFocus,
      onKeyEvent: _onKey,
      child: Container(
        color: dark ? const Color(0xFF1A1A24) : const Color(0xFFD8D8D4),
        child: Column(
          children: [
            // ── ヘッダーのボタン列は隠せる (= ユーザー要望: ヘッダー自体は
            //    残し、 ボタンだけ隠す。 カーソルを乗せると表示ボタンが出る)。
            _buildHeader(dark, fg),
            Expanded(
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  // ── 左: メモパネル (= ユーザー要望: PDF ビューアの様な
                  //    メモ欄。 境界ドラッグで幅可変) ──
                  if (_isDesktopEditor && _memoPanelOpen) ...[
                    _buildMemoPanel(dark, fg),
                    _panelResizeHandle(left: true),
                  ],
                  Expanded(
                    child: Stack(
                      children: [
                        Positioned.fill(child: body),
                        // ── 音声読み上げ操作バー (= ユーザー要望) ──
                        if (_readerVisible && _reader != null)
                          Positioned(
                            left: 0,
                            right: 0,
                            bottom: 14,
                            child: Center(
                              child: ReadAloudBar(
                                controller: _reader!,
                                onClose: _stopReadAloud,
                              ),
                            ),
                          ),
                        // (ヘッダー非表示中の再表示は、 ヘッダーへカーソルを
                        //  乗せた時に出るボタンに変更 = ユーザー要望)
                      ],
                    ),
                  ),
                  // ── 右: AI チャットパネル (= ユーザー要望: PDF ビューアの
                  //    様な AI 欄 + MCP でファイルを編集できる AI。
                  //    境界ドラッグで幅可変) ──
                  if (_isDesktopEditor && _aiPanelOpen) ...[
                    _panelResizeHandle(left: false),
                    _buildAiChatPanel(dark, fg),
                  ],
                ],
              ),
            ),
            _buildStatusBar(dark, fg),
          ],
        ),
      ),
      ),
    );
  }

  /// ヘッダーのボタン列を隠している時、 カーソルが乗っているか
  /// (= ユーザー要望: カーソルを持ってきたら表示ボタンが出る)。
  bool _headerBtnHover = false;

  Widget _buildHeader(bool dark, Color fg) {
    // ── ヘッダーを隠している時はファイル名ごと全て隠し、 細いバーだけ残す
    //    (= ユーザー要望: ヘッダーを隠すを押したらファイル名の所まで
    //    隠れるように)。 ホバー / タップで元に戻す。 ──
    if (!_headerVisible) {
      return MouseRegion(
        onEnter: (_) {
          if (!_headerBtnHover) setState(() => _headerBtnHover = true);
        },
        onExit: (_) {
          if (_headerBtnHover) setState(() => _headerBtnHover = false);
        },
        child: GestureDetector(
          onTap: () => setState(() => _headerVisible = true),
          behavior: HitTestBehavior.opaque,
          child: Container(
            height: 16,
            decoration: BoxDecoration(
              color: dark ? const Color(0xFF22222E) : const Color(0xFFE0E0DA),
              border: Border(
                bottom: BorderSide(
                    color: dark ? Colors.white12 : Colors.black12),
              ),
            ),
            alignment: Alignment.center,
            child: _headerBtnHover
                ? Icon(Icons.keyboard_double_arrow_down_rounded,
                    size: 14, color: fg.withValues(alpha: 0.8))
                : null,
          ),
        ),
      );
    }
    return MouseRegion(
      onEnter: (_) {
        if (!_headerVisible && !_headerBtnHover) {
          setState(() => _headerBtnHover = true);
        }
      },
      onExit: (_) {
        if (_headerBtnHover) setState(() => _headerBtnHover = false);
      },
      child: GestureDetector(
        // タッチ端末はホバーが無いので、 隠している時はタップで戻す。
        onTap: _headerVisible
            ? null
            : () => setState(() => _headerVisible = true),
        child: Container(
      height: 52,
      padding: const EdgeInsets.symmetric(horizontal: 12),
      decoration: BoxDecoration(
        color: dark ? const Color(0xFF22222E) : const Color(0xFFE0E0DA),
        border: Border(
          bottom: BorderSide(color: dark ? Colors.white12 : Colors.black12),
        ),
      ),
      child: Row(
        children: [
          Icon(_languageIcon(_language), color: _languageColor(_language)),
          const SizedBox(width: 8),
          // タイトルは固定幅にする (= Flexible だと中央ボタン領域と
          //   余白を取り合って中央がズレるため)。
          ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 240),
            child: InkWell(
              onTap: _showRenameDialog,
              borderRadius: BorderRadius.circular(6),
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Flexible(
                      child: Text(_currentFileName,
                          style: TextStyle(
                              color: fg,
                              fontSize: 15,
                              fontWeight: FontWeight.w600),
                          overflow: TextOverflow.ellipsis),
                    ),
                    const SizedBox(width: 4),
                    Icon(Icons.edit_outlined,
                        size: 14, color: fg.withValues(alpha: 0.5)),
                  ],
                ),
              ),
            ),
          ),
          const SizedBox(width: 8),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
            decoration: BoxDecoration(
              color: _languageColor(_language).withValues(alpha: 0.18),
              borderRadius: BorderRadius.circular(10),
            ),
            child: Text(
              _language,
              style: TextStyle(
                color: _languageColor(_language),
                fontSize: 11,
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
          if (_dirty)
            Container(
              margin: const EdgeInsets.only(left: 8),
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
              // ★ 白いヘッダーの上では黄色の文字が読めないので、 塗り潰した
              //   帯に白抜きの文字にする (= ユーザー要望: 未保存の文字が
              //   黄色で見にくい)。 暗い配色でも同じように読める。
              decoration: BoxDecoration(
                color: const Color(0xFFD84315),
                borderRadius: BorderRadius.circular(10),
              ),
              child: Text(context.read<MindMapProvider>().t('doc.unsaved'),
                  style: const TextStyle(
                      color: Colors.white,
                      fontSize: 11,
                      fontWeight: FontWeight.w700)),
            ),
          // ── ボタン列はヘッダー中央に置く (= ユーザー要望)。 隠して
          //    いる間はホバー時だけ「表示する」 ボタンを出す。 ──
          Expanded(
            child: !_headerVisible
                ? Align(
                    alignment: Alignment.centerRight,
                    child: _headerBtnHover
                        ? IconButton(
                            tooltip: context
                                .read<MindMapProvider>()
                                .t('text.showHeader'),
                            icon: Icon(
                                Icons.keyboard_double_arrow_down_rounded,
                                color: fg.withValues(alpha: 0.8)),
                            onPressed: () =>
                                setState(() => _headerVisible = true),
                          )
                        : const SizedBox.shrink(),
                  )
                : Center(
                    child: SingleChildScrollView(
                      scrollDirection: Axis.horizontal,
                      child:
                          Row(mainAxisSize: MainAxisSize.min, children: [
          // ── 揃え切替: 左 → 中央 → 右 の循環 (= ユーザー要望: 既定は
          //    左揃え、 右揃えもできるように)。 ツールチップは「押したら
          //    次にどうなるか」 を出す。 ──
          IconButton(
            tooltip: context.read<MindMapProvider>().t(_alignMode == 'left'
                ? 'text.alignCenter'
                : _alignMode == 'center'
                    ? 'text.alignRight'
                    : 'text.alignLeft'),
            icon: Icon(
              _alignMode == 'center'
                  ? Icons.format_align_center_rounded
                  : _alignMode == 'right'
                      ? Icons.format_align_right_rounded
                      : Icons.format_align_left_rounded,
              color: _alignMode == 'left'
                  ? fg.withValues(alpha: 0.7)
                  : const Color(0xFF4DB6AC),
            ),
            onPressed: _toggleCenterAlign,
          ),
          // ── メモパネル (= ユーザー要望: PDF ビューアの様なメモ欄) ──
          if (_isDesktopEditor)
            IconButton(
              tooltip: context.read<MindMapProvider>().t('text.memoPanel'),
              icon: Icon(
                Icons.sticky_note_2_outlined,
                color: _memoPanelOpen
                    ? const Color(0xFFFFB347)
                    : fg.withValues(alpha: 0.7),
              ),
              onPressed: () =>
                  setState(() => _memoPanelOpen = !_memoPanelOpen),
            ),
          // ── AI チャットパネル (= ユーザー要望: ブラウザ版 AI + MCP 編集 AI) ──
          if (_isDesktopEditor)
            IconButton(
              tooltip: context.read<MindMapProvider>().t('text.aiPanel'),
              // ── アイコンはキラキラの紫 (= ユーザー要望: 他の画面の
              //    AI ボタンと見た目を揃える) ──
              icon: Icon(
                Icons.auto_awesome_rounded,
                color: _aiPanelOpen
                    ? const Color(0xFFAB47BC)
                    : const Color(0xFFAB47BC).withValues(alpha: 0.75),
              ),
              onPressed: () {
                if (_aiPanelOpen) {
                  setState(() {
                    _aiPanelOpen = false;
                    _aiWebCache = null; // ★ フリーズ対策
                    _aiWinCtrl = null;
                  });
                } else {
                  // 既定のブラウザ AI (PDF ビューアと共有) で開く。
                  _openTextAiPanel(
                      context.read<MindMapProvider>().pdfAiPanelDefault);
                }
              },
            ),
          // (ダウンロードは保存ボタンの右に移した = ユーザー要望)
          // ── プレビュー切替 (.md は Mermaid 記法も描画、 .html は書いた
          //    ページをそのまま表示 = ユーザー要望) ──
          if (_isPreviewableFile)
            IconButton(
              tooltip: context.read<MindMapProvider>().t('md.togglePreview'),
              icon: Icon(
                // プレビューは目のアイコンを使わない (= ユーザー要望)。
                _mdPreview ? Icons.edit_rounded : Icons.wysiwyg_rounded,
                color: _mdPreview
                    ? const Color(0xFF4DB6AC)
                    : fg.withValues(alpha: 0.7),
              ),
              onPressed: () {
                // ignore: discarded_futures
                _toggleMdPreview();
              },
            ),
          // ── 編集×プレビューの左右分割 (= ユーザー要望: 発展案) ──
          if (_isPreviewableFile && _isDesktopEditor)
            IconButton(
              tooltip: context.read<MindMapProvider>().t('md.splitView'),
              icon: Icon(
                Icons.vertical_split_rounded,
                color: _mdSplitView
                    ? const Color(0xFF4DB6AC)
                    : fg.withValues(alpha: 0.7),
              ),
              onPressed: () {
                // ignore: discarded_futures
                _toggleMdSplitView();
              },
            ),
          // 数式プレビューモード切替 (対応拡張子のみ)
          if (_mathCapable)
            IconButton(
              tooltip: context.read<MindMapProvider>().t(
                  _mathPreview ? 'text.mathPreviewOff' : 'text.mathPreviewOn'),
              icon: Icon(
                // 数式プレビューは目のアイコンを使わない (= ユーザー要望)。
                _mathPreview ? Icons.edit_rounded : Icons.functions_rounded,
                color: _mathPreview
                    ? const Color(0xFFAB47BC)
                    : fg.withValues(alpha: 0.7),
              ),
              onPressed: () {
                _commitEdit();
                setState(() {
                  _mathPreview = !_mathPreview;
                  if (_mathPreview) _mdPreview = false;
                });
              },
            ),
          // ── LaTeX 数式を挿入 (= ユーザー要望: Word の数式挿入ボタンを
          //    テキストファイルにも) ──
          if (_mathCapable)
            IconButton(
              tooltip:
                  context.read<MindMapProvider>().t('docx.insertFormula'),
              icon: Icon(Icons.superscript_rounded,
                  color: fg.withValues(alpha: 0.7)),
              onPressed: () => unawaited(_insertMathText()),
            ),
          // 音声読み上げ (= ユーザー要望: テキストファイルの音声読み上げ)
          IconButton(
            tooltip: context.read<MindMapProvider>().t(
                _readerVisible ? 'text.readAloudStop' : 'text.readAloud'),
            icon: Icon(
              _readerVisible
                  ? Icons.stop_circle_rounded
                  : Icons.record_voice_over_rounded,
              color: _readerVisible
                  ? const Color(0xFFFF6B6B)
                  : const Color(0xFF4FC3F7),
            ),
            onPressed: _readerVisible ? _stopReadAloud : _startReadAloud,
          ),
          // (「AI で書き換える」 ボタンは廃止 = ユーザー要望: 右パネルの
          //  AI編集と同じ機能のため。 AI編集は AI パネルから使う)
          // ── 保存はまわりに合わせてアイコンだけ (= ユーザー要望)。
          //    ホバーの案内は「上書き保存」。 ──
          IconButton(
            tooltip: context.read<MindMapProvider>().t('tip.saveOverwrite'),
            icon: const Icon(Icons.save_rounded, color: Color(0xFF6C63FF)),
            onPressed: _save,
          ),
          // ── ダウンロード (= ユーザー要望: 保存ボタンの右に置く) ──
          PopupMenuButton<String>(
            tooltip: context.read<MindMapProvider>().t('fsv.download'),
            icon: Icon(Icons.download_rounded, color: fg),
            color: dark ? const Color(0xFF22222E) : Colors.white,
            onSelected: (v) async {
              if (v == 'same') {
                await _downloadTextCopy();
              } else if (v == 'pdf') {
                await _downloadTextAsPdf();
              }
            },
            itemBuilder: (_) => [
              PopupMenuItem(
                value: 'same',
                child: Row(children: [
                  Icon(_languageIcon(_language),
                      size: 16, color: _languageColor(_language)),
                  const SizedBox(width: 8),
                  Text('このまま保存', style: TextStyle(color: fg, fontSize: 13)),
                ]),
              ),
              PopupMenuItem(
                value: 'pdf',
                child: Row(children: [
                  const Icon(Icons.picture_as_pdf_outlined,
                      size: 16, color: Color(0xFFFF6B6B)),
                  const SizedBox(width: 8),
                  Text(
                      _isPreviewableFile
                          ? 'PDF に変換 (プレビューの内容)'
                          : 'PDF に変換',
                      style: TextStyle(color: fg, fontSize: 13)),
                ]),
              ),
            ],
          ),
          IconButton(
            tooltip: context.read<MindMapProvider>().t('pptx.openExternal'),
            icon: Icon(Icons.open_in_new_rounded, color: fg),
            onPressed: () async {
              if (_currentFilePath.isEmpty) {
                ScaffoldMessenger.maybeOf(context)?.showSnackBar(
                  SnackBar(
                    backgroundColor: const Color(0xFFE57373),
                    content: Text(
                        context.read<MindMapProvider>().t('pptx.notSavedYet')),
                  ),
                );
                return;
              }
              try {
                final r = await OpenFilex.open(_currentFilePath);
                if (r.type != ResultType.done && mounted) {
                  ScaffoldMessenger.maybeOf(context)?.showSnackBar(
                    SnackBar(
                      backgroundColor: const Color(0xFFE57373),
                      content: Text(context
                          .read<MindMapProvider>()
                          .t('pptx.cannotOpenExternal')
                          .replaceFirst('{err}', '${r.message}')),
                    ),
                  );
                }
              } catch (e) {
                if (mounted) {
                  ScaffoldMessenger.maybeOf(context)?.showSnackBar(
                    SnackBar(
                      backgroundColor: const Color(0xFFE57373),
                      content: Text(context
                          .read<MindMapProvider>()
                          .t('pptx.externalLaunchFailed')
                          .replaceFirst('{err}', '$e')),
                    ),
                  );
                }
              }
            },
          ),
          // ── ヘッダーを隠す (= ユーザー要望: 閉じるボタンの隣に配置) ──
          IconButton(
            tooltip: context.read<MindMapProvider>().t('text.hideHeader'),
            icon: Icon(Icons.keyboard_double_arrow_up_rounded,
                color: fg.withValues(alpha: 0.7)),
            onPressed: () => setState(() => _headerVisible = false),
          ),
          // Builder で × ボタン自身の context を取り、 未保存確認をその
          // すぐ近くに出す (= ユーザー要望: × の近くに出るように)。
          Builder(
            builder: (btnCtx) => IconButton(
              tooltip: context.read<MindMapProvider>().t('btn.close'),
              icon: Icon(Icons.close_rounded, color: fg),
              onPressed: () async {
                if (await _confirmDiscard(anchor: btnCtx)) {
                  if (mounted) Navigator.of(context).pop();
                }
              },
            ),
          ),
                      ]),
                    ),
                  ),
          ),
        ],
      ),
        ), // Container 閉じ
      ), // GestureDetector 閉じ
    ); // MouseRegion 閉じ
  }

  Widget _buildStatusBar(bool dark, Color fg) {
    return Container(
      height: 24,
      padding: const EdgeInsets.symmetric(horizontal: 12),
      decoration: BoxDecoration(
        color: dark ? const Color(0xFF1E1E2A) : const Color(0xFFE8E8E2),
        border: Border(
          top: BorderSide(color: dark ? Colors.white12 : Colors.black12),
        ),
      ),
      alignment: Alignment.centerLeft,
      child: Text(
        '$_language  •  ${_lines.length} 行  •  ${_fullText.length} 文字',
        style: TextStyle(
          color: fg.withValues(alpha: 0.6),
          fontSize: 11,
          fontFamily: 'monospace',
        ),
      ),
    );
  }

  // ─── メモパネル (= ユーザー要望: PDF ビューアと同じメモ欄) ─────────────
  // 添付元ノードの PdfMemo をそのまま使うので、 フォルダ / ピン / 編集 /
  // 貼り付け / AI へ送る、 など PDF ビューアのメモ欄と完全に同じ機能になる。

  /// いま画面の一番上に見えている行 (1 始まり)。 メモの行アンカーに使う。
  int _currentTopLine() {
    if (_editingIdx != null) return _editingIdx! + 1;
    if (!_scroll.hasClients) return 1;
    final line = (_scroll.offset / _lineHeight).floor() + 1;
    return line.clamp(1, _lines.isEmpty ? 1 : _lines.length);
  }

  /// メモに控えた行へジャンプ (折り返しがあると多少ずれるが目安として十分)。
  void _jumpToMemoLine(PdfMemo memo) {
    final page = memo.pageNumber;
    if (page == null || !_scroll.hasClients) return;
    _scroll.animateTo(
      ((page - 1) * _lineHeight).clamp(0.0, _scroll.position.maxScrollExtent),
      duration: const Duration(milliseconds: 250),
      curve: Curves.easeOut,
    );
  }

  /// ノード未紐付けの時に「ページに追加」 でノード化する (= PDF ビューアの
  /// _ensureNode と同じ仕組み。 ユーザー要望: アプリで開くとメモが書けない)。
  Future<String?> _ensureTextNode({String? pageId}) async {
    final cur = _nodeId;
    if (cur != null) return cur;
    final cb = widget.onEnsureNode;
    if (cb == null) return null;
    final id = await cb(pageId: pageId);
    if (id != null && mounted) setState(() => _nodeId = id);
    return id;
  }

  /// このファイルを別の場所へコピー保存する (= ユーザー要望:
  /// テキストにもダウンロードボタンを)。
  Future<void> _downloadTextCopy() async {
    try {
      _commitEdit();
      final text = _lines.join('\n');
      final defaultName = _currentFileName;
      final ext = defaultName.contains('.')
          ? defaultName.substring(defaultName.lastIndexOf('.') + 1)
          : 'txt';
      String? outPath;
      if (_isDesktopEditor) {
        outPath = await FilePicker.platform.saveFile(
          dialogTitle: context.read<MindMapProvider>().t('fsv.download'),
          fileName: defaultName,
          type: FileType.custom,
          allowedExtensions: [ext],
        );
        if (outPath == null) return;
        await File(outPath).writeAsString(text, flush: true);
      } else {
        final dir = await getApplicationDocumentsDirectory();
        final exportDir = Directory('${dir.path}/exports');
        if (!await exportDir.exists()) await exportDir.create(recursive: true);
        outPath = '${exportDir.path}/$defaultName';
        await File(outPath).writeAsString(text, flush: true);
        await OpenFilex.open(outPath);
      }
      _showSnackBar('ダウンロード完了: $outPath');
    } catch (e) {
      _showSnackBar('ダウンロードに失敗: $e');
    }
  }

  /// 中身を PDF にして保存する (= ユーザー要望: プレビューモードで PDF に
  /// 変換できるように)。 Markdown は見出し / 箇条書きを整えて、 HTML は
  /// タグを外した中身を出す。
  Future<void> _downloadTextAsPdf() async {
    final provider = context.read<MindMapProvider>();
    try {
      _commitEdit();
      final ok = await _PdfExporter.ensureJapaneseFontOrConfirm(context);
      if (!ok) return;
      _showSnackBar(provider.t('video.exporting'));
      final bytes = await _PdfExporter.exportPlainLines(
        _lines,
        markdown: _isMarkdownFile,
        html: _isHtmlFile,
      );
      final base = _currentFileName.contains('.')
          ? _currentFileName.substring(0, _currentFileName.lastIndexOf('.'))
          : _currentFileName;
      final defaultName = '$base.pdf';
      String? outPath;
      if (_isDesktopEditor) {
        outPath = await FilePicker.platform.saveFile(
          dialogTitle: provider.t('pptx.saveAsPdf'),
          fileName: defaultName,
          type: FileType.custom,
          allowedExtensions: ['pdf'],
        );
        if (outPath == null) return;
        if (!outPath.toLowerCase().endsWith('.pdf')) outPath = '$outPath.pdf';
        await File(outPath).writeAsBytes(bytes, flush: true);
      } else {
        final dir = await getApplicationDocumentsDirectory();
        final exportDir = Directory('${dir.path}/exports');
        if (!await exportDir.exists()) await exportDir.create(recursive: true);
        outPath = '${exportDir.path}/$defaultName';
        await File(outPath).writeAsBytes(bytes, flush: true);
        await OpenFilex.open(outPath);
      }
      _showSnackBar('PDF にしました: $outPath');
    } catch (e) {
      _showSnackBar('PDF にできませんでした: $e');
    }
  }

  /// 追加先のページを選んでから追加する (= PDF ビューアと同じ UI)。
  /// ページが 1 つしかない時はそのまま追加する。
  Future<String?> _ensureTextNodeWithPagePicker(BuildContext btnCtx) async {
    final cur = _nodeId;
    if (cur != null) return cur;
    final provider = context.read<MindMapProvider>();
    final targets = provider.pages
        .where((p) => p.pageType == 'normal' || p.pageType == 'bookshelf')
        .toList();
    if (targets.length <= 1) return _ensureTextNode();
    final curId = provider.currentPage.id;
    final box = btnCtx.findRenderObject() as RenderBox?;
    final pos =
        box == null ? const Offset(80, 80) : box.localToGlobal(Offset.zero);
    final chosen = await showMenu<String>(
      context: btnCtx,
      position: RelativeRect.fromLTRB(
          pos.dx - 160, pos.dy + 28, pos.dx + 1, pos.dy + 29),
      color: const Color(0xFF1E2430),
      items: [
        PopupMenuItem<String>(
          enabled: false,
          height: 30,
          child: Text(provider.t('openWith.choosePage'),
              style: const TextStyle(
                  color: Color(0xFF8FA6B4),
                  fontSize: 11,
                  fontWeight: FontWeight.w700)),
        ),
        for (final pg in targets)
          PopupMenuItem<String>(
            value: pg.id,
            height: 36,
            child: Row(children: [
              Icon(
                  pg.id == curId
                      ? Icons.radio_button_checked_rounded
                      : _MindMapScreenState._pageKindIconOf(pg).$1,
                  size: 15,
                  color: pg.id == curId
                      ? const Color(0xFF43B97F)
                      : _MindMapScreenState._pageKindIconOf(pg).$2),
              const SizedBox(width: 8),
              Flexible(
                child: Text(pg.name,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style:
                        const TextStyle(color: Colors.white, fontSize: 12.5)),
              ),
            ]),
          ),
      ],
    );
    if (chosen == null) return null;
    return _ensureTextNode(pageId: chosen);
  }

  /// Ctrl+Shift+N: 新規フリーメモの編集画面を開く (= ユーザー要望)。
  /// ノード未紐付けなら先に「ページに追加」 の流れでノード化する。
  Future<void> _openFreeMemoDialogFromEditor() async {
    var nid = _nodeId;
    nid ??= await _ensureTextNode();
    if (nid == null) {
      if (mounted) {
        _showSnackBar(
            context.read<MindMapProvider>().t('openWith.memoNeedsNode'));
        setState(() => _memoPanelOpen = true);
      }
      return;
    }
    if (!mounted) return;
    // 結果がすぐ見えるようにメモ欄も開く。
    if (!_memoPanelOpen) setState(() => _memoPanelOpen = true);
    final provider = context.read<MindMapProvider>();
    final created = await showDialog<PdfMemo?>(
      context: context,
      builder: (_) => const _PdfMemoEditDialog(freeMode: true),
    );
    if (created != null && mounted) {
      provider.addPdfMemo(
        nid,
        text: created.text,
        pageNumber: created.pageNumber,
        colorValue: created.colorValue,
      );
    }
  }

  /// メモの本文で YouTube 検索を開く (= ユーザー要望: PDF ビューアと同じ)。
  void _openMemoYoutubeSearchFromEditor(PdfMemo memo) {
    if (!Platform.isWindows) return;
    final text = memo.text
        .split('\n')
        .where((l) => !l.startsWith(_kMemoImgPrefix))
        .join('\n')
        .trim();
    if (text.isEmpty) return;
    final url = 'https://www.youtube.com/results?search_query='
        '${Uri.encodeQueryComponent(text)}';
    showDialog<void>(
      context: context,
      barrierColor: Colors.black.withValues(alpha: 0.75),
      builder: (_) => Dialog(
        backgroundColor: Colors.transparent,
        // ほぼ全画面で開く (= ユーザー要望: もう少し大きく)。
        insetPadding: const EdgeInsets.symmetric(horizontal: 20, vertical: 14),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(16),
          child: _WindowsWebViewSheet(
            url: url,
            forceHome: true,
            focusMode: false,
          ),
        ),
      ),
    );
  }

  /// パネルの幅を変えるドラッグハンドル (= ユーザー要望: 表示領域の境界を
  /// 動かせるように)。 [left] = ハンドルが左パネル (メモ欄) 用かどうか。
  Widget _panelResizeHandle({required bool left}) {
    return MouseRegion(
      cursor: SystemMouseCursors.resizeColumn,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onHorizontalDragUpdate: (d) {
          setState(() {
            if (left) {
              _memoPanelW = (_memoPanelW + d.delta.dx).clamp(200.0, 560.0);
            } else {
              _aiPanelW = (_aiPanelW - d.delta.dx).clamp(240.0, 640.0);
            }
          });
        },
        child: Container(
          width: 6,
          color: Colors.transparent,
          alignment: Alignment.center,
          child: Container(width: 2, color: Colors.white12),
        ),
      ),
    );
  }

  Widget _buildMemoPanel(bool dark, Color fg) {
    final provider = context.read<MindMapProvider>();
    final nodeId = _nodeId;
    final hasNode = nodeId != null && provider.nodes[nodeId] != null;
    return Container(
      width: _memoPanelW,
      decoration: const BoxDecoration(
        color: Color(0xFF1E1E32),
        border: Border(right: BorderSide(color: Colors.white24)),
      ),
      child: !hasNode
          // ノード未紐付け (= アプリで開く)。 「ページに追加」 でノード化
          // すればメモが書ける (= PDF ビューアと同じ導線。 ユーザー要望)。
          ? Padding(
              padding: const EdgeInsets.all(16),
              child: Center(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Icon(Icons.sticky_note_2_outlined,
                        color: Color(0xFFFFC107), size: 34),
                    const SizedBox(height: 10),
                    Text(provider.t('openWith.memoNeedsNode'),
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                            color: Colors.white70,
                            fontSize: 12,
                            height: 1.5)),
                    if (widget.onEnsureNode != null) ...[
                      const SizedBox(height: 12),
                      Builder(builder: (btnCtx) {
                        return ElevatedButton.icon(
                          style: ElevatedButton.styleFrom(
                            backgroundColor: const Color(0xFF43B97F),
                            foregroundColor: Colors.white,
                            padding: const EdgeInsets.symmetric(
                                horizontal: 14, vertical: 8),
                          ),
                          icon: const Icon(Icons.add_to_photos_rounded,
                              size: 16),
                          label: Text(provider.t('openWith.addToPage'),
                              style: const TextStyle(fontSize: 12)),
                          onPressed: () async {
                            await _ensureTextNodeWithPagePicker(btnCtx);
                          },
                        );
                      }),
                    ],
                  ],
                ),
              ),
            )
          : _PdfMemoPanel(
              nodeId: nodeId,
              isPdf: false,
              currentPage: _currentTopLine(),
              currentUrl: _currentFilePath,
              highlightMemoId: null,
              onJumpToMemo: _jumpToMemoLine,
              // 「ここにメモ」 = 今見えている行をアンカーにして空メモを作る。
              onAddHere: () {
                provider.addPdfMemo(nodeId, pageNumber: _currentTopLine());
              },
              onClosePanel: () => setState(() => _memoPanelOpen = false),
              onSendMemoToAi: _sendMemoToBrowserAi,
              // メモの本文で YouTube 検索 (= ユーザー要望)。
              onSearchYoutube: _openMemoYoutubeSearchFromEditor,
              // メモをまとめて AI に送る (= ユーザー要望)。
              onSendAllToAi: _sendTextToBrowserAi,
            ),
    );
  }

  // ─── ブラウザ版 AI チャット欄 (= ユーザー要望: API キーを叩くものでは
  //     なく、 ブラウザ版 (ChatGPT / Gemini 等) が開かれるように)。
  //     PDF ビューアの AI 欄と同じ仕組みで、 既定 AI (pdfAiPanelDefault) も
  //     共有する。 「AI編集」 (MCP でファイルを書き換えるチャット) は
  //     この上にオーバーレイで重ねる (WebView を作り直さないため)。 ───────

  static const Map<String, String> _kBrowserAiUrls = {
    'chatgpt': 'https://chatgpt.com/',
    'gemini': 'https://gemini.google.com/app',
    'claude': 'https://claude.ai/',
    'deepseek': 'https://chat.deepseek.com/',
    'grok': 'https://grok.com/',
  };

  String get _textAiPanelLabel {
    final u = _aiPanelUrl.toLowerCase();
    if (u.contains('chatgpt') || u.contains('openai')) return 'ChatGPT';
    if (u.contains('gemini')) return 'Gemini';
    if (u.contains('claude')) return 'Claude';
    if (u.contains('deepseek')) return 'DeepSeek';
    if (u.contains('grok') || u.contains('x.ai')) return 'Grok';
    return 'AI';
  }

  /// ブラウザ AI を開く / 切り替える。 選んだ AI は PDF ビューアと同じ
  /// 既定 (pdfAiPanelDefault) として永続化する。
  void _openTextAiPanel(String aiId) {
    final url = _kBrowserAiUrls[aiId];
    if (url == null) return;
    setState(() {
      _aiPanelUrl = url;
      _aiPanelOpen = true;
    });
    try {
      context.read<MindMapProvider>().setPdfAiPanelDefault(aiId);
    } catch (_) {}
    if (Platform.isWindows) {
      try {
        _aiWinCtrl?.loadUrl(url);
      } catch (_) {}
    }
  }

  /// 毎回 AI に渡す「前提条件」 の編集 (= ユーザー要望: AI モデル切替の所に
  /// 設定項目を付ける)。 PDF ビューア・メモ→AI と同じ
  /// `provider.browserAiPrefix` を共有する。
  Future<void> _showTextAiPrefixDialog() async {
    if (!mounted) return;
    final provider = context.read<MindMapProvider>();
    final ctrl = TextEditingController(text: provider.browserAiPrefix);
    final saved = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('ai.prereqTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: SizedBox(
          width: 340,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Align(
              alignment: Alignment.centerLeft,
              child: Text(provider.t('ai.prefixDescApi'),
                  style: const TextStyle(color: Colors.white54, fontSize: 12)),
            ),
            const SizedBox(height: 10),
            TextField(
              controller: ctrl,
              autofocus: true,
              minLines: 2,
              maxLines: 5,
              style: const TextStyle(color: Colors.white, fontSize: 13),
              decoration: InputDecoration(
                hintText: provider.t('ai.prefixHint'),
                hintStyle: const TextStyle(color: Colors.white24, fontSize: 12),
                filled: true,
                fillColor: Colors.white.withValues(alpha: 0.06),
                border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(8),
                    borderSide: BorderSide.none),
              ),
            ),
          ]),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, '__cancel__'),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          TextButton(
            onPressed: () => Navigator.pop(dctx, ''),
            child: Text(provider.t('btn.clear'),
                style: const TextStyle(color: Color(0xFFFF8A80))),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFBA68C8),
                foregroundColor: Colors.white),
            onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
            child: Text(provider.t('btn.save')),
          ),
        ],
      ),
    );
    ctrl.dispose();
    if (saved == null || saved == '__cancel__') return;
    await provider.setBrowserAiPrefix(saved);
    if (mounted) {
      _showSnackBar(saved.isEmpty ? '前提条件をクリアしました' : '前提条件を保存しました');
    }
  }

  /// AI 欄のホイールスクロール (webview_windows はホイールを内部に転送
  /// しないことがあるため、 PDF ビューアと同じく JS で直接動かす)。
  void _scrollTextAiPanelByWheel(PointerSignalEvent event) {
    if (event is! PointerScrollEvent) return;
    if (!Platform.isWindows) return;
    final dx = event.scrollDelta.dx.round();
    final dy = event.scrollDelta.dy.round();
    if (dx == 0 && dy == 0) return;
    try {
      _aiWinCtrl?.executeScript(_webWheelScrollJs(dx, dy));
    } catch (_) {}
  }

  /// メモの本文をブラウザ AI の入力欄へ流し込む (= PDF ビューアのメモ欄と
  /// 同じ「AI に送る」)。 クリップボードにも常にコピーする (挿入失敗時の
  /// フォールバック)。
  void _sendMemoToBrowserAi(PdfMemo memo) {
    // 画像マーカー行を除いた本文と、 貼ってある画像ファイルを取り出す。
    final (imgPath, rawBody) = _parseMemoImage(memo.text);
    final body = rawBody
        .split('\n')
        .where((l) => !l.startsWith(_kMemoImgPrefix))
        .join('\n')
        .trim();
    final hasImg = imgPath != null && imgPath.trim().isNotEmpty;
    if (body.isEmpty && !hasImg) {
      _showSnackBar(context.read<MindMapProvider>().t('ai.memoEmpty'));
      return;
    }
    // ── 画像だけのメモでも送れるようにする (= ユーザー要望: メモ欄の
    //    画像を AI チャットへ。 文字に変換せず画像ファイルのまま添付) ──
    if (body.isNotEmpty) {
      _sendTextToBrowserAi(body);
    } else {
      // 文字が無い時も AI 欄だけは開いておく (画像を貼り込む先が要る)。
      final provider = context.read<MindMapProvider>();
      if (!(_aiPanelOpen && _aiPanelUrl.isNotEmpty)) {
        _openTextAiPanel(provider.pdfAiPanelDefault);
      }
      if (_aiEditChatMode) setState(() => _aiEditChatMode = false);
    }
    if (hasImg) unawaited(_attachImageToBrowserAi(imgPath));
  }

  /// メモに貼ってある画像ファイルを、 ブラウザ版 AI の入力欄へ
  /// **画像のまま** 添付する (= ユーザー要望)。 base64 で読み込んで
  /// ページ側で File を組み立て、 paste / drop イベントを合成する。
  Future<void> _attachImageToBrowserAi(String imgPath) async {
    if (!Platform.isWindows) return;
    try {
      final f = File(imgPath);
      if (!await f.exists()) return;
      final b64 = base64Encode(await f.readAsBytes());
      final lower = imgPath.toLowerCase();
      final mime = lower.endsWith('.png')
          ? 'image/png'
          : (lower.endsWith('.jpg') || lower.endsWith('.jpeg'))
              ? 'image/jpeg'
              : lower.endsWith('.gif')
                  ? 'image/gif'
                  : lower.endsWith('.webp')
                      ? 'image/webp'
                      : 'image/png';
      // AI 欄を開いた直後は描画が終わっていないので、 間を置いて数回試す。
      final wasOpen = _aiPanelOpen && _aiPanelUrl.isNotEmpty;
      final base = wasOpen
          ? const Duration(milliseconds: 400)
          : const Duration(milliseconds: 1800);
      Future.delayed(base, () => _injectImageToTextAi(b64, mime));
      Future.delayed(base + const Duration(milliseconds: 1600),
          () => _injectImageToTextAi(b64, mime));
    } catch (_) {}
  }

  /// テキストをブラウザ AI へ渡す共通処理 (= 単発メモ /「まとめて送る」 の
  /// 両方から使う)。
  void _sendTextToBrowserAi(String text) {
    final t = text.trim();
    if (t.isEmpty) return;
    final provider = context.read<MindMapProvider>();
    Clipboard.setData(ClipboardData(text: t));
    final wasOpen = _aiPanelOpen && _aiPanelUrl.isNotEmpty;
    if (!wasOpen) _openTextAiPanel(provider.pdfAiPanelDefault);
    // ブラウザ面を前に出す (AI編集オーバーレイが被っていたら下げる)。
    if (_aiEditChatMode) setState(() => _aiEditChatMode = false);
    final sendText = provider.browserAiApplyPrefix(t);
    final token = ++_aiInjectSeq;
    final initial = wasOpen
        ? const Duration(milliseconds: 300)
        : const Duration(milliseconds: 1500);
    Future.delayed(initial, () => _injectTextToTextAi(sendText, token));
    Future.delayed(initial + const Duration(milliseconds: 1200),
        () => _injectTextToTextAi(sendText, token));
    Future.delayed(initial + const Duration(milliseconds: 2800),
        () => _injectTextToTextAi(sendText, token));
  }

  /// AI サイトの入力欄へテキストを挿入する JS (PDF ビューアの
  /// _injectTextToAi と同じもの。 token で重複挿入を防ぐ)。
  void _injectTextToTextAi(String text, int token) {
    if (!mounted || !Platform.isWindows) return;
    final escaped = jsonEncode(text);
    final js = '''
(function() {
  try {
    if (window.__mmTxtAiToken === $token) return 'dup';
    var text = $escaped;
    var ceSelectors = [
      'div.ProseMirror[contenteditable="true"]',
      '#prompt-textarea',
      'div[contenteditable="true"].ql-editor',
      'div[contenteditable="true"]',
    ];
    function visibleArea(el) {
      var r = el.getBoundingClientRect();
      if (r.width < 80 || r.height < 16) return 0;
      if (r.bottom < 0 || r.top > window.innerHeight) return 0;
      return r.width * r.height;
    }
    function moveCursorToEnd(el) {
      el.focus();
      try {
        var range = document.createRange();
        range.selectNodeContents(el);
        range.collapse(false);
        var sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
      } catch (e) {}
    }
    var best = null;
    var bestArea = 0;
    for (var i = 0; i < ceSelectors.length; i++) {
      var nodes = document.querySelectorAll(ceSelectors[i]);
      for (var j = 0; j < nodes.length; j++) {
        var n = nodes[j];
        var a = visibleArea(n);
        if (a > bestArea) { bestArea = a; best = n; }
      }
      if (best) break;
    }
    if (best) {
      var existing = (best.innerText || best.textContent || '').trim();
      moveCursorToEnd(best);
      var prefix = existing.length > 0 ? '\\n' : '';
      try {
        document.execCommand('insertText', false, prefix + text);
      } catch (e) {
        best.innerText = (existing + prefix + text);
        best.dispatchEvent(new InputEvent('input', { bubbles: true, data: text }));
      }
      window.__mmTxtAiToken = $token;
      return 'ok-ce';
    }
    var taList = document.querySelectorAll('textarea, input[type="text"]');
    var bestTa = null;
    var bestTaArea = 0;
    for (var k = 0; k < taList.length; k++) {
      var t = taList[k];
      var ta = visibleArea(t);
      if (ta > bestTaArea) { bestTaArea = ta; bestTa = t; }
    }
    if (bestTa) {
      bestTa.focus();
      var existing = bestTa.value || '';
      var prefix = existing.length > 0 ? '\\n' : '';
      var newVal = existing + prefix + text;
      var proto = bestTa.tagName === 'TEXTAREA'
        ? window.HTMLTextAreaElement.prototype
        : window.HTMLInputElement.prototype;
      var setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
      setter.call(bestTa, newVal);
      bestTa.dispatchEvent(new Event('input', { bubbles: true }));
      try {
        bestTa.selectionStart = bestTa.selectionEnd = newVal.length;
      } catch (e) {}
      window.__mmTxtAiToken = $token;
      return 'ok-ta';
    }
    return 'not-found';
  } catch (e) {
    return 'error: ' + e;
  }
})();
''';
    try {
      _aiWinCtrl?.executeScript(js);
    } catch (_) {}
  }

  /// AI サイトの入力欄へ画像を添付する JS (PDF ビューアの
  /// `_injectImageToAi` と同じもの)。 base64 → File を組み立てて
  /// paste / drop を合成し、 サイト側に「画像を貼られた」 と認識させる。
  int _txtAiImgSeq = 0;
  void _injectImageToTextAi(String base64Img, String mime) {
    if (!mounted || !Platform.isWindows) return;
    final token = ++_txtAiImgSeq;
    final escB64 = jsonEncode(base64Img);
    final escMime = jsonEncode(mime);
    final js = '''
(function() {
  try {
    // 同じ画像の二重添付を防ぐ (リトライで複数回呼ばれるため)。
    if (window.__mmTxtAiImgToken === $token) return 'dup';
    var b64 = $escB64;
    var mime = $escMime;
    var bin = atob(b64);
    var arr = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    var blob = new Blob([arr], { type: mime });
    var ext = mime.split('/')[1] || 'png';
    var file = new File([blob], 'memo.' + ext, { type: mime, lastModified: Date.now() });
    function visibleArea(el) {
      var r = el.getBoundingClientRect();
      if (r.width < 80 || r.height < 16) return 0;
      if (r.bottom < 0 || r.top > window.innerHeight) return 0;
      return r.width * r.height;
    }
    var ceSelectors = [
      'div.ProseMirror[contenteditable="true"]',
      '#prompt-textarea',
      'div[contenteditable="true"].ql-editor',
      'div[contenteditable="true"]',
      'textarea',
    ];
    var target = null;
    var targetArea = 0;
    for (var s = 0; s < ceSelectors.length; s++) {
      var nodes = document.querySelectorAll(ceSelectors[s]);
      for (var j = 0; j < nodes.length; j++) {
        var n = nodes[j];
        var a = visibleArea(n);
        if (a > targetArea) { targetArea = a; target = n; }
      }
      if (target) break;
    }
    if (!target) return 'no-target';
    target.focus();
    var dt = new DataTransfer();
    dt.items.add(file);
    target.dispatchEvent(new ClipboardEvent('paste', {
      clipboardData: dt, bubbles: true, cancelable: true,
    }));
    target.dispatchEvent(new DragEvent('drop', {
      dataTransfer: dt, bubbles: true, cancelable: true,
    }));
    window.__mmTxtAiImgToken = $token;
    return 'ok';
  } catch (e) {
    return 'error: ' + e;
  }
})();
''';
    try {
      _aiWinCtrl?.executeScript(js);
    } catch (_) {}
  }

  // ─── AI編集 (MCP) チャット ──────────────────────────────────────────
  void _aiChatScrollEnd() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_aiScroll.hasClients) {
        _aiScroll.animateTo(
          _aiScroll.position.maxScrollExtent,
          duration: const Duration(milliseconds: 200),
          curve: Curves.easeOut,
        );
      }
    });
  }

  Future<void> _sendAiChat() async {
    final q = _aiInput.text.trim();
    if ((q.isEmpty && _aiPendingFiles.isEmpty) || _aiChatBusy) return;
    final provider = context.read<MindMapProvider>();
    if (!provider.hasActiveAiKey) {
      _showSnackBar(provider.t('text.aiNeedKey'));
      return;
    }
    // ── 添付を組み立てる (= ユーザー要望: 画像やファイルを渡せるように) ──
    final images = <AiInputImage>[];
    final attachNote = StringBuffer();
    final attachNames = <String>[];
    final pending =
        List<({String path, String name, bool isImage})>.from(_aiPendingFiles);
    for (final f in pending) {
      attachNames.add(f.name);
      try {
        if (f.isImage) {
          final bytes = await File(f.path).readAsBytes();
          final ext = f.name.contains('.')
              ? f.name.substring(f.name.lastIndexOf('.') + 1)
              : 'png';
          images.add(AiInputImage(
              mime: AiInputImage.mimeForExt(ext),
              base64: base64Encode(bytes),
              name: f.name));
        } else {
          var body = await File(f.path).readAsString();
          if (body.length > 12000) {
            body = '${body.substring(0, 12000)}\n…(長いので省略)';
          }
          attachNote.writeln('\n【添付ファイル ${f.name}】\n$body');
        }
      } catch (e) {
        attachNote.writeln('\n【添付ファイル ${f.name}】(読み込み失敗: $e)');
      }
    }
    if (!mounted) return;
    final combined = '$q${attachNote.toString()}';
    _aiInput.clear();
    _aiHistIdx = null;
    if (q.isNotEmpty) unawaited(_aiHistoryAdd(q));
    setState(() {
      _aiPendingFiles.clear();
      _aiChat.add((
        role: 'user',
        text: attachNames.isEmpty ? q : '$q\n📎 ${attachNames.join(', ')}',
      ));
      _aiChatBusy = true;
    });
    _aiChatScrollEnd();
    try {
      await _runAiFileEditAgent(provider, combined,
          images: images.isEmpty ? null : images);
    } catch (e) {
      if (mounted) setState(() => _aiChat.add((role: 'ai', text: '⚠ $e')));
    } finally {
      if (mounted) setState(() => _aiChatBusy = false);
      // 会話の履歴を保存 (= ユーザー要望)。
      unawaited(_saveAiChatLog());
      // 残りトークン表示を更新する (= ユーザー要望: LLM 設定の表示)。
      unawaited(provider
          .refreshCreditBalance()
          .then((_) => mounted ? setState(() {}) : null));
      _aiChatScrollEnd();
    }
  }

  /// MCP ツール (text_file_*) を使ってファイルを書き換えるエージェント
  /// ループ (= ユーザー要望: MCP で内部を編集できる AI 機能)。
  Future<void> _runAiFileEditAgent(MindMapProvider provider,
      String instruction,
      {List<AiInputImage>? images}) async {
    final tools = McpServer(provider);
    const allowed = {
      'text_file_status',
      'text_file_read',
      'text_file_edit',
      // 仕様を確かめたい時に説明書を読ませる (= ユーザー要望: skills 方式)。
      'list_app_docs',
      'read_app_doc',
    };
    final defs = jsonEncode([
      for (final t in McpServer.toolDefs)
        if (allowed.contains(t['name'])) t
    ]);
    // アプリの説明書を既定で渡す (= ユーザー要望)。
    final guide = (await provider.loadAppAgentsGuide()).trim();
    final guideBlock =
        guide.isEmpty ? '' : '【このアプリの説明書 (必ず踏まえること)】\n$guide\n\n';
    final hist = StringBuffer()..writeln('ユーザー: $instruction');
    const maxRounds = 12;
    for (var round = 0; round < maxRounds; round++) {
      // 現在の内容 (毎ラウンド撮り直す = 編集後の姿を AI が見られる)。
      final numbered = StringBuffer();
      var used = 0;
      var truncated = false;
      for (var i = 0; i < _lines.length; i++) {
        final l = '${i + 1}: ${_lines[i]}';
        if (used + l.length > 16000) {
          truncated = true;
          break;
        }
        numbered.writeln(l);
        used += l.length + 1;
      }
      final prompt = '$guideBlock'
          'あなたはアプリ内テキストエディタで開いているファイルを編集するアシスタントです。\n'
          'ツールで、 開いているファイルを直接書き換えられます。\n'
          'ツール定義: $defs\n'
          'ツールを使う時は、 説明文を付けず {"tool":"ツール名","args":{...}} の '
          'JSON だけを 1 つ返してください。\n'
          '編集は text_file_edit の edits 配列に「まとめて 1 回」 で渡してください。\n'
          '行番号は 1 始まりで、 その呼び出しの前のファイルに対する番号です。\n'
          '完了したら、 何をどう変えたかを短い普通の文章で返してください '
          '(JSON は返さない)。\n'
          '${provider.languageInstructionForAi()}\n'
          '【開いているファイル $_currentFileName の現在の内容 (行番号付き'
          '${truncated ? '。長いので途中まで。続きは text_file_read で読めます' : ''})】\n'
          '$numbered\n'
          '${hist}アシスタント:';
      // 添付画像は毎ラウンド付ける (= 各ラウンドは独立したリクエストのため)。
      final reply = await provider.askAi(prompt, images: images);
      if (!mounted) return;
      final call = _McpChatDialogState._parseToolCall(reply);
      if (call == null || round == maxRounds - 1) {
        final answer = call != null
            ? provider.t('mcp.tooManySteps')
            : stripToolEchoFromReply(reply);
        setState(() => _aiChat.add((role: 'ai', text: answer)));
        break;
      }
      final name = call['tool'] as String;
      final args = (call['args'] as Map?)?.cast<String, dynamic>() ?? const {};
      Map<String, dynamic> result;
      if (!allowed.contains(name)) {
        result = {
          'content': [
            {
              'type': 'text',
              'text': 'error: tool "$name" is not available here'
            }
          ],
          'isError': true,
        };
      } else {
        try {
          result = await tools.callTool(name, args);
        } catch (e) {
          result = {
            'content': [
              {'type': 'text', 'text': 'error: $e'}
            ],
            'isError': true,
          };
        }
      }
      final resText = ((result['content'] as List?)?.isNotEmpty ?? false)
          ? ((result['content'] as List).first as Map)['text']?.toString() ?? ''
          : '';
      final ok = result['isError'] != true;
      if (!mounted) return;
      setState(() => _aiChat.add((
            role: 'tool',
            text: ok ? '⚙ $name ✓' : '⚙ $name ✗ $resText',
          )));
      _aiChatScrollEnd();
      hist.writeln('アシスタント: $reply');
      hist.writeln(
          'ツール実行結果: ${resText.length > 1500 ? '${resText.substring(0, 1500)}…' : resText}');
    }
  }

  /// リレー (代行) モデル名の表示用ラベル。 末尾の日付は落とす。
  String _relayModelLabel(String id) => id.replaceAll(RegExp(r'-\d{8}$'), '');

  /// AI編集で使うモデルの切替 (= ユーザー要望: AI編集は API 呼び出しなので
  /// LLM の設定項目が要る)。 MCP チャットと同じ relayModel を共有する。
  Widget _buildAiEditModelPicker(MindMapProvider provider) {
    final models = provider.relayModels;
    return PopupMenuButton<String>(
      tooltip: provider.t('pdf.aiSelectTip'),
      color: const Color(0xFF1E1E32),
      onSelected: (id) async {
        await provider.setRelayModel(id);
        if (mounted) setState(() {});
      },
      itemBuilder: (_) => [
        for (final m in models)
          if (m is Map)
            PopupMenuItem<String>(
              value: '${m['id']}',
              child: Row(children: [
                Icon(
                    '${m['id']}' == provider.relayModel
                        ? Icons.radio_button_checked_rounded
                        : Icons.radio_button_off_rounded,
                    size: 14,
                    color: '${m['id']}' == provider.relayModel
                        ? const Color(0xFF9CCC65)
                        : Colors.white38),
                const SizedBox(width: 8),
                Text(_relayModelLabel('${m['id']}'),
                    style:
                        const TextStyle(color: Colors.white, fontSize: 12.5)),
              ]),
            ),
        if (models.isEmpty)
          PopupMenuItem<String>(
            enabled: false,
            child: Text(_relayModelLabel(provider.relayModel),
                style: const TextStyle(color: Colors.white54, fontSize: 12.5)),
          ),
      ],
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: Colors.white24),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          const Icon(Icons.memory_rounded, size: 13, color: Colors.white54),
          const SizedBox(width: 5),
          Text(_relayModelLabel(provider.relayModel),
              style: const TextStyle(color: Colors.white70, fontSize: 11)),
          const Icon(Icons.expand_more_rounded,
              size: 14, color: Colors.white38),
        ]),
      ),
    );
  }

  /// 「あと何トークン使えるか」 の表示 (MCP チャットと同じ計算)。
  String _aiEditRemainText(MindMapProvider provider) => aiRemainText(provider);

  /// AI編集 (MCP) チャットの中身 (ブラウザ AI の上に重ねるオーバーレイ)。
  Widget _buildAiEditChatColumn() {
    final provider = context.read<MindMapProvider>();
    return Column(
      children: [
        // ── 設定バー: モデル切替 + 残りトークン + 履歴クリア ──
        Container(
          padding: const EdgeInsets.fromLTRB(8, 6, 4, 6),
          decoration: const BoxDecoration(
            color: Color(0xFF16162A),
            border: Border(bottom: BorderSide(color: Colors.white12)),
          ),
          child: Row(children: [
            _buildAiEditModelPicker(provider),
            const SizedBox(width: 8),
            Expanded(
              child: Text(_aiEditRemainText(provider),
                  textAlign: TextAlign.right,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                      color: Color(0xFF9CCC65), fontSize: 10.5)),
            ),
            if (_aiChat.isNotEmpty)
              IconButton(
                tooltip: provider.t('memo.delete'),
                padding: EdgeInsets.zero,
                constraints:
                    const BoxConstraints(minWidth: 26, minHeight: 26),
                icon: const Icon(Icons.delete_sweep_rounded,
                    size: 16, color: Colors.white38),
                onPressed: () => setState(() => _aiChat.clear()),
              ),
          ]),
        ),
        // ── 空の時の案内 (= ユーザー要望: 味気ないので何ができるか示す) ──
        if (_aiChat.isEmpty)
          Expanded(
            child: Center(
              child: Padding(
                padding: const EdgeInsets.all(20),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Container(
                      padding: const EdgeInsets.all(14),
                      decoration: BoxDecoration(
                        color: const Color(0xFF6C63FF).withValues(alpha: 0.15),
                        shape: BoxShape.circle,
                      ),
                      child: const Icon(Icons.edit_note_rounded,
                          color: Color(0xFF6C63FF), size: 30),
                    ),
                    const SizedBox(height: 12),
                    Text(provider.t('text.aiEditMode'),
                        style: const TextStyle(
                            color: Colors.white,
                            fontSize: 14,
                            fontWeight: FontWeight.w700)),
                    const SizedBox(height: 8),
                    Text(provider.t('text.aiEditIntro'),
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                            color: Colors.white54,
                            fontSize: 11.5,
                            height: 1.6)),
                  ],
                ),
              ),
            ),
          ),
        if (_aiChat.isNotEmpty)
          Expanded(
            child: ListView.builder(
              controller: _aiScroll,
              padding: const EdgeInsets.all(8),
              itemCount: _aiChat.length,
              itemBuilder: (ctx, i) {
              final m = _aiChat[i];
              if (m.role == 'tool') {
                return Padding(
                  padding: const EdgeInsets.symmetric(vertical: 2),
                  child: Text(m.text,
                      style: const TextStyle(
                          color: Colors.white38,
                          fontSize: 10.5,
                          fontStyle: FontStyle.italic)),
                );
              }
              final isUser = m.role == 'user';
              return Align(
                alignment:
                    isUser ? Alignment.centerRight : Alignment.centerLeft,
                child: Container(
                  margin: const EdgeInsets.symmetric(vertical: 3),
                  padding:
                      const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
                  constraints: const BoxConstraints(maxWidth: 300),
                  decoration: BoxDecoration(
                    color: isUser
                        ? const Color(0xFF6C63FF)
                        : const Color(0xFF262636),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: SelectableText(m.text,
                      style: const TextStyle(
                          color: Colors.white, fontSize: 12, height: 1.4)),
                ),
              );
            },
          ),
        ),
        if (_aiChatBusy)
          const Padding(
            padding: EdgeInsets.symmetric(vertical: 4),
            child: SizedBox(
              width: 16,
              height: 16,
              child: CircularProgressIndicator(strokeWidth: 2),
            ),
          ),
        // ── 添付中のファイル (= ユーザー要望: 画像やファイルを渡せるように) ──
        if (_aiPendingFiles.isNotEmpty)
          Padding(
            padding: const EdgeInsets.fromLTRB(8, 2, 8, 0),
            child: Wrap(
              spacing: 4,
              runSpacing: 4,
              children: [
                for (var i = 0; i < _aiPendingFiles.length; i++)
                  Container(
                    padding: const EdgeInsets.fromLTRB(8, 3, 4, 3),
                    decoration: BoxDecoration(
                      color: const Color(0xFF262636),
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(color: Colors.white12),
                    ),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      Icon(
                          _aiPendingFiles[i].isImage
                              ? Icons.image_rounded
                              : Icons.description_rounded,
                          size: 12,
                          color: const Color(0xFF4FC3F7)),
                      const SizedBox(width: 4),
                      ConstrainedBox(
                        constraints: const BoxConstraints(maxWidth: 130),
                        child: Text(_aiPendingFiles[i].name,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: Colors.white70, fontSize: 10.5)),
                      ),
                      InkWell(
                        onTap: () =>
                            setState(() => _aiPendingFiles.removeAt(i)),
                        child: const Padding(
                          padding: EdgeInsets.all(2),
                          child: Icon(Icons.close_rounded,
                              size: 12, color: Colors.white54),
                        ),
                      ),
                    ]),
                  ),
              ],
            ),
          ),
        Padding(
          padding: const EdgeInsets.fromLTRB(8, 4, 8, 8),
          child: Row(
            children: [
              // ── 添付 (画像 / ファイル) ──
              IconButton(
                tooltip: provider.t('aichat.attach'),
                padding: EdgeInsets.zero,
                constraints:
                    const BoxConstraints(minWidth: 30, minHeight: 30),
                icon: const Icon(Icons.attach_file_rounded,
                    size: 18, color: Colors.white54),
                onPressed:
                    _aiChatBusy ? null : () => unawaited(_pickAiAttachment()),
              ),
              Expanded(
                // ↑↓ で過去のプロンプトを呼び出す (= ユーザー要望)。
                child: Focus(
                  onKeyEvent: (node, event) {
                    if (event is! KeyDownEvent) return KeyEventResult.ignored;
                    if (event.logicalKey == LogicalKeyboardKey.arrowUp) {
                      unawaited(_aiHistMove(-1).then((_) {
                        if (mounted) setState(() {});
                      }));
                      return KeyEventResult.handled;
                    }
                    if (event.logicalKey == LogicalKeyboardKey.arrowDown) {
                      unawaited(_aiHistMove(1).then((_) {
                        if (mounted) setState(() {});
                      }));
                      return KeyEventResult.handled;
                    }
                    return KeyEventResult.ignored;
                  },
                  child: TextField(
                    controller: _aiInput,
                    style: const TextStyle(color: Colors.white, fontSize: 12),
                    decoration: InputDecoration(
                      hintText: provider.t('text.aiEditHint'),
                      hintStyle:
                          const TextStyle(color: Colors.white38, fontSize: 12),
                      isDense: true,
                      contentPadding: const EdgeInsets.symmetric(
                          horizontal: 10, vertical: 8),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(10),
                        borderSide: const BorderSide(color: Colors.white24),
                      ),
                    ),
                    onSubmitted: (_) => _sendAiChat(),
                  ),
                ),
              ),
              const SizedBox(width: 4),
              IconButton(
                icon: _aiChatBusy
                    ? const SizedBox(
                        width: 18,
                        height: 18,
                        child: CircularProgressIndicator(strokeWidth: 2))
                    : const Icon(Icons.send_rounded, color: Color(0xFF6C63FF)),
                onPressed: _aiChatBusy ? null : _sendAiChat,
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _buildAiChatPanel(bool dark, Color fg) {
    final provider = context.read<MindMapProvider>();
    Widget webView;
    if (!Platform.isWindows) {
      webView = Center(
        child: Text(provider.t('md.previewUnavailable'),
            style: const TextStyle(color: Colors.white38, fontSize: 12)),
      );
    } else if (_aiPanelUrl.isEmpty) {
      webView = Center(
        child: Text(provider.t('pdf.aiSelect'),
            style: const TextStyle(color: Colors.white38, fontSize: 12)),
      );
    } else {
      // ★ フリーズ対策 (PDF ビューアと同じ): 一度生成した WebView の実体を
      //   保持して、 setState のたびにネイティブ View が作り直されないように
      //   する。 AI の切替は loadUrl で行う。
      webView = _aiWebCache ??= _SplitWindowsWebView(
        url: _aiPanelUrl,
        onControllerReady: (c) => _aiWinCtrl = c,
        onInitialized: () {},
        onUrlChanged: (u) {
          if (mounted && u != _aiPanelUrl) _aiPanelUrl = u;
        },
      );
    }
    final editSelected = _aiEditChatMode;
    return Container(
      width: _aiPanelW,
      decoration: const BoxDecoration(
        color: Color(0xFF1E1E32),
        border: Border(left: BorderSide(color: Colors.white24)),
      ),
      child: Column(
        children: [
          // ── ヘッダー: AI 選択 + AI編集切替 + 再読込 + 閉じる ──
          // 高さを固定して、 ブラウザ AI ⇔ AI編集 の切替でボタン位置が
          // ズレないようにする (= ユーザー要望: 同じ位置に来るように)。
          Container(
            height: 40,
            padding: const EdgeInsets.fromLTRB(10, 0, 2, 0),
            color: const Color(0xFF12121C),
            child: Row(
              children: [
                Icon(
                    editSelected
                        ? Icons.edit_note_rounded
                        : Icons.smart_toy_rounded,
                    color: const Color(0xFF4FC3F7),
                    size: 18),
                const SizedBox(width: 6),
                Flexible(
                  // AI編集モード中はブラウザ AI のサービス名を出さない
                  // (= ユーザー要望: ChatGPT なのにモデルが Gemini という
                  //   混乱を避ける)。
                  child: Text(
                      editSelected
                          ? provider.t('text.aiEditMode')
                          : _textAiPanelLabel,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 13,
                          fontWeight: FontWeight.w700)),
                ),
                if (!editSelected)
                SizedBox(
                  width: 28,
                  height: 28,
                  child: PopupMenuButton<String>(
                  tooltip: provider.t('pdf.aiSelectTip'),
                  // ── 28×28 に固定してヘッダーの高さに影響させない
                  //    (= モード切替でボタン位置がズレないように) ──
                  padding: EdgeInsets.zero,
                  icon: const Icon(Icons.expand_more_rounded,
                      color: Colors.white70, size: 18),
                  color: const Color(0xFF1E1E32),
                  onSelected: (sel) {
                    if (sel == '__prefix__') {
                      // ── 毎回 AI に渡す前提条件の設定 (= ユーザー要望:
                      //    モデル切替の所に設定項目を付ける)。 PDF ビューア
                      //    と同じ provider.browserAiPrefix を共有する。 ──
                      _showTextAiPrefixDialog();
                      return;
                    }
                    _openTextAiPanel(sel);
                  },
                  itemBuilder: (_) => [
                    for (final e in const [
                      ('chatgpt', 'ChatGPT'),
                      ('gemini', 'Gemini'),
                      ('claude', 'Claude'),
                      ('deepseek', 'DeepSeek'),
                      ('grok', 'Grok'),
                    ])
                      PopupMenuItem(
                        value: e.$1,
                        child: Text(e.$2,
                            style: const TextStyle(
                                color: Colors.white, fontSize: 13)),
                      ),
                    const PopupMenuDivider(),
                    PopupMenuItem(
                      value: '__prefix__',
                      child: Row(children: [
                        const Icon(Icons.tips_and_updates_outlined,
                            color: Color(0xFFBA68C8), size: 18),
                        const SizedBox(width: 8),
                        Text(provider.t('ai.prereq'),
                            style:
                                const TextStyle(color: Color(0xFFBA68C8))),
                      ]),
                    ),
                  ],
                ),
                ),
                const Spacer(),
                // ── AI編集 (MCP でファイルを書き換えるチャット) 切替 ──
                InkWell(
                  borderRadius: BorderRadius.circular(10),
                  onTap: () {
                    setState(() => _aiEditChatMode = !_aiEditChatMode);
                    if (_aiEditChatMode) {
                      // モデル一覧と残高を取り直す (= ユーザー要望:
                      // AI編集は API 呼び出しなので LLM 設定を出す)。
                      final p = context.read<MindMapProvider>();
                      unawaited(p
                          .refreshRelayModels()
                          .then((_) => mounted ? setState(() {}) : null));
                      unawaited(p
                          .refreshCreditBalance()
                          .then((_) => mounted ? setState(() {}) : null));
                    }
                  },
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 9, vertical: 3),
                    decoration: BoxDecoration(
                      color: editSelected
                          ? const Color(0xFF6C63FF)
                          : Colors.transparent,
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(
                        color: editSelected
                            ? const Color(0xFF6C63FF)
                            : Colors.white30,
                      ),
                    ),
                    child: Text(provider.t('text.aiEditMode'),
                        style: TextStyle(
                            fontSize: 11,
                            fontWeight: FontWeight.w600,
                            color:
                                editSelected ? Colors.white : Colors.white70)),
                  ),
                ),
                IconButton(
                  tooltip: provider.t('pdf.aiReload'),
                  icon: const Icon(Icons.refresh_rounded,
                      color: Colors.white70, size: 18),
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints(minWidth: 28, minHeight: 28),
                  onPressed: () {
                    try {
                      _aiWinCtrl?.reload();
                    } catch (_) {}
                  },
                ),
                IconButton(
                  tooltip: provider.t('pdf.aiClose'),
                  icon: const Icon(Icons.close_rounded,
                      color: Colors.white60, size: 18),
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints(minWidth: 28, minHeight: 28),
                  onPressed: () {
                    setState(() {
                      _aiPanelOpen = false;
                      // ★ フリーズ対策: 閉じたら WebView キャッシュを破棄
                      _aiWebCache = null;
                      _aiWinCtrl = null;
                    });
                  },
                ),
              ],
            ),
          ),
          Expanded(
            child: Stack(
              children: [
                Positioned.fill(
                  child: Listener(
                    onPointerSignal: _scrollTextAiPanelByWheel,
                    child: webView,
                  ),
                ),
                // AI編集はブラウザ AI の上に重ねる (WebView を作り直さない)。
                if (_aiEditChatMode)
                  Positioned.fill(
                    child: Container(
                      color: const Color(0xFF1E1E2A),
                      child: _buildAiEditChatColumn(),
                    ),
                  ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildEditor(bool dark, Color fg) {
    final bg = dark ? const Color(0xFF1A1A24) : const Color(0xFFF5F5F0);
    return Listener(
      // なぞり選択の終わり (= ユーザー要望: 上下ドラッグで複数行選択)。
      onPointerUp: (_) => _lineDragSelecting = false,
      onPointerCancel: (_) => _lineDragSelecting = false,
      child: Container(
      color: bg,
      child: ListView.builder(
        controller: _scroll,
        itemCount: _lines.length + 1, // 末尾の "新規行追加" 用
        itemBuilder: (ctx, i) {
          if (i == _lines.length) {
            return InkWell(
              onTap: _appendBlankLine,
              child: Container(
                height: _lineHeight,
                padding: const EdgeInsets.symmetric(horizontal: 12),
                alignment: Alignment.centerLeft,
                // 「新しい行を追加」 の文字は出さない (= ユーザー要望:
                //   Enter で自動的に行が増えるため、 + の印だけで足りる)。
                child: Row(children: [
                  SizedBox(
                    width: _gutterWidth - 12,
                    child: Icon(Icons.add,
                        size: 14, color: fg.withValues(alpha: 0.35)),
                  ),
                ]),
              ),
            );
          }
          return _buildLine(i, dark, fg);
        },
      ),
      ),
    );
  }

  Widget _buildLine(int idx, bool dark, Color fg) {
    final editing = _editingIdx == idx;
    // まとめ選択中の行 (= ユーザー要望: Ctrl+Shift+↑↓ の範囲選択)。
    final selected = _isLineSelected(idx);
    // 画面内へ引き戻す基準にする「今いる行」 は 1 つだけ。
    final isCurrent =
        editing || (_editingIdx == null && _selFocusLine == idx);
    final gutter = SizedBox(
      width: _gutterWidth,
      child: Padding(
        padding: const EdgeInsets.only(right: 8),
        child: Text(
          '${idx + 1}',
          textAlign: TextAlign.right,
          style: TextStyle(
            color: fg.withValues(alpha: editing ? 0.9 : 0.35),
            fontSize: _fontSize - 1,
            fontFamily: 'monospace',
            fontWeight: editing ? FontWeight.w700 : FontWeight.w400,
          ),
        ),
      ),
    );

    if (editing) {
      return Container(
        key: isCurrent ? _curLineKey : null,
        constraints: BoxConstraints(minHeight: _lineHeight),
        decoration: BoxDecoration(
          color: dark
              ? const Color(0xFF2A2A3E).withValues(alpha: 0.5)
              : const Color(0xFFEAEAE2),
          border: Border(
            left: BorderSide(color: const Color(0xFF6C63FF), width: 2),
          ),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            gutter,
            Expanded(
              child: Focus(
                onKeyEvent: (node, event) {
                  if (event is! KeyDownEvent) {
                    return KeyEventResult.ignored;
                  }
                  if (event.logicalKey == LogicalKeyboardKey.escape) {
                    _cancelEdit();
                    return KeyEventResult.handled;
                  }
                  if (event.logicalKey == LogicalKeyboardKey.enter) {
                    _splitLineAtCursor();
                    return KeyEventResult.handled;
                  }
                  if (event.logicalKey == LogicalKeyboardKey.backspace) {
                    if (_editCtrl.selection.baseOffset == 0 &&
                        _editCtrl.selection.extentOffset == 0 &&
                        _editingIdx != null &&
                        _editingIdx! > 0) {
                      _mergeWithPrev();
                      return KeyEventResult.handled;
                    }
                  }
                  if (event.logicalKey == LogicalKeyboardKey.arrowUp &&
                      !HardwareKeyboard.instance.isShiftPressed) {
                    final cur = _editingIdx;
                    if (cur != null && cur > 0) {
                      _commitEdit();
                      _beginEditLine(cur - 1);
                      return KeyEventResult.handled;
                    }
                  }
                  if (event.logicalKey == LogicalKeyboardKey.arrowDown &&
                      !HardwareKeyboard.instance.isShiftPressed) {
                    final cur = _editingIdx;
                    if (cur != null && cur < _lines.length - 1) {
                      _commitEdit();
                      _beginEditLine(cur + 1);
                      return KeyEventResult.handled;
                    }
                  }
                  final isCtrl = HardwareKeyboard.instance.isControlPressed ||
                      HardwareKeyboard.instance.isMetaPressed;
                  if (isCtrl && event.logicalKey == LogicalKeyboardKey.keyS) {
                    _save();
                    return KeyEventResult.handled;
                  }
                  return KeyEventResult.ignored;
                },
                child: TextField(
                  controller: _editCtrl,
                  focusNode: _editFocus,
                  maxLines: 1,
                  // 閲覧表示と揃える (= ユーザー要望: 中央揃え)。
                  textAlign:
                      _bodyAlign,
                  style: TextStyle(
                    color: fg,
                    fontSize: _fontSize,
                    fontFamily: 'monospace',
                  ),
                  decoration: const InputDecoration(
                    isDense: true,
                    contentPadding:
                        EdgeInsets.symmetric(horizontal: 4, vertical: 2),
                    border: InputBorder.none,
                  ),
                  onTapOutside: (_) => _commitEdit(),
                ),
              ),
            ),
          ],
        ),
      );
    }

    // 閲覧モード: クリックした文字位置にカーソルを置いて、 その場で編集を
    // 始める (= ユーザー要望: クリックしたら即座にその場所が編集できる)。
    return LayoutBuilder(builder: (ctx, cons) {
      final textW = math.max(0.0, cons.maxWidth - _gutterWidth);
      return MouseRegion(
        // ── なぞって複数行選択 (= ユーザー要望) ──
        onEnter: (_) {
          if (!_lineDragSelecting) return;
          final a = _lineDragAnchor;
          if (a == null) return;
          if (_editingIdx != null) _commitEdit();
          setState(() {
            _selAnchorLine = a;
            _selFocusLine = idx;
          });
        },
        child: Listener(
          onPointerDown: (_) {
            if (_editingIdx == idx) return; // 編集中の行は文字選択に任せる
            _lineDragSelecting = true;
            _lineDragAnchor = idx;
          },
          child: InkWell(
        onTapDown: (d) => _lineTapPos = d.localPosition,
        onTap: () {
          int? caret;
          final p = _lineTapPos;
          final line = _lines[idx];
          if (p != null && textW > 0 && line.isNotEmpty) {
            // 表示と同じスタイル / 揃えで TextPainter を組み、 クリック座標を
            // 文字位置に変換する (中央揃えでも正しい位置になる)。
            final tp = TextPainter(
              text: TextSpan(
                text: line,
                style: const TextStyle(
                  fontSize: _fontSize,
                  fontFamily: 'monospace',
                  height: 1.5,
                ),
              ),
              textAlign: _bodyAlign,
              textDirection: TextDirection.ltr,
            )..layout(maxWidth: textW);
            caret = tp
                .getPositionForOffset(Offset(
                  (p.dx - _gutterWidth).clamp(0.0, textW),
                  p.dy.clamp(0.0, tp.height),
                ))
                .offset
                .clamp(0, line.length);
            tp.dispose();
          }
          _beginEditLine(idx, caret: caret);
        },
        child: Container(
          key: isCurrent ? _curLineKey : null,
          constraints: BoxConstraints(minHeight: _lineHeight),
          padding: const EdgeInsets.symmetric(vertical: 1),
          // 選んだ行は帯で塗る (= ユーザー要望: 複数行の範囲選択)。
          decoration: selected
              ? BoxDecoration(
                  color: const Color(0xFF6C63FF)
                      .withValues(alpha: dark ? 0.30 : 0.18),
                  border: Border(
                    left: BorderSide(
                        color: const Color(0xFF6C63FF),
                        width: _selFocusLine == idx ? 2.0 : 1.0),
                  ),
                )
              : null,
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              gutter,
              Expanded(
                child: Text(
                  _lines[idx].isEmpty ? ' ' : _lines[idx],
                  // ── 中央揃え (= ユーザー要望: 開いたら中央揃えで表示) ──
                  textAlign:
                      _bodyAlign,
                  style: TextStyle(
                    color: fg,
                    fontSize: _fontSize,
                    fontFamily: 'monospace',
                    height: 1.5,
                  ),
                ),
              ),
            ],
          ),
        ),
          ), // InkWell
        ), // Listener
      );
    });
  }

  // ─── 数式プレビュー ─────────────────────────────────────────────
  /// $...$ / $$...$$ を Math.tex で描画。 それ以外はプレーンテキスト。
  Widget _buildMathPreview(bool dark, Color fg) {
    final bg = dark ? const Color(0xFF1A1A24) : const Color(0xFFF5F5F0);
    final segments = _parseMath(_fullText);
    return Container(
      color: bg,
      child: SingleChildScrollView(
        padding: const EdgeInsets.all(24),
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 820),
            child: Wrap(
              alignment: WrapAlignment.start,
              crossAxisAlignment: WrapCrossAlignment.center,
              children: [
                for (final s in segments) _renderMathSegment(s, fg),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _renderMathSegment(_MathSeg seg, Color fg) {
    switch (seg.kind) {
      case _MathSegKind.text:
        return SelectableText(
          seg.value,
          style: TextStyle(color: fg, fontSize: 14, height: 1.7),
        );
      case _MathSegKind.inlineMath:
        return _MathRenderer(
          tex: seg.value,
          displayMode: false,
          color: fg,
        );
      case _MathSegKind.blockMath:
        return SizedBox(
          width: double.infinity,
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 12),
            child: Center(
              child: _MathRenderer(
                tex: seg.value,
                displayMode: true,
                color: fg,
              ),
            ),
          ),
        );
    }
  }

  /// 数式パーサ: $$...$$ をブロック、 $...$ をインライン、 それ以外はテキスト。
  static List<_MathSeg> _parseMath(String src) {
    final out = <_MathSeg>[];
    int i = 0;
    while (i < src.length) {
      // ブロック数式 $$...$$
      if (i + 1 < src.length && src[i] == r'$' && src[i + 1] == r'$') {
        final end = src.indexOf(r'$$', i + 2);
        if (end >= 0) {
          out.add(_MathSeg(
              _MathSegKind.blockMath, src.substring(i + 2, end).trim()));
          i = end + 2;
          continue;
        }
      }
      // インライン数式 $...$
      if (src[i] == r'$') {
        final end = src.indexOf(r'$', i + 1);
        if (end >= 0 && end > i + 1) {
          // 改行が間に入らないこと (LaTeX のインライン)
          final body = src.substring(i + 1, end);
          if (!body.contains('\n')) {
            out.add(_MathSeg(_MathSegKind.inlineMath, body));
            i = end + 1;
            continue;
          }
        }
      }
      // 通常テキスト — 次の $ までを取る
      int j = i + 1;
      while (j < src.length && src[j] != r'$') {
        j++;
      }
      out.add(_MathSeg(_MathSegKind.text, src.substring(i, j)));
      i = j;
    }
    return out;
  }
}

enum _MathSegKind { text, inlineMath, blockMath }

class _MathSeg {
  final _MathSegKind kind;
  final String value;
  const _MathSeg(this.kind, this.value);
}

/// 数式描画ウィジェット (依存パッケージなしの自前実装)。
///
/// LaTeX 文字列を Unicode ベースで読みやすく整形して表示する。
///   - ギリシャ文字 ( \alpha → α )
///   - 上付き / 下付き ( ^2 → ²、 _i → ᵢ )
///   - よく使う記号 ( \int → ∫、 \sum → ∑、 \infty → ∞ など)
///   - 分数 ( \frac{a}{b} → (a)/(b) を縦並びで表示)
///
/// 本格的な 2 次元レイアウト (積分の上下限が真上/真下に来る等) は
/// していないが、 内部的に LaTeX 文字列をそのまま保持しているので、
/// 後で flutter_math_fork 等を pubspec.yaml に追加して `Math.tex(tex)`
/// に置き換えれば、 美しい数式描画に切り替えられる。
/// 文章中の `$...$` / `$$...$$` を数式描画し、 それ以外はプレーンテキストとして
/// インラインに流すウィジェット (= ユーザー要望: フラッシュカードのベクトル等の
/// 数式を視覚的に分かる形で表示)。 数式が無ければ普通の Text にフォールバック。
class _RichMathText extends StatelessWidget {
  final String text;
  final Color color;
  final double fontSize;
  final TextAlign textAlign;
  final FontWeight? fontWeight;
  const _RichMathText(
    this.text, {
    required this.color,
    this.fontSize = 16,
    this.textAlign = TextAlign.center,
    this.fontWeight,
  });

  @override
  Widget build(BuildContext context) {
    final base = TextStyle(
        color: color, fontSize: fontSize, fontWeight: fontWeight, height: 1.45);
    final segs = _parseMathSegments(text);
    if (!segs.any((s) => s.kind != _MathSegKind.text)) {
      // 数式を含まない → 通常の Text (折り返し/選択が自然)。
      return Text(text, textAlign: textAlign, style: base);
    }
    final spans = <InlineSpan>[];
    for (final s in segs) {
      if (s.kind == _MathSegKind.text) {
        spans.add(TextSpan(text: s.value, style: base));
      } else {
        spans.add(WidgetSpan(
          alignment: PlaceholderAlignment.middle,
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 2),
            child: _MathRenderer(
              tex: s.value,
              displayMode: s.kind == _MathSegKind.blockMath,
              color: color,
            ),
          ),
        ));
      }
    }
    return Text.rich(TextSpan(children: spans),
        textAlign: textAlign, style: base);
  }
}

/// `$$...$$` をブロック、 `$...$` をインライン数式、 残りをテキストに分割する。
/// (`_MathRenderer` 系の `_parseMath` と同じ規則の独立版。)
List<_MathSeg> _parseMathSegments(String src) {
  final out = <_MathSeg>[];
  int i = 0;
  while (i < src.length) {
    if (i + 1 < src.length && src[i] == r'$' && src[i + 1] == r'$') {
      final end = src.indexOf(r'$$', i + 2);
      if (end >= 0) {
        out.add(
            _MathSeg(_MathSegKind.blockMath, src.substring(i + 2, end).trim()));
        i = end + 2;
        continue;
      }
    }
    if (src[i] == r'$') {
      final end = src.indexOf(r'$', i + 1);
      if (end > i + 1) {
        final body = src.substring(i + 1, end);
        if (!body.contains('\n')) {
          out.add(_MathSeg(_MathSegKind.inlineMath, body));
          i = end + 1;
          continue;
        }
      }
    }
    int j = i + 1;
    while (j < src.length && src[j] != r'$') {
      j++;
    }
    out.add(_MathSeg(_MathSegKind.text, src.substring(i, j)));
    i = j;
  }
  return out;
}

class _MathRenderer extends StatelessWidget {
  final String tex;
  final bool displayMode;
  final Color color;
  const _MathRenderer({
    required this.tex,
    required this.displayMode,
    required this.color,
  });

  /// 依存パッケージ無しの Unicode 近似描画 (flutter_math_fork が式を解釈できない
  /// 時のフォールバック)。
  Widget _unicodeRender() {
    try {
      final widgets =
          _LatexFormatter.format(tex, color, baseSize: displayMode ? 18 : 14);
      return Wrap(
        crossAxisAlignment: WrapCrossAlignment.center,
        spacing: 1,
        runSpacing: 2,
        children: widgets,
      );
    } catch (_) {
      return _buildFallback();
    }
  }

  @override
  Widget build(BuildContext context) {
    // flutter_math_fork で本格的な LaTeX 描画 (= ユーザー要望: ベクトル \vec{a}
    //   や分数などを視覚的に分かる形で)。 解釈できない式は Unicode 近似に落とす。
    try {
      return fmath.Math.tex(
        tex,
        mathStyle: displayMode ? fmath.MathStyle.display : fmath.MathStyle.text,
        textStyle: TextStyle(color: color, fontSize: displayMode ? 18 : 14),
        onErrorFallback: (_) => _unicodeRender(),
      );
    } catch (_) {
      return _unicodeRender();
    }
  }

  Widget _buildFallback() {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
      margin: const EdgeInsets.symmetric(horizontal: 2),
      decoration: BoxDecoration(
        color: Colors.redAccent.withValues(alpha: 0.1),
        borderRadius: BorderRadius.circular(4),
        border: Border.all(color: Colors.redAccent.withValues(alpha: 0.4)),
      ),
      child: Text(
        '\$$tex\$',
        style: TextStyle(
          color: Colors.redAccent.withValues(alpha: 0.9),
          fontFamily: 'monospace',
          fontSize: 13,
        ),
      ),
    );
  }
}

/// LaTeX 文字列を Unicode ベースの軽量レンダリングに変換するヘルパ。
///
/// 完全な LaTeX 互換ではないが、 一般的な数式表現 (ギリシャ文字、 上付き /
/// 下付き、 よく使う演算子・関数記号、 分数 / 平方根) はカバーする。
class _LatexFormatter {
  /// LaTeX 文字列を Widget のリストに変換 (Wrap に入れて使う)
  static List<Widget> format(String tex, Color color, {double baseSize = 14}) {
    final parser = _LatexFormatter._(tex, color, baseSize);
    return parser._parseSequence();
  }

  final String _src;
  int _pos = 0;
  final Color _color;
  final double _baseSize;
  _LatexFormatter._(this._src, this._color, this._baseSize);

  bool get _eof => _pos >= _src.length;

  List<Widget> _parseSequence({String? stopAt}) {
    final out = <Widget>[];
    while (!_eof) {
      final ch = _src[_pos];
      if (stopAt != null && ch == stopAt) break;
      if (ch == '}') break;
      if (ch == '\\') {
        out.addAll(_parseCommand());
      } else if (ch == '^') {
        _pos++;
        final body = _parseGroupOrSingle();
        out.add(_supSub(body, isSuper: true));
      } else if (ch == '_') {
        _pos++;
        final body = _parseGroupOrSingle();
        out.add(_supSub(body, isSuper: false));
      } else if (ch == '{') {
        _pos++;
        out.addAll(_parseSequence(stopAt: '}'));
        if (!_eof && _src[_pos] == '}') _pos++;
      } else {
        // 通常文字 — 連続して取り出す
        final start = _pos;
        while (!_eof &&
            _src[_pos] != '\\' &&
            _src[_pos] != '^' &&
            _src[_pos] != '_' &&
            _src[_pos] != '{' &&
            _src[_pos] != '}' &&
            (stopAt == null || _src[_pos] != stopAt)) {
          _pos++;
        }
        final text = _src.substring(start, _pos);
        if (text.isNotEmpty) {
          out.add(_textWidget(text, italic: _shouldItalicize(text)));
        }
      }
    }
    return out;
  }

  /// 変数 1 文字は数学的慣習でイタリックに (LaTeX のデフォルト挙動)
  bool _shouldItalicize(String s) {
    if (s.length != 1) return false;
    return RegExp(r'^[a-zA-Z]$').hasMatch(s);
  }

  /// '\command' を解釈
  List<Widget> _parseCommand() {
    if (_eof || _src[_pos] != '\\') return [];
    _pos++; // skip '\'
    final cmdStart = _pos;
    while (!_eof && RegExp(r'[a-zA-Z]').hasMatch(_src[_pos])) {
      _pos++;
    }
    final cmd = _src.substring(cmdStart, _pos);
    if (cmd.isEmpty) {
      // \\ や \, など、 非アルファベットコマンド
      if (!_eof) {
        final special = _src[_pos];
        _pos++;
        if (special == ',' ||
            special == ';' ||
            special == ' ' ||
            special == '!' ||
            special == ':') {
          return [SizedBox(width: _baseSize * 0.2)];
        }
        if (special == '\\') {
          return [SizedBox(width: double.infinity, height: 4)];
        }
        return [_textWidget(special)];
      }
      return [];
    }

    // 分数: \frac{a}{b}
    if (cmd == 'frac' || cmd == 'dfrac' || cmd == 'tfrac') {
      _skipWhitespace();
      final num = _parseGroup();
      _skipWhitespace();
      final den = _parseGroup();
      return [_fraction(num, den)];
    }

    // 平方根: \sqrt{x} または \sqrt[n]{x}
    if (cmd == 'sqrt') {
      _skipWhitespace();
      // [n] (省略可能)
      if (!_eof && _src[_pos] == '[') {
        // 簡易: 省略
        while (!_eof && _src[_pos] != ']') {
          _pos++;
        }
        if (!_eof) _pos++;
      }
      final body = _parseGroupOrSingle();
      return [
        _textWidget('√'),
        Container(
          padding: const EdgeInsets.only(top: 1),
          decoration: BoxDecoration(
            border: Border(top: BorderSide(color: _color, width: 1)),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: body),
        ),
      ];
    }

    // 太字
    if (cmd == 'mathbf' ||
        cmd == 'mathrm' ||
        cmd == 'text' ||
        cmd == 'mathit' ||
        cmd == 'mathsf' ||
        cmd == 'mathtt') {
      _skipWhitespace();
      final body = _parseGroupOrSingle();
      return body;
    }

    // left/right ( delimiter )
    if (cmd == 'left' || cmd == 'right') {
      if (!_eof) {
        final d = _src[_pos];
        _pos++;
        if (d == '.') return []; // \left. / \right.
        return [_textWidget(d)];
      }
      return [];
    }

    // 既知のシンボル変換
    final mapped = _kCommandMap[cmd];
    if (mapped != null) {
      return [_textWidget(mapped)];
    }

    // 大型演算子 (積分・総和等)
    final big = _kBigOpMap[cmd];
    if (big != null) {
      return [
        _textWidget(big, fontSize: _baseSize * 1.4, weight: FontWeight.w500)
      ];
    }

    // 関数名 (\sin, \cos 等は立体で表示)
    final func = _kFuncMap[cmd];
    if (func != null) {
      return [_textWidget(func)];
    }

    // 不明コマンドはそのまま表示
    return [_textWidget('\\$cmd', mono: true)];
  }

  void _skipWhitespace() {
    while (!_eof && _src[_pos] == ' ') {
      _pos++;
    }
  }

  /// '{...}' を解析
  List<Widget> _parseGroup() {
    if (_eof) return [];
    if (_src[_pos] != '{') {
      // ブレース無しの 1 文字
      final ch = _src[_pos];
      _pos++;
      return [_textWidget(ch, italic: _shouldItalicize(ch))];
    }
    _pos++; // skip '{'
    final inner = _parseSequence(stopAt: '}');
    if (!_eof && _src[_pos] == '}') _pos++;
    return inner;
  }

  /// '{...}' または 1 文字を解析
  List<Widget> _parseGroupOrSingle() {
    if (_eof) return [];
    if (_src[_pos] == '{') return _parseGroup();
    if (_src[_pos] == '\\') return _parseCommand();
    final ch = _src[_pos];
    _pos++;
    return [_textWidget(ch, italic: _shouldItalicize(ch))];
  }

  /// 上付き / 下付き表示
  Widget _supSub(List<Widget> body, {required bool isSuper}) {
    // 単一の文字なら Unicode 上付き / 下付き 文字を使う
    if (body.length == 1 && body.first is _PlainTextHolder) {
      final t = (body.first as _PlainTextHolder).text;
      if (t.length == 1) {
        final mapped = isSuper ? _kSuperscriptMap[t] : _kSubscriptMap[t];
        if (mapped != null) {
          return _textWidget(mapped);
        }
      }
    }
    // それ以外: 小さくして縦オフセット
    return Transform.translate(
      offset: Offset(0, isSuper ? -_baseSize * 0.35 : _baseSize * 0.18),
      child: DefaultTextStyle.merge(
        style: TextStyle(fontSize: _baseSize * 0.7),
        child: Row(mainAxisSize: MainAxisSize.min, children: body),
      ),
    );
  }

  /// 分数: 縦並び、 中央に横線
  Widget _fraction(List<Widget> num, List<Widget> den) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 2),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          DefaultTextStyle.merge(
            style: TextStyle(fontSize: _baseSize * 0.85),
            child: Padding(
              padding: const EdgeInsets.only(bottom: 1, left: 2, right: 2),
              child: Row(mainAxisSize: MainAxisSize.min, children: num),
            ),
          ),
          Container(
            height: 1,
            constraints: const BoxConstraints(minWidth: 16),
            color: _color,
          ),
          DefaultTextStyle.merge(
            style: TextStyle(fontSize: _baseSize * 0.85),
            child: Padding(
              padding: const EdgeInsets.only(top: 1, left: 2, right: 2),
              child: Row(mainAxisSize: MainAxisSize.min, children: den),
            ),
          ),
        ],
      ),
    );
  }

  Widget _textWidget(String text,
      {bool italic = false,
      bool mono = false,
      double? fontSize,
      FontWeight? weight}) {
    return _PlainTextHolder(
      text: text,
      style: TextStyle(
        color: _color,
        fontSize: fontSize ?? _baseSize,
        fontStyle: italic ? FontStyle.italic : null,
        fontFamily: mono ? 'monospace' : null,
        fontWeight: weight,
      ),
    );
  }
}

/// 内部用: テキストノードを後で識別して上付き/下付き Unicode 化するために
/// 必要なホルダ
class _PlainTextHolder extends StatelessWidget {
  final String text;
  final TextStyle style;
  const _PlainTextHolder({required this.text, required this.style});

  @override
  Widget build(BuildContext context) {
    return Text(text, style: style);
  }
}

