// ════════════════════════════════════════════════════════════════════════
//  AI 生成スタジオ ページ (= ユーザー要望: 画像生成 / pptx 生成)
// ════════════════════════════════════════════════════════════════════════
//
// pageType=='aiStudio' のページで表示される全画面ビュー。
// 2 タブ構成:
//   - 画像生成: プロンプト → Gemini image モデルで画像生成 → 保存。
//   - スライド生成: トピック → AI がスライド構成を作成 (テキスト編集可・画像付き)
//     → テーマ/テンプレートに合わせて .pptx を生成。
class _AiStudioPageView extends StatefulWidget {
  final MindMapProvider provider;
  final String pageId;
  const _AiStudioPageView(
      {super.key, required this.provider, required this.pageId});

  @override
  State<_AiStudioPageView> createState() => _AiStudioPageViewState();
}

class _AiStudioPageViewState extends State<_AiStudioPageView>
    with SingleTickerProviderStateMixin {
  late final TabController _tab = TabController(length: 2, vsync: this);

  // ── 画像生成 ──
  final TextEditingController _imgPromptCtrl = TextEditingController();
  final List<Uint8List> _imgResults = []; // 生成結果 (複数枚) = ユーザー要望
  int _imgCount = 1; // 生成枚数
  int _imgDone = 0; // 進捗 (生成済み枚数)
  bool _imgLoading = false;
  String? _imgError;

  // ── スライド生成 ──
  final TextEditingController _slideTopicCtrl = TextEditingController();
  int _slideCount = 6;
  final List<_SlideDraft> _drafts = [];
  bool _slideLoading = false;
  String? _slideError;
  bool _includeImages = true; // 画像も加える (= ユーザー要望、 トグル可)
  bool _batchImgLoading = false;
  int _themeIndex = 0; // 内蔵テーマ選択
  String? _templateXml; // テンプレート .pptx から抽出した theme1.xml
  String? _templateName;

  @override
  void dispose() {
    _tab.dispose();
    _imgPromptCtrl.dispose();
    _slideTopicCtrl.dispose();
    for (final d in _drafts) {
      d.dispose();
    }
    super.dispose();
  }

  void _snack(String msg, Color c) {
    final m = ScaffoldMessenger.maybeOf(context);
    m?.showSnackBar(SnackBar(
        content: Text(msg),
        backgroundColor: c,
        duration: const Duration(seconds: 2)));
  }

  // ── 画像生成 (= ユーザー要望: 枚数指定) ───────────────────────
  Future<void> _generateImage() async {
    final prompt = _imgPromptCtrl.text.trim();
    if (prompt.isEmpty) {
      setState(() => _imgError = 'プロンプトを入力してください');
      return;
    }
    final n = _imgCount.clamp(1, 8);
    setState(() {
      _imgLoading = true;
      _imgError = null;
      _imgResults.clear();
      _imgDone = 0;
    });
    try {
      for (int i = 0; i < n; i++) {
        if (!mounted) return;
        final bytes = await widget.provider.generateAiImage(prompt);
        if (!mounted) return;
        setState(() {
          _imgResults.add(bytes);
          _imgDone = i + 1;
        });
      }
    } catch (e) {
      if (!mounted) return;
      setState(() => _imgError = e.toString().replaceFirst('Exception: ', ''));
    } finally {
      if (mounted) setState(() => _imgLoading = false);
    }
  }

  Future<void> _saveBytes(
      Uint8List bytes, String defaultName, String label) async {
    try {
      final outPath = await FilePicker.platform.saveFile(
        dialogTitle: widget.provider.t('save.named').replaceAll('{name}', label),
        fileName: defaultName,
        bytes: bytes,
      );
      if (outPath == null) return; // キャンセル
      // デスクトップでは saveFile が bytes を書き込まない場合があるので保険。
      try {
        final out = File(outPath);
        if (!await out.exists() || (await out.length()) == 0) {
          await out.writeAsBytes(bytes);
        }
      } catch (_) {}
      _snack('$labelを保存しました', const Color(0xFF43B97F));
    } catch (_) {
      _snack('保存に失敗しました', const Color(0xFFE53935));
    }
  }

  // ── スライド生成 ────────────────────────────────────────────
  Future<void> _generateSlides() async {
    final topic = _slideTopicCtrl.text.trim();
    if (topic.isEmpty) {
      setState(() => _slideError = 'トピックを入力してください');
      return;
    }
    setState(() {
      _slideLoading = true;
      _slideError = null;
    });
    try {
      final slides = await widget.provider
          .generateSlideOutline(topic, slides: _slideCount);
      if (!mounted) return;
      setState(() {
        for (final d in _drafts) {
          d.dispose();
        }
        _drafts
          ..clear()
          ..addAll(slides
              .map((s) => _SlideDraft(title: s.title, bullets: s.bullets)));
      });
      // 画像も加える設定なら、 各スライドの挿絵を背景で生成する。
      if (_includeImages &&
          (widget.provider.canUseAiRelay ||
              widget.provider.hasGeminiKey)) {
        _generateAllImages();
      }
    } catch (e) {
      if (!mounted) return;
      setState(
          () => _slideError = e.toString().replaceFirst('Exception: ', ''));
    } finally {
      if (mounted) setState(() => _slideLoading = false);
    }
  }

  // 各スライドの挿絵を順番に生成 (= ユーザー要望: 画像も加えたおしゃれなスライド)。
  Future<void> _generateAllImages() async {
    if (_batchImgLoading) return;
    setState(() => _batchImgLoading = true);
    for (final d in List<_SlideDraft>.from(_drafts)) {
      if (!mounted) break;
      if (d.image != null) continue;
      await _generateImageFor(d);
    }
    if (mounted) setState(() => _batchImgLoading = false);
  }

  Future<void> _generateImageFor(_SlideDraft d) async {
    // 画像もアプリ側キー (前払いクレジット) で動くので、 自分のキーの
    // 有無では止めない (= ユーザー要望)。 使えない時は provider が理由を投げる。
    if (!widget.provider.hasGeminiKey && !widget.provider.canUseAiRelay) {
      _snack(widget.provider.t('credit.insufficient'),
          const Color(0xFFE53935));
      return;
    }
    setState(() => d.imgLoading = true);
    try {
      final topic = _slideTopicCtrl.text.trim();
      final prompt = 'プレゼン資料に挿入する上品でシンプルなイラスト/図。'
          'テーマ「$topic」、スライド「${d.title.text.trim()}」の内容を表す。'
          '文字や表は入れない。 余白のある明るい配色。';
      final bytes = await widget.provider.generateAiImage(prompt);
      if (!mounted) return;
      setState(() => d.image = bytes);
    } catch (e) {
      if (mounted) {
        _snack(e.toString().replaceFirst('Exception: ', ''),
            const Color(0xFFE53935));
      }
    } finally {
      if (mounted) setState(() => d.imgLoading = false);
    }
  }

  // テンプレート .pptx を選んでデザイン (theme1.xml) を取り込む (= ユーザー要望)。
  Future<void> _pickTemplate() async {
    try {
      final res = await FilePicker.platform.pickFiles(
        dialogTitle: widget.provider.t('pick.pptxTemplate'),
        type: FileType.custom,
        allowedExtensions: ['pptx'],
        withData: true,
      );
      if (res == null || res.files.isEmpty) return;
      final f = res.files.first;
      final bytes = f.bytes ??
          (f.path != null ? await File(f.path!).readAsBytes() : null);
      if (bytes == null) return;
      final arch = ZipDecoder().decodeBytes(bytes);
      ArchiveFile? themeFile;
      for (final af in arch.files) {
        if (af.name == 'ppt/theme/theme1.xml') {
          themeFile = af;
          break;
        }
      }
      themeFile ??= arch.files
          .where((af) =>
              af.name.startsWith('ppt/theme/') && af.name.endsWith('.xml'))
          .cast<ArchiveFile?>()
          .firstWhere((af) => af != null, orElse: () => null);
      if (themeFile == null) {
        _snack('テンプレートからテーマを取得できませんでした', const Color(0xFFE53935));
        return;
      }
      final xml = utf8.decode(themeFile.content as List<int>);
      setState(() {
        _templateXml = xml;
        _templateName = f.name;
      });
      _snack('テンプレートを適用しました: ${f.name}', const Color(0xFF43B97F));
    } catch (_) {
      _snack('テンプレートの読み込みに失敗しました', const Color(0xFFE53935));
    }
  }

  void _addBullet(_SlideDraft d) {
    setState(() => d.bullets.add(TextEditingController()));
  }

  void _removeBullet(_SlideDraft d, int idx) {
    setState(() {
      d.bullets[idx].dispose();
      d.bullets.removeAt(idx);
    });
  }

  void _removeSlide(int i) {
    setState(() {
      _drafts[i].dispose();
      _drafts.removeAt(i);
    });
  }

  Future<void> _savePptx() async {
    final slides = _drafts
        .map((d) => d.toRecord())
        .where((r) => r.title.isNotEmpty || r.bullets.isNotEmpty)
        .toList();
    if (slides.isEmpty) return;
    final bytes = _OfficeFileTemplate.buildPptxFromSlides(
      slides,
      themeXml: _templateXml,
      theme: _kPptxThemes[_themeIndex.clamp(0, _kPptxThemes.length - 1)],
    );
    final base = _slideTopicCtrl.text.trim();
    final fname = (base.isEmpty ? 'slides' : base)
            .replaceAll(RegExp(r'[\\/:*?"<>|]'), '_') +
        '.pptx';
    await _saveBytes(bytes, fname, 'pptx');
  }

