  /// テーマの見本サムネイル (= ユーザー要望: 見本がないと分かりにくい)。
  /// 実際の pptx レイアウト (アクセント色のタイトルバー + 箇条書き) を縮小再現。
  Widget _themeThumb(_PptxTheme t, bool selected) {
    Color hex(String h) => Color(int.parse('FF$h', radix: 16));
    final bg = hex(t.lt1);
    final bar = t.accent;
    final txt = hex(t.dk1);
    return SizedBox(
      width: 104,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.center,
        mainAxisSize: MainAxisSize.min,
        children: [
          Container(
            width: 104,
            height: 58,
            decoration: BoxDecoration(
              color: bg,
              borderRadius: BorderRadius.circular(6),
              border: Border.all(
                  color: selected ? const Color(0xFFBA68C8) : Colors.white24,
                  width: selected ? 2 : 1),
            ),
            clipBehavior: Clip.antiAlias,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // タイトルバー (アクセント色) + 見出しのダミー線
                Container(
                  height: 18,
                  width: double.infinity,
                  color: bar,
                  alignment: Alignment.centerLeft,
                  padding: const EdgeInsets.symmetric(horizontal: 5),
                  child: Container(
                    height: 4,
                    width: 46,
                    decoration: BoxDecoration(
                        color: Colors.white.withValues(alpha: 0.9),
                        borderRadius: BorderRadius.circular(2)),
                  ),
                ),
                // 本文 (箇条書きのダミー線)
                Padding(
                  padding: const EdgeInsets.fromLTRB(6, 6, 6, 0),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      for (final wdt in const [54.0, 44.0, 38.0])
                        Padding(
                          padding: const EdgeInsets.only(bottom: 4),
                          child: Row(children: [
                            Container(
                                width: 3,
                                height: 3,
                                decoration: BoxDecoration(
                                    color: bar, shape: BoxShape.circle)),
                            const SizedBox(width: 4),
                            Container(
                                height: 3.5,
                                width: wdt,
                                decoration: BoxDecoration(
                                    color: txt.withValues(alpha: 0.6),
                                    borderRadius: BorderRadius.circular(2))),
                          ]),
                        ),
                    ],
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 3),
          Text(t.name,
              style: TextStyle(
                  color: selected ? Colors.white : Colors.white60,
                  fontSize: 11,
                  fontWeight: selected ? FontWeight.w700 : FontWeight.normal)),
        ],
      ),
    );
  }

  InputDecoration _inputDeco(String hint) => InputDecoration(
        hintText: hint,
        hintStyle: const TextStyle(color: Colors.white38),
        filled: true,
        fillColor: const Color(0xFF1A1A26),
        border: OutlineInputBorder(
            borderRadius: BorderRadius.circular(8),
            borderSide: BorderSide.none),
      );

  Widget _keyHint(String msg) => Container(
        margin: const EdgeInsets.only(bottom: 12),
        padding: const EdgeInsets.all(10),
        decoration: BoxDecoration(
          color: const Color(0xFF332B1A),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: const Color(0xFFFFB347)),
        ),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            const Icon(Icons.info_outline, color: Color(0xFFFFB347), size: 18),
            const SizedBox(width: 8),
            Expanded(
              child: Text(msg,
                  style: const TextStyle(color: Colors.white, fontSize: 12)),
            ),
          ]),
          const SizedBox(height: 6),
          // ── キーの取得導線 (= ユーザー要望: 利用者が自分でキーを取得) ──
          // BYOK 方針なので、 Google AI Studio で無料キーを取得する案内を出す。
          InkWell(
            onTap: () {
              try {
                launchUrl(Uri.parse('https://aistudio.google.com/apikey'),
                    mode: LaunchMode.externalApplication);
              } catch (_) {}
            },
            borderRadius: BorderRadius.circular(4),
            child: Padding(
              padding: EdgeInsets.symmetric(horizontal: 2, vertical: 2),
              child: Row(mainAxisSize: MainAxisSize.min, children: [
                Icon(Icons.open_in_new_rounded,
                    size: 13, color: Color(0xFFFFD27F)),
                SizedBox(width: 5),
                Text(context.read<MindMapProvider>().t('ai.getFreeKey'),
                    style: TextStyle(
                        color: Color(0xFFFFD27F),
                        fontSize: 12,
                        decoration: TextDecoration.underline,
                        decorationColor: Color(0xFFFFD27F))),
              ]),
            ),
          ),
        ]),
      );

  Widget _errorBox(String msg) => Container(
        padding: const EdgeInsets.all(10),
        decoration: BoxDecoration(
          color: const Color(0xFF3A1E1E),
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: const Color(0xFFE53935)),
        ),
        child: Row(children: [
          const Icon(Icons.error_outline, color: Color(0xFFE53935), size: 18),
          const SizedBox(width: 8),
          Expanded(
            child: Text(msg,
                style: const TextStyle(color: Colors.white, fontSize: 12)),
          ),
        ]),
      );
}

// ════════════════════════════════════════════════════════════════════════
//  空ファイル テンプレート生成
// ════════════════════════════════════════════════════════════════════════
//
// 「ファイルを作成」 メニュー用に、 各形式の最小限の空ファイルを生成する。
//
// - txt / csv: シンプルな空文字列バイト列
// - docx / pptx / xlsx: OOXML 規格に従った最小限の zip ファイル
//
// 既存の内蔵エディタ ( _DocxViewerDialog / _PptxViewerDialog /
// _SpreadsheetEditorDialog ) で開いて編集可能なレベルの中身にする。
class _OfficeFileTemplate {
  // ─── 中身つきのファイルを作る (= ユーザー要望: AI から pptx / pdf /
  //     xlsx / csv などを作れるように) ────────────────────────────────
  //
  // 空ファイルを作る buildEmpty と同じ土台を使い、 本文を流し込む。
  // 出来上がったファイルはアプリ内蔵のビューアでそのまま開ける。

  /// XML に入れて良い形に直す。
  static String _esc(String s) => s
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;');

  /// 中身つきのファイルを作る。
  ///   [rows]       … xlsx / csv の表 (行 × 列)
  ///   [paragraphs] … docx / txt の段落
  ///   [slides]     … pptx のスライド ({title, bullets})
  ///   [title]      … docx / pdf の見出し
  static Future<Uint8List> buildWithContent(
    String type, {
    List<List<String>>? rows,
    List<String>? paragraphs,
    List<({String title, List<String> bullets})>? slides,
    String? title,
  }) async {
    switch (type.toLowerCase()) {
      case 'txt':
      case 'md':
        final body = <String>[
          if ((title ?? '').isNotEmpty) '# $title', '',
          ...(paragraphs ?? const []),
        ].join('\n');
        return Uint8List.fromList(utf8.encode(body));
      case 'csv':
        final r = rows ?? const <List<String>>[];
        final out = StringBuffer();
        for (final line in r) {
          out.writeln(line.map((c) {
            final needsQuote =
                c.contains(',') || c.contains('"') || c.contains('\n');
            final v = c.replaceAll('"', '""');
            return needsQuote ? '"$v"' : v;
          }).join(','));
        }
        // Excel で文字化けしないよう BOM を付ける。
        return Uint8List.fromList(utf8.encode('﻿$out'));
      case 'xlsx':
        return _buildXlsxRows(rows ?? const <List<String>>[]);
      case 'docx':
        return _buildDocx(paragraphs: paragraphs, title: title);
      case 'pptx':
        // ★ AI に頼んで作る pptx も、 スライド生成と同じ「配色つき」 の作りに
        //   する (= ユーザー要望: テキストだけでなくお洒落に)。 以前はここだけ
        //   白地に黒文字の素の版 (_buildPptx) を使っていたので、 同じ内容でも
        //   見栄えがはっきり劣っていた。
        return buildPptxFromSlides([
          for (final sl in (slides ?? const <({String title, List<String> bullets})>[]))
            (title: sl.title, bullets: sl.bullets, image: null),
        ]);
      case 'pdf':
        return _buildPdf(title: title, paragraphs: paragraphs, rows: rows);
      default:
        throw ArgumentError('Unsupported file type: $type');
    }
  }

  /// 表の中身が入った xlsx。 excel パッケージで組むので確実に読み戻せる。
  static Uint8List _buildXlsxRows(List<List<String>> rows) {
    final excel = xls.Excel.createExcel();
    final name = excel.tables.keys.isNotEmpty
        ? excel.tables.keys.first
        : 'Sheet1';
    final sheet = excel[name];
    for (int r = 0; r < rows.length; r++) {
      for (int c = 0; c < rows[r].length; c++) {
        final raw = rows[r][c];
        // 数字に見えるものは数値として入れる (集計できるように)。
        final asNum = num.tryParse(raw.trim());
        sheet.updateCell(
          xls.CellIndex.indexByColumnRow(columnIndex: c, rowIndex: r),
          raw.trim().isEmpty
              ? xls.TextCellValue('')
              : (asNum == null
                  ? xls.TextCellValue(raw)
                  : (asNum is int
                      ? xls.IntCellValue(asNum)
                      : xls.DoubleCellValue(asNum.toDouble()))),
        );
      }
    }
    final encoded = excel.encode();
    if (encoded == null) throw Exception('xlsx エンコードに失敗しました');
    return Uint8List.fromList(encoded);
  }

  /// 本文つきの PDF。 日本語が豆腐にならないよう同梱フォントを使う。
  static Future<Uint8List> _buildPdf({
    String? title,
    List<String>? paragraphs,
    List<List<String>>? rows,
  }) async {
    // 日本語フォントは無くても作れるようにする (豆腐になるが落ちない)。
    pw.Font? font;
    try {
      font = await _PdfExporter._loadJapaneseFont();
    } catch (e) {
      debugPrint('PDF 用の日本語フォント読込に失敗 (続行): $e');
    }
    final doc = pw.Document();
    final theme = font == null
        ? null
        : pw.ThemeData.withFont(base: font, bold: font, italic: font);
    // ★ 中身が 1 つも無いと pdf パッケージが例外を投げるので、 必ず何か置く
    //   (= AI が本文を渡してこなかった時に「作成できませんでした」 になっていた)。
    final hasBody = (title ?? '').isNotEmpty ||
        (paragraphs?.isNotEmpty ?? false) ||
        (rows?.isNotEmpty ?? false);
    doc.addPage(
      pw.MultiPage(
        pageFormat: pdf.PdfPageFormat.a4,
        theme: theme,
        margin: const pw.EdgeInsets.all(40),
        build: (ctx) => [
          if (!hasBody) pw.Text(' '),
          if ((title ?? '').isNotEmpty)
            pw.Padding(
              padding: const pw.EdgeInsets.only(bottom: 16),
              child: pw.Text(title!,
                  style: pw.TextStyle(
                      fontSize: 20, fontWeight: pw.FontWeight.bold)),
            ),
          for (final p in (paragraphs ?? const <String>[]))
            pw.Padding(
              padding: const pw.EdgeInsets.only(bottom: 10),
              child: pw.Text(p, style: const pw.TextStyle(fontSize: 11)),
            ),
          if (rows != null && rows.isNotEmpty)
            pw.TableHelper.fromTextArray(
              data: rows,
              cellStyle: const pw.TextStyle(fontSize: 10),
              headerStyle:
                  pw.TextStyle(fontSize: 10, fontWeight: pw.FontWeight.bold),
              headerDecoration:
                  const pw.BoxDecoration(color: pdf.PdfColors.grey300),
              cellAlignment: pw.Alignment.centerLeft,
            ),
        ],
      ),
    );
    return Uint8List.fromList(await doc.save());
  }

  /// 指定形式の空ファイルのバイト列を返す。
  static Uint8List buildEmpty(String type) {
    switch (type.toLowerCase()) {
      case 'txt':
        return Uint8List.fromList(utf8.encode(''));
      case 'md':
        // Markdown (= ユーザー要望: 右クリックから md も生成できるように)。
        return Uint8List.fromList(utf8.encode(''));
      case 'html':
      case 'htm':
        // HTML (= ユーザー要望: マークダウンみたいに編集してプレビューを
        //   出せるように)。 空だと真っ白で分かりにくいので最小の骨組みを
        //   入れておく。
        return Uint8List.fromList(utf8.encode(
            '<!DOCTYPE html>\n'
            '<html lang="ja">\n'
            '<head>\n'
            '  <meta charset="utf-8">\n'
            '  <meta name="viewport" content="width=device-width, initial-scale=1">\n'
            '  <title>ページ</title>\n'
            // 同じ名前の .css を読む (= ユーザー要望: HTML & CSS)。
            '  <link rel="stylesheet" href="style.css">\n'
            '  <style>\n'
            '    body { font-family: sans-serif; margin: 24px; line-height: 1.7; }\n'
            '  </style>\n'
            '</head>\n'
            '<body>\n'
            '  <h1>見出し</h1>\n'
            '  <p>ここに本文を書きます。</p>\n'
            '</body>\n'
            '</html>\n'));
      case 'csv':
        return Uint8List.fromList(utf8.encode(''));
      case 'docx':
        return _buildDocx();
      case 'pptx':
        return _buildPptx();
      case 'xlsx':
        return _buildXlsx();
      default:
        throw ArgumentError('Unsupported file type: $type');
    }
  }

  /// 最小の OOXML zip helper: ファイル名 → 内容 (string) のマップから zip を組む。
  static Uint8List _buildZip(Map<String, String> files) {
    final archive = Archive();
    files.forEach((name, content) {
      final bytes = utf8.encode(content);
      archive.addFile(ArchiveFile(name, bytes.length, bytes));
    });
    // archive 3.x 系では encode() の戻り値が List<int>? (nullable)。
    // 空でないアーカイブなら基本 null は返らないが、 念のためチェック。
    final encoded = ZipEncoder().encode(archive);
    if (encoded == null) {
      throw Exception('Zip エンコードに失敗しました');
    }
    return Uint8List.fromList(encoded);
  }

  /// 空の .docx (Word ドキュメント) を生成。
  /// 4 ファイル構成 (Content_Types / .rels / document / document.rels)。
  static Uint8List _buildDocx({List<String>? paragraphs, String? title}) {
    // 段落 XML を組む。 何も渡されなければ従来どおり空の 1 段落。
    final body = StringBuffer();
    if ((title ?? '').isNotEmpty) {
      body.write('<w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr>'
          '<w:r><w:rPr><w:b/><w:sz w:val="36"/></w:rPr>'
          '<w:t xml:space="preserve">${_esc(title!)}</w:t></w:r></w:p>');
    }
    if (paragraphs == null || paragraphs.isEmpty) {
      if ((title ?? '').isEmpty) {
        body.write('<w:p><w:r><w:t></w:t></w:r></w:p>');
      }
    } else {
      for (final p in paragraphs) {
        body.write('<w:p><w:r>'
            '<w:t xml:space="preserve">${_esc(p)}</w:t>'
            '</w:r></w:p>');
      }
    }
    return _buildZip({
      '[Content_Types].xml': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
          '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
          '<Default Extension="xml" ContentType="application/xml"/>'
          '<Override PartName="/word/document.xml" '
          'ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
          '</Types>',
      '_rels/.rels': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
          '<Relationship Id="rId1" '
          'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" '
          'Target="word/document.xml"/>'
          '</Relationships>',
      'word/_rels/document.xml.rels':
          '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '</Relationships>',
      'word/document.xml': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
          '<w:body>'
          '$body'
          '<w:sectPr/>'
          '</w:body>'
          '</w:document>',
    });
  }

  /// 空の .xlsx (Excel) を生成。
  /// ── 手書きの最小 OOXML をやめ、 excel パッケージ自身で生成する ──
  ///   (= ユーザー要望: モバイルで xlsx が開けない不具合の修正)。
  /// 手書きの最小 xlsx は styles.xml / sharedStrings.xml を含まないため、
  /// 同じ excel パッケージの decodeBytes が読み込み時に例外を投げ、 内蔵
  /// スプレッドシートエディタが「ファイルを開けません」 になっていた。
  /// createExcel() で作れば確実に decodeBytes で読み戻せる。
  static Uint8List _buildXlsx() {
    final excel = xls.Excel.createExcel(); // 既定シート 'Sheet1' を含む空ブック
    final encoded = excel.encode();
    if (encoded == null) {
      throw Exception('xlsx エンコードに失敗しました');
    }
    return Uint8List.fromList(encoded);
  }

  /// 空の .pptx (PowerPoint) を生成。
  /// 1 枚の白紙スライドのみのプレゼン。 必要最小限 (presentation / slide /
  /// slideLayout / slideMaster / theme + rels)。 内蔵 PptxViewer は
  /// テキスト抽出にしか pptx を使わないので、 スライドが 1 枚あれば十分。
  /// スライド 1 枚分の XML。 タイトルと箇条書きをテキストボックスで置く。
  static String _pptxSlideXml(String title, List<String> bullets) {
    String box(int id, String name, int x, int y, int cx, int cy,
        List<String> lines, int sizePt, bool bold) {
      final paras = lines.isEmpty
          ? '<a:p/>'
          : lines
              .map((t) => '<a:p><a:r>'
                  '<a:rPr lang="ja-JP" altLang="en-US" sz="${sizePt * 100}"'
                  '${bold ? ' b="1"' : ''} dirty="0"/>'
                  '<a:t>${_esc(t)}</a:t>'
                  '</a:r></a:p>')
              .join();
      return '<p:sp>'
          '<p:nvSpPr>'
          '<p:cNvPr id="$id" name="$name"/>'
          '<p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr>'
          '<p:nvPr/>'
          '</p:nvSpPr>'
          '<p:spPr>'
          '<a:xfrm><a:off x="$x" y="$y"/><a:ext cx="$cx" cy="$cy"/></a:xfrm>'
          '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom>'
          '</p:spPr>'
          '<p:txBody>'
          '<a:bodyPr wrap="square"><a:normAutofit/></a:bodyPr>'
          '<a:lstStyle/>'
          '$paras'
          '</p:txBody>'
          '</p:sp>';
    }

    final shapes = StringBuffer();
    if (title.isNotEmpty) {
      shapes.write(box(2, 'Title', 685800, 685800, 7772400, 1143000,
          [title], 32, true));
    }
    if (bullets.isNotEmpty) {
      shapes.write(box(3, 'Body', 685800, 2057400, 7772400, 3886200,
          bullets.map((b) => '・$b').toList(), 18, false));
    }
    return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<p:sld xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
        'xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">'
        '<p:cSld>'
        '<p:spTree>'
        '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>'
        '<p:grpSpPr/>'
        '$shapes'
        '</p:spTree>'
        '</p:cSld>'
        '</p:sld>';
  }

  static Uint8List _buildPptx(
      {List<({String title, List<String> bullets})>? slides}) {
    // 渡されなければ従来どおり白紙 1 枚。
    final list = (slides == null || slides.isEmpty)
        ? <({String title, List<String> bullets})>[
            (title: '', bullets: const <String>[])
          ]
        : slides;
    final n = list.length;

    // スライドの枚数ぶん、 目録・関連付け・本体を作る。
    final slideOverrides = StringBuffer();
    final sldIds = StringBuffer();
    final presRels = StringBuffer();
    final extra = <String, String>{};
    for (var i = 0; i < n; i++) {
      final no = i + 1;
      slideOverrides.write('<Override PartName="/ppt/slides/slide$no.xml" '
          'ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>');
      // rId1 = slideMaster なので、 スライドは rId2 から始める。
      sldIds.write('<p:sldId id="${256 + i}" r:id="rId${no + 1}"/>');
      presRels.write('<Relationship Id="rId${no + 1}" '
          'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide" '
          'Target="slides/slide$no.xml"/>');
      extra['ppt/slides/slide$no.xml'] =
          _pptxSlideXml(list[i].title, list[i].bullets);
      extra['ppt/slides/_rels/slide$no.xml.rels'] =
          '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
          '<Relationship Id="rId1" '
          'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" '
          'Target="../slideLayouts/slideLayout1.xml"/>'
          '</Relationships>';
    }
    // テーマはスライドの後ろ番号にする。
    final themeRid = 'rId${n + 2}';
    presRels.write('<Relationship Id="$themeRid" '
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" '
        'Target="theme/theme1.xml"/>');

    final base = _buildPptxParts(
      slideOverrides: slideOverrides.toString(),
      sldIds: sldIds.toString(),
      presRels: presRels.toString(),
    );
    base.addAll(extra);
    return _buildZip(base);
  }

  static Map<String, String> _buildPptxParts({
    required String slideOverrides,
    required String sldIds,
    required String presRels,
  }) {
    return {
      '[Content_Types].xml': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
          '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
          '<Default Extension="xml" ContentType="application/xml"/>'
          '<Override PartName="/ppt/presentation.xml" '
          'ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/>'
          '$slideOverrides'
          '<Override PartName="/ppt/slideLayouts/slideLayout1.xml" '
          'ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/>'
          '<Override PartName="/ppt/slideMasters/slideMaster1.xml" '
          'ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/>'
          '<Override PartName="/ppt/theme/theme1.xml" '
          'ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>'
          '</Types>',
      '_rels/.rels': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
          '<Relationship Id="rId1" '
          'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" '
          'Target="ppt/presentation.xml"/>'
          '</Relationships>',
      'ppt/_rels/presentation.xml.rels':
          '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '<Relationship Id="rId1" '
              'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" '
              'Target="slideMasters/slideMaster1.xml"/>'
              '$presRels'
              '</Relationships>',
      'ppt/presentation.xml': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<p:presentation xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
          'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
          'xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">'
          '<p:sldMasterIdLst>'
          '<p:sldMasterId id="2147483648" r:id="rId1"/>'
          '</p:sldMasterIdLst>'
          '<p:sldIdLst>'
          '$sldIds'
          '</p:sldIdLst>'
          '<p:sldSz cx="9144000" cy="6858000"/>'
          '<p:notesSz cx="6858000" cy="9144000"/>'
          '</p:presentation>',
      'ppt/slideLayouts/_rels/slideLayout1.xml.rels':
          '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '<Relationship Id="rId1" '
              'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" '
              'Target="../slideMasters/slideMaster1.xml"/>'
              '</Relationships>',
      'ppt/slideLayouts/slideLayout1.xml':
          '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<p:sldLayout xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
              'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
              'xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" '
              'type="blank">'
              '<p:cSld name="Blank">'
              '<p:spTree>'
              '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>'
              '<p:grpSpPr/>'
              '</p:spTree>'
              '</p:cSld>'
              '</p:sldLayout>',
      'ppt/slideMasters/_rels/slideMaster1.xml.rels':
          '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '<Relationship Id="rId1" '
              'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" '
              'Target="../slideLayouts/slideLayout1.xml"/>'
              '<Relationship Id="rId2" '
              'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" '
              'Target="../theme/theme1.xml"/>'
              '</Relationships>',
      'ppt/slideMasters/slideMaster1.xml':
          '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<p:sldMaster xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
              'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
              'xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">'
              '<p:cSld>'
              '<p:bg><p:bgRef idx="1001"><a:schemeClr val="bg1"/></p:bgRef></p:bg>'
              '<p:spTree>'
              '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>'
              '<p:grpSpPr/>'
              '</p:spTree>'
              '</p:cSld>'
              '<p:clrMap bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2" '
              'accent1="accent1" accent2="accent2" accent3="accent3" '
              'accent4="accent4" accent5="accent5" accent6="accent6" '
              'hlink="hlink" folHlink="folHlink"/>'
              '<p:sldLayoutIdLst>'
              '<p:sldLayoutId id="2147483649" r:id="rId1"/>'
              '</p:sldLayoutIdLst>'
              '</p:sldMaster>',
      'ppt/theme/theme1.xml': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<a:theme xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
          'name="Office Theme">'
          '<a:themeElements>'
          '<a:clrScheme name="Office">'
          '<a:dk1><a:sysClr val="windowText" lastClr="000000"/></a:dk1>'
          '<a:lt1><a:sysClr val="window" lastClr="FFFFFF"/></a:lt1>'
          '<a:dk2><a:srgbClr val="1F497D"/></a:dk2>'
          '<a:lt2><a:srgbClr val="EEECE1"/></a:lt2>'
          '<a:accent1><a:srgbClr val="4F81BD"/></a:accent1>'
          '<a:accent2><a:srgbClr val="C0504D"/></a:accent2>'
          '<a:accent3><a:srgbClr val="9BBB59"/></a:accent3>'
          '<a:accent4><a:srgbClr val="8064A2"/></a:accent4>'
          '<a:accent5><a:srgbClr val="4BACC6"/></a:accent5>'
          '<a:accent6><a:srgbClr val="F79646"/></a:accent6>'
          '<a:hlink><a:srgbClr val="0000FF"/></a:hlink>'
          '<a:folHlink><a:srgbClr val="800080"/></a:folHlink>'
          '</a:clrScheme>'
          '<a:fontScheme name="Office">'
          '<a:majorFont><a:latin typeface="Calibri"/><a:ea typeface=""/><a:cs typeface=""/></a:majorFont>'
          '<a:minorFont><a:latin typeface="Calibri"/><a:ea typeface=""/><a:cs typeface=""/></a:minorFont>'
          '</a:fontScheme>'
          '<a:fmtScheme name="Office">'
          '<a:fillStyleLst>'
          '<a:solidFill><a:schemeClr val="phClr"/></a:solidFill>'
          '<a:solidFill><a:schemeClr val="phClr"/></a:solidFill>'
          '<a:solidFill><a:schemeClr val="phClr"/></a:solidFill>'
          '</a:fillStyleLst>'
          '<a:lnStyleLst>'
          '<a:ln w="9525"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln>'
          '<a:ln w="25400"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln>'
          '<a:ln w="38100"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln>'
          '</a:lnStyleLst>'
          '<a:effectStyleLst>'
          '<a:effectStyle><a:effectLst/></a:effectStyle>'
          '<a:effectStyle><a:effectLst/></a:effectStyle>'
          '<a:effectStyle><a:effectLst/></a:effectStyle>'
          '</a:effectStyleLst>'
          '<a:bgFillStyleLst>'
          '<a:solidFill><a:schemeClr val="phClr"/></a:solidFill>'
          '<a:solidFill><a:schemeClr val="phClr"/></a:solidFill>'
          '<a:solidFill><a:schemeClr val="phClr"/></a:solidFill>'
          '</a:bgFillStyleLst>'
          '</a:fmtScheme>'
          '</a:themeElements>'
          '</a:theme>',
    };
  }

  /// AI が作ったスライド構成から .pptx を生成する (= ユーザー要望: pptx 生成)。
  /// 各スライド = タイトル(アクセントバー) + 本文(箇条書き) + 任意の挿絵画像。
  /// [themeXml] が与えられればそれを theme1.xml として使う (テンプレート由来)。
  /// 無ければ [theme] (内蔵プリセット) から配色/フォントを生成する。
  static Uint8List buildPptxFromSlides(
      List<({String title, List<String> bullets, Uint8List? image})> slides,
      {String? themeXml,
      _PptxTheme? theme}) {
    final th = theme ?? _kPptxThemes.first;
    final themeContent = themeXml ?? th.themeXml();
    String esc(String s) => s
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;');

    final list = slides.isEmpty
        ? <({String title, List<String> bullets, Uint8List? image})>[
            (title: 'スライド', bullets: <String>[], image: null)
          ]
        : slides;
    final n = list.length;

    String slideXml(
        ({String title, List<String> bullets, Uint8List? image}) s) {
      final hasImg = s.image != null;
      final bodyCx = hasImg ? 4400000 : 8046720;
      final body = StringBuffer();
      if (s.bullets.isEmpty) {
        body.write('<a:p><a:endParaRPr lang="ja-JP"/></a:p>');
      } else {
        for (final b in s.bullets) {
          body.write('<a:p>'
              '<a:pPr><a:buFont typeface="Arial"/><a:buChar char="•"/></a:pPr>'
              '<a:r><a:rPr lang="ja-JP" sz="1800" dirty="0">'
              '<a:solidFill><a:schemeClr val="tx1"/></a:solidFill></a:rPr>'
              '<a:t>${esc(b)}</a:t></a:r></a:p>');
        }
      }
      final pic = hasImg
          ? '<p:pic>'
              '<p:nvPicPr><p:cNvPr id="4" name="Image"/><p:cNvPicPr/><p:nvPr/></p:nvPicPr>'
              '<p:blipFill><a:blip r:embed="rId2"/><a:stretch><a:fillRect/></a:stretch></p:blipFill>'
              '<p:spPr><a:xfrm><a:off x="5180000" y="1750000"/>'
              '<a:ext cx="3500000" cy="2625000"/></a:xfrm>'
              '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></p:spPr></p:pic>'
          : '';
      return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<p:sld xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
          'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
          'xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">'
          '<p:cSld><p:spTree>'
          '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>'
          '<p:grpSpPr/>'
          // アクセントカラーのタイトルバー (= おしゃれ要素)
          '<p:sp><p:nvSpPr><p:cNvPr id="2" name="TitleBar"/>'
          '<p:cNvSpPr/><p:nvPr/></p:nvSpPr>'
          '<p:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="9144000" cy="1300000"/></a:xfrm>'
          '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom>'
          '<a:solidFill><a:schemeClr val="accent1"/></a:solidFill></p:spPr>'
          '<p:txBody><a:bodyPr anchor="ctr" lIns="548640" rIns="548640"/><a:lstStyle/>'
          '<a:p><a:r><a:rPr lang="ja-JP" sz="2800" b="1" dirty="0">'
          '<a:solidFill><a:schemeClr val="bg1"/></a:solidFill></a:rPr>'
          '<a:t>${esc(s.title)}</a:t></a:r></a:p></p:txBody></p:sp>'
          // 本文 (箇条書き)
          '<p:sp><p:nvSpPr><p:cNvPr id="3" name="Body"/>'
          '<p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr/></p:nvSpPr>'
          '<p:spPr><a:xfrm><a:off x="548640" y="1650000"/>'
          '<a:ext cx="$bodyCx" cy="4850000"/></a:xfrm>'
          '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></p:spPr>'
          '<p:txBody><a:bodyPr/><a:lstStyle/>$body</p:txBody></p:sp>'
          '$pic'
          '</p:spTree></p:cSld></p:sld>';
    }

    final files = <String, String>{};
    final media = <String, List<int>>{};

    final ctSlides = StringBuffer();
    for (int i = 1; i <= n; i++) {
      ctSlides.write('<Override PartName="/ppt/slides/slide$i.xml" '
          'ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>');
    }
    files['[Content_Types].xml'] =
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
        '<Default Extension="xml" ContentType="application/xml"/>'
        '<Default Extension="png" ContentType="image/png"/>'
        '<Default Extension="jpeg" ContentType="image/jpeg"/>'
        '<Override PartName="/ppt/presentation.xml" '
        'ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/>'
        '$ctSlides'
        '<Override PartName="/ppt/slideLayouts/slideLayout1.xml" '
        'ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/>'
        '<Override PartName="/ppt/slideMasters/slideMaster1.xml" '
        'ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/>'
        '<Override PartName="/ppt/theme/theme1.xml" '
        'ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>'
        '</Types>';

    files['_rels/.rels'] =
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" '
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" '
        'Target="ppt/presentation.xml"/></Relationships>';

    final presRels = StringBuffer()
      ..write('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
          '<Relationship Id="rId1" '
          'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" '
          'Target="slideMasters/slideMaster1.xml"/>'
          '<Relationship Id="rId2" '
          'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" '
          'Target="theme/theme1.xml"/>');
    final sldIdLst = StringBuffer();
    for (int i = 1; i <= n; i++) {
      final rid = i + 2;
      presRels.write('<Relationship Id="rId$rid" '
          'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide" '
          'Target="slides/slide$i.xml"/>');
      sldIdLst.write('<p:sldId id="${255 + i}" r:id="rId$rid"/>');
      final s = list[i - 1];
      final rels = StringBuffer()
        ..write('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" '
            'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" '
            'Target="../slideLayouts/slideLayout1.xml"/>');
      if (s.image != null) {
        media['ppt/media/image$i.png'] = s.image!;
        rels.write('<Relationship Id="rId2" '
            'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" '
            'Target="../media/image$i.png"/>');
      }
      rels.write('</Relationships>');
      files['ppt/slides/_rels/slide$i.xml.rels'] = rels.toString();
      files['ppt/slides/slide$i.xml'] = slideXml(s);
    }
    presRels.write('</Relationships>');
    files['ppt/_rels/presentation.xml.rels'] = presRels.toString();

    files['ppt/presentation.xml'] =
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<p:presentation xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
        'xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">'
        '<p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="rId1"/></p:sldMasterIdLst>'
        '<p:sldIdLst>$sldIdLst</p:sldIdLst>'
        '<p:sldSz cx="9144000" cy="6858000"/>'
        '<p:notesSz cx="6858000" cy="9144000"/></p:presentation>';

    files['ppt/slideLayouts/_rels/slideLayout1.xml.rels'] =
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" '
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" '
        'Target="../slideMasters/slideMaster1.xml"/></Relationships>';
    files['ppt/slideLayouts/slideLayout1.xml'] =
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<p:sldLayout xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
        'xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" type="blank">'
        '<p:cSld name="Blank"><p:spTree>'
        '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>'
        '<p:grpSpPr/></p:spTree></p:cSld></p:sldLayout>';
    files['ppt/slideMasters/_rels/slideMaster1.xml.rels'] =
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" '
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" '
        'Target="../slideLayouts/slideLayout1.xml"/>'
        '<Relationship Id="rId2" '
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" '
        'Target="../theme/theme1.xml"/></Relationships>';
    files['ppt/slideMasters/slideMaster1.xml'] =
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<p:sldMaster xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
        'xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">'
        '<p:cSld><p:bg><p:bgRef idx="1001"><a:schemeClr val="bg1"/></p:bgRef></p:bg>'
        '<p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>'
        '<p:grpSpPr/></p:spTree></p:cSld>'
        '<p:clrMap bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2" '
        'accent1="accent1" accent2="accent2" accent3="accent3" '
        'accent4="accent4" accent5="accent5" accent6="accent6" '
        'hlink="hlink" folHlink="folHlink"/>'
        '<p:sldLayoutIdLst><p:sldLayoutId id="2147483649" r:id="rId1"/></p:sldLayoutIdLst>'
        '</p:sldMaster>';
    files['ppt/theme/theme1.xml'] = themeContent;

    // テキスト + バイナリ (画像) を 1 つの zip にまとめる。
    final archive = Archive();
    files.forEach((name, content) {
      final b = utf8.encode(content);
      archive.addFile(ArchiveFile(name, b.length, b));
    });
    media.forEach((name, bytes) {
      archive.addFile(ArchiveFile(name, bytes.length, bytes));
    });
    final encoded = ZipEncoder().encode(archive);
    if (encoded == null) throw Exception('Zip エンコードに失敗しました');
    return Uint8List.fromList(encoded);
  }
}

// ════════════════════════════════════════════════════════════════════════
//  YouTube ナビゲーション履歴 (SharedPreferences ベース)
// ════════════════════════════════════════════════════════════════════════
//
// _WindowsWebViewSheet (Windows 版 WebView) で開いた YouTube ページを
// 最大 3 件まで履歴として保存し、 次回ノードを開いた時に最新の URL から
// 復元できるようにする。
//
// - 動画ページ (youtube.com/watch?v=...) / 検索結果 / チャンネルページなど
//   YouTube ドメイン内なら何でも記録する。
// - 同じ URL が再訪問された場合は順位を最新に更新 (= 重複なし)。
// - 上限 3 件を超えたら、 古いものから削除。
class _YoutubeNavHistory {
  static const String _kKey = 'mokumoku_youtube_nav_history_v1';
  static const int _kMaxItems = 3;

  /// 履歴を取得 (新しい順)。 空ならそのまま空リスト。
  static Future<List<String>> history() async {
    try {
      final sp = await SharedPreferences.getInstance();
      return sp.getStringList(_kKey) ?? const [];
    } catch (_) {
      return const [];
    }
  }

  /// 最新の URL を取得。 履歴がなければ null。
  static Future<String?> latest() async {
    final h = await history();
    return h.isEmpty ? null : h.first;
  }

  /// URL を訪問履歴に追加。 既に同じ URL があれば最前に移動。
  /// 最大 3 件を超えたら末尾から削除。
  static Future<void> recordVisit(String url) async {
    if (url.isEmpty) return;
    try {
      final sp = await SharedPreferences.getInstance();
      final list = (sp.getStringList(_kKey) ?? const <String>[]).toList();
      // 既存のものは削除して、 先頭に追加 (= 重複防止 + 最新化)
      list.removeWhere((e) => e == url);
      list.insert(0, url);
      // 上限を適用
      while (list.length > _kMaxItems) {
        list.removeLast();
      }
      await sp.setStringList(_kKey, list);
    } catch (_) {/* 失敗時は無視 (= 履歴が更新されないだけ) */}
  }

  /// 履歴を全消去 (= 次回は widget.url から始まる)。
  static Future<void> clear() async {
    try {
      final sp = await SharedPreferences.getInstance();
      await sp.remove(_kKey);
    } catch (_) {}
  }
}

enum _DocxBlockKind { paragraph, table, image, math, pageBreak }

/// 段落の水平揃え。
enum _DocxAlign { left, center, right, justify }

extension _DocxAlignExt on _DocxAlign {
  /// OOXML の <w:jc w:val="..."/> の値
  String get jcValue {
    switch (this) {
      case _DocxAlign.left:
        return 'left';
      case _DocxAlign.center:
        return 'center';
      case _DocxAlign.right:
        return 'right';
      case _DocxAlign.justify:
        return 'both';
    }
  }

  TextAlign get textAlign {
    switch (this) {
      case _DocxAlign.left:
        return TextAlign.left;
      case _DocxAlign.center:
        return TextAlign.center;
      case _DocxAlign.right:
        return TextAlign.right;
      case _DocxAlign.justify:
        return TextAlign.justify;
    }
  }

  static _DocxAlign fromJc(String s) {
    final l = s.toLowerCase();
    if (l == 'center') return _DocxAlign.center;
    if (l == 'right' || l == 'end') return _DocxAlign.right;
    if (l == 'both' || l == 'justify' || l == 'distribute') {
      return _DocxAlign.justify;
    }
    return _DocxAlign.left;
  }
}

/// 段落スタイル
enum _DocxParaStyle {
  normal,
  title,
  heading1,
  heading2,
  heading3,
  quote,
  listBullet,
  listNumber
}

extension _DocxParaStyleExt on _DocxParaStyle {
  /// 見出し系スタイルかどうか (title / heading1-3)
  bool get isHeading =>
      this == _DocxParaStyle.title ||
      this == _DocxParaStyle.heading1 ||
      this == _DocxParaStyle.heading2 ||
      this == _DocxParaStyle.heading3;

  /// OOXML での pStyle 名
  String get pStyleName {
    switch (this) {
      case _DocxParaStyle.normal:
        return '';
      case _DocxParaStyle.title:
        return 'Title';
      case _DocxParaStyle.heading1:
        return 'Heading1';
      case _DocxParaStyle.heading2:
        return 'Heading2';
      case _DocxParaStyle.heading3:
        return 'Heading3';
      case _DocxParaStyle.quote:
        return 'Quote';
      case _DocxParaStyle.listBullet:
        return 'ListBullet';
      case _DocxParaStyle.listNumber:
        return 'ListNumber';
    }
  }

  String get label {
    switch (this) {
      case _DocxParaStyle.normal:
        return '本文';
      case _DocxParaStyle.title:
        return 'タイトル';
      case _DocxParaStyle.heading1:
        return '見出し 1';
      case _DocxParaStyle.heading2:
        return '見出し 2';
      case _DocxParaStyle.heading3:
        return '見出し 3';
      case _DocxParaStyle.quote:
        return '引用';
      case _DocxParaStyle.listBullet:
        return '箇条書き';
      case _DocxParaStyle.listNumber:
        return '番号付きリスト';
    }
  }

  static _DocxParaStyle fromPStyle(String s) {
    final l = s.toLowerCase();
    if (l.contains('title')) return _DocxParaStyle.title;
    if (l == 'heading1' || l == 'heading 1') return _DocxParaStyle.heading1;
    if (l == 'heading2' || l == 'heading 2') return _DocxParaStyle.heading2;
    if (l == 'heading3' || l == 'heading 3') return _DocxParaStyle.heading3;
    if (l.contains('heading')) return _DocxParaStyle.heading3;
    if (l.contains('quote')) return _DocxParaStyle.quote;
    if (l.contains('listbullet')) return _DocxParaStyle.listBullet;
    if (l.contains('listnumber')) return _DocxParaStyle.listNumber;
    return _DocxParaStyle.normal;
  }
}

/// 文字列の Run (= 連続した同一書式テキスト)。
/// プレーン編集と書式保持を両立するため、 Run のリストとして段落本文を保持する。
class _DocxRun {
  String text;
  bool bold;
  bool italic;
  bool underline;

  /// 文字色 (RRGGBB の int)。 null なら段落既定色。 (= ユーザー要望: Word の
  /// 文字色 `<w:color w:val="FF0000"/>` をアプリ内でも反映する)。
  int? colorRgb;

  /// フォント名 (`<w:rFonts w:ascii="..."/>`)。 null なら既定フォント。
  /// (= ユーザー要望: フォントの種類を変更できるように)。
  String? fontFamily;

  /// 文字の背景色 (蛍光ペン、 `<w:highlight w:val="yellow"/>` の val)。
  /// null なら無し (= ユーザー要望: 文字背景色も設定できるように)。
  String? highlight;

  _DocxRun(this.text,
      {this.bold = false,
      this.italic = false,
      this.underline = false,
      this.colorRgb,
      this.fontFamily,
      this.highlight});

  _DocxRun copy() => _DocxRun(text,
      bold: bold,
      italic: italic,
      underline: underline,
      colorRgb: colorRgb,
      fontFamily: fontFamily,
      highlight: highlight);
}

class _DocxTableStyle {
  int? fillRgb;
  int? borderRgb;
  int borderSz;

  _DocxTableStyle({this.fillRgb, this.borderRgb, this.borderSz = 4});

  _DocxTableStyle copy() => _DocxTableStyle(
      fillRgb: fillRgb, borderRgb: borderRgb, borderSz: borderSz);
}

class _DocxCellStyle {
  int? fillRgb;
  int? borderRgb;
  int? borderSz;

  _DocxCellStyle({this.fillRgb, this.borderRgb, this.borderSz});

  _DocxCellStyle copy() => _DocxCellStyle(
      fillRgb: fillRgb, borderRgb: borderRgb, borderSz: borderSz);
}

class _DocxBlock {
  _DocxBlockKind kind;
  _DocxParaStyle paraStyle;

  /// パラグラフ本文 (Run のリスト)
  List<_DocxRun> runs;

  /// テーブル: rows[r][c] = 各セルがブロックのリスト (基本は段落1個)
  List<List<List<_DocxBlock>>> tableRows;

  /// 画像: media 内のファイル名 (例: 'image1.png')
  String? imageName;

  /// 画像のサイズ ヒント (幅 EMU、 1cm ≈ 360000 EMU)
  int? imageWidthEmu;
  int? imageHeightEmu;

  /// 数式: LaTeX 文字列
  String? mathTex;

  /// 段落の水平揃え (left / center / right / justify)。
  /// Word の `<w:jc w:val="center"/>` 相当。
  _DocxAlign align;

  /// 段落単位のフォントサイズ override (pt 単位)。 null なら paraStyle の
  /// デフォルトを使う。 ツールバーから変更可能。
  double? fontSize;

  _DocxTableStyle? tableStyle;
  List<List<_DocxCellStyle>> tableCellStyles;

  /// 元ファイル由来のブロックの、 元 XML 全文 (`<w:p>…</w:p>` /
  /// `<w:tbl>…</w:tbl>`)。 保存/ダウンロード時、 ユーザーが編集していない
  /// ブロックはこの XML をそのまま書き戻すことで、 行間・インデント・
  /// ルビ・スタイル参照・画像アンカー等のパースしきれない情報を完全に
  /// 保持する (= ユーザー要望 2026-07: ダウンロードすると元の docx と
  /// レイアウトが異なる → Word にできる限り近づける)。
  /// ブロックを編集したら null にして再生成へフォールバック。
  String? originalXml;

  _DocxBlock.paragraph(
      {required this.paraStyle,
      required this.runs,
      this.align = _DocxAlign.left,
      this.fontSize})
      : kind = _DocxBlockKind.paragraph,
        tableRows = const [],
        tableCellStyles = const [];

  _DocxBlock.image(this.imageName, {this.imageWidthEmu, this.imageHeightEmu})
      : kind = _DocxBlockKind.image,
        paraStyle = _DocxParaStyle.normal,
        runs = const [],
        tableRows = const [],
        tableCellStyles = const [],
        align = _DocxAlign.center;

  _DocxBlock.math(this.mathTex)
      : kind = _DocxBlockKind.math,
        paraStyle = _DocxParaStyle.normal,
        runs = const [],
        tableRows = const [],
        tableCellStyles = const [],
        align = _DocxAlign.center;

  _DocxBlock.table(this.tableRows,
      {this.tableStyle, List<List<_DocxCellStyle>>? tableCellStyles})
      : kind = _DocxBlockKind.table,
        paraStyle = _DocxParaStyle.normal,
        runs = const [],
        tableCellStyles = tableCellStyles ?? const [],
        align = _DocxAlign.left;

  _DocxBlock.pageBreak()
      : kind = _DocxBlockKind.pageBreak,
        paraStyle = _DocxParaStyle.normal,
        runs = const [],
        tableRows = const [],
        tableCellStyles = const [],
        align = _DocxAlign.left;

  /// 段落本文をプレーンテキストとして取得
  String get plainText => runs.map((r) => r.text).join();

  /// プレーンテキストから Run リストを単一 Run に置き換え
  set plainText(String s) {
    if (runs.isEmpty) {
      runs = [_DocxRun(s)];
    } else {
      // 1 個目の Run の書式を保ちつつテキスト差し替え (残りは破棄)
      final first = runs.first;
      runs = [
        _DocxRun(s,
            bold: first.bold, italic: first.italic, underline: first.underline)
      ];
    }
  }

  /// このブロックの **ディープコピー** を返す。 undo / redo 用。
  /// テーブルブロックの場合、 セル内の全ブロックも再帰的にコピーする。
  _DocxBlock copy() {
    final c = _DocxBlock.paragraph(
      paraStyle: paraStyle,
      runs: runs.map((r) => r.copy()).toList(),
      align: align,
      fontSize: fontSize,
    );
    c.kind = kind;
    c.imageName = imageName;
    c.imageWidthEmu = imageWidthEmu;
    c.imageHeightEmu = imageHeightEmu;
    c.mathTex = mathTex;
    c.originalXml = originalXml;
    c.tableStyle = tableStyle?.copy();
    if (kind == _DocxBlockKind.table) {
      c.tableRows = tableRows
          .map((row) =>
              row.map((cell) => cell.map((b) => b.copy()).toList()).toList())
          .toList();
      c.tableCellStyles = tableCellStyles
          .map((row) => row.map((style) => style.copy()).toList())
          .toList();
    } else {
      c.tableRows = const [];
      c.tableCellStyles = const [];
    }
    return c;
  }
}

/// _DocxViewerDialog の undo/redo 用スナップショット。
/// ブロックリスト全体 (= ディープコピー) + 選択状態を持つ。
class _DocxSnapshot {
  final List<_DocxBlock> blocks;
  final int? selectedIdx;
  _DocxSnapshot(this.blocks, this.selectedIdx);
}

// ─── .ipynb (Jupyter Notebook) 読み取り専用ビューア ───────────────────
// (= ユーザー要望: ipynb などの拡張子もエディタとして開けるように)。
// 追加の依存パッケージ無しで実装 (jsonDecode / base64Decode / _MathRenderer)。
// nbformat v4 (トップレベル 'cells') と v3 ('worksheets[].cells') に対応。

/// パース済みの 1 セル。
class _IpynbCell {
  final String type; // 'markdown' | 'code' | 'raw'
  final String source;
  final List<_IpynbOutput> outputs;
  final int? execCount;
  const _IpynbCell(this.type, this.source, this.outputs, this.execCount);
}

/// code セルの 1 出力 (標準出力 / テキスト結果 / 画像 / エラー)。
class _IpynbOutput {
  final String kind; // 'text' | 'stream' | 'error' | 'image'
  final String? text;
  final Uint8List? image;
  const _IpynbOutput._(this.kind, this.text, this.image);
  factory _IpynbOutput.text(String? t) => _IpynbOutput._('text', t, null);
  factory _IpynbOutput.stream(String? t) => _IpynbOutput._('stream', t, null);
  factory _IpynbOutput.error(String? t) => _IpynbOutput._('error', t, null);
  factory _IpynbOutput.image(Uint8List b) => _IpynbOutput._('image', null, b);
}

class _IpynbViewerDialog extends StatefulWidget {
  final String filePath;
  final String fileName;
  final bool isDarkMode;

  /// 他ビューアと引数形状を合わせるためのフック (このビューアは読み取り専用
  /// なので実際には呼ばれない)。
  final void Function(String newPath, String newName)? onRenamed;
  final VoidCallback? onSaved;

  const _IpynbViewerDialog({
    required this.filePath,
    required this.fileName,
    this.isDarkMode = true,
    this.onRenamed,
    this.onSaved,
  });

  @override
  State<_IpynbViewerDialog> createState() => _IpynbViewerDialogState();
}

class _IpynbViewerDialogState extends State<_IpynbViewerDialog> {
  List<_IpynbCell> _cells = const [];
  bool _loading = true;
  String? _error;

  @override
  void initState() {
    super.initState();
    _load();
  }

  static String _stripAnsi(String s) =>
      s.replaceAll(RegExp(r'\x1B\[[0-9;?]*[ -/]*[@-~]'), '');

  String _joinSource(dynamic src) {
    if (src is List) return src.map((e) => e.toString()).join();
    if (src == null) return '';
    return src.toString();
  }

  List<dynamic> _extractCells(dynamic root) {
    if (root is Map) {
      final cells = root['cells'];
      if (cells is List) return cells;
      // nbformat v3: worksheets[].cells
      final ws = root['worksheets'];
      if (ws is List) {
        final out = <dynamic>[];
        for (final w in ws) {
          if (w is Map && w['cells'] is List) {
            out.addAll(w['cells'] as List);
          }
        }
        return out;
      }
    }
    return const [];
  }

  Uint8List? _decodeB64Image(dynamic v) {
    if (v is! String || v.isEmpty) return null;
    try {
      return base64Decode(v.replaceAll('\n', '').replaceAll('\r', '').trim());
    } catch (_) {
      return null;
    }
  }

  void _parseOutput(Map<dynamic, dynamic> o, List<_IpynbOutput> sink) {
    final ot = (o['output_type'] ?? '').toString();
    if (ot == 'stream') {
      sink.add(_IpynbOutput.stream(_joinSource(o['text'])));
    } else if (ot == 'error') {
      final tb = o['traceback'];
      final raw = (tb is List)
          ? tb.map((e) => e.toString()).join('\n')
          : (o['evalue']?.toString() ??
              o['ename']?.toString() ??
              'Error');
      sink.add(_IpynbOutput.error(_stripAnsi(raw)));
    } else if (ot == 'execute_result' || ot == 'display_data') {
      final data = o['data'];
      if (data is Map) {
        final png = _decodeB64Image(data['image/png']) ??
            _decodeB64Image(data['image/jpeg']);
        if (png != null) {
          sink.add(_IpynbOutput.image(png));
          return;
        }
        final tp = data['text/plain'];
        if (tp != null) {
          sink.add(_IpynbOutput.text(_joinSource(tp)));
          return;
        }
        final html = data['text/html'];
        if (html != null) {
          sink.add(_IpynbOutput.text(_joinSource(html)));
          return;
        }
      }
    }
  }

  Future<void> _load() async {
    try {
      final text = await File(widget.filePath).readAsString();
      final dynamic root = jsonDecode(text);
      final cellsRaw = _extractCells(root);
      final parsed = <_IpynbCell>[];
      for (final c in cellsRaw) {
        if (c is! Map) continue;
        final type = (c['cell_type'] ?? 'raw').toString();
        final source = _joinSource(c['source']);
        final outputs = <_IpynbOutput>[];
        if (type == 'code') {
          final outs = c['outputs'];
          if (outs is List) {
            for (final o in outs) {
              if (o is Map) _parseOutput(o, outputs);
            }
          }
        }
        final ec = c['execution_count'];
        parsed.add(
            _IpynbCell(type, source, outputs, ec is int ? ec : null));
      }
      if (!mounted) return;
      setState(() {
        _cells = parsed;
        _loading = false;
      });
    } catch (e) {
      debugPrint('ipynb load error: $e');
      if (!mounted) return;
      setState(() {
        _error = '$e';
        _loading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final dark = widget.isDarkMode;
    final bg = dark ? const Color(0xFF1A1A24) : const Color(0xFFF4F4F2);
    final fg = dark ? Colors.white : const Color(0xFF1A1A24);
    return Column(
      children: [
        // ── ヘッダー ──
        Container(
          height: 52,
          padding: const EdgeInsets.symmetric(horizontal: 8),
          color: dark ? const Color(0xFF23233A) : const Color(0xFFE4E4E0),
          child: Row(
            children: [
              const Icon(Icons.menu_book_rounded,
                  color: Color(0xFFF37726), size: 20),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  widget.fileName,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                      color: fg, fontSize: 15, fontWeight: FontWeight.w600),
                ),
              ),
              IconButton(
                tooltip: context.read<MindMapProvider>().t('ipynb.openExternal'),
                icon: Icon(Icons.open_in_new,
                    color: fg.withValues(alpha: 0.7), size: 20),
                onPressed: () => OpenFilex.open(widget.filePath),
              ),
              IconButton(
                tooltip: context.read<MindMapProvider>().t('btn.close'),
                icon: Icon(Icons.close, color: fg, size: 22),
                onPressed: () => Navigator.of(context).maybePop(),
              ),
            ],
          ),
        ),
        Expanded(child: _buildBody(dark, bg, fg)),
      ],
    );
  }

  Widget _buildBody(bool dark, Color bg, Color fg) {
    if (_loading) {
      return Container(
        color: bg,
        child: const Center(child: CircularProgressIndicator()),
      );
    }
    if (_error != null) {
      return Container(
        color: bg,
        alignment: Alignment.center,
        padding: const EdgeInsets.all(24),
        child: Text(
          'ノートブックを読み込めませんでした\n$_error',
          textAlign: TextAlign.center,
          style: TextStyle(color: fg.withValues(alpha: 0.8)),
        ),
      );
    }
    if (_cells.isEmpty) {
      return Container(
        color: bg,
        alignment: Alignment.center,
        child: Text(context.read<MindMapProvider>().t('ipynb.empty'),
            style: TextStyle(color: fg.withValues(alpha: 0.7))),
      );
    }
    return Container(
      color: bg,
      child: ListView.builder(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 12),
        itemCount: _cells.length,
        itemBuilder: (_, i) => _buildCell(_cells[i], dark, fg),
      ),
    );
  }

  Widget _buildCell(_IpynbCell cell, bool dark, Color fg) {
    if (cell.type == 'markdown') return _buildMarkdownCell(cell, dark, fg);
    if (cell.type == 'code') return _buildCodeCell(cell, dark, fg);
    // raw セル
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: SelectableText(
        cell.source,
        style: TextStyle(
            color: fg.withValues(alpha: 0.75),
            fontFamily: 'monospace',
            fontSize: 13),
      ),
    );
  }

  /// $...$ を含む行はインライン数式として _MathRenderer で描画。
  Widget _buildMdInline(String line, Color fg,
      {double size = 14, FontWeight weight = FontWeight.normal}) {
    if (!RegExp(r'\$[^$]+\$').hasMatch(line)) {
      return SelectableText(line,
          style: TextStyle(
              color: fg, fontSize: size, fontWeight: weight, height: 1.4));
    }
    final parts = line.split(r'$');
    final spans = <Widget>[];
    for (var k = 0; k < parts.length; k++) {
      final seg = parts[k];
      if (k.isOdd) {
        spans.add(_MathRenderer(tex: seg, displayMode: false, color: fg));
      } else if (seg.isNotEmpty) {
        spans.add(Text(seg,
            style: TextStyle(
                color: fg, fontSize: size, fontWeight: weight, height: 1.4)));
      }
    }
    return Wrap(crossAxisAlignment: WrapCrossAlignment.center, children: spans);
  }

  Widget _codeBlock(String code, bool dark, Color fg) {
    return Container(
      width: double.infinity,
      margin: const EdgeInsets.symmetric(vertical: 4),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: dark ? const Color(0xFF11111A) : const Color(0xFFECECEC),
        borderRadius: BorderRadius.circular(6),
      ),
      child: SelectableText(
        code,
        style: TextStyle(
            color: dark ? const Color(0xFFD6E2F0) : const Color(0xFF1A1A24),
            fontFamily: 'monospace',
            fontSize: 12.5,
            height: 1.35),
      ),
    );
  }

  Widget _buildMarkdownCell(_IpynbCell cell, bool dark, Color fg) {
    final lines = cell.source.split('\n');
    final widgets = <Widget>[];
    bool inFence = false;
    final codeBuf = <String>[];
    for (final raw in lines) {
      if (raw.trimLeft().startsWith('```')) {
        if (inFence) {
          widgets.add(_codeBlock(codeBuf.join('\n'), dark, fg));
          codeBuf.clear();
          inFence = false;
        } else {
          inFence = true;
        }
        continue;
      }
      if (inFence) {
        codeBuf.add(raw);
        continue;
      }
      final trimmed = raw.trimRight();
      if (trimmed.trim().isEmpty) {
        widgets.add(const SizedBox(height: 8));
        continue;
      }
      if (trimmed.startsWith('### ')) {
        widgets.add(Padding(
            padding: const EdgeInsets.only(top: 4, bottom: 2),
            child: _buildMdInline(trimmed.substring(4), fg,
                size: 15, weight: FontWeight.w700)));
      } else if (trimmed.startsWith('## ')) {
        widgets.add(Padding(
            padding: const EdgeInsets.only(top: 6, bottom: 3),
            child: _buildMdInline(trimmed.substring(3), fg,
                size: 18, weight: FontWeight.w700)));
      } else if (trimmed.startsWith('# ')) {
        widgets.add(Padding(
            padding: const EdgeInsets.only(top: 8, bottom: 4),
            child: _buildMdInline(trimmed.substring(2), fg,
                size: 21, weight: FontWeight.w800)));
      } else if (trimmed.startsWith('- ') || trimmed.startsWith('* ')) {
        widgets.add(Padding(
            padding: const EdgeInsets.only(left: 8, top: 1, bottom: 1),
            child: _buildMdInline('•  ${trimmed.substring(2)}', fg)));
      } else {
        widgets.add(_buildMdInline(trimmed, fg));
      }
    }
    if (inFence && codeBuf.isNotEmpty) {
      widgets.add(_codeBlock(codeBuf.join('\n'), dark, fg));
    }
    return Container(
      width: double.infinity,
      margin: const EdgeInsets.only(bottom: 10),
      child: Column(
          crossAxisAlignment: CrossAxisAlignment.start, children: widgets),
    );
  }

  Widget _buildCodeCell(_IpynbCell cell, bool dark, Color fg) {
    final gutter = cell.execCount != null ? 'In [${cell.execCount}]' : 'In [ ]';
    return Container(
      width: double.infinity,
      margin: const EdgeInsets.only(bottom: 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Container(
            width: double.infinity,
            decoration: BoxDecoration(
              color: dark ? const Color(0xFF11131C) : const Color(0xFFF0F0F3),
              borderRadius: BorderRadius.circular(6),
              border: Border.all(
                  color:
                      dark ? const Color(0xFF2A2A3D) : const Color(0xFFD8D8DC)),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(10, 6, 10, 0),
                  child: Text(gutter,
                      style: const TextStyle(
                          color: Color(0xFF5C9DFF),
                          fontFamily: 'monospace',
                          fontSize: 11,
                          fontWeight: FontWeight.w700)),
                ),
                Padding(
                  padding: const EdgeInsets.fromLTRB(10, 2, 10, 10),
                  child: SelectableText(
                    cell.source,
                    style: TextStyle(
                        color: dark
                            ? const Color(0xFFE6ECF5)
                            : const Color(0xFF15151E),
                        fontFamily: 'monospace',
                        fontSize: 12.5,
                        height: 1.4),
                  ),
                ),
              ],
            ),
          ),
          for (final o in cell.outputs) _buildOutput(o, dark, fg),
        ],
      ),
    );
  }

  Widget _buildOutput(_IpynbOutput o, bool dark, Color fg) {
    if (o.kind == 'image' && o.image != null) {
      return Container(
        margin: const EdgeInsets.only(top: 6, left: 6),
        alignment: Alignment.centerLeft,
        child: ClipRRect(
          borderRadius: BorderRadius.circular(4),
          child: Image.memory(
            o.image!,
            fit: BoxFit.contain,
            errorBuilder: (_, __, ___) => const SizedBox.shrink(),
          ),
        ),
      );
    }
    final isError = o.kind == 'error';
    return Container(
      width: double.infinity,
      margin: const EdgeInsets.only(top: 6, left: 6),
      padding: const EdgeInsets.all(8),
      decoration: BoxDecoration(
        color: isError
            ? Colors.redAccent.withValues(alpha: 0.12)
            : (dark ? const Color(0xFF0E0E16) : const Color(0xFFF7F7F7)),
        borderRadius: BorderRadius.circular(4),
        border: isError
            ? Border.all(color: Colors.redAccent.withValues(alpha: 0.4))
            : null,
      ),
      child: SelectableText(
        o.text ?? '',
        style: TextStyle(
            color: isError
                ? Colors.redAccent.withValues(alpha: 0.95)
                : fg.withValues(alpha: 0.85),
            fontFamily: 'monospace',
            fontSize: 12,
            height: 1.35),
      ),
    );
  }
}

class _DocxViewerDialog extends StatefulWidget {
  final String filePath;
  final String fileName;
  final bool isDarkMode;
  final void Function(String newPath, String newName)? onRenamed;
  final VoidCallback? onSaved;

  /// 「画面分割で開く」 ボタン押下時に呼ばれる。 画面分割パネル内で
  /// 表示されている時は null を渡してボタン非表示。
  /// ユーザー要望: 「word もパワポも画面分割に対応させて」 +
  ///   「wordファイル等、 上に左画面分割の項目も付けて」 (= isLeftPanel)。
  final void Function(String path, String name, {bool isLeftPanel})?
      onSplitOpen;

  const _DocxViewerDialog({
    required this.filePath,
    required this.fileName,
    this.isDarkMode = true,
    this.onRenamed,
    this.onSaved,
    this.onSplitOpen,
  });

  @override
  State<_DocxViewerDialog> createState() => _DocxViewerDialogState();
}

class _DocxViewerDialogState extends State<_DocxViewerDialog> {
  late String _currentFilePath = widget.filePath;
  late String _currentFileName = widget.fileName;

  bool _loading = true;
  String? _loadError;
  OverlayEntry? _noticeEntry;

  /// 文書本文 (ブロックのリスト)
  final List<_DocxBlock> _blocks = [];

  /// メディア (画像) ファイル名 → バイト列
  final Map<String, Uint8List> _media = {};

  /// 元 zip のファイル一覧 (保存時に書式系 XML を保持するため)
  Archive? _origArchive;

  bool _dirty = false;

  /// 選択中のブロックインデックス (null = 何も選択していない)
  int? _selectedIdx;

  /// 編集中のブロック (null = 閲覧モード)
  int? _editingIdx;
  final TextEditingController _editCtrl = TextEditingController();
  final FocusNode _editFocus = FocusNode();

  /// 表セルの編集状態 (簡易): row,col,blockIdx で表現
  int? _editingTableBlockIdx;
  int? _editingTableRow;
  int? _editingTableCol;

  /// AI 編集中フラグ
  bool _aiBusy = false;

  /// 元ファイル読み込み済みのフラグ (= 保存先存在チェック用)
  bool _docInitialized = false;

  final ScrollController _scroll = ScrollController();
  final GlobalKey _docScrollViewportKey = GlobalKey();

  // ─── Undo / Redo ────────────────────────────────────────────────
  final List<_DocxSnapshot> _undoStack = [];
  final List<_DocxSnapshot> _redoStack = [];
  static const int _maxHistory = 100;

  /// 現在のブロックリスト全体をディープコピーしてスナップショットを作る。
  /// メディア (画像) はファイル名参照しか保持していないため、 _media は
  /// スナップショットに含めない (= undo で画像が消えるなら、 _media には
  /// 元データが残り続ける可能性があるが、 表示には影響しない)。
  _DocxSnapshot _captureSnapshot() {
    return _DocxSnapshot(
      _blocks.map((b) => b.copy()).toList(),
      _selectedIdx,
    );
  }

  void _restoreSnapshot(_DocxSnapshot s) {
    setState(() {
      _blocks
        ..clear()
        ..addAll(s.blocks.map((b) => b.copy()));
      if (_blocks.isEmpty) {
        _blocks.add(_DocxBlock.paragraph(
            paraStyle: _DocxParaStyle.normal, runs: [_DocxRun('')]));
      }
      _selectedIdx = (s.selectedIdx != null && s.selectedIdx! < _blocks.length)
          ? s.selectedIdx
          : null;
      _editingIdx = null;
      _editingTableBlockIdx = null;
      _editingTableRow = null;
      _editingTableCol = null;
      _dirty = true;
    });
  }

  /// 編集の **前** に呼ぶ。 redo スタックはクリア。
  void _pushUndo() {
    _undoStack.add(_captureSnapshot());
    if (_undoStack.length > _maxHistory) _undoStack.removeAt(0);
    _redoStack.clear();
  }

  bool get _canUndo => _undoStack.isNotEmpty;
  bool get _canRedo => _redoStack.isNotEmpty;

  void _undo() {
    if (_undoStack.isEmpty) return;
    _commitEdit();
    _commitTableEdit();
    final cur = _captureSnapshot();
    final prev = _undoStack.removeLast();
    _redoStack.add(cur);
    if (_redoStack.length > _maxHistory) _redoStack.removeAt(0);
    _restoreSnapshot(prev);
  }

  void _redo() {
    if (_redoStack.isEmpty) return;
    _commitEdit();
    _commitTableEdit();
    final cur = _captureSnapshot();
    final next = _redoStack.removeLast();
    _undoStack.add(cur);
    if (_undoStack.length > _maxHistory) _undoStack.removeAt(0);
    _restoreSnapshot(next);
  }

  @override
  void initState() {
    super.initState();
    _loadFile();
    // ── アプリ本体の × でも未保存確認が出るよう登録 (= ユーザー要望) ──
    kUnsavedCloseGuards[identityHashCode(this)] = () async {
      if (!mounted) return true;
      return _confirmDiscard();
    };
  }

  @override
  void dispose() {
    kUnsavedCloseGuards.remove(identityHashCode(this));
    _noticeEntry?.remove();
    _noticeEntry = null;
    _editCtrl.dispose();
    _editFocus.dispose();
    _hfCtrl.dispose();
    _hfFocus.dispose();
    _scroll.dispose();
    super.dispose();
  }

  // ─── 読み込み ───────────────────────────────────────────────────
  Future<void> _loadFile() async {
    try {
      final bytes = await File(_currentFilePath).readAsBytes();
      final archive = ZipDecoder().decodeBytes(bytes);
      _origArchive = archive;

      // メディアを抽出
      for (final f in archive.files) {
        if (f.name.startsWith('word/media/') && f.isFile) {
          final short = f.name.substring('word/media/'.length);
          _media[short] = Uint8List.fromList(f.content as List<int>);
        }
      }

      // relationships で rId → media ファイル名
      final rels = <String, String>{};
      for (final f in archive.files) {
        if (f.name == 'word/_rels/document.xml.rels' && f.isFile) {
          final xml = utf8.decode(f.content as List<int>, allowMalformed: true);
          final relRe =
              RegExp(r'<Relationship[^>]*Id="([^"]+)"[^>]*Target="([^"]+)"');
          for (final m in relRe.allMatches(xml)) {
            final rId = m.group(1)!;
            var target = m.group(2)!;
            if (target.startsWith('media/')) {
              target = target.substring('media/'.length);
            }
            rels[rId] = target;
          }
        }
      }

      // document.xml を解析
      for (final f in archive.files) {
        if (f.name == 'word/document.xml' && f.isFile) {
          final xml = utf8.decode(f.content as List<int>, allowMalformed: true);
          _parseBody(xml, rels);
          break;
        }
      }

      if (_blocks.isEmpty) {
        _blocks.add(_DocxBlock.paragraph(
            paraStyle: _DocxParaStyle.normal, runs: [_DocxRun('')]));
      }
      _docInitialized = true;
      if (mounted) setState(() => _loading = false);
    } catch (e, st) {
      debugPrint('DocxEditor load error: $e\n$st');
      if (mounted) {
        setState(() {
          _loading = false;
          _loadError = '$e';
        });
      }
    }
  }

  /// document.xml の <w:body>...</w:body> から段落/表/画像/数式を抽出。
  /// 簡易パーサ (正規表現ベース) のため、 複雑なネストは取りこぼす可能性あり。
  void _parseBody(String xml, Map<String, String> rels) {
    // body 部分
    final bodyMatch =
        RegExp(r'<w:body\b[^>]*>([\s\S]*?)</w:body>').firstMatch(xml);
    final body = bodyMatch?.group(1) ?? xml;
    int i = 0;
    while (i < body.length) {
      // 次の <w:p> または <w:tbl> を探す
      final pStart = body.indexOf('<w:p', i);
      final tStart = body.indexOf('<w:tbl', i);
      int nextStart;
      String tag;
      if (pStart < 0 && tStart < 0) break;
      if (pStart < 0) {
        nextStart = tStart;
        tag = 'tbl';
      } else if (tStart < 0) {
        nextStart = pStart;
        tag = 'p';
      } else {
        if (pStart < tStart) {
          nextStart = pStart;
          tag = 'p';
        } else {
          nextStart = tStart;
          tag = 'tbl';
        }
      }
      // タグの終端を探す (自己閉じも考慮)
      if (tag == 'p') {
        // 自己閉じ ( <w:p/> ) の場合
        final selfClose =
            RegExp(r'<w:p\s*/>').firstMatch(body.substring(nextStart));
        if (selfClose != null && selfClose.start == 0) {
          _blocks.add(_DocxBlock.paragraph(
              paraStyle: _DocxParaStyle.normal, runs: [_DocxRun('')]));
          i = nextStart + selfClose.end;
          continue;
        }
        final end = body.indexOf('</w:p>', nextStart);
        if (end < 0) break;
        final inner = body.substring(nextStart + 4, end);
        final block = _parseParagraph(inner, rels);
        if (block != null) {
          // 元 XML を保持 (= 未編集ブロックは保存時にそのまま書き戻す)。
          block.originalXml = body.substring(nextStart, end + '</w:p>'.length);
          _blocks.add(block);
        }
        i = end + '</w:p>'.length;
      } else {
        final end = body.indexOf('</w:tbl>', nextStart);
        if (end < 0) break;
        final inner = body.substring(nextStart + 6, end);
        final block = _parseTable(inner, rels);
        if (block != null) {
          block.originalXml =
              body.substring(nextStart, end + '</w:tbl>'.length);
          _blocks.add(block);
        }
        i = end + '</w:tbl>'.length;
      }
    }
  }

  _DocxBlock? _parseParagraph(String inner, Map<String, String> rels) {
    // スタイル
    final styleMatch =
        RegExp(r'<w:pStyle[^>]*w:val="([^"]+)"', caseSensitive: false)
            .firstMatch(inner);
    final style = styleMatch != null
        ? _DocxParaStyleExt.fromPStyle(styleMatch.group(1)!)
        : _DocxParaStyle.normal;

    // 水平揃え (<w:jc w:val="center"/> 等)
    final jcMatch = RegExp(r'<w:jc[^>]*w:val="([^"]+)"', caseSensitive: false)
        .firstMatch(inner);
    final align = jcMatch != null
        ? _DocxAlignExt.fromJc(jcMatch.group(1)!)
        : _DocxAlign.left;

    // フォントサイズ (<w:sz w:val="24"/> = half-pt なので /2 で pt)
    // 段落の最初の <w:rPr><w:sz/></w:rPr> を見る (簡易)
    double? fontSize;
    final szMatch = RegExp(r'<w:sz[^>]*w:val="(\d+)"', caseSensitive: false)
        .firstMatch(inner);
    if (szMatch != null) {
      final halfPt = int.tryParse(szMatch.group(1)!);
      if (halfPt != null && halfPt > 0) fontSize = halfPt / 2.0;
    }

    // ページ区切り
    if (RegExp(r'<w:br[^>]*w:type="page"', caseSensitive: false)
        .hasMatch(inner)) {
      return _DocxBlock.pageBreak();
    }

    // 画像参照 (drawing > blip)
    final blipMatch =
        RegExp(r'<a:blip[^>]*r:embed="([^"]+)"', caseSensitive: false)
            .firstMatch(inner);
    if (blipMatch != null) {
      final rId = blipMatch.group(1)!;
      final target = rels[rId];
      if (target != null) {
        // サイズ取得
        int? cx, cy;
        final extentMatch = RegExp(r'<wp:extent[^>]*cx="(\d+)"[^>]*cy="(\d+)"')
            .firstMatch(inner);
        if (extentMatch != null) {
          cx = int.tryParse(extentMatch.group(1)!);
          cy = int.tryParse(extentMatch.group(2)!);
        }
        return _DocxBlock.image(target, imageWidthEmu: cx, imageHeightEmu: cy);
      }
    }

    // 数式 (OMML <m:oMath>...</m:oMath>) — LaTeX に逆変換は困難なので
    // テキスト風に取り出す。
    final mathMatch =
        RegExp(r'<m:oMath\b[^>]*>([\s\S]*?)</m:oMath>').firstMatch(inner);
    if (mathMatch != null) {
      // <m:t>...</m:t> のテキストを連結
      final mathBuf = StringBuffer();
      final mtRe = RegExp(r'<m:t\b[^>]*>([\s\S]*?)</m:t>');
      for (final mm in mtRe.allMatches(mathMatch.group(1)!)) {
        mathBuf.write(_unescapeXml(mm.group(1) ?? ''));
      }
      return _DocxBlock.math(mathBuf.toString());
    }

    // 通常段落: <w:r> ごとに分けて Run のリストを作る
    final runs = <_DocxRun>[];
    final runRe = RegExp(r'<w:r\b[^>]*>([\s\S]*?)</w:r>', caseSensitive: false);
    for (final rm in runRe.allMatches(inner)) {
      final ri = rm.group(1) ?? '';
      // 書式
      final bold =
          RegExp(r'<w:b\b(?:\s|/|>)', caseSensitive: false).hasMatch(ri) &&
              !RegExp(r'<w:b\s+w:val="(0|false)"', caseSensitive: false)
                  .hasMatch(ri);
      final italic =
          RegExp(r'<w:i\b(?:\s|/|>)', caseSensitive: false).hasMatch(ri) &&
              !RegExp(r'<w:i\s+w:val="(0|false)"', caseSensitive: false)
                  .hasMatch(ri);
      final underline = RegExp(r'<w:u\b', caseSensitive: false).hasMatch(ri);
      // 文字色 (<w:color w:val="FF0000"/>)。 'auto' は段落既定色に任せる。
      // (= ユーザー要望: Word の文字色をアプリ内でも表示する)。
      final colorMatch =
          RegExp(r'<w:color\b[^>]*w:val="([^"]+)"', caseSensitive: false)
              .firstMatch(ri);
      final colorRgb = _docxRgb(colorMatch?.group(1));
      // フォント名 (<w:rFonts w:ascii="..."/>)。 東アジア指定しか無い
      // ファイルもあるので eastAsia も見る (= ユーザー要望: フォント変更)。
      final fontsMatch = RegExp(
              r'<w:rFonts\b[^>]*w:(?:ascii|eastAsia)="([^"]+)"',
              caseSensitive: false)
          .firstMatch(ri);
      final fontFamily = fontsMatch?.group(1);
      // 蛍光ペン (<w:highlight w:val="yellow"/>) (= ユーザー要望: 背景色)。
      final hlMatch =
          RegExp(r'<w:highlight\b[^>]*w:val="([^"]+)"', caseSensitive: false)
              .firstMatch(ri);
      final hlVal = hlMatch?.group(1);
      final highlight = (hlVal == null || hlVal == 'none') ? null : hlVal;
      // テキスト
      final textBuf = StringBuffer();
      final tRe =
          RegExp(r'<w:t(?:\s[^>]*)?>([\s\S]*?)</w:t>', caseSensitive: false);
      for (final tm in tRe.allMatches(ri)) {
        textBuf.write(_unescapeXml(tm.group(1) ?? ''));
      }
      // <w:tab/> はタブ、 <w:br/> は改行
      final hasTab = RegExp(r'<w:tab\b', caseSensitive: false).hasMatch(ri);
      final hasBr = RegExp(r'<w:br\b', caseSensitive: false).hasMatch(ri);
      var text = textBuf.toString();
      if (hasTab) text = '\t$text';
      if (hasBr) text = '$text\n';
      if (text.isNotEmpty) {
        runs.add(_DocxRun(text,
            bold: bold,
            italic: italic,
            underline: underline,
            colorRgb: colorRgb,
            fontFamily: fontFamily,
            highlight: highlight));
      }
    }
    if (runs.isEmpty) runs.add(_DocxRun(''));
    return _DocxBlock.paragraph(
      paraStyle: style,
      runs: runs,
      align: align,
      fontSize: fontSize,
    );
  }

  String? _docxAttr(String attrs, String name) {
    final re = RegExp('${RegExp.escape(name)}="([^"]*)"', caseSensitive: false);
    return re.firstMatch(attrs)?.group(1);
  }

  int? _docxRgb(String? value) {
    if (value == null) return null;
    var v = value.trim();
    if (v.isEmpty || v.toLowerCase() == 'auto') return null;
    if (v.length > 6) v = v.substring(v.length - 6);
    return int.tryParse(v, radix: 16);
  }

  int? _docxShadingFill(String xml) {
    final m = RegExp(r'<w:shd\b([^>]*)>', caseSensitive: false).firstMatch(xml);
    if (m == null) return null;
    return _docxRgb(_docxAttr(m.group(1) ?? '', 'w:fill'));
  }

  ({int? rgb, int? sz}) _docxFirstBorder(String xml) {
    final m = RegExp(r'<w:(?:top|left|bottom|right|insideH|insideV)\b([^>]*)>',
            caseSensitive: false)
        .firstMatch(xml);
    if (m == null) return (rgb: null, sz: null);
    final attrs = m.group(1) ?? '';
    return (
      rgb: _docxRgb(_docxAttr(attrs, 'w:color')),
      sz: int.tryParse(_docxAttr(attrs, 'w:sz') ?? ''),
    );
  }

  _DocxTableStyle _parseDocxTableStyle(String inner) {
    final pr =
        RegExp(r'<w:tblPr\b[^>]*>([\s\S]*?)</w:tblPr>', caseSensitive: false)
            .firstMatch(inner)
            ?.group(1);
    final border = _docxFirstBorder(pr ?? '');
    return _DocxTableStyle(
      fillRgb: _docxShadingFill(pr ?? ''),
      borderRgb: border.rgb,
      borderSz: border.sz ?? 4,
    );
  }

  _DocxCellStyle _parseDocxCellStyle(String tc) {
    final pr =
        RegExp(r'<w:tcPr\b[^>]*>([\s\S]*?)</w:tcPr>', caseSensitive: false)
            .firstMatch(tc)
            ?.group(1);
    final border = _docxFirstBorder(pr ?? '');
    return _DocxCellStyle(
      fillRgb: _docxShadingFill(pr ?? ''),
      borderRgb: border.rgb,
      borderSz: border.sz,
    );
  }

  _DocxBlock? _parseTable(String inner, Map<String, String> rels) {
    final rows = <List<List<_DocxBlock>>>[];
    final cellStyles = <List<_DocxCellStyle>>[];
    final trRe =
        RegExp(r'<w:tr\b[^>]*>([\s\S]*?)</w:tr>', caseSensitive: false);
    for (final trm in trRe.allMatches(inner)) {
      final tr = trm.group(1) ?? '';
      final cells = <List<_DocxBlock>>[];
      final rowStyles = <_DocxCellStyle>[];
      final tcRe =
          RegExp(r'<w:tc\b[^>]*>([\s\S]*?)</w:tc>', caseSensitive: false);
      for (final tcm in tcRe.allMatches(tr)) {
        final tc = tcm.group(1) ?? '';
        final cellBlocks = <_DocxBlock>[];
        final pRe =
            RegExp(r'<w:p\b[^>]*>([\s\S]*?)</w:p>', caseSensitive: false);
        for (final pm in pRe.allMatches(tc)) {
          final p = _parseParagraph(pm.group(1) ?? '', rels);
          if (p != null) cellBlocks.add(p);
        }
        if (cellBlocks.isEmpty) {
          cellBlocks.add(_DocxBlock.paragraph(
              paraStyle: _DocxParaStyle.normal, runs: [_DocxRun('')]));
        }
        cells.add(cellBlocks);
        rowStyles.add(_parseDocxCellStyle(tc));
      }
      if (cells.isNotEmpty) {
        rows.add(cells);
        cellStyles.add(rowStyles);
      }
    }
    if (rows.isEmpty) return null;
    return _DocxBlock.table(rows,
        tableStyle: _parseDocxTableStyle(inner), tableCellStyles: cellStyles);
  }

  static String _unescapeXml(String s) => s
      .replaceAll('&amp;', '&')
      .replaceAll('&lt;', '<')
      .replaceAll('&gt;', '>')
      .replaceAll('&quot;', '"')
      .replaceAll('&apos;', "'");

  static String _escapeXml(String s) => s
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&apos;');

  // ─── 編集オペレーション ─────────────────────────────────────────
  void _beginEditBlock(int idx, {Offset? tapLocalPos}) {
    if (idx < 0 || idx >= _blocks.length) return;
    final b = _blocks[idx];
    if (b.kind != _DocxBlockKind.paragraph) return;
    _pushUndo();
    _commitEdit();
    // ── クリックした位置にカーソルを置く ──
    // (= ユーザー要望 2026-07: 「テキストを入力したらボックスの右端の位置に
    //  カーソルが来るのではなく、 クリックした位置がピンポイントで編集
    //  できるようにして」)。 タップ座標をブロックのテキストレイアウト
    //  (TextPainter) で文字オフセットへ変換する。 変換できない時は従来
    //  どおり文末。
    int caret = b.plainText.length;
    if (tapLocalPos != null) {
      try {
        final box =
            _keyForBlock(idx).currentContext?.findRenderObject() as RenderBox?;
        final width = box?.size.width;
        if (width != null && width > 16) {
          TextStyle st = _paragraphTextStyle(b.paraStyle, Colors.black);
          if (b.fontSize != null && b.fontSize! > 0) {
            st = st.copyWith(fontSize: b.fontSize);
          }
          final tp = TextPainter(
            text: TextSpan(text: b.plainText, style: st),
            textDirection: TextDirection.ltr,
            textAlign: b.align.textAlign,
            maxLines: null,
          )..layout(maxWidth: width - 10);
          // _buildBlockRow の Padding(horizontal:4, vertical:2) と
          // _renderParagraph の縦 Padding を補正する。
          final vp = _DocxParaStyleExt(b.paraStyle).isHeading ? 10.0 : 4.0;
          final local = Offset(
            (tapLocalPos.dx - 5).clamp(0.0, width),
            (tapLocalPos.dy - 2 - vp).clamp(0.0, 100000.0),
          );
          caret = tp
              .getPositionForOffset(local)
              .offset
              .clamp(0, b.plainText.length)
              .toInt();
          tp.dispose();
        }
      } catch (_) {
        caret = b.plainText.length;
      }
    }
    setState(() {
      _editingIdx = idx;
      _editCtrl.text = b.plainText;
      _editCtrl.selection = TextSelection.collapsed(offset: caret);
      _selectedIdx = idx;
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _editFocus.requestFocus();
    });
  }

  void _commitEdit() {
    final idx = _editingIdx;
    if (idx == null) return;
    if (idx < _blocks.length) {
      final b = _blocks[idx];
      if (b.kind == _DocxBlockKind.paragraph) {
        final newText = _editCtrl.text;
        if (b.plainText != newText) {
          b.plainText = newText;
          // 編集済み → 元 XML は使えない (= 再生成にフォールバック)。
          b.originalXml = null;
          _dirty = true;
        }
      }
    }
    setState(() => _editingIdx = null);
  }

  void _commitTableEdit() {
    final bi = _editingTableBlockIdx;
    final r = _editingTableRow;
    final col = _editingTableCol;
    if (bi == null || r == null || col == null) return;
    if (bi < _blocks.length) {
      final tb = _blocks[bi];
      if (tb.kind == _DocxBlockKind.table) {
        if (r < tb.tableRows.length &&
            col < tb.tableRows[r].length &&
            tb.tableRows[r][col].isNotEmpty) {
          final cellPara = tb.tableRows[r][col].first;
          if (cellPara.kind == _DocxBlockKind.paragraph) {
            if (cellPara.plainText != _editCtrl.text) {
              cellPara.plainText = _editCtrl.text;
              // セル編集 → 表全体を再生成する必要がある。
              tb.originalXml = null;
              _dirty = true;
            }
          }
        }
      }
    }
    setState(() {
      _editingTableBlockIdx = null;
      _editingTableRow = null;
      _editingTableCol = null;
    });
  }

  void _beginEditTableCell(int blockIdx, int row, int col) {
    final b = _blocks[blockIdx];
    if (b.kind != _DocxBlockKind.table) return;
    _pushUndo();
    _commitEdit();
    _commitTableEdit();
    final cellBlocks = b.tableRows[row][col];
    final p = cellBlocks.firstWhere(
      (x) => x.kind == _DocxBlockKind.paragraph,
      orElse: () {
        final np = _DocxBlock.paragraph(
            paraStyle: _DocxParaStyle.normal, runs: [_DocxRun('')]);
        cellBlocks.add(np);
        return np;
      },
    );
    setState(() {
      _editingTableBlockIdx = blockIdx;
      _editingTableRow = row;
      _editingTableCol = col;
      _editCtrl.text = p.plainText;
      _editCtrl.selection =
          TextSelection.collapsed(offset: _editCtrl.text.length);
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _editFocus.requestFocus();
    });
  }

  void _insertParagraphAfter(int idx, _DocxParaStyle style) {
    _pushUndo();
    _commitEdit();
    _commitTableEdit();
    setState(() {
      _blocks.insert(idx + 1,
          _DocxBlock.paragraph(paraStyle: style, runs: [_DocxRun('')]));
      _selectedIdx = idx + 1;
      _dirty = true;
    });
    _beginEditBlock(idx + 1);
  }

  void _changeParaStyle(int idx, _DocxParaStyle style) {
    if (idx < 0 || idx >= _blocks.length) return;
    final b = _blocks[idx];
    if (b.kind != _DocxBlockKind.paragraph) return;
    _pushUndo();
    setState(() {
      b.paraStyle = style;
      b.originalXml = null; // スタイル変更 → 再生成へ
      _dirty = true;
    });
  }

  /// 段落の水平揃えを変更。
  void _changeAlign(int idx, _DocxAlign align) {
    if (idx < 0 || idx >= _blocks.length) return;
    final b = _blocks[idx];
    if (b.kind != _DocxBlockKind.paragraph) return;
    _pushUndo();
    setState(() {
      b.align = align;
      b.originalXml = null; // 揃え変更 → 再生成へ
      _dirty = true;
    });
  }

  /// 段落のフォントサイズを ±1 pt で増減。
  /// override が無ければ paraStyle のデフォルトから開始。
  void _bumpFontSize(int idx, int delta) {
    if (idx < 0 || idx >= _blocks.length) return;
    final b = _blocks[idx];
    if (b.kind != _DocxBlockKind.paragraph) return;
    _pushUndo();
    final current = b.fontSize ?? _PdfExporter._docxFontSize(b.paraStyle);
    final next = (current + delta).clamp(6.0, 96.0);
    setState(() {
      b.fontSize = next;
      b.originalXml = null; // サイズ変更 → 再生成へ
      _dirty = true;
    });
  }

  /// フォントサイズを数値で直接入力するダイアログ。
  /// プリセット (8/9/10/11/12/14/16/18/20/24/28/36/48/72 pt) もタップで選択可能。
  Future<void> _showFontSizeInputDialog(int idx) async {
    if (idx < 0 || idx >= _blocks.length) return;
    final b = _blocks[idx];
    if (b.kind != _DocxBlockKind.paragraph) return;
    final current = b.fontSize ?? _PdfExporter._docxFontSize(b.paraStyle);
    final controller = TextEditingController(text: current.toStringAsFixed(0));
    final focus = FocusNode();
    final result = await showDialog<double?>(
      context: context,
      builder: (dctx) {
        return StatefulBuilder(builder: (sctx, setS) {
          // 入力時のリアルタイムバリデーション
          double? parseValue() {
            final raw = controller.text.trim();
            if (raw.isEmpty) return null;
            final v = double.tryParse(raw);
            if (v == null) return null;
            if (v < 6 || v > 96) return null;
            return v;
          }

          final valid = parseValue() != null;
          return AlertDialog(
            backgroundColor: const Color(0xFF22222E),
            title: Row(children: [
              Icon(Icons.text_fields_rounded,
                  color: Color(0xFF6C63FF), size: 22),
              SizedBox(width: 8),
              Text(context.read<MindMapProvider>().t('docx.fontSize'),
                  style: const TextStyle(color: Colors.white)),
            ]),
            content: SizedBox(
              width: 360,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(context.read<MindMapProvider>().t('docx.numericInput'),
                      style: TextStyle(color: Colors.white70, fontSize: 12)),
                  const SizedBox(height: 8),
                  TextField(
                    controller: controller,
                    focusNode: focus,
                    autofocus: true,
                    keyboardType: TextInputType.number,
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 20,
                        fontWeight: FontWeight.w700),
                    decoration: InputDecoration(
                      filled: true,
                      fillColor: const Color(0xFF1A1A24),
                      suffixText: 'pt',
                      suffixStyle: const TextStyle(color: Colors.white54),
                      contentPadding: const EdgeInsets.symmetric(
                          horizontal: 12, vertical: 10),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(6),
                        borderSide: const BorderSide(color: Colors.white24),
                      ),
                      enabledBorder: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(6),
                        borderSide: const BorderSide(color: Colors.white24),
                      ),
                      focusedBorder: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(6),
                        borderSide: const BorderSide(
                            color: Color(0xFF6C63FF), width: 2),
                      ),
                    ),
                    onChanged: (_) => setS(() {}),
                    onSubmitted: (_) {
                      final v = parseValue();
                      if (v != null) Navigator.of(dctx).pop(v);
                    },
                  ),
                  if (!valid && controller.text.trim().isNotEmpty) ...[
                    const SizedBox(height: 4),
                    Text(context.read<MindMapProvider>().t('docx.range6to96'),
                        style:
                            TextStyle(color: Colors.redAccent, fontSize: 11)),
                  ],
                  const SizedBox(height: 14),
                  Text(context.read<MindMapProvider>().t('docx.quickSelect'),
                      style: TextStyle(color: Colors.white70, fontSize: 12)),
                  const SizedBox(height: 6),
                  Wrap(
                    spacing: 6,
                    runSpacing: 6,
                    children: [
                      for (final preset in const [
                        8,
                        9,
                        10,
                        11,
                        12,
                        14,
                        16,
                        18,
                        20,
                        24,
                        28,
                        36,
                        48,
                        72
                      ])
                        InkWell(
                          onTap: () {
                            controller.text = preset.toString();
                            controller.selection = TextSelection(
                              baseOffset: 0,
                              extentOffset: controller.text.length,
                            );
                            setS(() {});
                          },
                          borderRadius: BorderRadius.circular(4),
                          child: Container(
                            padding: const EdgeInsets.symmetric(
                                horizontal: 10, vertical: 6),
                            decoration: BoxDecoration(
                              color: const Color(0xFF3A3A4A),
                              borderRadius: BorderRadius.circular(4),
                              border: Border.all(
                                color: parseValue() == preset.toDouble()
                                    ? const Color(0xFF6C63FF)
                                    : Colors.white24,
                                width: parseValue() == preset.toDouble()
                                    ? 1.5
                                    : 0.5,
                              ),
                            ),
                            child: Text(
                              '$preset',
                              style: const TextStyle(
                                  color: Colors.white, fontSize: 12),
                            ),
                          ),
                        ),
                    ],
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dctx).pop(),
                child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                    style: const TextStyle(color: Colors.white54)),
              ),
              FilledButton(
                onPressed:
                    valid ? () => Navigator.of(dctx).pop(parseValue()) : null,
                style: FilledButton.styleFrom(
                  backgroundColor: const Color(0xFF6C63FF),
                  foregroundColor: Colors.white,
                ),
                child: Text(context.read<MindMapProvider>().t('btn.apply')),
              ),
            ],
          );
        });
      },
    );
    if (result != null && mounted) {
      setState(() {
        b.fontSize = result;
        b.originalXml = null; // サイズ変更 → 再生成へ
        _dirty = true;
      });
    }
    controller.dispose();
    focus.dispose();
  }

  void _deleteBlock(int idx) {
    if (idx < 0 || idx >= _blocks.length) return;
    _pushUndo();
    if (_blocks.length == 1) {
      _blocks[0] = _DocxBlock.paragraph(
          paraStyle: _DocxParaStyle.normal, runs: [_DocxRun('')]);
    } else {
      _blocks.removeAt(idx);
    }
    setState(() {
      _dirty = true;
      _selectedIdx = null;
      _editingIdx = null;
    });
  }

  void _moveBlock(int idx, int delta) {
    final newIdx = idx + delta;
    if (newIdx < 0 || newIdx >= _blocks.length) return;
    _pushUndo();
    _commitEdit();
    setState(() {
      final b = _blocks.removeAt(idx);
      _blocks.insert(newIdx, b);
      _selectedIdx = newIdx;
      _dirty = true;
    });
  }

  Future<void> _insertImage() async {
    final result = await FilePicker.platform.pickFiles(
      dialogTitle: context.read<MindMapProvider>().t('pick.image'),
      type: FileType.image,
    );
    if (result == null || result.files.isEmpty) return;
    final file = result.files.first;
    if (file.path == null) return;
    final bytes = await File(file.path!).readAsBytes();
    final ext = file.path!.contains('.')
        ? file.path!.substring(file.path!.lastIndexOf('.') + 1).toLowerCase()
        : 'png';
    // ユニークなメディア名生成
    int n = 1;
    while (_media.containsKey('mokumoku_image$n.$ext')) {
      n++;
    }
    final mediaName = 'mokumoku_image$n.$ext';
    _pushUndo();
    _media[mediaName] = Uint8List.fromList(bytes);
    // 標準的な画像サイズ (約 10cm 幅)
    const defaultWidth = 3600000; // 約 10cm
    final aspectRatio = 0.5625; // ざっくり 16:9
    setState(() {
      final insertAt = (_selectedIdx ?? _blocks.length - 1) + 1;
      _blocks.insert(
          insertAt,
          _DocxBlock.image(mediaName,
              imageWidthEmu: defaultWidth,
              imageHeightEmu: (defaultWidth * aspectRatio).round()));
      _selectedIdx = insertAt;
      _dirty = true;
    });
  }

  /// 紙の余白をダブルクリックした時: そこまで空の段落を足して、
  /// 一番下の段落を編集状態にする (= ユーザー要望: 好きな箇所に書ける。
  /// 行間は変えないので、 見た目の間隔は本文と同じまま)。
  void _writeFromBlankArea(int lastIdxOnPage, double localDy) {
    // 1 行分の高さ (= 本文の行送り) の目安。
    const lineH = 26.0;
    final add = (localDy / lineH).floor().clamp(0, 60);
    _pushUndo();
    setState(() {
      var at = lastIdxOnPage;
      for (var i = 0; i <= add; i++) {
        at = at + 1;
        _blocks.insert(at, _DocxBlock.paragraph(
            paraStyle: _DocxParaStyle.normal, runs: [_DocxRun('')]));
      }
      _selectedIdx = at;
      _dirty = true;
    });
    // 追加した最後の段落へ入力を移す。
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _beginEditBlock(_selectedIdx ?? 0);
    });
  }

  /// ページを 1 枚足す (= ユーザー要望)。 区切り + 空の段落を入れる。
  void _addDocxPage() {
    _pushUndo();
    setState(() {
      _blocks.add(_DocxBlock.pageBreak());
      _blocks.add(_DocxBlock.paragraph(
            paraStyle: _DocxParaStyle.normal, runs: [_DocxRun('')]));
      _selectedIdx = _blocks.length - 1;
      _dirty = true;
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _beginEditBlock(_selectedIdx ?? 0);
    });
  }

  // ─── 数式の挿入 (= ユーザー要望: ダイアログではなく、 ヘッダーが
  //     数式を入れるモードになる) ────────────────────────────────────
  bool _mathMode = false;
  final TextEditingController _mathCtrl = TextEditingController();

  void _commitMathFromBar() {
    final tex = _mathCtrl.text.trim();
    if (tex.isEmpty) return;
    _pushUndo();
    setState(() {
      final insertAt = (_selectedIdx ?? _blocks.length - 1) + 1;
      _blocks.insert(insertAt, _DocxBlock.math(tex));
      _selectedIdx = insertAt;
      _dirty = true;
      _mathCtrl.clear();
    });
  }

  /// 数式モードのヘッダー (= ユーザー要望: ここで書いて入れる)。
  Widget _buildMathBar(bool dark, Color fg) {
    return Container(
      height: 44,
      padding: const EdgeInsets.symmetric(horizontal: 8),
      color: dark ? const Color(0xFF23233A) : const Color(0xFFE8E8F2),
      child: Row(children: [
        Icon(Icons.functions_rounded, size: 18, color: fg),
        const SizedBox(width: 8),
        // よく使う書き方をすぐ入れられるように。
        for (final (label, snippet) in const [
          ('分数', r'\frac{a}{b}'),
          ('累乗', r'a^{2}'),
          ('添字', r'a_{i}'),
          ('平方根', r'\sqrt{x}'),
          ('総和', r'\sum_{i=1}^{n}'),
        ])
          Padding(
            padding: const EdgeInsets.only(right: 4),
            child: OutlinedButton(
              style: OutlinedButton.styleFrom(
                foregroundColor: fg,
                side: BorderSide(color: fg.withValues(alpha: 0.3)),
                padding: const EdgeInsets.symmetric(horizontal: 8),
                minimumSize: const Size(0, 26),
              ),
              onPressed: () {
                final t = _mathCtrl.text;
                final sel = _mathCtrl.selection;
                final at = sel.isValid ? sel.end : t.length;
                _mathCtrl.text = t.substring(0, at) + snippet + t.substring(at);
                _mathCtrl.selection = TextSelection.collapsed(
                    offset: at + snippet.length);
              },
              child: Text(label, style: const TextStyle(fontSize: 11)),
            ),
          ),
        const SizedBox(width: 6),
        Expanded(
          child: TextField(
            controller: _mathCtrl,
            autofocus: true,
            style: TextStyle(color: fg, fontSize: 13, fontFamily: 'monospace'),
            decoration: InputDecoration(
              isDense: true,
              hintText: r'LaTeX で書く (例: E = mc^2)',
              hintStyle:
                  TextStyle(color: fg.withValues(alpha: 0.4), fontSize: 12),
              border: const OutlineInputBorder(),
              contentPadding:
                  const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
            ),
            onSubmitted: (_) => _commitMathFromBar(),
          ),
        ),
        const SizedBox(width: 6),
        ElevatedButton.icon(
          style: ElevatedButton.styleFrom(
            backgroundColor: const Color(0xFF6C63FF),
            foregroundColor: Colors.white,
            padding: const EdgeInsets.symmetric(horizontal: 12),
            minimumSize: const Size(0, 30),
          ),
          icon: const Icon(Icons.add_rounded, size: 16),
          label: const Text('入れる', style: TextStyle(fontSize: 12)),
          onPressed: _commitMathFromBar,
        ),
        IconButton(
          tooltip: context.read<MindMapProvider>().t('tip.exitMathMode'),
          icon: Icon(Icons.close_rounded, color: fg, size: 18),
          onPressed: () => setState(() => _mathMode = false),
        ),
      ]),
    );
  }

  Future<void> _insertMath() async {
    // ダイアログ本体はテキストエディタと共用 (= ユーザー要望)。
    final tex = await _showLatexInsertDialog(context,
        isDarkMode: widget.isDarkMode);
    if (tex == null || tex.trim().isEmpty) return;
    if (!mounted) return;
    _pushUndo();
    setState(() {
      final insertAt = (_selectedIdx ?? _blocks.length - 1) + 1;
      _blocks.insert(insertAt, _DocxBlock.math(tex.trim()));
      _selectedIdx = insertAt;
      _dirty = true;
    });
  }

  Future<void> _insertTable() async {
    int rows = 3, cols = 3;
    final r = await showDialog<bool>(
      context: context,
      builder: (dctx) {
        return AlertDialog(
          backgroundColor:
              widget.isDarkMode ? const Color(0xFF22222E) : Colors.white,
          title: Row(children: [
            Icon(Icons.grid_on_rounded, color: Color(0xFF6C63FF)),
            SizedBox(width: 8),
            Text(context.read<MindMapProvider>().t('pptx.insertTable')),
          ]),
          // ── 数値で行数・列数を指定できる入力欄 (= ユーザー要望:
          //    スライダーではなく数値で指定して挿入) ──
          content: StatefulBuilder(
            builder: (sctx, setS) {
              Widget numField(String label, int value,
                  void Function(int) onChanged, int maxV) {
                return Row(children: [
                  SizedBox(width: 60, child: Text(label)),
                  SizedBox(
                    width: 90,
                    child: TextFormField(
                      initialValue: '$value',
                      keyboardType: TextInputType.number,
                      textAlign: TextAlign.center,
                      inputFormatters: const [_FullWidthDigitToHalfFormatter()],
                      decoration: const InputDecoration(
                        isDense: true,
                        contentPadding:
                            EdgeInsets.symmetric(horizontal: 8, vertical: 8),
                        border: OutlineInputBorder(),
                      ),
                      onChanged: (v) {
                        final n = int.tryParse(v.trim());
                        if (n != null) {
                          setS(() => onChanged(n.clamp(1, maxV)));
                        }
                      },
                    ),
                  ),
                  const SizedBox(width: 8),
                  Text('(1〜$maxV)',
                      style: const TextStyle(
                          fontSize: 11, color: Colors.grey)),
                ]);
              }

              return SizedBox(
                width: 320,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    numField(
                        context.read<MindMapProvider>().t('docx.rowsColon'),
                        rows,
                        (n) => rows = n,
                        50),
                    const SizedBox(height: 10),
                    numField(
                        context.read<MindMapProvider>().t('docx.colsColon'),
                        cols,
                        (n) => cols = n,
                        20),
                  ],
                ),
              );
            },
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.of(dctx).pop(false),
                child: Text(context.read<MindMapProvider>().t('btn.cancel'))),
            FilledButton(
                onPressed: () => Navigator.of(dctx).pop(true),
                child: Text(context.read<MindMapProvider>().t('pptx.insert'))),
          ],
        );
      },
    );
    if (r != true) return;
    final tableRows = <List<List<_DocxBlock>>>[];
    for (int i = 0; i < rows; i++) {
      final rowCells = <List<_DocxBlock>>[];
      for (int j = 0; j < cols; j++) {
        rowCells.add([
          _DocxBlock.paragraph(
              paraStyle: _DocxParaStyle.normal, runs: [_DocxRun('')])
        ]);
      }
      tableRows.add(rowCells);
    }
    _pushUndo();
    setState(() {
      final insertAt = (_selectedIdx ?? _blocks.length - 1) + 1;
      _blocks.insert(insertAt, _DocxBlock.table(tableRows));
      _selectedIdx = insertAt;
      _dirty = true;
    });
  }

  void _toggleRunFormat(int idx, {bool? bold, bool? italic, bool? underline}) {
    if (idx < 0 || idx >= _blocks.length) return;
    final b = _blocks[idx];
    if (b.kind != _DocxBlockKind.paragraph) return;
    _pushUndo();
    setState(() {
      // 段落内全 Run に対して適用 (簡易: 部分選択は非対応)
      for (final r in b.runs) {
        if (bold != null) r.bold = bold;
        if (italic != null) r.italic = italic;
        if (underline != null) r.underline = underline;
      }
      b.originalXml = null; // 書式変更 → 再生成へ
      _dirty = true;
    });
  }

  /// 段落の文字色を変える (= ユーザー要望)。 null = 既定色に戻す。
  void _setRunColor(int idx, int? rgb) {
    if (idx < 0 || idx >= _blocks.length) return;
    final b = _blocks[idx];
    if (b.kind != _DocxBlockKind.paragraph) return;
    _pushUndo();
    setState(() {
      for (final r in b.runs) {
        r.colorRgb = rgb;
      }
      b.originalXml = null;
      _dirty = true;
    });
  }

  /// 段落のフォントを変える (= ユーザー要望)。 null = 既定フォントに戻す。
  void _setRunFont(int idx, String? family) {
    if (idx < 0 || idx >= _blocks.length) return;
    final b = _blocks[idx];
    if (b.kind != _DocxBlockKind.paragraph) return;
    _pushUndo();
    setState(() {
      for (final r in b.runs) {
        r.fontFamily = family;
      }
      b.originalXml = null;
      _dirty = true;
    });
  }

  /// フォント選択肢 (Windows / 一般的な日本語環境で使える名前)。
  static const List<String> _docxFontChoices = [
    'Yu Gothic UI',
    'Yu Mincho',
    'Meiryo',
    'MS Gothic',
    'MS Mincho',
    'Arial',
    'Times New Roman',
    'Consolas',
  ];

  // ─── 保存 (zip 再パッケージング) ────────────────────────────────
  // ─── ヘッダー / フッター編集 (= ユーザー要望) ─────────────────────
  //
  // 既存の default ヘッダー/フッター part があればそのテキストを読み、
  // 編集後はその part を書き換える。 無ければ word/hnHeader1.xml /
  // word/hnFooter1.xml を新規作成し、 rels + Content_Types + sectPr の
  // 参照も併せて登録する (= Word で開くと全ページの上下余白に表示される)。
  String _headerText = '';
  String _footerText = '';

  /// 揃えと書体 (= ユーザー要望: 右端 / 左端揃えや書体も変えたい)。
  /// 'left' | 'center' | 'right'。
  String _headerAlign = 'center';
  String _footerAlign = 'center';
  String? _headerFont;
  String? _footerFont;
  double _headerSize = 10.5;
  double _footerSize = 10.5;

  /// 今どちらを編集しているか (null = 編集していない)。
  String? _hfEditing; // 'header' | 'footer'
  final TextEditingController _hfCtrl = TextEditingController();
  final FocusNode _hfFocus = FocusNode();

  bool _hfLoaded = false;
  bool _hfEdited = false;
  String? _headerPartName;
  String? _footerPartName;

  String _readArchivePart(String name) {
    final orig = _origArchive;
    if (orig == null) return '';
    for (final f in orig.files) {
      if (f.name == name && f.isFile) {
        return utf8.decode(f.content as List<int>, allowMalformed: true);
      }
    }
    return '';
  }

  void _ensureHeaderFooterLoaded() {
    if (_hfLoaded) return;
    _hfLoaded = true;
    try {
      final doc = _readArchivePart('word/document.xml');
      final rels = _readArchivePart('word/_rels/document.xml.rels');
      String? partFor(String tag) {
        // sectPr の default 参照を優先、 無ければ最初の参照。
        String? rid;
        for (final m
            in RegExp('<w:${tag}Reference[^>]*/>').allMatches(doc)) {
          final s = m.group(0)!;
          final idM = RegExp(r'r:id="([^"]+)"').firstMatch(s);
          if (idM == null) continue;
          rid ??= idM.group(1);
          if (s.contains('w:type="default"')) {
            rid = idM.group(1);
            break;
          }
        }
        if (rid == null) return null;
        final relM =
            RegExp('<Relationship[^>]*Id="$rid"[^>]*>').firstMatch(rels);
        if (relM == null) return null;
        final tM = RegExp(r'Target="([^"]+)"').firstMatch(relM.group(0)!);
        if (tM == null) return null;
        var target = tM.group(1)!;
        target = target.startsWith('/')
            ? target.substring(1)
            : 'word/$target';
        return target;
      }

      String textOf(String xml) {
        final buf = StringBuffer();
        bool first = true;
        for (final p in RegExp(r'<w:p\b[\s\S]*?</w:p>').allMatches(xml)) {
          if (!first) buf.write('\n');
          first = false;
          for (final t in RegExp(r'<w:t[^>]*>([^<]*)</w:t>')
              .allMatches(p.group(0)!)) {
            buf.write(_unescapeXml(t.group(1) ?? ''));
          }
        }
        return buf.toString().trim();
      }

      _headerPartName = partFor('header');
      _footerPartName = partFor('footer');
      if (_headerPartName != null) {
        _headerText = textOf(_readArchivePart(_headerPartName!));
      }
      if (_footerPartName != null) {
        _footerText = textOf(_readArchivePart(_footerPartName!));
      }
    } catch (_) {}
  }

  Future<void> _showHeaderFooterDialog() async {
    _ensureHeaderFooterLoaded();
    final hCtrl = TextEditingController(text: _headerText);
    final fCtrl = TextEditingController(text: _footerText);
    final ok = await showDialog<bool>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF2A2A3E),
        title: const Text('ヘッダーとフッター',
            style: TextStyle(color: Colors.white, fontSize: 15)),
        content: SizedBox(
          width: 380,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              TextField(
                controller: hCtrl,
                minLines: 1,
                maxLines: 3,
                style: const TextStyle(color: Colors.white, fontSize: 13),
                decoration: const InputDecoration(
                  labelText: 'ヘッダー (ページ上部)',
                  labelStyle:
                      TextStyle(color: Colors.white60, fontSize: 12),
                  hintText: '例: 社外秘 / 資料タイトル',
                  hintStyle:
                      TextStyle(color: Colors.white24, fontSize: 12),
                ),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: fCtrl,
                minLines: 1,
                maxLines: 3,
                style: const TextStyle(color: Colors.white, fontSize: 13),
                decoration: const InputDecoration(
                  labelText: 'フッター (ページ下部)',
                  labelStyle:
                      TextStyle(color: Colors.white60, fontSize: 12),
                  hintText: '例: © 2026 会社名',
                  hintStyle:
                      TextStyle(color: Colors.white24, fontSize: 12),
                ),
              ),
              const SizedBox(height: 10),
              const Text(
                '保存すると全ページの上下余白に表示されます (Word と同じ)。\n'
                'このエディタはページ分割表示ではないため、 本文には出ません。',
                style: TextStyle(color: Colors.white38, fontSize: 11),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dctx, false),
            child:
                const Text('キャンセル', style: TextStyle(color: Colors.white54)),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dctx, true),
            child: const Text('設定'),
          ),
        ],
      ),
    );
    if (ok == true && mounted) {
      setState(() {
        _headerText = hCtrl.text.trim();
        _footerText = fCtrl.text.trim();
        _hfEdited = true;
        _dirty = true;
      });
      _showSnack('✓ ヘッダー / フッターを設定しました (保存で反映)');
    }
  }

  /// 保存時に書き込むヘッダー / フッター part (path → XML)。
  /// 新規作成が必要な場合は `_headerPartName` / `_footerPartName` を
  /// hn 名に確定させる (= sectPr / rels / Content_Types 側が参照)。
  Map<String, String> _buildHeaderFooterParts() {
    if (!_hfEdited) return const {};
    _ensureHeaderFooterLoaded();
    String hfXml(String rootTag, String text,
        {String align = 'center', String? font, double size = 10.5}) {
      final buf = StringBuffer();
      final jc = align == 'left'
          ? ''
          : '<w:jc w:val="${align == 'right' ? 'right' : 'center'}"/>';
      final rFonts = (font == null || font.isEmpty)
          ? ''
          : '<w:rFonts w:ascii="$font" w:hAnsi="$font" w:eastAsia="$font"/>';
      final sz = '<w:sz w:val="${(size * 2).round()}"/>';
      for (final line in (text.isEmpty ? [''] : text.split('\n'))) {
        buf.write('<w:p>'
            '${jc.isEmpty ? '' : '<w:pPr>$jc</w:pPr>'}'
            '<w:r><w:rPr>$rFonts$sz</w:rPr>'
            '<w:t xml:space="preserve">${_escapeXml(line)}</w:t>'
            '</w:r></w:p>');
      }
      return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<w:$rootTag '
          'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '
          'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
          '$buf</w:$rootTag>';
    }

    final out = <String, String>{};
    if (_headerPartName == null && _headerText.isNotEmpty) {
      _headerPartName = 'word/hnHeader1.xml';
    }
    if (_headerPartName != null) {
      out[_headerPartName!] = hfXml('hdr', _headerText,
          align: _headerAlign, font: _headerFont, size: _headerSize);
    }
    if (_footerPartName == null && _footerText.isNotEmpty) {
      _footerPartName = 'word/hnFooter1.xml';
    }
    if (_footerPartName != null) {
      out[_footerPartName!] = hfXml('ftr', _footerText,
          align: _footerAlign, font: _footerFont, size: _footerSize);
    }
    return out;
  }

  /// アプリ作成のヘッダー / フッター参照を sectPr へ差し込む。
  /// (元からある part は sectPr が既に参照しているので何もしない)。
  String _injectHfRefsIntoSectPr(String sectPr) {
    var refs = '';
    if (_headerPartName == 'word/hnHeader1.xml' &&
        !sectPr.contains('r:id="rIdHNHDR"')) {
      refs += '<w:headerReference w:type="default" r:id="rIdHNHDR"/>';
    }
    if (_footerPartName == 'word/hnFooter1.xml' &&
        !sectPr.contains('r:id="rIdHNFTR"')) {
      refs += '<w:footerReference w:type="default" r:id="rIdHNFTR"/>';
    }
    if (refs.isEmpty) return sectPr;
    if (RegExp(r'<w:sectPr\s*/>').hasMatch(sectPr)) {
      return '<w:sectPr>$refs</w:sectPr>';
    }
    // headerReference / footerReference は sectPr の先頭要素なので
    // 開きタグ直後に挿入する。
    return sectPr.replaceFirstMapped(
        RegExp(r'<w:sectPr\b[^>]*>'), (m) => '${m.group(0)}$refs');
  }

  Future<void> _save() async {
    if (!_docInitialized) return;
    try {
      _commitEdit();
      _commitTableEdit();
      final orig = _origArchive;
      if (orig == null) {
        _showSnack('元アーカイブが見つかりません');
        return;
      }
      // ── ヘッダー / フッター part を先に確定 (= sectPr / rels /
      //    Content_Types が part 名を参照するため)。 ──
      final hfParts = _buildHeaderFooterParts();
      // 新しい document.xml を生成
      final newDocXml = _buildDocumentXml();
      // 新しい rels を生成 (画像追加分も反映)
      final newRelsXml = _buildRelsXml();
      // 新しい Content_Types.xml (画像形式が追加されたら拡張)
      final newCtXml = _buildContentTypesXml();
      // archive を組み立て直す
      final newArchive = Archive();
      final overwritten = <String>{
        'word/document.xml',
        'word/_rels/document.xml.rels',
        '[Content_Types].xml',
        ...hfParts.keys,
      };
      // 既存ファイル (上書き対象以外) をコピー
      for (final f in orig.files) {
        if (f.name.startsWith('word/media/')) {
          continue; // メディアは下で書き直し
        }
        if (overwritten.contains(f.name)) continue;
        newArchive.addFile(ArchiveFile(f.name, f.size, f.content as List<int>));
      }
      // メディア
      _media.forEach((name, bytes) {
        final path = 'word/media/$name';
        newArchive.addFile(ArchiveFile(path, bytes.length, bytes));
      });
      // 上書き対象
      final docBytes = utf8.encode(newDocXml);
      newArchive
          .addFile(ArchiveFile('word/document.xml', docBytes.length, docBytes));
      final relsBytes = utf8.encode(newRelsXml);
      newArchive.addFile(ArchiveFile(
          'word/_rels/document.xml.rels', relsBytes.length, relsBytes));
      final ctBytes = utf8.encode(newCtXml);
      newArchive
          .addFile(ArchiveFile('[Content_Types].xml', ctBytes.length, ctBytes));
      // ヘッダー / フッター part (= ユーザー要望: 編集できるように)
      hfParts.forEach((path, xmlStr) {
        final b = utf8.encode(xmlStr);
        newArchive.addFile(ArchiveFile(path, b.length, b));
      });
      // 書き出し
      final zipBytes = ZipEncoder().encode(newArchive);
      if (zipBytes == null) throw Exception('zip encode failed');
      await File(_currentFilePath).writeAsBytes(zipBytes);
      if (!mounted) return;
      setState(() => _dirty = false);
      widget.onSaved?.call();
      _showSnack('保存しました: $_currentFileName');
    } catch (e, st) {
      debugPrint('DocxEditor save error: $e\n$st');
      _showSnack('保存に失敗: $e');
    }
  }

  /// 内部ブロックリストから word/document.xml の全体を生成
  String _buildDocumentXml() {
    final body = StringBuffer();
    for (int i = 0; i < _blocks.length; i++) {
      final b = _blocks[i];
      body.write(_blockToXml(b, paraId: 'p$i'));
    }
    // 末尾の sectPr (= ページサイズ等) は元ファイルから引き継ぐ。
    // アプリ作成のヘッダー / フッター参照があれば差し込む (= ユーザー要望)。
    final sectPr = _injectHfRefsIntoSectPr(_extractSectPr());
    body.write(sectPr);

    return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<w:document '
        'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
        'xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" '
        'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
        'xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture" '
        'xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math">'
        '<w:body>${body.toString()}</w:body></w:document>';
  }

  /// 元ファイルの末尾 <w:sectPr>...</w:sectPr> を抽出 (= ページサイズ等を保持)
  String _extractSectPr() {
    final orig = _origArchive;
    if (orig == null) return '<w:sectPr/>';
    for (final f in orig.files) {
      if (f.name == 'word/document.xml' && f.isFile) {
        final xml = utf8.decode(f.content as List<int>, allowMalformed: true);
        final m = RegExp(r'<w:sectPr\b[\s\S]*?</w:sectPr>').firstMatch(xml);
        if (m != null) return m.group(0)!;
        final m2 = RegExp(r'<w:sectPr\s*/>').firstMatch(xml);
        if (m2 != null) return m2.group(0)!;
      }
    }
    return '<w:sectPr/>';
  }

  String _blockToXml(_DocxBlock b, {required String paraId}) {
    // ── 未編集ブロックは元 XML をそのまま書き戻す ──
    // (= ユーザー要望 2026-07: ダウンロードすると元の docx とレイアウトが
    //  異なる。 パースで拾いきれない行間/インデント/スタイル参照/画像
    //  アンカー等を失わないため、 編集していないブロックは再生成しない)。
    final orig = b.originalXml;
    if (orig != null && orig.isNotEmpty) return orig;
    switch (b.kind) {
      case _DocxBlockKind.paragraph:
        return _paragraphXml(b);
      case _DocxBlockKind.table:
        return _tableXml(b);
      case _DocxBlockKind.image:
        return _imageXml(b, paraId);
      case _DocxBlockKind.math:
        return _mathXml(b);
      case _DocxBlockKind.pageBreak:
        return '<w:p><w:r><w:br w:type="page"/></w:r></w:p>';
    }
  }

  String _paragraphXml(_DocxBlock b) {
    final pPr = StringBuffer();
    if (b.paraStyle != _DocxParaStyle.normal) {
      pPr.write('<w:pStyle w:val="${b.paraStyle.pStyleName}"/>');
    }
    // 水平揃え (left は出力しない = OOXML のデフォルト)
    if (b.align != _DocxAlign.left) {
      pPr.write('<w:jc w:val="${b.align.jcValue}"/>');
    }
    // 段落単位のフォントサイズ (pt → half-pt に変換)
    if (b.fontSize != null && b.fontSize! > 0) {
      final halfPt = (b.fontSize! * 2).round();
      pPr.write('<w:rPr><w:sz w:val="$halfPt"/></w:rPr>');
    }
    final runs = StringBuffer();
    for (final r in b.runs) {
      final text = r.text;
      if (text.isEmpty) continue;
      // 改行を <w:br/> に分解
      final parts = text.split('\n');
      for (int j = 0; j < parts.length; j++) {
        final part = parts[j];
        final rPr = StringBuffer();
        // フォント名 (= ユーザー要望: フォント変更を保存にも反映)。
        // rPr の並びは rFonts を先頭にする (OOXML のスキーマ順)。
        if ((r.fontFamily ?? '').isNotEmpty) {
          final ff = _escapeXml(r.fontFamily!);
          rPr.write('<w:rFonts w:ascii="$ff" w:eastAsia="$ff" '
              'w:hAnsi="$ff" w:cs="$ff"/>');
        }
        if (r.bold) rPr.write('<w:b/>');
        if (r.italic) rPr.write('<w:i/>');
        if (r.underline) rPr.write('<w:u w:val="single"/>');
        // 文字色 (= 従来は表示のみで保存されず消えていた。 保存にも反映)。
        if (r.colorRgb != null) {
          final hex = (r.colorRgb! & 0xFFFFFF)
              .toRadixString(16)
              .padLeft(6, '0')
              .toUpperCase();
          rPr.write('<w:color w:val="$hex"/>');
        }
        // 蛍光ペン (背景色) (= ユーザー要望)。
        if ((r.highlight ?? '').isNotEmpty) {
          rPr.write('<w:highlight w:val="${r.highlight}"/>');
        }
        // 段落の fontSize を run にも繁殖
        if (b.fontSize != null && b.fontSize! > 0) {
          final halfPt = (b.fontSize! * 2).round();
          rPr.write('<w:sz w:val="$halfPt"/>');
        }
        runs.write('<w:r>');
        if (rPr.isNotEmpty) runs.write('<w:rPr>$rPr</w:rPr>');
        // タブ
        final tabSplit = part.split('\t');
        for (int k = 0; k < tabSplit.length; k++) {
          if (tabSplit[k].isNotEmpty) {
            runs.write('<w:t xml:space="preserve">'
                '${_escapeXml(tabSplit[k])}</w:t>');
          }
          if (k < tabSplit.length - 1) {
            runs.write('<w:tab/>');
          }
        }
        runs.write('</w:r>');
        if (j < parts.length - 1) {
          runs.write('<w:r><w:br/></w:r>');
        }
      }
    }
    final pPrXml = pPr.isEmpty ? '' : '<w:pPr>$pPr</w:pPr>';
    return '<w:p>$pPrXml$runs</w:p>';
  }

  String _docxHex(int? rgb, {String fallback = 'auto'}) {
    if (rgb == null) return fallback;
    return (rgb & 0xFFFFFF).toRadixString(16).padLeft(6, '0').toUpperCase();
  }

  String _docxBorderXml(String edge, int sz, String color) =>
      '<w:$edge w:val="single" w:sz="$sz" w:space="0" w:color="$color"/>';

  String _tableXml(_DocxBlock b) {
    final sb = StringBuffer();
    final style = b.tableStyle;
    final borderSz = style?.borderSz ?? 4;
    final borderColor = _docxHex(style?.borderRgb);
    sb.write('<w:tbl>');
    sb.write('<w:tblPr><w:tblW w:w="0" w:type="auto"/>');
    sb.write('<w:tblBorders>');
    for (final edge in [
      'top',
      'left',
      'bottom',
      'right',
      'insideH',
      'insideV'
    ]) {
      sb.write(_docxBorderXml(edge, borderSz, borderColor));
    }
    sb.write('</w:tblBorders>');
    if (style?.fillRgb != null) {
      sb.write('<w:shd w:val="clear" w:color="auto" '
          'w:fill="${_docxHex(style!.fillRgb, fallback: "FFFFFF")}"/>');
    }
    sb.write('</w:tblPr>');
    final cols = b.tableRows.isNotEmpty ? b.tableRows.first.length : 0;
    final colW = cols > 0 ? (9000 / cols).round() : 9000;
    sb.write('<w:tblGrid>');
    for (int i = 0; i < cols; i++) {
      sb.write('<w:gridCol w:w="$colW"/>');
    }
    sb.write('</w:tblGrid>');
    for (int r = 0; r < b.tableRows.length; r++) {
      final row = b.tableRows[r];
      sb.write('<w:tr>');
      for (int c = 0; c < row.length; c++) {
        final cell = row[c];
        final cellStyle =
            r < b.tableCellStyles.length && c < b.tableCellStyles[r].length
                ? b.tableCellStyles[r][c]
                : null;
        final tcPr = StringBuffer();
        tcPr.write('<w:tcW w:w="$colW" w:type="dxa"/>');
        if (cellStyle?.fillRgb != null) {
          tcPr.write('<w:shd w:val="clear" w:color="auto" '
              'w:fill="${_docxHex(cellStyle!.fillRgb, fallback: "FFFFFF")}"/>');
        }
        if (cellStyle?.borderRgb != null || cellStyle?.borderSz != null) {
          final sz = cellStyle?.borderSz ?? borderSz;
          final color = _docxHex(cellStyle?.borderRgb ?? style?.borderRgb);
          tcPr.write('<w:tcBorders>');
          for (final edge in ['top', 'left', 'bottom', 'right']) {
            tcPr.write(_docxBorderXml(edge, sz, color));
          }
          tcPr.write('</w:tcBorders>');
        }
        sb.write('<w:tc><w:tcPr>$tcPr</w:tcPr>');
        for (final cb in cell) {
          sb.write(_blockToXml(cb, paraId: 'cell'));
        }
        sb.write('</w:tc>');
      }
      sb.write('</w:tr>');
    }
    sb.write('</w:tbl>');
    return sb.toString();
  }

  String _imageXml(_DocxBlock b, String paraId) {
    final mediaName = b.imageName;
    if (mediaName == null) return '<w:p/>';
    final rId = _rIdForMedia(mediaName);
    final cx = b.imageWidthEmu ?? 3600000;
    final cy = b.imageHeightEmu ?? 2700000;
    return '<w:p><w:r><w:drawing>'
        '<wp:inline distT="0" distB="0" distL="0" distR="0">'
        '<wp:extent cx="$cx" cy="$cy"/>'
        '<wp:effectExtent l="0" t="0" r="0" b="0"/>'
        '<wp:docPr id="${paraId.hashCode.abs() % 10000}" '
        'name="Picture $paraId"/>'
        '<wp:cNvGraphicFramePr/>'
        '<a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main">'
        '<a:graphicData '
        'uri="http://schemas.openxmlformats.org/drawingml/2006/picture">'
        '<pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture">'
        '<pic:nvPicPr>'
        '<pic:cNvPr id="0" name="$mediaName"/>'
        '<pic:cNvPicPr/>'
        '</pic:nvPicPr>'
        '<pic:blipFill>'
        '<a:blip r:embed="$rId"/>'
        '<a:stretch><a:fillRect/></a:stretch>'
        '</pic:blipFill>'
        '<pic:spPr>'
        '<a:xfrm><a:off x="0" y="0"/><a:ext cx="$cx" cy="$cy"/></a:xfrm>'
        '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom>'
        '</pic:spPr>'
        '</pic:pic>'
        '</a:graphicData>'
        '</a:graphic>'
        '</wp:inline>'
        '</w:drawing></w:r></w:p>';
  }

  String _mathXml(_DocxBlock b) {
    final tex = b.mathTex ?? '';
    // OMML への変換は範囲が広いので、 シンプルに <m:oMath> + <m:t> に
    // 入れる (Word では LaTeX 風テキストとして表示される)。
    // また、 編集モードで保持できるように、 元の LaTeX をテキストとして
    // 1 段落に書く。 これで Word でも読み返せる。
    return '<w:p><w:pPr><w:pStyle w:val="Quote"/></w:pPr>'
        '<m:oMathPara><m:oMath>'
        '<m:r><m:t>${_escapeXml(tex)}</m:t></m:r>'
        '</m:oMath></m:oMathPara>'
        '</w:p>';
  }

  /// メディア名から rId を生成 (= 'mokumoku_rId_<hash>')
  /// 元ファイルの document.xml.rels にある media/ の rId マップ
  /// (メディア名 → rId)。 未編集段落の元 XML が参照する r:embed を
  /// 壊さないため、 元の rId を最優先で使い回す (= ユーザー要望 2026-07:
  /// ダウンロードで画像/レイアウトが崩れる問題への対応)。
  Map<String, String>? _origMediaRelIdCache;
  Map<String, String> get _origMediaRelIds {
    final cached = _origMediaRelIdCache;
    if (cached != null) return cached;
    final map = <String, String>{};
    final orig = _origArchive;
    if (orig != null) {
      for (final f in orig.files) {
        if (f.name == 'word/_rels/document.xml.rels' && f.isFile) {
          final xml = utf8.decode(f.content as List<int>, allowMalformed: true);
          for (final m
              in RegExp(r'<Relationship\s+[^>]*?/?>').allMatches(xml)) {
            final rel = m.group(0)!;
            final idM = RegExp(r'Id="([^"]+)"').firstMatch(rel);
            final tM = RegExp(r'Target="media/([^"]+)"').firstMatch(rel);
            if (idM != null && tM != null) {
              map[tM.group(1)!] = idM.group(1)!;
            }
          }
          break;
        }
      }
    }
    return _origMediaRelIdCache = map;
  }

  String _rIdForMedia(String mediaName) {
    // 元ファイル由来のメディアは元の rId を使う (= 元 XML の r:embed と一致)。
    final origId = _origMediaRelIds[mediaName];
    if (origId != null) return origId;
    final h = mediaName.hashCode.abs() % 1000000;
    return 'rIdMM$h';
  }

  String _buildRelsXml() {
    final sb = StringBuffer();
    sb.write('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships '
        'xmlns="http://schemas.openxmlformats.org/package/2006/relationships">');
    // ── 元ファイルの relationships を **メディアも含めて** 引き継ぐ ──
    // 旧仕様は media/ の rel を破棄してハッシュ rId で再生成していたが、
    // 未編集段落の元 XML (r:embed="rIdN") が壊れるため、 元の rel を
    // そのまま保持する (ヘッダー/フッター/スタイル等の rel も保持)。
    final orig = _origArchive;
    final usedIds = <String>{};
    final relatedMediaTargets = <String>{};
    if (orig != null) {
      for (final f in orig.files) {
        if (f.name == 'word/_rels/document.xml.rels' && f.isFile) {
          final xml = utf8.decode(f.content as List<int>, allowMalformed: true);
          // 注: 旧正規表現 `[^/>]*` は Type URL に含まれる '/' で必ず
          // マッチ失敗し、 元の relationship (styles/numbering/header/
          // footer/hyperlink 等) が 1 件も引き継がれていなかった。 これが
          // 「ダウンロードするとヘッダー/フッターが消える・レイアウトが
          // 崩れる」 主因 (= ユーザー要望 2026-07 で修正)。
          final relRe = RegExp(r'<Relationship\s[^>]*>');
          for (final m in relRe.allMatches(xml)) {
            final rel = m.group(0)!;
            final idM = RegExp(r'Id="([^"]+)"').firstMatch(rel);
            if (idM != null) usedIds.add(idM.group(1)!);
            final tM = RegExp(r'Target="media/([^"]+)"').firstMatch(rel);
            if (tM != null) relatedMediaTargets.add(tM.group(1)!);
            sb.write(rel);
          }
          break;
        }
      }
    }
    // 新規追加メディアの relationships を生成 (元から rel があるものは除く)
    _media.forEach((name, _) {
      if (relatedMediaTargets.contains(name)) return;
      final rId = _rIdForMedia(name);
      if (usedIds.contains(rId)) return; // 既にあれば追加しない
      usedIds.add(rId);
      sb.write('<Relationship Id="$rId" '
          'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" '
          'Target="media/$name"/>');
    });
    // ── アプリ作成のヘッダー / フッター (= ユーザー要望) ──
    if (_headerPartName == 'word/hnHeader1.xml' &&
        !usedIds.contains('rIdHNHDR')) {
      sb.write('<Relationship Id="rIdHNHDR" '
          'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/header" '
          'Target="hnHeader1.xml"/>');
    }
    if (_footerPartName == 'word/hnFooter1.xml' &&
        !usedIds.contains('rIdHNFTR')) {
      sb.write('<Relationship Id="rIdHNFTR" '
          'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" '
          'Target="hnFooter1.xml"/>');
    }
    sb.write('</Relationships>');
    return sb.toString();
  }

  String _buildContentTypesXml() {
    final orig = _origArchive;
    if (orig != null) {
      for (final f in orig.files) {
        if (f.name == '[Content_Types].xml' && f.isFile) {
          var xml = utf8.decode(f.content as List<int>, allowMalformed: true);
          // 画像 ContentType がない拡張子があれば追加
          final extensions = _media.keys
              .map((n) =>
                  n.contains('.') ? n.substring(n.lastIndexOf('.') + 1) : '')
              .where((e) => e.isNotEmpty)
              .toSet();
          for (final ext in extensions) {
            if (!xml.contains('Extension="$ext"')) {
              final mime = _imageMime(ext);
              // 旧: '<Types ' の前に挿入していたため Types 要素の外に
              // Default が出て壊れた XML になっていた。 </Types> の直前へ。
              xml = xml.replaceFirst('</Types>',
                  '<Default Extension="$ext" ContentType="$mime"/></Types>');
            }
          }
          // ── アプリ作成のヘッダー / フッター (= ユーザー要望) ──
          if (_headerPartName == 'word/hnHeader1.xml' &&
              !xml.contains('/word/hnHeader1.xml')) {
            xml = xml.replaceFirst(
                '</Types>',
                '<Override PartName="/word/hnHeader1.xml" '
                'ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml"/>'
                '</Types>');
          }
          if (_footerPartName == 'word/hnFooter1.xml' &&
              !xml.contains('/word/hnFooter1.xml')) {
            xml = xml.replaceFirst(
                '</Types>',
                '<Override PartName="/word/hnFooter1.xml" '
                'ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml"/>'
                '</Types>');
          }
          return xml;
        }
      }
    }
    return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        '<Default Extension="rels" '
        'ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
        '<Default Extension="xml" ContentType="application/xml"/>'
        '<Default Extension="png" ContentType="image/png"/>'
        '<Default Extension="jpg" ContentType="image/jpeg"/>'
        '<Default Extension="jpeg" ContentType="image/jpeg"/>'
        '<Override PartName="/word/document.xml" '
        'ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
        '</Types>';
  }

  String _imageMime(String ext) {
    switch (ext.toLowerCase()) {
      case 'png':
        return 'image/png';
      case 'jpg':
      case 'jpeg':
        return 'image/jpeg';
      case 'gif':
        return 'image/gif';
      case 'bmp':
        return 'image/bmp';
      case 'webp':
        return 'image/webp';
      case 'svg':
        return 'image/svg+xml';
      default:
        return 'application/octet-stream';
    }
  }

  // ─── ファイル名変更 / 確認ダイアログ ─────────────────────────────
  Future<bool> _confirmDiscard({BuildContext? anchor}) async {
    if (!_dirty) return true;
    // × ボタンの近く + フローティング窓の上に出す (= ユーザー要望)。
    final r = await _showUnsavedConfirmNear(anchor ?? context);
    if (r == 'save') {
      await _save();
      return true;
    }
    return r == 'discard';
  }

  Future<void> _showRenameDialog() async {
    final ctrl = TextEditingController(text: _currentFileName);
    final newName = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor:
            widget.isDarkMode ? const Color(0xFF22222E) : Colors.white,
        title: Row(children: [
          const Icon(Icons.drive_file_rename_outline_rounded,
              color: Color(0xFF2196F3)),
          const SizedBox(width: 8),
          Text(context.read<MindMapProvider>().t('doc.renameFile')),
        ]),
        content: SizedBox(
          width: 380,
          child: TextField(
            controller: ctrl,
            autofocus: true,
            decoration: InputDecoration(
              hintText: context.read<MindMapProvider>().t('doc.fileName'),
              border: OutlineInputBorder(),
            ),
            onSubmitted: (_) => Navigator.of(dctx).pop(ctrl.text),
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
              child: Text(context.read<MindMapProvider>().t('btn.cancel'))),
          FilledButton(
              onPressed: () => Navigator.of(dctx).pop(ctrl.text),
              child: Text(context.read<MindMapProvider>().t('btn.change'))),
        ],
      ),
    );
    if (newName == null) return;
    final input = newName.trim();
    if (input.isEmpty || input == _currentFileName) return;
    if (input.contains('/') || input.contains('\\')) {
      _showSnack('ファイル名にパス区切り文字 ( / \\ ) は使えません');
      return;
    }
    final origExt = _currentFileName.contains('.')
        ? _currentFileName.substring(_currentFileName.lastIndexOf('.'))
        : '';
    String fixed = input;
    if (origExt.isNotEmpty &&
        !fixed.toLowerCase().endsWith(origExt.toLowerCase())) {
      if (fixed.contains('.')) {
        fixed = '${fixed.substring(0, fixed.lastIndexOf('.'))}$origExt';
      } else {
        fixed = '$fixed$origExt';
      }
    }
    try {
      if (_dirty) await _save();
      final oldFile = File(_currentFilePath);
      if (!await oldFile.exists()) {
        _showSnack('元ファイルが見つかりません');
        return;
      }
      final sep = _currentFilePath.contains('\\') ? '\\' : '/';
      final dirEnd = _currentFilePath.lastIndexOf(sep);
      final dir = dirEnd >= 0 ? _currentFilePath.substring(0, dirEnd) : '';
      final newPath = dir.isEmpty ? fixed : '$dir$sep$fixed';
      if (await File(newPath).exists() && newPath != _currentFilePath) {
        _showSnack('同名のファイルが既に存在します');
        return;
      }
      final renamed = await oldFile.rename(newPath);
      setState(() {
        _currentFilePath = renamed.path;
        _currentFileName = fixed;
      });
      widget.onRenamed?.call(renamed.path, fixed);
      _showSnack('ファイル名を変更しました: $fixed');
    } catch (e) {
      _showSnack('ファイル名変更に失敗: $e');
    }
  }

  void _showSnack(String msg) {
    if (!mounted) return;
    final overlay = Overlay.maybeOf(context, rootOverlay: true);
    if (overlay == null) {
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(SnackBar(
        content: Text(msg),
        duration: const Duration(seconds: 4),
      ));
      return;
    }

    // 全画面 Dialog の背後へ通知が隠れないよう、ビューアより前面に出す。
    _noticeEntry?.remove();
    late final OverlayEntry entry;
    entry = OverlayEntry(
      builder: (_) => Positioned(
        left: 16,
        right: 16,
        bottom: 24,
        child: SafeArea(
          child: IgnorePointer(
            child: Align(
              alignment: Alignment.bottomCenter,
              child: Semantics(
                container: true,
                liveRegion: true,
                child: Material(
                  color: Colors.transparent,
                  child: Container(
                    constraints: const BoxConstraints(maxWidth: 720),
                    padding: const EdgeInsets.symmetric(
                        horizontal: 18, vertical: 12),
                    decoration: BoxDecoration(
                      color: const Color(0xFF2A2A3E),
                      borderRadius: BorderRadius.circular(10),
                      boxShadow: const [
                        BoxShadow(
                            color: Colors.black38,
                            blurRadius: 14,
                            offset: Offset(0, 5)),
                      ],
                    ),
                    child: Text(msg,
                        textAlign: TextAlign.center,
                        style: const TextStyle(color: Colors.white)),
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
    _noticeEntry = entry;
    overlay.insert(entry);
    Future<void>.delayed(const Duration(seconds: 4), () {
      if (_noticeEntry == entry) {
        entry.remove();
        _noticeEntry = null;
      }
    });
  }

  /// 現在の内容を .docx として別名で保存 (ダウンロード)。
  /// 未保存の編集も含めて出力する。
  Future<void> _downloadCopy() async {
    try {
      _commitEdit();
      _commitTableEdit();
      final orig = _origArchive;
      if (orig == null) {
        _showSnack('元アーカイブが見つかりません');
        return;
      }
      final newDocXml = _buildDocumentXml();
      final newRelsXml = _buildRelsXml();
      final newCtXml = _buildContentTypesXml();
      final newArchive = Archive();
      final overwritten = <String>{
        'word/document.xml',
        'word/_rels/document.xml.rels',
        '[Content_Types].xml',
      };
      for (final f in orig.files) {
        if (f.name.startsWith('word/media/')) continue;
        if (overwritten.contains(f.name)) continue;
        newArchive.addFile(ArchiveFile(f.name, f.size, f.content as List<int>));
      }
      _media.forEach((name, bytes) {
        newArchive
            .addFile(ArchiveFile('word/media/$name', bytes.length, bytes));
      });
      final docBytes = utf8.encode(newDocXml);
      newArchive
          .addFile(ArchiveFile('word/document.xml', docBytes.length, docBytes));
      final relsBytes = utf8.encode(newRelsXml);
      newArchive.addFile(ArchiveFile(
          'word/_rels/document.xml.rels', relsBytes.length, relsBytes));
      final ctBytes = utf8.encode(newCtXml);
      newArchive
          .addFile(ArchiveFile('[Content_Types].xml', ctBytes.length, ctBytes));
      final zipBytes = ZipEncoder().encode(newArchive);
      if (zipBytes == null) throw Exception('zip encode failed');

      String? outPath;
      final defaultName = _currentFileName.toLowerCase().endsWith('.docx')
          ? _currentFileName
          : '$_currentFileName.docx';
      if (Platform.isWindows || Platform.isMacOS || Platform.isLinux) {
        outPath = await FilePicker.platform.saveFile(
          dialogTitle: context.read<MindMapProvider>().t('save.docx'),
          fileName: defaultName,
          type: FileType.custom,
          allowedExtensions: ['docx'],
        );
        if (outPath == null) return;
        if (!outPath.toLowerCase().endsWith('.docx')) {
          outPath = '$outPath.docx';
        }
        await File(outPath).writeAsBytes(zipBytes, flush: true);
      } else {
        final dir = await getApplicationDocumentsDirectory();
        final exportDir = Directory('${dir.path}/exports');
        if (!await exportDir.exists()) {
          await exportDir.create(recursive: true);
        }
        outPath = '${exportDir.path}/$defaultName';
        await File(outPath).writeAsBytes(zipBytes, flush: true);
        await OpenFilex.open(outPath);
      }
      _showSnack('ダウンロード完了: $outPath');
    } catch (e, st) {
      debugPrint('DocxEditor download error: $e\n$st');
      _showSnack('ダウンロードに失敗: $e');
    }
  }

  /// 現在の内容を PDF として保存。
  /// 日本語フォントが未配置なら警告を出す (英字は出るが日本語は □ になる)。
  Future<void> _downloadAsPdf() async {
    final provider = context.read<MindMapProvider>();
    try {
      _commitEdit();
      _commitTableEdit();
      // ── 日本語フォント事前チェック ──
      // 未配置なら警告ダイアログを出して、 ユーザーが続行 OK しなければ中止。
      final ok = await _PdfExporter.ensureJapaneseFontOrConfirm(context);
      if (!ok) return;
      _showSnack(provider.t('video.exporting'));
      final bytes = await _PdfExporter.exportDocx(_blocks, _media);
      String? outPath;
      final base = _currentFileName.toLowerCase().endsWith('.docx')
          ? _currentFileName.substring(0, _currentFileName.length - 5)
          : _currentFileName;
      final defaultName = '$base.pdf';
      if (Platform.isWindows || Platform.isMacOS || Platform.isLinux) {
        outPath = await FilePicker.platform.saveFile(
          dialogTitle: provider.t('pptx.saveAsPdf'),
          fileName: defaultName,
          type: FileType.custom,
          allowedExtensions: ['pdf'],
        );
        if (outPath == null) return;
        if (!outPath.toLowerCase().endsWith('.pdf')) {
          outPath = '$outPath.pdf';
        }
        await File(outPath).writeAsBytes(bytes, flush: true);
      } else {
        final dir = await getApplicationDocumentsDirectory();
        final exportDir = Directory('${dir.path}/exports');
        if (!await exportDir.exists()) {
          await exportDir.create(recursive: true);
        }
        outPath = '${exportDir.path}/$defaultName';
        await File(outPath).writeAsBytes(bytes, flush: true);
        await OpenFilex.open(outPath);
      }
      _showSnack(provider
          .t('export.success')
          .replaceFirst('{path}', outPath ?? defaultName));
    } catch (e, st) {
      debugPrint('DocxEditor PDF export error: $e\n$st');
      _showSnack(provider.t('doc.saveFailed').replaceFirst('{err}', '$e'));
    }
  }

  // ─── ビルド ─────────────────────────────────────────────────────
  @override
  Widget build(BuildContext context) {
    final dark = widget.isDarkMode;
    final fg = dark ? Colors.white : const Color(0xFF1A1A24);
    Widget body;
    if (_loading) {
      body = const Center(child: CircularProgressIndicator());
    } else if (_loadError != null) {
      body = Center(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(Icons.error_outline_rounded,
                  color: Colors.redAccent, size: 48),
              const SizedBox(height: 12),
              Text(
                  context
                      .read<MindMapProvider>()
                      .t('doc.loadError')
                      .replaceFirst('{err}', '$_loadError'),
                  style: TextStyle(color: fg),
                  textAlign: TextAlign.center),
              const SizedBox(height: 16),
              FilledButton.icon(
                onPressed: () async {
                  if (_currentFilePath.isEmpty) {
                    ScaffoldMessenger.maybeOf(context)?.showSnackBar(
                      SnackBar(
                        backgroundColor: const Color(0xFFE57373),
                        content: Text(context
                            .read<MindMapProvider>()
                            .t('pptx.notSavedYet')),
                      ),
                    );
                    return;
                  }
                  try {
                    final r = await OpenFilex.open(_currentFilePath);
                    if (r.type != ResultType.done && mounted) {
                      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
                        SnackBar(
                          backgroundColor: const Color(0xFFE57373),
                          content: Text(context
                              .read<MindMapProvider>()
                              .t('pptx.cannotOpenExternal')
                              .replaceFirst('{err}', '${r.message}')),
                        ),
                      );
                    }
                  } catch (e) {
                    if (mounted) {
                      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
                        SnackBar(
                          backgroundColor: const Color(0xFFE57373),
                          content: Text(context
                              .read<MindMapProvider>()
                              .t('pptx.externalLaunchFailed')
                              .replaceFirst('{err}', '$e')),
                        ),
                      );
                    }
                  }
                },
                icon: const Icon(Icons.open_in_new_rounded, size: 16),
                label: Text(
                    context.read<MindMapProvider>().t('pptx.openExternal')),
              ),
            ],
          ),
        ),
      );
    } else {
      body = _buildDocBody(dark, fg);
    }
    // ── Esc で閉じないようにする (= ユーザー要望) ──
    // 埋め込みで使われている時 (画面分割のペインの中など) は、 アプリ本体の
    // 画面と入れ物を共有しているので横取りしない (= 横取りすると Android の
    // 戻るでアプリ本体まで閉じてしまう)。
    return PopScope(
      canPop: !_ownsCloseRoute(context),
      onPopInvokedWithResult: (didPop, _) {
        if (didPop || !mounted) return;
        if (_isEscClosePressed(context)) return;
        unawaited(_tryCloseWithConfirm());
      },
      child: Focus(
      focusNode: _docxFocusNode,
      autofocus: true,
      onKeyEvent: _handleDocxKey,
      child: Container(
        color: dark ? const Color(0xFF1A1A24) : const Color(0xFFD8D8D4),
        child: Column(
          children: [
            _buildHeader(dark, fg),
            // (書式ツールバーはヘッダー内へ統合 = ユーザー要望: 1 行に)
            Expanded(
              child: Row(children: [
                Expanded(child: body),
                // ── AI アシスタント (サイドパネル = ユーザー要望) ──
                if (_aiChatPanelOpen)
                  _AiDocChatPanel(
                    title: context
                        .read<MindMapProvider>()
                        .t('docx.aiChatTitle'),
                    hint: context
                        .read<MindMapProvider>()
                        .t('docx.aiChatHint'),
                    docContextGetter: _collectDocAiContext,
                    roleLine:
                        'あなたは Word ドキュメントの編集を手伝うアシスタントです。\n'
                        '要約・校正・翻訳・追記案など、 指示に沿って答えてください。',
                    applyLabel:
                        context.read<MindMapProvider>().t('docx.aiApply'),
                    appliedMsg:
                        context.read<MindMapProvider>().t('docx.aiApplied'),
                    historyKey:
                        'docAiChat_${_currentFilePath.hashCode.toRadixString(16)}',
                    onApply: (aiResult) {
                      setState(() {
                        for (final line in aiResult.split('\n')) {
                          _blocks.add(_DocxBlock.paragraph(
                            paraStyle: _DocxParaStyle.normal,
                            runs: [_DocxRun(line)],
                          ));
                        }
                        _dirty = true;
                      });
                    },
                    onClose: () =>
                        setState(() => _aiChatPanelOpen = false),
                  ),
              ]),
            ),
          ],
        ),
      ),
      ),
    );
  }

  /// ドキュメント全体のキー受け取り用 FocusNode。
  /// 編集モードに入ると TextField の方にフォーカスが移るので、 こちらは
  /// 編集中以外の操作 (= 矢印キーでブロック選択を上下に動かす) を担う。
  final FocusNode _docxFocusNode = FocusNode(debugLabel: 'docx_viewer_body');

  /// 矢印キー / Enter / Escape のキーハンドリング。
  /// - 編集中でない時: ↑↓ で選択ブロックを移動、 Enter で編集モード、
  ///   Esc で選択解除
  /// - 編集中の時: TextField 側で処理 (= ここでは ignore)
  /// `KeyDownEvent` だけでなく `KeyRepeatEvent` も処理することで、
  /// OS のキーリピート (= 長押しでの連続移動) に対応する。
  KeyEventResult _handleDocxKey(FocusNode node, KeyEvent event) {
    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
      return KeyEventResult.ignored;
    }
    final isCtrl = HardwareKeyboard.instance.isControlPressed ||
        HardwareKeyboard.instance.isMetaPressed;
    final isShift = HardwareKeyboard.instance.isShiftPressed;

    // ── Ctrl+S = 保存 ──
    if (isCtrl && event.logicalKey == LogicalKeyboardKey.keyS) {
      _save();
      return KeyEventResult.handled;
    }
    // ── Ctrl+Z = Undo, Ctrl+Shift+Z = Redo ──
    if (isCtrl && event.logicalKey == LogicalKeyboardKey.keyZ) {
      if (isShift) {
        _redo();
      } else {
        _undo();
      }
      return KeyEventResult.handled;
    }
    // ── Ctrl+Y = Redo (Windows 慣習) ──
    if (isCtrl && event.logicalKey == LogicalKeyboardKey.keyY) {
      _redo();
      return KeyEventResult.handled;
    }

    // 編集中の TextField がフォーカス持ってる時は、 こっちはスルー
    if (_editingIdx != null || _editingTableBlockIdx != null) {
      return KeyEventResult.ignored;
    }
    final cur = _selectedIdx;
    if ((event.logicalKey == LogicalKeyboardKey.delete ||
            event.logicalKey == LogicalKeyboardKey.backspace) &&
        cur != null) {
      _deleteBlock(cur);
      _docxFocusNode.requestFocus();
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.arrowUp) {
      _moveSelection(-1);
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.arrowDown) {
      _moveSelection(1);
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.enter ||
        event.logicalKey == LogicalKeyboardKey.f2) {
      if (cur != null && _blocks[cur].kind == _DocxBlockKind.paragraph) {
        _beginEditBlock(cur);
        return KeyEventResult.handled;
      }
    }
    if (event.logicalKey == LogicalKeyboardKey.escape) {
      // ── Esc の挙動 ──
      // 1. 何か選択中 (= _selectedIdx != null) なら、 まず選択解除のみ
      //    (= 既存挙動。 ユーザーが意図せず閉じてしまうのを防ぐ)
      // 2. 何も選択されてない状態で再度 Esc → ダイアログを閉じる
      //    変更があれば確認ダイアログで「保存 / 破棄 / キャンセル」 を選択。
      if (_selectedIdx != null) {
        setState(() => _selectedIdx = null);
        return KeyEventResult.handled;
      }
      // ── Esc で閉じない設定 (= ユーザー要望) ──
      if (!context.read<MindMapProvider>().closeViewerWithEsc) {
        return KeyEventResult.handled;
      }
      // 閉じる処理は async なので fire-and-forget
      _tryCloseWithConfirm();
      return KeyEventResult.handled;
    }
    return KeyEventResult.ignored;
  }

  /// ダイアログを閉じる前に、 変更 (`_dirty`) があれば確認ダイアログを出し、
  /// ユーザーの選択に応じて保存 / 破棄 / キャンセルを行う。
  Future<void> _tryCloseWithConfirm() async {
    if (!_dirty) {
      if (mounted) Navigator.of(context).pop();
      return;
    }
    final choice = await showDialog<String>(
      context: context,
      barrierDismissible: false,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF22222E),
        title: Text(context.read<MindMapProvider>().t('doc.unsavedChanges'),
            style: const TextStyle(color: Colors.white)),
        content: const Text(
          '編集内容を保存して閉じますか?',
          style: TextStyle(color: Colors.white70),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop('cancel'),
            child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          TextButton(
            onPressed: () => Navigator.of(ctx).pop('discard'),
            style: TextButton.styleFrom(
              foregroundColor: const Color(0xFFE57373),
            ),
            child: Text(context.read<MindMapProvider>().t('pdf.discardClose')),
          ),
          FilledButton.icon(
            onPressed: () => Navigator.of(ctx).pop('save'),
            icon: const Icon(Icons.save_rounded, size: 16),
            label: Text(context.read<MindMapProvider>().t('pdf.saveClose')),
            style: FilledButton.styleFrom(
              backgroundColor: const Color(0xFF43B97F),
              foregroundColor: Colors.white,
            ),
          ),
        ],
      ),
    );
    if (!mounted) return;
    if (choice == 'save') {
      await _save();
      if (mounted) Navigator.of(context).pop();
    } else if (choice == 'discard') {
      Navigator.of(context).pop();
    }
    // cancel: 何もしない (= ダイアログのまま残る)
  }

  /// 各ブロックに付ける GlobalKey マップ。 スクロール追跡用に
  /// `Scrollable.ensureVisible` でブロックの BuildContext を必要とする。
  /// ブロックが追加/削除されると idx がずれるが、 移動時に都度参照するだけ
  /// なので問題にならない (古いキーは次フレームで再生成)。
  final Map<int, GlobalKey> _blockKeys = {};

  GlobalKey _keyForBlock(int idx) {
    return _blockKeys.putIfAbsent(idx, () => GlobalKey());
  }

  /// ブロック行の onTapDown で記憶するタップ位置 (= クリック位置に
  /// カーソルを置くため。 ユーザー要望 2026-07)。
  Offset? _pendingDocxTapPos;

  /// 選択を delta (= +1 or -1) で動かす。 編集可能なブロックにスキップ。
  /// 移動先が paragraph タイプの場合は自動で編集モードに入る (= ユーザーが
  /// すぐタイプ開始できる)。
  /// 画面外に出たら自動でスクロールして画面内に戻す。 方向別に追跡位置を
  /// 調整することで、 連続移動時に「下に動いてるのに上端寄りに置かれる」
  /// 等の違和感をなくす。
  void _moveSelection(int delta) {
    if (_blocks.isEmpty) return;
    int start = _selectedIdx ?? -1;
    int next = start + delta;
    // 範囲チェック + ブロック存在チェック
    if (next < 0) next = 0;
    if (next >= _blocks.length) next = _blocks.length - 1;
    // 編集中の TextField がもしあれば commit
    _commitEdit();
    _commitTableEdit();
    setState(() => _selectedIdx = next);
    // ── 重要: 矢印キー移動時は編集モードに入らない ──
    // 旧実装: _beginEditBlock(next) を呼んで TextField を自動で開いていた。
    // しかし、 TextField (EditableText) は自身を viewport 内に入れる自動
    // スクロール処理を持っており、 これが Scrollable.ensureVisible と
    // 競合して「下端まで完全に外れないと追跡されない」 不具合の原因に
    // なっていた。 → 矢印キーは純粋に選択移動のみとし、 編集モードへの
    // 突入はクリック or Enter キーに委ねる (Word と同じ感覚)。
    _ensureSelectedVisible(direction: delta);
  }

  /// シーケンス番号: `_ensureSelectedVisible` 呼び出し毎に進める。
  /// 古い保留要求 (addPostFrameCallback で待機中のもの) は実行時に
  /// 番号不一致でスキップされる。
  int _ensureVisibleSeq = 0;

  /// 選択中ブロックが画面内に収まるようスクロール。 1 フレーム後に実行。
  /// 旧実装は `Scrollable.ensureVisible` のみだったが、 ブロック高さが
  /// 大きい場合や、 `currentContext` が一時的に null の場合に追跡が
  /// 飛ぶことがあった。 信頼性向上のため、 シーケンス番号で古い要求を
  /// 無効化しつつ、 RenderObject の位置を計算して ScrollPosition を
  /// 直接動かす自前ロジックを採用。
  void _ensureSelectedVisible({int direction = 0}) {
    if (_selectedIdx == null) return;
    _ensureVisibleSeq++;
    final mySeq = _ensureVisibleSeq;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || mySeq != _ensureVisibleSeq) return;
      _doEnsureVisible(direction, 0);
    });
  }

  /// 実際にスクロールを実行。 idx 引数は持たず、 常にその時点の
  /// `_selectedIdx` を見て動かす (= 連打中も最新の選択に追従)。
  /// [attempt] はリトライ回数 (= ブロック context が null だった時の再試行)。
  void _doEnsureVisible(int direction, int attempt) {
    if (!mounted) return;
    final idx = _selectedIdx;
    if (idx == null) return;
    final key = _blockKeys[idx];
    final ctx = key?.currentContext;
    if (ctx == null) {
      // context がまだ生成されていない (= viewport 外で recycled、 もしくは
      // 高速連打中で build が間に合っていない)。 短い間隔でリトライする。
      // ただし無限ループ防止のため最大 6 回 (~100ms) で諦める。
      if (attempt >= 6) return;
      Future.delayed(const Duration(milliseconds: 16), () {
        if (!mounted) return;
        _doEnsureVisible(direction, attempt + 1);
      });
      return;
    }
    _scrollToCtx(ctx, direction);
  }

  /// ブロックの RenderBox を viewport (= ScrollView) の座標系で計算し、
  /// 画面外なら ScrollPosition.animateTo でスムーズにスクロール。
  /// `animateTo` は前のアニメーションを自動中断して新目標に切り替わるため、
  /// キー連打時も滑らかに追従する (旧 jumpTo は瞬間移動で「飛び飛び」 になっていた)。
  void _scrollToCtx(BuildContext ctx, int direction) {
    if (!_scroll.hasClients) return;
    final box = ctx.findRenderObject();
    if (box is! RenderBox) return;
    final viewport = _docScrollViewportKey.currentContext?.findRenderObject();
    if (viewport is! RenderBox) return;
    final position = _scroll.position;
    final blockTop = box.localToGlobal(Offset.zero, ancestor: viewport).dy;
    final blockHeight = box.size.height;
    final blockBottom = blockTop + blockHeight;
    final viewportHeight = viewport.size.height;
    const margin = 16.0;
    double targetDelta = 0.0;
    if (direction >= 0) {
      if (blockBottom > viewportHeight - margin) {
        targetDelta = blockBottom - viewportHeight * 0.7;
      } else if (blockTop < margin) {
        targetDelta = blockTop - viewportHeight * 0.3;
      }
    } else {
      if (blockTop < margin) {
        targetDelta = blockTop - viewportHeight * 0.3;
      } else if (blockBottom > viewportHeight - margin) {
        targetDelta = blockBottom - viewportHeight * 0.7;
      }
    }
    if (targetDelta == 0.0) return;
    final newPos = (position.pixels + targetDelta)
        .clamp(position.minScrollExtent, position.maxScrollExtent);
    if ((newPos - position.pixels).abs() < 0.5) return;
    position.animateTo(
      newPos,
      duration: const Duration(milliseconds: 120),
      curve: Curves.easeOut,
    );
  }

  void _recenterSelection() {
    _ensureSelectedVisible(direction: 0);
  }

  /// AI アシスタントへ渡す本文 (段落 / 表 / 数式などの要約テキスト)。
  String _collectDocAiContext() {
    final sb = StringBuffer();
    for (final blk in _blocks) {
      switch (blk.kind) {
        case _DocxBlockKind.paragraph:
          sb.writeln(blk.runs.map((r) => r.text).join());
          break;
        case _DocxBlockKind.table:
          // tableRows: List<List<List<_DocxBlock>>> = rows[r][c] = ブロック群
          for (final row in blk.tableRows) {
            final cellTexts = <String>[];
            for (final cell in row) {
              final cellSb = StringBuffer();
              for (final cellBlk in cell) {
                if (cellBlk.kind == _DocxBlockKind.paragraph) {
                  cellSb.write(cellBlk.runs.map((r) => r.text).join());
                }
              }
              cellTexts.add(cellSb.toString());
            }
            sb.writeln(cellTexts.join(' | '));
          }
          break;
        case _DocxBlockKind.math:
          sb.writeln('[数式: ${blk.mathTex ?? ""}]');
          break;
        case _DocxBlockKind.image:
          sb.writeln('[画像]');
          break;
        case _DocxBlockKind.pageBreak:
          sb.writeln('---');
          break;
      }
    }
    return sb.toString();
  }

