/// ダイアログを押したボタンの近くに出す汎用ヘルパー (= ユーザー要望:
/// 画面中央ではなくボタン付近に項目が出るように)。 [anchorContext] は
/// 押されたボタン自身の BuildContext。 位置が取れない時は中央に出す。
Future<T?> _showDialogNearAnchor<T>(
  BuildContext anchorContext, {
  required WidgetBuilder builder,
  double width = 320,
  double estHeight = 240,
}) {
  final overlayBox = Overlay.of(anchorContext, rootOverlay: true)
      .context
      .findRenderObject() as RenderBox?;
  Rect? rect;
  final ro = anchorContext.findRenderObject();
  if (ro is RenderBox && ro.attached && overlayBox != null) {
    rect = ro.localToGlobal(Offset.zero, ancestor: overlayBox) & ro.size;
  }
  return showDialog<T>(
    context: anchorContext,
    builder: (dctx) {
      if (rect == null) return Builder(builder: builder);
      final screen = MediaQuery.of(dctx).size;
      final left = (rect.center.dx - width / 2)
          .clamp(8.0, math.max(8.0, screen.width - width - 8))
          .toDouble();
      var top = rect.bottom + 8;
      if (top + estHeight > screen.height - 8) {
        top = math.max(8.0, rect.top - estHeight - 8);
      }
      return Stack(children: [
        Positioned(
          left: left,
          top: top,
          width: width,
          child: Material(
            type: MaterialType.transparency,
            child: Builder(builder: builder),
          ),
        ),
      ]);
    },
  );
}

/// 未保存確認を「× ボタンの付近 + 最前面」 に出す (= ユーザー要望: 変更を
/// 保存して閉じるかのモーダルはフローティングの上・× ボタンの近くに)。
///
/// showDialog はフローティング窓 (root Overlay 直挿し) より下に描かれて
/// 隠れてしまうため、 こちらも root Overlay へ直接挿す。 各エディタの
/// × ボタンはヘッダー右端にあるので、 [hostContext] (= エディタ本体) の
/// 右上内側に置けば × のすぐ近くに出る。
/// 返り値: 'save' / 'discard' / 'cancel' / null (外側タップ)。
/// 未保存確認が今出ているか (= ユーザー報告: Esc を押すたびにダイアログが
/// 積み上がって画面が真っ暗になる)。 出ている間は新しく出さない。
bool _unsavedConfirmOpen = false;

Future<String?> _showUnsavedConfirmNear(BuildContext hostContext) {
  if (_unsavedConfirmOpen) return Future<String?>.value(null);
  final provider = hostContext.read<MindMapProvider>();
  final title = provider.t('doc.unsavedChanges');
  final message = provider.t('doc.discardChangesClose');
  final actions = <(String, String)>[
    ('cancel', provider.t('btn.cancel')),
    ('save', provider.t('pdf.saveClose')),
    ('discard', provider.t('pdf.discardClose')),
  ];
  final overlayState = Overlay.of(hostContext, rootOverlay: true);
  final overlayBox = overlayState.context.findRenderObject() as RenderBox?;
  final screen = overlayBox?.size ?? MediaQuery.of(hostContext).size;
  const width = 320.0;
  double left = screen.width - width - 16;
  double top = 60;
  final ro = hostContext.findRenderObject();
  if (ro is RenderBox && ro.attached && overlayBox != null) {
    final tl = ro.localToGlobal(Offset.zero, ancestor: overlayBox);
    final rect = tl & ro.size;
    if (rect.height <= 80) {
      // アンカーが × ボタンそのもの (小さい widget) → すぐ下に出す
      // (= ユーザー要望: ちゃんと × の近くに出るように)。
      left = rect.right - width;
      top = rect.bottom + 6;
    } else {
      // アンカーがエディタ全体 → ヘッダー右端 (× の付近) に出す。
      left = rect.right - width - 10;
      top = rect.top + 44;
    }
  }
  left = left.clamp(8.0, math.max(8.0, screen.width - width - 8));
  top = top.clamp(8.0, math.max(8.0, screen.height - 180));
  final completer = Completer<String?>();
  late OverlayEntry entry;
  // 出ている間は 2 枚目を出さない (= ユーザー報告: Esc 連打で溜まって
  // 画面が真っ暗になる)。
  _unsavedConfirmOpen = true;
  void finish(String? v) {
    if (completer.isCompleted) return;
    _unsavedConfirmOpen = false;
    completer.complete(v);
    try {
      entry.remove();
    } catch (_) {}
  }

  entry = OverlayEntry(
    builder: (_) => Stack(children: [
      Positioned.fill(
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () => finish(null),
          child: const ColoredBox(color: Color(0x2E000000)),
        ),
      ),
      Positioned(
        left: left,
        top: top,
        width: width,
        child: Material(
          color: const Color(0xFF1E1E32),
          elevation: 10,
          borderRadius: BorderRadius.circular(10),
          child: Padding(
            padding: const EdgeInsets.fromLTRB(14, 12, 14, 8),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(title,
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 13.5,
                        fontWeight: FontWeight.w600)),
                const SizedBox(height: 6),
                Text(message,
                    style:
                        const TextStyle(color: Colors.white70, fontSize: 12)),
                const SizedBox(height: 8),
                Align(
                  alignment: Alignment.centerRight,
                  child: Wrap(spacing: 2, children: [
                    for (final a in actions)
                      TextButton(
                        onPressed: () => finish(a.$1),
                        child: Text(a.$2,
                            style: TextStyle(
                                fontSize: 12.5,
                                color: a.$1 == 'discard'
                                    ? const Color(0xFFFF8A80)
                                    : a.$1 == 'save'
                                        ? const Color(0xFF8C7CFF)
                                        : Colors.white54)),
                      ),
                  ]),
                ),
              ],
            ),
          ),
        ),
      ),
    ]),
  );
  overlayState.insert(entry);
  return completer.future;
}

/// 分割セルの中でファイルビューアを開くための器 (= ユーザー要望:
/// 浮遊窓ではなく、 その画面に埋め込まれた状態で開く)。
///
/// ビューアは `Navigator.of(context).pop()` で自分を閉じるので、 アプリ本体の
/// ルートを巻き添えにしないよう、 セルの中に専用の Navigator を立てる
/// (`_FloatingPanelWindow` と同じ方式)。 その pop を検知して [onClose] を呼び、
/// セルの埋め込みを解除する。
///
/// MediaQuery のサイズはセルの大きさに差し替える。 これをしないと、
/// ビューア側の「画面の 70%」 のような寸法計算がウィンドウ全体を基準にして
/// しまい、 狭いセルからはみ出す。
class _SplitCellEmbeddedPanel extends StatefulWidget {
  final WidgetBuilder builder;
  final VoidCallback onClose;
  const _SplitCellEmbeddedPanel({
    super.key,
    required this.builder,
    required this.onClose,
  });

  @override
  State<_SplitCellEmbeddedPanel> createState() =>
      _SplitCellEmbeddedPanelState();
}

class _SplitCellEmbeddedPanelState extends State<_SplitCellEmbeddedPanel> {
  final GlobalKey<NavigatorState> _navKey = GlobalKey<NavigatorState>();
  bool _pushed = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || _pushed) return;
      _pushed = true;
      _navKey.currentState!
          .push(MaterialPageRoute<void>(builder: widget.builder))
          .then((_) {
        if (mounted) widget.onClose();
      });
    });
  }

  @override
  Widget build(BuildContext context) {
    final mq = MediaQuery.of(context);
    return Material(
      color: const Color(0xFF10101A),
      child: LayoutBuilder(builder: (ctx, bc) {
        return MediaQuery(
          data: mq.copyWith(
            size: Size(bc.maxWidth, bc.maxHeight),
            padding: EdgeInsets.zero,
            viewPadding: EdgeInsets.zero,
          ),
          child: Navigator(
            key: _navKey,
            onGenerateRoute: (_) => MaterialPageRoute<void>(
                builder: (_) => const ColoredBox(color: Color(0xFF10101A))),
          ),
        );
      }),
    );
  }
}

class _FloatingPanelWindow extends StatefulWidget {
  final WidgetBuilder builder;
  final VoidCallback onClose;
  final double initialWidth;
  final double initialHeight;

  /// 大きさと位置を覚えておくための名前 (= ユーザー要望: 最後に開いた
  /// 大きさで開いてほしい)。 null なら覚えない。
  final String? memoryKey;

  /// アプリの外へ出せる窓なら、 その URL (= ユーザー要望: Google マップ
  /// などをフローティングメモのようにアプリの外へ出したい)。
  /// null なら「外に出す」 ボタンを出さない。
  final String? popOutUrl;

  /// 押された時に URL を決める版 (= フローティング AI のように、 中で
  /// 表示先を切り替えられる窓のため)。 [popOutUrl] より優先する。
  final ValueGetter<String>? popOutUrlBuilder;

  /// AI を切り替えられる窓なら、 ヘッダーに切り替えボタンを出す
  /// (= ユーザー要望: フローティングに切り替えた後もヘッダーからモデルを
  /// 変えられるように)。 null ならボタンを出さない。
  final VoidCallback? onSwitchAi;

  /// Web ページではない画面を外へ出すための差し替え口
  /// (= ユーザー要望: AI アシスタントもアプリの外に出したい)。
  /// 渡された場所・大きさで外の窓を開き、 開けたら true を返す。
  /// これがある窓は「ウェブページだけ」 の制限を受けない。
  final Future<bool> Function(Rect frame, bool pinned)? popOutCustom;
  const _FloatingPanelWindow({
    required this.builder,
    required this.onClose,
    this.initialWidth = 760,
    this.initialHeight = 560,
    this.memoryKey,
    this.popOutUrl,
    this.popOutUrlBuilder,
    this.onSwitchAi,
    this.popOutCustom,
    this.initialRect,
  });

  /// 最初に出す位置と大きさ (画面グローバル座標)。 マップ分割中に
  /// 「分割セルを覆う形」 で開くために使う (= ユーザー要望)。
  /// memoryKey の保存値よりもこちらを優先する。
  final Rect? initialRect;
  @override
  State<_FloatingPanelWindow> createState() => _FloatingPanelWindowState();
}

class _FloatingPanelWindowState extends State<_FloatingPanelWindow> {
  final GlobalKey<NavigatorState> _navKey = GlobalKey<NavigatorState>();
  bool _pushed = false;
  late Offset _pos = widget.initialRect?.topLeft ?? const Offset(100, 70);
  late double _w = widget.initialRect?.width ?? widget.initialWidth;
  late double _h = widget.initialRect?.height ?? widget.initialHeight;

  /// 大きさ・位置の保存は、 動かすたびに書かず少し待ってからまとめて行う。
  Timer? _saveTimer;

  String? get _prefsKey =>
      widget.memoryKey == null ? null : 'floatWin_${widget.memoryKey}';

  Future<void> _restoreGeometry() async {
    // 分割セルを覆う指定 (initialRect) がある時は保存値で動かさない。
    if (widget.initialRect != null) return;
    final key = _prefsKey;
    if (key == null) return;
    try {
      final sp = await SharedPreferences.getInstance();
      final raw = sp.getString(key);
      if (raw == null || raw.isEmpty) return;
      final m = jsonDecode(raw);
      if (m is! Map) return;
      final w = (m['w'] as num?)?.toDouble();
      final h = (m['h'] as num?)?.toDouble();
      final x = (m['x'] as num?)?.toDouble();
      final y = (m['y'] as num?)?.toDouble();
      if (!mounted) return;
      setState(() {
        if (w != null && w >= 360) _w = w;
        if (h != null && h >= 280) _h = h;
        if (x != null && y != null) _pos = Offset(x, y);
      });
    } catch (_) {}
  }

  /// この URL を、 アプリとは別のウィンドウ (別プロセス) で開く。
  ///
  /// 同じプロセスのサブ窓にすると、 その窓を閉じた時に本体側で WebView を
  /// 作れなくなる不具合があった (b88 で修正済み)。 それを避けるため、
  /// 自分自身をもう 1 つ起動して、 そちらに Web だけ表示させる。
  void _popOutToOwnWindow(String url) {
    // 実体は共通の openExternalWebWindow (別プロセスの窓)。
    openExternalWebWindow(url);
  }

  void _scheduleSaveGeometry() {
    if (_prefsKey == null) return;
    _saveTimer?.cancel();
    _saveTimer = Timer(const Duration(milliseconds: 400), () async {
      try {
        final sp = await SharedPreferences.getInstance();
        await sp.setString(
          _prefsKey!,
          jsonEncode({'w': _w, 'h': _h, 'x': _pos.dx, 'y': _pos.dy}),
        );
      } catch (_) {}
    });
  }

  @override
  void dispose() {
    _floatingPopOutHandlers.remove(_popOutHandler);
    _saveTimer?.cancel();
    super.dispose();
  }

  @override
  void initState() {
    super.initState();
    // 本体が最小化されたら外の窓に変わって生き残る (= ユーザー要望)。
    _popOutHandler = () => _popOutSelf();
    _floatingPopOutHandlers.add(_popOutHandler);
    unawaited(_restoreGeometry());
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || _pushed) return;
      _pushed = true;
      _navKey.currentState!
          .push(MaterialPageRoute(builder: widget.builder))
          .then((_) {
        if (mounted) widget.onClose();
      });
    });
  }


  // ─── モード切替 (元の画面 / AI / メモ) と ピン留め (= ユーザー要望) ───
  /// 'main' = 元の画面、 'ai' = フローティング AI、 'memo' = フローティングメモ。
  String _floatMode = 'main';
  bool _aiStarted = false;
  bool _memoStarted = false;
  String _floatAiUrl = '';

  /// 本体が最小化された時に「外の窓」 へ変わるための登録口。
  late final Future<bool> Function() _popOutHandler;

  /// この窓が外に出る時に開く URL。
  String get _popOutUrl => (widget.popOutUrlBuilder?.call() ?? widget.popOutUrl ?? '').trim();

  /// 外に出せない理由 (出せるなら null)。 差し替え口を持つ窓は制限を受けない。
  String? _blockedReason(MindMapProvider provider) => widget.popOutCustom != null
      ? null
      : popOutBlockedReason(provider, _popOutUrl);

  /// この窓を「アプリの外の本物の窓」 へ変える。 出せない窓なら false。
  /// [pinned] なら開いた瞬間から常に手前 (= 前面にピン留め)。
  Future<bool> _popOutSelf({bool pinned = false}) async {
    if (!mounted) return false;
    final provider = context.read<MindMapProvider>();
    final url = _popOutUrl;
    final custom = widget.popOutCustom;
    if (custom == null && popOutBlockedReason(provider, url) != null) {
      return false;
    }
    var origin = Offset.zero;
    try {
      final b = await windowManager.getBounds();
      // 最小化中は座標があり得ない値になるので、 その時は使わない。
      if (b.left > -8000 && b.top > -8000) origin = b.topLeft;
    } catch (_) {}
    final frame = Rect.fromLTWH((origin.dx + _pos.dx).clamp(0.0, 8000.0),
        (origin.dy + _pos.dy).clamp(0.0, 8000.0), _w, _h);
    // Web ページでない画面 (AI アシスタントなど) は差し替え口に任せる。
    if (custom != null) {
      final ok = await custom(frame, pinned);
      if (ok && mounted) widget.onClose();
      return ok;
    }
    final ok = openExternalWebWindow(url, pinned: pinned, frame: frame);
    if (ok && mounted) widget.onClose();
    return ok;
  }

  /// ヘッダーのモード切替 + ピン留めボタン群 (両方のフローティング窓で共通)。
  /// [showAi] が false の時は AI ボタンを出さない (= AI 窓自身には不要)。
  List<Widget> _floatModeButtons(BuildContext ctx, {bool showAi = true}) {
    // 別の窓を作れないスマホ版では出さない (ピンも外出しもできないため)。
    if (kIsWeb ||
        !(Platform.isWindows || Platform.isMacOS || Platform.isLinux)) {
      return const [];
    }
    final provider = ctx.read<MindMapProvider>();
    Widget btn(IconData icon, String tip, VoidCallback onTap,
        {Color color = Colors.white54}) {
      return IconButton(
        padding: EdgeInsets.zero,
        constraints: const BoxConstraints(minWidth: 28, minHeight: 28),
        tooltip: tip,
        icon: Icon(icon, size: 15, color: color),
        onPressed: onTap,
      );
    }

    return [
      // 元の画面に戻る (= ユーザー要望: AI などに切り替えた後で戻れるように)。
      if (_floatMode != 'main')
        btn(Icons.arrow_back_rounded, provider.t('float.backToItem'),
            () => setState(() => _floatMode = 'main'),
            color: const Color(0xFF4FC3F7)),
      // フローティング AI に切り替え (= ユーザー要望)。
      if (showAi && _floatMode != 'ai')
        btn(Icons.auto_awesome_rounded, provider.t('float.toAi'), () {
          setState(() {
            _floatAiUrl = (provider.browserAiTargetDef['url'] ?? '')
                .replaceAll('{q}', '');
            _aiStarted = true;
            _floatMode = 'ai';
          });
        }, color: const Color(0xFFBA68C8)),
      // フローティングメモに切り替え (= ユーザー要望)。 保存先は外のメモ窓と
      // 同じなので、 どこで書いても同じメモ帳に積まれる。
      if (_floatMode != 'memo')
        btn(Icons.sticky_note_2_rounded, provider.t('float.toMemo'), () {
          setState(() {
            _memoStarted = true;
            _floatMode = 'memo';
          });
        }, color: const Color(0xFFFFB347)),
      // 前面にピン留め (= ユーザー要望)。 アプリの中の重ね描きは他のアプリの
      // 手前には出られないので、 外の本物の窓に変わって常に手前になる。
      btn(Icons.push_pin_rounded, provider.t('float.pinToFront'), () {
        final blocked = _blockedReason(provider);
        if (blocked != null) {
          final m = ScaffoldMessenger.maybeOf(ctx);
          m?.hideCurrentSnackBar();
          m?.showSnackBar(SnackBar(
              content: Text(blocked),
              duration: const Duration(seconds: 4)));
          return;
        }
        unawaited(_popOutSelf(pinned: true));
      }),
    ];
  }

  /// AI / メモへ切り替えても元の画面を壊さないよう、 重ねて出し分ける。
  Widget _floatModeStack(Widget main) {
    return Stack(children: [
      Offstage(offstage: _floatMode != 'main', child: main),
      if (_aiStarted)
        Offstage(
          offstage: _floatMode != 'ai',
          child: _WinGoogleSearchView(
              key: ValueKey('float_ai_$_floatAiUrl'), url: _floatAiUrl),
        ),
      if (_memoStarted)
        Offstage(
            offstage: _floatMode != 'memo',
            // = ユーザー要望: メモはフローティングメモと同じ画面を出す。
            child: const FloatingMemoView()),
    ]);
  }

  /// 今の位置なら「アプリの外」 とみなせるか (= 半分より外に出ている)。
  bool _isDraggedOutside(Size screen) {
    final cx = _pos.dx + _w / 2;
    final cy = _pos.dy + _h / 2;
    return cx < 0 || cy < 0 || cx > screen.width || cy > screen.height;
  }

  /// 掴んで外へ放したら、 そのまま「アプリの外の窓」 になる
  /// (= ユーザー要望: ボタンを押さなくても、 外へ出したら外に出るように)。
  /// 出せない窓 (電卓など / スマホ版) は理由を知らせて画面の中へ戻す。
  Future<void> _handleDragRelease(Size screen) async {
    if (!mounted || !_isDraggedOutside(screen)) return;
    final provider = context.read<MindMapProvider>();
    final url = (widget.popOutUrlBuilder?.call() ?? widget.popOutUrl ?? '')
        .trim();
    final blocked = _blockedReason(provider);
    void snapBack() {
      setState(() {
        _pos = Offset(
          _pos.dx.clamp(0.0, math.max(0.0, screen.width - _w)),
          _pos.dy.clamp(0.0, math.max(0.0, screen.height - _h)),
        );
      });
    }

    if (blocked != null) {
      final m = ScaffoldMessenger.maybeOf(context);
      m?.hideCurrentSnackBar();
      m?.showSnackBar(SnackBar(
          content: Text(blocked), duration: const Duration(seconds: 4)));
      snapBack();
      return;
    }
    // Web ページでない画面 (AI アシスタントなど) は差し替え口に任せる。
    if (widget.popOutCustom != null) {
      if (!await _popOutSelf()) snapBack();
      return;
    }
    // アプリ窓の画面上の位置を足して、 放した場所にそのまま出す。
    var origin = Offset.zero;
    try {
      final b = await windowManager.getBounds();
      origin = b.topLeft;
    } catch (_) {}
    final ok = openExternalWebWindow(url,
        frame:
            Rect.fromLTWH(origin.dx + _pos.dx, origin.dy + _pos.dy, _w, _h));
    if (!ok) {
      snapBack();
      return;
    }
    widget.onClose();
  }

  @override
  Widget build(BuildContext context) {
    final screen = MediaQuery.of(context).size;
    // ★ 端をまたいで外へ引っ張れるようにする (= ユーザー要望: 外へ出したら
    //   そのまま外の窓になるように)。 以前は画面の中へ抑え込んでいたので、
    //   そもそも外へ引っ張れなかった。 見失わないよう 1/4 は画面に残す。
    final maxLeft = math.max(0.0, screen.width - _w / 4);
    final maxTop = math.max(0.0, screen.height - _h / 4);
    final minLeft = -_w * 0.75;
    final minTop = -_h * 0.75;
    final draggedOut = _isDraggedOutside(screen);
    return Positioned(
      left: _pos.dx.clamp(minLeft, maxLeft),
      top: _pos.dy.clamp(minTop, maxTop),
      child: Material(
        color: Colors.transparent,
        child: Container(
          width: _w,
          height: _h,
          decoration: BoxDecoration(
            color: const Color(0xFF10101A),
            borderRadius: BorderRadius.circular(12),
            border: Border.all(color: Colors.white24),
            boxShadow: const [BoxShadow(color: Colors.black54, blurRadius: 18)],
          ),
          child: Stack(children: [
            Column(children: [
              // ── ドラッグ移動用ヘッダー ──
              GestureDetector(
                behavior: HitTestBehavior.opaque,
                onPanUpdate: (d) {
                  setState(() => _pos = Offset(
                      (_pos.dx + d.delta.dx).clamp(minLeft, maxLeft),
                      (_pos.dy + d.delta.dy).clamp(minTop, maxTop)));
                  _scheduleSaveGeometry();
                },
                // 画面の外まで引っ張って放したら、 そのまま外の窓になる
                // (= ユーザー要望: ボタンを押さなくても外に出るように)。
                onPanEnd: (_) => unawaited(_handleDragRelease(screen)),
                child: Container(
                  height: 30,
                  padding: const EdgeInsets.only(left: 10, right: 2),
                  decoration: const BoxDecoration(
                    color: Color(0xFF1A1A2E),
                    borderRadius:
                        BorderRadius.vertical(top: Radius.circular(11)),
                  ),
                  child: Row(children: [
                    const Icon(Icons.drag_indicator_rounded,
                        color: Colors.white38, size: 15),
                    const Spacer(),
                    // ── AI の切り替え (= ユーザー要望: フローティングに
                    //    切り替えた後もヘッダーからモデルを変えられるように) ──
                    if (widget.onSwitchAi != null)
                      IconButton(
                        tooltip:
                            context.read<MindMapProvider>().t('ai.selectAi'),
                        padding: EdgeInsets.zero,
                        constraints:
                            const BoxConstraints(minWidth: 28, minHeight: 28),
                        icon: const Icon(Icons.auto_awesome_rounded,
                            color: Color(0xFFBA68C8), size: 15),
                        onPressed: widget.onSwitchAi,
                      ),
                    ..._floatModeButtons(context,
                        showAi: widget.onSwitchAi == null),
                    // ── 「外に出す」 ボタンは廃止 (= ユーザー要望: 右上に
                    //    ボタンを付けなくても、 外へ引っ張ったら外に出るように)。
                    //    代わりに、 画面の外まで引っ張っている間だけ
                    //    「放すと外に出る」 と出して分かるようにする。 ──
                    if (draggedOut)
                      Padding(
                        padding: const EdgeInsets.only(right: 6),
                        child: Row(mainAxisSize: MainAxisSize.min, children: [
                          const Icon(Icons.open_in_new_rounded,
                              color: Color(0xFF4FC3F7), size: 13),
                          const SizedBox(width: 4),
                          Text(
                              context
                                  .read<MindMapProvider>()
                                  .t('float.dropToPopOut'),
                              style: const TextStyle(
                                  color: Color(0xFF4FC3F7), fontSize: 10)),
                        ]),
                      ),
                    IconButton(
                      padding: EdgeInsets.zero,
                      constraints:
                          const BoxConstraints(minWidth: 28, minHeight: 28),
                      icon: const Icon(Icons.close_rounded,
                          color: Colors.white54, size: 15),
                      onPressed: widget.onClose,
                    ),
                  ]),
                ),
              ),
              Expanded(
                child: ClipRRect(
                  borderRadius:
                      const BorderRadius.vertical(bottom: Radius.circular(11)),
                  // ── 中身には「窓の大きさ」 を画面の大きさとして見せる ──
                  //   = ユーザー報告「計算機のフローティングを移動させると
                  //   挙動が不安定」。 中の道具は MediaQuery の大きさを画面と
                  //   見なして動ける範囲を決めるので、 これが無いと窓ではなく
                  //   デスクトップ全体を基準にしてしまい、 窓の外まで動いて
                  //   見えなくなったり、 掴んだ位置とずれたりしていた。
                  child: LayoutBuilder(builder: (lctx, bc) {
                    final mq = MediaQuery.of(lctx);
                    return MediaQuery(
                      data: mq.copyWith(
                        size: Size(bc.maxWidth, bc.maxHeight),
                        padding: EdgeInsets.zero,
                        viewPadding: EdgeInsets.zero,
                        viewInsets: EdgeInsets.zero,
                      ),
                      child: _floatModeStack(Navigator(
                        key: _navKey,
                        onGenerateRoute: (_) => MaterialPageRoute(
                            builder: (_) =>
                                const ColoredBox(color: Color(0xFF10101A))),
                      )),
                    );
                  }),
                ),
              ),
            ]),
            // ── 右下リサイズグリップ ──
            Positioned(
              right: 0,
              bottom: 0,
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onPanUpdate: (d) => setState(() {
                  _w = (_w + d.delta.dx).clamp(360.0, screen.width);
                  _h = (_h + d.delta.dy).clamp(280.0, screen.height);
                  _scheduleSaveGeometry();
                }),
                child: const Padding(
                  padding: EdgeInsets.all(4),
                  child: Icon(Icons.south_east_rounded,
                      size: 14, color: Colors.white38),
                ),
              ),
            ),
          ]),
        ),
      ),
    );
  }
}

// ─── MCP チャット (= ユーザー要望: MCP サーバーを押したらアプリ内で MCP
//     接続した AI チャット欄が立ち上がるように) ───────────────────────────
// ユーザーの AI キー (BYOK) で選択中の AI プロバイダーに問い合わせ、 AI が
// ツール呼び出し JSON を返したら McpServer.callTool で実行して結果を
// フィードバックする簡易エージェントループ。 マップの変更は即画面に反映。


/// 画像を丸く切り抜いてボタンのアイコンにする編集画面 (= ユーザー要望:
/// アップロードした画像を○のトリミングで編集できるように)。
/// ドラッグで位置、 下のつまみで大きさを合わせ、 丸の中身がそのまま保存される。
class _CircleCropDialog extends StatefulWidget {
  final String imagePath;

  /// 保存ファイル名の頭に付ける名前 (= どのボタンの画像か分かるように)。
  final String saveName;
  const _CircleCropDialog({required this.imagePath, required this.saveName});
  @override
  State<_CircleCropDialog> createState() => _CircleCropDialogState();
}

class _CircleCropDialogState extends State<_CircleCropDialog> {
  final GlobalKey _cropKey = GlobalKey();
  double _scale = 1.0;
  Offset _offset = Offset.zero;
  bool _saving = false;

  /// 四角で切り抜くか (= ユーザー要望: 丸以外も使えるように)。
  bool _square = false;

  /// 丸の中身を PNG に描き出して保存する。
  Future<void> _save() async {
    if (_saving) return;
    setState(() => _saving = true);
    try {
      final boundary = _cropKey.currentContext!.findRenderObject()!
          as RenderRepaintBoundary;
      final img = await boundary.toImage(pixelRatio: 2.0);
      final data = await img.toByteData(format: ui.ImageByteFormat.png);
      if (data == null) throw Exception('encode failed');
      final dir = await getApplicationDocumentsDirectory();
      final folder =
          Directory('${dir.path}${Platform.pathSeparator}button_icons');
      if (!folder.existsSync()) folder.createSync(recursive: true);
      final file = File(
          '${folder.path}${Platform.pathSeparator}${widget.saveName}_${DateTime.now().millisecondsSinceEpoch}.png');
      await file.writeAsBytes(data.buffer.asUint8List());
      if (mounted) Navigator.of(context).pop(file.path);
    } catch (_) {
      if (mounted) Navigator.of(context).pop();
    }
  }

  @override
  Widget build(BuildContext context) {
    final provider = context.read<MindMapProvider>();
    const double crop = 240;
    return Dialog(
      backgroundColor: const Color(0xFF1E1E2E),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(18),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Text(provider.t('icon.cropTitle'),
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 15,
                  fontWeight: FontWeight.w700)),
          const SizedBox(height: 4),
          Text(provider.t('icon.cropHint'),
              style: const TextStyle(color: Colors.white54, fontSize: 11)),
          const SizedBox(height: 12),
          // ── 丸い切り抜き窓 (ドラッグで位置を動かす) ──
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            onPanUpdate: (d) => setState(() => _offset += d.delta),
            child: Container(
              decoration: BoxDecoration(
                shape: _square ? BoxShape.rectangle : BoxShape.circle,
                borderRadius:
                    _square ? BorderRadius.circular(18) : null,
                border: Border.all(color: Colors.white24, width: 2),
              ),
              child: RepaintBoundary(
                key: _cropKey,
                child: ClipRRect(
                  // 丸は半径 = 半分、 四角は角を少しだけ丸める。
                  borderRadius:
                      BorderRadius.circular(_square ? 16 : crop / 2),
                  child: SizedBox(
                    width: crop,
                    height: crop,
                    child: Transform.translate(
                      offset: _offset,
                      child: Transform.scale(
                        scale: _scale,
                        child: Image.file(File(widget.imagePath),
                            fit: BoxFit.contain),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
          const SizedBox(height: 8),
          // ── 形を選ぶ (丸 / 四角) ──
          Row(mainAxisAlignment: MainAxisAlignment.center, children: [
            for (final e in [
              (false, provider.t('icon.shapeCircle'), Icons.circle_outlined),
              (true, provider.t('icon.shapeSquare'), Icons.crop_square_rounded),
            ])
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 4),
                child: InkWell(
                  borderRadius: BorderRadius.circular(18),
                  onTap: () => setState(() => _square = e.$1),
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 12, vertical: 6),
                    decoration: BoxDecoration(
                      color: _square == e.$1
                          ? const Color(0xFF4FC3F7).withValues(alpha: 0.25)
                          : Colors.white.withValues(alpha: 0.06),
                      borderRadius: BorderRadius.circular(18),
                      border: Border.all(
                          color: _square == e.$1
                              ? const Color(0xFF4FC3F7)
                              : Colors.white24),
                    ),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      Icon(e.$3,
                          size: 14,
                          color: _square == e.$1
                              ? Colors.white
                              : Colors.white54),
                      const SizedBox(width: 5),
                      Text(e.$2,
                          style: TextStyle(
                              color: _square == e.$1
                                  ? Colors.white
                                  : Colors.white60,
                              fontSize: 12)),
                    ]),
                  ),
                ),
              ),
          ]),
          const SizedBox(height: 8),
          // ── 大きさのつまみ ──
          Row(children: [
            const Icon(Icons.zoom_out_rounded,
                color: Colors.white38, size: 16),
            Expanded(
              child: Slider(
                value: _scale,
                min: 0.5,
                max: 5,
                activeColor: const Color(0xFF4FC3F7),
                onChanged: (v) => setState(() => _scale = v),
              ),
            ),
            const Icon(Icons.zoom_in_rounded,
                color: Colors.white38, size: 16),
          ]),
          Row(mainAxisAlignment: MainAxisAlignment.end, children: [
            TextButton(
              onPressed:
                  _saving ? null : () => Navigator.of(context).pop(),
              child: Text(provider.t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54)),
            ),
            const SizedBox(width: 8),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF4FC3F7),
                  foregroundColor: Colors.black),
              onPressed: _saving ? null : () => unawaited(_save()),
              child: _saving
                  ? const SizedBox(
                      width: 16,
                      height: 16,
                      child: CircularProgressIndicator(strokeWidth: 2))
                  : Text(provider.t('btn.save')),
            ),
          ]),
        ]),
      ),
    );
  }
}

/// フローティング窓の中に出す「フローティングメモ」 (= ユーザー要望: どの
/// フローティングからでもメモへ切り替えられるように)。 保存先は外のメモ窓と
/// 同じ (`kFloatingMemoPrefsKey`) なので、 どこで書いても同じメモ帳に積まれる。
/// 分割ペインの中に「ダイアログとして組まれた画面」 を出すための入れ物
/// (= ユーザー要望: メモも左右分割で開けるように)。
///
/// ペインの中に専用の Navigator を立て、 最初のフレームで [open] を呼ぶ。
/// その画面が閉じたら [onClose] を呼んでペインの埋め込みも解く。
class _PaneDialogHost extends StatefulWidget {
  final Future<void> Function(BuildContext hostContext) open;
  final VoidCallback onClose;
  const _PaneDialogHost({super.key, required this.open, required this.onClose});

  @override
  State<_PaneDialogHost> createState() => _PaneDialogHostState();
}

class _PaneDialogHostState extends State<_PaneDialogHost> {
  final GlobalKey<NavigatorState> _navKey = GlobalKey<NavigatorState>();
  bool _opened = false;

  @override
  Widget build(BuildContext context) {
    return Material(
      color: const Color(0xFF12121F),
      child: LayoutBuilder(builder: (lctx, bc) {
        final mq = MediaQuery.of(lctx);
        return MediaQuery(
          data: mq.copyWith(
            size: Size(bc.maxWidth, bc.maxHeight),
            padding: EdgeInsets.zero,
            viewPadding: EdgeInsets.zero,
          ),
          child: Navigator(
            key: _navKey,
            onGenerateRoute: (_) => MaterialPageRoute<void>(
              builder: (routeCtx) {
                if (!_opened) {
                  _opened = true;
                  WidgetsBinding.instance.addPostFrameCallback((_) async {
                    if (!mounted) return;
                    await widget.open(routeCtx);
                    if (mounted) widget.onClose();
                  });
                }
                return const ColoredBox(color: Color(0xFF12121F));
              },
            ),
          ),
        );
      }),
    );
  }
}

class _FloatingMemoPane extends StatefulWidget {
  const _FloatingMemoPane();
  @override
  State<_FloatingMemoPane> createState() => _FloatingMemoPaneState();
}

class _FloatingMemoPaneState extends State<_FloatingMemoPane> {
  List<FloatMemoBook> _books = [];
  int _active = 0;
  final TextEditingController _input = TextEditingController();
  bool _loading = true;

  @override
  void initState() {
    super.initState();
    unawaited(_reload());
  }

  Future<void> _reload() async {
    try {
      final parsed = parseFloatingMemoBooks(await loadFloatingMemoText());
      if (!mounted) return;
      setState(() {
        _books = parsed.books;
        _active = parsed.active;
        _loading = false;
      });
    } catch (_) {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _add() async {
    final t = _input.text.trim();
    if (t.isEmpty) return;
    _input.clear();
    await appendFloatingMemoItem(t);
    await _reload();
  }

  Future<void> _delete(FloatMemoItem item) async {
    try {
      _books[_active].items.removeWhere((e) => e.id == item.id);
      await saveFloatingMemoText(encodeFloatingMemoBooks(_books, _active));
      if (mounted) setState(() {});
    } catch (_) {}
  }

  @override
  void dispose() {
    _input.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final provider = context.read<MindMapProvider>();
    final items =
        (_active < _books.length) ? _books[_active].items : <FloatMemoItem>[];
    return Container(
      color: const Color(0xFF14141F),
      child: Column(children: [
        Expanded(
          child: _loading
              ? const Center(
                  child: SizedBox(
                      width: 22,
                      height: 22,
                      child: CircularProgressIndicator(strokeWidth: 2)))
              : items.isEmpty
                  ? Center(
                      child: Text(provider.t('float.memoEmpty'),
                          style: const TextStyle(
                              color: Colors.white38, fontSize: 12)))
                  : ListView.separated(
                      padding: const EdgeInsets.all(8),
                      itemCount: items.length,
                      separatorBuilder: (_, __) => const SizedBox(height: 6),
                      itemBuilder: (_, i) {
                        final it = items[i];
                        return Container(
                          padding: const EdgeInsets.fromLTRB(10, 8, 4, 8),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.06),
                            borderRadius: BorderRadius.circular(8),
                          ),
                          child: Row(children: [
                            Expanded(
                              child: SelectableText(it.text,
                                  style: const TextStyle(
                                      color: Colors.white,
                                      fontSize: 12,
                                      height: 1.4)),
                            ),
                            IconButton(
                              padding: EdgeInsets.zero,
                              constraints: const BoxConstraints(
                                  minWidth: 26, minHeight: 26),
                              icon: const Icon(Icons.close_rounded,
                                  color: Colors.white38, size: 14),
                              onPressed: () => unawaited(_delete(it)),
                            ),
                          ]),
                        );
                      },
                    ),
        ),
        // 追記欄 (Enter か + で追加)。
        Padding(
          padding: const EdgeInsets.fromLTRB(8, 4, 4, 8),
          child: Row(children: [
            Expanded(
              child: TextField(
                controller: _input,
                style: const TextStyle(color: Colors.white, fontSize: 12),
                onSubmitted: (_) => unawaited(_add()),
                decoration: InputDecoration(
                  isDense: true,
                  hintText: provider.t('float.memoHint'),
                  hintStyle:
                      const TextStyle(color: Colors.white24, fontSize: 11),
                  filled: true,
                  fillColor: Colors.white.withValues(alpha: 0.06),
                  border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(8),
                      borderSide: BorderSide.none),
                ),
              ),
            ),
            IconButton(
              tooltip: provider.t('float.memoAdd'),
              icon: const Icon(Icons.add_circle_rounded,
                  color: Color(0xFFFFB347), size: 20),
              onPressed: () => unawaited(_add()),
            ),
          ]),
        ),
      ]),
    );
  }
}
/// 処理中に投げられて、 順番を待っている指示。
class _McpPending {
  final String shown;
  final String raw;
  final List<AiInputImage>? images;
  const _McpPending({required this.shown, required this.raw, this.images});
}

class _McpChatMsg {
  final String role; // 'user' | 'ai' | 'tool'

  /// 画面に出す文 (人が読める言葉)。
  final String text;

  /// AI に渡す中身 (ツールの実際の戻り値)。 画面表示を人向けに変えても
  /// AI には本物を渡さないと、 結果が分からず同じ操作を繰り返してしまう。
  final String? raw;
  const _McpChatMsg(this.role, this.text, {this.raw});
}

/// AI アシスタントの会話と、 実行中のやり取りを持つ入れ物。
///
/// = ユーザー要望「処理の途中でストップできるようにして欲しい」「処理中に
///   チャット欄を閉じても処理が中断しないようにして欲しい」。
///   以前はダイアログの State がループを回していたので、 閉じた瞬間に
///   `mounted` が false になり、 途中のツール実行がそのまま捨てられていた。
///   会話とループを画面の外 (ここ) に移し、 画面は覗いて表示するだけに
///   する。 閉じても走り続け、 開き直せば続きが見える。
class _McpChatSession extends ChangeNotifier {
  _McpChatSession._();
  static final _McpChatSession instance = _McpChatSession._();

  final List<_McpChatMsg> _msgs = [];
  List<_McpChatMsg> get msgs => _msgs;

  /// この会話で書き換えたページ (最後にまとめて並べ直す)。
  final Set<String> _touchedPageIds = {};

  MindMapProvider? _provider;
  McpServer? _tools;
  MindMapProvider get provider => _provider!;

  bool _busy = false;
  bool get busy => _busy;

  /// 止めてほしいと言われたか (= ストップボタン)。
  bool _cancel = false;
  bool get canceling => _cancel;

  /// 今どこまで進んだか (画面に「n / 24 手目」 と出す)。
  int step = 0;
  static const int maxRounds = 24;

  /// この回の「お題」 (= 「AI で新規ページ作成」 から開いた時)。
  String? initialTask;

  /// 処理中に投げられた、 まだ渡していない指示 (= ユーザー要望: 走っている
  /// 間も次を打てるように)。 順番に処理する。
  final List<_McpPending> _queued = [];
  List<_McpPending> get queued => List<_McpPending>.unmodifiable(_queued);

  /// 割り込みで足した指示の数 (画面の表示用)。
  int _steeredCount = 0;
  int get steeredCount => _steeredCount;

  /// 指示を受け付ける。
  ///
  /// - 動いていなければそのまま始める。
  /// - 動いていて [steer] が true なら **今の作業に割り込む**。 会話へ足すので、
  ///   AI は次の手を考える時にその指示も読む (途中で方針を変えられる)。
  /// - 動いていて [steer] が false なら **順番待ち**。 今の作業が終わってから
  ///   自動で始める。
  void submit({
    required String shown,
    required String raw,
    List<AiInputImage>? images,
    bool steer = false,
  }) {
    if (!_busy) {
      unawaited(run(shown: shown, raw: raw, images: images));
      return;
    }
    if (steer) {
      // 走っているループは毎回 _msgs から文脈を作り直すので、 ここへ足せば
      // 次の手から効く。
      _msgs.add(_McpChatMsg('user', shown, raw: raw));
      _steeredCount++;
      notifyListeners();
      unawaited(provider.appendMcpChat('user', shown));
      return;
    }
    _queued.add(_McpPending(shown: shown, raw: raw, images: images));
    notifyListeners();
  }

  /// 順番待ちを 1 件取り消す。
  void cancelQueued(int index) {
    if (index < 0 || index >= _queued.length) return;
    _queued.removeAt(index);
    notifyListeners();
  }

  void clearQueued() {
    if (_queued.isEmpty) return;
    _queued.clear();
    notifyListeners();
  }

  void bind(MindMapProvider p) {
    if (identical(_provider, p) && _tools != null) return;
    _provider = p;
    _tools = McpServer(p);
  }

  void add(_McpChatMsg m) {
    _msgs.add(m);
    notifyListeners();
  }

  /// 会話の履歴を消す (= ユーザー要望: 「チャット履歴を clear にして」)。
  ///
  /// 走っている最中に頼まれた時は、 今のお願いだけ残して前を消す。
  /// そうしないと、 返事を書いている途中で足元の文脈が消えてしまう。
  void clearHistory() {
    if (_busy && _msgs.isNotEmpty) {
      final lastUser = _msgs.lastIndexWhere((m) => m.role == 'user');
      if (lastUser > 0) _msgs.removeRange(0, lastUser);
    } else {
      _msgs.clear();
    }
    _touchedPageIds.clear();
    notifyListeners();
  }

  /// 実行中の処理を止める。 走っている HTTP 応答そのものは取り消せないので、
  /// 「次の区切りで抜ける」 形にする (ツールの実行はそこで打ち切られる)。
  void stop() {
    if (!_busy || _cancel) return;
    _cancel = true;
    notifyListeners();
  }

  /// 1 回ぶんのやり取りを回す。 画面が閉じても走り続ける。
  Future<void> run({
    required String shown,
    required String raw,
    List<AiInputImage>? images,
  }) async {
    if (_busy || _provider == null) return;
    _busy = true;
    _cancel = false;
    // ページ削除の歯止めは「ひと続きの作業」 単位で掛ける。 新しい指示が
    // 来た = 利用者が改めて頼んだという事なので、 ここで外す
    // (消し過ぎを止めた後、 利用者が「はい消して」 と答えた時に続けられる)。
    provider.mcpResetDeleteBrake();
    var stopped = false;
    step = 0;
    _msgs.add(_McpChatMsg('user', shown, raw: raw));
    notifyListeners();
    unawaited(provider.appendMcpChat('user', shown));
    final photos = images ?? const <AiInputImage>[];
    try {
      // ── エージェントループ ──
      //   「ページを作って項目を n 個足して繋ぐ」 だけでも 10 回以上
      //   ツールを呼ぶので、 上限が小さいと途中で力尽きる。
      var repairNote = '';
      for (var round = 0; round < maxRounds; round++) {
        if (_cancel) break;
        step = round + 1;
        notifyListeners();
        final prompt =
            '${_systemPrompt()}\n\n${_historyText()}\n${repairNote}アシスタント:';
        // 写真は最初の 1 往復にだけ付ける (毎回付けると同じ画像の分だけ
        //   何度も課金されてしまう)。
        final reply = await provider.askAi(prompt,
            images: round == 0 && photos.isNotEmpty ? photos : null);
        if (_cancel) break;
        final call = _McpChatDialogState._parseToolCall(reply);
        final lastRound = round == maxRounds - 1;
        // ツール呼び出しのつもりが JSON として壊れていた時は書き直させる。
        if (call == null &&
            !lastRound &&
            _McpChatDialogState._looksLikeToolCall(reply)) {
          repairNote = provider.t('mcp.retryBrokenJson');
          continue;
        }
        repairNote = '';
        if (call == null || lastRound) {
          _tidyTouched();
          final answer = (call != null && lastRound)
              ? provider.t('mcp.tooManySteps')
              : stripToolEchoFromReply(reply);
          add(_McpChatMsg('ai', answer));
          unawaited(provider.appendMcpChat('ai', answer));
          await provider.refreshCreditBalance();
          add(_McpChatMsg('meta', aiRemainText(provider)));
          break;
        }
        final name = call['tool'] as String;
        final args =
            (call['args'] as Map?)?.cast<String, dynamic>() ?? const {};
        // ★ 並べ直すのは「ノードを増やした」 ページだけ (= 動作確認で判明:
        //   pageId を含むツール全部を対象にしていたため、 「このノードを
        //   x=-5000 へ動かして」 と頼まれてその通り動かしても、 応答の
        //   最後に自動整列が走って元の位置に戻っていた)。
        const kTidyAfter = {
          'add_node',
          'add_image_node',
          'add_table_node',
          'connect_nodes',
        };
        final touched = '${args['pageId'] ?? ''}'.trim();
        if (touched.isNotEmpty && kTidyAfter.contains(name)) {
          _touchedPageIds.add(touched);
        }
        add(_McpChatMsg('tool', _toolLabel(name, args), raw: ''));
        Map<String, dynamic> result;
        try {
          result = await _tools!.callTool(name, args);
        } catch (e) {
          result = {
            'content': [
              {'type': 'text', 'text': 'error: $e'}
            ],
            'isError': true,
          };
        }
        final resText = ((result['content'] as List?)?.isNotEmpty ?? false)
            ? ((result['content'] as List).first as Map)['text']?.toString() ??
                ''
            : '';
        // create_page は pageId を戻り値で返すので、 そこからも拾う。
        if (name == 'create_page') {
          try {
            final j = jsonDecode(resText);
            final pid = '${(j is Map ? j['pageId'] : '') ?? ''}'.trim();
            if (pid.isNotEmpty) _touchedPageIds.add(pid);
          } catch (_) {}
        }
        final ok = result['isError'] != true;
        add(_McpChatMsg(
            'tool',
            ok
                ? '  ${provider.t('mcp.done')}'
                : '  ${provider.t('mcp.failed')}: $resText',
            // ★ 読むための道具は切らない (= 動作確認で判明: 1200 文字で
            //   一律に切っていたため、 read_page は connections まで届かず
            //   「本当に繋がったか確かめて」 に答えられず、 read_app_doc は
            //   説明書の冒頭しか読めずに記憶で答えていた)。
            raw: '$name → ${_capToolResult(name, resText)}'));
      }
      if (_cancel) {
        stopped = true;
        // 止めた時も、 そこまでに作った物は並べ直しておく。
        _tidyTouched();
        add(_McpChatMsg('ai', provider.t('mcp.runStopped')));
        unawaited(provider.appendMcpChat('ai', provider.t('mcp.runStopped')));
      }
    } catch (e) {
      add(_McpChatMsg('ai', '⚠ $e'));
    } finally {
      _busy = false;
      _cancel = false;
      step = 0;
      _steeredCount = 0;
      notifyListeners();
      unawaited(provider.refreshCreditBalance());
      // ★ 順番待ちがあれば続けて始める (= ユーザー要望: 終わった後に投げる)。
      //   止められた時は待たせていた分も取り消す (続けたくないはずなので)。
      if (stopped) {
        _queued.clear();
        notifyListeners();
      } else if (_queued.isNotEmpty) {
        final next = _queued.removeAt(0);
        notifyListeners();
        // 直接呼ぶと finally の中で走り始めてしまうので 1 拍置く。
        Future<void>.microtask(() => run(
              shown: next.shown,
              raw: next.raw,
              images: next.images,
            ));
      }
    }
  }

  /// AI が決めた座標は当てにならず要素が離れて置かれてしまうので、
  /// 出来上がりをツリーとして並べ直す (= ユーザー要望)。
  void _tidyTouched() {
    if (_touchedPageIds.isEmpty) return;
    for (final pid in _touchedPageIds) {
      provider.mcpTidyPage(pid);
    }
    _touchedPageIds.clear();
  }

  String _systemPrompt() {
    final tools = jsonEncode(McpServer.toolDefs);
    final pages = jsonEncode(provider.mcpListPages());
    // ユーザーが書き置いた前提を最優先で守らせる (= ユーザー要望)。
    final pre = provider.mcpPreamble.trim();
    final preBlock = pre.isEmpty
        ? ''
        : '【利用者が決めた前提 — 他のどの指示よりも優先して守ること】\n'
            '$pre\n'
            '（ただしツールの使い方と返答形式のきまりは崩さないこと）\n\n';
    // ── アプリの説明書 (AGENTS.md) を既定で渡す (= ユーザー要望:
    //    skills / AGENTS.md のように既定で設定されているように) ──
    //    詳細は read_app_doc で必要な時だけ取り寄せさせる。
    final guide = provider.appAgentsGuide.trim();
    final guideBlock = guide.isEmpty
        ? ''
        : '【このアプリの説明書 (必ず踏まえること)】\n$guide\n\n';
    // ── この回のお題 (= ユーザー要望: + ボタンからの「AI で新規ページ作成」) ──
    //    説明書と同じ扱いで、 何をする回なのかを先に伝えておく。
    final taskBlock = initialTask == 'newPage'
        ? '【この回の仕事】\n'
            '利用者は「新しいページを AI に作ってほしい」 と思ってこの画面を開きました。\n'
            '・まず何のページを作るか (主題・種類) を短く 1 回だけ尋ねます。\n'
            '  ただし利用者が最初のメッセージで既に主題を書いていれば、 聞き返さずに作ります。\n'
            '・create_page で新しいページを作り、 その pageId を以降に使います。\n'
            '・種類は内容に合わせて選びます '
            '(考えを広げる = normal、 一覧・カード = bookshelf、 '
            '文章 = document (便箋型メモ帳)、 絵や自由な書き込み = paint、 '
            '動画 = videoEditor)。\n'
            '・normal なら主題ノードを 1 つ作り、 子を add_node の nodes に '
            'まとめて渡して parentIndex でつなぎます。\n'
            '・作り終えたら read_page で中身を確かめてから、 何を作ったかを普通の文章で伝えます。\n\n'
        : '';
    return '$preBlock$guideBlock$taskBlock'
        'あなたはマインドマップアプリ「Kamispec」を操作するアシスタントです。\n'
        '以下のツールを使ってページやノードを読み書きできます。\n'
        'ツール定義: $tools\n'
        '現在のページ一覧: $pages\n'
        'ツールを使う時は、 説明文を付けず次の JSON だけを 1 つ返してください:\n'
        '{"tool":"ツール名","args":{...}}\n'
        'ツールの結果を受け取ったら、 続けて必要なら次のツール JSON を、 '
        '完了したら短い説明文だけを返してください。\n'
        // ── 応答は必ず利用者の言語で、 人が読める文章にする
        //    (= ユーザー要望: 人間が分かる言葉で、 表示言語で返す) ──
        '【返答のきまり】${provider.languageInstructionForAi()}'
        '最後の説明文は、 JSON や識別子 (ID) をそのまま並べず、 何をどこに'
        '作ったかを普通の文章で伝えてください。 例:「新しいマップ『〇〇』を'
        '作り、 見出し 4 つとその下に 8 項目を並べました」。\n'
        // 座標は AI に決めさせない (= ユーザー要望: 要素が離れて変な位置に
        //   置かれるバグ)。 置いた後にアプリがツリーとして並べ直す。
        'ノードの位置 (x, y) は指定しないでください。 アプリが自動で'
        'きれいに並べます。'
        '★ 主題 (親) のノードは 1 つだけ作り、 同じ名前のノードを'
        '重ねて作らないでください。 create_page の戻り値の pageId を'
        'そのまま以降の pageId に使ってください。'
        '★ 最後の説明文を書く前に read_page で実際の中身を確認し、'
        '本当に作られた物だけを説明してください '
        '(やっていないことを「しました」 と書かない)。'
        '★ 作ったノードは必ず connect_nodes で親ノードにつないでください。'
        // = ユーザー報告: id の書き写しに失敗して接続できなかった。
        '線を引く時は id を調べ直さず、 画面に出ているノードの題名を '
        'そのまま from / to に書いてください '
        '(例: {"tool":"connect_nodes","args":{"pageId":"…",'
        '"connections":[{"from":"春","to":"夏",'
        '"label":"次の季節へ"}]}})。 '
        '同じ組を 2 度繋いでもラベルが上書きされるだけなので、 '
        '失敗したと思ったら題名で繋ぎ直して構いません。'
        'つながっていないノードは「根」 として扱われ、 バラバラの位置に'
        '並んでしまいます。 まず親 (主題) を 1 つ作り、 その下に子を'
        'ぶら下げる形にしてください。'
        // ── 表 / 図での出力 (= ユーザー要望) ──
        '比較・一覧・数値のように「表にした方が分かりやすい」 内容は '
        'add_table_node で表として出してください (rows は 2 次元配列で、 '
        '先頭行が見出しになります)。 '
        '関係や流れを示したい時は、 add_node で要素を作り connect_nodes で '
        'つないで図にしてください。 画像は add_image_node が使えます。 '
        '子ノードの数など生成量はユーザーの指示に従ってください '
        '(指定が無ければ 5 個程度)。 '
        // ── リンクは url 欄で渡す (= ユーザー報告: YouTube リンクを頼んだら
        //    メモ本文に生の URL が書かれ、 押せない形で出てきた) ──
        '★ リンクは必ず add_node の "url" 欄に入れてください。 '
        'メモ本文に URL を書くとただの文字になってしまいます。 '
        '"url" に入れると押せるリンクになり、 YouTube の**動画**の URL '
        '(https://www.youtube.com/watch?v=動画ID または https://youtu.be/動画ID) '
        'ならサムネイル付きの動画ノードになってアプリ内で再生できます。 '
        '検索結果の URL (/results?search_query=…) は動画ではないので、 '
        '動画が分かる時は必ず watch の URL を渡してください。 '
        '"memo" と "url" は同じノードに一緒に指定できます。 '
        // ── ページの種類ごとに使うツールが違う (= ユーザー要望: フリーノート /
        //    ギャラリー / 動画エディターも操作できるように) ──
        // アプリの機能そのものを開いてほしい時 (= ユーザー要望)。
        '★「背景を夜空にして」「壁紙を変えて」 のような指示には '
        'generate_page_background を使い、 **AI で絵を描き起こして**背景に '
        'してください (prompt に、 何を・どんな色で・どんな雰囲気で描くかを '
        '具体的に書く。 英語の方がうまく描けます)。 出来合いの物から選ぶ '
        'のではなく、 その場で作るのが既定のやり方です。 '
        '画像 1 枚分のクレジットを使います。 '
        '既にある画像を指定したい / 背景を外したい時だけ '
        'set_page_background を使ってください。\n'
        '★「フラッシュカードを開いて」「無音カメラを起動して」 のように '
        'アプリの機能を使いたい指示には、 ページを作らず '
        'run_app_command でその機能を開いてください '
        '(id が分からなければ先に list_app_commands)。 '
        '起動を頼まれたら、 確認を挟まずそのまま開いてください。\n'
        // ── どのページの話かを取り違えない (= ユーザー報告: 「このページ
        //    消して」 と頼んだのに、 一覧を上から順に消していき最後の 1 枚
        //    しか残らなかった) ──
        '★「このページ」「今開いているページ」 は、 list_pages の '
        'isCurrent が true の 1 枚を指します。 名前から当てずっぽうで '
        '選ばず、 消す前・種類を変える前に list_pages で確かめてください。 '
        'pageId や nodeId は list_pages / read_page が返した物だけを使い、 '
        'それらしい id を自分で組み立てないでください。\n'
        '★ 消す・入れ替える範囲は頼まれた分だけにしてください。 '
        '1 枚と言われたら 1 枚です。 delete_page が失敗しても別の id で '
        '試し直したり、 一覧を順に消していったりしないでください。\n'
        // ── 確認の要る / 要らないの線引き (= 過剰な確認も、 勝手な削除も
        //    どちらも困る) ──
        '★ 対象が 1 つに決まる頼まれ方 (「『メモ2』消して」 等) なら、 '
        '確認を重ねずそのまま実行してください。 逆に、 同じ名前のページが '
        '複数ある・「いらなそうなの見繕って」 のように対象が決まらない時は、 '
        '候補を挙げて了解を得るまで消さないでください。 '
        'ノードを題名の一部で消す時も、 当てはまった題名を全部挙げてから '
        '消してください (関係ない物まで巻き込みます)。 '
        '同じ文の中で取り消された指示 (「やっぱりいい」) は実行せず、 '
        '中止した事をはっきり答えてください。\n'
        '★ 消したページを戻す道具はありません。 アプリ側で直前に消した '
        '1 枚だけ Ctrl+Z (元に戻す) で復元できます。 それ以前の物は '
        '戻せないので、 無い機能をでっち上げないでください。\n'
        '★ ページの種類を変えてもノードは消えません。 '
        'delete_page と create_page で作り直さないでください。 '
        'フリーノートや便箋の中身もページ本体とは別に保存されているので、 '
        '種類を戻せばまた出てきます '
        '(クラウド同期が運ぶのはフリーノートの中身だけです)。\n'
        // ── 利用者本人しか始められない事 (= 勝手に実行しない / 嘘をつかない)
        '★ クラウド同期・アプリロック・集中ロックは利用者本人しか '
        '始められません。 頼まれたら理由を添えて断り、 自分で押す手順を '
        '案内してください (「掛けました」 と答えない)。 '
        'プラン変更や購入を代行する手段はありません '
        '(subscriptionManager で管理画面を開く案内までです)。 '
        'LAN 共有は廃止された機能で、 共有 URL を作る手段もないので '
        'URL をでっち上げないでください。\n'
        '★ ボタンを置けるのはヘッダー (上のバー) だけです。 '
        '「下のバーに移して」 と頼まれたら、 移せない事を伝えて '
        'ボタン設定画面の手順を案内してください。 '
        'set_header_buttons の戻り値の ignored (そんな機能は無い) と '
        'blocked (利用者しか使えない) に入った id は置かれていないので、 '
        '付けたと答えないでください。\n'
        '★「Excel で作って」「スライドにして」「PDF にして」 のように '
        'ファイルが欲しい指示には create_document_file を使ってください。 '
        '表は rows、 文章は paragraphs、 スライドは slides に入れます。 '
        '出来たファイルはページに貼られ、 押せばアプリ内で開けます。\n'
        '★ 同じツールを何度も呼ばないでください。 複数まとめて置けるツール '
        '(add_gallery_item / add_paint_text / append_document_text) は '
        'texts に全部入れて 1 回で呼びます。 '
        'マインドマップも add_node の nodes に全部入れて 1 回で作ります '
        '(各要素の parentIndex にこの配列内の親の番号 (0 始まり) を書けば '
        '線も同時に引かれます)。 connect_nodes も connections でまとめられます。\n'
        '★ ツールの戻り値は「ツール実行結果:」 の行に入っています。 '
        'そこに結果が出ていれば成功しているので、 '
        '「結果を確認できない」 と言って途中でやめないでください。\n'
        // = ユーザー要望: ツールの戻り値を応答に出さない。
        '★ 最後の返事に、 ツールの戻り値 (JSON) や「ツール実行結果:」 の '
        '行をそのまま貼り付けないでください。 何をどうしたかを、 '
        '普通の文章だけで短く答えてください。\n'
        '★ ページの種類 (list_pages の type) で使うツールを変えてください: '
        'normal (マインドマップ) = add_node / connect_nodes / add_table_node、 '
        'bookshelf (ギャラリー) = add_gallery_item (add_node は使わない。 '
        '座標も渡さない。 棚に自動で並びます)、 '
        'paint (フリーノート) = add_paint_text、 '
        'document (便箋型メモ帳) = append_document_text (段落ごとに呼ぶ)、 '
        'markdown (Markdown / 図) = append_document_text、 '
        'videoEditor (動画エディター) = add_video_editor_item。 '
        'ページの種類はこの 6 つだけです。 一覧に無い種類 (例:「AI '
        'スタジオのページ」) を頼まれたら、 近い種類で黙って代用せず、 '
        '無い事を伝えてから近い手段を勧めてください。 '
        '※ Web 検索の手段は持っていないので、 事実はあなたの知識から答え、 '
        '不確かな点はその旨を明記してください。'
        '(アプリの表示言語: ${provider.appLanguage})';
  }

  String _historyText() {
    final b = StringBuffer();
    for (final m in _msgs) {
      switch (m.role) {
        case 'user':
          // 添付の中身は raw 側に入っている。
          b.writeln('ユーザー: ${m.raw ?? m.text}');
          break;
        case 'tool':
          // 画面用の要約ではなく、 実際の戻り値を渡す。
          // 呼び出しの見出し行は raw が空なので渡さない。 渡すと
          // 「ツール実行結果: 」 だけの行が並び、 AI が 「結果を確認できない」
          // と誤解して途中で諦めてしまう (= 実際に起きた不具合)。
          final raw = m.raw;
          if (raw == null || raw.trim().isEmpty) break;
          b.writeln('ツール実行結果: $raw');
          break;
        case 'meta':
          // 残りトークンの表示はアプリが出している行なので AI には渡さない。
          break;
        default:
          b.writeln('アシスタント: ${m.text}');
      }
    }
    return b.toString();
  }

  /// ツールの戻り値を AI に渡す時の長さの上限。
  ///
  /// 書き込み系は「出来た / 出来なかった」 が分かれば十分なので短くて良いが、
  /// **読むための道具**を途中で切ると、 AI は中身を見ないまま答える事に
  /// なる (= 動作確認で判明: 5 ノードのページでも read_page の JSON は
  /// 3000 文字を超え、 1200 文字では connections まで届かない)。
  static String _capToolResult(String name, String text) {
    const caps = {
      'read_app_doc': 20000,
      'read_page': 8000,
      'text_file_read': 8000,
      'list_pages': 4000,
      'list_app_commands': 4000,
    };
    final cap = caps[name] ?? 1200;
    return text.length > cap ? '${text.substring(0, cap)}…' : text;
  }

  String _toolLabel(String name, Map<String, dynamic> args) {
    String a(String k) => '${args[k] ?? ''}'.trim();
    switch (name) {
      case 'list_pages':
        return provider.t('mcp.actListPages');
      case 'read_page':
        return provider.t('mcp.actReadPage');
      case 'create_page':
        return provider
            .t('mcp.actCreatePage')
            .replaceFirst('{name}', a('name').isEmpty ? '-' : a('name'));
      case 'add_node':
        {
          // まとめて置く形では title が無いので、 代わりに名前を並べる
          // (そのままだと 「ノード「」 を置く」 と出てしまう)。
          final batch = args['nodes'];
          if (batch is List && batch.isNotEmpty) {
            final names = <String>[];
            for (final e in batch) {
              if (e is Map) {
                final t = '${e['title'] ?? ''}'.trim();
                if (t.isNotEmpty) names.add(t);
              }
            }
            final shown = names.length <= 6
                ? names.join('・')
                : '${names.take(6).join('・')}…';
            return provider.t('mcp.actAddNode').replaceFirst(
                '{title}', shown.isEmpty ? '${batch.length}' : shown);
          }
          return provider
              .t('mcp.actAddNode')
              .replaceFirst('{title}', a('title'));
        }
      case 'update_node':
        return provider.t('mcp.actUpdateNode');
      case 'delete_node':
        return provider.t('mcp.actDeleteNode');
      case 'connect_nodes':
        return provider.t('mcp.actConnect');
      case 'add_image_node':
        return provider.t('mcp.actAddImage');
      case 'add_table_node':
        return provider.t('mcp.actAddTable');
      case 'add_gallery_item':
        return provider.t('mcp.actAddGallery');
      case 'add_paint_text':
        return provider.t('mcp.actPaintText');
      case 'append_document_text':
        return provider.t('mcp.actDocText');
      case 'add_video_editor_item':
        return provider.t('mcp.actVideoItem');
      case 'create_document_file':
        return provider.t('mcp.actCreateFile').replaceFirst(
            '{name}',
            a('fileName').isNotEmpty
                ? a('fileName')
                : '${a('kind').toUpperCase()} ファイル');
      case 'list_app_commands':
        return provider.t('mcp.actListCommands');
      case 'run_app_command':
        {
          // id より、 利用者が知っている機能名で見せる。
          final id = a('id');
          final hit = provider.mcpCommands
              .firstWhere((c) => c['id'] == id, orElse: () => const {});
          return provider
              .t('mcp.actRunCommand')
              .replaceFirst('{name}', hit['label'] ?? id);
        }
      default:
        return name;
    }
  }
}

class _McpChatDialog extends StatefulWidget {
  final MindMapProvider provider;

  /// AI 設定を開く (= ユーザー要望: APIキーが未設定なら、 プロンプトを打つ
  /// 前に設定画面を出す)。
  final VoidCallback? onOpenAiSettings;

  /// 添付ファイルを文字に直す (= ユーザー要望: 文書もチャットに投げたい)。
  /// 画面側の `_extractAttachmentTextForAi` を渡す。
  final Future<String?> Function(String path, String ext)? extractFileText;

  /// この回の「お題」 (= ユーザー要望: + ボタンから「AI で新規ページ作成」)。
  /// 'newPage' を渡すと、 新規ページを作る前提を AGENTS.md と同じ扱いで
  /// システム側に添える。
  final String? initialTask;

  /// ブラウザ版 AI を開く (= ユーザー要望: 右上のアシスタントからも呼べる
  /// ように)。 画面側が「開き方」 の設定に従って開く。
  final void Function(String url)? onOpenBrowserAi;

  /// この画面を浮遊窓で開き直す (= ユーザー要望: フローティング機能)。
  final VoidCallback? onFloatRequest;

  /// 既に浮遊窓の中で開いているか (= その時は浮かせるボタンを出さない)。
  final bool floatingPanel;

  /// 分割ペインの中に埋め込んで使うか (= ユーザー要望: AI アシスタントの
  /// 画面自体を左右分割でも出せるように)。 true の時は Dialog で包まず、
  /// ペインいっぱいに広げる。 [onClosePane] が閉じる口。
  final bool paneMode;
  final VoidCallback? onClosePane;
  const _McpChatDialog(
      {required this.provider,
      this.onOpenAiSettings,
      this.extractFileText,
      this.initialTask,
      this.onOpenBrowserAi,
      this.onFloatRequest,
      this.floatingPanel = false,
      this.paneMode = false,
      this.onClosePane});
  @override
  State<_McpChatDialog> createState() => _McpChatDialogState();
}

class _McpChatDialogState extends State<_McpChatDialog> {
  // 会話と実行中のループは画面の外 (_McpChatSession) が持つ。
  //   = ユーザー要望: チャット欄を閉じても処理が続くように。
  final _McpChatSession _session = _McpChatSession.instance;
  List<_McpChatMsg> get _msgs => _session.msgs;
  bool get _busy => _session.busy;
  final TextEditingController _input = TextEditingController();
  final ScrollController _scroll = ScrollController();

  /// 添付したファイル (名前 → 取り出した文字)。
  final List<({String name, String text})> _attachments = [];

  /// 一緒に見せる写真 (= ユーザー要望: カメラで撮った画像を LLM に渡す)。
  /// 文字に直せないので、 そのまま画像として AI へ送る。
  final List<AiInputImage> _images = [];

  /// カメラボタンを出すか (= ユーザー要望はモバイル版)。
  static bool get _cameraAvailable =>
      !kIsWeb && (Platform.isAndroid || Platform.isIOS);

  /// 説明パネルを一時的に開いているか (ヘッダーの ⓘ で切り替え)。
  bool _showMcpInfo = false;

  MindMapProvider get provider => widget.provider;

  /// セッションが動いたら描き直す (閉じている間に進んだぶんも見える)。
  void _onSessionChanged() {
    if (!mounted) return;
    setState(() {});
    _scrollToEnd();
  }

  @override
  void initState() {
    super.initState();
    _session.bind(provider);
    _session.initialTask = widget.initialTask;
    _session.addListener(_onSessionChanged);
    unawaited(provider.loadMcpInfoDismissed());
    unawaited(provider.loadMcpPreamble());
    unawaited(provider.loadMcpModelBarHidden());
    // アプリの説明書を読み込んでおく (= 既定で AI へ渡す。 ユーザー要望)。
    unawaited(provider.loadAppAgentsGuide().then((_) {
      if (mounted) setState(() {});
    }));
    // 使えるモデルと残高を取り直す (= ユーザー要望: モデル切替と残量表示)。
    unawaited(provider.refreshRelayModels());
    unawaited(provider.refreshCreditBalance());
    // 前回までのやり取りを読み直す (= ユーザー要望: 履歴を閲覧できるように)。
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      await provider.loadMcpChatHistory();
      if (!mounted) return;
      final saved = provider.mcpChatHistory;
      if (saved.isNotEmpty && _msgs.isEmpty) {
        setState(() {
          for (final e in saved) {
            _msgs.add(_McpChatMsg('${e['role']}', '${e['text']}'));
          }
        });
      }
      // ── 「AI で新規ページ作成」 で開いた時は、 何をする画面かを
      //    最初に 1 行出す (= ユーザー要望) ──
      if (widget.initialTask == 'newPage' && mounted) {
        setState(() => _msgs
            .add(_McpChatMsg('ai', provider.t('drawer.aiNewPageGreeting'))));
      }
      _scrollToEnd();
    });
    // キーが無いまま入力させても必ず失敗するので、 開いた時点で設定へ促す
    // (= ユーザー要望: プロンプトを打つより前に設定画面が出るように)。
    // ただし起動直後は「アプリ側キー (代行) が使えるか」 の確認が終わって
    // いないことがある。 まだ未確認なら確認を待ってから判断する
    // (= 待たないと、 チャージ済みでも設定画面が開いてしまう)。
    if (!provider.hasActiveAiKey) {
      WidgetsBinding.instance.addPostFrameCallback((_) async {
        if (provider.relayAvailable == null) {
          await provider.probeAiRelay();
        }
        if (!mounted || provider.hasActiveAiKey) return;
        _promptForAiKey();
      });
    }
  }

  /// AI 設定を開く。 閉じた後もキーが無ければ、 その旨だけ残す。
  void _promptForAiKey() {
    final open = widget.onOpenAiSettings;
    if (open == null) {
      setState(() => _msgs.add(_McpChatMsg('ai', provider.t('mcp.needKey'))));
      return;
    }
    open();
  }

  @override
  void dispose() {
    // ★ セッションは止めない (= ユーザー要望: 閉じても処理は続ける)。
    _session.removeListener(_onSessionChanged);
    _input.dispose();
    _scroll.dispose();
    super.dispose();
  }

  void _scrollToEnd() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_scroll.hasClients) {
        _scroll.jumpTo(_scroll.position.maxScrollExtent);
      }
    });
  }


  /// 直近の会話を AI へ渡すテキストに直列化する。

  /// 使うモデルを選ぶ (= ユーザー要望: モデルの種類を切り替えたい)。
  /// 一覧は代行サーバーが返す「実際に使えるモデル」 だけを出す。
  /// 画面に出すモデル名。 末尾の日付 (…-20251001) は分かりにくいので落とす
  /// (= ユーザー要望)。 実際に送る id は元のまま。
  String _modelLabel(String id) =>
      id.replaceAll(RegExp(r'-\d{8}$'), '');

  /// モデル名と残りトークンの行。 文字が気になる人は畳める (= ユーザー要望)。
  /// 畳んでも目のボタンだけは残るので、 いつでも戻せる。
  Widget _buildModelBar() {
    final hidden = provider.mcpModelBarHidden;
    return Padding(
      padding: const EdgeInsets.fromLTRB(8, 4, 10, 0),
      child: Row(children: [
        IconButton(
          tooltip:
              provider.t(hidden ? 'mcp.showModelBar' : 'mcp.hideModelBar'),
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 26, minHeight: 26),
          icon: Icon(
              hidden
                  ? Icons.visibility_off_outlined
                  : Icons.visibility_outlined,
              size: 15,
              color: Colors.white38),
          onPressed: () => provider.setMcpModelBarHidden(!hidden),
        ),
        if (!hidden) ...[
          const SizedBox(width: 2),
          const Icon(Icons.memory_rounded, size: 13, color: Colors.white38),
          const SizedBox(width: 6),
          _buildModelPicker(),
          const SizedBox(width: 6),
          // Spacer (= Expanded) と併用すると余った幅を半分ずつ分け合って
          // しまい、 残量表示が途中で切れていた (= ユーザー報告)。
          // 余りは全部こちらへ渡す。
          Expanded(
            child: Text(_remainText(),
                textAlign: TextAlign.right,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                    color: Color(0xFF9CCC65), fontSize: 10.5)),
          ),
        ],
      ]),
    );
  }

  Widget _buildModelPicker() {
    final models = [
      for (final m in provider.relayModels)
        if (m is Map && m['available'] == true) m
    ];
    final cur = provider.relayModel;
    if (models.isEmpty) {
      return Text(_modelLabel(cur),
          style: const TextStyle(color: Colors.white54, fontSize: 11));
    }
    // 保存されているモデルが一覧から消えている時は実際に切り替える。
    if (!models.any((m) => '${m['id']}' == cur)) {
      final first = '${models.first['id']}';
      WidgetsBinding.instance.addPostFrameCallback((_) async {
        if (!mounted) return;
        await provider.setRelayModel(first);
        if (mounted) setState(() {});
      });
    }

    const groups = [
      ('gemini', 'Gemini'),
      ('openai', 'ChatGPT'),
      ('anthropic', 'Claude'),
    ];
    return InkWell(
      borderRadius: BorderRadius.circular(6),
      onTap: () => _showModelSheet(models, groups),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 2),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          Text(_modelLabel(cur),
              style: const TextStyle(color: Colors.white70, fontSize: 11)),
          const Icon(Icons.arrow_drop_down_rounded,
              color: Colors.white38, size: 18),
        ]),
      ),
    );
  }

  /// モデル選択。 サービスを横に並べ、 その中のモデルを縦に並べる
  /// (= ユーザー要望: 縦長でスクロールが要るのを避ける)。
  /// モデル選択 (= ユーザー要望: AI を使う所はどこでも同じ画面にする)。
  /// 中身は共通の showAiModelDialog に寄せてある。
  Future<void> _showModelSheet(
      List models, List<(String, String)> groups) async {
    await showAiModelDialog(context, provider, onChanged: () {
      if (mounted) setState(() {});
    });
  }

  /// 残高と、 今のモデルで「あと何トークン使えるか」 の目安。
  String _remainText() => aiRemainText(provider);

  // ─── ↑ / ↓ で前に送った指示を呼び戻す (= ユーザー要望) ───────────────
  /// 今どこを見ているか。 -1 = 履歴を見ていない (書きかけの状態)。
  int _promptHistoryIndex = -1;

  /// 履歴に入る前に書きかけだった文 (一番下まで戻った時に返す)。
  String _promptDraft = '';

  /// 送信済みの指示 (古い順)。 この会話のユーザー発言から作る。
  List<String> get _sentPrompts => [
        for (final m in _msgs)
          if (m.role == 'user')
            ((m.raw ?? m.text).trim().isEmpty ? m.text : (m.raw ?? m.text))
      ].where((s) => s.trim().isNotEmpty).toList();

  /// [delta] = -1 で 1 つ前、 +1 で 1 つ後。 動かせたら true。
  bool _recallPrompt(int delta) {
    final list = _sentPrompts;
    if (list.isEmpty) return false;
    if (_promptHistoryIndex < 0) {
      if (delta > 0) return false; // 履歴を見ていない時の ↓ は何もしない
      _promptDraft = _input.text;
      _promptHistoryIndex = list.length - 1;
    } else {
      final next = _promptHistoryIndex + (delta < 0 ? -1 : 1);
      if (next < 0) return true; // 一番上で止める (これ以上は遡らない)
      if (next >= list.length) {
        // 一番下まで戻った → 書きかけの内容に戻す。
        _promptHistoryIndex = -1;
        _setInputText(_promptDraft);
        return true;
      }
      _promptHistoryIndex = next;
    }
    _setInputText(list[_promptHistoryIndex]);
    return true;
  }

  void _setInputText(String text) {
    _input.value = TextEditingValue(
      text: text,
      selection: TextSelection.collapsed(offset: text.length),
    );
    setState(() {});
  }

  /// 会話の一覧を出して切り替える (= ユーザー要望: セッションを分けて保存)。
  Future<void> _showSessionPicker() async {
    final list = provider.mcpSessions.reversed.toList();
    await showDialog<void>(
      context: context,
      builder: (dctx) => StatefulBuilder(builder: (dctx, setD) {
        // ── Ctrl / Shift でまとめて選んで消す (= ユーザー要望) ──
        //    Ctrl+クリック = 1 件ずつ足し引き、 Shift+クリック = 直前に触った
        //    行からここまでを一気に選択 (ファイル一覧と同じ操作)。 何も選んで
        //    いない時の素のクリックは今までどおり「その会話を開く」。
        final selecting = _sessionSel.isNotEmpty;
        void toggle(int i, String id) {
          setD(() {
            if (_sessionSel.contains(id)) {
              _sessionSel.remove(id);
            } else {
              _sessionSel.add(id);
            }
            _sessionAnchor = i;
          });
        }

        void selectRange(int i) {
          final from = _sessionAnchor < 0 ? i : _sessionAnchor;
          final lo = from < i ? from : i;
          final hi = from < i ? i : from;
          setD(() {
            for (var k = lo; k <= hi && k < list.length; k++) {
              _sessionSel.add('${list[k]['id']}');
            }
          });
        }

        Future<void> deleteMany(Iterable<String> ids) async {
          for (final id in ids.toList()) {
            await provider.deleteMcpSession(id);
          }
          _sessionSel.clear();
          _sessionAnchor = -1;
          if (!dctx.mounted) return;
          Navigator.of(dctx).pop();
          if (mounted) _reloadFromSession();
        }

        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Row(children: [
            Expanded(
              child: Text(
                  selecting
                      ? provider
                          .t('mcp.sessionsSelected')
                          .replaceFirst('{n}', '${_sessionSel.length}')
                      : provider.t('mcp.sessions'),
                  style: const TextStyle(color: Colors.white, fontSize: 15)),
            ),
            if (list.isNotEmpty)
              TextButton.icon(
                style: TextButton.styleFrom(
                    visualDensity: VisualDensity.compact,
                    foregroundColor: const Color(0xFFFF8A80)),
                icon: const Icon(Icons.delete_sweep_rounded, size: 16),
                label: Text(
                    selecting
                        ? provider.t('mcp.deleteSelected')
                        : provider.t('mcp.deleteAll'),
                    style: const TextStyle(fontSize: 11.5)),
                onPressed: () async {
                  final ids = selecting
                      ? _sessionSel.toList()
                      : [for (final e in list) '${e['id']}'];
                  if (!await _confirmDeleteSessions(ids.length)) return;
                  await deleteMany(ids);
                },
              ),
          ]),
          content: SizedBox(
            width: 380,
            child: list.isEmpty
                ? Text(provider.t('mcp.noSessions'),
                    style:
                        const TextStyle(color: Colors.white60, fontSize: 12))
                : ListView.builder(
                    shrinkWrap: true,
                    itemCount: list.length,
                    itemBuilder: (_, i) {
                      final e = list[i];
                      final id = '${e['id']}';
                      final title = '${e['title'] ?? ''}'.isEmpty
                          ? provider.t('mcp.untitled')
                          : '${e['title']}';
                      final n = (e['msgs'] as List?)?.length ?? 0;
                      final at = DateTime.fromMillisecondsSinceEpoch(
                          (e['at'] as num?)?.toInt() ?? 0);
                      final cur = id == provider.mcpCurrentSessionId;
                      final picked = _sessionSel.contains(id);
                      return ListTile(
                        dense: true,
                        selected: picked || cur,
                        selectedTileColor: picked
                            ? const Color(0xFF6C63FF).withValues(alpha: 0.18)
                            : const Color(0xFF43B97F).withValues(alpha: 0.10),
                        leading: Icon(
                            picked
                                ? Icons.check_circle_rounded
                                : (cur
                                    ? Icons.chat_bubble_rounded
                                    : Icons.chat_bubble_outline_rounded),
                            size: 16,
                            color: picked
                                ? const Color(0xFF8D86FF)
                                : (cur
                                    ? const Color(0xFF43B97F)
                                    : Colors.white38)),
                        title: Text(title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: Colors.white, fontSize: 12.5)),
                        subtitle: Text(
                            '${at.month}/${at.day} '
                            '${at.hour.toString().padLeft(2, '0')}:'
                            '${at.minute.toString().padLeft(2, '0')}  ・  $n',
                            style: const TextStyle(
                                color: Colors.white38, fontSize: 10.5)),
                        trailing: IconButton(
                          icon: const Icon(Icons.close_rounded,
                              size: 16, color: Colors.white30),
                          onPressed: () => deleteMany([id]),
                        ),
                        onTap: () async {
                          // Ctrl / Shift は「選ぶ」、 素のクリックは「開く」。
                          final keys = HardwareKeyboard.instance;
                          if (keys.isShiftPressed) {
                            selectRange(i);
                            return;
                          }
                          if (keys.isControlPressed ||
                              keys.isMetaPressed ||
                              selecting) {
                            toggle(i, id);
                            return;
                          }
                          await provider.switchMcpSession(id);
                          if (!dctx.mounted) return;
                          Navigator.of(dctx).pop();
                          if (mounted) _reloadFromSession();
                        },
                      );
                    },
                  ),
          ),
          actions: [
            if (selecting)
              TextButton(
                onPressed: () => setD(() {
                  _sessionSel.clear();
                  _sessionAnchor = -1;
                }),
                child: Text(provider.t('mcp.clearSelection'),
                    style: const TextStyle(color: Colors.white38)),
              ),
            TextButton(
              onPressed: () => Navigator.of(dctx).pop(),
              child: Text(provider.t('btn.close'),
                  style: const TextStyle(color: Colors.white60)),
            ),
          ],
        );
      }),
    ).whenComplete(() {
      _sessionSel.clear();
      _sessionAnchor = -1;
    });
  }

  /// 会話一覧で選んでいる id (Ctrl / Shift の複数選択)。
  final Set<String> _sessionSel = <String>{};

  /// Shift の範囲選択の起点 (-1 = まだ無い)。
  int _sessionAnchor = -1;

  /// まとめて消す前の確認。
  Future<bool> _confirmDeleteSessions(int n) async {
    if (n <= 0) return false;
    final ok = await showDialog<bool>(
      context: context,
      builder: (cctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(provider.t('mcp.deleteConfirmTitle'),
            style: const TextStyle(color: Colors.white, fontSize: 15)),
        content: Text(
            provider.t('mcp.deleteConfirmBody').replaceFirst('{n}', '$n'),
            style: const TextStyle(color: Colors.white70, fontSize: 13)),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(cctx).pop(false),
            child: Text(provider.t('btn.cancel'),
                style: const TextStyle(color: Colors.white54)),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFE53935),
                foregroundColor: Colors.white),
            onPressed: () => Navigator.of(cctx).pop(true),
            child: Text(provider.t('act.delete')),
          ),
        ],
      ),
    );
    return ok == true;
  }

  /// 選んだ会話の中身を画面に読み込み直す。
  void _reloadFromSession() {
    setState(() {
      _msgs
        ..clear()
        ..addAll([
          for (final e in provider.mcpChatHistory)
            _McpChatMsg('${e['role']}', '${e['text']}')
        ]);
      _attachments.clear();
    });
    _scrollToEnd();
  }

  /// ファイルを選んで中身を取り出し、 次の質問に添える。
  /// カメラで撮った写真をこの会話に添える (= ユーザー要望: モバイルの
  /// AI チャットにカメラボタンを付けて、 撮った画像を LLM に渡したい)。
  /// 写真は端末に残さず、 その場で base64 にして送信時にだけ使う。
  Future<void> _takePhoto() async {
    try {
      var status = await Permission.camera.status;
      if (!status.isGranted) status = await Permission.camera.request();
      if (!status.isGranted) {
        if (!mounted) return;
        setState(() => _msgs.add(
            _McpChatMsg('ai', provider.t('cam.permissionDenied'), raw: '')));
        if (status.isPermanentlyDenied) await openAppSettings();
        return;
      }
      if (!mounted) return;
      final path = await Navigator.of(context).push<String>(
        MaterialPageRoute<String>(
          fullscreenDialog: true,
          builder: (_) => const _SilentCameraPage(),
        ),
      );
      if (path == null || !mounted) return;
      final bytes = await File(path).readAsBytes();
      try {
        await File(path).delete(); // 一時ファイルは残さない
      } catch (_) {}
      if (!mounted) return;
      setState(() => _images.add(AiInputImage(
            mime: 'image/jpeg',
            base64: base64Encode(bytes),
            name: '${provider.t('ai.photoAttached')} ${_images.length + 1}',
          )));
    } catch (e) {
      if (!mounted) return;
      setState(() => _msgs.add(_McpChatMsg('ai', '⚠ $e', raw: '')));
    }
  }

  Future<void> _pickAttachment() async {
    try {
      final res = await FilePicker.platform.pickFiles(withData: false);
      final path = res?.files.single.path;
      if (path == null) return;
      final name = res!.files.single.name;
      final dot = name.lastIndexOf('.');
      final ext = dot >= 0 ? name.substring(dot + 1).toLowerCase() : '';
      // ── 画像は文字に直さず、 そのまま AI に見せる ──
      //   以前はここで「中身を取り出せませんでした」 になっていた
      //   (画像から文字は取り出せないため)。
      if (const {'jpg', 'jpeg', 'png', 'webp', 'gif', 'heic', 'heif'}
          .contains(ext)) {
        final bytes = await File(path).readAsBytes();
        if (!mounted) return;
        setState(() => _images.add(AiInputImage(
              mime: AiInputImage.mimeForExt(ext),
              base64: base64Encode(bytes),
              name: name,
            )));
        return;
      }
      final extract = widget.extractFileText;
      final text = extract == null ? null : await extract(path, ext);
      if (!mounted) return;
      if (text == null || text.trim().isEmpty) {
        setState(() => _msgs
            .add(_McpChatMsg('ai', provider.t('mcp.attachFailed'), raw: '')));
        _scrollToEnd();
        return;
      }
      setState(() => _attachments.add((name: name, text: text)));
    } catch (e) {
      if (!mounted) return;
      setState(() => _msgs.add(_McpChatMsg('ai', '⚠ $e', raw: '')));
    }
  }

  /// ツール呼び出しを人が読める一文にする (= ユーザー要望)。

