  /// 応答からツール呼び出し JSON を取り出す。
  ///
  /// モデルによって書き方が違う (Gemini は素の JSON、 Claude / GPT は
  /// 説明文 + ```json フェンスを混ぜてくる)。 昔は「応答全体が JSON か
  /// 全体がフェンス」 しか受け付けず、 説明文が付くと拾えないまま
  /// 「作成しました」 とだけ言って何も実行されない状態だった。
  /// そこで、 文中のどこにあっても最初の 1 件を拾う。
  // (テキストエディタの AI 編集からも使うので static にしてある)
  static Map<String, dynamic>? _parseToolCall(String reply) {
    Map<String, dynamic>? tryParse(String raw) {
      final t = raw.trim();
      if (!t.startsWith('{')) return null;
      try {
        final j = jsonDecode(t);
        if (j is Map<String, dynamic> && j['tool'] is String) return j;
      } catch (_) {}
      return null;
    }

    // ① ```json ... ``` の中身を順に試す (文中のどこにあっても良い)。
    final fence = RegExp(r'```(?:json)?\s*([\s\S]*?)```', multiLine: true);
    for (final m in fence.allMatches(reply)) {
      final hit = tryParse(m.group(1) ?? '');
      if (hit != null) return hit;
    }
    // ② フェンス無しで書かれた場合: 対応の取れた最初の { … } を探す。
    for (var i = 0; i < reply.length; i++) {
      if (reply[i] != '{') continue;
      var depth = 0;
      var inStr = false;
      var esc = false;
      for (var j = i; j < reply.length; j++) {
        final c = reply[j];
        if (inStr) {
          if (esc) {
            esc = false;
          } else if (c == r'\') {
            esc = true;
          } else if (c == '"') {
            inStr = false;
          }
          continue;
        }
        if (c == '"') {
          inStr = true;
        } else if (c == '{') {
          depth++;
        } else if (c == '}') {
          depth--;
          if (depth == 0) {
            final hit = tryParse(reply.substring(i, j + 1));
            if (hit != null) return hit;
            break; // この { からは取れない → 次の { を探す
          }
        }
      }
    }
    // ③ 途中で切れた JSON を閉じて読み直す。
    //    = ユーザー報告「新規ページは立ち上がるのに要素がページ内に生成
    //    されない」。 ノードを大量に足す呼び出しは出力が長く、 末尾が欠けて
    //    `{` `[` が開いたままになることがある。 そうなると①②で拾えず、
    //    壊れた JSON がそのまま画面に出て、 何も実行されなかった。
    //    閉じ括弧を補って「途中まで」 でも実行できるようにする
    //    (欠けた最後の 1 件は捨てる)。
    final head = RegExp(r'\{\s*"tool"').firstMatch(reply);
    if (head != null) {
      final repaired = _repairTruncatedJson(reply.substring(head.start));
      if (repaired != null) {
        final hit = tryParse(repaired);
        if (hit != null) return hit;
      }
    }
    return null;
  }

  /// 途中で切れた JSON を閉じて、 読める形に直す。 直せなければ null。
  ///
  /// 末尾から「要素の切れ目 (文字列の外のカンマ)」 まで少しずつ削りながら、
  /// 開いたままの `{` `[` を閉じて JSON として通るところを探す。
  static String? _repairTruncatedJson(String src) {
    // 末尾のコードフェンスや説明文は落とす。
    var body = src.replaceAll(RegExp(r'```[\s\S]*$'), '');
    // 「ここまでで切ってよい」 位置 (文字列の外のカンマ) を集めておく。
    final commas = <int>[];
    var inStr = false;
    var esc = false;
    for (var i = 0; i < body.length; i++) {
      final c = body[i];
      if (inStr) {
        if (esc) {
          esc = false;
        } else if (c == r'\') {
          esc = true;
        } else if (c == '"') {
          inStr = false;
        }
        continue;
      }
      if (c == '"') {
        inStr = true;
      } else if (c == ',') {
        commas.add(i);
      }
    }

    /// [text] の開いたままの括弧を閉じた文字列。 閉じられなければ null。
    String? close(String text) {
      final stack = <String>[];
      var s = false;
      var e = false;
      for (var i = 0; i < text.length; i++) {
        final c = text[i];
        if (s) {
          if (e) {
            e = false;
          } else if (c == r'\') {
            e = true;
          } else if (c == '"') {
            s = false;
          }
          continue;
        }
        if (c == '"') {
          s = true;
        } else if (c == '{') {
          stack.add('}');
        } else if (c == '[') {
          stack.add(']');
        } else if (c == '}' || c == ']') {
          if (stack.isEmpty) return null;
          stack.removeLast();
        }
      }
      if (stack.isEmpty && !s) return text; // 元々閉じている
      final b = StringBuffer(text);
      if (s) b.write('"'); // 文字列の途中で切れていた
      for (var i = stack.length - 1; i >= 0; i--) {
        b.write(stack[i]);
      }
      return b.toString();
    }

    // まずはそのまま閉じてみる。 駄目なら後ろのカンマから順に切り詰める。
    final candidates = <String>[
      body,
      for (var i = commas.length - 1; i >= 0 && i >= commas.length - 8; i--)
        body.substring(0, commas[i]),
    ];
    for (final c in candidates) {
      final closed = close(c);
      if (closed == null) continue;
      try {
        final j = jsonDecode(closed);
        if (j is Map<String, dynamic> && j['tool'] is String) return closed;
      } catch (_) {}
    }
    return null;
  }

  /// ツール呼び出しのつもりで書かれた返答か (= JSON として読めなくても)。
  static bool _looksLikeToolCall(String reply) =>
      reply.contains('"tool"') &&
      (reply.contains('"args"') || reply.trimLeft().startsWith('{'));

  /// 処理中に投げた時の扱い。 true = 割り込み (今の作業に口を挟む) /
  /// false = 順番待ち (終わってから始める)。
  ///
  /// ★ 設定 (歯車) の中へ移した (= ユーザー要望: 処理中の帯に切り替え札を
  ///   出しっぱなしにしないで欲しい)。 覚えておく所は provider。
  bool get _steerNext => widget.provider.mcpSteerNext;

  Future<void> _send() async {
    final text = _input.text.trim();
    // ── 「clear」 だけ打った時は、 その場で会話を消す (= ユーザー要望:
    //    確認も「はい」 も「消しました」 も出さずにそのまま消える)。 ──
    if (_images.isEmpty &&
        _attachments.isEmpty &&
        const {'clear', '/clear', 'クリア'}.contains(text.toLowerCase())) {
      _input.clear();
      _promptHistoryIndex = -1;
      _promptDraft = '';
      _session.bind(provider);
      _session.clearHistory();
      // 保存してある会話の記録も空にする (次に開いた時も消えたまま)。
      unawaited(provider.clearMcpChatHistory());
      if (mounted) setState(() {});
      return;
    }
    // 写真だけ送りたいこともある (= 「これ何？」 と撮っただけの時)。
    // ★ 処理中でも受け付ける (順番待ち / 割り込み)。
    if (text.isEmpty && _images.isEmpty) return;
    if (!provider.hasActiveAiKey) {
      // 打ってから気付くのではなく、 その場で設定を開く (= ユーザー要望)。
      _promptForAiKey();
      return;
    }
    _input.clear();
    // 送ったら履歴の位置は先頭 (= 書きかけ) に戻す (↑ を押すと今送った物から)。
    _promptHistoryIndex = -1;
    _promptDraft = '';
    // 添付があれば中身を質問に添える (= ユーザー要望: 文書も投げたい)。
    final attachNote = _attachments.isEmpty
        ? ''
        : _attachments
            .map((a) => '\n\n[添付ファイル: ${a.name}]\n${a.text}')
            .join();
    // 写真は文字にできないので、 画像として別に渡す。 会話の記録には
    //   「写真を付けた」 という事実だけ残す (次の往復で AI が混乱しない)。
    final photos = List<AiInputImage>.of(_images);
    final photoNote =
        photos.isEmpty ? '' : '\n\n[${photos.length} 枚の写真を添付]';
    final shown = [
      if (text.isNotEmpty) text,
      if (_attachments.isNotEmpty)
        '📎 ${_attachments.map((a) => a.name).join(', ')}',
      if (photos.isNotEmpty) '📷 ${photos.map((p) => p.name).join(', ')}',
    ].join('\n');
    setState(() {
      _attachments.clear();
      _images.clear();
    });
    _session.bind(provider);
    _session.initialTask = widget.initialTask;
    // ★ await しない。 画面を閉じてもセッション側で走り続ける
    //   (= ユーザー要望: 処理中にチャット欄を閉じても中断しない)。
    // 動いていなければそのまま始まり、 動いていれば順番待ちか割り込みになる。
    _session.submit(
      shown: shown,
      raw: '$text$attachNote$photoNote',
      images: photos.isEmpty ? null : photos,
      steer: _steerNext,
    );
    _scrollToEnd();
  }

  @override
  Widget build(BuildContext context) {
    // 外部公開をやめたので URL は使わない。
    // ペインに埋め込む時は Dialog で包まず、 与えられた場所いっぱいに広げる
    // (= ユーザー要望: 左右分割でも出せるように)。
    final pane = widget.paneMode;
    Widget wrap(Widget child) => pane
        ? Material(color: const Color(0xFF1A1A2E), child: child)
        : Dialog(
            backgroundColor: const Color(0xFF1A1A2E),
            insetPadding: const EdgeInsets.all(24),
            child: child,
          );
    return wrap(
      ConstrainedBox(
        constraints: BoxConstraints(
            maxWidth: pane ? double.infinity : 560,
            maxHeight: pane ? double.infinity : 640),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          // ── ヘッダー ──
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 10, 6, 4),
            child: Row(children: [
              const Icon(Icons.auto_awesome_rounded,
                  size: 18, color: Color(0xFF80CBC4)),
              const SizedBox(width: 8),
              Expanded(
                child: Text(provider.t('mcp.chatTitle'),
                    style: const TextStyle(
                        color: Colors.white,
                        fontSize: 14,
                        fontWeight: FontWeight.w700)),
              ),
              // (ブラウザ版 AI を開くボタンは削除 = ユーザー要望:
              //  AI アシスタントからはブラウザ版 AI を開けないように)
              // ── 浮かせるボタンは廃止 (= ユーザー要望: AI アシスタントは
              //    アプリの中でしか使わないのでフローティングは要らない)。
              //    外に出す窓の仕組みは残してあるが、 ここからは開かない。 ──
              // 説明をもう一度見る (= ユーザー要望: ヘッダーに ⓘ で置く)。
              IconButton(
                tooltip: provider.t('mcp.showInfo'),
                icon: Icon(Icons.info_outline_rounded,
                    color: _showMcpInfo || !provider.mcpInfoDismissed
                        ? const Color(0xFF80CBC4)
                        : Colors.white38,
                    size: 18),
                onPressed: () =>
                    setState(() => _showMcpInfo = !_showMcpInfo),
              ),
              // 前提条件 (= ユーザー要望: Markdown のように自分で書いて置ける)。
              IconButton(
                tooltip: provider.t('mcp.preamble'),
                icon: Icon(Icons.rule_rounded,
                    color: provider.mcpPreamble.trim().isEmpty
                        ? Colors.white54
                        : const Color(0xFF80CBC4),
                    size: 19),
                onPressed: _editPreamble,
              ),
              // 設定 (= ユーザー要望: 順番待ち / 割り込みはここで決める。
              //   処理中の帯には出さない)。
              PopupMenuButton<String>(
                tooltip: provider.t('mcp.assistantSettings'),
                color: const Color(0xFF23233A),
                icon: const Icon(Icons.tune_rounded,
                    color: Colors.white54, size: 19),
                onSelected: (v) {
                  if (v == 'queue') provider.setMcpSteerNext(false);
                  if (v == 'steer') provider.setMcpSteerNext(true);
                },
                itemBuilder: (_) => [
                  PopupMenuItem<String>(
                    enabled: false,
                    height: 30,
                    child: Text(provider.t('mcp.whenBusy'),
                        style: const TextStyle(
                            color: Colors.white38, fontSize: 11)),
                  ),
                  for (final e in const [
                    ['queue', 'mcp.modeQueue'],
                    ['steer', 'mcp.modeSteer'],
                  ])
                    PopupMenuItem<String>(
                      value: e[0],
                      height: 36,
                      child: Row(children: [
                        Icon(
                            (e[0] == 'steer') == provider.mcpSteerNext
                                ? Icons.radio_button_checked_rounded
                                : Icons.radio_button_off_rounded,
                            size: 15,
                            color: (e[0] == 'steer') == provider.mcpSteerNext
                                ? const Color(0xFF4FC3F7)
                                : Colors.white38),
                        const SizedBox(width: 8),
                        Text(provider.t(e[1]),
                            style: const TextStyle(
                                color: Colors.white, fontSize: 12.5)),
                      ]),
                    ),
                ],
              ),
              // 会話の一覧 (= ユーザー要望: セッションを分けて保存)。
              IconButton(
                tooltip: provider.t('mcp.sessions'),
                icon: const Icon(Icons.forum_outlined,
                    color: Colors.white54, size: 19),
                onPressed: _showSessionPicker,
              ),
              // 新しい会話を始める。
              IconButton(
                tooltip: provider.t('mcp.newSession'),
                icon: const Icon(Icons.add_comment_outlined,
                    color: Colors.white54, size: 19),
                onPressed: () async {
                  await provider.newMcpSession();
                  if (!mounted) return;
                  setState(() {
                    _msgs.clear();
                    _attachments.clear();
                  });
                },
              ),
              // 今の会話の中身を消す。
              IconButton(
                tooltip: provider.t('mcp.clearHistory'),
                icon: const Icon(Icons.delete_sweep_rounded,
                    color: Colors.white38, size: 19),
                onPressed: () async {
                  await provider.clearMcpChatHistory();
                  if (!mounted) return;
                  setState(_msgs.clear);
                },
              ),
              IconButton(
                tooltip: provider.t('btn.close'),
                icon:
                    const Icon(Icons.close_rounded, color: Colors.white70),
                // ペインの中では Navigator を閉じてはいけない
                //   (アプリ本体が pop されてしまう)。
                onPressed: () => widget.paneMode
                    ? widget.onClosePane?.call()
                    : Navigator.of(context).pop(),
              ),
            ]),
          ),
          const Divider(height: 1, color: Colors.white12),
          // ── MCP の説明 (= ユーザー要望: 初回だけ出し、 閉じたらヘッダーの
          //    ⓘ から見られるようにする) ──
          if (!provider.mcpInfoDismissed || _showMcpInfo)
            Container(
            width: double.infinity,
            margin: const EdgeInsets.fromLTRB(12, 10, 12, 0),
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              color: const Color(0xFF43B97F).withValues(alpha: 0.08),
              borderRadius: BorderRadius.circular(8),
              border: Border.all(
                  color: const Color(0xFF43B97F).withValues(alpha: 0.35)),
            ),
            child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              const Icon(Icons.info_outline_rounded,
                  color: Color(0xFF43B97F), size: 15),
              const SizedBox(width: 8),
              Expanded(
                child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(children: [
                        Expanded(
                          child: Text(provider.t('mcp.explain'),
                              style: const TextStyle(
                                  color: Colors.white70,
                                  fontSize: 11,
                                  height: 1.55)),
                        ),
                        // 閉じる (= 以後は自動で出さない)。
                        IconButton(
                          tooltip: provider.t('btn.close'),
                          padding: EdgeInsets.zero,
                          constraints: const BoxConstraints(
                              minWidth: 24, minHeight: 24),
                          icon: const Icon(Icons.close_rounded,
                              size: 14, color: Colors.white38),
                          onPressed: () async {
                            await provider.setMcpInfoDismissed(true);
                            if (mounted) setState(() => _showMcpInfo = false);
                          },
                        ),
                      ]),
                      // 外部アプリからの接続 UI は削除した
                      //   (= ユーザー要望)。 MCP はこのアプリの中だけで動く。
                      // 料金の説明 (= ユーザー要望: 説明欄に単価を書く)。
                      Padding(
                        padding: const EdgeInsets.only(top: 6),
                        child: Text(provider.t('mcp.priceInfo'),
                            style: const TextStyle(
                                color: Color(0xFF9CCC65),
                                fontSize: 10.5,
                                height: 1.5)),
                      ),
                      // できること一覧 (= ユーザー要望: 具体的に何ができるか)。
                      Theme(
                        data: Theme.of(context)
                            .copyWith(dividerColor: Colors.transparent),
                        child: ExpansionTile(
                          tilePadding: EdgeInsets.zero,
                          childrenPadding:
                              const EdgeInsets.only(bottom: 4, right: 4),
                          expandedCrossAxisAlignment:
                              CrossAxisAlignment.start,
                          iconColor: const Color(0xFF43B97F),
                          collapsedIconColor: const Color(0xFF43B97F),
                          title: Text(provider.t('mcp.canDoTitle'),
                              style: const TextStyle(
                                  color: Color(0xFF9CCC65),
                                  fontSize: 11,
                                  fontWeight: FontWeight.w700)),
                          children: [
                            Text(provider.t('mcp.canDoBody'),
                                style: const TextStyle(
                                    color: Colors.white60,
                                    fontSize: 10.5,
                                    height: 1.7)),
                          ],
                        ),
                      ),
                    ]),
              ),
            ]),
          ),
          // ── メッセージ一覧 ──
          Expanded(
            child: _msgs.isEmpty
                ? Center(
                    child: Padding(
                      padding: const EdgeInsets.all(24),
                      child: Text(provider.t('mcp.chatHint'),
                          textAlign: TextAlign.center,
                          style: const TextStyle(
                              color: Colors.white38, fontSize: 12)),
                    ),
                  )
                : ListView.builder(
                    controller: _scroll,
                    padding: const EdgeInsets.all(12),
                    itemCount: _msgs.length,
                    itemBuilder: (_, i) {
                      final m = _msgs[i];
                      // 残りトークンの案内行 (= ユーザー要望: 出力の後に出す)。
                      if (m.role == 'meta') {
                        return Padding(
                          padding: const EdgeInsets.only(top: 4, bottom: 10),
                          child: Text(m.text,
                              textAlign: TextAlign.right,
                              style: const TextStyle(
                                  color: Color(0xFF9CCC65), fontSize: 10.5)),
                        );
                      }
                      if (m.role == 'tool') {
                        return Padding(
                          padding: const EdgeInsets.symmetric(vertical: 3),
                          child: Text(m.text,
                              style: const TextStyle(
                                  color: Color(0xFF80CBC4), fontSize: 11)),
                        );
                      }
                      final isUser = m.role == 'user';
                      return Align(
                        alignment: isUser
                            ? Alignment.centerRight
                            : Alignment.centerLeft,
                        child: Container(
                          margin: const EdgeInsets.symmetric(vertical: 4),
                          padding: const EdgeInsets.symmetric(
                              horizontal: 12, vertical: 8),
                          constraints: const BoxConstraints(maxWidth: 420),
                          decoration: BoxDecoration(
                            color: isUser
                                ? const Color(0xFF6C63FF)
                                : const Color(0xFF2A2A3E),
                            borderRadius: BorderRadius.circular(12),
                          ),
                          child: SelectableText(m.text,
                              style: const TextStyle(
                                  color: Colors.white, fontSize: 13)),
                        ),
                      );
                    },
                  ),
          ),
          // 実行中の表示 + ストップ (= ユーザー要望: 途中で止められるように)。
          // ── 処理中でも次を投げられる (= ユーザー要望: キュー / 割り込み) ──
          // ★ 「順番待ち / 割り込み」 の切り替え札はここから外し、 設定
          //   (歯車) の中へ移した (= ユーザー要望: 処理中に常時出さないで
          //   欲しい)。 ここに残すのは待ち件数だけ。
          if (_busy && (_session.queued.isNotEmpty || _session.steeredCount > 0))
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 0, 12, 6),
              child: Row(children: [
                const Spacer(),
                if (_session.queued.isNotEmpty)
                  Tooltip(
                    message: provider.t('mcp.queuedClear'),
                    child: InkWell(
                      onTap: () => setState(_session.clearQueued),
                      borderRadius: BorderRadius.circular(6),
                      child: Padding(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 6, vertical: 2),
                        child: Text(
                            '${provider.t('mcp.queuedCount')
                                .replaceFirst('{n}', '${_session.queued.length}')}  ×',
                            style: const TextStyle(
                                color: Color(0xFF4FC3F7), fontSize: 11)),
                      ),
                    ),
                  ),
                if (_session.steeredCount > 0)
                  Padding(
                    padding: const EdgeInsets.only(left: 8),
                    child: Text(
                        provider.t('mcp.steeredCount').replaceFirst(
                            '{n}', '${_session.steeredCount}'),
                        style: const TextStyle(
                            color: Color(0xFFFFB347), fontSize: 11)),
                  ),
              ]),
            ),
          if (_busy)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 10),
              child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                const SizedBox(
                    width: 16,
                    height: 16,
                    child: CircularProgressIndicator(
                        strokeWidth: 2, color: Color(0xFF43B97F))),
                const SizedBox(width: 10),
                Text(
                    provider
                        .t('mcp.working')
                        .replaceFirst('{n}', '${_session.step}'),
                    style: const TextStyle(
                        color: Colors.white38, fontSize: 11)),
                const SizedBox(width: 10),
                TextButton.icon(
                  style: TextButton.styleFrom(
                    padding: const EdgeInsets.symmetric(horizontal: 10),
                    minimumSize: const Size(0, 28),
                    tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                    foregroundColor: const Color(0xFFE57373),
                  ),
                  icon: const Icon(Icons.stop_circle_outlined, size: 16),
                  label: Text(
                      provider.t(
                          _session.canceling ? 'mcp.stopping' : 'mcp.stop'),
                      style: const TextStyle(fontSize: 11.5)),
                  onPressed: _session.canceling ? null : _session.stop,
                ),
              ]),
            ),
          const Divider(height: 1, color: Colors.white12),
          // ── 添付したファイル (= ユーザー要望: 文書もチャットに投げたい) ──
          if (_attachments.isNotEmpty)
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 6, 12, 0),
              child: Wrap(
                spacing: 6,
                runSpacing: 4,
                children: [
                  for (var i = 0; i < _attachments.length; i++)
                    Chip(
                      backgroundColor: const Color(0xFF23233A),
                      side: const BorderSide(color: Color(0xFF3A3A55)),
                      avatar: const Icon(Icons.description_outlined,
                          size: 14, color: Color(0xFF80CBC4)),
                      label: Text(_attachments[i].name,
                          style: const TextStyle(
                              color: Colors.white70, fontSize: 10.5)),
                      onDeleted: () =>
                          setState(() => _attachments.removeAt(i)),
                      deleteIconColor: Colors.white38,
                      materialTapTargetSize:
                          MaterialTapTargetSize.shrinkWrap,
                      visualDensity: VisualDensity.compact,
                    ),
                ],
              ),
            ),
          // ── 添えた写真 (= ユーザー要望: カメラで撮った画像を AI に渡す) ──
          //    小さく実物を出す。 押すと外せる。
          if (_images.isNotEmpty)
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 6, 12, 0),
              child: Wrap(
                spacing: 6,
                runSpacing: 6,
                children: [
                  for (var i = 0; i < _images.length; i++)
                    Stack(children: [
                      ClipRRect(
                        borderRadius: BorderRadius.circular(6),
                        child: Image.memory(
                          base64Decode(_images[i].base64),
                          width: 56,
                          height: 56,
                          fit: BoxFit.cover,
                          gaplessPlayback: true,
                        ),
                      ),
                      Positioned(
                        right: 0,
                        top: 0,
                        child: InkWell(
                          onTap: () => setState(() => _images.removeAt(i)),
                          child: Container(
                            decoration: const BoxDecoration(
                              color: Colors.black54,
                              borderRadius:
                                  BorderRadius.only(bottomLeft: Radius.circular(6)),
                            ),
                            padding: const EdgeInsets.all(2),
                            child: const Icon(Icons.close_rounded,
                                size: 12, color: Colors.white70),
                          ),
                        ),
                      ),
                    ]),
                ],
              ),
            ),
          // ── 使うモデル と 残り (= ユーザー要望: モデル切替 / 残トークン。
          //    文字が気になる時は目のボタンで畳める) ──
          _buildModelBar(),
          // ── 入力欄 ──
          Padding(
            padding: const EdgeInsets.fromLTRB(10, 6, 6, 8),
            child: Row(children: [
              IconButton(
                padding: EdgeInsets.zero,
                constraints:
                    const BoxConstraints(minWidth: 34, minHeight: 34),
                tooltip: provider.t('mcp.attach'),
                icon: Icon(Icons.attach_file_rounded,
                    color: _busy ? Colors.white24 : Colors.white54, size: 20),
                onPressed: _busy ? null : _pickAttachment,
              ),
              // ── カメラ (= ユーザー要望: 撮った写真をそのまま AI へ) ──
              if (_cameraAvailable)
                IconButton(
                  padding: EdgeInsets.zero,
                  constraints:
                      const BoxConstraints(minWidth: 34, minHeight: 34),
                  tooltip: provider.t('mcp.camera'),
                  icon: Icon(Icons.photo_camera_rounded,
                      color: _busy ? Colors.white24 : Colors.white54,
                      size: 20),
                  onPressed: _busy ? null : _takePhoto,
                ),
              Expanded(
                // ── ↑ / ↓ で前に送った指示を呼び戻す (= ユーザー要望) ──
                //    端末のシェルと同じ感覚。 ↑ で 1 つ前、 ↓ で 1 つ後、
                //    一番下まで戻ると書きかけの内容に戻る。
                child: Focus(
                  onKeyEvent: (node, event) {
                    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
                      return KeyEventResult.ignored;
                    }
                    if (event.logicalKey == LogicalKeyboardKey.arrowUp) {
                      return _recallPrompt(-1)
                          ? KeyEventResult.handled
                          : KeyEventResult.ignored;
                    }
                    if (event.logicalKey == LogicalKeyboardKey.arrowDown) {
                      return _recallPrompt(1)
                          ? KeyEventResult.handled
                          : KeyEventResult.ignored;
                    }
                    return KeyEventResult.ignored;
                  },
                  child: TextField(
                    controller: _input,
                    // 処理中でも打てる (= ユーザー要望)。
                    enabled: true,
                    style:
                        const TextStyle(color: Colors.white, fontSize: 13),
                    decoration: InputDecoration(
                      hintText: provider.t('mcp.chatPlaceholder'),
                      hintStyle: const TextStyle(
                          color: Colors.white30, fontSize: 12),
                      filled: true,
                      fillColor: Colors.white.withValues(alpha: 0.06),
                      isDense: true,
                      border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(10),
                          borderSide: BorderSide.none),
                    ),
                    onSubmitted: (_) => _send(),
                  ),
                ),
              ),
              const SizedBox(width: 6),
              IconButton(
                icon: Icon(Icons.send_rounded,
                    color: false
                        ? Colors.white24
                        : const Color(0xFF43B97F)),
                onPressed: _send,
              ),
            ]),
          ),
        ]),
      ),
    );
  }
}

class _AppLockChoice {
  final String label;
  final Duration? duration;

  /// タスクを終わらせるまでロックする (= ユーザー要望: 時間ではなく
  /// タスクベースをメインに)。 true の時 [duration] は見ない。
  final bool taskMode;
  const _AppLockChoice(this.label, this.duration, {this.taskMode = false});
}

// ════════════════════════════════════════════════════════════════════════
//  フラッシュカード (= ユーザー要望: 表裏カード + AI 生成/採点 + フォルダー)
// ════════════════════════════════════════════════════════════════════════

class _FlashcardDialog extends StatefulWidget {
  const _FlashcardDialog();
  @override
  State<_FlashcardDialog> createState() => _FlashcardDialogState();
}

class _FlashcardDialogState extends State<_FlashcardDialog> {
  static const String _allId = '__all__';
  String? _folderId = _allId; // _allId = すべて, null = 未分類

  @override
  Widget build(BuildContext context) {
    final provider = context.watch<MindMapProvider>();
    final folders = provider.flashcardFolders;
    final cards = _folderId == _allId
        ? provider.flashcards
        : provider.flashcardsInFolder(_folderId);
    final viewport = MediaQuery.sizeOf(context);
    final largeDesktopLayout = viewport.width >= 800;
    return Dialog(
      backgroundColor: const Color(0xFF1A1A2E),
      insetPadding: const EdgeInsets.all(24),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: SizedBox(
        width: largeDesktopLayout ? math.min(760.0, viewport.width - 48) : 560,
        height:
            largeDesktopLayout ? math.min(720.0, viewport.height - 48) : 640,
        child: Column(children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 12, 8, 8),
            child: Row(children: [
              const Icon(Icons.style_rounded,
                  color: Color(0xFF26C6DA), size: 22),
              const SizedBox(width: 10),
              Expanded(
                child: Text(context.read<MindMapProvider>().t('flash.title'),
                    style: TextStyle(
                        color: Colors.white,
                        fontSize: 17,
                        fontWeight: FontWeight.w700)),
              ),
              if (cards.isNotEmpty)
                TextButton.icon(
                  onPressed: () => _study(provider, cards, 0),
                  icon: const Icon(Icons.play_arrow_rounded,
                      color: Color(0xFF43B97F), size: 20),
                  label: Text(context.read<MindMapProvider>().t('flash.study'),
                      style: TextStyle(color: Color(0xFF43B97F))),
                ),
              IconButton(
                onPressed: () => Navigator.pop(context),
                icon: const Icon(Icons.close, color: Colors.white70),
              ),
            ]),
          ),
          SizedBox(
            height: 46,
            child: ListView(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(horizontal: 12),
              children: [
                _folderChip('すべて', _allId),
                _folderChip('未分類', null),
                for (final f in folders)
                  _folderChip(f.name.isEmpty ? '(無題)' : f.name, f.id,
                      folderId: f.id),
                Padding(
                  padding: const EdgeInsets.only(left: 4, top: 5),
                  child: ActionChip(
                    backgroundColor: const Color(0xFF2A2A3E),
                    avatar: const Icon(Icons.create_new_folder_rounded,
                        color: Colors.white70, size: 16),
                    label: Text(
                        context.read<MindMapProvider>().t('folder.title'),
                        style: TextStyle(color: Colors.white70, fontSize: 12)),
                    onPressed: () => _addFolder(provider),
                  ),
                ),
              ],
            ),
          ),
          const Divider(color: Colors.white12, height: 1),
          Expanded(
            child: cards.isEmpty
                ? Center(
                    child: Text(
                        context.read<MindMapProvider>().t('flash.noMemos'),
                        style: TextStyle(color: Colors.white38, fontSize: 13)),
                  )
                : ListView.builder(
                    padding: const EdgeInsets.all(12),
                    itemCount: cards.length,
                    itemBuilder: (_, i) => _cardTile(provider, cards[i],
                        large: largeDesktopLayout),
                  ),
          ),
          Padding(
            padding: const EdgeInsets.all(12),
            child: SizedBox(
              width: double.infinity,
              child: ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF26C6DA),
                    foregroundColor: Colors.black87),
                onPressed: () => _editCard(provider, null),
                icon: const Icon(Icons.add_rounded),
                label: Text(context.read<MindMapProvider>().t('flash.addCard')),
              ),
            ),
          ),
        ]),
      ),
    );
  }

  Widget _folderChip(String label, String? id, {String? folderId}) {
    final sel = _folderId == id;
    return Padding(
      padding: const EdgeInsets.only(right: 6, top: 5),
      child: GestureDetector(
        onLongPress: folderId != null
            ? () => _folderMenu(context.read<MindMapProvider>(), folderId)
            : null,
        child: ChoiceChip(
          label: Text(label,
              style: TextStyle(
                  color: sel ? Colors.black87 : Colors.white70, fontSize: 12)),
          selected: sel,
          selectedColor: const Color(0xFF26C6DA),
          backgroundColor: const Color(0xFF2A2A3E),
          onSelected: (_) => setState(() => _folderId = id),
        ),
      ),
    );
  }

  Widget _cardTile(MindMapProvider provider, Flashcard c,
      {bool large = false}) {
    return Card(
      color: const Color(0xFF24243A),
      margin: EdgeInsets.only(bottom: large ? 12 : 8),
      child: ListTile(
        contentPadding: large
            ? const EdgeInsets.symmetric(horizontal: 20, vertical: 8)
            : null,
        title: Text(c.front.isEmpty ? '(表が空です)' : c.front,
            style: TextStyle(color: Colors.white, fontSize: large ? 16 : 14),
            maxLines: large ? 3 : 2,
            overflow: TextOverflow.ellipsis),
        subtitle: Text(c.back.isEmpty ? '裏: (未設定)' : '裏: ${c.back}',
            style: TextStyle(
                color: c.back.isEmpty ? Colors.white38 : Colors.white54,
                fontSize: large ? 14 : 12),
            maxLines: large ? 2 : 1,
            overflow: TextOverflow.ellipsis),
        onTap: () => _study(provider, [c], 0),
        trailing: PopupMenuButton<String>(
          icon: const Icon(Icons.more_vert, color: Colors.white54),
          color: const Color(0xFF1E1E32),
          onSelected: (v) {
            if (v == 'edit') {
              _editCard(provider, c);
            } else if (v == 'delete') {
              provider.deleteFlashcard(c.id);
            } else if (v == 'move') {
              _moveCard(provider, c);
            }
          },
          itemBuilder: (_) => [
            PopupMenuItem(
                value: 'edit',
                child: Text(context.read<MindMapProvider>().t('btn.edit'),
                    style: const TextStyle(color: Colors.white))),
            PopupMenuItem(
                value: 'move',
                child: Text(
                    context.read<MindMapProvider>().t('flash.moveFolder'),
                    style: const TextStyle(color: Colors.white))),
            PopupMenuItem(
                value: 'delete',
                child: Text(context.read<MindMapProvider>().t('btn.delete'),
                    style: const TextStyle(color: Color(0xFFFF6B6B)))),
          ],
        ),
      ),
    );
  }

  Future<void> _editCard(MindMapProvider provider, Flashcard? card) async {
    await showDialog<void>(
      context: context,
      builder: (_) => _FlashcardEditDialog(
        card: card,
        defaultFolderId: _folderId == _allId ? null : _folderId,
      ),
    );
  }

  void _study(MindMapProvider provider, List<Flashcard> cards, int start) {
    if (cards.isEmpty) return;
    showDialog<void>(
      context: context,
      builder: (_) =>
          _FlashcardStudyDialog(cards: List.of(cards), start: start),
    );
  }

  Future<void> _addFolder(MindMapProvider provider) async {
    final ctrl = TextEditingController();
    final name = await showDialog<String>(
      context: context,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(context.read<MindMapProvider>().t('flash.addFolder'),
            style: TextStyle(color: Colors.white, fontSize: 16)),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white),
          decoration: InputDecoration(
              hintText: context.read<MindMapProvider>().t('folder.nameLabel'),
              hintStyle: const TextStyle(color: Colors.white38)),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dctx),
              child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                  style: const TextStyle(color: Colors.white54))),
          ElevatedButton(
              onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
              child: Text(context.read<MindMapProvider>().t('btn.add'))),
        ],
      ),
    );
    if (name != null && name.isNotEmpty) {
      final f = provider.addFlashcardFolder(name);
      setState(() => _folderId = f.id);
    }
  }

  Future<void> _folderMenu(MindMapProvider provider, String folderId) async {
    final v = await showDialog<String>(
      context: context,
      builder: (dctx) => SimpleDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(context.read<MindMapProvider>().t('folder.title'),
            style: TextStyle(color: Colors.white, fontSize: 15)),
        children: [
          SimpleDialogOption(
              onPressed: () => Navigator.pop(dctx, 'rename'),
              child: Text(context.read<MindMapProvider>().t('pmemo.rename'),
                  style: const TextStyle(color: Colors.white))),
          SimpleDialogOption(
              onPressed: () => Navigator.pop(dctx, 'delete'),
              child: Text(
                  context.read<MindMapProvider>().t('flash.deleteFolderCards'),
                  style: TextStyle(color: Color(0xFFFF6B6B)))),
        ],
      ),
    );
    if (v == 'rename') {
      final f = provider.flashcardFolders.firstWhere((x) => x.id == folderId,
          orElse: () => FlashcardFolder(id: ''));
      final ctrl = TextEditingController(text: f.name);
      final name = await showDialog<String>(
        context: context,
        builder: (dctx) => AlertDialog(
          backgroundColor: const Color(0xFF1E1E32),
          title: Text(context.read<MindMapProvider>().t('pmemo.rename'),
              style: TextStyle(color: Colors.white, fontSize: 16)),
          content: TextField(
              controller: ctrl,
              autofocus: true,
              style: const TextStyle(color: Colors.white)),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(dctx),
                child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                    style: TextStyle(color: Colors.white54))),
            ElevatedButton(
                onPressed: () => Navigator.pop(dctx, ctrl.text.trim()),
                child: Text(context.read<MindMapProvider>().t('btn.save'))),
          ],
        ),
      );
      if (name != null && name.isNotEmpty) {
        provider.renameFlashcardFolder(folderId, name);
      }
    } else if (v == 'delete') {
      provider.deleteFlashcardFolder(folderId);
      if (_folderId == folderId) setState(() => _folderId = _allId);
    }
  }

  Future<void> _moveCard(MindMapProvider provider, Flashcard c) async {
    final v = await showDialog<String?>(
      context: context,
      builder: (dctx) => SimpleDialog(
        backgroundColor: const Color(0xFF1E1E32),
        title: Text(context.read<MindMapProvider>().t('flash.moveToFolder'),
            style: TextStyle(color: Colors.white, fontSize: 15)),
        children: [
          SimpleDialogOption(
              onPressed: () => Navigator.pop(dctx, '__none__'),
              child: Text(
                  context.read<MindMapProvider>().t('pmemo.uncategorized'),
                  style: const TextStyle(color: Colors.white))),
          for (final f in provider.flashcardFolders)
            SimpleDialogOption(
                onPressed: () => Navigator.pop(dctx, f.id),
                child: Text(f.name.isEmpty ? '(無題)' : f.name,
                    style: const TextStyle(color: Colors.white))),
        ],
      ),
    );
    if (v != null) {
      provider.moveFlashcardToFolder(c.id, v == '__none__' ? null : v);
    }
  }
}

/// カードの作成 / 編集 (表 + AI で裏面生成 + 裏)。
class _FlashcardEditDialog extends StatefulWidget {
  final Flashcard? card;
  final String? defaultFolderId;
  const _FlashcardEditDialog({this.card, this.defaultFolderId});
  @override
  State<_FlashcardEditDialog> createState() => _FlashcardEditDialogState();
}

class _FlashcardEditDialogState extends State<_FlashcardEditDialog> {
  late final TextEditingController _front;
  late final TextEditingController _back;
  bool _generating = false;

  @override
  void initState() {
    super.initState();
    _front = TextEditingController(text: widget.card?.front ?? '');
    _back = TextEditingController(text: widget.card?.back ?? '');
  }

  @override
  void dispose() {
    _front.dispose();
    _back.dispose();
    super.dispose();
  }

  Future<void> _genBack() async {
    final provider = context.read<MindMapProvider>();
    final q = _front.text.trim();
    if (q.isEmpty) return;
    setState(() => _generating = true);
    final ans = await provider.generateFlashcardBack(q);
    if (!mounted) return;
    setState(() {
      _generating = false;
      if (ans.isNotEmpty) _back.text = ans;
    });
    if (ans.isEmpty && mounted) {
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(SnackBar(
          content:
              Text(context.read<MindMapProvider>().t('flash.aiGenFailed'))));
    }
  }

  @override
  Widget build(BuildContext context) {
    final provider = context.read<MindMapProvider>();
    return AlertDialog(
      backgroundColor: const Color(0xFF1E1E32),
      title: Text(widget.card == null ? 'カードを追加' : 'カードを編集',
          style: const TextStyle(color: Colors.white, fontSize: 16)),
      content: SizedBox(
        width: 460,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(context.read<MindMapProvider>().t('flash.frontQ'),
                style: TextStyle(color: Colors.white54, fontSize: 12)),
            TextField(
              controller: _front,
              autofocus: true,
              minLines: 1,
              maxLines: 4,
              style: const TextStyle(color: Colors.white),
              decoration: InputDecoration(
                  hintText: context.read<MindMapProvider>().t('flash.termHint'),
                  hintStyle: const TextStyle(color: Colors.white38)),
            ),
            const SizedBox(height: 12),
            Row(children: [
              Text(context.read<MindMapProvider>().t('flash.backA'),
                  style: TextStyle(color: Colors.white54, fontSize: 12)),
              const Spacer(),
              TextButton.icon(
                onPressed: _generating ? null : _genBack,
                icon: _generating
                    ? const SizedBox(
                        width: 14,
                        height: 14,
                        child: CircularProgressIndicator(strokeWidth: 2))
                    : const Icon(Icons.auto_awesome_rounded,
                        color: Color(0xFF26C6DA), size: 16),
                label: Text(
                    context.read<MindMapProvider>().t('flash.genAnswer'),
                    style: TextStyle(color: Color(0xFF26C6DA), fontSize: 12)),
              ),
            ]),
            TextField(
              controller: _back,
              minLines: 1,
              maxLines: 6,
              style: const TextStyle(color: Colors.white),
              decoration: InputDecoration(
                  hintText:
                      context.read<MindMapProvider>().t('flash.answerHint'),
                  hintStyle: const TextStyle(color: Colors.white38)),
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
            onPressed: () => Navigator.pop(context),
            child: Text(context.read<MindMapProvider>().t('btn.cancel'),
                style: const TextStyle(color: Colors.white54))),
        ElevatedButton(
          style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFF26C6DA),
              foregroundColor: Colors.black87),
          onPressed: () {
            final f = _front.text.trim();
            final b = _back.text.trim();
            if (f.isEmpty) return;
            if (widget.card == null) {
              provider.addFlashcard(
                  front: f, back: b, folderId: widget.defaultFolderId);
            } else {
              provider.updateFlashcard(widget.card!.id, front: f, back: b);
            }
            Navigator.pop(context);
          },
          child: Text(context.read<MindMapProvider>().t('btn.save')),
        ),
      ],
    );
  }
}

/// カードの学習 / 回答 (表 → 答えを見る or 回答を AI 採点)。
class _FlashcardStudyDialog extends StatefulWidget {
  final List<Flashcard> cards;
  final int start;
  const _FlashcardStudyDialog({required this.cards, this.start = 0});
  @override
  State<_FlashcardStudyDialog> createState() => _FlashcardStudyDialogState();
}

class _FlashcardStudyDialogState extends State<_FlashcardStudyDialog> {
  late int _i;
  bool _revealed = false;
  final TextEditingController _answer = TextEditingController();
  bool _judging = false;
  bool? _correct;
  String _explanation = '';
  // ── 音声入力 (= ユーザー要望: フラッシュカードの回答を音声でも入力) ──
  final stt.SpeechToText _speech = stt.SpeechToText();
  bool _speechInit = false;
  bool _listening = false;
  // ── 左右キーで前/次のカードへ (= ユーザー要望) ──
  //   回答欄にフォーカスがある間は EditableText がカーソル移動で矢印を消費する
  //   ため、 このルート Focus へは届かず誤作動しない。 採点後などはルートへ
  //   フォーカスを戻して矢印でめくれるようにする。
  final FocusNode _rootFocus = FocusNode();

  @override
  void initState() {
    super.initState();
    _i = widget.start.clamp(0, widget.cards.length - 1);
  }

  @override
  void dispose() {
    try {
      _speech.cancel();
    } catch (_) {}
    _answer.dispose();
    _rootFocus.dispose();
    super.dispose();
  }

  KeyEventResult _onStudyKey(FocusNode node, KeyEvent event) {
    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
      return KeyEventResult.ignored;
    }
    final k = event.logicalKey;
    if (k == LogicalKeyboardKey.arrowRight) {
      _next();
      return KeyEventResult.handled;
    }
    if (k == LogicalKeyboardKey.arrowLeft) {
      _prev();
      return KeyEventResult.handled;
    }
    return KeyEventResult.ignored;
  }

  void _prev() {
    if (_i > 0) {
      setState(() {
        _i--;
        _reset();
      });
    }
    _rootFocus.requestFocus();
  }

  void _reset() {
    _revealed = false;
    _answer.clear();
    _correct = null;
    _explanation = '';
    _judging = false;
  }

  /// 回答欄の音声入力をトグルする (= ユーザー要望)。 認識結果を _answer に流す。
  Future<void> _toggleVoiceAnswer() async {
    if (_listening) {
      try {
        await _speech.stop();
      } catch (_) {}
      if (mounted) setState(() => _listening = false);
      return;
    }
    if (!_speechInit) {
      try {
        if (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) {
          var mic = await Permission.microphone.status;
          if (!mic.isGranted) mic = await Permission.microphone.request();
          if (!mic.isGranted) return;
        }
        _speechInit = await _speech.initialize(onStatus: (s) {
          if (!mounted) return;
          if (s == 'done' || s == 'notListening') {
            setState(() => _listening = false);
          }
        });
      } catch (_) {
        _speechInit = false;
      }
    }
    if (!_speechInit || !mounted) return;
    final provider = context.read<MindMapProvider>();
    final base = _answer.text.trim();
    setState(() => _listening = true);
    try {
      await _speech.listen(
        localeId: provider.speechLocaleId,
        onResult: (r) {
          if (!mounted) return;
          final words = r.recognizedWords;
          _answer.text = base.isEmpty ? words : '$base $words';
          _answer.selection =
              TextSelection.collapsed(offset: _answer.text.length);
        },
      );
    } catch (_) {
      if (mounted) setState(() => _listening = false);
    }
  }

  void _next() {
    if (_i < widget.cards.length - 1) {
      setState(() {
        _i++;
        _reset();
      });
      _rootFocus.requestFocus();
    } else {
      Navigator.pop(context);
    }
  }

  Future<void> _judge() async {
    final provider = context.read<MindMapProvider>();
    final ua = _answer.text.trim();
    if (ua.isEmpty) return;
    final c = widget.cards[_i];
    // ── 解答 (裏) と同じ入力なら AI を呼ばずに即「正解」 (= ユーザー要望) ──
    // 大文字小文字・前後/連続空白の違いは無視して比較する。
    String norm(String s) =>
        s.trim().toLowerCase().replaceAll(RegExp(r'\s+'), ' ');
    if (norm(ua) == norm(c.back)) {
      setState(() {
        _revealed = true;
        _correct = true;
        _explanation = '';
      });
      _rootFocus.requestFocus(); // 採点後は矢印でめくれるようにする
      return;
    }
    setState(() => _judging = true);
    final r = await provider.judgeFlashcardAnswer(c.front, c.back, ua);
    if (!mounted) return;
    setState(() {
      _judging = false;
      _revealed = true;
      _correct = r.correct;
      _explanation = r.explanation;
    });
    _rootFocus.requestFocus(); // 採点後は矢印でめくれるようにする
  }

  @override
  Widget build(BuildContext context) {
    final c = widget.cards[_i];
    // モバイルは専用の全画面表示 (背景のオブジェクトが見えず集中できる) =
    //   ユーザー要望。 デスクトップは従来の中央ダイアログ。
    final isMobile = MediaQuery.of(context).size.width < 600;
    final largeDesktopLayout = MediaQuery.sizeOf(context).width >= 800;
    return Focus(
      focusNode: _rootFocus,
      autofocus: true,
      onKeyEvent: _onStudyKey,
      child: Dialog(
        backgroundColor: const Color(0xFF1A1A2E),
        insetPadding: isMobile ? EdgeInsets.zero : const EdgeInsets.all(24),
        shape: isMobile
            ? const RoundedRectangleBorder(borderRadius: BorderRadius.zero)
            : RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        child: SafeArea(
          child: SizedBox(
            width: isMobile
                ? double.infinity
                : largeDesktopLayout
                    ? 720
                    : 520,
            // モバイルは高さも画面いっぱいにして真の全画面にする (= ユーザー要望:
            //   集中の為の専用画面。 従来は内容分の高さで上下にキャンバスが見えた)。
            height: isMobile ? double.infinity : null,
            child: SingleChildScrollView(
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 12, 8, 4),
                  child: Row(children: [
                    Text('${_i + 1} / ${widget.cards.length}',
                        style: const TextStyle(
                            color: Colors.white54, fontSize: 12)),
                    const Spacer(),
                    IconButton(
                        onPressed: () => Navigator.pop(context),
                        icon: const Icon(Icons.close, color: Colors.white70)),
                  ]),
                ),
                Container(
                  width: double.infinity,
                  margin: EdgeInsets.symmetric(
                      horizontal: largeDesktopLayout ? 24 : 16),
                  padding: EdgeInsets.all(largeDesktopLayout ? 32 : 20),
                  decoration: BoxDecoration(
                      color: const Color(0xFF24243A),
                      borderRadius: BorderRadius.circular(12)),
                  child: Column(children: [
                    Text(context.read<MindMapProvider>().t('flash.front'),
                        style: TextStyle(
                            color: Colors.white38,
                            fontSize: largeDesktopLayout ? 12 : 11)),
                    SizedBox(height: largeDesktopLayout ? 10 : 6),
                    _RichMathText(c.front.isEmpty ? '(空)' : c.front,
                        color: Colors.white,
                        fontSize: largeDesktopLayout ? 24 : 18,
                        fontWeight: FontWeight.w600,
                        textAlign: TextAlign.center),
                  ]),
                ),
                if (_revealed)
                  Container(
                    width: double.infinity,
                    margin: EdgeInsets.fromLTRB(largeDesktopLayout ? 24 : 16,
                        10, largeDesktopLayout ? 24 : 16, 0),
                    padding: EdgeInsets.all(largeDesktopLayout ? 24 : 16),
                    decoration: BoxDecoration(
                        color: const Color(0xFF1B3A2E),
                        borderRadius: BorderRadius.circular(12)),
                    child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(context.read<MindMapProvider>().t('flash.backA'),
                              style: TextStyle(
                                  color: Colors.white38,
                                  fontSize: largeDesktopLayout ? 12 : 11)),
                          const SizedBox(height: 4),
                          _RichMathText(c.back.isEmpty ? '(未設定)' : c.back,
                              color: Colors.white,
                              fontSize: largeDesktopLayout ? 18 : 14,
                              textAlign: TextAlign.left),
                          if (_correct != null) ...[
                            const Divider(color: Colors.white12, height: 18),
                            Row(children: [
                              Icon(
                                  _correct! ? Icons.check_circle : Icons.cancel,
                                  color: _correct!
                                      ? const Color(0xFF43B97F)
                                      : const Color(0xFFFF6B6B),
                                  size: 18),
                              const SizedBox(width: 6),
                              Text(_correct! ? '正解' : '不正解',
                                  style: TextStyle(
                                      color: _correct!
                                          ? const Color(0xFF43B97F)
                                          : const Color(0xFFFF6B6B),
                                      fontWeight: FontWeight.w700)),
                            ]),
                            if (_explanation.isNotEmpty) ...[
                              const SizedBox(height: 4),
                              Text(_explanation,
                                  style: const TextStyle(
                                      color: Colors.white70, fontSize: 13)),
                            ],
                          ],
                        ]),
                  ),
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
                  child: Row(children: [
                    Expanded(
                      child: TextField(
                        controller: _answer,
                        style: const TextStyle(color: Colors.white),
                        decoration: InputDecoration(
                            hintText: context
                                .read<MindMapProvider>()
                                .t('flash.answerInput'),
                            hintStyle: const TextStyle(color: Colors.white38),
                            isDense: true),
                        onSubmitted: (_) => _judge(),
                      ),
                    ),
                    // ── 音声入力ボタン (= ユーザー要望: 回答を音声でも) ──
                    IconButton(
                      icon: Icon(
                          _listening ? Icons.mic : Icons.mic_none_rounded,
                          color: _listening
                              ? const Color(0xFFFF6B6B)
                              : Colors.white70),
                      tooltip: _listening ? '停止' : '音声で回答',
                      padding: EdgeInsets.zero,
                      constraints:
                          const BoxConstraints(minWidth: 36, minHeight: 36),
                      onPressed: _toggleVoiceAnswer,
                    ),
                    const SizedBox(width: 8),
                    ElevatedButton(
                      style: ElevatedButton.styleFrom(
                          backgroundColor: const Color(0xFF26C6DA),
                          foregroundColor: Colors.black87),
                      onPressed: _judging ? null : _judge,
                      child: _judging
                          ? const SizedBox(
                              width: 16,
                              height: 16,
                              child: CircularProgressIndicator(strokeWidth: 2))
                          : Text(
                              context.read<MindMapProvider>().t('flash.grade')),
                    ),
                  ]),
                ),
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 4, 16, 14),
                  // ── 前へ / (答えを見る) / 次へ を中央寄せ (= ユーザー要望:
                  //    前/次ボタンが左右端で離れすぎて押しにくいので中央へ) ──
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      TextButton(
                          onPressed: _i > 0 ? _prev : null,
                          child: Text(
                              context.read<MindMapProvider>().t('search.prev'),
                              style: TextStyle(color: Colors.white54))),
                      if (!_revealed) ...[
                        const SizedBox(width: 8),
                        TextButton.icon(
                          onPressed: () {
                            setState(() => _revealed = true);
                            _rootFocus.requestFocus();
                          },
                          icon: const Icon(Icons.visibility_rounded,
                              color: Color(0xFF4FC3F7), size: 18),
                          label: Text(
                              context
                                  .read<MindMapProvider>()
                                  .t('flash.showAnswer'),
                              style: TextStyle(color: Color(0xFF4FC3F7))),
                        ),
                        const SizedBox(width: 8),
                      ] else
                        const SizedBox(width: 24),
                      TextButton(
                          onPressed: _next,
                          child: Text(
                              _i < widget.cards.length - 1 ? '次へ' : '終了',
                              style:
                                  const TextStyle(color: Color(0xFF43B97F)))),
                    ],
                  ),
                ),
              ]),
            ),
          ),
        ),
      ),
    );
  }
}